INSERT INTO texts VALUES(10000025,'欧西里斯之天空龙',replace(replace('通常召唤此卡的情况下，必须解放3只来召唤。\r\n①：此卡的召唤不会被无效化。\r\n②：此卡召唤成功时，双方不可发动卡的效果。\r\n③：此卡的攻击力・守备力上升自己手牌数量×1000的数值。\r\n④：每当有怪兽以攻击表示被召唤・特殊召唤至对手场上则发动。该怪兽的攻击力下降2000。变为0的情况下将该怪兽破坏。\r\n⑤：此卡是被特殊召唤的情况下，在结束阶段发动。将此卡送至墓地。','\r',char(13)),'\n',char(10)),'送至墓地','攻击下降','把3只解放作召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10000080,'拉之翼神龙－球体形',replace(replace('此卡不可特殊召唤。\r\n通常召唤此卡的情况下，必须从自己・对手其中一方的场上解放３只怪兽并召唤至该玩家的场上，召唤的此卡其控制权将在下个回合的结束阶段还给原本的持有者。\r\n①：此卡不可攻击，对手怪兽不可将此卡作为攻击对象，对手不可将此卡作为效果的对象。\r\n②：解放此卡可以发动。从手牌・牌组将１只“拉之翼神龙”无视召唤条件，将其攻击力・守备力改成４０００并特殊召唤。','\r',char(13)),'\n',char(10)),'在自己场上召唤','在对手场上召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10000090,'拉之翼神龙－不死鸟',replace(replace('此卡不可通常召唤，仅可以此卡的效果特殊召唤。\r\n①：此卡存在于墓地的状态下，有“拉之翼神龙”从场上被送至自己墓地的情况下发动（应对此发动不可发动效果）。将此卡特殊召唤。\r\n②：此卡不受其他卡的效果影响。\r\n③：支付1000LP可以发动。将场上的1只怪兽送至墓地。\r\n④：在结束阶段发动。将此卡送至墓地，从自己手牌・牌组・墓地将1只“拉之翼神龙－球体形”无视召唤条件特殊召唤。','\r',char(13)),'\n',char(10)),'此卡特殊召唤','选场上1只怪兽送至墓地','把1只「拉之翼神龙－球体形」特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10002346,'硬梆梆岩铁',replace(replace('等级2怪兽×2\r\n①：只要此卡存在于怪兽区域，自己场上的怪兽的攻击力・守备力上升此卡的超量素材数量×200的数值。\r\n②：此卡将被破坏的情况下，作为代替可去除此卡的1个超量素材。','\r',char(13)),'\n',char(10)),'是否使用「硬梆梆岩铁」的效果代替破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10004783,'宝玉的解放',replace(replace('仅限装备“宝玉兽”怪兽。\r\n①：装备怪兽的攻击力上升８００。\r\n②：此卡从场上被送入墓地时可发动。从牌组将１只“宝玉兽”怪兽视作永续魔法卡以表侧表示放置在我方的魔法与陷阱区域。','\r',char(13)),'\n',char(10)),'放置「宝玉兽」在魔法陷阱区','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10012614,'勇气的旗印','①：只要此卡存在于魔法与陷阱区域，我方场上怪兽的攻击力在我方战斗阶段期间上升２００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10019086,'铁兽式强袭机动兵装改“BucephalusⅡ”',replace(replace('兽族・兽战士族・鸟兽族怪兽３只以上\r\n自己墓地的“铁兽”魔法・陷阱卡为２张以下的情况下，此卡不可从额外牌组特殊召唤。此卡名的③效果１回合仅可使用１次。①：自己特殊召唤怪兽成功时，对手不可发动效果。②：怪兽的攻击宣言时可以发动。将此卡及对手场上的卡全部除外。③：此卡被送至墓地的情况下可以发动。从额外牌组将１只兽族・兽战士族・鸟兽族怪兽送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10024317,'混炼装・汞巫',replace(replace('←1 【灵摆】 1→\r\n①：１回合１次，以自己场上此卡以外的１张表侧表示卡为对象可以发动。将该卡破坏，从牌组挑选１张“炼装”魔法・陷阱卡放置在自己场上。\r\n【怪兽效果】\r\n此卡名的怪兽效果１回合仅可使用１次。\n①：场上的此卡因战斗・效果被破坏的情况下可以发动。从自己的额外牌组将“混炼装・汞巫”以外的１只表侧表示的“炼装”灵摆怪兽加入手牌。此回合，自己不可在灵摆区域发动以此效果加入手牌的卡及其同名卡。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10026986,'异虫王','此卡可释放放１只冠有“异虫”之名的爬虫类族怪兽，并以攻击表示上级召唤。此外，可释放我方场上１只冠有“异虫”之名的爬虫类族怪兽并发动。选择对手场上的１张卡牌并破坏。','用1只怪兽解放上级召唤','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10028593,'轮回天狗','①：表侧表示的此卡从场上离开的情况下发动。从牌组将１只“轮回天狗”特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10032958,'神龙－卓越光',replace(replace('此卡召唤时，我方墓地每存在１只“神龙－卓越光”，获得以下的１个效果。但是，不可重复获得相同效果。\r\n●此卡的攻击力上升１０００点\r\n●此卡因战斗破坏对手怪兽的场合，仅可再继续攻击１次。\r\n●此卡因战斗破坏怪兽并送入墓地时，给予对手生命相当于被破坏怪兽的攻击力的伤害。','\r',char(13)),'\n',char(10)),'得到效果','攻击力上升1000','战斗破坏对手怪兽的情况下，只有1次可以再度攻击','战斗破坏怪兽送至墓地时，给予对手基本分破坏怪兽的攻击力数值的伤害','','','','','','','','','','','','');
INSERT INTO texts VALUES(10035717,'武器交换','１回合１次，可在我方准备阶段时支付７００LP发动。选择我方场上的１只战士族、机械族怪兽，直至下一次对手回合结束时，只要此卡存在于场上，相互交换其攻击力和守备力。','攻守交换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10040267,'新生代化石机械 骷髅越野车',replace(replace('自己墓地的岩石族怪兽＋等级４以下的怪兽\r\n此卡仅可通过“化石融合”的效果从额外牌组中特殊召唤。\r\n此卡名的②效果１回合仅可使用１次。\r\n①：此卡战斗破坏对手怪兽时可以发动。给予对手６００点伤害。\r\n②：将墓地的此卡除外可以发动。从牌组中将１只记载有“化石融合”卡名的怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10045474,'无限泡影',replace(replace('自己场上不存在卡的情况下，此卡也可从手牌发动。\r\n①：以对手场上的1只表侧表示怪兽为对象可以发动。将该怪兽的效果直至回合结束时为止无效。将被放置的此卡发动的情况下，进而在此回合中，将和此卡同一纵列的其他魔法・陷阱卡的效果无效化。','\r',char(13)),'\n',char(10)),'适用「无限泡影」的效果来发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10045475,'无限泡影',replace(replace('自己场上不存在卡的情况下，此卡也可从手牌发动。\r\n①：以对手场上的1只表侧表示怪兽为对象可以发动。将该怪兽的效果直至回合结束时为止无效。将被放置的此卡发动的情况下，进而在此回合中，将和此卡同一纵列的其他魔法・陷阱卡的效果无效化。','\r',char(13)),'\n',char(10)),'适用「无限泡影」的效果来发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10060427,'核成城主','此卡控制者每次我方的结束阶段，从手牌将１张“核成之钢核”送入墓地，或向对手展示１只手牌的战士族怪兽。或者不执行上述两项破坏此卡。此卡可释放１只冠有“核成”之名的怪兽并上级召唤。此卡召唤成功时，可将我方墓地的１张冠有“核成”之名的卡牌从游戏中除外并发动。选择对手场上最多２张卡牌破坏。','选择一张「核成之钢核」送至墓地','选择一张战士族怪兽给对手观看','破坏「核成城主」','把1只「核成」怪兽解放作上级召唤','破坏','','','','','','','','','','','');
INSERT INTO texts VALUES(10065487,'烙印丧失','此卡名的卡１回合仅可发动１张。①：以自己场上的１只融合怪兽和对手场上的１只被从额外牌组特殊召唤的怪兽为对象可以发动。将该怪兽放回持有者的牌组。在此回合的结束阶段，双方可各从自身的额外牌组将１只需以“阿尔白斯之落胤”作为融合素材的融合怪兽特殊召唤。','回到牌组','是否特殊召唤以「阿尔白斯之落胤」为融合素材的融合怪兽？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10069180,'魔力终了宣告','对手发动永续魔法卡时可发动。使该发动无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10071151,'暮光道巫师 莱拉',replace(replace('①：１回合１次，魔法、陷阱卡效果发动时，可从我方手牌、墓地将１只“光道”怪兽除外，并以场上的１张表侧表示魔法、陷阱卡为对象发动。破坏该卡。\r\n②：１回合１次，除此卡以外的我方“光道”怪兽效果发动的场合发动。从我方牌组上方将３张卡牌送入墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10071456,'王座保卫者','王不在的期间，守卫王座不受外敌侵害的王妃。守备很强。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10080320,'侏罗纪世界','场上表侧表示的恐龙族怪兽的攻击力和守备力上升３００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10097168,'虎龙','释放龙族怪兽并上级召唤此卡成功时，最多可选择２张被覆盖在对手魔法与陷阱区域的卡牌并破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10110717,'机械兔','此卡因战斗被破坏并送至墓地时可以发动。从牌组以里侧守备表示特殊召唤１只“机械兔”。此卡反转时，从场上选择１张卡片，并给予该控制者５００点伤害。','特殊召唤','伤害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10113611,'电力黄鳍金枪鱼',replace(replace('此卡名的①③效果１回合仅可各使用１次。\r\n①：自己的怪兽给予了对手战斗伤害的伤害步骤结束时可以发动。从手牌将此卡特殊召唤。\r\n②：此卡可直接攻击。\r\n③：此卡以直接攻击给予对手战斗伤害时可以发动。解放此卡、和自己手牌・场上（表侧表示）１只以上协调以外的怪兽，从额外牌组将等级与所解放怪兽的合计等级相同的１只“电力”同步怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10117149,'文具博格００５',replace(replace('←10 【灵摆】 10→\r\n①：自己仅可灵摆召唤“文具博格”怪兽。此效果不会被无效化。\r\n【怪兽效果】\r\n此卡名的③怪兽效果１回合仅可使用１次。①：此卡召唤・特殊召唤成功的情况下，以场上１张魔法・陷阱卡为对象可以发动。将该卡破坏。②：此卡的攻击力上升相当于自己额外牌组表侧表示“文具博格”怪兽数量×５００的数值。③：此卡在灵摆区域被破坏的情况下，以自己墓地的１只“文具博格”怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10118318,'休战增援','发动此卡的回合中，自己无法进行战斗阶段。①：从牌组将１只等级２以下的战士族怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10125011,'星圣的守星骑士团',replace(replace('此卡名的卡1回合仅可发动1张，此卡名的②效果1回合仅可使用1次。\r\n①：作为此卡发动时的效果处理，可从自己手牌・墓地将1只“星骑士”、“星圣”怪兽特殊召唤。\r\n②：以自己场上的1只“星骑士”、“星圣”超量怪兽为对象可以发动。从额外牌组将1只阶级与该自己的怪兽不同的“星骑士”、“星圣”超量怪兽重叠在对象怪兽上面，视为超量召唤特殊召唤。','\r',char(13)),'\n',char(10)),'是否选怪兽特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10131855,'暗黑界的洗脑','①：自己手牌存在3张以上，且对手发动怪兽的效果时，以场上的1只“暗黑界”怪兽为对象可以发动。将对象怪兽放回手牌，该对手的效果变为“随机舍弃对手的1张手牌”。','发动但不使用效果','改变对手效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10132124,'翼龟','我方场上表侧表示的鱼族、海龙族、水族怪兽从游戏中被除外时，可从手牌或墓地特殊召唤此卡。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10136446,'黄昏的堕天使 路西法',replace(replace('等级6以上的天使族・暗属性怪兽×2\r\n此卡名的①③效果1回合仅可各使用1次。\r\n①：此卡融合召唤的情况下可以发动。从牌组将1张“堕天使”魔法卡和1张“堕天使”陷阱卡放置在自己场上。\r\n②：对手不可将场上的此卡作为效果的对象。\r\n③：在自己・对手回合中，支付1000LP，以自己墓地的1张“堕天使”魔法・陷阱卡为对象可以发动。适用该魔法・陷阱卡发动时的效果。然后，将该卡放回牌组。','\r',char(13)),'\n',char(10)),'放置','复制效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10140443,'转生炎兽 爆裂狮鹫',replace(replace('协调＋协调以外的怪兽１只以上\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：以自己墓地的１只等级７以下的炎属性怪兽为对象可以发动。将该怪兽特殊召唤，此卡的等级下降相当于该怪兽原本等级的数值。此回合，自己仅可特殊召唤炎属性怪兽。\r\n②：此卡以“转生炎兽 爆裂狮鹫”作为素材同步召唤的情况下可以发动。在下个准备阶段从自己的墓地将１只怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10158145,'梦魇曲 崩界之伊布丽丝','此卡名的③效果1回合仅可使用1次。①：此卡召唤成功时，以自己墓地的1只连接怪兽为对象可以发动。将该怪兽的攻击力改成0，效果无效，并特殊召唤至自己场上使其和此卡呈连接状态。②：只要此卡存在于怪兽区域，此卡的控制者仅可特殊召唤连接怪兽。③：此卡从自己场上被送至墓地的情况下可以发动。将此卡以守备表示特殊召唤至对手场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10163855,'贝壳骑士',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：此卡召唤成功时可以发动。将此卡变为守备表示，并给予对手５００点伤害。\r\n②：此卡因效果被送至墓地的情况下，或因战斗被破坏的情况下可以发动。从牌组中将１只岩石族・等级８怪兽加入手牌。自己的墓地有“化石融合”存在的情况下，也可不加入手牌并特殊召唤。此回合，自己不可发动该卡及该同名卡的效果。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10178757,'真次代机・预言机',replace(replace('以此卡作为同步素材的情况下，仅可用于“次代机”怪兽的同步召唤。\r\n①：此卡以“次代机”怪兽的效果从自己的牌组加入手牌的情况下可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10182251,'抒情歌鸲－绿柱金丝雀',replace(replace('此卡名的①效果1回合仅可使用1次。①：在此卡存在于手牌中的情况下，以自己墓地的1只“抒情歌鸲”怪兽为对象可以发动。将此卡与对象怪兽特殊召唤。此效果发动后，直至回合结束时为止自己从额外牌组仅可特殊召唤超量怪兽。②：以场上的此卡为素材超量召唤的风属性怪兽将获得以下效果。\r\n●此卡的攻击力上升200，不可变更控制权。','\r',char(13)),'\n',char(10)),'','「抒情歌鸲－绿柱金丝雀」效果适用中','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10186633,'EN洗牌','此卡名的①②效果１回合仅可各使用１次。①：挑选自己场上的１只“元素－英雄”怪兽或“新空间人”怪兽放回持有者的牌组，从牌组将１只卡名与该怪兽不同的“元素－英雄”怪兽或“新空间人”怪兽特殊召唤。②：将墓地的此卡除外可以发动。从自己的墓地挑选“元素－英雄”怪兽和“新空间人”怪兽各１只，或１只“元素－英雄 新宇侠”放回牌组。然后，自己从牌组抽１张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10189126,'假面魔道士','此卡给予对手生命战斗伤害时，从我方牌组抽取１张卡牌。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10194329,'急袭猛禽－复仇秃鹫','①：自己因战斗・效果受到伤害的情况下可以发动。从手牌将此卡特殊召唤。此效果发动后，直至回合结束时为止自己从额外牌组仅可特殊召唤“急袭猛禽”怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10202894,'天空猎手','会从空中撒下隐藏于羽翼中的利刃，进行攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10204849,'鲜花之花剑','此卡名的卡1回合仅可发动1张，此卡名的③效果1回合仅可使用1次。①：以自己墓地1只等级2以下的怪兽为对象可以发动此卡。将该怪兽的效果无效并特殊召唤，装备此卡。此卡从场上离开时该怪兽将被破坏。②：装备怪兽的攻击力上升700。③：此卡从魔法与陷阱区域被送至墓地的情况下可以发动。挑选自己场上的1只同步怪兽装备此卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10209545,'腐朽武将','成功召唤此卡时，可从手牌特殊召唤１只“僵尸虎”。此卡成功直接攻击对手玩家的场合，对手随机弃置１张手牌。','特殊召唤','手牌丢弃','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10218411,'二重融合','①：支付500LP可以发动。将自己手牌・场上的怪兽作为融合素材，将1只融合怪兽融合召唤。然后，可将自己手牌・场上的怪兽作为融合素材，将1只融合怪兽融合召唤。','发动','是否继续融合召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10236520,'忍者义贼 五卫五卫','对手手牌为５张或以上的场合，此卡给予对手生命战斗伤害时，随机挑选２张对手手牌并舍弃。','手牌丢弃','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10239627,'魔法诱导者',replace(replace('←3 【灵摆】 3→\r\n①：只要此卡存在于灵摆区域，每当自己或对手发动魔法卡，就在此卡上放1个魔力计数物。\n②：1回合1次，去除此卡的3个魔力计数物可以发动。从牌组将1只灵摆怪兽加入手牌。\r\n【怪兽效果】\r\n①：只要此卡存在于怪兽区域，每当自己或对手发动魔法卡，就在此卡上放1个魔力计数物。\n②：此卡的攻击力上升此卡魔力计数物的数量×100的数值。\n③：1回合1次，去除此卡的3个魔力计数物可以发动。从牌组将1只魔法师族・等级1怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10248192,'象形文字石板','支付１０００LP可以发动。该决斗中，我方的手牌限制张数变成７张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10248389,'电子冰刀滑雪手',replace(replace('“电子明星”＋“冰刀滑雪手”\r\n此卡的融合召唤仅限以上述卡牌进行。\r\n①：根据对手场上的怪兽数量，此卡获得以下效果。\r\n●１只：此卡不会因战斗而被破坏。\r\n●２只：此卡的攻击力加倍。\r\n●３只：对手发动的卡牌效果被无效化。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10262698,'复活岛的摩艾像','存在于复活岛的石像。会从口中吐出圆柱状激光。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10266279,'狱神影精－朱诺璐多',replace(replace('←1 【灵摆】 1→\r\n此卡名的灵摆效果1回合仅可使用1次。\n①：此卡存在于灵摆区域的状态下，有“狱神”怪兽或“耀圣”怪兽被特殊召唤至自己场上的情况下可以发动。将此卡破坏，自己抽2张。然后，挑选自己的1张手牌舍弃。\r\n【怪兽效果】\r\n此卡名在规则上也视为“耀圣”卡。\n此卡名的①②怪兽效果1回合仅可各使用1次。\n①：从牌组上面将3张卡以里侧除外可以发动。将此卡破坏，从额外牌组将1只“调狱神 朱诺拉”视为同步召唤特殊召唤。\n②：此卡以表侧加入额外牌组的情况下可以发动。从自己额外牌组（表侧）・墓地将除“狱神影精－朱诺璐多”以外的1张“狱神”卡或“耀圣”卡加入手牌。','\r',char(13)),'\n',char(10)),'抽牌效果','特殊召唤','检索效果','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10275411,'超量复仇','如果对手场上有拥有超量素材的超量怪兽，则可以选择我方墓地中的１只超量怪兽发动。特殊召唤所选怪兽，将对手场上的１个超量素材叠放在所选的怪兽之下，作为其超量素材。“超量复仇”１回合只能发动１张。','请选择要转移的素材','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10282757,'普朗克尺度',replace(replace('①：在此回合中适用以下效果。\r\n●双方场上的所有阶级３以下的超量怪兽的攻击力・守备力上升５００。\r\n●双方场上的所有阶级４以上的超量怪兽不可攻击。','\r',char(13)),'\n',char(10)),'阶级3以下的超量怪兽的攻击力·守备力上升500','阶级4以上的超量怪兽不可攻击','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10286023,'魔救奇石－龙石','此卡名的①②效果1回合仅可各使用1次。①：此卡用“魔救”卡的效果特殊召唤成功的情况下可以发动。自己从牌组抽1张。②：此卡存在于墓地的情况下，可以自己场上・墓地的1只水属性同步怪兽为对象发动。该怪兽放回持有者的额外牌组，此卡放回牌组最上面。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10300821,'混沌编号79 燃烧拳斗士 将星之指虎',replace(replace('等级５怪兽×３\r\n①：此卡的攻击力上升相当于此卡的超量素材的数量×２００的数值。\r\n②：１回合１次，对手将怪兽特殊召唤之际可以发动。去除此卡的２个超量素材，将其无效并破坏。\r\n③：此卡持有“编号79 燃烧拳斗士 新星之拳环”作为超量素材的情况下，获得以下效果。\r\n●１回合１次，自己的“燃烧拳斗士”怪兽与对手怪兽进行战斗的攻击宣言时可以发动。从手牌・牌组将１只“燃烧拳斗士”怪兽送至墓地，将该对手怪兽作为此卡的超量素材。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10307853,'护石庭园',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：只要自己的魔法与陷阱区域存在5张卡，双方受到的战斗伤害变为一半，1回合1次，自己可以将1张永续陷阱卡在放置的回合发动。\r\n②：在自己・对手的准备阶段可以发动。从牌组将卡名不同的5张永续陷阱卡出示给对手，对手从其中随机挑选1张。自己将该1张放置在自己场上，剩余的放回牌组。','\r',char(13)),'\n',char(10)),'适用「护石庭园」的效果来发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10312660,'未界域之盛情欢待','此卡名的卡1回合仅可发动1张。①：从牌组将3种“未界域”怪兽出示给对手，对手从其中随机挑选1只。将1只该怪兽特殊召唤至自己场上。剩余的怪兽放回牌组。以此效果特殊召唤的怪兽将在结束阶段被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10315429,'剪刀机器','方形的身体内部隐藏着无数刀刃，能切碎一切的机器。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10321588,'日光独角兽','１回合１次，可在我方的主要阶段时发动此卡。翻开我方牌组最上方的卡牌，是装备魔法卡的场合将其加入到手牌中，不是装备魔法卡的场合将其放回到我方牌组的最下方。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10333641,'超重武者 隐秘－３２','此卡名以①方法的特殊召唤１回合仅可进行１次，且②效果１回合仅可使用１次。①：自己墓地不存在魔法・陷阱卡的情况下，此卡可从手牌中特殊召唤。②：自己墓地不存在魔法・陷阱卡的情况下，解放此卡，以对手墓地的１张魔法・陷阱卡为对象可以发动。将该卡放置在自己场上。以此效果放置的卡从场上离开的情况下，将其除外。此效果在对手回合中也可以发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10352095,'幻惑之卷物','可以宣言１个属性并发动此卡。装备怪兽的属性变成宣言的属性。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10365322,'起爆兽火神加农炮',replace(replace('机械族怪兽＋炎族怪兽\r\n此卡融合召唤成功时，选择对手场上的１只怪兽可以发动。破坏被选择的对手怪兽与此卡。破坏２只的情况下，给予对手LP被破坏并被送至墓地的对手怪兽的原本攻击力数值的伤害。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10375182,'指令骑士','只要此卡以表侧表示存在于场上，我方场上表侧表示的战士族怪兽的攻击力就上升４００点。另外，我方场上有其他怪兽存在的场合，对手不可选择表侧表示的此卡作为攻击对象。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10383554,'魔玩具・轮锯狮',replace(replace('“锋利小鬼・锯”＋“绒毛动物”怪兽\r\n此卡仅可以通过融合召唤进行特殊召唤。\r\n“魔玩具・轮锯狮”的效果１回合仅可使用１次，发动此效果的回合，此卡不可进行直接攻击。\r\n①：以对手场上的１只表侧表示怪兽为对象可以发动。破坏该怪兽，并给予对手被破坏怪兽原本攻击力数值的伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10383555,'魔玩具・轮锯狮',replace(replace('“锋利小鬼・锯”＋“绒毛动物”怪兽\r\n此卡仅可以通过融合召唤进行特殊召唤。\r\n“魔玩具・轮锯狮”的效果１回合仅可使用１次，发动此效果的回合，此卡不可进行直接攻击。\r\n①：以对手场上的１只表侧表示怪兽为对象可以发动。破坏该怪兽，并给予对手被破坏怪兽原本攻击力数值的伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10389142,'编号42 星舰・银河战斧',replace(replace('等级7怪兽×2\r\n①：1回合1次，去除此卡的2个超量素材可以发动。将尽可能多的“战鹰衍生物”（机械族・风・星6・攻2000/守0）特殊召唤至自己场上。以此效果特殊召唤的衍生物将在此回合的结束阶段被破坏。此效果发动后，直至回合结束时为止，对手受到的战斗伤害变为0。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10389143,'战鹰衍生物','由“编号42 星舰 银河战斧机”的效果特殊召唤而来。此衍生物在其被特殊召唤的回合的结束阶段将被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10389794,'死亡甜甜圈','反转：破坏场上全部原本攻击力是０或原本守备力是０的怪兽。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10406322,'森罗守神 森精',replace(replace('等级8怪兽×2\r\n此卡名的②效果1回合仅可使用1次。\r\n①：1回合1次，宣言1个卡名可以发动。翻开自己牌组最上面的卡，是宣言卡的情况下，将该卡加入手牌。不是的情况下，将所翻开的卡送至墓地。\r\n②：自己牌组的卡因效果被送至墓地的情况下，去除此卡的1个超量素材，以场上的1张卡为对象可以发动。将该卡放回牌组最上面或最下面。','\r',char(13)),'\n',char(10)),'宣言卡名','返回牌组','返回牌组最上面','返回牌组最下面','','','','','','','','','','','','');
INSERT INTO texts VALUES(10424147,'超级量子机舰 惊天运输机',replace(replace('①：舍弃1张手牌，以自己场上的1只“超级量子士”怪兽为对象可以发动。从额外牌组将1只属性与该自己的怪兽相同的“超级量子机兽”超量怪兽重叠在对象怪兽上面，视为超量召唤特殊召唤。\r\n②：将场地区域的此卡送至墓地，以自己场上・墓地的3只“超级量子机兽”超量怪兽为对象可以发动（同名卡最多1张）。从额外牌组将1只“超级量子机神王 超凡惊天煌”特殊召唤，将对象怪兽和其超量素材全部作为该特殊召唤的怪兽的超量素材。','\r',char(13)),'\n',char(10)),'丢弃手牌','送至墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10426067,'堕天使 杰夫提',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将“堕天使 杰夫提”以外的1只“堕天使”怪兽以守备表示特殊召唤。此效果发动后，直至回合结束时为止自己仅可特殊召唤天使族怪兽。\r\n②：自己场上存在天使族・暗属性的融合怪兽的情况下，将墓地的此卡除外，以自己墓地的1张“堕天使”卡或“禁忌的”速攻魔法卡为对象可以发动。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10441498,'辉神鸟贝努',replace(replace('由“原初的叫唤”降临。\r\n①：１回合１次，可向对手展示手牌中的１只怪兽，以场上表侧表示的１只怪兽为对象并发动。此回合，对象怪兽的等级变成与被展示怪兽的相同。\r\n②：１回合１次，除此卡以外的我方手牌・场上的怪兽被解放的场合，可以我方墓地的１只怪兽为对象并发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'等级变换','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10443957,'电子龙无限',replace(replace('机械族・光属性等级6怪兽×3\r\n“电子龙无限”1回合1次，也可重叠在自己场上的“电子龙新星”上来超量召唤。\r\n①：此卡的攻击力上升此卡的超量素材数量×200的数值。\r\n②：1回合1次，以场上的1只表侧攻击表示的怪兽为对象可以发动。将该怪兽作为此卡的超量素材。\r\n③：1回合1次，魔法・陷阱・怪兽的效果发动时，去除此卡的1个超量素材可以发动。将该发动无效并破坏。','\r',char(13)),'\n',char(10)),'是否在「电子龙新星」上面重叠来超量召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10443958,'电子龙无限',replace(replace('机械族・光属性等级6怪兽×3\r\n“电子龙无限”1回合1次，也可重叠在自己场上的“电子龙新星”上来超量召唤。\r\n①：此卡的攻击力上升此卡的超量素材数量×200的数值。\r\n②：1回合1次，以场上的1只表侧攻击表示的怪兽为对象可以发动。将该怪兽作为此卡的超量素材。\r\n③：1回合1次，魔法・陷阱・怪兽的效果发动时，去除此卡的1个超量素材可以发动。将该发动无效并破坏。','\r',char(13)),'\n',char(10)),'是否在「电子龙新星」上面重叠来超量召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10456559,'恶魂邪苦止','①：自己场上的此卡因战斗被破坏并被送至墓地时可以发动。从牌组将任意数量的“恶魂邪苦止”加入手牌。','把「恶魂邪苦止」加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10474647,'五月豹',replace(replace('①：手牌仅有此１张卡的情况下可以发动。将此卡特殊召唤。\r\n②：以此卡的①效果特殊召唤的情况下发动。此卡的攻击力直至对手回合结束时为止变为２５００。\r\n③：此卡与对手怪兽进行战斗的情况下，因该战斗对对手造成的战斗伤害由自己代为承受。\r\n④：自己因此卡的战斗受到伤害的情况下发动。此卡的攻击力变为０。然后，自己的LP为２０００以下的情况下，此卡的攻击力变为５０００。','\r',char(13)),'\n',char(10)),'特殊召唤','改变攻击力','攻击力变成5000','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10476868,'机枪岩','一边用双肩的冲锋枪扫射一边用身体撞击敌人。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10485110,'海龙神－超代达罗斯',replace(replace('此卡不可通常召唤。\r\n仅可在解放自己场上的1只“海龙－代达罗斯”的情况下特殊召唤。\r\n①：将自己场上的1张表侧表示的“海”送至墓地可以发动。将此卡以外的、双方手牌・场上的卡全部送至墓地。','\r',char(13)),'\n',char(10)),'送墓','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10489311,'英雄徽章','被盖牌的此卡因对手效果被破坏并送入墓地时，将此卡加入牌组并洗牌。之后，从我方牌组抽取１张卡牌。','返回牌组并抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10493654,'-艾-眼神交流','此卡名的卡1回合仅可发动1张。①：自己的场地区域有“伊格尼斯者-艾-乐园岛”存在的情况下，将手牌的1张“伊格尼斯者-艾-乐园岛”出示给对手可以发动。将出示的卡放回牌组最下面，自己从牌组抽3张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10497636,'战吼・迈泰奥拉贡',replace(replace('①：此卡不会因对手效果被破坏。\r\n②：此卡与对手怪兽进行战斗的攻击宣言时可发动。此回合，该对手怪兽及原本卡牌名与该对手怪兽相同之怪兽的效果被无效化。\r\n③：１回合１次，在我方战士族、地属性怪兽进行了战斗之我方、对手的战斗阶段可发动。直至对手回合结束时，我方场上所有“战吼”怪兽的攻击力上升２００。此回合，此卡在１次的战斗阶段中可对怪兽进行最多２次攻击。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10505300,'悠悠燕','此卡名以①方法的特殊召唤１回合仅可进行１次。①：场上相同等级的怪兽有２只以上存在的情况下，此卡可从手牌中特殊召唤。②：解放此卡可以发动。下一个自己的抽牌阶段的通常抽牌变为２张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10509340,'古代机械齿轮兽',replace(replace('此卡不可特殊召唤。\r\n①：此卡攻击的场合，直至伤害步骤结束时，对手不可发动魔法、陷阱卡。\r\n②：此卡在战斗中破坏的对手怪兽的效果无效化。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10515412,'光明风暴龙',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡特殊召唤的情况下，以自己墓地的通常怪兽数量＋1张为上限，以场上的魔法・陷阱卡为对象可以发动。将该卡破坏。\r\n②：此卡因战斗・效果被破坏的情况下，以自己墓地的1张魔法・陷阱卡为对象可以发动。将该卡放置在自己场上。以此效果放置的卡，在自己场上不存在通常怪兽的情况下就不可发动。','\r',char(13)),'\n',char(10)),'破坏','放置','「光明风暴龙」效果适用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10526791,'元素－英雄 狂野锯刃人',replace(replace('“元素-英雄 狂野人”＋“元素-英雄 刀锋人”\r\n此卡仅可以融合召唤方式特殊召唤。①：此卡可攻击所有对手怪兽各1次。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10529441,'呜呼落穴','①：对手特殊召唤过怪兽的回合，对手场上的怪兽发动效果时可以发动。将发动该效果的怪兽破坏。然后，该怪兽存在的区域的前・后・相邻区域（怪兽区域・魔法与陷阱区域）有对手的卡存在的情况下，将其全部破坏。','发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10530913,'森罗的贤树 夏曼','冠有“森罗”之名的怪兽被送入墓地时，可从手牌特殊召唤此卡。１回合１次，在我方主要阶段时可发动。翻阅我方牌组最上方的卡牌。若翻阅的卡牌为植物族怪兽的场合，将该怪兽送入墓地。不是的场合，将该卡返回至牌组的最下方。此外，牌组的此卡因卡牌效果被翻阅并送入墓地的场合，可选择我方墓地１张冠有“森罗”之名的魔法、陷阱卡加入手牌。','特殊召唤','翻开牌组','加入手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10532969,'古代鲨 超巨齿鲨','此卡给予对手生命战斗伤害时，可选择对手场上的１只怪兽并发动。破坏被选择的对手怪兽。','怪兽破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10537981,'回魂','结束阶段时可发动。最多可将３只此回合被破坏的墓地怪兽返回至持有者牌组。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10538007,'狮子王','拥有百兽之王般气派的鬃毛。体型也很大。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10547580,'古代机械齿轮・弓弩手',replace(replace('机械族・地属性怪兽２只\r\n此卡名的①②效果１回合仅可各使用１次。①：此卡连接召唤成功的情况下可以发动。从牌组将１只“古代机械齿轮”怪兽或１张“齿轮镇”加入手牌。②：以自己场上的１张魔法・陷阱卡和对手场上的１只表侧表示怪兽为对象可以发动。将该自己的卡破坏，将该对手怪兽的攻击力・守备力直至回合结束时为止改成０。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10552026,'刚鬼 邪道食人魔',replace(replace('“刚鬼”怪兽2只\r\n①：1回合1次，此卡连接端的怪兽的效果发动时可以发动。将该发动无效并破坏。然后可从自己的墓地挑选1只“刚鬼 邪道食人魔”以外的“刚鬼”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','是否选「刚鬼」怪兽特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10560119,'鱼博格－诊疗者',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：自己场上存在“鱼博格”怪兽以外的怪兽的情况下，此卡将被破坏。\r\n②：此卡存在于墓地，且自己场上的怪兽仅有“鱼博格”怪兽的情况下可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10584050,'守宝团・爆破！','此卡名的卡１回合仅可发动１张。①：自己场上有“守宝团”怪兽存在的情况下，指定１处对手的主要怪兽区域可以发动。该区域有表侧表示怪兽存在的情况下，此回合，该怪兽不可直接攻击，效果无效化。该区域没有怪兽存在的情况下，此回合指定区域不可使用。自己场上有以“阿尔白斯之落胤”作为融合素材的融合怪兽存在的情况下，可将以此效果指定的区域改成２处。','是否再选择1个区域？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10591919,'变形斗士・显微镜',replace(replace('此卡依据此卡的表示形式获得以下效果。\r\n●攻击表示：１回合１次，可从手牌特殊召唤１只冠有“变形斗士”之名的等级４怪兽。以此效果特殊召唤的怪兽在结束阶段时被破坏。\r\n●守备表示：此卡的等级变成４。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10598400,'龙虾怪','龙虾进化成的怪兽。会用巨大的钳子取下对手的首级。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10602628,'黑羽－魔风之玻瑞阿斯',replace(replace('暗属性协调＋协调以外的怪兽1只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡同步召唤的情况下可以发动。从牌组将1只“黑羽”怪兽送至墓地。此卡的等级变为与该怪兽的等级相同。\r\n②：此卡战斗破坏怪兽并将其送至墓地时，从自己场上（表侧表示）・墓地将1只“黑羽”怪兽除外可以发动。将该被破坏的怪兽以守备表示特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10604644,'兽带斗士“王者”雷古拉斯',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：以自己墓地的1只“兽带斗士”怪兽或机械族怪兽为对象可以发动。从手牌将此卡特殊召唤，将对象怪兽视为装备魔法卡装备于此卡。\r\n②：对手发动效果时，从自己手牌・场上（表侧表示）将1张“兽带斗士”怪兽卡送至墓地可以发动。将该效果无效。\r\n③：装备此卡的“兽带斗士”怪兽的攻击力上升700，获得此卡名的②效果。','\r',char(13)),'\n',char(10)),'','对手效果无效（兽带斗士“王者”轩辕十四）','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10612222,'妖仙兽的居太刀风',replace(replace('此卡牌名的卡牌１回合只可发动１张。\r\n①：我方场上不存在有怪兽的场合，最多可从手牌向对手展示２只卡牌名不同的“妖仙兽”怪兽，并以对手场上的表侧表示卡牌为对象发动，其数量与向对手展示数量相同。将该卡牌返回至持有者手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10613952,'神圣骑士王阿托利斯',replace(replace('等级５“圣骑士”怪兽×２\r\n①：此卡超量召唤成功时，可以我方墓地最多３种“圣剑”装备魔法卡为对象发动。将对象卡牌装备此卡。\r\n②：１回合１次，可移除此卡的１个超量素材，并以场上除此卡以外的１只怪兽为对象发动。破坏该怪兽。\r\n③：此卡从场上被送入墓地的场合，可以我方墓地１只等级４或以上的“圣骑士”怪兽为对象发动。特殊召唤该怪兽。','\r',char(13)),'\n',char(10)),'装备','破坏','特殊召唤','是否要继续选择名字带有「圣剑」的装备魔法卡进行装备？','','','','','','','','','','','','');
INSERT INTO texts VALUES(10632284,'模仿象',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：此卡发动后，变为效果怪兽（兽族・地・星２・攻０／守２０００），特殊召唤至怪兽区域（也视为陷阱卡）。\r\n②：此卡存在于怪兽区域的情况下，在自己・对手的回合中，宣言种族和属性各１个，以场上的１只表侧表示怪兽为对象可以发动。该怪兽直至回合结束时为止，变为所宣言的种族・属性。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10642488,'V型蛇 T301',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：此卡存在于手牌・墓地，且自己的表侧表示怪兽与对手怪兽进行战斗的攻击宣言时可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。\r\n②：只要此卡存在于怪兽区域，自己场上其他的光属性・机械族怪兽的攻击力上升1200。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10651797,'燕返','特殊召唤成功时发动的怪兽效果发动时可发动。使该发动无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10666000,'编号1 感染蝇王',replace(replace('等级8怪兽×2只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡超量召唤的情况下可以发动。确认对手的额外牌组，将其中1张送至墓地。\r\n②：去除此卡的1个超量素材，以对手场上的1张卡为对象可以发动。将该卡破坏。以此效果破坏了表侧表示怪兽的情况下，进而给予对手相当于其攻击力一半数值的伤害。\r\n③：在自己的准备阶段可以发动。从对手墓地将1张卡作为此卡的超量素材。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10667321,'远古规则','从手牌特殊召唤１只等级５以上的通常怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10669138,'连接神龙',replace(replace('怪兽5只\r\n此卡仅可以连接召唤方式特殊召唤。\r\n①：此卡以暗・地・水・炎・风的全部属性作为素材连接召唤的情况下可以发动。将对手场上的卡全部破坏。\r\n②：场上的此卡不受其他卡的效果影响，不会因与暗・地・水・炎・风属性怪兽的战斗被破坏。\r\n③：在对手的结束阶段发动。从自己墓地将5张卡以里侧除外。无法除外5张的情况下，此卡将被送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10673071,'人工神灵 薇拉卡姆',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：自己场上或墓地存在“阿莱斯特”怪兽的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：此卡特殊召唤的情况下可以发动。从牌组将1张“召唤魔术”或记载有该卡名的魔法卡放置在自己场上。\r\n③：对手连锁自己的融合怪兽的效果的发动，来发动卡的效果时可以发动。将场上的此卡除外，将该对手的效果无效并除外。','\r',char(13)),'\n',char(10)),'特殊召唤','放置效果','效果无效','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10678778,'魔海城埃该翁',replace(replace('等级８怪兽×２\r\n“魔海城埃该翁”的①②效果１回合仅可使用１次，在对手回合可以发动。\r\n①：从对手的额外牌组随机将１只里侧表示的怪兽除外。此卡的攻击力变为与除外的怪兽的攻击力相同。\r\n②：去除此卡的１个超量素材，以对手１只被除外的融合・同步・超量怪兽为对象可以发动。将该怪兽放回额外牌组，挑选对手场上１只种类（融合・同步・超量）与该怪兽相同的怪兽破坏。','\r',char(13)),'\n',char(10)),'除外','怪兽破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10691144,'冰结界之镜',replace(replace('①：此回合中，每次卡因对手所发动的怪兽的效果被除外，根据该卡是从何处被除外的，适用以下效果。\r\n●自己手牌：随机将对手的最多２张手牌除外。\r\n●自己场上：将对手场上的最多２张卡除外。\r\n●自己墓地：将对手墓地的最多２张卡除外。','\r',char(13)),'\n',char(10)),'是否要除外对手的手牌？','是否要除外对手场上的卡？','是否要除外对手墓地的卡？','除外一张手牌','除外两张手牌','','','','','','','','','','','');
INSERT INTO texts VALUES(10698416,'机怪虫・兰氏结','此卡名的①②效果1回合仅可各使用1次。①：此卡反转的情况下，以自己墓地最多2只“机怪虫”怪兽为对象可以发动。将该怪兽加入手牌。②：表侧表示的此卡因对手的效果从场上离开的情况下可以发动。将2只“机怪虫・兰氏结”以外的“机怪虫”怪兽从牌组以里侧守备表示特殊召唤（同名卡最多1张）。','墓地回收','2只怪兽特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10705656,'微件小子','此卡名的效果1回合仅可使用1次。①：此卡召唤・特殊召唤成功的情况下可以发动。从手牌将1只电子界族怪兽以守备表示特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10712320,'大日神械圣痕','１回合１次，可选择我方场上１张冠有“大日神械”之名的装备卡和另外１只成为正确对象的怪兽。将被选择的我方装备卡转换给被选择怪兽。此效果在对手回合也可发动。','装备转移','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10719350,'炎舞－天枢－',replace(replace('①：只要此卡存在于魔法与陷阱区域，自己除通常召唤外仅可追加１次，在自己的主要阶段召唤１只兽战士族怪兽。\r\n②：只要此卡存在于魔法与陷阱区域，自己场上的兽战士族怪兽的攻击力上升１００。','\r',char(13)),'\n',char(10)),'使用「炎舞－天枢－」的效果召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10723472,'燃烧之魂',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：自己场上存在等级８以上的同步怪兽的情况下可以发动。将自己墓地“燃烧之魂”以外的１张卡加入手牌。然后，进行１只同步怪兽的同步召唤。此卡发动后，直至回合结束时为止，对手不可以场上的同步怪兽作为效果的对象。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10731333,'娱乐伙伴・异色眼牛头人',replace(replace('←6 【灵摆】 6→\r\n①：我方的“娱乐伙伴”怪兽或“异色眼”怪兽攻击了守备表示怪兽的场合，给予对手相当于攻击力超过该守备力数值的战斗伤害。\r\n【怪兽效果】\r\n①：我方灵摆怪兽攻击对手怪兽的伤害计算时可发动。仅限于该伤害计算时，该对手怪兽的攻击力下降相当于我方场上的“娱乐伙伴”卡牌及“异色眼”卡牌数量×１００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10732060,'高速疾行机人 滑翔飞镖',replace(replace('机械族・风属性协调＋协调以外的怪兽1只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡同步召唤的情况下，以除协调以外的、自己墓地的1只等级7以下的风属性同步怪兽为对象可以发动。将该怪兽特殊召唤。\r\n②：对手特殊召唤怪兽的情况下，如果自己场上存在“清透翼”怪兽，将墓地的此卡除外则可以发动。对手场上的所有怪兽的等级上升5。','\r',char(13)),'\n',char(10)),'特殊召唤','等级上升','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10736540,'湖中少女薇薇安',replace(replace('以此卡为同步素材的场合，只可使用于战士族怪兽的同步召唤，被用于同步召唤的此卡被除外。\r\n①：此卡召唤成功时，可以我方墓地的１只“圣骑士”通常怪兽为对象发动。特殊召唤该怪兽。\r\n②：此卡存在于墓地的场合，可以我方场上１只等级５的“圣骑士”怪兽为对象发动。该怪兽等级下降１级，并从墓地特殊召唤此卡。','\r',char(13)),'\n',char(10)),'墓地苏生','此卡特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10753491,'森罗的神芽 幼芽','此卡特殊召唤成功时，可从我方牌组上方翻阅最多２张卡牌。若翻阅的卡牌中有植物族怪兽的场合，将所有那些怪兽送入墓地。剩余的卡牌依照喜好的顺序返回至牌组的最下方。此外，牌组的此卡因卡牌效果被翻阅并送入墓地的场合，可从牌组特殊召唤１只植物族、等级１怪兽。“森罗的神芽 幼芽”的此效果１回合只可使用１次。','翻开牌组','请选择要翻开牌组的数量','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10755153,'守护者・希尔','只有在我方场上有“流星之弓－希尔”存在的场合，才可召唤・反转召唤・特殊召唤此卡。将１张装备于此卡上的我方的装备卡送入墓地，破坏对手场上的１只怪兽。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10755984,'大薰风天鹰',replace(replace('协调＋协调以外冠有“薰风”之名的怪兽１只或以上\r\n１回合１次，可在我方结束阶段时，将我方墓地的１只风属性怪兽从游戏中除外并发动。选择１张被盖牌在对手场上的卡牌并破坏。','\r',char(13)),'\n',char(10)),'场上里侧表示存在的1张卡破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10759529,'小子防卫','对手怪兽的攻击宣言时，可解放我方场上的１只“英雄小子”并发动。使该攻击无效，并从牌组将１只冠有“元素－英雄”之名的怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10774240,'肃声保卫者 律守护者',replace(replace('以“肃声祈祷”降临\r\n此卡名的①③效果１回合仅可各使用１次。\r\n①：此卡仪式召唤的情况下可以发动。从牌组将１只“肃声”怪兽或战士族・龙族的仪式怪兽加入手牌。\r\n②：只要自己的场上或墓地存在“肃声之祈祷者 律”，此卡的攻击力上升２０５０。\r\n③：自己场上存在“肃声之祈祷者 律”，且对手发动魔法・陷阱・怪兽的效果时可以发动。将该发动无效并破坏。','\r',char(13)),'\n',char(10)),'牌组检索','发动无效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10780049,'皮尔莉分享莉！？',replace(replace('①：以自己场上的１只“皮尔莉”超量怪兽为对象可以发动。从牌组将１只等级１“皮尔莉”怪兽的效果无效并特殊召唤，将１只属性与对象怪兽不同、阶级相同的“皮尔莉”超量怪兽重叠在该特殊召唤的怪兽上面，视为超量召唤从额外牌组特殊召唤。然后，可适用以下效果。\r\n●根据对象怪兽持有的超量素材的“皮尔莉”速攻魔法卡，从牌组挑选１张其同名卡作为该超量召唤的怪兽的超量素材。','\r',char(13)),'\n',char(10)),'','是否把超量素材的同名卡作为超量素材？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10789972,'觉醒战士 库丘林','由“觉醒之证”召唤而来。１回合１次，可选择我方墓地中的１只通常怪兽发动此卡。将所选择怪兽从游戏中除外，此卡的攻击力上升从游戏中除外的通常怪兽的攻击力数值，直到下次我方回合的准备阶段时。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10793085,'铁兽之咆哮',replace(replace('此卡名的卡１回合仅可发动１张。①：自己场上存在连接怪兽的情况下，从牌组・额外牌组将１张“铁兽”卡送至墓地，以场上的１只效果怪兽为对象可以发动。根据送至墓地的卡的种类，适用以下效果。\r\n●怪兽：对象怪兽的攻击力直至回合结束时为止变为０。\r\n●魔法：对象怪兽效果直至回合结束时为止无效。\r\n●陷阱：将对象怪兽放回持有者的手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10796448,'A★黑桃天运',replace(replace('攻击力2500以上的怪兽＋守备力2500以下的里侧守备表示怪兽\r\n自己1回合仅可特殊召唤1次“A★黑桃天运”。\r\n①：此卡根据表示形式获得以下效果。\r\n●攻击表示：此卡的攻击力上升相当于对手场上怪兽的最高原本攻击力的数值。\r\n●守备表示：此卡不会因战斗・效果被破坏。\r\n②：此卡存在于墓地的情况下，从自己场上解放1只攻击表示怪兽和1只里侧守备表示怪兽可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10802915,'魔界发现世行死亡向导','①：此卡召唤时可以发动。从手牌・牌组将1只恶魔族・等级3怪兽特殊召唤。以此效果特殊召唤的怪兽的效果无效化，不可作为同步素材。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10802916,'魔界发现世行死亡向导','①：此卡召唤时可以发动。从手牌・牌组将1只恶魔族・等级3怪兽特殊召唤。以此效果特殊召唤的怪兽的效果无效化，不可作为同步素材。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10802917,'魔界发现世行死亡向导','①：此卡召唤时可以发动。从手牌・牌组将1只恶魔族・等级3怪兽特殊召唤。以此效果特殊召唤的怪兽的效果无效化，不可作为同步素材。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10802918,'魔界发现世行死亡向导','①：此卡召唤时可以发动。从手牌・牌组将1只恶魔族・等级3怪兽特殊召唤。以此效果特殊召唤的怪兽的效果无效化，不可作为同步素材。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10804018,'肃声龙神 萨菲拉',replace(replace('以“肃声祝福”降临\r\n此卡名的①②③效果１回合仅可各使用１次。\r\n①：此卡仪式召唤的情况下，如果自己场上或墓地存在“肃声之祈祷者 律”则可以发动。自己抽２张。然后，挑选自己的１张手牌舍弃。\r\n②：战士族・龙族的光属性仪式怪兽进行战斗的攻击宣言时可以发动。随机舍弃对手的１张手牌。\r\n③：在对手的结束阶段可以发动。从自己的墓地将１只光属性怪兽加入手牌。','\r',char(13)),'\n',char(10)),'抽牌并丢弃手牌','丢弃对手手牌','回收光属性怪兽','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10805153,'魔女工艺・协作','此卡名的①②效果１回合１次，仅可使用其中１个。①：以自己场上的１只“魔女工艺”怪兽为对象可以发动。此回合，该怪兽在１次战斗阶段中可攻击２次，该怪兽攻击的情况下，对手直至伤害步骤结束时为止不可发动魔法・陷阱卡。②：此卡存在于墓地，自己场上有“魔女工艺”怪兽存在的情况下，在自己的结束阶段可以发动。将此卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10807219,'新异蜜蜂！',replace(replace('此卡名以①方法的特殊召唤１回合仅可进行１次，且②效果１回合仅可使用１次。\r\n①：自己墓地存在攻击力和守备力为０的怪兽的情况下，此卡可从手牌特殊召唤。\r\n②：此卡从手牌特殊召唤的情况下可以发动。可分别适用以下效果。\r\n●将自己墓地“新异蜜蜂！”以外的１只昆虫族・光属性怪兽加入手牌。\r\n●将自己墓地・除外状态的１张陷阱卡放回牌组最上面或最下面。','\r',char(13)),'\n',char(10)),'特殊召唤','发动效果','是否把怪兽加入手牌？','是否让陷阱回到牌组？','牌组最上面','牌组最下面','','','','','','','','','','');
INSERT INTO texts VALUES(10808715,'假面－英雄 暮鸦',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡存在于手牌的情况下，从自己墓地将1只“－英雄”怪兽除外可以发动。将此卡特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从自己牌组・墓地将“假面－英雄 暮鸦”以外的1只“假面－英雄”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10809984,'世纪大盗','此卡给予对手LP战斗伤害时，宣言１个卡名。确认对手的手牌，将其中的宣言的卡全部舍弃。','宣言','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10813327,'打草蛇','①：被放置的此卡因对手的效果从场上离开、并被送至墓地的情况下，或者是被除外的情况下可以发动。从牌组・额外牌组将1只怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10817524,'始祖龙',replace(replace('通常怪兽×２\r\n此卡仅可以融合召唤特殊召唤。①：“始祖龙”在自己场上仅可有１只以表侧表示存在。②：只要此卡存在于怪兽区域，不会因与通常怪兽以外的怪兽的战斗被破坏，不受此卡以外怪兽的效果影响。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10833828,'魔神王的禁断契约书',replace(replace('①：1回合1次，在自己的主要阶段可以发动。从手牌将1只“DDD”怪兽以守备表示特殊召唤。以此效果特殊召唤的怪兽的效果无效化。\r\n②：1回合1次，在自己的主要阶段可以发动。将包含以此卡的①效果特殊召唤的怪兽在内的、自己手牌・场上的怪兽作为融合素材，将1只恶魔族的融合怪兽融合召唤。\r\n③：在自己的准备阶段发动。自己受到2000伤害。','\r',char(13)),'\n',char(10)),'特殊召唤','融合召唤','效果伤害','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10851853,'花恐龙',replace(replace('此卡不可通常召唤，仅可以此卡的效果特殊召唤。\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：自己发动陷阱卡的效果的情况下，或对手发动魔法卡的效果的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：此卡被送至墓地的情况下，从自己及对手被除外的魔法・陷阱卡中以合计３张为对象可以发动。将这些卡以喜欢的顺序放回持有者的牌组下面。然后，自己从牌组抽１张。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10852583,'弥次郎侵略者','①：此卡被召唤・特殊召唤至中央以外的主要怪兽区域的情况下破坏。②：1回合1次，在自己的主要阶段可以发动。将此卡移动至相邻且未使用的主要怪兽区域。③：每当仅1只怪兽被召唤・特殊召唤至对手场上，发动此效果。该对手怪兽的位置与此卡为不同纵列的情况下，将此卡移动至相邻的主要怪兽区域以靠近该怪兽。然后，将与移动过的此卡同一纵列的其他卡全部破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10859908,'全息投影机','使人看见各种幻象并趁机进行攻击的机器。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10860121,'武斗神器－孔雀',replace(replace('“武斗神器－孔雀”的效果１回合只可使用１次。\r\n①：我方场上的兽战士族“武斗神”怪兽因战斗被破坏并送入墓地时，可从手牌将此卡送入墓地并发动。从牌组特殊召唤１只“武斗神”怪兽。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10875327,'地缚神 Aslla piscu',replace(replace('①：“地缚神”怪兽在场上仅可有１只以表侧表示存在。\r\n②：此卡可直接攻击。\r\n③：对手怪兽不可将此卡选择为攻击对象。\r\n④：不存在表侧表示的场地魔法卡的情况下，此卡将被破坏。\r\n⑤：表侧表示的此卡以此卡的效果以外的方法从场上离开的情况下发动。将对手场上的表侧表示怪兽全部破坏，给予对手相当于所破坏数量×８００的伤害。','\r',char(13)),'\n',char(10)),'伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10877309,'时潜怪盗・起动','此卡名的①②效果1回合1次，仅可使用其中1个。①：从手牌将1只“时潜怪盗”怪兽特殊召唤。②：在自己的主要阶段将墓地的此卡除外，以自己场上的1只“时潜怪盗”超量怪兽对象可以发动。从自己墓地挑选3种“时潜怪盗”卡（怪兽・魔法・陷阱）各1张，重叠在对象怪兽下面作为超量素材。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10920352,'假面－英雄 蒸汽','此卡仅可以“假面变换”的效果特殊召唤。①：场上的此卡不会因效果被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10925955,'与仪水镜之交讯',replace(replace('①：自己场上有水属性怪兽存在的情况下，可从以下效果中选择１个发动。此卡发动时自己场上有水属性仪式怪兽存在的情况下，以下两个效果均可选择。\r\n●确认所有被放置在对手的魔法与陷阱区域的卡。\r\n●从自己或对手牌组上面确认２张卡，以喜欢的顺序放回牌组上面。','\r',char(13)),'\n',char(10)),'确认对手的魔法与陷阱卡区域放置的卡','确认牌组上方的两张卡','两个效果都使用','确认自己的牌组','确认对手的牌组','','','','','','','','','','','');
INSERT INTO texts VALUES(10928224,'亚马逊宠物仔虎',replace(replace('此卡牌名的②效果１回合只可使用１次。\r\n①：只要存在于场上、墓地，此卡的卡牌名被视为“亚马逊宠物虎”。\r\n②：此卡存在于手牌、墓地，且召唤、特殊召唤“亚马逊”怪兽至我方场上的场合可发动。特殊召唤此卡。\r\n③：此卡的攻击力上升我方墓地“亚马逊”卡牌数量×１００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10938846,'心之桥梁',replace(replace('此卡名的②③效果１回合仅可各使用１次。\r\n①：自己除通常召唤外仅可追加１次，在自己的主要阶段召唤１只“宝玉兽”怪兽。\r\n②：在自己的主要阶段可以发动。挑选自己的手牌・场上的１张“宝玉兽”卡破坏，从牌组将１张“宝玉”魔法・陷阱卡加入手牌。\r\n③：自己的魔法与陷阱区域放有“宝玉兽”卡的情况下，以对手场上的１张卡为对象可以发动（伤害步骤也可发动）。将该卡和此卡放回持有者的手牌。','\r',char(13)),'\n',char(10)),'使用「心之桥梁」的效果召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10949074,'异宇宙战煌','踏遍几亿战火的异界之军神。汝若欲此威光，来取便是。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10960419,'时间魔术槌',replace(replace('仅限以“海尔摩斯之爪”的效果将我方手牌、场上的魔法师族怪兽送入墓地的场合，此卡可特殊召唤。\r\n①：此卡特殊召唤成功的场合，以场上除此卡以外的１只怪兽为对象发动。此卡被视为装备卡装备该怪兽。\r\n②：以此卡效果装备此卡的怪兽与对手怪兽进行战斗的伤害步骤开始时可发动。掷１次骰子。直至与掷出的数字相同数量回合后的准备阶段，将该对手怪兽除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10963799,'暴雨之结界像','①：只要此卡存在于怪兽区域，双方仅可特殊召唤水属性怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10966439,'棉花喵☆黯蜜',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：自己场上的怪兽，不存在的情况下或均为兽族・光属性怪兽的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从自己墓地将1张“黯蜜”魔法・陷阱卡加入手牌。以同步怪兽的效果特殊召唤的情况下，作为代替也可将自己牌组・除外状态的1张“黯蜜”场地魔法卡或“黯蜜”永续魔法・永续陷阱卡以表侧表示放在自己场上。','\r',char(13)),'\n',char(10)),'特殊召唤','回收效果','是否放置永续·场地卡？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10971759,'光虫异变',replace(replace('“光虫异变”１回合只可发动１张。\r\n①：可以我方墓地的２只昆虫族、等级３怪兽为对象发动。特殊召唤该怪兽。以此效果特殊召唤而来的怪兽效果被无效化。\r\n②：可从我方墓地将此卡和１只超量怪兽除外并发动。直至回合结束时，我方场上所有昆虫族、等级３怪兽的等级变成与被除外之超量怪兽的阶级相同数值等级。此效果发动后，直至回合结束时，我方只可特殊召唤昆虫族怪兽。','\r',char(13)),'\n',char(10)),'特殊召唤','等级变更','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10979723,'亚马逊宠物虎','我方场上只可有１张表侧表示的此卡存在。我方场上每有１张冠有“亚马逊”之名的怪兽卡存在，此卡的攻击力便上升４００点。只要对手未破坏此卡，就不可攻击场上其他冠有“亚马逊”之名的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(10992251,'超时界战斗机 V型蛇','通过动能胶囊，发挥各种能力的超高性能战斗机。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11012154,'守护龙 尤司帝阿',replace(replace('星键流下未流的泪水，天命得遂。\r\n神之门嘶吼崩裂，蛇吞噬守人的幻梦。\r\n其之魂魄去往初始之地，彼之魂魄去往终极之地。\r\n--此处将开辟神狱之星。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11012887,'朱罗纪・瓜巴龙','①：此卡战斗破坏对手怪兽时可以发动。从牌组将1只攻击力1700以下的“朱罗纪”怪兽特殊召唤。以此效果特殊召唤的怪兽在此回合不可攻击宣言。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11020863,'皇家同花顺剑士',replace(replace('此卡不可通常召唤，仅可以“皇家同花顺”的效果特殊召唤。\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：“王后骑士”、“卫兵骑士”、“国王骑士”在自己墓地全部存在的情况下可以发动。将等级１～５的怪兽各１只从手牌・牌组送至墓地，将对手场上的卡全部破坏。\r\n②：此卡因战斗被破坏时，以自己墓地最多３只战士族・光属性怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11021521,'招财猫王','对手回合中此卡因对手效果被送入墓地时，结束对手回合。','回合结束','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11024707,'回猫',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡从手牌・牌组被送至墓地的情况下可以发动。将此卡以里侧守备表示特殊召唤。\r\n②：反转的此卡存在于怪兽区域的状态下，怪兽从手牌・牌组送至自己墓地的情况下，以其中１只为对象可以发动。将该怪兽以里侧守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11035075,'死地误算守护',replace(replace('①：将自己或对手墓地的1只等级1或阶级1的怪兽特殊召唤至自己场上，装备此卡。\r\n②：在自己・对手的结束阶段发动。装备怪兽的等级・阶级上升1。\r\n③：根据装备怪兽的等级・阶级，适用以下效果。\r\n●3以上：该怪兽的攻击力上升相当于其原本攻击力的数值。\r\n●5以上：该怪兽不受对手发动的效果影响。\r\n④：在自己的准备阶段，装备怪兽的等级・阶级在7以上的情况下发动。将场上的卡全部送至墓地。','\r',char(13)),'\n',char(10)),'发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11039171,'魔玩具・剪刀狼',replace(replace('“锋利小鬼・剪刀”＋1只以上“绒毛动物”怪兽\r\n此卡仅可用以上述卡为融合素材的融合召唤特殊召唤。①：此卡在1次战斗阶段中，可攻击次数最多为此卡的作为融合素材的怪兽数量。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11047543,'念力感知区','①：以被除外的自己的、１只念动力族协调和１只协调以外的念动力族怪兽为对象可以发动。将该２只怪兽放回墓地。然后，将１只拥有与放回怪兽等级合计相同等级的念动力族同步怪兽从额外牌组以守备表示特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11050415,'超河马嘉年华','①：从自己的手牌・牌组・墓地挑选１只“娱乐伙伴 探索河马”特殊召唤。然后，可将“河马衍生物”（兽族・地・星１・攻／守０）尽可能多地特殊召唤至自己场上。此衍生物不可解放。只要“河马衍生物”存在于怪兽区域，自己不可从额外牌组特殊召唤怪兽。以此效果特殊召唤了“河马衍生物”的情况下，直至回合结束时为止，对手不可将“河马衍生物”以外的怪兽作为攻击对象。','是否尽可能地特殊召唤「河马衍生物」？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11050416,'河马衍生物','由“河马嘉年华”等的效果特殊召唤而来。此衍生物不可用作祭品。只要“河马衍生物”在怪兽区，特殊召唤“河马衍生物”的玩家就不能从额外牌组特殊召唤怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11050417,'河马衍生物','由“河马嘉年华”等的效果特殊召唤而来。此衍生物不可用作祭品。只要“河马衍生物”在怪兽区，特殊召唤“河马衍生物”的玩家就不能从额外牌组特殊召唤怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11050418,'河马衍生物','由“河马嘉年华”等的效果特殊召唤而来。此衍生物不可用作祭品。只要“河马衍生物”在怪兽区，特殊召唤“河马衍生物”的玩家就不能从额外牌组特殊召唤怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11050419,'河马衍生物','由“河马嘉年华”等的效果特殊召唤而来。此衍生物不可用作祭品。只要“河马衍生物”在怪兽区，特殊召唤“河马衍生物”的玩家就不能从额外牌组特殊召唤怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11052544,'军刀斩','①：依自己场上的攻击表示的“X－军刀”怪兽的数量，将场上的表侧表示卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11066358,'银河长蛇','据说会在黄昏夜色中悄然出现的龙。它飞翔的神秘姿态宛如在星辰大海中遨游，故得此名。传说中能看到它的人屈指可数，但一旦见过，就会获得崭新力量。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11067666,'白翼的魔术师',replace(replace('←1 【灵摆】 1→\r\n①：１回合１次，可将以自己场上的魔法师族・暗属性怪兽为对象发动的效果无效。然后将此卡破坏。\r\n【怪兽效果】\r\n此卡在规则上也视为“同步龙”卡。灵摆召唤的此卡被使用于同步召唤的情况下将被除外。','\r',char(13)),'\n',char(10)),'是否使用「白翼的魔术师」的效果？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11069680,'废品转换者',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从手牌将此卡和1只协调舍弃可以发动。从牌组将1只“同步士”怪兽加入手牌。\r\n②：此卡作为同步素材被送至墓地的情况下，以自己墓地的1只协调为对象可以发动。将该怪兽以守备表示特殊召唤。此回合，以此效果特殊召唤的怪兽的效果不可发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11074235,'魔晶龙吉鲁德拉斯','此卡名的效果1回合仅可使用1次。①：此卡存在于手牌・墓地，自己场上的魔法・陷阱卡因对手的效果从场上离开、被送至墓地的情况下或被除外的情况下可以发动。将此卡特殊召唤。然后，可从自己墓地的卡及自己被除外的卡中挑选1张魔法・陷阱卡放置在自己的魔法与陷阱区域。以此效果特殊召唤的此卡离开场上的情况下，将其除外。','','是否放置魔法·陷阱卡？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11082056,'克里底亚之牙',replace(replace('此卡的卡牌名称在规则上视为“传说之龙 克里提斯”。\r\n１个回合中只可发动１张“克里底亚之牙”。\r\n①：将只有“克里底亚之牙”的效果才可特殊召唤的融合怪兽卡记述的１张陷阱卡从我方手牌・场上送入墓地（该卡被盖牌在场上的场合，翻开进行确认）。之后，从额外牌组特殊召唤１只该融合怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11091375,'蓝玉石龙','全身被蓝玉覆盖，外形非常美丽的龙。虽然不喜欢争斗，但具有很强的攻击力。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11102908,'紫炎的霞城','冠有“六武众”之名的怪兽被攻击的场合，攻击怪兽的攻击力仅限在伤害计算时下降５００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11109820,'超量宇宙','①：以场上的2只超量怪兽为对象可以发动。将该2只怪兽送至墓地。然后，从额外牌组将阶级与该2只超量怪兽的阶级合计相同或低1的、“编号”怪兽以外的1只超量怪兽特殊召唤，将此卡作为该怪兽的超量素材。此卡发动后，直至回合结束时为止，对手受到的所有伤害变为0。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11110218,'常世断离','此卡名的卡１回合仅可发动１张。①：以对手墓地的最多５张卡为对象，并依该数量，以被除外的对手的卡为对象可以发动。将墓地的对象卡除外，将被除外的对象卡放回墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11110587,'邻人割草','①：自己牌组的张数多于对手的情况下可以发动。从自己牌组上面将卡送至墓地，直至牌组的张数变为与对手相同。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11125718,'枪骑龙兵','①：此卡攻击了守备表示怪兽的场合，给予攻击力超过该守备力数值的战斗伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11132674,'超巨霸“冠军”飒嘉斯',replace(replace('等级８怪兽×２只以上\r\n“超巨霸“冠军”飒嘉斯”１回合１次，也可重叠在自己场上的“守宝团”超量怪兽上面来超量召唤。此卡名的①②效果１回合仅可各使用１次。①：此卡拥有超量素材的情况下可以发动。从牌组将１张“守宝团”卡或“兽带斗士”卡加入手牌。②：场上的超量素材被去除的情况下，以场上的１张卡为对象可以发动。将该卡破坏或放回持有者的手牌。','\r',char(13)),'\n',char(10)),'是否在「守宝团」超量怪兽上面重叠来超量召唤？','','场上1张卡破坏或回到持有者手牌','破坏','回到手牌','','','','','','','','','','','');
INSERT INTO texts VALUES(11136371,'反击宝石','可将我方魔法与陷阱区域的所有其他卡牌送入墓地并发动。尽可能地从我方墓地将冠有“宝玉兽”之名的怪兽视为永续魔法卡并以表侧表示放置在我方的魔法与陷阱区域。此回合的结束阶段时，破坏我方场上冠有“宝玉兽”之名的所有卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11155484,'宝玉之奇迹',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：怪兽的效果・魔法・陷阱卡发动时可以发动。挑选自己场上的１张“宝玉兽”卡破坏，将该发动无效并破坏。\r\n②：此卡存在于墓地的状态下，自己的魔法与陷阱区域放入“宝玉兽”卡的情况下，将此卡除外可以发动（伤害步骤也可发动）。从自己的手牌・牌组・墓地挑选１只“宝玉兽”怪兽，视为永续魔法卡，以表侧表示放在自己的魔法与陷阱区域。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11159464,'异虫霍普','反转：此卡因对手怪兽的攻击反转的场合，从牌组抽取１张卡牌。此外，此卡从场上被送入墓地时，我方挑选１张手牌并送入墓地。','把1张手牌送至墓地','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11161666,'御巫奉 纱鸣',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：以自己场上的1张“御巫”卡为对象可以发动。将该卡放回手牌。\r\n②：此卡被装备上装备卡的情况下可以发动。从牌组将幻想魔族以外的1只“御巫”怪兽特殊召唤。此回合，自己从额外牌组仅可特殊召唤“御巫”怪兽。\r\n③：此卡被送至墓地的情况下，以场上的1只表侧表示怪兽为对象可以发动。将此卡视为装备魔法卡装备于该怪兽。','\r',char(13)),'\n',char(10)),'回到手牌','特殊召唤','装备','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11163040,'坏兽的出现记录',replace(replace('①：每次“坏兽”怪兽被从手牌・墓地特殊召唤，在此卡上放１个坏兽计数物（最多５个）。\r\n②：１回合１次，以场上的１只“坏兽”怪兽为对象可以发动。将该怪兽破坏，然后，将１只原本卡名与所破坏怪兽不同的“坏兽”怪兽从自己的牌组特殊召唤至该怪兽控制者的场上。\r\n③：将坏兽计数物为３个以上的此卡送至墓地可以发动。从牌组将１张“坏兽的出现记录”以外的“坏兽”魔法・陷阱卡加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11167052,'灵神统一',replace(replace('①：只要此卡存在于魔法与陷阱区域，我方场上的“灵神的圣殿”不会因效果被破坏，也不会成为对手效果的对象。\r\n②：１回合１次，可解放１只我方场上的怪兽并发动。从牌组特殊召唤１只原本属性不同于被解放怪兽的“元素军刀”怪兽。\r\n③：可将魔法与陷阱区域表侧表示的此卡送入墓地并发动。舍弃所有手牌。之后，从我方墓地挑选“灵神”怪兽加入手牌，其数量相当于因此效果舍弃的卡牌数量。','\r',char(13)),'\n',char(10)),'特殊召唤','墓地回收','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11193246,'月光轮回舞蹈','此卡名的卡１回合仅可发动１张。①：自己场上的怪兽因战斗・效果被破坏的情况下可以发动。从牌组将最多２只“月光”怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11212437,'魔龙阁－德拉尔维斯','不断吐出龙之诅咒的女战士的末路。如今，她已成为瘟疫的根源，其身影化作邪念涌动的楼阁，成为人们复仇的对象。阻挡在眼前的讨伐队，是曾被龙毁灭的村庄的幸存者。对此，她如今已无从知晓……','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11221418,'武斗神隐','选择自己场上１只“武斗神”超量怪兽可以发动。将选择的怪兽除外，将场上的怪兽全部放回手牌。直至发动后第２次自己的结束阶段时为止，双方不可召唤・反转召唤・特殊召唤，双方将受到的所有伤害变为０。此外，发动后第２次的自己的结束阶段时发动。将以此卡的效果除外的怪兽特殊召唤，选择自己墓地的１只“武斗神”怪兽，重叠在该特殊召唤的怪兽下面作为超量素材。','结束召唤限制','此卡的效果除外的怪兽特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11224103,'荷鲁斯之黑炎龙 LV6',replace(replace('①・此卡只要存在于怪兽区域，不受魔法卡的效果影响。\r\n②：在此卡战斗破坏怪兽的回合的结束阶段，将此卡送至墓地可以发动。从手牌・牌组将１只“荷鲁斯之黑炎龙 LV8”特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11224934,'强化空间','直至回合结束时，我方场上所有超量怪兽的攻击力上升该超量素材的数量×３００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11228035,'超量之魂','可选择我方或对手墓地的１只超量怪兽并发动。我方场上所有怪兽的攻击力直至回合结束时上升相当于被选择怪兽的阶级×２００点。之后，被选择怪兽可返回至额外牌组。','是否要让选择的怪兽回到额外牌组？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11232355,'超能毁灭者','可支付１０００点LP来发动此卡。选择对手场上１张被盖牌的魔法・陷阱卡并将其破坏。此外，在双方的结束阶段时，我方场上没有除此卡以外的念动力族怪兽存在的场合，破坏此卡。','魔法·陷阱卡破坏','自坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11234702,'T.G.螺旋桨海蛇','此卡名的①②效果1回合仅可各使用1次。①：此卡召唤・特殊召唤成功的情况下，以自己墓地“T.G.螺旋桨海蛇”以外的1只等级4以下的“T.G.”怪兽为对象可以发动。将该怪兽的效果无效并特殊召唤。②：将墓地的此卡除外，以自己场上的1只“T.G.”怪兽为对象可以发动。该怪兽的等级直至回合结束时为止上升或下降1。','','等级上升1星','等级下降1星','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11248645,'殿下恶魔',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤的情况下，从自己墓地将1张“恶魔”卡除外可以发动。从牌组将“殿下恶魔”以外的2张“恶魔”卡加入手牌。此效果发动后，直至回合结束时为止，自己从额外牌组仅可特殊召唤“恶魔”怪兽。\r\n②：此卡存在于墓地的状态下，自己的仪式怪兽因战斗被破坏时可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'检索效果','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11250655,'水陆的帝王','巨大的嘴会向四面八方吐出火焰，是一只爬虫类怪物。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11260714,'堕天使 倨薄彼亚','①：从墓地将此卡特殊召唤时，以“堕天使 倨薄彼亚”以外的、自己墓地的1只天使族怪兽为对象可以发动。将该天使族怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11264180,'TGX1－HL','可选择我方场上冠有“T.G.”之名的１只怪兽并发动。被选择怪兽的攻击力、守备力减半，并挑选场上的１张魔法、陷阱卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11270236,'召唤兽 埃律西昂',replace(replace('“召唤兽”怪兽＋从额外牌组被特殊召唤的怪兽\r\n此卡仅可用以上述卡作为融合素材的融合召唤来从额外牌组特殊召唤。①：只要此卡存在于怪兽区域，此卡的属性也视为“暗”“地”“水”“炎”“风”。②：１回合１次，以自己场上・墓地的１只“召唤兽”怪兽为对象可以发动。将该怪兽及与对手场上拥有与该怪兽相同属性的怪兽全部除外。此效果在对手回合中也可以发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11287364,'速攻扳手骑士','此卡被使用于同步怪兽的同步召唤并被送入墓地的场合，选择对手场上的１只表侧表示怪兽，并将该攻击力下降５００点。','攻击下降 ','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11302671,'魔救分析者',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：仅有对手场上才存在怪兽的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：在自己的主要阶段可以发动。从自己牌组上面翻开5张卡。可从其中挑选1只协调以外的等级4以下的岩石族怪兽特殊召唤。将剩余的以喜欢的顺序放回牌组下面。','\r',char(13)),'\n',char(10)),'','','是否特殊召唤怪兽？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11317977,'月光黑羊',replace(replace('①：从手牌将此卡舍弃，可从以下效果中选择1个发动。\r\n●从自己墓地将“月光黑羊”以外的1只“月光”怪兽加入手牌。\r\n●从牌组将1张“融合”加入手牌。\r\n②：此卡作为融合召唤的素材被送至墓地的情况下可以发动。从自己的额外牌组（表侧）・墓地将“月光黑羊”以外的1只“月光”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'墓地回收','牌组检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11321089,'守护者・客迈拉',replace(replace('卡名不同的怪兽×３\r\n此卡从额外牌组仅可通过以手牌和自己场上各１只以上的怪兽作为素材的融合召唤来特殊召唤。此卡名的①效果１回合仅可使用１次。①：此卡以魔法卡的效果融合召唤成功的情况下可以发动。依手牌作为融合素材的卡的数量、自己从牌组抽牌，依场上作为融合素材的卡的数量、挑选对手场上的卡破坏。②：只要自己墓地存在“融合”，此卡不会成为对手效果的对象。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11321183,'暗魔界战士 暗黑剑','据说能操控龙的暗魔界战士。其用邪恶的力量进行劈砍的攻击锐不可当。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11324436,'电蛇','此卡因对手效果从手牌被舍弃至墓地时，从我方牌组抽取２张卡牌。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11327848,'修士号 文凭人',replace(replace('①：此卡上级召唤成功的情况下，以自己墓地的１只怪兽和对手场上的１只表侧表示怪兽为对象可以发动。将该墓地的怪兽视为装备卡，装备于该对手怪兽。只要以此效果装备着怪兽，装备怪兽的攻击力下降相当于其攻击力的数值。\r\n②：只要此卡存在于怪兽区域，装备了自己的魔法与陷阱区域的装备卡的对手怪兽的效果不可发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11335209,'荷鲁斯的祝福－杜阿木忒弗',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次，且③效果1回合仅可使用1次。\r\n①：自己场上存在“王之棺”的情况下，此卡可从墓地特殊召唤。\r\n②：此卡的攻击力・守备力上升相当于自己场上的“荷鲁斯”怪兽的数量×1200的数值。\r\n③：此卡存在于怪兽区域的状态下，自己场上的其他卡因对手的效果从场上离开的情况下可以发动。自己依自己的主要怪兽区域的怪兽种类数量抽牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11366199,'黑暗西摩格','①：此卡存在于手牌的情况下，从自己的墓地将暗属性和风属性的怪兽各1只除外可以发动。将此卡特殊召唤。②：此卡存在于墓地的情况下，从手牌将暗属性和风属性的怪兽各1只除外可以发动。将此卡特殊召唤。③：只要此卡存在于怪兽区域，此卡的属性也视为“风”。④：只要此卡存在于怪兽区域，对手不可放置卡。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11373345,'无力的证明','我方场上存在等级７或以上怪兽的场合可发动。破坏对手场上等级５或以下全部怪兽。此卡发动的回合，我方场上的怪兽不可攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11375683,'廷达三角・三位一体',replace(replace('此卡名的③效果１回合仅可使用１次。\r\n①：此卡反转的情况下可以发动。从牌组将１只“廷达三角・底边守卫者”特殊召唤。\r\n②：只要反转的此卡存在于怪兽区域，自己的“廷达三角”怪兽不会因战斗被破坏。\r\n③：此卡作为“廷达三角”连接怪兽的连接素材被送至墓地的情况下可以发动。从牌组将１张“热尔岗终焉”加入手牌，从牌组将１张魔法・陷阱卡送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11384280,'加农炮兵','可解放我方场上的１只怪兽并发动。给予对手生命５００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11390349,'大植然飞蝇','只要此卡以表侧表示存在于场上，对手场上怪兽的攻击力、守备力下降相当于我方场上冠有“大植然”之名怪兽的数量×３００点。此外，１回合１次，直至结束阶段时，可选择对手场上１只守备力为０的怪兽并获得其控制权。','获得控制权','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11398059,'王者戈兰林',replace(replace('等级4怪兽×2\r\n①：1回合1次，去除此卡的1个超量素材可以发动。从牌组将1只爬虫类族怪兽加入手牌。','\r',char(13)),'\n',char(10)),'检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11398951,'机械天使的绝对仪式','“电子天使”仪式怪兽降临所必需。①：为使合计等级与仪式召唤的怪兽相等，解放自己手牌・场上的怪兽，或从自己的墓地将天使族或战士族怪兽放回牌组作为解放的代替，从手牌将１只“电子天使”仪式怪兽仪式召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11411223,'编号10 白辉士照耀者',replace(replace('等级４怪兽×３\r\n１回合１次，可移除此卡的１个超量素材并发动。挑选１张我方手牌送入墓地，并从我方牌组抽取１张卡牌。','\r',char(13)),'\n',char(10)),'抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11426487,'花骑士团的白马','此卡名以①方法的特殊召唤1回合仅可进行1次，且②效果1回合仅可使用1次。①：自己场上有等级2以下的怪兽存在的情况下，此卡可从手牌以守备表示特殊召唤。②：对手怪兽攻击宣言时，将墓地的此卡除外，以自己场上的1张卡为对象可以发动。使该攻击无效，将对象卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11429811,'警戒点','①：怪兽受到了召唤、反转召唤或特殊召唤时可以发动。此回合中，该表侧表示的怪兽无法攻击，效果失效，且无法作为融合、同步、超量、连接召唤的素材。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11434258,'蛇龙的枷锁',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：以对手场上・墓地的１只连接怪兽为对象可以发动。依该怪兽的连接标记数量，自己从牌组抽牌。然后，自己的手牌为２张以上的情况下，从其中挑选２张，以喜欢的顺序放回牌组最下面。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11439455,'月光苍猫','此卡名的①效果１回合仅可使用１次。①：此卡特殊召唤成功的情况下，以自己场上“月光苍猫”以外的１只“月光”怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止变为原本攻击力的两倍。②：场上的此卡因战斗・效果被破坏的情况下可以发动。从牌组将１只“月光”怪兽特殊召唤。','攻击力变成2倍','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11441009,'朋.克.即兴狂热！',replace(replace('等级8怪兽×2\r\n“朋.克.即兴狂热！”1回合1次，也可重叠在自己场上的“朋.克.”融合・同步怪兽上面来超量召唤。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：支付600LP，去除此卡的1个超量素材可以发动。自己抽1张。\r\n②：自己墓地存在念动力族・等级3怪兽，且此卡以外的怪兽的效果发动时，去除此卡的1个超量素材可以发动。将该发动无效并破坏。','\r',char(13)),'\n',char(10)),'是否在「朋.克.」融合·同步怪兽上面重叠来超量召唤？','抽牌','无效发动','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11443677,'青眼暴君龙',replace(replace('“青眼白龙”＋龙族怪兽\r\n此卡从额外牌组仅可通过融合召唤及以下方法特殊召唤。\r\n●解放１只装备着融合怪兽的自己的“青眼白龙”的情况下，可从额外牌组特殊召唤。\r\n①：场上的此卡不受陷阱卡的效果影响。\r\n②：此卡可攻击所有对手怪兽各１次。\r\n③：１回合１次，此卡进行战斗的伤害步骤结束时，以自己墓地的１张陷阱卡为对象可以发动。将该卡放置在自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11448373,'墓地守卫','只要此卡以表侧表示存在于场上，因战斗被破坏的怪兽不送入墓地，返回至持有者牌组。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11449436,'冰河之水魔道士',replace(replace('①：在自己的通常怪兽与对手怪兽进行战斗的伤害步骤开始时，将手牌中的此卡出示给对手可以发动。挑选１张自己的手牌舍弃，该自己的怪兽不会因该战斗被破坏。\r\n②：在此卡与对手怪兽进行战斗的伤害步骤开始时，将手牌的１只通常怪兽出示给对手可以发动。挑选１张自己的手牌舍弃，该将该对手的怪兽破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11458071,'天魔神 恩莱兹','此卡不可通常召唤。仅限在我方墓地的３只光属性、天使族怪兽与１只暗属性、恶魔族怪兽从游戏中除外的场合可特殊召唤。可选择场上以表侧表示存在的１只怪兽从游戏中除外。发动此效果的场合，此回合的此卡不可攻击。此效果１回合只可使用１次。','除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11460577,'电子明星','此卡直接攻击手玩家的场合，伤害步骤期间的攻击力上升５００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11464648,'威魔镌刻・雷克斯托雷米德',replace(replace('“魔镌”融合怪兽＋融合・连接怪兽\r\n此卡名的①③效果1回合仅可各使用1次。\r\n①：此卡融合召唤的情况下，舍弃1张手牌可以发动。从牌组・额外牌组将1只恶魔族・光属性怪兽送至墓地。\r\n②：此卡只要装备有“魔镌”装备魔法卡，就不受“魔镌”卡以外的卡的效果影响。\r\n③：此卡被送至墓地的情况下，以自己墓地・除外状态的1张其他的“魔镌”卡为对象可以发动。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'送至墓地','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11471117,'光之抹杀剑','仅限装备光属性、战士族怪兽。在装备怪兽与怪兽进行战斗的伤害计算后发动。伤害步骤结束时，从游戏中将该怪兽除外。','战斗对象除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11475049,'古遗物－阿基里斯','①：此卡可视为魔法卡从手牌放置在魔法与陷阱区域。②：放置在魔法与陷阱区域的此卡在对手回合被破坏并送至墓地的情况下发动。将此卡特殊召唤。③：在对手回合中，此卡特殊召唤成功的情况下发动。此回合中，对手怪兽不可将“古遗物”怪兽作为攻击对象。','特殊召唤','攻击限制','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11481610,'娱乐伙伴弹出','此卡名的卡１回合仅可发动１张。①：将最多３张手牌送至墓地可以发动。自己依所送数量从牌组抽牌。然后，可将拥有自己灵摆区域２张卡的灵摆刻度下可灵摆召唤等级的、“娱乐伙伴”怪兽、“魔术师”灵摆怪兽、“异色眼”怪兽从手牌特殊召唤，数量最多为以此效果所抽牌的数量（同名卡最多１张）。没有以此卡的效果特殊召唤的情况下，自己失去相当于自己手牌数量×１０００的LP。','是否从手牌特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11489642,'三角阵－Ｏ',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n \r\n①：“水晶头骨”、“阿育王石柱”、“伊卡黑石”全部存在于自己场上的情况下可以发动。将场上的卡全部破坏。此回合，自己受到的效果伤害由对手代为承受。 \r\n②：将墓地的此卡除外，以自己墓地的“水晶头骨”、“阿育王石柱”、“伊卡黑石”各１只为对象可以发动。将该怪兽放回牌组。然后，自己抽３张。','\r',char(13)),'\n',char(10)),'场上的卡全部破坏','回收并抽牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11493868,'极强音',replace(replace('①：１回合１次，以自己场上的１只“幻奏”怪兽为对象可以发动。该怪兽的攻击力直至下个自己的准备阶段为止上升８００。\r\n②：将魔法与陷阱区域的表侧表示的此卡送至墓地可以发动。以自己场上的怪兽作为融合素材，将１只“幻奏”融合怪兽融合召唤。','\r',char(13)),'\n',char(10)),'攻击上升','融合召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11496832,'首席哈巴',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：以原本卡名包含“守护者”的、自己场上的１只不可通常召唤的怪兽为对象可以发动。此回合，该怪兽在１次战斗阶段中可攻击２次。\r\n②：将墓地的此卡除外，以自己墓地１只不可通常召唤的“守护者”怪兽为对象，可从以下效果中选择１个发动。\r\n●将对象怪兽加入手牌。\r\n●从自己的墓地将１张卡名记载于对象怪兽的卡加入手牌。','\r',char(13)),'\n',char(10)),'','作为对象的怪兽加入手牌','作为对象的怪兽有卡名记述的卡加入手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11501629,'踢火','只要此卡存在于场上，每次我方场上以表侧表示存在的炎属性怪兽因卡牌效果被破坏时，放置与被破坏怪兽数量相同的计数物至此卡。此效果１回合只可适用１次。此外，我方或对手的准备阶段时，可将此卡送入墓地并发动。给予对手生命相当于因此卡牌效果放置于此卡的计数物数量×１０００点的伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11502550,'元素－英雄 天空新宇侠',replace(replace('“元素－英雄 新宇侠”＋“新空间人・天空蜂鸟”\r\n仅限我方场上的上述卡牌返回至持有者牌组的场合，可从额外牌组特殊召唤（不需要“融合”）。我方LP比对手少的场合，此卡的攻击力上升相当于该差额数值。结束阶段时此卡返回至持有者的额外牌组。','\r',char(13)),'\n',char(10)),'返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11508758,'变异先导者','①：对手场上存在有２只或以上怪兽的场合，此卡的攻击宣言时，可以对手场上的１只表侧攻击表示怪兽为对象发动。直至战斗阶段结束时，获得该对手的１只表侧攻击表示怪兽之控制权。此回合，对象怪兽不可进行直接攻击但攻击可能的场合，挑选１只对手怪兽作为攻击对象，并进行伤害计算。','获得控制权','请选择攻击对象','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11510448,'十二兽 寅炮',replace(replace('等级4怪兽×3\r\n“十二兽 寅炮”1回合1次，也可重叠在同名卡以外的、自己场上的“十二兽”怪兽上面来超量召唤。\r\n①：此卡的攻击力・守备力分别上升此卡持有的超量素材中“十二兽”怪兽的相应数值。\r\n②：1回合1次，去除此卡的1个超量素材，以自己场上的1只超量怪兽和自己墓地的1只“十二兽”怪兽为对象可以发动。将该“十二兽”怪兽作为该超量怪兽的超量素材。','\r',char(13)),'\n',char(10)),'是否在「十二兽」怪兽上面重叠来超量召唤？','补充超量素材','请选择1只超量怪兽','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11516241,'刚鬼 力道食人魔',replace(replace('战士族怪兽2只以上\r\n此卡名的③效果1回合仅可使用1次。①：此卡的攻击力上升相当于自己场上此卡以外的连接怪兽连接标记合计×200的数值。②：连接召唤的此卡不受其他卡的效果影响。③：解放自己场上的1只“刚鬼”连接怪兽，以场上的卡为对象可以发动，数量最多为该连接标记的数量。将该卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11522479,'燃烧拳斗士 上钩拳手',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将“燃烧拳斗士 上钩拳手”以外的１只“燃烧拳斗士”怪兽或１张“反击”反击陷阱卡加入手牌。\r\n②：此卡因效果被送至墓地的情况下，可从以下效果中选择１个发动。\r\n●从自己的墓地将“燃烧拳斗士 上钩拳手”以外的１只“燃烧拳斗士”怪兽特殊召唤。\r\n●从自己的墓地将１张“反击”反击陷阱卡放置在自己场上。','\r',char(13)),'\n',char(10)),'','从墓地特殊召唤怪兽','从墓地放置反击陷阱','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11522979,'混沌编号69 徽章死神 混盾徽',replace(replace('等级5怪兽×4\r\n①：对手怪兽攻击宣言时可以发动。将对手场上的卡全部破坏。\r\n②：此卡持有“编号69 徽章神 盾徽”作为超量素材的情况下，获得以下效果。\r\n●1回合1次，去除此卡的1个超量素材，以对手场上的1只超量怪兽为对象可以发动。直至结束阶段为止，此卡的攻击力上升该怪兽原本攻击力的数值，此卡获得与该怪兽原本卡名・效果相同的卡名・效果。','\r',char(13)),'\n',char(10)),'破坏','获得效果','复制效果结束','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11548522,'迷犬玛隆','①：此卡被送至墓地的情况下发动。将此卡放回牌组。','返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11549357,'磁石战士伽玛','以阿尔法、贝塔、伽玛变形合体。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11556339,'灵兽的连契','①：将场上的怪兽破坏，数量最多为自己场上“灵兽”怪兽的数量。','怪兽破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11587414,'真太阳神',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：作为此卡发动时的效果处理，将“真太阳神”之外的、１只“拉之翼神龙”或１张记载有该卡名的卡从牌组加入手牌。\r\n②：“拉之翼神龙”以外的被特殊召唤的怪兽在该回合不可攻击。\r\n③：１回合１次，在自己的主要阶段可以发动。将此卡或牌组的１只“拉之翼神龙－不死鸟”送至墓地。然后，挑选自己场上的１只“拉之翼神龙”送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11590299,'哆啦哆啦',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：此卡召唤的情况下可以发动。从牌组将１只等级４以下的龙族・炎属性怪兽加入手牌。\r\n②：１回合１次，在自己的主要阶段可以发动。翻开自己牌组最上面的卡。所翻开的卡是龙族・炎属性怪兽的情况下，将该怪兽送至墓地，此卡的攻击力上升相当于自己场上的“哆啦哆啦”的数量×１０００的数值。不是的情况下，将所翻开的卡放回牌组最下面。','\r',char(13)),'\n',char(10)),'检索','翻卡顶','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11593137,'混沌的落穴','可支付２０００LP发动。使光属性或暗属性怪兽的召唤、反转召唤、特殊召唤无效并从游戏中除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11596936,'失控能量','可向对手展示手牌的１张“核成之钢核”并发动。破坏所有被盖牌在对手场上的魔法、陷阱卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11609969,'DD 魔导贤者开普勒',replace(replace('←10 【灵摆】 10→\r\n①：自己仅可灵摆召唤“DD”怪兽。此效果不会被无效化。\n②：在自己的准备阶段发动。此卡的灵摆刻度下降2（最低下降至1）。然后，将自己场上等级在此卡灵摆刻度数值以上的“DD”怪兽以外的怪兽全部破坏。\r\n【怪兽效果】\r\n此卡名的怪兽效果1回合仅可使用1次。\n①：此卡召唤・特殊召唤的情况下，可从以下效果中选择1个发动。\n●以自己场上1张其他的“DD”卡为对象可以发动。将该卡放回手牌。\n●从牌组将1张“契约书”卡加入手牌。','\r',char(13)),'\n',char(10)),'自己场上1张「DD」卡回到手牌','自己牌组1张「契约书」卡加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11613567,'黑羽－漆黑的艾尔芬','我方场上存在有冠有“黑羽”之名怪兽的场合，此卡可无须释放进行召唤。此卡召唤成功时，可选择对手场上的１只怪兽并变更其表示形式。','不用解放作召唤','改变表示形式','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11637481,'超级运动员自由攻手',replace(replace('按此卡名的方法①进行的特殊召唤在１个回合中仅可进行１次，此卡名的效果②在１个回合中仅可使用１次。\r\n①：此卡可在将自己场上的１只“超级运动员自由攻手”以外的“超级运动员”怪兽放回手牌后，从手牌特殊召唤。\r\n②：在对手的主要阶段可以发动。将手牌中１只等级５以上的“超级运动员”怪兽放回牌组，从牌组特殊召唤１只与该怪兽卡名不同的“超级运动员”怪兽。然后，将场上的此卡放回持有者的手牌中。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11642993,'超元特防队 理序世界',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：为发动自己场上的“超元特防队”怪兽的效果而要将手牌除外的情况下，作为代替可从牌组将1张“超元特防队 理序世界”以外的“超元特防队”卡送至墓地。\r\n②：其他卡被除外的情况下，以对手场上・墓地的1张卡为对象可以发动。将该卡除外。然后，可将自己场上的1只“超元特防队”怪兽的位置移动至自己的其他主要怪兽区域。','\r',char(13)),'\n',char(10)),'','除外','是否要移动位置？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11646785,'超级量子机兽 天翔衔尾蛇',replace(replace('等级4怪兽×2\r\n①：没有超量素材的此卡不可攻击。\r\n②：1回合1次，去除此卡的1个超量素材，以场上1只其他的表侧表示怪兽为对象可以发动（此卡持有“超级量子士 绿层”作为超量素材的情况下，此效果在对手回合中也可以发动）。将该怪兽改成里侧守备表示。\r\n③：1回合1次，在自己的主要阶段可以发动。从自己手牌・场上（表侧表示）将1只“超级量子士”怪兽作为此卡的超量素材。','\r',char(13)),'\n',char(10)),'里侧守备表示','超量素材','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11654067,'火焰驱逐',replace(replace('此卡名的卡１回合仅可发动１张。\r\n \r\n①：从牌组将１只炎族怪兽送至墓地。以此效果将“火山性”怪兽送至墓地的情况下，进而可从以下效果中挑选１个适用。\r\n●给予对手相当于其等级×１００的伤害。\r\n●将１只“炸弹衍生物”（炎族・炎・星１・攻／守１０００）特殊召唤至对手场上。此衍生物被破坏时，其控制者受到５００伤害。','\r',char(13)),'\n',char(10)),'给与对手伤害','特殊召唤衍生物','什么都不做','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11654068,'炸弹衍生物','将被以“火山性骑兵”等的效果特殊召唤。此衍生物被破坏时，其控制者受到５００伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11662742,'双生天使',replace(replace('①：上级召唤天使族、光属性怪兽的场合，此卡当作２只怪兽解放。\r\n②：此卡不会因战斗被破坏。\r\n③：我方因战斗、效果受到伤害的场合发动。破坏场上表侧表示的此卡。','\r',char(13)),'\n',char(10)),'自坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11674673,'电子界女巫',replace(replace('电子界族怪兽2只\r\n此卡名的①②效果1回合仅可各使用1次。①：怪兽被特殊召唤至此卡连接端的情况下，将自己墓地的1张魔法卡除外可以发动。从牌组将1只电子界族仪式怪兽和1张“电脑网仪式”加入手牌。②：在此卡的①效果发动过的回合的自己主要阶段，以自己墓地的1只等级4以下的电子界族怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'牌组检索','墓地苏生','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11677278,'迷拟宝箱鬼・铠甲',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己的主要阶段可以发动。从手牌将此卡以里侧守备表示特殊召唤至对手场上。对手场上存在怪兽的情况下，作为代替也可以表侧表示特殊召唤至自己场上。\r\n②：此卡在主要阶段反转的情况下发动。分别适用以下效果。\r\n●此回合中，“迷拟宝箱鬼”怪兽不会因战斗被破坏。\r\n●将此卡的控制权转移给对手。','\r',char(13)),'\n',char(10)),'反转效果','特殊召唤','在自己场上特殊召唤','在对手场上特殊召唤','','','','','','','','','','','','');
INSERT INTO texts VALUES(11678191,'守护灵 爱琳','１回合１次，可在我方的主要阶段时，将此卡作为装备卡装备至我方的“不屈斗士 磊磊”上，或者解除装备状态以表侧攻击表示特殊召唤此卡。以此效果变为装备卡的场合，装备怪兽在１个回合中可有１次机会变更表示形式。（１只怪兽最多只可装备１张联合。装备怪兽因战斗而被破坏的场合，破坏此卡来代替。）','装备','解除装备状态表侧攻击表示特殊召唤','改变装备怪兽的表示形式','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11682713,'森罗的保镳 刀叶',replace(replace('①：此卡因战斗破坏对手怪兽并送入墓地时可发动。翻阅我方牌组最上方的卡牌，该卡是植物族怪兽的场合，将该怪兽送入墓地。不是的场合，将该卡牌返回至牌组的最下方。\r\n②：牌组的此卡因效果被翻阅并送入墓地的场合可发动。墓地的此卡加入手牌。','\r',char(13)),'\n',char(10)),'翻开牌组','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11685347,'连爆魔人','魔法、陷阱卡产生连锁的场合，给予对方生命５００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11688916,'音服和弦・普莉莫娅',replace(replace('←0 【灵摆】 0→\r\n①：自己将怪兽灵摆召唤时，以自己的灵摆区域的1张“音服和弦”卡为对象可以发动。将该卡放回手牌。\r\n【怪兽效果】\r\n此卡名的①③怪兽效果1回合仅可各使用1次。\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将“音服和弦・普莉莫娅”以外的1张“音服和弦”卡加入手牌。\n②：只要灵摆刻度为奇数和偶数的“音服和弦”卡皆存在于自己的灵摆区域，自己发动的“音服和弦”卡的效果就不会被无效化。\n③：自己将“音服和弦”怪兽连接召唤的情况下可以发动。从自己额外牌组（表侧）・墓地将1张“音服和弦”卡加入手牌。','\r',char(13)),'\n',char(10)),'回到手牌','检索效果','回收效果','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11699941,'机偶蛤蟆油','此卡名的卡１回合仅可发动１张。①：以自己墓地的１只“机偶”怪兽为对象可以发动此卡。将该怪兽特殊召唤，装备此卡。②：１回合１次，自己场上表侧表示的“机偶”怪兽的表示形式被变更的情况下发动。装备怪兽的攻击力・守备力上升５００。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11705261,'超量转换战术','①：“超量转换战术”在自己场上仅可有１张以表侧表示形式存在。②：“希望皇霍普”怪兽被超量召唤至自己场上时，支付５００LP可以发动。自己从牌组抽１张。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11711438,'战华史略－三顾礼迎',replace(replace('此卡发动后将在自己的第2次准备阶段被送至墓地。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己的主要阶段，自己将“战华”怪兽召唤・特殊召唤的情况下，以该1只怪兽为对象可以发动。从牌组将1只卡名与该怪兽不同的“战华”怪兽加入手牌。\r\n②：此卡从魔法与陷阱区域被送至墓地的情况下可以发动。从手牌将1只“战华”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','牌组检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11714098,'３万年的白龟','活了３万年的巨大乌龟。守备力极高。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11722335,'异虫杰克斯','此卡召唤成功时可发动。从牌组将１只冠有“异虫”之名的爬虫类族怪兽送入墓地。我方场上存在有“异虫亚冈”的场合，此卡不会因战斗被破坏。','送至墓地','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11738489,'到临电子界＠伊格尼斯者',replace(replace('属性不同的怪兽3只以上\r\n①：“到临电子界＠伊格尼斯者”在自己场上仅可有1只以表侧表示存在。②：此卡原本的攻击力变为相当于作为此卡连接素材的怪兽数量×1000的数值。③：此卡不受其他卡的效果影响。④：1回合1次，以场上此卡以外的1只怪兽为对象可以发动。将该怪兽破坏，将1只“＠伊格尼斯者衍生物”（电子界族・暗・星1・攻/守0）特殊召唤至此卡连接端的自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11738490,'＠伊格尼斯者衍生物','由「到临电子界＠伊格尼斯者」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11741041,'雷瓶','每次我方场上的怪兽进行攻击宣言，放置１个雷计数物在此卡。可将放置了４个或以上雷计数物的此卡送入墓地并发动。破坏对手场上的所有怪兽。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11743119,'同盟骑士','取得对手场上处于怪兽状态的联合怪兽的控制权，最多装备１张至此卡上。装备至此卡上的联合怪兽不可以自身效果恢复为怪兽状态。','装备','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11747708,'孢子',replace(replace('此卡名的效果在决斗中仅可使用1次。\r\n①：此卡存在于墓地的情况下，从自己墓地将1只其他的植物族怪兽除外可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡的等级上升相当于为发动此效果而除外的怪兽的等级数值。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11755663,'恐龙摔跤手・武术崇高龙',replace(replace('①：在自己・对手回合中，自己的“恐龙摔跤手”怪兽与攻击力在其攻击力以上的怪兽进行战斗的伤害计算时，从手牌将此卡送至墓地可以发动。该自己的怪兽不会因该战斗被破坏，在该伤害步骤结束后结束战斗阶段。\r\n②：在此卡为发动此卡的效果而被送至墓地的回合的结束阶段，对手场上的怪兽数量多于自己场上的怪兽的情况下可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11759079,'双天脚之鸿鹄',replace(replace('此卡名的效果①②在1个回合中仅可各使用1次。\r\n①：在自己场上“双天脚之鸿鹄”以外的表侧表示的“双天”怪兽在对手回合中因战斗或效果被破坏的情况下可以发动。从手牌中特殊召唤此卡。然后，可以适用以下效果。\r\n●挑选自己场上的1只“双天”怪兽破坏，从额外牌组特殊召唤1只“双天”融合怪兽。\r\n②：在此卡召唤或特殊召唤成功的情况下可以发动。将牌组中的1张“双天”陷阱卡加入手牌。','\r',char(13)),'\n',char(10)),'从手牌特殊召唤','「双天」陷阱卡加入手牌','是否要把怪兽破坏并特殊召唤融合怪兽？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11760174,'言语道断侍','１回合１次，支付８００LP可以发动。此回合，双方不可发动魔法・陷阱卡的效果。','发动限制','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11761845,'塔瓦弯刀恶魔','那对塔瓦弯刀即使是恶魔族也只能由被允许的剑术高手所持有。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11765832,'共命之翼 迦楼拉',replace(replace('种族・属性相同、卡名不同的怪兽×２\r\n此卡名的②效果１回合仅可使用１次。\r\n①：因此卡的战斗对对手造成的战斗伤害变为两倍。\r\n②：此卡被送至墓地的情况下可以发动。自己抽１张。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11790356,'破戒蛮龙－毁灭龙',replace(replace('协调＋协调以外的怪兽１只或以上\r\n①：只要此卡以表侧表示存在，对手场上的怪兽变成龙族。\r\n②：我方场上不存在有“毁灭剑士”怪兽的场合，１回合１次，可以我方墓地的１只“毁灭剑士”为对象发动。特殊召唤该怪兽。\r\n③：对手回合仅１次，可以我方场上的１只“毁灭剑士”怪兽为对象发动。我方墓地的１只“破坏剑”怪兽被视为装备卡装备对象怪兽。','\r',char(13)),'\n',char(10)),'特殊召唤','装备','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11793047,'戈耳工之蛋','蛇发女戈耳工所产下的蛋，据说会孵化出映入其巨眼中的事物。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11801343,'垃圾收集员',replace(replace('此卡牌名的效果１回合只可使用１次。\r\n①：可以我方场上１只除此卡以外的电子界族怪兽为对象发动。将该怪兽返回至持有者手牌，并从牌组特殊召唤１只与返回至手牌怪兽相同等级但不同卡牌名的电子界族怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11802691,'查理史诗',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：将手牌的１张“圣剑”装备魔法卡出示给对手，从手牌・牌组将１只“焰圣骑士”怪兽特殊召唤。然后，将所出示的卡装备于该怪兽，或送至墓地。\r\n②：将墓地的此卡除外，以自己场上的１只“焰圣骑士帝－查理”为对象可以发动。从手牌・牌组挑选１只“圣骑士”怪兽，视为攻击力上升５００的装备魔法卡，装备于对象怪兽。','\r',char(13)),'\n',char(10)),'','','给那只怪兽装备','送至墓地','','','','','','','','','','','','');
INSERT INTO texts VALUES(11808215,'骰子地牢',replace(replace('①：作为此卡发动时的效果处理，可从牌组将１张“次元骰子”加入手牌。\r\n②：自己・对手的战斗阶段开始时可以发动。双方各摇１次骰子，自身场上的所有怪兽的攻击力直至回合结束时为止，适用摇出的数字的效果。\r\n●１：下降１０００。\r\n●２：上升１０００。\r\n●３：下降５００。\r\n●４：上升５００。\r\n●５：改成一半。\r\n●６：变为两倍。','\r',char(13)),'\n',char(10)),'是否从牌组把1张「次元骰子」加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11813722,'神龙之鳞','我方场上有冠有“大植然”之名的怪兽存在的场合可发动。此回合，对手不可发动陷阱卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11813953,'巨大安格斯','非常凶暴的猛兽，如同发狂般地不断肆虐。据说不曾有人看到它温驯的模样。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11819473,'秘仪读牌',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：掷1次硬币，根据掷出的正反，适用以下效果。自己的场地区域存在“光之结界”的情况下，不掷硬币而改为从正反的效果中择一适用。\r\n●正面：从牌组将“秘仪读牌”以外的、1张拥有掷硬币效果的卡加入手牌。\r\n●反面：对手从自身牌组挑选1张卡加入手牌。\r\n②：将墓地的此卡除外可以发动。进行手牌的1只“秘仪之力”怪兽的召唤。','\r',char(13)),'\n',char(10)),'投掷硬币','召唤','表：从牌组把持有进行投掷硬币效果的卡加入手牌','里：对手从自身牌组选1张卡加入手牌','','','','','','','','','','','','');
INSERT INTO texts VALUES(11819616,'椿姬媞泰妮亚','①：以场上的卡为对象的魔法・陷阱・怪兽的效果发动时，解放自己场上的1只表侧表示的植物族怪兽可以发动。将该发动无效并破坏。','发动无效并破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11825276,'戎之忍者－冥禅',replace(replace('种族不同的“忍者”怪兽×２\r\n此卡仅可以融合召唤及以下方法从额外牌组特殊召唤。\r\n●解放自己场上的上述卡的情况下，可从额外牌组特殊召唤。\r\n此卡名的③效果１回合仅可使用１次。\r\n①：自己的“忍者”怪兽可直接攻击。\r\n②：只要自己场上有里侧守备表示怪兽存在，此卡不会成为攻击对象。\r\n③：对手发动效果时可以发动。从牌组将１只“忍者”怪兽以表侧守备表示或里侧守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11827244,'圆融结合魔术',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：将自己场上・墓地的怪兽作为融合素材除外，将1只魔法师族融合怪兽融合召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11830996,'上古绿叶','①：当我方LP在９０００点以上的场合，可支付２０００点LP来发动此卡。我方从牌组抽取２张卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11834972,'岩浆炎・枪手','此卡召唤成功时，我方墓地存在有除“岩浆炎・枪手”以外的冠有“岩浆炎”之名怪兽的场合，可从我方牌组上方最多将５张卡牌送入墓地并发动。此卡的攻击力上升为了发动此效果而送入墓地的冠有“岩浆炎”之名怪兽的数量×２００点。','攻击上升','请选择送至墓地的数量','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11845050,'右手鲨',replace(replace('此卡名的①②③效果1回合仅可各使用1次。①：此卡召唤成功时可以发动。从牌组将1只“左手鲨”加入手牌。②：此卡存在于墓地，自己场上不存在怪兽的情况下可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡离开场上的情况下，将其除外。③：以包括场上的此卡、且仅以水属性怪兽作为素材超量召唤的怪兽获得以下效果。\r\n●此卡不会因战斗被破坏。','\r',char(13)),'\n',char(10)),'','','「右手鲨」效果适用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11851647,'排邱比特','此卡名的①②效果1回合仅可各使用1次。①：从自己的牌组上面将最多3张卡送至墓地可以发动。此卡的等级直至回合结束时为止，上升相当于为发动此效果送至墓地的卡数量的数值。②：场上的此卡因对手被破坏并被送至墓地的情况下发动。自己恢复1500LP。','','','请选择要送至墓地的数量','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11852093,'DDD 圣贤王阿尔弗雷德',replace(replace('“DD”怪兽×2\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己的主要阶段可以发动。将自己手牌・场上・除外状态的怪兽作为融合素材放回牌组，将1只“DDD”融合怪兽融合召唤。\r\n②：此卡被除外的情况下，以自己场上的“DDD”怪兽数量为上限，以自己墓地・除外状态的“契约书”永续魔法・永续陷阱卡为对象可以发动。将该卡以表侧表示放在自己场上。','\r',char(13)),'\n',char(10)),'融合召唤','表侧表示放置','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11868731,'魔幻甜点・玛德琳魔女',replace(replace('①：此卡召唤・反转召唤时可以发动。从牌组将１只“魔幻甜点”怪兽加入手牌。\r\n②：此卡被对手破坏并被送至墓地的情况下发动。将此卡放回牌组。','\r',char(13)),'\n',char(10)),'返回牌组','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11868825,'格布林秘药','①：自己恢复６００LP。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11877465,'禁咒仪・心灵女食人魔','以“咒仪”仪式魔法卡降临。①：此卡仪式召唤成功的情况下，以双方墓地合计最多５张卡为对象发动。将该卡放回持有者的牌组。','返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11881272,'至爱英雄','仅可装备于等级5以上的“-英雄”怪兽。此卡名的②效果1回合仅可使用1次。①：自己的场地区域有卡存在的情况下，装备怪兽的攻击力上升相当于原本守备力的数值，不会成为对手效果的对象。②：自己・对手的战斗阶段开始时可以发动。从自己的手牌・牌组挑选1张场地魔法卡发动。③：以装备怪兽的攻击破坏对手怪兽时，将此卡送至墓地可以发动。该攻击怪兽可继续攻击仅1次。','','','请选择要发动的场地魔法卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11895663,'艾米・雷盟',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：用抽牌以外的方法将此卡加入手牌的情况下，将此卡出示给对手，以场上的1张卡为对象可以发动。将该卡破坏，从手牌将1只雷族怪兽特殊召唤。此回合，自己不可从手牌以外的地方特殊召唤效果怪兽。\r\n②：此卡存在于怪兽区域的状态下，此卡以外的卡因效果被破坏的情况下可以发动。从牌组将1张“雷盟”陷阱卡加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','检索效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11901678,'黑恶魔龙','“恶魔的召唤”＋“真红眼黑龙”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11908584,'守护龙之核醒','此卡名的①效果1回合仅可使用1次。①：从手牌将1只效果怪兽送至墓地可以发动。从自己的手牌・牌组・墓地挑选1只等级4以下的龙族通常怪兽以守备表示特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11911336,'大轮之魔导书',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从自己牌组・墓地・除外状态将4只“灵使”怪兽加入手牌（同属性最多1只）。然后，挑选自己的2张手牌放回牌组。\r\n②：将墓地的此卡除外可以发动。将自己手牌・场上的“灵使”、“凭依装着”怪兽作为融合素材，将1只融合怪兽融合召唤。该融合召唤成功时，对手不可发动魔法・陷阱・怪兽的效果。','\r',char(13)),'\n',char(10)),'发动','融合召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11913700,'简易新宇空间','仅可装备于以“元素－英雄 新宇侠”为融合素材的融合怪兽。①：装备怪兽在结束阶段，可以不发动放回额外牌组的效果。②：因装备怪兽从场上离开导致此卡被破坏的情况下可以发动。从自己的手牌・牌组・墓地挑选１只“元素－英雄 新宇侠”特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11925569,'狩猎本能','可在对手场上有怪兽特殊召唤时发动此卡。从手牌特殊召唤１只恐龙族怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11954712,'飞牙鲨','此卡攻击了守备表示怪兽时，若其攻击力超过守备力，给予对手生命相当于该差值的战斗伤害。此卡给予对手生命战斗伤害的战斗阶段结束时，直至下一个我方准备阶段，将此卡从游戏中除外。','除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11958188,'武斗神器－真经津','①：我方场上的“武斗神”怪兽因与对手怪兽的战斗被破坏并送入我方墓地时，可将此卡从手牌送入墓地并发动。破坏该对手怪兽。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11961740,'时光胶囊','①：从牌组挑选1张卡以里侧表示除外，此卡持续留在场上。②：此卡发动后第2次自己的准备阶段时破坏此卡，将以此卡①效果除外的卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11962031,'火焰转生炎兽',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将“火焰转生炎兽”以外的、１只等级４以下的“转生炎兽”怪兽加入手牌。此效果发动后，直至回合结束时为止，自己仅可特殊召唤炎属性怪兽。\r\n②：在自己的电子界族怪兽进行战斗的伤害步骤开始时，将墓地的此卡除外可以发动。将该自己的怪兽破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11969228,'龙骑兵团骑士－罗慕路斯',replace(replace('衍生物以外的龙族・鸟兽族怪兽2只\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡连接召唤的情况下可以发动。从牌组将1张“龙骑兵团”魔法・陷阱卡或“龙之溪谷”加入手牌。\r\n②：有龙族怪兽被从额外牌组被特殊召唤至此卡连接端的情况下可以发动。从手牌将1只龙族・鸟兽族怪兽以守备表示特殊召唤。以此效果特殊召唤的怪兽在此回合，效果无效化且不可作为连接素材。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11975962,'抹杀之圣刻印','①：解放自己场上的１只“圣刻”怪兽，以对手场上的１张卡为对象可以发动。将该对手的卡除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(11987744,'忍犬奇狗','精通忍术的犬忍者。历经严峻的修行，能够使出拟人化之忍术。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12014404,'我我我枪手',replace(replace('等级4怪兽×2\r\n①：1回合1次，去除此卡的1个超量素材可以发动。根据此卡的表示形式适用以下效果。\r\n●攻击表示：此回合，此卡攻击对手怪兽的伤害步骤期间，此卡的攻击力上升1000，该对手怪兽的攻击力下降500。\r\n●守备表示：给予对手800伤害。','\r',char(13)),'\n',char(10)),'攻击变换','伤害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12015000,'新生代化石龙 骷髅剑角龙',replace(replace('岩石族怪兽＋对手墓地中等级4以下的怪兽\r\n此卡仅可通过“化石融合”的效果从额外牌组中特殊召唤。\r\n此卡名的效果②在1个回合中仅可使用1次。\r\n①：此卡攻击了守备表示的怪兽时，将对其造成战斗伤害，数值为此卡攻击力超出该怪兽守备力的部分。\r\n②：除外墓地的此卡后可以发动。将牌组中的1张“化石融合”卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12018201,'岩浆炎谷爆烈王',replace(replace('协调＋１只以上协调以外的炎属性怪兽\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：对手发动手牌・场上的怪兽的效果时可以发动。将该怪兽破坏，给予对手１０００伤害。\r\n②：同步召唤的此卡被对手破坏的情况下可以发动。从自己的墓地挑选同步怪兽以外的最多３只守备力２００的炎属性怪兽，以守备表示特殊召唤。以此效果特殊召唤的怪兽的效果无效化。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12021072,'大胆无敌',replace(replace('①：对手每次召唤、反转召唤、特殊召唤怪兽，我方回复３００LP。\r\n②：我方LP为１００００或以上的场合，我方的怪兽不会因战斗而被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12023931,'助瞄龙',replace(replace('“枪弹”怪兽2只\r\n此卡名的②效果1回合仅可使用1次。\r\n①：1回合1次，以场上1只其他的表侧表示怪兽为对象可以发动（应对此效果的发动，对手不可发动卡的效果）。该怪兽的攻击力・守备力上升500。\r\n②：连接召唤的此卡因战斗・效果被破坏并被送至墓地的情况下，以自己墓地1只其他的龙族怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12057781,'落空格布林','为了写出完美的“落空”文字，每日精益求精的格布林。它将一切都倾注在一笔一划当中。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12058741,'蛇眼・怀特巴棋',replace(replace('此卡名以①方法的特殊召唤１回合仅可进行１次，且②效果１回合仅可使用１次。\r\n①：自己场上存在炎属性怪兽的情况下，此卡可从手牌中特殊召唤。\r\n②：在对手回合中，将自己场上包含此卡在内的２张表侧表示卡送至墓地可以发动。从手牌・牌组将“蛇眼・怀特巴棋”以外的１只“蛇眼”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12061457,'灵魂剪刀',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡存在于墓地的状态下，场上的怪兽因战斗・效果被破坏并被送至墓地的情况下可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。\r\n②：此卡从墓地特殊召唤成功的情况下，以对手场上的１只怪兽为对象可以发动。将该怪兽破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12067160,'美丽的磁律机坏',replace(replace('效果怪兽2只以上\r\n自己不可将怪兽出到此卡的连接端。\r\n①：此卡连接端的怪兽不可攻击，该怪兽发动的效果无效化。\r\n②：此卡的攻击力上升此卡连接端的怪兽的原本攻击力的数值。\r\n③：此卡连接端不存在怪兽的情况下，此卡不会因战斗及怪兽的效果被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12071500,'黑暗呼唤','①：将自己手牌・墓地的怪兽作为融合素材除外，将1只仅可以“黑暗结合”的效果特殊召唤的融合怪兽，视为通过“黑暗结合”来融合召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12076263,'发条狗','我方主要阶段时可发动。直至回合结束时，此卡的等级上升２级，攻击力上升６００点。只要此卡以表侧表示存在于场上，此效果仅可使用１次。','等级攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12079734,'三角三型战机',replace(replace('①：此卡战斗破坏对手怪兽的情况下，从以下效果中选择1个发动。\r\n●以自己墓地的1只可装备于此卡的联合怪兽为对象发动。将该联合怪兽视为以其效果变成的装备魔法卡装备于此卡。\r\n●以自己场上的1只机械族・光属性怪兽为对象发动。将该自己的机械族・光属性怪兽放回牌组。然后，自己抽1张。','\r',char(13)),'\n',char(10)),'选择效果','同盟怪兽给此卡装备','回到牌组并抽牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12081875,'轰机雷龙',replace(replace('雷族怪兽2只以上\r\n此卡名的①效果1回合仅可使用1次。①：此卡是被连接召唤的情况下，从自己墓地的怪兽及被除外的自己的怪兽中，以1只“雷龙”怪兽为对象可以发动。适用记载于该怪兽、从手牌舍弃自身发动的效果。然后，将该怪兽放回牌组最上面或最下面。②：自己场上的雷族怪兽将被战斗・效果破坏的情况下，可将自己墓地的3张卡除外作为代替。','\r',char(13)),'\n',char(10)),'','回到牌组最上面','回到牌组最下面','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12097275,'刚鬼 抱熊','此卡名的①②效果1回合仅可各使用1次。①：此卡召唤或以“刚鬼”卡的效果特殊召唤成功的情况下，以对手场上的1只表侧表示怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止变为原本攻击力的一半。②：此卡从场上被送至墓地的情况下可以发动。从牌组将1张“刚鬼 抱熊”以外的“刚鬼”卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12117532,'逐渐龟裂之斧',replace(replace('可以场上１只表侧表示的怪兽为对象发动此卡。\r\n①：只要此卡存在于魔法与陷阱区域域，对象怪兽的攻击力每次在我方的准备阶段下降５００。当该怪兽被破坏时破坏此卡。','\r',char(13)),'\n',char(10)),'攻击下降','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12143771,'流离的民众','虽然一直承受着苦难，但在心中发誓终有一天必会发动革命。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12146024,'电击蜗牛','会吐出粘液，趁敌人动弹不得的时候以电击攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12148078,'疾行机人轮盘','此卡名的卡1回合仅可发动1张。①：舍弃1张手牌可以发动。掷1次骰子。为使合计等级与掷出的数字相等，从手牌・牌组将最多2只“疾行机人”怪兽的效果无效并特殊召唤。无法特殊召唤的情况下，自己将失去相当于掷出数字×500的LP。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12152769,'乞丐格布林','①：此卡对对手造成战斗伤害的场合发动此卡。对手可将１张手牌转交给此卡的控制者而令此效果无效。未转交的场合，我方将牌组中的１张“格布林”卡牌加入到手牌中。','手牌转移','是否将手牌交给对手？','请选择交给对手的手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12157563,'禁断仪式术',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：为使合计等级与仪式召唤的怪兽相等，将自己墓地的怪兽除外，从自己墓地将1只仪式怪兽仪式召唤。以此效果特殊召唤的怪兽将在结束阶段被破坏。\r\n②：将墓地的此卡除外可以发动。此回合，自己要仪式召唤的情况下仅1次，作为解放的代替可将自己墓地的仪式怪兽除外。','\r',char(13)),'\n',char(10)),'发动','增加墓地仪式素材','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12160911,'灾厄之像','此卡因对手的卡牌效果从手牌被送入墓地时，给予对手生命２０００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12163590,'龙女仆・希幽媞露',replace(replace('此卡名的①③效果1回合仅可各使用1次。\r\n①：从手牌将此卡舍弃可以发动。将“龙女仆・希幽媞露”以外的、自己墓地・除外状态的1只“龙女仆”怪兽特殊召唤。\r\n②：只要此卡存在于怪兽区域，自己场上的龙族融合怪兽不会因对手的效果被破坏。\r\n③：在自己・对手的战斗阶段结束时可以发动。将此卡放回手牌，从手牌将1只等级4以下的“龙女仆”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','回到手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12171659,'天空使者 杰拉迪亚斯','可将此卡从手牌舍弃至墓地并发动。从牌组将１张“天空的圣域”加入手牌。此外，场上不存在有“天空的圣域”的场合，此卡被破坏。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12172567,'心智易位凯瑟琳',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：以对手场上的1只表侧表示怪兽为对象可以发动。该怪兽和此卡的控制权交换。\r\n②：同步召唤的此卡被送至墓地的情况下，以自己及对手场上的表侧表示怪兽各1只为对象可以发动。该2只怪兽的控制权交换。','\r',char(13)),'\n',char(10)),'控制权交换','控制权交换','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12174035,'水压加农炮','仅限装备等级３以下的水属性怪兽。装备怪兽通过战斗破坏对手怪兽的场合，随机将对手１张手牌送入墓地。','送墓','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12181376,'三角狂欢电光','①：场上所有“神鹰女郎三姐妹”的攻击力直至回合结束时为止变为２７００。此回合，对手不可发动陷阱卡，对手场上陷阱卡的效果无效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12183332,'霰弹式洗牌','１回合１次，可支付３００LP发动。将我方或对手牌组洗牌。','洗牌','自己洗切牌组','对手洗切牌组','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12196873,'玄化诱饵龙',replace(replace('←1 【灵摆】 1→\r\n此卡牌名的灵摆效果１回合只可使用１次。\n①：我方怪兽被选择为攻击对象时，可从我方墓地的怪兽及被除外的我方怪兽中，以１只“玄化”怪兽为对象发动。将此卡除外，并以攻击表示特殊召唤对象怪兽。\r\n【怪兽效果】\r\n此卡牌名的①②怪兽效果１回合只可各使用１次。\n①：我方怪兽被选择为攻击对象时，可从我方墓地的怪兽及我方被除外的怪兽中，以１只“玄化”怪兽为对象发动。将场上的此卡除外，并以攻击表示特殊召唤对象怪兽。\n②：在此卡被除外的下一回合之准备阶段可发动。特殊召唤被除外的此卡。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12197223,'天雷之双风神 息那',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：自己场上存在风属性怪兽，且对手发动魔法・陷阱・怪兽的效果时可以发动。从手牌将此卡特殊召唤。然后，根据该对手的效果的种类，适用以下效果。\r\n●怪兽：将“天雷之双风神 息那”以外的场上的表侧表示怪兽全部放回手牌。\r\n●魔法・陷阱：将场上的魔法・陷阱卡全部放回手牌。\r\n②：此卡1回合仅1次，不会因战斗被破坏。','\r',char(13)),'\n',char(10)),'发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12197543,'剑之指挥',replace(replace('对手的抽牌阶段时，可在对手进行了通常抽牌时发动。双方确认抽取的卡牌，确认的卡牌是魔法、陷阱卡的场合，从以下效果中挑选１个并适用。\r\n●舍弃抽取的卡牌。\r\n●挑选对手场上的１张魔法、陷阱卡并破坏。','\r',char(13)),'\n',char(10)),'把抽到的卡丢弃。','选对手场上1张魔法·陷阱卡破坏。','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12206212,'神鹰女郎三姐妹','此卡不可通常召唤。以“万华镜－华丽的分身－”的效果可以特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12210097,'巳剑之磐境',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：对自己场上的“巳剑”仪式怪兽，对手不可将其作为被从额外牌组特殊召唤的怪兽的效果的对象。\r\n②：以“巳剑之磐境”以外的、自己墓地的4张“巳剑”卡为对象可以发动。将该卡放回牌组。对手场上存在怪兽的情况下，对手进而必须将自身场上的1只怪兽解放。','\r',char(13)),'\n',char(10)),'','回到牌组','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12213463,'白蔷薇龙',replace(replace('此卡名的①③效果1回合仅可各使用1次。\r\n①：自己场上存在龙族或植物族协调的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：此卡召唤时可以发动。从自己手牌・墓地将“白蔷薇龙”以外的1只“蔷薇龙”怪兽特殊召唤。\r\n③：此卡作为同步素材被送至墓地的情况下可以发动。从牌组将1只等级4以上的植物族怪兽送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12215894,'文具博格・基地','①：场上的“文具博格”怪兽的攻击力・守备力上升５００。②：１回合１次，在自己的主要阶段可以发动。将手牌任意数量的“文具博格”卡出示给对手，放回牌组洗牌。然后，自己依放回牌组的数量从牌组抽牌。③：将自己场上・墓地“文具博格・基地”以外的９种“文具博格”卡各１张除外可以发动。将对手的手牌・场上・墓地的所有卡放回持有者的牌组。','抽牌','对方卡返回牌组','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12216615,'核成的障壁','我方墓地存在有２张或以上“核成之钢核”的场合，对手怪兽的攻击宣言时可发动。破坏所有对手场上的攻击表示怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12219047,'魅影骑士团咒标枪',replace(replace('等级2怪兽×2\r\n此卡名的效果1回合仅可使用1次。\r\n①：去除此卡的1个超量素材，以对手场上的1只表侧表示怪兽为对象可以发动（此卡持有“魅影骑士团”卡作为超量素材的情况下，此效果在对手回合中也可以发动）。该怪兽直至回合结束时为止攻击力变为0，效果无效化。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12235475,'魔轰神亚森威尔','①：此卡进行战斗的该伤害计算时，可１次将１张手牌送入墓地并发动。此卡的攻击力仅在该伤害计算时上升６００。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12247206,'地狱的暴走召唤','①：对手场上存在表侧表示怪兽，且仅１只攻击力１５００以下的怪兽被特殊召唤至自己场上时可以发动。从自己的手牌・牌组・墓地尽可能地将该特殊召唤的怪兽的同名怪兽以攻击表示特殊召唤，对手挑选自身场上的１只表侧表示怪兽，从自身的手牌・牌组・墓地尽可能地将该怪兽的同名怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12253117,'世界的平定','场地魔法卡发动时可发动。此回合，场上的场地魔法卡的效果被无效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12255007,'娱乐伙伴 灯泡萤火虫',replace(replace('←5 【灵摆】 5→\r\n①：１回合１次，对手怪兽攻击宣言时，解放自己场上的１只“娱乐伙伴”怪兽可以发动。使该攻击无效，然后结束战斗阶段。\r\n【怪兽效果】\r\n①：只要此卡存在于怪兽区域，自己场上的“娱乐伙伴”怪兽或“异色眼”怪兽攻击的情况下，对手直至伤害步骤结束时为止不可发动魔法・陷阱卡。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12262393,'磁石战士德尔塔',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将1只等级4以下的“磁石战士”怪兽送至墓地。\r\n②：此卡被送至墓地的情况下，从自己墓地将除“磁石战士德尔塔”以外的3只等级4以下的“磁石战士”怪兽除外可以发动。从手牌・牌组将1只“磁石之战士 翔武机翁”无视召唤条件特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12266229,'混沌之幻像',replace(replace('以“混沌形态”降临\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：向对手出示手牌的此卡可以发动。从牌组将除仪式怪兽之外的、1只“黑魔导”或记载有该卡名的怪兽加入手牌。然后，挑选1张自己手牌放回牌组最上面。\r\n②：对手发动怪兽的效果时可以发动。将场上的此卡放回手牌，从自己墓地将1只“黑魔导”特殊召唤，将该发动的效果无效。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12275533,'机动要犀 铁犀三角龙','①：对手召唤、反转召唤、特殊召唤３只或以上怪兽成功的回合可发动。从手牌特殊召唤此卡。以此效果特殊召唤的此卡，不受其他卡牌效果的影响，每次双方的准备阶段守备力下降５００。此效果在对手回合也可发动。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12289247,'刻读阵魔术士',replace(replace('←8 【灵摆】 8→\r\n此卡名的灵摆效果１回合仅可使用１次。①：在自己的主要阶段可以发动。破坏此卡，从手牌・牌组挑选１只“时读的魔术师”，放在自己的灵摆区域或特殊召唤。\r\n【怪兽效果】\r\n①：自己场上的卡因战斗・效果被破坏的情况下可以发动。从手牌将此卡特殊召唤。然后，可从手牌将１只怪兽特殊召唤。②：将自己手牌・场上・墓地的“灵摆龙”、“超量龙”、“同步龙”、“结合龙”怪兽各１只和场上的此卡除外可以发动。将１只“霸王龙扎克”视为融合召唤从额外牌组特殊召唤。','\r',char(13)),'\n',char(10)),'此卡破坏','灵摆区域放置','特殊召唤','此卡从手牌特殊召唤','是否从手牌把怪兽特殊召唤？','融合召唤「霸王龙扎克」','请选择1只「时读的魔术师」','','','','','','','','','');
INSERT INTO texts VALUES(12292422,'标本阅览',replace(replace('此卡名的卡在1个回合中仅可发动1张。\r\n①：向对手出示手牌中的1张“化石融合”卡后可以发动。从手牌中将1只怪兽送至墓地，宣言1个种族与1个等级。对手查看自己的手牌与牌组，如果存在被宣言的种族与等级的怪兽，将其中1只送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12296376,'电力啄木鸟','此卡在１次战斗阶段中可攻击２次。与此卡进行过战斗的怪兽不可改变表示形式。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12298909,'物质龙','只要此卡以表侧表示存在于场上，给予LP伤害的效果变为回复LP效果。此外，破坏场上怪兽之魔法、陷阱、效果怪兽的效果发动时，可将１张手牌送入墓地并发动。使该发动无效并破坏。','破坏场上怪物的效果发动无效并破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12299841,'发条士兵','我方主要阶段时可发动。直至回合结束时，此卡的等级上升１级，攻击力上升４００点。只要此卡以表侧表示存在于场上，此效果仅可使用１次。','等级攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12307878,'召唤兽 普尔加托里奥',replace(replace('“召唤师 阿莱斯特”＋炎属性怪兽\r\n①：此卡的攻击力上升相当于对手场上卡的数量×２００的数值。②：此卡可攻击所有对手怪兽各１次，攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予战斗伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12324546,'漆黑的名马','仅限装备冠有“六武众”之名的怪兽。装备怪兽的攻击力、守备力上升２００点。装备怪兽被破坏的场合，破坏此卡作为代替。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12332865,'圣座天嗣 坐天使',replace(replace('此卡名的效果１回合仅可使用１次。\r\n①：原本的种族・属性为天使族・地属性的怪兽从自己的手牌・场上被送至墓地的情况下可以发动。从手牌将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12338068,'真魔兽 巨变神',replace(replace('此卡不可通常召唤。\r\n仅我方场上的所有怪兽释放的场合可特殊召唤。\r\n①：此卡的攻击力变成为特殊召唤此卡而释放之怪兽的原本攻击力合计数值。\r\n②：此卡攻击了守备表示怪兽的场合，给予相当于攻击力超过该守备力数值的战斗伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12369277,'超级量子士 蓝层',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤时可以发动。从牌组将“超级量子士 蓝层”以外的1张“超级量子”卡加入手牌。\r\n②：此卡被送至墓地的情况下，以自己墓地的最多3张“超级量子”卡为对象可以发动。将该卡放回牌组。','\r',char(13)),'\n',char(10)),'加入手牌','回到牌组','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12375297,'煌耀圣诗之狱神精',replace(replace('此卡名的②③效果1回合仅可各使用1次。\r\n①：自己从额外牌组仅可特殊召唤同步怪兽。\r\n②：在自己・对手的主要阶段，以自己中央的主要怪兽区域的1只怪兽为对象可以发动。该怪兽的等级直至回合结束时为止上升3。然后，可进行1只“耀圣”同步怪兽或“调狱神 朱诺拉”的同步召唤。\r\n③：此卡作为同步素材被送至墓地的情况下可以发动。从牌组将1张“耀圣”卡加入手牌。','\r',char(13)),'\n',char(10)),'等级改变','检索','是否同步召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12381100,'究极龙魔导师',replace(replace('“青眼究极龙”（或“青眼”怪兽×3）＋“混沌”仪式怪兽\r\n此卡仅可以融合召唤方式特殊召唤。\r\n①：对手发动效果时可以发动（此卡名的此效果应对魔法・陷阱・怪兽的效果1回合仅可各发动1次）。将该发动无效并破坏。\r\n②：表侧表示的此卡因对手从场上离开的情况下可以发动。从自己额外牌组・墓地将1只“青眼”怪兽或“混沌”仪式怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','无效对手怪兽','特召「青眼」怪兽或者「混沌」仪式怪兽','已对怪兽效果把「究极龙魔导师」的效果发动','已对魔法效果把「究极龙魔导师」的效果发动','已对陷阱效果把「究极龙魔导师」的效果发动','','','','','','','','','','');
INSERT INTO texts VALUES(12381101,'究极龙魔导师',replace(replace('“青眼究极龙”（或“青眼”怪兽×3）＋“混沌”仪式怪兽\r\n此卡仅可以融合召唤方式特殊召唤。\r\n①：对手发动效果时可以发动（此卡名的此效果应对魔法・陷阱・怪兽的效果1回合仅可各发动1次）。将该发动无效并破坏。\r\n②：表侧表示的此卡因对手从场上离开的情况下可以发动。从自己额外牌组・墓地将1只“青眼”怪兽或“混沌”仪式怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','无效对手怪兽','特召「青眼」怪兽或者「混沌」仪式怪兽','已对怪兽效果把「究极龙魔导师」的效果发动','已对魔法效果把「究极龙魔导师」的效果发动','已对陷阱效果把「究极龙魔导师」的效果发动','','','','','','','','','','');
INSERT INTO texts VALUES(12385638,'星际仙踪－尾声',replace(replace('①：只要此卡存在于魔法与陷阱区域，自己的“星际仙踪”怪兽战斗破坏的怪兽不会被送至墓地而是返回持有者的牌组。\r\n②：将墓地的此卡除外可以发动。此回合，自己因自己的“星际仙踪”怪兽的战斗将受到战斗伤害的情况下仅１次，自己依其数值恢复LP作为代替。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12397569,'神域 巴提斯蒂娜',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：在自己的主要阶段可以发动。从牌组将１只“提斯蒂娜”怪兽送至墓地。对手场上存在３张以上表侧表示卡的情况下，进而可从手牌・牌组将１只“结晶神 提斯蒂娜”特殊召唤。\r\n②：场地区域的此卡因对手的效果被破坏的情况下可以发动。从自己牌组・墓地将１只“提斯蒂娜”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','是否把1只「结晶神 提斯蒂娜」特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12398280,'胜利的引导者 弗蕾亚','我方场上有“胜利的引导者 弗蕾亚”以外的天使族怪兽以表侧表示存在的场合，此卡不可被选择作为攻击对象。只要此卡以表侧表示存在于我方场上，我方场上以表侧表示存在的天使族怪兽的攻击力、守备力上升４００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12408276,'星际仙踪－暗黑女郎',replace(replace('“星际仙踪－暗黑女郎”的①效果１回合仅可使用１次。\r\n①：将场上的此卡除外可以发动。从手牌将１只等级６以上的“星际仙踪”怪兽特殊召唤。此效果在对手回合中也可以发动。\r\n②：１回合１次，此卡以外的怪兽的效果发动时，支付１０００LP可以发动。将该发动无效并破坏。','\r',char(13)),'\n',char(10)),'从手牌把「星际仙踪」怪兽特殊召唤','发动无效并破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12421694,'闪刀姬－腕',replace(replace('地属性以外的“闪刀姬”怪兽1只\r\n自己1回合仅可特殊召唤1次“闪刀姬-腕”。①：此卡特殊召唤成功的情况下，以对手场上的1只表侧表示怪兽为对象可以发动。该怪兽直至对手回合结束时为止不可攻击。②：只要此卡存在于怪兽区域，自己每次发动“闪刀”魔法卡的效果，自己恢复100LP。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12423762,'我我我守卫',replace(replace('①：对手怪兽的直接攻击宣言时可以发动。从手牌将此卡特殊召唤。\r\n②：此卡被选择为攻击对象时，舍弃1张手牌可以发动。此卡不会因该战斗被破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','不被战破','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12435193,'核成龙',replace(replace('此卡的控制者每当到自己的结束阶段，从手牌将1张“核成之钢核”送至墓地，或向对手出示手牌的1只龙族怪兽，或将此卡破坏。\r\n①：只要此卡存在于怪兽区域，双方不可特殊召唤光・暗属性怪兽。','\r',char(13)),'\n',char(10)),'选择一张「核成之钢核」送至墓地','选择一只龙族怪物给对手观看','破坏「核成龙」','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12436646,'水蛇','它会用尾巴尾端的珠子施展催眠术，溺毙对手。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12444060,'古遗物之神智','此卡名的卡１回合仅可发动１张，发动此卡的回合中，自己无法进行战斗阶段。①：从牌组将１只“古遗物”怪兽特殊召唤。②：此卡被对手破坏的情况下，以场上的１张卡为对象可以发动。将该卡破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12450071,'代理・F・魔术师',replace(replace('效果怪兽2只\r\n此卡名的①②效果1回合仅可各使用1次。①：在自己的主要阶段可以发动。从自己场上将由融合怪兽卡决定的融合素材怪兽送至墓地，从额外牌组将1只该融合怪兽融合召唤。②：融合怪兽被融合召唤至此卡连接端的情况下可以发动。从手牌将1只攻击力1000以下的怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12451640,'前线观察员',replace(replace('①：在此卡召唤成功回合的结束阶段可发动。从牌组将１只地属性灵摆怪兽加入手牌。\r\n②：此卡召唤成功的场合，可在下一个我方回合的结束阶段，释放此卡并发动。从牌组将１只地属性怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12467005,'拦截十字军',replace(replace('①：此卡被送至墓地的情况下，可从以下效果中选择１个发动。\r\n●以对手场上的１只表侧表示怪兽为对象可以发动。将该对手的表侧表示怪兽改成里侧守备表示。\r\n●以对手场上的１张表侧表示魔法・陷阱卡为对象可以发动。将该对手的表侧表示魔法・陷阱卡放回手牌。此回合，对手不可发动以此效果放回手牌的卡及其同名卡。','\r',char(13)),'\n',char(10)),'选择效果发动','怪兽变成里侧守备表示','魔法·陷阱卡回到手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12469386,'再度盛开的大朵蔷薇','我方场上等级５或以上的植物族怪兽被破坏的场合，可从墓地特殊召唤此卡。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12470447,'邪恶的仪式','变更场上所有怪兽的表示形式。发动回合中，怪兽的表示形式不可进行变更。此卡仅可在准备阶段发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12472242,'蜈蚣兵','此卡可直接攻击对手玩家。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12482652,'扰乱怪之绿色','是人称不择手段捣乱的扰乱怪三人组的一员。据说只要三人到齐就会有什么发生。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12493482,'美德女武神','勇敢的光之天使。因为有着强烈的正义感，即使知晓会战败，也绝不逃避与邪恶对抗。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12496261,'龙骑兵团骑士－嗜毒魔枪',replace(replace('“龙骑兵团”协调＋协调以外的怪兽1只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡特殊召唤的情况下，以自己墓地的1只“龙骑兵团”怪兽为对象可以发动。将该怪兽视为装备魔法卡装备于此卡。\r\n②：此卡被送至墓地的情况下，以自己场上的1只“龙骑兵团”怪兽为对象可以发动。将此卡视为攻击力・守备力上升1000的装备魔法卡，装备于对象的自己的怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12500059,'晓天使 肯比',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：自己场上的怪兽，不存在的情况下或均为天使族怪兽的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：解放包含此卡在内的自己场上的任意数量天使族怪兽可以发动（发动此效果的回合中，自己仅可特殊召唤天使族怪兽）。从牌组将1只等级与所解放怪兽合计等级相同的天使族怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'此卡特殊召唤','从牌组特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12501230,'战斗机轮',replace(replace('协调＋协调以外的怪兽１只以上 \r\n①：场上的此卡１回合仅１次，不会因对手的效果被破坏。 \r\n②：在对手的战斗阶段１次，舍弃１张手牌可以发动。此卡的攻击力上升相当于自己场上其他怪兽的攻击力合计数值的一半。然后，在此卡上放１个计数物。此回合中，对手怪兽不可将其他怪兽选择为攻击对象。 \r\n③：放有计数物的此卡因战斗被破坏的情况下发动。将自己场上的怪兽全部破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12503902,'稀有钢铁化・魔法反射装甲','可选择场上１只机械族怪兽来发动此卡。只要此卡存在于场上，该机械族怪兽的攻击力上升５００点，令以该怪兽为对象的魔法卡效果无效１次。所选择怪兽离开场上时，破坏此卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12508268,'翼日驱动',replace(replace('此卡名的卡１回合仅可发动１张。①：以自己场上的１只“未来皇霍普”超量怪兽为对象可以发动。此回合，该自己的怪兽适用以下效果。\r\n●该怪兽可攻击所有对手怪兽各１次。\r\n●该怪兽与对手怪兽进行战斗的伤害步骤期间，该对手怪兽的效果无效化。\r\n●每次该怪兽战斗破坏对手怪兽，给予对手相当于该被破坏的怪兽原本攻击力的数值的伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12510878,'天空勇士新珀耳修斯',replace(replace('①：此卡可解放我方场上的１只“天空骑士珀耳修斯”，并从手牌特殊召唤。\r\n②：场上存在有“天空的圣域”，并且我方的LP高于对手的场合，此卡的攻击力、守备力上升该差值数值。\r\n③：此卡攻击守备表示怪兽的场合，给予相当于攻击力若超过其守备力数值的战斗伤害。\r\n④：此卡给予对手战斗伤害的场合发动。我方从牌组抽取１张卡牌。','\r',char(13)),'\n',char(10)),'抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12524259,'恣动机群指令・再奇动','此卡名的卡１回合仅可发动１张。①：以自己场上的１只机械族怪兽为对象可以发动。从手牌・牌组将１只可装备的机械族联合怪兽装备于该怪兽。以此效果装备的联合怪兽此回合不可特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12525049,'音响战士 吉伊他',replace(replace('←7 【灵摆】 7→\r\n此卡名的灵摆效果１回合仅可使用１次。①：舍弃１张手牌可以发动。从牌组将１只“音响战士 吉伊他”以外的“音响战士”怪兽特殊召唤。\r\n【怪兽效果】\r\n①：此卡召唤成功时，以自己墓地的１只“音响战士”怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12527118,'卡西莫拉尔',replace(replace('①：此卡召唤成功时，以对手场上的１只表侧表示怪兽为对象可以发动。该怪兽的攻击力上升相当于其原本攻击力的数值。已适用此效果的怪兽将在下个回合的结束阶段被破坏，对手将受到相当于其原本攻击力一半数值的伤害。\r\n②：在对手的战斗阶段开始时，解放通常召唤的此卡可以发动。此回合，对手怪兽不可直接攻击。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12533811,'宝贝虎龙',replace(replace('等级１怪兽×３\r\n在我方的主要阶段１，可以移除这张卡的１个超量素材，并选择我方场上１只等级１的怪兽发动。选择的怪兽可以直接攻击对手。','\r',char(13)),'\n',char(10)),'直接攻击','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12538374,'黄泉青蛙','①：此卡存在于墓地，且自己场上不存在“黄泉青蛙”的情况下，在自己的准备阶段可以发动（此效果在自己场上不存在魔法・陷阱卡的情况下才能发动和处理）。将此卡特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12541409,'永火镇压',replace(replace('此卡名的卡在1个回合中仅可发动1张。\r\n在自己的手牌数量为0的情况下，此卡在其放置的回合也可发动。\r\n①：自己场上有“永火”怪兽存在，且对手发动了怪兽的效果时可以发动。使该效果无效。然后，可以给对手该怪兽的等级×100的伤害。','\r',char(13)),'\n',char(10)),'','是否给与伤害？','适用「无限狱压制」的效果来发动','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12571621,'电脑堺獬－豸豸','此卡名的效果１回合仅可使用１次。①：在此卡存在于手牌中的情况下，以自己场上的１张“电脑堺”卡为对象可以发动。从牌组将１张种类（怪兽・魔法・陷阱）与该卡不同的“电脑堺”卡送至墓地，将此卡特殊召唤。在此回合的结束阶段，可从自己的墓地挑选１只“电脑堺獬－豸豸”以外的“电脑堺”怪兽加入手牌。此回合，自己仅可特殊召唤等级或阶级为３以上的怪兽。','从手牌特殊召唤','是否从墓地把怪兽加入手牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12580477,'雷击','①：将对手场上的怪兽全部破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12580478,'雷击','①：将对手场上的怪兽全部破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12580479,'雷击','①：将对手场上的怪兽全部破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12600382,'艾克佐迪亚的亡灵',replace(replace('此卡不可通常召唤。\r\n仅限以“与艾克佐迪亚的契约”的效果可特殊召唤。\r\n①：此卡不会因战斗及魔法、陷阱卡的效果被破坏。\r\n②：在我方准备阶段发动。此卡的攻击力上升５００。\r\n③：我方墓地不存在有“被封印的艾克佐迪亚”“被封印者的右腕”“被封印者的左腕”“被封印者的右足”“被封印者的左足”中的任何１张的场合，此卡被破坏。','\r',char(13)),'\n',char(10)),'攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12607053,'和睦使者','①：此回合，自己的怪兽不会因战斗被破坏，自己受到的战斗伤害变为0。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12612470,'童妖 茶壶',replace(replace('此卡名的②③效果１回合仅可各使用１次。\r\n①：只要此卡存在于怪兽区域，与此卡同一纵列的、里侧守备表示怪兽不可变更表示形式，被放置在魔法与陷阱区域的卡不可发动。\r\n②：在自己的主要阶段可以发动。将此卡移动至相邻的主要怪兽区域。\r\n③：怪兽区域的此卡移动至其他怪兽区域的情况下发动。将与此卡同一纵列的其他怪兽全部改成里侧守备表示。','\r',char(13)),'\n',char(10)),'移动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12615446,'电子光虫－散热圣甲虫',replace(replace('昆虫族、光属性等级３怪兽×２只或以上\r\n①：１回合１次，可移除此卡的２个超量素材，并以对手场上的１只怪兽为对象发动。变更该怪兽的表示形式，直至回合结束时，该效果无效。此效果在对手回合也可发动。\r\n②：１回合１次，此卡因战斗破坏对手怪兽并送入墓地时可发动。将被破坏的该怪兽重叠至此卡的下方当作超量素材。','\r',char(13)),'\n',char(10)),'效果无效','增加素材','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12624008,'光明之灵','此卡因战斗破坏并被送入墓地时，破坏场上所有以表侧表示存在的除光属性怪兽以外的怪兽。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12632096,'超银河眼光波龙',replace(replace('等级９怪兽×３\r\n①：此卡持有“光波”卡作为超量素材的情况下，获得以下效果。●１回合１次，去除此卡的最多３个超量素材可以发动。依去除的数量挑选对手场上的表侧表示怪兽，直至结束阶段为止获得其控制权。以此效果获得控制权的怪兽的效果无效化，攻击力变为４５００，卡名视为“超银河眼光波龙”。此效果发动后，直至回合结束时为止，此卡以外的自己怪兽不可直接攻击。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12644061,'高等暗黑','将双方场上、墓地冠有“宝玉兽”之名的所有怪兽视为暗属性。此外，冠有“究极宝玉神”之名的怪兽攻击的场合，仅限在战斗阶段期间，攻击对象怪兽的效果被无效化。我方场上冠有“宝玉兽”之名的怪兽进行战斗的伤害计算时，可从牌组将１只冠有“宝玉兽”之名的怪兽送入墓地并发动。该战斗中发生的给予我方的战斗伤害变成０。','战斗伤害变成0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12652643,'古代机械齿轮究极巨人',replace(replace('“古代机械齿轮巨人”＋“古代机械齿轮”怪兽×２\r\n此卡仅可以融合召唤方式特殊召唤。\r\n①：此卡攻击的情况下，对手直至伤害步骤结束时为止，不可发动魔法・陷阱卡。\r\n②：此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。\r\n③：此卡被破坏的情况下，以自己墓地的１只“古代机械齿轮巨人”为对象可以发动。将该怪兽无视召唤条件特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12670770,'电子网络','此卡发动后，将在自己的第3次准备阶段被破坏。①：1回合1次，在场上有“电子龙”存在的情况下可以发动。从牌组将1只机械族・光属性怪兽除外。②：在此卡从场上被送至墓地的情况下发动。尽可能将被除外的自己的机械族・光属性怪兽特殊召唤，将自己场上的所有魔法・陷阱卡破坏。此效果特殊召唤的怪兽不可发动效果。在发动此效果的回合中，自己不可进入战斗阶段。','是否现在使用「电子网络」的效果？','使用效果','从牌组把1只机械族·光属性怪兽除外','除外的怪兽特殊召唤','回合计数','','','','','','','','','','','');
INSERT INTO texts VALUES(12678601,'廷达三角・巨噬虫',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡被从手牌・牌组被送至墓地的情况下，以自己墓地“廷达三角・巨噬虫”以外的１只“廷达三角”怪兽为对象可以发动。将该怪兽以里侧守备表示形式特殊召唤。\r\n②：此卡反转的情况下可以发动。从牌组挑选１张魔法・陷阱卡送至墓地。\r\n③：以此卡作为连接素材的“廷达三角”连接怪兽在１次战斗阶段中可攻击３次。','\r',char(13)),'\n',char(10)),'','','「廷达三角之巨噬蠕虫」作为连接素材','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12678870,'圣灵兽骑 别都豚',replace(replace('“灵兽使”怪兽＋“精灵兽”怪兽\r\n仅可在将自己场上的上述卡除外的情况下特殊召唤。\r\n①：场上的此卡不会因效果被破坏。\r\n②：在自己・对手回合中，将此卡放回额外牌组，以自己除外状态的１只“灵兽使”怪兽与１只“精灵兽”怪兽为对象可以发动。将该怪兽以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'1只「灵兽使」怪兽和1只「精灵兽」怪兽特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12682213,'铁骑之雷锤','①：场上怪兽的效果・魔法・陷阱卡发动时，支付一半LP可以发动。将该发动无效并破坏。然后，与所破坏的卡原先存在的区域同一纵列的怪兽区域・魔法与陷阱区域存在卡的情况下，将那些卡全部破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12686296,'秘仪之力EX－混沌统御者',replace(replace('卡名不同的“秘仪之力”怪兽×3\r\n仅可在将自己・对手场上的上述卡送至墓地的情况下特殊召唤。\r\n①：此卡特殊召唤的情况下发动。掷1次硬币，根据掷出的正反，适用以下效果。\r\n●正面：从手牌・牌组将1只等级10的“秘仪之力”怪兽无视召唤条件特殊召唤。\r\n●反面：从牌组将1张拥有掷硬币效果的卡加入手牌。\r\n②：只要“光之结界”存在于场地区域，对手不可发动场上的怪兽的效果。','\r',char(13)),'\n',char(10)),'手牌·牌组特殊召唤','加入手牌','不可把怪兽效果发动','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12694768,'暴鬼','此卡因战斗被破坏并送入墓地时、双方受到５００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12697630,'古遗物－贝加尔挞','此卡名的③效果１回合仅可使用１次。①：此卡可视为魔法卡从手牌放置在魔法与陷阱区域。②：放置在魔法与陷阱区域的此卡在对手回合被破坏并送至墓地的情况下发动。将此卡特殊召唤。③：在对手回合中，此卡特殊召唤成功的情况下发动。挑选被放置在自己场上的最多２张卡破坏。','特殊召唤','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12735388,'虹之衣','装备怪兽与对手怪兽进行战斗的场合，对手怪兽的效果在战斗阶段中无效。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12743620,'齐唱协调',replace(replace('此卡牌名的卡牌１回合只可发动１张。\r\n①：可以我方或对手墓地的１只协调和场上的１只表侧表示的怪兽为对象发动。除外对象墓地的怪兽。之后，直至回合结束时，对手场上的怪兽等级变成被除外怪兽相同等级，并被视为协调。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12744567,'混沌编号101 寂静荣耀黑暗骑士',replace(replace('等级５怪兽×３\r\n①：１回合１次，以对手场上１只被特殊召唤的怪兽为对象可以发动。将该怪兽作为此卡的超量素材。\r\n②：持有超量素材的此卡被破坏并被送至墓地时可以发动（此效果在自己墓地存在“编号101 寂静荣耀方舟骑士”的情况下才能发动和处理）。将此卡特殊召唤。然后，依此卡原本攻击力数值恢复自己的LP。以此效果特殊召唤的此卡此回合不可攻击。','\r',char(13)),'\n',char(10)),'吸收素材','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12755462,'格布林填埋部队','成功召唤此卡时，陷阱卡不可发动。此外，只要此卡以表侧表示存在于场上，成功召唤・反转召唤・特殊召唤怪兽时，冠有“落穴”之名的陷阱卡不可发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12760674,'剑柄打击',replace(replace('仅限装备于我方场上通常召唤而来的怪兽。\r\n①：装备怪兽不受对手场上特殊召唤而来的怪兽所发动的效果影响。\r\n②：装备怪兽与特殊召唤而来的对手怪兽进行战斗的伤害计算时发动。该对手怪兽的攻击力、守备力仅在该伤害计算时，下降装备怪兽的原本攻击力数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12766474,'影王 阴暗公爵','此卡名的①②效果1回合仅可各使用1次，此卡效果发动的回合中，自己仅可特殊召唤暗属性怪兽。①：解放自己场上任意数量的暗属性怪兽可以发动。从手牌将此卡特殊召唤。以此效果特殊召唤的此卡的攻击力上升相当于解放的怪兽数量×500的数值。②：此卡召唤・特殊召唤成功的情况下，以自己墓地1只等级5以上的暗属性怪兽为对象可以发动。将该怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12800564,'真龙魔王 至尊行者 完灵',replace(replace('要通常召唤此卡的情况下，必须解放自己场上的3只怪兽来召唤，且可解放自己场上的永续魔法・永续陷阱卡来作为怪兽的代替。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡是被上级召唤的情况下，对手发动手牌・场上的怪兽的效果时可以发动。将该发动无效并破坏。\r\n②：上级召唤的此卡因战斗或对手的效果被破坏的情况下可以发动。跳过下个对手的主要阶段。','\r',char(13)),'\n',char(10)),'是否选择魔法·陷阱卡解放？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12800777,'风之精灵 迦楼罗',replace(replace('此卡不可通常召唤。\r\n从自己墓地将1只风属性怪兽除外的情况下可以特殊召唤。\r\n①：在对手的结束阶段，以对手场上的1只表侧表示怪兽为对象可以发动。变更该对手的表侧表示怪兽的表示形式。','\r',char(13)),'\n',char(10)),'改变表示形式','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12801833,'虫惑之园',replace(replace('此卡名的③效果１回合仅可使用１次。\r\n①：自己除通常召唤外仅可追加１次，在自己的主要阶段召唤１只“虫惑魔”怪兽。\r\n②：只要此卡存在于场地区域，自己的昆虫族・植物族怪兽１回合各仅１次，不会因战斗被破坏。\r\n③：将自己场上的１只怪兽除外可以发动。从自己的手牌・墓地将１只“虫惑魔”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'使用「虫惑之园」的效果召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12804701,'芬芳疗愈',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：自己恢复相当于自己场上“芬芳”怪兽种类×１０００的LP。\r\n②：将墓地的此卡除外，以自己墓地的１只“芬芳”怪兽为对象可以发动。将该怪兽特殊召唤。然后，自己恢复５００LP。以此效果特殊召唤的怪兽从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12817939,'漆黑魔王 LV6','以“漆黑魔王 LV4”的效果特殊召唤的此卡，其因战斗破坏的对手怪兽的效果被无效化。以此效果使对手怪兽的效果被无效化的下一个我方回合的准备阶段时，可将此卡送入墓地并发动。从手牌、牌组特殊召唤１只“漆黑魔王 LV8”。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12822541,'DD 莉莉丝',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：此卡召唤・特殊召唤的情况下，可从以下效果中选择1个发动。\r\n●以自己墓地的1只“DD”怪兽为对象可以发动。将该怪兽加入手牌。\r\n●从自己额外牌组（表侧）将1只“DD”灵摆怪兽加入手牌。','\r',char(13)),'\n',char(10)),'自己墓地1只「DD」怪兽加入手牌','自己额外牌组1只「DD」灵摆怪兽加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12829151,'女剑士迦南','飞如蝴蝶、刺如蜜蜂，手持剑与盾牌的女战士。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12836042,'失散者佣兵部队','我方场上不存在有除此卡以外的怪兽的场合，可解放此卡并发动。选择对手场上的１只怪兽，直至结束阶段时获得其控制权。发动此效果的回合，我方不可特殊召唤怪兽，不能进行战斗阶段。','获得控制权','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12863633,'五棱星的咒缚','可选择对手场上的１只怪兽并发动。对手不可释放被选择怪兽，也不可作为同步素材。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12877076,'宝玉神觉醒',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：将手牌的１只“究极宝玉神”怪兽出示给对手，可从以下效果中选择１个发动。或自己场上有“究极宝玉神”怪兽存在的情况下，可从以下效果中选择１个或两方发动。\r\n●从牌组挑选１张“桥梁”卡或“飞越彩虹”，加入手牌或送至墓地。\r\n●从自己的手牌・牌组・墓地挑选１只“宝玉兽”怪兽或从自己的魔法与陷阱区域挑选１张“宝玉兽”怪兽卡特殊召唤。','\r',char(13)),'\n',char(10)),'牌组检索','特殊召唤','选择两方','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12883044,'火焰舞者','他会挥舞著熊熊燃烧的绳索靠近。一旦与他四目相对就完蛋了。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12888461,'盾甲鱼群',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：此卡召唤时可以发动。从手牌将1只等级6以下的鱼族怪兽以守备表示特殊召唤。以此效果特殊召唤的怪兽从场上离开的情况下，将其除外。\r\n②：此卡被除外的情况下可以发动。将此卡以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'从手牌特殊召唤','此卡特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12890860,'拒神 杜坦',replace(replace('光属性怪兽＋场上・墓地以外的怪兽×2\r\n①：融合召唤的此卡不会因战斗被破坏。\r\n②：自己场上・墓地不存在与对手场上・墓地的怪兽原本卡名相同的怪兽的情况下，自己场上的怪兽不会因效果被破坏。\r\n③：从手牌・牌组・额外牌组、将与对手场上・墓地的怪兽原本卡名相同的1只怪兽送至墓地，以对手场上・墓地的1只怪兽为对象可以发动。将该怪兽除外。','\r',char(13)),'\n',char(10)),'','','除外','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12908094,'我我我魔术师－我我我魔术',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：此卡存在于手牌的情况下可以发动。将“我我我魔术师－我我我魔术”以外的、自己手牌・墓地的1只“刷拉拉”、“我我我”、“隆隆隆”、“怒怒怒”怪兽、与此卡特殊召唤，仅以该2只作为素材进行1只“刷拉拉”、“我我我”、“隆隆隆”、“怒怒怒”、“魔人”、“英豪胜利者”、“编号”、“ZEXAL兵器”、“ZEXAL从者”超量怪兽的超量召唤。在此之际，要作为超量素材的1只怪兽的等级可视为与另1只怪兽的等级相同。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12908095,'我我我魔术师－我我我魔术',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：此卡存在于手牌的情况下可以发动。将“我我我魔术师－我我我魔术”以外的、自己手牌・墓地的1只“刷拉拉”、“我我我”、“隆隆隆”、“怒怒怒”怪兽、与此卡特殊召唤，仅以该2只作为素材进行1只“刷拉拉”、“我我我”、“隆隆隆”、“怒怒怒”、“魔人”、“英豪胜利者”、“编号”、“ZEXAL兵器”、“ZEXAL从者”超量怪兽的超量召唤。在此之际，要作为超量素材的1只怪兽的等级可视为与另1只怪兽的等级相同。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12923641,'暗之护封剑',replace(replace('此卡将在发动后的、自己的第２次准备阶段被破坏。\r\n①：作为此卡发动时的效果处理，对手场上存在表侧表示怪兽的情况下，将该怪兽全部改成里侧守备表示。\r\n②：只要此卡存在于魔法与陷阱区域，对手场上怪兽的表示形式不可更改。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12927849,'闪光ZEXAL兵器－天圣辉狼剑','此卡召唤成功时，可选择我方场上１只被视为装备卡之冠有“ZEXAL兵器”之名的怪兽，并以守备表示特殊召唤。此外，可选择我方场上１只冠有“希望皇霍普”之名的怪兽并发动。手牌的此卡被视为装备卡装备被选择之我方冠有“希望皇霍普”之名的怪兽。装备怪兽因战斗破坏对手怪兽并送入墓地时可发动。选择我方墓地１只冠有“ZEXAL兵器”之名的怪兽加入手牌。','特殊召唤','装备','加入手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12930501,'暗黑之魔重生',replace(replace('①：对手怪兽进行攻击宣言时，可以以对手墓地的１张魔法卡为对象发动。将该卡放置在自己场上。\r\n②：除外墓地的此卡，从手牌及放置在自己场上的卡中选择１张“死者苏生”卡送至墓地后可以发动。从自己墓地选择１只“拉之翼神龙”，无视召唤条件进行特殊召唤。然后，可以选择１只对手场上的怪兽送至墓地。此效果特殊召唤的怪兽在结束阶段被送至墓地。','\r',char(13)),'\n',char(10)),'','','是否选对手怪兽送至墓地？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12931061,'超级运动员超级竞技场',replace(replace('此卡名在规则上也可作为“方程式运动员”卡使用。\r\n此卡名的卡在１个回合中仅可发动１张。\r\n①：作为此卡发动时的效果处理，可从牌组挑选１只“超级运动员”怪兽或“方程式运动员”怪兽加入手牌，或从自己的墓地挑选１张“超级运动员竞技场”加入手牌。\r\n②：向对手出示手牌中的１张场地魔法卡，消耗１０００LP后可以发动。此回合中，自己除通常召唤外，还有１次机会可召唤１只“超级运动员”怪兽或“方程式运动员”怪兽。','\r',char(13)),'\n',char(10)),'是否把卡加入手牌？','','使用「超级运动员超级竞技场」的效果召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12940613,'魔幻甜点・礼仪','①：以自己墓地的１只“魔幻甜点”怪兽为对象可以发动。将该怪兽放回牌组，自己场上的所有“魔幻甜点”怪兽的攻击力・守备力上升８００。然后，可将自己墓地的１只怪兽放回牌组。','是否要选择墓地一只怪兽回到牌组？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12948099,'古神克图格亚',replace(replace('协调＋１只以上协调以外的怪兽\r\n①：此卡同步召唤成功的情况下可以发动。将场上的阶级４超量怪兽全部放回持有者的额外牌组。②：以此卡为素材的融合召唤成功的情况下发动。自己从牌组抽１张。③：以场上的此卡为素材超量召唤的怪兽获得以下效果。\r\n●此超量召唤成功的情况下发动。自己从牌组抽１张。','\r',char(13)),'\n',char(10)),'回到持有者的额外牌组','抽1张卡','抽1张卡（古神克图格亚）','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12950294,'速装龙',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：自己受到效果伤害时可以发动。从手牌将此卡特殊召唤。然后，给予对手相当于自己受到的伤害相同数值的伤害，依所给予的伤害的一半数值恢复自己的LP。\r\n②：此卡上级召唤时可以发动。从牌组将2只“枪弹”怪兽加入手牌（同名卡最多1张）。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12953226,'女邪神努维娅','被召唤的场合，破坏此卡。对手即使只控制着１只怪兽的场合，对手场上每有１只怪兽攻击力就下降２００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12954226,'妖精圆环',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的②效果1回合仅可使用1次。\r\n①：只要此卡存在于怪兽区域，自己在通常召唤之外，可在自己的主要阶段追加1次召唤1只昆虫族・植物族怪兽。\r\n②：有怪兽因自己的昆虫族・植物族怪兽的战斗被破坏并被送至墓地时，以该被破坏的怪兽中的1只为对象可以发动。给予对手相当于该怪兽攻击力一半数值的伤害。然后，依给予伤害的数值恢复自己的LP。','\r',char(13)),'\n',char(10)),'使用「妖精圆环」的效果召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12958919,'幻铳士','①：此卡召唤・反转召唤成功时可以发动。将“铳士衍生物”（恶魔族・暗・星4・攻/守500）特殊召唤至自己场上，数量最多为自己场上的怪兽数量。②：自己的准备阶段可以发动。给予对手自己场上“铳士”怪兽数量×300的伤害。发动此效果的回合中，自己的“铳士”怪兽不可攻击宣言。','特殊召唤','伤害','是否还要特殊召唤Token？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12958920,'铳士衍生物','以“幻铳士”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12965761,'死亡石斛','１回合１次，可在我方的主要阶段时，将此卡作为装备卡装备至我方的“血兰”上，或者解除装备状态以表侧攻击表示特殊召唤此卡。以此效果变为装备卡的场合，可在装备怪兽每次通过战斗破坏怪兽时特殊召唤１只“魔草衍生物”（植物族・地・１星・攻／守８００）。（１只怪兽最多只可装备１张联合。装备怪兽因战斗而被破坏的场合，破坏此卡来代替。）','装备','特殊召唤','特殊召唤衍生物','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12965762,'魔草衍生物','由“死亡石斛”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12975671,'先驱企鹅',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：自己场上不存在表侧表示怪兽的情况下，此卡可从手牌特殊召唤。以此方法特殊召唤的此卡视为协调。\r\n②：舍弃1张手牌，向对手出示额外牌组的1只水属性同步怪兽可以发动。从牌组将1只等级比所出示的怪兽低1、种族相同的水属性怪兽加入手牌。然后，可将此卡改成里侧守备表示。此回合，自己从额外牌组仅可特殊召唤水属性怪兽。','\r',char(13)),'\n',char(10)),'','检索效果','是否变成里侧守备表示？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12977245,'幻变骚灵・迟滞菲菲内拉','①：只要此卡存在于怪兽区域，对手不可将“幻变骚灵・迟滞菲菲内拉”以外的自己场上的“幻变骚灵”怪兽选择为攻击对象，也不可作为效果的对象。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12980373,'魔幻甜点・千层咪咪',replace(replace('①：此卡召唤时可以发动。从手牌将１只“魔幻甜点”怪兽特殊召唤。\r\n②：此卡被对手破坏并被送至墓地的情况下发动。将此卡放回牌组。','\r',char(13)),'\n',char(10)),'返回牌组','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12986778,'机皇帝的赐予','场上的表侧表示怪兽仅是２只冠有“机皇”之名怪兽的场合可发动。我方从牌组抽取２张卡牌。发动此卡的回合，我方不能进行战斗阶段。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12986807,'岩浆炎・巨人',replace(replace('协调＋协调以外的炎属性怪兽１只或以上\r\n此卡同步召唤成功的场合发动。挑选１张我方手牌并送入墓地。此卡因卡牌效果被破坏的场合，作为代替可将我方墓地１只冠有“岩浆炎”之名的怪兽从游戏中除外。','\r',char(13)),'\n',char(10)),'把1张手牌送至墓地','是否要把墓地的1只名字带有「岩浆炎」的怪兽除外代替破坏？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(12989604,'从星遗物的苏醒','此卡名的卡1回合仅可发动1张。①：以自己场上的怪兽为素材，将1只连接怪兽连接召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13002461,'魔导战士 芙尔丝','１回合１次，可将我方墓地的１张冠有“魔导书”之名的魔法卡返回至牌组，并选择场上的１只魔法师族怪兽发动。被选择的怪兽提升１个等级，攻击力上升５００点。','等级攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13014905,'火天兽－蜡烛',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：用抽牌以外的方法将此卡加入手牌的情况下可以发动。将此卡特殊召唤。\r\n②：１回合最多３次，怪兽被送至自己墓地的情况下可以发动（同一连锁上最多１次）。此卡的等级上升或下降１。','\r',char(13)),'\n',char(10)),'特殊召唤','等级变换','等级上升','等级下降','','','','','','','','','','','','');
INSERT INTO texts VALUES(13021682,'星废品同步士',replace(replace('此卡可代替“同步士”协调作为同步素材。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡存在于手牌的情况下，以自己墓地的1只等级2以下的怪兽为对象可以发动。将此卡特殊召唤，将对象怪兽的效果无效并特殊召唤。此回合，自己从额外牌组仅可特殊召唤同步怪兽。\r\n②：将墓地的此卡除外可以发动。此回合中，自己场上的“废品战士”不会因对手的效果而被破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','破坏耐性','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13021683,'星废品同步士',replace(replace('此卡可代替“同步士”协调作为同步素材。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡存在于手牌的情况下，以自己墓地的1只等级2以下的怪兽为对象可以发动。将此卡特殊召唤，将对象怪兽的效果无效并特殊召唤。此回合，自己从额外牌组仅可特殊召唤同步怪兽。\r\n②：将墓地的此卡除外可以发动。此回合中，自己场上的“废品战士”不会因对手的效果而被破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','破坏耐性','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13023431,'密林狩猎者修弗鲁依由',replace(replace('等级5以上的战士族・地属性怪兽＋战士族・地属性怪兽\r\n此卡名的②效果1回合仅可使用1次。\r\n①：此卡只要存在于怪兽区域，在自己・对手的主要阶段期间，不受对手发动的效果影响。\r\n②：自己的其他战士族・地属性怪兽战斗破坏对手怪兽时可以发动。将自己墓地・除外状态的1只战士族・地属性怪兽特殊召唤。\r\n③：可以攻击的对手怪兽必须攻击自己场上攻击力最高的怪兽。','\r',char(13)),'\n',char(10)),'','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13026402,'陷阱处理班 A组','对手发动陷阱卡时，通过解放此卡使该发动无效并破坏。','陷阱无效并破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13030280,'混沌超量－漫画英雄 传奇亚瑟',replace(replace('等级５怪兽×３\r\n此卡１回合仅１次，不会因战斗被破坏。此外，此卡有“漫画英雄 亚瑟王”在作为超量素材的情况下，获得以下效果。\r\n●此卡因战斗破坏怪兽并将其送至墓地时，去除此卡的１个超量素材可以发动。将所破坏的怪兽从游戏除外，给予对手生命值相当于其原本攻击力数值的伤害。','\r',char(13)),'\n',char(10)),'除外并伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13032689,'超量单位','仅限装备超量怪兽。装备怪兽的攻击力上升装备怪兽的阶级×２００点。此外，我方场上的装备怪兽移除超量素材并发动效果的场合，此卡可被视为１个移除的超量素材。','是否要使用「超量单位」的效果？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13035077,'龙叁阵 示图',replace(replace('①：场上的“真龙”怪兽的攻击力・守备力上升300。\r\n②：只要此卡存在于场地区域，上级召唤的“真龙”怪兽1回合各仅1次，不会因战斗被破坏。\r\n③：1回合1次，在自己的主要阶段可以发动。将自己手牌・场上的1张其他的卡破坏，从牌组将1张“真龙”卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13039848,'岩石巨兵','岩石巨人兵。粗壮手臂使出的攻击会撼动大地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13046291,'进化虫・巨手蜥',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：解放自己场上的１只爬虫类族怪兽，舍弃１张手牌可以发动。从牌组将１只等级６以下的恐龙族・炎属性怪兽特殊召唤。\r\n②：将墓地的此卡除外，以自己场上的１只没有超量素材的龙族超量怪兽为对象可以发动。从自己的手牌・墓地挑选最多２只爬虫类族・恐龙族怪兽，作为对象怪兽的超量素材（同名卡最多１张）。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13048472,'仪式的事前准备',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从牌组挑选1张仪式魔法卡，进而从自己牌组・墓地挑选1只卡名记载于该仪式魔法卡的仪式怪兽。将该2张卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13048473,'仪式的事前准备',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从牌组挑选1张仪式魔法卡，进而从自己牌组・墓地挑选1只卡名记载于该仪式魔法卡的仪式怪兽。将该2张卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13069066,'剑龙','全身都附有刀刺的恐龙，以突进为手段进行攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13070280,'提斯蒂娜的嬉戏',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：从自己手牌・墓地将１只“提斯蒂娜”怪兽以守备表示特殊召唤。以此效果特殊召唤的怪兽将在结束阶段被放回手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13073850,'机壳别名',replace(replace('←1 【灵摆】 1→\r\n①：我方只可特殊召唤“机壳”怪兽。此效果不会被无效化。\n②：我方场上“机壳”怪兽的攻击力上升３００。\r\n【怪兽效果】\r\n①：此卡可无需释放进行召唤。\n②：以特殊召唤或无需释放召唤而来的此卡之等级变成４，原本攻击力变成１８００。\n③：通常召唤而来的此卡不受原本等级或阶级低于此卡等级之怪兽所发动的效果影响。\n④：释放“机壳”怪兽且此卡的上级召唤成功时，可以场上的１张卡牌为对象发动。将该卡返回至持有者手牌。针对此效果的发动，对手不可发动魔法、陷阱、怪兽的效果。','\r',char(13)),'\n',char(10)),'不用解放作召唤','弹回手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13076804,'混沌恶魔－混元的魔神－',replace(replace('光属性协调＋１只以上协调以外的暗属性怪兽\r\n此卡名的③效果１回合仅可使用１次。①：此回合有卡被除外过的情况下，此卡的攻击力上升２０００。②：此卡可攻击所有对手怪兽各１次，此卡战斗破坏的怪兽不去墓地而直接被除外。③：此卡因对手从场上离开的情况下可以发动。从额外牌组将“混沌恶魔－混元的魔神－”以外的１只“混沌”同步怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13090893,'网格扫除机',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：场地魔法卡以表侧表示存在的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：将墓地的此卡和自己场上的１只连接怪兽除外可以发动。将对手场上的１张卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13093792,'命运－英雄 钻石魔侠','①：1回合1次，在自己的主要阶段可以发动。翻开自己牌组最上面的卡，其为通常魔法卡的情况下，将该卡送至墓地。不是的情况下，将该卡放回牌组最下面。以此效果将通常魔法卡送至墓地的情况下，在下一个自己回合的主要阶段，可以发动墓地的该通常魔法卡发动时的效果。','发动魔法卡效果','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13108445,'宝石骑士・海蓝玉',replace(replace('“宝石骑士・苍玉石”＋“宝石骑士”怪兽\r\n此卡从额外牌组仅可通过以上述卡作为融合素材的融合召唤来特殊召唤。\r\n①：此卡攻击的情况下，将在战斗阶段结束时变为守备表示。\r\n②：此卡从场上被送至墓地的情况下，以对手场上的1张卡为对象发动。将该对手的卡放回手牌。','\r',char(13)),'\n',char(10)),'返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13117073,'杜宾警卫拦路者',replace(replace('卡名不同的怪兽2只\r\n此卡名的①效果1回合仅可使用1次。\r\n①：此卡连接召唤的情况下，舍弃1张手牌可以发动。在此回合的结束阶段，从自己墓地将1张场地・永续魔法卡加入手牌。\r\n②：只要此卡存在于怪兽区域，自己场上的表侧表示的魔法卡不会因对手的效果被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13140300,'神龙之圣刻印','刻有谜之刻印的神圣遗物。传说其中封印着能施展如神般力量的龙之力。在黄金色的太阳下，历经悠久的时光，散发的神圣光辉使其最终被称为太阳石。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13143275,'守护龙 必思缇',replace(replace('等级4以下的龙族怪兽1只\r\n自己1回合仅可特殊召唤“守护龙 必思缇”1次，其②效果1回合仅可使用1次。①：只要此卡存在于怪兽区域，自己仅可特殊召唤龙族怪兽。②：从自己墓地的怪兽或被除外的自己的怪兽中，以1只龙族怪兽为对象可以发动。将该怪兽特殊召唤至作为2只以上连接怪兽共同的连接端的自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13166204,'我我我突击','①：对手发动以自己场上的“我我我”怪兽为对象的怪兽的效果时可以发动。将该对手的效果无效并破坏。然后，给予对手相当于破坏的怪兽原本攻击力和原本守备力中较高一方的数值的伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13166648,'双龙降临','对手超量怪兽的直接攻击宣言时可发动。从额外牌组以攻击表示特殊召唤１只龙族、光属性超量怪兽，将攻击对象转移至该怪兽并进行伤害计算。以此效果特殊召唤而来的怪兽之攻击力变成与攻击怪兽的攻击力相同，且效果被无效化。“双龙降临”１回合只可发动１张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13171876,'龙女仆・清扫龙女',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从自己牌组上面将3张卡送至墓地。\r\n②：在自己・对手的战斗阶段开始时可以发动。将此卡放回手牌，从自己手牌・墓地将1只等级7的“龙女仆”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13171877,'龙女仆・清扫龙女',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从自己牌组上面将3张卡送至墓地。\r\n②：在自己・对手的战斗阶段开始时可以发动。将此卡放回手牌，从自己手牌・墓地将1只等级7的“龙女仆”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13173832,'转生炎兽 獾狼','此卡名的②③效果1回合1次，仅可使用其中1个。①：以此卡作为素材连接召唤成功的怪兽，该回合不会因战斗・效果被破坏。②：此卡从墓地特殊召唤成功的情况下，以自己墓地的1只炎属性怪兽为对象可以发动。将该怪兽加入手牌。③：此卡因效果从自己的墓地加入手牌的情况下，将此卡出示给对手，以自己墓地的1只炎属性怪兽为对象可以发动。将该怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13179234,'弈勇战争～起始之地～',replace(replace('此卡名的①②效果１回合仅可各使用１次。①：从牌组将１张“弈勇”场地魔法卡加入手牌。然后，可以适用以下效果。\r\n●挑选自己场上的１张灵摆怪兽卡破坏，从牌组将１张“位置移动”加入手牌。\r\n②：将墓地的此卡除外可以发动。从自己的额外牌组挑选１只表侧表示的“弈勇”灵摆怪兽，放在自己的灵摆区域。此效果在此卡被送至墓地的回合不可发动。','\r',char(13)),'\n',char(10)),'牌组检索','放置灵摆卡','是否破坏灵摆卡并检索「位置移动」？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13179332,'大木炭１８','完全烧焦的巨木化身。据说该木炭烤出的肉味道极佳，被重视为珍宝。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13183454,'零鸟姬 鹰身冰妖',replace(replace('鸟兽族等级５怪兽×２\r\n可移除此卡的１个超量素材，选择对手场上的１只表侧表示怪兽并发动。被选择怪兽的攻击力变成０。','\r',char(13)),'\n',char(10)),'攻击变成0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13193642,'黑暗之花','在被污染的土地以及黑暗之力的环境下生长的花，非常凶暴。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13203964,'完美智能・海德拉驱动龙',replace(replace('连接怪兽1只以上\r\n①：此卡连接召唤的情况下，或此卡进行战斗的伤害步骤结束时发动。将对手场上的怪兽全部破坏。然后，给予对手相当于自己墓地的连接怪兽的数量×300的伤害。\r\n②：此卡只要存在于怪兽区域，属性也视为“光”、“水”、“炎”、“风”，不受与自身相同属性的怪兽发动的效果影响。\r\n③：攻击力1000以上的此卡将被战斗・效果破坏的情况下，作为代替可将此卡的攻击力改成下降了1000的数值。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13204145,'迷拟宝箱鬼・创造主',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：从牌组将2只卡名不同的反转怪兽出示给对手，对手从其中随机挑选1只。将该1只以里侧守备表示特殊召唤至对手场上，剩余的加入自己手牌。然后，可从手牌将1只“迷拟宝箱鬼”怪兽特殊召唤。\r\n②：对手将怪兽特殊召唤的情况下，将墓地的此卡除外，以对手场上的1只里侧表示怪兽为对象可以发动。将该怪兽改成表侧攻击表示或表侧守备表示。','\r',char(13)),'\n',char(10)),'检索','改变表示形式','是否从手牌特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13210191,'风暴','破坏我方场上所有魔法、陷阱卡。之后，尽可能地挑选最多被破坏卡牌数量的对手场上的魔法、陷阱卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13215230,'梦境小丑','此卡的表示形式从攻击表示变成表侧守备表示时，破坏对手场上的１只怪兽。','破坏对手场上1只怪兽','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13220032,'大日神械充能者','只要此卡以表侧表示存在于场上，我方场上的光属性怪兽攻击力，上升相当于此卡装备的装备卡数×３００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13224603,'机巧嘴－八咫御先','此卡名的②③效果1回合仅可各使用1次。①：解放自己场上的1只被通常召唤的怪兽，可以从手牌特殊召唤此卡。②：此卡召唤・特殊召唤成功的回合，在自己的主要阶段可以发动。召唤1只怪兽。自己以此效果召唤过的余下回合，仅可特殊召唤原本种族与该怪兽相同的怪兽。③：以此卡的①方法特殊召唤的此卡被解放的情况下发动。自己恢复2050LP。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13234975,'骑甲虫队登陆准备',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：将自己手牌・场上的怪兽作为融合素材，将１只昆虫族融合怪兽融合召唤。\r\n②：不是在此回合被送至墓地的此卡存在于墓地的情况下，从自己墓地将２只昆虫族怪兽除外可以发动。将此卡加入手牌。','\r',char(13)),'\n',char(10)),'融合召唤','此卡加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13235258,'侵蚀鳞粉',replace(replace('①：以自己场上的１只昆虫族怪兽为对象可以发动此卡。将此卡视为装备卡，装备于该怪兽。对手不可攻击该自己的装备怪兽以外的昆虫族怪兽。\r\n②：只要此卡被装备中，每次对手召唤・特殊召唤怪兽，或每次对手发动魔法・陷阱・怪兽的效果，在对手场上的所有表侧表示怪兽上各放１个鳞粉计数物。对手场上的怪兽的攻击力・守备力下降相当于该怪兽的鳞粉计数物×１００的数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13241004,'绒毛动物・企鹅','此卡名的②效果1回合仅可使用1次。①：只要此卡在场上以表侧表示存在，仅限1次，在自己的主要阶段可以发动。从手牌将“绒毛动物・企鹅”以外的1只“绒毛动物”怪兽特殊召唤。②：此卡作为“魔玩具”融合怪兽的融合召唤素材被送至墓地的情况下可以发动。自己从牌组抽2张，然后挑选1张手牌舍弃。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13243124,'至爱－英雄 火焰翼人',replace(replace('种族相同而属性不同的怪兽×2\r\n此卡名在规则上也视为“元素－英雄”卡。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡与攻击力2200以上的怪兽进行战斗的攻击宣言时可以发动。此卡的攻击力上升1000。然后，可从手牌将1只等级4以下的怪兽以守备表示特殊召唤。\r\n②：有怪兽因战斗被破坏的自己・对手回合可以发动。将自己手牌・场上的怪兽作为融合素材，将1只融合怪兽融合召唤。','\r',char(13)),'\n',char(10)),'攻击力上升','融合召唤','是否特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13243125,'至爱－英雄 火焰翼人',replace(replace('种族相同而属性不同的怪兽×2\r\n此卡名在规则上也视为“元素－英雄”卡。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡与攻击力2200以上的怪兽进行战斗的攻击宣言时可以发动。此卡的攻击力上升1000。然后，可从手牌将1只等级4以下的怪兽以守备表示特殊召唤。\r\n②：有怪兽因战斗被破坏的自己・对手回合可以发动。将自己手牌・场上的怪兽作为融合素材，将1只融合怪兽融合召唤。','\r',char(13)),'\n',char(10)),'攻击力上升','融合召唤','是否特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13247801,'机甲部队的防卫圈','此卡名的②效果１回合仅可使用１次。①：只要自己场上有等级７以上的机械族怪兽存在，对手不可将自己场上的等级６以下的机械族怪兽选择为攻击对象，也不可作为效果的对象。②：自己场上的表侧表示机械族怪兽因战斗・效果被破坏的情况下，以自己墓地的１只机械族怪兽为对象可以发动。将该怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13250922,'吞食大食蚁兽蚁','此卡不可通常召唤。仅限将我方场上有２张魔法、陷阱卡送入墓地的场合可特殊召唤。１回合１次，可选择对手场上的１张魔法、陷阱卡破坏。此效果发动回合，此卡不可攻击。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13256226,'元素－英雄 新宇侠之精灵','此卡名的①②③效果１回合仅可各使用１次。①：对手怪兽攻击宣言时可以发动。将此卡从手牌以守备表示特殊召唤。以此效果特殊召唤的此卡不会因战斗被破坏。②：此卡特殊召唤成功的情况下可以发动。从牌组将１张记载有“元素－英雄”怪兽的卡名的魔法・陷阱卡或“融合”加入手牌。③：在自己的主要阶段可以发动。将此卡放回持有者的牌组，从牌组将１只“元素－英雄”通常怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13258285,'浮－朋.克.娑乐斋','此卡名的①②效果1回合仅可各使用1次。①：支付600LP可以发动。从自己的手牌・场上，将由“朋.克.”融合怪兽卡决定的融合素材怪兽送至墓地，从额外牌组将1只该融合怪兽融合召唤。②：在对手回合中，支付600LP可以发动。以自己场上的怪兽作为同步素材同步召唤1只“朋.克.”同步怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13289758,'流丽骑士盖亚奔流',replace(replace('等级6怪兽×2只以上\r\n“流丽骑士盖亚奔流”1回合1次，也可重叠在自己场上的阶级5・7的超量怪兽上面来超量召唤。\r\n此卡在被超量召唤的回合不可作为超量召唤的素材。\r\n①：此卡不可直接攻击。\r\n②：此卡的攻击力上升相当于此卡持有的超量素材的怪兽的等级・阶级合计×200的数值。\r\n③：此卡进行战斗的伤害步骤结束时发动。去除此卡的1个超量素材。','\r',char(13)),'\n',char(10)),'是否在5·７阶的超量怪兽上面重叠来超量召唤？','取除超量素材','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13291886,'弈勇－支配者公爵',replace(replace('←1 【灵摆】 1→\r\n此卡名的灵摆效果１回合仅可使用１次。①：场地区域有“弈勇世界－百识公国”存在的情况下，或自己场上有炎属性的“弈勇”怪兽存在的情况下可以发动。将此卡特殊召唤至正面的自己的主要怪兽区域。\r\n【怪兽效果】\r\n此卡名的①②怪兽效果１回合仅可各使用１次。①：以１张被放置在魔法与陷阱区域的卡为对象可以发动。被放置的该卡在此回合不可发动。②：怪兽区域的此卡移动至其他怪兽区域的情况下，以对手主要怪兽区域的１只表侧表示怪兽为对象可以发动。获得该表侧表示怪兽的控制权。以此效果获得控制权的怪兽不可攻击宣言，不可发动效果，也视为“弈勇”怪兽。','\r',char(13)),'\n',char(10)),'请选择要禁止发动的卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13293158,'邪恶－英雄 野生旋风',replace(replace('“元素－英雄 狂野人”＋“元素－英雄 羽毛人”\r\n此卡仅可以“暗黑结合”的效果特殊召唤。\r\n①：此卡进行攻击的场合，直至伤害步骤结束时，对手不可发动魔法、陷阱卡。\r\n②：此卡给予对手战斗伤害的场合发动。将所有盖牌于对手场上的魔法、陷阱卡破坏。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13298352,'胄之忍者－橹丸',replace(replace('种族不同的“忍者”怪兽×２\r\n此卡仅可以融合召唤及以下方法从额外牌组特殊召唤。\r\n●解放自己场上的上述卡的情况下，可从额外牌组特殊召唤。\r\n①：此卡特殊召唤・反转的情况下从自己的手牌・墓地及自己场上的表侧表示卡中，将此卡以外的１张“忍者”卡或“忍法”卡除外，以场上的１张卡为对象可以发动。将该卡除外。此卡名的此效果１回合仅可使用１次。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13301895,'失乐园','此卡名的②效果1回合仅可使用1次。①：只要此卡存在于场地区域，自己的怪兽区域的“神炎皇乌利亚”、“降雷皇哈蒙”、“幻魔皇拉比艾尔”、“混沌幻魔阿米泰尔”不会成为对手效果的对象，也不会因对手的效果而被破坏。②：自己的怪兽区域有“神炎皇乌利亚”、“降雷皇哈蒙”、“幻魔皇拉比艾尔”、“混沌幻魔阿米泰尔”中的任一存在的情况下可以发动。自己从牌组抽2张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13302026,'女王蝶 斑蝶',replace(replace('此卡名的效果１回合仅可使用１次。\r\n①：此卡被通常召唤的情况下，以自己墓地的最多３只等级４以下的昆虫族怪兽为对象可以发动。此卡的攻击力变为０，将对象怪兽特殊召唤。以此效果特殊召唤的怪兽的效果无效化。此效果在对手回合中也可以发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13313278,'燃烧拳斗士 护罩','①：自己受到战斗伤害时可以发动。从手牌将此卡特殊召唤，依所受伤害的数值恢复自己的LP。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13314457,'深海巨鳗','此卡从场上被送入墓地时，所有以表侧表示存在于我方场上的水属性怪兽的攻击力上升５００点，直到结束阶段时。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13316346,'起动士兵 死亡旋转者','只要冠有“小工具”之名的怪兽以表侧表示存在于我方场上，此卡的攻击力上升２０００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13317419,'火箭掌',replace(replace('“火箭掌”的①②效果１回合１次仅可使用其中１个。\r\n①：可以我方场上１只攻击力８００或以上的攻击表示怪兽为对象发动此卡。此卡被视为攻击力上升８００的装备卡，装备该怪兽。\r\n②：可将被装备的此卡送入墓地，并以场上表侧表示的１张卡牌为对象发动。破坏该卡。之后，装备此卡的怪兽攻击力变成０，并不可变更表示形式。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13331639,'霸王龙扎克',replace(replace('←1 【灵摆】 1→\r\n①：只要此卡存在于灵摆区域，对手不可发动场上的融合・同步・超量怪兽的效果。\n②：1回合1次，在抽牌阶段以外有卡从牌组加入对手手牌时可以发动。将该卡破坏。\r\n【怪兽效果】\r\n龙族的融合・同步・超量・灵摆怪兽各1只合计4只\n此卡仅可以融合召唤方式特殊召唤。\n①：此卡特殊召唤的情况下发动。将对手场上的卡全部破坏。\n②：此卡不会因对手的效果而被破坏，对手不可将此卡作为效果的对象。\n③：此卡战斗破坏对手怪兽时可以发动。从牌组・额外牌组将1只“霸王眷龙”怪兽特殊召唤。\n④：怪兽区域的此卡因战斗・效果被破坏的情况下可以发动。将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'破坏加入手牌的卡','对手场上的卡全部破坏','从牌组·额外牌组把1只「霸王眷龙」怪兽特殊召唤','此卡在自己的灵摆区域放置','','','','','','','','','','','','');
INSERT INTO texts VALUES(13331640,'霸王龙扎克',replace(replace('←1 【灵摆】 1→\r\n①：只要此卡存在于灵摆区域，对手不可发动场上的融合・同步・超量怪兽的效果。\n②：1回合1次，在抽牌阶段以外有卡从牌组加入对手手牌时可以发动。将该卡破坏。\r\n【怪兽效果】\r\n龙族的融合・同步・超量・灵摆怪兽各1只合计4只\n此卡仅可以融合召唤方式特殊召唤。\n①：此卡特殊召唤的情况下发动。将对手场上的卡全部破坏。\n②：此卡不会因对手的效果而被破坏，对手不可将此卡作为效果的对象。\n③：此卡战斗破坏对手怪兽时可以发动。从牌组・额外牌组将1只“霸王眷龙”怪兽特殊召唤。\n④：怪兽区域的此卡因战斗・效果被破坏的情况下可以发动。将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'破坏加入手牌的卡','对手场上的卡全部破坏','从牌组·额外牌组把1只「霸王眷龙」怪兽特殊召唤','此卡在自己的灵摆区域放置','','','','','','','','','','','','');
INSERT INTO texts VALUES(13332685,'天羽羽斩之巳剑',replace(replace('以“巳剑降临”降临\r\n此卡名的①效果在决斗中仅可使用1次，③效果1回合仅可使用1次。\r\n①：向对手出示手牌的此卡可以发动。从牌组将1只“巳剑”怪兽特殊召唤。然后，解放自己场上的1只怪兽。\r\n②：对手场上的怪兽的攻击力下降800。\r\n③：此卡被解放的情况下可以发动。从牌组将“天羽羽斩之巳剑”以外的1张“巳剑”卡加入手牌。然后，可将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤并解放','','检索','是否特殊召唤？','','','','','','','','','','','','');
INSERT INTO texts VALUES(13361027,'龙骑兵团－黑矛','①：1回合1次，解放自己场上的1只龙族的“龙骑兵团”怪兽，以自己墓地的1只等级4以下的鸟兽族怪兽为对象可以发动。将该鸟兽族怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13364097,'电脑堺门－朱雀','此卡名的①②效果１回合仅可各使用１次。①：以场上的１张表侧表示卡为对象可以发动。挑选２张自己被除外的“电脑堺”卡放回牌组（同名卡最多１张）。然后破坏对象卡。②：在自己的主要阶段将墓地的此卡除外，以自己场上的１只“电脑堺”怪兽为对象可以发动。该怪兽的等级或阶级直至回合结束时为止上升或下降３。','破坏','改变等级·阶级','上升','下降','','','','','','','','','','','','');
INSERT INTO texts VALUES(13379114,'恶魔的气魄',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：额外怪兽区域存在自己的“恶魔”仪式怪兽的情况下，以对手场上的1张表侧表示卡为对象可以发动。将该卡的效果直至回合结束时为止无效。\r\n②：此卡从手牌・场上被除外的情况下可以发动。从牌组将“恶魔的气魄”以外的1张“恶魔”卡加入手牌。','\r',char(13)),'\n',char(10)),'效果无效','检索效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13382806,'木天蓼仙狸',replace(replace('此卡名的效果１回合仅可使用１次。\r\n①：解放此卡，以“木天蓼仙狸”以外的自己墓地的１只等级２怪兽为对象可以发动。将该怪兽特殊召唤。然后，可将１只属性与以此效果特殊召唤的怪兽不同的等级２怪兽从手牌特殊召唤。','\r',char(13)),'\n',char(10)),'是否从手牌特殊召唤2星怪兽？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13386407,'极饿・仇尸','“仇尸”仪式怪兽的降临所必需。此卡名的卡１回合仅可发动１张。①：从自己的手牌・牌组・墓地挑选“仇尸・殇痕食腐者”以外的１只“仇尸”怪兽，以里侧守备表示特殊召唤。然后适用以下效果。●为使合计等级为仪式召唤的怪兽的等级以上，解放自己场上包含以此效果特殊召唤的怪兽在内的怪兽，从自己的手牌・墓地将１只“仇尸”仪式怪兽仪式召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13386503,'胡狼灵骑士','此卡可将１只此卡因战斗破坏并送入墓地的对手怪兽以表侧守备表示特殊召唤至我方场上。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13391185,'圣骑士加拉哈德',replace(replace('只要此卡以表侧表示存在于场上，被视为通常怪兽。只要此卡装备冠有“圣剑”之名的装备魔法卡，此卡被视为效果怪兽获得以下效果。\r\n●可选择我方墓地的１只冠有“圣骑士”之名的怪兽并发动。将被选择怪兽加入手牌，挑选我方场上的１张冠有“圣剑”之名的装备魔法卡并破坏。“圣骑士加拉哈德”的此效果１回合只可使用１次。','\r',char(13)),'\n',char(10)),'返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13408726,'梅塔特隆的影灵衣',replace(replace('←5 【灵摆】 5→\r\n此卡名的灵摆效果1回合仅可使用1次。\n①：自己的“影灵衣”卡以表侧被除外的情况下，以场上的1张魔法・陷阱卡为对象可以发动。将该卡除外。\r\n【怪兽效果】\r\n以“影灵衣”仪式魔法卡降临\n此卡仅可以仪式召唤方式特殊召唤，且仪式召唤仅可使用等级9以外的怪兽。\n此卡名的①怪兽效果1回合仅可使用1次。\n①：在自己・对手的主要阶段，以对手场上的1只表侧表示怪兽为对象可以发动。将此卡直至结束阶段为止除外，将对象怪兽除外。\n②：自己的“影灵衣”怪兽战斗破坏的怪兽不去墓地而直接被除外。','\r',char(13)),'\n',char(10)),'魔法·陷阱卡除外','怪兽除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13409151,'砂貘','反转：选择１只除“砂貘”以外的表侧表示怪兽，变更成里侧守备表示。','变成里侧守备','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13429800,'大白鲨','巨大的白色鲨鱼，一旦被那血盆大口咬住便无法脱身。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13438207,'花朵炸弹','仅限对手怪兽被自己的植物族怪兽战斗破坏并送往墓地时可以发动。给予对手LP该被破坏之怪兽的原本攻击力数值的伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13452889,'向量恫吓恶魔',replace(replace('电子界族怪兽２只以上\r\n①：此卡因战斗破坏对手怪兽并将其送入墓地时，可解放此卡连接端的１只我方怪兽并发动。特殊召唤被破坏的该怪兽至成为该卡连接端之我方・对手场上。以此效果特殊召唤怪兽至对手场上的场合，在此战斗阶段，此卡可再进行仅１次攻击。','\r',char(13)),'\n',char(10)),'','是否在自己场上特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13455674,'水晶机巧－黄龙伽德',replace(replace('协调2只以上＋协调以外的怪兽1只\r\n①：此卡同步召唤的情况下，以作为其同步素材的怪兽数量为上限，以对手场上・墓地的怪兽为对象可以发动。将该怪兽除外。\r\n②：同步召唤的此卡因战斗・效果被破坏的情况下，以此卡以外的、自己或对手除外状态的1只怪兽为对象可以发动。将该怪兽特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'对手怪兽除外','除外的怪兽特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13455953,'极星灵 小矮人','此卡召唤成功的回合，我方除通常召唤以外可仅再１次召唤１只冠有“极星”之名的怪兽。场上表侧表示的此卡被送入墓地时，从我方墓地选择１张冠有“极星宝”之名的卡牌加入手牌。','加入手牌','使用「极星灵 小矮人」的效果召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13474291,'云魔物－风暴龙','此卡不可通常召唤。可将我方墓地的１只冠有“云魔物”之名怪兽从游戏中除外并特殊召唤。此卡不因战斗被破坏。此卡以表侧守备表示存在的场合，被破坏。１回合１次，可选择１只场上的表侧表示怪兽并发动。放置１个雾计数物至被选择怪兽。','放置计数物','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13478040,'橡子松鼠','每次对手特殊召唤怪兽，就在此卡上放置１个橡子计数物。可移除此卡的１个橡子计数物并发动。选择对手场上的１只怪兽破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13482075,'仇尸・客迈拉','以“仇尸”仪式魔法卡降临。此卡名的①②效果１回合仅可各使用１次。①：破坏场上的卡的魔法・陷阱・怪兽的效果发动时，从自己的墓地将１只不死族怪兽除外可以发动。将该发动无效并破坏。②：此卡为了仪式召唤、而被解放或除外的情况下发动。对手场上的所有怪兽的攻击力・守备力下降５００。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13482262,'魔神仪的捉迷藏室','此卡名的卡1回合仅可发动1张。①：作为此卡发动时的效果处理，可将手牌的1只“魔神仪”怪兽出示给对手，将2只该怪兽的同名怪兽从牌组特殊召唤。然后将出示的怪兽放回牌组。②：1回合1次，仪式怪兽被特殊召唤至自己场上的情况下，以场上的1张卡为对象可以发动。将该卡破坏。','是否特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13486638,'急袭猛禽－魅影爪','此卡名的卡１回合仅可发动１张。①：怪兽的效果发动时，去除自己场上暗属性超量怪兽的１个超量素材可以发动。将该发动无效并破坏。为发动此卡而去除的超量素材为“魅影骑士团”、“急袭猛禽”、“超量龙”卡的情况下，进而挑选自己场上的１只“急袭猛禽”超量怪兽，其攻击力上升相当于以此效果破坏的怪兽原本攻击力的数值。','请选择要取除超量素材的卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13492423,'光子凯撒','①：此卡召唤・反转召唤成功时可以发动。从手牌・牌组将１只“光子凯撒”特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13504844,'加特姆士的紧急指令','①：场上存在“X－军刀”怪兽的情况下，以自己・对手墓地的合计2只“X－军刀”怪兽为对象可以发动。将该2只怪兽特殊召唤至自己场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13510157,'提斯蒂娜的猎犬',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：此卡存在于手牌・墓地，且自己场上存在光属性“提斯蒂娜”怪兽的情况下可以发动。将此卡特殊召唤。\r\n②：只要对手场上存在里侧守备表示怪兽，自己的“提斯蒂娜”怪兽可直接攻击。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13513663,'龙魂之城','①：“龙魂之城”在自己场上只可有1张以表侧表示形式存在。②：1回合1次，将自己墓地的1只龙族怪兽除外，可以自己场上的1只表侧表示的怪兽为对象发动。该怪兽的攻击力直至回合结束时为止上升700。③：表侧表示的此卡从场上被送至墓地时，可以1只被除外的自己的龙族怪兽为对象发动。将该怪兽特殊召唤。','攻击上升','特殊召唤','是否现在使用「龙魂之城」的效果？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13518809,'破灭之美神 露茵',replace(replace('以“世界不灭”降临\r\n①：此卡只要存在于手牌・场上，卡名视为“破灭之女神 露茵”。\r\n②：只要仪式召唤的此卡存在于怪兽区域，自己场上的仪式怪兽不会因效果被破坏。\r\n③：仅使用了仪式怪兽来仪式召唤的此卡在1次战斗阶段中可攻击2次。\r\n④：此卡战斗破坏对手怪兽时可以发动。给予对手相当于该怪兽的原本攻击力数值的伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13521194,'地狱公路巡警','①：此卡战斗破坏怪兽并将其送至墓地的情况下发动。给予对手相当于该怪兽原本等级×100的伤害。②：将墓地的此卡除外可以发动。从手牌将1只攻击力2000以下的恶魔族怪兽特殊召唤。','给与伤害','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13522325,'炎之精灵 伊夫利特','此卡不可通常召唤。将我方墓地中１只炎属性怪兽从游戏中除外的场合，可特殊召唤此卡。此卡的攻击力在我方的战斗阶段中上升３００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13529466,'召唤兽 卡里古拉',replace(replace('“召唤师 阿莱斯特”＋暗属性怪兽\r\n①：只要此卡存在于怪兽区域，在此期间，双方1回合仅可发动1次怪兽的效果，在1次战斗阶段中仅可用1只怪兽攻击。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13532663,'傀儡魔像','反转：由对手挑选对手场上的１只怪兽，与我方场上的此卡互换控制权。','控制权交换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13533678,'电光闪灵・喷流','此卡名以①方法的特殊召唤１回合仅可进行１次，且②效果１回合仅可使用１次。①：自己场上存在等级２或阶级２的怪兽的情况下，此卡可从手牌中特殊召唤。②：此卡特殊召唤成功的情况下可以发动。从牌组将１张“电光闪灵”魔法・陷阱卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13536606,'V－LAN 多头蛇',replace(replace('除衍生物以外的怪兽２只以上\r\n具此卡名的②效果１回合只能使用１次。\r\n①：此卡的攻击力上升与此卡相互连接的怪兽数×３００点。\r\n②：以此卡相互连接端的１只连接３以下的怪兽为目标可发动。解放该怪兽后，按其连接标记数在我方场上特殊召唤“V－LAN衍生物”（电子界族・光・星１・攻／守０）。此回合我方不能特殊召唤与目标怪兽连接标记数相同的怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13536607,'V－LAN衍生物','由「V－LAN 多头蛇」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13556444,'星尘幻象',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：自己场上有等级８以上的龙族同步怪兽存在的情况下可以发动。此回合，将因战斗或对手的效果被破坏并被送至自己墓地的怪兽尽可能多地特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13567610,'无穷机龙 卡诺',replace(replace('此卡不可通常召唤。\r\n对手在此决斗中发动过手牌或墓地的怪兽的效果的情况下，可从手牌・墓地特殊召唤。\r\n自己１回合仅可特殊召唤１次“无穷机龙 卡诺”。\r\n①：１回合１次，对手发动怪兽的效果的情况下可以发动。此卡的攻击力上升１０００。\r\n②：此卡从手牌・牌组以外被送至墓地的情况下发动。将此卡放回牌组。','\r',char(13)),'\n',char(10)),'攻击力上升','回到牌组','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13574687,'一击加农炮',replace(replace('“一击火箭”＋１只协调以外的怪兽\r\n１回合１次，自己的主要阶段时可以发动。选择场上的１只表侧表示怪兽并破坏，给予该控制者被破坏怪兽攻击力一半数值的伤害。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13582837,'无限狱上膛者','１回合１次，我方主要阶段时可发动。从我方牌组抽取１张卡牌，并相互确认。该卡是怪兽的场合，给予对手生命相当于该怪兽等级×２００点的伤害。若不是的场合，我方受到５００点伤害。此效果可在我方手牌是０张的场合发动与处理。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13597785,'耀圣之花诗 露西娜',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次，且②③效果1回合仅可各使用1次。\r\n①：此卡可从手牌特殊召唤至自己中央的主要怪兽区域。\r\n②：在自己的主要阶段可以发动。从牌组将“耀圣之花诗 露西娜”以外的1只“耀圣”怪兽加入手牌。\r\n③：在对手回合中可以发动。将自己的主要怪兽区域的、此卡和中央的怪兽的位置交换。然后，可将对手场上的1只等级6以下的怪兽放回手牌。','\r',char(13)),'\n',char(10)),'检索怪兽','交换位置','是否让怪兽回到手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13599884,'铁蝎','除机械族以外的怪兽对此卡进行攻击的场合，该怪兽在以对手回合计算的第３回合的结束阶段被破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13604200,'贤者的宝石','①：可在我方场上有“黑魔导女孩”存在的场合发动此卡。从手牌・牌组特殊召唤１只“黑魔导”。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13611090,'威风魔灵・声波','①：以自己场上的１只“威风魔灵”怪兽为对象可以发动。该怪兽直至回合结束时为止，攻击力・守备力变为两倍，给予对手的战斗伤害变为一半。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13626450,'邪气退散','可舍弃１张手牌并发动。破坏场上的所有永续陷阱卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13629812,'忍法 影缝之术','可释放我方场上１只冠有“忍者”之名的怪兽来发动此卡。选择对手场上的１只怪兽并从游戏中除外。只要该怪兽处于被除外的状态，不可使用其怪兽区域。此卡离开场上时，以此效果除外的怪兽以相同的表示形式回到其原来的怪兽区域位置。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13647631,'重机货列车 起重吊臂','此卡名的①效果１回合仅可使用１次。①：机械族・地属性怪兽被召唤・特殊召唤至自己场上的情况下可以发动。从手牌将此卡特殊召唤。以此效果特殊召唤的此卡原本的攻击力・守备力变为一半。②：作为超量素材的此卡为发动超量怪兽的效果被去除并被送至墓地的情况下，以对手场上的１张卡为对象可以发动。将该卡破坏。','从手牌特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13650422,'邪恶－英雄 黄金暗星',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：从手牌将此卡舍弃可以发动。从牌组将除“邪恶－英雄 黄金暗星”以外的1张“黑暗结合”或记载有该卡名的卡加入手牌。\r\n②：自己场上不存在融合怪兽的情况下，此卡不可攻击。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13662809,'魔界剧本“魔王降临”','①：可以场上的表侧表示的卡为对象发动，数量最多为自己场上的攻击表示的“魔界剧团”怪兽种类的数量。将该卡破坏。自己场上有等级7以上的“魔界剧团”怪兽存在的情况下， 应对此卡的发动对手不可发动效果。②：在自己的额外牌组有表侧表示的“魔界剧团”灵摆怪兽存在、被放置的此卡被对手的效果破坏的情况下可以发动。从牌组将“魔界剧团”卡或“魔界剧本”魔法卡合计最多2张加入手牌（同名卡最多1张）。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13676474,'假面咒术师 诅咒之喉','通过咒语来咒杀敌人的假面怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13683298,'大狼雷鸣',replace(replace('发动此卡效果的回合中，自己无法进行战斗阶段。\r\n①：此卡从墓地特殊召唤的情况下可以发动。将对手场上的表侧表示怪兽全部破坏。','\r',char(13)),'\n',char(10)),'怪兽破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13685271,'同名同姓同盟条约',replace(replace('除衍生物以外的同名怪兽有２只或以上以表侧表示存在于我方场上的场合可发动。根据该同名怪兽数量，适用以下效果。\r\n●２只：破坏对手场上存在的１张魔法、陷阱卡。\r\n●３只：破坏对手场上存在的所有魔法、陷阱卡。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13694209,'教导之神徒 阿萨辛','此卡名的①②③效果１回合仅可各使用１次。①：融合・同步・超量・连接怪兽被送至自己或对手墓地的情况下可以发动。从手牌将此卡特殊召唤。②：此卡从手牌特殊召唤成功的情况下，以自己墓地的１张“教导之神徒 阿萨辛”以外的“教导”卡为对象可以发动。将该卡加入手牌。③：对手怪兽攻击宣言时可以发动。自己场上的所有“教导”怪兽的攻击力上升５００。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13708425,'火焰共鸣者','①：以此卡作为同步素材的同步怪兽的攻击力上升300。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13708888,'邪恶－英雄 新宇霸主',replace(replace('“元素－英雄 新宇侠”（或记载有该卡名的融合怪兽）＋场上的效果怪兽\r\n此卡仅可以“黑暗结合”的效果特殊召唤。\r\n此卡名的①效果1回合仅可使用1次。\r\n①：此卡特殊召唤的情况下，或在此卡存在于怪兽区域的状态下、有怪兽被送至对手墓地的情况下，以对手场上的1只表侧表示怪兽为对象可以发动。获得该怪兽的控制权。\r\n②：场上的此卡不会因战斗・效果被破坏。','\r',char(13)),'\n',char(10)),'获取控制权','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13722870,'黑炎之骑士',replace(replace('“黑魔导”＋“炎之剑士”\r\n①：因此卡的战斗对自己造成的战斗伤害变为０。\r\n②：此卡因战斗被破坏并被送至墓地的情况下发动。从手牌・牌组将１只“幻影之骑士”特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13723605,'食人宝石箱','宝石箱形状的怪兽。欺骗冒险者接近并发动攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13735899,'秘仪之龙冠',replace(replace('魔法师族怪兽＋龙族怪兽\r\n此卡不可作为融合素材。\r\n此卡名的②效果1回合仅可使用1次。\r\n①：此卡的攻击力下降自己除外状态的卡数量×100的数值。\r\n②：因怪兽发动的效果，使该怪兽或与该怪兽原本种族相同的怪兽被特殊召唤的情况下，以其中1只为对象可以发动。将对象怪兽及与该怪兽原本种族相同的场上的怪兽全部除外。','\r',char(13)),'\n',char(10)),'怪兽除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13744068,'狂战恶魔',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：以包含恶魔族怪兽在内的、自己场上的最多２只表侧表示怪兽为对象可以发动。从手牌将此卡特殊召唤，将对象怪兽破坏。\r\n②：以此卡的①效果破坏怪兽时，依其数量，以对手场上表侧表示的怪兽为对象可以发动。此卡的攻击力直至下个自己回合结束时为止，上升相当于对象怪兽原本攻击力合计的数值。','\r',char(13)),'\n',char(10)),'此卡特殊召唤','攻击力上升','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13756293,'龙魔人 龙骑士之王',replace(replace('“龙之主宰－龙的支配者”＋“神龙 诸神黄昏”\r\n①：只要此卡存在于怪兽区域，对手不可将龙族怪兽作为魔法・陷阱・怪兽的效果的对象。②：１回合１次，在自己的主要阶段可以发动。从手牌将１只龙族怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13758665,'魔术师的左手','①：１回合１次，自己场上有魔法师族怪兽存在的情况下，将对手发动的陷阱卡效果无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13760677,'P・M捕获者',replace(replace('←5 【灵摆】 5→\r\n①：我方不死族怪兽的灵摆召唤成功时可发动。此回合，该怪兽不会因战斗、效果而被破坏。\r\n【怪兽效果】\r\n①：此卡因战斗破坏了怪兽的场合，可以我方墓地１只灵摆怪兽为对象发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'不会被战斗·效果破坏','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13761956,'炎狱宝宝','可将此卡从手牌送入至墓地并发动。选择１只我方场上的炎属性怪兽并攻击力上升４００点。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13764602,'阿吽的呼吸',replace(replace('此卡名的卡在1个回合中仅可发动1张，此卡名的效果②在1个回合中仅可使用1次。\r\n①：作为此卡发动时的效果处理，可以从牌组挑选1只“双天”怪兽加入手牌。\r\n②：在自己场上存在“双天”效果怪兽的情况下可以发动。特殊召唤1只“双天魂衍生物”（战士族・光・星2・攻/守0）至自己场上。此效果发动后，直至回合结束时为止，自己从额外牌组只可特殊召唤融合怪兽。','\r',char(13)),'\n',char(10)),'是否要加入手牌？','特殊召唤衍生物','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13764603,'双天魂衍生物','由“双天招来”等的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13764881,'锁链共鸣者','①：场上有同步怪兽存在，此卡召唤成功时可以发动。从牌组将1只“锁链共鸣者”以外的“共鸣者”怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13803864,'悠悠王',replace(replace('“悠悠”＋“悠悠”＋“悠悠”\r\n此卡离开场上时，可将我方墓地中的“悠悠”尽可能地特殊召唤至我方场上。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13821299,'陷阱吞噬者',replace(replace('此卡不可通常召唤。\r\n仅可在将对手场上的1张表侧表示的陷阱卡送至墓地的情况下特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13836592,'百战王 贝希摩斯',replace(replace('此卡可解放１只怪兽来上级召唤。\r\n①：此卡召唤・特殊召唤的情况下，以自己墓地的１只兽族・兽战士族・鸟兽族怪兽为对象可以发动。将该怪兽加入手牌，此卡的攻击力下降７００。\r\n②：通常召唤的此卡不受被特殊召唤的怪兽所发动的效果影响。\r\n③：在自己的结束阶段可以发动。此卡的攻击力上升７００。','\r',char(13)),'\n',char(10)),'把1只怪兽解放作上级召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13839120,'黄色小工具','①：此卡召唤・特殊召唤成功时可以发动。从牌组将１只“绿色小工具”加入手牌。','选1只「绿色小工具」加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13846680,'地狱日珥','此卡因战斗破坏并被送入墓地时，破坏场上所有以表侧表示存在的除炎属性怪兽以外的怪兽。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13851202,'卫星骑士 猎户里格尔','此卡名的效果１回合仅可使用１次。①：此卡召唤・反转召唤・特殊召唤成功的情况下，以场上的１只“星骑士”怪兽为对象可以发动。该怪兽的攻击力上升５００，并将在结束阶段被送至墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13857930,'新空间人・闪耀青苔',replace(replace('此卡牌名按规定被视作“新空间人・光辉青苔”。此卡仅限以“NEX”的效果可特殊召唤。此卡进行战斗攻击宣言时，我方抽取１张卡牌并相互确认。根据该卡的种类适用以下效果。\r\n●怪兽：结束此回合的战斗阶段。\r\n●魔法：可将此卡的攻击直接攻击对手玩家。\r\n●陷阱：此卡变成守备表示。','\r',char(13)),'\n',char(10)),'确认手牌','是否要进行直接攻击？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13890468,'精灵兽 别都豚',replace(replace('自己１回合仅可特殊召唤１次“精灵兽 别都豚”。\r\n①：１回合１次，从手牌将１张“灵兽”卡除外，以对手场上的１张卡为对象可以发动。将该卡放回手牌。','\r',char(13)),'\n',char(10)),'回到手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13893596,'究极封印神 艾克佐迪奥斯',replace(replace('此卡不可通常召唤。\r\n仅可在将自己墓地的怪兽全部放回牌组・额外牌组的情况下特殊召唤。\r\n以此卡的②效果将５种“被封印”怪兽送至自己的墓地并全部集齐时，自己获得决斗胜利。\r\n①：此卡的攻击力上升相当于自己墓地的通常怪兽的数量×１０００的数值。\r\n②：此卡的攻击宣言时发动。从手牌・牌组将１只怪兽送至墓地。\r\n③：表侧表示的此卡从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'怪兽送墓','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13903402,'光之创王 玛戴尔',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：“光之创王 玛戴尔”在自己场上仅可有1张以表侧表示存在。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从牌组将“光之创王 玛戴尔”以外的1张“创王”卡或1只植物族怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13923256,'战华之妙－鲁敬',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：以自己场上的1张永续魔法・永续陷阱卡为对象可以发动。将该卡送至墓地，从自己墓地将1张卡名与该卡不同的“战华”魔法・陷阱卡加入手牌。\r\n②：自己的其他“战华”怪兽发动效果的情况下，以对手场上的1张魔法・陷阱卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','魔陷破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13927359,'急袭猛禽－辉煌荣光',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：自己场上存在“急袭猛禽”怪兽的情况下，以对手场上的１只表侧表示怪兽为对象可以发动（自己场上存在“急袭猛禽”超量怪兽的情况下，作为代替也可以对手场上的１张表侧表示卡作为对象）。将该卡的效果直至回合结束时为止无效。\r\n②：将墓地的此卡除外，以自己的墓地・除外状态的１只“急袭猛禽”怪兽为对象可以发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13935001,'月光小夜曲舞蹈',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：融合怪兽被融合召唤至自己场上时，以其中1只为对象可以发动。适用以下效果。\r\n●将1只“月光衍生物”（兽战士族・暗・星4・攻/守2000）特殊召唤至对手场上。\r\n●对象怪兽的攻击力上升相当于对手场上怪兽数量×500的数值。\r\n②：在自己的主要阶段，将墓地的此卡除外可以发动。挑选自己的1张手牌送至墓地，从牌组将1只“月光”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13935002,'月光衍生物','由“月光小夜曲舞蹈”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13944422,'贪吃龙','成功召唤・反转召唤・特殊召唤此怪兽时，我方回复１０００点LP。此卡被破坏送入墓地时，我方受到２０００点伤害。','回复1000','伤害2000','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13945283,'幻影之壁','此卡被攻击的伤害计算后，将攻击怪兽返回至持有者手牌。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13955608,'机动城 堡垒',replace(replace('①：此卡发动后变成效果怪兽（机械族・地・星４・攻０／守２０００），以守备表示特殊召唤至怪兽区域。此卡也视为陷阱卡。\r\n②：自己场上有“绿色小工具”“红色小工具”“黄色小工具”存在的情况下，以此卡的效果特殊召唤的此卡的攻击力上升３０００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13959634,'冰灵神 穆岚格雷斯',replace(replace('此卡不可通常召唤。\r\n仅可在自己墓地的水属性怪兽为５只的情况下特殊召唤。\r\n此卡名的①效果１回合仅可使用１次。\r\n①：此卡特殊召唤的情况下发动。随机舍弃对手的２张手牌。\r\n②：表侧表示的此卡从场上离开时适用。跳过下个自己回合的战斗阶段。','\r',char(13)),'\n',char(10)),'手牌丢弃','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13965201,'逢华妖丽谭－不知火语',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：对手场上存在怪兽的情况下，从手牌将１只不死族怪兽舍弃可以发动。从自己的牌组・墓地将１只卡名与所舍弃怪兽不同的“不知火”怪兽特殊召唤。此卡发动后，直至回合结束时为止自己仅可特殊召唤不死族怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13972452,'威风魔灵・风暴','①：解放自己场上的１只魔法师族・风属性怪兽，以对手场上的１只怪兽为对象可以发动。将该怪兽放回牌组。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13974207,'电光－雪花－',replace(replace('此卡不可特殊召唤。\r\n①：只要自己场上不存在里侧表示的魔法・陷阱卡，且此卡存在于怪兽区域，双方就不可放置魔法・陷阱卡，不可发动场上里侧表示的魔法・陷阱卡。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13995824,'流电双角兽',replace(replace('兽族协调＋１只以上协调以外的怪兽\r\n此卡被对手破坏的情况下发动。双方玩家从牌组上面将７张卡送至墓地。','\r',char(13)),'\n',char(10)),'牌组破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(13997673,'核心浓度压缩','可向对手展示手牌的１张“核成之钢核”，从手牌舍弃１只冠有“核成”之名的怪兽并发动。从我方牌组抽取２张卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14001430,'魔幻甜点・城堡',replace(replace('①：作为此卡发动时的效果处理，自己的墓地存在“魔幻甜点”怪兽的情况下，将那些卡全部放回牌组。\r\n②：只要此卡存在于场地区域，场上的“魔幻甜点”怪兽的攻击力・守备力上升５００。\r\n③：自己墓地的怪兽因“魔幻甜点”怪兽的效果要被放回牌组的情况下，也可不放回牌组，而是改为放回手牌。','\r',char(13)),'\n',char(10)),'是否使用「魔幻甜点城堡」的效果？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14005031,'月舞的仪式',replace(replace('①：以自己场上的１只没有超量素材的风属性超量怪兽为对象可以发动此卡。只要该怪兽存在于场上，场上的表侧表示怪兽的效果无效化。对象怪兽离开场上时，此卡将被破坏。\r\n②：此卡发动过的余下回合的结束阶段发动。将场上的此卡重叠在此卡发动时作为对象的怪兽下面，作为超量素材。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14015067,'阴森林的长老','自古就居住在森林中的白山羊。其真实身分是森林的长老。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14017402,'波动龙骑士',replace(replace('龙族同步怪兽＋战士族怪兽\r\n此卡仅可以融合召唤从额外牌组特殊召唤。１回合１次，可选择我方或对手墓地的１只龙族同步怪兽并发动。将被选择怪兽从游戏中除外，并直至结束阶段时，将此卡视为该怪兽的同名卡，获得相同效果。此外，只要此卡以表侧表示攻击存在于场上，因对手卡牌效果发生的给予我方的效果伤害将由对手代替承受。','\r',char(13)),'\n',char(10)),'获得龙族同步怪兽效果','复制效果结束','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14025912,'斩机方程式','此卡名的卡1回合仅可发动1张。①：可以自己墓地的1只“斩机”怪兽为对象发动。将该怪兽特殊召唤。用此效果特殊召唤的怪兽的攻击力直至回合结束时为止上升1000。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14037717,'书本的精灵 霍克彼修普','书之精灵，拥有非常高的智慧，能发动多彩多样的攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14047624,'岩浆炎王制裁者','１回合１次，将自己墓地中的１只名字带有“岩浆炎”的怪兽从游戏中除外可以发动。给予对手LP１０００点伤害。发动此效果的回合中，“岩浆炎王制裁者”不可攻击宣言。','给与对手1000伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14055212,'安详的埋葬',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：从牌组将１只怪兽送至墓地。此回合，自己不可发动以此效果送至墓地的卡及其同名卡的效果。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14057297,'同归于尽',replace(replace('１个回合中只可发动１张“同归于尽”。\r\n①：可在双方手牌有３张以上的场合发动此卡。双方各自将所有手牌按任意顺序放回到牌组底部，我方失去双方以此效果放回牌组的卡牌数量×３００LP。之后，双方各从牌组抽取５张卡牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14087893,'月之书','①：以场上的1只表侧表示怪兽为对象可以发动。将该怪兽改成里侧守备表示。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14088859,'新宇结合','①：从自己的手牌・牌组・场上，将由融合怪兽卡决定的融合素材怪兽送至墓地，将该１只仅以２只怪兽作为素材的、且素材包括“元素－英雄 新宇侠”在内的融合怪兽无视召唤条件，从额外牌组特殊召唤。此卡发动后，直至回合结束时为止，自己不可特殊召唤怪兽。②：自己场上以“元素－英雄 新宇侠”作为融合素材的融合怪兽将被战斗・效果破坏的情况下，或因自身的效果放回额外牌组的情况下，可将墓地的此卡除外作为代替。','','是否除外「新宇结合」作为代替？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14089428,'蓝雷号T45','此卡因战斗破坏对手怪兽的场合，特殊召唤１只“雷选配件衍生物”（机械族、光、星４、攻／守１５００）至我方场上。此衍生物不可进行以上级召唤为目的的解放。','特殊召唤衍生物','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14089429,'雷选配件衍生物','由「蓝雷号T45」特殊召唤。这衍生物不能为上级召唤而解放。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14094090,'超战士的仪式','“混沌士兵”仪式怪兽的降临所必需。此卡名的②效果１回合仅可使用１次。①：为使合计等级为８，从自己的手牌・场上解放怪兽，从手牌将１只“混沌士兵”仪式怪兽仪式召唤。②：从自己的墓地将此卡及１只光属性怪兽与１只暗属性怪兽除外可以发动。从手牌将１只“混沌士兵”仪式怪兽无视召唤条件特殊召唤。此效果在此卡被送至墓地的回合不可发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14105623,'异色眼弧灵摆龙',replace(replace('←8 【灵摆】 8→\r\n此卡名的灵摆效果１回合仅可使用１次。\n①：自己场上表侧表示的“异色眼”卡因战斗・效果被破坏的情况下可以发动。从自己的手牌・牌组・墓地将１只“异色眼”怪兽特殊召唤。\r\n【怪兽效果】\r\n雄武美丽、拥有神秘眼睛的奇迹之龙。\n其双色眼眸熠熠生辉，映出描绘于天空的轨迹。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14108995,'春化精的花冠','①：只要此卡存在于魔法与陷阱区域，自己场上的地属性怪兽也视为“春化精”怪兽。②：１回合１次，自己为发动手牌的“春化精”怪兽的效果，而要将该怪兽和１张卡从手牌舍弃的情况下，作为代替可以仅舍弃该怪兽。','是否适用「春化精的花冠」的效果？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14124483,'元素－英雄 真诚新宇侠',replace(replace('此卡名的①②效果1回合仅可各使用1次，在对手回合中也可以发动。\r\n①：从手牌将此卡舍弃，以场上的1只“－英雄”怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止上升2500。\r\n②：从手牌将1只“－英雄”怪兽舍弃可以发动。此卡的攻击力直至回合结束时为止，上升相当于所舍弃的怪兽的攻击力的数值。','\r',char(13)),'\n',char(10)),'「－英雄」怪兽攻击力上升','丢弃手牌上升攻击力','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14141448,'大飞蛾','此卡不可通常召唤。解放１只装备了“进化之茧”后经过４个以上我方回合的“小毛虫”的场合，可特殊召唤此卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14146794,'阴郁里波＠伊格尼斯者','此卡名的①②效果1回合仅可各使用1次。①：自己的“＠伊格尼斯者”怪兽被攻击的伤害计算时，从手牌将此卡舍弃可以发动。因该战斗发生的对自己的战斗伤害改为0。②：“＠伊格尼斯者”怪兽或“-艾-”魔法・陷阱卡的、给予对手伤害的效果发动时，将墓地的此卡除外可以发动（伤害步骤也可以发动）。因该效果给予对手的伤害变为两倍。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14148099,'巨大战舰 巨核',replace(replace('①：此卡召唤的情况下发动。在此卡上放3个计数物。\r\n②：此卡不会因战斗被破坏。\r\n③：此卡进行战斗的伤害步骤结束时发动。去除此卡的1个计数物。无法去除的情况下将此卡破坏。','\r',char(13)),'\n',char(10)),'放置计数物','移除计数物','破坏','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14152693,'月光翠鸟',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从手牌将1张“月光”卡送至墓地，自己抽1张。\r\n②：此卡因效果被送至墓地的情况下，以除“月光翠鸟”以外的、自己墓地・除外状态的1只等级4以下的“月光”怪兽为对象可以发动。将该怪兽以守备表示特殊召唤。以此效果特殊召唤的怪兽的效果无效化。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14152862,'风纪宫司 祝词',replace(replace('魔法师族等级６怪兽×２\r\n①：１回合１次，对手发动魔法・陷阱卡时，去除此卡的１个超量素材可以发动。将该发动无效并破坏。','\r',char(13)),'\n',char(10)),'发动无效并破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14154221,'进化的代价','１回合１次，怪兽因冠有“进化虫”之名怪兽的效果而被特殊召唤的场合，可选择场上的１张卡牌破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14166715,'Recette de Viande～肉料理食谱～',replace(replace('“饿魔新飨”仪式怪兽的降临所必需。\r\n①：为使合计等级为仪式召唤的怪兽的等级以上，解放自己的手牌・场上的怪兽，从手牌将１只“饿魔新飨”仪式怪兽仪式召唤。以此效果将“油封之康菲拉斯・饿魔新飨”仪式召唤的情况下，可进而适用以下效果。\r\n●将对手场上的守备表示怪兽全部改成表侧攻击表示。','\r',char(13)),'\n',char(10)),'是否把对手怪兽全部变成攻击表示？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14169843,'芬芳法师－月桂',replace(replace('此卡名的①②③效果１回合仅可各使用１次。\r\n①：自己的LP多于对手的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：自己的LP恢复的情况下，以场上的１只植物族怪兽为对象发动。此回合，将该怪兽视为协调。\r\n③：此卡被送至墓地的情况下可以发动。自己恢复５００LP。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14181608,'香菇人','在潮湿的地方发挥实力！能从香菇伞散布菌丝发动攻击！','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14198496,'神秘吹笛人',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：解放此卡可以发动。自己抽1张，给双方确认。其为等级1怪兽的情况下，自己进而抽1张。','\r',char(13)),'\n',char(10)),'抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14212201,'影子吸血鬼','把这张卡作为超量召唤的素材的情况下，只可用于暗属性怪兽的超量召唤。①：这张卡召唤成功时可以发动。从手牌・牌组特殊召唤“影子吸血鬼”以外的1只暗属性“吸血鬼”怪兽。用这个效果特殊召唤成功的回合，该怪兽以外的自己的怪兽不可攻击。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14214060,'魔法剑士特兰斯','是一个具有相当实力的古怪魔法使他似乎是从异空间的旅程中归来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14220547,'烙印之教导法则','此卡名的①②效果１回合仅可各使用１次。①：自己以魔法卡的效果仅特殊召唤了１只仪式怪兽的情况下可以发动。确认自己或对手的额外牌组，挑选其中１只怪兽送至墓地。②：自己以魔法卡的效果仅特殊召唤了１只融合怪兽的情况下，以该１只怪兽为对象可以发动。该怪兽直至回合结束时为止，攻击力上升相当于自身原本攻击力的数值，仅可攻击对手场上的攻击表示怪兽。','额外牌组送至墓地','确认自己的额外牌组','确认对手的额外牌组','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14225239,'元素－英雄 水手侠',replace(replace('“元素－英雄 泡沫人”＋“元素－英雄 羽毛人”\r\n此卡仅可以融合召唤特殊召唤。我方的魔法＆陷阱卡区有卡牌被盖牌的场合，该卡可直接攻击对手玩家。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14235211,'暴风龙之防人','①：以自己场上的1只龙族通常怪兽作为对象可以发动。从自己的手牌・场上将此怪兽视为装备卡，将其装备给自己的龙族通常怪兽。②：装备怪兽攻击守备表示怪兽的情况下，将给对手造成攻击力超出其守备力部分数值的战斗伤害。③：装备怪兽将被破坏的情况下，作为代替破坏此卡。','装备','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14255590,'增幅的恶意','只要此卡以表侧表示存在于场上，对手回合的准备阶段时，从对手牌组最上方将卡牌送入墓地，其数量相当于我方墓地存在的“增幅的恶意”数量。','牌组送墓','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14258627,'地球巨人 盖亚・普雷特','此卡可将我方墓地的２只岩石族怪兽从游戏中除外，并从手牌特殊召唤。与此卡进行战斗的对手怪兽的攻击力、守备力，仅限在伤害计算时减半。每次此卡控制者的我方准备阶段，从我方墓地将１只岩石族怪兽从游戏中除外。或者不除外而将此卡送入墓地。','是否要把墓地的一只岩石族怪兽除外？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14261867,'八手蝎','此卡仅限１回合１次可变为里侧守备表示。以对手的里侧守备表示怪兽为攻击对象的场合，此卡的攻击力仅限于伤害计算时变为２４００点。','变成里侧守备','攻击变换','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14283055,'Concours de Cuisine～糕冷料理对决～',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：从手牌・牌组・额外牌组挑选１只“饿魔新飨”灵摆怪兽和１只“圣果使”灵摆怪兽，分别特殊召唤１只至双方场上。此回合，自己的融合・同步・超量・连接召唤仅可以“饿魔新飨”怪兽及“圣果使”怪兽作为素材。\r\n②：在自己的主要阶段将墓地的此卡除外，以场上的１只表侧表示怪兽为对象可以发动。该怪兽的攻击力上升相当于双方墓地的“食谱”卡的数量×２００的数值。','\r',char(13)),'\n',char(10)),'','','请选择要在自己场上特殊召唤的怪兽','请选择要在对手场上特殊召唤的怪兽','','','','','','','','','','','','');
INSERT INTO texts VALUES(14289852,'投石区','①：只要此卡存在于场地区，我方怪兽因战斗被破坏的场合，可从我方牌组将１只岩石族怪兽送入墓地作为代替。此效果１回合只可适用１次。','是否要使用「投石区」的效果代替破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14291024,'子机',replace(replace('此卡不可通常召唤。\r\n自己的怪兽区域存在“超时界战斗机 V型蛇”的情况下可以特殊召唤。\r\n此卡特殊召唤之际，必须选择自己场上的1只“超时界战斗机 V型蛇”。\r\n①：此卡的攻击力・守备力始终与所选择的怪兽相同。该怪兽不再以表侧表示存在于怪兽区域时此卡将被破坏。','\r',char(13)),'\n',char(10)),'请选择1只「超时界战斗机 V型蛇」','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14301396,'英豪胜利者 最强王者之剑',replace(replace('战士族等级4怪兽×2\r\n①：此卡与对手怪兽进行战斗的伤害计算时，去除此卡的2个超量素材可以发动。此卡的攻击力仅在该伤害计算时变为两倍。\r\n②：1回合1次，在自己・对手的主要阶段，以自己场上的1只其他的表侧表示怪兽为对象可以发动。将自己场上的此卡视为攻击力・守备力上升2000的装备魔法卡装备于对象怪兽。\r\n③：将墓地的此卡除外可以发动。从自己墓地将3只战士族怪兽放回牌组。','\r',char(13)),'\n',char(10)),'攻击力变成2倍','当作装备卡','回到牌组','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14306092,'牙鲛帝 鲨鱼凯萨',replace(replace('等级３怪兽×３只以上（最多５只）\r\n１回合１次，移除此卡的１个超量素材可以发动。放１个鲨鱼计数物至此卡。此外，此卡进行战斗的伤害步骤期间，此卡的攻击力上升此卡的鲨鱼计数物数量×１０００点。','\r',char(13)),'\n',char(10)),'放置计数物','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14307929,'白森的妖魔 迪亚贝尔',replace(replace('协调＋协调以外的怪兽１只以上\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡以同步怪兽的协调作为素材同步召唤的情况下，以自己墓地的１张魔法・陷阱卡为对象可以发动。将该卡加入手牌。\r\n②：对手发动魔法・陷阱・怪兽的效果时，从自己的手牌・场上将１张魔法・陷阱卡送至墓地可以发动。将自己的额外牌组・墓地・除外状态的１只等级７以下同步怪兽的协调特殊召唤。','\r',char(13)),'\n',char(10)),'回收墓地魔陷','特殊召唤同步协调','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14309486,'核成・过载体',replace(replace('此卡的控制者每当到自己的结束阶段，从手牌将1张“核成之钢核”送至墓地，或向对手出示手牌的1只岩石族怪兽，或将此卡破坏。\r\n①：对手召唤・反转召唤・特殊召唤怪兽之际，解放此卡可以发动。将其无效，将该怪兽破坏。','\r',char(13)),'\n',char(10)),'选择一张「核成之钢核」送至墓地','选择一只岩石族怪物给对手观看','破坏「核成・过载体」','召唤无效并破坏','反转召唤无效并破坏','特殊召唤无效并破坏','','','','','','','','','','');
INSERT INTO texts VALUES(14315573,'攻击无力化','①：可在对手怪兽的攻击宣言时，以１只该攻击怪兽为对象发动。使该攻击无效。之后，结束战斗阶段。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14318794,'生命吸收装置','每次我方准备阶段，回复前一个我方回合所支付的LP的一半数值。','回复','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14342283,'暴走斗君','①：只要此卡存在于魔法与陷阱区域，攻击表示的衍生物攻击力上升１０００，不会因战斗被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14344682,'武士刀男爵','１回合１次，可选择对手场上的１只守备表示怪兽并发动。将被选择怪兽变成表侧攻击表示。','表示形式改变','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14357527,'重骑甲虫 雄威尼普顿',replace(replace('此卡不可通常召唤。\r\n在将自己除外状态的３只昆虫族怪兽放回牌组的情况下可以特殊召唤。\r\n此卡名的②效果１回合仅可使用１次。\r\n①：在自己・对手的结束阶段，以自己场上的１只其他昆虫族怪兽为对象可以发动。该怪兽的攻击力上升１０００。\r\n②：场上的此卡在主要阶段因对手的效果，被破坏的情况下或被除外的情况下可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14365823,'淘气仙星・青绿歌姬',replace(replace('等级3以下的“淘气仙星”怪兽2只\r\n①：“淘气仙星・青绿歌姬”在自己场上仅可有1只以表侧表示存在。②：此卡特殊召唤成功的情况下可以发动。给予对手200伤害。③：对手每次召唤・特殊召唤怪兽成功发动。给予对手200伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14386013,'暗黑神秘学',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：舍弃１张手牌可以发动。从自己的牌组・墓地挑选１张“通灵盘”或１只恶魔族・等级８怪兽加入手牌。\r\n②：将墓地的此卡除外可以发动。从自己手牌・墓地的“通灵盘”及“死之信息”卡中，挑选任意数量（同名卡最多１张），以喜欢的顺序放回牌组下面。然后，自己依放回的数量从牌组抽牌。此效果在此卡被送至墓地的回合不可发动。','\r',char(13)),'\n',char(10)),'加入手牌','回收并抽牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14391625,'维萨思・轮回转生',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：此卡只要存在于场上・墓地，卡名视为“维萨思・史塔弗罗斯特”。\r\n②：以自己场上・墓地・除外状态的任意数量的“维萨思”怪兽为对象可以发动。将该“维萨思”怪兽放回牌组，从手牌将此卡特殊召唤。此卡的攻击力上升以此效果放回的种类×400的数值。\r\n③：要以自己场上的此卡作为同步素材的情况下，可将此卡视为协调以外的怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14391626,'维萨思・轮回转生',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：此卡只要存在于场上・墓地，卡名视为“维萨思・史塔弗罗斯特”。\r\n②：以自己场上・墓地・除外状态的任意数量的“维萨思”怪兽为对象可以发动。将该“维萨思”怪兽放回牌组，从手牌将此卡特殊召唤。此卡的攻击力上升以此效果放回的种类×400的数值。\r\n③：要以自己场上的此卡作为同步素材的情况下，可将此卡视为协调以外的怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14391920,'地狱暴风','受到３０００点或以上的战斗伤害时可发动。将双方牌组、墓地的怪兽全部从游戏中除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14393464,'斩机归纳法','此卡名的②效果1回合仅可使用1次。①：自己场上的电子界族怪兽的攻击力上升500。②：自己场上有“斩机”怪兽存在的情况下，把魔法与陷阱区域的表侧表示的此卡送至墓地，可以对手场上的1张卡为对象发动。将该卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14418464,'弈勇－爆破男爵',replace(replace('←1 【灵摆】 1→\r\n此卡名的灵摆效果１回合仅可使用１次。①：在自己的主要阶段可以发动。将此卡特殊召唤至正面的自己的主要怪兽区域。此效果发动后，直至回合结束时为止自己仅可特殊召唤“弈勇”怪兽（除了从额外牌组的特殊召唤以外）。\r\n【怪兽效果】\r\n此卡名的①②怪兽效果１回合仅可各使用１次。①：此卡是被特殊召唤的情况下，以此卡以外的自己主要怪兽区域的１只“弈勇”怪兽为对象可以发动。将该自己的怪兽的位置移动至其相邻的怪兽区域。②：怪兽区域的此卡移动至其他的怪兽区域的情况下，以自己或对手的灵摆区域的１张卡为对象可以发动。将该卡视为永续魔法卡，以表侧表示放在其相邻的魔法与陷阱区域。','\r',char(13)),'\n',char(10)),'请选择移动位置的怪兽','请选择移动位置的卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14425515,'无限狱死亡枪手',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己的主要阶段可以发动。从手牌将1只恶魔族怪兽特殊召唤。\r\n②：在自己・对手回合中，自己手牌为0张的情况下，将墓地的此卡除外可以发动。对手从以下挑选1个，自己适用其效果。\r\n●双方确认自己牌组最上面的卡，是怪兽的情况下，此回合，自己受到的效果伤害由对手代为承受。不是的情况下，自己受到4000伤害。\r\n●此回合，自己所受到的效果伤害变为0。','\r',char(13)),'\n',char(10)),'特殊召唤','发动','确认牌组','不受效果伤害','','','','','','','','','','','','');
INSERT INTO texts VALUES(14430063,'拦截恶魔','只要此卡以表侧攻击表示存在于自己场上，对手怪兽的攻击宣言时，给予对手LP５００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14442329,'地下俱乐部『杀手旋律』',replace(replace('此卡名的③效果1回合仅可使用1次。\r\n①：自己在通常召唤之外，可在自己的主要阶段追加1次召唤1只协调。\r\n②：只要对手场上或墓地存在协调，自己场上的“杀手旋律・响度战争”的攻击力上升3300。\r\n③：解放自己场上的1只协调可以发动。从牌组挑选1只“杀手旋律”怪兽，加入手牌或特殊召唤。此效果发动后，直至回合结束时为止，自己仅可特殊召唤协调。','\r',char(13)),'\n',char(10)),'使用「点唱机酒吧“杀手级协调曲”」的效果召唤','检索效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14457896,'寄生虫帕拉诺伊德',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：以场上的１只表侧表示怪兽为对象可以发动。将此卡视为装备卡，从手牌装备于该怪兽。装备怪兽的种族变为昆虫族，不可攻击昆虫族怪兽，以昆虫族怪兽为对象发动的装备怪兽的效果无效化。此效果在对手回合中也可以发动。\r\n②：视为装备卡的此卡被送至墓地的情况下可以发动。从手牌将１只等级７以上的昆虫族怪兽无视召唤条件特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14462257,'冰之女王',replace(replace('此卡不可从墓地特殊召唤。\r\n①：自己场上表侧表示的此卡被破坏并被送至墓地时，以自己墓地的1张魔法卡为对象可以发动（此效果在自己墓地的魔法师族怪兽为3只以上的情况下才能发动和处理）。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'墓地1张魔法卡加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14463695,'捕食嫁接木','①：以自己墓地的１只“捕食植物”怪兽为对象可以发动此卡。将该怪兽特殊召唤，装备此卡。此卡从场上离开时，该怪兽将被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14464864,'神的桎梏 格莱普尼尔','从牌组将１只冠有“极星”之名的怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14466224,'大气圈神鸟','此卡不可通常召唤。仅限将我方场上的２只怪兽及我方墓地的１只怪兽从游戏中除外的场合可特殊召唤。１回合１次，可选择对手场上１只以表侧表示的怪兽并将其视为装备卡装备在此卡（仅限装备１只）。此卡的攻击力、守备力上升相当于以此效果装备的怪兽的各个数值。','装备','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14469229,'宝玉的保卫者',replace(replace('←2 【灵摆】 2→\r\n①：１回合１次，只要此卡存在于灵摆区，我方场上的“究极宝玉神”怪兽及“宝玉兽”卡牌不会因效果被破坏。\r\n【怪兽效果】\r\n①：我方的“宝玉兽”怪兽与对手怪兽进行战斗的伤害计算时，可释放我方手牌、场上的此卡并发动。进行该战斗之我方怪兽，仅限在伤害计算时，攻击力、守备力变成原本数值的两倍，并在伤害步骤结束时被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14470845,'扰乱怪二人组',replace(replace('①：将２只“扰乱怪衍生物”（兽族・光・星２・攻０／守１０００）以守备表示特殊召唤至对手场上。此衍生物不可为上级召唤解放。“扰乱怪衍生物”被破坏时，每有１只，其控制者受到３００伤害。\r\n②：将墓地的此卡除外可以发动。从牌组将２只卡名不同的“扰乱怪”怪兽特殊召唤。此效果在此卡被送至墓地的回合不可发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14470846,'扰乱怪衍生物','由「扰乱怪二人组」的效果特殊召唤。这衍生物不能为上级召唤而解放。「扰乱衍生物」被破坏时那控制者受到每1只300伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14470847,'扰乱怪衍生物','由「扰乱怪二人组」的效果特殊召唤。这衍生物不能为上级召唤而解放。「扰乱衍生物」被破坏时那控制者受到每1只300伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14472500,'蟑螂宝宝','此卡因战斗被破坏并送入墓地时可发动。从牌组将１只攻击力１５００或以下的昆虫族怪兽加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14478717,'书灵师・阻止',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：自己场上存在“书灵师”怪兽的情况下，以对手场上的1只表侧表示怪兽为对象可以发动。此回合，该表侧表示怪兽不可作为融合・同步・超量・连接召唤的素材。\r\n②：在自己・对手的结束阶段，自己场上不存在“书灵师”仪式怪兽的情况下发动。将此卡送至墓地。','\r',char(13)),'\n',char(10)),'不可作为素材','「书灵师・阻止」效果适用中','此卡送至墓地','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14504454,'恶之魔娘 爱丽斯','此卡名的①③效果１回合仅可各使用１次。①：从自己的手牌・墓地将１张陷阱卡除外可以发动。从手牌将此卡特殊召唤。②：此卡召唤成功时，以自己墓地的１只“恶之魔娘”怪兽为对象可以发动。将该怪兽特殊召唤。③：此卡被解放的情况下，或因对手被破坏的情况下可以发动。从牌组将１只“恶之魔娘 爱丽斯”以外的、攻击力・守备力合计为２０００的恶魔族怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14505685,'电子界转换器',replace(replace('以此卡牌名的①方法进行的特殊召唤１回合只可使用１次。\r\n①：我方场上的怪兽仅是电子界族怪兽的场合，此卡可从手牌特殊召唤。\r\n②：此卡召唤成功时，可以我方场上的１只表侧表示怪兽为对象发动。直至回合结束时，该怪兽的种族变成电子界族。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14506878,'二足炮台','①：此卡反转的场合，以我方墓地１只等级４怪兽为对象发动。该怪兽加入手牌。','加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14507213,'同步素材','可选择对手场上的１只表侧表示怪兽并发动。此回合我方进行同步召唤的场合，可将被选择怪兽作为同步素材。发动此卡的回合，我方不进行战斗阶段。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14509651,'诅咒恋尸狂',replace(replace('此卡不可通常召唤，仅可以卡牌的效果进行特殊召唤。\r\n此卡牌名的①②效果１回合只可各使用１次。\r\n①：可以我方被除外的３只恶魔族怪兽为对象发动。从手牌特殊召唤此卡，并将对象之怪兽返回至牌组。\r\n②：怪兽区的此卡因对手被破坏并送入墓地之回合的结束阶段发动。从墓地特殊召唤此卡。之后，可挑选对手场上的卡牌并破坏，其数量最多是我方场上魔法、陷阱卡之卡牌名种类的数量。','\r',char(13)),'\n',char(10)),'','','是否选对手的卡破坏？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14512825,'南瓜马车',replace(replace('①：只要此卡存在于怪兽区，我方的“灰姑娘”可直接攻击。\r\n②：只要此卡存在于怪兽区，我方场上的“急流山的金宫”不会因效果被破坏，也不会成为对手效果的对象。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14513016,'灵兽使的长老',replace(replace('自己１回合仅可特殊召唤１次“灵兽使的长老”。\r\n①：此卡召唤时适用。此回合自己除通常召唤外仅可追加１次，在自己的主要阶段召唤１只“灵兽”怪兽。','\r',char(13)),'\n',char(10)),'使用「灵兽使的长老」的效果召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14513273,'霸王门的魔术师',replace(replace('←1 【灵摆】 1→\r\n此卡名的②灵摆效果１回合仅可使用１次。\n①：自己场上的“霸王龙扎克”不可因对手的效果除外。\n②：在自己的主要阶段可以发动。破坏此卡，从手牌・牌组将“霸王门的魔术师”以外的１只“霸王门”灵摆怪兽放在自己的灵摆区域。\r\n【怪兽效果】\r\n此卡名的①②怪兽效果１回合仅可各使用１次。\n①：自己的灵摆区域存在“霸王门的魔术师”以外的“霸王门”卡的情况下可以发动。从手牌・额外牌组将“灵摆龙”、“超量龙”、“同步龙”、“结合龙”怪兽中的１只送至墓地，从手牌将此卡特殊召唤。\n②：此卡特殊召唤的情况下可以发动。从牌组将除魔法师族怪兽以外的、１张记载有“霸王龙扎克”卡名的卡加入手牌。','\r',char(13)),'\n',char(10)),'此卡从手牌特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14517422,'堕天使的戒坛',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从自己墓地将1只“堕天使”怪兽以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14529511,'冥骸王－冥铭途兰泰库特利卡',replace(replace('“冥铭途”怪兽×３\r\n此卡名的①②③效果１回合仅可各使用１次，①②效果不可在同一连锁上发动。\r\n①：此卡融合召唤的情况下可以发动。从牌组・额外牌组将３张“冥铭途”卡送至墓地。\r\n②：在自己・对手回合中，以相同数量的自己场上的“冥铭途”怪兽和对手场上的卡为对象可以发动。将该卡破坏。\r\n③：将墓地的此卡除外可以发动。从牌组将１张“冥骸府－冥铭途兰”加入手牌。','\r',char(13)),'\n',char(10)),'送至墓地','场上卡片破坏','牌组检索','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14531242,'红色独眼巨人','侍奉“冥界的魔王 哈・迪斯”的独眼巨人。用尖角攻击来粉碎敌人。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14532163,'闪电风暴',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：自己场上不存在表侧表示的卡的情况下，可从以下效果中选择1个发动。\r\n●将对手场上攻击表示的怪兽全部破坏。\r\n●将对手场上的魔法・陷阱卡全部破坏。','\r',char(13)),'\n',char(10)),'对手场上的攻击表示怪兽全部破坏','对手场上的魔法·陷阱卡全部破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14532164,'闪电风暴',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：自己场上不存在表侧表示的卡的情况下，可从以下效果中选择1个发动。\r\n●将对手场上攻击表示的怪兽全部破坏。\r\n●将对手场上的魔法・陷阱卡全部破坏。','\r',char(13)),'\n',char(10)),'对手场上的攻击表示怪兽全部破坏','对手场上的魔法·陷阱卡全部破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14536035,'暗黑古雷法',replace(replace('①：此卡可从手牌将１只等级５以上的暗属性怪兽舍弃来从手牌特殊召唤。\r\n②：１回合１次，从手牌将１只暗属性怪兽舍弃可以发动。从牌组将１只暗属性怪兽送至墓地。','\r',char(13)),'\n',char(10)),'特殊召唤','送至墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14541657,'黄昏的忍者－新月',replace(replace('“黄昏的忍者－新月”的②效果１回合只可使用１f次。\r\n①：只要此卡存在于怪兽区，对手不可以其他的“忍者”怪兽作为攻击对象，也不可作为效果对象。\r\n②：此卡因战斗或对手效果被破坏并送入墓地的场合可发动。从牌组将１只除“黄昏的忍者－新月”以外的“忍者”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14550855,'无限狱狱火','挑选最多２张我方手牌并舍弃。之后，从牌组将相当于舍弃数量的冠有“无限狱”之名的卡牌送入墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14553285,'奥法魔术士／爆裂',replace(replace('此卡不可通常召唤，仅可通过“爆裂模式”的效果特殊召唤。\r\n①：此卡特殊召唤的情况下发动。在此卡上放2个魔力计数物。\r\n②：此卡的攻击力上升此卡魔力计数物的数量×1000的数值。\r\n③：去除此卡的2个魔力计数物可以发动。将对手场上的卡全部破坏。\r\n④：场上的此卡被破坏时，以自己墓地的1只“奥法魔术士”为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'放置魔力计数物','破坏','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14554127,'和平雕像',replace(replace('①：此卡发动后，变为拥有以下效果的效果怪兽（岩石族・地・星4・攻/守1800），特殊召唤至怪兽区域（也视为陷阱卡）。\r\n●在自己・对手回合中，支付800LP可以发动（此卡名的此效果1回合仅可使用1次）。将“和平雕像”以外的自己墓地・除外状态的1张永续陷阱卡、视为卡名为“和平雕像”的通常怪兽（岩石族・地・星4・攻/守1000）特殊召唤（不视为陷阱卡）。','\r',char(13)),'\n',char(10)),'发动','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14556954,'豪回游鲸 VIP鲸鱼',replace(replace('①：此卡可通过解放任意数量的怪兽来以表侧表示上级召唤。\r\n②：此卡上级召唤的情况下可以发动。依为上级召唤此卡而解放的怪兽的数量，在此卡上放VIP计数物。\r\n③：对手发动魔法・陷阱・怪兽的效果时，去除此卡的1个VIP计数物可以发动。掷1次硬币，猜正反。猜中的情况下，将该效果无效。猜错的情况下，此卡的原本的攻击力直至回合结束时为止变为一半。','\r',char(13)),'\n',char(10)),'解放任意数量怪兽召唤','放置计数物','投掷硬币','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14558127,'灰流丽',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：包含以下其中任意效果的魔法・陷阱・怪兽的效果发动时，从手牌将此卡舍弃可以发动。将该效果无效。\r\n●从牌组将卡加入手牌的效果\r\n●从牌组将怪兽特殊召唤的效果\r\n●从牌组将卡送至墓地的效果','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14558128,'灰流丽',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：包含以下其中任意效果的魔法・陷阱・怪兽的效果发动时，从手牌将此卡舍弃可以发动。将该效果无效。\r\n●从牌组将卡加入手牌的效果\r\n●从牌组将怪兽特殊召唤的效果\r\n●从牌组将卡送至墓地的效果','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14558129,'灰流丽',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：包含以下其中任意效果的魔法・陷阱・怪兽的效果发动时，从手牌将此卡舍弃可以发动。将该效果无效。\r\n●从牌组将卡加入手牌的效果\r\n●从牌组将怪兽特殊召唤的效果\r\n●从牌组将卡送至墓地的效果','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14568951,'青龙忍者','１回合１次，可从手牌舍弃１只冠有“忍者”之名的怪兽和１张冠有“忍法”之名的卡牌，选择对手场上的１只表侧表示怪兽并发动。此回合，被选择怪兽不可攻击，效果被无效化。此效果在对手回合也可发动。','效果无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14575467,'僵尸男孩',replace(replace('两个人感情真好\r\n死也在一起 重生也要一起\r\n从不分离\r\n所以两人再也不会相遇','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14577226,'风魔女－冬铃',replace(replace('协调＋1只以上协调以外的风属性怪兽\r\n此卡名的①②效果1回合仅可各使用1次。①：以自己墓地的1只“风魔女”怪兽为对象可以发动。给予对手相当于该怪兽等级×200的数值的伤害。②：在自己・对手的战斗阶段，以自己场上的1只“风魔女”怪兽为对象可以发动。将1只拥有该怪兽等级以下的等级的怪兽从手牌特殊召唤。以此效果特殊召唤的怪兽在此回合不可攻击。','\r',char(13)),'\n',char(10)),'伤害','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14602126,'超量输入','此卡名的卡１回合仅可发动１张。①：以自己场上的１只超量怪兽与对手场上的１只攻击力在其攻击力以下的怪兽为对象可以发动。将该对手的怪兽重叠在该自己的怪兽下方作为超量素材。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14604710,'星遗物之胎导',replace(replace('此卡名的卡1回合仅可发动1张。①：可从以下效果中选择1个发动。\r\n●从手牌将1只等级9怪兽特殊召唤。\r\n●以自己场上的1只等级9怪兽为对象可以发动。将2只与该怪兽原本种族・属性不同的等级9怪兽从牌组特殊召唤（同名卡最多1张）。以此效果特殊召唤的怪兽不可攻击，将在结束阶段被破坏。','\r',char(13)),'\n',char(10)),'从手牌特殊召唤','从牌组特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14613029,'混合变形斗士','我方场上存在有２只或以上冠有“变形斗士”之名怪兽的场合，可选择对手场上的２张卡牌并发动。对手从中挑选１张并破坏该卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14618326,'红色忍者','反转：选择场上的１张陷阱卡并将其破坏。选择被盖牌的卡牌的场合，翻开该卡进行确认，若为陷阱卡则破坏，魔法卡的场合则恢复原状。','陷阱破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14624296,'超重武者装魂 双角','此卡名的②效果１回合仅可使用１次。①：在自己的主要阶段，以自己场上的１只“超重武者”怪兽为对象可以发动。从自己的手牌・场上将此怪兽视为装备卡，装备于该自己的怪兽。装备怪兽在１次战斗阶段中可攻击２次。②：此卡是以此卡的效果被装备中的情况下可以发动。将被装备的此卡特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14625090,'龙女仆的迎候',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：自己场上的怪兽的攻击力・守备力上升相当于自己场上“龙女仆”怪兽数量×100的数值。\r\n②：自己场上存在2只以上“龙女仆”怪兽的情况下，以“龙女仆的迎候”以外的、自己墓地的1张“龙女仆”卡为对象可以发动。将该卡加入手牌。\r\n③：此卡被送至墓地的情况下发动。此回合中，对手不可将自己场上的“龙女仆”怪兽作为效果的对象。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14644902,'幻想召唤师','①：此卡反转的场合发动。解放除此卡以外的我方场上的１只怪兽，并从额外牌组特殊召唤１只融合怪兽。以此效果特殊召唤的融合怪兽在该回合的结束阶段被破坏。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14677495,'极星兽 坦格乔斯特','我方场上的怪兽因战斗被破坏并送入墓地时，可从手牌特殊召唤此卡。１回合１次，场上守备表示的此卡变成表侧攻击表示时可发动。以守备表示从牌组特殊召唤１只除“极星兽 坦格乔斯特”以外冠有“极星兽”之名的怪兽。','从手牌特殊召唤','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14702066,'百万加农炮机械兵','可解放２只我方场上的怪兽并发动。给予对手生命１５００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14708569,'阿罗妮','花中的女性散发着有毒的花粉。不可以靠近她。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14729426,'来自行星的物体A','在战斗阶段结束时，获得向攻击表示的此卡攻击的怪兽的控制权。','得到控制权','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14730606,'常春藤枷锁','我方回合中，所有对手场上的怪兽变成植物族。场上表侧表示的此卡因对手效果被破坏并送入墓地时，从我方牌组抽取１张卡牌。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14731897,'结束 UNITY','①：可以我方场上的１只表侧表示怪兽为对象发动。直至回合结束时，该怪兽的守备力变成我方场上全部表侧表示怪兽原本守备力的合计数值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14733538,'龙呼相争',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：从牌组将１只“龙剑士”灵摆怪兽和１只“龙魔王”灵摆怪兽出示给对手，对手从其中随机挑选１只。将对手挑选的灵摆怪兽放在自己的灵摆区域或特殊召唤。将剩余的灵摆怪兽以表侧加入自己的额外牌组。','\r',char(13)),'\n',char(10)),'是否在灵摆区域放置？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14735698,'影灵衣的降魔镜',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：为使合计等级与仪式召唤的怪兽相等，解放自己手牌・场上的怪兽，或作为解放的代替将自己墓地的“影灵衣”怪兽除外，从手牌将1只“影灵衣”仪式怪兽仪式召唤。\r\n②：自己场上不存在怪兽的情况下，从自己墓地将1只“影灵衣”怪兽和此卡除外可以发动。从牌组将1张“影灵衣”魔法卡加入手牌。','\r',char(13)),'\n',char(10)),'加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14745409,'圣剑加拉廷',replace(replace('仅限装备战士族怪兽。\r\n此卡牌名的③效果１回合只可使用１次。\r\n①：我方场上只可有１张“圣剑加拉廷”以表侧表示存在。\r\n②：装备怪兽的攻击力上升１０００，每次我方的准备阶段下降２００。\r\n③：场上表侧表示的此卡被破坏并送入墓地的场合，可以我方场上的１只战士族“圣骑士”怪兽为对象发动。将此卡装备该我方的战士族“圣骑士”怪兽。','\r',char(13)),'\n',char(10)),'装备','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14756848,'超重武者 盗人－１０','①：自己的墓地不存在魔法・陷阱卡的情况下，此卡可从手牌中特殊召唤。以此方法特殊召唤成功的余下本回合，自己仅可特殊召唤“超重武者”怪兽。②：解放此卡，可从以下效果中选择１个发动。●挑选对手魔法与陷阱区域的１张卡破坏。然后，可将该破坏的魔法・陷阱卡放置在自己场上。●挑选对手灵摆区域的１张卡破坏。然后，可将所破坏的该卡放在自己的灵摆区域。','·。·','对手的魔法与陷阱区域1张卡破坏','选对手的灵摆区域1张卡破坏','把破坏的那张魔法·陷阱卡在自己场上放置？','把破坏的那张卡在自己的灵摆区域放置？','','','','','','','','','','','');
INSERT INTO texts VALUES(14759024,'星圣 天秤埃斯卡','①：此卡召唤・特殊召唤时可以发动。从牌组将1只“星圣”怪兽加入手牌。','牌组检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14761450,'企鹅勇士',replace(replace('此卡名的①②效果1回合仅可各使用1次，要以此卡作为同步素材的情况下，仅可使用于水属性怪兽的同步召唤。\r\n①：自己场上有怪兽被放置的情况下可以发动。从手牌将此卡特殊召唤。然后，可将此卡的等级下降1或2。\r\n②：以自己场上的1只里侧守备表示怪兽为对象可以发动。将该怪兽改成表侧守备表示。以此效果将“企鹅”怪兽以外的怪兽改成了表侧守备表示的情况下，其效果无效化。','\r',char(13)),'\n',char(10)),'特殊召唤','','等级下降1星','等级下降2星','什么都不做','','','','','','','','','','','');
INSERT INTO texts VALUES(14763299,'幻奏的歌姬索罗',replace(replace('①：对手场上存在有怪兽，且我方场上不存在有怪兽的场合，此卡可从手牌特殊召唤。\r\n②：此卡因战斗被破坏并送入墓地时可发动。从牌组特殊召唤１只除“幻奏的歌姬索罗”以外的“幻奏”怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14771222,'绝海的骑士','１回合１次，场上表侧表示的此卡变更表示形式时，从牌组将１只水属性怪兽送入墓地。','牌组送墓','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14772491,'魂之共享','可选择场上的１只表侧表示怪兽并发动。从我方手牌将１只冠有“新空间人”之名的怪兽特殊召唤至被选择怪兽控制者的场上。被选择怪兽的攻击力上升以此效果特殊召唤的冠有“新空间人”之名怪兽的攻击力数值。此卡从场上离开时，以此卡效果特殊召唤的冠有“新空间人”之名的怪兽返回至持有者手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14778250,'诡术师','①：舍弃1张手牌，可将此卡从手牌特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14785765,'黑羽－精锐之仄费罗斯',replace(replace('此卡名的效果在决斗中仅可使用1次。\r\n①：此卡存在于墓地的情况下，将自己场上的1张表侧表示的卡放回手牌可以发动。将此卡特殊召唤，自己受到400伤害。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14799437,'狱炎机・拿赫摩斯',replace(replace('此卡不可通常召唤。\r\n仅可在自己场上的效果怪兽的等级・阶级的合计为８以下时，将自己的手牌・墓地的３只“狱炎机”怪兽除外的情况下从手牌・墓地特殊召唤。\r\n①：此卡特殊召唤时可以发动。将场上其他的怪兽全部破坏。\r\n②：１回合１次，魔法・陷阱卡的效果发动时，解放自己场上的１只怪兽可以发动。将该发动无效并除外。','\r',char(13)),'\n',char(10)),'怪兽破坏','魔法·陷阱卡的发动无效并除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14812471,'转生炎兽 烽火猞猁',replace(replace('等级４以下的电子界族怪兽１只\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡连接召唤的情况下可以发动。从牌组将１张“转生炎兽之圣域”加入手牌。\r\n②：自己场上的“转生炎兽”卡将被战斗・效果破坏的情况下，作为代替可将墓地的此卡除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14812659,'觉星师莱兹贝尔特','１回合１次，可选择１只场上的表侧表示怪兽并发动。被选择怪兽的等级上升１级。此效果在对手回合也可发动。','等级上升1','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14816688,'洗牌重生',replace(replace('此卡牌名的②效果１回合只可使用１次。\r\n①：我方场上不存在怪兽的场合，可以我方墓地的１只怪兽为对象发动。特殊召唤该怪兽。以此效果特殊召唤的怪兽的效果被无效化，并在结束阶段被除外。\r\n②：可除外墓地中的此卡，并以我方场上的１张卡牌为对象发动。该卡返回至持有者的牌组并洗牌，之后我方从牌组抽取１张卡牌。在该回合结束阶段，除外１张我方手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','回到牌组','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14816857,'铁兽战线 纳贝尔',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从自己墓地将任意数量的兽族・兽战士族・鸟兽族怪兽除外可以发动。从额外牌组将1只连接标记与除外数量相同的兽族・兽战士族・鸟兽族连接怪兽特殊召唤。此效果发动后，直至回合结束时为止，自己仅可以兽族・兽战士族・鸟兽族怪兽作为连接素材。\r\n②：此卡被送至墓地的情况下可以发动。从牌组将“铁兽战线 纳贝尔”以外的1只“铁兽”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14821890,'相剑暗转','此卡名的①②效果１回合仅可各使用１次。①：以自己场上的１只幻龙族怪兽和对手场上的２张卡为对象可以发动。将该卡破坏。②：此卡被除外的情况下可以发动。将１只“相剑衍生物”（幻龙族・协调・水・星４・攻／守０）特殊召唤至自己场上。只要以此效果特殊召唤的衍生物存在，自己从额外牌组仅可特殊召唤同步怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14821891,'相剑衍生物','由“相剑”卡片的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14824019,'魔导书士 巴泰尔','①：此卡召唤・反转的情况下发动。从牌组将1张“魔导书”魔法卡加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14839621,'嘣床',replace(replace('指定１处未使用的怪兽区域可以发动此卡。\r\n①：效果怪兽被特殊召唤至所指定的区域的情况下发动。将存在于该区域的怪兽和此卡合计共２张放回持有者的手牌。','\r',char(13)),'\n',char(10)),'2张卡回到手牌','选择双方主要怪兽区域','选择左侧额外怪兽区域','选择右侧额外怪兽区域','','','','','','','','','','','','');
INSERT INTO texts VALUES(14851496,'海月－水母－','漂浮于海中的水母，半透明的身体使人难以察觉。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14878871,'救援猫',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：将场上的此卡送至墓地可以发动。从牌组将2只等级3以下的兽族怪兽特殊召唤。以此效果特殊召唤的怪兽的效果无效化，将在结束阶段被破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14878872,'救援猫',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：将场上的此卡送至墓地可以发动。从牌组将2只等级3以下的兽族怪兽特殊召唤。以此效果特殊召唤的怪兽的效果无效化，将在结束阶段被破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14882493,'极夜的骑士盖亚',replace(replace('“极夜的骑士盖亚”的以下效果１回合只可各使用１次。\r\n●可释放我方场上１只除此卡以外的暗属性怪兽并发动。从牌组将１只战士族、光属性、等级４的怪兽加入手牌，之后挑选１张手牌并送入墓地。\r\n●可从我方墓地将１只光属性怪兽除外，并选择我方场上的１只怪兽发动。直至对手回合结束时，被选择怪兽的攻击力上升５００点。','\r',char(13)),'\n',char(10)),'牌组检索','攻击力上升','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14883228,'台风','对手场上有2张以上的魔法・陷阱卡存在，自己场上没有魔法・陷阱卡存在的情况下，此卡也可从手牌发动。①：以场上的1张表侧表示魔法・陷阱卡为对象可以发动。将该卡破坏。','适用「台风」的效果来发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14886190,'电脑堺都－九龙',replace(replace('此卡名的卡１回合仅可发动１张。①：从牌组将１张“电脑堺门”卡以表侧表示放在自己的魔法与陷阱区域。然后，可根据自己场上“电脑堺门”卡的数量分别适用以下效果。\r\n●２张以上：此回合，自己场上“电脑堺”怪兽的攻击力上升２００。\r\n●３张以上：从自己的牌组上面将３张卡送至墓地。\r\n●４张：从额外牌组将最多４只“电脑堺”怪兽特殊召唤（同名卡最多１张）。','\r',char(13)),'\n',char(10)),'从牌组放置','是否把怪兽的攻击力上升？','是否从牌组把卡送至墓地？','是否从额外牌组特殊召唤？','','','','','','','','','','','','');
INSERT INTO texts VALUES(14886469,'红莲赛马',replace(replace('此卡名的效果１回合仅可使用１次。\r\n①：此卡召唤・特殊召唤时，如果自己场上没有其他怪兽存在则可以发动。从自己的手牌・墓地将１只等级３以下的恶魔族协调特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14898066,'血战士','以做尽坏事而引以为荣的魔兽人，手上的斧头总是沾满鲜血。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14898067,'血战士','以做尽坏事而引以为荣的魔兽人，手上的斧头总是沾满鲜血。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14920218,'贱龙的魔术师',replace(replace('←2 【灵摆】 2→\r\n此卡名的灵摆效果１回合仅可使用１次。①：另一方自己的灵摆区域有“魔术师”卡存在的情况下可以发动。将自己额外牌组“贱龙的魔术师”以外的１只表侧表示“魔术师”灵摆怪兽或“异色眼”灵摆怪兽加入手牌。\r\n【怪兽效果】\r\n此卡名的怪兽效果１回合仅可使用１次。①：此卡召唤・特殊召唤成功的情况下，以自己墓地“贱龙的魔术师”以外的１只“魔术师”灵摆怪兽或“异色眼”怪兽为对象可以发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14934922,'转生炎兽的愤怒',replace(replace('这个卡名的卡1个回合只能发动1张。①：可以从以下效果选择1个发动。\r\n●从手牌以及自己场上的表侧表示怪兽中把1只“转生炎兽”怪兽送至墓地，可以场上1张卡为对象发动。破坏这张卡。\r\n●可对用和自身同名的怪兽为素材进行连接召唤的自己场上1只“转生炎兽”连接怪兽为对象发动。挑选张数至多为该怪兽的连接标记数量的对手场上的卡进行破坏。','\r',char(13)),'\n',char(10)),'破坏1张卡','破坏连接标记数量的卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14936691,'异虫伊洛金','此卡不可特殊召唤。１回合１次，可选择场上的１只冠有“异虫”之名的爬虫类族将其变成里侧守备表示。','变更表示形式','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14943837,'残骸龙','此卡作为同步素材的情况下，仅可用于龙族怪兽的同步召唤，其他的同步素材怪兽必须全部是等级4以外的怪兽。①：此卡召唤成功时，以1只自己墓地攻击力500以下的怪兽为对象可以发动。将该怪兽以攻击表示特殊召唤。以此效果特殊召唤的怪兽的效果无效化。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14957440,'落魂',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：只要自己场上有协调以外的怪兽存在，对手不可将此卡选择为攻击对象。\r\n②：怪兽从场上被送至对手墓地的情况下发动。在此卡上放１个落魂计数物。然后，将“落魂衍生物”（兽族・地・星１・攻／守？）特殊召唤至自己场上，数量最多为此卡落魂计数物的数量。此衍生物的等级依此卡落魂计数物的数量上升，攻击力・守备力变为其等级×５００的数值。','\r',char(13)),'\n',char(10)),'','是否继续特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14957441,'落魂衍生物','由“落魂”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14959144,'天极辉士－熊斗龙巧阿尔法',replace(replace('此卡名在规则上也视为“北斗天熊”卡、“龙机巧”卡。\r\n此卡不可通常召唤，仅可以卡的效果特殊召唤。\r\n此卡名的效果１回合仅可使用１次。\r\n①：“天极辉士－熊斗龙巧阿尔法”以外的、“北斗天熊”怪兽或“龙机巧”怪兽存在于自己场上的情况下可以发动。从手牌将此卡特殊召唤。然后，可从牌组将１张“北斗天熊”魔法・陷阱卡或“龙机巧”魔法・陷阱卡加入手牌。','\r',char(13)),'\n',char(10)),'','是否从牌组把魔法·陷阱卡加入手牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14965712,'增殖的库里波！',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：对手发动怪兽的效果时，或对手怪兽攻击宣言时可以发动。从手牌将此卡特殊召唤。\r\n②：1回合1次，对手发动场上的怪兽的效果时，或对手怪兽攻击的伤害计算时可以发动。从自己牌组・墓地挑选1只“黑魔导”或攻击力300/守备力200的怪兽，加入手牌或特殊召唤。然后，可将该对手怪兽的攻击力改成0。','\r',char(13)),'\n',char(10)),'特殊召唤','检索效果','是否把攻击力变成0？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14965713,'增殖的库里波！',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：对手发动怪兽的效果时，或对手怪兽攻击宣言时可以发动。从手牌将此卡特殊召唤。\r\n②：1回合1次，对手发动场上的怪兽的效果时，或对手怪兽攻击的伤害计算时可以发动。从自己牌组・墓地挑选1只“黑魔导”或攻击力300/守备力200的怪兽，加入手牌或特殊召唤。然后，可将该对手怪兽的攻击力改成0。','\r',char(13)),'\n',char(10)),'特殊召唤','检索效果','是否把攻击力变成0？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14970113,'十二兽 申锤',replace(replace('等级4怪兽×3只以上\r\n“十二兽 申锤”1回合1次，也可重叠在同名卡以外的、自己场上的“十二兽”怪兽上面来超量召唤。\r\n①：此卡的攻击力・守备力分别上升此卡持有的超量素材中“十二兽”怪兽的相应数值。\r\n②：只要持有超量素材的此卡存在于怪兽区域，对手不可将场上的其他“十二兽”怪兽作为效果的对象。\r\n③：在自己・对手的结束阶段发动。去除此卡的1个超量素材。','\r',char(13)),'\n',char(10)),'是否在「十二兽」怪兽上面重叠来超量召唤？','此卡1个超量素材取除','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14972952,'华耳琴璃・承继',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：自己场上存在“华耳琴璃”连接怪兽，且怪兽的效果・魔法・陷阱卡发动时可以发动。将该发动无效并破坏。\r\n②：将墓地的此卡除外可以发动。将“华耳琴璃・承继”以外的、自己额外牌组（表侧）・墓地・除外状态的“华耳琴璃”卡放回牌组，数量最多为自己场上的响鸣计数物的数量。然后，所放回的卡每有３张，自己可抽１张。','\r',char(13)),'\n',char(10)),'发动无效并破坏','回收','是否抽牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14977074,'加鲁撒斯','头部是龙的兽战士。他的斧头攻击相当强劲。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14983497,'霞之谷的幼怪鸟','①：此卡从手牌被送至墓地时可以发动。将此卡特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(14989021,'神鸟 西摩格','此卡不可特殊召唤。上级召唤此卡的场合，解放怪兽必须是风属性怪兽。只要此卡以表侧表示存在于场上，双方玩家在每次双方的结束阶段受到１０００点伤害。此时，各个玩家受到的伤害减少相当于控制的魔法、陷阱卡数量×５００点。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15001619,'傀偶女王',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：对手用抽卡以外的方式从牌组中将怪兽加入手牌时可以发动。从手牌将此卡特殊召唤。\r\n②：此卡召唤・特殊召唤成功的情况下可以发动。从自己的手牌・墓地中挑选１只战士族・地属性・等级７的怪兽特殊召唤。以此效果特殊召唤“傀偶国王”的情况下，自己场上的全部战士族・地属性怪兽的攻击力直至下个回合结束时为止上升１０００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15001940,'肥肝之佛格雷希亚・饿魔新飨',replace(replace('以“食谱”卡降临\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡特殊召唤的情况下，以自己・对手墓地的合计最多３张卡为对象可以发动。将该卡放回牌组。\r\n②：场上的怪兽成为攻击・效果的对象时可以发动。解放自己场上的１只“饿魔新飨”怪兽和自己・对手场上的１只攻击表示怪兽，从手牌・牌组将１只等级５・６的“饿魔新飨”仪式怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'墓地的卡回到牌组','从手牌·牌组特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15005145,'重装百夫骑士 普莉梅拉',replace(replace('此卡名的①③效果１回合仅可各使用１次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将１张“重装百夫骑士 普莉梅拉”以外的“百夫骑”卡加入手牌。此回合，自己不可特殊召唤“重装百夫骑士 普莉梅拉”。\r\n②：此卡视为永续陷阱卡的情况下，自己场上等级５以上的“百夫骑”怪兽不会因效果被破坏。\r\n③：此卡视为永续陷阱卡的情况下，在自己・对手的主要阶段可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15013468,'安德鲁・斯芬克斯','此卡不可从墓地特殊召唤。场上存在有“光之金字塔”的场合，此卡可支付５００LP从手牌特殊召唤。此卡於进行了召唤、特殊召唤的回合不可攻击。此卡因战斗破坏守备表示怪兽的场合，给予对手生命相当於被破坏怪兽的攻击力一半的伤害。','LP伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15023985,'岩石巨人','巨大岩石堆积而成的岩石巨人。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15025844,'圣精灵','虽是柔弱的精灵，但会以神圣力量保护身体，守备力很高。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15028680,'超念导体 铋希摩斯',replace(replace('协调＋协调以外的怪兽1只以上\r\n①：此卡与对手怪兽进行战斗的伤害计算后可以发动。将进行了该战斗的各自的怪兽除外。','\r',char(13)),'\n',char(10)),'除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15033525,'烈焰火星',replace(replace('“烈焰火星”的②效果１回合仅可使用１次。\r\n①：此卡存在于手牌・墓地的情况下，将自己的墓地中除此卡以外的３只怪兽除外可以发动。将此卡特殊召唤。此效果发动后，直至回合结束时为止，自己不可特殊召唤怪兽。\r\n②：在自己的主要阶段１，将自己场上除此卡以外的所有怪兽送至墓地可以发动。给予对手送至墓地的怪兽的数量×５００点伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15042735,'龙卷风妖','肆虐荒野的龙卷风，用风之刃切割对手。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15052462,'紫水晶','仅限装备不死族怪兽。令１只装备怪兽的攻击力和守备力上升３００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15066114,'分段龙',replace(replace('①：此卡无需解放即可通常召唤。\r\n②：以此卡的①方法通常召唤的此卡原本的攻击力・守备力变为一半。\r\n③：１回合１次，此卡是被通常召唤的情况下可以发动。将表侧表示的此卡破坏，将主要怪兽区域拥有其攻击力以下的攻击力的怪兽全部破坏。此效果在对手回合中也可以发动。','\r',char(13)),'\n',char(10)),'不用解放召唤','怪兽破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15079028,'地久神－碳','此卡名的①②效果１回合１次，仅可使用其中１个。①：解放通常召唤的此卡可以发动。从牌组将“地久神－碳”以外的１只天使族・地属性怪兽加入手牌。②：此卡存在于墓地的状态下，自己场上的表侧表示天使族怪兽被送至墓地的情况下可以发动。将此卡放回牌组最上面。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15083304,'未界域的危险地带','此卡名的卡1回合仅可发动1张。①：自己从牌组抽3张。然后从手牌将包括1张以上“未界域”卡的2张卡舍弃。手牌没有“未界域”卡的情况下，将手牌全部公开，放回牌组。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15083728,'粘胶带之家','可在对手召唤、反转召唤守备力５００以下的怪兽时发动。破坏１只该怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15090429,'暴风小子','上级召唤风属性怪兽的情况下，此卡可作为２只解放。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15092394,'急袭猛禽－异邦猎鹰',replace(replace('等级5怪兽×2\r\n①：此卡持有超量怪兽作为超量素材的情况下获得以下效果。\r\n●1回合1次，去除此卡的1个超量素材，以对手场上的1只怪兽为对象可以发动。破坏该怪兽，给予对手相当于其原本攻击力数值的伤害。\r\n②：此卡因对手被破坏并被送至墓地的情况下，以自己墓地1只“急袭猛禽-异邦猎鹰”以外的“急袭猛禽”超量怪兽为对象可以发动。将该怪兽特殊召唤，将此卡重叠在该怪兽下方作为超量素材。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15094540,'格布林百罗刹大危机',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：以自己场上的１只“格布林”怪兽和对手场上的１只怪兽，或自己墓地的１只“格布林”怪兽和对手墓地的１只怪兽为对象可以发动。将该２只怪兽除外。\r\n②：将魔法与陷阱区域的表侧表示的此卡送至墓地，以自己除外状态的５只“格布林”怪兽为对象可以发动（同名卡最多１张）。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'除外','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15103313,'肉身佛','选择我方场上的１只怪兽并送入墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15123983,'星鼠侠',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡同步召唤的情况下，舍弃1张手牌可以发动。从自己墓地将作为其同步素材的1只怪兽特殊召唤。以此效果特殊召唤的怪兽视为协调。\r\n②：此卡存在于墓地的情况下，舍弃2张手牌可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'特殊召唤素材','此卡特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15130912,'弈勇之射手－西园',replace(replace('←1 【灵摆】 1→\r\n此卡名的灵摆效果１回合仅可使用１次。①：在自己的主要阶段可以发动。将此卡特殊召唤至正面的自己的主要怪兽区域。此效果发动后，直至回合结束时为止自己仅可特殊召唤“弈勇”怪兽（除了从额外牌组的特殊召唤以外）。\r\n【怪兽效果】\r\n此卡名的①②怪兽效果１回合仅可各使用１次。①：此卡是被特殊召唤的情况下，以场上的１只效果怪兽为对象可以发动。掷１次硬币。正面的情况下，将该怪兽的效果无效。反面的情况下，其攻击力变为一半。②：怪兽区域的此卡移动至其他怪兽区域的情况下，以场上的１张卡为对象可以发动。掷１次硬币。正面的情况下，将该卡破坏。反面的情况下，将该卡放回持有者的手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15141103,'黑暗协调 灾祸恶棍',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：向对手出示手牌的此卡可以发动。进行1只“黑暗协调”怪兽的召唤。\r\n②：1回合1次，此卡是被通常召唤的情况下可以发动。解放自己场上的此卡，和1只表侧表示的、等级低于此卡的协调以外的怪兽，根据其等级之差的数值，从额外牌组将1只相同等级的同步怪兽视为同步召唤特殊召唤。然后，可将对手场上的1张卡破坏。','\r',char(13)),'\n',char(10)),'进行召唤','同步召唤','是否把卡破坏？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15146890,'龙脉的魔术师',replace(replace('←1 【灵摆】 1→\r\n①：１回合１次，另一方自己的灵摆区域有“魔术师”卡存在的情况下，舍弃手牌的１只灵摆怪兽，以场上的１只表侧表示怪兽为对象可以发动。将该怪兽破坏。\r\n【怪兽效果】\r\n只有充满活力这一点长处的新手少年魔术师。但其实他已在不知不觉中具备了感知沉睡于大地的龙之灵魂的能力。虽然还不能独当一面，但因为天赋异禀，师傅“龙穴的魔术师”也对他另眼相看。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15150365,'白衣大盗','此卡对对手生命造成战斗伤害时，随机弃置对手１张手牌。','丢弃手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15150371,'恶魔的镜子','对映于镜中之人施以催眠术，从而避开攻击的恶魔之镜。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15155568,'破坏剑一闪',replace(replace('①：自己场上有需以“毁灭剑士”作为融合素材的融合怪兽存在的情况下可以发动。将对手场上的怪兽全部除外。\r\n②：以自己场上的“毁灭剑士”怪兽作为对象的魔法・陷阱・怪兽的效果发动时，将墓地的此卡除外可以发动。将该效果无效并破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15169262,'岩浆炎炎树海的妖女','此卡从场上被送入墓地时，直至回合结束时，我方场上所有冠有“岩浆炎”之名的怪兽的攻击力上升我方墓地冠有“岩浆炎”之名怪兽的数量×２００点。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15171722,'进化龙・滑齿龙',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将１张“通往进化的桥梁”或“进化的特异点”放置在自己场上。\r\n②：此卡被召唤或因炎属性怪兽的效果被特殊召唤的情况下，在自己的主要阶段可以发动。从牌组将１只爬虫类族・恐龙族的炎属性怪兽送至墓地。然后，可将场上的２只怪兽的种族和等级改成和送至墓地的怪兽相同。','\r',char(13)),'\n',char(10)),'','','是否改变2只怪兽的种族和等级？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15173384,'魔术幻象师 无面',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：自己场上的表侧表示的“眼纳祭魔”融合怪兽或“纳祭魔”因战斗・效果被破坏的情况下可以发动。从手牌・墓地将此卡特殊召唤。\r\n②：此卡从场上被送至墓地的情况下，以自己墓地的1只“眼纳祭魔”融合怪兽或“纳祭魔”为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15175429,'魔法热核・袭','１回合１次，对手发动了魔法卡时可以发动。破坏该魔法卡，并给予对手LP８００点伤害。','破坏并伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15177750,'惠畅之风',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：可从以下效果中选择１个发动。\r\n●从自己的手牌・场上（表侧表示）将１只植物族怪兽送至墓地可以发动。自己恢复５００LP。\r\n●以自己墓地的１只植物族怪兽为对象可以发动。将该怪兽放回牌组。然后，自己恢复５００LP。\r\n●支付１０００LP可以发动。从自己的墓地将１只“芬芳”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'送至墓地回复基本分','回到牌组回复基本分','支付基本分特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15180041,'真沉默剑士',replace(replace('此卡不可通常召唤。\r\n仅限解放１只我方场上的战士族怪兽的场合可特殊召唤。\r\n①：每次我方・对手的准备阶段发动。此卡的攻击力上升５００。\r\n②：１回合１次，魔法卡发动时可发动。使该发动无效。\r\n③：场上的此卡因战斗或对手效果被破坏的场合可发动。无视召唤条件，从手牌・牌组特殊召唤１只除“真沉默剑士”以外的“沉默剑士”怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15185344,'灿冠乘骑 迅快拉维',replace(replace('等级3怪兽×2\r\n“灿冠乘骑 迅快拉维”1回合1次，也可重叠在自己场上的攻击力2000以下的兽族怪兽上面来超量召唤。\r\n此卡不可作为超量召唤的素材。\r\n①：此卡战斗破坏怪兽的情况下发动。在此卡上放1个冠计数物。然后，根据此卡的冠计数物的数量适用以下效果。\r\n●1个：此卡的攻击力上升400。\r\n●2个：此卡的攻击力上升600。\r\n●3个：将此卡放回额外牌组，自己抽3张。','\r',char(13)),'\n',char(10)),'是否在兽族怪兽上面重叠来超量召唤？','放置计数物','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15187079,'地缚神 Uru',replace(replace('①：“地缚神”怪兽在场上仅可有1只以表侧表示存在。\r\n②：此卡可直接攻击。\r\n③：对手怪兽不可将此卡选择为攻击对象。\r\n④：不存在表侧表示的场地魔法卡的情况下，此卡将被破坏。\r\n⑤：1回合1次，解放自己场上的1只其他怪兽，以对手场上的1只表侧表示怪兽为对象可以发动。直至结束阶段为止，获得该对手的表侧表示怪兽的控制权。','\r',char(13)),'\n',char(10)),'获得控制权','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15198996,'青涩忍者',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：有怪兽以表侧表示被特殊召唤至自己场上的情况下，以其中1只为对象可以发动。从手牌将此卡特殊召唤，将对象怪兽改成里侧守备表示。\r\n②：此卡从手牌・场上被送至墓地的情况下，以场上的1只怪兽为对象可以发动。将该怪兽改成表侧攻击表示或里侧守备表示。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15216188,'时间机械－时之引擎',replace(replace('此卡名在规则上也视为“钢铁化”卡。\r\n①：自己场上的怪兽因战斗或对手的效果被破坏的情况下，以其中１只为对象可以发动。将该怪兽特殊召唤。以此效果将等级５以上的机械族怪兽特殊召唤，且自己场上或墓地存在此卡以外的“钢铁化”陷阱卡的情况下，进而可适用以下效果。\r\n●将对手场上的怪兽全部破坏。然后，可给予对手以此效果特殊召唤的怪兽其原本攻击力数值的伤害。','\r',char(13)),'\n',char(10)),'','','是否把怪兽破坏？','是否给予伤害？','','','','','','','','','','','','');
INSERT INTO texts VALUES(15232745,'编号1源数之门－壹',replace(replace('等级1的怪兽×3\r\n①：此卡在战斗中不会被破坏。\r\n②：此卡与对手怪兽进行战斗的伤害步骤结束时，去除此卡的1个超量素材后可以发动。自己场上的所有“源数”怪兽的攻击力翻倍，直至回合结束时为止。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15237615,'下裁决的女帝','“女王的影武者”＋“响女”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15240238,'霞鸟库拉索拉斯',replace(replace('协调＋协调以外的怪兽１只或以上\r\n１回合１次，可选择对手场上的１只表侧表示怪兽并发动。直至回合结束时，使被选择怪兽的攻击力变成０，并使该效果无效。','\r',char(13)),'\n',char(10)),'效果无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15248594,'炎斩机玛格玛',replace(replace('协调+1只以上协调以外的怪兽\r\n此卡名的①②效果1回合仅可各使用1次。①：此卡因战斗破坏怪兽时，可以对手场上的最多2张卡为对象发动。将该卡破坏。②：此卡因战斗或者是对手的效果被破坏的情况下可以发动。将牌组中的1张“斩机”魔法・陷阱卡加入手牌。','\r',char(13)),'\n',char(10)),'卡片破坏','牌组检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15248873,'立体书',replace(replace('“立体书”１回合只可发动１张。\r\n①：对手场地区有卡牌存在，并且我方场地区无卡牌存在的场合可发动。从牌组发动１张场地魔法卡。','\r',char(13)),'\n',char(10)),'请选择一张场地魔法卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15256925,'灭亡的咒文－死亡终极',replace(replace('①：自己场上存在等级8以上的魔法师族怪兽的情况下可以发动。将场上的1张卡以里侧除外。\r\n②：魔法与陷阱区域的此卡因对手的效果被破坏的情况下可以发动。从牌组将1只“黑混沌之魔导”或“混沌黑魔术师”无视召唤条件特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15259703,'卡通世界','支付1000LP可以发动此卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15259704,'卡通世界','支付1000LP可以发动此卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15270885,'卡通格布林突击部队',replace(replace('①：此卡在召唤・反转召唤・特殊召唤的回合不可攻击。\r\n②：自己场上存在“卡通世界”，且对手场上不存在卡通怪兽的情况下，此卡可直接攻击。\r\n③：此卡攻击的情况下，将在战斗阶段结束时变为守备表示，直至下个自己回合结束时为止，不可变更表示形式。\r\n④：场上的“卡通世界”被破坏时，此卡将被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15286412,'极星宝 根格尼尔','可将我方场上１只冠有“极神”或“极星”之名的表侧表示怪兽从游戏中除外，并选择场上的１张卡牌发动。破坏被选择卡牌。发动后第２次的我方结束阶段时，为了发动此效果将从游戏中被除外的怪兽以攻击表示返回至场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15291624,'超雷龙',replace(replace('“雷龙”＋雷族怪兽\r\n此卡仅可以融合召唤及以下方法特殊召唤。\r\n●有雷族怪兽的效果在手牌发动过的回合，解放融合怪兽以外的、自己场上的１只雷族效果怪兽的情况下可从额外牌组特殊召唤。\r\n①：只要此卡存在于怪兽区域，对手不可用抽牌以外的方法从牌组将卡加入手牌。\r\n②：场上的此卡将被战斗・效果破坏的情况下，作为代替可将自己墓地的１只雷族怪兽除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15294090,'命运幻象','我方场上表侧表示的冠有“命运－英雄”之名的怪兽因对手效果被破坏并送入墓地时可发动。将该回合被破坏并送入墓地的冠有“命运－英雄”之名的所有怪兽特殊召唤至我方场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15303296,'石像魔','会伪装成石像，从黑暗之中发动攻击。逃跑的速度也十分迅速。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15305240,'虏获装置','双方各自选择自己场上的１只怪兽，并互换所选择怪兽的控制权。但是此卡的控制者必须选择以表侧表示存在于自己场上的通常怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15306543,'星逢之神篱',replace(replace('①：１回合１次，可以发动。为使合计等级为仪式召唤的怪兽的等级以上，从自己场上的灵魂怪兽及“灵魂鸟衍生物”中将怪兽解放，从牌组将１只风属性仪式怪兽仪式召唤。\r\n②：１回合最多２次，自己场上的表侧表示风属性怪兽被放回自己手牌的情况下，可从以下效果中选择１个发动。\r\n●将自己墓地・除外状态的１只灵魂怪兽或１张仪式魔法卡加入手牌。\r\n●从牌组将１张“星逢之天河”放置在自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15308295,'魔界剧团－谐趣龙套',replace(replace('←8 【灵摆】 8→\r\n此卡名的灵摆效果1回合仅可使用1次。①：可以对手场上的1只怪兽和自己场上的1只“魔界剧团”灵摆怪兽为对象发动。交换该2只怪兽的控制权。然后，将此卡破坏。\r\n【怪兽效果】\r\n①：因此卡的战斗发生的对自己的战斗伤害变为0。②：在自己的准备阶段发动。此卡的控制权转移给对手。③：1回合1次，在此卡的控制权转移的情况下发动。此卡原本的持有者可从自身的魔法与陷阱区域挑选1张被放置的“魔界剧本”魔法卡破坏。','\r',char(13)),'\n',char(10)),'','','','是否选「魔界剧本“」魔法卡破坏？','','','','','','','','','','','','');
INSERT INTO texts VALUES(15310033,'未知同步士','以此卡名的①方法的特殊召唤在决斗中仅可有1次。①：对手场上存在怪兽，自己场上不存在怪兽的情况下，此卡可从手牌中特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15313433,'无限狱反射镜','自己场上名字带有“无限狱”的怪兽因战斗被破坏并送往自己墓地时，舍弃所有手牌，选择１只被破坏怪兽可以发动。特殊召唤被选择的怪兽，并给予对手LP１０００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15317640,'巨大战舰 盖核',replace(replace('①：此卡召唤的情况下发动。在此卡上放2个计数物。\r\n②：此卡不会因战斗被破坏。\r\n③：此卡进行战斗的伤害步骤结束时发动。此卡未放有计数物的情况下，将此卡破坏。有计数物的情况下，掷1次硬币，猜正反。猜错的情况下，去除此卡的1个计数物。','\r',char(13)),'\n',char(10)),'放置计数物','投掷硬币','破坏','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15327215,'六武众之真影',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：自己将“影六武众”怪兽召唤・特殊召唤时可以发动。从手牌将此卡特殊召唤。\r\n②：1回合1次，从自己墓地将1只等级4以下的“六武众”怪兽除外可以发动。直至回合结束时为止，此卡的属性・等级・攻击力・守备力变为与除外的该怪兽相同。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15335853,'幻兽机全球剑齿虎','此卡不可直接攻击。我方墓地存在有除冠有“幻兽机”之名怪兽以外怪兽的场合，此卡不可攻击。此卡的等级上升相当于我方场上“幻兽机衍生物”的等级合计值。只要我方场上存在衍生物，此卡不会因战斗及效果被破坏。此外，１回合１次，可释放１只衍生物并发动。选择我方或对手墓地的１张卡牌并从游戏中除外。','卡片除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15341821,'蒲公英狮子','①：此卡被送入墓地的场合发动此卡。以守备表示特殊召唤２只“绵毛衍生物”（植物族・风・１星・攻／守０）至我方场上。特殊召唤该衍生物的回合中，不可解放该衍生物来进行上级召唤。','特殊召唤衍生物','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15341822,'绵毛衍生物','由“蒲公英狮子”的效果特殊召唤而来。此衍生物被特殊召唤的回合，不可进行以升级召唤为目的的释放。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15341823,'绵毛衍生物','由“蒲公英狮子”的效果特殊召唤而来。此衍生物被特殊召唤的回合，不可进行以升级召唤为目的的释放。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15367030,'蟑螂球','圆圆的蟑螂。满地滚来滚去地发动攻击。守备力量高得出乎意料。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15381252,'狂战士之魂',replace(replace('“狂战士之魂”１回合只可发动１张。\r\n①：我方场上的怪兽以直接攻击给予对手１５００或以下的伤害时，可将所有手牌舍弃并发动。翻阅我方牌组最上方的卡牌，是怪兽的场合，将该怪兽送入墓地，并给予对手５００伤害。之后，重复执行此效果（最多７次），直至翻到怪兽以外的卡牌。翻阅的卡牌是怪兽以外的场合，将该卡牌返回至牌组最上方。','\r',char(13)),'\n',char(10)),'是否要继续使用「狂战士之魂」的效果？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15381421,'辉光龙 赛弗特',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：从自己的手牌・场上（表侧表示）将任意数量的龙族怪兽送至墓地可以发动。从牌组将１只等级与送至墓地的怪兽原本等级合计相同的龙族怪兽加入手牌。\r\n②：将墓地的此卡除外，以自己墓地的１只光・暗属性的龙族・等级８怪兽为对象可以发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'请选择要加入手牌的怪兽的等级','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15383415,'圣甲虫群','此卡在１个回合中可有１次机会变为里侧守备表示。成功反转召唤此卡时，选择对手场上的１只怪兽并将其破坏。','变成里侧守备表示','破坏对手1只怪兽','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15388353,'饿魔新飨餐厅『À Table』',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：作为此卡发动时的效果处理，可从自己的牌组・墓地将１张“食谱”卡加入手牌。\r\n②：１回合１次，从手牌将１只仪式怪兽放回牌组最下面可以发动。自己抽１张。\r\n③：在自己的结束阶段，以自己墓地包含“食谱”卡在内的２张卡为对象可以发动。将该卡以喜欢的顺序放回牌组下面。然后，自己抽１张。','\r',char(13)),'\n',char(10)),'是否选1张「食谱」卡加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15394083,'极星兽 坦格里斯尼尔','①：此卡因战斗被破坏并送入墓地的场合发动。特殊召唤２只“极星兽衍生物”（兽族、地、星３、攻／守０）至我方场上。','特殊召唤Token','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15394084,'极星兽衍生物','由“极星兽坦格里斯尼尔”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15397015,'冲浪检察官',replace(replace('自己场上存在怪兽的情况下，此卡不可召唤・特殊召唤。\r\n①：只要此卡存在于怪兽区域，在此期间，双方在１回合中各自可以发动的怪兽效果次数，最多为场上怪兽的种类（仪式・融合・同步・超量・灵摆・连接）的数量。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15401633,'紫炎之影武者','侍奉紫焰的影武者。手持锋利的名刀。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15419596,'魅幽鸟',replace(replace('①：此卡只要存在于主要怪兽区域，根据其位置获得以下效果。\r\n●左端：此卡的攻击力・守备力上升1000。\r\n●右端：此卡在1次战斗阶段中最多可攻击怪兽2次。\r\n●中央：此卡不会成为对手效果的对象，也不会因对手的效果而被破坏。\r\n●其他：与此卡同一纵列的怪兽不可发动效果。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15443125,'电光闪灵・启辉器','此卡名的卡１回合仅可发动１张。①：从牌组将１只“电光闪灵”怪兽特殊召唤，自己失去相当于该怪兽原本攻击力数值的LP。此卡发动后，直至回合结束时为止，自己仅可特殊召唤等级２・阶级２・连接２的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15447747,'调皮宝贝大作战',replace(replace('具此卡名的①②效果１回合各只能使用１次。\r\n①：在我方／对手的主要阶段可发动。将我方场上的“调皮宝贝”怪兽作为素材连接召唤１只“调皮宝贝”连接怪兽。\r\n②：对手怪兽的攻击宣告时从墓地将此卡除外可发动。从我方墓地选择任意张数的“调皮宝贝”卡放回卡组，该攻击怪兽的攻击力直到回合结束降低放回去的数量×１００点。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15449853,'珀耳修斯的神域',replace(replace('①：只要存在于场上、墓地，此卡的卡牌名被视为“天空的圣域”。\r\n②：只要此卡存在于魔法、陷阱区，场上的天使族怪兽的攻击力、守备力上升３００，盖牌于场上的魔法、陷阱卡不会成为效果的对象，也不会因效果被破坏。\r\n③：１回合１次，可从我方墓地的天使族怪兽以及计数物陷阱卡中，以合计３张为对象发动（同名卡最多１张）。将该卡以喜欢的顺序返回至牌组上方。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15452043,'娱乐伙伴剑鱼',replace(replace('①：此卡召唤、特殊召唤成功的场合发动。对手场上所有怪兽的攻击力、守备力下降６００。\r\n②：此卡存在于怪兽区，且我方特殊召唤怪兽成功的场合发动。对手场上所有怪兽的攻击力、守备力下降６００。','\r',char(13)),'\n',char(10)),'攻守变换','攻守变换','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15458892,'星舰侦察机','对手场上存在有超量怪兽的场合，此卡可从手牌特殊召唤。此外，此卡从手牌特殊召唤成功时，选择对手场上的１张魔法、陷阱卡并返回至持有者手牌。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15462014,'龙马踬图',replace(replace('双方场上皆有被从额外牌组特殊召唤的怪兽存在的情况下可以发动此卡。\r\n①：只要此卡存在于魔法与陷阱区域，从额外牌组被特殊召唤的表侧表示怪兽的效果无效化。\r\n②：有怪兽因被从额外牌组特殊召唤的怪兽之间的战斗被破坏的情况下发动。此卡被送至墓地，因该战斗被破坏的怪兽的控制者受到１０００伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15464375,'水月的冰长石',replace(replace('以此卡名以①方法的特殊召唤１回合仅可进行１次，且③效果１回合仅可使用１次。\r\n①：自己的魔法与陷阱区域存在表侧表示的卡的情况下，此卡可从手牌中特殊召唤。\r\n②：此卡的攻击力・守备力上升相当于场上的表侧表示的魔法・陷阱卡的数量×６００的数值。\r\n③：将自己的魔法与陷阱区域的２张表侧表示的卡送至墓地可以发动。从牌组将１只等级４以下的怪兽送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15471265,'狂战士冲击','①：从自己墓地将1只怪兽除外，以自己场上的1只“羽翼库里波”为对象可以发动。该自己的“羽翼库里波”的攻击力・守备力直至回合结束时为止变为与除外的怪兽相同数值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15475415,'外星人犬','我方召唤冠“外星人”之名怪兽成功时，可从手牌特殊召唤此卡。以此效果特殊召唤成功时，放置２个A计数物在对手场上的表侧表示怪兽。','特殊召唤','放置「A计数物」','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15480588,'铠蜥蜴','拥有坚硬躯体的蜥蜴，要是被它那张大嘴咬到会立即毙命。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15495787,'超重武者心构－A',replace(replace('我方墓地存在有魔法、陷阱卡的场合，此卡不可召唤、反转召唤。\r\n①：我方墓地不存在有魔法、陷阱卡，且我方受到战斗伤害时可发动。从手牌特殊召唤此卡。以此效果特殊召唤而来的此卡，此回合不会因战斗、效果被破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15502037,'电磁石战士伽玛',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从手牌将除“电磁石战士伽玛”以外的1只等级4以下的“磁石战士”怪兽特殊召唤。\r\n②：在对手回合中，解放此卡可以发动。从牌组将1只等级4的“磁石战士”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'加入手牌','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15507080,'黑暗追随者','崇拜黑暗的魔法师，召唤魔手将敌人拖入漆黑深渊。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15510988,'雷电小子','平时会在体内积蓄雷电，因此当它哭泣时会非常危险。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15520842,'光子之手','此卡名的卡1回合仅可发动1张。①：自己场上有“光子”怪兽或“银河”怪兽存在的情况下，可支付1000LP，以对手场上的1只怪兽为对象发动。获得该怪兽的控制权。发动时自己场上没有“银河眼光子龙”存在的情况下，仅可以超量怪兽为对象。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15521027,'变形斗士・智能手机',replace(replace('此卡不可通常召唤。\r\n将我方墓地１只冠有“变形斗士”之名的怪兽除外的场合可特殊召唤。\r\n①：此卡依据此卡的表示形式获得以下效果。\r\n●攻击表示：１回合１次，可我方主要阶段发动。掷１次骰子，从牌组上方翻阅与掷出数字相同数量的卡牌。从中挑选１张“变形斗士”卡牌加入手牌，将剩下的卡牌返回至牌组并洗牌。\r\n●守备表示：１回合１次，可在我方主要阶段发动。掷１次骰子，从牌组上方确认与掷出数字相同数量的卡牌，并按喜欢的顺序返回至牌组的上方或下方。','\r',char(13)),'\n',char(10)),'特殊召唤','确认牌组','确认牌组顺序','放回牌组上面','放回牌组下面','','','','','','','','','','','');
INSERT INTO texts VALUES(15543940,'暴君恐龙结合','①：将自己场上的怪兽作为融合素材，将1只“恐龙摔跤手”融合怪兽融合召唤。以此效果特殊召唤的怪兽只要以表侧表示存在于场上，仅限1次不会因战斗・效果被破坏。','','「暴君恐龙结合」特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15545291,'刚地帝古兰玛古',replace(replace('此卡可通过解放1只上级召唤的怪兽来上级召唤。\r\n①：此卡上级召唤的情况下，以场上的最多2张里侧表示卡为对象发动。将该里侧表示卡破坏。此卡解放了地属性怪兽来上级召唤的情况下，追加以下效果。\r\n●自己抽1张。','\r',char(13)),'\n',char(10)),'把1只上级召唤的怪兽解放作上级召唤','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15552258,'一半或停止',replace(replace('对手的战斗阶段时可以发动。对手可从以下效果中挑选１个适用。\r\n●自己场上的所有怪兽的攻击力直到战斗阶段结束时变为一半。\r\n●结束战斗阶段。','\r',char(13)),'\n',char(10)),'攻击力变成一半数值','把战斗阶段结束','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15555120,'高速等级重现','①：可将我方墓地的１只“疾行机人”怪兽除外，并以我方场上的１只同步怪兽为对象发动。直至回合结束时，该怪兽变成与被除外怪兽相同等级，攻击力上升被除外怪兽的等级×５００。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15561463,'手甲射手',replace(replace('等级6怪兽×2\r\n①：去除此卡的1个超量素材，以对手场上的1只怪兽为对象可以发动。将该怪兽破坏。','\r',char(13)),'\n',char(10)),'怪兽破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15574615,'异次元喷射钢铁号','此卡不可通常召唤。从自己的手牌・场上，将“异次元超能人・星之罗宾”、“野兽战士 豹人”、“凤王兽 盖尔达”、“铁巨人 钢铁之锤”各１只送至墓地的情况下可以特殊召唤。此外，解放此卡可以发动。选择自己墓地的“异次元超能人・星之罗宾”、“野兽战士 豹人”、“凤王兽 铠楼罗”、“铁巨人 钢铁之锤”各１只特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15576074,'共鸣者引擎','①：以自己墓地的２只“共鸣者”怪兽为对象可以发动。从牌组将１只等级４怪兽加入手牌，将对象怪兽放回牌组。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15582767,'连成的振动',replace(replace('此卡名的效果１回合仅可使用１次。\r\n①：以自己灵摆区域的１张卡为对象可以发动。将该卡破坏，然后，自己抽１张。','\r',char(13)),'\n',char(10)),'是否立刻使用此卡的效果？','自己的灵摆区域1张卡破坏，从牌组抽1张。','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15590355,'书灵师・实体化',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：向对手出示手牌的1只“书灵师”仪式怪兽可以发动。将1只等级与所出示的怪兽等级相同的“烈火衍生物”（电子界族・炎・攻/守0）特殊召唤至自己场上。只要以此效果特殊召唤的衍生物存在于自己场上，自己仅可特殊召唤“书灵师”怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15590356,'烈火衍生物','由「书灵师・实体化」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15595052,'封魔之传承者','此卡召唤、反转召唤、特殊召唤成功时发动。宣言相当于我方墓地的“封魔之传承者”数量的属性。攻击此卡宣言属性的怪兽的伤害阶段开始时，破坏该怪兽。','宣言属性','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15605085,'太阳能次代机',replace(replace('此卡可通过解放１只“次代机”怪兽来以表侧表示上级召唤。\r\n①：此卡存在于怪兽区域的状态下，每次自己场上表侧表示的“次代机”怪兽被送至墓地则发动。给予对手５００伤害。','\r',char(13)),'\n',char(10)),'用1只名字带有「次代机」的怪兽解放召唤','伤害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15609017,'隐蔽射击','①：将自己墓地的最多２只“疾行机人”怪兽除外，依除外的数量，以场上的卡为对象可以发动。将该卡破坏。','除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15610297,'方界胤维贾姆',replace(replace('①：此卡不会因战斗被破坏。\r\n②：此卡与对手怪兽进行战斗的伤害步骤结束时可发动。怪兽区的此卡被视为永续魔法卡以表侧表示放置于我方的魔法与陷阱区域，并于该对手怪兽放置１个方界计数物。放置有方界计数物的怪兽不可攻击，效果被无效化。\r\n③：此卡因此卡的效果被视为永续魔法卡的场合，在我方主要阶段可发动。特殊召唤魔法与陷阱区域的此卡。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15613529,'圣精灵－圣爆裂疾风弹','此卡名的①②效果１回合仅可各使用１次。①：自己场上有等级５以上的通常怪兽存在，对手场上的怪兽发动效果时可以发动。将此卡从手牌特殊召唤，将该效果无效。②：在对手战斗阶段，以自己或对手墓地的１只通常怪兽为对象可以发动。将该怪兽特殊召唤至自己场上。此回合，只要该怪兽存在于自己场上，可攻击的对手怪兽必须攻击该怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15627227,'再装填龙',replace(replace('“枪弹”怪兽2只\r\n此卡名的①效果1回合仅可使用1次。\r\n①：以自己场上的1只其他的连接怪兽为对象可以发动。从手牌将1只“枪弹”怪兽特殊召唤至对象怪兽连接端的自己场上。以此效果特殊召唤的怪兽不可作为连接素材，将在结束阶段被破坏。\r\n②：此卡因战斗被破坏并被送至墓地时，以自己墓地的1只“枪弹”怪兽为对象可以发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15629801,'武斗圆舞','可选择我方场上的１只同步怪兽并发动。特殊召唤１只持有与该怪兽相同种族、属性、等级、攻击力、守备力的“华尔滋衍生物”至我方场上。因此衍生物的战斗而发生的给予双方玩家的战斗伤害变成０。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15629802,'华尔滋衍生物','由「武斗圆舞」的效果特殊召唤。这个衍生物的战斗发生的对双方玩家的战斗伤害变成0。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15635751,'圣骑士与圣剑的巨城',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n \r\n①：在自己的主要阶段可以发动。将此卡直至下个准备阶段为止除外，从自己的手牌・牌组・墓地将１张“圆桌的圣骑士”以表侧表示放在自己的场地区域。然后，可适用以下效果。\r\n●从自己的牌组・墓地将１只“阿托利斯”怪兽特殊召唤，或将１张“圣剑”卡加入手牌。 \r\n②：１回合１次，自己场上的“圣骑士”卡将被战斗・效果破坏的情况下，作为代替可将自己场上的１张装备卡破坏。','\r',char(13)),'\n',char(10)),'','是否选卡特殊召唤或加入手牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15653824,'骷髅骑士','解放此卡后并成功上级召唤恶魔族怪兽时，从我方牌组特殊召唤１只“骷髅骑士”。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15658249,'异虫巴尔萨斯','此卡召唤成功时，选择场上的１只守备表示怪兽将其变成表侧攻击表示。','变更表示形式','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15661378,'冰狱龙 三叉龙',replace(replace('卡名不同的怪兽×３\r\n此卡从额外牌组仅可通过、仅以自己手牌・场上的怪兽作为素材的融合召唤，及以下方法特殊召唤。\r\n●将自己场上的上述卡除外的情况下，可从额外牌组特殊召唤。\r\n①：仅以原本种族为龙族的怪兽作为素材将此卡特殊召唤的情况下可以发动（此卡名的此效果１回合仅可使用１次）。对自己的牌组・对手的牌组最上面・对手的额外牌组，依序确认并从中各除外１张。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15665977,'杀手旋律・赤印',replace(replace('“杀手旋律・乐蔻”＋协调1只以上\r\n此卡名的③效果1回合仅可使用1次。\r\n①：此卡的攻击力上升双方墓地的协调数量×300的数值。\r\n②：原本攻击力在1700以下的对手场上的怪兽的等级上升1。\r\n③：在自己・对手的主要阶段，从自己墓地将1只协调除外，以对手场上1张表侧表示的卡为对象可以发动。将该卡的效果直至回合结束时为止无效。','\r',char(13)),'\n',char(10)),'效果无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15667446,'暗黑界之斗神 铂提纳','此卡因卡牌效果从手牌被舍弃至墓地的场合，从墓地特殊召唤此卡。因对手卡牌效果被舍弃的场合，另选择场上的１只恶魔族怪兽，攻击力提升５００点。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15684835,'邪恶爆裂','怪兽被特殊召唤至对手场上时，可以１只该怪兽为对象发动此卡。此卡被视为上升攻击力５００点的装备卡，装备在该怪兽。每次对手准备阶段，给予对手LP５００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15693423,'颉颃胜负',replace(replace('自己场上不存在卡的情况下，此卡也可从手牌发动。\r\n①：在自己・对手的战斗阶段结束时，对手场上的卡的数量多于自己场上的卡的情况下可以发动。对手必须将自身场上的卡以里侧除外，以使其数量与自己场上的卡的数量相同。','\r',char(13)),'\n',char(10)),'适用「颉颃胜负」的效果来发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15710054,'机怪虫・轴突','此卡名的①②效果1回合仅可各使用1次。①：此卡反转的情况下，以场上1张魔法・陷阱卡为对象可以发动。将该卡破坏。②：表侧表示的此卡因对手的效果从场上离开的情况下可以发动。将2只“机怪虫・轴突”以外的“机怪虫”怪兽从牌组以里侧守备表示特殊召唤（同名卡最多1张）。','魔陷破坏','2只怪兽特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15717011,'融合咒印生物－光','①：此卡可以代替1只融合怪兽卡上记载有卡名的融合素材怪兽。但是，其他融合素材怪兽必须为正规素材。②：从自己场上解放一组由光属性的融合怪兽卡决定的融合素材怪兽（此卡为其中1只）后可以发动。从额外牌组将1只以该解放的怪兽为融合素材的光属性融合怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15721123,'对峙的Z','①对手从额外牌组特殊召唤怪兽时可发动。从手牌特殊召唤此卡。因此效果特殊召唤的此卡，不受以此卡为对象的怪兽效果影响。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15721392,'超级量子要请 阿尔方呼救',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：自己的“超级量子”怪兽因战斗被破坏时可以发动。从额外牌组将1只“超级量子机兽”超量怪兽特殊召唤。然后，可从自己手牌・牌组・墓地将1只卡名记载于该超量怪兽卡的“超级量子士”怪兽效果无效并特殊召唤。','\r',char(13)),'\n',char(10)),'是否特殊召唤记述的怪兽？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15734813,'魂虎','据说会贪婪吞噬人类灵魂的可怖虎之魂。作为最不想遇到的灵魂而闻名。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15735108,'魔法卡“灵魂交换”',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：进行1只怪兽的上级召唤。在此之际，可解放对手场上的怪兽来作为自己场上怪兽的代替。以此效果上级召唤的怪兽此回合不可解放。\r\n②：此卡从场上被送至墓地的情况下发动。对手可适用此卡的①效果。','\r',char(13)),'\n',char(10)),'','','是否使用「魔法卡“灵魂交换”」的效果？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15744417,'神鬼食人魔',replace(replace('①：１回合１次，可在我方主要阶段发动。掷３次骰子。直至对手回合结束时，此卡的攻击力、守备力上升掷出点数合计×１００。之后，掷出点数的２个相同的场合，根据该相同点数适用以下效果。掷出点数全部相同的场合，适用以下全部效果。\r\n●１、２：直至对手回合结束时，不会因战斗、效果而被破坏。\r\n●３、４：我方从牌组抽取２张卡牌。\r\n●５、６：此回合，此卡可直接攻击。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15746348,'水灵媒师 艾里雅',replace(replace('此卡名在规则上也视为“灵使”卡。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：从手牌将此卡和1只水属性怪兽舍弃可以发动。从牌组将等级为此卡以外的所舍弃的怪兽等级以上的1只水属性怪兽加入手牌。此效果发动后，直至回合结束时为止，自己不可发动水属性以外的怪兽的效果。\r\n②：自己的水属性怪兽因战斗被破坏时可以发动。从手牌将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'检索','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15754711,'龙女仆的送行',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：以自己场上的1只“龙女仆”怪兽为对象可以发动。将卡名与该怪兽不同的1只“龙女仆”怪兽从手牌以守备表示特殊召唤，将对象怪兽放回手牌。以此效果特殊召唤的怪兽直至下个回合结束时为止，不会因战斗・效果被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15758127,'北斗天熊・五倍线充能',replace(replace('①：1回合1次，支付700LP，可从以下效果中选择1个发动。\r\n●从自己的墓地挑选1只“北斗天熊”怪兽加入手牌。\r\n●解放自己场上的2只“北斗天熊”怪兽，将1只拥有与该等级差相同等级的“北斗天熊”怪兽从额外牌组无视召唤条件特殊召唤。\r\n②：自己的“北斗天熊”同步怪兽因对手的攻击被破坏时可以发动。对手必须将自身的卡放回持有者的牌组，直至其手牌・场上・墓地的卡合计为7张为止。','\r',char(13)),'\n',char(10)),'加入手牌','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15767889,'骑士 迪格雷法',replace(replace('此卡存在于墓地或以表侧表示存在于场上的场合，将被视为通常怪兽。以通常召唤的方式再次召唤场上表侧表示的此卡，此卡将视为效果怪兽并获得以下效果。\r\n●可在我方结束阶段时发动此卡。选择我方墓地中的１张装备魔法卡并加入到手牌中。“骑士 迪格雷法”的此效果在１个回合中只可使用１次。','\r',char(13)),'\n',char(10)),'回收装备魔法','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15771991,'守护者史莱姆',replace(replace('此卡名的效果①②③在1个回合中仅可各使用1次。\r\n①：自己因战斗或效果受到伤害时可以发动。从手牌中特殊召唤此卡。\r\n②：此卡与对手怪兽进行战斗，计算伤害值时可以发动。此卡的守备力仅在计算其伤害值时上升其对手怪兽的攻击力数值。\r\n③：此卡从手牌、场上被送至墓地时可以发动。从牌组中将1张写有“拉之翼神龙”卡名的魔法・陷阱卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15778492,'游戏自游机GG',replace(replace('机械族等级4怪兽×2\r\n此卡名的②效果1回合仅可使用1次。\r\n①：此卡特殊召唤的情况下可以发动。将对手场上的怪兽全部改成攻击表示。\r\n②：对手场上或墓地存在怪兽的情况下，去除此卡的1个超量素材可以发动。从牌组・额外牌组将1只机械族怪兽送至墓地。然后，可适用以下效果。\r\n●挑选自己墓地的1只机械族超量怪兽，此卡直至结束阶段为止视为该怪兽的同名卡。','\r',char(13)),'\n',char(10)),'变成攻击表示','送至墓地','是否变更卡名？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15792576,'天魔神 希德赫尔斯',replace(replace('此卡不可特殊召唤。\r\n①：此卡上级召唤成功的情况下可以发动。根据为上级召唤此卡而解放的怪兽的种族・属性，适用以下效果。\r\n●天使族・光属性：从牌组将１只天使族・光属性或恶魔族・暗属性怪兽加入手牌。\r\n●恶魔族・暗属性：从牌组将天使族・光属性或和恶魔族・暗属性怪兽各最多１只送至墓地。','\r',char(13)),'\n',char(10)),'','牌组检索','送至墓地','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15800838,'心灵崩坏','①：宣言1个卡名可以发动。对手手牌中有宣言的卡的情况下，对手将手牌的该卡全部舍弃。对手手牌中没有宣言的卡的情况下，自己从手牌中随机挑选1张舍弃。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15808381,'热烫烫＠伊格尼斯者',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将“热烫烫＠伊格尼斯者”以外的1只等级4以下的“＠伊格尼斯者”怪兽加入手牌。\r\n②：自己的电子界族怪兽进行战斗的伤害步骤开始时，将墓地的此卡除外可以发动。将该自己的怪兽破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15820147,'怪兽龟','驼著带刺龟壳的乌龟。性情极其凶暴且与人不亲近。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15839054,'同步结融体','①：此卡作为同步素材被送至墓地的情况下可以发动。从牌组将１张“融合”魔法卡或“结合”魔法卡加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15844566,'力码语者',replace(replace('怪兽3只\r\n①：1回合1次，以场上1只表侧表示怪兽为对象可以发动。该怪兽的效果直至回合结束时为止无效。②：1回合1次，此卡与对手怪兽进行战斗的伤害计算时，解放此卡连接端的1只自己的怪兽可以发动。此卡的攻击力仅在该伤害计算时变为原本攻击力的两倍。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15845914,'团结与羁绊的魔导师',replace(replace('此卡不可通常召唤。\r\n仅可在自己墓地存在２５张以上的卡的情况下特殊召唤。\r\n①：只要对手墓地存在２５张以上的卡，此卡的攻击力・守备力上升２５００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15848542,'龙女仆・露风缇',replace(replace('此卡名的①③效果1回合仅可各使用1次。\r\n①：从手牌将此卡舍弃，以场上的1只表侧表示怪兽为对象可以发动。此回合，双方不可发动该表侧表示怪兽在场上发动的效果。\r\n②：只要自己场上存在融合怪兽，此卡就不会因效果被破坏。\r\n③：在自己・对手的战斗阶段结束时可以发动。将此卡放回手牌，从手牌将1只等级3的“龙女仆”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15854426,'霞之谷的神风','①：１回合１次，自己场上表侧表示的风属性怪兽被放回手牌的情况下可以发动。从牌组将１只等级４以下的风属性怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15862758,'混沌虚数编号1000 梦幻虚光神 原数天灵・原数天地',replace(replace('等级１３怪兽×５\r\n①：以“混沌编号1000 梦幻虚神 原数天灵”的效果特殊召唤的此卡的攻击力・守备力在对手回合期间上升１０００００，从被特殊召唤的下一个回合起适用以下内容。\r\n●可攻击的对手怪兽必须攻击此卡。\r\n●此卡未进行战斗的对手回合结束时，自己获得决斗的胜利。\r\n②：对手怪兽攻击宣言时，去除此卡的１个超量素材可以发动。使该攻击无效，依其攻击力数值恢复自己的LP。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15866454,'骚动邪灵','选择对手场上的１张魔法・陷阱卡令其回到持有者的手牌。此卡的发动和效果不会被无效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15871676,'星圣 金牛达巴兰','①：此卡召唤时可以发动。从手牌将1只等级3的“星圣”怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15893860,'雪人制造机','此卡召唤、反转召唤、特殊召唤成功时可发动。在对手场上的表侧表示怪兽放置与我方场上水属性怪兽数量相同的冰计数物。以此效果放置的数量在３或以上的场合，更可挑选对手场上的１张卡牌并破坏。','放置计数物','请选择要放置冰计数物的怪兽','是否要选择对手场上1张卡破坏？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15894048,'究极恐兽','①：在自己的战斗阶段有可攻击的“究极恐兽”存在的情况下，“究极恐兽”以外的怪兽不可攻击。②：此卡可攻击所有对手怪兽各１次。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15914410,'机装天使・引擎天兵',replace(replace('等级３怪兽×２\r\n１回合１次，可移除此卡的１个超量素材，并选择我方场上的１只表侧攻击表示怪兽发动。将被选择怪兽变成表侧守备表示，此回合该怪兽不会因战斗以及卡牌的效果被破坏。此效果在对手回合也可发动。','\r',char(13)),'\n',char(10)),'破坏耐性','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15935204,'风暴召唤师','只要此卡以表侧表示存在于我方场上，可将除此卡以外的念动力族怪兽因战斗破坏的对手怪兽不送入墓地，放置至对手牌组的最上方。此卡因卡牌效果被破坏时，此卡控制者受到相当于此卡攻击力的伤害。','伤害','是否要使用「风暴召唤师」的效果？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15936370,'潘朵拉的宝具箱',replace(replace('←4 【灵摆】 4→\r\n①：我方额外牌组不存在有卡牌的场合，可以对手灵摆区的１张卡牌为对象发动。破坏该卡，将灵摆区的此卡放置于对手的灵摆区。\r\n【怪兽效果】\r\n①：只要我方额外牌组不存在有卡牌，且此卡存在于怪兽区，我方抽牌阶段的通常抽取变成２张。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15939229,'DDD 双晓王伽梨玉迦',replace(replace('等级８“DD”怪兽×２\r\n①：此卡超量召唤成功的余下本回合，场上此卡以外的卡的效果不可发动且无效化。②：１回合１次，去除此卡的１个超量素材可以发动。将场上的魔法・陷阱卡全部破坏。此效果在对手回合中也可以发动。③：去除此卡的１个超量素材，以自己墓地的１张“契约书”魔法・陷阱卡为对象可以发动。将该卡放置在自己场上。','\r',char(13)),'\n',char(10)),'场上的魔法·陷阱卡全部破坏','放置魔法·陷阱','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15939448,'盾异虫','此卡召唤、反转召唤、特殊召唤成功时，变成守备表示。并且，从对手牌组上方将卡牌送入墓地，其数量相当于我方场上昆虫族怪兽数量。','牌组送墓','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15941690,'先史遗产水晶骨架','对手场上存在有怪兽且我方场上不存在怪兽的场合，此卡可从手牌特殊召唤。以此方法特殊召唤成功时可发动。从我方手牌、墓地挑选除“先史遗产水晶骨架”以外的１只冠有“先史遗产”之名的怪兽并特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15943341,'再上膛之筒','此卡名的②效果１回合仅可使用１次。①：从自己的牌组・墓地挑选１张“魔法之筒”放置在自己场上。从牌组放置的情况下，该卡在放置的回合也可以发动。②：自己发动“魔法之筒”时，将墓地的此卡除外可以发动。以该效果给予对手的伤害变为两倍。','','适用「再上膛之筒」的效果来发动','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15947754,'沉默狼－卡鲁波狼犬',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：此卡召唤・特殊召唤成功的情况下发动。将自己牌组最上面的卡视为攻击力上升５００的装备卡，以里侧表示装备于此卡。\r\n②：在自己・对手的结束阶段发动。对手将对以此卡的①效果装备中的卡的原本种类（怪兽・魔法・陷阱）作出猜测。猜中的情况下，将此卡送至墓地。未猜中的情况下，随机挑选对手的１张手牌舍弃，将此卡放回持有者的手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15951532,'亚马逊女王','只要此卡以表侧表示存在于场上，我方场上的冠有“亚马逊”之名的怪兽不会因战斗而被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15960641,'幻象龙','①：只要此卡存在于怪兽区域，对手在战斗阶段中就不可以发动陷阱卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15967552,'小小的对抗',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：指定2处同一纵列的、未使用的主要怪兽区域可以发动。自己适用以下效果。然后，对手可适用以下效果。\r\n●从自身手牌・牌组挑选1只等级2以下的怪兽，以表侧攻击表示或里侧守备表示特殊召唤至所指定的自身的主要怪兽区域。','\r',char(13)),'\n',char(10)),'','是否选怪兽特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15978426,'娱乐伙伴副手驴','①：此卡召唤、特殊召唤成功时可发动。从牌组将１只除“娱乐伙伴副手驴”以外的“娱乐伙伴”怪兽送入墓地。我方灵摆区存在有２张卡牌的场合，也可不送入墓地直接加入手牌。','加入手牌','是否加入手牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15981690,'碳素龙','此卡名的②效果1回合仅可使用1次。①：此卡与炎属性怪兽战斗的伤害计算时发动。此卡的攻击力仅在该伤害计算时上升1000。②：将墓地的此卡除外可以发动。从手牌・牌组将1只等级7以下的龙族通常怪兽以守备表示特殊召唤。','攻击上升','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15982593,'百夫骑士皇 蕾格提亚',replace(replace('协调＋协调以外的怪兽１只以上\r\n此卡名的①③效果１回合仅可各使用１次。\r\n①：此卡特殊召唤的情况下可以发动。自己抽１张。然后，可将对手场上攻击力最高的１只怪兽破坏。\r\n②：攻击力２０００以下的自己的怪兽不会因战斗被破坏。\r\n③：在自己・对手的结束阶段可以发动。从自己的手牌・墓地将同步怪兽以外的１只“百夫骑”怪兽视为永续陷阱卡，以表侧表示放在自己的魔法与陷阱区域。','\r',char(13)),'\n',char(10)),'','','是否把对手攻击力最高的怪兽破坏？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15983048,'大魔键－马夫提亚尔',replace(replace('此卡名的②效果１回合仅可使用１次，将此卡作为同步・超量召唤的素材的情况下，仅可使用于“魔键”怪兽的同步・超量召唤。\r\n①：自己场上有“魔键”怪兽存在的情况下，将手牌中的此卡出示给对手可以发动。此回合自己在通常召唤外仅追加１次，可召唤１只“魔键”怪兽。\r\n②：此卡召唤成功时，以自己墓地的１只等级４以下的、通常怪兽或“魔键”怪兽为对象可以发动。以守备表示形式将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','使用「大魔键－马夫提亚尔」的效果召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(15989522,'龙魔道骑士盖亚',replace(replace('“暗黑骑士盖亚”怪兽＋等级５龙族怪兽\r\n此卡名的②③效果１回合仅可各使用１次。①：此卡只要存在于怪兽区域，卡名视为“龙骑士盖亚”。②：在自己・对手的主要阶段，以场上此卡以外的１张卡为对象可以发动。此卡的攻击力下降２６００，破坏对象卡。③：此卡战斗破坏对手怪兽时可以发动。此卡的攻击力上升２６００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16001119,'红面波坦',replace(replace('此卡名的效果①②在1个回合中仅可各使用1次。\r\n①：可以以自己场上的1只“波波”怪兽为对象发动。该怪兽作为协调使用，直到下一回合结束。\r\n②：在此卡已经存在于怪兽区域的状态下，我方或对手同步召唤成功时可以发动。从手牌、牌组中特殊召唤1只“波波”怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16003979,'剑斗兽 弓骑',replace(replace('①：此卡以“剑斗兽”怪兽的效果特殊召唤的情况下，从手牌将１张“剑斗兽”卡舍弃可以发动。自己抽２张。\r\n②：此卡进行过战斗的战斗阶段结束时，将此卡放回牌组可以发动。从牌组将“剑斗兽 弓骑”以外的１只“剑斗兽”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16006416,'DDD 烈火大王执行铁木真',replace(replace('等级５以上的“DD”怪兽＋“DD”怪兽\r\n此卡名的①效果１回合仅可使用１次。①：此卡存在于怪兽区域，此卡以外的“DD”怪兽被召唤・特殊召唤至自己场上的情况下，以自己墓地的１只“DD”怪兽为对象可以发动。将该怪兽特殊召唤。②：１回合１次，魔法・陷阱卡的效果在自己的回合发动时可以发动。将该发动无效。','\r',char(13)),'\n',char(10)),'特殊召唤','发动无效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16008155,'爬虫妖使魔','场上存在有除此卡以外的表侧表示怪兽的场合，此卡被破坏。此卡变成魔法、陷阱卡的效果对象时，此卡被破坏。只要此卡以表侧表示存在于场上，双方不可召唤怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16020923,'闪亮亮＠伊格尼斯者','此卡名的①②效果1回合仅可各使用1次。①：此卡召唤・特殊召唤成功的情况下可以发动。从牌组将1张“-艾-”魔法・陷阱卡加入手牌。②：以自己场上的1只“＠伊格尼斯者”怪兽为对象可以发动。该怪兽的等级直至回合结束时为止改为4。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16021142,'幻奏音女 珈诺',replace(replace('此卡名以①方法的特殊召唤１回合仅可进行１次。\r\n①：自己场上存在“幻奏”怪兽的情况下，此卡可从手牌中特殊召唤。\r\n②：１回合１次，以自己场上的１只“幻奏”怪兽为对象可以发动。变更该怪兽的表示形式。','\r',char(13)),'\n',char(10)),'特殊召唤','表示形式变更','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16024176,'花札卫－松与鹤－',replace(replace('此卡不可通常召唤。\r\n解放了我方场上１只除“花札卫－松与鹤－”以外的等级１的“花札卫”怪兽的场合可特殊召唤。\r\n①：此卡特殊召唤成功的场合发动。我方从牌组抽取１张卡牌，并双方相互确认。该卡是“花札卫”怪兽的场合，可特殊召唤该怪兽。若不是的场合，将该卡送入墓地。\r\n②：此卡进行战斗的战斗阶段结束时可发动。我方从牌组抽取１张卡牌。','\r',char(13)),'\n',char(10)),'抽1张卡并给双方确认','是否特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16037007,'编号74 魔力小丑－失落之剑',replace(replace('等级７怪兽×２\r\n①：以此卡为对象的魔法・陷阱・怪兽的效果发动时，去除此卡的１个超量素材可以发动。将该发动无效并破坏。然后，可挑选场上的１张卡破坏。','\r',char(13)),'\n',char(10)),'无效并破坏','是否要选择场上一张卡破坏？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16051717,'强袭黑羽－骤雨之雷切',replace(replace('协调＋１只以上协调以外的怪兽\r\n①：以“黑羽”怪兽作为素材同步召唤的此卡视为协调。②：１回合１次，以对手场上的卡为对象可以发动，数量最多为自己场上此卡以外的“黑羽”怪兽数量。将该卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16066654,'R.B.操作测试',replace(replace('此卡名的卡1回合仅可发动1张，此卡名的②效果1回合仅可使用1次。\r\n①：此卡发动时，可将自己墓地1只等级3以上的“R.B.”怪兽作为对象。该情况下，将该怪兽特殊召唤。\r\n②：以自己场上任意数量的“R.B.”怪兽为对象可以发动。依该怪兽的原本攻击力的合计数值恢复自己的LP，将该怪兽放回手牌・额外牌组。然后，可从手牌将1只“R.B.”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','回复基本分','是否要选卡？','是否从手牌特殊召唤？','','','','','','','','','','','','');
INSERT INTO texts VALUES(16067089,'蛇神降临','我方场上表侧表示的“毒蛇王维诺米洛”因战斗以外的方式被破坏时可发动。从手牌、牌组特殊召唤１只“毒蛇神维诺米纳迦”。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16110708,'闪光编号38 泰坦银河',replace(replace('光属性等级9怪兽×3\r\n此卡也可重叠在自己场上的“编号38 希望魁龙 泰坦银河”上面来超量召唤。\r\n①：此卡的攻击力上升相当于此卡的超量素材的数量×200的数值。\r\n②：1回合1次，以对手场上最多2张魔法・陷阱卡为对象可以发动（应对此发动，不可发动对象卡的效果）。将该卡作为此卡的超量素材。\r\n③：去除此卡的1个超量素材可以发动。此回合，此卡的原本攻击力变为1500，且可直接攻击。','\r',char(13)),'\n',char(10)),'是否在「编号38 希望魁龙 银河巨神」上面重叠来超量召唤？','攻击力上升','作为超量素材','直接攻击','','','','','','','','','','','','');
INSERT INTO texts VALUES(16111820,'朱罗纪・艾雷拉龙','①：此卡存在于手牌・墓地，且“朱罗纪・艾雷拉龙”以外的、自己守备表示的“朱罗纪”怪兽因战斗被破坏并被送至墓地时可以发动。将此卡特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16114248,'协力车机人',replace(replace('同名机械族怪兽×２\r\n①：此卡可直接攻击。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16135253,'法眼蛋','当此卡因战斗而被破坏送入墓地时，投掷１次骰子。可从我方墓地中特殊召唤１只等级与掷出点数相同的天使族怪兽。（掷出６的场合，则包括等级６以上的怪兽）','掷骰子','是否要特殊召唤天使族怪兽？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16146511,'进化护法 主教',replace(replace('①：只要此卡存在于场上・墓地，视为通常怪兽。\r\n②：场上视为通常怪兽的此卡可作为通常召唤再召唤１次。该情况下，此卡改视为效果怪兽，获得以下效果。\r\n●此卡召唤・特殊召唤成功的情况下，以自己墓地“进化护法 主教”以外的１只战士族・炎属性怪兽或二重怪兽为对象可以发动。将该怪兽特殊召唤。此卡名的此效果１回合仅可使用１次。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16157341,'武斗神器－羽尾张','在我方主要阶段１，可将此卡从手牌送入墓地，并选择我方场上１只冠有“武斗神”之名的怪兽发动。此回合，被选择怪兽攻击守备表示怪兽时，若攻击力超过该守备力，给予对手生命相当于该差值的战斗伤害。','贯穿附加','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16165939,'超自然警戒区域','此卡名的①②效果１回合仅可各使用１次。①：效果怪兽以外的怪兽以表侧表示被特殊召唤的情况下，以对手场上的１张卡为对象可以发动。将该卡破坏。②：魔法与陷阱区域的此卡被对手效果破坏的情况下可以发动。从自己的手牌・牌组・墓地挑选效果怪兽以外的１只怪兽特殊召唤。','对手的卡破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16169772,'简易接触','此卡名的卡１回合仅可发动１张。①：支付１０００LP可以发动。从额外牌组将等级７以下的１只“元素－英雄”怪兽或“新空间人”怪兽无视召唤条件特殊召唤。自己的场上及墓地不存在“元素－英雄 新宇侠”的情况下，以此效果特殊召唤的怪兽不可攻击，效果无效化，将在结束阶段放回持有者的额外牌组。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16172067,'暗红恶魔龙・暴君',replace(replace('协调２只＋协调以外的怪兽１只以上\r\n此卡仅可以同步召唤方式特殊召唤。\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：在自己的主要阶段１可以发动。将场上的其他卡全部破坏。此回合，自己的其他怪兽不可攻击。\r\n②：魔法・陷阱卡在战斗阶段发动时可以发动。将该发动无效并破坏，此卡的攻击力上升５００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16178681,'异色眼灵摆龙',replace(replace('←4 【灵摆】 4→\r\n此卡名的①②的灵摆效果1回合仅可各使用1次。\n①：可将自己的灵摆怪兽战斗对自己造成的战斗伤害改成0。\n②：在自己的结束阶段可以发动。将此卡破坏，从牌组将1只攻击力1500以下的灵摆怪兽加入手牌。\r\n【怪兽效果】\r\n①：此卡与对手怪兽战斗给予对手的战斗伤害变为两倍。','\r',char(13)),'\n',char(10)),'伤害变换','牌组检索','是否要把战斗伤害变成0？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16178682,'异色眼灵摆龙',replace(replace('←4 【灵摆】 4→\r\n此卡名的①②的灵摆效果1回合仅可各使用1次。\n①：可将自己的灵摆怪兽战斗对自己造成的战斗伤害改成0。\n②：在自己的结束阶段可以发动。将此卡破坏，从牌组将1只攻击力1500以下的灵摆怪兽加入手牌。\r\n【怪兽效果】\r\n①：此卡与对手怪兽战斗给予对手的战斗伤害变为两倍。','\r',char(13)),'\n',char(10)),'伤害变换','牌组检索','是否要把战斗伤害变成0？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16178683,'异色眼灵摆龙',replace(replace('←4 【灵摆】 4→\r\n此卡名的①②的灵摆效果1回合仅可各使用1次。\n①：可将自己的灵摆怪兽战斗对自己造成的战斗伤害改成0。\n②：在自己的结束阶段可以发动。将此卡破坏，从牌组将1只攻击力1500以下的灵摆怪兽加入手牌。\r\n【怪兽效果】\r\n①：此卡与对手怪兽战斗给予对手的战斗伤害变为两倍。','\r',char(13)),'\n',char(10)),'伤害变换','牌组检索','是否要把战斗伤害变成0？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16178684,'异色眼灵摆龙',replace(replace('←4 【灵摆】 4→\r\n此卡名的①②的灵摆效果1回合仅可各使用1次。\n①：可将自己的灵摆怪兽战斗对自己造成的战斗伤害改成0。\n②：在自己的结束阶段可以发动。将此卡破坏，从牌组将1只攻击力1500以下的灵摆怪兽加入手牌。\r\n【怪兽效果】\r\n①：此卡与对手怪兽战斗给予对手的战斗伤害变为两倍。','\r',char(13)),'\n',char(10)),'伤害变换','牌组检索','是否要把战斗伤害变成0？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16188701,'瓢虫调试员','此卡名的效果1回合仅可使用1次。①：此卡召唤・特殊召唤成功的情况下可以发动。从牌组将1只等级3以下的电子界族怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16191953,'吉格大师','１回合１次，可支付１０００LP发动。挑选对手场上的怪兽并破坏，其数量相当于我方场上念动力族怪兽的数量。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16195942,'暗反叛超量龙',replace(replace('等级4怪兽×2\r\n①：去除此卡的2个超量素材，以对手场上的1只表侧表示怪兽为对象可以发动。将该怪兽的攻击力改成一半，此卡的攻击力上升该变动的数值。','\r',char(13)),'\n',char(10)),'攻守变换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16195943,'暗反叛超量龙',replace(replace('等级4怪兽×2\r\n①：去除此卡的2个超量素材，以对手场上的1只表侧表示怪兽为对象可以发动。将该怪兽的攻击力改成一半，此卡的攻击力上升该变动的数值。','\r',char(13)),'\n',char(10)),'攻守变换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16197610,'云魔物－乱气流','此卡不因战斗被破坏。此卡以表侧守备表示存在的场合，被破坏。此卡召唤成功时，放置雾计数物于此卡，其数量相当于场上冠有“云魔物”之名怪兽的数量。可移除此卡的１个雾计数物并发动。从我方牌组或从双方的墓地挑选１只“云魔物－小烟球”并特殊召唤。','放置计数物','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16209941,'未界域之卓柏卡布拉',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：向对手出示手牌中的此卡可以发动。对手从自己的所有手牌中随机挑选１张，自己舍弃该卡。该卡为“未界域之卓柏卡布拉”以外的情况下，进而从手牌将１只“未界域之卓柏卡布拉”特殊召唤，自己抽１张。\r\n②：此卡从手牌被舍弃的情况下，以自己墓地的“未界域之卓柏卡布拉”以外的１只“未界域”怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16222645,'一刀两断侍','此卡攻击里侧守备表示怪兽的场合，不进行伤害计算直接以里侧守备表示的状态破坏该怪兽。','里侧守备的攻击对象怪兽破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16223761,'雷霆手','此卡名的效果１回合仅可使用１次。①：此卡存在于手牌・墓地，自己场上原本攻击力或原本守备力为１６００的表侧表示怪兽因战斗或对手的效果被破坏并被送至墓地的情况下可以发动。将此卡特殊召唤，挑选对手场上的１张卡破坏。以此效果特殊召唤的此卡离开场上的情况下，将其除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16226786,'深渊的暗杀者',replace(replace('①：此卡反转的情况下，以对手场上的１只怪兽为对象发动。将该对手怪兽破坏。\r\n②：此卡从手牌送往墓地的情况下，以“深渊的暗杀者”以外的１只自己墓地的反转怪兽为对象发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'破坏','返回手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16227556,'检阅','每次对手的准备阶段，可支付５００LP发动。随机挑选１张对手的手牌确认。','查看手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16227633,'冥铭途・骨回归',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己场上表侧表示的“冥铭途”怪兽因对手从场上离开的情况下可以发动。从手牌・牌组将１只“冥骸合龙－冥铭途拉尔泰库特利卡”无视召唤条件特殊召唤。\r\n②：此卡存在于墓地的状态下，自己墓地的“冥铭途”怪兽因对手从墓地离开的情况下，将此卡除外可以发动。从手牌・牌组尽可能地将“冥铭途”怪兽特殊召唤（同名卡最多１张）。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16229315,'疾风毒蛾','①：支付3000LP可以发动。从额外牌组将1只怪兽送至墓地。','送墓','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16238373,'大念力兵工厂',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：以自己场上的1只念动力族怪兽为对象，支付其等级×200的LP可以发动。从牌组将1只等级高于该怪兽、拥有相同属性的机械族怪兽加入手牌。\r\n②：从墓地将不是在此回合被送至墓地的此卡除外，以自己除外状态的念动力族怪兽和机械族怪兽各1只为对象可以发动。将其中1只放回牌组最下面，另1只加入手牌。','\r',char(13)),'\n',char(10)),'','回收除外的卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16240772,'死之罪宝－露西耶拉',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：以自己场上的１只等级７以上的魔法师族怪兽为对象可以发动。分别适用以下效果。\r\n●对象的表侧表示怪兽在此回合不受其他怪兽的效果影响，且将在下个回合的准备阶段被送至墓地。\r\n●对手场上所有怪兽的攻击力下降相当于对象怪兽攻击力的数值。攻击力因此效果变为０的情况下，进而将该怪兽破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16241441,'茧状体・小幼虫','可解放此卡并发动。从手牌・牌组特殊召唤１只“新空间人・火焰甲虫”。此效果在我方场上存在有“新宇空间”的场合可发动与处理。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16246527,'铠鼠','身上有坚硬如盔甲的毛能保护身体不受伤害的老鼠。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16246535,'沉默的念力魔术师',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的①效果1回合仅可使用1次。\r\n①：此卡特殊召唤的情况下，以自己墓地・除外状态的1只等级4以下的念动力族怪兽为对象可以发动。将该怪兽特殊召唤。然后，该怪兽的等级可上升1。此回合，自己从额外牌组仅可特殊召唤念动力族怪兽。\r\n②：要以自己场上的此卡作为同步素材的情况下，可将此卡视为协调以外的怪兽。','\r',char(13)),'\n',char(10)),'特殊召唤','是否上升等级？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16255173,'The grand JUPITER',replace(replace('①：１回合１次，可舍弃２张手牌，并以对手场上的１只表侧表示怪兽为对象发动。该表侧表示怪兽被视作装备卡装备在此卡。\r\n②：此卡的攻击力上升因此卡效果装备的怪兽的原本攻击力数值。\r\n③：在我方、对手的结束阶段，可以１张因此卡效果装备的怪兽卡为对象发动。特殊召唤该卡至我方场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16255442,'光的召集','①：舍弃我方的所有手牌。之后，从我方墓地挑选光属性怪兽加入手牌，其数量相当于以此效果舍弃至墓地卡牌的张数。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16259549,'编号49 秘鸟 幸运啾啾',replace(replace('等级３怪兽×２\r\n此卡名的④效果１回合仅可使用１次。\r\n①：场上的此卡不会成为效果的对象。\r\n②：场上的此卡将被战斗・效果破坏的情况下，可去除此卡的１个超量素材作为代替。\r\n③：在自己的准备阶段发动。自己恢复５００LP。\r\n④：此卡从场上被送至墓地的情况下，以自己墓地２只等级３怪兽为对象发动。将该２只怪兽放回牌组，将此卡放回额外牌组。','\r',char(13)),'\n',char(10)),'回复','返回牌组','是否要使用「编号49 秘鸟 幸运啾啾鸟」的效果代替破坏？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16261341,'天空圣骑士首领珀耳修斯',replace(replace('①：此卡存在于手牌・墓地，且我方发动计数物陷阱卡的场合，或我方使怪兽的效果・魔法・陷阱卡的发动变成无效的场合，可从我方的手牌、场上、墓地将除此卡以外的２只天使族怪兽除外并发动。特殊召唤此卡。\r\n②：此卡攻击了守备表示怪兽的场合，若其攻击力超过守备力，给予对手生命相当于该差值的战斗伤害。\r\n③：此卡给予对手战斗伤害时可发动。从牌组将１张“珀耳修斯”卡或反制陷阱卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16268841,'黑祭司','解放此卡成功上级召唤时，回复我方２０００LP。','回复','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16269385,'调皮宝贝・屋',replace(replace('此卡名的卡片１回合只可发动１张。\r\n①：此卡发动时的效果处理能从卡组中将１只“调皮宝贝”怪兽加入手牌。\r\n②：１回合１次，在我方成功融合召唤“调皮宝贝”融合怪兽的情况下可发动。我方场上全部怪兽的攻击力上升５００点。\r\n③：１回合１次，在我方成功连接召唤“调皮宝贝”连接怪兽的情况下可发动。对手场上全部怪兽的攻击力降低５００点。','\r',char(13)),'\n',char(10)),'是否把「调皮宝贝」怪兽加入手牌？','自己全部怪兽攻击力上升','对手全部怪兽攻击力下降','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16272453,'机甲忍法・黄金变换','我方场上有冠有“忍法”之名卡牌存在的场合可发动。破坏我方场上所有冠有“忍法”之名的卡牌。之后，从牌组抽取２张卡牌。','破坏并抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16278116,'龙之束缚','以自己场上１只攻击力・守备力为２５００以下的龙族怪兽为对象可以发动此卡。①：只要此卡存在于魔法与陷阱区域，双方不可特殊召唤对象怪兽原本攻击力以下的怪兽。②：对象怪兽离开场上时，此卡将被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16279989,'鬼计・科学怪人','仅在自己场上有“鬼计”怪兽存在的情况下，此卡才可以表侧表示召唤。此卡名的②效果１回合仅可使用１次。①：在自己的主要阶段可以发动。将此卡改成里侧守备表示（１回合仅１次）。②：此卡给予对手战斗伤害时可以发动。从牌组将１张“鬼计”魔法・陷阱卡加入手牌。','变成里侧守备','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16304628,'元素－英雄 盖亚',replace(replace('“元素－英雄”怪兽＋地属性怪兽\r\n此卡仅可以融合召唤方式特殊召唤。\r\n①：此卡融合召唤的情况下，以对手场上的1只表侧表示怪兽为对象发动。直至回合结束时为止，将该怪兽的攻击力改成一半，此卡的攻击力上升该变动的数值。','\r',char(13)),'\n',char(10)),'攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16306932,'超天新龙 异色眼革命龙',replace(replace('←12 【灵摆】 12→\r\n①：自己仅可灵摆召唤龙族怪兽。此效果不会被无效化。\n②：以自己墓地的１只龙族融合・同步・超量怪兽为对象可以发动。将此卡破坏，将该怪兽特殊召唤。\r\n【怪兽效果】\r\n此卡不可通常召唤。仅可通过从手牌的灵摆召唤，或在解放自己场上龙族的融合・同步・超量怪兽各１只的情况下特殊召唤。\n①：从手牌将此卡舍弃，支付５００LP可以发动。从牌组将１只等级８以下的龙族灵摆怪兽加入手牌。\n②：此卡的攻击力・守备力上升相当于对手LP一半的数值。\n③：１回合１次，支付一半LP可以发动。将双方的场上・墓地此卡以外的卡全部放回牌组。','\r',char(13)),'\n',char(10)),'特殊召唤墓地怪兽','牌组检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16308000,'神之威光','可选择我方场上１只冠有“极神”之名的怪兽并发动此卡。只要此卡存在于场上，被选择怪兽不会成为卡牌效果的对象。在发动后第２次的我方准备阶段时，将此卡送入墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16310544,'御巫神乐',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：为使合计等级达到仪式召唤的怪兽的等级以上，解放自己手牌・场上的怪兽，从手牌将1只“御巫”仪式怪兽仪式召唤。然后，可适用以下效果。\r\n●以自己墓地的装备魔法卡种类数量为上限，将对手场上的卡破坏，并给予对手所破坏数量×1000的伤害。','\r',char(13)),'\n',char(10)),'是否选对手场上的卡破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16312943,'书灵师・烈火',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡存在于手牌的情况下，向对手出示手牌的1只仪式怪兽可以发动。将此卡特殊召唤。\r\n②：此卡特殊召唤的情况下可以发动。从牌组将“书灵师・烈火”以外的1只“书灵师”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16313112,'转生炎兽 翡翠鹰',replace(replace('以“转生炎兽之降临”降临。①：此卡使用自己场上的“转生炎兽 翡翠鹰”仪式召唤成功时可以发动。将对手场上被特殊召唤的怪兽全部破坏。②：1回合1次，解放自己场上的1只“转生炎兽”连接怪兽可以发动。此回合，此卡获得以下效果。\r\n●此卡与对手怪兽进行战斗的伤害步骤开始时发动。将该对手怪兽破坏，给予对手相当于其原本攻击力数值的伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16317140,'高亢焰波','①：“神炎皇乌利亚”以其本身的方法特殊召唤的情况下，也可将自己场上里侧表示的陷阱卡送至墓地。②：每次自己的“神炎皇乌利亚”进行战斗的攻击宣言时，从手牌・牌组将1张陷阱卡送至墓地可以发动1次。此回合中，该怪兽的攻击力・守备力变为双方场上・墓地的陷阱卡数量×1000。③：1回合1次，扔掉1张手牌可以发动。从自己的墓地挑选“神炎皇乌利亚”、“降雷皇哈蒙”、“幻魔皇拉比艾尔”中的任意1只，加入手牌或无视召唤条件特殊召唤。','改变攻击力·守备力','加入手牌或特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16327715,'废品战士・极致',replace(replace('“废品同步士”＋协调以外的怪兽1只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡同步召唤的情况下可以发动。从自己墓地将等级2以下的怪兽尽可能地特殊召唤，此回合，该怪兽的效果不可发动。此效果发动后，直至回合结束时为止，自己仅可特殊召唤1次。\r\n②：此卡战斗破坏对手怪兽时，将此卡除外可以发动。从额外牌组将1只“废品”同步怪兽视为同步召唤特殊召唤。','\r',char(13)),'\n',char(10)),'从墓地特殊召唤','从额外牌组特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16329071,'向星遗物蠢动的陷阱','此卡名的卡1回合仅可发动1张。①：从自己手牌・墓地的卡、自己场上表侧表示的卡、被除外的自己的卡中，挑选“向星遗物蠢动的陷阱”以外的5种“星遗物”卡各1张，加入持有者的牌组洗牌。然后，自己从牌组抽2张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16353197,'鲜血吸吮者','借着夜色袭击行人的人形吸血蛇。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16360142,'斩机减伐','此卡名的效果在1回合中仅可使用1次。①：可以场上1只表侧表示的怪兽为对象发动。从手牌将此卡特殊召唤，对象怪兽的攻击力直至回合结束时为止下降1000。用此效果特殊召唤的回合，此卡不可攻击。此效果发动后，直至回合结束时为止自己从额外牌组仅可特殊召唤电子界族怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16366810,'黄尘小妖','此卡不可进行释放，也不可作为融合、同步、超量召唤的素材。场上的此卡被破坏时，此卡的控制者选择我方墓地的１只怪兽并返回至牌组。我方场上只可有１只“黄尘小妖”以表侧表示存在。','返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16366944,'月光蝶','此卡从场上被送入墓地时，可从牌组特殊召唤１只等级４或以下的冠有“幻蝶刺客”之名的怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16387555,'杀手旋律・绮悠',replace(replace('要以场上的此卡作为素材同步召唤的情况下，可将手牌的1只协调也作为同步素材。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤的情况下可以发动。从自己手牌・牌组・墓地将“杀手旋律・绮悠”以外的1只协调特殊召唤。此回合，自己仅可特殊召唤协调。\r\n②：此卡作为同步素材被送至墓地的情况下可以发动。从对手牌组上面翻开2张卡，从其中除外1张，将另1张放回牌组最上面或最下面。','\r',char(13)),'\n',char(10)),'特殊召唤','除外效果','返回牌组最上面','返回牌组最下面','','','','','','','','','','','','');
INSERT INTO texts VALUES(16392422,'卡通假面魔道士',replace(replace('①：此卡在召唤・反转召唤・特殊召唤的回合不可攻击。\r\n②：自己场上存在“卡通世界”，且对手场上不存在卡通怪兽的情况下，此卡可直接攻击。\r\n③：此卡给予对手战斗伤害的情况下发动。自己抽1张。\r\n④：场上的“卡通世界”被破坏时，此卡将被破坏。','\r',char(13)),'\n',char(10)),'抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16404809,'库里盗贼','①：在此卡召唤成功的回合的结束阶段，解放此卡可以发动。从自己的牌组上翻开5张卡。可从其中挑选1张魔法・陷阱卡加入手牌。将剩下的卡全部送至墓地。','翻开牌组','是否要把一张魔法或陷阱卡加入手牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16428514,'地中骇界的导师',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡反转的情况下可以发动。从牌组将“地中骇界的导师”以外的1张“地中骇界”卡加入手牌。\r\n②：以场上1只其他的表侧表示怪兽为对象可以发动（自己场上存在其他的“地中骇界”卡的情况下，此效果在对手回合中也可以发动）。将该怪兽和此卡改成里侧守备表示。','\r',char(13)),'\n',char(10)),'牌组检索','变成里侧守备表示','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16430187,'可靠的保卫者','场上以表侧表示存在的１只怪兽的守备力直到结束阶段时上升７００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16433136,'御巫之祓舞',replace(replace('仅可装备于“御巫”怪兽。\r\n此卡名的②效果1回合仅可使用1次。\r\n①：装备怪兽不会因效果被破坏。\r\n②：怪兽被特殊召唤至对手场上的情况下，以自己及对手场上的怪兽各1只为对象可以发动。将该怪兽放回手牌。','\r',char(13)),'\n',char(10)),'双方怪兽回到手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16435215,'墓穴的同路人','①：双方各自确认对手手牌，挑选其中1张舍弃。然后，双方各抽1张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16437822,'火石打击','选择１只装备了“火石”的怪兽破坏。发动后，此卡被送至墓地的情况下可以发动。将此卡放回牌组。','返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16449363,'废铁同步士',replace(replace('此卡可代替“同步士”协调作为同步素材。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：要同步召唤需以“同步士”协调作为素材的同步怪兽的情况下，可将手牌的此卡也作为同步素材。\r\n②：自己场上的以下怪兽将被战斗・效果破坏的情况下，作为代替可将场上・墓地的此卡除外。\r\n●记载有“废品战士”卡名的怪兽\r\n●原本卡名包含“战士”的同步怪兽','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16469012,'提婆','①：此卡上级召唤成功的情况下发动。下一对手回合，对手不可进行攻击宣言。','攻击限制','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16471775,'北斗天熊・出击','此卡名的①②效果1回合仅可各使用1次。①：舍弃1张手牌可以发动。从牌组将2只“北斗天熊”怪兽加入手牌。②：自己为发动“北斗天熊”怪兽的效果而解放怪兽的情况下，可将墓地的此卡除外作为代替。此效果在此卡被送至墓地的回合不可使用。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16474916,'驱魔姐妹・以利斯',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：自己场上存在“驱魔姐妹”怪兽的情况下可以发动。从手牌将此卡特殊召唤。自己场上存在“驱魔姐妹・斯特拉”的情况下，自己进而恢复800LP。\r\n②：有自己或对手的卡因对手从墓地离开的情况下可以发动。从额外牌组将1只“驱魔姐妹”超量怪兽重叠在自己场上的此卡上面，视为超量召唤特殊召唤。','\r',char(13)),'\n',char(10)),'','超量召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16475472,'次级恶魔','只要此卡以表侧表示存在于场上，此卡因战斗破坏的怪兽不被送入墓地而从游戏中被除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16475473,'次级恶魔','只要此卡以表侧表示存在于场上，此卡因战斗破坏的怪兽不被送入墓地而从游戏中被除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16480084,'进化龙 佩尔塔','此卡因冠有“进化虫”之名怪兽的效果特殊召唤成功时，此卡的守备力上升５００点。之后，此卡因战斗被破坏时可发动。从牌组将１只冠有“进化虫”之名的怪兽加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16494704,'异色眼降临','龙族仪式怪兽的降临所必需。此卡名的卡１回合仅可发动１张。①：为使合计等级为仪式召唤的怪兽的等级以上，解放自己的手牌・场上的灵摆怪兽，从自己的手牌・墓地将１只龙族仪式怪兽仪式召唤。对手场上存在２只以上怪兽，而自己场上不存在怪兽的情况下，也可将自己额外牌组的“异色眼”怪兽送至墓地作为解放的代替。','额外代替解放','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16507828,'腕龙雷德斯','“双头恐龙王”＋“贪尸龙”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16509007,'杀手旋律・米可丝',replace(replace('要以场上的此卡作为素材同步召唤的情况下，可将手牌的1只协调也作为同步素材。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从自己牌组・墓地将等级2怪兽以外的1只“杀手旋律”怪兽加入手牌。\r\n②：此卡作为同步素材被送至墓地的情况下，以对手场上的1只怪兽为对象可以发动。将该怪兽破坏。','\r',char(13)),'\n',char(10)),'检索效果','破坏效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16509093,'王族亲卫队','此卡仅限１回合１次可变成里侧守备表示。此卡反转时，此卡的攻击力、守备力上升３００点直至回合结束为止。','变成里侧守备','攻守上升','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16516630,'黑羽－尖锐的波拉','可将墓地的此卡从游戏中除外，并选择我方场上１只冠有“黑羽”之名的怪兽发动。此回合被选择怪兽进行攻击的场合，因该攻击造成的对我方的战斗伤害变成０，被选择怪兽在战斗中不会被破坏，在进行战斗的对手怪兽的伤害计算后破坏。','附加能力','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16527176,'大植然狮面草','地属性协调＋１只以上协调以外的地属性怪兽','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16528181,'王之棺',replace(replace('此卡名的②效果1回合最多可使用4次。\r\n①：只要此卡存在于魔法与陷阱区域，自己场上的“荷鲁斯”怪兽不会因未以自身为对象的卡的效果被破坏。\r\n②：将1张手牌送至墓地可以发动。从牌组将1只“荷鲁斯”怪兽送至墓地。\r\n③：1回合1次，自己的“荷鲁斯”怪兽与对手怪兽进行战斗的伤害步骤开始时可以发动。将该对手怪兽送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16550875,'甲虫装机的魔剑 虫王剑','仅限装备冠有“甲虫装机”之名的怪兽。装备怪兽的攻击力、守备力上升８００点。场上表侧表示的此卡被送入墓地时，选择１只我方墓地冠有“甲虫装机”之名的怪兽加入手牌。','加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16556849,'流浪的勇者 弗利德','１回合１次，可将我方墓地中的２只光属性怪兽从游戏中除外来发动此卡。选择场上１只攻击力高于此卡的怪兽并将其破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16587243,'新虫','据说是来自异星球的巨大昆虫型怪兽。会以团体行动捕捉猎物。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16589042,'疾风暗黑骑士盖亚','①：手牌仅有此1张卡的情况下，此卡无需解放即可召唤。','不用解放召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16598965,'圣邪之花窗玻璃',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：根据自己场上的效果怪兽的种族，可分别适用以下效果。\r\n●天使族：自己抽３张。然后，挑选２张手牌以喜欢的顺序放回牌组下面。\r\n●恶魔族：对手抽１张。然后，对手随机舍弃１张手牌。对手还有手牌的情况下进而再挑选１张舍弃。','\r',char(13)),'\n',char(10)),'选择效果适用','是否让自己抽牌？','是否让对手丢弃手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16605586,'命运－英雄 否决魔侠',replace(replace('此卡名的①效果1回合仅可使用1次，②效果在决斗中仅可使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。挑选自己牌组・墓地・除外状态的1只“命运－英雄”怪兽，放在牌组最上面。\r\n②：此卡存在于墓地，且自己场上或墓地存在“命运－英雄 否决魔侠”以外的“命运－英雄”怪兽的情况下可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','请选择要放置到牌组最上面的卡','放置在牌组最上面的卡是否要从牌组选择？','','','','','','','','','','','','');
INSERT INTO texts VALUES(16616620,'接触','将我方场上所有冠有“茧状体”之名的怪兽送入墓地，从手牌或牌组特殊召唤１只那些卡牌所记述的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16617334,'娱乐伙伴 雨衣山羊',replace(replace('①：给予自己伤害的魔法・陷阱・怪兽的效果发动时，从手牌将此卡舍弃可以发动。将自己因该效果将受到的伤害改成０。\r\n②：在自己・对手的主要阶段将此卡从手牌舍弃，以自己场上的１张“娱乐伙伴”卡或“异色眼”卡为对象可以发动。此回合，该卡不会因战斗・效果被破坏。','\r',char(13)),'\n',char(10)),'伤害变成0','不会被破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16625614,'暗黑圣域',replace(replace('①：以自己的“通灵盘”的效果出“死之信息”卡的情况下，可将该卡作为通常怪兽（恶魔族・暗・星１・攻／守０）特殊召唤。以此效果特殊召唤的卡不受“通灵盘”以外的卡的效果影响，不会成为攻击对象（自己场上仅存在适用此效果的怪兽的状态下，对手的攻击变为对自己的直接攻击）。\r\n②：对手怪兽攻击宣言时发动。掷１次硬币。正面的情况下，使该攻击无效，给予对手相当于该对手怪兽的攻击力一半数值的伤害。','\r',char(13)),'\n',char(10)),'是否作为通常怪兽特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16632144,'顽强的钓师','①：此卡用直接攻击给予对手战斗伤害时，以自己墓地的1只怪兽为对象可以发动。以守备表示形式将该怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16638212,'异次元精灵',replace(replace('①：此卡可除外我方场上的１只表侧表示怪兽，并从手牌特殊召唤。\r\n②：以此卡①的方法特殊召唤的场合，在下一个准备阶段发动。将以特殊召唤此卡为目的而除外的怪兽返回至场上。','\r',char(13)),'\n',char(10)),'返回场上','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16643334,'辉光龙光子爆龙',replace(replace('等级4怪兽×2\r\n①：此卡超量召唤成功的情况下可以发动。从手牌将1只“光子”怪兽特殊召唤。②：只要超量召唤的此卡存在于怪兽区域，自己场上攻击力2000以上的怪兽不会成为对手效果的对象，也不会因对手的效果而被破坏。③：每个对手回合中1次，可去除此卡的1个超量素材，从自己墓地的怪兽及被除外的自己的怪兽中，以1只“银河眼光子龙”为对象发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16674846,'灵魂之力','对手怪兽攻击的场合，在该伤害计算时可发动。因该战斗对我方造成的战斗伤害变成０。之后，从我方墓地将１只守备力为１５００或以下的战士族协调加入手牌。','是否要把墓地的1只守备力1500以下的战士族协调加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16678947,'诅咒超能力','自己的念动力族怪兽因对手怪兽的攻击被破坏并送往墓地时，选择１只该对手怪兽可以发动。破坏被选择的对手怪兽，并给予对手LP被破坏的自己的怪兽的等级×３００点伤害。','破坏并伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16684346,'代理马',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：要以自己场上的此卡作为电子界族怪兽的连接素材的情况下，可将手牌的１只电子界族怪兽也作为连接素材。\r\n②：在自己的结束阶段将墓地的此卡除外，将自己墓地的、包含电子界族连接怪兽在内的２只连接怪兽为对象可以发动。将该怪兽放回额外牌组。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16691074,'异色眼绝零龙',replace(replace('等级７怪兽×２\r\n此卡名的①②效果１回合仅可各使用１次。①：自己或对手的怪兽的攻击宣言时，去除此卡的１个超量素材可以发动。将该攻击无效。然后，可从自己的手牌・墓地挑选１只“异色眼”怪兽特殊召唤。②：超量召唤的此卡被送至墓地的情况下可以发动。从额外牌组将“异色眼绝零龙”以外的１只“异色眼”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'攻击无效','从额外牌组特殊召唤','是否要特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16693254,'咒仪・阿凡斯','①：１回合１次，在自己的主要阶段可以发动。从牌组挑选１只“咒仪”怪兽，放在牌组最上面。','牌组最上方放置','请选择要放置到牌组最上方的卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16693934,'凶教导之圣兽',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：以自己墓地・除外状态的1只怪兽为对象可以发动。将1只攻击力在该怪兽的攻击力以上的、额外牌组的怪兽或牌组的“教导”怪兽送至墓地，将对象怪兽特殊召唤。此卡发动后，直至下个自己的回合结束时为止自己不可从额外牌组特殊召唤怪兽。','\r',char(13)),'\n',char(10)),'发动','「凶教导之圣兽」效果适用中','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16699558,'蓝眼银龙',replace(replace('龙族等级８怪兽×２\r\n此卡名的①③效果１回合仅可各使用１次。\r\n①：此卡超量召唤的情况下可以发动。对手场上的所有表侧表示卡的效果无效化。\r\n②：未持有通常怪兽作为超量素材的此卡不可直接攻击。\r\n③：去除此卡的１个超量素材，以自己墓地・除外状态的１只通常怪兽为对象可以发动。将该怪兽特殊召唤。以此效果特殊召唤的怪兽的攻击力上升１０００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16708652,'机偶粉','可在战斗阶段选择场上攻击表示的冠有“机偶”之名的２只怪兽并发动。将被选择的１只怪兽变成守备表示，直至回合结束时，另１只怪兽的攻击力上升相当于变为守备表示怪兽的攻击力数值。','请选择要改变表示形式的怪兽','请选择攻击力上升的怪兽','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16719140,'地中骇界的战士',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己・对手回合中，从牌组将1只“地中骇界”怪兽送至墓地可以发动。为使合计的原本等级达到该“地中骇界”怪兽的等级以上，解放此卡和自己场上1只以上的怪兽，将该“地中骇界”怪兽以表侧守备表示或里侧守备表示特殊召唤。\r\n②：自己的“地中骇界邪龙”怪兽反转的情况下可以发动（在伤害步骤也可以发动）。将墓地的此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16719802,'星辉龙','此卡召唤成功时，可选择场上除此卡以外以表侧表示存在的１只怪兽，直至结束阶段时上升２个等级。','等级上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16720314,'微笑药水',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：自己场上不存在怪兽、攻击力高于原本攻击力的怪兽存在于对手场上的情况下可以发动。自己从牌组抽２张。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16725505,'疾行机人 红眼骰子','①：此卡召唤・特殊召唤成功时，以自己场上1只“疾行机人 红眼骰子”以外的“疾行机人”怪兽为对象，宣言1～6中的任意等级可以发动。该怪兽的等级直至回合结束时为止，变为所宣言等级。','等级变换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16734927,'灵魂等离子',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：可从以下效果中选择1个发动。\r\n●自己场上不存在怪兽的情况下可以发动。从牌组将1只不死族・等级6怪兽或1张“活尸的呼唤”加入手牌。\r\n●自己场上所有的不死族怪兽的攻击力上升400。然后，自己可依自己场上的“活死人的呼唤”的数量抽牌。','\r',char(13)),'\n',char(10)),'发动','检索','攻击力上升','是否抽牌？','','','','','','','','','','','','');
INSERT INTO texts VALUES(16751086,'暖异虫','①：此卡被破坏的场合发动。从对手牌组的上方将３张卡牌送入墓地。','牌组送墓','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16759958,'芬芳炽天使－欧白芷',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：在自己・对手回合中，从手牌将此卡舍弃，以自己墓地的１只“芬芳”怪兽为对象可以发动。依该怪兽的攻击力数值恢复自己的LP。\r\n②：此卡存在于墓地，自己的LP多于对手，且自己场上存在“芬芳”怪兽的情况下可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16762927,'守墓的使魔','对手必须将牌组最上面的卡牌送入墓地，才能进行攻击宣言。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16768387,'大王目玉','反转：从我方牌组上面最多确认５张卡牌，并按照喜好顺序返回至牌组上面。','确认牌组','请选择要确认的卡的数量','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16769305,'魔界造车－GT１９',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：此卡反转的情况下，宣言１～９为止的任意等级可以发动。此卡的等级直至回合结束时为止，变为所宣言的等级。\r\n②：反转的此卡以表侧表示存在的情况下，在自己・对手的主要阶段，以自己・对手场上此卡以外的１只表侧表示怪兽为对象可以发动。仅以该怪兽和此卡作为素材来同步召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16780318,'超胜负！',replace(replace('①：选择1只自己场上的同步怪兽，放回持有者的额外牌组，从自己的墓地选择4只“花札卫”怪兽特殊召唤。然后，自己从牌组中抽1张卡，并与对手互相确认。如果该卡为“花札卫”怪兽，则可无视该怪兽的召唤条件进行特殊召唤。如果不是“花札卫”怪兽，则破坏自己场上的所有怪兽，将自己的LP数值减半。\r\n②：此卡因“花札卫”的效果被送至墓地的回合的结束阶段可以发动。从自己的墓地选择1张魔法陷阱卡加入手牌。','\r',char(13)),'\n',char(10)),'是否特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16796157,'野兽战士 豹人','解放此卡可以发动。从自己的牌组・墓地挑选１只“异次元超能人・星之罗宾”加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16802689,'花札卫－桐上凤凰',replace(replace('此卡不可通常召唤。\r\n解放自己场上“花札卫－桐上凤凰”以外的１只等级１２“花札卫”怪兽的情况下可以特殊召唤。\r\n①：此卡特殊召唤成功的情况下发动。自己从牌组抽１张，双方确认。其为“花札卫”怪兽的情况下，可将该怪兽特殊召唤。不是的情况下，将该卡送至墓地。\r\n②：１回合１次，此卡给予对手战斗伤害时可以发动。自己从牌组抽１张。','\r',char(13)),'\n',char(10)),'抽1张卡并给双方确认','是否特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16825874,'古怪少年',replace(replace('要以此卡作为同步素材的情况下，其他同步素材怪兽必须是手牌的1只怪兽。\r\n①：以此卡作为同步素材的同步怪兽的效果不可发动并无效化，从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16828633,'后备次代机','①：１回合１次，自己场上存在其他“次代机”怪兽的情况下可以发动。此卡的卡名直至结束阶段为止视为“次代机・控制者”。','当作「次代机控制员」使用','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16832845,'最终制约咒','①：原本等级为７或以上的怪兽，从我方及对手场上各１只或以上送入墓地的回合可发动。将双方墓地的所有怪兽除外。之后，可特殊召唤１只以此效果除外的怪兽中等级最高的魔法师族怪兽至我方场上。','是否把魔法师族怪兽在自己场上特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16849715,'雷之天气模样',replace(replace('①：只可有１张“雷之天气模样”以表侧表示存在于我方场上。\r\n②：存在于与此卡同一纵列的我方主要怪兽区以及其两旁的我方主要怪兽区的“天气”效果怪兽获得以下效果。\r\n●此卡与对手怪兽进行战斗的伤害步骤开始时，可将此卡除外并发动。将该对手怪兽返回至持有者手牌。','\r',char(13)),'\n',char(10)),'对手怪兽回到持有者手牌（雷之天气模样）','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16886617,'爬虫妖・婆苏吉','此卡不可通常召唤。仅可在解放自己・对手场上2只攻击力为0的怪兽的情况下特殊召唤。①：“爬虫妖・婆苏吉”在场上仅可有1只以表侧表示存在。②：1回合1次，以对手场上的1只表侧表示怪兽为对象可以发动。将对手的该表侧表示怪兽破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16889337,'荒魂',replace(replace('此卡不可特殊召唤。\r\n①：此卡召唤・反转时可以发动。从牌组将“荒魂”以外的1只灵魂怪兽加入手牌。\r\n②：此卡召唤・反转的回合的结束阶段发动。将此卡放回手牌。','\r',char(13)),'\n',char(10)),'返回手牌','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16893370,'梦现的寝姬－妮梦雷莉娅・蕾莉泽',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡存在于手牌中的情况下，以自己场上的１只怪兽为对象可以发动。将该怪兽放回牌组最下面，将此卡特殊召唤。\r\n②：此卡特殊召唤的情况下，可从以下效果中选择１个发动。\r\n●从牌组将１只“眠梦中的妮梦雷莉娅”以表侧加入额外牌组。\r\n●将场上的１只其他的表侧表示怪兽改成里侧守备表示。\r\n③：此卡的攻击力上升相当于自己额外牌组的里侧卡的数量×１００的数值。','\r',char(13)),'\n',char(10)),'','','加入额外牌组','变成里侧守备','','','','','','','','','','','','');
INSERT INTO texts VALUES(16898077,'巨人轰炸机・大空袭',replace(replace('此卡不可通常召唤。仅可以通过“召唤热核・大”的效果特殊召唤。１回合１次，将１张手牌送至墓地可以发动。选择对手场上的１张卡破坏。此外，在对手回合１次，从以下效果中选择１个可以发动。\r\n●对手召唤・特殊召唤怪兽成功时可以发动。破坏该怪兽，并给予对手LP８００点伤害。\r\n●对手放置卡片时可以发动。将该卡破坏，并给予对手LP８００点伤害。','\r',char(13)),'\n',char(10)),'破坏','怪兽破坏','盖卡破坏','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16899564,'斩首的美女','有着惊人美貌，却用刀砍下累累首级的女人。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16906241,'星圣 双鱼雷斯卡','①：此卡召唤时可以发动。从手牌将1只“星圣”怪兽以守备表示特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16908882,'编号104 假面魔蹈士 闪光V',replace(replace('等级4怪兽×3\r\n此卡名的②效果1回合仅可使用1次。\r\n①：1回合1次，去除此卡的1个超量素材可以发动。从牌组将1张“巴利安之”魔法・陷阱卡加入手牌。\r\n②：以场上的此卡作为素材超量召唤的怪兽获得以下效果。\r\n●此卡超量召唤的情况下发动。对手可从自身牌组将4只怪兽（相同属性最多1只）和1张魔法卡除外。未除外的情况下，自己从对手牌组上面将10张卡除外。','\r',char(13)),'\n',char(10)),'检索','除外','除外效果（编号104 假面魔蹈士 闪光V枉然）','是否把4只怪兽和1张魔法卡除外？','','','','','','','','','','','','');
INSERT INTO texts VALUES(16909657,'爬虫妖斯库拉','此卡因战斗破坏攻击力为０的怪兽并送入墓地时，可以守备表示将该怪兽特殊召唤至我方场上。以此效果特殊召唤的怪兽效果被无效化。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16922142,'绚岚之鹤罗莎',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：速攻魔法卡发动的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从自己牌组・墓地将“绚岚之鹤罗莎”以外的“绚岚”卡与“气旋”最多各1张加入手牌。此效果发动后，直至回合结束时为止，自己仅可特殊召唤风属性怪兽。\r\n③：对手场上不存在魔法・陷阱卡的情况下，场上的此卡不会因战斗・效果被破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16923472,'发条猎人','解放自己场上“发条猎人”以外的１只表侧表示的“发条”怪兽可以发动。随机挑选１张对手的手牌送至墓地。只要此卡以表侧表示存在于场上，此效果仅可使用１次。','手牌破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16926971,'防火墙军刀龙',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的①②③效果1回合仅可各使用1次。\r\n①：此卡同步召唤的情况下，以自己墓地・除外状态的1只电子界族怪兽为对象可以发动。将该怪兽加入手牌。\r\n②：以自己场上的1只其他电子界族怪兽为对象可以发动。此卡的等级变为与该怪兽相同。\r\n③：此卡作为连接素材被送至墓地的情况下可以发动。从牌组将1张“-艾-”魔法卡加入手牌。','\r',char(13)),'\n',char(10)),'回收效果','改变等级','检索','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16938770,'超量波塞冬飞溅',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：持有超量怪兽作为超量素材的超量怪兽存在于自己场上的情况下，宣言场上怪兽的１个属性可以发动。将装备有装备魔法卡的怪兽以外的、所宣言属性的场上怪兽全部破坏。\r\n②：将墓地的此卡除外，去除自己场上的１个超量素材可以发动。从自己墓地将１只鱼族・海龙族・水族怪兽特殊召唤至自己或对手场上。','\r',char(13)),'\n',char(10)),'破坏怪兽','特殊召唤','是否在对手场上特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16940215,'大植然叶脉','①：对手发动魔法・陷阱卡时，解放此卡和自己场上的１只“大植然”怪兽可以发动。将该发动无效并破坏。','魔法陷阱发动无效并破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16943770,'幻兽机航空企鹅',replace(replace('①：１回合１次，可将我方墓地中１只除“幻兽机航空企鹅”以外的“幻兽机”怪兽除外并发动。特殊召唤１只“幻兽机衍生物”（机械族、风、星３、攻／守０）至我方场上。\r\n②：此卡的等级上升相当于我方场上“幻兽机衍生物”的等级合计数值。\r\n③：只要我方场上有衍生物存在，此卡就不会因战斗、效果被破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16943771,'幻兽机衍生物','由名称中带有“幻兽机”的怪兽等的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16946849,'人造天使','①：只要此卡存在于魔法与陷阱区域，每次反制陷阱卡发动，特殊召唤１只“人造天使衍生物”（天使族、光、星１、攻／守３００）至我方场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16946850,'人造天使衍生物','由“人造天使”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16947147,'疾行机人 洋片外层','①：对手怪兽的直接攻击宣言时可以发动。将此卡从手牌以攻击表示特殊召唤，将对手场上的表侧表示怪兽全部改成守备表示。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16955631,'巨怪・迷拟宝箱鬼',replace(replace('等级1怪兽×2\r\n此卡名的①③效果1回合仅可各使用1次。\r\n①：此卡超量召唤的情况下可以发动。从牌组将1张“迷拟宝箱鬼”卡加入手牌。\r\n②：只要对手场上存在里侧表示怪兽，超量怪兽以外的自己的“迷拟宝箱鬼”怪兽可直接攻击。\r\n③：去除此卡的1个超量素材，以对手场上的里侧表示怪兽数量为上限，以场上的表侧表示卡为对象可以发动。将该卡破坏，给予对手所破坏数量×1000的伤害。','\r',char(13)),'\n',char(10)),'','检索','破坏','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16956455,'贤士喀戎','１回合１次，可从手牌舍弃１张魔法卡并发动。选择对手场上的１张魔法、陷阱卡破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16958382,'Sin 范式龙',replace(replace('此卡不可通常召唤。\r\n仅可在场上不存在“Sin 范式龙”，并从额外牌组将1只“Sin”怪兽除外的情况下特殊召唤。\r\n①：场上不存在“Sin 世界”的情况下，此卡将被破坏。\r\n②：1回合1次，从牌组将1张“Sin”卡送至墓地可以发动。将自己除外状态的1只等级8同步怪兽放回额外牌组。然后，可从额外牌组将该怪兽特殊召唤。此回合，自己仅可用“Sin”怪兽攻击。','\r',char(13)),'\n',char(10)),'','是否特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16960120,'龙女仆・炊事龙女',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将“龙女仆・炊事龙女”以外的1只“龙女仆”怪兽加入手牌。然后，从手牌挑选1只“龙女仆”怪兽送至墓地。\r\n②：在自己・对手的战斗阶段开始时可以发动。将此卡放回手牌，从自己手牌・墓地将1只等级8的“龙女仆”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16960351,'幻界突破','①：１回合１次，可释放我方场上的１只龙族怪兽并发动。从牌组特殊召唤１只等级与被释放怪兽原本等级相同的幻龙族怪兽。以此效果特殊召唤而来的怪兽因战斗所破坏之怪兽将不被送入墓地而是返回至有者牌组。','「幻界突破」效果适用中','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16964437,'暗黑边界','①：我方因战斗、效果受到伤害时可发动。从牌组特殊召唤１只持有攻击力为所受伤害数值或以下的魔法师族・暗属性怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16968936,'六武众之指南番',replace(replace('此卡名以①方法的特殊召唤１回合仅可进行１次，且②③效果１回合仅可各使用１次。\r\n①：自己场上存在“六武众之指南番”以外的“六武众”怪兽的情况下，此卡可从手牌特殊召唤。\r\n②：此卡从场上被送至墓地的情况下可以发动。从自己牌组・墓地将１张“六武式”卡加入手牌。\r\n③：以此卡作为素材同步召唤的“六武众”怪兽获得以下效果。\r\n●对手场上的怪兽的攻击力下降５００。','\r',char(13)),'\n',char(10)),'','检索效果','','「六武众之指南番」效果适用中','','','','','','','','','','','','');
INSERT INTO texts VALUES(16970158,'来自墓地的呼唤','可在对手发动“死者苏生”时发动此卡。令该“死者苏生”的效果无效。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16972957,'死之沉默天使 多玛','司职死亡的天使。若被这家伙盯上，则难逃一死。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16984449,'炎妖蝶 维尔普斯',replace(replace('此卡存在于墓地或以表侧表示存在于场上的场合，将被视为通常怪兽。以通常召唤的方式再次召唤场上表侧表示的此卡，此卡将视为效果怪兽并获得以下效果。\r\n●解放此卡，特殊召唤我方墓地中１只除“炎妖蝶 维尔普斯”以外的二重怪兽。以此效果特殊召唤的二重怪兽将处于已再次召唤的状态。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(16990348,'猛进的剑斗兽','①：以场上的表侧表示卡为对象可以发动，数量最多为自己场上的“剑斗兽”怪兽的种类数量。将该卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17000165,'爬虫妖反冲','此卡名的①②效果１回合仅可各使用１次。①：以自己场上１只攻击力０怪兽和自己墓地的１只爬虫类族・暗属性怪兽为对象可以发动。将该场上的怪兽破坏，将该墓地的怪兽特殊召唤。②：对手发动怪兽效果的情况下，以对手场上１只攻击力０的怪兽为对象可以发动。获得该怪兽的控制权。然后将１只“爬虫妖衍生物”（爬虫类族・地・星１・攻／守０）特殊召唤至对手场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17000166,'爬虫妖衍生物','由“爬虫妖产卵”等的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17008760,'原物质之圆环炉',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：去除自己场上的１个超量素材。所去除的超量素材被送至自己墓地的情况下，进而可将该卡放置在自己场上。','\r',char(13)),'\n',char(10)),'','是否把那张卡放置？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17016131,'海造贼－骄傲',replace(replace('具此卡名的①②效果１回合各只能使用１次。\r\n①：我方的“海造贼”怪兽在战斗中破坏对手怪兽的情况下可发动。我方从卡组抽１张卡。\r\n②：我方场上存在“海造贼”怪兽时，将魔法与陷阱区域内面朝上的此卡送至墓地，可从以下效果选择１项发动。\r\n●对手从卡组抽１张卡。然后，我方确认对方手牌，选择其中１只怪兽送至墓地。\r\n●确认对手的额外卡组，选择其中１张送至墓地。','\r',char(13)),'\n',char(10)),'','手牌送至墓地','额外牌组送至墓地','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17016362,'娱乐巫师 高空秋千魔术师',replace(replace('魔法师族等级4怪兽×2\r\n①：只要此卡存在于怪兽区域，自己不受此卡攻击力以下的战斗・效果伤害。\r\n②：在每个自己・对手的主要阶段1仅有1次，去除此卡的1个超量素材，以回合玩家的、场上的1只其他表侧攻击表示怪兽为对象可以发动。此回合，该怪兽可攻击2次，将在战斗阶段结束时被破坏。\r\n③：此卡因战斗或对手的效果被破坏并被送至墓地的情况下可以发动。从牌组将1只“娱乐巫师”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'多次攻击','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17020474,'艮鬼神 朱沙之王',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡同步召唤的情况下，从自己墓地将任意数量的陷阱卡除外可以发动。依其数量将场上的卡除外。\r\n②：在自己・对手的结束阶段，以自己墓地・除外状态的最多2张“艮鬼”怪兽・陷阱卡为对象可以发动。将该卡分别加入手牌或放置在自己场上。以2张卡为对象来发动的情况下，进而将此卡放回额外牌组。','\r',char(13)),'\n',char(10)),'破坏','回收','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17021204,'母蜘蛛','我方墓地的怪兽仅为昆虫族的场合，磁卡可将对手场上的２只表侧守备表示怪兽送入墓地，并从手牌特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17032740,'元素－英雄 混沌新宇侠',replace(replace('“元素－英雄 新宇侠”＋“新空间人 漆黑猎豹”＋“新空间人・光辉青苔”\r\n仅限我方场上的上述卡牌返回至持有者牌组的场合，可从额外牌组特殊召唤（不需要“融合”）。结束阶段时，此卡返回至持有者的额外牌组，场上表侧表示的所有怪兽变成里侧守备表示。此外，仅限１次可在我方主要阶段执行掷硬币３次。根据出现正面的次数适用以下效果。\r\n●３次：破坏对手场上的所有怪兽。\r\n●２次：直至回合结束时，对手场上表侧表示怪兽的效果全部被无效化。\r\n●１次：我方场上存在的怪兽全部返回至持有者手牌。','\r',char(13)),'\n',char(10)),'返回牌组','投掷硬币','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17045014,'进化龙・梁龙','①：此卡以“进化虫”怪兽的效果特殊召唤的情况下，以对手场上的１张魔法・陷阱卡作为对象发动。将该对手的卡破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17052477,'守护神的宝牌',replace(replace('①：可舍弃５张手牌并发动此卡。我方从牌组抽取２张卡牌。\r\n②：只要此卡存在于魔法与陷阱区域，我方抽取阶段的通常抽取变成２张。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17063599,'风之天翼 米勒德拉','此卡名的①②效果１回合仅可各使用１次，该发动和效果不会被无效化。①：对手从额外牌组特殊召唤攻击力２０００以上的怪兽的情况下可以发动。从手牌将此卡特殊召唤。②：此卡从手牌被特殊召唤成功的情况下，以对手场上的１只被从额外牌组特殊召唤的表侧表示怪兽为对象可以发动。此怪兽以表侧表示存在期间，对象怪兽不可发动效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17078030,'光之护封壁','支付１０００的倍数的LP可以发动此卡。只要此卡存在于场上，拥有支付的生命值的数值以下攻击力的对手怪兽不可攻击。','请选择支付的基本分','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17080584,'海皇精 邃渊莱因',replace(replace('此卡名在规则上也视为“水精鳞”卡。\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：解放手牌的此卡和自己手牌・场上的、１只“海皇”怪兽或“水精鳞”怪兽可以发动。从牌组挑选１只等级７的鱼族・海龙族・水族怪兽，加入手牌或特殊召唤。此回合，自己从额外牌组仅可特殊召唤水属性怪兽。\r\n②：在对手回合中，将墓地的此卡除外，将１张手牌舍弃至墓地可以发动。自己抽１张。','\r',char(13)),'\n',char(10)),'特殊召唤','抽牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17086528,'相生的魔术师',replace(replace('←8 【灵摆】 8→\r\n①：１回合１次，以自己场上的１只超量怪兽和１只等级５以上的怪兽为对象可以发动。该超量怪兽的阶级直至回合结束时为止，变为与该等级５以上怪兽的等级相同的数值。②：自己场上的卡多于对手场上的情况下，此卡的灵摆刻度变为４。\r\n【怪兽效果】\r\n①：因此卡的战斗对对手造成的战斗伤害变为０。②：１回合１次，以自己场上此卡以外的１只怪兽为对象可以发动。此卡的攻击力直至回合结束时为止，变为与该怪兽相同。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17092736,'古代的望远镜','可查看对手牌组最上面的５张卡牌。查看后将卡牌放回到原处。','请选择要查看的数目','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17115745,'尤蒙刚德','出现在神话世界的蛇，身体非常长。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17129783,'星圣 狮子雷奥尼斯','①：只要此卡存在于怪兽区域，自己在通常召唤之外，可在自己的主要阶段追加1次召唤1只“星圣”怪兽。','使用「星圣 狮子雷奥尼斯」的效果召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17132130,'命运－英雄 教义魔侠','此卡不可通常召唤。仅可在解放自己场上包含“命运-英雄”怪兽在内的3只怪兽的情况下特殊召唤。①：以此方法此卡特殊召唤成功的情况下，在下一个对手的准备阶段发动。将对手的LP改成一半。','特殊召唤','LP减半','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17141718,'花札卫－芒－',replace(replace('①：我方场上存在有等级７或以下的“花札卫”怪兽的场合可发动。从手牌特殊召唤此卡。此效果发动后，直至回合结束时，我方只可召唤、特殊召唤“花札卫”怪兽。\r\n②：此卡召唤、特殊召唤成功的场合可发动。向对手展示手牌任意数量的“花札卫”怪兽，返回至牌组并洗牌。之后，我方从牌组抽取相当于返回至牌组数量的卡牌。','\r',char(13)),'\n',char(10)),'特殊召唤','手牌回到牌组','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17151328,'旋涡海炎',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：可从以下效果中选择１个发动。\r\n●从手牌将１只水属性怪兽舍弃至墓地，以对手场上的１只表侧表示怪兽为对象可以发动。将该怪兽破坏。\r\n●将手牌的１只炎属性怪兽破坏。然后，自己可抽１张。\r\n②：仅有对手场上才存在怪兽的情况下，将墓地的此卡除外，以自己墓地的１只等级７・８的水・炎属性怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'发动','特殊召唤','破坏对手场上表侧表示怪兽','手牌1只炎属性怪兽破坏','是否抽牌？','','','','','','','','','','','');
INSERT INTO texts VALUES(17170970,'装甲白熊',replace(replace('此卡名的效果①②在1个回合中仅可各使用1次。\r\n①：场上存在同步怪兽，且此卡召唤或特殊召唤成功时，可以以自己墓地的1张场地魔法卡为对象发动。将该卡加入手牌。\r\n②：此卡因战斗或对手的效果被破坏且送至墓地后可以发动。从自己的牌组、墓地选择1只“装甲白熊”以外的等级4以下的兽族怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17178486,'生命转换装置','双方LP的差额为８０００点或以上的场合可发动。双方的LP变成３０００。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17183908,'龙星的辉迹','此卡名的卡1回合仅可发动1张。①：以自己墓地3只“龙星”怪兽为对象可以发动。将该3只怪兽放回牌组洗牌。然后，自己从牌组抽2张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17185260,'炼狱铁锤','①：此卡因战斗破坏对手怪兽并送入墓地时，可以对手场上的１只表侧表示怪兽为对象发动。该对手的表侧表示怪兽变成里侧守备表示。','变成里侧守备','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17188206,'R.B.拉姆达刃',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将“R.B.拉姆达刃”以外的1张“R.B.”卡送至墓地。\r\n②：在对手的主要阶段，此卡和“R.B.”连接怪兽为连接状态的情况下，支付1400LP，以对手场上的1只怪兽为对象可以发动。将此卡破坏，获得该怪兽的控制权。以此效果获得控制权的怪兽将在结束阶段被破坏。','\r',char(13)),'\n',char(10)),'送至墓地','控制权','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17189532,'幻影豹镖','场上的此卡被破坏并送入墓地的场合可发动。从牌组将２张冠有“豹镖”之名的卡牌加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17189677,'蛇雨','①：舍弃1张手牌可以发动。从牌组将4只爬虫类族怪兽送至墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17192817,'熔岩大巨人','诞生于岩浆大地的巨人。会用岩浆拳发动攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17194258,'融合征兵',replace(replace('１个回合中只可发动１张“融合征兵”。\r\n①：向对手展示额外牌组中的１只融合怪兽，并从我方的牌组・墓地选取１只该怪兽记述有卡牌名称的融合素材怪兽加入到手牌中。发动此卡后直到回合结束时，我方不可通常召唤或特殊召唤以此效果加入到手牌中的怪兽及其同名怪兽，且不可发动该怪兽效果。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17197110,'抵达冰结界的晴岚',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：解放自己场上任意数量的“冰结界”怪兽可以发动。依所解放的数量，从牌组将等级４以下的“冰结界”怪兽特殊召唤（同名卡最多１张）。\r\n②：从墓地将不是在此回合被送至墓地的此卡除外，以自己墓地・除外状态的１只“冰结界”怪兽为对象可以发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17201174,'槌头鲨','１回合１次，可在我方主要阶段时发动。此卡的等级下降１级，从手牌特殊召唤１只水属性、等级３或以下的怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17201951,'极驰高速战士',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将1只“废品同步士”或1张记载有“废品战士”卡名的魔法・陷阱卡加入手牌。\r\n②：只要此卡存在于怪兽区域，自己场上的以下的怪兽的攻击力仅在自己的战斗阶段期间上升900。\r\n●记载有“废品战士”卡名的怪兽\r\n●原本卡名包含“战士”的同步怪兽','\r',char(13)),'\n',char(10)),'检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17209452,'杀手旋律・萝塔丽',replace(replace('要以场上的此卡作为素材同步召唤的情况下，可将手牌的1只协调也作为同步素材。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：向对手出示手牌的此卡与手牌的1只协调可以发动。进行1只协调的召唤。\r\n②：此卡作为同步素材被送至墓地的情况下，可从以下效果中选择1个发动。\r\n●从对手墓地将1张卡放回牌组最下面。\r\n●确认对手的所有手牌。然后，可从牌组将1张“杀手旋律”魔法・陷阱卡加入手牌。','\r',char(13)),'\n',char(10)),'召唤','作为同步素材送至墓地','对手墓地让1张卡回到牌组最下面','确认对手手牌','是否把魔法·陷阱卡加入手牌？','','','','','','','','','','','');
INSERT INTO texts VALUES(17214465,'海神的巫女','①：不存在表侧表示的场地魔法卡的情况下，场地变为“海”。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17217034,'合体术式－交闪零式',replace(replace('光・暗属性怪兽2只\r\n此卡名在规则上也视为“闪刀姬”卡。\r\n自己1回合仅可特殊召唤1次“合体术式－交闪零式”，此卡不可作为连接素材。\r\n①：此卡特殊召唤的情况下，以场上的1只攻击力2500以上的怪兽为对象可以发动。将该怪兽的效果直至回合结束时为止无效。\r\n②：自己墓地存在“闪刀姬－零”及“闪刀姬－萝杰”的情况下，此卡攻击的伤害步骤开始时可以发动。将对手场上的怪兽全部破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17228908,'失落世界','①：场上恐龙族以外的怪兽的攻击力・守备力下降５００。②：１回合１次，恐龙族怪兽被召唤・特殊召唤的情况下可以发动。将１只“侏罗蛋衍生物”（恐龙族・地・星１・攻／守０）以守备表示特殊召唤至对手场上。③：只要对手场上有衍生物，对手不可将场上衍生物以外的怪兽作为效果的对象。④：１回合１次，场上的通常怪兽将被战斗・效果破坏的情况下，可依其数量破坏自己手牌・牌组的恐龙族怪兽作为代替。','特殊召唤衍生物','是否使用「迷失世界」的效果代替破坏？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17228909,'侏罗蛋衍生物','由“失落世界”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17236839,'瞬间融合','①：从我方场上将根据融合怪兽卡而决定的融合素材怪兽送入墓地，从额外牌组融合召唤１只该融合怪兽。以此效果融合召唤的怪兽，在结束阶段被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17238333,'阁楼中的怪物','家家户户的阁楼中都藏着的怪物。无害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17241370,'咒仪・娜塔莉亚','此卡不可特殊召唤。①：此卡召唤・反转时，以自己墓地的１只“咒仪”怪兽为对象可以发动。将该怪兽放回牌组最上面。②：此卡召唤・反转的回合的结束阶段发动。将此卡放回持有者的手牌。','返回手牌','返回牌组','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17241941,'大雷陀螺仪 独眼巨人',replace(replace('←5 【灵摆】 5→\r\n①：１回合１次，以自己场上的１只灵摆怪兽和对手场上的１只怪兽为对象可以发动。变更该怪兽的表示形式。\r\n【怪兽效果】\r\n从额外牌组特殊召唤的此卡被使用于同步召唤的情况下将被除外。\n此卡名的②③怪兽效果１回合仅可各使用１次。\n①：此卡召唤成功的情况下可以发动。变更此卡的表示形式。\n②：此卡的表示形式被变更的情况下，以场上的１张表侧表示魔法・陷阱卡为对象可以发动。将该卡破坏。\n③：此卡在灵摆区域被破坏的情况下可以发动。挑选自己灵摆区域的１张卡放回持有者的手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17242022,'真红眼超越黑龙',replace(replace('“真红眼黑龙”＋记载有“时间黑魔术师”卡名的怪兽\r\n“真红眼超越黑龙”1回合1次，仅可通过融合召唤及以下方法特殊召唤。\r\n●有怪兽因“时间黑魔术师”的效果被破坏的回合，将自己・对手场上的1只表侧表示怪兽解放的情况下，可从额外牌组特殊召唤。\r\n①：此卡特殊召唤的情况下可以发动。从自己手牌・墓地将1只等级8以下的怪兽特殊召唤。\r\n②：场上的此卡不受对手发动的魔法・怪兽的效果影响。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17242023,'真红眼超越黑龙',replace(replace('“真红眼黑龙”＋记载有“时间黑魔术师”卡名的怪兽\r\n“真红眼超越黑龙”1回合1次，仅可通过融合召唤及以下方法特殊召唤。\r\n●有怪兽因“时间黑魔术师”的效果被破坏的回合，将自己・对手场上的1只表侧表示怪兽解放的情况下，可从额外牌组特殊召唤。\r\n①：此卡特殊召唤的情况下可以发动。从自己手牌・墓地将1只等级8以下的怪兽特殊召唤。\r\n②：场上的此卡不受对手发动的魔法・怪兽的效果影响。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17243896,'大地蜘蛛','１回合１次，此卡以表侧守备表示存在于我方场上的场合，对手召唤、特殊召唤成功时，可将该怪兽变为守备表示。','变成守备表示','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17255673,'天御巫之阖',replace(replace('①：只要装备有装备卡的怪兽存在于自己场上，可攻击的对手怪兽必须攻击装备有装备卡的怪兽。\r\n②：自己的“御巫”怪兽进行战斗的情况下，对手直至伤害步骤结束时为止，不可发动魔法・陷阱・怪兽的效果。\r\n③：自己的“御巫”怪兽进行攻击的伤害步骤结束时，将自己场上的1张装备卡送至墓地可以发动。该怪兽可继续攻击对手怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17257342,'光之精灵 狄安娜','此卡不可通常召唤。可在将1只光属性怪兽从自己墓地除外的情况下特殊召唤。①：于对手的结束阶段发动。自己恢复1000LP。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17259470,'僵尸主宰者','①：１回合１次，从手牌将１只怪兽送至墓地，以自己或对手墓地１只等级４以下的不死族怪兽为对象可以发动。将该不死族怪兽特殊召唤至自己场上。此效果在此卡以表侧表示存在于怪兽区域的情况下才能发动和处理。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17264592,'超级运动员劲敌篮板手',replace(replace('１回合只可使用１次以“超级运动员劲敌篮板手”①方法的特殊召唤，②的效果１回合只可使用１次。\r\n①：此卡可将除“超级运动员劲敌篮板手”以外的我方场上的１只“超级运动员”怪兽返回至手牌，并从手牌特殊召唤。\r\n②：此卡召唤成功，或对手回合中特殊召唤成功的场合可发动。从我方手牌、墓地挑选１只除“超级运动员劲敌篮板手”以外的“超级运动员”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17266660,'朱光之宣告者','①：对手发动怪兽的效果时，从手牌将此卡和１只天使族怪兽送至墓地可以发动。将该发动无效并破坏。','效果怪兽的效果的发动无效并破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17269895,'霸者之鸣动',replace(replace('此卡名的卡1回合仅可发动1张，对手特殊召唤过10只以上怪兽的回合，应对此卡的发动不可发动效果。\r\n①：根据此回合对手特殊召唤过的怪兽数量，分别适用以下效果。\r\n●1只以上：将自己墓地・除外状态的1只暗属性同步怪兽特殊召唤。\r\n●3只以上：直至下个自己回合结束时为止的期间，自己的怪兽区域的“暗红恶魔龙”不受对手发动的效果影响。\r\n●5只以上：将对手场上的怪兽全部改成里侧守备表示。','\r',char(13)),'\n',char(10)),'发动','「霸者之鸣动」适用中','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17272964,'玛那桃圆乡・无畏','此卡名以①方法的特殊召唤１回合仅可进行１次。①：自己场上存在“维萨思・史塔弗罗斯特”或攻击力１５００／守备力２１００的怪兽的情况下，此卡可从手牌中特殊召唤。②：此卡因战斗・效果被破坏的情况下可以发动。从牌组将１只“玛那桃圆乡・无畏”特殊召唤。发动了此效果的回合的战斗阶段中，自己场上的同步怪兽的攻击力上升５００。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17285476,'大植然蚊','只要自己场上有此卡以外的“大植然”怪兽存在，对手不可将此卡选择为攻击对象。此卡以外的自己的“大植然”怪兽的战斗对自己产生的战斗伤害由对手代替承受。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17286057,'三子太阳・赫利欧斯','此卡可解放我方场上的１只“双子太阳・赫利欧斯”，并从手牌特殊召唤。此卡的攻击力、守备力变成从游戏中被除外怪兽数量×３００点。此卡因战斗被破坏并送入墓地回合的结束阶段时，将此卡的攻击力、守备力上升５００点并特殊召唤。对手场上存在有怪兽的场合，可连续再进行１次攻击。','特殊召唤','连续攻击','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17313545,'魔像','只要此卡以表侧表示存在于场上，场上表侧表示的的光属性怪兽效果被无效化。此卡因战斗破坏了光属性怪兽的场合，仅１次可再连续攻击。','连续攻击','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17315396,'死神官－苏帕伊',replace(replace('此卡名的效果１回合仅可使用１次。\r\n①：舍弃此卡以外的１张手牌可以发动（发动此效果的回合中，自己从额外牌组仅可特殊召唤同步怪兽）。从手牌将此卡以守备表示特殊召唤。然后，可从手牌・牌组将１只“苏帕伊”特殊召唤。','\r',char(13)),'\n',char(10)),'','是否特殊召唤「苏帕伊」？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17322533,'一点着地',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：仅1只怪兽被特殊召唤的情况下，若其为从自己或对手的手牌特殊召唤至自己场上则可以发动。自己抽1张。\r\n②：在自己回合中未用此卡的①效果抽牌的情况下，此卡将在该回合的结束阶段被送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17328157,'疾行机人 竹跷马','此卡名的②效果1回合仅可使用1次。①：此卡召唤成功时可以发动。从手牌将1只等级4以下的“疾行机人”怪兽特殊召唤。②：将墓地的此卡除外可以发动。从牌组将1只风属性怪兽送至墓地。此效果在此卡被送至墓地的回合不可发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17330916,'娱乐伙伴 琴键猴',replace(replace('←1 【灵摆】 1→\r\n此卡名的②灵摆效果１回合仅可使用１次。\n①：另一方自己的灵摆区域不存在“娱乐伙伴”卡的情况下，此卡的灵摆刻度变为４。\n②：在发动了此卡的回合的自己的主要阶段可以发动。从牌组将等级４以下的１只“娱乐伙伴”怪兽加入手牌。\r\n【怪兽效果】\r\n①：从手牌将此卡舍弃可以发动。将手牌的１只“娱乐伙伴”怪兽或“异色眼”怪兽出示给对手。此回合，该怪兽及自己手牌的同名怪兽的等级下降１。','\r',char(13)),'\n',char(10)),'降低等级','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17358176,'高等女祭司','吟唱闻所未闻的咒文，安抚狂乱的心灵。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17363041,'茧状体・小雏鸟','可解放此卡并发动。从手牌・牌组特殊召唤１只“新空间人・天空蜂鸟”。此效果在我方场上存在有“新宇空间”的场合可发动与处理。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17375316,'收押','支付１０００LP可以发动。确认对手的手牌，并从其中挑选１张卡舍弃。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17377751,'黑羽－煌星之格拉墨',replace(replace('协调＋１只以上协调以外的怪兽\r\n此卡从额外牌组仅可通过同步召唤来特殊召唤。①：此卡同步召唤成功时可以发动。从手牌将１只协调以外的等级４以下的“黑羽”怪兽特殊召唤。以此效果特殊召唤的怪兽的效果无效化。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17382973,'调皮宝贝・喔喔鸡',replace(replace('“调皮宝贝”怪兽２只\r\n具此卡名的①②效果１回合各只能使用１次。\r\n①：此卡在连接召唤成功的情况下可发动。从卡组将１张“调皮宝贝”魔法／陷阱卡加入手牌。\r\n②：解放此卡后，以我方墓地中除连接怪兽外的２张“调皮宝贝”卡为目标可发动（同名卡最多１张）。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17390179,'闪光骑士',replace(replace('←7 【灵摆】 7→\r\n【怪兽效果】\r\n通过神的钟摆领悟了崭新力量的骑士。现在正是觉醒时刻，解放汝之力量吧！','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17393207,'守墓的司令官','可将手牌中的此卡弃置至墓地来发动此卡。将牌组中的１张“王家长眠之谷－死灵谷”加入到手牌中。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17412721,'旧神诺登',replace(replace('同步・超量怪兽＋同步・超量怪兽\r\n此卡名的效果1回合仅可使用1次。\r\n①：此卡从额外牌组特殊召唤时，以自己墓地的1只等级4以下的怪兽为对象可以发动。将该怪兽的效果无效并特殊召唤。此卡从场上离开时该怪兽将被除外。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17415895,'火山性利刃','１回合１次，自己的主要阶段时可以发动。给予对手LP５００点伤害。发动此效果的回合中，此卡不可攻击。','给予对手500伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17418744,'光子圣域','发动此卡的回合中，自己仅可召唤・反转召唤・特殊召唤光属性怪兽。①：将2只“光子衍生物”（雷族・光・星4・攻2000/守0）以守备表示特殊召唤至自己场上。此衍生物不可攻击，也不可作为同步素材。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17418745,'光子衍生物','由“光子圣域”的效果特殊召唤而来。此衍生物不可攻击，也不可用作同步材料。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17427333,'电磁轨道炮','①：解放自己场上的１只机械族怪兽，以场上的卡为对象可以发动，对象数量最多为解放怪兽原本攻击力除以１０００的整数位数值。将该卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17441953,'龟狸','背着龟壳的狸。会变成对手的模样进行攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17444133,'帝王海马','①：上级召唤光属性怪兽的情况下，此卡可作为2只解放。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17449108,'扑灭之使徒','选择场上１张被盖牌的魔法、陷阱卡，将其破坏并从游戏中除外。该卡牌是陷阱卡的场合，双方相互确认牌组，将所有同名卡牌从游戏中除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17462320,'世坏挽歌',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：从牌组将１只“韦陀”怪兽加入手牌。\r\n②：此卡存在于墓地，场上存在“维萨思・史塔弗罗斯特”的状态下，自己场上的表侧表示协调因战斗・效果被破坏的情况下，将此卡除外，以其中１只为对象可以发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17465972,'黑羽－南风之奥斯特',replace(replace('此卡不可特殊召唤。①：此卡召唤成功时，可以自己的1只被除外的、等级4以下的“黑羽”怪兽为对象发动。以守备表示形式将该怪兽特殊召唤。②：将墓地的此卡除外，可从以下效果中选择1个发动。\r\n●挑选自己场上的1只“黑翼龙”，放相当于对手场上卡数量的黑羽计数物。\r\n●尽可能在对手场上所有的表侧表示怪兽上各放上1个楔计数物（最多1个）。','\r',char(13)),'\n',char(10)),'','「黑双足翼龙」放置计数物','对手全部怪兽放置计数物','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17469113,'双星神 阿－维达','此卡不可通常召唤。仅可在双方场上・墓地有8种以上的连接怪兽存在的情况下特殊召唤。将此卡特殊召唤的回合中，自己不可特殊召唤其他怪兽。①：此卡的特殊召唤不会被无效化。②：此卡特殊召唤成功的情况下发动。将此卡以外的、双方场上・墓地的怪兽及被除外的怪兽全部放回持有者的牌组。应对此效果的发动，魔法・陷阱・怪兽的效果不可发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17473466,'狱神影兽－涅尔绯多',replace(replace('←1 【灵摆】 1→\r\n此卡名的灵摆效果1回合仅可使用1次。\n①：连锁“狱神”怪兽或“神艺”怪兽的效果的发动，对手发动怪兽的效果的处理时，可将该效果无效。然后，将此卡破坏。\r\n【怪兽效果】\r\n此卡名在规则上也视为“神艺”卡。\n此卡名的①②怪兽效果1回合仅可各使用1次。\n①：从牌组上面将3张卡以里侧除外可以发动。将此卡破坏，从额外牌组将1只“创狱神 涅瓦”视为融合召唤特殊召唤。\n②：此卡以表侧加入额外牌组的情况下可以发动。从自己牌组・额外牌组（表侧）将除“狱神影兽－涅尔绯多”以外的1只“狱神”怪兽或“神艺”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'是否适用「狱神影兽－涅尔绯多」的效果来无效？','特殊召唤','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17475251,'英炎星－鹰荣',replace(replace('①：只要自己场上存在“炎舞”魔法・陷阱卡，自己场上的“炎星”怪兽的攻击力・守备力上升５００。\r\n②：此卡被对手破坏的情况下可以发动。从牌组将１张“炎舞”魔法卡放置在自己场上。','\r',char(13)),'\n',char(10)),'放置','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17484499,'现世与冥界的逆转',replace(replace('此卡名的卡在决斗中仅可发动1张。\r\n①：双方墓地的卡各有15张以上的情况下，支付1000LP可以发动。双方各自将自身牌组和墓地的卡全部交换（无法被加入牌组的卡则加入额外牌组）。然后，双方将牌组洗牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17490535,'外星人脑','自己的爬虫类族怪兽被对手怪兽的攻击破坏送往墓地时可以发动。获得该对手怪兽的控制权，并将该怪兽视为爬虫类族。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17494901,'我我我雷击','①：自己场上有“我我我”怪兽存在的情况下，以场上的１张卡为对象可以发动。将该卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17502671,'无限狱将军','我方手牌是０张的场合，可将墓地的此卡从游戏中除外，并选择我方墓地２只等级３或以下冠有“无限狱”之名的怪兽发动。特殊召唤被选择怪兽。以此效果特殊召唤的怪兽其效果被无效化。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17509503,'一色即发',replace(replace('此卡牌名的卡牌，１回合只可发动１张。\r\n①：从手牌特殊召唤等级４或以下的怪兽，其数量最多与对手场上的怪兽数量相同。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17511156,'木灵小丑','面带不怀好意笑容的恶魔。使用手上的镰刀灵巧地发动攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17521642,'零之力','我方场上的表侧表示怪兽从游戏中被除外时可发动。场上所有怪兽的攻击力变成０。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17530001,'魔术方块人','①：１回合１次，在我方主要阶段可发动。掷１次骰子。只要此怪兽以表侧表示存在于场上，双方不可召唤、特殊召唤与掷出点数相同等级的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17535588,'装甲海星','表皮坚硬守备力较高的蓝色海星。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17535764,'蟑螂柱',replace(replace('此卡名的效果１回合仅可使用１次。\r\n①：此卡被送至墓地的情况下可以发动。从牌组将１只等级４昆虫族怪兽加入手牌。以此效果加入了通常怪兽的情况下，进而可从手牌将该怪兽特殊召唤。然后，可将场上１只攻击力在以此效果特殊召唤的怪兽以上的怪兽破坏。','\r',char(13)),'\n',char(10)),'','是否特殊召唤？','是否破坏怪兽？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17536995,'变换徽章','对手怪兽攻击宣言时可发动。从手牌特殊召唤１只冠有“纹章兽”之名的怪兽，之后结束战斗阶段。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17540705,'娱乐伙伴飞刀匕首使',replace(replace('←2 【灵摆】 2→\r\n“娱乐伙伴飞刀匕首使”的灵摆效果１回合只可使用１次。\n①：在发动此卡回合之我方主要阶段，可以我方墓地的１只“娱乐伙伴”怪兽为对象发动。将该怪兽加入手牌。\r\n【怪兽效果】\r\n“娱乐伙伴飞刀匕首使”的怪兽效果１回合只可使用１次。\n①：在此卡灵摆召唤成功回合之我方主要阶段，可从手牌将１只“娱乐伙伴”怪兽送入墓地并发动。我方从牌组抽取１张卡牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17548456,'朱罗纪・陨星龙',replace(replace('“朱罗纪”协调＋协调以外的恐龙族怪兽2只以上\r\n①：此卡同步召唤的情况下发动。将场上的卡全部破坏。然后，可从自己墓地将1只协调特殊召唤。','\r',char(13)),'\n',char(10)),'破坏并特殊召唤','是否要特殊召唤一只协调？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17548457,'朱罗纪・陨星龙',replace(replace('“朱罗纪”协调＋协调以外的恐龙族怪兽2只以上\r\n①：此卡同步召唤的情况下发动。将场上的卡全部破坏。然后，可从自己墓地将1只协调特殊召唤。','\r',char(13)),'\n',char(10)),'破坏并特殊召唤','是否要特殊召唤一只协调？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17550376,'妮梦雷莉娅的守梦者－欧雷埃','此卡名以①方法的特殊召唤１回合仅可进行１次，且②效果１回合仅可使用１次。①：自己的额外牌组存在表侧表示的灵摆怪兽的情况下，此卡可从手牌中特殊召唤。②：自己的额外牌组存在表侧表示的“眠梦中的妮梦雷莉娅”的情况下，从额外牌组将１张里侧表示的卡以里侧表示除外可以发动。此卡的攻击力直至回合结束时为止，上升相当于对手场上的怪兽数量×５００的数值。此效果在对手回合中也可以发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17559367,'深海潜水员','此卡因战斗被破坏并被送入墓地的战斗阶段结束时，从牌组挑选１只怪兽置于牌组最上方。','检索','请选择放置在牌组最上方的怪兽卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17573739,'神禽王阿雷克多尔','对手场上存在有２只或以上相同属性怪兽的场合，此卡可从手牌特殊召唤。１回合１次，可选择场上的１张表侧表示卡牌并发动。直至回合结束时，使该卡牌的效果无效。场上只可有１张“神禽王阿雷克多尔”以表侧表示存在。','效果无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17589298,'生祭之剑','仅限装备暗属性怪兽。装备怪兽的攻击力上升４００点。此卡因解放装备怪兽被送入墓地的场合，此卡返回至手牌。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17597059,'冲击魔人','成功召唤・反转召唤・特殊召唤此卡时，令场上所有被盖牌的卡牌回到持有者的手牌中。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17601919,'鬼姬－南瓜公主','此卡在怪兽卡区被破坏的场合，可不送入墓地而被视为永续魔法卡以表侧表示放置于我方的魔法＆陷阱卡区。以此效果被视为永续魔法卡的场合，每次双方的准备阶段就在此卡放置１个南瓜计数物。对手场上全部怪兽的攻击力、守备力下降相当于被视为永续魔法卡的此卡上放置的南瓜计数物×１００点。','是否使用「鬼姬－南瓜公主」的效果？','放置计数物','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17616743,'唤忌的咒眼',replace(replace('此卡牌名的卡牌１回合只可发动１张。\r\n①：从我方的手牌、墓地挑选１只“咒眼”怪兽并特殊召唤。我方的魔法与陷阱区域存在有“塞勒涅的咒眼”的场合，还可从牌组特殊召唤１只“咒眼”怪兽作为代替。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17621695,'纠罪都市',replace(replace('此卡名在规则上也视为“纠罪巧”卡。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：以自己场上任意数量的“纠罪巧”灵摆怪兽卡为对象可以发动。将该卡放回手牌。\r\n②：自己场上的“纠罪巧”灵摆怪兽在主要阶段反转的情况下可以发动。挑选其中1只，放回手牌或放在自己的灵摆区域。\r\n③：在自己・对手的结束阶段发动。将自己场上的纠罪计数物全部去除，对手受到其数量×900的伤害。','\r',char(13)),'\n',char(10)),'回手','回手','伤害','放置灵摆区域','加入手牌','','','','','','','','','','','');
INSERT INTO texts VALUES(17626381,'补给部队','①：１回合１次，自己场上的怪兽因战斗・效果被破坏的情况下发动。自己抽１张。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17639150,'机壳的祭品',replace(replace('仅限装备“机壳”怪兽。\r\n①：装备怪兽的攻击力上升３００，且不会因战斗被破坏。\r\n②：上级召唤“机壳”怪兽的场合，装备怪兽可作为２只怪兽释放。\r\n③：此卡从场上被送入墓地的场合可发动。从牌组将１只“机壳”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'牌组检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17643265,'双头鲨','此卡召唤成功时可发动。可将我方场上所有鱼族、等级４怪兽的等级下降１。此卡可在１次的战斗阶段中攻击２次。','等级下降','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17649753,'异虫路克耶','此卡仅可在此卡反转的回合进行攻击宣言。此卡攻击了的场合，在战斗阶段结束时变成里侧守备表示。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17653779,'天使的手镜','对手的魔法卡以场上的１只怪兽作为对象发动时，可选择其它１张成为正确对象的卡牌并发动。此魔法卡的对象转移至被选择卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17655904,'毁灭的爆裂疾风弹',replace(replace('发动此卡的回合中，自己的“青眼白龙”不可攻击。\r\n①：自己场上存在“青眼白龙”的情况下可以发动。将对手场上的怪兽全部破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17658803,'翠玉石龙','会吞噬翠玉的龙。被其美丽身姿所吸引而丧命之人络绎不绝。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17663375,'古代机械齿轮飞龙','此卡名的①效果１回合仅可使用１次。①：此卡召唤・特殊召唤成功的情况下可以发动。从牌组将１张“古代机械齿轮飞龙”以外的“古代机械齿轮”卡加入手牌。此效果发动后，直至回合结束时为止自己不可放置卡。②：此卡攻击的情况下，对手直至伤害步骤结束时为止不可发动怪兽的效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17679043,'企鹅鱼雷',replace(replace('此卡名的效果②在１个回合中仅可使用１次。\r\n①：此卡可直接进行攻击。\r\n②：此卡给对手造成了战斗伤害时，可以以对手场上的１只等级６以下的怪兽为对象发动。获得该怪兽的控制权，直至结束阶段为止。通过此效果获得了其控制权的怪兽的效果失效，且该怪兽不可进行攻击宣言。\r\n③：此卡进行攻击的伤害步骤结束时发动。破坏此卡。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17688543,'过深的墓穴','①：可以我方或对手墓地的１只怪兽为对象发动。在下一个我方准备阶段，从墓地特殊召唤该怪兽至我方场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17691568,'雅－朋.克.轰击','此卡名的①效果1回合仅可使用1次。①：对手发动以自己的“朋.克.”怪兽为对象的效果的情况下，以对手场上的1张卡为对象可以发动。将该卡破坏。②：魔法与陷阱区域的此卡因对手的效果被破坏的情况下可以发动。自己场上的所有“朋.克.”怪兽此回合不会成为对手效果的对象，也不会因对手的效果而被破坏。','','','「雅乐朋.克.粉碎拍子」效果适用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17706537,'长毛兽化石','此卡因战斗破坏对手怪兽并送入墓地时，给予对手生命４００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17719582,'神艺逆转－动荡－',replace(replace('此卡名的①②效果1回合仅可各使用1次，发动此效果的回合中，自己从额外牌组仅可特殊召唤融合怪兽。\r\n①：以对手墓地的1只怪兽为对象可以发动。将自己场上的1只“神艺”怪兽放回手牌・额外牌组，将对象怪兽效果无效并特殊召唤至自己场上。\r\n②：此卡为发动“神艺学都”的效果被送至墓地的情况下可以发动。将自己墓地・除外状态的1张“神艺”魔法卡加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','回收魔法','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17720747,'黑蔷薇之魔女','此卡不可特殊召唤。①：自己场上没有其他卡存在，此卡召唤成功的情况下发动。自己从牌组抽１张，双方确认。所抽牌为怪兽以外的情况下，该卡将被送至墓地，此卡将被破坏。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17722185,'无敌光环','①：１回合１次，将自己场上１只表侧表示的仪式・融合・同步・超量・灵摆・连接怪兽除外可以发动。此回合，此卡存在于魔法与陷阱区域期间，与除外的怪兽种类（仪式・融合・同步・超量・灵摆・连接）相同的怪兽的效果无效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17725109,'青眼龙轰临',replace(replace('此卡名在规则上不视为“青眼”卡。\r\n此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：将自己牌组・墓地・除外状态的１只“青眼”怪兽以守备表示特殊召唤。自己场上不存在“青眼白龙”的情况下，此效果仅可特殊召唤“青眼白龙”。此回合，自己从额外牌组仅可特殊召唤龙族怪兽。\r\n②：将墓地的此卡除外可以发动。将包含“青眼”怪兽在内的、自己手牌・场上的怪兽作为融合素材，将１只融合怪兽融合召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','融合召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17732278,'新空间人・光辉青苔',replace(replace('此卡进行战斗攻击宣言时，对手抽取１张卡牌并互相确认。根据该卡的种类适用以下效果：\r\n●怪兽卡：结束战斗阶段。\r\n●魔法卡：此卡可直接攻击对手玩家。\r\n●陷阱卡：此卡变更成守备表示。','\r',char(13)),'\n',char(10)),'抽牌','是否要进行直接攻击？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17733394,'森之尸','森林守护神死后，被恶魔所唤醒的尸体。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17739335,'咒眼之王 萨拉卡埃尔',replace(replace('“咒眼”怪兽２只以上\r\n此卡名的②效果１回合仅可使用１次。\r\n①：以攻击力２６００以上的怪兽作为素材连接召唤的此卡在１次战斗阶段中可攻击２次。\r\n②：此卡装备了“塞勒涅的咒眼”的情况下，以对手场上的１张卡为对象可以发动。将该卡破坏。此效果在对手回合中也可以发动。\r\n③：发动过此卡的②效果的情况下，将在下一个准备阶段发动。挑选此卡连接端的１只效果怪兽，将其效果无效。','\r',char(13)),'\n',char(10)),'卡片破坏','效果无效','攻击力2600以上的怪兽作为连接素材','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17745969,'超级交通机人－移动基地',replace(replace('“机人”融合怪兽＋“机人”怪兽\r\n此卡牌名的①效果１回合只可使用１次。\r\n①：可以对手场上的１只表侧表示怪兽为对象发动。从牌组、额外牌组特殊召唤１只持有攻击力是该怪兽攻击力或以下的“机人”怪兽。\r\n②：在我方、对手的结束阶段，可以除此卡以外的我方主要怪兽区的１只“机人”怪兽为对象发动。将该我方怪兽返回至持有者手牌，将此卡的位置移至该怪兽区。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17749468,'圣徒人祖－赎罪神女',replace(replace('“圣徒妖主”＋融合・同步怪兽\r\n此卡从额外牌组仅可通过融合召唤及以下方法特殊召唤。\r\n●解放自己场上的1只“圣徒蓟主”和对手场上的1只表侧表示怪兽的情况下，可从额外牌组特殊召唤。\r\n①：场上的此卡不会因效果被破坏。\r\n②：每当对手发动魔法・陷阱・怪兽的效果，对手场上的所有怪兽的攻击力下降500。\r\n③：只要此卡存在于怪兽区域，对手不可发动攻击力0的怪兽的效果。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17751597,'烙印断罪',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：包含将怪兽特殊召唤的效果的、怪兽的效果・魔法・陷阱卡发动时可以发动。从自己场上的表侧表示怪兽中挑选1只、或从自己墓地挑选2只需以“阿尔白斯之落胤”作为融合素材的融合怪兽放回额外牌组，将该发动无效并破坏。\r\n②：将墓地的此卡除外，以“烙印断罪”以外的、自己墓地的1张“烙印”魔法・陷阱卡为对象可以发动。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17760003,'A次代机・三重武装',replace(replace('“次代机・控制者”＋协调以外的怪兽１只以上\r\n①：１回合１次，舍弃１张手牌，根据作为此卡的同步素材的、协调以外的怪兽的属性，可从以下效果中选择１个发动。\r\n●风：随机将对手的１张手牌送至墓地。\r\n●水：以场上的１张魔法・陷阱卡为对象可以发动。将该卡破坏。\r\n●暗：以场上的１只光属性怪兽为对象可以发动。将该光属性怪兽破坏，自己抽１张。','\r',char(13)),'\n',char(10)),'对手手牌随机1张送至墓地','场上存在的1张魔法或者陷阱卡破坏','场上表侧表示存在的1只光属性怪兽破坏','风属性怪兽作为同步素材','水属性怪兽作为同步素材','暗属性怪兽作为同步素材','','','','','','','','','','');
INSERT INTO texts VALUES(17775525,'超重蒸鬼 铁道王－O',replace(replace('“超重武者”协调＋２只以上协调以外的“超重武者”怪兽\r\n此卡名在规则上也视为“超重武者”卡。①：此卡可在表侧守备表示的状态下攻击。该情况下，将此卡的守备力视为攻击力来进行伤害计算。②：１回合１次，舍弃最多２张手牌，依所舍弃的数量，以对手场上的卡为对象可以发动。将该卡破坏。③：１回合１次，在自己的主要阶段可以发动。将双方墓地的魔法・陷阱卡全部除外，给予对手相当于所除外数量×２００的伤害。','\r',char(13)),'\n',char(10)),'卡片破坏','魔陷除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17787975,'次元斯芬克斯',replace(replace('可以我方场上的１只表侧攻击表示怪兽为对象发动此卡。\r\n①：对象怪兽被攻击力高于该怪兽的对手怪兽攻击的战斗步骤中，仅１次，可发动此效果。给予对手相当于该攻击怪兽与对象怪兽攻击力差值的伤害。\r\n②：对象怪兽从场上离开的场合此卡被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17810268,'云魔物－酸雨云','此卡不会因战斗而被破坏。此卡以表侧守备表示存在的场合，被破坏。此卡召唤成功时，在此卡放置雾计数物，其数量相当于场上冠有“云魔物”之名怪兽的数量。可移除此卡的２个雾计数物并发动。选择场上的１张魔法、陷阱卡破坏。','放置计数物','魔陷破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17814387,'援军','可选择１只以表侧表示存在于场上的怪兽发动此卡，令所选择怪兽的攻击力上升５００点，直到结束阶段时。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17825378,'捕食植物 黏菖蒲螳螂',replace(replace('←8 【灵摆】 8→\r\n①：只要此卡存在于灵摆区域，自己要融合召唤暗属性融合怪兽的情况下，也可将存在于自己的灵摆区域的融合素材怪兽当作场上的怪兽来作为融合素材使用。\r\n【怪兽效果】\r\n①：此卡作为融合召唤的素材，并被送至墓地的情况下或以表侧加入额外牌组的情况下可以发动。以自己场上怪兽的数量为上限，挑选场上怪兽。在该怪兽上各放1个捕食计数物。放有捕食计数物的等级2以上怪兽的等级变为1。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17827173,'随风飘飘游×大嘴','此卡名的①③效果１回合仅可各使用１次，发动此效果的回合中，自己不可将怪兽特殊召唤。①：此卡召唤成功的情况下，以自己１张被除外的“随风飘飘游”卡为对象可以发动。将该卡加入手牌。然后，可召唤１只鸟兽族怪兽。②：表侧表示的此卡离开场上的情况下，将其除外。③：此卡在被除外的状态下，鸟兽族怪兽被召唤至自己场上的情况下可以发动。将此卡加入手牌。','','此卡加入手牌','是否把鸟兽族怪兽召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17832359,'森之圣骑士 汪宝',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将1张“童话序章 启程之晓光”加入手牌。自己场上或墓地存在“童话序章 启程之晓光”的情况下，自己也可抽1张作为代替。\r\n②：只要场地区域存在卡，对手怪兽不可将其他怪兽选择为攻击对象。\r\n③：此卡因战斗被破坏时可以发动。破坏了此卡的怪兽的攻击力下降500。','\r',char(13)),'\n',char(10)),'检索','','攻击力下降','是否作为代替而抽牌？','','','','','','','','','','','','');
INSERT INTO texts VALUES(17841097,'针枪手','以此卡为同步素材的同步怪兽攻击了守备表示怪兽时，若攻击力超过其守备力，给予对手生命相当于该差值的战斗伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17841166,'磁石之力','①：此回合中，原本种族为机械族・岩石族的场上的怪兽不受自身以外的对手怪兽的效果影响。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17856505,'鬼魂大王－南瓜王－',replace(replace('不死族等级6怪兽×2\r\n此卡名的①③效果1回合仅可各使用1次。\r\n①：此卡特殊召唤的情况下可以发动。从牌组将1张“活死人的呼唤”或记载有该卡名的卡加入手牌。\r\n②：只要自己场上存在“活死人的呼唤”，对手不可将自己场上的不死族怪兽作为怪兽效果的对象。\r\n③：去除此卡的1个超量素材，以场上的最多2张卡为对象可以发动。将该卡放回手牌。','\r',char(13)),'\n',char(10)),'','检索','回到手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17857780,'娱乐伙伴啦啦队鼹鼠',replace(replace('←5 【灵摆】 5→\r\n①：我方场上灵摆怪兽的攻击力提升３００。\r\n【怪兽效果】\r\n“娱乐伙伴啦啦队鼹鼠”的怪兽效果１回合只可使用１次。\n①：在我方主要阶段，可以１只攻击力与原攻击力不同的怪兽为目标发动。根据该怪兽攻击力的数值，令以下效果生效。\n●如果该怪兽的攻击力高于其原攻击力，则将其攻击力提升１０００。\n●如果该怪兽的攻击力低于其原攻击力，则将其攻击力降低１０００。','\r',char(13)),'\n',char(10)),'攻守变换','攻守变换','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17871506,'真红眼凶星龙－陨星龙',replace(replace('①：只要此卡存在于场上・墓地，视为通常怪兽。②：场上视为通常怪兽的此卡可作为通常召唤再召唤１次。该情况下，此卡改视为效果怪兽，获得以下效果。\r\n●只要此卡存在于怪兽区域，自己场上此卡以外的“真红眼”怪兽不会因战斗・效果被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17874674,'破邪之刻印','在对手的准备阶段时，仅１次，可选择场上表侧表示的１张卡牌发动。只要此卡存在于场上，被选择卡牌的效果在该回合中变为无效。每次我方的准备阶段此卡的控制者支付５００LP，或不支付５００LP破坏此卡。','效果无效','是否支付500基本分维持「破邪之刻印」？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17881964,'暗黑火炎龙','“火炎草”＋“小龙”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17885118,'灵摆刻度',replace(replace('此卡名的卡１回合仅可发动１张。①：自己的灵摆区域存在２张卡的情况下，根据其灵摆刻度之差的数值，适用以下效果。\r\n●０：挑选场上的２张魔法・陷阱卡破坏。\r\n●１～３：从牌组将１只等级２～４的灵摆怪兽加入手牌。\r\n●４～６：从牌组将１只等级５～７的灵摆怪兽加入手牌。\r\n●７以上：挑选自己的灵摆区域的最多２张卡放回持有者的手牌。然后，可从手牌将１只灵摆怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','是否从手牌把灵摆怪兽特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17888577,'追逐音速者','“跨音速鸟”的降临所必需。此卡名的②效果１回合仅可使用１次。①：为使合计等级为４以上，解放自己手牌・场上的怪兽，从手牌将“跨音速鸟”仪式召唤。以此效果特殊召唤的怪兽的等级变为使用于该仪式召唤的怪兽的等级合计的等级。②：将墓地的此卡除外，以自己场上的１只仪式怪兽为对象可以发动。将１只种族或属性与该怪兽相同的仪式怪兽从牌组送至墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17896384,'魔法族的结界','每当场上的魔法师族怪兽被破坏时，在此卡上放置１个魔力计数物（最多４个）。此外，将放置有魔力计数物的此卡和１只以表侧表示存在于我方场上的魔法师族怪兽送入墓地，从牌组抽取与此卡上魔力计数物数量相同的卡牌。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17932494,'音速战士','①：此卡被送至墓地的情况下发动。自己场上所有等级2以下的怪兽的攻击力上升500。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17943271,'冥铭途・格布林',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：在自己・对手的主要阶段，自己场上存在“冥骸合龙－冥铭途拉尔泰库特利卡”的情况下，从手牌将此卡舍弃可以发动。此回合中，对手不可将自己场上的“冥铭途”怪兽作为效果的对象。\r\n②：在自己的主要阶段可以发动。将自己场上的１只“冥铭途”怪兽破坏，从牌组将“冥铭途・格布林”以外的最多２张“冥铭途”卡送至墓地（同名卡最多１张）。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17946349,'斩机直径',replace(replace('此卡名的①②效果１回合仅可各使用１次。①：此卡召唤成功时，可以自己墓地的１只电子界族・等级４怪兽为对象发动。将该怪兽特殊召唤。以此效果特殊召唤的怪兽不可发动效果。②：以场上的此卡为素材同步・超量召唤的“斩机”怪兽获得以下效果。\r\n●将此卡特殊召唤成功的回合中１次，对手发动魔法・陷阱・怪兽的效果时可以发动。将该效果无效。','\r',char(13)),'\n',char(10)),'','对手效果无效（斩机直径）','「斩机直径」效果适用中','已发动过效果','「斩机直径」效果适用中','','','','','','','','','','','');
INSERT INTO texts VALUES(17947697,'白之少女',replace(replace('此卡名的①②③效果１回合仅可各使用１次。\r\n①：将手牌・场上的此卡送至墓地可以发动。从自己手牌・牌组・墓地将１张“真之光”以表侧表示放在自己的魔法与陷阱区域。\r\n②：此卡存在于墓地的状态下，自己将“青眼白龙”特殊召唤的情况下可以发动。将此卡特殊召唤。\r\n③：场上的此卡成为攻击・效果的对象时可以发动。从自己墓地将１只“青眼白龙”或光属性・等级１协调特殊召唤。','\r',char(13)),'\n',char(10)),'表侧放置','此卡特殊召唤','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17948378,'朱罗纪・暴仔龙','①：在此卡战斗破坏对手怪兽的回合结束阶段，解放自己场上的1只“朱罗纪”怪兽可以发动。自己抽2张。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17954937,'巳剑大祓',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：对手发动魔法・陷阱・怪兽的效果时，解放自己场上1只等级5以上的爬虫类族怪兽可以发动。将该效果无效并破坏。\r\n②：将墓地的此卡除外，以自己墓地的1只爬虫类族怪兽为对象可以发动。将该怪兽特殊召唤，将以此效果特殊召唤的怪兽以外的、自己场上的1只怪兽解放。','\r',char(13)),'\n',char(10)),'无效并破坏','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17955766,'新空间人 水波海豚','①：１回合１次，舍弃１张手牌可以发动。确认对手的手牌，从其中挑选１只怪兽。自己场上有攻击力为所挑选怪兽的攻击力以上的怪兽存在的情况下，破坏所挑选的怪兽，给予对手５００伤害。不存在的情况下，自己受到５００伤害。','确认手牌','请选择一张怪兽卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17955767,'新空间人 水波海豚','①：１回合１次，舍弃１张手牌可以发动。确认对手的手牌，从其中挑选１只怪兽。自己场上有攻击力为所挑选怪兽的攻击力以上的怪兽存在的情况下，破坏所挑选的怪兽，给予对手５００伤害。不存在的情况下，自己受到５００伤害。','确认手牌','请选择一张怪兽卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17956906,'终幕之光',replace(replace('此卡牌名的卡牌１回合只可发动１张。\r\n①：支付１０００倍数的LP，每支付LP１０００，就可以我方墓地的１只“女战神”怪兽为对象发动（同名卡最多１张）。特殊召唤该怪兽。之后，对手可从自身的墓地挑选攻击力是２０００或以下的怪兽并特殊召唤，其数量相当于以此效果特殊召唤而来的怪兽数量。','\r',char(13)),'\n',char(10)),'请选择要特殊召唤的怪兽数量','是否特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17968114,'海原的女战士','侍奉海神的人鱼。守护着神圣的领域。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17979378,'DD 高傲骑士',replace(replace('←6 【灵摆】 6→\r\n①：１回合１次，可支付５００LP，并以对手场上１只表侧表示怪兽为对象发动。该怪兽的攻击力下降５００。\n②：另一边的我方灵摆区不存在有“DD”卡牌的场合，此卡的P刻度变成５。\r\n【怪兽效果】\r\n①：此卡召唤成功时可发动。从我方额外牌组将１只表侧表示的暗属性灵摆怪兽加入手牌。','\r',char(13)),'\n',char(10)),'攻守变换','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17985575,'龙之主宰－龙的支配者','①：只要此卡存在于怪兽区域，双方不可将场上的龙族怪兽作为效果的对象。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17988746,'派对夜骑士组','①：因对手怪兽的攻击使我方受到战斗伤害时可发动。从手牌特殊召唤此卡。之后，可从手牌特殊召唤１只持有攻击力是所受伤害数值或以下的怪兽。','此卡从手牌特殊召唤','是否特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(17994645,'强袭黑羽－雨隐之小夜',replace(replace('协调＋１只协调以外的怪兽\r\n①：以“黑羽”怪兽作为素材同步召唤的此卡视为协调。②：此卡１回合中最多２次，不会因战斗被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18000338,'复王龙EX','①：此卡与额外怪兽区域的怪兽进行战斗的情况下，仅伤害步骤期间，此卡的攻击力・守备力上升８００。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18013090,'氮素战士',replace(replace('“氮素同步士”＋1只以上协调以外的怪兽\r\n①：只要此卡存在于怪兽区域，自己在自己回合发动魔法卡的情况下，仅在该回合的伤害计算时1次，此卡的攻击力上升1000。②：以此卡的攻击破坏对手怪兽的伤害计算后，以对手场上的1只表侧守备表示的怪兽为对象可以发动。将对手的该表侧守备表示怪兽改成攻击表示，此卡可继续攻击该怪兽仅1次。','\r',char(13)),'\n',char(10)),'继续攻击','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18027138,'河马嘉年华','①：在我方场上特殊召唤３只“河马衍生物”（兽族・地・星１・攻／守０）。此衍生物不可解放。只要“河马衍生物”在怪兽区，我方就不可从额外卡组特殊召唤怪兽。发动此卡后，直到回合结束，对手不可选择“河马衍生物”以外的怪兽作为攻击目标。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18027139,'河马衍生物','由“河马嘉年华”等的效果特殊召唤而来。此衍生物不可用作祭品。只要“河马衍生物”在怪兽区，特殊召唤“河马衍生物”的玩家就不能从额外牌组特殊召唤怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18027140,'河马衍生物','由“河马嘉年华”等的效果特殊召唤而来。此衍生物不可用作祭品。只要“河马衍生物”在怪兽区，特殊召唤“河马衍生物”的玩家就不能从额外牌组特殊召唤怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18027141,'河马衍生物','由“河马嘉年华”等的效果特殊召唤而来。此衍生物不可用作祭品。只要“河马衍生物”在怪兽区，特殊召唤“河马衍生物”的玩家就不能从额外牌组特殊召唤怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18036057,'天空骑士珀耳修斯',replace(replace('①：此卡攻击守备表示的怪兽的场合，若其攻击力超过守备力，给予对手生命相当于该差值的战斗伤害。\r\n②：此卡给予对手战斗伤害的场合发动。我方从牌组抽取１张卡牌。','\r',char(13)),'\n',char(10)),'抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18046862,'叹息石版',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：装备怪兽不可攻击，效果无效化，且不可解放。\r\n②：１回合１次，装备怪兽存在于自己场上的情况下可以发动。从牌组将“叹息石版”以外的１张“石版”卡加入手牌。\r\n③：因装备怪兽被破坏导致此卡被送至墓地的情况下可以发动。给予对手５００伤害。','\r',char(13)),'\n',char(10)),'','检索','给与伤害','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18060565,'龙骑兵团－首席百夫长','①：此卡召唤・特殊召唤时，以自己场上1只鸟兽族的“龙骑兵团”怪兽为对象可以发动。从牌组将1只龙族・等级3以下的“龙骑兵团”怪兽视为装备魔法卡，装备于对象怪兽。','装备','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18063928,'铁皮金鱼','①：此卡召唤成功时可以发动。从手牌将１只等级４怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18078153,'活死人军团',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡存在于手牌・墓地，且自己场上存在“活死人的呼唤”的情况下可以发动。将此卡特殊召唤。\r\n②：此卡被送至墓地的情况下，以自己墓地的1张“活死人的呼唤”为对象可以发动。将该卡放置在自己场上。','\r',char(13)),'\n',char(10)),'特殊召唤','放置','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18094166,'幻影－英雄 法利斯',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从手牌将1只其他的“－英雄”怪兽舍弃可以发动。从手牌将此卡特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从牌组将“幻影－英雄 法利斯”以外的1只“幻影－英雄”怪兽视为永续陷阱卡，以表侧表示放在自己的魔法与陷阱区域。此效果发动后，直至回合结束时为止自己从额外牌组仅可特殊召唤“－英雄”怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18096222,'二重推进器','发动后此卡变为攻击力上升７００点的装备卡，装备至我方场上１只二重怪兽上。当成为装备卡的此卡被破坏送入墓地时，选择１只以表侧表示存在于场上的二重怪兽，令其变为已再次召唤的状态。','变成再度召唤状态','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18106132,'人偶怪兽 熊仔',replace(replace('我们就算受了重创坏掉也没有关系。\r\n因为德梅特爷爷会把我们修好！','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18108166,'幻壳龙','从别的次元突然飞来的谜一般的生命体。同时具备了高攻击力和奇袭能力。其攻击会使对象物的神经麻痹，并引起强烈的幻觉症状。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18114794,'召唤断路器','①：回合玩家在主要阶段1，进行该回合的第3次召唤・反转召唤・特殊召唤的情况下发动。直接变为该回合的结束阶段。','结束回合','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18138630,'魔玩具厄瓶','①：此卡只要存在于场上・墓地，卡名视为“玩具罐”。②：１回合１次，舍弃１张手牌可以发动。自己从牌组抽１张，双方确认。抽到的是“锋利小鬼”怪兽的情况下，可挑选场上的１张卡破坏。不是的情况下，挑选１张手牌放回牌组最上面或最下面。③：此卡被送至墓地的情况下，以对手场上的１只表侧表示怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止改成一半。','','','是否选场上1张卡破坏？','牌组最上面','牌组最下面','','','','','','','','','','','');
INSERT INTO texts VALUES(18144506,'神鹰羽毛扫','①：将对手场上的魔法・陷阱卡全部破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18144507,'神鹰羽毛扫','①：将对手场上的魔法・陷阱卡全部破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18144508,'神鹰羽毛扫','①：将对手场上的魔法・陷阱卡全部破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18158393,'玛那桃圆乡・净心','此卡名的①②效果１回合仅可各使用１次。①：自己场上存在同步怪兽，怪兽的效果・魔法・陷阱卡发动时可以发动。将该发动无效。自己场上或墓地存在“维萨思・史塔弗罗斯特”或攻击力１５００／守备力２１００的怪兽的情况下，进而可将该被无效的卡破坏。②：将墓地的此卡除外，以自己墓地的最多３只“玛那桃圆乡”怪兽为对象可以发动。将该怪兽放回牌组。','是否把那张无效的卡破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18158397,'自然灾害','每次对手控制的卡片被名字带有“云魔物”的怪兽的效果破坏并被送至墓地时，给予对手LP５００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18161786,'黑暗地带','场上的暗属性怪兽的攻击力上升５００点，守备力下降４００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18165869,'冥铭途・暗黑剑',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡召唤・特殊召唤的情况下，从手牌将１张“冥铭途”卡舍弃，以对手场上的１张魔法・陷阱卡为对象可以发动。将该卡破坏。\r\n②：在自己的主要阶段可以发动。将自己场上的１只“冥铭途”怪兽破坏，从牌组将１只等级３以下的“冥铭途”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18168997,'堕天使 内加尔',replace(replace('自己1回合仅可特殊召唤1次“堕天使 内加尔”，其②效果1回合仅可使用1次。\r\n①：自己的天使族怪兽攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。\r\n②：在自己・对手回合中，支付1000LP，以自己墓地的1张“堕天使”魔法・陷阱卡为对象可以发动。适用该魔法・陷阱卡发动时的效果。然后，将该卡放回牌组。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18175965,'守护者・迪斯赛斯',replace(replace('此卡不可通常召唤，只有通过此卡的效果才可特殊召唤此卡。\r\n①：“守护者・艾尔托斯”因战斗・效果而被破坏并送入我方墓地的场合可发动此卡。从手牌特殊召唤此卡。\r\n②：成功特殊召唤此卡时可发动此卡。将牌组中１张“死神的大镰－迪斯赛斯”装备至此卡上。\r\n③：只要此卡存在于怪兽区域，我方不可进行召唤・特殊召唤。\r\n④：此卡从场上被送入墓地的场合发动此卡。将１张手牌送入墓地，从墓地特殊召唤此卡。','\r',char(13)),'\n',char(10)),'特殊召唤','装备','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18176525,'巳剑之尊 佐士',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下，或此卡被解放的情况下可以发动。从牌组将1张“巳剑”魔法・陷阱卡加入手牌。\r\n②：自己场上的其他爬虫类族怪兽将被战斗・效果破坏的情况下，作为代替可将此卡解放。','\r',char(13)),'\n',char(10)),'检索','代替破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18180762,'泥浆潜居者','脚下开始溶化变得粘稠时就是这家伙现身的前兆。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18189187,'梦魔镜之使徒－涅伊洛','此卡名的①②效果１回合仅可各使用１次。①：场上有“梦魔镜”怪兽存在的情况下可以发动。从手牌将此卡特殊召唤。然后可将此卡改为暗属性。②：此卡以“梦魔镜”怪兽的效果特殊召唤成功的情况下发动。场上有“圣光之梦魔镜”存在的情况下，可挑选对手场上的１张魔法・陷阱卡放回持有者的手牌。场上有“暗黑之梦魔镜”存在的情况下，自己从牌组抽１张，然后将１张手牌放回牌组。','','是否将此卡变成暗属性？','是否选对手魔法·陷阱卡回到手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18190572,'微光线','场上表侧表示的１只怪兽的守备力，直到结束阶段结束时变为０。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18205590,'架天桥的卫星骑士',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：以自己场上的1只“星骑士”怪兽为对象可以发动。从牌组将1只卡名与该怪兽不同的“星骑士”怪兽特殊召唤，将对象怪兽放回牌组。只要以此效果特殊召唤的怪兽以表侧表示存在于场上，自己仅可特殊召唤“星骑士”怪兽。','\r',char(13)),'\n',char(10)),'「架天桥的卫星骑士」效果适用中','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18210764,'灵摆姆啾',replace(replace('←0 【灵摆】 0→\r\n①：在发动了此卡的回合的自己的主要阶段仅１次，以“灵摆姆啾”以外的、自己墓地・除外状态的１只灵摆怪兽为对象可以发动。将该怪兽以表侧加入自己的额外牌组。\r\n【怪兽效果】\r\n①：此卡召唤・特殊召唤的情况下可以发动。从自己的额外牌组（表侧）将“灵摆姆啾”以外的１只等级１灵摆怪兽特殊召唤。以此效果特殊召唤的怪兽从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'加入额外牌组','请选择要加入自己的额外牌组的卡','额外牌组灵摆怪兽特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18214905,'元素军刀 莱帕维拉',replace(replace('①：１回合１次，魔法、陷阱卡发动时，可从手牌将１只“元素军刀”怪兽送入墓地并发动。使该发动无效并破坏。\r\n②：此卡存在于墓地的场合，１回合１次，可宣言１个属性并发动。直至回合结束时，墓地的此卡变成宣言之属性。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18235309,'连击的帝王','①：1回合1次，在对手的主要阶段及战斗阶段可以发动。进行1只怪兽的上级召唤。','上级召唤','是否发动效果？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18235577,'寂寂虫','可将此卡从手牌送入墓地并发动。选择场上的１只怪兽，直至回合结束时，该等级下降１。','等级下降','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18236002,'调皮宝贝・火灯娃',replace(replace('此卡名的效果１回合仅可使用１次。\r\n①：此卡仅在作为“调皮宝贝”怪兽的融合素材或连接素材被送至墓地的情况下可以发动。给予对手５００点伤害。然后，从手牌・牌组中以守备表示特殊召唤１只除“调皮宝贝・火灯娃”以外的“调皮宝贝”怪兽。','\r',char(13)),'\n',char(10)),'是否特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18239909,'爆龙剑士 点火行者 日珥',replace(replace('协调＋协调以外的灵摆怪兽１只以上\r\n①：１回合１次，以场上的１只灵摆怪兽或灵摆区域的１张卡为对象可以发动。将该卡破坏，将场上的１张卡放回牌组。\r\n②：１回合１次，在自己的主要阶段可以发动。从牌组将１只“龙剑士”怪兽以守备表示特殊召唤。以此效果特殊召唤的怪兽不可作为同步素材。','\r',char(13)),'\n',char(10)),'返回牌组','特殊召唤','不可作为同步素材','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18246479,'牛魔人','住在森林里的牛之魔人，用突起的角进行突袭。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18249921,'电脑堺门－玄武','此卡名的卡１回合仅可发动１张，此卡名的①②效果１回合仅可各使用１次。①：自己场上有其他“电脑堺门”卡存在的情况下，在自己・对手的战斗阶段，以场上１只表侧表示怪兽为对象可以发动。变更该怪兽的表示形式。②：在自己的主要阶段将墓地的此卡除外，以自己墓地的１只“电脑堺”怪兽为对象可以发动。将该怪兽的效果无效并特殊召唤。然后挑选１张手牌送至墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18252559,'内置式爆弹',replace(replace('①：给予对手对手场上卡片数量×３００的伤害。\r\n②：场上的此卡被对手破坏并被送至墓地的情况下发动。给予对手１０００点伤害。','\r',char(13)),'\n',char(10)),'基本分伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18271561,'地狱暴破','自己场上的表侧表示怪兽因战斗或卡的效果被破坏并送往墓地时可以发动。破坏场上１只攻击力最低的表侧表示怪兽，双方都受到该攻击力一半的伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18282103,'魔轰神兽犍那萨','①：此卡从手牌被舍弃至墓地的情况下发动。将此卡特殊召唤。以此效果特殊召唤的此卡攻击力上升200，从场上离开的情况下，将其除外。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18294799,'无限龙 史瓦西',replace(replace('此卡名的效果１回合仅可使用１次，发动此效果的回合中，自己从额外牌组仅可特殊召唤龙族超量怪兽。\r\n①：自己场上不存在怪兽的情况下，或对手场上存在攻击力２０００以上的怪兽的情况下可以发动。从手牌将此卡特殊召唤，从牌组将“无限龙 史瓦西”以外的１只光・暗属性的龙族・等级８怪兽以守备表示特殊召唤。以此效果从牌组特殊召唤的怪兽的效果无效化。','\r',char(13)),'\n',char(10)),'特殊召唤自身并特殊召唤牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18300894,'丝绸炸弹蛾',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡存在于手牌，且自己墓地存在2只以上的风属性怪兽的情况下可以发动。将此卡特殊召唤，从自己墓地将1只风属性怪兽放回牌组。\r\n②：此卡召唤・特殊召唤的情况下可以发动。将对手牌组最上面的卡给双方确认，根据其种类适用以下效果。\r\n●怪兽：将所确认的卡视为永续魔法卡以表侧表示放在对手的魔法与陷阱区域。\r\n●魔法・陷阱：将所确认的卡除外。','\r',char(13)),'\n',char(10)),'特殊召唤','确认牌组','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18302224,'新宇侠之逆转','我方场上表侧表示的冠有“新宇侠”之名的融合怪兽被破坏时可发动。从牌组以攻击表示特殊召唤１只“元素－英雄 新宇侠”。直至回合结束时，以此效果特殊召唤的怪兽攻击力上升１０００点，并在此回合的结束阶段时被破坏。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18313046,'浮－朋.克.鲤跃',replace(replace('“朋.克.”怪兽×2\r\n此卡名的①②效果1回合仅可各使用1次。①：解放融合召唤的此卡可以发动。从手牌・牌组将最多2只等级8以外的“朋.克.”怪兽以守备表示特殊召唤（同名卡最多1张）。②：以此卡作为同步素材同步召唤成功的情况下，以自己场上的1只“朋.克.”怪兽为对象可以发动。此回合，该怪兽在1次战斗阶段中可攻击2次。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18318842,'深渊士兵','１回合１次，可从手牌舍弃１只水属性怪兽至墓地，选择场上的１张卡牌并发动。被选择的卡牌返回至持有者的手牌。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18319762,'冰结界的照魔师',replace(replace('此卡名的②③效果１回合仅可各使用１次。\r\n①：只要自己场上存在其他“冰结界”怪兽，对手不可上级召唤。\r\n②：舍弃１张手牌可以发动。从牌组将１只“冰结界”协调特殊召唤。此效果发动后，直至回合结束时为止自己仅可特殊召唤水属性怪兽。\r\n③：自己为发动“冰结界”怪兽的效果将手牌送至墓地的情况下，或将其舍弃的情况下，作为该１张卡的代替，可将墓地的此卡除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18321034,'百臂无形手 马基卜揶尔',replace(replace('此卡名的①③效果1回合仅可各使用1次。\r\n①：向对手出示手牌的此卡可以发动。将包含手牌的此卡在内的、自己手牌・场上的怪兽作为融合素材，将1只“百臂无形”融合怪兽融合召唤。\r\n②：此卡与怪兽进行战斗的情况下，该2只不会因该战斗被破坏。\r\n③：此卡存在于墓地的状态下，幻想魔族的融合怪兽被送至自己墓地的情况下可以发动。将此卡加入手牌。','\r',char(13)),'\n',char(10)),'融合召唤','回到手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18322364,'巨鲸','此卡上级召唤成功时，可解放此卡并发动。从牌组特殊召唤３只等级３的水属性怪兽。以此效果特殊召唤的怪兽的效果被无效化。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18325492,'旋翼机人','此卡１回合仅限１次不会因战斗而被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18326736,'守星骑士 托勒密',replace(replace('等级4怪兽×2只以上\r\n①：依以下数量去除此卡的超量素材，可以发动相应效果。\r\n●3个：在自己・对手的回合可以发动（同一连锁上最多1次）。从额外牌组将除“编号”怪兽以外的、1只阶级比此卡高1的超量怪兽重叠在自己场上的此卡上面，视为超量召唤特殊召唤。\r\n●7个：在自己的主要阶段可以发动。跳过下个对手回合。\r\n②：在自己・对手的结束阶段可以发动。从额外牌组将1张“辉星骑士”卡作为此卡的超量素材。','\r',char(13)),'\n',char(10)),'特殊召唤','下次对手回合跳过','添加超量素材','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18372968,'剃刀蜥蜴','只要我方场上存在有除此卡以外的爬虫类族怪兽，此卡攻击里侧守备表示怪兽的伤害步骤开始时，破坏该里侧守备表示怪兽。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18377261,'剑之御巫 波礼',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：此卡未装备装备卡的情况下，因此卡的战斗对自己造成的战斗伤害变为0，有装备的情况下，此卡不会因战斗被破坏，因此卡的战斗对自己造成的战斗伤害由对手代为承受。\r\n②：此卡被装备上装备卡的情况下可以发动。从牌组将1张“御巫”装备魔法卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18378582,'大天使 杰拉特','此卡不可通常召唤。只有在场上有“天空的圣域”存在的场合，解放自己场上１只表侧表示的“杰拉的战士”才可特殊召唤此卡。将手牌中的１只光属性怪兽弃置至墓地，破坏对手场上的所有怪兽。此效果仅在我方场上有“天空的圣域”存在时才适用。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18378992,'Sin 选择者',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从自己墓地将2张“Sin”卡除外可以发动。从牌组将卡名与所除外的卡不同的、“Sin 选择者”以外的2张“Sin”卡加入手牌（同名卡最多1张）。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18386170,'彼岸巡礼者 但丁',replace(replace('卡名不同的“彼岸”怪兽×3\r\n此卡只可以融合召唤方式特殊召唤。①：此卡不会成为对手效果的对象。②：1回合1次，将手牌的1张“彼岸”卡送至墓地可以发动。自己从牌组抽1张。此效果在对手回合中也可以发动。③：场上的此卡因对手的效果被送至墓地的情况下，或因战斗被破坏并被送至墓地的情况下可以发动。随机挑选1张对手的手牌送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18407024,'电力金鱼','此卡因直接攻击给予对手生命值战斗伤害的情况下发动。对手挑选１张手牌舍弃。','丢弃手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18426196,'圣骑士 贞德','①：此卡攻击的伤害步骤期间，此卡的攻击力下降300。②：此卡因对手被破坏并被送至墓地的情况下，将1张手牌送至墓地，以自己墓地的1只等级4以下的战士族怪兽为对象可以发动。将该战士族怪兽加入手牌。','加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18430390,'飞翼犀牛','陷阱卡发动时可发动。将场上表侧表示的此卡返回至持有者手牌。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18438874,'邪恶之心',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：自己场上存在恶魔族怪兽的情况下，根据对手墓地的怪兽数量，可从以下效果中选择1个发动。\r\n●1只以上：自己抽1张。\r\n●4只以上：从牌组将1只“－英雄”怪兽或1张“黑暗结合”加入手牌。\r\n●10只以上：从牌组将1张“融合”魔法卡或“结合”魔法卡加入手牌。','\r',char(13)),'\n',char(10)),'抽1张卡','检索「－英雄」怪兽或「黑暗结合」','检索「融合」魔法卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18444733,'雷龙放电','①：只要此卡存在于魔法与陷阱区域，自己的雷族怪兽的效果发动不会被无效化。②：1回合1次，“雷龙”怪兽被召唤・特殊召唤至自己场上的情况下，以场上1张魔法・陷阱卡为对象可以发动。从牌组将1只雷族怪兽除外，将对象卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18444902,'来一战骑士','自己的魔法・陷阱卡的发动因对手卡片的效果而变成无效的情况下，从手牌将此卡送至墓地可以发动。给予对手LP１５００点伤害。','LP伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18446701,'我我我护盾',replace(replace('①：以自己场上的1只魔法师族怪兽为对象可以发动此卡。将此卡视为拥有以下效果的装备卡，装备于该自己的魔法师族怪兽。\r\n●装备怪兽1回合最多2次不会因战斗・效果被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18458255,'妮梦雷莉娅的寝姬楼','此卡名的①效果１回合仅可使用１次。①：从额外牌组将２张里侧表示的卡以里侧表示除外可以发动。从牌组将２只卡名不同的兽族・等级１０怪兽加入手牌。发动此效果的回合中，自己从额外牌组仅可特殊召唤灵摆怪兽。②：自己的额外牌组存在表侧表示的“眠梦中的妮梦雷莉娅”，且自己场上的“妮梦雷莉娅”怪兽将被战斗或对手的效果破坏的情况下，作为代替可将自己额外牌组的１张里侧表示的卡以里侧表示除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18474999,'魔神仪－书本石','此卡名的①②效果1回合1次，仅可使用其中1个。①：将手牌的1张仪式魔法卡出示给对手可以发动。将“魔神仪-书本石”以外的1只牌组的“魔神仪”怪兽和手牌的此卡特殊召唤。②：此卡从牌组特殊召唤成功的情况下，以自己墓地的1张仪式魔法卡为对象可以发动。将该卡加入手牌。③：只要此卡存在于怪兽区域，自己不可从额外牌组特殊召唤怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18478530,'洛戈之焰',replace(replace('①：只要此卡存在于魔法与陷阱区域，且我方场上存在有“女战神”怪兽，攻击力是２０００或以下的对手怪兽不可进行攻击。\r\n②：此卡因对手效果被破坏的场合可发动。从手牌、牌组特殊召唤１只等级５或以上的“女战神”怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18482473,'H・E・R・O 闪光！',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：可从以下效果中选择1个发动。\r\n●此回合中，自己的“元素－英雄”怪兽攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。\r\n●以自己场上的“元素－英雄”怪兽的数量为上限，以对手场上的卡为对象可以发动。将该卡破坏。\r\n●从自己墓地挑选1只“元素－英雄”怪兽，加入手牌或特殊召唤。\r\n●此回合中，“元素－英雄”怪兽可直接攻击。','\r',char(13)),'\n',char(10)),'发动','贯通伤害','卡片破坏','墓地回收','直接攻击','','','','','','','','','','','');
INSERT INTO texts VALUES(18482591,'冰结界的破术师','①：只要自己场上存在其他“冰结界”怪兽，双方不放置魔法卡就不可发动，且站在放置的玩家的角度，直到自己下个回合到来为止不可发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18486927,'古代机械齿轮小工具','①：此卡召唤・特殊召唤成功的情况下，宣言卡的种类（怪兽・魔法・陷阱）可以发动。此回合，自己的怪兽攻击的情况下，对手直至伤害步骤结束时为止，不可发动所宣言的种类的卡。②：１回合１次，宣言１个“小工具”怪兽的卡名可以发动。直至结束阶段为止，此卡视为所宣言卡的同名卡。','宣言怪兽卡名','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18489208,'被诅咒的无花果','此卡因战斗被破坏并送入墓地的场合，选择２张盖牌于场上的魔法、陷阱卡并发动。只要此卡存在于墓地，被盖牌的该卡不可发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18491580,'真红眼亚黑龙',replace(replace('此卡不可通常召唤。\r\n从自己的手牌・场上，解放１只“真红眼”怪兽的情况下可以特殊召唤。\r\n“真红眼亚黑龙”以此方法的特殊召唤１回合仅可进行１次。\r\n①：此卡因战斗或对手的效果被破坏的情况下，以自己墓地“真红眼亚黑龙”以外的１只等级７以下的“真红眼”怪兽为对象可以发动。将该怪兽特殊召唤。以此效果特殊召唤的怪兽是“真红眼黑龙”的情况下，其原本的攻击力变为两倍。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18494511,'冰翡帝 爱姬尔・澜','此卡名的①效果１回合仅可使用１次。①：从手牌将此卡以外的１张“冰翡”卡或１只水属性怪兽舍弃可以发动。从手牌将此卡特殊召唤。然后，可将１只“冰翡衍生物”（水族・水・星３・攻／守０）特殊召唤至自己场上。只要以此效果特殊召唤的衍生物存在，自己从额外牌组仅可特殊召唤水属性怪兽。②：只要此卡装备有装备卡，卡名视为“冰翡底 伊尼恩摇篮”。','','是否特殊召唤衍生物？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18494512,'冰翡衍生物','由「冰翡帝 爱姬尔・澜」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18511384,'融合回收','将我方墓地的１张“融合”魔法卡和１只用于融合的融合素材怪兽加入到手牌中。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18511599,'进化帝・鬼翼龙',replace(replace('恐龙族等级６怪兽×２\r\n①：拥有超量素材的此卡不会因效果被破坏。②：对手特殊召唤怪兽成功时，去除此卡的１个超量素材可以发动。将该怪兽破坏。','\r',char(13)),'\n',char(10)),'怪兽破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18514525,'调皮宝贝・火箭',replace(replace('“调皮宝贝”怪兽×２\r\n具此卡名的①②效果１回合各只能使用１次。\r\n①：此卡仅在融合召唤成功时可发动。此回合中，此卡攻击力降低１０００点，可直接攻击。\r\n②：解放此卡后，以我方墓地中除融合怪兽外的２只“调皮宝贝”怪兽为目标可发动（同名卡最多１张）。特殊召唤该怪兽。以此效果特殊召唤的怪兽在本回合无法攻击。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18517177,'核心爆裂','我方场上存在有冠有“核成”之名怪兽的我方准备阶段时，可发动仅１次。对手场上的怪兽数量多于我方场上的怪兽数量的场合，可挑选对手场上的卡牌破坏，使得其数量与我方场上怪兽的数量相同。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18548966,'英豪挑战者 晨星',replace(replace('此卡名的①②③效果１回合仅可各使用１次。\r\n①：自己场上有２只以上的战士族怪兽存在的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：此卡召唤・特殊召唤成功的情况下可以发动。从牌组将１张“英豪”魔法・陷阱卡加入手牌。\r\n③：此卡存在于墓地，自己的LP为５００以下的情况下可以发动。将此卡的效果无效并特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18551923,'咒眼之死徒 梅杜莎',replace(replace('此卡牌名的②效果１回合只可使用１次。\r\n①：此卡召唤成功时，可以我方墓地１张除“咒眼之死徒 梅杜莎”以外的“咒眼”卡牌为对象发动。将该卡加入手牌。\r\n②：此卡装备有“塞勒涅的咒眼”的场合，可以对手墓地的１只怪兽为对象发动。将该怪兽除外。此效果在对手回合也可发动。\r\n③：发动此卡②效果的场合，在下一个准备阶段发动。挑选我方墓地的１张卡牌并除外。','\r',char(13)),'\n',char(10)),'加入手牌','对手墓地1只怪兽除外','自己墓地1张卡除外','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18558867,'岩吼战士・巴西雷奥斯',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡存在于手牌・墓地，自己的战士族・地属性怪兽因战斗被破坏时可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡离开场上的情况下，将其除外。\r\n②：在自己的战士族・地属性怪兽进行战斗的自己・对手的战斗阶段可以发动。自己场上所有“岩吼战士”怪兽的攻击力直至对手回合结束时为止上升２００。此回合，此卡可直接攻击。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18563744,'沉默之剑',replace(replace('①：可以我方场上的１只“沉默剑士”怪兽为对象发动。该我方怪兽的攻击力、守备力上升１５００，且直至回合结束时不受对手效果影响。此卡的发动和效果不会被无效化。\r\n②：可将墓地的此卡除外并发动。从牌组将１只“沉默剑士”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'攻击力·守备力上升','牌组检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18585765,'伏特测士','此卡名的效果1回合仅可使用1次。①：此卡被特殊召唤至连接怪兽连接端的情况下发动。将与此卡处于连接状态的连接怪兽全部破坏。进而重复执行“将被破坏的连接怪兽其连接端的怪兽也全部破坏”的处理。（此卡不会因此效果被破坏）','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18590133,'格布林王','我方场上有除此卡以外的恶魔族怪兽存在的场合，此卡不可被攻击。此卡的攻击力和守备力为场上除此卡以外的恶魔族怪兽的数量×１０００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18591904,'最终战争','弃置５张手牌来发动此卡。破坏场上的所有卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18595008,'捕食植物 铁炮瓜蜥蜴',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：此卡存在于手牌，且自己场上存在“捕食植物”怪兽或“凶饿猛毒”怪兽的情况下可以发动。将此卡特殊召唤。然后，可从牌组将1张“融合”加入手牌。\r\n②：以场上的1只表侧表示怪兽为对象可以发动。将该怪兽的属性直至回合结束时为止改成暗属性。\r\n③：此卡从墓地特殊召唤的情况下可以发动。自己抽1张。','\r',char(13)),'\n',char(10)),'特殊召唤','改变属性','抽牌','是否加入手牌？','','','','','','','','','','','','');
INSERT INTO texts VALUES(18597560,'人工脑革命','此卡名的卡1回合仅可发动1张。①：解放自己场上的1只“电子龙”可以发动。将1只以“电子龙”怪兽作为融合素材的融合怪兽从额外牌组特殊召唤。以此效果特殊召唤的怪兽不可直接攻击，在下一个回合的结束阶段将被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18605135,'龙卷海流壁',replace(replace('场上有“海”存在的场合可发动此卡。\r\n①：只要场上有“海”存在，我方受到的战斗伤害变为０。\r\n②：场上没有“海”存在的场合，此卡被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18616294,'灰层',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：解放此卡，向对手出示手牌的1只机械族怪兽可以发动。从牌组将1只属性与所出示怪兽不同的机械族怪兽加入手牌。以此效果将攻击力1200以下的怪兽加入了手牌的情况下，进而可从手牌将1只机械族怪兽特殊召唤。\r\n②：此卡存在于墓地的状态下，自己的怪兽因效果被破坏的情况下，将此卡除外可以发动。将场上的1张卡破坏。','\r',char(13)),'\n',char(10)),'检索效果','破坏效果','是否特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18621798,'炎王兽 伽内什',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡存在于怪兽区域，且怪兽的效果发动时可以发动。将该发动无效，将自己的手牌・场上（表侧表示）此卡以外的１只炎属性怪兽破坏。\r\n②：此卡被破坏并被送至墓地的情况下，以“炎王兽 伽内什”以外的、自己墓地的１只兽族・兽战士族・鸟兽族的炎属性怪兽为对象可以发动。将该怪兽特殊召唤。该怪兽的效果无效化，将在结束阶段被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18631392,'玛特','此卡不可通常召唤。仅可在将自己场上表侧表示的１只龙族・光属性怪兽和１只天使族・光属性怪兽送至墓地的情况下特殊召唤。１回合１次，宣言３个卡名可以发动。从自己牌组上面翻开３张卡，将所宣言的卡加入手牌。将其他翻开的卡全部送至墓地。此卡的攻击力・守备力变为相当于以此效果加入手牌的卡数量×１０００点的数值。','宣言卡名','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18634367,'红莲屏障',replace(replace('此卡的控制者在每个自己的结束阶段支付１０００LP。无法支付１０００LP的情况下，破坏此卡。\r\n①：只要此卡存在于魔法与陷阱区域，对手怪兽不可攻击宣言。\r\n②：以自己墓地的１只等级１协调为对象可以发动。将此卡破坏，将该怪兽特殊召唤。此效果在场上存在“暗红恶魔龙”的情况下才能发动和处理。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18654201,'羊头狮身斯芬克斯','只要此卡以表侧表示存在于我方场上，场上的怪兽返回至持有者手牌时，该怪兽的持有者挑选１张手牌并送入墓地。','手牌送墓','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18658572,'杂耍艺人格布林','每次我方的结束阶段，将我方牌组最下方的卡牌给双方确认，将该卡放置至我方牌组的最上方或以里侧表示从游戏中除外。','确认牌组','是否要里侧表示从游戏中除外？','里侧表示从游戏中除外','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18666161,'惨绝戏子・镜框舞台',replace(replace('“惨绝戏”怪兽＋光属性怪兽＋暗属性怪兽\r\n此卡名的①②效果１回合仅可各使用１次。①：在自己・对手的主要阶段，以对手墓地的１只融合・同步・超量・连接怪兽为对象可以发动。将该怪兽除外，或特殊召唤至自己场上。②：此卡战斗破坏对手怪兽时可以发动。依该怪兽原本攻击力和原本守备力中较高一方的数值来给予对手伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18678554,'时潜怪盗・飞返','此卡名的①②效果1回合1次，仅可使用其中1个。①：以自己场上的1只“时潜怪盗”超量怪兽为对象可以发动。从手牌・牌组挑选1张“时潜怪盗”卡，重叠在对象怪兽下方作为超量素材。②：将墓地的此卡除外，以自己场上的1只“时潜怪盗”超量怪兽为对象可以发动。从对手墓地挑选1张卡，重叠在对象怪兽下方作为超量素材。','自己的卡作为超量素材','对手的卡作为超量素材','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18698739,'垃圾食人魔','可将此卡从手牌送入墓地并发动。从牌组将１只“垃圾领主”加入手牌。“垃圾食人魔”的效果１回合只可使用１次。','牌组检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18710707,'愤怒的海王','伟大的海之王，会呼唤永无止息的巨大海啸将敌人吞没。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18711696,'爆裂音速战士',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：自己场上存在“废品战士”“爆裂模式”或记载有其中的任一卡名的卡的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从牌组将1只“同步士”怪兽或1张“爆裂模式”加入手牌。\r\n③：此卡作为同步素材被送至墓地的情况下可以发动。此回合中，自己场上的怪兽的攻击力上升500。','\r',char(13)),'\n',char(10)),'特殊召唤','检索','攻击力上升','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18712704,'无限狱之力','我方手牌为０张，且冠有“无限狱”之名的怪兽被选择为攻击对象时，可选择１只攻击怪兽与１只我方墓地冠有“无限狱”之名的怪兽并发动。破坏被选择攻击怪兽，并特殊召唤被选择墓地的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18716735,'稀炼装勇士・铋巫',replace(replace('←8 【灵摆】 8→\r\n①：１回合１次，可以我方场上１张除此卡以外的表侧表示卡牌为对象发动。破坏该卡，并从牌组挑选１张“炼装勇士”魔法、陷阱卡盖牌至我方场上。\r\n【怪兽效果】\r\n此卡牌名的怪兽效果１回合只可使用１次。\n①：场上的此卡因战斗、效果被破坏的场合可发动。在此回合的结束阶段，从牌组将１只“炼装勇士”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18720257,'天气预报',replace(replace('此卡名的卡１回合仅可发动１张，此卡名的②③效果１回合仅可各使用１次。\r\n①：作为此卡发动时的效果处理，可从牌组挑选１张“天气”魔法・陷阱卡，以表侧表示放在自己的魔法与陷阱区域。\r\n②：自己连接召唤“天气”连接怪兽的情况下，可将自己的魔法与陷阱区域表侧表示的“天气”卡当成“天气”怪兽作为连接素材。\r\n③：在自己的主要阶段可以发动。从手牌召唤１只“天气”怪兽。','\r',char(13)),'\n',char(10)),'','是否选「天气」魔法·陷阱卡放置？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18724123,'无限狱弓箭手','我方手牌是０张的场合，此卡可直接攻击对手玩家。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18738846,'牵星之雷后',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次，且②③效果1回合仅可各使用1次。\r\n①：此卡可通过将自己场上的最多2只怪兽放回手牌，来从手牌特殊召唤。\r\n②：此卡特殊召唤的情况下，向对手出示任意数量的手牌的怪兽（相同等级最多1只），依其数量以对手场上的表侧表示卡为对象可以发动。将该卡的效果无效。\r\n③：场上的此卡因效果被破坏并被送至墓地的情况下可以发动。将此卡加入手牌。','\r',char(13)),'\n',char(10)),'','无效','回到手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18739764,'破坏性药剂','可从我方场上选择１只怪兽并发动。破坏被选择怪兽，其为表侧表示的场合，我方回复相当于被破坏怪兽的攻击力数值的LP。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18743376,'玄化暴君龙',replace(replace('①：以“幻化”怪兽效果特殊召唤的此卡不受陷阱卡效果的影响，此卡攻击了怪兽的场合，仅１次可再连续攻击。\r\n②：此卡被除外的场合，可在下一个回合的准备阶段将被除外的此卡返回至牌组并发动。从手牌特殊召唤１只“玄化”怪兽。以此效果特殊召唤的怪兽在下一个回合的结束阶段被除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18752707,'魔力星幻像','①：我方场上怪兽数量少于对手场上怪兽数量的场合可发动此卡。令我方及对手场上的怪兽的攻击力上升该怪兽控制者场上怪兽的合计等级×１００，直到回合结束时。','攻守变换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18752938,'伪装的种子','从手牌特殊召唤１只等级２或以下的植物族怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18756904,'马骨的报酬','①：将效果怪兽以外的自己场上的1只表侧表示怪兽送至墓地可以发动。自己从牌组抽2张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18760514,'疯狂谋杀者','此卡名的②效果１回合仅可使用１次。①：此卡只要存在于场上・墓地，卡名视为“僵尸带菌者”。②：此卡存在于墓地的情况下，以自己场上的１只等级６以上的怪兽为对象可以发动。该怪兽的等级下降２，将此卡特殊召唤。只要以此效果特殊召唤的此卡以表侧表示存在于怪兽区域，自己仅可特殊召唤不死族怪兽。','请选择要下降等级的怪兽','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18789533,'点画替罪者',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个，决斗中仅可各使用１次。\r\n①：此卡被送至墓地的情况下可以发动。将此卡特殊召唤。\r\n②：此卡被除外的情况下可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18795635,'第55次GMX应用实验',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从自己牌组上面翻开卡，直至翻到“GMX”怪兽及恐龙族怪兽各至少1只为止，自己失去所翻开的数量×400的LP。可将所翻开的卡中的怪兽作为融合素材，将1只“GMX”融合怪兽融合召唤。将剩余的所翻开的卡放回牌组。','\r',char(13)),'\n',char(10)),'','是否融合召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18803791,'黑龙降临',replace(replace('用于召唤“黑龙圣骑士”。\r\n①：从我方的手牌・场上解放合计等级达到４以上的怪兽，从手牌仪式召唤“黑龙圣骑士”。\r\n②：可在我方主要阶段将墓地中的此卡除外来发动此卡。将牌组中１张“真红眼”魔法・陷阱卡加入到手牌中。此效果不可在此卡被送入墓地的回合中发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18807108,'六芒星之咒缚','选择对手场上的１只怪兽可以发动。被选择的怪兽不可攻击，也不可改变表示形式。选择的怪兽被破坏时，将此卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18807109,'六芒星之咒缚','选择对手场上的１只怪兽可以发动。被选择的怪兽不可攻击，也不可改变表示形式。选择的怪兽被破坏时，将此卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18809562,'魔导契约之门','①：从我方手牌挑选１张魔法卡加入对手手牌。之后，从我方牌组将１只等级７、８的暗属性怪兽加入我方手牌。','请选择要加入对手手牌的卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18816758,'侵略的波动','可将我方场上上级召唤的１只冠有“侵邪蚀”之名的怪兽返回至持有者手牌并发动。选择对手场上的１张卡牌并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18828179,'母脑鱼','解放场上一张“海洋看守者”即可特殊召唤此卡。它可将一个水属怪兽舍弃到墓地，以破坏一张面朝下的卡牌。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18832779,'海造贼－利斯号',replace(replace('“海造贼”怪兽×２\r\n具此卡名的①②效果１回合各只能使用１次。\r\n①：在我方／对手的主要阶段可发动。从手牌及我方的魔法与陷阱区域里面朝上的卡片中选择１张“海造贼”怪兽卡特殊召唤。\r\n②：对手怪兽的效果发动时，从手牌中弃掉１张“海造贼”卡可发动。将该发动失效并破坏。此卡装备有“海造贼”卡的情况下，还能从卡组将１张“海造贼”卡加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','发动无效','是否从牌组把「海造贼」卡加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18837926,'气冲冲队长','①：此卡召唤成功时，以自己墓地的1只等级4以下的怪兽为对象可以发动。以守备表示形式将该怪兽特殊召唤。以此效果特殊召唤的怪兽的效果无效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18842395,'力量侵略者','对手场上的怪兽为２只或以上的场合，此卡可无须释放进行召唤。','不用解放召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18843291,'光道雅典娜 密涅瓦',replace(replace('协调＋协调以外的怪兽１只以上\r\n此卡名的①③效果１回合仅可各使用１次。\r\n①：此卡同步召唤的情况下可以发动。从牌组将“光道”怪兽送至墓地，数量最多为作为该同步素材的“光道”怪兽数量（同种族最多１只）。\r\n②：自己场上的“光道”怪兽不可因效果除外。\r\n③：从自己的墓地将最多４只“光道”怪兽除外可以发动。依所除外的数量，从自己的牌组上面将卡送至墓地。','\r',char(13)),'\n',char(10)),'从牌组送至墓地','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18847598,'高等宝玉兽 琥珀猛犸',replace(replace('①：场地区域不存在“高等暗黑”的情况下，此怪兽将被送至墓地。\r\n②：１回合１次，对手发动以自己的“高等宝玉兽”卡或自己的“高等暗黑”为对象的效果时可以发动。将该发动无效。\r\n③：１回合１次，自己的“高等宝玉兽”怪兽被选择为攻击对象时可以发动。将该攻击无效。\r\n④：表侧表示的此卡在怪兽区域被破坏的情况下，可不送至墓地，而是视为永续魔法卡以表侧表示放在自己的魔法与陷阱区域。','\r',char(13)),'\n',char(10)),'发动无效','攻击无效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18859369,'混沌格雷法',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：只要此卡存在于怪兽区域，此卡的属性也视为“暗”。\r\n②：从手牌将１只光属性或暗属性怪兽舍弃可以发动。将１只属性与所舍弃的怪兽不同的光・暗属性怪兽从牌组送至墓地。此回合，自己不可特殊召唤以此效果送至墓地的怪兽及其同名怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18861006,'红飞马 焰翼天马',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次，且②效果1回合仅可使用1次。\r\n①：对手场上的怪兽数量多于自己场上怪兽的情况下，此卡可从手牌特殊召唤。此回合，此卡可直接攻击。\r\n②：对手发动场上的怪兽的效果时可以发动。给予对手相当于此效果发动时累积的连锁的数量×300的伤害，此卡不会因那些效果被破坏。','\r',char(13)),'\n',char(10)),'','给与伤害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18865703,'ZEXAL兵器－玄武绝对圣盾','此卡召唤、特殊召唤成功时，可选择１只从游戏中被除外的我方的超量怪兽并以守备表示特殊召唤。此外，可选择我方场上１只冠有“希望皇霍普”之名的怪兽并发动。我方场上的此怪兽可被视为上升守备力２０００点的装备卡，装备被选择的我方冠有“希望皇霍普”之名的怪兽。我方场上只可有１张“ZEXAL兵器－玄武绝对圣盾”以表侧表示存在。','装备','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18890039,'书灵师・崛起',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：作为此卡发动时的效果处理，可从牌组将自己场上不存在同名卡的1只“书灵师”怪兽加入手牌。\r\n②：在自己的主要阶段可以发动。为使合计等级达到仪式召唤的怪兽的等级以上，解放自己手牌・场上的怪兽，从手牌将1只“书灵师”仪式怪兽仪式召唤。','\r',char(13)),'\n',char(10)),'是否从牌组把「书灵师」怪兽加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18891691,'完美机械王','此卡的攻击力上升场上除此卡以外的机械族怪兽数量×５００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18895832,'系统崩溃','①：支付１０００LP可以发动。从对手场上・墓地将所有机械族怪兽除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18897163,'DDD 超死伟王黯黑地狱末日',replace(replace('←1 【灵摆】 1→\r\n①：1回合1次，另一方自己的灵摆区域存在“DD”卡的情况下可以发动。从额外牌组将“DDD 超死伟王黯黑地狱末日”以外的1只“DDD”超量怪兽特殊召唤。\r\n【怪兽效果】\r\n等级8“DDD”怪兽×2\n①：此卡超量召唤时可以发动。从自己额外牌组（表侧）将1只“DD”灵摆怪兽作为此卡的超量素材。\n②：自己场上的灵摆怪兽不会因效果被破坏。\n③：1回合1次，去除此卡的1个超量素材，依自己场上的灵摆怪兽的数量，以对手场上的怪兽为对象可以发动。将该怪兽破坏。\n④：怪兽区域的此卡被破坏的情况下可以发动。将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'「DDD」超量怪兽特殊召唤','补充超量素材','对手怪兽破坏','此卡在自己的灵摆区域放置','','','','','','','','','','','','');
INSERT INTO texts VALUES(18905770,'翼龙衍生物','由「吞婴蛇」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18914778,'变形史莱姆','能够自由改变形状，变身成任何物体的史莱姆。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18937875,'灼热之枪','仅限装备炎属性怪兽。装备怪兽的攻击力上升４００点，守备力下降２００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18940556,'究极传导恐兽',replace(replace('此卡不可通常召唤。\r\n从自己墓地将2只恐龙族怪兽除外的情况下可以特殊召唤。\r\n①：1回合1次，在自己・对手的主要阶段可以发动。将自己手牌・场上的1只怪兽破坏，将对手场上的表侧表示怪兽全部改成里侧守备表示。\r\n②：此卡可攻击所有对手怪兽各1次。\r\n③：此卡攻击守备表示怪兽的伤害步骤开始时可以发动。给予对手1000伤害，将该守备表示怪兽送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18940725,'随风飘飘游×知更','此卡名的①③效果１回合仅可各使用１次，发动此效果的回合中，自己不可将怪兽特殊召唤。①：此卡召唤成功的情况下可以发动。从牌组将１只等级４以下的鸟兽族怪兽加入手牌。然后，可召唤１只鸟兽族怪兽。②：表侧表示的此卡离开场上的情况下，将其除外。③：此卡在被除外的状态下，鸟兽族怪兽被召唤至自己场上的情况下可以发动。将此卡加入手牌。','','此卡加入手牌','是否把鸟兽族怪兽召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18954366,'优丽的灵镜',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：以自己墓地的1只等级4以下的怪兽为对象可以发动。从手牌将1只等级在该怪兽的等级以下的怪兽特殊召唤。然后，将对象怪兽视为装备魔法卡，装备于该特殊召唤的怪兽。只要该怪兽以此效果装备着怪兽，攻击力就上升以此效果装备着的怪兽的攻击力的一半的数值。此回合，自己不可发动该装备卡及其同名卡的效果。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18960169,'格布林佯攻部队','此卡对对手生命造成战斗伤害时，可从我方牌组抽取１张卡牌。此卡进行过攻击的场合，在战斗阶段结束时变为守备表示，直到下次我方回合的结束阶段时不可变更表示形式。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18963306,'银河眼光波龙',replace(replace('等级８怪兽×２\r\n①：１回合１次，去除此卡的１个超量素材，以对手场上的１只表侧表示怪兽为对象可以发动。直至结束阶段为止获得该怪兽的控制权。以此效果获得控制权的怪兽的效果无效化，攻击力变为３０００，卡名视为“银河眼光波龙”。此效果发动后，直至回合结束时为止，此卡以外的自己怪兽不可直接攻击。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18964575,'速攻稻草人','①：对手怪兽直接攻击宣言时，从手牌将此卡舍弃可以发动。使该攻击无效，然后结束战斗阶段。','攻击无效并结束战斗阶段','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18967507,'铠狱龙－电子暗黑冥龙',replace(replace('“电子暗黑”效果怪兽×5\r\n此卡从额外牌组仅可通过融合召唤来特殊召唤。\r\n①：此卡特殊召唤的情况下可以发动。从自己墓地将1只龙族或机械族怪兽视为装备魔法卡装备于此卡。\r\n②：此卡的攻击力上升以此卡的效果装备的怪兽的攻击力数值。\r\n③：对手发动魔法・陷阱・怪兽的效果时，将自己场上的1张装备卡送至墓地可以发动。将该发动无效并破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18969888,'灿幻超龙 三极天龙',replace(replace('龙族协调＋协调以外的龙族怪兽１只以上\r\n此卡名的③效果在决斗中仅可使用１次。\r\n①：此卡同步召唤的情况下可以发动。将场上的怪兽全部改成攻击表示。\r\n②：只要此卡存在于怪兽区域，可攻击的对手怪兽必须攻击，对手在战斗阶段中不可发动效果。\r\n③：在攻击宣言过３次以上的自己・对手回合中可以发动。从墓地将此卡特殊召唤。然后，可将场上的１张卡破坏。','\r',char(13)),'\n',char(10)),'改变形式','','从墓地特殊召唤','是否选场上1张卡破坏？','已经使用过「灿幻超龙 三极天龙」的③的效果','','','','','','','','','','','');
INSERT INTO texts VALUES(18973184,'失烙印',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：只要此卡存在于魔法与陷阱区域，自己发动包含融合召唤融合怪兽的效果在内的效果的情况下，该发动不会被无效化，该融合召唤成功时，对手不可发动魔法・陷阱・怪兽的效果。\r\n②：自己将融合怪兽融合召唤的情况下可以发动。从牌组将1只“阿尔白斯之落胤”或记载有该卡名的怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18988391,'解放彼岸花','可在我方的主要阶段时将墓地中的此卡从游戏中除外来发动此卡。该回合中有１次机会，可令我方召唤怪兽的场合下所需释放的怪兽减少１只。“解放彼岸花”的效果在１个回合中只可发动１次。','解放数量降低','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18988396,'奇迹渡鸦－供品的仪式－',replace(replace('←0 【灵摆】 0→\r\n①：1回合1次，在自己的主要阶段可以发动。为使合计等级达到1以上，解放自己手牌・场上的怪兽，将此卡仪式召唤。\r\n【怪兽效果】\r\n以“奇迹渡鸦－供品的仪式－”降临\n此卡仅可以仪式召唤方式特殊召唤。\n此卡名的③怪兽效果1回合仅可使用1次。\n①：仪式召唤的此卡不受对手发动的效果影响。\n②：要仪式召唤1只仪式怪兽的情况下，使用自己场上的1张此卡即可作为仪式召唤所必需的解放。\n③：此卡为仪式召唤而被解放的情况下可以发动。从牌组将1只仪式怪兽加入手牌。','\r',char(13)),'\n',char(10)),'此卡特殊召唤','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(18993198,'化合兽氧牛',replace(replace('①：只要此卡存在于场上、墓地时，被视为通常怪兽。\r\n②：可将场上被视为通常怪兽的此卡作为通常召唤再召唤１次。该场合此卡被视为效果怪兽获得以下效果。\r\n●可在我方主要阶段发动。从手牌特殊召唤１只二重怪兽，直至回合结束时，我方场上所有二重怪兽的等级变成以此效果特殊召唤的怪兽的原本等级。“化合兽氧牛”的此效果１回合只可使用１次。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19000848,'晓光之布依欧',replace(replace('此卡名的①③效果1回合仅可各使用1次。\r\n①：此卡存在于手牌的情况下，以自己场上的1只恶魔族效果怪兽为对象可以发动。将该怪兽的效果无效，将此卡特殊召唤。\r\n②：只要此卡存在于怪兽区域，自己左端・右端的主要怪兽区域的怪兽就不会因效果被破坏。\r\n③：此卡被送至墓地的情况下可以发动。从牌组将1张“至天的叛逆”加入手牌。','\r',char(13)),'\n',char(10)),'','特殊召唤','检索','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19012345,'灰尘王 灰痕','①：此卡给予对手战斗伤害的情况下发动。此卡的等级上升1（最多至12）。','等级上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19019586,'宝石象','我方主要阶段时可发动。将场上表侧表示的此卡返回至持有者手牌。此外，此卡进行战斗的伤害计算时，１次可从手牌将１只通常手牌送入墓地并发动１次。此卡的守备力仅限于该伤害计算时上升１０００点。','返回手牌','守备上升1000','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19024706,'英雄逆袭','我方场上冠有“元素－英雄”之名的怪兽因战斗被破坏时可发动。对手随机挑选１张我方手牌并相互确认。其为冠有“元素－英雄”之名的怪兽的场合，挑选对手场上的１只怪兽破坏，并将确认过的怪兽从手牌特殊召唤至我方场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19025379,'真红领主',replace(replace('以“真红眼转生”降临。\r\n①：１回合１次，自己或对手发动“真红领主”以外的魔法・陷阱・怪兽的效果时，以场上的１只怪兽为对象可以发动。将该怪兽破坏。\r\n②：１回合１次，自己或对手发动“真红领主”以外的魔法・陷阱・怪兽的效果时，以场上１张魔法・陷阱卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'选择一张怪兽破坏','选择一张魔法·陷阱破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19027895,'转生炎兽的复生',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：以自己墓地的１只炎属性怪兽为对象可以发动。将该怪兽特殊召唤。\r\n②：将墓地的此卡除外，以自己场上的１只“转生炎兽”怪兽与自己墓地的１只同名怪兽为对象可以发动。将该墓地的怪兽放回牌组，该自己场上的怪兽攻击力直至回合结束时为止，上升相当于自身原本攻击力的数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19028307,'兽神机王巴巴罗斯Ur',replace(replace('①：此卡可从我方手牌、场上、墓地除外兽战士族怪兽和机械族怪兽各１只，并从手牌特殊召唤。\r\n②：对手因此卡的战斗受到的战斗伤害变成０。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19036557,'元素军刀 玛卡妮',replace(replace('①：１回合１次，可从手牌将１只“元素军刀”怪兽送入墓地并发动。从牌组将１只除“元素军刀・玛卡妮”以外的“元素军刀”怪兽或“灵神”怪兽加入手牌。\r\n②：此卡存在于墓地的场合，１回合１次，可宣言１个属性并发动。直至回合结束时，墓地的此卡变成宣言之属性。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19041767,'二重召唤师','可在对手的结束阶段时支付５００点LP发动１次此卡。通常召唤手牌中的１只二重怪兽或通常召唤１次我方场上表侧表示的二重怪兽。此外，此卡在１个回合中有１次机会不会因战斗被破坏。','通常召唤','表侧表示召唤','里侧表示放置','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19048328,'幻龙星－嘲风',replace(replace('协调＋1只以上协调以外的怪兽\r\n①：只要同步召唤的此卡存在于怪兽区域，对手不可发动原本属性与作为此卡的同步素材的“龙星”怪兽相同的怪兽的效果。②：同步召唤的此卡因战斗・效果被破坏并被送至墓地时可以发动。从牌组将1只协调加入手牌。③：1回合1次，对手场上的怪兽因战斗・效果被破坏时可以发动。从自己的牌组将原本属性与1只该怪兽相同的1只幻龙族怪兽以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'牌组协调加入手牌','牌组怪兽特殊召唤','地属性「龙星」怪兽作为同步素材','水属性「龙星」怪兽作为同步素材','炎属性「龙星」怪兽作为同步素材','风属性「龙星」怪兽作为同步素材','光属性「龙星」怪兽作为同步素材','暗属性「龙星」怪兽作为同步素材','神属性「龙星」怪兽作为同步素材','','','','','','','');
INSERT INTO texts VALUES(19050066,'娱乐伙伴 巴洛克库里波',replace(replace('←1 【灵摆】 1→\r\n①：１回合１次，在自己・对手的战斗阶段开始时可以发动。从牌组将１只攻击力３００／守备力２００的怪兽加入手牌。然后将此卡破坏。\r\n【怪兽效果】\r\n①：自己的怪兽因战斗被破坏时可以发动。从手牌将此卡特殊召唤。\n②：只要此卡存在于怪兽区域，对手不可将其他怪兽选择为攻击对象。\n③：此卡被攻击的情况下，伤害步骤结束时变为攻击表示。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19059929,'炎舞－玉衡－',replace(replace('以对手场上的１张里侧表示的魔法・陷阱卡为对象可以发动此卡（应对此卡的发动，对手不可发动对象卡）。\r\n①：只要此卡存在于魔法与陷阱区域，对象的里侧表示卡不可发动。\r\n②：只要此卡存在于魔法与陷阱区域，自己场上的兽战士族怪兽的攻击力上升１００。','\r',char(13)),'\n',char(10)),'请选择对手场上放置的1张魔法·陷阱卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19066538,'轰隆的大海蛇','“魔法神灯”＋“兵主部”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19086954,'助手格布林','１回合１次，可在我方的主要阶段时，将此卡作为装备卡装备至我方的“巨型半兽人”上，或者解除装备状态以表侧攻击表示特殊召唤此卡。以此效果变为装备卡的场合，可在１回合中变更１次装备怪兽的表示形式。（１只怪兽最多只可装备１张联合。装备怪兽因战斗而被破坏的场合，破坏此卡来代替。）','装备','解除装备状态表侧攻击表示特殊召唤','改变装备怪兽的表示形式','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19089195,'潜海奇袭',replace(replace('①：作为此卡发动时的效果处理，可从自己手牌・墓地发动1张“海”。\r\n②：场上存在“海”的情况下，表侧表示的此卡获得以下效果。\r\n●1回合1次，将自己场上的1只表侧表示的水属性怪兽直至结束阶段为止除外可以发动。此回合中，自己场上的表侧表示的魔法・陷阱卡不会因对手的效果被破坏。\r\n●原本等级在5以上的自己的水属性怪兽与对手怪兽进行战斗的伤害步骤开始时发动。将该对手怪兽破坏。','\r',char(13)),'\n',char(10)),'是否把「海」发动？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19093698,'莫桑壹白骨',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：此卡只要存在于墓地，卡名视为“白骨”。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从牌组将“莫桑壹白骨”以外的1只“白骨”或1张记载有该卡名的卡加入手牌。此回合，自己仅可特殊召唤不死族怪兽。\r\n③：只要此卡存在于怪兽区域，自己除通常召唤外仅可追加1次，在自己的主要阶段召唤1只等级4以下的不死族怪兽。','\r',char(13)),'\n',char(10)),'检索','使用「莫桑壹白骨」的效果召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19096726,'铁兽鸟 墨丘利耶',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：自己场上存在需以“阿尔白斯之落胤”作为融合素材的融合怪兽，且对手发动怪兽效果时，将手牌・场上的此卡送至墓地可以发动。将该效果无效。\r\n②：此卡被除外的情况下可以发动。将除“铁兽鸟 墨丘利耶”以外的、1只“阿尔白斯之落胤”或记载有该卡名的怪兽从牌组加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19113101,'预防番茄','可将墓地的此卡从游戏中除外并发动。此回合，我方受到的效果伤害变成０。此效果仅限在对手回合发动。','效果无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19139516,'废铁野兽','①：表侧守备表示的此卡在被选择为攻击对象的情况下，在战斗阶段结束时发动。将此卡破坏。②：此卡因“废铁”卡的效果被破坏并被送至墓地的情况下，以自己墓地１只“废铁野兽”以外的“废铁”怪兽为对象可以发动。将该怪兽加入手牌。','此卡破坏','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19144622,'妖精传姬－火柴莉儿',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：场上存在原本攻击力为1850的魔法师族怪兽的情况下可以发动。从手牌・墓地将此卡特殊召唤。此回合，自己仅可特殊召唤魔法师族怪兽。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从牌组将1张“妖精传姬”魔法・陷阱卡或“妖精之传姬”加入手牌。\r\n③：支付500LP可以发动。将对手场上1只效果怪兽的卡名视为“妖精的王子大人”。','\r',char(13)),'\n',char(10)),'特殊召唤','检索效果','改变卡名','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19144623,'妖精王子','','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19153590,'巨钻武装龙','此卡名的①②效果１回合仅可各使用１次。①：将１只风属性或等级７以上的、此卡以外的龙族怪兽从手牌送至墓地可以发动。从手牌将此卡特殊召唤。②：从手牌・牌组将“巨钻武装龙”以外的１只“武装龙”怪兽送至墓地，以自己场上的１只表侧表示怪兽为对象可以发动。此回合，自己仅可用１只怪兽攻击，对象怪兽的攻击力上升相当于送至墓地怪兽的等级×３００的数值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19153634,'黑暗贵族','只要此卡以表侧表示存在于场上，对手怪兽的攻击对象由我方选择。','是否要改变攻击对象？','请选择要改变的攻击对象','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19159413,'魔法除去','选择场上的１张魔法卡并破坏。选择被盖牌的卡牌的场合，翻开该卡进行确认，若为魔法卡则破坏，若为陷阱卡的场合则恢复原状。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19162134,'娱乐决斗',replace(replace('①：只要此卡存在于场地区域，双方玩家分别在１回合中每次满足以下条件，每有１个条件，１回合各１次，可从牌组抽２张。\r\n●将等级不同的５只怪兽同时特殊召唤。\r\n●自身的１只怪兽进行了５次战斗。\r\n●在连锁５以上发动了卡的效果。\r\n●摇骰子次数及掷硬币的次数合计达到５次。\r\n●受到过使自身的LP变为５００以下的伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19163116,'宝石骑士・黑曜石','①：此卡从手牌被送至墓地的情况下，以自己墓地的1只等级4以下的通常怪兽为对象可以发动。将该怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19181420,'冥铭途・双头龙',replace(replace('“冥铭途”怪兽×２\r\n此卡名的①③效果１回合仅可各使用１次。\r\n①：此卡融合召唤的情况下可以发动。将自己的手牌・场上（表侧表示）的１只“冥铭途”怪兽破坏，从牌组将最多２只“冥铭途”怪兽加入手牌（同名卡最多１张）。\r\n②：自己的“冥铭途”怪兽战斗破坏的怪兽不去墓地而直接被除外。\r\n③：融合召唤的此卡被破坏的情况下可以发动。从自己的墓地将１只等级６以下的“冥铭途”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'破坏怪兽并检索「冥铭途」怪兽','特殊召唤「冥铭途」怪兽','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19182751,'次代机・中子','①：在召唤此卡的结束阶段可以发动。从牌组将１只机械族协调加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19186123,'幻影解放','①：以自己魔法与陷阱区域的１张“幻影－英雄”怪兽卡为对象可以发动。将该卡特殊召唤。②：将墓地的此卡除外，以自己墓地的１只“幻影－英雄”怪兽为对象可以发动。将该怪兽加入手牌。此效果在此卡被送至墓地的回合不可发动。','特殊召唤','回收墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19190082,'女战神战车',replace(replace('①：１回合１次，可从以下效果选择１个并发动。\r\n●以我方场上的１只天使族怪兽为对象，并将此卡视为装备卡装备该怪兽。装备怪兽因战斗、效果被破坏的场合，破坏此卡作为代替。\r\n●特殊召唤被装备的此卡。\r\n②：装备怪兽的攻击宣言时可发动。装备怪兽的攻击力上升５００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19204398,'正义盟军 视光者',replace(replace('协调＋协调以外的怪兽１只或以上\r\n此卡的攻击力上升对手墓地光属性怪兽数量×２００点。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19211362,'星义・标旗',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡存在于手牌的情况下，以“星义・标旗”以外的、自己除外状态的1只怪兽为对象可以发动。将此卡特殊召唤，将对象怪兽放回牌组。\r\n②：在自己的主要阶段可以发动。从牌组将“星义・标旗”以外的1只“星义”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19221310,'异色眼军刀龙','①：在此卡存在于手牌中的情况下，解放自己场上的１只光属性怪兽可以发动。从手牌・牌组及自己场上的表侧表示怪兽中，挑选１只“异色眼龙”送至墓地，将此卡特殊召唤。②：此卡战斗破坏怪兽并将其送至墓地时可以发动。挑选对手场上的１只怪兽破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19222426,'元素－英雄 雷霆巨人－雷霆漩涡',replace(replace('属性不同的“元素－英雄”怪兽×2\r\n此卡仅可以融合召唤方式特殊召唤。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡特殊召唤的情况下，如果对手场上的卡的数量多于自己场上的卡则可以发动。将场上的其他卡全部破坏。\r\n②：解放以通常怪兽作为素材融合召唤的此卡，以自己墓地的1只“元素－英雄”怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'破坏','特殊召唤','用通常怪兽为素材作融合召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19230407,'给死者的供物','破坏场上１只表侧表示的怪兽。跳过我方下个抽牌阶段。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19230408,'给死者的供物','破坏场上１只表侧表示的怪兽。跳过我方下个抽牌阶段。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19252988,'陷阱干扰','仅限战斗阶段期间可发动。使对手发动的陷阱卡效果无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19254117,'仁王立',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：以场上的1只表侧表示怪兽为对象可以发动。该怪兽的守备力变为两倍，回合结束时其守备力变为0。\r\n②：将墓地的此卡除外，以自己场上的1只怪兽为对象可以发动。此回合，对手怪兽仅可攻击对象怪兽。','\r',char(13)),'\n',char(10)),'守备力变成2倍','把墓地的此卡除外','守备力变成0','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19261966,'神影依・异花莉莉丝',replace(replace('“影依”怪兽+水属性怪兽\r\n此卡仅可通过融合召唤从额外牌组中特殊召唤。①：只要此卡存在于怪兽区域，双方就不可用魔法・陷阱卡的效果从手牌・墓地将怪兽特殊召唤。②：在此卡被送至墓地的情况下，可以自己墓地的1张“影依”魔法・陷阱卡为对象发动。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19271881,'赫耀的王之烙印','此卡名的①②效果１回合１次，仅可使用其中１个。①：挑选自己场上的１只需以“阿尔白斯之落胤”作为融合素材的融合怪兽，将场上该怪兽以外的所有表侧表示的卡的效果直至回合结束时为止无效。②：此回合有融合怪兽被送至自己墓地的情况下，在结束阶段可以发动。将墓地的此卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19272658,'超量便当',replace(replace('①：对手场上的怪兽因战斗被破坏的情况下，或被送至墓地的情况下，以自己场上的１只超量怪兽为对象可以发动。从对手的墓地挑选１只怪兽，重叠在对象怪兽下面作为超量素材。\r\n②：将墓地的此卡除外，以场上的１只被从额外牌组特殊召唤的怪兽为对象可以发动。变更该怪兽的表示形式。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19275188,'岩吼战士・世代',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：对手场上怪兽的数量比自己场上的怪兽多的情况下，在自己・对手的战斗阶段可以发动。从牌组将１只“岩吼战士”怪兽特殊召唤。在对手回合中发动此卡的情况下，只要在此回合以此效果特殊召唤的怪兽以表侧表示存在于自己场上，对手仅可攻击该怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19280589,'小天使特勒斯','此卡名的①②效果1回合仅可各使用1次。①：此卡从怪兽区域被送至墓地的情况下可以发动。将1只“特勒斯之羽衍生物”（天使族・光・星1・攻/守0）特殊召唤至自己场上。②：自己场上有“特勒斯之羽衍生物”存在的情况下，将墓地的此卡与手牌的1张魔法卡除外可以发动。将2只“特勒斯之羽衍生物”特殊召唤至自己场上。此效果发动后，直至回合结束时为止自己仅可从手牌特殊召唤怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19280590,'特勒斯之羽衍生物','由「小天使特勒斯」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19299793,'红莲王 焰罪',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：在自己・对手的主要阶段，自己场上存在恶魔族协调的情况下，或对手场上存在被特殊召唤的怪兽的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：此卡特殊召唤的情况下可以发动。给予对手自己场上的炎属性怪兽的种类×400的伤害。\r\n③：此卡作为同步素材被送至墓地的情况下可以发动。从牌组将1张通常陷阱卡送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19301729,'电子光虫－电阻水黾',replace(replace('以此卡作为超量召唤的素材的情况下，仅可使用于昆虫族怪兽的超量召唤。\r\n①：自己召唤昆虫族・等级３怪兽成功时可以发动。从手牌将此卡特殊召唤。然后，可将此卡和该怪兽的等级改成５或７。\r\n②：此卡从手牌的特殊召唤成功的情况下可以发动。挑选自己场上的１只昆虫族怪兽，变更表示形式。\r\n③：以场上的此卡作为素材超量召唤的怪兽获得以下效果。\r\n●此卡的攻击力・守备力上升１０００。','\r',char(13)),'\n',char(10)),'','','是否改变等级？','「电子光虫－电阻水黾」效果适用中','','','','','','','','','','','','');
INSERT INTO texts VALUES(19302550,'DD 魔导贤者牛顿',replace(replace('←10 【灵摆】 10→\r\n①：自己仅可灵摆召唤“DD”怪兽。此效果不会被无效化。②：只要此卡存在于灵摆区域，仅限１次，给予自己伤害的陷阱卡的效果发动的情况下，可将该效果无效。然后将此卡破坏。\r\n【怪兽效果】\r\n此卡名的怪兽效果１回合仅可使用１次。①：从手牌将此卡舍弃，以自己墓地“DD 魔导贤者牛顿”以外的１张“DD”卡或“契约书”卡为对象可以发动。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'卡片回收','是否使用「DD 魔导贤者牛顿」的效果？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19304410,'铁兽守宝团 炎工之姬特',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：自己场上存在“铁兽守宝团 炎工之姬特”以外的“铁兽”怪兽或“守宝团”怪兽的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：此卡被送至墓地的情况下可以发动。从自己墓地将除“铁兽守宝团 炎工之姬特”以外的以下怪兽中的1只以守备表示特殊召唤。\r\n●“铁兽”怪兽\r\n●“守宝团”怪兽\r\n●“阿尔白斯之落胤”或记载有该卡名的怪兽','\r',char(13)),'\n',char(10)),'从手牌特殊召唤','从墓地特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19307353,'魂之造形家','此卡名的效果1回合仅可使用1次。①：解放自己场上的1只怪兽可以发动。将原本攻击力与原本守备力的合计与解放的怪兽相同的1只怪兽从牌组加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19310321,'纹章兽 双头鹰',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：将墓地的此卡除外，以自己场上的1只没有超量素材的超量怪兽和自己墓地的2只“纹章兽”怪兽为对象可以发动。将该墓地的怪兽作为该超量怪兽的超量素材。','\r',char(13)),'\n',char(10)),'素材补充','请选择一只没有素材的超量怪兽','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19312169,'陷阱封印的咒符','此卡只有在“封印师 明晴”存在于我方场上时才可发动。只要此卡存在于场上，陷阱卡便不可发动，场上所有陷阱卡的效果无效。当“封印师 明晴”不存在于我方场上时，破坏此卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19316241,'银河战龙',replace(replace('此卡名的①②效果1回合仅可各使用1次，发动此效果的回合中，自己仅可特殊召唤光属性怪兽。\r\n①：光属性・等级4怪兽被特殊召唤至自己场上的情况下可以发动。从手牌・墓地将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。\r\n②：以自己场上的1只其他的光属性・等级4怪兽为对象可以发动。将该怪兽与此卡的等级直至回合结束时为止改成8。','\r',char(13)),'\n',char(10)),'特殊召唤','等级变成8','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19322865,'地缚囚人 地线巡视者',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从自己的牌组・墓地将１张“地缚牢”或“异界共鸣－同步结合”加入手牌。\r\n②：自己场上存在等级６以上的“地缚”怪兽的情况下，将墓地的此卡除外，以对手场上１只被从额外牌组特殊召唤的效果怪兽为对象可以发动。将该效果怪兽放回牌组。然后，对手可从自身的额外牌组将１只其同名怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','是否特殊召唤同名怪兽？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19324993,'特异－英雄 地狱操控者',replace(replace('“－英雄”怪兽2只\r\n此卡名的①效果1回合仅可使用1次。\r\n①：此卡连接召唤的情况下可以发动（发动此效果的回合中，自己仅可特殊召唤“－英雄”怪兽）。向对手出示额外牌组的1只“－英雄”融合怪兽，从牌组将最多2只卡名记载于该怪兽的融合素材怪兽加入手牌（同名卡最多1张）。\r\n②：此卡连接端的恶魔族怪兽的攻击力・守备力上升自身等级×100的数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19326613,'妖精传姬要开始啰要开始啰',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从自己手牌・墓地・除外状态各将最多1只光属性的“妖精传姬”怪兽特殊召唤（同名卡最多1张）。此回合，自己仅可特殊召唤魔法师族怪兽。\r\n②：此卡被除外的情况下，或从场上以外的地方被送至墓地的情况下可以发动。将此卡放置在自己场上。以此效果放置的此卡，在自己场上不存在“妖精传姬”怪兽的情况下就不可发动。','\r',char(13)),'\n',char(10)),'特殊召唤','放置','「妖精传姬要开始啰要开始啰」效果适用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19327348,'暗灵使 达尔克','①：此卡反转的情况下，以对手场上的１只暗属性怪兽为对象发动。此怪兽以表侧表示存在期间，获得该怪兽的控制权。','获得对手场上1只暗属性怪兽的控制权','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19327349,'暗灵使 达尔克','①：此卡反转的情况下，以对手场上的１只暗属性怪兽为对象发动。此怪兽以表侧表示存在期间，获得该怪兽的控制权。','获得对手场上1只暗属性怪兽的控制权','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19333131,'编号12 机甲忍者・深红暗影',replace(replace('等级５怪兽×２\r\n①：１回合１次，可移除取此卡的１个超量素材并发动。此回合，我方场上的“忍者”怪兽不会因战斗、效果被破坏。此效果在对手回合也可发动。','\r',char(13)),'\n',char(10)),'破坏耐性','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19337371,'歇斯底里的定约','此卡名的①②效果１回合１次，仅可使用其中１个。①：作为此卡发动时的效果处理，从自己的牌组・墓地挑选１张“万华镜－华丽的分身－”加入手牌。②：此卡从手牌・场上被送至墓地的回合的结束阶段发动。从牌组将最多３张“神鹰”卡加入手牌（同名卡最多１张）。','检索','是否还要选择名字带有「神鹰」的卡加入手牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19338434,'迷拟宝箱鬼・岔路',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：以对手场上的1只里侧表示怪兽为对象可以发动。对手从以下效果挑选1个，自己适用其效果。\r\n●将对象怪兽改成表侧攻击表示或表侧守备表示。\r\n●将对象怪兽送至墓地。然后，以此效果被送至墓地的怪兽的持有者抽2张。\r\n②：将墓地的此卡除外可以发动。从牌组将1张“迷拟宝箱鬼・岔路”加入手牌。','\r',char(13)),'\n',char(10)),'发动','那只怪兽变成表侧攻击表示或者表侧守备表示','那只怪兽送至墓地，那之后，那持有者抽2张','检索','','','','','','','','','','','','');
INSERT INTO texts VALUES(19353570,'影蛮干骑士','我方成功召唤等级３怪兽时，可以从手牌中特殊召唤这张卡。这张卡无法用作同步素材。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19355597,'宝石骑士女郎・璀璨辉钻',replace(replace('“宝石骑士”怪兽×3\r\n此卡从额外牌组仅可通过以上述卡作为融合素材的融合召唤来特殊召唤。\r\n自己1回合仅可特殊召唤1次“宝石骑士女郎・璀璨辉钻”。\r\n①：1回合1次，在自己的主要阶段可以发动。将自己场上的1只表侧表示“宝石骑士”怪兽送至墓地，从额外牌组将1只“宝石骑士”融合怪兽无视召唤条件特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19357125,'暗黑暗杀者',replace(replace('根据我方墓地的暗属性怪兽数量，此卡获得以下效果。\r\n●１张或以下：此卡的攻击力下降４００点。\r\n●２～４张：此卡的攻击力上升４００点。\r\n●５张或以上：可将此卡送入墓地并发动。破坏所有盖牌于对手场上的怪兽。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19362568,'冰风之叠歌',replace(replace('此卡名的卡１回合仅可发动１张。①：可从以下效果中选择１个发动。\r\n●以自己墓地的１只“风魔女”怪兽为对象可以发动。以守备表示形式将该怪兽特殊召唤。\r\n●对手连锁自己的“风魔女”怪兽效果的发动，发动魔法・陷阱・怪兽的效果时可以发动。将对手的该效果无效。','\r',char(13)),'\n',char(10)),'特殊召唤','效果无效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19369609,'抒情歌鸲－逍遥音乐鸫',replace(replace('等级1怪兽×2只以上\r\n①：此卡的攻击力上升此卡的超量素材数量×500的数值。\r\n②：1回合1次，去除此卡的1个超量素材，以对手场上的1张魔法・陷阱卡为对象可以发动。将该卡放回牌组。\r\n③：自己的其他怪兽进行战斗的伤害步骤开始时，去除此卡的任意数量的超量素材可以发动。该自己的怪兽的攻击力直至回合结束时为止，上升所去除的数量×300的数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19384334,'燃烧熔岩','场上的炎属性怪兽的攻击力上升５００点，守备力下降４００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19394153,'羽翼射击','可选择我方场上的１只“元素－英雄 羽毛人”并发动。该回合，被选择怪兽不可直接攻击，但在１次的战斗阶段中可进行次数相当于我方场上的怪兽数量的攻击。该回合，其他的我方怪兽不可进行攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19403423,'撕裂时间的绿柱魔瞳',replace(replace('①：此决斗中，分别适用以下效果。\r\n●自己不可发动手牌的怪兽的效果。\r\n●自己的抽牌阶段的通常抽牌变为2张。\r\n●自己1回合可进行最多2次通常召唤。\r\n②：将墓地的此卡除外，从手牌舍弃1张“撕裂时间的绿柱魔瞳”可以发动。此回合，自己的怪兽召唤成功时，对手不可发动怪兽的效果。','\r',char(13)),'\n',char(10)),'适用效果','把墓地的此卡除外','「撕裂时间的绿柱魔瞳」效果适用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19406822,'言灵','只要此卡以表侧表示存在于场上，场上的同名怪兽被破坏。（后来出现的同名怪兽被破坏。同时出现的场合，破坏所有同名怪兽。）','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19420830,'满天祸 科尔德',replace(replace('此卡名的效果１回合仅可使用１次。\r\n①：自己场上的表侧表示风属性怪兽因战斗或对手的效果被破坏的情况下可以发动。从手牌将此卡特殊召唤。然后，可挑选场上的１张魔法・陷阱卡放回持有者的牌组最上面。','\r',char(13)),'\n',char(10)),'此卡特殊召唤','是否选魔法·陷阱卡回到牌组？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19434243,'力量恶龙',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：自己场上的怪兽，不存在的情况下或均为暗属性同步怪兽的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：此卡特殊召唤的情况下可以发动。从牌组将1只“共鸣者”怪兽加入手牌。此回合，自己从额外牌组仅可特殊召唤暗属性同步怪兽。\r\n③：以此卡作为同步素材将“暗红恶魔龙”同步召唤的情况下，该怪兽不会因战斗被破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','检索','','「力量恶龙」效果适用中','','','','','','','','','','','','');
INSERT INTO texts VALUES(19439119,'魔轰神克露丝','①：此卡从手牌被舍弃至墓地的情况下，以自己墓地1只其他的等级4以下的“魔轰神”怪兽为对象发动。将该怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19441018,'电池人－业务用','此卡不可通常召唤。仅限我方墓地冠有“电池人”之名的２只怪兽从游戏中除外的场合可特殊召唤。１回合１次，可将我方墓地的１只雷族怪兽从游戏中除外并发动。选择场上的１只怪兽和１张魔法、陷阱卡破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19451302,'蛇绞','对手场上攻击力为０的攻击表示怪兽，不会因与冠有“爬虫妖”之名的怪兽进行战斗而被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19462747,'黑羽－吊风之德斯',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：此卡召唤・特殊召唤时，以自己场上的1只“黑羽”怪兽为对象，可从以下效果中选择1个发动。\r\n●对象怪兽的等级上升1。\r\n●对象怪兽的等级下降1。\r\n②：在此卡被送至墓地的回合的结束阶段发动。自己受到1000伤害。','\r',char(13)),'\n',char(10)),'等级变更','等级上升','等级下降','受到伤害','','','','','','','','','','','','');
INSERT INTO texts VALUES(19474136,'曼陀铃草龙',replace(replace('←2 【灵摆】 2→\r\n【怪兽效果】\r\n有悲痛欲绝的龙魂宿居着的曼陀铃。据说会演奏出诅咒的音色，闻音之人会因为极度的恐惧而失去自我。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19476824,'玄化末日龙',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡召唤・特殊召唤成功的情况下可以发动。从自己的牌组上面将３张卡除外。此卡的攻击力上升相当于以此效果除外的“玄化”卡数量×３００的数值。\r\n②：此卡给予对手战斗伤害时可以发动。从牌组将１只等级５以上的“玄化”怪兽特殊召唤。以此效果特殊召唤的怪兽将在下个回合的结束阶段被除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19489718,'魔键铳－巴托斯巴斯特',replace(replace('以“魔键－马夫提亚”降临。\r\n此卡名的①效果１回合仅可使用１次。\r\n①：此卡仪式召唤成功的情况下可以发动。从牌组将１张“魔键”卡加入手牌。\r\n②：１回合１次，拥有与自己墓地任一通常怪兽或“魔键”怪兽相同的属性的对手怪兽与此卡进行战斗的攻击宣言时可以发动。将任意数量的自己的手牌放回牌组最下面，将该对手怪兽的效果直至回合结束时为止无效。然后，自己依放回牌组的数量抽牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19491080,'小丑戏帮 哈特',replace(replace('←7 【灵摆】 7→\r\n此卡名的灵摆效果1回合仅可使用1次。\n①：在自己的主要阶段可以发动。从牌组将灵摆怪兽以外的1张“小丑戏帮”卡送至墓地，将此卡特殊召唤。此效果发动后，直至下个回合结束时为止，自己不可发动被从牌组・额外牌组特殊召唤的怪兽的效果。\r\n【怪兽效果】\r\n①：只要自己场上存在上级召唤的怪兽，对手场上的怪兽的守备力下降1500。\n②：此卡被解放的情况下，可从以下效果中选择1个发动（此卡名的以下效果1回合仅可各选择1次）。\n●将双方额外牌组（表侧）・场上的灵摆怪兽全部放回牌组。\n●从牌组・额外牌组将灵摆怪兽以外的1只“小丑戏帮”怪兽无视召唤条件特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','选择效果','回到牌组','特殊召唤','','','','','','','','','','','','');
INSERT INTO texts VALUES(19501924,'灵摆转换',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：以自己场上的最多２只灵摆怪兽为对象可以发动。将该自己的灵摆怪兽放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19502505,'沉默的魔导剑士－沉默帕拉丁',replace(replace('①：此卡召唤成功时可发动。从牌组将１只“沉默剑士 LV3”或“沉默魔术师 LV4”加入手牌。\r\n②：只要此卡以表侧表示存在于场上，仅１次，只以我方场上的１只怪兽为对象的魔法卡发动时，可发动。使该发动无效。\r\n③：场上的此卡因战斗或对手效果被破坏的场合，可以我方墓地的１只光属性“LV”怪兽为对象发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'牌组检索','发动无效','墓地回收','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19504025,'纠罪巧－重置再巧',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从自己牌组・墓地将1张“纠罪都市”以表侧表示放在自己的场地区域。自己场上存在“纠罪都市”的情况下，作为代替可以自己灵摆区域的卡的数量为上限，将对手场上的表侧表示卡的效果无效。\r\n②：此卡存在于墓地的状态下，对手发动卡的效果的情况下，将此卡除外可以发动。以自己灵摆区域的卡的数量为上限，将自己场上的“纠罪巧”怪兽改成里侧守备表示。','\r',char(13)),'\n',char(10)),'发动','变成里侧守备','是否把卡无效？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19505896,'杂草','场上的此卡被破坏的场合，可破坏我方场上的１只植物族怪兽作为代替。','是否要使用「杂草」的效果代替破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19508728,'月镜之盾',replace(replace('①：在这张卡的装备怪兽和对手怪兽进行战斗的伤害计算时发动。装备怪兽的攻击力・守备力只在伤害计算时变成进行战斗的对手怪兽的攻击力和守备力中较高方的数值+100。\r\n②：表侧表示的这张卡从场上被送至墓地的情况下，支付500LP进行发动。这张卡放回牌组最上面或者最下面。','\r',char(13)),'\n',char(10)),'牌组最上面','牌组最下面','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19510093,'超重僧兵 大弁庆－K',replace(replace('←1 【灵摆】 1→\r\n此卡名的灵摆效果１回合仅可使用１次。①：自己场上存在“超重武者”怪兽的情况下可以发动。从牌组将１只“超重武者装魂”怪兽加入手牌。\r\n【怪兽效果】\r\n此卡名在规则上也视为“超重武者”卡。此卡名的①②怪兽效果１回合仅可各使用１次。①：自己墓地不存在魔法・陷阱卡的情况下可以发动。从手牌・牌组将１只“超重武者 大弁庆－K”送至墓地，从手牌将此卡特殊召唤。②：此卡作为同步素材以表侧表示加入额外牌组的情况下可以发动。将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'','此卡从手牌特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19516687,'书灵师・特工',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡存在于手牌的情况下，向对手出示手牌的1只仪式怪兽可以发动。将此卡特殊召唤。\r\n②：以“书灵师・特工”以外的、自己墓地的1张“书灵师”卡为对象可以发动。将该卡加入手牌。以此效果将魔法・陷阱卡加入了手牌的情况下，进而挑选自己的1张手牌放回牌组最下面。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19523799,'昼夜大火灾','给予对手生命８００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19535693,'能－朋.克.世阿泯',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：支付600LP可以发动。从牌组将“能－朋.克.世阿泯”以外的1只“朋.克.”怪兽加入手牌。\r\n②：此卡被送至墓地的情况下，以自己场上的1只“朋.克.”怪兽为对象可以发动。该怪兽的攻击力上升600。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19544412,'选手入场广播',replace(replace('此卡名在规则上也视为“燃烧拳击”卡。\r\n此卡名的卡１回合仅可发动１张。\r\n①：从手牌将１只“燃烧拳斗士”怪兽特殊召唤。然后，可将场上的魔法・陷阱卡破坏，数量最多为自己场上的超量怪兽的数量。','\r',char(13)),'\n',char(10)),'','是否破坏魔法·陷阱卡？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19578592,'愚钝之斧','①：装备怪兽的攻击力上升１０００，效果无效化。②：在自己的准备阶段发动。给予装备怪兽的控制者５００伤害。','500伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19580308,'DD 拉弥亚','此卡名的效果１回合仅可使用１次。①：此卡存在于手牌・墓地的情况下，从手牌及自己场上表侧表示的卡中，将“DD 拉弥亚”以外的１张“DD”卡或“契约书”卡送至墓地可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡离开场上的情况下，将其除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19590644,'布局上勾拳',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：自己的怪兽因战斗被破坏时可以发动。将１只拥有该怪兽的攻击力以下的攻击力怪兽从手牌・牌组以里侧守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19594506,'新宇空间引导者','①：将此卡从手牌舍弃至墓地可以发动。从自己的牌组・墓地挑选１张“新宇空间”加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19596712,'邃渊鳞甲－塞特斯',replace(replace('仅可装备于“水精鳞”怪兽。\r\n①：装备怪兽的攻击力上升８００。\r\n②：只要此卡存在于魔法与陷阱区域，在对手场上发动的陷阱卡的效果无效化。然后，将此卡送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19605133,'大植然瓢虫','①：解放此卡，以自己场上的１只“大植然”怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止上升１０００。②：自己同步召唤“大植然”怪兽成功时可以发动。从墓地将此卡特殊召唤。','特殊召唤','攻击上升','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19612721,'圆盘斗士','此卡攻击守备力２０００或以上的守备表示怪兽的场合，不进行伤害计算破坏该怪兽。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19613556,'大岚','①：将场上的魔法・陷阱卡全部破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19619755,'娱乐伙伴 五虹的魔术师',replace(replace('←12 【灵摆】 12→\r\n①：自己仅可从额外牌组灵摆召唤。此效果不会被无效化。\n②：双方根据自身的魔法与陷阱区域的里侧表示卡的数量适用以下内容。\n●0张：自己场上的怪兽不可攻击，自己不可发动其效果。\n●4张以上：自己场上的怪兽的攻击力变为原本数值的两倍。\r\n【怪兽效果】\r\n①：此卡存在于墓地的状态下，有魔法・陷阱卡被放置在自己场上的情况下可以发动。将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19636995,'急兔马',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次。\r\n①：有纵列不存在卡的情况下，此卡可从手牌以攻击表示特殊召唤至该纵列的自己场上。\r\n②：有其他卡被摆放在与此卡同一纵列的情况下发动。将此卡破坏。\r\n③：1回合1次，在自己的主要阶段可以发动。此回合，此卡原本的攻击力变为一半，可直接攻击。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19642774,'花之同步士','①：此卡作为同步素材被送至墓地的情况下可以发动。从手牌将1只等级2以下的怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19642889,'核成电钻手','此卡的控制者在每次我方的结束阶段，从手牌将１张“核成之钢核”送入墓地，或向对手展示１张手牌的通常陷阱卡。或者，不执行上述任何一项破坏此卡。此卡与光属性或暗属性的怪兽进行战斗的场合，仅在战斗阶段期间该怪兽的效果被无效化。','选择一张「核成之钢核」送至墓地','选择一张通常陷阱给对手观看','破坏「核成电钻手」','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19652159,'光与暗之龙王',replace(replace('龙族・光属性・等级８怪兽＋龙族・暗属性・等级８怪兽\r\n此卡仅可以融合召唤方式特殊召唤。\r\n①：只要此卡存在于怪兽区域，此卡的属性也视为“暗”。\r\n②：怪兽的效果・魔法・陷阱卡发动时发动（同一连锁上最多１次）。此卡的攻击力・守备力下降１０００，将该发动无效。\r\n③：此卡因对手被破坏的情况下，以自己墓地的１只龙族怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'属性当作暗','发动无效','墓地特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19665973,'消战者','①：对手怪兽直接攻击宣言时可以发动。从手牌将此卡特殊召唤。然后，结束战斗阶段。以此效果特殊召唤的此卡从场上离开的情况下将被除外。','结束战斗阶段','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19667590,'隆隆隆巨灵','此卡名的效果１回合仅可使用１次。①：此卡存在于墓地的状态下，自己特殊召唤“隆隆隆”怪兽成功的情况下可以发动。将此卡以守备表示特殊召唤。发动此效果的回合中，自己无法进行战斗阶段。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19671102,'奇迹螺旋阶梯',replace(replace('①：在自己的主要阶段可以发动此效果。从手牌舍弃１张“廷达三角”卡，从以下效果中挑选１个适用。此回合，不可以自己的“奇迹螺旋阶梯”的效果将以此效果舍弃的卡的同名卡舍弃。\r\n●挑选自己场上的１只里侧守备表示怪兽改成表侧攻击表示。\r\n●挑选自己场上的１只表侧攻击表示怪兽改成里侧守备表示。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19671433,'玛那桃圆乡・心像','此卡名的①②效果１回合仅可各使用１次。①：将手牌的１只“玛那桃圆乡”怪兽或“维萨思・史塔弗罗斯特”出示给对手可以发动。自己从牌组抽２张。然后，挑选１张手牌放回牌组最下面。②：将墓地的此卡除外，以自己场上的１只攻击力１５００／守备力２１００的怪兽为对象可以发动。将该怪兽直至回合结束时为止视为协调。','抽牌','变成协调','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19673561,'魔女工艺・羊皮纸卷','此卡名的②③效果１回合１次，仅可使用其中１个。①：１回合１次，自己的魔法师族怪兽战斗破坏怪兽时可以发动。自己从牌组抽１张。②：自己场上的“魔女工艺”怪兽为发动效果而要舍弃手牌的情况下，可将此卡送至墓地作为代替。③：此卡存在于墓地，自己场上有“魔女工艺”怪兽存在的情况下，在自己的结束阶段可以发动。将此卡以表侧表示放在自己的魔法与陷阱区域。','抽牌','返回场上','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19680539,'圣骑士高文','我方场上存在光属性通常怪兽的场合，此卡可从手牌以表侧守备表示特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19684740,'妖精骑士 因古纳尔',replace(replace('等级６怪兽×３\r\n①：１回合１次，去除此卡的２个超量素材可以发动。将场上此卡以外的卡全部放回持有者的手牌。应对此效果的发动，对手不可发动魔法・陷阱・怪兽的效果。','\r',char(13)),'\n',char(10)),'返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19688343,'燃烧拳击・交叉反击',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：对手发动怪兽的效果时可以发动。将自己场上的１只“燃烧拳斗士”超量怪兽或“编号”超量怪兽破坏，将该发动无效并破坏。然后，可适用以下效果。\r\n●从额外牌组将卡名与所破坏的自己怪兽不同的１只“燃烧拳斗士”超量怪兽特殊召唤，将此卡作为该怪兽的超量素材。','\r',char(13)),'\n',char(10)),'是否从额外牌组特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19700943,'怒怒怒机器人',replace(replace('要通常召唤此卡的情况下，必须以里侧守备表示放置。\r\n①：此卡攻击的情况下，直至伤害步骤结束时为止不受其他卡的效果影响。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19712214,'海晶少女涡轮',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：自己或对手的怪兽攻击宣言时可以发动。使该攻击无效，从自己的额外牌组・墓地将１只“海晶少女 水晶心”特殊召唤。\r\n②：将墓地的此卡除外，以自己场上的１只连接２以上的“海晶少女”连接怪兽为对象可以发动。此回合，该怪兽在１次战斗阶段中可攻击的次数最多为自身连接标记的数量，因该怪兽的战斗对对手造成的战斗伤害变为０。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19715246,'电子世界蛇',replace(replace('此卡不可通常召唤，仅可以卡的效果特殊召唤。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：对手场上存在怪兽的情况下可以发动。从手牌将此卡特殊召唤。然后，从牌组挑选1只“电子龙”，特殊召唤或视为装备魔法卡装备于此卡。此回合，自己仅可特殊召唤机械族怪兽。\r\n②：将自己场上的1张“电子龙”放回手牌可以发动。从自己牌组・墓地将1张“融合”加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','检索','是否装备？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19733961,'电池人－单二型','我方场上的“电池人－单二型”皆为攻击表示的场合，每存在１只“电池人－单二型”，所有我方场上的机械族怪兽的攻击力上升５００点。我方场上的“电池人－单二型”皆为守备表示的场合，每存在１只“电池人－单二型”，所有我方场上的机械族怪兽守备力上升５００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19737320,'大门守门员','制造守卫入口的机械。要破坏它可不容易！','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19739265,'日与月',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：以自己及对手场上各1只怪兽为对象可以发动。根据其表示形式，对该怪兽分别适用以下效果。\r\n●表侧表示：改成里侧守备表示。\r\n●里侧表示：改成表侧守备表示。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19740112,'干旱之结界像','①：只要此卡存在于怪兽区域，双方只能特殊召唤地属性怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19743887,'蹴神－VARefar',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：自己场上的怪兽成为对手场上的怪兽的效果对象时，或被选择为对手怪兽的攻击对象时可以发动。从手牌将此卡特殊召唤。然后，可挑选该1只对手怪兽并向对手出示1张手牌。该情况下，进而根据所出示的卡的种类，对挑选的怪兽适用以下效果。\r\n●怪兽：改成守备表示。\r\n●魔法：攻击力改成两倍。\r\n●陷阱：除外。','\r',char(13)),'\n',char(10)),'特殊召唤','是否给对手观看手牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19747827,'真红眼的黑龙剑',replace(replace('仅限以“海尔摩斯之爪”的效果将我方手牌、场上的龙族怪兽送入墓地的场合，此卡可特殊召唤。\r\n①：此卡特殊召唤成功的场合，以场上除此卡以外的１只怪兽为对象发动。此卡被视为攻击力上升１０００的装备卡装备该怪兽。\r\n②：以此卡效果装备此卡的怪兽的攻击力、守备力，上升双方场上、墓地的龙族怪兽数量×５００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19748583,'拥抱圣剑的王妃桂妮薇尔',replace(replace('“拥抱圣剑的王妃桂妮薇尔”的①的效果１回合只可使用１次。\r\n①：可以我方场上１只“圣骑士”怪兽为对象发动。将手牌、墓地的此卡视为攻击力上升３００的装备卡装备该我方怪兽。\r\n②：根据装备怪兽的属性获得以下效果。\r\n●光：装备怪兽因效果被破坏的场合，可破坏此卡作为代替。\r\n●暗：装备怪兽与对手怪兽进行战斗的伤害步骤开始时可发动。破坏该怪兽。之后破坏此卡。','\r',char(13)),'\n',char(10)),'装备','是否要使用「拥抱圣剑的王妃桂妮薇尔」的效果代替破坏？','破坏','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19763315,'不运的报告','对手下次的战斗阶段进行２次。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19771459,'战吼・加托斯',replace(replace('此卡牌名的②效果１回合只可使用１次。\r\n①：战士族、地属性怪兽被召唤至我方场上的场合可发动。从手牌特殊召唤此卡。\r\n②：此卡因对手效果从怪兽区被送入墓地的场合可发动。从手牌、牌组特殊召唤１只等级５或以上的“战吼”怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19801646,'传说的渔夫二世',replace(replace('①：此卡只要存在于场上・墓地，卡名视为“传说的渔夫”。\r\n②：只要场上存在“海”，场上的此卡不受其他怪兽的效果影响。\r\n③：表侧表示的此卡因对手的效果从场上离开的情况下，或因战斗被破坏的情况下可以发动。从牌组将1只水属性・等级7怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19808608,'DD 巴风特','①：１回合１次，以自己场上“DD 巴风特”以外的１只“DD”怪兽为对象，宣言１～８之间的任意等级可以发动。该怪兽直至回合结束时为止变为所宣言的等级。此效果发动后，直至回合结束时为止，自己仅可特殊召唤“DD”怪兽。','宣言等级','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19814508,'超级运动员竞技场',replace(replace('①：“超级运动员”怪兽被召唤至我方场上的场合可发动。从牌组将１只“超级运动员”怪兽加入手牌。\r\n②：１回合１次，“超级运动员”怪兽被特殊召唤至我方场上的场合发动。我方场上的怪兽攻击力上升５００点。','\r',char(13)),'\n',char(10)),'牌组检索','攻守变换','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19827717,'死者生还','将我方手牌中的１张怪兽卡弃置至墓地。回合结束时，将此回合中因战斗而被破坏送入我方墓地的１只怪兽收回到手牌中。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19828680,'炼狱的契约','①：除此卡以外的我方手牌是３张或以上的场合，可发动。舍弃我方的所有手牌。之后，可从我方墓地挑选１只“无限狱”怪兽或龙族、暗属性、等级８的同步怪兽并特殊召唤。','是否特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19844995,'召唤限制－力量过滤器','只要此卡存在于场上，双方玩家不可特殊召唤攻击力１０００以下的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19847532,'地狱焰皇','此卡不可特殊召唤。此卡上级召唤成功时，可将存在于我方墓地中最多５只炎属性怪兽从游戏中除外。破坏场上与因此效果除外怪兽数量相等的魔法、陷阱卡。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19870120,'进击的帝王','①：只要此卡存在于魔法与陷阱区域，自己场上上级召唤的怪兽不会成为效果的对象，不会因效果被破坏。②：只要此卡存在于魔法与陷阱区域，自己不可从额外牌组特殊召唤怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19877898,'终极昆虫 LV7','只要以“终极昆虫 LV5”的效果特殊召唤的此卡存在于场上，对手场上所有怪兽的攻击力、守备力下降７００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19882096,'恐惧爪・针尖贝罗尼亚','此卡名以①方法的特殊召唤１回合仅可进行１次。①：此卡可从手牌特殊召唤至与自己场上“恐惧爪”怪兽相邻或同一纵列的、自己的主要怪兽区域。②：只要此卡存在于怪兽区域，额外怪兽区域的自己的“恐惧爪”怪兽攻击了守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19885332,'白之水镜',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：以自己墓地的１只等级４以下的鱼族怪兽为对象可以发动。将该怪兽特殊召唤。然后，可从牌组将原本卡名与特殊召唤的怪兽相同的１只怪兽加入手牌。','\r',char(13)),'\n',char(10)),'是否从牌组把同名卡加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19891131,'时潜怪盗・规范器','此卡名的①②效果1回合仅可各使用1次。①：自己场上没有此卡以外的怪兽存在的情况下，解放此卡可以发动。从牌组将“时潜怪盗・规范器”以外的2只“时潜怪盗”怪兽以守备表示特殊召唤（同名卡最多1张）。②：此卡存在于墓地的状态下，自己的超量怪兽因战斗被破坏时可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡离开场上的情况下，将其除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19891310,'齿轮齿轮齿轮 XG',replace(replace('等级３怪兽×３\r\n我方机械族怪兽进行战斗的战斗步骤时，可移除此卡的１个超量素材并发动。直至该伤害步骤结束时，对手场上的表侧表示卡牌的效果变成无效，并直至该伤害步骤结束时对手不可发动魔法、陷阱、怪兽效果。此外，表侧表示的此卡从场上离开时可发动。从我方墓地选择１张除此卡以外冠有“齿轮齿轮”之名的卡牌加入手牌。','\r',char(13)),'\n',char(10)),'效果无效','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19899073,'天丛云之巳剑',replace(replace('以“巳剑降临”降临\r\n此卡名的①②③效果1回合仅可各使用1次。\r\n①：此卡特殊召唤的情况下可以发动。将对手场上的怪兽全部破坏。\r\n②：对手发动效果时可以发动。对手可挑选1张手牌舍弃。未舍弃的情况下，其效果无效化。\r\n③：此卡被解放的情况下可以发动。从牌组将“天丛云之巳剑”以外的1张“巳剑”卡加入手牌。然后，可将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'破坏','无效','检索','是否丢弃手牌？','是否特殊召唤？','','','','','','','','','','','');
INSERT INTO texts VALUES(19899074,'天丛云之巳剑',replace(replace('以“巳剑降临”降临\r\n此卡名的①②③效果1回合仅可各使用1次。\r\n①：此卡特殊召唤的情况下可以发动。将对手场上的怪兽全部破坏。\r\n②：对手发动效果时可以发动。对手可挑选1张手牌舍弃。未舍弃的情况下，其效果无效化。\r\n③：此卡被解放的情况下可以发动。从牌组将“天丛云之巳剑”以外的1张“巳剑”卡加入手牌。然后，可将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'破坏','无效','检索','是否丢弃手牌？','是否特殊召唤？','','','','','','','','','','','');
INSERT INTO texts VALUES(19932396,'侵略的一手','可将我方场上上级召唤的１只冠有“侵邪蚀”之名的怪兽返回至持有者手牌并发动。从牌组抽取１张卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19942835,'不死苏生','此卡名的①②效果１回合１次，仅可使用其中１个。①：以自己或对手墓地的１只不死族怪兽为对象可以发动。从自己的牌组・额外牌组将１只该怪兽的同名怪兽除外，将对象怪兽特殊召唤至自己场上。②：此卡存在于墓地的情况下可以发动。挑选被除外的自己的１只不死族怪兽放回牌组，将此卡放置在自己场上。以此效果放置的此卡从场上离开的情况下，将其除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19943114,'电脑网回归','此卡名的卡1回合仅可发动1张。①：自己特殊召唤连接怪兽成功的情况下，以场上的1张卡为对象可以发动。将该卡破坏。然后，自己从牌组抽1张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19951423,'超元特防队 征义',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将“超元特防队 征义”以外的1只“超元特防队”怪兽加入手牌。此卡的正面存在对手怪兽的情况下，自己可进而抽1张。\r\n②：自己场上的怪兽的正面的、对手怪兽发动效果的情况下可以发动。自己场上所有“超元特防队”怪兽的攻击力上升1000。','\r',char(13)),'\n',char(10)),'检索','上升攻击力','是否抽牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19959563,'惩戒之龙',replace(replace('此卡不可通常召唤。\r\n仅可在自己除外状态的“光道”怪兽为４种以上的情况下特殊召唤。\r\n①：在每个自己・对手回合中１次，支付１０００LP可以发动。将“光道”怪兽以外的、双方墓地・除外状态（表侧）的卡全部放回牌组。\r\n②：１回合１次，自己的“光道”怪兽的效果发动的情况下发动。从自己的牌组上面将４张卡送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19959742,'咒仪软体动物','此卡因卡牌效果被送入墓地时，确认我方牌组最上方的３张卡牌，并将确认的３张卡牌按照喜好顺序返回至牌组的上方或下方。','牌组确认','回到牌组最上面','回到牌组最下面','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19963185,'高等宝玉兽 紫晶猫',replace(replace('①：场地区域不存在“高等暗黑”的情况下，此怪兽将被送至墓地。\r\n②：自己的“高等宝玉兽”怪兽可直接攻击。以该直接攻击给予对手的战斗伤害变为一半。\r\n③：表侧表示的此卡在怪兽区域被破坏的情况下，可不送至墓地，而是视为永续魔法卡以表侧表示放在自己的魔法与陷阱区域。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19974580,'链条・龙',replace(replace('协调＋协调以外的怪兽１只或以上\r\n在我方主要阶段时可发动。将我方墓地冠有“链条”之名的怪兽全部从游戏中除外。直至回合结束时，此卡的攻击力上升以此效果除外的怪兽数量×２００点。此外，此卡给予对手生命战斗伤害时，从对手牌组上方将３张卡牌送入墓地。','\r',char(13)),'\n',char(10)),'攻击上升','牌组上面3张卡送至墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19974890,'兽累累','①：将不是在此回合被召唤・特殊召唤的场上怪兽全部改成守备表示。此回合，自身场上存在守备表示怪兽的玩家不可用在此回合被召唤・特殊召唤的怪兽攻击宣言。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(19980975,'钻石尘风暴','可选择１只放置有４个或以上雾计数物的怪兽并发动。破坏被选择的怪兽，被破坏的怪兽上放置的雾计数物，每４个计数物就从我方牌组抽取１张卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20001443,'相剑师－莫邪','此卡名的①②效果１回合仅可各使用１次。①：此卡召唤・特殊召唤成功的情况下，向对手出示手牌的１张“相剑”卡或１只幻龙族怪兽可以发动。将１只“相剑衍生物”（幻龙族・协调・水・星４・攻／守０）特殊召唤至自己场上。只要以此效果特殊召唤的衍生物存在，自己从额外牌组仅可特殊召唤同步怪兽。②：此卡作为同步素材被送至墓地的情况下可以发动。自己从牌组抽１张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20001444,'相剑衍生物','由“相剑”卡片的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20003027,'梅尔菲・帕皮','此卡名的①②效果１回合仅可各使用１次。①：对手将怪兽召唤・特殊召唤成功的情况下，或此卡被选择为对手怪兽的攻击对象的情况下可以发动。将此卡放回持有者的手牌。然后，可从牌组中特殊召唤１只“梅尔菲・帕皮”以外的等级２以下的兽族怪兽。②：在自己的结束阶段可以发动。从手牌将此卡特殊召唤。','','','是否从牌组特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20003527,'云魔物－雨云人','此卡不因战斗被破坏。此卡以表侧守备表示存在的场合，被破坏。此卡可解放我方场上任意数量的水属性怪兽，并以表侧表示上级召唤。此卡上级召唤成功时，放置雾计数物于此卡，其数量相当于被解放水属性怪兽的数量。此卡的攻击力上升场上雾计数物数量×５００点。','只用水属性怪兽作为祭品召唤','放置计数物','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20007374,'聚集之祈愿','①：自己墓地存在５种以上的龙族同步怪兽的情况下可以发动。从额外牌组将１只“星尘龙”视为同步召唤特殊召唤，装备此卡。以此效果特殊召唤的怪兽将在结束阶段被除外。②：装备怪兽的攻击力上升相当于自己墓地龙族同步怪兽的攻击力合计的数值。③：装备怪兽每次战斗破坏对手怪兽，将自己墓地的１只龙族同步怪兽除外可以发动。装备怪兽可继续攻击对手怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20011655,'魔剑达士－塔瓦弯刀恶魔',replace(replace('①：自己场上不存在怪兽的情况下，此卡可从手牌特殊召唤。\r\n②：场上的此卡1回合仅1次不会因对手的效果被破坏。\r\n③：只要此卡存在于怪兽区域，双方不可将其他的怪兽作为装备魔法卡的效果的对象。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20032555,'机关傀偶－炸蛋',replace(replace('从手牌舍弃１只名字带有“机关傀偶”的怪兽，可从以下效果中选择１个发动。“机关傀偶－炸蛋”的效果１回合仅可使用１次。\r\n●给予对手LP８００点伤害。\r\n●直至回合结束时为止，此卡等级变成８。','\r',char(13)),'\n',char(10)),'选择效果发动','给与对手基本分800分伤害','此卡的等级直到结束阶段时变成8星','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20036055,'旅人的到彼岸','此卡名的卡1回合仅可发动1张。①：以自己墓地的、此回合被送至墓地的任意数量的“彼岸”怪兽为对象可以发动。以守备表示形式将该怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20049870,'GMX研究员 塞兰',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：此卡召唤的情况下可以发动。从牌组将战士族以外的1只“GMX”怪兽或等级3以下的恐龙族怪兽特殊召唤。\r\n②：此卡以怪兽的效果特殊召唤的情况下可以发动。从牌组将1张“GMX”魔法・陷阱卡加入手牌。\r\n③：场上存在恐龙族融合怪兽的情况下可以发动。将场上的此卡放回牌组，将场上的1张表侧表示卡的效果直至回合结束时为止无效。','\r',char(13)),'\n',char(10)),'特殊召唤','检索效果','无效效果','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20050865,'水晶机巧－黄晶',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：在对手的主要阶段及战斗阶段，以协调以外的、自己墓地的1只怪兽为对象可以发动。将该怪兽的效果无效并特殊召唤，仅以该怪兽和此卡作为素材，进行1只机械族同步怪兽的同步召唤。此时的同步素材怪兽不去墓地而直接被除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20056760,'灰篮史莱姆',replace(replace('“灰篮史莱姆”的①效果１回合只可使用１次。\r\n①：此卡存在于手牌、墓地的场合，可以我方场上的２张“灰篮”卡牌为对象发动。破坏该卡，特殊召唤此卡。\r\n②：以此卡的①效果特殊召唤成功时，可以我方墓地的１只“灰篮”怪兽为对象发动。以守备表示特殊召唤该怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20057949,'命运继承','可在我方场上冠有“命运女郎”之名的表侧表示怪兽被破坏的回合发动。下一次我方准备阶段时，可从手牌特殊召唤最多２只冠有“命运女郎”之名的怪兽。','是否要发动「命运继承」的效果？','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20060230,'坚硬铠甲','拥有心灵的铠甲，以坚硬的身体来阻截战士。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20065259,'铳之忍者－火光',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡召唤・特殊召唤・反转的情况下可以发动。从自己的手牌・墓地挑选“铳之忍者－火光”以外的１只“忍者”怪兽，以里侧守备表示特殊召唤。\r\n②：此卡存在于墓地，仅以自己场上的１张“忍者”卡或１只里侧守备表示怪兽为对象的对手效果发动时可以发动。将此卡以里侧守备表示特殊召唤，将该成为对象的卡放回持有者的手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20065322,'库里波召唤笛','可选择我方牌组中１只“库里波”或“羽翼库里波”，将其加入到手牌中或特殊召唤至我方场上。','加入手牌','在自己场上特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20065549,'绝对魔法禁止区域','场上除效果怪兽以外的表侧表示怪兽，全部不受魔法卡的效果影响。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20071842,'重型扳机','“枪管上膛镇暴龙”的降临所必需。①：为使合计等级为８以上，解放自己手牌・场上的怪兽，或将自己手牌・场上的“枪弹”怪兽破坏作为解放的代替，从手牌将“枪管上膛镇暴龙”仪式召唤。以此效果特殊召唤的怪兽不会因与从额外牌组被特殊召唤的怪兽的战斗被破坏，不受从被从额外牌组特殊召唤的怪兽发动的效果影响。','','请选择要解放或破坏的怪兽','是否选择「枪弹」怪兽破坏？','「重型扳机」效果适用中','','','','','','','','','','','','');
INSERT INTO texts VALUES(20073910,'天照大神',replace(replace('此卡不可召唤・特殊召唤。\r\n①：对手发动以里侧表示的此怪兽为对象的魔法・陷阱・怪兽的效果时，将此卡改成表侧守备表示可以发动。自己抽1张。\r\n②：此卡反转的情况下发动。将场上的其他卡全部除外。\r\n③：此卡反转的回合的结束阶段发动。将此卡放回手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20087414,'久延毘古',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：此卡发动后，变为拥有以下效果的效果怪兽（天使族・地・星2・攻/守0），特殊召唤至怪兽区域（也视为陷阱卡）。\r\n●对手发动以自己场上的卡为对象的、场上的怪兽的效果时可以发动（同一连锁上最多1次）。将此卡放置在自己的魔法与陷阱区域，将该对手的效果无效。该怪兽的攻击力为对手场上最高的情况下，进而将该怪兽放回手牌。','\r',char(13)),'\n',char(10)),'效果无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20101223,'神之气息','破坏场上所有表侧表示的岩石族怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20127343,'A次代机・转换者','①：１回合１次，以场上的１只表侧表示怪兽为对象，宣言１个属性可以发动。该怪兽直至回合结束时为止变为所宣言的属性。','属性变换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20129614,'梅尔菲・拉比',replace(replace('拉比最为钟爱这棵树桩。经常爬上去朝四周张望。\r\n梅尔菲的森林中有好多好多充满个性的可爱动物。\r\n当你发现这棵树桩时，一定会想坐上去体验一把！\r\n那就来吧，和拉比一起去寻找梅尔菲的朋友们吧♪','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20137754,'流星方界器狄扎',replace(replace('①：此卡召唤、特殊召唤成功时可发动。从牌组将１张“方界”卡牌送入墓地。\r\n②：１回合１次，在此卡是以表侧表示存在的状态，怪兽可在被送入我方墓地的回合发动。直至回合结束时，此卡的攻击力上升我方墓地怪兽种类×２００。此效果在对手回合也可发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20138923,'反魔镜','可在对手发动速攻魔法卡时发动。选择场上的１张卡牌并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20140382,'威压之力','我方场上有上级召唤的等级７以上表侧表示怪兽存在的场合可发动此卡。令陷阱卡或效果怪兽的效果的发动无效并将其破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20145685,'超量装甲・要塞',replace(replace('等级５怪兽×２\r\n１回合１次，“超量装甲・要塞”也可重叠在自己场上的阶级３・４超量怪兽上面超量召唤。\r\n拥有超量素材的此卡不可作为超量召唤的素材。\r\n①：１回合１次，去除此卡的最多２个超量素材可以发动。依去除的数量，从牌组将“装甲超量”卡加入手牌（同名卡最多１张）。\r\n②：装备此卡的怪兽与怪兽的战斗给予对手的战斗伤害变为两倍。','\r',char(13)),'\n',char(10)),'在自己场上的3·4阶的超量怪兽上面重叠来超量召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20154092,'先史遗产 卡布雷拉投石机','１回合１次，可释放我方场上１只除此卡以外冠有“先史遗产”之名的怪兽，并选择对手场上的１只表侧表示怪兽发动。直至回合结束时，被选择怪兽的攻击力变成０。','攻击变成0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20155904,'十二兽 酉刃',replace(replace('①：此卡因战斗・效果被破坏的情况下，以“十二兽 酉刃”以外的、自己墓地的1张“十二兽”卡为对象可以发动。将该卡放回牌组。\r\n②：持有此卡作为素材的、原本种族为兽战士族的超量怪兽获得以下效果。\r\n●对手发动以此卡为对象的怪兽效果时，去除此卡的1个超量素材可以发动。将该发动无效。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20174189,'大植然竹笋','①：只要解放“大植然”怪兽来上级召唤成功的此卡存在于怪兽区域，对手不可发动魔法・陷阱卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20188127,'泉之精灵','从我方墓地中选取１张装备魔法卡加入到手牌中。该装备魔法卡不可在该回合中发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20191720,'刚鬼 月面压击','此卡名的①②效果1回合仅可各使用1次。①：向对手出示手牌中的此卡，以“刚鬼 月面压击”以外的自己场上的1只“刚鬼”怪兽为对象可以发动。将此卡从手牌特殊召唤，将对象怪兽放回持有者手牌。②：以自己墓地的1只“刚鬼”连接怪兽为对象可以发动。将该怪兽放回额外牌组。然后，可以从自己墓地挑选1只“刚鬼”怪兽加入手牌。','','','是否从自己墓地选1只「刚鬼」怪兽加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20193924,'白夜的女王','此卡不可特殊召唤。１回合１次，可选择１张被盖牌于场上的卡牌破坏。','场上放置的1张卡破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20201255,'再起的剑斗兽','①：从自己手牌・墓地将１只自己场上不存在同种族怪兽的“剑斗兽”怪兽特殊召唤。以此效果特殊召唤的怪兽不会因战斗被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20210570,'雷古勒斯','１回合１次，可选择我方墓地的１张场地魔法卡并发动。将被选择的卡牌返回至牌组。','返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20212491,'皮尔莉流浪之街','①：自己场上的“皮尔莉”怪兽在被特殊召唤的回合，不会成为对手效果的对象。②：１回合１次，自己场上的表侧表示的“皮尔莉”超量怪兽因对手从场上离开的情况下发动。从自己的牌组・墓地挑选１只等级１“皮尔莉”怪兽特殊召唤。③：在双方的结束阶段，以场上的１只“皮尔莉”超量怪兽为对象可以发动。从自己的牌组・墓地挑选１张“皮尔莉”速攻魔法卡，重叠在该怪兽下方作为超量素材。','特殊召唤','补充超量素材','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20216608,'孤注差一掷',replace(replace('①：在自己的抽牌阶段已通常抽牌时，将该１张卡出示给对手可以发动。将该卡放回牌组最下面，自己从牌组抽１张。\r\n②：自己以效果抽卡时，将该１张卡出示给对手可以发动。将此卡送至墓地，将出示的卡放回牌组最下面，自己从牌组抽１张。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20228463,'仪典之钟','①：只要此卡存在于怪兽区域，双方持续公开所有手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20246864,'风魔女－冻铃','此卡名的①效果１回合仅可使用１次。①：自己场上的怪兽仅有“风魔女”怪兽的情况下可以发动。从手牌将此卡特殊召唤。②：１回合１次，在自己的主要阶段可以发动。此卡的等级上升１。③：将以此卡作为同步素材的风属性同步怪兽同步召唤的情况下，该同步怪兽不会因战斗被破坏。','','','「风魔女－冻铃」效果适用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20248754,'海造贼－静寂默克号',replace(replace('等级４怪兽×２\r\n具此卡名的①效果１回合只能使用１次。\r\n①：从手牌中弃掉１张“海造贼”卡，以对手场上的１只效果怪兽为目标可发动。除外该怪兽。然后，可将１张“海造贼”魔法／陷阱卡从卡组加入手牌。此卡有“海造贼”卡装备的情况下，此效果在对手回合也能发动。\r\n②：我方场上的“海造贼”卡被战斗／效果破坏的情况下，改为移除此卡的１个超量素材。','\r',char(13)),'\n',char(10)),'','是否从牌组把「海造贼」魔法·陷阱卡加入手牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20264508,'漏雷','给予对手LP对手场上的怪兽数量×４００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20265095,'慧炎星－孔雀三娘',replace(replace('“炎星”怪兽２只\r\n此卡名的②效果１回合仅可使用１次。\r\n①：只要此卡连接端存在“炎星”怪兽，对手怪兽不可将此卡选择为攻击对象。\r\n②：此卡的攻击宣言时将自己场上１张表侧表示的“炎舞”魔法・陷阱卡送至墓地，以对手场上的１只怪兽为对象可以发动。直至结束阶段为止，将该对手怪兽放在此卡连接端并获得其控制权。以此效果获得控制权的怪兽不可攻击宣言。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20277376,'神龙 天启','①：1回合1次，扔掉1张手牌，可以自己墓地的1只龙族怪兽为对象发动。将该龙族怪兽加入手牌。','加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20277860,'铠武者僵尸','由怨念复生的武者。挥舞的武士刀毫无章法，需要注意。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20281581,'娱乐伙伴飞毯鼯鼠',replace(replace('←7 【灵摆】 7→\r\n①：另一边的我方灵摆区不存在有卡牌的场合，此卡被破坏。\n②：只要此卡存在于灵摆区，我方所受到的战斗伤害减半。\r\n【怪兽效果】\r\n①：此卡反转的场合，可以被盖牌于场上的１张卡牌为对象发动。破坏该卡。\n②：此卡特殊召唤成功的场合可发动。将此卡变成里侧守备表示。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20285786,'杰作碎片','①：以自己墓地的２只怪兽为对象可以发动。将该２只怪兽的效果无效并特殊召唤，仅以该２只为素材将１只光属性“霍普”超量怪兽超量召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20292186,'古遗物－戴思塞斯','①：此卡可视为魔法卡从手牌放置在魔法与陷阱区域。②：放置在魔法与陷阱区域的此卡在对手回合被破坏并送至墓地的情况下发动。将此卡特殊召唤。③：在对手回合中，此卡特殊召唤成功的情况下发动。此回合，对手不可从额外牌组将怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20295753,'夜刀蛇巳',replace(replace('此卡名的效果１回合仅可使用１次。\r\n①：此卡因效果被送至墓地的情况下可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20315854,'精灵龙','是非常漂亮的龙之妖精，在妖精中出乎意料地强大。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20318029,'源雷龙','此卡名的①②效果1回合1次，仅可使用其中1个。①：将此卡从手牌中舍弃，以自己场上的1只雷族怪兽为对象可以发动。该怪兽的攻击力上升500。此效果在对手回合中也可以发动。②：此卡被除外的情况下或从场上被送至墓地的情况下可以发动。从牌组将1只“源雷龙”加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20343502,'魔幻甜点教师・眼镜舒芙蕾',replace(replace('等级４“魔幻甜点”怪兽×２\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：在自己・对手回合中，去除此卡的１个超量素材，以场上的１只“魔幻甜点”怪兽为对象可以发动。此回合，该表侧表示怪兽不受自身以外的怪兽的效果影响。\r\n②：此卡存在于怪兽区域的状态下，“魔幻甜点”卡被送至自己墓地的情况下可以发动。将自己・对手墓地的合计最多２张卡放回牌组。','\r',char(13)),'\n',char(10)),'效果抗性','墓地回收','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20345391,'空牙团的参谋 西尔','这个卡名的①②的效果1个回合各只可使用1次。①：自己主要阶段可以发动。从手牌特殊召唤“空牙团的参谋 西尔”以外的1只“空牙团”怪兽。②：这张卡已存在于怪兽区域的状态下，且这张卡以外的“空牙团”怪兽被特殊召唤至自己场上的情况下，可以自己墓地的1只“空牙团”怪兽为对象发动。将该怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20349913,'星河的施舍','自己场上有“银河”超量怪兽存在的情况下，舍弃１张手牌可以发动。从牌组抽２张卡。此卡发动过的余下回合，对手将受到的所有伤害变为一半。“星河的施舍”１回合仅可发动１张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20351153,'幻角兽催眠角','对手场上存在有怪兽，我方场上不存在有怪兽的场合，此卡召唤成功时可发动。选择场上１张被盖牌的魔法、陷阱卡破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20357457,'未来之柱－奇亚诺斯',replace(replace('此卡名在规则上也视为“闪刀”卡。\r\n此卡名的①②③效果1回合仅可各使用1次。\r\n①：从手牌将1张魔法卡舍弃可以发动。从手牌将此卡特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从自己牌组・墓地将1只“闪刀姬－萝杰”特殊召唤。此回合，自己从额外牌组仅可特殊召唤机械族怪兽。\r\n③：将墓地的此卡除外可以发动。挑选自己墓地・除外状态的1只“闪刀姬－萝杰”，加入手牌或特殊召唤。','\r',char(13)),'\n',char(10)),'从手牌特殊召唤','从牌组·墓地特殊召唤','加入手牌或特殊召唤','加入手牌','特殊召唤','','','','','','','','','','','');
INSERT INTO texts VALUES(20358953,'巡洋鲨','我方场上表侧表示的此卡因对手的卡牌效果被破坏的场合，最多可从牌组特殊召唤２只等级４或以下的水属性怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20366274,'神影依・拿非利',replace(replace('“影依”怪兽＋光属性怪兽\r\n此卡从额外牌组仅可通过融合召唤来特殊召唤。\r\n①：此卡特殊召唤的情况下可以发动。从牌组中将1张“影依”卡送至墓地。\r\n②：此卡与被特殊召唤的怪兽进行战斗的伤害步骤开始时发动。将该怪兽破坏。\r\n③：此卡被送至墓地的情况下，以自己墓地的1张“影依”魔法・陷阱卡为对象可以发动。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'送墓','破坏','加入手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20366275,'神影依・拿非利',replace(replace('“影依”怪兽＋光属性怪兽\r\n此卡从额外牌组仅可通过融合召唤来特殊召唤。\r\n①：此卡特殊召唤的情况下可以发动。从牌组中将1张“影依”卡送至墓地。\r\n②：此卡与被特殊召唤的怪兽进行战斗的伤害步骤开始时发动。将该怪兽破坏。\r\n③：此卡被送至墓地的情况下，以自己墓地的1张“影依”魔法・陷阱卡为对象可以发动。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'送墓','破坏','加入手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20366276,'神影依・拿非利',replace(replace('“影依”怪兽＋光属性怪兽\r\n此卡从额外牌组仅可通过融合召唤来特殊召唤。\r\n①：此卡特殊召唤的情况下可以发动。从牌组中将1张“影依”卡送至墓地。\r\n②：此卡与被特殊召唤的怪兽进行战斗的伤害步骤开始时发动。将该怪兽破坏。\r\n③：此卡被送至墓地的情况下，以自己墓地的1张“影依”魔法・陷阱卡为对象可以发动。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'送墓','破坏','加入手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20368763,'幻兽机鹞式狮豹','１回合１次，我方场上的怪兽以发动除此卡以外的卡牌效果为目被释放时，特殊召唤１只“幻兽机衍生物”（机械族、风、星３、攻／守０）。此卡的等级上升相当于我方场上“幻兽机衍生物”的合计等级。只要我方场上存在有衍生物，此卡不会因战斗以及效果被破坏。此外，１回合１次，可释放１只衍生物并发动。从手牌特殊召唤１只冠有“幻兽机”之名的怪兽。','特殊召唤Token','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20368764,'幻兽机衍生物','由名称中带有“幻兽机”的怪兽等的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20374351,'岩浆炎・斯泰莱德',replace(replace('协调＋协调以外的炎属性怪兽１只或以上\r\n此卡同步召唤成功时发动。我方挑选１张手牌送入墓地。此卡成为卡牌效果的对象时，可将我方墓地的１只冠有“岩浆炎”之名的怪兽从游戏中除外并发动。使该发动无效并破坏。','\r',char(13)),'\n',char(10)),'把1张手牌送至墓地','效果发动无效并破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20374520,'逐客令','①：此卡已存在于魔法与陷阱区域的状态下，怪兽给予玩家战斗伤害的情况下发动。将该怪兽放回持有者的手牌。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20394040,'野蛮人１号','①：我方场上每有１只“野蛮人２号”，此卡的攻击力上升５００。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20403123,'娱乐伙伴・手艺魔术师',replace(replace('①：此卡可解放我方场上１只除灵摆怪兽以外的“娱乐伙伴”怪兽，并从手牌特殊召唤。\r\n②：１回合１次，可舍弃１张手牌，并以场上的１张表侧表示卡牌为对象发动。破坏该卡。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20409757,'时读的魔术师',replace(replace('←8 【灵摆】 8→\r\n自己场上不存在怪兽的情况下可以发动此卡。①：自己的灵摆怪兽进行战斗的情况下，对手直至伤害步骤结束时为止，不可发动陷阱卡。②：另一方自己的灵摆区域没有“魔术师”卡或“异色眼”卡存在的情况下，此卡的灵摆刻度变为４。\r\n【怪兽效果】\r\n①：只要此卡存在于怪兽区域，１回合１次，自己灵摆区域的卡不会因对手的效果被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20415050,'神之百臂无形手',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n此卡也可以通过将自己场上的1张其他卡送至墓地来发动。\r\n①：从牌组将1只“百臂无形”怪兽加入手牌。通过将卡送至墓地来发动此卡的情况下，进而可从牌组将“神之百臂无形手”以外的1张“百臂无形”魔法・陷阱卡放置在自己场上。\r\n②：将墓地的此卡除外可以发动。对手抽1张。然后，对手挑选自身的1张手牌舍弃。','\r',char(13)),'\n',char(10)),'检索','抽牌','是否把卡送至墓地来发动？','是否放置？','','','','','','','','','','','','');
INSERT INTO texts VALUES(20417688,'星逢之天河','此卡名的①②效果１回合仅可各使用１次。①：将手牌的１只仪式怪兽出示给对手可以发动。从牌组将１只与该怪兽卡名不同、等级相同的仪式怪兽加入手牌。②：将墓地的此卡除外，从手牌将１张仪式魔法卡送至墓地可以发动。此效果变为与该仪式魔法卡发动时的仪式召唤的效果相同。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20419926,'枪王处决',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：在自己・对手的战斗阶段，从自己墓地将1只暗属性连接怪兽除外，以自己场上的1只“枪管”怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止，上升相当于所除外怪兽的攻击力的数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20424878,'守宝团・洛疾','此卡名的①②效果１回合仅可各使用１次。①：此卡召唤・特殊召唤成功的情况下，以“守宝团・洛疾”以外的自己墓地的１只“守宝团”怪兽或１张“大砂海 黄金的戈尔钢达”为对象可以发动。将该卡加入手牌。②：此卡存在于手牌・场上・墓地的情况下，以自己场上的１只“守宝团”超量怪兽为对象可以发动。将此卡重叠在该怪兽下方作为超量素材。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20426176,'海造贼－战利品',replace(replace('具此卡名的①效果１回合只能使用１次。\r\n①：宣言１个属性，以对手场上１只面朝上的怪兽为目标可发动。使该怪兽变为宣言的属性，直到回合结束。然后，可以选择１只我方墓地中的“海造贼”怪兽洗入卡组或特殊召唤。\r\n②：我方／对手的结束阶段中，如我方场上没有“海造贼”怪兽存在的情况下发动。将此卡送至墓地。','\r',char(13)),'\n',char(10)),'改变属性','此卡送至墓地','是否选怪兽回到牌组或特殊召唤？','回到牌组','','','','','','','','','','','','');
INSERT INTO texts VALUES(20426907,'机壳的再星',replace(replace('①：怪兽被召唤・反转召唤时，该怪兽为等级４以下的情况下发动此效果。将该怪兽的效果直至回合结束时为止无效。\r\n②：怪兽被特殊召唤时，该怪兽为等级５以上的情况下发动此效果。将该怪兽的效果直至回合结束时为止无效。该怪兽离开场上的情况下，将其除外。\r\n③：场上没有“机壳的再星”以外的“机壳”卡存在的情况下，将此卡送至墓地。','\r',char(13)),'\n',char(10)),'是否立即使用效果？','「机壳的再星」效果适用','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20436034,'磁力戒指','仅限装备我方场上的怪兽。装备怪兽的攻击力、守备力下降５００点。对手的攻击全部变成对装备怪兽的攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20438745,'灼热王 派隆',replace(replace('此卡存在于墓地或以表侧表示存在于场上的场合，将被视为通常怪兽。以通常召唤的方式再次召唤场上表侧表示的此卡，此卡将视为效果怪兽并获得以下效果。\r\n●１回合１次，可在我方的主要阶段时发动此卡。给予对手生命１０００点伤害。','\r',char(13)),'\n',char(10)),'1000伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20447641,'机壳的冻结',replace(replace('①：此卡发动后，变为效果怪兽（机械族・地・星４・攻１８００／守１０００），特殊召唤至怪兽区域（不视为陷阱卡）。以此效果特殊召唤此卡的回合，自己场上的“机壳”魔法・陷阱卡不会因效果被破坏。\r\n②：以此卡的效果特殊召唤的此卡在将“隐经机壳”怪兽上级召唤的情况下，可作为３只解放。','\r',char(13)),'\n',char(10)),'用「机壳的冻结」作为3只的数量解放','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20448151,'小丑戏帮《排练》',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：解放自己手牌・场上的1只怪兽可以发动。从牌组将“小丑戏帮《排练》”以外的1张“小丑戏帮”魔法・陷阱卡与1只“小丑戏帮 白脸”加入手牌。\r\n②：将墓地的此卡除外可以发动。为使合计等级达到仪式召唤的怪兽的等级以上，解放自己的手牌・场上的怪兽，从手牌将1只“小丑戏帮”仪式怪兽仪式召唤。','\r',char(13)),'\n',char(10)),'检索效果','仪式召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20450925,'羽翼棉花球','①：可从手牌舍弃此卡并发动。此回合，我方受到的效果伤害变为０。此效果在对手回合也可发动。','效果伤害变成０','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20455229,'防火墙防护者','此卡名的①②效果１回合仅可各使用１次。①：此卡作为电子界族连接怪兽的连接素材被送至墓地的情况下可以发动。从牌组将１只“防火墙防护者”以外的“防火墙”怪兽特殊召唤。发动此效果的回合中，自己仅可特殊召唤电子界族怪兽。②：自己场上的“防火墙”怪兽将被效果破坏的情况下，作为代替可将墓地的此卡除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20457551,'钢核收纳','仅限装备冠有“核成”之名的怪兽。与装备怪兽进行战斗的对手怪兽的攻击力，仅限该伤害计算时下降装备怪兽的等级×１００点。装备怪兽在结束阶段时被破坏的场合，可将此卡送入墓地作为代替。','是否要使用「钢核收纳」的效果代替破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20470500,'武装海猎手','我方场上存在此卡以外的水属性怪兽的场合，与此卡战斗过的效果怪兽，其效果在伤害计算后无效化。此外，场上的此卡被破坏的场合，作为代替可破坏我方场上的１只等级３或以下的水属性怪兽。','效果无效','是否使用「武装海猎手」的效果代替破坏？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20474741,'三戟战士','①：此卡召唤成功时可发动。从手牌特殊召唤１只等级３怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20501450,'插座集中','①：以自己场上的1只表侧表示怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止上升相当于其守备力的数值。发动此卡的回合中，对象怪兽以外的自己的怪兽不可攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20508881,'绚岚之见神',replace(replace('①：可从以下效果中选择1个发动（此卡名的以下效果1回合仅可各选择1次）。\r\n●自己抽2张。然后，手牌存在“绚岚”卡或速攻魔法卡的情况下，挑选其中1张舍弃。不存在的情况下，将自己的手牌全部舍弃。\r\n●从自己牌组・墓地将1张“气旋”加入手牌。\r\n②：此卡因“气旋”的效果被破坏的情况下可以发动。将此卡放置在自己的魔法与陷阱区域。','\r',char(13)),'\n',char(10)),'发动','放置','抽牌效果','检索气旋','','','','','','','','','','','','');
INSERT INTO texts VALUES(20513882,'苦涩的默札','①：可解放我方场上的１只怪兽并发动。从我方牌组・墓地选择１只和解放怪兽原种族・属性・等级相同但卡名相异的怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20515672,'超元特防队 暗夜追缉者',replace(replace('连接怪兽以外的“超元特防队”怪兽1只\r\n此卡名的②效果1回合仅可使用1次。\r\n①：只要此卡存在于怪兽区域，自己的“超元特防队”怪兽正面的对手怪兽不可将与自身同一纵列的怪兽选择为攻击对象。\r\n②：在自己・对手的主要阶段，以自己场上的1只“超元特防队”怪兽为对象可以发动。将该怪兽放回牌组。然后，可将自己除外状态的1只“超元特防队”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','是否选除外的自己怪兽特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20522190,'邪恶屏障－黑暗之力－','对手怪兽的攻击宣言时可发动。将对手场上以守备表示存在的所有怪兽从游戏中除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20529766,'超电磁驱动电流龙',replace(replace('解放以下怪兽并上级召唤的场合，此卡获得相应效果。\r\n●电池人－单一型：使仅以此卡为对象的魔法、陷阱卡的效果无效。\r\n●电池人－单二型：此卡攻击了守备表示怪兽时，若攻击力超过该守备力，给予对手生命相当于该数值的战斗伤害。\r\n●电池人－单三型：此卡的攻击力上升１０００点。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20537097,'苍穹之机界骑士','此卡名以①方法的特殊召唤1回合仅可进行1次，且②效果1回合仅可使用1次。①：同一纵列有2张以上的卡存在的情况下，可将此卡特殊召唤至该纵列的自己场上。②：此卡从手牌召唤・特殊召唤成功的情况下可以发动。从牌组将“苍穹之机界骑士”以外的“机界骑士”怪兽加入手牌，数量为与此卡同一纵列的对手卡的张数（同名卡最多1张）。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20541432,'心锁妖精','能够封印住心中良善的部分，使其成为恶魔的手下。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20546916,'植物狮子','此卡的攻击力上升我方场上的植物族怪兽数量×３００点。只要此卡以表侧表示存在于场上，就不可变更控制权。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20560620,'狸猫大人换天子','此卡名的②效果１回合仅可使用１次。①：只要此卡存在于怪兽区域，此卡不可解放。②：只要此卡存在于怪兽区域，自己要将怪兽仪式召唤的情况下，也可将自己额外牌组的１只怪兽送至墓地作为解放的代替。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20563387,'混沌编号80 葬装霸王 狂战镇魂曲',replace(replace('等级５怪兽×３\r\n①：以自己场上的１只超量怪兽为对象可以发动。将自己场上的此卡视为攻击力上升２０００的装备卡，装备于该自己的怪兽。②：装备怪兽将被破坏的情况下，破坏此卡作为代替。③：此卡持有“编号80 狂装霸王 狂战狂想曲”作为超量素材的情况下，获得以下效果。\r\n●去除此卡的１个超量素材，以场上的１张卡为对象可以发动。将该卡除外。','\r',char(13)),'\n',char(10)),'当作装备卡给自己场上的超量怪兽装备','选择场上1张卡从游戏中除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20568404,'朱罗纪・剑龙',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：在自己的主要阶段可以发动。将自己场上的1张卡破坏，从牌组将1只恐龙族怪兽送至墓地。然后，可从手牌・牌组将合计等级与从牌组送至了墓地的怪兽相等的、“朱罗纪・剑龙”以外的“朱罗纪”怪兽无视召唤条件特殊召唤。此回合，自己仅可特殊召唤恐龙族怪兽。\r\n②：此卡因战斗被破坏时可以发动。将场上的1张表侧表示卡放回手牌。','\r',char(13)),'\n',char(10)),'破坏并送至墓地','回到手牌','是否特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20579538,'森罗的姬芽君 幼芽',replace(replace('“森罗的姬芽君 幼芽”的①②效果１回合只可各使用１次。\r\n①：可解放此卡并发动。翻阅我方牌组最上方的卡牌并送入墓地。之后，可挑选我方墓地的１只“幼芽”怪兽并放置至我方牌组的最上方。\r\n②：牌组的此卡因效果被翻阅并送入墓地的场合，可宣言１到８之间任意等级并发动。从墓地特殊召唤此卡，且此卡的等级变成宣言等级。','\r',char(13)),'\n',char(10)),'翻开牌组','特殊召唤','是否把自己墓地1只「幼芽」怪兽在牌组最上面放置','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20584712,'秘旋谍－硬汉',replace(replace('①：此卡只要存在于场上・墓地，卡名视为“秘旋谍－花花公子”。\r\n②：１回合１次，宣言卡的种类（怪兽・魔法・陷阱），以对手场上的１张卡为对象可以发动。将对手牌组最上面的卡给彼此确认，是所宣言的种类的卡的情况下，将对象卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20586572,'炸弹龙',replace(replace('①：双方因此卡攻击而产生的战斗伤害变为０。\r\n②：此卡因战斗被破坏并送入墓地的场合发动。破坏破坏此卡的怪兽。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20590515,'黄金乡兵卒',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：此卡发动后，变为通常怪兽（不死族・光・星5・攻500/守1800），特殊召唤至怪兽区域（也视为陷阱卡）。自己场上存在“黄金卿埃尔德里奇”的情况下，进而可将场上的1张表侧表示卡破坏。\r\n②：在自己・对手的结束阶段，将墓地的此卡除外可以发动。从牌组将1张“埃尔德里希尔”魔法・陷阱卡放置在自己场上。','\r',char(13)),'\n',char(10)),'','','是否选卡破坏？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20590784,'立于星尘坠地之闪珖','此卡名的卡1回合仅可发动1张。①：被特殊召唤的对手怪兽的直接攻击宣言时，该怪兽的攻击力为自己LP以上的情况下可以发动。使该攻击无效，自己从牌组抽1张。然后，可从自己的额外牌组・墓地挑选1只“星尘”怪兽特殊召唤。','是否要特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20612097,'红色血染的埃尔德里希尔',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：从自己牌组・墓地将1只不死族怪兽特殊召唤。自己场上不存在“埃尔德里奇”怪兽的情况下，以此效果仅可特殊召唤“埃尔德里奇”怪兽。此卡发动后，直至回合结束时为止自己仅可特殊召唤不死族怪兽。\r\n②：将墓地的此卡除外可以发动。从牌组将1张“黄金乡”魔法・陷阱卡放置在自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20618081,'转生炎兽 列鹰','1个回合1次，这个卡名的①②的效果只能使用其中任意1个。①：这张卡被送至墓地的情况下，可以自己墓地1张“转生炎兽”魔法・陷阱卡为对象发动。该卡放置在自己场上。②：这张卡存在于墓地的情况下，可以“转生炎兽 列鹰”以外的自己场上的1只“转生炎兽”怪兽为对象发动。该怪兽放回持有者手牌中，将这张卡从墓地进行特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20618850,'黄金露滴之神碑',replace(replace('此卡名的卡１回合仅可发动１张。①：可从以下效果中选择１个发动。此卡发动后，跳过下一个自己的战斗阶段。\r\n●对手从牌组抽１张。然后，从对手的牌组上面将４张卡除外。\r\n●从额外牌组将１只“神碑”怪兽特殊召唤至额外怪兽区域。','\r',char(13)),'\n',char(10)),'对手抽牌','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20624263,'孔雀','展开美丽羽毛的大型孔雀，会射出那些羽毛进行攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20630765,'魔石术师 克鲁德','１回合１次，每次其他怪兽的效果发动，在此卡放置１个魔石计数物（最多１个）。此卡的守备力上升此卡的魔石计数物×３００点。此外，１回合１次，可移除我方场上的１个魔石计数物并发动。选择对手墓地的１张卡牌并从游戏中除外。','除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20638610,'龙之转生','①：可以我方场上的１只龙族怪兽为对象发动。将该我方龙族怪兽除外，并从我方的手牌、墓地挑选１只龙族怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20644748,'宇宙收缩','双方场上的卡牌各为５张或以下的场合可发动。双方场上可存在的卡牌上限各变为５张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20654247,'青眼混沌龙',replace(replace('以“混沌形态”降临\r\n此卡仅可以仪式召唤方式特殊召唤。\r\n①：场上的此卡不会因对手的效果被破坏，对手不可将场上的此卡作为效果的对象。\r\n②：使用“青眼白龙”仪式召唤的此卡攻击宣言时可以发动。变更对手场上所有怪兽的表示形式。以此效果变更表示形式的怪兽的攻击力・守备力变为０。此回合，此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20663556,'交换蛙','解放自己场上的１只怪兽可以发动。从牌组特殊召唤１只名字带有“青蛙”的怪兽。只要此卡表侧表示存在于场上，名字带有“青蛙”的怪兽不会因战斗被破坏。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20665527,'扬陆群舰 陆地巡洋鲸',replace(replace('效果怪兽２只以上\r\n此卡名的②③效果１回合仅可各使用１次。\r\n①：此卡的攻击力上升相当于双方墓地的连接怪兽的数量×２００的数值。\r\n②：此卡被破坏的情况下，以自己或对手墓地的１只连接３以下的怪兽为对象可以发动。将该怪兽特殊召唤至自己场上。\r\n③：此卡存在于墓地的状态下，场上的连接３以下的怪兽因战斗・效果被破坏的情况下，将此卡除外可以发动。将场上的１张卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20686759,'变形斗士・古董引擎','仅限名字带有“变形斗士”的怪兽可以装备。装备怪兽被破坏的情况下，双方皆受到该怪兽原本攻击力数值的伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20700531,'冰结界的修验者','①：此卡不会因与攻击力１９００以上的怪兽战斗被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20714553,'圣月之伟魔导士 恩底弥翁',replace(replace('包含魔法师族・等级4怪兽在内的怪兽2只\r\n此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：此卡连接召唤的情况下，以自己场上的1只“伟魔”怪兽为对象可以发动。将自己墓地・除外状态的1只魔法师族怪兽视为装备魔法卡，装备于对象怪兽。\r\n②：在自己・对手的主要阶段，以自己魔法与陷阱区域的1张视为装备魔法卡的魔法师族怪兽卡为对象可以发动。将该卡放回手牌。','\r',char(13)),'\n',char(10)),'装备效果','回到手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20715411,'DDD 零死王零降神',replace(replace('←0 【灵摆】 0→\r\n此卡名的灵摆效果1回合仅可使用1次。\n①：在发动了此卡的回合的自己的主要阶段可以发动。从牌组将1张“契约书”永续魔法・永续陷阱卡以表侧表示放在自己场上。\r\n【怪兽效果】\r\n此卡名的①②怪兽效果1回合仅可各使用1次。\n①：此卡以表侧存在于额外牌组的状态下，“DDD 零死王零降神”以外的、自己场上的表侧表示“DDD”卡或“契约书”卡被破坏的情况下可以发动（伤害步骤也可以发动）。将此卡特殊召唤。然后，可将场上的1张卡破坏。\n②：怪兽区域的此卡被破坏的情况下可以发动。将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'放置「契约书」卡','特殊召唤','放置到灵摆区域','是否破坏？','','','','','','','','','','','','');
INSERT INTO texts VALUES(20720928,'玄化因子',replace(replace('①：只要此卡存在于场地区，我方召唤等级５以上的“玄化”怪兽的场合可无须解放。此效果１回合只可适用１次。适用此效果召唤而来的怪兽在下一个回合的结束阶段被除外。\r\n②：只要此卡存在于场地区，针对我方“玄化”怪兽的效果发动，对手不可发动魔法・陷阱・怪兽的效果。','\r',char(13)),'\n',char(10)),'使用「玄化因子」效果不用解放召唤','使用「玄化因子」效果召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20721759,'仇恨裂缝','自己场上的仅１只怪兽因对手的卡的效果被破坏并送至墓地时可以发动。选择对手场上的１只怪兽送至墓地，并给予对手LP该原本攻击力数值的伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20721928,'元素－英雄 闪光人','对各种武器得心应手，光之战士的元素－英雄。神圣闪耀的电光将斩断恶行的退路。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20721929,'元素－英雄 闪光人','对各种武器得心应手，光之战士的元素－英雄。神圣闪耀的电光将斩断恶行的退路。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20721930,'元素－英雄 闪光人','对各种武器得心应手，光之战士的元素－英雄。神圣闪耀的电光将斩断恶行的退路。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20726052,'码丽丝＜序＞GWC－06',replace(replace('此卡名的卡1回合仅可发动1张。\r\n此卡也可通过将自己场上的1只表侧表示“码丽丝”怪兽除外，来在放置的回合发动。\r\n①：将自己墓地・除外状态的1只“码丽丝”怪兽特殊召唤。然后，自己场上存在“码丽丝”连接怪兽的情况下，可依以此效果特殊召唤的怪兽原本攻击力的数值恢复自己的LP。','\r',char(13)),'\n',char(10)),'','','适用「码丽丝＜序＞GWC－06」的效果来发动','是否回复基本分？','','','','','','','','','','','','');
INSERT INTO texts VALUES(20727787,'武装解除','破坏场上的所有装备卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20735371,'倍倍伤害',replace(replace('此卡名的效果１回合仅可适用１次。\r\n①：自己的怪兽被攻击的伤害计算时可以发动。该自己的怪兽不会因该战斗被破坏。自己因该战斗受到战斗伤害时，对手受到相当于该数值两倍的效果伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20745268,'魔弹－亡命之徒',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：自己场上存在“魔弹”怪兽的情况下，以场上的１张表侧表示卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20747792,'浆果魔导女孩',replace(replace('①：此卡召唤成功的场合可发动。从牌组将１只“魔导女孩”怪兽加入手牌。\r\n②：１回合１次，此卡变成对手的效果对象时，或被选择为对手怪兽的攻击对象时可发动。变更此卡的表示形式，并从牌组特殊召唤１只除“浆果魔导女孩”以外的“魔导女孩”怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20758643,'彼岸恶鬼 格拉伯尼','此卡名的①③效果1回合1次，仅可使用其中1个。①：自己场上没有魔法・陷阱卡存在的情况下可以发动。从手牌将此卡特殊召唤。②：自己场上有“彼岸”怪兽以外的怪兽存在的情况下此卡将被破坏。③：此卡被送至墓地的情况下可以发动。从牌组将1只“彼岸恶鬼 格拉伯尼”以外的“彼岸”怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20765952,'魔力无力化之假面','选择场上１张表侧表示的魔法卡发动此卡。每次在我方准备阶段给予所选择魔法卡的控制者５００点伤害。当所选择卡牌离开场上时，破坏此卡。','LP伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20773176,'炎兽的影灵衣－源质艾格扎',replace(replace('←7 【灵摆】 7→\r\n①：自己仅可灵摆召唤“影灵衣”怪兽及“源质”怪兽。此效果不会被无效化。\r\n【怪兽效果】\r\n此卡名的怪兽效果1回合仅可使用1次。\n①：此卡存在于手牌・墓地，且“炎兽的影灵衣－源质艾格扎”以外的、自己的怪兽区域・灵摆区域的表侧表示的“影灵衣”卡或“源质”卡因战斗・效果被破坏的情况下可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20781762,'投石攻击','可从牌组将１只岩石族怪兽送入墓地并发动。给予对手生命５００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20785975,'混沌编号103 神葬零娘 诸神无限',replace(replace('等级5怪兽×3\r\n①：1回合1次，去除此卡的1个超量素材，以对手场上的1只拥有与原本攻击力不同的攻击力的怪兽为对象可以发动。给予对手该怪兽的攻击力与其原本攻击力的差值的伤害，将该怪兽除外。此效果在对手回合中也可以发动。②：拥有超量素材的此卡被破坏并被送至墓地时可以发动。将此卡特殊召唤。此效果在自己墓地有“编号103 神葬零娘 诸神零”存在的情况下才能发动和处理。','\r',char(13)),'\n',char(10)),'除外伤害','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20788863,'转生炎兽的赠礼','1个回合1次，这个卡名的①②的效果只能使用其中任意1个。①：从手牌中扔掉1只“转生炎兽”怪兽后即可发动。从牌组中将1只“转生炎兽”怪兽送至墓地。之后，自己从牌组抽1张。②：用和自身同名的怪兽为素材进行连接召唤的“转生炎兽”连接怪兽存在于自己场上的情况下，从手牌中扔掉1只“转生炎兽”怪兽后可以发动。自己从牌组抽2张。','堆墓并抽1张卡','抽2张卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20797524,'三轮车人','此卡因战斗被破坏并送入墓地时，可从手牌、牌组特殊召唤１只“二轮车人”。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20799347,'电脑堺嫦－兔兔','此卡名的②效果１回合仅可使用１次。①：自己场上没有怪兽存在的情况下，或仅有念动力族・幻龙族怪兽的情况下，此卡无需解放即可召唤。②：此卡存在于墓地的情况下，从手牌将１只念动力族・幻龙族怪兽舍弃可以发动。将此卡视为协调特殊召唤。以此效果特殊召唤的此卡离开场上的情况下，将其除外。此回合，自己仅可特殊召唤等级或阶级为３以上的怪兽。','不用解放作召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20802187,'灵魂变换装置',replace(replace('①：1回合1次，以自己场上的1只超量怪兽为对象可以发动。从自己场上将1只光属性・等级4怪兽作为对象的超量怪兽的超量素材。\r\n②：此卡从场上被送至墓地的情况下，以自己墓地的2只雷族・光属性・等级4的同名怪兽为对象发动。将该雷族・光属性怪兽加入手牌。','\r',char(13)),'\n',char(10)),'素材补充','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20822520,'魔导书库 太阳苏雷','我方墓地的冠有“魔导书”之名的魔法卡是５张或以上的场合可发动。从我方牌组的上方依序翻阅２张卡牌。将其中冠有“魔导书”之名的所有魔法卡加入手牌，剩余的卡牌返回至牌组。“魔导书库 太阳苏雷”１回合只可发动１张，发动此卡的回合，我方不可发动冠有“魔导书”之名以外的魔法卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20831168,'蜥蜴兵','从龙衍生出来的兽人种。在龙族中体型较小、行动敏捷，富有战略性。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20838380,'鲨鱼','鱼族、海龙族、水族怪兽被召唤、特殊召唤至我方场上时，可从手牌特殊召唤此卡。此卡不可作为同步素材。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20848593,'冰水','具攻击性的人鱼，使用身上的刺来发动攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20849090,'星际仙踪－先驱者',replace(replace('①：此卡不会成为对手效果的对象。\r\n②：在自己的准备阶段发动。自己恢复１０００LP。\r\n③：此卡因战斗・效果被破坏并被送至墓地的情况下，将墓地的此卡除外可以发动。从牌组将１只等级６以下的“星际仙踪”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20855340,'进化虫 普雷乌洛斯','此卡在我方场上被破坏并送入墓地的场合，可从手牌特殊召唤１只冠有“进化龙”之名的怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20858318,'必杀！黑蝎合击','“首领扎鲁格”“黑蝎－拆除陷阱的克利夫”“黑蝎－逃跑的奇克”“黑蝎－强力的高戈”“黑蝎－棘之米芮”全部存在于自己场上的情况下可以发动。那些怪兽可以在此回合可直接攻击对手玩家。那些怪兽通过直接攻击对手给予的战斗伤害将变为４００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20862918,'交叉混种','此卡名的卡１回合仅可发动１张。①：从手牌及自己场上的表侧表示怪兽中，将原本种族・属性相同、卡名不同的２只怪兽除外可以发动。将原本种族・属性与那些怪兽相同、卡名不同的１只怪兽从牌组加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20871001,'蓝药水','①：自己恢复４００LP','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20899496,'天龙雪狱',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：以对手墓地的１只怪兽为对象可以发动。将该怪兽效果无效并特殊召唤至自己场上。然后可从自己及对手场上，将种族相同的怪兽各１只除外。','\r',char(13)),'\n',char(10)),'是否选怪兽除外？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20904475,'海瀧龙华－渊轮巴王',replace(replace('此卡名的①②③效果１回合仅可各使用１次。\r\n①：从手牌将此卡舍弃可以发动。从牌组将１张“登龙华海瀧门”加入手牌。\r\n②：在有“海瀧龙华－渊轮巴王”以外的、２只以上怪兽从手牌・牌组被送至墓地的回合的自己的主要阶段可以发动。从墓地将此卡特殊召唤。\r\n③：将自己场上的１张表侧表示“登龙华海瀧门”放回牌组最下面可以发动。将对手的手牌全部除外，对手依其张数抽牌。','\r',char(13)),'\n',char(10)),'检索','墓地特殊召唤','对方卡除外并抽牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20920083,'并列之力',replace(replace('①：自己场上有２只以上的表侧守备表示怪兽存在的情况下，自己场上的守备表示怪兽不会成为对手效果的对象，不会因对手的效果被破坏。\r\n②：此卡将被效果破坏的情况下，可将自己魔法与陷阱区域的１张其他卡破坏作为代替。','\r',char(13)),'\n',char(10)),'是否作为代替把其他的卡破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20932152,'快枪同步士','此卡可代替“同步士”协调作为同步素材。此卡作为同步素材的情况下，仅可使用于以“同步士”协调作为素材的同步怪兽的同步召唤。①：此卡可将1只手牌的怪兽送至墓地，来从手牌特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20934683,'圣徒・负疚',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：在自己・对手的主要阶段可以发动。将额外牌组的１只“圣徒”融合怪兽出示给对手，其等级每有４，就从自己手牌・场上将１张“罪宝”卡送至墓地（里侧表示卡则翻开确认）。然后，将所出示的怪兽视为融合召唤特殊召唤。\r\n②：在自己的主要阶段将墓地的此卡除外，以自己墓地的１只“圣徒”怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','从墓地特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20934852,'海晶少女 水葵・爱尔格诺特',replace(replace('水属性怪兽２只以上\r\n此卡名的②③效果１回合仅可各使用１次。\r\n①：只要此卡存在于额外怪兽区域，对手怪兽不可将其他怪兽选择为攻击对象。\r\n②：以自己场上的１只水属性怪兽与对手场上的１张卡为对象可以发动。将该卡放回手牌。\r\n③：在对手回合中，魔法・陷阱卡的效果在场上发动时可以发动。将１张装备于此卡的自己的“海晶少女”怪兽卡特殊召唤，将该发动的效果无效。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20936251,'源数风暴','①：自己场上有“原数天灵”怪兽存在的情况下可以发动。将对手场上的魔法・陷阱卡全部破坏，给予对手１０００伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20938824,'码丽丝＜兵＞三月兔',replace(replace('此卡名的①③效果1回合仅可各使用1次。\r\n①：此卡存在于手牌的情况下，在自己・对手的主要阶段可以发动。从自己手牌・墓地将此卡以外的1张“码丽丝”卡除外，将此卡特殊召唤。\r\n②：对手不可将连接端指向此卡的“码丽丝”连接怪兽作为效果的对象。\r\n③：此卡被除外的情况下，支付300LP，以自己除外状态的1只“码丽丝”怪兽为对象可以发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','','加入手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20939559,'暗之住人 暗影杀手','对手的怪兽卡区只存在守备表示怪兽的场合，此卡可直接攻击对手玩家。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20951752,'制裁者－伏尔泰尼斯','我方成功发动了反制陷阱卡的场合，可将我方场上的所有怪兽解放并发动。从手牌特殊召唤此卡。以此效果特殊召唤成功时，可破坏对手场上的卡牌破坏，其数量最多与被解放天使族怪兽的数量相同。','特殊召唤','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20960340,'水晶替身',replace(replace('①：对手怪兽的直接攻击宣言时，该怪兽的攻击力是我方LP或以上的场合，可发动。此卡发动后，变成攻击力与我方LP数值相同的效果怪兽（战士族、光、星４、攻？／守０），并以攻击表示特殊召唤至怪兽区。之后，将攻击对象转移至此卡。此卡也被视为陷阱卡。\r\n②：因此卡的效果特殊召唤而来的此卡因战斗被破坏的伤害计算后发动。给予对手相当於此卡攻击力数值的伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20985997,'破坏圈A','选择场上１只放有A计数物的怪兽并破坏，双方各受到１０００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20989253,'惊乐园家族脸',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：以装备了自己的“游乐设施”陷阱卡的对手场上的１只怪兽为对象可以发动此卡。将此卡视为装备卡，装备于该怪兽。\r\n②：获得装备怪兽的控制权。\r\n③：只要装备怪兽存在于自己的怪兽区域，攻击力上升５００，效果不可发动，也视为“惊乐园”怪兽。','\r',char(13)),'\n',char(10)),'「惊乐园家族脸」效果适用中','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(20994205,'号数觉醒','①：从额外牌组被特殊召唤的怪兽仅存在于对手场上的情况下可以发动。从额外牌组挑选４只“编号”超量怪兽（同阶级最多１只）。将１只“编号”的数值与该４只合计相同的“编号”超量怪兽视为超量召唤从额外牌组特殊召唤，将所挑选的怪兽全部重叠在该怪兽下面作为超量素材。只要以此效果特殊召唤的怪兽以表侧表示存在于自己场上，自己仅可特殊召唤“编号”超量怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21007444,'双刃之活人剑术','①：可以我方墓地的２只“六武众”怪兽为对象发动。以攻击表示特殊召唤该怪兽。以此效果特殊召唤的怪兽在此回合的结束阶段被破坏，我方受到相当于被破坏怪兽的攻击力合计数值的伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21011044,'影依的伪典',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：在自己・对手的主要阶段可以发动。将自己场上・墓地的怪兽作为融合素材除外，将1只“影依”融合怪兽融合召唤。然后，可将对手场上1只属性与以此效果特殊召唤的怪兽相同的怪兽送至墓地。以此效果特殊召唤的怪兽不可直接攻击。','\r',char(13)),'\n',char(10)),'是否选对手怪兽送至墓地？','「影依的伪典」效果适用中','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21015833,'隼骑士','①：此卡在１次战斗阶段中可以攻击２次。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21036656,'圆唤妖精 基克罗斯',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡召唤・特殊召唤的情况下，舍弃１张手牌可以发动。从牌组将“圆唤妖精 基克罗斯”以外的１只昆虫族・植物族协调加入手牌。\r\n②：此卡存在于墓地的状态下，昆虫族・植物族同步怪兽被特殊召唤的情况下可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21044178,'深渊潜伏者',replace(replace('等级４怪兽×２\r\n①：此卡持有水属性怪兽作为超量素材的情况下，自己场上的水属性怪兽的攻击力上升５００。\r\n②：在每个自己・对手回合中１次，去除此卡的１个超量素材可以发动。此回合，对手不可发动墓地的卡的效果。','\r',char(13)),'\n',char(10)),'效果发动限制','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21050476,'阿尔戈☆群星－热斗之帕耳忒',replace(replace('此卡名的①③效果1回合仅可各使用1次。\r\n①：在自己・对手回合中，向对手出示手牌的此卡可以发动。将自己场上的1张表侧表示“阿尔戈☆群星”永续陷阱卡放回手牌，将此卡特殊召唤。\r\n②：此卡的攻击力・守备力上升相当于自己场上的其他“阿尔戈☆群星”怪兽种类×700的数值。\r\n③：将场上的此卡除外可以发动。从手牌放置1张永续陷阱卡。以此效果放置的卡在放置的回合也可以发动。','\r',char(13)),'\n',char(10)),'特殊召唤','','放置','适用「阿尔戈☆群星－热斗之帕耳忒」的效果来发动','','','','','','','','','','','','');
INSERT INTO texts VALUES(21051146,'血魔导－炼狱的魔术师－','只要此卡以表侧表示存在于场上，每当我方或对手发动魔法卡时，在此卡上放置１个魔力计数物。取除放置在此卡上的任意数量的魔力计数物，破坏场上１只表侧表示的攻击力在取除数量×７００点以下的怪兽。','破坏','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21051977,'露果','我方主要阶段时可发动。从手牌将１只“松下小人”送入墓地，并从手牌特殊召唤此卡。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21056275,'武装蜂起',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：从手牌・牌组将１只攻击力１０００以下的昆虫族怪兽特殊召唤。以此效果从牌组特殊召唤的情况下，进而将自己场上的１只怪兽送至墓地。此卡发动后，直至回合结束时为止自己仅可特殊召唤昆虫族怪兽。\r\n②：此卡存在于墓地的状态下，自己场上表侧表示的昆虫族同步怪兽因战斗・效果被破坏的情况下，将此卡除外可以发动。从牌组将１张“一齐蜂起”加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21057444,'海晶少女 蓝宝女孩',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：从自己的墓地将１只“海晶少女”怪兽除外可以发动。从手牌将此卡特殊召唤。\r\n②：此卡作为水属性连接怪兽的连接素材被送至墓地的情况下可以发动。依自己场上的“海晶少女”怪兽的数量，从自己的牌组上面将卡送至墓地。以此效果将“海晶少女”卡送至墓地的情况下，进而给予对手相当于该“海晶少女”卡的数量×２００的伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21065189,'防火墙超越龙',replace(replace('等级4怪兽×2只以上\r\n①：超量召唤的此卡的攻击力上升相当于与此卡处于连接状态的连接怪兽连接标记数量×500的数值。②：去除此卡的2个超量素材，以自己墓地的1只连接4的电子界族连接怪兽为对象可以发动。将该怪兽特殊召唤至自己场上，使其与此卡变为连接状态。此效果发动后，直至回合结束时为止自己不可特殊召唤怪兽，不可直接攻击。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21070956,'牲祭的祭坛','可将我方场上的１只怪兽送入墓地并发动。回复相当于此怪兽的原本攻击力数值的LP。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21074344,'绿光之宣告者','①：对手发动魔法卡时，从手牌将此卡和１只天使族怪兽送至墓地可以发动。将该发动无效并破坏。','对手的魔法卡的发动无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21076084,'淘气仙星・康乃馨转世',replace(replace('①：将对手的手牌全部除外，对手抽相同张数的卡。\r\n②：将墓地的此卡除外，以自己墓地的１只“淘气仙星”怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21082832,'混沌形态','①：为使合计等级与仪式召唤的怪兽相等，将自己手牌・场上的怪兽解放，或作为解放的代替从自己墓地将“青眼白龙”或“黑魔导”除外，从手牌将１只“混沌”仪式怪兽仪式召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21088856,'华丽的密探－C','①：此卡召唤成功的场合发动。从对手额外牌组随机确认１张卡牌。是攻击力２０００或以上怪兽的场合，此卡攻击力上升１０００点。攻击力未满２０００怪兽的场合，我方回复相当于该攻击力数值的LP。','确认额外牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21105106,'sophia的影灵衣',replace(replace('以“影灵衣”仪式魔法卡降临\r\n此卡仅可以仪式召唤方式特殊召唤，且仪式召唤仅可使用自己场上种族各不相同的3只怪兽并从手牌进行。\r\n①：在自己・对手的主要阶段1，从手牌将此卡和1张“影灵衣”魔法卡舍弃可以发动。在该阶段期间，对手不可从额外牌组特殊召唤怪兽。\r\n②：此卡仪式召唤时可以发动（发动此效果的回合中，自己不可通常召唤・特殊召唤其他怪兽）。将此卡以外的、双方场上・墓地的卡全部除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21113684,'霸魔导士奥法魔术士',replace(replace('魔法师族同步怪兽＋魔法师族怪兽\r\n此卡仅可以融合召唤从额外牌组特殊召唤。\r\n①：此卡融合召唤成功的场合发动。在此卡放置２个魔力计数物。\r\n②：此卡的攻击力上升此卡的魔力计数物数量×１０００。\r\n③：１回合１次，可移除我方场上的１个魔力计数物，并从以下效果选择１个发动。\r\n●可以场上的１张卡牌为对象发动。该卡破坏。\r\n●我方从牌组抽取１张卡牌。','\r',char(13)),'\n',char(10)),'放置魔力计数物','场上1张卡破坏','抽1张卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21123811,'宇宙耀变龙',replace(replace('同步怪兽的协调＋协调以外的同步怪兽２只以上\r\n此卡仅可以同步召唤方式特殊召唤。\r\n①：将场上的此卡直至结束阶段为止除外，可从以下效果中选择１个发动。\r\n●对手发动魔法・陷阱・怪兽的效果时可以发动。将该发动无效并破坏。\r\n●对手召唤・反转召唤・特殊召唤怪兽之际可以发动。将其无效，将该怪兽破坏。\r\n●对手怪兽攻击宣言时可以发动。使该攻击无效，然后，结束战斗阶段。','\r',char(13)),'\n',char(10)),'发动无效并破坏','召唤无效并破坏','攻击无效','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21140872,'真红眼黑刃龙',replace(replace('“真红眼黑龙”＋战士族怪兽\r\n①：“真红眼”怪兽的攻击宣言时，以自己墓地的１只战士族怪兽为对象可以发动。将该怪兽视为攻击力上升２００的装备卡装备于此卡。②：以自己场上的卡为对象的卡的效果发动时，将自己场上的１张装备卡送至墓地可以发动。将该发动无效并破坏。③：此卡因战斗・效果被破坏的情况下可以发动。将原先装备于此卡的怪兽尽可能多地从自己的墓地特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21142671,'暗红新星',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次。\r\n①：场上存在等级8以上的龙族同步怪兽的情况下，此卡可从手牌特殊召唤。\r\n②：此卡作为同步素材被送至墓地的情况下，若该同步召唤使用了2只以上协调作为素材则可以发动。从牌组将1只恶魔族・炎属性怪兽以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21143940,'假面变换','①：以自己场上的1只“－英雄”怪兽为对象可以发动。确认该怪兽的属性，送至墓地。该怪兽因此效果从场上离开的情况下，进而从额外牌组将1只相同属性的“假面－英雄”怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21143941,'假面变换','①：以自己场上的1只“－英雄”怪兽为对象可以发动。确认该怪兽的属性，送至墓地。该怪兽因此效果从场上离开的情况下，进而从额外牌组将1只相同属性的“假面－英雄”怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21147203,'迷你玛利安',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从手牌将1张其他的卡除外可以发动。从手牌将此卡特殊召唤。\r\n②：将自己场上的1只等级4以下的表侧表示怪兽除外可以发动。从牌组将1只原本等级比除外的怪兽低1或2、原本种族・属性相同的怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'此卡特殊召唤','从牌组特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21155323,'巨人 果戈尔',replace(replace('此卡存在于墓地或以表侧表示存在于场上的场合，将被视为通常怪兽。以通常召唤的方式再次召唤场上表侧表示的此卡，此卡将视为效果怪兽并获得以下效果。\r\n●此卡的原始攻击力变为２１００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21159309,'救世龙','以此卡作为同步素材的情况下，仅可使用于“救世”怪兽的同步召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21175632,'圣女贞德','“大慈大悲修道女”＋“堕天使玛丽”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21179143,'爬虫妖产卵','①：从自己的墓地将1只“爬虫妖”怪兽除外可以发动。将2只“爬虫妖衍生物”（爬虫类族・地・星1・攻/守0）特殊召唤至自己场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21179144,'爬虫妖衍生物','由“爬虫妖产卵”等的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21187631,'幻变骚灵・拖拽格巫琳',replace(replace('协调+1只以上协调以外的怪兽\r\n此卡名的①②效果1回合仅可各使用1次。①：被特殊召唤的对手怪兽攻击宣言时，将自己场上的1只“幻变骚灵”怪兽放回持有者手牌可以发动。将该攻击无效。②：此卡被解放并被送至墓地的情况下可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21200905,'芬芳炽天使－茉莉',replace(replace('植物族怪兽２只\r\n此卡名的②效果１回合仅可使用１次。\r\n①：自己的LP多于对手的情况下，此卡及此卡连接端的植物族怪兽不会因战斗被破坏。\r\n②：解放此卡连接端的１只自己的怪兽可以发动。从牌组将１只植物族怪兽以守备表示特殊召唤。\r\n③：１回合１次，自己的LP恢复的情况下发动。从牌组将１只植物族怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21208154,'邪神 化身',replace(replace('此卡不可特殊召唤。\r\n仅可在解放自己场上的３只怪兽的情况下通常召唤。\r\n①：此卡召唤成功的情况下发动。从对手回合开始的２回合里，对手不可发动魔法・陷阱卡。\r\n②：此卡的攻击力・守备力变为相当于“邪神 化身”以外的场上攻击力最高的怪兽的攻击力＋１００的数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21219755,'破坏戒指','选择自己场上的１只表侧表示怪兽并破坏，双方均受到１０００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21223277,'圣骑士王阿托利斯',replace(replace('等级４“圣骑士”怪兽×２\r\n①：此卡超量召唤成功时，可以我方墓地最多３张“圣剑”装备魔法卡为对象发动（同名卡最多１张）。将该卡牌装备此卡。\r\n①：１回合１次，可移除此卡的１个超量素材并发动。挑选场上的魔法、陷阱卡破坏，其数量上限为我方场上的“圣剑”装备魔法卡数量。','\r',char(13)),'\n',char(10)),'装备','魔陷破坏','是否还要选择装备卡？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21225115,'古生代化石龙 骷髅暴龙',replace(replace('岩石族怪兽＋对手墓地中等级７以上的怪兽\r\n此卡仅可通过“化石融合”的效果从额外牌组中特殊召唤。\r\n①：计算此卡与对手怪兽进行战斗的伤害值前可以发动。该对手怪兽的攻击力与守备力互换，直至伤害步骤结束时为止。\r\n②：此卡攻击了守备表示的怪兽时，将对其造成战斗伤害，数值为此卡攻击力超出该怪兽守备力的部分。\r\n③：融合召唤的此卡在与对手怪兽进行的战斗中给对手的战斗伤害值翻倍。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21237481,'零式魔导粉碎机','通过从手牌舍弃１张魔法卡，给予对手生命５００点伤害。','伤害','是否现在使用「零式魔导粉碎机」的效果？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21239280,'骨鼠','为了对猫复仇雪恨，而复活成为不死族的老鼠。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21249921,'龙骑兵团骑士－圣雷牙枪',replace(replace('龙族协调＋协调以外的鸟兽族怪兽1只以上\r\n①：此卡同步召唤时，以自己墓地的1只等级3以下的龙族的“龙骑兵团”怪兽为对象可以发动。将该龙族怪兽视为装备魔法卡装备于此卡。\r\n②：1回合1次，将装备于此卡的、自己场上的1张装备卡送至墓地可以发动。此卡的攻击力直至回合结束时为止变为两倍。','\r',char(13)),'\n',char(10)),'装备','攻击变换','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21250202,'异色眼复面龙',replace(replace('←1 【灵摆】 1→\r\n①：仅以自己场上的１只“异色眼”灵摆怪兽为对象的对手效果发动的情况下，将在该回合的结束阶段发动。将灵摆区域的此卡特殊召唤，从自己的额外牌组（表侧）将“异色眼复面龙”以外的１只“异色眼”灵摆怪兽放在自己的灵摆区域。\r\n【怪兽效果】\r\n①：在每个自己・对手回合中１次，以被从额外牌组特殊召唤的１只表侧表示怪兽为对象可以发动。将该怪兽的效果直至回合结束时为止无效。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21254443,'星遗物之引导','①：从手牌及自己场上的表侧表示怪兽中，将1只“星遗物”怪兽除外，以自己墓地的2只怪兽为对象可以发动。将该怪兽特殊召唤。以此效果特殊召唤的怪兽在此回合不可攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21263083,'苍白兽','有着一身青白色皮肤，让人感觉毛骨悚然的谜样怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21281085,'魔轰神勒邪则步',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的②效果1回合仅可使用1次。\r\n①：在每个自己・对手的主要阶段可以发动1次。解放自己场上任意数量的“魔轰神”怪兽，依其数量获得对手场上的表侧表示怪兽的控制权。以此效果获得控制权的怪兽的效果无效化。\r\n②：此卡存在于墓地的情况下，以自己墓地的1张其他“魔轰神”卡为对象可以发动。将此卡放回额外牌组，将对象卡加入手牌。','\r',char(13)),'\n',char(10)),'得到控制权','回收','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21291696,'电极兽 阳离子',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤的情况下可以发动。从自己牌组・墓地将1只“电极兽 阴离子”加入手牌。然后，可进行1只等级4以下的雷族怪兽的召唤。此效果发动后，直至回合结束时为止自己从额外牌组仅可特殊召唤光属性超量怪兽。\r\n②：以自己场上的1只其他的雷族怪兽为对象可以发动。将此卡的等级直至回合结束时为止改成与该怪兽的等级相同。','\r',char(13)),'\n',char(10)),'检索「电极兽 阴离子」并进行召唤','改变等级','是否进行召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21293424,'航母军贯－白鱼型特务舰',replace(replace('等级４怪兽×２\r\n此卡名的①效果１回合仅可使用１次。①：此卡超量召唤成功的情况下可以发动。根据作为该超量召唤的素材的怪兽，适用以下效果。\r\n●“舍利军贯”：自己从牌组抽１张。\r\n●“白鱼军贯”：从牌组将１张“军贯”魔法・陷阱卡加入手牌。\r\n②：只要场地区域有卡以表侧表示存在，从额外牌组被特殊召唤的自己的“军贯”怪兽不会被对手的效果破坏，攻击力上升相当于其原本守备力的数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21296383,'独角鸟','可将此卡及我方场上的１只表侧表示怪兽从游戏中除外，并从我方墓地选择１只持有等级为该原本等级合计或以下的同步怪兽发动。从墓地特殊召唤被选择怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21296502,'卡通黑魔导',replace(replace('①：此卡在召唤・反转召唤・特殊召唤的回合不可攻击。\r\n②：自己场上存在“卡通世界”，且对手场上不存在卡通怪兽的情况下，此卡可直接攻击。\r\n③：1回合1次，从手牌将1张“卡通”卡舍弃，可从以下效果中选择1个发动。\r\n●从牌组将“卡通黑魔导”以外的1只卡通怪兽无视召唤条件特殊召唤。\r\n●从牌组将1张“卡通”魔法・陷阱卡加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','牌组检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21297224,'歇斯底里天使','可解放我方场上的２只怪兽并发动。我方回复１０００LP。','LP回复','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21313376,'编号14 强欲的死神犬',replace(replace('等级５怪兽×２\r\n①：只要此卡存在于怪兽区，因对手效果发生的对我方的效果伤害将由对手代替承受。\r\n②：此卡因战斗破坏对手怪兽并送入墓地时，可移除此卡的１个超量素材并发动。破坏所有持有攻击力是被破坏之该怪兽原本攻击力或以下的场上怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21323861,'酸性风暴','破坏场上所有表侧表示的机械族怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21340051,'野猪士兵','此卡召唤成功时，破坏此卡。只要对手场上存在怪兽的场合，此卡的攻击力下降１０００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21347668,'皮尔莉・困倦回忆','①：此回合仅１次，自己受到的战斗・效果伤害变为０。进而可适用以下效果。●挑选１张自己的手牌舍弃，从牌组将１只等级１的“皮尔莉”怪兽特殊召唤。②：持有此卡作为素材的“皮尔莉”超量怪兽获得以下效果。●在对手的准备阶段可以发动。自己从牌组抽１张。','是否从牌组特殊召唤？','抽1张卡（皮尔莉瞌睡回忆）','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21347810,'彩虹花','此卡可直接攻击对手玩家。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21350571,'幻兽之角','可选择我方场上的１只兽族、兽战士族怪兽并发动此卡。此卡被视为上升攻击力８００点的装备卡，装备我方的兽族、兽战士族怪兽。装备怪兽因战斗破坏对手怪兽并将其送入墓地时，从我方牌组抽取１张卡牌。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21351206,'焰圣骑士－奥吉尔','此卡名的①②效果１回合仅可各使用１次。①：此卡召唤・特殊召唤成功的情况下可以发动。从牌组中将１只“焰圣骑士－奥吉尔”以外的战士族・炎属性怪兽或１张“圣剑”卡送至墓地。②：此卡存在于墓地的情况下，以自己场上的１只战士族怪兽为对象可以发动。将此卡视为装备卡装备于自己的该怪兽。③：此卡装备的怪兽不会因效果被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21362970,'兽击士','１回合１次，可舍弃１张手牌并发动。从牌组特殊召唤１只“摩迦”。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21364070,'魔妖仙兽 独眼群主',replace(replace('←3 【灵摆】 3→\r\n此卡名的①②灵摆效果１回合各只能使用１次。\n①：可以我方灵摆区的１张“妖仙兽”卡片为对象发动。直到回合结束，其灵摆刻度变为１１。本回合，我方特殊召唤的只能是“妖仙兽”怪兽。\n②：在我方结束阶段发动。将此卡移回拥有者的手牌。\r\n【怪兽效果】\r\n此卡只能通过灵摆召唤来特殊召唤。\n①：如果此卡成功召唤或特殊召唤，则可以对手场上的１张卡为目标发动。将该卡移回其拥有者的手牌。\n②：此卡在怪兽区期间，每当有此卡以外场上的卡片因我方的卡片效果回到手牌或卡组，均发动。我方场上所有“妖仙兽”怪兽的攻击力上升５００点。\n③：在特殊召唤了此卡的回合结束阶段发动。将此卡移回其拥有者的手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21368273,'玛那桃圆乡・多利洛斯歌都',replace(replace('协调＋协调以外的怪兽１只以上\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡同步召唤的情况下，以自己墓地的１只等级２协调为对象可以发动。将该怪兽特殊召唤。以此效果特殊召唤的怪兽的效果无效化。\r\n②：以自己场上任意数量的协调为对象可以发动。将该怪兽的等级改成２。此回合，自己从额外牌组仅可特殊召唤同步怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21368442,'超元特防队 重力微子侠','此卡名的①效果１回合仅可使用１次。①：此卡召唤・特殊召唤成功的情况下可以发动。从牌组将１张“超元特防队 重力微子侠”以外的“超元特防队”卡加入手牌。②：只要此卡存在于怪兽区域，自己的“超元特防队”怪兽正面的对手怪兽离开场上的情况下，将其除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21377582,'真龙剑皇 至尊行者 完灵',replace(replace('要以表侧表示上级召唤此卡的情况下，可解放自己场上的永续魔法・永续陷阱卡来作为怪兽的代替。\r\n①：此卡不受种类（怪兽・魔法・陷阱）与为上级召唤此卡而解放的卡原本种类相同的效果影响。\r\n②：此卡是被上级召唤的情况下，在每个自己・对手回合中1次，从自己墓地将1张永续魔法・永续陷阱卡除外，以场上的1张其他卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'解放魔法·陷阱卡上级召唤','是否继续选择魔法·陷阱卡解放？','场上卡破坏','解放怪兽卡上级召唤','解放魔法卡上级召唤','解放陷阱卡上级召唤','','','','','','','','','','');
INSERT INTO texts VALUES(21390858,'凭依装着－达尔克','①：此卡可将自己场上的１只表侧表示的“暗灵使 达尔克”和１只暗属性怪兽送至墓地，来从手牌・牌组特殊召唤。②：以此卡的①方法特殊召唤成功时可以发动。从牌组将１只等级３・４的魔法师族・光属性怪兽加入手牌。③：以此卡的①方法特殊召唤的此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予战斗伤害。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21414674,'日珥手','①：我方场上存在有“魔术手”“火焰手”“冰冻手”中的任１卡牌的场合，此卡可从手牌特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21417692,'暗黑精灵','此卡必须支付１０００LP才可攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21419436,'破械神双 拉基安',replace(replace('包含恶魔族怪兽在内的怪兽2只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：对手将怪兽以表侧表示特殊召唤的情况下，以其中1只为对象可以发动。将自己场上的1只恶魔族怪兽破坏，将对象怪兽的效果直至回合结束时为止无效。\r\n②：自己场上存在连接4以上的“破械”连接怪兽，且场上怪兽的效果发动时，将墓地的此卡除外可以发动。将发动该效果的怪兽破坏。','\r',char(13)),'\n',char(10)),'无效','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21420702,'烈焰加农炮三戟式','可将我方场上１张表侧表示的“烈焰加农炮”送入墓地并发动。此外，可选择对手场上的１只怪兽并发动。从手牌将１只炎族怪兽送入墓地，破坏被选择的对手怪兽，给予对手生命５００点伤害。发动此效果的回合，我方怪兽不可攻击。','对手场上存在的1只怪兽破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21435914,'冥界浊龙 恸河龙',replace(replace('暗属性协调＋１只协调以外的龙族怪兽\r\n①：此卡不会因战斗被破坏。②：此卡战斗破坏对手怪兽并将其送至墓地时可以发动。此卡可继续再攻击对手怪兽仅１次。③：在自己的准备阶段，以对手场上的１只表侧表示怪兽为对象可以发动。将该怪兽的攻击力改成一半，依其数值给予对手伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21438286,'恶魔之杖',replace(replace('仅限装备我方场上的怪兽。\r\n此卡牌名的①②效果１回合只可各使用１次。\r\n①：在我方主要阶段可发动。直至回合结束时，对手场上所有怪兽的攻击力下降装备怪兽之攻击力一半的数值。\r\n②：装备于怪兽的此卡被送入墓地的场合，可支付１０００LP发动。将此卡返回至手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21441617,'自鸣天琴・骸骨谐谑曲','此卡名的效果1回合仅可使用1次。①：将墓地的此卡除外，以自己墓地的1只“自鸣天琴・骸骨谐谑曲”以外的“自鸣天琴”怪兽为对象可以发动。将该怪兽特殊召唤。此效果发动后，直至回合结束时为止自己仅可特殊召唤暗属性怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21452275,'芬芳炉',replace(replace('①：只要反转的此卡存在于怪兽区域，此卡不会因战斗被破坏。\r\n②：反转的此卡存在于怪兽区域的情况下，在自己・对手的结束阶段发动。自己恢复５００LP。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21454943,'念力指挥官','①：每次自己的念动力族怪兽与对手怪兽进行战斗，从伤害步骤开始时到伤害计算前为止仅有1次，以该1只对手怪兽为对象，支付100的倍数的LP可以发动（最多500）。进行该战斗的对手怪兽的攻击力・守备力直至回合结束时为止，下降所支付的数值。','攻守下降','请选择要支付的基本分','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21466326,'残骸爆破','自己墓地的卡有３０张以上的情况下可以发动。给予对手LP３０００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21481146,'闪光屏障－光辉之力','对手场上存在有３只或以上攻击表示怪兽的场合，在对手怪兽的攻击宣言时可发动。破坏对手场上的所有攻击表示怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21488686,'超能治愈','我方回复我方场上念动力族怪兽数量×１０００LP。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21495657,'宝龙星－源质负屃',replace(replace('←1 【灵摆】 1→\r\n①：自己仅可灵摆召唤“龙星”怪兽以及“源质”怪兽。此效果不会被无效化。\r\n【怪兽效果】\r\n此卡名的怪兽效果1回合仅可使用1次。①：此卡灵摆召唤或从牌组的特殊召唤成功的情况下，以“宝龙星-源质负屃”以外的自己场上的1只“龙星”怪兽或“源质”怪兽为对象可以发动。此回合，该表侧表示怪兽视为协调。发动了此效果的此卡从场上离开的情况下放回持有者牌组的最下面。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21496848,'禁咒仪・四面体巨魔','以“咒仪”仪式魔法卡降临。①：１回合１次，宣言卡的种类（怪兽・魔法・陷阱）可以发动。对手可舍弃１张手牌将此效果无效。不舍弃的情况下，双方各从牌组将１张被宣言种类的卡送至墓地。','宣言卡种送至墓地','怪兽卡','魔法卡','陷阱卡','是否要丢弃手牌？','请宣言卡的种类','','','','','','','','','','');
INSERT INTO texts VALUES(21501505,'暗迁士 黑晶戈贡',replace(replace('等级4怪兽×2\r\n①：仅以场上的1张卡为对象的其他魔法・陷阱・怪兽的效果发动时，去除此卡的1个超量素材，以场上1张能成为其正确对象的其他卡为对象可以发动。将该效果的对象移换至能成为其正确对象的该卡。','\r',char(13)),'\n',char(10)),'对象转移','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21502796,'光道猎犬 莱可','①：此卡反转的情况下发动。可挑选场上的1张卡破坏。从自己牌组上面将3张卡送至墓地。','破坏','是否要破坏一张卡？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21507589,'鱼和交换','可弃置１张手牌，选择我方从游戏中被除外的２只鱼族・海龙族・水族怪兽来发动此卡。将所选择怪兽加入到手牌中。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21516908,'高速疾行机人 马赫羽子板',replace(replace('协调+1只以上协调以外的怪兽\r\n此卡名的②效果1回合仅可使用1次。①：解放此卡可以发动。场上所有表侧表示怪兽的等级直至回合结束时为止上升1。此效果在对手回合中也可以发动。②：此卡存在于墓地，自己场上有“疾行机人”协调存在的情况下可以发动。将此卡特殊召唤。此效果发动后，直至回合结束时为止自己仅可特殊召唤风属性怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21521304,'编号39 希望皇极越霍普',replace(replace('等级６怪兽×２\r\n此卡名在规则上也视为“希望皇霍普”卡。①：此卡超量召唤成功的情况下发动。对手场上所有怪兽的攻击力变为０。②：１回合１次，去除此卡的１个超量素材，以自己场上的１只超量怪兽和自己墓地的１只“希望皇霍普”怪兽为对象可以发动。将该自己场上的超量怪兽除外，将该墓地的怪兽特殊召唤。然后自己恢复１２５０LP。此效果在对手回合中也可以发动。','\r',char(13)),'\n',char(10)),'攻击力变成0','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21522601,'魔女工艺掌门・玻璃匠薇儿',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：自己的魔法师族怪兽与对手怪兽进行战斗的自己・对手回合的伤害计算时可以发动。向对手出示手牌任意数量的卡名不同的魔法卡，该自己的怪兽的攻击力・守备力直至回合结束时为止，上升所出示数量×1000的数值。\r\n②：在自己・对手回合中，从手牌将1张魔法卡舍弃可以发动。对手场上的所有表侧表示怪兽的效果直至回合结束时为止无效化。','\r',char(13)),'\n',char(10)),'提升攻击','无效效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21522602,'魔女工艺掌门・玻璃匠薇儿',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：自己的魔法师族怪兽与对手怪兽进行战斗的自己・对手回合的伤害计算时可以发动。向对手出示手牌任意数量的卡名不同的魔法卡，该自己的怪兽的攻击力・守备力直至回合结束时为止，上升所出示数量×1000的数值。\r\n②：在自己・对手回合中，从手牌将1张魔法卡舍弃可以发动。对手场上的所有表侧表示怪兽的效果直至回合结束时为止无效化。','\r',char(13)),'\n',char(10)),'提升攻击','无效效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21522603,'魔女工艺掌门・玻璃匠薇儿',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：自己的魔法师族怪兽与对手怪兽进行战斗的自己・对手回合的伤害计算时可以发动。向对手出示手牌任意数量的卡名不同的魔法卡，该自己的怪兽的攻击力・守备力直至回合结束时为止，上升所出示数量×1000的数值。\r\n②：在自己・对手回合中，从手牌将1张魔法卡舍弃可以发动。对手场上的所有表侧表示怪兽的效果直至回合结束时为止无效化。','\r',char(13)),'\n',char(10)),'提升攻击','无效效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21524779,'雷电妈妈','①：1回合1次，在自己的主要阶段可以发动。进行“雷电妈妈”以外的、手牌的1只雷族・光属性・等级4怪兽的召唤。','召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21546416,'武装龙闪电 LV5','此卡名的②③效果１回合仅可各使用１次。①：此卡只要存在于场上・墓地，卡名视为“武装龙 LV5”。②：从手牌将１只怪兽送至墓地可以发动。将场上的此卡送至墓地，从手牌・牌组将１只等级７以下的“武装龙”怪兽特殊召唤。③：此卡为发动龙族怪兽的效果而被送至墓地的情况下可以发动。从牌组将１只等级５以上的龙族・风属性怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21558682,'防御软泥','对手怪兽攻击我方怪兽时，我方场上有表侧表示的“复活软泥”存在的场合，可令其攻击对象转移为“复活软泥”。','攻击对象转移','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21565445,'海皇子 尼普邃渊',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：从牌组将“海皇子 尼普邃渊”以外的１只“海皇”怪兽送至墓地可以发动。从牌组将１张“海皇子 尼普邃渊”以外的“海皇”卡加入手牌。\r\n②：此卡为发动水属性怪兽的效果被送至墓地的情况下，以自己墓地“海皇子 尼普邃渊”以外的１只“海皇”怪兽为对象发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'牌组检索','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21570001,'新世坏界','此卡名的卡１回合仅可发动１张。①：以自己场上的１只表侧表示怪兽为对象可以发动。将该怪兽破坏，将１只原本种族・属性与该怪兽不同，且等级低于该怪兽原本等级的怪兽从牌组以守备表示特殊召唤。以此效果特殊召唤的怪兽的效果无效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21576077,'食光之辉龙机巧','此卡名的①②效果1回合仅可各使用1次。①：以自己墓地的1只“龙机巧”怪兽为对象可以发动。将该怪兽加入手牌。②：将墓地的此卡除外，以自己场上的1只“龙机巧”怪兽为对象可以发动。该怪兽的攻击力直至对手回合结束时为止上升2000。此效果在此卡被送至墓地的回合不可发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21579049,'白之循环礁',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n \r\n①：以自己场上的1只鱼族怪兽为对象可以发动。将该鱼族怪兽破坏，从牌组将1只其同名怪兽加入手牌。此卡发动时自己场上存在鱼族同步怪兽的情况下，也可不加入手牌而是改为将其特殊召唤。 \r\n②：将墓地的此卡除外，以自己墓地的2只鱼族同名怪兽为对象可以发动。将该2只中的1只放回牌组最下面，另1只特殊召唤。','\r',char(13)),'\n',char(10)),'是否特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21593977,'处刑人－摩修罗',replace(replace('此卡名的效果在１个回合中仅可使用１次。\r\n①：此卡从怪兽区域被送至墓地时可以发动。此回合中，自己仅可从手牌中发动１次陷阱卡。','\r',char(13)),'\n',char(10)),'适用「处刑人－摩修罗」的效果来发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21597117,'英雄拜访','①：可在对手怪兽的攻击宣言时发动。对手随机挑选我方的１张手牌。该卡牌为怪兽的场合，特殊召唤至我方场上，不是的场合送入墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21598948,'怪兽箱',replace(replace('此卡的控制者在每个自己的准备阶段，支付500LP或将此卡破坏。\r\n①：对手怪兽攻击宣言时发动。掷1次硬币，猜正反。猜中的情况下，只要此卡存在于魔法与陷阱区域，该攻击怪兽的攻击力直至战斗阶段结束时为止变为0。','\r',char(13)),'\n',char(10)),'攻击变换','是否要支付500基本分维持「怪兽箱」？','正面','反面','请选择硬币的正反面','','','','','','','','','','','');
INSERT INTO texts VALUES(21607304,'地中骇界邪龙 飞雷第勒尼安',replace(replace('此卡名的③效果1回合仅可使用1次。\r\n①：自己场上的表侧表示怪兽变为里侧表示时，若自己场上不存在表侧表示怪兽则可以发动。从手牌将此卡以守备表示特殊召唤。\r\n②：在自己的主要阶段可以发动。将此卡改成里侧守备表示（1回合仅1次）。\r\n③：此卡反转的情况下，以对手场上的1只里侧表示怪兽为对象可以发动。获得该怪兽的控制权直至下个自己的结束阶段为止。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21615956,'炎狱护卫者','能自由操纵火焰的炎狱护卫战士。会制造灼热防护将敌人的攻击反弹回去。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21620076,'痛苦绘制者','①：此卡只要存在于怪兽区域，卡名视为“僵尸带菌者”。②：１回合１次，以自己场上此卡以外的最多２只不死族怪兽为对象可以发动。该怪兽的等级直至回合结束时为止变为２。将适用此效果的怪兽作为同步素材的情况下，仅可使用于不死族怪兽的同步召唤。','等级变换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21623008,'闪刀术式－矢量冲击波','①：自己的主要怪兽区域没有怪兽存在的情况下可以发动。从双方的牌组上面将2张卡送至墓地。然后，自己墓地存在3张以上的魔法卡的情况下，可将额外怪兽区域的所有对手怪兽放回持有者的牌组。','是否让额外怪兽区域的对手怪兽回到牌组？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21636650,'奇迹的残照','①：可以１只在此回合当中因战斗被破坏并被送入我方墓地的怪兽为对象发动。特殊召唤该怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21637210,'防火墙龙・奇点',replace(replace('效果怪兽3只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己・对手回合中，以自己场上・墓地的怪兽的种类（仪式・融合・同步・超量）数量为上限，以对手场上・墓地的卡为对象可以发动。将该卡放回手牌。此卡的攻击力上升所放回数量×500的数值。\r\n②：此卡连接端的怪兽，因战斗被破坏的情况下，或被送至墓地的情况下，以自己墓地的1只电子界族怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'对方卡回到手牌','墓地电子界族怪兽特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21637211,'防火墙龙・奇点',replace(replace('效果怪兽3只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己・对手回合中，以自己场上・墓地的怪兽的种类（仪式・融合・同步・超量）数量为上限，以对手场上・墓地的卡为对象可以发动。将该卡放回手牌。此卡的攻击力上升所放回数量×500的数值。\r\n②：此卡连接端的怪兽，因战斗被破坏的情况下，或被送至墓地的情况下，以自己墓地的1只电子界族怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'对方卡回到手牌','墓地电子界族怪兽特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21637502,'百臂无形手 布瑞撕',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：在抽牌阶段以外有卡加入对手手牌的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：在自己的主要阶段可以发动。随机确认对手的1张手牌。其为怪兽的情况下，可将该怪兽特殊召唤至自己场上。\r\n③：此卡与怪兽进行战斗的情况下，该2只不会因该战斗被破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','特殊召唤','是否特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21639276,'怒刹帝利・准备','此卡名的①②效果１回合仅可各使用１次。①：在自己・对手回合可以发动。从手牌的怪兽及被除外的自己的怪兽中，挑选１只“怒刹帝利”怪兽特殊召唤。②：此卡已存在于魔法与陷阱区域的状态下，对手发动陷阱卡的效果的情况下，自己场上如果存在“怒刹帝利”怪兽则可以发动。确认对手的手牌，从其中挑选１张，以里侧表示除外。','特殊召唤','手牌除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21648584,'急袭猛禽－战备','①：此回合，自己场上的“急袭猛禽”怪兽不会因战斗被破坏。②：自己的墓地有“急袭猛禽”怪兽存在的情况下，将墓地的此卡除外可以发动。此回合，自己受到的全部伤害变为0。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21663205,'守墓的神职',replace(replace('此卡牌名的效果１回合只可使用１次。\r\n①：此卡召唤、反转召唤、特殊召唤成功的场合，可以我方墓地１只等级４的“守墓”怪兽为对象发动。以表侧攻击表示或里侧守备表示特殊召唤该怪兽。此效果不受“王家长眠之谷－死灵谷”的效果影响。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21672573,'帝尸神官','只要此卡以表侧表示存在于我方场上，当我方成功上级召唤怪兽时，双方玩家可选择各自墓地中的１张卡牌将其放回至牌组的最上方。','返回牌组','是否要选择墓地一张卡回到牌组最上面？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21677871,'黄金荣耀－启动引擎','①：对手召唤・特殊召唤怪兽的情况下，以该１只怪兽为对象可以发动。从牌组将３只“黄金荣耀”怪兽出示给对手，对手从其中随机挑选１只。将该１只怪兽特殊召唤至自己场上，剩余的放回牌组。然后，将对象怪兽破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21686473,'DDD 命运王零拉普拉斯',replace(replace('←1 【灵摆】 1→\r\n此卡名的灵摆效果1回合仅可使用1次。\n①：在自己的主要阶段可以发动。从自己额外牌组（表侧）将“DDD 命运王零拉普拉斯”以外的1只“DDD”灵摆怪兽加入手牌。\r\n【怪兽效果】\r\n①：此卡可通过解放自己场上的1只“DDD”怪兽来从手牌特殊召唤。\n②：此卡与对手怪兽进行战斗的伤害计算前可以发动。此卡的攻击力直至伤害步骤结束时为止，变为该对手怪兽原本攻击力的两倍。\n③：此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。\n④：此卡1回合仅1次，不会因战斗被破坏。在此之际，自己受到的战斗伤害变为0。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21698716,'宝玉兽 蓝钴鹰',replace(replace('①：１回合１次，可以我方场上的１张“宝玉兽”卡牌为对象发动。将该我方的“宝玉兽”卡牌返回至持有者牌组的最上方。\r\n②：表侧表示的此卡在怪兽区被破坏的场合，可不送入墓地被视作永续魔法卡以表侧表示放置在我方的魔法与陷阱区域。','\r',char(13)),'\n',char(10)),'破坏时放置魔法陷阱区','返回牌组','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21702241,'反目随从','装备怪兽的控制权转移时，给予装备怪兽控制者装备怪兽原本攻击力数值的伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21715135,'我我我学园的紧急联络网','此卡名的卡１回合仅可发动１张，发动此卡的回合中，自己不可进行超量召唤以外的特殊召唤。①：仅有对手场上才存在怪兽的情况下可以发动。从牌组将１只“我我我”怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21720439,'神艺时势－血统－',replace(replace('此卡名的①②效果1回合仅可各使用1次，发动此效果的回合中，自己从额外牌组仅可特殊召唤融合怪兽。\r\n①：对手场上的怪兽数量多于自己场上的怪兽的情况下可以发动。从牌组将自己场上不存在同名卡的1只“神艺”怪兽以守备表示特殊召唤。\r\n②：此卡为发动“神艺学都”的效果被送至墓地的情况下可以发动。将自己墓地・除外状态的1张“神艺”陷阱卡加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','回收陷阱','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21723081,'X・Y・Z 高能加农炮',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：“XYZ－龙型加农炮”或记载有其卡名作为融合素材的融合怪兽存在于自己场上的情况下，根据此效果的发动回合，可发动以下效果。\r\n●自己回合：以自己除外状态的１只联合怪兽为对象可以发动。将该怪兽放回牌组最下面，自己抽１张。\r\n●对手回合：将任意张数的手牌舍弃，依其数量以对手场上的卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21727231,'兽带斗士“收割者”伐姆','此卡名的①②效果１回合仅可各使用１次。①：以自己墓地的１只“兽带斗士”怪兽或水族怪兽为对象可以发动。从手牌将此卡特殊召唤，将对象怪兽视为装备卡装备于此卡。②：在对手回合中，以自己的魔法与陷阱区域的１张“兽带斗士”卡和对手场上的１张卡为对象可以发动。将该卡放回持有者的手牌。③：装备此卡的“兽带斗士”怪兽的攻击力上升７００，获得此卡名的②效果。','','双方卡回到手牌（兽带斗士“跃鱼”霹雳一）','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21744288,'魔女工艺・铁匠舒蜜塔',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己・对手的主要阶段，解放此卡，从手牌将1张魔法卡舍弃可以发动。从牌组将“魔女工艺・铁匠舒蜜塔”以外的1只“魔女工艺”怪兽特殊召唤。\r\n②：将墓地的此卡除外可以发动。从牌组将“魔女工艺・铁匠舒蜜塔”以外的1张“魔女工艺”卡送至墓地。','\r',char(13)),'\n',char(10)),'特殊召唤','送至墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21767650,'水精鳞－深渊鲵鱼兵',replace(replace('可将墓地的此卡从游戏中除外，并从以下效果中选择１个发动。\r\n●使我方场上冠有“水精鳞”之名的所有怪兽等级上升１级。\r\n●使我方场上冠有“水精鳞”之名的所有怪兽等级上升２级。','\r',char(13)),'\n',char(10)),'等级上升','等级全部上升1星','等级全部上升2星','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21768554,'集体催眠','我方场上存在有冠有“外星人”之名的怪兽的场合，最多可选择３只对手场上放置有A计数物的怪兽并发动此卡。获得放置有A计数物的该怪兽的控制权。此卡在发动回合的结束阶段时被破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21770260,'软泥增殖炉','每次于我方的准备阶段，在我方场上以攻击表示特殊召唤１只“史莱姆衍生物”（每次于我方的准备阶段，在我方场上以攻击表示特殊召唤１只“史莱姆怪兽衍生物”（水族・水・１星・攻／守５００）。只要此卡存在于场上，我方不可召唤・反转召唤・特殊召唤除“史莱姆怪兽衍生物”以外的怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21770261,'史莱姆怪兽衍生物','由“软泥增殖炉”等的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21770839,'异色眼幻灵龙',replace(replace('←0 【灵摆】 0→\r\n此卡名的灵摆效果１回合仅可使用１次。\n①：舍弃１张手牌可以发动。从自己的额外牌组将１只表侧的龙族灵摆怪兽加入手牌。\r\n【怪兽效果】\r\n此卡名的①②怪兽效果１回合仅可各使用１次。\n①：自己的灵摆区域存在２张卡，且自己的额外牌组存在表侧的“异色眼”灵摆怪兽的情况下可以发动（发动此效果的回合中，自己不可灵摆召唤）。从手牌将此卡特殊召唤。\n②：此卡攻击对手怪兽的伤害计算时可以发动。该对手怪兽的攻击力仅在该伤害计算时，下降相当于自己额外牌组的表侧灵摆怪兽数量×１０００的数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21772453,'花札卫－枫与鹿－',replace(replace('此卡不可通常召唤。\r\n解放了我方场上１只除“花札卫－枫与鹿－”以外的“花札卫”怪兽的场合可特殊召唤。\r\n①：此卡特殊召唤成功的场合发动。我方从牌组抽取１张卡牌，并双方相互确认。该卡是“花札卫”怪兽的场合，可挑选对手场上的１张魔法・陷阱卡并破坏。若不是的场合，将该卡送入墓地。','\r',char(13)),'\n',char(10)),'抽牌','是否选对手场上1张魔法·陷阱卡破坏？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21785144,'光道龙 格拉古尼斯','此卡的攻击力、守备力，上升以我方墓地中冠有“光道”之名的怪兽种类×３００点。此卡攻击守备表示怪兽时，若攻击力超过该守备力，给予对手生命相当于该差值的战斗伤害。此外，在每次我方结束阶段时发动。从我方牌组的上方依序将３张卡牌送入墓地。','从牌组送3张卡去墓地','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21790410,'甲虫装机 蜈蚣',replace(replace('①：１回合１次，我方主要阶段时可发动。从我方手牌、墓地挑选１只“甲虫装机”怪兽，视为装备卡装备此卡。\r\n②：此卡存在于我方场上，且装备此卡的卡牌被送入我方墓地的场合可发动。从牌组将１张“甲虫装机”卡牌加入手牌。\r\n③：将此卡视为装备卡装备的怪兽，其等级上升３级。','\r',char(13)),'\n',char(10)),'装备','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21817254,'大雷电球','在地面上滚动游转、朝周围发出电击的球。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21830679,'时脉飞龙','此卡名的效果1回合仅可使用1次。①：此卡召唤・特殊召唤成功的情况下可以发动。将此卡的攻击力改成一半，将1只“时脉衍生物”（电子界族・风・星1・攻/守0）特殊召唤至自己场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21830680,'时脉衍生物','由「时脉飞龙」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21831848,'我我我抽牌','①：将自己墓地３只“我我我”怪兽除外可以发动。自己从牌组抽２张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21834870,'天威无双之拳','①：自己场上有效果怪兽以外的表侧表示怪兽存在，怪兽的效果・魔法・陷阱卡发动时可以发动。将该发动无效。②：被放置的此卡因对手的效果被破坏的情况下可以发动。从额外牌组将1只效果怪兽以外的怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21840375,'隐藏的魔导书','此卡仅限我方回合可发动。选择我方墓地存在的２张魔法卡加入牌组并洗牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21843307,'复制骑士','等级４或以下的战士族怪兽被召唤至我方场上时可发动。此卡发动后，变成与该被召唤怪兽相同卡牌名、等级的通常怪兽（战士族、光、攻／守０），特殊召唤至怪兽区。此卡也被视作作陷阱卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21844576,'元素－英雄 羽毛人','操控风、拥有翱翔于天际之翼的元素－英雄。用来自天空的一击、羽翼破乱制裁恶行。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21844577,'元素－英雄 羽毛人','操控风、拥有翱翔于天际之翼的元素－英雄。用来自天空的一击、羽翼破乱制裁恶行。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21846145,'绑架',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：以对手场上的1只表侧表示怪兽为对象可以发动。从牌组・额外牌组将1只原本种族、原本属性、原本等级・阶级・连接均与对象怪兽相同的怪兽除外，获得对象怪兽的控制权。以此效果将原本卡名和对象怪兽相同的怪兽除外的情况下，以此效果获得控制权的怪兽的效果无效化。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21848500,'码丽丝＜后＞红心密匿',replace(replace('包含“码丽丝”怪兽在内的怪兽3只\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己・对手回合中，以自己除外状态的1张“码丽丝”卡为对象可以发动（此卡连接端存在怪兽的情况下，此效果的发动和效果不会被无效化）。将该卡放回牌组，将场上的1张卡除外。\r\n②：此卡被除外的情况下，支付900LP可以发动。将此卡的攻击力改成两倍并特殊召唤。','\r',char(13)),'\n',char(10)),'回收并除外','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21858819,'编号XX 无限暗黑霍普',replace(replace('等级１０怪兽×２只或以上\r\n此卡牌名的①②效果１回合只可各使用１次。\r\n①：我方或对手怪兽因战斗被破坏并送入墓地时，可移除此卡的１个超量素材，并以该１只怪兽为对象发动。以守备表示特殊召唤该怪兽至我方场上。\r\n②：可以我方场上１只除此卡以外之特殊召唤而来的表侧表示怪兽为对象发动。我方回复相当于该怪兽原本攻击力数值的LP。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21861412,'磁通超导铠骑',replace(replace('等级5以上的地属性怪兽＋岩石族怪兽\r\n此卡名的①②效果1回合仅可各使用1次，不可在同一连锁上发动。\r\n①：此卡融合召唤的情况下可以发动。从自己手牌・墓地将“磁通超导铠骑”以外的1只岩石族怪兽特殊召唤。\r\n②：在自己・对手回合中，以自己场上的1只地属性怪兽和对手场上的1张卡为对象可以发动。将该卡放回手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','回到手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21862633,'撕裂的黑暗',replace(replace('此卡牌名的①②效果１回合只可各使用１次。\r\n①：我方除衍生物以外的通常怪兽召唤、特殊召唤成功的场合可发动。我方从牌组抽取１张卡牌。\r\n②：以下任意１种我方怪兽与对手怪兽进行战斗的攻击宣言时，可发动。直至回合结束时，该我方怪兽的攻击力上升相当于该对手怪兽的攻击力数值。\r\n●等级５或以上的通常怪兽\r\n●使用通常怪兽仪式召唤而来的怪兽\r\n●以通常怪兽作为素材融合、同步、超量召唤而来的怪兽','\r',char(13)),'\n',char(10)),'抽1张卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21879581,'同步屏障','可释放我方场上１只同步怪兽并发动。直至下一个回合结束时，我方所受到的所有伤害变成０。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21887075,'无尽机关 阿尔银洛系统','此卡名的①②效果１回合１次，仅可使用其中１个。①：从牌组将１张“兽带斗士”卡送至墓地。②：此卡存在于墓地的情况下，以自己墓地的１张“兽带斗士”卡为对象可以发动。将该卡和此卡中的１张加入手牌，另１张放回牌组最下面。','送至墓地','墓地回收','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21887175,'双穹之圣骑联盟・机界骑士',replace(replace('被从额外牌组特殊召唤的怪兽2只以上\r\n①：只要连接召唤的此卡存在于怪兽区域，对手怪兽不可将其他怪兽选择为攻击对象，对手不可将此卡作为效果的对象。\r\n②：每次此卡与被特殊召唤的对手怪兽进行战斗的伤害计算时可以发动1次。此卡的攻击力仅在该伤害计算时上升相当于该对手怪兽攻击力的数值。\r\n③：连接召唤的此卡因对手被送至墓地的情况下可以发动。将场上的1张卡放回牌组。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21887176,'双穹之圣骑联盟・机界骑士',replace(replace('被从额外牌组特殊召唤的怪兽2只以上\r\n①：只要连接召唤的此卡存在于怪兽区域，对手怪兽不可将其他怪兽选择为攻击对象，对手不可将此卡作为效果的对象。\r\n②：每次此卡与被特殊召唤的对手怪兽进行战斗的伤害计算时可以发动1次。此卡的攻击力仅在该伤害计算时上升相当于该对手怪兽攻击力的数值。\r\n③：连接召唤的此卡因对手被送至墓地的情况下可以发动。将场上的1张卡放回牌组。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21887179,'月风魔','此卡与恶魔族、不死族怪兽进行战斗的场合，在该伤害步骤结束时破坏该怪兽。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21888494,'被选中者','从我方手牌选择１张怪兽卡和怪兽以外的２张卡牌，对方从中随机选择１张。对手选中的是怪兽卡的场合，特殊召唤该怪兽至我方场上，并将剩下的卡牌送入墓地。不是怪兽卡的场合，所选的３张卡牌送入墓地。','请选择一张怪兽卡','请选择怪兽卡以外的两张卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21893603,'星杯妖精 丽丝','此卡名的①②效果1回合仅可各使用1次。①：此卡召唤・特殊召唤成功的情况下可以发动。从牌组将1只“星杯”怪兽加入手牌。②：此卡存在于墓地的情况下，将1只自己手牌・场上的怪兽送至墓地可以发动。将墓地的此卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21900719,'闪光之双剑－特莱斯',replace(replace('将1张手牌送至墓地可以发动此卡。\r\n①：装备怪兽攻击力下降500，在1次战斗阶段中可攻击2次。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21903613,'森罗舞娘 锋萄',replace(replace('植物族怪兽2只\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡连接召唤的情况下可以发动。从自己牌组上面翻开最多3张卡。其中有植物族怪兽的情况下，可将其中最多2只特殊召唤。将剩余的卡送至墓地。以此效果特殊召唤的怪兽不可作为连接素材。\r\n②：以自己墓地的1只植物族怪兽为对象可以发动。此卡连接端的怪兽的等级直至回合结束时为止，变为与对象怪兽相同。','\r',char(13)),'\n',char(10)),'','','请选择要翻开的卡的数量','是否选植物族怪兽特殊召唤？','','','','','','','','','','','','');
INSERT INTO texts VALUES(21908319,'哥查基的自爆装置','被放置的此卡被破坏的情况下发动。给予破坏此卡的玩家１０００点伤害。','1000伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21915012,'垒邱比特',replace(replace('协调＋１只以上协调以外的怪兽\r\n此卡名的③效果１回合仅可使用１次。①：此卡同步召唤成功的情况下发动。此卡的等级上升或下降作为该同步素材的协调的等级数值。②：此卡的攻击力上升相当于自身等级×４００的数值。③：同步召唤的此卡作为同步素材被送至墓地的情况下发动。给予对手相当于该同步召唤的怪兽等级×１００的伤害，可从牌组将１只等级８以下、守备力６００的怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','等级上升','等级下降','是否从牌组把怪兽加入手牌？','','','','','','','','','','','','');
INSERT INTO texts VALUES(21924381,'英豪前卫','我方场上冠有“英豪”之名的怪兽被选择为攻击对象时，可选择我方场上的其他１只等级４或以下冠有“英豪”之名的怪兽发动。被选择怪兽的攻击力直至战斗阶段结束时加倍，将被选择怪兽转换为攻击对象并进行伤害计算。双方的怪兽在此战斗中不被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21947653,'邪恶－英雄 闪电魔像',replace(replace('“元素－英雄 闪光人”＋“元素－英雄 黏土人”\r\n此卡仅可以“暗黑结合”的效果特殊召唤。\r\n①：１回合１次，可以场上的１只怪兽为对象发动。破坏该怪兽。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21949879,'娱乐伙伴 粗鲁先生',replace(replace('←8 【灵摆】 8→\r\n此卡名的灵摆效果１回合仅可使用１次。①：另一方的自己的灵摆区域存在“娱乐伙伴 天使女士”，且自己场上不存在怪兽的情况下或仅有灵摆怪兽的情况下可以发动。从牌组将１张“异色眼”卡加入手牌。\r\n【怪兽效果】\r\n此卡名的①②怪兽效果１回合１次，仅可使用其中１个。①：此卡被破坏的情况下可以发动。从牌组挑选“娱乐伙伴 粗鲁先生”以外的１只“娱乐伙伴”灵摆怪兽，放在自己的灵摆区域。②：此卡以表侧表示存在于额外牌组的情况下，从手牌将１只灵摆怪兽舍弃可以发动。将此卡加入手牌。然后，可挑选自己灵摆区域的１张“娱乐伙伴”卡或“异色眼”卡放回持有者的手牌。','\r',char(13)),'\n',char(10)),'','','','是否选自己的灵摆区域1张卡回到手牌？','','','','','','','','','','','','');
INSERT INTO texts VALUES(21954587,'水精鳞－巨齿邃渊',replace(replace('①：从手牌将２只其他的水属性怪兽舍弃至墓地可以发动。从手牌将此卡特殊召唤。\r\n②：以此卡的①效果特殊召唤时可以发动。从牌组将１张“邃渊”魔法・陷阱卡加入手牌。\r\n③：将自己场上１只其他的表侧攻击表示的水属性怪兽解放可以发动。此回合，此卡在１次战斗阶段中可攻击２次。','\r',char(13)),'\n',char(10)),'特殊召唤','检索','两次攻击','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21960890,'大尸教',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从手牌・牌组将1只恶魔族・不死族的仪式怪兽送至墓地。然后，可从牌组将1张仪式魔法卡加入手牌。\r\n②：此卡被除外的情况下，以自己除外状态的1只等级4以下的恶魔族・不死族怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'送至墓地','特殊召唤','是否加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21970285,'龙角的狩猎者',replace(replace('←3 【灵摆】 3→\r\n①：场上的通常怪兽的攻击力上升２００，因自己通常怪兽的战斗对自己造成的战斗伤害变为０。\r\n【怪兽效果】\r\n这位女战士为了拯救因瘟疫正处于水深火热之中的故乡村庄，滥捕作为灵药原料的龙角。\n然而她还不知道的是，那些被逐出栖息地的龙已将村庄夷为平地并燃烧殆尽......','\r',char(13)),'\n',char(10)),'攻守变换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21977828,'甲虫装机 巨大象鼻虫',replace(replace('此卡牌名的③效果１回合只可使用１次。\r\n①：可以我方场上１只“甲虫装机”怪兽为对象发动。此卡从手牌被视为装备卡装备该我方的“甲虫装机”怪兽。\r\n②：此卡被视为装备卡所装备怪兽的原本守备力变成２６００。\r\n③：怪兽所装备的此卡被送入墓地的场合，可以我方墓地的１只“甲虫装机”怪兽为对象发动。特殊召唤该怪兽。','\r',char(13)),'\n',char(10)),'装备','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21984400,'兽・魔・导',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：依以下数量去除自己场上的魔力计数物，可以发动相应效果。\r\n●2个：将自己场上的1只“魔导兽”灵摆怪兽放回手牌。\r\n●4个：从自己额外牌组（表侧）将1只“魔导兽”灵摆怪兽特殊召唤。然后，可在该怪兽上放2个魔力计数物。\r\n●6个：从自己额外牌组（表侧）将1只灵摆怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'取除2个','取除4个','取除6个','是否放置魔力计数物？','','','','','','','','','','','','');
INSERT INTO texts VALUES(21985407,'圣夜之降临',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：在自己・对手的主要阶段，可从以下效果中选择１个发动。\r\n●以自己场上的１只龙族・光属性・等级７怪兽为对象可以发动。将该怪兽放回持有者的手牌。\r\n●从手牌将１只龙族・光属性・等级７怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'回到手牌','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(21999001,'光波双颚机','此卡名的②效果１回合仅可使用１次。①：被从额外牌组特殊召唤的怪兽存在于对手场上，且自己场上不存在怪兽的情况下，此卡可从手牌中特殊召唤。②：舍弃１张手牌可以发动。从手牌・牌组将１只“光波”怪兽特殊召唤。此效果发动后，直至回合结束时为止，自己仅可特殊召唤“光波”怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22007085,'神圣篝火',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：从牌组将１只“圣夜骑士团”怪兽或龙族・光属性・等级７怪兽加入手牌。对手场上有暗属性怪兽存在、自己场上不存在怪兽的情况下，进而可从手牌特殊召唤１只龙族・光属性・等级７怪兽。','\r',char(13)),'\n',char(10)),'是否特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22009013,'侵邪蚀 莫斯','释放冠有“侵邪蚀”之名的怪兽并此卡的上级召唤成功时，可支付１０００LP发动。选择最多对手场上的２张卡牌并返回至持有者手牌。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22011689,'捕食植物 海鳝猪笼草',replace(replace('①：此卡的攻击力上升场上捕食计数物的数量×200的数值。\r\n②：此卡战斗破坏对手怪兽时可以发动。将该破坏的怪兽视为装备魔法卡，装备于此卡。\r\n③：1回合1次，以通过此卡的效果装备中的1张怪兽卡为对象可以发动。将该卡破坏，依其原本攻击力的数值恢复自己的LP。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22020907,'英雄信号','①：自己场上的怪兽因战斗被破坏并被送至墓地时可以发动。从手牌・牌组将1只等级4以下的“元素-英雄”怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22024279,'幻变骚灵・活化',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：以自己墓地的１只“幻变骚灵”连接怪兽为对象可以发动。将该怪兽特殊召唤。\r\n②：将墓地的此卡除外可以发动。进行１只“幻变骚灵”怪兽的召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22026707,'黑魔族的帘布','魔术师制作出的帘布。据说可使魔法师的力量上升。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22046459,'巨大化','①：在自己的LP比对手少的情况下，装备怪兽的攻击力变为其原本攻击力的两倍。在自己的LP比对手多的情况下，装备怪兽的攻击力变为其原本攻击力的一半。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22047978,'战斗中止','在对手怪兽攻击宣言时可以发动。对手从手牌出示１只怪兽可将此效果无效。不出示的情况下，将该攻击怪兽破坏，然后结束战斗阶段。','是否要从手牌把1只怪兽给对手观看？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22056710,'吸血鬼创世主','此卡不可通常召唤。仅限将我方场上的１只“吸血鬼领主”从游戏中除外的场合可特殊召唤。１回合１次，可从手牌将１只不死族怪兽舍弃至墓地并发动。从我方墓地选择１只等级低于舍弃怪兽的不死族怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22061412,'元素－英雄 闪耀',replace(replace('“元素－英雄”怪兽＋光属性怪兽\r\n此卡仅可以融合召唤方式特殊召唤。\r\n①：此卡的攻击力上升自己除外状态的“元素－英雄”怪兽数量×300的数值。\r\n②：此卡从场上被送至墓地时，以自己除外状态的最多2只“元素－英雄”怪兽为对象可以发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22070401,'凶饿毒敌致命龙',replace(replace('←1 【灵摆】 1→\r\n①：1回合1次，在自己的主要阶段可以发动。在对手场上的所有表侧表示怪兽上各放1个毒敌计数物。\n②：龙族・暗属性怪兽以外的场上怪兽的攻击力下降场上的毒敌计数物数量×200的数值。\r\n【怪兽效果】\r\n暗属性灵摆怪兽×3\n①：每当场上的卡被送至墓地，每有1张就在此卡上放1个毒敌计数物。\n②：龙族・暗属性怪兽以外的场上怪兽的攻击力下降场上的毒敌计数物数量×200的数值。\n③：1回合1次，在自己的主要阶段可以发动。对手场上所有表侧表示怪兽的效果直至回合结束时为止无效化。\n④：怪兽区域的此卡因战斗・效果被破坏的情况下可以发动。将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22073844,'教导枢机 尊位德拉格马','此卡不可通常召唤，仅可以此卡的效果特殊召唤。①：以自己・对手墓地的融合・同步・超量・连接怪兽合计４只为对象可以发动。将此卡从手牌特殊召唤，将对象怪兽除外。②：在被特殊召唤的怪兽与此卡进行战斗的伤害步骤开始时发动。将对手场上攻击表示的怪兽全部破坏。然后，给予对手相当于以此效果破坏的融合・同步・超量・连接怪兽数量×８００的伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22076135,'水精鳞－邃渊鲟',replace(replace('此卡名的效果１回合仅可使用１次。\r\n①：此卡召唤・特殊召唤时，从手牌将１只水属性怪兽舍弃至墓地，以自己墓地的１只等级３以下的水属性怪兽为对象可以发动。将该水属性怪兽加入手牌。','\r',char(13)),'\n',char(10)),'回收','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22082163,'亚马逊的意志','从我方墓地选择１只冠有“亚马逊”之名的怪兽并以攻击表示特殊召唤。以此效果特殊召唤的怪兽不可变更表示形式，可进行攻击的场合必须作出攻击。此卡不存在于场上时，破坏该怪兽。该怪兽被破坏时，破坏此卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22082432,'神之怒',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：支付一半LP，解放自己场上的1只怪兽可以发动。将自己手牌・除外状态的1只“拉之翼神龙”无视召唤条件，攻击力・守备力改成4000并特殊召唤。以此效果特殊召唤的怪兽的不可攻击，将在下个回合的结束阶段放回手牌。\r\n②：此卡从场上被送至墓地的情况下发动。挑选自己场上的1只“拉之翼神龙”，将该怪兽以外的场上怪兽全部送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22091345,'娱乐伙伴突刺鹰','①：１回合１次，可以我方场上的１只表侧表示怪兽为对象发动。此回合，该怪兽攻击了守备表示怪兽的场合，给予对手攻击力超过该守备力数值的战斗伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22091647,'神御不死鸟・机亚弗里德','此卡名的①②③效果１回合仅可各使用１次。①：从自己的场上・墓地将１张装备魔法卡除外可以发动。从手牌将此卡特殊召唤。②：此卡攻击的伤害步骤开始时可以发动。挑选场上１只此卡以外的表侧表示怪兽，视为攻击力上升５００的装备卡装备于此卡（仅可装备１只）。③：怪兽的效果发动时，将自己场上的１张表侧表示的装备卡送至墓地可以发动。将该发动无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22093873,'假面－英雄 神风',replace(replace('此卡仅可通过“假面变换”的效果特殊召唤。\r\n①：此卡不会因战斗被破坏。\r\n②：只要此卡存在于怪兽区域，对手在1次战斗阶段中仅可用1只怪兽攻击。\r\n③：此卡战斗破坏对手怪兽并将其送至墓地时可以发动。自己抽1张。','\r',char(13)),'\n',char(10)),'抽1张卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22106558,'机睿的机械调整师',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：场地区域存在卡的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：以自己场上的1张表侧表示的魔法・陷阱卡为对象可以发动。将该卡破坏，从牌组将1只攻击力0的机械族・风属性怪兽加入手牌。此回合，自己从额外牌组仅可特殊召唤机械族怪兽。\r\n③：其他自己的机械族怪兽进行战斗的攻击宣言时可以发动。将该自己的怪兽的等级上升或下降1。','\r',char(13)),'\n',char(10)),'等级改变','特殊召唤','破坏并检索','上升等级','下降等级','','','','','','','','','','','');
INSERT INTO texts VALUES(22110647,'幻兽机 哥萨克龙',replace(replace('等级７怪兽×２\r\n①：１回合１次，去除此卡的１个超量素材可以发动。将２只“幻兽机衍生物”（机械族・风・星３・攻／守０）特殊召唤至自己场上。②：只要自己场上有衍生物存在，此卡不会因战斗・效果被破坏。③：１回合１次，解放自己场上的１只“幻兽机”怪兽，以场上的１张卡为对象可以发动。将该卡破坏。发动此效果的回合中，此卡不可攻击。','\r',char(13)),'\n',char(10)),'在自己场上把2只「幻兽机衍生物」特殊召唤','选择场上1张卡破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22110648,'幻兽机衍生物','由名称中带有“幻兽机”的怪兽等的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22123627,'强欲之海鳝','①：从手牌将２只水属性怪兽放回牌组并洗牌。然后，自己从牌组抽３张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22125101,'超越灵摆・轨迹的魔术使',replace(replace('包括灵摆怪兽在内的效果怪兽２只\r\n此卡名的②效果１回合仅可使用１次。①：此卡被连接召唤至额外怪兽区域的情况下，支付１２００LP可以发动。从牌组将１只灵摆怪兽加入手牌。此回合，只要自己未灵摆召唤成功，则不可发动怪兽的效果，且自己的灵摆区域的卡的效果无效化。②：原本等级不同的２只怪兽同时被灵摆召唤至此卡连接端的情况下，以场上的２张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22134079,'守墓的伏兵','此卡反转时可发动。选择对手墓地的１张卡牌返回至牌组的最下方。此外，反转的此卡被送入墓地的场合可发动。选择我方墓地的１张“死灵谷”卡牌加入手牌。此卡的效果不受“王家长眠之谷－死灵谷”的效果影响。','返回牌组','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22138839,'捕食植物 佛塔树食人魔','①：此卡可在解放对手场上１只放有捕食计数物的怪兽的情况下，来从手牌特殊召唤。②：此卡从场上被送至墓地的情况下发动。在对手场上所有表侧表示怪兽上各放１个捕食计数物。放有捕食计数物的等级２以上怪兽的等级变为１。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22147147,'旋风剑','此卡仅限装备冠有“命运－英雄”之名的怪兽。装备怪兽进行了攻击的伤害步骤结束时，选择场上的１张魔法、陷阱卡破坏。','魔陷破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22159429,'淘气仙星・魔法花冠','此卡名的卡1回合仅可发动1张。①：以自己墓地的1只“淘气仙星”怪兽为对象可以发动此卡。将该怪兽特殊召唤，装备此卡。此卡从场上离开时该怪兽将被破坏。②：1回合1次，装备怪兽以战斗・效果给予对手伤害的情况下可以发动。从手牌将1只“淘气仙星”怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22160245,'邪恶－英雄 业火之翼',replace(replace('“元素－英雄 羽毛人”＋“元素－英雄 爆炎女郎”\r\n此卡仅可以“黑暗结合”的效果特殊召唤。\r\n①：此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。\r\n②：此卡战斗破坏怪兽并将其送至墓地的情况下发动。依该怪兽原本攻击力和原本守备力中较高一方的数值来给予对手伤害。','\r',char(13)),'\n',char(10)),'伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22171591,'秘学家','此卡因战斗被破坏并送入墓地时，可通过支付８００LP发动。从牌组将１只念动力族怪兽加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22174866,'芬芳法师－依兰',replace(replace('①：只要自己的LP多于对手，且此卡存在于怪兽区域，对手场上的怪兽的攻击力・守备力下降５００。\r\n②：１回合１次，自己的LP恢复的情况下，以对手场上的１张魔法・陷阱卡为对象发动。将该卡放回手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22180094,'超元特防队 乱破小夜丸',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：只要此卡存在于怪兽区域，自己的“超元特防队”怪兽正面的对手怪兽仅可将与自身同一纵列的怪兽选择为攻击对象。\r\n②：在自己・对手回合中，从手牌将1张“超元特防队”卡除外可以发动。将场上的此卡放回手牌，从牌组将“超元特防队 乱破小夜丸”以外的1只“超元特防队”怪兽以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22198672,'王车连接',replace(replace('①：１回合１次，在自己的主要阶段，以场上的１只连接怪兽为对象可以发动。将该怪兽的位置移动至该怪兽连接端的主要怪兽区域（不可移动至对该怪兽来说的对手场上）。\r\n②：１回合１次，在自己的主要阶段可以发动。挑选自己主要怪兽区域的２只连接怪兽，或对手主要怪兽区域的２只连接怪兽，交换其位置。','\r',char(13)),'\n',char(10)),'移动位置','交换位置','请选择要移动位置的怪兽','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22200403,'催眠妹妹',replace(replace('①：根据双方灵摆区的卡牌数量，此卡获得以下效果。\r\n●１张或以上：此卡的攻击力、守备力上升８００。\r\n●２张或以上：此卡与灵摆召唤而来的怪兽进行战斗的伤害步骤开始时发动。破坏该怪兽。\r\n●３张或以上：对手场上的怪兽可攻击的场合，必须攻击此卡。\r\n●４张：此卡因战斗或此卡的效果破坏怪兽的场合发动。我方从牌组抽取１张卡牌。','\r',char(13)),'\n',char(10)),'破坏','抽牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22201234,'光道防护罩','自己场上的名字带有“光道”的怪兽被选择作为攻击对象时，可以从自己的牌组上面将２张卡送往墓地，选择１只攻击怪兽发动此效果。将该攻击无效。','是否要使用效果？','对手怪兽的攻击无效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22205600,'连锁旋风','场上的卡牌因魔法、陷阱、怪兽效果被破坏时，可选择场上的２张魔法、陷阱卡发动。破坏被选择的卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22211622,'霸王门 无限',replace(replace('←13 【灵摆】 13→\r\n①：自己场上存在怪兽的情况下，自己不可灵摆召唤。此效果不会被无效化。\n②：１回合１次，自己场上存在“霸王龙扎克”的情况下，以对手场上的１只表侧表示怪兽为对象可以发动。依该怪兽的攻击力数值恢复自己的LP。\r\n【怪兽效果】\r\n①：１回合１次，以自己场上此卡以外的１张表侧表示卡为对象可以发动。将该卡和此卡破坏，从额外牌组将１只龙族超量怪兽或龙族灵摆怪兽特殊召唤。以此效果特殊召唤的怪兽的攻击力・守备力变为０，效果无效化，不可作为同步・超量召唤的素材。\n②：怪兽区域的此卡因战斗・效果被破坏的情况下可以发动。将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22219822,'淘气仙星・曼蕾克','此卡名的①②效果1回合仅可各使用1次。①：此卡从手牌被送至墓地的情况下可以发动。将此卡以守备表示特殊召唤。以此效果特殊召唤的此卡离开场上的情况下，将其除外。②：此卡作为“淘气仙星”连接怪兽的连接素材被送至墓地的情况下，以对手的连接怪兽连接端的1只怪兽为对象可以发动。将该怪兽破坏。','特殊召唤','怪兽破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22227683,'文具博格００４','①：此卡与对手怪兽进行战斗的伤害计算时可以发动。从牌组将“文具博格００４”以外的１只“文具博格”怪兽送至墓地，此卡的攻击力・守备力仅在该伤害计算时，上升相当于送至墓地怪兽等级×５００的数值。此效果发动后，直至回合结束时为止，对手所受战斗伤害变为０。②：此卡战斗破坏对手怪兽的情况下可以发动。从自己的手牌・墓地挑选等级不同的２只“文具博格”怪兽，以守备表示特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22283204,'提玛欧斯之眼光',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：以自己场上・墓地的1只“黑魔导”或“黑魔导女孩”为对象可以发动。仅将该1只怪兽作为融合素材放回牌组，将1只融合素材中记载有该卡名的融合怪兽，视为以“提玛欧斯之眼”的效果融合召唤。以此效果特殊召唤的怪兽将在下个回合的结束阶段被除外。','\r',char(13)),'\n',char(10)),'发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22318971,'一角兽的使魔','表侧守备表示的此卡被选择为攻击对象时，可将除此卡以外的我方场上的１只怪兽从游戏中除外并发动。将此卡从游戏中除外。此时的攻击怪兽必须进行攻击。以此效果除外的此卡，在下一个我方准备阶段时返回至场上。','除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22339232,'白骨梦魇',replace(replace('①：此卡只要存在于墓地，卡名视为“白骨”。②：将此卡从手牌中舍弃，可从以下效果中选择１个发动。\r\n●以自己１只被除外的“白骨”或“白骨梦魇”为对象可以发动。将该怪兽放回墓地。\r\n●以自己１只被除外的“白骨夫人”或“白骨王”为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'「白骨」或者「白骨梦魇」回到墓地','「白骨夫人」或者「白骨王」特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22346472,'破天荒暴风','可选择我方场上１只表侧表示的怪兽来发动此卡。所选择怪兽的攻击力和守备力上升１０００点，直到下次我方准备阶段时。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22359980,'银幕的镜壁','令对手攻击怪兽的攻击力减半。只要此卡存在于场上，此效果便有效。此卡的控制者须每次在自己的准备阶段支付２０００LP，或者破坏此卡而不支付２０００LP。','是否要支付2000基本分维持「银幕的镜壁」？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22371016,'正义盟军 未知破坏者','此卡在和光属性怪兽进行战斗的伤害计算后发动。将该怪兽从游戏中除外。','除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22373487,'滚・粗・去！','此卡名的卡1回合仅可发动1张。①：以从额外牌组被特殊召唤的对手场上的2只怪兽为对象可以发动。将该怪兽放回持有者的牌组。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22377092,'陷阱痴迷',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：以自己场上的1张魔法・陷阱卡为对象可以发动。将该卡破坏，从牌组将“陷阱痴迷”以外的1张通常陷阱卡放置在自己场上。只要自己墓地存在3张以上的陷阱卡，以此效果放置的卡在放置的回合也可以发动。','\r',char(13)),'\n',char(10)),'发动','适用「陷阱痴迷」的效果来发动','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22377815,'涟漪的艾瑞莎',replace(replace('此卡存在于墓地或以表侧表示存在于场上的场合，将被视为通常怪兽。以通常召唤的方式再次召唤场上表侧表示的此卡，此卡将视为效果怪兽并获得以下效果。\r\n●此卡通过战斗破坏对手怪兽并将其送入墓地时，随机弃置对手１张手牌。','\r',char(13)),'\n',char(10)),'手牌丢弃','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22382087,'风帝家臣迦楼姆',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：将自己场上的1只被上级召唤的怪兽放回手牌可以发动。从手牌将此卡特殊召唤。此回合，自己不可从额外牌组特殊召唤怪兽。\r\n②：此卡为上级召唤而被解放的情况下可以发动。从牌组将“风帝家臣迦楼姆”以外的1只攻击力800/守备力1000的怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22386234,'极光安吉拉斯','只要此卡以表侧表示存在于场上，双方不可特殊召唤怪兽。怪兽被召唤至我方或对手场上时，破坏此卡。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22390469,'黄金荣耀－星之里昂',replace(replace('协调＋协调以外的怪兽１只以上\r\n此卡名的①效果１回合仅可使用１次。\r\n①：在自己・对手的主要阶段，以对手场上的１只表侧表示怪兽为对象可以发动。此卡的攻击力上升相当于该怪兽原本攻击力的数值。自己的LP少于对手的情况下，进而可将对象怪兽破坏。\r\n②：在发动了此卡的①效果的回合的结束阶段发动。将此卡放回额外牌组，从自己的牌组・墓地将１只“黄金荣耀－里昂”特殊召唤。','\r',char(13)),'\n',char(10)),'','','是否把那只怪兽破坏？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22398665,'辉龙机巧降星','仪式怪兽的降临所必需。此卡名的②效果1回合仅可使用1次。①：为使合计攻击力变为仪式召唤怪兽的攻击力以上，解放自己手牌・场上的机械族怪兽，从自己的手牌・墓地将1只仪式怪兽仪式召唤。②：此卡存在于墓地的情况下，以自己场上的1只“龙机巧”怪兽为对象可以发动。该怪兽的攻击力直至对手回合结束时为止下降1000，将此卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22404570,'终末时刻的狱神影',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从自己手牌・额外牌组（表侧）・墓地将1只“狱神”怪兽特殊召唤。然后，根据自己场上的怪兽种类（融合・同步・超量）数量，可分别适用以下效果。\r\n●1种以上：从对手牌组上面将3张卡以里侧除外。\r\n●2种以上：将对手场上的1张卡以里侧除外。\r\n●3种：随机将对手的1张手牌以里侧除外。','\r',char(13)),'\n',char(10)),'发动','是否除外牌组？','是否除外场上？','是否除外手牌？','','','','','','','','','','','','');
INSERT INTO texts VALUES(22404675,'雷帝家臣密斯拉',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己的主要阶段可以发动。从手牌将此卡特殊召唤，将1只“家臣衍生物”（雷族・光・星1・攻800/守1000）以守备表示特殊召唤至对手场上。此效果发动后，直至回合结束时为止，自己不可从额外牌组特殊召唤怪兽。\r\n②：此卡为上级召唤而被解放的情况下可以发动。此回合，自己在通常召唤之外，可在自己的主要阶段追加1次上级召唤。','\r',char(13)),'\n',char(10)),'使用「雷帝家臣密斯拉」的效果召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22404676,'家臣衍生物','由“雷帝家臣密特拉”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22411609,'火山性骑兵',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n \r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将“火山性骑兵”以外的１张“火山性”卡加入手牌。 \r\n②：舍弃１张手牌可以发动。将１只“炸弹衍生物”（炎族・炎・星１・攻／守１０００）特殊召唤至对手场上。此衍生物被破坏时，其控制者受到５００伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22411610,'炸弹衍生物','将被以“火山性骑兵”等的效果特殊召唤。此衍生物被破坏时，其控制者受到５００伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22414174,'同步贪婪',replace(replace('此卡名的卡１回合仅可发动１张。\r\n \r\n①：场上存在同步怪兽的情况下可以发动。自己抽１张。场上存在３只以上同步怪兽的情况下，自己可进而再抽１张。','\r',char(13)),'\n',char(10)),'是否再抽1张？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22419772,'妖精守护者','解放此卡并发动。将此回合因对手而被送入墓地的我方的１张魔法卡返回至牌组最下方。','返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22420202,'辉龙机巧－天厨一德尔塔','此卡不可通常召唤，仅可用“龙机巧”卡的效果特殊召唤。此卡名的效果1回合仅可使用1次。①：从自己的手牌・场上，解放此卡以外的1只“龙机巧”怪兽或仪式怪兽可以发动。将此卡从手牌・墓地以守备表示特殊召唤。然后，可将手牌的1只仪式怪兽或1张仪式魔法卡出示给对手，自己从牌组抽1张。发动此效果的回合中，自己仅可特殊召唤不可通常召唤的怪兽。','','是否抽牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22423493,'机壳・盖尼乌斯',replace(replace('机械族怪兽２只\r\n①：连接召唤的此卡不受魔法・陷阱卡的效果影响，也不受此卡以外的连接怪兽发动的效果影响。②：１回合１次，以自己及对手场上此卡以外的表侧表示卡各１张为对象可以发动。将该２张卡的效果直至回合结束时为止无效。③：２只怪兽被同时特殊召唤至此卡连接端时可以发动。从牌组将１只等级５以上的机械族怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22431243,'超进化药','解放自己场上的１只爬虫类族怪兽来发动此卡。从手牌特殊召唤１只恐龙族怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22435424,'辉龙机巧－天棓二纽兹',replace(replace('此卡不可通常召唤，仅可以卡的效果特殊召唤。\r\n此卡名的①②效果１回合仅可各使用１次，发动此效果的回合中，自己仅可仪式召唤机械族怪兽。\r\n①：场上存在“龙机巧”卡的情况下可以发动。从手牌・墓地将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。\r\n②：此卡特殊召唤的情况下可以发动。从牌组将“辉龙机巧－天棓二纽兹”以外的１只“龙机巧”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','牌组检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22446869,'水精鳞－恐甲邃渊',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：从手牌将１只其他的水属性怪兽舍弃至墓地可以发动。从手牌将此卡特殊召唤。\r\n②：以此卡的①效果特殊召唤时可以发动。从牌组将１只等级４以下的“水精鳞”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22454453,'谦虚之瓶','①：我方挑选１张手牌并将其返回至牌组的最上方或最下方。','牌组最上面','牌组最下面','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22479888,'黏土冲撞','我方场上的“元素－英雄 黏土人”被选择为攻击对象时可发动（里侧表示的场合，翻阅确认）。破坏攻击怪兽与攻击对象的“元素－英雄 黏土人”，并给予对手生命８００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22493811,'蚂蚁增殖','解放自己场上的１只昆虫族怪兽来发动此卡。特殊召唤２只“兵蚁衍生物”（昆虫族・地・４星・攻５００／守１２００）至我方场上。不可解放该衍生物来进行上级召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22493812,'兵蚁衍生物','由「蚂蚁增殖」的效果特殊召唤。这个衍生物不能用于上级召唤而解放。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22499034,'真龙战士 点火烽刃 灼热',replace(replace('要以表侧表示上级召唤此卡的情况下，可解放自己场上的永续魔法・永续陷阱卡来作为怪兽的代替。\r\n①：此卡是被上级召唤的情况下，1回合1次，对手发动魔法・陷阱・怪兽的效果时可以发动。从牌组挑选1张“真龙”永续魔法卡，加入手牌或在自己场上发动。','\r',char(13)),'\n',char(10)),'解放魔法·陷阱卡上级召唤','加入手牌或在自己场上发动','是否加入手牌？','请选择要加入手牌或在自己场上发动的卡','','','','','','','','','','','','');
INSERT INTO texts VALUES(22499463,'猛毒眼镜蛇','全身披覆坚硬鳞片的巨大眼镜蛇。会喷出毒液进行攻击，由于它的身体巨大，因此毒液攻击威力十足。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22501005,'灵兽的继圣',replace(replace('此卡名的②③效果１回合仅可各使用１次。\r\n①：对手场上的怪兽的攻击力下降相当于自己场上的“灵兽”怪兽的种族种类×２００的数值。\r\n②：将手牌的１只“灵兽”怪兽出示给对手可以发动。从牌组将１只种族与该怪兽不同的“灵兽”怪兽加入手牌。然后，挑选自己的１张手牌舍弃。\r\n③：２只以上的怪兽同时被特殊召唤至自己场上的情况下，以场上的１只怪兽为对象可以发动。变更该怪兽的表示形式。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22510667,'刚鬼 铠甲食人魔',replace(replace('“刚鬼”怪兽2只以上\r\n①：只要此卡的连接端有“刚鬼”怪兽存在，此卡不会因战斗・效果被破坏。②：1回合1次，以“刚鬼 铠甲食人魔”以外的、自己主要怪兽区域的1只“刚鬼”怪兽为对象可以发动。将自己的该怪兽的位置移动至此卡连接端的自己主要怪兽区域。此效果在对手回合中也可以发动。','\r',char(13)),'\n',char(10)),'请选择要移动位置的怪兽','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22512237,'机械猎犬','①：只要自己的手牌为0张，则对手不可发动魔法卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22512406,'覆面忍者惠比寿','１回合１次，我方场上存在有除“覆面忍者惠比寿”以外的冠有“忍者”之名怪兽的场合可发动。将对手的魔法、陷阱卡返回至持有者手牌，其数量与我方场上冠有“忍者”之名怪兽的数量相同。适用了此效果的回合，我方场上的“忍者义贼 五卫五卫”可直接攻击对手玩家。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22530212,'魔术手','①：只要此卡以表侧表示存在于场上，仅１次，对手以抽牌以外的方法将卡片从牌组加入手牌时可以发动。将该卡送至墓地，并给予对手８００点伤害。','送墓并伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22537443,'塞贝克的祝福','①：我方怪兽因直接攻击给予对手战斗伤害时可发动。我方回复相当于该数值的LP。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22539270,'废铁油带','发动此卡的回合中，自己无法进行战斗阶段。①：以自己墓地的１只“废铁”怪兽为对象可以发动此卡。将该怪兽特殊召唤。以此效果特殊召唤的怪兽的效果无效化。此卡从场上离开时，该怪兽将被破坏。该怪兽从场上离开时，此卡将被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22555834,'魔轰神界之阶',replace(replace('此卡名的卡1回合仅可发动1张，此卡名的②效果1回合仅可使用1次。\r\n①：作为此卡发动时的效果处理，可从牌组将1只“魔轰神”怪兽送至墓地。\r\n②：以自己墓地的1只“魔轰神”怪兽为对象可以发动。挑选自己的2张手牌舍弃，将对象怪兽加入手牌。\r\n③：自己的手牌少于对手的情况下，自己的“魔轰神”怪兽的攻击力仅在攻击对手怪兽的伤害计算时，上升相当于双方手牌张数差×200的数值。','\r',char(13)),'\n',char(10)),'是否从牌组把「魔轰神」怪兽送至墓地？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22567609,'迅捷飞鼠','①：此卡因战斗被破坏并被送至墓地的情况下发动。自己恢复1000LP。然后可从牌组将任意数量的“迅捷飞鼠”以里侧守备表示特殊召唤。','回复','是否要特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22586618,'黑暗冥西摩格','此卡名的①③效果1回合仅可各使用1次。①：此卡存在于手牌・墓地，自己将暗属性或风属性怪兽上级召唤成功的情况下可以发动。将此卡特殊召唤。②：只要此卡存在于怪兽区域，此卡的属性也视为“风”。③：魔法・陷阱卡的效果发动时，解放自己场上的1只鸟兽族・风属性怪兽可以发动。将该发动无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22587018,'氢魔兽','此卡因战斗将对手怪兽破坏并送入墓地时，可从我方牌组特殊召唤１只“氢魔兽”。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22589918,'上膛','我方手牌全部加入牌组并洗牌。之后，抽取相当于加入牌组数量的卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22593417,'拓扑逻辑篡改感染龙',replace(replace('效果怪兽２只以上\r\n此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：此卡已经存在于怪兽区域的状态下，此卡以外的怪兽被特殊召唤至连接怪兽连接端的情况下发动。自己随机舍弃任意张数的手牌（最多２张）。然后，依舍弃的数量，对手挑选手牌舍弃。\r\n②：此卡为额外连接状态的情况下可以发动。对手尽可能地挑选最多２张手牌舍弃。对手的手牌以此效果变为０张的情况下，进而给予对手３０００伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22609617,'偷袭的又佐','此卡在１次的战斗阶段中可攻击２次。只要此卡以表侧表示存在于场上，不可改变控制权。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22610082,'遗言的假面',replace(replace('①：将此卡放回到牌组并进行洗牌。\r\n②：以“假面魔兽 死亡护法师”的效果装备此卡的场合，取得装备怪兽的控制权。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22617205,'觉辉星骑士－源质西卜',replace(replace('←7 【灵摆】 7→\r\n①：自己仅可灵摆召唤“星骑士”怪兽及“源质”怪兽。此效果不会被无效化。\r\n【怪兽效果】\r\n此卡名的怪兽效果１回合仅可使用１次。①：此卡召唤・反转召唤・灵摆召唤成功的情况下，以此卡以外的、自己的怪兽区域・灵摆区域的１张“星骑士”卡或“源质”卡，和被放置在对手场上的１张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22623509,'恩底弥翁的侍女 薇儿',replace(replace('此卡名在规则上也视为“魔女工艺”卡。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：在发动过魔法卡效果的回合的、自己的主要阶段可以发动。从手牌将此卡特殊召唤。\r\n②：此卡特殊召唤的情况下可以发动。从牌组将1张“魔女工艺”魔法・陷阱卡或“次元魔法”加入手牌。\r\n③：只要自己场上或墓地存在“恩底弥翁之圣月皇太子 雷格鲁斯”，此卡的攻击力上升2300。','\r',char(13)),'\n',char(10)),'特殊召唤','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22624373,'光道魔术师 莱拉','①：可以对手场上1张魔法・陷阱卡作为对象发动。将自己场上表侧攻击表示的此卡改成守备表示，破坏作为对象的对手的卡。此效果发动后，直到下一个自己回合结束时为止不可更改此卡的表示形式。②：在自己的结束阶段发动。从自己牌组上面将3张卡送至墓地。','破坏魔法陷阱','从牌组送3张卡去墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22628574,'伪羽翼','可从手牌将１冠只有“黑羽”之名的怪兽送入墓地，并选择１张对手墓地的通常陷阱卡发动。此卡的效果变成与被选择的通常陷阱卡相同效果。','请选择一张通常陷阱','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22634473,'对峙的宿命',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：自己场上存在“青眼白龙”或“黑魔导”的情况下可以发动。对手场上所有表侧表示怪兽的效果直至回合结束时为止无效化。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22638495,'刚龙剑士 机动行者 强劲',replace(replace('“龙剑士”灵摆怪兽＋灵摆怪兽\r\n仅在解放自己场上的上述卡的情况下，可从额外牌组特殊召唤。\r\n①：只要此卡存在于怪兽区域，自己的怪兽区域・灵摆区域的灵摆怪兽卡不会因战斗及对手的效果被破坏。\r\n②：１回合１次，在自己的主要阶段可以发动。从自己的手牌・墓地将１只“龙剑士”灵摆怪兽特殊召唤。以此效果特殊召唤的怪兽不可作为融合素材。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22653490,'电光千鸟',replace(replace('风属性等级4怪兽×2\r\n①：此卡超量召唤的情况下，以对手场上1张里侧表示的卡为对象发动。将该对手的里侧表示卡放回牌组最下面。\r\n②：1回合1次，去除此卡的1个超量素材，以对手场上的1张表侧表示卡为对象可以发动。将该对手的表侧表示卡放回牌组最上面。','\r',char(13)),'\n',char(10)),'返回牌组最下面','返回牌组最上面','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22657402,'冥界丽人 伊索尔德','此卡仅可以此卡的①方法特殊召唤。此卡名的②效果１回合仅可使用１次。①：自己场上存在“冥界骑士 崔斯坦”的情况下，此卡可从手牌中特殊召唤。②：以自己场上的最多２只不死族怪兽为对象，宣言５～８之间的任意等级可以发动。该怪兽直至回合结束时为止变为所宣言的等级。此效果发动后，直至回合结束时为止，自己仅可特殊召唤不死族怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22662014,'惊乐园的助手＜德利亚＞',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：将手牌的１张“游乐设施”陷阱卡出示给对手可以发动。从手牌将此卡特殊召唤。\r\n②：从手牌及自己场上表侧表示的卡中，将１张“游乐设施”陷阱卡送至墓地可以发动。从牌组挑选１张“游乐设施”陷阱卡，放置在自己的魔法与陷阱区域。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22666164,'督战官 科温顿','①：将自己场上表侧表示的“机甲部队・士兵”、“机甲部队・狙击兵”、“机甲部队・防卫兵”各１只送至墓地可以发动。从手牌・牌组将１只“机甲部队・武力”特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22669793,'高贵黄金乡的埃尔德里希尔',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：支付800LP，可从以下效果中选择1个发动。\r\n●此卡变为通常怪兽（不死族・光・星10・攻1500/守2800），特殊召唤至怪兽区域（也视为陷阱卡）。自己场上存在“黄金卿埃尔德里奇”的情况下，进而可将场上的1只怪兽放回手牌。\r\n●将自己除外状态的1张“黄金乡”魔法・陷阱卡或“埃尔德里希尔”魔法・陷阱卡放置在自己场上。','\r',char(13)),'\n',char(10)),'发动','特殊召唤','放置','是否让怪兽回到手牌？','','','','','','','','','','','','');
INSERT INTO texts VALUES(22702055,'海','①：场上的鱼族・海龙族・雷族・水族怪兽的攻击力・守备力上升200，场上的机械族・炎族怪兽的攻击力・守备力下降200。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22712877,'麻痹盖菇',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：原本种族为雷族的怪兽被从自己的手牌・场上送至墓地的情况下可以发动（伤害步骤也可以发动）。从手牌将此卡特殊召唤。\r\n②：此卡存在于怪兽区域的状态下，雷族怪兽的效果在手牌发动的情况下可以发动。将１只“麻痹衍生物”（雷族・暗・星１・攻／守０）特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'特殊召唤','特殊召唤衍生物','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22712878,'麻痹衍生物','「麻痹盖菇」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22723778,'暗黑界之混沌王 凯无零色',replace(replace('“暗黑界之魔神 彩莲恩”＋恶魔族怪兽２只以上 \r\n①：此卡融合召唤的情况下可以发动。将对手场上的卡全部破坏。 \r\n②：此卡原本的攻击力・守备力变为相当于作为此卡融合素材怪兽的数量×１０００的数值。 \r\n③：在自己・对手回合中１次，以自己场上的１张表侧表示的卡为对象可以发动。挑选１张自己的手牌舍弃。此回合，对手不可将对象表侧表示卡作为效果的对象。','\r',char(13)),'\n',char(10)),'对手场上的卡全部破坏','选自己1张手牌丢弃','「暗黑界之混沌王 凯无零色」效果适用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22734799,'三幻魔操世者',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：向对手出示手牌的此卡可以发动。挑选自己的1张手牌舍弃，从手牌将1只等级8以外的“三幻魔”怪兽以守备表示特殊召唤。\r\n②：舍弃1张手牌可以发动。从自己手牌・墓地将除所舍弃的卡以外的、1只等级8以外的“三幻魔”怪兽以守备表示特殊召唤。\r\n③：将墓地的此卡除外可以发动。从自己墓地将1只等级8以外的“三幻魔”怪兽以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','特殊召唤','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22747316,'以牙还牙','对手发动与存在于我方墓地的魔法、陷阱卡同名的卡牌时可发动。使该发动无效并破坏。之后，可从我方墓地挑选１张以此效果发动而无效的卡牌的同名卡加入手牌。','是否要选择一张同名卡加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22748199,'神之冰结',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：场上有２只以上水属性怪兽存在的情况下，以对手场上的１只表侧表示怪兽为对象可以发动。该表侧表示怪兽不可攻击，效果被无效化。\r\n②：此卡在墓地存在的状态下，自己场上有等级５以上的水属性怪兽被召唤・特殊召唤的情况下可以发动。将此卡放置在自己场上。以此效果放置的此卡离开场上的情况下，将其除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22751868,'风云机偶城','①：自己的“机偶”怪兽选择对手的表侧表示怪兽为攻击对象时，以１只该对手怪兽为对象可以发动。变更该对手怪兽的表示形式。②：场上表侧表示的此卡被破坏并被送至墓地时，以自己墓地１只等级４以上的“机偶”怪兽为对象可以发动。将该怪兽特殊召唤。','改变表示形式','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22754505,'小块魔像','①：此卡召唤・反转召唤・特殊召唤时，如果自己场上存在“大块魔像”则可以发动。从牌组将1只“中块魔像”特殊召唤。以此效果特殊召唤的怪兽的效果无效化。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22765132,'娱乐伙伴呼唤','①：在对手怪兽的直接攻击宣言时，可以１只该攻击怪兽为对象发动。使该攻击无效，并从牌组将最多２只“娱乐伙伴”怪兽加入手牌，使得守备力的合计变成对象怪兽的攻击力或以下。此卡发动后，直至下一个我方回合结束时，我方不可从额外牌组特殊召唤怪兽。','把最多2只「娱乐伙伴」怪兽加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22790789,'巨大战舰 晶核',replace(replace('①：此卡召唤的情况下发动。在此卡上放3个计数物。\r\n②：此卡不会因战斗被破坏。\r\n③：1回合1次，以对手场上的1只表侧攻击表示的怪兽为对象可以发动。将该对手的表侧攻击表示怪兽改成表侧守备表示。\r\n④：此卡进行战斗的伤害步骤结束时发动。去除此卡的1个计数物。无法去除的情况下将此卡破坏。','\r',char(13)),'\n',char(10)),'放置计数物','移除计数物','破坏','改变表示形式','','','','','','','','','','','','');
INSERT INTO texts VALUES(22790910,'智之贤者－辛梅尔',replace(replace('此卡名在规则上也视为“闪刀”卡。\r\n此卡名的①②③效果１回合仅可各使用１次。\r\n①：从手牌将１张魔法卡舍弃可以发动。从手牌将此卡特殊召唤。\r\n②：对手发动以自己场上的连接怪兽为对象的效果时，从自己的墓地将２张魔法卡除外可以发动。将该效果无效。\r\n③：此卡因战斗・效果被破坏并被送至墓地的情况下，以自己除外状态的１张“闪刀”魔法卡为对象可以发动。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22796548,'恶魔的宣告','①：１回合１次，支付５００LP，宣言１个卡名可以发动。将自己牌组最上面的卡翻开，是宣言的卡的情况下，将该卡加入手牌。不是的情况下，将翻开的卡送至墓地。','宣言','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22802010,'无差别崩坏','①：摇２次骰子。将场上等级・阶级低于摇出的数字的合计值的表侧表示怪兽全部破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22804410,'深眼白龙',replace(replace('①：我方场上的表侧表示“青眼”怪兽因战斗或对手效果被破坏时可发动。从手牌特殊召唤此卡，并给予对手我方墓地龙族怪兽种类×６００的伤害。\r\n②：此卡召唤、特殊召唤成功的场合，以我方墓地的１只龙族怪兽为对象发动。此卡的攻击力变成与该怪兽的攻击力相同。\r\n③：场上的此卡因效果被破坏的场合发动。破坏对手场上的所有怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22804644,'死亡病毒龙',replace(replace('此卡仅可在以“克里底亚之牙”的效果将自己的手牌・场上的“死之牌组破坏病毒”送至墓地的情况下特殊召唤。\r\n①：此卡特殊召唤成功的情况下发动。将对手场上的怪兽、对手的手牌、以对手回合为准３个回合期间对手所抽的卡全部确认，将其中攻击力１５００以上的怪兽全部破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22812068,'机甲忍者・地','对手场上存在有怪兽，而我方场上不存在怪兽的场合，此卡可从手牌特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22812963,'创言再世神 德乌特洛诺米翁',replace(replace('此卡不可通常召唤。\r\n“创言再世神 德乌特洛诺米翁”1回合1次，仅可在将原本攻击力和原本守备力为2500的、自己场上的1只表侧表示怪兽除外的情况下特殊召唤。\r\n①：此卡特殊召唤的情况下可以发动。从牌组将1张“再世”魔法・陷阱卡放置在自己场上。\r\n②：此卡的攻击力在战斗阶段期间上升2500。\r\n③：此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。','\r',char(13)),'\n',char(10)),'','放置','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22819092,'鱼群探知机',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从牌组将1只等级7以下的、记载有“海”卡名的怪兽或水属性通常怪兽加入手牌。场上存在“海”的情况下，进而可从牌组将1只水属性通常怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'是否从牌组把1只水属性通常怪兽特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22819093,'鱼群探知机',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从牌组将1只等级7以下的、记载有“海”卡名的怪兽或水属性通常怪兽加入手牌。场上存在“海”的情况下，进而可从牌组将1只水属性通常怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'是否从牌组把1只水属性通常怪兽特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22829942,'融合再生机构',replace(replace('①：1回合1次，舍弃1张手牌可以发动。从自己的牌组・墓地将1张“融合”加入手牌。\r\n②：在自己・对手的结束阶段，以此回合使用于融合召唤的自己墓地的1只融合素材怪兽为对象可以发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22835145,'黑羽－极北之暴冽扎德',replace(replace('此卡不可特殊召唤。\r\n①：此卡召唤时，以自己墓地的1只等级4以下的“黑羽”怪兽为对象可以发动。将该怪兽以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22837504,'霞之谷战士','只要此卡以表侧表示存在于我方场上，在伤害步骤结束时，将与此卡的战斗中未被破坏的对手怪兽返回至持有者手牌。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22842126,'泛神的帝王',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：从手牌将1张“帝王”魔法・陷阱卡送至墓地可以发动。自己抽2张。\r\n②：将墓地的此卡除外可以发动。从牌组将3张“帝王”魔法・陷阱卡出示给对手，对手从其中挑选1张。将该1张卡加入自己的手牌，剩余的放回牌组。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22842214,'海洋枪兵','只要此卡以表侧表示存在于场上，仅限１次，可选择从游戏中被除外的任意数量的我方鱼族、海龙族、水族怪兽，将其视为装备卡装备在此卡。以此效果装备怪兽的场合，此卡的攻击力上升１０００点。此外，场上的此卡被破坏的场合，破坏以此卡效果装备的１只怪兽作为代替。','装备怪兽','是否要使用「海洋枪兵」的效果代替破坏？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22850702,'混沌天使－混元的双翼－',replace(replace('协调＋协调以外的光・暗属性怪兽1只以上\r\n要同步召唤此卡的情况下，可将自己场上的1只光・暗属性怪兽视为协调。\r\n①：此卡特殊召唤的情况下，以场上的1张卡为对象可以发动。将该卡除外。\r\n②：根据作为此卡的同步素材的怪兽的原本属性，此卡获得以下效果。\r\n●光：自己场上的同步怪兽不受对手发动的怪兽效果影响。\r\n●暗：自己的怪兽不会因战斗被破坏。','\r',char(13)),'\n',char(10)),'光属性怪兽为同步素材','暗属性怪兽为同步素材','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22850703,'混沌天使－混元的双翼－',replace(replace('协调＋协调以外的光・暗属性怪兽1只以上\r\n要同步召唤此卡的情况下，可将自己场上的1只光・暗属性怪兽视为协调。\r\n①：此卡特殊召唤的情况下，以场上的1张卡为对象可以发动。将该卡除外。\r\n②：根据作为此卡的同步素材的怪兽的原本属性，此卡获得以下效果。\r\n●光：自己场上的同步怪兽不受对手发动的怪兽效果影响。\r\n●暗：自己的怪兽不会因战斗被破坏。','\r',char(13)),'\n',char(10)),'光属性怪兽为同步素材','暗属性怪兽为同步素材','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22855882,'受诅咒的魔剑','据说配戴它并战胜诅咒者就能获得力量。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22858242,'猿魔王泽曼',replace(replace('暗属性协调＋协调以外的兽族怪兽１只\r\n此卡攻击的场合，直至伤害步骤结束时，对手不可发动魔法、陷阱卡。对手怪兽的攻击宣言时，可将我方手牌、场上的１只怪兽送入墓地，并选择１只该攻击怪兽发动。使该攻击无效。','\r',char(13)),'\n',char(10)),'攻击无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22862454,'代理龙',replace(replace('怪兽2只\r\n①：自己场上的卡将被战斗・效果破坏的情况下，可破坏此卡连接端的1只自己的怪兽作为代替。','\r',char(13)),'\n',char(10)),'是否使用「代理龙」的效果代替破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22865492,'幻影－英雄 增量',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：自己因战斗・效果受到伤害的情况下可以发动。将墓地的此卡视为永续陷阱卡，以表侧表示放在自己的魔法与陷阱区域。\r\n②：此卡视为永续陷阱卡的情况下，在自己・对手的主要阶段，解放自己场上的1只“－英雄”怪兽可以发动。将此卡特殊召唤。\r\n③：此卡从魔法与陷阱区域特殊召唤的情况下可以发动。从牌组将1只等级4以下的“幻影－英雄”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'此卡当作永续陷阱卡放置','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22866836,'超原地转向',replace(replace('①：可从以下效果中选择１个发动。\r\n●以自己场上的１只攻击表示的机械族・地属性超量怪兽和对手场上的１只怪兽为对象可以发动。变更该自己的怪兽的表示形式，将该对手的怪兽破坏。\r\n●以自己场上的１只守备表示的机械族・地属性超量怪兽和对手场上的１张魔法・陷阱卡为对象可以发动。变更该自己的怪兽的表示形式，将该对手的魔法・陷阱卡破坏。','\r',char(13)),'\n',char(10)),'破坏对手怪兽','破坏对手魔陷','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22869904,'魔力诱爆','对手魔法与陷阱区域表侧表示存在的魔法卡被送入墓地的场合可发动。选择场上１只以表侧表示存在的怪兽并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22873798,'鬣狗','此卡因战斗被破坏并送入墓地时可发动。从牌组特殊召唤任意数量的“鬣狗”。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22888900,'纯灰色画的牢狱','①：有上级召唤・仪式召唤・融合召唤的任一的怪兽以表侧表示存在于自己场上的情况下可以发动。直至下个对手回合结束时为止，双方不可进行同步・超量召唤，场上的同步・超量怪兽效果无效化，不可攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22900219,'恐龙摔跤手・奇美拉・角力暴龙',replace(replace('“恐龙摔跤手”连接怪兽＋“恐龙摔跤手”怪兽\r\n①：此卡进行战斗的情况下，对手直至伤害步骤结束时为止，不可发动魔法・陷阱卡。\r\n②：此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。\r\n③：对手怪兽不可将其他怪兽选择为攻击对象。\r\n④：此卡战斗破坏怪兽的情况下发动。此卡的攻击力上升500。\r\n⑤：此卡因效果被破坏的情况下发动。将对手的攻击表示的怪兽全部破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22900598,'吸血鬼移地','此卡名的卡１回合仅可发动１张。①：自己的场地区域不存在卡，且自己场上表侧表示的怪兽仅有不死族怪兽的情况下可以发动。从牌组挑选１张“吸血鬼帝国”发动。然后，可从自己的墓地挑选１只暗属性的“吸血鬼”怪兽以守备表示特殊召唤。','是否要从墓地选1只名字带有「吸血鬼」的暗属性怪兽表侧守备表示特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22908820,'元素－英雄 日升侠',replace(replace('属性不同的“－英雄”怪兽×2\r\n此卡仅可通过融合召唤方式特殊召唤。\r\n此卡名的①③效果1回合仅可各使用1次。\r\n①：此卡特殊召唤的情况下可以发动。从牌组将1张“奇迹结合”加入手牌。\r\n②：自己场上的怪兽的攻击力上升自己场上怪兽属性的种类×200的数值。\r\n③：自己的其他“－英雄”怪兽进行战斗的攻击宣言时，以场上的1张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22910685,'绿树灵王','生活在绿树环绕的树林中统治森林的年少王者。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22912101,'萨吉・雷盟',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：向对手出示手牌的此卡，以场上的1只怪兽为对象可以发动。将该怪兽破坏，从手牌将1只雷族怪兽特殊召唤。此回合，自己不可从手牌以外的地方特殊召唤效果怪兽。\r\n②：此卡存在于怪兽区域的状态下，此卡以外的卡因效果被破坏的情况下可以发动。从牌组将“萨吉・雷盟”以外的1只“雷盟”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','检索效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22916281,'被星杯选中者',replace(replace('用机怪残骸武装自己、内心坦率真诚的少年。\r\n一直对星辰之森自古流传的“星之勇者”心怀向往，受妖精丽丝之托，与被授予光的伙伴们踏上旅程，去解放共七件星遗物。\r\n“星光之勇者 挥剑聚光 驱除那巨大的黑暗吧”','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22916418,'超人传－披风侠',replace(replace('此卡名的①③效果1回合仅可各使用1次。\r\n①：原本持有者为自己的表侧表示卡存在于对手场上的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：只要此卡存在于怪兽区域，不可解放，不会因战斗被破坏。\r\n③：此卡召唤・特殊召唤的回合的结束阶段可以发动。将此卡放回牌组最下面。然后，可将1张原本持有者为自己的、场上的表侧表示卡放回手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','回到牌组','是否选卡回到手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22923081,'黑之魔导战士 破坏者','此卡名的④效果1回合仅可使用1次。①：此卡召唤成功的情况下发动。在此卡上放2个魔力计数物。②：此卡灵摆召唤成功的情况下发动。在此卡上放3个魔力计数物。③：此卡的攻击力上升相当于此卡魔力计数物数量×400的数值。④：去除此卡的1个魔力计数物，以场上的1张魔法・陷阱卡为对象可以发动。将该卡破坏。','放置魔力计数物','放置魔力计数物','破坏一张魔法陷阱卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22933016,'-艾-待机重生','此卡名的①②效果1回合仅可各使用1次。①：以自己墓地的1只“＠伊格尼斯者”怪兽为对象可以发动。将该怪兽特殊召唤。此卡发动后，直至回合结束时为止自己仅可特殊召唤电子界族怪兽。②：怪兽之间进行战斗的攻击宣言时，将墓地的此卡和1张手牌除外，从自己墓地的卡及自己被除外的卡中，以“-艾-待机重生”以外的1张“-艾-”魔法・陷阱卡为对象可以发动。将该卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22938501,'再世名讳导神 摄墨斯',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次，且②③效果1回合仅可各使用1次。\r\n①：场上存在原本攻击力或原本守备力为2500的怪兽的情况下，此卡可从手牌特殊召唤。\r\n②：对手发动卡的效果时，从自己手牌・场上（表侧表示）将此卡以外的1张“再世”卡送至墓地可以发动。将该发动无效并破坏。\r\n③：在此卡被送至墓地的对手回合，于结束阶段可以发动。将此卡加入手牌。','\r',char(13)),'\n',char(10)),'','无效','回收','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22953211,'铃猫战斗机',replace(replace('含衍生物在内的怪兽３只\r\n①：此卡在战斗中破坏对手怪兽时可发动。在我方场上以守备状态特殊召唤１只“铃猫衍生物”（机械族・风・星４・攻／守２０００）。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22953212,'铃猫衍生物','由“铃猫战斗机”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22959079,'异虫空洞','选择我方场上的１只怪兽发动此卡。将所选择怪兽从游戏中除外直至我方下个准备阶段。从游戏中除外的期间，不可使用该怪兽区域。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22970795,'白骨道君主',replace(replace('此卡名的②③效果１回合仅可各使用１次。\r\n①：此卡只要存在于墓地，卡名视为“白骨”。\r\n②：自己的墓地存在“白骨”或“白骨王”的情况下，将手牌・场上的此卡送至墓地可以发动。从自己的牌组上面将卡送至墓地，数量最多为自己墓地的“白骨”、“白骨王”的数量。\r\n③：将墓地的此卡除外，以自己墓地的１只“白骨”或“白骨王”为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'从牌组送至墓地','特殊召唤','请选择要送至墓地的卡的数量','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22984000,'生命之汞 墨丘利姆',replace(replace('等级10怪兽×2只以上\r\n此卡名的①效果1回合仅可使用1次。\r\n①：此卡超量召唤的情况下可以发动。从牌组将1只怪兽作为此卡的超量素材。\r\n②：只要持有超量素材的此卡存在于怪兽区域，与自己墓地的任一怪兽属性相同的、对手墓地的怪兽的效果就不可发动。\r\n③：在自己・对手的结束阶段发动。去除此卡的1个超量素材，或自己受到3000伤害。','\r',char(13)),'\n',char(10)),'获取超量素材','取除素材或伤害','是否要取除超量素材？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22991179,'无视加护','对手怪兽的攻击宣言时，可将我方墓地的１只昆虫族怪兽从游戏中除外并发动。使该攻击无效。','攻击无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22993208,'炎王的急袭',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：仅有对手场上才存在怪兽的情况下可以发动。从牌组将１只兽族・兽战士族・鸟兽族的炎属性怪兽特殊召唤。以此效果特殊召唤的怪兽的效果无效化，将在结束阶段被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(22996376,'百兽王 贝希摩斯','此卡可解放１只怪兽并上级召唤。以此方法上级召唤的此卡的原本攻击力变成２０００。此卡上级召唤成功时，可选择相当于解放数量的我方墓地的兽族怪兽返回至手牌。','把1只怪兽解放作上级召唤','返回手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23002292,'红灯重启',replace(replace('此卡也可支付一半LP来从手牌发动。\r\n①：对手发动陷阱卡时可以发动。将该发动无效，将该卡就此放置。然后，对手可从牌组将1张陷阱卡放置在自身的魔法与陷阱区域。此卡发动后，直至回合结束时为止对手不可发动陷阱卡。','\r',char(13)),'\n',char(10)),'是否从牌组放置陷阱卡？','适用「红灯重启」的效果来发动','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23008320,'呼叫共鸣者','①：从牌组将1只“共鸣者”怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23015896,'炎王神兽 迦楼多尼克斯',replace(replace('①：此卡因效果被破坏并被送至墓地的情况下，在下个准备阶段发动。从墓地将此卡特殊召唤。\r\n②：以此卡的①效果特殊召唤的情况下发动。将场上的其他怪兽全部破坏。\r\n③：此卡因战斗被破坏并被送至墓地时可以发动。从牌组将“炎王神兽 迦楼多尼克斯”以外的１只“炎王”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','怪兽破坏','牌组特召','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23020408,'魂之侍从',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：从自己手牌・牌组・墓地挑选除“魂之侍从”以外的、1只“黑魔导”或“黑魔导女孩”，或1张记载有其中的任一卡名的卡放在牌组最上面。\r\n②：在自己的主要阶段将墓地的此卡除外可以发动。自己依双方场上・墓地的“守护神官”怪兽、“黑魔导”、“黑魔导女孩”的种类数量抽牌。','\r',char(13)),'\n',char(10)),'','','请选择要放置在牌组最上面的卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23032273,'梅基拉斯之光','令人毛骨悚然的眼睛会释放出邪恶的光芒，对敌人造成伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23051413,'大植然锹形虫','１回合１次，可在此卡进行攻击的战斗步骤时开始直至伤害计算前为止，对手发动魔法、陷阱、怪兽的效果时，选择我方墓地的１只冠有“大植然”之名的怪兽并发动。从墓地特殊召唤被选择怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23064604,'冥帝厄瑞玻斯',replace(replace('此卡可以通过解放1只上级召唤的怪兽来上级召唤。\r\n①：此卡上级召唤的情况下可以发动。从手牌・牌组将2种“帝王”魔法・陷阱卡各1张送至墓地，从对手手牌・场上・墓地将1张卡放回牌组（从手牌是随机挑选）。\r\n②：此卡存在于墓地的情况下，1回合1次，在自己・对手的主要阶段，从手牌将1张“帝王”魔法・陷阱卡舍弃，以自己墓地的1只攻击力2400以上且守备力1000的怪兽为对象可以发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'把1只上级召唤的怪兽解放作上级召唤','从手牌·牌组把「帝王」魔法·陷阱卡2种类送至墓地，从对手的手牌·场上·墓地之中选1张卡回到牌组','以自己墓地1只攻击力2400以上而守备力1000的怪兽为对象可以发动。那只怪兽加入手牌','选对手的1张手牌回到牌组','选对手场上的1张卡回到牌组','选对手墓地的1张卡回到牌组','','','','','','','','','','');
INSERT INTO texts VALUES(23068051,'幽丽幻泷',replace(replace('①：可从以下效果中选择1个发动。\r\n●从牌组将1只幻龙族怪兽加入手牌。\r\n●从自己手牌・场上（表侧表示）将任意数量的幻龙族怪兽送至墓地可以发动。自己依送至墓地的怪兽数量＋1的张数抽牌。','\r',char(13)),'\n',char(10)),'牌组检索','送至墓地并抽牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23076639,'幻爪之王 加赛尔',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将１只恶魔族・等级５怪兽或１张“客迈拉结合”加入手牌。\r\n②：此卡作为融合召唤的素材被送至墓地的情况下可以发动。从牌组将１只幻想魔族怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23085002,'编号68 魔天牢 桑达丰',replace(replace('等级８怪兽×２\r\n①：此卡的攻击力・守备力上升相当于双方墓地怪兽数量×１００的数值。\r\n②：１回合１次，去除此卡的１个超量素材可以发动。直至对手回合结束时为止，此卡不会因效果被破坏，双方不可特殊召唤墓地的怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23087070,'蔷薇女巫','上级召唤植物族怪兽的场合，此卡可释放２只数量。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23093373,'天魔之声选姬・华耳琴璃',replace(replace('此卡名的①③效果１回合仅可各使用１次。\r\n①：此卡召唤・灵摆召唤的情况下可以发动。从牌组将“天魔之声选姬・华耳琴璃”以外的１张“华耳琴璃”卡加入手牌。\r\n②：只要自己场上存在“天魔之声选姬・华耳琴璃”以外的怪兽，对手怪兽不可将此卡选择为攻击对象。\r\n③：此卡被送至墓地的情况下，如果自己的灵摆区域存在２张“华耳琴璃”卡则可以发动。将此卡加入手牌。','\r',char(13)),'\n',char(10)),'检索「华耳琴璃」卡','此卡加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23093604,'X－军刀 帕修尔',replace(replace('①：此卡不会因战斗被破坏。\r\n②：在对手的准备阶段发动（此效果在此卡以表侧守备表示存在于怪兽区域的情况下才能发动和处理）。自己受到1000伤害。','\r',char(13)),'\n',char(10)),'自己受到1000伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23099524,'法老降临',replace(replace('此卡名的①③效果１回合仅可各使用１次。\r\n①：解放自己场上的１只怪兽可以发动。从手牌将此卡特殊召唤。\r\n②：此卡的攻击力上升相当于双方场上・墓地的永续陷阱卡的数量×３００的数值。\r\n③：解放自己场上的１只天使族・恶魔族・爬虫类族怪兽可以发动。从牌组将１张永续陷阱卡加入手牌。此效果发动后，直至回合结束时为止，自己不可特殊召唤怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23115241,'X－军刀 安娜佩雷拉','X－军刀的女战士，她以华丽的攻击及冷静的判断飞舞在战场。时而冷酷的攻击令敌人畏惧。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23116808,'怨念之魂 业火','我方场上存在炎属性怪兽的场合，可从手牌特殊召唤此卡。以此方法特殊召唤成功时，选择我方场上１只炎属性怪兽破坏。在我方准备阶段时，以守备表示特殊召唤１只“火球衍生物”（炎族、炎、星１、攻／守１００）至我方场上。此外，可解放我方场上１只除此卡以外的炎属性怪兽发动。直至回合结束时，此卡的攻击力上升５００点。','破坏','特殊召唤','攻击上升','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23116809,'火球衍生物','由「怨念之魂 业火」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23118924,'元素魔鬼',replace(replace('当场上有特定属性的怪兽存在的场合，此怪兽获得以下效果。\r\n●地属性：此卡通过战斗破坏的效果怪兽的效果无效。\r\n●风属性：此卡通过战斗破坏对手怪兽的场合，可再进行一次攻击。','\r',char(13)),'\n',char(10)),'连续攻击','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23122036,'阴谋之盾','可选择我方场上的１只表侧表示怪兽发动此卡。此卡被视为装备卡，装备在被选择的我方怪兽。装备怪兽为攻击表示的场合，１回合仅限１次不会因战斗而被破坏。此外，因装备怪兽的战斗而发生的给予我方的战斗伤害变成０。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23147658,'风化战士',replace(replace('此卡名的效果①在1个回合中仅可使用1次。\r\n①：此卡在因效果被送至墓地时或因战斗被破坏时可以发动。从牌组中将1张写有除“风化战士”以外的“化石融合”卡名的卡或“化石融合”卡加入手牌。\r\n②：在自己的结束阶段发动。此卡的攻击力下降600。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23151193,'断罪之迪亚贝尔斯塔',replace(replace('此卡名在规则上也视为“罪宝”卡。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：从自己手牌・墓地将魔法卡和陷阱卡各1张除外可以发动。从手牌・墓地将此卡特殊召唤。\r\n②：在自己・对手回合中，支付一半LP，以对手场上的1张卡为对象可以发动。将该卡破坏。然后，场上存在其他的“迪亚贝尔”怪兽卡的情况下，可从额外牌组将1只幻想魔族・魔法师族同步怪兽的协调特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','破坏效果','是否特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23153227,'七皇升格',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从牌组挑选以下卡中的任意1张，加入手牌或放在牌组最上面。\r\n●“七皇升格”以外的“七皇”魔法・陷阱卡\r\n●“巴利安之”魔法・陷阱卡\r\n●“升阶魔法”速攻魔法卡\r\n②：对手场上存在被从额外牌组特殊召唤的怪兽的情况下，将墓地的此卡除外，从手牌将1张“升阶魔法”魔法卡送至墓地可以发动。适用该魔法卡发动时的效果。','\r',char(13)),'\n',char(10)),'牌组检索','复制升阶魔法','在牌组最上面放置','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23153228,'七皇升格',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从牌组挑选以下卡中的任意1张，加入手牌或放在牌组最上面。\r\n●“七皇升格”以外的“七皇”魔法・陷阱卡\r\n●“巴利安之”魔法・陷阱卡\r\n●“升阶魔法”速攻魔法卡\r\n②：对手场上存在被从额外牌组特殊召唤的怪兽的情况下，将墓地的此卡除外，从手牌将1张“升阶魔法”魔法卡送至墓地可以发动。适用该魔法卡发动时的效果。','\r',char(13)),'\n',char(10)),'牌组检索','复制升阶魔法','在牌组最上面放置','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23160024,'无形假面',replace(replace('①：场上的“无形噬体”怪兽的攻击力・守备力上升３００。\r\n②：只要此卡存在于场地区域，每次自己场上的“无形噬体”怪兽被解放，自己从牌组抽１张。此效果１回合最多可适用２次。\r\n③：将墓地的此卡除外可以发动。为使等级合计为８，从自己的手牌・场上解放灵摆怪兽，从手牌将“虚龙魔王无形因子 心”仪式召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23166823,'影灵兽使－源质温蒂',replace(replace('←7 【灵摆】 7→\r\n①：自己仅可灵摆召唤“灵兽”怪兽及“源质”怪兽。此效果不会被无效化。\r\n【怪兽效果】\r\n自己１回合仅可特殊召唤１次“影灵兽使－源质温蒂”。\n①：此卡召唤・灵摆召唤时可以发动。从自己的额外牌组（表侧）将“影灵兽使－源质温蒂”以外的１只“源质”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23168060,'钥匙战士基曼','１回合１次，可在我方主要阶段时发动。直至回合结束时此卡的等级变成３。','等级变换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23171610,'限制解除','①：自己场上的所有机械族怪兽的攻击力直至回合结束时为止变为两倍。在此回合的结束阶段，适用了此效果的怪兽将被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23171611,'限制解除','①：自己场上的所有机械族怪兽的攻击力直至回合结束时为止变为两倍。在此回合的结束阶段，适用了此效果的怪兽将被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23187256,'编号93 希望皇霍普・凯撒',replace(replace('拥有超量素材的相同阶级“编号”超量怪兽×２只以上\r\n①：１回合１次，在自己的主要阶段可以发动。从额外牌组将阶级９以下、攻击力３０００以下的“编号”怪兽效果无效并特殊召唤（同阶级最多１只），数量最多为此卡超量素材种类的数量。然后去除此卡的１个超量素材。此回合，对手受到的战斗伤害变为一半，自己不可特殊召唤怪兽。②：只要自己场上有其他“编号”超量怪兽存在，此卡不会因战斗・效果被破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','继续特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23204029,'对极－英雄 混沌',replace(replace('“假面－英雄”怪兽×2\r\n此卡名在规则上也视为“元素－英雄”卡。\r\n此卡仅可通过融合召唤方式特殊召唤。\r\n①：只要此卡存在于怪兽区域，此卡的属性也视为“光”。\r\n②：在每个自己・对手回合中1次，以场上的1张表侧表示卡为对象可以发动。将该卡的效果直至回合结束时为止无效。','\r',char(13)),'\n',char(10)),'效果无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23205979,'削魂的死灵','①：此卡不会因战斗被破坏。②：此卡以直接攻击给予对手战斗伤害的情况下发动。随机挑选对手的１张手牌舍弃。③：场上表侧表示的此卡成为效果的对象的情况下将被破坏。','丢弃手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23212990,'六武式风雷斩',replace(replace('①：去除自己场上的１个武士道计数物，可从以下效果中选择１个发动。\r\n●以对手场上的１只怪兽为对象可以发动。将该对手的怪兽破坏。\r\n●以对手场上的１张卡为对象可以发动。将该对手的卡放回手牌。','\r',char(13)),'\n',char(10)),'对手场上存在的1只怪兽破坏。','对手场上存在的1张卡回到手牌。','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23213239,'激荡之未界域','此卡名的②效果1回合仅可使用1次。①：自己的“未界域”怪兽因与对手怪兽的战斗被破坏时可以发动。将该对手的怪兽破坏。②：从自己的墓地将3种“未界域”魔法・陷阱卡各1张除外可以发动。将场上的卡全部破坏。此效果发动后，直至回合结束时为止自己仅可特殊召唤“未界域”怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23219323,'废品战士／爆裂',replace(replace('此卡不可通常召唤，仅可通过“爆裂模式”的效果特殊召唤。\r\n①：此卡的攻击力上升相当于自己场上的“／爆裂”怪兽的数量×1000的数值，此卡与怪兽的战斗给予对手的战斗伤害变为两倍。\r\n②：场上的此卡不受对手发动的怪兽的效果影响。\r\n③：此卡被破坏的情况下，以自己墓地的1只“废品战士”为对象可以发动。将该怪兽放回额外牌组。然后，可将该怪兽视为同步召唤特殊召唤。','\r',char(13)),'\n',char(10)),'回到牌组','是否特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23220533,'圣夜骑士团・圣光',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡召唤成功时可以发动。从牌组将１张“圣夜骑士团”魔法・陷阱卡加入手牌。\r\n②：将墓地的此卡除外，以“圣夜骑士团・圣光”以外的自己墓地的１只“圣夜骑士团”怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23220863,'苏鲁伯的魔导骑兵',replace(replace('←3 【灵摆】 3→\r\n【怪兽效果】\r\n①：只要此卡存在于怪兽区，不会受除灵摆怪兽以外的怪兽所发动之效果的影响。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23232295,'燃烧拳斗士 拘束蛮兵 前导刺拳',replace(replace('等级４“燃烧拳斗士”怪兽×２\r\n①：自己场上的“燃烧拳斗士”怪兽将被战斗・效果破坏的情况下，作为该“燃烧拳斗士”怪兽中１只的代替，可去除此卡的１个超量素材。\r\n②：此卡的超量素材被去除的情况下发动。此卡的攻击力上升８００。','\r',char(13)),'\n',char(10)),'攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23234094,'进化龙・双腔龙','①：此卡以“进化虫”怪兽的效果特殊召唤时可以发动。从手牌将１只恐龙族・炎属性・等级６以下的怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23249029,'天魔伏圣剑',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：装备怪兽的攻击力・守备力上升自己场上・墓地的装备魔法卡的数量×200的数值。\r\n②：此卡装备于战士族怪兽的情况下可以发动。从牌组将与装备怪兽卡名不同、属性・等级相同的1只战士族怪兽特殊召唤，将此卡装备于该怪兽。然后，将原先装备此卡的怪兽破坏。此效果发动后，直至回合结束时为止自己仅可特殊召唤战士族怪兽。','\r',char(13)),'\n',char(10)),'','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23265313,'降低代价','弃置１张手牌。我方手牌中所有怪兽卡的等级下降２直到发动回合的结束阶段。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23265594,'强化支援战机・重装兵器','１回合１次，可在我方的主要阶段时，将此卡作为装备卡装备至我方场上的机械族怪兽上，或者解除装备状态以表侧攻击表示特殊召唤此卡。以此效果变为装备卡的场合，装备怪兽的攻击力和守备力上升５００点。（１只怪兽最多只可装备１张联合。当装备怪兽被破坏的场合，破坏此卡来代替。）','装备','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23269426,'最后的同调','①：以自己场上的１只等级３怪兽为对象可以发动。从自己的手牌・墓地将１只该同名怪兽特殊召唤。以此效果特殊召唤的怪兽的效果无效化。对象怪兽将在此回合的结束阶段被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23270035,'怪兽分类','此卡名的卡１回合仅可发动１张。①：从牌组挑选种族・属性・等级相同的１只通常怪兽和１只效果怪兽出示给对手，对手从中随机挑选１只。将该１只怪兽加入自己的手牌，剩余的放回牌组。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23274061,'电力花栗鼠','此卡在１次的战斗阶段中可攻击２次。与此卡进行过战斗的怪兽的效果在伤害计算后无效化。','效果无效化','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23282832,'超越限制','可支付５００LP发动。尽可能地将此回合因战斗被破坏并送入墓地的攻击力是１０００或以下的通常怪兽特殊召唤至我方场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23288411,'冥骸合龙－冥铭途拉尔泰库特利卡',replace(replace('此卡不可通常召唤。\r\n仅在将自己的手牌・墓地的此卡以外的５种“冥铭途”怪兽各１只放回牌组・额外牌组的情况下，可从手牌・墓地特殊召唤。\r\n①：自己场上不存在其他怪兽的情况下，此卡可攻击所有对手怪兽各１次。\r\n②：１回合１次，对手发动魔法・陷阱・怪兽的效果的情况下可以发动。从自己的手牌・墓地将１只“冥铭途”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23289281,'空手道家','１回合１次，可在我方主要阶段时发动。此卡的攻击力直到结束阶段时变成原本攻击力２倍的数值。使用此效果的场合，此卡在结束阶段时被破坏。','攻击变换','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23296404,'点火骑士・复仇者',replace(replace('①：以自己场上的３张“点火骑士”卡为对象可以发动。将该卡破坏，从手牌将此卡特殊召唤。\r\n②：１回合１次，以自己场上１只其他的“点火骑士”怪兽为对象可以发动。将该卡放回手牌，将对手场上的１张魔法・陷阱卡放回牌组最下面。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23297235,'炎狱地狱犬','①：这张卡在战斗中破坏对手怪兽并将其送至墓地时可以发动。从牌组中特殊召唤1只“炎狱地狱犬”以外的守备力200以下的炎属性怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23299957,'交通机人连接区','①：从我方手牌、场上将因“交通机人”融合怪兽卡而规定的融合素材怪兽送入墓地，从额外牌组融合召唤１只该融合怪兽。以此效果特殊召唤的怪兽不会因效果而被破坏，该怪兽的效果不会被无效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23303072,'合成龙','此卡不可通常召唤。仅限从手牌将３只怪兽送入墓地的场合可特殊召唤。此卡的攻击力变成送入墓地怪兽的等级合计×３００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23309606,'炎狱魔人 地狱焚魔','通常召唤此卡的场合，将除此卡以外的我方手牌全部舍弃至墓地，并必须解放自己场上的１只攻击力２０００以上的怪兽。此卡的攻击力上升对手场上怪兽数量×２００点，下降除此卡以外的我方场上怪兽数量×５００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23314220,'噶尔德之魔导书',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：将“噶尔德之魔导书”以外的、自己手牌・场上（表侧表示）的1张“魔导书”卡或自己场上的1只表侧表示的魔法师族怪兽送至墓地，自己抽2张。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23323812,'念导力','我方场上的念动力族怪兽因对手怪兽的攻击被破坏时，可发动。选择１只该对手怪兽破坏，并回复相当于该攻击力数值的我方LP。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23327298,'平行选择','我方场上表侧表示的同步怪兽因对手被破坏并送入墓地时，可选择１张从游戏中被除外的我方魔法卡并发动。将被选择的魔法卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23331400,'连接流',replace(replace('此卡牌名的效果１回合只可使用１次。\r\n①：此卡已存在于怪兽区的状态下，电子界族怪兽被召唤・特殊召唤至我方场上时可发动。特殊召唤１只“数据衍生物”（电子界族・光・星１、攻／守０）至我方场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23331401,'数据衍生物','由“连接流”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23338098,'强袭黑羽－泪雨之千鸟',replace(replace('协调＋协调以外的怪兽1只以上\r\n①：以“黑羽”怪兽作为素材同步召唤的此卡视为协调。\r\n②：此卡的攻击力上升自己墓地的“黑羽”怪兽数量×300的数值。\r\n③：此卡被破坏并被送至墓地时，以“强袭黑羽－泪雨之千鸟”以外的、自己墓地的1只鸟兽族同步怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23361526,'高速疾行机人 软木塞枪',replace(replace('协调+1只以上协调以外的怪兽\r\n此卡名的效果1回合仅可使用1次，发动此效果的回合中，自己仅可特殊召唤风属性怪兽。①：此卡同步召唤成功的情况下，可从以下效果中选择1个发动。\r\n●从牌组将1张“疾行机人”魔法・陷阱卡加入手牌。\r\n●此卡仅以“疾行机人”怪兽作为素材同步召唤的情况下，如果该同步召唤所使用到的一组同步素材怪兽全部都在自己的墓地，将该一组特殊召唤。','\r',char(13)),'\n',char(10)),'选择效果发动','牌组检索','特殊召唤素材','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23377425,'超元特防队 桥头堡','此卡名的卡１回合仅可发动１张，此卡名的②效果１回合仅可使用１次。①：作为此卡发动时的效果处理，可从牌组将１只“超元特防队”怪兽加入手牌。②：对手怪兽对同一纵列的、自己的“超元特防队”怪兽攻击宣言时可以发动。自己的该怪兽不会因战斗被破坏。','是否从牌组把1只「超元特防队」怪兽加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23377694,'娱乐伙伴房东寄居蟹',replace(replace('←2 【灵摆】 2→\r\n①：１回合１次，我方“娱乐伙伴”怪兽因战斗被破坏时，可以我方灵摆区的１张“娱乐伙伴”卡牌或“异色眼”卡牌为对象发动。特殊召唤该卡。\r\n【怪兽效果】\r\n①：１回合１次，可以我方场上的１只灵摆怪兽为对象发动。直至回合结束时，该怪兽的攻击力上升相当于我方场上“娱乐伙伴”怪兽的数量×３００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23379054,'劫火之舟守 幽灵卡戎','此卡名的效果１回合仅可使用１次，发动此效果的回合中，自己仅可特殊召唤龙族怪兽。①：对手场上存在怪兽、自己场上不存在此卡以外的怪兽的情况下，以自己墓地的１只融合怪兽为对象可以发动。将墓地的该怪兽和场上的此卡除外，将１只拥有与该２只等级合计相同等级的龙族同步怪兽从额外牌组特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23384666,'机巧蛙－磐盾多迩具久','此卡名的①②效果１回合仅可各使用１次。①：此卡召唤・特殊召唤成功的情况下可以发动。从牌组挑选１只攻击力和守备力的数值相同的机械族怪兽，放在牌组最上面。②：将墓地的此卡除外，以自己墓地１只攻击力和守备力的数值相同的机械族怪兽为对象可以发动。以守备表示形式将该怪兽特殊召唤。','','','请选择要放置到牌组最上面的卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23401839,'千手之神','①：此卡召唤・反转召唤时可以发动。从牌组将１只仪式怪兽加入手牌。','选择1张仪式怪兽卡加入自己手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23401840,'千手之神','①：此卡召唤・反转召唤时可以发动。从牌组将１只仪式怪兽加入手牌。','选择1张仪式怪兽卡加入自己手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23408872,'替换蛙','①：1回合1次，解放自己场上的1只水族怪兽，以自己墓地的1只“青蛙”怪兽为对象可以发动。将该怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23421244,'复活僵尸','我方手牌为０张的场合，以攻击表示的此卡不会因战斗而被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23424603,'荒野','所有恐龙族・不死族・岩石族怪兽的攻击力和守备力上升２００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23431858,'天威龙－暝虚堕','此卡名的①②效果1回合仅可各使用1次。①：自己场上没有效果怪兽存在的情况下可以发动。从手牌将此卡特殊召唤。②：自己场上有效果怪兽以外的表侧表示怪兽存在的情况下，将手牌・墓地的此卡除外，以对手场上的1张卡为对象可以发动。将该卡放回持有者的手牌。','特殊召唤','对方卡回到手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23434538,'增殖的Z',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：在自己・对手回合中，从手牌将此卡送至墓地可以发动。在此回合中适用以下效果。\r\n●对手每次特殊召唤怪兽，自己抽1张。','\r',char(13)),'\n',char(10)),'对手特殊召唤时抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23434539,'增殖的Z',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：在自己・对手回合中，从手牌将此卡送至墓地可以发动。在此回合中适用以下效果。\r\n●对手每次特殊召唤怪兽，自己抽1张。','\r',char(13)),'\n',char(10)),'对手特殊召唤时抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23440062,'邪恶重生','可支付８００LP，选择我方墓地的１只同步怪兽并发动此卡。以攻击表示特殊召唤被选择怪兽。以此效果特殊召唤怪兽的效果被无效化，且此回合不可进行攻击宣言。此卡从场上离开时，破坏该怪兽。该怪兽被破坏时破坏此卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23440231,'狱炎机・莉莉丝',replace(replace('此卡不可通常召唤。\r\n仅可在自己场上的效果怪兽的等级・阶级的合计为８以下时，将自己的手牌・墓地的３只“狱炎机”怪兽除外的情况下从手牌・墓地特殊召唤。\r\n①：此卡特殊召唤时可以发动。将场上“炼狱”卡以外的魔法・陷阱卡全部破坏。\r\n②：１回合１次，此卡以外的怪兽的效果发动时，解放自己场上的１只怪兽可以发动。将该发动无效并除外。','\r',char(13)),'\n',char(10)),'效果无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23442438,'同步追走','此卡名的①效果1回合仅可使用1次。①：自己将“战士”、“同步士”、“星尘”同步怪兽同步召唤成功的情况下，以自己墓地的1只作为该同步召唤素材的怪兽为对象可以发动。以守备表示形式将该怪兽特殊召唤。②：只要此卡存在于魔法与陷阱区域，应对原本卡名中包含“战士”、“同步士”、“星尘”中任一的自己的同步怪兽的效果发动，对手不可发动魔法・陷阱・怪兽的效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23446369,'幻惑之眼',replace(replace('①：自己场上存在幻想魔族或魔法师族怪兽的情况下，可从以下效果中选择1个发动。\r\n●此回合中，自己的幻想魔族・魔法师族怪兽不会因战斗被破坏。\r\n●在对手回合中，以对手场上的1只表侧表示怪兽为对象可以发动。获得该怪兽的控制权直至结束阶段为止。\r\n●对手怪兽攻击宣言时，以攻击怪兽以外的对手场上的1只表侧表示怪兽为对象可以发动。攻击对象移换为该怪兽并进行伤害计算。','\r',char(13)),'\n',char(10)),'','不会被战斗破坏','得到控制权','攻击对象转移','','','','','','','','','','','','');
INSERT INTO texts VALUES(23454876,'混沌超量 黑暗妖精啦啦队女孩',replace(replace('等级５怪兽×３\r\n此卡被从场上送至墓地时，从牌组抽１张卡。此外，此卡有“妖精啦啦队女孩”在作为超量素材的情况下，获得以下效果。\r\n●此卡以战斗破坏对手怪兽时，去除此卡的１个超量素材可以发动。给予对手生命值相当于自己手牌数量×４００点的伤害。','\r',char(13)),'\n',char(10)),'抽牌','LP伤害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23459650,'奈芙蒂斯的轮回','①：为使合计等级为仪式召唤的怪兽的等级以上，解放自己的手牌・场上的怪兽，从手牌将１只“奈芙蒂斯”仪式怪兽仪式召唤。解放“奈芙蒂斯的祭祀者”或“奈芙蒂斯之苍凰神”来仪式召唤的情况下，可进而将场上的１张卡破坏。','是否把卡破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23469398,'机甲部队・空袭机','此卡名的①②效果１回合仅可各使用１次。①：从手牌将此卡以外的１只“机甲部队”怪兽舍弃可以发动。从手牌将此卡特殊召唤。②：在对手回合中，以自己场上的１只机械族怪兽为对象可以发动。从牌组将１只卡名与该怪兽不同、拥有该怪兽的等级以下等级的“机甲部队”怪兽特殊召唤，破坏对象怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23471572,'索罗门的律法书','跳过下一个我方准备阶段。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23499963,'守宝团・观察',replace(replace('此卡名的卡１回合仅可发动１张。①：从牌组将１张“大砂海 黄金的戈尔钢达”加入手牌。自己的场地区域有“大砂海 黄金的戈尔钢达”存在的情况下，可适用以下效果作为代替。\r\n●从牌组将１只“守宝团”怪兽加入手牌，从牌组将１只“守宝团”怪兽送至墓地。','\r',char(13)),'\n',char(10)),'是否检索「守宝团」怪兽？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23512906,'黄金荣耀－里昂',replace(replace('此卡名的①②③效果１回合仅可各使用１次。\r\n①：自己的LP少于对手的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下，以自己墓地的１只战士族以外的“黄金荣耀”怪兽为对象可以发动。将该怪兽以守备表示特殊召唤。此效果发动后，直至回合结束时为止，自己从额外牌组仅可特殊召唤“黄金荣耀”怪兽。\r\n③：在对手的主要阶段可以发动。仅以自己场上的“黄金荣耀”怪兽作为素材，进行同步召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23516703,'召唤限制器','①：此回合中召唤・反转召唤・特殊召唤怪兽合计成功２次以上的玩家，只要此卡存在于魔法与陷阱区域，不可召唤・反转召唤・特殊召唤怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23526128,'雷盟－回击电冲',replace(replace('此卡名的②③效果1回合仅可各使用1次。\r\n①：只要此卡存在于魔法与陷阱区域，自己场上的“雷盟”怪兽不会因对手的效果被破坏。\r\n②：对手发动魔法卡的效果时，将自己场上的1只“雷盟”怪兽放回手牌可以发动。将该效果无效并破坏。\r\n③：将墓地的此卡除外，以自己场上・墓地的1只“雷盟”怪兽为对象可以发动。将该怪兽放回手牌。','\r',char(13)),'\n',char(10)),'','效果无效','回收怪兽','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23530726,'闪术兵器－S.P.E.C.T.R.A.',replace(replace('包含连接怪兽在内的怪兽2只以上\r\n此卡名在规则上也视为“闪刀姬”卡。\r\n此卡从额外牌组仅可通过连接召唤来特殊召唤。\r\n此卡名的①效果1回合仅可使用1次。\r\n①：对手在连锁2以后发动魔法・陷阱・怪兽的效果时，从自己手牌・墓地将2张魔法卡除外可以发动。将该效果无效。然后，可将对手场上的1张卡破坏。\r\n②：自己墓地不存在魔法卡的情况下，此卡的攻击力下降3000。','\r',char(13)),'\n',char(10)),'效果无效','是否破坏对手场上的卡？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23535429,'牙城守护者','自己场上以守备表示存在的怪兽被攻击的情况下，该伤害步骤时将此卡从手牌送往墓地可以发动。进行该战斗的自己的怪兽的守备力直至回合结束时为止上升１５００点。','守备上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23536866,'间歇泉鲨',replace(replace('此卡名的效果１回合仅可使用１次。\r\n①：将墓地的此卡除外，以“间歇泉鲨”以外的、自己墓地的２只水属性・等级５怪兽为对象可以发动。将该２只怪兽效果无效并特殊召唤，仅以该２只作为素材进行１只水属性超量怪兽的超量召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23545031,'水精鳞－萨拉喀邃渊',replace(replace('鱼族・海龙族・水族怪兽２只\r\n此卡名的②③效果１回合仅可各使用１次。\r\n①：此卡的连接端的怪兽的攻击力・守备力上升５００。\r\n②：在对手回合中，将１张手牌送至墓地可以发动。从牌组将１只“水精鳞”怪兽加入手牌。\r\n③：此卡因对手怪兽的攻击或对手的效果被破坏的情况下，从牌组将１只水属性怪兽送至墓地，以自己墓地的１只水属性怪兽为对象可以发动。将该怪兽以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23557835,'次元融合','支付２０００LP可以发动。双方玩家各自尽可能地特殊召唤被除外的自身怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23558733,'凤凰彼岸花','此卡仅可以“凤凰花种”或此卡的效果特殊召唤。此卡在发动攻击后的伤害计算后被破坏。我方场上的此卡被破坏并送入墓地时，给予对手生命８００点伤害。此外，我方结束阶段时，可将１只除此卡以外的我方墓地的植物族怪兽从游戏中除外并发动。从墓地以守备表示特殊召唤此卡。','对于对手800伤害','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23562407,'圣剑卡里班','仅限装备战士族怪兽。装备怪兽的攻击力上升５００点。此外，１回合１次，我方可回复５００LP。场上以表侧表示存在的此卡被破坏并送入墓地的场合，可选择我方场上１只冠有“圣骑士”之名的战士族怪兽装备此卡。“圣剑卡里班”的此效果１回合只可使用１次。此外，我方场上只可有１张“圣剑卡里班”以表侧表示存在。','回复LP','装备','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23571046,'螺丝刺猬','①：在自己的主要阶段可以发动。从墓地将此卡特殊召唤。此效果在协调存在于自己场上的情况下才能发动和处理。以此效果特殊召唤的此卡离开场上的情况下，将其除外。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23581825,'升阶魔法－削魂之力','①：支付一半的LP，以自己墓地的1只“急袭猛禽”超量怪兽为对象可以发动。将该怪兽特殊召唤，将1只阶级比该怪兽高2的超量怪兽重叠在对象怪兽上面，视为超量召唤从额外牌组特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23587624,'青天霹雳','①：对手场上存在怪兽，自己场上不存在怪兽的情况下可以发动。将１只原本等级为１０以下、不可通常召唤的怪兽无视召唤条件从手牌特殊召唤。以此效果特殊召唤的怪兽不受该怪兽以外的自己的卡的效果影响，将在下一个对手的结束阶段返回持有者的牌组。此回合，自己不可通常召唤・特殊召唤怪兽，对手将受到的所有伤害变为０。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23599634,'神艺援助－觉醒－',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：从牌组将1只“神艺”怪兽或“无垢者 墨迪乌斯”特殊召唤。此回合，自己发动包含融合召唤融合怪兽的效果在内的效果的情况下，该发动不会被无效化，该融合召唤成功时，对手不可发动卡的效果。\r\n②：将墓地的此卡除外，以自己场上的1只“神艺”怪兽为对象可以发动。将该怪兽放回手牌・额外牌组，将对手场上的1张卡破坏。','\r',char(13)),'\n',char(10)),'发动','回收','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23603403,'急袭猛禽－卫星炮猎鹰',replace(replace('鸟兽族等级8怪兽×2\r\n①：此卡以“急袭猛禽”怪兽作为素材超量召唤成功的情况下可以发动。将对手场上的所有魔法・陷阱卡破坏。应对此效果的发动，对手不可发动魔法・陷阱・怪兽的效果。②：去除此卡的1个超量素材，以对手场上的1只表侧表示怪兽为对象可以发动。该怪兽的攻击力下降相当于自己墓地“急袭猛禽”怪兽的数量×800的数值。此效果在对手回合中也可以发动。','\r',char(13)),'\n',char(10)),'魔陷破坏','攻击力下降','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23611122,'急雷之泥沼',replace(replace('此卡名的卡1回合仅可发动1张，此卡名的②效果1回合仅可使用1次。\r\n①：作为此卡发动时的效果处理，可适用以下效果。\r\n●挑选自己的1张手牌舍弃，从自己牌组・墓地将除所舍弃的卡以外的、拥有将自身作为怪兽特殊召唤的效果的1张永续陷阱卡放置在自己场上。\r\n②：自己场上的卡因战斗・效果被破坏，被送至墓地的情况下或以表侧被除外的情况下，以其中1张为对象可以发动。从牌组将1张该卡的同名卡加入手牌。','\r',char(13)),'\n',char(10)),'发动','是否丢弃手牌并放置陷阱？','检索','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23615409,'驱虫网','对手场上表侧表示的昆虫族怪兽不可进行攻击宣言。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23617756,'愤怒的业火 艾克佐德之炎',replace(replace('此卡名在规则上也视为“艾格佐德”卡。\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：自己场上存在等级１０以上的“艾克佐迪亚”怪兽的情况下可以发动。将对手场上的卡全部破坏。\r\n②：从墓地将不是在此回合被送至墓地的此卡除外，可从以下效果中选择１个发动。\r\n●从自己的牌组・墓地将１只“被封印”怪兽加入手牌。\r\n●将自己的墓地・除外状态的最多５只“被封印”怪兽放回牌组。','\r',char(13)),'\n',char(10)),'','检索「被封印」怪兽','回收「被封印」怪兽','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23619206,'死神鸟 西摩格','此卡名的①②效果1回合仅可各使用1次。①：此卡召唤成功时可以发动。从牌组将“死神鸟 西摩格”以外的1张“西摩格”卡送至墓地。②：此卡存在于墓地、对手的魔法与陷阱区域没有卡存在的情况下可以发动。将此卡以守备表示特殊召唤。以此效果特殊召唤的此卡离开场上的情况下，将其除外。此效果发动后，直至回合结束时为止自己仅可特殊召唤鸟兽族怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23623653,'精灵兽使 蕾拉',replace(replace('自己１回合仅可特殊召唤１次“精灵兽使 蕾拉”，其①②③效果１回合仅可各使用１次。\r\n①：从手牌将此卡舍弃可以发动。进行手牌的１只“灵兽”怪兽的召唤。\r\n②：自己场上的“灵兽”卡将被战斗・效果破坏的情况下，作为代替可将场上・墓地的此卡除外。\r\n③：此卡被除外的情况下可以发动。从牌组将“精灵兽使 蕾拉”以外的１只“灵兽”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'进行「灵兽」怪兽的召唤','从牌组特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23626223,'苦纹样的土像',replace(replace('①：此卡发动后变为效果怪兽（岩石族・地・星７・攻０／守２５００），特殊召唤至怪兽区域（也视为陷阱卡）。\r\n②：只要此卡以外的、视为怪兽的陷阱卡存在于怪兽区域，对手不可将以此卡的效果特殊召唤的此卡作为效果的对象。\r\n③：以此卡的效果特殊召唤的此卡存在，且自己的魔法与陷阱区域的卡被特殊召唤至怪兽区域的情况下，以场上的１张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'卡片破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23635815,'杰瑞豆人','名叫杰瑞的豆战士。虽然坚信自己是世界最强的战士，但实力却未可知。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23639291,'侵略云魔物','我方场上冠有“云魔物”之名的怪兽因自身效果被破坏并送入墓地时可发动。从我方墓地选择１只该怪兽以攻击表示特殊召唤，并在该怪兽放置１个雾计数物。以此效果特殊召唤的怪兽不会因卡牌效果变成守备表示。','「侵略云魔物」效果适用中','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23649496,'编号18 纹章祖 素徽',replace(replace('等级4怪兽×2\r\n此卡的①效果在同一连锁上仅可发动1次。\r\n①：在自己・对手回合中，场上存在2只以上同名怪兽的情况下，去除此卡的1个超量素材可以发动。挑选其中1只，将该怪兽以外的、该怪兽的同名怪兽全部破坏。\r\n②：对手不可召唤・反转召唤・特殊召唤以此卡的效果挑选的怪兽的同名怪兽。\r\n③：此卡被送至墓地的情况下可以发动。从牌组将2只“纹章兽”怪兽送至墓地。','\r',char(13)),'\n',char(10)),'破坏','送墓','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23656668,'重力御者',replace(replace('连接怪兽以外的额外怪兽区域的怪兽1只\r\n此卡在被连接召唤的回合不可作为连接素材。\r\n①：额外怪兽区域的此卡不会因与主要怪兽区域的怪兽的战斗被破坏。\r\n②：此卡与额外怪兽区域的对手怪兽进行战斗的伤害步骤开始时可以发动。将该对手怪兽和此卡放回牌组。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23657016,'幻禄天杯龙',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：用抽牌以外的方法将此卡加入手牌的情况下可以发动。将此卡视为协调特殊召唤。然后，此卡的等级可上升１。\r\n②：在自己・对手回合中，解放此卡可以发动。从牌组将“幻禄天杯龙”以外的１只“天杯龙”怪兽特殊召唤。此效果发动后，直至回合结束时为止，自己仅可特殊召唤龙族怪兽。','\r',char(13)),'\n',char(10)),'特殊召唤&等级上升','特殊召唤','是否上升等级？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23659124,'海的龙王','海中之王。拥有坚硬的甲壳，从口中吐出水泡进行攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23672629,'瓦利安猛鲨枪兵',replace(replace('等级5怪兽×2\r\n此卡名的①②效果1回合仅可各使用1次。①：以对手场上的1只怪兽为对象可以发动。去除自己场上的1个超量素材，破坏对象怪兽。自己场上有其他水属性超量怪兽存在的情况下，此效果在对手回合中也可以发动。②：此卡已经存在于怪兽区域的状态下，自己场上的其他水属性超量怪兽因战斗・效果被破坏的情况下可以发动。从牌组挑选1张魔法卡放在牌组最上面。','\r',char(13)),'\n',char(10)),'','','请选择要在牌组最上面放置的卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23681456,'魔幻甜点・欢乐庆典','①：从手牌将任意数量的“魔幻甜点”怪兽特殊召唤。以此效果特殊召唤的怪兽将在结束阶段被放回牌组。','「魔幻甜点佳节」效果适用中','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23689428,'无限起动 歌利亚',replace(replace('连接怪兽以外的“无限起动”怪兽１只\r\n此卡名的①效果１回合仅可使用１次。①：此卡从场上被送至墓地的情况下，以自己场上的１只超量怪兽为对象可以发动。将此卡重叠在该怪兽下方作为超量素材。②：持有此卡作为素材的、原本种族为机械族的超量怪兽获得以下效果。\r\n●此卡不会因效果被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23689697,'冻冰帝莫比乌斯',replace(replace('此卡可通过解放1只上级召唤的怪兽来上级召唤。\r\n①：此卡上级召唤时，以场上最多3张魔法・陷阱卡为对象可以发动（此卡解放了水属性怪兽来上级召唤的情况下，应对此发动，对手不可发动对象卡）。将该卡破坏。','\r',char(13)),'\n',char(10)),'把1只上级召唤的怪兽解放进行上级召唤','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23693634,'巨人斗士',replace(replace('协调＋协调以外的怪兽1只以上\r\n①：此卡的攻击力上升双方墓地的战士族怪兽数量×100的数值。\r\n②：此卡因战斗被破坏并被送至墓地时，以自己或对手墓地的1只战士族怪兽为对象可以发动。将该战士族怪兽特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23701465,'原初之种','“混沌士兵 －开辟的使者－”或者“混沌帝龙 －终焉的使者－”在场上存在的情况下可以发动。选择２张从游戏中除外的自己的卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23720856,'刷拉拉番长－我我我外套','此卡名的①②效果１回合仅可各使用１次。①：此卡存在于手牌，自己场上有“刷拉拉番长－我我我外套”以外的、“刷拉拉”怪兽或“我我我”怪兽存在的情况下可以发动。将此卡特殊召唤。②：以自己墓地的１只“隆隆隆”怪兽或“怒怒怒”怪兽为对象可以发动。将该怪兽特殊召唤。此效果发动后，直至回合结束时为止自己从额外牌组仅可特殊召唤超量怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23732205,'德林加险龙',replace(replace('龙族・暗属性怪兽2只\r\n此卡名的①②效果1回合仅可各使用1次。①：在对手的结束阶段，以对手场上1只此回合未攻击宣言的攻击表示的怪兽为对象可以发动。将该怪兽破坏，给予对手相当于其原本攻击力数值的伤害。②：此卡存在于墓地、“枪弹”怪兽被特殊召唤至自己场上的情况下可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡离开场上的情况下，将其除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23738096,'无死虫团的补给兵',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：昆虫族怪兽的效果发动时可以发动。从手牌将此卡特殊召唤。此效果是连锁了对手的效果发动来发动的情况下，进而将该效果无效。此效果发动后，直至下一个自己回合结束时为止，自己从额外牌组仅可特殊召唤昆虫族怪兽。\r\n②：在自己的主要阶段可以发动。将自己手牌・场上的怪兽作为融合素材，将1只昆虫族融合怪兽融合召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','融合召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23740893,'妖仙兽 木魅',replace(replace('“妖仙兽 木魅”的①效果１回合只可使用１次。\r\n①：可释放此卡，并以１张我方场上的“修验的妖社”为对象发动。放置３个妖仙计数物在该卡。\r\n②：可在我方主要阶段，将墓地的此卡除外并发动。此回合，我方除通常召唤以外仅１次，可在我方主要阶段再召唤１只“妖仙兽”怪兽。','\r',char(13)),'\n',char(10)),'放置计数物','使用「妖仙兽 木魅」的效果召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23746827,'亿年之冰墓',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：在自己・对手的主要阶段，自己场上的怪兽被以破坏以外的方法，且因对手怪兽的效果从场上离开的情况下，可从以下效果中选择１个发动。\r\n●结束此主要阶段。\r\n●跳过下个对手回合的主要阶段１。','\r',char(13)),'\n',char(10)),'','这次主要阶段结束','下次的对手回合的主要阶段1跳过','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23756165,'魅惑女王 LV5',replace(replace('①：此卡是因“魅惑女王 LV3”的效果被特殊召唤的情况下，１回合１次，以对手场上的１只等级５以下的怪兽为对象可以发动。将该等级５以下的对手怪兽视为装备魔法卡，装备于此卡（仅可装备１只）。\r\n②：此卡将被战斗破坏的情况下，作为代替将以此卡的效果装备的怪兽破坏。\r\n③：在自己的准备阶段，将以此卡的效果装备有怪兽的此卡送至墓地可以发动。从手牌・牌组将１只“魅惑女王 LV7”特殊召唤。','\r',char(13)),'\n',char(10)),'装备','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23770284,'强风龙',replace(replace('①：释放１只龙族怪兽，且此卡的上级召唤成功的场合发动。此卡的攻击力上升被释放的该怪兽原本攻击力的一半数值。\r\n②：此卡不会因与相同攻击力怪兽的战斗而被破坏。\r\n③：此卡攻击了守备表示怪兽的场合，若其攻击力超过守备力，给予对手生命相当于该差值的战斗伤害。','\r',char(13)),'\n',char(10)),'攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23771716,'彩虹鱼','世间罕见的七彩鱼，捕捉的难度非常大。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23776077,'阳炎兽 火焰鸡蛇',replace(replace('炎属性等级６怪兽×２只或以上（最多５只）\r\n１回合１次，可移除此卡的１个超量素材并发动。选择对手场上、墓地的１只怪兽并从游戏中除外。此外，根据此卡所持有的超量素材数量，此卡获得以下效果。\r\n●３个或以上：此卡的攻击力、守备力上升相当于此卡的超量素材数量×２００点。\r\n●４个或以上：此卡不成为对手卡牌效果的对象。\r\n●５个：此卡不会因卡牌效果而被破坏。','\r',char(13)),'\n',char(10)),'除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23782705,'机甲部队・狙击兵','①：只要此卡存在于怪兽区域，双方不可攻击“机甲部队・狙击兵”以外的“机甲部队”怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23784496,'魔界剧本“开幕式”','此卡名的①②效果1回合仅可各使用1次。①：自己恢复自己场上的“魔界剧团”怪兽数量×500的LP。②：在自己的额外牌组有表侧表示的“魔界剧团”灵摆怪兽存在、被放置的此卡被对手的效果破坏的情况下可以发动。自己从牌组抽牌，直至手牌变为5张为止。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23790299,'幻变骚灵・内存摩莉甘特',replace(replace('“幻变骚灵”怪兽2只以上\r\n此卡名的①②③效果1回合仅可各使用1次。①：在双方的战斗阶段，解放自己场上的1只其他怪兽可以发动。此卡的攻击力上升相当于该怪兽攻击力的数值。②：此卡因战斗破坏怪兽时可以发动。挑选对手场上的1只怪兽破坏。破坏的情况下，此卡可继续再攻击仅1次。③：此卡将被破坏的情况下，可将自己墓地的1只怪兽除外作为代替。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23792058,'疾行机人 六角飞碟',replace(replace('←6 【灵摆】 6→\r\n此卡名的灵摆效果１回合仅可使用１次。\n①：从自己墓地的怪兽及自己被除外的怪兽中，以１只风属性同步怪兽为对象可以发动。将该怪兽放回额外牌组。\r\n【怪兽效果】\r\n①：因此卡的战斗造成的战斗伤害由双方玩家承受。\n②：因此卡的战斗对双方造成的战斗伤害变为一半。\n③：此卡在灵摆区域被破坏的情况下可以发动。从自己的额外牌组将１只表侧表示的“疾行机人”灵摆怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23804920,'圣神兽 塞尔凯特',replace(replace('“塞尔凯特”怪兽＋攻击力2500以下的怪兽\r\n此卡名的①效果1回合仅可使用1次。\r\n①：此卡特殊召唤的情况下，或此卡与对手怪兽进行战斗的伤害步骤开始时，以对手场上（表侧表示）・墓地的1只怪兽为对象可以发动。将该怪兽除外，此卡的攻击力上升相当于除外的怪兽原本攻击力的一半的数值。\r\n②：只要有等级10以上的怪兽被除外，此卡在1次战斗阶段中可攻击2次。','\r',char(13)),'\n',char(10)),'除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23812568,'附加镜・等级７','①：等级７怪兽被特殊召唤至自己场上的情况下，从手牌・牌组将２张“附加镜・等级７”送至墓地，以该１只怪兽为对象可以发动。从牌组将２只该怪兽的同名怪兽特殊召唤。然后，自己受到相当于以此效果特殊召唤的怪兽的原本攻击力的合计数值的伤害。此卡发动后，直至回合结束时为止，自己仅可从额外牌组特殊召唤怪兽１次。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23829452,'神艺之狱神兽',replace(replace('此卡名的②③效果1回合仅可各使用1次。\r\n①：自己从额外牌组仅可特殊召唤融合怪兽。\r\n②：在自己・对手的主要阶段可以发动。以包含场上的此卡在内的、自己手牌・场上的怪兽作为融合素材，将1只“神艺”融合怪兽或“创狱神 涅瓦”融合召唤。\r\n③：此卡从手牌・场上被送至墓地的情况下可以发动。从牌组将自己墓地不存在同名卡的1张“神艺”魔法・陷阱卡加入手牌。','\r',char(13)),'\n',char(10)),'融合召唤','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23837054,'溟界之引水蛟',replace(replace('此卡名的卡1回合仅可发动1张。①：将2只“溟界衍生物”（爬虫类族・暗・星2・攻/守0）特殊召唤至自己场上。自己墓地有8种以上的“溟界”怪兽存在的情况下，可适用以下效果作为代替。\r\n●从自己的墓地挑选2只卡名不同的爬虫类族怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'是否从墓地特殊召唤怪兽？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23837055,'溟界衍生物','由“溟界之引水蛟”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23842445,'氮素装置','仅限对手场上的怪兽可以装备。装备怪兽因战斗被破坏并送往墓地的情况下发动。给予对手LP装备怪兽原本攻击力数值的伤害。','LP伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23846921,'秘仪之力ⅩⅩⅠ－世界',replace(replace('①：此卡召唤・反转召唤・特殊召唤的情况下发动。掷1次硬币，根据掷出的正反，此卡获得以下效果。\r\n●正面：在自己的结束阶段，将自己场上的2只怪兽送至墓地可以发动。跳过下个对手回合。\r\n●反面：在对手的抽牌阶段发动。将对手墓地最上面的卡加入对手手牌。','\r',char(13)),'\n',char(10)),'投掷硬币','跳过对手回合','回收','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23848752,'英豪胜利者 铁手套',replace(replace('战士族等级１怪兽×２\r\n此卡名的②③效果１回合仅可各使用１次。\r\n①：自己场上的战士族怪兽１回合各仅１次，不会因战斗・效果被破坏。\r\n②：去除此卡的２个超量素材，以自己墓地的１只等级或阶级４的战士族怪兽为对象可以发动。将该怪兽特殊召唤，此卡的攻击力上升相当于其原本攻击力的数值。\r\n③：对手怪兽进行战斗的攻击宣言时可以发动。依该怪兽攻击力的一半数值恢复自己的LP。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23850421,'劫持飞龙',replace(replace('此卡牌名的效果１回合只可使用１次。\r\n①：可将我方场上的１只机械族怪兽与此卡除外，并以我方墓地１只暗属性怪兽为对象发动。特殊召唤该怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23851033,'异色眼重力龙','以“异色眼降临”降临。此卡名的①效果１回合仅可使用１次。①：此卡特殊召唤成功时可以发动。将对手场上的魔法・陷阱卡全部放回持有者的手牌。应对此效果的发动，对手不可发动魔法・陷阱・怪兽的效果。②：只要此卡存在于怪兽区域，对手必须支付５００LP才可以发动卡的效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23856331,'劫火之三幻魔－神炎皇乌利亚',replace(replace('此卡不可通常召唤，仅可通过“三幻魔”卡的效果特殊召唤。\r\n此卡名的①效果1回合仅可使用1次。\r\n①：向对手出示手牌的此卡可以发动。从牌组将1张“三幻魔”陷阱卡加入手牌。然后，挑选自己的1张手牌舍弃。\r\n②：此卡的攻击力・守备力上升双方墓地陷阱卡的数量×1000的数值。\r\n③：在每个自己・对手回合中1次，以场上的1张魔法・陷阱卡为对象可以发动（应对此发动，双方不可发动效果）。将该卡破坏。','\r',char(13)),'\n',char(10)),'检索效果','破坏效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23857661,'武斗神器－冲津','可将墓地的此卡从游戏中除外，从手牌将１只冠有“武斗神”之名的怪兽送入墓地并发动。此回合，我方受到的所有伤害变成０。此效果在对手回合也可发动。','伤害变成0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23869735,'化石发掘','①：舍弃１张手牌，以自己墓地的１只恐龙族怪兽为对象可以发动此卡。将该恐龙族怪兽特殊召唤。②：只要此卡存在于魔法与陷阱区域，以此卡的①效果被特殊召唤的怪兽的效果无效化，此卡从场上离开时该怪兽将被破坏。该怪兽被破坏时将此卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23874409,'机偶将军 无零',replace(replace('协调＋１只以上协调以外的机械族怪兽\r\n①：此卡同步召唤成功时可以发动。从牌组将１只“机偶”怪兽特殊召唤。②：１回合１次，以场上的１只怪兽为对象可以发动。变更该怪兽的表示形式。','\r',char(13)),'\n',char(10)),'特殊召唤','改变表示形式','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23893227,'电子龙核',replace(replace('此卡名的②③效果1回合1次，仅可使用其中1个。\r\n①：此卡只要存在于场上・墓地，卡名视为“电子龙”。\r\n②：此卡召唤的情况下发动。从牌组将1张“电子”魔法・陷阱卡或“人工脑”魔法・陷阱卡加入手牌。\r\n③：仅有对手场上才存在怪兽的情况下，将墓地的此卡除外可以发动。从牌组将1只“电子龙”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'检索','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23898021,'恶之魔娘 莉丽斯','此卡名的②效果１回合仅可使用１次。①：召唤的此卡的原本攻击力变为１０００。②：解放自己场上的１只暗属性怪兽可以发动。从牌组将３张通常陷阱卡向对手出示，对手从其中随机挑选１张。将该１张卡放置在自己场上，将剩余的卡放回牌组。此效果在对手回合中也可以发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23899727,'水精鳞－邃渊琳德',replace(replace('此卡名的效果１回合仅可使用１次。\r\n①：场上的此卡被破坏并被送至墓地的情况下可以发动。从牌组将“水精鳞－邃渊琳德”以外的１只“水精鳞”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23912837,'阳影依变生',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：以自己墓地的1只“影依”怪兽为对象可以发动。将该怪兽以表侧守备表示或里侧守备表示特殊召唤。\r\n②：从自己墓地将此卡与1张“影依”卡除外，可从以下效果中选择1个发动。\r\n●将自己场上的1只里侧表示怪兽变为表侧守备表示。\r\n●将自己场上的1只表侧表示怪兽变为里侧守备表示。','\r',char(13)),'\n',char(10)),'特殊召唤','选择效果发动','里侧表示怪兽变成表侧守备表示','表侧表示怪兽变成里侧守备表示','','','','','','','','','','','','');
INSERT INTO texts VALUES(23915499,'漏洞人Y','此卡召唤成功时，我方场上存在有“漏洞人Z”的场合，可从牌组特殊召唤１只“漏洞人X”。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23920796,'迷拟宝箱鬼・三头犬',replace(replace('此卡名的①③效果1回合仅可各使用1次。\r\n①：在自己的主要阶段可以发动。从手牌将此卡以里侧守备表示特殊召唤至对手场上。\r\n②：对手不可将自己场上的表侧表示的魔法卡作为效果的对象。\r\n③：此卡在主要阶段反转的情况下发动。分别适用以下效果。\r\n●从自己牌组上面将3张卡除外。然后，将自己除外状态的1只怪兽以守备表示特殊召唤至对手场上。\r\n●将此卡的控制权转移给对手。','\r',char(13)),'\n',char(10)),'反转效果','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23924608,'沙尘大岚',replace(replace('发动此卡的回合中，自己无法进行战斗阶段。\r\n①：以场上最多2张魔法・陷阱卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23927545,'朱罗纪・原角龙','此卡的攻击力上升对手场上的怪兽数量×１００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23927567,'告知幸运的白枭','反转：选择牌组中的１张场地魔法卡放置至牌组的最上面。场上有“王家长眠之谷－死灵谷”存在的场合，可将所选择场地魔法卡加入到手牌中。','在牌组最上面放置','请选择一张场地魔法卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23931679,'海龙神－利维坦',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：只要场上存在“海”，双方场上仅可各存在1只水属性以外的表侧表示怪兽（双方玩家如果自身场上存在2只以上的、水属性以外的表侧表示怪兽，则必须将其送至墓地直至只剩1只为止）。\r\n②：在自己的主要阶段可以发动。从牌组将以下卡中的任意1张加入手牌。\r\n●“海”\r\n●“利维坦”魔法・陷阱卡\r\n●“潜海”魔法・陷阱卡','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23935886,'天威之龙拳圣',replace(replace('包括连接怪兽在内的怪兽2只以上\r\n此卡名的②效果1回合仅可使用1次。①：此卡不会因与效果怪兽的战斗被破坏。②：自己场上没有其他效果怪兽存在的情况下可以发动。挑选对手场上的效果怪兽破坏，数量最多为在自己的墓地及自己场上表侧表示存在的效果怪兽以外的怪兽数量。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23950192,'冰结界的术者','①：只要自己场上存在其他“冰结界”怪兽，等级４以上的怪兽不可攻击宣言。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23965033,'亚马逊女帝王',replace(replace('“亚马逊”融合怪兽＋“亚马逊”怪兽\r\n此卡名的①效果１回合仅可使用１次。\r\n①：此卡融合召唤成功的情况下可以发动。从牌组将１只“亚马逊”怪兽特殊召唤。\r\n②：只要此卡存在于怪兽区域，自己场上此卡以外的“亚马逊”卡不会成为对手效果的对象，不会因对手的效果被破坏。\r\n③：以“亚马逊女帝”或“亚马逊女王”作为素材融合召唤的此卡在１次战斗阶段中可攻击２次。','\r',char(13)),'\n',char(10)),'','可以作2次攻击','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23965037,'多莉雅德的祈祷','用于召唤“精灵术师 多莉雅德”。必须从手牌・自己场上解放合计等级达到３以上的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23969415,'超越进化药贝塔',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：从自己的手牌・场上解放包含恐龙族怪兽在内的２只怪兽可以发动。从牌组・额外牌组将１只攻击力在所解放怪兽的攻击力合计以上的、等级５以上的恐龙族怪兽特殊召唤。此卡发动后，直至回合结束时为止，自己从额外牌组仅可特殊召唤龙族・恐龙族・海龙族・幻龙族怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23971061,'双字节龙',replace(replace('连接怪兽２只\r\n①：此卡的攻击力上升相当于作为此卡连接素材的怪兽的连接标记合计×３００的数值。\r\n②：只要此卡存在于怪兽区域，不受连接怪兽以外的怪兽的效果影响，不会因与连接怪兽以外的怪兽的战斗被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23979249,'武斗神－荒巢田','我方场上、墓地的冠有“武斗神”之名的怪兽从游戏中被除外的场合，可从手牌以守备表示特殊召唤此卡。此外，此卡以表侧表示存在于场上，且冠有“武斗神”之名的卡牌以抽牌以外的方式从我方牌组加入手牌的场合，可在该回合结束阶段时仅限发动１次。从牌组抽取１张卡牌，之后挑选１张手牌舍弃。我方场上只可有１只“武斗神－荒巢田”以表侧表示存在。','特殊召唤','抽牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23995346,'青眼究极龙','“青眼白龙”＋“青眼白龙”＋“青眼白龙”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23995347,'青眼究极龙','“青眼白龙”＋“青眼白龙”＋“青眼白龙”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23995348,'青眼究极龙','“青眼白龙”＋“青眼白龙”＋“青眼白龙”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23995349,'青眼究极龙','“青眼白龙”＋“青眼白龙”＋“青眼白龙”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23995350,'青眼究极龙','“青眼白龙”＋“青眼白龙”＋“青眼白龙”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(23998625,'编号53 伪骸神 心地心',replace(replace('等级５怪兽×３\r\n①：１回合１次，此卡在被选择为攻击对象的情况下发动。此卡的攻击力直至回合结束时为止，上升相当于该攻击怪兽原本攻击力的数值。②：场上的此卡将被战斗・效果破坏的情况下，可去除此卡的１个超量素材作为代替。③：没有超量素材的此卡因效果被破坏并被送至墓地的情况下发动。以此卡作为超量素材，从额外牌组将１只“编号92 伪骸神龙 心地心龙”视为超量召唤特殊召唤。','\r',char(13)),'\n',char(10)),'攻击上升','特殊召唤','是否要使用「编号53 伪骸神 心地心」的效果代替破坏？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24010609,'闪刀机关－多用途战机',replace(replace('①：1回合1次，以自己场上的1张其他的卡为对象可以发动。此回合，应对自己魔法卡的发动，对手不可发动魔法・陷阱・怪兽的效果。进而将对象的卡送至墓地。\r\n②：在自己・对手的结束阶段可以发动。根据此回合此卡以表侧表示形式存在的期间内自己发动过的“闪刀”魔法卡的张数，从自己墓地将最多相同数量的“闪刀”魔法卡放置于自己场上（同名卡最多1张）。以此效果放置的卡从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'','','是否继续选择？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24019092,'点火骑士・鸟嘴',replace(replace('←2 【灵摆】 2→\r\n①：另一方自己的灵摆区域存在“点火骑士”卡的情况下可以发动。将自己的灵摆区域的２张卡破坏，从自己的牌组・墓地将１只战士族・炎属性怪兽加入手牌。\r\n【怪兽效果】\r\n以冷静沉着、富于理性而著称的点火骑士参谋。实际上只是因为血气上涌需要花上一定时间，其实内心一直处于愤怒状态。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24019261,'救急救命','主要阶段２时可以发动。选择１只在此回合被效果破坏且被送往自己墓地的等级４怪兽并特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24025620,'双盾防御者','我方场上的此卡因战斗被破坏并送入墓地时可发动。选择对手场上的１只表侧表示怪兽，直至回合结束时，该攻击力减半。','攻击变换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24027078,'阿瓦隆的魔女 摩根',replace(replace('此卡名的效果１回合仅可使用１次。\r\n①：自己场上存在“圣骑士”怪兽及“圣剑”装备魔法卡，对手发动魔法・陷阱・怪兽的效果时，将此卡从手牌送至墓地可以发动。挑选自己场上的１张“圣剑”装备魔法卡破坏，将该发动无效。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24037702,'暗之进军',replace(replace('此卡牌名的卡牌，１回合只可发动１张。\r\n①：可以我方墓地的１只“光道”怪兽为对象发动。将该怪兽加入手牌。之后，从我方牌组上方将卡牌除外，其数量相当于加入手牌之怪兽的原本等级数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24040093,'魔轰神格里蒙罗','①：自己场上存在“魔轰神”怪兽的情况下，从手牌将此卡送至墓地可以发动。从牌组将“魔轰神格里蒙罗”以外的1只“魔轰神”怪兽加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24050692,'溟界之蛇睡莲','此卡名的卡1回合仅可发动1张。①：从牌组将1只爬虫类族怪兽送至墓地。然后，自己墓地有5种以上爬虫类族怪兽存在的情况下，可从自己的墓地挑选1只爬虫类族怪兽特殊召唤。','是否选怪兽特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24062258,'暗跃的德鲁伊・德律斯',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：此卡召唤时，以“暗跃的德鲁伊・德律斯”以外的、自己墓地的1只攻击力或守备力为0的暗属性・等级4怪兽为对象可以发动。将该暗属性怪兽以守备表示特殊召唤。以此效果特殊召唤的怪兽的效果无效化。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24068492,'自作自受','①：给予对手对手场上的怪兽的数量×５００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24070330,'音响战士 摇滚乐队',replace(replace('←10 【灵摆】 10→\r\n此卡名的①灵摆效果１回合仅可使用１次。①：在自己・对手的准备阶段可以发动。从自己的额外牌组将１只表侧表示的灵摆怪兽加入手牌。②：对手怪兽攻击宣言时可以发动。将该怪兽和此卡破坏。\r\n【怪兽效果】\r\n协调＋１只以上协调以外的怪兽\n此卡名的①②怪兽效果１回合仅可各使用１次。①：此卡特殊召唤成功的情况下可以发动。从自己的额外牌组将１只表侧表示的灵摆怪兽加入手牌。②：自己的场地区域存在“扩音器热焰”的情况下可以发动。挑选场上的１张卡破坏。③：怪兽区域的此卡因战斗・效果被破坏的情况下可以发动。将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24073068,'刚鬼 过肩摔霸王龙','此卡名的②效果1回合仅可使用1次。①：此卡召唤成功时可以发动。从手牌将1只“刚鬼”怪兽特殊召唤。②：此卡从场上被送至墓地的情况下可以发动。从牌组将1张“刚鬼 过肩摔霸王龙”以外的“刚鬼”卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24079759,'格布林百罗刹 特攻达格',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡存在于手牌的情况下可以发动。去除场上的１个超量素材，将此卡特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从牌组将１张“格布林百罗刹”魔法・陷阱卡加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','牌组检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24081957,'反逆之罪宝－蛇眼',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：以场上的１只表侧表示怪兽为对象可以发动。将该怪兽视为永续魔法卡，以表侧表示放在原本持有者的魔法与陷阱区域。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24082387,'神秘麦田圈','可将我方场上任意数量的怪兽送入墓地并发动。从牌组特殊召唤１只冠有“外星人”之名的怪兽，其所持等级与被送入墓地的怪兽的原本等级合计相同。特殊召唤失败的场合，我方受到２０００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24087580,'亚马逊的银剑师',replace(replace('←7 【灵摆】 7→\r\n此卡名的②灵摆效果１回合仅可使用１次。\n①：自己场上的“亚马逊”怪兽的攻击力上升相当于自身等级×１００的数值。\n②：自己的“亚马逊”怪兽进行战斗的攻击宣言时，以自己墓地的１张“亚马逊”魔法・陷阱卡为对象可以发动。将该卡加入手牌。\r\n【怪兽效果】\r\n此卡名的①②怪兽效果１回合仅可各使用１次。\n①：怪兽区域的此卡因战斗・效果被破坏的情况下可以发动。将此卡放在自己的灵摆区域。\n②：此卡存在于墓地的状态下，“亚马逊”怪兽被特殊召唤至自己场上的情况下可以发动。将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24088928,'混沌之魔王－骷髅恶魔',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡存在于手牌・墓地的情况下，以除此卡以外的、包含记载有“光与暗的仪式”卡名的卡在内的、自己・对手的、墓地・除外状态（表侧）的合计3张卡为对象可以发动。将该卡以喜欢的顺序放回牌组下面，将此卡特殊召唤。\r\n②：此卡被送至墓地的情况下，从手牌・牌组将1张仪式魔法卡送至墓地可以发动。从牌组将1只卡名记载于该卡的仪式怪兽加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','检索效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24092792,'耀圣诗章～激奏之狂想曲～',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：只要自己中央的主要怪兽区域存在怪兽，对手怪兽仅可攻击该怪兽。\r\n②：从自己手牌・场上将1只怪兽送至墓地，以自己墓地的1只原本属性与该怪兽不同的“耀圣”怪兽为对象可以发动。将该怪兽特殊召唤。然后，自己场上存在同步怪兽的情况下，可将对手场上的1张表侧表示卡的效果直至回合结束时为止无效。','\r',char(13)),'\n',char(10)),'特殊召唤','是否把卡效果无效？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24094258,'强炼装・银金',replace(replace('灵摆怪兽２只\r\n此卡名的③效果１回合仅可使用１次。①：此卡连接召唤成功的情况下可以发动。从牌组挑选１只灵摆怪兽，以表侧表示加入额外牌组。②：１回合１次，以此卡以外的自己场上的１张表侧表示的卡为对象可以发动。将该卡破坏。然后，从自己的额外牌组将１只表侧表示的灵摆怪兽加入手牌。③：自己灵摆区域的卡离开场上的情况下发动。自己从牌组抽１张。','\r',char(13)),'\n',char(10)),'牌组灵摆怪兽加入额外牌组','破坏并从额外牌组把灵摆怪兽加入手牌','抽牌','请选择要表侧表示加入额外牌组的卡','','','','','','','','','','','','');
INSERT INTO texts VALUES(24094653,'融合','①：将自己手牌・场上的怪兽作为融合素材，将1只融合怪兽融合召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24094654,'融合','①：将自己手牌・场上的怪兽作为融合素材，将1只融合怪兽融合召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24094655,'融合','①：将自己手牌・场上的怪兽作为融合素材，将1只融合怪兽融合召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24094656,'融合','①：将自己手牌・场上的怪兽作为融合素材，将1只融合怪兽融合召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24096228,'二重魔法','可从手牌中弃置１张魔法卡，并选择对手墓地中的１张魔法卡来发动此卡。将选择魔法卡放置于我方场上正确的卡牌区域来使用。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24096499,'森之圣兽 缬草小鹿','此卡名的效果１回合仅可使用１次。①：舍弃１张手牌，以自己墓地“森之圣兽 缬草小鹿”以外的１只等级２以下的兽族怪兽为对象可以发动。将该怪兽以表侧攻击表示或里侧守备表示特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24101897,'鬼计的猫娘','仅在自己场上有“鬼计”怪兽存在的情况下，此卡才可以表侧表示召唤。①：在自己的主要阶段可以发动。将此卡改成里侧守备表示（１回合仅１次）。②：等级４以上的怪兽召唤・特殊召唤成功的情况下发动。将该怪兽改成里侧守备表示。此效果在场上有此卡以外的“鬼计”怪兽存在的情况下才能发动和处理。','变成里侧守备','变成里侧守备','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24103628,'幻影魔术士','此卡因战斗被破坏并送入墓地时可发动。从牌组以守备表示特殊召唤１只攻击力为１０００或以下的冠有“－英雄”之名的怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24104865,'外星人之母','此卡因战斗破坏放置有A计数物怪兽并送入墓地的场合，在该战斗阶段结束时发动。特殊召唤被破坏的该怪兽至我方场上。此卡从场上离开时，以此效果特殊召唤的所有怪兽被破坏。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24128274,'深海的战士','只要“海”存在于场上，此卡便不会受到魔法效果的影响。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24131534,'点火骑士・马格南姆',replace(replace('←7 【灵摆】 7→\r\n①：另一方自己的灵摆区域存在“点火骑士”卡的情况下可以发动。将自己的灵摆区域的２张卡破坏，从自己的牌组・墓地将１只战士族・炎属性怪兽加入手牌。\r\n【怪兽效果】\r\n操控剑铳的炎之战士。浑身包裹着冰冷的钢铁铠甲，但其内里隐藏着一颗熊熊燃烧的滚烫之心。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24137081,'钻头藤壶','此卡可直接攻击对手玩家。每次此卡因直接攻击给予对手生命战斗伤害，此卡的攻击力上升１０００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24140059,'告知不幸的黑猫','①：反转此卡的场合，发动此卡。将牌组中的１张陷阱卡放置至牌组的最上面。场上有“王家长眠之谷－死灵谷”存在的场合，可将该陷阱卡加入到手牌中，而不用将其置于牌组最上方。','在牌组最上面放置','请选择一张陷阱卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24150026,'机偶无双 八壹八','①：此卡在可攻击的情况下必须攻击。②：此卡攻击的情况下，战斗阶段结束时变为守备表示。③：攻击表示的此卡在被选择为攻击对象的情况下发动。将此卡改成守备表示。','变成守备表示','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24151924,'G魔像・无果石墓',replace(replace('地属性怪兽2只以上\r\n①：只要此卡存在于怪兽区域，自己场上相互连接状态的怪兽不受对手场上发动的怪兽效果影响。\r\n②：可攻击的对手怪兽必须攻击此卡。\r\n③：1回合1次，从手牌将1只电子界族怪兽舍弃可以发动。自己抽1张。\r\n④：相互连接状态的此卡被破坏的情况下可以发动。对手场上的所有表侧表示卡的效果无效化。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24154052,'原型创机','在电子空间找到的原种。其信息量为未知数。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24158464,'廷达三角・结界石',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡在手牌的情况下，舍弃此卡以外的１张手牌可以发动。从牌组将“廷达三角 ・结界石”以外的１张“廷达三角”卡送至墓地，将此卡以里侧守备表示特殊召唤。\r\n②：此卡反转的情况下可以发动。从牌组挑选１只“廷达三角・结界石”以外的反转怪兽，加入手牌或送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24166324,'极辉龙机巧降星',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：“龙机巧”卡被除外的情况下，解放自己场上的１只“龙机巧”怪兽，以自己除外状态的最多２张“龙机巧”卡为对象可以发动。将该卡加入手牌。\r\n②：将手牌的１张“辉龙机巧降星”出示给对手可以发动。为使攻击力的合计达到仪式召唤的怪兽的攻击力以上，解放自己的手牌・场上的机械族怪兽，从自己的手牌・墓地将１只机械族仪式怪兽仪式召唤。','\r',char(13)),'\n',char(10)),'回收除外','墓地仪式','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24175232,'奈芙蒂斯之苍凰神',replace(replace('以“奈芙蒂斯的轮回”降临\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：在自己的主要阶段可以发动。将自己的手牌・场上（表侧表示）任意数量的“奈芙蒂斯”卡破坏。然后，依所破坏的数量，将对手场上的怪兽破坏。\r\n②：此卡因战斗・效果被破坏并被送至墓地的情况下，在下个自己的准备阶段可以发动。从墓地将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24181936,'暗味锅派对',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：自己的战斗阶段开始时，以自己场上的１只表侧表示怪兽为对象可以发动。此回合，该自己的怪兽的攻击对象由对手选择，该自己的怪兽的攻击力仅在和对手怪兽进行战斗的伤害计算时，上升相当于自身原本攻击力的数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24184846,'燃烧拳斗士 复仇守卫','可将手牌或墓地中的此卡从游戏中除外，选择我方场上１只冠有“燃烧拳斗士”之名的怪兽并发动。直至下一个我方准备阶段时，将被选择怪兽从游戏中除外。此效果在对手回合也可发动。','除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24194033,'泥浆怪','黏糊糊的令人感到恶心的怪兽，吐出剧毒瓦斯进行攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24203749,'天下独步之大义贼',replace(replace('自己场上不存在怪兽的情况下，此卡可通过从自己手牌及对手场上之中将怪兽解放来以表侧表示上级召唤。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡是被通常召唤的情况下，对手发动手牌・墓地・除外状态的卡的效果时可以发动。将该效果无效并破坏。\r\n②：在自己・对手的战斗阶段，向对手出示所有手牌可以发动。将对手场上的怪兽全部改成守备表示。','\r',char(13)),'\n',char(10)),'解放手牌以及对手怪兽上级召唤','效果无效','表示形式','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24203750,'天下独步之大义贼',replace(replace('自己场上不存在怪兽的情况下，此卡可通过从自己手牌及对手场上之中将怪兽解放来以表侧表示上级召唤。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡是被通常召唤的情况下，对手发动手牌・墓地・除外状态的卡的效果时可以发动。将该效果无效并破坏。\r\n②：在自己・对手的战斗阶段，向对手出示所有手牌可以发动。将对手场上的怪兽全部改成守备表示。','\r',char(13)),'\n',char(10)),'解放手牌以及对手怪兽上级召唤','效果无效','表示形式','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24207889,'千察万别','①：只要此卡存在于魔法与陷阱区域，相同种族的怪兽在双方场上各仅可有1只以表侧表示存在（双方玩家如果自身场上存在2只以上相同种族的怪兽，则必须将怪兽送至墓地，直至相同种族的怪兽只剩1只为止）。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24212820,'魅影骑士团暗手甲',replace(replace('①：从牌组将1张“魅影”魔法・陷阱卡送至墓地。\r\n②：自己场上不存在卡的情况下，每次对手怪兽的直接攻击宣言时有1次，可以在墓地发动。此卡变为效果怪兽（战士族・暗・星4・攻300/守600），以守备表示特殊召唤至怪兽区域（不视为陷阱卡）。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。\r\n③：以此卡的效果特殊召唤的此卡的守备力上升自己墓地的“魅影”魔法・陷阱卡的数量×300的数值。','\r',char(13)),'\n',char(10)),'此卡变成效果怪兽特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24215921,'地狱墓场蠕动者',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：在自己・对手回合中，自己场上存在恶魔族怪兽的情况下可以发动。从手牌将此卡特殊召唤。然后，可将自己场上的１只“尤贝尔”或记载有该卡名的怪兽破坏。\r\n②：将墓地的此卡除外可以发动。从自己的手牌・墓地将“地狱墓场蠕动者”以外的１只攻击力和守备力为０的恶魔族怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'自身特殊召唤','特殊召唤恶魔族怪兽','是否把怪兽破坏？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24218047,'破面龙','①：此卡因战斗被破坏并被送至墓地时可以发动。从牌组将1只守备力1500以下的幻龙族怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24220368,'宝石骑士彩光',replace(replace('①：可从以下效果中选择1个发动（此卡名的以下效果1回合仅可各选择1次）。\r\n●将自己手牌・场上的怪兽作为融合素材，将1只“宝石骑士”融合怪兽融合召唤。自己墓地存在“宝石骑士结合”的情况下，也可将牌组・额外牌组中岩石族以外的、最多2只“宝石骑士”怪兽作为融合素材。\r\n●将自己牌组・除外状态的1只“宝石”怪兽加入手牌。此回合的主要阶段期间，对手将受到的效果伤害变为一半。','\r',char(13)),'\n',char(10)),'发动','融合召唤','加入手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24221739,'神殿守卫者','①：只要此卡存在于怪兽区域，对手在抽牌阶段以外不可抽牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24221808,'心灵超载恶魔',replace(replace('念动力族协调＋协调以外的念动力族怪兽2只以上\r\n①：1回合1次，以自己墓地的1只念动力族怪兽为对象可以发动。将该念动力族怪兽除外。\r\n②：以此卡的①效果除外了怪兽的此卡从场上被送至墓地的情况下发动。将该除外状态的怪兽尽可能地特殊召唤。','\r',char(13)),'\n',char(10)),'除外','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24224830,'墓穴指名者','①：以对手墓地的1只怪兽为对象可以发动。将该怪兽除外。直至下个回合结束时为止，以此效果除外的怪兽及与该怪兽原本卡名相同的怪兽的效果无效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24224831,'墓穴指名者','①：以对手墓地的1只怪兽为对象可以发动。将该怪兽除外。直至下个回合结束时为止，以此效果除外的怪兽及与该怪兽原本卡名相同的怪兽的效果无效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24224832,'墓穴指名者','①：以对手墓地的1只怪兽为对象可以发动。将该怪兽除外。直至下个回合结束时为止，以此效果除外的怪兽及与该怪兽原本卡名相同的怪兽的效果无效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24226942,'混沌奈芙蒂斯','此卡不可通常召唤，仅可以此卡的效果特殊召唤。此卡名的①效果１回合仅可使用１次。①：此卡存在于手牌・墓地，场上的卡因效果被破坏的情况下，从自己的墓地将“混沌奈芙蒂斯”以外的光属性和暗属性怪兽各１只除外可以发动。将此卡特殊召唤。②：此卡特殊召唤成功的情况下，以对手场上的１张卡和对手墓地的２张卡为对象可以发动。将该卡除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24232799,'储纳母舰超碎龙',replace(replace('“机动要犀 铁犀三角龙 ”或“盾航战车电子剑龙”＋机械族・恐龙族怪兽\r\n此卡名的②效果１回合仅可使用１次。\r\n①：只要存在被从墓地特殊召唤的怪兽，此卡不会因战斗被破坏。\r\n②：此卡已存在于怪兽区域的状态下，怪兽被从手牌特殊召唤的情况下，以自己及对手场上的各１张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24268052,'护卫防壁','因对手怪兽攻击造成我方受到战斗伤害的伤害计算时可发动。因该战斗对我方产生的伤害变为０，并从我方牌组抽取１张卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24269961,'破械神王 阎魔',replace(replace('恶魔族怪兽2只\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡特殊召唤的情况下可以发动。从自己牌组・墓地将1只“破械”怪兽加入手牌。\r\n②：此卡存在于墓地的状态下，自己场上的卡因战斗・效果被破坏的情况下，将此卡除外可以发动。从自己手牌・墓地将1只恶魔族怪兽特殊召唤。然后，可将自己场上的1张卡破坏。','\r',char(13)),'\n',char(10)),'','','是否把自己场上1张卡破坏？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24269962,'破械神王 阎魔',replace(replace('恶魔族怪兽2只\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡特殊召唤的情况下可以发动。从自己牌组・墓地将1只“破械”怪兽加入手牌。\r\n②：此卡存在于墓地的状态下，自己场上的卡因战斗・效果被破坏的情况下，将此卡除外可以发动。从自己手牌・墓地将1只恶魔族怪兽特殊召唤。然后，可将自己场上的1张卡破坏。','\r',char(13)),'\n',char(10)),'','','是否把自己场上1张卡破坏？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24285858,'剑斗回归','可选择我方墓地冠有“剑斗兽”之名的３张卡牌发动。被选择的３张卡牌返回至牌组。之后，从我方牌组抽取１张卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24291651,'加把劲骑士','①：攻击表示的此卡被选择为攻击对象时可以发动。将此卡改成守备表示。','变成守备表示','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24294108,'燃烧的大地','发动此卡时，破坏场上的所有场地魔法卡。此外，在双方的准备阶段时，回合玩家受到５００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24299458,'禁忌的一滴',replace(replace('此卡名的卡1回合仅可发动1张，且应对此卡的发动，对手不可发动与为发动此卡而送至墓地的卡原本种类（怪兽・魔法・陷阱）相同的卡的效果。\r\n①：从自己手牌・场上将任意数量的其他卡送至墓地可以发动。依其数量挑选对手场上的效果怪兽。该怪兽直至回合结束时为止，攻击力变为一半，效果无效化。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24311372,'戴比鲁佐亚','据说是能通过钢铁化发挥真正力量的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24311595,'救援机人','只要此卡以表侧表示存在于我方场上，我方场上冠有“机人”之名的怪兽因战斗被破坏并送入墓地时，可将该怪兽返回至手牌。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24317029,'守墓的侦察者','反转：从我方牌组特殊召唤１只攻击力１５００以下的冠有“守墓的”之名的怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24326617,'冰帝家臣埃舍尔','①：对手的魔法与陷阱区域存在2张以上的卡的情况下，此卡可从手牌特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24348204,'魅惑的怪盗','肩披黑色斗篷的耍帅怪盗。挥舞手杖来迷倒对手。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24348804,'休息一回',replace(replace('自己场上不存在被特殊召唤的怪兽的情况下可以发动此卡。\r\n①：只要此卡存在于魔法与陷阱区域，被特殊召唤的怪兽直至该回合结束时为止效果无效化。\r\n②：效果怪兽被以攻击表示特殊召唤的情况下发动。将该怪兽改成守备表示。','\r',char(13)),'\n',char(10)),'是否使用效果？','发动同时使用效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24361622,'天球之圣刻印',replace(replace('龙族怪兽２只\r\n此卡名的②效果１回合仅可使用１次。\r\n①：在每个对手回合中１次，此卡存在于额外怪兽区域的情况下，解放自己手牌・场上的１只怪兽可以发动。将场上的１张表侧表示卡放回手牌。\r\n②：此卡被解放的情况下发动。从手牌・牌组将１只龙族怪兽的攻击力・守备力改成０并特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24362891,'突然进化','①：解放自己场上的１只爬虫类族怪兽可以发动。从牌组将１只“进化龙”怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24382602,'光之灵堂',replace(replace('①：只要此卡存在于场地区域，自己除通常召唤外仅可追加１次，在自己的主要阶段召唤１只光属性・等级１协调。\r\n②：１回合１次，以自己场上的１只表侧表示怪兽为对象可以发动。从手牌・牌组将１只通常怪兽送至墓地，对象怪兽的攻击力・守备力直至回合结束时为止，上升相当于送至墓地的怪兽原本等级×１００的数值。\r\n③：将墓地的此卡除外可以发动。从牌组将１张“毁灭的爆裂疾风弹”加入手牌。','\r',char(13)),'\n',char(10)),'使用「光之灵堂」的效果召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24384095,'九蛇孔雀','场上的此卡被释放并送入墓地的场合，可以从我方牌组、墓地挑选１只“九蛇孔雀”以外的等级４或以下的风属性怪兽加入手牌。“九蛇孔雀”的效果１回合只可使用１次。','加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24393683,'军贯随性捏','此卡也可以通过向对手出示手牌的１只“舍利军贯”来发动。①：从牌组将３只“军贯”怪兽向对手出示，对手从中挑选１只。将该１只怪兽加入自己的手牌，剩余的放回牌组。通过出示“舍利军贯”来发动的情况下，加入手牌的怪兽由自己挑选。②：将墓地的此卡除外，以自己墓地的３只“军贯”怪兽为对象可以发动。将该怪兽加入牌组。然后自己从牌组抽１张。此效果在此卡被送至墓地的回合不可发动。','是否从手牌展示「舍利军贯」发动？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24413299,'镇压冥王星',replace(replace('①：１回合１次，宣言１个卡名可以发动。确认对手的所有手牌，其中有所宣言卡的情况下，从以下效果中挑选１个适用。\r\n●挑选对手场上的１只怪兽，获得其控制权。\r\n●挑选对手场上的１张魔法・陷阱卡破坏。然后，可将破坏的该魔法・陷阱卡放置在自己场上。','\r',char(13)),'\n',char(10)),'宣言卡名','得到控制权','魔法·陷阱卡破坏','是否在自己场上放置？','','','','','','','','','','','','');
INSERT INTO texts VALUES(24419823,'矿场钻机','①：表侧表示的此卡从我方场上离开时，可以我方墓地的１张场地魔法卡作为对象发动。该卡牌加入手牌。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24425055,'诡雷陷阱E','①：可舍弃１张手牌并发动。挑选我方手牌、墓地的１张永续陷阱卡并盖牌在我方场上。因此效果而盖牌的卡牌在盖牌回合也可发动。','','适用「诡雷陷阱E」的效果来发动','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24429467,'魔导变换',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：只要此卡存在于魔法与陷阱区域，每当对手怪兽的效果发动，就在此卡上放1个魔力计数物。\r\n②：将放有6个以上魔力计数物的此卡送至墓地可以发动。从牌组将1张魔法卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24431911,'磁石之战士 大地机翁',replace(replace('此卡不可通常召唤。\r\n仅可在将自己手牌・场上（表侧表示）・墓地的“磁石战士西格玛＋”“磁石战士西格玛－”各1只除外的情况下从墓地特殊召唤。\r\n①：1回合1次，对手发动效果时，以对手场上的1只怪兽为对象可以发动。将该怪兽破坏。以地属性怪兽为对象来发动的情况下，作为代替也可获得该怪兽的控制权。\r\n②：在对手回合中，解放此卡可以发动。将自己除外状态的2只“磁石战士西格玛”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','破坏效果','特殊召唤','是否获取控制权？','','','','','','','','','','','','');
INSERT INTO texts VALUES(24432029,'次代机・鼓风','①：此卡特殊召唤时可以发动。从牌组将１只暗属性的“次代机”怪兽加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24433920,'挥刀的拷问机器','以巨大的钟摆刀刃将对手劈成两半，相当可怕的拷问机器。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24433921,'挥刀的拷问机器','以巨大的钟摆刀刃将对手劈成两半，相当可怕的拷问机器。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24434049,'爱皮尔莉・圆满',replace(replace('等级２怪兽×２\r\n①：１回合１次，以自己或对手墓地的合计最多２张魔法・陷阱卡为对象可以发动。将该卡重叠在此卡下方作为超量素材。此卡持有“皮尔莉・美味回忆”作为超量素材的情况下，此效果在对手回合中也可以发动。②：自己发动“皮尔莉”速攻魔法卡时可以发动。将场上的该卡重叠在此卡下方作为超量素材。然后，可挑选场上的１只怪兽，直至结束阶段为止将其除外。此效果１回合最多可使用３次。','\r',char(13)),'\n',char(10)),'从墓地补充超量素材','发动的速攻魔法卡在此卡下面重叠','是否选怪兽除外？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24435369,'人鱼骑士','只要“海”存在于场上，此卡便可在１个战斗阶段中进行２次攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24440742,'影帽子',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：此卡发动后，变为拥有以下效果的效果怪兽（幻想魔族・暗・星４・攻１５００／守６００），特殊召唤至怪兽区域（也视为陷阱卡）。\r\n●此卡特殊召唤的情况下，以对手场上的表侧表示卡为对象可以发动，数量最多为自己场上的幻想魔族怪兽的数量。将该卡的效果直至回合结束时为止无效。\r\n●此卡与怪兽进行战斗的情况下，该２只不会因该战斗被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24449083,'正义法院','此卡名的①效果1回合仅可使用1次。①：在自己的主要阶段可以发动。从手牌将1只天使族怪兽特殊召唤。此效果在自己场上存在等级1天使族怪兽的情况下才能发动和处理。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24454387,'至交死党恐龙',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：只要自己场上存在其他恐龙族怪兽，对手怪兽不可将此卡选择未攻击对象。\r\n②：以自己场上１张其他的卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24461358,'腐朽的祭仪要录',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从手牌・牌组将1张仪式魔法卡出示给对手，从牌组将1只记载有该卡名的怪兽加入手牌。\r\n②：此卡存在于墓地的状态下，自己场上有表侧表示的仪式怪兽因效果从场上离开的情况下，如果自己场上不存在仪式怪兽以外的表侧表示怪兽则可以发动。将此卡加入手牌。','\r',char(13)),'\n',char(10)),'检索效果','回到手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24484270,'宝石骑士・魅影原核',replace(replace('“宝石”怪兽2只\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡连接召唤的情况下可以发动。从牌组将1张“宝石骑士”卡加入手牌。\r\n②：支付1000LP可以发动。将自己墓地・除外状态的怪兽作为融合素材放回牌组，将1只“宝石骑士”融合怪兽融合召唤。以此效果特殊召唤的怪兽此回合不可直接攻击。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24487411,'雷管删除者',replace(replace('电子界族怪兽２只以上\r\n①：１回合１次，除连接３以上的连接怪兽之外，表侧表示怪兽与此卡进行战斗的伤害步骤开始时可以发动。将该怪兽破坏。\r\n②：１回合１次，解放此卡连接端的１只自己的怪兽，以对手场上的１只怪兽为对象可以发动。将该怪兽破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24506253,'先史遗产 阿坎巴罗土偶',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：自己场上的“先史遗产”怪兽将被战斗或对手的效果破坏的情况下，可将手牌的此卡舍弃作为代替。\r\n②：此卡存在于墓地的情况下，支付１０００LP可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡将在结束阶段返回持有者的手牌。发动此效果的回合中，自己仅可特殊召唤“先史遗产”怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24508238,'异次元乌鸦','①：在自己・对手回合中，从手牌将此卡舍弃至墓地，以对手墓地的1张卡为对象可以发动。将该卡除外。','对手墓地1张卡除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24514503,'冻心雪水晶',replace(replace('此卡名的①③效果1回合仅可各使用1次。\r\n①：自己场上怪兽的数量比对手场上怪兽少2只以上的情况下可以发动。将此卡从手牌特殊召唤。\r\n②：场上的此卡不会因效果被破坏。\r\n③：以对手场上的1只效果怪兽为对象可以发动。将该怪兽的效果无效。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24521325,'模板弹涂鱼',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次，且②效果1回合仅可使用1次。\r\n①：此卡可从手牌特殊召唤至电子界族连接怪兽连接端的自己场上。\r\n②：在自己的主要阶段可以发动。从自己手牌・墓地将1只电子界族怪兽除外。在此回合要连接召唤的情况下，可将此卡视为以此效果除外的怪兽的同名卡来作为连接素材。','\r',char(13)),'\n',char(10)),'','除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24521754,'百景战都 金发姑娘城',replace(replace('①：此卡被召唤・特殊召唤至中央以外的主要怪兽区域的情况下将被破坏。\r\n②：只要此卡存在于主要怪兽区域中央，此卡的攻击力上升３０００。\r\n③：１回合１次，指定１处未使用的自己的主要怪兽区域可以发动。将自己的主要怪兽区域的此卡的位置移动至所指定的区域。然后，将存在于移动前和移动后的怪兽区域及与其间的怪兽区域相同纵列的、此卡以外的卡全部破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24530661,'达人僵尸','为寻找强劲对手而徘徊游走的僵尸。据说曾是一名熟悉各种武术的知名达人。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24545464,'同步士反射','我方场上的同步怪兽成为攻击对象时可发动。使该发动无效，并选择对手场上的１只怪兽破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24550676,'月光舞狮子姬',replace(replace('“月光舞豹姬”＋“月光”怪兽×2\r\n此卡仅可通过以上述卡作为融合素材的融合召唤来特殊召唤。\r\n①：场上的此卡不会因对手的效果被破坏，对手不可将场上的此卡作为效果的对象。\r\n②：此卡在1次战斗阶段中可攻击2次。\r\n③：1回合1次，此卡攻击怪兽的伤害步骤结束时可以发动。将对手场上被特殊召唤的怪兽全部破坏。','\r',char(13)),'\n',char(10)),'特殊召唤的怪兽全部破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24557335,'天威龙－休塔纳','此卡名的①②效果1回合仅可各使用1次。①：自己场上没有效果怪兽存在的情况下可以发动。从手牌将此卡特殊召唤。②：效果怪兽以外的自己场上的表侧表示怪兽因战斗・效果被破坏的情况下，将手牌・墓地的此卡除外，以1只被破坏的该怪兽为对象可以发动。将该怪兽特殊召唤。然后可挑选对手场上的1只怪兽破坏。','特殊召唤','特殊召唤破坏的怪兽','是否破坏对手怪兽？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24566654,'深红地狱火焰','①：自己场上存在“暗红恶魔龙”，且对手发动给予自己伤害的魔法・陷阱卡时可以发动。作为自己受到的该效果伤害的代替，对手受到该数值两倍的伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24573625,'文具博格００８',replace(replace('←1 【灵摆】 1→\r\n①：自己仅可灵摆召唤“文具博格”怪兽。此效果不会被无效化。\r\n【怪兽效果】\r\n①：此卡的攻击力上升相当于自己墓地“文具博格”卡数量×５００的数值。②：只要此卡存在于怪兽区域，对手不可将其他“文具博格”卡作为效果的对象。③：此卡在１次战斗阶段中最多可攻击怪兽２次。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24590232,'王魂调和',replace(replace('①：对手怪兽的直接攻击宣言时可发动。使该攻击无效。之后，可适用以下效果。\r\n●为使等级的合计变成８或以下，从我方墓地挑选１只协调与除协调以外的任意数量怪兽并除外，并将１只持有等级与被除外怪兽等级合计相同的同步怪兽视为同步召唤从额外牌组特殊召唤。','\r',char(13)),'\n',char(10)),'是否要把同步怪兽特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24610207,'画星宝宝',replace(replace('①：此卡使用于超量召唤的情况下，此卡的等级可视为5。②：以场上的此卡作为素材超量召唤的怪兽获得以下效果。\r\n●此超量召唤成功的情况下发动。自己从牌组抽1张。','\r',char(13)),'\n',char(10)),'抽1张卡（画星宝宝）','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24611934,'动力石像怪','取得暗黑之力强化而成的石像鬼。尖锐的爪子值得警惕。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24621460,'机偶小町 贰贰四','①：只要此卡存在于怪兽区域，自己在通常召唤外仅可追加１次，在自己的主要阶段召唤１只“机偶”怪兽。②：此卡在可攻击的情况下必须攻击。③：此卡在被选择为攻击对象的情况下发动。变更此卡的表示形式。','表示形式变更','使用「机偶小町 二二四」的效果召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24623598,'迷失','将对手墓地的１张卡牌从游戏中除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24634594,'魔螂 迪亚波兰提斯',replace(replace('协调＋协调以外的怪兽１只以上\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡同步召唤的情况下可以发动。从牌组将昆虫族・植物族怪兽送至墓地，数量最多为作为该同步素材的怪兽中协调以外的怪兽数量。\r\n②：此卡是被同步召唤的情况下，以自己场上的１只昆虫族・植物族怪兽为对象可以发动。该怪兽直至回合结束时为止变为协调。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24635329,'圣影依 凯乌斯',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。①：在此卡反转的情况下可以发动。从手牌中以表侧守备表示或里侧守备表示将1只“影依”怪兽特殊召唤。②：在此卡因效果被送至墓地的情况下可以发动。从手牌将1只“影依”怪兽送至墓地。在此回合中适用以下效果。\r\n●自己场上怪兽的攻击力・守备力上升以此效果被送至墓地的怪兽的原本等级×100。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24639891,'舍利军贯',replace(replace('来到了我一直感兴趣的专注于军贯的军港。这里的舍利每年只制造两千艘，独立开发出的低粘性旧米会让品尝者享受到在其他海港无法体会到的厚重感，是无数老饕们念念不忘的佳品。港内的氛围也高贵典雅，令人心潮澎湃。\r\n心心念念的军贯，无论醋的比例、捏握的力道还是造型都堪称匠心之作。据店主介绍“带有柔和、芳醇香气的EDO－FRONT红醋预定近日入港”，非常期待其与寿司调和出的效果。\r\n周围海域有些嘈杂，这一点略微遗憾。但我给出４颗星，其中也包含有对未来的期待！','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24643836,'扰乱怪魔术','此卡从手牌或场上被送入墓地时，从牌组将“扰乱怪之绿色”“扰乱怪之黄色”“扰乱怪之黑色”各１只加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24643913,'叛革者 哀陀',replace(replace('此卡不可通常召唤。\r\n“叛革者 哀陀”1回合1次，仅可在拥有以下效果的怪兽卡存在于对手场上或墓地，并支付一半LP的情况下从手牌・墓地特殊召唤。\r\n●应对效果发动时连锁、在手牌或怪兽区域发动的效果\r\n①：此卡的特殊召唤不会被无效化。\r\n②：此卡只要存在于怪兽区域，不可作为融合・同步・超量・连接召唤的素材，且在自己回合期间，不受在对手场上发动的怪兽的效果影响。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24644634,'大植然白橡树','以此卡为对象的对手卡牌效果发动时，可将场上的此卡送入墓地并发动。从牌组特殊召唤２只等级４或以下的冠有“大植然”之名的怪兽。以此效果特殊召唤的怪兽不可进行攻击宣言，在我方的结束阶段时被破坏。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24649931,'变幻',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：以自己或对手的魔法与陷阱区域的１张表侧表示怪兽卡为对象，可从以下效果中选择１个发动。\r\n●将对象卡特殊召唤至原本持有者的场上。\r\n●将对象卡放回手牌。\r\n●破坏对象卡。然后，可将场上１只等级在该卡等级以下的怪兽破坏。','\r',char(13)),'\n',char(10)),'作为对象的卡在原本持有者的场上特殊召唤','作为对象的卡回到手牌','作为对象的卡破坏','是否把场上的怪兽破坏？','','','','','','','','','','','','');
INSERT INTO texts VALUES(24658418,'银河暴龙','我方冠有“银河”之名的怪兽被选择为攻击对象时可发动。从手牌以守备表示特殊召唤此卡。以此效果特殊召唤成功时，可仅以我方场上冠有“银河”之名的怪兽作为素材，超量召唤１只冠有“银河”之名的超量怪兽。','特殊召唤','超量召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24661486,'冰寒魔法师','可舍弃１张手牌并发动。选择场上１只表侧表示怪兽，并放置１个冰计数物。只要此卡以表侧表示存在于场上，此卡的攻击力上升场上冰计数物数量×３００点。','放置计数物','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24662957,'噩魔魔像','①：以场上的１只攻击力２０００以上的怪兽为对象可以发动。将该怪兽直至下个回合的结束阶段为止除外。在自己场上存在“暗红恶魔龙”或记载有该卡名的同步怪兽的状态下发动此卡的情况下，可进而从自己的牌组・墓地将１张“噩魔锁链”放置在自己场上。','是否放置「噩魔锁链」？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24668830,'细菌感染','仅限装备机械族以外的怪兽。装备怪兽的攻击力在每回合我方的准备阶段下降３００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24672164,'幻奏华歌圣 绽放首席',replace(replace('“幻奏音姬”怪兽＋“幻奏”怪兽１只以上\r\n①：此卡的攻击力上升相当于作为此卡融合素材的怪兽数量×３００的数值。\r\n②：此卡在１次战斗阶段中可攻击２次。\r\n③：被融合召唤的此卡被送至墓地的情况下，以自己墓地的１只“幻奏”怪兽为对象可以发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'加入手牌','是否继续选择融合素材？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24673894,'改变命运',replace(replace('对手怪兽的攻击宣言时，可选择该怪兽并发动。使该攻击无效，并将该怪兽变成守备表示。只要该怪兽以表侧表示存在于场上，不可变更表示形式。之后，对手从以下效果挑选１个并适用。\r\n●我方LP回复相当于该变成守备表示怪兽的攻击力一半数值。\r\n●给予对手生命相当于变成守备表示怪兽攻击力一半的伤害。','\r',char(13)),'\n',char(10)),'自己基本分回复','给予对手伤害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24689197,'芬芳夜魔－白千层',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：在自己・对手回合中，从手牌将此卡舍弃，以自己场上的１只“芬芳”怪兽为对象可以发动。依该怪兽攻击力数值的一半恢复自己的LP。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从牌组将协调以外的１只“芬芳”怪兽特殊召唤。此效果发动后，直至回合结束时为止自己仅可特殊召唤植物族怪兽。','\r',char(13)),'\n',char(10)),'回复基本分','从牌组特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24694698,'大植然栗子','①：此卡召唤成功时可以发动。从牌组将１只“大植然”怪兽送至墓地。②：１回合１次，以自己墓地的２只“大植然”怪兽为对象可以发动。将该２只怪兽放回牌组。然后自己从牌组抽１张。','送至墓地','抽牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24696097,'流星龙',replace(replace('同步怪兽的协调＋“星尘龙”\r\n①：1回合1次，可以发动。从自己牌组上面翻开5张并放回牌组。此回合，此卡最多可攻击的次数为翻开的卡中协调的数量。\r\n②：1回合1次，破坏场上的卡之效果发动时可以发动。将该效果无效并破坏。\r\n③：1回合1次，对手的攻击宣言时，以攻击怪兽为对象可以发动。将场上的此卡除外，将该攻击无效。\r\n④：因此③效果被除外的回合的结束阶段发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'多重攻击','把卡破坏的效果无效并破坏','无效攻击','特殊召唤','','','','','','','','','','','','');
INSERT INTO texts VALUES(24701066,'无限起动 大河风暴',replace(replace('等级5怪兽×2\r\n此卡名的①③效果1回合仅可各使用1次。\r\n①：去除此卡的1个超量素材可以发动。从牌组挑选1只机械族・地属性怪兽，加入手牌或送至墓地。\r\n②：此卡战斗破坏对手怪兽时可以发动。将该怪兽作为此卡的超量素材。\r\n③：此卡存在于墓地的情况下，解放自己场上的1只机械族连接怪兽可以发动。将此卡以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'牌组检索','超量素材','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24701235,'和魂','此卡不可特殊召唤。①：此卡召唤・反转的回合，自己除通常召唤外仅可追加１次，可在自己的主要阶段召唤１只灵魂怪兽。②：此卡召唤・反转的回合的结束阶段发动。将此卡放回持有者的手牌。③：此卡被送至墓地的情况下发动。自己从牌组抽１张。此效果在自己场上存在灵魂怪兽的情况下才能进行发动和处理。','使用「和魂」的效果召唤','抽牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24707869,'光明的未来','可选择２只从游戏中被除外的我方念动力族怪兽并发动。将被选择怪兽返回至墓地，从我方牌组抽取１张卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24721709,'救魔之标','此卡名的卡1回合仅可发动1张。①：以自己墓地的1只魔法师族效果怪兽为对象可以发动。将该怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24725825,'电虫','①：可将此卡从手牌舍弃至墓地，并以对手场上的１只龙族、机械族怪兽为对象发动。直至结束阶段，获得该龙族、机械族怪兽的控制权。','获取控制权','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24731391,'电子界魔术师','以“电脑网仪式”降临。①：只要此卡存在于怪兽区域，自己所受的全部伤害变为一半。②：只要自己场上有连接怪兽存在，对手不可选择自己场上的其他怪兽为攻击对象，也不可作为效果的对象。③：仅在此卡与连接怪兽进行战斗的伤害计算时此卡的攻击力上升1000。④：此卡因对手效果被破坏的情况下可以发动。从牌组将1只电子界族怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24731453,'除雪机关车 扫雪冲锋','①：自己的魔法与陷阱区域有卡存在的情况下，对手怪兽的直接攻击宣言时可以发动。从手牌将此卡特殊召唤。然后，将自己的魔法与陷阱区域的卡全部破坏，给予对手相当于破坏数量×２００的数值的伤害。②：只要此卡存在于怪兽区域，自己仅可特殊召唤机械族怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24749710,'双心切换',replace(replace('此卡名的①效果1回合仅可使用1次，①②的效果不可在同一连锁上发动。\r\n①：在自己・对手回合中可以发动。从牌组将1只记载有“光与暗的仪式”卡名的怪兽加入手牌。然后，挑选自己的1张手牌舍弃。\r\n②：对手发动卡的效果时，将自己场上的1只等级7以上的怪兽放回手牌可以发动。从手牌将1只卡名与所放回怪兽不同的、记载有“光与暗的仪式”卡名的怪兽无视召唤条件特殊召唤。','\r',char(13)),'\n',char(10)),'检索效果','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24779554,'白森的露西亚',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：自己场上存在“白森”怪兽的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：从自己手牌・场上将1张魔法・陷阱卡送至墓地可以发动。自己抽1张。\r\n③：在自己・对手回合中，此卡存在于墓地的情况下，以自己场上・墓地的1只“白森”同步怪兽为对象可以发动。将该怪兽放回额外牌组，将此卡的效果无效并特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','抽牌','墓地特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24793135,'机巧传－神使记纪图','此卡名的①效果１回合仅可使用１次。①：在自己的主要阶段可以发动。从自己的牌组上面翻开３张卡。可从其中挑选１只攻击力和守备力的数值相同的机械族怪兽加入手牌。将剩余的卡以里侧表示除外。②：每次攻击力和守备力的数值相同的机械族怪兽被召唤・特殊召唤，在此卡上放１个计数物。③：此卡的计数物数量为１０以上的情况下，攻击力和守备力的数值不同的场上怪兽不可发动效果。','','是否选卡加入手牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24799107,'龙女仆・秀特亮尔',replace(replace('“龙女仆”怪兽＋等级5以上的龙族怪兽\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己・对手的准备阶段可以发动。从自己手牌・墓地将1只等级9以下的“龙女仆”怪兽特殊召唤。\r\n②：对手发动魔法・陷阱・怪兽的效果时可以发动。适用以下全部效果。\r\n●将该发动无效并破坏。\r\n●将此卡放回额外牌组，从额外牌组将1只“龙女仆・总管龙女”特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24838456,'呼唤虚无的咒文','连锁４以后可支付一半的LP发动。使此卡发动时积累的连锁上的所有卡牌的发动无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24839398,'陷阱集锦',replace(replace('此卡名的②③效果１回合仅可各使用１次。\r\n①：装备怪兽的攻击力上升相当于自己墓地的陷阱卡的数量×４００的数值。\r\n②：装备怪兽战斗破坏对手怪兽的伤害计算后，或给予对手战斗伤害时，将此卡送至墓地可以发动。从自己的墓地将１张陷阱卡放置在自己场上。\r\n③：自己场上的表侧表示陷阱卡将被效果破坏的情况下，作为代替可将场上的此卡除外。','\r',char(13)),'\n',char(10)),'','放置墓地的陷阱卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24842059,'连环古里波',replace(replace('等级4以下的电子界族怪兽1只\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：对手发动陷阱卡时，解放此卡可以发动。将该效果无效并除外。\r\n②：在自己・对手回合中，此卡存在于墓地的情况下，解放自己场上1只被从额外牌组特殊召唤的“＠伊格尼斯者”怪兽可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24845628,'尘小妖的拖把','装备怪兽不可进行释放，也不可成为融合、同步、超量召唤的素材。场上的此卡因对手效果被破坏并送入墓地时可发动。从牌组将１只冠有“尘小妖”之名的怪兽加入手牌。我方场上只可有１张“尘小妖的拖把”以表侧表示存在。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24857466,'冥王龙梵达吉翁',replace(replace('对手怪兽的效果、魔法、陷阱卡因反制陷阱卡而无效的场合，可从手牌特殊召唤此卡。以此方法特殊召唤成功时，根据被无效化卡牌的种类发动以下效果。\r\n●魔法：给予对手生命１５００点伤害。\r\n●陷阱：选择对手场上的１张卡牌破坏。\r\n●怪兽：从我方墓地选择１只怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','给与对手基本分1500分伤害','选择对手场上1张卡破坏','从自己墓地选择1只怪兽在自己场上特殊召唤','','','','','','','','','','','','');
INSERT INTO texts VALUES(24861088,'先史遗产 内布拉星象盘',replace(replace('此卡牌名的①②效果１回合１次，只可使用其中１个。\r\n①：此卡召唤成功时可发动。从牌组将１张除“先史遗产 内布拉星象盘”以外的“先史遗产”卡牌加入手牌。\r\n②：此卡存在于墓地，且我方场上的怪兽仅是“先史遗产”怪兽的场合可发动。以守备表示特殊召唤此卡。发动此效果之回合，我方不可发动除“先史遗产”卡牌以外的卡牌效果。','\r',char(13)),'\n',char(10)),'检索','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24874630,'魔鬼圣域','特殊召唤１只“金属魔鬼衍生物”（恶魔族・暗・１星・攻／守０）至我方场上。该衍生物不可进行攻击。因“金属魔鬼衍生物”的战斗而对控制者所造成的差额伤害，由对手玩家来代替承受。每次在我方回合的准备阶段支付１０００LP。不支付则破坏“金属魔鬼衍生物”。','是否要支付1000基本分维持「金属魔鬼衍生物」？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24874631,'金属魔鬼衍生物','由「魔鬼圣域」的效果特殊召唤。这衍生物不能攻击，这衍生物的战斗发生的对控制者的战斗伤害由对方代受。这衍生物的控制者在每次自己准备阶段支付1000基本分。或者不支付基本分让这衍生物破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24878656,'玩具盒子',replace(replace('①：1回合1次，可从以下效果中选择1个发动。\r\n●从自己手牌・牌组・怪兽区域（表侧表示）・墓地挑选最多2只原本卡名包含“玩具”的、拥有可将自身视为魔法卡从手牌放置在魔法与陷阱区域的效果的怪兽，视为魔法卡放置在自己的魔法与陷阱区域。\r\n●将自己的魔法与陷阱区域的最多2张卡破坏。\r\n②：1回合1次，对手怪兽攻击宣言时，将自己场上的1张里侧表示卡送至墓地可以发动。将该对手怪兽破坏。','\r',char(13)),'\n',char(10)),'放置怪兽','破坏自己魔法陷阱区域的卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24882256,'火不死鸟＠伊格尼斯者',replace(replace('电子界族怪兽2只以上\r\n此卡名的①②③效果1回合仅可各使用1次。①：此卡攻击的伤害计算时可以发动。给予对手相当于此卡攻击力数值的伤害，因该战斗对对手造成的战斗伤害变为0。②：此卡因效果被破坏的情况下可以发动。挑选对手场上的1只怪兽破坏。③：连接召唤的此卡被破坏并被送至墓地的情况下，在下一次准备阶段可以发动。从墓地将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24892828,'提斯蒂娜的归还之子',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡存在于手牌的情况下，以“提斯蒂娜的归还之子”以外的、自己场上的１只“提斯蒂娜”怪兽为对象可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡的等级变为与对象怪兽相同。\r\n②：此卡存在于墓地的情况下，以自己场上的１只水族超量怪兽为对象可以发动。将此卡作为该怪兽的超量素材。','\r',char(13)),'\n',char(10)),'特殊召唤','作为超量素材','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24903843,'伯吉斯吸虫・皮卡虫',replace(replace('①：从手牌挑选1张“伯吉斯吸虫”卡舍弃。然后，自己抽2张。\r\n②：此卡存在于墓地，且陷阱卡发动时可以发动（同一连锁上最多1次）。此卡变为通常怪兽（水族・水・星2・攻1200/守0），特殊召唤至怪兽区域（不视为陷阱卡）。以此效果特殊召唤的此卡不受怪兽效果影响，从场上离开的情况下将被除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24907044,'魔界剧团－美丽女主演',replace(replace('←2 【灵摆】 2→\r\n①：1回合1次，因对手怪兽的攻击自己受到战斗伤害时，可从以下效果中选择1个发动。\n●该对手怪兽的攻击力下降受到的伤害的数值。\n●从自己的额外牌组将1只攻击力在所受伤害数值以下的表侧表示“魔界剧团”灵摆怪兽加入手牌。\r\n【怪兽效果】\r\n①：1回合1次，自己或对手受到战斗伤害时，可以对手场上的1只表侧表示怪兽为对象发动。该怪兽的攻击力下降该战斗伤害的数值。②：怪兽区域的此卡因战斗或对手的效果被破坏时可以发动。从牌组挑选1张“魔界剧本”魔法卡放置在自己场上。','\r',char(13)),'\n',char(10)),'攻击力下降','额外牌组灵摆怪兽加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24915933,'赫焉龙 格兰吉尼奥尔',replace(replace('“赫之圣女 卡尔塔西亚”＋光・暗属性怪兽\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡融合召唤的情况下可以发动。从牌组・额外牌组将1只等级6以上的光・暗属性怪兽送至墓地。\r\n②：此卡存在于怪兽区域或墓地的状态下，有怪兽因对手发动的怪兽的效果被特殊召唤的情况下，将此卡除外可以发动。从牌组将1只“教导”怪兽，或从额外牌组将1只“惨绝戏”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'从牌组送至墓地','从牌组特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24919805,'无赖特急 战斗列车',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：1回合1次，在自己的主要阶段可以发动（发动此效果的回合中，自己无法进行战斗阶段）。给予对手500伤害。\r\n②：在此卡被送至墓地的回合的结束阶段可以发动。从牌组将1只机械族・地属性・等级10怪兽加入手牌。','\r',char(13)),'\n',char(10)),'LP伤害','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24920410,'过度上弦','可选择我方场上１只冠有“发条”之名的怪兽并发动。被选择怪兽的攻击力、守备力加倍，并在此回合的结束阶段时返回至持有者手牌。“过度上弦”１回合只可发动１张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24925387,'魔救调律者',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡存在于手牌的情况下，从手牌将1张其他的“魔救”卡放回牌组最上面可以发动。将此卡特殊召唤。\r\n②：在自己的主要阶段可以发动。从自己牌组上面翻开5张卡。可从其中挑选1只等级4以下的岩石族怪兽特殊召唤。将剩余的以喜欢的顺序放回牌组下面。','\r',char(13)),'\n',char(10)),'特殊召唤','翻牌组','是否特殊召唤怪兽？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24940422,'雪花之光','此卡名的①②效果1回合仅可各使用1次。①：自己墓地没有魔法・陷阱卡存在的情况下可以发动。自己从牌组抽2张。此卡发动后，此决斗中自己不可发动“雪花之光”以外的魔法・陷阱卡的效果。②：将墓地的此卡除外可以发动。将手牌的1只怪兽出示给对手，放回牌组洗牌。然后，自己从牌组抽1张。','发动','回到牌组并抽牌','「雪花之光」效果适用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24943456,'T.G.力量角斗士',replace(replace('协调＋1只以上协调以外的“T.G.”怪兽\r\n①：此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予战斗伤害。②：场上的此卡被破坏的情况下发动。自己从牌组抽1张。','\r',char(13)),'\n',char(10)),'抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(24996659,'电力鹬鸵','只要此卡以表侧表示存在于场上，我方场上冠有“电力”之名怪兽进行攻击的场合，攻击怪兽不会因战斗被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25005816,'鼓舞','①：可以我方场上１只表侧表示的怪兽为对象发动此卡。该怪兽的攻击力上升７００，直到回合结束时。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25034083,'诱饵机人','只要此卡以表侧表示存在于场上，对手不可选择除“诱饵机人”以外的表侧表示怪兽为攻击对象。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25050038,'连锁治愈','回复我方５００LP。此卡在连锁２或连锁３发动的场合，此卡加入牌组并洗牌。此卡在连锁４以后发动的场合，将此卡返回至手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25067275,'旗鼓堂堂','可选择我方墓地中１张装备魔法卡及场上１只作为其正确对象的怪兽来发动此卡。将所选择的装备魔法卡装备至所选择的怪兽上。以此效果装备的装备魔法卡会在结束阶段时被破坏。发动此卡的回合中，我方不可特殊召唤怪兽。１个回合中只可发动１张“旗鼓堂堂”。','请选择墓地的装备卡','请选择要装备的对象','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25072579,'试作闪刀姬－天津',replace(replace('“闪刀姬”怪兽1只\r\n自己1回合仅可特殊召唤1次“试作闪刀姬－天津”，其①②效果1回合仅可各使用1次。\r\n①：对手场上攻击力2000以上的怪兽发动效果时可以发动。该效果变为“将对手场上的1只“闪刀姬”连接怪兽破坏”。\r\n②：此卡与对手怪兽进行战斗的攻击宣言时，以自己场上的1只“闪刀姬”怪兽和对手场上的1张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'效果变更','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25090294,'花与叶','可解放我方场上的１只“元素－英雄 小花蕾”并发动。从手牌、牌组特殊召唤１只“元素－英雄 花女郎”。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25096909,'连栗炮固定式',replace(replace('①：从自己的额外牌组将等级・阶级的合计与双方的手牌・场上的卡的数量相同的、２只超量怪兽（相同阶级）和１只融合怪兽除外。然后，可适用以下效果。\r\n●挑选对手场上的１只表侧表示怪兽，将等级・阶级的合计与该怪兽的等级・阶级相同的、自己除外状态的１只超量怪兽和１只融合怪兽放回额外牌组。然后，将对手场上的卡全部除外。','\r',char(13)),'\n',char(10)),'','是否回收怪兽并除外对手的卡？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25109950,'荒岛的小剑士','可解放我方场上除此卡以外的１只怪兽并发动。直至回合结束时，此卡的攻击力上升７００点。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25119460,'YZ－履带龙',replace(replace('“Y－龙首”＋“Z－金属履带”\r\n此卡从额外牌组仅可在将自己场上的上述卡除外的情况下特殊召唤。\r\n此卡不可从墓地特殊召唤。\r\n①：舍弃１张手牌，以对手场上的１只里侧表示怪兽为对象可以发动。将该对手的里侧表示怪兽破坏。','\r',char(13)),'\n',char(10)),'怪兽破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25123082,'火焰门魔导书','可选择我方场上的１只魔法师族怪兽并发动。直至回合结束时，被选择怪兽的攻击力上升１０００点，因战斗破坏对手怪兽的场合，可从牌组将１张冠有“魔导书”之名的魔法卡加入手牌。“火焰门魔导书”１回合只可发动１张。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25123713,'空牙团的豪杰 戴拿','这个卡名的①的效果1个回合只可使用1次。①：这张卡特殊召唤成功的情况下可以发动。挑选张数最多为自己场上的“空牙团”怪兽种类数量的对手墓地的卡，将其除外。②：只要这张卡存在于怪兽区域，对手就不可选择其他的“空牙团”怪兽作为攻击对象。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25131968,'毗龙之谦',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己的主要阶段可以发动。从手牌・牌组将1只“虎菱之玄”以守备表示特殊召唤至对手场上。\r\n②：此卡以“虎菱之玄”的效果特殊召唤的情况下发动。对手抽2张。然后，对手挑选自身的1张手牌舍弃。\r\n③：在自己・对手的战斗阶段结束时发动。将场上的此卡放回手牌。','\r',char(13)),'\n',char(10)),'回到手牌','特殊召唤「虎菱之玄」','抽牌&丢弃','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25132288,'光辉终结龙',replace(replace('协调＋协调以外的光属性怪兽１只或以上\r\n此卡与对手怪兽进行战斗的攻击宣言时可发动。此卡的攻击力、守备力下降５００点，进行战斗的对手怪兽的攻击力、守备力直至回合结束时下降１５００点。','\r',char(13)),'\n',char(10)),'攻守下降','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25137581,'潜伏的Z','此卡名的①效果１回合仅可使用１次。①：对手特殊召唤怪兽成功时可以发动。从手牌将此卡以里侧守备表示特殊召唤。以此效果特殊召唤的此卡将在此回合的结束阶段变为表侧守备表示。②：此卡在结束阶段反转的情况下发动。将场上被特殊召唤的怪兽全部破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25140659,'未界域调查报告','此卡名的①②效果1回合仅可各使用1次。①：以自己场上的1只“未界域”怪兽和场上的1只怪兽为对象可以发动。将该怪兽放回持有者的手牌。②：此卡存在于墓地的情况下，从手牌将1只“未界域”怪兽舍弃可以发动。将此卡放回牌组最下面。然后自己从牌组抽1张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25148255,'废品抓锚','此卡可代替“同步士”协调作为同步素材。①：1回合1次，舍弃1张手牌，以自己墓地的1只协调以外的“废品”怪兽为对象可以发动。将该怪兽特殊召唤，仅以该怪兽和此卡作为素材，将1只以“同步士”协调作为素材的同步怪兽同步召唤。此时的同步素材怪兽不去墓地而直接被除外。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25158975,'命运－英雄 死亡教义魔侠',replace(replace('此卡不可通常召唤。\r\n“命运－英雄 死亡教义魔侠”1回合1次，仅可在从自己墓地将合计3只战士族或暗属性怪兽除外的情况下，从手牌・墓地特殊召唤。\r\n①：此卡以此方法特殊召唤的情况下可以发动。在下个准备阶段给予对手2000伤害。\r\n②：1回合1次，对手发动效果时可以发动。将自己手牌・场上・墓地的怪兽作为融合素材放回牌组，将1只战士族或暗属性的融合怪兽融合召唤。','\r',char(13)),'\n',char(10)),'','给与伤害','融合召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25163248,'先史遗产玛雅机械','上级召唤机械族怪兽的场合，此卡可作为２只怪兽释放。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25163979,'诱导向星遗物之噩梦',replace(replace('①：只要此卡存在于场地区域，自己相互连接状态的怪兽因战斗发生的对自己的战斗伤害变为0。②：1回合1次，在自己的主要阶段可从以下效果中选择1个发动。\r\n●挑选自己场上的1只“梦魇曲”怪兽，将其位置移动至自己的其他主要怪兽区域。\r\n●挑选自己主要怪兽区域的2只“梦魇曲”怪兽，交换其位置。','\r',char(13)),'\n',char(10)),'','位置移动','位置交换','请选择要移动位置的怪兽','','','','','','','','','','','','');
INSERT INTO texts VALUES(25165047,'生命激流龙',replace(replace('协调＋“动力工具龙”\r\n①：此卡同步召唤时可以发动。将自己的LP改成４０００。\r\n②：只要此卡存在于怪兽区域，自己受到的效果伤害变为０。\r\n③：此卡将被破坏的情况下，作为代替可将自己墓地的１张装备魔法卡除外。','\r',char(13)),'\n',char(10)),'自己基本分变成4000','是否要把1张装备魔法卡除外代替破坏？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25166510,'转生炎兽 B野牛','这个卡名的①②的效果1个回合各只能使用1次。①：自己墓地存在3只以上“转生炎兽”怪兽的情况下可以发动。将这张卡从手牌以守备表示形式进行特殊召唤。②：可以自己墓地的炎属性连接怪兽为对象发动，其数量最多为对手场上的表侧表示的卡数量。该怪兽放回额外牌组。之后，可以挑选至多为放回卡张数的对手场上的表侧表示的卡，直到回合结束时为止使这些卡的效果无效。','','','是否选卡无效？','请选择要无效的卡','','','','','','','','','','','','');
INSERT INTO texts VALUES(25171661,'无限狱矮人','我方手牌是０张的场合，只要此卡以表侧表示存在于场上，我方场上的怪兽攻击了守备表示怪兽时，若其攻击力超过守备力，给予对手生命相当于该差值的战斗伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25173686,'同花顺','对手的魔法＆陷阱卡区全部都有卡牌存在的场合可发动。破坏对手魔法＆陷阱卡区的全部卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25191307,'急袭猛禽－盛放秃鹫',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个，发动此效果的回合中，自己仅可特殊召唤暗属性怪兽。\r\n①：自己场上不存在鸟兽族怪兽以外的表侧表示怪兽的情况下可以发动。从手牌将此卡和１只“急袭猛禽”怪兽特殊召唤。\r\n②：自己场上不存在怪兽的情况下，以包含此卡在内的、自己墓地２只等级４以下的“急袭猛禽”怪兽为对象可以发动。将该怪兽以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25200959,'电子界输送仪',replace(replace('协调+1只以上协调以外的怪兽\r\n此卡名的①②效果1回合仅可各使用1次。①：此卡同步召唤成功的情况下可以发动。从自己的手牌・墓地挑选1只电子界族协调以守备表示特殊召唤。此效果发动后，直至回合结束时为止自己仅可特殊召唤电子界族怪兽。②：同步召唤的此卡被送至墓地的情况下可以发动。自己从牌组抽1张。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25206027,'异界的棘紫龙','我方场上怪兽因战斗或卡牌效果被破坏并送入墓地的场合可发动。从手牌特殊召唤此卡。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25209168,'绝望与希望之逆转',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：自己场上有３只以上的天使族・地属性怪兽存在的情况下可以发动。将场上的怪兽全部送至墓地。然后，双方可从对手的墓地挑选怪兽特殊召唤至自身的场上，数量最多为以此效果送至各自对手墓地的怪兽数量。自己的墓地有“现世与冥界的逆转”存在的情况下，进而自己可从牌组挑选１张陷阱卡放置在自己场上。以此效果放置的卡在放置的回合中也可以发动。','\r',char(13)),'\n',char(10)),'','是否从对手墓地选怪兽特殊召唤？','是否从牌组选陷阱卡放置？','适用「绝望与希望之逆转」的效果来发动','','','','','','','','','','','','');
INSERT INTO texts VALUES(25218587,'光道埃癸斯',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：以对手场上的表侧表示卡为对象可以发动，数量最多为自己场上的“光道”怪兽数量。将该卡的效果直至回合结束时为止无效。\r\n②：此卡被从牌组送至墓地的情况下可以发动。将此卡放置在自己场上。','\r',char(13)),'\n',char(10)),'无效','在场上放置','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25221249,'蜂军之巢',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：自己的“蜂军”怪兽被选择为攻击对象时可以发动。从手牌・牌组将１只“蜂军”怪兽特殊召唤，在此卡上放１个计数物。然后，结束战斗阶段。\r\n②：在结束阶段，放有２个以上计数物的此卡将被送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25224340,'幻惑的操手',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：从牌组将1只幻想魔族怪兽送至墓地。\r\n②：自己场上存在等级5以上的幻想魔族怪兽的情况下，在自己的主要阶段将墓地的此卡除外，以对手墓地的1只怪兽为对象可以发动。将该怪兽特殊召唤至自己场上。以此效果被特殊召唤的怪兽将在下个回合的结束阶段被除外。','\r',char(13)),'\n',char(10)),'发动','特殊召唤','「幻惑的操手」的效果特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25231813,'白银之翼','仅限装备等级８或以上的龙族同步怪兽。装备怪兽１回合最多２次，不会因战斗被破坏。装备怪兽因卡牌效果被破坏的场合，可破坏此卡作为代替。','是否要使用「白银之翼」的效果代替破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25236056,'稀有金属龙','此卡不可通常召唤，仅可以卡牌效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25244515,'妖仙兽 十斩风',replace(replace('“妖仙兽 十斩风”的①②效果１回合只可各使用１次。\r\n①：从我方的“妖仙兽”怪兽与对手怪兽进行战斗的伤害步骤开始至伤害计算前，可从手牌舍弃此卡并发动。直至回合结束时，该我方怪兽的攻击力上升１０００。\r\n②：可以场上１只“妖仙兽”怪兽为对象发动。直至回合结束时，该怪兽的攻击力上升１０００。\r\n③：在召唤此卡回合的结束阶段发动。将此卡返回至持有者手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25247218,'大块魔像','①：仅有对手场上才存在怪兽的情况下，此卡无需解放即可召唤。','不解放进行召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25259669,'格布林德伯格','①：此卡召唤时可以发动。从手牌将１只等级４以下的怪兽特殊召唤。此卡为攻击表示的情况下，此卡进而变为守备表示。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25262697,'守墓的暗杀者','场上有“王家长眠之谷－死灵谷”存在时才可发动此卡。此卡进行攻击宣言时，可变更对手表侧表示怪兽的表示形式。','改变表示形式','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25273572,'G魔像・卵石斗牛犬',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组挑选1只“G魔像・卵石斗牛犬”，加入手牌或特殊召唤。此效果发动后，直至回合结束时为止，自己仅可特殊召唤电子界族怪兽。\r\n②：此卡从手牌被送至墓地的情况下可以发动。从牌组将1张“G魔像”卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25274141,'紧急时刻表','此卡名的①②效果１回合仅可各使用１次。①：对手场上的怪兽数量比自己场上的怪兽数量多的情况下可以发动。从牌组将机械族・地属性的、１只等级４以下的怪兽和１只等级５以上的怪兽的效果无效并以守备表示特殊召唤。发动此卡的回合中，自己仅可用机械族怪兽攻击宣言。②：被放置在场上的此卡被送至墓地的情况下可以发动。从牌组将１只机械族・等级１０的怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25280974,'魔道小丑 利真','此卡名的②效果1回合仅可使用1次。①：只要此卡存在于怪兽区域，自己在通常召唤外仅可追加1次，在自己主要阶段将1只魔法师族怪兽以表侧攻击表示上级召唤。②：此卡从场上被送至墓地的情况下可以发动。从自己牌组・墓地挑选1只魔法师族通常怪兽加入手牌。','','使用「魔道小丑 利真」的效果召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25290459,'等级上升！','可将我方场上１只表侧表示的冠有“LV”之名的怪兽送入墓地并发动。无视召唤条件从手牌、牌组特殊召唤１只记载于该卡的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25311006,'三战之才',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：对手在此回合的自己的主要阶段发动过怪兽效果的情况下，可从以下效果中选择1个发动。\r\n●自己抽2张。\r\n●直至结束阶段为止，获得对手场上的1只怪兽的控制权。\r\n●确认对手的手牌，从其中挑选1张放回牌组。','\r',char(13)),'\n',char(10)),'自己抽2张','对手场上1只怪兽的控制权直到结束阶段得到','把对手手牌确认，选那之内的1张回到牌组','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25334372,'九十九斩',replace(replace('“九十九斩”１回合仅可发动１张。\r\n①：自己的怪兽攻击攻击力高于该怪兽的怪兽的伤害计算时可以发动。进行该战斗的自己怪兽的攻击力仅在该伤害计算时上升相当于自己与对手LP数值差的数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25339070,'堕天使 莫斯提马',replace(replace('自己1回合仅可特殊召唤1次“堕天使 莫斯提马”，其②效果1回合仅可使用1次。\r\n①：从手牌将2张其他的“堕天使”卡舍弃可以发动。从手牌将此卡特殊召唤。\r\n②：在自己・对手回合中，支付1000LP，以自己墓地的1张“堕天使”魔法・陷阱卡为对象可以发动。适用该魔法・陷阱卡发动时的效果。然后，将该卡放回牌组。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25341652,'交响魔人 剑击指挥',replace(replace('等级4怪兽×2\r\n①：1回合1次，去除此卡的1个超量素材，以对手场上的1只表侧攻击表示的怪兽为对象可以发动。将该怪兽改成里侧守备表示。\r\n②：自己场上的“魔人”超量怪兽将被战斗・效果破坏的情况下，作为代替可去除该怪兽的1个超量素材。','\r',char(13)),'\n',char(10)),'变成里侧守备','是否要使用「交响魔人 剑击指挥」的效果代替破坏？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25342956,'宝石骑士统领・辉钻－彩光',replace(replace('“宝石”怪兽×3\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己・对手的主要阶段，将场上的此卡送至墓地可以发动。从自己额外牌组・墓地将岩石族以外的最多3只“宝石”怪兽无视召唤条件特殊召唤（同名卡最多1张）。此回合，自己从额外牌组仅可特殊召唤融合怪兽。\r\n②：此卡存在于墓地的状态下，自己的“宝石骑士”融合怪兽因战斗被破坏时可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'送至墓地特殊召唤','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25343017,'寡默的念力祭司',replace(replace('①：此卡召唤・反转召唤的情况下发动。将此卡改成守备表示。\r\n②：1回合1次，将1张手牌送至墓地，以自己墓地的1只念动力族怪兽为对象可以发动。将该念动力族怪兽除外。\r\n③：以此卡的②效果除外了怪兽的此卡从场上被送至墓地的情况下，以该1只除外状态的怪兽为对象发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'变成守备表示','除外','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25343280,'法老王的灵魂','此卡不可通常召唤。只可以“第一棺材”的效果特殊召唤此卡。成功特殊召唤此卡时，可从我方墓地中特殊召唤最多４只等级２以下的不死族通常怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25345186,'屠杀战争','只可在主要阶段１发动。此回合内因战斗而发生过伤害计算的所有我方、对手怪兽，在结束步骤时被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25366484,'元素－英雄 闪耀光焰翼人',replace(replace('“元素-英雄 火焰翼人”＋“元素-英雄 闪光人”\r\n此卡仅可以融合召唤方式特殊召唤。①：此卡的攻击力上升相当于自己墓地的“元素-英雄”卡数量×300的数值。②：此卡战斗破坏怪兽并将其送至墓地的情况下发动。给予对手该怪兽的原本攻击力数值的伤害。','\r',char(13)),'\n',char(10)),'伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25373678,'旋风之沃泰克斯',replace(replace('协调＋协调以外的鸟兽族怪兽１只或以上\r\n此卡因战斗被破坏并送入墓地时，可从牌组特殊召唤１只等级４或以下的鸟兽族怪兽。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25377819,'召集之圣刻印','①：从牌组将１只“圣刻”怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25388971,'灿幻开花',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：在自己・对手的主要阶段，自己场上的怪兽仅有龙族・炎属性怪兽，且对手场上的怪兽数量多于自己场上的怪兽的情况下可以发动。结束此主要阶段。\r\n②：在攻击宣言过３次以上的自己・对手回合中，将墓地的此卡除外可以发动。自己抽１张。然后，可从手牌将任意数量的“天杯龙”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'结束主要阶段','抽牌&特殊召唤','是否特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25396150,'亚马逊拜谒之间',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：作为此卡发动时的效果处理，可从自己墓地的怪兽及自己额外牌组的表侧表示灵摆怪兽中，挑选１只“亚马逊”怪兽加入手牌，或挑选１只“亚马逊”灵摆怪兽放在自己的灵摆区域。\r\n②：自己场上存在“亚马逊”怪兽卡，怪兽被特殊召唤至对手场上的情况下，以１只该对手怪兽为对象可以发动。依该怪兽的攻击力数值恢复自己的LP。','\r',char(13)),'\n',char(10)),'是否从墓地或额外牌组选卡？','加入手牌','在灵摆区域放置','回复基本分','','','','','','','','','','','','');
INSERT INTO texts VALUES(25397880,'奈芙蒂斯的叙事者',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：以自己墓地的１张“奈芙蒂斯的叙事者”以外的“奈芙蒂斯”卡为对象可以发动。挑选自己的１张手牌破坏，将对象卡加入手牌。\r\n②：此卡因效果被破坏并被送至墓地的情况下，在下个自己的准备阶段可以发动。从自己的墓地将１张“奈芙蒂斯的叙事者”以外的“奈芙蒂斯”卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25401880,'念力通道','①：支付８００LP，以最多２只被除外的自己的念动力族怪兽为对象可以发动。将该怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25407406,'剑斗兽之斗器短剑','仅限装备冠有“剑斗兽”之名的怪兽。装备怪兽的攻击力上升３００点。因装备怪兽从我方场上返回至牌组而导致此卡被被送入墓地时，此卡返回至手牌。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25407643,'魔法族的圣域','此卡以外的表侧表示魔法卡仅存在于自己场上，魔法师族以外的怪兽被召唤・特殊召唤至对手场上时，该回合，该怪兽不可攻击，也不可发动效果。此外，自己场上没有魔法师族怪兽存在的情况下，该卡将被破坏。','攻击效果限制','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25415052,'灵魂鸟神－姬孔雀',replace(replace('以“灵魂鸟之降神”降临\r\n此卡仅可以仪式召唤方式特殊召唤。\r\n①：此卡仪式召唤的情况下可以发动。将对手场上的最多３张魔法・陷阱卡放回牌组。然后，可从牌组将１只等级４以下的灵魂怪兽无视召唤条件特殊召唤。\r\n②：此卡特殊召唤的回合的结束阶段发动。将此卡放回手牌，将２只“灵魂鸟衍生物”（鸟兽族・风・星４・攻／守１５００）特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'对手魔法·陷阱回到牌组','是否从牌组把灵魂怪兽特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25415053,'灵魂鸟衍生物','由“灵魂鸟神－姬孔雀”“灵魂鸟神－彦孔雀”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25415161,'守宝团・途中插曲',replace(replace('此卡名的①②效果１回合仅可各使用１次。①：对手发动卡的效果时可以发动。挑选自己场上的１只“守宝团”超量怪兽，放回持有者的额外牌组。然后从以下效果中挑选１个适用。\r\n●将该发动的效果无效。\r\n●从自己的墓地挑选１只等级８怪兽特殊召唤。\r\n②：自己场上的表侧表示超量怪兽因效果离开场上的情况下可以发动。对手场上所有怪兽的攻击力直至回合结束时为止下降１０００。','\r',char(13)),'\n',char(10)),'','','效果无效','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25419323,'恐啡肽骇龙・甲壳','此卡名的卡１回合仅可发动１张。①：在对手的战斗阶段开始时，支付一半LP可以发动。将１只“恐啡肽骇龙衍生物”（恐龙族・暗・星１０・攻０／守３０００）特殊召唤至自己场上。此回合，只要以此效果特殊召唤的衍生物存在于自己场上，对手不可将其他怪兽选择为攻击对象。②：自己的LP为２０００以下，自己受到战斗伤害的伤害计算时，将墓地的此卡除外可以发动。将因该战斗对自己造成的战斗伤害改成０。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25419324,'恐啡肽骇龙衍生物','由「恐啡肽骇龙・甲壳」的效果特殊召唤。这个回合，只要这个效果特殊召唤的衍生物在自己场上存在，对方不能选择其他怪兽作为攻击对象。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25435080,'黑羽－力锚','可释放我方场上１只冠有“黑羽”之名的怪兽，并选择我方场上的１只同步怪兽发动。直至回合结束时，被选择怪兽的攻击力上升相当于为发动该卡而释放的怪兽的攻击力。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25449584,'地葬星 怪座',replace(replace('此卡名以①方法的特殊召唤１回合仅可进行１次，且②效果１回合仅可使用１次。\r\n①：解放自己场上的１只光属性或地属性战士族怪兽，可从手牌将此卡特殊召唤。以此方法特殊召唤的此卡的攻击力上升相当于所解放怪兽原本攻击力的数值。\r\n②：从自己的墓地将１只战士族怪兽除外可以发动。从牌组将１只光属性或地属性战士族怪兽送至墓地。','\r',char(13)),'\n',char(10)),'','出场方式为特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25451383,'黑衣龙 阿尔比昂',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：此卡只要存在于场上・墓地，卡名视为“阿尔白斯之落胤”。\r\n②：此卡存在于手牌・墓地的情况下，从手牌・牌组将1只“阿尔白斯之落胤”或1张“烙印”魔法・陷阱卡送至墓地可以发动。根据从何处将该卡送至墓地，适用以下效果。\r\n●手牌：将此卡特殊召唤。\r\n●牌组：将此卡放回牌组最下面。是从手牌放回的情况下，自己进而抽1张。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25451652,'堕天使 路西菲尔',replace(replace('此卡不可特殊召唤。\r\n①：此卡上级召唤的情况下可以发动。以对手场上的效果怪兽的数量为上限，从手牌・牌组将“堕天使”怪兽特殊召唤。\r\n②：只要自己场上存在其他“堕天使”怪兽，对手不可将此卡作为效果的对象。\r\n③：1回合1次，在自己的主要阶段可以发动。依场上的“堕天使”怪兽的数量从自己牌组上面将卡送至墓地，自己恢复送至了墓地的“堕天使”卡的数量×500的LP。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25460258,'暗黑耀星龙','①：将自己墓地的光属性和暗属性怪兽各1只除外，可将此卡从手牌特殊召唤。②：1回合1次，从手牌及牌组各将1只龙族怪兽送至墓地，可以自己或对手墓地的1张卡为对象发动。将该卡除外。','除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25472513,'天轮之双星道士',replace(replace('协调＋1只协调以外的怪兽\r\n此卡名的效果1回合仅可使用1次。①：此卡同步召唤成功时可以发动。从自己的手牌・墓地挑选最多4只协调以外的等级2怪兽，以守备表示特殊召唤。以此效果特殊召唤的怪兽的效果无效化。此效果发动后，直至回合结束时为止自己从额外牌组仅可特殊召唤同步怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25484449,'发条鲨',replace(replace('①：在有“发条”怪兽被召唤或特殊召唤至我方场上时，可以发动。将这张卡从手牌中特殊召唤。\r\n②：１回合１次，可以从以下效果中选择１项发动。\r\n●这张卡的等级提升１，直到回合结束。\r\n●这张卡的等级下降１，直到回合结束。','\r',char(13)),'\n',char(10)),'特殊召唤','等级变换','等级上升','等级下降','','','','','','','','','','','','');
INSERT INTO texts VALUES(25494711,'文具博格００９','①：１回合１次，在自己主要阶段１可以发动。此卡的攻击力直至对手回合结束时为止，上升相当于自己场上“文具博格００９”以外的“文具博格”怪兽的攻击力的合计数值。发动此效果的回合中，仅此卡可攻击。②：此卡进行战斗的情况下，对手直至伤害步骤结束时为止，不可发动魔法・陷阱・怪兽的效果。③：此卡将被战斗・效果破坏的情况下。可破坏自己场上的１张“文具博格”卡作为代替。','是否使用「文具博格００９」的效果代替破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25518020,'机器开发工厂','只要此卡存在于场上，场上的机械族怪兽攻击力上升２００点。每次场上的机械族怪兽因战斗或卡牌效果被破坏，放置２个废品计数物在此卡。此外，可将放置有废品计数物的此卡送入墓地并发动。从我方墓地选择１只持有等级为放置在此卡的废品计数物数量或以下的机械族怪兽并特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25524823,'守墓的审神者',replace(replace('可释放３只怪兽或１只冠有“守墓的”之名的怪兽来召唤此卡。成功召唤此卡时，可根据该召唤中所释放的冠有“守墓的”之名的怪兽数量来选择并发动以下效果中的一项或多项。\r\n●此卡的攻击力上升该召唤中所释放怪兽的合计等级×１００点。\r\n●破坏对手场上所有被盖牌的怪兽。\r\n●对手场上所有怪兽的攻击力和守备力下降２０００点。','\r',char(13)),'\n',char(10)),'解放3只怪兽召唤','解放1只名字带有「守墓」的怪兽召唤','此卡的攻击力上升','对手场上放置的怪兽全部破坏','对手场上的全部怪兽的攻击力·守备力下降','是否要继续选择效果发动？','效果发动','','','','','','','','','');
INSERT INTO texts VALUES(25531465,'魔法猫','①：此卡作为魔法师族怪兽的同步素材被送至墓地的情况下，以自己墓地的１张魔法卡为对象可以发动。将该卡放在牌组最上面。','返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25533642,'幻变骚灵・寻路美露莘',replace(replace('此卡名的③效果1回合仅可使用1次。\r\n①：此卡可直接攻击。\r\n②：此卡给予对手战斗伤害时，以对手场上的1张卡为对象可以发动。将该卡送至墓地。\r\n③：此卡从场上被送至墓地的情况下可以发动。从牌组将“幻变骚灵・寻路美露莘”以外的1只“幻变骚灵”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25538345,'魅影骑士团裂鳞甲',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：舍弃1张手牌可以发动。从牌组将“魅影骑士团裂鳞甲”以外的1只“魅影骑士团”怪兽或1张“魅影”魔法・陷阱卡送至墓地。\r\n②：此卡存在于墓地的状态下，自己墓地的其他“魅影骑士团”怪兽或“魅影”魔法・陷阱卡被除外的情况下可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25542642,'魅影雾剑',replace(replace('以场上的1只效果怪兽为对象可以发动此卡。\r\n此卡名的②效果1回合仅可使用1次。\r\n①：对象怪兽不可攻击，效果无效化，双方的怪兽不可将对象怪兽选择为攻击对象。对象怪兽从场上离开时此卡将被破坏。\r\n②：将墓地的此卡除外，以自己墓地的1只“魅影骑士团”怪兽为对象可以发动。将该怪兽特殊召唤。以此效果特殊召唤的怪兽从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25542643,'魅影雾剑',replace(replace('以场上的1只效果怪兽为对象可以发动此卡。\r\n此卡名的②效果1回合仅可使用1次。\r\n①：对象怪兽不可攻击，效果无效化，双方的怪兽不可将对象怪兽选择为攻击对象。对象怪兽从场上离开时此卡将被破坏。\r\n②：将墓地的此卡除外，以自己墓地的1只“魅影骑士团”怪兽为对象可以发动。将该怪兽特殊召唤。以此效果特殊召唤的怪兽从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25550531,'皮尔莉','①：此卡召唤・特殊召唤成功的情况下可以发动。从自己的牌组上面翻开３张卡。可从中挑选１张“皮尔莉”魔法・陷阱卡加入手牌。将剩余的卡以喜欢的顺序放回牌组下方。②：１回合１次，在自己的主要阶段可以发动。向对手出示手牌的１张“皮尔莉”速攻魔法卡，将１只记载有该卡名的超量怪兽重叠在自己场上的此卡上面，视为超量召唤从额外牌组特殊召唤，将所出示的卡重叠在该超量怪兽下方作为超量素材。','','','是否选1张「皮尔莉」魔法·陷阱卡加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25551951,'回膛手枪龙','①：１回合１次，可以对手场上的１张卡牌为对象发动。掷硬币３次，其中出现２次正面的场合，破坏该对手卡牌。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25554552,'枪弹装填者',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将1只龙族・暗属性・等级7怪兽加入手牌。此效果发动后，直至回合结束时为止，自己从额外牌组仅可特殊召唤暗属性怪兽。\r\n②：将墓地的此卡除外，以场上的1只表侧表示怪兽为对象可以发动。将该怪兽的属性直至回合结束时为止改成暗属性。','\r',char(13)),'\n',char(10)),'检索效果','改变属性','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25573054,'进化之翼','①：将自己场上的1只“羽翼库里波”与2张手牌送至墓地可以发动。从手牌・牌组将1只“羽翼库里波 LV10”特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25573115,'绝对猎食',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：被通常召唤的怪兽存在于自己场上的情况下可以发动。将场上被特殊召唤的怪兽全部破坏。此卡发动后，直至下一个自己回合结束时为止，自己不可通常召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25577965,'炎魔刃 火舌',replace(replace('炎属性怪兽２只\r\n此卡名的②效果１回合仅可使用１次。\r\n①：只要此卡存在于怪兽区域，自己场上表侧表示的魔法・陷阱卡不会因对手的效果被破坏。\r\n②：以自己除外状态的１只炎属性怪兽为对象可以发动。将该怪兽加入手牌。此回合，自己不可发动以此效果加入手牌的卡及其同名卡的效果。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25578802,'二人小组战斗','各玩家在自己回合的结束阶段时可有１次机会，从手牌特殊召唤１只等级４的通常怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25586143,'捕食植物 奇美拉大王花',replace(replace('“捕食植物”怪兽＋暗属性怪兽\r\n①：１回合１次，以场上１只拥有此卡等级以下等级的怪兽为对象可以发动。将该怪兽除外。②：此卡与对手的表侧表示怪兽进行战斗的攻击宣言时可以发动。直至回合结束时为止，该对手怪兽的攻击力下降１０００，此卡的攻击力上升１０００。③：此卡被送至墓地的情况下，在下一个准备阶段可以发动。从牌组将１张“融合”魔法卡或“结合”魔法卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25592142,'白森的阿斯特娅',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：从自己的手牌・场上将１张魔法・陷阱卡送至墓地可以发动。从牌组将１只魔法师族・光属性协调特殊召唤。\r\n②：此卡存在于墓地的状态下，魔法・陷阱卡为发动怪兽的效果被送至自己墓地的情况下可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'从牌组特殊召唤','从墓地特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25592143,'白森的阿斯特娅',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：从自己的手牌・场上将１张魔法・陷阱卡送至墓地可以发动。从牌组将１只魔法师族・光属性协调特殊召唤。\r\n②：此卡存在于墓地的状态下，魔法・陷阱卡为发动怪兽的效果被送至自己墓地的情况下可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'从牌组特殊召唤','从墓地特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25607552,'华信龙－诺鲁孜・艾蕊丝','此卡名的①②效果１回合仅可各使用１次。①：此卡存在于墓地的情况下，从手牌将１只等级５以上的怪兽送至墓地可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡离开场上的情况下，将其除外。②：此卡因战斗或对手的效果被破坏的情况下，以对手场上的１张卡为对象可以发动。将该卡除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25614410,'－英雄－之遗产','此卡名的卡1回合仅可发动1张。①：从自己的墓地将2只以“-英雄”怪兽作为融合素材的融合怪兽放回额外牌组可以发动。自己从牌组抽3张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25629622,'魔界剧团－巨星',replace(replace('←3 【灵摆】 3→\r\n①：1回合1次，可解放自己场上的1只“魔界剧团”怪兽，以自己墓地的1张“魔界剧本”魔法卡为对象发动。将该卡加入手牌。\r\n【怪兽效果】\r\n①：此卡召唤・特殊召唤成功时，对手不可发动魔法・陷阱卡的效果。②：1回合1次，在自己主要阶段可以发动。从牌组挑选1张“魔界剧本”魔法卡放置在自己场上。以此效果放置的卡会在结束阶段被送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25642998,'海神狂潮','在对手怪兽攻击宣言时选择该１只怪兽可以发动。使该攻击无效，自己场上有鱼族・海龙族・水族怪兽存在的情况下，给予对手LP该数量×８００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25643346,'恶之魔娘 玛丽斯','此卡名的效果1回合仅可使用1次。①：解放自己场上的2只怪兽，从自己墓地的卡及自己被除外的卡中，以1张通常陷阱卡为对象可以发动。将该卡放置在自己场上。以此效果放置的卡从场上离开的情况下，放回持有者牌组的最下面。此效果在对手回合中也可以发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25652259,'王后骑士','运用柔软的动作耍弄敌人，逮住对手的空隙后不断展开迅速攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25652655,'变换同步士','此卡被使用于同步怪兽的同步召唤并被送入墓地的场合，选择对手场上的１只怪兽并变更其表示形式。','变更表示形式','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25654671,'大植然蜘蛛牙','此卡仅可在对手发动魔法、陷阱、怪兽效果的回合进行攻击宣言。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25655502,'魔鬼之箱','“杀人小丑”＋“梦境小丑”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25661743,'绝解狱神门－特尔米纳斯',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从牌组・额外牌组将1只“狱神”怪兽送至墓地。然后，可从牌组将1只天使族・暗属性怪兽加入手牌。此回合，自己仅可用“狱神”怪兽攻击宣言。\r\n②：自己的“狱神”怪兽与对手怪兽进行战斗的伤害步骤开始时，将墓地的此卡除外可以发动。将该对手怪兽以里侧除外。','\r',char(13)),'\n',char(10)),'送至墓地','除外','是否加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25669282,'完全燃烧',replace(replace('“完全燃烧”１回合只可发动１张。\r\n①：可将我方场上的１只表侧表示的“化合兽”怪兽除外并发动。从牌组特殊召唤２只“化合兽”怪兽（同名卡最多１张）。\r\n②：在对手怪兽的直接攻击宣言时，可将墓地的此卡除外，并以１只被除外的我方的二重怪兽为对象发动。特殊召唤该怪兽。以此效果特殊召唤的怪兽被视为再１次被召唤状态。该效果不可在此卡被送入墓地的回合发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25682811,'龙骑兵团骑士－轻木掷枪',replace(replace('龙族协调＋协调以外的鸟兽族怪兽1只以上\r\n①：此卡同步召唤时，以自己墓地任意数量的龙族的“龙骑兵团”怪兽为对象可以发动。将该龙族怪兽视为装备魔法卡装备于此卡。\r\n②：此卡的攻击力上升被装备于此卡的“龙骑兵团”卡的数量×300的数值。','\r',char(13)),'\n',char(10)),'装备','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25687946,'梅尔菲摔倒倒',replace(replace('发动此卡的回合中，自己仅可特殊召唤“梅尔菲”怪兽。\r\n此卡名的②效果1回合仅可使用1次。\r\n①：从牌组将最多4只“梅尔菲”怪兽加入手牌（同名卡最多1张）。然后，直接变为此回合的结束阶段。\r\n②：将墓地的此卡除外，以“梅尔菲摔倒倒”以外的、自己墓地的2张“梅尔菲”卡为对象可以发动。将其中1张加入手牌，另1张放回牌组最下面。','\r',char(13)),'\n',char(10)),'检索','回收','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25700114,'尘小妖除尘筒','可选择场上的１只怪兽并发动。此回合，被选择怪兽不可进行释放。也不可成为融合、同步、超量召唤的素材。此外，被盖牌的此卡因对手卡牌的效果被破坏并送入墓地的场合可发动。从牌组将１只冠有“尘小妖”之名的怪兽加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25704359,'凭依解放',replace(replace('此卡名的③效果1回合仅可使用1次。\r\n①：自己的“灵使”怪兽不会因战斗被破坏。\r\n②：自己的“凭依装着”怪兽的攻击力仅在攻击对手怪兽的伤害计算时上升800。\r\n③：此卡存在于魔法与陷阱区域的状态下，自己场上的怪兽因战斗・效果被破坏的情况下可以发动。从牌组将原本属性与其中1只不同的、守备力1500的1只魔法师族怪兽以表侧攻击表示或里侧守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25716180,'发条猫咪','可以在我方主要阶段发动。选择对手场上的１只怪兽，将其移回其拥有者的手牌。此卡面朝上在场上期间，此效果只能使用１次。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25725326,'调皮宝贝・缪',replace(replace('等级4以下的“调皮宝贝”怪兽1只\r\n自己在1个回合中只能连接召唤“调皮宝贝・缪”1次，该效果在1个回合中只能使用1次。\r\n①：在对手的回合中，在自己场上的“调皮宝贝”怪兽为发动效果而解放自身的情况下，可以除外场上、墓地的此卡作为替代。','\r',char(13)),'\n',char(10)),'请选择要解放或代替解放除外的卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25726386,'巨石异物・阿拉特隆','以“巨石异物”卡降临。此卡名的①②效果1回合仅可各使用1次。①：在自己・对手的主要阶段，从手牌将此卡舍弃可以发动。为使合计等级为仪式召唤的怪兽以上，解放自己手牌・场上的怪兽，从手牌将1只“巨石异物”仪式怪兽仪式召唤。②：以自己场上的卡为对象的对手效果发动时可以发动。从自己的墓地挑选1只仪式怪兽放回牌组最下面，将该发动无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25727454,'名匠 加米尔','①：从我方怪兽进行战斗的伤害步骤开始时到伤害计算前，可将此卡从手牌送入墓地并发动。该怪兽的攻击力直至回合结束时上升３００。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25733157,'闪刀机－鹰式助推器','①：自己的主要怪兽区域不存在怪兽的情况下，以场上的1只表侧表示怪兽为对象可以发动。该表侧表示怪兽直至回合结束时为止，不受自身以外的卡的效果影响。自己墓地存在3张以上的魔法卡的情况下，进而在此回合，该怪兽不会因战斗被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25750986,'永恒混沌','此卡名的卡１回合仅可发动１张。①：以对手场上的１只表侧表示怪兽为对象可以发动。从牌组将攻击力合计为该怪兽的攻击力以下的、光属性和暗属性怪兽各１只送至墓地。此卡发动后，直至回合结束时为止，自己仅可发动墓地怪兽的效果１次。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25769732,'机械改造工厂','仅限装备机械族怪兽。令１只装备怪兽的攻击力和守备力上升３００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25771826,'正义盟军 螺旋雷剑','此卡和光属性怪兽进行战斗的场合，伤害步骤期间攻击力上升２００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25773409,'传说的柔术家','与守备表示的此卡进行了战斗的怪兽，在伤害步骤结束时返回至持有者牌组的最上面。','返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25774450,'死之魔术箱','①：以自己及对手场上各1只怪兽为对象可以发动。将该对手的怪兽破坏。然后，将该自己的怪兽的控制权转移给对手。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25784595,'骸骨恶魔',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡存在于手牌・墓地的情况下，将自己手牌・场上此卡以外的１张卡送至墓地可以发动。将此卡特殊召唤。此效果发动后，直至回合结束时为止，自己从额外牌组仅可特殊召唤龙族・暗属性同步怪兽。\r\n②：以自己场上的１只表侧表示怪兽为对象可以发动。从手牌・牌组将１只恶魔族协调送至墓地，对象怪兽的等级上升或下降１。','\r',char(13)),'\n',char(10)),'','等级上升','等级下降','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25788011,'调星师 莱斯贝尔特','①：此卡特殊召唤成功时，以场上1只表侧表示怪兽为对象可以发动。直至回合结束时为止，该怪兽的等级上升最多3。','等级上升','等级上升1','等级上升2','等级上升3','','','','','','','','','','','','');
INSERT INTO texts VALUES(25789292,'禁忌的圣杯','①：以场上的1只表侧表示怪兽为对象可以发动。该怪兽直至回合结束时为止，攻击力上升400，效果无效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25789293,'禁忌的圣杯','①：以场上的1只表侧表示怪兽为对象可以发动。该怪兽直至回合结束时为止，攻击力上升400，效果无效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25793414,'风魔女－水晶铃',replace(replace('“风魔女-冬铃”＋“风魔女”怪兽\r\n此卡名的①②效果1回合仅可各使用1次。①：以自己或对手墓地的1只怪兽为对象可以发动。直至结束阶段为止，此卡视为该怪兽的同名卡，获得相同效果。②：此卡因对手被破坏并被送至墓地的情况下，以自己墓地的1只“风魔女-冬铃”和1只等级4以下的“风魔女”怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'复制效果','特殊召唤','结束复制效果','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25795273,'光幻独角兔','①：只要此卡存在于怪兽区域，场上的怪兽的攻击力・守备力下降其等级・阶级×300。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25796442,'仪式之槛',replace(replace('①：只要此卡存在于魔法与陷阱区域，我方的仪式怪兽因战斗而产生的自身战斗伤害变为０。\r\n②：只要此卡存在于魔法与陷阱区域，我方场上的仪式怪兽不会成为怪兽的效果对象，也不会因怪兽的效果被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25800447,'火焰结合','此卡的卡名在规则上也视为“转生炎兽”卡。此卡名的卡1回合仅可发动1张。①：从自己的手牌及自己・对手场上，将由“转生炎兽”融合怪兽卡决定的融合素材怪兽送至墓地，从额外牌组将1只该融合怪兽融合召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25801745,'肃声之祈祷者 律',replace(replace('此卡名的①③效果１回合仅可各使用１次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将１张“肃声”永续魔法・永续陷阱卡以表侧表示放在自己的魔法与陷阱区域。\r\n②：仪式召唤１只战士族・龙族的光属性仪式怪兽的情况下，使用１张此卡即可作为仪式召唤所必需的解放。\r\n③：此卡存在于墓地的状态下，战士族・龙族的光属性仪式怪兽被特殊召唤至自己场上的情况下可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25807544,'大圣剑博物馆',replace(replace('①：自己场上的战士族・炎属性怪兽的攻击力上升５００。\r\n②：１回合１次，支付１２００LP可以发动。从牌组将“大圣剑博物馆”以外的１张“圣剑”卡加入手牌。\r\n③：在适用了此卡的②效果的每个回合有１次，以自己的魔法与陷阱区域的１张“圣骑士”怪兽卡为对象可以发动。将该卡特殊召唤。此效果是在自己场上不存在“焰圣骑士帝－查理”的状态下发动的情况下，直至回合结束时为止自己仅可特殊召唤战士族怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25811989,'狱炎机・阿斯蒙达',replace(replace('此卡不可通常召唤。\r\n仅可在自己场上的效果怪兽的等级・阶级的合计为８以下时，将自己的手牌・墓地的２只“狱炎机”怪兽除外的情况下从手牌・墓地特殊召唤。\r\n①：此卡攻击对手怪兽并给予对手战斗伤害时可以发动。随机将对手的１张手牌送至墓地。\r\n②：在每个自己・对手回合中１次，解放自己场上的１只怪兽，以对手墓地的１张卡为对象可以发动。将该卡除外。','\r',char(13)),'\n',char(10)),'手牌破坏','对手墓地的卡除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25824484,'森罗的仙树 雷基亚','１回合１次，可在我方主要阶段时发动。翻阅我方牌组最上方的卡牌。翻阅的卡牌是植物族怪兽的场合，将该怪兽送入墓地，从牌组抽取１张卡牌。不是的场合，将该卡牌返回至牌组最下方。此外，牌组的此卡因卡牌效果被翻阅并送入墓地的场合，最多确认我方牌组最上方的３张卡牌，并依照喜欢的顺序返回至牌组上方。','确认牌组','确认牌组顺序','请选择要确认的数量','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25833572,'门之守护者',replace(replace('此卡不可通常召唤。\r\n解放自己场上的“雷魔神－桑迦”、“风魔神－休迦”、“水魔神－苏迦”各１只的情况下可以特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25845518,'龙骑兵团・炽辉',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从自己牌组・墓地将1只等级5以上的“龙骑兵团”怪兽加入手牌。\r\n②：将墓地的此卡除外，以1张被装备于“龙骑兵团”怪兽的、自己的魔法与陷阱区域的怪兽卡为对象可以发动。将该卡以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25847467,'暗黑界之刺客 土黄其','此卡因卡牌效果从手牌被舍弃至墓地的场合，选择场上的１只怪兽破坏。','把场上1只怪兽破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25853045,'全装甲－黑鳍枪兵',replace(replace('水属性等级４怪兽×３\r\n此卡也可重叠在自己场上没有超量素材的阶级３水属性超量怪兽上面来超量召唤。\r\n①：此卡的攻击力上升相当于此卡的超量素材的数量×２００的数值。\r\n②：此卡战斗破坏对手怪兽时，以对手场上的１张魔法・陷阱卡为对象可以发动。将该对手的卡破坏。\r\n③：场上的此卡将被战斗・效果破坏的情况下，作为代替可将此卡的超量素材全部去除。','\r',char(13)),'\n',char(10)),'是否在没有超量素材的水属性·3阶超量怪兽上面重叠超量召唤？','是否要使用「全装甲－黑鳍枪兵」的效果代替破坏？','魔陷破坏','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25857246,'瓦尔基鲁斯的影灵衣',replace(replace('以“影灵衣”仪式魔法卡降临\r\n此卡仅可以仪式召唤方式特殊召唤，且仪式召唤仅可使用等级8以外的怪兽。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：对手怪兽攻击宣言时，从自己墓地将1张“影灵衣”卡除外，从手牌将此卡舍弃可以发动。将该攻击无效。然后，结束战斗阶段。\r\n②：在自己的主要阶段可以发动。将自己手牌・场上的最多2只怪兽解放，自己依其数量抽牌。','\r',char(13)),'\n',char(10)),'攻击无效','抽牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25857977,'DDD 死讴王恶德镇魂曲',replace(replace('←4 【灵摆】 4→\r\n此卡名的灵摆效果１回合仅可使用１次。①：以自己场上任意数量的“契约书”卡为对象可以发动。将该卡破坏，将灵摆区域的此卡特殊召唤。然后可将此卡的等级上升或下降相当于所破坏数量的数值。\r\n【怪兽效果】\r\n此卡名的②怪兽效果１回合仅可使用１次。①：只要此卡存在于怪兽区域，自己仅可特殊召唤“DDD”怪兽。②：以场上的此卡作为素材的融合・同步・超量・连接召唤的“DDD”怪兽获得以下效果。\n●１回合１次，以场上的１张卡为对象可以发动。从自己的场上・墓地挑选１张“契约书”卡放回持有者的牌组，将对象卡破坏。然后自己恢复１０００LP。','\r',char(13)),'\n',char(10)),'','破坏卡片（DDD 死讴王恶德镇魂曲）','不改变等级','上升等级','下降等级','「DDD 死讴王恶德镇魂曲」效果适用中','','','','','','','','','','');
INSERT INTO texts VALUES(25861589,'芬芳调香',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：舍弃１张手牌可以发动。从手牌・牌组将“润泽之风”、“干渴之风”、“惠畅之风”中的任意１张以表侧表示放在自己的魔法与陷阱区域。\r\n②：将墓地的此卡除外可以发动。将自己手牌・场上的怪兽作为融合素材除外，将１只植物族融合怪兽融合召唤。自己的LP多于对手的情况下，也可将自己墓地的植物族怪兽除外作为融合素材。','\r',char(13)),'\n',char(10)),'','放置','融合召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25862681,'上古精灵龙',replace(replace('协调＋协调以外的怪兽１只以上\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：在自己的主要阶段可以发动（发动此效果的回合中，自己无法进行战斗阶段）。从手牌将１只等级４以下的怪兽特殊召唤。\r\n②：在自己的主要阶段可以发动。将场地区域的卡全部破坏，自己恢复１０００LP。然后，可从牌组将１张卡名与所破坏的卡不同的场地魔法卡加入手牌。','\r',char(13)),'\n',char(10)),'从手牌把1只4星以下的怪兽特殊召唤','把场地全部破坏','是否要选一张场地魔法加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25865565,'水晶机巧－柠晶法瓦多',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡存在于手牌・墓地的情况下，以自己场上的1张“水晶机巧”卡为对象可以发动。将该卡破坏，将此卡特殊召唤。此回合，自己从额外牌组仅可特殊召唤机械族怪兽。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从牌组将“水晶机巧－柠晶法瓦多”以外的最多2张“水晶机巧”卡送至墓地（同名卡最多1张）。','\r',char(13)),'\n',char(10)),'特殊召唤','送至墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25866285,'大植然椿象','①：自己的“大植然”怪兽被选择为攻击对象时，将场上的此卡送至墓地可以发动。使该攻击无效，然后结束战斗阶段。','攻击无效并结束战斗阶段','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25880422,'『攻击』封印','选择对手场上１只以表侧攻击表示存在的怪兽变为表侧守备表示。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25882881,'死神骷髅','使出地狱的一击夺取灵魂的死神。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25904894,'机偶大权现 无零武',replace(replace('协调＋１只以上协调以外的机械族怪兽\r\n①：此卡同步召唤成功的情况下可以发动。从牌组将１只“机偶”怪兽特殊召唤。②：只要此卡存在于怪兽区域，自己的守备表示怪兽不会因战斗被破坏。③：１回合１次，自己场上表侧表示的“机偶”怪兽的表示形式被变更的情况下，以对手场上的１张卡为对象可以发动。将该卡除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25908748,'铁兽之战线','此卡名的②效果１回合仅可使用１次。①：只要此卡存在于魔法与陷阱区域，自己从额外牌组仅可特殊召唤兽族・兽战士族・鸟兽族怪兽。②：从自己的手牌・场上将１只怪兽送至墓地可以发动。将１只原本种族与送至墓地怪兽不同的“铁兽”怪兽从牌组加入手牌。③：魔法与陷阱区域的此卡因对手的效果被破坏的情况下可以发动。此回合对手不可攻击宣言。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25919316,'维修站骑士・菲儿',replace(replace('效果怪兽2只\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡被特殊召唤至连接怪兽的连接端的情况下，以自己场上的1只攻击力1500以下的怪兽为对象可以发动。此回合，该怪兽在1次战斗阶段中可攻击2次，该怪兽与对手怪兽的战斗给予对手的战斗伤害变为两倍。\r\n②：此卡因战斗・效果被破坏并被送至墓地的情况下，在下个回合的准备阶段可以发动。从墓地将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'2次攻击','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25920413,'外星人骷髅','可解放对手场上１只等级３以下的怪兽，并从手牌将此卡特殊召唤至对手场上。以此方法特殊召唤的回合，我方不可通常召唤。以此方法特殊召唤成功时，在此卡放置１个A计数物。只要此卡以表侧表示存在于场上，仅限在放置有A计数物的怪兽与冠有“外星人”之名的怪兽进行战斗的伤害计算时，攻击力、守备力下降该A计数器数量×３００点。','放置「A计数物」','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25924653,'剑斗兽 战马',replace(replace('①：此卡以“剑斗兽”怪兽的效果特殊召唤时，以自己墓地的１只“剑斗兽”怪兽为对象可以发动。将该怪兽的效果无效并特殊召唤。此卡从场上离开时，该怪兽将被放回牌组。\r\n②：此卡进行过战斗的战斗阶段结束时，将此卡放回牌组可以发动。从牌组将“剑斗兽 战马”以外的１只“剑斗兽”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'墓地特殊召唤','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25926710,'古尖兵 凯尔伯克',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：卡从手牌・牌组被送至对手的墓地的情况下，以对手场上１只被特殊召唤的怪兽为对象可以发动。从手牌将此卡特殊召唤。然后，将对象怪兽放回持有者的手牌。\r\n②：此卡被从手牌・牌组被送至墓地的情况下可以发动。从双方的牌组上面将５张卡送至墓地。然后，自己的墓地有“现世与冥界的逆转”存在的情况下，可从自己的墓地挑选１张陷阱卡放置在自己场上。','\r',char(13)),'\n',char(10)),'此卡从手牌特殊召唤','','是否从墓地选1张陷阱卡放置？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25935625,'暗龙星－椒图','此卡名的①②效果1回合1次，仅可使用其中1个。①：自己场上的此卡因战斗・效果被破坏并被送至墓地时可以发动。从牌组将1只“暗龙星-椒图”以外的“龙星”怪兽以攻击表示特殊召唤。②：自己场上没有此卡以外的怪兽存在的情况下，将手牌的2张“龙星”卡送至墓地可以发动。从牌组将攻击力0和守备力0的“龙星”怪兽各1只特殊召唤。以此效果特殊召唤的怪兽在结束阶段被除外。','特殊召唤','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25940932,'绚岚之轩昂',replace(replace('①：可从以下效果中选择1个发动（此卡名的以下效果1回合仅可各选择1次）。\r\n●从自己墓地将1只等级6以下的“绚岚”怪兽特殊召唤。\r\n●从自己牌组・墓地将1张“气旋”加入手牌。\r\n②：此卡因“气旋”的效果被破坏的情况下可以发动。将此卡放置在自己的魔法与陷阱区域。','\r',char(13)),'\n',char(10)),'发动','放置','特殊召唤','检索','','','','','','','','','','','','');
INSERT INTO texts VALUES(25955164,'雷魔神－桑迦','①：只要此卡在场上以表侧表示存在，仅限１次，此卡被攻击的伤害计算时，以１只攻击怪兽为对象可以发动。仅在该伤害计算时将该攻击怪兽的攻击力改成０。','攻击变成0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25955749,'闪刀术式－干扰波','①：自己的主要怪兽区域不存在怪兽的情况下，以场上的1张里侧表示的魔法・陷阱卡为对象可以发动。将该卡破坏。然后，自己墓地存在3张以上的魔法卡的情况下，可将场上的1只怪兽破坏。','是否选怪兽卡破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25958491,'上古圣翼龙',replace(replace('光属性协调＋协调以外的怪兽1只以上\r\n①：自己的LP多于对手的情况下，此卡的攻击力上升相当于其数值之差。自己的LP少于对手的情况下，此卡的攻击力下降相当于其数值之差。\r\n②：此卡因战斗被破坏并被送至墓地时，支付1000LP可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25964547,'梦现之梦魔镜','此卡名的卡1回合仅可发动1张。①：从手牌・牌组挑选“圣光之梦魔镜”和“暗黑之梦魔镜”各1张，以表侧表示分别将其中1放在自己的场地区域，另1张放在对手的场地区域。','请选择要放置在自己场地区域的卡','请选择要放置在对手场地区域的卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(25988873,'龙骑兵团－阔头枪',replace(replace('①：此卡召唤时可以发动。从手牌将1只鸟兽族的“龙骑兵团”怪兽特殊召唤。然后，将自己场上的此卡视为装备魔法卡，装备于该怪兽。\r\n②：装备着此卡的怪兽视为协调。','\r',char(13)),'\n',char(10)),'特殊召唤并装备','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26016357,'魔幻甜点・柑橘酱女仆',replace(replace('①：此卡反转时，以自己墓地的１张“魔幻甜点”魔法・陷阱卡为对象可以发动。将该卡加入手牌。\r\n②：此卡被对手破坏并被送至墓地的情况下发动。将此卡放回牌组。','\r',char(13)),'\n',char(10)),'返回牌组','返回手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26022485,'衰弱之雾','对方手牌限制张数变成５张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26034577,'狱炎机・别西布鲁',replace(replace('此卡不可通常召唤。\r\n仅可在自己场上的效果怪兽的等级・阶级的合计为８以下时，将自己的手牌・墓地的１只“狱炎机”怪兽除外的情况下从手牌特殊召唤。\r\n①：１回合１次，以对手场上的１张表侧表示卡为对象可以发动。将该卡放回手牌。\r\n②：在每个对手回合中１次，解放自己场上的１只怪兽，以对手墓地的１张卡为对象可以发动。将该卡除外。','\r',char(13)),'\n',char(10)),'卡片回手','对手墓地的卡除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26046205,'恶忍','表侧攻击表示的此卡被选择为攻击对象时，从我方牌组抽取１张卡牌。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26050548,'额外毒海德拉',replace(replace('被从额外牌组特殊召唤的自己场上的怪兽×２只以上\r\n①：只要此卡存在于怪兽区域，对手场上种类（融合・同步・超量・灵摆・连接）和作为此卡的融合素材的怪兽种类相同的怪兽，攻击力下降相当于其原本攻击力的数值。\r\n②：此卡给予对手１０００以上的战斗伤害时可以发动。该伤害每有１０００，自己抽１张。','\r',char(13)),'\n',char(10)),'以融合怪兽为融合素材','以同步怪兽为融合素材','以超量怪兽为融合素材','以灵摆怪兽为融合素材','以连接怪兽为融合素材','','','','','','','','','','','');
INSERT INTO texts VALUES(26057276,'卫星骑士 猎户贝忒基乌斯','此卡名的效果１回合仅可使用１次。①：此卡召唤・反转召唤・特殊召唤成功的情况下，以自己墓地的１张“卫星骑士 猎户贝忒基乌斯”以外的“星骑士”卡为对象可以发动。将此卡送至墓地，将对象卡加入手牌。','加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26077387,'闪刀姬－零',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己・对手回合中，解放此卡可以发动。从额外牌组将1只“闪刀姬”怪兽特殊召唤至额外怪兽区域。\r\n②：此卡存在于墓地的状态下，自己场上的“闪刀姬”连接怪兽因对手的效果从场上离开的情况下，或因战斗被破坏的情况下可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26077388,'闪刀姬－零',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己・对手回合中，解放此卡可以发动。从额外牌组将1只“闪刀姬”怪兽特殊召唤至额外怪兽区域。\r\n②：此卡存在于墓地的状态下，自己场上的“闪刀姬”连接怪兽因对手的效果从场上离开的情况下，或因战斗被破坏的情况下可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26077389,'闪刀姬－零',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己・对手回合中，解放此卡可以发动。从额外牌组将1只“闪刀姬”怪兽特殊召唤至额外怪兽区域。\r\n②：此卡存在于墓地的状态下，自己场上的“闪刀姬”连接怪兽因对手的效果从场上离开的情况下，或因战斗被破坏的情况下可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26077390,'闪刀姬－零',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己・对手回合中，解放此卡可以发动。从额外牌组将1只“闪刀姬”怪兽特殊召唤至额外怪兽区域。\r\n②：此卡存在于墓地的状态下，自己场上的“闪刀姬”连接怪兽因对手的效果从场上离开的情况下，或因战斗被破坏的情况下可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26082117,'我我我魔术师','此卡不可作为同步素材。①：“我我我魔术师”在自己场上仅可有１只以表侧表示存在。②：１回合１次，宣言１～８之间的任意等级可以发动。此卡的等级直至回合结束时为止，变为所宣言的等级。','等级变换','请宣言一个等级','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26082229,'侵略的炎','此卡的召唤成功时，不可发动陷阱卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26084285,'守墓的监视者','对手发动含有舍弃自己手牌效果的卡牌时，可将此卡从手牌送入墓地并发动。使该发动无效并破坏。','丢弃手牌效果无效并且破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26096328,'超重型炮塔列车 爱恋倾城炮',replace(replace('等级11怪兽×3\r\n“超重型炮塔列车 爱恋倾城炮”1回合1次，也可重叠在自己场上的机械族・阶级10的超量怪兽上面来超量召唤。\r\n①：1回合1次，去除此卡的1个超量素材可以发动。此卡的攻击力・守备力上升2000。此效果发动后，直至回合结束时为止，自己仅可用此卡攻击宣言。\r\n②：此卡在1次战斗阶段中，可攻击怪兽的次数最多为此卡超量素材数量＋1次。','\r',char(13)),'\n',char(10)),'是否在机械族超量怪兽上面重叠来超量召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26096329,'超重型炮塔列车 爱恋倾城炮',replace(replace('等级11怪兽×3\r\n“超重型炮塔列车 爱恋倾城炮”1回合1次，也可重叠在自己场上的机械族・阶级10的超量怪兽上面来超量召唤。\r\n①：1回合1次，去除此卡的1个超量素材可以发动。此卡的攻击力・守备力上升2000。此效果发动后，直至回合结束时为止，自己仅可用此卡攻击宣言。\r\n②：此卡在1次战斗阶段中，可攻击怪兽的次数最多为此卡超量素材数量＋1次。','\r',char(13)),'\n',char(10)),'是否在机械族超量怪兽上面重叠来超量召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26099457,'下降潮流','可选择我方场上１只表侧表示怪兽，宣言从１到３的任意等级并发动。被选择怪兽的等级变成宣言等级。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26116996,'祟纸之报应',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：以自己场上的1只怪兽和对手场上的1张表侧表示卡为对象可以发动。将该自己的怪兽破坏，将该对手的卡的效果直至回合结束时为止无效。\r\n②：被放置的此卡被送至墓地的情况下，以对手场上的1张表侧表示卡为对象可以发动。将该卡的效果无效。','\r',char(13)),'\n',char(10)),'效果无效','效果无效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26118970,'红蔷薇龙',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：此卡作为同步素材被送至墓地的情况下可以发动。从手牌・牌组将“红蔷薇龙”以外的1只“蔷薇龙”怪兽特殊召唤。此卡作为“黑蔷薇龙”或植物族同步怪兽的同步素材被送至墓地的情况下，进而可从牌组将1张“冷香蔷薇之抱吼”或“漆黑蔷薇之开华”加入手牌。','\r',char(13)),'\n',char(10)),'','是否选卡加入手牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26120084,'特殊二重召唤','选择１只以表侧表示存在于我方场上的二重怪兽使其变为再次召唤的状态。该回合的结束阶段时，所选择二重怪兽回到手牌中。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26157485,'链条・射手','１回合１次，将自己场上１只名字带有“链条”的怪兽送至墓地可以发动。给予对手LP８００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26162470,'飞龙战艇－帆朵拉',replace(replace('此卡名在规则上也视为“空牙团”卡。\r\n此卡名的②③效果1回合仅可各使用1次。\r\n①：自己场上的“空牙团”怪兽的攻击力上升相当于自己场上的“空牙团”怪兽的种类×300的数值。\r\n②：在自己的主要阶段可以发动。从牌组将1只“空牙团”怪兽加入手牌。然后，挑选自己的1张手牌舍弃。\r\n③：自己场上的表侧表示“空牙团”怪兽因对手的效果被破坏的情况下可以发动。从牌组将1只“空牙团”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'检索','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26185991,'代打蚱蜢','当我方场上的此卡被送入墓地时，可从我方手牌中特殊召唤１只昆虫族怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26194151,'死灵同步','此卡名在规则上也视为“机人”卡。①：从自己的墓地挑选1只协调和最多2只协调以外的怪兽除外，将1只拥有与除外怪兽等级合计相同等级的“星尘”同步怪兽从额外牌组特殊召唤，且视为同步召唤。以此效果特殊召唤的怪兽的效果无效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26202165,'三眼怪','此卡名的效果1回合仅可使用1次。①：此卡从场上被送至墓地的情况下发动。从牌组将1只攻击力1500以下的怪兽加入手牌。此回合，自己不可发动以此效果加入手牌的卡及该卡的同名卡的效果。','牌组检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26205777,'炎帝泰斯塔罗斯','①：此卡上级召唤的情况下发动。随机舍弃对手的1张手牌。所舍弃的卡为怪兽的情况下，进而给予对手其等级×100的伤害。','对手随机丢弃1张手牌去墓地','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26211048,'甲虫装机 艾克萨锹形虫',replace(replace('昆虫族等级５怪兽×２\r\n１回合１次，可移除此卡的１个超量素材并发动。选择对手场上、墓地的１只怪兽并将其视为装备卡装备此卡。此卡的攻击力、守备力上升相当于以此效果所装备之怪兽的攻击力、守备力一半数值。','\r',char(13)),'\n',char(10)),'装备','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26223582,'马赛鱼汤之布耶贝斯・饿魔新飨',replace(replace('以“食谱”卡降临\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡特殊召唤的情况下可以发动。从自己的牌组上面翻开５张卡。可从其中将１张“饿魔新飨”卡加入手牌。剩余的放回牌组。\r\n②：场上的此卡成为攻击・效果的对象时可以发动。解放此卡和自己・对手场上的１只攻击表示怪兽，从手牌・牌组将１只等级２・３的“饿魔新飨”仪式怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'翻开牌组检索','从手牌·牌组特殊召唤','是否选卡加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26232916,'隐之里－修练忍法之地',replace(replace('此卡牌名的①②效果１回合只可各使用１次。\r\n①：“忍者”怪兽被召唤、反转召唤、特殊召唤至我方场上的场合，可以我方墓地１只“忍者”怪兽或１张“忍法”卡牌为对象发动。将该卡牌加入手牌。此回合，我方不可发动因此效果加入手牌的卡牌及该同名卡的效果。\r\n①：我方场上的“忍者”怪兽或“忍法”卡牌因战斗或对手效果被破坏的场合，可将我方墓地的１只“忍者”怪兽除外作为代替。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26236560,'破械童子 安若般',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡存在于手牌的情况下，以自己场上的1张卡为对象可以发动。将该卡破坏，将此卡特殊召唤。此效果发动后，直至回合结束时为止自己仅可特殊召唤恶魔族怪兽。\r\n②：场上的此卡因战斗或“破械童子 安若般”以外的卡的效果被破坏的情况下可以发动。从手牌・牌组将“破械童子 安若般”以外的1只“破械”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26237713,'灵摆宝藏',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从牌组将1只灵摆怪兽以表侧加入额外牌组。','\r',char(13)),'\n',char(10)),'请选择要加入额外牌组的卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26254876,'二重枪兵',replace(replace('此卡存在于墓地或以表侧表示存在于场上的场合，将被视为通常怪兽。以通常召唤的方式再次召唤场上表侧表示的此卡，此卡将视为效果怪兽并获得以下效果。\r\n●此卡攻击守备表示的怪兽时，若此卡攻击力高于守备表示怪兽的守备力，给予对手生命超过部分数值的战斗伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26257572,'苦痛的回廊','只要此卡存在于场上，从牌组特殊召唤的怪兽，只要以表侧表示存在于场上其效果就不可发动并无效化，不可攻击宣言。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26259179,'交杯Ace',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：此卡存在于手牌的情况下可以发动。掷１次硬币。正面的情况下，将此卡特殊召唤至自己场上。背面的情况下，将此卡特殊召唤至对手场上。\r\n②：以此卡的①效果特殊召唤的情况下发动。自己抽２张。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26268488,'圣珖神龙 星尘零',replace(replace('同步怪兽的协调＋协调以外的同步怪兽2只以上\r\n此卡仅可以同步召唤方式特殊召唤。\r\n①：自己场上的卡1回合各仅1次不会因战斗・效果被破坏。\r\n②：1回合1次，对手发动怪兽的效果时可以发动。将该效果无效，将场上的1张卡破坏。\r\n③：将墓地的此卡除外，以自己墓地的1只等级8以下的“星尘”怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'效果无效，选场上1张卡破坏。','特殊召唤','已经使用过防止破坏效果','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26270847,'娱乐伙伴银爪狼',replace(replace('←5 【灵摆】 5→\r\n①：我方场上“娱乐伙伴”怪兽的攻击力上升３００。\r\n【怪兽效果】\r\n①：此卡的攻击宣言时发动。直至战斗阶段结束时，我方场上的“娱乐伙伴”怪兽的攻击力上升３００。','\r',char(13)),'\n',char(10)),'攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26273196,'时间魔导士',replace(replace('“时间魔术师”＋效果怪兽\r\n①：1回合1次，此卡是被融合召唤的情况下可以发动。掷1次硬币，猜正反。猜对的情况下，将场上的怪兽全部破坏，对手受到相当于以表侧表示被破坏的怪兽的原本攻击力合计数值的一半的伤害。猜错的情况下，将场上的怪兽全部破坏，自己受到相当于以表侧表示被破坏的怪兽的原本攻击力合计数值的一半的伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26285557,'刚鬼弃暗投明','此卡名的卡1回合仅可发动1张。①：以自己场上的1张“刚鬼”卡和自己墓地的1只“刚鬼”怪兽为对象可以发动。将对象之场上的卡破坏，将对象之墓地的怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26285788,'招来的对价',replace(replace('发动此卡回合的结束阶段时，依照此回合我方从手牌、场上释放的除衍生物以外的怪兽数量，适用以下效果。“招来的对价”１回合只可发动１张。\r\n●１只：从牌组抽取１张卡牌。\r\n●２只：从我方墓地挑选２只怪兽加入手牌。\r\n●３只或以上：最多可选择场上表侧表示的３张卡牌破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26293219,'燃烧骷髅头','此卡从手牌特殊召唤成功时，给予对手LP１０００点伤害。此外，将场上的此卡从游戏中除外可以发动。选择１只从游戏中被除外的“骷髅火焰”放回墓地。','伤害','返回墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26302107,'未界域之狼人','此卡名的②效果1回合仅可使用1次。①：向对手出示手牌中的此卡可以发动。对手从自己的所有手牌中随机挑选1张，自己舍弃该卡。该卡为“未界域之狼人”以外的情况下，进而从手牌将1只“未界域之狼人”特殊召唤，自己从牌组抽1张。②：此卡从手牌被舍弃的情况下可以发动。对手场上的所有怪兽的攻击力直至回合结束时为止下降1000。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26302522,'Sphere Bomb 球体限时炸弹',replace(replace('①：里侧守备表示的此卡受到对手怪兽攻击时发动，在伤害计算前将此卡视为装备卡装备至该攻击怪兽。\r\n②：以此此卡的效果装备于此卡后，在对手的下个准备阶段时发动，破坏装备怪兽并给予对手该攻击力的伤害。','\r',char(13)),'\n',char(10)),'装备','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26304459,'上古炎狱神',replace(replace('炎属性协调＋协调以外的炎族怪兽１只或以上\r\n此卡同步召唤成功时，选择对手墓地最多对手手牌数量的卡牌并从游戏中除外。此卡的攻击力上升以此效果除外的卡牌数量×２００点。','\r',char(13)),'\n',char(10)),'除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26308721,'捕食植物 翼龙猪笼草',replace(replace('①：此卡给予对手战斗伤害时，以对手场上的1只表侧表示怪兽为对象可以发动。在该怪兽上放1个捕食计数物。放有捕食计数物的等级2以上怪兽的等级变为1。\r\n②：1回合1次，以对手场上的1只等级在此卡等级以下的怪兽为对象可以发动。获得该怪兽的控制权直至结束阶段为止。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26326541,'业神－不知火',replace(replace('协调＋协调以外的怪兽１只以上\r\n自己１回合仅可特殊召唤１次“业神－不知火”，其②效果１回合仅可使用１次。\r\n①：此卡特殊召唤的情况下，以场上的１只怪兽为对象可以发动。变更该怪兽的表示形式。\r\n②：此卡被除外的情况下可以发动。将１只“不知火衍生物”（不死族・炎・星１・攻／守０）特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26326542,'不知火衍生物','由“业神－不知火”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26329679,'星圣 欧米伽星团',replace(replace('光属性等级4怪兽×2\r\n①：在每个自己・对手回合中1次，去除此卡的1个超量素材可以发动。自己场上的所有“星圣”怪兽直至回合结束时为止不受魔法・陷阱卡的效果影响。','\r',char(13)),'\n',char(10)),'效果免疫','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26334139,'峰回罪宝',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：从牌组挑选１只等级５以上的幻想魔族怪兽，加入手牌或特殊召唤。在此回合的主要阶段期间，自己不可发动以此效果特殊召唤的怪兽的效果。\r\n②：将墓地的此卡除外，以自己场上的１张里侧表示卡为对象可以发动。将该卡放回手牌。然后，可从手牌放置１张魔法・陷阱卡。','\r',char(13)),'\n',char(10)),'特殊召唤','回到手牌','是否放置？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26345570,'先史遗产－金字塔眼石板','我方场上冠有“先史遗产”之名的怪兽的攻击力上升８００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26357901,'死偿不知',replace(replace('①：我方的LP低于对手的场合，可从以下效果选择１个并发动。\r\n●挑选对手场上１只持有攻击力是该差额数值或以下的怪兽并破坏。\r\n●从我方墓地挑选１只持有攻击力是该差额数值或以下的怪兽并特殊召唤。','\r',char(13)),'\n',char(10)),'怪兽破坏','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26364381,'巨匠造物主 EMA',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从自己手牌・牌组・场上（表侧表示）将4只攻击力2400以上且守备力1000的怪兽送至墓地可以发动。从手牌将此卡特殊召唤。\r\n②：以自己及对手场上的各1张魔法・陷阱卡为对象可以发动。将该卡破坏。然后，各将1只“人工生命体衍生物”（天使族・光・星2・攻/守800）以守备表示特殊召唤至双方场上，此卡的攻击力上升1600。','\r',char(13)),'\n',char(10)),'特殊召唤','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26364382,'人工生命体衍生物','由「巨匠造物主 EMA」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26372118,'警报！',replace(replace('此卡名在规则上也视为“救援王牌”卡。\r\n此卡名的卡1回合仅可发动1张。\r\n①：从自己墓地挑选1只“救援王牌”怪兽加入手牌。自己场上存在“救援王牌 消防栓”的情况下，作为代替也可从牌组将1只“救援王牌”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26376390,'模仿幻想师','成功召唤・反转召唤・特殊召唤此卡时，选择对手场上１只表侧表示的怪兽发动此卡。令此卡的攻击力和守备力变为与所选择怪兽原始攻击力及原始守备力相同的数值。','攻守变换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26378150,'野蛮凯萨','魔人双手握的斧头，破坏力可是非常强大！','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26381750,'红莲地带的飞鹰','此卡被使用于同步怪兽的同步召唤并被送入墓地的场合，且我方墓地冠有“岩浆炎”之名的怪兽是３种或以上的场合，可从墓地特殊召唤此卡。以此效果特殊召唤的此卡，从场上离开的场合从游戏中被除外。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26387390,'废品信号',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：可从以下效果中选择1个发动。此回合，自己从额外牌组仅可特殊召唤同步怪兽。\r\n●解放自己场上的1只怪兽可以发动。从自己手牌・牌组・墓地将除该怪兽以外的1只“废品战士”“星尘龙”或记载有其中的任一卡名的怪兽特殊召唤。\r\n●对手连锁自己的同步怪兽的效果的发动，来发动效果时可以发动。将该对手的效果无效。','\r',char(13)),'\n',char(10)),'发动','特殊召唤','效果无效','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26400609,'瀑征龙－狂潮',replace(replace('此卡名的①～④效果１回合１次，仅可使用其中１个。\r\n①：从手牌将此卡与１只水属性怪兽舍弃至墓地可以发动。从牌组将１只怪兽送至墓地。\r\n②：从自己的手牌・墓地将２只龙族或水属性的怪兽除外可以发动。从手牌・墓地将此卡特殊召唤。\r\n③：此卡是被特殊召唤的情况下，在对手的结束阶段发动。将此卡放回手牌。\r\n④：此卡被除外的情况下可以发动。从牌组将１只龙族・水属性怪兽加入手牌。','\r',char(13)),'\n',char(10)),'从手牌特殊召唤','返回手牌','从牌组把1只怪兽送至墓地','加入手牌','','','','','','','','','','','','');
INSERT INTO texts VALUES(26412047,'槌击','破坏场上表侧攻击表示的攻击力最高的１只怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26420373,'疾行机人 超速滑翔机',replace(replace('←3 【灵摆】 3→\r\n①：１回合１次，从手牌及自己场上的表侧表示怪兽中，将１只“疾行机人”协调送至墓地可以发动。直至回合结束时为止，此卡的灵摆刻度上升或下降相当于送至墓地的该怪兽的原本等级的数值（最小下降至１）。\r\n【怪兽效果】\r\n“疾行机人 超速滑翔机”以①方法的特殊召唤１回合仅可进行１次。\n①：双方场上没有怪兽存在的情况下，此卡可从手牌中特殊召唤。\n②：此卡上级召唤成功时，以自己墓地１只等级４以下的“疾行机人”怪兽为对象可以发动。将该怪兽特殊召唤。\n③：只要此卡存在于怪兽区域，对手不可将其他的“疾行机人”怪兽选择为攻击对象。','\r',char(13)),'\n',char(10)),'刻度变更','刻度上升','刻度下降','墓地「疾行机人」怪兽特殊召唤','','','','','','','','','','','','');
INSERT INTO texts VALUES(26434972,'契印魔镌・怜歌颂',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：此回合中，自己的恶魔族・光属性怪兽不会因战斗被破坏，且自己受到的战斗伤害变为一半。\r\n②：将墓地的此卡除外可以发动。将自己场上的怪兽作为融合素材，将1只“魔镌”融合怪兽融合召唤。在此之际，装备于“魔镌”怪兽的、自己的魔法与陷阱区域视为装备魔法卡的融合素材怪兽也可作为融合素材使用。','\r',char(13)),'\n',char(10)),'不会被战斗破坏','融合召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26435595,'圣果使 巧皮儿',replace(replace('←1 【灵摆】 1→\r\n此卡名的灵摆效果１回合仅可使用１次。①：另一方自己的灵摆区域没有卡存在的情况下可以发动。从自己的额外牌组挑选１只表侧表示灵摆怪兽，放在自己的灵摆区域。\r\n【怪兽效果】\r\n灵摆怪兽×２\n①：怪兽区域的此卡被破坏的情况下可以发动。将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26439287,'原始电子龙','①：只要此卡存在于怪兽区域，卡名视为“电子龙”。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26443791,'蜂军－决战之重弩巨炮',replace(replace('协调＋协调以外的怪兽１只以上\r\n①：此卡特殊召唤的情况下，将自己墓地的昆虫族怪兽全部除外可以发动。对手场上所有怪兽的攻击力・守备力下降相当于自己除外状态的昆虫族怪兽的数量×５００的数值。\r\n②：此卡攻击了守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。\r\n③：同步召唤的此卡被对手破坏的情况下可以发动。将自己除外状态的３只等级１１以下的昆虫族怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'攻守下降','除外的怪兽特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26462013,'原石龙 异狱玄矿',replace(replace('“原石”怪兽＋通常怪兽1只以上\r\n①：此卡的攻击力上升相当于作为此卡融合素材的通常怪兽数量×1000的数值。\r\n②：只要此卡存在于怪兽区域，等级・阶级・连接的数值为自己场上・墓地的通常怪兽数量以下的、对手场上的怪兽发动的效果无效化。\r\n③：此卡从场上被送至墓地的情况下可以发动。从牌组将1只通常怪兽以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26493435,'希望乡－拟声乌托邦－','①：只要此卡存在于场地区域，每次“希望皇霍普”怪兽被特殊召唤至自己场上，在此卡上放１个勇往翔前计数物。②：自己场上怪兽的攻击力・守备力上升相当于此卡的勇往翔前计数物数量×２００的数值。③：１回合１次，去除此卡的２个勇往翔前计数物可以发动。从牌组将“刷拉拉”、“我我我”、“隆隆隆”、“怒怒怒”怪兽中的任意１只特殊召唤。','放置计数物','特殊召唤','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26495087,'吸血鬼淑女','此卡给予对手生命战斗伤害时，宣言卡牌的种类（怪兽、魔法、陷阱）并发动。对手将１张宣言种类的卡牌从牌组送入墓地。','送墓','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26509612,'地球重力','对手战斗阶段我方怪兽区上存在有“元素－英雄 地球”的场合可发动。该回合，能够发动攻击的对手的等级４或以下的怪兽必须攻击“元素－英雄 地球”。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26517393,'里风之精灵','①：此卡召唤的情况下可以发动。从牌组将1只反转怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26523337,'游魊之月夜 赛克斯',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将“游魊之月夜 赛克斯”以外的１只鱼族怪兽加入手牌。然后，将自己的手牌・场上（表侧表示）的１只鱼族怪兽除外。\r\n②：此卡被除外的情况下，从自己的手牌・场上（表侧表示）・墓地将“游魊之月夜 赛克斯”以外的１只鱼族怪兽除外可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'牌组检索','此卡特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26533075,'保安球','对手怪兽攻击宣言时可发动。选择１只该攻击怪兽，变更表示形式。被盖牌的此卡因对手的魔法、陷阱卡效果被破坏并送入墓地时，选择场上的１只怪兽破坏。','场上一只怪兽破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26534688,'深海之都 墨瓦腊泥加',replace(replace('此卡名在规则上视为“海”。\r\n①：作为此卡发动时的效果处理，可从牌组挑选1只水属性怪兽放在牌组最上面。\r\n②：1回合1次，以自己场上的1只水属性怪兽为对象可以发动。该怪兽的等级直至回合结束时为止上升1或2。\r\n③：1回合1次，在自己的主要阶段，自己将水属性同步怪兽特殊召唤的情况下可以发动。确认对手的手牌，从其中挑选1张卡直至结束阶段为止以表侧除外。','\r',char(13)),'\n',char(10)),'','','是否从牌组选1只水属性怪兽在牌组最上面放置？','请选择要在牌组最上面放置的卡','请选择要上升等级的怪兽','','','','','','','','','','','');
INSERT INTO texts VALUES(26548709,'蕾祸之矢筈天牛',replace(replace('此卡名以①方法的特殊召唤１回合仅可进行１次，且②效果１回合仅可使用１次。\r\n①：此卡可将自己除外状态的１只昆虫族・植物族・爬虫类族怪兽放回牌组最下面，来从手牌特殊召唤。\r\n②：此卡作为“蕾祸”连接怪兽的连接素材被送至墓地的情况下，以除“蕾祸之矢筈天牛”之外的自己墓地的１只等级４以下的昆虫族・植物族・爬虫类族怪兽为对象可以发动。将该怪兽以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'','特殊召唤昆虫族·植物族·爬虫类族怪兽','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26556950,'编号84 获痛者',replace(replace('等级１１怪兽×２\r\n此卡也可重叠在自己持有２个以上超量素材、阶级８～１０的暗属性超量怪兽上面来超量召唤。①：此卡的守备力上升相当于自己场上超量怪兽的阶级合计×２００的数值。②：只要持有超量素材的此卡存在于怪兽区域，对手每次发动魔法・陷阱卡就给予对手６００伤害。③：１回合１次，去除此卡的１个超量素材可以发动。将对手场上拥有此卡守备力以下守备力的怪兽全部破坏。','\r',char(13)),'\n',char(10)),'请选择8～10阶的暗属超量怪兽','破坏怪兽','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26557451,'抽卡释放',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：对手以对手的效果抽卡时可以发动。将对手所抽的该卡全部确认。其中有怪兽卡的情况下，给予对手相当于其攻击力合计数值的伤害，将确认的卡全部除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26561172,'变异体突异变种',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己场上有“突异变种”卡存在的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：解放此卡，从手牌・牌组将１张“突异变种”卡除外可以发动。根据所除外的卡的种类，将以下１只怪兽从手牌・牌组特殊召唤，自己失去相当于该怪兽原本攻击力数值的LP。\r\n●怪兽：“突异变种・猛兽”\r\n●魔法：“突异变种・迷雾”\r\n●陷阱：“突异变种・武装”','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26563200,'弦魔人 跃跃节奏',replace(replace('等级3怪兽×2\r\n此卡名的①效果1回合仅可使用1次。\r\n①：自己的“魔人”超量怪兽攻击对手怪兽的伤害步骤开始时至伤害计算前为止，去除此卡的1个超量素材可以发动。该攻击怪兽的攻击力直至回合结束时为止变为两倍。','\r',char(13)),'\n',char(10)),'攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26566878,'魔鬼蝎','体内寄宿着恶魔灵魂的巨大蝎子。平时一直储备着实力，因此潜力很高。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26570480,'魔幻甜点・巧克力哔哔',replace(replace('①：１回合１次，此卡以表侧表示存在于场上，且自己场上的“魔幻甜点”怪兽的表示形式被变更时，以场上的１只怪兽为对象可以发动。将该怪兽改成表侧守备表示，该怪兽为“魔幻甜点”怪兽以外的情况下，该怪兽不可攻击，效果无效化。\r\n②：此卡被对手破坏并被送至墓地的情况下发动。将此卡放回牌组。','\r',char(13)),'\n',char(10)),'返回牌组','改变表示形式','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26577155,'龙骑兵团－雷穆斯',replace(replace('此卡名的①②效果1回合仅可各使用1次，要以此卡作为同步素材的情况下，仅可使用于“龙骑兵团”怪兽的同步召唤。\r\n①：从手牌将此卡舍弃可以发动。从牌组将1张“龙之溪谷”加入手牌。\r\n②：自己场上存在“龙骑兵团”怪兽的情况下可以发动。从墓地将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。此回合，自己从额外牌组仅可特殊召唤龙族怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26582143,'剑斗兽 教鞭',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：向对手出示手牌的此卡与手牌的1只“剑斗兽”怪兽可以发动。将该2只特殊召唤。\r\n②：此卡以“剑斗兽”怪兽的效果特殊召唤的情况下可以发动。从牌组将1张“剑斗”魔法・陷阱卡加入手牌。\r\n③：此卡进行过战斗的战斗阶段结束时，将此卡放回牌组可以发动。从牌组将“剑斗兽 教鞭”以外的1只“剑斗兽”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','检索魔陷','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26585784,'K9－EW 特殊解除实验',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从自己的手牌・墓地将1只“K9”怪兽特殊召唤。然后，可从额外牌组将1只“K9”超量怪兽重叠在以此效果特殊召唤的怪兽上面，视为超量召唤特殊召唤。以此效果从额外牌组特殊召唤的怪兽将在下个回合结束阶段被破坏。\r\n②：在自己・对手的结束阶段，将墓地的此卡除外，以自己墓地的1张“K9”速攻魔法卡为对象可以发动。将该卡放置在自己场上。','\r',char(13)),'\n',char(10)),'特殊召唤','放置','是否超量召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26586849,'王宫的牢狱','只要此卡存在于场上，双方玩家不可特殊召唤墓地的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26593852,'A・O・J 灾难兽',replace(replace('协调＋协调以外的怪兽1只以上\r\n①：此卡与暗属性以外的表侧表示怪兽进行战斗的伤害步骤开始时发动。将该怪兽破坏。','\r',char(13)),'\n',char(10)),'暗属性以外怪兽破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26631975,'恐啡肽骇龙・领域','此卡名的卡１回合仅可发动１张。①：在自己・对手的主要阶段，支付一半LP可以发动。从自己的手牌・牌组・场上，将由“恐啡肽骇龙”融合怪兽卡决定的融合素材怪兽送至墓地，从额外牌组将１只该融合怪兽融合召唤。②：自己的LP为２０００以下、对手发动魔法・陷阱・怪兽的效果时，将墓地的此卡除外可以发动。此回合，因对手的效果对自己造成的效果伤害变为０。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26638543,'节拍器侏儒',replace(replace('←4 【灵摆】 4→\r\n①：１回合１次，可以我方或对手灵摆区１张此卡以外的卡片为目标发动。直到回合结束，此卡的灵摆刻度变为与该卡灵摆刻度相同的数值。\r\n【怪兽效果】\r\n①：如果我方灵摆区中有２张卡，且其灵摆刻度相同，则此卡的攻击力和守备力各提升等同于该灵摆刻度×１００的数值，且此卡可以直接攻击。\n②：如果此卡直接攻击并向对手造成了战斗伤害，则发动。破坏双方灵摆区的所有卡片。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26640671,'蜘蛛的领域','１回合１次，可选择我方场上的１只昆虫族怪兽并发动。与被选择怪兽进行了战斗的对手怪兽在战斗阶段结束时变成守备表示，只要此卡存在于场上，不可变更表示形式。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26647858,'英雄光环','可选择场上１只攻击力是１５００或以下的战士族怪兽并发动此卡。此卡被视为装备卡，装备于被选择之攻击力是１５００或以下的战士族怪兽。攻击力是１９００或以上的对手怪兽不可攻击装备怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26655293,'麦格农枪弹龙','此卡名的①②效果1回合仅可各使用1次。①：以场上的此卡为对象的连接怪兽的效果发动时可以发动。将此卡破坏。然后，挑选1只场上的怪兽送至墓地。②：场上的此卡因战斗・效果被破坏并被送至墓地的回合的结束阶段可以发动。从牌组将1只“麦格农枪弹龙”以外的“枪弹”怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26669055,'静寂之圣者','此卡通过战斗破坏怪兽的场合，对手玩家在下个回合中不可发动魔法卡。','发动限制','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26674724,'光枪龙的影灵衣',replace(replace('以“影灵衣”仪式魔法卡降临\r\n此卡仅可以仪式召唤方式特殊召唤，且仪式召唤仅可使用“光枪龙的影灵衣”以外的怪兽。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：从手牌将此卡舍弃可以发动。从牌组将“光枪龙的影灵衣”以外的1只“影灵衣”怪兽加入手牌。\r\n②：以场上最多2只被从额外牌组特殊召唤的怪兽为对象可以发动。将该怪兽放回牌组。','\r',char(13)),'\n',char(10)),'牌组检索','回到牌组','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26684111,'天空的圣水',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从牌组，将1张“天空的圣域”发动，或将1只记载有“天空的圣域”卡名的怪兽加入手牌。然后，自己或对手的、场上或墓地存在“天空的圣域”的情况下，自己可恢复自己场上的“许珀里翁”怪兽及“代行者”怪兽的数量×500的LP。\r\n②：记载有“天空的圣域”卡名的自己的怪兽将被战斗破坏的情况下，作为代替可将墓地的此卡除外。','\r',char(13)),'\n',char(10)),'把「天空的圣域」发动','把怪兽加入手牌','是否回复基本分？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26692769,'魅影骑士团锈蚀月刃斧',replace(replace('暗属性怪兽2只以上\r\n此卡不可作为连接素材。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己的主要阶段可以发动。从牌组将1只“魅影骑士团”怪兽送至墓地。然后，从牌组将1张“魅影”魔法・陷阱卡放置在自己的魔法与陷阱区域。\r\n②：此卡存在于怪兽区域的状态下，有暗属性超量怪兽被特殊召唤至此卡连接端的情况下，以场上的1张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26700718,'蛇眼追逐剧',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：从自己的手牌・牌组・墓地将１只“迪亚贝尔斯塔”怪兽视为永续魔法卡，以表侧表示放在原本持有者的魔法与陷阱区域。\r\n②：在自己・对手的结束阶段，将墓地的此卡除外，以自己场上的１张视为永续魔法卡的怪兽卡为对象可以发动。将该卡特殊召唤。','\r',char(13)),'\n',char(10)),'当作永续魔法卡放置','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26701483,'卡牌排除师','１回合１次，可选择对手墓地的１张卡牌并发动。将被选择卡牌从游戏中除外。','对手墓地存在的1张卡从游戏中除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26704411,'魔轰神兽寇克特','此卡因战斗破坏对手怪兽并送入墓地时，可从手牌舍弃１只冠有“魔轰神”之名的怪兽并发动。从牌组抽取１张卡牌。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26708437,'超量重生','①：以自己墓地的１只超量怪兽为对象可以发动。将该怪兽特殊召唤，将此卡重叠在下方作为超量素材。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26722601,'侵邪蚀的守卫','只要此卡以表侧表示存在于场上，冠有“侵邪蚀”之名的怪兽以表侧表示上级召唤成功的回合，仅限１次我方可除通常召唤以外再次通常召唤怪兽。','使用「侵邪蚀的门番」的效果召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26725158,'驱除魔鬼','破坏场上所有恶魔族怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26732909,'魔导教士 希斯缇','我方发动冠有“魔导书”之名的魔法卡的我方回合的结束阶段时，可将场上的此卡从游戏中除外并发动。从牌组将１只等级５或以上的光属性或暗属性魔法师族怪兽，以及１张冠有“魔导书”之名的魔法卡加入手牌。“魔导教士 希斯缇”的效果１回合只可使用１次。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26746975,'暗之守护神－黑暗守护者',replace(replace('此卡名在规则上也视为“门之守护者”卡。\r\n此卡不可通常召唤，仅可以“黑暗元素”的效果及以下方法特殊召唤。\r\n●可将自己的手牌・场上（表侧表示）・墓地・除外状态的“雷魔神－桑迦”、“风魔神－休迦”、“水魔神－苏迦”各１张放回牌组，从手牌・墓地特殊召唤。\r\n①：此卡不会因战斗被破坏。\r\n②：以“黑暗元素”的效果特殊召唤的此卡，不受其他怪兽及对手发动的魔法卡的效果影响。','\r',char(13)),'\n',char(10)),'「黑暗元素」的效果特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26773909,'才呼粉身',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：在自己・对手的战斗阶段，以自己场上的１只表侧表示怪兽为对象可以发动。自己失去相当于该怪兽攻击力数值的LP，该怪兽的攻击力直至回合结束时为止变为两倍。发动此卡的回合中，对象怪兽不可直接攻击。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26775203,'黑羽－热风的基布利',replace(replace('①：对手怪兽的直接攻击宣言时可发动。从手牌特殊召唤此卡。\r\n②：１回合１次，可在我方主要阶段发动。直至回合结束时，此卡的原本攻击力、守备力互换。','\r',char(13)),'\n',char(10)),'特殊召唤','原本的攻击力·守备力交换','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26781870,'老千御法度',replace(replace('①：１回合１次，对手从手牌特殊召唤了怪兽时可发动。将对手场上所有从手牌特殊召唤而来的怪兽返回至持有者手牌。\r\n②：场上不存在有“花札卫”同步怪兽的场合，此卡被送入墓地。','\r',char(13)),'\n',char(10)),'发动但不使用效果','发动并使用①效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26822796,'帝王的冻志','①：自己额外牌组不存在卡的情况下，以自己场上的1只上级召唤的表侧表示怪兽为对象可以发动。该怪兽效果无效，不受其他卡的效果影响。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26834022,'缴械','魔法卡发动时可发动。从手牌将１张冠有“剑斗兽”之名的卡牌返回至牌组，使该发动无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26841274,'D－结合','以此卡的效果融合召唤的情况下，仅可以“命运-英雄”怪兽作为融合素材。①：从自己场上将由融合怪兽卡决定的融合素材怪兽送至墓地，从额外牌组将1只该融合怪兽融合召唤。以此效果特殊召唤的怪兽此回合，不会因战斗・效果被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26842483,'正义使者','１回合１次，对手场上被特殊召唤怪兽的效果发动时可发动此卡。使该发动无效。','效果无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26845680,'自鸣天琴・唤魂','此卡名的卡1回合仅可发动1张。①：从手牌及自己场上的表侧表示怪兽中，将1只“自鸣天琴”怪兽或“星遗物”怪兽送至墓地可以发动。自己从牌组抽2张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26847978,'铁兽战线 谎花之费丽吉特',replace(replace('兽族・兽战士族・鸟兽族怪兽２只\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：在自己的主要阶段可以发动。从手牌将１只等级４以下的兽族・兽战士族・鸟兽族怪兽特殊召唤。此效果发动后，直至回合结束时为止，自己仅可将兽族・兽战士族・鸟兽族怪兽作为连接素材。\r\n②：此卡被送至墓地的情况下可以发动。自己抽１张。然后，挑选１张自己的手牌放回牌组最下面。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26857786,'咒炎王 爆焰诅咒',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：自己场上存在恶魔族协调的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：此卡特殊召唤的情况下，以对手场上的1只表侧表示怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止下降600。\r\n③：此卡因战斗・效果被破坏并被送至墓地的情况下，以对手场上的1只表侧表示怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止下降400。','\r',char(13)),'\n',char(10)),'特殊召唤','攻击力下降600','攻击力下降400','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26864586,'共振装置','可选择我方场上２只同种族、属性的怪兽并发动。直至回合结束时，被选择的１只怪兽的等级变成与另１只怪兽相同等级。','请选择等级要变换的怪兽','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26866984,'圣三天阶',replace(replace('此卡名的效果1回合仅可使用1次。①：此卡存在于手牌・墓地的情况下，在自己・对手的主要阶段，解放自己场上的最多3只天使族怪兽可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡离开场上的情况下，将其除外。根据为发动此效果解放的怪兽数量进而可分别适用以下效果。\r\n●2只以上：挑选对手场上的1张卡破坏。\r\n●3只：自己从牌组抽2张。','\r',char(13)),'\n',char(10)),'','是否选对手场上1张卡破坏？','是否从牌组抽2张？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26873574,'混沌代达罗斯','此卡不可通常召唤。将自己墓地中光属性与暗属性怪兽各１只除外的情况下可以特殊召唤。此卡名的②效果１回合仅可使用１次。①：只要场地魔法卡以表侧表示存在，自己场上的光・暗属性怪兽不会成为对手效果的对象。②：场地魔法卡以表侧表示存在的情况下，最多依其数量以场上的卡为对象可以发动。将该卡除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26885836,'英豪挑战者 战锤','此卡因战斗破坏对手怪兽并将其送入墓地时，破坏的怪兽可被视为装备卡仅限１只装备此卡。此卡的攻击力上升相当于以此效果装备的怪兽的攻击力数值。','装备','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26889158,'转生炎兽 羚羊',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：“转生炎兽 羚羊”以外的“转生炎兽”怪兽被送至自己墓地的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从牌组将“转生炎兽 羚羊”以外的１张“转生炎兽”卡送至墓地。','\r',char(13)),'\n',char(10)),'从手牌特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26902560,'融合贤者','将我方牌组中的１张“融合”魔法卡加入到手牌中。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26905245,'金属反射史莱姆','①：此卡发动后，变为效果怪兽（水族・水・星10・攻0/守3000），以守备表示特殊召唤至怪兽区域。此卡也视为陷阱卡。②：以此卡的效果被特殊召唤的此卡不可攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26913989,'幽魂拷问魔像',replace(replace('自己１回合仅可特殊召唤１次“幽魂拷问魔像”。\r\n①：将手牌的１只“尤贝尔”怪兽出示给对手可以发动。从手牌将此卡特殊召唤至对手场上。然后，可将所出示的怪兽特殊召唤至自己场上。\r\n②：１回合１次，此卡与“尤贝尔”怪兽进行战斗的伤害计算时发动。对手恢复３０００LP。\r\n③：此卡存在于墓地的状态下，自己将“尤贝尔”特殊召唤的情况下可以发动。将此卡特殊召唤至对手场上。','\r',char(13)),'\n',char(10)),'往对手场上特殊召唤','回复基本分','往对手场上特殊召唤','是否把给人观看的怪兽特殊召唤？','','','','','','','','','','','','');
INSERT INTO texts VALUES(26914168,'暗黑奥尼斯特','①：１回合１次，在自己的主要阶段可以发动。将场上表侧表示的此卡放回持有者的手牌。②：自己的暗属性怪兽和对手怪兽进行战斗的伤害步骤开始时到伤害计算前为止，从手牌将此卡送至墓地可以发动。该对手怪兽的攻击力直至回合结束时为止，下降相当于其攻击力的数值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26920296,'幻梦境',replace(replace('“幻梦境”１回合只可发动１张。\r\n①：根据场上怪兽种类获得以下效果。\r\n●融合：１回合１次，我方手牌、场上的怪兽因效果被送入墓地的场合可发动。我方从牌组抽取１张卡牌。\r\n●同步：召唤、特殊召唤怪兽成功时，我方可发动此效果。该怪兽的等级上升１级。\r\n●超量：在我方结束阶段发动。破坏场上等级最高的怪兽。','\r',char(13)),'\n',char(10)),'自己从牌组抽1张卡','召唤·特殊召唤成功的怪兽的等级上升1星','场上的等级最高的怪兽破坏','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26931058,'同盟阵型',replace(replace('从以下效果中选择１个进行发动：\r\n●选择我方场上１只表侧表示的联合怪兽，装备至我方场上表侧表示的可装备的怪兽上。\r\n●解除我方场上１只视为装备卡的联合怪兽的装备状态，并将其以表侧攻击表示特殊召唤至我方场上。','\r',char(13)),'\n',char(10)),'同盟装备','装备解除','请选择一只同盟怪兽','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26932788,'标枪甲虫','由“标枪甲虫的契约”召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26949946,'幻兽机雅格鲁斯兰枪蛇',replace(replace('“幻兽机”协调＋协调以外的“幻兽机”怪兽１只或以上\r\n①：此卡同步召唤成功时，可释放我方场上任意数量的“幻兽机衍生物”并发动。随机挑选对手手牌并舍弃，其数量相当于释放数量。\r\n②：只要此卡存在于怪兽区，我方场上除此卡以外的“幻兽机”怪兽不会因战斗、效果被破坏。\r\n③：此卡因对手被破坏的场合可发动。从牌组挑选１张速攻魔法卡盖牌至我方的魔法与陷阱区域。','\r',char(13)),'\n',char(10)),'手牌破坏','牌组检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26956670,'化石岩的解放','选择１只我方从游戏中被除外的岩石族怪兽并特殊召唤。此卡从场上离开时，破坏该怪兽。该怪兽被破坏时，破坏此卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26964762,'命运－英雄 暗黑天使',replace(replace('①：自己墓地的“命运－英雄”怪兽为3只以上的情况下，从手牌将此卡舍弃，以自己墓地的1只“命运－英雄”怪兽为对象可以发动。将该怪兽以守备表示特殊召唤至对手场上。\r\n②：只要此卡存在于怪兽区域，自己发动的魔法卡的效果将无效化并被破坏。\r\n③：在自己的准备阶段，从自己墓地将此卡和1只“命运－英雄”怪兽除外可以发动。双方各自从自身牌组挑选1张通常魔法卡放在牌组最上面。','\r',char(13)),'\n',char(10)),'特殊召唤','在牌组最上面放置','请选择要放置到牌组最上面的卡','请选择要放置到牌组最上面的卡','','','','','','','','','','','','');
INSERT INTO texts VALUES(26973555,'翼日编号0 未来龙皇霍普',replace(replace('“编号”怪兽以外的相同阶级的超量怪兽×3\r\n规则上，此卡的阶级视为1，此卡名也视为“未来皇霍普”卡。\r\n此卡也可重叠在自己场上的“翼日编号0 未来皇霍普”上面来超量召唤。\r\n①：此卡不会因战斗・效果被破坏。\r\n②：1回合1次，对手发动怪兽的效果时，去除此卡的1个超量素材可以发动。将该发动无效。以此效果将场上的怪兽效果的发动无效的情况下，进而获得其控制权。','\r',char(13)),'\n',char(10)),'是否在「未来编号0 翼日编号0 未来」上面重叠来超量召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26976414,'海皇的长矛兵','效忠于据说是海底统治者的海皇的长矛兵。从幽黑深海袭来的连续长矛攻击，令深海鱼们倍感恐惧。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26984177,'王墓之石壁',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：此卡只要存在于场地区域，卡名视为“王之棺”。\r\n②：在自己的主要阶段可以发动。从牌组将１只“荷鲁斯”怪兽加入手牌。然后，挑选自己的１张手牌放回牌组最下面。\r\n③：自己发动“荷鲁斯之黑炎神”的效果的情况下可以发动。自己抽１张。','\r',char(13)),'\n',char(10)),'检索','抽牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26988374,'魔键凭神－阿斯塔尔特',replace(replace('等级８怪兽×２\r\n①：１回合１次，自己的通常怪兽或“魔键”怪兽战斗破坏对手怪兽时，去除此卡的１个超量素材可以发动。给予对手相当于该被破坏的怪兽的原本攻击力数值的伤害。\r\n②：在对手的主要阶段１次，以对手场上１只属性与自己的场上・墓地的任一通常怪兽或“魔键”怪兽相同的怪兽为对象可以发动。去除此卡的１个超量素材，将对象怪兽除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(26993374,'X－军刀 乌鲁兹','①：此卡战斗破坏对手怪兽并将其送至墓地时，解放此卡可以发动。将该破坏的怪兽放在牌组最上面。','返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27004302,'宝石犰狳','①：此卡召唤时可以发动。从牌组将1只“宝石骑士”怪兽加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27012717,'猛虎',replace(replace('①：只要此卡存在于怪兽区域，场上此卡以外的怪兽的攻击力下降５００。\r\n②：１回合１次，在自己的主要阶段可以发动。将场上攻击力低于此卡的怪兽全部破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27012990,'海晶少女瀑布','自己场上有连接3以上的“海晶少女”怪兽存在的情况下，此卡也可从手牌发动。①：将自己场上任意数量的“海晶少女”连接怪兽直至下一次自己的准备阶段为止除外，以场上的1只表侧表示怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止，上升为发动此卡除外的连接怪兽的连接标记合计×300的数值。','适用「海晶少女瀑布」的效果来发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27015862,'韦陀・迦罗达',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：场上的卡因效果被破坏的情况下，场上如果存在“维萨思・史塔弗罗斯特”则可以发动。从手牌将此卡特殊召唤。然后，可从自己的牌组・墓地将１张“新世坏界”加入手牌。\r\n②：此卡以外的自己的怪兽因效果被破坏的情况下，以对手场上的１只怪兽为对象可以发动。将该怪兽破坏，直至回合结束时为止，此卡的攻击力上升相当于该怪兽原本攻击力的数值。','\r',char(13)),'\n',char(10)),'此卡从手牌特殊召唤','对手怪兽破坏','是否把「新世坏界」加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27024795,'极星灵 阿尔维斯',replace(replace('此卡名的②效果在决斗中仅可使用１次。\r\n①：仅此卡因“极星”连接怪兽的效果被除外的情况下可以发动。为使等级合计为１０，从自己场上将１只、从牌组将２只“极星”怪兽送至墓地。然后，从额外牌组将１只“极神”怪兽特殊召唤。\r\n②：自己的“极神”怪兽被对手以战斗以外的方法送至墓地的情况下，将墓地的此卡除外可以发动。将自己墓地没有同名卡的１只“极神”怪兽从额外牌组特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27036706,'圣夜骑士团・圣空',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡存在于手牌中的情况下，将“圣夜骑士团・西耶勒”以外的自己场上的１只“圣夜骑士团”怪兽或龙族・光属性・等级７怪兽放回持有者的手牌可以发动。将此卡特殊召唤。\r\n②：自己场上不存在怪兽的情况下，将墓地的此卡除外可以发动。从手牌将１只龙族・光属性・等级７怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27053506,'内置式机枪','①：给予对手对手的手牌・场上的卡的数量×２００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27054370,'焰翼天马','挥动着艳丽的鲜红翅膀，翱翔于天际的天马。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27062594,'命运之扉','①：对手怪兽的直接攻击宣言时可以发动此卡。将该攻击无效。然后，此卡变为效果怪兽（恶魔族・光・星１・攻／守０），特殊召唤至怪兽区域。此卡也视为陷阱卡。②：此卡是以此卡的效果被特殊召唤的情况下，在自己准备阶段从自己的墓地将任意数量的“希望皇霍普”怪兽除外可以发动（同名卡最多１张）。给予对手相当于除外数量×５００的数值的伤害，此卡的攻击力上升相当于该伤害的数值。','特殊召唤','效果伤害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27068117,'叠放再生','①：以场上的１只超量怪兽为对象可以发动。将此卡重叠在该怪兽下方作为超量素材。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27069566,'电脑堺凤－凰凰',replace(replace('等级６怪兽×２只以上\r\n此卡名的②效果１回合仅可使用１次。①：１回合１次，去除此卡的２个超量素材，以对手场上１张表侧表示卡和自己或对手墓地的１张卡为对象可以发动。将该卡除外。②：超量召唤的此卡因对手怪兽的攻击或对手的效果被破坏的情况下可以发动。从牌组将２只种族・属性相同的“电脑堺”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'除外','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27094595,'招手的墓地','给予死者更为强大的力量，引诱生者步向死亡的墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27096833,'枪管上膛戒放龙',replace(replace('效果怪兽3只以上\r\n自己1回合仅可特殊召唤1次“枪管上膛戒放龙”。\r\n①：1回合1次，在自己・对手的战斗阶段可以发动（应对此发动，对手不可发动卡的效果）。将对手场上的1只怪兽放在此卡连接端并获得其控制权。\r\n②：在自己・对手回合中，此卡存在于墓地的情况下，以自己场上的1只怪兽为对象可以发动（同一连锁上最多1次）。将该怪兽破坏，将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'得到控制权','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27096834,'枪管上膛戒放龙',replace(replace('效果怪兽3只以上\r\n自己1回合仅可特殊召唤1次“枪管上膛戒放龙”。\r\n①：1回合1次，在自己・对手的战斗阶段可以发动（应对此发动，对手不可发动卡的效果）。将对手场上的1只怪兽放在此卡连接端并获得其控制权。\r\n②：在自己・对手回合中，此卡存在于墓地的情况下，以自己场上的1只怪兽为对象可以发动（同一连锁上最多1次）。将该怪兽破坏，将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'得到控制权','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27103517,'邪神官契伦沙巴',replace(replace('“邪神官契伦沙巴”的②效果１回合只可使用１次。\r\n①：我方手牌是５张以上的场合，此卡可无须解放进行召唤。\r\n②：此卡因战斗被破坏并送入墓地时可发动。以守备表示从墓地特殊召唤此卡。以此效果特殊召唤而来的此卡被视为协调。','\r',char(13)),'\n',char(10)),'不用解放作召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27104921,'命运的囚徒',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：连接４怪兽被连接召唤的情况下可以发动１次。在此卡上放１个计数物（最多３个）。然后，可根据此卡的计数物数量适用以下效果。\r\n●１个：宣言１个卡名。此回合，原本卡名与所宣言卡相同的卡的效果无效化。\r\n●２个：从自己的墓地挑选１只等级４以下的怪兽特殊召唤。\r\n●３个：将此卡送至墓地，从额外牌组将１只连接４怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'是否宣言卡名无效化？','是否从墓地特殊召唤？','是否从额外牌组特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27107590,'时械巫女',replace(replace('①：自己场上不存在怪兽的情况下，此卡可从手牌中特殊召唤。\r\n②：上级召唤“时械神”怪兽的情况下，此卡可作为２只解放。\r\n③：解放此卡可以发动。从牌组将１只攻击力０的“时械神”怪兽加入手牌。\r\n④：将墓地的此卡除外可以发动。从牌组将１只攻击力０的“时械神”怪兽无视召唤条件特殊召唤。发动此效果的回合中，自己不可以此效果以外的方法将怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27118421,'四天之龙 凶饿猛毒结合龙',replace(replace('场上的暗属性怪兽×2\r\n此卡名在规则上也视为“捕食植物”卡。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡特殊召唤的情况下，以场上的1只其他的表侧表示怪兽为对象可以发动。该怪兽的攻击力变为0，效果无效化，变为暗属性。\r\n②：对手发动效果时可以发动。将包含此卡在内的、自己・对手场上的暗属性怪兽作为融合素材，将1只暗属性的融合怪兽融合召唤。','\r',char(13)),'\n',char(10)),'效果无效','融合召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27118422,'四天之龙 凶饿猛毒结合龙',replace(replace('场上的暗属性怪兽×2\r\n此卡名在规则上也视为“捕食植物”卡。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡特殊召唤的情况下，以场上的1只其他的表侧表示怪兽为对象可以发动。该怪兽的攻击力变为0，效果无效化，变为暗属性。\r\n②：对手发动效果时可以发动。将包含此卡在内的、自己・对手场上的暗属性怪兽作为融合素材，将1只暗属性的融合怪兽融合召唤。','\r',char(13)),'\n',char(10)),'效果无效','融合召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27125110,'千眼邪教神','操纵人心的邪神。千只邪眼洞察人类的负面之心，并使其不断膨胀。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27126980,'宝石骑士・苍玉石','可凭借苍玉石的力量随意操纵水，轻柔地化解敌人的攻击。其静谧的守护似乎深得伙伴信任。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27132350,'火焰巫师','反转：随机选择我方２张手牌从游戏中除外。给予对手生命８００点伤害。','LP伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27132400,'幻变骚灵・恶意无线提供者',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：用抽牌以外的方法将此卡加入手牌的情况下可以发动。将此卡特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下，以自己墓地“幻变骚灵・恶意无线提供者”以外的１只“幻变骚灵”怪兽为对象可以发动。将该怪兽以守备表示形式特殊召唤。此回合，以此效果特殊召唤的怪兽的效果不可发动。','\r',char(13)),'\n',char(10)),'','','「幻变骚灵・恶意无线提供者」效果适用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27134209,'树冠之甲帝 贝桠蛄朗姆','此卡不可通常召唤。仅可在将自己手牌・墓地的３只昆虫族・植物族怪兽除外的情况下，从手牌・墓地特殊召唤。自己１回合仅可特殊召唤１次“树冠之甲帝 贝桠蛄朗姆”。①：只要此卡存在于怪兽区域，应对自己的魔法・陷阱卡效果的发动，对手不可发动怪兽的效果。②：１回合１次，在自己的主要阶段可以发动。将昆虫族・植物族怪兽以外的场上的表侧表示怪兽全部破坏。此回合，此卡不可直接攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27134689,'OZ之主','“巨大考拉”＋“死亡袋鼠”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27143874,'缝制恐龙',replace(replace('①：此卡不会因战斗被破坏。\r\n②：此卡在被选择为攻击对象的情况下发动。此卡的攻击力・守备力上升１０００。\r\n③：在此卡攻击的伤害计算后发动。以此卡的②效果上升的数值变回０。','\r',char(13)),'\n',char(10)),'是否发动「缝制恐龙」的效果？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27157727,'隐匿城 坚实堡垒',replace(replace('①：此卡发动后，变为拥有以下效果的效果怪兽（机械族・地・星４・攻０／守２０００），特殊召唤至怪兽区域（也视为陷阱卡）。\r\n●此卡的攻击力上升相当于自己场上的“光之黄金柜”及记载有该卡名的怪兽数量×１０００的数值。\r\n●１回合１次，自己场上存在“光之黄金柜”的情况下，对手怪兽攻击宣言时可以发动。将该怪兽破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27157996,'机块转换',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：将自己主要怪兽区域的“机块”连接怪兽全部除外。然后，可挑选自己被除外的“机块”连接怪兽特殊召唤，数量最多为以此效果除外的怪兽数量。\r\n②：此卡存在于墓地的情况下，在自己的主要阶段，从自己的墓地将其他１张“机块”魔法・陷阱卡除外可以发动。将此卡加入手牌。此效果在此卡被送至墓地的回合不可发动。','\r',char(13)),'\n',char(10)),'','','是否选怪兽特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27170599,'不给糖就搞鬼计','此卡名的卡１回合仅可发动１张。①：自己场上存在“鬼计”场地魔法卡或“鬼计”连接怪兽的情况下，以对手场上的１只表侧表示怪兽为对象可以发动。对手可支付２０００LP。该情况下，此卡的效果变为“发动后此卡不会送往墓地，而是就此放置”。不支付的情况下，此回合，该表侧表示怪兽不可攻击，效果无效化，将在结束阶段变为里侧守备表示。','是否支付基本分？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27174286,'来自异次元的归还','可支付LP的一半数值发动。尽可能特殊召唤从游戏中被除外的我方怪兽。以此效果特殊召唤而来的怪兽将在结束阶段时从游戏中被除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27178262,'六武众之理','①：将自己场上的１只表侧表示“六武众”怪兽送至墓地，以自己或对手墓地的１只“六武众”怪兽为对象可以发动。将该怪兽特殊召唤至自己场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27182739,'斩机西格玛','此卡名的①效果1回合仅可使用1次。①：此卡存在于手牌・墓地，且额外怪兽区域没有自己怪兽存在的情况下可以发动。将此卡特殊召唤。在此效果特殊召唤的此卡离开场上的情况下被除外。此效果发动后，直至回合结束时为止自己从额外牌组仅可特殊召唤电子界族怪兽。②：将自己场上的此卡用作“斩机”同步怪兽的同步素材的情况下，此卡可视为协调以外的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27184601,'神艺狱徒 迪亚克特罗斯',replace(replace('“无垢者 墨迪乌斯”＋“神艺”怪兽\r\n此卡名的①②③效果1回合仅可各使用1次。\r\n①：以场上的1只怪兽为对象可以发动。变更该怪兽的表示形式。\r\n②：自己场上的怪兽的种族为3种以上，且对手在场上发动魔法・陷阱・怪兽的效果时可以发动。将该发动无效并破坏。\r\n③：融合召唤的此卡被破坏的情况下可以发动。将自己手牌・牌组・除外状态的1只“无垢者 墨迪乌斯”特殊召唤。','\r',char(13)),'\n',char(10)),'改变表示形式','无效','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27189308,'咕咕雏鸟','反转：可从牌组特殊召唤１只等级５或以上的协调。','是否要从牌组把1只5星以上的协调特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27191436,'爆裂归还','我方场上存在有“元素－英雄 爆炎女郎”的场合可发动。将场上除“元素－英雄 爆炎女郎”以外的冠有“元素－英雄”之名的怪兽全部返回至持有者手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27196937,'星尘的残光','①：可以１只我方墓地的“星尘”怪兽为对象发动。特殊召唤该怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27198001,'九尾狐','此卡名的①效果1回合仅可使用1次。①：此卡在手牌・墓地存在的情况下，解放自己场上的2只怪兽可以发动。将此卡特殊召唤。②：从墓地特殊召唤的此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予战斗伤害。③：此卡因战斗・效果被破坏并被送至墓地的情况下可以发动。将2只“狐衍生物”（不死族・炎・星2・攻/守500）特殊召唤至自己场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27198002,'狐衍生物','由“九尾狐”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27204311,'原始生命态 尼比鲁',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：在对手召唤・特殊召唤过5只以上怪兽的、自己・对手回合的主要阶段可以发动。将自己・对手场上的表侧表示怪兽尽可能地解放，从手牌将此卡特殊召唤。然后，将1只“原始生命态衍生物”（岩石族・光・星11・攻/守？）特殊召唤至对手场上。此衍生物的攻击力・守备力，变为以此效果解放的怪兽的原本攻击力・守备力各自的合计数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27204312,'原始生命态衍生物','由“原始生命态 尼比鲁”的效果特殊召唤而来。此衍生物的攻击力、守备力将为特殊召唤此衍生物时所献祭怪兽的原攻击力、守备力各自合计的数值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27204313,'原始生命态 尼比鲁',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：在对手召唤・特殊召唤过5只以上怪兽的、自己・对手回合的主要阶段可以发动。将自己・对手场上的表侧表示怪兽尽可能地解放，从手牌将此卡特殊召唤。然后，将1只“原始生命态衍生物”（岩石族・光・星11・攻/守？）特殊召唤至对手场上。此衍生物的攻击力・守备力，变为以此效果解放的怪兽的原本攻击力・守备力各自的合计数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27204314,'原始生命态 尼比鲁',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：在对手召唤・特殊召唤过5只以上怪兽的、自己・对手回合的主要阶段可以发动。将自己・对手场上的表侧表示怪兽尽可能地解放，从手牌将此卡特殊召唤。然后，将1只“原始生命态衍生物”（岩石族・光・星11・攻/守？）特殊召唤至对手场上。此衍生物的攻击力・守备力，变为以此效果解放的怪兽的原本攻击力・守备力各自的合计数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27207573,'侵略的手段','可从牌组将１只冠有“侵邪蚀”之名的怪兽送入墓地，并选择我方场上的１只冠有“侵入魔鬼”之名的怪兽发动。直至回合结束时，被选择怪兽的攻击力上升８００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27217742,'雷电哥哥','①：此卡召唤时可以发动。从牌组将“雷电哥哥”以外的1只雷族・光属性・等级4怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27240101,'耳边风鸟',replace(replace('等级１怪兽×２\r\n①：此卡只要存在于怪兽区域，不受其他卡的效果影响。\r\n②：在每个自己・对手回合中１次，去除此卡的２个超量素材可以发动。此回合，此卡不会因战斗被破坏，因此卡的战斗对自己造成的战斗伤害变为０。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27243130,'禁忌的圣枪','①：以场上的1只表侧表示怪兽为对象可以发动。该怪兽直至回合结束时为止，攻击力下降800，不受其他的魔法・陷阱卡的效果影响。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27260347,'蛇眼大炎魔・迪亚贝尔斯塔',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡与对手怪兽进行战斗的攻击宣言时可以发动。将该对手怪兽和此卡各自视为永续魔法卡，以表侧表示放在原本持有者的魔法与陷阱区域。\r\n②：此卡视为永续魔法卡的情况下，以自己墓地“蛇眼大炎魔・迪亚贝尔斯塔”以外的１只炎属性怪兽为对象可以发动。将该怪兽视为永续魔法卡，以表侧表示放在原本持有者的魔法与陷阱区域，将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'放置到魔法与陷阱区域','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27268998,'钢铁戴比鲁佐亚X',replace(replace('此卡不可通常召唤，通过解放等级５以上恶魔族怪兽来发动的“钢铁化・强化反射装甲”的效果可以特殊召唤。\r\n此卡名的①效果１回合仅可使用１次。\r\n①：向对手出示手牌的此卡可以发动。从牌组将１张“钢铁化”陷阱卡放置在自己场上，将此卡放回牌组。\r\n②：１回合最多２次，对手发动魔法・怪兽的效果时，以对手场上的１只表侧表示怪兽为对象可以发动。将该怪兽破坏。','\r',char(13)),'\n',char(10)),'放置「钢铁化」陷阱卡','破坏效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27275398,'黄金荣耀－全速前进',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：以自己场上的１只“黄金荣耀”怪兽为对象可以发动。该怪兽直至回合结束时为止，攻击力上升５００，不会因战斗・效果被破坏，不可发动效果。\r\n②：此回合，自己场上表侧表示的“黄金荣耀”怪兽因战斗・效果被破坏的情况下，在结束阶段可以发动。将墓地的此卡放置在自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27279764,'隐藏的机壳杀手',replace(replace('此卡不可特殊召唤，仅在解放自己场上的３只“机壳”怪兽的情况下可以通常召唤。\r\n①：通常召唤的此卡不受魔法・陷阱卡的效果影响，也不受原本等级或阶级低于此卡等级的怪兽发动的效果影响。\r\n②：只要此卡存在于怪兽区域，被特殊召唤的怪兽的攻击力・守备力下降５００。\r\n③：１回合１次，在自己的主要阶段可以发动。对手必须将自身手牌・场上的１只怪兽送至墓地。','\r',char(13)),'\n',char(10)),'把3只「机壳」怪兽解放','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27285068,'开辟预幻视',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：自己场上存在“无垢者 墨迪乌斯”的情况下可以发动。从牌组挑选1只攻击力300/守备力200的怪兽，加入手牌或特殊召唤。\r\n②：在自己的主要阶段将墓地的此卡除外，以自己场上的1只表侧表示怪兽为对象可以发动。此回合，将该怪兽视为协调。','\r',char(13)),'\n',char(10)),'从牌组选怪兽','变成协调','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27288416,'悠悠','完全不知在想什么的天使中的异类。一旦生气，后果将非常恐怖。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27308231,'K9－LC 拘束解除',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：以自己场上的1只“K9”超量怪兽或阶级5的超量怪兽为对象可以发动。从额外牌组将卡名与该自己的怪兽不同的1只“K9”超量怪兽重叠在对象怪兽上面，视为超量召唤特殊召唤。\r\n②：自己的“K9”怪兽进行过战斗的回合的战斗阶段结束时可以发动。将墓地的此卡放置在自己场上。','\r',char(13)),'\n',char(10)),'超量','放置','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27315304,'喷霞虫',replace(replace('协调＋协调以外的怪兽２只或以上\r\n①：此卡同步召唤成功的场合，可以对手场上最多３张卡牌为对象发动。将该对手的卡牌返回至持有者手牌。','\r',char(13)),'\n',char(10)),'返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27324313,'电力小子','雷电攻击出奇地威力惊人。低估了它可是会触电的哦。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27331568,'庄严的机械天使','此卡名的卡１回合仅可发动１张。①：解放自己手牌・场上１只“电子天使”仪式怪兽，以自己场上的１只天使族・光属性怪兽为对象可以发动。对象怪兽的攻击力・守备力直至回合结束时为止，上升相当于解放的怪兽的等级×２００的数值。此回合，对象怪兽与被从额外牌组特殊召唤的对手怪兽进行战斗的情况下，仅在战斗阶段期间该对手怪兽的效果无效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27337596,'圣刻龙王－亚图姆斯',replace(replace('龙族等级６怪兽×２\r\n①：１回合１次，去除此卡的１个超量素材可以发动。从牌组挑选１只龙族怪兽，将其攻击力・守备力改成０并特殊召唤。发动此效果的回合中，此卡不可攻击。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27340877,'DNA定期体检','可选择我方场上的１只里侧表示的怪兽发动。对手宣言２个怪兽属性。翻开被选择的怪兽进行确认，其属性为被宣言属性的场合，对手从牌组抽取２张卡牌。否则我方从牌组抽取２张卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27345070,'对击斗魂 续关',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：支付５００LP，以自己墓地的１只“对击斗魂”怪兽为对象可以发动。将该怪兽加入手牌，或以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27346636,'剑斗兽 赫拉克雷诺斯',replace(replace('“剑斗兽 炎索”＋“剑斗兽”怪兽×２\r\n此卡从额外牌组仅可在将自己场上的上述卡放回牌组・额外牌组的情况下特殊召唤。\r\n①：魔法・陷阱卡发动时，舍弃１张手牌可以发动。此卡在场上以表侧表示存在的情况下，将该发动无效并破坏。','\r',char(13)),'\n',char(10)),'无效发动并破坏','特殊召唤','请选择一张「剑斗兽 炎索」','请选择两张名字带有「剑斗兽」的怪兽','','','','','','','','','','','','');
INSERT INTO texts VALUES(27352108,'乔巴姆装甲龙',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：对手怪兽的直接攻击宣言时可以发动。将此卡从手牌以攻击表示特殊召唤。此回合，以此效果特殊召唤的此卡不会因战斗被破坏，因此卡的战斗造成的对自己的战斗伤害变为一半。\r\n②：此卡作为连接素材被送至墓地的情况下，以自己墓地此卡以外的１只暗属性怪兽为对象可以发动。将该怪兽加入手牌。对手可挑选自身墓地的１只怪兽加入手牌。','\r',char(13)),'\n',char(10)),'是否选墓地怪兽加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27354732,'魔导兽 胡狼王',replace(replace('←4 【灵摆】 4→\r\n此卡名的灵摆效果1回合仅可使用1次。\n①：自己另一方的灵摆区域不存在卡的情况下可以发动。将此卡破坏，从自己额外牌组（表侧）将“魔导兽 胡狼王”以外的1只“魔导兽”灵摆怪兽特殊召唤。\r\n【怪兽效果】\r\n①：只要此卡存在于怪兽区域，每当自己或对手发动魔法卡，就在此卡上放2个魔力计数物。\n②：1回合1次，对手怪兽的效果发动时，去除自己场上的2个魔力计数物可以发动。将该发动无效并破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27381364,'电光闪灵・精灵',replace(replace('包括等级２・阶级２・连接２的怪兽在内的怪兽２只\r\n此卡名的②效果１回合仅可使用１次。此卡被连接召唤的回合不可作为连接素材。①：此卡连接端的怪兽不会成为对手效果的对象。②：在自己・对手的主要阶段，以自己墓地的１只等级２怪兽为对象可以发动。将该怪兽特殊召唤。对手场上存在怪兽的情况下，作为代替也可将１只阶级２或连接２的怪兽作为对象。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27383110,'宣告者之预言','“神光之宣告者”的降临所必需。①：为使合计等级为６，解放自己手牌・场上的怪兽，从手牌将“神光之宣告者”仪式召唤。②：以此卡的①效果仪式召唤“神光之宣告者”成功时，将墓地的此卡除外，以为该仪式召唤而解放的１只怪兽为对象可以发动。将该解放的自己墓地的１只怪兽加入手牌。','一只仪式解放的怪兽回到手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27383719,'超元特防队 拉普斯韦','此卡名的①②效果１回合仅可各使用１次。①：此卡特殊召唤成功的情况下，以自己墓地的１只“超元特防队 拉普斯韦”以外的“超元特防队”怪兽为对象可以发动。将该怪兽特殊召唤。②：从手牌将１张“超元特防队”卡除外可以发动。将自己的“超元特防队”怪兽正面的对手怪兽全部破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27407330,'光芒 古雷法','此卡可从手牌舍弃１只等级５或以上的光属性怪兽，并从手牌特殊召唤。１回合１次，可从手牌舍弃１只光属性怪兽并发动。从牌组挑选１只光属性怪兽，从游戏中除外。','除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27408609,'黄金人工生命体','此卡的攻击力、守备力上升从游戏中被除外的我方卡牌数量×３００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27412542,'双王之械',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从牌组将1张“破械”卡加入手牌。\r\n②：被放置的此卡因效果被破坏的情况下可以发动。从牌组将1只“破械”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27415516,'水征龙－川流',replace(replace('此卡名的效果１回合仅可使用１次。\r\n①：从手牌将１只龙族或水属性的怪兽与此卡舍弃可以发动。从牌组将１只“瀑征龙－狂潮”特殊召唤。以此效果特殊召唤的怪兽在此回合不可攻击。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27416701,'柴战士太郎','此卡不会因战斗被破坏。场上的卡因战斗或卡的效果被破坏时，将自己场上的表侧表示的此卡放回持有者的手牌。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27420823,'K9－17号 “割裂者”',replace(replace('等级5怪兽×2\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：去除此卡的1个超量素材可以发动。从牌组将1张“K9”卡加入手牌。对手在此回合发动过怪兽的效果的情况下，自己进而可从自己牌组・墓地将1张“K9”速攻魔法卡放置在自己场上。\r\n②：对手发动手牌・墓地的怪兽的效果时，去除此卡的1个超量素材可以发动。将该效果无效。','\r',char(13)),'\n',char(10)),'检索','效果无效','是否把卡放置？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27420824,'K9－17号 “割裂者”',replace(replace('等级5怪兽×2\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：去除此卡的1个超量素材可以发动。从牌组将1张“K9”卡加入手牌。对手在此回合发动过怪兽的效果的情况下，自己进而可从自己牌组・墓地将1张“K9”速攻魔法卡放置在自己场上。\r\n②：对手发动手牌・墓地的怪兽的效果时，去除此卡的1个超量素材可以发动。将该效果无效。','\r',char(13)),'\n',char(10)),'检索','效果无效','是否把卡放置？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27439792,'混沌召唤神','此卡名的①②效果1回合仅可各使用1次。①：解放此卡可以发动。从手牌将“神炎皇乌利亚”、“降雷皇哈蒙”、“幻魔皇拉比艾尔”中的任意1只无视召唤条件特殊召唤。②：将墓地的此卡除外可以发动。从牌组将1张“失乐园”加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27450400,'群聚灵摆','此卡召唤成功时，最多可特殊召唤与对手场上怪兽数量相等数量的“灵摆衍生物”（机械族、地、星１、攻／守０）至我方场上。','特殊召唤','是否继续特殊召唤「灵摆衍生物」？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27450401,'灵摆衍生物','由「群聚灵摆」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27480536,'装甲鲨',replace(replace('此卡名在规则上也视为“装甲超量”卡。\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：从额外牌组将１只水属性超量怪兽送至墓地，依该怪兽的阶级，以等级的数值与其相同的、自己墓地的１只鱼族怪兽为对象可以发动。将该怪兽特殊召唤。\r\n②：在对手回合中，此卡存在于墓地的情况下，以自己场上的１只水属性超量怪兽为对象可以发动。将此卡视为攻击力上升５００的装备魔法卡，装备于该怪兽。','\r',char(13)),'\n',char(10)),'特殊召唤','装备效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27483935,'古代机械齿轮司令',replace(replace('此卡名的①②③效果１回合仅可各使用１次。\r\n①：从自己的手牌・牌组・场上（表侧表示）将１只“古代机械齿轮巨人”送至墓地可以发动。进行１只“古代机械齿轮”怪兽的召唤。\r\n②：自己将“古代机械齿轮巨人”召唤・特殊召唤的情况下可以发动。从自己的手牌・墓地将１只“古代机械齿轮巨人”无视召唤条件特殊召唤。\r\n③：将墓地的此卡除外可以发动。从手牌将１张“古代机械齿轮”永续陷阱卡以表侧表示放在自己场上。','\r',char(13)),'\n',char(10)),'进行召唤','特殊召唤','放置永续陷阱','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27491571,'鬼计的魔女','仅在自己场上有“鬼计”怪兽存在的情况下，此卡才可以表侧表示召唤。①：在自己的主要阶段可以发动。将此卡改成里侧守备表示（１回合仅１次）。②：１回合１次，以对手场上的１只表侧表示怪兽为对象可以发动。将该怪兽改成里侧守备表示。','变成里侧守备表示','选择对手场上怪兽变成里侧守备表示','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27503418,'王者之同步',replace(replace('①：对手怪兽对自己的同步怪兽攻击宣言时可以发动。将该攻击无效。然后，可适用以下效果。\r\n●将该自己的同步怪兽和自己墓地的１只协调除外，将１只等级与所除外怪兽的等级合计相同的同步怪兽视为同步召唤从额外牌组特殊召唤。','\r',char(13)),'\n',char(10)),'是否把同步怪兽特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27519978,'四花缭乱之灵使',replace(replace('怪兽2只以上\r\n此卡名的②效果1回合仅可使用1次。\r\n①：此卡的攻击力上升场上的怪兽的属性种类×300的数值。\r\n②：只要此卡以表侧表示存在，仅限1次，在自己・对手的主要阶段，以自己墓地的，属性相同而种族不同的2只怪兽、或是种族相同而属性不同的2只怪兽为对象可以发动。将该2只怪兽特殊召唤。此卡及以此效果特殊召唤的怪兽直至下个回合结束时为止，不可作为融合・同步・超量・连接召唤的素材。','\r',char(13)),'\n',char(10)),'特殊召唤','「四花缭乱之灵使」效果适用中','已发动过效果','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27520594,'圣种之地灵','据说每一千年才可从圣天树上摘取１次的种子，历经千年时光后，将会化身为那片土地上的守护精灵。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27527047,'冰结界的御庭番','①：只要此卡存在于怪兽区域，对手不可将自己场上的“冰结界”怪兽作为怪兽效果的对象。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27541267,'侵略的泛发感染','①：自己场上的所有“邪蚀”怪兽直至回合结束时为止不受其他魔法・陷阱卡的效果影响。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27541563,'幻变骚灵・协定','此卡名的②效果1回合仅可使用1次。①：只要此卡存在于魔法与陷阱区域，自己场上的“幻变骚灵”卡的效果的发动及发动的该效果不会被无效化。②：对手发动怪兽效果时，将此卡以外的自己场上的1张表侧表示的“幻变骚灵”卡送至墓地可以发动。将该发动无效并破坏。','发动但不使用②效果','发动并使用②效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27548199,'枪管上膛狞猛龙',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的③效果1回合仅可使用1次。\r\n①：此卡同步召唤的情况下可以发动。从自己墓地将1只连接怪兽视为装备魔法卡装备于此卡，在此卡上放相当于其连接标记数量的枪管计数物。\r\n②：此卡的攻击力上升以此卡的效果装备的怪兽攻击力一半的数值。\r\n③：对手的效果发动时，去除此卡的1个枪管计数物可以发动。将该发动无效。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27552504,'永远的淑女 贝缇丽彩',replace(replace('等级6怪兽×2\r\n此卡也可将手牌的1只“彼岸”怪兽送至墓地，来重叠在自己场上的“但丁”怪兽的上方超量召唤。以此方法特殊召唤的回合，此卡的①效果不可发动。①：1回合1次，去除此卡的1个超量素材可以发动。从牌组挑选1张卡送至墓地。此效果在对手回合中也可以发动。②：此卡因对手被破坏并被送至墓地的情况下可以发动。将1只“彼岸”怪兽从额外牌组无视召唤条件特殊召唤。','\r',char(13)),'\n',char(10)),'在自己场上的「但丁」怪兽上面重叠来超量召唤？','从牌组选1张卡送至墓地','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27556460,'原石的反叫',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：除衍生物以外的、通常怪兽或等级5以上的“原石”怪兽存在于自己场上，且对手召唤・特殊召唤怪兽之际可以发动。将其无效，将该怪兽除外。\r\n②：在自己的准备阶段，自己场上存在“原石”怪兽的情况下可以发动。将墓地的此卡放置在自己场上。以此效果放置的此卡从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'无效','放置','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27561302,'雨之天气模样',replace(replace('①：只可有１张“雨之天气模样”以表侧表示存在于我方场上。\r\n②：存在于与此卡同一纵列的我方主要怪兽区以及其两旁的我方主要怪兽区的“天气”效果怪兽获得以下效果。\r\n●可将此卡除外，并以对手场上的１张魔法、陷阱卡为对象发动。将该卡返回至持有者手牌。此效果在对手回合也可发动。','\r',char(13)),'\n',char(10)),'魔法·陷阱卡回到持有者手牌（雨之天气模样）','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27564031,'Sin 世界','①：在自己的抽牌阶段，作为通常抽牌的代替可以发动。从牌组将3张“Sin”卡出示给对手，对手从其中随机挑选1张。将该1张卡加入自己的手牌，将剩余的卡放回牌组。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27565379,'蜂军－灵弓之梓',replace(replace('协调＋协调以外的怪兽１只以上\r\n此卡名的①效果１回合仅可使用１次。\r\n①：对手因其他“蜂军”怪兽的效果受到伤害时可以发动（在伤害步骤也可以发动）。给予对手该怪兽的原本攻击力数值的伤害。\r\n②：此卡存在于墓地的状态下，有怪兽因自己的“蜂军”怪兽的战斗被破坏时可以发动。将此卡以守备表示特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27572350,'神渊兽 迪斯・帕忒耳',replace(replace('协调＋协调以外的龙族怪兽1只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：以自己或对手除外状态的1只光・暗属性怪兽为对象可以发动。将该怪兽特殊召唤至自己场上。\r\n②：对手发动怪兽的效果时，以自己或对手除外状态的1张卡为对象可以发动。将该卡放回牌组。进而，对象卡的持有者为自己的情况下，发动该效果的怪兽将被破坏。为对手的情况下，将该发动的效果无效。','\r',char(13)),'\n',char(10)),'以对手除外的卡为对象发动','以自己除外的卡为对象发动','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27581098,'融合禁止区域','只要此卡存在于场上，双方玩家不可进行融合召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27618634,'薄幸的少女','只要此卡以表侧攻击表示存在，就不会因战斗而被破坏。只要此卡以表侧攻击表示存在于场上，与此卡战斗过的怪兽不可变更表示形式、不可攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27623932,'雷霆喷射','此卡名的卡1回合仅可发动1张。①：自己场上有“勇者衍生物”存在的情况下，以自己场上的1只装备了记载有“勇者衍生物”的衍生物名的装备卡的怪兽为对象可以发动。将对手场上拥有该怪兽的攻击力以下攻击力的怪兽全部破坏。然后，可从自己的手牌・墓地挑选1张记载有“勇者衍生物”的衍生物名的装备魔法卡，装备于自己场上1只可装备的怪兽。','是否选装备魔法卡装备？','请选择要装备的魔法卡','请选择要装备给的怪兽','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27632240,'虚空的骑士','１回合１次，此卡以表侧表示存在于场上的场合，场上的怪兽返回至手牌、牌组时，从牌组将１只风属性怪兽送入墓地。','送墓','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27632520,'妖精传姬－猫巫婆',replace(replace('魔法师族等级4怪兽×2\r\n此卡名的②③效果1回合仅可各使用1次。\r\n①：自己场上的原本属性为光属性的“妖精传姬”怪兽不受对手发动的效果影响。\r\n②：去除此卡的最多2个超量素材可以发动。依去除的数量，从牌组将“妖精传姬”卡送至墓地。\r\n③：在自己・对手回合中，此卡存在于墓地的情况下，以自己场上的1只原本属性为光属性的“妖精传姬”怪兽为对象可以发动。将此卡特殊召唤，将对象怪兽送至墓地。','\r',char(13)),'\n',char(10)),'送墓效果','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27642961,'秘旋谍任务－强袭',replace(replace('此卡发动后，将在第３次自己的结束阶段被破坏。\r\n①：１回合１次，自己的“秘旋谍”怪兽战斗破坏了怪兽的情况下，或自己场上的“秘旋谍”怪兽的效果破坏了场上的卡的情况下可以发动。自己抽１张。\r\n②：将墓地的此卡除外可以发动。从手牌将１只“秘旋谍”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27655513,'尖叫怪','此卡因战斗被破坏的场合，从牌组将２只水属性怪兽送入墓地。','送墓','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27657173,'真红眼黑星龙','此卡名的①②效果１回合仅可各使用１次。①：从手牌・牌组将１只等级５以上的通常怪兽送至墓地可以发动。从手牌将此卡特殊召唤。然后，此卡的等级上升１。②：将墓地的此卡除外可以发动。从自己的牌组・墓地挑选１张“真红眼结合”加入手牌。此效果在此卡被送至墓地的回合不可发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27660735,'疾行机人 三眼骰子','①：在对手回合中，将墓地的此卡除外可以发动。此回合仅１次，将对手怪兽的攻击无效。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27664101,'连接重启','①：给予我方伤害之怪兽的效果・魔法・陷阱卡发动时可发动。且使该发动无效，从我方墓地挑选１只连接怪兽并特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27671321,'雷鳗','传说电鳗进化之后就成了雷鳗。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27693363,'北斗天熊－勾陈一','此卡不可同步召唤，仅可在从自己场上将等级差为1的、1只协调和1只协调以外的怪兽送至墓地的情况下特殊召唤。此卡名的①②效果1回合仅可各使用1次。①：此卡特殊召唤成功的情况下可以发动。从牌组挑选1张“北斗天熊・大舀取号”发动。②：解放自己场上1只等级7以上的怪兽可以发动。从自己的墓地挑选1只“北斗天熊”怪兽加入手牌或特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27699122,'卡通翻页',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：自己场上存在“卡通世界”的情况下可以发动。从牌组将3只卡名不同的卡通怪兽出示给对手，对手从其中随机挑选1只。将该1只无视召唤条件特殊召唤至自己场上。将剩余的放回牌组。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27704731,'钢炎之剑士',replace(replace('此卡不可通常召唤，通过解放等级5以上战士族怪兽来发动的“钢铁化・强化反射装甲”的效果可以特殊召唤。\r\n此卡名的①效果1回合仅可使用1次。\r\n①：向对手出示手牌的此卡可以发动。从牌组将“钢炎之剑士”以外的、1张记载有“钢铁化・强化反射装甲”卡名的卡加入手牌，将此卡放回牌组。\r\n②：只要此卡存在于怪兽区域，每当对手发动效果，此卡的攻击力就上升300，并给予对手500伤害。','\r',char(13)),'\n',char(10)),'检索','上升攻击力','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27705190,'星遗物之交心','此卡名的①②效果1回合1次，仅可使用其中1个。①：自己场上有“机怪虫”怪兽存在，对手怪兽的效果发动时可以发动。该效果变为“挑选对手场上的1只表侧表示怪兽放回持有者手牌”。②：将墓地的此卡除外，以场上的1只连接怪兽为对象可以发动。从自己的手牌・牌组・墓地挑选1只“机怪虫”怪兽，以里侧守备表示特殊召唤至对象怪兽连接端的自己场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27744077,'绝体绝命','可在对手回合发动。此回合，对手怪兽的所有攻击会变成对玩家的直接攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27750191,'横纲犬','①：此卡召唤时可以发动。从自己手牌・墓地将1只协调特殊召唤。以此效果特殊召唤的怪兽的效果无效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27753563,'命运的里宝牌',replace(replace('①：支付１０００LP，以自己场上的１只表侧表示怪兽为对象可以发动。直至对手回合结束时为止，该怪兽的攻击力上升１０００，适用以下效果。\r\n●该怪兽战斗破坏对手怪兽时可以发动。将自己牌组最下面的卡给双方确认，并放回牌组最上面或最下面。所确认的卡为龙族・恐龙族・海龙族・幻龙族怪兽的情况下，其攻击力每有１０００，则自己抽１张。然后，自己恢复相当于所抽数量×１０００的LP。','\r',char(13)),'\n',char(10)),'自己牌组最下面的卡给双方确认','回到牌组最上面','回到牌组最下面','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27755794,'绚岚之米葛拉',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次，且②效果1回合仅可使用1次。\r\n①：自己墓地存在“气旋”的情况下，或对手场上不存在魔法・陷阱卡的情况下，此卡可从手牌特殊召唤。\r\n②：“绚岚”速攻魔法卡或“气旋”发动的情况下可以发动。从牌组将自己场上不存在同名怪兽的1只“绚岚”怪兽特殊召唤。此效果发动后，直至回合结束时为止，自己仅可特殊召唤风属性怪兽。','\r',char(13)),'\n',char(10)),'','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27756115,'超重武者装魂 死返',replace(replace('①：我方主要阶段可以我方场上的１只“超重武者”怪兽为对象发动。从我方手牌、场上将此怪兽视为装备卡装备该我方怪兽。\r\n②：因此卡效果装备此卡的怪兽，１回合仅１次不会因效果被破坏。\r\n③：守备表示怪兽因战斗被破坏并送入我方墓地时，可将此卡从手牌送入墓地并发动。以攻击表示特殊召唤该怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27762803,'大植然甲虫','只要此卡以表侧表示存在于场上，每次魔法卡发动，将此卡原本的攻击力与原本的守备力相互交换。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27769400,'图拉丁','对手战斗阶段开始时，我方场上存在２只或以上的怪兽，并且该些怪兽在１次战斗阶段中因战斗被全部破坏并送入墓地时可发动。从手牌特殊召唤此卡。此外，以此效果特殊召唤成功时发动。宣言１个属性，并破坏场上的全部宣言属性的怪兽。只要此卡以表侧表示存在于场上，对手不可召唤、特殊召唤宣言属性的怪兽。','特殊召唤','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27770341,'超再生能力','①：此卡发动的回合的结束阶段，自己从牌组抽与此回合从自己手牌扔掉的龙族怪兽以及此回合从自己手牌・场上解放的龙族怪兽数量等量的卡。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27780618,'幻影－英雄 拜昂',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将1只“－英雄”怪兽送至墓地。\r\n②：1回合1次，从自己墓地将1只“－英雄”怪兽除外可以发动。从牌组将1张“融合”加入手牌。','\r',char(13)),'\n',char(10)),'「－英雄」怪兽送至墓地','「融合」加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27781371,'天地再世',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：从牌组将1只“再世”怪兽送至墓地，以对手场上的1只表侧表示怪兽为对象可以发动。将该怪兽改成里侧守备表示。\r\n②：在对手回合中，将魔法与陷阱区域表侧表示的此卡送至墓地可以发动。将自己手牌・墓地・除外状态的“再世”怪兽尽可能地特殊召唤（同名卡最多1张）。以此效果特殊召唤的怪兽将在结束阶段被送至墓地。','\r',char(13)),'\n',char(10)),'改变表示形式','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27782503,'六武众－伊郎','我方场上存在有除“六武众－伊郎”以外的冠有“六武众”之名的怪兽的场合，此卡攻击了里侧守备表示怪兽的伤害步骤开始时，破坏该里侧守备表示怪兽。此外，场上的此卡被破坏的场合，可破坏我方场上的１只冠有“六武众”之名的怪兽作为代替。','里侧守备的攻击对象怪兽破坏','是否要使用「六武众－伊郎」的代替破坏效果？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27784944,'极天气 烟绿',replace(replace('①：此卡召唤成功时可以发动。从自己的手牌・牌组・墓地挑选１张“天气”魔法・陷阱卡，以表侧表示放在自己的魔法与陷阱区域。\r\n②：只要此卡存在于怪兽区域，自己场上的“天气”魔法・陷阱卡不会成为对手效果的对象，不会因对手的效果被破坏。\r\n③：场上的此卡为发动“天气”卡的效果被除外的情况下，可在下个回合的准备阶段发动。将被除外的此卡特殊召唤。','\r',char(13)),'\n',char(10)),'放置「天气」魔法·陷阱卡','除外的此卡特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27796375,'影灵衣的大魔道士',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：此卡因效果被解放的情况下可以发动。从牌组将1只魔法师族“影灵衣”仪式怪兽加入手牌。\r\n②：此卡被除外的情况下可以发动。从牌组将“影灵衣的大魔道士”以外的1只“影灵衣”怪兽送至墓地。','\r',char(13)),'\n',char(10)),'牌组检索','送至墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27813661,'天空之虹彩','此卡名的②效果１回合仅可使用１次。①：只要此卡存在于场地区域，自己灵摆区域的“魔术师”卡、“娱乐伙伴”卡、“异色眼”卡不会成为对手效果的对象。②：以自己场上此卡以外的１张表侧表示卡为对象可以发动。破坏该卡，从牌组将１张“异色眼”卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27821104,'六武众之荒行','①：以自己场上的１只“六武众”怪兽为对象可以发动。从牌组将１只卡名与该怪兽不同、攻击力相同的“六武众”怪兽特殊召唤。对象怪兽将在此回合的结束阶段被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27822206,'几星霜',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：自己场上的怪兽因自己的魔法卡的效果或对手的效果被破坏并被送至墓地的回合可以发动。下个自己的战斗阶段可进行２次。\r\n②：此卡存在于墓地的状态下，自己场上的怪兽被放回牌组・额外牌组（里侧）的情况下可以发动。将此卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27827272,'魔雾雨','可选择我方场上的１只“恶魔的召唤”或雷族怪兽来发动此卡。破坏对手场上所有守备力低于所选择怪兽攻击力的怪兽。发动此卡的回合中，跳过我方的战斗阶段。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27827903,'A次代机・粉碎机','①：１回合１次，属性与此卡相同的怪兽被召唤至自己场上时，以对手场上的１张卡为对象可以发动。将该对手的卡破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27863269,'火箭穿射器','装备怪兽攻击的场合，装备怪兽不会因战斗被破坏。装备怪兽进行攻击的伤害步骤结束时，受到装备怪兽攻击的怪兽的攻击力，直至回合结束时下降相当于装备怪兽的攻击力数值。','攻击下降','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27868563,'格布林百罗刹 神速布恩','①：此卡存在于手牌・墓地的情况下，在自己・对手的主要阶段可以发动。去除场上的１个超量素材，将此卡特殊召唤。此效果发动后，直至下个回合结束时为止，自己不可特殊召唤“格布林百罗刹 神速布恩”。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27869883,'圣音女祭司','解放自己场上的１只表侧表示的暗属性怪兽可以发动。给予对手LP８００点伤害。','800伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27870033,'追缉巡逻机','守备表示怪兽因战斗被破坏并送入墓地时，给予对手生命５００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27870337,'音服和弦・优雅',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：可从以下效果中选择1个发动。\r\n●从牌组将1只“音服和弦”灵摆怪兽放在自己的灵摆区域。\r\n●从手牌将1只“音服和弦”灵摆怪兽以表侧加入额外牌组。然后，从牌组将灵摆刻度为奇数和偶数的“音服和弦”灵摆怪兽各1只放在自己的灵摆区域。\r\n●从自己的灵摆区域将灵摆刻度为奇数和偶数的卡各1张以表侧加入额外牌组，自己抽2张。','\r',char(13)),'\n',char(10)),'放置1只灵摆怪兽','放置2只灵摆怪兽','抽2张卡','请选择要加入额外牌组的卡','','','','','','','','','','','','');
INSERT INTO texts VALUES(27873305,'DDD 怒涛坏薙王凯撒诸神黄昏',replace(replace('“DDD”怪兽×２\r\n①：１回合１次，此卡进行战斗的攻击宣言时，以此卡以外的自己场上的１张“DD”卡或“契约书”卡为对象可以发动。将该卡放回持有者的手牌，挑选与此卡进行战斗的怪兽以外的、对手场上的１只表侧表示怪兽，视为装备卡装备于此卡。②：此卡的攻击力上升相当于以此卡的效果装备的怪兽原本攻击力的数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27877771,'嗅探龙','此卡名的效果1回合仅可使用1次。①：此卡召唤・特殊召唤成功的情况下可以发动。从牌组将1只“嗅探龙”加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27882993,'狱火皇后鲑','此卡名的①②效果１回合仅可各使用１次。①：此卡召唤・特殊召唤成功的情况下可以发动。从自己的手牌・牌组・墓地挑选１只鱼族通常怪兽特殊召唤。②：此卡因战斗或对手的效果被破坏的情况下可以发动。将任意数量的“地狱士兵鲑衍生物”（鱼族・水・星１・攻／守０）特殊召唤至自己场上。','','','是否继续特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27882994,'地狱士兵鲑衍生物','由「狱火皇后鲑」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27895597,'命运女郎・考琳格',replace(replace('此卡牌名的卡牌１回合只可发动１张。\r\n①：我方场上存在有“命运女郎”怪兽的场合可发动。从牌组特殊召唤１只我方场不存在有同名卡的“命运女郎”怪兽。此卡发动后，直至回合结束时，我方只可从额外牌组特殊召唤同步怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27911549,'寄生虫 帕拉赛德','反转：将此卡以表侧表示混入对手牌组进行洗牌。当对手抽到此卡时，以表侧守备表示特殊召唤此卡至对手场上，并给予对手生命１０００点伤害。之后，只要此卡以表侧表示存在于场上，对手场上所有表侧表示的怪兽都将视为昆虫族。','进入对方卡组','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27911550,'寄生虫 帕拉赛德','反转：将此卡以表侧表示混入对手牌组进行洗牌。当对手抽到此卡时，以表侧守备表示特殊召唤此卡至对手场上，并给予对手生命１０００点伤害。之后，只要此卡以表侧表示存在于场上，对手场上所有表侧表示的怪兽都将视为昆虫族。','进入对方卡组','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27918365,'星遗物－星冠－','此卡名以①方法的特殊召唤1回合仅可进行1次，且③效果1回合仅可使用1次。①：此卡可从手牌以守备表示特殊召唤至连接怪兽连接端的自己场上。②：从额外牌组被特殊召唤的场上怪兽发动效果时，解放此卡可以发动。将该发动无效并破坏。③：通常召唤的此卡被解放的情况下可以发动。从牌组将1张“星遗物”魔法・陷阱卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27918963,'修验的妖社',replace(replace('“修验的妖社”的②效果１回合只可使用１次。\r\n①：只要此卡存在于魔法与陷阱区域，每次“妖仙兽”怪兽被召唤、特殊召唤，就放置１个妖仙计数物在此卡。\r\n②：可移除此卡任意数量的妖仙计数物并发动。根据移除数量适用以下效果。\r\n●１个：直至回合结束时，我方场上的“妖仙兽”怪兽的攻击力上升３００。\r\n●３个：从我方牌组、墓地挑选１张“妖仙兽”卡牌加入手牌。','\r',char(13)),'\n',char(10)),'取除计数物','攻击上升','加入手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27923575,'蠢贼游戏','此卡名的②效果１回合仅可使用１次。①：自己受到战斗伤害的伤害计算时可以发动。将因该战斗造成的对自己的战斗伤害改成０。②：被放置的此卡因对手的效果被破坏并被送至墓地的情况下，以“蠢贼游戏”以外的自己墓地的最多２张通常陷阱卡为对象可以发动。将该卡放置在自己场上。以此效果放置的卡在放置的回合中也可以发动。','','','适用「蠢贼游戏」的效果来发动','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27927359,'神鹰女郎','有着人身并长有翅膀的兽。其舞姿优美华丽，其攻击凌厉无比。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27944249,'薰风之贤者 薇达尔','此卡因战斗破坏怪兽并将其送入墓地时，可从我方墓地选择１只等级３或以下冠有“薰风”之名的怪兽并以守备表示特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27946124,'圣蔓之社',replace(replace('自己场上存在“圣天树”连接怪兽的情况下，将１张手牌送至墓地可以发动此卡。\r\n①：只要此卡存在于魔法与陷阱区域，自己从额外牌组仅可特殊召唤植物族怪兽。\r\n②：１回合１次，可以发动。从自己的墓地将１只等级４以下的植物族通常怪兽特殊召唤。\r\n③：在对手的结束阶段，将魔法与陷阱区域的表侧表示的此卡送至墓地，以自己墓地的１张永续陷阱卡为对象可以发动。将该卡放置在自己的魔法与陷阱区域。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27967615,'结合武器','仅限装备等级６或以下的融合怪兽。装备怪兽的攻击力、守备力上升１５００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27970830,'六武之门',replace(replace('①：每当有“六武众”怪兽被召唤・特殊召唤，就在此卡上放２个武士道计数物。\r\n②：依以下数量去除自己场上的武士道计数物，可以发动相应效果。\r\n●２个：以场上的１只“六武众”效果怪兽或“紫炎”效果怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止上升５００。\r\n●４个：从自己牌组・墓地将１只“六武众”怪兽加入手牌。\r\n●６个：以自己墓地的１只“紫炎”效果怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'●2个：攻击力上升','●4个：「六武众」怪兽加入手牌','●6个：「紫炎」怪兽特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27971137,'腐乱犬','每次此卡进行攻击宣言，此卡的攻击力上升５００点。此外，场上的此卡被破坏并被送入墓地的场合可发动。从牌组中特殊召唤１只守备力是０等级是１的怪兽。以此效果特殊召唤的怪兽的效果被无效化，下一个我方结束阶段时被破坏。','攻击上升','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27978707,'超重武者 影法师－C','此卡名的①②效果１回合仅可各使用１次。①：解放此卡可以发动。从手牌将１只“超重武者”怪兽特殊召唤。②：自己场上的“超重武者”怪兽成为效果的对象时，将墓地的此卡除外可以发动。将该发动无效并破坏。此效果在对手回合中也可以发动。','特殊召唤','发动无效并破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27979109,'武装锻炼',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：在自己的抽牌阶段，可以发动以代替进行通常的抽牌。从自己的牌组・墓地挑选１张装备魔法卡加入手牌。\r\n②：自己场上有装备魔法卡存在的情况下，从自己墓地将１只战士族・炎属性怪兽或二重怪兽放回牌组最下面可以发动。自己从牌组抽１张。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27980138,'飞鹏羽毛笔','将我方墓地中的２只风属性怪兽放回至牌组，选择场上１张卡牌回到持有者的手牌中。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27993919,'拉音服和弦・安吉莉娅',replace(replace('←3 【灵摆】 3→\r\n①：自己的“音服和弦”灵摆怪兽灵摆召唤成功时，对手不可发动怪兽的效果・魔法・陷阱卡。\r\n【怪兽效果】\r\n此卡名的①怪兽效果1回合仅可使用1次。\n①：在自己的主要阶段可以发动。解放自己场上的1只“音服和弦”灵摆怪兽，将“拉音服和弦・安吉莉娅”以外的、灵摆刻度比该怪兽高2或低2的1只“音服和弦”灵摆怪兽从牌组特殊召唤。\n②：自己的灵摆区域存在奇数的灵摆刻度，自己的“音服和弦”灵摆怪兽攻击的情况下，直至伤害步骤结束时为止对手不可发动魔法・陷阱卡的效果。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(27995943,'Dr.弗朗戈',replace(replace('“Dr.弗朗戈”的效果１回合只可使用１次。\r\n①：此卡召唤、特殊召唤成功的场合，可支付５００LP发动。我方确认牌组最上方的卡牌。之后，将已确认的卡牌返回至牌组最下方，或向对手展示并加入手牌。加入手牌的场合，跳过下一个我方抽牌阶段。','\r',char(13)),'\n',char(10)),'是否将确认的卡回到牌组最下面？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28002611,'小工具拖车','１回合１次，可从手牌将任意数量冠有“变形斗士”之名的怪兽送入墓地。此卡的攻击力上升以此效果被送入墓地的怪兽数量×８００点。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28003512,'审判之手','用寄宿着神灵之手下达最后的审判，并发动激烈的攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28004531,'空牙团的载货 雷克斯',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将1张“空牙团”魔法・陷阱卡加入手牌。\r\n②：在自己・对手的主要阶段，自己场上存在“空牙团”怪兽的情况下，将墓地的此卡除外，以自己墓地的1张“空牙团”卡为对象可以发动。将该卡加入手牌。对象卡为怪兽的情况下，也可不加入手牌而是改成将其特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28016193,'炼装勇士・山铜',replace(replace('“炼装勇士”怪兽×２\r\n①：我方的“炼装勇士”怪兽攻击了守备表示怪兽的场合，给予对手攻击力超过该守备力数值之双倍数值的战斗伤害。\r\n②：此卡从场上被送入墓地的场合，可以场上的１张卡牌为对象发动。破坏该卡。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28031913,'百兽之圣骑联盟','此卡名以①方法的特殊召唤1回合仅可进行1次，且②效果1回合仅可使用1次。①：此卡可从手牌以守备表示特殊召唤至连接怪兽连接端的自己场上。②：以自己场上的1只“圣骑联盟”连接怪兽为对象可以发动。此回合，该怪兽攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28039390,'魔玩具・复活',replace(replace('①：可以我方墓地的１只“魔玩具”怪兽为对象发动。特殊召唤该怪兽。\r\n②：可将墓地的此卡除外，并以我方被除外的１只“绒毛动物”怪兽或“魔玩具”怪兽为对象发动。将该怪兽返回至墓地。此效果在此卡被送入墓地之回合不可发动。','\r',char(13)),'\n',char(10)),'特殊召唤','回到墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28053106,'电子蛋天使','此卡名的效果１回合仅可使用１次。①：此卡召唤・反转召唤・特殊召唤成功的情况下可以发动。从牌组将１张“机械天使”魔法卡或“祝福教会－仪式圣堂”加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28053763,'机龙生成器',replace(replace('支付１０００LP可以发动此卡。\r\n此卡名的①效果１回合最多可使用２次。\r\n①：在自己的主要阶段可以发动。将１只“机龙衍生物”（机械族・地・星１・攻／守３００）以攻击表示特殊召唤至自己场上。此效果发动后，直至回合结束时为止，自己不可从额外牌组将怪兽特殊召唤。在此回合的结束阶段，对手必须将１只“机龙衍生物”以攻击表示特殊召唤至自身场上。','\r',char(13)),'\n',char(10)),'特殊召唤衍生物','对手必须把1只「机龙衍生物」在自身场上攻击表示特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28053764,'机龙衍生物','由“机龙生成器”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28062325,'竹头木屑','释放我方场上存在的１只植物族怪兽并发动。以守备表示特殊召唤２只“植物衍生物”（植物族、地、星１、攻８００／守５００）至对手场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28062326,'植物衍生物','由“竹头木屑”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28066831,'薰风・雷狼','此卡因战斗被破坏并送入墓地的场合，可在该战斗阶段结束时，将我方墓地的１只冠有“薰风”之名的怪兽从游戏中除外并发动。从牌组特殊召唤１只守备力是１５００或以下的念动力族、风属性怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28103028,'火马天龙','在沸腾的大海上纵横驰骋的龙马。为了不让自己的火熄灭，今天仍旧在水面上奔驰。梦想着踏上故土的那一天。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28106077,'双弯剑','仅限装备天使族怪兽。１只装备怪兽的攻击力上升５００点。装备怪兽通过战斗对对手玩家造成伤害时，回复我方与该伤害相同数值的LP。','LP回复','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28112535,'卡通左轮手枪龙',replace(replace('①：此卡在召唤・反转召唤・特殊召唤的回合不可攻击。\r\n②：自己场上存在“卡通世界”，且对手场上不存在卡通怪兽的情况下，此卡可直接攻击。\r\n③：1回合1次，以场上的1张卡为对象可以发动。掷3次硬币，其中2次以上为正面的情况下，将该卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28115467,'咪音服和弦・爱理迪娅',replace(replace('←6 【灵摆】 6→\r\n①：自己的“音服和弦”灵摆怪兽的灵摆召唤不会被无效化。\r\n【怪兽效果】\r\n此卡名的①怪兽效果1回合仅可使用1次。①：此卡召唤・特殊召唤成功的情况下，以对手场上1张魔法・陷阱卡作为对象可以发动。将该卡放回持有者的手牌。②：只要自己的灵摆区域有偶数的灵摆刻度存在，因自己的“音服和弦”灵摆怪兽的战斗对自己造成的战斗伤害变为0。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28118128,'子狸当当','反转：从牌组特殊召唤１只除“子狸当当”以外的兽族、等级２怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28120197,'断层地带','守备表示的岩石族怪兽被攻击，并且攻击怪兽的控制者受到战斗伤害的场合，该战斗伤害加倍。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28121403,'大成佛','破坏所有装备有装备卡的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28124263,'变形斗士・相机',replace(replace('此卡依据此卡的表示形式获得以下效果。\r\n●攻击表示：此卡因战斗被破坏时，可从我方的手牌、墓地挑选１只除“变形斗士・相机”以外的等级４或以下冠有“变形斗士”之名的怪兽特殊召唤。\r\n●守备表示：不可以双方场上冠有“变形斗士”之名的怪兽作为卡牌的效果对象。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28126717,'随风飘飘游与谜之地图','此卡名的①②效果１回合仅可各使用１次。①：在自己的主要阶段可以发动。从手牌将１只等级１“随风飘飘游”怪兽向对手出示，将卡名与所出示怪兽不同的１张“随风飘飘游”卡从牌组除外。然后，召唤所出示的怪兽。②：对手召唤怪兽成功的情况下可以发动。自己召唤１只“随风飘飘游”怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28139785,'拖吊小熊猫',replace(replace('①：在我方、对手的准备阶段时支付５００LP可发动。将我方牌组最上方的卡牌送入墓地，该卡牌为怪兽的场合，该卡的攻击力、守备力上升该怪兽等级×２００点。\r\n②：此卡因对手而破坏被送入墓地的场合可发动。从我方墓地将１只等级最低的怪兽加入手牌。','\r',char(13)),'\n',char(10)),'送至墓地','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28143384,'大气吞食者',replace(replace('同属性的恶魔族怪兽×2\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡融合召唤的情况下可以发动。从牌组将1只恶魔族怪兽送至墓地。\r\n②：此卡存在于墓地的情况下，从自己墓地将除“大气吞食者”以外的、2只等级6以上且属性相同的恶魔族怪兽除外可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'送至墓地','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28143906,'霾之谷的大怪鸟','此卡从手牌被送入墓地时发动。此卡返回至牌组。','返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28150174,'光子蝶刺客',replace(replace('等级４怪兽×２\r\n１回合１次，可移除此卡的１个超量素材，并选择场上的１只守备表示怪兽发动。将被选择怪兽变成表侧攻击表示，且该攻击力下降６００点。','\r',char(13)),'\n',char(10)),'改变表示形式','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28151978,'疾行机人 多米诺蝴蝶',replace(replace('←8 【灵摆】 8→\r\n“疾行机人 多米诺蝴蝶”的②灵摆效果１回合仅可使用１次。\n①：自己仅可灵摆召唤风属性怪兽。此效果不会被无效化。\n②：从手牌将１只风属性怪兽舍弃，以自己１只被除外的风属性怪兽为对象可以发动。将该怪兽加入手牌。\r\n【怪兽效果】\r\n以此卡作为同步素材的情况下，仅可使用于龙族・机械族风属性怪兽的同步召唤。\n从额外牌组特殊召唤的此卡被使用于同步召唤的情况下被除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28168628,'斗神的虚像',replace(replace('“对击斗魂”怪兽１只\r\n此卡不可作为连接素材。\r\n此卡名的②效果１回合仅可使用１次。\r\n①：只要自己场上存在“对击斗魂”怪兽，对手仅可将自己场上攻击力最高的怪兽选择为攻击对象。\r\n②：在自己・对手的主要阶段，可从以下效果中选择１个发动。\r\n●从手牌将１只“对击斗魂”怪兽特殊召唤。\r\n●从自己的墓地将１只“对击斗魂”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'从手牌把1只「对击格斗之魂」怪兽特殊召唤','从自己墓地选1只「对击格斗之魂」怪兽加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28168762,'圣蔓之守卫者',replace(replace('植物族通常怪兽１只\r\n①：自己场上的“圣天树”连接怪兽因效果从场上离开的情况下发动。将此卡破坏。\r\n②：与“圣天树”连接怪兽处于连接状态的此卡与对手怪兽进行战斗的攻击宣言时可以发动。因该战斗对自己造成的战斗伤害变为一半。\r\n③：此卡因战斗被破坏时可以发动。该伤害步骤结束后，结束战斗阶段。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28174796,'海晶少女 官服','此卡名的效果1回合仅可使用1次。①：此卡存在于手牌・墓地，自己场上有2只以上“海晶少女”怪兽存在的情况下，以自己场上的1只水属性连接怪兽为对象可以发动。将此卡特殊召唤至该怪兽连接端的自己场上。以此效果特殊召唤的此卡离开场上的情况下，将其除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28183605,'龙骑兵团－执政官','①：此卡召唤成功时，以自己墓地的1只龙族・等级3以下的“龙骑兵团”怪兽为对象可以发动。将该龙族怪兽视为装备卡装备于此卡。②：此卡的攻击力上升自己场上的“龙骑兵团”卡的数量×200。','装备','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28189908,'T.G.－突破限制',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：舍弃１张手牌可以发动。从牌组将２只“T.G.”怪兽加入手牌（同名卡最多１张）。\r\n②：将墓地的此卡除外，以自己墓地的１只“T.G.”怪兽为对象可以发动。将该怪兽放回牌组。自己场上存在机械族“T.G.”怪兽的情况下，也可不放回牌组而是改为将其加入手牌。','\r',char(13)),'\n',char(10)),'','','是否加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28190303,'黑羽－白夜的古罗马短剑',replace(replace('①：我方场上的表侧表示怪兽除“黑羽－白夜的古罗马短剑”以外仅有１只“黑羽”怪兽的场合，可从手牌特殊召唤此卡。\r\n②：此卡仅１回合１次，不会因战斗而被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28194325,'英豪挑战者 折叠刀','此卡因冠有“英豪挑战者”之名怪兽的效果特殊召唤成功时，可发动。从牌组将１只冠有“英豪挑战者”之名的怪兽加入手牌。“英豪挑战者 折叠刀”的效果１回合只可使用１次。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28201945,'蜜笼之虫惑魔',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：此卡只要存在于怪兽区域，不受“空洞”通常陷阱卡及“落穴”通常陷阱卡的效果影响。\r\n②：自己发动“空洞”通常陷阱卡或“落穴”通常陷阱卡的情况下可以发动。从牌组挑选“蜜笼之虫惑魔”以外的１只“虫惑魔”怪兽，加入手牌或特殊召唤。','\r',char(13)),'\n',char(10)),'牌组检索','是否要把怪兽特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28226490,'泪冠哀歌・卡雷多哈忒',replace(replace('“泪冠哀歌・雷诺哈忒”＋水族怪兽×２\r\n此卡不可作为融合素材。此卡名的①②效果１回合仅可各使用１次。①：此卡特殊召唤成功的情况下，或此卡存在于场上的状态下、水族怪兽因效果被送至自己墓地的情况下，以对手场上的１张卡为对象可以发动。将该卡放回持有者的牌组。②：此卡因效果被送至墓地的情况下可以发动。将此卡特殊召唤，从牌组将１张“泪冠哀歌”卡送至墓地。','\r',char(13)),'\n',char(10)),'对方卡回到持有者牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28234578,'灵子纠缠',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：以对手场上的１只表侧表示怪兽为对象可以发动。将该怪兽直至结束阶段为止除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28240337,'真红眼不死尸龙',replace(replace('协调＋１只以上协调以外的怪兽\r\n此卡名的②效果１回合仅可使用１次。①：此卡的攻击力・守备力上升相当于双方场上・墓地的不死族怪兽数量×１００的数值。②：此卡以外的不死族怪兽因战斗被破坏时可以发动。挑选自己或对手墓地的１只不死族怪兽，特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28265983,'干渴之风',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己恢复LP的情况下，以对手场上的１只表侧表示怪兽为对象发动。将该怪兽破坏。\r\n②：自己场上存在“芬芳”怪兽，且自己的LP比对手多３０００以上的情况下，支付相当于其数值差的LP可以发动。将攻击力合计为、为发动此效果而支付的LP的数值以下的、对手场上表侧表示的怪兽破坏。','\r',char(13)),'\n',char(10)),'发动但不使用效果','选择1只怪兽破坏','选攻击力在支付的基本分数值以下的怪兽破坏','是否还要选择怪兽破坏？','','','','','','','','','','','','');
INSERT INTO texts VALUES(28270534,'鼓劲-艾-','此卡名的卡１回合仅可发动１张。①：以自己墓地的１只“＠伊格尼斯者”怪兽为对象可以发动。将该怪兽特殊召唤。②：自己场上攻击力２３００以上的“＠伊格尼斯者”怪兽将被效果破坏的情况下，可将墓地的此卡除外作为代替。③：此卡被除外的情况下可以发动。此回合，自己攻击力２３００以上的“＠伊格尼斯者”怪兽不会因战斗被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28273805,'六武式袭双阵',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：从以下效果中挑选１个适用。自己场上存在２只以上“六武众”怪兽的情况下，两者都可适用。\r\n●从自己手牌・墓地将１只攻击力２０００以下的“六武众”怪兽特殊召唤。\r\n●将对手场上的１只攻击力２０００以下的怪兽改成里侧守备表示。\r\n②：在自己的主要阶段将墓地的此卡除外，以自己墓地的１只“六武众”怪兽为对象可以发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','改变表示形式','选择2方','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28279365,'闪瞬连倒','①：以场上的１只连接怪兽为对象可以发动。将该怪兽放回额外牌组。然后，可将作为该怪兽的连接素材的、被送至自己墓地的１只怪兽特殊召唤。','是否特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28279543,'诅咒之龙','邪恶的龙。其使用暗黑力量的攻击强而有力。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28284902,'变形斗士・监视器','冠有“变形斗士”之名的怪兽召唤、反转召唤、特殊召唤成功时，可将该怪兽变为表侧守备表示。','变成守备表示','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28290705,'妖精王 艾尔柏德',replace(replace('地属性等级４怪兽×２\r\n１回合１次，可移除此卡的１个超量素材并发动。场上所有地属性以外的怪兽的攻击力、守备力下降５００点。','\r',char(13)),'\n',char(10)),'攻守下降','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28292031,'恐啡肽骇龙・逆转','此卡名的卡１回合仅可发动１张。①：自己场上存在“恐啡肽骇龙”融合怪兽的情况下，支付一半LP，从自己的墓地将１张反击陷阱卡除外可以发动。此效果变为与该反击陷阱卡发动时的效果相同。②：自己的LP为２０００以下，自己受到战斗伤害的伤害计算时，将墓地的此卡除外可以发动。将因该战斗对自己造成的战斗伤害改成０。','复制反击陷阱卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28297833,'死灵脸','①：此卡召唤成功的情况下发动。将双方被除外的卡全部放回持有者的牌组。此卡的攻击力上升相当于以此效果放回牌组的数量×１００的数值。②：此卡被除外的情况下发动。双方玩家分别从自身牌组上面将５张卡除外。','除外的卡全部回到牌组','双方从牌组上面把5张卡从游戏中除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28306253,'饥怒汉堡',replace(replace('以“食谱”卡降临\r\n此卡名在规则上视为“饥饿汉堡”。\r\n此卡名的①③效果1回合仅可各使用1次。\r\n①：向对手出示手牌的此卡可以发动。从牌组将1只“饿魔新飨”怪兽加入手牌，将此卡放回牌组。\r\n②：可攻击的对手怪兽必须攻击此卡。\r\n③：在自己・对手回合中可以发动。解放自己・对手场上的1只攻击表示怪兽，从手牌・牌组将1只攻击力2000的“饥饿汉堡”特殊召唤。','\r',char(13)),'\n',char(10)),'检索','','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28325165,'水物语－浦岛','①：自己的墓地有“水伶女”怪兽存在的情况下，以场上的１只怪兽为对象可以发动。直至回合结束时为止，将该怪兽的效果无效化，攻击力・守备力变为１００，不受对手效果的影响。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28331069,'超银河眼光子龙－光子咆哮',replace(replace('等级8怪兽×3\r\n“超银河眼光子龙－光子咆哮”1回合1次，也可重叠在自己场上的阶级8的超量怪兽上面来超量召唤。\r\n①：此卡超量召唤的情况下可以发动。从牌组挑选1只“光子”怪兽，以守备表示特殊召唤，或作为此卡的超量素材。\r\n②：在自己・对手回合中，去除此卡的3个超量素材可以发动。解放自己场上1只其他的超量怪兽，此卡以外的、场上所有表侧表示的卡的效果直至回合结束时为止无效化。','\r',char(13)),'\n',char(10)),'是否在超量怪兽上面重叠来超量召唤？','是否特殊召唤？','选择要处理的怪兽','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28331070,'超银河眼光子龙－光子咆哮',replace(replace('等级8怪兽×3\r\n“超银河眼光子龙－光子咆哮”1回合1次，也可重叠在自己场上的阶级8的超量怪兽上面来超量召唤。\r\n①：此卡超量召唤的情况下可以发动。从牌组挑选1只“光子”怪兽，以守备表示特殊召唤，或作为此卡的超量素材。\r\n②：在自己・对手回合中，去除此卡的3个超量素材可以发动。解放自己场上1只其他的超量怪兽，此卡以外的、场上所有表侧表示的卡的效果直至回合结束时为止无效化。','\r',char(13)),'\n',char(10)),'是否在超量怪兽上面重叠来超量召唤？','是否特殊召唤？','选择要处理的怪兽','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28332833,'炎狱妖猴','此卡因战斗被破坏并送入墓地时可发动。从牌组将１只守备力２００的怪兽加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28340377,'花牌的纽带',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：自己场上不存在“王后骑士”、“卫兵骑士”、“国王骑士”以外的怪兽的情况下可以发动。从自己的手牌・墓地，挑选“王后骑士”、“卫兵骑士”、“国王骑士”中的１只特殊召唤。\r\n②：从自己的手牌・墓地，将“王后骑士”、“卫兵骑士”、“国王骑士”各最多１只除外可以发动。自己依所除外的数量从牌组抽牌。','\r',char(13)),'\n',char(10)),'特殊召唤','除外并抽牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28346136,'银河眼光波极龙',replace(replace('等级１０怪兽×２\r\n“银河眼光波极龙”１回合１次，也可重叠在自己场上的“光波龙”怪兽上面来超量召唤。①：去除此卡的２个超量素材可以发动。自己场上的光属性怪兽直至对手回合结束时为止，不会成为对手效果的对象。②：在自己的准备阶段可以发动。将自己墓地的１只阶级９以下的龙族超量怪兽放回额外牌组。然后，可将该怪兽重叠在自己场上的此卡上面，视为超量召唤从额外牌组特殊召唤。','\r',char(13)),'\n',char(10)),'是否在「光波龙」怪兽上面重叠来超量召唤？','','','','是否把那只怪兽特殊召唤？','','','','','','','','','','','');
INSERT INTO texts VALUES(28348537,'暴风雪公主',replace(replace('此卡可通过解放1只魔法师族怪兽来以攻击表示上级召唤。\r\n①：此卡召唤时适用。此回合，对手不可发动魔法・陷阱卡。','\r',char(13)),'\n',char(10)),'把1只魔法师族怪兽解放召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28348939,'白虎召唤士',replace(replace('①：成功召唤此卡时可发动此卡。从手牌特殊召唤１只等级４以下的通常怪兽。\r\n②：只要此卡存在于怪兽区域，我方场上的怪兽的攻击力和守备力上升１００。','\r',char(13)),'\n',char(10)),'特殊召唤','攻守上升','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28355718,'命运－英雄 双身小子','此卡不可特殊召唤。此卡可在１次战斗阶段中进行２次攻击。此卡被破坏送入墓地的场合，在下一次我方回合的准备阶段时，可将２只“双身小子衍生物”（战士族・暗・星４・攻／守１０００）特殊召唤至我方场上。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28355719,'双身小子衍生物','由「命运－英雄 双身小子」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28357177,'华丽哈尼','反转：可选择最多３只场上的怪兽并将其返回至持有者手牌。','返回手牌','是否要选择怪兽回到手牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28358902,'红莲女守护兵','解放此卡可以发动。选择１只此回合因战斗被破坏的自己墓地的怪兽并放回牌组的最下方。','返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28363749,'火焰蛋白石头领',replace(replace('←0 【灵摆】 0→\r\n【怪兽效果】\r\n热血澎湃的石头恐龙头领。会用变幻莫测的动作和火焰将敌人玩弄于股掌之间，并用必杀技“火焰蛋白石头槌”发出攻势。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28369508,'地中骇界邪龙的潜伏',replace(replace('①：从自己墓地将1只“地中骇界”怪兽除外可以发动。直至回合结束时为止，自己场上的里侧表示怪兽不会因效果被破坏，对手不可将其作为效果的对象。\r\n②：场上的此卡因效果被破坏的情况下可以发动。从牌组将1只“地中骇界”怪兽加入手牌。\r\n③：将墓地的此卡除外，以自己场上的1只“地中骇界”怪兽为对象可以发动。将该怪兽改成里侧守备表示。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28373620,'神碑之牙 基利',replace(replace('“神碑”怪兽×２\r\n①：此卡从额外牌组特殊召唤成功的情况下，以１张速攻魔法卡以外的自己墓地的“神碑”魔法卡为对象可以发动。将该卡加入手牌。②：场上的此卡不会因效果被破坏。③：此卡因战斗被破坏时，以场上的１张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'墓地回收','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28378427,'伤害电容器','①：自己受到战斗伤害时，扔掉1张手牌可以发动。将1只拥有所受伤害数值以下的攻击力的怪兽从牌组以攻击表示特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28388296,'废铁工厂','此卡名的②效果１回合仅可使用１次。①：场上的“废铁”怪兽的攻击力・守备力上升２００。②：场上的表侧表示“废铁”怪兽因效果被破坏并被送至墓地时可以发动。自己从牌组将１只“废铁”怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28388927,'蜂军－毒针之尖刺',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将“蜂军－毒针之尖刺”以外的１只“蜂军”怪兽加入手牌。\r\n②：在自己・对手回合中，解放自己场上的１只其他昆虫族怪兽，以对手场上的１只效果怪兽为对象可以发动。将该怪兽的效果直至回合结束时为止无效。','\r',char(13)),'\n',char(10)),'牌组检索','效果无效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28400508,'编号97 龙影神 引力子龙',replace(replace('等级８怪兽×２\r\n此卡名的②效果１回合仅可使用１次。\r\n①：对手不可将场上的此卡作为效果的对象。\r\n②：去除此卡的１个超量素材可以发动。从自己的额外牌组・墓地挑选“编号97 龙影神 引力子龙”以外的２种龙族“编号”怪兽。将其中１只特殊召唤，另１只作为其超量素材。此效果发动后，直至回合结束时为止自己不可特殊召唤怪兽，仅可用以此效果特殊召唤的怪兽攻击宣言。','\r',char(13)),'\n',char(10)),'','请选择要作为超量素材的卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28403802,'朋.克.即兴龙舞',replace(replace('念动力族协调＋１只以上协调以外的怪兽\r\n此卡名的①②效果１回合仅可各使用１次。①：此卡同步召唤或以“朋.克.”卡的效果特殊召唤成功的情况下，支付６００LP可以发动。从牌组挑选１只念动力族・等级３怪兽，加入手牌或送至墓地。②：此卡存在于墓地的状态下，对手连锁自己的“朋.克.”卡的效果的发动、发动卡的效果的情况下可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28403803,'朋.克.即兴龙舞',replace(replace('念动力族协调＋１只以上协调以外的怪兽\r\n此卡名的①②效果１回合仅可各使用１次。①：此卡同步召唤或以“朋.克.”卡的效果特殊召唤成功的情况下，支付６００LP可以发动。从牌组挑选１只念动力族・等级３怪兽，加入手牌或送至墓地。②：此卡存在于墓地的状态下，对手连锁自己的“朋.克.”卡的效果的发动、发动卡的效果的情况下可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28406301,'DD 狮鹫',replace(replace('←1 【灵摆】 1→\r\n此卡名的灵摆效果１回合仅可使用１次。①：以自己场上的１只恶魔族怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止，上升相当于自己的场上・墓地的“契约书”魔法・陷阱卡种类×５００的数值。然后，将此卡破坏。\r\n【怪兽效果】\r\n此卡名的①②③怪兽效果１回合仅可各使用１次。①：在自己场上有“DD”怪兽存在的情况下可以发动。从手牌将此卡以守备表示特殊召唤。②：此卡灵摆召唤成功的情况下，从手牌将１张“DD”卡或“契约书”卡舍弃可以发动。自己从牌组抽１张。③：此卡从墓地特殊召唤成功的情况下可以发动。从牌组将“DD 狮鹫”以外的１张“DD”卡加入手牌。','\r',char(13)),'\n',char(10)),'从手牌守备表示特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28423537,'战栗的凶皇－始祖恶魔',replace(replace('①：此卡无需解放即可召唤。\r\n②：以此卡的①方法召唤的此卡原本的攻击力・守备力变为一半，将在结束阶段被破坏。\r\n③：只要此卡存在于怪兽区域，自己仅可特殊召唤恶魔族怪兽。\r\n④：1回合1次，从自己手牌・墓地将1张“恶魔”卡除外，以场上的1张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'不解放进行召唤','破坏','结束阶段破坏','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28427869,'卷烟蚊',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己因对手怪兽的攻击受到战斗伤害的伤害计算时可以发动。从手牌将此卡特殊召唤，因该战斗对自己造成的战斗伤害变为一半，在该伤害步骤结束后，结束战斗阶段。\r\n②：以自己场上的１只表侧表示怪兽为对象可以发动。此卡的等级直至回合结束时为止变为与该怪兽相同。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28429121,'咒仪世传禁断秘术','“咒仪”仪式怪兽的降临所必需。发动此卡的回合中，自己无法进行战斗阶段。①：为使合计等级与仪式召唤的怪兽相等，解放自己・对手场上的表侧表示怪兽，从手牌将１只“咒仪”仪式怪兽仪式召唤。以此效果仪式召唤的怪兽的攻击力变为一半。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28450915,'来自异次元的侵略者','从银河系外来到地球的外星人。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28454232,'纠罪巧－诈狐 Astaγ.PIXIEA',replace(replace('←0 【灵摆】 0→\r\n①：每当有怪兽反转，就在此卡上放1个纠罪计数物。\n②：在自己・对手的战斗阶段结束时，另一方自己的灵摆区域存在“纠罪巧”卡的情况下，以对手场上的1只攻击力低于此卡的怪兽为对象可以发动。将该怪兽破坏。\r\n【怪兽效果】\r\n①：向对手出示手牌的此卡可以发动（发动此效果的回合中，自己仅可以里侧守备表示特殊召唤怪兽）。从手牌将1只怪兽以里侧守备表示特殊召唤。\n②：对手发动以自己场上的卡为对象的效果时，将里侧表示的此卡改成表侧守备表示可以发动。将该效果无效。然后，可随机将对手的1张手牌以里侧除外。\n③：只要反转的此卡存在于怪兽区域，对手不可将场上・墓地的卡作为效果的对象。','\r',char(13)),'\n',char(10)),'破坏','特殊召唤','除外','是否除外？','已反转过','','','','','','','','','','','');
INSERT INTO texts VALUES(28465301,'异虫欧佩拉','反转：除冠有“异虫”之名的爬虫类族怪兽以外的场上所有怪兽的攻击力下降５００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28470714,'镰刀苍蝇','只要此卡以表侧表示存在于场上，场上的风属性怪兽攻击力上升５００点。地属性怪兽攻击力下降４００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28486799,'补充部隊','①：每次我方因对手怪兽的攻击或对手效果受到１０００或以上伤害发动。每受到１０００伤害，我方从牌组抽取１张卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28493337,'终焉的指名者','可将１张手牌从游戏中除外并发动。在此决斗中，不可发动被除外的该卡牌及其同名卡的效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28497830,'黄金荣耀－弹球手',replace(replace('“黄金荣耀－滚球手”＋“黄金荣耀”怪兽１只以上\r\n此卡名的①效果１回合仅可使用１次。\r\n①：此卡融合召唤的情况下可以发动（自己的LP少于对手的情况下，此效果的发动和效果不会被无效化）。将对手场上的表侧表示怪兽视为装备魔法卡装备于此卡，数量最多为作为该融合素材的数量。\r\n②：在发动了此卡的①效果的回合的结束阶段发动。将此卡放回额外牌组，从自己的牌组・墓地将１只“黄金荣耀－滚球手”特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28506708,'异虫呼唤','１回合１次，对手场上存在有怪兽，且我方场上不存在怪兽的场合可发动。从手牌以里侧守备表示特殊召唤１只冠有“异虫”之名的爬虫类族怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28529976,'超营养太阳','①：解放自己场上的1只等级2以下的植物族怪兽可以发动此卡。从手牌・牌组将1只等级在所解放怪兽的等级＋3以下的植物族怪兽特殊召唤。此卡从场上离开时，该怪兽将被破坏。该怪兽从场上离开时，此卡将被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28531163,'默齿录',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：作为此卡发动时的效果处理，依对手场上卡的数量在此卡上放C计数物。\r\n②：以对手场上的1只表侧表示怪兽为对象，去除自己场上的最多4个C计数物可以发动。根据去除的计数物的数量对该怪兽适用以下效果。\r\n●1个：攻击力下降500。\r\n●2个：将攻击力改成0。\r\n●3个：将效果无效。\r\n●4个：破坏。','\r',char(13)),'\n',char(10)),'选效果发动','下降攻击力','攻击力变成0','效果无效','破坏','','','','','','','','','','','');
INSERT INTO texts VALUES(28534130,'转生炎兽之炎虞','此卡名的卡1回合仅可发动1张。①：从手牌将1只“转生炎兽”怪兽的效果无效并特殊召唤，以包括该怪兽的自己场上怪兽作为素材，将1只“转生炎兽”连接怪兽连接召唤。此回合，以此效果连接召唤的怪兽不可攻击，不可发动效果。②：在自己的主要阶段将墓地的此卡除外，以自己墓地的1只“转生炎兽”连接怪兽对象可以发动。将该怪兽放回额外牌组。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28546905,'幻想师・无面者','制造幻影，能轻易躲开敌人的攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28553439,'次元魔法','①：自己场上有魔法师族怪兽存在的情况下，以自己场上的1只怪兽为对象可以发动。解放自己的该怪兽，从手牌将1只魔法师族怪兽特殊召唤。然后，可挑选1只场上的怪兽破坏。','是否要破坏一只怪兽？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28563545,'龙杀者','此卡被召唤、反转召唤至场上时，破坏表侧表示的１只龙族怪兽。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28565527,'黄龙的召唤士',replace(replace('“黄龙的召唤士”的效果１回合只可使用１次。\r\n①：可释放我方场上的１只怪兽，并以场上的１只怪兽为对象发动。将该怪兽返回至持有者手牌。','\r',char(13)),'\n',char(10)),'回到手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28566710,'最终一战！','自己的LP在１０００以下的情况下，在对手回合可以发动。挑选自己场上存在的１只怪兽，将该怪兽以外的双方的手牌・场上的卡全部送往墓地。发动后，对手从牌组以攻击表示特殊召唤１只怪兽，和自己挑选的怪兽进行战斗。此战斗发生的对双方玩家的战斗伤害变成０。此回合的结束阶段时，仅一方玩家控制有怪兽的情况下，该控制者获得决斗胜利。除此以外的情况下游戏平局。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28570310,'魔导兽 迦楼罗',replace(replace('←4 【灵摆】 4→\r\n此卡名的灵摆效果1回合仅可使用1次。\n①：自己另一方的灵摆区域不存在卡的情况下，以场上1张其他魔法・陷阱卡为对象可以发动。将该卡和此卡破坏。\r\n【怪兽效果】\r\n此卡名的①怪兽效果1回合仅可使用1次。\n①：对手召唤・特殊召唤怪兽时，去除自己场上的3个魔力计数物可以发动。从手牌将此卡特殊召唤。然后，将对手召唤・特殊召唤的该怪兽放回手牌。\n②：只要此卡存在于怪兽区域，每当自己或对手发动魔法卡，就在此卡上放1个魔力计数物。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28573958,'奇迹之代行者 朱庇特',replace(replace('①：1回合1次，从自己墓地将1只“代行者”怪兽除外，以自己场上的1只天使族・光属性怪兽为对象可以发动。该自己的天使族・光属性怪兽的攻击力直至回合结束时为止上升800。\r\n②：1回合1次，从手牌将1只天使族怪兽舍弃，以自己除外状态的1只天使族・光属性怪兽为对象可以发动（此效果在场上存在“天空的圣域”的情况下才能发动和处理）。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'攻击力上升','除外怪兽特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28577986,'水精鳞－水仙女深渊','可选择我方场上冠有“水精鳞”之名的１只怪兽并发动。从牌组特殊召唤等级４或以下冠有“水精鳞”之名的任意数量怪兽，使等级的合计变为被选择怪兽的等级或以下。之后，将被选择怪兽送入墓地。“水精鳞－水仙女深渊”的效果１回合只可使用１次。','特殊召唤','是否要继续特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28593329,'暗黑安琪儿','①：我方的天使族怪兽被选择为攻击对象时，可解放该怪兽，并将此卡从手牌送入墓地，以我方场上的１只表侧表示怪兽为对象发动。攻击对象转移至该我方怪兽，直至回合结束时，对象怪兽的攻击力上升被解放之天使族怪兽的原本攻击力数值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28593363,'潜伏深海的鲨鱼','“神鱼”＋“舌鱼”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28596933,'巨龙振翅','①：挑选自己场上的1只等级5以上的龙族怪兽放回持有者手牌，将场上的魔法・陷阱卡全部破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28601770,'迷雾恶魔','此卡可无须解放进行召唤。以此方法召唤的此卡在结束阶段被破坏，我方受到１０００点伤害。','不用解放作召唤','破坏并伤害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28604635,'抖落','可支付５００LP发动。破坏场上所有攻击表示的等级３怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28617139,'西摩格之来寇','此卡名的卡1回合仅可发动1张。①：从手牌将1只鸟兽族怪兽舍弃可以发动。从牌组将2只“西摩格”怪兽加入手牌（同属性最多1只）。②：将墓地的此卡除外可以发动。将手牌的1只鸟兽族怪兽出示给对手。此回合，该怪兽及自己手牌的同名怪兽的等级下降1。','牌组检索','等级下降','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28630501,'妖仙兽 镰参太刀',replace(replace('“妖仙兽 镰参太刀”的②效果１回合只可使用１次。\r\n①：此卡召唤成功的场合可发动。从手牌召唤１只除“妖仙兽 镰参太刀”以外的“妖仙兽”怪兽。\r\n②：除此卡以外的我方“妖仙兽”怪兽给予对手战斗伤害时可发动。从牌组将１张除“妖仙兽 镰参太刀”以外的“妖仙兽”卡牌加入手牌。\r\n③：於召唤此卡回合的结束阶段发动。将此卡返回至持有者手牌。','\r',char(13)),'\n',char(10)),'召唤','牌组检索','返回手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28637168,'起重鹤','此卡名的效果1回合仅可使用1次。①：此卡召唤成功时，以自己墓地的1只等级3怪兽为对象可以发动。将该怪兽特殊召唤。以此效果特殊召唤的怪兽的效果无效化。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28642461,'K9－66a号 冰精',replace(replace('此卡名的②③效果1回合仅可各使用1次。\r\n①：对手的手牌为2张以上的情况下，此卡无需解放即可召唤。\r\n②：将手牌的此卡与手牌的1只等级5怪兽出示给对手可以发动。将该2只特殊召唤。以此效果特殊召唤的怪兽不可作为光属性超量怪兽的超量召唤的素材。\r\n③：在自己的主要阶段可以发动。从牌组将水族以外的1只“K9”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'不用解放召唤(K9－66a号 冰精)','特殊召唤','检索','「K9－66a号 冰精」的效果特殊召唤','','','','','','','','','','','','');
INSERT INTO texts VALUES(28643791,'最后的进军','可选择我方场上１只冠有“极神”之名的怪兽并发动。直至回合结束时，被选择怪兽的效果被无效化，且不受其他魔法、陷阱卡效果的影响。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28645123,'决战-艾-','此卡名的③效果１回合仅可使用１次。①：对手场上怪兽的攻击力下降相当于自己场上卡数量×１００的数值。②：自己的“＠伊格尼斯者”怪兽进行战斗的情况下，对手直至伤害步骤结束时为止，不可发动魔法・陷阱・怪兽的效果。③：自己的“＠伊格尼斯者”怪兽因战斗被破坏时，以自己墓地该怪兽以外的１只攻击力２３００的电子界族怪兽为对象可以发动。将该怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28649820,'阿波菲斯的化神','①：在自己・对手的主要阶段可以发动此卡。此卡变为通常怪兽（爬虫类族・地・星4・攻1600/守1800）特殊召唤至怪兽区域（也视为陷阱卡）。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28651380,'幻魔皇拉比艾尔－天界蹂躏拳','此卡不可通常召唤。仅可在解放自己场上3只怪兽的情况下特殊召唤。此卡名的①②效果1回合仅可各使用1次。①：可从手牌将此卡扔掉，以自己场上的1只“幻魔皇拉比艾尔”为对象发动。此回合中，该怪兽的攻击力变为两倍，可攻击所有对手怪兽各1次。此效果在对手回合中也可以发动。②：此卡存在于墓地的情况下，解放自己场上的1只怪兽可以发动。将此卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28653611,'地狱处刑者',replace(replace('①：可从以下效果中选择1个发动（此卡名的以下效果1回合仅可各选择1次）。\r\n●从牌组将1只恐龙族・水属性怪兽加入手牌。对手场上存在怪兽的情况下，进而可将加入了手牌的该怪兽特殊召唤。\r\n●解放自己场上的1只怪兽可以发动。从自己手牌・牌组・墓地将1只等级6以上的炎属性怪兽特殊召唤。以此效果将恶魔族以外的怪兽特殊召唤的情况下，该怪兽的效果无效化。','\r',char(13)),'\n',char(10)),'发动','检索效果','特殊召唤','是否特殊召唤？','','','','','','','','','','','','');
INSERT INTO texts VALUES(28654932,'深黑落穴','等级５以上的效果怪兽特殊召唤成功时可以发动。将该等级５以上的效果怪兽从游戏除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28669235,'登龙华海瀧门',replace(replace('①：“登龙华海瀧门”在自己场上仅可有１张以表侧表示存在。\r\n②：只要此卡存在于魔法与陷阱区域，自己的“龙华”怪兽不会因战斗被破坏。\r\n③：自己场上的“龙华”灵摆怪兽，及等级１０以上且原本种族为海龙族的怪兽获得以下效果。\r\n●每个对手回合中１次，将自己场上的１张表侧表示的“龙华”永续魔法卡放回牌组最下面，以场上的１张卡为对象可以发动。将该卡放回手牌。','\r',char(13)),'\n',char(10)),'','让场上的卡回到手牌（「登龙华海瀧门」）','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28674152,'多次元坏兽掠地昂','①：此卡可以解放对手场上１只怪兽，以攻击表示从手牌特殊召唤至对手场上。②：对手场上有“坏兽”怪兽存在的情况下，此卡可以从手牌中以攻击表示特殊召唤。③：“坏兽”怪兽在自己场上仅可有１只以表侧表示形式存在。④：１回合１次，去除自己・对手场上的２个坏兽计数物可以发动。将１只“掠地昂衍生物”（恶魔族・暗・星７・攻２８００／守０）特殊召唤至自己场上。此衍生物不可作为同步素材。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28674153,'掠地昂衍生物','由「多次元坏兽掠地昂」的效果特殊召唤。这衍生物不能作为同调素材。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28677304,'元素－英雄 漆黑新宇侠',replace(replace('“元素－英雄 新宇侠”＋“新空间人 漆黑猎豹”\r\n仅在将自己场上的上述卡放回牌组的情况下，可从额外牌组特殊召唤。①：以场上的１只效果怪兽为对象可以发动。此卡存在于怪兽区域期间，该怪兽的效果无效化（以此效果可作为对象的怪兽最多１只）。②：在结束阶段发动。将此卡放回持有者的额外牌组。','\r',char(13)),'\n',char(10)),'返回牌组','效果无效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28692962,'紫宵之机界骑士','此卡名以①方法的特殊召唤1回合仅可进行1次，且②效果1回合仅可使用1次。①：同一纵列有2张以上的卡存在的情况下，可将此卡特殊召唤至该纵列的自己场上。②：以自己场上的1只“机界骑士”怪兽为对象可以发动。直至下个自己回合的准备阶段为止将该怪兽除外，从牌组将1只“紫宵之机界骑士”以外的“机界骑士”怪兽加入手牌。此效果在对手回合中也可以发动。','','除外的怪兽回到场上','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28711704,'卡通混沌士兵',replace(replace('此卡不可通常召唤。\r\n为使合计等级达到8以上，解放自己手牌・场上的卡通怪兽的情况下可以特殊召唤。\r\n①：自己场上存在“卡通世界”，且对手场上不存在卡通怪兽的情况下，此卡可直接攻击。\r\n②：1回合1次，自己场上存在“卡通世界”的情况下，以场上的1张卡为对象可以发动（发动此效果的回合中，此卡不可攻击）。将该卡除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28715905,'北斗天熊－大白熊','此卡名的①②效果1回合仅可各使用1次。①：在自己・对手的主要阶段，从手牌解放此卡以外的1只等级7以上的怪兽可以发动。从手牌将此卡特殊召唤。此效果发动后，直至回合结束时为止，自己仅可特殊召唤拥有等级的怪兽。②：自己场上有其他“北斗天熊”怪兽存在的状态下，此卡特殊召唤成功的情况下，以对手场上1张魔法・陷阱卡作为对象可以发动。将该卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28720123,'龙剑士 机动重装 强化',replace(replace('←6 【灵摆】 6→\r\n此卡名的灵摆效果１回合仅可使用１次。\n①：以另一方自己的灵摆区域的１张“龙剑士”卡或“机动雾龙”卡为对象可以发动。将该卡特殊召唤。\r\n【怪兽效果】\r\n此卡名在规则上也视为“机动雾龙”卡。\n此卡名的怪兽效果１回合仅可使用１次。\n①：此卡被解放的情况下可以发动。从自己的额外牌组（表侧）将除“龙剑士 机动重装 强化”以外的１只“龙剑士”灵摆怪兽或“机动雾龙”灵摆怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28725004,'魔鬼的智慧','此卡从攻击表示变为表侧守备表示时，我方牌组洗牌。','洗牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28741524,'念动收集机','①：以自己墓地任意数量的等级2以下的念动力族怪兽为对象可以发动。将该念动力族怪兽特殊召唤。然后，自己受到以此效果特殊召唤的怪兽的合计等级×300的伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28754338,'真海皇 特莱顿','可释放此卡以及我方场上的１只海龙族怪兽并发动。从手牌、牌组特殊召唤１只“海皇龙 波赛德龙”。之后，所有对手场上怪兽的攻击力下降３００点。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28762303,'冰翡之蒂诺拉','此卡名的①②效果１回合仅可各使用１次。①：将１张手牌送至墓地，以自己墓地的１只水属性怪兽为对象可以发动。将场上的此卡送至墓地，将对象怪兽特殊召唤。②：此卡存在于墓地的状态下，自己场上表侧表示的水属性怪兽因战斗・效果被破坏的情况下，将此卡除外可以发动。从自己的手牌・墓地挑选“冰翡之蒂诺拉”以外的１只“冰翡”怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28770951,'银河修道师','此卡名的①②效果1回合1次，仅可使用其中1个。①：以自己场上的1只“光子”超量怪兽或“银河”超量怪兽为对象可以发动。将手牌的此卡重叠在该怪兽下面作为超量素材。②：此卡召唤・特殊召唤成功的情况下，以自己墓地的“光子”卡及“银河”卡中合计5张为对象可以发动（同名卡最多1张）。将该卡加入牌组洗牌。然后自己从牌组抽2张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28776350,'阿卡西魔术师',replace(replace('衍生物以外的同种族怪兽2只\r\n自己1回合仅可连接召唤1次“阿卡西魔术师”。①：此卡连接召唤成功的情况下发动。将此卡连接端的怪兽全部放回持有者手牌。②：1回合1次，宣言1个卡名可以发动。从自己牌组上面翻牌，数量为此卡的相互连接端的怪兽的连接标记的合计数，其中有宣言的卡的情况下，将该卡加入手牌。其他翻开的卡全部送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28781003,'急袭者骑士',replace(replace('暗属性等级4怪兽×2\r\n此卡名在规则上也视为“魅影骑士团”卡、“急袭猛禽”卡。\r\n此卡名的效果1回合仅可使用1次。\r\n①：去除此卡的1个超量素材可以发动。从额外牌组将1只比此卡阶级高1或低1的“魅影骑士团”、“急袭猛禽”、“超量龙”超量怪兽重叠在自己场上的此卡上面，视为超量召唤特殊召唤。以此效果特殊召唤的怪兽将在下个对手的结束阶段被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28798938,'双天之狮使－阿吽',replace(replace('“双天”怪兽×２\r\n①：此卡根据作为融合素材的怪兽的原本卡名，获得以下效果。\r\n●“双天将 金刚”：进行战斗的自己的“双天”怪兽的攻击力仅在伤害计算时变为３０００。\r\n●“双天将 密迹”：在对手回合中１次，以场上的１张卡为对象可以发动。将该卡除外。\r\n②：融合召唤的此卡被破坏的情况下可以发动。从牌组将“双天拳之熊罴”、“双天脚之鸿鹄”各１只特殊召唤。该怪兽此回合不会因战斗・效果被破坏。','\r',char(13)),'\n',char(10)),'「双天将 金刚」为融合素材','「双天将 密迹」为融合素材','','「双天之狮使－阿吽」效果适用中','','','','','','','','','','','','');
INSERT INTO texts VALUES(28803166,'红泪之魔 拉克莉末莎',replace(replace('此卡名在规则上也视为“魔镌”卡。\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将“红泪之魔 拉克莉末莎”以外的１张“魔镌”卡送至墓地。\r\n②：在对手回合中，此卡存在于墓地的情况下，以自己墓地的１只“魔镌”连接怪兽为对象可以发动。将此卡放回牌组，将对象怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'送至墓地','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28806532,'阴天气丝紫',replace(replace('此卡牌名的①效果１回合只可使用１次。\r\n①：此卡存在于我方场上，且除此卡以外我方场上的表侧表示“天气”卡牌被送入墓地的场合，可以我方墓地最多２张“天气”魔法、陷阱卡为对象发动。将该卡以表侧表示放置在我方的魔法与陷阱区域。\r\n②：场上的此卡为了发动“天气”卡牌效果而被除外的场合，可在下一个回合的准备阶段发动。特殊召唤被除外的此卡。','\r',char(13)),'\n',char(10)),'从墓地放置「天气」魔法·陷阱卡','除外的此卡特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28827503,'进入VRAINS！','此卡名的卡１回合仅可发动１张。①：从手牌将１只怪兽的效果无效并特殊召唤，将自己场上包括该怪兽在内的怪兽作为素材来连接召唤。该连接召唤不会被无效化，该连接召唤成功时，对手不可发动魔法・陷阱・怪兽的效果。②：此卡存在于墓地的状态下，自己场上的连接怪兽因战斗・效果被破坏的情况下，将此卡除外可以发动。从自己的墓地挑选１只原本种族与该怪兽相同的怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28859794,'盾翼鸟','此卡１回合最多２次不会因战斗被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28865322,'魔装邪龙 以太兵器',replace(replace('←4 【灵摆】 4→\r\n①：１回合１次，可将我方墓地的１只“魔装战士”怪兽除外，并以场上的１张卡牌为对象发动。破坏该卡。\r\n【怪兽效果】\r\n①：此卡召唤、特殊召唤成功时，可以场上的１只怪兽为对象发动。将该怪兽除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28868394,'貉藻之虫惑魔',replace(replace('此卡名的①③效果１回合１次，仅可使用其中１个。\r\n①：将自己场上里侧表示的１张陷阱卡送至墓地可以发动。从手牌将此卡特殊召唤。\r\n②：此卡只要存在于怪兽区域，不受“空洞”通常陷阱卡及“落穴”通常陷阱卡的效果影响。\r\n③：自己的魔法与陷阱区域不存在卡的情况下，将墓地的此卡除外，以自己墓地的１张“空洞”通常陷阱卡或“落穴”通常陷阱卡为对象可以发动。将该卡放置在自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28877100,'防守战术','自己场上有名字带有“剑斗兽”的怪兽存在的情况下可以发动。此回合，自己的怪兽不会被战斗破坏，对自己的战斗伤害变为０。发动后，将此卡放回牌组最下面。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28877382,'终刻龙机Ⅴ－阿玛耳忒',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下，或因效果被破坏的情况下可以发动。从牌组将“终刻龙机Ⅴ－阿玛耳忒”以外的1只“终刻”怪兽加入手牌。\r\n②：在自己・对手回合中，此卡装备有装备卡的情况下可以发动。从额外牌组将阶级与此卡的等级数值相同的1只机械族・风属性超量怪兽视为超量召唤特殊召唤，将此卡及此卡的装备卡全部作为其超量素材。','\r',char(13)),'\n',char(10)),'加入手牌','超量召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28877602,'进化虫・半甲齿龟','①：此卡召唤时可以发动。从手牌将１只“进化龙”怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28884172,'我我我巫师','①：１回合１次，以自己墓地的１只“我我我巫师”以外的“我我我”怪兽为对象可以发动。将该怪兽特殊召唤。此效果发动后，直至回合结束时为止自己仅可特殊召唤“我我我”怪兽。②：作为超量素材的此卡为发动超量怪兽的效果被去除并被送至墓地的情况下，以自己场上的１只超量怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止上升５００。','特殊召唤','攻击上升','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28890974,'光神化','①：从手牌特殊召唤１只天使族怪兽。以此效果特殊召唤的怪兽攻击力减半，在结束阶段被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28903523,'永恒阳光',replace(replace('此卡名的②效果在1回合中，最多可使用的次数为自己场上“上古精灵龙”及记载有该卡名的怪兽数量。\r\n①：自己场上的怪兽的守备力上升相当于自己场上的“上古精灵龙”及记载有该卡名的怪兽数量×500的数值。\r\n②：以对手场上的1只表侧表示怪兽为对象可以发动（同一连锁上最多1次）。该怪兽直至回合结束时为止，攻击力・守备力变为一半，效果无效化。','\r',char(13)),'\n',char(10)),'','无效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28912357,'齿轮齿巨人 X',replace(replace('机械族等级４怪兽×２\r\n①：１回合１次，去除此卡的１个超量素材可以发动。从自己的牌组・墓地挑选１只等级４以下的机械族怪兽加入手牌。②：表侧表示的此卡从场上离开时，以自己墓地的１只等级３以下的“齿轮齿轮”怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'加入手牌','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28927782,'龙骑兵团・小队疾驰',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：可从以下效果中选择1个发动。此回合，自己仅可特殊召唤“龙骑兵团”怪兽。\r\n●以自己的魔法与陷阱区域的1张“龙骑兵团”怪兽卡为对象可以发动。将该卡以守备表示特殊召唤。\r\n●以自己场上的1只“龙骑兵团”怪兽为对象可以发动。从自己墓地将1只“龙骑兵团”怪兽视为装备魔法卡，装备于对象的自己怪兽。','\r',char(13)),'\n',char(10)),'是否立即使用效果？','特殊召唤','装备','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28929131,'时械神 扎菲翁',replace(replace('此卡不可从牌组特殊召唤。\r\n①：自己场上不存在怪兽的情况下，此卡无需解放即可召唤。\r\n②：此卡不会因战斗・效果被破坏，因此卡的战斗对自己造成的战斗伤害变为0。\r\n③：此卡进行过战斗的战斗阶段结束时发动。将对手场上的魔法・陷阱卡全部放回牌组。\r\n④：此卡从场上被送至墓地的情况下可以发动。自己抽1张。\r\n⑤：在自己的准备阶段发动。将此卡放回牌组。','\r',char(13)),'\n',char(10)),'不用解放作召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28933734,'暗之假面','反转：选择我方墓地１张陷阱卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28954097,'镜 剑骑士',replace(replace('此卡名的①③效果１回合仅可各使用１次。\r\n①：在自己・对手回合中，解放此卡可以发动。从牌组将“镜 剑骑士”以外的１只记载有“客迈拉结合”卡名的怪兽特殊召唤。\r\n②：此卡与怪兽进行战斗的情况下，该２只不会因该战斗被破坏。\r\n③：自己场上存在“有翼幻兽 客迈拉”，且对手场上的怪兽发动效果时，将场上・墓地的此卡除外可以发动。将该效果无效。','\r',char(13)),'\n',char(10)),'从牌组特殊召唤','对手效果无效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28957126,'格尔格尼奥的咒眼',replace(replace('仅限装备“咒眼”怪兽。\r\n此卡牌名的卡牌１回合只可发动１张，此卡牌名的③效果１回合只可使用１次。\r\n①：只要此卡存在于魔法与陷阱区域，卡牌名就被视为“塞勒涅的咒眼”。\r\n②：我方的LP少于对手的场合，装备怪兽的攻击力上升LP差额数值。\r\n③：可将墓地的此卡除外，从手牌舍弃１张“咒眼”卡牌并发动。从牌组将１张除“格尔格尼奥的咒眼”以外的“咒眼”魔法、陷阱卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28958464,'魔法卡“死者苏生”',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：以自己或对手墓地的1只怪兽为对象可以发动。将该怪兽特殊召唤至自己场上。此回合，以此效果特殊召唤的怪兽不可攻击，其效果不可发动。','\r',char(13)),'\n',char(10)),'','「魔法卡“死者苏生”」的效果特殊召唤，不可攻击，不可把效果发动。','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28966434,'单游小魔女','１回合１次，可选择我方场上１只冠有“命运女郎”之名的怪兽和场上１只表侧表示怪兽并发动。被选择的冠有“命运女郎”之名怪兽的等级下降３级，破坏另１只被选择怪兽。','破坏','请选择等级下降的怪兽','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28968609,'垃圾魔像',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：自己场上存在攻击力或守备力为0的怪兽的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：向对手出示额外牌组的阶级不同的3只超量怪兽，以场上的1张其他卡为对象可以发动。将该卡和此卡破坏。\r\n③：将墓地的此卡除外可以发动。去除自己场上的1个超量素材。然后，可从自己手牌・墓地将1只攻击力或守备力为0的怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','破坏效果','取除素材','是否特殊召唤？','','','','','','','','','','','','');
INSERT INTO texts VALUES(28981598,'九魂猫',replace(replace('等级９怪兽×２\r\n此卡名的②效果１回合仅可使用１次。\r\n①：只要此卡存在于怪兽区域，自己场上被从墓地特殊召唤的其他怪兽不会成为对手效果的对象。\r\n②：去除此卡的１个超量素材，以自己墓地的１只等级９怪兽或对手墓地的１只怪兽为对象可以发动。将该怪兽特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28985331,'终末骑士','①：此卡召唤・反转召唤・特殊召唤成功时可以发动。从牌组将1只暗属性怪兽送至墓地。','从牌组把1只暗属性怪兽送至墓地','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(28990150,'光子三头犬','只要此卡以表侧表示存在于场上，召唤此卡的回合，双方都不可发动陷阱卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29013526,'狂啸薇茵','①：1回合1次，解放自己场上的1只其他风属性怪兽可以发动。从手牌将1只风属性怪兽特殊召唤。以此效果特殊召唤的怪兽在自己场上表侧表示的“狂啸薇茵”从场上离开时将被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29021114,'银色小工具',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：此卡召唤・特殊召唤时可以发动。从手牌将１只机械族・等级４怪兽特殊召唤。\r\n②：此卡因战斗・效果被破坏的情况下可以发动。从牌组将“银色小工具”以外的１只等级４“小工具”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29047353,'水剧台水舞台',replace(replace('①：自己场上的水属性怪兽不会因与水属性以外的怪兽的战斗被破坏。\r\n②：自己场上的“水伶女”怪兽不受对手怪兽的效果影响。\r\n③：此卡从场上被送至墓地的情况下，以自己墓地１只水族怪兽为对象可以发动。将该怪兽特殊召唤。此效果发动后，直至回合结束时为止，自己仅可特殊召唤水族怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29053656,'赤龙 克察尔科亚特尔',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的①③效果1回合仅可各使用1次。\r\n①：此卡同步召唤的情况下可以发动。从自己墓地将龙族同步怪兽尽可能地特殊召唤。此回合，自己不可特殊召唤怪兽。\r\n②：此卡的攻击力上升相当于自己场上其他的同步怪兽原本攻击力的合计数值。\r\n③：对手发动怪兽的效果时可以发动。将自己场上的1只其他的龙族同步怪兽放回额外牌组，将该发动无效。','\r',char(13)),'\n',char(10)),'特殊召唤','发动无效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29053657,'赤龙 克察尔科亚特尔',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的①③效果1回合仅可各使用1次。\r\n①：此卡同步召唤的情况下可以发动。从自己墓地将龙族同步怪兽尽可能地特殊召唤。此回合，自己不可特殊召唤怪兽。\r\n②：此卡的攻击力上升相当于自己场上其他的同步怪兽原本攻击力的合计数值。\r\n③：对手发动怪兽的效果时可以发动。将自己场上的1只其他的龙族同步怪兽放回额外牌组，将该发动无效。','\r',char(13)),'\n',char(10)),'特殊召唤','发动无效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29054481,'霞之谷的看守者','他是代代看守霞之谷的看守者一族之末裔。任何一点发生在峡谷中的小事都逃不过他的法眼。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29062925,'花牌融合',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：从自己的手牌・场上，将由战士族・光属性融合怪兽卡决定的融合素材怪兽送至墓地，将该１只融合怪兽从额外牌组融合召唤。自己场上有“王后骑士”、“卫兵骑士”、“国王骑士”中的任一存在的情况下，也可以自己牌组的最多１只怪兽作为融合素材。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29071332,'支援武器手',replace(replace('协调＋协调以外的怪兽1只以上\r\n①：1回合1次，可以发动以下的1个效果。\r\n●以场上的1只表侧表示怪兽为对象，将此卡视为攻击力上升1000的装备魔法卡装备。\r\n●将以此效果装备中的此卡以攻击表示特殊召唤。\r\n②：以此卡的效果装备此卡的怪兽战斗破坏怪兽并将其送至墓地的情况下发动。给予对手相当于该所破坏怪兽的原本攻击力数值的伤害。','\r',char(13)),'\n',char(10)),'当作装备卡使用给怪兽装备','装备解除特殊召唤','给予对手伤害','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29081251,'死相之冥鉴 修布罗',replace(replace('此卡名的②③效果1回合仅可各使用1次。\r\n①：此卡无需解放即可召唤。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从牌组将除“死相之冥鉴 修布罗”以外的、1只等级6以上的不死族怪兽送至墓地。然后，可从自己墓地将1只等级6以上的不死族怪兽加入手牌。\r\n③：此卡存在于怪兽区域的状态下，有怪兽从墓地被特殊召唤的情况下可以发动。进行1只不死族超量怪兽的超量召唤。','\r',char(13)),'\n',char(10)),'不用解放召唤','送至墓地','超量召唤','是否加入手牌？','','','','','','','','','','','','');
INSERT INTO texts VALUES(29085954,'编号78 号数档案馆',replace(replace('等级１怪兽×２\r\n①：１回合１次，去除此卡的１个超量素材可以发动。对手随机挑选自己额外牌组的１张卡。其为“编号1“～“编号99”中的任一“编号”怪兽的情况下，将该怪兽重叠在自己场上的此卡上面，视为超量召唤从额外牌组特殊召唤。以此效果特殊召唤的怪兽将在结束阶段被除外。此效果发动后，直至回合结束时为止，自己不可特殊召唤怪兽。此效果在对手回合中也可以发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29087919,'齿轮齿轮变换',replace(replace('“齿轮齿轮变换”１回合只可发动１张。\r\n①：可以我方墓地２只或以上的“齿轮齿轮人”怪兽为对象发动（同名卡最多１张）。特殊召唤该怪兽，并仅以该怪兽为素材超量召唤１只超量怪兽。','\r',char(13)),'\n',char(10)),'是否还要召唤「齿轮齿轮人」怪兽','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29088922,'命运女郎・沃特莉',replace(replace('①：此卡的攻击力、守备力变成此卡的等级×３００。\r\n②：在我方准备阶段发动。此卡的等级上升１级（最高至１２级）。\r\n③：我方场上存在有除“命运女郎・沃特莉”以外的“命运女郎”怪兽，且此卡特殊召唤成功的场合发动。我方从牌组抽取２张卡牌。','\r',char(13)),'\n',char(10)),'等级上升','抽牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29092121,'光波复叶机','此卡名的①③效果１回合仅可各使用１次。①：“光波”怪兽被召唤・特殊召唤至自己场上的情况下可以发动。从手牌将此卡特殊召唤。②：１回合１次，以自己场上的２只“光波”怪兽为对象可以发动。将该怪兽的等级直至回合结束时为止改成８。③：此卡因战斗・效果被破坏并被送至墓地的情况下，将墓地的此卡除外可以发动。从牌组将１只“光波”怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29095457,'原石之穿光',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：向对手出示“原石之穿光”以外的、手牌的1张“原石”卡或1只通常怪兽，以场上的1张表侧表示卡为对象可以发动（自己场上存在除衍生物以外的、通常怪兽或等级5以上的“原石”怪兽的情况下，也可在不出示的条件下发动）。将对象卡的效果无效并除外。\r\n②：自己场上存在“原石”怪兽的情况下，在自己的主要阶段可以发动。将墓地的此卡放置在自己场上。','\r',char(13)),'\n',char(10)),'是否展示卡来发动？','此卡放置 ','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29095552,'假面－英雄 酸水',replace(replace('此卡仅可通过“假面变换”的效果特殊召唤。\r\n①：此卡特殊召唤的情况下发动。将对手场上的魔法・陷阱卡全部破坏，对手场上的所有怪兽的攻击力下降300。','\r',char(13)),'\n',char(10)),'魔陷破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29099860,'刚鬼 魔神・过肩摔霸王龙',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：向对手出示手牌的此卡与手牌的1只“刚鬼”怪兽可以发动。将该2只特殊召唤。只要以此效果特殊召唤的怪兽以表侧表示存在于自己场上，自己仅可特殊召唤“刚鬼”怪兽。\r\n②：此卡从场上被送至墓地的情况下可以发动。从牌组将“刚鬼 魔神・过肩摔霸王龙”以外的1张“刚鬼”卡加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','检索','因「刚鬼 魔神・过肩摔霸王龙」的效果被观看','「刚鬼 魔神・过肩摔霸王龙」的效果特殊召唤','','','','','','','','','','','','');
INSERT INTO texts VALUES(29107423,'红莲蔷薇之魔女','此卡名的①②效果１回合仅可各使用１次。①：解放此卡可以发动。从牌组将１只“黑蔷薇之魔女”加入手牌，从牌组挑选１只等级３以下的植物族怪兽，放在牌组最上面。然后，可从手牌召唤１只“黑蔷薇之魔女”。②：将墓地的此卡除外可以发动。从自己墓地的怪兽或被除外的自己的怪兽中，挑选１只“黑蔷薇龙”或“红莲蔷薇龙”放回额外牌组。','','','请选择要放置在牌组最上面的卡','是否把「黑蔷薇女巫」召唤？','','','','','','','','','','','','');
INSERT INTO texts VALUES(29111045,'格布林百罗刹大收监',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：解放自己场上的１只怪兽可以发动。从牌组将１只“格布林”怪兽特殊召唤。以此效果特殊召唤的怪兽在此回合不可攻击。\r\n②：自己或对手的怪兽的攻击宣言时，将墓地的此卡除外，去除自己场上的“格布林”超量怪兽的任意数量的超量素材可以发动。对手场上所有怪兽的攻击力直至回合结束时为止，下降相当于所去除的数量×１０００的数值。','\r',char(13)),'\n',char(10)),'特殊召唤','攻击力下降','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29114773,'疾行机人刮刮乐','此卡名的卡1回合仅可发动1张。①：从手牌将1张“疾行机人”卡送至墓地可以发动。从牌组将1只“疾行机人”怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29116732,'破晓者','此卡特殊召唤成功时，可从手牌特殊召唤１只“破晓者”。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29139104,'荒狂奥丝','①：1回合1次，解放自己场上的1只其他地属性怪兽可以发动。从手牌将1只地属性怪兽特殊召唤。以此效果特殊召唤的怪兽在自己场上表侧表示的“荒狂奥丝”从场上离开时将被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29143457,'炎舞－隐元－',replace(replace('此卡名的卡１回合仅可发动１张，此卡名的②效果１回合仅可使用１次。\r\n①：作为此卡发动时的效果处理，可适用以下效果。\r\n●以自己的手牌・场上的怪兽作为融合素材，将１只兽战士族融合怪兽融合召唤。\r\n②：魔法与陷阱区域表侧表示的此卡被送至墓地的情况下，以自己墓地的１只“炎星”怪兽为对象可以发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','是否融合召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29143726,'转生龙 僧娑罗',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的效果1回合仅可使用1次。\r\n①：场上的此卡因对手的效果被送至墓地的情况下，或因战斗被破坏并被送至墓地的情况下，以“转生龙 僧娑罗”以外的自己或对手墓地的1只怪兽为对象可以发动。将该怪兽特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29146185,'魔导天士 托鲁蒙德','此卡因魔法师族怪兽或冠有“魔导书”之名的魔法卡效果特殊召唤成功时，可发动。选择我方墓地２张冠有“魔导书”之名的魔法卡加入手牌。发动此效果的回合，我方不可特殊召唤其他怪兽。以此效果将卡牌加入手牌时，可向对手展示手牌４种冠有“魔导书”之名的魔法卡并发动。破坏场上除此卡以外的所有卡牌。','返回手牌','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29155212,'鬼魂王－南瓜王－',replace(replace('①：只要场上存在“暗晦之城”，此卡的攻击力・守备力上升100。\r\n②：场上存在“暗晦之城”的情况下，在自己的准备阶段发动（从此卡和“暗晦之城”都存在起开始，直至第4次自己的准备阶段为止）。此卡的攻击力・守备力只要场上存在“暗晦之城”则上升100。','\r',char(13)),'\n',char(10)),'攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29155213,'鬼魂王－南瓜王－',replace(replace('①：只要场上存在“暗晦之城”，此卡的攻击力・守备力上升100。\r\n②：场上存在“暗晦之城”的情况下，在自己的准备阶段发动（从此卡和“暗晦之城”都存在起开始，直至第4次自己的准备阶段为止）。此卡的攻击力・守备力只要场上存在“暗晦之城”则上升100。','\r',char(13)),'\n',char(10)),'攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29157292,'钢铁幻象师',replace(replace('此卡名的①③效果１回合仅可各使用１次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将１张“钢铁化”陷阱卡放置在自己场上。自己墓地存在“钢铁化・强化反射装甲”的情况下，进而自己可抽１张。\r\n②：只要此卡存在于怪兽区域，此卡的等级在对手回合期间上升４。\r\n③：宣言１个种族可以发动。此卡直至对手回合结束时为止，变为所宣言的种族。','\r',char(13)),'\n',char(10)),'放置「钢铁化」陷阱','改变种族','是否抽牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29169993,'娱乐伙伴・跷跷板蝗虫',replace(replace('“娱乐伙伴・跷跷板蝗虫”的③效果１回合只可使用１次。\r\n①：特殊召唤而来的此卡１回合仅１次不会因战斗被破坏。\r\n②：在对手结束阶段，可以我方墓地１只等级３或以下的“娱乐伙伴”怪兽为对象发动。将此卡送入墓地，并将该怪兽加入手牌。\r\n③：在此卡存在于墓地的状态下，“娱乐伙伴”怪兽从手牌被送入我方墓地的场合可发动。从墓地特殊召唤此卡。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29172562,'钢铁巨神像','祭于机械之国的钢铁巨神像。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29177818,'玫瑰少女',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：自己场上的表侧表示的植物族怪兽被送至墓地的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：此卡存在于墓地，且场上存在植物族怪兽的情况下可以发动。将此卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29185231,'一击离脱','①：在自己・对手的战斗阶段结束时可以发动。变为此回合的结束阶段。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29189613,'芬芳园艺',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己召唤・特殊召唤“芬芳”怪兽的情况下可以发动。自己恢复１０００LP。\r\n②：自己的LP少于对手的情况下，对手怪兽攻击宣言时可以发动。从牌组将１只“芬芳”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29208536,'编号45 灭亡的预言者 库仁布尔・罗格斯',replace(replace('等级２怪兽×２只以上\r\n①：１回合１次，可移除此卡的１个超量素材，并以场上除此卡以外的１张表侧表示卡牌作为对象发动。在此怪兽以表侧表示存在的期间，对象表侧表示卡牌的效果被无效化。\r\n②：只要作为此卡的①效果的对象卡牌以表侧表示存在于场上，双方不可发动对象卡牌及其同名卡的效果。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29216198,'重力球','反转：变更对手场上的所有表侧表示怪兽的表示形式。','改变表示形式','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29216967,'机关傀偶－剪刀臂','①：此卡召唤时可以发动。从牌组将１只“机关傀偶”怪兽送至墓地。','送墓','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29223325,'古遗物动力机芯','①：以场上１张魔法・陷阱卡为对象可以发动。将该卡破坏，从牌组挑选１只“古遗物”怪兽，视为魔法卡放置在自己的魔法与陷阱区域。②：此卡因对手被破坏的情况下发动。跳过下一个对手的战斗阶段。','跳过战斗阶段','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29228350,'火龙镭射','选择我方场上装备于“三角三战机”的１张“三角炎龙”送入墓地，破坏对手场上的所有怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29228529,'魔法再生','将我方手牌中的２张魔法卡送入墓地。从我方墓地中选择１张魔法卡加入到手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29246354,'茧状体・小松茸','可解放此卡并发动。从手牌・牌组特殊召唤１只“新空间人・光辉青苔”。此效果在我方场上存在有“新宇空间”的场合可发动与处理。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29251488,'主厨・饿魔新飨',replace(replace('←0 【灵摆】 0→\r\n此卡名的①②灵摆效果1回合仅可各使用1次。\n①：在发动了此卡的回合的自己的主要阶段可以发动。从牌组将灵摆怪兽以外的1张“饿魔新飨”卡加入手牌。\n②：有怪兽被特殊召唤至对手场上的情况下可以发动。将此卡特殊召唤。\r\n【怪兽效果】\r\n此卡名的①②怪兽效果不可在同一连锁上发动。\n①：在每个自己・对手回合中1次，以场上的1只效果怪兽为对象可以发动。该怪兽的等级上升最多3。\n②：1回合1次，对手将怪兽特殊召唤的情况下，从自己手牌・牌组・墓地将1张“食谱”仪式魔法卡除外可以发动。适用该仪式魔法卡发动时的仪式召唤的效果。\n③：场上的此卡被解放并以表侧加入额外牌组的情况下可以发动。将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'检索','此卡特殊召唤','等级上升','适用效果','在灵摆区域放置','请选择要上升的等级','','','','','','','','','','');
INSERT INTO texts VALUES(29253591,'龙骑兵团－长柄大刀',replace(replace('要以此卡作为同步素材的情况下，仅可使用于“龙骑兵团”怪兽的同步召唤。\r\n①：要以场上的此卡作为同步素材的情况下，可将此卡视为等级4。\r\n②：此卡被装备中的情况下可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29265962,'同姓同名同盟罢工',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：以自己场上的1只表侧表示怪兽为对象可以发动。从自己手牌・牌组・墓地将2只原本卡名与该自己的怪兽相同的怪兽视为装备魔法卡装备于对象怪兽。只要该怪兽以此效果同时装备着2只怪兽，不可攻击，不会因战斗被破坏。此卡发动后，直至回合结束时为止自己仅可特殊召唤与对象怪兽原本种族相同的怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29267084,'暗之咒缚','①：可以对手场上１只表侧表示的怪兽为对象发动此卡。令该怪兽的攻击力下降７００，且不可进行攻击也不可变更表示形式。该怪兽离开场上时，破坏此卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29280200,'对击斗魂 狂恋博士',replace(replace('此卡名的①②效果1回合仅可各使用1次，不可在同一连锁上发动。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将1张“对击斗魂”魔法・陷阱卡加入手牌。\r\n②：在自己・对手回合中，从以下选择1个，向对手出示手牌相应属性的怪兽各1只可以发动。\r\n●暗：对手场上的1只表侧表示怪兽攻击力・守备力下降500。\r\n●暗・地：将场上的1只守备力最低的怪兽放回手牌。','\r',char(13)),'\n',char(10)),'牌组检索','展示暗属性的怪兽','展示暗·地属性的怪兽','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29280589,'锋利小鬼・镰刀','此卡名的①②效果１回合仅可各使用１次。①：在对手的主要阶段，向对手出示手牌中的此卡可以发动。从自己的手牌・场上，将包含手牌中此卡在内的、由“魔玩具”融合怪兽卡决定的融合素材怪兽送至墓地，从额外牌组将１只该融合怪兽融合召唤。②：自己场上的“魔玩具”融合怪兽将被战斗・效果破坏的情况下，可将墓地的此卡除外作为代替。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29284413,'王牌骑士',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：从牌组将“王后骑士”、“卫兵骑士”、“国王骑士”中的１只送至墓地可以发动。从手牌将此卡特殊召唤。以此效果特殊召唤的此卡直至结束阶段为止，视为送至墓地的怪兽的同名卡。\r\n②：在自己・对手的结束阶段，以自己墓地此卡以外的１只战士族・光属性怪兽为对象可以发动。将该怪兽放回牌组，将墓地的此卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29296344,'削短双枪管龙',replace(replace('包括“枪弹”怪兽在内的龙族怪兽2只\r\n此卡名的效果1回合仅可使用1次。①：舍弃1张手牌，以场上1只表侧表示怪兽为对象可以发动。将该怪兽破坏。以此效果破坏连接怪兽的情况下，进而可从自己的手牌・墓地挑选最多为该连接标记数量的“枪弹”怪兽特殊召唤（同名卡最多1张）。此效果发动后，直至回合结束时为止自己不可从额外牌组特殊召唤连接2以下的怪兽。','\r',char(13)),'\n',char(10)),'是否特殊召唤「枪弹」怪兽？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29301450,'S：P小夜骑士',replace(replace('效果怪兽2只\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡以融合・同步・超量・连接怪兽中的任一作为素材连接召唤的情况下，以自己或对手场上・墓地的1张卡为对象可以发动。将该卡除外。此回合，自己的怪兽不可直接攻击。\r\n②：对手的效果发动时，以包含自己场上的怪兽在内的、场上的2只表侧表示怪兽为对象可以发动。将该2只怪兽直至结束阶段为止除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29301451,'S：P小夜骑士',replace(replace('效果怪兽2只\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡以融合・同步・超量・连接怪兽中的任一作为素材连接召唤的情况下，以自己或对手场上・墓地的1张卡为对象可以发动。将该卡除外。此回合，自己的怪兽不可直接攻击。\r\n②：对手的效果发动时，以包含自己场上的怪兽在内的、场上的2只表侧表示怪兽为对象可以发动。将该2只怪兽直至结束阶段为止除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29302858,'对击斗魂 螺旋',replace(replace('此卡名的①②效果1回合仅可各使用1次，不可在同一连锁上发动。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将1只战士族以外的“对击斗魂”怪兽加入手牌。\r\n②：在自己・对手回合中，从以下选择1个，向对手出示手牌相应属性的怪兽各1只可以发动。\r\n●炎：此回合，此卡不会因效果被破坏。\r\n●炎・暗：将与此卡同一纵列的其他怪兽全部破坏。','\r',char(13)),'\n',char(10)),'牌组检索','展示炎属性的怪兽','展示炎·暗属性的怪兽','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29302859,'对击斗魂 螺旋',replace(replace('此卡名的①②效果1回合仅可各使用1次，不可在同一连锁上发动。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将1只战士族以外的“对击斗魂”怪兽加入手牌。\r\n②：在自己・对手回合中，从以下选择1个，向对手出示手牌相应属性的怪兽各1只可以发动。\r\n●炎：此回合，此卡不会因效果被破坏。\r\n●炎・暗：将与此卡同一纵列的其他怪兽全部破坏。','\r',char(13)),'\n',char(10)),'牌组检索','展示炎属性的怪兽','展示炎·暗属性的怪兽','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29303524,'眩月龙 塞勒桂莱尔',replace(replace('此卡名的③效果1回合仅可使用1次。\r\n①：此卡无需解放即可通常召唤。\r\n②：以此卡的①方法通常召唤的此卡的原本攻击力变为1500。\r\n③：在自己・对手的主要阶段，以对手场上的1只攻击力在此卡的攻击力以下的怪兽为对象可以发动。将场上的此卡放回手牌，直至结束阶段为止获得对象怪兽的控制权。','\r',char(13)),'\n',char(10)),'不用解放作通常召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29307554,'破坏神的族谱','在我方破坏对手场上守备表示怪兽回合，可选择我方场上１只等级８的怪兽并发动。此回合，被选择的怪兽在１次的战斗阶段中可攻击２次。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29311166,'强袭翼龙','①：此卡因战斗破坏对手怪兽时，可解放此卡并发动。从我方的手牌・墓地挑选１只除“强袭翼龙”以外的龙族怪兽并特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29325276,'异色眼阳焰龙',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：此卡特殊召唤的情况下可以发动。从自己额外牌组（表侧）将1只灵摆怪兽特殊召唤。只要以此效果特殊召唤的怪兽以表侧表示存在于自己场上，自己仅可特殊召唤灵摆怪兽。\r\n②：此卡存在于墓地的情况下，从自己墓地将2只其他的融合・同步・超量・灵摆怪兽除外可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'从额外牌组特殊召唤','此卡特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29330706,'武装神龙 护甲龙','①：此卡的攻击力上升相当于装备于此卡的装备卡数量×５００的数值。②：只要此卡存在于怪兽区域，自己场上的表侧表示装备卡不会因效果被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29343734,'元素－英雄 万灵贤侠',replace(replace('“元素-英雄 羽毛人”＋“元素-英雄 爆炎女郎”＋“元素-英雄 黏土人”＋“元素-英雄 泡沫人”\r\n此卡仅可以融合召唤特殊召唤。①：此卡的属性也视为“风”、“水”、“炎”、“地”。②：此卡融合召唤成功的情况下发动。将双方被除外的卡全部放回持有者的牌组。③：此卡的攻击力上升相当于对手场上拥有与此卡相同属性的怪兽数量×300的数值。','\r',char(13)),'\n',char(10)),'返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29348048,'仇尸・殇痕食腐者','以“仇尸”仪式魔法卡降临。此卡名的①②效果１回合仅可各使用１次。①：在双方的主要阶段，解放自己场上的１只不死族怪兽可以发动。此卡的攻击力直至回合结束时为止，上升相当于所解放怪兽原本攻击力的数值。②：此卡存在于墓地，自己场上存在“复仇尸者・屠戮者”的情况下可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29353756,'ZEXAL兵器－荒鹫激神爪','①：“ZEXAL兵器－荒鹫激神爪”在自己场上仅可有１张以表侧表示形式存在。②：自己的LP比对手少２０００以上的情况下，此卡可从手牌中特殊召唤。③：以自己场上的１只“希望皇霍普”怪兽为对象可以发动。将自己场上的此卡视为攻击力上升２０００的装备卡，装备于该自己的“希望皇霍普”怪兽。④：此卡被装备中的情况下，１回合１次，将对手场上发动的陷阱卡的效果无效。','变成装备','效果无效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29354228,'教导邂逅',replace(replace('此卡名的卡１回合仅可发动１张。①：可从以下效果中选择１个发动。\r\n●从手牌将１只“教导”怪兽或“阿尔白斯之落胤”特殊召唤。\r\n●从自己的墓地挑选１只“教导”怪兽或“阿尔白斯之落胤”，加入手牌或特殊召唤。','\r',char(13)),'\n',char(10)),'从手牌特殊召唤','从墓地加入手牌或特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29357687,'咒眼之女王 戈耳戈涅',replace(replace('包含“咒眼”怪兽的怪兽２只\r\n此卡名的②效果１回合仅可使用１次。\r\n①：此卡的攻击力上升相当于自己墓地“咒眼”卡种类×１００的数值。\r\n②：此卡装备了“塞勒涅的咒眼”的情况下，以对手场上的１只效果怪兽为对象可以发动。将该怪兽的效果直至回合结束时为止无效。此效果在对手回合中也可以发动。\r\n③：发动过此卡的②效果的情况下，将在下一个准备阶段发动。挑选此卡连接端的１只怪兽破坏。','\r',char(13)),'\n',char(10)),'对手怪兽效果无效','此卡所连接区1只怪兽破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29357956,'剑斗兽 尼禄基乌斯',replace(replace('“剑斗兽”怪兽×３\r\n此卡从额外牌组仅可在将自己场上的上述卡放回牌组・额外牌组的情况下特殊召唤。\r\n①：此卡不会因战斗被破坏，此卡进行战斗的情况下，对手直至伤害步骤结束时为止，不可发动魔法・陷阱・怪兽的效果。\r\n②：此卡进行过战斗的战斗阶段结束时，将此卡放回额外牌组可以发动。从牌组将２只“剑斗兽”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29369059,'黯蜜☆惊喜',replace(replace('①：可从以下选择1个发动（此卡名的以下效果1回合仅可各选择1次）。\r\n●以自己场上的2只兽族・光属性怪兽和对手场上的2张卡为对象可以发动。将该卡放回手牌。\r\n●从自己手牌・墓地将1只“黯蜜”怪兽特殊召唤。该怪兽此回合不可直接攻击。\r\n●从自己场上（表侧表示）・墓地将1张场地魔法卡放回手牌。然后，可从手牌将1张“黯蜜”场地魔法卡以表侧表示放在自己场上。','\r',char(13)),'\n',char(10)),'发动','双方的卡回到手牌','特殊召唤','场地回到手牌','是否把场地表侧表示放置？','','','','','','','','','','','');
INSERT INTO texts VALUES(29374928,'装甲比特创机',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：解放此卡可以发动。从牌组将“装甲比特创机”以外的１只电子界族怪兽的效果无效并特殊召唤。此回合，自己仅可特殊召唤电子界族怪兽。\r\n②：此卡存在于墓地的状态下，自己场上的连接３以上的连接怪兽因战斗或对手的效果被破坏的情况下可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29380133,'寄居龙','此卡从攻击表示变成表侧守备表示时可发动。将任意数量的我方手牌返回至牌组最下方。','返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29389368,'体力增强剂 超级Z','①：我方受到２０００或以上的战斗伤害的场合，计算该伤害时可发动。我方回复４０００LP。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29400787,'鬼计游行','①：只要此卡存在于场地区域，双方的怪兽不可攻击里侧守备表示怪兽，对手场上的怪兽仅有里侧守备表示怪兽的情况下，可直接攻击对手。②：对手怪兽的直接攻击宣言时可以发动。从牌组将１张“鬼计”卡加入手牌。③：只要此卡存在于场地区域，对手将受到的所有伤害变为０。','加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29401950,'奈落的落穴','①：对手将攻击力1500以上的怪兽召唤・反转召唤・特殊召唤时可以发动。将该攻击力1500以上的怪兽破坏并除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29402771,'彩虹人鱼','稀有的人鱼，当天空出现巨大的彩虹桥时就会出现。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29415459,'黄华之机界骑士','此卡名以①方法的特殊召唤1回合仅可进行1次。①：同一纵列有2张以上的卡存在的情况下，可将此卡特殊召唤至该纵列的自己场上。②：从自己的墓地将1只“机界骑士”怪兽除外，以1张与此卡同一纵列的魔法・陷阱卡为对象可以发动。将该卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29417188,'念动力阻挡者',replace(replace('①：1回合1次，宣言1个卡名可以发动。直至对手回合结束时为止，原本卡名与宣言的卡名相同的、双方的卡适用以下内容。\r\n●不可出到场上。\r\n●不可将卡发动及将效果发动和适用。\r\n●不可通常召唤・反转召唤・特殊召唤。\r\n●不可攻击及变更表示形式。\r\n●不可作为用于需要素材的特殊召唤的素材。','\r',char(13)),'\n',char(10)),'宣言禁止','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29423048,'狱焰班西',replace(replace('等级4怪兽×2\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：去除此卡的1个超量素材可以发动。从牌组挑选1只炎族怪兽，加入手牌或送至墓地。\r\n②：此卡被除外的情况下，如果自己场上存在炎族怪兽则可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡的攻击力直至回合结束时为止，上升自己除外状态的怪兽数量×100的数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29424328,'魔王迪亚波罗斯','此卡不可特殊召唤。上级召唤此卡的场合，解放怪兽必须为暗属性怪兽。在对手抽牌阶段抽牌前发动。确认对手牌组最上方的卡牌并将其返回至牌组的最上方或最下方。此外，此卡只要以表侧表示存在于场上，不可以卡牌效果解放。','确认牌组','返回牌组最上面','返回牌组最下面','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29432356,'源质之神星龙',replace(replace('←5 【灵摆】 5→\r\n“源质之神星龙”的灵摆效果１回合仅可使用１次。\n①：在自己的主要阶段可以发动。从牌组挑选１只“源质”灵摆怪兽，以表侧表示加入自己的额外牌组，将此卡的灵摆刻度直至回合结束时为止，改成与该灵摆怪兽的灵摆刻度相同。\r\n【怪兽效果】\r\n此卡不可通常召唤。\n仅在此卡以表侧表示存在于额外牌组、将自己场上包含３只以上“源质”怪兽的怪兽全部解放的情况下可以特殊召唤。\n①：此卡特殊召唤成功的余下本回合，自己在通常的灵摆召唤之外仅可追加１次，在自己的主要阶段将“源质”怪兽灵摆召唤。\n②：１回合１次，解放自己场上的１只怪兽可以发动。从牌组将１只“源质”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'「源质」灵摆怪兽加入自己的额外牌组','请选择要加入自己的额外牌组的卡','使用「源质之神星龙」的效果灵摆召唤','从牌组把1只「源质」怪兽特殊召唤','','','','','','','','','','','','');
INSERT INTO texts VALUES(29432790,'青之眼的激临','发动此卡的回合中，自己仅可召唤・特殊召唤“青眼白龙”。①：包括此卡在内，将自己手牌・场上・墓地的卡全部以里侧表示除外，从牌组将最多3只“青眼白龙”特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29436665,'黑之执行官',replace(replace('此卡不可通常召唤。\r\n仅可在解放自己场上的1只“黑魔导”的情况下特殊召唤。\r\n①：只要此卡存在于怪兽区域，每当自己或对手发动通常魔法卡，就给予对手1000伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29439831,'瞳之魔女 摩尔嘉娜',replace(replace('此卡名在规则上也视为“绿柱魔瞳”卡。\r\n此卡名的①③效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将1张“绿柱魔瞳”魔法卡加入手牌。\r\n②：对手怪兽攻击宣言时，从自己墓地将1张“绿柱魔瞳”魔法卡除外可以发动。将该攻击无效。\r\n③：自己墓地・除外状态的“绿柱魔瞳”魔法卡为3种以上的情况下可以发动。对手场上的所有怪兽的攻击力变为0。','\r',char(13)),'\n',char(10)),'检索','攻击无效','攻击力变成0','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29455728,'双头光子蜥蜴',replace(replace('“光子”怪兽×２\r\n①：解放此卡可以发动。将一组使用于所解放的此卡的融合召唤的融合素材怪兽从自己的墓地特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29477860,'螺旋炮击','此卡名的②效果１回合仅可使用１次。①：只要自己的怪兽区域有“龙骑士盖亚”存在，对手仅可将“龙骑士盖亚”选择为攻击对象。②：自己的“龙骑士盖亚”进行战斗的攻击宣言时，以场上的１张卡为对象可以发动。将该卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29479265,'破械双王神 来迎',replace(replace('包含连接怪兽在内的怪兽2只以上\r\n此卡名的①②③效果1回合仅可各使用1次。\r\n①：场上的其他卡因“破械双王神 来迎”以外的卡的效果被破坏的情况下，以场上的1张卡为对象可以发动。将该卡破坏。\r\n②：其他怪兽因战斗被破坏时，以场上的1张卡为对象可以发动。将该卡破坏。\r\n③：在自己・对手的结束阶段，以场上的1张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29479266,'破械双王神 来迎',replace(replace('包含连接怪兽在内的怪兽2只以上\r\n此卡名的①②③效果1回合仅可各使用1次。\r\n①：场上的其他卡因“破械双王神 来迎”以外的卡的效果被破坏的情况下，以场上的1张卡为对象可以发动。将该卡破坏。\r\n②：其他怪兽因战斗被破坏时，以场上的1张卡为对象可以发动。将该卡破坏。\r\n③：在自己・对手的结束阶段，以场上的1张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29491031,'美杜莎的亡灵','拥有毒蛇头的怪兽。若与其相视，便会变为石头。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29491334,'星际仙踪－犬战机',replace(replace('①：在自己・对手的准备阶段可以发动。将１只“犬战机衍生物”（机械族・暗・星６・攻２０００／守２４００）特殊召唤至自己场上。\r\n②：此卡因战斗・效果被破坏并被送至墓地的情况下，将墓地的此卡除外可以发动。从牌组将１只等级５以下的“星际仙踪”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤衍生物','从牌组把「星际仙踪」怪兽特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29491335,'犬战机衍生物','由「星际仙踪－犬战机」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29508346,'对手碰对头','此卡名的卡1回合仅可发动1张。①：自己・对手的战斗阶段可以发动。召唤1只怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29508347,'对手碰对头','此卡名的卡1回合仅可发动1张。①：自己・对手的战斗阶段可以发动。召唤1只怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29510428,'召煌女 奎因克丽',replace(replace('等级5怪兽×2\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：去除此卡的1个超量素材，以自己或对手墓地的1只等级5怪兽为对象可以发动。将该怪兽特殊召唤至自己或对手场上。\r\n②：此卡存在于怪兽区域的状态下，自己场上的表侧表示的等级5怪兽因对手的效果从场上离开的情况下，或因战斗被破坏的情况下可以发动。从牌组挑选1只等级5怪兽，加入手牌或特殊召唤。','\r',char(13)),'\n',char(10)),'','在自己场上特殊召唤','在对手场上特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29515122,'重机王・土木札克',replace(replace('等级５怪兽×３\r\n１回合１次，可移除此卡的１个超量素材并发动。从对手牌组的上方将３张卡牌送入墓地。以此效果送入墓地的卡牌中有怪兽卡的场合，破坏对手场上最多该数量的卡牌。','\r',char(13)),'\n',char(10)),'牌组送墓','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29537493,'北斗天熊－小白熊','此卡名的①②效果1回合仅可各使用1次。①：在自己・对手的主要阶段，从手牌解放此卡以外的1只等级7以上的怪兽可以发动。从手牌将此卡特殊召唤。此效果发动后，直至回合结束时为止，自己仅可特殊召唤拥有等级的怪兽。②：此卡特殊召唤成功的情况下可以发动。从牌组将1只“北斗天熊-小白熊”以外的“北斗天熊”怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29549364,'活祭品封印之假面','①：只要此卡存在于魔法与陷阱区域，双方不可解放卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29552709,'大薰风・风球术者',replace(replace('协调＋１只以上协调以外的“薰风”怪兽\r\n此卡同步召唤成功时可以发动。选择自己墓地的１张“薰风”卡加入手牌。只要此卡以表侧表示存在于场上，因自己场上的“薰风”怪兽的战斗产生的对自己的战斗伤害由对手代替承受。此外，此卡不会因战斗被破坏。','\r',char(13)),'\n',char(10)),'返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29570824,'纠罪巧ϝ’－恐怖“tromarIA”',replace(replace('←0 【灵摆】 0→\r\n此卡名的②灵摆效果1回合仅可使用1次。\n①：每当有怪兽反转，就在此卡上放1个纠罪计数物。\n②：支付900LP可以发动。从牌组将3张“纠罪巧”卡出示给对手，对手从其中随机挑选1张。将该1张加入自己手牌，剩余的放回牌组。\r\n【怪兽效果】\r\n①：向对手出示手牌的此卡可以发动（发动此效果的回合中，自己仅可以里侧守备表示特殊召唤怪兽）。从手牌将1只怪兽以里侧守备表示特殊召唤。\n②：对手发动包含将怪兽特殊召唤的效果的、卡的效果时，将里侧表示的此卡改成表侧守备表示可以发动。从牌组将1张“纠罪巧”卡加入手牌。\n③：此卡反转的情况下发动。将对手场上的1只效果怪兽的效果直至回合结束时为止无效。','\r',char(13)),'\n',char(10)),'检索','特殊召唤','检索','无效','','','','','','','','','','','','');
INSERT INTO texts VALUES(29587993,'霞之谷的巨神鸟','此卡的效果在同一连锁上仅可发动１次。①：魔法・陷阱・怪兽的效果发动时，以自己场上的１张“霞之谷”卡为对象可以发动。将自己的该“霞之谷”卡放回持有者的手牌，将该发动无效并破坏。','效果发动无效并破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29590752,'剑斗兽奥库达比乌斯','此卡因冠有“剑斗兽”之名的怪兽效果特殊召唤成功时，选择被盖牌在魔法与陷阱区域的１张卡牌破坏。此卡进行了战斗的我方战斗阶段结束时，舍弃１张手牌或将此卡返回至持有者牌组。','破坏','丢手牌或回牌组','丢弃一张手牌吗？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29590905,'超级少年对决！','对手怪兽的攻击宣言时可发动。使该攻击无效，以对手场上１只攻击力最低的攻击表示怪兽和我方场上１只守备力最低的守备表示怪兽来进行战斗的伤害计算。该战斗结束后，结束战斗阶段。','请选择攻击力最低的1只怪兽','请选择守备力最低的1只怪兽','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29595202,'神碑之诱骗','①：“神碑之诱骗”在自己场上仅可有１张以表侧表示形式存在。②：自己或对手每次发动速攻魔法卡则发动。从对手的牌组上面将１张卡除外。','对方卡组1张卡除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29596581,'兽雷龙','此卡名的①②效果1回合1次，仅可使用其中1个。①：将此卡从手牌中舍弃可以发动。从自己墓地的卡及自己被除外的卡中，挑选“兽雷龙”以外的1张“雷龙”卡加入手牌。②：此卡被除外的情况下或从场上被送至墓地的情况下可以发动。从牌组将1只“雷龙”怪兽以守备表示特殊召唤。以此效果特殊召唤的怪兽于结束阶段放回持有者的手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29599813,'皮尔莉・漂亮回忆','①：双方恢复１０００LP。进而可适用以下效果。●挑选１张自己的手牌舍弃，从牌组将１只等级１的“皮尔莉”怪兽特殊召唤。②：持有此卡作为素材的“皮尔莉”超量怪兽获得以下效果。●１回合１次，将自己场上此卡以外的１张卡送至墓地，以对手场上的１张卡为对象可以发动。将该卡重叠在此卡下方作为超量素材。','是否从牌组特殊召唤？','补充超量素材（皮尔莉可爱回忆）','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29599814,'皮尔莉・漂亮回忆','①：双方恢复１０００LP。进而可适用以下效果。●挑选１张自己的手牌舍弃，从牌组将１只等级１的“皮尔莉”怪兽特殊召唤。②：持有此卡作为素材的“皮尔莉”超量怪兽获得以下效果。●１回合１次，将自己场上此卡以外的１张卡送至墓地，以对手场上的１张卡为对象可以发动。将该卡重叠在此卡下方作为超量素材。','是否从牌组特殊召唤？','补充超量素材（皮尔莉可爱回忆）','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29601381,'守宝团・舰长 飒嘉斯',replace(replace('此卡名的①②效果１回合仅可各使用１次。①：此卡存在于手牌・场上・墓地的情况下，以自己场上的１只“守宝团”超量怪兽为对象可以发动。将此卡重叠在该怪兽下方作为超量素材。②：在对手回合中，去除自己场上的１个超量素材，以场上的１张表侧表示卡为对象可以发动。将该卡破坏。③：持有此卡作为素材的“守宝团”超量怪兽获得以下效果。\r\n●此卡的攻击力上升５００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29603180,'灾害恶魔',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：以自己及对手场上的各1张卡为对象可以发动。将该卡破坏。以此效果破坏了表侧表示的恶魔族怪兽的情况下，此卡的攻击力直至回合结束时为止上升相当于该怪兽原本攻击力的合计数值的一半。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29612557,'旋风回力标','仅限装备“元素－英雄 狂野人”。装备怪兽的攻击力上升５００点。装备怪兽因卡牌效果被破坏并送入墓地时，将场上所有的魔法、陷阱卡破坏，并给予对手生命相当于被破坏卡牌数量×１００点伤害。','破坏并伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29616929,'虫惑落穴','①：对手场上在此回合被特殊召唤的怪兽发动效果时可以发动。将其效果无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29616941,'美丽魔物使','罕见的女性魔物使。手拿鞭子的时候，个性丕变。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29618570,'灰翼','在主要阶段１中，从手牌舍弃１张卡牌。此卡在该回合的战斗阶段中可以进行２次攻击。','两次攻击','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29628180,'魔弹－亡者爆击',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：自己场上存在“魔弹”怪兽的情况下，对手发动魔法・陷阱卡时可以发动。将该发动无效并破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29649320,'反射镜力启动','①：1回合1次，在自己的主要阶段从手牌扔掉1只怪兽可以发动。从自己的牌组・墓地挑选1张“神圣防护罩-反射镜力-”加入手牌。②：被放置的此卡被对手的效果破坏送至墓地的情况下可以发动。挑选墓地的此卡和自己手牌・牌组・墓地的1张“神圣防护罩-反射镜力-”，将该卡和此卡放置在自己场上。以此效果放置的卡在放置的回合中也可以发动。','适用「反射镜力启动」的效果来发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29650040,'音服和弦・和音',replace(replace('①：可从以下效果中选择1个发动。“音服和弦・和音”的以下效果1回合仅可各选择1次。\r\n●从自己的额外牌组将1只表侧表示的“音服和弦”灵摆怪兽加入手牌。\r\n●挑选自己灵摆区域的1张“音服和弦”卡。此回合，该灵摆刻度上升相当于该卡等级的数值。\r\n●自己场上的“音服和弦”灵摆怪兽卡的灵摆刻度为奇数3种以上或偶数3种以上的情况下，挑选对手场上的1张卡破坏。','\r',char(13)),'\n',char(10)),'额外牌组加入手牌','灵摆刻度上升','对手场上1张卡破坏','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29654737,'亚马逊的锁链使','①：此卡因战斗而被破坏送入墓地时，可支付１５００LP来发动此卡。确认对手手牌，将其中１只怪兽卡加入到我方的手牌。','手牌夺取','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29666221,'自鸣天琴・起音','①：自己或对手的怪兽攻击宣言时，解放自己场上的1只“自鸣天琴”怪兽或“星遗物”怪兽，以对手场上的1只怪兽为对象可以发动。将该怪兽除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29669359,'编号61 火山恐龙',replace(replace('等级5怪兽×2\r\n①：1回合1次，去除此卡的1个超量素材，以对手场上的1只表侧表示怪兽为对象可以发动（发动此效果的回合中，此卡不可直接攻击）。将该对手怪兽破坏，给予对手相当于其原本攻击力数值的伤害。','\r',char(13)),'\n',char(10)),'破坏和伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29687169,'魔装战士 阿尔尼斯','①：此卡因对手怪兽的攻击被破坏并送至墓地时可以发动。从牌组将1只攻击力1500以下的魔法师族怪兽以攻击表示特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29692206,'双尾怪','挥舞着两根像鞭子一般的尾巴攻击的水中生物。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29716911,'电容金蝎',replace(replace('此卡牌名的②效果１回合只可使用１次。\r\n①：此卡召唤成功时，可以我方场上除此卡以外的１只电子界族怪兽为对象发动。此怪兽以表侧表示存在期间，该怪兽的攻击力上升８００。\r\n②：怪兽区的此卡因效果被破坏并送入墓地的场合发动。双方玩家受到８００伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29719112,'电子灯塔','此卡名的③效果1回合仅可使用1次。①：此卡可解放自己场上的1只机械族怪兽从手牌特殊召唤。②：1回合1次，在自己主要阶段可以发动。从自己的手牌・场上，将由机械族融合怪兽卡决定的融合素材怪兽送至墓地，从额外牌组将1只该融合怪兽融合召唤。③：自己的融合怪兽因战斗被破坏时，将墓地的此卡除外可以发动。从牌组将1张“力量焊接”加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29724053,'召唤之门','①：只要此卡存在于魔法与陷阱区域，双方在１回合中各自最多只可从额外牌组特殊召唤３只怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29726552,'粘丝坏兽 蛛默鼓丝',replace(replace('①：此卡可以解放对手场上１只怪兽，以攻击表示从手牌特殊召唤至对手场上。\r\n②：对手场上存在“坏兽”怪兽的情况下，此卡可以从手牌以攻击表示特殊召唤。\r\n③：“坏兽”怪兽在自己场上仅可有１只以表侧表示存在。\r\n④：对手召唤・特殊召唤怪兽时，去除自己・对手场上的２个坏兽计数物可以发动。直至下个回合结束时为止，该怪兽不可攻击，效果无效化。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29735721,'咒术抹消','魔法卡发动时，可舍弃２张手牌并发动。使该发动无效并破坏。之后，确认对手手牌和牌组，有与被破坏魔法卡同名卡牌的场合，全部送入墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29762407,'王家的神殿',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：自己可将1张陷阱卡在放置的回合发动。\r\n②：将自己场上的1只表侧表示的“圣兽 塞尔凯特”和此卡送至墓地可以发动。将手牌・牌组的1只怪兽或额外牌组的1只融合怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','适用「王家的神殿」的效果来发动','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29765339,'电力七头兽',replace(replace('“电力”协调＋协调以外的雷族怪兽１只以上\r\n①：此卡可直接攻击。\r\n②：此卡以直接攻击给予对手战斗伤害的情况下发动。从牌组挑选１张卡除外。在发动后自己第２次准备阶段，将以此效果除外的卡加入手牌。','\r',char(13)),'\n',char(10)),'除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29792472,'百臂无形招引手',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：自己场上存在“百臂无形”怪兽，且对手发动魔法・陷阱卡时可以发动。将该发动无效并破坏。然后，可将所破坏的魔法・陷阱卡放置在自己场上。','\r',char(13)),'\n',char(10)),'','是否放置？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29795530,'妖怪的恶作剧',replace(replace('①：场上的所有怪兽的等级直至回合结束时为止下降2。\r\n②：从墓地将不是在此回合被送至墓地的此卡除外，以场上的1只表侧表示怪兽为对象可以发动。该怪兽的等级直至回合结束时为止下降1。','\r',char(13)),'\n',char(10)),'等级下降','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29802344,'蛇椰树','大量蛇聚集拟态而成。一旦靠近，便会分解开来发动袭击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29826127,'来自暗黑的军势','从我方墓地选择２只冠有“暗黑界”之名的怪兽返回手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29834183,'灰篮鹰',replace(replace('①：自己怪兽区域的此卡因战斗或怪兽的效果被破坏并被送至墓地的情况下，以对手场上的１只表侧表示怪兽为对象可以发动。将此卡视为装备卡，装备于该对手怪兽。\r\n②：此卡以此卡的效果被装备中的情况下，获得装备怪兽的控制权。此卡离开场上时，装备怪兽将被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29838323,'水晶机巧－紫晶翼龙',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：以自己场上的1张表侧表示卡为对象可以发动。将该卡破坏，从牌组将1只“水晶机巧”协调特殊召唤。此效果发动后，直至回合结束时为止自己从额外牌组仅可特殊召唤机械族同步怪兽。\r\n②：将墓地的此卡除外可以发动。从牌组将“水晶机巧－紫晶翼龙”以外的1只“水晶机巧”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29843091,'扰乱怪三人组','①：以守备表示特殊召唤３只“扰乱怪衍生物”（兽族・光・星２・攻０／守１０００）至对手场上。此衍生物不可进行以上级召唤为目的的解放。“扰乱怪衍生物”被破坏时，每破坏１只该控制者受到３００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29843092,'扰乱怪衍生物','由「扰乱怪三人组」的效果特殊召唤。这个衍生物不能用于上级召唤的解放。这个衍生物破坏时，这个衍生物的控制者受到300点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29843093,'扰乱怪衍生物','由「扰乱怪三人组」的效果特殊召唤。这个衍生物不能用于上级召唤的解放。这个衍生物破坏时，这个衍生物的控制者受到300点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29843094,'扰乱怪衍生物','由「扰乱怪三人组」的效果特殊召唤。这个衍生物不能用于上级召唤的解放。这个衍生物破坏时，这个衍生物的控制者受到300点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29843095,'扰乱怪三人组','①：以守备表示特殊召唤３只“扰乱怪衍生物”（兽族・光・星２・攻０／守１０００）至对手场上。此衍生物不可进行以上级召唤为目的的解放。“扰乱怪衍生物”被破坏时，每破坏１只该控制者受到３００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29863101,'爆裂瞬移','①：从手牌将1只“／爆裂”怪兽放回牌组可以发动。自己抽2张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29867611,'惊乐游乐设施 宏伟旋转木马',replace(replace('①：以自己场上的１只“惊乐园”怪兽或对手场上的表侧表示怪兽为对象可以发动此卡。将此卡视为装备卡，装备于该怪兽。\r\n②：根据装备怪兽的控制者，适用以下效果。\r\n●自己：装备怪兽的攻击力上升５００。装备怪兽将被战斗・效果破坏的情况下，可将此卡送至墓地作为代替。\r\n●对手：装备怪兽的攻击力下降相当于装备于怪兽的自己的“游乐设施”陷阱卡数量×５００的数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29876299,'巨石异物・再生',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：舍弃1张手牌可以发动。从牌组将等级4以下与8以上的“巨石异物”怪兽各1只加入手牌。\r\n②：1回合1次，自己将“巨石异物”怪兽仪式召唤的情况下，可从以下效果中选择1个发动（此卡名的以下效果1回合仅可各选择1次）。\r\n●自己抽2张。然后，挑选自己的1张手牌舍弃。\r\n●将对手场上1只怪兽解放。','\r',char(13)),'\n',char(10)),'检索效果','抽牌','解放','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29876529,'暗之闪光','可释放我方场上１只攻击力１５００或以上的暗属性怪兽并发动。破坏在该回合被特殊召唤的所有怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29882827,'龙华界辟',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：从牌组将１只“龙华”怪兽加入手牌。然后，可从手牌将１只“龙华”灵摆怪兽以表侧加入额外牌组。\r\n②：自己场上存在“龙华”灵摆怪兽卡的情况下，在自己的主要阶段，从自己墓地将１只“龙华”怪兽和此卡除外可以发动。从牌组将１只原本的种族与除外的怪兽相同的“龙华”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'检索后灵摆卡加入额外牌组','从牌组特殊召唤','是否加入额外牌组？','请选择要加入额外牌组的卡','','','','','','','','','','','','');
INSERT INTO texts VALUES(29884951,'相剑瑞兽－纯钧','此卡名的①③效果１回合仅可各使用１次。①：在自己・对手的主要阶段，解放自己场上的１只怪兽可以发动。从手牌将此卡特殊召唤。②：自己的幻龙族怪兽与从额外牌组被特殊召唤的对手怪兽进行战斗的伤害计算前可以发动。将该对手怪兽和此卡破坏。③：此卡作为同步素材被送至墓地的情况下，以自己或对手场上・墓地的１张卡为对象可以发动。将该卡除外。','','','','以场上的卡为对象发动','以墓地的卡为对象发动','','','','','','','','','','','');
INSERT INTO texts VALUES(29888389,'暗影・咒仪','①：仪式召唤１只水属性仪式怪兽的情况下，使用１张此卡即可作为仪式召唤所必需的解放。②：从手牌舍弃此卡可以发动。从牌组将１张“咒仪”仪式魔法卡加入手牌。','仪式魔法卡加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29904964,'觉醒暗黑骑士盖亚','此卡名的②效果１回合仅可使用１次。①：对手场上怪兽的数量比自己场上的怪兽多的情况下，此卡无需解放即可召唤。②：此卡被解放的情况下可以发动。从自己的手牌・墓地挑选１只“混沌士兵”怪兽特殊召唤。③：进行“混沌士兵”怪兽的仪式召唤的情况下，可将墓地的此卡除外来作为所需等级数值的怪兽中的１只。','不用解放作召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29905795,'魔轰神兽吉娃','①：此卡存在于手牌的情况下可以发动。从手牌挑选1只“魔轰神”怪兽舍弃，将此卡特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29913783,'对坏兽用决战兵器 机械雷霆王','此卡名④的效果在决斗中仅可使用1次。①：在双方的主要阶段从手牌将此卡舍弃可以发动。挑选1只自己场上的、原本的持有者为对手的“坏兽”怪兽除外。然后可从自己的墓地挑选1只怪兽特殊召唤。②：“坏兽”怪兽在自己场上仅可有1只以表侧表示形式存在。③：场上的此卡不受其他“坏兽”卡的效果影响，不会因与“坏兽”怪兽的战斗被破坏。④：在自己的结束阶段可以发动。从墓地将此卡特殊召唤。','除外坏兽并苏生','此卡特殊召唤','是否从墓地特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29925614,'混沌的魅惑女王',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：从手牌将１只其他的光・暗属性怪兽舍弃可以发动。从手牌将此卡特殊召唤。\r\n②：以自己或对手墓地的１只怪兽为对象可以发动。将该怪兽视为装备魔法卡，装备于此卡。此卡直至结束阶段为止，视为以此效果装备的怪兽的同名卡。以此效果装备了光・暗属性的怪兽卡的情况下，进而可从自己牌组・墓地将１只暗属性的“魅惑女王”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','装备','是否再把怪兽特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29927283,'新世龙 达尼安',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：此卡以怪兽的效果特殊召唤的情况下可以发动。从牌组将1只“GMX”怪兽加入手牌。\r\n②：在自己的主要阶段可以发动。将自己手牌・场上的怪兽作为融合素材，将1只恐龙族融合怪兽融合召唤。\r\n③：此卡被送至墓地的情况下可以发动。自己场上的所有恐龙族怪兽的攻击力上升400。','\r',char(13)),'\n',char(10)),'检索','融合召唤','攻击力上升','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29929832,'海兽鱼','“水之魔导师”＋“大肚海蛇”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29934351,'地缚波','我方场上存在有冠有“地缚神”之名的怪兽，且对手发动魔法、陷阱卡时可发动。使该发动无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29942771,'大植然山茶花','此卡名的①②③效果１回合仅可各使用１次。①：此卡召唤・特殊召唤成功的情况下可以发动。从牌组将１张“大植然”卡送至墓地。②：只要此卡存在于怪兽区域，自己为发动“大植然”怪兽的效果而要解放怪兽的情况下，作为代替可从自己的牌组上面将２张卡送至墓地。③：对手将怪兽召唤・特殊召唤成功的情况下可以发动。从自己的墓地挑选１只“大植然”怪兽特殊召唤。','牌组「大植然」卡送至墓地','是否使用「大植然山茶」的效果代替解放？','墓地「大植然」怪兽特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29947751,'变形斗士・U型磁铁',replace(replace('此卡依据此卡的表示形式获得以下效果。\r\n●攻击表示：对手场上存在有表侧表示怪兽的场合，此卡只可选择攻击力最高的怪兽作为攻击对象。\r\n●守备表示：对手不可选择其他怪兽作为攻击对象。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29948294,'烙印之气炎',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：向对手出示手牌的1只怪兽，从额外牌组将1只和该怪兽相同种族、攻击力或守备力为2500的等级8融合怪兽送至墓地。然后，可适用以下效果。\r\n●将所出示的怪兽舍弃，从牌组将1只“阿尔白斯之落胤”或记载有该卡名的怪兽加入手牌。\r\n②：此回合有融合怪兽被送至自己墓地的情况下，在结束阶段可以发动。将墓地的此卡加入手牌。','\r',char(13)),'\n',char(10)),'','','是否丢弃观看的怪兽，并把卡加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29948642,'鸟嘴兽','卷起蛇一样长的身体，一边回转一边用嘴攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29951323,'放电枪野马',replace(replace('此卡不可通常召唤，仅可在自己没有进行过特殊召唤的自己的主要阶段1，以卡的效果特殊召唤。\r\n①：此卡1回合最多2次不会因战斗被破坏。\r\n②：只要此卡存在于怪兽区域，回合玩家可特殊召唤怪兽的次数最多为该回合攻击过的次数。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29975188,'电子龙四代','此卡名的②效果1回合仅可使用1次。①：此卡只要存在于场上・墓地，卡名视为“电子龙”。②：自己召唤・特殊召唤“电子龙”成功的情况下可以发动。将此卡从手牌以守备表示特殊召唤。③：只要此卡存在于怪兽区域，自己场上的所有“电子龙”的攻击力・守备力上升500。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29981921,'真六武众－紫焰',replace(replace('战士族协调＋协调以外的“六武众”怪兽１只以上\r\n①：１回合１次，对手发动魔法・陷阱卡时可以发动。将该发动无效并破坏。\r\n②：场上的此卡将被战斗・效果破坏的情况下，作为代替可将自己场上的１只“六武众”怪兽破坏。','\r',char(13)),'\n',char(10)),'魔法陷阱发动无效并破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29981922,'真六武众－紫焰',replace(replace('战士族协调＋协调以外的“六武众”怪兽１只以上\r\n①：１回合１次，对手发动魔法・陷阱卡时可以发动。将该发动无效并破坏。\r\n②：场上的此卡将被战斗・效果破坏的情况下，作为代替可将自己场上的１只“六武众”怪兽破坏。','\r',char(13)),'\n',char(10)),'魔法陷阱发动无效并破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29981935,'武斗神－鸟船',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：解放此卡可以发动。将除“武斗神－鸟船”之外的、种族不同的２只“武斗神”怪兽从牌组以守备表示特殊召唤。\r\n②：此卡存在于墓地，自己超量召唤“武斗神”超量怪兽成功时可以发动。将此卡视为装备卡，装备于该怪兽。装备怪兽战斗破坏的怪兽不去墓地而是被除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29996433,'恐龙摔跤手・卡波耶拉伶盗龙',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：攻击表示的此卡不会因战斗被破坏，被对手怪兽攻击的伤害步骤结束时将此卡改成守备表示。\r\n②：在自己・对手的准备阶段，此卡以守备表示存在的情况下可以发动。从牌组将1只“恐龙摔跤手・卡波耶拉伶盗龙”特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(29999161,'发条回卷','选择我方场上１只等级４或以下的冠有“发条”之名的怪兽返回至持有者手牌，并从手牌特殊召唤１只与返回至手牌怪兽相同等级的冠有“发条”之名的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30010480,'刚鬼 雷霆食人魔',replace(replace('“刚鬼”怪兽2只以上\r\n①：只要此卡存在于怪兽区域，回合玩家适用以下效果。\r\n●在自己的主要阶段，除通常召唤之外仅可追加1次，从手牌将1只怪兽召唤至此卡连接端的自己场上。\r\n②：此卡连接端的怪兽因战斗・效果被破坏的情况下可以发动。此卡的攻击力上升400。','\r',char(13)),'\n',char(10)),'使用「刚鬼 雷霆食人魔」的效果召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30012506,'A－强袭核心',replace(replace('①：１回合１次，可以发动以下的１个效果。\r\n●以自己场上的１只机械族・光属性怪兽为对象，将此卡视为装备魔法卡装备。装备怪兽将被战斗・效果破坏的情况下，作为代替将此卡破坏。\r\n●将装备状态的此卡特殊召唤。\r\n②：装备怪兽不受其他对手怪兽的效果影响。\r\n③：此卡从场上被送至墓地的情况下可以发动。将自己墓地１只其他的联合怪兽加入手牌。','\r',char(13)),'\n',char(10)),'装备','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30013902,'圣种之影芽',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己场上存在植物族通常怪兽的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：将墓地的此卡除外，以自己连接状态的、连接２以下的１只“圣天树”怪兽或“圣蔓”怪兽为对象可以发动。从额外牌组将１只其同名怪兽的效果无效并特殊召唤。此效果发动后，直至回合结束时为止自己仅可特殊召唤植物族怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30037118,'死制棺 冥椁',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：此卡因与对手怪兽的战斗被破坏时可以发动。获得该对手怪兽的控制权。以此效果获得的怪兽变为不死族，攻击力・守备力变为0。\r\n②：此卡存在于墓地的状态下，自己的不死族怪兽因与对手怪兽的战斗被破坏时，将此卡除外可以发动。获得该对手怪兽的控制权。以此效果获得的怪兽变为不死族，攻击力・守备力变为0。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30042158,'电子衔尾蛇','此卡从游戏中被除外时，可将１张手牌送入墓地并发动。我方从牌组中抽取１张卡牌。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30064423,'拓扑逻辑冲击龙',replace(replace('效果怪兽2只以上\r\n自己不可将怪兽出到此卡的连接端的额外怪兽区域。\r\n①：此卡存在于额外怪兽区域的状态下，有怪兽被特殊召唤至连接怪兽的连接端的情况下发动。从以下效果中挑选1个适用。此回合，自己的“拓扑逻辑冲击龙”的效果不可适用相同效果。\r\n●将此卡以外的场上的怪兽全部放回牌组。\r\n●将场上的魔法・陷阱卡全部放回牌组。\r\n●确认对手的额外牌组，将其中1张除外。','\r',char(13)),'\n',char(10)),'发动','怪兽全部回到牌组','魔法·陷阱卡全部回到牌组','除外额外牌组','','','','','','','','','','','','');
INSERT INTO texts VALUES(30068120,'锋利小鬼・剪刀','此卡名的效果1回合仅可使用1次。①：此卡存在于墓地的情况下，将1张手牌放回牌组最上面可以发动。将此卡从墓地以守备表示特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30068121,'锋利小鬼・剪刀','此卡名的效果1回合仅可使用1次。①：此卡存在于墓地的情况下，将1张手牌放回牌组最上面可以发动。将此卡从墓地以守备表示特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30068809,'魔救合缘',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从牌组将1只“魔救”怪兽加入手牌。\r\n②：此卡存在于墓地的情况下，将1张手牌放回牌组最上面可以发动。将此卡加入手牌。','\r',char(13)),'\n',char(10)),'检索效果','回到手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30069398,'常春藤壁','反转：以守备表示特殊召唤１只“常春藤衍生物”（植物族、地、星１、攻／守０）至对手场上。“常春藤衍生物”被破坏时，该衍生物的控制者受到３００点伤害。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30069399,'常春藤衍生物','由“常春藤壁”的效果特殊召唤而来。此衍生物被破坏时，控制者受到３００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30079770,'真红眼黑炎龙',replace(replace('①：只要此卡存在于场上・墓地，视为通常怪兽。②：场上视为通常怪兽的此卡可作为通常召唤再召唤１次。该情况下，此卡改视为效果怪兽，获得以下效果。\r\n●此卡进行战斗的战斗阶段结束时可以发动。给予对手相当于此卡原本攻击力数值的伤害。此卡名的此效果１回合仅可使用１次。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30086349,'凶星龙 陨星黑龙',replace(replace('等级７“真红眼”怪兽＋等级６龙族怪兽\r\n①：此卡融合召唤成功的情况下可以发动。从手牌・牌组将１只“真红眼”怪兽送至墓地，给予对手相当于该怪兽原本攻击力一半数值的伤害。②：此卡被从怪兽区域送至墓地的情况下，以自己墓地的１只通常怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30090452,'铠武者斩鬼','喜欢单挑，能抓住一瞬间的机会施展拔刀术进行攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30095833,'霸王黑龙 异色眼反叛超量龙',replace(replace('←4 【灵摆】 4→\r\n此卡名的灵摆效果１回合仅可使用１次。\n①：在自己的主要阶段可以发动。将此卡特殊召唤。然后，可从自己的墓地将１只暗属性怪兽作为此卡的超量素材。\r\n【怪兽效果】\r\n等级７的灵摆怪兽×２\n在可灵摆召唤等级７的情况下，额外牌组表侧的此卡可以灵摆召唤。\n此卡在被超量召唤的回合不可作为超量召唤的素材。\n此卡名的①怪兽效果１回合仅可使用１次。\n①：去除此卡的１个超量素材，以对手场上攻击力３０００以下的最多２只怪兽为对象可以发动。将该怪兽破坏。\n②：怪兽区域的此卡被破坏的情况下可以发动。将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'','','是否从墓地选暗属性怪兽作为超量素材？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30100551,'光道圣女 密涅瓦',replace(replace('等级４怪兽×２\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：去除此卡的１个超量素材可以发动。从自己的牌组上面将３张卡送至墓地。其中有“光道”卡的情况下，进而自己依其数量抽牌。\r\n②：此卡因战斗或对手的效果被破坏的情况下可以发动。从自己的牌组上面将３张卡送至墓地。其中有“光道”卡的情况下，进而可将场上的卡破坏，数量最多为其中“光道”卡的数量。','\r',char(13)),'\n',char(10)),'是否选场上的卡破坏？','送至墓地并抽牌','送至墓地并破坏','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30106950,'炎龙星－狻猊','此卡名的①效果1回合仅可使用1次。①：自己场上的此卡因战斗・效果被破坏并被送至墓地时可以发动。从牌组将1只“炎龙星-狻猊”以外的“龙星”怪兽以守备表示特殊召唤。②：1回合1次，在对手的主要阶段以及战斗阶段可以发动。仅以自己场上的“龙星”怪兽作为同步素材同步召唤。③：以此卡作为同步素材的同步怪兽攻击力・守备力上升500。','特殊召唤','「炎龙星－狻猊」效果适用中','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30109445,'小丑戏帮 朵莉诗',replace(replace('仪式・融合・同步・超量・灵摆怪兽2只\r\n①：上级召唤的自己怪兽在1次战斗阶段中可攻击2次。\r\n②：此卡被解放的情况下，可从以下效果中选择1个发动（此卡名的以下效果1回合仅可各选择1次）。\r\n●将双方场上・墓地的连接怪兽全部放回额外牌组。\r\n●双方将自身手牌全部放回牌组。然后，双方依自身放回的数量抽牌。','\r',char(13)),'\n',char(10)),'解放效果','回到牌组','抽牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30113682,'审判者','讨厌不分胜负的决斗的战士。棍棒的攻击很强哦！','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30114823,'码生成者','此卡名的①②效果1回合仅可各使用1次。①：在要将自己场上的电子界族怪兽作为“码语者”怪兽的连接素材的情况下，手牌的此卡也可一起作为连接素材。②：此卡作为“码语者”怪兽的连接素材从手牌・场上被送至墓地的情况下可以发动。从牌组将1只攻击力1200以下的电子界族怪兽送至墓地。将场上的此卡作为素材的情况下，也可不送往墓地而是改为加入手牌。','','从场上送至墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30118200,'扫除机块 真空吸尘象',replace(replace('1只“机块”怪兽\r\n此卡名的效果①②在1个回合中仅有1次机会使用其中任意1种。\r\n此卡在其被连接召唤的回合中不可当做连接素材使用。\r\n①：将1张手牌送至墓地后，可以以对手场上的1张卡为对象发动。破坏该卡。\r\n②：此卡处于相互连接状态时，可以以对手主要怪兽区域的1只怪兽为对象发动。破坏该怪兽。\r\n③：此卡不处于相互连接状态时可直接进行攻击。','\r',char(13)),'\n',char(10)),'丢弃手牌破坏对手1张卡','破坏对手1只怪兽','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30118701,'地雷星 轰木',replace(replace('此卡名以①方法的特殊召唤１回合仅可进行１次，且②效果１回合仅可使用１次。\r\n①：将手牌的１只其他的怪兽送至墓地，可将此卡从手牌特殊召唤。以此方法特殊召唤的此卡的攻击力下降５００。\r\n②：在自己・对手的战斗阶段支付５００LP可以发动。从自己的手牌・场上，将由战士族融合怪兽卡决定的融合素材怪兽送至墓地，将该１只融合怪兽从额外牌组融合召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30118811,'备援＠伊格尼斯者',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：被从额外牌组特殊召唤的电子界族怪兽存在于自己场上的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从牌组将“备援＠伊格尼斯者”以外的1只电子界族・暗属性怪兽加入手牌。然后，挑选自己的1张手牌舍弃。','\r',char(13)),'\n',char(10)),'特殊召唤','检索效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30123142,'同步直击','可选择１只场上被同步召唤的怪兽并发动。直至回合结束时，被选择怪兽的攻击力上升作为同步素材的怪兽数量×５００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30126992,'光芒 迪亚波逻斯','此卡不可通常召唤。我方墓地的光属性怪兽为５种或以上的场合可特殊召唤。１回合１次，可将我方墓地的１只光属性怪兽从游戏中除外并发动。选择被盖牌在对手场上的１张卡牌确认，并将其返回至持有者牌组的最上方或最下方。','返回牌组','返回牌组最上面','返回牌组最下面','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30127518,'大陷坑','对手以表侧表示成功特殊召唤２只或以上的怪兽时可发动。将所有该怪兽送入墓地。并且从对手的手牌、牌组将该同名怪兽全部送入墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30128445,'超越恐龙 钻头矛颌龙',replace(replace('等级６怪兽×２\r\n此卡名的①③效果１回合仅可各使用１次。\r\n①：去除此卡的１个超量素材，以自己除外状态的１只恐龙族怪兽为对象可以发动。将该怪兽特殊召唤。\r\n②：没有超量素材的此卡与怪兽的战斗给予对手的战斗伤害变为两倍。\r\n③：此卡被破坏的情况下可以发动。从自己的墓地将１只通常怪兽放回牌组。然后，可将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','是否将此卡特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30131474,'枪管供给点',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：自己场上存在“枪管”连接怪兽的情况下，在自己・对手的准备阶段以自己墓地的1只“枪弹”怪兽为对象可以发动。将该怪兽特殊召唤。以此效果特殊召唤的怪兽将在结束阶段被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30138615,'幻惑眼纳祭魔',replace(replace('种族不同的恶魔族・幻想魔族・魔法师族怪兽×2\r\n此卡名的①效果1回合仅可使用1次。\r\n①：此卡特殊召唤的情况下，或此卡进行过战斗的战斗阶段结束时可以发动。将对手场上的1只怪兽视为装备魔法卡装备于此卡。\r\n②：此卡的攻击力上升相当于以此卡的效果装备中的怪兽的攻击力数值。\r\n③：此卡与怪兽进行战斗的情况下，该2只不会因该战斗被破坏。\r\n④：对手怪兽不可攻击其他怪兽。','\r',char(13)),'\n',char(10)),'装备','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30155789,'暴虐药剂','可选择我方场上的１只表侧表示怪兽并发动此卡。此卡被视为装备卡，装备被选择的我方怪兽。我方给予对手生命效果伤害时，直至回合结束时，装备怪兽的攻击力上升１０００点（１回合仅１次）。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30163008,'罗天神将',replace(replace('相同种族的怪兽2只以上\r\n此卡名的②效果1回合仅可使用1次。\r\n①：在自己・对手的准备阶段，以此卡连接端的1只表侧表示怪兽为对象可以发动。从手牌将1只种族与该怪兽相同的、等级4以下的怪兽特殊召唤至此卡连接端的自己场上。\r\n②：在自己・对手的战斗阶段开始时，以对手场上的1张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30170981,'死之信息“L”','此卡只可通过“通灵盘”的效果上场。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30190809,'机动砦齿轮・魔像','支付８００LP可以发动。此回合，此卡可直接攻击对手玩家。','直接攻击','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30194529,'星杯战士 宁吉尔苏',replace(replace('连接怪兽2只以上\r\n此卡名的①效果1回合仅可使用1次。①：此卡连接召唤成功的情况下发动。自己从牌组抽相当于此卡连接端的“星杯”怪兽数量的张数的卡。②：1回合1次，在自己的主要阶段可以发动。从自己及对手场上的卡各挑选1张送至墓地。③：此卡从场上被送至墓地的情况下可以发动。从手牌将1只“星杯”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30208479,'黑混沌之魔导','以“混沌-黑魔术仪式”降临。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30213599,'守墓的末裔','可释放我方场上１只除此卡以外的表侧表示的冠有“守墓的”之名的怪兽来发动此卡。选择对手场上的１张卡牌并破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30221870,'机皇帝神智∞－同步吸收',replace(replace('此卡不可通常召唤，只能通过此卡的效果特殊召唤。\r\n此卡名的效果①在1个回合中仅可使用1次。\r\n①：在对手的回合中，将自己场上1只表侧表示的“机皇”怪兽送至墓地后可以发动。从手牌中特殊召唤此卡。\r\n②：此卡特殊召唤成功时，可以以对手场上的1只怪兽为对象发动。此回合中，该怪兽不可进行攻击。\r\n③：有破坏场上卡的效果发动时，解放此卡后可以发动。使该发动无效并破坏。','\r',char(13)),'\n',char(10)),'','对手怪兽不可攻击','发动无效并破坏','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30227494,'念力追踪者','此卡名以①方法的特殊召唤1回合仅可进行1次。①：自己场上有“念力追踪者”以外的等级3怪兽存在的情况下，可将此卡从手牌以守备表示特殊召唤。②：以此卡作为同步素材的同步怪兽的攻击力上升600。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30230789,'机偶商人 壹七七','①：此卡召唤成功的情况下发动。从牌组将１张“机偶”卡加入手牌。②：此卡在可攻击的情况下必须攻击。③：攻击表示的此卡在被选择为攻击对象的情况下发动。将此卡改成守备表示。','变成守备表示','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30241314,'宏观宇宙',replace(replace('①：作为此卡发动时的效果处理，可从手牌・牌组将1只“原始太阳 赫利俄斯”特殊召唤。\r\n②：只要此卡存在于魔法与陷阱区域，被送往墓地的卡不去墓地而直接被除外。','\r',char(13)),'\n',char(10)),'是否要特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30243636,'饥饿汉堡','以“汉堡的食谱”降临','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30270176,'暗黑方界神 深红新星',replace(replace('此卡不可通常召唤。\r\n仅可在向对手出示除此卡以外的手牌的３种“方界”卡的情况下可以特殊召唤。\r\n此卡名的③效果１回合仅可使用１次。\r\n①：此卡不受除此卡以外原本攻击力是３０００以下的怪兽发动的效果影响。\r\n②：此卡的攻击破坏怪兽时可以发动。此战斗阶段中，此卡仅可再进行１次攻击。\r\n③：在自己的结束阶段发动。双方玩家受到３０００点伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30271097,'落胤与圣女',replace(replace('此卡名在规则上也视为“烙印”卡、“教导”卡。\r\n此卡名的卡1回合仅可发动1张。\r\n①：可从以下效果中选择1个发动。\r\n●从额外牌组将1只记载有“阿尔白斯之落胤”卡名的怪兽送至墓地，以场上的1张表侧表示卡为对象可以发动。将该卡破坏。\r\n●自己场上或墓地存在“艾克利西亚”怪兽的情况下，以自己或对手墓地的1只怪兽为对象可以发动。将该怪兽特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'发动','破坏','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30275298,'终击龙－电子终极龙',replace(replace('攻击力2100以上的机械族怪兽×3\r\n此卡仅可以融合召唤方式特殊召唤。\r\n此卡名的①效果1回合仅可使用1次。\r\n①：仅以光属性怪兽作为素材的此卡融合召唤的情况下，支付4000LP可以发动。从牌组将1张“限制解除”加入手牌。\r\n②：此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。\r\n③：攻击力高于原本攻击力的此卡在1次战斗阶段中可攻击3次。','\r',char(13)),'\n',char(10)),'检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30275299,'终击龙－电子终极龙',replace(replace('攻击力2100以上的机械族怪兽×3\r\n此卡仅可以融合召唤方式特殊召唤。\r\n此卡名的①效果1回合仅可使用1次。\r\n①：仅以光属性怪兽作为素材的此卡融合召唤的情况下，支付4000LP可以发动。从牌组将1张“限制解除”加入手牌。\r\n②：此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。\r\n③：攻击力高于原本攻击力的此卡在1次战斗阶段中可攻击3次。','\r',char(13)),'\n',char(10)),'检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30276969,'冰弹手 蕾丝','①：此卡不会因与等级４以上的怪兽的战斗被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30284022,'暗黑界之傀儡',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：以双方墓地的合计最多３张卡为对象可以发动。将该卡除外。然后，从手牌挑选１只恶魔族怪兽舍弃。\r\n②：在自己的主要阶段将墓地的此卡除外，以自己１只被除外的恶魔族怪兽为对象可以发动。将该怪兽加入手牌。此效果在此卡被送至墓地的回合不可发动。','\r',char(13)),'\n',char(10)),'双方墓地除外','回收除外的怪兽','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30286474,'刚鬼 大师食人魔',replace(replace('“刚鬼”怪兽2只以上\r\n①：1回合1次，将此卡连接端的自己的任意数量的“刚鬼”怪兽放回持有者手牌，以放回手牌数量的对手场上的表侧表示卡为对象可以发动。将该卡的效果直至回合结束时为止无效。此效果在对手回合中也可以发动。②：此卡可对对手的所有怪兽各攻击1次，对手场上有表侧表示怪兽存在的情况下，仅可选择其中攻击力最高的怪兽为攻击对象。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30291086,'心灵协调',replace(replace('此卡名的效果１回合仅可使用１次。①：可从以下效果中选择１个发动。\r\n●从自己的手牌・墓地，将光・暗属性怪兽各最多１只除外可以发动。直至回合结束时为止，此卡的等级上升或下降相当于所除外数量的数值。\r\n●以自己被除外的光・暗属性怪兽各最多１只为对象可以发动。将该怪兽放回墓地，直至回合结束时为止，此卡的等级上升或下降相当于所放回数量的数值。','\r',char(13)),'\n',char(10)),'除外手牌·墓地的怪兽','回收除外的怪兽','等级上升','等级下降','','','','','','','','','','','','');
INSERT INTO texts VALUES(30299166,'异虫坦塔克尔斯','１回合１次，可将我方墓地的１只冠有“异虫”之名的爬虫类族怪兽从游戏中除外并发动。此回合，此卡在１次的战斗阶段中可攻击２次。','两次攻击','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30303854,'岩浆炎弓手',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：此卡召唤成功的情况下发动。此回合自己除通常召唤外仅追加１次，在自己的主要阶段可召唤１只“岩浆炎”怪兽。\r\n②：此卡存在于墓地的情况下，以自己场上的１只炎属性怪兽为对象可以发动。破坏该怪兽，将此卡以守备表示特殊召唤。以此效果特殊召唤的此卡离开场上的情况下，将其除外。此回合，自己仅可特殊召唤炎属性怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30312361,'混沌魅影','①：1回合1次，可以自己墓地的1只效果怪兽为对象发动。将该怪兽除外，此卡直到结束阶段为止，视为与该怪兽同名的卡，获得相同的原本攻击力和效果。②：因此卡的战斗发生的、给予对手的战斗伤害变为0。','复制效果','结束复制效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30314994,'元素龙',replace(replace('当场上有特定属性的怪兽存在的场合，此怪兽获得以下效果。\r\n●炎属性：此卡的攻击力上升５００点。\r\n●风属性：此卡通过战斗破坏对手怪兽的场合，可再进行一次攻击。','\r',char(13)),'\n',char(10)),'连续攻击','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30325729,'死神回旋镖','具有意志，坚持对着所瞄准目标飞去的回旋镖。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30327674,'混沌女巫－混元的魔女－','此卡名的①②效果１回合１次，仅可使用其中１个，发动的回合中，自己从额外牌组仅可特殊召唤光・暗属性的同步怪兽。①：解放此卡可以发动。将２只“黑兽衍生物”（恶魔族・暗・星２・攻１０００／守５００）特殊召唤至自己场上。②：此卡被从手牌・墓地除外的情况下可以发动。将２只“白兽衍生物”（天使族・协调・光・星２・攻５００／守１０００）特殊召唤至自己场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30327675,'黑兽衍生物','以“混沌魔女”的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30327676,'白兽衍生物','以“混沌魔女”的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30328508,'影依・蜥蜴',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：此卡反转的情况下，以场上的1只怪兽为对象可以发动。将该怪兽破坏。\r\n②：此卡因效果被送至墓地的情况下可以发动。从牌组将“影依・蜥蜴”以外的1张“影依”卡送至墓地。','\r',char(13)),'\n',char(10)),'怪兽破坏','送至墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30334522,'禁咒仪・精神鳌魔','以“咒仪”仪式魔法卡降临。①：１回合１次，宣言种族和属性各１个可以发动。随机挑选１张对手手牌确认，是宣言的种族・属性的怪兽的情况下，将该怪兽放回牌组。','宣言','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30336082,'杯满之灿幻庄',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：只要此卡存在于场地区域，在自己的主要阶段１期间，自己场上的龙族・炎属性怪兽不受对手所发动的效果影响。\r\n②：在自己的主要阶段可以发动。从牌组将１只“天杯龙”怪兽加入手牌。然后，挑选自己的１张手牌舍弃。\r\n③：此卡在战斗阶段中被破坏的情况下，以自己场上的１只龙族同步怪兽为对象可以发动。将该怪兽的攻击力改成两倍。','\r',char(13)),'\n',char(10)),'','检索','攻击力变成2倍','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30338466,'剑现武斗神',replace(replace('可从以下效果中选择１个发动。\r\n●选择我方墓地１只冠有“武斗神”之名的怪兽并加入手牌。\r\n●选择我方从游戏中被除外的１只冠有“武斗神”之名的怪兽并返回至墓地。','\r',char(13)),'\n',char(10)),'墓地回收','除外回到墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30339825,'万物始源－“水”',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：以自己或对手墓地的1只怪兽为对象可以发动。将该怪兽的持有者场上的1只水属性怪兽破坏，将对象怪兽以守备表示特殊召唤至其场上。\r\n②：从墓地将不是在此回合被送至墓地的此卡除外，以自己或对手墓地的1只水属性怪兽为对象可以发动。将该怪兽的持有者场上的1只怪兽破坏，将对象怪兽以守备表示特殊召唤至其场上。','\r',char(13)),'\n',char(10)),'发动','除外并发动','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30341772,'希望爆破炮','自己场上有“希望皇霍普”怪兽存在的情况下可以发动。破坏对手场上攻击力最低的１只怪兽，给予对手生命值相当于所破坏怪兽攻击力数值的伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30342076,'连接解码者',replace(replace('等级4以下的电子界族怪兽1只\r\n此卡名的效果1回合仅可使用1次。\r\n①：此卡作为原本攻击力为2300以上的电子界族连接怪兽的连接素材被送至墓地的情况下可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30348744,'T.G.钻头鱼','此卡名的①③效果1回合仅可各使用1次。①：自己场上的怪兽仅有“T.G.”怪兽的情况下可以发动。从手牌将此卡特殊召唤。②：此卡可直接攻击。③：自己的“T.G.”怪兽给予对手战斗伤害时，以对手场上的1只怪兽为对象可以发动。将该怪兽破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30350202,'凶征龙－日蚀',replace(replace('龙族等级7怪兽×2\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡超量召唤的情况下，以自己墓地・除外状态的1只等级4以下的“征龙”怪兽为对象可以发动。从自己牌组・除外状态将1只卡名记载于该怪兽的、等级7或阶级7的“征龙”怪兽特殊召唤。然后，将对象怪兽放回牌组。\r\n②：对手发动魔法・陷阱卡的效果时，去除此卡的2个超量素材可以发动。将该发动无效并除外。','\r',char(13)),'\n',char(10)),'特殊召唤','发动无效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30353551,'人海战术','各回合结束阶段时，从牌组选择等级２或以下的通常怪兽特殊召唤至我方场上，其数量和在该回合中因战斗被破坏的我方的等级２或以下的通常怪兽数量相同。之后将牌组洗牌。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30373970,'结瘴龙 提斯蒂娜',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将“结瘴龙 提斯蒂娜”以外的1只“提斯蒂娜”怪兽加入手牌。此回合中，自己场上的光属性“提斯蒂娜”怪兽的攻击力上升1000。\r\n②：此卡被送至墓地的情况下，如果场地区域存在卡则可以发动。将此卡特殊召唤。此回合，自己从手牌・墓地仅可特殊召唤“提斯蒂娜”怪兽。','\r',char(13)),'\n',char(10)),'检索','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30382214,'花札卫－樱－',replace(replace('①：自己场上有等级2以下的“花札卫”怪兽存在时可以发动。从手牌中特殊召唤此卡。此效果发动后，直至回合结束时为止，自己只能召唤或特殊召唤“花札卫”怪兽。\r\n②：1个回合1次，解放自己场上的1只“花札卫”怪兽后可以发动。自己从牌组中抽1张卡，并与对手互相确认。如果该卡为“花札卫”怪兽，则可从牌组中将1只“花札卫-樱-”以外的“花札卫”怪兽加入手牌，或对其进行特殊召唤。如果不是“花札卫”怪兽，则将该卡送至墓地。','\r',char(13)),'\n',char(10)),'是否把「花札卫」怪兽加入手牌或特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30392583,'圣占术的仪式',replace(replace('降临“圣占卜姬塔罗蕾”的必备。\r\n①：从我方手牌・场上解放怪兽，使得等级合计变成９以上，并从手牌仪式召唤“圣占卜姬塔罗蕾”。\r\n②：在我方主要阶段，可将墓地的此卡除外并发动。从牌组将１只“占卜姬”怪兽加入手牌。此效果在此卡被送入墓地的回合不可发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30394645,'教导之死徒',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：此卡存在于手牌，且场上存在被从额外牌组特殊召唤的怪兽的情况下可以发动。将此卡特殊召唤。\r\n②：此卡从手牌特殊召唤的情况下可以发动。双方各从自身的额外牌组将1只怪兽送至墓地。\r\n③：此卡被送至墓地的情况下，以“教导之死徒”以外的、自己墓地的1张“教导”卡为对象可以发动。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','送墓','回收','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30397786,'白之幻兽－青眼白龙',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡从牌组加入手牌时，或自己的怪兽因战斗被破坏时，向对手出示手牌的此卡可以发动。将此卡特殊召唤。\r\n②：此卡从手牌・牌组特殊召唤的情况下可以发动。将对手场上的怪兽全部破坏。此回合，自己仅可用“青眼”怪兽直接攻击。\r\n③：以场上的此卡为对象的效果发动时，舍弃1张手牌可以发动。将该效果无效。','\r',char(13)),'\n',char(10)),'特殊召唤','破坏','效果无效','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30397787,'白之幻兽－青眼白龙',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡从牌组加入手牌时，或自己的怪兽因战斗被破坏时，向对手出示手牌的此卡可以发动。将此卡特殊召唤。\r\n②：此卡从手牌・牌组特殊召唤的情况下可以发动。将对手场上的怪兽全部破坏。此回合，自己仅可用“青眼”怪兽直接攻击。\r\n③：以场上的此卡为对象的效果发动时，舍弃1张手牌可以发动。将该效果无效。','\r',char(13)),'\n',char(10)),'特殊召唤','破坏','效果无效','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30398342,'龙星的具象化','①：1回合1次，自己场上的怪兽因战斗・效果被破坏的情况下可以发动此效果。从牌组将1只“龙星”怪兽特殊召唤。②：只要此卡存在于魔法与陷阱区域，自己不可从额外牌组将同步怪兽以外的怪兽特殊召唤。','发动并使用①效果','发动但不使用效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30399511,'次代机・动力员','①：此卡召唤时可以发动。从牌组将１只等级３的“次代机”效果怪兽加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30411385,'女战神・次女',replace(replace('此卡牌名的①②效果１回合只可各使用１次。\r\n①：此卡召唤、反转召唤、特殊召唤成功的场合，可以对手场上的１只怪兽为对象发动。破坏该怪兽。\r\n②：此卡进行战斗的伤害计算后，可以我方墓地的１张永续魔法卡为对象发动。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30426226,'对调英雄','①：双方场上的怪兽数量相同的情况下，将该怪兽的控制权全部互换。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30430448,'冰冻诅咒之神碑',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：可从以下效果中选择1个发动。此卡发动后，跳过下个自己的战斗阶段。\r\n●以对手场上的1只效果怪兽为对象可以发动。将该怪兽的效果直至回合结束时为止无效。然后，从对手牌组上面将3张卡除外。\r\n●从额外牌组将1只“神碑”怪兽特殊召唤至额外怪兽区域。','\r',char(13)),'\n',char(10)),'怪兽无效','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30432463,'魔鬼之声・华耳琴璃',replace(replace('←5 【灵摆】 5→\r\n①：只要另一方自己的灵摆区域有天使族怪兽卡存在，每次自己受到效果伤害，在此卡上放１个响鸣计数物。\n②：对手场上的怪兽的攻击力下降相当于自己场上响鸣计数物数量×１００的数值。\r\n【怪兽效果】\r\n此卡名的①②怪兽效果１回合仅可各使用１次。\n①：此卡存在于手牌的情况下，从手牌将１张其他的卡舍弃可以发动。从牌组挑选１只“天使之声・华耳琴璃”，将此卡和该卡放在自己的灵摆区域。\n②：在此卡召唤・特殊召唤的回合的自己的主要阶段，从自己的墓地将１张“华耳琴璃”通常魔法・通常陷阱卡除外可以发动。适用该魔法・陷阱卡发动时的受到伤害一方的效果。','\r',char(13)),'\n',char(10)),'此卡和牌组的「天使之声・华耳琴璃」一起放置','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30435145,'古代机械齿轮工厂','向对手展示手牌的１只等级５以上冠有“古代机械齿轮”之名的怪兽。为使等级合计变成展示怪兽等级的２倍，将我方墓地冠有“古代机械齿轮”之名的怪兽从游戏中除外。此回合特殊召唤展示怪兽的场合无须解放。','不使用解放召唤','请选择一张名字带有「古代机械齿轮」的怪兽卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30439101,'森林的梅尔菲们',replace(replace('等级２怪兽×２\r\n此卡名的①②效果１回合仅可各使用１次。①：去除此卡的１个超量素材可以发动。从牌组将１张“梅尔菲”卡加入手牌。②：自己场上此卡以外的表侧表示“梅尔菲”怪兽被放回自己手牌的情况下，以对手场上的１只表侧表示怪兽为对象可以发动。该怪兽只要以表侧表示存在于场上，不可攻击，效果无效化。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30450531,'降灵的仪式','选择我方墓地中的１张冠有“守墓的”的怪兽卡并特殊召唤。此效果不会受到“王家长眠之谷－死灵谷”的效果影响。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30451366,'幻想绵羊','①：手牌・场上・墓地的此卡，可以代替１只融合怪兽卡上记载有卡名的融合素材怪兽。在此之际，其他融合素材怪兽必须为正规素材。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30453613,'维都苏的觉醒',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：从牌组将１张“灰灭之都 黑曜城”以表侧表示放在自己或对手的场地区域。然后，对手的场地区域存在卡的情况下，可从牌组将１只等级５以上的炎族・暗属性怪兽加入手牌。此卡发动后，直至回合结束时为止，自己从牌组・额外牌组仅可特殊召唤炎族怪兽。','\r',char(13)),'\n',char(10)),'','在自己场地区域放置','在对手场地区域放置','是否从牌组把怪兽加入手牌？','','','','','','','','','','','','');
INSERT INTO texts VALUES(30459350,'王宫的铁壁','①：只要此卡存在于魔法与陷阱区域，双方不可将卡除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30461781,'八咫鸦之骸',replace(replace('从以下效果中选择１项发动。\r\n●从我方牌组抽取１张卡牌。\r\n●可在对手场上有表侧表示的灵魂怪兽存在的场合发动此卡。从我方牌组抽取２张卡牌。','\r',char(13)),'\n',char(10)),'抽一张卡','抽两张卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30464153,'海牛头人','只要此卡以表侧表示存在于场上，我方场上的鱼族、海龙族、水族怪兽攻击守备表示怪兽时，若攻击力超过该守备力，给予对手生命相当于该数值的战斗伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30488793,'反作用力','以表侧攻击表示怪兽为攻击对象的怪兽的攻击变为无效时可以发动。给予对手LP该２只怪兽攻击力差额数值的伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30492798,'仪式魔人 布置者','进行仪式怪兽的仪式召唤的场合，作为该仪式召唤所需等级份的１只怪兽，可将我方墓地的此卡从游戏中除外。在仪式召唤中使用了此卡的仪式怪兽不受陷阱卡的影响。','「仪式魔人 布置者」效果适用中','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30494314,'红血鬼','此卡因不死族怪兽之效果从墓地特殊召唤成功时，可选择我方场上的１只不死族怪兽并发动。移除场上的１个超量素材，被选择怪兽的等级上升１级，攻击力上升３００点。','等级攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30500113,'急袭猛禽－回归',replace(replace('“急袭猛禽－回归”的②效果１回合仅可使用１次。\r\n①：自己场上的“急袭猛禽”怪兽因战斗被破坏的情况下，以自己墓地的１只“急袭猛禽”怪兽为对象可以发动。将该怪兽加入手牌。\r\n②：自己场上的“急袭猛禽”怪兽因效果被破坏的情况下，将墓地的此卡除外可以发动。从牌组将１张“急袭猛禽”卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30502181,'光道轻剑','仅限装备冠有“光道”之名的怪兽。装备怪兽的攻击力上升７００点。此卡从牌组被送入墓地时，可选择我方场上的１只冠有“光道”之名的怪兽装备此卡。','装备','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30525991,'斯巴尔克塔咒术师','此卡在场上以表侧表示存在的情况下，每次怪兽从牌组被特殊召唤，给予对手LP５００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30531525,'魔之试衣间','支付８００点LP。翻开我方牌组最上面的４张卡牌，将其中等级３以下的通常怪兽特殊召唤至我方场上，然后将其余卡牌放回到牌组并进行洗牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30532390,'鸟人','以５马赫的速度飞行之鸟人。他的眼神比老鹰还要锐利。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30537973,'捕食植物 蜘蛛兰',replace(replace('←8 【灵摆】 8→\r\n此卡名的灵摆效果１回合仅可使用１次。①：在发动此卡的回合的自己的主要阶段，以此卡以外的１张魔法与陷阱区域的表侧表示卡为对象可以发动。将该卡破坏。\r\n【怪兽效果】\r\n此卡名的怪兽效果１回合仅可使用１次。①：在此卡召唤・特殊召唤成功的回合的结束阶段，从手牌将１只植物族怪兽舍弃可以发动。从牌组将１只等级４以下的植物族怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30539496,'真龙皇 威岩真主 灾厄','此卡名的①②效果１回合仅可各使用１次。①：在自己的主要阶段可以发动。从手牌及自己场上的表侧表示怪兽中，将此卡以外的、包括地属性怪兽在内的２只怪兽破坏，将此卡从手牌特殊召唤，所破坏的２只都是地属性怪兽的情况下，可确认对手的额外牌组并从其中挑选最多３种怪兽除外。②：此卡因效果被破坏的情况下可以发动。从自己的墓地挑选１只地属性以外的幻龙族怪兽特殊召唤。','地属性怪兽破坏，此卡特殊召唤','幻影龙族怪兽特殊召唤','是否把对手的额外牌组的怪兽除外？','是否继续选择怪兽除外？','','','','','','','','','','','','');
INSERT INTO texts VALUES(30548775,'分体','场上的融合怪兽被破坏送入墓地时，可特殊召唤我方墓地中的融合该融合怪兽时所使用的１只融合素材怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30552375,'网格魔杖',replace(replace('仅限装备我方场上的电子界族怪兽。\r\n①：装备怪兽的攻击力上升３００，且不受对手效果的影响，１回合仅１次不会因战斗被破坏。\r\n②：场上表侧表示的此卡被破坏并送入墓地的场合可发动。直至回合结束时，我方场上所有电子界族怪兽都不会因战斗、效果被破坏。','\r',char(13)),'\n',char(10)),'全部电子界族怪兽不会被破坏','「网格魔杖」效果适用中','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30562585,'ZERO－MAX','我方手牌为０张的场合，可选择我方墓地中１只冠有“无限狱”之名的怪兽来发动此卡。特殊召唤所选择怪兽，破坏场上所有表侧表示的攻击力低于特殊召唤怪兽的怪兽。发动此卡的回合中，跳过我方的战斗阶段。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30575681,'圣骑士贝德维尔',replace(replace('①：此卡召唤、特殊召唤成功时可发动。从牌组将１张“圣剑”装备魔法卡送入墓地。\r\n②：只要此卡以表侧表示存在于场上，仅１次可以场上的１张“圣剑”装备魔法卡，以及１只能够装备该卡的怪兽为对象发动。该装备魔法卡转换给成为正确对象的该怪兽。此效果在对手回合也可发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30576089,'青眼喷气龙',replace(replace('此卡名的①③效果１回合仅可各使用１次，仅可在自己场上或墓地存在“青眼白龙”的情况下发动。\r\n①：此卡存在于手牌・墓地，且场上的卡因战斗・效果被破坏的情况下可以发动。将此卡特殊召唤。\r\n②：只要此卡存在于怪兽区域，自己场上的其他卡不会因对手的效果被破坏。\r\n③：此卡进行战斗的伤害步骤开始时，以对手场上的１张卡为对象可以发动。将该卡放回手牌。','\r',char(13)),'\n',char(10)),'此卡特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30581601,'黯蜜★史拿奇',replace(replace('等级4以下的兽族・光属性怪兽1只\r\n此卡名的①效果1回合仅可使用1次。\r\n①：此卡特殊召唤的情况下可以发动。从手牌・牌组将1张“黯蜜”场地魔法卡以表侧表示放在自己场上。此回合，自己不可连接召唤连接3以上的连接怪兽。\r\n②：在自己・对手的主要阶段及对手的战斗阶段，支付100LP可以发动（同一连锁上最多1次）。将包含“黯蜜”怪兽在内的、自己场上的怪兽作为素材进行同步召唤。','\r',char(13)),'\n',char(10)),'放置场地魔法','同步召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30581602,'黯蜜★史拿奇',replace(replace('等级4以下的兽族・光属性怪兽1只\r\n此卡名的①效果1回合仅可使用1次。\r\n①：此卡特殊召唤的情况下可以发动。从手牌・牌组将1张“黯蜜”场地魔法卡以表侧表示放在自己场上。此回合，自己不可连接召唤连接3以上的连接怪兽。\r\n②：在自己・对手的主要阶段及对手的战斗阶段，支付100LP可以发动（同一连锁上最多1次）。将包含“黯蜜”怪兽在内的、自己场上的怪兽作为素材进行同步召唤。','\r',char(13)),'\n',char(10)),'放置场地魔法','同步召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30583090,'邪恶－英雄 死亡镜囚',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次，且②效果1回合仅可使用1次。\r\n①：仅可以“黑暗结合”的效果特殊召唤的融合怪兽存在于自己场上的情况下，此卡可从手牌特殊召唤。\r\n②：从牌组将1只“－英雄”怪兽送至墓地可以发动。此回合，要融合召唤“－英雄”融合怪兽的情况下，表侧表示的此卡可以代用为该融合怪兽上记载有卡名的1只融合素材怪兽（其他融合素材不得代用）。','\r',char(13)),'\n',char(10)),'','','代替素材效果适用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30585393,'重生拼装','我方场上的怪兽仅有１只因卡牌效果被破坏的场合，可选择１只该怪兽发动。特殊召唤被选择的怪兽至我方场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30587695,'机械独角仙','可将我方场上１张表侧表示的魔法・陷阱卡送入墓地来发动此卡。选择我方墓地中１只等级４以下的昆虫族怪兽并以表侧守备表示特殊召唤。“机械独角仙”的效果在１个回合中只可使用１次。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30600344,'超量爆发','我方场上存在有等级６或以上的超量怪兽的场合可发动。破坏被盖牌于对手场上的所有卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30603688,'幻想见习魔导师',replace(replace('①：此卡可以舍弃1张手牌，来从手牌特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从牌组将1只“黑魔导”加入手牌。\r\n③：在自己・对手回合中，自己的其他魔法师族・暗属性怪兽与对手怪兽进行战斗的伤害计算时，将手牌・场上的此卡送至墓地可以发动。该自己的怪兽的攻击力・守备力仅在该伤害计算时上升2000。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30604579,'极神皇索尔',replace(replace('“极星兽”协调＋协调以外的怪兽２只或以上\r\n①：１回合１次，在我方主要阶段可发动。直至回合结束时，所有对手场上的表侧表示怪兽之效果被无效化。\r\n②：场上表侧表示的此卡因对手被破坏并送入墓地之回合的结束阶段，可从我方墓地将１只“极星兽”协调除外并发动。从墓地特殊召唤此卡。\r\n③：以此卡的②效果特殊召唤成功时可发动。给予对手８００伤害。','\r',char(13)),'\n',char(10)),'怪兽效果无效化','特殊召唤','给与对手800伤害','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30606547,'暗黑之扉','双方玩家在各自的战斗阶段中只可用１只怪兽进行攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30607616,'辙之魔妖－胧车',replace(replace('协调＋协调以外的怪兽１只以上\r\n此卡名的②③效果１回合仅可各使用１次。\r\n①：“辙之魔妖－胧车”在自己场上仅可有１张以表侧表示存在。\r\n②：此卡存在于墓地，且自己原本等级为５的同步怪兽因战斗或对手的效果被破坏的情况下可以发动。从自己的墓地将１只其他的不死族怪兽除外，将此卡特殊召唤。\r\n③：此卡从墓地特殊召唤的情况下可以发动。此回合，自己的怪兽不会因战斗被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30608985,'魔力礼仪师','反转：可选择我方墓地的１只等级４或以下的魔法师族怪兽并特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30643162,'强袭射击','自己场上的怪兽攻击宣言时可以发动。该怪兽的攻击力直至回合结束时为止上升７００点，该怪兽攻击守备表示怪兽时，若攻击力超过该守备力，则依该数值给予对手LP战斗伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30646525,'破灭魔王 加兰道夫','由“破灭的仪式”召唤而来。成功仪式召唤此卡时，破坏场上除此卡以外的所有守备力低于此卡攻击力的怪兽，每破坏１只怪兽此卡的攻击力上升１００点。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30650147,'仇尸・复生','①：以对手场上的１只表侧表示怪兽为对象可以发动。解放该怪兽，将１只拥有与其原本等级相同等级的“仇尸衍生物”（不死族・暗・攻／守０）特殊召唤至自己场上。只要以此效果特殊召唤的衍生物存在于怪兽区域，自己仅可召唤・特殊召唤“仇尸”怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30650148,'仇尸衍生物','由「仇尸・复生」的效果特殊召唤。只要这个效果特殊召唤的衍生物在怪兽区域存在，自己不是「复仇死者」怪兽不能召唤·特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30653113,'尼罗河的恩惠','每次因对手卡牌的效果，卡牌从我方手牌被舍弃至墓地发动。我方回复１０００LP。','回复','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30655537,'机械猎鹰','装备了喷气式引擎的鹰，能以音速飞行。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30674956,'苍翠之风灵使 薇茵',replace(replace('包含风属性怪兽在内的怪兽2只\r\n此卡名在规则上也视为“凭依装着”卡。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：以对手墓地的1只风属性怪兽为对象可以发动。将该怪兽特殊召唤至此卡连接端的自己场上。\r\n②：连接召唤的此卡因战斗或对手的效果被破坏的情况下可以发动。从牌组将1只守备力1500以下的风属性怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30676200,'灰灭之都的英雄',replace(replace('此卡名以①方法的特殊召唤１回合仅可进行１次，且②效果１回合仅可使用１次。\r\n①：场地区域存在“灰灭之都 黑曜城”的情况下，此卡可从手牌特殊召唤。\r\n②：在自己・对手的主要阶段，以场上的１只炎族怪兽为对象可以发动。将该怪兽破坏。以此效果破坏了“灭亡龙 维都苏”的情况下，进而可从牌组将１张“灰灭之都 黑曜城”以表侧表示放在自己的场地区域。','\r',char(13)),'\n',char(10)),'','破坏','是否放置场地？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30680659,'圣殿的遣水士',replace(replace('此卡名的①②③效果１回合仅可各使用１次。\r\n①：自己场上存在“勇者衍生物”的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：将手牌・墓地的此卡除外可以发动。从自己的牌组・墓地将１张“菈玛至崇颂之仪”加入手牌。\r\n③：自己场上存在“勇者衍生物”的情况下可以发动。从牌组将１张记载有“勇者衍生物”的衍生物名的场地魔法卡，以表侧表示放在自己的场地区域。','\r',char(13)),'\n',char(10)),'此卡特殊召唤','检索或回收','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30683373,'盾碎','选择场上１只守备表示的怪兽并将其破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30691817,'海晶少女 海洋天使',replace(replace('等级４以下的“海晶少女”怪兽１只\r\n自己１回合仅可连接召唤“海晶少女 海洋天使”１次。\r\n①：此卡连接召唤的情况下可以发动。从牌组将１张“海晶少女”魔法卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30698243,'绯暗红极超新星龙',replace(replace('协调4只＋协调以外的同步怪兽1只以上\r\n此卡从额外牌组仅可通过以上述卡作为同步素材的同步召唤来特殊召唤。\r\n①：此卡的攻击力上升自己墓地的协调数量×500的数值。\r\n②：场上的此卡不会因对手效果被破坏，对手不可将场上的此卡作为效果的对象。\r\n③：在每个自己・对手回合中1次，可以发动。将此卡及对手场上・墓地的卡全部除外。然后，可从额外牌组将1只“绯暗红新星龙”视为同步召唤特殊召唤。','\r',char(13)),'\n',char(10)),'除外','是否特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30707994,'最大值六','此卡上级召唤成功的情况下发动。掷１次股子，此卡的攻击力上升掷出点数×２００点。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30741334,'热血指导王 巨人训练师',replace(replace('等级8怪兽×3\r\n此卡名的效果1回合最多可使用3次，发动此效果的回合中，自己无法进行战斗阶段。\r\n①：去除此卡的1个超量素材可以发动。自己抽1张，给双方确认。其为怪兽的情况下，进而给予对手800伤害。','\r',char(13)),'\n',char(10)),'抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30741503,'自鸣天琴・伽拉忒亚',replace(replace('包括“自鸣天琴”怪兽在内的效果怪兽2只\r\n此卡名的②效果1回合仅可使用1次。①：连接状态的此卡不会因战斗被破坏。②：以1只被除外的自己的机械族怪兽为对象可以发动。将该怪兽放回牌组。然后，可从牌组将1张“自鸣天琴”魔法・陷阱卡放置在自己场上。','\r',char(13)),'\n',char(10)),'','是否放置魔法·陷阱卡？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30748475,'魔炮战机 达磨羯摩','①：将场上的怪兽全部改成里侧守备表示。然后，场上存在表侧表示怪兽的情况下，其控制者必须将自身场上的表侧表示怪兽全部送至墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30752324,'古之秘仪',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从自己手牌・牌组・墓地将1只通常怪兽以守备表示特殊召唤（从牌组特殊召唤的情况下必须是等级4以下）。自己场上存在通常怪兽卡的情况下，作为代替可从以下效果中挑选1个适用。\r\n●将对手场上的怪兽全部破坏。\r\n●将对手场上的魔法・陷阱卡全部破坏。\r\n●自己抽2张。\r\n●从自己或对手墓地将1只怪兽特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'发动','是否适用其他效果？','破坏怪兽','破坏魔法·陷阱卡','抽牌','特殊召唤','','','','','','','','','','');
INSERT INTO texts VALUES(30752325,'古之秘仪',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从自己手牌・牌组・墓地将1只通常怪兽以守备表示特殊召唤（从牌组特殊召唤的情况下必须是等级4以下）。自己场上存在通常怪兽卡的情况下，作为代替可从以下效果中挑选1个适用。\r\n●将对手场上的怪兽全部破坏。\r\n●将对手场上的魔法・陷阱卡全部破坏。\r\n●自己抽2张。\r\n●从自己或对手墓地将1只怪兽特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'发动','是否适用其他效果？','破坏怪兽','破坏魔法·陷阱卡','抽牌','特殊召唤','','','','','','','','','','');
INSERT INTO texts VALUES(30757127,'命运－英雄 绝命魔侠',replace(replace('“命运－英雄”怪兽＋暗属性效果怪兽\r\n此卡名的效果1回合仅可使用1次。\r\n①：在自己・对手回合中，舍弃1张手牌可以发动。从手牌・牌组将1只“命运－英雄”怪兽送至墓地。然后，自己墓地存在“命运－英雄”怪兽的情况下，自己场上的所有“命运－英雄”怪兽的攻击力直至回合结束时为止，上升自己墓地的“命运－英雄”怪兽数量×200的数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30757396,'血魔・墨非斯特',replace(replace('协调＋１只以上协调以外的怪兽\r\n对手的准备阶段时可以发动。给予对手LP对手场上的卡的数量×３００点伤害。此外，对手放置魔法・陷阱卡时，给予对手LP３００点的伤害。','\r',char(13)),'\n',char(10)),'给与对手伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30761649,'冀望乡－巴利安－',replace(replace('此卡名在规则上也视为“巴利安之”卡。\r\n①：自己场上的“混沌超量”怪兽、“混沌编号”怪兽、“编号101”～“编号107”的“编号”怪兽不会因对手的效果被破坏，对手不可将其作为效果的对象。\r\n②：１回合１次，自己以“升阶魔法”魔法卡的效果特殊召唤了超量怪兽的情况下，以该１只超量怪兽与对手场上的１只怪兽为对象可以发动。将该对手怪兽作为该超量怪兽的超量素材。','\r',char(13)),'\n',char(10)),'对手怪兽作为超量素材','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30765615,'百檎龙－林果虫',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：效果怪兽以外的表侧表示怪兽存在于场上的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：在自己将同步怪兽同步召唤过的回合的自己的主要阶段，将墓地的此卡除外可以发动。将1只“百檎衍生物”（幻龙族・光・星2・攻/守100）特殊召唤至自己场上。自己要以此衍生物作为同步素材的情况下，可视为协调。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30765616,'百檎衍生物','由“百檎龙－林果虫”的效果特殊召唤而来。将此衍生物特殊召唤的玩家以此衍生物作为同步素材的情况下，可将此衍生物视为协调。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30770156,'核心传送装置','１回合１次，可舍弃１张手牌并发动。从牌组将１张“核成之钢核”加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30778711,'阴影食尸鬼','我方墓地每存在１只怪兽，此卡的攻击力上升１００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30786387,'花积',replace(replace('“花积”的②效果１回合只可使用１次。\r\n①：从牌组挑选３种“花札卫”怪兽，依照喜好的顺序返回至牌组上方。\r\n②：可将墓地的此卡除外，并以我方墓地的１只“花札卫”怪兽为对象发动。将该怪兽加入手牌。此效果在此卡被送入墓地的回合不可发动。','\r',char(13)),'\n',char(10)),'卡片顺序','请选择要放到牌组上面的卡','卡片回收','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30794966,'圣刻龙－乌西尔龙','①：此卡可从自己的墓地将龙族・光属性怪兽和龙族通常怪兽各１只除外，来从手牌特殊召唤。②：场上的此卡将被破坏的情况下，可解放自己场上此卡以外的１只表侧表示“圣刻”怪兽作为代替。','是否要使用「圣刻龙－乌西尔龙」的效果代替破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30802207,'驱魔姐妹・惜取魔鬼',replace(replace('此卡名的②③效果1回合仅可各使用1次。\r\n①：双方不可将自己场上的“驱魔姐妹”怪兽作为从墓地被特殊召唤的怪兽的效果的对象。\r\n②：自己将“驱魔姐妹”怪兽超量召唤的情况下，宣言1个卡名可以发动。直至回合结束时为止，与宣言的卡原本卡名相同的卡的效果无效化。\r\n③：自己的“驱魔姐妹”怪兽进行战斗的攻击宣言时，以对手场上的1张魔法・陷阱卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'宣言卡名将其无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30811116,'幻兽机长尾隐形鳐','此卡给予对手生命战斗伤害时，特殊召唤１只“幻兽机衍生物”（机械族・风・星３・攻／守０）。此卡的等级上升相当于我方场上的“幻兽机衍生物”的等级的合计值。只要我方场上存在衍生物，此卡不会因战斗以及卡牌效果被破坏。此外，１回合１次，可释放１只衍生物并发动。选择场上的１张魔法、陷阱卡并破坏。','特殊召唤Token','魔陷破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30811117,'幻兽机衍生物','由名称中带有“幻兽机”的怪兽等的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30822527,'解码语者・扩展',replace(replace('效果怪兽2只以上\r\n①：此卡只要存在于怪兽区域，卡名视为“解码语者”。\r\n②：此卡的攻击力上升此卡连接端的怪兽数量×500的数值。\r\n③：在自己战斗阶段，此卡连接端的怪兽，因战斗被破坏的情况下，或被送至墓地的情况下可以发动。此回合，此卡在1次战斗阶段中可攻击2次。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30829071,'惊乐园的大使＜布佛＞',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：此卡召唤成功时，以自己墓地的１张“游乐设施”陷阱卡和对手场上的１只怪兽为对象可以发动。将墓地的该卡装备于该对手怪兽。\r\n②：以自己１张装备于怪兽的“游乐设施”陷阱卡为对象可以发动。将该卡装备于１只自己场上“惊乐园”怪兽或对手场上的表侧表示怪兽。此效果在对手回合中也可以发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30834988,'召唤限制－猛冲怪兽','此卡存在于场上的场合怪兽特殊召唤成功时，该怪兽变成表侧攻击表示。该回合该怪兽能够攻击的场合必须进行攻击。','变成攻击表示','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30845999,'起动机壳','①：直至回合结束时，场上通常召唤而来的“机壳”怪兽，攻击力上升３００，且效果被无效化，并不受除此卡以外的魔法、陷阱卡效果影响。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30860696,'火箭战士',replace(replace('①：我方的战斗阶段中，此卡不会因战斗而被破坏，此卡因战斗造成的我方的战斗伤害为０。\r\n②：此卡在攻击怪兽的伤害计算后发动。攻击对象怪兽的攻击力直到回合结束时下降５００。','\r',char(13)),'\n',char(10)),'攻击下降','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30864377,'剑斗兽总监 主斗',replace(replace('等级５以上的“剑斗兽”怪兽×２\r\n此卡从额外牌组仅可在将自己场上的上述卡放回牌组・额外牌组的情况下特殊召唤。\r\n此卡不可作为融合素材。\r\n①：１回合１次，可以发动。从额外牌组将“剑斗兽总监 主斗”以外的１只“剑斗兽”融合怪兽无视召唤条件特殊召唤。\r\n②：自己的“剑斗兽”怪兽进行过战斗的战斗阶段结束时，将该１只怪兽放回牌组・额外牌组可以发动。从牌组将１只“剑斗兽”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','请选择要回到牌组的卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30875635,'奇迹除外士',replace(replace('此卡名在规则上也视为“元素－英雄”卡。\r\n此卡名的①②③效果1回合仅可各使用1次。\r\n①：此卡存在于手牌的情况下，从牌组将1只“新空间人”怪兽送至墓地可以发动。将此卡特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下可以发动。将1张记载有“元素－英雄”怪兽的卡名的魔法・陷阱卡加入手牌。\r\n③：此卡被送至墓地的情况下，以对手墓地的1张卡为对象可以发动。将该卡除外。','\r',char(13)),'\n',char(10)),'特殊召唤','检索','除外','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30888983,'方舟之选别','①：自己或对手召唤・反转召唤・特殊召唤怪兽之际支付1000LP可以发动。将场上有同种族怪兽存在的怪兽的召唤・反转召唤・特殊召唤无效，将该怪兽破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30907810,'魔弹邪魔 萨米尔',replace(replace('此卡可通过解放１只“魔弹”怪兽来以表侧表示上级召唤。\r\n此卡名的②效果１回合仅可使用１次。\r\n①：只要此卡存在于怪兽区域，自己可在自己・对手回合中从手牌发动“魔弹”魔法・陷阱卡。\r\n②：在对手的结束阶段可以发动。自己依此回合此卡以表侧表示存在期间内自己所发动的“魔弹”魔法・陷阱卡的数量来抽牌。','\r',char(13)),'\n',char(10)),'把1只「魔弹」怪兽解放表侧表示上级召唤','','适用「魔弹邪魔 萨米尔」的效果来发动','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30913809,'光之波动',replace(replace('此卡名的③效果1回合仅可使用1次。\r\n①：在自己的准备阶段，自己的场地区域不存在“光之结界”的情况下发动。掷1次硬币，掷出反面的情况下，此卡的②③效果直至下个自己的准备阶段为止无效化。\r\n②：自己场上的天使族怪兽的攻击力・守备力上升300。\r\n③：舍弃1张手牌可以发动。从牌组将2只卡名不同的“秘仪之力”怪兽加入手牌。此回合，自己仅可特殊召唤“秘仪之力”怪兽。','\r',char(13)),'\n',char(10)),'掷硬币','攻守上升300','检索','①的效果（此卡的②③的效果直到下次的自己准备阶段无效化）适用中','','','','','','','','','','','','');
INSERT INTO texts VALUES(30914564,'圣鸟仙鹤','①：此卡特殊召唤成功的情况下发动。自己从牌组抽１张。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30915572,'星见兽 加里斯','向对手出示手牌中的此卡可以发动。将自己牌组最上面的卡送往墓地。该卡为怪兽的情况下，给予对手LP相当于该等级×２００点的伤害并特殊召唤此卡。不是的情况下，将此卡破坏。','牌组最上面的卡送至墓地','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30922149,'副作用？','①：对手从牌组抽１～３之间的任意张数。然后，自己恢复对手以此效果抽的数量×２０００的LP。','请选择要抽牌的数量','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30929786,'立炎星－董鸡',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：此卡以“炎星”怪兽的效果特殊召唤时可以发动。从牌组将１只“炎星”怪兽加入手牌。\r\n②：１回合１次，将自己场上的１张表侧表示的“炎舞”魔法・陷阱卡送至墓地可以发动。从牌组将１张“炎舞”魔法・陷阱卡放置在自己场上。','\r',char(13)),'\n',char(10)),'牌组检索','放置','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30936186,'核成原始骑士','此卡的控制者在每次我方的结束阶段，从手牌将１张“核成之钢核”送入墓地，或向对手展示１只手牌的兽战士族怪兽。或者，不执行上述任何一项破坏此卡。１回合１次，可向对手展示１张手牌的“核成之钢核”并发动。从牌组特殊召唤１只除“核成原始骑士”以外的等级４或以下冠有“核成”之名的怪兽。','选择一张「核成之钢核」送至墓地','选择一张兽战士族怪兽给对手观看','破坏「核成原始骑士」','特殊召唤','','','','','','','','','','','','');
INSERT INTO texts VALUES(30945251,'雷盟－电压过载',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：以场上的1张表侧表示卡为对象可以发动。将该卡破坏。此回合，自己不可从手牌以外的地方特殊召唤效果怪兽。\r\n②：此卡存在于墓地的状态下，以自己的“雷盟”卡的效果破坏了卡的情况下可以发动。将此卡加入手牌。','\r',char(13)),'\n',char(10)),'发动','回收','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30964246,'阿尔戈☆群星－巨人讨灭',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：从牌组将1只“阿尔戈☆群星”怪兽加入手牌。自己的怪兽区域存在永续陷阱卡的情况下，或自己的魔法与陷阱区域存在拥有以自身作为怪兽特殊召唤的效果的永续陷阱卡的情况下，进而可进行1只战士族怪兽的召唤。\r\n②：在自己的主要阶段将墓地的此卡除外，以包含自己场上的“阿尔戈☆群星”永续陷阱卡在内的场上的2张卡为对象可以发动。将该卡放回手牌。','\r',char(13)),'\n',char(10)),'检索','回到手牌','是否进行召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30968774,'交换祭司',replace(replace('此卡牌名的效果１回合只可使用１次。\r\n①：此卡作为连接素材被送入墓地的场合可发动。以此卡作为连接素材之连接怪兽的攻击力下降５００。之后，我方从牌组抽取１张卡牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30979619,'秘旋谍装备－大红',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：以自己墓地的１只“秘旋谍”怪兽为对象可以发动此卡。将该怪兽特殊召唤，装备此卡。\r\n②：装备怪兽不会因战斗被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30983281,'加速同步・星尘龙',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡同步召唤的情况下可以发动。从自己墓地将1只等级2以下的协调特殊召唤。\r\n②：在自己・对手的主要阶段，解放此卡可以发动。从额外牌组将1只“星尘龙”视为同步召唤特殊召唤。然后，进行1只同步怪兽的同步召唤。以此效果同步召唤的怪兽在此回合不受对手发动的效果影响。','\r',char(13)),'\n',char(10)),'特殊召唤','同步召唤','「加速同步星尘龙」效果适用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30989084,'芬芳夜魔－迷迭香',replace(replace('植物族怪兽２只以上\r\n此卡名的①②③效果１回合仅可各使用１次。\r\n①：此卡特殊召唤的情况下可以发动。从牌组将１张“芬芳”卡加入手牌。\r\n②：自己的LP恢复的情况下可以发动（在伤害步骤也可以发动）。从手牌将最多３只“芬芳”怪兽特殊召唤至此卡连接端的自己场上。\r\n③：解放此卡连接端的１只怪兽，以场上的１张卡为对象可以发动。将该卡除外，自己恢复１０００LP。','\r',char(13)),'\n',char(10)),'检索','从手牌特殊召唤','卡片除外','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30996652,'机块重用','①：可以以自己墓地的1只“机块”怪兽为对象发动。特殊召唤该怪兽。此效果特殊召唤的怪兽离开场上时，返回持有者牌组的最下方。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(30998403,'DDD 天空王宙斯诸神黄昏',replace(replace('“DD”怪兽2只以上\r\n此卡名的②效果1回合仅可使用1次。\r\n①：以自己场上的1张“DD”卡或“契约书”卡为对象可以发动。将该卡破坏。此回合，自己在通常的灵摆召唤之外，可在自己的主要阶段追加1次灵摆召唤“DD”怪兽。\r\n②：对手发动手牌的怪兽的效果时，从自己墓地将1只“DD”怪兽和1张“契约书”卡除外可以发动。将该发动无效。','\r',char(13)),'\n',char(10)),'破坏并获得额外灵摆','发动无效','使用「DDD 天空王宙斯诸神黄昏」的效果灵摆召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31000575,'征兵令','翻阅对手牌组最上面的１张卡牌。翻阅的卡牌是能够通常召唤的怪兽的场合，特殊召唤至我方场上。若为其他卡牌的场合，将该卡加入对手手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31002402,'凶教导之福音','“教导”仪式怪兽的降临所必需。此卡名的卡１回合仅可发动１张。①：为使合计等级与仪式召唤的怪兽相等，解放自己手牌・场上的怪兽，或将１只等级与仪式召唤怪兽相同的怪兽从额外牌组送至墓地，从手牌将１只“教导”仪式怪兽仪式召唤。此卡发动后，直至回合结束时为止，自己不可从额外牌组特殊召唤怪兽。','是否把怪兽从额外牌组送至墓地作为素材？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31006879,'骑乘决斗！加速！',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：作为此卡发动时的效果处理，自己场上不存在其他卡的情况下，可从牌组将1只“同步士”怪兽加入手牌。\r\n②：在自己的准备阶段发动。在此卡上放1个信号计数物。\r\n③：去除自己场上的2个信号计数物，将魔法与陷阱区域表侧表示的此卡送至墓地可以发动。自己抽2张。然后，挑选自己的1张手牌送至墓地。','\r',char(13)),'\n',char(10)),'是否从牌组把1只「同步士」怪兽加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31010081,'终刻狱徒 迪亚克特罗斯',replace(replace('等级4怪兽×2\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡特殊召唤的情况下可以发动。将自己手牌・场上（表侧表示）的1张“终刻”卡破坏。然后，可将场上的1只怪兽破坏。\r\n②：持有“终刻”怪兽或“无垢者 墨迪乌斯”作为超量素材的此卡因效果被破坏的情况下可以发动。从牌组挑选1张装备魔法卡，加入手牌或送至墓地。','\r',char(13)),'\n',char(10)),'破坏','检索','是否把场上怪兽破坏？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31034919,'上膛狂魔','①：此卡因战斗被破坏并被送至墓地的情况下发动。挑选2张手牌送至墓地，自己从牌组抽2张。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31036355,'强制转移','①：双方各自挑选1只自身场上的怪兽。该2只怪兽的控制权交换。此回合，不可变更该怪兽的表示形式。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31038159,'创世龙','①：1回合1次，从手牌将1只龙族怪兽送至墓地，可以自己墓地的1只龙族怪兽为对象发动。将该龙族怪兽加入手牌。②：此卡从场上被送至墓地时可以发动。将自己墓地的所有龙族怪兽放回牌组。','加入手牌','返回牌组','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31042659,'霸蛇大公 戈尔钢达','此卡名的①③效果１回合仅可各使用１次。①：此卡存在于手牌・墓地，自己的场地区域有表侧表示的卡存在的情况下可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡离开场上的情况下，将其除外。②：只要场上有“大砂海 黄金的戈尔钢达”存在，此卡原本的攻击力变为３０００。③：场上的“大砂海 黄金的戈尔钢达”将被效果破坏的情况下，可将自己墓地的１只怪兽除外作为代替。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31044787,'太刀鼬的大爆发','①：对手场上表侧表示怪兽的攻击力的合计数值高于自己LP的情况下可以发动。为使对手场上表侧表示怪兽的攻击力合计数值为自己的LP以下，对手必须挑选自身场上攻击力０以外的表侧表示怪兽放回持有者的牌组。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31053337,'黑羽－激震的亚布罗欧罗斯','此卡不可特殊召唤。１回合１次，在我方主要阶段１可发动。此卡的攻击力下降１０００点，将对手魔法与陷阱区域的所有卡牌返回至持有者手牌。与此卡进行了战斗的怪兽，在该战斗中不会被破坏并在伤害计算后返回至持有者手牌。','对手魔法陷阱区的卡全部回到手牌','战斗的怪兽回到手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31059809,'寂静海刺',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己场上存在水属性怪兽的情况下可以发动（发动此效果的回合中，自己仅可特殊召唤水属性怪兽）。从手牌将此卡特殊召唤。\r\n②：将墓地的此卡除外，以自己墓地的最多３只水属性怪兽为对象可以发动。将该怪兽放回牌组。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31061682,'星际仙踪－多萝塞尔',replace(replace('“星际仙踪－多萝塞尔”的①效果１回合仅可使用１次。\r\n①：将场上的此卡除外可以发动。从手牌将１只等级４以上的“星际仙踪”怪兽特殊召唤。此效果在对手回合中也可以发动。\r\n②：此卡给予对手战斗伤害时，支付５００LP可以发动。从牌组将１张“星际仙踪”卡加入手牌。','\r',char(13)),'\n',char(10)),'从手牌把「星际仙踪」怪兽特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31066283,'骷髅骑士的复活','用于召唤“骷髅骑士”。必须从手牌・我方场上解放合计等级达到６以上的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31076103,'第一棺材','每当对手的回合结束阶段，从手牌或牌组将“第二棺材”“第三棺材”按顺序放置于自己的魔法与陷阱区域。自己场上的“第一棺材”“第二棺材”“第三棺材”任意一个离场时将这些卡片全部送入墓地。所有卡片在自己场上集齐时，将这些卡片全部送入墓地并从手牌或牌组特殊召唤１“法老王的灵魂”。','放置','特殊召唤','请选择要表侧表示放到自己场上的卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31077447,'惊奇箱','①：对手场上存在有２只或以上怪兽的场合，在对手怪兽的攻击宣言时，可以１只该怪兽为对象发动。使该攻击无效，挑选对手场上除该怪兽以外的１只怪兽并送入墓地。之后，下降对象怪兽的攻击力，其数值相当于被送入墓地之怪兽的攻击力与守备力之内数值较高一方的数值。','攻击无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31086840,'编号69 徽章神 盾徽－神之遮断',replace(replace('等级4怪兽×4\r\n此卡也可重叠在自己场上原本卡名为“编号69 徽章神 盾徽”的怪兽上面来超量召唤。\r\n此卡名的效果1回合仅可使用1次。\r\n①：对手场上的怪兽发动效果时，或对手怪兽攻击宣言时可以发动。从额外牌组将1只“编号69 徽章神 盾徽－神之狂怒”重叠在自己场上的此卡上面视为超量召唤特殊召唤。然后，将该1只对手怪兽破坏。','\r',char(13)),'\n',char(10)),'是否在「编号69 徽章神 盾徽」上面重叠来超量召唤？','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31102447,'亚马逊的斥候',replace(replace('此卡牌名的①效果１回合只可使用１次。\r\n①：可向对手展示除此卡以外的手牌的１只“亚马逊”并发动。从手牌特殊召唤此卡。\r\n②：此卡因战斗被破坏并送入墓地时，可以除“亚马逊的斥候”以外的我方墓地的１只“亚马逊”怪兽为对象发动。将该怪兽返回至手牌或牌组。','\r',char(13)),'\n',char(10)),'此卡从手牌特殊召唤','怪兽回到手牌或者牌组','是否回到手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31111109,'元素－英雄 神新宇侠','此卡仅可以融合召唤特殊召唤。以冠有“新宇侠”、“新空间人”、“－英雄”之名的怪兽各１只或以上，合计５只怪兽为融合素材融合召唤。１回合１次，可将我方墓地冠有“新宇侠”、“新空间人”、“－英雄”之名怪兽中的任意１只从游戏中除外并发动。此卡的攻击力上升５００点，直至结束阶段时，获得与该怪兽相同的效果。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31114334,'强袭黑羽－丛云之草薙',replace(replace('协调＋协调以外的怪兽1只以上\r\n①：以“黑羽”怪兽作为素材同步召唤的此卡视为协调。\r\n②：此卡同步召唤时适用。此卡的攻击力直至回合结束时为止，上升相当于作为其同步素材的同步怪兽的原本攻击力的合计数值。\r\n③：此卡可攻击所有对手怪兽各1次，攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31118030,'占卜姬弓箭西尔芙','①：此卡反转的场合可发动。从我方牌组、墓地挑选１张仪式魔法卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31122090,'逆转女神','以神圣之力保护弱者，并赋予他们扭转局势之力的女神。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31122091,'逆转女神','以神圣之力保护弱者，并赋予他们扭转局势之力的女神。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31123642,'ZEXAL从者－霍普贤者',replace(replace('等级４怪兽×２\r\n此卡名的①效果１回合仅可使用１次。①：去除此卡的２个超量素材可以发动。从牌组将１只“ZEXAL兵器”怪兽或“ZEXAL从者”怪兽特殊召唤。此效果发动后，直至回合结束时为止，自己从额外牌组仅可特殊召唤超量怪兽，仅可用“编号”怪兽攻击。②：除“ZEXAL从者－霍普贤者”以外，自己场上原本属性为光属性的“霍普”超量怪兽将被战斗・效果破坏的情况下，可将场上・墓地的此卡除外作为代替。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31149212,'怒刹帝利・拉眦哈忒','此卡名的①②效果１回合仅可各使用１次。①：自己场上存在“怒刹帝利”怪兽的情况下可以发动。从手牌将此卡特殊召唤。此回合，自己从额外牌组仅可特殊召唤超量怪兽。②：在此卡召唤・特殊召唤成功的回合的自己的主要阶段，从牌组将“怒刹帝利・拉眦哈忒”以外的１张“怒刹帝利”卡除外可以发动。从对手的牌组上面将３张卡以里侧表示除外，此卡的等级变为７。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31173519,'雷骑士','此卡与对手怪兽进行了战斗的场合，只要该怪兽以表侧表示存在于场上就不可进行攻击。','攻击限制','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31175914,'攻击吸收者','此卡作为同步召唤素材被送入墓地的场合，选择对手场上的１只表侧表示怪兽，并直至回合结束时该攻击力下降１０００点。','攻击下降','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31178212,'威风魔灵・独角麒麟',replace(replace('←2 【灵摆】 2→\r\n【怪兽效果】\r\n此卡名的①怪兽效果１回合仅可使用１次。\n①：在自己・对手回合中，以自己怪兽区域的１只灵摆怪兽和对手场上的１只怪兽为对象可以发动。将该怪兽放回手牌。\n②：只要此卡存在于怪兽区域，此卡不会被对手的效果破坏，对手不可将此卡作为效果的对象。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31181711,'超重武者装魂 长城',replace(replace('①：可在我方主要阶段以我方场上１只“超重武者”怪兽为对象发动。从我方手牌、场上将此怪兽视为守备力上升１２００的装备卡装备我方怪兽。\r\n②：因此卡效果装备有此卡的怪兽被选择为攻击对象时，可将被装备的此卡送入墓地并发动。使该攻击无效，并将装备怪兽的守备力变成０。','\r',char(13)),'\n',char(10)),'装备','攻击无效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31189536,'吸血鬼觉醒','这个卡名的卡在1个回合只可发动1张。①：从牌组特殊召唤1只“吸血鬼”怪兽。用这个效果特殊召唤的怪兽将在这个回合的结束阶段被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31213049,'XX排除','①：对手发动手牌的怪兽的效果时可以发动。将该发动无效。对手有手牌的情况下，进而对手挑选１张手牌舍弃。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31222701,'摇摆的视线',replace(replace('①：将双方灵摆区域的卡全部破坏。然后，依以此效果破坏的卡的数量适用以下效果。\r\n●1张以上：给予对手500伤害。\r\n●2张以上：可从牌组将1只灵摆怪兽加入手牌。\r\n●3张以上：可挑选场上的1张卡除外。\r\n●4张：可从牌组将1张“摇摆的视线”加入手牌。','\r',char(13)),'\n',char(10)),'是否从牌组把1只灵摆怪兽加入手牌？','是否选场上1张卡除外？','是否从牌组把1张「摇摆的视线」加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31226177,'星杯龙 伊姆杜克',replace(replace('衍生物以外的通常怪兽1只\r\n①：只要此卡存在于怪兽区域，自己在通常召唤外仅可追加1次，在自己的主要阶段召唤1只“星杯”怪兽。②：此卡在与此卡连接端的对手怪兽进行战斗的伤害步骤开始时可以发动。将该对手的怪兽破坏。③：此卡从场上被送至墓地的情况下可以发动。从手牌将1只“星杯”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','使用「星杯龙 伊姆杜克」的效果召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31230289,'涂yā兽－jiàn龙',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己场上不存在怪兽的情况下，或仅有恐龙族怪兽的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从牌组将１张“涂yā本”魔法・陷阱卡加入手牌。然后，挑选自己的１张手牌舍弃。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31241087,'超越恐龙 厄兆陨龙',replace(replace('此卡不可通常召唤，仅可以卡的效果特殊召唤。\r\n此卡名的①②③效果１回合仅可各使用１次。\r\n①：在对手回合可以发动。将自己的手牌・场上（表侧表示）此卡以外的２只恐龙族怪兽破坏，从手牌将此卡特殊召唤。\r\n②：此卡特殊召唤的情况下可以发动。从牌组将１只恐龙族怪兽送至墓地。\r\n③：此卡被破坏的情况下可以发动。从自己的墓地将１只通常怪兽放回牌组。然后，可将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','是否将此卡特殊召唤？','','','','','','','','','','','','');
INSERT INTO texts VALUES(31242786,'食魂','全身充满谜团的超生命体。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31245780,'战斗狂','可在对手准备阶段时发动。对手场上表侧表示的所有怪兽变成攻击表示，此回合不可变更表示形式。此回合能够攻击的场合必须攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31247589,'剑斗兽迪卡埃利','此卡因冠有“剑斗兽”之名怪兽的效果而特殊召唤成功的场合，此卡可在１次的战斗阶段中攻击２次。此卡进行了战斗的战斗阶段结束时，可将此卡返回至持有者牌组并发动。从牌组特殊召唤１只除“剑斗兽迪卡埃利”以外的冠有“剑斗兽”之名的怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31259606,'绝海之泌泪','此卡名的①②效果１回合仅可各使用１次。①：此卡召唤・特殊召唤成功的情况下可以发动。从牌组将“绝海之泌泪”以外的１只水族怪兽送至墓地。②：在自己的结束阶段解放此卡，以自己墓地的１只“绝海之泌泪”以外的水族怪兽为对象可以发动。将该怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31281980,'治愈波浪','１回合１次，可选择我方场上１只除此卡以外的表侧表示怪兽并发动。我方回复相当于被选择怪兽等级×１００LP。','LP回复','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31286915,'K9－EX “割裂者／千”',replace(replace('等级9怪兽×2\r\n此卡名的①③效果1回合仅可各使用1次。\r\n①：此卡以“K9”魔法・陷阱卡的效果特殊召唤的情况下，以对手墓地・除外状态的最多2张卡为对象可以发动。将该卡放回牌组。\r\n②：此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。\r\n③：对手发动怪兽的效果时，去除此卡的2个超量素材可以发动。将该效果无效。然后，将场上的卡全部破坏。','\r',char(13)),'\n',char(10)),'回牌组','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31292357,'娱乐巫师・帽子戏法师','①：场上有2只以上怪兽存在的情况下，此卡可从手牌中特殊召唤。②：给予自己伤害的魔法・陷阱・怪兽的效果发动时可以发动。在此卡上放1个娱乐巫师计数物（最多3个）。然后，自己因该效果受到的伤害改成0。③：此卡上放了3个娱乐巫师计数物时，此卡的攻击力・守备力变为3300。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31303283,'阳炎兽 骏鹰','只要此卡以表侧表示存在于场上，对手就不可以此卡作为卡牌效果的对象。此外，１回合１次，可释放我方场上１只除此卡以外的炎属性怪兽并发动。此卡的攻击力上升３００点。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31305911,'棉花糖',replace(replace('①：此卡不会因战斗被破坏。\r\n②：在对里侧表示的此卡的进行攻击的伤害计算后发动。给予攻击的玩家１０００伤害。','\r',char(13)),'\n',char(10)),'1000伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31305912,'棉花糖',replace(replace('①：此卡不会因战斗被破坏。\r\n②：在对里侧表示的此卡的进行攻击的伤害计算后发动。给予攻击的玩家１０００伤害。','\r',char(13)),'\n',char(10)),'1000伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31313405,'转生炎兽 浴火不死鸟',replace(replace('炎属性的效果怪兽2只以上\r\n此卡名的②③效果1回合仅可各使用1次。①：此卡以“转生炎兽 浴火不死鸟”为素材连接召唤成功的情况下可以发动。将对手场上的卡全部破坏。②：以对手墓地的1只连接怪兽为对象可以发动。将该怪兽特殊召唤至对手场上。③：连接怪兽被特殊召唤至对手场上的情况下，以该1只怪兽为对象可以发动。给予对手该怪兽的原本攻击力数值的伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31314549,'急袭猛禽－鸣啭伯劳','此卡名以①方法的特殊召唤1回合仅可进行1次。①：自己场上有超量怪兽存在的情况下，此卡可从手牌中特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31320433,'编号47 梦魇鲨',replace(replace('等级３怪兽×２\r\n此卡特殊召唤成功时可发动。从我方手牌、场上挑选１只水属性、等级３怪兽，重叠至此卡的下方当作超量素材。此外，１回合１次，可移除此卡的１个超量素材，并选择我方场上的１只水属性怪兽发动。此回合，被选择怪兽以外的怪兽不可进行攻击，被选择怪兽可直接攻击对手玩家。','\r',char(13)),'\n',char(10)),'增加素材','直接攻击','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31322640,'魅惑宫殿',replace(replace('此卡名的③效果１回合最多可使用３次。\r\n①：自己场上的魔法师族怪兽的攻击力・守备力上升５００。\r\n②：自己场上的“魅惑女王”效果怪兽获得以下效果。\r\n●将以自身效果装备有卡的此卡送至墓地可以发动。从手牌・牌组将１只攻击力１５００以下的魔法师族怪兽特殊召唤。\r\n③：将１张手牌送至墓地可以发动。从牌组挑选１只“魅惑女王”怪兽，加入手牌或特殊召唤至对手场上。','\r',char(13)),'\n',char(10)),'特殊召唤（魅惑宫殿）','选牌组「魅惑女王」怪兽','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31328739,'念动力脉冲','①：解放自己场上的1只念动力族怪兽可以发动。将对手手牌全部放回牌组。然后，对手抽3张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31339260,'不死战士','“白骨”＋“格斗战士 阿提米特”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31353051,'炸裂枪弹龙','此卡名的①②效果1回合仅可各使用1次。①：以场上的此卡作为对象的连接怪兽的效果发动时可以发动。将此卡破坏。然后，双方受到2000伤害。②：场上的此卡因战斗・效果被破坏并被送至墓地的回合的结束阶段可以发动。从牌组将1只“炸裂枪弹龙”以外的“枪弹”怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31374201,'海造贼－舵手 白胡子',replace(replace('具此卡名的①②效果１回合各只能使用１次。\r\n①：在对手回合可发动。从额外牌组特殊召唤１只与对手场上／墓地中任意怪兽属性相同的“海造贼”怪兽，我方场上的此卡作为装备卡给该怪兽装备。\r\n②：此卡被从手牌／怪兽区送至墓地时可发动。从卡组中特殊召唤１只除“海造贼－舵手 白胡子”以外的“海造贼”怪兽。此回合我方无法特殊召唤“海造贼”以外的怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31383545,'XX－军刀 暗魂','①：在此卡从自己场上被送至墓地的回合的结束阶段可以发动。从牌组将1只“X－军刀”怪兽加入手牌。','牌组检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31385077,'混沌神女－混元的女神－',replace(replace('光属性协调＋２只以上协调以外的暗属性怪兽\r\n①：１回合１次，从手牌将１只光属性怪兽送至墓地，以自己墓地１只等级５以上的暗属性怪兽为对象可以发动。将该怪兽特殊召唤。以此效果特殊召唤的怪兽不可作为同步素材。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31386180,'始祖保卫者提拉斯',replace(replace('等级5怪兽×2\r\n如果此卡没有超量素材，则不会适用此卡的效果。①：场上的此卡不会因效果被破坏。②：此卡进行了战斗的战斗阶段结束时，可以1张对手场上的卡为对象发动。破坏该张对手的卡。③：在自己的结束阶段发动。去除此卡的1个超量素材。','\r',char(13)),'\n',char(10)),'选择对手场上存在的1张卡破坏','取除1个超量素材','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31398842,'超量之力',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从牌组将“超量之力”以外的1张“超量”卡送至墓地。以超量怪兽作为超量素材的超量怪兽存在于场上的情况下，也可不送至墓地而是加入手牌。\r\n②：从墓地将不是在此回合被送至墓地的此卡除外可以发动。去除场上的1个超量素材。去除的超量素材为超量怪兽的情况下，进而可将自己墓地・除外状态的该超量怪兽以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'','取除超量素材','是否加入手牌？','是否特殊召唤？','','','','','','','','','','','','');
INSERT INTO texts VALUES(31411835,'百臂无形手 坦达洛撕',replace(replace('“百臂无形”怪兽×2\r\n此卡名的①效果1回合仅可使用1次。\r\n①：以对手场上的1只怪兽为对象可以发动。获得该怪兽的控制权。\r\n②：只要此卡存在于怪兽区域，自己的“百臂无形”融合怪兽及原本持有者为对手的自己怪兽可直接攻击。\r\n③：此卡与怪兽进行战斗的情况下，该2只不会因该战斗被破坏。','\r',char(13)),'\n',char(10)),'获取控制权','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31423101,'神剑－凤凰剑','仅限装备战士族怪兽。装备怪兽的攻击力上升３００点。此卡存在于墓地的场合，可将我方墓地的２只战士族怪兽从游戏中除外并发动。将墓地的此卡加入手牌。','此卡加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31425736,'杯糕喵☆黯蜜',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次，且②效果1回合仅可使用1次。\r\n①：自己场上存在连接1怪兽或等级2的同步怪兽的情况下，此卡可从手牌特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从牌组将“杯糕喵☆黯蜜”以外的1张“黯蜜”卡加入手牌。以同步怪兽的效果特殊召唤的情况下，作为代替自己也可抽1张。','\r',char(13)),'\n',char(10)),'','检索','是否作为代替抽牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31434645,'被诅咒的埃尔德兰德',replace(replace('此卡名的②③效果1回合仅可各使用1次。\r\n①：只要此卡存在于魔法与陷阱区域，自己仅可用不死族怪兽攻击宣言。\r\n②：支付800LP可以发动。从牌组将1只“埃尔德里奇”怪兽或1张“黄金乡”魔法・陷阱卡加入手牌。\r\n③：此卡被从魔法与陷阱区域送至墓地的情况下可以发动。从牌组将1只“埃尔德里奇”怪兽或1张“黄金乡”魔法・陷阱卡送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31437713,'编号82 心园小龙',replace(replace('等级４怪兽×２\r\n①：只要自己场上有魔法卡以表侧表示存在，对手不可将此卡选择为攻击对象。②：１回合１次，去除此卡的１个超量素材可以发动。此回合，自己的其他怪兽不可攻击，此卡可以直接攻击。','\r',char(13)),'\n',char(10)),'直接攻击','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31440046,'调皮宝贝・岩石娃',replace(replace('具此卡名的效果１回合只能使用１次。\r\n①：此卡仅在作为“调皮宝贝”怪兽的融合素材或连接素材被送至墓地时可发动。从我方手牌除外１张卡，从我方卡组抽１张卡。然后，从手牌／卡组中将除“调皮宝贝・岩石娃”外的１只“调皮宝贝”怪兽以守备状态特殊召唤。','\r',char(13)),'\n',char(10)),'','是否特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31440542,'幻惑的大王花','反转：选择对手场上的１只表侧表示怪兽，直至结束阶段时获得其控制权。','获得控制权','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31443476,'速攻轮转','①：从牌组将1只“枪弹”怪兽特殊召唤。以此效果特殊召唤的怪兽不可攻击，将在结束阶段被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31444249,'炼狱的虚梦',replace(replace('①：只要此卡存在于魔法与陷阱区域，自己场上原本等级为２以上的“狱炎机”怪兽的等级变为１，那些怪兽给予对手的战斗伤害变为一半。\r\n②：将魔法与陷阱区域表侧表示的此卡送至墓地可以发动。将自己的手牌・场上的怪兽作为融合素材，将１只“狱炎机”融合怪兽融合召唤。被从额外牌组特殊召唤的怪兽仅存在于对手场上的情况下，可将自己牌组的最多６只怪兽也作为融合素材。','\r',char(13)),'\n',char(10)),'是否还要从牌组选择融合素材？','是否还要从手牌·场上选择融合素材？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31444250,'炼狱的虚梦',replace(replace('①：只要此卡存在于魔法与陷阱区域，自己场上原本等级为２以上的“狱炎机”怪兽的等级变为１，那些怪兽给予对手的战斗伤害变为一半。\r\n②：将魔法与陷阱区域表侧表示的此卡送至墓地可以发动。将自己的手牌・场上的怪兽作为融合素材，将１只“狱炎机”融合怪兽融合召唤。被从额外牌组特殊召唤的怪兽仅存在于对手场上的情况下，可将自己牌组的最多６只怪兽也作为融合素材。','\r',char(13)),'\n',char(10)),'是否还要从牌组选择融合素材？','是否还要从手牌·场上选择融合素材？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31447217,'织翼者','拥有６翼的高级天使。主宰人们的自由与希望。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31456110,'邪蚀 魔像','１回合１次，可选择场上１只除暗属性以外等级５或以上的怪兽并破坏。','怪兽破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31458630,'幻奏协奏曲',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：以自己手牌・场上的怪兽作为融合素材，将１只天使族融合怪兽融合召唤。在此之际，存在于自己的灵摆区域的融合素材怪兽也可作为融合素材使用。\r\n②：此卡存在于墓地的状态下，“幻奏”融合怪兽被送至自己墓地的情况下可以发动（伤害步骤也可以发动）。将此卡放回牌组最下面。然后，自己抽１张。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31461282,'开运奇迹石',replace(replace('①：我方场上仅可有１张“开运奇迹石”以表侧表示存在。\r\n②：我方场上的魔法师族怪兽的攻击力、守备力，上升我方场上的“占卜魔女”怪兽种类×５００。\r\n③：１回合１次，我方的“占卜魔女”怪兽发动进行战斗的攻击宣言时可发动。我方从牌组抽取１张卡牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31464658,'三眼死灵',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：将场上的此卡送至墓地可以发动。从牌组将1只暗属性・等级10怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31467372,'不死式冥界炮','１回合１次，不死族怪兽被特殊召唤至自己场上的情况下发动。给予对手LP８００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31467949,'空牙团的飞哨 莉空','这个卡名的①②的效果1个回合各只可使用1次。①：自己主要阶段可以发动。从手牌特殊召唤“空牙团的飞哨 莉空”以外的1只“空牙团”怪兽。②：这张卡已存在于怪兽区域的状态下，且这张卡以外的“空牙团”怪兽被特殊召唤至自己场上的情况下，可以场上1张放置的卡为对象发动。破坏该卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31472884,'共斗',replace(replace('此卡发动的回合，我方怪兽不可直接攻击。\r\n①：可从手牌舍弃１只怪兽，以场上表侧表示的１只怪兽为对象发动。直至回合结束时，该怪兽的攻击力、守备力变成以发动此卡为目的而舍弃的怪兽的攻击力、守备力数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31476755,'沙尘之结界','场上所有表侧表示的通常怪兽不受对手魔法卡效果的影响。此卡会在发动后我方的第２个准备阶段时被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31477025,'火山先生','操纵火焰的绅士。平时温文尔雅，但发起怒来十分恐怖。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31480215,'幻兽机暴风雪莺','此卡作为机械族怪兽的同步召唤素材被送入墓地的场合，特殊召唤１只“幻兽机衍生物”（机械族・风・星３・攻／守０）。发动此效果的回合，我方只可特殊召唤风属性怪兽。只要我方场上存在有衍生物，此卡不会因战斗及效果被破坏。此外，可释放我方场上１只冠有“幻兽机”之名的怪兽并发动。此卡的等级上升１级。“幻兽机暴风雪莺”的效果１回合只可使用１次。','特殊召唤衍生物','等级上升','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31480216,'幻兽机衍生物','由名称中带有“幻兽机”的怪兽等的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31516413,'圣刻龙－奈芙蒂龙','①：此卡可解放自己场上的１只“圣刻”怪兽来从手牌特殊召唤。②：１回合１次，从自己的手牌・场上解放此卡以外的１只“圣刻”怪兽，以对手场上的１只怪兽为对象可以发动。将该对手的怪兽破坏。③：此卡被解放的情况下发动。从自己的手牌・牌组・墓地挑选１只龙族通常怪兽，将其攻击力・守备力改成０并特殊召唤。','破坏','特殊召唤','出场方式为特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31525442,'预见者 卓尔加',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己场上有“预见者 卓尔加”以外的天使族・地属性怪兽存在的情况下可以发动。从手牌将此卡特殊召唤。然后，自己从自己及对手的牌组上面各确认最多５张。\r\n②：解放此卡来召唤的怪兽的攻击宣言时，将墓地的此卡除外可以发动。将该怪兽破坏，给予对手２０００伤害。','\r',char(13)),'\n',char(10)),'','','请选择自己牌组的要确认的数量','请选择对方卡组的要确认的数量','解放「预见者 卓尔加」作召唤','','','','','','','','','','','');
INSERT INTO texts VALUES(31531170,'共鸣振动','①：对手灵摆区存在有２张卡牌的场合，可以该２张卡牌为对象发动。该２张卡牌存在于对手的灵摆区，且此回合我方进行灵摆召唤的场合，可使用对手的灵摆刻度１组进行灵摆召唤。该场合，只可从额外牌组灵摆召唤怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31531914,'破械式鬼 修摩',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤的情况下可以发动。从牌组将“破械式鬼 修摩”以外的、1只等级4以下的“破械”怪兽特殊召唤。然后，将自己场上的1张卡破坏。此回合，自己仅可特殊召唤恶魔族怪兽。\r\n②：场上的此卡因战斗或“破械式鬼 修摩”以外的卡的效果被破坏的情况下可以发动。从手牌・牌组将“破械式鬼 修摩”以外的1只“破械”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'从牌组特殊召唤','从手牌·牌组特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31533473,'小丑戏帮 迪亚波罗',replace(replace('属性相同而种族不同的怪兽×2\r\n①：上级召唤的自己的怪兽攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值的两倍来给予对手战斗伤害。\r\n②：此卡被解放的情况下，可从以下效果中选择1个发动（此卡名的以下效果1回合仅可各选择1次）。\r\n●将双方场上・墓地的融合怪兽全部放回额外牌组。\r\n●从牌组将1张“小丑戏帮”陷阱卡放置在自己场上。','\r',char(13)),'\n',char(10)),'选择效果','回收融合怪兽','放置陷阱卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31533704,'幻兽机盗龙猛禽','特殊召唤衍生物至我方场上时，特殊召唤１只“幻兽机衍生物”（机械族・风・星３・攻／守０）。“幻兽机盗龙猛禽”的此效果１回合只可使用１次。此卡的等级上升相当于我方场上的“幻兽机衍生物”的等级的合计值。只要我方场上存在衍生物，此卡不会因战斗以及卡牌效果被破坏。此外，１回合１次，可释放１只衍生物并发动。从牌组将１只冠有“幻兽机”之名的怪兽加入手牌。','特殊召唤Token','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31533705,'幻兽机衍生物','由名称中带有“幻兽机”的怪兽等的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31539614,'疫苗护士',replace(replace('等级3怪兽×2只以上\r\n①：在自己・对手回合中，去除此卡的1个超量素材，以攻击力或守备力与原本数值不同的、场上的1只怪兽为对象可以发动。该怪兽的攻击力・守备力变为原本的数值。以自己场上的怪兽为对象发动的情况下，进而该怪兽在此回合不会因战斗・效果被破坏。\r\n②：1回合1次，其他怪兽被特殊召唤至自己场上的情况下，如果此卡的超量素材为3个以上则可以发动。该怪兽的攻击力上升900。','\r',char(13)),'\n',char(10)),'攻守变原本并破坏耐性','攻击力上升','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31548215,'自掘空洞','①：对手发动手牌・墓地・除外状态的怪兽的效果时可以发动。将该效果无效，给予对手２０００伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31548814,'炼狱的狂宴','①：将自己的手牌・场上（表侧表示）的１张“炼狱”魔法・陷阱卡送至墓地可以发动。从牌组将等级合计为８的、最多３只“狱炎机”怪兽无视召唤条件特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31550470,'暗次元的解放','①：可以1只被除外的自己的暗属性怪兽为对象发动此卡。将该怪兽特殊召唤。此卡从场上离开时，该怪兽将被破坏并除外。该怪兽被破坏时将此卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31552317,'水晶机巧・内蕴',replace(replace('此卡名的卡1回合仅可发动1张，此卡名的③效果1回合仅可使用1次。\r\n①：作为此卡发动时的效果处理，可从牌组将“水晶机巧・内蕴”以外的1张“水晶机巧”卡加入手牌。\r\n②：自己的“水晶机巧”怪兽1回合仅各1次，不会因战斗被破坏。\r\n③：将墓地的此卡除外，以自己墓地的1只“水晶机巧”怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'发动','特殊召唤','是否把卡加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31553716,'长枪龙','此卡攻击守备表示怪兽时，若攻击力超过该守备力，给予对手生命相当于该数值的战斗伤害。此卡攻击过的场合，在伤害步骤结束时变成守备表示。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31554054,'超量复仇洗牌','于我方场上的超量怪兽被选为攻击目标时，可选择我方墓地中的１只超量怪兽发动。将成为攻击目标的超量怪兽洗回其拥有者的卡组。然后特殊召唤所选的怪兽，将这张卡叠放在其下作为超量素材。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31557782,'古代机械齿轮','我方场上存在“古代机械齿轮”时，此卡可从手牌以攻击表示特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31560081,'圣之魔术师','①：此卡反转的场合，以我方墓地的１张魔法卡为对象发动。将该卡牌加入手牌。','魔法回收','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31562086,'神碑之枪尖',replace(replace('此卡名的卡１回合仅可发动１张。①：可从以下效果中选择１个发动。此卡发动后，跳过下一个自己的战斗阶段。\r\n●从牌组将１张“神碑之枪尖”以外的“神碑”卡加入手牌。然后，从对手的牌组上面将１张卡除外。\r\n●从额外牌组将１只“神碑”怪兽特殊召唤至额外怪兽区域。','\r',char(13)),'\n',char(10)),'牌组检索','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31563350,'刷拉拉将军',replace(replace('等级４怪兽×２\r\n①：１回合１次，去除此卡的１个超量素材可以发动。从手牌将１只战士族怪兽视为装备卡装备于此卡。此卡的攻击力上升相当于以此效果装备的怪兽的攻击力数值。','\r',char(13)),'\n',char(10)),'装备怪兽','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31571902,'邪神机－狱炎',replace(replace('①：此卡无需解放即可召唤。\r\n②：以此卡的①方法召唤而来的情况下，在结束阶段发动。将此卡送往墓地。然后，自己受到此卡原本攻击力数值的伤害。场上不存在有除此卡以外的不死族怪兽的情况下，此效果进行发动和处理。','\r',char(13)),'\n',char(10)),'不用解放作召唤','送墓','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31588572,'破械童子 娑罗摩',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：以“破械童子 娑罗摩”以外的、自己墓地的1张“破械”卡为对象可以发动。将该卡放置在自己场上。然后，将自己场上的1张卡破坏。\r\n②：场上的此卡因战斗或“破械童子 娑罗摩”以外的卡的效果被破坏的情况下可以发动。从手牌・牌组将“破械童子 娑罗摩”以外的1只“破械”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31596518,'冥帝王厄多斯',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从自己牌组・墓地将1张“帝王”魔法・陷阱卡或1只攻击力2800/守备力1000的怪兽加入手牌。\r\n②：宣言1个属性可以发动。将场上的1只怪兽的属性改成所宣言的属性。\r\n③：此卡存在于墓地的状态下，自己将攻击力2400以上且守备力1000的怪兽上级召唤的情况下可以发动。将此卡加入手牌或特殊召唤。','\r',char(13)),'\n',char(10)),'检索','属性变更','墓地回收','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31600513,'祈祷螳螂',replace(replace('此卡名的①③效果１回合仅可各使用１次。\r\n①：在自己的准备阶段可以发动。将１只“宝宝螳螂衍生物”（昆虫族・风・星１・攻／守５００）特殊召唤至自己场上。\r\n②：１回合１次，对手怪兽攻击宣言时，将自己的魔法与陷阱区域的１张卡送至墓地可以发动。将该对手怪兽放回手牌。\r\n③：将墓地的此卡除外可以发动。将１只“宝宝螳螂衍生物”特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31600514,'宝宝螳螂衍生物','由「祈祷螳螂」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31600845,'恐乐园的死配人＜A丑角＞',replace(replace('此卡名在规则上也视为“惊乐园”卡。\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：自己场上存在“惊乐园”怪兽的情况下可以发动。从手牌将此卡特殊召唤。然后，可从自己的牌组・墓地将１张“惊乐园家族脸”加入手牌。\r\n②：在对手回合中，以场上１只其他的效果怪兽为对象可以发动。将此卡放回持有者的牌组，从牌组将１只“惊乐园的经理人<∀阿尔历奇诺>”特殊召唤。然后，将对象怪兽的攻击力改成０。','\r',char(13)),'\n',char(10)),'是否把「惊乐园家族脸」加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31603289,'杯糕喵★黯蜜味',replace(replace('协调＋协调以外的怪兽1只\r\n要同步召唤此卡的情况下，可将自己场上的1只连接1怪兽视为等级1协调。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡同步召唤的情况下可以发动。从牌组将2只“黯蜜”怪兽加入手牌。然后，挑选自己的1张手牌舍弃。\r\n②：对手发动魔法・陷阱・怪兽的效果时，将此卡放回额外牌组可以发动。从自己墓地将最多2只“黯蜜”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'检索','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31615285,'仙人掌终结者',replace(replace('此卡不可特殊召唤。\r\n①：只要此卡存在于怪兽区域，且其他植物族怪兽存在于怪兽区域，双方不可特殊召唤怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31629407,'魔弹射手 斯塔尔',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：只要此卡存在于怪兽区域，自己可在自己・对手回合中从手牌发动“魔弹”魔法・陷阱卡。\r\n②：在此卡的同一纵列发动了魔法・陷阱卡的情况下可以发动。从牌组将除“魔弹射手 斯塔尔”以外的、１只等级４以下的“魔弹”怪兽以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'从牌组特殊召唤','适用「魔弹射手 斯塔尔」的效果来发动','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31632536,'岩浆炎・双杀手',replace(replace('协调＋协调以外的炎属性怪兽１只或以上\r\n依据我方墓地冠有“岩浆炎”之名怪兽的数量，此卡获得以下效果。\r\n●２只或以上：此卡攻击了守备表示怪兽的场合，可再连续攻击１次。\r\n●３只或以上：此卡攻击了守备表示怪兽时，若其攻击力超过守备力，给予对手生命相当于该差值的战斗伤害。','\r',char(13)),'\n',char(10)),'是否要继续攻击？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31643613,'捕食活动','此卡名的卡１回合仅可发动１张。①：从手牌将１只“捕食植物”怪兽特殊召唤。然后从牌组将１张“捕食活动”以外的“捕食”卡加入手牌。此卡发动后，直至回合结束时为止自己从额外牌组仅可特殊召唤融合怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31677606,'黑白的波动','场上存在有以同步怪兽为超量素材的超量怪兽的场合可发动。选择场上的１张卡牌并从游戏中除外，从我方从牌组抽取１张卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31683874,'占卜魔女 小暗',replace(replace('此卡牌名的①②效果１回合只可各使用１次。\r\n①：抽取到此卡时，可向对手展示此卡并发动。从手牌特殊召唤此卡。\r\n②：此卡从手牌特殊召唤成功的场合可发动。从牌组将１只魔法师族怪兽除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31692182,'核成全屏障','可从手牌将１张“核成之钢核”返回至牌组最上方并发动。直至下一次我方回合的准备阶段时，除冠有“核成”之名的怪兽以外的场上表侧表示怪兽的效果被无效化。','效果无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31699677,'魔术库里波','此卡名的①②效果１回合仅可各使用１次。①：因战斗或对手的效果使自己受到伤害的回合的主要阶段及战斗阶段，从手牌将此卡送至墓地可以发动。从自己的牌组・墓地挑选１只“黑魔导”或“黑魔导女孩”特殊召唤。此效果在对手回合中也可以发动。②：自己场上的表侧表示魔法师族怪兽因战斗或对手的效果被破坏的情况下可以发动。将墓地的此卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31706048,'星遗物之醒存','此卡名的卡1回合仅可发动1张。①：从自己牌组上面翻开5张卡。其中有“机怪虫”怪兽或“星遗物”卡的情况下，从其中挑选1张加入手牌，剩下的卡全部送至墓地。没有的情况下，将翻开的卡全部放回牌组。此卡发动后，直至回合结束时为止，自己从额外牌组仅可特殊召唤连接怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31709826,'复活软泥','此卡因战斗而被破坏送入墓地时，可支付１０００点LP，于我方的下个准备阶段将其以表侧守备表示特殊召唤至我方场上。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31712840,'ZEXAL结盟','①：自己场上的表侧表示超量怪兽因战斗或对手的效果被破坏的情况下，支付LP直至变为１０LP可以发动。从自己的墓地挑选１只“希望皇霍普”怪兽特殊召唤，从牌组挑选１张卡放在牌组最上面。以此效果特殊召唤的怪兽攻击力变为两倍，不会被效果破坏，不会因与“编号”怪兽以外的怪兽的战斗被破坏。','','「ZEXAL联盟」效果适用中','请选择要放置在牌组最上面的卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31733941,'真红眼卡通龙',replace(replace('①：此卡在召唤・反转召唤・特殊召唤的回合不可攻击。\r\n②：自己场上存在“卡通世界”，且对手场上不存在卡通怪兽的情况下，此卡可直接攻击。\r\n③：1回合1次，在自己的主要阶段可以发动。从手牌将“真红眼卡通龙”以外的1只卡通怪兽无视召唤条件特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31755044,'十二兽 巳鞭',replace(replace('①：在自己・对手回合中，以自己场上的1只兽战士族超量怪兽为对象可以发动（同一连锁上最多1次）。将自己手牌・场上的此卡作为该怪兽的超量素材。\r\n②：持有此卡作为素材的、原本种族为兽战士族的超量怪兽获得以下效果。\r\n●此卡与对手怪兽进行战斗的伤害计算后发动。将该对手怪兽除外。','\r',char(13)),'\n',char(10)),'此卡重叠作为超量素材','进行战斗的对手怪兽除外（十二兽 巳鞭）','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31759689,'廷达三角・猎犬',replace(replace('①：此卡反转的情况下，以场上此卡以外的１只表侧表示怪兽为对象可以发动。此卡的攻击力上升相当于对象怪兽原本攻击力的数值。然后，将对象怪兽改成里侧守备表示。\r\n②：对手场上的怪兽的攻击力下降相当于与该怪兽处于连接状态的怪兽数量×１０００的数值。\r\n③：此卡因战斗・效果被破坏并被送至墓地的情况下，以场上１只里侧表示怪兽为对象可以发动。将该怪兽改成表侧守备表示。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31764353,'凭依装着－薇茵',replace(replace('①：此卡可通过将自己场上表侧表示的、1只“风灵使 薇茵”和1只风属性怪兽送至墓地，来从手牌・牌组特殊召唤。\r\n②：以此卡的①方法特殊召唤的此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31764354,'凭依装着－薇茵',replace(replace('①：此卡可通过将自己场上表侧表示的、1只“风灵使 薇茵”和1只风属性怪兽送至墓地，来从手牌・牌组特殊召唤。\r\n②：以此卡的①方法特殊召唤的此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31764700,'尤贝尔－“悲狂之龙”',replace(replace('此卡不可通常召唤。\r\n仅可以“尤贝尔－“忌避骑士””的效果特殊召唤。\r\n①：此卡不会因战斗被破坏，因此卡的战斗对自己造成的战斗伤害变为０。\r\n②：在攻击表示的此卡与对手怪兽进行战斗的伤害步骤结束时发动。给予对手相当于该对手怪兽攻击力数值的伤害，将该怪兽破坏。','\r',char(13)),'\n',char(10)),'伤害并破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31766317,'地狱女帝恶魔',replace(replace('①：场上仅1只其他的恶魔族・暗属性怪兽将被破坏的情况下，作为代替可将自己墓地的1只恶魔族・暗属性怪兽除外。\r\n②：场上的此卡被破坏并被送至墓地时，以除“地狱女帝恶魔”以外的、自己墓地的1只等级6以上的恶魔族・暗属性怪兽为对象可以发动。将该恶魔族・暗属性怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'是否要使用「地狱女帝恶魔」的效果代替破坏？','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31768112,'石油人','１回合１次，可在我方的主要阶段时，将此卡作为装备卡装备至我方场上的机械族怪兽上，或者解除装备状态以表侧攻击表示特殊召唤此卡。以此效果变为装备卡的场合，我方在装备怪兽通过战斗破坏对手怪兽的场合从牌组抽取１张卡牌。（１只怪兽最多只可装备１张联合。当装备怪兽被破坏的场合，破坏此卡来代替。）','破坏','抽牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31772684,'仇尸・归来者',replace(replace('此卡名的②效果１回合仅可使用１次。①：此卡被对手破坏并被送至墓地的情况下可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡离开场上的情况下，将其除外。②：使用场上的此卡仪式召唤的“仇尸”怪兽获得以下效果。\r\n●１回合１次，以对手场上１只被特殊召唤的怪兽为对象可以发动。将该怪兽除外。此效果在对手回合中也可以发动。','\r',char(13)),'\n',char(10)),'此卡特殊召唤','对手怪兽除外（仇尸·归来者）','「仇尸·归来者」效果适用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31785398,'迎击准备','将场上１只以表侧表示存在的战士族或魔法师族怪兽变成里侧守备表示。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31786629,'雷龙','①：将此卡从手牌中舍弃可以发动。从牌组将最多２只“雷龙”加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31786838,'再世记',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从牌组挑选1只“再世”怪兽，加入手牌或送至墓地。自己场上存在“再世”怪兽的情况下，作为代替也可从牌组将1只攻击力和守备力为2500的怪兽加入手牌。\r\n②：从墓地将不是在此回合被送至墓地的此卡除外，以自己墓地的1只“再世”怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'牌组操作','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31801517,'编号62 银河眼光子龙皇',replace(replace('等级8怪兽×2\r\n①：每次此卡进行战斗的伤害计算时，去除此卡的1个超量素材可以发动1次。此卡的攻击力仅在该伤害计算时上升场上的超量怪兽阶级合计×200的数值。\r\n②：未持有“银河眼光子龙”作为超量素材的此卡给予对手的战斗伤害变为一半。\r\n③：持有“银河眼光子龙”作为超量素材的此卡被对手效果破坏的情况下可以发动。在发动后第2次自己准备阶段将此卡的攻击力改成两倍并特殊召唤。','\r',char(13)),'\n',char(10)),'攻击上升','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31801518,'编号62 银河眼光子龙皇',replace(replace('等级8怪兽×2\r\n①：每次此卡进行战斗的伤害计算时，去除此卡的1个超量素材可以发动1次。此卡的攻击力仅在该伤害计算时上升场上的超量怪兽阶级合计×200的数值。\r\n②：未持有“银河眼光子龙”作为超量素材的此卡给予对手的战斗伤害变为一半。\r\n③：持有“银河眼光子龙”作为超量素材的此卡被对手效果破坏的情况下可以发动。在发动后第2次自己准备阶段将此卡的攻击力改成两倍并特殊召唤。','\r',char(13)),'\n',char(10)),'攻击上升','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31809476,'徽章的明灭',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：以对手场上任意数量的表侧表示怪兽为对象可以发动。将该怪兽的卡名视为“未知”。\r\n②：在自己的结束阶段，此卡存在于墓地，且自己场上存在念动力族超量怪兽的情况下可以发动。将此卡放置在自己场上。以此效果放置的此卡从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'卡名变更','放置','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31812496,'阿兹提克石像','①：此卡被攻击的场合，因该战斗所产生之给予对手的战斗伤害加倍。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31817415,'武装新宇侠',replace(replace('“元素－英雄 新宇侠”＋“武装龙”怪兽\r\n此卡仅可以融合召唤方式特殊召唤。\r\n①：此卡特殊召唤的情况下可以发动。挑选自己墓地的１只龙族怪兽，将对手场上等级在其等级以下的怪兽全部破坏。\r\n②：此卡战斗破坏怪兽时可以发动。此卡获得以下效果。\r\n●在双方的主要阶段，解放此卡可以发动。从额外牌组将１只“元素－英雄”融合怪兽无视召唤条件特殊召唤。','\r',char(13)),'\n',char(10)),'','','「武装新宇侠」效果适用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31822037,'无垢祈祷的狱神使',replace(replace('连接怪兽以外的怪兽2只\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡连接召唤的情况下，如果自己墓地存在“狱神”怪兽则可以发动。从牌组将1张“预幻”卡加入手牌。\r\n②：在自己・对手的主要阶段，自己场上存在其他天使族・暗属性怪兽的情况下可以发动。将包含此卡在内的、自己场上的怪兽作为素材进行连接召唤。','\r',char(13)),'\n',char(10)),'检索','连接召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31826057,'音响战士 钢昂琴','①：１回合１次，宣言１个种族，以场上的１只“音响战士”怪兽为对象可以发动。该怪兽变为所宣言的种族。②：将墓地的此卡除外，宣言１个种族，以自己场上的１只“音响战士”怪兽为对象可以发动。该自己的“音响战士”怪兽变为所宣言的种族。','种族变换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31828916,'机甲部队的最前线','①：１回合１次，机械族怪兽因战斗被破坏并被送至自己的墓地时可以发动。将１只攻击力低于墓地的该怪兽、属性与之相同的机械族怪兽从牌组特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31829185,'黑暗恋尸狂',replace(replace('此卡不可通常召唤。\r\n将我方墓地中３只恶魔族怪兽从游戏中除外的场合，可特殊召唤此卡。\r\n①：怪兽区域的此卡被对手破坏送入墓地的回合的结束阶段，以对手场上１只表侧表示的怪兽为对象发动此卡。将墓地中的此卡作为装备卡装备至对手怪兽上。\r\n②：因此卡效果而装备此卡的场合，取得装备怪兽的控制权。','\r',char(13)),'\n',char(10)),'获得控制权','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31833038,'枪管上膛龙',replace(replace('效果怪兽3只以上\r\n①：此卡不会成为怪兽效果的对象。②：1回合1次，以场上1只表侧表示怪兽为对象可以发动。该怪兽的攻击力・守备力下降500。应对此效果的发动，对手不可发动卡的效果。此效果在对手回合中也可以发动。③：此卡攻击对手怪兽的伤害步骤开始时可以发动。将该对手怪兽放在此卡连接端，获得其控制权。该怪兽在下个回合的结束阶段将被送至墓地。','\r',char(13)),'\n',char(10)),'攻守下降','获得控制权','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31833039,'枪管上膛龙',replace(replace('效果怪兽3只以上\r\n①：此卡不会成为怪兽效果的对象。②：1回合1次，以场上1只表侧表示怪兽为对象可以发动。该怪兽的攻击力・守备力下降500。应对此效果的发动，对手不可发动卡的效果。此效果在对手回合中也可以发动。③：此卡攻击对手怪兽的伤害步骤开始时可以发动。将该对手怪兽放在此卡连接端，获得其控制权。该怪兽在下个回合的结束阶段将被送至墓地。','\r',char(13)),'\n',char(10)),'攻守下降','获得控制权','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31834488,'月全食之书','①：舍弃1张手牌，以场上的2只表侧表示怪兽为对象可以发动。将该怪兽改成里侧守备表示。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31849106,'异次元竞技场','①：此回合，被送往墓地的怪兽不去墓地而直接被除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31855260,'突异变种怪的产声',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：在自己・对手的主要阶段可以发动。从自己场上・墓地的怪兽及自己被除外的怪兽中，将由“突异变种”融合怪兽卡决定的融合素材怪兽放回持有者的牌组，将该１只融合怪兽从额外牌组融合召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31863912,'失败的股子','对手特殊召唤怪兽成功时，掷１次股子。掷出的点数与被特殊召唤的该怪兽等级相同的场合，该怪兽返回至持有者手牌。','投掷骰子','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31887806,'宙之忍者－鸟帷',replace(replace('此卡名的①③效果１回合仅可各使用１次。\r\n①：从手牌将此卡送至墓地可以发动。从手牌将１只“忍者”怪兽以表侧守备表示或里侧守备表示特殊召唤。\r\n②：此卡在特殊召唤・反转的回合，不会因战斗・效果被破坏。\r\n③：在对手的主要阶段及战斗阶段可以发动。从自己的手牌・场上，将由“忍者”融合怪兽卡决定的融合素材怪兽送至墓地，从额外牌组将该１只融合怪兽融合召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31887905,'凭依装着－奥丝',replace(replace('①：此卡可通过将自己场上表侧表示的、1只“地灵使 奥丝”和1只地属性怪兽送至墓地，来从手牌・牌组特殊召唤。\r\n②：以此卡的①方法特殊召唤的此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31887906,'凭依装着－奥丝',replace(replace('①：此卡可通过将自己场上表侧表示的、1只“地灵使 奥丝”和1只地属性怪兽送至墓地，来从手牌・牌组特殊召唤。\r\n②：以此卡的①方法特殊召唤的此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31890399,'魔鬼镜','由“魔鬼镜的仪式”召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31893528,'死之信息“I”','此卡只可通过“通灵盘”的效果上场。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31897444,'冥宫的守卫',replace(replace('通常怪兽２只\r\n此卡牌名的②效果１回合只可使用１次。\r\n①：我方场上除效果怪兽以外的怪兽攻击力上升５００，且对手场上效果怪兽的攻击力下降５００。\r\n②：此卡因对手被破坏的场合，可以我方墓地１只除效果怪兽以外的怪兽为对象发动。特殊召唤该怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31904181,'六武众－二藏','我方场上存在有除“六武众－二藏”以外的冠有“六武众”之名的怪兽的场合，此卡可在１次的战斗阶段中攻击２次。此外，场上的此卡被破坏的场合，可破坏我方场上的１只冠有“六武众”之名的怪兽作为代替。','是否要使用「六武众－二藏」的代替破坏效果？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31919988,'漆黑的朱姆沃尔特',replace(replace('暗属性协调＋１只协调以外的昆虫族怪兽\r\n此卡不会因战斗被破坏。此卡对攻击力高于此卡的对手怪兽攻击宣言的情况下发动。攻击对象怪兽的攻击力直至战斗阶段结束时为止，变为与此卡的攻击力相同。此卡战斗破坏对手怪兽并将之送至墓地时，从对手牌组上面将３张卡送至墓地。','\r',char(13)),'\n',char(10)),'攻击变换','牌组破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31924889,'奥法魔术士',replace(replace('协调＋１只以上协调以外的魔法师族怪兽\r\n①：此卡同步召唤成功的情况下发动。在此卡上放２个魔力计数物。②：此卡的攻击力上升相当于此卡魔力计数物数量×１０００的数值。③：去除自己场上的１个魔力计数物，以对手场上的１张卡为对象可以发动。将该对手的卡破坏。','\r',char(13)),'\n',char(10)),'放置魔力计数物','破坏一张卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31930787,'机皇帝神空∞',replace(replace('此卡不可通常召唤，只能通过自身的效果特殊召唤。\r\n①：自己场上表侧表示的怪兽因效果被破坏并送至墓地时可以发动。特殊召唤手牌中的此卡。\r\n②：1个回合1次，可以以对手场上的1只同步怪兽为对象发动。将对手的该同步怪兽装备到此卡上。\r\n③：此卡的攻击力上升通过自身的效果装备的怪兽的攻击力数值，自己的其他怪兽无法进行攻击宣言。\r\n④：将自己的1只通过自身装备的怪兽送至墓地后可以发动。在此回合中，此卡可直接攻击。','\r',char(13)),'\n',char(10)),'特殊召唤','装备同步怪兽','直接攻击','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31944175,'生化阈值人',replace(replace('①：我方场上不存在有怪兽的场合，此卡可舍弃手牌的１只电子界族怪兽，并从手牌特殊召唤。\r\n②：只要此卡存在于怪兽区，对手场上怪兽的攻击力下降５００。','\r',char(13)),'\n',char(10)),'从手牌特殊召唤','攻击力下降','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31969219,'影之灾祸',replace(replace('①：以对手场上的1张表侧表示卡为对象可以发动。根据卡名与该卡相同的对手墓地的卡的数量适用以下效果。\r\n●1张：将对象卡破坏。\r\n●2张：将对象卡除外。\r\n●3张：从对手场上・墓地将对象卡及其同名卡全部以里侧除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31971040,'选律之华耳琴璃',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：自己场上存在“华耳琴璃”怪兽卡的情况下，从以下效果中挑选１个适用。自己场上存在“华耳琴璃”连接怪兽的情况下，两者都可适用。\r\n●自己恢复５００LP。此回合中，对手不可将自己场上的“华耳琴璃”怪兽卡作为效果的对象。\r\n●自己受到５００伤害。然后，可将对手场上的１只效果怪兽的效果直至回合结束时为止无效。','\r',char(13)),'\n',char(10)),'','自己回复500基本分','自己受到500伤害','选两方适用','是否把对手1只怪兽的效果无效？','','','','','','','','','','','');
INSERT INTO texts VALUES(31975743,'魔术师猿','此卡不可特殊召唤。此卡以攻击表示存在的场合，１回合１次，可将手牌的１只怪兽送入墓地，并选择对手场上的１只表侧守备表示怪兽发动。直至此回合的结束阶段时，获得被选择怪兽的控制权。以此效果获得控制权的怪兽，此回合不可变更表示形式。','获得控制权','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31980955,'慢生活',replace(replace('自己场上不存在怪兽的情况下，自己的主要阶段１开始时可以发动此卡。\r\n①：只要此卡存在于魔法与陷阱区域，适用以下效果。\r\n●通常召唤过怪兽的玩家该回合不可特殊召唤怪兽。\r\n●特殊召唤过怪兽的玩家该回合不可通常召唤怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31986288,'分裂魔界蔷薇','此卡因战斗破坏并被送入墓地时，可特殊召唤２只“魔界蔷薇衍生物”（植物族、暗、星３、攻／守１２００）至我方场上。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31986289,'魔界蔷薇衍生物','由“分裂魔界蔷薇”的效果特殊召唤而来。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31987203,'死天使 哈贝斯特',replace(replace('←8 【灵摆】 8→\r\n此卡名的灵摆效果１回合仅可使用１次。\n①：在自己的主要阶段可以发动。将此卡破坏，从牌组将１张“升天之黑角笛”加入手牌。\r\n【怪兽效果】\r\n此卡名的①②怪兽效果１回合仅可各使用１次。\n①：此卡召唤・灵摆召唤的情况下可以发动。从牌组将１张“升天之角笛”加入手牌。\n②：此卡被解放的情况下可以发动。将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31987274,'跳跃飞鱼','据说看见其翱翔天际的人可以实现三个愿望。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(31991800,'威风魔灵・分福浣熊',replace(replace('←5 【灵摆】 5→\r\n【怪兽效果】\r\n此卡名的①怪兽效果１回合仅可使用１次。\n①：此卡召唤・特殊召唤时可以发动。从牌组将１只“威风魔灵”怪兽加入手牌。\n②：只要此卡存在于怪兽区域，此卡不会被对手的效果破坏，对手不可将此卡作为效果的对象。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32003338,'编号34 电算机兽太字节',replace(replace('等级３怪兽×３\r\n１回合１次，可以移除这张卡的１个超量素材，并选择对手场上１只等级４以下攻击状态的怪兽发动。获得该怪兽的操控权，直到结束阶段。','\r',char(13)),'\n',char(10)),'获得控制权','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32003339,'编号34 电算机兽太字节',replace(replace('等级３怪兽×３\r\n１回合１次，可以移除这张卡的１个超量素材，并选择对手场上１只等级４以下攻击状态的怪兽发动。获得该怪兽的操控权，直到结束阶段。','\r',char(13)),'\n',char(10)),'获得控制权','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32012841,'仟年之盾','据说传承自古埃及王室的传说之盾，无论多强的攻击都能抵挡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32012842,'仟年之盾','据说传承自古埃及王室的传说之盾，无论多强的攻击都能抵挡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32013448,'宵暗之骑士',replace(replace('此卡名的①②效果１回合仅可各使用１次。①：使用此卡仪式召唤的“混沌士兵”怪兽获得以下效果。\r\n●１回合１次，以对手场上的１只怪兽为对象可以发动。将该怪兽除外。\r\n●１回合１次，在自己的主要阶段可以发动。随机挑选１张对手的手牌，直至下一个对手的结束阶段为止，以里侧表示除外。\r\n②：墓地的此卡被除外的情况下可以发动。从牌组将１只仪式怪兽加入手牌。','\r',char(13)),'\n',char(10)),'对手场上1只怪兽除外（宵暗之骑士）','对手手牌随机1张暂时除外（宵暗之骑士）','「宵暗之骑士」效果适用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32015116,'无差别破坏','每次我方准备阶段就掷１次骰子。掷出１～５点的场合，破坏持有等级与骰子点数相同的所有场上怪兽。掷出６点的场合，破坏场上等级６或以上的所有怪兽。','投掷骰子','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32022366,'重力之斧－格拉尔','装备怪兽的攻击力上升５００点。只要此卡存在于场上，对手场上的怪兽不可变更表示形式。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32036866,'方程式运动员过热化','此卡名的②效果1回合仅可使用1次。①：仅有对手场上才存在怪兽的情况下可以发动。从手牌将1只“方程式运动员”怪兽特殊召唤。以此效果特殊召唤的怪兽的等级直至回合结束时为止上升3。②：自己的场地区域没有卡存在的情况下，将墓地的此卡除外可以发动。从自己的手牌・墓地挑选1张“方程式运动员”场地魔法卡发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32044231,'升阶魔法－魔术之力',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：以自己墓地的1只魔法师族・阶级4超量怪兽为对象可以发动。将该怪兽的效果无效并特殊召唤，将1只魔法师族・阶级5超量怪兽重叠在对象怪兽上面，从额外牌组视为超量召唤特殊召唤，将此卡作为其超量素材。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32044675,'无现坏收 无之获取者',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡同步召唤的情况下可以发动。从牌组将1只等级8以上且攻击力0的怪兽加入手牌。\r\n②：以自己墓地的1只攻击力0的怪兽为对象可以发动。将该怪兽特殊召唤。以此效果特殊召唤的怪兽效果无效化，不可作为融合・同步・超量・连接召唤的素材。','\r',char(13)),'\n',char(10)),'检索','特殊召唤','「无现坏收 无之获取者」的效果特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32056070,'友爱-艾-',replace(replace('①：原本攻击力为２３００的电子界族怪兽被特殊召唤的情况下，根据其属性可从以下效果中选择１个发动。“友爱-艾-”的以下效果对于每１个属性，１回合仅可选择１次。\r\n●地・水：挑选场上的１只表侧表示怪兽，将其攻击力直至回合结束时为止改成一半。\r\n●风・光：挑选场上的１张表侧表示卡，将其效果直至回合结束时为止无效。\r\n●炎・暗：将１只“＠伊格尼斯者衍生物”（电子界族・暗・星１・攻／守０）特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'','请选择要触发效果的属性','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32056071,'＠伊格尼斯者衍生物','由「友爱-艾-」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32061192,'码丽丝＜兵＞睡鼠',replace(replace('此卡名的①③效果1回合仅可各使用1次。\r\n①：在自己的主要阶段可以发动。从牌组将1只“码丽丝”怪兽除外。此回合中，自己场上的“码丽丝”怪兽的攻击力上升600。\r\n②：连接端指向此卡的“码丽丝”连接怪兽不会因效果被破坏。\r\n③：此卡被除外的情况下，支付300LP可以发动。将此卡特殊召唤。此回合，自己从额外牌组仅可特殊召唤连接怪兽。','\r',char(13)),'\n',char(10)),'除外','','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32061744,'电力守卫','可选择我方墓地的１只等级４或以下冠有“电力”之名的怪兽并发动。特殊召唤被选择怪兽。以此效果特殊召唤的怪兽在此回合的结束阶段时被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32062913,'百万吨魔法大炮','取除我方场上的１０个魔力计数物来发动此卡。破坏对手场上的所有卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32065885,'痛恨的控诉','我方因对手怪兽的直接攻击受到战斗伤害时可发动。直至下一个我方结束阶段时，获得对手场上１只守备力最高怪兽的控制权。以此效果获得控制权之怪兽的效果被无效化，不可进行攻击宣言。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32086564,'超量同门对手','①：只要此卡存在于魔法与陷阱区域，拥有２个以上超量素材的超量怪兽不会因效果被破坏。②：此卡存在于魔法与陷阱区域，自己的超量怪兽与对手怪兽进行战斗的伤害计算后发动。将该对手的怪兽破坏。此效果在该自己的怪兽拥有２个以上超量素材的情况下才能发动和处理。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32104431,'破坏剑的追忆',replace(replace('①：可从手牌舍弃１张“破坏剑”卡牌并发动。从牌组特殊召唤１只“毁灭剑士”怪兽。\r\n②：可将墓地的此卡除外并发动。将根据“龙破坏之剑士－毁灭剑士”指定的融合素材怪兽从我方墓地除外，从额外牌组融合召唤１只该融合怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32120116,'阎魔的裁决',replace(replace('①：对手特殊召唤怪兽成功时可以发动。将该怪兽破坏。然后，可适用以下效果。\r\n●从自己的墓地中将５只不死族怪兽除外，并从手牌・牌组特殊召唤１只等级７以上的不死族怪兽。','\r',char(13)),'\n',char(10)),'是否特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32126000,'学习妖精',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将1张拥有将自身视为装备卡装备的效果的陷阱卡放置在自己场上。\r\n②：此卡从场上被送至墓地的情况下可以发动。自己抽1张。','\r',char(13)),'\n',char(10)),'放置效果','抽牌效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32134638,'机动雾龙・甲龙',replace(replace('←6 【灵摆】 6→\r\n①：只要此卡存在于灵摆区域，仅限１次，可将以自己场上的其他“机动雾龙”卡为对象发动的效果无效。然后，将此卡破坏。\r\n【怪兽效果】\r\n①：只要此卡存在于怪兽区域，自己的“机动雾龙”怪兽战斗破坏的怪兽将被除外。','\r',char(13)),'\n',char(10)),'效果无效','是否使用「机动雾龙·甲龙」的效果？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32138660,'爬虫妖・美露莘',replace(replace('爬虫类族协调＋１只以上协调以外的怪兽\r\n此卡②效果在同一连锁上仅可发动１次。①：仅以爬虫类族怪兽作为素材同步召唤的此卡不会因战斗・效果被破坏。②：对手发动怪兽的效果时，以对手场上的１只表侧表示怪兽为对象可以发动。将该怪兽的攻击力改成０。③：同步召唤的此卡被对手送至墓地的情况下可以发动。从牌组将１只爬虫类族怪兽加入手牌。','\r',char(13)),'\n',char(10)),'只用爬虫类族怪兽为素材作同步召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32146097,'DD 潘朵拉','①：此卡因战斗或对手的效果被破坏并被送至墓地时，如果自己场上不存在卡则可以发动。自己抽2张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32152870,'恐惧爪・肆世坏的械贬','此卡名的②效果１回合仅可使用１次。①：以自己场上・墓地的１张“肆世坏・赖祸比亚”为对象可以发动。将该卡放回持有者的手牌。自己场上存在“维萨思・史塔弗罗斯特”的情况下，进而可挑选对手场上的１只表侧表示怪兽，改成里侧守备表示。②：场上存在３只以上的守备表示怪兽的情况下，将墓地的此卡除外可以发动。从自己墓地挑选１张“恐惧爪”卡加入手牌。','回收场地','回收「恐惧爪」卡','是否选对手怪兽变成里侧表示？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32164201,'ZEXAL兵器－天马双翼军刀','①：“ZEXAL兵器－天马双翼军刀”在自己场上仅可有１张以表侧表示形式存在。②：自己的LP比对手少２０００以上的情况下，此卡可从手牌中特殊召唤。③：以自己场上的１只“希望皇霍普”怪兽为对象可以发动。将自己场上的此卡视为攻击力上升１０００的装备卡装备于该怪兽。④：此卡被装备中的情况下，１回合１次，可将对手场上的怪兽发动的效果无效。','','是否适用「ZEXAL兵器-天马双翼剑」的效果来无效？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32175429,'英豪呼唤',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：从自己的手牌・墓地挑选１只战士族怪兽特殊召唤。以此效果特殊召唤“英豪”怪兽以外的怪兽的情况下，该怪兽不可攻击，效果无效化。\r\n②：自己的LP为５００以下的情况下，将墓地的此卡除外，以自己场上的１只表侧表示怪兽为对象可以发动。该怪兽的攻击力上升相当于自己场上“英豪”卡及作为超量素材的“英豪”卡数量×５００的数值。','\r',char(13)),'\n',char(10)),'特殊召唤','攻击力上升','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32176662,'触发冰晶','①：此卡被送至墓地的情况下可以发动。将对手场上的攻击表示怪兽全部改成守备表示。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32180819,'最古式念导','我方场上有念动力族怪兽存在的场合，可选择场上的１张卡牌发动此卡。破坏所选择卡牌，我方受到１０００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32181268,'天岩户',replace(replace('此卡不可特殊召唤。\r\n①：只要此卡存在于怪兽区域，双方不可发动灵魂怪兽以外的怪兽的效果。\r\n②：此卡召唤・反转的回合的结束阶段发动。将此卡放回手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32202803,'武斗神器－足玉','只要此卡以表侧表示存在于场上，我方场上除此卡以外的兽族、兽战士族、鸟兽族怪兽不会因战斗被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32207100,'大爆冷门','释放我方场上以表侧攻击表示存在的等级２或以下的１只怪兽发动。将场上以表侧表示存在的等级７或以上的特殊召唤的怪兽全部返回至持有者手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32216688,'R.B.野蛮蓝调',replace(replace('机械族怪兽2只以上\r\n此卡名的②效果1回合仅可使用1次。\r\n①：只要此卡连接端存在“R.B.”怪兽，此卡获得以下效果。\r\n●此卡的攻击力上升相当于此卡连接端的“R.B.”怪兽的原本攻击力的数值。\r\n●此卡在1次战斗阶段中可攻击2次。\r\n●此卡不会因战斗・效果被破坏。\r\n②：在自己的主要阶段可以发动。从牌组将1张“R.B.”卡加入手牌。','\r',char(13)),'\n',char(10)),'检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32224143,'鬼计・梦魔',replace(replace('等级２怪兽×２\r\n①：１回合１次，去除此卡的１个超量素材，以场上的１只攻击力为场上“鬼计”怪兽攻击力的合计以下的怪兽为对象可以发动。将该怪兽破坏，只要自己场上有“鬼计”怪兽存在，该怪兽区域不可使用。②：自己场上有其他“鬼计”怪兽存在的情况下，对手怪兽不可将此卡作为攻击对象。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32231618,'占卜姬 硬币地精','①：此卡反转的情况下可以发动。从手牌・牌组将１只等级３以上的反转怪兽以里侧守备表示特殊召唤。此效果发动后，直至回合结束时为止，自己不可发动“占卜姬”怪兽以外的怪兽的效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32232538,'DDD 智慧王索罗门',replace(replace('等级4“DD”怪兽×2\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：去除此卡的1个超量素材可以发动。从牌组将1张“DD”卡加入手牌。\r\n②：此卡被除外的情况下，以自己场上的1只“DD”效果怪兽为对象可以发动。该效果怪兽直至回合结束时为止获得以下效果。\r\n●此卡战斗破坏怪兽的情况下发动。给予对手相当于该怪兽的原本攻击力数值的伤害。','\r',char(13)),'\n',char(10)),'检索效果','赋予效果','伤害效果（DDD 智慧王索罗门）','「DDD 智慧王索罗门」效果适用中','','','','','','','','','','','','');
INSERT INTO texts VALUES(32233746,'光之放逐','可解放自己场上１只名字带有“光道”的怪兽发动。将怪兽的召唤・反转召唤・特殊召唤无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32236916,'虹之桥',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从额外牌组将包含光属性同步怪兽在内的、3只等级10以上的怪兽除外可以发动。从牌组将1张场地魔法卡加入手牌。','\r',char(13)),'\n',char(10)),'发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32240937,'绝对服从魔人','自己场上不存在有其他卡牌，且手牌必须为０张此卡才可发动。此卡因战斗破坏的怪兽，其效果被无效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32245230,'命运的契约','此卡名的②效果１回合仅可使用１次。①：自己场上的卡每次因战斗・效果被破坏，在此卡上放１个皇之钥计数物（最多１个）。②：对手从额外牌组特殊召唤怪兽的情况下，去除此卡的１个皇之钥计数物可以发动。从手牌・牌组及自己场上的表侧表示卡中，将１张“命运之扉”送至墓地，从额外牌组将１只光属性“霍普”超量怪兽视为超量召唤特殊召唤，将此卡重叠在该怪兽下方作为超量素材。','特殊召唤「霍普」超量怪兽','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32247099,'绝对之幻神兽','此卡名的①②效果1回合仅可各使用1次。①：对手怪兽攻击宣言时，从手牌舍弃1张魔法・陷阱卡，以自己墓地的1只幻神兽族怪兽为对象可以发动。以守备表示形式将该怪兽特殊召唤。然后，攻击对象移换为该怪兽。②：自己场上有幻神兽族怪兽存在的情况下，在结束阶段可以发动。将此回合在场上发动过效果的对手场上的表侧表示卡全部破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32268901,'沙罗曼龙',replace(replace('仅限装备炎属性怪兽。\r\n①：装备怪兽的攻击力上升７００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32269855,'独眼白虎','是丛林中高贵的王者。有些人对它充满畏惧，有些人则对它充满了敬意。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32270212,'伙伴羁绊',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：自己场上存在“光之黄金柜”及记载有该卡名的怪兽的情况下可以发动。从手牌・牌组将记载有“光之黄金柜”卡名的、最多２只等级４以下的怪兽特殊召唤（同名卡最多１张）。此卡发动后，直至回合结束时为止，自己不可从额外牌组特殊召唤怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32271987,'费德莱扎','此卡因战斗而被破坏送入墓地时，可将我方牌组中１只二重怪兽送入墓地，并从我方牌组抽取１张卡牌。','送墓抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32274490,'白骨','处处皆会出现的骸骨型妖怪。虽然攻击力很弱，一旦聚集却也十分棘手。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32274491,'白骨','处处皆会出现的骸骨型妖怪。虽然攻击力很弱，一旦聚集却也十分棘手。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32274492,'白骨','处处皆会出现的骸骨型妖怪。虽然攻击力很弱，一旦聚集却也十分棘手。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32278723,'水波喷气机・上浮',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：从自己手牌・墓地将１只等级４以下的鱼族・海龙族・水族怪兽特殊召唤。只要以此效果特殊召唤的怪兽以表侧表示存在于自己场上，自己从额外牌组仅可特殊召唤超量怪兽。\r\n②：对手场上存在攻击表示怪兽的情况下，将墓地的此卡除外，以自己场上的１只鱼族・海龙族・水族怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止上升１０００。','\r',char(13)),'\n',char(10)),'特殊召唤','上升攻击力','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32281491,'ZEXAL从者－双头龙贤者',replace(replace('①：此卡召唤成功时可以发动。从自己的墓地挑选１只光属性以外的“编号”怪兽，将效果无效并特殊召唤，从自己场上将此卡和１只“希望皇霍普”怪兽各视为攻击力上升１７００的装备卡，装备于该特殊召唤的怪兽。此回合，自己仅可攻击宣言１次。\r\n②：以此卡的效果装备此卡的怪兽对对手怪兽攻击宣言时可以发动。该攻击怪兽的攻击力变为两倍，将在结束阶段被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32289031,'星骑士 星圣 德塔特洛斯',replace(replace('等级4怪兽×3只以上\r\n①：对手不可将自己场上的阶级5以上的、“星骑士”、“星圣”超量怪兽作为效果的对象。\r\n②：1回合1次，去除此卡的1个超量素材可以发动。从牌组将1只“星骑士”、“星圣”怪兽加入手牌。然后，可进行1只光属性怪兽的召唤。\r\n③：此卡从场上以外的地方被送至墓地的情况下可以发动。将自己手牌・除外状态的1只“星骑士”、“星圣”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'检索效果','特殊召唤','是否进行召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32295838,'数码创机','在电子空间找到的亚种。其信息量貌似略多一点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32296881,'丰收之阿尔提米斯','①：只要此卡存在于怪兽区，每次我方或对手发动反制陷阱卡，我方从牌组抽取１张卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32298781,'三角力量','我方场上所有表侧表示的等级１通常怪兽（衍生物除外）的原始攻击力和原始守备力上升２０００点。在结束阶段时破坏我方场上所有等级１通常怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32302078,'交血鬼－吸血鬼谢里丹',replace(replace('等级6怪兽×2只以上\r\n可将原本持有者为对手的怪兽的等级视为6来作为超量召唤此卡的素材。\r\n①：1回合1次，去除此卡的1个超量素材，以对手场上的1张卡为对象可以发动。将该卡送至墓地。\r\n②：1回合1次，场上的怪兽卡因效果被送至对手墓地的情况下，或因战斗被破坏并被送至对手墓地的情况下，去除此卡的1个超量素材可以发动。将该1只怪兽以守备表示特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32305461,'占卜魔女 小炎',replace(replace('此卡牌名的①②效果１回合只可各使用１次。\r\n①：抽取到此卡时，可向对手展示此卡并发动。从手牌特殊召唤此卡。\r\n②：此卡从手牌特殊召唤成功的场合，可以盖牌于对手场上的１张卡牌为对象发动。破坏该卡。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32314730,'核成十字军','此卡的控制者在每次我方的结束阶段，从手牌将１张“核成之钢核”送入墓地，或向对手展示１只手牌的兽战士族怪兽。或者，不执行上述任何一项破坏此卡。此卡因战斗破坏对手怪兽时可发动。选择我方墓地的１张冠有“核成”之名的卡牌加入手牌。','选择一张「核成之钢核」送至墓地','选择一张兽战士族怪兽给对手观看','破坏「核成十字军」','回收','','','','','','','','','','','','');
INSERT INTO texts VALUES(32335697,'闹鬼不死族','此卡名的①②效果１回合１次，仅可使用其中１个。①：从自己或对手的墓地挑选１只不死族怪兽除外，将２只拥有与其等级相同等级的“闹鬼衍生物”（不死族・暗・攻／守０）特殊召唤至自己场上。②：此卡存在于墓地的情况下可以发动。挑选被除外的自己的１只不死族怪兽放回牌组，将此卡放置在自己场上。以此效果放置的此卡从场上离开的情况下，将其除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32335698,'闹鬼衍生物','由「闹鬼不死族」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32339440,'武斗神－大和','１回合１次，可在我方结束阶段时发动。从牌组将１只冠有“武斗神”之名的怪兽加入手牌。之后，将１张手牌送入墓地。我方场上只可以表侧表示存在１只１“武斗神－大和”。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32344688,'暗黑奇美拉','栖息于魔界的怪兽，可吐出暗炎进行攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32349062,'DD 猛犬',replace(replace('←3 【灵摆】 3→\r\n此卡名的灵摆效果１回合仅可使用１次。\n①：以对手场上的１只融合・同步・超量怪兽为对象可以发动。将该怪兽的效果直至回合结束时为止无效。然后，将灵摆区域的此卡破坏。\r\n【怪兽效果】\r\n①：１回合１次，对手特殊召唤融合・同步・超量怪兽的情况下，以该１只怪兽为对象可以发动。此回合，该表侧表示怪兽不可攻击，效果无效化。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32353566,'魔女工艺・瓦尔普吉斯夜行',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：在自己的主要阶段可以发动。从牌组将1只“魔女工艺”怪兽加入手牌。然后，挑选自己的1张手牌舍弃。\r\n②：在自己回合，为发动自己场上的“魔女工艺”怪兽的效果而要将手牌舍弃的情况下，作为代替可从牌组将“魔女工艺・瓦尔普吉斯夜行”以外的1张“魔女工艺”魔法・陷阱卡送至墓地。','\r',char(13)),'\n',char(10)),'检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32354768,'源质的神托',replace(replace('此卡牌名的卡牌１回合只可发动１张。\r\n①：此卡发动时，从牌组将１只“源质”怪兽加入手牌。\r\n②：使用“源质”怪兽仪式召唤，或以“源质”怪兽为素材特殊召唤以下怪兽时，我方１回合可发动各效果１次。\r\n●仪式：将场上的１只怪兽返回至牌组。\r\n●融合：特殊召唤手牌的１只怪兽。\r\n●同步：将牌组的１只怪兽放置于牌组的最上方。\r\n●超量：从牌组抽取１张卡牌，之后舍弃１张手牌。','\r',char(13)),'\n',char(10)),'场上1只怪兽回到牌组','手牌1只怪兽特殊召唤','牌组1只怪兽在牌组最上面放置','从牌组抽1张，那之后丢弃1张手牌','选择要放置在牌组最上方的怪兽','','','','','','','','','','','');
INSERT INTO texts VALUES(32355828,'骸骨龙','“美杜莎的亡灵”＋“暗黑的龙王”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32360466,'天地开辟','此卡名的卡１回合仅可发动１张。①：从牌组将包含１只以上“混沌士兵”怪兽或“暗黑骑士盖亚”怪兽的、３只战士族怪兽出示给对手，对手从其中随机挑选１只。所挑选的是“混沌士兵”怪兽或“暗黑骑士盖亚”怪兽的情况下，将该怪兽加入自己的手牌，剩余的卡全部送至墓地。不是的情况下，将出示给对手的卡全部送至墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32362575,'魔导杂货商人','①：此卡反转的情况下发动。从自己牌组上面翻开卡，直至翻到魔法・陷阱卡为止，将该魔法・陷阱卡加入手牌。将剩余的所翻开的卡全部送至墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32391566,'额外遮蔽者','对手特殊召唤怪兽时，可从手牌特殊召唤此卡。以此效果特殊召唤的回合，因对手卡牌效果给予我方的效果伤害将由对手代替承受。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32391631,'野蛮竞技场','怪兽进行攻击的场合，该控制者在伤害步骤结束时回复３００LP。只要此卡存在于场上，能够发动攻击的怪兽必须发动攻击。结束阶段时，破坏回合玩家场上所有未进行攻击宣言的攻击表示怪兽。','LP回复','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32393580,'电子鲨','我方场上存在有水属性怪兽的场合，此卡可无须释放进行召唤。','不用解放召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32422602,'战华之智－诸葛孔',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：此卡以“战华”卡的效果从牌组加入手牌的情况下可以发动。将此卡特殊召唤。\r\n②：魔法・陷阱卡发动时，将自己场上的1张表侧表示的“战华”永续魔法・永续陷阱卡送至墓地可以发动。将该发动无效。\r\n③：自己场上存在“战华之德－刘玄”，且怪兽的效果发动时，将自己场上的1张表侧表示的“战华”永续魔法・永续陷阱卡送至墓地可以发动。将该发动无效。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32437102,'龙魂之力','仅限装备战士族怪兽。装备怪兽变成龙族，且攻击力、守备力各上升５００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32441317,'同步解除','①：以场上的1只同步怪兽为对象可以发动。将该同步怪兽放回额外牌组。然后，如果被放回了额外牌组的该怪兽原先同步召唤的一组素材怪兽全部都在自己墓地，可将该一组特殊召唤。','是否要把素材特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32442017,'终刻击针',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：在自己的主要阶段可以发动。将自己手牌・场上（表侧表示）的1张其他的“终刻”卡破坏。然后，从牌组挑选1只“终刻”怪兽，加入手牌或特殊召唤。此效果发动后，直至回合结束时为止自己从额外牌组仅可特殊召唤超量怪兽。\r\n②：此卡因效果被破坏的情况下，以场上的1只表侧表示怪兽为对象可以发动。将该怪兽破坏。','\r',char(13)),'\n',char(10)),'破坏并检索','破坏怪兽','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32446630,'混沌编号43 魂魄傀儡鬼神 混沌灵魂人偶',replace(replace('暗属性等级３怪兽×４\r\n①：自己的衍生物在１次战斗阶段中可攻击２次。\r\n②：此卡有“编号43 魂魄傀儡鬼 灵魂人偶”在作为超量素材的情况下，获得以下效果。\r\n●１回合１次，去除此卡的１个超量素材可以发动。将１只“魂魄衍生物”（恶魔族・暗・星１・攻／守？）特殊召唤至自己场上。此衍生物的攻击力・守备力变为对手LP一半的数值。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32446631,'魂魄衍生物','由“混沌编号43 魂魄傀儡鬼神 混沌灵魂人偶”的效果特殊召唤而来。此衍生物的攻击力和守备力将为特殊召唤此衍生物时对手生命值的一半。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32448765,'淘气仙星・蜀葵天使',replace(replace('“淘气仙星”怪兽2只\r\n①：只要此卡存在于怪兽区域，每当有“淘气仙星”怪兽被召唤・特殊召唤至此卡的连接端，就给予对手200伤害。\r\n②：此卡连接端的“淘气仙星”怪兽不会因战斗・效果被破坏。\r\n③：每当对手因“淘气仙星”怪兽的效果受到伤害就发动。此卡的攻击力直至回合结束时为止，上升相当于该伤害的数值。','\r',char(13)),'\n',char(10)),'上升攻击力','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32448766,'淘气仙星・蜀葵天使',replace(replace('“淘气仙星”怪兽2只\r\n①：只要此卡存在于怪兽区域，每当有“淘气仙星”怪兽被召唤・特殊召唤至此卡的连接端，就给予对手200伤害。\r\n②：此卡连接端的“淘气仙星”怪兽不会因战斗・效果被破坏。\r\n③：每当对手因“淘气仙星”怪兽的效果受到伤害就发动。此卡的攻击力直至回合结束时为止，上升相当于该伤害的数值。','\r',char(13)),'\n',char(10)),'上升攻击力','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32452818,'盔甲兵','身体虽小，但在草原上具备高强的守备力。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32453837,'编号2 蚊学忍者 影蚊',replace(replace('等级2怪兽×2只以上\r\n①：此卡不会因战斗被破坏，因此卡的战斗对自己造成的战斗伤害变为0。\r\n②：可攻击的对手怪兽必须攻击。\r\n③：自己或对手的怪兽攻击宣言时，可从以下效果中选择1个发动。\r\n●去除此卡的1个超量素材，在对手场上的1只表侧表示怪兽上放1个幻觉计数物。放有幻觉计数物的怪兽的效果无效化。\r\n●给予对手相当于1只放有幻觉计数物的怪兽的攻击力数值的伤害。','\r',char(13)),'\n',char(10)),'放置计数物','伤害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32465539,'电子光虫－电容茧',replace(replace('以此卡作为超量召唤的素材的场合，只可超量召唤昆虫族怪兽。\r\n①：１回合１次，此卡以攻击表示存在于场上的场合，可以我方墓地的１只昆虫族、等级３怪兽为对象发动。将此卡变成守备表示，并以守备表示特殊召唤对象怪兽。\r\n②：以场上的此卡作为素材超量召唤而来的怪兽获得以下效果。\r\n●此卡攻击守备表示怪兽的场合，直至伤害步骤结束时，对手不可发动魔法、陷阱、怪兽效果。','\r',char(13)),'\n',char(10)),'特殊召唤','「电子光虫－电容茧」效果适用中','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32467459,'神影依・弥赛芙蕾尔',replace(replace('“影依”怪兽＋暗属性怪兽＋地属性怪兽\r\n此卡仅可通过融合召唤方式特殊召唤。\r\n①：场上的此卡不受对手发动的魔法・陷阱卡的效果影响，且不受原本等级・阶级的数值低于此卡等级的、对手怪兽发动的效果影响。\r\n②：1回合1次，支付800LP可以发动。从牌组将1张“影依”卡或“炼狱”魔法・陷阱卡加入手牌。\r\n③：此卡被送至墓地的情况下可以发动。从自己墓地将1只“影依”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','检索','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32472237,'金属枪弹龙','此卡名的①②效果1回合仅可各使用1次。①：场上以此卡为对象的连接怪兽的效果发动时可以发动。将此卡破坏。然后，将与此卡之前所在区域同一纵列的对手的卡全部破坏。②：场上的此卡因战斗・效果破坏并被送至墓地的回合的结束阶段可以发动。从牌组将1只“金属枪弹龙”以外的“枪弹”怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32476434,'将棋怪兽 长矛香车','１回合１次，可选择我方场上除此卡以外的１只兽战士族、等级３怪兽并发动。被选择怪兽和此卡的等级均变成各自等级的合计数值。','等级变换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32476603,'银色枪弹龙','此卡名的①②效果1回合仅可各使用1次。①：以场上的此卡作为对象的连接怪兽的效果发动时可以发动。将此卡破坏。然后确认对手的额外牌组，挑选其中1张除外。②：场上的此卡因战斗・效果被破坏并被送至墓地的回合的结束阶段可以发动。从牌组将1只“银色枪弹龙”以外的“枪弹”怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32480825,'T.G.强力突击兵',replace(replace('协调＋协调以外的怪兽１只\r\n此卡名的①③效果１回合仅可各使用１次。\r\n①：此卡同步召唤的情况下可以发动。从牌组将１张“T.G.”魔法・陷阱卡加入手牌。\r\n②：在对手的主要阶段可以发动１次。将包含此卡在内的自己场上的怪兽作为素材进行同步召唤。\r\n③：此卡从怪兽区域被送至墓地的情况下可以发动。从牌组将１张“T.G.”卡送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32484853,'特异点的魔鬼',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：对手特殊召唤怪兽时，从手牌将此卡和1张魔法卡舍弃可以发动。将该怪兽破坏。','\r',char(13)),'\n',char(10)),'破坏特殊召唤的怪兽','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32485271,'栖身蔷薇的恶灵','“戈兰林”＋“蛇椰树”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32485518,'不朽支配者','此卡不可特殊召唤。可解放此卡并发动。选择我方墓地的１张“不死世界”加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32491822,'降雷皇哈蒙','此卡不可通常召唤。仅可在将自己场上的3张表侧表示的永续魔法卡送至墓地的情况下特殊召唤。①：只要此卡在怪兽区域以守备表示存在，对手不可选择其他的怪兽作为攻击对象。②：此卡战斗破坏对手怪兽并将其送至墓地的情况下发动。给予对手1000伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32491823,'降雷皇哈蒙','此卡不可通常召唤。仅可在将自己场上的3张表侧表示的永续魔法卡送至墓地的情况下特殊召唤。①：只要此卡在怪兽区域以守备表示存在，对手不可选择其他的怪兽作为攻击对象。②：此卡战斗破坏对手怪兽并将其送至墓地的情况下发动。给予对手1000伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32519092,'天威之拳僧','连接怪兽以外的“天威”怪兽1只','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32530043,'御影志士',replace(replace('等级4怪兽×2\r\n此卡名的效果1回合仅可使用1次。\r\n①：去除此卡的1个超量素材，可从以下效果中选择1个发动。\r\n●从牌组将1只岩石族怪兽加入手牌。\r\n●从手牌将1只岩石族怪兽以里侧守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'牌组检索','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32539892,'伊比','此卡因对手效果从手牌被舍弃至墓地时，给予对手生命１０００点伤害。','LP伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32541773,'画中潜伏者','寄宿着作者诅咒的画，据说持有它的人都将陷入不幸之中。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32542011,'燃起的大海',replace(replace('我方场上存在等级７或以上的水属性或炎属性怪兽的场合可发动。根据我方场上怪兽的属性，适用以下效果。\r\n●水属性：尽可能特殊召唤为了发动此回合效果怪兽的效果而被送入我方墓地的水属性怪兽。之后，挑选我方场上的１只怪兽破坏。\r\n●炎属性：挑选场上的１只怪兽破坏。之后，我方手牌为１张或以上的场合，挑选１张舍弃至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32543380,'火山性魔鬼','此卡不可通常召唤。我方场上１张表侧表示的“烈焰加农炮三戟式”送入墓地的场合可特殊召唤。对手的战斗阶段中，对手场上的攻击表示怪兽能够攻击的场合，必须攻击此卡。此卡因战斗破坏怪兽并送入墓地时，破坏对手场上的全部怪兽，并给予对手生命相当于被破坏怪兽数量×５００点伤害。','对手场上的怪兽全部破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32548318,'罗睺星宿',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：将自己手牌・牌组・场上的怪兽作为融合素材，将1只“星宿”融合怪兽融合召唤。此卡发动后，直至回合结束时为止，自己从额外牌组仅可特殊召唤融合怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32548609,'电力鼹鼠','此卡在１次的战斗阶段中可攻击２次。此卡攻击了里侧守备表示怪兽的伤害步骤开始时，可破坏该里侧守备表示怪兽。','里侧守备的攻击对象怪兽破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32549749,'武装再生',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：可从以下效果中选择1个发动。\r\n●以自己场上的1只表侧表示怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止上升800。\r\n●以自己或对手墓地的1张装备魔法卡为对象可以发动。将该卡放置在自己场上，或装备于自己场上的1只可装备该卡的怪兽。','\r',char(13)),'\n',char(10)),'攻击力上升','回收装备魔法卡','在场上放置','给怪兽装备','','','','','','','','','','','','');
INSERT INTO texts VALUES(32557233,'六花深深','此卡名的卡1回合仅可发动1张。此卡也可以通过解放自己场上的1只植物族怪兽发动。①：从自己墓地挑选1只“六花”怪兽以守备表示形式进行特殊召唤。在通过解放怪兽发动此卡的情况下，进而从自己墓地挑选1只植物族怪兽以守备表示形式进行特殊召唤。','不解放怪兽发动','解放怪兽发动','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32559361,'混沌编号9 天盖妖星 混沌戴森球',replace(replace('等级１０怪兽×３\r\n①：１回合１次，在自己的主要阶段可以发动。给予对手相当于此卡超量素材数量×３００的伤害。\r\n②：此卡与对手怪兽进行战斗的伤害步骤开始时可以发动。将该怪兽重叠在此卡下面作为超量素材。\r\n③：此卡有“编号9 天盖星 戴森球”在作为超量素材的情况下，获得以下效果。\r\n●１回合１次，去除此卡任意数量的超量素材可以发动。给予对手相当于去除数量×８００的伤害。','\r',char(13)),'\n',char(10)),'吸收素材','给与对手超量素材数量×300的伤害','超量素材取除，给与对手×800的伤害','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32566831,'红玉的宝牌','此卡名的卡１回合仅可发动１张。①：从手牌将１只等级７的“真红眼”怪兽送至墓地可以发动。自己从牌组抽２张。然后，可从牌组将１只等级７的“真红眼”怪兽送至墓地。','是否从牌组把1只７星「真红眼」怪兽送至墓地？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32569498,'屎壳郎','滚动比自身体积大上数倍的粪便来碾压对手。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32588805,'The despair URANUS',replace(replace('①：我方场上不存在魔法、陷阱卡，此卡上级召唤成功时可发动。对手宣言卡牌种类（永续魔法、永续陷阱）。我方从牌组挑选１张宣言种类的卡牌盖牌至我方的魔法与陷阱区域。\r\n②：此卡的攻击力上升我方场上表侧表示的魔法、陷阱卡数量×３００。\r\n③：只要此卡存在于怪兽区，我方魔法与陷阱区域的表侧表示卡牌不会因效果被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32600024,'龙女仆・客房龙女',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将1张“龙女仆”魔法・陷阱卡加入手牌。\r\n②：在自己・对手的战斗阶段开始时可以发动。将此卡放回手牌，从自己手牌・墓地将1只等级7以上的“龙女仆”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32603633,'究极・背水之阵','可支付LP使其变成１００点并发动。尽可能从我方墓地特殊召唤场上不存在有同名卡的冠有“六武众”之名的怪兽（同名卡最多１张）。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32615065,'霸道星 修罗',replace(replace('“霸胜星 韦驮天”＋等级５以上战士族怪兽\r\n①：１回合１次，在自己・对手的战斗阶段可以发动。对手场上所有表侧表示怪兽的攻击力变为０。\r\n②：怪兽之间进行战斗的伤害计算时可以发动１次。进行该战斗的双方怪兽的攻击力仅在该伤害计算时，上升相当于各自等级×２００的数值。\r\n③：融合召唤的此卡被对手破坏并被送至墓地的情况下可以发动。将１只“霸胜星 韦驮天”视为融合召唤从额外牌组特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32617464,'三闸极男巫',replace(replace('衍生物以外的怪兽2只以上\r\n①：根据与此卡相互连接着的怪兽数量获得以下效果。\r\n●1只以上：与此卡相互连接着的怪兽与对手怪兽进行战斗的情况下，该怪兽给予对手的战斗伤害变为两倍。\r\n●2只以上：1回合1次，以场上的1张卡为对象可以发动。将该卡除外。\r\n●3只：1回合1次，魔法・陷阱・怪兽的效果发动时可以发动。将该发动无效并除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32619583,'暗黑界之军神 银希尔巴','①：此卡因效果从手牌被舍弃至墓地的情况下发动。将此卡特殊召唤。因对手的效果被舍弃的情况下，对手进而挑选自身的2张手牌，以喜欢的顺序放回牌组下面。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32623004,'否定企鹅',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：只要此卡存在于怪兽区域，因“企鹅”卡的效果要从场上被放回手牌的卡不回手牌而直接被除外。\r\n②：此卡存在于墓地，且“企鹅”怪兽的效果发动时发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32626733,'螺旋龙','相传这是能制造海流漩涡攻击人们的海龙。它那巨大的鳍发出的螺旋波会吞噬一切。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32646477,'暗黑俯冲轰炸机',replace(replace('协调＋１只以上协调以外的怪兽\r\n此卡名的效果１回合仅可使用１次。①：在自己的主要阶段１，解放自己场上的１只怪兽可以发动。给予对手相当于解放怪兽等级×２００的数值的伤害。','\r',char(13)),'\n',char(10)),'伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32663969,'多米诺骨牌','对手场上的怪兽因战斗破坏并被送入墓地时，可将我方场上的１只怪兽送入墓地并发动。选择对手场上的１只怪兽并破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32665564,'零王的契约书',replace(replace('此卡名在规则上也视为“DD”卡。\r\n此卡名的①效果1回合仅可使用1次。\r\n①：以“零王的契约书”以外的自己场上的1张“DD”卡为对象可以发动。将该卡破坏，从牌组将1只“DD”怪兽特殊召唤。此效果发动后，直至回合结束时为止，自己仅可特殊召唤“DD”怪兽。\r\n②：在自己的准备阶段发动。自己受到1000伤害。','\r',char(13)),'\n',char(10)),'特殊召唤','伤害效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32671443,'博士D','①：从自己的墓地将1只“命运-英雄”怪兽除外可以发动。从自己的墓地挑选1只“命运-英雄”怪兽，加入手牌或特殊召唤。②：将墓地的此卡除外，以自己场上的2只“命运-英雄”怪兽为对象可以发动。1只对象怪兽的攻击力变为与另1只怪兽的攻击力相同。','加入手牌或特殊召唤','改变攻击力','请选择要改变攻击力的怪兽','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32679370,'英雄小子','此卡特殊召唤成功时可发动。从牌组特殊召唤任意数量的“英雄小子”。','特殊召唤','是否还要特殊召唤「－英雄小子」？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32687071,'无形噬体・怠惰',replace(replace('←3 【灵摆】 3→\r\n此卡的控制者在每个自己的准备阶段解放自己场上的１只怪兽。\n或不解放而是破坏此卡。\n①：只要自己场上有“无形噬体”怪兽存在，双方不可用抽牌以外的方法从牌组将卡加入手牌。\r\n【怪兽效果】\r\n①：只要此卡存在于怪兽区域，双方从额外牌组仅可特殊召唤“无形噬体”怪兽。','\r',char(13)),'\n',char(10)),'是否解放自己场上1只怪兽？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32692693,'北斗天熊・放射','发动此卡的情况下，在此卡上放７个计数物发动。①：“北斗天熊・放射”在自己场上仅可有１张以表侧表示形式存在。②：每次“北斗天熊”怪兽被从手牌・额外牌组特殊召唤，去除此卡的１个计数物可以发动。自己从牌组抽１张。③：在自己・对手的结束阶段，以自己墓地的１张“北斗天熊・放射”以外的“北斗天熊”卡为对象可以发动。将该卡放回牌组。','抽1张卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32696942,'三段腹骑士','超量素材的此卡为了发动超量怪兽的效果而被移除并送入墓地的场合，可从手牌特殊召唤１只等级３或以下的怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32703716,'捕获与群攻','我方有３只以上鱼族・海龙族・水族怪兽从游戏中被除外的场合，选择场上１张卡牌来发动此卡。将所选择卡牌从游戏中除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32710364,'宝玉兽 红玉兽',replace(replace('①：此卡特殊召唤成功时可发动。尽可能地特殊召唤我方的魔法与陷阱区域的“宝玉兽”怪兽卡。\r\n②：表侧表示的此卡在怪兽区被破坏的场合，可不送入墓地被视作永续魔法卡以表侧表示放置在我方的魔法与陷阱区域。','\r',char(13)),'\n',char(10)),'破坏时放置魔法陷阱区','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32723153,'魔力爆发','自己的手牌是０张的情况下可以发动。给予对手LP相当于自己墓地的魔法卡的数量×２００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32731036,'深渊兽 卢绯里昂',replace(replace('此卡不可通常召唤。\r\n“深渊兽 卢绯里昂”1回合1次，仅可在解放自己场上1只等级6以上的龙族・暗属性怪兽的情况下，从手牌・墓地特殊召唤。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：从手牌将此卡送至墓地可以发动。从牌组将“深渊兽 卢绯里昂”以外的1只“渊兽”怪兽加入手牌。\r\n②：在自己的主要阶段可以发动。从牌组将1张“烙印”永续魔法・永续陷阱卡以表侧表示放在自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32744558,'真次代机・司令塔','①：此卡召唤・特殊召唤时可以发动。从手牌将等级３以下的１只“次代机”怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32750341,'燃烧拳斗士 练拳','①：自己场上存在“燃烧拳斗士”怪兽的情况下，此卡可从手牌特殊召唤。以此方法特殊召唤的回合，自己无法进行战斗阶段。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32750510,'寒冰暴风雪领主',replace(replace('①：此卡可通过解放自己场上的2只水属性怪兽来从手牌特殊召唤。\r\n②：1回合1次，以场上的1只表侧表示怪兽为对象可以发动。在该怪兽上放1个寒冰计数物。\r\n③：解放此卡可以发动。将放有寒冰计数物的怪兽全部破坏。','\r',char(13)),'\n',char(10)),'放置「冰计数物」','放置有「冰计数物」的怪兽全部破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32751480,'砂之魔女','“岩石巨兵”＋“古代精灵”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32752319,'UFO机人战士',replace(replace('“UFO机人”＋战士族怪兽\r\n此卡的融合召唤仅限以上述卡牌进行。此卡的原本攻击力、守备力变为成为融合素材的２只怪兽的原本攻击力合计数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32754886,'黑幻象','①：直至回合结束时，我方场上的攻击力是２０００或以上的魔法师族・暗属性怪兽，不会因战斗而被破坏，效果不会被无效化，且不会受对手效果影响。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32756828,'烙印之兽',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：1回合1次，自己场上存在“渊兽”怪兽的情况下，在自己・对手的主要阶段，解放自己场上的1只龙族怪兽，以对手场上的1张卡为对象可以发动。将该卡破坏。\r\n②：在自己・对手的结束阶段，以自己墓地的1张“烙印”永续魔法・永续陷阱卡为对象可以发动。将该卡以表侧表示放在自己场上。','\r',char(13)),'\n',char(10)),'对方卡破坏','回收墓地永续魔陷','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32759190,'百臂无形手 雅多揶尔',replace(replace('此卡名的①③效果1回合仅可各使用1次。\r\n①：向对手出示手牌的此卡可以发动。将此卡放回牌组。然后，从牌组将1张“百臂无形”魔法・陷阱卡加入手牌。\r\n②：此卡与怪兽进行战斗的情况下，该2只不会因该战斗被破坏。\r\n③：此卡被送至墓地的情况下，以自己墓地的1张“百臂无形”魔法・陷阱卡为对象可以发动。将该卡放置在自己场上。','\r',char(13)),'\n',char(10)),'检索效果','放置','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32761286,'废铁异虫','①：此卡可直接攻击。②：此卡攻击的情况下，将在战斗阶段结束时被破坏。③：此卡因“废铁”卡的效果被破坏并被送至墓地的情况下，以自己墓地“废铁异虫”以外的１只“废铁”怪兽为对象可以发动。将该怪兽加入手牌。','此卡破坏','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32762201,'古代机械齿轮像',replace(replace('此卡名以①方法的特殊召唤１回合仅可进行１次，且②效果１回合仅可使用１次。\r\n①：对手场上的怪兽数量多于自己场上怪兽的情况下，此卡可从手牌特殊召唤。\r\n②：解放此卡可以发动。从手牌・牌组将除“古代机械齿轮像”以外的、１只“古代机械齿轮巨人”或记载有该卡名的怪兽无视召唤条件特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32764863,'超量复苏飞溅','此卡名的①②效果1回合1次，仅可使用其中1个。①：以自己墓地的1只阶级4以下的超量怪兽为对象可以发动。将该怪兽特殊召唤。以此效果特殊召唤的怪兽变为水属性。②：将墓地的此卡除外，以自己场上的1只水属性超量怪兽为对象可以发动。将1只阶级比自己的该怪兽高1的水属性超量怪兽重叠在对象怪兽上面，视为超量召唤从额外牌组特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32768230,'永恒电子',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：以自己墓地的1只机械族“电子”融合怪兽为对象可以发动。将该怪兽放回额外牌组，或无视召唤条件特殊召唤。\r\n②：自己场上的机械族的“电子”融合怪兽将被战斗・效果破坏的情况下，作为代替可将墓地的此卡除外。','\r',char(13)),'\n',char(10)),'回到额外牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32775808,'恶魔的显现',replace(replace('“恶魔的召唤”＋暗属性怪兽\r\n①：只要此卡存在于怪兽区，卡牌名被视为“恶魔的召唤”。\r\n②：只要此卡存在于怪兽区，我方场上“恶魔的召唤”的攻击力上升５００。\r\n③：融合召唤而来的此卡因对手被送入墓地的场合可发动。从我方手牌、牌组、墓地挑选１只“恶魔的召唤”并特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32785578,'感谢光临拉比丽斯','①：自己场上有恶魔族怪兽存在的情况下，在自己或对手的怪兽攻击宣言时，以场上的１张卡为对象可以发动。使该攻击无效，破坏对象的卡。然后，可以从手牌・牌组挑选１张“拉比丽斯”卡以外的通常陷阱卡放置在自己场上。','是否选卡放置？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32787239,'娱乐伙伴・喇叭熊猫',replace(replace('←3 【灵摆】 3→\r\n①：１回合１次，在我方主要阶段可发动。此卡的灵摆刻度提升１（最高提至１２）。\r\n【怪兽效果】\r\n“娱乐伙伴・喇叭熊猫”的效果１回合只可使用１次。\n①：我方的灵摆怪兽被选择为攻击对象时可发动。使该攻击无效。','\r',char(13)),'\n',char(10)),'灵摆刻度上升','攻击无效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32807846,'增援','①：从牌组将1只等级4以下的战士族怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32807847,'增援','①：从牌组将1只等级4以下的战士族怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32807848,'增援','①：从牌组将1只等级4以下的战士族怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32807849,'增援','①：从牌组将1只等级4以下的战士族怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32809211,'人造人７号','此卡可直接攻击对手玩家。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32825095,'白鳝',replace(replace('①：此卡召唤时适用。此回合，此卡可直接攻击对手。\r\n②：此卡从墓地特殊召唤的情况下可以发动。此回合，此卡视为协调。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32828466,'唤醒你的元素－英雄',replace(replace('“元素－英雄”融合怪兽＋战士族怪兽1只以上\r\n此卡仅可通过融合召唤方式特殊召唤。\r\n①：此卡的攻击力上升此卡融合素材的怪兽数量×300的数值，在1次战斗阶段中可攻击怪兽的次数最多为其中融合怪兽的数量。\r\n②：此卡与怪兽进行战斗的伤害计算后发动。将该怪兽破坏，给予对手相当于其原本攻击力数值的伤害。\r\n③：融合召唤的此卡被破坏的情况下发动。从手牌・牌组将1只战士族怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32828467,'唤醒你的元素－英雄',replace(replace('“元素－英雄”融合怪兽＋战士族怪兽1只以上\r\n此卡仅可通过融合召唤方式特殊召唤。\r\n①：此卡的攻击力上升此卡融合素材的怪兽数量×300的数值，在1次战斗阶段中可攻击怪兽的次数最多为其中融合怪兽的数量。\r\n②：此卡与怪兽进行战斗的伤害计算后发动。将该怪兽破坏，给予对手相当于其原本攻击力数值的伤害。\r\n③：融合召唤的此卡被破坏的情况下发动。从手牌・牌组将1只战士族怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32828635,'世界不灭',replace(replace('①：为使合计等级达到仪式召唤的怪兽的等级以上，解放自己场上的怪兽，从手牌将“破灭之女神 露茵”或“终焉之王 迪米斯”仪式召唤。\r\n②：从墓地将不是在此回合被送至墓地的此卡放回牌组可以发动。从牌组将1张“世界终灭”加入手牌。然后，可从自己墓地将1只“破灭之女神 露茵”或“终焉之王 迪米斯”加入手牌。','\r',char(13)),'\n',char(10)),'','是否回收卡片？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32835363,'恶意破解','１回合１次，场上的怪兽由于卡片的效果被送至墓地的情况下发动。给予该怪兽的原本的持有者８００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32841045,'魔弹射手 卡斯帕',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：只要此卡存在于怪兽区域，自己可在自己・对手回合中从手牌发动“魔弹”魔法・陷阱卡。\r\n②：在此卡的同一纵列发动了魔法・陷阱卡的情况下可以发动。从牌组将１张卡名与该发动的卡不同的“魔弹”卡加入手牌。','\r',char(13)),'\n',char(10)),'牌组检索','适用「魔弹射手 卡斯帕」的效果来发动','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32854013,'猛突进','选择我方场上的１只兽族怪兽并破坏，选择对手场上的１只怪兽返回至牌组。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32872239,'加尔加尔德炼尸魔',replace(replace('←9 【灵摆】 9→\r\n【怪兽效果】\r\n身披摇曳火焰的鸟魔人，能化作万象之姿。在由鸟化人、由人化鸟的轮回之中，早已遗忘自己原本的模样。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32872833,'星间龙 秒差距','我方场上存在有等级８怪兽的场合，此卡可无须释放进行召唤。','不解放进行召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32875265,'傀儡葬仪－傀偶游行',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：对手场上的怪兽数量多于自己场上的怪兽数量的情况下，以其数量差为上限，从牌组将“机关傀偶”怪兽特殊召唤（同名卡最多１张）。自己的LP少于对手２０００以上的情况下，进而可从牌组将１张“升阶魔法”通常魔法卡放置在自己场上。此卡发动后，直至回合结束时为止自己仅可特殊召唤“机关傀偶”怪兽。','\r',char(13)),'\n',char(10)),'是否放置「升阶魔法」魔法卡？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32887445,'繁华的花笑',replace(replace('此卡牌名的卡牌１回合只可发动１张。\r\n①：从我方牌组上方翻阅相当于我方墓地“繁华的花笑”数量＋３张之卡牌。其中若有３种（怪兽、魔法、陷阱）卡牌的场合，从中挑选１张加入手牌，并将剩馀卡牌送入墓地。没有的场合，将所有翻阅的卡牌返回至牌组。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32907538,'造墙者','此卡召唤成功时，可选择１只对手场上的怪兽并发动。只要此卡以表侧表示存在于场上，被选择怪兽不可攻击，也不可释放。此卡的控制者每次自己的结束阶段支付５００LP。或不支付５００LP破坏此卡。','是否要支付500基本分维持「造墙者」？','攻击限制','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32909498,'怒刹帝利・芬里尔','此卡名的②③效果１回合仅可各使用１次。①：自己场上不存在怪兽的情况下，此卡可从手牌中特殊召唤。②：在自己的主要阶段可以发动。从牌组将１只“怒刹帝利”怪兽加入手牌。③：此卡的攻击宣言时，或对手发动怪兽的效果的情况下，以对手场上的１张表侧表示的卡为对象可以发动。将该卡以里侧表示除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32912040,'三形金字塔大师',replace(replace('①：１回合１次，可将我方场上１张表侧表示的“三形金字塔”卡牌送入墓地，并以１张被盖牌于场上的卡牌为对象发动。破坏该卡。\r\n②：在对手回合１次，可以我方场上的１张“三形金字塔”场地魔法卡为对象发动。将该卡送入墓地，并从牌组发动１张与该卡不同卡牌名的“三形金字塔”场地魔法卡。','\r',char(13)),'\n',char(10)),'场上放置的1张卡破坏','场地魔法卡发动','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32918479,'光神机－闪空','此卡因直接攻击给予对手生命战斗伤害时，从我方牌组抽取１张卡牌。在此卡牌进行了召唤、反转召唤、特殊召唤回合的结束阶段时，将此卡送入墓地。','抽牌','送至墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32919136,'堕落',replace(replace('可装备对手场上的怪兽。\r\n①：获得装备怪兽的控制权。\r\n②：在对手准备阶段发动。自己受到８００点伤害。\r\n③：自己场上没有“恶魔”卡存在的情况下，此卡被破坏。','\r',char(13)),'\n',char(10)),'LP伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32933942,'宝玉兽 紫晶猫',replace(replace('①：此卡可直接攻击。该场合，此卡给予对手的战斗伤害减半。\r\n②：表侧表示的此卡在怪兽区被破坏的场合，可不送入墓地被视作永续魔法卡以表侧表示放置在我方的魔法与陷阱区域。','\r',char(13)),'\n',char(10)),'破坏时放置魔法陷阱区','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32939238,'忍法装具 铁土龙',replace(replace('此卡名的②③效果１回合仅可各使用１次。\r\n①：装备怪兽的攻击力上升５００，也视为“忍者”怪兽。\r\n②：从自己的墓地将１只“忍者”怪兽除外，以场上的１张卡为对象可以发动。将该卡破坏。\r\n③：此卡从场上被送至墓地的情况下，以自己１只被除外的“忍者”怪兽为对象可以发动。将该怪兽加入手牌，或以里侧守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32965616,'精灵圣后 多里雅德','此卡不可通常召唤。仅可在自己・对手墓地的怪兽属性为6种以上的情况下特殊召唤。①：此卡的攻击力・守备力上升相当于自己・对手墓地怪兽属性种类×500的数值。②：对手特殊召唤怪兽之际，将自己墓地的3只怪兽除外可以发动。该特殊召唤无效，将该怪兽破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32975247,'神龙 伟战',replace(replace('此卡名的②③效果１回合仅可各使用１次。\r\n①：被特殊召唤的此卡不会因战斗被破坏。\r\n②：从自己的墓地及自己场上的表侧表示怪兽中，将包含场上的此卡在内的３只“神龙 伟战”除外可以发动。将对手场上的卡全部破坏。\r\n③：在自己・对手的结束阶段可以发动。依自己场上的龙族怪兽的数量，从自己的牌组上面将卡送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32986898,'肃星之钢机',replace(replace('３只连接怪兽以外的怪兽\r\n此卡名的②效果１回合仅可使用１次。\r\n①：此卡的攻击力上升相当于作为此卡连接素材的怪兽的原本等级・阶级合计×１００的数值。\r\n②：以连接怪兽以外的、对手场上的１只拥有此卡的攻击力以下的攻击力的怪兽为对象可以发动。将该怪兽破坏。此卡是以超量怪兽为素材连接召唤的情况下，进而给予对手相当于所破坏怪兽原本攻击力一半数值的伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32991027,'冰结界的剑士 格奥鲁吉亚斯',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己场上有“冰结界”怪兽存在的情况下可以发动。从手牌将此卡以守备表示特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从自己的手牌・墓地将１只等级５以下的“冰结界”怪兽特殊召唤。\r\n③：只要自己场上存在其他“冰结界”怪兽，对手不可发动墓地的怪兽的效果。','\r',char(13)),'\n',char(10)),'从手牌特殊召唤','从手牌·墓地特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32991300,'契印魔镌・神羔棺',replace(replace('包含恶魔族・光属性怪兽在内的怪兽２只以上\r\n①：在每个自己・对手回合中１次，以自己墓地连接怪兽以外的１只恶魔族・光属性怪兽为对象可以发动。将该怪兽特殊召唤，将自己场上的此卡视为拥有以下效果的装备魔法卡，装备于该怪兽。\r\n●装备怪兽的攻击力上升相当于自身装备中的连接怪兽的连接标记的合计×６００的数值。\r\n●装备怪兽攻击了守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32995007,'天狼王 苍狼星',replace(replace('协调＋协调以外的怪兽1只以上\r\n①：场上的此卡被破坏并被送至墓地的情况下，以对手场上的1只表侧表示怪兽为对象发动。该怪兽的攻击力下降2400。','\r',char(13)),'\n',char(10)),'攻击下降','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32995276,'连接门徒',replace(replace('等级4以下的电子界族怪兽1只\r\n此卡名的效果1回合仅可使用1次。①：解放1只此卡连接端的怪兽可以发动。自己从牌组抽1张，然后挑选1张手牌放回牌组最下面。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(32999573,'超量超控','场上的超量怪兽移除其超量素材并发动效果的场合，可将１张手牌以里侧表示从游戏中除外来代替移除的１个超量素材。此效果双方在１个回合只可使用１次。','是否要使用「超量超控」的效果？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33008376,'原物质・吉伽环龙',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：只要此卡存在于怪兽区域，自己从额外牌组仅可特殊召唤超量怪兽。\r\n②：舍弃１张手牌可以发动。从手牌・牌组将１只等级３通常怪兽特殊召唤。舍弃通常怪兽来发动的情况下，可将以此效果特殊召唤的怪兽改成１只“原物质”怪兽。','\r',char(13)),'\n',char(10)),'自己不是超量怪兽不可从额外牌组特殊召唤','手牌·牌组特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33015627,'时械神 桑达伊恩',replace(replace('此卡不可从牌组特殊召唤。\r\n①：“时械神 桑达伊恩”在自己场上仅可有１只以表侧表示存在。\r\n②：仅有对手场上有怪兽存在的情况下，此卡无需解放即可召唤。\r\n③：此卡不会因战斗・效果被破坏，因此卡的战斗对双方造成的战斗伤害变为０。\r\n④：此卡进行战斗的战斗阶段结束时发动。给予对手２０００伤害。\r\n⑤：在自己的准备阶段发动。将此卡放回持有者的牌组。','\r',char(13)),'\n',char(10)),'不用解放作召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33017655,'暗黑界之门',replace(replace('①：场上的恶魔族怪兽的攻击力・守备力上升300。\r\n②：1回合1次，从自己墓地将1只恶魔族怪兽除外可以发动。从手牌挑选1只恶魔族怪兽舍弃。然后，自己抽1张。','\r',char(13)),'\n',char(10)),'丢弃和抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33017964,'幻魔之扉',replace(replace('此卡名的效果在决斗中仅可适用1次。\r\n①：支付一半LP可以发动。将对手场上的怪兽全部破坏。然后，可从对手墓地将1只怪兽无视召唤条件特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'发动','是否特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33022867,'魔兽皇帝 加泽特','此卡不可通常召唤。仅可在解放自己场上的3只怪兽的情况下特殊召唤。①：此卡的攻击力变为相当于为特殊召唤此卡解放的怪兽原本攻击力的合计数值。②：只要此卡存在于怪兽区域，对手在战斗阶段不可发动魔法・陷阱・怪兽的效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33026283,'双天将 金刚',replace(replace('“双天拳之熊罴”+“双天”怪兽×2\r\n此卡名的效果③在1个回合中仅可使用1次。\r\n①：在此卡进行战斗的情况下，直至伤害步骤结束时为止，对手不可发动魔法、陷阱、怪兽的效果。\r\n②：计算此卡攻击的伤害值后可以发动。挑选对手场上的1只怪兽放回持有者的手牌中。\r\n③：自己场上存在2只以上的融合怪兽，且以场上的此卡为对象的对手的魔法・陷阱卡发动了效果时可以发动。使该发动无效。','\r',char(13)),'\n',char(10)),'破坏怪兽','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33031674,'灼热的试练','用于召唤“传说的爆炎使”。必须从手牌・我方场上解放合计等级７以上的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33034646,'机甲忍者 火','此卡召唤、反转召唤、特殊召唤成功时，可选择我方场上的１只冠有“忍者”之名的怪兽发动。被选择怪兽的等级上升１级。','等级上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33041277,'电子革新系统','①：从自己的手牌・墓地挑选1只“电子龙”特殊召唤。以此效果特殊召唤的怪兽不会因效果被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33055499,'地雷蜘蛛的饵食',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡发动后，变为通常怪兽（昆虫族・地・星５・攻２１００／守１００），特殊召唤至正面的自己的主要怪兽区域（也视为陷阱卡）。然后，可将与此卡同一纵列的１只对手怪兽破坏。\r\n②：将墓地的此卡除外可以发动。将自己的牌组・除外状态的“雷魔神－桑迦”、“风魔神－休迦”、“水魔神－苏迦”中的任意１只加入手牌。','\r',char(13)),'\n',char(10)),'','','是否把对手怪兽破坏？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33057951,'浮上','可选择我方墓地中１只等级３以下的鱼族・海龙族・水族怪兽来发动此卡。以表侧守备表示特殊召唤所选择的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33062423,'解码终结',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：以自己场上的１只“解码语者”为对象可以发动。根据该怪兽连接端的怪兽数量，此回合适用以下效果。\r\n●１只以上：该怪兽的攻击力，上升相当于其连接端的怪兽数量×５００的数值。\r\n●２只以上：该怪兽战斗破坏的怪兽在伤害计算后将被除外。\r\n●３只：该怪兽战斗破坏对手怪兽的伤害计算后发动。将对手场上的卡全部破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33064647,'一眼盾龙','身上装备的盾不仅可以保护自己，还可以用于突击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33066139,'狩猎卡牌的死神','反转：选择场上的１张陷阱卡并将其破坏。选择被盖牌的卡牌的场合，翻开该卡进行确认，若为陷阱卡则破坏，若为魔法卡的场合则恢复原状。','陷阱破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33093439,'电子天棓四','此卡不可通常召唤。仅可在从自己的墓地及自己场上表侧表示的怪兽中，将所有机械族・光属性怪兽除外的情况下特殊召唤。①：此卡的攻击力・守备力变为为了将此卡特殊召唤而除外的怪兽数量×500。②：在此卡特殊召唤成功的情况下发动。将场上此卡以外的所有表侧表示的怪兽送至墓地。','送至墓地','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33099732,'超未来融合－超永望结合',replace(replace('①：可从以下效果中选择1个发动（此卡名的以下效果1回合仅可各选择1次）。\r\n●向对手出示额外牌组的1只融合怪兽，从牌组将1只卡名记载于该怪兽的融合素材怪兽送至墓地。此回合，自己不可特殊召唤以此效果送至墓地的怪兽及其同名怪兽，不可发动其怪兽效果。\r\n●将自己墓地的怪兽作为融合素材除外，将1只机械族・暗属性融合怪兽融合召唤。','\r',char(13)),'\n',char(10)),'把素材送至墓地','进行融合召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33103459,'娱乐伙伴小角',replace(replace('①：在成功召唤或特殊召唤了此卡的我方主要阶段，可以我方场上１只此卡以外攻击力１０００以下的“娱乐伙伴”怪兽为目标发动１次。将我方场上面朝上攻击状态的该怪兽和此卡变为守备状态，从卡组中将１只“异色眼”怪兽加入手牌。\r\n②：在对手回合，可从我方墓地将此卡和１只“娱乐伙伴小角”以外的“娱乐伙伴”怪兽除外以发动。恢复我方５００点LP。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33112041,'火山性鼠','他是一种栖息于灼热之火山地带的变种老鼠。拥有可承受任何高温的身体。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33113958,'海善龙',replace(replace('等级３怪兽×２\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡特殊召唤的情况下可以发动。从牌组将１张“善德风暴”加入手牌。\r\n②：可从以下效果中选择１个发动。\r\n●去除自己场上的１个超量素材。然后，从自己墓地将“海善龙”以外的１只鱼族・海龙族・水族怪兽加入手牌。\r\n●以场上的２只超量怪兽为对象可以发动。将其中１只的１个超量素材作为另１只的超量素材。','\r',char(13)),'\n',char(10)),'加入手牌','回收墓地','转移超量素材','请选择失去超量素材的那只怪兽','','','','','','','','','','','','');
INSERT INTO texts VALUES(33114323,'金属银铠甲','①：只要装备怪兽存在于自己场上，对手不可将装备怪兽以外的、双方场上・墓地的怪兽及被除外的怪兽作为效果的对象。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33129626,'半人马米娜',replace(replace('战士族・光属性怪兽＋兽族怪兽\r\n此卡名的①③效果1回合仅可各使用1次。①：在自己的主要阶段可以发动。从自己的手牌・墓地挑选1只等级2以下的怪兽特殊召唤。②：1回合1次，对手在自己的回合发动陷阱卡时可以发动。将该发动无效，并将该卡就此放置。③：此卡作为战士族・风属性同步怪兽的同步素材被送至墓地的情况下可以发动。挑选场上的1只表侧表示怪兽破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33145233,'仪式魔人毁灭者',replace(replace('①：进行仪式召唤的场合，可作为１只该仪式召唤所必需等级的怪兽，将墓地的此卡除外。\r\n②：使用此卡仪式召唤的怪兽不会成为对手效果的对象。','\r',char(13)),'\n',char(10)),'「仪式魔人毁灭者」效果适用中','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33158448,'方程式运动员 光明御主',replace(replace('协调＋协调以外的怪兽1只以上\r\n①：此卡的攻击力上升此卡等级×300的数值。\r\n②：此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。\r\n③：每次“方程式运动员”魔法・陷阱卡的效果发动则可以发动（伤害步骤也可以发动）。此卡的等级上升1。\r\n④：1回合1次，对手发动魔法・陷阱卡的效果时可以发动。此卡的等级下降2，将该发动无效并破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33166263,'超越召唤兽 埃翁',replace(replace('属性不同的融合怪兽×2只以上\r\n此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：此卡融合召唤的情况下可以发动。以作为该融合素材的怪兽数量为上限，将自己・对手的、场上・墓地的卡除外。以3只以上作为素材的情况下，进而可确认对手的额外牌组，从其中将最多3张除外。\r\n②：在自己・对手回合中，宣言1个属性可以发动。此卡以外的、场上所有的怪兽直至回合结束时为止变为所宣言的属性。','\r',char(13)),'\n',char(10)),'除外效果','改变属性','是否除外额外？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33171768,'超能者神谕',replace(replace('念动力族怪兽＋同步・超量・连接怪兽\r\n此卡名的②③效果1回合仅可各使用1次。\r\n①：此卡融合召唤时适用。此卡的攻击力直至下个回合结束时为止，上升作为其融合素材的同步・超量・连接怪兽的数量×1000的数值。\r\n②：对手将怪兽特殊召唤之际可以发动。将其无效，将该怪兽除外。\r\n③：融合召唤的此卡被送至墓地的情况下，从自己墓地将1张“瞬移”通常・速攻魔法卡除外可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤无效','特殊召唤','「超能者神谕」效果适用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33178416,'奈耳','全身长满针刺的鱼。从腹部下方发射导弹。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33184167,'同族感染病毒','①：舍弃１张手牌，宣言１个种族可以发动。将场上的宣言种族的怪兽全部破坏。','宣言种族的怪兽全部破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33184236,'机偶大宅','我方场上冠有“机偶”之名的表侧表示怪兽变更其表示形式时可发动。选择场上的１张卡牌并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33198837,'大植然兽',replace(replace('地属性协调＋１只以上协调以外的地属性怪兽\r\n①：魔法卡发动时，从自己牌组上面将２张卡送至墓地可以发动。此卡在场上以表侧表示存在的情况下，将该发动无效并破坏。','\r',char(13)),'\n',char(10)),'魔法卡的发动无效并破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33202303,'地缚戒隶 地画戈兰林那',replace(replace('“地缚”怪兽＋暗属性怪兽\r\n此卡名的①②③效果１回合仅可各使用１次。\r\n①：此卡特殊召唤的情况下可以发动。从牌组将１只“地缚”怪兽加入手牌。\r\n②：以自己场上的１只暗属性同步怪兽为对象可以发动。此回合，该怪兽可直接攻击。\r\n③：对手场上的怪兽因“地缚”卡的效果被破坏的情况下，以１只该被破坏的怪兽为对象可以发动。给予对手该怪兽的原本攻击力数值的伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33206889,'娱乐巫师 高空秋千力量魔女',replace(replace('“娱乐巫师”怪兽×2\r\n①：只要此卡存在于怪兽区域，自己场上的“娱乐巫师”怪兽不会因自己的卡的效果被破坏，且对手不可将其作为效果的对象。\r\n②：只要自己场上存在“娱乐巫师 高空秋千力量魔女”以外的“娱乐巫师”怪兽，对手怪兽不可将此卡选择为攻击对象。\r\n③：自己的“娱乐巫师”怪兽与对手怪兽进行战斗的攻击宣言时可以发动。该对手怪兽的攻击力下降600。','\r',char(13)),'\n',char(10)),'降低攻击力','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33212663,'大星义・终焉','此卡不可通常召唤。从自己的墓地及自己场上的表侧表示怪兽中，将种族不同的3只怪兽除外的情况下可以特殊召唤。此卡名的②效果1回合仅可使用1次。①：场上的此卡不会因效果被破坏。②：宣言1个场上的怪兽种族可以发动。将场上宣言种族的怪兽全部破坏。直至下个回合结束时为止，双方不可特殊召唤宣言种族的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33225925,'久远之魔术师 米拉','①：成功召唤此卡的场合，以对手场上１张里侧表示的卡牌为对象发动此卡。确认该卡。对手不可针对此效果的发动来发动魔法・陷阱卡。','确认对手场上放置的1张卡','请选择一张要确认的卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33236860,'黑羽－孤高之银风',replace(replace('“黑羽”协调＋协调以外的怪兽2只以上\r\n①：此卡同步召唤时，以场上的最多2只表侧表示怪兽为对象可以发动（发动此效果的回合中，自己无法进行战斗阶段）。将守备力低于此卡攻击力的对象怪兽破坏。\r\n②：只要此卡存在于怪兽区域，每个对手回合仅1次，自己的“黑羽”怪兽不会因战斗被破坏。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33244944,'与艾克佐迪亚的契约','①：我方墓地存在有“被封印的艾克佐迪亚”“被封印者的右腕”“被封印者的左腕”“被封印者的右足”“被封印者的左足”的场合可发动。从手牌特殊召唤１只“艾克佐迪亚的亡灵”。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33245030,'库里波球','①：对手怪兽的攻击宣言时，从手牌将此卡送至墓地可以发动。将该攻击怪兽改成守备表示。②：进行仪式召唤的情况下，可将墓地的此卡除外来作为所需等级数值的怪兽中的１只。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33248692,'子机猎手','我方场上的怪兽因战斗破坏并被送入墓地时可发动。我方回复相当于该怪兽原本攻击力数值的LP。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33250142,'天极辉舰－熊斗龙巧','此卡名规则上也视为“北斗天熊”卡、“龙机巧”卡。此卡仅可以“北斗天熊龙机巧极”的效果特殊召唤。①：１回合１次，其他效果怪兽被特殊召唤至自己场上的情况下可以发动。从牌组将１只“北斗天熊”怪兽或“龙机巧”怪兽加入手牌。②：１回合１次，以自己１只被除外的“北斗天熊”怪兽或“龙机巧”怪兽为对象可以发动。将该怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33252803,'升阶魔法－速攻混沌','①：以“混沌编号”怪兽以外的、自己场上的１只“编号”超量怪兽为对象可以发动。从额外牌组将阶级比该自己怪兽高１的、拥有相同“编号”数字的１只“混沌编号”怪兽重叠在对象怪兽上面，视为超量召唤来特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33256280,'炼装勇士・金骑兵',replace(replace('←1 【灵摆】 1→\r\n①：１回合１次，可以我方场上１张除此卡以外的表侧表示卡牌为对象发动。破坏该卡，并从牌组挑选１张“炼装勇士”魔法、陷阱卡盖牌至我方场上。\r\n【怪兽效果】\r\n浑身闪烁着金光，以豪爽的漂移跑法横扫敌人。尽管经常都很夸张地出现侧滑失控，但本人坚定立场地表示那就是必杀技。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33280639,'破坏剑士的摇篮',replace(replace('“破坏剑士的摇篮”１回合仅可发动１张。\r\n①：从牌组将“破坏剑士的摇篮”以外的１张“破坏剑”卡和１只“毁灭剑士”怪兽送至墓地可以发动。从自己的额外牌组・墓地挑选１只“破戒蛮龙－毁灭龙”特殊召唤。以此效果特殊召唤的怪兽将在下个回合的结束阶段被破坏。\r\n②：将墓地的此卡除外可以发动。此回合，自己场上的“破坏剑”卡不会因战斗・效果被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33282498,'弧光勇烈龙',replace(replace('①：此卡从墓地特殊召唤成功的场合可发动。将所有对手场上表侧表示的魔法、陷阱卡除外，并此卡的攻击力、守备力上升因此效果被除外的卡牌数量×２００。\r\n②：在此卡被送入墓地的下一回合的准备阶段，可以我方墓地的１只除“弧光勇烈龙”以外的等级７、８的龙族怪兽为对象发动。特殊召唤该怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33296432,'教导之天启 亚丁','此卡名的①③效果１回合仅可各使用１次。①：场上有被从额外牌组特殊召唤的怪兽存在的情况下可以发动。从手牌将此卡特殊召唤。②：此卡不会因与从额外牌组中被特殊召唤的怪兽的战斗而被破坏。③：场上的此卡因战斗・效果被破坏的情况下可以发动。从牌组将１只“教导之天启 亚丁”以外的“教导”怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33298291,'兽血沸足蹈',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：对手怪兽的直接攻击宣言时，对手场上的表侧表示怪兽的攻击力合计为８０００以上的情况下可以发动。从自己的手牌・牌组・墓地各挑选３只原本卡名不同的怪兽，以攻击表示特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33300669,'无形噬体・嫉妒',replace(replace('←5 【灵摆】 5→\r\n此卡的控制者在每个自己的准备阶段解放自己场上的１只怪兽。\n或不解放而是破坏此卡。\n①：只要自己场上有“无形噬体”怪兽存在，双方不可连锁发动魔法・陷阱・怪兽的效果。\r\n【怪兽效果】\r\n①：只要灵摆召唤・反转的此卡存在于怪兽区域，双方从额外牌组仅可特殊召唤“无形噬体”怪兽。','\r',char(13)),'\n',char(10)),'是否解放自己场上1只怪兽？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33302407,'毒连锁','未进行战斗的我方回合的结束阶段时可发动。从对手牌组上方将相当于我方场上冠有“链条”之名怪兽数量的卡牌送入墓地。','牌组送墓','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33302589,'星圣 双子卡斯托尔',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：此卡召唤・反转召唤・特殊召唤的情况下可以发动。从牌组将“星圣 双子卡斯托尔”以外的1只“星圣”怪兽特殊召唤。此回合，自己从额外牌组仅可特殊召唤光・暗属性怪兽。\r\n②：持有此卡作为超量素材的“星圣”超量怪兽获得以下效果。\r\n●1回合1次，对手发动魔法卡的效果时可以发动。去除自己场上的2个超量素材，将该效果无效并破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','魔法卡的效果发动无效（星圣 双子卡斯托尔）','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33314479,'飞鲤',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：从手牌将１只水属性怪兽舍弃可以发动。此卡的攻击力上升５００。此效果在对手回合中也可以发动。\r\n②：此卡以战斗破坏对手怪兽时，解放此卡可以发动。从手牌・牌组将１只鱼族・海龙族・水族怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33318980,'暗黑骑士盖亚士兵','此卡名的①②③效果１回合仅可各使用１次。①：解放自己场上的１只龙族融合怪兽可以发动。从手牌将此卡特殊召唤。此效果在对手回合中也可以发动。②：此卡特殊召唤成功的情况下，以场上１只攻击表示的怪兽为对象可以发动。将该怪兽改成守备表示。③：解放此卡可以发动。从牌组将“暗黑骑士盖亚士兵”以外的１只等级７以上的战士族怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33323657,'念力之魂','可释放我方场上１只念动力族怪兽并发动。我方回复被释放怪兽的等级×３００LP。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33325951,'灵魂鸟影－姬孔雀',replace(replace('以“灵魂鸟之降神”降临\r\n此卡名的②效果１回合仅可使用１次。\r\n①：此卡只要存在于手牌・场上，卡名视为“灵魂鸟神－姬孔雀”。\r\n②：此卡仪式召唤的情况下可以发动。从牌组将效果文本上记载有“灵魂怪兽”的１张魔法・陷阱卡加入手牌。\r\n③：此卡被除外的下个回合的准备阶段发动。将除外状态的此卡特殊召唤。\r\n④：此卡特殊召唤的回合的结束阶段发动。将此卡放回手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33327029,'炼装勇士・反制',replace(replace('①：我方场上的卡牌因战斗、效果被破坏的场合可发动。从牌组特殊召唤１只“炼装勇士”怪兽。\r\n②：可将墓地的此卡除外并发动。从我方的额外牌组将１只表侧表示的“炼装勇士”灵摆怪兽加入手牌。此效果在此卡被送入墓地的回合不可发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33331231,'闪术兵器－H.A.M.P.',replace(replace('此卡名在规则上也视为“闪刀”卡。\r\n此卡名以①方法的特殊召唤１回合仅可进行１次。\r\n①：自己场上存在“闪刀姬”怪兽的情况下，此卡可以解放自己或对手场上的１只怪兽，从手牌特殊召唤至其控制者的场上。\r\n②：此卡因战斗被破坏时，以对手场上的１张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'往自己场上特殊召唤','往对手场上特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33334269,'DD 幽灵',replace(replace('①：此卡被送至墓地的情况下，以除“DD 幽灵”以外的、自己墓地的1只“DD”怪兽或1张“契约书”卡为对象可以发动。从牌组将1张该卡的同名卡送至墓地。\r\n②：此卡被除外的情况下，以除“DD 幽灵”以外的、自己除外状态的1只“DD”怪兽或1张“契约书”卡为对象可以发动。将该卡放回墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33347467,'灵魂护送船',replace(replace('此卡不可通常召唤。\r\n从自己的墓地将１只光属性怪兽除外的情况下可以特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33365932,'火山性子弹','①：此卡存在于墓地的情况下，１回合１次，支付５００LP可以发动。此卡存在于墓地的情况下，从牌组将１只“火山性子弹”加入手牌。','把1只「火山性子弹」加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33391067,'反弹诅咒的偶人',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：给予自己伤害的怪兽的效果发动时可以发动。因该效果产生的对自己的效果伤害由对手代替承受。\r\n②：此卡存在于墓地，自己受到战斗伤害时可以发动。将此卡放置在自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33393090,'幽威',replace(replace('此卡名的效果在决斗中仅可使用１次，发动此效果的回合中，自己仅可特殊召唤怪兽１次。\r\n①：仅此１张卡召唤・反转召唤・特殊召唤成功的情况下可以发动。跳过下一个对手的抽牌阶段。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33396948,'被封印的艾克佐迪亚','此卡和“被封印者的右臂”、“被封印者的左臂”、“被封印者的右足”、“被封印者的左足”全部在手牌集齐时，自己获得决斗胜利。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33396949,'被封印的艾克佐迪亚','此卡和“被封印者的右臂”、“被封印者的左臂”、“被封印者的右足”、“被封印者的左足”全部在手牌集齐时，自己获得决斗胜利。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33396950,'被封印的艾克佐迪亚','此卡和“被封印者的右臂”、“被封印者的左臂”、“被封印者的右足”、“被封印者的左足”全部在手牌集齐时，自己获得决斗胜利。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33407125,'白银的迷宫城・拉比丽斯',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：自己发动被放置的“光临拉比丽斯”通常陷阱卡的情况下，可以在其效果后追加以下的效果。\r\n●破坏场上的1张卡。\r\n②：自己发动“拉比丽斯”卡以外的通常陷阱卡的情况下可以发动。从自己手牌・墓地将1只恶魔族怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'是否使用「白银的迷宫城・拉比丽斯」的效果？','恶魔族怪兽特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33413279,'爆破魔术师',replace(replace('协调＋协调以外的魔法师族怪兽１只或以上\r\n可移除我方场上２个魔力计数物并发动。选择对手场上的１张魔法、陷阱卡并破坏。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33413638,'蟑螂骑士','此卡被送入墓地时，此卡回到牌组的最上面。','返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33420078,'僵尸带菌者','①：此卡存在于墓地的情况下，将１张手牌放回牌组最上面可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡离开场上的情况下，将其除外。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33423043,'异次元的指名者','宣言１个卡名可以发动。确认对手的手牌，其中有宣言的卡的情况下，将１张该卡片从游戏中除外。没有的情况下，随机挑选自己的１张手牌从游戏中除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33438265,'R.B.钢天切割机',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次，且②效果1回合仅可使用1次。\r\n①：自己场上的表侧表示怪兽，不存在的情况下或均为“R.B.”怪兽的情况下，此卡可从手牌特殊召唤。\r\n②：此卡和“R.B.”连接怪兽为连接状态的情况下，对手发动魔法・陷阱卡的效果时，支付700LP可以发动。将此卡破坏，将该发动的效果无效并破坏。','\r',char(13)),'\n',char(10)),'','无效并破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33438666,'吸血鬼绯红死神','①：自己场上的怪兽将被战斗或者对手的效果破坏的情况下，可以作为代替而支付该将被破坏的怪兽数量×1000LP。②：这张卡在通过战斗破坏怪兽的战斗阶段结束时可以发动。将该怪兽从墓地尽可能往自己场上进行特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33453260,'漫画手',replace(replace('可在自己场上存在“卡通世界”的情况下装备于对手场上的怪兽。\r\n①：获得装备怪兽的控制权。\r\n②：装备怪兽也视为卡通怪兽，对手场上不存在卡通怪兽的情况下，装备怪兽可直接攻击。\r\n③：场上不存在“卡通世界”的情况下，此卡将被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33455338,'邪狂神的使者','可在对手准备阶段时发动。挑选我方墓地任意数量的暗属性怪兽并从游戏中除外。直至回合结束时，此卡的守备力上升被除外怪兽数量×５００点。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33460840,'巨龙的守护者',replace(replace('①：此卡召唤・特殊召唤成功的场合可发动。从我方的手牌・墓地挑选１只等级７・８的龙族怪兽视作装备卡装备在此卡。\r\n②：此卡的攻击力・守备力上升因此卡的效果而装备的怪兽的攻击力・守备力的一半数值\r\n③：可解放此卡与我方场上的１只怪兽，并以我方墓地１只等级７・８的龙族怪兽为对象发动。特殊召唤该怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33467872,'深海的音乐导师',replace(replace('“深海的歌姬”＋协调以外的怪兽1只以上\r\n此卡名的②效果1回合仅可使用1次。\r\n①：在每个自己・对手回合中1次，从手牌将1只等级4以下的水属性怪兽舍弃可以发动。此卡的攻击力直至回合结束时为止上升800。\r\n②：同步召唤的此卡被送至墓地的情况下，以“深海的音乐导师”以外的、自己墓地的1只等级5以上的水属性怪兽为对象可以发动。将该怪兽以守备表示特殊召唤。此回合，自己仅可特殊召唤水属性怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33475154,'魔女工艺掌门・大魔女桑德里永',replace(replace('“魔女工艺掌门・玻璃匠薇儿”＋魔法师族怪兽×2\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡融合召唤的情况下可以发动。从手牌・牌组将最多3只等级7以下的“魔女工艺”怪兽特殊召唤（同属性最多1只）。此回合，自己从额外牌组仅可特殊召唤融合怪兽。\r\n②：此卡存在于墓地的情况下，在自己的结束阶段，向对手出示手牌的1张魔法卡可以发动。将此卡以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'从牌组特殊召唤','此卡特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33491462,'六花精雪花莲','此卡名的①②效果1回合仅可各使用1次。①：解放自己场上的1只植物族怪兽可以发动。从手牌将此卡和1只植物族怪兽特殊召唤。此效果发动后，直到回合结束时为止自己仅可特殊召唤植物族怪兽。②：可以自己场上的1只植物族怪兽为对象发动。自己场上的全部植物族怪兽的等级直到回合结束时为止变为和作为对象的怪兽的等级相同。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33499794,'妮梦雷莉娅・回笼',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：自己场上存在其他“妮梦雷莉娅”卡的情况下，依以下张数将“眠梦中的妮梦雷莉娅”以外的、额外牌组的卡以里侧除外，可以发动相应效果。\r\n●１张：从自己的墓地将１张“妮梦雷莉娅”卡加入手牌。\r\n●２张：此回合，自己受到的所有伤害变为一半。\r\n●３张：将自己场上的１只兽族・等级１０怪兽送至墓地，将对手场上所有表侧表示怪兽的效果直至回合结束时为止无效。','\r',char(13)),'\n',char(10)),'1张：从自己墓地把1张「妮梦雷莉娅」卡加入手牌','2张：这个回合，自己受到的全部伤害变成一半','3张：对手场上的全部表侧表示怪兽的效果无效','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33503878,'魔界剧本“戏剧性故事”','此卡名的卡１回合仅可发动１张。①：以自己场上的１只“魔界剧团”灵摆怪兽为对象可以发动。从牌组将１只卡名与该怪兽不同的“魔界剧团”怪兽特殊召唤。然后，将对象怪兽放在自己的灵摆区域或破坏。②：自己的额外牌组存在表侧表示的“魔界剧团”灵摆怪兽，被放置的此卡因对手的效果被破坏的情况下可以发动。挑选场上的最多２张卡，放回持有者的手牌。','','','在灵摆区域放置','破坏','','','','','','','','','','','','');
INSERT INTO texts VALUES(33506331,'清净立方',replace(replace('①：只要此卡存在于怪兽区域，自己不适用“清净世界”的效果。\r\n②：自己除通常召唤外仅可追加1次，在自己的主要阶段召唤1只记载有“清净世界”卡名的怪兽。\r\n③：表侧表示的此卡因对手从场上离开的情况下可以发动。从牌组将1只记载有“清净世界”卡名的怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33508719,'变形壶','①：此卡反转的情况下发动。双方将手牌全部舍弃。然后，双方从牌组各抽5张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33537328,'地缚神 Cusillu',replace(replace('①：“地缚神”怪兽在场上仅可有1只以表侧表示存在。\r\n②：此卡可直接攻击。\r\n③：对手怪兽不可将此卡选择为攻击对象。\r\n④：不存在表侧表示的场地魔法卡的情况下，此卡将被破坏。\r\n⑤：此卡将被战斗破坏的情况下，作为代替可解放自己场上的1只其他怪兽，并将对手的LP改成一半。','\r',char(13)),'\n',char(10)),'是否使用「地缚神 Cusillu」的效果代替破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33541430,'花札卫－月花见',replace(replace('协调＋２只协调以外的怪兽\r\n①：１回合１次，在自己的主要阶段可以发动。自己从牌组抽１张，双方确认。其为“花札卫”怪兽的情况下，可将该怪兽无视召唤条件特殊召唤。以此效果特殊召唤的怪兽在此回合可直接攻击。发动此效果的情况下，跳过下一个自己回合的抽牌阶段。\r\n②：以场上的此卡作为同步素材的情况下，可将包含此卡在内的所有同步素材怪兽视为等级２怪兽。','\r',char(13)),'\n',char(10)),'抽牌','是否特殊召唤？','是否把全部同步素材怪兽当作2星怪兽使用？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33543890,'辉龙机巧－天棓三贝塔','此卡不可通常召唤，仅可用“龙机巧”卡的效果特殊召唤。此卡名的效果1回合仅可使用1次。①：从自己的手牌・场上，解放此卡以外的1只“龙机巧”怪兽或仪式怪兽可以发动。将此卡从手牌・墓地以守备表示特殊召唤。然后，可挑选1只被除外的自己的“龙机巧”怪兽放回墓地。发动此效果的回合中，自己仅可特殊召唤不可通常召唤的怪兽。','','是否选除外的怪兽回到墓地？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33545259,'战华之孟－曹德',replace(replace('此卡名的①③效果1回合仅可各使用1次。\r\n①：对手场上的卡因战斗・效果被破坏的情况下，从自己手牌・场上将此卡以外的1张卡送至墓地可以发动。从手牌将此卡特殊召唤。\r\n②：只要自己场上存在其他“战华”怪兽，此卡不会因对手的效果被破坏，对手不可将此卡作为效果的对象。\r\n③：此卡战斗破坏对手怪兽并将其送至墓地时可以发动。将该怪兽以守备表示特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'此卡特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33550694,'结合之门','①：双方玩家可在自己的主要阶段发动。从自己的手牌・场上，将由融合怪兽卡决定的融合素材怪兽除外，从额外牌组将１只该融合怪兽融合召唤。','融合召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33551032,'黑影・无定形',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：以此卡的攻击使此卡因战斗被破坏并被送至墓地时可以发动。从牌组将2只“黑影”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33574806,'元素－英雄 幽冥',replace(replace('“元素-英雄”怪兽＋暗属性怪兽\r\n此卡仅可以融合召唤方式特殊召唤。①：此卡的攻击力上升相当于自己墓地的“元素-英雄”怪兽数量×100的数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33578406,'真刀竹光',replace(replace('①：装备怪兽的攻击力上升0。\r\n②：装备怪兽以直接攻击给予战斗伤害时可以发动。将对手场上的怪兽全部破坏。\r\n③：将被装备的此卡送至墓地可以发动。从牌组将“真刀竹光”以外的1张“竹光”装备魔法卡装备于场上的1只表侧表示怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33599853,'光与暗的仪式',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：为使合计等级达到仪式召唤的怪兽的等级以上，解放自己手牌・场上的怪兽，或作为解放的代替将自己墓地的怪兽除外，从手牌将“黑色混元之魔术师 黑暗混沌”或“光与暗的战士 混沌士兵”仪式召唤。\r\n②：此卡存在于墓地的情况下可以发动。从自己墓地将1张记载有“光与暗的仪式”卡名的卡和此卡加入手牌。','\r',char(13)),'\n',char(10)),'发动','回收效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33609093,'战华史略－十万之箭',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：以对手场上的1只表侧表示怪兽和自己场上的1只“战华”怪兽为对象可以发动。直至回合结束时为止，将该对手怪兽的攻击力改成一半，该自己的怪兽的攻击力上升其数值。\r\n②：此卡被送至墓地的情况下，如果自己场上的“战华”怪兽的属性为2种以上则可以发动。从手牌・牌组将“战华史略－十万之箭”以外的1张“战华”永续魔法・永续陷阱卡以表侧表示放在自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33609262,'帝王的深怨',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：向对手出示手牌的1只攻击力2400/守备力1000的怪兽或1只攻击力2800/守备力1000的怪兽可以发动。从牌组将“帝王的深怨”以外的1张“帝王”魔法・陷阱卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33611061,'武斗神集结','我方场上不存在除此卡以外的卡牌的场合可发动。将我方墓地所有冠有“武斗神”之名的兽战士族怪兽返回至牌组，并将我方的所有手牌送入墓地。之后，最多可从牌组将３只不同卡牌名的冠有“武斗神”之名的兽战士族怪兽加入手牌。“武斗神集结”１回合只可发动１张。','是否还要选择名字带有「武斗神」的兽战士族怪兽？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33621868,'铁球巨人','挥动上面布满长钉的铁球发动攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33622465,'救护部队',replace(replace('“救护部队”的②效果１回合只可使用１次。\r\n①：可以我方墓地的１只通常怪兽为对象发动。将该怪兽加入手牌。\r\n②：此卡存在于墓地，且通常怪兽因战斗被破坏时可发动。此卡变成通常怪兽（战士族、地、星３、攻１２００／守４００），以守备表示特殊召唤至怪兽区（不被视作陷阱卡）。以此效果特殊召唤的此卡，从场上离开的场合被除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33652635,'剑斗兽 多米提安诺斯',replace(replace('“剑斗兽 韦斯帕西亚斯”＋“剑斗兽”怪兽×２\r\n此卡从额外牌组仅可在将自己场上的上述卡放回牌组・额外牌组的情况下特殊召唤。\r\n①：１回合１次，对手发动怪兽的效果时可以发动。将该发动无效并破坏。\r\n②：只要此卡存在于怪兽区域，对手选择自身的怪兽的攻击对象之际，该攻击对象由自己选择。\r\n③：此卡进行过战斗的战斗阶段结束时，将此卡放回额外牌组可以发动。从牌组将１只“剑斗兽”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'发动无效并破坏','回到牌组并特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33655493,'暗之侯爵贝利亚尔','只要此卡以表侧表示存在于场上，对手不可选择我方场上除“暗之侯爵贝利亚尔”以外的表侧表示怪兽为攻击对象，也不可为魔法、陷阱卡的效果对象。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33656832,'曲艺的魔术师',replace(replace('←2 【灵摆】 2→\r\n“曲艺的魔术师”的灵摆效果１回合只可使用１次。\n①：我方场上的怪兽因效果被破坏时可发动。特殊召唤灵摆区的此卡。\r\n【怪兽效果】\r\n①：魔法、陷阱卡的发动变成无效的场合可发动。从手牌特殊召唤此卡。\n②：此卡因战斗被破坏时可发动。将此卡放置于我方的灵摆区。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33665663,'炎舞－开阳－',replace(replace('①：在发动了此卡的回合中，自己的兽战士族怪兽攻击了守备表示的怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。\r\n②：只要此卡存在于魔法与陷阱区域，自己场上的兽战士族怪兽的攻击力上升３００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33676146,'逃脱替罪山羊',replace(replace('①：对手发动以自己场上衍生物以外的怪兽为对象的效果时，解放自己场上的１只怪兽可以发动。将１只“逃羊衍生物”（兽族・地・星１・攻／守０）以守备表示特殊召唤至自己场上。\r\n②：自己场上衍生物以外的怪兽将被战斗・效果破坏的情况下，作为代替可破坏自己场上的１只衍生物。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33676147,'逃羊衍生物','由“逃脱替罪山羊”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33691040,'尖刺龙','“糙齿龙”＋“火焰毒蛇”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33695750,'死亡飞蚊','此卡召唤、特殊召唤成功时，在此卡放置２个计数物。此卡的攻击力上升此卡的计数物数量×５００点。此卡因战斗被破坏的场合，可移除此卡上的１个计数物作为代替。','放置计数物','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33698022,'月华龙 黑蔷薇',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的效果1回合仅可使用1次。\r\n①：此卡特殊召唤的情况下，或等级5以上的怪兽被特殊召唤至对手场上的情况下，以对手场上的1只被特殊召唤的怪兽为对象发动。将该对手怪兽放回手牌。','\r',char(13)),'\n',char(10)),'回到手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33725002,'V沙罗曼蛇',replace(replace('①：此卡召唤时，以自己墓地的1只“希望皇霍普”怪兽为对象可以发动。将该怪兽特殊召唤。\r\n②：以自己场上的1只“混沌编号39 希望皇霍普雷V”为对象可以发动。将自己场上的此卡视为装备魔法卡，装备于该自己的“混沌编号39 希望皇霍普雷V”。\r\n③：1回合1次，去除自己场上的装备怪兽的1个超量素材可以发动。将装备怪兽的效果无效，将对手场上的怪兽全部破坏，给予对手其数量×1000的伤害。','\r',char(13)),'\n',char(10)),'特殊召唤','装备','破坏并伤害','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33725271,'火山性充填','最多选择我方墓地３只冠有“火山性”之名的怪兽并返回至牌组。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33731070,'暗黑界之尖兵 米黄贝基','①：此卡因效果从手牌被舍弃至墓地的情况下发动。将此卡特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33734439,'二人三脚丧尸','关系亲密的胖瘦骸骨二人组。看上去走得很艰难。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33737664,'盗墓的报应','每次我方准备阶段，给予对手生命相当于从游戏中被除外的对方怪兽数×１００点的伤害。','LP伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33744268,'Z－无尽履带',replace(replace('①：此卡特殊召唤的情况下可以发动。将自己除外状态的１只机械族・光属性・等级４怪兽视为装备魔法卡装备于此卡。此回合，自己从额外牌组仅可特殊召唤光属性怪兽。\r\n②：１回合１次，可以发动以下的１个效果。\r\n●以自己场上的１只机械族怪兽为对象，将此卡视为装备魔法卡装备。装备怪兽将被战斗・效果破坏的情况下，作为代替将此卡破坏。\r\n●将装备状态的此卡特殊召唤。','\r',char(13)),'\n',char(10)),'装备效果','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33746252,'威光魔者',replace(replace('此卡不可特殊召唤。\r\n①：只要此卡存在于怪兽区域，双方不可发动怪兽的效果。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33750025,'轮回龙 僧娑罗','此卡名的②效果１回合仅可使用１次。①：上级召唤龙族怪兽的情况下，此卡可作为２只解放。②：将墓地的此卡除外，以自己墓地１只等级５以上的龙族怪兽为对象可以发动。将该怪兽加入手牌。然后可将该怪兽上级召唤。','是否上级召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33750856,'代码骇入',replace(replace('①：自己场上的电子界族连接怪兽不会因对手的效果被破坏。\r\n②：１回合１次，在自己和对手的怪兽之间进行战斗的战斗步骤可以发动。该对手怪兽的攻击力直至回合结束时为止变为０，双方怪兽不会因该战斗被破坏，因该战斗对双方造成的战斗伤害变为０。\r\n③：对手在自己的“码语者”怪兽攻击的伤害步骤发动效果时，将墓地的此卡除外可以发动。将该发动无效，该攻击怪兽的攻击力上升７００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33760966,'星宿爪龙 阿尔扎里昂',replace(replace('“星宿”怪兽＋手牌的怪兽1只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡融合召唤的情况下，以作为其融合素材的手牌的怪兽数量为上限，以自己・对手的、场上・墓地的怪兽为对象可以发动。将该怪兽放回手牌。\r\n②：此卡存在于墓地的状态下，有2只以上的怪兽同时被送至墓地的情况下可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'回到手牌','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33767325,'死亡流星','对手LP多余３０００点的情况下可以发动。给予对手LP１０００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33773528,'惊乐园・珍宝园',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己可将１张“游乐设施”陷阱卡在放置的回合的自己的主要阶段发动。\r\n②：在自己・对手的结束阶段，将１张装备于怪兽的自己场上的“游乐设施”陷阱卡送至墓地，从自己墓地的卡及自己被除外的卡中，以卡名和送至墓地的卡不同的１张“游乐设施”陷阱卡为对象可以发动。将该卡放置在自己的魔法与陷阱区域。','\r',char(13)),'\n',char(10)),'','适用「惊乐园・珍宝园」的效果来发动','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33776734,'羽翼库里波 LV9','可在连锁３之后发动。从手牌特殊召唤此卡。此卡的攻击力、守备力变成对手墓地的魔法卡数量×５００点。只要此卡以表侧表示存在于场上，发动了的魔法卡不被送入墓地而从游戏中被除外。我方场上只可存在有１张以表侧表示存在的“羽翼库里波 LV9”。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33776843,'混沌编号15 机关傀偶－连环杀手',replace(replace('等级９怪兽×３\r\n①：１回合１次，去除此卡的１个超量素材，以对手场上的１张卡为对象可以发动。将该卡破坏。以此效果破坏了怪兽的情况下，进而给予对手相当于该怪兽的原本攻击力数值的伤害。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33779875,'六花圣泪滴花束',replace(replace('等级８怪兽×２\r\n此卡名的①效果１回合仅可使用１次。\r\n①：去除此卡的１个超量素材，以自己・对手场上的１只怪兽为对象可以发动（此卡拥有植物族怪兽作为超量素材的情况下，此效果在对手回合中也可以发动）。解放该怪兽。\r\n②：每次怪兽被解放则发动。此卡的攻击力直至回合结束时为止，上升相当于被解放的怪兽数量×２００的数值。','\r',char(13)),'\n',char(10)),'怪兽解放','攻击力上升','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33781156,'铁兽式击灭兵装“Mouser”',replace(replace('兽族・兽战士族・鸟兽族怪兽2只\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡连接召唤的情况下可以发动。从牌组・额外牌组将“铁兽式击灭兵装“Mouser””以外的2张“铁兽”卡送至墓地（同名卡最多1张）。此回合，自己从额外牌组仅可特殊召唤兽族・兽战士族・鸟兽族怪兽。\r\n②：此卡被送至墓地的情况下，以场上的1只表侧表示怪兽为对象可以发动。将该怪兽改成里侧守备表示。','\r',char(13)),'\n',char(10)),'送至墓地','改变表示形式','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33782437,'暂时休战','①：双方各抽1张。直至下个对手回合结束时为止，双方受到的所有伤害变为0。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33784505,'盗壶贼','“强欲之壶”发动时可发动。使该效果无效，我方从牌组抽取１张卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33787730,'雷热涡炉・空洞电冲炮',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：以对手场上的表侧表示卡为对象可以发动，数量最多为自己场上的“雷热涡炉”超量怪兽数量。将该卡破坏。然后，可从自己墓地将１张“雷热涡炉”卡作为自己场上的１只阶级４超量怪兽的超量素材。\r\n②：将墓地的此卡除外可以发动。以包含“雷热涡炉”怪兽在内的、自己场上的怪兽作为素材进行超量召唤。','\r',char(13)),'\n',char(10)),'破坏效果','超量召唤','是否获取超量素材？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33814281,'专利权的契约书文件','此卡名的②效果１回合仅可使用１次。①：对手将种类（融合・同步・超量・连接）与自己场上的“DDD”怪兽相同的怪兽特殊召唤的情况下可以发动。给予对手１０００伤害。此回合，此卡存在于场上期间，对手不可将种类与该特殊召唤的怪兽相同的怪兽特殊召唤。②：此卡被送至墓地的情况下可以发动。从自己墓地的怪兽及自己额外牌组表侧表示的灵摆怪兽中，挑选１只“DD”怪兽加入手牌。','不可再特殊召唤融合怪兽','不可再特殊召唤同步怪兽','不可再特殊召唤超量怪兽','不可再特殊召唤连接怪兽','','','','','','','','','','','','');
INSERT INTO texts VALUES(33823832,'娱乐伙伴・火鬃狮',replace(replace('←5 【灵摆】 5→\r\n①：我方场上的灵摆怪兽因战斗被破坏时可发动。特殊召唤灵摆区的此卡。\r\n【怪兽效果】\r\n①：１回合１次，我方的灵摆怪兽因战斗破坏对手怪兽的伤害计算后可发动。直至战斗阶段结束时，该我方怪兽的攻击力上升２００，且可连续再进行１次攻击','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33833230,'娱乐伙伴 封条鳗',replace(replace('←3 【灵摆】 3→\r\n①：１回合１次，以对手场上的１只表侧表示怪兽为对象可以发动。将该怪兽的效果直至回合结束时为止无效。\r\n【怪兽效果】\r\n①：此卡召唤・特殊召唤成功时，以对手场上被放置的１张魔法・陷阱卡为对象可以发动。此回合该卡不可发动。应对此效果的发动，双方不可发动魔法・陷阱・怪兽的效果。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33837653,'天升星 天马',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：仅有对手场上有怪兽存在的情况下，或自己场上存在地属性怪兽的情况下，此卡无需解放即可召唤。\r\n②：此卡召唤・特殊召唤成功的情况下可以发动。从手牌将１只战士族・地属性・等级５怪兽特殊召唤。\r\n③：１回合１次，以自己场上的战士族怪兽为对象的对手效果发动时可以发动。此卡的攻击力下降５００，将该发动无效并破坏。','\r',char(13)),'\n',char(10)),'不用解放作召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33846209,'二重电光','①：解放自己场上的1只表侧表示的等级4二重怪兽，以场上的1张卡为对象可以发动。将该卡破坏，自己抽1张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33854624,'渊兽 玛格纳姆特',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：以自己或对手墓地的1只光・暗属性怪兽为对象可以发动（对手场上存在怪兽的情况下，此效果在对手回合中也可以发动）。将该怪兽除外，从手牌将此卡特殊召唤。\r\n②：此卡特殊召唤的情况下可以发动。在此回合的结束阶段，从自己牌组・墓地将“渊兽 玛格纳姆特”以外的1只龙族怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33866130,'大植然壁','此卡从场上被送入墓地时可发动。从牌组以攻击表示特殊召唤１只等级４或以下冠有“大植然”之名的怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33872334,'不死鸟・机亚锋烈刀',replace(replace('仅可装备于战士族怪兽或炎属性怪兽。\r\n此卡名的③效果１回合仅可使用１次。\r\n①：装备怪兽的攻击力上升３００。\r\n②：装备怪兽攻击的伤害步骤结束时，将此卡送至墓地可以发动。此战斗阶段中，自己的战士族怪兽及炎属性怪兽可各攻击２次。\r\n③：此卡为发动怪兽的效果，被送至墓地的情况下或被除外的情况下可以发动。将此卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33875961,'黑暗投射手','我方准备阶段时，此卡为守备表示的场合，放置１个计数物在此卡。可从游戏中除外相当于放置在此卡的计数物数量的我方墓地卡牌并发动。选择场上的魔法、陷阱卡破坏，其数量相当于被除外卡牌数量。之后，移除此卡的全部计数物。','放置计数物','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33878367,'泪冠哀歌・回荡的丧恸反响','此卡名的①②效果１回合１次，仅可使用其中１个。①：从自己的牌组・墓地挑选１只“泪冠哀歌”怪兽或“维萨思・史塔弗罗斯特”特殊召唤。然后，挑选自己场上１只种族或属性与以此效果特殊召唤的怪兽相同的怪兽送至墓地。②：此卡因效果被送至墓地的情况下，以自己１张被除外的“泪冠哀歌”陷阱卡为对象可以发动。将该卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33878931,'撞击兽','行动出乎意料地敏捷，且会卷成一团用身体撞击敌人。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33883834,'紫炎的寄子','我方场上冠有“六武众”之名怪兽进行战斗的伤害计算时，可将此卡从手牌送入墓地并发动。该怪兽不会因此回合战斗而被破坏。','不被战斗破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33897356,'射码语者',replace(replace('电子界族怪兽2只以上\r\n①：自己的战斗阶段开始时可以发动。此战斗阶段中，此卡可攻击对手怪兽的次数最多为此卡连接端的怪兽的数量＋1次。此回合，对手场上仅有1只怪兽的情况下，与该怪兽进行战斗的此卡的攻击力仅在该伤害计算时下降400。②：在自己・对手的战斗阶段结束时可以发动。自己从牌组抽此回合此卡战斗破坏的怪兽数量的卡。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33900648,'清净世界',replace(replace('此卡的控制者在每个自己的结束阶段，支付５００LP或将此卡破坏。\r\n①：双方根据自身场上的怪兽的属性各自适用以下效果。\r\n●光：持续公开所有手牌。\r\n●暗：自己场上的怪兽为２只以上的情况下，不可攻击宣言。\r\n●地：在自己的准备阶段，破坏自己的１只表侧守备表示的怪兽。\r\n●水：在自己的结束阶段，挑选１张手牌舍弃。\r\n●炎：在自己的结束阶段，受到１０００伤害。\r\n●风：必须支付５００LP才可以发动魔法卡。','\r',char(13)),'\n',char(10)),'是否要支付500基本分维持「清净世界」？','破坏','丢弃手牌','1000伤害','','','','','','','','','','','','');
INSERT INTO texts VALUES(33904024,'强欲之碎片','①：只要此卡存在于魔法与陷阱区域，每次在自己的抽牌阶段进行通常抽牌，就在此卡上放１个强欲计数物。②：将放有２个以上强欲计数物的此卡送至墓地可以发动。自己从牌组抽２张。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33907039,'皮瑞雷斯的地图','①：自己的主要阶段1开始时可以发动。从牌组将1只攻击力0的怪兽加入手牌，将自己的LP改成一半。此卡发动后，直至下个回合结束时为止，只要自己未成功召唤以此效果加入手牌的怪兽或其同名卡，则不可发动该怪兽及其同名卡的效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33909817,'森罗姬芽宫',replace(replace('等级1怪兽×2\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：去除此卡的1个超量素材可以发动。翻开自己牌组最上面的卡。翻开的卡是魔法・陷阱卡的情况下，将该卡加入手牌。不是的情况下，将该卡送至墓地。\r\n②：从自己手牌・场上（表侧表示）将此卡以外的1只植物族怪兽送至墓地，以自己墓地的1只“森罗”怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'翻开牌组','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33911264,'太阳风帆船','①：“太阳风帆船”在场上只可有1只以表侧表示存在。②：在自己场上不存在怪兽的情况下，此卡可从手牌中特殊召唤。通过此方法特殊召唤的此卡原本的攻击力与守备力变为一半。③：在自己的准备阶段发动。将此卡的等级上升1。','等级上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33918636,'超重武者 稻草人－C',replace(replace('“超重武者”怪兽１只\r\n此卡名的②效果１回合仅可使用１次。此卡不可作为连接素材。①：自己的墓地不存在魔法・陷阱卡的情况下，因此卡的战斗对自己造成的战斗伤害变为０。②：自己的墓地不存在魔法・陷阱卡的情况下，从手牌舍弃１只怪兽，以自己墓地的１只“超重武者”怪兽为对象可以发动。将该怪兽以守备表示特殊召唤至此卡连接端的自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33925864,'怒刹帝利・六世坏根清净','此卡名的①②效果１回合仅可各使用１次。①：场上存在“怒刹帝利”超量怪兽的情况下可以发动。双方必须将自身场上的怪兽以里侧表示除外，直至都只剩１只为止。②：此卡被除外的情况下，以自己场上的１只“怒刹帝利”超量怪兽为对象可以发动。将该怪兽作为超量素材持有的、自己１只“怒刹帝利”怪兽加入手牌。然后，可从手牌将该怪兽特殊召唤。','','','是否特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33945211,'海晶少女 角耳雪锉','此卡名的①③效果1回合仅可各使用1次。①：从自己的墓地将1张“海晶少女”陷阱卡除外可以发动。将1张卡名与该卡不同的“海晶少女”陷阱卡从牌组加入手牌。②：自己场上的怪兽将被效果破坏的情况下，可将墓地的此卡除外作为代替。③：此卡被除外的情况下，以自己场上的1只表侧表示怪兽为对象可以发动。该怪兽的攻击力上升600。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33950246,'王宫的号令','只要此卡存在于场上，所有反转怪兽的发动以及效果都被无效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33951077,'超级战狮','由“狮子的仪式”降临。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33955120,'黑蔷薇与荆棘之魔女',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的①③效果1回合仅可各使用1次。\r\n①：此卡同步召唤的情况下可以发动。从牌组・额外牌组各将最多1只植物族怪兽送至墓地。此效果发动后，直至回合结束时为止，自己从额外牌组仅可特殊召唤同步怪兽。\r\n②：自己场上的植物族怪兽不会因效果被破坏。\r\n③：此卡存在于墓地的状态下，场上的卡因效果被破坏的情况下可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'送至墓地','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33964637,'影六武众－里半',replace(replace('属性不同的“六武众”怪兽×3\r\n此卡从额外牌组仅可在将自己场上的上述卡送至墓地的情况下特殊召唤。\r\n此卡不可作为融合素材。\r\n①：1回合1次，从自己手牌・场上（表侧表示）将1张“六武众”卡除外，以场上的1张卡为对象可以发动。将该卡除外。\r\n②：自己场上的“六武众”怪兽将被战斗・效果破坏的情况下，作为代替可将墓地的此卡除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33970665,'废钢铁的意志','①：以自己墓地３只“废铁”怪兽为对象可以发动。对手从其中挑选１只。将对手所挑选的怪兽特殊召唤至自己或对手场上，将剩余的怪兽除外。','在自己场上特殊召唤','在对手场上特殊召唤','请选择3只名字带有「废铁」的怪兽','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33971095,'仇尸・梦魇','此卡名的②效果１回合仅可使用１次。①：１回合１次，从自己的手牌・场上解放任意数量的“仇尸”怪兽，以自己场上的１只表侧表示怪兽为对象可以发动。该怪兽的等级直至回合结束时为止，上升相当于所解放怪兽数量的数值。②：以自己的“仇尸”仪式怪兽的攻击破坏对手怪兽时可以发动。该自己怪兽的攻击力上升１０００。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33972299,'地能次代机',replace(replace('“次代机・控制者”＋协调以外的地属性怪兽１只以上\r\n①：１回合１次，自己场上存在等级４以下的“次代机”怪兽的情况下可以发动。直至回合结束时为止，交换此卡原本的攻击力与原本的守备力。此效果适用至自己场上不再存在等级４以下的“次代机”怪兽为止。','\r',char(13)),'\n',char(10)),'攻守交换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33977496,'千根针','攻击了守备表示的此卡的对手怪兽的攻击力低于此卡守备力的场合，在伤害步骤结束时破坏该攻击怪兽。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33981008,'魔导书院拉迈松',replace(replace('①：如果我方场上或我方墓地中有魔法师族怪兽，可于我方准备阶段发动。从我方墓地选择１张“魔导书院拉迈松”以外的“魔导书”魔法卡，将其送回卡组底端，然后抽一张卡。\r\n②：这张卡被对手破坏并送进墓地时可以发动。从手牌或卡组中特殊召唤１只等级为我方墓地中“魔导书”魔法卡数量以下的魔法师族怪兽。','\r',char(13)),'\n',char(10)),'返回牌组并抽牌','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(33995387,'英雄法则1 五大自由',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：以自己・对手墓地合计最多5张卡为对象可以发动。将该卡除外。\r\n②：从墓地将不是在此回合被送至墓地的此卡除外，以自己除外状态的1只“元素－英雄”怪兽为对象可以发动。将该怪兽无视召唤条件特殊召唤。','\r',char(13)),'\n',char(10)),'除外','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34001672,'格布林百罗刹 巨魁加蓬迦',replace(replace('等级３怪兽×２\r\n此卡名的①②③效果１回合仅可各使用１次。\r\n①：此卡超量召唤的情况下可以发动。从牌组将１只“格布林”怪兽加入手牌。\r\n②：场上的超量素材被去除的情况下，以场上１只其他的表侧表示怪兽为对象可以发动。将该怪兽作为此卡的超量素材。\r\n③：在自己・对手的结束阶段可以发动。从牌组将１只“格布林”怪兽作为此卡的超量素材。','\r',char(13)),'\n',char(10)),'牌组检索','场上怪兽作为超量素材','牌组怪兽作为超量素材','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34002992,'彩虹生命','可舍弃１张手牌并发动。此回合，代替因战斗及卡牌效果受到伤害，我方回复相当于该数值的LP。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34004470,'The big SATURN','此卡不可进行从手牌、牌组的特殊召唤。１回合１次，可舍弃１张手牌并支付１０００LP点数发动。直至回合结束时，此卡的攻击力上升１０００点。此卡因对手卡的效果被破坏并送至墓地时，双方均受到此卡原本攻击力一半数值的伤害。','攻击上升','伤害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34010534,'电脑网优选法','此卡名的①效果1回合仅可使用1次。①：在自己的主要阶段可以发动。召唤1只电子界族怪兽。此效果发动后，直至回合结束时为止自己从额外牌组仅可特殊召唤电子界族怪兽。②：自己的“码语者”怪兽进行战斗的情况下，对手直至伤害步骤结束时为止不可发动魔法・陷阱・怪兽的效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34016756,'力量','可选择以表侧表示存在于场上的２只怪兽发动此卡。直到结束阶段时，令所选择的其中１只怪兽攻击力减半，而另１只怪兽的攻击力则上升其减少的数值。','请选择攻击力变成一半的怪兽','请选择攻击力上升的怪兽','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34022290,'守护者・艾尔托斯',replace(replace('①：自己墓地不存在怪兽的情况下，此卡可从手牌特殊召唤。\r\n②：将装备于此卡的、自己场上的1张装备魔法卡送至墓地，以对手墓地的最多3只怪兽为对象可以发动。将该怪兽除外。此卡的攻击力直至回合结束时为止，上升相当于以此效果除外的怪兽数量×500的数值。','\r',char(13)),'\n',char(10)),'除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34022970,'超燃・雷热涡炉',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次，且②效果1回合仅可使用1次。\r\n①：此卡可通过将额外牌组的1只超量怪兽送至墓地，来从手牌特殊召唤。以此方法特殊召唤过的余下本回合，自己从额外牌组仅可特殊召唤阶级4的超量怪兽。\r\n②：此卡召唤・特殊召唤的情况下，如果自己场上不存在等级4・阶级4怪兽以外的表侧表示怪兽则可以发动。从牌组将1只雷族・炎属性怪兽加入手牌。','\r',char(13)),'\n',char(10)),'手牌特殊召唤','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34026662,'进化的奇迹','可选择１只因冠有“进化虫”之名怪兽的效果而被特殊召唤的怪兽并发动。此回合，被选择怪兽不会因战斗或卡牌效果被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34029630,'漆黑的魔力石','发动后，在此卡上放置３个魔力计数物。可在我方回合取除１次此卡上的１个魔力计数物，并在场上表侧表示的除此卡以外的１张可放置魔力计数物的卡牌上放置１个魔力计数物。在此卡失去所有魔力计数物时，破坏此卡。','是否现在使用「漆黑的魔力石」的效果？','计数物转移','请选择要放置魔力计数物的卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34031284,'扰乱怪・皇帝',replace(replace('包含“扰乱怪”怪兽在内的兽族怪兽３只\r\n此卡名的③效果１回合仅可使用１次。\r\n①：场地区域有“扰乱怪之乡”存在的情况下，此卡的攻击力上升３０００，不会因效果被破坏。\r\n②：对此卡的攻击造成的对自己的战斗伤害由对手代为承受。\r\n③：以连接怪兽以外的自己墓地的１只“扰乱怪”怪兽为对象可以发动。将该怪兽特殊召唤。此效果发动过的余下回合，自己从额外牌组仅可特殊召唤融合怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34034150,'分裂的母蜘蛛',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：自己场上不存在怪兽的情况下，此卡可从手牌中特殊召唤。\r\n②：解放此卡可以发动。从手牌・牌组将最多３只“宝宝蜘蛛”特殊召唤。以此效果特殊召唤的怪兽的等级变为５，要作为超量召唤的素材的情况下，仅可使用于暗属性怪兽的超量召唤。此效果发动后，直至回合结束时为止自己从额外牌组仅可特殊召唤超量怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34041788,'恩底弥翁皇国',replace(replace('此卡名的卡1回合仅可发动1张，此卡名的②效果1回合仅可使用1次。\r\n①：作为此卡发动时的效果处理，从牌组将1只“恩底弥翁之圣月皇太子 雷格鲁斯”或记载有该卡名的怪兽加入手牌。对手场上存在怪兽的情况下，进而可从手牌将1只魔法师族怪兽特殊召唤。\r\n②：自己场上的卡将被战斗・效果破坏的情况下，作为代替可将自己手牌・场上（表侧表示）的1只“恩底弥翁之圣月皇太子 雷格鲁斯”破坏。','\r',char(13)),'\n',char(10)),'是否特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34047456,'超巨霸・雷霆交叉击','此卡名的卡１回合仅可发动１张。①：以双方场上・墓地的怪兽为对象可以发动，数量为双方被除外的卡张数之差。将该怪兽除外。然后，对手可从自身牌组将１只怪兽特殊召唤。','','是否从牌组特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34072799,'跨音速鸟','以“追逐音速者”降临。①：１回合１次，可以发动。向对手出示手牌的１张仪式魔法卡，将１只卡名记载于该卡的仪式怪兽从牌组加入手牌，将所出示的卡放回牌组。②：每个对手回合中１次，从牌组将１张仪式魔法卡送至墓地可以发动。此效果变为与该仪式魔法卡发动时的仪式召唤的效果相同。③：仪式召唤的此卡被解放的情况下，以对手场上的１张表侧表示的卡为对象可以发动。将该卡的效果直至回合结束时为止无效。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34079868,'真龙剑士 统领星杰',replace(replace('此卡不可通常召唤。\r\n仅可在解放自己场上的“龙剑士”怪兽和“龙魔王”怪兽各１只的情况下特殊召唤。\r\n①：１回合１次，魔法・陷阱・怪兽的效果发动时可以发动。将该发动无效并破坏。\r\n②：场上的此卡被对手破坏的情况下可以发动。从牌组将“龙剑士”怪兽和“龙魔王”怪兽各１只特殊召唤。','\r',char(13)),'\n',char(10)),'效果发动无效','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34086406,'岩浆炎谷・连锁',replace(replace('等级４怪兽×２\r\n①：１回合１次，可移除此卡的１个×素材，并从以下效果选择１个发动。\r\n●从牌组挑选１张卡牌送入墓地。\r\n●从牌组挑选１只怪兽并放置于牌组的最上方。','\r',char(13)),'\n',char(10)),'选择一个效果发动','从自己牌组选择1张卡送至墓地。','从自己牌组选择1只怪兽在牌组最上面放置。','请选择放置到牌组最上方的怪兽','','','','','','','','','','','','');
INSERT INTO texts VALUES(34088136,'终极昆虫 LV3','只要以“终极昆虫 LV1”的效果特殊召唤的此存在于场上，对手场上所有怪兽的攻击力下降３００点。在我方准备阶段时，可将场上的此卡送入墓地并发动。从手牌、牌组特殊召唤１只“终极昆虫 LV5。此效果不可在此卡进行过召唤、特殊召唤、反转的回合发动。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34090915,'复烙印',replace(replace('此卡名的①效果1回合仅可使用1次，②效果在同一连锁上仅可发动1次。\r\n①：光・暗属性怪兽以表侧被除外的情况下，以其中1只为对象可以发动。将该怪兽放回牌组最下面，自己抽1张。\r\n②：1回合1次，对手将怪兽召唤・特殊召唤的情况下，以自己墓地的1只“渊兽”怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'回收除外的怪兽并抽牌','特殊召唤墓地的怪兽','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34093683,'复仇尸者・制裁者','以“仇尸”仪式魔法卡降临。此卡名的③效果１回合仅可使用１次。①：只要此卡存在于怪兽区域，卡名视为“复仇尸者・屠戮者”。②：只要仪式召唤的此卡存在于怪兽区域，对手不可将自己场上的其他卡作为效果的对象。③：仪式召唤的此卡因战斗或对手的效果被破坏的情况下可以发动。从牌组将１张“仇尸”卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34100324,'神鹰女孩','梦想有一天能以美丽的姿态华丽飞舞、敏锐攻击的鹰身少女。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34103656,'忘却之都 雷缪利亚',replace(replace('此卡名在规则上视为“海”。\r\n①：场上的水属性怪兽的攻击力・守备力上升200。\r\n②：1回合1次，在自己的主要阶段可以发动。只要此卡存在于场地区域，依自己场上的水属性怪兽的数量，自己场上的水属性怪兽的等级直至回合结束时为止上升相同数值。','\r',char(13)),'\n',char(10)),'等级上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34109611,'大薰风法尔科斯',replace(replace('协调＋协调以外冠有“大薰风”之名的怪兽１只或以上\r\n此卡同步召唤成功时，所有场上冠有“大薰风”之名怪兽的攻击力上升６００点。','\r',char(13)),'\n',char(10)),'攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34116027,'龙骑兵团骑士－破魔赤枪',replace(replace('龙族协调＋协调以外的鸟兽族怪兽1只以上\r\n①：1回合1次，在自己主要阶段可以发动。从牌组将1只等级4以下的龙族・鸟兽族怪兽加入手牌。然后，从手牌挑选1只龙族・鸟兽族怪兽舍弃。','\r',char(13)),'\n',char(10)),'检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34124316,'电子壶','①：此卡反转的情况下发动。将场上的怪兽全部破坏。然后，双方从牌组上面翻开5张卡，将其中可特殊召唤的等级4以下的怪兽以表侧攻击表示或里侧守备表示全部特殊召唤。将剩余的翻开的卡全部加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34130561,'魔道骑士盖亚','此卡名在规则上也视为“暗黑骑士盖亚”卡。此卡名的②效果１回合仅可使用１次。①：自己场上不存在怪兽的情况下，或对手场上有攻击力２３００以上的怪兽存在的情况下，此卡无需解放即可召唤。②：此卡召唤・特殊召唤成功的情况下可以发动。从自己的手牌・墓地挑选１只龙族・等级５怪兽以守备表示特殊召唤。','不用解放作召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34137269,'时械神 海隆',replace(replace('此卡不可从牌组特殊召唤。\r\n①：自己场上不存在怪兽的情况下，此卡无需解放即可召唤。\r\n②：此卡不会因战斗・效果被破坏，因此卡的战斗对自己造成的战斗伤害变为０。\r\n③：此卡进行战斗的战斗阶段结束时发动。自己的LP少于对手的情况下，依其数值之差来给予对手伤害。\r\n④：在自己的准备阶段发动。将此卡放回持有者的牌组。','\r',char(13)),'\n',char(10)),'不用解放作召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34143852,'英豪挑战者 额外之剑',replace(replace('①：以场上的此卡作为素材超量召唤的怪兽获得以下效果。\r\n●此卡超量召唤的情况下发动。此卡的攻击力上升１０００。','\r',char(13)),'\n',char(10)),'攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34149150,'葬角之食肉牛龙',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己・对手的主要阶段及战斗阶段可以发动。将包含此卡在内的自己场上的怪兽作为素材，将1只恐龙族同步怪兽同步召唤。\r\n②：自己或对手的怪兽的攻击宣言时可以发动。从手牌将1只恐龙族怪兽无视召唤条件特殊召唤。此效果发动后，直至回合结束时为止自己仅可特殊召唤恐龙族怪兽。','\r',char(13)),'\n',char(10)),'同步召唤','从手牌特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34149830,'死力的组队换手','我方场上的攻击表示怪兽因战斗被破坏的伤害计算时，因该战斗对我方造成的战斗伤害变成０，且在该伤害步骤结束时，可从手牌特殊召唤１只等级４或以下的战士族怪兽。','战斗伤害变成0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34160055,'龙炎剑的剑手','除“龙炎剑的剑手”以外的怪兽被召唤至我方场上时可发动。该怪兽的等级提升１，直至回合结束时，此卡的攻击力上升３００点。','等级攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34172284,'溟界王－阿泷','此卡名的①②③效果1回合仅可各使用1次。①：此卡存在于墓地的情况下，解放自己场上的2只怪兽可以发动。将此卡特殊召唤。②：对手在抽牌阶段以外将卡加入手牌的情况下可以发动。随机挑选1张对手的手牌送至墓地。③：对手场上的怪兽因效果被送至墓地的情况下可以发动。从自己的牌组・墓地挑选1只“溟界王-阿泷”以外的光・暗属性爬虫类族怪兽加入手牌。','','对手手牌随机选1张送至墓地','从自己的牌组·墓地选爬虫类族怪兽加入手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34187685,'双重攻击','将我方手牌中的１张怪兽卡弃置至墓地。选择我方场上１只等级比弃置怪兽低的怪兽。所选择怪兽在该回合中可进行２次攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34193084,'来自黑暗的恐惧','此卡因对手效果被从手牌、牌组送入墓地时，从墓地特殊召唤此卡。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34198387,'触点抖动啁啾猫',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：场地魔法卡发动的情况下可以发动。从手牌将此卡特殊召唤。双方的场地区域有表侧表示卡存在的情况下，进而此卡此回合不会因战斗・效果被破坏。\r\n②：只要此卡存在于怪兽区域，在自己回合期间，对手的场地区域表侧表示的卡的效果无效化，在对手回合期间，自己场地区域表侧表示的卡的效果无效化。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34206604,'魔导科学家','支付１０００LP可以发动。从额外牌组特殊召唤１只等级６以下的融合怪兽。以此效果特殊召唤的怪兽不可直接攻击，在结束阶段时放回持有者的额外牌组。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34225426,'嫋嫋泪冠哀歌姬的壹世坏','此卡名的②效果１回合仅可使用１次。①：自己场上的融合怪兽及“泪冠哀歌”怪兽的攻击力上升５００。②：水族的“泪冠哀歌”怪兽因效果被送至自己墓地的情况下可以发动。从牌组将１只等级４以下的水族怪兽送至墓地。以此效果将“泪冠哀歌”怪兽以外的怪兽送至墓地的情况下，此回合，自己不可发动以此效果送至墓地的卡及该卡的同名卡的效果。','从牌组把1只4星以下的水族怪兽送至墓地','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34230233,'暗黑界之龙神 漆黑古拉法',replace(replace('①：此卡可通过将“暗黑界之龙神 漆黑古拉法”以外的、自己场上的1只“暗黑界”怪兽放回手牌来从墓地特殊召唤。\r\n②：此卡因效果从手牌被舍弃至墓地的情况下，以对手场上的1张卡为对象发动。将该对手的卡破坏。因对手的效果被舍弃的情况下，进而随机确认对手的1张手牌。其为怪兽的情况下，可将该怪兽特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'对手场上存在的1张卡破坏','是否要特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34235530,'真魔六武众－紫焰',replace(replace('战士族协调＋协调以外的“六武众”怪兽１只以上\r\n此卡名的①效果１回合仅可使用１次。\r\n①：此卡同步召唤的情况下可以发动。从自己牌组・墓地将１只“六武众”怪兽或“紫炎”效果怪兽加入手牌。\r\n②：１回合１次，对手发动怪兽的效果时可以发动。将该发动无效并破坏。\r\n③：场上的此卡将被战斗・效果破坏的情况下，作为代替可将自己场上的１只怪兽破坏。','\r',char(13)),'\n',char(10)),'检索效果','发动无效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34236961,'赌注胜负','双方玩家从各自的手牌挑选１张卡牌，确认彼此的等级。将挑选了等级较高怪兽玩家的卡牌返回至手牌，挑选了等级低怪兽的玩家受到１０００点伤害，该卡牌送入墓地。挑选了怪兽以外卡牌的场合，等级变为０。相同等级的场合将卡牌返回至各自手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34242278,'圣骑士的持盾者','此卡名的①②效果1回合1次，仅可使用其中1个。①：此卡召唤・特殊召唤成功的情况下，从自己的墓地将1只光属性怪兽除外可以发动。自己从牌组抽1张。②：将手牌・场上的此卡除外可以发动。从牌组将1只等级6以下的兽族・风属性怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34244455,'星向鸟',replace(replace('①：此卡只要存在于主要怪兽区域，根据其位置获得以下效果。\r\n●左端：此卡的等级上升４。\r\n●右端：此卡的等级上升３。\r\n●中央：此卡的等级上升２。\r\n●除此以外：此卡的等级上升１。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34250214,'吸血鬼的使役魔','这个卡名的①②的效果1个回合各只可使用1次。①：这张卡特殊召唤成功的情况下，支付500LP可以发动。从牌组把“吸血鬼的使役魔”以外的1只“吸血鬼”怪兽加入手牌。②：这张卡存在于墓地的情况下，从手牌以及自己场上的表侧表示的卡之中将1张“吸血鬼”卡送至墓地后可以发动。特殊召唤这张卡。用这个效果特殊召唤的这张卡在从场上离开的情况下将被除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34251483,'格布林冲锋部队','在此卡的攻击宣言时，对手不可发动魔法、陷阱、怪兽的效果。此卡发动攻击的场合，于战斗阶段结束时变为守备表示，直至下一个次我方回合结束时，此卡不可变更表示形式。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34257001,'冲刺战士','此卡攻击的场合，在伤害步骤期间，此卡的攻击力上升１２００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34267821,'古遗物－朗基努斯',replace(replace('①：此卡可视为魔法卡从手牌放置在魔法与陷阱区域。\r\n②：被放置在魔法与陷阱区域的此卡在对手回合中被破坏并被送至墓地的情况下发动。将此卡特殊召唤。\r\n③：在对手回合中，解放手牌・场上的此卡可以发动。此回合，双方不可将卡除外。','\r',char(13)),'\n',char(10)),'特殊召唤','双方不可把卡除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34290067,'死亡鲨鱼','徘徊在海中的不死鲨鱼。与其相遇者均会遭到死亡诅咒。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34293667,'冰结界',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：对手怪兽进行战斗的攻击宣言时可以发动。该对手怪兽的攻击力变为０，表示形式不可变更，且效果无效化。\r\n②：将墓地的此卡除外可以发动。从牌组将１只等级５以上的水属性怪兽送至墓地。然后，可从自己的墓地将１只水属性怪兽加入手牌。此效果发动后，直至下个自己回合结束时为止，自己仅可特殊召唤水属性怪兽。','\r',char(13)),'\n',char(10)),'','是否从墓地选1只水属性怪兽加入手牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34294855,'诅咒吸血鬼','此卡因战斗破坏并被送入墓地时，可支付５００LP发动。下一回合准备阶段时，从墓地特殊召唤此卡。此外，因此效果特殊召唤成功时发动。此卡的攻击力上升５００点。','特殊召唤','攻击上升','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34298391,'心灵透视眼',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：只要自己场上或墓地存在“卡通”卡，对手持续公开所有手牌，自己可随时确认对手场上的里侧表示卡。\r\n②：自己场上・墓地存在卡通怪兽及“卡通”魔法卡的情况下，宣言1个未在同一连锁上发动效果的卡名可以发动。在此卡以表侧表示存在的期间内，直至回合结束时为止，所宣言的卡及原本卡名相同的卡所发动的效果无效化。','\r',char(13)),'\n',char(10)),'','宣言','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34302287,'幻煌龙之战涡',replace(replace('场上有“海”存在的情况下，此卡也可从手牌发动。\r\n①：自己场上的怪兽仅有通常怪兽的情况下，以对手场上的１张卡为对象可以发动。将该卡破坏。\r\n②：将墓地的此卡除外，以自己场上的１只通常怪兽为对象可以发动。将自己场上该怪兽可装备的所有“幻煌龙”装备魔法卡装备于该通常怪兽。','\r',char(13)),'\n',char(10)),'','适用「幻煌龙之战涡」的效果来发动','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34314989,'暗眼幻象师 无面',replace(replace('①：从手牌将此卡舍弃，可从以下效果中选择1个发动（此卡名的以下效果1回合仅可各选择1次）。\r\n●从手牌・牌组将1张“心灵透视眼”以表侧表示放在自己场上。\r\n●从自己墓地将除此卡以外的、1只记载有“卡通世界”卡名的怪兽加入手牌。然后，可从手牌将该怪兽无视召唤条件特殊召唤。\r\n②：此卡与怪兽进行战斗的情况下，该2只不会因该战斗被破坏。','\r',char(13)),'\n',char(10)),'丢弃','放置陷阱卡','回收怪兽','是否特殊召唤？','','','','','','','','','','','','');
INSERT INTO texts VALUES(34318086,'柠檬魔导女孩',replace(replace('①：１回合１次，可解放我方场上１只除“柠檬魔导女孩”以外的“魔导女孩”怪兽并发动。从牌组将１只魔法师族怪兽加入手牌。\r\n②：１回合１次，此卡被选择为攻击对象的场合可发动。从手牌使１只魔法师族怪兽的效果无效并特殊召唤。之后，攻击对象转移至该怪兽，且攻击怪兽的攻击力减半。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34320307,'有生命的花瓶','利用插花散布花粉并紧紧咬住对方的活花瓶。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34323367,'娱乐巫师・水舞者',replace(replace('←2 【灵摆】 2→\r\n此卡名的①②灵摆效果1回合仅可各使用1次。\n①：自己场上存在“娱乐巫师”怪兽的情况下可以发动。将此卡特殊召唤。\n②：自己或对手的怪兽的攻击宣言时，以场上1只攻击表示的怪兽为对象可以发动。将该怪兽改成守备表示。\r\n【怪兽效果】\r\n此卡名的①怪兽效果1回合仅可使用1次。\n①：此卡灵摆召唤的情况下可以发动。从自己牌组・墓地将1张“融合”加入手牌。\n②：场上的此卡因战斗・效果被破坏的情况下，以场上1只攻击表示的怪兽为对象可以发动。将该怪兽改成守备表示。','\r',char(13)),'\n',char(10)),'特殊召唤','变更表现形式','检索「融合」','变更表现形式','','','','','','','','','','','','');
INSERT INTO texts VALUES(34325937,'方界合神',replace(replace('①：从自己的手牌・场上，将由“方界”融合怪兽卡决定的融合素材怪兽送至墓地，将该１只融合怪兽从额外牌组融合召唤。\r\n②：表侧表示的“方界”怪兽因战斗被破坏的情况下，或离开场上的情况下，将墓地的此卡除外可以发动。从手牌・牌组将１只等级４以下的“方界”怪兽无视召唤条件特殊召唤。以此效果被特殊召唤的怪兽此回合不会因战斗・效果被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34334692,'仪式的供品','①：要仪式召唤1只暗属性仪式怪兽的情况下，使用1张此卡即可作为仪式召唤所必需的解放。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34351849,'蛙类防护罩','自己场上的名字带有“青蛙”的怪兽被选择作为攻击对象时可以发动。将对手场上的所有攻击表示怪兽破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34358408,'仪式魔人主持者','进行仪式召唤的场合，作为该仪式召唤所需要等级数值的１只怪兽，可将墓地的此卡从游戏中除外。此外，使用了此卡进行仪式召唤的仪式怪兽因战斗破坏怪兽时，该仪式怪兽的控制者从牌组抽取１张卡牌。','「仪式魔人主持者」效果适用中','抽牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34365442,'邪恶★双子 低难度游戏',replace(replace('此卡名的①效果1回合仅可使用1次。①：解放自己场上的1只“姬丝吉尔”怪兽或“璃拉”怪兽，可从以下效果中选择1个发动。\r\n●以自己场上的1只“姬丝吉尔”怪兽或“璃拉”怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止，上升相当于解放的怪兽原本攻击力的数值。\r\n●破坏场上卡的魔法・陷阱・怪兽的效果发动时可以发动。将该效果无效。','\r',char(13)),'\n',char(10)),'发动但不使用效果','攻击力上升','无效破坏效果','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34370473,'狮鹫羽毛扫','破坏自己场上所有魔法・陷阱卡。自己恢复相当于所破坏卡数量×５００的LP。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34379489,'娱乐伙伴泡沫犬',replace(replace('←5 【灵摆】 5→\r\n①：我方场上除灵摆怪兽以外从额外牌组特殊召唤而来的表侧表示怪兽因战斗、效果被破坏的场合，可破坏此卡作为代替。\r\n【怪兽效果】\r\n①：此卡从额外牌组特殊召唤成功时可发动。此回合，从额外牌组特殊召唤而来的我方场上之灵摆怪兽不会因效果被破坏。','\r',char(13)),'\n',char(10)),'是否使用「娱乐伙伴泡沫犬」的效果代替破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34408491,'魔王龙 别西',replace(replace('暗属性协调＋协调以外的怪兽1只以上\r\n①：场上的此卡不会因战斗・效果被破坏。\r\n②：每当自己因此卡的战斗或对手的效果受到伤害则发动。此卡的攻击力上升所受伤害的数值。','\r',char(13)),'\n',char(10)),'攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34419588,'库里拜',replace(replace('此卡名在规则上也视为“库里波”卡。\r\n①：从手牌将此卡舍弃，以自己场上的１只“库里波”怪兽为对象可以发动。该怪兽的攻击力上升１５００。此效果在对手回合中也可以发动。\r\n②：解放场上的此卡和自己手牌・场上的“库里巴”、“库里比”、“库里布”、“库里波”各１只可以发动。从自己的牌组・墓地挑选１只“库里盗贼”加入手牌。然后，可从手牌召唤１只恶魔族怪兽。','\r',char(13)),'\n',char(10)),'','','是否把恶魔族怪兽召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34433770,'闪刀亚式－双纽无限门',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：以自己墓地相同数量的“闪刀姬”怪兽和“闪刀”魔法卡为对象可以发动。将该卡放回牌组。然后，放回的卡每有3张，就可将场上的最多1张卡放回手牌。\r\n②：此卡存在于墓地的状态下，“闪刀”怪兽被特殊召唤至自己场上的情况下，将此卡除外可以发动。进行1只“闪刀姬”连接怪兽的连接召唤。','\r',char(13)),'\n',char(10)),'','是否选卡返回手牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34442949,'机械蜗牛','被改造成机械的蜗牛。但是速度却依然没什么改变。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34446231,'狱炎机・洪潦',replace(replace('包含“狱炎机”怪兽在内的怪兽２只以上\r\n此卡名的①②③效果１回合仅可各使用１次。\r\n①：对手将怪兽特殊召唤之际，解放自己场上的１只怪兽可以发动。将该特殊召唤无效，将该怪兽除外。\r\n②：卡从自己的墓地被除外的情况下可以发动。将场上的１张卡除外。\r\n③：连接召唤的此卡被对手破坏的情况下可以发动。从牌组将１只“狱炎机”怪兽无视召唤条件特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤无效','卡片除外','从牌组特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34447918,'怒刹帝利・六世坏他化自在天','此卡名的①②效果１回合仅可各使用１次。①：以自己场上的１只“怒刹帝利”怪兽为对象可以发动。从牌组将１只属性与该怪兽不同的“怒刹帝利”怪兽以守备表示特殊召唤。此卡发动后，直至回合结束时为止自己从额外牌组仅可特殊召唤超量怪兽。②：此卡被除外的情况下，以“怒刹帝利・六世坏他化自在天”以外的、自己１张被除外的“怒刹帝利”卡为对象可以发动。将该卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34449261,'融合死圆舞曲','①：以自己场上的１只“魔玩具”融合怪兽与对手场上的１只融合怪兽为对象可以发动。将场上除对象怪兽以外特殊召唤出的所有怪兽破坏。然后，由于此效果怪兽被破坏的玩家受到对象怪兽攻击力的合计数值的伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34456146,'慈爱之贤者－谢拉',replace(replace('此卡名在规则上也视为“闪刀”卡。\r\n此卡名的①②③效果１回合仅可各使用１次。\r\n①：从手牌将１张魔法卡舍弃可以发动。从手牌将此卡特殊召唤。\r\n②：从自己的墓地将１张魔法卡除外可以发动。此卡的控制权转移给对手，从自己的墓地将１只“闪刀姬”怪兽特殊召唤。\r\n③：此卡因战斗・效果被破坏并被送至墓地的情况下，以自己除外状态的１张“闪刀”魔法卡为对象可以发动。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34460239,'世代交替','选择我方场上１只以表侧表示的怪兽破坏。之后，将１张与从牌组破坏的卡牌同名的卡牌加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34460851,'炎之操纵者','任意制造出炎之海或炎之壁来发动攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34471458,'命运女郎・莱蒂',replace(replace('①：此卡的攻击力、守备力变成此卡的等级×２００。\r\n②：在我方准备阶段发动。此卡的等级上升１级（最高至１２级）。\r\n③：表侧表示的此卡因效果从场上离开时可发动。从牌组特殊召唤１只“命运女郎”怪兽。','\r',char(13)),'\n',char(10)),'等级上升','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34472920,'蜂蜜机器人',replace(replace('电子界族怪兽２只\r\n①：此卡连接端的怪兽不会成为效果对象，不会因战斗被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34475451,'工程列车 红色信号','①：对手怪兽攻击宣言时可以发动。将此卡从手牌特殊召唤，将该对手怪兽的攻击对象移换为此卡并进行伤害计算。此卡不会因该战斗被破坏。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34479658,'暗黑短吻鳄',replace(replace('此卡可释放１只爬虫类族怪兽并上级召唤。\r\n①：此卡上级召唤成功时可发动。特殊召唤最多以此卡的上级召唤为目的而释放的爬虫类怪兽数量之“短吻鳄衍生物”（爬虫类族、暗、星１、攻２０００／守０）至我方场上。\r\n②：上级召唤来的此卡因战斗或对手效果被破坏的场合可发动。从牌组将１只除“暗黑短吻鳄”以外的爬虫类族怪兽加入手牌。','\r',char(13)),'\n',char(10)),'把1只爬虫类族怪兽解放作上级召唤','','是否继续特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34479659,'短吻鳄衍生物','由“暗黑短吻鳄”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34481518,'魔头炮 红莲恐龙',replace(replace('等级４怪兽×２\r\n此卡名的②效果１回合仅可使用１次。\r\n①：自己的恐龙族怪兽战斗破坏对手怪兽并将其送至墓地时，去除此卡的１个超量素材可以发动。给予对手１０００伤害。然后，此卡的攻击力上升１０００。\r\n②：超量召唤的此卡被破坏的情况下，以场上的１张卡为对象可以发动。将该卡破坏，给予对手１０００伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34487429,'虹之古代都市－彩虹遗迹',replace(replace('①：根据我方魔法与陷阱区域的“宝玉兽”卡牌数量获得以下效果。\r\n●１张或以上：此卡不会因效果被破坏。\r\n●２张或以上：１回合１次，可将给予我方的战斗伤害减半。\r\n●３张或以上：魔法、陷阱卡发动时，可将我方场上１只表侧表示的“宝玉兽”怪兽送入墓地并发动。使该发动无效并破坏。\r\n●４张或以上：１回合１次，可发动。我方抽取１张卡牌。\r\n●５张：１回合１次，可以我方魔法与陷阱区域的１张“宝玉兽”卡牌为对象发动。特殊召唤该卡牌。','\r',char(13)),'\n',char(10)),'伤害减半','魔法·陷阱发动无效并破坏','从自己牌组抽1张卡','魔法与陷阱卡区域的「宝玉兽」卡特殊召唤','','','','','','','','','','','','');
INSERT INTO texts VALUES(34492631,'废品巨人',replace(replace('①：对手场上存在等级5以上的怪兽的情况下，此卡可从手牌特殊召唤。\r\n②：以此卡作为素材的同步召唤不会被无效化，该同步召唤成功时，对手不可发动魔法・陷阱・怪兽的效果。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34496660,'超重武者 大八－８','此卡名的③效果１回合仅可使用１次。①：此卡召唤・特殊召唤成功时可以发动。变更此卡的表示形式。②：此卡可在表侧守备表示的状态下攻击。该情况下，将此卡的守备力视为攻击力来进行伤害计算。③：自己的墓地不存在魔法・陷阱卡的情况下可以发动。将自己场上表侧守备表示的此卡改成攻击表示，从牌组将１只“超重武者装魂”怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34507039,'发讯追踪','①：陷阱卡发动时可以发动。将该发动无效，将该卡放回持有者的牌组。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34522216,'无形噬体・暴食',replace(replace('←5 【灵摆】 5→\r\n此卡的控制者在每个自己的准备阶段解放自己场上的１只怪兽。\n或不解放而是破坏此卡。\n①：只要自己场上有“无形噬体”怪兽存在，双方不可发动“无形噬体”怪兽以外的怪兽的效果。\r\n【怪兽效果】\r\n①：只要灵摆召唤・反转的此卡存在于怪兽区域，双方从额外牌组仅可特殊召唤“无形噬体”怪兽。','\r',char(13)),'\n',char(10)),'是否解放自己场上1只怪兽？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34528176,'龙骑兵团骑士－阿瑞斯',replace(replace('协调＋协调以外的同步怪兽1只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：以自己的魔法与陷阱区域的表侧表示的怪兽卡的数量为上限，以对手场上的表侧表示卡为对象可以发动（此卡装备有装备卡的情况下，此效果在对手回合中也可以发动）。将该卡的效果直至回合结束时为止无效。\r\n②：此卡被装备中的情况下可以发动。将此卡特殊召唤。然后，可从自己墓地将1只“龙骑兵团”协调特殊召唤。','\r',char(13)),'\n',char(10)),'效果无效','特殊召唤','是否特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34536276,'蟹蜘蛛','拥有蟹钳的蜘蛛。用蜘蛛丝封住敌人的行动，再用蟹钳了结对方。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34536828,'烙印之使徒','此卡名的①②效果１回合仅可各使用１次。①：对手发动的怪兽的效果处理时，自己场上存在等级８以上的恶魔族融合怪兽，且该对手怪兽攻击力或守备力为０的情况下，可将该发动的效果无效。②：攻击力０的怪兽之间进行战斗的伤害步骤结束时可以发动。将该进行战斗的对手怪兽破坏。','是否适用「烙印之使徒」的效果来无效？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34541543,'大阴阳师 道',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：此卡与怪兽进行战斗的情况下，该2只不会因该战斗被破坏。\r\n②：此卡被送至墓地的情况下，以“大阴阳师 道”以外的、自己墓地的1只幻想魔族怪兽为对象可以发动。将该怪兽以守备表示特殊召唤。此效果发动后，直至回合结束时为止，自己从墓地仅可特殊召唤幻想魔族怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34541863,'「A」细胞增殖装置','我方准备阶段时，选择对手场上的１只表侧表示怪兽，并放置１个A计数物。','放置「A计数物」','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34541940,'神艺学徒 珐艺美忒',replace(replace('此卡名的①③效果1回合仅可各使用1次。\r\n①：自己场上存在“神艺”卡的情况下可以发动。从手牌将此卡特殊召唤。然后，自己可抽1张。\r\n②：对手不可将自己场上的等级6以下的“神艺”怪兽作为效果的对象。\r\n③：在自己・对手的主要阶段，自己场上的怪兽的种族为3种以上的情况下可以发动。对手场上的所有表侧表示怪兽的效果无效化，其攻击力直至回合结束时为止变为一半。','\r',char(13)),'\n',char(10)),'特殊召唤','无效','是否抽牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34545235,'钢核的光辉','对手发动了魔法、陷阱卡时，可向对手展示１张手牌的“核成之钢核”。使该发动无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34550857,'抒情歌鸲－钴尖晶雀',replace(replace('此卡名的①效果1回合仅可使用1次。①：此卡特殊召唤成功的情况下可以发动。从牌组将1只鸟兽族・等级1怪兽加入手牌。②：以场上的此卡为素材超量召唤的风属性怪兽将获得以下效果。\r\n●此卡不会成为对手效果的对象。','\r',char(13)),'\n',char(10)),'牌组检索','「抒情歌鸲－钴尖晶雀」效果适用中','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34559295,'钢铁抽牌','此卡名的卡１回合仅可发动１张。①：自己场上的怪兽仅为２只机械族效果怪兽的情况下可以发动。自己从牌组抽２张。此卡发动后，直至回合结束时为止，自己仅可特殊召唤怪兽１次。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34566435,'锋利小鬼・魔玩仿品',replace(replace('此卡在规则上也被视为“魔玩具”卡牌。\r\n“锋利小鬼・魔玩仿品”的效果１回合只可使用１次。\r\n①：可以我方场上、墓地的１只“魔玩具”融合怪兽为对象发动。直至回合结束时，此卡的攻击力、守备力变成与该怪兽原本数值相同数值。','\r',char(13)),'\n',char(10)),'攻守变换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34568403,'秘仪之力Ⅶ－战车',replace(replace('①：此卡召唤・反转召唤・特殊召唤的情况下发动。掷1次硬币，根据掷出的正反，此卡获得以下效果。\r\n●正面：此卡战斗破坏对手怪兽时可以发动。将该怪兽特殊召唤至自己场上。\r\n●反面：将此卡的控制权转移给对手。','\r',char(13)),'\n',char(10)),'投掷硬币','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34568783,'真次代机・水精灵',replace(replace('①：１回合１次，从自己的墓地将１只“次代机”怪兽除外可以发动。此卡的属性也视为与该怪兽相同的属性。将协调除外来发动的情况下，进而可将此卡直至回合结束时为止视为协调。\r\n②：自己场上存在“次代机”同步怪兽的情况下，将自己墓地包含此卡在内的２只“次代机”怪兽为对象可以发动。将该怪兽加入手牌。此回合，自己被送往墓地的卡不去墓地而直接被除外。','\r',char(13)),'\n',char(10)),'变更属性','墓地回收','是否将此卡当作协调使用？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34572613,'突异变种进化研究所',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：作为此卡发动时的效果处理，可从手牌及自己被除外的怪兽中，挑选１只等级４以下的“突异变种”怪兽特殊召唤。\r\n②：自己场上的“突异变种”怪兽的攻击力上升相当于自己被除外的“突异变种”卡的卡名的种类×１００的数值。\r\n③：１回合１次，在自己的主要阶段可以发动。从手牌将１只“突异变种”怪兽放回牌组最下面，自己从牌组抽１张。','\r',char(13)),'\n',char(10)),'是否要进行特殊召唤？','回到牌组并抽牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34611551,'武装龙之霹雳','此卡名的卡１回合仅可发动１张。①：从牌组将１只等级３“武装龙”怪兽以守备表示特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34614289,'超级运动员强壮阻挡员',replace(replace('因“超级运动员强壮阻挡员”①方法的特殊召唤１回合只可１次。\r\n①：此卡可将我方场上除“超级运动员强壮阻挡员”以外的１只“超级运动员”怪兽返回至手牌，并从手牌特殊召唤。\r\n②：１回合１次，对手特殊召唤怪兽成功时可发动。变更该怪兽的表示形式，并使该效果无效。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34614910,'六花精仙客至','此卡名的①②效果1回合仅可各使用1次。①：解放手牌・场上的此卡，可以自己场上最多2只植物族怪兽为对象发动。该怪兽的等级直到回合结束时下降2。②：此卡被解放并被送至墓地的回合的结束阶段可以发动。将此卡特殊召唤。用此效果特殊召唤的此卡从场上离开的情况下将被除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34620088,'机关傀偶－阴影感触者','此卡不会因战斗被破坏。此外，此卡存在于墓地，因对手怪兽的直接攻击自己受到战斗伤害时可以发动。将此卡以攻击表示特殊召唤，自己受到１０００点伤害。“机关傀偶－阴影感触者”的此效果１回合仅可使用１次。变为超量素材的此卡将被送至墓地的情况下，不去墓地而是直接被从游戏除外。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34627841,'正义的伙伴 海马人','①：解放此卡可以发动。从手牌将1只“青眼白龙”特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34646691,'绊倒','召唤・反转召唤・特殊召唤怪兽成功的情况下发动。该怪兽变为守备表示。','变成守备表示','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34659866,'暗海救生艇','此卡被使用于同步怪兽的同步召唤并被送入墓地的场合，从我方牌组抽取１张卡牌。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34664411,'幸运铁斧头',replace(replace('①：装备怪兽的攻击力上升５００。\r\n②：以表侧表示存在于场上的此卡因对手的效果而被破坏送入墓地的场合发动此卡。我方从牌组抽取１张卡牌。','\r',char(13)),'\n',char(10)),'抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34680482,'魔幻甜点・果冻天使',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：解放此卡可以发动。从牌组将１只“魔幻甜点”怪兽特殊召唤。以此效果特殊召唤的怪兽不会因战斗被破坏，将在下个自己回合的结束阶段被放回牌组。\r\n②：此卡被对手破坏并被送至墓地的情况下发动。将此卡放回牌组。','\r',char(13)),'\n',char(10)),'返回牌组','特殊召唤','「魔幻甜点·果冻天使」效果适用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34688023,'锋利小鬼・锯',replace(replace('“锋利小鬼・锯”的效果１回合只可使用１次。\r\n①：此卡召唤成功时，可将手牌的１只“绒毛动物”怪兽送入墓地并发动。我方从牌组抽取２张卡牌，之后，从手牌挑选１张卡牌返回至牌组的最上方或最下方。','\r',char(13)),'\n',char(10)),'抽2张卡','回牌组最上面','回牌组最下面','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34690519,'山的精灵','据说听了它手中之笛吹奏出的声音的人会浑身乏力。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34690953,'禁咒 菈玛启崇颂','此卡名的①②效果１回合仅可各使用１次。①：在自己的主要阶段可以发动。将１只“勇者衍生物”（天使族・地・星４・攻／守２０００）特殊召唤至自己或对手场上。然后，挑选１张自己的手牌送至墓地。发动此效果的回合中，自己仅可特殊召唤“勇者衍生物”及记载有该衍生物名的怪兽。②：自己场上的怪兽因战斗・效果被破坏的情况下可以发动。将１只“勇者衍生物”特殊召唤至自己或对手场上。','','特殊召唤衍生物','在自己场上特殊召唤','在对手场上特殊召唤','','','','','','','','','','','','');
INSERT INTO texts VALUES(34690954,'勇者衍生物','由“菈玛至崇颂之仪”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34694160,'真实之眼','只要此卡存在于场，对手持续公开手牌。对手的准备阶段时对手手牌中有魔法卡的场合，对手回复１０００LP。','回复','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34695290,'突异变种・猛兽',replace(replace('此卡仅可以“突异变种”卡的效果特殊召唤。\r\n此卡名的②③效果１回合仅可各使用１次。\r\n①：此卡不会成为对手怪兽的效果的对象。\r\n②：对手发动魔法卡的效果时，从自己的手牌・场上将１张卡除外可以发动。将该发动无效并除外。\r\n③：此卡被对手破坏的情况下，以自己１张被除外的“突异变种”陷阱卡为对象可以发动。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'无效并除外','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34707034,'深渊呼唤','选择我方墓地的３只冠有“水精鳞”之名的怪兽，并以守备表示特殊召唤。以此效果特殊召唤的怪兽的效果被无效化，不可进行攻击宣言，在结束阶段时被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34710660,'超电磁乌龟','此卡名的效果在决斗中仅可使用1次。①：在对手的战斗阶段将墓地的此卡除外可以发动。结束该战斗阶段。','战斗阶段结束','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34717238,'叠返','召唤成功时发动的怪兽的效果发动时可发动。使该发动无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34721681,'超重机回送',replace(replace('此卡名的卡１回合仅可发动１张。①：作为此卡发动时的效果处理，可从牌组将１只“无限起动”怪兽加入手牌。②：１回合１次，以自己场上的１只机械族超量怪兽为对象，可从以下效果中选择１个发动。\r\n●变更该怪兽的表示形式。\r\n●将此卡重叠在该怪兽下方作为超量素材。','\r',char(13)),'\n',char(10)),'是否把1只「无限起动」怪兽加入手牌？','表示形式变更','补充超量素材','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34743446,'碎块人','身体的各个部位会各自变成不同的武器，分裂并发动攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34755994,'伟魔少女 圣魔之阿耳忒弥斯',replace(replace('等级4以下的魔法师族怪兽1只\r\n自己1回合仅可特殊召唤1次“伟魔少女 圣魔之阿耳忒弥斯”，其①②效果1回合仅可各使用1次。\r\n①：此卡存在于怪兽区域的状态下，有“伟魔”怪兽被召唤・特殊召唤的情况下，以其中1只为对象可以发动。将自己场上的此卡视为装备魔法卡装备于该怪兽。\r\n②：此卡被装备中的情况下可以发动。从牌组将1只“伟魔”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34755995,'伟魔少女 圣魔之阿耳忒弥斯',replace(replace('等级4以下的魔法师族怪兽1只\r\n自己1回合仅可特殊召唤1次“伟魔少女 圣魔之阿耳忒弥斯”，其①②效果1回合仅可各使用1次。\r\n①：此卡存在于怪兽区域的状态下，有“伟魔”怪兽被召唤・特殊召唤的情况下，以其中1只为对象可以发动。将自己场上的此卡视为装备魔法卡装备于该怪兽。\r\n②：此卡被装备中的情况下可以发动。从牌组将1只“伟魔”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34761062,'业火的重骑士',replace(replace('①：只要此卡存在于场上或墓地中，将被视为通常怪兽。\r\n②：可再次以通常召唤的方式召唤场上视为通常怪兽的此卡。此场合下该卡将视为效果怪兽并得到以下效果。\r\n●此卡攻击特殊召唤的怪兽可在伤害步骤开始时发动此卡。将该怪兽除外。','\r',char(13)),'\n',char(10)),'除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34761841,'深红共鸣者',replace(replace('此卡名的①②效果１回合仅可各使用１次，发动此效果的回合中，自己从额外牌组仅可特殊召唤龙族・暗属性同步怪兽。\r\n①：自己场上不存在怪兽的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：自己场上此卡以外的怪兽仅有１只、且为龙族・暗属性同步怪兽的情况下可以发动。从手牌・牌组将“深红共鸣者”以外的最多２只“共鸣者”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34767865,'电脑网仪式','电子界族仪式怪兽的降临所必须。①：为使合计等级为仪式召唤的怪兽的等级以上，将自己手牌・场上的怪兽解放，从手牌将1只电子界族仪式怪兽仪式召唤。②：自己场上不存在怪兽的情况下，从自己的墓地将此卡和1只仪式怪兽除外可以发动。将2只“电脑网衍生物”（电子界族・光・星4・攻/守0）特殊召唤至自己场上。此效果在此卡被送至墓地的回合不可发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34767866,'电脑网衍生物','由“电脑网仪式”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34771947,'迷宫壁・影',replace(replace('①：除原本等级为５以上的怪兽之外的、被召唤・反转召唤・特殊召唤的怪兽在该回合不可攻击。\r\n②：１回合１次，在自己的主要阶段可以发动。挑选自己的手牌・牌组・除外状态的“雷魔神－桑迦”、“风魔神－休迦”、“水魔神－苏迦”中的任意１只，视为永续魔法卡，以表侧表示放在自己的魔法与陷阱区域。\r\n③：对手的战斗阶段开始时，以对手场上的１只攻击力不满１６００的怪兽为对象可以发动。将该怪兽破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34773082,'魔玩具补缀',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从牌组将1张“融合”和1只“锋利小鬼”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34796454,'三连星联盟','此卡作为上级召唤的释放被送入墓地回合的结束阶段时，此卡可从墓地特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34800281,'梅尔菲・乐西','此卡名的①②效果１回合仅可各使用１次。①：自己场上“梅尔菲・乐西”以外的表侧表示的兽族怪兽放回手牌的回合可以发动。从手牌将此卡特殊召唤。然后，可仅以此卡和手牌的“梅尔菲”怪兽作为素材同步召唤。此效果在对手回合中也可以发动。②：在自己的结束阶段此卡存在于墓地的情况下，以自己场上的１只兽族超量怪兽为对象可以发动。将此卡重叠在该怪兽下方作为超量素材。','','','是否同步召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34813443,'无境的灰灭',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：在自己・对手的主要阶段可以发动。将包含“灭亡龙 维都苏”在内的、自己・对手场上的怪兽作为融合素材，将１只炎族融合怪兽融合召唤。以此效果特殊召唤的怪兽的攻击力上升相当于作为其融合素材的怪兽数量×５００的数值。\r\n②：从自己墓地将１只炎族・暗属性怪兽和此卡除外可以发动。对手场上的所有怪兽直至回合结束时为止变为炎族。','\r',char(13)),'\n',char(10)),'','融合召唤','改变种族','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34813545,'大植然春风',replace(replace('①：可从以下效果中选择１个发动。\r\n●从自己的手牌・墓地挑选１只“大植然”怪兽特殊召唤。\r\n●将包含“大植然”怪兽在内的自己场上的怪兽作为素材同步召唤。\r\n●从自己场上将由融合怪兽卡决定的、包含“大植然”怪兽在内的融合素材怪兽送至墓地，从额外牌组将１只该融合怪兽融合召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','同步召唤','融合召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34815282,'迷你化','可选择场上１只原本攻击力高于１０００的怪兽并发动此卡。被选择怪兽的等级下降１级，攻击力下降１０００点。该怪兽从场上离开时，破坏此卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34822850,'炼狱的泛滥',replace(replace('①：在自己的准备阶段可以发动。将１只“狱炎机衍生物”（恶魔族・炎・星１・攻／守０）特殊召唤至自己场上。\r\n②：以自身的方法特殊召唤“狱炎机”怪兽的情况下，也可从自己场上将“狱炎机”怪兽除外。\r\n③：在自己场上的“狱炎机”怪兽中，对手怪兽不可将等级最高的怪兽以外的“狱炎机”怪兽选择为攻击对象，且对手不可将之作为效果的对象。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34822851,'狱炎机衍生物','由“炼狱的泛滥”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34830502,'终极昆虫 LV5','只要以“终极昆虫 LV3”的效果特殊召唤的此存在于场上，对手场上所有怪兽的攻击力下降５００点。在我方准备阶段时，可将场上的此卡送入墓地并发动。从手牌、牌组特殊召唤１只“终极昆虫 LV7”。此效果不可在此卡进行过召唤、特殊召唤、反转的回合发动。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34834619,'流光龙降临','降临“光子龙圣骑士”的必备。必须从我方手牌、场上释放等级合计是４的怪兽。此外，在我方主要阶段时可将墓地的此卡从游戏中除外并发动。为使等级合计变成４，将我方墓地的怪兽从游戏中除外，并从手牌将１只“光子龙圣骑士”视为仪式召唤进行特殊召唤。','仪式召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34838437,'加速之光','此卡名的卡1回合仅可发动1张，发动此卡的回合中，自己不可通常召唤。①：自己场上不存在怪兽的情况下可以发动。从牌组将1只等级4以下的“光子”怪兽或“银河”怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34848821,'痕喰龙 蛮寇兽种',replace(replace('“阿尔白斯之落胤”＋等级8以上的怪兽\r\n此卡名的③效果1回合仅可使用1次。\r\n①：此卡不会因战斗被破坏。\r\n②：只要融合召唤的此卡存在于怪兽区域，对手不可将自己场上的其他怪兽作为怪兽效果的对象。\r\n③：在此卡被送至墓地的回合的结束阶段可以发动。从牌组挑选1只“铁兽”怪兽或“阿尔白斯之落胤”，加入手牌或特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34853266,'月读命','此卡不可特殊召唤。①：此卡召唤・反转的情况下，以场上的１只表侧表示怪兽为对象发动。将该怪兽改成里侧守备表示。②：此卡召唤・反转的回合的结束阶段发动。将此卡放回持有者的手牌。','回到手牌','改变表示形式','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34873741,'妖精灵 库里缎带',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：自己场上存在“上古精灵龙”或兽族・植物族・天使族的光属性怪兽中的任一的情况下可以发动。从手牌将此卡特殊召唤。将以此效果特殊召唤的此卡视为协调。\r\n②：自己场上的其他的、“上古精灵龙”或记载有该卡名的怪兽将被效果破坏的情况下，作为代替可将场上的此卡放回手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34876719,'沉魂救济帝车骑士',replace(replace('等级5怪兽×2\r\n此卡名的②效果1回合仅可使用1次。\r\n①：只要场上存在“编号”怪兽，此卡不会因战斗被破坏。\r\n②：在自己・对手的主要阶段，去除此卡的2个超量素材可以发动。从额外牌组将“编号101”～“编号107”中的任意1只“编号”超量怪兽作为此卡的超量素材。然后，可将场上1只其他的表侧表示怪兽作为此卡的超量素材。','\r',char(13)),'\n',char(10)),'','是否再选择1只怪兽作为超量素材？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34884015,'魂之灵摆',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：以自己灵摆区域的２张卡为对象可以发动。对象卡的灵摆刻度分别上升或下降１（最低降至１）。\r\n②：每次自己的灵摆怪兽被灵摆召唤，在此卡上放１个计数物。\r\n③：场上的灵摆怪兽的攻击力上升相当于此卡计数物数量×３００的数值。\r\n④：去除此卡的３个计数物可以发动。此回合，自己在通常的灵摆召唤之外仅可追加１次，可在自己的主要阶段灵摆召唤怪兽。','\r',char(13)),'\n',char(10)),'改变刻度','刻度上升','刻度下降','额外灵摆召唤','使用「魂之灵摆」的效果灵摆召唤','','','','','','','','','','','');
INSERT INTO texts VALUES(34898052,'牙龙咆哮','①：可将我方墓地的地、水、炎、风属性怪兽各１只除外并发动。挑选场上的１张卡牌返回至持有者牌组。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34904525,'雷风魔神－门之守护者',replace(replace('“雷魔神－桑迦”＋“风魔神－休迦”\r\n仅可在将自己场上的上述卡除外的情况下特殊召唤。\r\n此卡名的①效果１回合仅可使用１次。\r\n①：在自己的主要阶段可以发动。从牌组将１张记载有“雷魔神－桑迦”、“风魔神－休迦”、“水魔神－苏迦”全部卡名的魔法・陷阱卡加入手牌。\r\n②：特殊召唤的表侧表示的此卡因对手从场上离开的情况下可以发动。将自己除外状态的１只“雷魔神－桑迦”或“风魔神－休迦”特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34906152,'质量加速器','解放自己场上的１只怪兽可以发动。给予对手LP４００点伤害。','给予对手400分伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34909328,'雷热涡炉・绝命导爆',replace(replace('等级４“雷热涡炉”怪兽×２只以上\r\n此卡名的①③效果１回合仅可各使用１次。\r\n①：此卡特殊召唤的情况下可以发动。将自己墓地的１只怪兽作为此卡的超量素材。\r\n②：对手发动卡的效果时，去除此卡的１个超量素材，以场上的１张卡为对象可以发动。将该卡破坏。\r\n③：自己场上的超量怪兽将被战斗・效果破坏的情况下，作为代替可去除此卡的１个超量素材。','\r',char(13)),'\n',char(10)),'获取素材','破坏效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34923554,'无限起动 龙式挖掘机','此卡名的①②效果１回合仅可各使用１次。①：解放自己场上的１只机械族・地属性怪兽可以发动。将此卡从手牌以守备表示特殊召唤。②：从自己的墓地将１只机械族怪兽除外可以发动。从牌组将１张“超原地转向”加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34926568,'守护兽 塞尔凯特',replace(replace('此卡不可通常召唤。\r\n“守护兽 塞尔凯特”1回合1次，在自己场上存在“王家的神殿”的状态下，从手牌・牌组将1只等级10以上的怪兽除外的情况下可以特殊召唤。\r\n①：1回合1次，在自己的主要阶段可以发动。从牌组将1张“王家的神殿”或记载有该卡名的魔法卡加入手牌。\r\n②：此卡与对手怪兽进行战斗的伤害步骤开始时可以发动。将该对手怪兽破坏，此卡的攻击力上升相当于破坏的怪兽原本攻击力的一半的数值。','\r',char(13)),'\n',char(10)),'特殊召唤','检索','破坏','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34933456,'伟魔降灵','此卡名的卡1回合仅可发动1张。①：从自己的手牌・场上，将由融合怪兽卡决定的、包括魔法师族怪兽在内的融合素材怪兽送至墓地，从额外牌组将1只该融合怪兽融合召唤。将“伟魔”融合怪兽融合召唤的情况下，“伟魔”怪兽所装备的、自己魔法与陷阱区域视为装备卡的怪兽卡也可以作为融合素材使用。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34945480,'外神 阿撒托斯',replace(replace('等级５怪兽×３\r\n此卡也可重叠在自己场上的“外神”超量怪兽上面来超量召唤。\r\n此卡不可作为超量召唤的素材。\r\n①：此卡超量召唤成功的回合，对手不可发动怪兽的效果。\r\n②：此卡将融合・同步・超量怪兽都作为超量素材的情况下，去除此卡的１个超量素材可以发动。将对手场上的卡全部破坏。','\r',char(13)),'\n',char(10)),'对手场上的卡全部破坏','是否在自己场上的「外神」超量怪兽上面重叠来超量召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34950192,'心影依结合',replace(replace('此卡名的①②效果1回合仅可各使用1次，发动此效果的回合中，自己从额外牌组仅可特殊召唤“影依”怪兽。\r\n①：作为此卡发动时的效果处理，从额外牌组将1只融合怪兽送至墓地。\r\n②：解放自己场上的1只融合怪兽可以发动。从额外牌组将1只属性与该怪兽不同的“影依”融合怪兽视为融合召唤特殊召唤。以此效果特殊召唤的怪兽攻击力变为0。','\r',char(13)),'\n',char(10)),'发动','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34959756,'活化石','此卡名的卡1回合仅可发动1张。①：可以自己墓地的1只等级4以下的怪兽为对象发动此卡。将该怪兽特殊召唤，装备此卡。以此效果特殊召唤的怪兽在离开场上的情况下被除外。此卡离开场上时该怪兽被除外。②：装备怪兽的攻击力・守备力下降1000点，效果被无效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34961968,'幻兽 雷电天马','对手怪兽的攻击宣言时，可将墓地的此卡从游戏中除外，并选择我方场上１只冠有“幻兽”之名的怪兽发动。此回合，所选择怪兽不会因战斗而被破坏。','不被战斗破坏','请选择一只名字带有「幻兽」的怪兽','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34966096,'混沌叛徒',replace(replace('此卡牌名的①②效果１回合只可各使用１次。\r\n①：此卡存在于墓地的场合，可从我方墓地将除“混沌叛徒”以外的光属性与暗属性怪兽各１只除外并发动。以守备表示特殊召唤此卡。因此效果特殊召唤而来的此卡，从场上离开的场合被除外。\r\n②：此卡特殊召唤成功的场合，可以对手墓地的１张卡牌为对象发动。将该卡除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34968834,'暗黑界之鬼神 透特','此卡因卡牌效果从手牌被舍弃至墓地的场合，从墓地特殊召唤此卡。因对手卡牌效果被舍弃的场合，可另从我方牌组特殊召唤１只恶魔族怪兽至我方或对手场上。','特殊召唤','是否要从自己牌组特殊召唤？','在自己场上特殊召唤','在对手场上特殊召唤','','','','','','','','','','','','');
INSERT INTO texts VALUES(34974462,'幻奏华乐圣 绽放谐曲家',replace(replace('天使族怪兽２只\r\n此卡名的①效果１回合仅可使用１次。\r\n①：此卡连接召唤的情况下，舍弃１张手牌可以发动（发动此效果的回合中，自己仅可特殊召唤“幻奏”怪兽）。从牌组将２只等级不同的“幻奏”怪兽以守备表示特殊召唤至此卡连接端的自己场上。\r\n②：此卡连接端的“幻奏”怪兽攻击的情况下，对手直至伤害步骤结束时为止，不可发动魔法・陷阱・怪兽的效果。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34976176,'黑羽－雪击之奇努克','此卡名的效果１回合仅可使用１次。①：将手牌・场上的此卡送至墓地，以对手场上的１只表侧表示怪兽为对象可以发动。从额外牌组将１只“黑羽”同步怪兽或“黑翼龙”送至墓地，对象怪兽直至回合结束时为止，攻击力下降７００，效果无效化。自己场上存在暗属性同步怪兽的情况下，此效果在对手回合中也可以发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34989413,'重编梁龙',replace(replace('怪兽2只\r\n此卡名的效果1回合仅可使用1次。①：可从以下效果中选择1个发动。\r\n●宣言1个种族可以发动。此卡连接端的所有表侧表示怪兽的种族直至回合结束时为止变成宣言的种族。\r\n●宣言1个属性可以发动。此卡连接端的所有表侧表示怪兽的属性直至回合结束时为止变成宣言的属性。','\r',char(13)),'\n',char(10)),'改变种族','改变属性','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(34995106,'白之烙印',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：将包含龙族怪兽在内的、自己手牌・场上的怪兽作为融合素材，将1只融合怪兽融合召唤。要将自己的“阿尔白斯之落胤”作为融合素材的情况下，也可将自己墓地的怪兽除外来作为融合素材。\r\n②：在此卡为发动“阿尔白斯之落胤”的效果被送至墓地的回合的结束阶段可以发动。将此卡放置在自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35011819,'帝皇勒令','①：在怪兽召唤时发动的怪兽效果发动时可以发动。将该发动无效。然后，发动被无效的玩家抽1张。','无效并抽牌','是否要把怪兽的效果的发动无效？','发动同时使用效果','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35014241,'超限疾驰','此卡名的卡1回合仅可发动1张。①：将自己场上1只同步怪兽的协调和1只协调以外的同步怪兽放回额外牌组可以发动。将1只等级与该2只怪兽等级合计相同的同步怪兽无视召唤条件从额外牌组特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35026117,'迷宫的重魔战车',replace(replace('此卡名的③效果１回合仅可使用１次。\r\n①：此卡无需解放即可召唤。\r\n②：此卡在召唤的回合不可攻击。\r\n③：在自己的主要阶段可以发动。挑选自己的手牌・牌组・除外状态的“雷魔神－桑迦”、“风魔神－休迦”、“水魔神－苏迦”中的任意１只，视为永续魔法卡，以表侧表示放在自己的魔法与陷阱区域。自己场上存在“迷宫壁”卡的情况下，进而可破坏对手场上的１只怪兽。','\r',char(13)),'\n',char(10)),'不用解放作召唤','','是否选对手场上1只怪兽破坏？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35027493,'魔之牌组破坏病毒','①：解放自己场上攻击力２０００以上的１只暗属性怪兽可以发动。确认所有对手场上的怪兽、对手的手牌、从对手回合算起３回合内对手所抽的卡，将其中攻击力１５００以下的怪兽全部破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35035481,'伯吉斯吸虫・拟油栉虫',replace(replace('①：以场上的1张魔法・陷阱卡为对象可以发动。将该卡破坏。\r\n②：此卡存在于墓地，且陷阱卡发动时可以发动（同一连锁上最多1次）。此卡变为通常怪兽（水族・水・星2・攻1200/守0），特殊召唤至怪兽区域（不视为陷阱卡）。以此效果特殊召唤的此卡不受怪兽效果影响，从场上离开的情况下将被除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35035985,'灰灭之末路',replace(replace('炎族怪兽×２\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡融合召唤的情况下，以自己墓地的１张场地魔法卡为对象可以发动。将该卡加入手牌。\r\n②：此卡与对手的炎族怪兽进行战斗的伤害步骤开始时可以发动。将该对手怪兽破坏。此效果在自己回合发动的情况下，此卡可继续再攻击仅１次。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35037880,'军刀反射',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：自己场上存在“X－军刀”怪兽，自己因战斗・效果受到伤害时可以发动。依所受到的伤害数值恢复自己的LP，依该数值给予对手伤害。然后，可从牌组将1张“军刀”魔法・陷阱卡或“加特姆士”卡加入手牌。','\r',char(13)),'\n',char(10)),'牌组检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35050257,'电子幼虫','①：此卡在被选择为攻击对象的情况下发动。此回合中，自己受到的所有战斗伤害变为0。②：此卡因战斗被破坏且送至墓地时可以发动。从牌组中将1只“电子幼虫”特殊召唤。','战斗伤害变成0','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35052053,'甲虫装甲骑士','甲虫装甲骑士在昆虫战士中，是隶属于精英中的精英“无死虫团”的精锐骑士。他们强大的战斗力不容忽视。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35057188,'蜂军－革命之阔枪大游击',replace(replace('协调＋协调以外的怪兽１只以上\r\n此卡名的③效果１回合仅可使用１次。\r\n①：此卡只要存在于怪兽区域，不会因效果被破坏。\r\n②：自己场上的昆虫族同步怪兽的攻击力上升相当于自己除外状态的昆虫族怪兽的数量×２００的数值。\r\n③：此卡被除外的情况下可以发动。将此卡特殊召唤。然后，可将对手场上的卡破坏，数量最多为自己除外状态的昆虫族怪兽的数量。该情况下，进而给予对手相当于所破坏的数量×５００的伤害。','\r',char(13)),'\n',char(10)),'','是否选对手的卡破坏？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35058588,'方界波动',replace(replace('①：可以我方场上１只“方界”怪兽和对手场上１只表侧表示怪兽为对象发动。该我方怪兽的攻击力加倍，而该对手怪兽的攻击力减半。\r\n②：可从我方墓地除外此卡和任意数量的“方界”怪兽，并以对手场上的表侧表示怪兽为对象发动，其数量相当于被除外的“方界”怪兽数量。在该怪兽各放置１个方界计数物。放置有方界计数物的怪兽不可进行攻击，并效果被无效化。','\r',char(13)),'\n',char(10)),'改变攻击力','放置计数物','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35058857,'奇术王 月星',replace(replace('以此卡作为同步素材的情况下，仅可使用于暗属性怪兽的同步召唤。\r\n①：自己场上存在协调的情况下，此卡可从手牌中特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下，以自己场上（表侧表示）・墓地的１只怪兽为对象可以发动。直至回合结束时为止，此卡的等级变为与该怪兽相同。此效果发动后，直至回合结束时为止，自己不可进行同步召唤以外的特殊召唤。','\r',char(13)),'\n',char(10)),'等级变更','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35059553,'凯撒竞技场','①：只要自己场上存在怪兽，对手就不可将多于其数量的怪兽出到自身场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35073065,'幻想掠夺者','①：自己将怪兽上级召唤时可以发动。从手牌将此卡特殊召唤。以此效果特殊召唤的此卡的种族・属性・等级变为与该上级召唤的怪兽相同。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35089369,'风龙星－蒲牢','此卡名的①效果1回合仅可使用1次。①：自己场上的此卡因战斗・效果被破坏并被送至墓地时可以发动。从牌组将1只“风龙星-蒲牢”以外的“龙星”怪兽以攻击表示特殊召唤。②：1回合1次，在对手的主要阶段以及战斗阶段可以发动。仅以自己场上的“龙星”怪兽作为同步素材同步召唤。③：以此卡作为同步素材的同步怪兽不受魔法卡的效果影响。','特殊召唤','「风龙星－蒲牢」效果适用中','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35095329,'邪恶－英雄 恶意之爪',replace(replace('此卡名的①效果1回合仅可使用1次，且②效果在决斗中仅可使用1次。\r\n①：以场上的1只“－英雄”怪兽为对象可以发动。从手牌将此卡以守备表示特殊召唤，对象怪兽的攻击力上升300。\r\n②：自己场上的怪兽因战斗・效果被破坏的情况下可以发动。从墓地将此卡特殊召唤。然后，自己墓地存在记载有“黑暗结合”卡名的怪兽的情况下，可将场上的1张卡破坏。','\r',char(13)),'\n',char(10)),'从手牌特殊召唤','从墓地特殊召唤','是否把卡破坏？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35098357,'魔女工艺・混乱结合',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：将包含“魔女工艺”怪兽在内的、自己手牌・场上的怪兽作为融合素材，将1只融合怪兽融合召唤。\r\n②：在自己的结束阶段，此卡存在于墓地，且自己场上存在“魔女工艺”怪兽的情况下可以发动。将此卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35100834,'机动炮垒 强力要塞',replace(replace('①：此卡发动后，变为效果怪兽（机械族・地・星４・攻０／守２０００），特殊召唤至怪兽区域。然后，可从手牌・牌组挑选１只机械族・等级４的“小工具”怪兽，视为装备卡装备于此卡。此卡也视为陷阱卡。\r\n②：以此卡的效果被特殊召唤的此卡的攻击力上升相当于以此卡效果装备的怪兽的攻击力的两倍的数值。','\r',char(13)),'\n',char(10)),'是否装备？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35103106,'进化帝・沧怒龙',replace(replace('等级6怪兽×2\r\n①：对手不可将持有超量素材的此卡作为怪兽的效果的对象。\r\n②：对手发动卡的效果时，去除此卡的2个超量素材，以对手场上的1张表侧表示卡为对象可以发动（此卡仅持有爬虫类族・恐龙族怪兽作为超量素材的情况下，可将要去除的超量素材数量改成1个）。将该卡的效果直至回合结束时为止无效。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35112613,'库里光子','此卡名的②效果1回合仅可使用1次。①：将此卡从手牌送至墓地，支付2000LP可以发动。此回合中，自己受到的全部伤害变为0。此效果在对手回合中也可以发动。②：此卡存在于墓地的情况下，从手牌将“库里光子”以外的1只“光子”怪兽送至墓地可以发动。将墓地的此卡加入手牌。','伤害变成0','返回手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35125879,'真龙皇的复活',replace(replace('此卡名的①②③效果1回合仅可各使用1次，①②效果不可在同一连锁上发动。\r\n①：以自己墓地的1只“真龙”怪兽为对象可以发动。将该怪兽以守备表示特殊召唤。此效果发动后，直至回合结束时为止自己不可特殊召唤怪兽。\r\n②：在对手的主要阶段可以发动。以表侧表示进行1只“真龙”怪兽的上级召唤。\r\n③：此卡从魔法与陷阱区域被送至墓地的情况下，以场上的1只怪兽为对象可以发动。将该怪兽破坏。','\r',char(13)),'\n',char(10)),'墓地苏生','上级召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35129241,'星尘的祈愿',replace(replace('①：１回合１次，我方场上的“星尘”同步怪兽为了发动自身的效果而被解放的场合，可以１只该怪兽为对象发动。特殊召唤该怪兽。针对此效果的发动，对手不可发动魔法・陷阱・怪兽的效果。\r\n②：以此卡的①效果特殊召唤而来的怪兽是攻击表示的场合，不会因战斗被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35146019,'幻变骚灵・物化','此卡名的②效果1回合仅可使用1次。①：以自己墓地的1只“幻变骚灵”怪兽为对象可以发动此卡。将该怪兽以攻击表示特殊召唤，将此卡视为装备卡装备给该怪兽。此卡从场上离开时该怪兽将被破坏。②：将墓地的此卡除外，以自己墓地的1张“幻变骚灵”陷阱卡为对象可以发动。将该卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35149085,'家畜虐杀','选择我方场上的１只兽族怪兽并返回至持有者手牌，从手牌特殊召唤１只与返回手牌怪兽同等级的兽族怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35151572,'灰灭之都的咒术师',replace(replace('此卡名以①方法的特殊召唤１回合仅可进行１次，且②效果１回合仅可使用１次。\r\n①：场地区域存在“灰灭之都 黑曜城”的情况下，此卡可从手牌特殊召唤。\r\n②：以自己墓地・除外状态的３只炎族怪兽为对象可以发动。将该怪兽放回牌组。以此效果放回了“灰灭”怪兽的情况下，进而可从牌组将１张“灰灭之都 黑曜城”加入手牌。','\r',char(13)),'\n',char(10)),'','回收怪兽','是否把「灰灭之都 黑曜城」加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35167375,'惊喜结合',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：以自己场上的1只表侧表示怪兽为对象，宣言种族和属性各1个可以发动。该怪兽变为宣言的种族・属性。然后，可将包含该怪兽在内的、自己场上的怪兽作为融合素材，将1只融合怪兽融合召唤。\r\n②：将墓地的此卡除外可以发动。解放自己场上的1只融合怪兽，将2只等级与其等级相同的“惊喜衍生物”（魔法师族・暗・攻/守0）特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'融合召唤','特殊召唤衍生物','是否进行融合？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35167376,'惊喜衍生物','由“惊喜结合”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35183584,'星遗物守护龙 黑之米罗达克','此卡名的①③效果1回合仅可各使用1次。①：从自己的手牌・墓地将2只通常怪兽除外可以发动。从手牌将此卡特殊召唤。②：只要此卡存在于怪兽区域，对手场上怪兽的攻击力・守备力下降相当于自己场上龙族怪兽数量×500的数值。③：场上的此卡因战斗・效果被破坏的情况下可以发动。从自己墓地挑选1只原本种族・属性与此卡不同的等级9怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35183853,'镜鸣武斗神','我方场上存在有冠有“武斗神”之名的兽战士族怪兽，且对手场上的怪兽数量多于我方场上的怪兽数量的场合，可在主要阶段１开始时发动。直至下一个对手回合结束时，双方都不可发动魔法、陷阱卡效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35187185,'梦魔镜天魔－涅伊洛斯',replace(replace('属性不同的“梦魔镜”怪兽×2\r\n此卡名的②③效果1回合仅可各使用1次。①：只要此卡存在于怪兽区域，此卡的属性也视为“暗”。②：自己场上此卡以外的怪兽被解放的情况下，以场上的1张卡为对象可以发动。将该卡破坏。③：此卡因对手被破坏的情况下可以发动。从自己的墓地挑选“梦魔镜天魔-涅伊洛斯”以外的1只“梦魔镜”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35191415,'黑幻像之魔导','此卡名的①③效果1回合仅可各使用1次。①：自己在对手回合发动魔法・陷阱卡的效果的情况下可以发动。从手牌将此卡特殊召唤。②：只要此卡存在于怪兽区域，卡名视为“黑魔导”。③：只要此卡在场上以表侧表示存在，仅限1次，自己发动魔法・陷阱卡效果的情况下，以自己墓地的1只“黑魔导”为对象可以发动。将该怪兽特殊召唤。','此卡从手牌特殊召唤','自己墓地1只「黑魔导」特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35195612,'砂尘的骑士','反转：从牌组将１只地属性怪兽送入墓地。','检索送墓','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35199656,'淘气仙星・曼珠诗华',replace(replace('①：在自己・对手回合中，向对手出示手牌中的此卡，以自己场上“淘气仙星・曼珠诗华”以外的１只“淘气仙星”怪兽为对象可以发动。将此卡特殊召唤，将对象怪兽放回手牌。\r\n②：只要此卡存在于怪兽区域，每当有卡加入对手的手牌，就给予对手相当于加入的卡的数量×２００的伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35209994,'邪蚀 巨鹰','反转：选择对手场上的１张表侧表示卡牌并返回至持有者手牌。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35215622,'盲信格布林','只要此卡以表侧表示存在于场上，不可变更控制权。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35220244,'重力炮','仅限装备机械族怪兽。１回合１次，可令装备怪兽的攻击力上升４００点。此外，装备怪兽与对手怪兽进行战斗的场合，对手怪兽的效果在战斗阶段中无效。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35224440,'剑斗训练所','①：从牌组将１只等级４以下的“剑斗兽”怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35240714,'军刀合击',replace(replace('此卡名的②③效果1回合仅可各使用1次。\r\n①：只要自己场上・墓地・除外状态的“X－军刀”怪兽为10只以上，自己场上的“X－军刀”怪兽的攻击力就上升相当于自身原本守备力的数值。\r\n②：自己从额外牌组将“X－军刀”怪兽特殊召唤的情况下可以发动。从手牌・牌组将1只“X－军刀”怪兽特殊召唤。\r\n③：对手怪兽攻击宣言时可以发动。从手牌将1只“X－军刀”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','特殊召唤','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35252119,'电脑堺兽－鹫鹫',replace(replace('协调＋１只以上协调以外的怪兽\r\n此卡名的②效果１回合仅可使用１次。①：只要原本种族・属性相同、卡名不同的怪兽在自己的墓地有２只以上存在，场上的此卡不会因战斗・效果被破坏。②：将２只原本种族・属性相同、卡名不同的怪兽从自己的墓地除外，以场上的１张卡为对象可以发动。将该卡送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35255456,'奇迹接触','①：从自己的手牌・场上・墓地，将由融合怪兽卡决定的融合素材怪兽放回持有者的牌组，将以“元素－英雄 新宇侠”作为融合素材的该１只“元素－英雄”融合怪兽无视召唤条件，从额外牌组特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35259350,'微笑宇宙',replace(replace('发动此卡的回合中，自己不可以此卡的效果以外的方法召唤・特殊召唤怪兽，自己的怪兽不可攻击。\r\n①：从自己的额外牌组尽可能地将表侧表示的灵摆怪兽特殊召唤。以此效果特殊召唤的怪兽的效果无效化。然后，依以此效果特殊召唤的怪兽的原本攻击力的合计数值，恢复对手的LP。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35261759,'强欲而贪欲之壶',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：从自己牌组上面将１０张卡以里侧除外可以发动。自己抽２张。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35262428,'贤者的圣杯','我方场上没有怪兽存在的场合，可选择对手墓地中的１只怪兽发动此卡。将所选择怪兽特殊召唤至我方场上。在该回合的结束阶段时，将以此效果特殊召唤的怪兽的控制权移交给对手。此外，以此效果特殊召唤的怪兽不可释放，也不可作为同步素材使用。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35263180,'偷吃零嘴的大屋枛姬',replace(replace('①：１回合１次，场上的此卡成为攻击・效果的对象时可以发动。将１只“零嘴衍生物”（植物族・光・星１・攻／守８００）特殊召唤至自己场上。\r\n②：１回合１次，对手将怪兽特殊召唤之际，解放自己场上的１只通常怪兽可以发动。将该特殊召唤无效，将该怪兽破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35263181,'零嘴衍生物','由「偷吃零嘴的大屋枛姬」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35268887,'伤害转化器','此回合我方受到的效果伤害减半。此回合的结束阶段时，以守备表示特殊召唤与承受效果伤害次数相同的“幽灵衍生物”（恶魔族、暗、星１、攻／守０）至我方场上。','特殊召唤Token','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35268888,'幽灵衍生物','由“伤害转化器”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35269904,'三战之号',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：对手在此回合有发动过怪兽效果的情况下可以发动。从牌组将“三战之号”以外的1张通常魔法・通常陷阱卡放置在自己场上。以此效果放置的卡此回合不可发动。对手场上存在怪兽的情况下，也可不放置而是改为加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35269905,'三战之号',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：对手在此回合有发动过怪兽效果的情况下可以发动。从牌组将“三战之号”以外的1张通常魔法・通常陷阱卡放置在自己场上。以此效果放置的卡此回合不可发动。对手场上存在怪兽的情况下，也可不放置而是改为加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35272499,'捕食植物 蜂兰蝎',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：此卡召唤・特殊召唤的情况下，从手牌将1只怪兽送至墓地可以发动。从牌组将“捕食植物 蜂兰蝎”以外的1只“捕食植物”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35282433,'蓝眼银僵尸','据说可以从眼睛里射出怪异的光线，把对手变成僵尸。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35283277,'炎兽使 艾卡',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡召唤・特殊召唤成功的情况下，以自己或对手的魔法与陷阱区域的１张表侧表示怪兽卡为对象可以发动。将该卡特殊召唤至自己场上。\r\n②：以自己场上此卡以外的１只表侧表示怪兽为对象可以发动。将该表侧表示的怪兽视为攻击力上升５００的装备卡装备于此卡。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35306215,'失乐的堕天使',replace(replace('天使族怪兽2只\r\n此卡名的②效果1回合仅可使用1次。\r\n①：只要此卡存在于怪兽区域，自己要上级召唤需要解放2只怪兽的天使族怪兽的情况下，可不解放2只怪兽，而是从自己墓地将2只怪兽除外来上级召唤。\r\n②：舍弃1张手牌可以发动。从牌组挑选1只“堕天使”怪兽，加入手牌或送至墓地。\r\n③：在自己的结束阶段发动。自己恢复场上天使族怪兽数量×500的LP。','\r',char(13)),'\n',char(10)),'把墓地2只怪兽除外上级召唤','牌组检索','回复基本分','请选择要加入手牌或送至墓地的卡','','','','','','','','','','','','');
INSERT INTO texts VALUES(35307484,'噬恶・汤匙','除“噬恶・汤匙”以外冠有“噬恶”之名的怪兽被召唤、特殊召唤至我方场上时，可从我方墓地选择１只恶魔族、等级２怪兽并特殊召唤。以此效果特殊召唤的怪兽的效果被无效化。“噬恶・汤匙”的效果１回合只可使用１次。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35311929,'阳龙果 凤梨','此卡名的①效果１回合仅可使用１次。①：此卡以怪兽的效果从牌组被送至墓地的情况下可以发动。将此卡特殊召唤。自己场上有其他植物族怪兽存在的情况下，可进而挑选场上的１只怪兽，将其攻击力・守备力改成一半。②：１回合１次，场上的此卡将被战斗・效果破坏的情况下，可从牌组将１只植物族怪兽送至墓地作为代替。','','是否选1只怪兽攻击力·守备力变成一半？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35316708,'刻之封印','跳过下次对手回合的抽牌阶段。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35322812,'人造木人１８','这是神秘的大木１８利用魔界的先进技术改造而成的模样。因为过于重视坚固的装甲，而牺牲了其机动性。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35329581,'暗影冲动',replace(replace('“暗影冲动”１回合只可发动１张。\r\n①：我方场上的同步怪兽因战斗、效果被破坏并送入墓地时，可以１只该怪兽为对象发动。从额外牌组特殊召唤１只与该怪兽相同等级、种族但卡牌名不同的同步怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35330871,'彼岸鬼神 赫尔雷卡','以“善恶的彼岸”降临。此卡只可以仪式召唤方式特殊召唤。①：1回合1次，从手牌将1只“彼岸”怪兽送至墓地，以对手场上的1只表侧表示怪兽为对象可以发动。该对手怪兽的攻击力・守备力直至回合结束时为止，分别下降为发动此效果而被送至墓地的怪兽的相应数值。此效果在对手回合中也可以发动。②：此卡从场上被送至墓地的情况下，以场上的1张卡为对象可以发动。将该卡送至墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35334193,'超元特防队 证义',replace(replace('包括“超元特防队”怪兽在内的效果怪兽３只\r\n自己不可将怪兽出到此卡的连接端。此卡名的①效果１回合仅可使用１次。①：在自己・对手回合中，以对手场上的１只效果怪兽为对象可以发动。将该怪兽的效果直至回合结束时为止无效。然后，可将该对手怪兽移动至此卡连接端的对手怪兽区域。②：此卡攻击的伤害步骤开始时可以发动。将此卡连接端的怪兽全部除外。','\r',char(13)),'\n',char(10)),'','','是否移动那只怪兽？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35346968,'神之恩惠','①：只要此卡存在于魔法与陷阱区域域，我方每次抽牌时回复５００LP。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35371948,'淘气仙星・灯光舞台',replace(replace('①：作为此卡发动时的效果处理，可从牌组将１只“淘气仙星”怪兽加入手牌。\r\n②：１回合１次，以对手的魔法与陷阱区域的１张里侧表示卡为对象可以发动。只要此卡存在于场地区域，该里侧表示卡直至结束阶段为止不可发动，对手必须在结束阶段将该卡发动或送至墓地。\r\n③：每当自己场上的“淘气仙星”怪兽因战斗・效果给予对手伤害，就给予对手２００伤害。','\r',char(13)),'\n',char(10)),'是否从牌组把1只「淘气仙星」怪兽加入手牌？','限制发动','请选择对手的魔法与陷阱区域放置的1张卡','发动','送至墓地','','','','','','','','','','','');
INSERT INTO texts VALUES(35380371,'抵达冰结界的晶域',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：应对自己的“冰结界”怪兽的效果的发动，对手不可发动魔法・陷阱・怪兽的效果。\r\n②：怪兽被从额外牌组特殊召唤的情况下可以发动。挑选自己场上的１只“冰结界”怪兽，放回手牌或牌组。然后，可将自己或对手场上・墓地的１张卡放回牌组最下面。\r\n③：在自己的结束阶段发动。从额外牌组将卡名不同的３只“冰结界”怪兽出示给对手，或是将此卡破坏。','\r',char(13)),'\n',char(10)),'回到牌组','维持此卡','回到手牌','回到牌组','是否再选1张卡回到牌组？','是否把卡给对手观看？','','','','','','','','','','');
INSERT INTO texts VALUES(35394356,'达摩落师',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：去除自己场上的１个超量素材，以对手场上的１只表侧表示怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止变为０。此效果在对手回合中也可以发动。\r\n②：自己场上的超量怪兽去除超量素材发动效果的情况下，可将墓地的此卡除外作为去除１个超量素材的代替。此效果在此卡被送至墓地的回合不可使用。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35405755,'俱利伽罗天童',replace(replace('此卡不可通常召唤。\r\n仅可在将此回合在对手的怪兽区域发动过效果的、自己・对手场上的表侧表示怪兽全部解放的情况下特殊召唤。\r\n此卡名的②效果1回合仅可使用1次。\r\n①：此卡的攻击力上升为特殊召唤此卡而解放的怪兽数量×1500的数值。\r\n②：在自己的结束阶段，以对手墓地的1只怪兽为对象可以发动。将该怪兽特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35405756,'俱利伽罗天童',replace(replace('此卡不可通常召唤。\r\n仅可在将此回合在对手的怪兽区域发动过效果的、自己・对手场上的表侧表示怪兽全部解放的情况下特殊召唤。\r\n此卡名的②效果1回合仅可使用1次。\r\n①：此卡的攻击力上升为特殊召唤此卡而解放的怪兽数量×1500的数值。\r\n②：在自己的结束阶段，以对手墓地的1只怪兽为对象可以发动。将该怪兽特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35419032,'侵略的侵蚀感染','１回合１次，可从手牌及我方场上的表侧表示怪兽中，将１只冠有“邪蚀”之名的怪兽返回至持有者牌组并发动。从牌组将１只冠有“邪蚀”之名的怪兽加入手牌。','牌组检索','是否现在使用「侵略的侵蚀感染」的效果？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35429292,'妖精骑士','此卡因战斗被送入墓地时，由对手选择我方墓地的１张魔法卡，将该卡放置到我方牌组的最上面。','返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35448319,'除草兽','１回合１次，可释放１只我方场上的植物族怪兽并发动。选择对手场上的１张表侧表示卡牌并破坏。此外，此卡存在于墓地，且场上的表侧表示植物族怪兽被破坏时可发动。特殊召唤此卡。以此效果特殊召唤的此卡，从场上离开的场合从游戏中被除外。','破坏','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35464895,'命运标记','我方的怪兽因战斗被破坏并送入墓地时可发动。从手牌、牌组特殊召唤１只等级４或以下的“命运－英雄”怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35479109,'沙尘大飓风',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：以任意数量的被放置在自己的魔法与陷阱区域的卡为对象可以发动。将被放置的该卡和此卡放回持有者的手牌。然后，自己可依以此效果放回自己手牌的卡的数量从手牌放置魔法・陷阱卡。','\r',char(13)),'\n',char(10)),'是否把相同数量的卡从手牌放置？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35480699,'日全食之书','①：将场上的表侧表示怪兽全部改成里侧守备表示。在此回合的结束阶段，将对手场上的里侧守备表示怪兽全部改成表侧守备表示，然后，对手依以此效果改成了表侧守备表示的怪兽数量抽牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35486099,'宝玉的恩惠','最多可选择我方墓地的２只冠有“宝玉兽”之名的怪兽并发动。被选择的怪兽被视为永续魔法卡以表侧表示放置在我方的魔法与陷阱区域。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35487920,'直播☆双子 频道','此卡名的①②效果1回合仅可各使用1次。①：自己或对手的怪兽攻击宣言时，解放自己场上的1只“姬丝吉尔”怪兽或“璃拉”怪兽可以发动。该攻击无效化。②：自己・对手的结束阶段，以自己墓地的1只“姬丝吉尔”怪兽或“璃拉”怪兽为对象可以发动。将该怪兽放回牌组。自己场上不存在怪兽的情况下，也可不放回牌组而改为加入手牌。','','','回到牌组','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35488287,'寿炎星－李熊猫',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己发动“炎舞”魔法・陷阱卡的情况下可以发动。从手牌将此卡特殊召唤。然后，可以从自己的墓地将１只“寿炎星－李熊猫”以外的“炎星”怪兽特殊召唤。此效果发动后，直至回合结束时为止，自己仅可特殊召唤“炎星”怪兽。\r\n②：自己场上的“炎星”怪兽将被对手的效果破坏的情况下，作为代替可将自己场上的１张表侧表示的“炎舞”魔法・陷阱卡送至墓地。','\r',char(13)),'\n',char(10)),'','是否从墓地把「炎星」怪兽特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35494087,'疾行机人 玻璃骷髅',replace(replace('“疾行机人 玻璃骷髅”的③效果１回合仅可使用１次。\r\n①：在自己・对手的准备阶段，被从额外牌组特殊召唤的怪兽存在于对手场上的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：此卡不会因与被通常召唤的怪兽的战斗被破坏。\r\n③：因此卡的战斗造成的对自己的战斗伤害由对手代替承受。\r\n④：自己场上有“疾行机人”怪兽以外的表侧表示怪兽存在的情况下，此卡将被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35498188,'动作魔法－双重侧倾',replace(replace('①：可舍弃１张手牌并发动。我方场上的怪兽，在此回合因战斗破坏了对手怪兽的场合，可连续再进行１次攻击。\r\n②：此卡存在于墓地的场合，在我方准备阶段，可从手牌舍弃１张魔法卡并发动。将此卡盖牌至我方的魔法＆陷阱卡区。此效果在此卡被送入墓地的回合不可发动。','\r',char(13)),'\n',char(10)),'此卡放置','是否继续攻击？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35514096,'王者不列颠号',replace(replace('①：此卡战斗破坏对手怪兽的情况下，从以下效果中选择1个发动。\r\n●此卡可继续再攻击仅1次。\r\n●以场上1张里侧表示的卡为对象发动。将该里侧表示卡破坏。\r\n●将1只“分机衍生物”（机械族・光・星4・攻/守1200）特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'选择一个效果发动','只有1次可以继续攻击','选择场上放置的1张卡破坏','在自己场上把1只「分机衍生物」特殊召唤','','','','','','','','','','','','');
INSERT INTO texts VALUES(35514097,'分机衍生物','由“罗德不列颠号”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35537251,'燃烧拳斗士 影击',replace(replace('此卡名的效果１回合仅可使用１次。\r\n①：此卡存在于手牌的情况下可以发动。去除自己场上的“燃烧拳斗士”超量怪兽的１个超量素材，将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35537860,'精神同调波','只有在我方场上有表侧表示的同步怪兽存在的场合才可发动此卡。破坏对手场上的１只怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35539880,'正统的血统','①：可以我方墓地中的１只通常怪兽为对象发动此卡。以攻击表示特殊召唤该怪兽。此卡离开场上时，破坏该怪兽。该怪兽离开场上时，破坏此卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35544402,'闪烁星圣',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：以自己场上的1只“星圣”怪兽为对象可以发动。该怪兽的等级上升最多2。\r\n②：此卡存在于墓地的情况下，从自己的墓地将1只“星圣”怪兽除外可以发动。将此卡加入手牌。','\r',char(13)),'\n',char(10)),'等级上升','加入手牌','等级上升1星','等级上升2星','','','','','','','','','','','','');
INSERT INTO texts VALUES(35546670,'星遗物所刻印的伤痕','①：场上的“机界骑士”怪兽的攻击力・守备力上升300。②：1回合1次，从手牌将1只“机界骑士”怪兽或1张“星遗物”卡舍弃可以发动。自己从牌组抽1张。③：从自己墓地及自己场上的表侧表示怪兽中，将8种“机界骑士”怪兽各1只除外可以发动。对手的手牌・额外牌组的卡全部送至墓地。','抽牌','全部送至墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35550352,'对击斗魂开战！',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：以自己场上的1只“对击斗魂”怪兽为对象可以发动。从牌组将属性与该怪兽不同的1只“对击斗魂”怪兽加入手牌。\r\n②：自己场上的“对击斗魂”怪兽将被战斗・效果破坏的情况下，作为代替可出示手牌的1只“对击斗魂”怪兽。\r\n③：在自己的结束阶段，自己场上存在2只以上“对击斗魂”怪兽的情况下可以发动。从牌组将1张“对击斗魂”陷阱卡放置在自己场上。','\r',char(13)),'\n',char(10)),'检索','放置','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35552985,'契印魔镌・赞圣颂',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己场上的表侧表示怪兽，不存在的情况下或仅有恶魔族・光属性怪兽的情况下可以发动。将１只“魔镌衍生物”（恶魔族・光・星１・攻／守０）特殊召唤至自己场上。此回合，自己仅可用恶魔族怪兽进行攻击宣言。\r\n②：此卡存在于墓地的状态下，自己场上的表侧表示“魔镌”怪兽因对手的效果被破坏的情况下可以发动。将此卡放置在自己场上。','\r',char(13)),'\n',char(10)),'特殊召唤','放置','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35552986,'魔镌衍生物','「契印魔镌・赞圣颂」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35561352,'源质的神击','①：怪兽的效果・魔法・陷阱卡发动时，从自己额外牌组将１只表侧表示的“源质”怪兽除外可以发动。将该发动无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35563539,'精灵之镜','将针对单一玩家的魔法卡效果移转至其他玩家。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35565537,'女武神','在神话里出现的战斗天使，用手中的枪处以天罚。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35569555,'凶教导之圣告','此卡名的卡１回合仅可发动１张。①：作为此卡发动时的效果处理，可适用以下效果。●从牌组将１只“教导”仪式怪兽或１张“教导”仪式魔法卡加入手牌。对手场上存在怪兽的情况下，进而可再从牌组将１张“教导”卡加入手牌。②：１回合１次，自己场上存在“教导”仪式怪兽的情况下可以发动。确认自己或对手的额外牌组，挑选其中１只怪兽送至墓地。','是否从牌组把「教导」仪式卡加入手牌？','是否再从牌组把「教导」卡加入手牌？','','把自己的额外牌组确认','把对手的额外牌组确认','','','','','','','','','','','');
INSERT INTO texts VALUES(35577420,'光之回弹','每次因冠有“光道”之名怪兽的效果卡牌从我方牌组被送入墓地，从对手牌组上方将１张卡牌从游戏中除外。','对方卡组上面1张卡从游戏中除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35595518,'连接山猫屠杀者',replace(replace('①：自己场上不存在怪兽的情况下，此卡可从手牌特殊召唤。\r\n②：1回合1次，舍弃最多2张手牌，依其数量以场上的魔法・陷阱卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35606858,'长世国王恶魔',replace(replace('恶魔族怪兽2只\r\n此卡的控制者在每个自己的准备阶段，支付500LP或将此卡破坏。\r\n此卡的①②效果在同一连锁上各仅可发动1次。\r\n①：自己支付了LP的情况下可以发动。从牌组将1只攻击力或守备力与支付的数值相同的恶魔族怪兽送至墓地。\r\n②：有恶魔族怪兽被送至自己墓地的情况下可以发动。掷1次骰子，根据掷出的数字对其中1只适用相应效果。\r\n●1：加入手牌。\r\n●2～5：放回牌组。\r\n●6：特殊召唤。','\r',char(13)),'\n',char(10)),'恶魔族怪兽从牌组送至墓地','掷1次骰子','是否维持「长世国王恶魔」？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35614780,'光与升华之龙',replace(replace('此卡名的①②③效果１回合仅可各使用１次。\r\n①：从额外牌组将１只龙族・等级８怪兽除外可以发动。从手牌将此卡特殊召唤。此回合，自己仅可特殊召唤龙族怪兽。\r\n②：在自己的主要阶段可以发动。将自己的手牌・场上的怪兽作为融合素材，将１只融合怪兽融合召唤。\r\n③：对手怪兽攻击宣言时可以发动。此卡的攻击力・守备力下降５００，该对手怪兽的攻击力下降１５００。','\r',char(13)),'\n',char(10)),'手牌特殊召唤','融合召唤','攻守下降','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35618217,'月光彩雏',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：1回合1次，从牌组・额外牌组将1只“月光”怪兽送至墓地可以发动。此回合，要将表侧表示的此卡作为融合素材的情况下，此卡可视为被送至墓地的该怪兽的同名卡。\r\n②：此卡因效果被送至墓地的情况下，以自己墓地的1张“融合”为对象可以发动。将该卡加入手牌。\r\n③：此卡被除外的情况下可以发动。此回合，对手在战斗阶段中不可发动效果。','\r',char(13)),'\n',char(10)),'代替素材','墓地「融合」加入手牌','对手在战斗阶段中不可把效果发动','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35618486,'侵邪蚀的先锐','我方场上的此卡被送入墓地时，选择场上的１只仪式・融合・同步怪兽并破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35622739,'宝石骑士・石英',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：对手场上存在怪兽的情况下，从手牌将此卡舍弃可以发动。从牌组将1张“结合”永续魔法卡放置在自己场上。此回合，自己从额外牌组仅可特殊召唤“宝石骑士”怪兽。\r\n②：此卡成为融合召唤的素材，被送至墓地的情况下或被除外的情况下可以发动。从自己墓地将“宝石骑士・石英”以外的1只“宝石骑士”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35629124,'子龙',replace(replace('“子龙”的效果１回合只可使用１次，发动此效果的回合，我方只可特殊召唤龙族怪兽，不能进行战斗阶段。\r\n①：此卡被送入墓地的场合可发动。从手牌中特殊召唤１只龙族怪兽。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35631584,'星圣的星痕','①：1回合1次，“星圣”超量怪兽被特殊召唤至自己场上时可以发动。自己抽1张。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35638627,'异虫军神','此卡不可特殊召唤。此卡因战斗破坏的怪兽的效果被无效化。此卡因战斗破坏对手怪兽时可发动。此卡仅可再持续攻击１次。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35645105,'无限起动 收割机','此卡名的①②效果１回合仅可各使用１次。①：此卡召唤・特殊召唤成功的情况下可以发动。从牌组将１只“无限起动 收割机”以外的“无限起动”怪兽加入手牌。②：以自己场上此卡以外的１只机械族怪兽为对象可以发动。该怪兽和此卡直至回合结束时为止，变为该２只原本等级合计的等级。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35659410,'青之眼的幻出','此卡名的卡１回合仅可发动１张。①：此卡也可通过出示手牌的１只“青眼白龙”来发动。该情况下，从手牌将１只怪兽特殊召唤。②：１回合１次，以自己场上的１只表侧表示怪兽为对象可以发动。将该表侧表示怪兽放回持有者的手牌。然后，可根据放回手牌的卡的原本卡名适用以下效果。●“青眼白龙”：从手牌将１只怪兽特殊召唤。●该卡以外：从手牌将１只“青眼”怪兽特殊召唤。','是否展示「青眼白龙」并从手牌特殊召唤怪兽？','是否从手牌特殊召唤怪兽？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35686187,'断头台的惨剧','对手场上以表侧攻击表示存在的怪兽，其表示形式变为表侧守备表示时可发动。破坏对手场上所有以守备表示存在的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35686188,'断头台的惨剧','对手场上以表侧攻击表示存在的怪兽，其表示形式变为表侧守备表示时可发动。破坏对手场上所有以守备表示存在的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35697544,'斗气炎斩剑',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：可从以下效果中选择１个发动。\r\n●从牌组将除“斗气炎斩剑”以外的、１张记载有“炎之剑士”卡名的卡加入手牌。\r\n●自己的战士族・炎属性怪兽进行战斗的攻击宣言时，以场上的１张卡为对象可以发动。将该卡破坏。\r\n●对手发动以自己场上的、“炎之剑士”或记载有该卡名的怪兽为对象的效果时可以发动。将该效果无效。','\r',char(13)),'\n',char(10)),'检索有「炎之军刀」的卡名记述的卡','破坏场上的卡','无效对手的效果','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35705817,'幽合－幽灵结合',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：将自己场上的不死族怪兽作为融合素材，将1只融合怪兽融合召唤。自己的LP少于对手的情况下，也可将自己手牌・牌组・墓地的最多1只不死族怪兽除外并作为融合素材。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35712107,'巨大的怪鸟','罕见的大鸟。会从空急降而下发动攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35726888,'愚蠢副葬',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从牌组将1张魔法・陷阱卡送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35752363,'朱雀','“赤剑之莱蒙多斯”＋“炎之魔神”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35756798,'最终交错',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：在同步怪兽被送至自己墓地的自己回合，以自己场上的１只同步怪兽为对象可以发动。此回合，该怪兽在１次战斗阶段中可攻击２次。以原本卡名包含“战士”、“同步士”、“星尘”中任一的同步怪兽为对象来发动此卡的情况下，进而可挑选自己墓地的１只同步怪兽，对象怪兽依其攻击力来上升攻击力。','\r',char(13)),'\n',char(10)),'','是否选怪兽以上升攻击力？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35762283,'凡骨的意志','①：自己在自己的抽牌阶段抽牌时，该抽到的卡为通常怪兽的情况下，将该怪兽出示给对手可以发动。自己抽１张。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35763582,'月光银狗',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡因效果被送至墓地的情况下可以发动。从牌组将“月光银狗”以外的1只“月光”怪兽特殊召唤。只要以此效果特殊召唤的怪兽以表侧表示存在于自己场上，自己从额外牌组仅可特殊召唤“月光”怪兽。\r\n②：魔法・陷阱卡的效果在场上发动时，从自己墓地将此卡和1只“月光”融合怪兽除外可以发动。将该发动无效。','\r',char(13)),'\n',char(10)),'特殊召唤','无效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35770983,'恐龙摔跤手・武术甲龙',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：在自己・对手回合中，其他的自己的“恐龙摔跤手”怪兽与对手怪兽进行战斗的伤害计算时，将手牌・场上的此卡送至墓地可以发动。该自己的怪兽不会因该战斗被破坏，该对手的怪兽的攻击力在伤害步骤结束时变为一半。\r\n②：在此卡从场上被送至墓地的回合的结束阶段可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35772782,'编号67 天堂骰子锤手',replace(replace('等级5怪兽×2只以上\r\n①：1回合1次，在自己的主要阶段1，去除此卡的2个超量素材可以发动。双方各掷2次骰子。掷出的数字合计较大的玩家直至下个回合结束时为止，不可发动怪兽的效果，不可攻击宣言。\r\n②：持有超量素材的此卡存在于怪兽区域，自己或对手掷骰子的情况下，1回合仅1次，可将其中1个数字作为7适用。','\r',char(13)),'\n',char(10)),'','是否修改骰子结果？','请选择要修改的骰子序号','「编号6７ 平行骰子天堂锤手」效果适用中','','','','','','','','','','','','');
INSERT INTO texts VALUES(35778533,'切勿踏足白森之地',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己场上存在等级６以上的幻想魔族或魔法师族怪兽的情况下，以对手场上的１张卡为对象可以发动。将该卡破坏。\r\n②：此卡为发动怪兽的效果被送至墓地的情况下可以发动。将此卡放置在自己场上。','\r',char(13)),'\n',char(10)),'破坏卡片','放置','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35781051,'秘仪之力Ⅲ－女皇',replace(replace('①：此卡召唤・反转召唤・特殊召唤的情况下发动。掷1次硬币，根据掷出的正反，此卡获得以下效果。\r\n●正面：对手将怪兽通常召唤时可以发动。从手牌将1只“秘仪之力”怪兽特殊召唤。\r\n●反面：每当对手将怪兽通常召唤则发动。挑选1张自己的手牌送至墓地。','\r',char(13)),'\n',char(10)),'投掷硬币','特殊召唤','手牌送墓','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35787450,'无尽恐惧','①：在场上的所有“幽狱时钟塔”上各放2个时钟计数物。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35798491,'黑暗主教恶魔','此卡的控制者每次在自己的准备阶段支付５００点LP。当我方场上冠有“恶魔”之名的怪兽卡成为对手所控制的卡牌的效果对象，在处理效果时投掷１次骰子。掷出１、３、６的场合，令该效果无效并将其破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35800511,'超重武者装魂 爆裂手甲','①：在自己的主要阶段，以自己场上的１只“超重武者”怪兽为对象可以发动。从自己的手牌・场上，将此怪兽视为守备力上升４００的装备卡，装备于该自己的怪兽。②：自己的墓地不存在魔法・陷阱卡的情况下，自己的守备表示“超重武者”怪兽与对手怪兽进行战斗的伤害步骤开始时到伤害计算前为止，从手牌将此卡送至墓地可以发动。进行该战斗的自己的怪兽的守备力直至回合结束时为止，变为原本守备力的两倍。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35803249,'人造人－念力领主',replace(replace('此卡无法通常召唤。\r\n仅将自己场上１只表侧表示的“人造人－念力震慑者”送至墓地时可特殊召唤。\r\n①：只要此卡存在于怪兽区域，双方场上的陷阱卡就不可发动效果，场上陷阱卡的效果失效。\r\n②：１个回合１次，可以在自己的主要阶段发动。破坏场上所有表侧表示的陷阱卡，给对手的伤害值为破坏的数量×３００。','\r',char(13)),'\n',char(10)),'表侧的陷阱卡全部破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35809262,'元素－英雄 火焰翼人',replace(replace('“元素-英雄 羽毛人”＋“元素-英雄 爆炎女郎”\r\n此卡仅可以融合召唤方式特殊召唤。①：此卡战斗破坏怪兽并将其送至墓地的情况下发动。给予对手该怪兽的原本攻击力数值的伤害。','\r',char(13)),'\n',char(10)),'伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35809263,'元素－英雄 火焰翼人',replace(replace('“元素-英雄 羽毛人”＋“元素-英雄 爆炎女郎”\r\n此卡仅可以融合召唤方式特殊召唤。①：此卡战斗破坏怪兽并将其送至墓地的情况下发动。给予对手该怪兽的原本攻击力数值的伤害。','\r',char(13)),'\n',char(10)),'伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35815783,'魔键施解',replace(replace('此卡名的卡１回合仅可发动１张，此卡名的③效果１回合仅可使用１次。\r\n①：作为此卡发动时的效果处理，可从牌组将１只“魔键”怪兽加入手牌。\r\n②：只要此卡存在于场地区域，衍生物以外的自己场上的通常怪兽１回合各仅１次，不会因战斗・效果被破坏。\r\n③：在自己的主要阶段可以发动。从牌组将１张“魔键－马夫提亚”加入手牌。然后挑选１张手牌放回牌组最下面。','\r',char(13)),'\n',char(10)),'是否从牌组把1只「魔键」怪兽加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35817848,'同步传送',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：在自己・对手的主要阶段可以发动。进行１只同步怪兽的同步召唤。\r\n②：在自己的主要阶段，从墓地将不是在此回合被送至墓地的此卡除外，以自己墓地的１只同步怪兽为对象可以发动。将该怪兽放回额外牌组。然后，自己抽１张。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35818851,'不知火的武士','此卡名的①②效果１回合仅可各使用１次。①：将自己墓地的１只不死族怪兽除外可以发动。此卡的攻击力直至回合结束时为止上升６００，此回合，此卡与怪兽进行战斗的情况下，该怪兽将在伤害计算后被除外。此效果在对手回合中也可以发动。②：此卡被除外的情况下，以“不知火的武士”以外的自己墓地的１只“不知火”怪兽为对象可以发动。将该怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35834119,'灯鱼',replace(replace('协调＋协调以外的怪兽１只以上\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡作为同步素材被送至墓地的情况下可以发动。将２只“灯衍生物”（鱼族・炎・星２・攻／守０）特殊召唤至自己场上。此回合，自己从额外牌组仅可特殊召唤鱼族怪兽。\r\n②：自己场上存在鱼族同步怪兽的情况下，将墓地的此卡除外，以场上的１张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'特殊召唤衍生物','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35834120,'灯衍生物','由“灯鱼”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35842855,'炎灵神派罗雷克斯','此卡不可通常召唤。仅限我方墓地的炎属性怪兽为５只的场合可特殊召唤。此卡特殊召唤成功时，可选择对手场上的１只怪兽并发动。破坏被选择的怪兽，且双方均受到相当于被破坏怪兽原本攻击力一半的伤害。“炎灵神派罗雷克斯”的此效果１回合只可使用１次。此卡从场上离开的场合，跳过下一次我方回合的战斗阶段。','破坏并伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35844557,'剑极・雷热涡炉',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次，且②效果1回合仅可使用1次。\r\n①：自己场上或墓地存在“雷热涡炉”怪兽的情况下，此卡可从手牌特殊召唤。以此方法特殊召唤过的余下本回合，自己从额外牌组仅可特殊召唤阶级4的超量怪兽。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从牌组将1只炎族・光属性怪兽加入手牌。','\r',char(13)),'\n',char(10)),'手牌特殊召唤','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35848254,'光子领导','以攻击表示从手牌特殊召唤１只等级４或以下的光属性怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35866404,'大地奔兽','对手场上存在超量怪兽的场合，可从手牌以攻击表示特殊召唤此卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35870016,'刚鬼必杀技','此卡名的卡1回合仅可发动1张。①：以自己场上的1只“刚鬼”连接怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止，上升相当于其连接标记数量×1000的数值，此回合，该怪兽攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。此卡发动后，直至回合结束时为止自己仅可用“刚鬼”怪兽攻击宣言。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35871958,'鬼计嘉年华',replace(replace('连接怪兽以外的“鬼计”怪兽１只\r\n在要将此卡连接召唤的情况下，也可将自己场上的里侧表示“鬼计”怪兽作为连接素材。此卡名的②效果１回合仅可使用１次。①：只要场地区域存在“鬼计”卡，自己的“鬼计”怪兽可直接攻击。②：对手怪兽攻击宣言时，解放此卡可以发动。从牌组将１只“鬼计”怪兽以里侧守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35877582,'伟魔圣灵 法典之爱华斯',replace(replace('“伟魔”怪兽＋魔法师族怪兽\r\n此卡名的①效果1回合仅可使用1次。①：在自己・对手的主要阶段，以场上1只此卡以外的表侧表示怪兽为对象可以发动。将自己场上的此卡视为装备卡装备于该怪兽。以此效果将此卡装备于对手怪兽的情况下，装备怪兽的效果不可发动，且获得其控制权。②：装备此卡的怪兽的攻击力・守备力上升1000。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35884610,'超级运动员强力球衣',replace(replace('仅限装备“超级运动员”怪兽。\r\n①：装备怪兽的攻击力，守备力上升１０００，且装备怪兽与对手怪兽进行战斗的场合，给予对手的战斗伤害变成２倍。\r\n②：因装备怪兽的攻击破坏怪兽的场合可发动。此战斗阶段中，装备怪兽仅可再进行１次攻击。\r\n③：在我方准备阶段发动。除外装备怪兽。\r\n④：因将装备怪兽返回至手牌而导致此卡被送入墓地的场合可发动。将此卡返回至手牌。','\r',char(13)),'\n',char(10)),'连续攻击','返回手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35886170,'隆隆隆格布林德伯格',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤时可以发动。从自己手牌・牌组・墓地将战士族以外的1只“隆隆隆”怪兽特殊召唤。此卡为攻击表示的情况下，此卡进而变为守备表示。此效果发动后，直至回合结束时为止自己从额外牌组仅可特殊召唤超量怪兽。\r\n②：作为超量素材的此卡为发动超量怪兽的效果被去除的情况下可以发动。从牌组将1只“怒怒怒”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35906693,'闪光抽牌',replace(replace('①：通过持续公开在自己的抽牌阶段以通常抽牌抽到的此卡，在该回合的主要阶段１，以自己场上的１只“希望皇霍普”超量怪兽为对象，可从以下效果中选择１个发动。\r\n●从牌组・额外牌组挑选任意数量卡名不同的“ZEXAL兵器”怪兽，视为装备卡装备于对象怪兽。\r\n●将１只卡名与对象的自己怪兽不同的“希望皇霍普”超量怪兽重叠在该怪兽上面，视为超量召唤从额外牌组特殊召唤。','\r',char(13)),'\n',char(10)),'是否要持续公开「闪光抽牌」？','装备','超量召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35911108,'火箭炮指挥官',replace(replace('①：只要此卡存在于怪兽区，我方场上此卡以外的电子界族怪兽的攻击力・守备力上升３００。\r\n②：１回合１次，可解放我方场上的１只电子界族怪兽，并以对手场上的１只表侧表示怪兽为对象发动。破坏该怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35950025,'银河骑士','①：自己场上有“光子”怪兽或“银河”怪兽存在的情况下，此卡无需解放即可召唤。②：以此卡的①方法召唤成功的情况下，以自己墓地的1只“银河眼光子龙”为对象发动。此卡的攻击力直至回合结束时为止下降1000，将对象怪兽以守备表示特殊召唤。','不用解放作召唤','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35952884,'流天类星龙',replace(replace('同步怪兽的协调＋协调以外的同步怪兽2只以上\r\n此卡仅可以同步召唤方式特殊召唤。\r\n①：此卡在1次战斗阶段中可攻击的次数最多为其同步素材的怪兽中协调以外的怪兽数量。\r\n②：1回合1次，魔法・陷阱・怪兽的效果发动时可以发动。将该发动无效并破坏。\r\n③：表侧表示的此卡从场上离开时可以发动。从额外牌组将1只“流星龙”特殊召唤。','\r',char(13)),'\n',char(10)),'效果无效并破坏','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35952885,'流天类星龙',replace(replace('同步怪兽的协调＋协调以外的同步怪兽2只以上\r\n此卡仅可以同步召唤方式特殊召唤。\r\n①：此卡在1次战斗阶段中可攻击的次数最多为其同步素材的怪兽中协调以外的怪兽数量。\r\n②：1回合1次，魔法・陷阱・怪兽的效果发动时可以发动。将该发动无效并破坏。\r\n③：表侧表示的此卡从场上离开时可以发动。从额外牌组将1只“流星龙”特殊召唤。','\r',char(13)),'\n',char(10)),'效果无效并破坏','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35956022,'酸雨','场上的地属性怪兽攻击力下降５００点，守备力上升４００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35960413,'高邱比特','此卡名的①②效果１回合仅可各使用１次。①：自己场上的怪兽仅有守备力６００的怪兽的情况下可以发动。从手牌将此卡特殊召唤。②：舍弃１张手牌，以自己场上１只天使族・光属性怪兽和场上１只表侧表示怪兽为对象可以发动。自己的该怪兽的等级直至回合结束时为止变为与另１只怪兽的等级相同。此效果在对手回合中也可以发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35975813,'屠杀国王恶魔','若我方场上没有冠有“恶魔”之名的怪兽卡存在，不可召唤・反转召唤此卡。此卡的控制者每次在自己的准备阶段支付８００点LP。当此卡成为对手所控制的卡牌的效果对象，在处理效果时投掷１次骰子。掷出２、５的场合，令该效果无效并将其破坏。此卡通过战斗而破坏的效果怪兽的效果无效。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35984222,'超魔神 本我','此卡被卡的效果破坏送往墓地的情况下，在下个回合的准备阶段时发动。将此卡从墓地特殊召唤，将此卡以外的自己场上存在的怪兽全部破坏。只要此卡表侧表示存在于场上，自己不可通常召唤・反转召唤・特殊召唤怪兽。在自己场上仅可以表侧表示存在１张“超魔神 本我”。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35989913,'永远之绊',replace(replace('此卡名在规则上也视为“超量”卡。\r\n此卡名的卡1回合仅可发动1张。\r\n①：作为此卡发动时的效果处理，可从自己墓地将1只“编号39 希望皇霍普”特殊召唤。该怪兽的攻击力上升相当于自己墓地光属性的“霍普”超量怪兽的攻击力合计的数值。\r\n②：以原本的属性为光属性的、自己的“霍普”超量怪兽的攻击破坏对手怪兽时可以发动。该自己的怪兽的攻击力下降1000，该怪兽可继续攻击。','\r',char(13)),'\n',char(10)),'发动','继续攻击','是否特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(35998832,'溟界之漠－浊哈','此卡名的①②效果1回合仅可各使用1次。①：此卡从场上被送至墓地的情况下，或从墓地特殊召唤成功的情况下可以发动。对手从牌组抽1张，自己从牌组将1只“溟界之漠-浊哈”以外的“溟界”怪兽加入手牌。然后，双方玩家各挑选1张手牌送至墓地。②：此卡存在于墓地的情况下，将1张手牌送至墓地可以发动。将此卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36006208,'彼岸的沉溺','①：将自己场上的2只表侧表示的“彼岸”怪兽送至墓地，以场上的最多3张卡为对象可以发动。将该卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36010310,'溟界之滓－努泸','此卡名的①②效果1回合仅可各使用1次。①：从手牌将此卡送至墓地可以发动。从牌组将1只爬虫类族・暗属性怪兽送至墓地。②：自己场上没有怪兽存在的情况下，或有“溟界”怪兽存在的情况下可以发动。从墓地将此卡特殊召唤。以此效果特殊召唤的此卡离开场上的情况下，将其除外。只要以此效果特殊召唤的此卡以表侧表示存在于怪兽区域，自己仅可特殊召唤爬虫类族怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36016907,'杰克麦瓜','此卡名的①②效果1回合仅可各使用1次。①：从手牌将1只不死族怪兽舍弃可以发动。从手牌将此卡特殊召唤。②：在对手的主要阶段，以自己或对手墓地的1只不死族怪兽为对象可以发动。将该怪兽特殊召唤至自己场上。然后，直至结束阶段为止将表侧表示的此卡除外。以此效果特殊召唤的怪兽离开场上的情况下，将其除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36021814,'白骨王','①：此卡原本的攻击力变为相当于自己墓地“白骨王”、“白骨”的数量×１０００的数值。②：此卡因战斗被破坏并被送至墓地时，从自己的墓地将１只此卡以外的、“白骨王”或“白骨”除外可以发动。将此卡特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36029076,'地狱大蜈蚣','对手场上存在有怪兽，且我方场上不存在怪兽的场合，此卡可无须释放进行召唤。以此方法召唤的此卡其原本攻击力变成１３００。','不解放怪兽进行召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36033786,'电子界男巫','①：1回合1次，以对手场上1只攻击表示的怪兽为对象可以发动。将该怪兽改成守备表示。以此效果将其改成了守备表示的余下回合，自己的怪兽仅可攻击对象怪兽，自己的电子界族怪兽攻击对象的守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36039163,'企鹅骑士','此卡因对手的卡牌效果从我方牌组被送入墓地时，我方墓地的卡牌全部返回至牌组。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36042004,'小角龙','①：此卡因效果被破坏并被送至墓地的情况下发动。从牌组将1只等级4以下的恐龙族怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36042825,'一击魔杖','仅限装备魔法师族怪兽。装备怪兽的攻击力上升８００点。此外，装备怪兽进行战斗并计算伤害后，可破坏此卡并从牌组抽取１张卡牌。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36045450,'魔导合作','①：我方场上有２只以上攻击表示的魔法师族怪兽存在的场合，可以其中１只为对象发动此卡。该怪兽的攻击力变为３０００，直到回合结束时。此卡发动后，除该怪兽以外的魔法师族怪兽不可进行攻击，直到回合结束时。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36046926,'森罗的水先 叶子','此卡召唤成功时，可翻阅我方牌组最上方的２张卡牌。翻阅的卡牌中有植物族怪兽的场合，将那些怪兽全部送入墓地。剩下的卡牌依照喜欢的顺序返回至牌组最下方。此外，牌组的此卡因卡牌效果被翻阅并送入墓地的场合，可选择场上的１只怪兽破坏。','确认牌组','请选择要翻开的数量','破坏','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36076683,'编号73 激泷神 邃渊飞溅',replace(replace('水属性等级５怪兽×２\r\n①：在每个自己・对手回合中１次，去除此卡的１个超量素材可以发动。此卡的攻击力直至对手回合结束时为止变为两倍。此效果发动后，直至回合结束时为止，此卡给予对手的战斗伤害变为一半。','\r',char(13)),'\n',char(10)),'攻击变成2倍','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36088082,'公牛剑士','可于此卡进行向对手怪兽的攻击宣告时发动。战斗中向各个玩家造成的战斗伤害变为０，在伤害计算后破坏对手怪兽。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36092504,'铳剑处刑',replace(replace('此卡名的卡1回合仅可发动1张。①：根据自己场上・墓地的“枪管”怪兽的种类，适用以下效果。自己场上有攻击力3000以上的怪兽存在的情况下，应对此卡的发动对手不可发动效果。\r\n●融合：挑选对手场上的1只怪兽除外。\r\n●同步：从对手的额外牌组随机将里侧表示的3张卡除外。\r\n●超量：挑选对手场上的1张魔法・陷阱卡除外。\r\n●连接：从对手的墓地挑选最多3张卡除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36099130,'伟魔贤者 绝火之琐罗亚',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：以自己场上的1只“伟魔”怪兽为对象可以发动。从额外牌组将1只“伟魔”怪兽视为装备魔法卡装备于对象怪兽。\r\n②：此卡被装备上“伟魔”怪兽卡的情况下可以发动。从自己手牌・墓地将“伟魔贤者 绝火之琐罗亚”以外的1只魔法师族・等级4怪兽以守备表示特殊召唤。以此效果特殊召唤的怪兽的效果无效化。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36099620,'正义世界','每次从我方牌组将卡牌送入墓地，就放置１个闪光计数物于此卡。场上冠有“光道”之名怪兽的攻击力上升此卡的闪光计数物数量×１００点。此外，此卡因卡牌效果被破坏的场合，移除此卡的２个闪光计数物作为代替。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36100154,'亚马逊的斗志','冠有“亚马逊”之名的怪兽攻击攻击力高于自身的怪兽的场合，攻击怪兽的攻击力在伤害计算时上升１０００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36107810,'夜末巫师','①：此卡特殊召唤成功时，最多可以对手墓地的２张卡牌为对象发动。将该卡牌除外。','除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36111775,'灵摆停顿','①：自己的额外牌组存在３种以上的表侧灵摆怪兽的情况下可以发动。自己抽２张。此卡发动后，直至回合结束时为止，自己不可从牌组将卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36114945,'垂冰之魔妖－雪女',replace(replace('不死族怪兽２只以上\r\n此卡名的②③效果１回合仅可各使用１次。\r\n①：“垂冰之魔妖－雪女”在自己场上仅可有１张以表侧表示存在。\r\n②：此卡特殊召唤的情况下，以对手场上的１只效果怪兽为对象可以发动。将该怪兽的效果无效。\r\n③：在自己・对手回合中，将墓地的此卡除外可以发动。将自己的墓地・除外状态的１只不死族同步怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36119641,'太空翻车鱼','漂浮在广阔银河的宇宙翻车鱼。它是被发现于阿尔法德４的超文明遗迹中的活化石。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36121917,'怪兽蛋','全身包裹蛋壳的神秘战士。会甩出蛋壳进行攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36148308,'命之奇迹',replace(replace('仅可装备于地属性同步怪兽。\r\n①：仅在装备怪兽与对手怪兽进行战斗的伤害计算时，该对手怪兽的攻击力下降１５００。\r\n②：１回合１次，怪兽的表示形式被变更的情况下，以场上的１张卡为对象可以发动。将该卡破坏。\r\n③：此卡从魔法与陷阱区域被送至墓地的情况下，解放自己场上的１只“动力工具”同步怪兽可以发动。从额外牌组将１只“生命激流龙”视为同步召唤来特殊召唤。','\r',char(13)),'\n',char(10)),'场上1张卡破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36151751,'菊石骑士','从遥远过去就守护大海不受外敌侵扰的菊石战士。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36183881,'威风魔灵・龙卷','①：解放自己场上的１只魔法师族・风属性怪兽，以对手场上的１只怪兽为对象可以发动。将该怪兽除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36187051,'岩乐团之美技－磷钇吉他手','此卡名的①②效果１回合仅可各使用１次。①：此卡被送至墓地的情况下，以自己墓地的１只“岩乐团之美技－磷钇吉他手”以外的岩石族怪兽为对象可以发动。将该怪兽加入手牌。然后挑选１张手牌放在牌组最上面。②：此卡从场上・墓地被除外的情况下可以发动。从牌组将１只岩石族怪兽送至墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36197902,'星遗物带来的崩界','此卡名的①②效果1回合仅可各使用1次。①：从自己手牌・墓地及自己场上的表侧表示怪兽中，将1只“星遗物”怪兽除外，以场上1只连接怪兽为对象可以发动。该怪兽的攻击力上升相当于除外怪兽原本攻击力的数值。②：此卡存在于墓地的状态下，自己场上的连接怪兽因战斗或对手的效果被破坏的情况下，将此卡除外可以发动。从自己墓地挑选1只电子界族连接怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36205132,'空牙团的传令 菲萝','此卡名的①②效果1回合仅可各使用1次。①：在自己的主要阶段可以发动。从手牌特殊召唤“空牙团的传令 菲萝”以外的1只“空牙团”怪兽。②：此卡已经存在于怪兽区域的状态下，且此卡以外的“空牙团”怪兽被特殊召唤至自己场上的情况下，以自己墓地的1只“空牙团”怪兽为对象可以发动。以守备表示形式将该怪兽特殊召唤。以此效果特殊召唤的怪兽从场上离开的情况下放回持有者牌组的最下面。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36211150,'比特创机','在电子空间找到的新种类。其信息量很少。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36218106,'寡默的念力管理员',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次，且②效果1回合仅可使用1次。\r\n①：自己场上存在“寡默的念力管理员”以外的念动力族怪兽的情况下，此卡可从手牌以守备表示特殊召唤。\r\n②：从自己墓地将此卡和1只念动力族怪兽除外，以场上的1只表侧表示怪兽为对象可以发动。将该怪兽直至结束阶段为止除外。','\r',char(13)),'\n',char(10)),'特殊召唤','除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36224040,'升阶魔法－ZEXAL之力','此卡名的②效果１回合仅可使用１次。①：以自己场上的１只超量怪兽为对象可以发动。将阶级比该自己怪兽高１的１只“希望皇霍普”怪兽或“ZEXAL兵器”怪兽重叠在对象怪兽上面，视为超量召唤从额外牌组特殊召唤，从牌组挑选１只“ZEXAL兵器”怪兽或“ZEXAL从者”怪兽放在牌组最上面。②：自己的LP比对手少２０００以上的情况下，将墓地的此卡除外可以发动。自己从牌组抽１张。','','','请选择要放置在牌组最上面的卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36227804,'咒仪・野兽','①：此卡召唤成功时，以自己墓地的１只等级４以下的“咒仪”怪兽为对象可以发动。以守备表示形式将该怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36239585,'鬼计的妖精','仅在自己场上有“鬼计”怪兽存在的情况下，此卡才可以表侧表示召唤。①：在自己的主要阶段可以发动。将此卡改成里侧守备表示（１回合仅１次）。②：此卡反转时，以自己墓地的１张“鬼计”卡为对象可以发动。将该卡放置在自己场上。该卡离开场上的情况下，将其除外。然后，可挑选对手场上的表侧表示怪兽改成里侧守备表示，数量最多为被放置在自己场上的卡的数量。','','','是否选对手怪兽变成里侧守备表示？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36247316,'魅影骑士团失落铠','①：以场上的1只拥有等级的怪兽为对象可以发动。直至回合结束时为止，该怪兽的攻击力下降600，等级变为2，自己的“魅影骑士团”怪兽不会因战斗被破坏。然后，此卡变为通常怪兽（战士族・暗・星2・攻600/守0），以守备表示特殊召唤至怪兽区域（不视为陷阱卡）。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36256625,'超级交通机人巨型尖钻机',replace(replace('“蒸汽火车机人”＋“钻头机人”＋“潜艇机人”\r\n此卡仅可以上述卡牌进行融合召唤。此卡攻击守备表示怪兽时，若攻击力超过该守备力，给予对手生命相当于该差值的战斗伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36261276,'亚空间物质传送装置','①：可以我方场上的１只表侧表示怪兽为对象发动。直到结束阶段，将该我方的表侧表示怪兽从游戏中除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36262024,'黑龙之雏','可将我方场上表侧表示的此卡送入墓地来发动此卡。从手牌特殊召唤１只“真红眼黑龙”。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36270527,'无限与有限之奥艺',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：从手牌将此卡除外可以发动。从牌组将1只战士族以外的“奥艺”怪兽加入手牌。此回合中，自己场上的“狱神”连接怪兽的原本的攻击力变为3倍。\r\n②：此卡为除外状态，且融合・连接怪兽被特殊召唤的情况下可以发动。将此卡特殊召唤。\r\n③：自己场上存在“狱神”连接怪兽的情况下，以场上的1只怪兽为对象可以发动。将该怪兽除外。','\r',char(13)),'\n',char(10)),'检索效果','特殊召唤','除外效果','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36278828,'猛毒双头蛇','１回合１次，可选择对手场上的１只怪兽并放置１个猛毒计数物。','放置计数物','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36280194,'补充要员','我方墓地上存在５只或以上怪兽的场合可发动。选择存在于我方墓地的除效果怪兽以外的最多３只攻击力１５００或以下的怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36304921,'魔人死亡撒旦','身着一袭与黑夜融为一体的漆黑燕尾服，是操纵死亡的恶魔。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36318200,'森之圣兽 绿叶独角兽','①：自己墓地的怪兽仅有兽族的情况下，解放此卡可以发动。从自己的手牌・墓地挑选“森之圣兽 绿叶独角兽”以外的１只兽族怪兽特殊召唤。以此效果特殊召唤的怪兽在此回合不可攻击。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36319131,'斗气炎斩龙',replace(replace('龙族怪兽＋战士族・炎属性怪兽\r\n此卡名的①效果１回合仅可使用１次。\r\n①：在自己・对手回合中，以自己场上的１只战士族融合怪兽为对象可以发动。从自己场上・墓地将此卡视为装备魔法卡，装备于该自己的怪兽。\r\n②：只要此卡被装备于“炎之剑士”或记载有该卡名的怪兽，装备怪兽的攻击力上升７００，在１次战斗阶段中可攻击２次。','\r',char(13)),'\n',char(10)),'当作装备卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36320744,'巡历圣剑的王姬 安洁莉卡',replace(replace('协调＋协调以外的怪兽１只以上\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡特殊召唤的情况下可以发动。从牌组将１张记载有“焰圣骑士帝－查理”卡名的卡或“象牙号角 奥利方”加入手牌。\r\n②：场上的此卡成为攻击・效果的对象时可以发动。从牌组将１只战士族・炎属性怪兽送至墓地，将此卡直至结束阶段为止除外。然后，可从牌组・额外牌组将１只“罗兰”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'牌组检索','此卡除外','是否从牌组·额外牌组特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36322312,'起动提督 毁灭旋转者',replace(replace('此卡不可通常召唤。\r\n仅可在从手牌及自己场上表侧表示的卡中，将２张“小工具”怪兽卡送至墓地的情况下特殊召唤。\r\n①：只要自己场上存在“小工具”怪兽或视为装备卡的“小工具”怪兽，此卡不会因战斗・效果被破坏。\r\n②：１回合１次，以此卡以外的场上的１张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36326160,'直播☆双子 姬丝吉尔',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：此卡召唤・特殊召唤的情况下，如果自己场上不存在其他怪兽则可以发动。从手牌・牌组将1只“璃拉”怪兽特殊召唤。\r\n②：只要此卡存在于怪兽区域，每当对手怪兽攻击宣言，自己就恢复500LP。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36328300,'究极宝玉阵',replace(replace('①：我方的“宝玉兽”因战斗被破坏时，可从手牌、牌组及我方场上表侧表示的卡牌中，将７种“宝玉兽”卡牌各１张送入墓地并发动。将１只“究极宝玉神”融合怪兽视为融合召唤从额外牌组特殊召唤。\r\n②：表侧表示的“究极宝玉神”怪兽因对手效果从我方场上离开的场合，可将墓地的此卡除外并发动。挑选我方墓地任意数量的“宝玉兽”怪兽，并将其视为永续魔法卡以表侧表示放置在我方的魔法与陷阱区域。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36331074,'薰风之疾风 莉姿','１回合１次，可将１张手牌返回至牌组最下方，并选择对手场上的１只怪兽和我方场上的１只冠有“薰风”之名的怪兽发动。交换被选择怪兽的控制权。','控制权交换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36346532,'伯吉斯吸虫・寒武耙虾',replace(replace('“伯吉斯吸虫”怪兽2只\r\n此卡名的②③效果1回合仅可各使用1次。\r\n①：场上的此卡不受其他怪兽的效果影响。\r\n②：以魔法与陷阱区域的1张里侧表示的卡为对象可以发动。将该卡送至墓地，从牌组将1张“伯吉斯吸虫”陷阱卡放置在自己场上。以此效果放置的卡在放置的回合也可以发动。\r\n③：自己场上的里侧表示卡将被效果破坏的情况下，作为代替可将场上・墓地的此卡除外。','\r',char(13)),'\n',char(10)),'','适用「伯吉斯吸虫·寒武耙虾」的效果来发动','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36350300,'高尚仪式术','仪式怪兽的降临所必需。此卡名的卡１回合仅可发动１张。①：为使合计等级与仪式召唤的怪兽相等，解放手牌的通常怪兽，从牌组将１只仪式怪兽仪式召唤。以此效果特殊召唤的怪兽将在对手的结束阶段放回持有者的牌组。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36352429,'吸血鬼龙','上级召唤的此卡从场上被送入墓地时可发动。从牌组将１只等级４或以下的怪兽加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36354007,'闪电战神 吉尔福德',replace(replace('此卡也可解放３只怪兽来进行召唤。\r\n①：解放３只怪兽成功上级召唤此卡的场合，发动此卡。破坏对手场上的所有怪兽。','\r',char(13)),'\n',char(10)),'解放3只怪兽召唤','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36354008,'闪电战神 吉尔福德',replace(replace('此卡也可解放３只怪兽来进行召唤。\r\n①：解放３只怪兽成功上级召唤此卡的场合，发动此卡。破坏对手场上的所有怪兽。','\r',char(13)),'\n',char(10)),'解放3只怪兽召唤','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36361633,'威吓之咆哮','①：此回合，对手不可攻击宣言。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36368606,'电脑网・刷新',replace(replace('①：对手电子界族怪兽的攻击宣言时可发动。破坏双方主要怪兽区的所有怪兽。从墓地尽可能地特殊召唤在此回合结束阶段以此效果破坏的电子界族连接怪兽至持有者的场上。\r\n②：对手怪兽的效果发动时，可将墓地的此卡除外并发动。直至回合结束时，我方场上的电子界族连接怪兽不受除自身以外之卡牌的效果影响。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36376145,'魂之一击','我方的LP为４０００或以下的场合，可在我方场上的怪兽与对手怪兽进行战斗的攻击宣言时，支付一半LP，并选择我方场上的１只怪兽发动。直至对手回合结束时，被选择怪兽的攻击力上升相当于我方LP低于４０００的差额。“魂之一击”１回合只可发动１张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36378044,'幸运重击','１回合１次，对手怪兽的攻击宣言时可发动。掷３次硬币，３次均为正面的场合，我方从牌组抽取３张卡牌。３次都是反面的场合，破坏此卡。此外，场上以表侧表示存在的此卡被破坏的场合，我方失去６０００LP。','投掷骰子','是否现在使用「幸运重击」的效果？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36378213,'救护车机人','冠有“机人”之名怪兽从我方墓地加入手牌时，可特殊召唤该怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36400569,'傀儡游仪－饭杀傀偶',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：以对手场上的怪兽为对象可以发动，数量最多为自己场上的“机关傀偶”超量怪兽的数量。直至结束阶段为止获得该怪兽的控制权。\r\n②：自己场上存在“机关傀偶”超量怪兽的情况下，从墓地将不是在此回合被送至墓地的此卡除外，以自己或对手的墓地的１只超量怪兽为对象可以发动。将该怪兽以守备表示特殊召唤至自己或对手场上。','\r',char(13)),'\n',char(10)),'取得对手场上怪兽控制权','在自己或对手场上特殊召唤','在自己场上特殊召唤','在对手场上特殊召唤','','','','','','','','','','','','');
INSERT INTO texts VALUES(36405256,'鲜花之魔女','此卡名的效果1回合仅可使用1次。①：此卡召唤・特殊召唤成功的情况下，以对手墓地的1只怪兽为对象发动。将该怪兽特殊召唤至自己场上。以此效果特殊召唤的怪兽对手不可直接攻击，将在此回合的结束阶段被破坏。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36407615,'恶魔混沌王',replace(replace('恶魔族协调＋协调以外的怪兽１只或以上\r\n此卡的攻击宣言时可发动。直至战斗阶段结束时，互换对手场上所有怪兽的攻击力、守备力。','\r',char(13)),'\n',char(10)),'攻守交换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36415522,'娱乐伙伴危机帮手',replace(replace('①：１回合１次，对手怪兽的直接攻击宣言时可以发动此效果。使该攻击无效，从牌组将１只“娱乐伙伴”怪兽特殊召唤。以此效果特殊召唤的怪兽的效果无效化。\r\n②：自己的怪兽与对手怪兽进行战斗的攻击宣言时，将魔法与陷阱区域表侧表示的此卡送至墓地可以发动。因该战斗对自己造成的战斗伤害变为０。','\r',char(13)),'\n',char(10)),'是否使用效果？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36426778,'魅影骑士团无声靴','此卡名以①方法的特殊召唤1回合仅可进行1次，且②效果1回合仅可使用1次。①：自己场上有“魅影骑士团”怪兽存在的情况下，此卡可从手牌中特殊召唤。②：将墓地的此卡除外可以发动。从牌组将1张“魅影”魔法・陷阱卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36429703,'急袭猛禽－智慧林鸮',replace(replace('鸟兽族・暗属性怪兽2只\r\n此卡名的①②效果1回合仅可各使用1次。①：此卡连接召唤成功的情况下可以发动。从牌组将1只鸟兽族・暗属性・等级4怪兽以守备表示特殊召唤。以此效果特殊召唤的怪兽不可作为连接素材，效果无效化。②：自己的“急袭猛禽”超量怪兽的效果发动的情况下发动。从牌组将1张“升阶魔法”魔法卡放置在自己场上。放置的是速攻魔法卡的情况下，该卡在放置的回合也可以发动。','\r',char(13)),'\n',char(10)),'','','适用「急袭猛禽－智慧林鸮」的效果来发动','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36436372,'机关傀偶－小兵队',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：此卡召唤・特殊召唤的情况下，从牌组将等级与此卡不同的１只“机关傀偶”怪兽送至墓地可以发动。将此卡的等级改成与所送至墓地的怪兽相同。\r\n②：将墓地的此卡除外，以自己场上的最多２只“机关傀偶”怪兽为对象可以发动。该怪兽的等级直至回合结束时为止上升４。','\r',char(13)),'\n',char(10)),'送墓等级变换','等级上升','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36442179,'黑羽－龙卷的飓风','①：１回合１次，可以场上的１只同步怪兽为对象发动。直至回合结束时，此卡的攻击力变成与对象怪兽的攻击力相同。','攻击变换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36458063,'魔女的一击','①：对手将怪兽的召唤・特殊召唤无效的情况下，或对手将魔法・陷阱・怪兽效果的发动无效的情况下可以发动。将对手手牌・场上的卡全部破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36468556,'停战协定','①：场上有效果怪兽或里侧守备表示怪兽存在的情况下可以发动。将场上所有里侧守备表示的怪兽改成表侧守备表示。此时，反转怪兽的效果不发动。给予对手相当于场上效果怪兽数量×500的伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36472900,'小走鹃','①：此卡不会因与攻击力1900以上的怪兽战斗被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36484016,'奇迹同步结合',replace(replace('①：将自己的场上・墓地的怪兽作为融合素材除外，将１只需以同步怪兽作为融合素材的融合怪兽融合召唤。\r\n②：被放置的此卡因对手的效果被破坏并被送至墓地的情况下发动。自己抽１张。','\r',char(13)),'\n',char(10)),'抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36492575,'海晶少女 海马',replace(replace('此卡名以①方法的特殊召唤１回合仅可进行１次，且②效果１回合仅可使用１次。\r\n①：此卡可从手牌特殊召唤至“海晶少女”连接怪兽连接端的自己场上。\r\n②：将不是在此回合被送至墓地的此卡从墓地除外可以发动。从手牌将１只水属性怪兽特殊召唤至“海晶少女”连接怪兽连接端的自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36494597,'瞬移结合',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己・对手的主要阶段可以发动。将自己场上・墓地的念动力族怪兽作为融合素材除外，将1只念动力族的融合怪兽融合召唤。\r\n②：自己场上被从额外牌组特殊召唤的表侧表示念动力族怪兽因战斗・效果被破坏的情况下，将墓地的此卡除外，以自己除外状态的1只念动力族怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'融合召唤','除外状态的怪兽特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36499284,'炎舞－摇光－',replace(replace('①：此卡发动时，可以对手场上的１张表侧表示卡为对象。该情况下，从手牌挑选１只兽战士族怪兽舍弃，破坏对象卡。\r\n②：只要此卡存在于魔法与陷阱区域，自己场上的兽战士族怪兽的攻击力上升１００。','\r',char(13)),'\n',char(10)),'是否要选择对手场上表侧表示存在的1张卡破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36521307,'斩机弓形','此卡名的①②效果１回合仅可各使用１次。①：从牌组将“斩机弓形”以外的１只“斩机”怪兽送至墓地可以发动。从手牌将此卡特殊召唤。此效果发动后，直至回合结束时为止，自己仅可用１只怪兽攻击。②：此卡已经存在于怪兽区域的状态下，其他“斩机”怪兽被召唤・特殊召唤至自己场上的情况下可以发动。从牌组将１张“斩机”魔法・陷阱卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36521459,'Sin 星尘龙',replace(replace('此卡不可通常召唤。\r\n仅可在从额外牌组将1只“星尘龙”除外的情况下特殊召唤。\r\n①：“Sin”怪兽在场上仅可有1只以表侧表示存在。\r\n②：只要此卡存在于怪兽区域，场地区域的表侧表示卡不会因效果被破坏。\r\n③：只要此卡存在于怪兽区域，自己的其他怪兽不可攻击宣言。\r\n④：不存在表侧表示的场地魔法卡的情况下，此卡将被破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36523152,'超重武者 大草屦－G','①：自己的墓地不存在魔法・陷阱卡的情况下，此卡可从手牌中特殊召唤。以此方法特殊召唤成功的余下本回合，自己仅可特殊召唤“超重武者”怪兽。②：上级召唤机械族怪兽的情况下，此卡可作为２只解放。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36527535,'娱乐伙伴・活报剧舞者',replace(replace('①：对手场上存在有怪兽，且我方场上不存在有怪兽的场合，此卡可从手牌特殊召唤。\r\n②：上级召唤“娱乐伙伴”怪兽的场合，此卡可当成２只怪兽进行解放。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36539330,'刺拳大熊猫',replace(replace('此卡名以①方法的特殊召唤１回合仅可进行１次，且②效果１回合仅可使用１次。\r\n①：场上有２只以上兽战士族怪兽存在的情况下，此卡可从手牌中特殊召唤。\r\n②：此卡从场上被送至墓地的情况下，以自己场上的１只表侧表示怪兽为对象可以发动。该怪兽的攻击力上升５００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36553319,'彼岸恶鬼 法法雷鲁','此卡名的①③效果1回合1次，仅可使用其中1个。①：自己场上没有魔法・陷阱卡存在的情况下可以发动。从手牌将此卡特殊召唤。②：自己场上有“彼岸”怪兽以外的怪兽存在的情况下此卡将被破坏。③：此卡被送至墓地的情况下，可以场上的1只怪兽为对象发动。将该怪兽直到结束阶段为止除外。','特殊召唤','除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36556781,'龙骑兵团骑士－碧刃之枪',replace(replace('“龙骑兵团”协调＋１只以上协调以外的怪兽\r\n此卡名的①②效果１回合仅可各使用１次。①：此卡同步召唤成功时，以自己墓地的１只“龙骑兵团”协调为对象可以发动。将该怪兽视为装备卡装备于此卡。②：将自己场上１张装备于此卡的装备卡送至墓地，以对手墓地的最多２张卡为对象可以发动。将该卡除外。此效果在对手回合中也可以发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36560997,'核心超频','只要此卡存在于场上，我方场上冠有“核成”之名的所有怪兽的攻击力上升５００点。此外，１回合１次，可从手牌舍弃１张“核成之钢核”并发动。直至回合结束时，我方场上冠有“核成”之名的所有怪兽的攻击力上升１０００点。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36562627,'第二次机会',replace(replace('此卡名的①效果１回合仅可适用１次。\r\n①：自己掷硬币的效果适用之际，可从最开始重新掷硬币。','\r',char(13)),'\n',char(10)),'是否要使用「第二次机会」的效果？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36565699,'心灵探索者','①：除外状态的此卡特殊召唤的情况下发动。从对手牌组上面翻开3张卡，自己从其中挑选1张除外。然后，将剩余的卡放回牌组。','除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36569343,'红炎之骑士','1个回合1次，这个卡名的①②的效果只能使用其中任意1个。①：这张卡已存在于怪兽区域的状态下，这张卡以外的炎属性怪兽在被破坏并被送至自己墓地的情况下发动。从牌组将1只炎属性怪兽送至墓地。②：这张卡在被破坏并被送至墓地的情况下发动。从牌组把1只炎属性怪兽送至墓地。','牌组送墓','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36577931,'悲剧之惨绝戏子',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：此卡因效果被送至墓地的情况下，或因效果被除外的情况下可以发动。从牌组将“悲剧之惨绝戏子”以外的1只“惨绝戏”怪兽加入手牌。\r\n②：将墓地的此卡除外，以自己墓地的1张“烙印”魔法・陷阱卡为对象可以发动。将该卡放置在自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36584821,'红莲魔兽 泰沙','①：此卡的攻击力・守备力变为被除外的自己的卡数量×400的数值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36586443,'元素充电','我方回复我方场上冠有“元素－英雄”之名怪兽数量×１０００LP。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36591747,'惊乐游乐设施・激奋列车',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：以自己场上的１只“惊乐园”怪兽或对手场上的表侧表示怪兽为对象可以发动此卡。将此卡视为装备卡，装备于该怪兽。\r\n②：根据装备怪兽的控制者，可以发动以下效果。\r\n●自己：变更装备怪兽的表示形式，对手挑选自己墓地的１张“游乐设施”陷阱卡。将该卡放置在自己场上。\r\n●对手：将装备怪兽直至结束阶段为止除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36607978,'魔性之月','仅限装备兽战士族怪兽。令装备怪兽的攻击力和守备力上升３００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36608728,'战刀匠 再刃',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：以自己墓地的1只等级6以下的战士族怪兽为对象可以发动。将该怪兽特殊召唤。以此效果特殊召唤的怪兽的效果无效化。此卡在此回合不可作为同步素材。\r\n②：在对手的主要阶段可以发动。将包含战士族怪兽在内的、自己场上的怪兽作为素材进行同步召唤。','\r',char(13)),'\n',char(10)),'从墓地特殊召唤','同步召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36609518,'邪恶★双子 璃拉',replace(replace('包含“璃拉”怪兽在内的怪兽2只\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡特殊召唤的情况下，如果自己场上存在“姬丝吉尔”怪兽，则以场上的1张卡为对象可以发动。将该卡破坏。\r\n②：在自己・对手的主要阶段，自己场上不存在“姬丝吉尔”怪兽的情况下可以发动。从自己的墓地将1只“姬丝吉尔”怪兽特殊召唤。此回合，自己从额外牌组仅可特殊召唤恶魔族怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36609519,'邪恶★双子 璃拉',replace(replace('包含“璃拉”怪兽在内的怪兽2只\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡特殊召唤的情况下，如果自己场上存在“姬丝吉尔”怪兽，则以场上的1张卡为对象可以发动。将该卡破坏。\r\n②：在自己・对手的主要阶段，自己场上不存在“姬丝吉尔”怪兽的情况下可以发动。从自己的墓地将1只“姬丝吉尔”怪兽特殊召唤。此回合，自己从额外牌组仅可特殊召唤恶魔族怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36614113,'DD方舟',replace(replace('←1 【灵摆】 1→\r\n此卡牌名的灵摆效果１回合只可使用１次。\n①：可以对手场上１只灵摆召唤而来的怪兽作为对象发动。破坏该怪兽与此卡。\r\n【怪兽效果】\r\n此卡牌名的怪兽效果１回合只可使用１次。\n①：此卡因效果被破坏的场合可发动。从我方的额外牌组特殊召唤１只除“DD方舟”以外之表侧表示的“DD”灵摆怪兽。以此效果特殊召唤之怪兽的效果被无效化。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36623431,'核成之钢核',replace(replace('①：此卡存在于墓地的情况下，在自己的抽牌阶段的抽牌前可以发动。作为此回合通常抽牌的代替，将此卡加入手牌。\r\n②：在自己的抽牌阶段，从手牌将1只“核成”怪兽送至墓地可以发动。将墓地的此卡加入手牌。','\r',char(13)),'\n',char(10)),'代替抽牌加入手牌','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36625827,'命运－英雄 恐惧从者',replace(replace('①：此卡召唤的情况下发动。在场上的所有“幽狱时钟塔”上各放1个时钟计数物。\r\n②：此卡因战斗被破坏并被送至墓地时，以自己场上的1张魔法・陷阱卡为对象可以发动。将该自己的卡破坏。','\r',char(13)),'\n',char(10)),'放置计数物','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36629203,'正义盟军 核心破坏兽','此卡与光属性怪兽进行战斗的伤害步骤开始时，破坏该怪兽。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36629635,'蒲公英白狮',replace(replace('此卡名的效果1回合仅可使用1次，发动此效果的回合，自己不可从额外牌组特殊召唤怪兽。\r\n \r\n①：此卡从手牌・场上被送至墓地的情况下可以发动。将3只“白绵毛衍生物”（植物族・风・星1・攻/守0）以守备表示特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36629636,'白绵毛衍生物','由“蒲公英白狮”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36630403,'妖刀－不知火','此卡名的效果１回合仅可使用１次。①：此卡存在于墓地的情况下，以自己墓地协调以外的１只不死族怪兽为对象可以发动。将该怪兽和此卡从墓地除外，将１只拥有与该２只等级合计相同等级的不死族同步怪兽从额外牌组特殊召唤。此效果在此卡被送至墓地的回合不可发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36637374,'烙印开幕',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：挑选自己的1张手牌舍弃。然后，从牌组挑选1只“惨绝戏”怪兽，加入手牌或以守备表示特殊召唤。此卡发动后，直至回合结束时为止，自己从额外牌组仅可特殊召唤融合怪兽。\r\n②：自己场上的融合怪兽将被效果破坏的情况下，作为代替可将墓地的此卡除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36643046,'同步士探索者','①：此卡召唤成功时，以自己墓地的1只“同步士”怪兽为对象可以发动。将该怪兽特殊召唤。以此效果特殊召唤的怪兽的效果无效化。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36668118,'轮转导引扇区',replace(replace('此卡名的②效果1回合仅可使用1次。①：场上的“枪弹”怪兽的攻击力・守备力上升300。②：在自己的主要阶段可从以下效果中选择1个发动。\r\n●从手牌将最多2只“枪弹”怪兽以守备表示特殊召唤（同名卡最多1张）。\r\n●对手场上的怪兽数量多于自己场上怪兽的情况下，从自己墓地挑选最多为其数量差的“枪弹”怪兽以守备表示特殊召唤（同名卡最多1张）。','\r',char(13)),'\n',char(10)),'从手牌特殊召唤','从墓地特殊召唤','是否继续选择怪兽特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36672909,'再世律',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：自己场上存在原本攻击力或原本守备力为2500的怪兽的情况下，以对手场上的1张卡为对象可以发动（自己场上存在“创言再世神 德乌特洛诺米翁”的情况下，可将此效果的对象改成2张）。将该卡除外。\r\n②：从墓地将不是在此回合被送至墓地的此卡除外可以发动。从手牌将1只攻击力或守备力为2500的怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'发动','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36687247,'T.G.冲刺犀牛','此卡攻击的场合，在伤害步骤期间，攻击力上升４００点。场上的此卡被破坏并送入墓地回合的结束阶段时可发动。从牌组将１只除“T.G.冲刺犀牛”以外冠有“T.G.”之名的怪兽加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36690018,'逆转的命运','可选择我方场上１只冠有“秘仪之力”之名的怪兽并发动。被选择怪兽由掷硬币的正反面而获得的效果变为相反。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36693940,'魔玩具・改造','①：可以我方墓地的１只“锋利小鬼”怪兽或１只“绒毛动物”怪兽为对象发动。特殊召唤该怪兽。将以此效果特殊召唤之怪兽作为融合素材的场合，可被视为“魔玩具”怪兽。','「魔玩具・改造」效果适用中','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36694815,'比特骑兵','此卡名的效果1回合仅可使用1次。①：从手牌将1只等级2以下的怪兽送至墓地可以发动。从手牌将此卡特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36704180,'魅影骑士团脆铠甲','此卡名的①②效果1回合仅可各使用1次。①：自己场上的表侧表示的“魅影骑士团”怪兽因战斗・效果被破坏的情况下可以发动。从手牌将此卡特殊召唤。②：将墓地的此卡除外，将手牌的1张“魅影骑士团”卡或“魅影”魔法・陷阱卡送至墓地可以发动。自己从牌组抽1张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36708764,'轮盘蜘蛛',replace(replace('①：可在对手怪兽的攻击宣言时发动。掷１次股子，适用掷出的点数的效果。\r\n●１：将自己的LP改成一半。\r\n●２：该攻击变成对我方的直接攻击。\r\n●３：从我方场上挑选１只怪兽，将攻击对象转移至该怪兽并进行伤害计算。\r\n●４：挑选对手场上１只除攻击怪兽以外的怪兽，将攻击对象转移至该怪兽并进行伤害计算。\r\n●５：使该攻击无效，并给予对手相当于该怪兽攻击力数值的伤害。\r\n●６：破坏该对手怪兽。','\r',char(13)),'\n',char(10)),'请选择攻击对象','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36709484,'无预幻的牧歌日常',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：自己场上存在“神艺”、“终刻”、“耀圣”卡中的任一的情况下可以发动。从手牌・牌组将1只“无垢者 墨迪乌斯”特殊召唤。该特殊召唤成功时对手不可发动卡的效果。\r\n②：将墓地的此卡除外，以自己墓地的1只融合・同步・超量怪兽为对象可以发动。将该怪兽特殊召唤至连接怪兽连接端的自己场上。','\r',char(13)),'\n',char(10)),'发动','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36717258,'朱罗纪・单冠龙','①：此卡可攻击所有对手怪兽各1次。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36730805,'疾行漂移','①：自己场上的怪兽仅有1只且为协调的情况下可以发动。从牌组将1只等级4以下的“疾行机人”怪兽特殊召唤。该特殊召唤成功时，双方不可发动魔法・陷阱・怪兽的效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36733451,'次元合成师','１回合１次，可在我方主要阶段时发动。将牌组最上方的卡牌以表侧表示从游戏中除外，此卡的攻击力直至结束阶段时上升５００点。此外，我方场上的此卡被破坏送入墓地时，可选择我方１只从游戏中除外的怪兽加入手牌。','攻击上升','选择除外的1张自己怪兽卡加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36734924,'青之眼巫女','此卡名的①②效果１回合１次，仅可使用其中１个。①：场上表侧表示的此卡成为效果的对象时可以发动。挑选自己场上的１只效果怪兽送至墓地，从牌组将最多２只“青眼”怪兽加入手牌（同名卡最多１张）。②：此卡存在于墓地的情况下，以自己场上的１只“青眼”怪兽为对象可以发动。将该怪兽放回持有者的牌组，从墓地将此卡特殊召唤。','把最多2只「青眼」怪兽加入手牌','此卡从墓地特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36736723,'突击战士','此卡名的①②效果1回合仅可各使用1次。①：自己的“战士”同步怪兽与对手怪兽进行战斗的伤害计算时，将此卡从手牌送至墓地可以发动。进行该战斗的自己的怪兽的攻击力仅在该伤害计算时变为两倍。②：将墓地的此卡除外，以自己墓地的1只“同步士”怪兽为对象可以发动。将该怪兽加入手牌。','攻击上升','卡片回收','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36737092,'同步变化','可将我方场上的１只表侧表示同步怪兽从游戏中除外并发动。从额外牌组特殊召唤１只与该怪兽相同等级的同步怪兽。以此效果特殊召唤怪兽的效果被无效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36742774,'同步世界',replace(replace('①：每次怪兽被同步召唤，在此卡上放２个信号计数物。\r\n②：依以下数量去除自己场上的信号计数物，可以发动相应效果。\r\n●４：自己场上的１只表侧表示怪兽的等级上升或下降１。\r\n●７：从自己的墓地将１只协调特殊召唤。\r\n●１０：从自己的墓地将１只同步怪兽特殊召唤。\r\n③：场上的此卡因对手的效果被破坏的情况下可以发动。从额外牌组将１只“赤龙”特殊召唤。','\r',char(13)),'\n',char(10)),'4个：等级变换','７个：协调特殊召唤','10个：同步怪兽特殊召唤','从额外牌组把1只「赤龙」特殊召唤','等级上升','等级下降','','','','','','','','','','');
INSERT INTO texts VALUES(36745317,'森与觉醒的春化精','此卡名的①②效果１回合仅可各使用１次。①：从手牌将此卡和、１只怪兽或１张“春化精”卡舍弃可以发动。将１只可通常召唤的地属性怪兽从牌组送至墓地。然后，可从自己的墓地挑选１只卡名与该怪兽不同的地属性怪兽特殊召唤。此回合，自己不可发动地属性以外的怪兽的效果。②：以自己场上的１只“春化精”怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止变为两倍。','是否从墓地特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36750412,'炎龙','①：此卡给予对手战斗伤害的场合发动。此卡的攻击力上升２００。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36757171,'邪蚀 巴哈姆特',replace(replace('冠有“邪蚀”之名的等级４怪兽×２\r\n１回合１次，可移除此卡的１个超量素材，选择对手场上的１只表侧表示怪兽并发动。从手牌舍弃１只冠有“邪蚀”之名的怪兽，并获得被选择对手怪兽的控制权。','\r',char(13)),'\n',char(10)),'获取控制权','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36768783,'星导龙 阿米莱尔',replace(replace('效果怪兽2只\r\n此卡不可作为连接素材。\r\n此卡名的效果1回合仅可使用1次。\r\n①：以此卡连接端的1只表侧表示怪兽为对象可以发动。从手牌将1只原本等级与该怪兽相同的怪兽以守备表示特殊召唤至此卡连接端的自己场上。以此效果特殊召唤的怪兽的效果无效化。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36776089,'神骑 圣人马',replace(replace('等级2怪兽×2\r\n①：持有超量素材的此卡不会因战斗被破坏。\r\n②：此卡与对手怪兽进行战斗的伤害步骤结束时，去除此卡的1个超量素材可以发动。将该对手怪兽放回手牌。','\r',char(13)),'\n',char(10)),'回到手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36795102,'究极宝玉兽 虹龙',replace(replace('此卡名的①③效果１回合仅可各使用１次。\r\n①：“宝玉兽”怪兽进行战斗的攻击宣言时可以发动。从手牌将此卡特殊召唤。\r\n②：表侧表示的此卡在怪兽区域被破坏的情况下，可不送至墓地，而是视为永续魔法卡以表侧表示放在自己的魔法与陷阱区域。\r\n③：将视为永续魔法卡的此卡除外可以发动。从牌组将１只等级４以下的“宝玉兽”怪兽的效果无效并特殊召唤，从牌组将１只“究极宝玉神”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36809777,'炽烈兽争',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：双方玩家自身场上有２只以上同种类（仪式・融合・同步・超量・连接）的怪兽存在的情况下，只能留下１只，其余的必须送至墓地。然后，将怪兽送至墓地的玩家依自身场上的怪兽种类（仪式・融合・同步・超量・连接）的数量从牌组抽牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36821538,'古代魔导士','拥有许多魔杖，区分使用施展多彩的攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36834155,'光子海盗','可将我方墓地１只冠有“光子”之名的怪兽从游戏中除外并发动。直至回合结束时，此卡的攻击力上升１０００点。“光子海盗”的效果１回合最多可使用２次。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36841733,'元素－英雄 统合人',replace(replace('“-英雄”通常怪兽×2\r\n此卡仅可以融合召唤方式特殊召唤。①：此卡的攻击力・守备力上升相当于作为此卡融合素材的怪兽原本等级合计×300的数值。②：此卡战斗破坏对手怪兽时，解放此卡可以发动。从额外牌组将1只“元素-英雄”融合怪兽无视召唤条件特殊召唤。以此效果特殊召唤的怪兽不可攻击拥有自身等级以下的等级的怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36848764,'甜蜜房务女仆',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：自己或对手的卡从手牌・牌组被送至墓地的情况下，以自己或对手墓地的1张卡为对象可以发动。将该卡放回牌组。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36849933,'巨石异物・奥赫','以“巨石异物”卡降临。此卡名的②效果1回合仅可使用1次。①：此卡仪式召唤成功的情况下可以发动。自己从牌组抽1张。然后挑选1张手牌舍弃。②：在自己・对手的主要阶段可以发动。为使合计等级为仪式召唤的怪兽以上，解放包括场上的此卡的自己手牌・场上的怪兽，从手牌将1只仪式怪兽仪式召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36857073,'琰魔龙 暗红恶魔彼列',replace(replace('协调＋协调以外的龙族・暗属性同步怪兽１只\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：解放自己场上的１只怪兽，以自己墓地的１只“暗红恶魔”怪兽为对象可以发动。将该怪兽特殊召唤。\r\n②：此卡给予对手战斗伤害时可以发动。从自己的牌组及墓地将等级相同的协调各１只以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36868108,'玻璃之铠','装备卡被装备在怪兽时可发动。此回合，场上的装备卡的效果被无效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36870345,'龙骑兵团－小投枪','①：此卡召唤成功时可以发动。从手牌将1只“龙骑兵团”怪兽特殊召唤，然后，将自己场上表侧表示的此卡视为装备卡装备于该特殊召唤的怪兽。②：装备于怪兽的此卡被送至墓地的情况下，以场上的1张卡为对象发动。将该卡破坏。','特殊召唤并装备','场上的1张卡破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36890111,'地狱人偶之馆',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：作为此卡发动时的效果处理，可从牌组将１只“机关傀偶”怪兽加入手牌。\r\n②：自己场上的“机关傀偶”怪兽不会因战斗被破坏，不受超量怪兽以外的对手怪兽发动的效果影响。\r\n③：１回合１次，去除自己场上的１个超量素材，以自己墓地的１只“机关傀偶”怪兽为对象可以发动。将该怪兽以守备表示特殊召唤至对手场上。','\r',char(13)),'\n',char(10)),'是否从牌组把「机关傀偶」怪兽加入手牌？','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36894320,'无限械００',replace(replace('将自己魔法与陷阱区域的１张表侧表示的“虚无械０”送至墓地可以发动此卡。\r\n①：此卡１回合仅１次，不会因对手的效果被破坏。\r\n②：１回合１次，可从以下效果中选择１个发动。\r\n●在自己・对手的主要阶段可以发动。从手牌将１只“时械神”怪兽特殊召唤。\r\n●以自己墓地的１只“时械神”怪兽为对象可以发动。将该怪兽放回牌组。然后，可从手牌・牌组挑选１张“无限光０００”，放置在自己的魔法与陷阱区域。','\r',char(13)),'\n',char(10)),'特殊召唤','墓地回收','是否放置「无限光０００」？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36898537,'玄化荷鲁斯龙',replace(replace('协调＋１只以上协调以外的怪兽\r\n①：此卡同步召唤成功的情况下，根据该作为同步素材的协调以外的怪兽种类，可分别发动以下效果。\r\n●通常怪兽：此回合，此卡不受自身以外的卡的效果影响。\r\n●效果怪兽：以场上此卡以外的１张表侧表示卡为对象可以发动。将该效果无效。\r\n●灵摆怪兽：对手挑选自身场上的１只怪兽，自己获得该控制权。此回合，该怪兽不可攻击。','\r',char(13)),'\n',char(10)),'效果耐性','效果无效','得到控制权','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36904469,'卡可塔斯','潜伏在水中，形态异常的怪物。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36916401,'燃烧拳击・斗魂',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：将牌组最上面的卡送至墓地，以自己墓地的１只“燃烧拳斗士”怪兽为对象可以发动。将该怪兽以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36920182,'世坏同心',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：可从以下效果中选择１个发动。\r\n●从自己的墓地将１只攻击力１５００／守备力２１００的怪兽特殊召唤。\r\n●将自己场上（表侧表示）・墓地・除外状态的１只“维萨思・史塔弗罗斯特”和４只攻击力１５００／守备力２１００的怪兽放回牌组，将１只“维萨思”同步怪兽视为同步召唤从额外牌组特殊召唤。','\r',char(13)),'\n',char(10)),'从墓地特殊召唤','回收并同步召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36931229,'城堡之门',replace(replace('①：此卡不会因战斗被破坏。\r\n②：１回合１次，此卡在场上以攻击表示存在的情况下，解放自己场上１只等级５以下的怪兽可以发动。给予对手解放的怪兽的原本攻击力数值的伤害。','\r',char(13)),'\n',char(10)),'伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36935434,'小巷中的祭品','我方场上的怪兽因战斗被破坏时可发动。从手牌特殊召唤１只“电子食人魔”。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36953371,'超重神鬼 酒吞童子－G',replace(replace('机械族协调＋１只以上协调以外的“超重武者”怪兽\r\n此卡名在规则上也视为“超重武者”卡。①：此卡可在表侧守备表示的状态下攻击。该情况下，将此卡的守备力视为攻击力来进行伤害计算。②：自己的墓地不存在魔法・陷阱卡，此卡同步召唤成功时可以发动。将对手场上的魔法・陷阱卡全部破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36956512,'怪粉坏兽 伽达拉',replace(replace('①：此卡可以解放对手场上１只怪兽，以攻击表示从手牌特殊召唤至对手场上。\r\n②：对手场上存在“坏兽”怪兽的情况下，此卡可以从手牌以攻击表示特殊召唤。\r\n③：“坏兽”怪兽在自己场上仅可有１只以表侧表示存在。\r\n④：在每个自己・对手回合中１次，去除自己・对手场上的３个坏兽计数物可以发动。将此卡以外的、场上所有怪兽的攻击力・守备力改成一半。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36970611,'精神骨架过载','①：１回合１次，从自己的手牌及自己场上的表侧表示怪兽中，将１只“精神骨架”怪兽除外，以场上的１张卡为对象可以发动。将该卡以里侧表示除外。②：将墓地的此卡除外可以发动。从牌组将１张“精神骨架过载”以外的“精神骨架”卡加入手牌。此效果在此卡被送至墓地的回合不可发动。','除外','加入手牌','是否立即使用效果？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36974120,'龙葬主－维尔殓',replace(replace('①：有怪兽在主要阶段被从对手场上送至墓地的情况下，根据此卡的所在之处，可以发动以下效果（此卡名的以下效果１回合仅可各使用１次）。\r\n●手牌：将此卡特殊召唤。\r\n●场上：对手场上的１只效果怪兽的攻击力下降１５００。攻击力因此效果变为０的情况下，进而可将该怪兽破坏。\r\n②：此卡与怪兽进行战斗的情况下，该２只不会因该战斗被破坏。','\r',char(13)),'\n',char(10)),'','','是否把那只怪兽破坏？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36975314,'大搜捕','①：以对手场上的1只表侧表示怪兽为对象可以发动此卡。获得该怪兽的控制权。该怪兽存在于自己场上的情况下，不可攻击，不可发动效果。该怪兽从场上离开时此卡将被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36982581,'咒仪之冰魔镜','“咒仪”仪式怪兽的降临所必需。①：解放对手场上的１只表侧表示怪兽，或为使合计等级与仪式召唤的怪兽相等，解放自己手牌・场上的怪兽，从手牌将１只“咒仪”仪式怪兽仪式召唤，自己失去相当于其原本攻击力数值的LP。②：此卡存在于墓地的情况下，以自己墓地的１只“咒仪”怪兽为对象可以发动。将该怪兽放回牌组最上面，将此卡放回牌组最下面。','是否解放对手的1只怪兽来仪式召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(36995273,'缩退回路','只要此卡存在于场上，从场上返回至手牌的怪兽卡不回到手牌而从游戏中被除外。此卡的控制者每次自己的准备阶段，支付５００LP，不能支付５００LP的场合破坏此卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37006702,'克里希那德女巫',replace(replace('此卡名的①③效果１回合仅可各使用１次。\r\n①：场地区域的卡因效果从场上离开的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：只要场上存在“多元宇宙”，此卡不会因对手的效果被破坏。\r\n③：已经以表侧表示存在的场地魔法卡的效果发动时可以发动。将自己墓地・除外状态的１只怪兽放回牌组。该怪兽记载有该发动的场地魔法卡的卡名的情况下，可不放回牌组而是特殊召唤。','\r',char(13)),'\n',char(10)),'是否特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37007105,'电子宇宙旋风','①：可以对手场上的１只连接怪兽为对象发动。从我方墓地挑选１只连接标记数量和该怪兽数量相同的怪兽并除外，破坏对象怪兽。以此效果除外的我方怪兽的原本种族是电子界族的场合，则可再挑选对手魔法与陷阱区域的１张表侧表示卡牌并破坏。','是否再选1张对手的魔陷破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37011715,'奇迹的苏生','连锁４以后可发动。选择我方或对手墓地的１只怪兽，特殊召唤至我方场上。同一连锁上复数同名卡效果发动的场合，此卡不可发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37021315,'泥岩灵长－强壮泥岩山魈',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：可将此卡视为魔法卡，从手牌放置在魔法与陷阱区域。\r\n②：被放置的此卡因对手的效果被破坏并被送至墓地的回合的结束阶段可以发动。将此卡特殊召唤。然后，可从自己的墓地挑选１只“泥岩灵长－强壮泥岩山魈”以外的怪兽加入手牌。','\r',char(13)),'\n',char(10)),'此卡特殊召唤','是否从墓地把怪兽加入手牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37038993,'焰紫龙匹拉里斯',replace(replace('协调＋协调以外的怪兽１只\r\n此卡从场上被送入墓地时，对手场上所有怪兽的攻击力下降５００点。','\r',char(13)),'\n',char(10)),'攻击下降','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37042505,'不朽的特殊合金',replace(replace('①：自己场上有“人造人-念力震慑者”存在时，可从以下效果中选择1种发动。\r\n●自己场上的所有机械族怪兽直至回合结束时为止不会被对手的效果破坏。\r\n●有以自己场上的机械族怪兽为对象的魔法、陷阱、怪兽的效果发动时可以发动。使该效果无效。','\r',char(13)),'\n',char(10)),'破坏耐性','效果无效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37043180,'异次元战士','此卡同怪兽进行战斗时，将该怪兽和此卡从游戏中除外。','除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37053871,'星光屏障','我方怪兽被选择为攻击对象时可发动此效果。将该攻击转为对我方的直接攻击。','是否现在使用「星光屏障」的效果？','直接攻击','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37055344,'鬼计天旋地转',replace(replace('①：１回合１次，在战斗阶段可从以下效果中选择１个发动。\r\n●以自己场上的１只“鬼计”怪兽为对象可以发动。将该“鬼计”怪兽改成里侧守备表示，挑选对手场上的１只里侧守备表示怪兽改成表侧攻击表示。\r\n●以自己场上的１只里侧守备表示怪兽为对象可以发动。将该里侧守备表示怪兽改成表侧攻击表示，该怪兽是“鬼计”怪兽的情况下，挑选对手场上的１只表侧表示怪兽改成里侧守备表示。','\r',char(13)),'\n',char(10)),'选择效果','自己「鬼计」怪兽变成里侧守备表示','自己怪兽变成表侧攻击表示','请选择一个效果发动','','','','','','','','','','','','');
INSERT INTO texts VALUES(37057012,'电子食人魔２',replace(replace('“电子食人魔”＋“电子食人魔”\r\n此怪兽的融合召唤仅能以上述卡牌进行。此卡的攻击力仅在攻击怪兽的伤害计算时，上升相当于该攻击对象怪兽攻击力的一半数值。','\r',char(13)),'\n',char(10)),'攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37057743,'炎星皇－晁怒狮',replace(replace('炎属性等级３怪兽×２\r\n①：１回合１次，去除此卡的１个超量素材，以自己墓地的１只炎属性怪兽为对象可以发动。将该炎属性怪兽加入手牌。此效果发动后，直至回合结束时为止，自己不可召唤・特殊召唤对象怪兽及其同名怪兽。','\r',char(13)),'\n',char(10)),'加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37061511,'水勒维亚坦＠伊格尼斯者','以“-艾-爱之仪式”降临。此卡名的②效果1回合仅可使用1次。①：此卡仪式召唤成功的情况下可以发动。将对手场上攻击力2300以下的怪兽全部放回持有者的手牌。②：以对手场上的1只表侧表示怪兽为对象可以发动。将自己墓地的连接怪兽全部放回额外牌组，将对象怪兽的攻击力改为0。③：每次此卡与对手怪兽进行战斗的伤害计算时可以发动1次。该对手怪兽的攻击力仅在该伤害计算时变为一半。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37083210,'交叉反制','我方场上守备表示的怪兽被对手怪兽攻击，该守备力超过攻击怪兽的攻击力的场合，给予对手生命的战斗伤害加倍，在伤害步骤结束时破坏该攻击怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37092104,'亚特兰蒂斯的怪腕',replace(replace('此卡名的①③效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下，以自己墓地的1只记载有“龙都 亚特兰蒂斯”卡名的怪兽为对象可以发动。将该怪兽以守备表示特殊召唤。\r\n②：此卡只要存在于怪兽区域，卡名视为“海”。\r\n③：对手发动怪兽的效果时，将场上・墓地的此卡除外，并将自己场上的1张表侧表示的“海”送至墓地可以发动。将该发动的效果无效。','\r',char(13)),'\n',char(10)),'特殊召唤','效果无效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37101832,'守墓的门卫','反转：选择对手场上的１只怪兽并返回至持有者手牌。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37104630,'海皇的重装兵',replace(replace('①：只要此卡存在于怪兽区域，自己除通常召唤外仅可追加１次，在自己的主要阶段召唤１只等级４以下的海龙族怪兽。\r\n②：此卡为发动水属性怪兽的效果被送至墓地的情况下，以对手场上的１张表侧表示卡为对象发动。将该对手的表侧表示卡破坏。','\r',char(13)),'\n',char(10)),'破坏','使用「海皇的重装兵」的效果召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37115575,'Sin 真实龙',replace(replace('此卡不可通常召唤，仅可以此卡的效果特殊召唤。\r\n①：“Sin 真实龙”以外的、自己场上的表侧表示“Sin”怪兽因战斗・效果被破坏的情况下，支付一半LP可以发动。从手牌・墓地将此卡特殊召唤。\r\n②：“Sin”怪兽在场上仅可有1只以表侧表示存在。\r\n③：不存在表侧表示的场地魔法卡的情况下，此卡将被破坏。\r\n④：此卡战斗破坏对手怪兽的情况下发动。将对手场上的表侧表示怪兽全部破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','对手表侧表示的怪兽全部破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37115973,'编号猎人',replace(replace('①：此卡召唤、反转召唤、特殊召唤成功的场合发动。将场上所有的“编号”超量怪兽返回至持有者的额外牌组。\r\n②：只要此卡存在于怪兽区，双方不可特殊召唤“编号”超量怪兽。此外，此卡不会因与超量怪兽的战斗而被破坏，且不受超量怪兽的效果影响。','\r',char(13)),'\n',char(10)),'回到额外牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37119142,'码输出者','此卡名的①②效果1回合仅可各使用1次。①：在要将自己场上的电子界族怪兽作为“码语者”怪兽的连接素材的情况下，手牌的此卡也可一起作为连接素材。②：此卡作为“码语者”怪兽的连接素材从手牌・场上被送至墓地的情况下，以自己墓地的1只等级4以下的电子界族怪兽为对象可以发动。将该怪兽加入手牌。将场上的此卡作为素材的情况下，可不加入手牌而是改为将其效果无效并特殊召唤。','','从场上送至墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37120512,'暗的破神剑','仅限装备暗属性怪兽。令装备怪兽的攻击力上升４００点、守备力下降２００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37129797,'吸血鬼吸食者',replace(replace('不死族怪兽2只\r\n此卡名的①②效果1回合仅可各使用1次。①：以对手墓地的1只怪兽为对象可以发动。将该怪兽以守备表示特殊召唤至对手场上。特殊召唤的该怪兽变为不死族。②：从自己・对手墓地有不死族怪兽被特殊召唤的情况下发动。自己从牌组抽1张。③：自己将怪兽上级召唤的情况下，可解放对手场上的不死族怪兽作为自己场上怪兽的代替。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37132349,'扰乱怪之红色','此卡召唤成功时可发动。从手牌以攻击表示特殊召唤最多４只“扰乱怪”怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37160778,'天使・魔女','背负着成为天使的命运，却成为了她所向往的魔女。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37164373,'魔幻甜点女王・后冠提拉米苏',replace(replace('等级４“魔幻甜点”怪兽×２\r\n①：１回合１次，去除此卡的１个超量素材，以自己墓地的最多２张“魔幻甜点”卡为对象可以发动。将该卡放回牌组，依所放回的数量为上限，将对手场上的卡放回牌组。','\r',char(13)),'\n',char(10)),'返回牌组','是否要选择对手场上的卡回到牌组？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37168514,'蛇魔・三头犬','①：此卡召唤时可以发动。将自己场上的所有岩石族怪兽的等级改成3。','等级变换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37169670,'高能念力枪手／爆裂',replace(replace('此卡不可通常召唤，仅可通过“爆裂模式”的效果特殊召唤。\r\n①：此卡与对手怪兽进行战斗的伤害步骤结束时发动。同时适用以下效果。\r\n●依该对手怪兽守备力的数值给予对手伤害。\r\n●依该对手怪兽攻击力的数值恢复自己的LP。\r\n②：场上的此卡被破坏时，以自己墓地的1只“高能念力枪手”为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'伤害和回复','特殊召唤「高能念力枪手」','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37192109,'精神骨架装载王 截塔',replace(replace('协调＋１只以上协调以外的怪兽\r\n①：１回合１次，以对手场上１只被特殊召唤的表侧攻击表示怪兽为对象可以发动。将该怪兽和场上的此卡直至下一个自己准备阶段为止除外。此效果在对手回合中也可以发动。②：此卡存在于墓地的情况下，以自己墓地此卡以外的１张“精神骨架”卡为对象可以发动。将此卡放回额外牌组，将对象卡加入手牌。','\r',char(13)),'\n',char(10)),'对手怪兽和此卡除外','「精神骨架」卡回到手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37195861,'元素－英雄 海洋人','①：1回合1次，在自己的准备阶段以自己场上・墓地的1只“-英雄”怪兽为对象可以发动。将自己的该“-英雄”怪兽放回持有者的手牌。','把1只名字带有「－英雄」的怪兽回到持有者手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37198732,'等级大师','可将手牌的１只怪兽送入墓地，并从我方场上选择最多２只表侧表示怪兽发动。直至回合结束时，被选择怪兽的等级变成为发动此卡而送入墓地怪兽的原本等级。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37209439,'误封的契约书',replace(replace('①：1回合1次，自己场上存在“DD”怪兽的情况下可以发动。此回合中，场上其他的陷阱卡的效果无效化。\r\n②：在自己的准备阶段发动。自己受到1000伤害。','\r',char(13)),'\n',char(10)),'效果无效','伤害','是否使用效果？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37231841,'轻量化','１回合１次，可在我方主要阶段发动。将手牌中１只等级７或以上的怪兽加入牌组并洗牌。之后，从牌组抽取１张卡牌。','交换手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37241623,'纹章的记录','对手场上的超量怪兽移除该超量素材并发动效果时可发动。使该发动无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37243151,'天气控制者','可以自由操纵天气，山里变化无常的天气就是这家伙的杰作。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37256135,'梅尔菲追追乐','此卡名的卡１回合仅可发动１张。①：以自己墓地的１只“梅尔菲”怪兽为对象可以发动。将该怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37256334,'娱乐伙伴 卡片守卫',replace(replace('←8 【灵摆】 8→\r\n①：１回合１次，以自己场上的１只表侧守备表示怪兽为对象可以发动。该怪兽的守备力变为自己场上所有表侧守备表示怪兽原本守备力的合计数值。\r\n【怪兽效果】\r\n①：此卡的守备力上升相当于自己场上此卡以外的“娱乐伙伴”怪兽原本守备力的合计数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37260677,'龙王绝火 伟魔琐罗亚',replace(replace('“伟魔”怪兽＋融合・同步・超量・连接怪兽\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：以自己墓地或对手场上的1只效果怪兽为对象可以发动。将该效果怪兽视为装备魔法卡装备于此卡。\r\n②：怪兽的效果发动时，将自己场上的1张表侧表示的“伟魔”怪兽卡送至墓地可以发动。将该效果无效。然后，可将对手场上的1张卡破坏。','\r',char(13)),'\n',char(10)),'装备','效果无效','是否把卡破坏？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37260946,'变形斗士・耳机',replace(replace('协调＋１只以上协调以外的怪兽\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡特殊召唤成功的情况下，以场上的１只表侧表示怪兽为对象可以发动。将该怪兽直至回合结束时为止视为协调。\r\n②：以场上的１只同步怪兽为对象可以发动。从自己场上・墓地，将此卡视为装备卡装备于该怪兽。\r\n③：装备了此卡的怪兽在１次战斗阶段中最多可攻击怪兽２次。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37261776,'转生炎兽 堇色客迈拉',replace(replace('“转生炎兽”怪兽＋连接怪兽\r\n①：此卡融合召唤成功的情况下可以发动。此卡的攻击力直至回合结束时为止，上升相当于作为素材的怪兽的原本攻击力合计数值一半的数值。②：每次此卡与拥有和原本攻击力不同的攻击力的怪兽进行战斗的伤害计算时可以发动1次。此卡的攻击力仅在该伤害计算时变为两倍。③：与以“转生炎兽 堇色客迈拉”作为素材融合召唤的此卡进行战斗的怪兽的攻击力仅在伤害计算时变为0。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37265642,'军刀角龙','以性格温顺而闻名的恐龙。喜欢在大草原的小窝里悠闲地度过。一旦生气会很恐怖。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37267041,'沉默剑士 LV7',replace(replace('此卡不可通常召唤。\r\n只有通过“沉默剑士 LV5”的效果才可特殊召唤此卡。\r\n①：只要此卡存在于怪兽区域，场上的魔法卡效果无效。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37279096,'无垢奥艺－“黄昏之变幻”',replace(replace('此卡名在规则上也视为“神艺”、“终刻”、“耀圣”卡。\r\n此卡名的②效果1回合仅可使用1次。\r\n①：只要自己场上存在“狱神”连接怪兽，原本卡名包含“奥艺”在内的、自己场上的怪兽发动的效果，变为在对手回合也可以发动的效果。\r\n②：只要此卡以表侧表示存在，仅限1次，在自己的主要阶段可以发动。从牌组将1只“墨迪乌斯”怪兽或“奥艺”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','检索效果','已发动过效果','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37279508,'编号37 希望织龙 蜘蛛鲨',replace(replace('水属性等级4怪兽×2\r\n此卡名的①②效果1回合仅可各使用1次。①：自己或对手的怪兽攻击宣言时，去除此卡的1个超量素材可以发动。对手场上的所有怪兽攻击力直至回合结束时为止下降1000。②：此卡因战斗・效果被破坏并被送至墓地时，以自己墓地此卡以外的1只怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'攻击力下降','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37300735,'T.G.喷射猎鹰','此卡作为同步召唤的素材被送至墓地的情况下发动。给予对手LP５００点伤害。','给予对手500伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37310367,'封锁守卫',replace(replace('①：对手怪兽的直接攻击宣言时可发动。从手牌以攻击表示特殊召唤此卡。以此效果特殊召唤而来的此卡，此回合不会因战斗被破坏。\r\n②：仅以我方场上的１只电子界族怪兽为对象之对手场上的怪兽效果发动时，可发动。直至回合结束时，该我方的电子界族怪兽与该对手怪兽的效果被无效化。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37313338,'春化精的历替','此卡名的①②效果１回合仅可各使用１次。①：以自己墓地的１只“春化精”怪兽为对象可以发动。将该怪兽加入手牌或特殊召唤。②：自己的手牌为０张的情况下，在对手回合中，将墓地的此卡除外可以发动。从自己的墓地尽可能多地将“春化精”怪兽特殊召唤（同名卡最多１张）。以此效果特殊召唤的怪兽将在自己的结束阶段放回持有者的手牌。此效果在此卡被送至墓地的回合不可发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37313348,'龟虎','身着龟甲的老虎。利用坚固的龟甲护身，并以尖锐的利牙发动攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37313786,'赌博','对手手牌为６张或以上，并且我方手牌为２张或以下的场合可发动。掷１次硬币猜正反面。猜中的场合，可从牌组抽取卡牌直至我方手牌达到５张为止。猜错的场合，跳过下一次的我方回合。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37318031,'R－公平正义','①：依自己场上“元素-英雄”卡的数量，挑选场上的魔法・陷阱卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37322745,'大植然森林','①：将对手的怪兽效果・魔法・陷阱卡的发动无效了的情况下可以发动。从牌组将１只等级３以下的“大植然”怪兽加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37337327,'废品连结者',replace(replace('包含1只以上协调在内的战士族・机械族效果怪兽2只\r\n①：1回合1次，自己・对手的主要阶段及战斗阶段可以发动。仅以此卡连接端的怪兽作为素材同步召唤。②：连接召唤的此卡因战斗或对手的效果被破坏并被送至墓地的情况下可以发动。从额外牌组将1只“废品”同步怪兽特殊召唤，且视为同步召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37343995,'驱魔姐妹・玛尔法',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：自己场上的怪兽，不存在的情况下或仅有超量怪兽的情况下可以发动（发动此效果的回合中，自己仅可特殊召唤“驱魔姐妹”怪兽）。从手牌将此卡特殊召唤，从牌组将1只“驱魔姐妹・以利斯”特殊召唤。\r\n②：有自己或对手的卡从墓地离开的情况下可以发动。从额外牌组将1只“驱魔姐妹”超量怪兽重叠在自己场上的此卡上面，视为超量召唤特殊召唤。','\r',char(13)),'\n',char(10)),'','当作超量召唤从额外牌组特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37349495,'大植然茄子','此卡从场上被送入墓地时可发动。将我方墓地的１只除“大植然茄子”以外的冠有“大植然”之名的怪兽加入手牌。','加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37351133,'闪刀姬－萝杰',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：“闪刀姬－萝杰”以外的“闪刀姬”怪兽被召唤・特殊召唤的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：此卡存在于墓地的状态下，额外怪兽区域的对手怪兽因战斗被破坏的情况下，或因自己的卡的效果从场上离开的情况下可以发动。将此卡特殊召唤。然后，可将对手场上的1只表侧表示怪兽的效果直至回合结束时为止无效。','\r',char(13)),'\n',char(10)),'此卡从手牌特殊召唤','此卡从墓地特殊召唤','是否选对手怪兽效果无效？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37351134,'闪刀姬－萝杰',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：“闪刀姬－萝杰”以外的“闪刀姬”怪兽被召唤・特殊召唤的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：此卡存在于墓地的状态下，额外怪兽区域的对手怪兽因战斗被破坏的情况下，或因自己的卡的效果从场上离开的情况下可以发动。将此卡特殊召唤。然后，可将对手场上的1只表侧表示怪兽的效果直至回合结束时为止无效。','\r',char(13)),'\n',char(10)),'此卡从手牌特殊召唤','此卡从墓地特殊召唤','是否选对手怪兽效果无效？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37351135,'闪刀姬－萝杰',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：“闪刀姬－萝杰”以外的“闪刀姬”怪兽被召唤・特殊召唤的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：此卡存在于墓地的状态下，额外怪兽区域的对手怪兽因战斗被破坏的情况下，或因自己的卡的效果从场上离开的情况下可以发动。将此卡特殊召唤。然后，可将对手场上的1只表侧表示怪兽的效果直至回合结束时为止无效。','\r',char(13)),'\n',char(10)),'此卡从手牌特殊召唤','此卡从墓地特殊召唤','是否选对手怪兽效果无效？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37354507,'忍者头领 才藏',replace(replace('“忍者”怪兽２只\r\n此卡名的②效果１回合仅可使用１次。\r\n①：只要此卡的连接端存在怪兽，此卡不会成为攻击对象，不会成为对手效果的对象。\r\n②：在自己的主要阶段可以发动。从牌组挑选１张“忍法”魔法・陷阱卡，放置在自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37364101,'克己挑战','仅可装备于持有超量素材的超量怪兽。①：“克己挑战”在自己场上仅可有１张以表侧表示存在。②：装备怪兽不可发动效果，攻击力上升相当于自己场上超量素材数量×６００的数值，因与对手怪兽战斗而给予对手的战斗伤害变为两倍。③：在对手的结束阶段发动。将此卡送至墓地。④：装备于怪兽的此卡离开场上时，装备怪兽将被破坏。','送至墓地','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37383714,'魂之绳索','当我方场上的怪兽因卡牌效果而被破坏送入墓地时，可支付１０００点LP发动此卡。从牌组中特殊召唤１只等级４怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37390589,'锁链飞镖',replace(replace('①：从以下效果中选择1个或者两者，可以发动此卡。\r\n●对手怪兽攻击宣言时，可以1只该攻击怪兽为对象发动。将该攻击怪兽变成守备表示。\r\n●可以自己场上的1只表侧表示的怪兽为对象发动。此卡视为攻击力上升500的装备卡，装备该自己的怪兽。','\r',char(13)),'\n',char(10)),'把攻击怪兽变成守备表示','变成装备卡','两个效果都使用','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37390590,'锁链飞镖',replace(replace('①：从以下效果中选择1个或者两者，可以发动此卡。\r\n●对手怪兽攻击宣言时，可以1只该攻击怪兽为对象发动。将该攻击怪兽变成守备表示。\r\n●可以自己场上的1只表侧表示的怪兽为对象发动。此卡视为攻击力上升500的装备卡，装备该自己的怪兽。','\r',char(13)),'\n',char(10)),'把攻击怪兽变成守备表示','变成装备卡','两个效果都使用','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37405032,'淘气仙星・水葵天使',replace(replace('此卡名在规则上也视为“海晶少女”卡。\r\n此卡名的①③效果在决斗中仅可各使用１次。\r\n①：自己场上存在“淘气仙星”怪兽或“海晶少女”怪兽的情况下可以发动。从手牌・墓地将此卡特殊召唤。\r\n②：连接端指向此卡的连接怪兽不会因战斗被破坏。\r\n③：此卡作为连接素材被送至墓地的情况下可以发动。确认对手的手牌・场上（里侧表示）的所有卡。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37406863,'封神镜','观看对手手牌。手牌中有灵魂怪兽存在的场合，选择１只灵魂怪兽并弃置至墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37412656,'英雄炸裂','①：以自己墓地的1只“元素－英雄”通常怪兽为对象可以发动。将该怪兽加入手牌。对手场上存在攻击力在所加入手牌的怪兽的攻击力以下的怪兽的情况下，进而将其中1只破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37414347,'方程式运动员 辉耀明星・超跑级',replace(replace('机械族怪兽2只\r\n此卡名的④效果1回合仅可使用1次。①：此卡的攻击力上升相当于此卡连接端的“方程式运动员”怪兽等级合计×300的数值。②：因此卡的战斗对双方造成的战斗伤害变为0。③：“方程式运动员”魔法・陷阱卡的效果发动的情况下发动。在此卡上放1个运动员计数物。④：对手发动怪兽效果时，去除此卡的1个运动员计数物可以发动。将该发动无效并破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37421075,'强制退化','可释放我方场上１只等级４或以上的恐龙族怪兽并发动。从我方手牌、墓地挑选２只等级３或以下的爬虫类族怪兽并特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37421579,'炎之骑士 基拉','“怪兽蛋”＋“史汀格”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37426272,'原物质・艾可萨环蜥',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：向对手出示手牌的此卡，并从手牌舍弃1张其他卡可以发动。从自己牌组・墓地将所舍弃的卡以外的1只等级3通常怪兽加入手牌。然后，可将此卡以守备表示特殊召唤。\r\n②：在自己・对手回合中，从手牌将此卡舍弃，以自己场上的1只阶级3超量怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止上升1500。','\r',char(13)),'\n',char(10)),'加入手牌','攻击力上升','是否将此卡特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37432075,'召唤魔术－“剑”',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：以自己场上的怪兽作为融合素材，将1只融合怪兽融合召唤。要融合召唤“召唤兽”融合怪兽的情况下，也可将自己・对手除外状态的怪兽放回墓地来作为融合素材。\r\n②：在自己的主要阶段，此卡存在于墓地的情况下，以自己墓地的1只“阿莱斯特”怪兽或1张“召唤魔术”为对象可以发动。将此卡放回牌组，将对象卡加入手牌。','\r',char(13)),'\n',char(10)),'融合召唤','回收效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37433748,'秘旋谍装备－绝地胜机',replace(replace('①：以自己场上的１只“秘旋谍”怪兽为对象可以发动。从自己手牌・场上将此怪兽视为装备魔法卡，装备于该自己的怪兽。装备怪兽不会因战斗・效果被破坏，对手不可将装备怪兽作为效果的对象。\r\n②：１回合１次，此卡是以此卡的效果被装备中的情况下，将自己场上的１张其他卡送至墓地可以发动。此回合，装备怪兽可直接攻击。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37436476,'炎热旋风壁','我方场上冠有“岩浆炎”之名怪兽的攻击力，上升我方墓地冠有“岩浆炎”之名怪兽的数量×１００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37440988,'究极宝玉神 彩虹超越龙',replace(replace('“宝玉兽”怪兽×７\r\n此卡仅可以融合召唤及以下方法特殊召唤。\r\n●解放了我方场上的１只等级１０的“究极宝玉神”怪兽的场合，可从额外牌组特殊召唤（不需要“融合”）。\r\n①：１回合１次，可从我方墓地将１只“宝玉兽”怪兽除外并发动。直至回合结束时，此卡的攻击力上升被除外怪兽的攻击力数值。\r\n②：可解放融合召唤的此卡并发动。将场上的所有卡牌返回至持有者牌组。此效果也可在对手回合发动。','\r',char(13)),'\n',char(10)),'上升攻击力','回到牌组','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37442336,'宇宙类星龙',replace(replace('同步怪兽的协调＋协调以外的同步怪兽２只以上\r\n此卡从额外牌组仅可通过以上述卡作为同步素材的同步召唤来特殊召唤。\r\n①：１回合１次，以场上的表侧表示卡为对象可以发动，数量最多为作为此卡同步素材的怪兽数量＋１张（此效果的发动和效果不会被无效化）。将该卡的效果无效。\r\n②：在自己・对手回合中，将同步召唤的此卡除外可以发动。将１只、需以协调以外的同步怪兽２只以上作为素材的龙族同步怪兽视为同步召唤从额外牌组特殊召唤。','\r',char(13)),'\n',char(10)),'场上的卡效果无效','此卡除外并同步召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37444964,'梦魔镜之梦物语','此卡名的卡1回合仅可发动1张。①：自己场上有“梦魔镜”怪兽存在的情况下，以被除外的自己的“圣光之梦魔镜”、“暗黑之梦魔镜”各1张为对象可以发动。将该卡放回牌组，挑选场上的1张卡除外。②：自己场上的“梦魔镜”卡将被战斗・效果破坏的情况下，可将墓地的此卡除外作为代替。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37445295,'影依・隼','此卡名的①②效果1回合1次，仅可使用其中1个。①：在此卡反转的情况下，可以自己墓地的1只“影依・隼”以外的“影依”怪兽为对象发动。以里侧守备表示将该怪兽特殊召唤。②：在此卡因效果被送至墓地的情况下可以发动。以里侧守备表示将此卡特殊召唤。','特殊召唤「影依」怪兽','特殊召唤此卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37457534,'古代机械齿轮战车','仅限装备冠有“古代机械齿轮”之名的怪兽。装备怪兽的攻击力上升６００点。此卡被破坏并送入墓地时，给予对手生命６００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37458564,'电子界契约女巫',replace(replace('相同种族的怪兽2只\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡连接召唤的情况下，或有怪兽被特殊召唤至此卡连接端的情况下，从自己手牌・场上（表侧表示）将1张魔法卡送至墓地可以发动。从牌组将1只仪式怪兽加入手牌。\r\n②：以此卡连接端的1只仪式・融合・同步・超量怪兽为对象可以发动。从自己墓地将1只与该怪兽种类（仪式・融合・同步・超量）不同、种族相同的怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'检索仪式怪兽','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37458565,'电子界契约女巫',replace(replace('相同种族的怪兽2只\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡连接召唤的情况下，或有怪兽被特殊召唤至此卡连接端的情况下，从自己手牌・场上（表侧表示）将1张魔法卡送至墓地可以发动。从牌组将1只仪式怪兽加入手牌。\r\n②：以此卡连接端的1只仪式・融合・同步・超量怪兽为对象可以发动。从自己墓地将1只与该怪兽种类（仪式・融合・同步・超量）不同、种族相同的怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'检索仪式怪兽','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37469904,'决斗者降临',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：自己或对手的灵摆区域存在卡的情况下可以发动。从牌组将１只“灵摆”灵摆怪兽或１张“灵摆”魔法・陷阱卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37474917,'弹射战士',replace(replace('协调+1只以上协调以外的怪兽\r\n①：1回合1次，解放自己场上的1只“废品”怪兽可以发动。给予对手相当于解放的怪兽原本攻击力数值的伤害。','\r',char(13)),'\n',char(10)),'伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37478723,'『焰圣剑－杜兰德尔』','此卡名的①②效果１回合１次，仅可使用其中１个。①：此卡被装备中的情况下可以发动。从牌组将１只等级５以下的战士族・炎属性怪兽加入手牌。然后破坏此卡。②：因装备怪兽被送至墓地导致此卡被送至墓地的情况下，以自己墓地１只等级５以下的战士族・炎属性怪兽为对象可以发动。将该怪兽特殊召唤。此效果发动后，直至回合结束时为止自己仅可特殊召唤战士族怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37480144,'瞬间转移','①：以自己主要怪兽区域的１只怪兽为对象可以发动。将该自己怪兽的位置移动至自己的其他主要怪兽区域。','请选择要移动位置的怪兽','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37491810,'混炼装・水银要塞',replace(replace('←8 【灵摆】 8→\r\n此卡名的灵摆效果１回合仅可使用１次。\n①：自己场上表侧表示的“炼装”卡因效果被破坏的情况下，以场上的１张表侧表示卡为对象可以发动。将该卡破坏。\r\n【怪兽效果】\r\n“炼装”怪兽＋融合怪兽\n此卡名的①怪兽效果１回合仅可使用１次。\n①：此卡从额外牌组的特殊召唤成功的情况下，以对手场上的１张卡为对象可以发动。从自己的额外牌组将２只表侧表示的灵摆怪兽放回牌组，破坏对象卡。\n②：怪兽区域的此卡被破坏的情况下可以发动。将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37495766,'救援王牌 爆流涡轮机',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：从自己墓地将2张“救援王牌”卡除外可以发动。从手牌将此卡特殊召唤。\r\n②：在自己的主要阶段可以发动。从牌组将最多4张“救援王牌”速攻魔法・通常陷阱卡放置在自己场上（同名卡最多1张）。\r\n③：自己场上的其他卡因对手的效果从场上离开的情况下，以场上的1张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','','破坏场上1张卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37495767,'救援王牌 爆流涡轮机',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：从自己墓地将2张“救援王牌”卡除外可以发动。从手牌将此卡特殊召唤。\r\n②：在自己的主要阶段可以发动。从牌组将最多4张“救援王牌”速攻魔法・通常陷阱卡放置在自己场上（同名卡最多1张）。\r\n③：自己场上的其他卡因对手的效果从场上离开的情况下，以场上的1张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','','破坏场上1张卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37507488,'怪兽救援','可在对手怪兽进行攻击宣言时发动此卡。将我方场上的１只怪兽收回到手牌中，之后从手牌特殊召唤１只等级４的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37511832,'魔藻海的灯塔','给予自己伤害的魔法卡的效果发动时可以发动。自己因该效果将受到的效果伤害变为０。此外，只要此卡存在于墓地，自己因“异次元的古战场－魔藻海”的效果将受到的效果伤害变为０。被放置的此卡被送至墓地时可以发动。从牌组将１张“异次元的古战场－魔藻海”加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37517035,'神艺杰作－继承－',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己・对手的主要阶段可以发动。以包含“神艺”怪兽在内的、自己手牌・场上的怪兽作为融合素材，将1只融合怪兽融合召唤。场地区域存在卡的情况下，进而以此效果特殊召唤的怪兽的攻击力上升500。\r\n②：在自己的主要阶段将墓地的此卡除外，以自己墓地的3张“神艺”卡为对象可以发动（同名卡最多1张）。将该卡放回牌组。','\r',char(13)),'\n',char(10)),'融合召唤','回到牌组','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37520316,'精神操作','①：以对手场上的1只怪兽为对象可以发动。获得该怪兽的控制权，直至结束阶段为止。以此效果获得了其控制权的怪兽不可攻击宣言，不可解放。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37531679,'飞龙炎 沙罗曼龙',replace(replace('此卡名的①③效果１回合仅可各使用１次。\r\n①：此卡存在于手牌・墓地的情况下，以自己场上的１只战士族怪兽为对象可以发动。将此卡视为装备魔法卡，装备于该自己的怪兽。\r\n②：只要此卡被装备于“炎之剑士”或记载有该卡名的怪兽，装备怪兽的攻击力上升７００。\r\n③：此卡被送至墓地的情况下可以发动。从牌组将１张“沙罗曼龙”魔法・陷阱卡加入手牌。','\r',char(13)),'\n',char(10)),'装备效果','检索「炎之军刀」魔法·陷阱卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37534148,'复活缎带','装备怪兽因战斗被破坏并送入墓地场合，此回合的结束阶段时特殊召唤该怪兽至我方场上。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37542782,'铠皇龙－电子暗黑终极龙',replace(replace('“铠黑龙－电子暗黑龙”＋“电子终极龙”\r\n此卡仅可以融合召唤及以下方法特殊召唤。\r\n●解放1只装备有“电子终极龙”的、自己的等级10以下的“电子暗黑”融合怪兽的情况下，可从额外牌组特殊召唤。\r\n①：此卡不受对手发动的效果影响。\r\n②：1回合1次，可以发动。将自己或对手墓地的1只怪兽视为装备魔法卡装备于此卡。\r\n③：此卡在1次战斗阶段中可攻击的次数最多为此卡装备卡的数量。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37552929,'千年月辉少女',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡存在于手牌的情况下可以发动。将此卡视为永续魔法卡，以表侧表示放在自己的魔法与陷阱区域。\r\n②：此卡视为永续魔法卡的状态下，对手的效果发动的情况下可以发动。将此卡特殊召唤，此回合中，对手不可将自己场上等级５以上的幻想魔族・魔法师族怪兽作为效果的对象。\r\n③：此卡与怪兽进行战斗的情况下，该２只不会因该战斗被破坏。','\r',char(13)),'\n',char(10)),'当作魔法卡放置','特殊召唤','「仟年月明少女」效果适用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37557626,'咒仪杀手','此卡召唤、反转召唤成功时可发动。我方场上存在有除此卡以外的冠有“咒仪”之名的怪兽的场合，选择我方场上除此卡以外的１只怪兽返回至持有者手牌。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37561138,'死灵谷的宝座',replace(replace('此卡牌名的卡牌１回合只可发动１张。\r\n①：可从以下效果选择１个并发动。\r\n●从牌组将１只“守墓”怪兽加入手牌。\r\n●从手牌召唤１只“守墓”怪兽。','\r',char(13)),'\n',char(10)),'从牌组把1只「守墓」怪兽加入手牌','从手牌把1只「守墓」怪兽召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37576645,'无谋的贪欲','①：自己从牌组抽2张，然后跳过自己的2次抽牌阶段。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37580756,'同路人','①：怪兽因战斗被破坏送入我方墓地时，或场上的怪兽被送入我方墓地时，可以场上的１只怪兽为对象并发动。破坏该怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37582948,'直播☆双子 麻烦桑','此卡名的卡１回合仅可发动１张。①：作为此卡发动时的效果处理，可从牌组将１只“直播☆双子”怪兽加入手牌。②：只要自己场上有“邪恶★双子”怪兽存在，每次对手召唤・特殊召唤怪兽，自己恢复２００LP，给予对手２００伤害。','是否从牌组把1只「直播☆双子」怪兽加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37613663,'仟年十字','①：挑选自己的手牌・牌组・场上（表侧表示）的５张“被封印”怪兽卡，双方确认。然后，从额外牌组将１只“幻之召唤神 艾克佐迪亚”特殊召唤。除“仟年”怪兽卡、“千年”怪兽卡、原本等级为１０以上的“艾克佐迪亚”怪兽卡以外的、表侧表示的怪兽卡存在于自己场上的情况下，进而将那些全部放回牌组。此回合，自己不可将怪兽召唤・反转召唤・特殊召唤。发动后此卡不送至墓地，而是放回牌组。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37617348,'救援王牌 消防栓',replace(replace('此卡名的②③效果1回合仅可各使用1次。\r\n①：只要自己场上存在“救援王牌 消防栓”以外的“救援王牌”怪兽，对手怪兽不可将此卡选择为攻击对象，对手也不可将此卡作为效果的对象。\r\n②：只要此卡存在于怪兽区域，以自己的“救援王牌”卡的效果放置的速攻魔法・陷阱卡有1张在放置的回合也可以发动。\r\n③：在自己的主要阶段可以发动。从牌组将“救援王牌 消防栓”以外的1只“救援王牌”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','适用「救援王牌 消防栓」的效果来发动','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37620434,'恶魔驯服师','反转：选择对手场上的１只恶魔族怪兽，直至结束阶段为止获得该控制权。','控制权转移','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37626500,'精灵的祝福','光属性仪式怪兽的降临所必需。①：为使合计等级与仪式召唤的怪兽相等，解放自己的手牌・场上的怪兽，从手牌将１只光属性仪式怪兽仪式召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37629703,'拉比丽斯的龙饰灯','此卡名的①②效果１回合仅可各使用１次。①：将手牌・场上的此卡送至墓地，舍弃１张手牌可以发动。从手牌・牌组挑选１张“拉比丽斯”魔法・陷阱卡放置在自己场上。此效果在对手回合中也可以发动。②：此卡存在于墓地的状态下，怪兽因自己通常陷阱卡的效果从场上离开的情况下可以发动。将此卡加入手牌。','','此卡加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37630732,'力量焊接','①：从自己的手牌・场上，将由机械族的融合怪兽卡决定的融合素材怪兽送至墓地，从额外牌组将1只该融合怪兽融合召唤。以此效果特殊召唤的怪兽的攻击力上升其原本攻击力的数值。发动了此卡的回合的结束阶段，自己将受到等同于以此效果上升的数值的伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37649320,'伯吉斯吸虫・欧巴宾海蝎',replace(replace('等级2怪兽×2\r\n此卡名的③效果1回合仅可使用1次。\r\n①：场上的此卡不受其他怪兽的效果影响。\r\n②：只要此卡存在于怪兽区域，自己可从手牌发动“伯吉斯吸虫”陷阱卡。\r\n③：此卡持有陷阱卡作为超量素材的情况下，去除此卡的1个超量素材可以发动。从牌组将1张“伯吉斯吸虫”陷阱卡加入手牌。','\r',char(13)),'\n',char(10)),'','适用「伯吉斯吸虫·欧巴宾海蝎」的效果来发动','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37654623,'天空城塞 库龙',replace(replace('此卡名的②③效果1回合仅可各使用1次。\r\n①：被从手牌召唤・特殊召唤的自己场上的怪兽的攻击力・守备力上升500。\r\n②：在自己的主要阶段可以发动。将1只“机兽衍生物”（机械族・地・星6・攻/守2000）特殊召唤至对手场上，从牌组将1只“雷盟”怪兽加入手牌。\r\n③：此卡存在于墓地的状态下，以自己的“雷盟”卡的效果破坏了卡的情况下可以发动。将此卡加入手牌。','\r',char(13)),'\n',char(10)),'','特殊召唤并检索','回到手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37654624,'机兽衍生物','由「天空城塞 库龙」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37663536,'古代机械齿轮・超巨人',replace(replace('“古代机械齿轮”怪兽×３\r\n①：此卡攻击的情况下，对手直至伤害步骤结束时为止，不可发动魔法・陷阱卡。\r\n②：从“古代机械齿轮巨人”、“古代机械齿轮巨人－究极重拳”中的合计２只以上作为素材融合召唤的此卡，在１次战斗阶段中最多可攻击相当于其数量的次数。\r\n③：融合召唤的表侧表示的此卡因对手的效果从场上离开的情况下可以发动。从额外牌组将１只“古代机械齿轮究极巨人”无视召唤条件特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤「古代机械齿轮究极巨人」','「古代机械齿轮超巨人」效果适用中','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37675138,'骨粉碎者','此卡因不死族怪兽的效果从我方墓地被特殊召唤时，可选择对手场上的１张魔法、陷阱卡破坏。在特殊召唤此卡回合的结束阶段发动。破坏此卡。','破坏','自坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37675907,'加速同步士',replace(replace('协调+1只以上协调以外的怪兽\r\n自己1回合仅可同步召唤1次“加速同步士”。①：1回合1次，从牌组将1只“同步士”怪兽送至墓地，可从以下效果中选择1个发动。\r\n●此卡的等级上升相当于送至墓地的该怪兽的等级的数值。\r\n●此卡的等级下降相当于送至墓地的该怪兽的等级的数值。\r\n②：在对手的主要阶段可以发动。将包括此卡在内的自己场上的怪兽作为同步素材同步召唤。','\r',char(13)),'\n',char(10)),'等级改变','同步召唤','等级上升','等级下降','','','','','','','','','','','','');
INSERT INTO texts VALUES(37678339,'梦魔镜魇魔－涅伊洛斯',replace(replace('属性不同的“梦魔镜”怪兽×２\r\n此卡名的②③效果１回合仅可各使用１次。①：只要此卡存在于怪兽区域，此卡的属性也视为“光”。②：场地区域有“暗黑之梦魔镜”存在，怪兽的效果发动时可以发动。将该效果无效。③：场地区域有“圣光之梦魔镜”存在的情况下，解放此卡可以发动。从额外牌组将１只“梦魔镜天魔－涅伊洛斯”以守备表示特殊召唤。此效果在对手回合中也可以发动。','\r',char(13)),'\n',char(10)),'效果无效','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37679169,'星际仙踪－穿梭机',replace(replace('①：１回合１次，从牌组将１只“星际仙踪”怪兽送至墓地，以场上的１只表侧表示怪兽为对象可以发动。对象怪兽的攻击力・守备力下降相当于为发动此效果送至墓地的怪兽等级×１００的数值。\r\n②：此卡因战斗・效果被破坏并被送至墓地的情况下，将墓地的此卡除外可以发动。从牌组将１只等级４以下的“星际仙踪”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37683441,'淘气仙星・高贵蓝天使',replace(replace('“淘气仙星”怪兽２只\r\n此卡名的①②③效果１回合仅可各使用１次。\r\n①：此卡连接召唤的情况下可以发动。从牌组将１张“青泪”卡加入手牌。\r\n②：自己的场上或墓地存在融合怪兽的情况下，以自己墓地的１只“淘气仙星”怪兽为对象可以发动。将该怪兽特殊召唤。\r\n③：自己或对手受到效果伤害的情况下，以场上的１张表侧表示卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'检索「青泪」卡','苏生效果','破坏效果','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37683547,'灰烬的阿尔白斯','此卡名的③效果１回合仅可使用１次。①：此卡只要存在于场上・墓地，卡名视为“阿尔白斯之落胤”。②：只要自己墓地存在等级８的融合怪兽，此卡的攻击力上升相当于自己墓地的怪兽数量×２００的数值，自己场上此卡以外的怪兽不会成为对手效果的对象。③：此卡和融合怪兽存在于自己墓地的状态下，自己场上的怪兽因对手的效果从场上离开的情况下可以发动。将此卡特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37684215,'融合武器村雨刀','仅限装备战士族怪兽。装备怪兽的攻击力上升８００点。装备状态的此卡不会因卡牌效果被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37694547,'齿轮镇','①：此卡只要存在于场地区域，双方玩家召唤“古代机械齿轮”怪兽的情况下所必须的解放数量可减少１只。②：此卡被破坏并被送至墓地时可以发动。从自己的手牌・牌组・墓地挑选１只“古代机械齿轮”怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37706769,'冥府之执行者 普鲁特',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名在规则上也视为“代行者”卡。\r\n此卡名的②效果1回合仅可使用1次。\r\n①：1回合1次，从自己墓地将1只怪兽除外，以场上的1只效果怪兽为对象可以发动（自己或对手的、场上或墓地存在“天空的圣域”的情况下，此效果在对手回合中也可以发动）。将该怪兽改成里侧守备表示。\r\n②：将墓地的此卡除外可以发动。从自己牌组・墓地将1张“天空的圣域”加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37720300,'星舰调控机',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：以自己场上的1只其他的机械族怪兽为对象可以发动。直至回合结束时为止，将该怪兽和此卡的等级变为两只的等级合计的等级。此效果发动后，直至回合结束时为止，自己从额外牌组仅可特殊召唤机械族超量怪兽。','\r',char(13)),'\n',char(10)),'等级变换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37721209,'海龙－代达罗斯','①：将自己场上的1张表侧表示的“海”送至墓地可以发动。将场上的其他卡全部破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37742478,'奥尼斯特',replace(replace('①：在自己的主要阶段可以发动。将场上表侧表示的此卡放回手牌。\r\n②：自己的光属性怪兽进行战斗的伤害步骤开始时至伤害计算前为止，从手牌将此卡送至墓地可以发动。该怪兽的攻击力直至回合结束时为止，上升相当于进行战斗的对手怪兽的攻击力的数值。','\r',char(13)),'\n',char(10)),'返回手牌','攻击上升','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37742479,'奥尼斯特',replace(replace('①：在自己的主要阶段可以发动。将场上表侧表示的此卡放回手牌。\r\n②：自己的光属性怪兽进行战斗的伤害步骤开始时至伤害计算前为止，从手牌将此卡送至墓地可以发动。该怪兽的攻击力直至回合结束时为止，上升相当于进行战斗的对手怪兽的攻击力的数值。','\r',char(13)),'\n',char(10)),'返回手牌','攻击上升','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37744402,'风灵使 薇茵','①：此卡反转的情况下，以对手场上的1只风属性怪兽为对象发动。此怪兽以表侧表示存在期间，获得对象怪兽的控制权。','获得对手场上1只风属性怪兽的控制权','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37744403,'风灵使 薇茵','①：此卡反转的情况下，以对手场上的1只风属性怪兽为对象发动。此怪兽以表侧表示存在期间，获得对象怪兽的控制权。','获得对手场上1只风属性怪兽的控制权','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37744404,'风灵使 薇茵','①：此卡反转的情况下，以对手场上的1只风属性怪兽为对象发动。此怪兽以表侧表示存在期间，获得对象怪兽的控制权。','获得对手场上1只风属性怪兽的控制权','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37745740,'娱乐伙伴弩弓蝗虫',replace(replace('“娱乐伙伴弩弓蝗虫”的①②效果１回合只可各使用１次。\r\n①：可释放我方场上的１只“娱乐伙伴”怪兽并发动。给予对手相当于被释放怪兽等级×１００的战斗伤害。\r\n②：可释放我方场上的１只“娱乐伙伴”怪兽，并以我方墓地１只除释放怪兽以外的“娱乐伙伴”怪兽为对象发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'效果伤害','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37745919,'废品BOX','从我方墓地中选择１只等级４以下的冠有“变形斗士”之名的怪兽并特殊召唤。以此效果效果特殊召唤的怪兽会在该回合的结束阶段时被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37750912,'星尘照耀','此卡名的①②效果１回合仅可各使用１次。①：从牌组将１只“星尘”怪兽送至墓地。自己场上有“星尘龙”或记载有该卡名的同步怪兽存在的情况下，也可不送至墓地而是改成将其特殊召唤。②：将墓地的此卡除外，以自己场上的１只“星尘”怪兽为对象可以发动。该怪兽的等级直至回合结束时为止上升或下降１。','','等级上升','等级下降','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37752990,'机动雾龙・角龙',replace(replace('←3 【灵摆】 3→\r\n①：自己场上的其他“机动雾龙”卡将被战斗或对手的效果破坏的情况下，作为代替可将此卡破坏。\r\n【怪兽效果】\r\n①：自己场上的怪兽均为“机动雾龙・角龙”以外的“机动雾龙”怪兽的情况下，此卡可从手牌中特殊召唤。','\r',char(13)),'\n',char(10)),'是否要使用「机动雾龙·角龙」的效果代替破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37780349,'命运－英雄 爆破魔侠','①：怪兽进行战斗的伤害计算时，从手牌将此卡舍弃可以发动。因该战斗发生的对自己的战斗伤害变为0，双方玩家受到1000伤害。②：将墓地的此卡除外，以自己场上的1只“命运-英雄”怪兽为对象可以发动。该怪兽的攻击力直至下一个对手回合结束时为止上升1000。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37781520,'水精鳞－利兹深渊','可从手牌将除此卡以外的３只水属性怪兽舍弃至墓地并发动。从手牌特殊召唤此卡。以此效果特殊召唤成功时可发动。从我方墓地选择１张冠有“邃渊”之名的魔法、陷阱卡加入手牌。此外，可释放我方场上１只除此卡以外的冠有“水精鳞”之名的攻击表示怪兽并发动。随机将对手的１张手牌送入墓地。“水精鳞－利兹深渊”的此效果１回合只可使用１次。','特殊召唤','魔陷回收','手牌送墓','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37792478,'代谢鲨鱼','此卡召唤成功时可发动。选择我方墓地的２只鱼族怪兽并返回至牌组。','返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37798171,'深海鲨','我方场上不存在有怪兽的场合，此卡可无需释放进行召唤。对手的准备阶段时仅１次，直至回合结束时，此卡的攻击力变成２倍。','不解放怪兽进行召唤','攻击上升','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37799519,'星尘同步士',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡存在于手牌・墓地的情况下，解放自己场上的1只怪兽可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。此效果发动后，直至回合结束时为止，自己从额外牌组仅可特殊召唤同步怪兽。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从牌组将1张记载有“星尘龙”卡名的魔法・陷阱卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37803172,'阳炎兽 雄鹿飞鸟','此卡除了冠有“阳炎兽”之名的怪兽的效果以外不可特殊召唤。只要此卡以表侧表示存在于场上，对手不可将此卡作为卡牌效果的对象。此外，可将手牌的１只炎属性怪兽送入墓地，释放此卡并发动。从牌组特殊召唤２只冠有“阳炎兽”之名的怪兽。“阳炎兽 雄鹿飞鸟”的此效果１回合只可使用１次。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37803970,'惊奇灵摆',replace(replace('“惊奇灵摆”１回合仅可发动１张。\r\n①：自己的灵摆区域不存在卡的情况下可以发动。从自己的额外牌组将２只卡名不同的表侧表示“魔术师”灵摆怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37806313,'冰结界的运输部队','①：１回合１次，以自己墓地的２只“冰结界”怪兽为对象可以发动。将该２只怪兽放回牌组。然后，双方各抽１张。','回牌组并且抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37812118,'圣杯Ace','①：掷1次硬币。正面的情况下，自己抽2张。背面的情况下，对手抽2张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37818794,'超魔导龙骑士－真红眼龙骑兵',replace(replace('“黑魔导”＋“真红眼黑龙”或龙族效果怪兽\r\n①：此卡不会因效果被破坏，双方不可将此卡作为效果的对象。\r\n②：在自己的主要阶段可以发动（此效果在1回合中可使用的次数最多为作为此卡融合素材的通常怪兽的数量）。破坏对手场上的1只怪兽，给予对手相当于其原本攻击力数值的伤害。\r\n③：1回合1次，卡的效果发动时，舍弃1张手牌可以发动。将该发动无效并破坏，此卡的攻击力上升1000。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37818795,'超魔导龙骑士－真红眼龙骑兵',replace(replace('“黑魔导”＋“真红眼黑龙”或龙族效果怪兽\r\n①：此卡不会因效果被破坏，双方不可将此卡作为效果的对象。\r\n②：在自己的主要阶段可以发动（此效果在1回合中可使用的次数最多为作为此卡融合素材的通常怪兽的数量）。破坏对手场上的1只怪兽，给予对手相当于其原本攻击力数值的伤害。\r\n③：1回合1次，卡的效果发动时，舍弃1张手牌可以发动。将该发动无效并破坏，此卡的攻击力上升1000。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37820550,'电击鞭','仅限装备雷族怪兽。令１只装备怪兽的攻击力和守备力上升３００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37829468,'RAI－JIN','只要此卡以表侧表示存在于场上，我方场上的光属性怪兽攻击力上升相当于我方墓地的光属性怪兽数量×１００点。此外，每次在我方的结束阶段发动。选择我方场上的１只光属性怪兽破坏。场上只可有１只“RAI－JIN”以表侧表示存在。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37839434,'剑艮鬼之神域',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：可从以下效果中选择1个发动。\r\n●此卡变为通常怪兽（水族・协调・水・星1・攻/守0），特殊召唤至怪兽区域（不视为陷阱卡）。然后，可进行1只同步怪兽的同步召唤。\r\n●对手发动魔法・陷阱卡的效果时，如果对手场上不存在里侧表示卡则可以发动。将该效果无效。','\r',char(13)),'\n',char(10)),'发动','当作怪兽特殊召唤','效果无效','是否同步召唤？','','','','','','','','','','','','');
INSERT INTO texts VALUES(37869028,'三头毒蛇','此卡在１次的攻击阶段中可攻击３次。此卡必须释放我方场上的１只水族怪兽才可进行攻击宣言。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37880706,'怠惰小奇美拉',replace(replace('炎属性怪兽2只\r\n这个卡名的②的效果1个回合只能使用1次。①：场上的炎属性怪兽的攻击力・守备力上升500，水属性怪兽的攻击力・守备力下降400。②：这张卡被战斗・效果破坏的情况下，可以自己墓地1只炎属性怪兽为对象发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37890974,'空牙团的修炼','这个卡名的①的效果1个回合只可使用1次。①：自己场上的“空牙团”怪兽通过战斗或者对手的效果被破坏的情况下，可以1只该怪兽为对象发动。从牌组特殊召唤比该怪兽的原本等级低的1只“空牙团”怪兽。','发动但不使用效果','从牌组特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37910722,'天穹霸龙升天龙',replace(replace('协调＋协调以外的怪兽１只或以上\r\n此卡同步召唤成功时，此卡的攻击力上升我方手牌数量×８００点。场上的此卡因对手被破坏并送入墓地时，若此卡同步召唤中所使用的同步素材怪兽一组汇集至我方墓地，可特殊召唤该一组怪兽。以此效果特殊召唤而来怪兽的效果被无效化。“天穹霸龙升天龙”的此效果１回合只可使用１次。','\r',char(13)),'\n',char(10)),'攻击上升','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37926346,'侵邪蚀蜚蠊',replace(replace('等级4怪兽×2\r\n①：自己或对手特殊召唤等级5以上的怪兽之际，去除此卡的1个超量素材可以发动。将该特殊召唤无效，将该怪兽破坏。','\r',char(13)),'\n',char(10)),'5星以上的怪兽的特殊召唤无效并破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37930737,'重力均衡',replace(replace('此卡名在规则上也视为“G魔像”卡。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：以自己墓地・除外状态的2只地属性的同名怪兽为对象可以发动。将该2只怪兽以守备表示特殊召唤。以此效果特殊召唤的怪兽，攻击力・守备力变为0，效果无效化，将在结束阶段被破坏。\r\n②：自己场上的“G魔像”怪兽将被战斗或对手的效果破坏的情况下，作为代替可将墓地的此卡除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37931734,'创王团战','此卡名的卡1回合仅可发动1张。①：从自己的牌组・墓地挑选1张“创王”场地魔法卡发动。然后，对手从牌组抽1张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37953640,'龙宫的白鳝','以此卡为同步素材的场合，其他同步素材怪兽都必须是鱼族怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37955049,'军神概布','只要此卡以表侧表示存在于场上，场上的所有怪兽变成表侧攻击表示，且不可变更表示形式。此时不发动反转怪兽的效果。此外，１回合１次，可展示手牌任意张数的恶魔族怪兽。直至回合结束时，此卡的攻击力上升展示张数×３００点。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37957847,'昆虫公主','只要此卡以表侧表示存在于场上，对手场上以表侧表示存在的昆虫族怪兽全部变成攻击表示。此卡因战斗每次破坏昆虫族怪兽，此卡的攻击力上升５００点。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37961969,'泪冠哀歌・哈弗妮丝','此卡名的①②效果１回合仅可各使用１次。①：对手发动场上的怪兽的效果时可以发动。从手牌将此卡特殊召唤，从自己的牌组上面将３张卡送至墓地。②：此卡因效果被送至墓地的情况下可以发动。将由融合怪兽卡决定的、包含墓地的此卡在内的融合素材怪兽从自己的手牌・场上・墓地以喜欢的顺序放回持有者的牌组下面，从额外牌组将１只该融合怪兽融合召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37970940,'地灵使 奥丝','①：此卡反转的情况下，以对手场上的1只地属性怪兽为对象发动。此怪兽以表侧表示存在期间，获得对象怪兽的控制权。','获得对手场上1只地属性怪兽的控制权','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37970941,'地灵使 奥丝','①：此卡反转的情况下，以对手场上的1只地属性怪兽为对象发动。此怪兽以表侧表示存在期间，获得对象怪兽的控制权。','获得对手场上1只地属性怪兽的控制权','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37970942,'地灵使 奥丝','①：此卡反转的情况下，以对手场上的1只地属性怪兽为对象发动。此怪兽以表侧表示存在期间，获得对象怪兽的控制权。','获得对手场上1只地属性怪兽的控制权','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37972500,'天籁音服和弦・缪斯西娅',replace(replace('灵摆怪兽２只\r\n此卡名的①②效果１回合仅可各使用１次。①：在自己的主要阶段可以发动。从手牌将１只灵摆怪兽以表侧表示加入额外牌组，其灵摆刻度为奇数则将偶数灵摆刻度的、为偶数则将奇数灵摆刻度的１只表侧表示灵摆怪兽，从自己的额外牌组加入手牌。②：自己将“音服和弦”怪兽灵摆召唤成功时，以其中１只为对象可以发动。将１只等级与该怪兽灵摆刻度数值相同的“音服和弦”灵摆怪兽从牌组加入手牌。','\r',char(13)),'\n',char(10)),'','','请选择要加入额外牌组的卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37984162,'蛇魔・魔像',replace(replace('①：此卡因战斗被破坏并被送至墓地的情况下发动。将破坏了此卡的怪兽的攻击力改成0。\r\n②：将墓地的此卡除外，以对手场上的1张里侧表示的魔法・陷阱卡为对象可以发动（应对此发动，对手不可发动对象卡）。此回合，该卡不可发动。','\r',char(13)),'\n',char(10)),'攻击变成0','发动限制','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37991342,'机壳基因',replace(replace('←9 【灵摆】 9→\r\n①：我方只可特殊召唤“机壳”怪兽。此效果不会被无效化。\n②：对手场上怪兽的攻击力下降３００。\r\n【怪兽效果】\r\n①：此卡可无需释放进行召唤。\n②：以特殊召唤或无需释放召唤而来的此卡之等级变成４，原本攻击力变成１８００。\n③：通常召唤而来的此卡不受原本等级或阶级低于此卡等级之怪兽所发动的效果影响。\n④：此卡被释放的场合，可以场上的１张魔法、陷阱卡为对象发动。破坏该卡。','\r',char(13)),'\n',char(10)),'不用解放作召唤','魔陷破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(37993923,'废品守卫者',replace(replace('“废品同步士”＋协调以外的怪兽１只或以上\r\n１回合１次，可选择对手场上的１只怪兽并变更其表示形式。此效果在对手回合也可发动。此外，此卡从场上被送入墓地的场合，可选择场上的１只怪兽并变更其表示形式。','\r',char(13)),'\n',char(10)),'改变表示形式','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38001022,'巴利安之印',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：自己场上存在“混沌超量”怪兽或“混沌编号101”～“混沌编号107”中的任一“混沌编号”怪兽，且对手发动怪兽的效果・魔法・陷阱卡时可以发动。将该发动无效。然后，可从自己或对手的、场上・墓地将1只怪兽作为自己场上的1只超量怪兽的超量素材。\r\n②：将墓地的此卡除外可以发动。从自己墓地将2只“黑影”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'无效','特殊召唤','是否获得超量素材？','请选择1只超量怪兽','','','','','','','','','','','','');
INSERT INTO texts VALUES(38007649,'终刻变转',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：将“终刻变转”以外的自己手牌・牌组・场上（表侧表示）的1张“终刻”卡破坏。\r\n②：此卡因效果被破坏的情况下可以发动。从自己墓地将“终刻变转”以外的1张“终刻”卡加入手牌。然后，可从手牌将1只“终刻”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'破坏','回收','是否特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38007744,'先史遗产 摩艾石像搬运器','对手场上存在有卡牌，且我方场上不存在有卡牌的场合，此卡可从手牌特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38026562,'超化合兽甲烷冰',replace(replace('等级８二重怪兽×２\r\n①：此卡超量召唤成功时，可以我方墓地１只二重怪兽为对象发动。特殊召唤该怪兽。\r\n②：只要持有超量素材的此卡存在于怪兽区，对手不可以我方场上的二重怪兽为攻击对象或效果对象。\r\n③：二重怪兽召唤成功时，可移除此卡的１个超量素材并发动。对手必须将自己手牌、场上的１张卡牌送入墓地。','\r',char(13)),'\n',char(10)),'特殊召唤墓地二重怪兽','对方卡送至墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38030232,'天威龙－萨哈司剌剌',replace(replace('幻龙族怪兽2只以上\r\n此卡名的②效果1回合仅可使用1次。①：自己场上有效果怪兽以外的表侧表示怪兽存在的情况下，对手不可将场上的效果怪兽作为攻击对象，也不可作为效果的对象。②：以对手场上的1只效果怪兽为对象可以发动。将1只“天威龙衍生物”（幻龙族・光・星4・攻？/守0）特殊召唤至自己场上。此衍生物的攻击力变为与对象怪兽原本的攻击力相同。此效果在对手回合中也可以发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38030233,'天威龙衍生物','由“天威龙－萨哈司剌剌”的效果特殊召唤而来。此衍生物的攻击力将与特殊召唤此衍生物时目标怪兽原相同。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38033121,'黑魔导女孩','①：此卡的攻击力，上升相当于双方墓地的“黑魔导”、“黑混沌之魔导”数量×300的数值。','','','','','','','','','','','','','','','','');
