INSERT INTO texts VALUES(38035986,'红色祭司','会施死亡诅咒的魔法使。一听见他念的咒文，就会昏厥。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38041940,'火焰种子','我方场上的此卡因卡牌效果被破坏并送入墓地时可发动。选择我方墓地１只除“火焰种子”以外的等级４或以下的植物族怪兽特殊召唤，并以守备表示特殊召唤１只“种子衍生物”（植物族、地、星１、攻／守０）至对手场上。此衍生物不可进行以上级召唤为目的的释放。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38041941,'种子衍生物','由「火焰种子」的效果特殊召唤。这衍生物不能为上级召唤而解放。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38044854,'起升阶魔法－急袭猛禽之力',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：在自己・对手的主要阶段及对手的战斗阶段，以包含场上怪兽在内的、自己场上・墓地的２只以上的“急袭猛禽”超量怪兽为对象可以发动。从额外牌组将１只阶级与该２只以上怪兽的阶级合计相同的“急袭猛禽”超量怪兽视为超量召唤特殊召唤，并将对象怪兽作为其超量素材（对象怪兽拥有超量素材的情况下，将那些素材也全部作为超量素材）。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38049541,'A次代机・化学家','①：在自己・对手回合中，从手牌将此卡舍弃，以自己场上的１只“次代机”怪兽为对象，宣言１个属性可以发动。该自己的“次代机”怪兽变为所宣言的属性。','属性变换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38049934,'炎尘爆发','可将我方墓地所有冠有“岩浆炎”之名的怪兽从游戏中除外并发动。挑选场上的卡牌破坏，其数量最多是以发动此卡为目的而被除外的怪兽数量。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38053381,'创王关卡','此卡名的②效果1回合仅可使用1次。①：1回合1次，对手从牌组将卡加入手牌的情况下可以发动。从牌组将1只“创王”怪兽以守备表示特殊召唤。②：在对手回合中，自己将“创王”怪兽特殊召唤成功的情况下可以发动。尽可能将自己场上的“创王衍生物”（天使族・光・星4・攻/守1500）以攻击表示特殊召唤。此衍生物将在结束阶段被破坏。','从牌组特殊召唤','特殊召唤衍生物','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38053382,'创王衍生物','由「创王关卡」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38057522,'大灵术－「一轮」',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：只要自己场上存在守备力1500的魔法师族怪兽，1回合仅1次，对手发动的怪兽效果无效化。\r\n②：在自己的主要阶段可以发动。将手牌的1只魔法师族怪兽出示给对手，从牌组将1只与该怪兽同属性、攻击力1500/守备力200的怪兽加入手牌，将出示的怪兽放回牌组。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38082437,'变形斗士・电话机',replace(replace('①：此卡根据表示形式获得以下效果。\r\n●攻击表示：１回合１次，在自己的主要阶段可以发动。摇１次骰子。自己恢复相当于摇出的数字×１００的LP。然后，可从自己的墓地挑选１只拥有摇出的数字以下的等级数值的“变形斗士”怪兽特殊召唤。\r\n●守备表示：１回合１次，在自己的主要阶段可以发动。摇１次骰子，从自己的牌组上面翻开摇出的数字张数的卡。可从其中挑选１张“变形斗士”卡送至墓地。剩余的以喜欢的顺序放回牌组上面或下面。','\r',char(13)),'\n',char(10)),'','是否从墓地特殊召唤？','','是否选卡送至墓地？','回到牌组上面','回到牌组下面','','','','','','','','','','');
INSERT INTO texts VALUES(38105306,'消损的生命',replace(replace('①：“消损的生命”在自己场上仅可有１张以表侧表示存在。\r\n②：在对手的结束阶段可以发动。在此卡上放１个计数物。\r\n③：此卡上放有计数物的情况下，在自己・对手的主要阶段及战斗阶段可以发动。将此卡送至墓地。然后，对手尽可能地挑选手牌舍弃，数量最多为放在此卡上的计数物数量。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38107923,'暗黑奈芙蒂斯','我方主要阶段时我方墓地中有３只以上暗属性怪兽存在的场合，将其中的２只从游戏中除外，将手牌中的此卡送入墓地。在下次我方的准备阶段时，从墓地特殊召唤以此效果送入墓地的此卡。此外，成功特殊召唤此卡时，选择场上的１张魔法・陷阱卡并将其破坏。','送至墓地','特殊召唤','魔法·陷阱卡破坏','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38109772,'龙之骑士','①：以自己场上的卡为对象的、会破坏该卡的对手怪兽的效果发动时，将成为对象的自己的卡全部送至墓地可以发动（同一连锁上最多1次）。从手牌将此卡特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38114652,'封神之剑艮鬼 水子守',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次，且②③效果1回合仅可各使用1次。\r\n①：此卡可通过将自己场上的1张里侧表示卡出示给对手并放回手牌・额外牌组，来从手牌特殊召唤。\r\n②：在自己的主要阶段可以发动。从牌组将1只幻龙族以外的“艮鬼”怪兽加入手牌。\r\n③：此卡作为“艮鬼”同步怪兽的同步素材被送至墓地的情况下，以自己墓地的1张通常陷阱卡为对象可以发动。将该卡放置在自己场上。','\r',char(13)),'\n',char(10)),'','检索','放置','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38116136,'机器攻击者','专为特攻而造的机器。使用突击打倒敌人。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38120068,'抵价交易','①：从手牌将１只等级８怪兽舍弃可以发动。自己抽２张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38124994,'绒毛动物・兔子',replace(replace('“绒毛动物・兔子”的效果１回合只可使用１次。\r\n①：此卡变成融合召唤的素材被送入墓地的场合，可以我方墓地的１只“锋利小鬼・剪刀”或除“绒毛动物・兔子”以外的１只“绒毛动物”怪兽为对象发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'牌组检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38129297,'双重扳机',replace(replace('①：可从以下效果中选择1个发动（此卡名的以下效果1回合仅可各选择1次）。\r\n●将包含“枪弹”怪兽在内的、自己墓地的怪兽作为融合素材除外，将1只融合怪兽融合召唤。\r\n●为使合计等级达到仪式召唤的怪兽的等级以上，将包含“枪弹”怪兽在内的、自己墓地的怪兽除外，从手牌将1只仪式怪兽仪式召唤。','\r',char(13)),'\n',char(10)),'发动','融合召唤','仪式召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38142739,'小天使','攻击时动作慌张、总是难以击中的超小天使。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38143903,'首席审判',replace(replace('此卡牌名的①效果１回合只可使用１次。\r\n①：我方或对手发动场上怪兽的效果时可发动。发动了效果的玩家掷１次硬币，猜正反面。猜中的场合，此卡被送入墓地。猜错的场合，该发动无效，并将该怪兽的控制权转移至该玩家的对手。','\r',char(13)),'\n',char(10)),'发动但不使用效果','发动并使用效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38148100,'芬芳炽天使－迷迭香',replace(replace('协调＋协调以外的怪兽１只以上\r\n①：只要自己的LP多于对手，且此卡存在于怪兽区域，自己场上的植物族怪兽的攻击力・守备力上升５００。\r\n②：１回合１次，自己的LP恢复的情况下，以对手场上的１张表侧表示卡为对象发动。将该卡的效果直至回合结束时为止无效。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38167722,'暗灵术－「欲」','①：解放自己场上的１只暗属性怪兽可以发动。对手可从手牌出示１张魔法卡，将此效果无效。不出示的情况下，自己从牌组抽２张。','是否要把一张魔法卡给对手观看？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38173725,'电弧火箭・光船',replace(replace('此卡牌名的②效果１回合只可使用１次。\r\n①：我方场上不存在有怪兽的场合，此卡可无需解放进行召唤。\r\n②：此卡召唤・特殊召唤成功的场合，可以１只我方墓地等级８以下的机械族怪兽为对象发动。以守备表示特殊召唤该怪兽。以此效果特殊召唤之怪兽的等级变成９，效果被无效化。\r\n③：只要此卡存在于怪兽区，我方只可从额外牌组特殊召唤机械族超量怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38179121,'究极进化药',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从自己手牌・墓地将1只恐龙族怪兽和恐龙族以外的1只怪兽除外可以发动。从手牌・牌组将1只等级7以上的恐龙族怪兽无视召唤条件特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38180759,'虚构王 无形虚空',replace(replace('等级４怪兽×３\r\n在对手的主要阶段时，可移除此卡的１个超量素材并发动１次。此卡的攻击力、守备攻击力上升相当于对手场上超量怪兽攻击力的合计数值。','\r',char(13)),'\n',char(10)),'攻守上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38192988,'真红眼不死龙皇',replace(replace('不死族协调＋１只以上协调以外的怪兽\r\n此卡名的①②效果１回合仅可各使用１次。①：在对手回合中，以自己墓地１只“真红眼不死龙皇”以外的不死族怪兽为对象可以发动。将该怪兽特殊召唤。②：此卡存在于墓地的情况下，将自己场上的１只不死族怪兽除外可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38199696,'红药水','自己恢复５００LP。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38203732,'灵摆悖论',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：从自己的额外牌组（表侧），将灵摆刻度相同、卡名不同的２只怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38210374,'爆貘团','我方主要阶段时，可选择对手场上的１只超量怪兽并发动。手牌或我方场上的此怪兽被视为装备卡装备被选择对手的超量怪兽。以此效果装备此卡的怪兽没有超量素材的场合，破坏该怪兽。此外，此卡被视为装备卡装备于怪兽时，每次对手的准备阶段移除装备怪兽的１个超量素材。','装备','取除素材','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38229962,'大骑甲虫 无敌阿特拉斯',replace(replace('昆虫族怪兽２只以上\r\n此卡名的③效果１回合仅可使用１次。\r\n①：连接召唤的此卡攻击力在３０００以下的情况下，不会因对手的效果被破坏，对手不可将其作为效果的对象。\r\n②：只要此卡存在于怪兽区域，自己仅可特殊召唤昆虫族怪兽。\r\n③：解放自己场上的１只昆虫族怪兽，可从以下效果中选择１个发动。\r\n●从牌组将１只“骑甲虫”怪兽特殊召唤。\r\n●此卡的攻击力直至回合结束时为止上升２０００。','\r',char(13)),'\n',char(10)),'从牌组特殊召唤','此卡攻击力上升','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38247752,'暗之眼的幻想师','反转：此卡存在于场上时，所指定的１只对象怪兽永久不可攻击。','攻击限制','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38250531,'红贵士－吸血鬼・布莱姆',replace(replace('不死族等级5怪兽×2\r\n这个卡名的①的效果1个回合只可使用1次。①：去除这张卡的1个超量素材，可以对手墓地的1只怪兽为对象发动。将该怪兽特殊召唤至自己场上。用这个效果特殊召唤成功的回合，该怪兽以外的自己的怪兽不可攻击。②：场上的这张卡被对手破坏并被送至墓地的下个回合的准备阶段发动。将这张卡从墓地以守备表示形式进行特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','苏生','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38264974,'幻想魔兽 客迈拉',replace(replace('“有翼幻兽 客迈拉”＋幻想魔族怪兽１只以上\r\n①：此卡只要存在于场上・墓地，卡名视为“有翼幻兽 客迈拉”。\r\n②：此卡在１次战斗阶段中，可攻击怪兽的次数最多为作为此卡融合素材的怪兽数量。\r\n③：此卡与怪兽进行战斗的情况下，该２只不会因该战斗被破坏。\r\n④：此卡与对手怪兽进行战斗的伤害步骤结束时可以发动。该对手怪兽的攻击力变为０，效果无效化。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38265153,'电子能量冲击',replace(replace('此卡名的卡在1个回合中仅可发动1张。\r\n①：自己场上有“人造人-念力震慑者”存在时，可以以场上的1张卡为对象发动。破坏该卡。通过此效果破坏了场上的陷阱卡时，还可以从以下效果中选择1个适用。\r\n●选择1张场上表侧表示的卡，使其效果无效，直至回合结束时为止。\r\n●自己场上的所有“人造人-念力震慑者”的攻击力上升800。','\r',char(13)),'\n',char(10)),'不选择效果','选卡无效','攻击力上升','请选择要无效的卡','','','','','','','','','','','','');
INSERT INTO texts VALUES(38267552,'梦魔镜黑骑士－鲁耳甫斯','此卡名的①②效果1回合仅可各使用1次。①：此卡以“梦魔镜”怪兽的效果特殊召唤成功的情况下，以场上的1张卡为对象可以发动。将该卡破坏。②：场地区域有“圣光之梦魔镜”存在的情况下，在自己・对手的主要阶段及战斗阶段，解放此卡可以发动。从牌组将1只“梦魔镜白骑士-鲁耳甫斯”特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38273745,'邪蚀 衔尾蛇',replace(replace('等级４怪兽×３\r\n①：１回合１次，可移除此卡的１个超量素材，并从以下效果选择１个发动。只要此卡以表侧表示存在于场上，以下的效果只可各选择１次。\r\n●选择对手场上的１张卡牌并返回至持有者手牌。\r\n●随机挑选１张对手的手牌并送入墓地。\r\n●选择对手墓地的１张卡牌并从游戏中除外。','\r',char(13)),'\n',char(10)),'选择效果发动','对手场上存在的1张卡回到持有者手牌。','对手手牌随机选1张送至墓地。','对手墓地存在的1张卡从游戏中除外。','','','','','','','','','','','','');
INSERT INTO texts VALUES(38275183,'八式对魔法多重结界',replace(replace('可从以下效果中选择１个发动。\r\n●使以场上的１只怪兽为对象的魔法卡发动无效并破坏。\r\n●可从手牌将１张魔法卡送入墓地并发动。使魔法卡发动无效并破坏。','\r',char(13)),'\n',char(10)),'直接无效取1只怪兽为对象的魔法卡','把手牌送至墓地无效魔法卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38277918,'新月龙','据说来自月球，拿着新月形刀的龙战士。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38280762,'紫炎的老中 缘','此卡不可通常召唤。仅限将我方墓地冠有“六武众”之名的２只怪兽从游戏中除外的场合可特殊召唤。１回合１次，可选择场上的１只表侧表示怪兽并破坏。发动此效果的回合，此卡不可进行攻击宣言。','表侧表示存在的1只怪兽破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38289717,'贪尸龙','拥有可咬碎一切的利嘴的恐龙。其攻击十分强劲。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38296564,'安全地带',replace(replace('以场上的1只表侧攻击表示怪兽为对象可以发动此卡。\r\n①：只要此卡存在于魔法与陷阱区域，该表侧表示怪兽不会因战斗及对手的效果被破坏，不可直接攻击对手，且对手不可将其作为效果的对象。此卡从场上离开时该怪兽将被破坏。该怪兽从场上离开时此卡将被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38299233,'针墙','在自己准备阶段时仅１次，掷１次骰子。从此卡的控制者的右方起，将对手的怪兽区域看作１～５，破坏掷出数目的区域里的怪兽。掷出的数目为６的情况下，重新投掷。','投掷骰子','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38318146,'暴君的暴力','可释放我方场上２只怪兽并发动此卡。只要此卡存在于场上，对手必须从牌组将１张魔法卡送入墓地才可发动魔法卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38325384,'魔导加速',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从自己牌组上面将2张卡送至墓地，以场上的1张能放魔力计数物的卡为对象可以发动。在该卡上放最多2个魔力计数物。\r\n②：此卡因对手的效果被破坏的情况下可以发动。从牌组将1只能放魔力计数物的怪兽特殊召唤，在该怪兽上放最多2个魔力计数物。','\r',char(13)),'\n',char(10)),'是否放置2个魔力计数物？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38331244,'金神之战艮鬼 赤沙',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次，且②③效果1回合仅可各使用1次。\r\n①：此卡可通过将自己场上的1张里侧表示卡出示给对手并放回手牌・额外牌组，来从手牌特殊召唤。\r\n②：在自己・对手的主要阶段，从自己手牌・场上（里侧表示）将1张陷阱卡送至墓地可以发动。将对手场上的表侧表示怪兽全部改成里侧守备表示。\r\n③：在自己的结束阶段可以发动。从牌组将1张“艮鬼”陷阱卡放置在自己场上。','\r',char(13)),'\n',char(10)),'','变成里侧表示','放置','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38331564,'辉天使 权杖',replace(replace('①：此卡召唤、特殊召唤成功时可发动。从牌组将１只除“辉天使 权杖”以外的“辉天使”怪兽加入手牌。\r\n②：以场上包含此卡在内的３只或以上的怪兽为素材超量召唤而来的怪兽获得以下效果。\r\n●此超量召唤成功时，可以场上除此卡以外的１张卡牌为对象发动。破坏该卡，我方可从牌组抽取１张卡牌。','\r',char(13)),'\n',char(10)),'牌组检索','破坏并抽牌（辉天使 天杖）','是否抽牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38339996,'救援王牌 脉冲消防员',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己的主要阶段可以发动。挑选对手场上1只攻击力最高的效果怪兽。此回合，双方不可发动该表侧表示怪兽在场上发动的效果。\r\n②：对手发动场上的怪兽的效果时，解放手牌・场上的此卡可以发动。从牌组将1只机械族的“救援王牌”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38342335,'梦魇曲・独角兽',replace(replace('卡名不同的怪兽2只以上\r\n此卡名的①效果1回合仅可使用1次。\r\n①：此卡连接召唤的情况下，舍弃1张手牌，以场上的1张卡为对象可以发动。将该卡放回牌组。此效果发动时此卡为相互连接状态的情况下，进而可自己抽1张。\r\n②：只要有相互连接状态的“梦魇曲”怪兽存在，自己抽牌阶段的通常抽牌的张数就变为该“梦魇曲”怪兽种类的数量。','\r',char(13)),'\n',char(10)),'','是否抽牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38342336,'梦魇曲・独角兽',replace(replace('卡名不同的怪兽2只以上\r\n此卡名的①效果1回合仅可使用1次。\r\n①：此卡连接召唤的情况下，舍弃1张手牌，以场上的1张卡为对象可以发动。将该卡放回牌组。此效果发动时此卡为相互连接状态的情况下，进而可自己抽1张。\r\n②：只要有相互连接状态的“梦魇曲”怪兽存在，自己抽牌阶段的通常抽牌的张数就变为该“梦魇曲”怪兽种类的数量。','\r',char(13)),'\n',char(10)),'','是否抽牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38354018,'超重型炮塔列车 飞行发射器',replace(replace('等级10怪兽×2\r\n此卡名的①③效果1回合仅可各使用1次。\r\n①：此卡超量召唤的情况下可以发动。从牌组将1只机械族・地属性怪兽或1张“扫射特攻”加入手牌。\r\n②：只要此卡存在于怪兽区域，自己在通常召唤之外，可在自己的主要阶段追加1次召唤1只机械族怪兽。\r\n③：去除此卡的任意数量的超量素材，依其数量以场上的魔法・陷阱卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'检索效果','使用「超重型炮塔列车 飞行发射器」的效果召唤','破坏效果','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38354937,'真次代机・黑铁汽机',replace(replace('“次代机”协调＋协调以外的暗属性怪兽１只以上\r\n①：此卡同步召唤的情况下发动。获得对手场上等级最高的１只怪兽的控制权。','\r',char(13)),'\n',char(10)),'获得控制权','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38356857,'残虐・咒仪','此卡名的②效果１回合仅可使用１次。①：仪式召唤１只水属性仪式怪兽的情况下，使用１张此卡即可作为仪式召唤所必需的解放。②：此卡召唤・特殊召唤成功的情况下可以发动。从牌组将１只“残虐・咒仪”以外的“咒仪”怪兽特殊召唤。此效果发动后，直至回合结束时为止，自己仅可用仪式怪兽进行攻击宣言。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38363525,'不死尸化','此卡名的①②效果１回合１次，仅可使用其中１个。①：场上存在等级５以上的不死族怪兽的情况下，以对手场上的１只怪兽为对象可以发动。直至结束阶段为止获得该怪兽的控制权。②：此卡存在于墓地的情况下可以发动。挑选被除外的自己的１只不死族怪兽放回牌组，将此卡放置在自己场上。以此效果放置的此卡离开场上的情况下，将其除外。','获得控制权','在自己场上放置','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38369349,'卡通龙蛋',replace(replace('此卡不可通常召唤。\r\n自己场上存在“卡通世界”的状态下，解放自己场上的2只怪兽的情况下可以特殊召唤。\r\n①：此卡在特殊召唤的回合不可攻击。\r\n②：此卡攻击宣言之际，自己必须支付500LP。\r\n③：此卡在对手场上不存在卡通怪兽的情况下可直接攻击。存在的情况下，仅可选择卡通怪兽为攻击对象。\r\n④：场上的“卡通世界”被破坏时，此卡将被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38379052,'阿尔戈☆群星－屠龙的厄忒欧',replace(replace('①：只要此卡存在于魔法与陷阱区域，自己场上的战士族怪兽不会因效果被破坏。\r\n②：1回合1次，对手发动效果时可以发动。此卡变为拥有以下效果的效果怪兽（战士族・光・星4・攻/守800），特殊召唤至怪兽区域（也视为陷阱卡）。有自己的“阿尔戈☆群星”怪兽被除外的情况下，进而可将场上的1张卡放回手牌。\r\n●在每个自己・对手回合中可以发动1次。将此卡以表侧表示放在自己的魔法与陷阱区域。','\r',char(13)),'\n',char(10)),'特殊召唤','表侧表示放置','是否让卡回到手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38383368,'临时保险三角龙装',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：此卡存在于墓地，额外怪兽区域的怪兽因与主要怪兽区域的怪兽进行的战斗被破坏并被送至墓地时可以发动。将此卡以守备表示特殊召唤至该被破坏的额外怪兽区域的怪兽的持有者的场上。\r\n②：以此卡的①效果特殊召唤的此卡被破坏并被送至墓地的情况下发动。自己从牌组抽１张。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38391684,'龙都 亚特兰蒂斯',replace(replace('此卡名的③效果1回合仅可使用1次。\r\n①：只要场上存在记载有“龙都 亚特兰蒂斯”卡名的怪兽，双方手牌・场上的怪兽的等级下降1。\r\n②：只要此卡存在于场地区域，自己要连接召唤“代达罗斯”连接怪兽的情况下，所需要的连接素材的数量可减少1、记载的连接素材的条件可减少1只。\r\n③：此卡存在于墓地，且自己场上存在“海”的情况下可以发动。将此卡以表侧表示放在自己场上。','\r',char(13)),'\n',char(10)),'','放置','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38395123,'扰乱怪较量',replace(replace('①：可从手牌及我方场上表侧表示的卡牌中，将１张“扰乱怪”卡牌送入墓地并发动。从我方牌组、墓地挑选１只与此卡卡牌名不同的“扰乱怪”怪兽和１只“武装龙”怪兽加入手牌。之后，可召唤１只以此效果加入手牌的怪兽。\r\n②：可在我方主要阶段将墓地的此卡除外，并以我方被除外的３只“扰乱怪”怪兽为对象发动。将该怪兽加入牌组并洗牌。之后，我方从牌组抽取１张卡牌。','\r',char(13)),'\n',char(10)),'是否选加入手牌的怪兽召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38406364,'常夏的雷鸣大人',replace(replace('雷族怪兽2只\r\n①：每个对手回合中1次，舍弃1张手牌，以连接怪兽以外的自己墓地的1只雷族怪兽为对象可以发动。将该怪兽特殊召唤至此卡连接端的自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38409239,'游魊宇宙',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：根据除外状态的鱼族怪兽的数量，分别适用以下效果。\r\n●１只以上：此回合，自己的鱼族怪兽不会因战斗被破坏。\r\n●４只以上：此回合，自己场上的鱼族怪兽的效果的发动及该发动的效果不会被无效化。\r\n●８只以上：从额外牌组将１只鱼族同步怪兽视为同步召唤来特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38411870,'尖刺吊顶','①：场上的怪兽为4只以上的情况下可以发动。将场上的表侧表示怪兽全部破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38412161,'灵塞术师 澄最',replace(replace('①：只要此卡存在于怪兽区域，双方不可发动墓地的魔法・陷阱卡的效果。\r\n②：此卡从场上被送至墓地的情况下，以对手墓地的１张魔法・陷阱卡为对象可以发动。将该卡除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38423248,'召唤兽 伟魔・瑟利昂',replace(replace('“召唤师 阿莱斯特”＋融合・同步・超量・连接怪兽\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡特殊召唤的情况下，以自己墓地的1只融合・同步・超量・连接怪兽和场上的1只怪兽为对象可以发动。将该怪兽除外。\r\n②：融合召唤的此卡因战斗・效果被破坏的情况下可以发动。从牌组将1只魔法师族・等级4怪兽特殊召唤。然后，可将此卡视为攻击力上升1000的装备魔法卡，装备于该怪兽。','\r',char(13)),'\n',char(10)),'除外','特殊召唤','是否装备？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38430673,'大十字','①：自己场上存在“宏观宇宙”的情况下可以发动。给予对手300伤害，场上存在怪兽的情况下，将其全部破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38436986,'泪冠哀歌・作响的异界爪音','此卡名的①②效果１回合１次，仅可使用其中１个。①：自己场上存在“泪冠哀歌”怪兽或“维萨思・史塔弗罗斯特”的情况下，以对手场上的１只表侧表示怪兽为对象可以发动。将该怪兽改成里侧守备表示。然后，从牌组将１只“泪冠哀歌”怪兽送至墓地。②：此卡因效果被送至墓地的情况下，以自己墓地的１只“泪冠哀歌”怪兽为对象可以发动。将该怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38445524,'钩刀魔','身披钢铁铠甲的杀戮机器。使用巨刀毫不留情地进行攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38450736,'甲虫装机 蠼螋','１回合１次，可从我方手牌、墓地将１只冠有“甲虫装机”之名的怪兽视为装备卡装备此卡。此卡被视为装备卡装备中的场合，装备怪兽的攻击力、守备力各上升此卡的攻击力、守备力数值。此外，直至回合结束时，被装备于怪兽的此卡被送入墓地时，装备过怪兽的攻击力上升１０００点。','装备','攻击上升','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38459905,'方程式运动员试跑','此卡名的①②效果1回合仅可各使用1次。①：以自己场上的1只“方程式运动员”怪兽为对象可以发动。更改该怪兽的表示形式。然后，挑选1张场上的卡破坏。②：在自己的主要阶段将墓地的此卡除外，以自己场上的1张表侧表示的卡为对象可以发动。破坏该卡，从牌组将1只“方程式运动员”怪兽特殊召唤。此效果在此卡被送至墓地的回合不可发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38468214,'外星人催眠',replace(replace('此卡以表侧表示存在于墓地或场上的场合，被视为通常怪兽。透过视为通常召唤再次召唤场上以表侧表示存在的此卡，使此卡被视为效果怪兽并获得以下效果。\r\n●选择对手场上１只放置有A计数物的怪兽并获得其控制权。每次我方结束阶段，移除获得控制权的怪兽的１个A计数物。获得控制权怪兽的A计数物被全部移除的场合，破坏该怪兽。','\r',char(13)),'\n',char(10)),'获得控制权','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38479725,'特洛伊木马','上级召唤地属性怪兽的情况下，此卡可作为２只解放。','地属性双祭品','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38480590,'女豹佣兵','解放此卡可以发动。选择１只此回合因战斗被破坏的自己墓地的怪兽并放回牌组的最上方。','返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38491199,'废品库里波','①：对手发动给予我方伤害的魔法、陷阱、怪兽效果时，可将我方手牌、场上的此卡送入墓地并发动。使该发动无效并破坏。','发动无效并破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38491852,'华耳琴璃・邀请',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从以下效果中挑选1个适用。\r\n●从牌组将1只“华耳琴璃”怪兽特殊召唤。此卡发动后，直至回合结束时为止，自己不可发动“华耳琴璃”怪兽以外的、场上怪兽的效果。\r\n●自己场上存在灵摆怪兽以外的“华耳琴璃”怪兽的情况下，从牌组挑选卡名不同的2只“华耳琴璃”灵摆怪兽，将其中1只加入手牌，另1只以表侧加入额外牌组。','\r',char(13)),'\n',char(10)),'','特殊召唤','加入手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38492752,'岩浆炎・加农抱','此卡召唤、反转召唤成功时，可选择１只从游戏中被除外的我方冠有“岩浆炎”之名的怪兽并特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38495396,'星圣 托勒密星团M7',replace(replace('等级6怪兽×2\r\n此卡也可重叠在“星圣 托勒密星团M7”以外的、自己场上的“星圣”超量怪兽上面来超量召唤。\r\n以此方法特殊召唤的回合，此卡的①效果不可发动。\r\n①：1回合1次，去除此卡的1个超量素材，以自己或对手的、场上・墓地的1只怪兽为对象可以发动。将该怪兽放回手牌。','\r',char(13)),'\n',char(10)),'返回手牌','是否在「星圣」超量怪兽上面重叠超量召唤？','以场上1只怪兽为对象','以墓地1只怪兽为对象','','','','','','','','','','','','');
INSERT INTO texts VALUES(38495397,'星圣 托勒密星团M7',replace(replace('等级6怪兽×2\r\n此卡也可重叠在“星圣 托勒密星团M7”以外的、自己场上的“星圣”超量怪兽上面来超量召唤。\r\n以此方法特殊召唤的回合，此卡的①效果不可发动。\r\n①：1回合1次，去除此卡的1个超量素材，以自己或对手的、场上・墓地的1只怪兽为对象可以发动。将该怪兽放回手牌。','\r',char(13)),'\n',char(10)),'返回手牌','是否在「星圣」超量怪兽上面重叠超量召唤？','以场上1只怪兽为对象','以墓地1只怪兽为对象','','','','','','','','','','','','');
INSERT INTO texts VALUES(38502358,'星痕之机界骑士',replace(replace('“机界骑士”怪兽2只以上\r\n此卡名的③效果1回合仅可使用1次。①：此卡的同一纵列没有其他卡存在的情况下，此卡可直接攻击。②：此卡在额外怪兽区域且连接端没有怪兽存在的情况下，此卡不会因效果被破坏，不会成为对手效果的对象。③：将与此卡同一纵列的1张自己的其他卡送至墓地可以发动。从牌组将1只“机界骑士”怪兽以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38505587,'棉棉花糖',replace(replace('此卡名的①③效果１回合仅可各使用１次。\r\n①：在对手回合中，自己场上存在“光之黄金柜”的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：只要自己场上存在“光之黄金柜”，此卡不会因战斗被破坏，对手怪兽不可将其他怪兽选择为攻击对象。\r\n③：此卡因效果被破坏的情况下可以发动。将除此卡之外的、自己的手牌・牌组・墓地・除外状态的１只“棉棉花糖”特殊召唤，给予对手１０００伤害。','\r',char(13)),'\n',char(10)),'此卡特殊召唤','特殊召唤「棉棉花糖」','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38511382,'背叛之罪宝－西尔维亚',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：从自己的手牌・场上（表侧表示）将１只“迪亚贝尔斯塔”怪兽送至墓地，以场上的１张表侧表示卡为对象可以发动。将该卡的效果无效。\r\n②：对手连锁自己的“迪亚贝尔斯塔”怪兽或自己的“罪宝”魔法・陷阱卡的效果发动，来发动魔法・陷阱・怪兽的效果时，将墓地的此卡除外可以发动。将该对手的效果无效。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38517737,'青眼亚白龙',replace(replace('此卡不可通常召唤。\r\n将手牌的１只“青眼白龙”出示给对手的情况下可以特殊召唤。\r\n“青眼亚白龙”以此方法的特殊召唤１回合仅可进行１次。\r\n①：此卡只要存在于场上・墓地，卡名视为“青眼白龙”。\r\n②：１回合１次，以对手场上的１只怪兽为对象可以发动（发动此效果的回合中，此卡不可攻击）。将该怪兽破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38520918,'古龙','此卡因直接攻击给予对手生命战斗伤害时可发动。此卡的等级上升１，攻击力上升５００点。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38522377,'机皇神龙星标',replace(replace('此卡无法通常召唤。\r\n自己场上有至少3只“机皇”怪兽时可特殊召唤。\r\n①：此卡特殊召唤成功时，可以以自己场上除此卡以外任意数量的“机皇”怪兽为对象发动。将自己的该“机皇”怪兽送至墓地。此卡的攻击力为因此效果被送至墓地的怪兽原本攻击力的合计数值。\r\n②：每次同步怪兽被特殊召唤时发动。对特殊召唤该怪兽的玩家造成数值为1000的伤害。','\r',char(13)),'\n',char(10)),'攻击变换','LP伤害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38525760,'阳炎兽 冥府犬','此卡可无须释放召唤。以此方法召唤的此卡的原本攻击力变成１０００。只要此卡以表侧表示存在于场上，对手不可将此卡作为卡牌效果的对象。此外，此卡被破坏并送入墓地时可发动。从牌组将１张冠有“阳炎”之名的卡牌加入手牌。','不用解放作召唤','牌组检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38527680,'联合激活',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：从手牌・牌组将１只机械族・光属性的、通常怪兽或联合怪兽送至墓地，从牌组将攻击力与该怪兽相同、原本卡名不同的１只机械族・光属性怪兽加入手牌。\r\n②：此卡存在于墓地的状态下，自己将３只机械族・光属性怪兽同时特殊召唤的情况下，将此卡除外可以发动。从牌组将１只攻击力３０００以上的怪兽加入手牌。然后，进行该１只怪兽的召唤。','\r',char(13)),'\n',char(10)),'加入手牌','加入手牌并召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38528901,'冰结界的决起队','①：解放此卡，以场上的１只水属性怪兽为对象可以发动。将该水属性怪兽破坏，从牌组将１只“冰结界”怪兽加入手牌。','破坏，检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38529357,'命之代行者 涅普顿',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从手牌将此卡舍弃可以发动。从自己手牌・墓地将“命之代行者 涅普顿”以外的1只“代行者”怪兽特殊召唤。自己或对手的、场上或墓地存在“天空的圣域”的情况下，可将要特殊召唤的怪兽改成1只“许珀里翁”怪兽。直至对手回合结束时为止，双方不可解放以此效果特殊召唤的怪兽。\r\n②：此卡被除外的情况下可以发动。从牌组将1张“天空的圣域”加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38532954,'方程式运动员修理站','此卡名的①②效果1回合仅可各使用1次。①：以自己场上的1只“方程式运动员”怪兽为对象可以发动。该怪兽的等级下降2，自己从牌组抽自己墓地的“方程式运动员修理站”张数＋1张。②：在自己的主要阶段将墓地的此卡除外，以自己墓地的1只“方程式运动员”怪兽为对象可以发动。将该怪兽特殊召唤。此效果在此卡被送至墓地的回合不可发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38538445,'不死之炎鸟','此卡不可特殊召唤。召唤・反转此卡的回合的结束阶段时回到持有者的手牌中。此卡对对手生命造成战斗伤害时，我方回复与该战斗伤害相同数值的LP。','返回手牌','回复','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38552107,'光之角','装备怪兽的守备力上升８００点。此卡从场上被送入墓地时，可支付５００LP发动。将此卡返回至牌组最上面。','返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38562933,'黑羽－空风的吉恩','此卡与持有守备力为此卡攻击力或以下的怪兽进行战斗的伤害步骤开始时，破坏该怪兽。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38568567,'奇异三叶草','选择我方场上１只表侧表示的怪兽，并将手牌中１只等级４的植物族怪兽送入墓地来发动此卡。所选择怪兽在１个战斗阶段中可进行２次攻击。发动此卡的回合中，我方场上的其他怪兽不可进行攻击宣言。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38572779,'幻创之混拼恐龙',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：在自己・对手的主要阶段，从手牌将此卡送至墓地可以发动。在此主要阶段中，自己场上的恐龙族怪兽不受对手发动的效果影响。\r\n②：从自己墓地将包含此卡在内的任意数量恐龙族怪兽除外可以发动。从牌组将1只等级与所除外怪兽数量相等的恐龙族怪兽特殊召唤。以此效果特殊召唤的怪兽将在结束阶段被破坏。','\r',char(13)),'\n',char(10)),'免疫效果','特殊召唤','请选择要特殊召唤的怪兽的等级','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38576155,'女神诗蔻蒂的托宣',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：作为此卡发动时的效果处理，自己场上的怪兽仅有“女战神”怪兽的情况下，可从牌组将１张“女神薇儿丹蒂的引导”加入手牌。\r\n②：１回合１次，在自己的主要阶段可以发动。从对手牌组上面确认３张卡，以喜欢的顺序放回牌组上面。此效果发动后，直至回合结束时为止，自己仅可召唤・特殊召唤天使族怪兽。','\r',char(13)),'\n',char(10)),'是否把「女神薇儿丹蒂的引导」加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38589847,'升级之力','只要此卡存在于场上，可释放１只等级５以上的怪兽来上级召唤等级７以上的怪兽。','把1只5星以上的怪兽解放上级召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38590361,'螺旋结合','①：从自己的手牌・场上，将由龙族融合怪兽卡决定的融合素材怪兽送至墓地，从额外牌组将１只该融合怪兽融合召唤。以此效果特殊召唤了“龙骑士盖亚”的情况下，该怪兽攻击力上升２６００，１次战斗阶段中最多可攻击怪兽２次。','「螺旋结合」效果适用中','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38601126,'破坏剑－武器破坏之刃',replace(replace('①：在我方主要阶段，可以我方场上的１只“毁灭剑士”作为对象并发动。我方手牌、场上的此怪兽被视为装备卡装备在我方怪兽。\r\n②：此卡被装备的场合，对手场上已经以表侧表示存在的魔法、陷阱卡不可发动效果。\r\n③：可将被装备的此卡送入墓地并发动。直至回合结束时，装备此卡的怪兽攻击力上升１０００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38606913,'方界缘起',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：在对手场上的表侧表示怪兽上放方界计数物，数量最多为自己场上的“方界”怪兽数量。放有方界计数物的怪兽不可攻击，效果无效化。\r\n②：将墓地的此卡除外，以自己场上的１只“方界”怪兽为对象可以发动。此回合，每次该怪兽战斗破坏放有方界计数物的怪兽，给予对手相当于该被破坏的怪兽原本攻击力数值的伤害。','\r',char(13)),'\n',char(10)),'','请选择要放置计数物的怪兽','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38625110,'晨曦映雪白皎皎 笑语成霜共行脚','①：自己场上（表侧表示）・墓地・除外状态都不存在“晨曦映雪白皎皎 笑语成霜共行脚”的情况下，从自己牌组上面将7张卡以里侧除外可以发动。对手必须从自身牌组上面・额外牌组将合计7张卡以里侧除外。','','选择除外的额外牌组的卡（取消的情况下除外７张牌组的卡）','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38628859,'恐啡肽骇龙・迪普梁斯','此卡名的①②效果１回合仅可各使用１次。①：此卡召唤・特殊召唤成功的情况下可以发动。从牌组将１张“恐啡肽骇龙”卡送至墓地。自己的LP为２０００以下的情况下，进而给予对手５００伤害。②：此卡因战斗・效果被破坏的情况下，从自己的墓地将１张陷阱卡除外可以发动。从自己的墓地挑选１只“恐啡肽骇龙・迪普梁斯”以外的、等级４以下的“恐啡肽骇龙”怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38643567,'甲虫装机的宝珠','可选择１只我方场上冠有“甲虫装机”之名的怪兽发动此卡。此卡被视为攻击力、守备力上升５００点的装备卡装备被选择的我方怪兽。仅以我方场上１只冠有“甲虫装机”之名的怪兽为对象的卡牌效果发动时，可将变成装备卡的此卡送入墓地并发动。使该效果无效。','效果无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38648860,'白森的圣徒 莉塞特',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：向对手出示手牌的此卡可以发动。从手牌将1只“白森”怪兽或“圣徒”怪兽特殊召唤。\r\n②：在自己的主要阶段可以发动。将自己手牌・场上的怪兽作为融合素材，将1只“圣徒”融合怪兽融合召唤。\r\n③：此卡作为同步素材被送至墓地的情况下可以发动。从牌组将1张“罪宝”卡加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','融合','检索效果','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38667773,'卫星骑士 天琴维嘉',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：此卡召唤・反转召唤・特殊召唤的情况下可以发动。从手牌将“卫星骑士 天琴维嘉”以外的1只“星骑士”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38669664,'原物质之炉芯熔毁',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：在自己的主要阶段可以发动。从自己牌组上面翻开6张卡，并可从其中挑选1张“原物质”卡加入手牌。将剩余的以喜欢的顺序放回牌组上面。然后，可将1张自己场上的阶级3超量怪兽所持有的超量素材中的卡加入手牌。\r\n②：自己的超量怪兽发动效果的情况下可以发动。将自己牌组最上面的卡作为自己场上的1只“原物质”超量怪兽的超量素材。','\r',char(13)),'\n',char(10)),'翻开牌组','变成超量素材','是否把卡加入手牌？','是否把超量素材加入手牌？','','','','','','','','','','','','');
INSERT INTO texts VALUES(38670435,'暗黑恐兽','当对手场上只有守备表示怪兽存在的场合，此卡可对对手玩家进行直接攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38679204,'大日神械星状体','此卡从怪兽区被送入墓地的场合，可支付５００LP，并选择我方场上的１只表侧表示怪兽发动。此卡被视为装备卡装备在被选择的我方怪兽。此卡被视为装备卡装备的场合，直至该伤害步骤结束时，破坏与装备怪兽进行了战斗的对手怪兽。','当成装备卡装备','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38680149,'信赖之心','可释放我方场上１只等级２或以上的怪兽，并从我方墓地选择１只等级为该等级一半或以下的协调发动。将被选择的怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38694052,'黑熔龙骑 沃尔尼吉斯',replace(replace('等级７怪兽×２\r\n①：１回合１次，去除此卡的２个超量素材，以场上的１张表侧表示卡为对象可以发动。将该卡破坏。以此效果破坏了怪兽的情况下，可挑选自己场上的１只表侧表示怪兽，其攻击力直至下个回合结束时为止，上升相当于所破坏怪兽原本等级・阶级数值×３００的数值。发动此效果的回合中，此卡不可攻击。此卡持有龙族怪兽作为超量素材的情况下，此效果在对手回合中也可以发动。','\r',char(13)),'\n',char(10)),'破坏场上1张表侧表示的卡','是否选怪兽上升攻击力？','请选择要上升攻击力的怪兽','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38695361,'混沌的使者','①：在自己・对手的战斗阶段从手牌将此卡舍弃，以自己场上的１只“混沌士兵”怪兽或“暗黑骑士盖亚”怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止上升１５００，此回合，与该怪兽进行战斗的对手怪兽的攻击力仅在伤害计算时变为原本的攻击力。②：在自己・对手的结束阶段，此卡存在于墓地的情况下，从自己的墓地将此卡以外的光属性和暗属性怪兽各１只除外可以发动。将此卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38699854,'太阳之书','①：以场上的1只里侧表示怪兽为对象可以发动。将该里侧表示怪兽改成表侧攻击表示。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38723936,'谜题','发动中，对手不可确认墓地中的卡。对手宣言１个怪兽卡名。自己墓地最下方的怪兽是宣言的卡的情况下，将该卡从游戏中除外。没有猜中的情况下，将该卡特殊召唤至自己场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38730226,'英知之代行者 墨丘利','在对手的结束阶段时若此卡以表侧表示存在于我方场上，且我方手牌数为０的场合，在我方下个准备阶段时发动此卡。从我方牌组抽取１张卡牌。','下一个准备阶段时抽牌','抽牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38737148,'光芒 代达罗斯','此卡不可通常召唤。仅限我方墓地的光属性怪兽为４只或以上的场合可特殊召唤。１回合１次，可选择场上的２张卡牌以及１张场地魔法卡共３张卡牌发动。破坏被选择的卡牌。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38742075,'边境的大贤者','只要此卡以表侧表示存在于场上，以我方场上表侧表示存在的战士族怪兽为对象的魔法卡无效果并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38745241,'迷你喵魔幻甜点・玛卡龙喵喵',replace(replace('包含“魔幻甜点”怪兽在内的效果怪兽２只以上\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡连接召唤的情况下可以发动。从牌组将１张“魔幻甜点”卡加入手牌。\r\n②：以自己墓地的１只怪兽为对象可以发动。从手牌将１只“魔幻甜点”怪兽特殊召唤，将对象怪兽放回牌组。此效果发动后，直至回合结束时为止，自己不可发动“魔幻甜点”怪兽以外的怪兽的效果。','\r',char(13)),'\n',char(10)),'牌组检索','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38745520,'骑龙 多拉贡巴克','仅可装备于自己场上的怪兽。此卡名的②③效果1回合仅可各使用1次。①：“骑龙 多拉贡巴克”在自己场上仅可有1张以表侧表示形式存在。②：此卡装备于效果怪兽以外的怪兽的情况下，以对手场上的1张卡为对象可以发动。将该卡放回持有者的手牌。③：此卡被送至墓地的情况下，以自己场上的1只“勇者衍生物”为对象可以发动。将此卡装备于自己的该怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38757297,'光子狮','此卡召唤成功时可发动。将所有对手手牌加入牌组并洗牌。之后，对手抽取卡牌，其数量相当于加入牌组的数量。','重新筹卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38761908,'伯吉斯吸虫・足杯虫',replace(replace('①：以场上的1张表侧表示的卡为对象可以发动。挑选自己的1张手牌舍弃，将对象卡除外。\r\n②：此卡存在于墓地，且陷阱卡发动时可以发动（同一连锁上最多1次）。此卡变为通常怪兽（水族・水・星2・攻1200/守0），特殊召唤至怪兽区域（不视为陷阱卡）。以此效果特殊召唤的此卡不受怪兽效果影响，从场上离开的情况下将被除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38775407,'觉醒于仟年长眠中的原人',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡存在于手牌的情况下可以发动。将此卡视为永续魔法卡，以表侧表示放在自己的魔法与陷阱区域。\r\n②：此卡视为永续魔法卡的情况下，支付２０００LP，或将手牌的１张“仟年十字”出示给对手可以发动。将此卡特殊召唤。然后，可从牌组将１只“仟年”怪兽或“千年”怪兽加入手牌。\r\n③：此卡只要存在于怪兽区域，不会因怪兽的效果被破坏。','\r',char(13)),'\n',char(10)),'当作魔法卡放置','特殊召唤','是否出示「仟年十字」？','是否把「仟年」怪兽加入手牌？','','','','','','','','','','','','');
INSERT INTO texts VALUES(38776201,'三幻魔解放',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从牌组将卡名不同的3只“三幻魔”怪兽加入手牌。然后，挑选自己的2张手牌舍弃。\r\n②：从墓地将不是在此回合被送至墓地的此卡除外可以发动。从牌组将1只不可通常召唤的等级10的炎族・雷族・恶魔族怪兽加入手牌。','\r',char(13)),'\n',char(10)),'发动','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38777931,'释放反转爆发','可释放我方场上１只冠有“希望皇霍普”之名的怪兽并发动。将盖牌于对手场上的所有魔法、陷阱卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38783169,'调整鼠骑士',replace(replace('①：此卡特殊召唤成功的情况下可以发动。此回合，将此卡视为协调。此效果发动后，直至回合结束时为止，自己仅可从额外牌组特殊召唤怪兽1次。②：1回合1次，可从以下效果中选择1个发动。\r\n●以自己场上的1只表侧表示怪兽为对象，将此卡视为装备卡装备于该怪兽。装备怪兽将被战斗・效果破坏的情况下，破坏此卡作为代替。\r\n●将被装备的此卡特殊召唤。','\r',char(13)),'\n',char(10)),'此卡当作协调使用','当作装备卡使用','装备的此卡特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38784726,'转生炎兽之降临','“转生炎兽”仪式怪兽降临所必须。①：为使合计等级为仪式召唤的怪兽以上，将自己手牌・场上的怪兽解放，从手牌将1只“转生炎兽”仪式怪兽仪式召唤。自己场上有炎属性连接怪兽存在的情况下，作为解放的代替可将自己墓地的“转生炎兽”怪兽放回牌组。②：此卡因对手的效果被破坏的情况下可以发动。从手牌将1只“转生炎兽 翡翠鹰”无视召唤条件特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38798785,'炎王的结袭',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：从自己的手牌・牌组・墓地各将１只兽族・兽战士族・鸟兽族的炎属性怪兽特殊召唤（同种族最多１只）。以此效果特殊召唤的怪兽的效果无效化，将在结束阶段被破坏。\r\n②：将墓地的此卡除外可以发动。此回合，自己的“炎王”怪兽的召唤・特殊召唤成功时，对手不可发动魔法・陷阱・怪兽的效果。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38811586,'真炎龙 阿尔比昂',replace(replace('“阿尔白斯之落胤”＋魔法师族・光属性怪兽\r\n此卡不可作为融合素材。此卡名的②③效果１回合仅可各使用１次。①：此卡不会成为对手效果的对象。②：在对手回合中，以自己・对手墓地的合计２只怪兽为对象可以发动。将该怪兽各特殊召唤１只至双方场上。③：此卡存在于墓地的情况下可以发动。解放存在于额外怪兽区域及双方中央的主要怪兽区域的４只怪兽，将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','请选择要在自己场上特殊召唤的怪兽','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38814750,'精神骨架装备 伽马',replace(replace('此卡不可通常召唤，仅可通过卡的效果特殊召唤。\r\n①：自己场上不存在怪兽，且对手发动怪兽的效果时可以发动（同一连锁上最多1次）。将手牌的此卡，和自己手牌・牌组・墓地的1只“精神骨架 驱动者”特殊召唤，将该发动无效并破坏。以此效果特殊召唤的怪兽将全部在结束阶段被除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38815069,'光道盗贼猫 莱喵','反转：选择我方墓地的１只冠有“光道”之名的怪兽加入牌组并洗牌。之后，从我方牌组抽取１张卡牌。','返回牌组抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38817295,'月女神之至天',replace(replace('①：对手场上的怪兽的数量多于自己场上的怪兽的情况下，可从以下效果中选择1个发动（此卡名的以下效果1回合仅可各选择1次）。\r\n●以对手场上的表侧表示怪兽的数量为上限，以场上的表侧表示卡为对象，支付作为对象的数量×800的LP可以发动。将该卡的效果直至回合结束时为止无效。\r\n●对手发动手牌・墓地的怪兽的效果时可以发动。将该效果无效。','\r',char(13)),'\n',char(10)),'发动','把场上表侧表示卡的效果无效','手牌墓地发动的怪兽效果无效','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38817296,'月女神之至天',replace(replace('①：对手场上的怪兽的数量多于自己场上的怪兽的情况下，可从以下效果中选择1个发动（此卡名的以下效果1回合仅可各选择1次）。\r\n●以对手场上的表侧表示怪兽的数量为上限，以场上的表侧表示卡为对象，支付作为对象的数量×800的LP可以发动。将该卡的效果直至回合结束时为止无效。\r\n●对手发动手牌・墓地的怪兽的效果时可以发动。将该效果无效。','\r',char(13)),'\n',char(10)),'发动','把场上表侧表示卡的效果无效','手牌墓地发动的怪兽效果无效','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38834303,'计数物吸除器','支付５００点LP。取除场上的所有计数物。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38837163,'豹人',replace(replace('此卡不可通常召唤。将存在于我方墓地的２只兽战士族怪兽从游戏中除外的场合可特殊召唤。１回合１次，可从手牌舍弃１只兽战士族怪兽，从以下效果选择１个发动。\r\n●此卡的攻击力直至结束阶段时变成２倍。\r\n●此回合的此卡可直接攻击对手玩家。','\r',char(13)),'\n',char(10)),'选择效果发动','此卡的攻击力直到结束阶段时变成2倍。','这个回合此卡可以直接攻击对手玩家。','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38844957,'紧急仪式术','①：自己场上不存在仪式怪兽的情况下，从自己手牌・墓地将1张仪式魔法卡除外可以发动。此卡的效果变为与该仪式魔法卡发动时的仪式召唤的效果相同。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38848158,'点火骑士・团结','此卡名的卡１回合仅可发动１张。①：以自己场上的１张“点火骑士”卡为对象可以发动。将该卡破坏，从牌组将１只“点火骑士”怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38891741,'神之摄理','①：怪兽的效果・魔法・陷阱卡发动时，从手牌将1张与该效果相同种类（怪兽・魔法・陷阱）的卡舍弃可以发动。将该发动无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38898779,'巨人斗士／爆裂',replace(replace('此卡不可通常召唤，仅可通过“爆裂模式”的效果特殊召唤。\r\n①：此卡特殊召唤时可以发动。从牌组将最多2只战士族怪兽送至墓地。\r\n②：只要此卡存在于怪兽区域，对手场上的怪兽的攻击力下降自己墓地的战士族怪兽的数量×100的数值。\r\n③：场上的此卡被破坏时，以自己墓地的1只“巨人斗士”为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'送墓','特殊召唤「巨人斗士」','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38904695,'无限狱地狱恶魔',replace(replace('协调+1只以上协调以外的怪兽\r\n①：1个回合1次，可以以场上的1张表侧表示的卡为对象发动。使该卡的效果无效，直至回合结束时为止。在自己的手牌数量为0的情况下，还可以破坏该卡。\r\n②：只要自己的手牌数量为0，此卡在与对手怪兽进行的战斗中，给对手的战斗伤害就将加倍。\r\n③：将此卡作为同步素材的暗属性同步怪兽在1个战斗阶段最多可以攻击怪兽2次。','\r',char(13)),'\n',char(10)),'','是否破坏？','「无限狱地狱恶魔」为同步素材','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38910263,'炎王兽 哈奴曼',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己场上的表侧表示“炎王”怪兽因效果被破坏的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：此卡存在于怪兽区域，且魔法・陷阱卡的效果发动时可以发动。将该发动无效，将自己的手牌・场上（表侧表示）此卡以外的１只炎属性怪兽破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38916461,'稀有金属战士','全身覆盖着金属装甲的战士。与“稀有金属女郎”融合提升力量。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38916526,'空牙团的英雄 拉法尔','这个卡名的①②的效果1个回合各只可使用1次。①：这张卡特殊召唤成功的情况下可以发动。把“空牙团的英雄 拉法尔”以外的自己场上的“空牙团”怪兽种类数量的卡从自己牌组上面翻开。挑选其中的1张加入手牌，剩下的卡放回牌组。②：对手怪兽的效果发动时，从手牌扔掉1张“空牙团”卡后可以发动。将该发动无效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38942059,'音女','擅长操纵音律的少女。使用音符镰刀进行攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38943357,'魔力统辖',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从牌组将1张“恩底弥翁”卡加入手牌。然后，可最多依自己场上・墓地的“魔力统辖”“魔力掌握”的数量，尽可能地在自己场上的能放魔力计数物的卡上放魔力计数物。','\r',char(13)),'\n',char(10)),'要在场上放置魔力计数物吗？','请选择要放置魔力计数物的卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38955728,'龙核的咒灵者',replace(replace('穿越永恒不断追逐狩猎的龙身上溅出的血，赋予了女战士非常人可比之力量。她的魂魄被死去的龙的怨嗟浸染，最终化身为播撒疫病的邪恶龙核。\r\n可归之故里不复存在，甚至连她自己也已记不起，当初出于本能血染刀锋，究竟是为了什么......','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38960450,'武器呼唤','此卡名的卡1回合仅可发动1张。①：从牌组将1张装备魔法卡加入手牌。然后，可将该卡装备于自己场上1只可装备的怪兽。','是否给怪兽装备？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38973775,'光子蜥蜴','可解放此卡并发动。从牌组将１只等级４以下冠有“光子”之名的怪兽加入手牌。“光子蜥蜴”的效果１回合只可使用１次。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38975369,'军荼利','此卡不可特殊召唤。召唤・反转此卡回合的结束阶段时此卡回到持有者的手牌中。此卡与同步怪兽进行战斗的场合，不进行伤害计算，令该怪兽和此卡回到持有者的手牌中。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38981606,'沙漠保卫者','此卡的守备力上升场上的魔法、陷阱卡数量×３００点。我方场上的昆虫族怪兽被破坏的场合，可以此卡代替破坏。','是否使用「沙漠保卫者」的效果代替破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38982356,'冰','全身由冰所构成的战士。他所触及的一切都会被冻结。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38984832,'第55次GMX实验报告',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：将自己手牌・场上的怪兽作为融合素材，将1只恐龙族融合怪兽融合召唤。对手场上存在怪兽的情况下，可将自己牌组的最多1只“GMX”怪兽也作为融合素材。\r\n②：在自己的主要阶段将墓地的此卡除外可以发动。从自己牌组上面翻开卡，直至翻到“GMX”卡为止，将该“GMX”卡加入手牌。将剩余的放回牌组。','\r',char(13)),'\n',char(10)),'融合召唤','翻卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38988538,'机动雾龙・蛇颈龙',replace(replace('←6 【灵摆】 6→\r\n①：只要此卡存在于灵摆区域，仅限１次，可将以自己场上的其他“机动雾龙”卡为对象发动的效果无效。然后，将此卡破坏。\r\n【怪兽效果】\r\n①：只要此卡存在于怪兽区域，对手场上的怪兽的攻击力・守备力下降相当于自己场上的“机动雾龙”卡的数量×１００的数值。','\r',char(13)),'\n',char(10)),'是否使用「机动雾龙·蛇颈龙」的效果？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38992735,'波动加农炮','①：将魔法与陷阱区域里的表侧表示的此卡送至墓地可以发动。给予对手此卡发动后经过的自己准备阶段的次数×１０００点的伤害。','给对手此卡发动后经过的自己的准备阶段数*1000的伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(38999506,'宇宙女皇','统治着存在于宇宙中所有星球的女王。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39000945,'恩底弥翁之女皇',replace(replace('←2 【灵摆】 2→\r\n①：每当自己或对手发动魔法卡，就在此卡上放1个魔力计数物。\n②：去除此卡的3个魔力计数物可以发动。将手牌的1只能放魔力计数物的怪兽和此卡特殊召唤，在该2只上各放1个魔力计数物。\r\n【怪兽效果】\r\n自己1回合仅可特殊召唤1次“恩底弥翁之女皇”。\n①：此卡特殊召唤的情况下，以自己场上的1张其他放有魔力计数物的卡和对手场上的1张卡为对象可以发动。将该自己及对手的卡放回手牌。然后，依从自己场上放回手牌的卡原先放有的魔力计数物数量，在此卡上放魔力计数物。\n②：放有魔力计数物的此卡因战斗被破坏时可以发动。从牌组将1张“恩底弥翁”卡加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','回到手牌并放置计数物','从牌组加入手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39004808,'水妖','潜伏在海里的半鱼人，掀起巨大的黑暗海啸进行攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39016067,'龙剑士 乘风独角麒麟 别型',replace(replace('←2 【灵摆】 2→\r\n此卡名的灵摆效果1回合仅可使用1次。\n①：自己另一方的灵摆区域有卡存在的情况下，可从以下效果中选择1个发动。\n●将此卡特殊召唤。\n●将此卡破坏，将自己灵摆区域的1张等级5以下的灵摆怪兽卡特殊召唤。\r\n【怪兽效果】\r\n此卡名的②怪兽效果1回合仅可使用1次。\n①：只要灵摆召唤的此卡存在于怪兽区域，此卡不会因对手的效果被破坏，对手不可将此卡作为效果的对象。\n②：在自己・对手回合中，以自己场上的1张灵摆怪兽卡和对手场上的1张卡为对象可以发动。将该卡放回手牌。','\r',char(13)),'\n',char(10)),'灵摆效果发动','回到手牌','此卡特殊召唤','此卡破坏','','','','','','','','','','','','');
INSERT INTO texts VALUES(39019325,'玉碎指令','可选择自己场上１只除衍生物以外的等级２以下的通常怪兽并发动。解放被选择通常怪兽，最多挑选对手场上的２张魔法・陷阱卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39024589,'魔界剧团－潮人配角',replace(replace('←8 【灵摆】 8→\r\n①：自己灵摆召唤成功时可以发动。从自己的额外牌组将1只表侧表示的等级1或等级8的“魔界剧团”灵摆怪兽加入手牌。\r\n【怪兽效果】\r\n此卡名的怪兽效果1回合仅可使用1次。①：自己的灵摆区域有2张“魔界剧团”卡存在的情况下，解放此卡可以发动。从手牌及自己的额外牌组的表侧表示怪兽中，将1只等级1或等级8的“魔界剧团”灵摆怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39030163,'银河眼全装甲光子龙',replace(replace('等级８怪兽×３\r\n此卡也可重叠在自己场上“银河眼全装甲光子龙”以外的“银河眼”超量怪兽上面来超量召唤。①：１回合１次，以此卡的最多２张装备卡为对象可以发动。将该卡重叠在此卡下方作为超量素材。②：１回合１次，去除此卡的１个超量素材，以对手场上的１张表侧表示的卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'是否在「银河眼」超量怪兽上面重叠超量召唤？','把装备卡作为超量素材','把对手1张卡破坏','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39030883,'暗黑武装龙・湮灭',replace(replace('此卡不可通常召唤。\r\n仅可在自己墓地的暗属性怪兽为3只的情况下特殊召唤。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：向对手出示手牌的此卡可以发动。从手牌将1只等级6以下的暗属性怪兽特殊召唤。此回合，自己仅可特殊召唤暗属性怪兽。\r\n②：在自己・对手的主要阶段，从自己墓地将最多3只暗属性怪兽除外，依其数量以场上的卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39030884,'暗黑武装龙・湮灭',replace(replace('此卡不可通常召唤。\r\n仅可在自己墓地的暗属性怪兽为3只的情况下特殊召唤。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：向对手出示手牌的此卡可以发动。从手牌将1只等级6以下的暗属性怪兽特殊召唤。此回合，自己仅可特殊召唤暗属性怪兽。\r\n②：在自己・对手的主要阶段，从自己墓地将最多3只暗属性怪兽除外，依其数量以场上的卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39033131,'妖怪的巢穴祠堂',replace(replace('此卡牌名的①②效果１回合１次，只可使用其中１个。\r\n①：我方场上不存在有怪兽的场合，可以我方墓地的１只不死族怪兽为对象发动。特殊召唤该怪兽。\r\n②：我方场上不存在有怪兽的场合，可将墓地的此卡除外，并以我方墓地的１只不死族怪兽为对象发动。使该怪兽的效果无效并特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39037517,'核成甲虫','此卡的控制者每次我方的结束阶段，从手牌将１张“核成之钢核”送入墓地，或向对手展示１只手牌的昆虫族怪兽。或者不执行上述两项破坏此卡。光属性或暗属性怪兽以攻击表示特殊召唤成功时，将该怪兽变成守备表示。','选择一张「核成之钢核」送至墓地','选择一张昆虫族怪兽给对手观看','破坏「核成甲虫」','改变表示形式','','','','','','','','','','','','');
INSERT INTO texts VALUES(39041550,'骑甲虫 鳞粉轰炸兵',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：昆虫族怪兽被召唤・特殊召唤至自己场上的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：对手发动场上怪兽的效果时，解放自己场上的１只昆虫族怪兽可以发动。将该怪兽破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39041729,'时空超越','①：可从我方墓地除外２只或以上的恐龙族怪兽并发动。从我方手牌、墓地挑选１只等级与被除外怪兽的等级合计相同的恐龙族怪兽特殊召唤。以此效果特殊召唤的怪兽，此回合不可攻击。','请选择要特殊召唤的怪兽的等级','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39049051,'歌冰丽月',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从手牌将1只等级4以下的天使族・魔法师族・鸟兽族・兽战士族怪兽特殊召唤，装备此卡。然后，可将场上的龙族怪兽全部放回手牌。\r\n②：在魔法与陷阱区域表侧表示的此卡被送至墓地的回合的结束阶段可以发动。从牌组将1张“融合”魔法卡或“结合”魔法卡，或1只“寄生结融者”加入手牌。','\r',char(13)),'\n',char(10)),'','','是否把龙族怪兽全部回到持有者手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39053882,'V黑影',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将“V黑影”以外的1只“黑影”怪兽加入手牌。\r\n②：将墓地的此卡除外，以自己场上的1只“假面魔蹈士”超量怪兽为对象可以发动。从额外牌组将1只阶级比该自己的怪兽高1的“编号”怪兽重叠在对象怪兽上面，视为超量召唤特殊召唤。','\r',char(13)),'\n',char(10)),'检索','超量召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39064822,'梦魇曲・格布林',replace(replace('卡名不同的怪兽2只\r\n①：此卡连接召唤成功的情况下，舍弃1张手牌可以发动。此效果发动时此卡为相互连接状态的情况下，自己可从牌组抽1张。自己在通常召唤外仅可追加1次，在此回合的主要阶段，从手牌将1只怪兽召唤至此卡连接端的自己场上。②：只要此卡存在于怪兽区域，自己场上相互连接状态的怪兽不会成为效果对象。','\r',char(13)),'\n',char(10)),'','是否抽牌？','使用「梦梦魇曲影·格布林」的效果召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39078434,'巨型蚁狮',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：对手怪兽攻击宣言时可以发动。从手牌将此卡特殊召唤。\r\n②：此卡召唤・特殊召唤成功的情况下可以发动。从自己的手牌・墓地挑选１只昆虫族怪兽，视为攻击力・守备力上升５００的装备卡装备于此卡。\r\n③：１回合１次，昆虫族怪兽进行战斗的伤害步骤开始时，以自己及对手场上的各１张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39091951,'生化熊猫','此卡因战斗被破坏并送入墓地时，可支付８００LP发动。从牌组特殊召唤１只等级４的念动力族怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39103226,'地磅计量','①：对手场上的怪兽数量比自己场上的怪兽多２只以上的情况下可以发动。对手必须将自身场上的怪兽送至墓地，直至只剩１只为止。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39109382,'机皇创出',replace(replace('此卡名的卡在1个回合中仅可发动1张，此卡名的效果②③在1个回合中仅可各使用1次。\r\n①：作为此卡发动时的效果处理，可以从牌组选择1只“机皇”怪兽加入手牌。\r\n②：从手牌中扔掉1张卡后，可以以自己场上的1只怪兽为对象发动。破坏该怪兽。\r\n③：自己场上表侧表示的“机皇”怪兽因战斗、效果被破坏时，可以以场上此卡以外的1张表侧表示的魔法・陷阱卡为对象发动。破坏该卡。','\r',char(13)),'\n',char(10)),'是否从牌组把1只「机皇」怪兽加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39111158,'三角龙','以头上的３个角为特征的恶魔龙。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39114494,'肃声祝福',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：以“肃声祝福”以外的、自己墓地・除外状态的１张“肃声”卡为对象可以发动。将该卡加入手牌。\r\n②：仪式怪兽以外的怪兽以表侧表示被召唤・特殊召唤的情况下可以发动。为使合计等级为仪式召唤的怪兽的等级以上，解放自己的手牌・场上的怪兽，从手牌将１只战士族・龙族的光属性仪式怪兽仪式召唤。以此效果特殊召唤的怪兽不会因战斗被破坏。','\r',char(13)),'\n',char(10)),'','回收「肃声」卡','仪式召唤战士族·龙族光属性仪式怪兽','「肃声祝福」效果适用中，不会被战斗破坏','','','','','','','','','','','','');
INSERT INTO texts VALUES(39118197,'机偶武者 六参壹八','此卡能够攻击的场合必须攻击。攻击表示的此卡被选择为攻击对象时，将此卡变成守备表示。场上冠有“机偶”之名的怪兽被破坏时，此卡的攻击力上升４００点。','变成守备表示','攻击上升','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39122311,'龙魂的幻泉','①：可以我方墓地的１只怪兽为对象发动此卡。以守备表示特殊召唤该怪兽。只要此卡存在于魔法与陷阱区域，特殊召唤而来的该怪兽之种族变成幻龙族。此卡从场上离开时该怪兽被破坏。该怪兽从场上离开时此卡被破坏。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39123673,'魔力到达',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从自己牌组・墓地将除“魔力到达”以外的、1张效果文本记载有“魔力计数物”的卡加入手牌。自己场上存在等级7以上的“恩底弥翁”怪兽卡的情况下，进而可适用以下效果。\r\n●去除自己场上任意数量的魔力计数物，依其数量将对手场上的表侧表示卡的效果无效并破坏。','\r',char(13)),'\n',char(10)),'发动','是否取除计数物？','请选择要取除计数物的数量','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39131963,'死亡反击','破坏通过直接攻击给予玩家战斗伤害的怪兽。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39138610,'合协码语者＠伊格尼斯者',replace(replace('效果怪兽3只以上\r\n此卡名的②效果1回合仅可使用1次。\r\n①：此卡连接召唤的情况下可以发动。从自己墓地将攻击力2300的电子界族怪兽尽可能地特殊召唤至此卡连接端的自己场上，此卡的攻击力上升其数量×500的数值。此效果发动后，直至回合结束时为止，自己不可特殊召唤怪兽。\r\n②：对手发动卡的效果时，解放1只此卡连接端的、自己的连接怪兽可以发动。将该发动无效并除外。','\r',char(13)),'\n',char(10)),'特殊召唤','发动无效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39139935,'编号33 先史遗产－超兵器天空之城',replace(replace('等级５怪兽×２\r\n①：１回合１次，移除此卡的１个超量素材，以对手场上的１只拥有与原本攻击力不同的攻击力的怪兽作为对象可以发动。给予对手该怪兽的攻击力与该原本攻击力差额数值的伤害，此卡的攻击力上升通过此效果所给予的伤害数值。','\r',char(13)),'\n',char(10)),'攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39153655,'DD 刻耳柏洛斯',replace(replace('←6 【灵摆】 6→\r\n①：１回合１次，以自己场上的１只“DD”怪兽为对象可以发动。将该怪兽的等级改成４，攻击力・守备力上升４００。\r\n【怪兽效果】\r\n①：此卡从手牌灵摆召唤成功时，自己场上有“DD 刻耳柏洛斯”以外的“DD”怪兽存在的情况下，以自己墓地的１张永续魔法卡为对象可以发动。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'攻守变换','卡片回收','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39163598,'行星汗染病毒','可释放我方场上的１只冠有“外星人”之名的怪兽并发动。破坏对手场上所有未放置有A计数物的表侧表示怪兽。以对手回合计算的３个回合期间，在对手召唤、反转召唤、特殊召唤的怪兽全部放置１个A计数物。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39168895,'愤怒的类人猿','此卡以表侧守备表示存在于场上的场合，此卡被破坏。此卡在能够攻击的场合必须进行攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39175982,'黑暗杀手','他会挥舞像螳螂般巨大的手臂进行攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39180960,'严格死神','①：此卡在反转时发动。双方玩家各自选择１张手牌舍弃。②此卡在因与怪兽战斗而被破坏时发动。该怪兽的攻击力、守备力下降５００。','丢弃手牌','攻守下降500','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39185163,'死灵王 堕哈司拉',replace(replace('此卡名的②效果１回合仅可使用１次。①：“死灵王 堕哈司拉”以外的不死族怪兽的效果发动时可以发动（同一连锁上最多１次）。从以下效果中挑选１个适用。此回合，自己的“死灵王 堕哈司拉”的效果不可适用同一效果。\r\n●将该效果无效。\r\n●将自己或对手的场上・墓地的１只怪兽除外。\r\n②：场地区域有表侧表示的卡存在的情况下，在双方的准备阶段可以发动。将墓地的此卡以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'','效果无效','怪兽除外','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39188539,'风暴射手',replace(replace('１回合１次，可从以下效果选择１个并发动。\r\n●可指定１处未使用的相邻怪兽区并发动。将我方场上的此卡移动至指定区域。\r\n●选择１张与此卡相同纵列的对手卡牌返回至持有者的手牌。','\r',char(13)),'\n',char(10)),'移动到没有使用的相邻的怪兽卡区域','正对面的1张对手的卡回到手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39191307,'假面龙','①：此卡因战斗被破坏并被送至墓地时可以发动。从牌组将１只攻击力１５００以下的龙族怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39210885,'天魔之声选器－『华耳琴璃』',replace(replace('此卡名的卡１回合仅可发动１张，此卡名的②效果１回合仅可使用１次。\r\n①：作为此卡发动时的效果处理，可从牌组将１只“华耳琴璃”怪兽加入手牌。\r\n②：响鸣计数物被放在自己的灵摆区域的卡上，使得该卡的响鸣计数物变为３个的情况下，以对手场上的１只怪兽为对象可以发动。直至结束阶段为止获得该怪兽的控制权。以此效果获得控制权的怪兽不可攻击宣言。','\r',char(13)),'\n',char(10)),'','是否从牌组把1只「华耳琴璃」怪兽加入手牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39229392,'叠放狙击者','此卡不可特殊召唤。此卡召唤成功时，变成守备表示。此外，我方场上存在有持有超量素材的超量怪兽的场合，可将墓地的此卡从游戏中除外、并选择对手场上的１只怪兽发动。被选择怪兽的攻击力下降相当于我方场上超量素材的数量×５００点。','变成守备表示','攻击下降','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39238953,'天声之服从',replace(replace('①：支付2000LP，宣言1个怪兽卡名可以发动。对手确认自身的牌组，有被宣言的怪兽的情况下，将其中1只给彼此确认，对手从以下效果中挑选1个适用。\r\n●将确认的卡加入发动此卡的玩家手牌。\r\n●将确认的卡无视召唤条件，以攻击表示特殊召唤至发动此卡的玩家场上。','\r',char(13)),'\n',char(10)),'加入手牌','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39239728,'皇家守卫','为了守护王族而开发的，拥有自我意志的机械军队。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39246582,'绒毛动物・狗','此卡名的效果1回合仅可使用1次。①：此卡从手牌召唤・特殊召唤成功时可以发动。从牌组将1只“锋利小鬼・剪刀”或“绒毛动物・狗”以外的1只“绒毛动物”怪兽加入手牌。','牌组检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39256679,'磁石战士贝塔','以阿尔法、贝塔、伽玛变形合体。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39260991,'水伶女－灯鱼','①：１回合１次，可在我方主要阶段发动。从牌组将１张“水剧台”卡牌加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39261576,'粒子结合','将根据冠有“宝石骑士”之名的融合怪兽卡规定的融合素材怪兽从我方场上送入墓地，从额外牌组融合召唤１只该融合怪兽。以此效果融合召唤成功时，将墓地的此卡从游戏中除外，并选择１只该融合召唤所使用的冠有“宝石骑士”之名的融合素材怪兽发动。直至回合结束时。该融合怪兽的攻击力上升被选择怪兽的攻击力数值。','攻击上升','请选择一个使用的融合素材','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39271553,'方程式运动员导航仪','此卡名的①②效果1回合仅可各使用1次。①：此卡存在于手牌・墓地的情况下，以自己场上1只所拥有之等级高于其原本等级的“方程式运动员”怪兽为对象可以发动。将此卡特殊召唤，对象怪兽的等级下降与其原本等级之差。以此效果特殊召唤的此卡的等级变为与该差值相同。②：此卡召唤・特殊召唤成功的情况下可以发动。从牌组将1张“方程式运动员”场地魔法卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39272762,'超银河眼光子龙',replace(replace('等级８怪兽×３\r\n①：此卡以“银河眼光子龙”作为素材超量召唤成功的情况下发动。将场上此卡以外的所有表侧表示卡的效果无效。②：１回合１次，去除此卡的１个超量素材可以发动。去除对手场上的所有超量素材，此回合，此卡的攻击力上升相当于以此效果去除的数量×５００的数值。进而，此回合此卡在１次战斗阶段中可攻击最多为以此效果去除数量的次数。','\r',char(13)),'\n',char(10)),'效果无效','取除素材','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39275698,'神鹰羽毛休憩','此卡名的卡１回合仅可发动１张。①：从自己墓地的“神鹰女郎”、“神鹰女郎三姐妹”中，以合计３只为对象可以发动。将该卡加入牌组洗牌。然后自己从牌组抽１张。在自己场上有等级５以上“神鹰”怪兽存在的状态下发动的情况下，抽牌张数变为２张。此卡发动后，直至回合结束时为止自己仅可特殊召唤风属性怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39276790,'真剑胜负','①：在伤害步骤怪兽效果、魔法、陷阱卡发动时可发动。使该发动无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39284521,'机甲部队・加农炮','此卡不可通常召唤。将手牌此卡以外任意数量的机械族怪兽送至墓地的情况下可以特殊召唤。①：此卡的攻击力上升相当于为特殊召唤此卡送至墓地的怪兽数量×８００的数值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39299733,'命运的战车',replace(replace('此卡牌名按规定也被视为“女战神”卡牌。\r\n①：１回合１次，可从以下效果选择１个并发动。\r\n●以我方场上的１只天使族怪兽为对象，并将此卡视为装备卡装备该怪兽。装备怪兽因战斗、效果被破坏的场合，破坏此卡作为代替。\r\n●特殊召唤被装备的此卡。\r\n②：装备怪兽可进行直接攻击。因该直接攻击给予对手的战斗伤害减半。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39303359,'古代机械齿轮骑士',replace(replace('①：只要此卡存在于场上、墓地，被视为通常怪兽。\r\n②：被视为场上的通常怪兽的此卡，可作为通常召唤再１次召唤。此种场合此卡被视为效果怪兽获得以下效果。\r\n●此卡攻击的场合，直至伤害步骤结束时，对手不可发动魔法，陷阱卡。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39317553,'旋坏钻蜂 贝斯佩内特',replace(replace('等级5怪兽×2\r\n“旋坏钻蜂 贝斯佩内特”1回合1次，也可重叠在自己场上的阶级4超量怪兽上面来超量召唤。\r\n此卡在被超量召唤的回合不可作为超量召唤的素材。\r\n此卡名的②效果1回合仅可使用1次。\r\n①：此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。\r\n②：超量召唤的此卡因对手被破坏的情况下，以自己墓地的1只等级5以下的怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'是否在4阶超量怪兽上面重叠来超量召唤？','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39321065,'沉默剑士・零',replace(replace('此卡名的③效果１回合仅可使用１次。\r\n①：在自己・对手的准备阶段发动。此卡的等级上升１。\r\n②：此卡的等级高于原本等级的情况下，此卡的攻击力上升相当于其数值之差×５００的数值。\r\n③：对手发动以自己场上的、“光之黄金柜”或记载有该卡名的怪兽为对象的效果时可以发动。将该发动无效，此卡的等级上升１。','\r',char(13)),'\n',char(10)),'等级上升','发动无效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39341885,'绚岚之海灵 伐楼仑',replace(replace('“绚岚”怪兽2只\r\n此卡名的①②③效果1回合仅可各使用1次。\r\n①：此卡连接召唤的情况下可以发动。从自己牌组・墓地将1张“气旋”加入手牌。\r\n②：以包含自己场上的“绚岚”怪兽在内的、场上的2只表侧表示怪兽为对象可以发动。将该怪兽视为永续魔法卡，以表侧表示放在原本持有者的魔法与陷阱区域。\r\n③：速攻魔法卡发动的情况下可以发动。从自己牌组・墓地将1张“绚岚”永续陷阱卡以表侧表示放在自己场上。','\r',char(13)),'\n',char(10)),'检索','当作永续魔法卡放置','放置永续陷阱卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39343610,'黑暗烈焰龙',replace(replace('①：此卡从墓地特殊召唤成功的场合发动。此卡的攻击力、守备力变为原本数值的２倍。\r\n②：此卡在战斗中破坏怪兽并送入墓地的场合发动。给予对手相当于该怪兽原本攻击力数值的伤害。','\r',char(13)),'\n',char(10)),'攻守变换','LP伤害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39354437,'冰翡之爱姬尔','此卡名的①②效果１回合仅可各使用１次。①：此卡召唤・特殊召唤成功的情况下可以发动。从牌组将１张“冰翡”魔法・陷阱卡加入手牌。②：此卡成为对手的效果的对象时，或被选择为对手怪兽的攻击对象时可以发动。从自己的手牌・墓地挑选“冰翡之爱姬尔”以外的１只水属性怪兽特殊召唤。以此效果特殊召唤的怪兽于结束阶段放回持有者的手牌。此回合，此卡仅１次不会因战斗・效果被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39357122,'真红眼凶雷皇－邪性恶魔',replace(replace('①：只要此卡存在于场上・墓地，视为通常怪兽。②：场上视为通常怪兽的此卡可作为通常召唤再召唤１次。该情况下，此卡改视为效果怪兽，获得以下效果。\r\n●１回合１次，在自己的主要阶段可以发动。将对手场上守备力低于此卡攻击力的表侧表示怪兽全部破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39373426,'秘旋谍任务－夺回',replace(replace('此卡发动后，将在第３次自己的结束阶段被破坏。\r\n①：１回合１次，“秘旋谍”怪兽被特殊召唤至自己场上的情况下，以对手场上的１只怪兽为对象可以发动。直至结束阶段为止获得该怪兽的控制权。以此效果获得控制权的怪兽此回合不可直接攻击。\r\n②：自己场上的“秘旋谍”怪兽将被战斗・效果破坏的情况下，作为该１只将被破坏的怪兽的代替，可将墓地的此卡除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39387565,'真红眼之铠旋','此卡名的①②效果１回合仅可各使用１次。①：自己场上有“真红眼”怪兽存在的情况下，以自己墓地的１只通常怪兽为对象，可以发动此效果。将该怪兽特殊召唤。②：此卡因对手的效果被破坏并被送至墓地的情况下，以自己墓地的１只“真红眼”怪兽为对象可以发动。将该怪兽特殊召唤。','是否使用效果？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39389320,'野蛮人国王','①：１回合１次，可释放我方场上除此卡以外的任意数量战士族怪兽并发动。此回合，此卡除了通常攻击以外，在１次的攻击阶段中，可进行最多以发动此效果为目的而释放的怪兽数量的攻击。','多次攻击','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39392286,'神鹰调香师','此卡名的②效果１回合仅可使用１次。①：此卡只要存在于场上・墓地，卡名视为“神鹰女郎”。②：此卡召唤・特殊召唤成功的情况下可以发动。从牌组将１张记载有“神鹰女郎三姐妹”卡名的魔法・陷阱卡加入手牌。在自己场上有等级５以上“神鹰”怪兽存在的状态下发动的情况下，其张数变为最多２张（同名卡最多１张）。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39396763,'恐龙基座',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己LP少于对手的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：在自己的主要阶段可以发动。将由融合怪兽卡决定的、包含场上的此卡在内的融合素材怪兽从自己的手牌・场上送至墓地，将该１只融合怪兽从额外牌组融合召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39399168,'夏古拉的复活','降临“夏古拉”的必备。必须从手牌・我方场上解放合计等级达到７以上的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39402797,'三戟天龙',replace(replace('龙族协调＋协调以外的龙族怪兽１只以上\r\n此卡仅可以同步召唤方式特殊召唤。\r\n①：此卡同步召唤时，以自己场上其他最多２张卡为对象可以发动。将该自己的卡破坏。此卡在此回合，除通常攻击外，在１次战斗阶段中可追加的攻击次数最多为以此效果破坏的卡的数量。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39432962,'怒怒怒魔女','①：此卡召唤・特殊召唤成功时可以发动。从手牌将“怒怒怒魔女”以外的１只“怒怒怒”怪兽以表侧攻击表示或里侧守备表示特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39439590,'电子恐龙','①：对手从手牌将怪兽特殊召唤时可以发动。从手牌中将此卡特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39440937,'妨害电波','有同步怪兽以攻击表示存在于场上的场合，可发动。将场上的所有同步怪兽变成表侧守备表示。并在此回合之结束阶段时，将场上的所有同步怪兽返回至持有者的额外牌组。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39454112,'荒谬',replace(replace('①：只要此卡存在于魔法＆陷阱卡区，我方或对手摇骰子的场合，可将其中１个数字当作以下数字适用。\r\n●出现１、３、５的场合：视作６。\r\n●出现２、４、６的场合：视作１。','\r',char(13)),'\n',char(10)),'是否要使用「荒谬」的效果？','要改变第几次骰子的结果？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39468724,'日神炎枪的影灵衣',replace(replace('以“影灵衣”仪式魔法卡降临\r\n此卡仅可以仪式召唤方式特殊召唤，且仪式召唤仅可使用等级10以外的怪兽。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：从手牌将此卡舍弃可以发动。将自己手牌・场上的最多2只“影灵衣”怪兽解放，依其数量从牌组将“影灵衣”卡送至墓地。\r\n②：怪兽的效果发动时，将自己手牌・场上的1只怪兽解放可以发动。将该发动无效并除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39475024,'骸之魔妖－饿者髑髅',replace(replace('协调＋协调以外的怪兽１只以上\r\n此卡名的②③效果１回合仅可各使用１次。\r\n①：“骸之魔妖－饿者髑髅”在自己场上仅可有１张以表侧表示存在。\r\n②：此卡存在于墓地，且自己的连接怪兽因战斗或对手的效果被破坏的情况下可以发动。从自己的墓地将１只其他的不死族怪兽除外，将此卡特殊召唤。\r\n③：此卡从墓地特殊召唤的情况下可以发动。此回合，表侧表示的此卡不受其他卡的效果影响。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39477584,'魔轰神勒维亚坦',replace(replace('“魔轰神”协调＋协调以外的怪兽1只以上\r\n①：场上的此卡被破坏并被送至墓地时，以自己墓地的最多3只“魔轰神”怪兽为对象可以发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39491690,'圣徒・救赎',replace(replace('此卡名在规则上也视为“白森”卡。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：以自己场上・墓地的、恶魔族・幻想魔族・魔法师族的融合・同步怪兽的数量为上限，以场上的卡为对象可以发动。将该卡放回手牌。\r\n②：此卡为发动怪兽的效果被送至墓地的情况下可以发动。将此卡放置在自己场上。','\r',char(13)),'\n',char(10)),'回到手牌','此卡在自己场上放置','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39505816,'炎天祸日灼伤',replace(replace('此卡名的效果１回合仅可使用１次。\r\n①：自己场上的表侧表示炎属性怪兽因战斗或对手的效果被破坏的情况下可以发动。从手牌将此卡特殊召唤。然后，可以挑选１只被破坏的自己墓地中的炎属性怪兽，并给予对手该攻击力一半数值的伤害。','\r',char(13)),'\n',char(10)),'特殊召唤','是否给与对手伤害？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39507162,'刀锋骑士',replace(replace('①：我方手牌为１张以下的场合，此卡的攻击力上升４００。\r\n②：我方场上没有此卡以外的怪兽存在的场合，此卡通过战斗破坏的反转怪兽的效果无效。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39512984,'宝石骑士统领・辉钻',replace(replace('“宝石骑士”怪兽×3\r\n此卡从额外牌组仅可通过融合召唤来特殊召唤。\r\n①：此卡的攻击力上升相当于自己墓地的“宝石”怪兽数量×100的数值。\r\n②：1回合1次，从自己墓地将1只等级7以下的“宝石骑士”融合怪兽除外可以发动。此卡直至结束阶段为止，获得与除外的怪兽原本卡名・效果相同的卡名・效果。','\r',char(13)),'\n',char(10)),'获得效果','复制效果结束','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39513225,'巴利安之七皇冀望乡',replace(replace('此卡名的②③效果1回合仅可各使用1次。\r\n①：只要此卡存在于场地区域，在此期间，双方1回合仅可从额外牌组特殊召唤“编号”怪兽以外的怪兽最多2次。\r\n②：在自己的主要阶段可以发动。从牌组将1只“黑影”怪兽加入手牌。然后，挑选自己的1张手牌舍弃。\r\n③：在自己・对手的结束阶段发动。双方受到场上的超量怪兽的数量×400的伤害。','\r',char(13)),'\n',char(10)),'','检索','受到伤害','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39520293,'废品盔甲',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：以此卡作为同步素材的同步怪兽不会因战斗被破坏。\r\n②：不是在此回合被送至墓地的此卡存在于墓地，且自己场上存在原本卡名包含“战士”、“同步士”、“星尘”中任一的同步怪兽的情况下可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'「废品盔甲」效果适用中','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39522887,'游魊之阴影 史诺匹奥斯',replace(replace('此卡名的①②③效果１回合仅可各使用１次。\r\n①：在自己・对手的主要阶段，从自己的手牌・墓地将２只鱼族怪兽除外可以发动。从手牌将此卡特殊召唤。\r\n②：此卡特殊召唤的情况下，以场上表侧表示的１张卡为对象可以发动。该卡从场上离开的情况下，将其除外。\r\n③：此卡被除外的情况下，从自己的墓地将１只鱼族怪兽除外可以发动。将此卡加入手牌。','\r',char(13)),'\n',char(10)),'','','「游魊的黑影 斯诺皮奥斯」效果适用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39526584,'礼品卡','对手恢复３０００LP。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39528955,'预言剑巫・圣骑联盟',replace(replace('包括“圣骑联盟”怪兽在内的效果怪兽2只\r\n①：此卡攻击力上升相当于此卡连接端的怪兽原本攻击力的数值。②：此卡连接端的怪兽不可攻击。③：1回合1次，效果怪兽被特殊召唤至此卡连接端的情况下，以此卡以外的自己或对手的主要怪兽区域的1只怪兽为对象可以发动。将该怪兽的位置移动至其他主要怪兽区域（不可向从该怪兽来看的对手场上移动）。','\r',char(13)),'\n',char(10)),'','请选择要移动的怪兽','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39531794,'脑灾害','①：可以１只被除外的我方念动力族怪兽为对象发动此卡。特殊召唤该怪兽。此卡从场上离开时，该怪兽被破坏。该怪兽被破坏时此卡被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39537362,'旅人的试练','①：对手怪兽攻击宣言时可以发动１次此效果。让对手随机挑选１张自己的手牌，并让对手猜测该卡片的种类（怪兽・魔法・陷阱）。猜错的情况下，将该攻击怪兽放回至持有者的手牌。','宣言卡种','是否现在使用「旅人的试练」的效果？','发动同时使用效果','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39552584,'暗黑界之龙神王 黑拉法',replace(replace('“暗黑界之龙神 黑拉法”＋暗属性怪兽\r\n此卡名的①效果１回合仅可使用１次。\r\n①：对手发动怪兽的效果・通常魔法・通常陷阱卡时可以发动。该效果变为“对手挑选自身的１张手牌舍弃”。\r\n②：融合召唤的此卡因对手从场上离开的情况下可以发动。从自己墓地的怪兽及被除外的自己的怪兽中，挑选１只“暗黑界之龙神 黑拉法”特殊召唤。然后，有手牌的玩家挑选自身的１张手牌舍弃。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39552864,'神圣球体','被神圣光辉所包围的天使的灵魂。据说看见其美丽姿态的人会实现心愿。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39564736,'重炼装融合','①：从我方手牌、场上将由“炼装勇士”融合怪兽卡规定之融合素材怪兽送入墓地，从额外牌组中融合召唤该１只融合怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39568067,'命运的旅途','此卡名的①②效果1回合仅可各使用1次。①：在自己的主要阶段可以发动。从牌组将1只记载有“勇者衍生物”的衍生物名的怪兽加入手牌，然后挑选1张手牌送至墓地。②：怪兽被召唤・特殊召唤的情况下可以发动。从牌组挑选1张记载有“勇者衍生物”的衍生物名的装备魔法卡加入手牌，或装备于自己场上的1只“勇者衍生物”。③：1回合仅1次，装备了装备卡的自己的怪兽不会因战斗被破坏。','','检索装备','装备','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39568068,'命运的旅途','此卡名的①②效果1回合仅可各使用1次。①：在自己的主要阶段可以发动。从牌组将1只记载有“勇者衍生物”的衍生物名的怪兽加入手牌，然后挑选1张手牌送至墓地。②：怪兽被召唤・特殊召唤的情况下可以发动。从牌组挑选1张记载有“勇者衍生物”的衍生物名的装备魔法卡加入手牌，或装备于自己场上的1只“勇者衍生物”。③：1回合仅1次，装备了装备卡的自己的怪兽不会因战斗被破坏。','','检索装备','装备','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39576656,'杀手旋律・爆响',replace(replace('“杀手旋律・酷莉普”＋协调1只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡同步召唤的情况下可以发动。确认对手的额外牌组，将其中1张直至结束阶段为止以表侧除外。然后，此卡的攻击力可上升相当于所除外怪兽的攻击力的数值。\r\n②：同步召唤的此卡被送至墓地的情况下可以发动。将此卡特殊召唤。然后，可适用以下效果。\r\n●确认对手的额外牌组，将其中2张直至结束阶段为止以表侧除外。','\r',char(13)),'\n',char(10)),'确认额外牌组并除外','特殊召唤','是否上升攻击力？','是否除外额外牌组？','直到结束阶段除外','','','','','','','','','','','');
INSERT INTO texts VALUES(39581190,'地中骇界的射手',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：自己场上存在其他“地中骇界”怪兽，且此卡攻击对手的里侧守备表示怪兽的伤害步骤开始时可以发动。将该对手怪兽放回牌组。\r\n②：场上的此卡因战斗・效果被破坏并被送至墓地的情况下可以发动。从牌组将1只“地中骇界”怪兽以表侧守备表示或里侧守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39613288,'黑暗至尊',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：以自己墓地的“黑暗结合”及记载有该卡名的魔法卡的数量为上限，以对手场上的表侧表示卡为对象可以发动。将该卡的效果直至回合结束时为止无效。\r\n②：从墓地将不是在此回合被送至墓地的此卡除外，以自己墓地・除外状态的最多5只“－英雄”怪兽为对象可以发动。将该怪兽放回牌组。','\r',char(13)),'\n',char(10)),'无效','回到牌组','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39618799,'电子天使－荼吉尼－','以“机械天使的仪式”降临。①：此卡仪式召唤成功的情况下可以发动。对手必须将自身场上的１只怪兽送至墓地。②：只要此卡存在于怪兽区域，自己的仪式怪兽攻击了守备表示的怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。③：在自己的结束阶段，以自己墓地的１只仪式怪兽或１张“机械天使的仪式”为对象可以发动。将该卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39622156,'编号26 次元孔路 绕道章鱼',replace(replace('等级３怪兽×２\r\n此卡名的①效果１回合仅可使用１次。\r\n①：自己・对手的战斗阶段开始时，去除此卡的１个超量素材可以发动。此战斗阶段中，仅可用１只怪兽攻击，该怪兽的攻击变为直接攻击。\r\n②：怪兽以直接攻击给予战斗伤害的伤害步骤结束时发动。该攻击的怪兽的控制权转移至从回合玩家来看的对手。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39643167,'兔耳导师',replace(replace('①：除“兔耳导师”以外的场上怪兽的效果发动时可发动。（同一连锁上最多1次。）放置1个兔耳计数物在该怪兽。放置有兔耳计数物的怪兽不会因战斗被破坏。\r\n②：1回合1次，可以放置有1只兔耳计数物的怪兽为对象发动。直至下一个回合的准备阶段，将该怪兽与此卡除外。此效果在对手回合也可发动。','\r',char(13)),'\n',char(10)),'放置计数物','怪兽除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39648965,'机皇兵神智一型',replace(replace('①：此卡的攻击力上升，上升的数值为场上此卡以外的“机皇”怪兽数量×100。\r\n②：1个回合1次，自己的此卡以外的“机皇”怪兽向守备表示怪兽进行攻击宣言时可以发动。在该战斗中，该自己的怪兽攻击了守备表示的怪兽时，将给对手造成战斗伤害，数值为攻击力超出其守备力的部分。','\r',char(13)),'\n',char(10)),'贯穿伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39672388,'进化龙 达尔维诺斯','此卡因冠有“进化虫”之名怪兽的效果特殊召唤成功时，可选择场上的１只表侧表示怪兽并发动。被选择怪兽的等级最多上升２级。','等级上升','等级上升１星','等级上升２星','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39674352,'哥吉咖・咖咖吉哥','精神已经崩溃，肉体为了追求更大的力量而暴走。其形姿中已无一分一毫过往的吉光片羽……','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39680372,'创造之圣刻印','此卡名的①②效果１回合１次，仅可使用其中１个。①：以自己场上的１只龙族超量怪兽为对象可以发动。将原本卡名与该自己的怪兽不同的１只“圣刻”超量怪兽重叠在对象怪兽上面，视为超量召唤从额外牌组特殊召唤。②：将墓地的此卡除外，以自己墓地的１只“圣刻”怪兽为对象可以发动。以守备表示形式将该怪兽特殊召唤。','超量召唤','墓地苏生','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39695323,'隆隆隆巨人','①：此卡召唤成功时，以自己墓地的１只“隆隆隆”怪兽为对象可以发动。以守备表示形式将该怪兽特殊召唤。然后此卡变为守备表示。②：此卡攻击的情况下，战斗阶段结束时变为守备表示。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39699564,'速炎星－戴豹',replace(replace('此卡名的效果１回合仅可使用１次。\r\n①：此卡召唤・特殊召唤的回合的主要阶段，解放自己场上的１只“炎星”怪兽可以发动。从牌组将１张“炎舞”魔法・陷阱卡放置在自己场上。','\r',char(13)),'\n',char(10)),'放置','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39701395,'调和的宝牌','①：从手牌扔掉1只攻击力1000以下的龙族协调可以发动。自己从牌组抽2张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39703254,'番茄小子','对手仅以除此卡以外的１只场上的植物族怪兽为对象发动魔法・陷阱卡时，可解放此卡并发动。从牌组抽取２张卡牌。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39706423,'GMX镇压部队 阿普特',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡存在于手牌，且自己场上存在“GMX”怪兽或恐龙族怪兽的情况下可以发动。将此卡特殊召唤。\r\n②：以场上的1只表侧表示怪兽为对象可以发动。从自己牌组上面翻开卡，直至翻到恐龙族怪兽为止，将该恐龙族怪兽送至墓地，将对象怪兽的种族直至回合结束时为止改成恐龙族。将剩余的所翻开的卡放回牌组。','\r',char(13)),'\n',char(10)),'特殊召唤','翻卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39711336,'不死王巫妖','此卡不可通常召唤。可以“大神官 迪・扎德”的效果特殊召唤。仅限１回合１次，此卡可变成里侧守备表示。此卡反转时，可选择我方墓地的１只不死族怪兽并特殊召唤。此外，以场上的此卡为对象的魔法、陷阱卡发动时发动。使该发动无效并破坏。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39712330,'决战的火盖','通过把我方墓地的１张怪兽卡从游戏中除外，可从手牌通常召唤１只通常怪兽。此效果仅在我方回合的主要阶段时发动。','通常召唤','是否现在使用「决战的火盖」的效果？','表侧表示召唤','里侧表示放置','','','','','','','','','','','','');
INSERT INTO texts VALUES(39719977,'三蝎联盟','可在自己场上有３只同名的通常怪兽（衍生物除外）存在时发动此卡。发动此卡的回合中，这３只同名的通常怪兽可对对手玩家进行直接攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39730727,'天威无崩之地','①：此卡只要存在于场地区域，效果怪兽以外的场上的表侧表示怪兽不受怪兽的效果影响。②：1回合1次，自己场上有效果怪兽以外的怪兽存在、对手特殊召唤效果怪兽的情况下可以发动。自己从牌组抽2张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39732186,'禁止档案蛇',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己的电子界族连接怪兽与对手怪兽进行战斗的伤害步骤开始时，将此卡从手牌送至墓地可以发动。将该对手怪兽放回持有者的手牌。\r\n②：此卡存在于墓地，自己的电子界族怪兽战斗将对手怪兽破坏并送至墓地时，从自己的墓地将１张卡除外，以自己墓地１只等级４以下的电子界族怪兽为对象可以发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39733924,'全装甲超量',replace(replace('①：场上有超量怪兽存在的情况下可以发动。进行１只超量怪兽的超量召唤。\r\n②：将墓地的此卡除外，以自己场上的１只超量怪兽为对象可以发动。将该怪兽以外的、自己场上（表侧表示）・墓地的１只超量怪兽视为拥有以下效果的装备魔法卡，装备于对象怪兽。\r\n●装备怪兽的攻击力上升相当于此卡攻击力的数值。\r\n●装备怪兽将被战斗・效果破坏的情况下，作为代替将此卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39751093,'龙宫之姬','此卡不可特殊召唤。召唤・反转此卡的回合的结束阶段时回到持有者的手牌中。召唤・反转此卡时，可选择对手场上１只表侧表示的怪兽，变更其表示形式。','返回手牌','改变表示形式','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39751094,'龙宫之姬','此卡不可特殊召唤。召唤・反转此卡的回合的结束阶段时回到持有者的手牌中。召唤・反转此卡时，可选择对手场上１只表侧表示的怪兽，变更其表示形式。','返回手牌','改变表示形式','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39752820,'星键士 利伊布',replace(replace('怪兽2只\r\n仅在自己的墓地有“星遗物”卡存在的情况下可连接召唤此卡。此卡名的①②效果1回合仅可各使用1次。①：在自己的主要阶段可以发动。从牌组挑选1张“星遗物”魔法・陷阱卡放置在自己场上。此回合，自己的墓地没有“星遗物”怪兽存在的情况下，不可发动该卡。②：连接召唤的此卡作为连接素材被送至墓地的情况下可以发动。挑选场上的1张卡放回持有者的牌组。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39753577,'魔妖变生',replace(replace('此卡名的卡１回合仅可发动１张，发动此卡的回合中，自己从额外牌组仅可特殊召唤“魔妖”怪兽。\r\n①：舍弃１张手牌，以自己墓地・除外状态的１只“魔妖”怪兽为对象可以发动。将该怪兽特殊召唤。此回合，对手不可将以此效果特殊召唤的怪兽作为效果的对象。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39761138,'新炎狱萨满','我方墓地存在有３只或以上的冠有“炎狱”之名的怪兽，并且此卡因战斗破坏对手怪兽的场合，选择对手墓地的１张卡牌从游戏中除外。此效果发动时，对手墓地不存在魔法卡的场合，进一步给予对手生命５００点伤害。','除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39761418,'秘仪之力ⅩⅨ－太阳',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：拥有掷硬币效果的卡存在于场上的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：此卡召唤・反转召唤・特殊召唤的情况下发动。掷1次硬币，根据掷出的正反，适用以下效果。\r\n●正面：从牌组将1张拥有掷硬币效果的魔法卡放置在自己场上。\r\n●反面：将双方魔法与陷阱区域的卡全部破坏。','\r',char(13)),'\n',char(10)),'手牌特殊召唤','','表','里','','','','','','','','','','','','');
INSERT INTO texts VALUES(39765115,'飞溅捕获','对手超量召唤成功时，将自己墓地的２只鱼族怪兽从游戏除外，选择该１只超量怪兽可以发动。获得所选择的超量怪兽的控制权。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39765958,'琰魔龙 暗红恶魔',replace(replace('协调＋协调以外的怪兽1只以上\r\n①：1回合1次，在自己的主要阶段1可以发动（发动此效果的回合中，自己的其他怪兽不可攻击）。将场上的其他表侧攻击表示怪兽全部破坏。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39767432,'索贝克的魔导士',replace(replace('效果怪兽2只\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡或此卡连接端的自己的怪兽给予对手战斗伤害时可以发动。依其数值恢复自己的LP。\r\n②：自己或对手的LP恢复的情况下可以发动（在伤害步骤也可以发动）。双方受到1000伤害。','\r',char(13)),'\n',char(10)),'','双方受到1000伤害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39774685,'魔菌','仅限装备植物族怪兽。令１只装备怪兽的攻击力和守备力上升３００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39778366,'急动联合',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：以自己除外状态的最多３只机械族・光属性的、通常怪兽或联合怪兽为对象可以发动。将该怪兽特殊召唤。\r\n②：从墓地将不是在此回合被送至墓地的此卡除外，以自己除外状态的１只机械族・光属性的、通常怪兽或联合怪兽为对象可以发动。将该怪兽放回手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39806198,'机关傀偶－磁力玩偶','①：对手场上存在有怪兽，且我方场上的怪兽仅是“机关傀偶”怪兽的场合，此卡可从手牌特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39817919,'灵魂鸟－忍鸦',replace(replace('此卡不可特殊召唤。\r\n①：１回合１次，此卡与对手怪兽进行战斗的伤害步骤开始时直至伤害计算前为止，从手牌将１只灵魂怪兽舍弃可以发动。此卡的攻击力・守备力直至战斗阶段结束时为止，分别上升相当于所舍弃怪兽的攻击力・守备力的数值。\r\n②：此卡召唤・反转的回合的结束阶段发动。将此卡放回手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39823987,'太阳龙 因蒂',replace(replace('“赤蚁 阿斯卡托尔”＋协调以外的怪兽１只以上\r\n①：此卡因战斗被破坏并被送至墓地的情况下发动。将破坏此卡的怪兽破坏，给予对手相当于其攻击力一半数值的伤害。\r\n②：场上的此卡被破坏的下个回合的准备阶段，以自己墓地的１只“月影龙 基利亚”为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'破坏','是否要发动「太阳龙 因蒂」的效果？','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39829561,'命运－英雄 故人小子','我方准备阶段时，此卡存在于墓地的场合，以攻击表示特殊召唤至对手场上。此卡因战斗被破坏的场合，不送入墓地而从游戏中被除外。此卡因卡牌效果从手牌或牌组被送入墓地的场合，不送入墓地而从游戏中被除外。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39838559,'方程式运动员赛道大奖赛','此卡名的③效果1回合仅可使用1次。①：只要此卡存在于场地区域，场上的“方程式运动员”怪兽的等级仅在战斗阶段期间上升2。②：1回合1次，自己的“方程式运动员”怪兽战斗破坏对手怪兽时可以发动。自己从牌组抽1张。③：场上表侧表示的此卡因效果被破坏的情况下可以发动。从牌组将1张“方程式运动员赛道大奖赛”以外的“方程式运动员”卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39848658,'白骨主宰者',replace(replace('①：自己的“白骨王”攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。\r\n②：1回合1次，以自己墓地的1只“白骨”或“白骨王”为对象可以发动。从牌组将1只“白骨”或记载有该卡名的怪兽送至墓地，将对象怪兽特殊召唤。此效果发动后，直至回合结束时为止自己仅可特殊召唤不死族怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39853199,'妖仙兽 阎魔巳裂',replace(replace('①：此卡与风属性以外的面朝上怪兽战斗的伤害步骤开始时可发动。将该怪兽破坏。\r\n②：此卡成功灵摆召唤时，可以１张对手场上的卡为目标发动。将该卡破坏。\r\n③：在特殊召唤了此卡的回合结束阶段发动。将此卡移回拥有者的手牌。','\r',char(13)),'\n',char(10)),'破坏怪兽','破坏1张卡','返回手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39880350,'圣天树之精灵',replace(replace('包含“圣天树”连接怪兽在内的植物族怪兽２只\r\n①：此卡不会成为攻击对象（自己场上仅存在适用此效果的怪兽的状态下，对手的攻击变为对自己的直接攻击）。\r\n②：１回合最多２次，自己因战斗・效果受到伤害的情况下可以发动。依其数值恢复自己的LP，从额外牌组将１只“圣蔓”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'回复并特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39881252,'兴妖迪亚贝尔',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：有魔法・陷阱卡为发动卡的效果被送至墓地的情况下可以发动。从手牌・牌组・额外牌组将1只幻想魔族・魔法师族怪兽送至墓地。\r\n②：在自己的主要阶段，从自己墓地将包含此卡在内的3张魔法・陷阱卡除外可以发动。从自己手牌・墓地将1只“迪亚贝尔”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'送墓效果','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39890958,'强化支援机械・重装铠甲',replace(replace('①：此卡召唤的情况下，以自己墓地的１只联合怪兽为对象可以发动。将该怪兽特殊召唤。\r\n②：１回合１次，可以发动以下的１个效果。\r\n●以自己场上的１只机械族怪兽为对象，将此卡视为装备魔法卡装备。装备怪兽将被战斗・效果破坏的情况下，作为代替将此卡破坏。\r\n●将装备状态的此卡特殊召唤。\r\n③：对手不可将装备怪兽作为效果的对象。','\r',char(13)),'\n',char(10)),'变成装备','装备的此卡特殊召唤','墓地同盟怪兽特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39892082,'气球蜥蜴','每次自己的准备阶段时，放１个计数物至此卡。此卡被破坏时，给予破坏此卡的卡片的控制者计数物数量×４００点伤害。','放置计数物','伤害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39897277,'精灵之光','仅限装备光属性怪兽。令装备怪兽的攻击力上升４００点，守备力下降２００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39900763,'异次元的邂逅','①：双方各存在有１只或以上被除外的我方怪兽的场合可发动。双方玩家各挑选１只被除外的我方怪兽并以里侧守备表示特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39905966,'咒仪纹章鱼','此卡召唤、反转召唤、特殊召唤成功时可发动。从我方墓地将１只冠有“咒仪”之名的仪式怪兽或１张冠有“咒仪”之名的仪式魔法卡加入手牌。','加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39910367,'魔法都市 恩底弥翁',replace(replace('①：只要此卡存在于场地区域，每当自己或对手发动魔法卡，就在此卡上放1个魔力计数物。\r\n②：放有魔力计数物的卡被破坏的情况下，依该卡原先放有的魔力计数物数量，在此卡上放魔力计数物。\r\n③：1回合1次，自己为发动卡的效果而要去除自己场上的魔力计数物的情况下，作为代替可从此卡上去除。\r\n④：此卡将被破坏的情况下，作为代替可去除此卡的1个魔力计数物。','\r',char(13)),'\n',char(10)),'发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39913299,'真实之名','此卡名的卡1回合仅可发动1张。①：宣言1个卡名可以发动。翻开自己牌组最上面的卡，是宣言的卡的情况下，将该卡加入手牌。进而可从牌组将1只神属性怪兽加入手牌或特殊召唤。不是的情况下，将翻开的卡送至墓地。','是否把神属性怪兽加入手牌或特殊召唤？','请选择神属性怪兽','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39915560,'凶饿猛毒捕食结合龙',replace(replace('暗属性融合怪兽＋融合怪兽\r\n此卡名在规则上也视为“捕食植物”卡。此卡名的②效果１回合仅可使用１次。①：１回合１次，魔法・陷阱・怪兽的效果发动时可以发动。解放自己或对手场上１只放有捕食计数物的怪兽，将该发动无效。②：融合召唤的此卡因对手被送至墓地的情况下，以自己墓地的１只暗属性怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39931513,'天杯龙 白板龙',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组挑选１张“灿幻”魔法・陷阱卡，加入手牌或放置在自己场上。\r\n②：只要此卡存在于怪兽区域，因自己的龙族・炎属性怪兽的战斗对自己造成的战斗伤害变为０。\r\n③：１回合１次，在自己・对手的战斗阶段可以发动。将包含此卡在内的自己场上的怪兽作为素材进行同步召唤。','\r',char(13)),'\n',char(10)),'检索','同步召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39943352,'液状巨人 大太胀流',replace(replace('←3 【灵摆】 3→\r\n此卡名的灵摆效果１回合仅可使用１次。\n①：以自己场上的１只超量怪兽为对象可以发动。将此卡作为该怪兽的超量素材。\r\n【怪兽效果】\r\n等级４怪兽×２\n在可灵摆召唤等级４的情况下，额外牌组表侧的此卡可以灵摆召唤。\n此卡名的①②怪兽效果１回合仅可各使用１次。\n①：去除此卡的１个超量素材可以发动。将此卡放在自己的灵摆区域。然后，可从自己的墓地将１只灵摆怪兽以表侧加入额外牌组。\n②：怪兽区域的此卡因战斗・效果被破坏的情况下可以发动。将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'','','','是否从墓地选1只灵摆怪兽加入额外牌组？','','','','','','','','','','','','');
INSERT INTO texts VALUES(39956951,'封魔一闪','可在对手场上的怪兽区域全都有怪兽存在时发动此卡。破坏对手场上的所有怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39964797,'水晶机巧－石英达姆',replace(replace('协调＋协调以外的怪兽１只以上\r\n①：在对手的主要阶段及战斗阶段可以发动（在同一连锁上最多１次）。将包含此卡在内的自己场上的怪兽作为素材进行同步召唤。\r\n②：同步召唤的此卡因战斗・效果被破坏的情况下，以自己墓地同步怪兽以外的１只“水晶机巧”怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'加速同步','墓地特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39967326,'过早的复活','选择自己的墓地的１只名字带有“地缚神”怪兽可以发动。将选择的怪兽特殊召唤。此回合，以此效果特殊召唤的怪兽不可攻击宣言。此外，以此效果特殊召唤的怪兽的战斗对对手造成的战斗伤害变为０。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39972129,'编号64 古狸三太夫',replace(replace('兽族等级２怪兽×２\r\n①：只要自己场上有其他兽族怪兽存在，此卡不会因战斗・效果被破坏。②：１回合１次，去除此卡的１个超量素材可以发动。将１只“影武者狸衍生物”（兽族・地・星１・攻？／守０）特殊召唤至自己场上。此衍生物的攻击力变为与场上怪兽的最高攻击力相同。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39972130,'影武者狸衍生物','由“编号64 古狸三太夫”的效果特殊召唤而来。此衍生物的攻击力将与特殊召唤此衍生物时存在于场上的攻击力最高的怪兽相同。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39973386,'表里一体',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：解放自己场上的１只光・暗属性怪兽可以发动。从手牌・额外牌组将原本种族・等级与该怪兽相同，原本属性不同的１只光・暗属性怪兽特殊召唤。\r\n②：在自己的主要阶段将墓地的此卡除外，以自己墓地的光・暗属性怪兽各１只为对象可以发动。将该２只怪兽放回牌组。然后，自己抽１张。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39978267,'电子怪',replace(replace('此卡召唤、反转召唤、特殊召唤成功时，从以下效果中选择１个发动：\r\n●选择１张装备在场上１只怪兽的装备卡并破坏。\r\n●选择１张装备在场上１只怪兽的装备卡并将其装备在此卡。','\r',char(13)),'\n',char(10)),'选择效果发动','装备卡破坏','装备卡装备在此卡身上','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39980304,'连锁素材','此卡的发动回合里自己融合召唤的情况下，可以将由融合怪兽卡决定的融合素材怪兽从自己的手牌・牌组・场上・墓地中挑选出从游戏中除外，用这些作为融合素材。使用此效果融合召唤的怪兽在结束阶段时被破坏。发动此卡的回合中，自己的怪兽不可攻击。','是否使用「连锁素材」的效果？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39984786,'产卵短吻鳄','释放爬虫类族怪兽且此卡上级召唤回合的结束阶段时，从墓地选择１只以此卡的上级召唤为目的而释放的怪兽，特殊召唤至我方场上。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39987164,'大日神械Disigma',replace(replace('等级４怪兽×３\r\n１回合１次，可移除此卡的１个超量素材并发动。选择对手场上１只攻击表示的效果怪兽，并视为装备卡装备此卡。此卡与和以此效果装备的怪兽相同属性之怪兽进行战斗的伤害步骤开始时，破坏该怪兽。','\r',char(13)),'\n',char(10)),'装备','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39987731,'威胁的人造人－念力震慑者',replace(replace('此卡名的效果①②在1个回合中仅可各使用1次。\r\n①：自己或对手的场上、墓地有陷阱卡存在时可以发动。从手牌中特殊召唤此卡。通过此效果特殊召唤的此卡的等级变为6，直至回合结束时为止。\r\n②：在自己或对手的主要阶段，解放此卡后可以发动。从自己的手牌、墓地选择1只“人造人-念力震慑者”特殊召唤。然后，可以破坏对手场上所有的陷阱卡（该卡放置于场上时，翻开确认）。','\r',char(13)),'\n',char(10)),'','','是否把对手场上的陷阱卡全部破坏？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39996157,'机械天使的仪式','“电子天使”仪式怪兽降临所必需。①：为使合计等级为仪式召唤的怪兽以上，解放自己手牌・场上的怪兽，从手牌将１只“电子天使”仪式怪兽仪式召唤。②：自己场上的光属性怪兽将被战斗・效果破坏的情况下，可将墓地的此卡除外作为代替。','是否使用「机械天使的仪式」的效果代替破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(39998992,'超机怪虫・突触本性',replace(replace('地属性怪兽2只\r\n①：此卡连接端的“机怪虫”怪兽不会因战斗被破坏，攻击力・守备力上升300，1次战斗阶段中最多可攻击怪兽2次。②：表侧表示的此卡因对手的效果从场上离开的情况下，或因战斗被破坏的情况下，以自己墓地的2只“机怪虫”怪兽为对象可以发动（同名卡最多1张）。将该怪兽以里侧守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40003819,'转临之守护龙','此卡名的卡1回合仅可发动1张。①：从自己场上・墓地，将由融合怪兽卡决定的融合素材怪兽除外，从额外牌组将1只该融合怪兽融合召唤。在此之际，融合素材怪兽必须全部是连接怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40005099,'不知火流 转生之阵',replace(replace('此卡名的卡１回合仅可发动１张。①：１回合１次，自己场上不存在怪兽的情况下，将１张手牌送至墓地，可从以下效果中选择１个发动。\r\n●以自己墓地１只守备力０的不死族怪兽为对象可以发动。将该怪兽特殊召唤。\r\n●以１只自己被除外的守备力０的不死族怪兽为对象可以发动。将该怪兽放回墓地。','\r',char(13)),'\n',char(10)),'特殊召唤','回到墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40012727,'爆裂横扫','①：自己场上存在“／爆裂”怪兽的情况下可以发动。将场上的表侧表示怪兽全部破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40028305,'超重武者装魂 光爪','此卡名的②效果１回合仅可使用１次。①：在自己的主要阶段，以自己场上的１只“超重武者”怪兽为对象可以发动。从自己的手牌・场上，将此怪兽视为攻击力・守备力上升５００的装备卡，装备于该自己的怪兽。装备怪兽不会因战斗被破坏。②：此卡是以此卡的效果被装备中的情况下可以发动。将被装备的此卡特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40041559,'指环精灵 吉尼娅',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡存在于手牌的情况下，以场上的1只表侧表示怪兽为对象可以发动。将此卡特殊召唤。对象表侧表示怪兽变为魔法师族，在此回合仅1次不会因效果被破坏。此回合，自己从额外牌组仅可特殊召唤魔法师族怪兽。\r\n②：此卡为发动魔法师族怪兽的效果，而被解放的情况下或被除外的情况下可以发动。将此卡加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','回到手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40044918,'元素－英雄 大气人',replace(replace('①：此卡召唤・特殊召唤时，可从以下效果中选择1个发动。\r\n●以自己场上的其他“－英雄”怪兽数量为上限，将场上的魔法・陷阱卡破坏。\r\n●从牌组将1只“－英雄”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'选择一个效果发动','魔法·陷阱卡破坏','「－英雄」怪兽加入手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40044919,'元素－英雄 大气人',replace(replace('①：此卡召唤・特殊召唤时，可从以下效果中选择1个发动。\r\n●以自己场上的其他“－英雄”怪兽数量为上限，将场上的魔法・陷阱卡破坏。\r\n●从牌组将1只“－英雄”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'选择一个效果发动','魔法·陷阱卡破坏','「－英雄」怪兽加入手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40048324,'密术炼贤','①：此卡作为同步素材被送至墓地的情况下可以发动。从牌组将1张“爆裂模式”加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40061558,'隐藏的机壳内核',replace(replace('此卡不可特殊召唤，仅释放我方场上３只“机壳”怪兽的场合，可进行通常召唤。\r\n①：通常召唤而来的此卡不受魔法、陷阱卡的效果影响，也不受原本等级或阶级低于此卡等级的怪兽所发动之效果的影响。\r\n②：１回合１次，可以对手场上的１只怪兽为对象发动。直至结束阶段，获得该怪兽的控制权。','\r',char(13)),'\n',char(10)),'把3只「机壳」怪兽解放','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40080312,'元素－英雄 星云新宇侠',replace(replace('“元素－英雄 新宇侠”＋“新空间人 大地鼹鼠”＋“新空间人 漆黑猎豹”\r\n仅在将自己场上的上述卡放回牌组的情况下，可从额外牌组特殊召唤。①：此卡从额外牌组特殊召唤成功的情况下发动。依对手场上卡的数量，自己从牌组抽牌。然后挑选场上的１张表侧表示卡，将其效果直至回合结束时为止无效。②：在结束阶段发动。将此卡放回持有者的额外牌组，将场上的卡全部以里侧表示除外。','\r',char(13)),'\n',char(10)),'','请选择要无效的卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40089744,'混沌之场','此卡名的卡１回合仅可发动１张。①：作为此卡发动时的效果处理，从牌组将１只“混沌士兵”仪式怪兽或“暗黑骑士盖亚”怪兽加入手牌。②：只要此卡存在于场地区域，怪兽每次从双方的手牌・场上被送至墓地，每有１只便在此卡上放１个魔力计数物（最多６个）。③：１回合１次，去除此卡的３个魔力计数物可以发动。自己从牌组将１张仪式魔法卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40101111,'究极超能者',replace(replace('念动力族同步怪兽＋念动力族怪兽\r\n此卡从额外牌组仅可通过融合召唤来特殊召唤。\r\n①：此卡只要存在于怪兽区域，不会因效果被破坏。\r\n②：此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。\r\n③：此卡战斗破坏怪兽并将其送至墓地的情况下发动。依该怪兽原本攻击力的数值恢复自己的LP。','\r',char(13)),'\n',char(10)),'回复破坏的怪兽的攻击力的数值','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40110009,'龙女仆的更衣',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：将自己手牌・场上的怪兽作为融合素材，将1只龙族融合怪兽融合召唤。\r\n②：此卡存在于墓地的情况下，以自己场上的1只“龙女仆”怪兽为对象可以发动。将此卡加入手牌，将该怪兽放回手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40133511,'噬魂者 巴兹','①：1回合1次，从自己墓地将最多3只怪兽除外可以发动。此卡的攻击力直至对手回合结束时为止，上升相当于除外数量×300的数值。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40139997,'红莲蔷薇龙',replace(replace('协调＋协调以外的怪兽1只以上\r\n①：此卡同步召唤的情况下可以发动。将双方墓地的卡全部除外。此卡以“黑蔷薇龙”或植物族同步怪兽作为素材同步召唤的情况下，进而可将场上的其他卡全部破坏。\r\n②：对手发动破坏卡的效果时，解放此卡可以发动。将该发动无效。然后，可从自己额外牌组・墓地将1只“黑蔷薇龙”特殊召唤。','\r',char(13)),'\n',char(10)),'双方墓地的卡全部除外','发动无效','是否将此卡以外的双方场上的卡全部破坏？','是否把「黑蔷薇龙」特殊召唤？','','','','','','','','','','','','');
INSERT INTO texts VALUES(40140448,'战华之仲－孙谋',replace(replace('此卡名的②③效果1回合仅可各使用1次。\r\n①：只要自己场上存在其他“战华”怪兽，对手怪兽不可将此卡选择为攻击对象。\r\n②：从自己手牌・场上将1张卡送至墓地可以发动。从牌组将“战华之仲－孙谋”以外的1只“战华”怪兽加入手牌。\r\n③：自己的其他“战华”怪兽发动效果的情况下，以对手场上的1只怪兽为对象可以发动。将该怪兽放回手牌。','\r',char(13)),'\n',char(10)),'','回到手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40143123,'星圣 室女斯皮卡','①：此卡召唤时可以发动。从手牌将1只等级5的“星圣”怪兽以守备表示特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40155014,'百夫骑士魔防阵',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：以场上的１张表侧表示的怪兽卡为对象可以发动。将该卡除外。在下个回合的准备阶段，将以此效果除外的怪兽特殊召唤至持有者的场上。\r\n②：将墓地的此卡除外，以自己墓地的１只“百夫骑”同步怪兽为对象可以发动。将该怪兽特殊召唤。以此效果特殊召唤的怪兽的攻击力下降１５００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40155554,'A・心灵','为了强化A・O・J的思考回路而开发出的高性能装置。内嵌有从异虫星云飞来的陨石中提取的物质，具有高度的调和能力。其未知力量的相关谜团至今尚未解开。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40159926,'镜共鸣者','此卡名的①效果1回合仅可使用1次。①：此卡存在于手牌・墓地，从额外牌组被特殊召唤的怪兽仅存在于对手场上的情况下可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡离开场上的情况下，将其除外。②：1回合1次，以对手场上的1只表侧表示怪兽为对象可以发动。此回合在要将此卡作为同步素材的情况下，视为与对象怪兽原本等级相同的等级。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40160226,'机海龙蛇颈龙','我方场上存在有海龙族怪兽的场合，此卡可无须释放召唤。１回合１次，可释放１只我方场上的水属性怪兽并发动。选择对手场上的１张表侧表示卡牌并破坏。','不进行解放作召唤','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40164421,'光道少女 密涅瓦',replace(replace('①：此卡召唤时可以发动。从牌组将１只等级为自己墓地的“光道”怪兽种类数量以下的龙族・光属性怪兽加入手牌。\r\n②：此卡被从手牌・牌组送至墓地的情况下发动。从自己的牌组上面将１张卡送至墓地。\r\n③：在自己的结束阶段发动。从自己的牌组上面将２张卡送至墓地。','\r',char(13)),'\n',char(10)),'检索','送墓','送墓','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40172183,'狭窄的道路','双方场上的怪兽都在２只以下的情况下可以发动此卡。双方玩家自身场上有２只以上怪兽存在的情况下，不可召唤手牌的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40173854,'水陆两用战斗艇','“陆战型 战斗舰”＋“守海战士”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40177746,'异娃',replace(replace('此卡名的效果１回合仅可使用１次。\r\n①：此卡被送至墓地的情况下，将自己场上・墓地此卡以外的最多２只天使族・光属性怪兽除外可以发动。依所除外的数量，从牌组将“异娃”以外的等级２以下的天使族・光属性怪兽加入手牌（同名卡最多１张）。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40189917,'炎狱死亡枪手','此卡不可特殊召唤。仅限解放自己场上的１只名字带有“炎狱”的怪兽的情况下可以召唤。１回合１次，将自己墓地１只守备力２００的怪兽从游戏中除外可以发动。给予对手LP被除外怪兽攻击力数值的伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40196604,'暗影','以水晶发出的强烈光芒进行攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40200834,'沉睡的狮子','平时一直在沉睡的猛兽。一旦苏醒就对它无计可施。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40204620,'巨石异物・升格','此卡名的①效果1回合仅可使用1次。①：以自己场上1只等级4以下的怪兽为对象可以发动。该怪兽的等级直至回合结束时为止改成原本等级的两倍。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40213117,'魔导弓士 拉穆尔','１回合１次，可向对手展示手牌的１张冠有“魔导书”之名的魔法卡并发动。从手牌特殊召唤１只等级４或以下的魔法师族怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40216089,'白金小工具',replace(replace('机械族怪兽２只\r\n此卡名的①②效果１回合仅可各使用１次。\r\n此卡在被连接召唤的回合不可作为连接素材。\r\n①：在自己的主要阶段可以发动。从手牌将１只等级４以下的机械族怪兽特殊召唤至此卡连接端的自己场上。\r\n②：此卡因战斗・效果被破坏的情况下可以发动。从牌组将１只等级４的“小工具”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40217358,'蓝尘小妖','此卡不可进行释放，也不可作为融合、同步、超量召唤的素材。场上的此卡被破坏时，随机挑选１张此卡控制者的手牌，并直至下一个回合的准备阶段时，以里侧表示从游戏中除外。我方场上仅可有１只“蓝尘小妖”以表侧表示存在。','除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40221691,'幻惑的魔术士',replace(replace('①：此卡与怪兽进行战斗的情况下，该２只不会因该战斗被破坏。\r\n②：此卡与对手怪兽进行战斗的伤害步骤结束时可以发动。获得该对手怪兽的控制权。\r\n③：１回合１次，此卡以外的怪兽攻击的伤害步骤开始时可以发动。将场上的１张卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40225398,'双剑破坏者','此卡攻击了守备表示怪兽的场合，可再连续发动１次攻击。此卡攻击了守备表示怪兽时，若其攻击力超过守备力，给予对手生命相当于该差值的战斗伤害。','是否使用「双剑破坏者」的效果？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40227329,'GO－DDD 神零王 零神零怒',replace(replace('←0 【灵摆】 0→\r\n此卡名的①②灵摆效果１回合仅可各使用１次。\n①：此卡存在于灵摆区域，自己将受到效果伤害的情况下，该伤害变为０。\n②：只要此卡存在于灵摆区域，自己召唤等级５以上的“DD”怪兽的情况下，可免除所必须的解放。\r\n【怪兽效果】\r\n①：解放自己场上１只其他的怪兽可以发动。从以下效果中挑选１个，直至回合结束时为止适用。\n●此卡可直接攻击。\n●对手不可发动魔法与陷阱区域的卡的效果。\n●对手不可发动手牌・墓地的卡的效果。\n②：对手的LP为４０００以下的情况下，此卡的攻击宣言时可以发动。此卡的攻击力直至回合结束时为止，上升相当于对手LP的数值。\n③：此卡不会因战斗被破坏，因此卡的战斗对自己造成的战斗伤害变为０。','\r',char(13)),'\n',char(10)),'此卡可以直接攻击','对手不可把魔法与陷阱区域的卡的效果发动','对手不可把手牌·墓地的卡的效果发动','','使用「GO－DDD 神零王 零神零怒」的效果不用解放','','','','','','','','','','','');
INSERT INTO texts VALUES(40230018,'魔导书库 娥眉月','我方墓地不存在冠有“魔导书”之名的魔法卡的场合可发动。从牌组挑选３种冠有“魔导书”之名的魔法卡并向对手展示，对手从中随机挑选１张。将对手挑选的１张卡牌加我方入手牌，剩下的卡牌返回至牌组。“魔导书库 娥眉月”１回合只可发动１张，发动此卡的回合，我方不可发动除冠有“魔导书”之名以外的魔法卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40235813,'时间黑魔术师',replace(replace('①：可从以下效果中选择1个发动（此卡名的以下效果1回合仅可各选择1次）。\r\n●从牌组将除“时间黑魔术师”以外的、1张记载有“时间黑魔术师”卡名的卡加入手牌。在此回合的结束阶段，从自己墓地将1张“时间黑魔术师”加入手牌。\r\n●掷1次硬币，猜正反。猜对的情况下，将对手场上的怪兽全部破坏，给予对手相当于其原本攻击力的合计数值的一半的伤害。猜错的情况下，将自己场上的怪兽全部破坏。','\r',char(13)),'\n',char(10)),'发动','检索','投掷硬币','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40237839,'羽翼库里波・萨巴希尔 LV10',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：向对手出示手牌的此卡，支付一半LP可以发动。从牌组将1张“融合”魔法卡或“结合”魔法卡加入手牌，将此卡放回牌组。此回合，自己从额外牌组仅可特殊召唤“－英雄”怪兽。\r\n②：在对手回合中，自己的LP在1000以下的情况下可以发动。从手牌将此卡特殊召唤。然后，可给予对手相当于对手场上的怪兽中最高攻击力数值的伤害。','\r',char(13)),'\n',char(10)),'检索效果','特殊召唤','是否给与伤害？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40237840,'羽翼库里波・萨巴希尔 LV10',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：向对手出示手牌的此卡，支付一半LP可以发动。从牌组将1张“融合”魔法卡或“结合”魔法卡加入手牌，将此卡放回牌组。此回合，自己从额外牌组仅可特殊召唤“－英雄”怪兽。\r\n②：在对手回合中，自己的LP在1000以下的情况下可以发动。从手牌将此卡特殊召唤。然后，可给予对手相当于对手场上的怪兽中最高攻击力数值的伤害。','\r',char(13)),'\n',char(10)),'检索效果','特殊召唤','是否给与伤害？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40240595,'进化之茧','此卡可被视为装备卡从手牌装备于我方场上的１只“小毛虫”。以此效果装备此卡的“小毛虫”的原本攻击力、守备力将适用“进化之茧”的数值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40251688,'焰圣骑士导－罗兰',replace(replace('协调＋１只以上协调以外的怪兽\r\n此卡名的①②效果１回合仅可各使用１次。①：此卡同步召唤成功的情况下可以发动。在此回合的结束阶段，从牌组将１张装备魔法卡送至墓地。然后，从牌组将１只战士族怪兽加入手牌。②：此卡存在于墓地的情况下，在自己・对手的主要阶段，以自己场上的１只战士族怪兽为对象可以发动。将此卡视为攻击力上升５００的装备卡，装备于该自己的怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40252269,'魔术师的再演',replace(replace('①：只要此卡在场上以表侧表示存在仅１次，以自己墓地的１只等级３以下的魔法师族怪兽为对象可以发动。将该怪兽特殊召唤。\r\n②：此卡被送至墓地的情况下可以发动。从牌组将“魔术师的再演”以外的１张“魔术师”永续魔法卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40253382,'TG－SX1','仅对手怪兽因我方场上存在的冠有“T.G.”之名怪兽的战斗而被破坏并送入墓地时可发动。选择我方墓地１只冠有“T.G.”之名的同步怪兽并特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40267580,'捕脑魔','反转：选择对手场上上的１只表侧表示怪兽发动。将此卡视为装备卡，装备于选择的对手怪兽。获得装备此卡的怪兽的控制权。每次对手的准备阶段，对手恢复５００LP。','装备获得控制权','LP回复','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40275470,'人造人－念力能量震慑者',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：此卡只要存在于场上・墓地，卡名视为“人造人－念力震慑者”。\r\n②：此卡召唤・特殊召唤的情况下可以发动。将对手场上的陷阱卡全部破坏（里侧表示卡翻开确认）。然后，此卡的攻击力上升所破坏数量×300的数值。\r\n③：只要自己场上或墓地存在除此卡以外的、记载有“时间黑魔术师”卡名的怪兽，对手不可发动陷阱卡的效果。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40279770,'黑羽的引导','我方因卡牌效果而受到伤害时可发动。从手牌特殊召唤１只等级４或以下冠有“黑羽”之名的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40318957,'娱乐伙伴 骷髅杂技小丑',replace(replace('←8 【灵摆】 8→\r\n①：自己仅可灵摆召唤“娱乐伙伴”怪兽、“魔术师”灵摆怪兽、“异色眼”怪兽。此效果不会被无效化。\r\n【怪兽效果】\r\n①：此卡召唤成功时可以发动。从牌组“娱乐伙伴 骷髅杂技小丑”以外的“娱乐伙伴”怪兽、“魔术师”灵摆怪兽、“异色眼”怪兽中，挑选任意１只加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40320754,'毒根王','此卡因战斗被破坏并送入墓地时，从我方墓地选择１只除“毒根王”以外的植物族怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40343749,'屋尘小妖','①：场上表侧表示的此卡因对手的效果被破坏并被送至墓地时，或伤害步骤开始时曾为表侧表示的此卡因与对手怪兽的战斗被破坏并被送至墓地时，可以发动。从手牌・牌组挑选任意数量的“尘小妖”怪兽，依相同数量分别特殊召唤至双方场上。','特殊召唤','请选择在自己场上特殊召唤的怪兽','请选择在对手场上特殊召唤的怪兽','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40348946,'高能同步士','此卡被使用于龙族怪兽的同步召唤并被送入墓地的场合，以此卡作为同步素材的同步怪兽攻击力上升８００点，并在结束阶段时从游戏中除外。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40350910,'胆怯之风','不可破坏场上被盖牌的魔法・陷阱卡，直到下次对手回合的结束阶段。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40352445,'凶教导之白骑士','以“凶教导之福音”降临。此卡名的②效果１回合仅可使用１次。①：只要此卡存在于怪兽区域，自己不可从额外牌组特殊召唤怪兽。②：对手发动魔法・陷阱・怪兽的效果的情况下可以发动。从自己的额外牌组将１只怪兽送至墓地，确认对手的额外牌组，挑选其中１只怪兽送至墓地。此卡的攻击力直至回合结束时为止，上升相当于送至墓地的怪兽攻击力的合计数值一半的数值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40364916,'不知火流 传承之阵',replace(replace('①：此卡只要存在于魔法与陷阱区域，卡名视为“不知火流 转生之阵”。\r\n②：１回合１次，可从以下效果中选择１个发动。\r\n●从自己的墓地将１只不死族怪兽除外可以发动。此回合，自己的不死族怪兽的召唤・特殊召唤不会被无效化。\r\n●以自己场上的１只不死族怪兽为对象可以发动。将该怪兽除外。然后，可从牌组将守备力０的１只不死族怪兽送至墓地。','\r',char(13)),'\n',char(10)),'召唤不会被无效化','场上怪兽除外','是否把怪兽送至墓地？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40366667,'灵主王之波动',replace(replace('此卡名的卡1回合仅可发动1张。\r\n对手场上存在卡的情况下，此卡也可从手牌发动。\r\n①：包含将怪兽特殊召唤的效果在内的、魔法・陷阱・怪兽的效果发动时可以发动。将该效果无效。自己墓地存在陷阱卡的情况下，进而将该无效的卡破坏。从手牌发动此卡的情况下，发动后，此决斗中自己不可发动光・地・风属性怪兽的效果。','\r',char(13)),'\n',char(10)),'效果无效','适用「灵主王之波动」的效果来发动','「灵主王之波动」效果适用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40366668,'灵主王之波动',replace(replace('此卡名的卡1回合仅可发动1张。\r\n对手场上存在卡的情况下，此卡也可从手牌发动。\r\n①：包含将怪兽特殊召唤的效果在内的、魔法・陷阱・怪兽的效果发动时可以发动。将该效果无效。自己墓地存在陷阱卡的情况下，进而将该无效的卡破坏。从手牌发动此卡的情况下，发动后，此决斗中自己不可发动光・地・风属性怪兽的效果。','\r',char(13)),'\n',char(10)),'效果无效','适用「灵主王之波动」的效果来发动','「灵主王之波动」效果适用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40371092,'白夜的骑士盖亚',replace(replace('“白夜的骑士盖亚”的以下效果１回合只可各使用１次。\r\n●可释放我方场上１只除此卡以外的光属性怪兽并发动。从牌组将１只战士族、暗属性、等级４的怪兽加入手牌，之后挑选１张手牌并送入墓地。\r\n●可从我方墓地将１只暗属性怪兽除外，并选择我方场上的１只怪兽发动。直至对手回合结束时，被选择怪兽的攻击力下降５００点。','\r',char(13)),'\n',char(10)),'牌组检索','攻击力下降','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40374923,'猛犸的墓地','守护着伙伴墓地的猛犸，对任何胆敢践踏墓地的盗墓者会毫不客气地进行攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40380686,'泥龙宝宝',replace(replace('①：要以自己场上的此卡作为同步素材的情况下，可将此卡视为协调以外的怪兽。\r\n②：此卡作为同步素材被送至墓地的情况下，宣言1个种族或属性，以自己场上的1只同步怪兽为对象可以发动。该怪兽直至回合结束时为止变为宣言的种族或属性。','\r',char(13)),'\n',char(10)),'改变种族','改变属性','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40383551,'大寒气','此回合，我方不可发动魔法、陷阱卡的效果，也不可盖牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40384720,'音速射手','对手的魔法与陷阱区域不存在卡牌的场合，此卡可直接攻击对手玩家。此时，给予对手玩家的战斗伤害为此卡的原本攻击力。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40387124,'深渊绽放的花','默默生长在黑暗的深渊里，是平常很难见到的花。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40390147,'辉光皇帝盖勒克希翁',replace(replace('等级４“光子”怪兽×２\r\n①：１回合１次，去除此卡的最多２个超量素材可以发动。依去除的数量，适用以下效果。\r\n●１个：从手牌将１只“银河眼光子龙”特殊召唤。\r\n●２个：从牌组将１只“银河眼光子龙”特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','从手牌把1只「银河眼光子龙」特殊召唤','从牌组把1只「银河眼光子龙」特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40391316,'扰乱怪骑士',replace(replace('冠有“扰乱怪”之名的怪兽×２\r\n只要此卡以表侧表示存在于场上，最多能指定２处未使用的对手怪兽区，使其变成不能使用。','\r',char(13)),'\n',char(10)),'是否还要选择一个区域？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40392714,'方界帝疾风・盖伊鲁',replace(replace('此卡不可通常召唤。\r\n我方场上的１只“方界”怪兽送入墓地的场合可特殊召唤。\r\n①：以此方法特殊召唤的此卡攻击力上升８００。\r\n②：此卡从手牌特殊召唤成功的场合发动。给予对手８００伤害。\r\n③：此卡战斗的伤害步骤结束时，可以我方墓地最多２只“方界胤维贾姆”为对象发动。将此卡送入墓地，并特殊召唤对象怪兽。之后，可从牌组将１只“方界帝伏尔甘・德拉耆尼”加入手牌。','\r',char(13)),'\n',char(10)),'是否把1只「方界帝伏尔甘・德拉耆尼」加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40398073,'龙女仆・护育龙女',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下，以除“龙女仆・护育龙女”以外的、自己墓地的1只等级4以下的“龙女仆”怪兽为对象可以发动。将该怪兽特殊召唤。\r\n②：在自己・对手的战斗阶段开始时可以发动。将此卡放回手牌，从自己手牌・墓地将1只等级7的“龙女仆”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40410110,'炼金生物 人工生命体','１回合１次，在我方主要阶段时可发动。变更此卡的属性。','改变属性','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40418351,'铠黑龙－电子暗黑龙',replace(replace('“电子暗黑角”＋“电子暗黑刃”＋“电子暗黑骨”\r\n此卡仅可以融合召唤方式特殊召唤。\r\n①：此卡特殊召唤的情况下，以自己墓地的1只龙族怪兽为对象发动。将该龙族怪兽视为装备魔法卡装备于此卡。\r\n②：此卡的攻击力上升以此卡的效果装备的怪兽的攻击力数值，以及自己墓地的怪兽数量×100的数值。\r\n③：此卡将被战斗破坏的情况下，作为代替将装备的该怪兽破坏。','\r',char(13)),'\n',char(10)),'装备','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40424929,'烈华炮舰 抚子',replace(replace('等级３怪兽×３\r\n移除此卡的１个超量素材可以发动。给予对手LP对手的手牌数量×２００点伤害。“烈华炮舰 抚子”的效果１回合仅可使用１次。','\r',char(13)),'\n',char(10)),'伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40428851,'战华之德－刘玄',replace(replace('此卡名的②③效果1回合仅可各使用1次。\r\n①：只要自己场上存在其他“战华”怪兽，对手怪兽不可将此卡选择为攻击对象。\r\n②：对手场上的怪兽数量多于自己场上的怪兽的情况下，从自己手牌・场上将1张卡送至墓地可以发动。从牌组将“战华之德－刘玄”以外的1只“战华”怪兽特殊召唤。\r\n③：自己的其他“战华”怪兽进行战斗的攻击宣言时可以发动。自己抽1张。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40441990,'星遗物－星键－','此卡名的①②效果1回合仅可各使用1次。①：从手牌将1张“星遗物”卡舍弃可以发动。此回合，自己在通常召唤以外仅可追加1次，在自己的主要阶段上级召唤。②：此卡与对手连接怪兽进行战斗的伤害步骤开始时可以发动。将该怪兽放回持有者的额外牌组。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40450317,'同胞羁绊','发动此卡的回合中，自己无法进行战斗阶段。①：支付2000LP，以自己场上的1只等级4以下怪兽为对象可以发动。从牌组将2只与该怪兽种族・属性・等级相同而卡名不同的怪兽特殊召唤（同名卡最多1张）。此卡发动后，直至回合结束时为止自己不可特殊召唤怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40453765,'野蛮人２号','①：自己场上每有１只“野蛮人１号”，此卡的攻击力上升５００。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40456412,'霸王龙之奇迹',replace(replace('①：自己场上存在“霸王龙扎克”的情况下，可从以下效果中选择１个发动（此卡名的以下效果１回合仅可各选择１次）。\r\n●破坏自己场上的１张“霸王龙扎克”，从牌组・额外牌组将１只“异色眼”灵摆怪兽或光属性的“霸王龙扎克”无视召唤条件特殊召唤。\r\n●将自己的额外牌组的１只表侧的灵摆怪兽放在自己的灵摆区域。\r\n●从牌组将１张速攻魔法卡放置在自己场上。','\r',char(13)),'\n',char(10)),'','破坏并特殊召唤','从额外牌组放置灵摆怪兽','从牌组放置速攻魔法卡','','','','','','','','','','','','');
INSERT INTO texts VALUES(40460013,'炎魔的触媒',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：将手牌的此卡与手牌的１只恶魔族怪兽出示给对手可以发动。将该２只中的１只特殊召唤，另１只舍弃。\r\n②：此卡存在于墓地的状态下，有怪兽因自己的恶魔族怪兽的战斗被破坏时可以发动。将此卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40465719,'凡人的施舍','从牌组抽取２张卡牌，然后将手牌中的１只通常怪兽从游戏中除外。手牌中没有通常怪兽的场合，将所有手牌送入墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40473581,'雷帝神','此卡不可特殊召唤。召唤、反转回合的结束阶段时返回至持有者的手牌。此卡给予对手生命的战斗伤害减半。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40493210,'魔键锭－施－',replace(replace('①：解放自己场上衍生物以外的１只通常怪兽或“魔键”怪兽，为使等级合计变为８以下，以自己墓地的最多２只通常怪兽或“魔键”怪兽为对象可以发动。以守备表示形式将该怪兽特殊召唤。然后，可从以下效果中挑选１个适用。\r\n●以自己场上的怪兽作为同步素材，将１只“魔键”同步怪兽同步召唤。\r\n●以自己场上的怪兽作为超量素材，将１只“魔键”超量怪兽超量召唤。','\r',char(13)),'\n',char(10)),'同步召唤','超量召唤','什么都不做','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40502912,'幻奏音女 阿丽娅','①：只要特殊召唤的此卡存在于怪兽区域，自己场上的“幻奏”怪兽不会因战斗被破坏，双方不可将其作为效果的对象。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40509732,'鬼动武者',replace(replace('协调+1只以上协调以外的怪兽\r\n①：此卡与对手怪兽进行战斗的情况下，直至伤害步骤结束时为止对手不可发动魔法・陷阱・怪兽的效果，仅在战斗阶段期间该对手怪兽的效果无效化。②：表侧表示的此卡因对手的效果从场上离开的情况下，以自己墓地的1只机械族怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40516623,'相扑魂 YOKO－ZUNA',replace(replace('←1 【灵摆】 1→\r\n①：怪兽被灵摆召唤至场上的场合发动。将灵摆区的此卡返回至持有者手牌。\r\n【怪兽效果】\r\n①：此卡召唤成功时可发动。将与我方灵摆区卡牌相同纵列的所有对手怪兽送入墓地。\n②：此卡召唤、反转之回合的结束阶段发动。将此卡返回至持有者手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40522482,'摩天楼射击','①：以自己场上的１只“元素－英雄”融合怪兽为对象可以发动。将对手场上攻击力高于该怪兽的表侧表示怪兽全部破坏。然后，依以此效果被破坏并被送至墓地的怪兽中原本攻击力最高的数值，来给予对手伤害。自己的场地区域有“摩天楼”场地魔法卡存在的情况下，给予对手的伤害变为所有以此效果被破坏并被送至墓地的怪兽的原本攻击力的合计数值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40529384,'爆翼龙',replace(replace('协调＋1只以上协调以外的龙族怪兽\r\n①：此卡与怪兽进行战斗的伤害步骤开始时可以发动。破坏该怪兽，给予对手相当于其攻击力数值的伤害。在与此卡进行战斗的怪兽的攻击力在此卡攻击力以下的情况下，此效果才能发动和处理。','\r',char(13)),'\n',char(10)),'破坏并伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40542825,'凭依装着－莱娜',replace(replace('①：此卡可通过将自己场上的表侧表示的、1只“光灵使 莱娜”和1只光属性怪兽送至墓地，来从手牌・牌组特殊召唤。\r\n②：以此卡的①方法特殊召唤时可以发动。从牌组将“凭依装着－莱娜”以外的1只守备力1500的魔法师族怪兽加入手牌。\r\n③：以此卡的①方法特殊召唤的此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40542826,'凭依装着－莱娜',replace(replace('①：此卡可通过将自己场上的表侧表示的、1只“光灵使 莱娜”和1只光属性怪兽送至墓地，来从手牌・牌组特殊召唤。\r\n②：以此卡的①方法特殊召唤时可以发动。从牌组将“凭依装着－莱娜”以外的1只守备力1500的魔法师族怪兽加入手牌。\r\n③：以此卡的①方法特殊召唤的此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40543231,'巳剑之尊 麁正',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下，或此卡被解放的情况下可以发动。从牌组将“巳剑之尊 麁正”以外的1只“巳剑”怪兽加入手牌。\r\n②：自己场上的其他爬虫类族怪兽将被战斗・效果破坏的情况下，作为代替可将此卡解放。','\r',char(13)),'\n',char(10)),'检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40551410,'Recette de Personnel～伙食食谱～',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：以自己场上的１只仪式怪兽为对象可以发动。将１只“饿魔新飨衍生物”（恶魔族・暗・星１・攻／守５０）特殊召唤至自己场上。此衍生物的等级变为与对象怪兽相同。\r\n②：将魔法与陷阱区域表侧表示的此卡送至墓地可以发动。为使合计等级与仪式召唤的怪兽相等，解放自己的手牌・场上的怪兽，从手牌将１只“饿魔新飨”仪式怪兽仪式召唤。','\r',char(13)),'\n',char(10)),'特殊召唤衍生物','仪式召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40551411,'饿魔新飨衍生物','由「Recette de Personnel～伙食食谱～」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40555959,'空手假象','我方场上存在有“无限狱”怪兽的场合，１回合１次，直至下一个我方准备阶段时，可将所有我方手牌以里侧表示从游戏中除外。','手牌除外','是否要除外手牌？','发动同时使用效果','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40575313,'地狱亡灵','出现在荒野的野兽亡灵。是一张聚集数量后非常棘手的卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40583194,'力量共鸣者','①：将场上的此卡送至墓地，以自己场上的1只表侧表示怪兽为对象可以发动。此回合，该怪兽攻击的情况下，对手直至伤害步骤结束时为止，不可发动以怪兽为对象的魔法・陷阱・怪兽的效果。','效果抑制','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40591390,'命运－英雄 恐惧魔侠','①：此卡以“幽狱时钟塔”的效果特殊召唤成功的情况下发动。将自己场上“命运-英雄”怪兽以外的怪兽全部破坏。可从自己的墓地挑选最多2只“命运-英雄”怪兽特殊召唤。②：此卡特殊召唤成功的余下回合，自己场上的“命运-英雄”怪兽不会被破坏，因该怪兽的战斗对自己造成的战斗伤害变为0。③：此卡的攻击力・守备力变为自己场上其他“命运-英雄”怪兽原本攻击力的合计数值。','特殊召唤','是否要特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40597694,'散射结合',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：对手场上存在怪兽的情况下可以发动。将自己牌组的怪兽作为融合素材，将岩石族以外的1只“宝石骑士”融合怪兽融合召唤。此卡从场上离开时，该怪兽将被破坏。此效果发动后，直至回合结束时为止，自己从额外牌组仅可特殊召唤“宝石骑士”怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40605147,'神之通告',replace(replace('①：支付1500LP可以发动以下效果。\r\n●怪兽效果发动时可以发动。将该发动无效并破坏。\r\n●自己或对手特殊召唤怪兽之际可以发动。将该特殊召唤无效，将该怪兽破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40607210,'吸血鬼女王','此卡名的①效果１回合仅可使用１次。①：此卡存在于墓地的状态下，等级５以上的不死族怪兽因不死族怪兽的效果被特殊召唤至自己场上时，支付２０００LP可以发动。将此卡特殊召唤。②：１回合１次，宣言卡的种类（怪兽・魔法・陷阱）可以发动。对手从牌组将１张种类被宣言的卡送至墓地。','特殊召唤','牌组送墓','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40619741,'大日神械士兵','此卡的攻击宣言时，可选择对手场上的怪兽并改变表示形式，其数量最多与装备此卡的装备卡数量相同。','改变表示形式','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40619825,'恶魔之斧',replace(replace('①：令装备怪兽的攻击力上升１０００。\r\n②：当此卡从场上移入墓地时，可解放我方场上的１只怪兽来发动此卡。将此卡放回到牌组的最上面。','\r',char(13)),'\n',char(10)),'回到牌组的最上面','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40633084,'骑甲虫步兵分队',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：解放衍生物以外的、自己场上的１只昆虫族怪兽可以发动。该怪兽的原本攻击力每有１０００，将最多１只“骑甲虫衍生物”（昆虫族・地・星３・攻／守１０００）特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'','请选择要特殊召唤的衍生物的数量','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40633085,'骑甲虫衍生物','由"骑甲虫"卡片的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40633297,'药物的副作用','只要此卡存在于场上，回复对手LP的效果将变成给予对手生命伤害的效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40634253,'BM－4炸弹蜘蛛',replace(replace('此卡牌名的②效果１回合只可使用１次。\r\n①：１回合１次，可以我方场上的１只机械族、暗属性怪兽与对手场上的１张表侧表示卡牌为对象发动。破坏该卡。\r\n②：我方场上原本种族、属性为机械族、暗属性的怪兽，以战斗或自身效果破坏对手场上的怪兽并送入墓地的场合，可发动。给予对手相当于１只该被破坏并送入墓地怪兽的原本攻击力一半数值的伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40636712,'魔玩具・钩手海怪',replace(replace('“锋利小鬼”怪兽＋“绒毛动物”怪兽\r\n①：1回合1次，以对手场上的1只怪兽为对象可以发动。将该怪兽送至墓地。发动此效果的回合中，此卡不可直接攻击。②：此卡在1次战斗阶段中可攻击2次。③：此卡进行战斗的战斗阶段结束时可以发动。将此卡改为守备表示。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40640057,'库里波','①：因对手怪兽的攻击使得自己将受到战斗伤害的伤害计算时，从手牌将此卡舍弃可以发动。将因该战斗造成的对自己的战斗伤害改成0。','战斗伤害变成0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40640058,'库里波','①：因对手怪兽的攻击使得自己将受到战斗伤害的伤害计算时，从手牌将此卡舍弃可以发动。将因该战斗造成的对自己的战斗伤害改成0。','战斗伤害变成0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40640059,'库里波','①：因对手怪兽的攻击使得自己将受到战斗伤害的伤害计算时，从手牌将此卡舍弃可以发动。将因该战斗造成的对自己的战斗伤害改成0。','战斗伤害变成0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40640060,'库里波','①：因对手怪兽的攻击使得自己将受到战斗伤害的伤害计算时，从手牌将此卡舍弃可以发动。将因该战斗造成的对自己的战斗伤害改成0。','战斗伤害变成0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40640061,'库里波','①：因对手怪兽的攻击使得自己将受到战斗伤害的伤害计算时，从手牌将此卡舍弃可以发动。将因该战斗造成的对自己的战斗伤害改成0。','战斗伤害变成0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40659562,'守护者斯芬克斯','此卡在１个回合中可有１次机会变为里侧守备表示。成功反转召唤此卡时，令对手场上的所有怪兽回到持有者的手牌中。','变成里侧守备表示','对手场上的全部怪兽返回手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40663548,'芬芳法师－马郁兰',replace(replace('此卡名的①③效果１回合仅可各使用１次。\r\n①：自己的植物族怪兽因战斗被破坏时可以发动。从手牌将此卡特殊召唤。然后，自己恢复５００LP。\r\n②：只要自己的LP多于对手，且此卡存在于怪兽区域，因自己的植物族怪兽的战斗对自己造成的战斗伤害变为０。\r\n③：自己的LP恢复的情况下，以对手墓地的卡为对象发动，数量最多为自己场上的“芬芳”怪兽的数量。将该卡除外。','\r',char(13)),'\n',char(10)),'此卡从手牌特殊召唤','对手墓地的卡除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40666140,'极星灵 光明精灵','此卡召唤成功时，可选择我方场上１只除此卡以外的表侧表示怪兽并发动。从手牌特殊召唤１只等级是被选择怪兽等级或以下的冠有“极星”之名的怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40669071,'特码语者',replace(replace('电子界族怪兽2只以上\r\n此卡名的①效果1回合仅可使用1次。①：此卡连接召唤成功时，依额外怪兽区域的怪兽数量，指定尚未使用的主要怪兽区域可以发动。此怪兽以表侧表示存在期间指定区域不可使用。②：此卡连接端的怪兽攻击力上升500，不会因效果被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40672993,'避雷神','①：只要此卡存在于怪兽区域，在自己・对手的主要阶段1期间，双方不可发动魔法卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40673853,'超念铳士瓦隆',replace(replace('等级5怪兽×2\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己・对手的主要阶段，去除此卡的1个超量素材，以对手场上的1只表侧表示怪兽为对象可以发动。将该怪兽改成里侧守备表示。\r\n②：此卡被送至墓地的情况下，以场上的1张里侧表示卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'变成里侧表示','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40678060,'天子的指环',replace(replace('仅可装备于自己场上装备有装备卡的怪兽。\r\n①：“天子的指环”在自己场上仅可有1张以表侧表示存在。\r\n②：对手发动的魔法卡的效果1回合仅1次无效化。\r\n③：1回合1次，此卡被装备中的情况下可以发动。自己恢复500LP。然后，将此卡破坏，适用以下效果。\r\n●只要原先装备此卡的怪兽以表侧表示存在于怪兽区域，对手不可将该怪兽作为效果的对象。','\r',char(13)),'\n',char(10)),'','','「天子的指环」效果适用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40680521,'弈勇之聚－幻中',replace(replace('←10 【灵摆】 10→\r\n此卡名的灵摆效果１回合仅可使用１次。①：可从以下效果中选择１个发动。\n●将此卡特殊召唤至正面的自己主要怪兽区域。\n●挑选１只自己主要怪兽区域的怪兽，将其位置移动至其相邻的怪兽区域。\r\n【怪兽效果】\r\n“弈勇”怪兽×３\n此卡名的①怪兽效果１回合仅可使用１次。①：在双方的主要阶段，以对手主要怪兽区域的１只效果怪兽为对象可以发动。将该对手怪兽视为永续魔法卡，以表侧表示放在与其同一纵列的对手的魔法与陷阱区域（原先位于所放之处的卡将被破坏，其为怪兽卡的情况下，对手将失去相当于其攻击力数值的LP）。②：特殊召唤的此卡因对手的效果被破坏的情况下可以发动。将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'特殊召唤','位置移动','请选择移动位置的怪兽','请选择要放置到后场的怪兽','','','','','','','','','','','','');
INSERT INTO texts VALUES(40695128,'磨破罗魏','此卡不可特殊召唤。召唤・反转此卡的回合的结束阶段时回到持有者的手牌中。此外，召唤・反转此卡时发动此卡。在我方下个抽牌阶段抽牌前确认牌组最上面的卡牌，并将其放回至牌组的最上方或最下方。','返回手牌','确认卡','放回牌组最上面','放回牌组最下面','','','','','','','','','','','','');
INSERT INTO texts VALUES(40702028,'DPA 摩尔枪骑兵',replace(replace('协调＋协调以外的怪兽１只以上\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡同步召唤的情况下可以发动。从自己的墓地将１只电子界族・等级４怪兽的效果无效并以守备表示特殊召唤。此回合，自己仅可特殊召唤电子界族怪兽。\r\n②：自己的电子界族怪兽以与对手怪兽的战斗给予对手战斗伤害时，将墓地的此卡除外可以发动。依其数值给予对手伤害。','\r',char(13)),'\n',char(10)),'特殊召唤','给予伤害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40703222,'增殖','①：解放自己场上的1只表侧表示的“库里波”可以发动。将“库里波衍生物”（恶魔族・暗・星1・攻300/守200）尽可能地以守备表示特殊召唤至自己场上。此衍生物不可为上级召唤而解放。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40703223,'库里波衍生物','由“增殖”的效果特殊召唤而来。此衍生物不可用作上级召唤的祭品。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40703393,'冥界流傀儡术','选择存在于我方墓地的１只恶魔族怪兽发动。将存在于我方场上的怪兽从游戏中除外，其合计等级和所选怪兽的等级相同。之后，从墓地特殊召唤所选怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40706444,'阿尔戈☆群星－勇骏的阿里翁',replace(replace('等级4怪兽×2\r\n“阿尔戈☆群星－勇骏的阿里翁”1回合1次，也可重叠在自己场上的“阿尔戈☆群星”怪兽上面来超量召唤。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡超量召唤的情况下可以发动。从牌组将1张“阿尔戈☆群星”魔法卡加入手牌。\r\n②：在自己・对手的准备阶段，去除此卡的2个超量素材可以发动。从自己墓地将最多3张“阿尔戈☆群星”永续陷阱卡以表侧表示放在自己的魔法与陷阱区域。','\r',char(13)),'\n',char(10)),'是否在「阿尔戈☆群星」怪兽上面重叠来超量召唤？','检索','表侧表示放置','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40725446,'荧焅圣 亚雷库斯',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次，且②③效果1回合仅可各使用1次。\r\n①：自己的魔法与陷阱区域存在表侧表示卡的情况下，此卡可从手牌特殊召唤。\r\n②：以自己场上1张表侧表示的魔法・陷阱卡为对象可以发动。将该卡破坏。然后，自己抽1张。\r\n③：此卡被破坏的情况下，以自己场上的1只超量怪兽为对象可以发动。将此卡作为该怪兽的超量素材。','\r',char(13)),'\n',char(10)),'破坏效果','作为超量素材','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40732515,'神圣魔导王 恩底弥翁',replace(replace('①：此卡可通过去除自己场上的“魔法都市 恩底弥翁”上放有的6个魔力计数物，来从手牌・墓地特殊召唤。\r\n②：以此卡的①方法特殊召唤的情况下，以自己墓地的1张魔法卡为对象发动。将该卡加入手牌。\r\n③：1回合1次，从手牌舍弃1张魔法卡，以场上的1张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'墓地存在的1张魔法卡加入手牌','场上存在的1张卡破坏','请选择要取除计数物的卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40736921,'心镇壶的复制品','可选择１张被盖牌在场上的魔法、陷阱卡并发动。只要此卡存在于场上，被选择卡牌不可发动。针对此卡的发动，魔法、陷阱、怪兽的效果不可发动。','请选择一张放置的魔法·陷阱卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40737112,'混沌黑魔术师','此卡名的①效果1回合仅可使用1次。①：此卡召唤・特殊召唤成功的回合的结束阶段，以自己墓地的1张魔法卡为对象可以发动。将该卡加入手牌。②：此卡战斗破坏对手怪兽的伤害计算后发动。将该对手怪兽除外。③：表侧表示的此卡离开场上的情况下，将其除外。','魔法回收','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40740224,'交叉看守员','此卡名的①②效果１回合仅可各使用１次。①：将手牌・场上的此卡送至墓地可以发动。从自己的手牌・墓地挑选１只“元素－英雄”怪兽或“新空间人”怪兽特殊召唤。以此效果从墓地特殊召唤的怪兽的效果无效化。②：此卡存在于墓地的状态下，自己将“元素－英雄”融合怪兽特殊召唤成功的情况下，将此卡除外可以发动。自己从牌组抽２张，然后挑选１张手牌放回牌组最下面。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40771118,'死之宣告',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：从自己墓地的怪兽及自己被除外的怪兽中，以恶魔族怪兽为对象可以发动，数量最多为自己场上“通灵盘”和“死之信息”卡的数量。将该怪兽加入手牌。\r\n②：将魔法与陷阱区域的此卡送至墓地可以发动。从自己的手牌・牌组・墓地挑选１张“死之信息”卡，视为以“通灵盘”的效果出到自己的魔法与陷阱区域。','\r',char(13)),'\n',char(10)),'回收怪兽','让「死之信息」出现','请选择要出现的卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40785230,'韦陀・优婆尼沙昙',replace(replace('←0 【灵摆】 0→\r\n①：自己或对手的怪兽被破坏的情况下发动（同一连锁上最多１次）。在此卡上放３个计数物。\n②：此卡的灵摆刻度上升相当于此卡计数物的数值。\n③：去除此卡的１２个计数物可以发动。将此卡特殊召唤。\r\n【怪兽效果】\r\n此卡不可通常召唤，仅可以此卡的灵摆效果特殊召唤。\n自己１回合仅可特殊召唤１次“韦陀・优婆尼沙昙”。\n①：１回合１次，对手从额外牌组将怪兽特殊召唤的情况下，从自己的手牌・场上・墓地将１２张卡以里侧除外可以发动。直接变为此回合的结束阶段。\n②：在自己的准备阶段发动。将此卡放回手牌。然后，可将自己的手牌・牌组・墓地・除外状态的１只“韦陀”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','变成这个回合的结束阶段','此卡回到手牌','是否特殊召唤？','','','','','','','','','','','','');
INSERT INTO texts VALUES(40817915,'闪电栗子球','可选择１只有超量素材的超量怪兽发动。移除１个该怪兽的超量素材，并从卡组中特殊召唤１只“闪电栗子球”。这张卡无法用作同步素材。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40826495,'岩浆人','从岩浆中诞生的怪兽。由于温度极高，会熔化任何靠近它的东西。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40830387,'古代机械齿轮掌','仅限装备冠有“古代机械齿轮”之名的怪兽。在该伤害步骤结束时，破坏与装备怪兽进行战斗的怪兽。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40838625,'沙尘防护罩 －尘埃之力－','①：对手怪兽攻击宣言时可以发动。将对手场上的攻击表示怪兽全部改成里侧守备表示。以此效果变为里侧守备表示的怪兽不可变更表示形式。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40844552,'极星天 女武神','①：此卡召唤成功时，对手场上存在有怪兽，且我方场上不存在有除此卡以外的卡牌的场合，可从手牌将２只“极星”怪兽除外并发动。以守备表示特殊召唤２只“英灵衍生物”（战士族、地、星４、攻／守１０００）至我方场上。','特殊召唤Token','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40844553,'英灵衍生物','由“极星天女武神”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40847034,'杀手旋律・歌单',replace(replace('此卡名的卡1回合最多可以发动2张。\r\n①：以自己场上・墓地的1只“杀手旋律”怪兽为对象可以发动。分别适用以下效果。此卡发动后，直至回合结束时为止，自己仅可特殊召唤协调。\r\n●适用对象怪兽的、自身作为同步素材被送至墓地的情况下发动的效果。\r\n●将对象怪兽放回手牌。','\r',char(13)),'\n',char(10)),'发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40854197,'元素－英雄 绝对零度',replace(replace('“－英雄”怪兽＋水属性怪兽\r\n此卡仅可以融合召唤方式特殊召唤。\r\n①：此卡的攻击力上升“元素－英雄 绝对零度”以外的、场上的水属性怪兽的数量×500的数值。\r\n②：表侧表示的此卡从场上离开，被送至墓地的情况下或被除外的情况下发动。将对手场上的怪兽全部破坏。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40854824,'飞越彩虹','①：我方场上原本卡牌名是“究极宝玉神 彩虹龙”或“究极宝玉神 彩虹暗黑龙”的怪兽发动效果的回合可发动。从牌组特殊召唤任意数量的“宝玉兽”怪兽（同名卡最多１张）。','是否还要继续特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40867519,'静寂虫','此卡召唤、反转召唤成功时，变成守备表示。只要此卡以表侧表示存在于场上，场上的永续魔法、永续陷阱卡效果无效。','变成守备表示','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40884383,'凶恶犯－开膛手','此卡反转召唤成功时，可将我方墓地的１张装备魔法卡装备至此卡。','装备','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40894584,'基哥百特',replace(replace('①：“基哥百特”在自己场上仅可有1张以表侧表示存在。\r\n②：自己场上存在魔法师族怪兽的情况下，此卡可从手牌特殊召唤。\r\n③：此卡因战斗・效果被破坏并被送至墓地时可以发动。从牌组将“基哥百特”以外的1只攻击力1500/守备力200的怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40907115,'灵兽使 温',replace(replace('自己１回合仅可特殊召唤１次“灵兽使 温”。\r\n①：此卡召唤的情况下，以自己除外状态的１只“灵兽”怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40908371,'苍眼银龙',replace(replace('协调＋协调以外的通常怪兽１只以上\r\n①：此卡特殊召唤的情况下发动。自己场上的所有龙族怪兽直至下个回合结束时为止不会因效果被破坏，双方直至下个回合结束时为止不可将那些怪兽作为效果的对象。\r\n②：在自己的准备阶段，以自己墓地的１只通常怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'效果耐性','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40916023,'水之精灵 亚库艾莉娅','此卡不可通常召唤。将我方墓地中１只水属性怪兽从游戏中除外的场合，可特殊召唤此卡。可每次在对手的准备阶段选择对手场上１只表侧表示的怪兽并变更其表示形式。该回合所选择怪兽不可变更表示形式。','改变表示形式','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40921545,'邪蚀 鲸','可释放此卡发动。选择对手场上的１张魔法、陷阱卡破坏。','魔陷破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40921744,'堕天使 杰拉特',replace(replace('自己墓地存在4种以上的暗属性怪兽的情况下，此卡可通过解放1只暗属性怪兽来上级召唤。\r\n①：从手牌将1只暗属性怪兽送至墓地可以发动。将对手场上的怪兽全部破坏。\r\n②：在发动了此卡的①效果的回合的结束阶段发动。将此卡破坏。','\r',char(13)),'\n',char(10)),'把1只暗属性怪兽解放上级召唤','对手场上存在的怪兽全部破坏','此卡破坏','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40933924,'黑蝎盗掘团','此卡给予对手生命战斗伤害时，对手从牌组将１张魔法卡送入墓地。','选择1张魔法卡送至墓地','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40937767,'墓穴王者','只要我方场上存在里侧守备表示的怪兽，对手怪兽就不可选择此卡作为攻击对象。每次我方场上的怪兽进行反转召唤，给予对手生命３００点伤害。','LP伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40939228,'流天救世星龙',replace(replace('“救世龙”＋１只以上包含龙族同步怪兽在内的协调以外的怪兽\r\n此卡仅可以同步召唤从额外牌组特殊召唤。①：１回合１次，可以发动。挑选对手场上的１只效果怪兽，将该效果无效。②：此卡在通常攻击外可追加攻击，次数最多为自己墓地的“星尘龙”及记载有该卡名的同步怪兽数量。③：１回合１次，对手发动效果时可以发动。将此卡直至结束阶段为止除外，将该发动无效并除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40941889,'ZEXAL兵器－阿修罗副腕','①：“ZEXAL兵器－阿修罗副腕”在自己场上仅可有１张以表侧表示形式存在。②：以自己场上的１只“希望皇霍普”怪兽为对象可以发动。从自己的手牌・场上，将此卡视为攻击力上升１０００的装备卡，装备于该自己的“希望皇霍普”怪兽。③：此卡被装备中的情况下，装备怪兽可攻击对手场上的所有怪兽各１次。','装备','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40945356,'黄昏的中忍－日轮',replace(replace('此卡在规则上也被视为“忍者”卡牌。\r\n①：１回合１次，可从手牌舍弃１只“忍者”怪兽，并从以下效果选择１个发动。此效果在对手回合也可发动。\r\n●此回合，我方场上的“忍者”怪兽以及“忍法”卡牌不会因战斗、效果被破坏。\r\n●挑选我方场上的１只“忍者”怪兽，直至回合结束时该攻击力上升１０００。','\r',char(13)),'\n',char(10)),'破坏耐性','攻击上升1000','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40971261,'亡龙之旋律',replace(replace('宣言１个卡名可以发动此卡。\r\n①：只要此卡存在于魔法与陷阱区域，每次被宣言的卡的效果发动，发动该效果的卡的原本持有者的LP变为一半。在适用此效果的回合的结束阶段，此卡将被送至墓地。\r\n②：对手场上有怪兽存在的情况下，此卡不会因效果被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40975243,'铁兽之御敌',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：将自己墓地・除外状态的任意数量的兽族・兽战士族・鸟兽族怪兽效果无效并特殊召唤，将１只仅以该怪兽作为素材的“铁兽”连接怪兽连接召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40975574,'红莲共鸣者',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：此卡召唤时可以发动。从手牌将1只等级4以下的怪兽特殊召唤。\r\n②：此卡特殊召唤时，以场上的1只表侧表示怪兽为对象可以发动。依该怪兽的攻击力的数值恢复自己的LP。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40991587,'白骨夫人','①：此卡只要存在于墓地，卡名视为“白骨”。②：只要此卡存在于怪兽区域，“白骨夫人”以外的等级３以下不死族怪兽不会因战斗被破坏，也不受魔法・陷阱卡的效果影响。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(40998517,'剑之创王 弗洛迪','此卡名的②效果1回合仅可使用1次。①：“剑之创王 弗洛迪”在自己场上仅可有1只以表侧表示存在。②：解放自己场上任意数量的“创王”怪兽或者是战士族怪兽，可以场上与之相应的数量的怪兽为对象发动。将该怪兽破坏。然后，对手可以从牌组抽与对手场上被破坏的怪兽的相同数量的卡。此效果在对手回合中也可以发动。','','是否抽牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41002238,'帝王滑翔龙－黄金爆裂',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：解放自己场上的１只怪兽可以发动。从手牌将此卡特殊召唤。此效果在对手回合中也可以发动。\r\n②：此卡召唤・特殊召唤成功的情况下，以对手场上的１只表侧表示怪兽为对象可以发动。此卡的攻击力直至回合结束时为止，变为与该怪兽的攻击力相同。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41006930,'速攻的黑色忍者','可将我方墓地的２只暗属性怪兽从游戏中除外并发动。直至结束阶段，将表侧表示的此卡从游戏中除外。此效果在对手回合也可使用。“速攻的黑色忍者”的效果１回合只可使用１次。','除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41039846,'乌鸦巨群','此卡不可从牌组特殊召唤。此卡在１个回合中可有１次机会变为里侧守备表示。成功反转召唤此卡时，随机弃置对手１张手牌。','变成里侧表示','手牌丢弃','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41044418,'千年的启示',replace(replace('此卡名的效果①②在1个回合中仅可各使用1次。\r\n①：从手牌将1只幻神兽族怪兽送至墓地后可以发动。从自己的牌组、墓地选择1张“死者苏生”加入手牌。\r\n②：将魔法与陷阱区域表侧表示的此卡送至墓地后可以发动。此回合中，因自己的“死者苏生”，可无视召唤条件而特殊召唤自己墓地的“拉之翼神龙”。在发动了此效果的回合的结束阶段，自己必须将用“死者苏生”的效果特殊召唤的“太阳神的翼神龙”送至墓地。','\r',char(13)),'\n',char(10)),'检索或回收','准备死苏翼神龙','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41061625,'椰子树','拥有自我意志的椰子树。它会落下果实来攻击敌人。果实中的椰奶相当美味。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41069676,'杀手旋律・响度战争',replace(replace('协调＋协调1只以上\r\n此卡名的②效果1回合仅可使用1次。\r\n①：只要此卡存在于怪兽区域，自己场上其他的协调不会因效果被破坏，且对手不可将其作为效果的对象。\r\n②：对手发动效果时，从自己墓地将1只“杀手旋律”怪兽除外可以发动。适用除外的怪兽的、自身作为同步素材被送至墓地的情况下发动的效果。','\r',char(13)),'\n',char(10)),'复制效果','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41077745,'元素－英雄 冰棱侠','１回合１次，可在我方主要阶段舍弃１张手牌并发动。此回合此卡可直接攻击对手玩家。此外，此卡因直接攻击给予对手生命战斗伤害时可发动。选择被盖牌在对手魔法与陷阱区域的１张卡牌并破坏。','直接攻击','魔陷破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41085464,'书灵师・再崛起','①：为使合计等级达到仪式召唤的怪兽的等级以上，解放自己手牌・场上的怪兽，从手牌将1只“书灵师”仪式怪兽仪式召唤。以此效果使用场上的“书灵师・烈火引燃者”来仪式召唤的“书灵师・烈火爆裂”不会因效果被破坏，不可因效果除外。','「书灵师・再崛起」效果适用中','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41089128,'火炎的支配者','上级召唤炎属性怪兽的情况下，此卡可作为２只解放。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41090784,'冰结界的大僧正',replace(replace('①：此卡召唤・反转召唤的情况下发动。将此卡改成守备表示。\r\n②：只要此卡存在于怪兽区域，自己场上的“冰结界”怪兽不会因魔法・陷阱卡的效果被破坏。','\r',char(13)),'\n',char(10)),'变成守备表示','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41091257,'秘旋谍－花花公子',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡存在于手牌的情况下，宣言卡的种类（怪兽・魔法・陷阱）可以发动。将对手牌组最上面的卡给彼此确认，是所宣言的种类的卡的情况下，从手牌将此卡特殊召唤。\r\n②：此卡以“秘旋谍”卡的效果特殊召唤的情况下，以对手场上的１张魔法・陷阱卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41097056,'同步破解法','①：以自己场上的１只同步怪兽为对象可以发动。将该怪兽放回持有者的额外牌组，将对手场上攻击力在该同步怪兽原本攻击力以下的表侧表示怪兽全部破坏。','返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41098335,'斗士猿','此卡因战斗破坏对手怪兽时，此卡的攻击力上升３００点。此卡在我方回合中未进行攻击的场合，直至回合结束时，以此效果上升的数值归０。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41113025,'圆盘骑士','１回合１次，可选择我方墓地的１张通常陷阱卡并发动。被选择的卡牌从游戏中除外，直至对手回合结束时，此卡的攻击力上升５００点。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41114306,'方界兽暗黑・甘尼克斯',replace(replace('此卡不可通常召唤。\r\n我方场上的１只“方界”怪兽送入墓地的场合可特殊召唤。\r\n①：以此方法特殊召唤的此卡攻击力上升１０００。\r\n②：此卡因战斗破坏了怪兽时，可以我方墓地最多２只“方界胤维贾姆”为对象发动。将此卡送入墓地，并特殊召唤对象怪兽。之后，可从牌组将１只“方界兽刀刃・迦楼迪亚”加入手牌。','\r',char(13)),'\n',char(10)),'是否把1只「方界兽刀刃・迦楼迪亚」加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41128647,'机动阵 强化',replace(replace('①：场上的“机动雾龙”怪兽的攻击力・守备力上升３００。\r\n②：自己的“机动雾龙”怪兽进行战斗的情况下，对手直至伤害步骤结束时为止，不可发动魔法・陷阱・怪兽的效果。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41139112,'召唤骰子',replace(replace('此卡牌名的卡牌１回合只可发动１张。\r\n①：可支付１０００LP并发动。掷１次骰子，适用掷出点数的效果。\r\n●１、２：可召唤１只怪兽。\r\n●３、４：可从我方墓地挑选１只怪兽并特殊召唤。\r\n●５、６：可从手牌特殊召唤１只等级５或以上的怪兽。','\r',char(13)),'\n',char(10)),'是否召唤？','是否从墓地特殊召唤？','是否从手牌特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41141943,'超重武者 飞脚－Q','此卡名的②效果１回合仅可使用１次。①：自己的墓地不存在魔法・陷阱卡的情况下，此卡可从手牌中特殊召唤。以此方法特殊召唤成功的余下本回合，自己仅可特殊召唤“超重武者”怪兽。②：自己的墓地不存在魔法・陷阱卡的情况下，解放此卡可以发动。从手牌将最多２只怪兽以守备表示特殊召唤至对手场上。然后，依以此效果特殊召唤的怪兽数量，自己从牌组抽牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41142615,'爽朗埋葬者','将我方手牌中最多３只怪兽卡弃置至墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41147577,'混沌超量 风纪大宫司祭文',replace(replace('等级７怪兽×３\r\n此卡不受其他怪兽效果的影响。此外，此卡以“风纪宫司 祝词”为超量素材的场合，获得以下效果。\r\n●１回合１次，可移除此卡的１个超量素材，选择对手场上的１只怪兽并发动。变更被选择怪兽的表示形式，且直至回合结束时，使该怪兽的效果无效。此效果在对手回合也可发动。','\r',char(13)),'\n',char(10)),'效果无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41158734,'阿波卡提奎尔','我方场上存在有协调的场合，场上的此卡被视为等级５。场上的此卡被破坏并送入墓地时，可选择我方墓地的１只“太阳的神官”并特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41160533,'蔷薇藤蔓','此卡不可特殊召唤。在我方战斗阶段开始时对手场上存在有植物族怪兽的场合，此回合此卡除了通常攻击以外，最多可进行与该植物族怪兽数量相同次数的攻击。此卡因战斗破坏植物族怪兽时，给予对手生命３００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41160595,'召集魔法','因对手的魔法、陷阱卡效果被盖牌的此卡被破坏并送入墓地时，从牌组挑选１张速攻魔法卡并盖牌至我方场上。','检索放置','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41165831,'破械神 奢婆罗',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡存在于手牌的情况下，在自己・对手的主要阶段，以自己场上的1只恶魔族怪兽或1张里侧表示卡为对象可以发动。将该卡破坏，将此卡特殊召唤。只要以此效果特殊召唤的此卡以表侧表示存在于怪兽区域，自己仅可特殊召唤恶魔族怪兽。\r\n②：此卡被送至墓地的情况下可以发动。从牌组将1张“破械”魔法・陷阱卡放置在自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41172955,'绿色小工具','①：此卡召唤・特殊召唤成功时可以发动。从牌组将１只“红色小工具”加入手牌。','选1只「红色小工具」加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41175645,'沉默魔术师',replace(replace('此卡不可通常召唤。仅可在解放自己场上的１只魔法师族怪兽的情况下特殊召唤。\r\n①：此卡的攻击力上升相当于自己手牌数量×５００的数值。\r\n②：１回合１次，魔法卡发动时可以发动。将该发动无效。\r\n③：场上的此卡因战斗或对手的效果被破坏的情况下可以发动。从手牌・牌组将“沉默魔术师”以外的１只“沉默魔术师”怪兽无视召唤条件特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41181774,'地缚神 Wiraqocha Rasca',replace(replace('①：“地缚神”怪兽在场上仅可有１只以表侧表示存在。\r\n②：此卡召唤的情况下，以自己场上其他的卡为对象发动，数量最多为对手的手牌数量（最多３张）。将该卡放回牌组。然后，依所放回的数量随机舍弃对手的手牌，此卡的攻击力上升相当于所舍弃数量×１０００的数值。\r\n③：此卡可直接攻击。\r\n④：对手怪兽不可将此卡选择为攻击对象。\r\n⑤：不存在表侧表示的场地魔法卡的情况下，此卡将被破坏。','\r',char(13)),'\n',char(10)),'返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41182875,'标枪甲虫的契约','用于召唤“标枪甲虫”。必须从手牌・我方场上解放合计等级达到８以上的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41197012,'绯暗红毯','①：场上存在龙族同步怪兽的情况下，以自己墓地最多2只“共鸣者”怪兽为对象可以发动。将该怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41201386,'升阶魔法－急袭之力','①：以自己场上的1只超量怪兽为对象可以发动。将1只阶级比该怪兽高1的“急袭猛禽”怪兽重叠在自己的对象怪兽上面，视为超量召唤从额外牌组特殊召唤。②：将墓地的此卡和1张手牌的“急袭猛禽”卡除外，以“升阶魔法-急袭之力”以外的自己墓地的1张“升阶魔法”魔法卡为对象可以发动。将该卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41201555,'核成初孕玫瑰','此卡的控制者每次我方的结束阶段，从手牌将１张“核成之钢核”送入墓地，或向对手展示１只手牌的植物族怪兽。或者不执行上述两项破坏此卡。我方准备阶段时可发动。从牌组将１只等级３或以下的怪兽送入墓地。','选择一张「核成之钢核」送至墓地','选择一张植物族怪兽给对手观看','破坏「核成初孕玫瑰」','送墓','','','','','','','','','','','','');
INSERT INTO texts VALUES(41209827,'凶饿猛毒结合龙',replace(replace('衍生物以外的场上的暗属性怪兽×2\r\n①：此卡融合召唤的情况下可以发动。此卡的攻击力直至回合结束时为止，上升对手场上1只被特殊召唤的怪兽攻击力的数值。\r\n②：1回合1次，以对手场上1只等级5以上的怪兽为对象可以发动。直至结束阶段为止，此卡获得与该怪兽原本卡名・效果相同的卡名・效果。\r\n③：融合召唤的此卡被破坏的情况下可以发动。将对手场上被特殊召唤的怪兽全部破坏。','\r',char(13)),'\n',char(10)),'攻击力上升','复制效果','全部破坏','结束复制效果','','','','','','','','','','','','');
INSERT INTO texts VALUES(41209828,'凶饿猛毒结合龙',replace(replace('衍生物以外的场上的暗属性怪兽×2\r\n①：此卡融合召唤的情况下可以发动。此卡的攻击力直至回合结束时为止，上升对手场上1只被特殊召唤的怪兽攻击力的数值。\r\n②：1回合1次，以对手场上1只等级5以上的怪兽为对象可以发动。直至结束阶段为止，此卡获得与该怪兽原本卡名・效果相同的卡名・效果。\r\n③：融合召唤的此卡被破坏的情况下可以发动。将对手场上被特殊召唤的怪兽全部破坏。','\r',char(13)),'\n',char(10)),'攻击力上升','复制效果','全部破坏','结束复制效果','','','','','','','','','','','','');
INSERT INTO texts VALUES(41215808,'随风飘飘游与梦之乡','此卡名的②效果１回合仅可使用１次。①：在自己・对手的主要阶段可以发动。召唤１只等级４以下的鸟兽族怪兽。②：此卡存在于墓地的状态下，自己将等级７以上的怪兽上级召唤成功的情况下，将此卡除外可以发动。将对手场上的怪兽全部改成里侧守备表示。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41218256,'利爪杀手','手臂能自由伸缩，用尖利的爪子刺穿敌人。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41224658,'野望的高弗','１回合１次，可选择对手场上最多２只怪兽并发动。对手可展示１只手牌的怪兽并使此卡的效果无效。若不展示的场合，破坏被选择怪兽。','破坏','是否要把一只怪兽给对手观看？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41230939,'电子暗黑角',replace(replace('①：此卡召唤的情况下，以自己墓地的1只等级3以下的龙族怪兽为对象发动。将该龙族怪兽视为装备魔法卡装备于此卡。\r\n②：此卡的攻击力上升以此卡的效果装备的怪兽的攻击力数值。\r\n③：此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。\r\n④：此卡将被战斗破坏的情况下，作为代替将以此卡的效果装备的怪兽破坏。','\r',char(13)),'\n',char(10)),'装备','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41232647,'龙女仆・总管龙女',replace(replace('“龙女仆”怪兽＋龙族怪兽\r\n①：在自己・对手的准备阶段，以自己场上的1只其他“龙女仆”怪兽为对象可以发动。从自己手牌・墓地将1只等级比该怪兽高1或低1的“龙女仆”怪兽以守备表示特殊召唤。\r\n②：此卡存在于怪兽区域的状态下，自己场上的表侧表示龙族怪兽被放回自己手牌时，以对手场上的1只怪兽为对象可以发动。将该怪兽破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41232648,'龙女仆・总管龙女',replace(replace('“龙女仆”怪兽＋龙族怪兽\r\n①：在自己・对手的准备阶段，以自己场上的1只其他“龙女仆”怪兽为对象可以发动。从自己手牌・墓地将1只等级比该怪兽高1或低1的“龙女仆”怪兽以守备表示特殊召唤。\r\n②：此卡存在于怪兽区域的状态下，自己场上的表侧表示龙族怪兽被放回自己手牌时，以对手场上的1只怪兽为对象可以发动。将该怪兽破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41234315,'伪爆破五星','对手怪兽的攻击宣言时可发动。怪兽不会因该战斗被破坏，伤害计算结束后，从我方手牌、墓地挑选１只“召唤热核・大”并特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41248270,'流量幽灵','怪兽３只','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41249545,'幻影草','此卡的攻击力上升相当于我方墓地存在的“幻影草”数量×５００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41255165,'企鹅忍者',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：此卡反转的情况下，以对手场上的最多2张魔法・陷阱卡为对象可以发动。将该卡放回手牌。\r\n②：以自己场上的1只“企鹅”怪兽为对象可以发动。将该怪兽改成里侧守备表示。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41269771,'星圣 摩羯格雷迪','①：此卡召唤时可以发动。从手牌将1只等级4的“星圣”怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41302052,'淘气仙星・颠茄歌后',replace(replace('“淘气仙星”怪兽2只以上\r\n此卡名的②效果1回合仅可使用1次。①：连接召唤的此卡的连接端没有怪兽存在的情况下，此卡不受其他卡发动的效果影响。②：此卡连接端没有怪兽存在的情况下可以发动。给予对手相当于自己墓地的“淘气仙星”怪兽种类×200的伤害。','\r',char(13)),'\n',char(10)),'给予伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41306080,'凉飕飕＠伊格尼斯者','此卡名的①②效果1回合仅可各使用1次。①：在自己场上有“＠伊格尼斯者”怪兽存在的情况下可以发动。从手牌将此卡特殊召唤。②：解放自己场上此卡以外的1只电子界族怪兽可以发动。从牌组将1只等级5以上的“＠伊格尼斯者”怪兽加入手牌，此卡的等级直至回合结束时为止改为4。为发动此效果解放连接怪兽的情况下，进而可从牌组将1张“-艾-爱之仪式”加入手牌。','','','是否把「-艾-爱之仪式」加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41307269,'超重武者兜－10','①：对手特殊召唤怪兽成功的场合可发动。将我方场上所有攻击表示的“超重武者”怪兽变成守备表示，直至回合结束时，该守备力上升５００。','表示形式变换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41309158,'混沌超量 机装魔人・引擎天将',replace(replace('等级４怪兽×３\r\n此卡超量召唤成功时可以发动。选择场上的１只守备表示怪兽变成攻击表示。此外，此卡以“机装天使・引擎天兵”为超量素材的情况下，获得以下效果。\r\n●此卡给予对手LP战斗伤害时，移除此卡的１个超量素材可以发动。给予对手LP１０００点伤害。','\r',char(13)),'\n',char(10)),'改变表示形式','LP伤害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41329458,'幻兽机格林芬','我方主要阶段时，可释放我方场上２只冠有“幻兽机”之名的怪兽并发动。从手牌特殊召唤此卡。“幻兽机格林芬”的此效果１回合只可使用１次。只要我方场上存在衍生物，此卡不会因战斗以及效果被破坏。此外，１回合１次，可从手牌舍弃１只冠有“幻兽机”之名的怪兽并发动。特殊召唤１只“幻兽机衍生物”（机械族・风・星３・攻／守０）。','特殊召唤','特召衍生物','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41329459,'幻兽机衍生物','由名称中带有“幻兽机”的怪兽等的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41348446,'爆破代码','此卡名的①②效果１回合仅可各使用１次。①：自己场上存在“拓扑逻辑”连接怪兽的情况下，以连接怪兽以外的、自己墓地的１只龙族・机械族・电子界族的暗属性怪兽为对象可以发动。将该怪兽特殊召唤。②：此卡从魔法与陷阱区域被除外的情况下，在下个回合的准备阶段可以发动。将此卡放置在自己场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41350417,'黑之魔导的帘布',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：双方可各自从自身手牌・牌组将1只魔法师族・暗属性怪兽特殊召唤。自己以此效果特殊召唤的怪兽原本卡名为“黑魔导”或“黑魔导女孩”的情况下，自己进而可从牌组将除“黑之魔导的帘布”以外的、1张记载有“黑魔导”卡名的魔法・陷阱卡加入手牌。此回合，以此效果特殊召唤的怪兽的效果不可发动。','\r',char(13)),'\n',char(10)),'发动','是否特殊召唤？','是否加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41350418,'黑之魔导的帘布',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：双方可各自从自身手牌・牌组将1只魔法师族・暗属性怪兽特殊召唤。自己以此效果特殊召唤的怪兽原本卡名为“黑魔导”或“黑魔导女孩”的情况下，自己进而可从牌组将除“黑之魔导的帘布”以外的、1张记载有“黑魔导”卡名的魔法・陷阱卡加入手牌。此回合，以此效果特殊召唤的怪兽的效果不可发动。','\r',char(13)),'\n',char(10)),'发动','是否特殊召唤？','是否加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41356845,'蓄满硫酸的落穴','①：可以场上１只里侧守备表示的怪兽为对象发动。将该怪兽变成表侧守备表示，守备力是２０００或以下的场合将其破坏。守备力高于２０００的场合，则变回里侧守备表示。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41356846,'蓄满硫酸的落穴','①：可以场上１只里侧守备表示的怪兽为对象发动。将该怪兽变成表侧守备表示，守备力是２０００或以下的场合将其破坏。守备力高于２０００的场合，则变回里侧守备表示。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41359411,'圣剑 格兰特',replace(replace('仅可装备于战士族怪兽。\r\n此卡名的③效果１回合仅可使用１次。\r\n①：“圣剑 格兰特”在自己场上仅可有１张以表侧表示存在。\r\n②：１回合１次，支付５００LP可以发动。此回合，装备怪兽可直接攻击。\r\n③：场上表侧表示的此卡被破坏并被送至墓地的情况下，以自己场上的１只战士族“圣骑士”怪兽为对象可以发动。将此卡装备于该自己的战士族“圣骑士”怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41367003,'抽卡肌肉',replace(replace('“抽卡肌肉”１回合仅可发动１张。\r\n①：以自己场上１只守备力１０００以下的表侧守备表示怪兽为对象可以发动。自己从牌组抽１张。该怪兽此回合不会因战斗被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41371602,'站起来吧・百夫骑士！',replace(replace('此卡名的②③效果１回合仅可各使用１次。\r\n①：只要自己场上存在“百夫骑”怪兽卡，此卡不会因对手的效果被破坏。\r\n②：在发动了此卡的回合的自己的主要阶段，将１张手牌送至墓地可以发动。从牌组将１只“百夫骑”怪兽视为永续陷阱卡，以表侧表示放在自己的魔法与陷阱区域。\r\n③：怪兽被特殊召唤的情况下可以发动。以包含“百夫骑”怪兽在内的、自己场上的怪兽作为素材进行同步召唤。','\r',char(13)),'\n',char(10)),'','同步召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41371603,'站起来吧・百夫骑士！',replace(replace('此卡名的②③效果１回合仅可各使用１次。\r\n①：只要自己场上存在“百夫骑”怪兽卡，此卡不会因对手的效果被破坏。\r\n②：在发动了此卡的回合的自己的主要阶段，将１张手牌送至墓地可以发动。从牌组将１只“百夫骑”怪兽视为永续陷阱卡，以表侧表示放在自己的魔法与陷阱区域。\r\n③：怪兽被特殊召唤的情况下可以发动。以包含“百夫骑”怪兽在内的、自己场上的怪兽作为素材进行同步召唤。','\r',char(13)),'\n',char(10)),'','同步召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41373230,'灰烬龙 落尘劣种',replace(replace('“阿尔白斯之落胤”＋攻击力2500以上的怪兽\r\n此卡名的③效果1回合仅可使用1次。\r\n①：此卡的攻击力上升作为此卡融合素材的怪兽的原本等级合计×100的数值。\r\n②：此卡融合召唤时适用。此回合，此卡不受被从额外牌组特殊召唤的其他怪兽发动的效果影响。\r\n③：在此卡被送至墓地的回合的结束阶段可以发动。从牌组挑选1只“教导”怪兽或“阿尔白斯之落胤”，加入手牌或特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41375811,'十二兽 戌环',replace(replace('等级4怪兽×2只以上\r\n“十二兽 戌环”1回合1次，也可重叠在同名卡以外的、自己场上的“十二兽”怪兽上面来超量召唤。\r\n①：此卡的攻击力・守备力分别上升此卡持有的超量素材中“十二兽”怪兽的相应数值。\r\n②：1回合1次，去除此卡的1个超量素材，以自己墓地的1只“十二兽”怪兽为对象可以发动。将该怪兽特殊召唤。以此效果特殊召唤的怪兽在此回合，效果无效化且不可作为超量召唤的素材。','\r',char(13)),'\n',char(10)),'是否在「十二兽」怪兽上面重叠来超量召唤？','自己墓地「十二兽」怪兽特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41382147,'星见鸟拉利斯','此卡进行战斗的伤害步骤期间，此卡的攻击力上升进行战斗对手怪兽的等级×２００点。此外，此卡进行攻击的伤害步骤结束时，从游戏中除外此卡，下一个我方回合的战斗阶段开始时以攻击表示返回至我方场上。','除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41386308,'数学家','①：此卡召唤成功时可以发动。从牌组将1只等级4以下的怪兽送至墓地。②：此卡因战斗被破坏且送至墓地时可以发动。自己从牌组抽1张。','送墓','抽牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41392891,'戈兰林','喜欢恶作剧的小恶魔。会在幽暗中发动袭击。要小心！','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41396436,'苍翼羽冠','头部的毛有如王冠，苍白燃烧的鸟。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41398771,'老化的诅咒','从手牌舍弃１张卡牌。直到回合结束时，对手场上所有怪兽的攻击力、守备力下降５００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41403766,'冻原的大蝎','不在沙漠而是分布于冻原地带的罕见蓝蝎。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41406613,'暗黑界之魔神王 虹莲',replace(replace('①：此卡可通过将自己场上的1只等级7以下的“暗黑界”怪兽放回手牌，来从墓地特殊召唤。\r\n②：此卡因效果从手牌被舍弃至墓地的情况下可以发动。从牌组将除“暗黑界之魔神王 虹莲”以外的、1只等级5以上的“暗黑界”怪兽加入手牌。因对手的效果被舍弃的情况下，进而可从自己牌组・墓地将1只等级4以下的“暗黑界”怪兽特殊召唤至自己或对手场上。','\r',char(13)),'\n',char(10)),'','','是否特殊召唤？','在自己场上特殊召唤','在对手场上特殊召唤','','','','','','','','','','','');
INSERT INTO texts VALUES(41410651,'斩机刀那由他','仅可装备至电子界族怪兽。此卡名的①②效果1回合仅可各使用1次。①：装备怪兽和对手怪兽进行战斗的伤害计算时，从牌组将1只“斩机”怪兽送至墓地可以发动。装备怪兽的攻击力直至回合结束时为止，上升被送至墓地的怪兽的攻击力数值。②：此卡从魔法与陷阱区域被送至墓地的情况下，可以自己墓地的1张“斩机刀那由他”以外的“斩机”卡为对象发动。将该卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41418852,'源数网络',replace(replace('此卡名的效果①在1个回合中仅可使用1次。\r\n①：在自己的主要阶段，将1张满足发动条件的“源数”通常魔法卡从牌组送至墓地后可以发动。此效果与该魔法卡发动时的效果相同。\r\n②：去除自己场地“源数”超量怪兽的超量素材发动效果时，只要此卡存在于场地区域，不去除超量素材也可以发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41420027,'神之宣告',replace(replace('①：支付一半的LP可以发动以下效果。\r\n●发动魔法・陷阱卡时可以发动。将该发动无效并破坏。\r\n●自己或对手召唤・反转召唤・特殊召唤怪兽之际可以发动。将其无效，将该怪兽破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41420028,'神之宣告',replace(replace('①：支付一半的LP可以发动以下效果。\r\n●发动魔法・陷阱卡时可以发动。将该发动无效并破坏。\r\n●自己或对手召唤・反转召唤・特殊召唤怪兽之际可以发动。将其无效，将该怪兽破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41422426,'暗处的协力者','会在暗中偷偷协助他人的可爱小人。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41424250,'混沌终末统御者 －开辟与终焉的支配者－',replace(replace('此卡不可通常召唤。\r\n仅可在从自己墓地将战士族・光属性和恶魔族・暗属性的怪兽各1只除外的情况下特殊召唤。\r\n此卡名的③效果1回合仅可使用1次。\r\n①：此卡的特殊召唤不会被无效化。\r\n②：此卡特殊召唤成功时双方不可发动卡的效果。\r\n③：此卡是以上述方法被特殊召唤的情况下，支付1000LP可以发动。将对手场上・墓地的卡全部除外。然后，给予对手以此效果除外的数量×500的伤害。','\r',char(13)),'\n',char(10)),'','除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41426869,'幻象之仪式','①：为使合计等级达到1以上，解放自己手牌・场上的怪兽，从手牌将“纳祭魔”仪式召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41431329,'大日神械立方体','此卡被使用于同步召唤光属性怪兽并被送入墓地的场合可发动。从牌组将１张装备魔法卡加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41436536,'元素－英雄 不死鸟魔侠',replace(replace('“元素－英雄 羽毛人”＋“元素－英雄 爆炎女郎”\r\n此卡仅可以融合召唤方式特殊召唤。①：此卡不会因战斗被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41440148,'娱乐伙伴 探索河马','①：此卡召唤成功的回合，自己在通常召唤外仅可追加１次，在自己的主要阶段，将１只等级７以上怪兽以表侧攻击表示上级召唤。','使用「娱乐伙伴 探索河马」的效果召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41440817,'心太炮式','①：自己或对手的怪兽攻击宣言时，以场上的1只怪兽为对象可以发动。将该怪兽放回牌组。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41442341,'操控死灵的傀儡大师','①：此卡上级召唤成功时，可支付2000LP，以自己墓地的2只恶魔族怪兽为对象发动。将该恶魔族怪兽特殊召唤。以此效果特殊召唤的怪兽在此回合不可攻击。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41443249,'救援王牌 空中防灾机',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：从自己墓地将1张“救援王牌”卡除外可以发动。从手牌将此卡特殊召唤。\r\n②：在自己・对手回合中，自己场上存在其他“救援王牌”怪兽的情况下，以对手场上的1只效果怪兽为对象可以发动。将该怪兽改成里侧守备表示。\r\n③：此卡被送至墓地的情况下，以等级8怪兽以外的、自己除外状态的1只“救援王牌”怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41456841,'终极变态昆虫女王',replace(replace('此卡不可通常召唤，可仅限以卡牌的效果特殊召唤。\r\n①：场上存在有其他昆虫族怪兽的场合，我方场上的昆虫族怪兽不会成为对手的效果对象，不会因对手效果被破坏。\r\n②：此卡攻击的伤害步骤结束时，可解放我方场上的１只怪兽并发动。此卡可继续攻击对方怪兽。\r\n③：可在我方・对手的结束阶段发动。特殊召唤１只“昆虫怪兽衍生物”（昆虫族・地・星１・攻／守１００）至我方场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41456842,'昆虫怪兽衍生物','由“昆虫女王”等的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41458361,'魔救辉迹',replace(replace('包含同步怪兽在内的效果怪兽2只\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡连接召唤的情况下，或怪兽被特殊召唤至此卡连接端的情况下，以自己场上・墓地的1只怪兽为对象可以发动。将1只与该怪兽等级相同的“奇石衍生物”（岩石族・光・攻/守0）特殊召唤至自己场上。\r\n②：此卡以外的场上的怪兽的效果发动时可以发动。将该怪兽放回牌组最上面。','\r',char(13)),'\n',char(10)),'特殊召唤','回到牌组','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41458362,'奇石衍生物','由「魔救辉迹」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41458579,'六尺琼勾玉','①：我方场上存在有“六武众”怪兽，并且对手发动了破坏卡牌怪兽的效果、魔法、陷阱卡时可发动。使该发动无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41462083,'千岁龙','“时间魔术师”＋“宝贝龙”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41462084,'千岁龙','“时间魔术师”＋“宝贝龙”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41463181,'转生炎兽 炽热猛狮',replace(replace('炎属性效果怪兽2只以上\r\n①：此卡连接召唤的情况下，以对手的魔法与陷阱区域的1张卡为对象可以发动。将该卡放回牌组。\r\n②：此卡是以“转生炎兽 炽热猛狮”作为素材被连接召唤的情况下，1回合1次，以场上的1只表侧表示怪兽和自己墓地的1只怪兽为对象可以发动。对象的场上的怪兽的攻击力直至回合结束时为止，变为与对象的墓地的怪兽的攻击力相同。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41463182,'转生炎兽 炽热猛狮',replace(replace('炎属性效果怪兽2只以上\r\n①：此卡连接召唤的情况下，以对手的魔法与陷阱区域的1张卡为对象可以发动。将该卡放回牌组。\r\n②：此卡是以“转生炎兽 炽热猛狮”作为素材被连接召唤的情况下，1回合1次，以场上的1只表侧表示怪兽和自己墓地的1只怪兽为对象可以发动。对象的场上的怪兽的攻击力直至回合结束时为止，变为与对象的墓地的怪兽的攻击力相同。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41470137,'剑斗兽 锐枪',replace(replace('①：此卡以“剑斗兽”怪兽的效果特殊召唤的情况下，以场上的１张魔法・陷阱卡为对象发动。将该卡破坏。\r\n②：此卡进行过战斗的战斗阶段结束时，将此卡放回牌组可以发动。从牌组将“剑斗兽 锐枪”以外的１只“剑斗兽”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'破坏','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41475424,'机限炸弹','可选择我方场上１只冠有“机皇”之名的怪兽与对手场上的１张卡牌发动。破坏被选择卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41482598,'噩梦蜃楼','对手准备阶段时，从牌组抽卡直到自己有４张手牌。以此效果抽卡的情况下，在自己的下一个准备阶段时，随机挑选与抽到的相同数量的自己的手牌舍弃。','抽牌','丢弃','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41488249,'原石之号咆',replace(replace('①：宣言１个通常怪兽的卡名可以发动。此回合，因自己所宣言的通常怪兽及自己的“原石”怪兽的战斗对自己造成的战斗伤害变为０。自己场上不存在怪兽的情况下，进而可从自己牌组・墓地将１只所宣言的通常怪兽特殊召唤。\r\n②：在对手回合将墓地的此卡除外，以自己场上・墓地的１只通常怪兽为对象可以发动。获得对手场上１只攻击力高于该怪兽的怪兽的控制权，直至结束阶段为止。','\r',char(13)),'\n',char(10)),'宣言','获得控制权','是否要把宣言的怪兽特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41493640,'将棋怪兽 K桂马',replace(replace('此卡召唤成功时，可选择盖牌于对手魔法与陷阱区域的１张卡牌并发动。确认该被盖牌的卡牌，若是陷阱卡的场合，破坏该卡。若并非陷阱卡的场合，则返回原处。以此效果破坏陷阱卡时，可发动以下效果。\r\n●从手牌以守备表示特殊召唤１只地属性、等级３的怪兽。','\r',char(13)),'\n',char(10)),'破坏','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41510920,'神星之因子','①：怪兽的效果・魔法・陷阱卡发动时，将自己场上的１只表侧表示的“星骑士”怪兽送至墓地可以发动。将该发动无效并破坏。然后自己从牌组抽１张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41516133,'超巨大战舰 金属仆从',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：从手牌・牌组将最多5只等级10以下的“巨大战舰”怪兽送至墓地可以发动（同名卡最多1张）。从手牌将此卡特殊召唤。然后，依为发动此效果而送至了墓地的数量在此卡上放计数物。\r\n②：在自己・对手回合中，去除此卡的1个计数物，以包含自己场上的“巨大战舰”怪兽在内的、场上的2张表侧表示卡为对象可以发动（同一连锁上最多1次）。将该卡破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41517789,'星态龙',replace(replace('协调+1只以上协调以外的怪兽\r\n此卡只可以同步召唤方式特殊召唤。①：此卡的同步召唤不会被无效化。②：此卡同步召唤成功时，不可以发动魔法・陷阱・怪兽的效果。③：此卡攻击的情况下，直至伤害步骤结束时为止不受其他卡的效果影响。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41517968,'元素－英雄 暗辉人',replace(replace('“元素-英雄 闪光人”＋“元素-英雄 死灵暗黑人”\r\n此卡仅可以融合召唤方式特殊召唤。①：此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予战斗伤害。②：此卡攻击的情况下，在伤害步骤结束时变为守备表示。③：此卡被破坏的情况下，以对手场上的1只怪兽为对象发动。将该对手的怪兽破坏。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41522092,'翼日编号0 未来皇霍普ZEXAL',replace(replace('相同阶级的超量怪兽×2\r\n规则上，此卡的阶级视为1。\r\n①：此卡的攻击力・守备力上升自己场上及对手墓地的超量怪兽的阶级合计×500的数值。\r\n②：对手怪兽不可将其他怪兽选择为攻击对象，对手不可将场上其他卡作为效果的对象。\r\n③：1回合1次，对手在场上发动效果时，去除此卡的1个超量素材可以发动。获得对手场上的1只怪兽的控制权。此回合，此卡不会因战斗・效果被破坏。','\r',char(13)),'\n',char(10)),'','得到控制权','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41524885,'驱魔姐妹・阿索菲尔',replace(replace('等级4怪兽×2\r\n此卡名的①③效果1回合仅可各使用1次。\r\n①：此卡以“驱魔姐妹”怪兽作为素材超量召唤的情况下可以发动。此回合，双方不可发动墓地的卡的效果。\r\n②：场上的此卡不会因从墓地被特殊召唤的怪兽发动的效果被破坏。\r\n③：去除此卡的1个超量素材，以对手场上的1只怪兽为对象可以发动。将该怪兽放回手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41525660,'弈勇之忍者－南月',replace(replace('←1 【灵摆】 1→\r\n此卡名的灵摆效果１回合仅可使用１次。①：场地区域有“弈勇世界－真罗万象”存在的情况下，或自己场上有水属性的“弈勇”怪兽存在的情况下可以发动。将此卡特殊召唤至正面的自己的主要怪兽区域。\r\n【怪兽效果】\r\n此卡名的①②怪兽效果１回合仅可各使用１次。①：以此卡以外的主要怪兽区域的１只怪兽为对象可以发动。将该怪兽的位置移动至其相邻的怪兽区域。②：怪兽区域的此卡移动至其他怪兽区域的情况下，以自己的魔法与陷阱区域的１张“弈勇”怪兽卡为对象可以发动。将该卡特殊召唤至其正面的自己的主要怪兽区域。','\r',char(13)),'\n',char(10)),'请选择移动位置的怪兽','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41544074,'混沌男巫','“圣精灵”＋“黑魔族的帘布”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41554273,'机动雾龙・突击',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：从牌组将１只“机动雾龙”怪兽特殊召唤。以此效果特殊召唤的怪兽不受其他卡的效果影响，且将在结束阶段被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41562624,'不知火的武部',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡召唤时可以发动。从手牌・牌组将１只“妖刀－不知火”怪兽特殊召唤。此效果发动后，直至回合结束时为止自己仅可特殊召唤不死族怪兽。\r\n②：此卡被除外的情况下可以发动。自己抽１张。然后，自己挑选１张手牌舍弃。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41570943,'苍海龙神－超代达罗斯・狂怒',replace(replace('怪兽4只\r\n①：此卡连接召唤的情况下可以发动。从自己墓地将最多3只记载有“龙都 亚特兰蒂斯”卡名的怪兽特殊召唤至此卡连接端的自己场上。此效果发动后，直至回合结束时为止自己不可特殊召唤怪兽。\r\n②：此卡只要存在于怪兽区域，卡名视为“海”。\r\n③：在每个自己・对手回合中1次，将自己场上的1张表侧表示的“海”送至墓地可以发动。将除“海”以外的、场上的卡全部送至墓地。','\r',char(13)),'\n',char(10)),'适用作为连接3进行连接召唤（龙都 亚特兰蒂斯）','特殊召唤','送至墓地','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41578483,'千年眼纳祭魔',replace(replace('“纳祭魔”＋效果怪兽\r\n①：1回合1次，对手怪兽的效果发动时，以对手场上・墓地的1只效果怪兽为对象可以发动。将该对手的效果怪兽视为装备卡装备于此卡。②：此卡的攻击力・守备力分别上升以此卡效果装备的怪兽的相应数值。③：与以此卡效果装备的怪兽原本卡名相同的怪兽不可攻击，效果无效化。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41587307,'折断的竹光','①：装备怪兽的攻击力上升0。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41589166,'天下人 紫炎','此卡不受陷阱卡效果影响。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41613948,'命运－英雄 恶劫魔侠',replace(replace('此卡名的效果发动的回合中，自己不可攻击宣言。\r\n①：1回合1次，以对手场上的1只怪兽为对象可以发动（此效果在此卡以表侧攻击表示存在于自己场上的情况下才能发动和处理）。将该对手怪兽直至发动后的第2次自己的准备阶段为止除外。','\r',char(13)),'\n',char(10)),'除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41619242,'恐惧爪・从肆世坏的跨天',replace(replace('此卡名的卡１回合仅可发动１张。①：可从以下效果中选择１个发动。\r\n●以自己场上的１只“恐惧爪”怪兽或“维萨思・史塔弗罗斯特”、和对手场上的１只表侧表示怪兽为对象可以发动。该自己的怪兽的攻击力・守备力上升相当于该对手怪兽的攻击力和守备力中较高一方的数值。\r\n●以自己场上的“恐惧爪”怪兽或“维萨思・史塔弗罗斯特”为对象的效果发动时可以发动。将该效果无效。','\r',char(13)),'\n',char(10)),'攻守上升','效果无效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41620959,'龙之灵庙','此卡名的卡1回合仅可发动1张。①：从牌组将1只龙族怪兽送至墓地。以此效果送至墓地的怪兽是龙族的通常怪兽的情况下，可以进而再从牌组将1只龙族怪兽送至墓地。','是否再从牌组把1只龙族怪兽送至墓地？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41628550,'超重武者 鬼若－Ｏ２',replace(replace('①：此卡召唤・特殊召唤成功时可以发动。变更此卡的表示形式。\r\n②：此卡不会因战斗被破坏。','\r',char(13)),'\n',char(10)),'表示变更','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41639001,'圣刻龙－龙人努特','①：１回合１次，以场上的此卡作为对象的魔法・陷阱・怪兽的效果发动时发动。从自己的手牌・牌组・墓地挑选１只龙族通常怪兽，将其攻击力・守备力改成０并特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41659072,'炽天龙 裁决',replace(replace('协调＋协调以外的怪兽１只或以上\r\n同步召唤此卡的场合，同步素材怪兽必须全都是相同属性之怪兽。\r\n①：我方墓地存在有４种或以上的协调，且此卡被同步召唤的场合，１回合１次，可支付一半的LP发动。破坏场上除此卡以外的所有卡牌。此效果发动后，直至回合结束时，我方只可特殊召唤龙族怪兽。\r\n②：在我方结束阶段发动。从我方牌组的上方将４张卡牌除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41685633,'神雷龙',replace(replace('“雷龙”怪兽×3\r\n此卡仅可用融合召唤及以下方法特殊召唤。\r\n●将手牌1只雷族怪兽和1只“神雷龙”以外的自己场上的雷族融合怪兽除外的情况下可从额外牌组特殊召唤（无需“融合”）。\r\n①：雷族怪兽的效果在手牌发动时可以发动（伤害步骤也可以发动）。挑选场上的1张卡破坏。②：此卡将被效果破坏的情况下，作为代替可将自己墓地的2张卡除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41705642,'打捞战士','此卡上级召唤成功时，可从我方手牌、墓地挑选１只协调特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41721210,'龙骑士黑魔导',replace(replace('“黑魔导”＋龙族怪兽\r\n①：此卡只要存在于场上・墓地，卡名视为“黑魔导”。\r\n②：只要此卡存在于怪兽区域，自己场上的魔法・陷阱卡不会因对手的效果被破坏，对手不可将其作为效果的对象。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41722932,'暗黑灭绝刃','我方场上有３只以上暗属性怪兽存在的场合可发动此卡。选择场上１张表侧表示的卡牌并从游戏中除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41729254,'翼之魔妖－波旬',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将１只“翼之魔妖－波旬”以外的“魔妖”怪兽特殊召唤。\r\n②：只要此卡存在于怪兽区域，自己从额外牌组仅可特殊召唤“魔妖”怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41735184,'黑魔术之继承','此卡名的卡1回合仅可发动1张。①：从自己的墓地将2张魔法卡除外可以发动。将1张记载有“黑魔术之继承”以外的、“黑魔导”卡名或“黑魔导女孩”卡名的魔法・陷阱卡从牌组加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41739381,'机械装置作响骑士',replace(replace('连接怪兽以外的、原本攻击力为1000以下的机械族怪兽1只\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡连接召唤的情况下，将自己场上的1张表侧表示的永续魔法卡送至墓地可以发动。从牌组将1张“机械装置作响之夜”加入手牌。\r\n②：以自己墓地的1只攻击力1000以下的机械族怪兽为对象可以发动。解放自己场上的1只其他的机械族怪兽，将对象怪兽以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'检索','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41741922,'岩浆龙','①：解放守备表示的此卡可以发动。从自己的手牌・墓地分别将１只等级３以下的龙族怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41753322,'龙脚兽 腕龙','此卡不可从牌组特殊召唤。可解放我方场上的１只恐龙族怪兽来召唤此卡。此卡在１个回合中可有１次机会变为里侧守备表示。成功反转召唤此卡时，除此卡以外的所有怪兽变为里侧守备表示。对手玩家攻击此卡所受到的战斗伤害翻倍。','把1只恐龙族怪兽解放上级召唤','变成里侧守备','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41762634,'吸血跳蚤','攻击力高强的巨型吸血跳蚤，轻视它会非常危险。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41763141,'蜃欺龙',replace(replace('种族・属性相同且等级不同的怪兽×2\r\n此卡名的②效果1回合仅可使用1次。\r\n①：只要此卡存在于怪兽区域，对手不可将自己场上的融合怪兽作为效果的对象。\r\n②：此卡作为融合召唤的素材被送至墓地的情况下可以发动。从额外牌组将1只融合怪兽以守备表示特殊召唤。以此效果特殊召唤的怪兽的效果无效化，将在结束阶段放回额外牌组。此回合，自己从额外牌组仅可特殊召唤融合怪兽。','\r',char(13)),'\n',char(10)),'','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41767843,'幻奏音女 丝可娅','①：自己的“幻奏”怪兽与对手怪兽进行战斗的伤害计算时，从手牌将此卡送至墓地可以发动。该对手怪兽的攻击力・守备力直至回合结束时为止变为０。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41773061,'Voici la Carte～请看菜单～',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：从牌组将卡名不同的２只“饿魔新飨”怪兽出示给对手，对手从其中挑选１只。将该１只怪兽加入自己的手牌，剩余的放回牌组。然后，根据以此效果加入手牌的怪兽的种族，可从自己的牌组・墓地将以下的１张卡加入手牌。\r\n●兽战士族：“Recette de Poisson～鱼料理食谱～”\r\n●战士族：“Recette de Viande～肉料理食谱～”','\r',char(13)),'\n',char(10)),'','是否再选对应的卡加入手牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41782653,'超顶风神翼龙','此卡不可通常召唤。仅可在将自己被除外的５只恐龙族怪兽放回牌组的情况下特殊召唤。此卡名的②效果１回合仅可使用１次。①：１回合１次，对手发动魔法・陷阱卡时可以发动。挑选自己手牌・场上的１只恐龙族怪兽破坏，将该发动无效并破坏。②：此卡因效果被送至墓地的情况下可以发动。从牌组将１张“进化药”魔法卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41788781,'极星兽 古尔法克西','对手场上存在有同步怪兽，且我方场上不存在有怪兽的场合，此卡可以从手牌特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41790641,'电力王国',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：对手不可发动位于此卡及自己场上“电力”怪兽正面的、对手怪兽自身的召唤・特殊召唤成功时的效果。\r\n②：以自己场上的１只“电力”怪兽为对象可以发动。从牌组将１只卡名与该怪兽不同的“电力”怪兽特殊召唤。然后，自己失去相当于以此效果特殊召唤的怪兽的攻击力数值的LP。此效果发动后，直至回合结束时为止，自己仅可特殊召唤雷族怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41802073,'弈勇－伏特子爵',replace(replace('←1 【灵摆】 1→\r\n此卡名的灵摆效果１回合仅可使用１次。①：在自己的主要阶段可以发动。将此卡特殊召唤至正面的自己的主要怪兽区域。此效果发动后，直至回合结束时为止自己仅可特殊召唤“弈勇”怪兽（除了从额外牌组的特殊召唤以外）。\r\n【怪兽效果】\r\n此卡名的①②怪兽效果１回合仅可各使用１次。①：此卡是被特殊召唤的情况下，在自己的主要阶段可以发动。从自己的额外牌组挑选１只表侧表示的“弈勇”灵摆怪兽，视为永续魔法卡，以表侧表示放在自己的魔法与陷阱区域。②：怪兽区域的此卡移动至其他怪兽区域的情况下可以发动。从自己的额外牌组挑选１只表侧表示的“弈勇”灵摆怪兽，放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41803903,'魔界剧本“浪漫语者”','此卡名的卡1回合仅可发动1张。①：挑选自己场上的1只“魔界剧团”灵摆怪兽放回持有者的手牌，从自己的额外牌组将1只原本卡名和放回手牌的怪兽不同的表侧表示“魔界剧团”灵摆怪兽以守备表示特殊召唤。②：在自己的额外牌组有表侧表示的“魔界剧团”灵摆怪兽存在、被放置的此卡因对手的效果被破坏的情况下可以发动。从牌组挑选任意数量的“魔界剧本”魔法卡放置在自己的魔法与陷阱区域。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41830887,'复写机块 复印小矮人',replace(replace('此卡名的效果①②在1个回合中仅可各使用1次。\r\n①：可以以自己场上的1只“机块”怪兽为对象发动。从手牌中特殊召唤此卡。此效果特殊召唤的此卡作为对象怪兽的同名卡使用，直至结束阶段为止。\r\n②：除外墓地中的此卡后，可以以自己场上的1只“机块”怪兽为对象发动。从自己的手牌、墓地选择1只该怪兽的同名怪兽特殊召唤。此效果在此卡被送至墓地的回合不可发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41850466,'源数混沌仪式','①：自己场上表侧表示的“混沌编号1 混沌源数之门－零”因怪兽的效果被破坏的回合，从自己墓地的卡及自己被除外的卡中，以１张“源数网络”和４只“编号”超量怪兽为对象可以发动。从额外牌组将１只“混沌编号1000 梦幻虚神 原数天灵”改成攻击力１００００／守备力１０００并特殊召唤，将５张对象卡作为其超量素材。此效果发动后，直至回合结束时为止，自己仅可召唤・特殊召唤怪兽１次。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41855169,'升灵术师 奘玄','随机舍弃１张手牌至墓地可以发动。破坏场上的所有被特殊召唤的怪兽。此外，只要此卡表侧表示存在于场上，双方不可特殊召唤怪兽。','特殊召唤的怪兽全部破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41858121,'大日神械物体',replace(replace('可选择我方墓地的３张装备魔法卡并发动。将被选择的３张卡牌加入牌组并洗牌。之后，可从以下效果中挑选１个适用。\r\n●从我方牌组抽取１张卡牌。\r\n●挑选对手场上的１张卡牌并破坏。','\r',char(13)),'\n',char(10)),'从自己牌组抽1张卡。','对手场上存在的1张卡破坏。','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41859700,'燃烧海藻','此卡被送入墓地的场合发动。对手回复１０００LP。','回复','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41867019,'魔妖游行',replace(replace('此卡名的①效果在同一连锁上仅可发动１次。\r\n①：不死族同步怪兽被从额外牌组以外特殊召唤的情况下可以发动（在伤害步骤也可以发动）。从以下效果中挑选１个适用。此回合，不可以自己的“魔妖游行”的效果适用相同效果。\r\n●自己抽１张。\r\n●从牌组将“魔妖游行”以外的１张“魔妖”魔法・陷阱卡放置在自己场上。\r\n●将对手场上攻击力最低的１只怪兽送至墓地。\r\n●给予对手８００伤害。','\r',char(13)),'\n',char(10)),'抽1张卡','放置魔陷','送至墓地','800伤害','','','','','','','','','','','','');
INSERT INTO texts VALUES(41872150,'蝗虫军势','此卡在１个回合中可有１次机会变为里侧守备表示。成功反转召唤此卡时，选择对手场上的１张魔法・陷阱卡并将其破坏。','变成里侧守备表示','破坏对手1张魔法·陷阱卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41902352,'黑羽－黎明的东风','被特殊召唤的此卡不可作为同步素材。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41908872,'霸王眷龙 光明亚龙',replace(replace('←8 【灵摆】 8→\r\n此卡名的灵摆效果１回合仅可使用１次。\n①：怪兽被特殊召唤的情况下，如果自己场上存在“霸王龙扎克”、且还另外存在一只灵摆怪兽则可以发动。将此卡特殊召唤。然后，可将自己场上的１只灵摆怪兽和此卡中的１只的等级・属性改成和另１只相同。\r\n【怪兽效果】\r\n此卡名的①②怪兽效果１回合仅可各使用１次。\n①：此卡召唤・特殊召唤的情况下可以发动。从自己的额外牌组（表侧）将１只“霸王眷龙”灵摆怪兽或“霸王门”灵摆怪兽加入手牌。然后，可进行１只“霸王眷龙”同步怪兽的同步召唤或１只“霸王眷龙”超量怪兽的超量召唤。\n②：此卡以表侧存在于额外牌组的状态下，自己场上的表侧表示灵摆怪兽因战斗・效果被破坏的情况下可以发动。将此卡加入手牌。','\r',char(13)),'\n',char(10)),'此卡特殊召唤','','此卡加入手牌','是否改变怪兽的属性·等级？','请选择要改变的怪兽','是否同步或超量召唤？','','','','','','','','','','');
INSERT INTO texts VALUES(41916534,'铁汉斯',replace(replace('此卡牌名的①效果１回合只可使用１次。\r\n①：此卡召唤、反转召唤、特殊召唤成功的场合可发动。从牌组特殊召唤１只“铁之骑士”怪兽。此效果处理时，场地区不存在有“急流山的金宫”的场合，直至回合结束时，我方不可从额外牌组特殊召唤怪兽。\r\n②：场地区存在有“急流山的金宫”的场合，此卡的攻击力上升我方场上的“铁之骑士”数量×１０００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41924516,'白森的魔狼 西尔维亚',replace(replace('协调＋协调以外的怪兽１只以上\r\n①：此卡特殊召唤的情况下可以发动。将对手场上的表侧表示怪兽全部改成里侧守备表示。\r\n②：只要此卡存在于怪兽区域，自己场上的幻想魔族・魔法师族同步怪兽的攻击力上升５００，攻击了守备表示怪兽的情况下，依其守备力超过攻击力的数值的两倍来给予对手战斗伤害。','\r',char(13)),'\n',char(10)),'变成里侧','攻击力上升并贯通','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41925941,'冥王的咆哮','我方场上的恶魔族怪兽进行战斗的伤害步骤时，可支付１００的倍数的LP发动。选择１只进行攻击的对手怪兽，直至回合结束时，该攻击力、守备力下降相当于支付的数值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41927278,'脆刃之剑','①：“脆刃之剑”在自己场上仅可有１张以表侧表示形式存在。②：装备怪兽的攻击力上升２０００，因装备怪兽的战斗发生的战斗伤害由双方玩家承受。③：自己受到２０００以上的战斗伤害的情况下发动。将此卡送至墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41930553,'暗黑的瘴气','①：1回合1次，以对手墓地的1只怪兽为对象可以发动。从手牌挑选1只恶魔族怪兽舍弃，将对象怪兽除外。','是否现在使用「暗黑烟雾」的效果？','丢弃手牌并除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41933425,'接触之门','此卡名的卡１回合仅可发动１张。①：从自己的墓地将２种“新空间人”怪兽各１只除外可以发动。从自己的手牌・牌组・墓地挑选２只“新空间人”怪兽特殊召唤（同名卡最多１张）。此效果发动过的余下本回合，自己从额外牌组仅可特殊召唤融合怪兽。②：自己场上表侧表示的、以“元素－英雄 新宇侠”作为融合素材的融合怪兽被放回额外牌组的情况下，将墓地的此卡除外可以发动。挑选１只自己被除外的“新空间人”怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41940225,'破坏剑士融合',replace(replace('“破坏剑士融合”的①②效果１回合各只可使用１次。\r\n①：从我方的手牌以及我方、对手场上将根据融合怪兽卡所指定的融合素材怪兽送入墓地，从额外牌组融合召唤１只以“毁灭剑士”作为融合素材的融合怪兽。\r\n②：此卡存在于墓地的场合，可将１张手牌送入墓地并发动。将墓地的此卡加入手牌。','\r',char(13)),'\n',char(10)),'融合召唤','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41949033,'暗之暗杀者','手持一把被称作精神之剑的剑，是一名君临魔界的暗杀者。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41952656,'小海豚','场上的此卡因对手被破坏并送入墓地时，将我方牌组最上方的卡牌送入墓地。被送入墓地的卡牌为水属性怪兽的场合，从我方牌组中抽取１张卡牌。','牌组送墓','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41978142,'霞之谷的执行者','此卡召唤成功时，将场上所有以表侧表示存在的魔法、陷阱卡返回至持有者手牌。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(41999284,'连接库里波',replace(replace('等级1怪兽1只\r\n此卡名的②效果1回合仅可使用1次。\r\n①：对手怪兽攻击宣言时，解放此卡可以发动。该对手怪兽的攻击力直至回合结束时为止变为0。\r\n②：在自己・对手回合中，此卡存在于墓地的情况下，解放自己场上的1只等级1怪兽可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42002073,'娱乐伙伴扑克女孩',replace(replace('←4 【灵摆】 4→\r\n【怪兽效果】\r\n①：１回合１次，在我方主要阶段可发动。将由融合怪兽卡规定之包含此卡在内的融合素材怪兽从我方场上送入墓地，从额外牌组融合召唤１只该融合怪兽。\n②：此卡在灵摆区被破坏的场合，可以我方墓地的１只龙族融合怪兽为对象发动。特殊召唤该怪兽。以此效果特殊召唤而来的怪兽在结束阶段被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42006475,'守护神官 玛娜',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：此卡存在于手牌・墓地，仅以自己场上的１只魔法师族怪兽为对象的对手的魔法・陷阱・怪兽的效果发动时可以发动。将此卡特殊召唤。\r\n②：只要此卡存在于怪兽区域，自己场上的等级７以上的魔法师族怪兽不会因效果被破坏。\r\n③：此卡因战斗・效果被破坏的情况下可以发动。从自己的手牌・牌组・墓地挑选１只“黑魔导女孩”特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42009836,'化石恐龙 肿头龙',replace(replace('①：此卡反转的情况下发动。将场上被特殊召唤的怪兽全部破坏。\r\n②：只要此卡存在于怪兽区域，双方不可特殊召唤怪兽。','\r',char(13)),'\n',char(10)),'特殊召唤的怪兽全部破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42015635,'新宇空间','①：只要此卡存在于场地区域，“元素－英雄 新宇侠”及以“元素－英雄 新宇侠”为融合素材的融合怪兽的攻击力上升５００。②：只要此卡存在于场地区域，以“元素－英雄 新宇侠”为融合素材的融合怪兽在结束阶段，可以不发动放回额外牌组的效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42021064,'机动石器 土偶罗多',replace(replace('包含岩石族怪兽在内的怪兽2只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡特殊召唤的情况下，以自己墓地的1只岩石族怪兽为对象可以发动。此卡的攻击力上升相当于对象怪兽攻击力的数值。\r\n②：在对手的主要阶段，以场上1只攻击力在此卡的攻击力以下的其他怪兽为对象可以发动。此卡的攻击力下降相当于对象怪兽的攻击力的数值，将对象怪兽破坏。','\r',char(13)),'\n',char(10)),'攻击力上升','攻击力下降并破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42023223,'电磁石战士阿尔法',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将1只等级8的“磁石之战士”怪兽加入手牌。\r\n②：在对手回合中，解放此卡可以发动。从牌组将1只等级4的“磁石战士”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'加入手牌','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42024143,'XX－军刀 突击守卫','①：自己墓地存在2只以上“X－军刀”怪兽，且自己场上不存在怪兽的情况下，此卡可从手牌特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42029847,'幻奏音女 塞雷娜',replace(replace('①：上级召唤天使族怪兽的情况下，此卡可作为２只解放。\r\n②：此卡特殊召唤时适用。此回合自己除通常召唤外仅可追加１次，在自己的主要阶段召唤１只“幻奏”怪兽。','\r',char(13)),'\n',char(10)),'使用「幻奏音女 塞雷娜」的效果召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42035044,'漆黑的豹战士','①：此卡的攻击宣言之际，自己必须解放自己场上的1只其他的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42035045,'漆黑的豹战士','①：此卡的攻击宣言之际，自己必须解放自己场上的1只其他的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42052439,'取火女郎','此卡名的①②效果１回合仅可各使用１次。①：自己场上有战士族怪兽存在的情况下可以发动。从手牌将此卡特殊召唤。②：将场上的此卡送至墓地可以发动。从手牌将１只等级４以下的战士族怪兽特殊召唤。以此效果特殊召唤的怪兽在此回合不会成为对手效果的对象。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42055234,'龙女仆・弗燃梅',replace(replace('此卡名的①③效果1回合仅可各使用1次。\r\n①：在自己・对手回合中，从手牌将此卡舍弃，以自己场上的1只“龙女仆”怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止上升2000。\r\n②：只要自己场上存在融合怪兽，此卡就不会因效果被破坏。\r\n③：在自己・对手的战斗阶段结束时可以发动。将此卡放回手牌，从手牌将1只等级3的“龙女仆”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42071342,'暗黑海龙兵','守护暗黑之海的战士。在水中的战斗力毋庸置疑，即使是在陆地上也拥有很高的战斗能力。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42079445,'陨星坠落','①：可以我方墓地的１只同步怪兽为对象发动。将该怪兽的等级下降１级，使守备力变成０并以守备表示特殊召唤。以此效果特殊召唤的怪兽的效果被无效化，且不可变更表示形式。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42081767,'粗心藏果松鼠',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己・对手的主要阶段，以自己墓地最多3张魔法・陷阱卡为对象可以发动。将该卡除外。在下回合的结束阶段，将以此效果被除外的卡放回牌组。\r\n②：在自己的准备阶段，以自己除外状态的1张魔法・陷阱卡为对象可以发动。将该卡放置在自己场上。','\r',char(13)),'\n',char(10)),'除外','放置','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42082363,'薰风・狮鹫','此卡从手牌被送入墓地的场合，可从牌组特殊召唤１只冠有“薰风”之名的怪兽。“薰风・狮鹫”的效果１回合只可使用１次。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42090294,'爬虫妖・尼亚米尼','此卡名的①②效果１回合１次，仅可使用其中１个。①：自己的墓地存在爬虫类族怪兽的情况下，在自己・对手的主要阶段，将此卡从手牌送至墓地，以对手场上的１只表侧表示怪兽为对象可以发动。将该怪兽的攻击力改成０。②：对手场上存在攻击力０的怪兽的情况下可以发动。从墓地将此卡特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42091632,'命主王之螺旋',replace(replace('此卡名的卡1回合仅可发动1张。\r\n对手发动过手牌・墓地的怪兽的效果的回合，此卡也可从手牌发动。\r\n①：以对手场上的1只怪兽为对象可以发动。将该怪兽放回手牌・额外牌组。自己墓地不存在陷阱卡的情况下，对手进而可从自身墓地将1只怪兽特殊召唤。从手牌发动此卡的情况下，发动后，此决斗中自己不可发动光・暗属性怪兽的效果。','\r',char(13)),'\n',char(10)),'回到手牌·额外牌组','适用「命主王之螺旋」的效果从手牌发动','是否特殊召唤？','「命主王之螺旋」效果适用中','','','','','','','','','','','','');
INSERT INTO texts VALUES(42097666,'青之眼精灵',replace(replace('等级４以下的龙族・魔法师族怪兽１只\r\n此卡名的①③效果１回合仅可各使用１次。\r\n①：此卡连接召唤的情况下可以发动。从牌组挑选１张“光之灵堂”，加入手牌或送至墓地。\r\n②：只要此卡存在于怪兽区域，自己仅可特殊召唤龙族怪兽。\r\n③：解放此卡可以发动。从自己手牌・墓地将１只“青眼”怪兽特殊召唤。以此效果从墓地特殊召唤的效果怪兽不可攻击，效果无效化。','\r',char(13)),'\n',char(10)),'检索','','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42104806,'希望之天启',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：将自己场上1只表侧表示的龙族・等级8怪兽送至墓地可以发动。从额外牌组将1只龙族・阶级8的超量怪兽视为超量召唤特殊召唤。','\r',char(13)),'\n',char(10)),'发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42110434,'大植然蝴蝶','①：１回合１次，对手怪兽攻击宣言时可以发动。将自己的牌组最上面的卡送至墓地，将该攻击无效。','攻击无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42110604,'高速疾行机人 剑剧骑手',replace(replace('协调+1只以上协调以外的怪兽\r\n自己1回合仅可特殊召唤1次“高速疾行机人 剑剧骑手”。①：此卡在1次战斗阶段中可以攻击2次。②：此卡进行战斗的伤害步骤开始时发动。此卡的攻击力上升200。③：此卡被送至墓地的情况下，以自己1张被除外的“疾行机人”卡为对象可以发动。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'攻击上升','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42125140,'星宿钳龙 夏乌拉斯',replace(replace('“星宿”怪兽＋手牌的怪兽\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：以自己墓地的2张“星宿”卡和与其中的任意种类（怪兽・魔法・陷阱）相同的场上的1张表侧表示卡为对象可以发动。将该3张卡放回牌组。\r\n②：此卡存在于墓地的状态下，有2只以上的怪兽同时被送至墓地的情况下可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'回牌组','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42129512,'巨大考拉','一种非常巨大的死亡考拉。性格温顺，但力量异常强大，使众人恐惧。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42138622,'时光漩涡',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：自己场上存在不死族怪兽及“活死人的呼唤”，且对手发动怪兽或通常・速攻魔法卡的效果时可以发动。对手掷1次硬币，根据掷出的正反，该效果变为以下效果。\r\n●正面：“对手必须将自身场上的1只怪兽除外”\r\n●反面：“自己必须将自己场上的怪兽全部除外”','\r',char(13)),'\n',char(10)),'发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42141493,'多多迷宝・软绵雀精',replace(replace('发动此卡的效果的回合中，自己仅可发动1次此卡以外的“多多迷宝”怪兽的效果。\r\n①：在自己・对手回合中，自己场上不存在卡的情况下，从手牌将此卡舍弃可以发动。在此回合中适用以下效果。\r\n●对手每次从牌组・额外牌组将怪兽特殊召唤，自己抽1张。\r\n●在结束阶段，自己手牌多于对手场上的卡的数量＋6张的情况下，依其数量差将自己手牌随机放回牌组。','\r',char(13)),'\n',char(10)),'抽牌&手牌回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42143067,'怒气土器','此卡名的效果1回中仅可使用1次。①：从手牌扔掉1只岩石族怪兽后可以发动。将原本的属性・等级和该怪兽相同的1只岩石族怪兽从牌组以表侧攻击表示或者里侧守备表示形式进行特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42149850,'一次性学习装置',replace(replace('此卡牌名的②效果１回合只可使用１次。\r\n①：装备怪兽的攻击力上升我方墓地怪兽数量×２００。\r\n②：此卡从场上被送入墓地回合的结束阶段可发动。将此卡盖牌至我方场上。以此效果盖牌的此卡从场上离开的场合被除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42155488,'基因组斗士','此卡可无须释放召唤。以此方法召唤的此卡的等级变成３，原本攻击力减半。此外，１回合１次，可宣言１个种族并发动。此回合以此卡为同步素材的场合，含此卡在内的该一组同步素材怪兽被视为被宣言种族。发动此效果的回合，我方只可召唤、特殊召唤被宣言种族的怪兽。','不用解放作召唤','素材变换','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42158279,'教导拟剧','此卡名的①②效果１回合１次，仅可使用其中１个。①：为使合计等级与仪式召唤的怪兽相等，解放自己场上的、“教导”怪兽或仪式・融合・同步怪兽，从手牌・牌组将１只“教导”仪式怪兽仪式召唤。②：将墓地的此卡除外，以自己墓地等级不同的２只“教导”怪兽为对象可以发动。将该２只怪兽中的１只加入手牌，另１只放回牌组最下面。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42160203,'霸王眷龙 暗反叛',replace(replace('暗属性等级４的灵摆怪兽×２\r\n①：１回合１次，此卡与对手怪兽进行战斗的伤害计算前，去除此卡的１个超量素材可以发动。直至回合结束时为止，将该对手怪兽的攻击力改成０，此卡的攻击力上升该原本攻击力的数值。\r\n②：在自己・对手的战斗阶段，将此卡放回额外牌组可以发动。从自己的额外牌组（表侧）将“霸王眷龙”灵摆怪兽或“霸王门”灵摆怪兽合计最多２只以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'攻击力上升','回到牌组并特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42166000,'神・史莱姆',replace(replace('水族怪兽＋水属性・等级１０怪兽\r\n此卡从额外牌组仅可通过融合召唤及以下方法特殊召唤。\r\n●解放自己场上１只攻击力０的水族・等级１０怪兽的情况下，可从额外牌组特殊召唤。\r\n①：上级召唤需要解放３只以上怪兽的怪兽的情况下，此卡可作为３只解放。\r\n②：此卡不会因战斗被破坏，对手怪兽不可将自己场上“神・史莱姆”以外的怪兽选择为攻击对象，对手不可将其作为效果的对象。','\r',char(13)),'\n',char(10)),'使用「神・史莱姆」作为3只的数量解放来召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42167046,'阔剑式未爆弹','可选择２只以表侧表示存在于场上的怪兽并发动此卡。被选择怪兽从场上离开时，破坏此卡。此卡被破坏时，破坏被选择怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42172465,'创星改归','此卡名的卡1回合仅可发动1张。①：从手牌・牌组将1只“星遗物”怪兽特殊召唤。以此效果特殊召唤的怪兽将在下个回合的结束阶段被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42175079,'大喷火','我方场上存在有“侏罗纪世界”的场合，可在我方结束阶段时发动。破坏场上的所有卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42193638,'华耳琴璃・倾注',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：从以下效果中挑选１个适用。自己的灵摆区域不存在“华耳琴璃”卡的情况下，要适用的效果由对手挑选。\r\n●自己恢复５００LP。然后，可从自己的牌组上面翻开卡，直至翻到“华耳琴璃”卡为止。该情况下，将所翻到的“华耳琴璃”卡加入手牌，剩余的卡放回牌组。\r\n●自己受到５００伤害。然后，可从牌组将“华耳琴璃・倾注”以外的１张“华耳琴璃”卡送至墓地。','\r',char(13)),'\n',char(10)),'','自己回复500基本分','自己受到500伤害','是否从牌组翻卡？','是否从牌组把卡送至墓地？','','','','','','','','','','','');
INSERT INTO texts VALUES(42198835,'外法的骑士','此卡名的①②效果１回合仅可各使用１次。①：自己场上不存在怪兽的情况下，或存在“勇者衍生物”的情况下，在自己・对手的主要阶段可以发动。从手牌将此卡特殊召唤。②：自己场上存在“勇者衍生物”的情况下，以对手场上的最多２张卡为对象可以发动。将此卡的控制权转移给对手，将对象卡放回持有者的手牌。此效果在对手回合中也可以发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42199039,'妖刀竹光',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：装备怪兽的攻击力上升0。\r\n②：以自己场上的1张其他“竹光”卡为对象可以发动。将该卡放回手牌，装备怪兽此回合可直接攻击。\r\n③：此卡被送至墓地的情况下可以发动。从牌组将“妖刀竹光”以外的1张“竹光”卡加入手牌。','\r',char(13)),'\n',char(10)),'回到手牌','牌组检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42201897,'圣徒・棘路',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：将额外牌组的１只“圣徒”融合怪兽出示给对手，其等级每有４，就将自己墓地・除外状态的１张“罪宝”卡放回牌组。然后，将所出示的怪兽视为融合召唤特殊召唤。\r\n②：将墓地的此卡除外，以自己墓地的１张“罪宝”魔法・陷阱卡为对象可以发动。将该卡放置在自己场上。以此效果放置的卡此回合不可发动。','\r',char(13)),'\n',char(10)),'特殊召唤','放置','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42209438,'真魔六武众－鬼斩',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的②③效果1回合仅可各使用1次。\r\n①：自己场上的“六武众”怪兽的攻击力・守备力仅在战斗阶段期间上升600。\r\n②：在对手的主要阶段，从自己墓地将1张“六武式”卡除外，以场上的1张卡为对象可以发动。将该卡破坏。\r\n③：自己场上存在2只以上“六武众”怪兽的情况下可以发动。从墓地将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','破坏','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42216237,'杰拉的天使',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的②效果1回合仅可使用1次。\r\n①：此卡的攻击力上升对手除外状态的卡的数量×100的数值。\r\n②：此卡被除外的下个回合的准备阶段发动。将除外状态的此卡特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42228966,'战场的惨剧',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：在怪兽之间未进行战斗的回合的自己的主要阶段２，舍弃１张手牌可以发动。从牌组挑选１张“战场的惨剧”，放置在自己的魔法与陷阱区域。\r\n②：在怪兽之间进行了战斗的回合的结束阶段发动。回合玩家从自身的牌组上面将５张卡送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42230449,'编号2源数之门－贰',replace(replace('等级1的怪兽×3\r\n①：此卡在战斗中不会被破坏。\r\n②：此卡与对手怪兽进行战斗的伤害步骤结束时，去除此卡的1个超量素材后可以发动。自己场上的所有“源数”怪兽的攻击力翻倍，直至回合结束时为止。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42233477,'野蛮人之怒','①：可以我方场上的１只战士族怪兽为对象发动。该怪兽的攻击力上升１０００点，该怪兽因战斗破坏的怪兽不送入墓地而返回至持有者手牌。对象怪兽从场上离开时此卡被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42237854,'机动要塞 钢铁堡垒',replace(replace('①：可以我方场上任意数量的机械族、等级４怪兽为对象发动。此卡发动后成为效果怪兽（机械族、地、星４、攻／守０），并特殊召唤至怪兽区。之后，对象的表侧表示怪兽被视为装备卡装备此卡。此卡也被视为陷阱卡。\r\n②：以此卡的效果特殊召唤而来的此卡的攻击力上升，其数值相当于因此卡效果装备的怪兽的攻击力合计值，对手不可以其他我方场上的怪兽为攻击对象、效果对象。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42239546,'茧状体・小鼹鼠','可解放此卡并发动。从手牌・牌组特殊召唤１只“新空间人 大地鼹鼠”怪兽。场上存在有“新宇空间”的场合，此卡的效果可发动与处理。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42256406,'卡片防卫士','此卡召唤、反转召唤、特殊召唤成功时，变成守备表示。我方场上的表侧表示怪兽被选择为攻击对象时，可将攻击对象变成此卡。此卡成为攻击对象时，可从我方牌组上方将最多３张卡牌送入墓地并发动。此卡的守备力上升相当于直至回合结束时送入墓地的卡牌数×５００点。','变成守备表示','改变攻击对象','守备上升','请选择要送至墓地的卡的数量','','','','','','','','','','','','');
INSERT INTO texts VALUES(42280216,'太阳的神官',replace(replace('①：仅有对手场上才存在怪兽的情况下，此卡可从手牌中特殊召唤。\r\n②：场上的此卡被破坏并被送至墓地时可以发动。从牌组将１只“赤蚁 阿斯卡托尔”或“苏帕伊”加入手牌。','\r',char(13)),'\n',char(10)),'检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42291297,'花札卫－雨四光',replace(replace('协调＋３只协调以外的怪兽\r\n①：只要此卡存在于怪兽区域，自己场上的“花札卫”怪兽不会因效果被破坏，不会成为对手效果的对象。\r\n②：对手在对手的抽牌阶段通常抽牌的情况下发动。给予对手１５００伤害。\r\n③：在对手的结束阶段，从以下效果中选择１个发动。\r\n●跳过下一个自己回合的抽牌阶段。\r\n●将此卡的效果直至下一个对手的　准备阶段　为止无效。','\r',char(13)),'\n',char(10)),'给与对手1500伤害','下次的自己回合的抽牌阶段跳过','此卡的效果直到下次的对手准备阶段无效','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42302563,'狱花之大煌耀圣 斯特莉西亚',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的②效果1回合仅可使用1次。\r\n①：只要此卡存在于中央的主要怪兽区域，原本攻击力变为3000。\r\n②：在自己・对手的主要阶段可以发动。从自己手牌・墓地将1只等级6以下的“耀圣”怪兽特殊召唤。然后，可将场上的所有等级4以上的怪兽的等级直至回合结束时为止下降3。此回合，自己从额外牌组仅可特殊召唤同步怪兽。','\r',char(13)),'\n',char(10)),'特殊召唤','是否下降等级？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42303365,'爬虫妖・毒蛇','①：此卡召唤成功时，以对手场上的1只攻击力0的怪兽为对象可以发动。获得该攻击力为0的怪兽的控制权。','获得控制权','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42307760,'蕾祸之大王鬼牙',replace(replace('昆虫族・植物族・爬虫类族怪兽２只以上\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：怪兽被从对手的牌组・额外牌组特殊召唤的情况下可以发动。将场上的２只怪兽破坏。\r\n②：此卡存在于墓地的情况下，以自己场上的１只昆虫族・植物族・爬虫类族怪兽为对象可以发动。将该怪兽放回牌组最下面，将此卡特殊召唤。此回合，自己仅可特殊召唤昆虫族・植物族・爬虫类族怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42309337,'反击反击','反制陷阱卡发动时可发动。使该发动无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42314669,'完全防音壁','同步怪兽不以表侧表示存在于我方场上的场合，在主要阶段１的开始时可发动。直至对手回合结束时，双方不可特殊召唤同步怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42328171,'发条蝙蝠','我方主要阶段时可发动。将我方场上表侧攻击表示的此卡变成表侧守备表示，并从我方墓地选择１只冠有“发条”之名的怪兽加入手牌。只要此卡以表侧表示存在于场上，此效果只可使用１次。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42338879,'喔喔公鸡',replace(replace('①：双方场上不存在怪兽的情况下，此卡可作为等级3怪兽从手牌特殊召唤。\r\n②：对手场上存在怪兽，且自己场上不存在卡的情况下，此卡可作为等级4怪兽从手牌特殊召唤。\r\n③：表侧表示的此卡从场上离开的情况下将被除外。','\r',char(13)),'\n',char(10)),'作为3星怪兽特殊召唤','作为4星怪兽特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42348802,'糙齿龙','虎纹恐龙。穿越荒野的速度极快。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42352091,'源数壁',replace(replace('此卡名的效果①在1个回合中仅可使用1次。\r\n①：自己场上不存在“源数壁”以外的卡时，将手牌或场上的此卡送至墓地后可以发动。从手牌、牌组中选择1张“源数网络”卡发动。此效果在对手回合中也可以发动。\r\n②：自己受到了战斗伤害时可以发动。从手牌中特殊召唤此卡，在该伤害步骤结束后，结束战斗阶段。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42364257,'避雷针','当对手使用“雷击”时，破坏对手所有怪兽来代替我方的怪兽。发动后此卡将被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42364374,'武装苍蝇','如果我方场上除了此卡以外无昆虫族怪兽存在，此卡的攻击力、守备力各变为１０００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42377643,'海胆军贯',replace(replace('此卡名的①②效果１回合仅可各使用１次。①：向对手出示此卡以外的手牌的１张“军贯”卡可以发动。从手牌将此卡特殊召唤。然后，根据所出示的卡，适用以下效果。\r\n●“舍利军贯”：可将出示的怪兽特殊召唤。\r\n●该卡以外：将所出示的卡放回牌组最下面。\r\n②：以自己场上的１只“军贯”怪兽为对象可以发动。将该怪兽的等级改成４或５。然后，可从牌组将１只“舍利军贯”加入手牌。','\r',char(13)),'\n',char(10)),'','','是否把把给人观看的怪兽特殊召唤？','变成4星','变成5星','是否从牌组把「舍利军贯」加入手牌？','','','','','','','','','','');
INSERT INTO texts VALUES(42378577,'灵摆切换',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：以自己灵摆区域的１张卡为对象可以发动。将该卡特殊召唤。\r\n②：以自己的怪兽区域的１只灵摆怪兽为对象可以发动。将该灵摆怪兽放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'灵摆区域怪兽特殊召唤','灵摆怪兽在灵摆区域放置','请选择要放置到灵摆区域的卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42382265,'DD 刻度测量员',replace(replace('←9 【灵摆】 9→\r\n此卡名的灵摆效果1回合仅可使用1次。\n①：在自己・对手的准备阶段，以自己・对手的灵摆区域的最多2张卡为对象可以发动。将该卡的灵摆刻度直至回合结束时为止改成0。\r\n【怪兽效果】\r\n此卡名的①②③怪兽效果1回合仅可各使用1次。\n①：自己场上存在“DD”灵摆怪兽卡的情况下可以发动。从手牌将此卡特殊召唤。\n②：此卡召唤・特殊召唤的情况下可以发动。将此卡的等级改成4。\n③：此卡被送至墓地的情况下，或以表侧加入额外牌组的情况下，以自己场上的1张“DD”灵摆怪兽卡为对象可以发动。将该卡放回手牌。','\r',char(13)),'\n',char(10)),'改变刻度','特殊召唤','改变等级','回到手牌','','','','','','','','','','','','');
INSERT INTO texts VALUES(42386471,'卡通双生精灵',replace(replace('①：此卡在召唤・反转召唤・特殊召唤的回合不可攻击。\r\n②：自己场上存在“卡通世界”，且对手场上不存在卡通怪兽的情况下，此卡可直接攻击。\r\n③：此卡给予对手战斗伤害时可以发动。随机舍弃对手的1张手牌。\r\n④：场上的“卡通世界”被破坏时，此卡将被破坏。','\r',char(13)),'\n',char(10)),'丢弃手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42388271,'星遗物－星柜－','此卡名的①③效果1回合仅可各使用1次。①：自己场上的连接怪兽因对手的效果被破坏并被送至自己墓地的情况下，将此卡从手牌送至墓地，以1只该连接怪兽为对象可以发动。将该怪兽特殊召唤。②：将怪兽上级召唤的情况下，此卡可作为2只解放。③：通常召唤的此卡存在于怪兽区域，对手从额外牌组将怪兽特殊召唤的情况下可以发动。从牌组将1只怪兽送至墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42391240,'星圣 天蝎安塔雷斯','①：此卡召唤・特殊召唤时，以自己墓地的1只“星圣”怪兽为对象可以发动。将该怪兽加入手牌。','加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42396591,'混沌编号104 假面魔蹈士 黑影・胜利',replace(replace('等级5怪兽×4\r\n①：在每个自己・对手回合中1次，去除此卡的1个超量素材，以对手场上的1张卡为对象可以发动。将该卡破坏。\r\n②：此卡与对手怪兽进行战斗的伤害计算时发动。此卡的攻击力・守备力仅在该伤害计算时，变为该对手怪兽的攻击力和守备力中较高一方＋100的数值。\r\n③：此卡战斗破坏怪兽的情况下发动。随机将对手的1张手牌送至墓地，将对手的LP改成一半。','\r',char(13)),'\n',char(10)),'破坏','变换攻击力·守备力','手牌送至墓地','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42418084,'诞生的天使','据说会向肚子里孕育着新生命的女性报喜。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42421606,'编号85 狂箱',replace(replace('等级４怪兽×２\r\n①：此卡不可攻击。\r\n②：１回合１次，去除此卡的１个超量素材可以发动。掷１次骰子，根据掷出的数字适用以下效果。\r\n●１：将自己的LP改成一半。\r\n●２：自己抽１张。\r\n●３：对手挑选１张手牌舍弃。\r\n●４：将场上的１张表侧表示卡的效果直至回合结束时为止无效。\r\n●５：将场上的１张卡破坏。\r\n●６：将此卡破坏。','\r',char(13)),'\n',char(10)),'投掷骰子','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42425831,'雷遁封印式','１回合１次，可将我方场上的１只表侧表示的风属性怪兽返回至牌组最下方并发动。选择对手墓地中的最多２张卡牌并从游戏中除外。','除外','是否现在使用「雷遁封印式」的效果？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42427230,'分割体',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n \r\n①：解放自己场上所有的表侧表示“分割体”可以发动。将“机械衍生物”（机械族・炎・星１・攻／守２００）特殊召唤至自己场上，数量最多为所解放数量×２只。此衍生物被破坏时，每有１只，则对手受到５００伤害。 \r\n②：此卡被除外的情况下，以自己场上任意数量的衍生物为对象可以发动。将该衍生物破坏。','\r',char(13)),'\n',char(10)),'特殊召唤衍生物','破坏衍生物','请选择要特殊召唤的衍生物数量','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42427231,'机械衍生物','由“分割体”的效果特殊召唤而来。此衍生物被破坏时，每有１只，则对手受到５００伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42429678,'风萧萧＠伊格尼斯者','此卡名的①②效果1回合仅可各使用1次。①：此卡召唤・特殊召唤成功的情况下可以发动。从牌组将1只“＠伊格尼斯者”怪兽送至墓地。②：此卡作为电子界族同步怪兽的同步素材被送至墓地的情况下，以自己墓地“风萧萧＠伊格尼斯者”以外的、作为该同步召唤素材的1只怪兽为对象可以发动。将该怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42431833,'电光闪灵・伽马暴','此卡名的①②效果１回合１次，仅可使用其中１个。①：场上所有等级２・阶级２・连接２的怪兽的攻击力・守备力，直至回合结束时为止上升１４００。②：在自己的主要阶段将墓地的此卡除外，以自己场上１只等级２・阶级２・连接２的怪兽为对象可以发动。该怪兽的攻击力直至对手回合结束时为止上升１４００。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42431843,'魔天老','被天界放逐的堕落天使。擅长在黑暗中战斗。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42444868,'轮回的珀耳修斯','①：怪兽的效果・魔法・陷阱卡发动时，可向对手展示１张手牌的计数物陷阱卡，舍弃１张手牌，并支付１０００LP发动。使该发动无效，并将该卡返回至持有者牌组。之后，可从牌组・额外牌组挑选１只“珀耳修斯”怪兽特殊召唤。','是否特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42461852,'电脑网风暴','①：场上的连接状态的怪兽的攻击力・守备力上升500。②：只要此卡存在于场地区域，连接怪兽的连接召唤不会被无效化。③：自己受到2000以上的战斗・效果伤害的情况下可以发动。将自己额外牌组的里侧表示的卡洗牌，翻开最上面的卡。翻开的卡是电子界族连接怪兽的情况下，将该怪兽特殊召唤。不是的情况下放回原处。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42463414,'尖刺半鱼人','只要此卡以表侧表示存在于场上，我方场上的鱼族、海龙族、水族怪兽的攻击力上升４００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42469671,'超电导波雷击炮',replace(replace('此卡名的卡1回合仅可发动1张。此卡的发动和效果不会被无效化。①：自己场上有原本卡名为“欧西里斯之天空龙”的怪兽的情况下可以发动。将对手场上的表侧表示怪兽全部破坏。此卡在自己的主要阶段发动的情况下，进而可以适用以下效果。\r\n●根据以此效果被破坏并被送至对手墓地的怪兽数量，自己从牌组抽相同数量的牌。此回合，自己仅可用1只怪兽攻击。','\r',char(13)),'\n',char(10)),'是否抽牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42472002,'圣骑士 康尼厄斯',replace(replace('此卡名以①方法的特殊召唤１回合仅可进行１次。\r\n①：自己场上有“圣剑”装备魔法卡存在的情况下，此卡可从手牌中特殊召唤。\r\n②：以场上的此卡作为素材的同步・超量・连接召唤的“圣骑士”怪兽获得以下效果。\r\n●此卡的特殊召唤成功的情况下可以发动。此回合自己除通常召唤外仅追加１次，可在自己的主要阶段召唤１只怪兽。此效果发动后，直至回合结束时为止，自己从额外牌组仅可特殊召唤“圣骑士”唤怪兽。','\r',char(13)),'\n',char(10)),'增加召唤次数','使用「圣骑士 康尼厄斯」的效果召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42493140,'从属百夫骑士 特露蒂亚',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：在自己的主要阶段可以发动。将自己场上的此卡和手牌・牌组的“从属百夫骑士 特露蒂亚”以外的１只“百夫骑”怪兽，视为永续陷阱卡，以表侧表示放在自己的魔法与陷阱区域。此回合，自己不可特殊召唤“从属百夫骑士 特露蒂亚”。\r\n②：此卡视为永续陷阱卡的情况下，在自己・对手的主要阶段可以发动。将此卡特殊召唤。然后，此卡的等级可上升４。','\r',char(13)),'\n',char(10)),'','是否上升等级？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42502956,'艾尔斯岩日出','此卡名的卡1回合仅可发动1张。①：以自己墓地的1只兽族怪兽为对象可以发动。将该兽族怪兽特殊召唤，对手场上有表侧表示怪兽存在的情况下，那些怪兽的攻击力直至回合结束时为止，下降相当于自己墓地兽族・鸟兽族・植物族怪兽数量×200的数值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42510430,'日落律动',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：自己场上的表侧表示怪兽变为里侧守备表示的情况下，以场上的1张卡为对象可以发动。将该卡破坏。\r\n②：自己场上的反转怪兽反转的情况下，以其中1只为对象可以发动（伤害步骤也可以发动）。给予对手该怪兽等级×200的伤害。','\r',char(13)),'\n',char(10)),'破坏','给与伤害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42516299,'火焰回击',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：以自己墓地的１只炎属性怪兽为对象可以发动。挑选１张自己的手牌送至墓地，将对象怪兽特殊召唤。\r\n②：将墓地的此卡除外，以自己墓地・除外状态的３只炎属性怪兽为对象可以发动。将该怪兽放回牌组。然后，自己抽１张。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42517468,'扰乱怪・粉红',replace(replace('此卡名的效果１回合仅可使用１次。\r\n①：此卡从手牌・场上被送至墓地的情况下可以发动。双方玩家从牌组抽１张，然后挑选１张手牌舍弃。以此效果自己舍弃“扰乱怪”卡的情况下，进而可指定对手１处尚未使用的怪兽区域。该区域直至对手回合结束时为止不可使用。','\r',char(13)),'\n',char(10)),'是否指定对手怪兽区域不可使用？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42534368,'沉默的死者','选择我方墓地中的１只通常怪兽发动此卡。以表侧守备表示特殊召唤所选择怪兽。以此效果特殊召唤的怪兽只要以表侧表示存在于场上便不可进行攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42541548,'鬼格布林','只要此卡以表侧表示存在于我方场上，可在我方回合的结束阶段时将手牌中１张通常怪兽卡放回到牌组的最下方，并从牌组抽取１张卡牌。此效果在１个回合中只可使用１次。','交换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42542842,'丽之魔妖－妲姬',replace(replace('①：“丽之魔妖－妲姬”在自己场上仅可有１张以表侧表示存在。\r\n②：此卡存在于墓地，且“魔妖”怪兽被从额外牌组特殊召唤至自己场上时可以发动（发动此效果的回合中，自己从额外牌组仅可特殊召唤“魔妖”怪兽）。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42544773,'封印之伟魔导士 斯普恩',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从手牌将此卡舍弃，可从以下效果中选择1个发动。\r\n●从牌组将“封印之伟魔导士 斯普恩”以外的1只“伟魔”怪兽加入手牌。\r\n●将对手场上的1只怪兽的攻击力直至回合结束时为止改成一半。\r\n②：将墓地的此卡除外，以自己场上的1只表侧表示怪兽为对象可以发动。从自己额外牌组・墓地将1只“伟魔”怪兽视为装备魔法卡，装备于对象怪兽。','\r',char(13)),'\n',char(10)),'丢弃发动效果','装备','检索','攻击力变成一半','','','','','','','','','','','','');
INSERT INTO texts VALUES(42548470,'摇摆机械秤','可从我方场上选择２只名称不同且都具“发条”之名的怪兽发动。由对手选择其中１只，使另１只怪兽的等级变为和对手选择的怪兽之等级相同，直到回合结束。如果对手选择了等级较低的怪兽，我方可以从卡组中抽１张卡。','是否抽牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42551040,'武斗神器－生刀','我方场上存在冠有“武斗神”之名怪兽的场合，可将墓地的此卡从游戏中除外，并选择对手场上的１只表侧攻击表示怪兽发动。将被选择怪兽变为表侧守备表示，直至回合结束时该守备力变为０。','改变表示形式','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42560034,'夜之逃飞行','①：以自己场上的1只表侧表示怪兽为对象可以发动。将该表侧表示怪兽放回手牌。此回合，双方不可发动以此效果所加入手牌的卡及其同名卡的效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42562690,'娱乐伙伴水黾船','①：攻击表示的此卡被选择为攻击对象时可发动。此卡变成表侧守备表示，并使该攻击无效。','攻击无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42566602,'瑚之龙',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的②效果1回合仅可使用1次。\r\n①：1回合1次，舍弃1张手牌，以对手场上的1张卡为对象可以发动。将该卡破坏。\r\n②：同步召唤的此卡被送至墓地的情况下可以发动。自己抽1张。','\r',char(13)),'\n',char(10)),'卡片破坏','抽牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42577802,'结合突异变种怪',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：从自己的手牌・场上，将由“突异变种”融合怪兽卡决定的融合素材怪兽除外，将该１只融合怪兽从额外牌组融合召唤。对手在此回合发动过卡的效果的情况下，也可将自己牌组・墓地的各最多１只怪兽作为融合素材。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42578427,'捕鼠夹','对手召唤、反转召唤的怪兽攻击力为５００以下的场合，可破坏１只该怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42589641,'辉星骑士 特莱维尔',replace(replace('等级4“星骑士”怪兽×3\r\n将此卡超量召唤的回合中，自己仅可特殊召唤“星骑士”怪兽。\r\n①：此卡超量召唤的情况下发动。将场上的其他卡全部放回手牌。\r\n②：1回合1次，去除此卡的1个超量素材可以发动。随机将对手的1张手牌送至墓地。\r\n③：持有超量素材的此卡被送至墓地的情况下，以自己墓地的1只“星骑士”怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'回到手牌','手牌破坏','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42591472,'笑之花','一直在笑的花。持续聆听其笑声，脑袋就会变得一片混乱。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42592719,'剑斗兽亚历山大','此卡不可以“剑斗兽迪卡埃利”以外的效果特殊召唤。特殊召唤的此卡不受魔法卡的效果影响。此卡进行了战斗的战斗阶段结束时，可将此卡返回至持有者牌组并发动。从牌组特殊召唤１只除“剑斗兽亚历山大”以外的冠有“剑斗兽”之名的怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42596828,'龙狸灯',replace(replace('①：1个回合1次，从手牌扔掉1只幻龙族怪兽后可以发动。此卡的守备力上升1000，直至回合结束时为止。此效果在对手回合中也可以发动。\r\n②：攻击表示的此卡与攻击表示的怪兽进行战斗，计算伤害值时，可以发动1次。该战斗中，将互相怪兽的守备力作为攻击力进行伤害计算。','\r',char(13)),'\n',char(10)),'守备力上升','使用守备力进行伤害计算','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42598242,'特殊飓风','弃置我方的１张手牌。破坏场上所有特殊召唤的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42599677,'火焰杀手','使用炎之盾的剑士。无论是什么样的攻击都会被此盾化解。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42600274,'电子舞裙球球','①：此卡可从自己的手牌・场上解放１只战士族或天使族怪兽，来从手牌特殊召唤。②：此卡为仪式召唤而被解放的情况下，以自己墓地的１张仪式魔法卡为对象可以发动。将该卡加入手牌。','出场方式为特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42620460,'时潜怪盗・动力储备',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡发动后，变为通常怪兽（念动力族・暗・星４・攻１９００／守２５００），特殊召唤至怪兽区域（也视为陷阱卡）。然后，可从自己的手牌・牌组・墓地将１只机械族“时潜怪盗”怪兽特殊召唤。\r\n②：自己场上存在持有魔法卡与陷阱卡作为超量素材的超量怪兽的情况下，将墓地的此卡除外可以发动。将场上的１张卡除外。','\r',char(13)),'\n',char(10)),'变成通常怪兽特殊召唤','场上1张卡除外','是否再把怪兽特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42625254,'小暴龙','暴龙之子。性格非常兄暴。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42632209,'炎斩机最终西格玛',replace(replace('协调+1只以上协调以外的怪兽\r\n此卡名的③效果1回合仅可使用1次。①：只要此卡存在于额外怪兽区域，就不受“斩机”卡以外的卡的效果影响。②：额外怪兽区域的此卡在和对手怪兽的战斗中给对手的战斗伤害变为两倍。③：此卡因战斗或者是对手的效果被破坏的情况下可以发动。将牌组中的1张“斩机”卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42647539,'石像怪道化师','此卡召唤、反转召唤、特殊召唤成功时，选择场上的１只表侧表示怪兽并变更其表示形式。','改变表示形式','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42664989,'天赐的宝牌','①：可将我方所有手牌・场上的卡牌从游戏中除外来发动此卡。从牌组抽取卡牌直到我方手牌变为２张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42671151,'弗丽嘉的苹果','①：自己场上没有怪兽存在、且自己受到了战斗伤害时可以发动。依所受伤害的数值恢复自己的LP，将1只“邪精衍生物”（恶魔族・暗・星1・攻/守？）特殊召唤至自己场上。此衍生物的攻击力・守备力变为与以此效果自己恢复的数值相同。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42671152,'邪精衍生物','由“弗丽嘉的苹果”的效果特殊召唤而来。此衍生物的攻击力和守备力将与“弗丽嘉的苹果”的效果中我方恢复的数值相同。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42679662,'邪蚀 阿扎特霍斯','反转：选择场上１只特殊召唤而来的怪兽并返回至持有者牌组。','返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42682609,'茧状体・小海豚','可解放此卡并发动。从手牌・牌组特殊召唤１只“新空间人 水波海豚”。此效果在我方场上存在有“新宇空间”的场合可发动与处理。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42685062,'来自地狱的使者','此卡不可特殊召唤。此卡可释放１只怪兽并召唤。以此方法召唤的此卡的等级变为５，原本攻击力、守备力减半。','解放１只怪兽召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42703248,'飓风','场上的魔法、陷阱卡全部返回至持有者手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42705243,'御巫之契',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从手牌・牌组将1只“御巫”怪兽特殊召唤。然后，可从自己手牌・墓地将1张该怪兽可装备的装备魔法卡装备于该怪兽。以此效果特殊召唤的怪兽从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'是否选装备魔法卡装备？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42705244,'御巫之契',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从手牌・牌组将1只“御巫”怪兽特殊召唤。然后，可从自己手牌・墓地将1张该怪兽可装备的装备魔法卡装备于该怪兽。以此效果特殊召唤的怪兽从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'是否选装备魔法卡装备？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42709949,'守护神之矛','装备怪兽的攻击力上升双方墓地中与装备怪兽同名的卡牌数量×９００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42711820,'废铁战士',replace(replace('“废铁同步士”＋协调以外的怪兽1只以上\r\n此卡名的①效果1回合仅可使用1次。\r\n①：此卡同步召唤的情况下可以发动。从牌组挑选1只“废品同步士”或1张记载有“废品战士”卡名的卡，加入手牌或送至墓地。\r\n②：“废铁战士”以外的自己场上的以下怪兽发动的效果不会被无效化。\r\n●记载有“废品战士”卡名的怪兽\r\n●原本卡名包含“战士”的同步怪兽','\r',char(13)),'\n',char(10)),'检索效果','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42713844,'地中骇界邪龙 地蜥利古里亚',replace(replace('此卡名的③效果1回合仅可使用1次。\r\n①：自己场上的表侧表示怪兽变为里侧表示时，若自己场上不存在表侧表示怪兽则可以发动。从手牌将此卡以守备表示特殊召唤。\r\n②：在自己的主要阶段可以发动。将此卡改成里侧守备表示（1回合仅1次）。\r\n③：此卡反转的情况下，以对手场上的1只怪兽为对象可以发动。将该怪兽除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42717221,'电子界时脉龙',replace(replace('“时脉飞龙”＋连接怪兽1只以上\r\n①：此卡融合召唤成功时可以发动。将相当于该素材连接标记合计数值的张数的卡从自己的牌组上面送至墓地。直至下个回合结束时为止，自己的其他怪兽不可攻击，此卡的攻击力上升相当于以此效果送至墓地的张数×1000的数值。②：只要自己场上有连接怪兽存在，对手不可将自己场上的其他怪兽作为攻击・效果的对象。③：融合召唤的此卡因对手的效果被送至墓地的情况下可以发动。从牌组将1张魔法卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42719764,'召唤冲击',replace(replace('①：每当有怪兽被召唤・特殊召唤，就在此卡上放1个召唤计数物（最多4个）。\r\n②：召唤计数物被放在此卡上，使得该召唤计数物的数量变为4的情况下发动。去除此卡的全部召唤计数物，将场上的怪兽全部送至墓地。','\r',char(13)),'\n',char(10)),'送至墓地','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42737833,'XX－军刀 埃摩斯剑刃','①：此卡因战斗被破坏并被送至墓地时可以发动。从牌组将1只等级4以下的“X－军刀”怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42741437,'驱魔姐妹・米迦以利斯',replace(replace('等级4怪兽×2\r\n此卡名的①③效果1回合仅可各使用1次。\r\n①：在以“驱魔姐妹”怪兽作为素材将此卡超量召唤的自己・对手回合中，以对手场上・墓地的1张卡为对象可以发动。将该卡除外。\r\n②：此卡不会因与从墓地被特殊召唤的怪兽的战斗被破坏。\r\n③：去除此卡的1个超量素材可以发动。从牌组将1张“驱魔姐妹”魔法・陷阱卡加入手牌。','\r',char(13)),'\n',char(10)),'对方卡除外','牌组检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42741438,'驱魔姐妹・米迦以利斯',replace(replace('等级4怪兽×2\r\n此卡名的①③效果1回合仅可各使用1次。\r\n①：在以“驱魔姐妹”怪兽作为素材将此卡超量召唤的自己・对手回合中，以对手场上・墓地的1张卡为对象可以发动。将该卡除外。\r\n②：此卡不会因与从墓地被特殊召唤的怪兽的战斗被破坏。\r\n③：去除此卡的1个超量素材可以发动。从牌组将1张“驱魔姐妹”魔法・陷阱卡加入手牌。','\r',char(13)),'\n',char(10)),'对方卡除外','牌组检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42752141,'进化帝・长鳄龙',replace(replace('恐龙族等级４怪兽×２\r\n①：此卡以外的怪兽的效果发动时，去除此卡的１个超量素材可以发动。将该发动无效并破坏。','\r',char(13)),'\n',char(10)),'无效并破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42759961,'小丑戏帮 弗蕾娅',replace(replace('以“小丑戏帮”卡降临\r\n此卡名的①效果1回合仅可使用1次。\r\n①：向对手出示手牌的此卡可以发动。从牌组将仪式怪兽以外的1张“小丑戏帮”卡加入手牌。然后，挑选自己的1张手牌舍弃。\r\n②：此卡被解放的情况下，可从以下效果中选择1个发动（此卡名的以下效果1回合仅可各选择1次）。\r\n●将双方场上・墓地的仪式怪兽全部放回牌组。\r\n●将场上的1只效果怪兽改成里侧守备表示。','\r',char(13)),'\n',char(10)),'检索效果','选择效果','仪式怪兽回到牌组','放置怪兽','','','','','','','','','','','','');
INSERT INTO texts VALUES(42776855,'追赶之翼',replace(replace('以自己场上的１只同步怪兽为对象可以发动此卡。\r\n①：只要此卡存在于魔法与陷阱区域，对象怪兽不会因战斗及对手的效果被破坏。\r\n②：对象怪兽与等级５以上的对手怪兽进行战斗的伤害步骤开始时可以发动。将该对手的怪兽破坏。对象怪兽的攻击力直至回合结束时为止，上升相当于以此效果破坏的怪兽的原本攻击力的数值。\r\n③：对象怪兽离开场上的情况下，此卡将被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42776960,'魂之接力','①：从手牌将１只怪兽特殊召唤。只要以此效果特殊召唤的怪兽在自己场上以表侧表示存在，自己将受到的所有伤害变为０。该怪兽从场上离开时，对手获得决斗胜利。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42781164,'杀手旋律・造轨者',replace(replace('“杀手旋律”协调＋协调1只以上\r\n要以场上的此卡作为素材同步召唤的情况下，可将手牌的1只协调也作为同步素材。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡特殊召唤的情况下可以发动。从牌组将1张“杀手旋律”卡加入手牌。\r\n②：此卡作为同步素材被送至墓地的情况下可以发动。将对手场上的1张卡放回手牌。','\r',char(13)),'\n',char(10)),'检索效果','回手效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42790071,'幻变骚灵・多重伪装者',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己发动陷阱卡的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：此卡特殊召唤的情况下可以发动（发动此效果的回合中，自己仅可特殊召唤“幻变骚灵”怪兽）。从牌组将“幻变骚灵・多重伪装者”以外的１只“幻变骚灵”怪兽以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'此卡从手牌特殊召唤','从牌组把「幻变骚灵」怪兽特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42793609,'极星宝 布里希嘉曼','可选择我方及对手场上的各１只表侧表示怪兽并发动。直至回合结束时，被选择的我方怪兽的攻击力变成与被选择的对手怪兽的原本攻击力相同。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42810973,'废品弓箭手',replace(replace('“废品同步士”＋1只以上协调以外的怪兽\r\n①：1回合1次，以对手场上的1只怪兽为对象可以发动。将该怪兽除外。以此效果除外的怪兽将在此回合的结束阶段放回至对手场上。','\r',char(13)),'\n',char(10)),'除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42822433,'星骑士 天鹰阿尔提亚',replace(replace('此卡名在规则上也视为“星圣”卡。此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・反转召唤・特殊召唤的情况下，以自己场上光・暗属性超量怪兽的数量为上限，以场上的卡为对象可以发动。将该卡破坏。\r\n②：“星骑士 天鹰阿尔提亚”以外的“星骑士”、“星圣”怪兽被特殊召唤至自己场上的情况下可以发动。从墓地将此卡特殊召唤。此回合，自己仅可用超量怪兽攻击宣言。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42829885,'强硬的卫兵','确认对手的手牌，并从其中挑选１张卡放回牌组。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42851643,'穿孔重机・巨型钻孔机','此卡召唤成功时可发动。我方场上的所有机械族怪兽之等级上升１级。此卡攻击了守备表示怪兽时，若该攻击力超过该守备力，给予对手生命相当于该差额数值的战斗伤害。此外，此卡进行了攻击的场合，在伤害步骤结束时变成守备表示。','等级上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42868711,'幻影的哥拉龟','以在场上表侧表示存在的此卡为对象，使对手控制的魔法、陷阱卡的效果无效。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42874792,'发条兔子','可选择我方场上１只冠有“发条”之名的怪兽并发动。直至下一个我方准备阶段时，将被选择怪兽从游戏中除外。此效果在对手回合也可发动。此外，只要此卡以表侧表示存在于场上，此效果只可使用１次。','除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42878636,'古代机械齿轮猎犬',replace(replace('①：此卡召唤的情况下发动。给予对手６００伤害。\r\n②：此卡攻击的情况下，对手直至伤害步骤结束时为止，不可发动魔法・陷阱卡。\r\n③：１回合１次，在自己的主要阶段可以发动。以自己的手牌・场上的怪兽作为融合素材，将１只“古代机械齿轮”融合怪兽融合召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42880485,'超重辉将 翡翠－E',replace(replace('←1 【灵摆】 1→\r\n①：自己仅可灵摆召唤“超重武者”怪兽。此效果不会被无效化。②：１回合１次，以自己场上的１只“超重武者”怪兽为对象可以发动。该怪兽的等级上升１。\r\n【怪兽效果】\r\n此卡在规则上也视为“超重武者”卡。此卡可借由解放１只“超重武者”怪兽来上级召唤。①：此卡召唤・特殊召唤成功时可以发动。变更此卡的表示形式。②：此卡可在表侧守备表示的状态下攻击。该情况下，将此卡的守备力视为攻击力来进行伤害计算。','\r',char(13)),'\n',char(10)),'把1只「超重武者」怪兽解放作上级召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42883273,'森林居民 乌丹','此卡的攻击力，上升场上植物族怪兽数量×１００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42899204,'死配之咒眼',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：对手以攻击表示将怪兽特殊召唤时，拥有比该怪兽高的攻击力的“咒眼”怪兽存在于自己场上的情况下，以该１只对手怪兽为对象可以发动此卡。获得该怪兽的控制权。只要自己的魔法与陷阱区域有“塞勒涅的咒眼”存在，该怪兽也视为“咒眼”怪兽。该怪兽离开场上时，此卡将被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42901635,'电磁石之战士 狂勇机翁',replace(replace('此卡不可通常召唤。\r\n从自己手牌・场上（表侧表示）・墓地将“电磁石战士阿尔法”“电磁石战士贝塔”“电磁石战士伽玛”各1只除外的情况下可以特殊召唤。\r\n①：从自己墓地将1只等级4以下的“磁石战士”怪兽除外，以对手场上的1张卡为对象可以发动。将该卡破坏。\r\n②：此卡因战斗或对手的效果被破坏的情况下，以自己除外状态的“电磁石战士阿尔法”“电磁石战士贝塔”“电磁石战士伽玛”各1只为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42908201,'死亡马尼亚魔鬼','①：此卡战斗破坏对手怪兽时可以发动。从牌组将1只等级4以下的兽族怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42921475,'妖精传姬－塔利娅',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：此卡反转的情况下可以发动。从手牌将1只怪兽特殊召唤。\r\n②：对手发动通常魔法・通常陷阱卡时，解放自己场上的1只其他怪兽可以发动。该效果变为“将对手场上的1只表侧表示怪兽改成里侧守备表示”。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42925441,'光子转换',replace(replace('此卡发动后，在第2次的自己准备阶段会被送至墓地。此卡名的①效果1回合仅可使用1次。①：将自己场上的1只表侧表示的“光子”怪兽或“银河”怪兽送至墓地，可从以下效果中选择1个发动。将“银河眼光子龙”送至墓地来发动的情况下，两者都可以选择。\r\n●从牌组将1只原本的卡名与该怪兽不同的“光子”怪兽特殊召唤。\r\n●从牌组将1张“光子转换”以外的“光子”卡加入手牌。','\r',char(13)),'\n',char(10)),'选择效果发动','特殊召唤','牌组检索','我全都要','回合计数','','','','','','','','','','','');
INSERT INTO texts VALUES(42932862,'冥占卜姬塔罗蕾丝',replace(replace('以“冥占术的仪式”降临。\r\n此卡仅可以仪式召唤及“圣占卜姬塔罗蕾”的效果特殊召唤。\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡反转的情况下可以发动。从牌组将１只反转怪兽以里侧守备表示特殊召唤。\r\n②：在自己・对手回合中，可从以下效果中选择１个发动。\r\n●挑选自己场上任意数量的里侧表示怪兽，改成表侧守备表示。\r\n●挑选自己场上任意数量的表侧表示怪兽，改成里侧守备表示。','\r',char(13)),'\n',char(10)),'从牌组特殊召唤','改变表示形式','里侧变成表侧','表侧变成里侧','','','','','','','','','','','','');
INSERT INTO texts VALUES(42940335,'迷拟宝箱鬼・王座',replace(replace('等级1“迷拟宝箱鬼”怪兽×2\r\n此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：去除此卡的1个超量素材可以发动。从自己手牌・牌组・墓地将1只“迷拟宝箱鬼・领主”特殊召唤。\r\n②：在自己・对手的主要阶段，以自己场上的1只“迷拟宝箱鬼・领主”为对象可以发动。将此卡视为攻击力上升1000的装备魔法卡，装备于该怪兽。然后，可以此卡原先持有的超量素材数量为上限，将场上的卡放回手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','装备','是否让卡回到手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42940404,'机甲部队・齿轮传动架',replace(replace('①：此卡召唤成功时可以发动。从牌组将１只“机甲部队・齿轮传动架”以外的“机甲部队”怪兽加入手牌。②：１回合１次，可从以下效果中选择１个发动。\r\n●以自己场上的１只机械族怪兽为对象，将此卡视为装备卡装备于该怪兽。装备怪兽将被战斗・效果破坏的情况下，破坏此卡作为代替。\r\n●将被装备的此卡特殊召唤。','\r',char(13)),'\n',char(10)),'变成装备卡','特殊召唤','检索','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42941100,'扰乱怪之黄色','是人称不择手段捣乱的扰乱怪三人组的一员。据说只要三人到齐就会有什么发生。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42945701,'火灵术－「红」','①：解放自己场上的1只炎属性怪兽可以发动。给予对手相当于解放的怪兽原本攻击力数值的伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42952160,'冥府的对照镜',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：自己因对手的攻击・效果受到伤害时可以发动。根据所受伤害的种类，适用以下效果。\r\n●战斗：从自己的墓地将１只攻击力在该数值以下的怪兽特殊召唤，在该伤害步骤结束后，结束战斗阶段。\r\n●效果：给予对手相当于该数值两倍的伤害。','\r',char(13)),'\n',char(10)),'','战斗','效果','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42956963,'梦魇恶魔群','①：可解放自己场上的１只怪兽发动。以攻击表示将３只“梦魇恶魔衍生物”（恶魔族・暗・星６・攻／守２０００）特殊召唤至对手场上。每１只“梦魇恶魔衍生物”被破坏时，该控制者受到８００伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42956964,'梦魇恶魔衍生物','由“梦魇恶魔群”的效果特殊召唤而来。此衍生物被破坏时，控制者受到８００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42969214,'钢铁指猴','１回合１次，可以在我方的主要阶段发动。此卡的攻击力提升４００点。发动此效果的回合，这张卡不能攻击。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(42994702,'榜徨木乃伊','此卡１回合仅１次可以变成里侧守备表示。使用此效果的情况下，将自己场上的所有里侧守备表示怪兽洗牌，并再次以里侧守备表示重新排列。','变成里侧守备','攻守上升','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43002864,'爬虫妖・守卫','①：自己场上的此卡被破坏并被送至墓地的情况下发动。从牌组将1只“爬虫妖”怪兽加入手牌。','牌组检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43004235,'海造贼－大派对',replace(replace('此卡名的①效果１回合只能使用１次，②效果在决斗中只能使用１次。\r\n①：我方场上存在“海造贼”怪兽时可发动此卡。我方按我方场上的装备卡数量＋１从卡组抽卡，然后按我方场上装备卡数量选择手牌洗回卡组中。\r\n②：此卡存在于墓地中时，我方从额外卡组特殊召唤“海造贼”怪兽的情况下可发动。将此卡作为能让１只该怪兽攻击力上升５００点的装备卡装备。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43011492,'惨祸的咒眼',replace(replace('此卡牌名的卡牌１回合只可发动１张。\r\n①：我方场上存在有“咒眼”怪兽的场合，可以对手场上的１张魔法、陷阱卡为对象发动。破坏该卡。我方的魔法与陷阱区域存在有“塞勒涅的咒眼”的场合，以此效果破坏的卡牌不送入墓地而直接被除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43014054,'恶狂战士','此卡作为同步召唤素材被送至墓地的情况下，给予该玩家２０００点伤害。此外，直至回合结束时为止，以此卡为同步素材的同步怪兽的攻击力上升２０００点。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43017476,'氘恐龙',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从手牌将此卡舍弃可以发动。从牌组将1张“键结”魔法・陷阱卡加入手牌。\r\n②：此卡召唤・特殊召唤的情况下，以自己墓地的“氢恐龙”、“氧恐龙”、“氘恐龙”中的任意1只为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43034264,'机壳要塞',replace(replace('①：只要此卡存在于场地区，我方除了通常召唤之外仅１次，可在我方主要阶段再召唤１只“机壳”怪兽。\r\n②：只要此卡存在于场地区，“机壳”怪兽的召唤不会被无效化。','\r',char(13)),'\n',char(10)),'使用「机壳要塞」的效果召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43040603,'怪兽门','①：解放自己场上的１只怪兽可以发动。从自己的牌组上面翻开卡，直至翻到可通常召唤的怪兽为止，将该怪兽特殊召唤。将剩余的所翻开的卡全部送至墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43047672,'急袭猛禽－最终要塞猎鹰',replace(replace('等级１２怪兽×３\r\n①：持有“急袭猛禽”超量怪兽作为超量素材的此卡不受其他卡的效果影响。\r\n②：１回合１次，去除此卡的１个超量素材可以发动。将自己除外状态的“急袭猛禽”怪兽全部放回墓地。\r\n③：１回合最多２次，以此卡的攻击破坏怪兽时，将自己墓地的１只“急袭猛禽”超量怪兽除外可以发动。此卡可继续攻击。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43061293,'火焰飞镖','自己手牌为０张的情况下可以发动。掷３次骰子，给予对手LP该合计数值×１００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43066927,'迷拟宝箱鬼・妖精',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己的主要阶段可以发动。从手牌将此卡以里侧守备表示特殊召唤至对手场上。自己场上存在“迷拟宝箱鬼”怪兽的情况下，作为代替也可以表侧表示特殊召唤至自己场上。\r\n②：此卡在主要阶段反转的情况下发动。分别适用以下效果。\r\n●此回合，自己不可发动从自身手牌被特殊召唤的怪兽的效果。\r\n●将此卡的控制权转移给对手。','\r',char(13)),'\n',char(10)),'反转效果','特殊召唤','在自己场上特殊召唤','在对手场上特殊召唤','','','','','','','','','','','','');
INSERT INTO texts VALUES(43096270,'紫翠玉龙',replace(replace('拥有紫翠玉鳞的极度稀世之龙。它的美丽鳞片冠以古代帝王之名，被视为是神秘的象征。\r\n——它的获得者并未意识到自己已经抓住莫大幸运。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43114901,'宝石骑士・红缟玛瑙',replace(replace('只要此卡以表侧表示存在于墓地或场上的场合，被视作通常怪兽。通过将场上以表侧表示存在的此卡视作通常召唤再次召唤，此卡被视作效果怪兽并获得以下效果。\r\n●此卡因战斗破坏对手怪兽并送入墓地时，可发动。从牌组将１张冠有“宝石骑士”之名的卡牌加入手牌。','\r',char(13)),'\n',char(10)),'牌组检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43129357,'蕾祸之武者骷髅',replace(replace('包含昆虫族・植物族・爬虫类族怪兽在内的怪兽２只\r\n此卡名的①②效果１回合仅可各使用１次，发动此效果的回合中，自己仅可特殊召唤昆虫族・植物族・爬虫类族怪兽。\r\n①：以自己墓地的１只“蕾祸”怪兽为对象可以发动。将该怪兽以守备表示特殊召唤。\r\n②：此卡存在于墓地的情况下，以自己场上的１只昆虫族・植物族・爬虫类族怪兽为对象可以发动。将该怪兽放回牌组最下面，将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤「蕾祸」怪兽','特殊召唤自身','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43138260,'超量鮣鱼',replace(replace('①：此卡可去除自己场上的２个超量素材来从手牌特殊召唤。\r\n②：以此卡的①方法特殊召唤时，以自己墓地的２只鱼族・等级４怪兽为对象可以发动。将该鱼族怪兽以守备表示特殊召唤。以此效果特殊召唤的怪兽不可攻击，效果无效化，也不可变更表示形式。将以此效果特殊召唤的怪兽作为超量召唤的素材的情况下，仅可使用于水属性怪兽的超量召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43140791,'异虫饵','发动此卡的回合中，自己不可召唤・特殊召唤等级3・4的怪兽。①：在自己场上有昆虫族怪兽存在的情况下可以发动。将2只“异虫衍生物”（昆虫族・地・星1・攻/守0）特殊召唤至自己场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43140792,'异虫衍生物','由「异虫饵」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43143567,'黄金乡堕天像',replace(replace('“黄金卿埃尔德里奇”＋不死族怪兽\r\n“黄金乡堕天像”1回合1次，仅可以融合召唤及以下方法特殊召唤。\r\n●自己场上或墓地存在“黄金卿埃尔德里奇”的状态下，解放自己场上的1只不死族・光属性怪兽的情况下，可从额外牌组特殊召唤。\r\n此卡名的效果1回合仅可使用1次。\r\n①：此卡从场上被送至墓地的情况下可以发动。从自己牌组・额外牌组・墓地将1只“埃尔德里奇”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43147039,'光子驱逐者',replace(replace('此卡不可通常召唤。自己场上有“光子”怪兽或“银河”怪兽存在的情况下可以特殊召唤。自己1回合仅可特殊召唤1次“光子驱逐者”。①：此卡特殊召唤成功的情况下可以发动。从牌组将1只“银河眼光子龙”加入手牌。②：此卡在特殊召唤的回合不可攻击。③：以场上的此卡为素材超量召唤的怪兽将获得以下效果。\r\n●此卡战斗破坏的怪兽不去墓地而直接被除外。','\r',char(13)),'\n',char(10)),'','「光子驱逐者」效果适用中','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43150717,'超量叠光',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：装备怪兽的攻击力上升场上的超量素材数量×200的数值。\r\n②：1回合1次，根据装备怪兽的种类可以发动以下效果。\r\n●超量怪兽：去除自己场上的2个超量素材可以发动。从牌组将1张“超量”魔法・陷阱卡放置在自己场上。\r\n●超量怪兽以外：从手牌将1只等级与装备怪兽的等级相同的怪兽以守备表示特殊召唤。以此效果特殊召唤的怪兽的效果无效化。','\r',char(13)),'\n',char(10)),'','放置','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43175027,'极冰兽 暴风雪狼',replace(replace('此卡名的效果①②在1个回合中仅可各使用1次。\r\n①：自己或对手的怪兽进行攻击宣言时可以发动。使该攻击无效，从手牌中特殊召唤1只除“极冰兽 暴风雪狼”以外的等级4以下的水属性怪兽。\r\n②：此卡存在于墓地，且自己场上没有怪兽存在时，在对手的战斗阶段开始时可以发动。以攻击表示特殊召唤此卡。此效果特殊召唤的此卡离开场地时将被除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43175858,'卡通王国',replace(replace('①：作为此卡发动时的效果处理，从自己牌组上面将3张卡以里侧除外。\r\n②：此卡只要存在于场地区域，卡名视为“卡通世界”。\r\n③：只要此卡存在于场地区域，对手不可将自己场上的卡通怪兽作为效果的对象。\r\n④：自己场上的卡通怪兽将被战斗・效果破坏的情况下，被破坏的怪兽每有1只，作为代替可从自己牌组上面将1张卡以里侧除外。','\r',char(13)),'\n',char(10)),'是否代替破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43191636,'龙影鱼 雷布隆特',replace(replace('此卡存在于墓地或以表侧表示存在于场上的场合，将被视为通常怪兽。以通常召唤的方式再次召唤场上表侧表示的此卡，此卡将视为效果怪兽并获得以下效果。\r\n●此卡的原始攻击力变为２３００。此卡进行过攻击的场合，在战斗阶段结束时变为守备表示。直到下次我方的回合结束时此卡不可变更表示形式。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43202238,'邪龙星－睚眦',replace(replace('协调+1只以上协调以外的怪兽\r\n此卡名的②③效果1回合仅可各使用1次。①：场上的此卡不会成为对手效果的对象。②：以自己场上1只“龙星”怪兽和对手场上1张卡为对象可以发动。将该卡破坏。③：自己场上的此卡因战斗・效果被破坏并被送至墓地时可以发动。从牌组将1只幻龙族怪兽以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'卡片破坏','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43210483,'音响战士 副奏吉他',replace(replace('←0 【灵摆】 0→\r\n此卡名的灵摆效果１回合仅可使用１次。①：以自己场上此卡以外的１张“音响战士”卡为对象可以发动。将该卡和此卡放回持有者的手牌。\r\n【怪兽效果】\r\n此卡名的①②怪兽效果１回合仅可各使用１次。①：自己的场地区域存在“扩音器热焰”的情况下可以发动。从手牌将此卡特殊召唤。②：此卡召唤・特殊召唤成功的情况下，以自己的灵摆区域的１张卡为对象可以发动。将该卡放回持有者的手牌。','\r',char(13)),'\n',char(10)),'','此卡从手牌特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43215738,'冥铭途・碎骨舞',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己场上存在“冥铭途”怪兽的情况下，以场上的１张卡为对象可以发动。将该卡破坏。然后，自己场上存在“冥骸合龙－冥铭途拉尔泰库特利卡”的情况下，可将场上的１张卡破坏。\r\n②：自己的“冥铭途”怪兽与对手怪兽进行战斗的攻击宣言时，将墓地的此卡除外可以发动。对手场上所有怪兽的攻击力直至回合结束时为止下降１０００。','\r',char(13)),'\n',char(10)),'','','是否破坏场上1张卡？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43218406,'机巧辰－高暗御津羽靇','此卡名的①③效果１回合仅可各使用１次。①：场上有２只以上被从额外牌组特殊召唤的怪兽存在的情况下可以发动。从手牌将此卡特殊召唤。②：支付１５００LP可以发动。将场上从额外牌组被特殊召唤的怪兽全部破坏。此回合，自己仅可用１只怪兽攻击。③：此卡因对手被送至墓地的情况下可以发动。挑选对手墓地的１只怪兽除外。然后，依其攻击力恢复自己的LP。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43219114,'白之龙的威光',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：挑选自己手牌・场上（表侧表示）・墓地的最多３只“青眼白龙”给双方确认。然后，依所确认数量，将对手场上的卡破坏。\r\n②：将墓地的此卡除外可以发动。为使合计等级与仪式召唤的怪兽相等，将自己手牌・场上的“青眼白龙”解放，从手牌将１只仪式怪兽仪式召唤。','\r',char(13)),'\n',char(10)),'破坏','仪式召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43225434,'决斗结合',replace(replace('“决斗结合”１回合只可发动１张。\r\n①：我方场上的融合怪兽与对手怪兽战斗进行战斗的攻击宣言时可发动。直至伤害步骤结束时，该我方怪兽的攻击力上升进行战斗的对手怪兽的攻击力数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43228023,'青眼究极亚龙',replace(replace('“青眼白龙”＋“青眼白龙”＋“青眼白龙”\r\n①：场上的此卡不会成为对手效果的对象，不会因对手的效果被破坏。\r\n②：１回合１次，以对手场上的１张卡为对象可以发动。将该卡破坏。以原本卡名为“青眼亚白龙”的怪兽作为素材的此卡被融合召唤的情况下，可将此效果的对象改成２张或３张。发动此效果的回合中，此卡不可攻击。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43230671,'古代蜥蜴战士','保持这昔日远古姿态的蜥蜴战士，实力出人意表地强悍。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43236494,'童话序章 启程之晓光',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：只要此卡存在于场地区域，双方受到的战斗伤害变为一半。\r\n②：自己场上存在兽族・光属性怪兽或等级7・8的龙族同步怪兽的情况下可以发动。自己抽1张。\r\n③：在自己的准备阶段，将场地区域的此卡送至墓地可以发动。从自己手牌・牌组将“童话序章 启程之晓光”以外的1张场地魔法卡以表侧表示放在自己的场地区域。','\r',char(13)),'\n',char(10)),'伤害减半','抽牌','表侧表示放置场地魔法卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43237273,'新空间人 漆黑猎豹','①：１回合１次，以对手场上的１只表侧表示怪兽为对象可以发动。直至结束阶段为止，此卡获得与该怪兽原本卡名・效果相同的卡名・效果。','效果复制','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43241495,'娱乐伙伴跳跳床山猫',replace(replace('←4 【灵摆】 4→\r\n“娱乐伙伴跳跳床山猫”的灵摆效果１回合只可使用１次。\n①：我方灵摆召唤成功时，可以我方或对手灵摆区的１张卡牌为对象发动。将该卡返回至持有者的手牌。\r\n【怪兽效果】\r\n①：此卡召唤成功时，可以我方或对手灵摆区的１张卡牌为对象发动。将该卡返回至持有者的手牌。','\r',char(13)),'\n',char(10)),'回到手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43250041,'吸收屏障','①：对手怪兽的攻击宣言时，可以１只攻击怪兽为对象发动。使该攻击怪兽的攻击无效，并且我方回复相当于该怪兽攻击力数值的LP。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43256007,'冰结界的随身',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：解放此卡可以发动。从手牌将１只等级５以上的“冰结界”怪兽特殊召唤。\r\n②：不是在此回合被送至墓地的此卡存在于墓地的情况下，以自己场上１只等级３以上的水属性怪兽为对象可以发动。该怪兽的等级下降２，将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43262273,'红莲指名者','①：支付2000LP，向对手出示所有手牌可以发动。确认对手的手牌，挑选其中1张，直至下个对手的结束阶段为止以表侧除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43266605,'精神骨架 多线处理者','此卡名的③效果１回合仅可使用１次。①：此卡只要存在于手牌・墓地，视为“精神骨架 驱动者”。②：自己场上的“精神骨架”卡将被战斗・效果破坏的情况下，可将手牌的此卡舍弃作为代替。③：此卡存在于墓地，“精神骨架”协调被特殊召唤至自己场上的情况下可以发动。从墓地将此卡特殊召唤。以此效果特殊召唤的此卡离开场上的情况下，将其除外。','是否使用「精神骨架多线人」的效果代替破坏？','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43268675,'幻奏的音女欧佩拉',replace(replace('①：于此卡召唤、反转的回合不可攻击。\r\n②：此卡作为融合召唤素材被送入墓地的场合可发动。此回合，我方场上的“幻奏”怪兽不会因战斗、效果而被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43270827,'兽带斗士・交叉击',replace(replace('此卡名的卡１回合仅可发动１张。①：自己场上存在“兽带斗士”怪兽、对手发动怪兽的效果时，可从以下效果中选择１个发动。自己墓地存在“无尽机关 阿尔银洛系统”的情况下，两者都可以选择。\r\n●将该效果无效。\r\n●将该怪兽除外。','\r',char(13)),'\n',char(10)),'选择效果发动','该效果无效','那只怪兽除外','选择两方','','','','','','','','','','','','');
INSERT INTO texts VALUES(43316238,'未界域之大脚',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：向对手出示手牌的此卡可以发动。对手从自己的所有手牌中随机挑选1张，自己舍弃该卡。挑选到的是“未界域之大脚”以外的情况下，进而从手牌将1只“未界域之大脚”特殊召唤，自己抽1张。\r\n②：此卡从手牌被舍弃的情况下，以对手场上的1张表侧表示卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43316239,'未界域之大脚',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：向对手出示手牌的此卡可以发动。对手从自己的所有手牌中随机挑选1张，自己舍弃该卡。挑选到的是“未界域之大脚”以外的情况下，进而从手牌将1只“未界域之大脚”特殊召唤，自己抽1张。\r\n②：此卡从手牌被舍弃的情况下，以对手场上的1张表侧表示卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43318266,'云魔物－卷层云','此卡不会因战斗而被破坏。此卡以表侧守备表示存在的场合，被破坏。此卡召唤成功时，在此卡放置雾计数物，其数量相当于场上冠有“云魔物”之名怪兽的数量。可移除此卡的２个雾计数物并发动。选择场上的１只怪兽破坏。','放置计数物','怪兽破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43321985,'上古精灵生命龙',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的①效果1回合仅可使用1次。\r\n①：此卡同步召唤的情况下可以发动。自己抽1张。场上存在“精灵的世界”的情况下，作为代替从牌组将1只光属性的兽族・植物族・天使族怪兽或1张“永恒阳光”加入手牌。\r\n②：自己的“上古精灵龙”及记载有该卡名的怪兽可在表侧守备表示的状态下攻击（在伤害计算将守备力视为攻击力）。','\r',char(13)),'\n',char(10)),'抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43331750,'结合复制',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：以自己或对手墓地的1张“融合”通常・速攻魔法卡或“结合”通常・速攻魔法卡为对象可以发动。将该魔法卡除外。然后，适用该魔法卡发动时的效果。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43332022,'朱罗纪・似鸡龙','①：此卡因战斗被破坏并被送至墓地的情况下发动。对手可挑选1张手牌舍弃来将此效果无效。不舍弃的情况下，将破坏了此卡的怪兽破坏。','破坏','是否要丢弃手牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43338320,'冥骸府－冥铭途兰',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：自己的“冥铭途”怪兽进行战斗的情况下，对手直至伤害步骤结束时为止，不可发动魔法・陷阱卡。\r\n②：自己场上的怪兽因战斗・效果被破坏的情况下，以其中１只为对象可以发动。从自己的手牌・墓地将１只等级低于该怪兽的“冥铭途”怪兽特殊召唤。\r\n③：在自己的结束阶段，以自己墓地的１张“冥铭途”魔法・陷阱卡为对象可以发动。将该卡放置在自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43340443,'反冲','怪兽的召唤・反转召唤无效，将该怪兽放回持有者的手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43341600,'芙蕾雅的苹果',replace(replace('①：可以对手墓地卡牌为对象发动，其数量最多是我方场上“女战神”怪兽数量。将该卡除外。\r\n②：被盖牌的此卡因对手效果从场上离开，并被送入墓地或被除外的场合，可发动。我方从牌组抽取卡牌，其数量相当于我方场上的“女战神”怪兽数量＋１张卡牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43352213,'猫女郎','以敏捷的动作避开攻击，并以锐利的爪子袭击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43355214,'不死大军团',replace(replace('等级7怪兽×2\r\n“不死大军团”1回合1次，也可重叠在自己场上的不死族・阶级6超量怪兽上面超量召唤。\r\n此卡名的①效果1回合仅可使用1次。\r\n①：在对手的主要阶段，去除此卡的2个超量素材，以对手场上的1只攻击表示怪兽或对手墓地的1只怪兽为对象可以发动（此卡仅持有超量怪兽作为超量素材的情况下，可将要去除的超量素材的数量改成1个）。将该怪兽作为此卡的超量素材。','\r',char(13)),'\n',char(10)),'是否在6阶不死族超量怪兽上面重叠来超量召唤？','作为超量素材','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43359262,'电镀军曹','１回合１次，可选择被盖牌于对手魔法与陷阱区域的１张卡牌。只要此卡以表侧表示存在于场上，被选择的卡牌不可发动。','发动限制','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43363035,'塔尔塔牢斯的徊神',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：此卡被从牌组送至墓地的情况下发动（应对此效果的发动，双方不可发动怪兽的效果）。将自己场上的卡全部送至墓地，将此卡特殊召唤。然后，以因此效果送至了墓地的卡的数量为上限，将对手场上的卡送至墓地。\r\n②：此卡被从牌组以外的地方送至墓地的情况下，将１张手牌送至墓地可以发动。将场上的１张卡送至墓地。','\r',char(13)),'\n',char(10)),'特殊召唤','送墓效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43366227,'七剑战士',replace(replace('协调＋１只以上协调以外的怪兽\r\n１回合１次，在此卡装备了装备卡时，给予对手LP８００点伤害。此外，１回合１次，可以选择被装备于此卡的１张装备卡并送至墓地。装备于此卡的装备卡被送至墓地时，可以选择对手场上的１只表侧表示怪兽并破坏。','\r',char(13)),'\n',char(10)),'伤害','装备送墓','破坏','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43378048,'混沌幻魔阿米泰尔',replace(replace('“神炎皇乌利亚”＋“降雷皇哈蒙”＋“幻魔皇拉比艾尔”\r\n仅在除外自己场上的上述卡的情况下，可从额外牌组特殊召唤（无需“融合”）。①：此卡的攻击力在自己回合期间上升10000。②：此卡不会因战斗被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43378076,'罗刹','此卡不可特殊召唤。召唤・反转此卡回合的结束阶段时回到持有者的手牌中。召唤・反转此卡时，可将手牌中除“罗刹”以外的１只灵魂怪兽向对手展示来发动此卡。选择对手场上１只表侧攻击表示的怪兽令其回到持有者的手牌中。发动此效果的回合中，我方不可特殊召唤怪兽。','返回手牌','返回手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43383478,'升阶魔法－猛禽之力','①：自己场上的“急袭猛禽”超量怪兽被破坏并被送至墓地的回合，以自己墓地的１只“急袭猛禽”超量怪兽为对象可以发动。将该怪兽特殊召唤，将１只阶级比该怪兽高１的“急袭猛禽”怪兽重叠在对象怪兽上面，视为超量召唤从额外牌组特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43385557,'魔力人造机人',replace(replace('协调＋协调以外的怪兽1只以上\r\n①：在自己的结束阶段发动。自己恢复相当于自己场上的念动力族怪兽的数量×600的LP。','\r',char(13)),'\n',char(10)),'回复LP','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43387895,'霸王眷龙 凶饿猛毒',replace(replace('暗属性灵摆怪兽×２\r\n此卡仅可以融合召唤及以下方法特殊召唤。\r\n●解放自己场上的上述卡的情况下，可从额外牌组特殊召唤。\r\n①：１回合１次，以此卡以外的、自己或对手场上・墓地的１只怪兽为对象可以发动。此卡直至结束阶段为止，获得与该怪兽原本卡名・效果相同的卡名・效果。此回合，自己的怪兽攻击了守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。','\r',char(13)),'\n',char(10)),'复制效果','结束复制效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43405287,'D－锁链',replace(replace('①：可以我方场上的１只“命运－英雄”怪兽为对象发动。此卡被视为攻击力上升５００点的装备卡，装备在该我方怪兽。\r\n②：装备怪兽因战斗破坏对手怪兽并送入墓地的场合发动。给予对手５００点伤害。','\r',char(13)),'\n',char(10)),'伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43411769,'守护龙 卡尔米德思','此卡名的①②效果1回合仅可各使用1次。①：通常怪兽被送至自己墓地的情况下可以发动。从手牌将此卡特殊召唤。②：此卡存在于墓地的情况下，从手牌将1只龙族怪兽送至墓地可以发动。将此卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43413875,'花札卫－芒与月－',replace(replace('此卡不可通常召唤。\r\n解放了我方场上１只除“花札卫－芒与月－”以外的等级８的“花札卫”怪兽的场合可特殊召唤\r\n①：此卡特殊召唤成功的场合发动。我方从牌组抽取１张卡牌，并双方相互确认。该卡是“花札卫”怪兽的场合，可特殊召唤该怪兽。若不是的场合，将该卡送入墓地。\r\n②：１回合１次，此卡因战斗破坏对手怪兽时可发动。我方从牌组抽取１张卡牌。','\r',char(13)),'\n',char(10)),'抽1张卡并给双方确认','是否特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43417563,'舞蹈的诱发','用于召唤“舞斗士”。必须从手牌・我方场上解放合计等级达到６以上的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43419178,'艮鬼神 水子守命',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的①效果1回合仅可使用1次。\r\n①：此卡特殊召唤的情况下可以发动。从牌组将1张“艮鬼”卡送至墓地，将场上的1张卡送至墓地。\r\n②：对手发动怪兽的效果的情况下，以自己墓地・除外状态的1张“艮鬼”陷阱卡为对象可以发动（场上的里侧表示卡在3张以上的情况下，作为代替也可以自己墓地的1张陷阱卡为对象）。将该卡放置在自己场上。','\r',char(13)),'\n',char(10)),'送至墓地','放置','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43422537,'二重召唤','①：此回合自己最多可进行2次通常召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43426903,'爬虫妖戈尔工','此卡进行攻击的伤害计算后，与此卡进行战斗的怪兽攻击力变成０，不可变更表示形式。','攻击变成0，不可改变表示形式','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43434803,'过浅的墓穴','双方玩家各自选择墓地中的１只怪兽，并以里侧守备表示盖牌至各自的场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43436049,'废品破坏者','①：在此卡召唤的回合的自己的主要阶段，解放此卡可以发动。将场上所有表侧表示怪兽的效果直至回合结束时为止无效。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43450363,'R.B.终战屹立',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：从自己牌组・额外牌组・墓地将自己场上不存在同名卡的1只“R.B.”怪兽特殊召唤。此卡发动后，直至回合结束时为止自己从额外牌组仅可特殊召唤攻击力1500以下的机械族怪兽。\r\n②：对手发动以自己场上的“R.B.”怪兽为对象的魔法・陷阱・怪兽的效果时，将墓地的此卡除外可以发动。将该效果无效。','\r',char(13)),'\n',char(10)),'发动','效果无效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43452193,'异次元隧道－镜之门－','将自己场上的名字带有“元素－英雄”的怪兽作为攻击对象的对手怪兽的攻击宣言时可以发动。直到结束阶段时将对手的攻击怪兽和成为攻击对象的自己怪兽的控制权交换，再进行伤害计算。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43455065,'魔力之泉',replace(replace('“魔力之泉”１回合只可发动１张。\r\n①：我方从牌组抽取相当于对手场上表侧表示的魔法、陷阱卡数量的卡牌。之后，从我方手牌挑选相当于我方场上表侧表示的魔法、陷阱卡数量的卡牌并舍弃。此卡发动后，直至下一个对手回合结束时，对手场上的魔法、陷阱卡不会被破坏，发动及效果不会被无效化。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43464884,'妖海的非法猎捕',replace(replace('此卡牌名的①②效果１回合只可各使用１次，发动此效果的回合，我方只可特殊召唤兽战士族怪兽。\r\n①：此卡召唤、特殊召唤成功的场合，可以我方墓地的１只兽战士族怪兽为对象发动。直至回合结束时，此卡的属性、等级变为与该怪兽相同。\r\n②：可在我方主要阶段发动。从手牌特殊召唤１只持有与此卡相同属性、等级的兽战士族怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43471513,'卷尺骑士',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡存在于手牌，且场上存在机械族怪兽的情况下可以发动。将此卡以守备表示特殊召唤。然后，可将此卡的等级改成与场上的1只机械族怪兽的等级・阶级的数值相同。\r\n②：在自己的主要阶段可以发动。从牌组将1只机械族・地属性怪兽送至墓地。然后，此卡的攻击力直至回合结束时为止，上升被送至墓地的怪兽等级×100的数值。','\r',char(13)),'\n',char(10)),'特殊召唤','送至墓地','是否改变等级？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43476205,'升阶魔法－革命之力',replace(replace('①：根据发动的回合可以发动以下效果。\r\n●自己回合：以自己场上的１只“急袭猛禽”超量怪兽为对象可以发动。将１只阶级高１的“急袭猛禽”怪兽重叠在对象的自己怪兽上面，视为超量召唤从额外牌组特殊召唤。\r\n●对手回合：以对手场上１只没有超量素材的超量怪兽为对象可以发动。获得该超量怪兽的控制权。然后，将１只阶级高１的“急袭猛禽”怪兽重叠在对象怪兽上面，视为超量召唤从额外牌组特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43487744,'白洞','此卡名在规则上也视为“空洞”卡。对手发动“黑洞”时可以发动。自己场上存在的怪兽不会因该“黑洞”的效果被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43490025,'翼日编号0 未来皇霍普－翼日斩',replace(replace('“编号”怪兽以外的相同阶级超量怪兽×２\r\n规则上，此卡的阶级视为１。此卡也可重叠在自己场上的“希望皇霍普”怪兽或“翼日编号0 未来皇霍普”上面来超量召唤。①：此卡的攻击力上升相当于双方墓地的“编号”超量怪兽数量×５００的数值。②：此卡不会因战斗被破坏。③：１回合１次，去除此卡的１个超量素材可以发动。此回合，此卡在１次战斗阶段中可攻击２次。','\r',char(13)),'\n',char(10)),'2次攻击','是否在霍普怪兽上重叠来超量召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43500484,'魔界的荆棘','生存于魔界的荆棘。会缠住企图强行通过者。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43502497,'灵摆女巫',replace(replace('←8 【灵摆】 8→\r\n此卡名的灵摆效果1回合仅可使用1次。\n①：此卡存在于灵摆区域的状态下，且自己场上表侧表示的融合・同步・超量怪兽因战斗或对手的效果被破坏的情况下可以发动。从牌组将1只原本种族与其中1只相同的灵摆怪兽以表侧加入额外牌组。\r\n【怪兽效果】\r\n此卡名的①怪兽效果1回合仅可使用1次。\n①：此卡召唤・灵摆召唤的情况下，以自己灵摆区域的1张卡为对象可以发动。将该卡和此卡破坏，从牌组将1只等级4以下的灵摆怪兽加入手牌。\n②：怪兽区域的此卡被破坏的情况下可以发动。将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'加入额外牌组','检索','放置灵摆刻度','请选择要加入额外牌组的卡','','','','','','','','','','','','');
INSERT INTO texts VALUES(43509019,'卡通防御','①：对手怪兽对自己的等级4以下的卡通怪兽攻击宣言时可以发动。将该对手怪兽的攻击改成对自己的直接攻击。','改变攻击对象','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43513897,'星圣 巨蟹阿库贝斯','①：此卡召唤・特殊召唤的情况下发动。自己场上所有“星圣”怪兽的攻击力上升500。','攻击力上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43527730,'御巫之展翅水舞',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：装备怪兽不会因效果被破坏。\r\n②：在自己的主要阶段可以发动。将原本卡名与装备怪兽不同的1只“御巫”怪兽从手牌・牌组特殊召唤，将此卡装备于该怪兽。然后，将原先装备此卡的怪兽放回手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43528009,'星之金币',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：挑选自己的２张手牌加入对手的手牌。然后，自己从牌组抽２张。','\r',char(13)),'\n',char(10)),'请选择要加入对手手牌的卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43530283,'勇气之沙漏','此卡召唤、反转召唤成功时，在下次我方回合的结束阶段前此卡原本的攻击力、守备力减半，之后此卡原本的攻击力、守备力变成２倍。','攻守变换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43534808,'衍生物收藏家','此卡名的①效果1回合仅可使用1次。①：此卡存在于手牌・墓地、衍生物被特殊召唤的情况下可以发动。将此卡特殊召唤。②：此卡特殊召唤成功的情况下发动。将场上的衍生物全部破坏，此卡的攻击力上升相当于破坏的衍生物数量×400的数值。③：只要此卡存在于怪兽区域，双方不可特殊召唤衍生物。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43543777,'伊奘波','此卡不可特殊召唤。召唤・反转此卡的回合的结束阶段时此卡回到持有者的手牌中。召唤・反转此卡时，可弃置１张手牌将我方墓地中的１只灵魂怪兽加入到手牌中。','回到手牌','把自己墓地存在的1只灵魂怪兽加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43573231,'幻蝶刺客－闪蝶','１回合１次，对手场上怪兽的表示形式被改变时，可选择１只该怪兽并发动。被选择怪兽的攻击力、守备力下降１０００点。','攻守下降','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43575579,'余晖',replace(replace('此卡名的卡在决斗中仅可发动1张。\r\n①：从自己的手牌、牌组、墓地及自己场上表侧表示的卡中，除外包括此卡在内的所有“余晖”卡。然后，从被除外的自己的卡中，选择1张“余晖”卡加入牌组。在自己的下一次抽牌阶段，互相查看以通常抽牌的方式抽出的卡。如果抽出的卡为“余晖”，则给对手4000伤害值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43577607,'龙星的气脉',replace(replace('①：根据自己墓地的“龙星”怪兽的属性种类数量，获得以下效果。\r\n●2种以上：自己场上的“龙星”怪兽的攻击力上升500。\r\n●3种以上：自己场上的“龙星”怪兽将被战斗・效果破坏的情况下，可将此卡送至墓地作为代替。\r\n●4种以上：对手不可放置怪兽，对手场上的表侧表示怪兽全部变成攻击表示。\r\n●5种以上：将此卡送至墓地可以发动。将场上的卡全部破坏。','\r',char(13)),'\n',char(10)),'全部破坏','是否要使用「龙星的气脉」的效果代替破坏？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43580269,'无限真理','①：此卡因战斗破坏对手怪兽并送入墓地的场合发动。此卡的攻击力上升７００。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43582229,'冰结界的晶壁',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：此卡发动时，可将自己墓地１只等级４以下的“冰结界”怪兽作为对象。该情况下，将该怪兽特殊召唤。\r\n②：只要此卡存在于魔法与陷阱区域，且自己场上存在３只以上的“冰结界”怪兽，自己场上的“冰结界”怪兽不受被从额外牌组特殊召唤的对手怪兽所发动的效果影响。','\r',char(13)),'\n',char(10)),'是否把墓地怪兽特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43583400,'反锯齿星人',replace(replace('①：１回合１次，此卡与怪兽进行了战斗的我方、对手的战斗阶段可发动。从手牌召唤１只电子界族怪兽。\r\n②：表侧表示的此卡因对手效果从场上离开的场合发动。我方从牌组抽取１张卡牌。','\r',char(13)),'\n',char(10)),'怪兽召唤','抽牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43586926,'多尔多拉',replace(replace('“多尔多拉”的效果在决斗中只可使用１次。\r\n①：可在场上的此卡被破坏送入墓地的回合的结束阶段从墓地特殊召唤此卡。以此效果特殊召唤的此卡的攻击力和守备力变为１０００。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43598843,'机关傀偶－恐怖婴',replace(replace('①：此卡召唤时，以自己墓地“机关傀偶－恐怖婴”以外的１只“机关傀偶”怪兽为对象可以发动。将该怪兽以守备表示特殊召唤。\r\n②：将墓地的此卡除外可以发动。此回合，应对自己的“机关傀偶”怪兽的效果发动，对手不可发动魔法・陷阱・怪兽的效果。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43618262,'初买','①：从对手的牌组上面翻开５张卡，自己从其中挑选１张，宣言１００的倍数（最多３０００）。对手可恢复相应数值的LP。恢复的情况下，自己失去该数值的LP，将所挑选的卡加入自己的手牌，将剩余的卡以原来的顺序放回牌组上面。未恢复的情况下，将所翻开的卡以原来的顺序放回牌组上面。','是否回复基本分让对手把卡加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43633088,'紧急显形','①：以自己墓地・除外状态的1只等级5以下的念动力族怪兽为对象可以发动。将该怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43641473,'善变的裁缝师','将１张装备于怪兽的装备卡，转换给另外１只成为正确对象的怪兽。','请选择一张装备卡','请选择要转移装备的对象','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43642620,'猛玛象僵尸','自己墓地不存在有不死族怪兽的情况下此卡被破坏。场上表侧表示的此卡被破坏的情况下，给予此时的控制者此卡原本攻击力数值的伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43644025,'虫茧再生','可解放我方场上的１只冠有“茧状体”之名的表侧表示怪兽并发动。从我方或对手墓地选择１只该卡牌中记载的冠有“新空间人”之名的怪兽并特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43658697,'超级运动员王牌签约',replace(replace('此卡牌名的卡牌１回合只可发动１张。\r\n①：从牌组特殊召唤１只“超级运动员”怪兽。以此效果特殊召唤之怪兽不可作为同步、超量召唤的素材，且效果被无效化。之后，我方失去相当于该怪兽等级×３００LP。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43661068,'向星辰许愿','可选择我方场上的１只表侧表示怪兽并发动。直至回合结束时，我方场上持有与被选择怪兽相同攻击力或相同守备力的怪兽等级变成与被选择怪兽相同。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43664494,'调皮宝贝・捣蛋记',replace(replace('具此卡名的①②效果１回合各只能使用１次。\r\n①：从手牌中弃掉１张“调皮宝贝”卡可发动。在我方场上特殊召唤１只“调皮宝贝衍生物”（炎族・炎・星１・攻／守０）。此衍生物不可解放。\r\n②：在我方结束阶段，以除“调皮宝贝・捣蛋记”之外我方墓地中３张“调皮宝贝”卡为目标可发动。将那３张卡加入卡组并洗牌。然后，我方从卡组抽１张卡。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43664495,'调皮宝贝衍生物','由“调皮宝贝・捣蛋记”的效果特殊召唤而来。此衍生物不可用作祭品。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43685562,'净－朋.克.危险裂口','此卡名的卡1回合仅可发动1张。①：以对手场上的1只效果怪兽为对象可以发动。将该怪兽的效果直至回合结束时为止无效。自己场上有“朋.克.”怪兽存在的情况下，自己的LP进而恢复相当于对象怪兽原本攻击力的数值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43694075,'律之祈祷','①：为使等级合计变为７以上，解放自己的手牌・场上的怪兽，从手牌将“律守护者”仪式召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43694481,'暴风雪猎鹰','此卡的攻击力高于原本攻击力的情况下可以发动。给予对手LP１５００点的伤害。此效果只要此卡以表侧表示存在于场上仅可使用１次，“暴风雪猎鹰”的效果１回合仅可使用１次。','LP伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43694650,'未界域之鹿角兔','此卡名的②效果1回合仅可使用1次。①：向对手出示手牌中的此卡可以发动。对手从自己的所有手牌中随机挑选1张，自己舍弃该卡。该卡为“未界域之鹿角兔”以外的情况下，进而从手牌将1只“未界域之鹿角兔”特殊召唤，自己从牌组抽1张。②：此卡从手牌被舍弃的情况下可以发动。从牌组将1只“未界域之鹿角兔”以外的“未界域”怪兽以守备表示特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43697559,'喷射机机人','此卡被选择为对手怪兽的攻击对象时，我方可从手牌发动陷阱卡。','','适用「喷射机机人」的效果来发动','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43698897,'魔玩具工厂','此卡名的①②效果1回合仅可各使用1次。①：从自己的墓地将1张“融合”魔法卡或“结合”魔法卡除外，可以发动此效果。从自己的手牌・场上，将由“魔玩具”融合怪兽卡决定的融合素材怪兽送至墓地，从额外牌组将1只该融合怪兽融合召唤。②：此卡被送至墓地的情况下，以1张被除外的自己的“魔玩具结合”为对象可以发动。将该卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43708041,'阳炎光轮','只要此卡存在于场上，可减少释放１只我方召唤冠有“阳炎兽”之名怪兽的场合时必要的怪兽。此外，可将场上表侧表示的此卡送入墓地并发动。从我方墓地选择１张除“阳炎光轮”以外的冠有“阳炎”之名的卡牌加入手牌。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43708640,'牛马林神','此卡不可特殊召唤。释放此卡，从我方牌组特殊召唤２只兽战士族・等级４的通常怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43709490,'被检体突异变种GB－88',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己的场地区域有“突异变种进化研究所”存在的情况下，在对手的主要阶段可以发动。从手牌将此卡特殊召唤。\r\n②：在对手回合中，此卡特殊召唤成功的情况下，解放此卡，将手牌或自己场上的１张表侧表示卡除外可以发动。从自己墓地的怪兽及自己被除外的怪兽中，挑选１只等级８“突异变种”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'此卡特殊召唤','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43711255,'禁止令',replace(replace('宣言1个卡名可以发动此卡。\r\n①：只要此卡存在于魔法与陷阱区域，原本卡名与被宣言的卡名相同的、双方的卡适用以下内容（不适用于此效果适用前就存在于场上的卡）。\r\n●不可出到场上。\r\n●不可将卡发动及将效果发动和适用。\r\n●不可通常召唤・反转召唤・特殊召唤。\r\n●不可攻击及变更表示形式。\r\n●不可作为用于需要素材的特殊召唤的素材。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43714890,'投人巨魔','通过解放存在于我方场上的１只除衍生物以外的通常怪兽，给予对手生命８００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43716289,'剧毒木乃伊','反转：给予对手玩家５００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43722862,'风魔女－冰铃','此卡名的①②效果1回合仅可各使用1次。①：自己场上不存在怪兽的情况下可以发动。从手牌将此卡特殊召唤。然后可从牌组将1只“风魔女”怪兽特殊召唤。以此效果从牌组特殊召唤的怪兽不可解放，发动此效果的回合中，自己从额外牌组仅可特殊召唤等级5以上的风属性怪兽。②：此卡召唤・特殊召唤成功的情况下可以发动。给予对手500伤害。','特殊召唤','是否从牌组把1只「风魔女」怪兽特殊召唤？','伤害','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43730887,'拘束臂',replace(replace('①：此卡召唤或特殊召唤成功时，以对手场上1只表侧表示的怪兽为对象发动。此怪兽以表侧表示存在时，作为其对象的表侧表示怪兽不可攻击且效果无效。\r\n②：只要此卡效果①的对象怪兽存在于场上，此卡就不会因战斗或效果被破坏。','\r',char(13)),'\n',char(10)),'选择怪兽不可攻击，效果无效化','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43735670,'海晶少女 蓝彩蛞蝓',replace(replace('等级４以下的“海晶少女”怪兽１只\r\n自己１回合仅可连接召唤“海晶少女 蓝彩蛞蝓”１次。\r\n①：此卡连接召唤的情况下，以自己墓地“海晶少女 蓝彩蛞蝓”以外的１只“海晶少女”怪兽为对象可以发动。将该怪兽加入手牌。此效果发动后，直至回合结束时为止自己仅可特殊召唤水属性怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43739056,'天孔邪鬼',replace(replace('①：只要此卡存在于怪兽区域，自己不可发动此卡以外的、与此卡属性相同的、被特殊召唤的怪兽的效果。\r\n②：１回合１次，在自己・对手的主要阶段可以发动。将此卡的控制权转移给对手。然后，可将此卡的属性直至下个回合结束时为止变更为任意属性。此效果仅可在此卡原本持有者的回合发动。','\r',char(13)),'\n',char(10)),'是否改变属性？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43748308,'微炎星－龙进',replace(replace('①：１回合１次，将自己场上的２张表侧表示的“炎舞”魔法・陷阱卡送至墓地，以自己墓地的１只“微炎星－龙进”以外的“炎星”怪兽为对象可以发动。将该怪兽特殊召唤。\r\n②：１回合１次，自己发动“炎舞”魔法・陷阱卡的情况下可以发动。从牌组将１张“炎舞”陷阱卡放置在自己场上。','\r',char(13)),'\n',char(10)),'放置','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43751755,'茧状体・小黑豹','可解放此卡并发动。从手牌・牌组特殊召唤１只“新空间人 漆黑猎豹”。此效果在我方场上存在有“新宇空间”的场合可发动与处理。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43785278,'傅科的魔炮石',replace(replace('←2 【灵摆】 2→\r\n①：在发动了此卡的回合的结束阶段，以场上的１张表侧表示的魔法・陷阱卡为对象可以发动。将该卡破坏。\r\n【怪兽效果】\r\n本该是徘徊于梦幻空间的机械装置生命体。\n最大的谜团是，过去的记录几乎都未保……着。\n其理由……为何？……拒绝……介入……？\n……删除……','\r',char(13)),'\n',char(10)),'魔陷破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43791861,'凤王兽 盖尔达','此卡攻击对手怪兽的场合，在伤害步骤期间攻击力上升３００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43793530,'吉咖・咖咖吉哥','为了对抗强大的恶，进行了各种各样的肉体改造，结果得到了可怕的力量，但代价却是失去了正义之心。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43797906,'亚特兰蒂斯的战士','①：从手牌将此卡舍弃至墓地可以发动。从牌组将1张“传说之都 亚特兰蒂斯”加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43803845,'仗势鸭',replace(replace('①：只要此卡存在于场上、墓地，被视为通常怪兽。\r\n②：可将场上被视为通常怪兽的此卡作为通常召唤再召唤１次。该场合此卡被视为效果怪兽获得以下效果。\r\n●此卡不会成为效果的对象，不会因效果被破坏。\r\n●只要此卡存在于怪兽区，对手怪兽的攻击全部变为直接攻击。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43813459,'反射光子流','我方的龙族、光属性怪兽被选择为攻击对象时可发动。直至伤害步骤结束时，该攻击对象怪兽的攻击力上升相当于攻击怪兽的攻击力数值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43834302,'同步同伴',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从牌组将以下的怪兽各1只加入手牌。然后，挑选自己的1张手牌舍弃。\r\n●“废品同步士”\r\n●记载有“废品战士”“星尘龙”中的任一卡名的怪兽\r\n②：将墓地的此卡除外，以自己场上的1只同步怪兽为对象可以发动。该怪兽的等级下降1。进而在此回合，自己在通常召唤之外，可在自己的主要阶段追加1次召唤1只“同步士”怪兽。','\r',char(13)),'\n',char(10)),'检索','等级下降','使用「同步伙伴」的效果召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43839002,'电脑网后门',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：以自己场上的１只电子界族怪兽为对象可以发动。将该怪兽除外，从牌组将１只攻击力低于该怪兽原本攻击力的电子界族怪兽加入手牌。以此效果除外的怪兽将在下个自己的准备阶段放回场上，该回合可直接攻击。','\r',char(13)),'\n',char(10)),'「电脑网后门」效果适用中','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43841694,'魔导书的奇迹','可选择我方墓地的１只魔法师族超量怪兽，以及从游戏中被除外的我方冠有“魔导书”之名的魔法卡最多２张并发动。特殊召唤被选择怪兽，将被选择的魔法卡叠放至该怪兽的下方作为超量素材。“魔导书的奇迹”１回合只可发动１张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43845801,'究极爆裂弹','①：以自己场上１只被融合召唤的“青眼究极龙”为对象可以发动。此回合，该怪兽在１次战斗阶段中可攻击３次，该怪兽攻击的情况下，对手直至伤害步骤结束时为止，不可发动魔法・陷阱・怪兽的效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43857222,'天平魔法秤',replace(replace('←5 【灵摆】 5→\r\n此卡名的灵摆效果1回合仅可使用1次。①：宣言1～6为止的任意等级，以自己场上的2只表侧表示怪兽为对象可以发动。直至回合结束时为止，其中1只对象怪兽的等级下降所宣言等级数值，另1只怪兽的等级上升所宣言等级的数值。\r\n【怪兽效果】\r\n拥有想法的天秤。维护着世间的平衡，但时而会在错误一方放上星锤。','\r',char(13)),'\n',char(10)),'改变等级','请选择要下降等级的怪兽','请选择要上升等级的怪兽','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43863925,'驱魔姐妹・斯特拉',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己的主要阶段可以发动。从手牌将1只“驱魔姐妹”怪兽特殊召唤。然后，自己场上存在“驱魔姐妹・以利斯”的情况下，自己恢复800LP。\r\n②：有自己或对手的卡因对手从墓地离开的情况下可以发动。从额外牌组将1只“驱魔姐妹”超量怪兽重叠在自己场上的此卡上面，视为超量召唤特殊召唤。','\r',char(13)),'\n',char(10)),'','超量召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43871165,'狱神影机－宙格黎多',replace(replace('←1 【灵摆】 1→\r\n此卡名的灵摆效果1回合仅可使用1次。\n①：在自己的主要阶段可以发动。将此卡与自己手牌・场上（表侧表示）的1只“狱神”怪兽或“终刻”怪兽破坏。然后，可将场上的1张卡破坏。\r\n【怪兽效果】\r\n此卡名在规则上也视为“终刻”卡。\n此卡名的①②怪兽效果1回合仅可各使用1次。\n①：从牌组上面将3张卡以里侧除外可以发动。将此卡破坏，从额外牌组将1只“坏狱神 朱庇特”视为超量召唤特殊召唤。然后，可挑选自己的1张手牌作为其超量素材。\n②：此卡以表侧加入额外牌组的情况下可以发动。从牌组将1张“狱神”魔法・陷阱卡或“终刻”魔法・陷阱卡加入手牌。','\r',char(13)),'\n',char(10)),'破坏效果','特殊召唤','检索效果','是否把场上的卡破坏？','是否把手牌作为超量素材？','','','','','','','','','','','');
INSERT INTO texts VALUES(43886072,'调皮宝贝・汪汪狗',replace(replace('“调皮宝贝”怪兽２只\r\n具此卡名的②效果１回合只能使用１次。\r\n①：此卡连接端的“调皮宝贝”怪兽攻击力上升１０００点。\r\n②：在对手回合解放此卡后，以我方墓地中除连接怪兽外的２张“调皮宝贝”卡为目标可发动（同名卡最多１张）。将该卡加入手牌。此外，本回合我方场上的“调皮宝贝”怪兽不会被对手的效果破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43889633,'忘却之海底神殿',replace(replace('①：此卡只要存在于魔法与陷阱区域，卡名视为“海”。\r\n②：1回合1次，以自己场上的1只等级4以下的鱼族・海龙族・水族怪兽为对象可以发动。将该自己的等级4以下的鱼族・海龙族・水族怪兽除外。\r\n③：以此卡②效果将怪兽除外的情况下，在自己的结束阶段发动。将该除外状态的怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'是否现在使用「忘却之海底神殿」效果？','除外','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43892408,'龙骑士黑魔导女孩',replace(replace('“黑魔导女孩”＋龙族怪兽\r\n此卡仅可通过以上述卡为融合素材的融合召唤及“提玛欧斯之眼”的效果特殊召唤。\r\n①：在每个自己・对手回合中1次，将1张手牌送至墓地，以场上的1张表侧表示的卡为对象可以发动。将该表侧表示的卡破坏。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43892409,'龙骑士黑魔导女孩',replace(replace('“黑魔导女孩”＋龙族怪兽\r\n此卡仅可通过以上述卡为融合素材的融合召唤及“提玛欧斯之眼”的效果特殊召唤。\r\n①：在每个自己・对手回合中1次，将1张手牌送至墓地，以场上的1张表侧表示的卡为对象可以发动。将该表侧表示的卡破坏。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43898403,'双龙卷','①：舍弃1张手牌，以场上的最多2张魔法・陷阱卡为对象可以发动。将该卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43904702,'杀手旋律・酷莉普',replace(replace('要以场上的此卡作为素材同步召唤的情况下，可将手牌的1只协调也作为同步素材。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡存在于手牌的情况下，在对手的主要阶段可以发动。将此卡特殊召唤。然后，可进行1只同步怪兽的协调的同步召唤。\r\n②：此卡作为同步素材被送至墓地的情况下可以发动。随机除外对手额外牌组的1张里侧卡。','\r',char(13)),'\n',char(10)),'特殊召唤','除外额外','是否进行同步召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43905751,'魔人枪','从口中发射子弹进行攻击的生物武器。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43906884,'黑羽－地雷','被盖牌的此卡因对手效果被破坏时，我方场上存在有冠有“黑羽”之名怪兽的场合，给予对手生命１０００点伤害，我方从牌组抽取１张卡牌。','伤害和抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43912676,'异层空间',replace(replace('①：场上幻龙族怪兽的攻击力、守备力上升３００。\r\n②：１回合１次，可从我方墓地将３只幻龙族怪兽除外，并以场上的１张卡牌为对象发动。破坏该卡。','\r',char(13)),'\n',char(10)),'卡片破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43925870,'风场次代机',replace(replace('“次代机・控制者”＋协调以外的风属性怪兽１只以上\r\n①：此卡的攻击力上升相当于场上里侧表示的魔法・陷阱卡的数量×３００的数值。\r\n②：将１张手牌送至墓地，以场上１张里侧表示的魔法・陷阱卡为对象可以发动。将该里侧表示卡破坏。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43930492,'魔法伟人',replace(replace('此卡名的③的效果１回合只可使用１次。\r\n①：只要此卡存在于怪兽区，每次我方或对手发动魔法卡，放置１个魔力计数物在此卡。\r\n②：此卡的等级上升相当于此卡魔力计数物的数量。\r\n③：可移除此卡的３个魔力计数物，并以我方墓地的１张速攻魔法卡为对象发动。将该卡牌盖牌至我方的魔法与陷阱区域。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43932352,'百臂无形引导手',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：解放自己场上的1只“百臂无形”怪兽或原本持有者为对手的怪兽可以发动。获得对手场上的1只怪兽的控制权。\r\n②：在自己的结束阶段发动。将自己场上的1张卡送至墓地。','\r',char(13)),'\n',char(10)),'获取控制权','送至墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43932460,'大植然陆龟',replace(replace('地属性协调＋１只以上协调以外的地属性怪兽\r\n①：此卡以外的怪兽的效果发动时，从手牌将１张魔法卡送至墓地可以发动。此卡在场上以表侧表示存在的情况下，将该效果无效并破坏。','\r',char(13)),'\n',char(10)),'效果怪兽的效果发动无效并破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43940008,'决斗塔 阿尔卡特拉斯',replace(replace('①：在自己・对手的战斗阶段开始时发动。双方可分别从自身的牌组挑选１只攻击力？以外的怪兽。双方确认所挑选的怪兽，以里侧表示除外。挑选了攻击力最高的怪兽的玩家可从手牌特殊召唤１只怪兽。以此效果特殊召唤的怪兽可直接攻击。\r\n②：在自己・对手的结束阶段可以发动。在下一个自己回合的结束阶段，此卡存在于场上的情况下，将场上的卡全部破坏。','\r',char(13)),'\n',char(10)),'','','是否从手牌特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43944080,'妮梦雷莉娅的守梦者－库艾特','此卡名以①方法的特殊召唤１回合仅可进行１次，且②效果１回合仅可使用１次。①：自己的额外牌组存在表侧表示的灵摆怪兽的情况下，此卡可从手牌中特殊召唤。②：自己的额外牌组存在表侧表示的“眠梦中的妮梦雷莉娅”，且对手发动以自己场上的“妮梦雷莉娅”卡为对象的效果时，从额外牌组将１张里侧表示的卡以里侧表示除外可以发动。将该发动无效。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43959432,'变形粘土要塞',replace(replace('①：可以我方场上１只等级４或以上的怪兽为对象发动。此卡发动后，变成效果怪兽（岩石族、地、星４、攻／守１０００），特殊召唤至怪兽区。之后，将对象的表侧表示怪兽视为装备卡装备此卡。此卡也可被视为陷阱卡。\r\n②：以此卡效果特殊召唤而来的此卡的攻击力、守备力上升以此卡效果装备之怪兽的攻击力数值，并此卡在进行了攻击的伤害步骤结束时变成守备表示。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43973174,'唤龙笛','①：从手牌将最多２只龙族怪兽特殊召唤。此效果在场上有“龙之主宰－龙的支配者”存在的情况下才能发动和处理。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43986064,'巨星坠落',replace(replace('应对此卡的发动，不可发动不拥有等级的怪兽的效果。\r\n①：以场上的１只不拥有等级的表侧表示怪兽为对象可以发动。该表侧表示的怪兽直至回合结束时为止，攻击力变为０，效果不可发动，不会因战斗被破坏。此回合，因该表侧表示怪兽的战斗对双方造成的战斗伤害变为一半。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43989315,'召唤兽 索拉特',replace(replace('“阿莱斯特”怪兽＋炎・风属性怪兽\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己・对手的主要阶段，以自己或对手墓地的1只等级6以下的怪兽为对象可以发动。将该怪兽以守备表示特殊召唤至自己场上。以此效果特殊召唤的怪兽的效果无效化。\r\n②：此卡存在于墓地的情况下可以发动。将包含墓地的此卡在内的、自己场上・墓地的怪兽作为融合素材除外，将1只“召唤兽”融合怪兽融合召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','融合效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(43994202,'迅捷三分利',replace(replace('此卡牌名的卡牌，１回合只可发动１张。\r\n①：我方场上的怪兽仅是除衍生物以外的３只同名怪兽的场合可发动。从牌组将３只同名怪兽加入手牌。此卡发动后，直至回合结束时，我方不可通常召唤、特殊召唤因此效果而加入手牌的怪兽与该同名怪兽，该怪兽不可发动效果。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44001993,'黑色混元之魔术师 黑暗混沌',replace(replace('以“光与暗的仪式”降临\r\n此卡名的①③效果1回合仅可各使用1次。\r\n①：此卡特殊召唤的情况下可以发动。从自己墓地将1张魔法卡加入手牌。\r\n②：只要此卡存在于怪兽区域，自己场上的魔法・陷阱卡就不会因对手的效果被破坏、不可因对手的效果除外，此卡不受对手发动的效果影响，除非是以此卡为对象的效果。\r\n③：以对手场上的1张卡为对象可以发动。将该卡以里侧除外。','\r',char(13)),'\n',char(10)),'回收魔法','里侧除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44001994,'黑色混元之魔术师 黑暗混沌',replace(replace('以“光与暗的仪式”降临\r\n此卡名的①③效果1回合仅可各使用1次。\r\n①：此卡特殊召唤的情况下可以发动。从自己墓地将1张魔法卡加入手牌。\r\n②：只要此卡存在于怪兽区域，自己场上的魔法・陷阱卡就不会因对手的效果被破坏、不可因对手的效果除外，此卡不受对手发动的效果影响，除非是以此卡为对象的效果。\r\n③：以对手场上的1张卡为对象可以发动。将该卡以里侧除外。','\r',char(13)),'\n',char(10)),'回收魔法','里侧除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44009443,'影星轨道兵器 无双九头蛇','此卡不可通常召唤。仅可在自己墓地有5只以上怪兽存在，且这些怪兽的卡名全部不同的情况下特殊召唤。①：1回合1次，从自己的牌组上面将3张卡送至墓地可以发动。自己墓地的怪兽的卡名全部不同的情况下，挑选场上的1张卡破坏。此效果在对手回合中也可以发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44026393,'幻兽机雷电貂',replace(replace('①：弃掉１张手牌可发动。在我方场上特殊召唤１只“幻兽机衍生物”（机械族・风・星３・攻／守０）。发动此效果后，直到回合结束，我方不能将非“幻兽机”怪兽用作融合・同调・超量・连接召唤的素材。\r\n②：此卡的等级仅按我方场上的“幻兽机衍生物”等级总数提升。\r\n③：只要我方场上有衍生物存在，此卡不会被战斗／效果破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44026394,'幻兽机衍生物','由名称中带有“幻兽机”的怪兽等的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44028461,'黑色归还','我方回合可发动。选择我方墓地１只攻击力是２０００或以下的冠有“黑羽”之名的怪兽特殊召唤。发动此卡的回合，我方不可通常召唤怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44035031,'重力战士',replace(replace('协调＋协调以外的怪兽１只或以上\r\n此卡同步召唤成功时，此卡的攻击力上升对手场上表侧表示怪兽数量×３００点。１回合１次，在对手的战斗阶段时，可选择１只对手场上的守备表示怪兽并发动。将被选择的怪兽变成攻击表示。此回合，该怪兽是可攻击的场合必须攻击。','\r',char(13)),'\n',char(10)),'攻击上升','改变表示形式','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44046281,'次元之门','可选择我方场上的１只怪兽发动此卡。以表侧表示将被选择的我方怪兽从游戏中除外。另外，对手怪兽直接攻击宣言时可发动。将场上表侧表示的此卡送入墓地。此卡被送入墓地的场合，可特殊召唤因此卡效果而除外的怪兽。','送至墓地','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44052074,'古代机械齿轮弹射器','此卡名的①②效果１回合１次，仅可使用其中１个。①：自己场上不存在怪兽的情况下，以自己场上的１张表侧表示卡为对象可以发动。破坏该卡，从牌组将１只“古代机械齿轮”怪兽无视召唤条件特殊召唤。②：将墓地的此卡除外，以自己场上的１张表侧表示卡为对象可以发动。将该卡破坏，将１只“古代机械齿轮衍生物”（机械族・地・星１・攻／守０）特殊召唤至自己场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44052075,'古代机械齿轮衍生物','由“古代机械齿轮弹射器”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44072894,'物资采购员','反转：将因融合而被送入我方墓地的２只融合素材怪兽加入到手牌中。','加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44073668,'水鱼鳍龙','身上长有鳍，在水中也能自由活动的海龙同类。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44088292,'进化合兽二氧碳鬼神',replace(replace('①：只要此卡存在于场上、墓地，被视为通常怪兽。\r\n②：被视为场上的通常怪兽的此卡，可作为通常召唤再１次召唤。此种场合此卡被视为效果怪兽获得以下效果。\r\n●只要此卡存在于怪兽区，二重怪兽的召唤不被无效化。\r\n●１回合１次，可将我方墓地的１只二重怪兽除外，并以对手场上的１张卡牌为对象发动。破坏该卡牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44092304,'梦迷枕 异睡貘',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：在自己・对手的结束阶段可以发动。将装备怪兽破坏。\r\n②：此卡因装备怪兽被破坏并被送至墓地而被送至墓地的情况下可以发动。将１只原本种族・属性・攻击力与装备过此卡的怪兽相同的“异睡貘衍生物”（星１・攻？／守０）特殊召唤至自己场上。然后将此卡装备于该衍生物。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44092305,'异睡貘衍生物','由「梦迷枕 异睡貘」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44094981,'地缚戒隶 地画格里芬',replace(replace('暗属性协调＋协调以外的怪兽１只以上\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：在自己・对手回合可以发动。从自己的墓地将“地缚戒隶 地画格里芬”以外的１只“地缚”怪兽以守备表示特殊召唤。此回合，自己从额外牌组仅可特殊召唤融合・同步怪兽。\r\n②：此卡被对手破坏的情况下可以发动。将场上的１张卡破坏。然后，给予对手相当于自己场上・墓地的“地缚”怪兽种类数量×３００的伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44095762,'神圣防护罩－反射镜力－','①：对手怪兽攻击宣言时可以发动。将对手场上攻击表示的怪兽全部破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44097050,'幻兽机 曙光女神百头龙',replace(replace('机械族怪兽２只以上\r\n①：此卡连接召唤成功的情况下可以发动。将３只“幻兽机衍生物”（机械族・风・星３・攻／守０）特殊召唤至自己场上。此回合自己不可连接召唤。②：１回合１次，解放自己场上最多３只怪兽可以发动。根据解放怪兽的数量适用以下效果。\r\n●１只：挑选场上的１张卡破坏。\r\n●２只：从牌组将１只“幻兽机”怪兽特殊召唤。\r\n●３只：从自己的墓地挑选１张陷阱卡加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤衍生物','解放怪兽','1只：选场上1张卡破坏','2只：从牌组把1只「幻兽机」怪兽特殊召唤','3只：从自己墓地选1张陷阱卡加入手牌','','','','','','','','','','','');
INSERT INTO texts VALUES(44097051,'幻兽机衍生物','由名称中带有“幻兽机”的怪兽等的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44125452,'蔷薇之妖精','①：以效果将此卡从自己牌组加入手牌的情况下可以发动。将此卡特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44133040,'塞勒涅的咒眼',replace(replace('此卡仅限装备“咒眼”怪兽。\r\n此卡牌名的③效果１回合只可使用１次。\r\n①：装备怪兽不会因战斗以及对手的效果被破坏，也不会成为对手效果的对象。\r\n②：每次我方发动装备怪兽的效果或除此卡以外的“咒眼”魔法、陷阱卡发动。装备怪兽的攻击力上升５００，我方失去５００LP。\r\n③：此卡存在于墓地的场合，可支付１０００LP，从我方墓地除外１张除“塞勒涅的咒眼”以外的“咒眼”魔法、陷阱卡并发动。将此卡盖牌在我方场上。','\r',char(13)),'\n',char(10)),'攻击力上升并失去基本分','此卡在自己场上放置','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44139064,'巨机人都市',replace(replace('此卡牌名的①②效果１回合只可各使用１次，发动此效果的回合，我方只可从额外牌组特殊召唤融合怪兽。\r\n①：可以除此卡以外的我方场上的１张卡牌为对象发动。破坏该卡牌，并从牌组将１张“机人”卡牌加入手牌。\r\n②：可在我方的“机人”怪兽进行战斗的伤害计算时，从牌组将１只“机人”怪兽送入墓地并发动。进行该战斗的我方怪兽，仅限在该伤害计算时，将其原本攻击力与原本守备力相互交换。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44146295,'冰剑龙 镜翠幻种',replace(replace('“阿尔白斯之落胤”＋融合・同步・超量・连接怪兽\r\n①：“冰剑龙 镜翠幻种”在自己场上仅可有1张以表侧表示存在。\r\n②：在每个自己・对手回合中1次，从额外牌组将1只需以“阿尔白斯之落胤”作为融合素材的融合怪兽送至墓地可以发动。将场上的1只怪兽除外。在下个回合，此卡不可使用此效果。\r\n③：融合召唤的此卡因对手从场上离开的情况下可以发动。在此回合的结束阶段，将对手场上的怪兽全部破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44146296,'冰剑龙 镜翠幻种',replace(replace('“阿尔白斯之落胤”＋融合・同步・超量・连接怪兽\r\n①：“冰剑龙 镜翠幻种”在自己场上仅可有1张以表侧表示存在。\r\n②：在每个自己・对手回合中1次，从额外牌组将1只需以“阿尔白斯之落胤”作为融合素材的融合怪兽送至墓地可以发动。将场上的1只怪兽除外。在下个回合，此卡不可使用此效果。\r\n③：融合召唤的此卡因对手从场上离开的情况下可以发动。在此回合的结束阶段，将对手场上的怪兽全部破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44155002,'魔轰神兽尤尼科尔',replace(replace('“魔轰神”协调＋协调以外的怪兽1只以上\r\n①：只要此卡存在于怪兽区域，且双方手牌张数相同，对手发动的魔法・陷阱・怪兽效果将无效化并被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44161893,'转生炎兽 类斑马X',replace(replace('此卡名在规则上也视为“机人”卡。此卡名的①效果1回合仅可使用1次。①：此卡存在于墓地，自己的“转生炎兽”连接怪兽因对手的效果从场上离开的情况下可以发动。从自己的墓地挑选包括此卡的2只等级4“转生炎兽”怪兽，将其效果无效并特殊召唤，仅以该2只作为素材，将1只“转生炎兽”怪兽超量召唤。②：以场上的此卡作为素材超量召唤的怪兽将获得以下效果。\r\n●此卡的攻击力上升相当于此卡超量素材数量×300的数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44163252,'女战神・六女',replace(replace('此卡牌名的①②效果１回合只可各使用１次。\r\n①：此卡特殊召唤成功的场合可发动。从牌组特殊召唤１只除“女战神・六女”以外的“女战神”怪兽。\r\n②：在我方主要阶段可发动。从对手牌组的上方将２张卡牌送入墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44175358,'分裂涡虫',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：将场上的此卡除外可以发动。从牌组将2只同名的昆虫族・等级3怪兽特殊召唤。以此效果特殊召唤的怪兽的效果无效化，将在结束阶段被除外。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44178886,'光道武僧 爱琳','①：此卡攻击守备表示怪兽的伤害计算前发动。将该怪兽放回持有者的牌组。②：在自己的结束阶段发动。从自己的牌组上面将3张卡送至墓地。','返回牌组','从牌组送3张卡去墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44179224,'魔界剧团－启幕人',replace(replace('←7 【灵摆】 7→\r\n此卡名的灵摆效果在决斗中仅可使用１次。①：自己场上不存在怪兽的情况下可以发动。将灵摆区域的此卡特殊召唤。\r\n【怪兽效果】\r\n①：自己场上不存在此卡以外的怪兽的情况下，此卡的攻击力上升１１００。②：１回合１次，从牌组将１张“魔界剧本”魔法卡送至墓地可以发动。从自己的额外牌组将１只表侧表示“魔界剧团”灵摆怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44182827,'轮回转生','为进行仪式召唤而解放的怪兽不送入墓地，直接返回至持有者牌组。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44186624,'DDD制霸王皇帝',replace(replace('①：此卡灵摆召唤成功的场合发动。直至回合结束时，对手场上表侧表示卡牌的效果变成无效。\r\n②：此卡灵摆召唤成功回合的主要阶段，最多可以我方魔法与陷阱区域的２张卡牌为对象发动１次。破坏该卡。此回合，此卡在１次的战斗阶段中，除了通常攻击以外，最多可再发动以此效果破坏之卡牌数量的攻击。','\r',char(13)),'\n',char(10)),'效果无效','多次攻击','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44190146,'德梅特爷爷',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：去除自己的“珂珑公主”的１个超量素材可以发动。从自己的墓地挑选最多２只攻击力或守备力为０的通常怪兽，视为暗属性・等级８怪兽以守备表示特殊召唤。\r\n②：自己的超量怪兽去除作为超量素材的通常怪兽发动效果的情况下，以该１只超量怪兽和对手场上的１只怪兽为对象可以发动。将该对手怪兽破坏，给予对手相当于对象超量怪兽的阶级×３００的伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44201739,'米拉与火柴之子',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n \r\n①：此卡存在于手牌的情况下可以发动。从手牌・牌组将同名卡存在于对手墓地的３张卡出示给对手（同名卡最多１张），将此卡特殊召唤。 \r\n②：对手发动魔法・陷阱・怪兽的效果时，将以此卡的①效果特殊召唤的此卡送至墓地可以发动。从牌组・额外牌组将１张对手所发动的该卡的同名卡送至墓地，将该发动无效。','\r',char(13)),'\n',char(10)),'从手牌特殊召唤','发动无效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44203504,'机械军曹','侍奉机械王的机械族司令塔。以统帅机械军队，且采取攻击性强用兵策略而闻名。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44209392,'城壁','选择１只以表侧表示存在于场上的怪兽发动此卡。令所选择怪兽的守备力上升５００点，直到结束阶段时。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44221928,'褒誉的吐息',replace(replace('风属性仪式怪兽的降临所必需。\r\n①：为使合计等级与仪式召唤的怪兽相等，解放自己手牌・场上的怪兽，从手牌将１只风属性仪式怪兽仪式召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44223284,'深海王魔鬼鲨鱼','仅限１回合１次，不会因不以此卡为对象的卡牌的效果而被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44227727,'海造贼－新船舶船运',replace(replace('具此卡名的②效果１回合只能使用１次。\r\n①：从自己的手牌／场上将由恶魔族融合怪兽指定的融合素材怪兽送至墓地，从额外卡组融合召唤１只该融合怪兽。\r\n②：从墓地将此卡除外，以我方场上１只“海造贼”怪兽为目标可发动。从卡组将１张“海造贼－象征”装备给我方该怪兽，从卡组将１张“海造贼”怪兽当作装备卡装备给我方该怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44236692,'死灵连接者','可释放此卡，并选择我方墓地１只冠有“同步士”之名的协调发动。特殊召唤被选择怪兽。以此效果特殊召唤的怪兽，此回合不可作为同步素材。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44241999,'格布林百罗刹 格里阿雷三杰',replace(replace('等级３怪兽×２只以上\r\n①：场上的超量素材为３个以上的情况下，自己的“格布林”怪兽可直接攻击。\r\n②：１回合１次，此卡存在于怪兽区域的状态下，怪兽被召唤・特殊召唤的情况下，以其中１只为对象可以发动。去除场上的１个超量素材，变更对象怪兽的表示形式。\r\n③：１回合１次，对手怪兽攻击宣言时可以发动。去除场上的１个超量素材，将该攻击无效。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44250812,'我我我书记','①：自己场上有“我我我书记”以外的“我我我”怪兽存在的情况下，此卡可从手牌中特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44256816,'独奏第１乐章',replace(replace('此卡名的卡１回合仅可发动１张，发动此卡的回合中，自己仅可特殊召唤“幻奏”怪兽。\r\n①：自己场上不存在怪兽的情况下可以发动。从手牌・牌组将１只等级４以下的“幻奏”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44265115,'大脑控制者',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将1张“洗脑”加入手牌。\r\n②：自己支付了LP的情况下，以场上的1只表侧表示怪兽为对象，宣言1～8为止的任意等级可以发动。该怪兽的等级变为所宣言的等级。\r\n③：此卡作为同步素材被送至墓地的情况下可以发动。将此卡的效果无效并以守备表示特殊召唤至对手场上。','\r',char(13)),'\n',char(10)),'检索效果','改变等级','特殊召唤','请选择要改变的等级','','','','','','','','','','','','');
INSERT INTO texts VALUES(44273680,'辉天使 书籍','１回合１次，可将手牌的１张魔法卡送入墓地并发动。从手牌特殊召唤１只冠有“辉天使”之名的怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44287299,'传说之剑豪 MASAKI','据传已达成百人斩的传说级剑豪。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44293356,'巨石异物・阿特拉普尔隆',replace(replace('以“巨石异物”卡降临\r\n此卡仅可通过仪式召唤方式特殊召唤，且仪式召唤仅可使用仪式怪兽。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：向对手出示手牌的此卡可以发动。此回合，应对自己的“巨石异物”仪式怪兽的效果的发动，对手不可发动效果。\r\n②：对手发动卡的效果时可以发动。将该发动无效并破坏。以此效果将以场上的卡为对象的效果的发动无效的情况下，进而可将对手场上的1只怪兽解放。','\r',char(13)),'\n',char(10)),'反制连锁','发动无效','是否把怪兽解放？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44297127,'奇迹之穿孔',replace(replace('此卡名的卡在1个回合中仅可发动1张。\r\n①：将牌组中1只等级4以下的岩石族怪兽送至墓地。自己墓地中存在“化石融合”卡时，自己再从牌组中抽1张卡。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44308317,'冰结界的依巫',replace(replace('此卡名的①③效果１回合仅可各使用１次。\r\n①：自己场上存在“冰结界”怪兽的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：只要自己场上存在其他“冰结界”怪兽，对手场上守备表示的怪兽不可变更表示形式。\r\n③：自己场上存在“冰结界”怪兽的情况下，将墓地的此卡除外可以发动。将１只“冰结界衍生物”（水族・水・星１・攻／守０）特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44308318,'冰结界衍生物','由“冰结界的依巫”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44311445,'魔幻甜点・布丁公主・巧克力风味',replace(replace('地属性等级５怪兽×２\r\n此卡也可重叠在自己场上的阶级４以下的“魔幻甜点”超量怪兽上面来超量召唤。\r\n①：１回合１次，以自己墓地的１张“魔幻甜点”卡为对象可以发动。将该卡放回牌组。\r\n②：此卡持有“魔幻甜点・布丁公主”作为超量素材的状态下，自己墓地的“魔幻甜点”卡放回牌组时，去除此卡的１个超量素材可以发动。从牌组将１只“魔幻甜点”怪兽以表侧攻击表示或里侧守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'是否在「魔幻甜点」超量怪兽上面重叠来超量召唤？','回到牌组','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44330098,'冥府之使者格斯',replace(replace('①：因对手使自己受到战斗・效果伤害时可以发动（此效果在自己场上不存在卡的情况下才能发动和处理）。从手牌将此卡特殊召唤。\r\n②：以此卡的①方法特殊召唤的情况下，根据所受到的伤害的种类，发动以下效果。\r\n●战斗伤害：将1只“冥府之使者凯茵衍生物”（天使族・光・星7・攻/守？）特殊召唤至自己场上。此衍生物的攻击力・守备力变为与此时所受伤害相同的数值。\r\n●效果伤害：给予对手相当于所受伤害数值的伤害。','\r',char(13)),'\n',char(10)),'特殊召唤','特殊召唤衍生物','给与伤害','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44330099,'冥府的使者凯恩衍生物','由“冥府的使者格斯”的效果特殊召唤而来。此衍生物的攻击力和守备力将与玩家在“冥府的使者格斯”被特殊召唤时所受到的战斗伤害相同。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44330100,'冥府之使者格斯',replace(replace('①：因对手使自己受到战斗・效果伤害时可以发动（此效果在自己场上不存在卡的情况下才能发动和处理）。从手牌将此卡特殊召唤。\r\n②：以此卡的①方法特殊召唤的情况下，根据所受到的伤害的种类，发动以下效果。\r\n●战斗伤害：将1只“冥府之使者凯茵衍生物”（天使族・光・星7・攻/守？）特殊召唤至自己场上。此衍生物的攻击力・守备力变为与此时所受伤害相同的数值。\r\n●效果伤害：给予对手相当于所受伤害数值的伤害。','\r',char(13)),'\n',char(10)),'特殊召唤','特殊召唤衍生物','给与伤害','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44335251,'食魂窃蛋龙',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组挑选1只恐龙族怪兽，加入手牌或送至墓地。\r\n②：以场上1只其他的等级4以下的恐龙族怪兽为对象可以发动。将该怪兽破坏。然后，从自己墓地将1只恐龙族怪兽以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'恐龙族怪兽加入手牌或送至墓地','破坏并特殊召唤','请选择要加入手牌或送至墓地的卡','是否加入手牌？','','','','','','','','','','','','');
INSERT INTO texts VALUES(44341034,'黑暗异虫','此卡召唤成功时，选择我方墓地的１只等级３的协调并特殊召唤。以此效果特殊召唤的怪兽效果被无效化。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44352516,'电子黑暗狱火',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：装备有装备卡的、自己场上的“电子暗黑”效果怪兽不会因对手的效果被破坏，且对手不可将其作为效果的对象。\r\n②：以自己场上的1只“电子暗黑”怪兽为对象可以发动。将该怪兽放回手牌。然后，可进行1只“电子暗黑”怪兽的召唤。\r\n③：场上的此卡因对手的效果被破坏的情况下可以发动。从牌组将1张“融合”魔法卡或“结合”魔法卡加入手牌。','\r',char(13)),'\n',char(10)),'是否把「电子黑暗」怪兽召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44362883,'烙印融合',replace(replace('此卡名的卡1回合仅可发动1张，发动此卡的回合中，自己从额外牌组仅可特殊召唤融合怪兽。\r\n①：将自己手牌・牌组・场上的2只怪兽作为融合素材，将1只需以“阿尔白斯之落胤”作为融合素材的融合怪兽融合召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44364077,'娱乐伙伴・军队虎',replace(replace('“娱乐伙伴・军队虎”的效果１回合只可使用１次。\r\n①：此卡因战斗破坏对手怪兽并送入墓地时可发动。从牌组将１只“娱乐伙伴”灵摆怪兽加入手牌。','\r',char(13)),'\n',char(10)),'牌组检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44364207,'翡翠骑士','①：只要此卡在怪兽区域以攻击表示存在，自己场上的攻击力为1200以下的机械族怪兽就不会被陷阱卡的效果破坏。②：此卡因战斗被破坏且送至墓地时可以发动。从牌组将1只机械族・光属性・等级4的怪兽加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44373896,'破坏龙',replace(replace('此卡仅可在以“克里底亚之牙”的效果将自己手牌・场上的“破坏轮”送至墓地的情况下特殊召唤。\r\n①：１回合１次，以对手场上的１张卡为对象可以发动。将该卡破坏。然后，所破坏的卡是怪兽卡的情况下，给予对手相当于其原本攻击力数值的伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44376395,'局域阿修罗－U1000型',replace(replace('种族和属性不同的怪兽2只\r\n此卡名的②③效果1回合仅可各使用1次。\r\n①：此卡连接端的仪式怪兽攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。\r\n②：向对手出示手牌的1只仪式怪兽可以发动。从牌组将种族和属性与所出示的怪兽不同的1只仪式怪兽加入手牌。\r\n③：自己将怪兽仪式召唤的情况下，以对手场上的1张表侧表示卡为对象可以发动。将该卡放回手牌。','\r',char(13)),'\n',char(10)),'','检索','回到手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44394295,'影依结合',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：将自己手牌・场上的怪兽作为融合素材，将1只“影依”融合怪兽融合召唤。对手场上存在被从额外牌组特殊召唤的怪兽的情况下，也可将自己牌组的怪兽作为融合素材。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44397496,'真红眼灵魂','①：可将我方墓地的１只“真红眼”怪兽作为对象发动。特殊召唤该怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44405066,'真红眼钢炎龙',replace(replace('等级７怪兽×２\r\n①：拥有超量素材的此卡不会因效果被破坏。②：只要拥有超量素材的此卡存在于怪兽区域，每次对手发动魔法・陷阱・怪兽的效果，给予对手５００伤害。③：１回合１次，去除此卡的１个超量素材，以自己墓地的１只“真红眼”通常怪兽为对象可以发动。将该怪兽特殊召唤。此效果在对手回合中也可以发动。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44413654,'变形斗士・冲击归来',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：以对手场上的最多２张魔法・陷阱卡为对象可以发动。从手牌将１只“变形斗士”怪兽放回牌组，将对象卡放回持有者的牌组。\r\n②：将墓地的此卡除外，从自己墓地的怪兽及自己被除外的怪兽中，以１只“变形斗士”怪兽为对象可以发动。以守备表示形式将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44424095,'变形斗士・速度装备','可选择场上的１张卡牌并发动。将手牌的１只冠有“变形斗士”之名的怪兽返回至牌组并洗牌。之后，破坏被选择卡牌，从牌组抽取１张卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44430454,'六武众之侍从','在背后支持六武众的神秘人物。虽然现在已不再战斗，但身上留下的无数伤痕似乎在诉说着什么。其过去无人知晓。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44436472,'双价体','①：上级召唤暗属性怪兽的情况下，此卡可作为２只解放。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44440058,'星义・基石','此卡名的①②效果１回合仅可各使用１次。①：以“星义・基石”以外的、自己被除外的１只怪兽为对象可以发动。将此卡从手牌特殊召唤，将对象怪兽放回牌组。②：此卡被除外的回合的结束阶段可以发动。将此卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44451698,'妖精弓士 因古纳尔','此卡名的①效果１回合仅可使用１次。①：此卡以植物族怪兽的效果特殊召唤成功的情况下，以自己墓地１只等级６以上的植物族怪兽为对象可以发动。以守备表示形式将该怪兽特殊召唤。此效果发动后，直至回合结束时为止自己仅可特殊召唤植物族怪兽。②：此卡在特殊召唤的回合中不可攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44455560,'炎王妃 乌尔甘尼克斯',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。将此卡以外的、自己手牌・场上（表侧表示）的1只炎属性怪兽破坏，从牌组将“炎王妃 乌尔甘尼克斯”以外的1只兽族・兽战士族・鸟兽族的炎属性怪兽加入手牌。然后，可将此卡的等级改成与以此效果加入手牌的怪兽相同。\r\n②：此卡被破坏并被送至墓地的情况下可以发动。从牌组将1只“炎王神兽 迦楼多尼克斯”以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'是否变成相同等级？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44459942,'合损为新',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：从自己墓地将1只机械族・暗属性怪兽除外可以发动。从自己手牌・牌组・墓地将1只记载有“马达衍生物”的衍生物名的怪兽特殊召唤。\r\n②：此卡存在于墓地的状态下，自己场上表侧表示的机械族・暗属性怪兽因战斗以外的方法被送至墓地的情况下，将此卡除外可以发动。将1只“马达衍生物”（机械族・地・星1・攻/守200）以攻击表示特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'除外并特殊召唤','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44459943,'马达衍生物','由“恶鬼马达Ω”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44466810,'快子时空银河霸主',replace(replace('此卡名的卡１回合仅可发动１张。\r\n自己场上存在“银河眼时空龙”怪兽的情况下，此卡也可从手牌发动。\r\n①：在自己・对手的战斗阶段，去除自己场上的“银河眼”超量怪兽的１个超量素材可以发动（自己场上存在“混沌编号”怪兽的情况下，此卡的发动与效果不会被无效化）。将在此回合被召唤・特殊召唤的、对手场上的怪兽全部放回牌组。','\r',char(13)),'\n',char(10)),'全部回到牌组','适用「快子时空银河霸主」的效果来发动','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44472639,'太阳光线','给予对手LP存在于自己场上的光属性怪兽数量×６００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44478599,'圣天树之灰树精',replace(replace('包含连接怪兽在内的植物族怪兽２只以上\r\n①：此卡连接召唤的情况下可以发动。从自己的墓地将１只“圣种之地灵”特殊召唤。\r\n②：此卡不会成为攻击对象（自己场上仅存在适用此效果的怪兽的状态下，对手的攻击变为对自己的直接攻击）。\r\n③：１回合１次，以此卡连接端的自己的１只“圣蔓”连接怪兽为对象可以发动。此回合，该怪兽可攻击的次数最多为自己场上“圣天树”连接怪兽的数量。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44481227,'娱乐伙伴・下降骆驼',replace(replace('←2 【灵摆】 2→\r\n①：１回合１次，可以我方场上的１只表侧表示怪兽为对象发动。直至回合结束时，对手场上所有怪兽的守备力下降８００，此回合对象怪兽攻击了守备表示怪兽的场合，给予对手相当于攻击力超过该守备力数值的战斗伤害。\r\n【怪兽效果】\r\n①：此卡因战斗被破坏的场合可发动。破坏此卡之怪兽的攻击力下降８００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44482554,'星宿龙 潘',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡作为融合召唤的素材被送至墓地的情况下可以发动。从牌组将1张“星宿”魔法・陷阱卡放置在自己场上。然后，可将场上的1只怪兽破坏。\r\n②：此卡存在于墓地的状态下，自己场上的表侧表示融合怪兽因对手的效果被破坏的情况下可以发动。将此卡放回牌组最下面，从自己墓地将融合怪兽以外的1只“星宿”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'放置魔陷','特殊召唤','是否把怪兽破坏？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44487250,'超量阻挡','对手发动怪兽效果时，可移除我方场上的１个超量素材并发动。使该发动效果并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44505297,'甲虫装机 艾可萨兜虫',replace(replace('等级6怪兽×2\r\n①：此卡超量召唤时，以自己或对手墓地的1只怪兽为对象可以发动。将该怪兽视为装备魔法卡，装备于此卡。\r\n②：此卡的攻击力・守备力分别上升以此卡的①效果装备的怪兽对应数值的一半。\r\n③：1回合1次，去除此卡的1个超量素材，以自己及对手场上各1张表侧表示卡为对象可以发动。将该自己及对手的表侧表示卡送至墓地。','\r',char(13)),'\n',char(10)),'装备','送至墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44508094,'星尘龙',replace(replace('协调＋协调以外的怪兽1只以上\r\n①：破坏场上的卡之魔法・陷阱・怪兽的效果发动时，解放此卡可以发动。将该发动无效并破坏。\r\n②：适用此卡的①效果的回合的结束阶段可以发动。将为发动该效果解放的此卡从墓地特殊召唤。','\r',char(13)),'\n',char(10)),'破坏场上卡的效果发动无效并破坏','回合结束时特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44508095,'星尘龙',replace(replace('协调＋协调以外的怪兽1只以上\r\n①：破坏场上的卡之魔法・陷阱・怪兽的效果发动时，解放此卡可以发动。将该发动无效并破坏。\r\n②：适用此卡的①效果的回合的结束阶段可以发动。将为发动该效果解放的此卡从墓地特殊召唤。','\r',char(13)),'\n',char(10)),'破坏场上卡的效果发动无效并破坏','回合结束时特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44508096,'星尘龙',replace(replace('协调＋协调以外的怪兽1只以上\r\n①：破坏场上的卡之魔法・陷阱・怪兽的效果发动时，解放此卡可以发动。将该发动无效并破坏。\r\n②：适用此卡的①效果的回合的结束阶段可以发动。将为发动该效果解放的此卡从墓地特殊召唤。','\r',char(13)),'\n',char(10)),'破坏场上卡的效果发动无效并破坏','回合结束时特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44508097,'星尘龙',replace(replace('协调＋协调以外的怪兽1只以上\r\n①：破坏场上的卡之魔法・陷阱・怪兽的效果发动时，解放此卡可以发动。将该发动无效并破坏。\r\n②：适用此卡的①效果的回合的结束阶段可以发动。将为发动该效果解放的此卡从墓地特殊召唤。','\r',char(13)),'\n',char(10)),'破坏场上卡的效果发动无效并破坏','回合结束时特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44509529,'调皮宝贝・气象精灵',replace(replace('“调皮宝贝”怪兽×２\r\n具此卡名的②效果１回合只能使用１次。\r\n①：我方的“调皮宝贝”怪兽攻击时，对手直到伤害步骤结束时都无法发动魔法／陷阱／怪兽效果。\r\n②：在对手回合解放此卡后，以我方墓地中除融合怪兽外的２只“调皮宝贝”怪兽为目标可发动（同名卡最多１张）。特殊召唤该怪兽。用此效果特殊召唤的怪兽在本回合不会被战斗破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44509898,'精准防御','①：对手怪兽的攻击宣言时，以自己墓地１只等级４以下的怪兽为对象可以发动。以守备表示形式将该怪兽特殊召唤。以此效果特殊召唤的怪兽此回合不会因战斗・效果被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44519536,'被封印者的左足','被封印的左足。解开封印后将获得无限力量。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44536921,'捕食计划',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从牌组将1只“捕食植物”怪兽送至墓地可以发动。在场上所有表侧表示怪兽上各放1个捕食计数物。放有捕食计数物的等级2以上怪兽的等级变为1。\r\n②：此卡存在于墓地的状态下，自己将暗属性怪兽融合召唤的情况下，将此卡除外，以场上的1张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44553392,'识无边世坏','①：场上存在“维刹思・阿斯特劳德”的情况下，以场上的１张卡为对象可以发动。将该卡破坏。然后，所破坏的卡的原本卡名为“维刹思・阿斯特劳德”的情况下，可挑选自己１只被除外的“维萨思・史塔弗罗斯特”特殊召唤。不是“维刹思・阿斯特劳德”的情况下，可挑选自己场上的１只“维刹思・阿斯特劳德”，使其攻击力上升１５００。','是否选除外的怪兽特殊召唤？','是否选怪兽上升攻击力？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44573911,'R.B.钢天贯桩机',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次，且②效果1回合仅可使用1次。\r\n①：自己场上的表侧表示怪兽，不存在的情况下或均为“R.B.”怪兽的情况下，此卡可从手牌特殊召唤。\r\n②：连接端指向此卡的“R.B.野蛮蓝调”与对手怪兽进行战斗的攻击宣言时，支付1500LP可以发动。将此卡与对手场上的卡全部破坏。','\r',char(13)),'\n',char(10)),'','破坏效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44584775,'伤害＝爬虫','１回合１次，因爬虫类族怪兽的战斗方式而使我方受到战斗伤害时，可发动此效果。从牌组特殊召唤１只持有相当于受到伤害的数量或以下攻击力的爬虫类族怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44586426,'太阳电池人','此卡名的①②③效果1回合仅可各使用1次。①：此卡召唤・特殊召唤成功的情况下可以发动。从牌组将1只雷族怪兽送至墓地。②：此卡已经存在于怪兽区域的状态下，雷族怪兽被召唤・特殊召唤的情况下发动。将1只“电池人衍生物”（雷族・光・星1・攻/守0）特殊召唤至自己场上。③：以自己场上・墓地的1只“电池人”效果怪兽为对象可以发动。直至结束阶段为止，此卡视为该卡的同名卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44586427,'电池人衍生物','由“太阳电池人”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44595286,'制裁之光',replace(replace('①：场上有“天空的圣域”存在的场合，可从手牌将１只光属性怪兽舍弃至墓地并发动。从以下效果挑选１个并适用。\r\n●确认对手的手牌，从中挑选１张卡牌送入墓地。\r\n●挑选对手场上的１张卡牌送入墓地。','\r',char(13)),'\n',char(10)),'从对手场上选择1张卡送至墓地','从对手手牌选择1张卡送至墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44612603,'生存境界','①：将场上的通常怪兽全部破坏，从牌组将等级４以下的恐龙族怪兽特殊召唤至自己场上，数量最多为所破坏的数量。以此效果特殊召唤的怪兽将在结束阶段被破坏。②：将墓地的此卡除外，以自己场上的１只恐龙族怪兽和对手场上的１张卡为对象可以发动。将该卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44632120,'库里巴',replace(replace('此卡名在规则上也视为“库里波”卡。\r\n此卡名的①效果１回合仅可使用１次。\r\n①：此卡或自己的“库里波”怪兽因战斗被破坏时可以发动。从牌组将“库里巴”以外的１只攻击力３００／守备力２００的怪兽特殊召唤。\r\n②：解放场上的此卡和自己手牌・场上的“库里比”、“库里布”、“库里拜”、“库里波”各１只可以发动。从自己的手牌・牌组・墓地挑选１只“库里巴比伦”特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44635489,'星圣 水瓶夏特',replace(replace('要以此卡作为超量召唤素材的情况下，仅可使用于“星圣”怪兽的超量召唤。\r\n①：仅有对手场上才存在怪兽的情况下，此卡可从手牌特殊召唤。\r\n②：1回合1次，以此卡以外的、自己场上・墓地的1只“星圣”怪兽为对象可以发动。此卡的等级变为与该怪兽相同。','\r',char(13)),'\n',char(10)),'等级变换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44640691,'恩底弥翁之刺客',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下发动。在此卡上放1个魔力计数物。\r\n②：去除此卡的1个魔力计数物，从手牌舍弃1只魔法师族怪兽可以发动。从牌组将1张永续魔法卡放置在自己的魔法与陷阱区域。此回合，自己不可发动以此效果放置的卡及其同名卡的效果。','\r',char(13)),'\n',char(10)),'放置1个魔力计数物','将永续魔法卡放置','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44644529,'双天之转身',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：以自己场上的１只“双天”怪兽为对象可以发动。将该怪兽破坏，将１只比该怪兽原本等级高１，或原本等级低１的“双天”怪兽从牌组・额外牌组特殊召唤。\r\n②：在自己的主要阶段将墓地的此卡除外，以自己墓地的１只“双天”怪兽为对象可以发动。将该怪兽加入手牌。此效果在此卡被送至墓地的回合不可发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44649322,'传承之大御巫',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从手牌将1只“御巫”怪兽无视召唤条件特殊召唤。以此效果特殊召唤的怪兽将在对手的结束阶段被放回手牌。\r\n②：在自己的主要阶段将墓地的此卡除外可以发动。从牌组将“传承之大御巫”以外的1张“御巫”卡送至墓地。','\r',char(13)),'\n',char(10)),'特殊召唤','送至墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44654994,'神艺厚涂－夺还－',replace(replace('此卡名的卡1回合仅可发动1张。\r\n自己场上存在“神艺”怪兽的情况下，此卡在放置的回合也可以发动。\r\n①：对手发动怪兽的效果时可以发动。将自己场上的1只融合怪兽直至结束阶段为止除外，将该发动无效并破坏。然后，自己场上怪兽的种族为3种以上的情况下，可将对手场上的魔法・陷阱卡全部放回手牌。','\r',char(13)),'\n',char(10)),'发动','是否让魔法·陷阱卡回到手牌？','适用「神艺厚涂－夺还－」的效果来发动','直到结束阶段除外','','','','','','','','','','','','');
INSERT INTO texts VALUES(44656450,'失乐魔女','此卡名的①②效果1回合仅可各使用1次。①：此卡召唤成功时可以发动。从牌组将1张“禁忌的”速攻魔法卡加入手牌。②：在对手的主要阶段，解放此卡可以发动。从牌组将1只“失乐魔女”以外的天使族・等级4怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44656491,'和平使者','攻击力１５００以上的怪兽不可攻击宣言。每次自己准备阶段，此卡片的控制者支付１００LP。或不支付１００LP，将此卡片破坏。','是否要支付100基本分维持「和平使者」？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44663232,'异怪妖精 艾尔佛比亚','①：1回合1次，将手牌的1只风属性怪兽出示给对手可以发动。直至下一次对手的主要阶段1结束时为止，双方不可发动等级高于出示的怪兽的怪兽的效果。','效果抑制','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44665365,'神光之宣告者','以“宣告者之预言”降临。①：对手发动怪兽的效果・魔法・陷阱卡时，从手牌将１只天使族怪兽送至墓地可以发动。将该发动无效并破坏。','效果怪兽的效果·魔法·陷阱卡的发动无效并破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44676200,'英雄屏障','此回合，我方场上存在有冠有“元素－英雄”之名怪兽的场合，使对手怪兽的攻击仅１次无效。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44680819,'岚龙',replace(replace('①：“岚龙”在自己场上仅可有1张以表侧表示存在。\r\n②：自己场上存在魔法师族怪兽的情况下，此卡可从手牌特殊召唤。\r\n③：此卡因战斗・效果被破坏并被送至墓地的情况下，以除了“岚龙”以外的、自己墓地的1只攻击力1500/守备力200的怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44682448,'垃圾领主','此卡可支付２０００LP，并从手牌特殊召唤。以此卡为超量召唤素材的场合，仅可使用于暗属性怪兽的超量召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44686185,'影六武众－初芽',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：从自己场上（表侧表示）・墓地将2只“六武众”怪兽除外，以“影六武众－初芽”以外的、自己墓地的1只“六武众”怪兽为对象可以发动。将该怪兽特殊召唤。\r\n②：自己场上仅1只“六武众”怪兽将被效果破坏的情况下，作为代替可将墓地的此卡除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44689688,'朱罗纪・棘龙','①：此卡战斗破坏对手怪兽并将其送至墓地的情况下发动。将1只“棘龙衍生物”（恐龙族・炎・星1・攻300/守0）以攻击表示特殊召唤至对手场上。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44689689,'棘龙衍生物','由“朱罗纪・棘龙”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44694191,'假形幻脸师',replace(replace('此卡名的①效果1回合仅可使用1次，③效果在决斗中仅可使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将1只恶魔族・幻想魔族・魔法师族怪兽送至墓地。然后，可将此卡的种族改成与以此效果被送至墓地的怪兽的原本种族相同。\r\n②：此卡与怪兽进行战斗的情况下，该2只不会因该战斗被破坏。\r\n③：此卡存在于墓地的情况下，从自己墓地将1张魔法卡除外可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'送至墓地','特殊召唤','是否改变种族？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44698398,'神影金龙 胶子光龙',replace(replace('等级８怪兽×２\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡从额外牌组特殊召唤的情况下可以发动。从牌组将１张“银河”卡或“时空”卡加入手牌。\r\n②：去除此卡的２个超量素材可以发动。从额外牌组将１只龙族・阶级８・攻击力３０００的超量怪兽重叠在自己场上的此卡上面，视为超量召唤来特殊召唤。然后，可从额外牌组将１只“银河”怪兽作为其超量素材。','\r',char(13)),'\n',char(10)),'检索','叠放特殊召唤','是否把1只「银河」怪兽变成超量素材？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44702857,'拜驼隆','此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予战斗伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44708154,'浮－朋.克.惊龙',replace(replace('协调+1只以上协调以外的怪兽\r\n此卡名的①②效果1回合1次，仅可使用其中1个。①：此卡同步召唤成功的情况下，以对手场上的卡为对象可以发动，数量最多为自己场上・墓地的念动力族・等级3怪兽的种类数量。将该卡放回持有者的手牌。②：以自己墓地的1只“浮-朋.克.惊龙”以外的“朋.克.”怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44710391,'地缚地画',replace(replace('此卡名的③效果１回合仅可使用１次。\r\n①：只要场上存在等级１０怪兽，此卡不会因效果被破坏，双方不可将此卡作为效果的对象。\r\n②：只要此卡存在于场地区域，自己上级召唤“地缚神”怪兽的情况下，同步怪兽可作为２只解放。\r\n③：同步怪兽被特殊召唤的情况下可以发动。从牌组将１张“地缚神”魔法・陷阱卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44716748,'纠罪巧γ’－欺瞒“exapatisIA”',replace(replace('←0 【灵摆】 0→\r\n此卡名的②灵摆效果1回合仅可使用1次。\n①：每当有怪兽反转，就在此卡上放1个纠罪计数物。\n②：支付900LP可以发动。从牌组将3张“纠罪巧”卡出示给对手，对手从其中随机挑选1张。将该1张加入自己手牌，剩余的放回牌组。\r\n【怪兽效果】\r\n①：向对手出示手牌的此卡可以发动（发动此效果的回合中，自己仅可以里侧守备表示特殊召唤怪兽）。从手牌将1只怪兽以里侧守备表示特殊召唤。\n②：对手发动包含将卡放置的效果的、卡的效果时，将里侧表示的此卡改成表侧守备表示可以发动。从牌组将1张“纠罪巧”卡加入手牌。\n③：此卡反转的情况下发动。将对手场上的1张魔法・陷阱卡破坏，从手牌将1只怪兽以里侧守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'检索','特殊召唤','检索','破坏','','','','','','','','','','','','');
INSERT INTO texts VALUES(44716890,'通行增税','①：双方玩家必须将１张手牌送至墓地才可攻击宣言。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44717069,'海星','１回合１次，我方主要阶段时可发动。我方场上所有的“海星”等级上升１。','等级上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44728989,'再生之海',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：以自己墓地的1只攻击力1000以下的水属性怪兽为对象可以发动。将该怪兽特殊召唤。以此效果特殊召唤的怪兽将在结束阶段被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44729197,'蒸汽火车机人','此卡攻击对手怪兽的场合，伤害步骤期间攻击力上升５００点。此卡被对手怪兽攻击的场合，伤害步骤期间攻击力下降５００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44760562,'玛那桃圆乡・温顺','此卡名以①方法的特殊召唤１回合仅可进行１次。①：自己场上存在“维萨思・史塔弗罗斯特”或攻击力１５００／守备力２１００的怪兽的情况下，此卡可从手牌中特殊召唤。②：此卡因战斗・效果被破坏的情况下可以发动。从牌组将１只“玛那桃圆乡・温顺”特殊召唤。然后，以此效果特殊召唤的怪兽的等级可上升２。','','','是否上升等级？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44762290,'光学迷彩铠甲','仅限装备等级１怪兽。装备怪兽可直接攻击对手玩家。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44763025,'爱恶作剧的双子魔鬼','支付１０００LP可以发动。对手随机挑选１张手牌舍弃，对手还有手牌的情况下进而再挑选１张舍弃。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44763696,'Sin 邪调',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：自己场上的表侧表示“Sin”怪兽因战斗或对手的效果被破坏的情况下可以发动。自己抽2张。\r\n②：此卡存在于墓地的状态下，自己场上表侧表示的“Sin”怪兽因战斗以外的方法被破坏的情况下，将此卡除外可以发动。从牌组将1只“Sin”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44771289,'旅人的结彼岸','①：从自己的手牌・场上，将由“彼岸”融合怪兽卡决定的融合素材怪兽送至墓地，从额外牌组将1只该融合怪兽融合召唤。②：在自己的主要阶段将墓地的此卡除外，以场上的1只“彼岸”怪兽为对象可以发动。该怪兽的攻击力・守备力直至下一个对手回合结束时为止上升800。此效果在此卡被送至墓地的回合不可发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44789585,'大植然豆一族','此卡１回合仅１次，不会因战斗被破坏。此卡被选择为攻击对象时，给予对手LP５００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44790889,'重槌突击豹镖','对手场上存在有卡牌，而我方场上不存在有卡牌的场合，此卡可无须释放进行召唤。我方场上不存在有魔法、陷阱卡，此卡攻击对手怪兽的场合，直至伤害步骤结束时，对手不可发动魔法、陷阱卡。','不用解放召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44792253,'D.D.破坏者','场上的此卡从游戏中被除外时，可选择对手场上的１张表侧表示卡牌并破坏。','对手场上表侧表示存在的1张卡破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44800181,'连击大师','此卡以表侧表示存在于场上时，在我方主要阶段１发生连锁的场合，仅限此回合，此卡在１次的战斗阶段中可进行２次攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44811425,'异虫林克斯','只要反转的此卡以表侧表示存在于场上，每次双方的结束阶段，我方从牌组抽取１张卡牌。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44822037,'碑像天使－亚兹卢恩',replace(replace('①：此卡发动后，变为效果怪兽（天使族・光・星4・攻/守1800），特殊召唤至怪兽区域（也视为陷阱卡）。\r\n②：此卡是被以此卡的效果特殊召唤的情况下，1回合1次，对手特殊召唤怪兽之际，将自己怪兽区域的、1张被从魔法与陷阱区域特殊召唤的永续陷阱卡送至墓地可以发动。将该特殊召唤无效，将该怪兽破坏。\r\n③：此卡因战斗被破坏时可以发动。将破坏此卡的怪兽破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44839512,'超电导战士 线性麦格农±',replace(replace('此卡不可通常召唤。\r\n“超电导战士 线性麦格农±”1回合1次，从自己手牌・牌组・场上（表侧表示）将2只原本等级4以下的“磁石战士”怪兽送至墓地的情况下可以特殊召唤。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：以场上的1只其他的地属性怪兽为对象可以发动。此卡的攻击力直至回合结束时为止，上升其攻击力的一半的数值。\r\n②：此卡被破坏并被送至墓地的情况下发动。将此卡加入手牌。','\r',char(13)),'\n',char(10)),'攻击力上升','回到手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44843954,'妮梦雷莉娅的寐梦','此卡名的卡１回合仅可发动１张。①：从牌组将１只“妮梦雷莉娅”怪兽加入手牌。自己的额外牌组存在表侧表示的“眠梦中的妮梦雷莉娅”的情况下，进而此回合，“妮梦雷莉娅”怪兽的召唤・特殊召唤成功时，对手不可发动魔法・陷阱・怪兽的效果。②：将墓地的此卡放回牌组最下面，以自己场上的１张“眠梦中的妮梦雷莉娅”为对象可以发动。将该卡以表侧表示加入持有者的额外牌组。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44852429,'DDD 咒血王齐格弗里德',replace(replace('协调＋１只以上协调以外的“DD”怪兽\r\n此卡名的①效果１回合仅可使用１次。①：以场上的１张表侧表示魔法・陷阱卡为对象可以发动。该卡的效果直至下一个准备阶段为止无效化。此效果在对手回合中也可以发动。②：此卡因战斗・效果被破坏并被送至墓地的情况下发动。自己恢复相当于自己场上“契约书”卡数量×１０００的LP。','\r',char(13)),'\n',char(10)),'魔陷无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44860890,'捷炎星－鸦清',replace(replace('①：只要此卡存在于怪兽区域，自己场上的“炎舞”魔法・陷阱卡不会因对手的效果被破坏。\r\n②：此卡从场上被送至墓地的情况下可以发动。从牌组将１张“炎舞”魔法卡放置在自己场上。','\r',char(13)),'\n',char(10)),'放置','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44865098,'机械兵队','护卫机械王的兵队。用圆滚滚的身体滚着过来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44874522,'古代机械齿轮・热核反应机龙','①：解放“古代机械齿轮”怪兽来上级召唤的此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予战斗伤害。②：解放“小工具”怪兽来上级召唤的此卡在１次战斗阶段中可攻击２次。③：此卡攻击的情况下，对手直至伤害步骤结束时为止，不可发动怪兽的效果・魔法・陷阱卡。④：此卡攻击的伤害步骤结束时可以发动。挑选场上的１张魔法・陷阱卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44877690,'冰结界的神精灵',replace(replace('此卡不可特殊召唤。\r\n①：此卡召唤・反转的回合的结束阶段发动。将此卡放回手牌。自己场上存在其他“冰结界”怪兽的情况下，作为代替发动以下效果。\r\n●此卡召唤・反转的回合的结束阶段，以对手场上的１只怪兽为对象发动。将该对手怪兽放回手牌。','\r',char(13)),'\n',char(10)),'返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44883600,'双重防御者','１回合１次，我方场上存在有２只或以上表侧守备表示怪兽的场合，在对手怪兽的攻击宣言时可发动。选择１只攻击怪兽，使该攻击无效。','攻击无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44883830,'死之合唱','①：自己场上存在3只以上“死亡青蛙”的情况下可以发动。将对手场上的卡全部破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44886582,'超逸融合',replace(replace('此卡名的卡1回合仅可发动1张，应对此卡的发动，不可发动卡的效果。\r\n①：支付2000LP，以场上的1只效果怪兽为对象可以发动。从额外牌组将1只与该怪兽等级不同、种族・属性相同的怪兽的效果无效并特殊召唤。然后，从以下效果中挑选1个适用。\r\n●将以此效果特殊召唤的怪兽与对象怪兽作为融合素材，将1只融合怪兽融合召唤。\r\n●将以此效果特殊召唤的怪兽送至墓地。','\r',char(13)),'\n',char(10)),'发动','融合召唤','送至墓地','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44887817,'增草剂','①：1回合1次，以自己墓地的1只植物族怪兽为对象可以发动（发动此效果的回合中，自己不可通常召唤）。将该植物族怪兽特殊召唤。以此效果特殊召唤的怪兽从场上离开时此卡将被破坏。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44889144,'书灵师・介入',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：对手发动魔法・陷阱・怪兽的效果时，以自己场上的1只“书灵师”仪式怪兽为对象可以发动。将该怪兽放回手牌，将该发动的效果无效。然后，可从自己手牌・墓地将1只“书灵师”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','是否选1只「书灵师」怪兽特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44891812,'超重武者御助－K',replace(replace('①：我方墓地不存在有魔法、陷阱卡的场合，我方守备表示怪兽和对手怪兽进行战斗的伤害计算时，从手牌舍弃此卡，并可以１只我方场上进行了战斗的怪兽以外的“超重武者”怪兽为对象发动。进行该战斗的我方怪兽仅限伤害计算期间，守备力上升对象怪兽的守备力数值。\r\n②：对手怪兽的直接攻击宣言时，可将墓地的此卡除外，并以我方墓地的１只“超重武者”怪兽为对象发动。特殊召唤该怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44901281,'军刀空洞','①：自己场上存在“X－军刀”怪兽，且自己或对手召唤・反转召唤・特殊召唤怪兽之际可以发动。将其无效，将该怪兽破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44913552,'时间吞噬者','此卡战斗破坏对手怪兽时发动。跳过下次对手回合的主要阶段１。','跳过阶段','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44920699,'炎舞－天璇－',replace(replace('①：以自己场上的１只兽战士族怪兽为对象可以发动此卡。该怪兽的攻击力直至回合结束时为止上升７００。\r\n②：只要此卡存在于魔法与陷阱区域，自己场上的兽战士族怪兽的攻击力上升３００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44928016,'胡萝卜人',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：此卡存在于墓地的情况下，从自己手牌・场上（表侧表示）将“胡萝卜人”以外的1只植物族怪兽送至墓地可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44932065,'捕食植物 腺毛草胡蜂',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡被送至墓地的情况下可以发动。从牌组将“捕食植物 腺毛草胡蜂”以外的1只“捕食植物”怪兽加入手牌。\r\n②：此卡存在于墓地，且场上的怪兽上放有捕食计数物的情况下可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44935634,'左起子','此卡名的②效果1回合仅可使用1次。①：此卡特殊召唤成功的情况下可以发动。此卡的等级直至回合结束时为止变为3。②：将墓地的此卡除外可以发动。从牌组将1只“右起子”加入手牌。此效果在此卡被送至墓地的回合不可发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44944304,'娱乐伙伴搞笑人',replace(replace('←5 【灵摆】 5→\r\n①：１回合１次，对手场上存在有持有攻击力高于原本攻击力的怪兽的场合可发动。我方回复１０００LP。\r\n【怪兽效果】\r\n“娱乐伙伴搞笑人”①②怪兽效果１回合１次，只可使用其中任１个。\n①：此卡的攻击宣言时可发动。直至战斗阶段结束时，此卡的攻击力上升相当于此卡及对手场上怪兽内，持有攻击力高于原本攻击力的怪兽数量×１０００。\n②：持有攻击力高于原本攻击力的此卡因战斗、效果被破坏的场合，可以我方墓地的１只怪兽为对象发动。特殊召唤该怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44947065,'强者的苦痛','①：对手场上的怪兽的攻击力下降相当于该怪兽的等级×１００的数值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44954628,'巨大战舰 泰特朗',replace(replace('①：此卡召唤的情况下发动。在此卡上放3个计数物。\r\n②：此卡不会因战斗被破坏。\r\n③：1回合1次，去除此卡的1个计数物，以场上的1张魔法・陷阱卡为对象可以发动。将该卡破坏。\r\n④：此卡进行战斗的伤害步骤结束时发动。去除此卡的1个计数物。无法去除的情况下将此卡破坏。','\r',char(13)),'\n',char(10)),'放置计数物','移除计数物','破坏','魔陷破坏','','','','','','','','','','','','');
INSERT INTO texts VALUES(44956694,'ROM云雌羊',replace(replace('①：此卡召唤成功时，可以我方墓地１只除“ROM云雌羊”以外的电子界族怪兽为对象发动。将该怪兽加入手牌。\r\n②：此卡因战斗、效果被破坏的场合可发动。从牌组特殊召唤１只除“ROM云雌羊”以外等级４或以下的电子界族怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44968459,'沉默爆破',replace(replace('①：我方场上存在有“沉默魔术师”怪兽，并且我方手牌比对手多的场合，可在我方、对手的战斗阶段发动。双方从牌组抽取卡牌，直至各自手牌成为６张。此卡的发动以及效果不被无效化。\r\n②：可从墓地将此卡除外并发动。从牌组将１只“沉默魔术师”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'抽牌','牌组检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44968687,'传说的渔夫三世',replace(replace('此卡不可通常召唤。\r\n仅可在解放自己场上的1只“传说的渔夫”的情况下特殊召唤。\r\n①：此卡特殊召唤时可以发动。将对手场上的怪兽全部除外。此回合，此卡不可攻击。\r\n②：场上的此卡不会因战斗・效果被破坏，不受魔法・陷阱卡的效果影响。\r\n③：1回合1次，在自己的主要阶段可以发动。将对手除外状态的卡全部放回墓地，此回合，对手受到的战斗・效果伤害仅1次变为两倍。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(44994712,'捕食植物 长叶狸藻新妇蛛',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将“捕食植物 长叶狸藻新妇蛛”以外的1张“捕食”卡加入手牌。\r\n②：将墓地的此卡除外，可从以下效果中选择1个发动。\r\n●在场上的1只表侧表示怪兽上放1个捕食计数物。放有捕食计数物的等级2以上怪兽的等级变为1。\r\n●将自己墓地・除外状态的1张“融合”放置在自己场上。','\r',char(13)),'\n',char(10)),'检索效果','发动','放置计数物','放置「融合」','','','','','','','','','','','','');
INSERT INTO texts VALUES(45001322,'书灵师・烈火引燃者',replace(replace('以“书灵师”卡降临\r\n①：使用场上的怪兽来仪式召唤的此卡不会因效果被破坏，不可因效果除外。\r\n②：只要攻击力未满3000的此卡存在于怪兽区域，每当对手发动卡的效果，此卡的攻击力・守备力就上升200。','\r',char(13)),'\n',char(10)),'使用场上的怪兽作仪式召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45002991,'穹弧主宰・圣骑联盟',replace(replace('包括连接怪兽在内的效果怪兽2只以上\r\n①：此卡的攻击力上升相当于此卡连接端的怪兽原本攻击力的数值。②：此卡连接端的怪兽不可攻击。③：1回合1次，解放此卡连接端的自己的1只“圣骑联盟”怪兽或“星遗物”怪兽，以对手场上的1张表侧表示的卡为对象可以发动。将该卡的效果直至回合结束时为止无效。此效果在对手回合中也可以发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45005708,'深渊兽 阿卢绯尔',replace(replace('此卡名的②效果１回合仅可使用１次。①：此卡只要存在于场上・墓地，卡名视为“阿尔白斯之落胤”。②：此卡召唤・特殊召唤成功的情况下，舍弃１张手牌，以对手场上・墓地的１只龙族怪兽为对象，可从以下效果中选择１个发动。\r\n●将此卡送至墓地，直至结束阶段为止获得场上的对象怪兽的控制权。\r\n●将此卡送至墓地，将墓地的对象怪兽特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'得到对手场上的怪兽的控制权','特殊召唤对手墓地的怪兽','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45010690,'鲜花机器人','①：此卡被送入墓地的场合发动。我方从牌组抽取１张卡牌。之后，将１张手牌返回至持有者牌组的最上方。','把自己1张手牌放在牌组最上面','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45014450,'霸王紫龙 异色眼猛毒龙',replace(replace('←1 【灵摆】 1→\r\n①：1回合1次，以自己场上的1只融合怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止，上升对手场上的怪兽数量×1000的数值。\r\n【怪兽效果】\r\n“凶饿猛毒”怪兽＋“异色眼”怪兽\n此卡仅可以融合召唤（及灵摆召唤）方式特殊召唤。\n①：1回合1次，以对手场上的1只表侧表示怪兽为对象可以发动。此卡直至结束阶段为止，攻击力上升相当于该怪兽攻击力的数值，获得与该怪兽原本卡名・效果相同的卡名・效果。\n②：怪兽区域的此卡被破坏的情况下可以发动。将自己灵摆区域的1张卡特殊召唤，将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'融合怪兽攻击力上升','复制效果','结束复制效果','灵摆区域卡特殊召唤','','','','','','','','','','','','');
INSERT INTO texts VALUES(45016904,'阴阳师 道道',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：此卡与怪兽进行战斗的情况下，该2只不会因该战斗被破坏。\r\n②：自己因战斗・效果受到伤害的情况下可以发动。从自己手牌・墓地将1只等级3以上的幻想魔族怪兽特殊召唤。受到的伤害为2000以上的情况下，也可从牌组・额外牌组挑选要特殊召唤的怪兽。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45023678,'闪电处刑人','累积了３个或以上连锁的场合发动。选择对手场上的１张卡牌破坏。同一连锁上复数次同名卡效果发动的场合，此效果不可发动。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45025640,'拒绝绵羊',replace(replace('①：因此卡的战斗所产生的对对手的战斗伤害由我方代替承受。\r\n②：此卡不会因此卡的战斗而被破坏，我方受到战斗伤害的场合发动。将此卡返回至持有者手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45033006,'正义盟军 擒敌者','此卡召唤成功时可发动。选择对手场上的１只里侧守备表示怪兽，直至结束阶段，取得其控制权。','获得控制权','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45037489,'鲜花之骑士',replace(replace('“花之同步士”＋1只以上协调以外的怪兽\r\n①：1回合1次，对手在自己的回合发动魔法・陷阱卡时可以发动。将该发动无效并破坏。','\r',char(13)),'\n',char(10)),'魔法·陷阱卡的发动无效并破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45041488,'核成・守护者',replace(replace('此卡的控制者每当到自己的结束阶段，从手牌将1张“核成之钢核”送至墓地，或向对手出示手牌的1只岩石族怪兽，或将此卡破坏。\r\n①：怪兽的效果发动时，解放此卡可以发动。将该发动无效并破坏。','\r',char(13)),'\n',char(10)),'选择一张「核成之钢核」送至墓地','选择一只岩石族怪物给对手观看','破坏「核成・守护者」','效果怪物发动无效并破坏','','','','','','','','','','','','');
INSERT INTO texts VALUES(45042329,'地雷兽','向周围放出强大的电磁波进行攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45045866,'海洋看守者','此卡攻击守备表示怪兽时，如果攻击力超出守备力，则给对方生命相当于该差值的战斗伤害。此卡因战斗被破坏时发动。从牌组将１只“千眼水母”或“母脑鱼”加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45064756,'轮回独断','①：１回合１次，宣言１个种族可以发动。此回合，双方墓地的怪兽变为所宣言的种族。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45065541,'玛那桃圆乡・摘心','此卡名的①②效果１回合仅可各使用１次。①：以自己场上的１只怪兽为对象可以发动。将该怪兽破坏，从牌组将１张“伍世坏・佳乐里姆”加入手牌。自己场上存在“伍世坏・佳乐里姆”的情况下，作为代替可将“玛那桃圆乡・摘心”以外的１张“玛那桃圆乡”魔法・陷阱卡加入手牌。②：将墓地的此卡除外可以发动。从手牌将１只“维萨思・史塔弗罗斯特”或攻击力１５００／守备力２１００的怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45072394,'铁之牢笼',replace(replace('此卡牌名的卡牌１回合只可发动１张。\r\n①：作为此卡发动的效果处理，将我方场上的１只怪兽送入墓地。场地区存在有“急流山的金宫”的场合，也可将对手场上的怪兽送入墓地作为代替。\r\n②：在我方准备阶段，可以１只因此卡的①效果而被送入我方或对手墓地的怪兽为对象发动。破坏此卡，并将该怪兽特殊召唤至我方场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45078193,'电子暗黑炮',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从手牌将此卡舍弃可以发动。从牌组将1只机械族的“电子暗黑”怪兽加入手牌。\r\n②：装备此卡的怪兽进行战斗的伤害计算时可以发动。从牌组将1只怪兽送至墓地。\r\n③：装备于怪兽的此卡被送至墓地的情况下可以发动。自己抽1张。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45082499,'ZEXAL兵器－雷神猛虎剑','①：“ZEXAL兵器－雷神猛虎剑”在自己场上仅可有１张以表侧表示形式存在。②：以自己场上的１只“希望皇霍普”怪兽为对象可以发动。从自己的手牌・场上，将此卡视为攻击力上升１２００的装备卡，装备于该自己的“希望皇霍普”怪兽。③：此卡被装备中的情况下，自己场上的“ZEXAL兵器”卡不会因对手的效果被破坏。④：装备怪兽将被效果破坏的情况下，破坏此卡作为代替。','装备','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45103815,'召唤师 莱斯贝尔特',replace(replace('←2 【灵摆】 2→\r\n①：1回合1次，以场上1只表侧表示怪兽为对象可以发动。该怪兽的等级上升1。\r\n【怪兽效果】\r\n作为哥哥的莱斯贝尔特心地善良，非常爱自己的妹妹塞姆贝尔。每天他都会在正午后和妹妹一同看魔术书，两人看上去关系亲密和睦，会让周围人自然而然地感觉心灵受到慰藉。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45112597,'世海龙 西兰提斯',replace(replace('效果怪兽1只以上\r\n此卡名的②③效果1回合仅可各使用1次。\r\n①：“世海龙 西兰提斯”在自己场上仅可有1张以表侧表示存在。\r\n②：在自己的主要阶段可以发动。将场上的怪兽全部除外。然后，将以此效果除外的怪兽尽可能地以表侧表示或里侧守备表示特殊召唤至其原本持有者的场上。\r\n③：在自己・对手的战斗阶段可以发动。将场上的卡破坏，数量最多为场上的相互连接状态的怪兽数量。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45115956,'战华史略－矫诏之叛',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己的主要阶段可以发动。从手牌将1只“战华”怪兽特殊召唤，自己受到该怪兽的等级×100的伤害。\r\n②：将魔法与陷阱区域的表侧表示的此卡送至墓地，以场上的1只“战华”怪兽为对象可以发动。将该怪兽的属性变更为任意属性。以对手场上的怪兽为对象来发动的情况下，进而可获得该怪兽的控制权。','\r',char(13)),'\n',char(10)),'特殊召唤','改变属性','是否获得控制权？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45116390,'重装骑士 巴别双层列车',replace(replace('此卡名的②③效果1回合仅可各使用1次。\r\n①：此卡无需解放即可召唤。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从手牌将1只机械族・地属性怪兽特殊召唤。\r\n③：在对手发动过卡的效果的回合的、自己的主要阶段可以发动。从额外牌组将1只机械族・地属性・阶级10的超量怪兽重叠在自己场上的此卡上面，视为超量召唤特殊召唤。','\r',char(13)),'\n',char(10)),'不用解放作召唤','特殊召唤','超量召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45118716,'魔法回收员','可在对手怪兽的攻击宣言时将墓地的此卡从游戏中除外，并选择我方墓地的１张魔法卡发动。将我方牌组最上方的卡牌送入墓地，并将被选择卡牌返回至牌组最下方。','魔法回收','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45121025,'黑影鬼王','被黑影附体的恶鬼，能以惊人的速度进行突击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45133463,'死神的呼声','怪兽从我方墓地被特殊召唤时可发动。从我方墓地选择１只“苏帕伊”或“赤蚁 阿斯卡托尔”并特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45141013,'大热波','①：在自己的主要阶段１开始时可以发动。直至下个自己的抽牌阶段为止，双方不可召唤・特殊召唤效果怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45141844,'执着的老魔术师','①：此卡反转的情况下，以对手场上的1只怪兽为对象发动。将该对手的怪兽破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45148985,'玄化执行者',replace(replace('此卡不可通常召唤。\r\n仅限从我方墓地及我方场上的表侧表示卡牌中，将５种“玄化”卡牌各除外１张的场合可特殊召唤。\r\n①：场上的此卡不会因效果被破坏，也不会因效果被除外。\r\n②：对手场上的卡牌数量多于我方场上卡牌的场合，１回合１次，可以１只被除外的我方“玄化”怪兽为对象发动。特殊召唤该怪兽。以此效果特殊召唤的怪兽在下一个回合的结束阶段被除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45154513,'巨食尸鬼 魔杰拉','此卡名的①②效果１回合仅可各使用１次。①：自己场上的不死族怪兽将被战斗・效果破坏的情况下，作为代替可以将手牌・墓地的此卡除外。②：此卡被从手牌・墓地除外的情况下可以发动。将此卡以守备表示特殊召唤。然后，可将此卡的等级下降１。','是否下降等级？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45159319,'摩艾迎击炮','此卡１回合１次可变成里侧守备表示。','变成里侧守备表示','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45170821,'幻影－英雄 崇高',replace(replace('“－英雄”怪兽×２\r\n①：１回合１次，以对手场上的１只表侧表示怪兽和自己场上此卡以外的１只“－英雄”怪兽为对象可以发动。该对手怪兽的攻击力・守备力直至回合结束时为止，下降相当于该自己的怪兽的攻击力的数值。','\r',char(13)),'\n',char(10)),'攻守下降','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45171524,'巳剑劝请',replace(replace('此卡名的卡1回合仅可发动1张。\r\n此卡也可以通过解放自己手牌・场上的1只爬虫类族怪兽来发动。\r\n①：从以下效果中挑选1个适用。解放了怪兽来发动此卡的情况下，两者都可适用。\r\n●从牌组将1只“巳剑”怪兽加入手牌。\r\n●自己受到800伤害。然后，可从自己手牌・墓地将1只“巳剑”怪兽特殊召唤。以此效果特殊召唤的怪兽不可直接攻击。','\r',char(13)),'\n',char(10)),'发动','是否解放怪兽来发动？','是否从牌组加入手牌？','是否受到伤害？','是否特殊召唤？','','','','','','','','','','','');
INSERT INTO texts VALUES(45178472,'满堂红','可选择场上除此卡以外的２张表侧表示魔法、陷阱卡，以及被盖牌的３张魔法、陷阱卡发动。破坏被选择的卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45184165,'急袭猛禽－骷髅鹰',replace(replace('“急袭猛禽－骷髅鹰”的①效果１回合仅可使用１次。\r\n①：超量素材的此卡为发动超量怪兽的效果被去除并被送至墓地的情况下，将墓地的此卡除外，以自己墓地的１张“急袭猛禽”卡为对象可以发动。将该卡加入手牌。\r\n②：以场上的此卡作为素材超量召唤的怪兽获得以下效果。\r\n●此超量召唤成功的情况下发动。此卡的攻击力上升３００。','\r',char(13)),'\n',char(10)),'此卡的攻击力上升300（急袭猛禽－骷髅鹰）','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45195443,'元素－英雄 固态人',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：此卡召唤时可以发动。从手牌将1只等级4以下的“－英雄”怪兽特殊召唤。\r\n②：此卡因魔法卡的效果从怪兽区域被送至墓地的情况下，以“元素－英雄 固态人”以外的、自己墓地的1只“－英雄”怪兽为对象可以发动。将该怪兽以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45206713,'DD 漩涡史莱姆',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡存在于手牌的情况下可以发动。将包含此卡在内的手牌的怪兽作为融合素材，将1只“DDD”融合怪兽融合召唤。\r\n②：将墓地的此卡除外可以发动。从手牌将1只“DD”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45215225,'绒毛动物・天使',replace(replace('←8 【灵摆】 8→\r\n此卡名的灵摆效果１回合仅可使用１次。\n①：以自己墓地１只“绒毛动物”怪兽或“锋利小鬼”怪兽为对象可以发动。将该怪兽特殊召唤。此效果发动后，直至回合结束时为止，自己从额外牌组仅可特殊召唤融合怪兽。\r\n【怪兽效果】\r\n此卡名的怪兽效果１回合仅可使用１次。\n①：解放此卡，以自己墓地的１只“魔玩具”融合怪兽为对象可以发动。挑选１张手牌舍弃，将对象怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45215453,'大日神械三角',replace(replace('协调＋协调以外的光属性怪兽１只或以上\r\n我方结束阶段时此卡以表侧守备表示存在的场合，可从牌组将１张装备魔法卡加入手牌。','\r',char(13)),'\n',char(10)),'检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45221020,'寻宝熊猫','①：从自己墓地将最多３张魔法・陷阱卡以里侧除外可以发动。从牌组将１只等级与除外的卡的数量相同的通常怪兽特殊召唤。','特殊召唤','请选择要特殊召唤的怪兽的等级','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45222299,'禁咒仪・幽灵克拉肯','以“咒仪”仪式魔法卡降临。①：此卡仪式召唤成功的情况下发动。随机挑选最多２张对手手牌确认，挑选其中１张放回牌组。','确认手牌','请选择要确认的手牌的数量','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45223540,'沼地魔道王',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：此卡存在于手牌的情况下可以发动。向对手出示额外牌组的1只融合怪兽，从牌组将1只卡名记载于该怪兽的融合素材怪兽除外。然后，将此卡特殊召唤。此回合，要将以此效果特殊召唤的此卡作为融合素材的情况下，可视为以此效果所除外的怪兽的同名卡。','\r',char(13)),'\n',char(10)),'特殊召唤','「沼地魔道王」效果适用中','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45231177,'炎之剑士','“炎之操纵者”＋“传说之剑豪 MASAKI”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45231178,'炎之剑士','“炎之操纵者”＋“传说之剑豪 MASAKI”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45236142,'高等宝玉兽 蓝钴鹰',replace(replace('①：场地区域不存在“高等暗黑”的情况下，此怪兽将被送至墓地。\r\n②：将手牌・场上的此卡送至墓地可以发动。从牌组将１张“高等暗黑”加入手牌。\r\n③：１回合１次，以自己场上的１张“高等宝玉兽”卡为对象可以发动。将该卡放回持有者的手牌，或放回牌组最上面。\r\n④：表侧表示的此卡在怪兽区域被破坏的情况下，可不送至墓地，而是视为永续魔法卡以表侧表示放在自己的魔法与陷阱区域。','\r',char(13)),'\n',char(10)),'牌组检索','回到手牌或牌组','回到手牌','回到牌组','','','','','','','','','','','','');
INSERT INTO texts VALUES(45247637,'蔷薇之刻印',replace(replace('从自己墓地将1只植物族怪兽除外，以对手场上的1只表侧表示怪兽为对象可以发动此卡。\r\n①：获得装备怪兽的控制权。\r\n②：在自己的结束阶段发动。此卡的①效果直至下一个自己准备阶段为止无效。','\r',char(13)),'\n',char(10)),'控制权转移','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45282603,'召唤师－赛姆贝尔','我方主要阶段时，可从手牌特殊召唤与此卡相同等级的１只怪兽。此效果只要此卡以表侧表示存在于场上只可使用１次。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45283341,'永恒之绊','此卡名的①②效果１回合仅可各使用１次。①：以自己墓地任意数量的“光子”怪兽为对象可以发动。将该怪兽的效果无效并特殊召唤。②：在自己的主要阶段将墓地的此卡除外，以对手场上的１只“光子”怪兽为对象可以发动。获得该怪兽的控制权。此回合，自己仅可用该怪兽攻击宣言，该怪兽的攻击力变为相当于自己场上“光子”怪兽原本攻击力合计的数值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45286019,'齿轮齿轮人 Mk－Ⅲ','此卡名的效果１回合仅可使用１次，发动此效果的回合中，自己仅可特殊召唤“齿轮齿轮”怪兽。①：此卡以“齿轮齿轮”卡的效果特殊召唤成功时可以发动。从自己的手牌・墓地挑选“齿轮齿轮人 Mk－Ⅲ”以外的１只“齿轮齿轮”怪兽，以守备表示特殊召唤。以此效果特殊召唤的怪兽的效果无效化。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45298492,'伤疤战士',replace(replace('协调＋协调以外的怪兽１只或以上\r\n只要此卡以表侧表示存在于场上，对手不可选择其他的战士族怪兽作为攻击对象。此外，此卡１回合仅１次，不会因战斗被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45305419,'继承之印','①：自己墓地存在3只以上同名怪兽的情况下，以其中1只为对象可以发动此卡。将该怪兽特殊召唤，装备此卡。此卡被破坏时装备怪兽将被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45311864,'盗贼格布林','给予对手生命５００点伤害，回复我方５００LP。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45313724,'炼狱之釜',replace(replace('①：我方场上的“无限狱”怪兽或龙族、暗属性、等级８的同步怪兽因对手效果被破坏的场合，可将我方墓地的１张“无限狱”卡牌除外作为代替。\r\n②：我方手牌并非０张的场合，此卡被送入墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45313993,'红莲狼','①：自己召唤“共鸣者”怪兽时可以发动。从手牌将此卡特殊召唤。以此效果特殊召唤的此卡的攻击力变为一半。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45337544,'英豪使者',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：从牌组将１只“英豪”怪兽加入手牌。\r\n②：自己的LP为５００以下的情况下，将墓地的此卡除外，以自己墓地的１张“英豪”卡为对象可以发动。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45349196,'凶魔龙 黑恶魔龙',replace(replace('等级６“恶魔”通常怪兽＋“真红眼”通常怪兽\r\n自己１回合仅可特殊召唤１次“凶魔龙 黑恶魔龙”。①：此卡进行战斗的情况下，对手直至伤害步骤结束时为止，不可发动魔法・陷阱・怪兽的效果。②：融合召唤的此卡进行战斗的战斗阶段结束时，以自己墓地的１只“真红眼”通常怪兽为对象可以发动。给予对手相当于墓地的该怪兽原本攻击力数值的伤害。然后将该怪兽放回牌组。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45354718,'抒情歌鸲－鸟哨','此卡名的卡1回合仅可发动1张。①：从牌组挑选1只“抒情歌鸲”怪兽加入手牌或送至墓地。然后，可从手牌将1只卡名与该怪兽不同的“抒情歌鸲”怪兽特殊召唤。','牌组检索','是否从手牌特殊召唤卡名不同的怪兽？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45358284,'镜瓢虫','只要我方场上存在有表侧表示怪兽，且我方墓地不存在怪兽的场合，此卡可从手牌特殊召唤。以此效果特殊召唤成功时，此卡的等级变成我方场上除此卡以外的怪兽等级的合计数值。此外，场上的此卡的等级超过１２的场合，此卡被破坏。','等级变换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45379225,'念力健能转换者',replace(replace('协调＋协调以外的怪兽1只以上\r\n①：1回合1次，从自己墓地将1只念动力族怪兽除外可以发动。自己恢复1200LP。','\r',char(13)),'\n',char(10)),'回复1200基本分','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45383307,'三形金字塔巡航机',replace(replace('“三形金字塔巡航机”的③效果１回合只可使用１次。\r\n①：只要此卡存在于场地区，每次岩石族怪兽被召唤，我方恢复５００LP。\r\n②：“三形金字塔”怪兽被召唤至场上的场合可发动。我方从牌组抽取１张卡牌，之后挑选１张手牌舍弃。\r\n③：场地区表侧表示的此卡被送入墓地的场合可发动。从牌组将１只“三形金字塔”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'回复基本分','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45409943,'宵暗之路彻',replace(replace('自己墓地的恶魔族・天使族怪兽×3\r\n此卡名的②③效果1回合仅可各使用1次。\r\n①：只要此卡存在于怪兽区域，自己左端・右端的主要怪兽区域的怪兽就不会因效果被破坏。\r\n②：以对手场上的1张卡为对象可以发动。从牌组将1只恶魔族・天使族怪兽送至墓地，将对象卡破坏。\r\n③：自己场上的其他卡因效果被破坏的情况下，以场上的1张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','从牌组送至墓地','场上的卡破坏','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45410988,'真红眼转生',replace(replace('“真红领主”降临所必需。\r\n①：为使等级合计为８以上，从自己的手牌・场上解放怪兽，或将自己墓地的“真红眼”怪兽除外作为解放的代替，从手牌将“真红领主”仪式召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45420955,'迅雷之暴君 格罗扎',replace(replace('协调＋协调以外的恶魔族怪兽1只以上\r\n此卡名的①效果1回合仅可使用1次。\r\n①：在对手的主要阶段，以场上的1只效果怪兽为对象可以发动。从手牌挑选1只怪兽舍弃，将对象怪兽的效果直至回合结束时为止无效。\r\n②：有恶魔族怪兽从手牌被送至自己墓地的情况下可以发动。从以下效果中挑选1个，直至回合结束时为止适用于此卡。\r\n●不会因战斗被破坏。\r\n●不会因对手的效果被破坏。\r\n●对手不可将此卡作为效果的对象。','\r',char(13)),'\n',char(10)),'效果无效','获得抗性','不会被战斗破坏','不会被对手的效果破坏','不会成为对手的效果的对象','','','','','','','','','','','');
INSERT INTO texts VALUES(45425051,'妖精王 奥伯龙','①：只要此卡以守备表示存在于怪兽区，我方场上的植物族怪兽的攻击力、守备力上升５００。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45439263,'岩浆炎・翼龙','我方墓地冠有“岩浆炎”之名的怪兽为３种或以上的场合，此卡可从手牌特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45445571,'死灵公爵',replace(replace('恶魔族・不死族怪兽×2\r\n此卡的控制者在每个自己的准备阶段，支付500LP或将此卡破坏。\r\n此卡名的②③效果1回合仅可各使用1次。\r\n①：此卡不会因战斗被破坏。\r\n②：在自己的主要阶段可以发动。进行1只怪兽的召唤。\r\n③：将墓地的此卡除外，以自己墓地的1只等级4以上的恶魔族・不死族怪兽为对象可以发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'是否支付基本分？','进行召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45450218,'正义盟军 致命武器','此卡因战斗破坏光属性怪兽并送入墓地时，从牌组抽取１张卡牌。并且，以此效果抽取的卡牌是等级４或以下的暗属性怪兽的场合，可向对手展示该卡并特殊召唤。','抽牌','是否要特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45452224,'金华猫',replace(replace('此卡不可特殊召唤。\r\n①：此卡召唤・反转时，以自己墓地的1只等级1怪兽为对象可以发动。将该怪兽特殊召唤。此卡从场上离开时，该怪兽将被除外。\r\n②：此卡召唤・反转的回合的结束阶段发动。将此卡放回手牌。','\r',char(13)),'\n',char(10)),'返回手牌','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45458027,'上弦式神',replace(replace('此卡不可通常召唤。\r\n自己墓地的怪兽仅有机械族怪兽的情况下可以特殊召唤。\r\n①：１回合１次，以对手场上的１只表侧表示怪兽为对象可以发动。将该怪兽的攻击力直至回合结束时为止改成０。','\r',char(13)),'\n',char(10)),'攻击力变成0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45462149,'码语者・倒置',replace(replace('电子界族怪兽2只\r\n此卡名的效果1回合仅可使用1次。①：此卡连接召唤成功的情况下可以发动。从手牌将1只电子界族怪兽特殊召唤至此卡连接端的自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45462306,'X－军刀 布鲁诺',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡存在于手牌的情况下，从自己手牌・场上（表侧表示）・墓地将此卡以外的1只地属性怪兽除外可以发动。将此卡特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从自己牌组・墓地将1张“军刀”魔法・陷阱卡加入手牌。\r\n③：1回合1次，在对手的主要阶段及战斗阶段可以发动。将包含此卡在内的、仅以自己场上的地属性怪兽作为素材进行同步召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','检索','同步召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45462639,'暗红之魔导师','成功召唤此卡时，在此卡上放置２个魔力计数物。只要此卡以表侧表示存在于场上，每当我方或对手发动魔法卡时，在此卡上放置１个魔力计数物。此卡上每有１个魔力计数物，此卡的攻击力便上升３００点。１回合１次，取除此卡上放置的２个魔力计数物，随机弃置对手１张手牌。','放置计数物','丢弃手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45464587,'黄金荣耀－灭击手',replace(replace('协调＋协调以外的怪兽１只以上\r\n此卡名的①效果１回合仅可使用１次。\r\n①：在对手回合中，以场上的１只融合・同步・超量・连接怪兽为对象可以发动（自己的LP少于对手的情况下，可将此效果的对象改成２只）。将该怪兽破坏。\r\n②：在发动了此卡的①效果的回合的结束阶段发动。将此卡放回额外牌组，从自己的牌组・墓地将１只“黄金荣耀－暗袭手”特殊召唤。','\r',char(13)),'\n',char(10)),'破坏怪兽','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45467446,'白之灵龙',replace(replace('此卡名在规则上也视为“青眼”卡。\r\n①：此卡只要存在于手牌・墓地，则视为通常怪兽。\r\n②：此卡召唤・特殊召唤时，以对手场上的１张魔法・陷阱卡为对象可以发动。将该卡除外。\r\n③：在自己・对手回合中，对手场上存在怪兽的情况下，解放此卡可以发动。从手牌将１只“青眼白龙”特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45483489,'深海的哨兵',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡为发动水属性怪兽的效果被送至墓地的情况下可以发动。对手挑选自身的1张手牌直至结束阶段为止以表侧除外。\r\n②：此卡特殊召唤的情况下，从自己牌组上面将2张卡送至墓地，以“深海的哨兵”以外的、自己墓地的1只等级4以下的水属性怪兽为对象可以发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45484331,'守宝团・姬特',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：自己场上或墓地存在需以“阿尔白斯之落胤”作为融合素材的融合怪兽的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下可以发动。将自己牌组・墓地・除外状态的1张“烙印”魔法・陷阱卡加入手牌。然后，挑选自己的1张手牌放回牌组最下面。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45488703,'NT8000－天狼星',replace(replace('此卡名的②③效果1回合仅可各使用1次。\r\n①：连接状态的此卡不会因战斗被破坏。\r\n②：在有连接怪兽的效果发动过的自己・对手回合中，以自己及对手场上的各1张表侧表示卡为对象可以发动。将该2张卡破坏。\r\n③：此卡从场上以外的地方被送至墓地的情况下，如果自己场上存在暗属性连接怪兽则可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'','破坏','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45496268,'超防卫机器人・大象','此卡召唤成功时，可从手牌特殊召唤１只冠有“超防卫机器人”之名的怪兽或“奥比塔尔７”。１回合１次，可选择我方场上１只冠有“超防卫机器人”之名的怪兽或“奥比塔尔７”并发动。直至回合结束时，被选择怪兽的等级变成８。此外，以此卡为超量召唤素材的场合，只可用于机械族怪兽的超量召唤。','特殊召唤','等级变换','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45500495,'地狱刺藤',replace(replace('协调＋协调以外的植物族怪兽1只以上\r\n①：只要此卡存在于怪兽区域，双方为从自身手牌召唤・特殊召唤植物族以外的怪兽，每有1只就必须支付1000LP。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45508030,'凭依共鸣',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：以场上的1只表侧表示怪兽为对象可以发动。从自己手牌・牌组・墓地将属性与该怪兽相同的、1只“灵使”怪兽或“凭依装着”怪兽以表侧攻击表示或里侧守备表示特殊召唤。然后，可将对象怪兽改成里侧守备表示。\r\n②：将墓地的此卡除外，以自己场上的1只怪兽为对象可以发动。变更该怪兽的表示形式。','\r',char(13)),'\n',char(10)),'发动','改变表示形式','是否让对象怪兽变成里侧守备表示？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45531624,'精灵的圣剑士',replace(replace('此卡在游戏规则上也被视为“精灵剑士”卡牌。\r\n①：我方有手牌的场合，此卡不可攻击。\r\n②：１回合１次，在我方主要阶段可发动。从手牌特殊召唤１只“精灵剑士”怪兽。\r\n③：因此卡的攻击给予对手战斗伤害时可发动。我方从牌组抽取卡牌，其数量相当于我方场上的“精灵剑士”怪兽数量。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45533023,'急袭猛禽－烈焰猎鹰',replace(replace('鸟兽族等级5怪兽×3\r\n①：拥有超量素材的此卡可以直接攻击。②：此卡给予对手战斗伤害时，以对手场上的1只怪兽为对象可以发动。将该怪兽破坏。③：1回合1次，去除此卡的1个超量素材可以发动。对手场上的被特殊召唤的怪兽全部破坏，给予对手破坏的怪兽数量×500伤害。','\r',char(13)),'\n',char(10)),'1只怪兽破坏','特殊召唤的怪兽全部破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45536531,'滑稽暗黑兔',replace(replace('①：此卡召唤・特殊召唤时适用。此回合，自己在通常召唤之外，可在自己的主要阶段追加1次召唤1只记载有“卡通世界”卡名的怪兽。\r\n②：只要场上存在“卡通世界”，此卡就视为卡通怪兽。\r\n③：1回合1次，在自己的主要阶段可以发动。从牌组挑选1张“卡通”场地・永续魔法卡，加入手牌或以表侧表示放在自己场上。','\r',char(13)),'\n',char(10)),'','使用「滑稽暗黑兔」的效果召唤','检索效果','放置','','','','','','','','','','','','');
INSERT INTO texts VALUES(45538320,'精灵术的使役魔',replace(replace('此卡名在规则上也视为“凭依装着”卡。\r\n此卡名的①②③效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将1张“凭依”魔法・陷阱卡或“大灵术－「一轮」”加入手牌。\r\n②：宣言种族与属性各1个可以发动。此卡直至回合结束时为止，变为所宣言的种族・属性。\r\n③：此卡因战斗・效果被破坏的情况下可以发动。从自己牌组・墓地将1只守备力1500魔法师族怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'检索效果','改变种族属性','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45547649,'鸟面人','当此卡因战斗而被破坏送入墓地时，可将我方牌组中的１张“神鹰女郎”加入到手牌中。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45584727,'女战神的拥抱',replace(replace('此卡牌名的卡牌１回合只可发动１张，此卡发动的回合，我方只可特殊召唤“女战神”怪兽。\r\n①：我方场上的怪兽仅是“女战神”怪兽的场合，可以我方场上的１只攻击表示“女战神”怪兽与对手场上的１只表侧表示怪兽为对象发动。将该我方怪兽变成守备表示，并将该对手怪兽除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45586855,'正义盟军 旋风制造者','１回合１次，可舍弃１张手牌并发动。挑选场上的魔法、陷阱卡并返回至持有者手牌，其数量相当于场上的协调数量。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45591967,'娱乐伙伴・额外射手',replace(replace('←6 【灵摆】 6→\r\n“娱乐伙伴・额外射手”的灵摆效果１回合只可使用１次，发动此效果的回合，我方不可进行灵摆召唤。\n①：在我方主要阶段可发动。给予对手相当于我方额外牌组的表侧表示灵摆怪兽数量×３００的伤害。\r\n【怪兽效果】\r\n①：１回合１次，可从我方额外牌组将１只怪兽除外，并以我方或对手灵摆区的１张卡牌为对象发动。破坏该卡，并给予对手３００的伤害。','\r',char(13)),'\n',char(10)),'效果伤害','卡片破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45593005,'变形斗士・I型磁铁',replace(replace('此卡依据此卡的表示形式获得以下效果。\r\n●攻击表示：我方场上除此卡以外的表侧攻击表示怪兽为２只的场合，１回合１次，直至回合结束时，此卡的攻击力可上升该怪兽的攻击力合计数值。发动此效果的回合，其他的怪兽不可攻击。\r\n●守备表示：我方场上的怪兽不可攻击。','\r',char(13)),'\n',char(10)),'攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45593826,'彼岸恶鬼 德拉格涅','此卡名的①③效果1回合1次，仅可使用其中1个。①：自己场上没有魔法・陷阱卡存在的情况下可以发动。从手牌将此卡特殊召唤。②：自己场上有“彼岸”怪兽以外的怪兽存在的情况下此卡将被破坏。③：此卡被送至墓地的情况下可以发动。从牌组挑选1张“彼岸”卡放在牌组最上面。','特殊召唤','选1张「彼岸」卡在牌组最上面放置','请选择要在牌组最上面放置的卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45620686,'骚骚虫','可将此卡从手牌送入墓地，并选择１只场上的怪兽发动。直至回合结束时，被选择怪兽的等级上升１级。','等级上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45627618,'霸王黑龙 异色眼反叛龙',replace(replace('←4 【灵摆】 4→\r\n①：１回合１次，另一方自己的灵摆区域没有卡存在的情况下可以发动。从牌组挑选１只灵摆怪兽，放在自己的灵摆区域。\r\n【怪兽效果】\r\n龙族等级７怪兽×２\n在可灵摆召唤等级７的情况下，额外牌组表侧表示的此卡可以灵摆召唤。①：此卡以超量怪兽为素材超量召唤成功的情况下发动。将对手场上等级７以下的怪兽全部破坏，给予对手相当于所破坏数量×１０００的数值的伤害。此回合，此卡在１次战斗阶段中可攻击３次。②：怪兽区域的此卡因战斗・效果被破坏的情况下可以发动。将自己灵摆区域的卡全部破坏，将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'放置灵摆怪兽','７星以下的怪兽全部破坏','此卡在自己的灵摆区域放置','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45627619,'霸王黑龙 异色眼反叛龙',replace(replace('←4 【灵摆】 4→\r\n①：１回合１次，另一方自己的灵摆区域没有卡存在的情况下可以发动。从牌组挑选１只灵摆怪兽，放在自己的灵摆区域。\r\n【怪兽效果】\r\n龙族等级７怪兽×２\n在可灵摆召唤等级７的情况下，额外牌组表侧表示的此卡可以灵摆召唤。①：此卡以超量怪兽为素材超量召唤成功的情况下发动。将对手场上等级７以下的怪兽全部破坏，给予对手相当于所破坏数量×１０００的数值的伤害。此回合，此卡在１次战斗阶段中可攻击３次。②：怪兽区域的此卡因战斗・效果被破坏的情况下可以发动。将自己灵摆区域的卡全部破坏，将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'放置灵摆怪兽','７星以下的怪兽全部破坏','此卡在自己的灵摆区域放置','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45644898,'青之眼祭司','此卡名的②效果１回合仅可使用１次。①：此卡召唤成功时，以自己墓地的１只光属性・等级１协调为对象可以发动。将该怪兽加入手牌。②：将墓地的此卡放回牌组，以自己场上的１只效果怪兽为对象可以发动。将该怪兽送至墓地，从自己的墓地挑选该怪兽以外的１只“青眼”怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45651298,'仿耳怪','对手场上存在有怪兽，且我方场上存在有等级３怪兽的场合，此卡可从手牌特殊召唤。１回合只可１次以此方法特殊召唤“仿耳怪”。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45653036,'暴风雨',replace(replace('可选择我方场上的１只冠有“云魔物”之名的怪兽并发动。从以下效果挑选１个并适用。\r\n●被选择怪兽的攻击力下降１０００点，挑选对手场上的１张魔法、陷阱卡破坏。\r\n●被选择怪兽的攻击力下降２０００点，挑选２张对手场上的卡牌并破坏。','\r',char(13)),'\n',char(10)),'攻击力下降1000','攻击力下降2000','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45655875,'魔键召兽－安希亚拉波斯',replace(replace('“魔键”怪兽＋衍生物以外的通常怪兽\r\n此卡名的①效果１回合仅可使用１次。\r\n①：此卡融合召唤成功的情况下可以发动。从自己的墓地挑选１张“魔键－马夫提亚”加入手牌。\r\n②：１回合１次，以拥有与自己墓地任一通常怪兽或“魔键”怪兽相同的属性的、对手的１只攻击表示怪兽为对象可以发动。将该怪兽改成守备表示，其守备力下降１０００。\r\n③：此卡战斗破坏的怪兽不去墓地而是被除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45659520,'邪恶－英雄 恶兆死灵',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：将墓地的此卡除外可以发动。从手牌・牌组将“邪恶－英雄 恶兆死灵”以外的1只“邪恶－英雄”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45662855,'宝石骑士・堇青石',replace(replace('只要此卡以表侧表示存在于墓地或场上的场合，被视为通常怪兽。通过将场上以表侧表示存在的此卡视为通常召唤再次召唤，使此卡被视作效果怪兽获得以下效果。\r\n●１回合１次，可将我方墓地１只冠有“宝石”之名的怪兽从游戏中除外并发动。选择我方墓地的１张冠有“宝石骑士”之名的卡牌并加入手牌。','\r',char(13)),'\n',char(10)),'加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45663742,'蛇眼・奥柯',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡召唤・特殊召唤的情况下，以自己墓地・除外状态的１只炎属性・等级１怪兽为对象可以发动。将该怪兽加入手牌或特殊召唤。\r\n②：将自己场上包含此卡在内的２张表侧表示卡送至墓地可以发动。从手牌・牌组将“蛇眼・奥柯”以外的１只“蛇眼”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45666710,'星义之执行者','此卡名的卡1回合仅可发动1张。①：从自己墓地的怪兽及被除外的自己的怪兽中，以1只“星义”怪兽为对象可以发动。将该怪兽特殊召唤。以此效果特殊召唤的原本等级为11以上的怪兽此回合不可发动效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45667991,'降龙之魔术师',replace(replace('←2 【灵摆】 2→\r\n①：１回合１次，以场上的１只表侧表示怪兽为对象可以发动。该怪兽种族直至对手回合结束时为止变为龙族。\r\n【怪兽效果】\r\n①：１回合１次，在自己的主要阶段可以发动。此卡的种族直至回合结束时为止变为龙族。\n②：以场上的此卡作为素材融合・同步・超量召唤的怪兽获得以下效果。\n●此卡与龙族怪兽进行战斗的伤害步骤期间，此卡的攻击力变为原本攻击力的两倍。','\r',char(13)),'\n',char(10)),'种族变更','此卡的种族变更','「降龙之魔术师」效果适用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45674286,'机甲部队・断链备用体','此卡名的①②效果１回合仅可各使用１次。①：用抽牌以外的方法将此卡加入手牌的情况下可以发动。将此卡特殊召唤。此效果发动后，直至回合结束时为止自己仅可特殊召唤机械族怪兽。②：此卡召唤・特殊召唤成功的情况下可以发动。从牌组将“机甲部队・断链备用体”以外的１只“机甲部队”怪兽送至墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45675980,'烙印的即凶剧','此卡名的①效果１回合仅可使用１次。①：在自己・对手回合可以发动。将包含龙族怪兽在内的自己场上的怪兽作为素材同步召唤。②：只要自己场上有“渊兽”怪兽存在，为对手的仪式召唤而被解放并被送至对手墓地的怪兽，以及成为对手的融合・同步・连接召唤的素材并被送至对手墓地的怪兽，不去墓地而直接被除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45688586,'机偶蜘蛛','此卡攻击的场合，在伤害计算后破坏与此卡战斗过的暗属性怪兽。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45700805,'等离子战士 原能',replace(replace('此卡名在规则上也视为“磁石之战士”卡。\r\n此卡不可通常召唤。\r\n“等离子战士 原能”1回合1次，仅可在解放自己场上1只等级7以上的怪兽的情况下，从手牌・墓地特殊召唤。\r\n①：1回合1次，从牌组将除“等离子战士 原能”以外的、1只“磁石战士”怪兽或“磁石之战士”怪兽送至墓地可以发动。此回合，此卡的原本攻击力变为1500，且可直接攻击。','\r',char(13)),'\n',char(10)),'','直接攻击','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45702014,'元素军刀 莫雷夫',replace(replace('①：１回合１次，可从手牌将１只“元素军刀”怪兽送入墓地，并以场上的１只表侧表示怪兽为对象发动。将该怪兽变成里侧守备表示。此效果在对手回合也可发动。\r\n②：此卡存在于墓地的场合，１回合１次，可宣言１个属性并发动。直至回合结束时，墓地的此卡变成宣言之属性。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45702357,'天翻地转甲壳虫',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡召唤・特殊召唤成功的情况下发动。将此卡及与此卡同一纵列的怪兽全部改成里侧守备表示。\r\n②：此卡反转的情况下发动。将此卡及与此卡同一纵列的表侧表示怪兽全部放回持有者的牌组。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45705025,'纹章兽 独角兽',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：将墓地的此卡除外，以自己墓地的1只念动力族超量怪兽为对象可以发动。将该怪兽特殊召唤。以此效果特殊召唤的怪兽的效果无效化。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45710945,'银河眼时空源龙',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：在自己・对手回合中，场上存在龙族超量怪兽的情况下可以发动。从手牌将此卡特殊召唤至自己或对手场上。\r\n②：此卡召唤・特殊召唤的情况下发动。此卡原本的持有者从自身的牌组将１张“时空”魔法・陷阱卡加入手牌。\r\n③：自己或对手的龙族超量怪兽的攻击宣言时发动。将场上的此卡作为该怪兽的超量素材。','\r',char(13)),'\n',char(10)),'特殊召唤','检索','变成超量素材','往自己场上特殊召唤','往对手场上特殊召唤','','','','','','','','','','','');
INSERT INTO texts VALUES(45711266,'朱罗纪・翼龙','此卡在被攻击的伤害计算后，将攻击怪兽返回至持有者手牌。此卡的守备力上升因此效果返回至手牌的怪兽等级×１００点。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45716579,'地缚戒隶 地画克拉肯',replace(replace('“地缚”怪兽×２\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡特殊召唤的情况下可以发动。从自己的牌组・墓地将１张场地魔法卡加入手牌。\r\n②：怪兽被从对手的额外牌组特殊召唤的情况下可以发动。将对手场上在此回合被特殊召唤的怪兽全部破坏，给予对手相当于所破坏怪兽数量×８００的伤害。','\r',char(13)),'\n',char(10)),'牌组检索','特殊召唤的对手怪兽破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45725480,'七星宝刀','此卡名的卡１回合仅可发动１张。①：从手牌及自己场上的表侧表示怪兽中，将１只等级７怪兽除外可以发动。自己从牌组抽２张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45730592,'魔救共振击','①：自己场上存在“魔救”同步怪兽，且怪兽的效果发动时可以发动。将该发动无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45742626,'巡死神 收割者',replace(replace('等级6怪兽×2\r\n此卡名的②效果1回合仅可使用1次。\r\n①：此卡的攻击力・守备力上升双方墓地的暗属性怪兽的数量×200的数值。\r\n②：去除此卡的1个超量素材可以发动。从双方牌组上面将5张卡送至墓地。','\r',char(13)),'\n',char(10)),'牌组送墓','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45778242,'克莱因蚁',replace(replace('①：只要通常召唤而来的此卡存在于怪兽区，我方场上的电子界族怪兽的攻击力、守备力在我方回合期间上升５００。\r\n②：场上的此卡因战斗、效果被破坏的场合，可将我方手牌、场上的１只电子界族怪兽破坏作为代替。','\r',char(13)),'\n',char(10)),'是否使用「克莱因蚁」的效果代替破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45778932,'沙漠风暴','场上的风属性怪兽的攻击力上升５００点，守备力下降４００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45792753,'游魊链',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：将自己场上１只表侧表示的鱼族怪兽除外可以发动。从自己的手牌・牌组・墓地・除外状态将原本卡名与为发动此卡而除外的怪兽不同的１只“游魊”怪兽特殊召唤。以此效果特殊召唤的怪兽从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45796834,'光天之摩诃毗卢',replace(replace('①：此卡根据此卡的装备卡的数量获得以下效果。\r\n●１张以上：此卡的攻击力上升相当于此卡的装备卡数量×１０００的数值。\r\n●２张以上：对手在战斗阶段中不可发动怪兽的效果。\r\n●３张以上：以此卡作为对象的对手效果发动时，将自己场上的１张装备卡送至墓地可以发动。将该效果无效。\r\n●４张以上：对手在战斗阶段中不可发动卡的效果。\r\n●５张以上：此卡给予对手的战斗伤害变为两倍。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45801022,'电力狐猴','此卡被对手破坏的情况下发动。下一个对手回合，对手不可进行战斗阶段。','对手不可进行战斗阶段','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45803070,'蝇狱之虫惑魔',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：此卡召唤时，以自己墓地的１只“虫惑魔”怪兽为对象可以发动。将该怪兽以守备表示特殊召唤。\r\n②：此卡特殊召唤时，以自己墓地的１张“空洞”通常陷阱卡或“落穴”通常陷阱卡为对象可以发动。将该卡放置在自己场上。以此效果放置的卡将在下个自己回合的结束阶段被除外。\r\n③：此卡不受“空洞”通常陷阱卡及“落穴”通常陷阱卡的效果影响。','\r',char(13)),'\n',char(10)),'特殊召唤','放置','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45809008,'命运抽牌','①：从手牌将1张“命运-英雄”卡舍弃可以发动。自己从牌组抽2张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45812361,'卡片车 D',replace(replace('此卡无法特殊召唤。\r\n发动此卡效果的回合，我方不能特殊召唤怪兽。\r\n①：成功召唤这张卡的我方主要阶段１期间，可以解放这张卡发动。我方从卡组中抽２张卡。然后，进入该回合的结束阶段。','\r',char(13)),'\n',char(10)),'抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45815891,'废铁死亡恶魔','协调＋１只以上协调以外的怪兽','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45819647,'神圣魔皇后 塞勒涅',replace(replace('包含魔法师族怪兽在内的怪兽2只以上\r\n①：此卡连接召唤的情况下发动。依双方场上・墓地的魔法卡的数量在此卡上放魔力计数物。\r\n②：只要场上有“恩底弥翁”卡存在，对手怪兽不可将此卡选择为攻击对象。\r\n③：1回合1次，在自己・对手的主要阶段，去除自己场上的3个魔力计数物可以发动。从自己手牌・墓地挑选1只魔法师族怪兽，以守备表示特殊召唤至此卡连接端的自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45836982,'地缚超神官',replace(replace('此卡名的①②③效果１回合仅可各使用１次。\r\n①：自己的场上・墓地都存在同步怪兽的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：在自己的主要阶段可以发动。从自己的牌组・墓地将１只“地缚神”怪兽加入手牌。\r\n③：此卡存在于怪兽区域的状态下，“地缚神”怪兽被召唤的情况下可以发动。对手的LP变为３０００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45852939,'蚀之双子',replace(replace('等级4怪兽×2\r\n要超量召唤此卡的情况下，可将自己场上的阶级4怪兽作为等级4怪兽来作为素材。\r\n此卡名的②效果1回合仅可使用1次。\r\n①：去除此卡的1个超量素材可以发动。此回合，此卡在1次战斗阶段中最多可攻击怪兽2次。\r\n②：此卡被送至墓地的情况下，以自己墓地2只其他的阶级4以下的超量怪兽为对象可以发动。将该2只中的1只特殊召唤，另1只作为其超量素材。','\r',char(13)),'\n',char(10)),'2次攻击','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45869829,'速攻魔力增幅器','从我方墓地选择１张除“速攻魔力增幅器”以外的速攻魔法卡返回至牌组。此外，场上的此卡因对手被破坏并送入墓地时可发动。从牌组将１张除“速攻魔力增幅器”以外的速攻魔法卡加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45871897,'失落守护者','此卡的原本守备力变为被除外的我方岩石族怪兽数量×７００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45877457,'魔键炮－加雷斯维特',replace(replace('以“魔键－马夫提亚”降临。\r\n此卡名的②③效果１回合仅可各使用１次。\r\n①：此卡的攻击力上升相当于自己墓地怪兽属性种类×３００的数值。\r\n②：使用于此卡的仪式召唤的怪兽的属性为２种以上的情况下，对手发动拥有与自己墓地任一怪兽相同的属性的怪兽的效果时可以发动。将该发动无效并破坏。\r\n③：仪式召唤的此卡被送至墓地的情况下可以发动。从牌组将１只“魔键”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','仪式召唤使用的怪兽的属性是2种类以上','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45883110,'引导之圣女 库妸㽗',replace(replace('此卡名在规则上也视为“教导”卡、“惨绝戏”卡。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将1只“阿尔白斯之落胤”或1张记载有该卡名的卡送至墓地。\r\n②：自己・对手的卡从额外牌组离开的情况下，以除“引导之圣女 库妸㽗”以外的、自己墓地的1只“阿尔白斯之落胤”或记载有该卡名的怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'从牌组把卡送至墓地','墓地怪兽特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45885288,'新帝王翔风龙',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：从手牌舍弃此卡和１只怪兽，以自己墓地的１只龙族通常怪兽为对象可以发动。将该怪兽特殊召唤。\r\n②：此卡被送至墓地的情况下可以发动。对手场上的所有怪兽的攻击力直至回合结束时为止下降５００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45894482,'俊足之基拉龙','①：此卡可从手牌中特殊召唤。②：以此卡的①方法特殊召唤成功的情况下发动。对手可挑选自身墓地的１只怪兽来特殊召唤。','对手特殊召唤','是否特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45895206,'消除黑暗的光','将对手场上里侧表示的怪兽全都变为表侧表示。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45898858,'键结－H２O','解放我方场上的２只“氢魔兽”和１只“氧魔兽”来发动此卡。从我方的手牌・牌组・墓地特殊召唤１只“水合龙”。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45906428,'奇迹结合','①：将自己场上・墓地的怪兽作为融合素材除外，将1只“元素－英雄”融合怪兽融合召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45909477,'月之使者','侍奉月之女神的战士。手持新月形的长茅发动攻击！','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45935145,'死祖之隶龙 窝落',replace(replace('等级6怪兽×2只以上\r\n此卡名的②效果1回合仅可使用1次。\r\n①：自己场上的怪兽的攻击力・守备力上升对手墓地的卡数量×100的数值。\r\n②：在自己・对手回合中，以对手墓地的1张卡为对象，依以下数量去除此卡的超量素材，可以发动相应效果。\r\n●1个：将对象卡放回牌组。\r\n●2个：对象卡为怪兽的情况下，以表侧表示或里侧守备表示特殊召唤至自己场上。除此以外的情况下，放置在自己场上。','\r',char(13)),'\n',char(10)),'取除1个超量素材','取除2个超量素材','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45939611,'小妖精','可以将１张手牌送至墓地发动。将这张卡的等级提升１。此效果１回合可以使用２次。','等级上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45939841,'龙卷','可支付５００点LP来发动此卡。选择场上１张表侧表示的魔法・陷阱卡并将其破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45943123,'飞空鱼雷','此卡名的①②效果1回合1次，仅可使用其中1个。①：以自己场上的1只水属性超量怪兽为对象可以发动。去除该怪兽的1个超量素材，给予对手相当于自己手牌数量×400数值的伤害。该怪兽的攻击力直至回合结束时为止，上升相当于以此效果给予的伤害数值的数值。②：从自己的墓地将此卡和1只水属性超量怪兽除外可以发动。自己从牌组抽2张。','伤害','抽牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45943516,'战吼的奇岩',replace(replace('此卡牌名的卡牌１回合只可发动１张。\r\n①：作为此卡发动时的效果处理，可从牌组将１只“战吼”怪兽加入手牌。\r\n②：我方场上不存在有怪兽或仅有战士族怪兽的场合，在我方、对手战斗阶段开始时可发动。从手牌特殊召唤１只我方场上不存在有其同名卡的“战吼”怪兽。\r\n③：我方战士族怪兽因战斗被破坏的场合，可将此卡送入墓地作为代替。','\r',char(13)),'\n',char(10)),'是否从牌组把1只「战吼」怪兽加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45945685,'单车机人','众多交通机人中，最亲近也是最受喜爱的交通机人。还可以装备辅助轮哦！','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45948430,'超战士的萌芽',replace(replace('“混沌士兵”仪式怪兽的降临所必需。此卡名的卡１回合仅可发动１张。①：为使合计等级为８，将以下任一组合的怪兽送至墓地，从自己的手牌・墓地将１只“混沌士兵”仪式怪兽仪式召唤。\r\n●手牌的１只光属性怪兽和牌组的１只暗属性怪兽\r\n●手牌的１只暗属性怪兽和牌组的１只光属性怪兽','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45950291,'升阶魔法－阿斯特拉尔之力','①：以自己场上阶级最高的1只超量怪兽为对象可以发动。将1只与该自己的怪兽种族・属性相同，阶级高2的怪兽重叠在对象怪兽上面，从额外牌组特殊召唤，且视为超量召唤。②：此卡存在于墓地的情况下，在自己抽牌阶段抽牌前可以发动。将此卡加入手牌。发动此效果的回合中，自己不可进行通常的抽牌，不可用“升阶魔法-阿斯特拉尔之力”的效果之外的方法特殊召唤怪兽。','加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45951104,'机器牧者',replace(replace('①：以对手场上的1只里侧守备表示怪兽或原本的持有者为自己的表侧表示怪兽为对象可以发动。对象怪兽不存在的情况下，或对象怪兽的原本的持有者为自己的情况下（里侧表示卡翻开确认），分别适用以下效果。\r\n●给予对手200伤害。\r\n●获得除对象怪兽外的、对手场上的所有怪兽的控制权。','\r',char(13)),'\n',char(10)),'发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45955628,'咒眼的眷属 卡托布莱帕斯',replace(replace('此卡牌名的①②效果１回合只可各使用１次。\r\n①：可以我方场上的１张“咒眼”魔法、陷阱卡为对象发动。直至下一个回合结束时，该卡仅１次不会因对手的效果被破坏。\r\n②：此卡存在于墓地，且我方场上存在有除“咒眼的眷属 卡托布莱帕斯”以外的“咒眼”怪兽的场合可发动。特殊召唤此卡。以此效果特殊召唤的此卡，从场上离开的场合被除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45960523,'玄化戴达罗斯',replace(replace('①：此卡因“玄化”怪兽的效果特殊召唤成功的场合可发动。将场上除此卡以外被特殊召唤的所有表侧表示怪兽除外。\r\n②：此卡被除外的场合，可在下一个回合的准备阶段将被除外的此卡返回至牌组并发动。从牌组将１张除“玄化戴达罗斯”以外的“玄化”卡牌除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45974017,'暗魔界的契约书',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：可从以下效果中选择1个发动。\r\n●以自己墓地的1只“DD”灵摆怪兽为对象可以发动。将该怪兽放在自己的灵摆区域。\r\n●从自己额外牌组（表侧）将1只“DD”灵摆怪兽放在自己的灵摆区域。\r\n②：在自己的准备阶段发动。自己受到1000伤害。','\r',char(13)),'\n',char(10)),'选择1个效果发动','自己墓地1只「DD」灵摆怪兽在灵摆区放置','额外牌组1只「DD」灵摆怪兽在灵摆区放置','受到1000伤害','','','','','','','','','','','','');
INSERT INTO texts VALUES(45985838,'日珥龙','自己场上有其他炎族怪兽存在的情况下，对手怪兽不可攻击此卡。自己结束阶段时发动。给予对手LP５００点伤害。','给予对手500伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(45986603,'强夺',replace(replace('可装备于对手场上的怪兽。\r\n①：获得装备怪兽的控制权。\r\n②：在对手的准备阶段发动。对手恢复1000LP。','\r',char(13)),'\n',char(10)),'对手回复1000基本分','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46001505,'王者的鼓动',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：可从以下效果中选择1个发动。\r\n●在对手的战斗阶段可以发动。对手恢复1000LP。然后，结束战斗阶段。\r\n●对手场上的卡的数量多于自己场上的卡，且对手发动怪兽的效果时可以发动。从自己额外牌组・墓地将1只“暗红恶魔龙”或“琰魔龙 暗红恶魔”特殊召唤，将该发动的效果无效并破坏。','\r',char(13)),'\n',char(10)),'发动','战斗阶段结束','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46005939,'灵摆超量','此卡名的卡１回合仅可发动１张。①：以自己灵摆区域的２张卡为对象可以发动。将该２张卡效果无效并特殊召唤，仅以该２只怪兽为素材，将１只超量怪兽超量召唤。在此之际，作为超量素材的１只怪兽的等级可视为与另１只怪兽相同。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46008667,'圣剑 传奇湖中剑',replace(replace('仅可装备于“圣骑士”怪兽。\r\n“圣剑 传奇湖中剑”的②效果１回合仅可使用１次。\r\n①：装备怪兽不会成为对手效果的对象。\r\n②：在自己的主要阶段将墓地的此卡除外，以自己场上的１只“圣骑士”超量怪兽为对象可以发动。将１只卡名与该自己的怪兽不同的“圣骑士”超量怪兽重叠在对象怪兽上面，视为超量召唤从额外牌组特殊召唤。此效果在此卡被送至墓地的回合不可发动。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46009906,'猛兽之齿','仅限装备兽族怪兽。令１只装备怪兽的攻击力和守备力上升３００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46014517,'格布林百罗刹唯我独尊',replace(replace('等级6怪兽×2只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：以自己场上的“格布林”怪兽的数量为上限，以对手场上的表侧表示怪兽为对象可以发动。去除自己场上的1个超量素材，将对象怪兽作为此卡的超量素材。\r\n②：在对手回合中，以自己场上的“格布林”超量怪兽的数量为上限，以对手场上的卡为对象可以发动。去除自己场上的3个超量素材，将对象卡送至墓地。','\r',char(13)),'\n',char(10)),'吸收超量素材','送至墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46031686,'伤害偏光镜','拥有给予伤害效果，并且怪兽的效果、魔法、陷阱卡发动时可发动。使该发动无效，并双方玩家各抽取１张卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46033517,'机甲部队 蹂躏武力','此卡不可通常召唤。仅在为使合计等级为１２以上而将自己墓地的机械族怪兽除外的情况下，可从墓地特殊召唤。此卡名的①②效果１回合仅可各使用１次。①：对手在战斗阶段发动效果时，支付一半LP可以发动。将该发动无效，将对手的LP改成一半。②：此卡因战斗・效果被破坏的情况下可以发动。挑选合计等级为１２以下的、最多３只自己被除外的“机甲部队”怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46035545,'DD 魔导贤者尼古拉',replace(replace('←8 【灵摆】 8→\r\n①：自己仅可灵摆召唤“DD”怪兽。此效果不会被无效化。②：１回合１次，从手牌将１只“DDD”怪兽舍弃，以自己场上１只等级６以下的“DD”怪兽为对象可以发动。该怪兽的攻击力・守备力直至回合结束时为止上升２０００。\r\n【怪兽效果】\r\n此卡名的怪兽效果１回合仅可使用１次。①：此卡在灵摆区域被破坏的情况下，以自己场上的１只“DDD”怪兽为对象可以发动。将该怪兽放回持有者的手牌，从自己的额外牌组挑选最多２只表侧表示“DD”灵摆怪兽，放在自己的灵摆区域。该卡的灵摆效果此回合不可发动。','\r',char(13)),'\n',char(10)),'攻守变换','回到手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46037213,'守护者・特莱斯','只有在我方场上有“闪光之双剑－特莱斯”存在的场合，才可召唤・反转召唤・特殊召唤此卡。此卡被破坏送入墓地时，从墓地中特殊召唤上级召唤此卡时所解放的怪兽至我方场上。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46037983,'游魊之灯 佩西斯',replace(replace('此卡名的①②③效果１回合仅可各使用１次。\r\n①：将场上的此卡除外可以发动。从手牌将“游魊之灯 佩西斯”以外的１只鱼族怪兽特殊召唤。\r\n②：在此卡被除外的下个回合的准备阶段可以发动。将除外状态的此卡特殊召唤。\r\n③：在此卡特殊召唤的对手回合的主要阶段可以发动。将包含此卡在内的自己场上的怪兽作为素材，将１只鱼族同步怪兽同步召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46044841,'薰风・隼','场上表侧表示的此卡以战斗以外的方式被送入墓地时，可从牌组以里侧守备表示特殊召唤１只冠有“薰风”之名的怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46052429,'高等仪式术','仪式怪兽降临所必须。①：为使合计等级与仪式召唤的怪兽相等，从牌组将通常怪兽送至墓地，从手牌将1只仪式怪兽仪式召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46057733,'燐回的三弦猫',replace(replace('协调＋１只以上协调以外的怪兽\r\n此卡名的①②效果１回合仅可各使用１次。①：在对手的主要阶段可以发动。将包含此卡在内的自己场上的怪兽作为素材同步召唤。②：此卡存在于墓地的情况下，以自己墓地此卡以外的１只同步怪兽为对象可以发动。将该怪兽放回额外牌组，将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46060017,'十二兽的会局',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：以自己场上的1张表侧表示卡为对象可以发动。将该卡破坏，从牌组将1只“十二兽”怪兽特殊召唤。\r\n②：此卡因效果被破坏并被送至墓地的情况下，以自己场上的1只“十二兽”超量怪兽为对象可以发动。将此卡作为该超量怪兽的超量素材。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46066477,'娱乐乐队飓风',replace(replace('“娱乐乐队飓风”１回合仅可发动１张。\r\n①：以对手场上的卡为对象可以发动，数量最多为自己场上“娱乐伙伴”怪兽的数量。将该卡放回持有者的手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46072770,'魅影骑士团衰朽斗篷',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：此卡存在于手牌的情况下，向对手出示手牌的1张其他“魅影骑士团”卡可以发动。将此卡特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从牌组将1只“魅影骑士团”怪兽加入手牌。\r\n③：将墓地的此卡除外，以自己场上的1只超量怪兽为对象可以发动。该超量怪兽在此回合，可当成与自身阶级的数值相同等级的怪兽，来作为超量召唤的素材。','\r',char(13)),'\n',char(10)),'特殊召唤','检索效果','赋予超量等级','「魅影骑士团 衰亡斗篷」效果适用中','','','','','','','','','','','','');
INSERT INTO texts VALUES(46083111,'机怪虫・树突','此卡名的①②效果1回合仅可各使用1次。①：此卡反转的情况下可以发动。从牌组将1只怪兽送至墓地。②：表侧表示的此卡因对手的效果从场上离开的情况下可以发动。将2只“机怪虫・树突”以外的“机怪虫”怪兽从牌组以里侧守备表示特殊召唤（同名卡最多1张）。','送至墓地','2只怪兽特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46083380,'攻通规则','对手场上有３只以上怪兽存在的情况下，对手怪兽不可攻击宣言。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46089249,'核杀轮','从手牌将１张“核成之钢核”出示给对手可以发动。选择场上的１只表侧表示怪兽破坏，双方受到１０００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46104361,'电子界白帽','此卡名以①方法的特殊召唤1回合仅可进行1次。①：自己场上有2只以上的同种族怪兽存在的情况下，此卡可从手牌中特殊召唤。②：此卡作为连接素材被送至墓地的情况下可以发动。对手场上的全部怪兽的攻击力直至回合结束时为止下降1000。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46123974,'书灵师・极客少年',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡存在于手牌的情况下，向对手出示手牌的1只仪式怪兽可以发动。将此卡特殊召唤。\r\n②：此卡特殊召唤的情况下可以发动。从牌组将1张“书灵师”魔法卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46128076,'黑魔法师 库兰','我方的准备阶段时，给予对手生命相当于存在于对手场上的怪兽数量×３００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46130346,'火球','给予对手５００伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46132282,'甲化铠骨骼',replace(replace('协调＋协调以外的怪兽１只以上\r\n①：此卡同步召唤的情况下发动。此回合，此卡不会因战斗・效果被破坏，自己受到的全部伤害变为０。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46136942,'娱乐伙伴 异色眼溶解者',replace(replace('←4 【灵摆】 4→\r\n①：１回合１次，在自己的主要阶段可以发动。从自己的手牌・场上，将由龙族融合怪兽卡决定的融合素材怪兽送至墓地，将该１只融合怪兽从额外牌组融合召唤。\r\n【怪兽效果】\r\n此卡名的①怪兽效果１回合仅可使用１次。①：自己的灵摆怪兽与对手怪兽进行战斗的伤害步骤开始时可以发动。将此卡从手牌特殊召唤，该自己的怪兽不会因该战斗被破坏。②：在自己的主要阶段可以发动。将由融合怪兽卡决定的、包含此卡在内的融合素材怪兽从自己场上送至墓地，将该１只融合怪兽从额外牌组融合召唤。在此之际，存在于自己的灵摆区域的融合素材怪兽也可作为融合素材使用。','\r',char(13)),'\n',char(10)),'融合召唤','此卡从手牌特殊召唤','使用灵摆区怪兽融合召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46145256,'闪光之结界像','①：只要此卡存在于怪兽区域，双方只能特殊召唤光属性怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46148485,'转轮的斯芬克斯',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：怪兽的表示形式被变更的情况下，从自己墓地将1张魔法卡除外可以发动。从手牌・墓地将此卡特殊召唤。\r\n②：在自己的主要阶段可以发动。从自己牌组・墓地将“太阳之书”和“月之书”最多各1张放置在自己的魔法与陷阱区域。\r\n③：1回合1次，场上的其他怪兽的表示形式被变更的情况下，以场上的1张卡为对象可以发动。将该卡放回手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','放置','回到手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46159582,'咒仪之仪水镜','“咒仪”仪式怪兽的降临所必需。①：为使合计等级与仪式召唤的怪兽相等，解放自己手牌・场上的怪兽，从手牌将１只“咒仪”仪式怪兽仪式召唤。②：将墓地的此卡放回牌组，以自己墓地的１只“咒仪”仪式怪兽为对象可以发动。将该怪兽加入手牌。','墓地的仪式怪兽回到手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46169154,'战吼・奥比斯',replace(replace('此卡牌名的②效果１回合只可使用１次。\r\n①：我方场上不存在有怪兽或仅有战士族怪兽的场合，此卡可无需解放进行召唤。\r\n②：于我方战士族・地属性怪兽进行了战斗之伤害计算后可发动。从牌组将１只除“战吼・奥比斯”以外的战士族・地属性怪兽送入墓地。之后，直至对手回合结束时，我方场上全部“战吼”怪兽的攻击力上升２００。','\r',char(13)),'\n',char(10)),'不用解放作召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46173679,'末日之焰','发动此卡的回合中，我方不可进行召唤・反转召唤・特殊召唤。以守备表示特殊召唤２只“黑焰衍生物”（恶魔族・暗・１星・攻／守０）至我方场上。不可解放该衍生物上级召唤除暗属性怪兽以外的怪兽。','特殊召唤衍生物','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46173680,'黑焰衍生物','由“末日之焰”的效果特殊召唤而来。除暗属性的怪兽外，此衍生物不可用作其他上级召唤的祭品。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46173681,'黑焰衍生物','由“末日之焰”的效果特殊召唤而来。除暗属性的怪兽外，此衍生物不可用作其他上级召唤的祭品。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46174776,'杀戮圣徒 摩尔蕾吉娜',replace(replace('幻想魔族怪兽＋等级６以上的恶魔族怪兽\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：以自己墓地“杀戮圣徒 摩尔蕾吉娜”以外的１只幻想魔族怪兽为对象可以发动。将该怪兽特殊召唤。\r\n②：“杀戮圣徒 摩尔蕾吉娜”以外的“圣徒”卡或“罪宝”卡的效果发动时，以场上的最多２张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'墓地特殊召唤','破坏效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46181000,'前线基地','１回合１次，可在我方的主要阶段时从手牌特殊召唤１只等级４以下的联合怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46186135,'神光之龙',replace(replace('“裁决之龙”＋“惩戒之龙”\r\n仅可在从自己场上及墓地将上述卡各１只除外的情况下特殊召唤。\r\n①：在每个自己・对手回合中１次，支付２０００LP可以发动。将此卡以外的、双方场上・墓地的卡全部除外。\r\n②：在自己的结束阶段发动。从自己的牌组上面将４张卡送至墓地。\r\n③：此卡被对手破坏的情况下可以发动。将自己除外状态的“裁决之龙”、“惩戒之龙”各１只加入手牌。然后，可将该２只无视召唤条件特殊召唤。','\r',char(13)),'\n',char(10)),'场上·墓地的卡全部除外','从牌组送至墓地','回收','是否无视条件特殊召唤？','','','','','','','','','','','','');
INSERT INTO texts VALUES(46195773,'涡轮战士',replace(replace('“涡轮同步士”＋1只以上协调以外的怪兽\r\n①：场上的此卡不会成为等级6以下怪兽的效果的对象。②：此卡攻击等级6以上同步怪兽的攻击宣言时发动。将该怪兽的攻击力直至伤害步骤结束时为止改成一半。','\r',char(13)),'\n',char(10)),'攻击对象攻击变成一半','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46221535,'钻头武装龙',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从手牌将此卡与1只风属性怪兽送至墓地可以发动。此回合中，自己场上的龙族・风属性怪兽的攻击力上升300。\r\n②：从自己墓地将任意数量的风属性或等级7以上的、龙族怪兽除外可以发动。从牌组将“钻头武装龙”以外的、1只等级与所除外的怪兽的数量相同的龙族怪兽加入手牌。','\r',char(13)),'\n',char(10)),'攻击力上升','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46232525,'海尔摩斯之爪',replace(replace('此卡的卡牌名称在规则上视为“传说之龙 海尔摩斯”。\r\n１个回合中只可发动１张“海尔摩斯之爪”。\r\n①：将只有“海尔摩斯之爪”的效果才可特殊召唤的融合怪兽卡记述的种族的１只怪兽从我方手牌・场上送入墓地（该卡被盖牌在场上的场合，翻开进行确认）。之后，从额外牌组特殊召唤１只该融合怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46237548,'红莲魔斗士','当我方墓地中只有３只通常怪兽存在的场合，可将我方墓地中的２只通常怪兽从游戏中除外，从手牌特殊召唤此卡。１回合１次，可选择我方墓地中１只等级４以下的通常怪兽并特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46239604,'魔知青蛙',replace(replace('①：此卡只要存在于怪兽区域，卡名视为“死亡青蛙”。\r\n②：只要此卡存在于怪兽区域，对手怪兽不可将其他怪兽选择为攻击对象。\r\n③：此卡从场上被送至墓地时可以发动。从自己牌组・墓地将“魔知青蛙”以外的1只“青蛙”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46241344,'炎星仙－鹫真人',replace(replace('兽战士族怪兽２只\r\n自己１回合仅可特殊召唤１次“炎星仙－鹫真人”，其②效果１回合仅可使用１次。\r\n①：只要此卡存在于怪兽区域，自己可以不用将自己的手牌・场上的“炎星”卡及“炎舞”卡送至墓地就能发动“炎星”怪兽的效果。\r\n②：以自己的场上・墓地的１张“炎舞”魔法・陷阱卡为对象可以发动。将该卡放回手牌。然后，从牌组将１只“炎星”怪兽送至墓地。','\r',char(13)),'\n',char(10)),'是否不把卡送至墓地发动？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46247282,'铁骑龙提亚马顿','此卡不可通常召唤，仅可通过此卡的①效果特殊召唤。此卡名的①效果1回合仅可使用1次。①：3张以上的卡存在于同一纵列的情况下可以发动。从手牌将此卡特殊召唤。此效果在对手回合中也可以发动。②：此卡特殊召唤成功的情况下发动。将与此卡同一纵列的其他卡全部破坏。③：只要此卡存在于怪兽区域，与此卡同一纵列的未使用的区域不可使用。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46247516,'阴阳师 道','侵蚀阴阳的力量，孕育出扭曲之力的魔导士。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46253216,'误伤队友','①：对手的魔法、陷阱、怪兽效果发动时，可以场上除该卡以外的１张卡牌为对象发动。破坏对象卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46259438,'契约洗净','①：将自己的魔法与陷阱区域的“契约书”卡全部破坏，自己依其数量抽牌。然后，自己恢复所抽数量×1000LP。','卡片破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46261704,'盖勒库里波','此卡名在规则上也视为“银河”卡。①：对手怪兽攻击宣言时，从手牌将此卡舍弃可以发动。从手牌・牌组将１只“银河眼光子龙”特殊召唤。然后，攻击对象移换为该怪兽。进而可挑选自己或对手场上的１只超量怪兽，将墓地的此卡重叠在该怪兽下方作为超量素材。②：自己场上的“光子”怪兽或“银河”怪兽将被战斗或对手的效果破坏的情况下，作为代替可将墓地的此卡除外。','','','是否选超量怪兽将此卡作为超量素材？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46263076,'地缚神 Ccapac Apu',replace(replace('①：“地缚神”怪兽在场上仅可有1只以表侧表示存在。\r\n②：此卡可直接攻击。\r\n③：对手怪兽不可将此卡选择为攻击对象。\r\n④：不存在表侧表示的场地魔法卡的情况下，此卡将被破坏。\r\n⑤：此卡战斗破坏对手怪兽的情况下发动。给予对手该怪兽的原本攻击力数值的伤害。','\r',char(13)),'\n',char(10)),'伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46271408,'闪刀术式－剪除交刃','①：自己的主要怪兽区域没有怪兽存在的情况下，以自己墓地的1只等级4“闪刀姬”怪兽为对象可以发动。将该怪兽加入手牌。自己墓地存在3张以上的魔法卡的情况下，也可不加入手牌而是改为将其特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46272804,'长矛麟龙','①：此卡攻击了守备表示怪兽的场合，给予攻击力超过该守备力数值的战斗伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46290741,'城塞鲸',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：此卡存在于手牌・墓地的情况下，解放自己场上的2只水属性怪兽可以发动。将此卡特殊召唤。\r\n②：此卡特殊召唤的情况下可以发动。从牌组将1张“潜海奇袭”放置在自己场上。\r\n③：1回合1次，对手发动仅以自己场上的1只水属性怪兽为对象的魔法・陷阱・怪兽的效果时可以发动。将该发动无效并破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46291010,'超能兽','此卡召唤成功时，可从我方牌组将１只念动力族怪兽从游戏中除外。此卡变成与以此效果除外的怪兽相同等级。','等级变换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46294982,'女巫特露德',replace(replace('①：场地区域有“急流山的金宫”存在的情况下，此卡无需解放即可召唤。\r\n②：１回合１次，场地区域存在“急流山的金宫”的情况下，以场上此卡以外的１张卡为对象可以发动。将该卡破坏，此回合，此卡在１次战斗阶段中最多可攻击怪兽２次。\r\n③：此卡战斗破坏怪兽时，以自己场上的１只表侧表示怪兽为对象可以发动。该怪兽的攻击力上升４００。','\r',char(13)),'\n',char(10)),'不用解放作召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46303688,'轮盘炸弹','１回合１次，在我方主要阶段时可发动。掷２次骰子，挑选１个掷出的点数，并挑选１只持有等级与该数量相同的场上怪兽破坏。','掷骰子','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46337945,'仪水镜之冥想术','①：将手牌的１张仪式魔法卡出示给对手，以自己墓地的２只“咒仪”怪兽为对象可以发动。将该怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46354113,'火箭海尔摩斯加农炮',replace(replace('仅限以“海尔摩斯之爪”的效果将我方手牌、场上的战士族怪兽送入墓地的场合，此卡可特殊召唤。\r\n①：此卡特殊召唤成功的场合，以场上除此卡以外的１只怪兽为对象发动。此卡被视为装备卡装备该怪兽。\r\n②：以此卡效果装备此卡的怪兽，在１次的战斗阶段中可攻击２次，攻击了守备表示怪兽的场合，给予对手相当于攻击力超过该守备力数值的战斗伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46358784,'高等宝玉兽 翠玉龟',replace(replace('①：场地区域不存在“高等暗黑”的情况下，此怪兽将被送至墓地。\r\n②：１回合１次，以场上的１只表侧表示怪兽为对象可以发动。变更该怪兽的表示形式。此效果在对手回合中也可以发动。\r\n③：表侧表示的此卡在怪兽区域被破坏的情况下，可不送至墓地，而是视为永续魔法卡以表侧表示放在自己的魔法与陷阱区域。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46363422,'熟练的白魔导师','只要此卡以表侧表示存在于场上，每次我方或对手发动魔法卡，在此卡放置１个魔力计数物（最多３个）。此外，可解放放置有３个魔力计数物的此卡并发动。从我方手牌・牌组・墓地挑选１只“毁灭剑士”特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46372010,'地狱门的契约书',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：在自己的主要阶段可以发动。从牌组将1只“DD”怪兽加入手牌。\r\n②：在自己的准备阶段发动。自己受到1000伤害。','\r',char(13)),'\n',char(10)),'牌组检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46382143,'源数创造','此卡名在规则上也视为“银河眼”卡。此卡名的效果１回合仅可适用１次。①：原本攻击力为３０００以上的龙族・光属性怪兽在场上有３只以上存在的情况下可以发动。从额外牌组将１只龙族“编号”超量怪兽特殊召唤。然后，将场上的此卡重叠在该怪兽下方作为超量素材。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46384403,'迅捷蝠鲼','场上的此卡因卡牌效果被送入墓地时，可从牌组特殊召唤任意数量的“迅捷蝠鲼”。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46384672,'武装龙 LV5','①：从手牌将１只怪兽送至墓地，以对手场上１只拥有该怪兽的攻击力以下攻击力的怪兽为对象可以发动。将拥有为发动此效果而送至墓地的怪兽的攻击力以下攻击力的该对手的怪兽破坏。②：在此卡战斗破坏怪兽的回合的结束阶段，将场上的此卡送至墓地可以发动。从手牌・牌组将１只“武装龙 LV7”特殊召唤。','破坏','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46396218,'背信圣徒 雷亚西尔薇亚',replace(replace('幻想魔族怪兽＋魔法师族・光属性怪兽\r\n此卡名的②③效果１回合仅可各使用１次。\r\n①：“背信圣徒 雷亚西尔薇亚”以外的、自己的“圣徒”怪兽给予对手的战斗伤害变为两倍。\r\n②：对手发动魔法・陷阱・怪兽的效果时，解放此卡可以发动。将该效果无效。\r\n③：此卡因战斗・效果被破坏的情况下可以发动。从牌组将１张“罪宝”陷阱卡加入手牌。','\r',char(13)),'\n',char(10)),'效果无效','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46404281,'岩浆炎熔岩炮兵','从手牌将１只炎属性怪兽送至墓地可以发动。给予对手LP５００点伤害。此效果１回合最多可以使用２次。','给与对手500伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46411259,'突然变异','①：解放自己场上的1只怪兽可以发动。从额外牌组将1只等级与该怪兽相同的融合怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46412900,'火山性帝皇',replace(replace('此卡不可通常召唤。\r\n仅可在从自己的场上（表侧表示）・墓地将３只炎族怪兽或１张“烈焰加农炮”卡除外的情况下，从手牌・墓地特殊召唤。\r\n自己１回合仅可特殊召唤１次“火山性帝皇”。\r\n \r\n①：此卡以此方法特殊召唤时可以发动。给予对手相当于除外状态的炎族怪兽的数量×５００的伤害。然后，可从牌组将１张“火山性”陷阱卡放置在自己场上。 \r\n②：每次对手特殊召唤怪兽，给予对手５００伤害。','\r',char(13)),'\n',char(10)),'','','是否把1张「火山」陷阱卡在自己场上放置？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46425662,'元素军刀 娜鲁',replace(replace('①：１回合１次，可从手牌将１只“元素军刀”怪兽送入墓地，并以我方墓地１只除“元素军刀・娜鲁”以外的“元素军刀”怪兽或“灵神”怪兽为对象发动。将该怪兽加入手牌。\r\n②：此卡存在于墓地的场合，１回合１次，可宣言１个属性并发动。直至回合结束时，墓地的此卡变成宣言之属性。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46427957,'破灭之女神 露茵',replace(replace('以“世界终灭”降临\r\n①：以此卡的攻击破坏对手怪兽时可以发动。此卡可继续再攻击仅1次。','\r',char(13)),'\n',char(10)),'连续攻击','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46435376,'无限狱贤者',replace(replace('此卡牌名的①②效果１回合只可各使用１次。\r\n①：在我方主要阶段可发动。舍弃我方的所有手牌。\r\n②：此卡被送入墓地的场合可发动。从牌组将１只“无限狱”怪兽送入墓地。此效果在我方手牌是０张的场合，可发动与处理。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46448938,'魔导书的神判','此卡发动过的余下回合的结束阶段时，从自己的牌组将“魔导书的神判”以外的“魔导书”魔法卡加入手牌，数量最多为在此卡发动后，自己或对手发动的魔法卡的张数。然后，可将１只等级数值低于以此效果加入手牌的卡数量的魔法师族怪兽从牌组特殊召唤。“魔导书的神判”１回合仅可发动１张。','检索效果','是否要把1只魔法师族怪兽从牌组特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46457856,'死党恐龙','体型虽小，但性格凶狠狂暴。同伴之间也会发生争抢。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46461247,'陷阱大师','反转：选择场上的１张陷阱卡并将其破坏。选择被盖牌的卡牌的场合，翻开该卡进行确认，若为陷阱卡则破坏，若为魔法卡的场合则恢复原状。','陷阱破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46474915,'魔法幽灵','使用魔法，让对方陷于恐惧与混乱后发动攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46480475,'不协和音','只要此卡存在于场上，双方玩家不可进行同步召唤。发动后第３回合的自己的结束阶段时将此卡送往墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46485778,'烹鱼大厨・饿魔新飨',replace(replace('←8 【灵摆】 8→\r\n此卡名的灵摆效果１回合仅可使用１次。\n①：自己场上存在仪式怪兽的情况下，以场上的１只怪兽为对象可以发动。将此卡特殊召唤。然后，变更该对象怪兽的表示形式。\r\n【怪兽效果】\r\n此卡名的①怪兽效果１回合仅可使用１次。\n①：此卡召唤・特殊召唤的情况下，可从以下效果中选择１个发动。\n●从牌组将１只等级１仪式怪兽或１张“食谱”卡加入手牌。\n●从自己的墓地将任意数量的“食谱”卡除外，从手牌将１只等级数值与其数量相同的“饿魔新飨”仪式怪兽特殊召唤。\n②：场上的此卡被解放并以表侧加入额外牌组的情况下可以发动。将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'','','','从牌组加入手牌','从手牌特殊召唤','','','','','','','','','','','');
INSERT INTO texts VALUES(46497537,'猪铁对笔钉',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：以场上的１只表侧表示怪兽为对象可以发动。该怪兽的攻击力・守备力・等级中，高于原本数值的数值变为原本数值。然后，支付１００倍数的LP（最多１０００）。\r\n②：此卡存在于墓地，自己的LP与对手相同的情况下，在自己的主要阶段可以发动。将此卡放置在自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46500985,'炼金阵式',replace(replace('①：我方场上的“炼装”怪兽之攻击力、守备力上升３００。\r\n②：只要我方灵摆区存在有“炼装”卡牌，我方场上除效果怪兽以外的“炼装”怪兽不会受到对手效果的影响。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46502013,'妖精之轮','我方场上存在有２只或以上的表侧攻击表示怪兽的场合，对手怪兽不可选择我方场上攻击力最低的怪兽作为攻击对象。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46502744,'应战的Z',replace(replace('①：对手发动包含将怪兽特殊召唤的效果在内的魔法卡时可以发动（同一连锁上最多1次）。从手牌将此卡特殊召唤。\r\n②：只要以此卡的①效果特殊召唤的此卡存在于怪兽区域，被送往墓地的卡不去墓地而直接被除外。\r\n③：此卡从场上被送至墓地的情况下可以发动。从牌组将除“应战的Z”以外的、攻击力1500以下的1只昆虫族・地属性怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46508640,'龙脉栖息者','此卡的攻击力上升相当于以表侧表示存在于我方魔法＆陷阱卡区的永续魔法卡的数量×３００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46518210,'溟界神－涅斐尔邃渊',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡存在于墓地的状态下，怪兽从自己或对手的手牌・牌组被送至墓地的情况下可以发动。将此卡特殊召唤。此效果发动后，直至下个回合结束时为止，自己仅可特殊召唤爬虫类族怪兽。\r\n②：此卡是从墓地被特殊召唤的情况下，以自己墓地“溟界神－涅斐尔邃渊”以外的１只怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46533533,'皮缇','寄居在玻璃瓶里的可爱家伙，被认为会给契约者带来好运。其盖子绝对不可打开。不管发生什么事，都绝对不可以……','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46534755,'火焰乌贼','一只全身燃烧着火焰的乌贼，即使在水中火焰也依然熊熊燃烧着。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46552140,'魔救拉普达石','①：自己场上的岩石族怪兽的攻击力・守备力上升500。②：1回合1次，自己的主要阶段可以发动。从牌组挑选最多5张“魔救”卡以喜欢的顺序放在牌组最上面。','','请选择要放置牌组最上面的卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46565218,'撒旦老人',replace(replace('①：此卡可以解放对手场上１只怪兽，以守备表示从手牌特殊召唤至对手场上。\r\n②：在此卡以此卡的①方法被特殊召唤的回合的结束阶段可以发动。自己抽１张。','\r',char(13)),'\n',char(10)),'抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46570372,'镇魂之决斗',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：双方可从自身的墓地挑选１只在此回合因战斗被破坏的怪兽，以攻击表示特殊召唤。自己以此效果特殊召唤的怪兽是“元素－英雄 新宇侠”的情况下，此回合，该怪兽与对手怪兽进行战斗的伤害步骤期间，该怪兽的攻击力变为两倍。','\r',char(13)),'\n',char(10)),'是否从墓地特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46571052,'血兰','成功召唤此卡时，可从手牌特殊召唤１只“死亡石斛”。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46572756,'真次代机・极金','①：场上表侧表示的此卡被破坏并被送至墓地时，以自己墓地的２只“次代机”怪兽为对象可以发动。将该怪兽放回牌组。','返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46576366,'抒情歌鸲－天青白鹡鸰','此卡名的①②效果1回合仅可各使用1次。①：此卡特殊召唤成功的情况下可以发动。从牌组将1张“抒情歌鸲”魔法・陷阱卡加入手牌。②：此卡存在于墓地的情况下，以自己场上的1只“抒情歌鸲”超量怪兽为对象可以发动。将此卡重叠在该怪兽下面作为超量素材。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46589034,'急袭猛禽－痛苦伯劳','此卡名的效果1回合仅可使用1次，此卡作为超量召唤的素材的情况下，仅可使用于鸟兽族怪兽的超量召唤。①：在此卡存在于手牌中的情况下，以自己场上的1只“急袭猛禽”怪兽为对象可以发动。自己受到该怪兽的攻击力或守备力之中较低方数值的伤害，从手牌将此卡特殊召唤。以此效果特殊召唤的此卡的等级变为与对象的怪兽的等级相同。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46593546,'DDD 赦俿王死亡降神',replace(replace('←10 【灵摆】 10→\r\n此卡名的灵摆效果１回合仅可使用１次。①：另一方的自己的灵摆区域有卡存在的情况下，以自己的场上・墓地的１只灵摆怪兽为对象可以发动。将另一方的自己的灵摆区域的卡特殊召唤，将对象的灵摆怪兽放在自己的灵摆区域。\r\n【怪兽效果】\r\n恶魔族等级１０怪兽×２\n此卡也可重叠在自己场上的“DDD”怪兽上面来超量召唤。①：“DDD 赦俿王死亡降神”在自己的怪兽区域仅可有１只以表侧表示存在。②：对手场上的怪兽卡发动效果时可以发动（同一连锁上最多１次）。去除此卡的２个超量素材，或将自己场上的１张“契约书”卡破坏，将该对手的卡作为此卡的超量素材。③：在自己的准备阶段可以发动。将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'是否在「DDD」怪兽上面重叠来超量召唤？','特殊召唤灵摆区域的怪兽','发动效果的怪兽作为超量素材','此卡在自己的灵摆区域放置','请选择要放置到灵摆区域的卡','此卡2个超量素材取除','自己场上1张「契约书」卡破坏','','','','','','','','','');
INSERT INTO texts VALUES(46606977,'星义・护伞','此卡名的①②效果1回合仅可各使用1次。①：以“星义・护伞”以外的、自己1只被除外的怪兽为对象可以发动。将此卡从手牌特殊召唤，将对象怪兽放回牌组。②：以自己墓地的1只“星义・护伞”以外的“星义”怪兽为对象可以发动。将该怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46609443,'混沌终结王','此卡因战斗破坏对手怪兽并送入墓地时，可从牌组特殊召唤１只等级５或以上，且攻击力是１６００或以下的怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46613515,'洁净库里波',replace(replace('此卡牌名的②效果１回合只可使用１次。\r\n①：对手发动给予伤害怪兽的效果时，可从手牌舍弃此卡并发动。使该发动无效。\r\n②：对手怪兽的直接攻击宣言时，可将墓地的此卡除外并发动。我方从牌组抽取１张卡牌。该抽取之卡牌是怪兽的场合，可进一步特殊召唤该怪兽。之后，将攻击对象转移至该怪兽。','\r',char(13)),'\n',char(10)),'伤害效果的发动无效','把墓地的此卡除外','是否把那只怪兽特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46640168,'泪魔镌刻・拉克莉末莎',replace(replace('恶魔族・光属性怪兽×２\r\n此卡名的①③效果１回合仅可各使用１次。\r\n①：此卡融合召唤的情况下，以自己墓地・除外状态的１只恶魔族・光属性怪兽为对象可以发动。将该怪兽加入手牌或特殊召唤。\r\n②：只要此卡存在于怪兽区域，对手场上的怪兽的攻击力下降６００。\r\n③：此卡被送至墓地的情况下，从自己的墓地将１只其他的恶魔族・光属性怪兽放回牌组・额外牌组可以发动。给予对手１２００伤害。','\r',char(13)),'\n',char(10)),'加入手牌或特殊召唤','给予伤害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46647144,'星遗物－星枪－','此卡名的①③效果1回合仅可各使用1次。①：包括连接怪兽的怪兽之间进行战斗的伤害计算时，将此卡从手牌中舍弃可以发动。进行该战斗的对手怪兽的攻击力下降3000。②：只要此卡存在于怪兽区域，对手不可攻击其他的“星遗物”怪兽。③：怪兽从额外牌组被特殊召唤的情况下发动。将“星遗物衍生物”（机械族・暗・星1・攻/守0）各1只以守备表示特殊召唤至双方场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46647145,'星遗物衍生物','由“星遗物－星枪－”等的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46652477,'转生之预言','①：可以双方墓地的卡合计2张为对象发动。该卡放回持有者的牌组中。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46656406,'咒言之镜','对手从牌组特殊召唤怪兽时可发动。破坏该怪兽，我方从牌组抽取１张卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46657337,'姆卡姆卡','此卡的攻击力、守备力上升我方手牌张数×３００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46659709,'银河战士','此卡名的②效果1回合仅可使用1次。①：将手牌中此卡以外的1只光属性怪兽送至墓地可以发动。从手牌将此卡以守备表示特殊召唤。②：此卡特殊召唤成功时可以发动。从牌组将1只“银河”怪兽加入手牌。','特殊召唤','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46660187,'岩吼战士・重击',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：在自己・对手的主要阶段，自己场上表侧表示的“岩吼战士”怪兽因对手的效果离开场上的情况下可以发动。挑选对手场上的最多２张卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46668237,'森之番人 绿狒狒','①：此卡存在于手牌、墓地，并且我方场上表侧表示的兽族怪兽因效果被破坏并送入墓地时，支付１０００LP可以发动。特殊召唤此卡。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46696593,'红阳鸟','“神圣鸟”＋“天空猎手”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46700124,'机械王','场上每存在１只表侧表示的机械族怪兽，此卡的攻击力上升１００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46701379,'女战神・五女',replace(replace('此卡牌名的②效果１回合只可使用１次。\r\n①：我方场上的“女战神”怪兽的攻击力上升相当于被除外对手怪兽的数量×２００。\r\n②：我方场上存在有除“女战神・五女”以外的“女战神”怪兽的场合可发动。从牌组将１张魔法、陷阱卡送入墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46708514,'凝视苍穹的蠕龙',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：此卡存在于墓地的状态下，有怪兽因对手发动的怪兽效果从牌组或额外牌组被特殊召唤的情况下可以发动。将此卡特殊召唤。\r\n②：包含将怪兽特殊召唤的效果的怪兽效果发动时，从自己手牌・场上将1张卡除外可以发动。将该效果无效并破坏。\r\n③：此卡被除外的回合的结束阶段可以发动。将自己除外状态的1只其他的怪兽放回墓地。','\r',char(13)),'\n',char(10)),'特殊召唤','效果无效','回收除外','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46710683,'黑羽－银盾的密斯特拉尔','场上的此卡被破坏并送入墓地的场合，此回合我方受到的战斗伤害仅１次变成０。','这个回合自己受到的战斗伤害只有1次变成0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46718686,'海星葵','受污染水源侵蚀而狂暴化的海星，能从口中吐出溶解液。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46724542,'电子龙胜利者',replace(replace('包含“电子龙”在内的机械族怪兽2只\r\n此卡名的②效果1回合仅可使用1次。\r\n①：此卡只要存在于场上・墓地，卡名视为“电子龙”。\r\n②：在此卡未攻击宣言的自己・对手的战斗阶段，以自己场上的1只攻击力2100以上的机械族怪兽为对象可以发动。该怪兽的攻击力・守备力直至回合结束时为止上升2100。此效果发动后，直至回合结束时为止，因此卡战斗产生的双方的战斗伤害变为0。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46759931,'幻影－英雄 三位一体',replace(replace('“－英雄”怪兽×３\r\n①：此卡不可直接攻击。②：此卡融合召唤成功的回合，此卡的攻击力变为原本攻击力的两倍。③：融合召唤的此卡在１次战斗阶段中可攻击３次。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46772449,'励辉士 邪蚀西卜',replace(replace('等级4怪兽×2\r\n①：在自己的主要阶段及对手的战斗阶段，对手手牌・场上的卡的数量多于自己手牌・场上的卡的数量的情况下，去除此卡的1个超量素材可以发动（同一连锁上最多1次）。将场上的其他卡全部破坏。此效果发动后，直至回合结束时为止，对手受到的所有伤害变为0。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46789706,'机雷化的库里波',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡存在于手牌，且场上存在“库里波”怪兽卡的情况下可以发动。将此卡特殊召唤。\r\n②：对手发动场上的怪兽的效果时可以发动。将自己场上的此卡视为拥有以下效果的装备魔法卡装备于该对手怪兽。\r\n●装备怪兽的效果无效化。','\r',char(13)),'\n',char(10)),'特殊召唤','装备','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46796664,'DD 魔导贤者哥白尼',replace(replace('←1 【灵摆】 1→\r\n①：自己仅可灵摆召唤“DD”怪兽。此效果不会被无效化。\n②：只要此卡存在于灵摆区域，仅限1次，给予自己伤害的魔法卡的效果的处理时，可将该效果无效。然后将此卡破坏。\r\n【怪兽效果】\r\n此卡名的怪兽效果1回合仅可使用1次。\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将除“DD 魔导贤者哥白尼”以外的1张“DD”卡或“契约书”卡送至墓地。','\r',char(13)),'\n',char(10)),'送至墓地','是否适用「DD 魔导贤者哥白尼」的效果来无效？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46804536,'燃烧拳斗士 拳王登普西',replace(replace('等级４怪兽×２\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡特殊召唤的情况下可以发动。从牌组挑选１只等级４以下的战士族・炎属性怪兽或１张“燃烧拳击”魔法・陷阱卡，加入手牌或送至墓地。\r\n②：在自己・对手回合中可以发动。去除自己场上的１个超量素材，适用以下效果。\r\n●此回合中，对手不可将自己场上的“燃烧拳斗士”怪兽作为效果的对象。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46809548,'机巧牙－御神尊真神','此卡名的②③效果1回合仅可各使用1次。①：被除外的自己的卡为6张以上的情况下，此卡无需解放即可召唤。②：此卡召唤・特殊召唤成功的情况下，从手牌舍弃1只怪兽可以发动。从牌组将1只“机巧牙-御神尊真神”以外的、攻击力与守备力数值相同的怪兽加入手牌。③：怪兽区域的此卡被破坏的情况下可以发动。挑选6张被除外的自己的卡放回牌组。','不用解放作召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46815301,'游魊之双角 阿斯坎',replace(replace('协调＋协调以外的怪兽１只以上\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡同步召唤的情况下，以自己场上的１只鱼族怪兽和对手场上的１张卡为对象可以发动。将该卡除外。\r\n②：此卡被除外的情况下，从自己的墓地将１只鱼族怪兽除外可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46820049,'地狱将军・梅菲斯托','此卡攻击守备表示怪兽时，如果攻击力超出守备力，则给对方生命相当于该差值的战斗伤害。此外，此卡给予对手生命战斗伤害时，随机舍弃对手的１张手牌。','丢弃手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46821314,'人形软泥','具有人类形状的软泥。被内置了人类的基因。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46833854,'魔轰神托比','①：自己的手牌比对手少2张以上的情况下，向对手出示手牌的1只“魔轰神”怪兽，解放此卡，以对手场上的2张魔法・陷阱卡为对象可以发动。将该对手的卡破坏。','对手场上存在的2张魔法·陷阱卡破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46848859,'航空母舰机人','对手以我方场上的魔法、陷阱卡为对象发动持有”破坏场上的魔法、陷阱卡”效果的卡牌时，可舍弃１张手牌并发动。使该发动无效并破坏。','无效并破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46864967,'岩之战士','岩石战士，挥舞极为沉重的岩石剑。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46871387,'编号55 隆隆隆歌利亚',replace(replace('等级４怪兽×２\r\n此卡名的②效果１回合仅可使用１次。①：只要此卡存在于怪兽区域，自己场上怪兽的守备力上升８００。②：去除此卡的１个超量素材，以自己墓地１只岩石族・地属性・等级４怪兽为对象可以发动。将该岩石族・地属性怪兽加入手牌。','\r',char(13)),'\n',char(10)),'加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46874015,'六武众推参！','可选择我方墓地１只冠有“六武众”之名的怪兽并发动。从墓地特殊召唤被选择怪兽。以此效果特殊召唤的怪兽在此回合的结束阶段时被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46877100,'恐惧爪・高空阿克罗亚','此卡名以①方法的特殊召唤１回合仅可进行１次。①：此卡可从手牌特殊召唤至与自己场上“恐惧爪”怪兽相邻或同一纵列的、自己的主要怪兽区域。②：只要此卡存在于怪兽区域，额外怪兽区域的自己的“恐惧爪”怪兽的攻击力上升相当于自己场上守备表示怪兽数量×３００的数值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46895036,'鬼计・无头骑士',replace(replace('等级1怪兽×2\r\n①：此卡的攻击力上升自己场上的“鬼计”卡的数量×200的数值。\r\n②：在每个自己・对手回合中1次，去除此卡的1个超量素材，以场上的1只表侧表示怪兽为对象可以发动。将该怪兽的攻击力直至回合结束时为止改成一半。\r\n③：此卡被送至墓地的情况下，以自己墓地的1张其他的“鬼计”卡为对象可以发动。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'攻击降低','返回手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46897277,'电力狐狸','①：此卡因对手被破坏的情况下发动。此回合，对手不可发动魔法・陷阱・怪兽的效果，不可将怪兽特殊召唤。','对手发动限制','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46898368,'汹涌的燃烧抽牌',replace(replace('此卡名在规则上也视为“转生炎兽”卡。\r\n此卡名的卡１回合仅可发动１张，发动此卡的回合中，自己仅可召唤・特殊召唤炎属性怪兽。\r\n①：对手场上的卡数量多于自己场上的卡的情况下，以对手场上的１只连接怪兽为对象可以发动。自己依该怪兽连接标记的数量来抽牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46910446,'地狱联盟','装备怪兽的攻击力上升相当于场上存在的除装备怪兽以外的同名怪兽数量×８００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46918794,'火炎地狱','给予对手LP１０００点伤害，自己受到５００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46924949,'领地恐龙',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：只要此卡存在于主要怪兽区域，额外怪兽区域的怪兽的效果无效化。\r\n②：此卡因战斗被破坏时可以发动。从牌组将１只“领地恐龙”特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46925518,'鬼计的人偶','仅在自己场上有“鬼计”怪兽存在的情况下，此卡才可以表侧表示召唤。①：在自己的主要阶段可以发动。将此卡改成里侧守备表示（１回合仅１次）。②：此卡反转的情况下发动。在此回合的结束阶段，场上的表侧表示怪兽全部变为里侧守备表示。然后，可将１只等级为以此效果变为里侧守备表示的怪兽数量以下的“鬼计”怪兽，从牌组以里侧守备表示特殊召唤。','变成里侧表示','是否要把「鬼计」怪兽从牌组里侧守备表示特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46935289,'虚光之宣告者',replace(replace('衍生物以外的相同种族・属性的怪兽２只\r\n此卡名的①②效果１回合仅可各使用１次。①：魔法・陷阱卡效果发动时，从手牌将１只天使族怪兽送至墓地可以发动。将该发动无效并破坏。②：此卡被对手送至墓地的情况下可以发动。从自己墓地的仪式怪兽及仪式魔法卡中，挑选合计最多２张加入手牌（同名卡最多１张）。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46939151,'地缚囚人 大地看守者',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从自己的牌组・墓地将“地缚囚人 大地看守者”以外的１只等级５以下的“地缚”怪兽特殊召唤。此效果发动后，直至回合结束时为止，自己从额外牌组仅可特殊召唤融合・同步怪兽。\r\n②：只要场地区域存在卡，自己场上的“地缚”怪兽不会因战斗・效果被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46947713,'转码语者',replace(replace('效果怪兽2只以上\r\n此卡名的②效果1回合仅可使用1次。\r\n①：此卡在相互连接状态的情况下，此卡及此卡相互连接端怪兽的攻击力上升500，不会成为对手效果的对象。\r\n②：以除了“转码语者”以外的、自己墓地的1只连接3以下的电子界族连接怪兽为对象可以发动（发动此效果的回合中，自己仅可特殊召唤电子界族怪兽）。将该怪兽特殊召唤至此卡连接端的自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46955132,'梅尔菲・拉比好朋友',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：对手将怪兽召唤・特殊召唤的情况下可以发动。从手牌将此卡特殊召唤。然后，可将自己手牌・场上的怪兽作为融合素材，将1只“梅尔菲”融合怪兽融合召唤。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从牌组将1只“梅尔菲”怪兽加入手牌。以此效果将通常怪兽加入了手牌的情况下，进而可从手牌将任意数量的兽族怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','检索效果','是否融合召唤？','是否特殊召唤？','','','','','','','','','','','','');
INSERT INTO texts VALUES(46955770,'守墓的异端者','①：只要此卡存在于怪兽区域，且场上有“王家长眠之谷－死灵谷”存在，此卡便不会受到除此卡以外的效果的影响。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46956301,'白斗气砂滑',replace(replace('水属性协调＋协调以外的怪兽１只以上\r\n此卡名的①效果１回合仅可使用１次。\r\n①：此卡同步召唤的情况下可以发动。从自己的手牌・墓地将１只等级４以下的鱼族怪兽以守备表示特殊召唤。然后，可从自己的墓地将１只其同名怪兽特殊召唤。\r\n②：此卡因对手被破坏并被送至墓地的情况下，从自己的墓地将１只其他的水属性怪兽除外可以发动。将此卡视为协调特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','此卡特殊召唤','是否再把同名怪兽特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46961802,'交叉攻击','选择我方场上２只表侧攻击表示且攻击力相同的怪兽来发动此卡。该回合中，选择的１只怪兽可对对手玩家进行直接攻击。另１只怪兽则不可进行攻击。','','请选择可以直接攻击的怪兽','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46967601,'诅咒纸符','由于装备怪兽被破坏并被送往墓地导致此卡被破坏并被送往墓地时，给予装备怪兽的控制者被破坏并被送往墓地的装备怪兽的原本守备力数值的伤害。','LP伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46984349,'救魔的奇石',replace(replace('此卡牌名的卡牌１回合只可发动１张。\r\n①：可将我方场上１只表侧表示怪兽或我方墓地１只怪兽除外并发动此卡。此卡发动后，变成持有等级与被除外怪兽原本等级相同的通常怪兽（魔法师族・光・攻／守０），并特殊召唤至怪兽区。此卡也被视为陷阱卡。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46985799,'黑蔷薇龙／爆裂',replace(replace('此卡不可通常召唤，仅可通过“爆裂模式”的效果特殊召唤。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：向对手出示手牌的此卡可以发动。将此卡放回牌组，将场上的1只怪兽的攻击力改成0。\r\n②：此卡特殊召唤的情况下，或有怪兽被特殊召唤至对手场上的情况下可以发动。将场上的卡全部破坏。\r\n③：此卡被破坏的情况下可以发动。从自己墓地将1只“黑蔷薇龙”特殊召唤。','\r',char(13)),'\n',char(10)),'攻击力改变','破坏效果','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46986414,'黑魔导','作为魔法使，攻击力・守备力均为最高级别。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(46986415,'黑魔导','作为魔法使，攻击力・守备力均为最高级别。','','','','','','','','','','','','','','','','');
