INSERT INTO texts VALUES(74677431,'真红眼黑龙','拥有真红之眼的黑龙。愤怒的黑色火焰会将映入其眼中者尽数烧成灰烬。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74677432,'真红眼黑龙','拥有真红之眼的黑龙。愤怒的黑色火焰会将映入其眼中者尽数烧成灰烬。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74689476,'伟魔女巫 结晶之桑德里永',replace(replace('属性不同的魔法师族等级４怪兽×２\r\n此卡名的①②效果１回合仅可各使用１次。①：去除此卡的１个超量素材可以发动。从牌组将１只“伟魔”怪兽特殊召唤。此效果发动后，直至回合结束时为止，自己从额外牌组仅可特殊召唤“伟魔”怪兽。②：此卡被装备中的情况下，以对手场上的１只效果怪兽为对象可以发动。将该怪兽的效果直至回合结束时为止无效。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74694807,'再融合','①：可支付８００LP，以我方墓地的１只融合怪兽为对象发动此卡。特殊召唤该怪兽并装备在此卡。此卡被破坏时该怪兽被除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74701381,'DNA改造手术','可以宣言１种种族并发动。只要此卡存在于场上，场上的所有表侧表示怪兽变成宣言的种族。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74703140,'裁决之鹰','“苍翼羽冠”＋“喔喔”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74711057,'元素－英雄 地球',replace(replace('“元素-英雄 海洋人”＋“元素-英雄 森林人”\r\n此卡仅可以融合召唤方式特殊召唤。①：解放自己场上此卡以外的1只表侧表示的“元素-英雄”怪兽可以发动。此卡的攻击力直至回合结束时为止，上升相当于解放的怪兽的攻击力的数值。','\r',char(13)),'\n',char(10)),'攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74713516,'暗黑的模拟箱 LV1','反转：从牌组抽取１张卡牌。此外，我方回合的准备阶段时，可通过将表侧表示的此卡送入墓地，从手牌或牌组中特殊召唤１只“暗黑的模拟箱 LV3”。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74715061,'条带化伙伴犬',replace(replace('此卡不可通常召唤，仅可以此卡的①效果特殊召唤。\r\n此卡牌名的②效果１回合只可使用１次。\r\n①：在我方场上发动之怪兽的效果变成无效的场合，可发动。从手牌特殊召唤此卡。\r\n②：此卡特殊召唤成功时，可以我方墓地１只等级４或以下的电子界族怪兽为对象发动。特殊召唤该怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74717840,'地龟的光藓','我方场上冠有“大植然”之名的怪兽存在的场合可发动。此回合，对手的怪兽不可发动效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74725513,'荷鲁斯的加护－克贝克塞努弗',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次，且②效果1回合仅可使用1次。\r\n①：自己场上存在“王之棺”的情况下，此卡可从墓地特殊召唤。\r\n②：此卡存在于怪兽区域的状态下，自己场上的其他卡因对手的效果从场上离开的情况下可以发动。此回合，对手怪兽不可将“荷鲁斯”怪兽作为攻击对象，对手不可将场上的“荷鲁斯”怪兽作为效果的对象。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74728028,'超量招待会','可选择我方场上１只表侧表示的怪兽来发动此卡。从手牌特殊召唤１只与所选择怪兽相同等级的怪兽。以此效果特殊召唤的怪兽的效果无效，攻击力和守备力变为０。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74730899,'燃料电池人','我方场上存在有２只或以上冠有“电池人”之名的怪兽的场合，此卡可从手牌特殊召唤。１回合１次，可释放我方场上１只除此卡以外冠有“电池人”之名的怪兽并发动。选择对手场上的１张卡牌并返回至持有者手牌。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74733322,'神艺学都',replace(replace('①：自己除通常召唤外仅可追加1次，在自己的主要阶段召唤1只“无垢者 墨迪乌斯”。\r\n②：从手牌舍弃1张魔法・陷阱卡，宣言同名怪兽不存在于自己场上的1个“神艺”怪兽的卡名可以发动（此回合，不可为发动此卡名的此效果而宣言相同卡名）。从牌组将1只宣言的怪兽加入手牌。此回合，自己仅可特殊召唤“神艺”怪兽及“无垢者 墨迪乌斯”（除了从额外牌组的特殊召唤以外）。','\r',char(13)),'\n',char(10)),'使用「神艺学都」的效果召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74741494,'能力调整','直至回合结束时，我方场上的所有怪兽等级下降１级。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74752631,'六武众之军大将',replace(replace('包含“六武众”怪兽在内的战士族怪兽２只\r\n此卡名的①效果１回合仅可使用１次。\r\n①：此卡连接召唤的情况下，舍弃１张手牌可以发动。从牌组将１张拥有放武士道计数物的效果的卡加入手牌。\r\n②：只要此卡存在于怪兽区域，每当有“六武众”怪兽被召唤・特殊召唤至此卡的连接端，就在此卡上放１个武士道计数物。\r\n③：此卡的攻击力上升相当于自己场上的武士道计数物的数量×１００的数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74762582,'地中骇界的妖魔',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：对手发动魔法・陷阱・怪兽的效果时，将手牌・场上的此卡送至墓地，以自己场上的1只“地中骇界”怪兽为对象可以发动。将该发动无效。然后，将对象怪兽改成里侧守备表示。\r\n②：以自己场上的1只表侧表示怪兽为对象可以发动。将该怪兽改成里侧守备表示，从自己手牌・墓地将1只“地中骇界”怪兽以表侧守备表示或里侧守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'发动无效','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74798297,'不知火流 才华之阵',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：从手牌将１只不死族怪兽特殊召唤。以此效果特殊召唤的怪兽从场上离开的情况下，将其除外。\r\n②：将墓地的此卡除外，以自己场上的１只不死族怪兽为对象可以发动。此回合，该不死族怪兽不受自身以外的卡的效果影响。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74820316,'宵星之自鸣天琴・机界骑士 恩基苏',replace(replace('包含“自鸣天琴”连接怪兽在内的怪兽2只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：以自己除外状态的1张“自鸣天琴”卡或“星遗物”卡为对象可以发动。将该卡加入手牌。然后，可挑选自己的1张手牌放回牌组并获得对手场上的1只表侧表示怪兽的控制权。\r\n②：在此卡从额外怪兽区域被送至墓地的回合的自己的主要阶段，将此卡除外可以发动。将场上的1张卡送至墓地。','\r',char(13)),'\n',char(10)),'回收&得到控制权','送墓','是否要得到对手怪兽的控制权？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74822425,'神影依・舍金那迦',replace(replace('“影依”怪兽＋地属性怪兽\r\n此卡从额外牌组仅可通过融合召唤来特殊召唤。\r\n此卡名的①效果1回合仅可使用1次。\r\n①：被特殊召唤的怪兽的效果发动时可以发动。将该发动无效并破坏。然后，从自己手牌挑选1张“影依”卡送至墓地。\r\n②：此卡被送至墓地的情况下，以自己墓地的1张“影依”魔法・陷阱卡为对象可以发动。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'无效并破坏','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74823665,'狱火','这张卡不可进行通常召唤。将1只炎属性怪兽从自己墓地除外的情况下可进行特殊召唤。①：这张卡通过战斗破坏对手怪兽并将其送至墓地的情况下发动。给对手1500伤害。','1500伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74825788,'H－炽热之心','①：以自己场上的1只表侧表示怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止上升500，此回合，该怪兽攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74839123,'魔玩具・圣域',replace(replace('可舍弃１张手牌，从我方额外牌组将２只“魔玩具”怪兽送入墓地并发动此卡。\r\n①：只要此卡存在于魔法与陷阱区域，所有我方场上的融合怪兽也被视为“魔玩具”怪兽。\r\n②：此卡被送入墓地的场合，可以我方墓地的１只“魔玩具”融合怪兽为对象发动。将该怪兽返回至额外牌组。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74841885,'天魔神 因维希尔',replace(replace('此卡不可特殊召唤。根据以此卡的上级召唤为目的而解放的怪兽的种族与属性，此卡获得以下效果。\r\n●天使族、光属性：只要此卡以表侧表示存在于场上，使场上魔法卡的效果无效。\r\n●恶魔族、暗属性：只要此卡以表侧表示存在于场上，使场上陷阱卡的效果无效。','\r',char(13)),'\n',char(10)),'魔法卡的效果无效','陷阱卡的效果无效','魔法和陷阱卡的效果无效','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74845897,'真炎的爆发','从我方的墓地尽可能地特殊召唤守备力２００的炎属性怪兽。以此效果特殊召唤的怪兽会在该回合的结束阶段时从游戏中除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74848038,'死者转生','①：扔掉1张手牌，可以自己墓地的1只怪兽为对象发动。将该怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74850403,'星霜的灵摆读阵','此卡名的②效果１回合仅可使用１次。①：只要此卡存在于魔法与陷阱区域，对手不可将自己场上的魔法师族怪兽作为魔法卡效果的对象。②：自己的怪兽区域・灵摆区域的表侧表示“魔术师”灵摆怪兽卡从场上离开的情况下发动。从牌组将１只“魔术师”灵摆怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74852097,'幻之狮鹫','隐于山岳之间的传说级怪兽。据说其羽翼轻拍便能掀起风暴。貌似与神鹰关系恶劣，经常为争抢狩猎领地而争斗。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74852810,'叠放捕获','可选择对手场上１只持有超量素材的超量怪兽和我方场上的１只超量怪兽并发动。移除被选择对手怪兽的所有超量素材，并重叠至选择此卡的我方怪兽下方当作超量素材。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74854609,'虫装转换','我方场上冠有“甲虫装机”之名的怪兽被选择为攻击对象时，可选择１只攻击怪兽并发动。将攻击对象怪兽视为装备卡装备被选择的攻击怪兽。只要冠有“甲虫装机”之名的怪兽因此效果被装备，我方取得该装备怪兽的控制权。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74860293,'废品破坏神',replace(replace('“废品同步士”＋1只以上协调以外的怪兽\r\n①：此卡同步召唤成功时，以场上的卡为对象可以发动，数量最多为作为该同步素材的怪兽中协调以外的怪兽数量。将该卡破坏。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74875003,'拉之使徒','①：此卡召唤・反转召唤・特殊召唤成功时可以发动。从手牌・牌组特殊召唤最多2只“拉之使徒”。②：只要此卡存在于怪兽区域，自己仅可用“拉之使徒”的效果特殊召唤怪兽，此卡除为了上级召唤“欧西里斯之天空龙”、“欧贝利斯克之巨神兵”、“拉之翼神龙”以外不可解放。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74879881,'拟态千岛短尾猫',replace(replace('此卡牌名的效果１回合只可使用１次。\r\n①：在我方主要阶段可发动。翻阅我方牌组最上方的卡牌，若是怪兽的场合，特殊召唤该怪兽，并将此卡返回至持有者牌组的最下方。不是的场合，或不可特殊召唤的场合，将该卡返回至牌组的最下方。以此效果特殊召唤之怪兽，在结束阶段返回至持有者牌组的最下方。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74889525,'征服王・黄金狂埃尔德里奇',replace(replace('“埃尔德里奇”怪兽＋等级５以上的不死族怪兽\r\n此卡名的③效果１回合仅可使用１次。①：只要此卡存在于怪兽区域，卡名视为“黄金卿埃尔德里奇”。②：场上的此卡不会因战斗・效果被破坏。③：解放自己场上的１只不死族怪兽，以对手场上的１只表侧表示怪兽为对象可以发动。获得该怪兽的控制权。该怪兽直至回合结束时为止，不可攻击，不可发动效果。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74891384,'魔救奇石－猛禽石','此卡名的①②效果1回合仅可各使用1次。①：此卡用“魔救”卡的效果特殊召唤成功的情况下可以发动。从自己的手牌・墓地挑选1只岩石族怪兽放回牌组最上面。②：此卡存在于墓地的情况下，可以自己场上・墓地的1只风属性同步怪兽为对象发动。该怪兽放回持有者的额外牌组，此卡放回牌组最上面。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74892653,'星尘战士',replace(replace('同步怪兽的协调＋协调以外的同步怪兽1只以上\r\n①：对手特殊召唤怪兽之际，解放此卡可以发动。将其无效，将该怪兽破坏。\r\n②：适用此卡的①效果的回合的结束阶段可以发动。将为发动该效果解放的此卡从墓地特殊召唤。\r\n③：表侧表示的此卡因战斗或对手的效果从场上离开的情况下可以发动。从额外牌组将1只等级8以下的“战士”同步怪兽视为同步召唤特殊召唤。','\r',char(13)),'\n',char(10)),'无效特殊召唤','苏生','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74906081,'睥睨统摄之蛇眼',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：自己场上的“蛇眼”怪兽的合计等级为２以上的情况下，可从以下效果中选择１个发动。\r\n●以对手场上（表侧表示）・墓地的１只怪兽为对象可以发动。将该怪兽视为永续魔法卡，以表侧表示放在原本持有者的魔法与陷阱区域。\r\n●以自己・对手场上１张视为永续魔法卡的怪兽卡为对象可以发动。将该卡特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'','放置怪兽','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74920585,'泪冠哀歌・奏鸣的摧花悲唱','此卡名的①②效果１回合仅可各使用１次。①：自己场上存在“泪冠哀歌”怪兽或“维萨思・史塔弗罗斯特”的情况下，以对手场上的１只效果怪兽为对象可以发动。将该怪兽的效果无效。然后，挑选自己场上的１只怪兽送至墓地。②：此卡因效果被送至墓地的情况下可以发动。从牌组将１只“泪冠哀歌”怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74923978,'强制接收','自己的手牌被舍弃时可以发动此卡。只要场上存在有此卡，每次自己舍弃手牌时，对手挑选相同数量的手牌舍弃。','手牌丢弃','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74926274,'灵摆显现',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：将自己场上的１只怪兽送至墓地可以发动。从牌组将等级与该怪兽原本等级相同的１只灵摆怪兽特殊召唤。以此效果特殊召唤的怪兽将在结束阶段被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74936480,'恐啡肽骇龙・隐形翼龙',replace(replace('卡名不同的“恐啡肽骇龙”怪兽×２\r\n此卡名的②③效果１回合仅可各使用１次。①：只要自己的LP为２０００以下，自己不需为发动“恐啡肽骇龙”怪兽的效果及陷阱卡而支付LP。②：对手发动怪兽的效果时可以发动。给予对手该怪兽的原本攻击力数值的伤害。③：此卡因战斗・效果被破坏的情况下可以发动。从自己的墓地挑选１只等级４以下的“恐啡肽骇龙”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74937659,'地中骇界邪龙之妖魔',replace(replace('反转怪兽2只\r\n此卡名的②效果1回合仅可使用1次。\r\n①：此卡的攻击力上升作为此卡连接素材的“地中骇界”怪兽的原本等级合计×100的数值。\r\n②：在自己的主要阶段可以发动。从牌组将1只反转怪兽送至墓地，从手牌将1只怪兽以里侧守备表示特殊召唤至此卡的连接端。\r\n③：1回合1次，此卡连接端的怪兽反转的情况下发动。从自己牌组・墓地将1只反转怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74941992,'月之魔术师',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次，且②效果1回合仅可使用1次。\r\n①：对手场上存在超量怪兽的情况下，可从手牌将此卡特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下，以“月之魔术师”以外的、自己墓地的1只光属性・等级4怪兽为对象可以发动。将该怪兽特殊召唤。以此效果特殊召唤的怪兽的效果无效化。','\r',char(13)),'\n',char(10)),'','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74952447,'曾被称为神的龟','①：只要此卡存在于怪兽区域，双方不可特殊召唤攻击力１８００以上的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74968065,'赫卡泰莉丝','①：可在我方主要阶段将此卡从手牌舍弃至墓地并发动。从牌组将１张“神之居城－瓦尔哈拉”加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74974229,'外星人士兵 强力／外骨骼',replace(replace('爬虫类族怪兽２只\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：在自己・对手回合中，从手牌将１只怪兽舍弃可以发动。依所舍弃怪兽的原本等级数，在场上的表侧表示怪兽上放A计数物。\r\n②：此卡因战斗・效果被破坏并被送至墓地的情况下可以发动。从自己的墓地将连接怪兽以外的爬虫类族怪兽特殊召唤（同名卡最多１张），数量最多为对手场上放有A计数物的怪兽的数量。','\r',char(13)),'\n',char(10)),'','','请选择要放置计数物的怪兽','是否继续选择？','','','','','','','','','','','','');
INSERT INTO texts VALUES(74976215,'十字剑猎手','我方场上存在有其他昆虫族怪兽的场合，我方场上的昆虫族怪兽攻击了守备表示怪兽时，若其攻击力超过守备力，给予对手生命相当于该差值的战斗伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74983881,'小玉米','１回合１次，在自己的主要阶段２时支付５００LP可以发动。特殊召唤１只“玉米粒衍生物”（植物族・地・星１・攻／守０）至自己场上。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74983882,'玉米粒衍生物','由“小玉米”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(74997493,'锁龙蛇－骷髅四尸',replace(replace('卡名不同的怪兽2只以上\r\n①：根据作为此卡的连接素材的怪兽数量，此卡获得以下效果。\r\n●2只以上：怪兽被召唤・特殊召唤至此卡连接端的情况下发动。该怪兽的攻击力・守备力上升300。\r\n●3只以上：1回合1次，在自己的主要阶段可以发动。从手牌将1只怪兽特殊召唤。\r\n●4只：此卡连接召唤成功时可以发动。自己从牌组抽4张，然后挑选3张手牌以喜欢的顺序放回牌组下面。','\r',char(13)),'\n',char(10)),'攻击力·守备力上升','从手牌把1只怪兽特殊召唤','抽滤','2只以上怪兽为素材','3只以上怪兽为素材','','','','','','','','','','','');
INSERT INTO texts VALUES(75003700,'星宿枪手 卢奇亚斯',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将“星宿枪手 卢奇亚斯”以外的1只“星宿”怪兽加入手牌。\r\n②：此卡作为融合召唤的素材被送至墓地的情况下可以发动。从牌组将1张“星宿”魔法・陷阱卡放置在自己场上。','\r',char(13)),'\n',char(10)),'检索效果','放置魔陷','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75014062,'魔力掌握',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：以场上的1张能放魔力计数物的卡为对象可以发动。在该卡上放1个魔力计数物。然后，可从牌组将1张“魔力掌握”加入手牌。','\r',char(13)),'\n',char(10)),'是否要把1张「魔力掌握」加入手牌？','请选择要放置「魔力计数物」的卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75025112,'魍魉跋扈','①：在自己或对手的主要阶段可以发动。通常召唤1只怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75041269,'幽狱时钟塔','①：对手的准备阶段发动。在此卡上放1个时钟计数物。②：此卡的时钟计数物为4个以上的情况下，自己受到的战斗伤害变为0。③：放有4个以上时钟计数物的此卡被破坏并被送至墓地的情况下发动。从手牌・牌组将1只“命运-英雄 恐惧魔侠”特殊召唤。','放置计数物','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75043725,'冥界使者','当此卡从场上被送入墓地时，双方各自从自己牌组中选择１只等级３以下的通常怪兽，相互确认后加入到手牌中。之后对牌组进行洗牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75046994,'能－朋.克.跃鳞',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：从自己手牌・墓地将此卡以外的1张“朋.克.”卡除外可以发动。从手牌将此卡特殊召唤。\r\n②：此卡特殊召唤的情况下，支付600LP可以发动。从自己牌组・墓地挑选等级8怪兽以外的1只“朋.克.”怪兽，加入手牌或特殊召唤。\r\n③：对手场上攻击力2500以上的怪兽发动效果时可以发动。将该怪兽改成里侧守备表示。','\r',char(13)),'\n',char(10)),'此卡特殊召唤','加入手牌或者特殊召唤','改变表示形式','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75047173,'至爱接触',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从自己手牌・场上・墓地・除外状态，将由融合怪兽决定的融合素材怪兽以喜欢的顺序放回牌组下面，从额外牌组将该1只需以“－英雄”怪兽作为融合素材的融合怪兽无视召唤条件特殊召唤。以此效果将“元素－英雄 新宇侠”放回了牌组的情况下，双方不可将以此效果特殊召唤的怪兽放回额外牌组。','\r',char(13)),'\n',char(10)),'','「至爱接触」效果适用中','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75059201,'方程式运动员 涡轮增压机战车','①：此卡的攻击力上升相当于此卡等级×300的数值，原本的等级或阶级低于此卡等级的对手怪兽仅可以此卡作为攻击对象，仅可以此卡作为效果的对象。②：“方程式运动员”魔法・陷阱卡的效果发动的情况下可以发动（伤害步骤也可以发动）。此卡的等级上升1。③：此卡等级为7以上、自己的“方程式运动员”怪兽进行战斗的情况下，直至伤害步骤结束时为止，对手不可发动怪兽的效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75064463,'神鹰女王','①：此卡只要存在于场上・墓地，卡名视为“神鹰女郎”。②：从手牌将此卡舍弃至墓地可以发动。从牌组将１张“神鹰狩猎场”加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75078585,'破蛋','①：自己场上的怪兽因战斗・效果被破坏并被送至墓地的情况下可以发动。从自己手牌・牌组・墓地将1只“小走鹃”特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75081613,'巨型异虫',replace(replace('此卡不可通常召唤。\r\n仅可在从自己的墓地将１只昆虫族怪兽除外的情况下特殊召唤。\r\n①：此卡给予对手战斗伤害的情况下发动。将对手的牌组最上面的卡送至墓地。','\r',char(13)),'\n',char(10)),'牌组送墓','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75083197,'告天子龙 百灵',replace(replace('等级６怪兽×２\r\n此卡名的②效果１回合仅可使用１次。①：只要“告天子龙 百灵”以外的、从墓地被特殊召唤的怪兽在场上以表侧表示存在，此卡不会因战斗・效果被破坏。②：在自己・对手的准备阶段，去除此卡的１个超量素材，以自己墓地的１只等级５以下怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75105429,'同步驱逐','选择对手场上的１只同步怪兽并从游戏中除外，对手从牌组抽取１张卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75109441,'半蛇人萨库兹','此卡仅限１回合１次可变成里侧守备表示。此卡反转时，确认盖牌在对手场上的全部魔法、陷阱卡。','变成里侧守备','确认盖卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75116619,'真六武众－缘',replace(replace('①：在每个自己・对手回合中１次，从自己墓地将２只“六武众”怪兽除外，以场上的１只表侧表示怪兽为对象可以发动（此效果在自己场上存在“真六武众－缘”以外的“六武众”怪兽的情况下才能发动和处理）。将该表侧表示怪兽放回手牌。\r\n②：自己场上存在“真六武众－缘”以外的２只以上“六武众”怪兽的情况下，此卡的攻击力・守备力上升５００。','\r',char(13)),'\n',char(10)),'返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75119040,'廷达三角・锐角地狱犬',replace(replace('“廷达三角”怪兽３只\r\n①：自己墓地存在包含“廷达三角・底边守卫者”在内的３种以上的“廷达三角”怪兽的情况下，此卡的攻击力上升３０００。\r\n②：此卡的攻击力上升相当于此卡连接端的“廷达三角”怪兽数量×５００的数值。\r\n③：此卡攻击宣言的战斗阶段结束时可以发动。将１只“廷达三角衍生物”（恶魔族・暗・星１・攻／守０）特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75119041,'廷达三角衍生物','由「廷达三角・锐角地狱犬」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75130221,'码冷却者','此卡名的①②效果1回合仅可各使用1次。①：在要将自己场上的电子界族怪兽作为“码语者”怪兽的连接素材的情况下，手牌的此卡也可一起作为连接素材。②：此卡作为“码语者”怪兽的连接素材从手牌・场上被送至墓地的情况下，以对手场上的1只表侧表示怪兽为对象可以发动。该怪兽攻击力变为0，效果无效化。将场上的此卡作为素材的情况下，可将此效果的对象改为2只。','','从场上送至墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75132317,'雄炎星－蛇冲',replace(replace('①：自己场上不存在其他怪兽的情况下，１回合１次，将自己场上的２张表侧表示的“炎舞”魔法・陷阱卡送至墓地可以发动。自己抽１张。\r\n②：１回合１次，“炎舞”魔法・陷阱卡被送至自己墓地的情况下可以发动。从牌组将１张“炎舞”陷阱卡放置在自己场上。','\r',char(13)),'\n',char(10)),'放置','抽牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75141056,'英雄假面','①：可以我方场上表侧表示的１只怪兽为对象发动。从牌组将１只“元素－英雄”怪兽送入墓地，直至结束阶段，作为对象的我方表侧表示怪兽被视作以此效果送入墓地的同名卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75147529,'闪刀姬－泽克',replace(replace('包含“闪刀姬”怪兽在内的怪兽２只\r\n此卡仅可以连接召唤方式特殊召唤，自己１回合仅可特殊召唤１次“闪刀姬－泽克”。\r\n①：此卡连接召唤的情况下，以场上的１只表侧表示怪兽为对象可以发动。将该怪兽直至下个对手的结束阶段为止除外。\r\n②：１回合１次，以自己场上的１张其他卡为对象可以发动。此卡的攻击力上升１０００。然后，将对象卡送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75153328,'强制切断',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：以连接怪兽以外的自己场上的１只表侧表示怪兽和对手场上的１只连接怪兽为对象可以发动。该２只怪兽的控制权交换。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75157704,'双天之使命',replace(replace('此卡名的卡在1个回合中仅可发动1张。\r\n①：在自己或对手的主要阶段，除外1张“双天之使命”以外的自己墓地的“双天”魔法・陷阱卡后可以发动。此卡的效果与该魔法・陷阱卡发动时的效果相同。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75162696,'维多利亚','１回合１次，可选择对手墓地中的１只龙族怪兽并特殊召唤至我方场上！只要此卡面朝上在场上，对手就不能选择除此卡以外的天使族怪兽作为攻击目标。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75180828,'水精鳞－蓝鲸深渊','可从手牌将４只冠有“水精鳞”之名的怪兽舍弃至墓地并发动。从手牌特殊召唤此卡。以此效果特殊召唤时，此卡的攻击力上升５００点，并选择对手场上的卡牌破坏，其数量上限为我方墓地冠有“水精鳞”之名的怪兽数量。此外，可释放除此卡以外的我方场上的１只冠有“水精鳞”之名的攻击表示怪兽。此回合的此卡攻击守备表示怪兽的伤害步骤开始时，破坏该怪兽。','特殊召唤','破坏','效果附加','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75190122,'黑・爆・裂・破・魔・导','①：原本卡牌名是“黑魔导”和“黑魔导女孩”的怪兽各自存在于我方场上的场合可发动。破坏对手场上的所有卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75191028,'GMX－混霸种COMPREX',replace(replace('“GMX”怪兽＋恐龙族怪兽2只以上\r\n①：此卡根据作为此卡融合素材的恐龙族怪兽的数量，获得以下效果。\r\n●3只以上：对手不可将此卡作为效果的对象。\r\n●4只以上：此卡在1次战斗阶段中可攻击3次。\r\n●5只以上：每当对手将怪兽召唤・特殊召唤，对手就失去800LP。\r\n②：1回合1次，自己因“GMX”卡的效果将牌组的卡翻开的情况下可以发动。将场上其他的怪兽全部破坏。','\r',char(13)),'\n',char(10)),'','破坏','3只以上恐龙族怪兽作为融合素材','4只以上恐龙族怪兽作为融合素材','5只以上恐龙族怪兽作为融合素材','','','','','','','','','','','');
INSERT INTO texts VALUES(75195825,'龙剑士 至尊行者 灵摆',replace(replace('←3 【灵摆】 3→\r\n①：只要此卡存在于灵摆区域，仅限１次，以自己或对手的灵摆区域的１张卡为对象可以发动。将该卡破坏。\r\n【怪兽效果】\r\n获得同志们的力量成长后的“龙剑士 光栅行者 灵摆”的姿态。因被施以谜之诅咒，显现出了与龙魔族相似的龙之力量，却丧失了此前的所有记忆，以致无人知晓个中真相。他相信“龙化之秘法”是解除该诅咒和取回记忆的关键，至今仍在继续着讨伐恶之魔王的旅程。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75198893,'扫描机','选择从游戏中除外的１只对手怪兽并发动。此卡直到结束阶段时被视为和被选择怪兽的同名卡，属性、等级、攻击力、守备力变成和被选择怪兽相同。此效果１回合只可使用１次。适用了此效果的此卡从场上离开的场合，从游戏中除外。','卡名变换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75209824,'守护者石像','此卡在１个回合中可有１次机会变为里侧守备表示。成功反转召唤此卡时，令对手场上的１只怪兽回到持有者的手牌中。','变成里侧守备','返回手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75214390,'叠放推进者',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次。\r\n①：自己场上存在攻击力2000以上的怪兽的情况下，此卡可从手牌以守备表示特殊召唤。\r\n②：从墓地将不是在此回合被送至墓地的此卡除外，以自己场上的1只持有超量素材的超量怪兽为对象可以发动。该怪兽的攻击力上升自身的超量素材数量×500的数值。','\r',char(13)),'\n',char(10)),'攻击变换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75215744,'弩级军贯－鲑鱼子型一号舰',replace(replace('等级４怪兽×２\r\n此卡名的①效果１回合仅可使用１次。①：此卡超量召唤成功的情况下可以发动。根据作为该超量召唤的素材的怪兽，适用以下效果。\r\n●“舍利军贯”：自己从牌组抽１张。\r\n●“鲑鱼子军贯”：此卡在１次战斗阶段中可攻击２次。\r\n②：１回合１次，从额外牌组被特殊召唤的自己的“军贯”怪兽给予对手战斗伤害时，以对手场上的１张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75220074,'铠龙－武装龙－','①：此卡战斗破坏对手怪兽时可以发动。从手牌・牌组将除“铠龙－武装龙－”以外的1只等级5以下的龙族・风属性怪兽特殊召唤。以此效果特殊召唤的怪兽此回合不可直接攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75223115,'Sin 领域',replace(replace('①：作为此卡发动时的效果处理，可从牌组发动1张“Sin 世界”。只要以此效果发动的卡存在于场地区域，双方不可将场地区域的卡作为效果的对象。\r\n②：“Sin”怪兽拥有的、““Sin”怪兽在场上仅可有1只以表侧表示存在”的效果，改为““Sin”怪兽每1种在场上仅可有1只以表侧表示存在”并适用。\r\n③：仅在战斗阶段期间，场上的“Sin”怪兽的效果无效化。','\r',char(13)),'\n',char(10)),'是否发动场地？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75249652,'业炎防护罩 －火焰之力－','①：对手怪兽攻击宣言时可以发动。将对手场上的攻击表示怪兽全部破坏，自己受到相当于以此效果所破坏的怪兽的原本攻击力的合计数值的一半的伤害。然后，给予对手相当于自己所受到的伤害相同数值的伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75252099,'蔷薇鸟','我方场上攻击表示的此卡因对手怪兽的攻击被破坏并送入墓地时，可从牌组以守备表示特殊召唤２只植物族协调。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75253697,'编号72 行列怪兽 战车・飞车',replace(replace('等级６怪兽×２\r\n①：１回合１次，去除此卡的２个超量素材，以对手场上的１只表侧表示怪兽和对手场上被放置的１张魔法・陷阱卡为对象可以发动。将该卡破坏。此效果发动后，直至回合结束时为止，对手将受到的战斗伤害变为一半。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75285069,'水蒸气星人','此卡可以解放３只怪兽并召唤。以此方法召唤成功时，破坏对手场上存在的所有魔法・陷阱卡。','解放3只怪兽召唤','魔陷破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75286621,'召唤兽 梅尔卡巴',replace(replace('“召唤师 阿莱斯特”＋光属性怪兽\r\n①：1回合1次，怪兽的效果・魔法・陷阱卡发动时，从手牌将1张种类（怪兽・魔法・陷阱）与该效果相同的卡送至墓地可以发动。将该发动无效并除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75286622,'召唤兽 梅尔卡巴',replace(replace('“召唤师 阿莱斯特”＋光属性怪兽\r\n①：1回合1次，怪兽的效果・魔法・陷阱卡发动时，从手牌将1张种类（怪兽・魔法・陷阱）与该效果相同的卡送至墓地可以发动。将该发动无效并除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75290703,'兽带斗士・异雷古拉','此卡名的①②③效果１回合仅可各使用１次。①：以自己墓地的最多３只“兽带斗士”怪兽为对象可以发动。从手牌将此卡特殊召唤，将对象怪兽视为装备卡装备于此卡。②：从手牌将１张“无尽机关 阿尔银洛系统”舍弃可以发动。将对手场上的卡全部破坏。③：此卡被装备中的情况下可以发动。将此卡特殊召唤。然后，将原先装备着此卡的怪兽视为装备卡装备于此卡。','','对手场上的卡全部破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75292259,'海神大兜虫','此卡攻击对手的表侧攻击表示怪兽，且该怪兽未因该战斗被破坏的场合，可连续攻击相同怪兽。此效果１回合最多可使用２次。','是否要继续攻击？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75294187,'狂惑落穴',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：对手特殊召唤过怪兽的回合，以对手场上１只攻击力２０００以上的怪兽为对象可以发动。将该怪兽破坏。然后，自己墓地存在“空洞”通常陷阱卡或“落穴”通常陷阱卡的情况下，可从对手墓地将１只怪兽除外。','\r',char(13)),'\n',char(10)),'是否从对手墓地选1只怪兽除外？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75304793,'扩音器热焰',replace(replace('①：此卡只要存在于场地区域，每次“音响战士”卡拥有的效果发动，在此卡上放１个音响计数物。②：场上的“音响战士”怪兽的攻击力上升相当于此卡音响计数物数量×１００的数值。③：１回合１次，依以下数量去除自己场上的音响计数物，可以发动相应效果。\r\n●５个：给予对手相当于场上“音响战士”卡数量×３００的数值的伤害。\r\n●７个：挑选对手场上・墓地的卡除外，数量最多为场上“音响战士”卡的数量。','\r',char(13)),'\n',char(10)),'5个：给与对手伤害','７个：对手的卡除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75311421,'布提斯',replace(replace('①：此卡召唤成功时可以发动。自己从牌组上面翻开３张卡。其中有怪兽的情况下，可通过将其中１只除外，从牌组及翻开的卡中将１只其同名怪兽加入手牌。将剩余的卡放回牌组。\r\n②：通常召唤的此卡被送至墓地的回合的结束阶段可以发动。从自己的牌组上面翻开３张卡，以喜欢的顺序放回牌组上面。','\r',char(13)),'\n',char(10)),'是否除外并检索同名卡？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75326861,'天刑王 黑穹降临者',replace(replace('恶魔族协调＋协调以外的恶魔族怪兽1只以上\r\n①：只要此卡存在于怪兽区域，双方不可同步召唤。\r\n②：1回合1次，以装备有装备卡的对手场上的1只怪兽为对象可以发动。将该怪兽装备的装备卡全部破坏，给予对手所破坏数量×400的伤害。','\r',char(13)),'\n',char(10)),'装备卡破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75347539,'磁石之战士 翔武机翁',replace(replace('此卡不可通常召唤。\r\n解放自己手牌・场上的“磁石战士阿尔法”“磁石战士贝塔”“磁石战士伽玛”各1只的情况下可以特殊召唤。\r\n①：解放此卡，以自己墓地的“磁石战士阿尔法”“磁石战士贝塔”“磁石战士伽玛”各1只为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75352507,'蕾祸之玄神凭月',replace(replace('昆虫族・植物族・爬虫类族怪兽２只以上\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：从自己的墓地将最多２只怪兽除外，依其数量以对手场上的魔法・陷阱卡为对象可以发动。将该卡破坏。\r\n②：此卡存在于墓地的情况下，以自己场上的１只昆虫族・植物族・爬虫类族怪兽为对象可以发动。将该怪兽放回牌组最下面，将此卡特殊召唤。此回合，自己仅可特殊召唤昆虫族・植物族・爬虫类族怪兽。','\r',char(13)),'\n',char(10)),'魔陷破坏','墓地特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75356564,'小龙','非常小的龙。会用自己小小的身体全力发动攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75361204,'灰篮分裂',replace(replace('“灰篮分裂”的②效果１回合只可使用１次。\r\n①：可以我方场上的１只怪兽为对象发动此卡。此卡被视为攻击力上升５００的装备卡装备该怪兽。\r\n②：在我方主要阶段，可将因此卡效果被装备的此卡送入墓地并发动。破坏装备此卡的怪兽，并从牌组特殊召唤２只“灰篮”怪兽（同名卡最多１张）。以此效果特殊召唤的怪兽在结束阶段被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75363626,'魔幻甜点・泡芙骑士',replace(replace('①：只要此卡存在于怪兽区域，对手怪兽不可将“魔幻甜点・泡芙骑士”以外的“魔幻甜点”怪兽选择为攻击对象。\r\n②：此卡被对手破坏并被送至墓地的情况下发动。将此卡放回牌组。','\r',char(13)),'\n',char(10)),'返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75364199,'相视相杀','①：此回合，双方玩家持续公开手牌。以此效果持续公开手牌的期间，双方手牌存在有同名卡的场合，双方皆不可发动该卡以及该同名卡的效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75366958,'恐龙摔跤手・班卡西拉腔骨龙',replace(replace('此卡名以①方法的特殊召唤在决斗中仅可进行1次。\r\n①：自己场上不存在怪兽的情况下，此卡可从手牌特殊召唤。要将以此方法特殊召唤的此卡作为连接素材的情况下，仅可使用于“恐龙摔跤手”怪兽的连接召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75367227,'鬼计・阿尔卡德',replace(replace('等级３怪兽×２\r\n此卡名的②效果１回合仅可使用１次。①：只要此卡存在于怪兽区域，对手不可将其他“鬼计”怪兽及里侧守备表示怪兽选择为攻击对象。②：去除此卡的１个超量素材，以被放置在对手场上的１张卡为对象可以发动。将该被放置的对手的卡破坏。③：此卡被送至墓地的情况下，以自己墓地此卡以外的１张“鬼计”卡为对象可以发动。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'盖卡破坏','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75372290,'绝对防御将军','此卡召唤、反转召唤成功时，变成守备表示。此卡可以表侧守备表示的状态直接进行攻击。该场合，适用攻击力数值并进行伤害计算。','变成守备表示','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75375465,'地狱的守门熊','只要此卡以表侧表示存在于场上，我方场上的“万魔殿－魔鬼的巢穴－”就不会因对手的卡牌效果被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75376965,'恍惚人鱼','诱惑航海者并使之沉溺的美丽人鱼。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75380687,'咒符龙',replace(replace('“黑魔导”＋龙族怪兽\r\n此卡仅可通过以上述卡作为融合素材的融合召唤及“提玛欧斯之眼”的效果来特殊召唤。\r\n①：此卡特殊召唤的情况下，以自己・对手墓地的任意数量的魔法卡为对象发动。将该卡除外，此卡的攻击力上升除外的卡数量×100的数值。\r\n②：此卡被破坏的情况下，以自己墓地的1只魔法师族怪兽为对象可以发动。将该魔法师族怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'除外','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75390004,'百万角龙','全身长满角的恐龙，突击攻击相当厉害！','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75392615,'精神骇客','支付５００LP可以发动。确认对手所有手牌及场上所有被盖牌的卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75402014,'龙装合体 龙王霍普雷',replace(replace('等级５怪兽×３\r\n此卡名规则上视为“混沌编号39 希望皇霍普雷”。①：１回合１次，此卡成为效果的对象时，或被选择为攻击对象时可以发动。从手牌・牌组挑选１只“ZEXAL兵器”怪兽，视为以自身效果变成的装备卡装备于此卡。②：１回合１次，去除此卡的１个超量素材，以对手场上的表侧表示卡为对象可以发动，数量最多为此卡装备中的“ZEXAL兵器”怪兽卡的数量。将该卡的效果无效。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75416738,'光蕈之虫惑魔',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：自己场上存在“虫惑魔”怪兽的情况下，在自己・对手的主要阶段可以发动。从手牌将此卡特殊召唤。此效果发动后，直至回合结束时为止，自己从额外牌组仅可特殊召唤昆虫族・植物族怪兽。\r\n②：此卡只要存在于怪兽区域，不受“空洞”通常陷阱卡及“落穴”通常陷阱卡的效果影响。\r\n③：１回合各仅１次，自己的魔法与陷阱区域的里侧表示卡不会因效果被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75417459,'拘束解除','解放我方场上的１只“钢铁骑士 机亚弗里德”来发动此卡。从我方的手牌或牌组特殊召唤１只“剑圣－解放基亚弗利德”。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75421661,'怒怒怒斗笠剑士',replace(replace('①：只要反转召唤的此卡存在于怪兽区域，此卡的攻击力上升3500。\r\n②：此卡反转时，以场上的最多2只表侧表示怪兽为对象可以发动。将该怪兽破坏。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75425043,'精神骨架装备 阿尔法','此卡不可通常召唤，仅可以卡的效果特殊召唤。①：自己场上不存在怪兽，对手召唤・特殊召唤怪兽时可以发动。挑选自己手牌・牌组・墓地的１只“精神骨架 驱动者”，和手牌的此卡一起特殊召唤，从牌组将“精神骨架装备 阿尔法”以外的１张“精神骨架”卡加入手牌。以此效果特殊召唤的怪兽将全部在结束阶段被除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75425320,'真龙凰的使徒',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：以自己墓地的3张“真龙”卡为对象可以发动。将该卡放回牌组。然后，自己抽1张。\r\n②：在自己的主要阶段可以发动。以表侧表示进行1只“真龙”怪兽的上级召唤。\r\n③：此卡从魔法与陷阱区域被送至墓地的情况下，以场上的1张魔法・陷阱卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'回收并抽牌','上级召唤','魔法·陷阱卡破坏','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75433814,'编号40 机关傀偶－天堂之弦',replace(replace('等级８怪兽×２\r\n①：１回合１次，去除此卡的１个超量素材可以发动。在场上全部其他的表侧表示怪兽上各放１个弦计数物。\r\n②：以此卡的①效果放了弦计数物的情况下，将在下个对手的结束阶段发动。将放有弦计数物的怪兽全部破坏，给予对手相当于所破坏数量×５００的伤害。','\r',char(13)),'\n',char(10)),'放置计数物','破坏并伤害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75434695,'元素－英雄 森林人','①：1回合1次，在自己的准备阶段可以发动。从自己的牌组・墓地挑选1张“融合”加入手牌。','把1张「融合」魔法卡加入手牌。','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75448086,'创王试炼','此卡名的卡1回合仅可发动1张。①：将手牌的1只“创王”怪兽出示给对手，从牌组将最多2张“创王试炼”以外的“创王”魔法・陷阱卡加入手牌（同名卡最多1张）。然后，将出示的卡放回牌组最下面。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75452921,'梦魇曲・地狱犬',replace(replace('卡名不同的怪兽2只\r\n此卡名的①效果1回合仅可使用1次。①：此卡连接召唤成功的情况下，舍弃1张手牌，以对手主要怪兽区域的1只被特殊召唤的怪兽为对象可以发动。将该怪兽破坏。此效果发动时此卡为相互连接状态的情况下，自己可进而从牌组抽1张。②：只要此卡存在于怪兽区域，自己场上相互连接状态的怪兽不会因效果被破坏。','\r',char(13)),'\n',char(10)),'','是否抽牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75457624,'灵兽的羁绊','①：将自己场上２只表侧表示的“灵兽”怪兽除外可以发动。从额外牌组将１只“灵兽”怪兽无视召唤条件特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75487237,'中型盾守卫者','此卡１回合仅限１次可变更成里侧守备表示。仅以里侧表示的此怪兽１只为对象的魔法卡发动时发动。此卡变成表侧守备表示，并使该发动无效。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75493362,'梵格尔夫的祝福',replace(replace('此卡名的卡1回合仅可发动1张，此卡名的③效果1回合仅可使用1次。\r\n①：作为此卡发动时的效果处理，可从牌组将1只天使族・光属性怪兽送至墓地。\r\n②：自己场上的天使族怪兽的攻击力上升自己场上・墓地的天使族怪兽数量×100的数值。\r\n③：此卡被送至墓地的情况下，以自己墓地的1只等级4以下的天使族怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'发动','特殊召唤','是否把卡送至墓地？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75498415,'黑羽－晓之西洛可',replace(replace('①：仅有对手场上才存在怪兽的情况下，此卡无需解放即可通常召唤。\r\n②：1回合1次，在自己的主要阶段1，以自己场上的1只“黑羽”怪兽为对象可以发动（发动此效果的回合中，仅对象怪兽可以攻击）。该怪兽的攻击力直至回合结束时为止，上升相当于该怪兽以外的、场上的“黑羽”怪兽的攻击力的合计数值。','\r',char(13)),'\n',char(10)),'不用祭品召唤','攻击上升','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75499502,'主人与能手','擅长运用野兽的达人和忠于主人的野兽。是一对完美的搭组合。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75500286,'封印的黄金柜','①：从牌组挑选1张卡除外。在此卡发动后自己的第2次准备阶段，将以此效果除外的卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75518330,'巴利安之希望',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从自己手牌・墓地将1只“黑影”怪兽或“假面魔蹈士”超量怪兽特殊召唤。然后，可将自己场上的所有“黑影”怪兽的等级改成与自己场上・墓地的1只“黑影”怪兽相同的等级。\r\n②：将墓地的此卡除外，以自己场上的1只超量怪兽为对象可以发动。从自己额外牌组・墓地将1只“编号”超量怪兽作为对象怪兽的超量素材。','\r',char(13)),'\n',char(10)),'发动','作为素材','是否改变等级？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75524092,'凶恶之爪','装备怪兽的攻击力上升３００点。装备怪兽被战斗被破坏的情况下，将此卡放回持有者手牌作为代替。再挑选１只除进行了战斗的对手怪兽以外的怪兽破坏，并给予对手LP６００点伤害。然后，特殊召唤１只“邪恶衍生物”（恶魔族・暗・星７・攻／守２５００）至对手场上。此卡放回手牌的回合，自己不可从手牌发动・放置“凶恶之爪”。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75524093,'邪恶衍生物','由「凶恶之爪」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75525309,'六武派二刀流','己方战场上只有１只攻击状态且名字带有“六武众”的怪兽时可以发动。选择对手战场上的２张卡移回其拥有者的手上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75527221,'尸气腐朽吐息',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：自己场上存在不死族怪兽及“活死人的呼唤”的情况下，以对手场上的1只怪兽为对象可以发动。将该怪兽送至墓地。\r\n②：自己场上存在不死族怪兽的情况下，将墓地的此卡除外，以自己及对手场上的各1张表侧表示卡为对象可以发动。将该卡送至墓地。','\r',char(13)),'\n',char(10)),'发动','送至墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75539614,'念力之剑',replace(replace('“念力之剑”１回合仅可发动１张。\r\n支付１００倍数的LP可以发动此卡（最多２０００）。\r\n①：装备怪兽的攻击力・守备力上升相当于为发动此卡支付的LP数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75559356,'魔界的机械兵','用暗之力制造出来的机械兵。会像发狂般的破坏敌人。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75560629,'火石','装备怪兽攻击力下降３００点，且不可进行表示形式的变更和攻击宣言。此卡因装备怪兽被破坏而被破坏的场合，选择场上的１只怪兽，并将此卡装备于该怪兽。','装备','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75574498,'珂珑公主',replace(replace('等级４怪兽×２\r\n①：此卡超量召唤成功时，可以我方墓地的１只“玩具箱”为对象发动。特殊召唤该怪兽。\r\n②：只要我方场上存在有其他怪兽，对手不可选择此卡作为攻击对象，也不可作为效果对象。\r\n③：我方场上表侧表示的通常怪兽因战斗、效果被破坏并送入墓地的场合，可移除此卡的１个超量素材并发动。从我方的牌组、墓地挑选１只通常怪兽并以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75582395,'圣鸟','尾巴非常长的鸟。全身散发着神圣的光芒。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75620895,'独眼学艺者',replace(replace('等级４怪兽×３\r\n可以移除这张卡的１个超量素材，选择对手场上的１只超量怪兽发动。将这张卡视所选的怪兽的同名卡，并获得与之相同的效果。此卡面朝上在场上期间，此效果只能使用１次。','\r',char(13)),'\n',char(10)),'效果复制','复制效果结束','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75622824,'巧诈魔法４','①：可将我方场上１只表侧表示的“诡术师”送入墓地来发动此卡。以守备表示特殊召唤与对手场上怪兽相同数量的“巧诈衍生物”（魔法师族・风・５星・攻２０００／守１２００）至我方场上。此衍生物不可进行攻击宣言。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75622825,'巧诈衍生物','由「巧诈魔法４」的效果特殊召唤。这衍生物不能攻击宣言。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75646173,'方阵兽','上下都有头的、令人作呕的怪兽。口中可以吐出激光。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75646520,'金属探知器','永续陷阱卡发动时可发动。此回合，场上的永续陷阱卡的效果被无效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75652080,'二重旋风','①：可以我方场上的１张魔法、陷阱卡与对方场上的１张魔法、陷阱为对象发动。破坏该卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75660578,'死之创王 赫尔','此卡名的②效果1回合仅可使用1次。①：“死之创王 赫尔”在自己场上仅可有1只以表侧表示存在。②：解放自己场上的1只“创王”怪兽或者是不死族怪兽，可以和该怪兽卡名不同的自己墓地的1只“创王”怪兽或者是不死族怪兽为对象发动。以守备表示形式将该怪兽特殊召唤。此效果在对手回合中也可以发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75672051,'黑牙的魔术师',replace(replace('←8 【灵摆】 8→\r\n①：１回合１次，以对手场上的１只表侧表示怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止改成一半。然后将此卡破坏。\r\n【怪兽效果】\r\n此卡在规则上也视为“超量龙”卡。①：此卡因战斗・效果被破坏的情况下，以自己墓地的１只魔法师族・暗属性怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75673220,'龙草','此卡被送入墓地时，随机挑选１张对手手牌，并直至结束阶段以表侧表示从游戏中除外。“龙草”的效果１回合只可使用１次。','手牌除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75675029,'记忆破坏王','此卡直接攻击给予对手LP战斗伤害时，将对手墓地中的所有同步怪兽从游戏除外，给予对手LP该数量×１０００点伤害。','除外并伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75676192,'方程式运动员运载房车',replace(replace('协调+1只以上协调以外的怪兽\r\n①：此卡的攻击力上升相当于此卡等级×300的数值。②：“方程式运动员”魔法・陷阱卡的效果发动的情况下可以发动（伤害步骤也可以发动）。此卡的等级上升1。③：依据此卡的等级，此卡获得以下效果。\r\n●等级11以上：此卡不会因战斗・效果被破坏。\r\n●等级13以上：1回合1次，以自己墓地的1只“方程式运动员”怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75690317,'机偶蛤蟆 四六贰四','此卡名的③效果１回合仅可使用１次。①：此卡在可攻击的情况下必须攻击。②：此卡在被选择为攻击对象的情况下发动。变更此卡的表示形式。③：将墓地的此卡除外，以自己场上的１只“机偶”怪兽为对象可以发动。变更该怪兽的表示形式。此效果在对手回合中也可以发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75702749,'幻煌龙之螺旋绞',replace(replace('仅可装备于通常怪兽。\r\n“幻煌龙之螺旋绞”的②效果１回合仅可使用１次。\r\n①：装备怪兽的攻击力上升５００。\r\n②：装备怪兽战斗破坏对手怪兽时可以发动。从自己的手牌・牌组・墓地挑选１只“幻煌龙 螺旋”特殊召唤，将此卡装备于该怪兽。然后给予对手１０００伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75713017,'燎星之普罗米流星','①：以此卡的攻击破坏主要怪兽区的对手怪兽时，可舍弃１张手牌并发动。此卡可连续进行攻击。直至下一个回合结束时，该怪兽曾存在的区域不可使用。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75719089,'荣光的圣骑士团',replace(replace('此卡牌名的卡牌１合只可发动１张。\r\n①：可以我方场上的１只“圣骑士”怪兽为对象发动。从牌组挑选１张该我方怪兽能够装备的装备魔法卡，装备该怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75728539,'新世坏回',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：场上存在“维萨思・史塔弗罗斯特”的情况下，以场上的１只效果怪兽为对象可以发动。将该效果怪兽放回牌组。在此回合的结束阶段，其持有者可从牌组将１只种族与所放回怪兽不同、等级数值低于其等级・阶级・连接的怪兽加入手牌。\r\n②：此卡存在于墓地的状态下，“韦陀”怪兽被特殊召唤的情况下可以发动。将此卡加入手牌。','\r',char(13)),'\n',char(10)),'','','是否从牌组把怪兽加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75730490,'拉比丽斯的仆从 亚莉安努',replace(replace('此卡名的①②效果１回合仅可各使用１次。①：从手牌及被放置在自己场上的卡中，将１张通常陷阱卡送至墓地可以发动。从牌组将１只“拉比丽斯的仆从 亚莉安努”以外的等级４以下的恶魔族怪兽以守备表示特殊召唤。②：怪兽因自己通常陷阱卡的效果从场上离开的情况下可以发动。自己从牌组抽１张。然后，可以适用以下效果。\r\n●从手牌、特殊召唤１只恶魔族怪兽，或放置１张魔法・陷阱卡。','\r',char(13)),'\n',char(10)),'','抽牌','从手牌特殊召唤','从手牌放置','什么都不做','','','','','','','','','','','');
INSERT INTO texts VALUES(75732622,'拷问魔像','此卡不可通常召唤。通过在自己场上以攻击表示特殊召唤２只“拷问衍生物”（恶魔族・暗・星１・攻／守０），可以特殊召唤至对手场上。将此卡特殊召唤的回合，自己不可通常召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75732623,'拷问衍生物','由“拷问魔像”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75733063,'机皇兵神空・一型','此卡的攻击力上升除此卡以外场上冠有“机皇”之名的怪兽数量×２００点。此卡因战斗被破坏并送入墓地时可发动。从牌组特殊召唤１只冠有“机皇兵”之名的怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75745607,'火之迦具土','此卡不可特殊召唤。召唤・反转此卡的回合的结束阶段时回到持有者的手牌中。此卡对对手生命造成战斗伤害时发动此卡。下个回合抽牌阶段抽牌前对手弃置所有手牌。','返回手牌','手牌丢弃','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75748977,'XYZ－高能龙型加农炮',replace(replace('“X－交叉加农”＋“Y－敏捷龙首”＋“Z－无尽履带”\r\n此卡从额外牌组仅可在将自己场上・墓地的上述卡除外的情况下特殊召唤。\r\n①：每个对手回合中１次，舍弃１张手牌，以对手场上的１张卡为对象可以发动。将该卡破坏。\r\n②：将场上・墓地的此卡除外，将额外牌组的１只机械族・光属性・等级８融合怪兽出示给对手可以发动。将自己的墓地・除外状态的最多３只卡名记载于该怪兽的融合素材怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'破坏效果','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75771170,'荒日女之御巫',replace(replace('以“御巫神乐”降临\r\n此卡名的①效果1回合仅可使用1次。\r\n①：此卡存在于手牌・墓地，自己墓地存在其他“御巫”卡的情况下，以场上的1只表侧表示怪兽为对象可以发动。将此卡视为装备魔法卡，装备于该怪兽。\r\n②：此卡被装备中的情况下，在自己・对手的结束阶段可以发动。将此卡和装备怪兽放回手牌。\r\n③：此卡不会因战斗被破坏，因此卡的战斗对自己造成的战斗伤害由对手代为承受。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75775867,'变形斗士・弹弓',replace(replace('此卡依据此卡的表示形式获得以下效果。\r\n●攻击表示：１回合１次，可释放１只除“变形斗士・弹弓”以外的冠有“变形斗士”之名的怪兽并发动。选择场上的１张卡牌并破坏。\r\n●守备表示：此卡被破坏的场合，可破坏我方场上的１只冠有“变形斗士”之名的怪兽作为代替。','\r',char(13)),'\n',char(10)),'场上1张卡破坏','是否用1只名字带有「变形斗士」的怪兽代替破坏？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75779210,'大日神械艾普希龙',replace(replace('光属性协调＋协调以外的怪兽１只或以上\r\n装备在此卡的装备卡，不会成为卡牌的效果对象。此外，１回合１次，可将装备在此卡的我方场上的１张装备卡送入墓地并发动。选择对手场上的１只怪兽并破坏。','\r',char(13)),'\n',char(10)),'对手场上的1只怪兽破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75780818,'恐龙战车',replace(replace('机械族怪兽＋恐龙族怪兽\r\n此卡名的②③效果１回合仅可各使用１次。\r\n①：此卡的攻击力上升相当于作为此卡融合素材的恐龙族怪兽原本攻击力的数值。\r\n②：仅以场上的此１张卡作为对象的效果发动时，以场上此卡以外的１张卡为对象可以发动。将该对象移换至可以是正确对象的该卡。\r\n③：此卡被对手破坏的情况下可以发动。从自己的墓地挑选１只恐龙族怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75782277,'神鹰狩猎场','①：场上鸟兽族怪兽的攻击力・守备力上升２００。②：自己或对手召唤・特殊召唤“神鹰女郎”或“神鹰女郎三姐妹”成功的情况下，该玩家以场上１张魔法・陷阱卡为对象发动。将该卡破坏。','魔陷破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75787708,'四天之龙 异色眼灵摆龙',replace(replace('←4 【灵摆】 4→\r\n此卡名的灵摆效果1回合仅可使用1次。\n①：在自己的主要阶段可以发动。将此卡破坏，从牌组将1只攻击力1500以下的灵摆怪兽加入手牌。此回合，自己只要未灵摆召唤成功，则不可发动场上怪兽的效果。\r\n【怪兽效果】\r\n此卡名的②怪兽效果1回合仅可使用1次。\n①：灵摆召唤的此卡获得以下效果。\n●只要自己的灵摆区域存在2张卡，此卡攻击力上升其灵摆刻度的差值×300的数值。\n●因此卡的战斗对对手造成的战斗伤害变为两倍。\n②：怪兽区域的此卡因战斗・效果被破坏的情况下可以发动。将此卡加入手牌。此卡是被对手破坏的情况下，进而可将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'检索','加入手牌','是否特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75787709,'四天之龙 异色眼灵摆龙',replace(replace('←4 【灵摆】 4→\r\n此卡名的灵摆效果1回合仅可使用1次。\n①：在自己的主要阶段可以发动。将此卡破坏，从牌组将1只攻击力1500以下的灵摆怪兽加入手牌。此回合，自己只要未灵摆召唤成功，则不可发动场上怪兽的效果。\r\n【怪兽效果】\r\n此卡名的②怪兽效果1回合仅可使用1次。\n①：灵摆召唤的此卡获得以下效果。\n●只要自己的灵摆区域存在2张卡，此卡攻击力上升其灵摆刻度的差值×300的数值。\n●因此卡的战斗对对手造成的战斗伤害变为两倍。\n②：怪兽区域的此卡因战斗・效果被破坏的情况下可以发动。将此卡加入手牌。此卡是被对手破坏的情况下，进而可将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'检索','加入手牌','是否特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75797046,'光子亚历山大蝶后',replace(replace('名字带有“幻蝶刺客”的等级４怪兽×２\r\n移除此卡的１个超量素材可以发动。将场上所有怪兽放回持有者的手牌。然后，以此效果将卡片加入手牌的玩家，受到该数量×３００点伤害。','\r',char(13)),'\n',char(10)),'返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75830094,'荷鲁斯之黑炎龙 LV4',replace(replace('①：此卡只要存在于怪兽区域，控制权不可变更。\r\n②：在此卡战斗破坏怪兽的回合的结束阶段，将此卡送至墓地可以发动。从手牌・牌组将１只“荷鲁斯之黑炎龙 LV6”特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75833426,'魔幻甜点・茶歇','①：自己的墓地不存在怪兽，且魔法・陷阱卡发动时可以发动。将该发动无效，将该卡放回手牌。自己场上存在“魔幻甜点・布丁公主”的情况下，进而可将对手场上的１张卡破坏。','是否要选择对手场上一张卡破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75840616,'武斗神帝－须佐之男',replace(replace('等级４“武斗神”怪兽×２\r\n①：我方场上只可有１只“武斗神帝－须佐之男”以表侧表示存在。\r\n②：此卡可对所有对手怪兽各进行１次攻击。\r\n③：１回合１次，可移除取此卡的１个超量素材并发动。从牌组挑选１只“武斗神”怪兽，并加入手牌或送入墓地。','\r',char(13)),'\n',char(10)),'检索','是否要将怪兽加入手牌？','怪兽送至墓地','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75850803,'明月','住在月球上的魔法师。会以月亮的魔力迷惑对手。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75874514,'闪耀的星之龙',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：此卡存在于手牌的情况下，在对手的主要阶段，以自己墓地的1只龙族同步怪兽为对象可以发动。将此卡特殊召唤，将对象怪兽的效果无效并特殊召唤。然后，可将包含此卡在内的自己场上的怪兽作为素材，进行1只龙族同步怪兽的同步召唤。\r\n②：以此卡做为同步素材将龙族同步怪兽同步召唤的情况下，该同步怪兽不会因战斗被破坏。','\r',char(13)),'\n',char(10)),'从手牌特殊召唤','「闪耀的星之龙」效果适用中','是否进行同步召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75878039,'卫星骑士 天鹅德奈普',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：此卡召唤・反转召唤・特殊召唤的情况下可以发动。从牌组将“卫星骑士 天鹅德奈普”以外的1只“星骑士”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'牌组检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75884822,'扰乱怪・睡衣派对',replace(replace('此卡名的①③效果１回合仅可各使用１次。\r\n①：在自己・对手的主要阶段可以发动。从牌组将１张“扰乱怪”卡加入手牌，然后挑选１张手牌舍弃。\r\n②：自己场上的“武装龙”怪兽或机械族・光属性融合怪兽将被战斗・效果破坏的情况下，可将自己手牌・场上・墓地的１张“扰乱怪”卡除外作为代替。\r\n③：此卡被送至墓地的情况下可以发动。将自己被除外的“扰乱怪”怪兽尽可能地特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75886890,'大日神械球体','此卡从怪兽区被送入墓地的场合，可支付５００LP，选择我方场上的１只表侧表示怪兽并发动。此卡被视为装备卡装备被选择的我方怪兽。此外，可将装备于怪兽的此卡送入墓地并发动。从我方墓地选择１张装备魔法卡并装备此卡的装备怪兽。','当成装备卡装备','选择一张装备魔法卡装备','请选择一张装备魔法卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75888208,'梦魔镜梦魔－伊刻洛斯','此卡名的①②效果1回合仅可各使用1次。①：此卡以“梦魔镜”怪兽的效果特殊召唤成功的情况下可以发动。从手牌将“梦魔镜梦魔-伊刻洛斯”以外的1只“梦魔镜”怪兽特殊召唤。②：场地区域有“圣光之梦魔镜”存在的情况下，在自己・对手的主要阶段及战斗阶段，解放此卡可以发动。从牌组将1只“梦魔镜少女-伊刻洛斯”特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75889523,'恶魔啃食者','拥有恶魔角和翅膀的河狸。会投掷橡子进行攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75892194,'古代机械齿轮龙',replace(replace('此卡不可特殊召唤。\r\n此卡名的②效果１回合仅可使用１次。\r\n①：自己场上的怪兽，不存在的情况下或仅有机械族・地属性怪兽的情况下，此卡无需解放即可召唤。\r\n②：对手发动魔法・陷阱卡的效果时，将自己的手牌・场上（表侧表示）的１只机械族怪兽或牌组的１只“古代机械齿轮巨人”送至墓地可以发动。将该效果无效。','\r',char(13)),'\n',char(10)),'不用解放作召唤','魔法·陷阱卡无效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75901113,'铠龙圣骑','以“铠龙降临”降临。此卡名的①②效果１回合仅可各使用１次。①：被从额外牌组特殊召唤的怪兽与此卡进行战斗的伤害步骤开始时可以发动。将该怪兽放回持有者的牌组。②：解放此卡可以发动。从手牌・牌组将１只等级５以上的龙族・风属性怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75902998,'穿刺的落穴','①：在此回合召唤・特殊召唤而来的对手怪兽的攻击宣言时可以发动。破坏该攻击怪兽，并给予对手该怪兽原本攻击力一半数值的伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75906310,'武装龙弹射加农炮',replace(replace('“VWXYZ－弹射加农龙”＋“武装龙 LV7”\r\n我方将上述所有卡牌特殊召唤成功的决斗中，仅限将我方场地、墓地的上述卡牌除外的场合，可从额外牌组特殊召唤（不需要“融合”）。\r\n①：只要此卡存在于怪兽区，对手不可发动被除外的我方、对手卡牌以及同名卡的效果。\r\n②：对手回合仅１次，可从牌组、额外牌组除外１张卡牌并发动。将对手场上、墓地的所有卡牌除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75917088,'魔法之国的王女－比可儿','此卡不可通常召唤。只有通过“王女的试炼”的效果才可特殊召唤此卡。在我方的准备阶段时，回复我方场上的怪兽数量×８００点LP。','LP回复','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75922381,'电光闪灵・红精','此卡名以①方法的特殊召唤１回合仅可进行１次，且②效果１回合仅可使用１次。①：自己场上存在等级２或连接２的怪兽的情况下，此卡可从手牌中特殊召唤。②：对手发动怪兽的效果时，解放此卡以外的、自己场上的１只等级２・阶级２・连接２的怪兽可以发动。将该效果无效。解放阶级２或连接２的怪兽来发动的情况下，进而可将该怪兽破坏。','','','是否把那只怪兽破坏？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75923050,'稀有金属女武神',replace(replace('“稀有金属女郎”＋“稀有金属战士”\r\n直接攻击对手玩家时，伤害步骤期间此卡的攻击力上升１０００点。另外，此卡在被特殊召唤回合以外的我方主要阶段时，可将此卡返回至额外牌组，并从额外牌组特殊召唤１只“稀有金属骑士”。','\r',char(13)),'\n',char(10)),'攻击上升','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75926389,'AtoZ 能量加载',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：对手发动魔法・陷阱・怪兽的效果时可以发动。自己依自己场上等级８以上的机械族・光属性融合怪兽的数量来抽牌。\r\n②：在自己的准备阶段，将墓地的此卡除外可以发动。将包含联合怪兽在内的、自己的除外状态的最多６只机械族・光属性怪兽放回牌组。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75937826,'巨大战舰 巨核Mk－Ⅱ',replace(replace('①：自己场上不存在怪兽的情况下，此卡无需解放即可召唤。\r\n②：此卡特殊召唤的情况下发动。在此卡上放3个计数物。\r\n③：此卡不会因战斗被破坏。\r\n④：此卡进行战斗的伤害步骤结束时发动。去除此卡的1个计数物。无法去除的情况下将此卡破坏。','\r',char(13)),'\n',char(10)),'放置计数物','取除计数物','破坏','不解放作召唤','','','','','','','','','','','','');
INSERT INTO texts VALUES(75944053,'文具博格００３','①：此卡召唤成功时可以发动。从牌组将“文具博格００３”以外的１只“文具博格”怪兽特殊召唤。②：１回合１次，以自己场上的１只“文具博格”怪兽为对象可以发动。该怪兽的攻击力・守备力直至回合结束时为止，上升相当于自己场上“文具博格”卡数量×５００的数值。此效果在对手回合中也可以发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75946257,'混沌的咒术师','反转：从我方或对手的墓地选择１只怪兽从游戏中除外。','除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75952542,'弈勇世界－百识公国','此卡名的②效果１回合仅可使用１次。①：作为此卡发动时的效果处理，从牌组将１张“弈勇世界－百识公国”以外的“弈勇”场地魔法卡以表侧表示放在对手的场地区域。②：场地区域有２张卡的情况下，回合玩家以自己怪兽正面的、对手主要怪兽区域的１只效果怪兽为对象可以发动。将该对手怪兽视为永续魔法卡，以表侧表示放在同一纵列的对手的魔法与陷阱区域（原先位于所放之处的卡将被破坏）。','请选择要放置到后场的怪兽','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75953262,'战士 戴・古雷法','身怀操控龙族天赋的战士。其过去充满谜团。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75956913,'我我我霍普战术',replace(replace('此卡名的②③效果1回合仅可各使用1次。\r\n①：自己场上原本属性为光属性的“霍普”超量怪兽不会因效果被破坏，对手不可将其作为效果对象。\r\n②：宣言1～12的任意等级，以自己场上包含“我我我”怪兽在内的2只表侧表示怪兽为对象可以发动。将该怪兽的等级改成宣言的等级。\r\n③：自己将原本属性为光属性的“霍普”超量怪兽超量召唤的情况下，以对手场上的1张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','修改等级','破坏','请选择要宣言的等级','','','','','','','','','','','','');
INSERT INTO texts VALUES(75967082,'漏电','自己场上有３只以上名字带有“电池人”的怪兽存在的情况下可以发动。将对手场上所有卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75983808,'混沌魔术箱',replace(replace('①：对手发动以自己场上的其他卡为对象的效果时可以发动。将该自己的卡中的1张放回手牌（里侧表示卡则翻开确认），将场上的1张卡破坏。然后，可从手牌将1只卡名与所放回手牌的卡不同的、记载有“光与暗的仪式”卡名的怪兽无视召唤条件特殊召唤。\r\n②：此卡被对手破坏的情况下可以发动。从手牌・牌组将1只记载有“光与暗的仪式”卡名的仪式怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'破坏效果','特殊召唤','是否特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75987257,'隶属的鳞粉','对手怪兽的攻击宣言时，可选择１只该怪兽并发动。被选择攻击怪兽变成守备表示，并将此卡视为装备卡装备于该怪兽。此外，１回合１次，在主要阶段及战斗阶段中可发动。变更装备怪兽的表示形式。','变更表示形式','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75988594,'超重剑圣 武藏－C',replace(replace('协调＋１只以上协调以外的怪兽\r\n此卡名在规则上也视为“超重武者”卡。①：此卡同步召唤成功时，以自己墓地的１只机械族怪兽为对象可以发动。将该怪兽加入手牌。自己的墓地有魔法・陷阱卡存在的情况下，此回合，自己不可召唤・特殊召唤该怪兽及该怪兽的同名怪兽。②：此卡可在表侧守备表示的状态下攻击。该情况下，将此卡的守备力视为攻击力来进行伤害计算。','\r',char(13)),'\n',char(10)),'加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75991479,'异次元的哨戒机',replace(replace('此卡牌名的效果１回合只可使用１次。\r\n①：在此卡被除外回合的结束阶段可发动。从我方的手牌、场上、墓地挑选１张卡牌除外，并以攻击表示特殊召唤此卡。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(75991898,'岩浆炎谷・龙',replace(replace('协调＋协调以外的炎属性怪兽１只或以上\r\n可将我方墓地２只冠有“岩浆炎”之名的怪兽返回至牌组，并选择１张对手场上的卡牌发动。将被选择卡牌返回至持有者手牌。','\r',char(13)),'\n',char(10)),'返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76004142,'不幸的爆弹',replace(replace('“不幸的爆弹”１回合仅可发动１张。\r\n①：以对手场上的１只表侧表示怪兽为对象可以发动。自己受到该表侧表示怪兽攻击力一半数值的伤害。然后，给予对手自己所受到的相同数值的伤害。\r\n②：场上的此卡被对手破坏并被送至墓地的情况下发动。给予对手１０００点伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76029419,'DDD 超视王零麦克斯韦',replace(replace('←4 【灵摆】 4→\r\n此卡名的灵摆效果１回合仅可使用１次。\n①：以场上的１只表侧表示怪兽为对象可以发动。将该怪兽的守备力直至回合结束时为止改成０。\r\n【怪兽效果】\r\n①：此卡攻击对手的守备表示怪兽的伤害计算前可以发动。该对手怪兽的守备力直至伤害步骤结束时为止变为０。\n②：此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。\n③：因此卡的战斗对自己造成的战斗伤害变为０。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76039636,'魔鬼铲土虫',replace(replace('此卡不可通常召唤。\r\n仅可在从自己的墓地将２只昆虫族怪兽除外的情况下特殊召唤。\r\n①：此卡给予对手战斗伤害的情况下发动。从对手的牌组上面将１张卡送至墓地。','\r',char(13)),'\n',char(10)),'对方卡组最上面把1张卡送至墓地','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76045757,'代罪之暗','①：破坏场上卡牌的对手魔法、陷阱、怪兽的效果发动时可发动。使该效果无效。之后，从牌组将１只等级３或以下的暗属性怪兽送入墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76052811,'地狱诗人 赫波艾','此卡因战斗而被破坏送入墓地的场合，发动效果。只要此卡存在于墓地中，对手需在对手的战斗阶段结束时随机弃置１张手牌。此卡不可从墓地特殊召唤。','丢弃手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76066541,'龙探测摆',replace(replace('“龙探测摆”的效果１回合只可使用１次。\r\n①：场上的此卡因战斗或对手效果被破坏并送入墓地时可发动。从牌组以守备表示特殊召唤１只地属性灵摆怪兽。以此效果特殊召唤的怪兽在结束阶段被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76067258,'编号66 霸键甲虫 万能钥匙兜虫',replace(replace('暗属性等级4怪兽×2\r\n①：1回合1次，去除此卡的1个超量素材，以自己场上的1张其他卡为对象可以发动。此卡获得以下效果。\r\n●只要此卡存在于怪兽区域，对象卡不会因效果被破坏。\r\n●此卡将被战斗・效果破坏的情况下，作为代替可将自己的1张对象卡送至墓地。','\r',char(13)),'\n',char(10)),'破坏耐性','是否要使用「编号66 霸键甲虫」的效果代替破坏？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76072561,'闪刀姬＝零萝',replace(replace('“闪刀姬”怪兽2只\r\n自己1回合仅可特殊召唤1次“闪刀姬＝零萝”，此卡不可作为连接素材。\r\n此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：此卡特殊召唤的情况下可以发动。从自己牌组・墓地将1张“闪刀”魔法卡加入手牌。\r\n②：在自己・对手回合中，解放此卡可以发动。从自己牌组・墓地将“闪刀姬－零”“闪刀姬－萝杰”各1只特殊召唤。然后，可将场上的1张卡破坏。','\r',char(13)),'\n',char(10)),'检索魔法卡','特殊召唤','是否选卡破坏？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76075139,'弈勇－创世大公',replace(replace('←10 【灵摆】 10→\r\n此卡名的灵摆效果１回合仅可使用１次。①：可从以下效果中选择１个发动。\n●将此卡特殊召唤至正面的自己主要怪兽区域。\n●挑选１只自己主要怪兽区域的怪兽，将其位置移动至其相邻的怪兽区域。\r\n【怪兽效果】\r\n“弈勇”怪兽×２\n额外牌组里侧表示的此卡仅可以融合召唤及以下方法特殊召唤。\n●解放１只除了融合怪兽以外的、与额外怪兽区域同一纵列的自己的等级５以上的“弈勇”怪兽的情况下可以特殊召唤。\n①：此卡特殊召唤成功的情况下，以对手魔法与陷阱区域的１张怪兽卡为对象可以发动。将该卡放回持有者的手牌，给予对手相当于其攻击力数值的伤害。然后，此卡的攻击力上升相当于给予的伤害数值一半的数值。','\r',char(13)),'\n',char(10)),'特殊召唤','位置移动','请选择移动位置的怪兽','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76075810,'投石部队','可解放我方场上１只除此卡以外的战士族怪兽并发动。挑选场上１只持有守备力为此卡攻击力以下的怪兽破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76076738,'暗龙族之爪',replace(replace('仅可装备于暗属性怪兽。\r\n此卡名的②效果１回合仅可使用１次。\r\n①：装备怪兽的攻击力上升６００，不会因对手的效果被破坏。\r\n②：装备怪兽因战斗被破坏并被送至墓地导致此卡也被送至墓地的情况下可以发动。将该怪兽特殊召唤至自己场上，装备此卡。以此效果被装备的此卡离开场上的情况下，将其除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76078185,'异端之弗魄祀寇猧司',replace(replace('等级４怪兽×２\r\n此卡名的①效果１回合仅可使用１次。\r\n①：以对手场上的１只效果怪兽为对象可以发动（此卡持有幻想魔族怪兽作为超量素材的情况下，此效果在对手回合中也可以发动）。将对象怪兽的效果无效。该怪兽在此回合进行过战斗的情况下，进而可获得其控制权直至结束阶段为止。\r\n②：此卡与怪兽进行战斗的情况下，该２只不会因该战斗被破坏。','\r',char(13)),'\n',char(10)),'效果无效','是否得到控制权？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76080032,'ZEXAL兵器－一角兽皇枪','①：“ZEXAL兵器－一角兽皇枪”在自己场上仅可有１张以表侧表示形式存在。②：以自己场上的１只“混沌编号39 希望皇霍普雷”为对象可以发动。将手牌的此卡视为攻击力上升１９００的装备卡，装备于该自己的“混沌编号39 希望皇霍普雷”。③：装备怪兽与对手怪兽进行战斗的情况下，仅在战斗阶段期间该对手怪兽的效果无效化。','装备','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76103404,'电子小天使','此卡名的效果１回合仅可使用１次。①：此卡召唤・反转召唤・特殊召唤成功的情况下可以发动。从牌组将１只“电子天使”怪兽或１张“机械天使的仪式”加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76103675,'火花','给予对手２００伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76133574,'游魊之红玉 泽普',replace(replace('此卡名的①②③效果１回合仅可各使用１次。\r\n①：将此卡从手牌除外，以自己墓地的１只鱼族怪兽为对象可以发动。将该怪兽除外。\r\n②：此卡在对手回合被除外的情况下可以发动。将此卡特殊召唤。\r\n③：此卡特殊召唤的情况下可以发动。将包含此卡在内的自己场上的怪兽作为素材，将１只鱼族同步怪兽同步召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76136345,'回转调车',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：机械族・地属性・等级10怪兽被召唤・特殊召唤至自己场上的情况下可以发动。从牌组将1只攻击力1800以上的机械族・地属性・等级4怪兽特殊召唤。以此效果特殊召唤的怪兽的等级变为10。此效果发动后，直至回合结束时为止，对手所受战斗伤害变为0。\r\n②：将1张手牌送至墓地可以发动。从牌组将1只机械族・地属性・等级10怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76137276,'魔法捕获','我方发动魔法卡时，可舍弃１张手牌并发动。该魔法卡被送入墓地时，该卡牌返回至持有者手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76137614,'神圣解咒师','１回合１次，可取除场上的１个魔力计数物，令场上１张表侧表示的魔法卡回到手牌中。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76145142,'自鸣天琴・朗基尔苏',replace(replace('包括“自鸣天琴”怪兽在内的效果怪兽2只以上\r\n此卡名的②效果1回合仅可使用1次。①：连接状态的此卡不会因效果被破坏。②：以2只被除外的自己的机械族怪兽为对象可以发动。将该怪兽放回牌组。然后，可挑选1只连接状态的对手怪兽送至墓地。发动此效果的回合中，此卡不可攻击。','\r',char(13)),'\n',char(10)),'','是否把对手怪兽送至墓地？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76145933,'电光闪灵・蓝精','此卡名以①方法的特殊召唤１回合仅可进行１次，且②效果１回合仅可使用１次。①：自己场上存在等级２或阶级２的怪兽的情况下，此卡可从手牌中特殊召唤。②：此卡特殊召唤成功的情况下可以发动。从牌组将１只“电光闪灵・蓝精”以外的“电光闪灵”怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76184692,'独眼巨人','只有一只眼睛的巨人。利用巨腕殴打敌人，需要特别小心。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76202610,'黑暗子','此卡召唤成功时可发动。直至回合结束时，我方场上的表侧表示怪兽等级提升１级，并变成暗属性。','等级属性变换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76203291,'光鳞飞鱼','可解放我方场上１只除此卡以外的鱼族怪兽并发动。选择场上的１张卡牌并破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76209339,'巨石异物・创出','此卡名的①效果1回合仅可使用1次。①：以自己墓地的1只“巨石异物”怪兽为对象可以发动。以守备表示形式将该怪兽特殊召唤。以此效果特殊召唤的怪兽从场上离开的情况下，放回持有者牌组的最下面。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76211194,'暗黑拿破仑','心有歹意者所制造出的眼珠恶魔。会以暗黑炸弹进行爆破攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76213610,'死宰 萨姆艾尔',replace(replace('等级6怪兽×2\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己・对手的主要阶段，去除此卡的1个超量素材，以自己墓地的1只不死族怪兽为对象可以发动。将该怪兽特殊召唤。然后，可将对手场上的1只、攻击力在以此效果特殊召唤的怪兽的攻击力以下的怪兽的效果无效。\r\n②：此卡被送至墓地的情况下，以自己或对手墓地的1只怪兽为对象可以发动。将该怪兽放回牌组。','\r',char(13)),'\n',char(10)),'特殊召唤','回到牌组','是否让怪兽无效？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76214441,'生命协调体','对方发动持有伤害效果的怪兽效果、魔法、陷阱卡时，可从手牌中舍弃此卡并发动。使该发动无效并破坏。','效果无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76218313,'破坏剑－龙毁灭之剑',replace(replace('“破坏剑－龙毁灭之剑”的③效果１回合仅可使用１次。\r\n①：在自己的主要阶段，以自己场上的１只“毁灭剑士”为对象可以发动。从自己的手牌・场上，将此怪兽视为装备卡装备于该自己的怪兽。\r\n②：此卡被装备中的情况下，对手不可从额外牌组特殊召唤怪兽。\r\n③：此卡被装备中的情况下可以发动。将被装备的此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76218643,'黑色波坦','我方场上存在有协调的场合，此卡不会因战斗被破坏。我方场上表侧表示的协调从场上离开时，我方回复８００LP。','LP回复','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76224717,'升级区域',replace(replace('１回合１次，可在我方成功进行上级召唤回合的结束阶段时发动此卡。按照该回合中我方上级召唤而释放的怪兽数量，适用以下效果。\r\n●１只以上：破坏对手场上１张被盖牌的卡牌。\r\n●２只以上：从牌组抽取１张卡牌。\r\n●３只以上：将我方墓地中的１只怪兽加入到手牌中。','\r',char(13)),'\n',char(10)),'破坏对手场上1张盖卡','抽1张卡','把1只自己墓地的怪兽加入自己手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76232340,'仟年原人','拥有千年神器的原始人，无论什么时候都凭蛮力进击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76232522,'恢复巫师',replace(replace('电子界族怪兽２只\r\n此卡牌名的效果１回合只可使用１次。\r\n①：可以在此回合被破坏之我方墓地的１只电子界族连接怪兽为对象发动。特殊召唤该怪兽。以此效果特殊召唤之怪兽的效果被无效化，并在结束阶段被破坏。此效果在对手回合也可发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76263644,'龙骑兵 D-终结',replace(replace('“命运-英雄 血魔-D”＋“命运-英雄 教义魔侠”\r\n此卡的融合召唤仅可用上述卡进行。①：1回合1次，以对手场上的1只怪兽为对象可以发动。破坏该对手怪兽，破坏的是表侧表示怪兽的情况下，给予对手相当于其攻击力数值的伤害。发动此效果的回合中，自己无法进行战斗阶段。②：此卡存在于墓地的情况下，在自己的准备阶段将自己墓地的1张“命运-英雄”卡除外可以发动。从墓地将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'破坏','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76290637,'机关傀偶－迷魅机械神',replace(replace('等级８怪兽×２\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：去除此卡的１个超量素材可以发动。从牌组将１张“升阶魔法”魔法卡加入手牌。此回合，自己除通常召唤外仅可追加１次，在自己的主要阶段召唤１只机械族怪兽。\r\n②：自己将“机关傀偶”超量怪兽特殊召唤的情况下可以发动。从墓地将此卡以守备表示特殊召唤至自己或对手场上。然后，可从自己的墓地将１张“升阶魔法”魔法卡加入手牌。','\r',char(13)),'\n',char(10)),'检索「升阶魔法」魔法卡','从墓地特殊召唤','使用「机关傀偶-机械降临的粉丝幻想」的效果召唤','在自己场上特殊召唤','在对手场上特殊召唤','是否从墓地把「升阶魔法」魔法卡加入手牌？','','','','','','','','','','');
INSERT INTO texts VALUES(76290638,'机关傀偶－迷魅机械神',replace(replace('等级８怪兽×２\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：去除此卡的１个超量素材可以发动。从牌组将１张“升阶魔法”魔法卡加入手牌。此回合，自己除通常召唤外仅可追加１次，在自己的主要阶段召唤１只机械族怪兽。\r\n②：自己将“机关傀偶”超量怪兽特殊召唤的情况下可以发动。从墓地将此卡以守备表示特殊召唤至自己或对手场上。然后，可从自己的墓地将１张“升阶魔法”魔法卡加入手牌。','\r',char(13)),'\n',char(10)),'检索「升阶魔法」魔法卡','从墓地特殊召唤','使用「机关傀偶-机械降临的粉丝幻想」的效果召唤','在自己场上特殊召唤','在对手场上特殊召唤','是否从墓地把「升阶魔法」魔法卡加入手牌？','','','','','','','','','','');
INSERT INTO texts VALUES(76297408,'魂粉碎','只要此卡存在于场上，通过支付５００LP，双方各选择存在于对手墓地的１只怪兽并从游戏中除外。该效果仅在我方场上有恶魔族怪兽以表侧表示存在的场合可发动。','除外','是否现在使用「魂粉碎」的效果？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76302448,'秘仪牌阵',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：掷1次硬币，根据掷出的正反，适用以下效果。自己的场地区域存在“光之结界”的情况下，不掷硬币而改为从正反的效果中择一适用。\r\n●正面：从牌组将1只等级4以下的“秘仪之力”怪兽特殊召唤。\r\n●反面：从自己墓地将1只拥有掷硬币效果的怪兽特殊召唤。\r\n②：将墓地的此卡除外可以发动。从自己墓地将1张拥有掷硬币效果的卡加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','墓地加入手牌','表','里','','','','','','','','','','','','');
INSERT INTO texts VALUES(76305638,'岩之精灵 泰坦','此卡不可通常召唤。将我方墓地中１只地属性怪兽从游戏中除外的场合，可特殊召唤此卡。此卡的攻击力在对手的战斗阶段中上升３００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76321376,'地雷魔像','此卡因战斗被破坏并送入墓地时，给予对手生命５００点的伤害。','LP伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76334960,'召唤魔术－“杯”',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：自己场上、墓地或除外状态存在“阿莱斯特”怪兽的情况下，可从以下效果中选择1个发动。\r\n●将自己手牌・场上的1只怪兽和自己牌组的1只怪兽作为融合素材除外，将1只“召唤兽”融合怪兽融合召唤。\r\n●将自己场上的1只怪兽和对手场上的1只表侧表示怪兽作为融合素材除外，将1只“召唤兽”融合怪兽融合召唤。','\r',char(13)),'\n',char(10)),'发动','手牌场上牌组融合','自己对手场上融合','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76348260,'极星天 密米尔','此卡存在于墓地，且我方场上存在有冠有“极星”之名怪兽的场合，可在我方阶段开始时仅１次，从手牌将１张魔法卡送入墓地并发动。特殊召唤此卡。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76352503,'灵道士 姜诗',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己的主要阶段可以发动。从手牌・牌组将1只不死族怪兽送至墓地。\r\n②：此卡被除外的情况下，从自己墓地将1只不死族怪兽除外可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，回到牌组最下面。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76353872,'戒备转换鸟',replace(replace('此卡牌名的①效果１回合只可使用１次。\r\n①：可从手牌舍弃１只除此卡以外的电子界族怪兽并发动。从手牌特殊召唤此卡。\r\n②：１回合１次，我方的电子界族怪兽被选择为攻击对象时可发动。直至该伤害步骤结束时，该怪兽的攻击力、守备力变成原本攻击力的２倍。该怪兽是攻击表示的场合，可进一步将该表示形式变成守备表示。','\r',char(13)),'\n',char(10)),'此卡从手牌特殊召唤','攻击力翻倍','是否变成守备表示？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76359406,'水晶机巧－紫黄特力',replace(replace('协调＋协调以外的怪兽1只以上\r\n①：此卡同步召唤的情况下可以发动。将对手场上被特殊召唤的表侧表示怪兽全部改成守备表示。\r\n②：同步召唤的此卡因战斗・效果被破坏的情况下，以自己墓地同步怪兽以外的1只“水晶机巧”怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76372778,'禁咒仪・幽魂梅洛欧',replace(replace('等级４怪兽×２\r\n①：此卡战斗破坏对手怪兽的伤害计算后，去除此卡的１个超量素材可以发动。破坏的该怪兽不送至墓地而是放回持有者的牌组。','\r',char(13)),'\n',char(10)),'战斗破坏的怪兽返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76375976,'魔钟洞','①：对手场上怪兽的数量比自己场上怪兽多的情况下，对手不可发动怪兽的效果，也不可攻击宣言。②：自己场上怪兽的数量比对手场上怪兽多的情况下，自己不可发动怪兽效果，也不可攻击宣言。③：在自己・对手的结束阶段，双方场上怪兽的数量相同的情况下发动。将此卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76382116,'铁之创王 铁威古斯','此卡名的②效果1回合仅可使用1次。①：“铁之创王 铁威古斯”在自己场上仅可有1只以表侧表示存在。②：解放自己场上任意数量的“创王”怪兽或者是机械族怪兽可以发动。将与解放数量等量的、与被解放怪兽卡名不同的“创王”怪兽或者是机械族怪兽从手牌以守备表示特殊召唤（同名卡最多1张）。此效果在对手回合中也可以发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76384284,'特洛伊的剑斗兽','从我方手牌特殊召唤１只冠有“剑斗兽”之名的怪兽至对手场上。之后，从我方从牌组抽取１张卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76403456,'力量障壁','①：因对手怪兽攻击造成我方受到战斗伤害的伤害计算时可发动。每５００点就从我方牌组的上方将１张卡牌送入墓地，从而使得该战斗中对我方造成的战斗伤害变为０。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76407432,'爆裂反击','①：自己场上存在“／爆裂”怪兽，且怪兽的效果・魔法・陷阱卡发动时可以发动。将该发动无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76416959,'战华之义－关云',replace(replace('此卡名的③效果1回合仅可使用1次。\r\n①：仅有对手场上才存在怪兽的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：只要此卡存在于怪兽区域，对手不可将自己场上的其他“战华”怪兽作为效果的对象。\r\n③：对手场上的怪兽数量多于自己场上的怪兽的情况下，以对手场上的1只怪兽为对象可以发动。将该怪兽破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76419637,'混沌超量 激烈华战舰 手弱女',replace(replace('等级４怪兽×４\r\n对手的结束阶段时，对手的手牌多于自己手牌的情况下发动。对手挑选１张手牌并舍弃。此外，此卡以“烈华炮舰 抚子”为超量素材的情况下，获得以下效果。\r\n●移除此卡的１个超量素材可以发动。给予对手LP场上的卡片数量×３００点伤害。“混沌超量 激烈华战舰 手弱女”的此效果１回合仅可使用１次。','\r',char(13)),'\n',char(10)),'丢弃手牌','伤害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76436988,'闪闪枪兵','对手场上存在有怪兽，且自己场上没有怪兽存在的情况下，此卡可从手牌中特殊召唤。只要此卡以表侧表示存在于场上，自己每次结束阶段受到５００点伤害。','500伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76442347,'子型企鹅','①：反转的此卡被送至墓地的情况下，以“子型企鹅”以外的自己墓地的1只“企鹅”怪兽为对象发动。将该怪兽以表侧攻击表示或里侧守备表示特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76442616,'－英雄－之绊','①：场上有“-英雄”怪兽存在的情况下可以发动。从手牌将2只等级4以下的“元素-英雄”怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76446915,'圆盘魔法师','自己将自己封印在圆盘中，发动攻击时实体就会出现。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76459806,'火山性火箭','此卡召唤、反转召唤、特殊召唤成功时，可从我方牌组、墓地挑选１张冠有“烈焰加农炮”之名的卡牌加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76471944,'超重忍者 猿飞－B',replace(replace('机械族协调＋１只以上协调以外的“超重武者”怪兽\r\n此卡名在规则上也视为“超重武者”卡。①：此卡可在表侧守备表示的状态下攻击。该情况下，将此卡的守备力视为攻击力来进行伤害计算。②：１回合１次，自己的墓地不存在魔法・陷阱卡的情况下，以场上１张魔法・陷阱卡为对象可以发动。将该卡破坏，给予对手５００伤害。此效果在对手回合中也可以发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76473843,'威风阵 天马',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：场上的“威风魔灵”怪兽的攻击力・守备力上升３００。\r\n②：解放自己场上的１只魔法师族・风属性怪兽可以发动。从牌组将等级４以下的１只“威风魔灵”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76500786,'一曲集中',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：自己的连接怪兽与对手怪兽进行战斗的伤害计算时可以发动。该自己的怪兽的攻击力仅在该伤害计算时，上升相当于其连接端的怪兽的等级・阶级合计×４００的数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76504386,'编号39 光之使者 希望皇霍普',replace(replace('等级4怪兽×2\r\n①：此卡不会因与“编号”怪兽以外的怪兽的战斗被破坏。\r\n②：在自己・对手回合中，去除此卡的1个超量素材，以自己场上的1只怪兽为对象可以发动。该怪兽在此回合仅1次，不会因战斗・效果被破坏。\r\n③：此回合的第2次攻击宣言时可以发动。此卡的攻击力上升2500，获得以下效果。\r\n●此卡战斗破坏怪兽并将其送至墓地时可以发动。将该怪兽特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'破坏抗性','攻击力上升','特殊召唤','已得到效果','','','','','','','','','','','','');
INSERT INTO texts VALUES(76504387,'编号39 光之使者 希望皇霍普',replace(replace('等级4怪兽×2\r\n①：此卡不会因与“编号”怪兽以外的怪兽的战斗被破坏。\r\n②：在自己・对手回合中，去除此卡的1个超量素材，以自己场上的1只怪兽为对象可以发动。该怪兽在此回合仅1次，不会因战斗・效果被破坏。\r\n③：此回合的第2次攻击宣言时可以发动。此卡的攻击力上升2500，获得以下效果。\r\n●此卡战斗破坏怪兽并将其送至墓地时可以发动。将该怪兽特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'破坏抗性','攻击力上升','特殊召唤','已得到效果','','','','','','','','','','','','');
INSERT INTO texts VALUES(76512652,'鳄鱼人','拥有智慧且更加狂暴化的鳄鱼。以身上坚硬的鳞片反弹对方的攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76515293,'心镇壶','选择场上２张被盖牌的魔法・陷阱卡发动此卡。只要此卡存在于场上，选择的魔法・陷阱卡不可发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76520646,'无限暗魔',replace(replace('此卡存在于墓地或以表侧表示存在于场上的场合，将被视为通常怪兽。以通常召唤的方式再次召唤场上表侧表示的此卡，此卡将视为效果怪兽并获得以下效果。\r\n●此卡进行攻击宣言时，可变更１只以表侧表示存在于对手场上的怪兽的表示形式。','\r',char(13)),'\n',char(10)),'改变表示形式','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76524506,'花园蔷薇芙萝拉',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的①效果1回合仅可使用1次。\r\n①：以场上的1张场地魔法卡为对象可以发动。将该卡破坏。然后，在其控制者场上将1只“蔷薇衍生物”（植物族・暗・星2・攻/守800）以攻击表示特殊召唤。此回合，自己从额外牌组仅可特殊召唤同步怪兽。\r\n②：在对手的主要阶段可以发动（同一连锁上最多1次）。将包含此卡在内的自己场上的怪兽作为素材进行同步召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76524507,'蔷薇衍生物','由“黑花园”等的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76532077,'无底流沙','每次对手结束阶段发动。破坏场上攻击力最高的怪兽。我方准备阶段时我方手牌为４张或以下的场合，此卡被破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76539047,'猛毒之牙','每次兽族怪兽给予对手玩家战斗伤害，就给予对手生命５００点伤害。','LP伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76543119,'机关傀偶－死之木马',replace(replace('①：只要此卡以表侧表示存在于场上，仅１次可以场上的１只“机关傀偶”怪兽为对象发动。破坏该怪兽。\r\n②：此卡从场上被送入墓地时可发动。从手牌特殊召唤最多２只“机关傀偶”怪兽。','\r',char(13)),'\n',char(10)),'破坏','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76547525,'红莲翼龙',replace(replace('协调＋协调以外的怪兽１只以上\r\n①：只要同步召唤的此卡以表侧表示存在，仅限１次，在自己・对手回合中，场上存在攻击力高于此卡的怪兽的情况下可以发动。将场上攻击力最高的１只怪兽破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76548531,'蛇魔・黑影',replace(replace('此卡名的①③效果1回合仅可各使用1次。\r\n①：自己场上的怪兽，不存在的情况下或均为“黑影”怪兽的情况下可以发动。从手牌将此卡特殊召唤，从牌组将岩石族以外的1只“黑影”怪兽加入手牌。\r\n②：只要此卡存在于怪兽区域，自己从额外牌组仅可特殊召唤“编号”超量怪兽。\r\n③：要超量召唤需以3只以上怪兽作为素材的“编号”超量怪兽的情况下，此卡可作为2只的超量素材。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76552147,'异次元赛马',replace(replace('①：以下任一怪兽以表侧表示存在于自己场上的情况下，以场上的１张卡为对象可以发动。将该卡除外。\r\n●使用通常怪兽仪式召唤的怪兽\r\n●以通常怪兽作为素材融合・同步・超量・连接召唤的怪兽','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76573247,'外星人侵略者','１回合１次，可指定１处未使用的相邻怪兽区并发动。将我方场上的此卡移动至指定区域。与此卡相同纵列不存在有对手卡牌的场合，此卡可直接攻击对手玩家。','移动位置','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76587747,'时潜怪盗・逆跳','此卡名的卡1回合仅可发动1张。①：自己场上有“时潜怪盗”超量怪兽存在、魔法・陷阱卡发动时可以发动。将该发动无效，将该卡重叠在自己场上的“时潜怪盗”超量怪兽下面作为超量素材。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76589546,'溢出龙',replace(replace('此卡名的效果１回合仅可使用１次。\r\n①：场上的怪兽因效果被破坏时可以发动。从手牌将此卡特殊召唤。场上２只以上的怪兽因效果被破坏时发动的情况下，进而可将１只“溢出衍生物”（龙族・暗・星１・攻／守０）特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'特殊召唤','是否特殊召唤衍生物？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76589547,'溢出衍生物','由“溢出龙”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76589815,'燃烧拳斗士 作弊拳击委员',replace(replace('等级３怪兽×２\r\n只要此卡以表侧表示存在于场上，具有攻击可能的对手怪兽就必须进行攻击。此外，我方场上存在有除此卡以外冠有“燃烧拳斗士”之名的怪兽的场合，对手不可以此卡为攻击对象。我方除此卡以外冠有“燃烧拳斗士”之名的怪兽进行战斗的攻击宣言时，可移除此卡的２个超量素材并发动。确认对手手牌，并从中挑选１张魔法卡盖牌至我方场上。','\r',char(13)),'\n',char(10)),'确认手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76593718,'强欲之瓮',replace(replace('此卡名的效果１回合仅可使用１次。\r\n①：此卡反转的情况下发动。分别适用以下效果。\r\n●从自己的牌组上面翻开卡，数量最多为对手场上的卡的数量，从其中挑选１张加入手牌，剩余的送至墓地。\r\n●从自己的额外牌组将怪兽送至墓地，数量最多为对手场上被从额外牌组特殊召唤的怪兽的数量。','\r',char(13)),'\n',char(10)),'','请选择要翻开的卡的数量','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76614003,'黑暗维修员','此卡从我方场上被送入墓地时，确认我方牌组最上方的卡牌并将其返回至牌组的最上或最下方。','确认牌组','回到牌组最上面','回到牌组最下面','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76614340,'宝石骑士・红玉',replace(replace('“宝石骑士・石榴石”＋“宝石骑士”怪兽\r\n此卡从额外牌组仅可通过以上述卡作为融合素材的融合召唤来特殊召唤。\r\n①：1回合1次，解放自己场上1只其他的表侧表示的“宝石”怪兽可以发动。此卡的攻击力直至回合结束时为止，上升相当于所解放怪兽的攻击力的数值。\r\n②：此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。','\r',char(13)),'\n',char(10)),'攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76615300,'火灵媒师 希塔',replace(replace('此卡名在规则上也视为“灵使”卡。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：从手牌将此卡和1只炎属性怪兽舍弃可以发动。从牌组将攻击力高于此卡以外的所舍弃怪兽的1只炎属性怪兽加入手牌。此效果发动后，直至回合结束时为止，自己不可发动炎属性以外的怪兽的效果。\r\n②：自己的炎属性怪兽因战斗被破坏时可以发动。从手牌将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76630812,'天使与魔鬼的骰子',replace(replace('①：掷2次骰子，此回合中，分别适用以下效果。\r\n●记载有“时间黑魔术师”卡名的、自己场上的怪兽的攻击力・守备力上升掷出的数字合计×200的数值。\r\n●对手场上的怪兽的攻击力・守备力下降掷出的数字合计×200的数值。\r\n②：此卡存在于墓地的状态下，对手将怪兽召唤・特殊召唤的情况下，将此卡除外，以其中1只为对象可以发动。掷2次骰子，掷出的数字合计在6以上的情况下，将对象怪兽破坏。','\r',char(13)),'\n',char(10)),'发动','掷骰子','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76634149,'海龙神','被称为海洋霸主的海中巨龙，能掀起海啸吞噬一切。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76636978,'星尘龙－牺牲者圣域',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的①②效果1回合仅可各使用1次，不可在同一连锁上发动。\r\n①：应对自己的效果的发动，对手连锁发动魔法・陷阱・怪兽的效果时，解放此卡可以发动。将该对手的效果的发动无效并破坏。\r\n②：在自己的怪兽被解放的自己・对手回合中，将墓地的此卡除外可以发动。从额外牌组将1只“星尘”同步怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'发动无效','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76636979,'星尘龙－牺牲者圣域',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的①②效果1回合仅可各使用1次，不可在同一连锁上发动。\r\n①：应对自己的效果的发动，对手连锁发动魔法・陷阱・怪兽的效果时，解放此卡可以发动。将该对手的效果的发动无效并破坏。\r\n②：在自己的怪兽被解放的自己・对手回合中，将墓地的此卡除外可以发动。从额外牌组将1只“星尘”同步怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'发动无效','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76641981,'TG1－EM1','①：以对手场上的1只怪兽和自己场上的1只“T.G.”怪兽为对象可以发动。将该怪兽的控制权交换。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76647978,'超越融合','应对此卡的发动，不可发动卡的效果。①：支付２０００LP可以发动。将由融合怪兽卡决定的２只融合素材怪兽从自己场上送至墓地，将该１只融合怪兽从额外牌组融合召唤。②：将墓地的此卡除外，以用此卡效果融合召唤的１只怪兽为对象可以发动。将用于该怪兽融合召唤的一组融合素材怪兽从自己的墓地特殊召唤。以此效果特殊召唤的怪兽的攻击力・守备力变为０，效果无效化。','融合召唤','融合素材特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76650663,'正义盟军 遮光吸收者','在伤害计算后使得与此卡战斗过的光属性怪兽的效果无效。','效果无效化','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76660178,'大海的传说－渔夫',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：对手发动场上的怪兽的效果的情况下，或对手怪兽攻击宣言时，如果场上存在除“大海的传说－渔夫”以外的、记载有“时间黑魔术师”卡名的卡或“海”则可以发动。从手牌将此卡特殊召唤。\r\n②：此卡特殊召唤的情况下，以对手场上的1只怪兽为对象可以发动。将该怪兽破坏。在此回合的结束阶段，场上的此卡将回到手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76660409,'灵摆回归','①：我方灵摆区存在有２张卡牌的场合，可以我方墓地的２只怪兽为对象发动，该两只怪兽持有能通过该灵摆刻度灵摆召唤的等级。将该怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76666602,'吞喰圣痕之龙',replace(replace('“阿尔白斯之落胤”＋光・暗属性怪兽＋效果怪兽\r\n此卡名的①③效果1回合仅可各使用1次。\r\n①：此卡特殊召唤的情况下可以发动。将自己・对手的、墓地・除外状态的合计最多2张卡放回牌组。\r\n②：只要自己或对手的、场上或墓地存在“艾克利西亚”怪兽，此卡的攻击力上升500，不受此卡以外的效果影响。\r\n③：在此卡被送至墓地的回合的结束阶段可以发动。从牌组将1张“教导”卡或“铁兽”卡加入手牌。','\r',char(13)),'\n',char(10)),'回到牌组','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76672730,'暗黑界之文殿',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：在自己的主要阶段可以发动。从手牌挑选１只“暗黑界”怪兽舍弃，自己场上的所有“暗黑界”怪兽的攻击力直至回合结束时为止上升相当于以此效果舍弃的怪兽的等级×１００的数值。\r\n②：原本种族为恶魔族的怪兽因“暗黑界”卡的效果或对手的效果从自己的手牌被舍弃的情况下可以发动（在伤害步骤也可以发动）。挑选１张自己的手牌舍弃。然后，自己从牌组抽２张。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76683171,'异虫阿格理','释放此卡并冠有“异虫”之名的爬虫类族怪兽的上级召唤成功时，可将我方墓地的此卡以攻击表示特殊召唤至对手场上。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76685519,'幻变骚灵・键盘侧录难近母',replace(replace('“幻变骚灵”怪兽2只\r\n①：此卡以外的自己的“幻变骚灵”怪兽给予对手战斗伤害时，以对手墓地的1只怪兽为对象可以发动。将该怪兽特殊召唤至此卡连接端的自己场上。以此效果特殊召唤的怪兽仅可在此卡攻击宣言过的回合攻击。②：此卡因战斗被破坏的情况下，以自己墓地的1张“幻变骚灵”卡为对象可以发动。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76704943,'八岐大蛇的绘卷','由绘卷中的龙实体化后进行攻击，守备力相当低。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76714458,'痛魂咒术','①：对手发动对我方造成伤害的卡牌效果时可发动此卡。令对手代替我方承受该效果对我方造成的效果伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76721030,'暴君的暴言','可释放我方场上的２只怪兽并发动。只要此卡存在于场上，就不可发动在双方手牌及场上发动的怪兽效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76722334,'扭蛋魔壳',replace(replace('此卡名的①②③效果1回合1次，仅可使用其中1个。\r\n①：此卡被解放的情况下可以发动。自己抽1张。\r\n②：此卡作为融合・同步・连接召唤的素材，且被送至墓地的情况下或被除外的情况下可以发动。自己抽1张。\r\n③：超量素材的此卡为发动超量怪兽的效果被去除的情况下可以发动。自己抽1张。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76725398,'巳剑之勾玉',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：在自己・对手的主要阶段，可从以下效果中选择1个发动。\r\n●解放自己场上的1只爬虫类族怪兽，以对手场上的1张表侧表示卡为对象可以发动。将该卡破坏。\r\n●为使合计等级达到仪式召唤的怪兽的等级以上，解放自己场上的怪兽，从手牌将1只“巳剑”仪式怪兽仪式召唤。','\r',char(13)),'\n',char(10)),'发动','破坏','仪式召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76728962,'亡命左轮枪龙',replace(replace('①：我方场上的机械族、暗属性怪兽因战斗、效果被破坏的场合可发动。从手牌中特殊召唤此卡。\r\n②：１回合１次，可在我方、对手的战斗阶段发动。掷３次硬币。挑选最多与掷出的正面次数相同的表侧表示怪兽破坏。３次均是正面的场合，我方再从牌组抽取１张卡牌。发动此效果的回合，此卡不可攻击。\r\n③：此卡被送入墓地的场合可发动。从牌组将１只持有掷硬币效果的等级７或以下的怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76751255,'点火骑士・再上膛',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：将手牌任意数量的灵摆怪兽出示给对手并放回牌组。然后，自己抽所放回数量＋１张。此卡发动后，直至回合结束时为止自己不可以卡的效果抽牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76754619,'金字塔力量',replace(replace('可从以下效果选择１个发动。\r\n●直至回合结束时，我方场上所有怪兽的攻击力上升２００点。\r\n●直至回合结束时，我方场上所有怪兽的守备力上升５００点。','\r',char(13)),'\n',char(10)),'攻击力上升200','守备力上升500','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76763417,'电子体操员','①：１回合１次，可舍弃１张手牌，并以对手场上１只表侧攻击表示怪兽为对象发动。破坏该对手的表侧攻击表示怪兽。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76766706,'混沌之种','若我方场上存在光属性以及暗属性怪兽的场合，可选择我方被除外的１只光属性或暗属性战士族怪兽并发动。被选择的怪兽加入手牌。“混沌之种”１回合只可发动１张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76774528,'废铁龙',replace(replace('协调＋协调以外的怪兽1只以上\r\n①：1回合1次，以自己及对手场上的各1张卡为对象可以发动。将该卡破坏。\r\n②：此卡被对手破坏并被送至墓地的情况下，以同步怪兽以外的、自己墓地的1只“废铁”怪兽为对象发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'破坏','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76775123,'巡逻机器人','只要此卡以表侧表示存在于场上，我方的准备阶段时可确认对手场上被盖牌的１张卡牌。','确认盖卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76782778,'龙女仆・蔼儿地',replace(replace('此卡名的①③效果1回合仅可各使用1次。\r\n①：在自己・对手回合中，从手牌将此卡舍弃可以发动。从手牌将1只等级4以下的“龙女仆”怪兽特殊召唤。\r\n②：只要自己场上存在融合怪兽，此卡就不会因效果被破坏。\r\n③：在自己・对手的战斗阶段结束时可以发动。将此卡放回手牌，从手牌将1只等级2的“龙女仆”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76792184,'混沌－黑魔术仪式','“黑混沌之魔导”降临所必须。①：为使合计等级为8以上，解放自己手牌・场上的怪兽，从手牌将“黑混沌之魔导”仪式召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76794549,'宙读阵魔术士',replace(replace('←1 【灵摆】 1→\r\n此卡名的灵摆效果１回合仅可使用１次。①：在自己的主要阶段可以发动。破坏此卡，从手牌・牌组挑选１只“星读的魔术师”，放在自己的灵摆区域或特殊召唤。\r\n【怪兽效果】\r\n①：自己场上的卡因战斗・效果被破坏的情况下可以发动。从手牌将此卡特殊召唤。然后，可挑选１只在此回合被破坏的自己或对手的怪兽，将１只该怪兽的同名怪兽从牌组加入手牌。②：将自己手牌・场上・墓地的“灵摆龙”、“超量龙”、“同步龙”、“结合龙”怪兽各１只和场上的此卡除外可以发动。将１只“霸王龙扎克”视为融合召唤从额外牌组特殊召唤。','\r',char(13)),'\n',char(10)),'此卡破坏','灵摆区域放置','特殊召唤','此卡从手牌特殊召唤','是否把破坏怪兽的同名怪兽加入手牌？','融合召唤「霸王龙扎克」','请选择1只「星读的魔术师」','请选择这个回合被破坏的1只怪兽','','','','','','','','');
INSERT INTO texts VALUES(76798740,'仇尸・突击','此卡名的卡１回合仅可发动１张。①：从手牌及自己场上的表侧表示怪兽中，将１只不死族怪兽送至墓地可以发动。从牌组将１只“仇尸”怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76806714,'龟的誓言','用于召唤“蟹龟”。必须从手牌・我方场上解放合计等级达到８以上的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76812113,'神鹰女郎','有着人身并长有翅膀的兽。其舞姿优美华丽，其攻击凌厉无比。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76815942,'抒情歌鸲－独行夜莺',replace(replace('“抒情歌鸲-聚合夜莺”＋“抒情歌鸲”怪兽\r\n①：此卡以原本卡名包含“抒情歌鸲”的超量怪兽作为素材融合召唤成功的情况下可以发动。此卡等级上升相当于该怪兽原先拥有的超量素材数量。②：此卡的攻击力上升相当于此卡等级×500的数值，不受其他卡的效果影响。③：1回合1次，在自己的主要阶段可以发动。给予对手相当于此卡等级×500数值的伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76821171,'华耳琴璃之异神－誓拉尔梅',replace(replace('效果怪兽１只\r\n此卡的连接召唤仅可在自己灵摆区域的天使族怪兽卡的响鸣计数物为３个以上的情况下进行，且自己１回合仅可特殊召唤１次“华耳琴璃之异神－誓拉尔梅”。\r\n①：此卡连接召唤的情况下，以对手场上的怪兽为对象可以发动，数量最多为自己的灵摆区域的响鸣计数物的数量。将该怪兽破坏。\r\n②：去除自己灵摆区域的３个响鸣计数物可以发动。此回合，此卡在１次战斗阶段中可攻击３次。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76823930,'血肉的代价',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己的主要阶段支付1000LP可以发动。此回合，自己可进行最多3次通常召唤。\r\n②：在对手的战斗阶段支付500LP可以发动。进行1只怪兽的召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76830505,'无限起动 暴虐推土机','此卡名的①②效果１回合仅可各使用１次。①：解放自己场上的１只机械族・地属性怪兽可以发动。将此卡从手牌以守备表示特殊召唤。②：此卡从手牌特殊召唤成功的情况下可以发动。从牌组将“无限起动 暴虐推土机”以外的１只“无限起动”怪兽的效果无效并以守备表示特殊召唤。此效果发动后，直至回合结束时为止，自己仅可特殊召唤机械族・地属性怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76833149,'梅尔菲・玛咪',replace(replace('兽族等级2怪兽×2只以上\r\n①：在每个自己・对手回合中1次，可以发动。从自己手牌・场上（表侧表示）将1只兽族怪兽作为此卡的超量素材。\r\n②：根据此卡持有的超量素材数量，此卡获得以下效果。\r\n●3个以上：此卡不会因战斗被破坏。\r\n●4个以上：因此卡的战斗对自己造成的战斗伤害变为0。\r\n●5个以上：此卡与攻击表示怪兽进行战斗的攻击宣言时可以发动。给予对手相当于该攻击表示怪兽攻击力数值的伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76840111,'霸王天龙之魂',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：解放自己场上原本攻击力为２５００的１只魔法师族灵摆怪兽可以发动。将自己的手牌・牌组・额外牌组・场上・墓地的怪兽作为融合素材除外，将１只“霸王龙扎克”融合召唤。除非自己除外状态的“灵摆龙”、“超量龙”、“同步龙”、“结合龙”怪兽各存在１只以上，否则以此效果特殊召唤的怪兽的效果无效化。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76848240,'绝对不可侵犯领域','我方准备阶段时可发动。从手牌中舍弃１张牌卡。对手在下一对手回合不可通常召唤、特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76862289,'八俣大龙','此卡不可特殊召唤。①：此卡给予对手战斗伤害的情况下发动。自己从牌组抽牌，直至手牌变为５张。②：此卡召唤・反转的回合的结束阶段发动。将此卡放回持有者的手牌。','返回手牌','抽牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76865611,'变形斗士・手电筒',replace(replace('此卡依据此卡的表示形式获得以下效果。\r\n●攻击表示：因对手卡牌效果对我方造成的效果伤害将由对手代替承受。\r\n●守备表示：此卡因战斗被破坏并送入墓地时，因此回合战斗而造成的对我方的战斗伤害变成０。','\r',char(13)),'\n',char(10)),'战斗伤害变成0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76869711,'六花来来',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：自己场上存在“六花”怪兽的情况下可以发动。从牌组将１张“六花”魔法・陷阱卡，放置在自己的魔法与陷阱区域。此效果发动后，直至回合结束时为止自己仅可特殊召唤植物族怪兽。\r\n②：１回合１次，自己为发动“六花”卡的效果而要解放自己场上的植物族怪兽的情况下，作为自己场上１只植物族怪兽的代替，可解放对手场上的１只表侧表示怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76871889,'仇尸・厄夜','此卡名的①效果１回合仅可使用１次。①：在自己的主要阶段舍弃１张手牌可以发动。从牌组将１只“仇尸”怪兽加入手牌。②：以自己的“仇尸”怪兽的攻击破坏对手怪兽时，从自己的墓地将１只“仇尸”怪兽除外可以发动。该怪兽可继续攻击对手怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76891401,'神海龙基希尔诺顿',replace(replace('协调＋协调以外的等级３怪兽１只\r\n场上表侧表示的等级３或以下怪兽被送入墓地时，直至回合结束时，此卡的攻击力变成３０００。','\r',char(13)),'\n',char(10)),'攻击力变成3000','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76895648,'危险机器 第６型',replace(replace('每次我方的准备阶段掷一次股子。适用掷出点数的效果。\r\n●１：我方挑选１张手牌并舍弃。\r\n●２：对手挑选１张手牌并舍弃。\r\n●３：我方抽取１张卡牌。\r\n●４：对手抽取１张卡牌。\r\n●５：挑选对手场上的１只怪兽破坏。\r\n●６：破坏此卡。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76902476,'幻兽机 龟式追踪机','此卡的等级上升相当于自己场上“幻兽机衍生物”等级合计的数值。只要自己场上有衍生物存在，此卡不会因战斗及效果被破坏。此外，只要此卡以表侧表示存在于场上，１回合１次，自己场上的“幻兽机衍生物”不会因战斗被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76908448,'宝石骑士・水晶','能优化水晶力量，将其转化为战斗力，是宝石骑士的上级战士。其高超的战斗力在敌人面前占据压倒性优势。然而，因经常感觉到优化存在局限性，故很重视与伙伴之间的团结关系。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76909279,'激昂的米诺陶洛斯','①：只要此卡存在于怪兽区域，我方的兽族、兽战士族、鸟兽族怪兽攻击了守备表示怪兽的场合，给予对手相当于攻击力超过该守备力的战斗伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76913983,'黑羽－武装之翼',replace(replace('“黑羽”协调＋协调以外的怪兽1只以上\r\n①：此卡攻击守备表示怪兽的伤害步骤期间，此卡的攻击力上升500。\r\n②：此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76922029,'首领扎鲁格',replace(replace('此卡给予对手生命战斗伤害时，可从以下效果选择１个发动。\r\n●随机挑选１张对手的手牌并舍弃。\r\n●从对手牌组的上面将２张卡牌送入墓地。','\r',char(13)),'\n',char(10)),'选择一个效果发动','对手随机丢弃1张手牌。','对手的牌组最上面的2张卡送至墓地。','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76925842,'暗黑珀耳修斯','此卡的攻击力上升相当于我方墓地的暗属性怪兽数量×１００点。此卡因战斗破坏对手怪兽时，可将我方墓地的１只暗属性怪兽从游戏中除外并发动。从我方牌组抽取１张卡牌。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76930964,'黄昏的忍者将军－月牙',replace(replace('此卡可解放１只“忍者”怪兽并上级召唤。\r\n“黄昏的忍者将军－月牙”的效果１回合只可使用１次。\r\n①：此卡以攻击表示存在于场上的场合，可以我方墓地２只除“黄昏的忍者将军－月牙”以外的“忍者”怪兽为对象发动。将此卡变成守备表示，并特殊召唤对象怪兽。','\r',char(13)),'\n',char(10)),'把1只「忍者」怪兽解放作上级召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76937326,'大薰风 飞翼心皮莉卡',replace(replace('协调＋１只以上协调以外的“薰风”怪兽\r\n自己１回合仅可特殊召唤“大薰风 飞翼心皮莉卡”１次。\r\n①：此卡同步召唤成功的情况下可以发动。从手牌及牌组将“薰风”怪兽各１只效果无效并特殊召唤，仅以该２只为素材将１只“薰风”同步怪兽同步召唤。此回合，自己仅可特殊召唤风属性怪兽。\r\n②：只要此卡存在于怪兽区域，自己场上的其他“薰风”同步怪兽不会成为对手效果的对象。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76948970,'巳剑之皇子 小碓',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次，且②效果1回合仅可使用1次。\r\n①：此卡可通过解放手牌的1只其他的爬虫类族怪兽和对手场上的1只怪兽来从手牌特殊召唤。以此方法特殊召唤过的余下本回合，自己仅可特殊召唤爬虫类族怪兽，且不可发动爬虫类族以外的怪兽的效果。\r\n②：此卡被解放的情况下可以发动。挑选自己的1张手牌舍弃，将此卡加入手牌。','\r',char(13)),'\n',char(10)),'','回到手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76972801,'我我我防御','①：自己场上存在2只以上“我我我”怪兽的情况下可以发动。此回合中，自己场上的怪兽不会因战斗・效果被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76978105,'邪恶－英雄 地狱骑士',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从自己牌组・墓地将1张“黑暗结合”加入手牌。\r\n②：从自己墓地将4只怪兽和此卡除外可以发动。从牌组将1张“超融合”放置在自己场上。直至对手回合结束时为止，自己仅可特殊召唤“－英雄”怪兽，且自己可通过“黑暗结合”以外的效果，来融合召唤原先仅可以“黑暗结合”的效果特殊召唤的融合怪兽。','\r',char(13)),'\n',char(10)),'检索「黑暗结合」','放置「超融合」','','「邪恶－－英雄 地狱苍骑」效果适用中','','','','','','','','','','','','');
INSERT INTO texts VALUES(76981308,'与梅尔菲瞪瞪眼','此卡名的①效果１回合仅可使用１次。①：将手牌的１只兽族怪兽向对手出示可以发动。从自己的牌组・墓地挑选１只卡名与其不同的“梅尔菲”怪兽加入手牌，将所出示的怪兽放回牌组最下面。②：在对手的战斗阶段开始时可以发动。将手牌中的任意数量的“梅尔菲”怪兽向对手出示，并仅在战斗阶段期间公开。③：对手场上的怪兽的攻击力下降相当于以此卡②效果公开中的怪兽的攻击力・守备力的合计数值。','','','请选择要公开的怪兽','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76986005,'电子麒麟','可解放此卡并发动。直至回合结束时，我方受到的效果伤害变为０。','效果伤害免疫','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(76990617,'幻奏音女 索娜塔',replace(replace('①：自己场上存在“幻奏”怪兽的情况下，此卡可从手牌中特殊召唤。\r\n②：只要特殊召唤的此卡存在于怪兽区域，自己场上的天使族怪兽的攻击力・守备力上升５００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77007920,'激光炮铠甲','仅限装备昆虫族怪兽。令装备怪兽的攻击力和守备力上升３００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77013169,'超重武者剑－999',replace(replace('①：此卡召唤或特殊召唤成功时可发动。改变此卡的战斗状态。\r\n②：我方场上的“超重武者”怪兽和对手怪兽战斗并进行伤害计算后发动。将该对手怪兽的攻击力和守备力变为０。','\r',char(13)),'\n',char(10)),'改变表示形式','攻守变换','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77027445,'海神之力','仅限装备水族怪兽。令１只装备怪兽的攻击力和守备力上升３００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77036039,'爆裂佣兵','①：1回合1次，从自己手牌・墓地将1张“爆裂模式”放回牌组，以对手场上的1张魔法・陷阱卡为对象可以发动。将该对手的卡破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77044671,'金字塔龟','①：此卡因战斗被破坏并被送至墓地时可以发动。从牌组将１只守备力２０００以下的不死族怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77058170,'降频承办机',replace(replace('效果怪兽2只\r\n①：1回合1次，以此卡连接端的1只表侧表示怪兽，和对手场上的1只表侧表示怪兽为对象可以发动。该对手怪兽的攻击力直至回合结束时为止，下降相当于作为对象的连接端的怪兽的攻击力的数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77060848,'极星灵 黑暗精灵','此卡召唤成功时可发动。从我方墓地选择１只冠有“极星”之名的怪兽返回至手牌。','加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77066768,'卡片扫描者',replace(replace('①：１回合１次，宣言１个卡的种类（怪兽・魔法・陷阱）可以发动。双方玩家相互确认自身牌组最下面的卡，是所宣言的种类的情况下，将该卡加入自身的手牌。不是的情况下，将所确认的卡放在自身牌组最上面。\r\n②：魔法与陷阱区域的表侧表示的此卡因对手的效果被破坏的情况下可以发动。对手挑选自身的１张手牌，放回牌组最下面。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77075360,'废品增速者',replace(replace('“同步士”协调＋协调以外的怪兽1只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡同步召唤的情况下可以发动（发动此效果的回合中，自己从额外牌组仅可特殊召唤同步怪兽）。从牌组将“同步士”协调尽可能地以守备表示特殊召唤（同等级最多1只）。\r\n②：在此回合中同步召唤的此卡与怪兽进行战斗的攻击宣言时可以发动。此卡的攻击力直至回合结束时为止变为原本攻击力的两倍。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77084837,'因幡之白兔','此卡不可特殊召唤。召唤・反转此卡的回合的结束阶段时回到持有者的手牌中。对手场上有怪兽存在的场合，此卡只可直接攻击对手玩家。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77087109,'时钟共鸣者','①：守备表示的此卡1回合仅1次，不会因战斗・效果被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77092311,'毒之魔妖－土蜘蛛',replace(replace('协调＋协调以外的怪兽１只以上\r\n此卡名的②③效果１回合仅可各使用１次。\r\n①：“毒之魔妖－土蜘蛛”在自己场上仅可有１张以表侧表示存在。\r\n②：此卡存在于墓地，且自己原本等级为７的同步怪兽因战斗或对手的效果被破坏的情况下可以发动。从自己的墓地将１只其他的不死族怪兽除外，将此卡特殊召唤。\r\n③：此卡从墓地特殊召唤的情况下可以发动。双方各自从自身的牌组上面将３张卡送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77098449,'银河波动','每次自己超量召唤成功时，给予对手LP５００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77102944,'洗涤机块 洗衣龙',replace(replace('1只“机块”怪兽\r\n此卡在其被连接召唤的回合中不可当做连接素材使用。\r\n①：在此卡的战斗中发生的互相的战斗伤害变为0。\r\n②：1个回合1次，处于相互连接状态的此卡与对手怪兽进行战斗，计算伤害值后可以发动。除外该对手怪兽。\r\n③：1个回合1次，未处于相互连接状态的此卡与对手怪兽进行战斗，计算伤害值后可以发动。破坏该对手怪兽，给对手的伤害值为该怪兽原本的攻击力数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77103950,'壹世坏・佩尔雷诺','此卡名的卡１回合仅可发动１张，此卡名的③效果１回合仅可使用１次。①：作为此卡发动时的效果处理，可从牌组将１只“泪冠哀歌”怪兽或“维萨思・史塔弗罗斯特”加入手牌。②：自己场上的融合怪兽及“泪冠哀歌”怪兽的攻击力上升５００。③：自己场上・墓地的“泪冠哀歌”怪兽被放回牌组・额外牌组的情况下，以场上的１张卡为对象可以发动。将该卡破坏。','是否从牌组把怪兽加入手牌？','场上卡破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77116346,'机动雾龙・充能',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：作为此卡发动时的效果处理，从牌组将１只“机动雾龙”怪兽加入手牌。\r\n②：１回合１次，“机动雾龙”灵摆怪兽卡从场上以表侧加入自己的额外牌组的情况下发动。将其中的１张加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77121851,'暗黑之蝎尾狮','在此卡被送至墓地的回合的结束阶段时，从自己的手牌・场上将１只兽族・兽战士族・鸟兽族怪兽送往墓地可以发动。从墓地将此卡特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77124096,'黑暗接触',replace(replace('①：可从以下效果中选择1个发动（此卡名的以下效果1回合仅可各选择1次）。\r\n●将自己场上・墓地・除外状态的怪兽作为融合素材放回牌组，将1只仅可以“黑暗结合”的效果特殊召唤的融合怪兽，视为通过“黑暗结合”来融合召唤。\r\n●从牌组将1张“霸王城”或“黑暗结合”加入手牌。','\r',char(13)),'\n',char(10)),'发动','当作用「黑暗结合」融合召唤','检索','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77133792,'磁石转换',replace(replace('①：以自己墓地最多3只等级4以下的“磁石战士”怪兽为对象可以发动。将该怪兽加入手牌。\r\n②：从墓地将不是在此回合被送至墓地的此卡除外，以自己除外状态的1只等级4以下的“磁石战士”怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77135531,'龙之尖兵','可将手牌中的１只龙族怪兽送入墓地，令此卡的攻击力上升３００点。我方场上的此卡因对手卡牌的效果而被送入墓地时，可特殊召唤我方或对手墓地中的１只龙族通常怪兽。','攻击上升','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77150143,'十二兽 午剑',replace(replace('①：此卡召唤・特殊召唤的情况下可以发动。从手牌挑选1张“十二兽”卡舍弃，自己抽1张。\r\n②：持有此卡作为素材的、原本种族为兽战士族的超量怪兽获得以下效果。\r\n●此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。','\r',char(13)),'\n',char(10)),'从手牌丢弃1张「十二兽」卡，自己从牌组抽1张','穿刺伤害（十二兽 午剑）','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77152542,'黑羽－沙尘之哈马丹',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次。\r\n①：自己场上存在“黑羽－沙尘之哈马丹”以外的“黑羽”怪兽的情况下，此卡可从手牌特殊召唤。\r\n②：此卡召唤・特殊召唤时，以自己场上的1只其他的“黑羽”怪兽为对象可以发动。此卡的等级上升相当于该怪兽等级的数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77153811,'仪式魔人诅咒魔法师','进行仪式召唤的场合，可作为该仪式召唤必要等级数值的１只怪兽，将墓地的此卡从游戏中除外。只要在仪式召唤中使用此卡的仪式怪兽以表侧表示存在于场上，同步怪兽的效果被无效化。','「仪式魔人诅咒魔法师」效果适用中','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77157846,'暗翳之信仰者 朦胧裘德',replace(replace('←11 【灵摆】 11→\r\n此卡名的②灵摆效果1回合仅可使用1次。\n①：自己仅可灵摆召唤灵摆怪兽。此效果不会被无效化。\n②：攻击力1000以下的怪兽被特殊召唤的情况下可以发动。将此卡放回手牌。\r\n【怪兽效果】\r\n此卡名的①②怪兽效果1回合仅可各使用1次。\n①：此卡存在于手牌，且自己的灵摆区域有卡存在的情况下可以发动。将此卡特殊召唤。\n②：支付1000LP可以发动。将自己手牌・场上（表侧表示）的1张灵摆怪兽卡破坏。然后，可从牌组将1只灵摆怪兽以表侧加入额外牌组。','\r',char(13)),'\n',char(10)),'','回到手牌','特殊召唤','破坏','是否把卡加入额外牌组？','请选择加入额外牌组的卡','','','','','','','','','','');
INSERT INTO texts VALUES(77189532,'枪弹代码者',replace(replace('此卡名的①③效果１回合仅可各使用１次。\r\n①：在要将自己场上的电子界族怪兽作为“码语者”怪兽的连接素材的情况下，手牌的此卡也可一起作为连接素材。\r\n②：将此卡使用于“枪管”怪兽的连接召唤的情况下，此卡的种族视为龙族。\r\n③：在要将自己场上的此卡作为“枪管”怪兽的连接素材的情况下，手牌的最多１只暗属性怪兽也可一起作为连接素材。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77202120,'强袭同步士',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己的主要阶段可以发动。从手牌将此卡特殊召唤。然后，自己受到700伤害。只要以此效果特殊召唤的此卡以表侧表示存在于怪兽区域，自己从额外牌组仅可特殊召唤同步怪兽。\r\n②：自己场上表侧表示的龙族同步怪兽被解放的情况下或被除外的情况下，将墓地的此卡除外，以该1只怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77205367,'混沌编号96 黑色风暴',replace(replace('暗属性等级３怪兽×４\r\n①：此卡不会因战斗被破坏，因此卡的战斗产生的对自己的战斗伤害对手也将承受。\r\n②：此卡有“编号96 黑色迷雾”在作为超量素材的情况下，获得以下效果。\r\n●此卡与对手怪兽进行战斗的攻击宣言时１次，去除此卡的１个超量素材可以发动。将该对手怪兽的攻击力改成０，此卡的攻击力上升相当于该对手怪兽原本攻击力的数值。','\r',char(13)),'\n',char(10)),'攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77207191,'巴风特','①：此卡召唤・反转召唤时可以发动。从牌组将１只“幻兽王 加赛尔”加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77229910,'变形斗士・防护罩','破坏我方场上冠有“变形斗士”之名怪兽的魔法、陷阱卡发动时可发动。使该发动无效并破坏。进一步从牌组将１张冠有“变形斗士”之名的卡牌加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77235086,'电子天使－弁天－',replace(replace('以“机械天使的仪式”降临\r\n①：此卡战斗破坏怪兽并将其送至墓地的情况下发动。给予对手相当于该怪兽原本守备力数值的伤害。\r\n②：此卡被解放的情况下可以发动。从牌组将１只天使族・光属性怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77252217,'电动刃虫','此卡进行战斗的场合，在伤害步骤结束时对手抽取１张卡牌。','对手抽1张卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77297908,'魔界剧场“幻想剧院”','此卡名的①②效果1回合仅可各使用1次。①：将手牌中1只“魔界剧团”灵摆怪兽与1张“魔界剧本”魔法卡出示给对手可以发动。将1张与所出示魔法卡的卡名不同的“魔界剧本”魔法卡从牌组加入手牌。②：只要灵摆召唤的“魔界剧团”灵摆怪兽存在于自己场上，将对手发动的怪兽效果变为“挑选1张放置在对手场上的魔法・陷阱卡破坏”。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77307161,'淘气仙星・绽放金雀儿',replace(replace('等级２以下的“淘气仙星”怪兽１只\r\n此卡名的②效果１回合仅可使用１次。\r\n①：此卡连接召唤的情况下可以发动。对手抽１张。\r\n②：此卡连接端的表侧表示的“淘气仙星”怪兽因战斗・效果被破坏的情况下可以发动。给予对手相当于对手手牌数量×２００的伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77312273,'混沌壳','此卡不可通常召唤，仅可以卡的效果特殊召唤。此卡名的①②效果１回合仅可各使用１次。①：从自己的手牌・墓地将１只光属性怪兽除外可以发动。从手牌将此卡特殊召唤。此回合，自己从额外牌组仅可特殊召唤光・暗属性的同步怪兽。②：此卡特殊召唤成功的情况下，以自己１只被除外的“混沌核”为对象可以发动。将该怪兽特殊召唤。③：表侧表示的此卡从场上离开的情况下，将其除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77313225,'白森的魔性 露西耶拉',replace(replace('协调＋协调以外的怪兽１只以上\r\n此卡名的①效果１回合仅可使用１次。\r\n①：此卡特殊召唤的情况下，从自己的手牌・场上将１张魔法・陷阱卡送至墓地可以发动。从牌组将１张“白森”卡或１只魔法师族・光属性怪兽加入手牌。\r\n②：只要此卡存在于怪兽区域，自己场上的幻想魔族・魔法师族同步怪兽的攻击力上升５００，不会因对手的效果被破坏。','\r',char(13)),'\n',char(10)),'牌组检索','攻击力上升并破坏耐性','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77330185,'XX－军刀 卡尔塞姆',replace(replace('①：此卡的攻击力上升自己场上的“X－军刀”怪兽数量×200的数值。\r\n②：场上的此卡因效果被破坏并被送至墓地的情况下发动。从牌组将1只“X－军刀”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77334267,'弹簧装攻 发条王',replace(replace('等级5怪兽×2\r\n①：1回合1次，去除此卡的1个超量素材，以场上的2张里侧表示卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77336644,'暗红恶魔龙／爆裂',replace(replace('此卡不可通常召唤，仅可以“爆裂模式”的效果特殊召唤。\r\n①：此卡攻击的伤害计算后发动。将场上的其他怪兽全部破坏。\r\n②：场上的此卡被破坏时，以自己墓地的１只“暗红恶魔龙”为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'破坏','特殊召唤','特殊召唤「暗红魔鬼龙」','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77360173,'同步克隆共鸣者',replace(replace('此卡名以①方法的特殊召唤１回合仅可进行１次。\r\n①：场上存在同步怪兽的情况下，此卡可从手牌中特殊召唤。\r\n②：此卡从场上被送至墓地的情况下，以自己墓地的“同步克隆共鸣者”以外的１只“共鸣者”怪兽为对象可以发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77363314,'水晶龙','①：１回合１次，可在此卡进行战斗的我方回合的战斗步骤发动。从牌组将１只龙族、等级８怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77372241,'炎狱龙人','此卡因战斗破坏怪兽并将其送入墓地时，给予对手生命相当于被破坏怪兽的原本等级×２００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77379481,'大盘振舞侍','此卡给予对手玩家战斗伤害时，对手玩家抽取卡牌直至手牌变成７张。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77384395,'帕祖拼图',replace(replace('←1 【灵摆】 1→\r\n①：１回合１次，以另一方自己的灵摆区域的１张卡为对象可以发动。此卡的灵摆刻度直至回合结束时为止，变为与对象灵摆怪兽卡的等级相同的数值。此效果发动后，直至回合结束时为止，自己不可进行灵摆召唤以外的特殊召唤。\r\n【怪兽效果】\r\n①：只要此卡存在于怪兽区域，自己怪兽的灵摆召唤不会被无效化。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77387463,'方界帝伏尔甘・德拉耆尼',replace(replace('此卡不可通常召唤。\r\n我方场上的２只“方界”怪兽送入墓地的场合可特殊召唤。\r\n①：以此方法特殊召唤的此卡攻击力上升１６００。\r\n②：此卡从手牌特殊召唤成功的场合发动。给予对手８００伤害。\r\n③：此卡进行了战斗的伤害步骤结束时，可以我方墓地最多３只的“方界胤维贾姆”为对象发动。将此卡送入墓地，并特殊召唤对象怪兽。之后，可从牌组将１只“方界超帝因蒂奥拉・死亡伏特”加入手牌。','\r',char(13)),'\n',char(10)),'是否把1只「方界超帝因蒂奥拉・死亡伏特」加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77392987,'T.G.火箭沙罗曼蛇',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：解放自己场上的１只“T.G.”怪兽可以发动。从牌组将原本卡名与所解放怪兽不同的１只“T.G.”怪兽特殊召唤。\r\n②：自己场上存在机械族“T.G.”怪兽的情况下，以自己墓地的１只等级４以下的“T.G.”怪兽为对象可以发动。将该怪兽以守备表示特殊召唤。以此效果特殊召唤的怪兽的效果无效化。','\r',char(13)),'\n',char(10)),'从牌组特殊召唤','从墓地特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77402960,'源数直连','①：自己的场地区域存在“源数网络”卡、而自己场上不存在怪兽时可以发动。最多从额外牌组特殊召唤4只“源数之门”超量怪兽（最多1张同名卡）。此效果特殊召唤的怪兽将在结束阶段被除外。此效果发动后，直至回合结束时为止，自己仅可召唤或特殊召唤怪兽1次。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77406972,'魔导骑士 基尔提亚－灵魂枪',replace(replace('此卡名的③效果１回合仅可使用１次。\r\n①：自己场上不存在怪兽的情况下，此卡无需解放即可召唤。\r\n②：此卡召唤成功时可以发动。挑选对手场上１只拥有此卡的攻击力以上的攻击力的怪兽除外。\r\n③：舍弃１张手牌可以发动。从牌组将以下怪兽中的１只加入手牌。\r\n●龙族・暗属性・等级７怪兽\r\n●机械族・暗属性・等级６怪兽\r\n●战士族・水属性・等级５怪兽','\r',char(13)),'\n',char(10)),'不用解放作召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77411244,'B－爆裂龙兽',replace(replace('①：１回合１次，可以发动以下的１个效果。\r\n●以自己场上的１只机械族・光属性怪兽为对象，将此卡视为装备魔法卡装备。装备怪兽将被战斗・效果破坏的情况下，作为代替将此卡破坏。\r\n●将装备状态的此卡特殊召唤。\r\n②：装备怪兽不受对手的魔法卡的效果影响。\r\n③：此卡从场上被送至墓地的情况下可以发动。从牌组将１只联合怪兽加入手牌。','\r',char(13)),'\n',char(10)),'装备','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77414722,'魔法干扰','①：魔法卡发动时，可弃置１张手牌来发动此卡。令其发动无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77421977,'-艾-眼影','此卡名的②效果1回合仅可使用1次。以自己场上的1只“＠伊格尼斯者”怪兽为对象可以发动此卡。①：只要此卡存在于魔法与陷阱区域，对象怪兽的攻击力上升800，可攻击的对手怪兽必须攻击对象怪兽。②：魔法与陷阱区域的表侧表示的此卡因对手的效果从场上离开、被送至墓地的情况下或被除外的情况下发动。自己从牌组抽1张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77428945,'土地锯','此卡名的效果１回合仅可使用１次。①：此卡特殊召唤成功的情况下发动。将场上此卡以外的、被特殊召唤的怪兽全部改成里侧守备表示。','变成里侧守备','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77432167,'太阳神合一',replace(replace('此卡的效果①②不可在同一连锁上发动，自己场上有原本卡名为“拉之翼神龙”的怪兽存在时，此卡在放置此卡的回合也可以发动。\r\n①：在自己或对手的主要阶段，消耗LP至剩下100LP后可以发动。选择1只自己场上被特殊召唤的“拉之翼神龙”，其攻击力、守备力上升消耗的LP数值。\r\n②：1个回合1次，解放自己场上的1只“拉之翼神龙”后可以发动。自己的LP恢复该怪兽的攻击力数值。','\r',char(13)),'\n',char(10)),'攻击力上升','基本分回复','适用「太阳神合一」的效果来发动','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77435268,'质检机',replace(replace('自己场上存在怪兽的情况下，此卡不可召唤。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：解放此卡可以发动。从牌组将1只攻击力和守备力的数值相同的机械族怪兽特殊召唤。以此效果特殊召唤的怪兽将在结束阶段放回手牌。\r\n②：将墓地的此卡除外，舍弃1张手牌可以发动。将1只“铁渣衍生物”（机械族・地・星1・攻/守0）特殊召唤至自己场上。此衍生物不可作为融合・同步・连接召唤的素材。','\r',char(13)),'\n',char(10)),'','特殊召唤','特殊召唤衍生物','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77435269,'铁渣衍生物','「质检机」的效果特殊召唤，这衍生物不能作为融合·同调·连接召唤的素材。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77449773,'电脑网交叉清除','①：可解放我方场上的１只电子界族怪兽，并以场上的１张卡牌为对象发动。破坏该卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77454922,'要塞鲸鱼的誓言','用于召唤“要塞鲸鱼”。必须从手牌・我方场上解放合计等级达到７以上的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77456448,'魔法效果之剑',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：可从以下效果中选择1个发动。\r\n●将对手场上表侧表示的魔法卡全部破坏。\r\n●以对手场上的1只表侧表示怪兽为对象可以发动。挑选自己手牌・墓地的1张“光与暗的仪式”，给双方确认。然后，对象怪兽的攻击力变为0，效果无效化。\r\n②：此卡被对手破坏的情况下可以发动。将对手手牌・场上的1张卡破坏（从手牌是随机挑选）。','\r',char(13)),'\n',char(10)),'发动','对手场上的表侧表示的魔法卡全部破坏','对象怪兽的攻击力变成0，效果无效化','对手的手牌·场上1张卡破坏','随机选对手手牌破坏','选对手场上的卡破坏','','','','','','','','','','');
INSERT INTO texts VALUES(77456781,'魔鬼乌贼','潜在海里的巨大乌贼，会从海中突然出现并发动攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77462146,'魅影骑士团影披幕',replace(replace('①：以自己场上的1只表侧表示怪兽为对象可以发动。该怪兽的攻击力・守备力上升300。\r\n②：此卡存在于墓地的情况下，每次对手的直接攻击宣言时有1次可以发动。此卡变为通常怪兽（战士族・暗・星4・攻0/守300），以守备表示特殊召唤至怪兽区域（不视为陷阱卡）。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'当作通常怪兽特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77482666,'疾风的豹战士',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：在自己・对手的主要阶段，解放场上的此卡以外的、自己手牌・场上的1只怪兽，可从以下效果中选择1个发动。\r\n●从手牌・牌组将除“疾风的豹战士”以外的、1只记载有“时间黑魔术师”卡名的怪兽特殊召唤。\r\n●从牌组将1张记载有“时间黑魔术师”卡名的魔法・陷阱卡送至墓地。\r\n②：此卡必须在有怪兽被解放的回合才可以攻击宣言。','\r',char(13)),'\n',char(10)),'发动效果','','特殊召唤','送至墓地','','','','','','','','','','','','');
INSERT INTO texts VALUES(77491079,'暴风蜥蜴','反转：选择对手场上的１只怪兽并返回至持有者手牌。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77498348,'混沌士兵 －宵暗之使者－',replace(replace('此卡不可通常召唤。只有在我方墓地中光属性和暗属性的怪兽数量相同的场合下，将其中一个属性的怪兽全都除外的场合才可特殊召唤此卡。此卡的属性也视为“光”。成功特殊召唤此卡时，可根据为特殊召唤而除外的怪兽属性来发动以下效果。发动此效果的回合中，跳过我方的战斗阶段。\r\n●光：选择场上的１只怪兽并将其除外。\r\n●暗：随机将对手的１张手牌以里侧表示除外，直到对手结束阶段时。','\r',char(13)),'\n',char(10)),'除外光属性','除外暗属性','除外','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77505534,'坠影的蠢动','①：从牌组中将1张“影依”卡送至墓地。然后，可挑选任意数量的自己场上的里侧守备表示的“影依”怪兽，将其变为表侧守备表示。','是否要选择里侧守备表示的「影依」怪兽变成表侧守备表示？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77506119,'雷电独角兽',replace(replace('兽族协调＋协调以外的怪兽１只或以上\r\n１回合１次，可选择对手场上的１只表侧表示怪兽并发动。被选择怪兽攻击力直至回合结束时，下降我方场上的怪兽数量×５００点。发动此效果的回合，除此卡以外的怪兽不可攻击。','\r',char(13)),'\n',char(10)),'攻击下降','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77511331,'空手道魂 KURO－OBI',replace(replace('←9 【灵摆】 9→\r\n①：怪兽被灵摆召唤至场上的场合发动。将灵摆区的此卡返回至持有者手牌。\r\n【怪兽效果】\r\n①：此卡召唤成功时可发动。将与我方的灵摆区卡牌相同纵列的所有对手魔法、陷阱卡送入墓地。\n②：此卡召唤、反转之回合的结束阶段发动。将此卡返回至持有者手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77515704,'龙女仆・休息',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：以自己场上的1只“龙女仆”怪兽为对象，可从以下效果中选择1个发动。\r\n●将对象怪兽放回手牌，从牌组将“龙女仆・休息”以外的1张“龙女仆”卡加入手牌。\r\n●将对象怪兽放回手牌，将对手场上的1张魔法・陷阱卡放回手牌。','\r',char(13)),'\n',char(10)),'牌组检索','魔陷返回手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77522571,'魔玩具大师',replace(replace('←4 【灵摆】 4→\r\n此卡名的灵摆效果１回合仅可使用１次。\n①：解放自己场上等级４以下的、“魔玩具”、“绒毛动物”、“锋利小鬼”怪兽中的任意１只可以发动。将１只等级与解放的怪兽相同、卡名不同的恶魔族怪兽从牌组特殊召唤。\r\n【怪兽效果】\r\n此卡名的①②怪兽效果１回合仅可各使用１次。\n①：在自己的主要阶段可以发动。从牌组将等级４以下的、“魔玩具”、“绒毛动物”、“锋利小鬼”怪兽中的任意１只特殊召唤。此回合，自己从额外牌组仅可特殊召唤融合怪兽。\n②：解放自己场上２只以上的恶魔族怪兽可以发动。将等级等于其原本等级合计的１只“魔玩具”融合怪兽视为融合召唤从额外牌组特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77527210,'神圣之魂','此卡不可通常召唤。我方墓地的２只光属性怪兽从游戏中除外的场合可特殊召唤。只要此卡以表侧表示存在于场上，仅限在对手战斗阶段中，对手场上所有怪兽的攻击力下降３００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77538567,'魔宫的贿赂','①：对手发动魔法・陷阱卡时可以发动。将该发动无效并破坏。对手从牌组抽1张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77539547,'战华之美－周公',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：以自己场上的1张永续魔法・永续陷阱卡为对象可以发动。将该卡送至墓地，从牌组将1张“战华”魔法・陷阱卡加入手牌。\r\n②：自己的其他“战华”怪兽发动效果的情况下，以对手场上的1只效果怪兽为对象可以发动。将该怪兽的效果直至回合结束时为止无效。','\r',char(13)),'\n',char(10)),'','怪兽无效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77542832,'邪蚀 血滴石','终结灭破坏破念邪高崇的鬼魔入侵魂之等我求追邪恶为又纯粹为既','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77543769,'百夫骑士皇爆诞',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：怪兽的效果・魔法・陷阱卡发动时，将自己的魔法与陷阱区域的1张表侧表示的怪兽卡送至墓地可以发动。将该发动无效并破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77558536,'光道暗杀者 莱丁',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：在自己的主要阶段可以发动。从自己的牌组上面将２张卡送至墓地。其中有“光道”怪兽的情况下，进而此卡的攻击力直至对手回合结束时为止上升２００。\r\n②：在自己的结束阶段发动。从自己的牌组上面将２张卡送至墓地。','\r',char(13)),'\n',char(10)),'送墓','送墓','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77561728,'搅乱作战','对手将所有手牌加入牌组并洗牌。之后，对手抽取与加入牌组数量相同张数的卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77565204,'未来融合－永望结合',replace(replace('①：此卡发动后将在自己的第1次的准备阶段发动。向对手出示额外牌组的1只融合怪兽，从牌组将由该怪兽决定的融合素材怪兽送至墓地。\r\n②：此卡发动后将在自己的第2次的准备阶段发动。将以此卡的①效果出示的怪兽的1只同名融合怪兽融合召唤。此卡从场上离开时该怪兽将被破坏。该怪兽被破坏时将此卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77568553,'酸液爬虫','巨大的毛毛虫。口中吐出的强酸能够溶解一切物体。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77571454,'编号69 徽章神 盾徽－神之狂怒',replace(replace('等级4怪兽×5\r\n①：场上的此卡不会因战斗・效果被破坏。\r\n②：在每个自己・对手回合中1次，去除此卡的1个超量素材，以对手场上的1只表侧表示怪兽为对象可以发动。将该怪兽的卡名视为“未知”。\r\n③：只要此卡存在于怪兽区域，对手发动的“未知”的效果无效化。','\r',char(13)),'\n',char(10)),'卡名变更','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77571455,'不明','','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77573354,'蕾祸之曝藤',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：此卡发动后，变为通常怪兽（植物族・暗・星４・攻１６００／守０），特殊召唤至怪兽区域（也视为陷阱卡）。自己场上存在“蕾祸”连接怪兽的情况下，进而可从对手墓地将最多２张卡除外。\r\n②：在自己・对手的结束阶段，此卡存在于墓地的情况下可以发动。将自己墓地・除外状态的２只昆虫族・植物族・爬虫类族怪兽放回牌组，将此卡放置在自己场上。','\r',char(13)),'\n',char(10)),'特殊召唤','放置效果','是否除外对手墓地的卡？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77581312,'假面小丑','一边跳着死亡之舞，一边用手中的镰刀砍杀敌人的战士。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77584012,'拟似空间','①：１回合１次，可从我方墓地除外１张场地魔法卡并发动。直至结束阶段，此卡被视为与被除外卡牌的同名卡，获得相同效果。','获得场地魔法卡的效果','结束复制效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77585513,'人造人－念力震慑者','①：只要此卡存在于怪兽区域，双方不可在场上发动陷阱卡的效果，场上的陷阱卡的效果无效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77585514,'人造人－念力震慑者','①：只要此卡存在于怪兽区域，双方不可在场上发动陷阱卡的效果，场上的陷阱卡的效果无效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77590412,'傀偶车',replace(replace('①：此卡召唤成功时可以发动。将此卡改成守备表示，从牌组将１只战士族・地属性怪兽送至墓地。\r\n②：只要此卡存在于怪兽区域，可攻击的对手怪兽必须攻击此卡。\r\n③：１回合１次，此卡被选择为攻击对象时，以自己墓地的１只等级６以上的战士族・地属性怪兽为对象可以发动。将场上的此卡送至墓地，将对象怪兽特殊召唤。然后，将攻击对象移换为该怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77600660,'念力帝皇','此卡召唤、特殊召唤成功时，我方回复我方墓地的念动力族怪兽数量×５００LP。','LP回复','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77603950,'沙塔那','能诅咒敌人，令其动弹不得的魔法师。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77608643,'命运－英雄 顽强魔侠','此卡以表侧表示存在于我方场上时，我方场上除此卡以外冠有“命运－英雄”之名的怪兽因战斗被破坏送入墓地的场合，下一次我方准备阶段时可选择１只该怪兽特殊召唤至我方场上。特殊召唤被选择怪兽至我方场上。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77610503,'随风飘飘游与恐怖的海','此卡名的卡１回合仅可发动１张。①：自己场上有上级召唤的表侧表示怪兽存在，且被特殊召唤的怪兽不存在的情况下，对手将怪兽特殊召唤之际可以发动。将该特殊召唤无效，将该怪兽放回持有者的手牌。此回合，对手不可将怪兽特殊召唤，通常召唤最多可进行３次。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77610772,'星杯神乐 伊布',replace(replace('种族与属性不同的怪兽2只\r\n①：连接状态的此卡不会因战斗・效果被破坏，不会成为对手效果的对象。②：此卡连接端的怪兽将被效果破坏的情况下，可将此卡送至墓地作为代替。③：此卡从场上被送至墓地的情况下可以发动。从手牌将1只“星杯”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'是否使用「星杯神乐 伊布」的效果代替破坏？','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77622396,'天邪鬼的诅咒','直到发动回合的结束阶段时，令攻击力和守备力的上升或下降效果变为相反。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77625948,'电子暗黑刃',replace(replace('①：此卡召唤的情况下，以自己墓地的1只等级3以下的龙族怪兽为对象发动。将该龙族怪兽视为装备魔法卡装备于此卡。\r\n②：此卡的攻击力上升以此卡的效果装备的怪兽的攻击力数值。\r\n③：此卡可直接攻击。该情况下，此卡的攻击力仅在该伤害计算时变为一半。\r\n④：此卡将被战斗破坏的情况下，作为代替将以此卡的效果装备的怪兽破坏。','\r',char(13)),'\n',char(10)),'装备','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77631175,'漫画英雄 亚瑟王',replace(replace('战士族等级４怪兽×２\r\n此卡因战斗被破坏的情况下，可以移除此卡的１个超量素材作为代替。超量素材以此效果被移除时，此卡的攻击力上升５００点，并给予对手LP５００点伤害。','\r',char(13)),'\n',char(10)),'是否使用「漫画－英雄 亚瑟王」的效果代替破坏？','攻击上升','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77637979,'局域网喙嘴龙','怪兽2只','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77642288,'剑斗兽 追鬣','①：以“剑斗兽”怪兽的效果特殊召唤的此卡进行过战斗的战斗阶段结束时发动。从牌组将“剑斗兽 追鬣”以外的２只“剑斗兽”怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77656797,'焰圣骑士帝－查理',replace(replace('协调＋１只以上协调以外的怪兽\r\n此卡名的①②效果１回合仅可各使用１次。①：装备卡被装备至场上怪兽的情况下可以发动（伤害步骤也可以发动）。挑选场上的１张卡破坏。②：在自己・对手的结束阶段可以发动。从自己手牌・墓地挑选１张装备魔法卡装备于此卡。然后，可从牌组挑选１只战士族・炎属性怪兽，视为攻击力上升５００的装备卡装备于此卡。','\r',char(13)),'\n',char(10)),'选场上1张卡破坏','装备卡给此卡装备','是否选怪兽装备？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77672444,'马达暴徒',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下，或机械族怪兽被召唤・特殊召唤至自己场上的情况下可以发动。该被召唤・特殊召唤的怪兽直至对手回合结束时为止，攻击力上升相当于其原本守备力一半的数值，不可变更表示形式。\r\n②：上级召唤的此卡被送至墓地的情况下可以发动。将2只“马达衍生物”（机械族・地・星1・攻/守200）以攻击表示特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77672445,'马达衍生物','由“恶鬼马达Ω”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77675029,'驱魔姐妹・卡尔玛尔',replace(replace('等级4“驱魔姐妹”怪兽×2\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡超量召唤的情况下可以发动。在此回合的结束阶段，将自己牌组・墓地・除外状态的1张“驱魔姐妹”魔法・陷阱卡放置在自己场上。\r\n②：对手发动怪兽的效果・通常魔法・通常陷阱卡时可以发动。去除此卡的全部超量素材，该效果变为“从对手墓地将1张卡加入对手手牌”。','\r',char(13)),'\n',char(10)),'放置魔陷','改变效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77679716,'超重武者装魂 破碎铠甲',replace(replace('①：在自己的主要阶段，以自己场上的１只“超重武者”怪兽为对象可以发动。将自己手牌・场上的此怪兽视为守备力下降１０００的装备卡，装备于该自己的怪兽。装备怪兽不会因战斗被破坏。\r\n②：在自己的主要阶段，从自己的墓地将包含此卡在内的“超重武者装魂 破碎铠甲”全部除外，以守备力低于原本守备力的１只“超重武者”怪兽为对象可以发动。给予对手相当于该怪兽的守备力和其原本守备力的数值差的伤害。','\r',char(13)),'\n',char(10)),'装备','效果伤害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77683371,'次元施法者','此卡名的①②效果１回合仅可各使用１次。①：此卡召唤・特殊召唤成功的情况下可以发动。从自己的牌组・墓地挑选１张“次元魔法”加入手牌。②：此卡被从怪兽区域送至墓地的情况下可以发动。依自己场上的魔法师族怪兽的数量，自己从牌组抽牌。然后，依所抽的数量挑选手牌，以喜欢的顺序放回牌组上面。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77693536,'重炼装・万溶',replace(replace('“炼装”怪兽＋通常怪兽\r\n此卡只可以融合召唤进行特殊召唤。\r\n①：在对手回合仅１次，可以场上的１只效果怪兽为对象发动。该效果怪兽被视为装备卡装备此卡。\r\n②：此卡的守备力上升相当于因此卡效果所装备之怪兽的原本攻击力数值。\r\n③：此卡装备有由“炼装”融合怪兽卡所规定之融合素材怪兽的场合，可将该装备卡作为该融合怪兽之融合素材使用。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77700347,'死灵防御者','可将墓地的此卡从游戏中除外，并选择我方场上１只怪兽发动。直至回合结束时，被选择怪兽不会因战斗被破坏，且因被选择怪兽的战斗所造成的对我方的战斗伤害变成０。','战斗耐性','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77710579,'机皇枢无限之核',replace(replace('此卡名的效果①③在1个回合中仅可各使用1次。\r\n①：此卡召唤或特殊召唤成功时可以发动。将牌组中的1张“机皇”魔法・陷阱卡加入手牌。\r\n②：此卡1个回合中仅有1次不会在战斗中被破坏。\r\n③：此卡在因效果被破坏时可以发动。无视召唤条件，从手牌或牌组中特殊召唤1只同属性怪兽不存在于自己场上的“机皇帝”怪兽。此效果发动后，直至回合结束时为止，自己只能用1只怪兽进行攻击宣言。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77714963,'骸之魔妖－夜叉',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：从手牌将１只其他的“魔妖”怪兽舍弃可以发动。从手牌将此卡特殊召唤。\r\n②：只要此卡存在于怪兽区域，自己从额外牌组仅可特殊召唤“魔妖”怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77723643,'影依・龙',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：此卡反转的情况下，以对手场上的1张卡为对象可以发动。将该卡放回手牌。\r\n②：此卡因效果被送至墓地的情况下，以场上的1张魔法・陷阱卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'回到手牌','魔陷破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77751766,'火器的祝台',replace(replace('发动此卡的情况下，在此卡上放５个祝台计数物发动。\r\n①：因魔法・陷阱卡的效果、使得怪兽被从额外牌组特殊召唤的情况下，或使得卡被从牌组送至墓地的情况下发动。去除此卡的１个祝台计数物。然后，此卡的祝台计数物的数量为０的情况下，将此卡破坏，自己恢复４０００LP。然后，从自己牌组・墓地将１张“祝台”陷阱卡放置在自己场上。然后，自己牌组的张数为１张以下的情况下，自己获得决斗胜利。','\r',char(13)),'\n',char(10)),'','取除计数物','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77754169,'超装甲兵器机器人 黑钢铁G',replace(replace('此卡牌名的①②效果１回合只可各使用１次。\r\n①：我方墓地存在有３只昆虫族的同名怪兽的场合，可以其中任意数量怪兽为对象发动。从手牌特殊召唤此卡。之后，对象怪兽被视为装备卡装备此卡。\r\n②：可将１张以此卡效果装备的怪兽卡送入墓地并发动。破坏对手场上持有攻击力是送入墓地的该卡攻击力或以上的所有怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77754944,'万能地雷阔剑式','①：对手怪兽进行攻击宣言时可发动。破坏对方场上表侧攻击表示怪兽中攻击力最高的１只怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77754945,'万能地雷阔剑式','①：对手怪兽进行攻击宣言时可发动。破坏对方场上表侧攻击表示怪兽中攻击力最高的１只怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77765207,'起誓的徽纹',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：可从以下效果中选择１个发动。\r\n●从牌组将１只“百夫骑”怪兽视为永续陷阱卡，以表侧表示放在自己的魔法与陷阱区域。此回合，以此效果所放的卡或原本卡名与该卡相同的卡以表侧表示存在于自己场上期间，自己从额外牌组仅可特殊召唤“百夫骑”怪兽。\r\n●从牌组将１张“百夫骑”魔法・陷阱卡放置在自己场上。','\r',char(13)),'\n',char(10)),'把怪兽表侧表示放置','把魔法·陷阱卡放置','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77778835,'歇斯底里的派对','①：舍弃１张手牌可以发动此卡。从自己的墓地尽可能地将“神鹰女郎”特殊召唤。此卡离开场上时，以此效果特殊召唤的怪兽将被全部破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77783947,'龙星的极致','①：只要此卡存在于魔法与陷阱区域，可攻击的对手怪兽必须攻击。②：在自己或对手的主要阶段以及战斗阶段，将魔法与陷阱区域表侧表示存在的此卡送至墓地可以发动此效果。以包含1只以上“龙星”怪兽在内的怪兽作为素材将1只同步怪兽同步召唤。','同步召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77797992,'森之圣兽 羊驼驯鹿',replace(replace('①：此卡根据表示形式获得以下效果。\r\n●攻击表示：自己的攻击表示的鸟兽族・昆虫族・植物族怪兽不会因战斗被破坏。\r\n●守备表示：自己场上的守备表示的鸟兽族・昆虫族・植物族怪兽不会成为效果的对象，不会因效果被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77799846,'垃圾眼太鼓龙',replace(replace('机械族等级８怪兽×２\r\n１回合１次，可移除此卡的１个超量素材并发动。直至对手回合结束时，此卡的攻击力上升１０００点。持有超量素材的此卡被破坏并送入墓地的场合，可将我方墓地１只冠有“超防卫机器人”之名的怪兽从游戏中除外并发动。特殊召唤此卡。之后，可挑选我方墓地１只冠有“超防卫机器人”之名的怪兽，并重叠至此卡的下方当作超量素材。','\r',char(13)),'\n',char(10)),'攻击上升','特殊召唤','是否要选择墓地1只名字带有「超防卫机器人」的怪兽作为超量素材？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77826734,'灵摆重生','①：从自己的额外牌组（表侧）・墓地将１只灵摆怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77827521,'地狱的判决','将敌人封在棺材中，由地狱使者刺一刀执行判决。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77832858,'邪炎帝王泰斯塔罗斯',replace(replace('此卡可解放对手场上的１只怪兽和自己的１只上级召唤的怪兽来上级召唤。\r\n①：此卡上级召唤的情况下可以发动。随机将对手１张手牌除外，给予对手１０００伤害。解放上级召唤的等级８以上怪兽来上级召唤此卡的情况下，可进而适用以下效果。\r\n●将场上的１张卡除外，该卡为炎・暗属性怪兽卡的情况下，给予对手相当于其原本等级×２００的伤害。','\r',char(13)),'\n',char(10)),'把对手场上1只怪兽和上级召唤的1只自己怪兽解放作上级召唤','','是否再把场上1张卡除外？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77840540,'超进化之茧',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：解放１只自己・对手场上装备有装备卡的昆虫族怪兽，无视召唤条件，从牌组中特殊召唤１只昆虫族怪兽。\r\n②：在自己的主要阶段将墓地的此卡除外，并以自己墓地的１只昆虫族怪兽为对象可以发动。将该怪兽加入牌组并洗牌。然后，自己从牌组中抽１张牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77841719,'邪蚀 克佩里尔','此卡不可特殊召唤。表侧表示的此卡因对手从场上离开时，选择对手场上的１只表侧表示怪兽，并直至下一个我方结束阶段时获得其控制权。','获得控制权','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77847678,'紫炎的策略','我方场上冠有“六武众”之名的怪兽因战斗被破坏时可发动。从手牌特殊召唤最多２只冠有“六武众”之名的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77848740,'魔幻甜点・布蕾小公主',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己的墓地不存在怪兽的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：此卡特殊召唤的情况下可以发动。从手牌・牌组将“魔幻甜点・布蕾小公主”以外的１只“魔幻甜点”怪兽特殊召唤。该怪兽的等级下降１。此回合，自己仅可特殊召唤“魔幻甜点”怪兽。\r\n③：此卡被对手破坏并被送至墓地的情况下发动。将此卡放回牌组。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77855162,'摆式特急 同律列车',replace(replace('协调＋协调以外的怪兽１只以上\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡同步召唤的情况下可以发动。从自己的手牌・额外牌组（表侧）将等级４以下的１只灵摆怪兽特殊召唤。\r\n②：此卡或自己的灵摆怪兽与对手怪兽进行战斗，且该对手怪兽未被破坏的伤害步骤结束时可以发动。将该对手的怪兽破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77856460,'海中战型助手机器人',replace(replace('机械族怪兽2只\r\n此卡名的①②效果1回合仅可各使用1次，发动此效果的回合中，自己仅可特殊召唤机械族怪兽。\r\n①：此卡连接召唤的情况下，以对手场上的1只怪兽为对象可以发动。将该怪兽及此卡破坏。然后，可从自己墓地将除水属性怪兽以外的、1只攻击力1600以下的机械族怪兽特殊召唤。\r\n②：此卡被除外的情况下可以发动。从牌组将1只攻击力和守备力的数值相同的机械族怪兽加入手牌。','\r',char(13)),'\n',char(10)),'破坏效果','检索效果','是否特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77859858,'步向破灭的速攻抽卡','抽牌阶段开始时双方玩家手牌为０张的场合，可在通常抽牌以外再抽１张卡牌。此卡的控制者每次我方回合的结束阶段时支付７００LP。此时LP不足７００的场合，LP变成０。表侧表示的此卡从场地离开时，我方受到３０００点伤害。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77864539,'机皇厂','冠有“机皇”之名的怪兽被选择为攻击对象时可发动。从我方墓地将１只冠有“机皇兵”之名的怪兽加入手牌。之后，破坏成为攻击对象之怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77876207,'通往宝藏的隐秘通道','选择我方场上１只表侧表示的攻击力低于１０００的怪兽。该回合中，所选择怪兽可直接攻击对手玩家。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77891946,'驱魔姐妹・去往何处',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：支付800LP可以发动。从牌组挑选1只“驱魔姐妹”怪兽，进而再从牌组挑选1只卡名记载于该怪兽的“驱魔姐妹”怪兽。将该2只怪兽特殊召唤。以此效果特殊召唤的怪兽将在结束阶段被放回牌组。此卡发动后，直至回合结束时为止自己从额外牌组仅可特殊召唤“驱魔姐妹”怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77894049,'对击斗魂 项',replace(replace('等级4“对击斗魂”怪兽×2只以上\r\n在“对击斗魂”怪兽战斗过的每个回合有1次，“对击斗魂 项”也可重叠在自己场上的“对击斗魂”怪兽或“斗神的虚像”上面来超量召唤。\r\n①：此卡根据此卡持有的超量素材的怪兽属性获得以下效果。\r\n●暗：对手场上的怪兽的攻击力下降800。\r\n●炎：自己场上的“对击斗魂”怪兽的攻击力上升1000。\r\n●地：去除此卡的1个超量素材可以发动。将对手场上的1张卡破坏。','\r',char(13)),'\n',char(10)),'是否在「对击格斗之魂」怪兽或者「斗神的虚像」上面重叠来超量召唤？','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77895328,'暗黑界之门卫 品红赞塔',replace(replace('自己1回合仅可特殊召唤1次“暗黑界之门卫 品红赞塔”。\r\n①：从手牌将此卡舍弃至墓地可以发动。从牌组将1张“暗黑界之门”加入手牌。\r\n②：此卡被除外的情况下，如果自己场上存在“暗黑界”卡则可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77901552,'圣刻龙－泰芙努龙','①：仅有对手场上才存在怪兽的情况下，此卡可从手牌中特殊召唤。以此方法特殊召唤的回合，此卡不可攻击。②：此卡被解放的情况下发动。从自己的手牌・牌组・墓地挑选１只龙族通常怪兽，将其攻击力・守备力改成０并特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77910045,'死之演算盘','每次将场上存在的怪兽送入墓地，该怪兽的持有者每有１张就受到５００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77913594,'驱魔姐妹・平安同在',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：在自己・对手的主要阶段支付800LP可以发动。从牌组将1张“驱魔姐妹・平安同在”以外的“驱魔姐妹”卡加入手牌。以此效果将怪兽加入了手牌，且卡名记载于该怪兽的“驱魔姐妹”怪兽存在于自己场上或墓地的情况下，进而可将加入了手牌的该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'牌组检索','是否特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77936940,'凯尼亚','①：场上表侧表示的此卡因对手的卡牌效果而被破坏送入墓地的场合，在我方下个准备阶段发动此卡。从墓地中特殊召唤此卡。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77946022,'天威无穷之境地',replace(replace('此卡名的卡1回合仅可发动1张，此卡名的②效果1回合仅可使用1次。\r\n①：作为此卡发动时的效果处理，可从牌组将1张“虚空龙轮”或“天幻龙轮”加入手牌。\r\n②：解放自己场上的1只幻龙族怪兽，以场上的1只怪兽为对象可以发动。将该怪兽破坏。\r\n③：在自己的结束阶段可以发动。将此卡送至墓地，从自己牌组・墓地将1张“天威无崩之地”以表侧表示放在自己的场地区域。','\r',char(13)),'\n',char(10)),'发动','破坏','表侧表示放置','是否把卡加入手牌？','','','','','','','','','','','','');
INSERT INTO texts VALUES(77967790,'恐龙摔跤手・王者・角力暴龙',replace(replace('“恐龙摔跤手”怪兽2只以上\r\n①：此卡进行战斗的情况下，对手直至伤害步骤结束时为止，不可发动魔法・陷阱卡。\r\n②：只要此卡存在于怪兽区域，对手怪兽不可将其他怪兽选择为攻击对象。\r\n③：对手的战斗阶段开始时，以对手场上1只攻击表示的怪兽为对象可以发动。此战斗阶段中，对手如果不用该怪兽进行攻击宣言，则不可用其他怪兽攻击宣言。没有进行攻击宣言的情况下，对象怪兽将在该战斗阶段结束时被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77972406,'反击的毒牙','以我方场上冠有“猛毒”之名的怪兽为攻击对象的对手怪兽之攻击宣言时，可选择该攻击怪兽并发动。使该攻击怪兽的攻击无效，并结束战斗阶段。之后，放置１个猛毒计数物在该怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77994337,'万圣哈喽',replace(replace('←2 【灵摆】 2→\r\n①：１回合１次，以场上的１只表侧表示怪兽为对象可以发动。掷１次骰子。该怪兽的等级直至回合结束时为止，变为与出现的数字相同。\r\n【怪兽效果】\r\n万圣哈喽总是对甜甜的点心两眼放光。\n为了找点心往那边四处彷徨，又往这边东张西望。\n不给点心就搞出恶作剧各种各样，直到你头垂气也丧。\n一切都无济于事，哪怕你慌慌张张。\n就请期待会出现什么吧。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(77998771,'乌鸦天狗','通晓万物的天狗。据说它可以施展神通之力。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78004197,'暗黑界之武神 金格尔德','①：此卡因效果从手牌被舍弃至墓地的情况下发动（因对手的效果被舍弃的情况下，可将对手场上的最多2张卡作为对象）。将此卡特殊召唤。此效果发动时将对手的卡作为对象的情况下，进而将该对手的卡破坏。','特殊召唤','是否要破坏对手场上的卡？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78009994,'龙神守卫','每次怪兽被通常召唤时，放置１个龙神计数物在此卡。此外，可将放置有龙神计数物的此卡送入墓地并发动。从牌组特殊召唤１只持有等级为放置在此卡的龙神计数物数量或以下的龙族怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78010363,'黑森林女巫',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：此卡从场上被送至墓地的情况下发动。从牌组将1只守备力1500以下的怪兽加入手牌。此回合，自己不可发动以此效果加入手牌的卡及其同名卡的效果。','\r',char(13)),'\n',char(10)),'牌组检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78021082,'编织妖精传姬之人',replace(replace('“妖精传姬”怪兽＋魔法师族怪兽\r\n此卡名的①效果1回合仅可使用1次。\r\n①：在自己的主要阶段可以发动。将自己牌组・除外状态的1只“妖精传姬”怪兽特殊召唤。\r\n②：此卡存在于怪兽区域的状态下，自己将地属性以外的“妖精传姬”怪兽召唤・特殊召唤的情况下，以对手场上的1只效果怪兽为对象可以发动。将该怪兽的效果无效化，卡名视为“妖精的王子大人”。\r\n③：场上的“妖精的王子大人”变为魔法师族。','\r',char(13)),'\n',char(10)),'特殊召唤','改变卡名','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78033100,'圣刻龙－龙人盖布','①：此卡战斗破坏对手怪兽并将其送至墓地的情况下发动。从自己的手牌・牌组・墓地挑选１只龙族通常怪兽，将其攻击力・守备力改成０并特殊召唤。②：此卡被解放的情况下发动。从自己的手牌・牌组・墓地挑选１只“圣刻”通常怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78053598,'暗之指名者','宣言１个怪兽卡名可以发动。对手将宣言的１张卡从牌组加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78058681,'杀手旋律・同步',replace(replace('此卡名的卡1回合最多可以发动2张。\r\n①：从牌组将1张“杀手旋律・同步”以外的“杀手旋律”卡加入手牌。然后，可进行1只同步怪兽的协调的同步召唤。此卡发动后，直至回合结束时为止，自己仅可特殊召唤协调。','\r',char(13)),'\n',char(10)),'发动','是否同步召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78060096,'灭绝国王鲑','身为暗黑海洋之主，深受人们恐惧的巨大鲑鱼。其鱼卵是暗黑界首屈一指的美味，闻名遐迩。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78063197,'纳祭魔结合',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：将自己手牌・场上・墓地的怪兽作为融合素材除外，将1只“眼纳祭魔”融合怪兽融合召唤。\r\n②：在自己的主要阶段将墓地的此卡除外，以对手场上的1只效果怪兽为对象可以发动。挑选自己场上的1只“眼纳祭魔”融合怪兽或“纳祭魔”，将对象的对手的效果怪兽视为以其效果变成的装备魔法卡装备。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78077209,'魔龙将 蒂娅波莉卡',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：有“魔龙将 蒂娅波莉卡”以外的恶魔族怪兽因效果被送至自己墓地的情况下可以发动。从手牌・墓地将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下将被除外。\r\n②：此卡因效果被送至墓地的情况下，以“魔龙将 蒂娅波莉卡”以外的、自己墓地的1只恶魔族怪兽为对象可以发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78080961,'秘旋谍－天才',replace(replace('①：此卡召唤・特殊召唤的情况下可以发动。从牌组将１张“秘旋谍装备”卡加入手牌。\r\n②：此卡存在于墓地，且自己场上存在“秘旋谍－花花公子”的情况下，舍弃１张手牌可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78082039,'封闭的森林','我方场上的兽族怪兽的攻击力，上升我方墓地怪兽数量×１００点。只要此卡存在于场上，不可发动场地魔法卡。此外，此卡被破坏的回合，双方都不可发动场地魔法卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78084378,'信号分离器客迈拉',replace(replace('电子界族怪兽×2\r\n此卡名的②效果1回合仅可使用1次。①：1回合1次，解放自己场上的1只电子界族怪兽可以发动。此回合的战斗阶段中，双方不可发动魔法・陷阱卡的效果。②：融合召唤的此卡被送至墓地的情况下，以此卡以外的自己墓地的1只电子界族怪兽和1张“电脑网结合”为对象可以发动。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78098950,'刀皇－都牟羽沓薙','此卡不可特殊召唤。此卡可以解放１只通常召唤的怪兽来上级召唤。①：此卡召唤・反转的情况下发动。对手可挑选自身场上任意数量的卡送至墓地。该情况下，依其数量双方从牌组抽牌。在此效果发动过的回合的结束阶段，将双方场上・墓地的卡及被除外的卡全部放回持有者的牌组。②：此卡召唤・反转的回合的结束阶段发动。将此卡放回持有者的手牌。','把1只通常召唤的怪兽解放作上级召唤','','是否选场上的卡送至墓地？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78114463,'神之密告',replace(replace('此卡也可通过将自己场上的1张其他里侧表示陷阱卡出示给对手，来在放置的回合发动。\r\n①：魔法・陷阱卡发动时，可从以下效果中选择1个发动。\r\n●支付1500LP可以发动。将该发动无效并破坏。此回合，双方不可发动所破坏的卡及与该卡原本卡名相同的卡的效果。\r\n●支付3000LP可以发动。将该发动无效并除外。然后，对手从自身手牌・牌组将与以此效果所除外的卡原本卡名相同的卡全部除外。','\r',char(13)),'\n',char(10)),'发动','无效并破坏','无效并除外','适用「神之密告」的效果来发动','','','','','','','','','','','','');
INSERT INTO texts VALUES(78121572,'黑魔力精制者','１回合１次，可将我方场上表侧攻击表示的此卡变为表侧守备表示，并在我方场上１张表侧表示的可放置魔力计数物的卡牌上放置１个魔力计数物。','改变表示形式','请选择要放置魔力计数物的卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78135071,'驱魔姐妹・加斯伯特拉',replace(replace('等级4怪兽×2\r\n此卡名的①③效果1回合仅可各使用1次。\r\n①：此卡以“驱魔姐妹”怪兽作为素材超量召唤的情况下可以发动。此回合，双方不可从墓地将怪兽特殊召唤。\r\n②：此卡不会因与从墓地被特殊召唤的怪兽的战斗被破坏。\r\n③：去除此卡的1个超量素材可以发动。从牌组将1只“驱魔姐妹”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78144171,'击灭龙 暗黑武装',replace(replace('等级7怪兽×2只以上\r\n“击灭龙 暗黑武装”1回合1次，在自己墓地的暗属性怪兽仅有5只的情况下，也可重叠在自己场上的等级5以上的龙族・暗属性怪兽上面来超量召唤。\r\n①：去除此卡的1个超量素材，以对手场上的1张卡为对象可以发动。将该卡破坏。然后，从自己墓地将1张卡除外。此效果发动后，直至回合结束时为止此卡不可攻击。','\r',char(13)),'\n',char(10)),'是否只用1只素材超量召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78156759,'弹簧机雷 发条爆具',replace(replace('等级3怪兽×2\r\n①：场上的此卡将被破坏的情况下，作为代替可去除此卡的1个超量素材。\r\n②：1回合1次，在适用了此卡的①效果的回合的结束阶段，以场上的1张卡为对象发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'是否要使用「弹簧机雷 发条爆具」的效果代替破坏？','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78161361,'驱动勇士','①：１回合１次，我方电子界族怪兽攻击宣告时，从手牌弃掉１只怪兽可发动。该攻击怪兽的攻击力上升６００点直到回合结束。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78161960,'抗拒复活','①：对手怪兽的直接攻击宣言时可发动。结束战斗阶段。之后，可从我方墓地挑选１只协调与１只同步怪兽并特殊召唤。以此效果特殊召唤的怪兽其效果被无效化。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78184733,'娱乐闪光','①：我方场上存在有“娱乐伙伴”怪兽的场合可发动。对手场上的表侧攻击表示怪兽全部变成守备表示，直至下一个回合结束时，该怪兽不可变更表示形式。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78193831,'毁灭剑士','①：此卡的攻击力上升对方场上、墓地的龙族怪兽数量×５００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78193832,'毁灭剑士','①：此卡的攻击力上升对方场上、墓地的龙族怪兽数量×５００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78193833,'毁灭剑士','①：此卡的攻击力上升对方场上、墓地的龙族怪兽数量×５００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78193834,'毁灭剑士','①：此卡的攻击力上升对方场上、墓地的龙族怪兽数量×５００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78199891,'御巫神比',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：自己场上有“御巫”怪兽存在的情况下，以场上的1只表侧表示怪兽为对象可以发动。从牌组将1张该怪兽可装备的装备魔法卡装备于该怪兽。\r\n②：此卡存在于墓地的状态下，装备魔法卡被送至自己墓地的情况下，将此卡除外，以自己墓地的1张装备魔法卡为对象可以发动。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'','回收装备魔法卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78202553,'地中骇界邪龙 煤岩直布罗陀',replace(replace('此卡名的③效果1回合仅可使用1次。\r\n①：自己场上的表侧表示怪兽变为里侧表示时，若自己场上不存在表侧表示怪兽则可以发动。从手牌将此卡以守备表示特殊召唤。\r\n②：在自己的主要阶段可以发动。将此卡改成里侧守备表示（1回合仅1次）。\r\n③：此卡反转的情况下可以发动。从手牌挑选1只“地中骇界”怪兽舍弃，自己抽2张。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78211862,'提升能量','①：可舍弃１张手牌，并以场上的１只表侧表示怪兽为对象发动。直至回合结束时，该怪兽的攻击力上升１５００。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78217065,'进化终末冲击波',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从牌组将1张“超负载结合”加入手牌。此回合中，通过“超负载结合”的效果将6只以上怪兽作为素材融合召唤的情况下，该怪兽此回合在1次战斗阶段中最多可攻击的次数为作为其融合素材的怪兽数量。此卡发动后，直至回合结束时为止自己仅可以魔法卡的效果特殊召唤怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78225596,'充电机块 电池章鱼',replace(replace('2只“机块”怪兽\r\n①：处于连接状态的此卡不会成为攻击对象，也不会成为对手效果的对象。\r\n②：与此卡相互连接的自己的“机块”连接怪兽与对手怪兽进行战斗，计算伤害值时发动。仅在计算伤害值时，该自己怪兽的攻击力上升与此卡相互连接的怪兽数量×1000。\r\n③：1个回合1次，未与此卡相互连接的自己场上的“机块”怪兽因战斗或效果被破坏时可以发动。自己从牌组中抽1张卡。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78229193,'白斗气海豚',replace(replace('协调＋协调以外的怪兽１只以上\r\n①：１回合１次，以对手场上的１只表侧表示怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止，变为原本攻击力的一半。\r\n②：此卡因对手被破坏并被送至墓地的情况下，从自己的墓地将１只其他的水属性怪兽除外可以发动。将此卡视为协调并特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78231355,'龙女仆的无微不至',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从自己手牌・墓地将1只“龙女仆”怪兽以守备表示特殊召唤。然后，可将1只与以此效果特殊召唤的怪兽等级不同、属性相同的“龙女仆”怪兽从牌组送至墓地。','\r',char(13)),'\n',char(10)),'是否从牌组把等级不同的怪兽送至墓地？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78231356,'龙女仆的无微不至',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从自己手牌・墓地将1只“龙女仆”怪兽以守备表示特殊召唤。然后，可将1只与以此效果特殊召唤的怪兽等级不同、属性相同的“龙女仆”怪兽从牌组送至墓地。','\r',char(13)),'\n',char(10)),'是否从牌组把等级不同的怪兽送至墓地？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78243409,'火山口的潜伏者','此卡被破坏并从场上被送入墓地时，可从手牌特殊召唤１只炎族怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78266168,'巨大木乃伊','此卡在１个回合中可有１次机会变为里侧守备表示。当攻击里侧守备表示的此卡的怪兽的攻击力低于此卡守备力的场合，破坏攻击怪兽。','变成里侧守备','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78274190,'超重辉将 珊瑚－５',replace(replace('←8 【灵摆】 8→\r\n①：自己墓地存在魔法・陷阱卡的情况下，此卡的灵摆刻度变为４。②：１回合１次，自己的“超重武者”怪兽战斗破坏对手怪兽时可以发动。该怪兽可继续攻击仅１次。\r\n【怪兽效果】\r\n此卡在规则上也视为“超重武者”卡。此卡名的怪兽效果１回合仅可使用１次。①：自己墓地不存在魔法・陷阱卡的情况下，解放自己场上的最多２只“超重武者”怪兽可以发动。自己依解放的数量从牌组抽牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78275321,'赤蚁 阿斯卡托尔','①：此卡因战斗被破坏并被送至墓地时，以自己墓地的１只等级５怪兽为对象可以发动。将该怪兽特殊召唤。以此效果特殊召唤的怪兽的效果无效化，将在此回合的结束阶段被送至墓地。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78293584,'狂怒・迪亚贝尔',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从牌组将1只等级8以上的“迪亚贝尔”怪兽加入手牌。仅有对手场上才存在怪兽的情况下，也可不加入手牌而是改为将其特殊召唤。\r\n②：此卡被除外的情况下可以发动。自己场上的所有“迪亚贝尔”怪兽的攻击力上升500。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78310590,'魔界剧团－成熟女演员',replace(replace('←0 【灵摆】 0→\r\n此卡名的灵摆效果1回合仅可使用1次。①：支付1000LP可以发动。从牌组将1只“魔界剧团-成熟女演员”以外的“魔界剧团”灵摆怪兽加入手牌。此效果发动后，直至回合结束时为止，自己仅可特殊召唤“魔界剧团”灵摆怪兽。\r\n【怪兽效果】\r\n此卡名的①③的怪兽效果1回合仅可各使用1次。①：自己的灵摆怪兽因战斗被破坏时可以发动。从手牌将此卡特殊召唤。②：此卡的攻击力上升自己墓地的“魔界剧本”魔法卡数量×100。③：“魔界剧本”魔法卡的效果发动的情况下可以发动。从牌组将1只等级4以下的“魔界剧团”灵摆怪兽特殊召唤。以此效果特殊召唤的怪兽于结束阶段放回持有者的手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78316184,'电子天使－美朱濡－','以“机械天使的仪式”降临。①：此卡仪式召唤成功的情况下可以发动。将对手场上被从额外牌组特殊召唤的怪兽全部破坏，给予对手相当于破坏的怪兽数量×１０００数值的伤害。此回合，此卡在１次战斗阶段可攻击２次。②：１回合１次，破坏场上的卡之魔法・陷阱・怪兽的效果发动时，将自己墓地的１只仪式怪兽放回牌组可以发动。将该发动无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78348934,'破坏剑士的宿命',replace(replace('“破坏剑士的宿命”的①②效果１回合各只可使用１次。\r\n①：最多可将对手墓地的３只相同种族怪兽作为对象并发动。将该怪兽除外，并挑选我方场上的１只“毁灭剑士”怪兽或“破坏剑”怪兽，直至回合结束时，该攻击力、守备力上升除外怪兽数量×５００点。\r\n②：此卡存在于墓地的场合，可从手牌舍弃１张“破坏剑”卡牌并发动。将墓地的此卡加入手牌。','\r',char(13)),'\n',char(10)),'继续除外怪兽？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78349103,'机甲部队・维和者',replace(replace('①：１回合１次，可从以下效果中选择１个发动。\r\n●以自己场上的１只机械族怪兽为对象，将此卡视为装备卡装备于该怪兽。装备怪兽将被战斗・效果破坏的情况下，破坏此卡作为代替。\r\n●将被装备的此卡特殊召唤。\r\n②：场上的此卡被破坏并被送至墓地时可以发动。从牌组将１只联合怪兽加入手牌。','\r',char(13)),'\n',char(10)),'变成装备卡','特殊召唤','检索','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78355370,'重生库里波',replace(replace('①：在自己・对手的战斗阶段结束时，从手牌将此卡舍弃，以1只在此回合因战斗被破坏并被送至自己墓地的怪兽为对象可以发动。将该怪兽特殊召唤。\r\n②：对手怪兽攻击宣言时，将墓地的此卡除外，以自己墓地任意数量的“库里波”怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78358521,'星圣 索恩布雷斯',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：从自己墓地将1只“星圣”怪兽除外，以自己墓地的1只“星圣”怪兽为对象可以发动。将该怪兽加入手牌。\r\n②：在适用了此卡①效果的回合的主要阶段可以发动。进行1只“星圣”怪兽的召唤。\r\n③：此卡被送至了墓地的回合，要召唤“星圣”怪兽的情况下，可减少1只所必须的解放。','\r',char(13)),'\n',char(10)),'选择自己墓地1只名字带有「星圣」的怪兽加入手牌','把1只名字带有「星圣」的怪兽召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78360952,'白昼狙击手',replace(replace('①：可将此卡视为魔法卡，从手牌放置在魔法与陷阱区域。\r\n②：被放置的此卡被破坏并被送至墓地的情况下，在下个回合的准备阶段可以发动。将此卡特殊召唤。然后将与此卡同一纵列的对手的卡全部破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78362751,'白鱼军贯','此卡名的①②效果１回合仅可各使用１次。①：自己场上存在“舍利军贯”或持有“舍利军贯”作为超量素材的超量怪兽的情况下可以发动。从手牌将此卡特殊召唤。②：在自己的主要阶段可以发动。从手牌特殊召唤“白鱼军贯”以外的１只“军贯”怪兽。然后，可从自己的牌组・墓地挑选任意数量的“舍利军贯”，以喜欢的顺序放在牌组最上面。','','','是否选「舍利军贯」在牌组最上面放置？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78364470,'星圣 双子波鲁克斯','①：此卡召唤时适用。此回合，自己在通常召唤之外，可在自己的主要阶段追加1次召唤1只“星圣”怪兽。','使用「星圣 双子波鲁克斯」的效果召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78371393,'尤贝尔',replace(replace('①：此卡不会因战斗被破坏，因此卡的战斗对自己造成的战斗伤害变为０。\r\n②：攻击表示的此卡在被选择为攻击对象的情况下，在该伤害计算前发动。给予对手相当于攻击怪兽的攻击力数值的伤害。\r\n③：在自己的结束阶段发动。解放自己场上１只其他的怪兽，或将此卡破坏。\r\n④：此卡因此③效果以外的方式被破坏时可以发动。从自己的手牌・牌组・墓地将１只“尤贝尔－“忌避骑士””特殊召唤。','\r',char(13)),'\n',char(10)),'伤害','破坏','是否要选择1只怪兽作为祭品？','特殊召唤','','','','','','','','','','','','');
INSERT INTO texts VALUES(78387742,'冒牌英雄','从手牌特殊召唤１只冠有“元素－英雄”之名的怪兽。以此效果特殊召唤的怪兽不可攻击，在此回合结束阶段时返回至持有者手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78391364,'超重武者 天平B－N','此卡名的②效果１回合仅可使用１次。①：对手场上存在２只以上怪兽，而自己场上不存在怪兽的情况下，此卡可从手牌中特殊召唤。②：此卡召唤・特殊召唤成功的情况下，以自己墓地“超重武者 天平B－N”以外的１只等级４以下的“超重武者”怪兽为对象可以发动。以守备表示形式将该怪兽特殊召唤。','特殊召唤','墓地怪兽特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78394032,'马达外壳',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：此卡从场上被送至墓地的情况下可以发动。将1只“马达衍生物”（机械族・地・星1・攻/守200）以攻击表示特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78394033,'马达衍生物','由“恶鬼马达Ω”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78397661,'黑衣龙之艾克利西亚',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己・对手的主要阶段可以发动。将此卡直至结束阶段为止除外，从自己牌组・墓地将1只“阿尔白斯之落胤”或记载有该卡名的等级4以下的怪兽特殊召唤。\r\n②：此卡存在于墓地的情况下，以自己墓地・除外状态的1只等级8融合怪兽和场上的1张卡为对象可以发动。将该2张卡和此卡放回牌组。','\r',char(13)),'\n',char(10)),'特殊召唤','回到牌组','直到结束阶段除外','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78402798,'骑士蜥蜴','身覆绿色鳞片，守护海洋的蜥蜴战士。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78420796,'恐啡肽骇龙・狂乱','此卡名的卡１回合仅可发动１张。①：在对手的主要阶段，支付一半LP可以发动。从牌组及额外牌组将由“恐啡肽骇龙”融合怪兽卡决定的融合素材怪兽各１只送至墓地，从额外牌组将１只该融合怪兽融合召唤。②：自己的LP为２０００以下、对手发动魔法・陷阱・怪兽的效果时，将墓地的此卡除外可以发动。此回合，因对手的效果对自己造成的效果伤害变为０。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78422252,'XX－军刀 佛兰姆骑士',replace(replace('①：只要此卡以表侧表示存在，仅限1次，对手怪兽攻击宣言时，以该1只怪兽为对象可以发动。将该攻击无效。\r\n②：此卡战斗破坏对手的守备表示怪兽时，以自己墓地的1只等级4以下的“X－军刀”怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'攻击无效','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78423643,'三头基多','有三个头的怪兽，夜行性且性格非常凶暴。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78437364,'刚鬼 巨型食人魔',replace(replace('“刚鬼”怪兽2只以上\r\n①：只要此卡存在于怪兽区域，场上怪兽的攻击力下降相当于该怪兽原本守备力的数值。②：此卡将被战斗・效果破坏的情况下，可破坏此卡连接端的1只自己的怪兽作为代替。','\r',char(13)),'\n',char(10)),'是否使用「刚鬼 巨型食人魔」的效果代替破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78437365,'刚鬼 巨型食人魔',replace(replace('“刚鬼”怪兽2只以上\r\n①：只要此卡存在于怪兽区域，场上怪兽的攻击力下降相当于该怪兽原本守备力的数值。②：此卡将被战斗・效果破坏的情况下，可破坏此卡连接端的1只自己的怪兽作为代替。','\r',char(13)),'\n',char(10)),'是否使用「刚鬼 巨型食人魔」的效果代替破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78447174,'电幻机块 插座妖',replace(replace('此卡名的效果①②在1个回合中仅可各使用1次。\r\n①：自己场上有“机块”怪兽存在时可以发动。从手牌中特殊召唤此卡。\r\n②：在此卡已经存在于怪兽区域的状态下，其他“电幻机块 插座妖”被特殊召唤至自己场上时可以发动。从牌组中特殊召唤1只“电幻机块 插座妖”。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78449284,'魅影骑士团凶恶之镰',replace(replace('暗属性等级3怪兽×2\r\n此卡名的①②③效果1回合仅可各使用1次。\r\n①：去除此卡的1个超量素材可以发动。从牌组将1只“魅影骑士团”怪兽特殊召唤。\r\n②：此卡存在于怪兽区域的状态下，自己将“超量龙”怪兽超量召唤的情况下可以发动。从牌组将1张“升阶魔法”魔法卡加入手牌。\r\n③：此卡被破坏的情况下可以发动。将超量怪兽以外的、自己除外状态的1张“魅影骑士团”卡加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','检索效果','回收效果','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78474168,'突破技能',replace(replace('①：以对手场上的1只效果怪兽为对象可以发动。将该对手怪兽的效果直至回合结束时为止无效。\r\n②：在自己回合，从墓地将不是在此回合被送至墓地的此卡除外，以对手场上的1只效果怪兽为对象可以发动。将该对手的效果怪兽的效果直至回合结束时为止无效。','\r',char(13)),'\n',char(10)),'效果无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78486968,'星圣 牡羊谢拉坦','①：此卡召唤时可以发动。从牌组将1只“星圣”怪兽加入手牌。','牌组检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78509901,'方界兽刀刃・迦楼迪亚',replace(replace('此卡不可通常召唤。\r\n我方场上的２只“方界”怪兽送入墓地的场合可特殊召唤。\r\n①：以此方法特殊召唤的此卡攻击力上升２０００。\r\n②：此卡在１次的战斗阶段中可攻击２次。\r\n③：此卡因战斗破坏了怪兽时，可以我方墓地最多３只“方界胤维贾姆”为对象发动。将此卡送入墓地，并特殊召唤对象怪兽。之后，可从牌组将１只“方界超兽爆裂・健驮尔”加入手牌。','\r',char(13)),'\n',char(10)),'是否把1只「方界超兽爆裂・健驮尔」加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78512663,'元素－英雄 熔岩新宇侠',replace(replace('“元素－英雄 新宇侠”＋“新空间人・火焰甲虫”＋“新空间人 大地鼹鼠”\r\n仅限我方场上的上述卡牌返回至持有者牌组的场合，可从额外牌组特殊召唤（不需要“融合”）。此卡的攻击力上升场上卡牌数量×４００点。此外，结束阶段时，此卡返回至持有者的额外牌组。此卡因此效果而返回至额外牌组时，场上的卡牌全部返回至持有者手牌。','\r',char(13)),'\n',char(10)),'返回牌组','返回手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78527720,'灰姑娘',replace(replace('此卡牌名的①效果１回合只可使用１次。\r\n①：此卡召唤、特殊召唤成功的场合可发动。从手牌、牌组特殊召唤１只“南瓜马车”。场地区存在有“急流山的金宫”的场合，可进一步从牌组将１张“玻璃鞋”装备此卡。\r\n②：此卡以直接攻击给予对手战斗伤害时，可以１张装备在此卡的“玻璃鞋”和场上的１只表侧表示怪兽为对象发动。将该“玻璃鞋”装备该怪兽。','\r',char(13)),'\n',char(10)),'','是否装备「玻璃鞋」？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78534861,'恐惧爪・怒刹帝利','此卡名的①效果１回合仅可使用１次。①：在自己・对手的主要阶段可以发动。从手牌将此卡特殊召唤，从自己的手牌・墓地挑选１张“怒刹帝利”卡或“恐惧爪”卡除外。②：此卡可在表侧守备表示的状态下攻击。该情况下，将此卡的守备力视为攻击力来进行伤害计算。③：自己的“怒刹帝利”怪兽或“恐惧爪”怪兽与对手怪兽进行战斗的情况下，直至回合结束时为止，该对手怪兽的效果无效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78540593,'姬葵玛莉娜','只要此卡以表侧表示存在于场上，除此卡以外的我方场上的仅１只植物族怪兽，因战斗或卡牌效果被破坏并送入墓地的场合，可选择对手场上的１张卡牌并破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78543464,'切纸九字的咒符','此卡名的卡1回合仅可发动1张。①：从手牌及自己场上的表侧表示怪兽中，将1只等级9怪兽送至墓地可以发动。自己从牌组抽2张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78552773,'苏帕伊','①：此卡因效果从场上被送至墓地时可以发动。从牌组将１只“太阳的神官”特殊召唤。以此效果特殊召唤的怪兽的攻击力变为两倍，将在此回合的结束阶段放回手牌。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78556320,'女夜魔战士','侍奉黑暗的女战士。生存的意义就是血祭对手。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78564023,'黑羽－二之太刀地中海季风','自己场上名字带有“黑羽”的怪兽与对手怪兽进行战斗的伤害步骤结束时，该对手怪兽在场上存在的情况下，从手牌将此卡送至墓地可以发动。给予对手LP１０００点伤害。','给与对手1000伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78574395,'神奇气球',replace(replace('①：１回合１次，可将任意数量的手牌送入墓地并发动。在此卡放置气球计数物，其数量与送入墓地的卡牌数相等。\r\n②：只要此卡存在于魔法＆陷阱卡区，对手场上怪兽的攻击力下降相当于此卡的气球计数物数量×３００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78577570,'六剑兽的宣誓',replace(replace('降临“六剑兽”的必备。\r\n①：从我方的手牌・场上解放合计等级达到７以上的怪兽，并从手牌仪式召唤１只“六剑兽”。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78579058,'真海龙骑－代达罗斯',replace(replace('水属性怪兽3只\r\n此卡名的①③效果1回合仅可各使用1次。\r\n①：此卡连接召唤的情况下可以发动。从牌组将1只记载有“龙都 亚特兰蒂斯”卡名的怪兽特殊召唤。\r\n②：此卡只要存在于怪兽区域，卡名视为“海”。\r\n③：在自己・对手的主要阶段，将自己场上的1张表侧表示的“海”送至墓地可以发动（应对此发动，双方不可发动效果）。将对手的手牌全部舍弃，对手依其数量抽牌。','\r',char(13)),'\n',char(10)),'适用作为连接2进行连接召唤（龙都 亚特兰蒂斯）','特殊召唤','对手丢弃并抽牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78586116,'力量提升插头','可选择我方场上１只冠有“变形斗士”之名的怪兽并发动此卡。此卡被视为装备卡，装备被选择的我方怪兽。装备怪兽不可攻击。以此效果被装备时，选择场上１只除装备怪兽以外的表侧表示怪兽发动。被选择怪兽的攻击力上升装备怪兽的攻击力数值。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78598237,'华耳琴璃・调音',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：从以下效果中挑选１个适用。自己的灵摆区域不存在“华耳琴璃”卡的情况下，要适用的效果由对手挑选。\r\n●自己恢复５００LP。自己墓地存在可特殊召唤的怪兽的情况下，进而由对手挑选其中１只，将该怪兽特殊召唤至自己场上。\r\n●自己受到５００伤害。然后，可从自己的墓地将１只等级４怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','自己回复500基本分','自己受到500伤害','是否从墓地把4星怪兽加入手牌？','','','','','','','','','','','','');
INSERT INTO texts VALUES(78610936,'超量叠光延迟','应对此卡的发动，魔法・陷阱・怪兽的效果不可发动。①：以对手场上１只拥有超量素材的超量怪兽为对象可以发动。将该怪兽的超量素材全部去除，将对象怪兽放回持有者的额外牌组。去除的超量素材中有怪兽卡的情况下，进而从墓地将该怪兽尽可能地以守备表示特殊召唤至对手场上。以此效果特殊召唤的怪兽的等级下降１。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78613627,'死亡袋鼠','①：伤害计算时，攻击守备表示的此卡的怪兽的攻击力低于此卡的守备力的情况下，伤害步骤结束时发动。将该怪兽破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78621186,'野蛮人咆哮','①：我方场上的战士族怪兽被选择为攻击对象时，或变成对手怪兽效果的对象时，可以对手场上的１只表侧表示怪兽为对象发动。给予对手相当于与该怪兽原本攻击力的伤害，将该怪兽返回至手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78625448,'编号3源数之门－叁',replace(replace('等级1的怪兽×3\r\n①：此卡在战斗中不会被破坏。\r\n②：此卡与对手怪兽进行战斗的伤害步骤结束时，去除此卡的1个超量素材后可以发动。自己场上的所有“源数”怪兽的攻击力翻倍，直至回合结束时为止。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78625592,'光之护封灵剑',replace(replace('①：在对手怪兽的攻击宣言时可支付１０００LP发动１次。使该攻击无效。\r\n②：可在对手回合将墓地的此卡除外并发动。此回合，对手怪兽不可直接攻击。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78636495,'纽特',replace(replace('①：此卡反转的场合发动。此卡的攻击力、守备力上升５００。\r\n②：此卡因与怪兽的战斗被破坏的场合发动。该怪兽的攻击力、守备力下降５００。','\r',char(13)),'\n',char(10)),'攻守上升500','攻守下降500','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78637313,'来自黑暗的呼唤','将所有以“死者苏生”效果特殊召唤出的怪兽送入墓地。只要此卡存在于场上，双方不可使用“死者苏生”。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78642798,'黄金邪教神',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：在每个自己・对手回合中1次，可以发动。确认对手的全部手牌。此卡的卡名直至结束阶段为止视为“千眼邪教神”。\r\n②：此卡被除外的情况下，或因效果被送至墓地的情况下，以对手场上的1只效果怪兽为对象可以发动。将该效果怪兽视为装备魔法卡，装备于自己场上的1只不可通常召唤的“纳祭魔”怪兽。只要以此效果装备着怪兽，装备怪兽的攻击力上升相当于其攻击力的数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78651105,'神兽王巴巴罗斯','①：此卡无需解放即可通常召唤。②：用此卡的①方法通常召唤的此卡的原本攻击力变为1900。③：此卡也可解放3只怪兽来召唤。④：用此卡的③方法召唤此卡成功的情况下发动。将对手场上的卡全部破坏。','不用解放召唤','解放3只怪兽召唤','对手场上的卡全部破坏','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78658564,'格布林突击部队','①：此卡攻击的情况下，将在战斗阶段结束时变为守备表示，直至下个自己的回合结束时为止，不可变更表示形式。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78661338,'幻创龙幻紫魅',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：对手将连接怪兽特殊召唤的情况下可以发动。从手牌将此卡特殊召唤。然后，自己抽对手场上的连接怪兽数量＋1张。然后，依对手场上的连接怪兽数量挑选自己的手牌放回牌组。\r\n②：对手发动以自己场上的怪兽为对象的魔法・陷阱・怪兽的效果时，舍弃1张手牌可以发动。将该发动无效并破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78661339,'幻创龙幻紫魅',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：对手将连接怪兽特殊召唤的情况下可以发动。从手牌将此卡特殊召唤。然后，自己抽对手场上的连接怪兽数量＋1张。然后，依对手场上的连接怪兽数量挑选自己的手牌放回牌组。\r\n②：对手发动以自己场上的怪兽为对象的魔法・陷阱・怪兽的效果时，舍弃1张手牌可以发动。将该发动无效并破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78663366,'邪蚀 雷鸟','魔法、陷阱、怪兽效果发动时可发动。将我方场上的此卡从游戏中除外。此效果在对手回合也可发动。以此效果被除外的此卡在下一个准备阶段时返回至场上，且攻击力上升３００点。“邪蚀 雷鸟”的效果１回合只可发动１次。','除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78665705,'古老咒语',replace(replace('此卡名的卡在1个回合中仅可发动1张。\r\n①：从自己的牌组、墓地选择1只“拉之翼神龙”加入手牌，此回合自己除通常召唤外，仅有1次可在自己的主要阶段上级召唤。\r\n②：除外墓地的此卡后可以发动。发动后，此回合中自己成功上级召唤了“拉之翼神龙”时，其原本攻击力、守备力为：为该上级召唤解放的怪兽的原本攻击力、守备力分别合计的数值。','\r',char(13)),'\n',char(10)),'牌组检索','准备改变攻守','使用「古老咒语」的效果上级召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78679226,'向未来的沉默',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：从牌组将记载有“光之黄金柜”卡名的１只怪兽加入手牌。自己场上存在“光之黄金柜”及记载有该卡名的怪兽的状态下，且为在自己・对手的战斗阶段发动此卡的情况下，进而双方各自抽牌，直至手牌各变为６张。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78693036,'咒雷神 宙拉',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的②效果1回合仅可使用1次。\r\n①：只要此卡存在于怪兽区域，每当对手发动卡的效果，自己恢复300LP。\r\n②：在对手回合中，支付1500LP，解放此卡，可从以下效果中选择1个发动。\r\n●将对手场上的表侧表示怪兽全部破坏。\r\n●将对手场上的表侧表示的魔法・陷阱卡全部破坏。','\r',char(13)),'\n',char(10)),'破坏效果','破坏怪兽','破坏魔陷','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78697395,'第三棺材','此卡只可通过“第一棺材”的效果上场。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78700060,'死灵骑士','此卡不可特殊召唤。效果怪兽的效果发动时，必须解放以表侧表示存在于场上的此卡。令该效果怪兽的效果的发动无效并将其破坏。','不可特殊召唤','怪物效果发动无效并破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78706415,'纤维壶','反转：将双方的手牌・场上・墓地的卡片全部放回持有者的牌组。然后，双方各从牌组抽５张卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78710386,'R.B.放克出击',replace(replace('此卡名的卡1回合仅可发动1张，此卡名的③效果1回合仅可使用1次。\r\n①：作为此卡发动时的效果处理，从牌组将“R.B.放克出击”以外的1张“R.B.”卡加入手牌。\r\n②：每当对手场上的怪兽因战斗・效果被破坏，自己就恢复500LP。\r\n③：自己场上的表侧表示的“R.B.”怪兽因效果从场上离开的情况下可以发动。从牌组将1只“R.B.”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78734254,'新空间人 水波海豚','①：１回合１次，舍弃１张手牌可以发动。确认对手的手牌，从其中挑选１只怪兽。自己场上有攻击力为所挑选怪兽的攻击力以上的怪兽存在的情况下，破坏所挑选的怪兽，给予对手５００伤害。不存在的情况下，自己受到５００伤害。','确认手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78744660,'死亡女后恶魔',replace(replace('←9 【灵摆】 9→\r\n此卡名的灵摆效果1回合仅可使用1次。\n①：以自己墓地・除外状态的1张“恶魔”魔法・陷阱卡为对象可以发动。将此卡破坏，将对象卡加入手牌。\r\n【怪兽效果】\r\n以“恶魔王座”降临\n此卡仅可通过仪式召唤方式特殊召唤。\n此卡名的①怪兽效果1回合仅可使用1次。\n①：此卡仪式召唤的情况下可以发动。将对手场上的魔法・陷阱卡全部破坏。此卡存在于额外怪兽区域的情况下，进而可将对手墓地的魔法・陷阱卡全部除外。\n②：额外怪兽区域的此卡不受其他怪兽的效果影响。','\r',char(13)),'\n',char(10)),'回收效果','破坏效果','是否除外？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78748366,'炼狱的消华',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：舍弃１张手牌可以发动。从牌组将“炼狱的消华”以外的１张“炼狱”魔法・陷阱卡加入手牌。此效果发动后，直至回合结束时为止，自己仅可召唤・特殊召唤“狱炎机”怪兽。\r\n②：自己的“狱炎机”怪兽与对手怪兽进行战斗的伤害计算后，将魔法与陷阱区域表侧表示的此卡送至墓地可以发动。将进行该战斗的双方的怪兽除外。','\r',char(13)),'\n',char(10)),'牌组检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78751195,'沉咚咚＠伊格尼斯者','此卡名的①②效果1回合仅可各使用1次。①：在自己场上有“＠伊格尼斯者”怪兽存在的情况下可以发动。从手牌将此卡特殊召唤。②：以自己墓地的1只电子界族连接怪兽为对象可以发动。将该怪兽放回额外牌组，从牌组将1张“-艾-我爱融合”加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78765160,'不知火流 轮回之阵','①：此卡只要存在于魔法与陷阱区域，卡名视为“不知火流 转生之阵”。②：１回合１次，可从以下效果中选择１个发动。●将自己场上１只表侧表示的不死族怪兽除外可以发动。此回合，自己所受到的所有伤害变为０。●以２只自己被除外的守备力０的不死族怪兽为对象可以发动。将该２只怪兽放回牌组洗牌。然后，自己从牌组抽１张。','除外并使伤害变成0','回收并抽牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78778375,'魔玩具・残酷鲸',replace(replace('“锋利小鬼”怪兽＋“绒毛动物”怪兽\r\n①：此卡融合召唤成功的情况下可以发动。挑选自己及对手场上的卡各１张并破坏。②：１回合１次，以自己场上的１只融合怪兽为对象可以发动。从牌组・额外牌组将“魔玩具・残酷鲸”以外的１张“魔玩具”卡送至墓地，对象怪兽的攻击力直至回合结束时为止，上升相当于自身原本攻击力一半的数值。此效果在对手回合中也可以发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78780140,'特伦特','目前还不断继续成长的森林大树。森林的守护神。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78783370,'穿越地狱门的枪','给予我方伤害的效果发动时可发动。因此效果发生的对我方造成的效果伤害均由对手代替承受。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78783557,'灭亡龙 维都苏',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡存在于手牌的情况下，在自己・对手的主要阶段，以场地区域的1张卡为对象可以发动。将此卡特殊召唤至对手场上，将对象卡破坏。然后，可从牌组挑选1张“灰灭”永续陷阱卡，加入手牌或放置在自己场上。\r\n②：此卡从对手场上被送至墓地的情况下可以发动。将场上的怪兽全部破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','破坏怪兽','什么都不做','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78785392,'花牌戏',replace(replace('“花牌戏”１回合仅可发动１张，发动此卡的回合中，自己仅可召唤・特殊召唤“花札卫”怪兽。\r\n①：从牌组将４只攻击力１００的“花札卫”怪兽以攻击表示特殊召唤（同名卡最多１张）。以此效果特殊召唤的怪兽的效果无效化，不可为上级召唤解放。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78789356,'黎溟界辟',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：解放自己场上的１只爬虫类族怪兽可以发动。该怪兽的等级每有２，将最多１只“溟界衍生物”（爬虫类族・暗・星２・攻／守０）特殊召唤至自己场上。\r\n②：在自己的主要阶段将墓地的此卡除外，以自己除外状态的１只爬虫类族怪兽为对象可以发动。将该怪兽放回牌组。然后，可从牌组将１只爬虫类族怪兽送至墓地。','\r',char(13)),'\n',char(10)),'','','是否从牌组把1只爬虫类族怪兽送至墓地？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78789357,'溟界衍生物','由“溟界之引水蛟”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78792195,'六武众的先导','我方场上存在有除此卡以外的冠有“六武众”之名怪兽的场合可发动。可释放我方场上的１只冠有“六武众”之名的怪兽并发动。选择场上的１只怪兽破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78794994,'战线复活的代价','①：将自己场上的1只表侧表示的通常怪兽送至墓地，可以自己或对手的墓地的1只怪兽为对象发动此卡。将该怪兽特殊召唤至自己场上，装备此卡。此卡从场上离开时该怪兽将被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78811937,'潜伏之暗','可将我方墓地的２只暗属性怪兽从游戏中除外并发动。从牌组将１只暗属性、等级４的怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78835747,'娱乐伙伴・万花筒蝎子',replace(replace('←4 【灵摆】 4→\r\n①：我方场上的光属性怪兽攻击力上升３００。\r\n【怪兽效果】\r\n①：１回合１次，可以我方场上的１只表侧表示怪兽为对象发动。此回合，该怪兽可对对手场上特殊召唤而来的所有怪兽各进行１次攻击。','\r',char(13)),'\n',char(10)),'多次攻击','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78836195,'瑞相剑究','此卡名的①②效果１回合仅可各使用１次。①：以自己场上的１只表侧表示怪兽为对象可以发动。从自己的墓地将最多５张“相剑”卡或幻龙族怪兽除外，对象怪兽的攻击力上升相当于除外数量×３００的数值。②：此卡被除外的情况下可以发动。将１只“相剑衍生物”（幻龙族・协调・水・星４・攻／守０）特殊召唤至自己场上。只要以此效果特殊召唤的衍生物存在，自己从额外牌组仅可特殊召唤同步怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78836196,'相剑衍生物','由“相剑”卡片的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78845026,'闪电调整','可选择我方场上１只等级４的光属性怪兽发动。只要被选择怪兽以表侧表示存在于场上，就被视为协调。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78859567,'分组连接',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：在自己・对手的主要阶段２可以发动。从自己的手牌・牌组・墓地挑选任意数量的等级２以下怪兽，特殊召唤至场上连接怪兽的连接端的自己场上（同名卡最多１张）。','\r',char(13)),'\n',char(10)),'是否继续选择？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78861134,'炎之剑豪','是一位武士，因跌落火山而获得掌控火焰的能力。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78864369,'还魂','将存在于我方墓地的１只反转效果怪兽返回至牌组最上面。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78868119,'深海的歌姬','①：此卡召唤时可以发动。从牌组将1只等级3以下的海龙族怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78868776,'剑斗兽 炎索',replace(replace('①：以“剑斗兽”怪兽的效果特殊召唤的此卡的原本攻击力变为２１００。\r\n②：此卡进行过战斗的战斗阶段结束时，将此卡放回牌组可以发动。从牌组将“剑斗兽 炎索”以外的１只“剑斗兽”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78872731,'十二兽 子骑',replace(replace('①：此卡召唤的情况下可以发动。从牌组将1张“十二兽”卡送至墓地。\r\n②：持有此卡作为素材的、原本种族为兽战士族的超量怪兽获得以下效果。\r\n●1回合1次，去除此卡的1个超量素材可以发动。从手牌・牌组将1只“十二兽 子骑”特殊召唤。','\r',char(13)),'\n',char(10)),'从牌组把1张「十二兽」卡送至墓地','把「十二兽 子骑」特殊召唤（十二兽 子骑）','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78876707,'神圣骑士王康斯坦丁',replace(replace('等级４“圣骑士”怪兽×２只或以上\r\n此卡牌名的①②效果１回合只可各使用１次。\r\n①：可移除此卡任意数量的超量素材，并以对手场上的卡牌为对象发动，其数量相当于该移除数量。将该卡返回至持有者手牌。\r\n②：此卡因战斗、效果被破坏并送入墓地的场合可发动。将１只除“神圣骑士王康斯坦丁”以外的“圣骑士”超量怪兽视为超量召唤从额外牌组特殊召唤，并将墓地的此卡重叠至下方当作超量素材。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78888899,'重装百夫骑兵 艾梅忒Ⅵ',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡存在于手牌・墓地的情况下，在对手回合中，以自己场上的“重装百夫骑兵 艾梅忒Ⅵ”以外的１只“百夫骑”怪兽为对象可以发动。将该怪兽视为永续陷阱卡，以表侧表示放在自己的魔法与陷阱区域，将此卡特殊召唤。此回合，自己不可特殊召唤“重装百夫骑兵 艾梅忒Ⅵ”。\r\n②：此卡视为永续陷阱卡的情况下，在自己・对手的主要阶段可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78905039,'响魔从 三角兽',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：自己的怪兽因战斗・效果被破坏的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：此卡被从场上送至墓地的情况下，以种族・属性和自己场上任一怪兽相同的、自己墓地的1只怪兽为对象可以发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78910579,'仪水镜之反魂术','①：以自己场上的１只水属性怪兽和自己墓地的２只水属性怪兽为对象可以发动。将该自己场上的水属性怪兽放回持有者的牌组，将该２只墓地的水属性怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78910832,'V型蛇 Type－L',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己的战斗阶段开始时，可从以下效果中选择1个发动。\r\n●从手牌将1只机械族怪兽特殊召唤。\r\n●从牌组将1只等级4以下的机械族・光属性怪兽送至墓地。\r\n②：此卡被破坏的情况下，以自己墓地的1只机械族・光属性怪兽为对象可以发动。将该怪兽特殊召唤。以此效果特殊召唤了原本攻击力在1200以下的怪兽的情况下，其攻击力上升1200。','\r',char(13)),'\n',char(10)),'选择效果','特殊召唤','特殊召唤','送至墓地','','','','','','','','','','','','');
INSERT INTO texts VALUES(78917791,'天威之龙仙女',replace(replace('幻龙族怪兽2只\r\n此卡名的①②效果1回合仅可各使用1次。①：舍弃1张手牌，以自己墓地的1只幻龙族怪兽为对象可以发动。将该怪兽特殊召唤。此效果发动后，直至回合结束时为止自己不可发动“天威”怪兽以外的、从额外牌组被特殊召唤的场上怪兽的效果。②：效果怪兽以外的自己的表侧表示怪兽进行战斗的攻击宣言时，以对手场上的1张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','卡片破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78922939,'废品仆从','①：自己场上存在“废品”怪兽的情况下，此卡可从手牌特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78933589,'原始之液','１回合１次，在我方主要阶段时可发动。将手牌最多２只冠有“进化龙”之名的怪兽返回至牌组并洗牌，从牌组抽取相当于返回数量的卡牌。我方场上仅可有１张“原始之液”以表侧表示存在。','手牌交换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78936551,'辙之魔妖－伡夫',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：此卡召唤・特殊召唤的情况下，以自己墓地的１只“辙之魔妖－伡夫”以外的“魔妖”怪兽为对象可以发动。将该怪兽以守备表示特殊召唤。以此效果特殊召唤的怪兽的效果无效化。\r\n②：只要此卡存在于怪兽区域，自己从额外牌组仅可特殊召唤“魔妖”怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78942513,'魂源影依永劫','①：可以自己场上的1只“影依”怪兽为对象发动。从手牌中将1张“影依”卡送至墓地。对象怪兽的攻击力・守备力上升1000点，在结束阶段变为里侧守备表示。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78949372,'威风魔灵・超级单体',replace(replace('①：自己的灵摆区域存在“威风魔灵”卡的情况下，此卡以外的“威风魔灵”卡在自己场上发动的效果的发动和效果不会被无效化。\r\n②：１回合１次，以自己墓地的５张“威风魔灵”卡为对象可以发动。将该５张卡放回牌组。然后，自己抽１张。','\r',char(13)),'\n',char(10)),'墓地回收','发动同时使用效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78984772,'爆炎龙','宇宙形成时所诞生的龙。那股冲击力使双胞胎龙合体。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78986941,'突击指令','选择我方场上以表侧表示存在的除衍生物以外的１只通常怪兽并发动，发动后，解放被选择的通常怪兽，破坏对手场上的１只怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(78990927,'巨石异物・普尔','以“巨石异物”卡降临。此卡名的①②效果１回合仅可各使用１次。①：此卡仪式召唤成功的情况下，以自己墓地的１只仪式怪兽为对象可以发动。此卡的等级变为与该怪兽相同。然后将对象怪兽加入手牌。②：在自己・对手的主要阶段可以发动。为使合计等级为仪式召唤的怪兽以上，解放自己手牌・场上的怪兽，从手牌・牌组将１只“巨石异物”仪式怪兽仪式召唤。','改变等级','仪式召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79015062,'-艾-互联互接',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：向对手出示手牌的1只电子界族怪兽可以发动。根据所出示怪兽的属性适用以下效果。此卡发动后，直至回合结束时为止自己仅可特殊召唤电子界族怪兽。\r\n●暗：将所出示的怪兽特殊召唤，从牌组将暗属性以外的1只等级4以下的电子界族怪兽加入手牌。\r\n●暗以外：将所出示的怪兽放回牌组，从牌组将1只属性与所放回怪兽不同的“＠伊格尼斯者”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79016563,'二进制女巫',replace(replace('衍生物以外的怪兽２只\r\n①：根据与此卡相互连接中的怪兽数量获得以下效果。\r\n●１只以上：与此卡相互连接中的怪兽因与对手怪兽的战斗给予对手战斗伤害时，可发动。回复相当于该数值数量的我方LP。\r\n●２只：１回合１次，可以我方场上的２只表侧表示怪兽为对象发动。直至回合结束时，该２只怪兽中１只的攻击力减半，并另１只的攻击力上升该减少数值数量。此效果在对手回合也可发动。','\r',char(13)),'\n',char(10)),'基本分回复','攻击力上升','请选择要让攻击力变成一半的怪兽','请选择要让攻击力上升的怪兽','','','','','','','','','','','','');
INSERT INTO texts VALUES(79059098,'调皮宝贝大暴走','①：在我方／对手的主要阶段可发动。从我方手牌／场上“调皮宝贝”融合怪兽卡所指定的融合素材怪兽送入墓地，并从额外牌组融合召唤该融合怪兽。发动此卡后，我方直到回合结束不能不能召唤／特殊召唤除“调皮宝贝”外的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79068663,'废品攻击','装备怪兽因战斗破坏怪兽并送入墓地时，给予对手生命相当于被破坏怪兽原本攻击力的一半数值。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79072916,'突异变种反射作用',replace(replace('仅可装备于自己场上等级８以上的“突异变种”怪兽。\r\n此卡名的②效果１回合仅可使用１次。\r\n①：装备怪兽攻击被特殊召唤的对手怪兽的伤害步骤开始时可以发动。将该对手怪兽除外。\r\n②：将装备中的此卡除外可以发动。将装备过此卡的怪兽送至墓地，将１只原本属性与该怪兽不同的等级８“突异变种”怪兽从手牌・牌组特殊召唤。','\r',char(13)),'\n',char(10)),'怪兽除外','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79080761,'巨石Ω','此卡不可通常召唤。我方墓地的２只地属性怪兽从游戏中除外的场合可特殊召唤。我方场上表侧表示的此卡因卡牌效果被送入墓地时，破坏对手场上的全部魔法、陷阱卡。','对手场上所有魔法·陷阱卡全部破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79086452,'机关傀偶－素瓷娃娃',replace(replace('①：此卡可舍弃手牌的１只“机关傀偶”怪兽来从手牌特殊召唤。\r\n②：将墓地的此卡除外可以发动。此回合中，对手不可将自己场上的“机关傀偶”怪兽作为效果的对象。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79094383,'光波异邦臣','此卡名的①②效果１回合１次，仅可使用其中１个。①：此卡存在于手牌・墓地的情况下，以自己场上的１只“光波”超量怪兽为对象可以发动。将此卡重叠在该怪兽下方作为超量素材。②：此卡被送至墓地的情况下可以发动。从牌组将１张“光波”魔法・陷阱卡加入手牌。','此卡作为超量素材','「光波」魔法·陷阱卡加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79106360,'混沌壶','①：此卡反转的情况下发动。将场上的怪兽全部放回牌组。然后，双方从自身牌组上面翻开卡，直至翻出的怪兽数量与放回各自牌组的怪兽相同为止，将其中所有等级4以下的怪兽以里侧守备表示特殊召唤至自身场上。将剩余的翻开的卡全部送至墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79109599,'沼地魔神王','①：手牌・场上・墓地的此卡，可以代替１只融合怪兽卡上记载有卡名的融合素材怪兽。在此之际，其他融合素材怪兽必须为正规素材。②：从手牌将此卡舍弃至墓地可以发动。从牌组将１张“融合”加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79126789,'暗黑界之猎人 棕布劳','①：此卡因效果从手牌被舍弃至墓地的情况下发动。自己抽1张。因对手的效果被舍弃的情况下，以此效果抽牌的张数变为2张。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79130389,'海晶少女 珊瑚海葵',replace(replace('水属性怪兽2只\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：以自己墓地的1只攻击力1500以下的水属性怪兽为对象可以发动。将该怪兽特殊召唤至此卡连接端的自己场上。此效果发动后，直至回合结束时为止自己仅可特殊召唤水属性怪兽。\r\n②：此卡从场上被送至墓地的情况下，以“海晶少女 珊瑚海葵”以外的、自己墓地的1张“海晶少女”卡为对象可以发动。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79155167,'虫甲爆破','可选择我方场上１张冠有“甲虫装机”之名的卡牌与对手场上２张表侧表示卡牌并发动。破坏被选择卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79161790,'反转世界','场上所有效果怪兽的攻击力、守备力变成攻击力与守备力互换数值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79169622,'极冰兽 极地企鹅',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：此卡特殊召唤的情况下，以对手场上的1只怪兽为对象可以发动。将该怪兽放回手牌。\r\n②：场上的此卡因战斗・效果被破坏的情况下，以对手场上的1张卡为对象可以发动。将该卡放回手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79176962,'旋风机 风神电动人',replace(replace('将此卡以表侧表示上级召唤的情况下，将解放的怪兽不送往墓地而是放回持有者的手牌。\r\n①：１回合１次，舍弃１张手牌可以发动。将对手场上与此卡同一纵列的卡全部放回持有者的手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79178930,'定时机偶炸弹','场上冠有“机偶”之名的守备表示怪兽被选择为攻击对象时可发动。破坏对手场上的所有表侧表示怪兽破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79182538,'暗黑的狂犬','原本只是一只在公园玩耍的普通小狗，受暗黑之力的影响而变得凶暴。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79185500,'铁巨人 钢铁之锤','“异次元超能人・星之罗宾”、“野兽战士 豹人”、“凤王兽 盖尔达”在自己场上全部存在的情况下，此卡可从手牌中特殊召唤。只要此卡以表侧表示存在场上，不可变更表示形式。此外，１回合１次，选择自己场上的１只表侧表示怪兽可以发动。此回合，所选择的怪兽可直接攻击对手玩家。','直接攻击','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79194594,'统合突异变种怪',replace(replace('属性不同的“突异变种”怪兽×２\r\n此卡名的①②③效果１回合仅可各使用１次。\r\n①：此卡融合召唤成功的情况下，以场上的１张卡为对象可以发动。将该卡破坏。\r\n②：对手发动效果时可以发动。此回合，表侧表示的此卡不受该效果及相同种类（怪兽・魔法・陷阱）的对手效果的影响。\r\n③：融合召唤的此卡被对手破坏的情况下可以发动。挑选自己１张被除外的“突异变种”卡加入手牌。','\r',char(13)),'\n',char(10)),'卡片破坏','效果免疫','加入手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79205581,'强制终了','战斗阶段时，将此卡以外的自己场上的１张卡送往墓地可以发动此效果。结束战斗阶段。','战斗阶段结束','是否现在使用「強制終了」的效果？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79206750,'深渊触手','可选择我方场上的１只冠有“水精鳞”之名的怪兽并发动。被选择怪兽的攻击力直至回合结束时上升１０００点。此外，被盖牌的此卡被送入墓地时，选择对手场上的１只怪兽并送入墓地。','怪兽送墓','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79206925,'守墓的异能者',replace(replace('“守墓”怪兽×２\r\n此卡牌名的③效果１回合只可使用１次。\r\n①：此卡的攻击力、守备力上升作为此卡的融合素材怪兽的原本等级合计×１００。\r\n②：只要场上存在有“王家长眠之谷－死灵谷”，此卡及我方场地区的卡牌不会因效果被破坏。\r\n③：在我方主要阶段可发动。在此回合的结束阶段，从牌组将１只“守墓”怪兽或１张“死灵谷”卡牌加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79210531,'星骑士 天琴琉拉',replace(replace('此卡名在规则上也视为“星圣”卡。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：“星骑士 天琴琉拉”以外的“星骑士”、“星圣”怪兽被召唤至自己场上的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：此卡召唤・反转召唤・特殊召唤的情况下可以发动。从牌组将1张“星骑士”魔法卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79229522,'嵌合要塞龙',replace(replace('“电子龙”＋机械族怪兽1只以上\r\n此卡从额外牌组仅可在将自己・对手场上的上述卡送至墓地的情况下特殊召唤。\r\n此卡不可作为融合素材。\r\n①：此卡原本的攻击力变为相当于作为此卡融合素材的怪兽数量×1000的数值。','\r',char(13)),'\n',char(10)),'请选择一只「电子龙」','请选择1只以上的机械族怪兽','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79234734,'超战士之魂','此卡名的①②效果１回合仅可各使用１次。①：将手牌的１只“混沌士兵”怪兽送至墓地可以发动。直至下一个对手的结束阶段为止，此卡的攻击力变为３０００，卡名视为“混沌士兵”。②：将墓地的此卡除外可以发动。从牌组将１只“开辟之骑士”或“宵暗之骑士”加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79266769,'暗钢龙 暗铁',replace(replace('种族・属性相同的效果怪兽2只以上\r\n此卡名的效果1回合仅可使用1次。\r\n①：以自己墓地・除外状态的1只怪兽为对象可以发动。将该怪兽以守备表示特殊召唤至此卡连接端的自己场上。以此效果特殊召唤的怪兽的效果无效化，从场上离开的情况下放回牌组最下面。此效果发动后，直至回合结束时为止自己不可特殊召唤连接怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79279397,'D少年组','反转：可从牌组以攻击表示特殊召唤任意数量的“D少年组”。之后，我方受到以此效果特殊召唤怪兽的数量×１０００点伤害。','特殊召唤','是否要进行特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79306385,'宣告者之神讬','“崇光之宣告者”的降临所必需。应对此卡的发动，对手不可发动魔法・陷阱・怪兽的效果。①：为使合计等级为１２以上，解放自己手牌・场上的怪兽，从手牌将“崇光之宣告者”仪式召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79323590,'魔力枷锁','双方玩家若不支付５００LP，则不可从手牌中通常召唤・特殊召唤・发动・放置卡片。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79324191,'隐密忍法帖','①：１回合１次，从手牌中将１只“忍者”怪兽送入墓地并发动。从牌组挑选１张除“隐密忍法帖”以外的“忍法”魔法、陷阱卡盖牌至我方场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79333300,'风灵术－「雅」','①：解放自己场上的1只风属性怪兽，以对手场上的1张卡为对象可以发动。将该对手的卡放回持有者牌组的最下面。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79335209,'扰乱怪之黑色','是人称不择手段捣乱的扰乱怪三人组的一员。据说只要三人到齐就会有什么发生。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79337169,'臂铠战士','可解放此卡并发动。我方场上所有战士族怪兽的攻击力・守备力上升５００点，直至该怪兽进行战斗的伤害步骤结束时被适用。此效果在对手回合也可发动。','攻守上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79339613,'灵魂能力MAX！！',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己场上有原本属性为神属性的“欧贝利斯克之巨神兵”存在的情况下，解放自己场上其他２只表侧表示怪兽可以发动。将对手场上的怪兽全部破坏，给予对手４０００伤害。\r\n②：在自己・对手的主要阶段及战斗阶段，将墓地的此卡除外可以发动。从自己的牌组・墓地挑选１只“欧贝利斯克之巨神兵”加入手牌。然后，可召唤１只“欧贝利斯克之巨神兵”。','\r',char(13)),'\n',char(10)),'是否召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79371769,'清扫龙女的困境',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：怪兽被召唤・特殊召唤至自己场上的情况下可以发动（同一连锁上最多1次）。从自己的牌组上面将1张卡送至墓地。\r\n②：此卡因效果从牌组被送至墓地的情况下，以“清扫龙女的困境”以外的、1张此回合被送至自己墓地的卡为对象可以发动。将该卡加入手牌。此效果发动后，直至下个自己回合结束时为止，自己不可发动以此效果加入手牌的卡及其同名卡的效果。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79371897,'增援部队',replace(replace('此卡牌名的①效果１回合只可使用１次。\r\n①：我方战士族怪兽进行战斗的攻击宣言时可发动。从手牌特殊召唤１只等级４或以下的战士族怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79383919,'断罪之咒眼',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：自己场上存在“咒眼”怪兽，魔法・陷阱卡发动时可以发动。将该发动无效并破坏。自己的魔法与陷阱区域有“塞勒涅的咒眼”存在的情况下，此卡的发动与效果不会被无效化。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79387392,'反应机史莱姆','此卡名的①②效果1回合仅可各使用1次。①：在自己的主要阶段可以发动。将2只“史莱姆怪兽衍生物”（水族・水・星1・攻/守500）特殊召唤至自己场上。此回合，自己仅可召唤・特殊召唤幻神兽族怪兽。②：在自己・对手的战斗阶段解放此卡可以发动。从自己的手牌・牌组・墓地挑选1张“金属反射史莱姆”放置在自己的魔法与陷阱区域。以此效果放置的卡在放置的回合中也可以发动。','','','适用「反应机史莱姆」的效果来发动','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79387393,'史莱姆怪兽衍生物','由“软泥增殖炉”等的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79400597,'静冠的咒眼',replace(replace('此卡牌名的卡牌１回合只可发动１张。\r\n①：此卡也可从我方墓地将１张“咒眼”卡牌除外并发动。该场合，我方从牌组抽取１张卡牌。\r\n②：１回合１次，装备有“塞勒涅的咒眼”的我方的“咒眼”怪兽在攻击了对手的伤害计算后可发动。将该对手怪兽除外。\r\n③：魔法与陷阱区域的此卡因效果被破坏的场合，最多可以３张被除外的我方的“咒眼”卡牌为对象发动。将该卡牌返回至墓地。','\r',char(13)),'\n',char(10)),'是否除外墓地「咒眼」卡并抽牌？','请选择要回到墓地的卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79402185,'键结－D2O',replace(replace('此卡牌名的②效果１回合只可使用１次。\r\n①：可解放我方手牌・场上的２只“氘魔兽”和１只“氧魔兽”并发动。从我方的手牌・牌组・墓地挑选１只“水合龙”或“水合龙－团簇”并将其视为“键结－H２O”的效果特殊召唤。\r\n②：此卡存在于墓地，且“水合龙”或“水合龙－团簇”从场上被送入我方墓地的场合发动。将墓地的此卡返回至手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79407975,'究极宝玉神 彩虹暗黑龙','此卡不可通常召唤。仅可在从自己墓地将7种暗属性怪兽各1只除外的情况下特殊召唤。①：从自己墓地及自己场上的表侧表示怪兽中，将此卡以外的暗属性怪兽全部除外可以发动。此卡的攻击力上升除外数量×500。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79409334,'暗黑剑龙','当场上以表侧攻击表示存在的此卡被选择为攻击对象时，将此卡的表示形式变为守备表示。','变成守备表示','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79415624,'蛇眼断罪龙',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己・对手的主要阶段，以自己或对手场上（表侧表示）・墓地的1只怪兽为对象可以发动。将该怪兽视为永续魔法卡，以表侧表示放在原本持有者的魔法与陷阱区域。在下个回合，此卡不可使用此效果。\r\n②：在自己・对手的战斗阶段，以场上的1只怪兽和场上的1张永续魔法卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'放置到魔陷区','破坏效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79418153,'枪兵恶魔','１回合１次，以对手的守备怪兽为攻击对象的我方怪兽的攻击宣言时可发动。该战斗中该怪兽攻击了守备表示怪兽的场合，若其攻击力超过守备力，给予对手生命相当于该差值的战斗伤害。','穿刺伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79418928,'电磁石战士贝塔',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将除“电磁石战士贝塔”以外的1只等级4以下的“磁石战士”怪兽加入手牌。\r\n②：在对手回合中，解放此卡可以发动。从牌组将1只等级4的“磁石战士”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'加入手牌','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79436874,'R.B.沃肯火箭',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次，且②效果1回合仅可使用1次。\r\n①：自己场上的表侧表示怪兽，不存在的情况下或均为“R.B.”怪兽的情况下，此卡可从手牌特殊召唤。\r\n②：此卡和“R.B.”连接怪兽为连接状态的情况下，支付1000LP，以对手场上的最多2张卡为对象可以发动。将该卡及此卡破坏，给予对手所破坏的数量×500的伤害。','\r',char(13)),'\n',char(10)),'','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79441381,'黄昏的忍者－上弦',replace(replace('←1 【灵摆】 1→\r\n①：我方的“忍者”怪兽攻击了守备表示怪兽的场合，给予对手攻击力超过该守备力数值的战斗伤害。\r\n【怪兽效果】\r\n①：可向对手展示手牌的１张“忍法”卡牌并发动。从手牌特殊召唤此卡。\n②：此卡攻击了守备表示怪兽的场合，给予攻击力超过该守备力数值的战斗伤害。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79444933,'炎之魔精 伊格尼斯','释放我方场上表侧表示存在的１只炎属性怪兽发动。给予对手生命相当于我方墓地中存在的炎属性怪兽数量×１００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79447365,'卡通面具','①：自己场上存在“卡通世界”的情况下，以对手场上的1只表侧表示怪兽为对象可以发动。从手牌・牌组将1只等级在该怪兽的等级・阶级的数值以下的卡通怪兽无视召唤条件特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79473793,'青冰的白夜龙',replace(replace('①：以此卡为对象的魔法、陷阱卡发动时发动。使该发动无效并破坏。\r\n②：除此卡以外的我方表侧表示怪兽被选择为攻击对象时，可将我方场上１张魔法、陷阱卡送入墓地并发动。将攻击对象移转至此卡。','\r',char(13)),'\n',char(10)),'无效并破坏','改变攻击对象','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79480466,'魂喰魔兽 巴祖',replace(replace('等级4怪兽×3\r\n①：只要此卡存在于怪兽区域，从怪兽被去除的超量素材不去墓地而直接被除外。\r\n②：怪兽卡被送至墓地的情况下可以发动（同一连锁上最多1次）。去除此卡的１个超量素材。\r\n③：此卡的超量素材全部被去除的情况下，以自己・对手墓地的合计3张卡为对象可以发动。将该卡作为此卡的超量素材。','\r',char(13)),'\n',char(10)),'','取除超量素材','获取超量素材','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79491903,'爬虫妖・那伽','①：此卡不会因战斗被破坏。②：此卡与怪兽进行战斗的战斗阶段结束时发动。将该怪兽的攻击力改成0。③：此卡以守备表示存在的情况下，在自己的结束阶段发动。将表侧守备表示的此卡改为表侧攻击表示。','攻击变成0','变成表侧攻击表示','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79509511,'银河超航行',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：将自己除外状态的1只光・暗属性怪兽特殊召唤。\r\n②：此卡存在于墓地的状态下，自己场上表侧表示的超量怪兽被除外的情况下，将此卡除外，以其中1只为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','除外并特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79514956,'幻奏音女 埃蕾姬',replace(replace('①：只要此卡存在于怪兽区域，自己场上被特殊召唤的“幻奏”怪兽不会因效果被破坏。\r\n②：只要特殊召唤的此卡存在于怪兽区域，自己场上的天使族怪兽的攻击力上升３００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79519259,'夜翼祭司',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡特殊召唤的情况下可以发动。从自己手牌・牌组・墓地将1张“爆裂模式”放置在自己场上。以此效果放置的卡在放置的回合也可以发动。\r\n②：舍弃1张手牌可以发动。从牌组挑选1只记载有“爆裂模式”卡名的怪兽，加入手牌或特殊召唤。此回合，自己从额外牌组仅可特殊召唤同步怪兽。','\r',char(13)),'\n',char(10)),'放置','检索','适用「夜翼祭司」的效果来发动','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79523365,'吸血鬼猩红灾星','这个卡名的①的效果1个回合只可使用1次。①：这张卡召唤・特殊召唤成功的情况下，支付1000LP，可以“吸血鬼猩红灾星”以外的自己墓地1只“吸血鬼”怪兽为对象发动。特殊召唤该怪兽。用这个效果特殊召唤的怪兽在这个回合不可攻击。②：这张卡在通过战斗破坏怪兽的战斗阶段结束时可以发动。将该怪兽从墓地尽可能往自己场上进行特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79531196,'水晶蔷薇',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：1回合1次，在自己的主要阶段可以发动。从手牌・牌组将1只“宝石骑士”怪兽或“幻奏”怪兽送至墓地。此卡直至结束阶段为止，视为送至墓地的怪兽的同名卡。\r\n②：此卡存在于墓地的情况下，从自己墓地将1只融合怪兽除外可以发动。将此卡以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79538761,'扭力调整齿轮',replace(replace('①：１回合１次，可以发动以下的１个效果。\r\n●以自己场上的１只表侧表示怪兽为对象，将此卡视为装备魔法卡装备。装备怪兽将被战斗・效果破坏的情况下，作为代替将此卡破坏。\r\n●将装备状态的此卡特殊召唤。\r\n②：装备怪兽的攻击力・守备力上升５００，视为协调。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79544790,'悔恨苏生','我方场上的怪兽因战斗被破坏并送入墓地时可发动。选择１只该怪兽并以表侧守备表示特殊召唤至我方场上。以此效果特殊召唤的怪兽在我方结束阶段时被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79552283,'恐惧爪・牙掌突','此卡名的②效果１回合仅可使用１次。①：１回合１次，以自己场上的１只“恐惧爪”怪兽或“维萨思・史塔弗罗斯特”为对象可以发动。此回合，该怪兽可在表侧守备表示的状态下攻击。该情况下，适用攻击力和守备力中较高一方的数值进行伤害计算。②：额外怪兽区域存在自己的“恐惧爪”怪兽、对手发动效果时，将魔法与陷阱区域的表侧表示的此卡送至墓地可以发动。将该效果无效。','守备表示攻击','对手效果无效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79555535,'点火阵 凤凰',replace(replace('①：场上的“点火骑士”怪兽的攻击力・守备力上升３００。\r\n②：１回合１次，以自己场上的１张“点火骑士”卡为对象可以发动。将该卡破坏，从牌组将１张“点火骑士”卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79559912,'DDD 怒涛大王执行凯撒',replace(replace('恶魔族等级6怪兽×2\r\n①：包含将怪兽特殊召唤的效果在内的、怪兽的效果・魔法・陷阱卡发动时，去除此卡的1个超量素材可以发动。将该发动无效并破坏。然后，可使此卡与自己场上的1只“DD”怪兽的攻击力直至回合结束时为止上升1800。\r\n②：此卡从场上被送至墓地的情况下可以发动。从牌组将1张“契约书”卡加入手牌。','\r',char(13)),'\n',char(10)),'发动无效并破坏','是否选怪兽上升攻击力？','牌组「契约书」卡加入手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79561872,'怦然期待的梅尔菲们',replace(replace('“梅尔菲”怪兽＋兽族怪兽\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡融合召唤的情况下，以相同数量的、自己场上的“梅尔菲”卡及对手场上的卡为对象可以发动。将该卡放回手牌。\r\n②：对手将怪兽召唤・特殊召唤的情况下，或此卡被选择为对手怪兽的攻击对象的情况下，以自己墓地的1只兽族怪兽为对象可以发动。此卡的等级下降2，将对象怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'回到手牌','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79569173,'大地震','我方场上的恐龙族怪兽被破坏送入墓地时，可指定对手未使用的３处魔法＆陷阱卡区发动此卡。只要此卡存在于场上，指定的魔法＆陷阱卡区不可使用。此卡在发动后第３回合的我方准备阶段中被破坏。之后，可选择我方墓地的１只恐龙族怪兽返回至手牌。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79571449,'天使的施舍','从自己的牌组抽３张卡，然后挑选２张手牌舍弃。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79575620,'注射天使 莉莉','①：每次此卡进行战斗的伤害计算时１次，支付２０００LP可以发动。此卡的攻击力仅在该伤害计算时上升３０００。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79580323,'剑斗兽斯巴达克思','此卡不可以“剑斗兽霍普洛姆斯”以外的效果特殊召唤。此卡特殊召唤成功时，可从牌组将１张冠有“斗器”之名的装备魔法卡加入手牌。此卡进行了战斗的战斗阶段结束时，可将此卡返回至持有者牌组并发动。从牌组特殊召唤１只除“剑斗兽斯巴达克思”以外的冠有“剑斗兽”之名的怪兽。','检索牌组','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79582540,'战华之暴－董颖',replace(replace('此卡名的①③效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将1只等级7以上的“战华”怪兽或1张“战华”永续魔法・永续陷阱卡加入手牌。\r\n②：只要自己场上存在于等级7以上的“战华”怪兽，对手必须支付400LP才可以发动卡的效果。\r\n③：怪兽被送至对手墓地的情况下，以对手墓地的1张卡为对象可以发动。将该卡除外，自己抽1张。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79600447,'冥铭途・颅骨爆发',replace(replace('此卡名的②效果在同一连锁上仅可发动１次。\r\n①：只要自己场上存在“冥铭途”怪兽，可攻击的对手怪兽必须攻击其中攻击力最高的怪兽。\r\n②：对手发动场上怪兽的效果时，以自己场上的１只“冥骸合龙－冥铭途拉尔泰库特利卡”为对象可以发动。该怪兽的攻击力・守备力下降１０００，将该发动的效果无效。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79606837,'虹光之宣告者',replace(replace('协调＋协调以外的怪兽１只以上\r\n①：只要此卡存在于怪兽区域，从双方手牌・牌组被送至墓地的怪兽不去墓地而直接被除外。\r\n②：怪兽的效果・魔法・陷阱卡发动时，解放此卡可以发动。将该发动无效并破坏。\r\n③：此卡被送至墓地的情况下可以发动。从牌组将１只仪式怪兽或１张仪式魔法卡加入手牌。','\r',char(13)),'\n',char(10)),'无效并破坏','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79613121,'黑混沌之魔导・极限',replace(replace('以“混沌形态”降临。\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡特殊召唤成功的情况下，解放自己场上的１只怪兽可以发动。此回合，对手不可发动怪兽的效果。\r\n②：此卡战斗破坏对手怪兽时，以自己墓地的１张魔法卡为对象可以发动。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79625003,'闪光编号37 蜘蛛鲨',replace(replace('水属性等级5怪兽×3\r\n此卡也可重叠在自己场上的“编号37 希望织龙 蜘蛛鲨”上面来超量召唤。\r\n①：1回合1次，去除此卡的1个超量素材，以对手场上的1只怪兽为对象可以发动。将该怪兽直至下个对手的准备阶段除外，对手场上存在怪兽的情况下，那些怪兽的攻击力直至回合结束时为止下降1000。\r\n②：在超量召唤的此卡被破坏并被送至墓地的回合的结束阶段可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'是否在「编号3７ 希望织龙 蜘蛛鲨」上面重叠来超量召唤？','除外','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79627627,'半缠鸟官－翻飞鸟',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡存在于手牌的情况下，在自己・对手的战斗阶段中，以场上的1只里侧表示怪兽为对象可以发动。将该怪兽送至墓地，将此卡以里侧守备表示特殊召唤。\r\n②：此卡反转的情况下可以发动。从牌组将除“半缠鸟官－翻飞鸟”以外的1只等级5以上的反转怪兽以里侧守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'从牌组特殊召唤','此卡特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79629370,'月明少女','被月亮守护的月之魔导士。会用神秘的魔法展现幻象。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79636594,'积木蜘蛛',replace(replace('“积木蜘蛛”的②效果１回合只可使用１次。\r\n①：只要此卡存在于怪兽区，对手不可将其他的昆虫族怪兽作为攻击对象。\r\n②：此卡特殊召唤成功的场合可发动。从牌组特殊召唤１只“积木蜘蛛”。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79649195,'铠甲爆裂','令装备魔法卡的发动无效并将其破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79656239,'芬芳炽天使－香甜马郁兰',replace(replace('协调＋协调以外的怪兽１只以上\r\n此卡名的①③效果１回合仅可各使用１次。\r\n①：此卡同步召唤的情况下可以发动。从牌组将“润泽之风”、“干渴之风”、“惠畅之风”中的任意１张加入手牌。\r\n②：只要自己的LP多于对手，且此卡存在于怪兽区域，对手不可将自己场上的植物族怪兽作为效果的对象。\r\n③：自己的LP恢复的情况下，以对手场上的１张卡为对象发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','','对方卡破坏','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79663524,'油蝉',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。自己场上的所有昆虫族怪兽的等级下降1。\r\n②：此卡的表示形式被变更的情况下可以发动。从自己手牌・牌组・墓地将1只“油蝉”特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79698395,'未界域－欧玛利亚大陆','①：只要此卡存在于场地区域，自己场上的“未界域”怪兽在被特殊召唤的回合不会成为对手效果的对象。②：1回合1次，以自己场上的1只“未界域”怪兽为对象可以发动。只要该怪兽和此卡以表侧表示存在于自己场上，该怪兽可直接攻击，不会成为攻击对象（仅有适用此效果的怪兽存在于自己场上的状态下，对手的攻击变为对自己的直接攻击）。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79703905,'云魔物－高层云','此卡不会因战斗而被破坏。此卡以表侧守备表示存在的场合，被破坏。此卡召唤成功时，在此卡放置雾计数物，其数量相当于场上冠有“云魔物”之名怪兽的数量。可移除场上的３个雾计数物并发动。随机舍弃１张对手手牌。','放置计数物','丢弃手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79707116,'麻痹锁链','每当通过卡片的效果将卡片从对手的牌组送至墓地时，给予对手LP３００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79718768,'急转直下','对手以墓地的卡牌为对象发动了魔法、陷阱、效果怪兽的效果的场合，破坏此卡。此卡因此效果被破坏并送入墓地时，对手将墓地的所有卡牌返回至牌组。','返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79724755,'黄纺鮄 黄鲂二重奏',replace(replace('此卡名的①②③效果１回合仅可各使用１次。\r\n①：此卡特殊召唤成功的情况下可以发动。依自己场上的水属性怪兽的数量，从对手的牌组上面将卡除外。\r\n②：以自己场上的１只等级４以下的水属性怪兽为对象可以发动。该怪兽的等级上升相当于其原本等级的数值。\r\n③：将墓地的此卡除外可以发动。挑选场上的１只水属性怪兽，其攻击力直至回合结束时为止，上升相当于被除外的怪兽数量×１００的数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79747096,'混沌编号1 混沌源数之门－零',replace(replace('等级2的怪兽×4\r\n此卡也可重叠在自己场上的“编号1源数之门-壹”上方进行超量召唤。\r\n①：此卡在超量召唤成功时发动。将场上的怪兽全部除外。\r\n②：此卡被除外时，在自己的下一个准备阶段可以发动。特殊召唤已被除外的此卡。自己的场地区域存在“源数网络”卡时，会给对手造成进一步伤害，伤害值为已被除外的自己与对手的超量怪兽攻击力的合计值。','\r',char(13)),'\n',char(10)),'是否在「编号1 源数之门-壹」上面重叠来超量召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79755671,'星宿法宫 格拉梅尔',replace(replace('“星宿”怪兽＋手牌的怪兽\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：自己发动“星宿”卡的效果时，以对手场上的1张卡为对象可以发动。将该卡破坏。\r\n②：此卡存在于墓地的状态下，有2只以上的怪兽同时被送至墓地的情况下可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'破坏效果','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79757784,'幻奏音女 唐唐',replace(replace('①：自己场上存在“幻奏”怪兽，且此卡特殊召唤的情况下可以发动。从自己的牌组・墓地将１张“融合”加入手牌。\r\n②：此卡作为融合召唤的素材被送至墓地的情况下，以自己场上的１只“幻奏”怪兽为对象可以发动。该怪兽的攻击力下降５００，给予对手５００伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79759367,'魔幻甜点玩偶之夜','①：自己的墓地不存在怪兽，且怪兽的效果发动时可以发动。将该发动无效。自己场上存在“魔幻甜点・布丁公主”的情况下，进而随机将对手的１张手牌放回牌组。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79759861,'对死者的奠仪','①：可弃置１张手牌，将场上的１只怪兽作为对象发动此卡。破坏该怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79766336,'黑暗中的陷阱','①：自己的生命值为３０００以下时，支付１０００LP，以“黑暗中的陷阱”以外的自己的墓地的１张通常陷阱卡为对象可以发动。此卡的效果变成和该墓地的通常陷阱卡发动时的效果相同。然后，将该墓地的通常陷阱卡除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79775821,'兽带斗士・站起来啊','此卡名的①②效果１回合１次，仅可使用其中１个。①：以自己墓地的１只“兽带斗士”怪兽为对象可以发动。将该怪兽特殊召唤。然后，可从自己的手牌・墓地挑选１只“兽带斗士”怪兽，视为装备卡装备于该怪兽。②：在双方的主要阶段将墓地的此卡除外，以自己场上・墓地的各１只“兽带斗士”怪兽为对象可以发动。将该墓地的怪兽视为装备卡，装备于该自己场上的怪兽。','是否选怪兽装备？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79777187,'护罩泡泡',replace(replace('①：只要此卡存在于魔法与陷阱区域，自己场上的所有“娱乐伙伴”怪兽及“娱乐巫师”怪兽１回合各仅１次，不会因战斗・效果被破坏。\r\n②：只要此卡存在于魔法与陷阱区域，因自己场上的“娱乐伙伴”怪兽及“娱乐巫师”怪兽的战斗产生的对自己的战斗伤害变为０。','\r',char(13)),'\n',char(10)),'「护罩泡泡」的效果已经适用一次','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79783880,'逢魔之妖刀－不知火',replace(replace('此卡名的效果１回合仅可使用１次。\r\n①：解放此卡，以除“逢魔之妖刀－不知火”以外的、包含“不知火”怪兽在内的、自己除外状态的２只不死族怪兽为对象可以发动。将该怪兽以守备表示特殊召唤。以此效果特殊召唤的怪兽的效果无效化。此效果发动后，直至回合结束时为止自己仅可特殊召唤不死族怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79785958,'邪蚀 卡斯托尔','此卡召唤成功的回合，我方除了通常召唤以外，仅１次，可再召唤１只冠有“邪蚀”之名的怪兽。','使用「邪蚀鬼·北河二」的效果召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79791695,'混沌超量 冀望皇龙混沌巴利安龙',replace(replace('等级7怪兽×3只以上\r\n此卡也可重叠在自己场上的“混沌编号101”～“混沌编号107”中的任一“混沌编号”怪兽上面来超量召唤。\r\n①：此卡的攻击力上升此卡超量素材的数量×1000的数值。\r\n②：只要此卡持有“混沌编号”怪兽作为超量素材，对手不可用抽牌以外的方法从牌组将卡加入手牌。\r\n③：1回合1次，去除此卡的1个超量素材可以发动。从对手牌组上面将2张卡作为此卡的超量素材。','\r',char(13)),'\n',char(10)),'是否要在自己场上的怪兽上面叠放来超量召唤？','得到超量素材','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79791696,'混沌超量 冀望皇龙混沌巴利安龙',replace(replace('等级7怪兽×3只以上\r\n此卡也可重叠在自己场上的“混沌编号101”～“混沌编号107”中的任一“混沌编号”怪兽上面来超量召唤。\r\n①：此卡的攻击力上升此卡超量素材的数量×1000的数值。\r\n②：只要此卡持有“混沌编号”怪兽作为超量素材，对手不可用抽牌以外的方法从牌组将卡加入手牌。\r\n③：1回合1次，去除此卡的1个超量素材可以发动。从对手牌组上面将2张卡作为此卡的超量素材。','\r',char(13)),'\n',char(10)),'是否要在自己场上的怪兽上面叠放来超量召唤？','得到超量素材','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79791878,'光之黄金柜',replace(replace('此卡名的②③效果１回合仅可各使用１次。\r\n①：此卡只要存在于魔法与陷阱区域，不会因怪兽的效果被破坏。\r\n②：在自己的主要阶段可以发动。从牌组将除“光之黄金柜”之外的、记载有“光之黄金柜”卡名的１张卡加入手牌。\r\n③：对手从墓地特殊召唤怪兽的情况下，从手牌将１张魔法卡舍弃，以其中１只为对象可以发动。将该怪兽送至墓地。','\r',char(13)),'\n',char(10)),'检索','送至墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79794767,'无形噬体・愤怒',replace(replace('←3 【灵摆】 3→\r\n此卡的控制者在每个自己的准备阶段解放自己场上的１只怪兽。\n或不解放而是破坏此卡。\n①：只要“无形噬体”怪兽存在于自己场上，双方不可解放“无形噬体”怪兽以外的怪兽。\r\n【怪兽效果】\r\n①：只要灵摆召唤・反转的此卡存在于怪兽区域，双方从额外牌组仅可特殊召唤“无形噬体”怪兽。','\r',char(13)),'\n',char(10)),'是否解放自己场上1只怪兽？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79796561,'同步抱手','１回合１次，在我方主要阶段１发动。选择我方场上１只同步怪兽并从游戏中除外，给予对手生命６００点伤害。以此效果除外的怪兽，将在下一个我方准备阶段时返回至场上。','除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79798060,'地缚神 Ccarayhua',replace(replace('①：“地缚神”怪兽在场上仅可有１只以表侧表示存在。\r\n②：此卡可直接攻击。\r\n③：对手怪兽不可将此卡选择为攻击对象。\r\n④：不存在表侧表示的场地魔法卡的情况下，此卡将被破坏。\r\n⑤：此卡因其他卡的效果被破坏的情况下发动。将场上的卡全部破坏。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79814787,'传说的白石','①：此卡被送至墓地的情况下发动。从牌组将１只“青眼白龙”加入手牌。','加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79816536,'召唤师之技法','①：从牌组将1只等级5以上的通常怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79844764,'帝王的烈旋',replace(replace('此卡名的卡1回合仅可发动1张，发动此卡的回合中，自己不可从额外牌组特殊召唤怪兽。\r\n①：此回合，自己要上级召唤怪兽的情况下，仅限1次，可解放对手场上的1只怪兽作为自己场上1只怪兽的代替。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79850798,'暴走特急 火箭飞矢',replace(replace('此卡不可通常召唤。\r\n仅可在自己场上不存在卡的情况下特殊召唤。\r\n将此卡特殊召唤的回合中，自己无法进行战斗阶段。\r\n此卡的控制者在每个自己的准备阶段，将手牌全部送至墓地或将此卡破坏。\r\n①：只要此卡存在于怪兽区域，自己不可发动魔法・陷阱・怪兽的效果，不可放置卡。','\r',char(13)),'\n',char(10)),'效果选择','是否要把手牌全部送至墓地？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79852326,'死灵佐玛',replace(replace('①：此卡发动后变成效果怪兽（不死族・暗・星４・攻１８００／守５００），以守备表示特殊召唤至怪兽区域。此卡也视为陷阱卡。\r\n②：以此卡的效果特殊召唤的此卡因战斗被破坏的情况下发动。给予对手破坏此卡的怪兽的攻击力数值的伤害。','\r',char(13)),'\n',char(10)),'伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79853073,'光波尖兵','此卡在计算与战士族怪兽战斗的伤害时发动。此卡的攻击力、守备力仅限该伤害计算时上升２０００点。','攻守上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79856792,'究极宝玉神 彩虹龙',replace(replace('此卡不可通常召唤。\r\n仅可在自己场上・墓地存在7种“宝玉兽”卡的情况下特殊召唤。\r\n此卡特殊召唤的回合，此卡的①②效果不可发动。\r\n①：在自己・对手回合中，将自己场上表侧表示的“宝玉兽”怪兽全部送至墓地可以发动。此卡的攻击力上升相当于送至墓地的怪兽数量×1000的数值。\r\n②：从自己墓地将“宝玉兽”怪兽全部除外可以发动。将场上的卡全部放回牌组。','\r',char(13)),'\n',char(10)),'攻击力上升','场上的卡全部回到持有者牌组','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79858629,'驱魔姐妹・怡莱努',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从手牌将1张“驱魔姐妹”卡放回牌组最下面可以发动。自己抽1张。自己场上存在“驱魔姐妹・索菲亚”的情况下，自己进而恢复800LP。\r\n②：有自己或对手的卡因对手从墓地离开的情况下可以发动。从额外牌组将1只“驱魔姐妹”超量怪兽重叠在自己场上的此卡上面，视为超量召唤特殊召唤。','\r',char(13)),'\n',char(10)),'','超量召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79859067,'R.B.下一阶段',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：自己场上存在“R.B.”怪兽，且对手发动怪兽的效果时可以发动。将自己场上的1只怪兽破坏，将该发动无效并破坏。然后，自己恢复2000LP。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79861914,'妖仙大旋风',replace(replace('可支付８００LP发动此卡。\r\n①：１回合１次，我方场上表侧表示的“妖仙兽”怪兽返回至手牌的场合，可以对手场上的１张卡牌为对象发动。将该卡返回至持有者手牌。\r\n②：在我方回合未适用此卡的①效果的场合，此卡在该回合的结束阶段被破坏。','\r',char(13)),'\n',char(10)),'回到手牌','此卡破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79864860,'捕食植物 三首剧毒穗叶藤龙',replace(replace('场上的暗属性怪兽×３\r\n此卡名的②③效果１回合仅可各使用１次。①：此卡的攻击力上升相当于场上此卡以外放有捕食计数物的怪兽的原本攻击力合计的数值。②：此卡是被融合召唤的情况下，对手从额外牌组特殊召唤怪兽之际可以发动。将该特殊召唤无效，将该怪兽破坏。③：对手场上的怪兽上放有捕食计数物的情况下可以发动。将此卡从墓地以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79867938,'燃烧拳斗士 护头',replace(replace('①：此卡召唤时可以发动。从牌组将１只“燃烧拳斗士”怪兽送至墓地。\r\n②：攻击表示的此卡１回合仅１次，不会因战斗被破坏。','\r',char(13)),'\n',char(10)),'送墓','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79868386,'神拳粉碎',replace(replace('此卡名的卡1回合仅可发动1张。此卡的发动和效果不会被无效化。①：自己场上有原本卡名为“欧贝利斯克之巨神兵”的怪兽存在的情况下可以发动。挑选对手场上的1只效果怪兽，将其效果无效并破坏。此回合，以此效果破坏的怪兽及原本卡名与该怪兽相同的怪兽的效果无效化。此卡在自己的主要阶段发动的情况下，可进而适用以下效果。\r\n●将对手场上的魔法・陷阱卡全部破坏。','\r',char(13)),'\n',char(10)),'是否把对手场上的魔法·陷阱卡全部破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79870141,'猛进剑角兽','此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予战斗伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79875176,'卡通加农炮斗士','召唤・反转召唤・特殊召唤此卡的回合中此卡不可进行攻击。我方场上有“卡通世界”存在且对手场上没有卡通怪兽存在的场合，此卡可直接攻击对手玩家。当场上的“卡通世界”被破坏时，破坏此卡。解放１只我方场上的怪兽，给予对手生命５００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79875526,'附属电子翼',replace(replace('此卡名的③效果1回合仅可使用1次。\r\n①：以自己场上的1只龙族・机械族的“电子”怪兽为对象可以发动。从自己手牌・场上将此卡视为装备魔法卡装备于该怪兽。\r\n②：装备此卡的怪兽的攻击力上升600。\r\n③：装备于怪兽的此卡被送至墓地的情况下，以自己墓地的1只其他的龙族・机械族的“电子”怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79890560,'占卜魔女 小风',replace(replace('此卡牌名的①②效果１回合只可各使用１次。\r\n①：抽取到此卡时，可向对手展示此卡并发动。从手牌特殊召唤此卡。\r\n②：此卡从手牌特殊召唤成功的场合，可以１只我方被除外的魔法师族怪兽为对象发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79905468,'守护龙 普罗米奈喜思','此卡名的②效果1回合仅可使用1次。①：将手牌・场上的此卡送至墓地，以自己场上的1只龙族怪兽为对象可以发动。该怪兽的攻击力・守备力直至对手回合结束时为止上升500。②：此卡存在于墓地，通常怪兽被送至自己墓地的情况下可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡离开场上的情况下，将其除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79912449,'御巫之幻惑轮舞',replace(replace('可装备于对手场上的怪兽。\r\n此卡名的卡1回合仅可发动1张。\r\n①：“御巫之幻惑轮舞”在自己场上仅可有1张以表侧表示存在。\r\n②：只要自己场上存在“御巫”怪兽，则获得装备怪兽的控制权。\r\n③：装备怪兽只要存在于自己场上，则不可发动效果。\r\n④：此卡从场上离开时，装备怪兽将被送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79922118,'糖果屋',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：在对手的准备阶段可以发动。对手场上的所有怪兽的攻击力上升６００。然后，将对手场上攻击力２５００以上的怪兽全部破坏，自己恢复相当于所破坏怪兽数量×５００的LP。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79928401,'勇气天使 维多利卡',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡特殊召唤成功的情况下可以发动。从手牌将１只等级５以上的光属性怪兽特殊召唤，自己失去相当于该怪兽原本攻击力数值的LP。以此效果特殊召唤的怪兽的攻击力直至回合结束时为止变为两倍。\r\n②：怪兽区域的此卡被破坏的情况下，从自己的墓地将此卡以外的１只天使族怪兽除外可以发动。将１只等级与所除外的怪兽相同的天使族怪兽从牌组加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79933029,'皮尔莉・莉莉',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将速攻魔法卡以外的1张“皮尔莉”卡加入手牌。\r\n②：以自己墓地的1张“皮尔莉”速攻魔法卡为对象可以发动。从额外牌组将1只记载有该卡名的超量怪兽重叠在自己场上的此卡上面视为超量召唤特殊召唤，将对象卡作为该超量怪兽的超量素材。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79936051,'北十字炮击',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：自己场上怪兽的合计等级为10以上的情况下可以发动。从手牌・牌组挑选1只等级10怪兽，加入手牌或特殊召唤。\r\n②：对手场上怪兽的合计等级为10以上的情况下，从自己墓地将此卡与1只等级10怪兽除外，以对手场上的1张卡为对象可以发动。将该卡除外。','\r',char(13)),'\n',char(10)),'发动','除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79965360,'亚马逊的秘宝','仅限装备冠有“亚马逊”之名的怪兽。装备怪兽在１个回合中有１次机会不会因战斗而被破坏。装备怪兽进行攻击的场合，在伤害计算后破坏受到该攻击的怪兽。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79966218,'血树龙姬 朵拉塞蕾尔',replace(replace('此卡名的①②效果1回合仅可各使用1次，发动此效果的回合中，自己仅可特殊召唤龙族・植物族怪兽。\r\n①：从牌组将除“血树龙姬 朵拉塞蕾尔”以外的1只等级4以下的植物族怪兽送至墓地可以发动。从手牌将此卡特殊召唤。以此效果特殊召唤的此卡的等级变为与送至墓地的怪兽相同。\r\n②：从自己墓地将此卡与1只植物族怪兽除外可以发动。从自己手牌・墓地将1只龙族怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79967395,'娱乐伙伴・鞭子蛇','①：１回合１次，可以场上的１只表侧表示的怪兽为对象发动。直至回合结束时，该怪兽的攻击力、守备力互换。仅限于双方主要阶段此效果可发动。','攻守互换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79968632,'六武众之影忍术',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：将自己场上的1只怪兽送至墓地，以自己除外状态的1只“六武众”怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79972330,'幻蝶刺客－凤蝶','除此卡以外的我方场上怪兽给予对手生命战斗伤害时，选择对手场上１只表侧表示怪兽发动。被选择怪兽的攻击力下降，其数值相当于那时给予的伤害数值。','攻击下降','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79979666,'元素－英雄 泡沫人',replace(replace('①：手牌仅有此1张卡的情况下，此卡可从手牌特殊召唤。\r\n②：此卡召唤・反转召唤・特殊召唤时可以发动（此效果在自己手牌・场上不存在其他卡的情况下才能发动和处理）。自己抽2张。','\r',char(13)),'\n',char(10)),'特殊召唤','抽牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79985120,'急袭猛禽－革命猎鹰－大空袭',replace(replace('鸟兽族等级６怪兽×３\r\n此卡也可舍弃手牌的１张“升阶魔法”魔法卡，来重叠在自己场上阶级５以下的“急袭猛禽”超量怪兽上面超量召唤。①：此卡超量召唤成功的情况下，以对手场上的１只怪兽为对象可以发动。破坏该怪兽，给予对手相当于其攻击力数值的伤害。②：此卡因对手被破坏并被送至墓地的情况下可以发动。从额外牌组将１只“急袭猛禽－革命猎鹰”特殊召唤，将此卡重叠在下方作为超量素材。','\r',char(13)),'\n',char(10)),'是否在5阶以下的「急袭猛禽」超量怪兽上面重叠来超量召唤？','对手怪兽破坏','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(79997591,'双重巴塞舞姿','①：对手怪兽对我方场上表侧攻击表示怪兽进行攻击宣言时可发动。给予对手相当于攻击对象怪兽的攻击力数值的伤害，该对手怪兽的攻击会转成对我方的直接攻击。该我方怪兽在下一次的我方回合可直接攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80015408,'纠罪巧－反转裁诞',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从自己手牌・场上（表侧表示）将任意数量的“纠罪巧”怪兽卡放回牌组。然后，自己依放回的数量抽牌。\r\n②：此卡存在于墓地的状态下，对手将怪兽召唤・特殊召唤的情况下，将此卡除外，可从以下效果中选择1个发动。\r\n●从手牌将1只“纠罪巧”怪兽以里侧守备表示特殊召唤。\r\n●将自己场上的1只里侧守备表示的“纠罪巧”怪兽改成表侧守备表示。','\r',char(13)),'\n',char(10)),'发动','选择效果','特殊召唤','改变表示形式','','','','','','','','','','','','');
INSERT INTO texts VALUES(80019195,'传说骑士 蒂迈欧',replace(replace('此卡不可通常召唤。\r\n仅可以“传说之心”的效果特殊召唤。\r\n①：此卡特殊召唤成功时，可以场上表侧表示的１张魔法、陷阱卡为对象发动。将该表侧表示的魔法、陷阱卡除外。\r\n②：此卡被选择为攻击对象时，可以我方墓地的１张魔法卡为对象发动。将该卡牌盖牌至我方场上。','\r',char(13)),'\n',char(10)),'除外','放置','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80032567,'朱罗纪・巨兽龙',replace(replace('协调＋协调以外的恐龙族怪兽1只以上\r\n①：只要此卡存在于怪兽区域，自己场上的“朱罗纪”怪兽的攻击力上升相当于自己墓地的“朱罗纪”怪兽的数量×200的数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80033124,'电子黑暗冲击！','①：将自己手牌・场上・墓地的“电子暗黑角”、“电子暗黑刃”、“电子暗黑骨”各1张作为融合素材放回牌组，将1只“铠黑龙－电子暗黑龙”融合召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80036543,'通往活路的希望','①：自己的LP比对手少１０００以上的情况下，支付１０００LP可以发动。双方的LP每差２０００，自己从牌组抽１张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80040886,'碧钢机龙',replace(replace('协调＋协调以外的怪兽1只以上\r\n①：此卡特殊召唤的情况下，以自己墓地的协调数量为上限，以对手场上的表侧表示卡为对象可以发动。将该卡的效果直至回合结束时为止无效。\r\n②：同步召唤的此卡因效果被破坏并被送至墓地的情况下，以自己墓地的1只协调为对象可以发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80044027,'御巫之火丛舞',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从自己手牌・墓地将1只“御巫”怪兽特殊召唤，并装备此卡。然后，可从对手墓地将1只怪兽效果无效并特殊召唤至对手场上。\r\n②：装备怪兽不会因效果被破坏。','\r',char(13)),'\n',char(10)),'','是否选对手怪兽在对手场上特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80045583,'古代机械齿轮炮台','可解放此卡并发动。给予对手生命５００点伤害，此回合的战斗阶段中，双方不可发动陷阱卡。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80054655,'叉路小走鹃',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：有协调被送至自己墓地的情况下可以发动（伤害步骤也可以发动）。从手牌・墓地将此卡特殊召唤。除此卡以外的、“废品战士”或记载有该卡名的怪兽存在于场上的情况下，进而可将对手场上的攻击力1900以上的怪兽全部改为守备表示。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。此回合，自己从额外牌组仅可特殊召唤同步怪兽。','\r',char(13)),'\n',char(10)),'特殊召唤','是否改变表示形式？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80071619,'R.B.牧者权杖',replace(replace('包含“R.B.”怪兽在内的怪兽2只以上\r\n此卡名的②③效果1回合仅可各使用1次。\r\n①：此卡的攻击力上升自己场上的其他怪兽的数量×500的数值。\r\n②：在自己的主要阶段可以发动。从自己牌组・墓地将1张“R.B.”陷阱卡放置在自己场上。\r\n③：在对手的主要阶段，以自己墓地的3只等级3以上的“R.B.”怪兽为对象可以发动。将其中2只以喜欢的顺序放回牌组下面，将另1只以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'放置陷阱','回到牌组并特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80071763,'魔人 黑暗巴尔塔',replace(replace('“凭依的血魂”＋“边境的大贤者”\r\n此卡的融合召唤，只能用上述卡进行。通常魔法卡发动时可以通过支付１０００LP，使该效果无效。并且，此卡战斗破坏的效果怪兽的效果也可无效化。','\r',char(13)),'\n',char(10)),'效果无效化','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80073414,'绝对超能者',replace(replace('念动力族同步怪兽＋同步怪兽\r\n此卡从额外牌组仅可通过融合召唤来特殊召唤。\r\n此卡名的③效果1回合仅可使用1次。\r\n①：此卡融合召唤的情况下，支付2000LP可以发动。将对手场上的表侧表示卡全部除外。\r\n②：此卡只要存在于怪兽区域，不会因效果被破坏。\r\n③：从墓地将不是在此回合被送至墓地的此卡除外可以发动。从额外牌组将1只念动力族・等级10融合怪兽视为融合召唤特殊召唤。','\r',char(13)),'\n',char(10)),'除外','','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80075749,'泡沫幻象','我方场上存在有“元素－英雄 泡沫人”的场合可发动。此回合，我方可从手牌发动１张陷阱卡。','适用「泡沫幻象」的效果来发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80086070,'北斗天熊－帝车','此卡不可同步召唤，仅可在从自己场上将等级差为7的、1只等级8以上的协调和1只协调以外的同步怪兽送至墓地的情况下特殊召唤。①：此卡特殊召唤成功的情况下，以场上此卡以外的最多2张卡为对象可以发动。将该卡破坏。②：1回合1次，以自己场上“北斗天熊”卡为对象的卡的效果发动时，解放自己手牌・场上的1只怪兽可以发动。将该发动无效。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80088625,'二进制剑士',replace(replace('通常怪兽２只\r\n①：根据和此卡相互连接着的怪兽数量，获得以下效果。\r\n●１只以上：此卡攻击对手怪兽的攻击宣言时可以发动。此回合，此卡在１次战斗阶段中可攻击２次，此卡与对手怪兽进行战斗的情况下，该对手怪兽不会因该战斗被破坏。\r\n●２只：此卡与对手怪兽进行战斗的伤害计算后可以发动。将该对手怪兽除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80101899,'陷阱诡计',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从牌组将“陷阱诡计”以外的1张通常陷阱卡除外，从牌组将1张该卡的同名卡放置在自己场上。以此效果放置的卡在放置的回合也可以发动。此卡发动后，直至回合结束时为止自己仅可发动1张陷阱卡。','\r',char(13)),'\n',char(10)),'适用「陷阱诡计」的效果来发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80101900,'陷阱诡计',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从牌组将“陷阱诡计”以外的1张通常陷阱卡除外，从牌组将1张该卡的同名卡放置在自己场上。以此效果放置的卡在放置的回合也可以发动。此卡发动后，直至回合结束时为止自己仅可发动1张陷阱卡。','\r',char(13)),'\n',char(10)),'适用「陷阱诡计」的效果来发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80102359,'强化人 赛克','将我方墓地中的１只念动力族怪兽从游戏中除外发动此卡。此卡的攻击力上升５００点。此效果在１个回合中最多可使用２次。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80108118,'X－军刀 乌尔贝尔姆',replace(replace('协调＋协调以外的怪兽1只以上\r\n①：此卡给予对手战斗伤害的情况下，如果对手手牌为4张以上则发动。随机将对手的1张手牌放回牌组最上面。','\r',char(13)),'\n',char(10)),'返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80117527,'编号11 大眼',replace(replace('等级7怪兽×2\r\n①：1回合1次，去除此卡的1个超量素材，以对手场上的1只怪兽为对象可以发动（发动此效果的回合中，此卡不可攻击）。获得该怪兽的控制权。','\r',char(13)),'\n',char(10)),'得到控制权','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80141055,'魔守熊',replace(replace('①：只要此卡存在于怪兽区，对手回合期间，盖牌于我方魔法与陷阱区域的卡牌不会因效果而被破坏。\r\n②：每次盖牌于我方魔法与陷阱区域的卡牌因对手效果被破坏即发动。此卡的攻击力直至回合结束时上升８００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80141480,'猎手蜘蛛','布置蜘蛛网来进行狩猎，吞食落入网中的猎物。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80143954,'幻变骚灵・伪装','①：以自己场上的1只“幻变骚灵”怪兽为对象可以发动此卡。此卡视为装备卡装备给该怪兽。装备怪兽不会成为对手怪兽的攻击对象。（仅有适用此效果的怪兽存在于自己场上的状态下，对手的攻击变为对自己的直接攻击。）②：以装备怪兽为对象发动的对手怪兽的效果无效化。③：自己场上的“幻变骚灵”卡将被战斗・效果破坏的情况下，可将墓地的此卡除外作为代替。','是否使用「幻变骚灵・伪装」的效果代替破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80159717,'龙骑兵团骑士－三叉之枪',replace(replace('龙族协调＋协调以外的鸟兽族怪兽1只以上\r\n①：1回合1次，将自己场上的最多3张卡送至墓地可以发动。确认对手的额外牌组，依为发动此效果而送至了墓地的数量，将卡送至墓地。','\r',char(13)),'\n',char(10)),'确认额外牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80161395,'神秘的中华锅','可解放我方场上的１只怪兽，选择攻击力或守备力发动。我方LP回复相当于被解放怪兽的该数值。','请选择要回复的数值','怪兽的攻击力','怪兽的守备力','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80163754,'爆裂龙息','①：可解放我方场上的１只龙族怪兽并发动。破坏所有持有守备力为被解放怪兽攻击力以下的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80168720,'暗的到访','弃置２张手牌。选择表侧表示的１只怪兽，维持其攻防状态并将其变为里侧表示。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80170678,'EN－交战新宇空间','此卡名的卡１回合仅可发动１张，发动此卡的回合中，自己从额外牌组仅可特殊召唤融合怪兽。①：将１只“新空间人”怪兽和１只“元素－英雄”怪兽送至墓地可以发动（从手牌及牌组各送１只）。从牌组将１只“新空间人”怪兽或等级５以上的“元素－英雄”怪兽特殊召唤，从自己的牌组・墓地挑选１张“融合”加入手牌。以此效果特殊召唤的怪兽是“元素－英雄 新宇侠”的情况下，其攻击力上升１０００。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80181649,'“K9刑侦案件”',replace(replace('此卡名的卡1回合仅可发动1张，此卡名的③效果1回合仅可使用1次。\r\n①：作为此卡发动时的效果处理，可从牌组将1只“K9”怪兽加入手牌。\r\n②：对手发动过手牌・墓地的怪兽的效果的回合，自己场上的“K9”怪兽的攻击力上升900。\r\n③：魔法与陷阱区域的此卡因效果被破坏的情况下可以发动。从自己牌组・墓地将1张“K9”速攻魔法卡放置在自己场上。','\r',char(13)),'\n',char(10)),'发动','','放置','是否把卡加入手牌？','','','','','','','','','','','','');
INSERT INTO texts VALUES(80186010,'杀手恐龙','可从手牌将此卡舍弃至墓地并发动。从牌组将１张“侏罗纪世界”加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80190753,'樱姬塔莉雅','此卡的攻击力上升相当于我方场上的植物族怪兽数量×１００点。只要此卡以表侧表示存在于场上，双方场上除此卡以外的植物族怪兽不会因卡牌效果被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80193355,'救出剧','可在以场上冠有“亚马逊”之名的怪兽为对象的卡牌发动时发动此卡。令成为对象的怪兽卡回到持有者的手牌中，然后从手牌中特殊召唤另１只怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80193356,'救出剧','可在以场上冠有“亚马逊”之名的怪兽为对象的卡牌发动时发动此卡。令成为对象的怪兽卡回到持有者的手牌中，然后从手牌中特殊召唤另１只怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80196387,'天启的蔷薇之钟',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：从牌组将1只攻击力2400以上的植物族怪兽加入手牌。\r\n②：将墓地的此卡除外可以发动。从手牌将1只攻击力2400以上的植物族怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'牌组检索','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80204957,'机偶借金藏','①：以自己场上的１只“机偶”怪兽为对象可以发动。从牌组将１只等级４以下的“机偶”怪兽加入手牌，变更对象怪兽的表示形式。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80208158,'异次元超能人・星之罗宾','只要此卡以表侧表示存在于场上，对手不可将自己场上的其他怪兽作为攻击对象，也不可将之作为效果的对象。此外，对手的直接攻击宣言时可以发动。将此卡从墓地以守备表示特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将被从游戏除外。“异次元超能人・星之罗宾”在场上仅可有１只以表侧表示存在。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80208225,'星宿之刺毒',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：以对手墓地的怪兽和魔法・陷阱卡最多各1张为对象可以发动。将该卡除外。然后，可适用以下效果。\r\n●将“星宿之刺毒”以外的、自己墓地・除外状态的1张“星宿”卡放回牌组最下面。然后，自己抽1张。','\r',char(13)),'\n',char(10)),'发动','是否回收并抽牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80208323,'异界棘紫兽','此卡存在于墓地，且我方场上的怪兽因战斗被破坏并送入墓地时，可从墓地特殊召唤此卡。以此效果特殊召唤的此卡从场上离开的场合，从游戏中被除外。“异界棘紫兽”的效果１回合只可发动１次。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80230510,'被埋葬的祭品','①：此回合，我方进行必须解放２只怪兽的上级召唤的场合，仅限１次，可无需解放２只怪兽从我方・对手墓地各除外１只怪兽进行上级召唤。此效果发动后，直至回合结束时，我方不可特殊召唤怪兽。','把墓地怪兽除外上级召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80233946,'哥拉龟','只要此卡以表侧表示存在于场上，攻击力１９００或以上的怪兽不可进行攻击宣言。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80234301,'棱镜人','晶莹剔透的水晶体。收集光线后发射激光。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80237445,'古遗物－妙尔尼尔','此卡名的③效果１回合仅可使用１次。①：此卡可视为魔法卡从手牌放置在魔法与陷阱区域。②：放置在魔法与陷阱区域的此卡在对手回合被破坏并送至墓地的情况下发动。将此卡特殊召唤。③：在对手回合中，此卡特殊召唤成功的情况下，以自己墓地的１只“古遗物”怪兽为对象发动。以守备表示形式将该怪兽特殊召唤。此效果发动后，直至下个回合结束时为止，自己仅可特殊召唤“古遗物”怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80244114,'星尘幻影','我方场上的此卡因对手被破坏并送入墓地时可发动。从我方墓地选择１只“星尘龙”，并以守备表示特殊召唤。此外，可将墓地的此卡从游戏中除外，并选择我方场上的１只龙族同步怪兽发动。被选择怪兽１回合仅１次不会因战斗被破坏，适用此效果的伤害步骤结束时，攻击力、守备力下降８００点。','特殊召唤','战斗破坏耐性','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80250185,'自动枪弹龙','此卡名的①②效果1回合仅可各使用1次。①：以场上的此卡为对象的连接怪兽的效果发动时可以发动。将此卡破坏。然后，挑选1张场上的魔法・陷阱卡送至墓地。②：场上的此卡因战斗・效果被破坏并被送至墓地的回合的结束阶段可以发动。从牌组将1只“自动枪弹龙”以外的“枪弹”怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80250319,'灰篮史莱姆Jr.',replace(replace('①：此卡召唤成功时，可以我方墓地的１只“灰篮”怪兽为对象发动。特殊召唤该怪兽。之后，可从手牌特殊召唤１只与以此效果特殊召唤而来的怪兽相同等级的水族怪兽。此效果发动后，直至回合结束时，我方只可特殊召唤水属性怪兽。\r\n②：此卡因战斗被破坏并送入墓地时可发动。从牌组特殊召唤１只“灰篮”怪兽。','\r',char(13)),'\n',char(10)),'从墓地特殊召唤','是否从手牌把水族怪兽特殊召唤？','从牌组特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80254726,'黑鸟闭幕',replace(replace('自己场上存在“黑羽”同步怪兽或“黑翼龙”的情况下，此卡也可从手牌发动。\r\n①：对手发动场上的怪兽的效果时，将自己场上的1只表侧表示的“黑羽”怪兽送至墓地可以发动。将该发动无效并破坏。然后，可从额外牌组将1只“黑翼龙”特殊召唤。','\r',char(13)),'\n',char(10)),'是否特殊召唤「黑双足翼龙」？','适用「黑鸟闭幕」的效果来发动','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80275707,'小丑鸟 笑盈盈海鹦','此卡名的①②效果１回合仅可各使用１次。①：场上存在表侧表示的魔法・陷阱卡的情况下可以发动。从手牌将此卡特殊召唤。②：解放自己场上的１只鸟兽族怪兽，以场上的１张表侧表示魔法・陷阱卡为对象可以发动。将该表侧表示的卡放回持有者的手牌。此回合，自己不可发动以此效果放回手牌的卡及该卡的同名卡的效果。自己场上的怪兽仅有鸟兽族怪兽的情况下，此效果在对手回合中也可以发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80280737,'爆裂模式','①：解放自己场上的1只同步怪兽可以发动。从牌组将包含该怪兽卡名的1只“／爆裂”怪兽以攻击表示特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80280944,'巨大恐龙','此卡名的②效果１回合仅可使用１次。①：此卡不可直接攻击。②：此卡被除外的情况下可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡的攻击力上升相当于自己被除外的恐龙族怪兽数量×２００的数值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80304126,'魔导女武神','①：只要此卡存在于怪兽区域，对手不可将其他的魔法师族怪兽作为攻击对象。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80312545,'七精解门',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：作为此卡发动时的效果处理，从牌组将“神炎皇乌利亚”、“降雷皇哈蒙”、“幻魔皇拉比艾尔”中的任意1只，或记载有其中任一卡名的1只怪兽加入手牌。\r\n②：1回合1次，舍弃1张手牌可以发动。从自己墓地将1只攻击力和守备力为0的恶魔族怪兽特殊召唤。\r\n③：1回合1次，自己场上存在等级10怪兽的情况下可以发动。从自己墓地将1张永续魔法卡加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','墓地回收','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80316585,'神鹰女郎・电子紧身装束','此卡的卡名规则上视为“神鹰女郎”。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80320877,'终刻决坏',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：以自己场上的1只“终刻”超量怪兽为对象可以发动此卡。将此卡视为拥有以下效果的装备卡，装备于该怪兽。\r\n●对手不可以抽牌以外的方法从牌组将卡加入手牌。\r\n②：此卡因效果被破坏的情况下，以场上的1只表侧表示怪兽为对象可以发动。从牌组将1只“终刻”怪兽视为装备魔法卡，装备于对象怪兽。','\r',char(13)),'\n',char(10)),'此卡装备','从牌组装备','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80321197,'深红剑士',replace(replace('协调＋协调以外的怪兽1只以上\r\n①：此卡战斗破坏对手怪兽并将其送至墓地的情况下发动。下个对手回合，对手不可召唤・特殊召唤等级5以上的怪兽。','\r',char(13)),'\n',char(10)),'召唤限制','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80326401,'青之眼的祈祷',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：舍弃１张手牌可以发动。从牌组将除“青之眼的祈祷”以外的、记载有“青眼白龙”卡名的１张魔法・陷阱卡，和１只光属性・等级１协调加入手牌。\r\n②：将墓地的此卡除外，以自己场上的１只“青眼白龙”为对象可以发动。从额外牌组将１只“青眼”怪兽视为攻击力上升４００的装备魔法卡，装备于对象怪兽。','\r',char(13)),'\n',char(10)),'检索','装备','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80335817,'刻剑之魔术师',replace(replace('←2 【灵摆】 2→\r\n①：只要此卡存在于灵摆区域，１回合１次，自己场上的灵摆怪兽不会因对手的效果被破坏。\r\n【怪兽效果】\r\n①：仅手牌的此卡灵摆召唤成功时可以发动。此卡的攻击力变为原本攻击力的两倍。\n②：１回合１次，以场上的１只怪兽为对象可以发动。将该怪兽和场上的此卡直至下一个自己的准备阶段为止除外。','\r',char(13)),'\n',char(10)),'请选择要回到场上的卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80344569,'新空间人 大地鼹鼠','①：此卡与对手怪兽进行战斗的伤害步骤开始时可以发动。将该对手怪兽和此卡放回持有者的手牌。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80352158,'磁石反转','①：以自己墓地・除外状态的1只不可通常召唤的机械族・岩石族怪兽为对象可以发动。将该怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80367387,'核成双剑士','每次我方的结束阶段，此卡的控制者从手牌将１张“核成之钢核”送入墓地，或向对手展示１只手牌的战士族怪兽。或者，不执行上述两项直接破坏此卡。此卡因战斗破坏对手怪兽的场合，可连续再进行１次攻击。','选择一张「核成之钢核」送至墓地','选择一只战士族怪物给对手观看','破坏「核成双剑士」','继续攻击','','','','','','','','','','','','');
INSERT INTO texts VALUES(80368942,'虫茧派对','我方墓地每存在１种冠有“新空间人”之名的怪兽，就从牌组特殊召唤１只冠有“茧状体”之名的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80402389,'大树海','场上表侧表示的昆虫族怪兽因战斗或卡牌效果被破坏并送入墓地时，该怪兽的控制者可从牌组将１只与被破坏怪兽相同等级的昆虫族怪兽加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80433039,'随风飘飘游×鸵鸵','此卡名的①③效果１回合仅可各使用１次，发动此效果的回合中，自己不可将怪兽特殊召唤。①：此卡召唤成功的情况下，以自己或对手墓地的１张卡为对象可以发动。将该卡除外。然后，可召唤１只鸟兽族怪兽。②：表侧表示的此卡离开场上的情况下，将其除外。③：此卡在被除外的状态下，鸟兽族怪兽被召唤至自己场上的情况下可以发动。将此卡加入手牌。','','此卡加入手牌','是否把鸟兽族怪兽召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80441106,'凯尔多','当此卡因战斗而被破坏送入墓地时，从对手的墓地中选择２张卡牌加入到对手牌组并进行洗牌。','返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80447641,'森之忍者 蝠宝',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次，且②效果1回合仅可使用1次。\r\n①：场地区域存在表侧表示卡的情况下，此卡可从手牌特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下，如果自己场上或墓地存在“童话序章 启程之晓光”则可以发动。从牌组将1只兽族・光属性怪兽加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80453041,'尤贝尔的魅影',replace(replace('“尤贝尔”怪兽＋攻击力与守备力为０的恶魔族怪兽\r\n仅可在将自己的手牌・场上・墓地的上述卡放回牌组・额外牌组的情况下特殊召唤。\r\n此卡不可作为融合素材。\r\n此卡名的②效果１回合仅可使用１次。\r\n①：此卡不会因战斗被破坏，因此卡的战斗对自己造成的战斗伤害变为０。\r\n②：对手怪兽的效果发动时，解放此卡可以发动。该效果变为“对手将自身的手牌・牌组・场上的１只“尤贝尔”怪兽破坏”。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80457744,'推进战士','①：自己场上有协调存在的情况下，此卡可从手牌以守备表示特殊召唤。②：只要此卡存在于怪兽区域，自己场上的战士族怪兽的攻击力上升300。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80461466,'冥界魔象',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：此卡特殊召唤的情况下，如果自己场上存在“冥界魔象”以外的不死族怪兽或“活死人的呼唤”，则以场上的1张卡为对象可以发动。将该卡破坏。\r\n②：持有此卡作为超量素材的不死族超量怪兽获得以下效果。\r\n●此卡的攻击力上升1000。','\r',char(13)),'\n',char(10)),'破坏','上升攻击力','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80476891,'进化合兽九头蛇龙',replace(replace('①：只要此卡存在于场上、墓地，被视为通常怪兽。\r\n②：被视为场上的通常怪兽的此卡，可作为通常召唤再１次召唤。此种场合此卡被视为效果怪兽获得以下效果。\r\n●此卡以外的二重怪兽召唤成功时可发动。该怪兽的攻击力、守备力上升５００点。\r\n●我方场上的二重怪兽因效果被破坏的场合，可破坏我方场上的１张卡牌作为代替。','\r',char(13)),'\n',char(10)),'攻击力·守备力上升','是否作为代替把自己场上1张卡破坏？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80485722,'吸血鬼杀手','此卡与暗属性怪兽进行战斗的伤害步骤开始时发动。破坏该怪兽。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80495985,'光子剑齿虎','①：此卡召唤・反转召唤成功时可以发动。从牌组将1只“光子剑齿虎”加入手牌。②：自己场上没有其他“光子剑齿虎”存在的情况下，此卡的攻击力下降800。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80513550,'悲惨结局女王龙','此卡不可通常召唤。我方场上的永续魔法卡是３张或以上的场合可特殊召唤。因此卡的攻击给予对手生命战斗伤害时，对手挑选１张手牌并送入墓地，我方从牌组抽取１张卡牌。此外，此卡从场上被送入墓地的场合，在我方准备阶段时，可将我方场上１张表侧表示的永续魔法卡送入墓地并发动。从墓地特殊召唤此卡。','抽牌','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80516007,'珍鱼','“结融体”＋“恍惚人鱼”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80529459,'废铁盗龙','此卡名的①②效果１回合仅可各使用１次。①：以自己场上的１只怪兽为对象可以发动。将该怪兽破坏。此回合自己除通常召唤外仅追加１次，可在自己的主要阶段召唤１只“废铁”怪兽。②：此卡因“废铁”卡的效果被破坏并被送至墓地的情况下可以发动。从牌组将１张“废铁工厂”或协调以外的１只“废铁”怪兽加入手牌。','','','使用「废铁盗龙」的效果召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80532587,'旧神努茨',replace(replace('同步怪兽＋超量怪兽\r\n仅可在将自己场上的上述卡送至墓地的情况下特殊召唤。\r\n自己１回合仅可特殊召唤１次“旧神努茨”。\r\n①：１回合１次，在自己的主要阶段可以发动。从手牌将１只等级４怪兽特殊召唤。\r\n②：此卡被送至墓地的情况下，以场上的１张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80534031,'善德风暴',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：以自己场上的１只鱼族・海龙族・水族怪兽和对手场上的２张卡为对象可以发动。将该卡破坏。\r\n②：将墓地的此卡除外，以场上的１只表侧表示怪兽为对象可以发动。该怪兽为水属性的情况下，此回合，对象怪兽仅１次不会因效果被破坏。除此以外的情况下，对象怪兽变为水属性。','\r',char(13)),'\n',char(10)),'破坏','改变属性或者赋予抗性','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80538047,'绚岚之狲',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次，且②效果1回合仅可使用1次。\r\n①：自己墓地存在“气旋”的情况下，或对手场上不存在魔法・陷阱卡的情况下，此卡可从手牌特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从牌组将1张“绚岚”魔法・陷阱卡或“气旋”加入手牌。','\r',char(13)),'\n',char(10)),'','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80538728,'发条骑士','我方场上冠有“发条”之名怪兽被选择为攻击对象时，可使该攻击无效。只要此卡以表侧表示存在于场上，此效果只可使用１次。','攻击无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80549379,'龙骑兵团－标枪','①：表侧表示的此卡在怪兽区域被破坏的情况下，可不送至墓地，而是视为装备魔法卡装备于自己场上的1只鸟兽族的“龙骑兵团”怪兽。','是否要使用「龙骑兵团－标枪」的效果？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80551022,'迷拟宝箱鬼・史莱姆',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己的主要阶段可以发动。从手牌将此卡以里侧守备表示特殊召唤至对手场上。对手场上的怪兽数量多于自己场上的怪兽的情况下，作为代替也可以表侧表示特殊召唤至自己场上。\r\n②：此卡在主要阶段反转的情况下发动。分别适用以下效果。\r\n●对手可从自身牌组将1只“迷拟宝箱鬼”怪兽特殊召唤。\r\n●将此卡的控制权转移给对手。','\r',char(13)),'\n',char(10)),'反转效果','特殊召唤','是否从牌组特殊召唤？','在自己场上特殊召唤','在对手场上特殊召唤','','','','','','','','','','','');
INSERT INTO texts VALUES(80551130,'奇迹的光临','①：可以我方被除外的１只天使族怪兽为对象发动。特殊召唤该怪兽。此卡从场上离开时该怪兽被破坏。该怪兽被破坏时此卡被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80555062,'武斗神器－道返','①：只要此卡以守备表示存在于怪兽区，我方场上除此卡以外的“武斗神”怪兽不会因效果被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80555116,'大植然守护者','对手召唤怪兽成功时，此卡的攻击力直到结束阶段时上升３００点。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80559548,'疾行机人剃刀回力镖',replace(replace('①：此卡在召唤的回合不可进行攻击。\r\n②：１回合１次，可以场上的１只表侧表示怪兽为对象发动。将此卡变成守备表示，直至回合结束时，对象怪兽的攻击力下降８００。','\r',char(13)),'\n',char(10)),'守备表示','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80560728,'次元幻像',replace(replace('可以对手场上的１只表侧攻击表示怪兽为对象发动此卡。\r\n①：攻击对象怪兽未被因对象怪兽的攻击而破坏的伤害步骤结束时，可将我方墓地的１只怪兽除外并发动此效果。对象怪兽变成能再１次攻击，且必须持续进行攻击。\r\n②：对象怪兽从场上离开的场合此卡被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80566312,'祝祷圣歌',replace(replace('①：为使合计等级为６以上，解放自己手牌・场上的怪兽，从手牌将“龙姬神 萨菲拉”仪式召唤。\r\n②：自己场上的仪式怪兽将被战斗・效果破坏的情况下，作为代替可将墓地的此卡除外。','\r',char(13)),'\n',char(10)),'是否要使用「祝祷圣歌」的效果代替破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80570228,'六武众之破戒僧',replace(replace('此卡名以①方法的特殊召唤１回合仅可进行１次，且②③效果１回合仅可各使用１次。\r\n①：自己场上存在“六武众之破戒僧”以外的“六武众”怪兽的情况下，此卡可从手牌特殊召唤。\r\n②：此卡从场上被送至墓地的情况下可以发动。从牌组将１张“六武众”速攻魔法卡加入手牌。\r\n③：以此卡作为素材同步召唤的“六武众”怪兽获得以下效果。\r\n●对手场上的怪兽的等级下降１。','\r',char(13)),'\n',char(10)),'','检索效果','','「六武众之破戒僧」效果适用中','','','','','','','','','','','','');
INSERT INTO texts VALUES(80577258,'雪之天气模样',replace(replace('①：只可有１张“雪之天气模样”以表侧表示存在于我方场上。\r\n②：存在于与此卡同一纵列的我方主要怪兽区以及其两旁的我方主要怪兽区的“天气”效果怪兽获得以下效果。\r\n●可将此卡除外并发动。从牌组将１张“天气”卡牌加入手牌。此效果发动后，直至回合结束时，我方不可以抽取卡牌以外的方法将卡牌从牌组加入手牌。此效果在对手回合也可发动。','\r',char(13)),'\n',char(10)),'从牌组把1张「天气」卡加入手牌（雪之天气模样）','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80584548,'弩弓部队','①：可解放我方场上的１只怪兽，并以对手场上的１张卡牌为对象发动。破坏该卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80600490,'暗影斗士','实体和影子会分开攻击。一不小心就会被夹击哦。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80604092,'血的代价','可以在自己的主要阶段或对手的战斗阶段，通过支付５００LP发动。通常召唤１只怪兽。','通常召唤','是否使用效果？','表侧表示召唤','里侧表示放置','','','','','','','','','','','','');
INSERT INTO texts VALUES(80611581,'随风飘飘游×帝企','①：此卡上级召唤成功的情况下可以发动。从牌组将１张“随风飘飘游”魔法・陷阱卡加入手牌。然后可召唤１只怪兽。②：只要上级召唤的此卡存在于怪兽区域，对手场上被特殊召唤的攻击表示怪兽不可发动效果。③：此卡与对手怪兽进行战斗的伤害计算时１次，将１张手牌除外可以发动。该对手怪兽的攻击力・守备力直至回合结束时为止变为一半。','','','是否把1只怪兽召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80621253,'玛那桃圆乡・热情',replace(replace('此卡名以①方法的特殊召唤１回合仅可进行１次，且②效果１回合仅可使用１次。\r\n①：自己场上存在“维萨思・史塔弗罗斯特”或攻击力１５００／守备力２１００的怪兽的情况下，此卡可从手牌中特殊召唤。\r\n②：此卡因战斗・效果被破坏的情况下可以发动。从牌组将１只“玛那桃圆乡”协调特殊召唤。','\r',char(13)),'\n',char(10)),'自己场上有特定怪兽存在的情况下，此卡可以从手牌特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80621422,'海造贼－象征',replace(replace('仅可装备于“海造贼”怪兽。\r\n此卡名的②效果１回合仅可使用１次。\r\n①：装备怪兽的攻击力上升５００，不会成为对手效果的对象。\r\n②：将被装备中的此卡送至墓地可以发动。将１只属性与双方场上・墓地的任一怪兽相同的“海造贼”怪兽从额外牌组特殊召唤。然后，将装备过此卡的怪兽视为攻击力上升５００的装备卡，装备于该特殊召唤的怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80627281,'海晶少女雪花','此卡名的卡1回合仅可发动1张。①：自己场上的“海晶少女”连接怪兽因战斗・效果被破坏的情况下，以该1只怪兽为对象可以发动。将1只连接标记数量比该怪兽少的“海晶少女”连接怪兽视为连接召唤从额外牌组特殊召唤。以此效果特殊召唤的怪兽只要存在于自己场上，不受对手的效果影响。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80630522,'花札卫－桐',replace(replace('①：自己场上有等级１１以下的“花札卫”怪兽存在的情况下可以发动。从手牌将此卡特殊召唤。此效果发动后，直至回合结束时为止，自己仅可召唤・特殊召唤“花札卫”怪兽。\r\n②：此卡被选择为攻击对象时可以发动。使该攻击无效，结束战斗阶段。然后，自己从牌组抽１张。','\r',char(13)),'\n',char(10)),'特殊召唤','攻击无效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80635735,'召唤兽 迪・阿尼玛',replace(replace('“阿莱斯特”怪兽＋被从额外牌组特殊召唤的怪兽\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡特殊召唤的情况下，可从以下效果中选择1个发动。\r\n●将对手场上的、被从额外牌组特殊召唤的怪兽全部破坏。\r\n●将对手场上的魔法・陷阱卡全部破坏。\r\n②：对手发动墓地的卡的效果时，将场上的此卡除外可以发动。从牌组将1只“阿莱斯特”怪兽特殊召唤，将该发动的效果无效。','\r',char(13)),'\n',char(10)),'选择效果','特殊召唤并无效','破坏怪兽','破坏魔陷','','','','','','','','','','','','');
INSERT INTO texts VALUES(80637190,'间谍蜘蛛','此卡因战斗破坏对手的守备表示怪兽时，可从我方墓地选择１只等级４或以下的昆虫族怪兽并特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80651316,'进化龙・角鼻龙',replace(replace('①：此卡以“进化虫”怪兽的效果特殊召唤的情况下发动。此卡的攻击力上升２００。\r\n②：以“进化虫”怪兽的效果特殊召唤的此卡战斗破坏对手怪兽时可以发动。从牌组将１只“进化虫”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80666118,'暗红恶魔龙・荣光右痕',replace(replace('协调＋协调以外的怪兽1只以上\r\n①：此卡只要存在于场上・墓地，卡名视为“暗红恶魔龙”。\r\n②：1回合1次，在自己的主要阶段可以发动。将除此卡以外的、攻击力在此卡攻击力以下的、被特殊召唤的效果怪兽全部破坏。然后，给予对手以此效果破坏的怪兽数量×500的伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80678380,'蛇神的敕命','对手发动魔法卡时，可向对手展示手牌１只冠有“猛毒”之名的怪兽并发动。使该发动无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80681226,'念动力波动',replace(replace('此卡名的效果②在1个回合中仅可使用1次。\r\n①：自己场上存在机械族怪兽时，从手牌、牌组中将1只“人造人-念力震慑者”送至墓地后可以发动。给对手600伤害值。\r\n②：在自己的主要阶段除外墓地中的此卡后，可以以自己墓地的1只机械族怪兽为对象发动。从牌组中选择1只“人造人”怪兽送至墓地，将对象怪兽加入手牌。此效果在此卡被送至墓地的回合不可发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80696379,'异色眼陨爆龙',replace(replace('协调＋１只以上协调以外的怪兽\r\n此卡名的①效果１回合仅可使用１次。①：此卡特殊召唤成功时，以自己灵摆区域的１张卡为对象可以发动。将该卡特殊召唤。此回合，此卡不可攻击。②：只要此卡存在于怪兽区域，对手在战斗阶段中不可发动怪兽的效果。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80701178,'魔神仪－曼陀罗护身符','此卡名的①②效果1回合1次，仅可使用其中1个。①：将手牌的1只仪式怪兽出示给对手可以发动。将“魔神仪-曼陀罗护身符”以外的牌组的1只“魔神仪”怪兽和手牌的此卡特殊召唤。②：此卡从牌组特殊召唤成功的情况下可以发动。从牌组将1只仪式怪兽加入手牌。③：只要此卡存在于怪兽区域，自己不可从额外牌组特殊召唤怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80722024,'冥铭途・骨派对',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：将自己手牌・场上（表侧表示）的1只“冥铭途”怪兽破坏，从牌组挑选卡名与该怪兽不同的1只“冥铭途”怪兽，加入手牌或以守备表示特殊召唤。\r\n②：在自己的主要阶段将墓地的此卡除外，以自己场上的1只“冥铭途”怪兽为对象可以发动。此回合，该怪兽攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80723580,'大落穴','同时２只或以上的怪兽特殊召唤成功时可发动。破坏所有场上的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80727036,'黑色食人鲨','“深海切割手”＋“杀人污泥”＋“海原的女战士”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80727721,'朱罗纪・异特龙','①：解放此卡，以“朱罗纪・异特龙”以外的、自己墓地的1只等级4以下的“朱罗纪”怪兽为对象可以发动。将该怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80738884,'对击斗魂 龙帝之枪',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：自己场上存在“对击斗魂”怪兽、对手发动以自己场上的卡为对象的怪兽的效果・魔法・陷阱卡时可以发动。将该发动无效并破坏。然后，可给予对手相当于自己场上的１只“对击斗魂”怪兽的攻击力数值的伤害。','\r',char(13)),'\n',char(10)),'','是否选怪兽给与对手伤害？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80741828,'见习魔女','只要此卡以表侧表示存在于场上，场上所有暗属性怪兽的攻击力上升５００点，光属性怪兽的攻击力下降４００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80744121,'命运－英雄 破灭小子','此卡因战斗被破坏送入墓地的场合，在下一次我方准备阶段时发动，从我方墓地选择１只除“命运－英雄 破灭小子”以外的冠有“命运－英雄”之名的怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80749819,'活尸的呼唤',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：作为此卡发动时的效果处理，可从自己牌组・墓地将最多3张“活死人的呼唤”放置在自己场上。该情况下，直至对手回合结束时为止，自己仅可特殊召唤不死族怪兽（除了从墓地的特殊召唤以外）。\r\n②：1回合1次，自己发动了“活死人的呼唤”的情况下，以对手场上的1只怪兽为对象可以发动。将该怪兽送至墓地。','\r',char(13)),'\n',char(10)),'发动','送至墓地','是否把卡放置？','「活尸的呼唤」效果适用中','','','','','','','','','','','','');
INSERT INTO texts VALUES(80758812,'二重烧蚀',replace(replace('此卡牌名的①效果１回合只可使用１次。\r\n①：在我方・对手的主要阶段，可舍弃１张手牌，并从以下效果选择１个发动。\r\n●从牌组特殊召唤１只二重怪兽。以此效果特殊召唤而来的怪兽再一次被视为被召唤状态。\r\n●解放我方场上的１只二重怪兽，并从手牌・牌组特殊召唤１只战士族・炎属性怪兽。解放了再一次处于被召唤状态的二重怪兽之场合，可再挑选１张场上的卡牌并破坏。','\r',char(13)),'\n',char(10)),'特殊召唤二重怪兽','解放并特殊召唤战士族·炎属性怪兽','是否选场上1张卡破坏？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80764541,'编号44 白天马 天空佩伽萨斯',replace(replace('等级4怪兽×2\r\n①：1回合1次，去除此卡的1个超量素材，以对手场上的1只表侧表示怪兽为对象可以发动。对手可支付1000LP将此效果无效。未支付的情况下，将对象怪兽破坏。','\r',char(13)),'\n',char(10)),'破坏','是否要支付1000基本分无效「编号44 白天马」的效果？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80769747,'链条・蛇','可选择对手场上１只表侧表示怪兽并发动。此卡被视为装备卡装备被选择的对手怪兽。装备怪兽的攻击力、守备力下降８００点。装备怪兽因战斗被破坏并送入墓地时，从装备怪兽的控制者牌组上方将相当于该怪兽等级数量的卡牌送入墓地。','装备','牌组送墓','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80770678,'竖琴精灵','在天界弹奏竖琴的精灵，其琴音能抚平周围听众的心灵。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80773359,'强袭黑羽－神立之鬼丸',replace(replace('协调＋１只以上协调以外的怪兽\r\n此卡名的③效果在决斗中仅可使用１次。①：以“黑羽”怪兽作为素材同步召唤的此卡视为协调。②：此卡不会因效果被破坏。③：以自己墓地的１只“黑羽”怪兽为对象可以发动。此卡的等级变为与该怪兽相同。④：仅以同步怪兽作为素材同步召唤的此卡攻击的情况下，伤害步骤期间，此卡的攻击力上升３０００。','\r',char(13)),'\n',char(10)),'等级变换','只用同步怪兽为素材作同步召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80776622,'哆音服和弦・克理娅',replace(replace('←1 【灵摆】 1→\r\n①：自己的“音服和弦”灵摆怪兽灵摆召唤成功时，对手不可发动怪兽的效果・魔法・陷阱卡。\r\n【怪兽效果】\r\n此卡名的②③怪兽效果1回合仅可各使用1次。①：此卡可以解放自己场上的2只灵摆怪兽，从手牌特殊召唤。②：以对手场上的1张表侧表示的卡为对象可以发动。该卡的效果直至对手回合结束时为止无效。自己的灵摆区域有奇数的灵摆刻度存在的情况下，此效果的对象可改为2张。③：所拥有之攻击力为自己灵摆区域最高灵摆刻度×300的数值以下的场上怪兽的效果发动时可以发动。将该怪兽破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80794697,'帧缓存火牛','此卡名的效果1回合仅可使用1次。①：表侧表示的此卡从场上离开的情况下可以发动。从手牌舍弃1只电子界族怪兽，自己从牌组抽2张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80796456,'编号70 大罪',replace(replace('等级４怪兽×２\r\n①：１回合１次，去除此卡的１个超量素材，以对手场上的１只怪兽为对象可以发动。将该怪兽直至下个对手的准备阶段为止除外。\r\n②：此卡攻击过的伤害步骤结束时可以发动。此卡的攻击力上升３００，阶级上升３。','\r',char(13)),'\n',char(10)),'对手怪兽除外','此卡攻击力上升','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80801743,'破械双极',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从自己手牌・墓地将1只“破械”怪兽特殊召唤。\r\n②：被放置的此卡因效果被破坏的情况下可以发动。从牌组将1只“破械”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80802524,'鬼计爆碎','①：我方场上的１只“鬼计”怪兽因战斗或对手效果被破坏并送入我方墓地时，可以我方墓地的２只与该被破坏怪兽不同卡牌名的“鬼计”怪兽为对象发动。以里侧守备表示特殊召唤该怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80811661,'汉堡的食谱','①：为使合计等级为６以上，从自己的手牌・场上解放怪兽，从手牌将“饥饿汉堡”仪式召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80813021,'犀牛','虽然守备不像外表般高强。但是犀牛角的攻击力很强。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80825553,'云魔物－小烟球','小小的云魔物的小孩云。最讨厌孤单一人，最喜欢和伙伴们乘着风悠哉散步。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80831552,'恐龙摔跤手・综合格斗重爪龙',replace(replace('①：仅有对手场上才存在怪兽的情况下，此卡可从手牌特殊召唤。\r\n②：只要自己场上存在连接3以上的“恐龙摔跤手”怪兽，自己场上的表侧表示怪兽就不受连接3以下的对手怪兽发动的效果影响。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80831721,'贤者之石－萨巴希尔',replace(replace('①：自己墓地存在“羽翼库里波”怪兽的情况下，支付一半LP可以发动。从牌组将1张“融合”魔法卡或“结合”魔法卡加入手牌。\r\n②：此卡存在于墓地的情况下，从自己墓地将3张“贤者之石－萨巴希尔”除外，以场上的1只怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止，上升相当于场上怪兽的最高攻击力的数值。','\r',char(13)),'\n',char(10)),'加入手牌','攻击上升','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80839052,'核成・供给者',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：自己场上的表侧表示的岩石族怪兽被送至墓地的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：此卡特殊召唤的情况下可以发动。从牌组将除“核成・供给者”以外的1张“核成之钢核”或记载有该卡名的卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80845034,'“狩猎罪宝的魔鬼”',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从自己牌组・墓地将1只“迪亚贝尔斯塔”怪兽加入手牌。\r\n②：在自己的主要阶段将墓地的此卡除外，以““狩猎罪宝的魔鬼””以外的、自己墓地・除外状态的1张“罪宝”魔法・陷阱卡为对象可以发动。将该卡放回牌组最下面。然后，自己抽1张。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80863132,'无效','可在发动抽牌效果时发动此卡。依照此卡的效果，双方都对所抽取的卡牌进行确认，并全部弃置至墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80870883,'真红眼黑全钢龙',replace(replace('此卡不可通常召唤，通过解放等级５以上龙族怪兽来发动的“钢铁化・强化反射装甲”的效果可以特殊召唤。\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：向对手出示手牌的此卡可以发动。从牌组将１张“钢铁化”陷阱卡放置在自己场上，将此卡放回牌组。\r\n②：对手发动效果时可以发动。将该发动无效。然后，可给予对手相当于对手场上的１只攻击表示怪兽的原本攻击力数值的伤害。','\r',char(13)),'\n',char(10)),'放置「钢铁化」陷阱卡','发动无效','是否再给予伤害','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80885284,'鬼计・跳尸','仅在自己场上有“鬼计”怪兽存在的情况下，此卡才可以表侧表示召唤。此卡名的②效果１回合仅可使用１次。①：在自己的主要阶段可以发动。将此卡改成里侧守备表示（１回合仅１次）。②：此卡反转时可以发动。将１只等级为自己场上的“鬼计”怪兽数量以下的“鬼计”怪兽从牌组加入手牌。','变成里侧守备','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80885324,'搜索狙击者','此卡攻击了里侧守备表示怪兽的伤害步骤开始时，可破坏该里侧守备表示怪兽。使用此效果的场合，此卡在战斗阶段结束时变成守备表示，直至下一个我方回合结束时不可变更表示形式。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80887714,'银河风暴','选择场上１只无超量素材的超量怪兽并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80887952,'双子太阳・赫利欧斯','此卡可解放我方场上的１只“原始太阳 赫利俄斯”，并从手牌特殊召唤。此卡的攻击力、守备力变成从游戏中被除外的怪兽数量×２００。此卡因战斗被破坏并送入墓地回合的结束阶段时，特殊召唤此卡。以此效果特殊召唤而来的此卡的攻击力、守备力上升３００点。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80889750,'魔玩具・刺刀虎',replace(replace('“魔玩具”融合怪兽＋1只以上“绒毛动物”怪兽或“锋利小鬼”怪兽\r\n①：此卡融合召唤成功时，以自己墓地的1只“魔玩具”怪兽为对象可以发动。将该怪兽特殊召唤。②：只要此卡存在于怪兽区域，自己场上的“魔玩具”怪兽攻击力上升400。③：以3只以上怪兽为素材融合召唤的此卡不会因战斗・效果被破坏。','\r',char(13)),'\n',char(10)),'不会被战斗·效果破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80893872,'皇家企鹅花园',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：作为此卡发动时的效果处理，可从牌组将“皇家企鹅花园”以外的1张“企鹅”卡加入手牌。\r\n②：1回合1次，在自己的主要阶段可以发动。将自己手牌・场上（表侧表示）的1只“企鹅”怪兽的等级直至回合结束时为止下降1。然后，挑选自己的1张手牌舍弃。','\r',char(13)),'\n',char(10)),'是否从牌组把「企鹅」卡加入手牌？','','请选择要下降等级的卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80896940,'涅槃的超魔导剑士',replace(replace('←8 【灵摆】 8→\r\n①：自己的灵摆怪兽攻击的情况下，该怪兽不会因该战斗被破坏，因该战斗对自己造成的战斗伤害变为０。②：自己的灵摆怪兽攻击的伤害步骤结束时发动。对手场上所有怪兽的攻击力直至回合结束时为止，下降相当于攻击的该怪兽攻击力的数值。\r\n【怪兽效果】\r\n协调＋１只以上协调以外的同步怪兽\n同步召唤此卡的情况下，可将自己场上的１只灵摆召唤的灵摆怪兽视为协调。①：此卡将灵摆召唤的灵摆怪兽作为协调同步召唤成功的情况下，以自己墓地的１张卡为对象可以发动。将该卡加入手牌。②：此卡战斗破坏对手怪兽时可以发动。将对手的LP改成一半。③：怪兽区域的此卡因战斗・效果被破坏的情况下可以发动。将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'同步召唤','使用灵摆召唤的灵摆怪兽当作协调同步召唤','攻击力下降','加入手牌','基本分变成一半','此卡在灵摆区域放置','','','','','','','','','','');
INSERT INTO texts VALUES(80908502,'元素－英雄 黄金队长','①：将此卡从手牌舍弃至墓地可以发动。从牌组将1张“摩天楼”加入手牌。②：场上没有“摩天楼”存在的情况下，此卡将被破坏。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80921533,'死皇帝的陵墓',replace(replace('①：双方玩家可在自身的主要阶段从以下效果中选择１个发动。\r\n●支付１０００LP可以发动。将手牌的１只、需要解放１只来通常召唤的怪兽，免去解放直接进行通常召唤。\r\n●支付２０００LP可以发动。将手牌的１只、需要解放２只来通常召唤的怪兽，免去解放直接进行通常召唤。','\r',char(13)),'\n',char(10)),'通常召唤','表侧表示召唤','里侧表示放置','请选择要支付的基本分','','','','','','','','','','','','');
INSERT INTO texts VALUES(80925836,'核成魔鬼','此卡的控制者在自己的每个结束阶段，从手牌将１张“核成之钢核”送往墓地，或向对手出示手牌中的１只恶魔族怪兽。或者两者都不进行，将此卡破坏。只要此卡表侧表示存在于场上，主要阶段时发动的光・暗属性怪兽的效果被无效化。','选择一张「核成之钢核」送至墓地','选择一只恶魔族怪物给对手观看','破坏「核成魔鬼」','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80949182,'蜂军－降魔弓之破魔',replace(replace('协调＋协调以外的怪兽１只以上\r\n此卡名的②③效果１回合仅可各使用１次。\r\n①：以同步怪兽作为素材同步召唤的此卡在１次战斗阶段中可攻击２次。\r\n②：此卡给予对手战斗伤害时可以发动。对手场上的所有怪兽的攻击力・守备力下降１０００。\r\n③：在对手未受到战斗伤害的自己的战斗阶段结束时可以发动。给予对手相当于自己墓地的“蜂军”怪兽的数量×３００的伤害。','\r',char(13)),'\n',char(10)),'攻击力·守备力下降','给与对手伤害','同步怪兽为素材作同步召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80955168,'王墓的陷阱','①：不死族怪兽从对手墓地被特殊召唤至我方场上时，可以场上的２张卡牌为对象发动。破坏该卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80959027,'魔导兽 巴西利斯克',replace(replace('←4 【灵摆】 4→\r\n此卡名的灵摆效果1回合仅可使用1次。\n①：自己另一方的灵摆区域不存在卡的情况下可以发动。将此卡破坏，从自己额外牌组（表侧）将“魔导兽 巴西利斯克”以外的1只魔法师族灵摆怪兽放回牌组。然后，自己抽1张。\r\n【怪兽效果】\r\n此卡名的②怪兽效果1回合仅可使用1次。\n①：只要此卡存在于怪兽区域，每当自己或对手发动魔法卡，就在此卡上放1个魔力计数物。\n②：去除自己场上的3个魔力计数物可以发动。将自己额外牌组（表侧）・灵摆区域的1张“魔导兽”卡放回手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80965043,'斩机加伐','此卡名的效果在1回合中仅可使用1次。①：可以场上1只表侧表示的怪兽为对象发动。从手牌将此卡特殊召唤，对象怪兽的攻击力直至回合结束时为止上升1000。用此效果特殊召唤的回合，此卡不可攻击。此效果发动后，直至回合结束时为止自己从额外牌组仅可特殊召唤电子界族怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80978111,'飞翔的Z','对手召唤・特殊召唤怪兽成功时可以发动。将此卡从手牌以守备表示特殊召唤至对手场上。只要此卡以表侧表示存在于场上，此卡的控制者不可超量召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80987696,'时间机－Time Machine','①：当我方或对手的１只怪兽因战斗而被破坏送入墓地时，可发动此卡。以相同的表示形式特殊召唤该怪兽至被破坏时的控制者的场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(80993256,'亚种罗王',replace(replace('等级３怪兽×３只以上\r\n此卡名的③效果１回合仅可使用１次。①：拥有超量素材的此卡在１次战斗阶段中最多可攻击相当于其素材数量的次数。②：此卡进行战斗的伤害步骤开始时发动。此卡的攻击力上升２００。③：此卡以外的怪兽的效果发动时，去除此卡的１个超量素材可以发动。将该发动无效并破坏。','\r',char(13)),'\n',char(10)),'攻击力上升','发动无效并破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81000306,'浑身的一击','选择我方场上１只表侧表示的怪兽发动此卡。该回合中，所选择怪兽不会因战斗而被破坏，双方因其攻击而受到的战斗伤害变为０。此外，该回合中，所选择怪兽攻击对手怪兽的场合，在伤害计算后破坏对手怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81003500,'元素－英雄 死灵巫侠',replace(replace('“元素－英雄 狂野人”＋“元素－英雄 死灵暗黑人”\r\n此卡名在规则上也视为“机人”卡。此卡仅可以融合召唤特殊召唤。此卡特殊召唤成功时，选择对手场上的１只怪兽破坏。之后，从对手墓地挑选１只怪兽特殊召唤至对手场上。','\r',char(13)),'\n',char(10)),'破坏并特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81005500,'点心大精灵 维恩',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。此卡以表侧表示存在于自己场上的情况下，对手从以下效果中挑选1个，自己适用该效果。\r\n●此卡的攻击力上升相当于自己墓地的不死族怪兽数量×800的数值。\r\n●给予对手相当于自己墓地的不死族怪兽的数量×500的伤害。\r\n②：此卡因战斗・效果被破坏的情况下可以发动。从对手墓地将1只怪兽特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'攻击力上升或者给予伤害','对手墓地怪兽在自己场上特殊召唤','攻击力上升','伤害给与','','','','','','','','','','','','');
INSERT INTO texts VALUES(81019803,'飘飘然的梅尔菲们',replace(replace('协调＋１只以上协调以外的怪兽\r\n此卡名的①②效果１回合仅可各使用１次。①：此卡特殊召唤成功的情况下，以场上的１只表侧表示怪兽为对象可以发动。将该怪兽放回持有者的手牌。②：对手将怪兽召唤・特殊召唤成功的情况下，或此卡被选择为对手怪兽的攻击对象的情况下可以发动。将此卡放回持有者的额外牌组。然后，可从额外牌组将１只“梅尔菲”超量怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','此卡回到额外牌组','是否从额外牌组特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81020140,'火山性左轮','此卡因战斗被破坏并送入墓地时可发动。从牌组挑选１只冠有“火山性”之名的怪兽并放置于牌组的最上方。','检索','请选择要在牌组最上方放置的卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81020646,'炼狱龙 食人魔龙',replace(replace('暗属性协调＋协调以外的怪兽１只或以上\r\n我方手牌是０张的场合，１回合１次，对手发动魔法、陷阱卡时可发动。使该发动无效并破坏。','\r',char(13)),'\n',char(10)),'发动无效并破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81028112,'电力超能斗士',replace(replace('“电力超能斗士”的效果１回合只可使用１次。\r\n①：此卡召唤、特殊召唤成功时，可以对手墓地的１张卡牌作为对象发动。该卡牌返回至对手牌组的最上方或最下方。','\r',char(13)),'\n',char(10)),'墓地干扰','牌组最上面','牌组最下面','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81034083,'暗黑招来神',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：此卡召唤时可以发动。从牌组将“神炎皇乌利亚”、“降雷皇哈蒙”、“幻魔皇拉比艾尔”中的任意1只，或记载有其中任一卡名的、“暗黑招来神”以外的1张卡加入手牌。\r\n②：只要此卡存在于怪兽区域，自己在通常召唤之外，可在自己的主要阶段追加1次召唤1只攻击力和守备力为0的恶魔族怪兽。','\r',char(13)),'\n',char(10)),'','使用「暗黑招来神」的效果召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81035362,'魔犀战士','此卡名的②效果1回合仅可使用1次。①：只要此卡存在于怪兽区域，自己场上“魔犀战士”以外的恶魔族怪兽不会因战斗・效果被破坏。②：此卡被送至墓地的情况下可以发动。从牌组将1只“魔犀战士”以外的恶魔族怪兽送至墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81038234,'梦魔镜之述梦','①：只要此卡存在于魔法与陷阱区域，自己场上的“梦魔镜”怪兽为发动自身效果而被解放的情况下，不去墓地而是放回持有者的牌组。②：在自己・对手的主要阶段，将魔法与陷阱区域表侧表示的此卡送至墓地可以发动。从自己墓地的卡及自己被除外的卡中，挑选１张“圣光之梦魔镜”或“暗黑之梦魔镜”以表侧表示放在自己的场地区域。然后，可将１只记载有所放卡卡名的怪兽从手牌特殊召唤。','','是否从手牌特殊召唤怪兽？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81055000,'娱乐伙伴返转狸猫',replace(replace('←3 【灵摆】 3→\r\n“娱乐伙伴返转狸猫”的灵摆效果１回合只可使用１次。\n①：可以我方场上的１张“娱乐伙伴”卡牌为对象发动。将该卡返回至持有者手牌。此回合，我方不可发动因此效果返回至手牌的卡牌及其同名卡。\r\n【怪兽效果】\r\n①：此卡因战斗被破坏时，可以场上的１张卡牌为对象发动。将该卡返回至持有者手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81057455,'坏兽捕获大作战',replace(replace('“坏兽捕获大作战”的②效果１回合仅可使用１次。\r\n①：１回合１次，以场上的１只“坏兽”怪兽为对象可以发动。将该怪兽改成里侧守备表示。然后，在此卡上放１个坏兽计数物（最多３个）。\r\n②：此卡因对手的效果被破坏并被送至墓地的情况下可以发动。自己从牌组抽２张。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81057959,'龙人','身怀龙之力挥舞着龙牙之剑的战士。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81059524,'死亡魔导龙',replace(replace('①：此卡因战斗破坏对手怪兽并送入墓地的场合发动。给予对手５００伤害。\r\n②：只要此卡存在于怪兽区，我方或对手每次发动通常、速攻魔法卡，直至回合结束时，此卡的攻击力各上升２００。','\r',char(13)),'\n',char(10)),'LP伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81066751,'天罚','①：场上存在有“天空的圣域”，并且怪兽的效果、魔法、陷阱卡发动时可发动。使该发动无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81078880,'直播☆双子 璃拉讨糖','此卡名以①方法的特殊召唤１回合仅可进行１次，且②效果１回合仅可使用１次。①：自己场上有“姬丝吉尔”怪兽存在的情况下，此卡可从手牌中特殊召唤。②：自己或对手因“邪恶★双子”怪兽的战斗受到战斗伤害时，将墓地的此卡除外，以对手场上的１只表侧表示怪兽为对象可以发动。该怪兽的攻击力下降相当于该战斗伤害的数值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81096431,'龙兽鲨',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：用抽牌以外的方法将此卡加入手牌的情况下可以发动。将此卡特殊召唤。\r\n②：超量召唤需以３只以上怪兽作为素材的水属性超量怪兽的情况下，此卡可作为２只的超量素材。\r\n③：持有此卡作为素材的“鲨龙兽”超量怪兽获得以下效果。\r\n●１回合１次，去除此卡的２个超量素材，以场上的１张魔法・陷阱卡为对象可以发动。将该卡作为此卡的超量素材。','\r',char(13)),'\n',char(10)),'特殊召唤','','获取超量素材（龙兽鲨）','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81101309,'夜光列车 蓝色旅人',replace(replace('此卡名的①效果1回合仅可使用1次，且②效果在决斗中仅可使用1次。\r\n①：从手牌将此卡舍弃可以发动。从自己牌组・墓地将1张“机关连结”或“回转调车”加入手牌。\r\n②：此卡存在于墓地的情况下，以自己墓地的1只其他的机械族・地属性怪兽为对象可以发动。将该怪兽和此卡特殊召唤。此效果发动后，直至回合结束时为止，自己从额外牌组仅可特殊召唤机械族怪兽。','\r',char(13)),'\n',char(10)),'检索效果','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81105204,'黑羽－残夜之酷利斯',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次。\r\n①：自己场上存在“黑羽－残夜之酷利斯”以外的“黑羽”怪兽的情况下，此卡可从手牌特殊召唤。\r\n②：场上的此卡1回合仅1次，不会因魔法・陷阱卡的效果被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81108658,'北斗天熊－大灰熊','此卡名的①②效果1回合仅可各使用1次。①：在自己・对手的主要阶段，从手牌解放此卡以外的1只等级7以上的怪兽可以发动。从手牌将此卡特殊召唤。此效果发动后，直至回合结束时为止，自己仅可特殊召唤拥有等级的怪兽。②：自己场上有其他“北斗天熊”怪兽存在的状态下，此卡特殊召唤成功的情况下，以对手墓地的1张卡为对象可以发动。将该卡除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81109178,'焰火爆竹魔',replace(replace('“焰火爆竹魔”的①的效果１回合仅可使用１次。\r\n①：从手牌将此卡舍弃可以发动。给予对手１０００点伤害，并跳过下一个自己的抽牌阶段。此效果在对手回合中也可以发动。\r\n②：只要此卡存在于怪兽区域，每次对手受到效果伤害，放１个计数物于此卡。\r\n③：在自己・对手的结束阶段发动。移除此卡的所有计数物，并给予对手该数量×３００点伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81119816,'调皮宝贝・脉冲娃',replace(replace('具此卡名的效果１回合只能使用１次。\r\n①：此卡仅在作为“调皮宝贝”怪兽的融合素材或连接素材被送至墓地时可发动。从卡组中将除“调皮宝贝・脉冲娃”之外的１张“调皮宝贝”卡送至墓地。然后，从手牌／卡组中以守备状态特殊召唤１只除“调皮宝贝・脉冲娃”之外的“调皮宝贝”怪兽。','\r',char(13)),'\n',char(10)),'是否特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81122844,'上弦航母发条巨舰',replace(replace('等级３怪兽×２\r\n①：１回合１次，可以移除此卡的１张超量素材发动。从手牌或卡组中特殊召唤１只“发条”怪兽。\r\n②：场上面朝上的“发条”怪兽在被战斗以外的情况破坏并送进我方墓地时，可以移除此卡的１张超量素材，选择１只上述的“发条”怪兽为目标发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','返回手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81128478,'蜘蛛巢丝网','可将我方墓地的１只昆虫族怪兽从游戏中除外，并选择对手场上的１只怪兽发动。破坏被选择怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81143465,'哀哉玉绳双魂缱绻',replace(replace('仅可装备于自己场上的被从额外牌组特殊召唤的怪兽。\r\n①：有攻击力高于装备怪兽的怪兽被对手从额外牌组特殊召唤的情况下，以其中1只为对象可以发动。将该怪兽与装备怪兽破坏，自己受到相当于所破坏怪兽原本攻击力合计数值的伤害。然后，给予对手与自己所受伤害相同数值的伤害。','\r',char(13)),'\n',char(10)),'','破坏效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81146288,'大凛魔天使箩扎利安','此卡不可通常召唤。从我方的手牌和墓地将等级７或以上的植物族怪兽各１只从游戏中除外的场合，可特殊召唤。１回合１次，我方主要阶段时可发动。直至回合结束时，使场上除此卡以外的表侧表示卡牌的效果无效。','效果无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81167171,'英雄精神','我方冠有“元素－英雄”之名的怪兽因战斗被破坏回合的战斗阶段可发动。此回合的对手怪的战斗中仅１次，来自对手怪兽的战斗伤害变成０，我方怪兽不会因该战斗被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81171949,'头奖壶７','将此卡放回到牌组并进行洗牌。此外，当此卡因对手的卡牌效果而被送入墓地时，将此卡从游戏中除外。当以此效果而从游戏中除外的我方的“头奖壶７”达到３张时，我方获得决斗的胜利。','除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81172176,'魔鬼喜剧演员','①：掷1次硬币，猜硬币的正反。猜中的情况下，将对手墓地的卡全部除外。猜错的情况下，依对手墓地的卡的张数，从自己牌组上面将卡送至墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81172177,'魔鬼喜剧演员','①：掷1次硬币，猜硬币的正反。猜中的情况下，将对手墓地的卡全部除外。猜错的情况下，依对手墓地的卡的张数，从自己牌组上面将卡送至墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81179446,'青虫','吐丝进行攻击。不知会成长为何物的虫子。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81191584,'噩梦再临','①：以自己墓地2只守备力0的暗属性怪兽为对象可以发动。将该暗属性怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81192859,'雅－朋.克.狂奏','此卡名的①效果1回合仅可使用1次。①：自己的“朋.克.”怪兽与对手怪兽进行战斗的伤害步骤开始时可以发动。将该对手的怪兽破坏。②：魔法与陷阱区域的此卡因对手的效果被破坏的情况下可以发动。自己场上的所有“朋.克.”怪兽此回合不会因战斗被破坏。','','','「雅乐朋.克.野蛮弹奏」效果适用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81193865,'永恒进化冲击波','仅可装备于机械族的融合怪兽。①：只要此卡存在于魔法与陷阱区域，在自己的战斗阶段中对手不可发动魔法・陷阱・怪兽的效果。②：装备怪兽攻击对手怪兽的伤害步骤结束时，从自己的墓地将1只“电子龙”怪兽除外可以发动。装备怪兽可继续攻击对手怪兽。发动此效果的回合中，装备怪兽以外的自己的怪兽不可攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81196066,'月光舞香姬',replace(replace('“月光”怪兽×2\r\n此卡名的①②③效果1回合仅可各使用1次。\r\n①：此卡融合召唤的情况下可以发动。从牌组将1张“月华香”加入手牌。\r\n②：以自己场上的1张其他的“月光”卡为对象可以发动。将该卡放回手牌・额外牌组。然后，可从手牌将1只“月光”怪兽特殊召唤。\r\n③：将墓地的此卡除外可以发动。此回合中，对手场上的怪兽的攻击力下降自身原本守备力的数值。','\r',char(13)),'\n',char(10)),'检索','回收','下降攻击力','是否特殊召唤？','','','','','','','','','','','','');
INSERT INTO texts VALUES(81197327,'元素－英雄 蒸气治疗师',replace(replace('“元素－英雄 爆炎女郎”＋“元素－英雄 泡沫人”\r\n此卡仅可以融合召唤特殊召唤。此卡因战斗破坏怪兽并送入墓地时，回复我方相当于被破坏怪兽原本攻击力数值的LP。','\r',char(13)),'\n',char(10)),'LP回复','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81210420,'魔术礼帽','①：在对手的战斗阶段可以发动。从牌组挑选2张魔法・陷阱卡，将该2张卡视为通常怪兽（攻/守0），和自己主要怪兽区域的1只怪兽一起洗牌并以里侧守备表示放置。以此效果从牌组特殊召唤的卡仅可在战斗阶段期间存在，将在战斗阶段结束时被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81218874,'侵略的波纹','可支付５００LP，从我方墓地选择１只等级４或以下的冠有“侵邪蚀”之名的怪兽并发动。特殊召唤被选择怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81223446,'死魂结合','①：从自己的墓地将由融合怪兽卡决定的融合素材怪兽以里侧表示除外，从额外牌组中将１只该融合怪兽融合召唤。以此效果特殊召唤的怪兽在此回合不可攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81231742,'破邪的魔法壁','①：我方场上的怪兽在我方回合内攻击力上升３００，在对手回合内守备力上升３００。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81237046,'纠罪巧－嗜蝎 Archaη.TAIL',replace(replace('←0 【灵摆】 0→\r\n①：每当有怪兽反转，就在此卡上放1个纠罪计数物。\n②：在自己・对手的战斗阶段结束时，另一方自己的灵摆区域存在“纠罪巧”卡的情况下，以对手场上的1只攻击力低于此卡的怪兽为对象可以发动。将该怪兽破坏。\r\n【怪兽效果】\r\n①：向对手出示手牌的此卡可以发动（发动此效果的回合中，自己仅可以里侧守备表示特殊召唤怪兽）。从手牌将1只怪兽以里侧守备表示特殊召唤。\n②：对手发动将会破坏场上的卡的效果时，将里侧表示的此卡改成表侧守备表示可以发动。此回合中，自己场上的怪兽及“纠罪巧”魔法卡不会因效果被破坏。\n③：只要反转的此卡存在于怪兽区域，每当有怪兽被送至对手墓地，对手就受到900伤害。','\r',char(13)),'\n',char(10)),'破坏','特殊召唤','抗性赋予','已反转过','','','','','','','','','','','','');
INSERT INTO texts VALUES(81254059,'异虫女王','此卡可释放１只冠有“异虫”之名的爬虫类族怪兽，并以攻击表示上级召唤。此外，１回合１次，可释放我方场上１只冠有“异虫”之名的爬虫类族怪兽并发动。从牌组特殊召唤１只等级为被释放怪兽等级或以下的冠有“异虫”之名的爬虫类族怪兽。','用1只怪兽解放上级召唤','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81260679,'大日女之御巫',replace(replace('以“御巫神乐”降临\r\n此卡名的①③效果1回合仅可各使用1次。\r\n①：向对手出示手牌的此卡可以发动。从牌组将“大日女之御巫”以外的1张“御巫”卡加入手牌。然后，挑选自己的1张手牌舍弃。\r\n②：此卡不会因战斗被破坏，因此卡的战斗对自己造成的战斗伤害由对手代为承受。\r\n③：在自己・对手回合中，以自己墓地的1张装备魔法卡为对象可以发动。将该卡装备于场上1只可装备的怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81260680,'大日女之御巫',replace(replace('以“御巫神乐”降临\r\n此卡名的①③效果1回合仅可各使用1次。\r\n①：向对手出示手牌的此卡可以发动。从牌组将“大日女之御巫”以外的1张“御巫”卡加入手牌。然后，挑选自己的1张手牌舍弃。\r\n②：此卡不会因战斗被破坏，因此卡的战斗对自己造成的战斗伤害由对手代为承受。\r\n③：在自己・对手回合中，以自己墓地的1张装备魔法卡为对象可以发动。将该卡装备于场上1只可装备的怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81263643,'幻妖胡尔德拉',replace(replace('此卡牌名的效果１回合只可使用１次。\r\n①：此卡召唤、特殊召唤成功的场合，可舍弃１张手牌并发动。依据舍弃卡牌的种类适用以下效果。\r\n●怪兽：从我方墓地挑选１张陷阱卡加入手牌。\r\n●魔法：从我方墓地挑选１只怪兽加入手牌。\r\n●陷阱：从我方墓地挑选１张魔法卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81269231,'古代机械齿轮合成龙','①：解放“古代机械齿轮”怪兽来上级召唤的此卡与对手怪兽战斗、但未将其破坏的伤害步骤结束时可以发动。将该对手怪兽除外。②：解放“小工具”怪兽来上级召唤的此卡可攻击所有对手怪兽各１次。③：自己的“古代机械齿轮”怪兽攻击的情况下，对手直至伤害步骤结束时为止，不可发动怪兽的效果・魔法・陷阱卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81275020,'疾行机人 贝陀螺飞轮',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：自己场上不存在怪兽的情况下，此卡可从手牌特殊召唤。\r\n②：此卡召唤・特殊召唤时可以发动。从牌组将“疾行机人 贝陀螺飞轮”以外的1只“疾行机人”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81275309,'冰结界的虎将 雷奉','①：只要此卡存在于怪兽区域，对手在场上所发动的怪兽的效果处理时，对手可舍弃１张手牌。未舍弃的情况下，其效果无效化。','是否要丢弃一张手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81278754,'里青蛙',replace(replace('①：在自己的主要阶段可以发动。将此卡改成里侧守备表示（1回合仅1次）。\r\n②：此卡反转时可以发动。以自己场上的“青蛙”怪兽数量为上限，将对手场上的怪兽放回手牌。','\r',char(13)),'\n',char(10)),'变成里侧守备','返回手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81306186,'世界回归',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：作为此卡发动时的效果处理，从牌组将1只仪式怪兽除外。\r\n②：将此卡送至墓地，可从以下效果中选择1个发动。\r\n●为使等级达到仪式召唤的怪兽的等级以上，解放自己手牌・场上的1只怪兽，或作为解放的代替将自己墓地的1只仪式怪兽放回牌组，将以此卡的①效果除外的怪兽仪式召唤。\r\n●将以此卡的效果除外的怪兽加入手牌。','\r',char(13)),'\n',char(10)),'除外的怪兽仪式召唤','除外的怪兽加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81306586,'企鹅梦魇','此卡反转时，选择对手场上的１张卡牌返回至持有者的手牌。此外，只要此卡以表侧表示存在于场上，我方场上水属性怪兽的攻击力上升２００点。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81321206,'北斗天熊－小灰熊','此卡名的①②效果1回合仅可各使用1次。①：在自己・对手的主要阶段，从手牌解放此卡以外的1只等级7以上的怪兽可以发动。从手牌将此卡特殊召唤。此效果发动后，直至回合结束时为止，自己仅可特殊召唤拥有等级的怪兽。②：此卡特殊召唤成功的情况下可以发动。从手牌将“北斗天熊-小灰熊”以外的1只“北斗天熊”怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81325903,'亚马逊的诅咒师','直到回合结束时，令我方场上１只表侧表示的冠有“亚马逊”之名的怪兽与对手场上１只表侧表示的怪兽的原始攻击力互换。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81330115,'编号30 破灭之酸蚀魔像',replace(replace('等级3怪兽×2\r\n①：没有超量素材的此卡不可攻击。\r\n②：只要此卡存在于怪兽区域，自己不可特殊召唤怪兽。\r\n③：在自己的准备阶段发动。去除此卡的1个超量素材，或自己受到2000伤害。','\r',char(13)),'\n',char(10)),'去除素材','是否要去除一个超量素材？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81332143,'友情 YU－JYO','①：向对手玩家提出握手邀请。对手回握的场合，双方的LP变为双方合计值的一半。我方手牌中存在有“结束 UNITY”的场合，可向对手展示该卡。该场合双方握手并适用此卡的效果。','同意握手','拒绝握手','是否要把「结束 UNITY」给对手观看？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81336148,'剑圣','对手怪兽未因我方场上战士族怪兽的攻击被破坏的伤害步骤结束时，可从手牌特殊召唤此卡。此外，此卡攻击了守备表示怪兽时，若其攻击力超过守备力，给予对手生命相当于该差值的战斗伤害。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81344070,'海造贼－新人 金发',replace(replace('具此卡名的①②效果１回合各只能使用１次。\r\n①：从除此卡以外的手牌及我方场上面朝上的卡片中，将１张“海造贼”怪兽卡送至墓地可发动。从手牌中特殊召唤此卡。\r\n②：此卡存在于墓地中的情况下，弃掉１张手牌可发动。特殊召唤此卡。此回合我方无法特殊召唤“海造贼”以外的怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81344637,'咒眼的眷属 巴西利乌斯',replace(replace('以此卡牌名①方法进行的特殊召唤１回合只可使用１次，②的效果１回合只可使用１次。\r\n①：我方场上存在有“咒眼”怪兽的场合，此卡可从手牌特殊召唤。\r\n②：在我方主要阶段可发动。从牌组将１张“咒眼”魔法、陷阱卡送入墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81354330,'朱雀的召唤士','①：此卡因对手怪兽的攻击被破坏并送入墓地时可发动。从牌组以攻击表示特殊召唤１只攻击力为１５００或以下的战士族怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81380218,'圣域的歌声','场上守备表示怪兽的守备力上升５００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81383947,'白魔导师 比可儿','我方准备阶段时，回复LP，其数值相当于存在于我方场上怪兽数量×４００点。','回复LP','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81384993,'Sin 痛怖交错','①：以自己墓地的1只“Sin”怪兽为对象可以发动。将该怪兽无视召唤条件特殊召唤。以此效果特殊召唤的怪兽的效果无效化，将在结束阶段被除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81385346,'粉碎践踏','只有在我方场上有表侧表示的龙族怪兽存在的场合才可发动此卡。选择场上的１张魔法・陷阱卡将其破坏，并给予该卡控制者５００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81386177,'神鱼','在水中优雅游动的鱼神。将其惹怒的话会陷入危险。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81418467,'原石龙 帝皇龙',replace(replace('此卡仅可在解放１只通常怪兽的情况下召唤。\r\n此卡名的①效果１回合仅可使用１次。\r\n①：在对手的主要阶段，向对手出示手牌的此卡可以发动。进行１只“原石”怪兽的召唤。\r\n②：此卡上级召唤的情况下可以发动。分别适用以下效果。\r\n●对手场上的所有表侧表示怪兽的效果无效化。\r\n●将对手场上的种族或属性与自己墓地的任一通常怪兽相同的怪兽全部除外。','\r',char(13)),'\n',char(10)),'进行召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81426505,'六武式三段冲',replace(replace('①：自己场上存在３只以上“六武众”怪兽的情况下，可从以下效果中选择１个发动。\r\n●将对手场上表侧表示的怪兽全部破坏。\r\n●将对手场上表侧表示的魔法・陷阱卡全部破坏。\r\n●将对手场上里侧表示的魔法・陷阱卡全部破坏。','\r',char(13)),'\n',char(10)),'对手表侧表示怪兽全部破坏','对手表侧表示魔法·陷阱全部破坏','对手放置的魔法·陷阱全部破坏','选择一个效果发动','','','','','','','','','','','','');
INSERT INTO texts VALUES(81434470,'千眼水母','此卡不可通常召唤。仅限解放我方场上的１只“海洋看守者”的场合可特殊召唤。只要此卡以表侧表示存在于场上，对手就必须持续公开手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81439173,'愚蠢埋葬','①：从牌组将1只怪兽送至墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81439174,'愚蠢埋葬','①：从牌组将1只怪兽送至墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81439175,'愚蠢埋葬','①：从牌组将1只怪兽送至墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81443745,'水遁封印式','１回合１次，可将手牌的１只水属性怪兽送入墓地并发动。选择对手墓地的１张卡牌并从游戏中除外。','除外','是否现在使用「水遁封印式」的效果？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81470373,'黑羽－毒风之砂蒙',replace(replace('此卡名的效果１回合仅可使用１次。\r\n①：自己场上不存在怪兽的情况下，从手牌将１只其他的“黑羽”怪兽除外可以发动。从牌组将１张“黑旋风”以表侧表示放在自己的魔法与陷阱区域。然后，将手牌的此卡无需解放进行召唤，或送至墓地。以此效果所放的“黑旋风”在结束阶段会被送至墓地，且自己受到１０００伤害。此效果发动后，直至回合结束时为止自己从额外牌组仅可特殊召唤暗属性怪兽。','\r',char(13)),'\n',char(10)),'','是否召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81471108,'ZEXAL兵器－风神云龙剑','①：“ZEXAL兵器－风神云龙剑”在自己场上仅可有１张以表侧表示形式存在。②：以自己场上的１只“希望皇霍普”怪兽为对象可以发动。从自己的手牌・场上，将此卡视为攻击力上升１３００的装备卡，装备于该自己的“希望皇霍普”怪兽。③：此卡被装备中的情况下，对手不可将装备怪兽作为效果的对象。④：装备怪兽将被战斗破坏的情况下，破坏此卡作为代替。','装备','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81476402,'恶夜龙 邪恶骑士龙',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：此卡存在于手牌的情况下，解放此卡以外的、自己手牌・场上的1只暗属性怪兽可以发动。将此卡特殊召唤。\r\n②：此卡因战斗被破坏时，以对手场上的1只怪兽为对象可以发动。将该怪兽送至墓地。然后，可将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','送至墓地','是否特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81481818,'拼布绒毛动物',replace(replace('①：此卡只要存在于怪兽区，被视为“魔玩具”怪兽。\r\n②：此卡只要存在于怪兽区，可代替１只“魔玩具”融合怪兽上记载有卡牌名的融合素材怪兽。那时，其他的融合素材怪兽必须是正规品。','\r',char(13)),'\n',char(10)),'代替素材','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81489939,'魔人之歌','只要此卡存在于场上，对手场上所有怪兽的等级下降１。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81492226,'太古之壶','非常脆弱的太古之壶，里面好像还潜藏着什么东西。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81497285,'迷宫城的白银姬・拉比丽斯',replace(replace('此卡名的①③效果1回合仅可各使用1次。\r\n①：在有“迷宫城的白银姬・拉比丽斯”以外的“拉比丽斯”卡的效果、或通常陷阱卡发动过的自己・对手回合可以发动。从手牌将此卡以守备表示特殊召唤。\r\n②：只要自己场上存在里侧表示的卡，此卡就不会因对手的效果被破坏，对手不可将此卡作为效果的对象。\r\n③：通常陷阱卡发动时可以发动。从牌组将1张卡名与该卡不同的通常陷阱卡放置在自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81497286,'迷宫城的白银姬・拉比丽斯',replace(replace('此卡名的①③效果1回合仅可各使用1次。\r\n①：在有“迷宫城的白银姬・拉比丽斯”以外的“拉比丽斯”卡的效果、或通常陷阱卡发动过的自己・对手回合可以发动。从手牌将此卡以守备表示特殊召唤。\r\n②：只要自己场上存在里侧表示的卡，此卡就不会因对手的效果被破坏，对手不可将此卡作为效果的对象。\r\n③：通常陷阱卡发动时可以发动。从牌组将1张卡名与该卡不同的通常陷阱卡放置在自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81510157,'灵魂捕获者','①：以对手场上的1只表侧表示怪兽为对象可以发动。将对手的该表侧表示怪兽破坏。然后，对手恢复1000LP。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81519836,'苗与霞的春化精','此卡名的①效果１回合仅可使用１次。①：从手牌将此卡和、１只怪兽或１张“春化精”卡舍弃可以发动。从牌组将“苗与霞的春化精”以外的１只天使族・地属性怪兽加入手牌。然后，可从自己的墓地挑选１只地属性怪兽特殊召唤。此回合，自己不可发动地属性以外的怪兽的效果。②：只要此卡存在于怪兽区域，场上“春化精”怪兽以外的怪兽的攻击力下降６００。','是否从墓地特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81522098,'迷拟宝箱鬼・火龙',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：在自己的主要阶段可以发动。从手牌将此卡以里侧守备表示特殊召唤至对手场上。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从牌组将1张“迷拟宝箱鬼”魔法・陷阱卡加入手牌。\r\n③：此卡在主要阶段反转的情况下发动。分别适用以下效果。\r\n●将“迷拟宝箱鬼”怪兽以外的、自己场上的表侧表示怪兽全部破坏。\r\n●将此卡的控制权转移给对手。','\r',char(13)),'\n',char(10)),'破坏并转移控制权','特殊召唤','检索','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81524756,'天穹之圣骑联盟','此卡名以①方法的特殊召唤1回合仅可进行1次，且②效果1回合仅可使用1次。①：此卡可从手牌以守备表示特殊召唤至连接怪兽连接端的自己场上。②：以自己场上的1只“圣骑联盟”连接怪兽为对象可以发动。此回合，自己仅可用该怪兽攻击，该怪兽因与对手怪兽的战斗给予对手的战斗伤害变为两倍。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81524977,'种子子弹','每次植物族怪兽被召唤・反转召唤・特殊召唤时，放１个植物计数物在此卡（最多５个）。可将场上的此卡送至墓地并发动。给予对手LP放在此卡的植物计数物数量×５００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81549048,'龙华三界流转',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：从自己手牌・牌组・墓地将１只“龙华”怪兽特殊召唤。以此效果特殊召唤的怪兽将在结束阶段被放回手牌。\r\n②：将墓地的此卡除外，以自己场上・墓地・除外状态的１张“龙华”永续魔法卡为对象可以发动。将该卡放回牌组最下面。然后，自己抽１张。','\r',char(13)),'\n',char(10)),'特殊召唤','回收','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81555617,'惨绝戏之随兴凶剧','此卡名的①②效果１回合仅可各使用１次。①：在自己的主要阶段可以发动。场上所有怪兽的攻击力直至对手回合结束时为止，上升相当于自身等级×１００的数值。②：手牌・场上的此卡成为融合召唤的素材，并被送至墓地的情况下或被除外的情况下，从自己墓地的怪兽及被除外的自己的怪兽中，以“惨绝戏之随兴凶剧”以外的１只“惨绝戏”怪兽或等级８以上的融合怪兽为对象可以发动。将该怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81558967,'女战神・四女',replace(replace('此卡牌名的①②效果１回合只可各使用１次。\r\n①：在我方主要阶段可发动。从我方牌组上方翻阅卡牌，其数量相当于我方场上除此卡以外的“女战神”怪兽数量。其中有通常魔法、通常陷阱卡的场合，挑选其中１张并加入手牌，将剩馀的所有卡牌送入墓地。没有的场合，将翻阅的所有卡牌返回至牌组。\r\n②：此卡因战斗被破坏并送入墓地时可发动。从牌组特殊召唤１只“女战神”怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81560239,'巳剑降临',replace(replace('①：可从以下效果中选择1个发动（此卡名的以下效果1回合仅可各选择1次）。\r\n●为使合计等级与仪式召唤的怪兽相等，解放自己手牌・场上的爬虫类族怪兽，从牌组将1只爬虫类族仪式怪兽仪式召唤。\r\n●为使合计等级与仪式召唤的怪兽相等，解放自己手牌・牌组・场上的最多2只爬虫类族怪兽，从手牌将1只爬虫类族仪式怪兽仪式召唤。','\r',char(13)),'\n',char(10)),'发动','从牌组仪式召唤','从手牌仪式召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81563416,'泉之妖精','守卫泉水的妖精。对所有污染泉水者毫不留情地发动攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81566151,'元素－英雄 火焰新宇侠',replace(replace('“元素－英雄 新宇侠”＋“新空间人・火焰甲虫”\r\n仅限我方场上的上述卡牌返回至持有者牌组的场合，可从额外牌组特殊召唤（不需要“融合”）。此卡的攻击力上升相当于场上的魔法、陷阱卡数量×４００点。此外，结束阶段时，此卡返回至持有者的额外牌组。','\r',char(13)),'\n',char(10)),'返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81570454,'焰圣骑士－罗兰','此卡名的①②效果１回合仅可各使用１次。①：以自己场上的１只表侧表示怪兽为对象可以发动。将此卡视为攻击力上升５００的装备卡，从手牌装备于自己的该怪兽。此效果在对手回合中也可以发动。②：在此卡被送至墓地的回合的结束阶段可以发动。从牌组将１只“焰圣骑士－罗兰”以外的战士族・炎属性怪兽或１张装备魔法卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81571633,'DD高傲食人魔',replace(replace('←8 【灵摆】 8→\r\n①：１回合１次，可支付５００LP，并以我方场上１只“DD”怪兽为对象发动。该怪兽的攻击力上升５００。\n②：另一边的我方灵摆区不存在有“DD”卡牌的场合，此卡的P刻度变成５。\r\n【怪兽效果】\r\n①：此卡召唤成功时可发动。从我方额外牌组特殊召唤１只表侧表示的暗属性灵摆怪兽。以此效果特殊召唤而来的怪兽效果被无效化，此效果发动后，直至回合结束时，我方只可特殊召唤“DD”怪兽。','\r',char(13)),'\n',char(10)),'攻守变换','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81587028,'玩具箱',replace(replace('此卡牌名的效果１回合只可使用１次。\r\n①：此卡被破坏并送入墓地的场合可发动。从牌组以守备表示特殊召唤２只攻击力或守备力为０的通常怪兽（同名卡最多１张）。以此效果特殊召唤的怪兽不可作为同步素材，并在下一个我方结束阶段被破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81599449,'化合兽碳蟹',replace(replace('①：只要此卡存在于场上、墓地，被视为通常怪兽。\r\n②：被视为场上的通常怪兽的此卡，可作为通常召唤再１次召唤。此种场合此卡被视为效果怪兽获得以下效果。\r\n●可在我方主要阶段发动。从牌组将１只二重怪兽送入墓地。之后，从牌组将１只二重怪兽加入手牌。“化合兽碳蟹”的此效果１回合只可使用１次。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81601517,'二重反击','将１只以表侧表示存在于我方场上的二重怪兽变为里侧守备表示，令对手魔法卡的发动无效并将其破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81612598,'炼装勇士・精金','“炼装勇士”怪兽＋攻击力２５００或以下的怪兽','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81613061,'岩吼战士・灵媒',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：只要被特殊召唤的怪兽存在于对手场上、自己场上存在等级７以上的“岩吼战士”怪兽，在双方的主要阶段１期间，双方不可发动场上怪兽的效果。\r\n②：在自己的主要阶段可以发动。从牌组挑选１张“岩吼战士・灵媒”以外的“岩吼战士”魔法・陷阱卡放置在自己场上。此效果发动后，直至回合结束时为止，自己仅可特殊召唤战士族怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81615450,'爬虫妖分歧',replace(replace('此卡名的卡１回合仅可发动１张。①：将１张手牌送至墓地，可从以下效果选择２个发动。\r\n●从牌组将１只“爬虫妖”怪兽加入手牌。\r\n●从牌组将“爬虫妖分歧”以外的１张“爬虫妖”魔法・陷阱卡加入手牌。\r\n●挑选对手场上的１只怪兽，将该攻击力改成０。','\r',char(13)),'\n',char(10)),'选择效果发动','检索「爬虫妖」怪兽','检索「爬虫妖」魔法·陷阱卡','对手怪兽攻击力变成0','','','','','','','','','','','','');
INSERT INTO texts VALUES(81616639,'僵尸女孩','①：此卡因对手被破坏的情况下，以自己墓地1只“僵尸女孩”以外的等级4以下的怪兽为对象可以发动。将该怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81618817,'杰米亚之神','擅长欺骗对手并将其引诱至毁灭之路的邪神。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81650695,'狱神机 终刻',replace(replace('此卡名的②③效果1回合仅可各使用1次。\r\n①：自己从额外牌组仅可特殊召唤超量怪兽。\r\n②：以自己场上的1只其他的效果怪兽为对象可以发动。从额外牌组将阶级与该自己的怪兽的等级数值相同的1只“终刻”超量怪兽或“坏狱神 朱庇特”重叠在对象怪兽上面，视为超量召唤特殊召唤，将自己场上的此卡视为装备魔法卡装备。\r\n③：此卡被破坏的情况下可以发动。从牌组将1张“终刻”卡加入手牌。','\r',char(13)),'\n',char(10)),'超量召唤','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81661951,'龙骑兵团－士兵','①：1回合1次，以自己的魔法与陷阱区域的1张“龙骑兵团”怪兽卡为对象可以发动。将该卡特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81665333,'撤收命令','将我方场上的怪兽全部返回至持有者手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81670445,'时潜怪盗・停秒','此卡名的②效果1回合仅可使用1次。①：只要此卡存在于魔法与陷阱区域，自己场上的超量怪兽在特殊召唤的回合，不会成为对手效果的对象，也不会因对手的效果而被破坏。②：以自己场上的1只超量怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止，上升相当于其超量素材数量×300的数值。该怪兽所持有的超量素材中，有原本持有者为对手的卡的情况下，进而在此回合该怪兽可直接攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81674782,'次元的裂缝','①：只要此卡存在于魔法与陷阱区域，被送往墓地的怪兽不去墓地而直接被除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81677154,'冥铭途・海马',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己场上不存在“冥铭途”怪兽以外的表侧表示怪兽的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：在自己的主要阶段可以发动。将自己场上的１只“冥铭途”怪兽破坏，从牌组将等级合计为所破坏怪兽原本等级以下的“冥铭途”怪兽送至墓地（同名卡最多１张）。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81684048,'墓场的鬼魂王－南瓜王－',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：向对手出示手牌的此卡可以发动。从自己牌组・墓地将1张“活死人的呼唤”放置在自己场上，挑选自己的1张手牌舍弃。以此效果放置的卡在放置的回合也可以发动。\r\n②：此卡特殊召唤的情况下可以发动。从牌组将1只攻击力1950以外的不死族・等级6怪兽特殊召唤。此回合，自己从手牌・墓地仅可特殊召唤不死族怪兽。','\r',char(13)),'\n',char(10)),'放置','特殊召唤','适用「墓场的鬼魂王－南瓜王－」的效果来发动','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81686058,'赛莲','能操纵风并能吹起疾风吹飞所有事物。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81696879,'影魔百夫骑士 西梅莉娅',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：对手在连锁２以后发动怪兽的效果时可以发动。该效果变为“对手将自身场上（表侧表示）・墓地的１只“百夫骑”怪兽视为永续陷阱卡，以表侧表示放在自身的魔法与陷阱区域”。此回合，自己不可特殊召唤“影魔百夫骑士 西梅莉娅”。\r\n②：此卡视为永续陷阱卡的情况下，在自己・对手的主要阶段可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'效果变换','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81743801,'龙王 恐龙王',replace(replace('①：以此卡的攻击破坏对手怪兽时可以发动。此战斗阶段中，此卡可再攻击仅１次。\r\n②：此卡不是在此回合被召唤・反转召唤・特殊召唤的情况下，１回合１次，以对手场上的最多２只怪兽为对象可以发动。将该怪兽破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81752019,'花札卫－松－',replace(replace('“花札卫－松－”的①效果１回合只可使用１次。\r\n①：此卡召唤成功的场合发动。我方从牌组抽取１张卡牌，并双方相互确认。该卡是“花札卫”怪兽以外的场合，将该卡送入墓地。\r\n②：此卡因战斗或对手的效果被破坏并送入墓地的场合可发动。我方从牌组抽取１张卡牌。','\r',char(13)),'\n',char(10)),'抽1张卡并给双方确认','抽1张卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81755371,'暗黑结构体','上级召唤暗属性通常怪兽的场合，此卡可作为２只怪兽来解放。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81756619,'讴歌死亡的绿柱魔瞳',replace(replace('①：此决斗中，分别适用以下效果。\r\n●自己不可发动手牌的怪兽的效果。\r\n●自己的怪兽在１次战斗阶段中最多可攻击怪兽２次。\r\n●自己的怪兽与对手怪兽的战斗给予对手的战斗伤害变为两倍。\r\n②：将墓地的此卡除外可以发动。从牌组将１张“绿柱魔瞳”卡加入手牌。然后，挑选自己的１张手牌放回牌组最下面。','\r',char(13)),'\n',char(10)),'发动','检索','「讴歌死亡的绿柱魔瞳」效果适用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81756897,'杰拉的仪式','降临“杰拉”的必备。必须从手牌・我方场上解放合计等级达到８以上的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81758313,'一日万倍龙',replace(replace('①：在自己・对手的结束阶段，支付100LP可以发动。在此卡上放1个万倍计数物。\r\n②：1回合1次，在自己的主要阶段可以发动。双方的LP之差每有1000，就在此卡上放1个万倍计数物。\r\n③：只要此卡的万倍计数物的数量在10以上，此卡的攻击力・守备力上升10000。\r\n④：此卡将被战斗・效果破坏的情况下，作为代替去除此卡的1个万倍计数物。','\r',char(13)),'\n',char(10)),'放置计数物','放置计数物','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81759748,'黑暗蜘蛛','１回合１次，可选择１只我方场上的昆虫族怪兽，直至回合结束时，可上升该等级２级。','等级上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81767888,'烙印之剑',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：从自己墓地将任意数量的“烙印”魔法・陷阱卡除外可以发动。依所除外的数量，将“冰剑衍生物”（龙族・暗・星8・攻2500/守2000）特殊召唤至自己场上。\r\n②：将墓地的此卡除外，以自己除外状态的1只“阿尔白斯之落胤”或记载有该卡名的怪兽为对象可以发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81767889,'冰剑衍生物','由“烙印之剑”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81769387,'扇风机块 螺旋风扇狮',replace(replace('“机块”怪兽１只\r\n此卡在被连接召唤的回合中不可作为连接素材。\r\n①：此卡可直接攻击。\r\n②：１回合１次，此卡处于相互连接状态的情况下，自己与对手的怪兽之间进行战斗的伤害计算时可以发动。该对手怪兽的攻击力仅在该伤害计算时变为０。\r\n③：１回合１次，不处于相互连接状态的此卡与对手怪兽进行战斗的伤害计算时可以发动。该对手怪兽的攻击力仅在该伤害计算时变为０。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81777047,'光芒冲击','场上光属性怪兽的攻击力上升５００点，守备力下降４００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81782101,'爬虫蛋',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：此卡不会因战斗被破坏。\r\n②：此卡召唤成功的情况下，在下一个自己回合的准备阶段，解放此卡可以发动。从手牌・牌组将最多３只等级４以下的爬虫类族・岩石族怪兽特殊召唤（特殊召唤２只以上的情况下必须都是同名怪兽）。以此效果特殊召唤的怪兽将在结束阶段被除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81782376,'命运的发掘',replace(replace('①：我方受到战斗伤害时可发动。我方从牌组抽取１张卡牌。\r\n②：场上的此卡因对手效果被破坏的场合可发动。我方从牌组抽取卡牌，其数量相当于我方墓地“命运的发掘”的张数。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81788994,'影牢之咒缚','①：每次当“影依”怪兽因效果被送至墓地，每有1只给此卡放1个魔石计数物。②：对手场上怪兽的攻击力在对手回合期间下降此卡的魔石计数物数量×100。③：每次自己将“影依”融合怪兽融合召唤可以有1次，去除3个此卡的魔石计数物，并将对手场上1只表侧表示的怪兽作为融合素材。','是否要把对手场上1只表侧表示怪兽作为融合素材？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81791932,'蛇哨','我方场上表侧表示的爬虫类族怪兽因战斗以外的方式被破坏时可发动。从牌组中特殊召唤１只等级４或以下的爬虫类族怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81794107,'R.B.拉姆达加农',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下，以“R.B.拉姆达加农”以外的、自己墓地的1只“R.B.”怪兽为对象可以发动。将该怪兽加入手牌。\r\n②：此卡和“R.B.”连接怪兽为连接状态的情况下，支付1200LP可以发动。将此卡破坏，确认对手的所有手牌。然后，可挑选其中的1只怪兽特殊召唤至对手场上。以此效果特殊召唤的怪兽的效果无效化。','\r',char(13)),'\n',char(10)),'检索效果','特殊召唤','是否特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81810441,'辉星骑士的因子','仅可装备于自己场上的“星骑士”怪兽。①：装备怪兽的攻击力・守备力上升５００。装备怪兽不受对手的卡的效果影响。②：自己场上有“星骑士”怪兽以外的怪兽以表侧表示存在的情况下，此卡将被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81816475,'叠放吞噬者','可将墓地中的这张卡从游戏中除外并发动。将对手场上的１个超量素材放在我方超量怪兽下，作为超量素材。','素材夺取','请选择一只超量怪兽','请选择要转移的素材','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81820689,'菜鸟侦探','可指定对手１张手牌进行观看。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81823360,'巨型碎噬者 X','在远古的海面上突然现身的恐龙型生体机器人。依靠其引以为豪的消声装甲可悄悄来到猎物身后，毫无动静地扑上去。但因切换成捕食模式后身体就会发光，所以总是让猎物逃掉。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81825063,'冰结界的虎将 韦恩',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：对手场上存在怪兽，且自己场上存在“冰结界”怪兽的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从牌组将１张“冰结界”魔法・陷阱卡加入手牌。\r\n③：只要此卡存在于怪兽区域，从场上被送往对手墓地的魔法・陷阱卡不去墓地而直接被除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81843628,'针异虫','反转：从对手牌组上面将５张卡送至墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81846453,'武力军奏',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的①效果1回合仅可使用1次。\r\n①：此卡同步召唤的情况下，以自己墓地的1只协调为对象可以发动。将该怪兽以守备表示特殊召唤。以此效果特殊召唤的怪兽的效果无效化。\r\n②：只要以此卡作为同步素材的同步怪兽在场上以表侧表示存在，视为协调。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81846636,'宝石骑士・琉璃','①：此卡因效果被送至墓地的情况下，以自己墓地的1只通常怪兽为对象可以发动。将该怪兽加入手牌。','加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81863068,'魔鬼的侦察者','反转：对手从牌组抽取３张卡牌。双方确认以此效果抽取的卡牌，并将其中的所有魔法卡舍弃至墓地。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81866673,'命运－英雄 冲刺魔侠','①：1回合1次，解放自己场上的1只怪兽可以发动。此卡的攻击力直至回合结束时为止上升1000。②：此卡攻击过的情况下，战斗阶段结束时变为守备表示。③：只要此卡存在于墓地，仅限1次，自己在自己的抽牌阶段抽卡时，抽到的卡为怪兽的情况下，将该1只怪兽给双方确认可以发动。此卡存在于墓地的情况下，将该确认的怪兽特殊召唤。','攻击上升','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81873903,'进化虫・西洛仙蜥','①：此卡反转的情况下发动。从牌组将１只“进化龙”怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81878201,'邃渊突刺－三叉戟',replace(replace('此卡名的卡１回合仅可发动１张，此卡名的③效果１回合仅可使用１次。\r\n①：从自己手牌・墓地将１只“海皇”怪兽或“水精鳞”怪兽特殊召唤，并装备此卡。\r\n②：装备怪兽将被战斗・效果破坏的情况下，作为代替可将此卡送至墓地。\r\n③：将墓地的此卡除外，以自己墓地・除外状态的最多３只鱼族・海龙族・水族怪兽为对象可以发动。将该怪兽放回牌组。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81881839,'双重曝光',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：以场上２只等级６以下的同名怪兽为对象可以发动。该怪兽的等级变为两倍。\r\n②：在自己・对手的战斗阶段开始时，以自己场上的１只“光波”怪兽为对象可以发动。挑选场上该怪兽以外的１只表侧表示怪兽，直至结束阶段为止，将其卡名和对象“光波”怪兽视为同名卡。','\r',char(13)),'\n',char(10)),'等级变成2倍','改变卡名','请选择自己的「光波」怪兽','请选择要改变卡名的怪兽','','','','','','','','','','','','');
INSERT INTO texts VALUES(81896370,'疾风鸟人 乔','解放风属性怪兽并上级召唤成功时发动。场上的魔法、陷阱卡全部返回至持有者手牌。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81896771,'电力绿雉',replace(replace('①：此卡可直接攻击。\r\n②：此卡以直接攻击给予对手战斗伤害的情况下，以场上的１只表侧表示怪兽为对象发动。将该表侧表示怪兽直至结束阶段为止除外。','\r',char(13)),'\n',char(10)),'暂时除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81907872,'鬼计・幽灵','仅在自己场上有“鬼计”怪兽存在的情况下，此卡才可以表侧表示召唤。①：“鬼计”怪兽因对手的攻击・效果被破坏并被送至自己墓地时可以发动。将此卡从手牌以里侧守备表示特殊召唤，从牌组抽１张。②：在自己的主要阶段可以发动。将此卡改成里侧守备表示（１回合仅１次）。','变成里侧守备','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81913510,'NEX','将我方场上１只表侧表示的冠有“新空间人”之名的怪兽送入墓地，从额外牌组特殊召唤１只视为送入墓地卡牌的同名卡牌的等级４的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81914447,'能－朋.克.鬼曲','此卡名的①②效果1回合仅可各使用1次。①：解放自己场上的1只“朋.克.”怪兽可以发动。从手牌将此卡特殊召唤。②：将手牌・场上的此卡送至墓地可以发动。从牌组将1只等级8以外的“朋.克.”怪兽加入手牌。③：1回合1次，对手发动怪兽的效果时可以发动。此卡的攻击力直至回合结束时为止，上升相当于该对手怪兽原本攻击力的数值。','此卡特殊召唤','牌组检索','攻击力上升','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81916745,'红镰华',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡存在于怪兽区域的状态下，其他怪兽从场上被送至对手墓地的情况下可以发动（伤害步骤也可以发动）。依其中1只的攻击力的数值恢复自己的LP。\r\n②：此卡存在于墓地的状态下，对手受到效果伤害的情况下，将此卡除外可以发动。将场上的1只攻击力在双方LP的数值之差以下的怪兽送至墓地。','\r',char(13)),'\n',char(10)),'回复基本分','送至墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81919143,'大脑粉碎者','１回合１次，此卡因战斗破坏对手怪兽并将其送入墓地的回合结束阶段时可发动。选择１只该怪兽并从墓地特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81927732,'急袭猛禽－革命猎鹰',replace(replace('鸟兽族等级6怪兽×3\r\n①：去除此卡的1个超量素材可以发动。此回合，此卡可攻击所有对手怪兽各1次。②：此卡与被特殊召唤的表侧表示怪兽进行战斗的伤害步骤开始时发动。将该怪兽的攻击力・守备力改成0。③：此卡持有“急袭猛禽”超量怪兽作为超量素材的情况下，获得以下效果。\r\n●1回合1次，以对手场上的1只怪兽为对象可以发动。破坏该怪兽，给予对手相当于其攻击力一半数值的伤害。','\r',char(13)),'\n',char(10)),'多次攻击','怪兽破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81933259,'魔鬼镜的仪式','用于召唤“魔鬼镜”。必须从手牌・我方场上解放合计等级达到６以上的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81945676,'冥铭途・梅思',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：在对手的主要阶段，自己场上存在“冥骸合龙－冥铭途拉尔泰库特利卡”的情况下，从手牌将此卡舍弃，以对手场上的１只表侧表示怪兽为对象可以发动。直至结束阶段为止获得该怪兽的控制权。\r\n②：在自己的主要阶段可以发动。将自己场上的１只“冥铭途”怪兽破坏，从牌组将“冥铭途・梅思”以外的１张“冥铭途”卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81945678,'王牌百搭',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：在自己・对手的主要阶段及战斗阶段，从牌组将记录有“王后骑士”、“卫兵骑士”、“国王骑士”的全部卡名的１张魔法卡送至墓地可以发动。此效果变为与该魔法卡发动时的效果相同。\r\n②：在自己・对手的结束阶段，以自己墓地的１只战士族・光属性怪兽为对象可以发动。将该怪兽放回牌组，将墓地的此卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81951640,'奇动装置 恣动机',replace(replace('此卡名的②效果１回合仅可使用１次。①：１回合１次，可从以下效果中选择１个发动。\r\n●以自己场上的１只表侧表示怪兽为对象，将此卡视为装备卡装备于该怪兽。装备怪兽将被战斗・效果破坏的情况下，破坏此卡作为代替。\r\n●将被装备的此卡特殊召唤。\r\n②：装备于怪兽的此卡被破坏并被送至墓地的情况下可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81954378,'死神的大镰－迪斯赛斯',replace(replace('仅限装备“守护者・迪斯赛斯”。\r\n①：装备怪兽的攻击力上升双方墓地的怪兽数量×５００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81962318,'龙骑兵团－保民官','①：此卡召唤・特殊召唤时可以发动。从牌组将1只等级3以下的龙族怪兽送至墓地。','检索送墓','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81974607,'光波翼机','①：自己场上有“光波”怪兽存在的情况下，此卡可从手牌中特殊召唤。②：解放此卡可以发动。自己场上所有的“光波”怪兽的等级直至回合结束时为止上升４。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81977953,'荒漠龙卷怪','此卡不可通常召唤。仅限将我方墓地的２只风属性怪兽和１只地属性怪兽从游戏中除外的场合可特殊召唤。１回合１次，可舍弃１张手牌并发动，选择场上的１张魔法、陷阱卡破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81978611,'超量托付',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：从自己的牌组・墓地将１张“装甲超量”卡加入手牌。然后，挑选自己场上的最多２只表侧表示怪兽，可将其等级直至回合结束时为止全部改成３或全部改成５。\r\n②：从墓地将不是在此回合被送至墓地的此卡除外，以自己的魔法与陷阱区域１张视为装备卡的超量怪兽卡为对象可以发动。将该卡特殊召唤。','\r',char(13)),'\n',char(10)),'「装甲超量」卡加入手牌','特殊召唤当作装备卡使用的超量怪兽','选怪兽等级变成3星','选怪兽等级变成5星','不改变等级','请选择要改变等级的怪兽','','','','','','','','','','');
INSERT INTO texts VALUES(81983656,'黑羽驯鸟师－漆黑之鹰匠',replace(replace('“黑羽”协调＋协调以外的“黑羽”怪兽1只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：以自己墓地的1只等级5以上的鸟兽族怪兽为对象可以发动。将该怪兽特殊召唤。\r\n②：仅场上的此卡成为对手的攻击・效果对象时，以自己场上的1只其他的“黑羽”怪兽为对象可以发动。将该对象移换至能成为其正确对象的该怪兽。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81985784,'死亡戈兰林','反转：从我方墓地中选择１张卡牌，将其加入到我方的牌组并进行洗牌。','返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81992475,'彼岸恶鬼 巴巴利却','此卡名的①③效果1回合1次，仅可使用其中1个。①：自己场上没有魔法・陷阱卡存在的情况下可以发动。从手牌将此卡特殊召唤。②：自己场上有“彼岸”怪兽以外的怪兽存在的情况下此卡将被破坏。③：此卡被送至墓地的情况下，以“彼岸恶鬼 巴巴利却”以外的自己墓地的最多3张“彼岸”卡为对象可以发动。将该卡除外，给予对手除外数量×300的伤害。','特殊召唤','效果伤害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81994591,'核成的金刚核','从牌组将１张除“核成的金刚核”以外冠有“核成”之名的卡牌加入手牌。此外，可将墓地的此卡从游戏中除外并发动。此回合，我方场上冠有“核成”之名的怪兽不会被破坏。','加入手牌','防止破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(81997228,'调皮宝贝・屋子管家',replace(replace('“调皮宝贝・火灯娃”＋“调皮宝贝・水滴娃”＋“调皮宝贝・脉冲娃”\r\n此卡仅可以融合召唤来特殊召唤。\r\n此卡名的②效果１回合仅可使用１次。\r\n①：解放此卡可以发动。将对手场上的怪兽全部破坏。此效果在对手回合中也可以发动。\r\n②：此卡被对手送至墓地的情况下，以自己墓地融合怪兽以外的１只怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82003859,'通行税','双方玩家若不支付５００LP，则不可攻击宣言。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82005435,'女忍者 八重','从手牌中舍弃１张风属性怪兽至墓地。将存在于对手场上魔法、陷阱卡全部返回至持有者手牌。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82012319,'废铁魔像','①：１回合１次，以自己墓地１只等级４以下的“废铁”怪兽为对象可以发动。将该怪兽特殊召唤至自己或对手场上。','特殊召唤','在自己场上特殊召唤','在对手场上特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82016179,'森罗的施舍','从牌组抽３张卡。然后，挑选包含１张“森罗”卡在内的２张手牌的卡，以喜欢的顺序放回牌组上面。手牌中没有“森罗”卡的情况下，将手牌全部公开，以喜欢的顺序放回牌组上面。“森罗的施舍”１回合仅可发动１张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82035781,'双头猛兽','①：此卡在１次战斗阶段中可以攻击２次。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82041999,'净－朋.克.蜘蛛夫人','此卡名的①②效果1回合仅可各使用1次。①：支付600LP可以发动。从牌组将1张“朋.克.”陷阱卡加入手牌。②：以对手场上的卡作为对象的自己的“朋.克.”卡的效果发动时，以对手场上的1只表侧表示怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止变为一半。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82044279,'清透翼同步龙',replace(replace('协调＋协调以外的怪兽1只以上\r\n①：1回合1次，场上的其他等级5以上的怪兽的效果发动时可以发动。将该发动无效并破坏。\r\n②：1回合1次，仅以场上的1只等级5以上的怪兽为对象的怪兽的效果发动时可以发动。将该发动无效并破坏。\r\n③：因此卡的效果破坏了怪兽的情况下，此卡的攻击力直至回合结束时为止，上升因此卡的效果破坏的怪兽的原本的攻击力的数值。','\r',char(13)),'\n',char(10)),'5星以上的怪兽的效果发动无效并破坏','5星以上的怪兽1只为对象的怪兽的效果发动无效并破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82044280,'清透翼同步龙',replace(replace('协调＋协调以外的怪兽1只以上\r\n①：1回合1次，场上的其他等级5以上的怪兽的效果发动时可以发动。将该发动无效并破坏。\r\n②：1回合1次，仅以场上的1只等级5以上的怪兽为对象的怪兽的效果发动时可以发动。将该发动无效并破坏。\r\n③：因此卡的效果破坏了怪兽的情况下，此卡的攻击力直至回合结束时为止，上升因此卡的效果破坏的怪兽的原本的攻击力的数值。','\r',char(13)),'\n',char(10)),'5星以上的怪兽的效果发动无效并破坏','5星以上的怪兽1只为对象的怪兽的效果发动无效并破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82045034,'百雷之雷龙','此卡名的卡1回合仅可发动1张。①：以自己墓地的1只雷族怪兽为对象可以发动。将该怪兽特殊召唤。然后可从自己的墓地尽可能将该怪兽的同名怪兽特殊召唤。以此效果特殊召唤的怪兽离开场上的情况下，将其除外。只要以此效果特殊召唤的怪兽存在于怪兽区域，自己仅可特殊召唤雷族怪兽。','是否特殊召唤同名怪兽？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82050203,'怒天怒天狗','此卡因对手卡牌效果被送入墓地的场合，可选择对手场上的１张卡牌并发动。被选择卡牌返回至持有者的手牌。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82052602,'我我我回归',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：自己场上的“我我我”怪兽因战斗被破坏并被送至墓地的回合可以发动。从自己墓地将此回合因战斗被破坏的怪兽以守备表示尽可能地特殊召唤。然后，自己受到以此效果特殊召唤的怪兽数量×600的伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82065276,'电眼英雄','来自异次元让人摸不清楚底细的战士。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82085295,'魔神仪－钢笔羽毛','此卡名的①②效果1回合1次，仅可使用其中1个。①：将手牌的1只仪式怪兽出示给对手可以发动。将“魔神仪-钢笔羽毛”以外的1只牌组的“魔神仪”怪兽和手牌的此卡特殊召唤。②：此卡从牌组特殊召唤成功的情况下，以自己墓地的1只仪式怪兽为对象可以发动。将该怪兽加入手牌。③：只要此卡存在于怪兽区域，自己不可从额外牌组特殊召唤怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82085619,'友情天使','即便在决斗中吵架，也会传达友情努力和好。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82090807,'阿尔银洛斯之落胤','此卡名以①方法的特殊召唤１回合仅可进行１次，且③效果１回合仅可使用１次。①：场上存在等级２・阶级２・连接２的怪兽中的任一的情况下，此卡可从手牌特殊召唤至自己或对手场上。②：连接端指向此卡的连接怪兽不可发动效果。③：在对手回合中，以场上的１只超量怪兽为对象可以发动。去除该怪兽的最多２个超量素材。','往自己场上特殊召唤','往对手场上特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82099401,'水晶占卜师','反转：从我方牌组上方翻阅２张卡牌，从中挑选１张加入手牌。之后，剩余的卡牌返回至牌组最下方。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82103466,'蛇神 格',replace(replace('此卡不可通常召唤，仅可以此卡的效果特殊召唤。\r\n①：自己场上的怪兽被对手的攻击・效果破坏的情况下，支付一半LP可以发动。从手牌将此卡特殊召唤。\r\n②：此卡不会成为效果的对象。\r\n③：此卡攻击对手怪兽的伤害步骤期间，将该怪兽的效果无效化，攻击力变为原本攻击力的一半。\r\n④：此卡进行战斗的伤害计算时可以发动。此卡的攻击力变为与场上怪兽最高的原本攻击力相同。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82105704,'皮尔莉・快乐回忆','①：挑选场上的１张卡，该卡直至下个回合结束时为止，仅１次不会因效果被破坏。进而可适用以下效果。●挑选１张自己的手牌舍弃，从牌组将１只等级１的“皮尔莉”怪兽特殊召唤。②：持有此卡作为素材的“皮尔莉”超量怪兽获得以下效果。●此卡在１次战斗阶段中可攻击怪兽的次数最多为此卡所持有的作为超量素材的“皮尔莉・快乐回忆”的数量＋１次。','是否从牌组特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82108372,'姆朵拉','我方的墓地中每存在１只天使族怪兽，此卡的攻击力便上升２００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82112494,'超重神童 若牛－U４',replace(replace('←8 【灵摆】 8→\r\n此卡名的灵摆效果１回合仅可使用１次。①：自己墓地不存在魔法・陷阱卡的情况下可以发动。从牌组挑选“超重神童 若牛－U４”以外的１只“超重武者”灵摆怪兽，放在自己的灵摆区域。然后将此卡特殊召唤。\r\n【怪兽效果】\r\n此卡名在规则上也视为“超重武者”卡。此卡名的①②怪兽效果１回合仅可各使用１次。①：自己墓地不存在魔法・陷阱卡的情况下，从手牌舍弃１只怪兽可以发动。从手牌・牌组将１只“超重武者”怪兽以守备表示特殊召唤。此效果发动后，直至回合结束时为止，自己仅可特殊召唤“超重武者”怪兽。②：此卡作为同步素材以表侧表示加入额外牌组的情况下可以发动。将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82112775,'D・D・M','１回合１次，可从手牌舍弃１张魔法卡，选择１只从游戏中被除外的我方怪兽并发动。特殊召唤该怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82114013,'多拉科尼亚的海龙骑兵',replace(replace('←7 【灵摆】 7→\r\n此卡名的灵摆效果１回合仅可使用１次。\n①：自己或对手的怪兽因战斗被破坏时可以发动。从手牌将１只通常怪兽特殊召唤。\r\n【怪兽效果】\r\n龙人族之国──多拉科尼亚帝国拥有的龙骑士团海军部队。该部队擅长从深海悄无声息地靠近袭击对象的隐秘作战，与对岸的迪隆公国军队因领海问题，一直处于小规模冲突状态。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82116191,'巨大土瓶草','场上的表侧表示植物族怪兽被送入墓地时发动。此卡的攻击力上升２００点。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82119326,'妖精传姬之尾',replace(replace('此卡名的③效果1回合仅可使用1次。\r\n①：装备怪兽的攻击力上升1000。\r\n②：1回合1次，在自己的主要阶段可以发动。将自己手牌・场上的怪兽作为融合素材，将1只魔法师族的融合怪兽融合召唤。在此之际，也可将对手场上的“妖精的王子大人”作为融合素材。\r\n③：此卡存在于墓地的情况下可以发动。将此卡装备于场上的1只“妖精传姬”怪兽。然后，可进行1只攻击力1850的魔法师族怪兽的召唤。','\r',char(13)),'\n',char(10)),'融合召唤','装备效果','是否进行召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82128978,'书灵师・魔法女孩',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡存在于手牌的情况下，向对手出示手牌的1只仪式怪兽可以发动。将此卡特殊召唤。\r\n②：在对手回合可以发动。为使合计等级达到仪式召唤的怪兽的等级以上，解放自己手牌・场上的怪兽，从手牌将1只“书灵师”仪式怪兽仪式召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82134632,'梅尔菲过家家','①：去除自己场上任意数量的兽族超量怪兽的超量素材，以对手场上的卡为对象可以发动，数量最多为去除的数量。将该卡放回持有者的手牌。自己场上所有兽族超量怪兽的攻击力直至回合结束时为止，上升相当于为发动此卡去除的超量素材数量×５００的数值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82135803,'怒魔镌刻・迪厄斯伊雷',replace(replace('“刻魔印契之魔镌客”＋恶魔族・光属性怪兽×２\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：在自己・对手回合中可以发动。挑选场上的表侧表示卡，数量最多为此卡装备中的连接怪兽的连接标记的合计，将其效果直至回合结束时为止无效。\r\n②：此卡被送至墓地的情况下，从自己的墓地将１只其他的恶魔族・光属性怪兽放回牌组・额外牌组，以场上的１张卡为对象可以发动。将该卡送至墓地。','\r',char(13)),'\n',char(10)),'无效效果','送至墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82140600,'约束之地 －阿瓦隆－','①：可以我方墓地５只各包含１只“阿托利斯”和“兰斯洛特”怪兽的“圣骑士”怪兽为对象发动。将该怪兽除外，并破坏场上的所有卡牌。','场上的卡全部破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82159583,'小丑戏帮 白脸',replace(replace('此卡可通过解放1只仪式・融合・同步・超量・灵摆・连接怪兽来以表侧表示上级召唤。\r\n①：此卡上级召唤的情况下，可从以下效果中选择1个发动（此卡名的以下效果1回合仅可各选择1次）。\r\n●依为上级召唤此卡而解放的怪兽的数量，自己抽牌。\r\n●依为上级召唤此卡而解放的怪兽的数量，将对手场上的表侧表示卡的效果无效。\r\n②：1回合1次，在对手的主要阶段可以发动。进行1只怪兽的上级召唤。','\r',char(13)),'\n',char(10)),'用1只怪兽解放召唤','选择效果','上级召唤','抽牌','无效','','','','','','','','','','','');
INSERT INTO texts VALUES(82162616,'永远之银河','此卡名的卡1回合仅可发动1张。①：自己场上有“光子”怪兽或“银河”怪兽存在的情况下，以自己场上的1只超量怪兽为对象可以发动。将1只比自己的该怪兽阶级高4的“光子”超量怪兽或“银河”超量怪兽重叠在对象怪兽上面，从额外牌组特殊召唤，且视为超量召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82176812,'魔装战士 水陆龟','①：此卡反转的场合，以对手场上的１张魔法、陷阱卡为对象发动。破坏该卡。','魔陷破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82184400,'邃渊卫士',replace(replace('水属性怪兽２只\r\n此卡名的①②效果１回合仅可各使用１次。\r\n此卡被连接召唤的回合不可作为连接素材。\r\n①：此卡连接召唤的情况下可以发动。从手牌将１只鱼族怪兽特殊召唤至此卡连接端的自己场上。\r\n②：以自己场上１只其他的鱼族怪兽和对手场上的１张卡为对象可以发动。将该卡除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82190203,'光翼之龙',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：在自己・对手的主要阶段可以发动。从牌组将１只“霸王眷龙”灵摆怪兽或“霸王门”灵摆怪兽加入手牌。自己场上存在“霸王龙扎克”的情况下，也可不加入手牌而是改为将其特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82197831,'蓦进装甲 犀牛军刀',replace(replace('协调＋１只以上协调以外的怪兽\r\n此卡名的①②效果１回合仅可各使用１次。①：舍弃任意张数的手牌可以发动。此卡的攻击力上升相当于舍弃数量×７００的数值。②：此卡进行过战斗的战斗阶段结束时，将此卡送至墓地可以发动。从自己的墓地挑选等级合计为７的“蓦进装甲 犀牛军刀”以外的怪兽特殊召唤。以此效果特殊召唤的怪兽的效果无效化。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82199284,'霞之谷的猎鹰','此卡必须将除此卡以外的我方场上的１张卡牌返回至手牌才可进行攻击宣言。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82213171,'暗王 普罗米修斯','此卡召唤成功时，挑选我方墓地任意数量的暗属性怪兽并从游戏中除外。直至回合结束时，此卡的攻击力上升以此效果除外的卡牌数量×４００点。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82224646,'娱乐伙伴 异色眼同步士',replace(replace('←6 【灵摆】 6→\r\n①：１回合１次，以自己场上的１只“娱乐伙伴”怪兽或“异色眼”怪兽为对象可以发动。此回合，该表侧表示怪兽视为协调，等级变为１。\r\n【怪兽效果】\r\n从额外牌组特殊召唤的此卡被用于同步召唤的情况下将被除外。①：此卡召唤成功时，以自己的墓地１只等级３以下的“娱乐伙伴”怪兽或“异色眼”怪兽为对象可以发动。将该怪兽特殊召唤。以此效果特殊召唤的怪兽的效果无效化。②：１回合１次，以自己灵摆区域的１张卡为对象可以发动。将该卡的效果无效并特殊召唤，仅以该卡和此卡作为素材，将１只同步怪兽同步召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82243738,'天使欧１','此卡名以①方法的特殊召唤1回合仅可进行1次。①：将手牌的1只等级7以上的怪兽出示给对手，可从手牌特殊召唤此卡。②：只要特殊召唤的此卡存在于怪兽区域，自己在通常召唤之外仅可追加1次，在自己的主要阶段将1只等级7以上的怪兽以表侧攻击表示上级召唤。','','使用「天使欧１」的效果上级召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82255872,'战华史略－大丈夫之义',replace(replace('此卡名的①③效果1回合仅可各使用1次。\r\n①：对手将怪兽特殊召唤的情况下可以发动。将1只“战华的龙兵衍生物”（兽战士族・风・星1・攻/守500）特殊召唤至自己场上。\r\n②：自己・对手的“战华”怪兽将被战斗破坏的情况下，作为代替可将此卡送至墓地。\r\n③：以场上的“战华”怪兽为对象的魔法・陷阱・怪兽的效果发动时，将墓地的此卡除外可以发动。将该发动无效。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82255873,'战华的龙兵衍生物','由「战华史略－大丈夫之义」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82257671,'坚盾固固＠伊格尼斯者','此卡名的①③效果1回合仅可各使用1次。①：以自己场上的1只电子界族效果怪兽为对象可以发动。将该怪兽的效果无效，从手牌将此卡特殊召唤。②：自己场上的电子界族怪兽1回合各仅1次，不会因效果被破坏。③：此卡从场上被送至墓地的情况下，以自己场上的1只表侧表示怪兽为对象可以发动。自己的该表侧表示怪兽直至对手回合结束时为止不受对手的效果影响。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82257940,'礼物交换','①：双方玩家各自从我方的牌组挑选１张卡牌并以里侧表示除外。在此回合的结束阶段，双方将各自对手玩家除外的该卡牌加入我方手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82260502,'鹰头狮身斯芬克斯','只要此卡以表侧表示存在于场上，对手不可选择里侧守备表示怪兽为攻击对象。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82263578,'战火的残渣','①：双方场上不存在其他卡的情况下，以自己墓地的１只水・风属性怪兽为对象可以发动。将该水・风属性怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82270047,'星际仙踪－光剑',replace(replace('仅可装备于念动力族的“星际仙踪”怪兽。\r\n“星际仙踪－光剑”的②效果１回合仅可使用１次。\r\n①：装备怪兽的攻击力・守备力上升５００，在１次战斗阶段中可最多攻击怪兽２次，攻击了守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。\r\n②：此卡从场上被送至墓地的情况下，支付８００LP可以发动。将墓地的此卡加入手牌。','\r',char(13)),'\n',char(10)),'墓地的此卡加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82286798,'怒刹帝利・阿刹特罗','此卡名的①②效果１回合仅可各使用１次。①：自己场上表侧表示的“怒刹帝利”超量怪兽因战斗・效果被破坏的情况下可以发动。从自己的手牌・牌组・场上挑选１只“维萨思・史塔弗罗斯特”除外，从额外牌组将１只“维刹思・阿斯特劳德”无视召唤条件特殊召唤。②：此卡被除外的情况下，以自己１只被除外的“维萨思・史塔弗罗斯特”为对象可以发动。将该怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82293134,'纹章兽 雄狮',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：此卡召唤的回合的结束阶段发动。将此卡破坏。\r\n②：此卡被送至墓地的情况下发动。从牌组将“纹章兽 雄狮”以外的1只“纹章兽”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'破坏','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82301904,'混沌帝龙 －终焉的使者－','此卡不可通常召唤。仅可在将自己墓地中光属性与暗属性怪兽各1只除外的情况下特殊召唤。发动此卡效果的回合，自己不可以发动其他效果。①：1回合1次，支付1000LP可以发动。将双方手牌・场上的卡全部送至墓地。然后，给对手数值相当于以此效果送至对手墓地的卡数量×300的伤害。','特殊召唤','送墓','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82308875,'编号7 幸运条纹',replace(replace('等级7怪兽×3\r\n①：去除此卡的1个超量素材可以发动。掷2次骰子。此卡的攻击力直至对手回合结束时为止，变为掷出的较大数字×700的数值。掷出的数字合计为7的情况下，进而从以下效果中挑选1个适用。\r\n●将场上的其他卡全部送至墓地。\r\n●从手牌或自己・对手墓地将1只怪兽特殊召唤至自己场上。\r\n●自己抽3张。然后，挑选自己的2张手牌舍弃。','\r',char(13)),'\n',char(10)),'投掷骰子','此卡以外的场上的卡全部送至墓地','从手牌或者墓地把1只怪兽特殊召唤','从牌组抽3张卡，那之后选2张手牌丢弃','','','','','','','','','','','','');
INSERT INTO texts VALUES(82315403,'电子永久龙',replace(replace('“电子龙”怪兽＋机械族怪兽×2\r\n①：只要自己墓地存在机械族融合怪兽，此卡不会因对手的效果被破坏，对手不可将此卡作为效果的对象。\r\n②：融合召唤的此卡因对手被送至墓地的情况下可以发动。从自己手牌・牌组・墓地将1只“电子龙”特殊召唤。\r\n③：将墓地的此卡除外可以发动。此回合中，自己场上的融合怪兽不会因对手的效果被破坏，对手不可将其作为效果的对象。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82315772,'纹章兽 野迩','①：自己场上存在2只以上“纹章兽”怪兽的情况下，此卡可从手牌特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82319644,'邪王特拉卡莱尔','①：此卡上级召唤成功的场合可发动。为使攻击力合计变成为了此卡的上级召唤而解放的怪兽的原本攻击力以下，挑选对手场上任意数量的表侧表示怪兽并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82321037,'真龙皇 渊渎圣子 统领',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己的主要阶段可以发动。将此卡以外的、自己手牌・场上（表侧表示）的、包含水属性怪兽在内的2只怪兽破坏，从手牌将此卡特殊召唤，破坏了2只水属性怪兽的情况下，可从对手场上・墓地将最多2张魔法・陷阱卡除外。\r\n②：此卡因效果被破坏的情况下可以发动。从牌组将水属性以外的1只幻龙族怪兽以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'是否选魔法·陷阱卡除外？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82323997,'绯暗红新星龙／爆裂',replace(replace('此卡不可通常召唤，仅可通过“爆裂模式”的效果特殊召唤。\r\n①：对手发动卡的效果时，将场上的此卡直至结束阶段为止除外可以发动。以自己墓地的协调数量为上限，将对手场上的卡除外。\r\n②：对手怪兽攻击宣言时，将场上的此卡直至结束阶段为止除外可以发动。将该攻击无效。然后，结束战斗阶段。\r\n③：此卡被破坏的情况下可以发动。从自己墓地将1只“绯暗红新星龙”特殊召唤。','\r',char(13)),'\n',char(10)),'除外','无效攻击','特殊召唤','直到结束阶段除外','','','','','','','','','','','','');
INSERT INTO texts VALUES(82324105,'对极限的冲动','可将２张手牌送入墓地并发动。特殊召唤２只“灵魂衍生物”（恶魔族、暗、星１、攻／守０）至我方场上。此衍生物不可进行以上级召唤以外的目的释放。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82324106,'灵魂衍生物','由“对极限的冲动”的效果特殊召唤而来。除上级召唤外，此衍生物不可用作祭品。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82324312,'格布林侦察部队','此卡直接攻击对手玩家成功的场合，可随机确认对手的１张手牌。确认的卡牌是魔法卡的场合，该卡送入墓地。此卡攻击的场合，在战斗阶段结束时变成守备表示。直至下次我方回合结束时，此卡不可变更表示形式。','确认手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82340056,'荣誉的祭品','当你的LP低于３０００，且对手宣布进行直接攻击时可以发动。使该怪兽的攻击无效化，并在你的战场特殊召唤２个“祭品石碑衍生物”（岩石族・地・１星・攻／守０），从卡组中将１张名为“地缚神”的卡片加入你的手牌。“祭品石碑衍生物”只能在用于上级召唤名为“地缚神”的怪兽时解放，且不能作为同步素材使用。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82340057,'祭品石碑衍生物','由“荣誉的祭品”的效果特殊召唤而来。除名称中带有“地缚神”的怪兽外，此衍生物不可用作其他上级召唤的祭品，也不可用作同步材料。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82344137,'原初之神 法拉',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：向对手出示手牌的此卡与手牌的1张魔法・陷阱卡可以发动。直至下个回合结束时为止，应对所出示的魔法・陷阱卡及其同名卡的效果的发动，双方不可发动效果。\r\n②：此卡因魔法・陷阱卡的效果从手牌・场上被送至墓地的情况下可以发动。将此卡特殊召唤。\r\n③：此卡从墓地特殊召唤的情况下可以发动。获得对手场上攻击力最高的1只怪兽的控制权。','\r',char(13)),'\n',char(10)),'出示','特殊召唤','得到控制权','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82344138,'原初之神 法拉',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：向对手出示手牌的此卡与手牌的1张魔法・陷阱卡可以发动。直至下个回合结束时为止，应对所出示的魔法・陷阱卡及其同名卡的效果的发动，双方不可发动效果。\r\n②：此卡因魔法・陷阱卡的效果从手牌・场上被送至墓地的情况下可以发动。将此卡特殊召唤。\r\n③：此卡从墓地特殊召唤的情况下可以发动。获得对手场上攻击力最高的1只怪兽的控制权。','\r',char(13)),'\n',char(10)),'出示','特殊召唤','得到控制权','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82359538,'纠罪巧－骄狮 Aizaβ.LEON',replace(replace('←0 【灵摆】 0→\r\n①：每当有怪兽反转，就在此卡上放1个纠罪计数物。\n②：在自己・对手的战斗阶段结束时，另一方自己的灵摆区域存在“纠罪巧”卡的情况下，以对手场上的1只攻击力低于此卡的怪兽为对象可以发动。将该怪兽破坏。\r\n【怪兽效果】\r\n①：向对手出示手牌的此卡可以发动（发动此效果的回合中，自己仅可以里侧守备表示特殊召唤怪兽）。从手牌将1只怪兽以里侧守备表示特殊召唤。\n②：对手连锁自己的效果的发动，来发动卡的效果时，将里侧表示的此卡改成表侧守备表示可以发动。将场上的最多3张卡放回手牌。\n③：只要反转的此卡存在于怪兽区域，每当对手通过自身的卡的效果将卡加入自身的手牌，每有1张就受到900伤害。','\r',char(13)),'\n',char(10)),'破坏','特殊召唤','回手','已反转过','','','','','','','','','','','','');
INSERT INTO texts VALUES(82361206,'灵灭独钴杵','装备怪兽给予对手生命战斗伤害时，最多可选择对手墓地的２只怪兽并从游戏中除外。','除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82361809,'恐惧爪・赖希哈忒','此卡名以①方法的特殊召唤１回合仅可进行１次，且②效果１回合仅可使用１次。①：此卡可从手牌特殊召唤至与自己场上“恐惧爪”怪兽相邻或同一纵列的、自己的主要怪兽区域。②：此卡召唤・特殊召唤成功的情况下可以发动。从牌组将１张“恐惧爪”魔法・陷阱卡加入手牌。场上存在３只以上守备表示怪兽的情况下，自己进而可从牌组抽１张。','','是否抽牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82370493,'捕食植物 无畏魔鬼树',replace(replace('“捕食植物”怪兽＋等级1怪兽\r\n此卡从额外牌组仅可通过融合召唤及以下方法特殊召唤。\r\n●解放自己场上的1只“捕食植物”怪兽和自己或对手场上1只放有捕食计数物的怪兽的情况下可以特殊召唤。\r\n此卡名的效果1回合仅可使用1次。\r\n①：在此卡特殊召唤的自己・对手回合的主要阶段，以放有捕食计数物的怪兽数量为上限，以场上的魔法・陷阱卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'破坏效果','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82377606,'正义盟军 无限制者','可解放此卡并发动。选择我方场上１只冠有“正义盟军”之名的怪兽，直至回合结束时，该攻击力变成原本攻击力的２倍。','原本攻击变换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82382815,'王者的看破',replace(replace('①：自己场上存在等级7以上的通常怪兽的情况下，可以发动以下效果。\r\n●发动魔法・陷阱卡时可以发动。将该发动无效并将其破坏。\r\n●自己或者是对手将召唤・反转召唤・特殊召唤怪兽之际可以发动。将其无效，并将该怪兽破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82385847,'恐龙摔跤手・潘克拉三角龙',replace(replace('此卡名以①方法的特殊召唤１回合仅可进行１次，且②效果１回合仅可使用１次。\r\n①：对手场上怪兽的数量多于自己场上怪兽的情况下，此卡可从手牌特殊召唤。\r\n②：在自己・对手回合中，解放自己场上的１只“恐龙摔跤手”怪兽，以对手场上的１张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82386016,'乌合的行进','我方场上有兽族・兽战士族・鸟兽族其中任意一种怪兽存在的场合，每有１个种族从牌组抽取１张卡牌。发动此卡的回合中，我方不可发动其他魔法・陷阱卡的效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82404868,'黑魔术的面纱','①：可支付１０００LP并发动。从我方手牌、墓地挑选１只魔法师族、暗属性怪兽并特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82419869,'超级运动员完美王牌',replace(replace('因“超级运动员完美王牌”①方法的特殊召唤１回合只可１次。\r\n①：此卡可将我方场上１只除“超级运动员完美王牌”以外的“超级运动员”怪兽返回至手牌，并从手牌特殊召唤。\r\n②：魔法、陷阱、怪兽效果在对手回合中发动１次时，可舍弃１张手牌并发动。使该发动无效并破坏。','\r',char(13)),'\n',char(10)),'无效并破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82422049,'对薰风的祈祷','选择我方墓地的２只冠有“薰风”之名的怪兽，将该２只加入牌组并洗牌。之后，选择我方墓地１只冠有“薰风”之名的怪兽并特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82428674,'人工脑溢出','此卡名的①②效果1回合仅可各使用1次。①：从自己的手牌・墓地及自己场上的表侧表示怪兽中，挑选任意数量的“电子龙”除外（同等级最多1只）。然后，从对手场上挑选除外数量的卡破坏。②：场上的此卡被效果破坏的情况下可以发动。从牌组将1张“电子”魔法・陷阱卡或“人工脑”魔法・陷阱卡加入手牌。','是否继续选择？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82432018,'凶暴化之假面','装备怪兽的攻击力上升１０００点，守备力下降１０００点。此卡的控制者每次在自己的准备阶段支付１０００点LP，或者破坏此卡而不支付１０００点LP。','是否要支付1000基本分？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82434071,'无限狱步兵',replace(replace('①：我方手牌是０张的场合，在我方抽牌阶段，可将墓地的此卡除外，并从以下效果选择１个发动来代替执行通常抽取。\r\n●从牌组挑选１张“无限狱”卡牌并放置于牌组的最上方。\r\n●从牌组挑选１张“炼狱”魔法、陷阱卡并盖牌至我方场上。','\r',char(13)),'\n',char(10)),'发动「无限狱兵卒」的效果代替抽牌','从牌组选1张「无限狱」卡在牌组最上面放置','从牌组选1张「炼狱」魔法·陷阱卡在自己场上放置','请选择要放置在牌组最上面的卡','','','','','','','','','','','','');
INSERT INTO texts VALUES(82452993,'孤高的格斗家','自己场上仅只有“格斗鼠 吱助”“僧侣斗士”“僧侣大师”中的任意１只怪兽的情况下，选择１只该怪兽可以发动。选择的自己的表侧表示怪兽不会被战斗破坏，也不会受到对手怪兽的效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82458280,'魔空洞魔像','１回合１次，可选择我方场上１只表侧表示怪兽并发动。直至回合结束时，被选择怪兽的攻击力减半，此回合可直接攻击对手玩家。发动此效果的回合，仅被选择怪兽可进行攻击。','直接攻击','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82460246,'伍世坏・佳乐里姆','此卡名的卡１回合仅可发动１张，此卡名的③效果１回合仅可使用１次。①：作为此卡发动时的效果处理，可从牌组将１只“玛那桃圆乡”怪兽或“维萨思・史塔弗罗斯特”加入手牌。②：自己场上的光属性怪兽的攻击力上升相当于自己的场上・墓地的协调数量×１００的数值。③：自己场上表侧表示的协调因战斗・效果被破坏的情况下，以该１只怪兽为对象可以发动。将该怪兽特殊召唤。','是否从牌组把怪兽加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82466274,'咒眼死徒 沙利叶',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：此卡召唤成功时可以发动。从牌组将“咒眼死徒 沙利叶”以外的１张“咒眼”卡加入手牌。\r\n②：此卡装备了“塞勒涅的咒眼”的情况下，以对手场上１只被特殊召唤的怪兽为对象可以发动。将该怪兽破坏。此效果在对手回合中也可以发动。\r\n③：发动过此卡的②效果的情况下，将在下一个准备阶段发动。挑选自己场上的１张卡破坏。','\r',char(13)),'\n',char(10)),'牌组检索','对手1只怪兽破坏','自己1张卡破坏','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82482194,'千年蝎子','此卡每次通过战斗破坏对手场上１只怪兽并将其送入墓地时，攻击力上升５００点。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82489470,'轩辕的相剑师','此卡名的②效果１回合仅可使用１次。①：怪兽的攻击宣言时可以发动。将此卡从手牌特殊召唤，将该攻击无效。自己场上存在需以“阿尔白斯之落胤”作为融合素材的融合怪兽的情况下，进而可将该攻击宣言的怪兽破坏。②：怪兽以表侧表示被除外的情况下，将场上・墓地的此卡除外可以发动。从自己的手牌・墓地挑选１只攻击力和守备力数值相同的魔法师族・光属性怪兽特殊召唤。','是否把攻击怪兽破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82496097,'时潜怪盗・表圈潜航艇','此卡名的①②效果1回合仅可各使用1次。①：解放此卡，以自己场上的1只“时潜怪盗”超量怪兽为对象可以发动。从对手墓地挑选1张卡，重叠在对象怪兽下方作为超量素材。此效果在对手回合中也可以发动。②：此卡存在于墓地的情况下，去除自己场上的1个超量素材可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡离开场上的情况下，将其除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82498947,'冰结界的守护阵','①：只要自己场上存在其他“冰结界”怪兽，攻击力在此卡的守备力以上的对手怪兽不可攻击宣言。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82529174,'希望之光','将我方墓地的２张光属性的怪兽卡加入我方牌组并洗牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82542267,'掘坟盗墓者','选择对手墓地中的１至２张怪兽卡。将所选择卡牌从游戏中除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82556058,'恶性马达・欧米伽',replace(replace('①：1回合1次，在自己的主要阶段可以发动。此卡的攻击力直至回合结束时为止上升1000。\r\n②：发动过此卡的①效果的情况下，在结束阶段发动。将此卡破坏。\r\n③：在自己的结束阶段发动。将1只“马达衍生物”（机械族・地・星1・攻/守200）以攻击表示特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'特殊召唤1只「马达衍生物」','攻击上升','「恶性马达・欧米伽」破坏','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82556059,'马达衍生物','由“恶鬼马达Ω”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82562802,'电子暗黑爪',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从手牌将此卡舍弃可以发动。从牌组将1张“电子黑暗”魔法・陷阱卡加入手牌。\r\n②：装备此卡的怪兽进行战斗的伤害计算时可以发动。从额外牌组将1只怪兽送至墓地。\r\n③：装备于怪兽的此卡被送至墓地的情况下，以自己墓地的1只“电子暗黑”怪兽为对象可以发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82566662,'饕餮龙',replace(replace('从额外卡组特殊召唤的怪兽２只以上\r\n①：此卡根据此卡连接素材的怪兽种类获得以下效果。\r\n●融合：战斗阶段中对手无法发动怪兽效果。\r\n●同步：我方主要阶段中对手无法发动魔法／陷阱卡的效果。\r\n●超量：我方主要阶段及战斗阶段中对手无法发动墓地中的卡片效果。','\r',char(13)),'\n',char(10)),'融合怪兽作为连接素材','同步怪兽作为连接素材','超量怪兽作为连接素材','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82570174,'灿幻升龙 双戟天龙',replace(replace('龙族协调＋协调以外的龙族怪兽１只以上\r\n此卡名的①效果１回合仅可使用１次，②效果在决斗中仅可使用１次。\r\n①：此卡同步召唤的情况下，以自己墓地的１只龙族・炎属性怪兽为对象可以发动。将该怪兽特殊召唤。此回合，自己仅可特殊召唤龙族怪兽。\r\n②：在攻击宣言过３次以上的自己・对手回合中可以发动。从墓地将此卡特殊召唤。然后，可将场上的１张魔法・陷阱卡破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','此卡从墓地特殊召唤','是否选场上1张魔法·陷阱卡破坏？','已经使用过「灿幻升龙 双戟天龙」的②的效果','','','','','','','','','','','','');
INSERT INTO texts VALUES(82579942,'光芒 玛多鲁','从游戏中被除外的我方光属性怪兽是３只或以上的场合，此卡可从手牌特殊召唤。此卡１回合仅限１次，不会因战斗而被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82593786,'骨猪一掷','怪兽进行战斗的战斗步骤时，可将墓地的此卡从游戏中除外并发动。使该怪兽的攻击无效。此效果也可在对手回合发动。决斗中“骨猪一掷”的效果只可使用１次。','攻击无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82616239,'超轻水合龙',replace(replace('此卡名在规则上视为“水合龙”。\r\n此卡名的效果1回合仅可使用1次。\r\n①：将场上的此卡除外可以发动。从牌组将3只等级5以下的水・风属性的恐龙族怪兽以守备表示特殊召唤。以此效果特殊召唤的怪兽的效果无效化。此效果发动后，直至回合结束时为止，自己从额外牌组仅可特殊召唤恐龙族・海龙族怪兽。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82627406,'奇异果魔导女孩',replace(replace('①：可将此卡从手牌舍弃并发动。直至回合结束时，我方场上“魔导女孩”怪兽的攻击力、守备力上升双方场上、墓地的“魔导女孩”怪兽种类×３００。此效果在对手回合也可发动。\r\n②：只要此卡存在于怪兽区，我方场上的魔法师族怪兽不会因效果被破坏，也不会成为对手效果的对象。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82633039,'鸟铳士卡斯戴尔',replace(replace('等级4怪兽×2\r\n此卡名的①②效果1回合1次，仅可使用其中1个。①：去除此卡的1个超量素材，以场上1只表侧表示怪兽为对象可以发动。将该怪兽改成里侧守备表示。②：去除此卡的2个超量素材，以场上此卡以外的1张表侧表示的卡为对象可以发动。将该卡放回持有者的牌组。','\r',char(13)),'\n',char(10)),'变成里侧守备表示','回到持有者牌组','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82633308,'念力聚能','可选择我方墓地的３只念动力族怪兽并发动。将该３只念动力族怪兽加入牌组并洗牌。之后，从我方牌组抽取２张卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82639107,'转换接触','①：自己场上不存在怪兽的情况下可以发动。从手牌及牌组各挑选１张“新空间人”卡送至墓地。然后自己从牌组抽２张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82642348,'残酷','此卡因战斗被破坏并送入墓地时，选择对手场上的１只怪兽并发动。掷１次硬币，猜正反面。若猜中的场合，破坏该怪兽。','投掷硬币','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82661461,'娱乐伙伴 异色眼仆从',replace(replace('←8 【灵摆】 8→\r\n①：１回合１次，对手怪兽攻击宣言时可以发动。该对手怪兽的攻击力下降相当于自己的额外牌组的表侧灵摆怪兽的数量×３００的数值。\r\n【怪兽效果】\r\n此卡名的①怪兽效果１回合仅可使用１次。\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将“娱乐伙伴 异色眼仆从”以外的１只“娱乐伙伴”怪兽或“异色眼”怪兽送至墓地。此卡的等级直至回合结束时为止，变为与送至墓地的怪兽的等级相同。\n②：怪兽区域的此卡被破坏的情况下可以发动。将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82661630,'登龙华恐巄门',replace(replace('①：“登龙华恐巄门”在自己场上仅可有１张以表侧表示存在。\r\n②：只要此卡存在于魔法与陷阱区域，自己场上的“龙华”怪兽的攻击力上升３００。\r\n③：自己场上的“龙华”灵摆怪兽，及等级１０以上且原本种族为恐龙族的怪兽获得以下效果。\r\n●１回合１次，攻击力低于此卡的场上的怪兽的效果发动时，将自己场上的１张表侧表示的“龙华”永续魔法卡放回牌组最下面可以发动。将该发动无效。','\r',char(13)),'\n',char(10)),'','发动无效（「登龙华恐巄门」）','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82670878,'血泪食人魔','对手回合的１次战斗阶段中，在第２次宣言直接攻击时，可从手牌特殊召唤此卡。以此效果特殊召唤成功时，此卡的攻击力、守备力数值变成此战斗阶段中第１次进行直接攻击的场上的怪兽数量。此回合，只要以此效果特殊召唤的此卡以表侧表示存在于场上，对手不可选择除此卡以外的怪兽为攻击对象。','特殊召唤','攻守变换','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82685480,'利维坦的愤怒',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：场上存在“海”的情况下，以自己场上的原本等级在5以上的水属性怪兽的数量为上限，以对手场上的怪兽为对象可以发动。将该怪兽破坏。直至下个回合结束时为止，以此效果所破坏的怪兽原先存在的区域不可使用。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82692552,'耀烂龙 珊栖泳龙',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：此卡以抽牌以外的方法加入手牌的情况下，将此卡和手牌的1只水属性怪兽出示给对手可以发动。将该2只特殊召唤。此效果发动后，直至回合结束时为止自己仅可特殊召唤水属性怪兽。\r\n②：只要自己场上存在“海”，对手不可将自己场上的水属性连接怪兽作为效果的对象。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82693042,'混沌球体','只要此卡以表侧表示存在于场上，被视为光属性。此卡１回合仅１次，不会因战斗而被破坏。此卡上级召唤成功时可发动。从牌组将１只等级３的怪兽加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82693917,'命运女郎・温蒂','此卡的攻击力、守备力变成此卡的等级×３００点。此外，我方准备阶段时，此卡的等级上升１级（最高至１２级）。此卡召唤成功时，可挑选对手场上的魔法、陷阱卡破坏，其数量相当于我方场上冠有“命运女郎”之名怪兽的数量。','等级上升','魔法·陷阱卡破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82697249,'编号59 背反的料理人',replace(replace('等级４怪兽×２\r\n①：自己场上的卡仅有此卡的情况下，此卡不受其他卡的效果影响。\r\n②：在每个自己・对手回合中１次，去除此卡的１个超量素材可以发动。将自己场上的其他卡全部破坏。然后，此卡的攻击力直至回合结束时为止，上升相当于以此效果被破坏并被送至墓地的怪兽数量×３００的数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82697428,'幻影－英雄 突袭魔女','以表侧表示上级召唤此卡的情况下，可解放自己场上的陷阱卡作为怪兽的代替。①：此卡召唤成功时可以发动。将对手场上的魔法・陷阱卡全部破坏。发动此效果的回合中，自己仅可特殊召唤“－英雄”怪兽。','解放陷阱卡上级召唤','对手场上的魔法·陷阱卡全部破坏','是否继续选择陷阱卡解放？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82699999,'直播☆双子 璃拉甜心',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：对手连锁自己的“直播☆双子”卡的效果发动来发动魔法・陷阱・怪兽的效果时，从手牌将此卡舍弃可以发动。将该对手的效果无效。\r\n②：此卡存在于墓地，且自己场上存在“姬丝吉尔”怪兽的情况下可以发动。将此卡特殊召唤。只要以此效果特殊召唤的此卡以表侧表示存在于怪兽区域，自己从额外牌组仅可特殊召唤恶魔族怪兽。','\r',char(13)),'\n',char(10)),'效果无效','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82705573,'逆火','①：每次自己场上的表侧表示的炎属性怪兽被破坏并被送至墓地都要发动。给对手500伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82706696,'GMX－伶盗种VELOX',replace(replace('“GMX”怪兽＋恐龙族怪兽\r\n此卡名的②效果1回合仅可使用1次。\r\n①：每当对手将怪兽召唤・特殊召唤，自己就恢复200LP。\r\n②：在对手回合中，以对手场上的1张卡为对象可以发动。适用以下所有效果。\r\n●从自己牌组上面翻开卡，直至翻到“GMX”怪兽或恐龙族怪兽为止，自己失去所翻开的数量×400的LP。将该怪兽加入手牌或特殊召唤。将剩余的放回牌组。\r\n●将对象卡破坏。','\r',char(13)),'\n',char(10)),'','破坏效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82732705,'技能抽取',replace(replace('支付１０００LP可以发动此卡。\r\n①：只要此卡存在于魔法与陷阱区域，场上所有表侧表示的怪兽的效果无效化。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82734805,'狱炎机・缇耶拉',replace(replace('“狱炎机・拿赫摩斯”＋“狱炎机・莉莉丝”＋“狱炎机”怪兽１只以上\r\n①：此卡融合召唤时可以发动。根据作为其融合素材的怪兽的种类，适用以下效果。\r\n●３种以上：双方各自从自身的额外牌组将３张卡送至墓地。\r\n●５种以上：双方各自从自身的牌组上面将３张卡送至墓地。\r\n●８种以上：双方各自将自身除外状态的最多３张卡放回墓地。\r\n●１０种以上：有手牌的玩家将其手牌全部送至墓地。','\r',char(13)),'\n',char(10)),'从额外牌组选3张卡送至墓地','从牌组上面把3张卡送至墓地','选除外的最多3张自己的卡回到墓地','手牌的卡全部送至墓地','','','','','','','','','','','','');
INSERT INTO texts VALUES(82735249,'总彩排','此卡名的②③效果１回合仅可各使用１次。①：只要此卡存在于魔法与陷阱区域，每次发动“音响战士”卡拥有的效果，在此卡上放１个音响计数物。②：去除自己场上的３个音响计数物可以发动。从牌组将１只“音响战士”怪兽加入手牌。③：自己召唤・特殊召唤“音响战士”怪兽成功的情况下可以发动。从牌组将１张“扩音器热焰”加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82738008,'赫之烙印',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：以自己墓地的1只“惨绝戏”怪兽或“阿尔白斯之落胤”为对象可以发动。将该怪兽加入手牌。然后，可适用以下效果。\r\n●将自己手牌・场上的怪兽作为融合素材除外，将1只等级8以上的融合怪兽融合召唤。以此效果特殊召唤的怪兽此回合不可直接攻击。','\r',char(13)),'\n',char(10)),'是否进行融合召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82738277,'兰花之虫惑魔',replace(replace('①：此卡召唤时可以发动。从牌组将１只“虫惑魔”怪兽加入手牌。\r\n②：此卡只要存在于怪兽区域，不受“空洞”通常陷阱卡及“落穴”通常陷阱卡的效果影响。\r\n③：在每个自己・对手回合中１次，以自己场上里侧表示的１张魔法・陷阱卡为对象可以发动。将该里侧表示卡放回手牌。然后，可从手牌放置１张魔法・陷阱卡。','\r',char(13)),'\n',char(10)),'牌组检索','回到手牌','是否把魔法·陷阱卡放置？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82742611,'恶鬼蛇','独眼蛇。吐出冷气，冰封对方。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82744076,'协调口香糖',replace(replace('“协调口香糖”的①效果１回合只可使用１次。\r\n①：可以我方场上１只表侧表示怪兽为对象发动。此回合，该表侧表示怪兽被视为协调。发动此效果的回合，我方只可使用同步怪兽进行攻击。\r\n②：仅以我方场地的１只同步怪兽为对象的魔法、陷阱、怪兽效果发动时，可将墓地的此卡除外并发动。使该发动无效。','\r',char(13)),'\n',char(10)),'当作协调使用','效果发动无效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82760689,'宝牌云','在发动回合中召唤、反转召唤、特殊召唤２只或以上冠有“云魔物”之名的同名怪兽的场合，结束阶段时从我方牌组抽取２张卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82768499,'螺旋之强袭爆裂',replace(replace('①：可从以下效果中选择１个发动。\r\n●自己场上有“异色眼”卡存在的情况下，以场上的１张卡为对象可以发动。将该卡破坏。\r\n●从牌组的怪兽及自己额外牌组的表侧表示灵摆怪兽中，将１只等级７“异色眼”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'卡片破坏','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82773292,'悦乐的堕天使',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从手牌・牌组挑选除“悦乐的堕天使”以外的、2只等级不同的“堕天使”怪兽，将其中1只以守备表示特殊召唤至对手场上，将另1只加入自己手牌。此效果发动后，直至回合结束时为止，自己不可发动天使族以外的怪兽的效果。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82777208,'冰翡之阿克蒂','此卡名的①②效果１回合仅可各使用１次。①：此卡召唤・特殊召唤成功的情况下，从手牌将１只水属性怪兽送至墓地可以发动。自己从牌组抽１张。②：此卡存在于墓地的状态下，自己场上表侧表示的水属性怪兽因战斗・效果被破坏的情况下，将此卡除外可以发动。从自己的手牌・墓地挑选“冰翡之阿克蒂”以外的１只“冰翡”怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82782870,'巳剑之尊 草那艺',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下，或此卡被解放的情况下，以“巳剑之尊 草那艺”以外的、自己墓地・除外状态的1张“巳剑”卡为对象可以发动。将该卡加入手牌。\r\n②：自己场上的其他爬虫类族怪兽将被战斗・效果破坏的情况下，作为代替可将此卡解放。','\r',char(13)),'\n',char(10)),'回收','代替破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82791472,'战华之叛－吕奉',replace(replace('此卡不可通常召唤。\r\n“战华之叛－吕奉”1回合1次，仅可在场上的“战华”怪兽中，攻击力最高的怪兽存在于自己场上的情况下特殊召唤。\r\n①：在每个双方的主要阶段1次，可以发动（发动此效果的回合中，自己不可发动“战华”怪兽以外的怪兽效果）。将对手场上攻击力最高的1只怪兽破坏。\r\n②：在结束阶段，场上攻击力最高的怪兽存在于对手场上的情况下发动。将此卡的控制权转移给对手。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82818645,'岩石的精灵','虽然外表如同陶俑，却是岩石精灵。攻击和守备都很强。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82821760,'巨大战舰 巨核Mk－Ⅲ',replace(replace('①：仅有对手场上才存在怪兽的情况下，此卡可从手牌中以守备表示特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下发动。在此卡上放3个计数物。\r\n③：此卡不会因战斗被破坏。\r\n④：此卡进行战斗的伤害步骤结束时发动。去除此卡的1个计数物。无法去除的情况下将此卡破坏。\r\n⑤：将墓地的此卡除外可以发动。将自己墓地的“巨大战舰”怪兽全部放回牌组。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82828051,'地震','将场上所有表侧表示的怪兽变为守备表示。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82832464,'奈芙蒂斯的觉醒',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：只要此卡存在于魔法与陷阱区域，自己场上的“奈芙蒂斯”怪兽的攻击力上升３００。\r\n②：魔法与陷阱区域表侧表示的此卡因效果被破坏并被送至墓地的情况下可以发动。从自己的手牌・牌组・墓地将１只“奈芙蒂斯”怪兽特殊召唤。以此效果特殊召唤的怪兽将在结束阶段被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82841979,'大和神','此卡不可通常召唤。只有将我方墓地中的１只灵魂怪兽从游戏中除外的场合才可特殊召唤此卡。特殊召唤此卡的回合的结束阶段时此卡回到持有者的手牌中。此卡通过战斗破坏对手怪兽的场合，可破坏对手场上的１张魔法卡或陷阱卡。','返回手牌','魔陷破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82878489,'闪光城堡',replace(replace('仅可装备于光属性怪兽。\r\n①：装备怪兽的攻击力上升700。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82886276,'电脑网回路','此卡名的①②效果１回合仅可各使用１次。①：以自己场上的１只“防火墙”连接怪兽为对象可以发动。从自己的墓地挑选任意数量的怪兽，特殊召唤至自己或对手场上，使其与对象怪兽呈连接状态。②：自己的LP为２０００以下的情况下，将墓地的此卡除外可以发动。从自己的墓地挑选１只“防火墙”连接怪兽放回额外牌组。然后，可将该怪兽从额外牌组特殊召唤。','','是否继续特殊召唤？','','是否把那只怪兽特殊召唤？','','','','','','','','','','','','');
INSERT INTO texts VALUES(82888408,'魔轰神兽刻耳柏拉尔','①：此卡从手牌被舍弃至墓地的情况下发动。将此卡特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82896870,'绒毛动物・海豚','此卡名的①②效果１回合仅可各使用１次。①：以自己墓地的１张“玩具罐”为对象可以发动。将该卡放置在自己场上，从牌组将１只“锋利小鬼・剪刀”或１只“绒毛动物”怪兽送至墓地。②：此卡作为融合召唤的素材被送至墓地的情况下可以发动。从自己墓地的卡及自己被除外的卡中，挑选１张“融合”魔法卡或“结合”魔法卡放回牌组。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82913020,'星圣 卡多克乌斯',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：自己场上存在“星圣 卡多克乌斯”以外的“星圣”怪兽的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：在自己的主要阶段可以发动。从牌组将1张“星圣”魔法・陷阱卡加入手牌。\r\n③：持有此卡作为超量素材的“星圣”超量怪兽获得以下效果。\r\n●此卡与光・暗属性怪兽进行战斗的伤害计算前可以发动。将该怪兽除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82933935,'迷拟宝箱鬼・食人花',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己的主要阶段可以发动。从手牌将此卡以里侧守备表示特殊召唤至对手场上。场上存在里侧表示怪兽的情况下，作为代替也可以表侧表示特殊召唤至自己场上。\r\n②：此卡在主要阶段反转的情况下发动。分别适用以下效果。\r\n●对手可从自身牌组将1只反转怪兽或1张“迷拟宝箱鬼”卡加入手牌。\r\n●将此卡的控制权转移给对手。','\r',char(13)),'\n',char(10)),'反转效果','特殊召唤','在自己场上特殊召唤','在对手场上特殊召唤','是否把卡加入手牌？','','','','','','','','','','','');
INSERT INTO texts VALUES(82944432,'机甲忍者 刃心',replace(replace('战士族等级4怪兽×2\r\n①：1回合1次，去除此卡的1个超量素材，以自己场上的1只“忍者”怪兽为对象可以发动。此回合，该怪兽在1次战斗阶段中可攻击2次。','\r',char(13)),'\n',char(10)),'2次攻击','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82946847,'小翼龙','①：此卡因效果被破坏并被送至墓地的情况下发动。从牌组将1只等级4以上的恐龙族怪兽特殊召唤。以此效果特殊召唤的怪兽在此回合不可攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82956214,'教导惩戒',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：以对手场上的1只表侧表示怪兽为对象可以发动。从额外牌组将1只攻击力在该怪兽攻击力以上的怪兽送至墓地，破坏对象怪兽。此卡发动后，直至下个自己回合结束时为止，自己不可从额外牌组特殊召唤怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82956492,'DDD 神讬王达尔克',replace(replace('“DD”怪兽×２\r\n①：只要此卡存在于怪兽区域，给予自己伤害的效果变为恢复自己LP的效果。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82962242,'吸血鬼妖女','①：１回合１次，此卡召唤成功时，或此卡以外的“吸血鬼”怪兽被召唤至自己场上时，以对手场上的１只攻击力高于此卡的怪兽为对象可以发动。将该怪兽视为装备卡装备于此卡。②：此卡的攻击力上升相当于以此卡的效果装备的怪兽原本攻击力的数值。③：以此卡的效果装备了装备卡的此卡被送至墓地的情况下发动。从墓地将此卡特殊召唤。','装备','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82970905,'公灰熊',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：此卡因战斗被破坏并被送至墓地时可以发动。从牌组将1只攻击力1400的等级4怪兽特殊召唤。自己墓地存在2只以上攻击力1400的等级4怪兽的情况下，作为代替也可将1只通常怪兽特殊召唤。\r\n②：自己场上存在效果怪兽以外的表侧表示怪兽，且对手发动怪兽的效果时，将墓地的此卡除外可以发动。将该发动无效并破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','发动无效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82971335,'命运女郎・厄希','此卡的攻击力、守备力变成此卡的等级×４００点。此外，我方准备阶段时，此卡的等级上升１级（最高至１２级）。此卡等级上升时，给予对手生命４００点伤害。','等级上升','伤害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82977464,'超元特防队 实验样本','此卡名的①②效果１回合１次，仅可使用其中１个。①：对手场上有怪兽存在的情况下，从自己墓地的怪兽及被除外的自己的怪兽中，以１只“超元特防队”怪兽为对象可以发动。将该怪兽特殊召唤至对手怪兽正面的自己场上。②：将墓地的此卡除外，以自己场上的１只“超元特防队”怪兽为对象可以发动。将自己的该怪兽的位置移动至自己的其他主要怪兽区域。','','','请选择要移动位置的怪兽','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82983267,'皮尔莉穿越！？','此卡名的卡１回合仅可发动１张。①：以自己场上的１只“皮尔莉”超量怪兽为对象可以发动。将阶级与该自己的怪兽不同的１只“皮尔莉”超量怪兽，重叠在对象怪兽上面，视为超量召唤从额外牌组特殊召唤。以此效果特殊召唤的怪兽将在下个回合的结束阶段放回持有者的额外牌组。②：将墓地的此卡除外，以自己墓地的最多３只“皮尔莉”怪兽为对象可以发动。将该怪兽放回牌组。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82994509,'笔头菜','此卡因战斗被破坏并送入墓地时，以守备表示特殊召唤１只“笔头菜衍生物”（植物族、风、星１、攻／守０）至对手场上。此衍生物因与植物族怪兽的战斗被破坏的场合，此衍生物的控制者将１张手牌送入墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82994510,'笔头菜衍生物','由“笔头菜”的效果特殊召唤而来。如果此衍生物在与植物族怪兽战斗时被破坏，控制者要将１张手牌送入墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82997779,'恶魔的篡夺',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：可从以下效果中选择1个发动。\r\n●从自己牌组・墓地将1张“恶魔”陷阱卡放置在自己场上。以此效果放置的卡在放置的回合也可以发动。\r\n●为使合计等级达到仪式召唤的怪兽的等级以上，解放自己手牌・场上的怪兽，从自己手牌・额外牌组（表侧）将1只“恶魔”仪式怪兽仪式召唤。','\r',char(13)),'\n',char(10)),'放置','仪式召唤','适用「恶魔的篡夺」的效果来发动','','','','','','','','','','','','','');
INSERT INTO texts VALUES(82999629,'水世界','场上的水属性怪兽的攻击力上升５００点，守备力下降４００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83008724,'军贯推荐捏','①：１回合１次，将手牌的１只“舍利军贯”出示给对手可以发动。在此卡上放１个计数物，向对手出示额外牌组的１只“军贯”超量怪兽，对手宣言１个卡名记载于“军贯”超量怪兽的、“舍利军贯”以外的“军贯”怪兽的卡名。自己从牌组将对手所宣言的卡加入手牌。无法加入的情况下，将此卡放回持有者的牌组。②：此卡因对手被破坏的情况下发动。对手支付放于此卡上的计数物数量×５００的LP。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83011277,'杀手番茄','①：此卡因战斗被破坏且送至墓地时可以发动。从牌组将1只攻击力1500以下的暗属性怪兽以攻击表示特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83011278,'杀手番茄','①：此卡因战斗被破坏且送至墓地时可以发动。从牌组将1只攻击力1500以下的暗属性怪兽以攻击表示特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83021423,'急匆匆射手','１回合１次，可选择场上的１张魔法、陷阱卡并发动。破坏被选择的卡牌。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83027236,'破坏之光','卡牌因对手效果从对手牌组被送入墓地时，将对手牌组最上方的３张卡牌送入墓地。','牌组送墓','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83032858,'元素军刀 阿依娜',replace(replace('①：１回合１次，可从手牌将１只“元素军刀”怪兽送入墓地，并以我方墓地１只除“元素军刀・阿依娜”以外的“元素军刀”怪兽或“灵神”怪兽为对象发动。无视召唤条件特殊召唤该怪兽。\r\n②：此卡存在于墓地的场合，１回合１次，可宣言１个属性并发动。直至回合结束时，墓地的此卡变成宣言之属性。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83035296,'莫吉斯特里仪术师',replace(replace('此卡牌名的②效果１回合只可使用１次。\r\n①：只要此卡存在于怪兽区，每次我方或对手发动魔法卡，放置１个魔力计数物在此卡。\r\n②：在我方、对手的结束阶段，可移除此卡的３个魔力计数物，并以我方被除外的１张魔法卡为对象发动。从牌组将１张该卡牌的同名卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83039608,'魔轰神兽阿凡可',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：此卡存在于墓地的情况下可以发动。从手牌挑选1只“魔轰神”怪兽舍弃，将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83039729,'六武众之师范',replace(replace('①：“六武众之师范”在自己场上仅可有1张以表侧表示存在。\r\n②：自己场上存在“六武众”怪兽的情况下，此卡可从手牌特殊召唤。\r\n③：此卡因对手的效果被破坏的情况下，以自己墓地的1只“六武众”怪兽为对象发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'墓地回收','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83048208,'电子光虫－LED瓢虫',replace(replace('以此卡作为超量召唤之素材的场合，只可使用于昆虫族怪兽的超量召唤。\r\n①：１回合１次，表侧攻击表示的此卡变成守备表示时，可发动。从牌组将１只昆虫族、等级３怪兽加入手牌。\r\n②：以场上的此卡作为素材超量召唤而来的怪兽获得以下效果。\r\n●此卡因战斗破坏怪兽时，我方从牌组抽取１张卡牌。','\r',char(13)),'\n',char(10)),'牌组检索','「电子光虫－LED瓢虫」效果适用中','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83054225,'紧急起飞','对手场上的怪兽数量比我方场上除衍生物以外的怪兽数量多的场合，可释放我方场上任意数量的“幻兽机衍生物”并发动。从牌组特殊召唤冠有“幻兽机”之名的怪兽，其数量仅为被释放衍生物的数量。以此效果特殊召唤的怪兽，在结束阶段时返回至持有者牌组。“紧急起飞”１回合只可发动１张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83061014,'后来被称为龟的神','只要此卡以表侧表示存在于场上，双方都不可特殊召唤攻击力１８００或以下的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83094004,'有氧妖精Ξ',replace(replace('①：１回合１次，以与此卡同一纵列的对手的１只表侧表示怪兽为对象可以发动。将自己场上的此卡的位置移动至自己的其他主要怪兽区域，将对象的对手怪兽的位置移动至此卡正面的对手的主要怪兽区域。然后，在该对手怪兽上放１个燃烧计数物。此效果在对手回合中也可以发动。\r\n②：只要此卡存在于怪兽区域，放有燃烧计数物的怪兽的攻击力・守备力下降相当于其数量×２００的数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83102080,'平行龙卷','①：可将我方场上除此卡以外的１张魔法・陷阱卡送入墓地，以场上的１张卡牌为对象发动此卡。破坏该卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83104731,'古代机械齿轮巨人',replace(replace('此卡不可特殊召唤。\r\n①：此卡攻击的情况下，对手直至伤害步骤结束时为止，不可发动魔法・陷阱卡。\r\n②：此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83107873,'鸟雷龙','此卡名的①②效果1回合1次，仅可使用其中1个。①：将此卡从手牌中舍弃可以发动。从自己墓地的怪兽及被除外的自己的怪兽中，挑选“鸟雷龙”以外的1只“雷龙”怪兽特殊召唤。②：此卡被除外的情况下或从场上被送至墓地的情况下可以发动。将自己任意数量的手牌放回牌组洗牌。然后自己从牌组抽放回牌组数量的牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83108603,'阳炎柱','只要此卡存在于场上，我方可减少１只召唤冠有“阳炎兽”之名怪兽的场合所必要释放的怪兽。此外，１回合１次，可选择我方场上的１只超量怪兽并发动。将我方手牌、场上的１只冠有“阳炎兽”之名的怪兽重叠至被选择的超量怪兽的下方当作超量素材。','增加素材','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83116692,'死眼之传灵－普绪科蓬波斯',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡特殊召唤成功的情况下发动。适用对手墓地的以下卡中张数多的效果。\r\n●怪兽卡：将此卡除外，对手从自身墓地挑选１只怪兽除外。\r\n●魔法・陷阱卡：将此卡送至墓地，对手挑选自身场上的１只怪兽送至墓地。\r\n②：此卡被除外的情况下，在下个回合的结束阶段可以发动。将被除外的此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83121692,'元素－英雄 暴风侠',replace(replace('“元素－英雄 羽毛人”＋“元素－英雄 闪光人”＋“元素－英雄 泡沫人”\r\n此怪兽仅可以融合召唤特殊召唤。可将我方场上除此卡以外的１张卡牌送入墓地，并选择我方场上以表侧表示存在的１只怪兽发动。只要此卡以表侧表示存在于场上，被选择的怪兽就不会因战斗而被破坏。','\r',char(13)),'\n',char(10)),'破坏耐性','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83133491,'重力解除','变更场上全部表侧表示怪兽的表示形式。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83135907,'废铁格布林','①：此卡不会因战斗被破坏。②：表侧守备表示的此卡在被选择为攻击对象的情况下，在战斗阶段结束时发动。将此卡破坏。③：此卡因“废铁”卡的效果被破坏并被送至墓地的情况下，以自己墓地的１只“废铁格布林”以外的“废铁”怪兽为对象可以发动。将该怪兽加入手牌。','此卡破坏','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83152482,'同盟运输车',replace(replace('种族或属性相同的怪兽2只\r\n此卡名的效果1回合仅可使用1次。此卡被连接召唤的回合不可作为连接素材。①：以自己场上的1只表侧表示怪兽为对象可以发动。从手牌・牌组挑选1只原本种族或原本属性与对象怪兽相同的怪兽，视为攻击力上升1000的装备卡装备于对象怪兽。以此效果从牌组装备的情况下，直至回合结束时为止，自己不可特殊召唤该装备的怪兽卡及该怪兽的同名怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83190280,'月光虎',replace(replace('←5 【灵摆】 5→\r\n①：1回合1次，以自己墓地的1只“月光”怪兽为对象可以发动。将该怪兽特殊召唤。以此效果特殊召唤的怪兽不可攻击，效果无效化，将在结束阶段被破坏。\r\n【怪兽效果】\r\n此卡名的怪兽效果1回合仅可使用1次。\n①：场上的此卡因战斗・效果被破坏的情况下，以自己墓地的1只“月光”怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83195035,'龙岚归还','此卡名的卡1回合仅可发动1张。①：以1只自己或对手被除外的怪兽为对象可以发动。将该怪兽特殊召唤至自己场上。以此效果特殊召唤的怪兽于结束阶段放回持有者的手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83199011,'守宝团・警报！','此卡名的①②效果１回合仅可各使用１次。①：以自己墓地的１只“守宝团”怪兽或“阿尔白斯之落胤”为对象可以发动。将该怪兽特殊召唤。②：从自己的墓地将此卡和１只融合怪兽除外，以自己场上的１只“守宝团”超量怪兽为对象可以发动。从额外牌组挑选１只以“阿尔白斯之落胤”作为融合素材的融合怪兽，重叠在对象怪兽下方作为超量素材。此效果在此卡被送至墓地的回合不可发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83203672,'守宝团・庞哥','此卡名的①②效果１回合仅可各使用１次。①：此卡存在于手牌・场上・墓地的情况下，以自己场上的１只“守宝团”超量怪兽为对象可以发动。将此卡重叠在该怪兽下方作为超量素材。②：从自己的墓地将“守宝团・庞哥”以外的１只“守宝团”怪兽和此卡除外可以发动。从牌组将１张“守宝团”卡加入手牌。','补充超量素材','牌组检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83225447,'兴奋剂','装备怪兽的攻击力上升７００点。此外，每次我方的准备阶段，装备怪兽的攻击力下降２００点。','攻击下降','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83228073,'针二千枚','攻击了守备表示的此卡的对手怪兽的攻击力低于此卡守备力的场合，在伤害步骤结束时破坏该攻击怪兽。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83232904,'小丑戏帮《极艺》',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从牌组・额外牌组将最多2只“小丑戏帮”怪兽无视召唤条件特殊召唤。此卡发动后，直至下个回合结束时为止，自己不可发动被从牌组・额外牌组特殊召唤的怪兽的效果。\r\n②：在自己的主要阶段，从墓地将不是在此回合被送至墓地的此卡除外，解放自己手牌・场上的1只怪兽，以场上的1张卡为对象可以发动。将该卡放回手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','回到手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83235263,'无限暴龙','①：此卡原本的攻击力变为相当于自己被除外的恐龙族怪兽数量×１０００的数值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83236601,'急袭猛禽－献祭伯劳','此卡名的①②效果1回合仅可各使用1次。①：在此卡召唤・特殊召唤成功的回合的自己的主要阶段可以发动。从牌组将1张“急袭猛禽”卡送至墓地。②：在此卡战斗破坏了对手怪兽的回合的自己主要阶段2可以发动。从牌组将1张“升阶魔法”速攻魔法卡加入手牌。此效果发动后，直至回合结束时为止自己仅可特殊召唤“急袭猛禽”怪兽。','送至墓地','牌组检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83239739,'牡蛎大王','①：此卡被以战斗以外的方法从场上被送至墓地的情况下发动。将１只“牡蛎衍生物”（鱼族・水・星１・攻／守０）特殊召唤至自己场上。','特殊召唤衍生物','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83239740,'牡蛎衍生物','由“牡蛎王”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83241722,'反转骰子','①：此回合，适用掷骰子效果时，仅可重掷１次骰子。','是否要重掷1次骰子？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83257450,'幻之召唤神 艾克佐迪亚',replace(replace('“被封印”怪兽×５\r\n①：场上的此卡不会因对手的效果被破坏。\r\n②：１回合１次，此卡进行战斗的伤害计算时可以发动。此卡的攻击力上升相当于自己的LP的数值。\r\n③：１回合１次，魔法・陷阱卡的效果发动时可以发动。将该发动无效。\r\n④：在自己・对手的结束阶段可以发动。从牌组将１张“艾格佐德”魔法・陷阱卡放置在自己场上。\r\n⑤：在自己的准备阶段发动。自己失去１０００LP。','\r',char(13)),'\n',char(10)),'上升攻击力','效果无效','放置魔陷','失去基本分','','','','','','','','','','','','');
INSERT INTO texts VALUES(83258273,'拦路贼僵尸','每次我方场上的怪兽给予对手玩家战斗伤害，对手将牌组最上面的１张卡牌送入墓地。','牌组送墓','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83266006,'逢华妖丽谭－魔妖语',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：在自己・对手的主要阶段，以自己场上的１只不死族同步怪兽为对象可以发动。将属性和该怪兽相同的、自己墓地・除外状态的１只不死族怪兽特殊召唤。以此效果特殊召唤的怪兽将在结束阶段被除外。此卡发动后，直至回合结束时为止自己仅可特殊召唤不死族怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83266092,'超古代生物的墓场','只要此卡存在于场上，场上等级６以上的被特殊召唤的怪兽不可攻击宣言，不可发动效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83269557,'暗黑女武神',replace(replace('此卡存在于墓地或以表侧表示存在于场上的场合，将被视为通常怪兽。以通常召唤的方式再次召唤场上表侧表示的此卡，此卡将视为效果怪兽并获得以下效果。\r\n●只要此卡以表侧表示存在，可有１次机会在此卡上放置１个魔力计数物。此卡的攻击力上升放置在此卡上的魔力计数物数量×３００点。此外，可取除放置在此卡上的１个魔力计数物，选择场上的１只怪兽并将其破坏。','\r',char(13)),'\n',char(10)),'放置魔力计数物','场上一只怪物破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83272895,'劈啪劈啪蜜蜂',replace(replace('①：以场上的此卡作为素材超量召唤的怪兽获得以下效果。\r\n●此卡攻击守备表示怪兽的场合，若攻击力超过该守备力，给予相当于该数值的战斗伤害。','\r',char(13)),'\n',char(10)),'「劈啪劈啪蜜蜂」效果适用中','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83274244,'怒怒怒战士','①：此卡无需解放即可召唤。以此卡的①方法召唤的此卡原本的攻击力变为１８００。②：此卡攻击的情况下，直至伤害步骤结束时为止，在对手墓地发动的效果无效化。','不用解放召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83283063,'战神－不知火',replace(replace('不死族协调＋１只以上协调以外的不死族怪兽\r\n自己１回合仅可特殊召唤１次“战神－不知火”。①：此卡特殊召唤成功的情况下，从自己的墓地将１只不死族怪兽除外可以发动。此卡的攻击力直至回合结束时为止，上升相当于所除外的怪兽原本攻击力的数值。②：场上的此卡因战斗・效果被破坏并被送至墓地的情况下，以１只自己被除外的守备力０的不死族怪兽为对象可以发动。将该怪兽放回墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83286340,'战吼・伏蒂亚',replace(replace('此卡牌名的①②效果１回合只可各使用１次。\r\n①：我方战士族、地属性怪兽进行了战斗的伤害计算后可发动。从牌组将１张除“战吼・伏蒂亚”以外的“战吼”卡牌加入手牌。之后，直至对手回合结束时，我方场上所有“战吼”怪兽的攻击力上升２００。\r\n②：此卡因对手效果从怪兽区被送入墓地的场合可发动。从手牌、牌组特殊召唤１只等级５或以上的“战吼”怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83289866,'魔女工艺・窄巷',replace(replace('此卡名的②③效果1回合1次，仅可使用其中1个。\r\n①：自己场上的“魔女工艺”怪兽1回合各仅1次，不会因战斗・效果被破坏。\r\n②：为发动自己场上的“魔女工艺”怪兽的效果而要将手牌舍弃的情况下，作为代替可将场上的此卡送至墓地。\r\n③：在自己的结束阶段，此卡存在于墓地，且自己场上存在“魔女工艺”怪兽的情况下可以发动。将此卡以表侧表示放在自己的魔法与陷阱区域。','\r',char(13)),'\n',char(10)),'返回场上','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83293307,'机怪虫・神经受体','此卡名的①②效果1回合仅可各使用1次。①：此卡反转的情况下可以发动。从牌组将1只“机怪虫”怪兽加入手牌。②：表侧表示的此卡因对手的效果从场上离开的情况下可以发动。将2只“机怪虫・神经受体”以外的“机怪虫”怪兽从牌组以里侧守备表示特殊召唤（同名卡最多1张）。','牌组检索','2只怪兽特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83293635,'七皇觉醒','①：在战斗阶段，怪兽因战斗・效果被破坏的情况下，以自己墓地的１只“编号”超量怪兽为对象可以发动。从额外牌组将种族与该怪兽相同、阶级高１的１只“混沌编号”怪兽特殊召唤，将对象怪兽作为其超量素材。以此效果特殊召唤了“混沌编号101”～“混沌编号107”怪兽中的任一的情况下，进而可从牌组将除“七皇觉醒”之外的“七皇”魔法・陷阱卡、“巴利安之”魔法・陷阱卡、“升阶魔法”速攻魔法卡中的任意１张加入手牌。','','是否从牌组把卡加入手牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83295594,'蒸汽同步士','①：在对手的主要阶段可以发动。将包括此卡在内的自己场上的怪兽作为同步素材同步召唤。','同步召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83301414,'魔女工艺・怠工',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：以自己墓地的1只“魔女工艺”怪兽为对象可以发动。将该怪兽特殊召唤。\r\n②：在自己的结束阶段，此卡存在于墓地，且自己场上存在“魔女工艺”怪兽的情况下可以发动。将此卡加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83303851,'DDD 极智王混沌默示录',replace(replace('←4 【灵摆】 4→\r\n①：将自己墓地的２只“DD”怪兽除外可以发动。将灵摆区域的此卡特殊召唤。\r\n【怪兽效果】\r\n此卡名的怪兽效果１回合仅可使用１次，仅可在对手回合发动。①：此卡存在于手牌・墓地的情况下，以自己场上的２张表侧表示魔法・陷阱卡为对象可以发动。将该卡破坏，将此卡特殊召唤。此效果发动后，直至回合结束时为止自己仅可特殊召唤恶魔族怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83308376,'赫圣之相剑','此卡名的①②效果１回合仅可各使用１次。①：自己场上存在同步怪兽的情况下，以自己或对手的场上・墓地的１张卡为对象可以发动。将该卡除外。②：对手场上存在仪式・融合・同步・超量・连接怪兽中的任一的情况下，从自己的墓地将１只同步怪兽除外可以发动。将墓地的此卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83315222,'燃烧拳斗士 推广人',replace(replace('此卡名的①②③效果１回合仅可各使用１次，发动此效果的回合中，自己仅可特殊召唤“燃烧拳斗士”怪兽。\r\n①：对手场上存在怪兽的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：解放此卡可以发动。从牌组将“燃烧拳斗士 推广人”以外的最多２只“燃烧拳斗士”怪兽特殊召唤（同名卡最多１张）。\r\n③：将墓地的此卡除外可以发动。自己场上的“燃烧拳斗士”怪兽的等级全部上升１或全部下降１。','\r',char(13)),'\n',char(10)),'','','','等级上升','等级下降','','','','','','','','','','','');
INSERT INTO texts VALUES(83319154,'溯时的穿光',replace(replace('①：对手发动非在此回合被召唤・反转召唤・特殊召唤的、场上的怪兽的效果时可以发动。将该发动无效。然后，可将非在此回合被召唤・反转召唤・特殊召唤的、对手场上的表侧表示怪兽全部以里侧除外。\r\n②：被放置的此卡因对手的效果被破坏的情况下可以发动。从牌组将1张陷阱卡放置在自己场上。','\r',char(13)),'\n',char(10)),'发动','放置','是否把怪兽除外？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83319610,'机芯拧紧',replace(replace('此卡的①②效果不可在同一连锁上发动。\r\n①：１回合１次，以自己场上的１只机械族超量怪兽为对象可以发动。从自己的手牌・场上挑选１只“发条”怪兽，重叠在对象怪兽下面作为超量素材。\r\n②：将魔法与陷阱区域表侧表示的此卡送至墓地，以自己场上的１只“发条”超量怪兽为对象可以发动。将１只阶级比该自己的怪兽高１的“发条”超量怪兽重叠在其上，视为超量召唤从额外牌组特殊召唤。','\r',char(13)),'\n',char(10)),'把「发条」怪兽作为超量素材','把高1阶的「发条」怪兽特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83326048,'次元障壁',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：宣言１个怪兽的种类（仪式・融合・同步・超量・灵摆）可以发动。在此回合中适用以下效果。\r\n●双方不可特殊召唤所宣言种类的怪兽，场上所宣言种类的怪兽的效果无效化。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83334932,'超重武者 摩托－Q','此卡名的①效果１回合仅可使用１次。①：自己墓地不存在魔法・陷阱卡的情况下，从手牌将此卡舍弃可以发动。从牌组将１只“超重武者 摩托－Q”以外的“超重武者”怪兽加入手牌。②：１回合１次，以自己场上的１只机械族怪兽为对象可以发动。该怪兽的等级上升２。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83340560,'伟大的双咒术师',replace(replace('效果怪兽以外的怪兽×２\r\n此卡名的③效果１回合仅可使用１次。\r\n①：此卡的攻击力上升相当于作为此卡融合素材的仪式・融合・同步・超量・连接怪兽原本攻击力的合计数值。\r\n②：此卡可直接攻击。\r\n③：此卡因战斗・效果被破坏的情况下，以效果怪兽以外的、自己墓地・除外状态的１只怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83347294,'异色眼枪兵龙',replace(replace('①：如果我方场上的灵摆怪兽因战斗或效果被破坏，则可以解放１只我方场上的怪兽以发动。将此卡从手牌中特殊召唤。\r\n②：如果这张卡攻击，则对手在伤害步骤结束前不能发动魔法和陷阱卡。\r\n③：如果我方场上的“异色眼”卡因战斗或效果被破坏，则可以改为破坏１张我方手牌、怪兽区或灵摆区的１张“异色眼”卡片。','\r',char(13)),'\n',char(10)),'此卡从手牌特殊召唤','是否使用「异色眼枪兵龙」的效果代替破坏？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83370323,'陷阱颠倒者','将此卡作为同步素材的场合，只可使用于战士族怪兽的同步召唤。将此卡作为同步素材的同步怪兽攻击的场合，对手直至伤害步骤结束时不可发动陷阱卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83392426,'二轮车人','此卡因战斗被破坏并送入墓地时，可从手牌、牌组特殊召唤１只“单轮车人”。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83404468,'一色万骨',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：根据自己墓地的通常怪兽的种类适用以下效果。\r\n●1种以上：此回合中，自己场上的通常怪兽的攻击力上升800。\r\n●2种以上：将场上的1只效果怪兽的效果直至回合结束时为止无效。\r\n●3种以上：此回合中，自己场上的通常怪兽不会因效果被破坏。\r\n●4种以上：将场上的1只效果怪兽放回牌组。\r\n●5种以上：从牌组将1张“一色万骨”加入手牌。','\r',char(13)),'\n',char(10)),'发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83407038,'亚马逊的急袭',replace(replace('①：１回合１次，在我方、对手的战斗阶段可发动。从手牌特殊召唤１只“亚马逊”怪兽。直至回合结束时，以此效果特殊召唤的怪兽的攻击力上升５００。\r\n②：在我方的“亚马逊”怪兽与对手怪兽进行战斗的伤害计算后可发动。将该对手怪兽除外。\r\n③：场上的此卡被破坏并送入墓地的场合，可以我方墓地的１只“亚马逊”怪兽为对象发动。特殊召唤该怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83414006,'幻影－英雄 投毒者','此卡名的①②③效果１回合仅可各使用１次。①：自己因战斗・效果受到伤害的情况下可以发动。将墓地的此卡视为永续陷阱卡，以表侧表示放在自己的魔法与陷阱区域。②：此卡视为永续陷阱卡的情况下，在双方的主要阶段，解放自己场上的１只“－英雄”怪兽可以发动。将此卡特殊召唤。③：从魔法与陷阱区域将此卡特殊召唤成功的情况下可以发动。挑选１只场上的怪兽，将其攻击力改成一半。','此卡当作永续陷阱卡放置','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83438826,'圣剑阿隆戴特','仅限装备战士族怪兽。１回合１次，可下降装备怪兽攻击力５００点，并选择被盖牌于对手场上的１张卡牌破坏。场上以表侧表示存在的此卡被破坏并送入墓地的场合，可选择我方场上１只冠有“圣骑士”之名的战士族怪兽装备此卡。“圣剑阿隆戴特”的此效果１回合只可使用１次。此外，我方场上只可有１张“圣剑阿隆戴特”以表侧表示存在。','魔陷破坏','装备','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83443619,'水晶机巧－烟晶虎',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：以自己场上的1张表侧表示卡为对象可以发动。将该卡破坏，从牌组将1只“水晶机巧”协调特殊召唤。此效果发动后，直至回合结束时为止自己从额外牌组仅可特殊召唤机械族同步怪兽。\r\n②：将墓地的此卡除外可以发动。从牌组将1张“水晶机巧”魔法・陷阱卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83445539,'暗冥共鸣者',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：向对手出示额外牌组的1只“暗红恶魔龙”可以发动。从手牌将此卡特殊召唤。此回合，自己从额外牌组仅可特殊召唤同步怪兽。\r\n②：此卡特殊召唤的情况下可以发动。此回合，自己在通常召唤之外，可在自己的主要阶段追加1次召唤1只“共鸣者”怪兽。\r\n③：以自己场上任意数量的协调为对象可以发动。将该怪兽的等级改成1。','\r',char(13)),'\n',char(10)),'特殊召唤','追加召唤','改变等级','使用「暗冥共鸣者」的效果召唤','','','','','','','','','','','','');
INSERT INTO texts VALUES(83446909,'充电池人','此卡召唤成功时，可从手牌、牌组特殊召唤１只除“充电池人”以外的冠有“电池人”之名的怪兽。此卡的攻击力、守备力上升我方场上雷族怪兽数量×３００点。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83461421,'灵摆风暴','①：将双方灵摆区域的卡全部破坏。然后，可挑选对手场上的１张魔法・陷阱卡破坏。','是否选对手场上1张魔法·陷阱卡破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83464209,'催眠羊','长尾巴羊。利用尾巴施加催眠术，诱使睡魔出动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83467607,'自然反射','此回合，因对手发动效果而发生的给予我方的效果伤害，将由对手代替承受。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83477829,'星遗物－星铠－','此卡名的①②③效果1回合仅可各使用1次。①：怪兽反转召唤成功时可以发动。从手牌将此卡特殊召唤。②：此卡召唤・特殊召唤成功的情况下可以发动。从牌组将1张“星遗物”卡加入手牌。③：通常召唤的此卡存在的情况下，以1只从额外牌组特殊召唤的、对手场上的表侧表示怪兽为对象可以发动。将该怪兽和此卡放回持有者的手牌。此效果在对手回合中也可以发动。','此卡从手牌特殊召唤','牌组检索','回到手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83488497,'恐惧爪・雷电阿斯特拉','此卡名以①方法的特殊召唤１回合仅可进行１次。①：此卡可从手牌特殊召唤至与自己场上“恐惧爪”怪兽相邻或同一纵列的、自己的主要怪兽区域。②：只要自己场上存在守备表示的“恐惧爪”怪兽，根据其种类的数量，额外怪兽区域的自己的“恐惧爪”怪兽在１次战斗阶段中最多可作出同次数的攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83500096,'A次代机・涌刃','①：１回合１次，将自己场上１只表侧表示的水属性“次代机”怪兽送至墓地可以发动。自己抽２张。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83512285,'超级银河','此卡名的卡１回合仅可发动１张。①：解放自己场上“银河眼光子龙”以外的１只攻击力２０００以上的怪兽，以对手场上１只攻击力２０００以上的怪兽为对象可以发动。解放该怪兽，从自己的手牌・牌组・墓地挑选１只“银河眼光子龙”特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83518674,'未界域之欧戈波戈','此卡名的②效果1回合仅可使用1次。①：向对手出示手牌中的此卡可以发动。对手从自己的所有手牌中随机挑选1张，自己舍弃该卡。该卡为“未界域之欧戈波戈”以外的情况下，进而从手牌将1只“未界域之欧戈波戈”特殊召唤，自己从牌组抽1张。②：此卡从手牌被舍弃的情况下可以发动。从牌组将“未界域之欧戈波戈”以外的1张“未界域”卡送至墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83519853,'魔圣骑士皇兰斯洛特',replace(replace('协调＋协调以外的“圣骑士”怪兽１只或以上\r\n①：仅可有１只“魔圣骑士皇兰斯洛特”以表侧表示存在于我方场上。\r\n②：此卡同步召唤成功时可发动。从牌组挑选１张“圣剑”装备魔法卡装备在此卡。\r\n③：此卡在因战斗破坏怪兽并将其送入墓地的战斗阶段结束时可发动。从牌组将１张“圣骑士”卡牌或“圣剑”卡牌加入手牌。','\r',char(13)),'\n',char(10)),'装备','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83528184,'GMX准教授 诺玛',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡以怪兽的效果特殊召唤的情况下，以自己及对手墓地的卡各1张为对象可以发动。将该卡分别放回牌组最上面或最下面。\r\n②：此卡存在于怪兽区域的状态下，有怪兽被召唤・特殊召唤至对手场上的情况下可以发动。将自己场上・墓地・除外状态的怪兽作为融合素材放回牌组，将1只“GMX”融合怪兽融合召唤。','\r',char(13)),'\n',char(10)),'回到牌组','融合召唤','返回牌组最上面','返回牌组最下面','','','','','','','','','','','','');
INSERT INTO texts VALUES(83531441,'彼岸旅人 但丁',replace(replace('等级3怪兽×2\r\n①：1回合1次，去除此卡的1个超量素材，从自己的牌组上面将最多3张卡送至墓地可以发动。此卡的攻击力直至回合结束时为止，上升相当于为发动此效果而被送至墓地的卡的数量×500的数值。②：此卡攻击过的情况下，战斗阶段结束时变为守备表示。③：此卡被送至墓地的情况下，以此卡以外的1张自己墓地的“彼岸”卡为对象可以发动。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'攻守变换','卡片回收','请选择要送至墓地的卡的数量','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83533296,'转生炎兽之炎军',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：可从以下效果中选择１个发动。\r\n●以自己的墓地・除外状态的３只炎属性怪兽为对象可以发动。将该３只中的２只放回牌组，将剩余的１只特殊召唤。以此效果特殊召唤的怪兽在此回合，效果无效化且不可攻击。\r\n●攻击力不同于原本攻击力的炎属性仪式・融合・同步・超量・连接怪兽存在于自己场上的情况下，以场上的１张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'回收除外的怪兽','场上卡破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83544697,'薰风之通讯','可选择我方墓地的２只冠有“薰风”之名的怪兽和对手场上的１张卡牌并发动。将被选择的２只墓地怪兽加入牌组并洗牌。之后，破坏被选择的１张对手卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83546647,'无抵抗的真相','我方因对手怪兽的直接攻击受到战斗伤害时，可向对手展示１只手牌的等级１怪兽并发动。特殊召唤１只向对手展示的怪兽和１只牌组的同名怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83550869,'暮光道斗犬 莱可',replace(replace('①：此卡召唤・反转的情况下，从自己的手牌・墓地将１只“光道”怪兽除外可以发动。将场上的１张卡除外。\r\n②：１回合１次，自己其他的“光道”怪兽的效果发动的情况下发动。从自己的牌组上面将３张卡送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83554231,'转生炎兽之再起','此卡名的①②效果1回合仅可各使用1次。①：以自己墓地卡名不同的2只“转生炎兽”怪兽为对象可以发动。将该怪兽加入手牌。②：被放置的此卡被效果破坏、送至墓地的情况下可以发动。从牌组将“转生炎兽之再起”以外的1张“转生炎兽”魔法・陷阱卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83555666,'破坏轮','此卡名的卡1回合仅可发动1张。①：在对手回合中，可以对手场上的1只表侧表示的、拥有对手LP数值以下攻击力的怪兽为对象发动。破坏该表侧表示怪兽，自己受到相当于该怪兽原本攻击力数值的伤害。然后，给对手与自己所受伤害相同数值的伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83555667,'破坏轮','此卡名的卡1回合仅可发动1张。①：在对手回合中，可以对手场上的1只表侧表示的、拥有对手LP数值以下攻击力的怪兽为对象发动。破坏该表侧表示怪兽，自己受到相当于该怪兽原本攻击力数值的伤害。然后，给对手与自己所受伤害相同数值的伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83558891,'恐惧爪・新星','此卡名的②效果１回合仅可使用１次。①：以自己墓地的１只“恐惧爪”怪兽或“维萨思・史塔弗罗斯特”为对象可以发动。以守备表示形式将该怪兽特殊召唤。②：自己场上的“恐惧爪”连接怪兽将被战斗・效果破坏的情况下，作为代替可将墓地的此卡除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83566725,'魅影骑士团末日护胫',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次，且②③效果1回合仅可各使用1次。\r\n①：自己场上不存在怪兽的情况下，此卡可从手牌特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从牌组将1张“魅影骑士团”魔法・陷阱卡放置在自己场上。\r\n③：将墓地的此卡除外，以自己场上的最多2只等级3・阶级3的暗属性怪兽为对象可以发动。该怪兽的等级・阶级上升1。','\r',char(13)),'\n',char(10)),'特殊召唤','放置魔陷','上升等级·阶级','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83575471,'高等宝玉兽 红玉兽',replace(replace('此卡名的③效果１回合仅可使用１次。\r\n①：场地区域不存在“高等暗黑”的情况下，此怪兽将被送至墓地。\r\n②：表侧表示的此卡在怪兽区域被破坏的情况下，可不送至墓地，而是视为永续魔法卡以表侧表示放在自己的魔法与陷阱区域。\r\n③：此卡视为永续魔法卡的情况下可以发动。将此卡特殊召唤。然后，可将自己的魔法与陷阱区域的“高等宝玉兽”怪兽卡尽可能多地特殊召唤。','\r',char(13)),'\n',char(10)),'是否尽可能特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83584898,'魔界的脚镣',replace(replace('①：装备怪兽不可进行攻击，攻击力・守备力变为１００。\r\n②：自己的准备阶段时发动。给予装备怪兽的控制者５００点伤害。','\r',char(13)),'\n',char(10)),'500伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83589191,'生命骇入',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：以场上的1只表侧表示怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止变为与对手的LP相同的数值，此回合，对手受到的所有伤害变为一半。\r\n②：在自己的主要阶段将墓地的此卡除外，以场上的1只表侧表示怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止变为与自己的LP相同的数值，此回合，对手受到的所有伤害变为一半。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83602069,'并肩战斗的陆星剑士','只要此卡以表侧表示存在于场上，我方场上的战士族怪兽攻击力上升４００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83604828,'云魔物－幽灵雾','此卡不可特殊召唤。因此卡的战斗对双方玩家造成的战斗伤害变为０。此卡因战斗被破坏的场合，放置雾计数物于场上的表侧表示怪兽，其数量相当于破坏此卡的怪兽的等级数量。','放置计数物','请选择要放置「雾计数物」的卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83610035,'兽带斗士“百合”玻莱雅','此卡名的①②效果１回合仅可各使用１次。①：以自己墓地的１只“兽带斗士”怪兽或植物族怪兽为对象可以发动。从手牌将此卡特殊召唤，将对象怪兽视为装备卡装备于此卡。②：从自己的手牌・场上将１张卡送至墓地可以发动。从牌组将１张“兽带斗士”魔法・陷阱卡加入手牌。③：装备此卡的“兽带斗士”怪兽的攻击力上升７００，获得此卡名的②效果。','','牌组检索（兽带斗士“百合”胃宿二）','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83626916,'异次元邮箱',replace(replace('此卡名的③效果1回合仅可使用1次。\r\n①：自己场上的怪兽的攻击力上升自己除外状态的卡的种类（怪兽・魔法・陷阱）×300的数值。\r\n②：1回合1次，在自己・对手的主要阶段可以发动。从自己手牌・墓地将1张卡除外。然后，可将自己除外状态的1张卡放回牌组。\r\n③：此卡被除外的情况下可以发动。将此卡以表侧表示放在自己场上。','\r',char(13)),'\n',char(10)),'','除外','表侧表示放置','是否让卡回到牌组？','','','','','','','','','','','','');
INSERT INTO texts VALUES(83629030,'卡通电子龙',replace(replace('①：仅有对手场上才存在怪兽的情况下，此卡可从手牌特殊召唤。\r\n②：此卡在召唤・反转召唤・特殊召唤的回合不可攻击。\r\n③：自己场上存在“卡通世界”，且对手场上不存在卡通怪兽的情况下，此卡可直接攻击。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83656563,'中生代化石机械 骷髅运输车',replace(replace('自己墓地的岩石族怪兽＋等级５・６的怪兽\r\n此卡仅可通过“化石融合”的效果从额外牌组中特殊召唤。\r\n此卡名的③效果１回合仅可使用１次。\r\n①：此卡在１次的战斗阶段中最多可对怪兽进行２次攻击。\r\n②：此卡战斗破坏对手怪兽时可以发动。给予对手８００点伤害。\r\n③：将墓地的此卡除外，并以场上１张魔法・陷阱卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83670388,'冰翡咒缚','此卡名的②效果１回合仅可使用１次。①：只要场上存在“冰翡”怪兽及“冰翡底 伊尼恩摇篮”，对手不可发动在此回合被召唤・反转召唤・特殊召唤的场上怪兽的效果。②：怪兽因自己的“冰翡”怪兽的战斗被破坏时，以该１只被破坏的怪兽为对象可以发动。给予对手该怪兽的原本攻击力数值的伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83675475,'衍生物谢肉祭','衍生物被特殊召唤时可以发动。破坏场上的所有衍生物，给予对手LP破坏衍生物的数量×３００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83678433,'午夜魔鬼','现身于深夜的鸟怪物。据说必须要献上活祭品才能将它唤出。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83682209,'海灵贼',replace(replace('此卡牌名的效果１回合只可使用１次。\r\n①：此卡存在于墓地的状态下，除“海灵贼”以外的我方场上的表侧表示之水属性怪兽因战斗、效果被破坏的场合可发动。特殊召唤此卡。直至下一个回合结束时，以此效果特殊召唤而来的此卡的攻击力，上升相当于我方墓地的水属性怪兽数量×１００。以此效果特殊召唤的此卡从场上离开的场合被除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83682725,'摆尾攻击','选择我方场上１只表侧表示的等级５以上的恐龙族怪兽来发动此卡。令对手场上合计最多２只里侧表示的怪兽或等级低于所选择的恐龙族怪兽的怪兽回到持有者的手牌中。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83705073,'女战神・爱尔达',replace(replace('①：只可有１只“女战神・爱尔达”以表侧表示存在于我方场上。\r\n②：只要以“女战神”卡牌之效果特殊召唤而来的此卡存在于怪兽区，对手场上怪兽的攻击力下降１０００。\r\n③：只要此卡存在于怪兽区，因战斗、效果被破坏并被送入对手墓地的卡牌不前往墓地而直接被除外。','\r',char(13)),'\n',char(10)),'「女武斗神」卡的效果特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83711531,'真红眼钢爪龙',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：将自己场上的1张里侧表示卡送至墓地可以发动。从手牌将此卡特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下，如果自己场上或墓地存在“钢铁化・强化反射装甲”则可以发动。从自己牌组・墓地将1张“钢铁化”陷阱卡加入手牌。\r\n③：只要此卡存在于怪兽区域，自己可以在“钢铁化”陷阱卡放置的回合就将其发动。','\r',char(13)),'\n',char(10)),'特殊召唤','加入手牌','适用「真红眼钢爪龙」的效果来发动','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83715234,'削月刀','１回合１次，我方场上的岩石族怪兽的表示形式被变更时可发动。选择对手场上的１张魔法、陷阱卡破坏。','魔陷破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83723605,'海晶少女环流',replace(replace('自己场上存在连接３以上的“海晶少女”怪兽的情况下，此卡也可从手牌发动。\r\n①：以自己场上的１只水属性连接怪兽为对象可以发动。将该怪兽放回额外牌组，从额外牌组将卡名与该怪兽不同、连接标记数量相同的１只“海晶少女”连接怪兽视为连接召唤来特殊召唤。此回合，以此效果特殊召唤的怪兽不可直接攻击，不会因战斗被破坏。','\r',char(13)),'\n',char(10)),'适用「海晶少女环流」的效果来发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83725008,'光道祭司 洁妮丝','因冠有“光道”之名卡牌的效果而将卡牌从我方牌组送入墓地回合的结束阶段时，给予对手生命５００点伤害，我方回复５００LP。','伤害，回复','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83743222,'女神的圣弓－阿尔提米斯',replace(replace('仅限以“海尔摩斯之爪”的效果将我方手牌、场上的战士族怪兽送入墓地的场合，此卡可特殊召唤。\r\n①：此卡特殊召唤成功的场合，以场上除此卡以外的１只怪兽为对象发动。此卡被视为装备卡装备该怪兽。\r\n②：以此卡效果装备此卡的场合，在我方、对手的战斗阶段中仅１次，使对手发动的魔法、陷阱、怪兽效果无效。适用此效果的战斗阶段中，装备怪兽可攻击２次。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83746708,'魔导师之力','①：装备怪兽的攻击力・守备力上升相当于自己场上魔法・陷阱卡张数×500的数值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83747250,'黄昏的交衣',replace(replace('①：可以我方场上的１只表侧表示怪兽为对象发动。挑选我方墓地任意数量的“光道”怪兽并除外，直至回合结束时，对象怪兽的攻击力、守备力上升以此效果被除外的怪兽数量×２００。\r\n②：此卡因“光道”怪兽的效果从牌组被送入墓地的场合可发动。此回合，我方场上的“光道”怪兽不会因战斗、效果被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83755611,'辉龙星－蚣蝮',replace(replace('协调＋1只以上协调以外的幻龙族怪兽\r\n①：此卡同步召唤成功时，以场上的卡为对象可以发动，数量最多为作为此卡的同步素材的幻龙族怪兽的原本属性的种类数量。将该卡放回持有者的牌组。②：1回合1次，以自己场上1张卡和自己墓地1只等级4以下的怪兽为对象可以发动。将该场上的卡破坏，将该墓地的怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'回到牌组','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83764718,'死者苏生','①：以自己或对手墓地的1只怪兽为对象可以发动。将该怪兽特殊召唤至自己场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83764719,'死者苏生','①：以自己或对手墓地的1只怪兽为对象可以发动。将该怪兽特殊召唤至自己场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83764720,'死者苏生','①：以自己或对手墓地的1只怪兽为对象可以发动。将该怪兽特殊召唤至自己场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83764721,'死者苏生','①：以自己或对手墓地的1只怪兽为对象可以发动。将该怪兽特殊召唤至自己场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83764722,'死者苏生','①：以自己或对手墓地的1只怪兽为对象可以发动。将该怪兽特殊召唤至自己场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83764996,'魔导绅士－J','穿着奇特，性格反复无常，既会干坏事也会帮助人。对“美”相当执着。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83778600,'错误苏醒','可选择对手墓地的１只怪兽并发动。以守备表示特殊召唤被选择怪兽至对手场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83793721,'幻奏华歌神 绚烂舞星',replace(replace('“幻奏音姬”怪兽＋“幻奏”怪兽×２\r\n此卡名的①效果１回合仅可使用１次。\r\n①：在自己・对手回合可以发动。将自己场上任意数量的“幻奏”怪兽直至结束阶段为止除外。然后，可将对手场上表侧表示的卡放回手牌，数量最多为以此效果除外的怪兽数量。\r\n②：融合召唤的、表侧表示的此卡因对手从场上离开的情况下可以发动。从牌组・额外牌组将“幻奏华歌神 绚烂舞星”以外的１只“幻奏”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'是否回到手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83810690,'X－军刀 韦恩',replace(replace('协调＋协调以外的怪兽1只以上\r\n①：此卡同步召唤时可以发动。从手牌将1只等级4以下的战士族怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83812099,'燧发式战斗机','１回合１次，可选择场上的１张“火石”并发动。将被选择之“火石”装备于此卡。此外，可选择１张此卡所装备的“火石”和场上的１只表侧表示怪兽并发动。将选择之“火石”装备于被选择怪兽。此卡可装备的“火石”最多１张。只要此卡装备有“火石”，此卡不会受到“火石”的效果影响，也不会因战斗被破坏。','装备给此卡','装备转移','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83819309,'冷却之火',replace(replace('①：自己或对手的LP恢复的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：１回合１次，此卡存在于怪兽区域的状态下，自己或对手的LP恢复的情况下可以发动。自己或对手恢复１０００LP。','\r',char(13)),'\n',char(10)),'','是否让对手回复基本分？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83827392,'爱克斯皮尔莉・黑夜',replace(replace('等级７怪兽×２\r\n此卡也可重叠在拥有５个以上超量素材的、自己的阶级２怪兽上面来超量召唤。①：拥有５个以上的超量素材的此卡不受对手所发动效果的影响。②：去除此卡的２个超量素材，以对手场上・墓地的１张卡为对象可以发动。将该卡放回持有者的牌组最下面。此卡持有等级１的“皮尔莉”怪兽作为超量素材的情况下，此效果在对手回合中也可以发动。','\r',char(13)),'\n',char(10)),'是否在持有超量素材5个以上的自己的2阶怪兽上面重叠来超量召唤？','对方卡回到牌组','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83828288,'撒豆','①：以对手场上的１只表侧表示怪兽为对象可以发动。依该怪兽等级的数值，挑选自己的手牌舍弃，依舍弃的数量，自己从牌组抽牌。然后，将对象怪兽放回持有者的手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83831356,'机偶大爆走','可选择场上的１只冠有“机偶”之名的怪兽并发动。直至回合结束时，被选择怪兽的攻击力上升１０００点，且效果被无效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83838727,'抽牌面包',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：自己墓地存在怪兽的情况下，支付200LP可以发动。自己抽1张，给双方确认。其为怪兽的情况下，进而根据其属性适用以下效果。\r\n●自己墓地中不存在的属性：自己抽1张。\r\n●自己墓地中存在的属性：挑选自己的1张手牌舍弃。','\r',char(13)),'\n',char(10)),'发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83866861,'魔玩具・疯狂客迈拉',replace(replace('“魔玩具”怪兽×３\r\n此卡只可以融合召唤特殊召唤。\r\n“魔玩具・疯狂客迈拉”的②效果１回合只可使用１次。\r\n①：此卡进行战斗的场合，直至伤害步骤结束时，对手不可发动魔法、陷阱、怪兽的效果。\r\n②：此卡因战斗破坏对手怪兽并将其送入墓地时可发动。该怪兽的攻击力减半，并特殊召唤至我方场上。\r\n③：此卡的攻击力上升相当于我方场上原本持有者为对手之怪兽的数量×３００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83880087,'月神护盾',replace(replace('①：怪兽的攻击变成无效时，可从以下效果选择１个发动。\r\n●变成此回合的结束阶段。\r\n●可以我方场上的１只“希望皇霍普”超量怪兽为对象发动。直至回合结束时，该怪兽的攻击力变成原本攻击力的两倍。\r\n②：我方场上的“希望皇霍普”超量怪兽移除１个超量素材并发动效果的场合，可将墓地的此卡除外代替移除超量素材。','\r',char(13)),'\n',char(10)),'变成这个回合的结束阶段','攻击力变成2倍','使用「月神护盾」的效果代替取除素材','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83880473,'战吼・精神',replace(replace('此卡牌名的卡牌１回合只可发动１张。\r\n①：在我方、对手的战斗阶段，可以我方墓地的１只“战吼”怪兽为对象，并从以下效果选择１个发动。\r\n●以攻击表示特殊召唤对象怪兽。以此效果特殊召唤之怪兽，在此回合效果被无效化，且不可进行直接攻击。\r\n●以守备表示特殊召唤对象怪兽。此回合，我方的“战吼”怪兽仅各１次不会因战斗被破坏。','\r',char(13)),'\n',char(10)),'攻击表示特殊召唤','守备表示特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83887306,'夹击','选择存在于自己场上的２只怪兽和存在于对方场上的１只怪兽破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83888009,'七皇再生','①：将自己场上的超量怪兽全部解放，以自己除外状态的１只超量怪兽为对象可以发动。将该怪兽特殊召唤。然后，可将自己墓地・除外状态的“编号101”～“编号107”中的任意“编号”超量怪兽作为该特殊召唤的怪兽的超量素材，数量最多为所解放怪兽数量＋１只。在发动了此卡的回合的结束阶段，双方受到相当于各自自身手牌数量×３００的伤害。','是否重叠超量素材？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83903521,'法老化身','①：此卡作为同步素材被送至墓地的情况下，以自己墓地１只等级４以下的不死族怪兽为对象可以发动。将该不死族怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83928661,'未界域捕缚作战','仅可装备于“未界域”怪兽。①：装备怪兽的攻击力・守备力上升800，不会因效果被破坏。②：装备怪兽在1次战斗阶段中最多可攻击怪兽2次。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83957459,'半犀牛人','１次的战斗阶段中，因我方怪兽以的战斗破坏对手怪兽２只或以上的场合，此卡在该战斗阶段中可攻击２次。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83962752,'同步恐慌',replace(replace('此卡在发动后，将在自己的第３次准备阶段被破坏。\r\n \r\n①：自己场上表侧表示的同步怪兽因战斗或对手的效果被破坏的情况下，以其中１只为对象可以发动此卡。为使合计等级与该怪兽相等，从自己墓地将１只协调和任意数量协调以外的怪兽特殊召唤。以此效果特殊召唤的怪兽此回合不会因战斗・效果被破坏。 \r\n②：只要此卡存在于魔法与陷阱区域，双方不可同步召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','「同步恐慌」的效果特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83965310,'命运－英雄 血魔-D',replace(replace('此卡不可通常召唤。\r\n仅可在解放自己场上3只怪兽的情况下特殊召唤。\r\n①：只要此卡存在于怪兽区域，对手场上的表侧表示怪兽的效果无效化。\r\n②：1回合1次，以对手场上的1只怪兽为对象可以发动。将该对手怪兽视为装备魔法卡装备于此卡（仅可装备1只）。\r\n③：此卡的攻击力上升以此卡效果装备的怪兽原本攻击力一半的数值。','\r',char(13)),'\n',char(10)),'把自己场上3只怪兽解放特殊召唤','把对手怪兽给此卡装备','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83965311,'命运－英雄 血魔-D',replace(replace('此卡不可通常召唤。\r\n仅可在解放自己场上3只怪兽的情况下特殊召唤。\r\n①：只要此卡存在于怪兽区域，对手场上的表侧表示怪兽的效果无效化。\r\n②：1回合1次，以对手场上的1只怪兽为对象可以发动。将该对手怪兽视为装备魔法卡装备于此卡（仅可装备1只）。\r\n③：此卡的攻击力上升以此卡效果装备的怪兽原本攻击力一半的数值。','\r',char(13)),'\n',char(10)),'把自己场上3只怪兽解放特殊召唤','把对手怪兽给此卡装备','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83968380,'强欲之瓶','①：自己从牌组抽１张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83980492,'铜锣龙',replace(replace('←7 【灵摆】 7→\r\n【怪兽效果】\r\n采用最先进的技术而得以实现飞行的战斗用铜锣。以０.７马赫的速度翱翔于天际，任谁见了都会惊愕不已。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83982270,'云魔物－毒云','此卡在战斗中被破坏并送往墓地时，将破坏此卡的怪兽破坏，并给予对手LP８００点伤害。','破坏并伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83986578,'王虎','①：此卡存在于怪兽区域的状态下，每次攻击力１４００以下的怪兽被召唤・特殊召唤则发动。此卡以表侧表示存在于场上的情况下，将该攻击力１４００以下的怪兽破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83991690,'天福猪','可将墓地的此卡从游戏中除外，并选择我方场上的１只等级４或以下的天使族、光属性怪兽发动。只要被选择怪兽以表侧表示存在于场上，就被视为协调。','当成协调使用','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83994433,'闪珖龙 星尘',replace(replace('协调+1只以上协调以外的怪兽\r\n①：1回合1次，可以自己场上的表侧表示的1张卡为对象发动。该卡在此回合中仅1次不会因战斗・效果被破坏。此效果在对手回合中也可以发动。','\r',char(13)),'\n',char(10)),'破坏耐性','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(83994646,'死之四星瓢虫','反转：破坏对手场上所有表侧表示的等级４怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84012625,'流星音速',replace(replace('①：可以我方场上的１只“星尘”同步怪兽为对象发动。此回合，该我方同步怪兽与对手怪兽进行战斗的场合，在伤害步骤开始时将该对手怪兽返回至持有者牌组。\r\n②：我方场上的“星尘”同步怪兽以发动效果为目的解放自身的场合，可将墓地的此卡除外作为代替。','\r',char(13)),'\n',char(10)),'请选择要解放或代替解放除外的卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84013237,'编号39 希望皇霍普',replace(replace('等级4怪兽×2\r\n①：自己或对手的怪兽攻击宣言时，去除此卡的1个超量素材可以发动。将该攻击无效。\r\n②：此卡在没有超量素材的状态下被选择为攻击对象的情况下发动。将此卡破坏。','\r',char(13)),'\n',char(10)),'攻击无效','自坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84013238,'编号39 希望皇霍普',replace(replace('等级4怪兽×2\r\n①：自己或对手的怪兽攻击宣言时，去除此卡的1个超量素材可以发动。将该攻击无效。\r\n②：此卡在没有超量素材的状态下被选择为攻击对象的情况下发动。将此卡破坏。','\r',char(13)),'\n',char(10)),'攻击无效','自坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84013239,'编号39 希望皇霍普',replace(replace('等级4怪兽×2\r\n①：自己或对手的怪兽攻击宣言时，去除此卡的1个超量素材可以发动。将该攻击无效。\r\n②：此卡在没有超量素材的状态下被选择为攻击对象的情况下发动。将此卡破坏。','\r',char(13)),'\n',char(10)),'攻击无效','自坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84013240,'编号39 希望皇霍普',replace(replace('等级4怪兽×2\r\n①：自己或对手的怪兽攻击宣言时，去除此卡的1个超量素材可以发动。将该攻击无效。\r\n②：此卡在没有超量素材的状态下被选择为攻击对象的情况下发动。将此卡破坏。','\r',char(13)),'\n',char(10)),'攻击无效','自坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84025439,'超级量子机神王 超凡惊天煌',replace(replace('等级12怪兽×3\r\n①：根据此卡的超量素材的种类获得以下效果。\r\n●2种以上：1回合1次，在自己・对手的主要阶段，去除此卡的1个超量素材可以发动。将场上的1张卡放回牌组。\r\n●4种以上：此卡不受“超级量子”卡以外的卡的效果影响。\r\n●6种以上：对手不可以卡的效果从牌组将卡加入手牌。\r\n②：此卡被送至墓地的情况下可以发动。从自己墓地将3只“超级量子机兽”超量怪兽特殊召唤（同名卡最多1张）。','\r',char(13)),'\n',char(10)),'回到牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84031359,'堕天使 骨尔加尔塔',replace(replace('自己1回合仅可特殊召唤1次“堕天使 骨尔加尔塔”，其②效果1回合仅可使用1次。\r\n①：此卡特殊召唤的情况下可以发动。将2只“堕天使衍生物”（天使族・暗・星6・攻/守0）特殊召唤至自己场上。此效果发动后，直至回合结束时为止自己仅可特殊召唤天使族怪兽。\r\n②：此卡被送至墓地的情况下可以发动。从牌组将“堕天使 骨尔加尔塔”以外的1张“堕天使”卡或“禁忌的”速攻魔法卡加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84031360,'堕天使衍生物','由“堕天使 骨尔加尔塔”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84031736,'小丑戏帮《终演》',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：自己场上存在上级召唤的怪兽的情况下，舍弃任意数量的手牌，依其数量以场上的表侧表示卡为对象可以发动。将该卡破坏。\r\n②：将墓地的此卡除外，解放自己手牌・场上的1只仪式・融合・同步・超量・灵摆・连接怪兽可以发动。从自己牌组・墓地将1只与该怪兽原本等级・阶级・连接数值不同的“小丑戏帮”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'破坏效果','检索效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84040113,'泥泥龙',replace(replace('协调+1只以上协调以外的怪兽\r\n此卡名的②效果1回合仅可使用1次。①：此卡可以代替1只融合怪兽卡上记载有卡名的融合素材怪兽。在此之际，其他融合素材怪兽必须为正规素材。②：此卡是被同步召唤的情况下，在自己的主要阶段可以发动。将由融合怪兽卡决定的、包括此卡的融合素材怪兽从自己场上送至墓地，从额外牌组将1只该融合怪兽融合召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84046493,'鬼牛肉',replace(replace('←4 【灵摆】 4→\r\n①：１回合１次，在自己的主要阶段可以发动。掷１次骰子。直至回合结束时为止，此卡的灵摆刻度上升所掷出的数字（最多上升至１０）。\r\n【怪兽效果】\r\n钟情美食的牛幽灵。尤其对最爱吃的烤牛肉毫无抵抗力，今天也在为邂逅新口味而心驰神往，彷徨于现世。','\r',char(13)),'\n',char(10)),'灵摆刻度上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84054556,'终刻反转《A.D.R.A.S.T.E.I.A.》',replace(replace('此卡名的②③效果1回合仅可各使用1次。\r\n①：装备怪兽1回合仅1次，不会因战斗被破坏。\r\n②：在自己的主要阶段可以发动。破坏装备怪兽，将所破坏怪兽以外的、自己手牌・墓地・除外状态的1只“终刻”怪兽以守备表示特殊召唤。\r\n③：此卡存在于墓地的情况下，以自己场上的1只表侧表示怪兽为对象可以发动。将此卡装备于该怪兽。然后，自己受到装备怪兽的等级・阶级×100的伤害。','\r',char(13)),'\n',char(10)),'特殊召唤','装备效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84055227,'艺妓之影','此卡通过战斗破坏对手怪兽的场合，在此卡上放置１个魔力计数物。此卡的攻击力上升放置在此卡上的魔力计数物数量×２００点。','放置计数物','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84058253,'嵌合暴走龙',replace(replace('“电子龙”怪兽×2只以上\r\n此卡的融合召唤仅可用上述卡进行。①：此卡融合召唤成功时，可以场上的魔法・陷阱卡为对象发动，数量最多为作为此卡的融合素材的怪兽数量。将该卡破坏。②：1回合1次，在自己主要阶段可以发动。从牌组将最多2只机械族・光属性怪兽送至墓地。此回合中，此卡在通常攻击之外，在1次战斗阶段中最多可进行相当于以此效果被送至墓地的怪兽数量次数的攻击。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84079032,'面子蝙蝠',replace(replace('①：１回合最多３次，对手将怪兽召唤・特殊召唤的情况下，以其中１只为对象可以发动。掷１次硬币。正面的情况下，将该怪兽改成表侧攻击表示。反面的情况下，将该怪兽改成里侧守备表示。\r\n②：１回合１次，此卡存在于怪兽区域的状态下，场上的怪兽反转的情况下，或表侧表示怪兽变为里侧守备表示的情况下，以其中１只为对象可以发动（伤害步骤也可以发动）。将该怪兽改成表侧攻击表示或里侧守备表示。','\r',char(13)),'\n',char(10)),'用①效果改变表现形式','用②效果改变表现形式','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84080939,'大慈大悲修道女','解放此卡可以发动。选择１只此回合因战斗被破坏的自己墓地的怪兽并放回手牌。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84103702,'甲壳蟹','螃蟹怪兽。会用两个巨大的钳子将对手切碎。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84117021,'魔力隔壁',replace(replace('①：可从以下效果中选择１个并发动。此卡发动后，直至回合结束时，对手所受到的全部伤害变为０。\r\n●此回合，魔法师族怪兽的召唤、反转召唤、特殊召唤不被无效化，魔法师族怪兽的召唤、反转召唤、特殊召唤成功时，对手不可发动魔法、陷阱、怪兽效果。\r\n●可以我方场上的１只魔法师族怪兽作为对象发动。此回合该怪兽攻击的场合，直至伤害步骤结束时，对手不可发动魔法、陷阱、怪兽效果。','\r',char(13)),'\n',char(10)),'这个回合，魔法师族怪兽的召唤·反转召唤·特殊召唤不会被无效化，在魔法师族怪兽的召唤·反转召唤·特殊召唤成功时对手不可把魔法·陷阱·怪兽的效果发动。','以自己场上1只魔法师族怪兽为对象可以发动。这个回合那只怪兽攻击的情况下，对手直到伤害步骤结束时魔法·陷阱·怪兽的效果不可发动。','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84121193,'码破者・病毒剑客',replace(replace('效果怪兽2只\r\n此卡名的①②效果1回合仅可各使用1次。①：此卡特殊召唤成功时，此卡为相互连接状态的情况下可以发动。从自己的手牌・牌组・墓地挑选1只“码破者・零日”，特殊召唤至连接怪兽连接端的自己・对手场上。②：在此卡被对手破坏并被送至墓地的回合的结束阶段可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡离开场上的情况下，将其除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84121302,'书灵师・本源',replace(replace('此卡名的卡1回合仅可发动1张，此卡名的③效果1回合仅可使用1次。\r\n①：作为此卡发动时的效果处理，可从牌组将“书灵师・本源”以外的1张“书灵师”魔法・陷阱卡放置在自己场上。\r\n②：自己场上的“书灵师”仪式怪兽的攻击力上升自身的等级×100的数值。\r\n③：有仪式怪兽被仪式召唤至自己场上的情况下，以对手场上的1张魔法・陷阱卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'是否选卡在场上放置？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84124261,'编号39 希望皇霍普起源',replace(replace('等级１怪兽×２\r\n①：自己或对手的怪兽的攻击宣言时，去除此卡的１个超量素材可以发动。使该攻击无效，该怪兽是超量怪兽的情况下，此卡的攻击力上升相当于该怪兽阶级×５００的数值。','\r',char(13)),'\n',char(10)),'攻击无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84125619,'互刺GUY','①：解放自己场上的１只战士族怪兽，以场上的１张卡为对象可以发动。将该卡破坏，自己从牌组抽１张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84133008,'怪兽眼','支付１０００点LP来发动此卡。将我方墓地中的１张“融合”魔法卡收回到手牌中。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84136000,'复活的墓穴','我方怪兽因战斗被破坏并送入墓地时可发动。双方玩家各从自己的墓地选择１只怪兽，以守备表示特殊召唤至各自的场上。以此效果特殊召唤的怪兽，只要以表侧表示存在于场上，就不可变更表示形式。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84138874,'火山性地狱火',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n \r\n①：对手发动场上怪兽的效果时，从自己的墓地将１只炎族怪兽除外可以发动。给予对手５００伤害。将“火山性”怪兽除外并发动的情况下，进而可将该发动的效果无效。 \r\n②：在对手的结束阶段，以自己墓地・除外状态的最多２只“火山性”怪兽为对象可以发动。将该怪兽以喜欢的顺序放回牌组最下面。','\r',char(13)),'\n',char(10)),'给与对手伤害','回收墓地·除外的怪兽','是否把发动的效果无效？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84171830,'真帝王领域',replace(replace('①：自己的额外牌组不存在卡，且只要仅自己场上存在上级召唤的怪兽，对手就不可从额外牌组特殊召唤怪兽。\r\n②：自己上级召唤的怪兽的攻击力仅在攻击对手怪兽的伤害计算时上升800。\r\n③：1回合1次，在自己的主要阶段可以发动。自己手牌的1只攻击力2800/守备力1000的怪兽的等级直至回合结束时为止下降2。','\r',char(13)),'\n',char(10)),'等级下降','选择要把等级下降的怪兽','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84173492,'不屈斗士 磊磊','此卡进行过攻击的场合，在战斗阶段结束时变为守备表示。直到下次我方回合结束时，此卡的表示形式不可变更。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84177693,'神圣洁拉鲁','场上存在有“天空的圣域”的场合，此卡以因战斗被破坏以外的方式被送入墓地时，我方回复１０００LP。','LP回复','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84192580,'多多迷宝・噗噜海月',replace(replace('发动此卡的效果的回合中，自己仅可发动1次此卡以外的“多多迷宝”怪兽的效果。\r\n①：在自己・对手回合中，自己场上不存在卡的情况下，从手牌将此卡舍弃可以发动。在此回合中适用以下效果。\r\n●对手每次从手牌将怪兽召唤・特殊召唤，自己抽1张。\r\n●在结束阶段，自己手牌多于对手场上的卡的数量＋6张的情况下，依其数量差将自己手牌随机放回牌组。','\r',char(13)),'\n',char(10)),'抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84206435,'冰结界的纹章','①：从牌组将１只“冰结界”怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84206436,'冰结界的纹章','①：从牌组将１只“冰结界”怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84211599,'金满而谦虚之壶',replace(replace('此卡名的卡1回合仅可发动1张，发动此卡的回合中，自己不可以卡的效果抽牌。\r\n①：将自己额外牌组的3张或6张卡以里侧除外可以发动。依除外的数量，从自己的牌组上面翻开卡，从其中挑选1张加入手牌，剩余的卡以喜欢的顺序放回牌组下面。此卡发动后，直至回合结束时为止，对手受到的所有伤害变为一半。','\r',char(13)),'\n',char(10)),'除外3张卡发动','除外6张卡发动','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84218527,'命运女郎・莉瓦英德',replace(replace('此卡牌名的卡牌１回合只可发动１张。\r\n①：可以我方被除外的任意数量的“命运女郎”怪兽为对象发动。（同名卡最多１张）。特殊召唤该怪兽。以此效果特殊召唤的怪兽在结束阶段返回至持有者牌组。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84220251,'苏生徽章','①：以自己墓地的1只“纹章兽”怪兽为对象可以发动。将该怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84224627,'猫鲨',replace(replace('等级２怪兽×２\r\n①：此卡持有水属性怪兽作为超量素材的情况下，此卡不会因战斗被破坏。②：１回合１次，去除此卡的１个超量素材，以自己场上１只阶级４以下的超量怪兽为对象可以发动。该怪兽的攻击力・守备力直至回合结束时为止，改成原本数值的两倍。此效果在对手回合中也可以发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84243274,'VWXYZ－弹射加农龙',replace(replace('“VW－虎式弹射器”＋“XYZ－龙型加农炮”\r\n只有将我方场上的上述卡牌从游戏中除外的场合才可从额外牌组中特殊召唤此卡（无需“融合”魔法卡）。１回合１次，可将对手场上的１张卡牌从游戏中除外。此卡进行攻击宣言时，可变更成为攻击对象的怪兽的表示形式。此时，反转效果怪兽的效果不会发动。','\r',char(13)),'\n',char(10)),'除外','改变表示形式','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84257640,'治疗之神 蒂安・凯特','①：自己恢复１０００LP。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84257883,'巨大战舰 爆裂大炮核','此卡名以①方法的特殊召唤1回合仅可进行1次。①：对手场上怪兽的数量比自己场上的怪兽多的情况下，此卡可从手牌中特殊召唤。②：此卡召唤・特殊召唤成功的情况下发动。在此卡上放3个计数物。③：此卡不会因战斗被破坏。④：此卡进行战斗的伤害步骤结束时发动。去除此卡的1个计数物，无法去除的情况下将此卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84262395,'地缚解放','①：等级６以上的怪兽被召唤・特殊召唤至场上时，解放自己场上的１只等级１０“地缚”怪兽可以发动。将对手场上的怪兽全部破坏，给予对手相当于所破坏怪兽原本攻击力合计数值的伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84268896,'古遗物－卡多克乌斯','①：“古遗物－卡多克乌斯”在自己场上仅可有１只以表侧表示存在。②：此卡可视为魔法卡从手牌放置在魔法与陷阱区域。③：放置在魔法与陷阱区域的此卡在对手回合被破坏并送至墓地的情况下发动。将此卡特殊召唤。④：此卡已经存在于怪兽区域的状态下，“古遗物”怪兽在对手回合被特殊召唤的情况下发动。自己从牌组抽１张。','特殊召唤','抽牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84271823,'下落消除之拼图多连块',replace(replace('等级不同怪兽2只\r\n此卡名的①②效果1回合仅可各使用1次。①：此卡已经存在于怪兽区域的状态下，怪兽以表侧表示被特殊召唤至此卡连接端的情况下，宣言1～8为止的任意等级可以发动。该怪兽直至回合结束时为止变为宣言的等级。②：从自己与对手场上以各1只等级相同的怪兽为对象可以发动。将该怪兽破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84274024,'灵摆次元',replace(replace('①：此卡已存在于魔法与陷阱区域的状态下，自己以灵摆怪兽作为素材特殊召唤以下怪兽的情况下可以发动。此回合，不可以自己的“灵摆次元”的效果适用相同效果。\r\n●融合：从牌组将原本等级和该融合怪兽相同的１只怪兽的效果无效并以守备表示特殊召唤。\r\n●同步：从牌组将１张“融合”加入手牌。\r\n●超量：从牌组将等级在该超量怪兽的阶级数值以下的１只协调加入手牌或特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84281045,'弈勇觉醒－大师阶段',replace(replace('①：１回合１次，怪兽区域的卡移动至其他怪兽区域的情况下，可从以下效果中选择１个发动。\r\n●自己场上所有等级５以上的“弈勇”怪兽的攻击力直至回合结束时为止上升１２００。\r\n●把魔法与陷阱区域的表侧表示的此卡送至墓地，以对手的主要怪兽区域的１只效果怪兽为对象可以发动。将该对手怪兽视为永续魔法卡，以表侧表示放在与之同一纵列的对手的魔法与陷阱区域（原先位于所放之处的卡将被破坏）。','\r',char(13)),'\n',char(10)),'攻击力上升','对手怪兽当作魔法卡放置','请选择要放置到后场的怪兽','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84285623,'陶俑','古代王墓中守护宝物的泥人。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84288367,'法之神灵 爱华斯',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：将手牌・场上的此卡除外可以发动。从牌组将1只“阿莱斯特”怪兽加入手牌。在场上发动的情况下，进而可进行1只魔法师族怪兽的召唤。\r\n②：此卡存在于墓地的状态下，自己场上的表侧表示融合怪兽因战斗以外的方法被送至墓地的情况下可以发动。将此卡特殊召唤。然后，可将自己手牌・场上的怪兽作为融合素材，将1只“召唤兽”怪兽融合召唤。','\r',char(13)),'\n',char(10)),'检索效果','特殊召唤','是否进行召唤？','是否融合召唤？','','','','','','','','','','','','');
INSERT INTO texts VALUES(84290642,'潜行狙击手','可舍弃１张手牌，选择场上的１张卡牌并发动。摇１次骰子，出现１或６以外的数字的场合，破坏被选择卡牌。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84298614,'强化苏生','①：以自己墓地的１只等级４以下的怪兽为对象可以发动此卡。将该怪兽特殊召唤。只要此卡存在于魔法与陷阱区域，该怪兽的等级上升１，攻击力・守备力上升１００。该怪兽被破坏时将此卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84305651,'御用王',replace(replace('协调＋协调以外的同步怪兽１只或以上\r\n①：此卡进行攻击对手怪兽的攻击宣言时发动。直至伤害步骤结束时，此卡的攻击力上升我方场上的战士族、地属性同步怪兽数量×４００。\r\n②：此卡因战斗破坏对手怪兽并送入墓地时，可从以下效果选择１个发动。\r\n●将破坏的该怪兽特殊召唤至我方场上。\r\n●挑选对手场上的１只表侧表示怪兽并获得其控制权。','\r',char(13)),'\n',char(10)),'攻击上升','特殊召唤','得到控制权','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84313685,'大日神械超立方体','１回合１次，可在我方主要阶段时被视为装备卡装备我方场上冠有“大日神械”之名的怪兽，或解除装备并以表侧攻击表示特殊召唤。仅限以此效果被视为装备卡的场合，装备怪兽因战斗破坏对手怪兽的场合，可从我方墓地选择１只等级４或以下冠有“大日神械”之名的怪兽并特殊召唤。（１只怪兽最多可装备１张联合。装备怪兽被破坏的场合，破坏此卡作为代替。）','变成装备卡','特殊召唤','墓地特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84327329,'元素－英雄 黏土人','拥有粘土铸造而成的强韧身体的元素－英雄。奋不顾身地全力守护元素－英雄伙伴们。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84330567,'泪冠哀歌・露露卡洛斯',replace(replace('“泪冠哀歌・琪多卡洛斯”＋“泪冠哀歌”怪兽\r\n此卡名的②③效果１回合仅可各使用１次。①：此卡以外的自己的水族怪兽不会因战斗被破坏。②：对手发动包含将怪兽特殊召唤的效果的效果时可以发动。将该发动无效并破坏。然后，从手牌及自己场上表侧表示的卡中，挑选１张“泪冠哀歌”卡送至墓地。③：融合召唤的此卡因效果被送至墓地的情况下可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84332527,'兽带斗士“猛牛”艾英','此卡名的①②效果１回合仅可各使用１次。①：以自己墓地的１只“兽带斗士”怪兽或战士族怪兽为对象可以发动。从手牌将此卡特殊召唤，将对象怪兽视为装备卡装备于此卡。②：以自己场上的１张“兽带斗士”卡和对手场上的１张卡为对象可以发动。将该卡破坏。③：装备此卡的“兽带斗士”怪兽的攻击力上升７００，获得此卡名的②效果。','','双方卡破坏（兽带斗士“公牛”毕宿一）','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84335863,'白蔷薇回廊',replace(replace('此卡名的①效果１回合仅可使用１次。①：自己场上不存在怪兽的情况下可以发动。从手牌将１只“蔷薇龙”怪兽或植物族怪兽特殊召唤。②：在自己抽牌阶段的抽牌前，宣言卡的种类（怪兽・魔法・陷阱）可以发动。双方确认自己牌组最上面的卡，其为所宣言种类的卡的情况下，在此回合中适用以下效果。\r\n●自己场上等级７以上的同步怪兽的攻击力上升１０００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84339249,'守护天灵 罗加埃斯',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己场上的天使族怪兽的效果发动的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：以对手场上的１张表侧表示卡和自己场上的１只攻击表示的怪兽为对象可以发动。将该对手的卡除外，将该自己的怪兽改成守备表示。\r\n③：场上的此卡因战斗・效果被破坏的情况下，以场上的１只怪兽为对象可以发动。此回合，该怪兽不会因战斗被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84341431,'恶魔的巨神',replace(replace('①：只要此卡以表侧表示存在，仅限1次，此卡将被效果破坏的情况下，作为代替可支付500LP。\r\n②：此卡因效果被破坏并被送至墓地的情况下可以发动。从手牌将1只“恶魔”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'是否要使用「恶魔巨人」的效果代替破坏？','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84343351,'水晶清透翼超同步龙',replace(replace('协调2只以上或同步怪兽的协调＋“清透翼同步龙”\r\n此卡仅可以同步召唤方式特殊召唤。\r\n①：1回合1次，其他卡的效果发动时可以发动。将该发动无效并破坏。以此效果破坏了怪兽的情况下，此卡的攻击力直至回合结束时为止上升相当于该怪兽原本攻击力的数值。\r\n②：同步召唤的、表侧表示的此卡因对手从场上离开的情况下可以发动。从额外牌组将1只“清透翼”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'无效并破坏','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84361420,'锋利之锤','解放自己场上的１只“元素－英雄 刀锋人”可以发动。破坏对手场上的１只怪兽，并给予对手LP该怪兽原本攻击力数值的伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84366728,'地底王的尖兵',replace(replace('此卡名的效果１回合仅可使用１次。\r\n①：此卡存在于墓地的状态下，怪兽从自己或对手的手牌被送至墓地的情况下可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，放回牌组最下面。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84384943,'伊卡黑石',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n \r\n①：此卡召唤・反转召唤・特殊召唤的情况下可以发动。从牌组将１张“三角阵－Ｏ”加入手牌。此卡为攻击表示的情况下，进而此卡变为守备表示。 \r\n②：此卡因战斗・效果被破坏的情况下发动。自己受到１０００伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84385264,'合成狼人','由“合成魔术”召唤而来。此卡对对手生命造成战斗伤害时，给予对手生命我方墓地中通常怪兽的数量×２００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84388461,'剑圣的影灵衣－源质军刀',replace(replace('←1 【灵摆】 1→\r\n①：自己仅可灵摆召唤“影灵衣”怪兽及“源质”怪兽。此效果不会被无效化。\r\n【怪兽效果】\r\n此卡名的怪兽效果1回合仅可使用1次。\n①：解放自己手牌・场上的此卡可以发动。为使合计等级与仪式召唤的怪兽相等，解放手牌・场上的怪兽，从手牌将1只“影灵衣”仪式怪兽仪式召唤。','\r',char(13)),'\n',char(10)),'放置灵摆刻度','仪式召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84389640,'穷鼠的进击','存在于我方场上等级３或以下的通常怪兽进行战斗的场合，在该伤害步骤时可支付１００的倍数之LP发动。直至此回合的结束阶段时，进行战斗的１只对手怪兽的攻击力下降，数值相当于支付数值。','攻击下降','请选择要支付的基本分','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84397023,'等级变换实验室','向对手展示１只手牌的怪兽，并掷１次骰子。掷出１点的场合，将该怪兽送入墓地。掷出２～６点的场合，直至回合结束时，该怪兽变成掷出点数之等级。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84401683,'蛇魔・守护者',replace(replace('岩石族等级3怪兽×2\r\n①：在每个自己・对手回合中1次，去除此卡的1个超量素材，以对手场上的1只表侧表示怪兽为对象可以发动。直至回合结束时为止，将该怪兽的攻击力改成0，其效果无效化。\r\n②：1回合1次，以场上的1只攻击力0的怪兽为对象可以发动。将该怪兽破坏。','\r',char(13)),'\n',char(10)),'攻击变成0','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84401954,'格瑞恩・雷盟',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：向对手出示手牌的此卡，以场上的1张魔法・陷阱卡为对象可以发动。将该卡破坏，从手牌将1只雷族怪兽特殊召唤。此回合，自己不可从手牌以外的地方特殊召唤效果怪兽。\r\n②：此卡存在于怪兽区域的状态下，此卡以外的卡因效果被破坏的情况下可以发动。从牌组将1张“雷盟”魔法卡或“天空城塞 库龙”加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','检索效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84404797,'可回收瓶',replace(replace('此卡名的效果①在1个回合中仅可使用1次。\r\n①：除外自己墓地的1张陷阱卡后可以发动。从自己的墓地选择1张原本卡名与该卡不同的陷阱卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84417082,'编号91 雷电闪光龙',replace(replace('等级4怪兽×3\r\n①：1回合1次，依以下数量去除此卡的超量素材，可以发动相应效果。\r\n●3个：将场上的其他表侧表示怪兽全部破坏。\r\n●5个：将对手场上的卡全部破坏。','\r',char(13)),'\n',char(10)),'3个：此卡以外的表侧表示怪兽全部破坏','5个：对手场上的卡全部破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84425220,'武装龙 LV10－白','此卡不可通常召唤，仅可以此卡的效果特殊召唤。此卡名的①效果１回合仅可使用１次。①：为使合计等级为１０，从自己场上・墓地将“武装龙”怪兽除外可以发动。从手牌将此卡特殊召唤。然后，可从牌组将１张“白色面纱”加入手牌。②：此卡的控制者受到的效果伤害变为０。③：此卡攻击的伤害步骤开始时可以发动。挑选场上的１张卡破坏。','','','是否从牌组把「白色面纱」加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84428023,'电力贮藏枪','仅限装备等级３或以下的雷族怪兽。装备怪兽的攻击力上升８００点，效果被无效化。装备怪兽给予对手生命战斗伤害时，从我方牌组抽取１张卡牌。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84430165,'海晶少女潮流','此卡名的卡1回合仅可发动1张。自己场上有连接3以上的“海晶少女”怪兽存在的情况下，此卡也可从手牌发动。①：自己的“海晶少女”连接怪兽战斗破坏对手怪兽时可以发动。给予对手相当于自己的该怪兽的连接标记数量×400的伤害。自己场上有连接2以上的“海晶少女”怪兽存在、且破坏的是对手连接怪兽的情况下，进而给予对手相当于被破坏怪兽的连接标记数量×500的伤害。','适用「海晶少女潮流」的效果来发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84430950,'重装武者－弁庆','此卡除了通常攻击以外，在１次的战斗阶段中可进行相当于装备于此卡的装备卡数量的攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84433129,'星气・雷热涡炉',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次，且②效果1回合仅可使用1次。\r\n①：此卡可通过去除自己场上的1个超量素材来从手牌特殊召唤。以此方法特殊召唤过的余下本回合，自己从额外牌组仅可特殊召唤阶级4超量怪兽。\r\n②：此卡特殊召唤的情况下可以发动。从牌组将1张“雷热涡炉”魔法・陷阱卡放置在自己场上。','\r',char(13)),'\n',char(10)),'特殊召唤','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84433295,'五重魔导师',replace(replace('魔法师族怪兽×5\r\n此卡仅可以融合召唤方式特殊召唤。\r\n①：此卡以5种魔法师族怪兽作为素材融合召唤的情况下可以发动。将对手场上的卡全部破坏。\r\n②：此卡只要存在于怪兽区域，不可解放，不可作为融合素材，不会因效果被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84442536,'灰篮战斗',replace(replace('①：仅以我方场上的１只“灰篮”怪兽为对象的怪兽，其效果・魔法・陷阱卡发动时，可从以下效果选择１个发动。\r\n●该效果变成“破坏１只对象怪兽”。\r\n●使该发动无效并破坏。','\r',char(13)),'\n',char(10)),'该效果变成「作为对象的1只怪兽破坏」','该发动无效并破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84451804,'死亡青蛙','①：此卡上级召唤时可以发动。以自己墓地的“恶魂邪苦止”数量为上限，从手牌・牌组将“死亡青蛙”特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84453939,'念力王牌','①：怪兽区的此卡被解放的场合，可以场上１张卡牌为对象发动。破坏该卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84462118,'龙咬虫',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡召唤时可以发动。从手牌将１只等级４以下的昆虫族怪兽特殊召唤。\r\n②：从自己手牌・场上（表侧表示）・墓地将１只等级４以下的昆虫族怪兽除外，以自己场上的１只表侧表示怪兽为对象可以发动。该怪兽的等级直至回合结束时为止，上升相当于为发动此效果而除外的怪兽等级的数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84464389,'枪管上膛绝焰龙',replace(replace('暗属性连接怪兽＋暗属性怪兽\r\n此卡名的①②③效果1回合仅可各使用1次。\r\n①：此卡融合召唤的情况下可以发动。从牌组将1只“枪弹”怪兽加入手牌。\r\n②：以自己场上的1只暗属性怪兽为对象可以发动。将自己墓地・除外状态的1只暗属性连接怪兽视为攻击力上升500的装备魔法卡，装备于对象怪兽。\r\n③：此卡作为连接素材被送至墓地的情况下，以场上的1张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'检索效果','装备效果','破坏效果','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84472026,'鬼计雪人',replace(replace('仅限我方场上存在有“鬼计”怪兽的场合，此卡可以表侧表示召唤。\r\n①：可在我方主要阶段发动。此卡变成里侧守备表示（１回合仅限１次）。\r\n②：此卡反转时，可以场上的１只“鬼计”怪兽为对象发动。该怪兽在该回合不会因战斗、效果被破坏。','\r',char(13)),'\n',char(10)),'变成里侧守备','破坏耐性','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84477320,'星宿响手 普莉库露',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下，以“星宿响手 普莉库露”以外的、自己墓地的1只“星宿”怪兽为对象可以发动。将该怪兽特殊召唤。然后，将自己场上的1只怪兽放回手牌。\r\n②：此卡作为融合召唤的素材被送至墓地的情况下可以发动。从牌组将1张“星宿”魔法・陷阱卡放置在自己场上。','\r',char(13)),'\n',char(10)),'特殊召唤','放置','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84478195,'深渊之结界像','①：只要此卡存在于怪兽区域，双方仅可特殊召唤暗属性怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84482694,'显现的徽章',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：解放自己场上的1只怪兽可以发动。从牌组将2只“纹章兽”怪兽以守备表示特殊召唤。此卡发动后，直至回合结束时为止自己从额外牌组仅可特殊召唤念动力族怪兽及机械族怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84488827,'侵邪蚀 卡扎斯',replace(replace('释放２只数量的冠有“侵邪蚀”之名怪兽，并此卡的上级召唤成功时，可从以下效果选择１个发动。\r\n●破坏场上除此卡以外的所有怪兽。\r\n●破坏场上所有的魔法・陷阱卡。','\r',char(13)),'\n',char(10)),'选择1个效果发动','此卡以外的场上存在的怪兽全部破坏。','场上存在的魔法·陷阱卡全部破坏。','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84491298,'细胞爆破病毒','放置有A计数物的对手怪兽的攻击宣言时可发动。破坏对手场上的所有攻击表示怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84504242,'巨石异物・传送门','此卡名的②效果1回合仅可使用1次。①：仪式召唤的怪兽1回合各仅有1次不会因战斗被破坏。②：“巨石异物”怪兽被特殊召唤的情况下，以自己墓地的1只仪式怪兽为对象可以发动。将该怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84521924,'天籁音服和弦・克理娅',replace(replace('包括灵摆怪兽在内的怪兽２只以上\r\n①：此卡的攻击力上升相当于自己额外牌组的表侧表示灵摆怪兽数量×１００的数值。②：此卡连接端的灵摆怪兽发动的效果不会被无效化。③：１回合１次，对手发动效果时可以发动。将自己灵摆区域的１张灵摆刻度为奇数的“音服和弦”卡特殊召唤至此卡连接端的自己场上，将该发动无效。然后，可从牌组将１只灵摆刻度为偶数的“音服和弦”灵摆怪兽以表侧表示加入额外牌组。','\r',char(13)),'\n',char(10)),'','是否从牌组把灵摆怪兽加入额外牌组？','请选择要加入额外牌组的灵摆怪兽','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84523092,'魔女工艺・裁缝海涅',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：只要此卡存在于怪兽区域，对手不可将自己场上的其他魔法师族怪兽作为效果的对象。\r\n②：在自己・对手回合中，从手牌将1张魔法卡舍弃，以对手场上的1张表侧表示卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84530620,'雷电爸爸','①：1回合1次，在自己的主要阶段可以发动。进行“雷电爸爸”以外的、手牌的1只雷族・光属性・等级4怪兽的召唤。','召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84536654,'形态变换','①：以自己场上的1只“-英雄”融合怪兽为对象可以发动。将该怪兽放回额外牌组，将1只等级与该怪兽原本等级相同、卡名不同的“假面-英雄”怪兽视为由“假面变换”的特殊召唤从额外牌组特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84539520,'亚马逊王女',replace(replace('此卡牌名的②的效果１回合只可使用１次。\r\n①：只要存在于场上、墓地，此卡的卡牌名被视为“亚马逊女王”。\r\n②：此卡召唤、特殊召唤成功的场合可发动。从牌组将１张“亚马逊”魔法、陷阱卡加入手牌。\r\n③：此卡的攻击宣言时，可将除此卡以外的我方手牌、场地的１张卡牌送入墓地并发动。从牌组以守备表示特殊召唤１只除“亚马逊王女”以外的“亚马逊”怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84544192,'究极宝玉神 彩虹龙・超驱动',replace(replace('“究极宝玉神”怪兽＋“宝玉兽”怪兽×７\r\n仅可在自己特殊召唤“究极宝玉神”怪兽成功的决斗中，将自己的场上・墓地的上述卡除外的情况下特殊召唤。\r\n①：自己被除外的“宝玉兽”怪兽为７种以上的情况下，此卡的攻击力上升７０００。\r\n②：在自己・对手回合中，解放该回合尚未进行战斗的此卡可以发动。将场上的卡全部放回持有者的牌组，挑选任意数量的自己被除外的“宝玉兽”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84546257,'海晶少女 珊瑚大三角',replace(replace('“海晶少女”怪兽２只以上\r\n此卡名的①②效果１回合仅可各使用１次，发动此效果的回合中，自己仅可特殊召唤水属性怪兽。\r\n①：从手牌将１只水属性怪兽送至墓地可以发动。从牌组将１张“海晶少女”陷阱卡加入手牌。\r\n②：仅有对手场上才存在怪兽的情况下，将墓地的此卡除外可以发动。从自己的墓地将连接标记合计为３的任意数量的水属性连接怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84550200,'音速干扰虫','①：此卡反转的情况下发动。直至下个回合结束时为止，对手不可发动魔法卡。','发动限制','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84550369,'御巫神舞－二贵子',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：从牌组将“御巫神舞－二贵子”以外的1张“御巫”卡送至墓地。然后，可以从牌组将“御巫神舞－二贵子”以外的1张“御巫”魔法・陷阱卡放置在自己场上。此卡发动后，直至回合结束时为止自己从额外牌组仅可特殊召唤“御巫”怪兽。\r\n②：将墓地的此卡除外，去除自己场上的1个超量素材可以发动。从手牌・牌组将1只“御巫”仪式怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'发动','特殊召唤','是否把「御巫」魔法·陷阱卡放置？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84565800,'传说骑士 海尔摩斯',replace(replace('此卡不可通常召唤。\r\n仅可以“传说之心”的效果特殊召唤。\r\n①：此卡特殊召唤成功时，可以场上的１张表侧表示魔法、陷阱卡为对象发动。将该表侧表示的魔法、陷阱卡除外。\r\n②：１回合１次，此卡被选择为攻击对象时，可以我方墓地的１只效果怪兽为对象发动。直至下一个我方回合的结束阶段，此卡被视为与该墓地怪兽的同名卡获得相同效果。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84569017,'旗鱼士兵','此卡的攻击力上升从游戏中被除外的我方鱼族、海龙族、水族怪兽数量×１００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84569886,'DDD 超死伟王至紫地狱末日',replace(replace('←1 【灵摆】 1→\r\n①：1回合1次，自己的“DDD”融合怪兽与对手怪兽进行战斗的伤害计算前可以发动。该对手怪兽的攻击力直至回合结束时为止下降1000。\r\n【怪兽效果】\r\n“DDD”怪兽×2\n此卡名的①怪兽效果1回合仅可使用1次。\n①：以对手场上1只攻击表示的怪兽为对象可以发动。将该怪兽破坏，给予对手相当于其原本攻击力一半数值的伤害。\n②：对手怪兽进行战斗的伤害计算前可以发动。该对手怪兽的攻击力直至伤害步骤结束时为止变为原本的数值。\n③：怪兽区域的此卡被破坏的情况下可以发动。将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'','对手怪兽破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84592800,'变形斗士・录影机',replace(replace('此卡依据此卡的表示形式获得以下效果。\r\n●攻击表示：此卡的攻击力上升装备于此卡的装备卡数量×８００点。\r\n●守备表示：此卡的守备力上升装备于此卡的装备卡数量×８００点。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84613836,'神速的盔甲','在我方抽牌阶段抽取卡牌时，该卡是冠有“六武众”之名怪兽的场合，可向对手展示该卡并发动。可特殊召唤该卡。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84620194,'断头锹型虫','栖息于高等精灵之森林的锹型虫。虽然体型只有人类的拇指一般大，但却拥有能够咬碎钢铁的颚力。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84631951,'新世侵略梁龙',replace(replace('自己１回合仅可特殊召唤“新世侵略梁龙”１次，其②效果１回合仅可使用１次。\r\n①：自己场上存在２只以上的恐龙族怪兽的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：解放自己场上的１只等级４以下的怪兽可以发动。从牌组将１只等级比所解放怪兽高２或低２的恐龙族怪兽特殊召唤。以此效果特殊召唤的怪兽将在结束阶段被破坏。','\r',char(13)),'\n',char(10)),'从手牌特殊召唤','从牌组特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84635192,'啾噜噗噜噗珑',replace(replace('此卡名的效果１回合仅可使用１次。\r\n①：此卡存在于手牌的情况下，以自己的主要怪兽区域的１只水属性怪兽为对象可以发动。将该自己的怪兽破坏，将此卡特殊召唤至该怪兽原先存在的区域。然后，可将与此卡同一纵列的、对手的表侧表示卡全部破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','是否破坏对手的卡？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84636823,'魔术抵消器','①：只要此卡存在于怪兽区域，双方不可在场上发动魔法卡的效果，场上的魔法卡的效果无效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84640866,'电网落穴','①：对手从牌组・墓地将怪兽特殊召唤时可以发动。将该怪兽以里侧表示除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84650463,'冰沙怪','成功召唤此卡时，可从牌组将１只“冰沙怪”送入墓地。此外，我方墓地的“冰沙怪”以及从游戏中除外的我方的“冰沙怪”合计为３只的场合，可将墓地的此卡从游戏中除外并发动。选择我方墓地的１只海龙族、等级５或以上的怪兽特殊召唤。“冰沙怪”的效果１回合只可使用１次。','送墓','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84653834,'超能力增幅器','此卡发动时，以表侧表示存在于我方场上的所有念动力族怪兽的攻击力，上升从游戏中被除外的我方念动力族怪兽数量×３００点。受到此效果的怪兽在结束阶段时从游戏中被除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84664085,'卫星战士',replace(replace('协调＋1只以上协调以外的同步怪兽\r\n此卡名的①②效果1回合仅可各使用1次。①：此卡同步召唤成功的情况下，以对手场上的卡为对象可以发动，数量最多为自己墓地的同步怪兽数量。破坏该卡，此卡的攻击力上升相当于破坏数量×1000的数值。②：同步召唤的此卡被破坏的情况下可以发动。从自己的墓地挑选最多3只等级8以下的“战士”、“同步士”、“星尘”同步怪兽特殊召唤（同名卡最多1张）。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84673417,'暮光道将军 杰恩',replace(replace('①：１回合１次，可从我方手牌、墓地将１只“光道”怪兽除外，并以场上的１只表侧表示怪兽为对象发动。直至回合结束时，该怪兽的攻击力、守备力下降被除外怪兽的等级×３００。\r\n②：１回合１次，除此卡以外的我方“光道”怪兽效果发动的场合发动。从我方牌组上方将２张卡牌送入墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84673574,'QQ九角怪',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：此卡存在于手牌・墓地的情况下，向对手出示“QQ九角怪”以外的、手牌的1只等级9怪兽可以发动。将此卡与出示的怪兽共2只以守备表示特殊召唤。此效果发动后，直至回合结束时为止自己从额外牌组仅可特殊召唤阶级9以上的超量怪兽。\r\n②：持有此卡作为超量素材的阶级9以上的超量怪兽获得以下效果。\r\n●此卡的攻击力・守备力上升900。','\r',char(13)),'\n',char(10)),'特殊召唤','','「QQ九角怪」效果适用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84677654,'大金星！？','可宣言１至１２的任意等级并发动。双方玩家各掷１次硬币，双方都掷出正面的场合，我方场上所有怪兽的等级变成宣言等级。双方都掷出反面的场合，我方失去宣言等级数×５００LP。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84686841,'烟之王','潜藏在烟雾中的恶魔。用烟雾包围四周，让一切都变得看不见。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84687358,'反射镜力龙',replace(replace('此卡仅可在以“克里底亚之牙”的效果将自己的手牌・场上的“神圣防护罩－反射镜力－”送至墓地的情况下特殊召唤。\r\n①：自己场上的怪兽被选择为攻击对象时，或成为对手的效果的对象时可以发动。将对手场上的卡全部破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84693918,'音服和弦・索露菲基娅',replace(replace('←9 【灵摆】 9→\r\n此卡名的灵摆效果1回合仅可使用1次。\n①：对手在场上所发动的怪兽的效果处理时，自己场上存在“天籁音服和弦”怪兽的情况下，可将该发动的效果无效。然后，将此卡破坏。\r\n【怪兽效果】\r\n此卡名的①②怪兽效果1回合仅可各使用1次。\n①：自己场上的怪兽，不存在的情况下或均为“音服和弦”怪兽的情况下可以发动。从手牌将此卡特殊召唤。\n②：在自己的主要阶段可以发动（也可以通过解放此卡来发动）。从手牌将“音服和弦・索露菲基娅”以外的1只“音服和弦”怪兽特殊召唤。解放此卡来发动的情况下，也可从自己额外牌组（表侧）・墓地挑选要特殊召唤的怪兽。','\r',char(13)),'\n',char(10)),'特殊召唤','特殊召唤','是否解放来发动？','是否适用「音服和弦·索尔费吉娅」的效果来无效？','','','','','','','','','','','','');
INSERT INTO texts VALUES(84696266,'音速鸭','可以以音速行走的鸭子。由于不能适应其惊人的速度而经常失控。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84731222,'希望之记忆','此卡名的卡１回合仅可发动１张。①：依自己场上“编号”超量怪兽种类的数量，自己从牌组抽牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84740193,'破坏发射器','仅限装备攻击力１０００或以下的怪兽。伤害计算时，对手怪兽若是攻击表示则攻击力、若是守备表示则守备力在２５００点或以上的场合，装备了此卡的怪兽攻击力上升２５００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84747429,'空邪虎鲸','１回合１次，可从手牌将１只鱼族、海龙族、水族怪兽从游戏中除外并发动。选择对手场上的１张表侧表示卡牌并破坏。之后，直至下一个我方准备阶段将此卡从游戏中除外。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84749824,'神之警告',replace(replace('①：支付2000LP可以发动以下效果。\r\n●包含将怪兽特殊召唤的效果在内的、怪兽的效果・魔法・陷阱卡发动时可以发动。将该发动无效并破坏。\r\n●自己或对手召唤・反转召唤・特殊召唤怪兽之际可以发动。将其无效，将该怪兽破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84749825,'神之警告',replace(replace('①：支付2000LP可以发动以下效果。\r\n●包含将怪兽特殊召唤的效果在内的、怪兽的效果・魔法・陷阱卡发动时可以发动。将该发动无效并破坏。\r\n●自己或对手召唤・反转召唤・特殊召唤怪兽之际可以发动。将其无效，将该怪兽破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84754430,'机界骑士 阿布拉姆',replace(replace('守护星光的勇者\r\n为了讨伐幻界的黑暗\r\n将其力量托于被选中者。\r\n继承于星之杯的意志成为崭新钥匙\r\n化作斩断黑暗之剑吧。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84755744,'转生炎兽 老虎',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：从手牌将１张其他的“转生炎兽”卡舍弃可以发动。从手牌将此卡特殊召唤。\r\n②：以自己场上的此卡作为炎属性同步怪兽的同步素材的情况下，可将此卡视为协调以外的怪兽。\r\n③：１回合１次，在自己的主要阶段可以发动。此卡的等级上升或下降１。','\r',char(13)),'\n',char(10)),'','','等级上升','等级下降','','','','','','','','','','','','');
INSERT INTO texts VALUES(84764038,'彼岸恶鬼 司加密林','此卡名的①③效果1回合1次，仅可使用其中1个。①：自己场上没有魔法・陷阱卡存在的情况下可以发动。从手牌将此卡特殊召唤。②：自己场上有“彼岸”怪兽以外的怪兽存在的情况下此卡将被破坏。③：在此卡被送至墓地的回合的结束阶段可以发动。从牌组将1只“彼岸恶鬼 司加密林”以外的恶魔族・暗属性・等级3怪兽加入手牌。','特殊召唤','牌组检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84766279,'大薰风飞鹏',replace(replace('协调＋协调以外冠有“薰风”之名的怪兽１只或以上\r\n１回合１次，可将我方墓地２只冠有“薰风”之名的怪兽返回至牌组并发动。选择对手场上的１只表侧表示怪兽并破坏。','\r',char(13)),'\n',char(10)),'对手场上表侧表示存在的1只怪兽破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84769941,'对坏兽用决战兵器 超级机械哥吉龙',replace(replace('此卡不可通常召唤。\r\n对手场上存在有“坏兽”怪兽的场合，可特殊召唤。\r\n①：仅可有１只“坏兽”怪兽以表侧表示存在于我方场上。\r\n②：１回合１次，可移除我方、对手场上的２个坏兽计数物并发动。从我方手牌、墓地挑选１只“坏兽”怪兽并视为装备卡装备此卡。\r\n③：此卡的攻击力上升因此卡效果所装备之“坏兽”怪兽的原本攻击力数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84778110,'火石岩壁龙',replace(replace('此卡牌名的①②效果１回合只可各使用１次。\r\n①：此卡特殊召唤成功的场合可发动。挑选我方手牌的１张卡牌并舍弃，从额外牌组将１只“化石”融合怪兽送入墓地。\r\n②：可将场上的此卡送入墓地并发动。给予对手５００的伤害。我方墓地存在有“化石融合”的场合，可进一步挑选我方被除外的１张“化石融合”或１张记载有该卡牌名的卡牌返回至墓地。','\r',char(13)),'\n',char(10)),'额外牌组送至墓地','除外的卡回到墓地','是否选除外的卡回到墓地？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84792926,'圆盘斗技场 兽带斗士擂台','此卡名的卡１回合仅可发动１张。①：作为此卡发动时的效果处理，可从牌组将１只“兽带斗士”怪兽加入手牌。②：１回合１次，自己的怪兽将被战斗破坏的情况下，作为代替可以从牌组将１张“兽带斗士”卡或“无尽机关 阿尔银洛系统”送至墓地。③：１回合１次，自己或对手的怪兽因战斗被破坏并被送至墓地时，以自己墓地的１只“兽带斗士”怪兽为对象可以发动。将该怪兽加入手牌。','是否从牌组把1只「兽带斗士」怪兽加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84794011,'索利堤德','下半身是鹿，持有吸魂大镰的兽战士。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84797028,'机械装置作响之夜',replace(replace('此卡名的卡1回合仅可发动1张，此卡名的③效果1回合仅可使用1次。\r\n①：场上的表侧表示怪兽变为机械族。\r\n②：自己场上的机械族怪兽的攻击力・守备力上升500，对手场上的机械族怪兽的攻击力・守备力下降500。\r\n③：将墓地的此卡除外，舍弃1张手牌可以发动。从牌组将1只机械族・地属性怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84808313,'大进化药','解放自己场上的１只恐龙族怪兽可以发动此卡。此卡发动后持续留在场上，将在第３个对手回合的对手结束阶段被破坏。①：只要此卡存在于魔法与陷阱区域，自己可免除召唤等级５以上的恐龙族怪兽所必须的解放。','使用「大进化药」的效果不用解放召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84812868,'月光白兔','①：此卡召唤成功时，以自己墓地的１只“月光白兔”以外的“月光”怪兽为对象可以发动。以守备表示形式将该怪兽特殊召唤。②：１回合１次，以对手场上的魔法・陷阱卡为对象可以发动，数量最多为自己场上此卡以外的“月光”卡的数量。将该卡放回持有者的手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84813516,'铁球魔神 戈罗贡',replace(replace('此卡名的①②③效果１回合仅可各使用１次。\r\n①：怪兽进行战斗的伤害步骤结束时可以发动。从手牌将此卡特殊召唤。\r\n②：从手牌及自己场上被放置的卡中，将１张陷阱卡送至墓地可以发动。将与此卡同一纵列的其他怪兽全部破坏。\r\n③：怪兽区域的此卡因战斗・效果被破坏并被送至墓地的情况下，以自己墓地的１张卡为对象可以发动。摇１次骰子。出现６的情况下，将对象卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84814897,'骑龙','１回合１次，可在我方的主要阶段时，将此卡作为装备卡装备至我方的“暗魔界之战士 暗剑”上，或者解除装备状态以表侧攻击表示特殊召唤此卡。以此效果变为装备卡的场合，装备怪兽的攻击力和守备力上升９００点。解放成为装备卡的此卡，可令装备怪兽在该回合中能够直接攻击对手玩家。（１只怪兽最多只可装备１张联合。装备怪兽因战斗而被破坏的场合，破坏此卡来代替。）','装备','解除装备状态表侧攻击表示特殊召唤','装备怪兽在这个回合可以直接攻击','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84815190,'鲜花之女男爵',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的②效果1回合仅可使用1次。\r\n①：1回合1次，以场上的1张卡为对象可以发动。将该卡破坏。\r\n②：只要此卡以表侧表示存在，仅限1次，魔法・陷阱・怪兽的效果发动时可以发动。将该发动无效并破坏。\r\n③：在自己・对手的准备阶段，以自己墓地的1只等级9以下的怪兽为对象可以发动。将此卡放回额外牌组，将对象怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','已发动过效果','','','','','','','','','','','','');
INSERT INTO texts VALUES(84816244,'闪盘橡实','此卡名的效果1回合仅可使用1次。①：此卡特殊召唤成功的情况下可以发动。将1只“闪盘衍生物”（电子界族・暗・星1・攻/守0）特殊召唤至自己场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84816245,'闪盘衍生物','由「闪盘橡实」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84824601,'植物少女','此卡从场上被送入墓地时可发动。从牌组将１只守备力１０００或以下的植物族怪兽加入手牌。','牌组检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84824728,'寻宝豹',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：此卡存在于手牌，且场上存在里侧守备表示怪兽的情况下可以发动。将此卡特殊召唤。\r\n②：以场上最多3只里侧守备表示怪兽为对象可以发动。将该怪兽改成攻击表示。以此效果将3只怪兽改成了攻击表示的情况下，进而给予对手900伤害。\r\n③：此卡反转的情况下可以发动。从牌组将1只通常怪兽送至墓地。','\r',char(13)),'\n',char(10)),'特殊召唤','变更表示形式','送至墓地','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84834865,'飞行蜻蜓','当此卡因战斗而被破坏送入墓地时，可从我方牌组以表侧攻击表示特殊召唤１只攻击力１５００以下的风属性怪兽至我方场上。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84845628,'狱落鸟',replace(replace('①：此卡的攻击力・守备力上升自己墓地的协调数量×100的数值。\r\n②：1回合1次，从手牌将1只协调送至墓地，以对手场上的1只怪兽为对象可以发动。获得该怪兽的控制权直至结束阶段为止。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84847656,'念动攻击手','念动力族怪兽被破坏的场合，可支付５００LP，破坏此卡来代替。','是否要使用「念动攻击手」的效果代替破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84851250,'风魔女－暴雪铃','此卡名的②效果１回合仅可使用１次。①：自己场上没有怪兽存在，或仅有“风魔女”怪兽的情况下，此卡无需解放即可召唤。②：自己场上有“风魔女－暴雪铃”以外的“风魔女”怪兽存在的情况下，在对手的主要阶段，将手牌・场上的此卡送至墓地可以发动。给予对手５００伤害。','不用解放作召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84869738,'霸王之逆鳞',replace(replace('①：自己场上存在“霸王龙扎克”的情况下可以发动。将自己场上“霸王龙扎克”以外的怪兽全部破坏，从自己的手牌・牌组・额外牌组・墓地将卡名不同的最多４只“霸王眷龙”怪兽无视召唤条件特殊召唤。\r\n②：将墓地的此卡除外，以自己场上的１只“霸王眷龙”超量怪兽为对象可以发动。从自己的额外牌组（表侧）・墓地挑选２只“霸王眷龙”怪兽，作为对象怪兽的超量素材。','\r',char(13)),'\n',char(10)),'是否继续特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84877802,'最强之盾',replace(replace('仅可装备于战士族怪兽。\r\n①：根据装备怪兽的表示形式，适用以下效果。\r\n●攻击表示：装备怪兽的攻击力上升其原本守备力的数值。\r\n●守备表示：装备怪兽的守备力上升其原本攻击力的数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84899094,'星杯守护龙','此卡名的②效果1回合仅可使用1次。①：以自己场上连接状态的怪兽为对象的魔法・陷阱・怪兽的效果发动时，将手牌・场上的此卡送至墓地可以发动。将该发动无效并破坏。②：将墓地的此卡除外，以自己墓地的1只通常怪兽为对象可以发动。将该怪兽以守备表示特殊召唤至连接怪兽的连接端的自己场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84900597,'拉米亚',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将１只爬虫类族・等级８怪兽加入手牌。\r\n②：此卡被除外的情况下，以自己场上的１只爬虫类族怪兽为对象可以发动。该怪兽直至下个回合结束时为止，不会因效果被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84903021,'战吼・猛穆德',replace(replace('此卡牌名的②效果１回合只可使用１次。\r\n①：我方场上不存在有怪兽或仅有战士族怪兽的场合，此卡可无需解放进行召唤。\r\n②：我方战士族・地属性怪兽进行了战斗的伤害计算后，可以对手场上的１张魔法・陷阱卡为对象发动。该卡破坏。之后，直至对手回合结束时，我方场上所有“战吼”怪兽的攻击力上升２００。','\r',char(13)),'\n',char(10)),'不用解放作召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84905691,'大植然蜂针','①：对手特殊召唤怪兽成功时，解放自己场上此卡以外的１只表侧表示“大植然”怪兽可以发动。将该怪兽破坏。此效果在对手回合中也可以发动。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84914462,'巨斧龙人','①：此卡攻击的情况下，伤害步骤结束时变为守备表示。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84916669,'多里雅德','森林的精灵。借助草木的力量封锁对手的行动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84926738,'雷仙人','反转：回复３０００LP。此卡从场上被送入墓地时，失去５０００LP。','LP回复','LP失去','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84932271,'异虫杰特立克普斯','此卡在反转的回合被破坏并送入墓地时，从墓地以守备表示特殊召唤此卡。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84941194,'荷鲁斯的荣光－伊姆塞特',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次，且②③效果1回合仅可各使用1次。\r\n①：自己场上存在“王之棺”的情况下，此卡可从墓地特殊召唤。\r\n②：将包含此卡在内的2张手牌送至墓地可以发动。从牌组将1张“王之棺”加入手牌。然后，自己可抽1张。\r\n③：此卡存在于怪兽区域的状态下，自己场上的其他卡因对手的效果从场上离开的情况下可以发动。将场上的1张卡送至墓地。','\r',char(13)),'\n',char(10)),'','','是否抽牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84962466,'野兽爆气','１回合１次，可将我方场上的１只表侧表示的兽族、兽战士族怪兽从游戏中除外并发动。选择我方场上的１只兽族、兽战士族怪兽，该攻击力上升相当于除外怪兽的原本攻击力。','是否现在使用「野兽爆气」的效果？','攻击上升','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84965420,'龙机巧流星群','此卡名的卡1回合仅可发动1张。①：自己场上有仪式怪兽存在、对手召唤・特殊召唤怪兽之际可以发动。将其无效化，将该怪兽放回持有者的牌组。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84968490,'针虫的巢穴','①：从自己牌组上面将5张卡送至墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84970821,'暗黑的咒缚','①：只要此卡存在于魔法与陷阱区域，每次自己或对手发动魔法卡就给予该发动玩家１０００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84976088,'后台龙',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：此卡存在于墓地，且自己场上不存在卡的情况下可以发动。将此卡和手牌的1只等级4以下的龙族怪兽以守备表示特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84988419,'幻奏华歌圣 绽放名伶',replace(replace('“幻奏音姬”怪兽＋“幻奏”怪兽\r\n①：此卡不会因战斗・效果被破坏，因此卡的战斗对自己造成的战斗伤害变为０。\r\n②：此卡与被特殊召唤的怪兽进行战斗的伤害计算后可以发动。给予对手相当于该对手怪兽与此卡原本攻击力之差的数值的伤害，将该对手怪兽破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(84990171,'豌豆士兵','使用剑和豆子攻击的植物战士。出乎意料的的强大。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85004150,'电子光虫－总线独角仙',replace(replace('昆虫族、光属性等级７怪兽×２只或以上\r\n此卡也可从我方场上阶级５、６的昆虫族×怪兽移除２个超量素材，并重叠至该超量怪兽的上方进行超量召唤。\r\n①：此卡攻击了守备表示怪兽的场合，给予相当于攻击力超过该守备力数值的战斗伤害。\r\n②：１回合１次，可移除此卡的１个超量素材并发动。破坏对手场上守备力最高的怪兽。此效果在对手回合也可发动。','\r',char(13)),'\n',char(10)),'是否在在超量怪兽上面重叠来超量召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85008676,'刚鬼 固定章鱼','此卡名的③效果1回合仅可使用1次。①：对手怪兽攻击的情况下，该伤害计算时将此卡从手牌中舍弃可以发动。因该战斗对自己产生的战斗伤害变为一半。②：对手发动给予自己伤害的效果时，将此卡从手牌中舍弃可以发动（伤害步骤也可以发动）。自己因该效果受到的伤害变为一半。③：此卡从场上被送至墓地的情况下可以发动。从牌组将1张“刚鬼 固定章鱼”以外的“刚鬼”卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85028288,'朱罗纪・泰坦龙',replace(replace('此卡不可特殊召唤。\r\n①：双方不可将场上的此卡作为陷阱・怪兽的效果的对象。\r\n②：1回合1次，从自己墓地将1只攻击力1700以下的“朱罗纪”怪兽除外可以发动。此卡的攻击力直至回合结束时为止上升1000。','\r',char(13)),'\n',char(10)),'攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85032782,'鲜花之贤者','此卡名的①②效果1回合仅可各使用1次。①：以自己场上的1只怪兽和场上的1张卡为对象可以发动。将此卡从手牌特殊召唤，将对象卡破坏。②：此卡从场上被送至墓地的情况下，以自己墓地此卡以外的1只怪兽为对象可以发动。将该怪兽放回牌组。然后，从自己的牌组・墓地挑选1只植物族・等级1怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85034450,'疾行机人小钢珠卡丁车','①：１回合１次，可从手牌舍弃１只机械族怪兽，并以场上的１只怪兽为对象发动。破坏该怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85055821,'森之圣兽 千斤榆熊','此卡名的①②效果１回合仅可各使用１次。①：此卡从手牌被送至墓地的情况下，以自己墓地此卡以外的兽族・兽战士族・鸟兽族・昆虫族・植物族怪兽共２只为对象可以发动（同种族最多１只）。将该怪兽放回牌组，将此卡特殊召唤。②：此卡召唤・特殊召唤成功的情况下可以发动。从牌组将“森之圣兽 千斤榆熊”以外的１只“森之圣兽”怪兽或“森之圣灵”怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85059922,'超魔导战士－混沌之主宰者',replace(replace('“黑魔导”＋“混沌”仪式怪兽\r\n此卡名的①②③效果1回合仅可各使用1次。\r\n①：此卡融合召唤的情况下，以自己墓地的1只光・暗属性怪兽为对象可以发动。将该怪兽特殊召唤。\r\n②：解放自己场上的光・暗属性怪兽各1只可以发动。将对手场上的怪兽全部除外。\r\n③：融合召唤的此卡因战斗・效果被破坏的情况下，以自己墓地的1张魔法卡为对象可以发动。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85060248,'心灵防护者',replace(replace('此卡的控制者在每个自己的准备阶段支付500LP（无法支付的情况下，将此卡破坏）。\r\n①：只要此卡存在于怪兽区域，除念动力族怪兽以外，攻击力2000以下的怪兽不可攻击宣言。','\r',char(13)),'\n',char(10)),'是否要支付500基本分维持「心灵防护者」？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85065943,'圣徒蓟主',replace(replace('等级6以上的融合怪兽＋等级6以上的同步怪兽\r\n此卡名的②效果1回合仅可使用1次。\r\n①：只要此卡存在于怪兽区域，对手不可将此卡及对手场上・墓地・除外状态的卡作为效果的对象，且自己将受到的战斗伤害由对手代为承受。\r\n②：在此卡融合召唤的自己・对手回合可以发动。从牌组・额外牌组将1只等级9以下的“圣徒”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'不可拿作为对象','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85066822,'水合龙','此卡不可通常召唤。仅可以“键结－H２O”的效果特殊召唤。只要此卡以表侧表示存在于场上，场上炎属性怪兽和炎族怪兽的攻击力变成０。此卡被破坏送入墓地时，可选择２只我方墓地的“氢魔兽”和１只“氧魔兽”特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85080048,'雷之制裁','我方场上的雷族怪兽被召唤、反转召唤、特殊召唤时可发动。选择对手场上的１张卡牌并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85080444,'古遗物－埃癸斯','①：此卡可视为魔法卡从手牌放置在魔法与陷阱区域。②：放置在魔法与陷阱区域的此卡在对手回合被破坏并送至墓地的情况下发动。将此卡特殊召唤。③：在对手回合中，此卡特殊召唤成功的情况下发动。此回合中，自己场上的“古遗物”怪兽不会成为对手效果的对象，也不会因对手的效果而被破坏。','特殊召唤','效果耐性','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85087012,'卡片炮击士','①：1回合1次，自己从牌组上面将最多3张卡送至墓地可以发动。直至回合结束时为止，此卡的攻击力上升为发动此效果送至墓地的卡数量×500的数值。②：自己场上的此卡被破坏送至墓地的情况下发动。自己从牌组抽1张。','攻击上升','抽牌','请选择要送至墓地的卡的数量','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85101097,'布丁队',replace(replace('此卡不可作为融合・同步・超量召唤的素材。\r\n①：只要此卡存在于怪兽区域，此卡不可解放。\r\n②：在自己的结束阶段，以自己的灵摆区域的１张卡为对象可以发动。将该卡破坏，此卡的控制权转移给对手。\r\n③：在自己的准备阶段发动。自己受到３００伤害。','\r',char(13)),'\n',char(10)),'控制权转移','效果伤害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85101228,'变形斗士・束缚网','只要我方场上存在有冠有“变形斗士”之名的怪兽，对手场上等级４或以上的怪兽不可进行攻击宣言，也不可变更表示形式。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85103922,'古遗物－魔拉尔挞','①：此卡可视为魔法卡从手牌放置在魔法与陷阱区域。②：放置在魔法与陷阱区域的此卡在对手回合被破坏并送至墓地的情况下发动。将此卡特殊召唤。③：在对手回合中，此卡特殊召唤成功的情况下可以发动。挑选对手场上的１张表侧表示卡破坏。','特殊召唤','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85106525,'篝火',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：从牌组将１只等级４以下的炎族怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85115440,'十二兽 丑斧',replace(replace('等级4怪兽×2\r\n“十二兽 丑斧”1回合1次，也可重叠在同名卡以外的、自己场上的“十二兽”怪兽上面来超量召唤。\r\n①：此卡的攻击力・守备力分别上升此卡持有的超量素材中“十二兽”怪兽的相应数值。\r\n②：1回合1次，去除此卡的1个超量素材可以发动。从牌组将1只可通常召唤的兽战士族怪兽加入手牌。','\r',char(13)),'\n',char(10)),'是否在「十二兽」怪兽上面重叠来超量召唤？','兽战士族怪兽加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85119159,'拟声选择','此卡名的卡１回合仅可发动１张，此卡名的②效果１回合仅可使用１次。①：作为此卡发动时的效果处理，可从牌组将“拟声选择”以外的１张“拟声”卡加入手牌。②：以自己场上“刷拉拉”、“我我我”、“隆隆隆”、“怒怒怒”怪兽中的任意１只为对象可以发动。自己场上的所有怪兽的等级直至回合结束时为止，变为与对象怪兽的等级相同。','','是否从牌组把1张「拟声」卡加入手牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85121942,'混沌编号105 燃烧拳斗士 彗星之拳套',replace(replace('等级５怪兽×４\r\n①：此卡战斗破坏怪兽并将其送至墓地的情况下发动。给予对手相当于该怪兽原本攻击力一半数值的伤害。\r\n②：此卡持有“编号105 燃烧拳斗士 流星之拳带”作为超量素材的情况下，获得以下效果。\r\n●１回合１次，去除此卡的１个超量素材，以对手场上的１只怪兽为对象可以发动。将该怪兽破坏，破坏了表侧表示怪兽的情况下，给予对手相当于其攻击力数值的伤害。','\r',char(13)),'\n',char(10)),'伤害','破坏并伤害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85123771,'格布林降下部队',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡从手牌以攻击表示特殊召唤的情况下，以对手场上的１只效果怪兽为对象可以发动。将此卡改成守备表示。对象怪兽的效果在此卡以表侧守备表示存在期间无效化。\r\n②：此卡存在于墓地的状态下，怪兽被特殊召唤至对手场上的情况下，舍弃１张手牌可以发动。将此卡加入手牌。','\r',char(13)),'\n',char(10)),'无效怪兽','此卡加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85136114,'机甲部队・夺舍封存体','此卡名的①②效果１回合仅可各使用１次。①：此卡召唤・特殊召唤成功的情况下，以自己墓地的１只“机甲部队・夺舍封存体”以外的“机甲部队”怪兽为对象可以发动。以守备表示形式将该怪兽特殊召唤。以此效果特殊召唤的怪兽，此回合不可发动效果。②：以自己场上此卡以外的１只“机甲部队”怪兽和对手场上１张魔法・陷阱卡为对象可以发动。将该卡放回持有者的手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85138716,'救援兔',replace(replace('此卡不可从牌组特殊召唤。\r\n此卡名的效果１回合仅可使用１次。\r\n①：将场上的此卡除外可以发动。从牌组将等级４以下的２只同名通常怪兽特殊召唤。以此效果特殊召唤的怪兽将在结束阶段被破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85138717,'救援兔',replace(replace('此卡不可从牌组特殊召唤。\r\n此卡名的效果１回合仅可使用１次。\r\n①：将场上的此卡除外可以发动。从牌组将等级４以下的２只同名通常怪兽特殊召唤。以此效果特殊召唤的怪兽将在结束阶段被破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85150300,'精灵猎人',replace(replace('①：在每个对手的准备阶段1次，可从以下效果中选择1个发动。\r\n●从牌组将1只怪兽视为永续魔法卡，以表侧表示放在自己的魔法与陷阱区域。\r\n●对手可将自己的魔法与陷阱区域的1张怪兽卡特殊召唤至自身场上。该情况下，对手进而支付相当于其原本攻击力数值的LP。\r\n②：原本持有者为自己的效果怪兽被特殊召唤至对手场上的情况下，将魔法与陷阱区域的表侧表示的此卡送至墓地可以发动。从牌组将1只等级4以下的怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'选择1个效果发动','特殊召唤','放置怪兽','对手特殊召唤','是否特殊召唤怪兽？','','','','','','','','','','','');
INSERT INTO texts VALUES(85154941,'公爵恶魔',replace(replace('此卡名的②③效果1回合仅可各使用1次。\r\n①：此卡的攻击力上升此卡的等级×200的数值。\r\n②：以自己场上的1只表侧表示怪兽为对象可以发动。从牌组将“公爵恶魔”以外的1只“恶魔”怪兽送至墓地。对象怪兽的等级上升送至了墓地的怪兽的等级。\r\n③：此卡存在于墓地的状态下，自己的仪式怪兽因战斗被破坏时可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'送至墓地','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85166216,'恩惠之像','此卡因对手的卡牌效果从手牌被送入墓地时，我方回复２０００LP。','回复','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85182315,'粉碎之破坏神',replace(replace('此卡名的①②效果１回合仅可各使用１次，其发动和效果不会被无效化。\r\n①：从自己的手牌・墓地挑选１只“欧贝利斯克之巨神兵”特殊召唤。以此效果特殊召唤的怪兽此回合不受对手效果的影响。\r\n②：自己场上存在“欧贝利斯克之巨神兵”的状态下，自己为发动卡的效果同时解放自己场上的２只以上怪兽的情况下，将墓地的此卡除外可以发动。将对手墓地的怪兽全部除外，给予对手相当于其数量×５００的伤害。','\r',char(13)),'\n',char(10)),'','','「粉碎之破坏神」效果适用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85215458,'黑羽－月影之卡鲁特','①：自己的“黑羽”怪兽进行战斗的伤害步骤开始时至伤害计算前为止，从手牌将此卡送至墓地可以发动。该怪兽的攻击力直至回合结束时为止上升1400。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85216896,'源质・梅塔特隆',replace(replace('被从额外牌组特殊召唤的怪兽２只以上\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡连接端的、被从额外牌组特殊召唤的怪兽因战斗或对手的效果被破坏的情况下可以发动。从自己墓地的怪兽及自己的额外牌组的表侧表示的灵摆怪兽中，挑选１只怪兽加入手牌。\r\n②：以此卡以外的、自己及对手场上的被从额外牌组特殊召唤的怪兽各１只为对象可以发动。将该２只怪兽直至结束阶段为止除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85239662,'神秘妖精 艾尔菲莉亚','１回合１次，将手牌的１只风属性怪兽出示给对手可以发动。直至对手回合结束时为止，双方玩家不可将等级不同于所出示怪兽的怪兽作为超量召唤的素材。','召唤限制','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85243784,'连接十字',replace(replace('连接２以上的连接怪兽１只\r\n此卡名的效果１回合仅可使用１次。\r\n①：此卡连接召唤成功的情况下可以发动。将“连接衍生物”（电子界族・光・星１・攻／守０）特殊召唤至自己场上，数量最多为作为该连接素材的连接怪兽的连接标记数量。此效果发动后，直至回合结束时为止，自己不可将“连接衍生物”作为连接素材。','\r',char(13)),'\n',char(10)),'','请选择要特殊召唤的衍生物的数量','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85243785,'连接衍生物','由“连接信徒”等的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85250352,'火山性烈焰加农炮',replace(replace('从手牌・牌组・场上（表侧表示）将１张“烈焰加农炮”送至墓地，可以发动此卡。\r\n \r\n①：“火山性烈焰加农炮”在自己场上仅可有１张以表侧表示存在。 \r\n②：１回合１次，在自己的主要阶段可以发动。从手牌将１只“火山性”怪兽特殊召唤。 \r\n③：１回合１次，以对手场上的１只表侧表示怪兽为对象可以发动。从牌组将１只炎族・等级１怪兽送至墓地，将对象怪兽破坏。','\r',char(13)),'\n',char(10)),'从手牌特殊召唤','对手怪兽破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85252081,'超级量子机兽 惊涛虎鲸',replace(replace('等级3怪兽×2\r\n①：没有超量素材的此卡不可攻击。\r\n②：1回合1次，去除此卡的1个超量素材，以场上的1张魔法・陷阱卡为对象可以发动（此卡持有“超级量子士 蓝层”作为超量素材的情况下，此效果在对手回合中也可以发动）。将该卡破坏。\r\n③：1回合1次，在自己的主要阶段可以发动。从自己手牌・场上（表侧表示）将1只“超级量子士”怪兽作为此卡的超量素材。','\r',char(13)),'\n',char(10)),'魔陷破坏','增加素材','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85255550,'异国的剑士','受到此卡攻击的怪兽，将在５回合后的结束阶段时被破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85257384,'魅影骑士团愤恨披幕',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n自己场上或墓地存在“魅影骑士团”怪兽的情况下，此卡在放置的回合也可以发动。\r\n①：此卡发动后，变为通常怪兽（战士族・暗・星3・攻0/守300），以守备表示特殊召唤至怪兽区域（不视为陷阱卡）。然后，可将对手场上的1只攻击表示怪兽改成守备表示。\r\n②：将墓地的此卡除外可以发动。进行1只暗属性超量怪兽的超量召唤。','\r',char(13)),'\n',char(10)),'适用「魅影骑士团 本影烈焰剑苍骑」的效果来发动','超量召唤','是否改变表示形式？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85277313,'提斯蒂娜的胎动',replace(replace('①：以场上的１只表侧表示怪兽为对象可以发动此卡。发动后，变为拥有以下效果的效果怪兽（水族・光・星１０・攻／守０），特殊召唤至怪兽区域（也视为陷阱卡）。\r\n●对象的表侧表示怪兽在对手回合中从场上离开时，此卡将被破坏。此卡在对手回合中从场上离开时，对象的表侧表示怪兽将被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85289965,'枪管刺刀龙',replace(replace('效果怪兽3只以上\r\n①：此卡不会因战斗被破坏。\r\n②：在每个自己・对手回合中1次，以1只攻击表示的怪兽为对象可以发动（应对此效果的发动，对手不可发动卡的效果）。将该怪兽改成守备表示。此回合，此卡在1次战斗阶段中可攻击2次。\r\n③：1回合1次，此卡对表侧表示怪兽攻击宣言时可以发动。直至回合结束时为止，此卡的攻击力上升该怪兽攻击力一半的数值，该怪兽的攻击力变为一半。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85289966,'枪管刺刀龙',replace(replace('效果怪兽3只以上\r\n①：此卡不会因战斗被破坏。\r\n②：在每个自己・对手回合中1次，以1只攻击表示的怪兽为对象可以发动（应对此效果的发动，对手不可发动卡的效果）。将该怪兽改成守备表示。此回合，此卡在1次战斗阶段中可攻击2次。\r\n③：1回合1次，此卡对表侧表示怪兽攻击宣言时可以发动。直至回合结束时为止，此卡的攻击力上升该怪兽攻击力一半的数值，该怪兽的攻击力变为一半。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85306040,'格布林部队','①：此卡攻击的情况下，将在战斗阶段结束时变为守备表示，直至下个自己的回合结束时为止，不可变更表示形式。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85309439,'北风与太阳','关系很好的北风和太阳。使用风刃与热光线进行攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85310252,'怒怒怒车夫',replace(replace('①：此卡在以“怒怒怒”怪兽的效果被特殊召唤的回合的自己主要阶段，以自己场上的１只“怒怒怒”怪兽为对象，可从以下效果中选择１个发动。此效果１回合最多可使用２次。\r\n●对象怪兽的等级上升１。\r\n●对象怪兽的等级下降１。','\r',char(13)),'\n',char(10)),'等级变换','等级上升1星','等级下降1星','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85313220,'漆黑魔王 LV4','此卡因战斗破坏的对手怪兽的效果被无效化。此卡因战斗破坏怪兽的下一个我方回合的准备阶段时，可将此卡送入墓地并发动。从手牌、牌组特殊召唤１只“漆黑魔王 LV6。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85314178,'祈祷的女王－宇宙女皇',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：场地魔法卡发动的情况下可以发动。从手牌将此卡以守备表示特殊召唤。\r\n②：以场地区域的１张表侧表示卡为对象，根据其控制者可以发动以下效果。\r\n●自己：将对象卡破坏，从牌组将卡名与所破坏的卡不同的１张场地魔法卡加入手牌。\r\n●对手：将对象卡的效果直至回合结束时为止无效，从牌组将１张场地魔法卡加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85315450,'绚岚豪火 凤尼克斯',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：速攻魔法卡发动的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：速攻魔法卡发动的情况下，以对手场上的最多2张卡为对象可以发动。将该卡放回牌组。\r\n③：此卡存在于墓地的状态下，“气旋”发动的情况下可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','回到牌组','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85325774,'暗黑界的援军',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：以自己墓地1只等级4以下的恶魔族怪兽为对象可以发动。将该怪兽特殊召唤。然后，从手牌挑选1只恶魔族怪兽舍弃。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85326399,'尖刺海龙','用身上的尖刺攻击敌人，并能放出电流。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85327820,'-艾-爱之仪式','电子界族仪式怪兽降临所必须。①：为使合计等级为仪式召唤的怪兽以上，解放自己手牌・场上的“＠伊格尼斯者”怪兽，从手牌将1只电子界族仪式怪兽仪式召唤。发动时自己场上有“＠伊格尼斯者”怪兽存在的情况下，也可将自己墓地的“＠伊格尼斯者”怪兽除外作为解放的代替。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85346853,'光子龙圣骑士','由“流光龙降临”降临。可解放此卡并发动。从手牌・牌组特殊召唤１只“银河眼光子龙”。此外，此卡因战斗破坏对手怪兽并送入墓地时，从牌组抽取１张卡牌。','特殊召唤','抽牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85352446,'统制训练','选择对手场上的１只等级５以下的怪兽可以发动。将场上等级不同于所选择的怪兽的怪兽全部破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85359414,'冰岩魔兽','１回合１次，可在我方的主要阶段时，将此卡作为装备卡装备至我方的“灼岩魔兽”上，或者解除装备状态以表侧攻击表示特殊召唤此卡。以此效果变为装备卡的场合，在装备怪兽对对手生命造成战斗伤害时破坏场上１张被盖牌的魔法卡或陷阱卡。（１只怪兽最多只可装备１张联合。装备怪兽因战斗而被破坏的场合，破坏此卡来代替。）','装备','特殊召唤','破坏','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85360035,'双天拳之熊罴',replace(replace('此卡名的效果①②在1个回合中仅可各使用1次。\r\n①：可以以自己场上的1只“双天”怪兽为对象发动。破坏该怪兽，将牌组中的1张“双天”魔法卡加入手牌。\r\n②：在此卡存在于墓地的状态下，以效果怪兽为素材被融合召唤的自己场上表侧表示的“双天”融合怪兽因战斗或对手的效果被破坏的情况下可以发动。将此卡加入手牌中。','\r',char(13)),'\n',char(10)),'「双天」魔法卡加入手牌','此卡加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85374678,'超级量子士 绿层',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤时可以发动。从手牌将1只“超级量子”怪兽特殊召唤。\r\n②：此卡被送至墓地的情况下，从手牌将1张“超级量子”卡舍弃可以发动。自己抽1张。','\r',char(13)),'\n',char(10)),'特殊召唤','抽牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85395151,'洗脑解放',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：手牌・场上的怪兽被解放的情况下，以对手场上的1只表侧表示怪兽为对象可以发动。根据该表侧表示怪兽的原本的持有者适用以下效果。\r\n●自己：获得对象怪兽的控制权。以此效果获得控制权的怪兽将在结束阶段被放回手牌。\r\n●对手：将对象怪兽的效果直至回合结束时为止无效。','\r',char(13)),'\n',char(10)),'发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85399281,'智天使哈维斯特','①：此卡因战斗被破坏并送入墓地时，可以我方墓地的１张反制陷阱卡为对象发动。将该卡加入手牌。','加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85401123,'毛可毛可',replace(replace('此卡名的②③效果1回合仅可各使用1次。\r\n①：此卡与怪兽进行战斗的情况下，该2只不会因该战斗被破坏。\r\n②：在自己的主要阶段可以发动。将此卡改成里侧守备表示。\r\n③：此卡反转的情况下发动。自己抽1张。','\r',char(13)),'\n',char(10)),'变为里侧守备表示','抽牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85407683,'星罗的新世坏',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：只要自己场上存在“维萨思・史塔弗罗斯特”，自己的怪兽１回合各仅１次，不会因战斗被破坏。\r\n②：自己场上存在“维萨思・史塔弗罗斯特”的情况下，在自己的结束阶段，以自己墓地的１只怪兽为对象可以发动。将该怪兽放回牌组。自己场上存在同步怪兽的协调的情况下，也可不放回牌组而改为加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85431040,'邪恶荆棘','①：解放此卡可以发动。给予对手300伤害，可从牌组将最多2只“邪恶荆棘”以攻击表示特殊召唤。以此效果特殊召唤的怪兽不可发动效果。','伤害','是否要特殊召唤「邪恶荆棘」？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85442146,'龙之意志',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：自己场上存在原本攻击力或原本守备力为2500的怪兽，且怪兽的效果・魔法・陷阱卡发动时可以发动。将该发动无效并破坏。\r\n②：此卡存在于墓地的情况下，支付2500LP可以发动。将此卡放置在自己场上。以此效果放置的此卡从场上离开的情况下将被除外。','\r',char(13)),'\n',char(10)),'无效并破坏','放置','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85446833,'零零封锁','只要此卡存在于场上，对手怪兽不可将攻击力０的攻击表示怪兽选择为攻击对象。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85448931,'守海战士','彻底攻击污染海洋者的人鱼战士。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85457355,'变容王 狱胶',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下，以场上的1只其他的表侧表示怪兽为对象可以发动。此卡的等级改成与该怪兽相同，自己恢复该怪兽的等级×200的LP。此效果发动后，直至回合结束时为止，自己从额外牌组仅可特殊召唤同步怪兽。\r\n②：在自己的主要阶段可以发动。从手牌将1只等级低于此卡的恶魔族怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85463083,'鬼计食尸鬼',replace(replace('仅限我方场上存在有“鬼计”怪兽的场合，此卡可以表侧表示召唤。\r\n①：可在我方主要阶段发动。将此卡变成里侧守备表示。（１回合仅限１次）。\r\n②：可在我方主要阶段，以我方场上１只“鬼计”怪兽为对象发动１次。直至下一对手回合结束时，该怪兽的攻击力变成场上“鬼计”怪兽原本攻击力的合计数值，此回合不可攻击除了对象怪兽以外的怪兽。','\r',char(13)),'\n',char(10)),'变成里侧守备','攻击变换','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85475641,'无限狱复仇者','此卡存在于墓地，且我方场上除“无限狱复仇者”以外的怪兽，因与对手怪兽的战斗而被破坏并送入我方墓地时可发动。从墓地特殊召唤此卡。以此效果特殊召唤的此卡的等级变成与被破坏的我方怪兽的原本等级相同。此效果可在我方手牌是０张的场合发动与处理。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85489096,'武器召唤师','反转：将我方牌组中１张冠有“守护者”之名的卡牌加入到手牌中。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85497611,'异色眼巫师龙','①：此卡在手牌的情况下，解放自己场上的１只暗属性怪兽可以发动。从手牌・牌组及自己场上的表侧表示怪兽中挑选１只“异色眼龙”送至墓地，将此卡特殊召唤。②：此卡被对手破坏并被送至墓地的情况下可以发动。从自己牌组・墓地挑选“异色眼巫师龙”以外的１只“异色眼”怪兽特殊召唤。然后，可从牌组将１张“螺旋之强袭爆裂”加入手牌。','此卡特殊召唤','特殊召唤并检索','是否把「螺旋之强袭爆裂」加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85505315,'侵邪蚀 马蒂斯','释放冠有“侵邪蚀”之名怪兽并成功上级召唤此卡时，可支付１０００LP发动。选择我方墓地的１只冠有“侵入魔鬼”之名的怪兽并特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85507811,'元素－英雄 光辉新宇侠',replace(replace('“元素－英雄 新宇侠”＋“新空间人・光辉青苔”\r\n仅限我方场上的上述卡牌返回至持有者牌组的场合，可从额外牌组特殊召唤（不需要“融合”）。结束阶段时此卡返回至持有者的额外牌组。我方的主要阶段，仅１次可选择对手场上表侧表示的１张卡牌并破坏。根据被破坏卡牌的种类适用以下效果。\r\n●怪兽卡：此回合此卡不可攻击。\r\n●魔法卡：此回合此卡可直接攻击对手玩家。\r\n●陷阱卡：此卡变成守备表示。','\r',char(13)),'\n',char(10)),'返回牌组','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85519211,'岩盘爆破','给予对手LP自己怪兽区域上的“地雷魔像”数量×１０００点的伤害。然后，破坏自己场上的所有“地雷魔像”。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85520170,'铁屑神像',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：以自己墓地・除外状态的１只等级７・８的龙族同步怪兽为对象可以发动。将该怪兽特殊召唤。以此效果特殊召唤的怪兽将在结束阶段放回额外牌组。发动后此卡不会送往墓地，而是就此放置。\r\n②：被放置的此卡因对手的效果被破坏的情况下可以发动。从额外牌组将１只“赤龙”特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85520851,'超传导恐兽','①：１回合１次，解放自己场上的１只怪兽可以发动。给予对手１０００伤害。发动此效果的回合中，此卡不可攻击宣言。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85523502,'威斯卡・雷盟',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：在以自己的“雷盟”卡的效果破坏了卡的、自己・对手回合中，向对手出示手牌的此卡可以发动。从手牌将最多3只雷族怪兽特殊召唤。然后，可以其数量为上限，将场上的卡破坏。此回合，自己不可从手牌以外的地方特殊召唤效果怪兽。\r\n②：怪兽的效果在手牌以外发动时，将自己场上的1只其他的雷族怪兽放回手牌可以发动。将该发动无效并破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','发动无效','是否把卡破坏？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85528209,'超重魔兽 九尾－B',replace(replace('协调＋１只以上协调以外的“超重武者”怪兽\r\n此卡名在规则上也视为“超重武者”卡。①：此卡可在表侧守备表示的状态下攻击。该情况下，将此卡的守备力视为攻击力来进行伤害计算。②：自己的墓地不存在魔法・陷阱卡的情况下，此卡的守备力上升相当于对手场上被特殊召唤的怪兽数量×９００的数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85541675,'机偶解体新书','①：每次“机偶”怪兽的表示形式被变更时，在此卡上放１个机偶计数物（最多２个）。②：将放有机偶计数物的此卡送至墓地可以发动。依被放在此卡上的机偶计数物的数量，自己从牌组抽牌。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85545073,'魔玩具・剪刀熊',replace(replace('“锋利小鬼・剪刀”＋“绒毛动物・熊”\r\n①：此卡因战斗将对手怪兽破坏并送至墓地时可以发动。将该怪兽视为攻击力上升1000的装备卡装备于此卡。','\r',char(13)),'\n',char(10)),'装备','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85551711,'虚空的黑之魔导师',replace(replace('魔法师族等级7怪兽×2\r\n①：只要持有超量素材的此卡存在于怪兽区域，自己可在对手回合从手牌发动速攻魔法卡及陷阱卡。在该发动之际去除此卡的1个超量素材。\r\n②：超量召唤的此卡因对手的效果被送至墓地的情况下，或因战斗被破坏并被送至墓地的情况下可以发动。从手牌・牌组将1只魔法师族・暗属性怪兽特殊召唤。然后，可将场上的1张卡破坏。','\r',char(13)),'\n',char(10)),'是否选场上1张卡破坏？','','适用「虚空的黑之魔导师」的效果来发动','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85555787,'恶之牌组破坏病毒','①：解放自己场上１只攻击力３０００以下的暗属性怪兽可以发动。对手从自身的手牌・牌组挑选卡破坏，破坏的卡的数量为该怪兽的攻击力除以５００的整数位数值。为发动此卡解放攻击力２０００以上的怪兽的情况下，以对手回合为准３个回合期间，确认对手所抽的所有卡，将其中的怪兽全部破坏。此外，因此卡的效果被破坏并被送至墓地的卡在被破坏的回合不可发动效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85562745,'恶梦的拷问室','①：每次对手因“恶梦的拷问室”以外的卡片的效果受到伤害时发动。给予对手３００点伤害。','给对手300伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85586937,'威咖杯！格雷',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：此卡存在于手牌的情况下可以发动。从自己手牌挑选1只其他的反转怪兽并舍弃，将此卡以表侧攻击表示或里侧守备表示特殊召唤。\r\n②：此卡反转的情况下可以发动。以自己场上的反转怪兽数量为上限，将对手场上的表侧表示卡送至墓地。\r\n③：在自己的结束阶段，以自己墓地的1只反转怪兽为对象可以发动。将该怪兽以里侧守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','送至墓地','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85590798,'神圣降诞',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：在自己的主要阶段可以发动。将手牌的１只天使族・光属性怪兽出示给对手，从牌组将１只龙族・光属性・等级７怪兽加入手牌。然后将所出示的怪兽放回牌组最下面。\r\n②：对手发动魔法・陷阱・怪兽的效果的情况下可以发动。从手牌将１只龙族・光属性・等级７怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','从手牌特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85602018,'遗言状','此回合自己场上的怪兽被送至自己墓地的情况下，该回合仅限１次，可以从牌组中特殊召唤１只攻击力１５００以下的怪兽。','是否要使用「遗言状」的效果？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85605684,'狂暴死亡龙','此卡不可通常召唤。仅限以“与恶魔的交涉”的效果可特殊召唤。此卡可对全部对手怪兽各发动１次攻击。每次我方结束阶段，此卡的攻击力下降５００点。','攻击下降','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85636437,'土俵间际','①：自己的LP少于对手的情况下，以对手场上的１只表侧表示怪兽为对象可以发动。给予对手该怪兽原本攻击力一半数值的伤害。此卡发动后，直至回合结束时为止，对手受到的所有伤害变为０。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85638822,'刚鬼死斗','①：作为此卡发动时的效果处理，在此卡上放3个计数物。②：自己的“刚鬼”怪兽战斗破坏对手怪兽的情况下发动。去除此卡的1个计数物。③：被放在此卡上的计数物因此卡的效果被全部去除的战斗阶段结束时，自己可以发动此效果。从手牌・牌组尽可能将“刚鬼”怪兽特殊召唤（同名卡最多1张）。然后在此卡上放3个计数物。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85639257,'水魔道士','操纵水的魔法师，造出厚重的水墙压垮敌人。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85640370,'舌尖短少',replace(replace('①：对手发动宣言1个卡名来发动的效果时可以发动。将该效果无效。然后，自己可从牌组将1张被宣言的卡加入手牌。\r\n②：被放置的此卡因对手的效果被破坏的情况下，以对手场上的1只表侧表示怪兽为对象可以发动。该怪兽的攻击力下降500。','\r',char(13)),'\n',char(10)),'效果无效','攻击力降低','是否加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85646474,'守墓的使者','此卡因对手怪兽的攻击被破坏并送入墓地时，可从牌组以里侧守备表示特殊召唤１只除“守墓的使者”以外冠有“守墓”之名的怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85651167,'真红眼铁骑士－机亚弗里德','①：１回合１次，此卡被装备装备卡的情况下可以发动。将该装备卡破坏。然后，可挑选对手场上的１张魔法・陷阱卡破坏。②：１回合１次，将自己场上１张装备于此卡的装备卡送至墓地，以自己墓地的１只等级７以下的“真红眼”怪兽为对象可以发动。将该怪兽特殊召唤。','装备卡破坏','特殊召唤','是否选对手场上1张魔法·陷阱卡破坏？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85668449,'脑开发研究所',replace(replace('①：只要此卡存在于场地区域，双方玩家在通常召唤之外，可在自身的主要阶段追加1次召唤1只念动力族怪兽。每当有念动力族怪兽以此方法被召唤，在此卡上放1个精神计数物。\r\n②：要为发动自己场上的念动力族怪兽的效果而支付LP的情况下，作为代替可在此卡上放1个精神计数物。\r\n③：此卡从场上离开时，自己受到放在此卡上的精神计数物的数量×1000的伤害。','\r',char(13)),'\n',char(10)),'给「脑开发研究所」放置1个「念力计数物」','使用「脑开发研究所」的效果召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85672957,'假面－英雄 原子',replace(replace('此卡仅可通过“假面变换”的效果特殊召唤。\r\n此卡名的①③效果1回合仅可各使用1次。\r\n①：此卡特殊召唤的情况下，以炎属性以外的、自己墓地・除外状态的1只“假面－英雄”怪兽为对象可以发动。将该怪兽无视召唤条件以守备表示特殊召唤。\r\n②：此卡1回合仅1次，不会因战斗・效果被破坏。\r\n③：在自己的结束阶段，以自己墓地的1张“变换”速攻魔法卡为对象可以发动。将该卡放置在自己场上。','\r',char(13)),'\n',char(10)),'特殊召唤','','放置','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85673903,'幻变骚灵・警告菲溺尔','此卡名的效果1回合仅可使用1次。①：此卡存在于手牌、“幻变骚灵”连接怪兽被连接召唤至自己场上时，以该怪兽以外的场上的1只连接怪兽为对象可以发动。将此卡特殊召唤至对象怪兽连接端的自己场上。此回合，对象怪兽也视为“幻变骚灵”怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85679527,'宇宙智囊','此卡不可通常召唤。从手牌及自己场上的表侧表示怪兽中，将效果怪兽以外的1只怪兽送至墓地的情况下可以特殊召唤。此卡名的②效果1回合仅可使用1次。①：此卡的攻击力上升相当于为特殊召唤此卡送至墓地的怪兽等级×200的数值。②：解放自己场上的1只效果怪兽可以发动。从手牌・牌组将1只通常怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85682655,'发条杂耍人','此卡可在与对手怪兽进行战斗的伤害计算后发动。破坏该对手怪兽。只要此卡以表侧表示存在于场上，此效果只可使用１次。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85684223,'驱使梦魇的死灵',replace(replace('“削魂的死灵”＋“梦魇马”\r\n①：此卡不会因战斗被破坏。②：此卡可直接攻击。③：此卡以直接攻击给予对手战斗伤害的情况下发动。随机挑选对手的１张手牌舍弃。④：场上表侧表示的此卡成为效果的对象的情况下将被破坏。','\r',char(13)),'\n',char(10)),'丢弃手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85687952,'原始生命态提亚',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：在自己・对手的主要阶段，为使合计等级达到11以上，解放自己场上的怪兽可以发动。从手牌将此卡特殊召唤。然后，自己场上不存在其他怪兽的情况下，可将场上攻击力最高的1只怪兽破坏。\r\n②：只要此卡存在于怪兽区域，在此期间，双方1回合仅可召唤・特殊召唤怪兽最多4次。','\r',char(13)),'\n',char(10)),'特殊召唤','是否破坏怪兽？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85692042,'块斩机达朗贝尔算子',replace(replace('等级４怪兽×２只以上\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡超量召唤的情况下，依以下数量去除此卡的超量素材，可以发动相应效果。\r\n●２个：从牌组将１张“斩机”卡加入手牌。\r\n●３个：从牌组将１只等级４怪兽加入手牌。\r\n●４个：从牌组将１张魔法・陷阱卡加入手牌。\r\n②：解放自己场上的１只怪兽可以发动。从自己的手牌・墓地将１只等级４的“斩机”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'2个：检索「斩机」卡','3个：检索4星怪兽','4个：检索魔法·陷阱卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85696777,'神鹰指挥者',replace(replace('风属性怪兽２只\r\n此卡名的②③效果１回合仅可各使用１次。①：此卡只要存在于场上・墓地，卡名视为“神鹰女郎”。②：自己场上的“神鹰”怪兽将被战斗・效果破坏的情况下，可破坏自己场上的１张魔法・陷阱卡作为代替。③：自己场上此卡以外的表侧表示“神鹰”怪兽被放回自己手牌的情况下，以对手场上１只被特殊召唤的怪兽为对象可以发动。将该怪兽放回持有者的手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85698115,'幽世断离',replace(replace('①：以对手墓地的１只怪兽为对象可以发动。将该怪兽特殊召唤至对手场上。然后，可将对手场上的１只怪兽除外。该情况下，进而将对手１只除外状态的怪兽放回墓地。\r\n②：从墓地将不是在此回合被送至墓地的此卡除外，以自己墓地的１只等级１怪兽为对象可以发动。将该怪兽放回牌组。然后，可从牌组将“常世断离”、“现世断离”、“幽世断离”中的任意１张放置在自己场上。','\r',char(13)),'\n',char(10)),'是否选怪兽除外？','是否从牌组放置？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85704698,'再生骰子',replace(replace('①：以自己墓地的１只“疾行机人”协调为对象可以发动。将该怪兽的效果无效并特殊召唤，摇１次骰子。该特殊召唤的怪兽的等级直至回合结束时为止变为与摇出的数字相同。\r\n②：将墓地的此卡除外可以发动。以自己场上的包含“疾行机人”协调在内的怪兽作为素材，将１只风属性同步怪兽同步召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85705804,'鸭人','尾巴很长的鸟，会利用尾巴从空中发起攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85709845,'鲁莽行事','我方场上的守备表示怪兽被选择为攻击对象时可发动。该守备表示怪兽变成表侧攻击表示。并且，因该战斗破坏攻击怪兽并送入墓地时，给予对手生命相当于该怪兽原本攻击力数值的伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85718645,'暗帝迪尔格','①：此卡召唤・特殊召唤成功时，以对手墓地的最多2张卡为对象可以发动。将该卡除外。然后，将除外张数的卡从对手牌组上面送至墓地。②：此卡召唤・特殊召唤的回合不可攻击。','把对手墓地存在的最多2张卡从游戏中除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85742772,'重力绑定－超重力网－','只要此卡存在于场上，等级４以上的怪兽不可攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85747929,'银河光子龙',replace(replace('等级４怪兽×２\r\n此卡名的②③效果１回合仅可各使用１次。①：自己场上此卡以外的光属性怪兽的攻击力上升５００。②：去除此卡的１个超量素材可以发动。从牌组挑选１张“光子”卡或“银河”卡，加入手牌或送至墓地。③：光属性怪兽被特殊召唤至自己场上的情况下，以该１只被特殊召唤的怪兽为对象可以发动。将该怪兽的等级直至回合结束时为止改成４或８。','\r',char(13)),'\n',char(10)),'','改变等级','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85753549,'月牙龙－新月龙',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡存在于手牌・墓地的情况下，在自己・对手的结束阶段可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，放回牌组最下面。\r\n②：舍弃1张手牌可以发动。从牌组将1只龙族・暗属性・等级7怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85754829,'异虫古鲁斯','每次场上的里侧守备表示怪兽反转，放置１个异虫计数物在此卡。此卡的攻击力上升此卡的异虫计数物数量×３００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85758066,'机械装置魔镜',replace(replace('①：对手怪兽攻击宣言时，以对手墓地的１张魔法卡为对象可以发动。将该卡放置在自己场上。\r\n②：将墓地的此卡除外，从放置在手牌及自己场上的卡中，将１张“死者苏生”送至墓地可以发动。从自己的墓地挑选１只“欧贝利斯克之巨神兵”，以守备表示特殊召唤。在对手回合发动此效果的情况下，只要此回合以此效果特殊召唤的怪兽存在于自己场上，可攻击的对手怪兽必须攻击该怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85763457,'响彻于星遗物的残叫','此卡名的卡1回合仅可发动1张。①：自己场上有相互连接状态的怪兽存在，对手发动怪兽的效果・魔法・陷阱卡时可以发动。将该发动无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85766789,'宝玉之祝福',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：挑选自己的魔法与陷阱区域的最多２张“宝玉兽”怪兽卡特殊召唤，依其原本攻击力的合计数值恢复自己的LP。\r\n②：此卡存在于墓地的状态下，自己的魔法与陷阱区域放入“宝玉兽”卡的情况下，将此卡除外可以发动（伤害步骤也可发动）。翻开自己牌组最上面的卡，其为“宝玉兽”怪兽的情况下，将该怪兽加入手牌或特殊召唤。不是的情况下，将该卡送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85771019,'堕天使 阿斯蒙德斯','此卡不可从牌组・墓地特殊召唤。①：1回合1次，在自己主要阶段可以发动。从牌组将1只天使族怪兽送至墓地。②：自己场上的此卡被破坏并被送至墓地的情况下发动。将1只“阿斯蒙衍生物”（天使族・暗・星5・攻1800/守1300）和1只“德斯衍生物”（天使族・暗・星3・攻/守1200）特殊召唤至自己场上。“阿斯蒙衍生物”不会因效果被破坏。“德斯衍生物”不会因战斗被破坏。','把1只天使族怪兽送至墓地','特殊召唤衍生物','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85771020,'阿斯蒙衍生物','由“堕天使 阿斯蒙德斯”的效果特殊召唤而来。此衍生物不会被卡片的效果破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85771021,'阿斯蒙衍生物','由「堕天使 阿斯蒙德斯」的效果特殊召唤。「蒂斯衍生物」不会被战斗破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85775486,'再机动','可从我方手牌将１只冠有“机皇”之名的怪兽返回至牌组并发动。从我方墓地选择１张冠有“机皇”之名的卡牌并加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85787173,'次一世代',replace(replace('此卡牌名的卡牌１回合只可发动１张。\r\n①：我方的LP少于对手的场合可发动。从我方牌组、墓地挑选持有攻击力是双方LP差额或以下的“元素－英雄”怪兽、“库里波”怪兽、“新空间人”怪兽中的任意１只加入手牌或特殊召唤。此回合，我方不可发动该卡及该同名卡的效果。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85800949,'传说骑士 克里底亚',replace(replace('此卡不可通常召唤。\r\n仅可以“传说之心”的效果特殊召唤。\r\n①：此卡特殊召唤成功时，可以场上表侧表示的１张魔法、陷阱卡为对象发动。将该表侧表示的魔法、陷阱卡除外。\r\n②：此卡被选择为攻击对象时，可以我方墓地的１张陷阱卡为对象发动。将该卡牌盖牌至我方场上。以此效果盖牌的卡牌在盖牌回合也可发动。','\r',char(13)),'\n',char(10)),'','','适用「传说骑士 克里底亚」的效果来发动','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85802526,'人鱼公主','只要此卡以表侧表示存在于我方场上，每次我方的准备阶段，我方回复８００LP。','回复','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85808813,'时间之流',replace(replace('①：可以以自己场上的1只“化石”融合怪兽为对象发动。解放该怪兽，作为由“化石融合”进行的融合召唤，从额外牌组特殊召唤1只原本等级高于该怪兽2级的“化石”融合怪兽。\r\n②：从自己的墓地除外此卡与1只“化石”融合怪兽后，可以以自己墓地的1只“化石”融合怪兽为对象发动。特殊召唤该怪兽。此效果在此卡被送至墓地的回合不可发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85821180,'协调快速','①：可从手牌舍弃１只怪兽并发动。从牌组特殊召唤１只与该怪兽同种族、属性且等级高１级的协调。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85827713,'鬼计之夜','①：只要场上存在“鬼计”怪兽，对手场上的怪兽不可反转召唤。②：此卡被对手破坏并被送至墓地的情况下发动。此回合对手不可攻击宣言。','不可攻击宣言','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85839825,'超量能量','可移除我方场上的１个超量素材并发动。选择对手场上的１只表侧表示怪兽并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85840608,'新宇空间连结者','此卡名的①②效果１回合仅可各使用１次。①：此卡召唤成功时可以发动。从手牌・牌组将１只“新空间人”怪兽或“元素－英雄 新宇侠”以守备表示特殊召唤。②：解放此卡，以自己墓地的１只“新空间人”怪兽或“元素－英雄 新宇侠”为对象可以发动。以守备表示形式将该怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85847157,'证明之普鲁弗拉斯',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：自己场上不存在被特殊召唤的怪兽的情况下可以发动。从手牌将此卡特殊召唤。此效果发动后，直至回合结束时为止自己不可特殊召唤怪兽。\r\n②：此卡召唤・特殊召唤的情况下可以发动。进行1只怪兽的上级召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85852291,'万宝槌','①：将任意数量的自己手牌放回牌组。然后，自己依放回牌组的数量抽牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85854214,'英雄规则２','以墓地的卡牌为对象怪兽的效果、魔法、陷阱卡发动时可发动。使该发动无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85862791,'同盗相窃',replace(replace('此卡名的卡片１回合只可发动１张。\r\n①：我方及对手场上的卡片同时被战斗／效果破坏时可发动。双方玩家各从卡组抽２张卡。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85876417,'正义盟军 千械鬼','此卡可向对手场上的所有光属性怪兽各攻击１次。此卡与除光属性以外的怪兽战斗的场合，在该伤害计算前破坏此卡。','此卡破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85888377,'淀神 阿波菲斯','①：在自己・对手的主要阶段可以发动此卡。此卡变为通常怪兽（爬虫类族・地・星6・攻2000/守2200），特殊召唤至怪兽区域（也视为陷阱卡）。然后，自己场上存在其他永续陷阱卡的情况下，可最多依其数量将对手场上的表侧表示卡的效果直至回合结束时为止无效。','是否选对手的卡无效？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85893201,'连锁诱爆','１回合１次，此卡存在于场上，且对手场上的怪兽因对手的卡牌效果被破坏的场合，可发动。选择场上的１张卡牌破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85899505,'合体魔龙 提玛欧斯',replace(replace('“黑魔导”或“黑魔导女孩”＋龙族・魔法师族怪兽\r\n此卡名的②③效果1回合仅可各使用1次。\r\n①：此卡特殊召唤时适用。直至下个自己回合结束时为止，此卡不受其他卡的效果影响。\r\n②：此卡进行战斗的伤害计算时可以发动。此卡的攻击力上升双方墓地・除外状态的魔法卡数量×100的数值。\r\n③：在对手回合中，以场上的1张魔法・陷阱卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'上升攻击力','破坏','「合体魔龙 提玛欧斯」效果适用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85908279,'召唤兽 科库托斯',replace(replace('“召唤师 阿莱斯特”＋水属性怪兽\r\n①：场上的此卡不会成为对手效果的对象，也不会因对手的效果而被破坏。②：此卡可在表侧守备表示的状态下攻击。该情况下，适用攻击力数值进行伤害计算。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85909450,'神鹰的宠物幻龙',replace(replace('风属性等级４怪兽×３\r\n若此卡没有超量素材，此卡的效果便不会适用。①：此卡可直接攻击。②：只要此卡存在于怪兽区域，对手不可将“神鹰”怪兽选择为攻击对象，也不可作为效果的对象。③：在自己的结束阶段发动。去除此卡的１个超量素材。','\r',char(13)),'\n',char(10)),'取除素材','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85914562,'魔救探索者','此卡名的①②效果1回合仅可各使用1次。①：自己场上存在“魔救探索者”以外的岩石族怪兽的情况下可以发动。从手牌将此卡特殊召唤。②：自己的主要阶段可以发动。从自己牌组上面翻开5张卡。可以从其中挑选1只协调以外的等级4以下的岩石族怪兽进行特殊召唤。剩下的卡以喜欢的顺序放回牌组最下面。','','','是否特殊召唤怪兽？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85936485,'团结的抗争','人们团结在一起，誓言要对抗强大的力量。革命之日指日可待。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85967160,'芬芳法师－蜂香薄荷',replace(replace('①：只要自己的LP多于对手，且此卡存在于怪兽区域，自己的植物族怪兽攻击了守备表示的怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。\r\n②：１回合１次，自己的LP恢复的情况下发动。此卡的攻击力・守备力直至对手回合结束时为止上升１０００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85969517,'海造贼－庄重之大地号',replace(replace('←1 【灵摆】 1→\r\n此卡名的灵摆效果１回合仅可使用１次。\n①：宣言１个属性可以发动。将此卡放回持有者的额外牌组，将拥有所宣言属性的“海造贼衍生物”（恶魔族・星４・攻／守０）各１只以守备表示特殊召唤至双方场上。\r\n【怪兽效果】\r\n协调＋１只以上协调以外的怪兽\n此卡名的①②怪兽效果１回合仅可各使用１次。\n①：对手特殊召唤怪兽成功的情况下可以发动。从牌组将１张“海造贼”卡加入手牌。此卡有装备“海造贼”卡的情况下，进而可从牌组将１只“海造贼”怪兽特殊召唤。\n②：以自己墓地的１张“海造贼”卡为对象可以发动。将该卡加入手牌，将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'','从牌组把1张「海造贼」卡加入手牌','是否再从牌组把1只「海造贼」怪兽特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85969518,'海造贼衍生物','以“海造贼－庄重之大地号”的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85970321,'妖仙兽 饭纲鞭',replace(replace('此卡牌名的①②效果１回合只可各使用１次。\r\n①：可将此卡从手牌舍弃并发动。此回合，“妖仙兽”怪兽召唤、特殊召唤成功时，对手不可发动魔法、陷阱、怪兽效果。\r\n②：我方场上存在有其他“妖仙兽”怪兽的场合可发动。我方从牌组抽取１张卡牌。\r\n③：在召唤此卡回合的结束阶段发动。将此卡返回至持有者手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85976588,'耀圣之月诗 福尔图娜',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次，且②③效果1回合仅可各使用1次。\r\n①：此卡可从手牌特殊召唤至自己中央的主要怪兽区域。\r\n②：在自己的主要阶段可以发动。从手牌・牌组将1张“耀圣”永续陷阱卡以表侧表示放在自己场上。\r\n③：在对手回合中可以发动。将自己的主要怪兽区域的、此卡和中央的怪兽的位置交换。然后，可将场上的1张表侧表示的魔法・陷阱卡放回手牌。','\r',char(13)),'\n',char(10)),'放置陷阱','交换位置','是否让魔陷回到手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(85991529,'星际仙踪－暗黑行星',replace(replace('此卡不可通常召唤。\r\n仅可在为使等级合计为１０以上，将手牌的“星际仙踪”怪兽除外的情况下特殊召唤。\r\n①：此卡不会成为对手效果的对象。\r\n②：魔法卡发动时，从自己墓地将１只“星际仙踪”怪兽除外可以发动。将该发动无效并破坏。\r\n③：此卡因战斗・效果被破坏并被送至墓地的情况下，将墓地的此卡除外可以发动。从牌组将１只等级９以下的“星际仙踪”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'发动无效并破坏','从牌组把「星际仙踪」怪兽加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86013171,'星际仙踪－胆怯狮',replace(replace('“星际仙踪－胆怯狮”的①效果１回合仅可使用１次。\r\n①：将场上的此卡除外可以发动。从手牌将１只等级３以上的“星际仙踪”怪兽特殊召唤。此效果在对手回合中也可以发动。\r\n②：１回合１次，支付５００LP，以自己３只被除外的“星际仙踪”怪兽为对象可以发动。将该怪兽放回墓地，给予对手５００伤害。','\r',char(13)),'\n',char(10)),'从手牌把「星际仙踪」怪兽特殊召唤','除外的「星际仙踪」怪兽回到墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86016245,'弱者的意志','我方手牌为０张的场合，我方场上存在的等级２或以下的怪兽因战斗破坏对手怪兽并送入墓地时，从我方牌组抽取２张卡牌。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86028783,'新锐女战士',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己的其他战士族怪兽与对手的表侧表示怪兽进行战斗的攻击宣言时，将手牌・场上的此卡送至墓地可以发动。该对手怪兽的攻击力直至回合结束时为止，下降相当于其原本攻击力的数值。\r\n②：将墓地的此卡除外，以自己墓地的１只战士族・地属性怪兽为对象可以发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86038337,'密林狩猎者弗赞',replace(replace('战士族・地属性怪兽×2\r\n此卡名的②效果1回合仅可使用1次。\r\n①：此卡只要存在于怪兽区域，在自己・对手的主要阶段期间，不受对手发动的效果影响。\r\n②：在自己・对手的战斗阶段中，解放融合召唤的此卡可以发动。\r\n从自己墓地将“密林狩猎者弗赞”以外的2只战士族・地属性怪兽特殊召唤，此回合中，自己的战士族・地属性怪兽不会因战斗被破坏。','\r',char(13)),'\n',char(10)),'','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86039057,'帮一把骑士','此卡存在于墓地，自己的手牌为０张的情况下，在对手怪兽攻击宣言时可以发动。将此卡特殊召唤，然后结束战斗阶段。“帮一把骑士”的效果在决斗中仅可使用１次。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86049351,'最终反击','①：自己的“燃烧拳斗士”怪兽与对手怪兽进行战斗的攻击宣言时可以发动。使该攻击无效，将该自己的怪兽送至墓地，自己场上的１只“燃烧拳斗士”怪兽的攻击力上升相当于该对手的怪兽原本攻击力的数值，与该对手怪兽进行战斗并进行伤害计算。然后，自己受到相当于以此效果上升的攻击力数值的伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86060749,'失速转向',replace(replace('①：从自己的牌组上面将３张卡以里侧表示除外，可以发动以下效果。\r\n●将怪兽的召唤・反转召唤・特殊召唤无效的怪兽效果・魔法・陷阱卡发动时可以发动。将该发动无效，将该卡放回持有者的牌组。\r\n●将魔法・陷阱卡的发动无效的怪兽效果・魔法・陷阱卡发动时可以发动。将该发动无效，将该卡放回持有者的牌组。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86062400,'超量复仇者',replace(replace('此卡不受超量怪兽的效果影响。此外，此卡因与超量怪兽的战斗被破坏并被送至墓地时，根据破坏此卡的超量怪兽的阶级，发动以下效果。\r\n●阶级３以下：对手挑选额外牌组的１张卡送至墓地。\r\n●阶级４：自己挑选对手的额外牌组的１张卡送至墓地。\r\n●阶级５以上：对手依该超量怪兽的阶级数值，挑选额外牌组的卡送至墓地。','\r',char(13)),'\n',char(10)),'额外送墓','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86066372,'访问码语者',replace(replace('效果怪兽2只以上\r\n应对此卡效果的发动，对手不可发动效果。\r\n①：此卡连接召唤的情况下，以1只作为连接素材的连接怪兽为对象可以发动。此卡的攻击力上升相当于该怪兽连接标记的数量×1000的数值。\r\n②：从自己场上・墓地将1只连接怪兽除外可以发动。将对手场上的1张卡破坏。此回合，不可为发动自己的“访问码语者”的效果而将相同属性的怪兽除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86066373,'访问码语者',replace(replace('效果怪兽2只以上\r\n应对此卡效果的发动，对手不可发动效果。\r\n①：此卡连接召唤的情况下，以1只作为连接素材的连接怪兽为对象可以发动。此卡的攻击力上升相当于该怪兽连接标记的数量×1000的数值。\r\n②：从自己场上・墓地将1只连接怪兽除外可以发动。将对手场上的1张卡破坏。此回合，不可为发动自己的“访问码语者”的效果而将相同属性的怪兽除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86088138,'耳天使','以其大耳与大眼监视周围、外表恐怖的天使。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86098176,'爆裂巫妖',replace(replace('此卡名的①③效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从自己墓地将1只记载有“爆裂模式”卡名的怪兽或等级4以下的不死族怪兽特殊召唤。\r\n②：要以自己场上的此卡作为同步素材的情况下，可将此卡视为协调以外的怪兽。\r\n③：此卡作为同步素材被送至墓地的情况下可以发动。从牌组将1张“爆裂横扫”或“爆裂反击”加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86099788,'异星的最终战士',replace(replace('“暗黑英雄 尸魔侠”＋“魔力吸收球体”\r\n①：此卡特殊召唤的情况下发动。将自己场上的其他怪兽全部破坏。\r\n②：只要此卡存在于怪兽区域，双方不可召唤・反转召唤・特殊召唤怪兽。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86100785,'区域吞食者','受到此卡攻击的怪兽，将在５回合后的结束阶段被破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86111442,'提斯蒂娜的哨兵',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡存在于手牌・墓地，且自己场上存在光属性“提斯蒂娜”怪兽的情况下可以发动。将此卡特殊召唤。\r\n②：以自己场上的１只“提斯蒂娜”怪兽或１张里侧表示卡为对象可以发动。将该卡破坏。然后，从牌组将１张“提斯蒂娜”卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86120751,'召唤师 阿莱斯特',replace(replace('①：在自己・对手回合中，从手牌将此卡送至墓地，以自己场上的1只融合怪兽为对象可以发动。该怪兽的攻击力・守备力直至回合结束时为止上升1000。\r\n②：此卡召唤・反转的情况下可以发动。从牌组将1张“召唤魔术”加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86120752,'召唤师 阿莱斯特',replace(replace('①：在自己・对手回合中，从手牌将此卡送至墓地，以自己场上的1只融合怪兽为对象可以发动。该怪兽的攻击力・守备力直至回合结束时为止上升1000。\r\n②：此卡召唤・反转的情况下可以发动。从牌组将1张“召唤魔术”加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86124104,'终焉之魔鬼 迪米斯',replace(replace('以“世界不灭”降临\r\n①：此卡只要存在于手牌・场上，卡名视为“终焉之王 迪米斯”。\r\n②：此卡仪式召唤的情况下发动。将场上的1只表侧表示怪兽破坏。\r\n③：此卡被送至墓地的情况下，以自己场上的1只仪式怪兽为对象可以发动。只要该怪兽以表侧表示存在于自己场上，应对自己的仪式怪兽的效果的发动，对手不可发动卡的效果。','\r',char(13)),'\n',char(10)),'','','「终焉之魔鬼 迪米斯」效果适用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86132414,'三幻魔之神渊',replace(replace('此卡名的①③效果1回合仅可各使用1次。\r\n①：在自己・对手的主要阶段可以发动。从自己手牌・牌组・墓地将2张“三幻魔之神渊”以表侧表示放在自己场上。\r\n②：将自己场上包含此卡在内的3张表侧表示的“三幻魔之神渊”送至墓地，以对手场上的1只表侧表示怪兽为对象可以发动。将该怪兽改成里侧守备表示。\r\n③：此卡存在于墓地的情况下，在对手的结束阶段可以发动。将此卡放回牌组最下面。','\r',char(13)),'\n',char(10)),'表侧表示放置','变成里侧守备表示','回到牌组','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86133013,'等级抗蚀墙','此卡名的卡1回合仅可发动1张。①：自己场上的怪兽因战斗或对手的效果被破坏的情况下，以1只该怪兽为对象可以发动。为使等级合计与该怪兽相同，从牌组挑选任意数量的怪兽以守备表示特殊召唤。以此效果特殊召唤的怪兽的效果无效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86137485,'地狱双警',replace(replace('恶魔族协调＋协调以外的怪兽１只或以上\r\n①：此卡因战斗破坏对手怪兽并送入墓地时可发动，直至战斗阶段结束时，此卡的攻击力上升８００，并可连续攻击仅１次。','\r',char(13)),'\n',char(10)),'连续攻击','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86148577,'守护龙 希露比',replace(replace('等级4以下的龙族怪兽1只\r\n自己1回合仅可特殊召唤“守护龙 希露比”1次，其②效果1回合仅可使用1次。①：只要此卡存在于怪兽区域，自己仅可特殊召唤龙族怪兽。②：在自己的主要阶段可以发动。从手牌・牌组将1只龙族怪兽特殊召唤至作为2只以上连接怪兽共同的连接端的自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86154370,'高速疾行机人 遥控清透翼骑手',replace(replace('风属性协调＋1只协调以外的风属性同步怪兽\r\n①：1回合1次，在自己的主要阶段可以发动。掷1次骰子。挑选自己墓地的风属性怪兽放回牌组，数量最多为掷出的数字。然后，可以挑选对手场上的卡破坏，数量最多为放回的数量。此卡的攻击力直至回合结束时为止，上升相当于以此效果破坏的数量×500的数值。②：在对手的主要阶段，解放同步召唤的此卡可以发动。从额外牌组将最多2只等级7的风属性同步怪兽特殊召唤（同名卡最多1张）。','\r',char(13)),'\n',char(10)),'回牌组并破坏','特殊召唤','是否选对手的卡破坏？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86157908,'娱乐伙伴异色眼独角兽',replace(replace('←8 【灵摆】 8→\r\n①：此卡在灵摆区时仅限１次。我方的“异色眼”怪兽进行攻击宣告时，可以１只该怪兽以外我方场上的“娱乐伙伴”怪兽为目标发动。将该攻击怪兽的攻击力提升等同于目标怪兽原攻击力的数值，直到战斗阶段结束。\r\n【怪兽效果】\r\n①：此卡召唤或特殊召唤成功时，可以我方墓地的１只“娱乐伙伴”怪兽为目标发动。我方恢复LP，数值等同于该怪兽的攻击力。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86164529,'水龙','“妖精龙”＋“海原的女战士”＋“区域吞食者”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86165817,'邪恶－英雄 极恶亡魔',replace(replace('“邪恶－英雄”怪兽＋等级5以上的怪兽\r\n此卡仅可以“黑暗结合”的效果特殊召唤。\r\n此卡名的②效果1回合仅可使用1次。\r\n①：场上的此卡不会因战斗・效果被破坏。\r\n②：在自己的主要阶段可以发动。将对手场上攻击力在此卡攻击力以下的怪兽全部破坏，此卡的攻击力上升相当于所破坏怪兽数量×200的数值。此效果发动后，直至回合结束时为止，自己仅可用“－英雄”怪兽进行攻击宣言。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86170989,'大刀贝塔',replace(replace('①：在此卡因战斗破坏了对手怪兽的情况下，从以下效果中选择1个发动。\r\n●将牌组中1只攻击力为1200以下的机械族・光属性怪兽送至墓地。\r\n●可以自己墓地的1只攻击力为1200以下的机械族・光属性怪兽为对象发动。将该机械族・光属性怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'选择一个效果发动','牌组怪兽送至墓地','墓地怪兽特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86174055,'尖嘴鸟','此卡因战斗被破坏并送入墓地时，可选择２只我方墓地的等级２的怪兽特殊召唤。以此效果特殊召唤的怪兽效果被无效化。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86188410,'元素－英雄 狂野人','①：此卡只要存在于怪兽区域，不受陷阱卡的效果影响。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86196216,'升阶魔法－死亡双力','①：以在此回合因战斗被破坏并被送至自己墓地的1只“急袭猛禽”超量怪兽为对象可以发动。将该怪兽特殊召唤，将1只阶级为该怪兽两倍的超量怪兽重叠在对象怪兽上面，视为超量召唤从额外牌组特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86197239,'无限狱幻象','此卡不可从墓地特殊召唤。我方手牌是０张的场合，可释放此卡，并选择我方墓地２只冠有“无限狱”之名的怪兽并发动。特殊召唤被选择怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86198326,'卡牌７','仅限装备机械族怪兽。装备怪兽的攻击力或守备力上升７００点。','攻击力上升７００','守备力上升７００','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86209650,'迷走魔鬼','此卡因战斗破坏被送入墓地时，双方回复８００LP。','回复','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86221741,'急袭猛禽－究极猎鹰',replace(replace('鸟兽族等级10怪兽×3\r\n①：此卡不受其他卡的效果影响。②：去除此卡的1个超量素材可以发动。此回合，对手场上的怪兽的攻击力下降1000，对手不可发动卡的效果。③：此卡持有“急袭猛禽”怪兽作为超量素材的情况下，获得以下效果。\r\n●在每次双方的结束阶段可以发动。对手场上所有怪兽的攻击力下降1000。对手场上不存在表侧表示怪兽的情况下，给予对手1000伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86223870,'等级重协调','选择我方场上的１只表侧表示怪兽，将该等级下降最多２级。','等级下降１星','等级下降２星','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86229493,'暗冥之魂','此卡因战斗破坏并被送入墓地时，破坏场上所有以表侧表示存在的除暗属性怪兽以外的怪兽。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86238081,'霸王烈龙 异色眼狂怒龙',replace(replace('←1 【灵摆】 1→\r\n①：１回合１次，另一方自己的灵摆区域没有卡存在的情况下可以发动。从牌组挑选１只灵摆怪兽，放在自己的灵摆区域。\r\n【怪兽效果】\r\n龙族等级７怪兽×２\n在可灵摆召唤等级７的情况下，额外牌组表侧表示的此卡可以灵摆召唤。①：以超量怪兽为素材超量召唤的此卡获得以下效果。\n●此卡在１次战斗阶段中可攻击２次。\n●１回合１次，去除此卡的１个超量素材可以发动。将对手场上的卡全部破坏，此卡的攻击力直至回合结束时为止，上升相当于所破坏的卡的数量×２００的数值。\n②：怪兽区域的此卡被破坏的情况下可以发动。将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'从牌组把灵摆怪兽放置','对手场上的卡全部破坏','此卡在灵摆区域放置','超量怪兽为素材作超量召唤','','','','','','','','','','','','');
INSERT INTO texts VALUES(86239173,'地狱角龙',replace(replace('“地狱猛禽龙”＋恐龙族・龙族怪兽\r\n此卡名的①③效果1回合仅可各使用1次。\r\n①：此卡融合召唤的情况下可以发动。从自己牌组・墓地将1张场地魔法卡以表侧表示放在自己的场地区域。\r\n②：此卡在特殊召唤的回合可直接攻击。\r\n③：在自己的主要阶段可以发动。进行1只恐龙族或龙族怪兽的召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86240887,'龙破坏之剑士－毁灭剑士',replace(replace('“毁灭剑士”＋龙族怪兽\r\n此卡仅可以融合召唤特殊召唤。\r\n①：此卡不可直接攻击。\r\n②：此卡的攻击力、守备力上升对手场上、墓地的龙族怪兽数量×１０００点。\r\n③：只要此卡存在于怪兽区，对手场上的龙族怪兽变为守备表示，对手不可发动龙族怪兽的效果。\r\n④：此卡攻击守备表示怪兽的场合，给予攻击力超出该守备力数值的战斗伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86271510,'机怪兽达雷顿','①：１回合１次，在我方主要阶段可发动。直至对手回合结束时，此卡的原本攻击力变成场上怪兽之攻击力与原本攻击力之差额的合计数值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86274272,'圣灵兽骑 亚边狮',replace(replace('“灵兽使”怪兽＋“精灵兽”怪兽\r\n仅可在将自己场上的上述卡除外的情况下特殊召唤。\r\n①：此卡攻击的情况下，直至伤害步骤结束时为止，不受其他卡的效果影响。\r\n②：在自己・对手回合中，将此卡放回额外牌组，以自己除外状态的１只“灵兽使”怪兽与１只“精灵兽”怪兽为对象可以发动。将该怪兽以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'1只「灵兽使」怪兽和1只「精灵兽」怪兽特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86277379,'薰风・苍鹰',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡存在于手牌，场上表侧表示的“薰风”怪兽因战斗被破坏的情况下，或被送至自己墓地的情况下可以发动。将此卡特殊召唤。\r\n②：此卡召唤・特殊召唤成功的情况下可以发动。从牌组将１只“薰风”怪兽送至墓地。然后，可从手牌特殊召唤１只“薰风”怪兽。','\r',char(13)),'\n',char(10)),'','','是否特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86281779,'小工具战士','专为战斗而打造的机械战士。由不生锈的金属制成。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86282581,'邪恶－英雄 黑暗骑士',replace(replace('恶魔族怪兽＋战士族怪兽\r\n此卡仅可以“黑暗结合”的效果特殊召唤。\r\n①：对手场上的怪兽的攻击力下降相当于作为此卡融合素材的怪兽的原本攻击力的合计数值。\r\n②：此卡在1次战斗阶段中可攻击2次。\r\n③：特殊召唤的、表侧表示的此卡因对手从场上离开的情况下，以自己墓地的1只恶魔族・战士族怪兽为对象可以发动。将该怪兽以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86289475,'磁石战士欧米伽＋',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡存在于手牌・墓地的情况下可以发动。将此卡以外的、自己手牌・场上（表侧表示）的1只岩石族怪兽破坏，将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。\r\n②：场上的地属性怪兽的效果发动时，解放此卡，以场上的1只表侧表示怪兽为对象可以发动。将该怪兽改成里侧守备表示。','\r',char(13)),'\n',char(10)),'特殊召唤','改变表示形式','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86304179,'运否的天赋罗－EBI',replace(replace('←8 【灵摆】 8→\r\n此卡名的灵摆效果1回合仅可使用1次。\n①：以自己灵摆区域的1张卡为对象可以发动。掷1次硬币，根据掷出的正反，适用以下效果。\n●正面：将该卡特殊召唤。\n●反面：将该卡破坏，自己失去相当于其灵摆刻度×300的LP。\r\n【怪兽效果】\r\n来到了备受瞩目的EDO－FRONT。这里的天赋罗规模之大自不必说，其精美的造型更是被誉为“金赋罗”。虽然港口内是充盈的最先进设备和满满的异国风情，但同时也弥漫着一股怀旧的芳醇香气，不时传来噼里啪啦的美妙音色，让人心情酥畅脆跃。可因为被周边空域的糟糕状况影响，心心念念的天赋罗今天完全不能入港……别说运气不好，连之后的计划也都打了水漂。1年来的期盼落空，着实让人遗憾，不过我认为这次的体验还是值得给3颗星。','\r',char(13)),'\n',char(10)),'投掷硬币','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86308219,'神鹰女郎 －凤凰之阵－','发动此卡的回合中，自己不可从牌组・额外牌组特殊召唤怪兽，不可进行战斗阶段。①：自己场上有“神鹰女郎”、“神鹰女郎三姐妹”合计３只以上存在的情况下，最多依其数量，以对手场上尽可能多的怪兽为对象可以发动。破坏对象怪兽，给予对手相当于破坏的怪兽中最高的原本攻击力数值的伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86310763,'肃声威光',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：在自己・对手的主要阶段，可从以下效果中选择１个发动。\r\n●从自己的手牌・墓地，将１只战士族・龙族的光属性仪式怪兽或１张仪式魔法卡放回牌组，从牌组挑选１只“肃声”怪兽，加入手牌或特殊召唤。\r\n●以对手场上的卡为对象可以发动，数量最多为自己场上的战士族・龙族光属性仪式怪兽的数量。将该卡和此卡破坏。','\r',char(13)),'\n',char(10)),'从牌组加入手牌或特殊召唤','此卡和对手的卡破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86318356,'草原','场上的战士族、兽战士族怪兽的攻击力、守备力上升２００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86319972,'魔法名－“洛萨门蒂”新世界的开始',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从自己墓地将1只“阿莱斯特”怪兽或融合怪兽除外可以发动。从额外牌组将1只“召唤兽”怪兽无视召唤条件特殊召唤。以此效果特殊召唤的怪兽将在结束阶段被除外。\r\n②：此卡存在于墓地的状态下，有怪兽以表侧被除外的情况下，将此卡除外，以自己除外状态的1只“召唤兽”怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86321248,'古代机械齿轮合成兽',replace(replace('①：根据以此卡的召唤为目的解放的怪兽获得以下效果。\r\n●绿色小工具：此卡的攻击力上升３００。\r\n●红色小工具：此卡以直接攻击给予对手战斗伤害的场合发动。给予对手５００伤害。\r\n●黄色小工具：此卡因战斗破坏对手怪兽的场合发动。给予对手７００伤害。','\r',char(13)),'\n',char(10)),'给予对手500伤害','给予对手７00伤害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86325573,'燃烧拳斗士 巨型绷带','此卡１回合仅１次不会因战斗被破坏。此外，１回合１次，可选择我方墓地１只冠有“燃烧拳斗士”之名的怪兽或１只被除外的我方冠有“燃烧拳斗士”之名的怪兽并发动。我方场上冠有“燃烧拳斗士”之名的所有怪兽变成被选择怪兽的相同等级。','等级变换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86325596,'邪剑男爵','操纵积满怨念之剑的贵族。对追逐猎物的信念十分执着。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86327225,'天界王 席那特','由“奇迹的方舟”召唤而来。此卡通过战斗破坏对手场上守备表示的怪兽并将其送入墓地时，给予对手生命与被破坏怪兽的原始攻击力相同数值的伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86331741,'我我我我魔术师',replace(replace('等级4怪兽×2\r\n此卡名的①效果1回合仅可使用1次。\r\n①：去除此卡的1个超量素材，以“我我我我魔术师”以外的、自己墓地的1只超量怪兽为对象可以发动。将该怪兽的效果无效并特殊召唤。\r\n②：持有此卡作为超量素材的“未来皇霍普”超量怪兽获得以下效果。\r\n●去除此卡的2个超量素材，以自己场上的1只超量怪兽为对象可以发动。直至回合结束时为止，该怪兽的攻击力变为4000，效果无效化。','\r',char(13)),'\n',char(10)),'','攻击力变成4000（我我我我魔术师）','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86346363,'时间重绕机',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：在自己・对手的主要阶段，场上的怪兽反转的情况下可以发动。从手牌将此卡特殊召唤。然后，将场上的１只表侧表示怪兽改成里侧守备表示。\r\n②：在自己・对手的主要阶段，此卡反转的情况下，以自己墓地的１只怪兽为对象可以发动。将该怪兽以守备表示特殊召唤。然后，将场上的１只表侧表示怪兽改成里侧守备表示。','\r',char(13)),'\n',char(10)),'此卡特殊召唤','墓地怪兽特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86346643,'彩虹新宇侠',replace(replace('“元素－英雄 新宇侠”＋“究极宝玉神”怪兽\r\n此卡仅可通过以上述卡作为融合素材的融合召唤来特殊召唤。①：１回合１次，可从以下效果中选择１个发动。\r\n●将自己场上的１只怪兽送至墓地可以发动。将对手场上的怪兽全部放回持有者的牌组。\r\n●将自己场上的１张魔法・陷阱卡送至墓地可以发动。将对手场上的魔法・陷阱卡全部放回持有者的牌组。\r\n●将牌组最上面的卡送至墓地可以发动。将对手墓地的卡全部放回牌组。','\r',char(13)),'\n',char(10)),'选择效果发动','对手场上怪兽全部回到牌组','对手场上的魔法·陷阱卡全部回到牌组','对手墓地的卡全部回到牌组','','','','','','','','','','','','');
INSERT INTO texts VALUES(86361354,'同族感电病毒','１回合１次，可将１只手牌的怪兽从游戏中除外并发动。破坏场上与被除外怪兽相同种族的全部怪兽。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86377375,'恶王 阿赫里曼','此卡名的②效果1回合仅可使用1次。①：从手牌将此卡舍弃可以发动。从牌组将1张“暗黑世界-暗影恶托邦”加入手牌。②：解放自己场上的1只暗属性怪兽可以发动。自己从牌组抽1张。为发动此效果解放此卡以外的暗属性怪兽的情况下，可从牌组将1只守备力2000以上的暗属性怪兽加入手牌代替抽牌。','','','是否作为抽牌的代替从牌组检索？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86379342,'铁兽之血盟','此卡名的①②效果１回合１次，仅可使用其中１个。①：以自己场上的１只连接怪兽为对象可以发动。从自己的手牌・墓地挑选１只种族与该怪兽不同的兽族・兽战士族・鸟兽族怪兽特殊召唤。②：自己场上有兽族・兽战士族・鸟兽族怪兽各１只以上存在的情况下，将墓地的此卡除外，以对手场上的１张表侧表示魔法・陷阱卡为对象可以发动。将该卡的效果直至回合结束时为止无效。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86395581,'风灵媒师 薇茵',replace(replace('此卡名在规则上也视为“灵使”卡。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：从手牌将此卡与1只风属性怪兽舍弃可以发动。从牌组将除了“风灵媒师 薇茵”以外的、守备力1500以下的1只风属性怪兽加入手牌。此效果发动后，直至回合结束时为止，自己不可发动风属性以外的怪兽的效果。\r\n②：自己的风属性怪兽因战斗被破坏时可以发动。从手牌将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86396750,'精灵兽 亚边狮',replace(replace('自己１回合仅可特殊召唤１次“精灵兽 亚边狮”。\r\n①：在每个自己・对手回合中１次，将自己墓地的１张“灵兽”卡除外可以发动。此回合中，自己场上的“灵兽”怪兽的攻击力・守备力上升５００。','\r',char(13)),'\n',char(10)),'攻守上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86401517,'岚龙圣骑','以“电脑网仪式”降临。此卡名的①②效果1回合仅可各使用1次。①：此卡攻击怪兽的伤害步骤开始时可以发动。将该怪兽放回持有者的手牌。②：解放此卡可以发动。从手牌・牌组将1只等级5以上的电子界族怪兽特殊召唤。以此效果特殊召唤的怪兽此回合不可发动效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86421986,'悟道的老树','利用起所有的知识，抵御住各式的攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86442081,'寂静深渊','此卡因战斗破坏并被送入墓地时，破坏场上所有以表侧表示存在的除水属性怪兽以外的怪兽。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86445415,'红色小工具','①：此卡召唤・特殊召唤成功时可以发动。从牌组将１只“黄色小工具”加入手牌。','选1只「黄色小工具」加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86449372,'-艾-打成平手','此卡名的卡1回合仅可发动1张。①：自己的怪兽与对手的怪兽进行战斗的伤害计算时可以发动。自己的该怪兽的攻击力仅在该伤害计算时变为与该对手怪兽的攻击力相同，在该伤害步骤结束时，因该战斗被破坏的怪兽的控制者受到相当于其原本攻击力数值的伤害。②：自己的“＠伊格尼斯者”怪兽将被战斗破坏的情况下，可将墓地的此卡除外作为代替。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86466163,'卫星骑士 御夫卡培拉','此卡名的效果１回合仅可使用１次。①：此卡召唤・反转召唤・特殊召唤成功的情况下可以发动。此回合，自己以３只以上怪兽作为素材进行超量召唤的情况下，可将自己场上的等级４以下“星骑士”怪兽视为等级５的素材。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86469231,'黑曼巴',replace(replace('此卡名以①方法的特殊召唤１回合仅可进行１次，且②效果１回合仅可使用１次。\r\n①：自己场上存在爬虫类族怪兽的情况下，此卡可从手牌中特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下，以对手场上的１只怪兽为对象可以发动。从牌组将１只爬虫类族怪兽送至墓地，变更对象怪兽的表示形式。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86474024,'共同战线','我方场上有２只或以上相同等级的怪兽存在的场合可发动。使陷阱卡的发动无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86483512,'电脑堺悟－老老','此卡名的效果１回合仅可使用１次。①：在此卡存在于手牌中的情况下，以自己场上的１张“电脑堺”卡为对象可以发动。从牌组将１张种类（怪兽・魔法・陷阱）与该卡不同的“电脑堺”卡送至墓地，将此卡特殊召唤。然后，可从自己的墓地挑选１只卡名与送至墓地的卡不同的“电脑堺”怪兽，将其效果无效，以守备表示特殊召唤。此回合，自己仅可特殊召唤等级或阶级为３以上的怪兽。','从手牌特殊召唤','是否从墓地把怪兽特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86489182,'始祖神鸟 西摩格','此卡存在于手牌的场合，被视为通常怪兽。只要此卡以表侧表示存在于场上，上级召唤风属性怪兽的场合必须解放的怪兽数量减少１只。仅限解放风属性怪兽并上级召唤此卡成功时，选择对手场上最多２张卡牌返回至持有者手牌。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86498013,'异次元驯兽师','被吸进异次元的可怜格布林。但现在正朝着新的目标每天努力奋斗中。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86509711,'魔术师联手','①：1回合1次，魔法・陷阱・怪兽的效果发动时，解放自己场上1只“黑魔导”或“黑魔导女孩”可以发动。从自己的手牌・墓地挑选1只与解放的怪兽卡名不同的“黑魔导”或“黑魔导女孩”特殊召唤，将发动的该效果无效。②：魔法与陷阱区域表侧表示的此卡被送至墓地的情况下可以发动。挑选场上的1张卡破坏。','发动但不使用效果','发动并使用①效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86516889,'鬼计恐慌','①：以自己场上任意数量的里侧守备表示怪兽为对象可以发动。将该怪兽改成表侧守备表示，挑选最多为其中“鬼计”怪兽数量的对手场上的表侧表示怪兽改成里侧守备表示。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86520461,'新生代化石骑士 骷髅士兵',replace(replace('岩石族怪兽＋等级4以下的怪兽\r\n此卡仅可通过“化石融合”的效果从额外牌组中特殊召唤。\r\n此卡名的效果②在1个回合中仅可使用1次。\r\n①：此卡在1个战斗阶段中最多可以攻击怪兽2次。\r\n②：除外墓地的此卡后可以发动。将牌组中的1张“时间之流”加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86527709,'虫之专场',replace(replace('此卡名的②③效果1回合仅可各使用1次。\r\n①：不是在此回合被召唤・反转召唤・特殊召唤的、对手场上的表侧表示怪兽变为昆虫族。\r\n②：以自己除外状态的3只昆虫族怪兽为对象可以发动。将该怪兽放回牌组。然后，自己抽1张。\r\n③：此卡从手牌被送至墓地的回合的结束阶段可以发动。将此卡以表侧表示放在自己的魔法与陷阱区域。','\r',char(13)),'\n',char(10)),'变成昆虫族','回收','表侧表示放置','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86532744,'闪光编号39 希望皇霍普・壹',replace(replace('光属性等级４怪兽×３\r\n此卡也可重叠在自己场上的“编号39 希望皇霍普”上面来超量召唤。①：自己的LP比对手少３０００以上的情况下，去除此卡的３个超量素材，支付LP直至变为１０LP可以发动。将对手场上被特殊召唤的怪兽全部破坏并除外。然后，给予对手相当于以此效果除外的怪兽数量×３００的伤害。','\r',char(13)),'\n',char(10)),'破坏并除外','是否在「编号39 希望皇 霍普」上面重叠超量召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86541496,'左臂的代价','发动此卡的回合中，自己不可放置魔法・陷阱卡。①：此卡以外的自己的手牌为2张以上的情况下，将这些手牌全部除外可以发动。从牌组将1张魔法卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86547356,'无限狱偏执狂',replace(replace('此卡名的卡在1个回合中仅可发动1张。\r\n①：解放自己场上的1只暗属性怪兽后可以发动。从自己的牌组、墓地挑选1只与该怪兽卡名不同、等级相同的“永火”怪兽特殊召唤。此效果特殊召唤的怪兽的效果失效。\r\n②：除外墓地中的此卡后，可以以自己墓地的1只“永火”怪兽为对象发动。将该怪兽加入手牌。此效果在此卡被送至墓地的回合不可发动。','\r',char(13)),'\n',char(10)),'特殊召唤','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86553594,'提斯蒂娜的变晶',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：可从以下效果中选择１个发动。\r\n●自己场上存在“提斯蒂娜”怪兽的情况下可以发动。将对手墓地的１张卡以里侧除外。\r\n●被从额外牌组特殊召唤的“提斯蒂娜”怪兽存在于自己场上的情况下可以发动。将对手墓地的卡全部以里侧除外。\r\n②：将墓地的此卡除外，以自己墓地的１只“提斯蒂娜”怪兽为对象可以发动。将该怪兽放回手牌。','\r',char(13)),'\n',char(10)),'从对手墓地把1张卡里侧表示除外','对手墓地的卡全部里侧表示除外','墓地回收','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86555018,'巨石阵术','我方场上冠有“先史遗产”之名的怪兽因战斗或卡牌效果被破坏并送入墓地时可发动。从牌组以表侧守备表示特殊召唤１只等级４或以下冠有“先史遗产”之名的怪兽。以此效果特殊召唤的怪兽不可变更表示形式。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86559484,'超量－透视细剑龙',replace(replace('“超量－透视细剑龙”的①②效果１回合各自仅可各使用１次。\r\n①：从自己的墓地中将龙族怪兽与幻龙族怪兽各１只除外可以发动。从手牌・牌组中特殊召唤１只“超量－透视细剑龙”。\r\n②：此卡从场上被送至墓地的情况下可以发动。给予对手５００点伤害。','\r',char(13)),'\n',char(10)),'特殊召唤','给予伤害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86569121,'梅尔基德四面兽','不断变换着四种面具并发动四种攻击的怪物。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86578200,'魔界大道具“逃跑马车”','①：只要此卡存在于魔法与陷阱区域，自己的“魔界剧团”怪兽１回合各仅１次，不会因战斗被破坏。②：１回合１次，以自己场上的１只“魔界剧团”怪兽为对象可以发动。直至对手回合结束时为止，对手不可将该怪兽作为效果的对象。③：自己的额外牌组存在表侧表示的“魔界剧团”灵摆怪兽，被放置的此卡因对手的效果被破坏的情况下可以发动。将对手场上的卡全部放回持有者的手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86585274,'魔导法士 朱诺',replace(replace('①：可向对手展示手牌的３张“魔导书”魔法卡并发动。从手牌特殊召唤此卡。\r\n②：１回合１次，可从我方手牌、墓地将１张“魔导书”魔法卡除外，并以场上的１张卡牌为对象发动。破坏该卡。','\r',char(13)),'\n',char(10)),'特殊召唤','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86605184,'防火墙守护者','此卡名的①②效果1回合仅可各使用1次。①：此卡作为电子界族连接怪兽的连接素材被送至墓地的情况下可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡离开场上的情况下，将其除外。②：自己与对手双方的连接怪兽之间进行战斗的攻击宣言时，将墓地的此卡除外可以发动。使该攻击无效，该对手怪兽直至回合结束时为止，原本的攻击力变为0，不受自身以外的卡的效果影响。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86605515,'贤瑞官 卡尔丹',replace(replace('①：此卡召唤时可以发动。从自己的手牌・墓地将１张永续陷阱卡放置在自己场上。以此效果放置的卡在放置的回合也可以发动。\r\n②：此卡被送至墓地的情况下可以发动。直至下个回合结束时为止，自己场上表侧表示的陷阱卡不会因对手的效果被破坏。','\r',char(13)),'\n',char(10)),'','','适用「贤瑞官 卡尔丹」的效果来发动','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86607583,'限制代码',replace(replace('此卡牌名的卡牌在决斗中只可发动１张。\r\n①：我方墓地存在有电子界族连接怪兽的场合，可发动此卡。放置计数物于此卡，其数量相当于该怪兽数量，从额外牌组特殊召唤１只“码语者”怪兽，并将此卡视为装备卡装备该怪兽。此卡从场上离开时该怪兽被破坏。\r\n②：在我方结束阶段发动。移除此卡的１个计数物。无法移除的场合破坏此卡。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86613346,'圣夜骑士团・圣炎',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：对手怪兽攻击宣言时，将手牌・场上的此卡送至墓地可以发动。从手牌将１只龙族・光属性・等级７怪兽特殊召唤。\r\n②：将墓地的此卡除外，以自己的场上・墓地的１只龙族・光属性・等级７怪兽为对象可以发动。将该怪兽放回持有者的手牌。此效果在对手回合中也可以发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86643777,'光虫基盘',replace(replace('“光虫基盘”的②效果１回合只可使用１次。\r\n①：我方场上昆虫族怪兽的攻击力、守备力上升３００。\r\n②：可以我方场上的１只昆虫族超量怪兽为对象发动。将１只手牌的昆虫族怪兽重叠至该怪兽下方当作超量素材。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86652646,'骨犬玛隆','１０００年前与主人走失的迷犬。至今仍在等候主人的归来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86676862,'邪恶－英雄 极恶邪魔',replace(replace('“邪恶－英雄 极恶刀缘”＋等级6以上的恶魔族怪兽\r\n此卡仅可以“黑暗结合”的效果特殊召唤。\r\n①：只要此卡存在于怪兽区域，对手的战斗阶段期间，对手场上的所有怪兽变为表侧攻击表示，且在可攻击的情况下必须攻击此卡。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86682165,'冰翡啼 爱姬尔・盖密尔',replace(replace('水属性协调＋１只以上协调以外的怪兽\r\n此卡名的①②效果１回合仅可各使用１次。①：在自己・对手回合可以发动。此回合，自己场上的表侧表示怪兽不会因对手的效果被破坏，不可因对手的效果除外。此效果是连锁了对手的效果发动来发动，且该卡的同名卡存在于对手场上・墓地的情况下，进而可将该卡的同名卡全部除外。②：此卡存在于墓地，卡因对手的效果被除外的情况下可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','是否把对手发动的效果的同名卡除外？','此卡特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86686671,'电子修理工厂',replace(replace('此卡名的卡1回合仅可发动1张。①：在自己墓地有“电子龙”存在的情况下，可从以下效果中选择1个发动。此卡发动时，在自己墓地有3只以上“电子龙”存在的情况下，则两者都可以选择。\r\n●从牌组将1只机械族・光属性怪兽加入手牌。\r\n●可以自己墓地的1只机械族・光属性怪兽为对象发动。将该机械族・光属性怪兽放回牌组。','\r',char(13)),'\n',char(10)),'牌组检索','墓地回收','选择两方','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86690572,'炎涡的胎动','陷阱卡发动时，可从手牌将１只冠有“岩浆炎”之名的怪兽送入墓地并发动。使该发动无效并破坏。此外，可将我方墓地的２只炎属性怪兽从游戏中除外并发动。将墓地的此卡加入手牌。','此卡加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86742443,'王宫的重税','对手的准备阶段时可以发动。随机挑选１张对手的手牌并确认。确认的卡或该同名卡直至下一个自己结束阶段时不被召唤或发动的情况下，给予对手LP１０００点伤害。被召唤或发动的情况下，自己受到１０００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86750474,'淘气仙星・狐手套女巫',replace(replace('天使族怪兽2只以上\r\n此卡名的①②效果1回合仅可各使用1次。①：此卡特殊召唤成功的情况下可以发动。给予对手相当于对手场上卡数量×200的伤害。②：连接召唤的此卡因战斗・效果被破坏的情况下可以发动。从额外牌组将连接2以下的1只“淘气仙星”怪兽特殊召唤。然后给予对手相当于对手场上卡数量×200的伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86758746,'亚马逊的秘术',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：从自己的手牌・场上，将由“亚马逊”融合怪兽卡决定的融合素材怪兽送至墓地，将该１只融合怪兽从额外牌组融合召唤。\r\n②：在自己的主要阶段将墓地的此卡除外可以发动。此回合，自己融合召唤“亚马逊”融合怪兽的情况下仅１次，也可将自己的额外牌组的１只“亚马逊”怪兽送至墓地作为融合素材。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86758915,'魔神仪的祝诞','仪式怪兽降临所必需。此卡名的②效果1回合仅可使用1次。①：为使合计等级变为仪式召唤的怪兽以上，将自己手牌・场上的“魔神仪”怪兽解放，从手牌将1只仪式怪兽仪式召唤。②：此卡存在于墓地的情况下，从手牌及自己场上表侧表示的卡中，将1张“魔神仪的祝诞”以外的“魔神仪”卡送至墓地可以发动。从牌组将1只“魔神仪”怪兽特殊召唤。然后将墓地的此卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86762958,'协助★黯蜜！',replace(replace('此卡名的②③效果1回合1次，仅可使用其中1个。\r\n①：在每个自己・对手的准备阶段可以发动1次。自己恢复100LP，对手支付100LP。\r\n②：在自己・对手的主要阶段及对手的战斗阶段，将包含此卡在内的、自己场上的2张表侧表示的“黯蜜”卡送至墓地可以发动。将自己或对手的、场上・墓地的1张卡放回手牌。\r\n③：将墓地的此卡除外可以发动。从牌组将“协助★黯蜜！”以外的1张“黯蜜”卡送至墓地。','\r',char(13)),'\n',char(10)),'基本分','回到手牌','送至墓地','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86767655,'Ms.JUDGE',replace(replace('“Ms.JUDGE”的效果１回合只可使用１次。\r\n①：只要此卡存在于怪兽区，对手卡牌效果发动的场合，在该效果处理时掷２次硬币，２次均是正面的场合，使该效果无效。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86778566,'攻击无敌化',replace(replace('可在我方或对手的战斗阶段，从以下效果中选择一个并发动。\r\n●可选择场上的１只怪兽并发动。被选择怪兽在此战斗阶段中，不会因战斗及卡牌效果被破坏。\r\n●此战斗阶段中，对我方的战斗伤害变成０。','\r',char(13)),'\n',char(10)),'选择怪兽不会被战斗以及卡的效果破坏','这次战斗阶段中，对自己的战斗伤害变成0','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86780027,'一族之团结','①：自己墓地所有怪兽的原本种族相同的情况下，自己场上该种族的怪兽的攻击力上升800。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86784733,'电子界同步士','此卡名的②效果1回合仅可使用1次。①：1回合1次，以自己场上1只等级4以下的怪兽为对象可以发动。该怪兽的等级直至回合结束时为止，上升相当于其原本等级的数值。②：额外怪兽区域的自己的怪兽将被战斗・效果破坏的情况下，可将墓地的此卡除外作为代替。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86801871,'蛇壶','反转：特殊召唤１只“毒蛇衍生物”（爬虫类族・地・３星・攻／守１２００）到我方场上。“毒蛇衍生物”因战斗被破坏的场合，给予对方生命５００点伤害。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86801872,'毒蛇衍生物','由“蛇壶”的效果特殊召唤而来。此衍生物在战斗中被破坏时，将给对手生命值造成５００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86804246,'超级漏洞人','此卡不可通常召唤。将自己墓地的“漏洞人X”、“漏洞人Y”、“漏洞人Z”从游戏除外的情况下，可以守备表示特殊召唤。只要此卡以表侧表示存在于场上，场上所有攻击表示怪兽的攻击力・守备力互换。“超级漏洞人”在场上仅可有１只以表侧表示存在。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86805855,'暗魔界之龙骑士 暗剑',replace(replace('“暗魔界之战士 暗剑”＋“漆黑的斗龙”\r\n此卡给予对方生命战斗伤害时可发动。从对手墓地最多选择３只怪兽，从游戏中除外。','\r',char(13)),'\n',char(10)),'除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86809440,'迷拟宝箱鬼・地下城',replace(replace('此卡名的③效果1回合仅可使用1次。\r\n①：不是在当回合被召唤・特殊召唤的、自己场上的“迷拟宝箱鬼”怪兽的攻击力上升自身原本守备力的数值。\r\n②：自身场上存在里侧表示怪兽的玩家不可召唤怪兽，不可用在当回合被特殊召唤的怪兽攻击宣言。\r\n③：在自己的主要阶段可以发动。从自己牌组・墓地将1只“迷拟宝箱鬼”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86821010,'力量解除','①：自己场上有“动力工具龙”存在的情况下，将自己的场上・墓地的最多３张装备卡作为对象可以发动。将该卡放回持有者的牌组，给予对手LP放回数量×５００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86825114,'淘气仙星・菲沃斯','此卡名的效果1回合仅可使用1次。①：此卡作为“淘气仙星”连接怪兽的连接素材被送至墓地的情况下可以发动。从墓地将此卡特殊召唤。以此效果特殊召唤的此卡离开场上的情况下，将其除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86825483,'星圣领域','只要此卡存在于场上，光属性怪兽的效果不会被无效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86827882,'极星宝 梅金吉奥德','可选择我方场上１只冠有“极神”或“极星”之名的怪兽并发动。直至回合结束时，被选择怪兽的攻击力、守备力变成原本数值的两倍。此回合，被选择怪兽不可直接攻击对手玩家。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86840720,'魔轰神迪夫','冠有“魔轰神”之名的怪兽从手牌被送入我方墓地时，可释放此卡，并选择１只该怪兽发动。从墓地特殊召唤被选择怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86848580,'零鸟兽 希尔菲尼',replace(replace('鸟兽族等级4怪兽×2\r\n①：1回合1次，去除此卡的1个超量素材可以发动。将对手场上的所有表侧表示卡的效果无效，此卡的攻击力上升此卡以外的、场上的表侧表示卡的数量×300的数值。此效果适用至下个自己的准备阶段为止。','\r',char(13)),'\n',char(10)),'效果无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86852702,'机甲部队的再编制',replace(replace('此卡名的卡１回合仅可发动１张。①：可从以下效果中选择１个发动。\r\n●舍弃１张手牌可以发动。从牌组将２只“机甲部队”怪兽加入手牌（同名卡最多１张）。\r\n●从手牌将１张“机甲部队”卡舍弃可以发动。从牌组将“机甲部队的再编制”以外的２张“机甲部队”卡加入手牌（同名卡最多１张）。','\r',char(13)),'\n',char(10)),'检索「机甲」怪兽','检索「机甲」卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86868952,'武斗神器－八握','可在我方主要阶段１中将此卡从手牌送入墓地，选择我方场上的１只冠有“武斗神”之名的怪兽并发动。此回合，被选择怪兽在１次战斗阶段中可攻击２次。发动此效果的回合，除被选择怪兽以外的怪兽不可进行攻击。','2次攻击','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86871614,'克隆复制','①：对手召唤・反转召唤怪兽成功时，以1只该怪兽为对象可以发动。将1只拥有该表侧表示怪兽原本的种族・属性・等级・攻击力・守备力的“克隆衍生物”特殊召唤至自己场上。该表侧表示怪兽被破坏并被送至墓地时此衍生物将被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86871615,'克隆衍生物','由“克隆复制”的效果特殊召唤而来。原怪兽被破坏并送入墓地时，此衍生物将被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86885905,'幻变骚灵・模拟精灵','①：此卡发动后变为效果怪兽（魔法师族・光・星4・攻1400/守1800），特殊召唤至怪兽区域。此卡也视为陷阱卡。②：只要以此卡效果特殊召唤的此卡存在于怪兽区域，此卡以外的自己场上的“幻变骚灵”陷阱卡不会成为效果对象，不会因效果被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86889202,'看门狗－戴表之犬',replace(replace('“看门狗－戴表之犬”的效果１回合只可使用１次，发动此效果的回合，我方不可特殊召唤怪兽。\r\n①：在此卡召唤成功回合的主要阶段２，可将手牌的１张魔法卡送入墓地并发动。从牌组挑选１张永续魔法卡并盖牌至我方的魔法与陷阱区域。','\r',char(13)),'\n',char(10)),'牌组检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86915847,'武装蜜蜂','１回合１次，可选择对手场上的１只表侧表示怪兽并发动。直至回合结束时，被选择的对手怪兽的攻击力减半。','攻防减半','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86926989,'丽神－不知火',replace(replace('不死族怪兽２只以上\r\n此卡名的③效果１回合仅可使用１次。\r\n①：只要此卡存在于怪兽区域，自己场上的同步怪兽不会因效果被破坏。\r\n②：只要此卡存在于怪兽区域，自己的炎属性怪兽不会因战斗被破坏。\r\n③：在对手回合中，以自己除外状态的１只不死族同步怪兽为对象可以发动。将该怪兽特殊召唤至此卡连接端的自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86937530,'妖精传姬－辉夜',replace(replace('①：此卡召唤时可以发动。从牌组将1只攻击力1850的魔法师族怪兽加入手牌。\r\n②：在每个自己・对手回合中1次，以对手场上的1只表侧表示怪兽为对象可以发动。对手可从自身的牌组・额外牌组将该怪兽的1张同名卡送至墓地，将此效果无效。没送至墓地的情况下，将此卡及对象怪兽放回手牌。','\r',char(13)),'\n',char(10)),'牌组检索','回到手牌','是否把同名卡送至墓地让此效果无效？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86938484,'影依・拿非利',replace(replace('反转怪兽2只\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己的主要阶段可以发动。将自己手牌・场上的怪兽作为融合素材，将1只“影依”融合怪兽融合召唤。\r\n②：此卡存在于墓地的情况下可以发动。从自己手牌・场上（表侧表示）将1张“影依”卡送至墓地，将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86943389,'高速疾行机人 快刀乱破拼图',replace(replace('协调+1只以上协调以外的怪兽\r\n①：此卡与被特殊召唤的怪兽进行战斗的伤害步骤开始时可以发动。此卡的攻击力直至该伤害步骤结束时为止变为两倍。②：在同步召唤的此卡被送至墓地的回合的结束阶段，以自己墓地的1只“高速疾行机人 快刀乱破拼图”以外的“疾行机人”怪兽为对象可以发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86952477,'闪光骑士','只要此卡以表侧守备表示存在于场上，此卡的等级变成４。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86962245,'转生炎兽 狐飒','此卡名的①②效果1回合1次，仅可使用其中1个。①：自己的墓地的“转生炎兽”怪兽有3只以上的情况下，将此卡从手牌送至墓地，以自己墓地的1只“转生炎兽”连接怪兽和对手的1张魔法与陷阱区域的卡为对象可以发动。将对象之墓地的怪兽放回额外牌组，破坏对象之场上的卡。②：此卡存在于墓地，对手的魔法与陷阱区域的卡被破坏并被送至墓地的情况下可以发动。将此卡以守备表示特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86976918,'疾行机人 伸缩弹簧狗','此卡名的②效果1回合仅可使用1次。①：此卡召唤成功时可以发动。从牌组将1张“疾行机人”卡送至墓地。②：将墓地的此卡除外，以自己墓地的1只“疾行机人”怪兽为对象可以发动。将该怪兽放回牌组，从额外牌组将1只卡名与该怪兽不同、等级相同的“疾行机人”同步怪兽的效果无效并特殊召唤。此效果在此卡被送至墓地的回合不可发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86988864,'三峰骆驼','我方怪兽区存在３只“三峰骆驼”的场合，可解放其中２只并发动。我方从牌组抽取３张卡牌。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86993168,'疯帽骇客',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：怪兽被特殊召唤至对手场上的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：在自己・对手的结束阶段，将场上的此卡除外可以发动。获得对手场上攻击力最低的１只怪兽的控制权。只要该怪兽以表侧表示存在于自己场上，该怪兽不可发动效果，自己从额外牌组仅可特殊召唤连接怪兽。','\r',char(13)),'\n',char(10)),'此卡从手牌特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86997073,'机动要塞超强音','１回合１次，我方主要阶段时可发动。从手牌特殊召唤１只冠有“机皇兵”之名的怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(86999951,'结晶神 提斯蒂娜',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：在自己的主要阶段可以发动。将对手场上的怪兽全部改成里侧守备表示。然后，可将对手场上的表侧表示卡全部送至墓地。\r\n②：此卡被对手破坏的情况下可以发动。将对手场上的怪兽全部改成里侧守备表示。然后，可将对手场上的表侧表示卡全部送至墓地。','\r',char(13)),'\n',char(10)),'','是否把对手场上的表侧表示的卡全部送至墓地？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87003671,'影灵衣的舞巫女 艾米莉娅',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：自己场上或墓地存在战士族“影灵衣”怪兽的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从牌组将1只“影灵衣”仪式怪兽或1张“影灵衣”魔法卡加入手牌。\r\n③：要仪式召唤1只“影灵衣”仪式怪兽的情况下，使用自己场上的1张此卡即可作为仪式召唤所必需的解放。','\r',char(13)),'\n',char(10)),'特殊召唤','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87008374,'ZEXAL兵器－不死鸟弩弓','选择自己场上的１只“混沌编号39 希望皇霍普雷”可以发动。手牌的此卡被视为装备卡装备于被选择的自己的“混沌编号39 希望皇霍普雷”。以此效果装备此卡的怪兽的攻击力上升１１００点。此外，装备怪兽战斗破坏对手怪兽时，给予对手LP１０００点伤害。自己场上仅可有１张“ZEXAL兵器－不死鸟弩弓”以表侧表示存在。','装备','伤害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87010442,'遗产猎人','此卡因战斗破坏里侧表示怪兽并将其送入墓地时，对手随机挑选１张手牌返回至牌组。','返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87025064,'银龙的轰咆','此卡名的卡1回合仅可发动1张。①：可以自己墓地的1只龙族通常怪兽为对象发动。特殊召唤该龙族通常怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87043568,'强袭之魂','发动后此卡变成装备卡，装备在我方场上的１只怪兽。１回合１次，可在装备怪兽攻击的伤害步骤时，从手牌将１只攻击力１０００或以下的怪兽送入墓地并发动。直至回合结束时，装备怪兽的攻击力上升相当于送入墓地的怪兽的攻击力数值。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87046457,'超越生死线','只要此卡存在于场上，从墓地特殊召唤至我方场上的植物族怪兽的攻击力上升１０００点。此卡在发动后第２回合的我方结束阶段时被破坏。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87047074,'甲虫装机的魔弓 虫王弓','此卡仅限装备冠有“甲虫装机”之名的怪兽。装备怪兽的攻击力上升５００点。对装备怪兽效果的发动对手不可发动魔法、陷阱、怪兽的效果。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87047161,'人鱼鲨','①：此卡召唤时可以发动。从牌组将１只等级３～５的鱼族怪兽加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87052196,'天威龙－阿舒那','此卡名的①②效果1回合仅可各使用1次。①：自己场上没有效果怪兽存在的情况下可以发动。从手牌将此卡特殊召唤。②：自己场上有效果怪兽以外的表侧表示怪兽存在的情况下，将手牌・墓地的此卡除外可以发动。从牌组将1只“天威龙-阿舒那”以外的“天威”怪兽特殊召唤。此效果发动后，直至回合结束时为止自己仅可特殊召唤幻龙族怪兽。','此卡从手牌特殊召唤','从牌组特殊召唤「天威」怪兽','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87054946,'焰凰神－奈芙蒂斯',replace(replace('包含仪式怪兽在内的怪兽２只以上\r\n①：此卡根据作为此卡连接素材的仪式怪兽的数量，获得以下效果。\r\n●１只以上：此卡不会因战斗被破坏。\r\n●２只以上：此卡的攻击力上升１２００，不会因效果被破坏。\r\n●３只：此卡的攻击力上升１２００，双方不可将此卡作为效果的对象。\r\n②：只要此卡存在于额外怪兽区域，对手怪兽不可将主要怪兽区域的“奈芙蒂斯”怪兽选择为攻击对象。','\r',char(13)),'\n',char(10)),'1只以上怪兽为素材','2只以上怪兽为素材','3只怪兽为素材','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87074380,'机甲部队・上校','此卡不可通常召唤，仅可以卡的效果特殊召唤。此卡名的①②效果１回合仅可各使用１次。①：在自己・对手回合中，以自己场上的１只机械族怪兽为对象可以发动。将该机械族怪兽和拥有其攻击力以下攻击力的对手场上的怪兽全部破坏。②：此卡存在于墓地的状态下，自己场上“机甲部队・上校”以外的表侧表示机械族・地属性怪兽因战斗・效果被破坏的情况下可以发动。将此卡特殊召唤。','怪兽破坏','此卡特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87091930,'急袭者不屈铁意','此卡名在规则上也视为“魅影骑士团”卡、“急袭猛禽”卡。此卡名的①②效果１回合仅可各使用１次。①：自己以暗属性超量怪兽作为素材超量召唤成功的情况下，以场上的１张卡为对象可以发动。将该卡破坏。②：魔法与陷阱区域表侧表示的此卡因效果被破坏的情况下可以发动。从自己的牌组・墓地挑选１张“升阶魔法”魔法卡放置在自己场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87102774,'黄金瓢虫','１回合１次，我方准备阶段时，可向对手展示手牌的此卡并发动。我方回复５００LP。使用了此效果的场合，直至回合结束时公开手牌中的此卡。','回复','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87106146,'伤害之门','我方受到战斗伤害时可发动。选择持有所受伤害数值或以下攻击力的我方墓地的１只怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87112784,'堕天使的放逐',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从牌组将“堕天使的放逐”以外的1张“堕天使”卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87116749,'游览艇 潜艇利兹鱼',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：自己场上有通常怪兽存在的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：１回合仅１次，自己的通常怪兽不会因与效果怪兽的战斗被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87116928,'嵌合巨舰龙',replace(replace('“电子龙”怪兽＋额外怪兽区域的怪兽1只以上\r\n仅在将自己・对手场上的上述卡送至墓地的情况下可以从额外牌组特殊召唤。\r\n此卡不可作为融合素材。\r\n①：此卡原本的攻击力变为用作此卡的融合素材的怪兽数量×1200的数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87116929,'嵌合巨舰龙',replace(replace('“电子龙”怪兽＋额外怪兽区域的怪兽1只以上\r\n仅在将自己・对手场上的上述卡送至墓地的情况下可以从额外牌组特殊召唤。\r\n此卡不可作为融合素材。\r\n①：此卡原本的攻击力变为用作此卡的融合素材的怪兽数量×1200的数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87118301,'灵兽使 蕾拉',replace(replace('自己１回合仅可特殊召唤１次“灵兽使 蕾拉”。\r\n①：此卡召唤的情况下，以自己墓地的１只“灵兽”怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87126721,'多多迷宝・喵噜猫咪',replace(replace('发动此卡的效果的回合中，自己仅可发动1次此卡以外的“多多迷宝”怪兽的效果。\r\n①：在自己・对手回合中，自己场上不存在卡的情况下，从手牌将此卡舍弃可以发动。在此回合中适用以下效果。\r\n●对手每次将墓地・除外状态的怪兽特殊召唤，自己抽1张。\r\n●在结束阶段，自己手牌多于对手场上的卡的数量＋6张的情况下，依其数量差将自己手牌随机放回牌组。','\r',char(13)),'\n',char(10)),'抽牌&手牌回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87148330,'光神忒堤斯','①：我方抽取卡牌时，若该卡为天使族怪兽的场合，可向对手展示该卡并发动。此卡以表侧表示存在于场上的场合，我方从牌组抽取１张卡牌。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87151205,'电力尾龙','总是萦绕电力浮游于空中的龙。自古便存在于世间，其生态尚存大量谜团，但依古时规矩禁止对其进行捕获。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87170768,'接触的Z',replace(replace('①：对手将怪兽召唤・特殊召唤时可以发动。从手牌将此卡以守备表示特殊召唤至对手场上。\r\n②：只要此卡存在于怪兽区域，自己要进行融合・同步・超量・连接召唤的情况下，仅可进行以此卡作为素材的融合・同步・超量・连接召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87182127,'古代机械齿轮・魔神',replace(replace('“古代机械齿轮”怪兽×２\r\n此卡名的②效果１回合仅可使用１次。\r\n①：场上的此卡不受其他卡的效果影响。\r\n②：在自己的主要阶段可以发动。给予对手１０００伤害。\r\n③：此卡因战斗被破坏并被送至墓地的情况下可以发动。从牌组将１只“古代机械齿轮”怪兽无视召唤条件特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87188910,'饥鳄龙 饿古提斯',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的①③效果1回合仅可各使用1次。\r\n①：此卡同步召唤的情况下可以发动。依作为其同步素材的怪兽中协调以外的怪兽数量，自己抽牌。\r\n②：此卡的攻击力・守备力上升自己手牌数量×500的数值。\r\n③：在自己・对手回合中，舍弃2张手牌，以场上的1张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87209160,'铁兽战线 弗拉克忒尔',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：将手牌・场上的此卡送至墓地可以发动。从牌组将1只等级3以下的兽族・兽战士族・鸟兽族怪兽送至墓地。\r\n②：从自己墓地将任意数量的兽族・兽战士族・鸟兽族怪兽除外可以发动。从额外牌组将1只连接标记与除外数量相同的兽族・兽战士族・鸟兽族连接怪兽特殊召唤。此效果发动后，直至回合结束时为止，自己仅可以兽族・兽战士族・鸟兽族怪兽作为连接素材。','\r',char(13)),'\n',char(10)),'送至墓地','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87210505,'骑士的称号','①：可解放我方场上１只表侧表示的“黑魔导”来发动此卡。从我方的手牌・牌组・墓地特殊召唤１只“黑魔导骑士”。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87240371,'骑甲虫队空降作战',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：将１只“骑甲虫衍生物”（昆虫族・地・星３・攻／守１０００）特殊召唤至自己场上。然后，自己场上存在攻击力３０００以上的昆虫族怪兽的情况下，可将场上的１张魔法・陷阱卡破坏。','\r',char(13)),'\n',char(10)),'是否选魔法·陷阱卡破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87240372,'骑甲虫衍生物','由"骑甲虫"卡片的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87246309,'绒毛动物・章鱼',replace(replace('“绒毛动物・章鱼”的①②效果１回合只可各使用１次。\r\n①：此卡召唤、特殊召唤成功时，可以我方墓地的１只“绒毛动物”怪兽或１只“锋利小鬼”怪兽为对象发动。将该怪兽加入手牌。\r\n②：此卡成为“魔玩具”融合怪兽之融合召唤素材被送入墓地的场合，最多可以２只被除外的我方怪兽为对象发动。将该怪兽返回至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87255382,'纹章兽 双头蛇',replace(replace('①：从手牌将1只其他的“纹章兽”怪兽舍弃可以发动。从手牌将此卡特殊召唤。\r\n②：1回合1次，从手牌将1只“纹章兽”怪兽舍弃可以发动。此卡的攻击力直至回合结束时为止上升800。','\r',char(13)),'\n',char(10)),'特殊召唤','攻击上升','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87257460,'魅惑女王 LV3',replace(replace('①：１回合１次，以对手场上的１只等级３以下的怪兽为对象可以发动。将该等级３以下的对手怪兽视为装备魔法卡，装备于此卡（仅可装备１只）。\r\n②：此卡将被战斗破坏的情况下，作为代替将以此卡的效果装备的怪兽破坏。\r\n③：在自己的准备阶段，将以此卡的效果装备有怪兽的此卡送至墓地可以发动。从手牌・牌组将１只“魅惑女王 LV5”特殊召唤。','\r',char(13)),'\n',char(10)),'装备','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87259077,'闪电战士',replace(replace('协调＋协调以外的怪兽１只或以上\r\n此卡因战斗破坏对手怪兽并送入墓地时，给予对手生命相当于对手手牌张数×３００点伤害。','\r',char(13)),'\n',char(10)),'伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87259933,'宝玉的集结',replace(replace('此卡的①②效果不可在同一连锁上发动。\r\n①：１回合１次，我方场上表侧表示的“宝玉兽”怪兽因战斗、效果被破坏的场合，可发动此效果。从牌组特殊召唤１只“宝玉兽”怪兽。\r\n②：可将魔法与陷阱区域表侧表示的此卡送入墓地，并以我方场上的１张“宝玉兽”卡牌和场上的１张卡牌为对象发动此效果。将对象卡牌返回至持有者手牌。','\r',char(13)),'\n',char(10)),'发动但不使用效果','发动并使用②效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87263576,'爆发龙',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：自己场上有怪兽存在的情况下可以发动。从手牌将此卡特殊召唤。然后，将自己场上其他的怪兽全部破坏。只要以此效果特殊召唤的此卡以表侧表示存在于怪兽区域，自己仅可特殊召唤暗属性怪兽。\r\n②：在对手的主要阶段可以发动。将包含此卡在内的自己场上的怪兽作为素材，进行1只龙族连接怪兽的连接召唤。','\r',char(13)),'\n',char(10)),'','','「爆发龙」效果适用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87288189,'怨邪帝盖乌斯',replace(replace('此卡可通过解放1只上级召唤的怪兽来上级召唤。\r\n①：此卡上级召唤的情况下，以场上的1张卡为对象发动（此卡解放了暗属性怪兽来上级召唤的情况下，可将此效果的对象改成2张）。将该卡除外，给予对手1000伤害。除外的卡为暗属性怪兽卡的情况下，进而从其控制者的手牌・牌组・额外牌组・墓地将所有同名卡除外。','\r',char(13)),'\n',char(10)),'把1只上级召唤的怪兽解放作上级召唤','卡片除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87292536,'XX－军刀 雷金古拉','①：此卡召唤・特殊召唤时，以自己墓地的1只“X－军刀”怪兽为对象可以发动。将该怪兽加入手牌。','墓地回收','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87294988,'红姬知流姬','只要此卡以表侧表示存在于场上，对手不可选择其他植物族怪兽为攻击对象。此外，此卡因对手被送入墓地的场合，可从牌组特殊召唤１只除“红姬知流姬”以外的植物族怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87303357,'闪光深渊','光之力与暗之力兼具的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87313164,'鱼！','怪兽效果发动时，可将１只从游戏中被除外的我方鱼族、海龙族、水族怪兽返回至牌组并发动。使该发动无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87319876,'信赖守护者','以此卡作为同步素材的场合，只可使用于等级７或以上同步怪兽的同步召唤。以此卡为同步素材的同步怪兽，１回合仅１次不会因战斗而被破坏。适用此效果的伤害步骤结束时，该同步怪兽的攻击力、守备力下降４００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87321742,'急袭猛禽－绞杀伯劳','此卡名的①②效果１回合仅可各使用１次。①：在自己场上有暗属性怪兽存在的情况下可以发动。从手牌将此卡特殊召唤。此效果发动后，直至回合结束时为止自己仅可特殊召唤暗属性怪兽。②：自己场上有持有暗属性超量怪兽作为超量素材的超量怪兽存在的情况下，以自己墓地的１只等级４以下的“急袭猛禽”怪兽为对象可以发动。将该怪兽特殊召唤。以此效果特殊召唤的怪兽的效果无效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87322377,'TM－1火箭炮蜘蛛','用火箭发射器乱射一通来轰杀敌人的机器蜘蛛。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87322378,'TM－1火箭炮蜘蛛','用火箭发射器乱射一通来轰杀敌人的机器蜘蛛。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87327776,'转生炎兽 幻象雄马',replace(replace('等级3怪兽×2\r\n此卡名的①②效果1回合仅可各使用1次。①：去除此卡的1个超量素材可以发动。从牌组将1只“转生炎兽”怪兽以守备表示形式特殊召唤。此效果发动后，直到回合结束时为止自己不可发动炎属性以外的怪兽的效果。②：超量召唤的此卡作为“转生炎兽”连接怪兽的连接素材被送至墓地的情况下，可以场上1只怪兽为对象发动。将该怪兽放回持有者的手牌中。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87340664,'原子萤火虫','此卡因战斗被破坏的情况下发动。破坏此卡的玩家受到１０００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87347365,'再生魔像',replace(replace('此卡名的效果１回合仅可使用１次。\r\n①：此卡被从牌组送至墓地的情况下，从以下效果中选择１个发动。\r\n●将此卡特殊召唤。\r\n●将此卡加入手牌。','\r',char(13)),'\n',char(10)),'选择效果发动','此卡特殊召唤','此卡加入手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87350908,'假面斩者','此卡战斗破坏对手怪兽的情况下，给予对手LP２０００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87390067,'黑羽－苍天的杰特','我方冠有“黑羽”之名的怪兽进行战斗的伤害计算时，可将此卡从手牌送入墓地并发动。我方怪兽不会因该战斗而被破坏。','不被战斗破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87390798,'魔界剧本“幻想魔法”','①：以自己场上的１只“魔界剧团”怪兽为对象可以发动。此回合，与该怪兽战斗过但未被破坏的怪兽，将在伤害步骤结束时放回持有者的手牌。②：自己的额外牌组存在表侧表示的“魔界剧团”灵摆怪兽，被放置的此卡因对手的效果被破坏的情况下，以对手场上的１张卡为对象可以发动。将该卡放回持有者的牌组最上面。','「魔界剧本“「幻想魔法」」效果适用中','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87430304,'先史遗产摩艾石像','我方场上存在有冠有“先史遗产”之名怪兽的场合，此卡可从手牌以守备表示特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87430998,'森林','场上的昆虫族、兽族、植物族、兽战士族怪兽的攻击力、守备力上升２００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87451661,'绯暗红恶魔',replace(replace('协调＋协调以外的暗属性怪兽１只以上\r\n此卡名的②效果１回合仅可使用１次。\r\n①：此卡只要存在于场上・墓地，卡名视为“暗红恶魔龙”。\r\n②：此卡被从怪兽区域送至墓地的情况下可以发动。从额外牌组将１只“暗红恶魔龙”视为同步召唤来特殊召唤。此卡作为龙族・暗属性同步怪兽的同步素材被送至墓地的情况下，进而可将对手场上的攻击表示怪兽全部破坏。','\r',char(13)),'\n',char(10)),'','是否把对手场上的攻击表示怪兽全部破坏？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87460579,'花札卫－五光',replace(replace('协调＋４只协调以外的怪兽\r\n①：１回合１次，对手发动魔法・陷阱卡时可以发动。将该发动无效并破坏。\r\n②：自己的“花札卫”怪兽与对手怪兽进行战斗的情况下，仅在战斗阶段期间，该对手怪兽的效果无效化。\r\n③：同步召唤的此卡因战斗被破坏的情况下，或因对手的效果离开场上的情况下可以发动。从额外牌组将“花札卫－五光”以外的１只“花札卫”同步怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87462901,'幻蜡馆的使者',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：对手怪兽攻击宣言时可以发动。从手牌将此卡特殊召唤。\r\n②：此卡与怪兽进行战斗的情况下，该2只不会因该战斗被破坏。\r\n③：对手的战斗阶段结束时可以发动。对手场上的所有攻击表示怪兽直至下个对手的战斗阶段开始时为止，不可变更表示形式，不可作为融合・同步・超量・连接召唤的素材，效果无效化。','\r',char(13)),'\n',char(10)),'此卡特殊召唤','效果无效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87468732,'变导机咎・弧线钟摆机',replace(replace('←4 【灵摆】 4→\r\n①：自己场上不存在怪兽或仅有灵摆怪兽的情况下，根据此卡在灵摆区域的位置，适用以下效果。\n●左侧：此卡的灵摆刻度下降３。\n●右侧：此卡的灵摆刻度上升４。\n②：在对手的准备阶段可以发动。将灵摆区域的此卡特殊召唤。\r\n【怪兽效果】\r\n①：此卡特殊召唤至中央以外的主要怪兽区域的情况下，将被破坏。\n②：此卡不会因战斗被破坏。\n③：在对手的结束阶段，以自己灵摆区域的１张卡为对象可以发动。将该卡破坏，将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87473172,'火炎鸟','只要此卡以表侧表示存在于场上，每次我方场上的鸟兽族怪兽被破坏，此卡的攻击力上升５００点。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87475570,'宝玉的先导者',replace(replace('←5 【灵摆】 5→\r\n①：只要此卡存在于灵摆区，我方场上的“究极宝玉神”怪兽及“宝玉兽”卡牌不会成为对手的效果对象。\r\n【怪兽效果】\r\n①：可解放此卡并发动。从牌组将“究极宝玉神”怪兽・“宝玉兽”怪兽・“宝玉”魔法・陷阱卡中的任１张卡牌加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87481592,'教导神理','此卡名的②效果１回合仅可使用１次。①：装备怪兽为“教导”怪兽的情况下，装备怪兽的攻击力上升相当于自身等级×１００的数值。为“教导”怪兽以外的情况下，装备怪兽的攻击力下降相当于自己场上“教导”怪兽数量×２００的数值。②：因装备怪兽被破坏导致此卡被送至墓地的情况下可以发动。从额外牌组将１只怪兽送至墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87483942,'素银忍者','此卡反转时，可从我方的手牌・墓地以里侧守备表示特殊召唤任意数量的除“素银忍者”以外的冠有“忍者”之名的怪兽。以表侧表示存在于场上的“素银忍者”只可有１只。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87497553,'圣约・圣骑联盟',replace(replace('此卡名的卡1回合仅可发动1张。①：可从以下效果中选择1个发动。\r\n●此回合，应对自己的“圣骑联盟”怪兽的效果发动，对手不可发动魔法・陷阱・怪兽的效果。\r\n●自己的“圣骑联盟”连接怪兽战斗破坏对手怪兽的伤害计算后可以发动。自己从牌组抽自己的该怪兽连接标记的数量的卡。','\r',char(13)),'\n',char(10)),'不可对应发动','抽牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87498729,'提斯蒂娜的遗落之子',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：将手牌・场上的此卡送至墓地可以发动。从牌组将１张“神域 巴提斯蒂娜”以表侧表示放在自己的场地区域。\r\n②：此卡存在于墓地的状态下，自己场上表侧表示的“提斯蒂娜”魔法・陷阱卡因对手的效果被破坏的情况下，将此卡除外可以发动。从自己手牌・牌组・墓地将１只光属性“提斯蒂娜”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'放置「神域 巴提斯蒂娜」','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87511987,'大榔头','地狱的魔术师制造出来的机械兵。用双臂的铁球不分敌我地不断攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87514539,'傀儡虫','①：可将此卡从手牌舍弃至墓地，并以对手场上的１只恶魔族、不死族怪兽为对象发动。直至结束阶段，获得该恶魔族、不死族怪兽的控制权。','获得控制权','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87523462,'有翼贤者 法尔科斯','此卡因战斗破坏以攻击表示的对手怪兽并将其送入对手墓地时可发动。可将该怪兽返回至对手牌组的最上面。','返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87526784,'漏洞人X','此卡召唤成功时，我方场上存在有“漏洞人Y”的场合，可从牌组特殊召唤１只“漏洞人Z”。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87532344,'永恒至爱',replace(replace('①：１回合１次，可从以下效果中选择１个发动（此卡名的以下效果１回合仅可各选择１次）。\r\n●将自己的墓地・除外状态的１只“尤贝尔”怪兽特殊召唤。该特殊召唤成功时，双方不可发动魔法・陷阱・怪兽的效果。\r\n●自己场上存在“尤贝尔”的情况下，舍弃１张手牌，将魔法与陷阱区域表侧表示的此卡送至墓地可以发动。将自己・对手场上包含“尤贝尔”怪兽在内的怪兽作为融合素材，将１只融合怪兽融合召唤。','\r',char(13)),'\n',char(10)),'特殊召唤「尤贝尔」怪兽','用「尤贝尔」怪兽融合召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87535691,'超重武者 鼓－３','此卡名的效果１回合仅可使用１次。①：场上的此卡被破坏并被送至墓地的情况下，以自己墓地１只“超重武者 鼓－３”以外的“超重武者”怪兽为对象可以发动。将该怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87557188,'严格的老魔术师','反转：将场上以里侧表示的卡牌全部变为表侧表示后，恢复原样。此时，不发动变为表侧表示的卡牌的效果。','确认盖卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87564352,'暗黑龙王','栖息于黑暗深处的龙。眼睛不太好。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87564935,'钢铁化寄生生物－日之甲','１回合１次，可在我方的主要阶段时，将此卡作为装备卡装备至我方场上的怪兽上，或者解除装备状态以表侧攻击表示特殊召唤此卡。以此效果变为装备卡的场合，装备怪兽不会成为对手效果怪兽的效果对象，不会因对手效果怪兽的效果而被破坏。（１只怪兽最多只可装备１张联合。当装备怪兽被破坏的场合，破坏此卡来代替。）','装备','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87567063,'造反剧',replace(replace('此卡牌名的卡牌１回合只可发动１张。\r\n①：在我方、对手的战斗阶段可以对手场上的１只怪兽为对象发动。直至战斗阶段结束时，获得该怪兽的控制权。此回合，除对象怪兽以外的我方怪兽不可进行攻击。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87571563,'星遗物守护龙','此卡名的卡1回合仅可发动1张。①：此卡发动时，可以自己墓地的1只等级4以下的龙族怪兽为对象。在该情况下，将该怪兽加入手牌或特殊召唤。②：1回合1次，以自己场上的1只龙族怪兽为对象可以发动。将该自己怪兽的位置移动至自己其他的主要怪兽区域。','','是否以墓地龙族怪兽为对象发动？','请选择要移动位置的卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87588741,'机壳通道',replace(replace('←9 【灵摆】 9→\r\n①：自己仅可特殊召唤“机壳”怪兽。此效果不会被无效化。\n②：对手场上怪兽的攻击力下降３００。\r\n【怪兽效果】\r\n①：此卡无需解放即可召唤。\n②：以特殊召唤或无需解放召唤的此卡的等级变为４，原本攻击力变为１８００。\n③：通常召唤的此卡不受原本等级或阶级低于此卡等级的怪兽发动的效果影响。\n④：解放“机壳”怪兽且此卡的上级召唤成功时可以发动。对手墓地的怪兽数量多于自己墓地的怪兽数量的情况下，自己恢复该差额数值×３００点LP，并给予对手仅该数值数量的伤害。','\r',char(13)),'\n',char(10)),'不用解放作召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87602890,'轰雷帝扎博尔格',replace(replace('此卡可通过解放1只上级召唤的怪兽来上级召唤。\r\n①：此卡上级召唤的情况下，以场上的1只怪兽为对象发动。将该怪兽破坏。破坏的怪兽是光属性的情况下，以其原本的等级・阶级数为上限，双方尽可能地各从自身额外牌组将卡送至墓地（此卡解放了光属性怪兽来上级召唤的情况下，要送至墓地的对手的卡由自己来挑选）。','\r',char(13)),'\n',char(10)),'把1只上级召唤的怪兽解放作上级召唤','怪兽破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87607094,'枪管重启',replace(replace('此卡也可通过支付一半LP来从手牌发动。\r\n①：自己场上存在“枪弹”怪兽或“枪管”怪兽，且对手发动魔法・陷阱卡时可以发动。将该发动无效，将该卡就此放置。以此效果放置的卡此回合不可发动。','\r',char(13)),'\n',char(10)),'发动','适用「枪管重启」的效果来发动','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87608852,'魔导召唤士 坦普尔','我方发动了冠有“魔导书”之名魔法卡的我方回合主要阶段时，可解放此卡并发动。从牌组特殊召唤１只等级５以上的光属性或暗属性魔法师族怪兽。发动此效果的回合，我方不可特殊召唤其他等级５以上的怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87609391,'猛禽究极权杖',replace(replace('仅可装备于“急袭猛禽”怪兽。\r\n①：装备怪兽的攻击力上升１０００。\r\n②：装备怪兽被选择为攻击力高于装备怪兽的怪兽的攻击对象时可以发动。从牌组将１张“升阶魔法”魔法卡加入手牌，因该战斗对自己造成的战斗伤害变为０。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87614611,'红莲魔龙之壶',replace(replace('发动此卡的回合及下个对手回合中，自己不可召唤・特殊召唤怪兽。\r\n①：自己场上存在“暗红恶魔龙”的情况下可以发动。自己抽2张。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87621407,'魔装机关车 凸伊奇','反转：我方从牌组抽取１张卡牌。我方场上存在“魔货物车厢 凹伊奇”的场合，再抽取与该卡牌数量相同的卡牌。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87622767,'最终超能怪物','此卡因战斗破坏对手怪兽时，可支付８００LP并发动。选择我方墓地的１只念动力族怪兽并加入手牌。','加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87624166,'古之森林','此卡发动时，场上有守备表示怪兽存在的情况下，将该怪兽全部变成表侧攻击表示。此时，不发动反转效果怪兽的效果。此外，只要此卡存在于场上，在战斗阶段结束时破坏进行了攻击的怪兽。','攻击怪兽破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87639778,'神鹰羽毛吹雪','自己场上有“神鹰”怪兽存在的情况下，此卡也可从手牌发动。①：自己场上有鸟兽族・风属性怪兽存在的情况下可以发动。直至回合结束时为止，对手发动的怪兽的效果无效化。②：魔法与陷阱区域的此卡因对手的效果被破坏的情况下可以发动。从自己的牌组・墓地挑选１张“神鹰羽毛扫”加入手牌。','','适用「神鹰女妖的羽毛吹雪」的效果来发动','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87640391,'冰候鸟',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：场上存在水属性超量怪兽的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：在自己的主要阶段可以发动。去除自己场上的1个超量素材。然后，可从自己手牌・墓地将1只等级3・4的水属性怪兽效果无效并特殊召唤。此回合，将以此效果特殊召唤的怪兽使用于水属性怪兽的超量召唤的情况下，也可将该等级视为5。','\r',char(13)),'\n',char(10)),'手牌特殊召唤','效果无效特殊召唤','是否把怪兽特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87649699,'大植然豚草','①：对手在抽牌阶段以外抽牌时，将场上的此卡送至墓地可以发动。自己从牌组抽２张。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87669904,'双天招来',replace(replace('此卡名的卡在1个回合中仅可发动1张。\r\n①：扔掉1张手牌，尽可能特殊召唤“双天魂衍生物”（战士族・光・星2・攻/守0）至自己场上。此回合中，自己从额外牌组只可特殊召唤融合怪兽，自己场上的衍生物不可解放且将在结束阶段被破坏。然后，可最多适用2次以下效果。\r\n●从自己的手牌、场上将由“双天”融合怪兽卡决定的融合素材怪兽送至墓地，从额外牌组中融合召唤1只该融合怪兽。','\r',char(13)),'\n',char(10)),'是否要融合召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87669905,'双天魂衍生物','由“双天招来”等的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87676171,'蚀神之光 提斯蒂娜',replace(replace('等级１０怪兽×２\r\n此卡名的①效果１回合仅可使用１次。\r\n①：此卡特殊召唤的情况下可以发动。将对手场上的里侧表示卡全部送至墓地。\r\n②：此卡持有“结晶神 提斯蒂娜”作为超量素材的情况下，１回合１次，去除此卡的１个超量素材可以发动。此卡的攻击力直至对手回合结束时为止上升２０００。\r\n③：持有超量素材的此卡被对手破坏的情况下可以发动。从自己墓地将１只“提斯蒂娜”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'里侧卡送至墓地','攻击力上升','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87685879,'考拉考','①：1回合1次，以对手场上的1只表侧表示怪兽为对象可以发动（此效果在自己场上存在其他兽族怪兽的情况下才能发动和处理）。将该对手的怪兽的攻击力直至回合结束时为止改成0。','攻击力变成0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87742943,'动力履带车',replace(replace('此卡名的效果①在1个回合中仅可使用1次。\r\n①：此卡召唤或特殊召唤成功时可以发动。选择1只攻击力低于此卡的对手场上的怪兽破坏。\r\n②：只要此卡存在于怪兽区域，可以进行攻击的对手怪兽就必须进行攻击。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87746184,'烙印龙 阿尔比昂',replace(replace('“阿尔白斯之落胤”＋光属性怪兽\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡融合召唤的情况下可以发动。将自己手牌・场上・墓地的怪兽作为融合素材除外，将除“烙印龙 阿尔比昂”以外的、1只等级8以下的融合怪兽融合召唤。\r\n②：在此卡被送至墓地的回合的结束阶段可以发动。从牌组挑选1张“烙印”魔法・陷阱卡，加入手牌或放置在自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87750925,'虚英雄迪斯盖斯',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：此卡存在于手牌，且自己场上或墓地存在装备魔法卡的情况下可以发动。将此卡特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从牌组将1张“天魔伏圣剑”加入手牌。\r\n③：此卡装备有装备卡的情况下，以调整以外的、场上的1只战士族怪兽为对象可以发动。直至结束阶段为止，此卡变为与该怪兽相同等级，视为同名卡。','\r',char(13)),'\n',char(10)),'特殊召唤','检索','改变卡名等级','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87751584,'机关枪龙',replace(replace('“左轮枪龙”＋“回膛手枪龙”\r\n１回合１次，可在我方主要阶段时发动。掷硬币３次，尽可能地挑选场上的怪兽破坏，其数量最多为出现正面的次数。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87756343,'飞蛾毛虫','此卡不可通常召唤。解放１只装备了“进化之茧”后经过２个以上我方回合的“小毛虫”的场合，可特殊召唤此卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87758525,'至爱－英雄 闪耀光焰翼人',replace(replace('融合怪兽＋场上表侧表示的怪兽\r\n此卡名在规则上也视为“元素－英雄”卡。\r\n此卡名的①效果1回合仅可使用1次。\r\n①：此卡从额外牌组特殊召唤的情况下可以发动。从自己墓地将5只怪兽放回牌组。然后，自己抽2张，此卡的攻击力上升1000。\r\n②：此卡战斗破坏怪兽的情况下发动。给予对手相当于该怪兽的原本攻击力数值的伤害。','\r',char(13)),'\n',char(10)),'回到牌组','给与伤害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87758526,'至爱－英雄 闪耀光焰翼人',replace(replace('融合怪兽＋场上表侧表示的怪兽\r\n此卡名在规则上也视为“元素－英雄”卡。\r\n此卡名的①效果1回合仅可使用1次。\r\n①：此卡从额外牌组特殊召唤的情况下可以发动。从自己墓地将5只怪兽放回牌组。然后，自己抽2张，此卡的攻击力上升1000。\r\n②：此卡战斗破坏怪兽的情况下发动。给予对手相当于该怪兽的原本攻击力数值的伤害。','\r',char(13)),'\n',char(10)),'回到牌组','给与伤害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87765315,'真龙之觉醒','①：“龙魔王”怪兽及灵摆怪兽以外的“龙剑士”怪兽存在于场上的情况下可以发动。将双方场上的卡全部放回持有者的牌组。然后，可从牌组将１只“龙剑士”怪兽或“龙魔王”怪兽无视召唤条件特殊召唤。','是否要把怪兽特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87769556,'魔术师的右手','①：１回合１次，自己场上有魔法师族怪兽存在的情况下，将对手发动的魔法卡效果无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87772572,'量子猫','①：可各宣言１个种族和属性发动。此卡发动后，变成持有宣言种族、属性的通常怪兽（星４、攻０／守２２００），特殊召唤至怪兽区。此卡被视为陷阱卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87774234,'棉花球','此卡因卡牌效果从我方牌组加入手牌的场合，可从手牌特殊召唤此卡。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87778106,'Recette de Poisson～鱼料理食谱～',replace(replace('“饿魔新飨”仪式怪兽的降临所必需。\r\n①：为使合计等级为仪式召唤的怪兽的等级以上，解放自己的手牌・场上的怪兽，从手牌将１只“饿魔新飨”仪式怪兽仪式召唤。以此效果将“马赛鱼汤之布耶贝斯・饿魔新飨”仪式召唤的情况下，可进而适用以下效果。\r\n●从自己的牌组・墓地将“Recette de Poisson～鱼料理食谱～”以外的１张“食谱”仪式魔法卡加入手牌。','\r',char(13)),'\n',char(10)),'是否把「食谱」仪式魔法卡加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87796900,'护城翼龙','守卫山城的龙。会从天空中急速俯冲，攻击敌人。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87798440,'铠甲破坏者','１回合１次，可在我方的主要阶段时，将此卡作为装备卡装备至我方场上的战士族怪兽上，或者解除装备状态以表侧攻击表示特殊召唤此卡。以此效果变为装备卡的场合，在装备怪兽对对手生命造成战斗伤害时破坏场上的１张卡牌。（１只怪兽最多只可装备１张联合。装备怪兽因战斗而被破坏的场合，破坏此卡来代替。）','装备','特殊召唤','破坏','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87800375,'圣剑导引的未来',replace(replace('此卡牌名的②效果１回合只可使用１次。\r\n①：从我方牌组上方翻阅相当于我方场上“圣剑”装备魔法卡数量的卡牌。从中挑选１张加入手牌，剩余卡牌依照喜好顺序返回至牌组上方。\r\n②：可将墓地的此卡除外并发动。从牌组特殊召唤１只我方场上、墓地不存在有同名卡的“圣骑士”怪兽。此效果在此卡被送入墓地的回合不可发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87804365,'斩机超阶乘',replace(replace('此卡名的卡1回合仅可发动1张。①：可以自己墓地的最多3只“斩机”怪兽为对象，从以下效果中选择1个发动（同名卡最多1张）。\r\n●将该怪兽的效果无效化并特殊召唤，仅以该怪兽为素材将1只“斩机”同步怪兽同步召唤。此时的同步素材怪兽不去墓地，而是放回持有者的牌组。\r\n●将该怪兽的效果无效化并特殊召唤，仅以该怪兽为素材将1只“斩机”超量怪兽超量召唤。','\r',char(13)),'\n',char(10)),'苏生并同步召唤','苏生并超量召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87804747,'完全体・大昆虫',replace(replace('昆虫族・等级８怪兽＋昆虫族・等级７怪兽\r\n自己１回合仅可特殊召唤“完全态・大昆虫”１次。\r\n此卡仅可以融合召唤及以下方法从额外牌组特殊召唤。\r\n●解放自己１只装备有装备卡的、守备力２０００以上的昆虫族怪兽的情况下，可从额外牌组特殊召唤。\r\n①：此卡不会因战斗被破坏。\r\n②：卡以表侧表示存在于场地区域的情况下，在自己・对手的战斗阶段可发动１次。将对手场上的怪兽全部破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87814728,'磁石战士西格玛－',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：向对手出示手牌的此卡可以发动。以包含手牌的此卡在内的、自己手牌・场上的岩石族怪兽作为融合素材，将1只融合怪兽融合召唤。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从牌组将1只等级8的“磁石之战士”怪兽送至墓地。\r\n③：1回合1次，双方的地属性怪兽之间进行战斗的攻击宣言时可以发动。将该攻击无效。','\r',char(13)),'\n',char(10)),'融合召唤','送至墓地','攻击无效','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87818869,'超升阶魔法－究极之力',replace(replace('①：以自己场上1只原本属性为光属性的、阶级9以下的“霍普”超量怪兽为对象可以发动。从额外牌组将1只阶级10以上的“编号”超量怪兽重叠在对象的自己的超量怪兽上面，视为超量召唤特殊召唤，将此卡作为其超量素材。\r\n②：持有此卡作为超量素材的“编号99”超量怪兽获得以下效果。\r\n●对手在战斗阶段发动怪兽的效果时发动（同一连锁上最多1次）。将此卡的超量素材全部去除，将对手场上的怪兽全部破坏。','\r',char(13)),'\n',char(10)),'发动','破坏效果（超升阶魔法－究极之力）','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87819421,'假面补给','①：以自己墓地的1只“-英雄”怪兽和1张“变换”速攻魔法卡为对象可以发动。将该卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87835759,'创世龙骑士',replace(replace('“创世龙骑士”的③效果１回合只可使用１次。\r\n①：只要此卡存在于怪兽区，对手回合期间，此卡的等级上升４。\r\n②：此卡在战斗中破坏怪兽并送入墓地时可发动。从牌组将１只等级７、８的龙族怪兽送入墓地。\r\n③：可将１张手牌送入墓地，并以我方墓地的１只等级７、８的龙族怪兽为对象发动。将此卡送入墓地，特殊召唤对象怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87836938,'大日神械先锋','此卡因卡牌效果被破坏并送入墓地时，可从牌组抽取卡牌，其数量最多与装备此卡的装备卡数量相同。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87837090,'带刃龙 柯伊伯带',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡同步召唤的情况下，以场上的1张卡为对象可以发动。将该卡破坏。\r\n②：场上的此卡被破坏的情况下，以场上的1只表侧表示怪兽为对象可以发动。该怪兽直至对手回合结束时为止不可攻击。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87844926,'灵魂召集',replace(replace('①：“灵魂召集”在自己场上仅可有１张以表侧表示存在。\r\n②：只要此卡存在于魔法与陷阱区域，每次对手特殊召唤怪兽成功，从对手的牌组上面将３张卡送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87871125,'转生炎兽 日光狼',replace(replace('炎属性的效果怪兽2只\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：怪兽被召唤・特殊召唤至此卡连接端的情况下可以发动。从自己墓地将1只炎属性怪兽加入手牌。此回合，自己不可通常召唤・特殊召唤以此效果加入手牌的怪兽及其同名怪兽。\r\n②：此卡是以“转生炎兽 日光狼”作为素材被连接召唤的情况下可以发动。从自己墓地将1张“转生炎兽”魔法・陷阱卡加入手牌。','\r',char(13)),'\n',char(10)),'墓地怪兽回收','墓地魔陷回收','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87880531,'扩散波动','可支付１０００LP，并选择我方场上１只等级７以上的魔法师族怪兽来发动此卡。该回合中，除所选择怪兽以外的怪兽不可进行攻击，而所选择怪兽必须对对手所有怪兽各进行１次攻击。因此攻击而被破坏的效果怪兽不可发动效果，其效果无效。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87890143,'世代之力','①：自己场上有超量怪兽存在的情况下可以发动。从牌组将１张“超量”卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87897777,'弈勇－疯狂侯爵',replace(replace('←1 【灵摆】 1→\r\n此卡名的灵摆效果１回合仅可使用１次。①：场地区域有“弈勇世界－百识公国”存在的情况下，或自己场上有炎属性的“弈勇”怪兽存在的情况下可以发动。将此卡特殊召唤至正面的自己的主要怪兽区域。\r\n【怪兽效果】\r\n此卡名的①②怪兽效果１回合仅可各使用１次。①：在自己的主要阶段可以发动。掷１次骰子，从自己的牌组上面翻开掷出数字数量的卡。可以从其中挑选１张“弈勇”卡加入手牌。剩余的放回牌组。②：怪兽区域的此卡移动至其他怪兽区域的情况下可以发动。掷１次骰子，出现２～５的情况下，挑选１张自己魔法与陷阱区域的怪兽卡，特殊召唤至其正面的自己主要怪兽区域。','\r',char(13)),'\n',char(10)),'是否选卡加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87902575,'未来显现','只要此卡存在于场上，我方或对手召唤怪兽成功时，选择１只该怪兽从游戏中除外。从被召唤怪兽的控制者视角出发的下一个我方准备阶段时，将因此效果被除外的怪兽以攻击表示返回至场上。','除外','返回场上','请选择要回到场上的卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87910978,'洗脑','①：支付800LP，以对手场上的1只可通常召唤的表侧表示怪兽为对象可以发动。直至结束阶段为止获得该表侧表示怪兽的控制权。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87911394,'混沌编号39 希望皇霍普雷・胜利',replace(replace('等级５怪兽×３\r\n①：此卡攻击的情况下，对手直至伤害步骤结束时为止，不可发动魔法・陷阱卡。②：此卡持有“希望皇霍普”怪兽作为超量素材的情况下，获得以下效果。\r\n●此卡对对手的表侧表示怪兽攻击宣言时，去除此卡的１个超量素材可以发动。直至回合结束时为止，该对手怪兽的效果无效化，此卡的攻击力上升相当于该对手怪兽攻击力的数值。','\r',char(13)),'\n',char(10)),'效果无效化','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87917187,'暗黑召唤神','此卡名的①效果1回合仅可使用1次。①：解放此卡可以发动。从手牌・牌组将“神炎皇乌利亚”、“降雷皇哈蒙”、“幻魔皇拉比艾尔”中的任意1只无视召唤条件特殊召唤。此回合中，自己的怪兽不可攻击。②：将墓地的此卡除外可以发动。从牌组将“神炎皇乌利亚”、“降雷皇哈蒙”、“幻魔皇拉比艾尔”中的任意1只加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87931906,'月光结合',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：将自己手牌・场上的怪兽作为融合素材，将1只“月光”融合怪兽融合召唤。对手场上存在被从额外牌组特殊召唤的怪兽的情况下，也可将自己牌组・额外牌组的最多1只“月光”怪兽作为融合素材。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87955518,'Recette de Spécialité～主厨的看家食谱～',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己场上存在“饿魔新飨”仪式怪兽，怪兽的效果・魔法・陷阱卡发动时可以发动。将该发动无效。以“饿魔新飨”怪兽的效果特殊召唤的怪兽存在于自己场上的情况下，可进而将该无效的卡破坏。\r\n②：自己特殊召唤“饥饿汉堡”的情况下，将墓地的此卡除外可以发动。将对手场上的怪兽尽可能地解放。','\r',char(13)),'\n',char(10)),'','对手场上的怪兽尽可能解放','是否把那张卡破坏？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87973893,'甲虫装机的魔斧 虫王斧','此卡仅限装备冠有“甲虫装机”之名的怪兽。装备怪兽的攻击力上升１０００点。装备怪兽的攻击宣言时，对手不可发动魔法、陷阱卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87978805,'寄生体 蜱螨','此卡的攻击力、守备力变为场上衍生物数量×５００点的数值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87979586,'天使曼陀号手','如天使般美丽的花朵。不断散发出迷惑人的雾气，阻挡入侵者闯进圣兽们所栖息的森林最深处。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87985506,'恶魔的谐谑',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从手牌・牌组将1只等级7以下的“恶魔”怪兽特殊召唤。自己的额外牌组存在表侧的“恶魔”仪式怪兽的情况下，作为代替也可从手牌・牌组将“皇室恶魔”“公爵恶魔”“殿下恶魔”各最多1只特殊召唤。','\r',char(13)),'\n',char(10)),'是否作为代替特殊召唤最多3只怪兽？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87988305,'怨念之邪恶灵',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：对手发动魔法・陷阱・怪兽的效果时，将手牌・场上的此卡送至墓地，以自己墓地的１只恶魔族・等级８怪兽为对象可以发动。将该怪兽特殊召唤。以此效果特殊召唤的怪兽的效果无效化。\r\n②：此卡存在于墓地，恶魔族・等级８怪兽被送至自己墓地的情况下可以发动。将此卡加入手牌。','\r',char(13)),'\n',char(10)),'','此卡加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87990236,'魅惑的堕天使',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从自己手牌・场上（表侧表示）将1只“堕天使”怪兽送至墓地可以发动。获得对手场上1只表侧表示怪兽的控制权直至结束阶段为止。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(87997872,'斯芬克斯・安德鲁吉尼斯','此卡不可通常召唤。可以此卡的效果特殊召唤。自己场上表侧表示的“安德鲁・斯芬克斯”和“斯芬克斯・泰蕾雅”同时被破坏时，可支付５００LP发动。可从手牌、牌组特殊召唤此卡。此卡特殊召唤成功时，可支付５００LP发动。直至回合结束时，此卡的攻击力上升３０００点。','特殊召唤','攻击上升','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88000953,'光栅狮虎',replace(replace('除衍生物以外的怪兽２只以上\r\n具此卡名的①②效果１回合各只能使用１次。\r\n①：以我方或对手墓地的１只连接怪兽为目标可发动。此卡的攻击力直到回合结束上升该怪兽的攻击力数值。\r\n②：仅在解放此卡连接端任意我方怪兽后可发动。仅按解放的怪兽数选择场上的卡片破坏。','\r',char(13)),'\n',char(10)),'攻击力上升','卡片破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88001391,'地缚死灵 佐玛',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡发动后，变为拥有以下效果的效果怪兽（不死族・暗・星４・攻１８００／守５００），特殊召唤至怪兽区域（也视为陷阱卡）。\r\n●可攻击的对手怪兽必须攻击此卡。\r\n②：以此卡的效果特殊召唤的此卡因对手怪兽的攻击被破坏的情况下发动。给予对手相当于破坏此卡的怪兽的原本攻击力的两倍数值的伤害（最多３０００）。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88021907,'块斩机拉普拉斯算子',replace(replace('等级4怪兽×3\r\n此卡名的①效果1回合仅可使用1次。①：此卡超量召唤成功的情况下，可将此卡的最多3个超量素材去除，并从以下选择相应数量的效果发动\r\n●随机挑选1张对手的手牌送至墓地。\r\n●挑选对手场上的1只怪兽送至墓地。\r\n●挑选对手场上的1张魔法・陷阱卡送至墓地。\r\n②：自己场上的“斩机”卡将被效果破坏的情况下，作为代替，可去除此卡的1个超量素材。','\r',char(13)),'\n',char(10)),'对手手牌随机选1张送至墓地','选对手场上1只怪兽送至墓地','选对手场上1张魔法·陷阱卡送至墓地','','取除超量素材选择效果发动','','','','','','','','','','','');
INSERT INTO texts VALUES(88032368,'二次推进士','释放此卡，选择我方场上的１只攻击表示怪兽并发动。直至回合结束时，被选择的怪兽攻击力上升１５００点。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88032456,'复制猫',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：自己场上存在“卡通世界”及卡通怪兽的情况下，以对手墓地的1张卡为对象可以发动。该卡是怪兽的情况下，将该怪兽特殊召唤至自己场上。该卡是魔法・陷阱卡的情况下，将该卡放置在自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88033975,'幻层保卫者阿尔玛迪斯',replace(replace('协调＋协调以外的怪兽1只以上\r\n①：此卡进行战斗的情况下，对手直至伤害步骤结束时为止，不可发动魔法・陷阱・怪兽的效果。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88039509,'一号机人',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：此卡因战斗・效果被破坏的情况下可以发动。从牌组将2只等级4以下的机械族怪兽送至墓地。','\r',char(13)),'\n',char(10)),'送至墓地','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88069166,'奥丁之眼','１回合１次，可于双方的准备阶段时，选择我方场上１只冠有“极神”之名的怪兽并发动。直至回合结束时，被选择怪兽的效果无效，并确认所有对手手牌及被盖牌在对手场上的卡牌。对此效果的发动，对手不可发动魔法、陷阱、怪兽的效果。','确认手牌和盖卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88069597,'捕食花盆','此卡的控制者在每个自己的准备阶段支付８００LP。或不支付LP而是破坏此卡。①：１回合１次，在自己的主要阶段可以发动。从自己的手牌・墓地挑选１只等级４以下的“捕食植物”怪兽特殊召唤。以此效果特殊召唤的怪兽的效果无效化。','「捕食植物」怪兽特殊召唤','是否支付800基本分？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88071625,'暴君的海王星','此卡不可特殊召唤。此卡可释放１只怪兽并上级召唤。此卡的攻击力、守备力上升相当于上级召唤时被释放怪兽之原本攻击力、守备力的各合计数值。此卡上级召唤成功时，可选择我方或对手墓地１只被释放的效果怪兽，并将其视为该怪兽的同名卡，获得相同效果。','把1只怪兽解放召唤','效果复制','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88078306,'旋狸之虫惑魔','此卡名的②效果１回合仅可使用１次。①：此卡只要存在于怪兽区域，不受“空洞”通常陷阱卡及“落穴”通常陷阱卡的效果影响。②：解放此卡可以发动。从自己的牌组及墓地各挑选１张、“空洞”通常陷阱卡或“落穴”通常陷阱卡放置在自己场上（同名卡最多１张）。以此效果放置的卡离开场上的情况下，将其除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88083109,'书灵师・波及',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：以自己场上的1只“书灵师”怪兽和对手场上的1只怪兽为对象可以发动。将该自己的怪兽放回手牌，获得该对手怪兽的控制权。以仪式怪兽以外的自己的怪兽为对象发动此卡的情况下，以此效果获得控制权的怪兽将在结束阶段放回手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88086137,'直通断线','①：与此卡同一纵列的怪兽的效果・魔法・陷阱卡发动时，可以发动被放置的此卡。将该发动无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88089103,'四次元之墓','将存在于我方墓地并带有“LV”的２只怪兽加入我方牌组并洗牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88093706,'更新干扰者',replace(replace('等级2以上电子界族怪兽2只\r\n①：每次自己的电子界族怪兽进行战斗的伤害计算时可以发动1次。直至伤害步骤结束时为止，此卡以外的场上的卡的效果无效化，该战斗的伤害计算以原本的攻击力・守备力进行。对手怪兽因该战斗被破坏并被送至墓地时，给予对手1000伤害。②：此卡作为连接素材被送至墓地的情况下可以发动。以此卡作为连接素材的连接怪兽在此回合，1次战斗阶段中可攻击2次。','\r',char(13)),'\n',char(10)),'','','「更新干扰者」效果适用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88095331,'进化虫・纳哈什蛇','①：场上的此卡被解放的情况下可以发动。从牌组将１只“进化龙”怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88106656,'书灵师・烈火爆裂',replace(replace('以“书灵师”卡降临\r\n①：使用场上的怪兽来仪式召唤的此卡不会因战斗被破坏，给予对手的战斗伤害变为两倍。\r\n②：此卡在1次战斗阶段中最多可攻击怪兽2次。\r\n③：自己或对手怪兽的攻击宣言时，从自己墓地将1只“书灵师”仪式怪兽除外可以发动。此卡的攻击力上升200。','\r',char(13)),'\n',char(10)),'使用场上的怪兽作仪式召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88120966,'编号15 机关傀偶－巨人杀手',replace(replace('等级８怪兽×２\r\n①：１回合最多２次，在自己的主要阶段１，去除此卡的１个超量素材，以对手场上１只被特殊召唤的怪兽为对象可以发动。将该怪兽破坏。所破坏的怪兽为超量怪兽的情况下，进而给予对手相当于该怪兽的原本攻击力数值的伤害。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88123329,'精灵兽 罗梦凤企',replace(replace('自己１回合仅可特殊召唤１次“精灵兽 罗梦凤企”。\r\n①：１回合１次，在自己的主要阶段可以发动。从额外牌组将１只“灵兽”怪兽除外，从牌组将种族与该怪兽相同的１只“灵兽”怪兽送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88124568,'秘旋谍－双重伪装',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：自己场上或墓地存在“秘旋谍”卡的情况下可以发动。从手牌将此卡以守备表示特殊召唤至对手场上。然后，将双方牌组最上面的卡给彼此确认。以此效果特殊召唤的此卡不可解放，也不可作为融合・同步・超量・连接召唤的素材。\r\n②：场上的“秘旋谍”怪兽的攻击力上升５００，“秘旋谍－花花公子”可直接攻击。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88132637,'双头地狱犬','除此卡以外的恶魔族怪兽以表侧表示存在于我方场上的场合，此卡以战斗破坏的反转效果怪兽的效果被无效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88139289,'念力枪手Mk－Ⅱ',replace(replace('念动力族协调＋协调以外的念动力族怪兽1只以上\r\n此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：以自己或对手除外状态的1只怪兽为对象可以发动。将该怪兽特殊召唤至自己场上。\r\n②：在自己・对手的主要阶段，从自己墓地将1只怪兽除外，以场上1只其他的表侧表示怪兽为对象可以发动。将该怪兽除外。然后，依除外的怪兽的原本攻击力的数值恢复自己的LP。','\r',char(13)),'\n',char(10)),'特殊召唤','除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88170262,'杀手旋律・重混',replace(replace('“杀手旋律・米可丝”＋协调1只以上\r\n此卡名的②效果1回合仅可使用1次。\r\n①：只要对手场上或墓地存在协调，此卡的攻击力上升1500。\r\n②：在对手回合中，解放此卡可以发动。从自己墓地挑选同步怪兽以外的2只协调，将其中1只加入手牌，将另1只特殊召唤。然后，可进行1只同步怪兽的协调的同步召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','是否同步召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88176533,'奈芙蒂斯的祭祀者',replace(replace('以“奈芙蒂斯的轮回”降临\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡仪式召唤的情况下可以发动。从牌组将１只“奈芙蒂斯”怪兽特殊召唤。在发动了此效果的回合的结束阶段此卡将被破坏。\r\n②：此卡存在于墓地的情况下可以发动。将自己手牌的１张“奈芙蒂斯”卡破坏，将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88177324,'编号107 银河眼时空龙',replace(replace('等级８怪兽×２\r\n①：自己的战斗阶段开始时，去除此卡的１个超量素材可以发动。场上此卡以外的所有表侧表示怪兽的效果无效化，其攻击力・守备力变为原本的数值。发动了此效果的回合的战斗阶段中，每当对手发动魔法・陷阱・怪兽的效果，此卡的攻击力直至战斗阶段结束时为止就上升１０００，此回合，此卡在１次战斗阶段中可攻击２次。','\r',char(13)),'\n',char(10)),'效果无效化','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88177325,'编号107 银河眼时空龙',replace(replace('等级８怪兽×２\r\n①：自己的战斗阶段开始时，去除此卡的１个超量素材可以发动。场上此卡以外的所有表侧表示怪兽的效果无效化，其攻击力・守备力变为原本的数值。发动了此效果的回合的战斗阶段中，每当对手发动魔法・陷阱・怪兽的效果，此卡的攻击力直至战斗阶段结束时为止就上升１０００，此回合，此卡在１次战斗阶段中可攻击２次。','\r',char(13)),'\n',char(10)),'效果无效化','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88190453,'铁链思拉舍','此卡除了通常的攻击外，还可以在同１次的战斗阶段中进行与自己墓地存在的“铁链思拉舍”相同数量的攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88190790,'强袭铠甲','我方场上的怪兽仅有１只战士族怪兽的场合，可装备该怪兽。装备怪兽的攻击力上升３００点。可将被装备的此卡送入墓地并发动。此回合装备怪兽在１次的战斗阶段中可攻击２次。','多次攻击','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88197162,'魂之转身',replace(replace('“魂之转身”１回合只可发动１张，此卡发动的回合，我方不可特殊召唤怪兽。\r\n①：我方场上不存在被特殊召唤怪兽的场合，可释放１只我方场上被通常召唤并以表侧表示的等级４怪兽发动。我方从牌组抽取２张卡牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88204302,'疾行复苏','①：以自己墓地的1只“疾行机人”怪兽为对象可以发动。将该怪兽特殊召唤。②：将墓地的此卡除外，以自己墓地的1只“疾行机人”怪兽为对象可以发动。将该怪兽加入手牌。此效果在此卡被送至墓地的回合不可发动。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88205593,'电力眼镜王蛇',replace(replace('①：此卡可直接攻击。\r\n②：此卡以直接攻击给予对手战斗伤害的情况下发动。从牌组将１只“电力”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88210105,'云魔物的云核',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：从手牌将１只“云魔物”怪兽舍弃，以场上的１只表侧表示怪兽为对象可以发动。在对象怪兽上放数量为其等级数值的雾计数物。\r\n②：从自己的墓地将此卡和１只“云魔物”怪兽除外可以发动。从牌组将１只“云魔物”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88225269,'宝石骑士・虚炼原核',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从牌组将1只“宝石骑士”通常怪兽或1张“宝石骑士结合”送至墓地可以发动。从手牌将此卡以守备表示特殊召唤。\r\n②：自己场上存在“宝石骑士”融合怪兽，对手发动效果时，从自己墓地将包含此卡在内的、3张“宝石骑士”卡除外可以发动。将该效果无效。然后，自己场上的所有“宝石骑士”怪兽的攻击力上升1000。','\r',char(13)),'\n',char(10)),'特殊召唤','效果无效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88232397,'熟练的栗魔导士',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：只要此卡存在于怪兽区域，每次自己或对手发动魔法卡，在此卡上放１个魔力计数物（最多３个）。\r\n②：去除此卡的１个魔力计数物，可从以下效果中选择１个发动。\r\n●此卡的等级上升１，攻击力上升１５００。\r\n●从自己的牌组・墓地挑选１只“库里波”怪兽或１张“增殖”加入手牌。','\r',char(13)),'\n',char(10)),'等级和攻击力上升','「库里波」怪兽或者「增殖」加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88234365,'堕天使 特斯卡特利波卡',replace(replace('自己1回合仅可特殊召唤1次“堕天使 特斯卡特利波卡”，其②效果1回合仅可使用1次。\r\n①：自己场上的“堕天使”怪兽将被战斗・效果破坏的情况下，作为代替可将手牌的此卡舍弃。\r\n②：在自己・对手回合中，支付1000LP，以自己墓地的1张“堕天使”魔法・陷阱卡为对象可以发动。适用该魔法・陷阱卡发动时的效果。然后，将该卡放回牌组。','\r',char(13)),'\n',char(10)),'是否使用「堕天使 特斯卡特利波卡」的效果代替破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88234821,'龙骑兵团骑士－日神炎枪',replace(replace('“龙骑兵团”协调＋协调以外的怪兽1只以上\r\n此卡名的①②③效果1回合仅可各使用1次。\r\n①：对手发动怪兽的效果时，从自己墓地将1只“龙骑兵团”怪兽除外可以发动。将该发动无效并除外。\r\n②：此卡战斗破坏对手怪兽的伤害计算后可以发动。将该对手怪兽除外。\r\n③：同步召唤的此卡因对手被破坏的情况下可以发动。将对手场上的魔法・陷阱卡全部破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88236094,'阿斯旺的亡灵','此卡给予对手玩家战斗伤害的场合可发动。选择我方墓地的１张陷阱卡返回至牌组的最上面。','返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88240808,'灵灭术师 海空','①：只要此卡存在于怪兽区域，对手不可除外双方墓地的卡。②：此卡给予对手战斗伤害时，以对手墓地最多2只怪兽为对象可以发动。将该怪兽除外。','选对手墓地2只怪兽除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88240999,'决战兵器的影灵衣',replace(replace('以“影灵衣”仪式魔法卡降临\r\n此卡仅可以仪式召唤方式特殊召唤，且仪式召唤仅可使用等级10以外的怪兽。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己・对手回合中，从手牌将此卡舍弃，以自己场上的1只“影灵衣”怪兽为对象可以发动。该怪兽的攻击力・守备力直至回合结束时为止上升1000。\r\n②：以对手场上1张里侧表示的卡为对象可以发动。将该卡破坏并除外。','\r',char(13)),'\n',char(10)),'攻守上升','破坏并除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88241506,'青之眼少女','此卡名的①②效果1回合1次，仅可使用其中1个。①：以场上的此卡为对象的魔法・陷阱・怪兽的效果发动时可以发动。从自己的手牌・牌组・墓地挑选1只“青眼白龙”特殊召唤。②：此卡被选择为攻击对象时可以发动。使该攻击无效，并更改此卡的表示形式。然后，可从自己的手牌・牌组・墓地挑选1只“青眼白龙”特殊召唤。','攻击无效','特殊召唤','是否要选择「青眼白龙」特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88264978,'真红眼暗铁龙',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次，且②效果1回合仅可使用1次。\r\n①：此卡可通过将自己场上的1只表侧表示的龙族怪兽除外，来从手牌特殊召唤。\r\n②：在自己的主要阶段可以发动。从自己手牌・墓地将“真红眼暗铁龙”以外的1只龙族怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88264979,'真红眼暗铁龙',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次，且②效果1回合仅可使用1次。\r\n①：此卡可通过将自己场上的1只表侧表示的龙族怪兽除外，来从手牌特殊召唤。\r\n②：在自己的主要阶段可以发动。从自己手牌・墓地将“真红眼暗铁龙”以外的1只龙族怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88279736,'强盗格布林','当我方场上的怪兽对对手生命造成战斗伤害时，随机弃置对手１张手牌。','对手随机丢弃1张手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88283496,'极星兽 加尔姆','此卡与等级４或以下的怪兽进行了战斗的伤害计算后可发动。将该怪兽返回至手牌。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88284599,'肃声之龙贤圣 萨拉维思',replace(replace('此卡名以①方法的特殊召唤１回合仅可进行１次，且②效果１回合仅可使用１次。\r\n①：此卡可借由从自己的手牌・墓地将包含仪式魔法卡在内的２张魔法卡放回牌组，来从手牌特殊召唤。\r\n②：对手发动卡的效果时，将场上的此卡放回手牌可以发动。从手牌・牌组将１只战士族・龙族的光属性仪式怪兽特殊召唤。以此效果特殊召唤的怪兽将在下个回合的结束阶段放回牌组。','\r',char(13)),'\n',char(10)),'特殊召唤仪式怪兽','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88289295,'同步操作','我方场上以及我方墓地不存在有同步怪兽的场合，可支付１０００LP，并选择对手场上的１只同步怪兽发动。直至我方的结束阶段时，获得被选择怪兽的控制权。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88301393,'狱炎机・阿德拉梅莱克',replace(replace('此卡不可通常召唤。\r\n仅可在自己场上的效果怪兽的等级・阶级的合计为８以下时，将自己的手牌・墓地的２只“狱炎机”怪兽除外的情况下从手牌・墓地特殊召唤。\r\n①：此卡战斗破坏对手怪兽并将其送至墓地时可以发动。此卡可继续再攻击仅１次。\r\n②：在每个自己・对手回合中１次，解放自己场上的１只怪兽，以对手墓地的１张卡为对象可以发动。将该卡除外。','\r',char(13)),'\n',char(10)),'连续攻击','对手墓地的卡除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88301833,'升华之魂','仪式怪兽仪式召唤成功时，可选择１只因该仪式召唤释放的存在于我方墓地的１只怪兽加入手牌。此效果１回合只可使用１次。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88305705,'勇气眼灵摆龙',replace(replace('“灵摆龙”怪兽＋战士族怪兽\r\n①：此卡融合召唤成功时可以发动。对手场上所有怪兽的攻击力变为０。此回合，此卡以外的自己的怪兽不可攻击。②：只要此卡存在于怪兽区域，攻击力０的怪兽发动的效果无效化。③：此卡攻击对手怪兽但未将其破坏的伤害步骤结束时可以发动。将该对手怪兽除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88305978,'黑羽－阳炎的卡姆','对手的战斗阶段时，我方场上不存在有怪兽的场合，可将墓地的此卡从游戏中除外并发动。选择我方墓地的１只同步怪兽并特殊召唤。以此效果特殊召唤的怪兽在战斗阶段结束时，从游戏中被除外。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88307361,'超古深海王 空棘鱼',replace(replace('①：１回合１次，舍弃１张手牌可以发动。从牌组将等级４以下的鱼族怪兽尽可能地特殊召唤。以此效果特殊召唤的怪兽不可攻击宣言，效果无效化。\r\n②：以场上的此卡为对象的魔法・陷阱・怪兽的效果发动时，解放自己场上１只其他的鱼族怪兽可以发动。将该效果无效并破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','效果无效并破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88316955,'机怪虫・棘','此卡名的①②效果1回合仅可各使用1次。①：此卡反转的情况下，以场上的1只怪兽为对象可以发动。将该怪兽破坏。②：表侧表示的此卡因对手的效果从场上离开的情况下可以发动。将2只“机怪虫・棘”以外的“机怪虫”怪兽从牌组以里侧守备表示特殊召唤（同名卡最多1张）。','怪兽破坏','2只怪兽特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88332693,'爆裂模式・零','此卡名的①②效果1回合仅可各使用1次。①：解放自己场上的1只同步怪兽可以发动。将1只包括该怪兽卡名的“/爆裂”怪兽视为由“爆裂模式”的特殊召唤从手牌特殊召唤。②：在自己的主要阶段将墓地的此卡除外可以发动。从手牌・牌组挑选1张“爆裂模式”放置在自己的魔法与陷阱区域。以此效果放置的卡在放置的回合中也可以发动。','','','适用「爆裂模式・零」的效果来发动','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88341502,'黑箭','选择自己场上的１只表侧表示怪兽可以发动。直至回合结束时为止，该怪兽的攻击力下降５００点，攻击了守备表示怪兽时，若攻击力超过了该守备力，则给予对手LP超过数值的战斗伤害。此回合，被选择的怪兽战斗破坏怪兽并将其送往墓地时，给予对手LP被破坏怪兽的原本守备力数值的伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88346805,'斩余番长',replace(replace('①：在卡的效果发动１０次以上的回合，可以发动此卡。发动后，变为效果怪兽（电子界族・暗・星１０・攻／守３０００），特殊召唤至怪兽区域（也视为陷阱卡）。以此效果特殊召唤的此卡将在自己的结束阶段被放置在自己的魔法与陷阱区域。\r\n②：１回合１次，此卡存在于怪兽区域、对手发动卡的效果时可以发动。将对手场上的卡全部破坏。然后，将此卡放置在自己的魔法与陷阱区域。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88358139,'娱乐伙伴 帮手公主','①：自己召唤・特殊召唤“娱乐伙伴 帮手公主”以外的“娱乐伙伴”怪兽成功时可以发动。从手牌将此卡特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88361177,'龙骑兵团－窄带军政官','①：装备着龙族的“龙骑兵团”怪兽卡的此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88369727,'愚蠢的转生','可选择对手墓地的１张卡牌并发动。将被选择的卡牌返回至牌组。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88392300,'电送拟人 电力念动','①：将手牌・场上的此卡送至墓地，以对手场上的1只怪兽为对象可以发动。将该对手怪兽的位置移动至对手的其他主要怪兽区域。此效果在对手回合中也可以发动。','请选择要移动位置的怪兽','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88406570,'刚鬼 覆灭食人魔',replace(replace('“刚鬼”怪兽2只以上\r\n此卡名的②效果1回合仅可使用1次。①：此卡连接端的怪兽1回合仅1次不会因战斗被破坏。②：在自己的主要阶段可以发动。对手从自身的墓地挑选最多2只怪兽特殊召唤。然后，自己从自己的墓地挑选连接怪兽以外“刚鬼”怪兽特殊召唤至此卡的连接端，数量最多为对手特殊召唤的怪兽数量。此效果发动后，直至回合结束时为止自己仅可特殊召唤“刚鬼”怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88409165,'深渊战士','１回合１次，可从手牌将１只水属性怪兽舍弃至墓地，选择我方或对手墓地的１只怪兽并发动。被选择的怪兽返回至持有者牌组的最上方或最下方。','返回牌组','回到牌组最上面','回到牌组最下面','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88412339,'魔界剧团－群演',replace(replace('←3 【灵摆】 3→\r\n此卡名的灵摆效果１回合仅可使用１次。①：对手场上有怪兽存在的情况下可以发动。将灵摆区域的此卡特殊召唤。\r\n【怪兽效果】\r\n此卡名的怪兽效果１回合仅可使用１次。①：解放此卡可以发动。从牌组挑选１只“魔界剧团”灵摆怪兽放在自己的灵摆区域。此效果发动后，直至回合结束时为止自己仅可特殊召唤“魔界剧团”怪兽，不可发动“魔界剧团－群演”的灵摆效果。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88413677,'郁闷闷＠伊格尼斯者','此卡名的①②效果1回合仅可各使用1次。①：此卡召唤・特殊召唤成功的情况下，以自己墓地的1只“＠伊格尼斯者”怪兽为对象可以发动。将该怪兽加入手牌。②：此卡作为电子界族连接怪兽的连接素材被送至墓地的情况下，以自己墓地的1张“-艾-”魔法・陷阱卡为对象可以发动。将该卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88435542,'火焰之眼','被火焰包围着的眼球，挥动翅膀就能掀起火焰之风。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88438982,'异虫狄米库雷斯','反转：此卡的攻击力、守备力上升３００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88453933,'龙女仆・侍应龙女',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将“龙女仆・侍应龙女”以外的1张“龙女仆”卡送至墓地。\r\n②：在自己・对手的战斗阶段开始时可以发动。将此卡放回手牌，从自己手牌・墓地将1只等级8的“龙女仆”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88472456,'暗黑英雄 尸魔侠','①：此卡不可直接攻击。②：此卡战斗破坏怪兽的情况下发动。此卡的攻击力下降２００。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88477149,'极寒冰柱',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：将2只“冰柱衍生物”（水族・水・星4・攻1900/守1200）以守备表示特殊召唤至自己场上。此卡发动后，直至回合结束时为止，自己不可从额外牌组特殊召唤怪兽。\r\n②：在自己的主要阶段将墓地的此卡除外可以发动。进行1只水属性怪兽的召唤。','\r',char(13)),'\n',char(10)),'特殊召唤衍生物','进行召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88477150,'冰柱衍生物','由“极寒冰柱”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88482761,'掷骰战斗',replace(replace('①：对手怪兽的攻击宣言时，可以我方墓地的１只“疾行机人”怪兽为对象发动。将该怪兽与手牌的１只“疾行机人”协调除外，并从额外牌组特殊召唤１只持有等级与该２只怪兽的原本等级合计相同的同步怪兽。\r\n②：在对手战斗步骤将墓地的此卡除外，并可以我方及对手场上表侧攻击表示的同步怪兽各１只为对象发动。该对手的表侧攻击表示怪兽攻击该我方怪兽，并进行伤害计算。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88494120,'不屈的斗志','①：我方场上的表侧表示怪兽仅是１只的场合，可以该１只怪兽为对象发动。直至回合结束时，该怪兽的攻击力上升相当于对手场上的攻击力最低怪兽之攻击力数值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88494899,'冰结界的交灵师',replace(replace('①：对手场上的卡的数量比自己场上的卡多４张以上的情况下，此卡可从手牌特殊召唤。\r\n②：只要此卡存在于自己的怪兽区域，在此期间，对手１回合仅可发动１张魔法・陷阱卡。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88504133,'升阶魔法－魅影之力','此卡名的卡１回合仅可发动１张。①：在自己・对手的主要阶段，从自己的墓地将任意数量的暗属性怪兽除外，以自己场上１只暗属性超量怪兽为对象可以发动。将阶级比自己的该怪兽高出与除外数量同数值的１只“魅影骑士团”、“急袭猛禽”、“超量龙”超量怪兽重叠在对象怪兽上面，视为超量召唤从额外牌组特殊召唤。此卡发动后，直至回合结束时为止自己从额外牌组仅可特殊召唤超量怪兽。','特殊召唤','请选择要除外的怪兽的数量','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88513608,'舍身的宝牌','我方场上的２只或以上的攻击表示怪兽的攻击力合计低于对手场上攻击力最低怪兽的场合，从我方的牌组抽取２张卡牌。发动此卡的回合，我方不可召唤、反转召唤、特殊召唤怪兽，也不可变更表示形式。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88540324,'转生炎兽之烈爪','只有“转生炎兽”怪兽才能装备。①：“转生炎兽之烈爪”在自己场上只能有1张以表侧表示形式存在。②：装备怪兽不会被战斗・效果破坏，对守备表示怪兽进行攻击的情况下，给对手造成攻击力超出其守备力数值的战斗伤害。③：装备怪兽是用和自身同名的怪兽为素材进行连接召唤的自己的“转生炎兽”连接怪兽的情况下，装备怪兽在1次战斗阶段中可以向怪兽作出至多为该连接标记数量的攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88544390,'魅影骑士团脏胫甲',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：“魅影骑士团”怪兽被特殊召唤至自己场上的情况下可以发动。从手牌将此卡特殊召唤。然后，可将此卡的等级上升1。\r\n②：将墓地的此卡除外可以发动。从手牌将“魅影骑士团脏胫甲”以外的1只“魅影骑士团”怪兽特殊召唤。然后，可将该怪兽的等级上升1。','\r',char(13)),'\n',char(10)),'','自身是否上升等级？','是否上升等级？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88552992,'先史遗产黄金飞船','１回合１次，可在我方主要阶段时发动。使我方场上所有冠有“先史遗产”之名怪兽的等级上升１级。','等级上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88554436,'破械神 修耶摩',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：以自己场上的1张卡为对象可以发动。将该卡破坏。然后，可将场上的1张魔法・陷阱卡破坏。\r\n②：此卡存在于墓地的情况下，以自己场上的1只恶魔族怪兽或1张里侧表示卡为对象可以发动。将该卡破坏，将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，放回牌组最下面。','\r',char(13)),'\n',char(10)),'','是否把场上1张魔法·陷阱卡破坏？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88559132,'炮塔战士','此卡可释放我方场上的１只战士族怪兽并从手牌特殊召唤。以此方法特殊召唤而来的此卡攻击力上升被释放怪兽的原本攻击力数值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88570003,'王之仆从－黑魔导',replace(replace('此卡名的②③效果1回合1次，仅可使用其中1个。\r\n①：此卡只要存在于场上・墓地，卡名视为“黑魔导”。\r\n②：此卡存在于手牌的情况下，向对手出示手牌的1张魔法卡可以发动。将此卡特殊召唤。然后，可从牌组将1张记载有“黑魔导”卡名的魔法・陷阱卡放置在自己场上。\r\n③：在自己・对手回合中，从手牌将1张魔法卡舍弃可以发动。将对手场上的魔法・陷阱卡全部破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','破坏','是否放置？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88570004,'王之仆从－黑魔导',replace(replace('此卡名的②③效果1回合1次，仅可使用其中1个。\r\n①：此卡只要存在于场上・墓地，卡名视为“黑魔导”。\r\n②：此卡存在于手牌的情况下，向对手出示手牌的1张魔法卡可以发动。将此卡特殊召唤。然后，可从牌组将1张记载有“黑魔导”卡名的魔法・陷阱卡放置在自己场上。\r\n③：在自己・对手回合中，从手牌将1张魔法卡舍弃可以发动。将对手场上的魔法・陷阱卡全部破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','破坏','是否放置？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88581108,'真龙皇 神子灾兽',replace(replace('等级9怪兽×2只以上\r\n①：1回合1次，去除此卡的1个超量素材，宣言1个属性可以发动。此回合适用以下效果。此效果在对手回合中也可以发动。\r\n●场上的表侧表示怪兽变成宣言的属性，宣言的属性的对手怪兽不可攻击，不可发动效果。\r\n②：只要此卡存在于怪兽区域，因自己手牌的“真龙”怪兽的效果破坏的怪兽也可从对手场上挑选。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88610708,'盾牌猛击',replace(replace('仅限装备被通常召唤的怪兽。\r\n①：装备怪兽的攻击力上升１０００。\r\n②：因装备怪兽战斗而造成的我方战斗伤害变为０。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88616795,'律法的魔导书',replace(replace('选择场上的１只魔法师族怪兽，并可从以下效果中选择１个发动。\r\n●此回合，被选择怪兽不受除此卡以外的魔法卡的效果影响。\r\n●此回合，被选择怪兽不受陷阱卡的效果影响。','\r',char(13)),'\n',char(10)),'不受此卡以外的魔法卡的效果影响','不受陷阱卡的效果影响','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88617904,'升变',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：以自己场上１只等级３以下的战士族・地属性怪兽为对象可以发动。将该怪兽送至墓地，从牌组将１只等级４以上的战士族・地属性怪兽特殊召唤。然后，自己场上有原本种族・属性为战士族・地属性的“傀偶”怪兽存在的情况下，以此效果特殊召唤的怪兽的攻击力・守备力上升相当于对手墓地卡的数量×１００的数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88619463,'黑魔法神官',replace(replace('此卡不可通常召唤。\r\n仅限解放我方场上２只等级６以上的魔法师族怪兽的场合，可特殊召唤。\r\n①：陷阱卡发动时可发动。此卡以表侧表示存在于场上的场合，使该发动无效并破坏。','\r',char(13)),'\n',char(10)),'陷阱发动无效并破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88643173,'恶梦毒蝎','令人陷入恶梦，并在其呻吟时用四条有毒的尾巴发动突刺攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88643579,'暗黑终极龙',replace(replace('协调＋协调以外的暗属性怪兽1只以上\r\n①：1回合1次，以对手场上的1只怪兽为对象可以发动。此卡的攻击力・守备力下降500，将该对手怪兽送至墓地。','\r',char(13)),'\n',char(10)),'对手场上存在的1只怪兽送至墓地。','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88650530,'异虫阿波克立普斯','反转：选择场上的１张魔法、陷阱卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88654892,'突然回归',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：解放自己场上的１只融合・同步怪兽可以发动。从牌组将１只等级与所解放怪兽原本等级相同的怪兽特殊召唤。以此效果特殊召唤的怪兽将在结束阶段被放回手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88667504,'超整地破碎','此卡名的①②效果１回合仅可各使用１次。①：自己场上表侧表示的机械族・地属性怪兽因战斗・效果被破坏的情况下，以场上的１张卡为对象可以发动。将该卡破坏。②：将墓地的此卡除外可以发动。从自己的牌组・墓地挑选１张“超接地展开”或“超原地转向”，放置在自己的魔法与陷阱区域。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88671720,'黑炸弹','此卡召唤成功时可发动。从我方墓地挑选１只机械族、暗属性、等级４怪兽并以守备表示特殊召唤。以此效果特殊召唤怪兽的效果被无效化。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88685329,'暗眼梦魇',replace(replace('此卡名的①效果１回合仅可使用１次。①：将自己墓地的最多３张陷阱卡除外可以发动。根据除外的数量适用以下效果。\r\n●１张：自己从牌组抽１张，然后挑选１张手牌放回牌组最上面。\r\n●２张：自己从牌组抽１张。\r\n●３张：自己从牌组抽２张，然后挑选１张手牌舍弃。\r\n②：１回合１次，此卡将被战斗破坏的情况下，可将自己墓地的１张陷阱卡除外作为代替。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88686573,'迅捷鮟鱇','①：此卡从手牌・牌组被送至墓地的情况下可以发动。将“迅捷鮟鱇”以外的最多２只等级３以下的“迅捷”怪兽从牌组特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88693151,'淘气仙星・结合',replace(replace('①：将自己的手牌・场上的怪兽作为融合素材，将１只“淘气仙星”融合怪兽融合召唤。\r\n②：将墓地的此卡除外，以自己墓地的１只“淘气仙星”怪兽为对象可以发动。将该怪兽加入手牌。此回合，自己不可通常召唤・特殊召唤以此效果加入手牌的怪兽及其同名怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88695895,'罪宝的咎人',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己场上存在“迪亚贝尔斯塔”怪兽卡，且对手从牌组・额外牌组将怪兽特殊召唤的情况下，以对手场上的１只怪兽为对象可以发动。将该怪兽放回牌组。\r\n②：从自己的“迪亚贝尔斯塔”怪兽与对手怪兽进行战斗的伤害步骤开始时直至伤害计算前为止，将墓地的此卡除外可以发动。该对手怪兽的攻击力直至回合结束时为止变为一半。','\r',char(13)),'\n',char(10)),'回牌组','攻击力变成一半','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88696724,'融合咒印生物－地','此卡可代替融合素材怪兽的其中１只来进行融合。不过此时其他的融合素材怪兽必须是指定的怪兽。可解放我方场上包括此卡在内的融合素材怪兽，从额外牌组特殊召唤１只地属性的融合怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88722973,'升龙剑士 威风行者 圣骑',replace(replace('等级４的灵摆怪兽×２\r\n①：此卡超量召唤时可以发动。在此回合的结束阶段，从牌组将１只灵摆怪兽加入手牌。\r\n②：１回合１次，去除此卡的１个超量素材可以发动。从自己的额外牌组（表侧）将１只“龙剑士”灵摆怪兽特殊召唤。以此效果特殊召唤的怪兽不可作为超量召唤的素材。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88724332,'夜龙巫妖','①：只要此卡存在于怪兽区域，从牌组・额外牌组被特殊召唤的幻龙族以外的攻击表示怪兽变为守备表示。②：只要此卡存在于怪兽区域，从牌组・额外牌组被特殊召唤的幻龙族以外的怪兽的守备力下降相当于其原本守备力的数值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88728507,'吸血鬼巫师','①：此卡被对手送至墓地的情况下可以发动。从牌组将１只暗属性的“吸血鬼”怪兽或１张“吸血鬼”魔法・陷阱卡加入手牌。②：将墓地的此卡除外可以发动。此回合仅１次，自己召唤等级５以上的暗属性“吸血鬼”怪兽的情况下，可免除所必需的解放。','检索','减少解放数量','不解放进行召唤（吸血鬼巫师）','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88733579,'穿孔虫','此卡给予对手战斗伤害时，可将存在于我方牌组中１张“寄生虫 帕拉赛德”放置到牌组的最上面。','检索','请选择要放置在牌组最上面的卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88753594,'月光舞剑虎姬',replace(replace('“月光”怪兽×3\r\n此卡仅可以融合召唤方式特殊召唤。\r\n此卡名的③效果1回合仅可使用1次。\r\n①：此卡的攻击力上升双方墓地・除外状态的兽战士族怪兽数量×200的数值。\r\n②：对手不可将场上的此卡作为效果的对象。\r\n③：从墓地将不是在此回合被送至墓地的此卡除外，以自己场上的1只融合怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止上升3000。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88753985,'狐火','只要此卡以表侧表示存在于场上，不可进行以上级召唤为目的的解放。此卡因战斗被破坏并送入墓地回合的结束阶段发动。从墓地特殊召唤此卡。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88754763,'混沌超量 热血指导神 究极训练师',replace(replace('等级9怪兽×4\r\n①：双方不可将场上的此卡作为效果的对象。\r\n②：此卡持有超量怪兽作为超量素材的情况下，获得以下效果。\r\n●1回合1次，去除此卡的1个超量素材可以发动。自己抽1张，给双方确认。其为怪兽的情况下，进而给予对手800伤害。','\r',char(13)),'\n',char(10)),'抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88757791,'法眼的魔术师',replace(replace('←2 【灵摆】 2→\r\n①：１回合１次，将手牌的１只灵摆怪兽出示给对手，以自己灵摆区域的１张“魔术师”卡为对象可以发动。该“魔术师”卡的灵摆刻度直至回合结束时为止，变为与所出示的灵摆怪兽的灵摆刻度相同。\r\n【怪兽效果】\r\n①：只要在此回合灵摆召唤的此卡存在于怪兽区域，自己场上的“魔术师”灵摆怪兽不会因对手的效果被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88760522,'多样进化','此卡名的卡１回合仅可发动１张。①：从牌组将１只“进化虫”怪兽或“进化龙”怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88774734,'螺旋龙 核球',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡存在于手牌・墓地，且自己场上存在２只以上光・暗属性的龙族怪兽的情况下可以发动。将此卡以守备表示特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。\r\n②：在自己的主要阶段可以发动。自己场上的所有怪兽的等级直至回合结束时为止变为８。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88789641,'神圣生命防护罩','可舍弃１张手牌并发动。此回合，受到来自对手的伤害全部变成０，我方怪兽不因与对手怪兽的战斗而破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88819587,'宝贝龙','切不可因其为幼年龙而藐视之。其中隐藏的力量不可估量。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88820235,'元素－英雄 闪光凤凰小子',replace(replace('“元素－英雄 凤凰小子”＋“元素－英雄 闪光人”\r\n此卡仅可以融合召唤特殊召唤。此卡的攻击力上升相当于我方墓地冠有“元素－英雄”之名卡牌数量×３００点。此卡不会因战斗而被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88836438,'电光闪灵・粉碎者乱斗',replace(replace('此卡名的卡１回合仅可发动１张。①：从自己的手牌・墓地将“守宝团”卡、“兽带斗士”卡、“电光闪灵”卡中的任意１张除外，可从以下效果中选择１个发动。\r\n●从牌组将１只“守宝团”怪兽特殊召唤。\r\n●从自己墓地挑选１只“兽带斗士”怪兽特殊召唤。\r\n●挑选自己场上的１只等级２・阶级２・连接２的怪兽和对手场上的１张卡除外。','\r',char(13)),'\n',char(10)),'从牌组把1只「守宝团」怪兽特殊召唤','从自己墓地选1只「兽带斗士」怪兽特殊召唤','选自己和对手场上各1张卡除外','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88845345,'小飞象','此卡因战斗被破坏并送入墓地时可发动。选择１只从游戏中被除外的我方等级３或以下的兽族、兽战士族、鸟兽族怪兽并加入手牌。','加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88851326,'热血的决斗者们',replace(replace('①：自己怪兽的攻击宣言时，以对手场上１张魔法・陷阱卡为对象可以发动。使该攻击无效，破坏对象卡。\r\n②：只要此卡存在于魔法与陷阱区域，双方１回合仅可从手牌放置１张魔法・陷阱卡，从额外牌组被特殊召唤的怪兽该回合不可攻击。\r\n③：自己的抽牌阶段的抽牌前可以发动。挑选自己墓地的１只怪兽加入手牌，作为此回合进行通常抽牌的代替。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88875132,'爆走轨道飞翔天马',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下，以“爆走轨道飞翔天马”以外的、自己墓地的1只机械族・地属性怪兽为对象可以发动。将该怪兽的效果无效并以守备表示特殊召唤。\r\n②：以自己场上的1只其他表侧表示怪兽为对象可以发动（发动此效果的回合中，自己仅可用超量怪兽攻击宣言）。将该怪兽和此卡中的1只的等级改为和另1只的等级相同。','\r',char(13)),'\n',char(10)),'','','请选择持有目标等级的怪兽','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88875133,'爆走轨道飞翔天马',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下，以“爆走轨道飞翔天马”以外的、自己墓地的1只机械族・地属性怪兽为对象可以发动。将该怪兽的效果无效并以守备表示特殊召唤。\r\n②：以自己场上的1只其他表侧表示怪兽为对象可以发动（发动此效果的回合中，自己仅可用超量怪兽攻击宣言）。将该怪兽和此卡中的1只的等级改为和另1只的等级相同。','\r',char(13)),'\n',char(10)),'','','请选择持有目标等级的怪兽','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88890658,'烧烤之巴格力尔・饿魔新飨',replace(replace('以“食谱”卡降临\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡特殊召唤的情况下可以发动。将对手场上所有表侧表示卡的效果直至回合结束时为止无效。以“饿魔新飨”怪兽的效果特殊召唤的情况下，进而将对手场上的怪兽尽可能地解放。\r\n②：在自己・对手回合中，以对手场上１只攻击表示的怪兽为对象可以发动。解放该怪兽，从手牌・牌组将１只“饥饿汉堡”特殊召唤。','\r',char(13)),'\n',char(10)),'对方卡无效','从手牌·牌组特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88901771,'熟练的青魔道士',replace(replace('①：只要此卡存在于怪兽区，每次我方或对手发动魔法卡，放置１个魔力计数物在此卡（最多３个）。\r\n②：可释放放置有３个魔力计数物的此卡并发动。从我方的手牌、牌组、墓地挑选１只“暗黑骑士盖亚”怪兽特殊召唤。\r\n③：可在我方主要阶段，将墓地的此卡除外，并以我方场上１张可放置魔力计数物的卡牌为对象发动。放置１个魔力计数物在此卡。','\r',char(13)),'\n',char(10)),'放置1个魔力计数物','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88901994,'同步轰鸣',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：以自己墓地的1只协调或1只等级7・8的龙族同步怪兽为对象可以发动。将该怪兽以守备表示特殊召唤。此卡发动后，直至回合结束时为止，自己从额外牌组仅可特殊召唤同步怪兽。\r\n②：自己场上的“赤龙”或等级7・8的龙族同步怪兽将被战斗・效果破坏的情况下，作为代替可将墓地的此卡除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88917691,'我我我我女孩',replace(replace('等级4怪兽×2\r\n此卡名的①效果1回合仅可使用1次。\r\n①：此卡持有“刷拉拉”、“我我我”、“隆隆隆”、“怒怒怒”卡中的任一作为超量素材的情况下，去除此卡的1个超量素材可以发动。从牌组将“我我我”、“拟声”、“超量”卡中的任意1张加入手牌。\r\n②：持有此卡作为超量素材的“未来皇霍普”超量怪兽获得以下效果。\r\n●此卡超量召唤的情况下发动。此回合，此卡在1次战斗阶段中可攻击2次。','\r',char(13)),'\n',char(10)),'','2次攻击（我我我我女孩）','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88919365,'弈勇之武者－北条',replace(replace('←1 【灵摆】 1→\r\n此卡名的灵摆效果１回合仅可使用１次。①：场地区域有“弈勇世界－真罗万象”存在的情况下，或自己场上有水属性的“弈勇”怪兽存在的情况下可以发动。将此卡特殊召唤至正面的自己的主要怪兽区域。\r\n【怪兽效果】\r\n此卡名的①②怪兽效果１回合仅可各使用１次。①：以魔法与陷阱区域的１张表侧表示的卡为对象可以发动。将该卡放回持有者的手牌。②：怪兽区域的此卡移动至其他怪兽区域的情况下可以发动。从自己的手牌・场上，将由“弈勇”融合怪兽卡决定的融合素材怪兽送至墓地，从额外牌组将１只该融合怪兽融合召唤。在此之际，自己灵摆区域存在的融合素材怪兽也可以作为融合素材使用。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88923963,'圣骑士伊文',replace(replace('此卡牌名的①效果１回合只可使用１次。\r\n①：此卡装备了“圣剑”装备魔法卡的场合可发动。特殊召唤１只“圣骑士衍生物”（战士族、光、星４、攻／守１０００）至我方场上。此效果发动后，直至回合结束时，我方只可特殊召唤“圣骑士”怪兽。\r\n②：只要此卡装备有“圣剑”装备魔法卡，我方场上除此卡以外的“圣骑士”怪兽的攻击力上升５００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88923964,'圣骑士衍生物','由“圣骑士伊文”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88926295,'禁咒仪・灵智涅瑞伊斯','以“咒仪”仪式魔法卡降临。①：此卡仪式召唤成功的情况下，以自己墓地的１只水属性怪兽为对象可以发动。将该怪兽特殊召唤。②：此卡不会因与被从额外牌组特殊召唤的怪兽的战斗而被破坏。③：１回合１次，对手发动怪兽的效果时可以发动。挑选自己场上的１只“咒仪”仪式怪兽放回持有者的手牌，将该发动无效，放回持有者的牌组。','墓地怪兽特殊召唤','无效并回到牌组','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88928798,'炸弹防御','仅以我方场上的１只怪兽为对象破坏，怪兽的效果、魔法、陷阱卡发动时可发动。使该发动无效并破坏。之后，给予对手生命５００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88931417,'加特林食人魔',replace(replace('此卡名的①效果1回合最多可使用3次。\r\n①：将自己魔法与陷阱区域任意数量的里侧表示卡送至墓地可以发动。给予对手送至了墓地的数量×800的伤害。此效果发动后，直至回合结束时为止，对手因恶魔族以外的怪兽的效果受到的所有效果伤害变为0。\r\n②：1回合1次，此卡被选择为攻击对象时可以发动。给予对手相当于对手场上的攻击表示怪兽数量×500的伤害。然后，结束战斗阶段。','\r',char(13)),'\n',char(10)),'给与伤害','给与伤害并结束战斗阶段','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88935103,'贵龙的魔术师',replace(replace('←5 【灵摆】 5→\r\n①：另一方自己的灵摆区域没有“魔术师”卡存在的情况下，此卡将被破坏。\r\n【怪兽效果】\r\n以此卡作为同步素材的情况下，仅可用于龙族怪兽的同步召唤，其他同步素材使用了“异色眼”怪兽以外的怪兽的情况下，将此卡放回持有者牌组最下面。①：此卡存在于手牌・墓地的情况下，以自己场上的１只等级７以上“异色眼”怪兽为对象可以发动。该怪兽的等级下降３，将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'在灵摆区发动','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88940154,'武斗神器－蜂','我方场上存在冠有“武斗神”之名兽战士族怪兽的场合，可将墓地的此卡从游戏中除外并发动。选择对手场上的１张魔法、陷阱卡破坏。“武斗神器－蜂”的效果１回合只可使用１次。','魔陷破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88942504,'管魔人・迷迷旋律',replace(replace('等级３怪兽×２\r\n１回合１次，可移除此卡的１个超量素材，并选择我方场上１只冠有“魔人”之名的超量怪兽发动。此回合，被选择怪兽在１次的战斗阶段中可攻击２次。','\r',char(13)),'\n',char(10)),'多次攻击','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88958576,'岩浆炎燃烧者','我方墓地冠有“岩浆炎”之名的怪兽为３种或以上的场合，此卡可从手牌特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88962829,'骑甲虫 轻盈振翅兵',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡召唤・特殊召唤的情况下，以自己墓地・除外状态的２只“骑甲虫”怪兽为对象可以发动（同名卡最多１张）。将该怪兽加入手牌。此回合，自己不可发动以此效果加入手牌的卡及其同名卡的效果。\r\n②：对手怪兽攻击宣言时可以发动。将此卡放回手牌，将该攻击无效。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88975532,'漆黑战士 战狼','①：只要此卡存在于怪兽区域，对手在战斗阶段不可发动陷阱卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88979991,'杀手蜂','身形硕大的黄蜂。会发动意料之外的强力攻击。如果被其群起而攻可就大为不妙了。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88989706,'大神官 迪・扎德',replace(replace('每次此卡因战斗破坏怪兽，获得以下效果。\r\n●第１次：以场上的此卡为对象的魔法・陷阱卡发动时发动。使该发动无效并破坏。\r\n●第２次：可解放此卡并发动。从手牌・牌组特殊召唤１只“不死王巫妖”。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(88996322,'剑斗兽 韦斯帕西亚斯',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：自己的“剑斗兽”怪兽与怪兽进行战斗的伤害步骤开始时可以发动。从手牌将此卡特殊召唤。\r\n②：只要以“剑斗兽”怪兽的效果特殊召唤的此卡存在于怪兽区域，自己场上的怪兽的攻击力上升５００。\r\n③：此卡进行过战斗的战斗阶段结束时，将此卡放回牌组可以发动。从牌组将“剑斗兽 韦斯帕西亚斯”以外的１只“剑斗兽”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89015998,'异次元的探求者',replace(replace('此卡牌名的效果１回合只可使用１次。\r\n①：可以我方场上的１只表侧表示怪兽为对象发动。直至下一回合的结束阶段，将该怪兽除外。此效果在对手回合也可发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89016236,'生煎之布娃雷提斯・饿魔新飨',replace(replace('以“食谱”卡降临\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡特殊召唤的情况下可以发动。自己抽１张。\r\n②：场上的怪兽成为攻击・效果的对象时可以发动。解放自己场上的１只“饿魔新飨”怪兽和自己・对手场上的１只攻击表示怪兽，从手牌・牌组将１只等级４・５的“饿魔新飨”仪式怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'抽1张卡','从手牌·牌组特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89019964,'破械神之祸灵',replace(replace('此卡名的②③效果1回合仅可各使用1次。\r\n①：此卡的攻击力上升自己墓地的“破械”卡的数量×300的数值。\r\n②：以对手场上的1只表侧表示怪兽为对象可以发动。仅以该对手怪兽和自己场上的此卡作为素材，进行1只暗属性连接怪兽的连接召唤。\r\n③：场上的此卡因战斗・效果被破坏的情况下，以“破械神之祸灵”以外的、自己墓地的1只“破械”怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89023486,'原罪宝－蛇眼',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：将自己场上此卡以外的１张表侧表示卡送至墓地可以发动。从手牌・牌组将１只炎属性・等级１怪兽特殊召唤。\r\n②：将墓地的此卡除外，以自己墓地的１只“蛇眼”怪兽或“迪亚贝尔斯塔”怪兽为对象可以发动。从牌组将１只炎属性・等级１怪兽加入手牌。然后，将对象怪兽放回牌组最下面。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89027419,'欺诈师衍生物','由「欺诈转移」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89040386,'黑羽－反击爆炎','我方墓地存在有５只或以上冠有“黑羽”之名怪兽的场合，在对手怪兽的直接攻击宣言时可发动。破坏对手场上的所有怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89041555,'牲祭怀抱的爆弹','①：被上级召唤的对手怪兽进行攻击宣言时可发动。破坏对手场上表侧攻击表示的所有怪兽，给予对手１０００伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89055154,'力天使瓦尔基里',replace(replace('此卡牌名的效果１回合只可使用１次。\r\n①：我方使怪兽的效果、魔法、陷阱卡的发动变为无效的场合发动。从牌组将１只天使族、光属性怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89058026,'EN波动','此卡名的①②效果１回合仅可各使用１次。①：自己的“元素－英雄”怪兽被作为融合怪兽融合召唤的素材，并被送至墓地的情况下或被除外的情况下可以发动。从牌组将１只“新空间人”怪兽或“元素－英雄 新宇侠”特殊召唤。②：“新空间人”怪兽或“元素－英雄 新宇侠”从自己的场上・墓地被放回自己的牌组・额外牌组的情况下可以发动。从自己的墓地挑选１只“元素－英雄”怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89086566,'机雷化','①：将自己场上的“库里波”、“库里波衍生物”全部破坏。然后，依所破坏的数量为上限，将对手场上的卡破坏。','是否要破坏对手场上的卡？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89086647,'阿菊的如意算盘',replace(replace('①：对手发动卡的效果时可以发动（同一连锁上最多1次）。依此效果发动时累积的连锁数量在此卡上放盘计数物。\r\n②：根据此卡的盘计数物的数量，适用以下效果。\r\n●9以下：此卡不会因对手的效果被破坏，对手不可将此卡作为效果的对象。\r\n●10以上：将此卡送至墓地。\r\n③：此卡因自身的效果被送至墓地的情况下可以发动。从自己牌组上面将10张卡送至墓地。','\r',char(13)),'\n',char(10)),'放置计数物','送至墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89091579,'昆虫人','群居生活的昆虫，森林是他们的乐园。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89091772,'超重武者 磁石－Q','①：此卡召唤成功时可以发动。从手牌将１只等级４以下的“超重武者”怪兽特殊召唤。然后将此卡改成守备表示。②：只要此卡存在于怪兽区域，对手不可攻击其他怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89111398,'沙尘的恶灵','此卡不可特殊召唤。召唤・反转此卡的回合的结束阶段时回到持有者的手牌中。召唤・反转此卡时，破坏场上除此卡以外的所有表侧表示的怪兽。','回到手牌','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89112729,'机械恐龙','“炸弹先生”＋“双头恐龙王”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89113320,'娱乐伙伴大咬龟',replace(replace('←3 【灵摆】 3→\r\n①：１回合１次，在我方主要阶段可发动。向对手展示手牌的１只“娱乐伙伴”怪兽或“异色眼”怪兽。此回合，该怪兽及我方手牌的同名怪兽之等级下降１级。\r\n【怪兽效果】\r\n①：此卡因战斗被破坏时可发动。将破坏此卡的怪兽破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89127526,'屏障共鸣者','①：在自己・对手回合中，从手牌将此卡送至墓地，以自己场上的1只协调为对象可以发动。此回合，该怪兽不会因战斗被破坏，因该怪兽的战斗对自己造成的战斗伤害变为0。','战斗破坏耐性','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89132148,'光子奥比塔尔',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：以自己场上的１只“光子”怪兽或“银河”怪兽为对象可以发动。从自己的手牌・场上将此卡视为拥有以下效果的装备魔法卡，装备于该自己的怪兽。\r\n●装备怪兽的攻击力上升５００，不会因战斗被破坏。\r\n②：将被装备的此卡送至墓地可以发动。从牌组将除“光子奥比塔尔”以外的１只“光子”怪兽或“银河”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89172051,'龙骑兵团－司令官',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡存在于手牌，且自己场上存在“龙骑兵团”怪兽或“龙之溪谷”的情况下可以发动。将此卡特殊召唤。\r\n②：自己的魔法与陷阱区域存在“龙骑兵团”怪兽卡的情况下，以场上的1张魔法・陷阱卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89176044,'捕食原生',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从牌组将“捕食原生”以外的1张“捕食”卡送至墓地可以发动。从牌组将1张“融合”魔法卡或“结合”魔法卡加入手牌。此卡发动后，直至回合结束时为止自己仅可特殊召唤龙族・植物族怪兽。\r\n②：怪兽被特殊召唤至对手场上的情况下，将墓地的此卡除外，以自己场上的1只融合怪兽为对象可以发动。将该怪兽破坏。','\r',char(13)),'\n',char(10)),'发动','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89181134,'捕食植物 毛毡伞蜥蜴','此卡名的②效果１回合仅可使用１次。①：只要此卡存在于怪兽区域，自己作为融合素材的、放有捕食计数物的怪兽的属性视为暗属性。②：在自己的主要阶段可以发动。从自己的手牌・场上及对手场上放有捕食计数物的怪兽中，挑选由暗属性融合怪兽卡决定的、包含场上此卡在内的融合素材怪兽送至墓地，从额外牌组将１只该融合怪兽融合召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89181369,'星尘的光芒','可选择我方墓地的１只龙族同步怪兽并发动。为成为与该等级相同等级，将被选择怪兽以外的我方墓地怪兽从游戏中除外，并从墓地特殊召唤被选择怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89185742,'风征龙－雷霆','此卡名的效果1回合仅可使用1次。①：将1只龙族或风属性怪兽和此卡从手牌舍弃可以发动。从牌组将1只“岚征龙-暴风”特殊召唤。以此效果特殊召唤的怪兽在此回合不可攻击。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89189982,'玄化武装龙','崇高如幻焉，其龙踞于巅。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89190953,'次元融合杀','①：从自己的手牌・场上・墓地，将由“幻魔”融合怪兽卡决定的融合素材怪兽除外，将1只该融合怪兽从额外牌组无视召唤条件特殊召唤。因以此效果特殊召唤的怪兽的战斗发生的、对自己的战斗伤害变为0。自己场上有“神炎皇乌利亚”、“降雷皇哈蒙”、“幻魔皇拉比艾尔”中任一存在的情况下，应对此卡的发动，对手不可发动效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89194033,'圣兽 塞尔凯特',replace(replace('①：自己场上不存在“王家的神殿”的情况下，此卡将被破坏。\r\n②：此卡战斗破坏的怪兽不去墓地而直接被除外。\r\n③：此卡战斗破坏怪兽的情况下发动。此卡的攻击力上升500。','\r',char(13)),'\n',char(10)),'攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89194103,'魔轰神兽件',replace(replace('冠有“魔轰神”之名的协调＋协调以外的怪兽１只或以上\r\n此卡依据我方手牌的张数获得以下效果。\r\n●０张：此卡不会因战斗与卡牌效果被破坏。\r\n●３张或以上：在结束阶段时破坏此卡。','\r',char(13)),'\n',char(10)),'此卡破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89208725,'虚拟世界','①：从牌组中挑选１张场地魔法卡，加入手牌或在自己场上发动。','请选择1张场地魔法卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89211486,'次代机・博士','①：解放自己场上１只表侧表示的“次代机・控制者”，以场上的１张卡为对象可以发动。将该卡破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89222931,'机械王－原型','场上每存在１只此卡以外的机械族怪兽，此卡的攻击力、守备力上升１００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89226534,'苏生之蜂玉',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：以自己墓地的１只“蜂军”怪兽为对象可以发动。将该怪兽特殊召唤。\r\n②：将墓地的此卡除外，以自己场上的１只昆虫族怪兽为对象可以发动。该怪兽直至下个回合结束时为止，不会因战斗・效果被破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','破坏抗性','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89235196,'大一战士','可将除此卡以外的手牌的１只等级１怪兽送入墓地并发动。从手牌特殊召唤此卡。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89238128,'电子界加速器',replace(replace('衍生物以外的怪兽２只以上\r\n此卡名的效果１回合仅可使用１次。\r\n①：在自己・对手的战斗阶段，以此卡连接端的１只电子界族怪兽为对象，可从以下效果中选择１个发动。发动此效果的回合中，此卡不可攻击。\r\n●该怪兽的攻击力直至回合结束时为止上升２０００。\r\n●此回合，该怪兽在１次战斗阶段中最多可攻击怪兽２次。','\r',char(13)),'\n',char(10)),'攻击力上升','多次攻击','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89252153,'元素－英雄 死灵暗黑人','①：只要此卡存在于墓地，仅限1次，自己无需解放即可召唤1只等级5以上的“元素-英雄”怪兽。','「元素－－英雄 死灵暗侠」的效果召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89252157,'蔷薇恋人',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：将墓地的此卡除外可以发动。从手牌将1只植物族怪兽特殊召唤。以此效果特殊召唤的怪兽在此回合不受对手的陷阱卡的效果影响。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89258225,'哈迪斯的使魔','解放此卡来发动此卡。令场上１只表侧表示的恶魔族怪兽的攻击力和守备力上升７００点。','攻守上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89258906,'黑羽－微风的布利兹','此卡因卡牌效果从我方牌组加入手牌的场合，可从手牌特殊召唤此卡。以此卡为同步素材的场合，只可使用于冠有“黑羽”之名怪兽的同步召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89264428,'北斗天熊・大舀取号','①：1回合1次，自己的“北斗天熊”怪兽为发动效果而解放怪兽的情况下，可从自己墓地将1只等级7以上的“北斗天熊”怪兽除外作为代替。②：每次怪兽被特殊召唤，在此卡上放1个计数物。③：1回合1次，怪兽被特殊召唤的情况下，将此卡7个以上的计数物全部去除，以对手场上的1只怪兽为对象可以发动。获得其控制权。此效果在场上有“北斗天熊”同步怪兽存在的情况下才能发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89272878,'冥界守门人','守卫冥界入口的战士。未得许可者将被无情斩杀。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89310929,'霞之谷雷神鬼',replace(replace('协调＋协调以外冠有“霞之谷”之名的怪兽１只或以上\r\n１回合１次，可选择我方场上１张除此卡以外的卡牌并发动。将被选择的我方卡牌返回至持有者手牌，直至回合结束时，此卡的攻击力上升５００点。此效果在对手回合也可发动。','\r',char(13)),'\n',char(10)),'攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89312388,'元素－英雄 棱镜侠','①：１回合１次，将额外牌组的１只融合怪兽出示给对手，从牌组将１只卡名记载于该怪兽的融合素材怪兽送至墓地可以发动。直至结束阶段为止，此卡视为为发动此效果送至墓地的怪兽的同名卡。','变成同名卡','变成同名卡的效果结束','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89320376,'星遗物之傀儡','此卡名的①②效果1回合1次，仅可使用其中1个。①：以自己场上的1只里侧表示怪兽为对象可以发动。将该怪兽改成表侧攻击表示或表侧守备表示。②：将自己墓地的1只“机怪虫”怪兽放回牌组，以自己场上的1只表侧表示怪兽为对象可以发动。将该怪兽改成里侧守备表示。','里侧表示怪兽变成表侧表示','表侧表示怪兽变成里侧表示','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89326990,'疾行机人弹珠小子','①：此卡召唤成功时，可以我方或对手墓地的１只协调为对象发动。特殊召唤该怪兽至我方场上，并仅以该怪兽与此卡为素材同步召唤１只风属性的同步怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89328238,'补强要员',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：依对手场上的卡的数量，自己从牌组抽牌。然后，依所抽的数量挑选手牌，以喜欢的顺序放回牌组下面。\r\n②：此卡存在于墓地，对手场上的卡数量比自己场上的卡多的情况下，在结束阶段可以发动。将此卡放置在自己场上。以此效果放置的此卡离开场上的情况下，将其除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89333528,'次代机・盖亚','①：场上的此卡将被战斗・效果破坏的情况下，作为代替可将自己场上的１只“次代机・控制者”破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89355716,'晴之天气模样',replace(replace('①：只可有１张“晴之天气模样”以表侧表示存在于我方场上。\r\n②：存在于与此卡同一纵列的我方主要怪兽区以及其两旁的我方主要怪兽区的“天气”效果怪兽获得以下效果。\r\n●可将此卡除外，并以我方场上的１只怪兽为对象发动。解放该我方怪兽，从我方手牌・墓地挑选１只卡牌名与该怪兽不同的“天气”怪兽并特殊召唤。此效果在对手回合也可发动。','\r',char(13)),'\n',char(10)),'「天气」怪兽特殊召唤（晴之天气模样）','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89357740,'联合飞行员',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：１回合１次，可以发动以下的１个效果。\r\n●以自己场上的１只效果怪兽为对象，将此卡视为装备魔法卡装备。装备怪兽将被战斗・效果破坏的情况下，作为代替将此卡破坏。\r\n●将装备状态的此卡特殊召唤。\r\n②：将装备状态的此卡放回手牌可以发动。将１只除外状态的联合怪兽视为以自身效果变成的装备魔法卡，装备于自己的１只可装备的怪兽，从自己手牌将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','此卡回到手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89362180,'骨生恐龙',replace(replace('此卡存在于墓地或以表侧表示存在于场上的场合，将被视为通常怪兽。以通常召唤的方式再次召唤场上表侧表示的此卡，此卡将视为效果怪兽并获得以下效果。\r\n●此卡变为恐龙族・地属性。此卡通过战斗破坏对手怪兽并将其送入墓地时，可以表侧守备表示特殊召唤该怪兽至我方场上。以此效果特殊召唤的怪兽只要以表侧表示存在于场上便视为不死族。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89386122,'正义盟军 辉剑鸟','以霞之谷栖息的怪兽辉剑鸟为主题开发而出的对外敌用战斗兵器。以从高空而来的奇袭玩弄敌人。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89392810,'杀手旋律・乐蔻',replace(replace('要以场上的此卡作为素材同步召唤的情况下，可将手牌的1只协调也作为同步素材。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从自己牌组・墓地将等级3怪兽以外的1只“杀手旋律”怪兽加入手牌。\r\n②：此卡作为同步素材被送至墓地的情况下，以对手场上的1张魔法・陷阱卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'检索效果','破坏效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89397517,'传说之心',replace(replace('“传说之心”１回合只可发动１张。\r\n①：可支付２０００LP，释放我方场上的１只战士族怪兽并发动。从我方的手牌、墓地除外最多３种“传说之龙”魔法卡，从我方手牌、牌组、墓地挑选与被除外种类数量相同的“传说骑士”怪兽特殊召唤（同名卡最多１张）。','\r',char(13)),'\n',char(10)),'是否继续除外？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89399912,'岚征龙－暴风',replace(replace('此卡名的①～④效果1回合1次，仅可使用其中1个。\r\n①：从手牌将此卡和1只风属性怪兽舍弃至墓地可以发动。从牌组将1只龙族怪兽加入手牌。\r\n②：从自己手牌・墓地将2只龙族或风属性怪兽除外可以发动。从手牌・墓地将此卡特殊召唤。\r\n③：此卡是被特殊召唤的情况下，在对手的结束阶段发动。将此卡放回手牌。\r\n④：此卡被除外的情况下可以发动。从牌组将1只龙族・风属性怪兽加入手牌。','\r',char(13)),'\n',char(10)),'从手牌特殊召唤','返回手牌','从牌组把1只龙族怪兽加入手牌','加入手牌','','','','','','','','','','','','');
INSERT INTO texts VALUES(89405199,'贪婪','以卡的效果抽牌的玩家，在该回合的结束阶段时受到卡的效果抽取的卡的张数×５００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89423971,'狱炎机・阿斯塔罗斯',replace(replace('此卡不可通常召唤。\r\n仅可在自己场上的效果怪兽的等级・阶级的合计为８以下时，将自己的手牌・墓地的１只“狱炎机”怪兽除外的情况下从手牌特殊召唤。\r\n①：１回合１次，以场上的１张魔法・陷阱卡为对象可以发动（发动此效果的回合中，此卡不可攻击）。将该卡破坏。\r\n②：在每个对手回合中１次，解放自己场上的１只怪兽，以对手墓地的１张卡为对象可以发动。将该卡除外。','\r',char(13)),'\n',char(10)),'魔陷破坏','对手墓地的卡除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89448140,'魔术师防护',replace(replace('①：只要自己场上存在魔法师族怪兽，自己受到的所有伤害变为一半。\r\n②：此卡从场上被送至墓地的情况下，以自己墓地的１只魔法师族怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89450409,'疾风之龙骑兵团','此卡名的卡1回合仅可发动1张。①：仅有对手场上才存在怪兽的情况下可以发动。从牌组将“龙骑兵团”协调和鸟兽族“龙骑兵团”怪兽各1只的效果无效并特殊召唤。在对手场上有从额外牌组中被特殊召唤的怪兽存在的情况下，进而可以仅以自己场上的“龙骑兵团”怪兽作为素材将1只龙族同步怪兽同步召唤。此卡发动后，直至回合结束时为止自己从额外牌组仅可特殊召唤龙族怪兽。','','是否进行同步召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89462956,'庄家之选','①：双方玩家将牌组洗牌，从牌组抽１张。然后双方玩家挑选１张手牌舍弃。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89463537,'尤尼科尔的影灵衣',replace(replace('以“影灵衣”仪式魔法卡降临\r\n此卡仅可以仪式召唤方式特殊召唤。\r\n此卡名的①效果1回合仅可使用1次。\r\n①：从手牌将此卡舍弃，以“尤尼科尔的影灵衣”以外的、自己墓地的1张“影灵衣”卡为对象可以发动。将该卡加入手牌。\r\n②：只要此卡存在于怪兽区域，被从额外牌组特殊召唤的表侧表示怪兽的效果无效化。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89474727,'真闪珖龙 星尘编年史',replace(replace('同步怪兽的协调＋1只以上协调以外的同步怪兽\r\n此卡仅可以同步召唤方式特殊召唤。①：1回合1次，将自己墓地的1只同步怪兽除外可以发动。此卡直至回合结束时为止，不受其他卡的效果影响。此效果在对手回合中也可以发动。②：此卡因对手被破坏的情况下，以自己被除外的1只龙族同步怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'是否发动「真闪珖龙 星尘编年史」的效果？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89477759,'混沌编号1000 梦幻虚神 原数天灵',replace(replace('等级１２怪兽×５\r\n①：双方的回合１次，去除此卡的１个超量素材可以发动。挑选场上的１只其他的怪兽破坏。\r\n②：在战斗阶段结束时发动。将场上的其他怪兽全部破坏。然后，可从对手的墓地挑选１只怪兽，以守备表示特殊召唤。\r\n③：拥有超量素材的此卡因对手的效果被破坏并被送至墓地的情况下可以发动。从额外牌组将１只“混沌虚数编号1000 梦幻虚光神 原数天灵・原数天地”特殊召唤，以此卡作为其超量素材。','\r',char(13)),'\n',char(10)),'选场上1只其他怪兽破坏','场上的其他怪兽全部破坏','','是否从对手墓地选怪兽特殊召唤？','','','','','','','','','','','','');
INSERT INTO texts VALUES(89484053,'转生炎兽 鼹','这个卡名的①②的效果1个回合各只能使用1次。①：自己对连接怪兽的连接召唤成功的回合的自己主要阶段可以发动。将手牌中的这张卡特殊召唤至作为连接怪兽的连接区的自己场上。②：自己场上不存在怪兽的情况下，把墓地的这张卡除外，可以自己墓地5张“转生炎兽”卡为对象发动。将该卡加入牌组洗牌。之后，自己从牌组抽2张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89493368,'召唤热核・大','只要此卡以表侧表示存在于自己场上，怪兽被召唤・反转召唤・特殊召唤至对手场上时，给予对手LP８００点伤害。此效果１回合仅可使用１次。使用了此效果回合的战斗阶段时，可以使１只对手怪兽的攻击无效。此外，将自己场上表侧表示的此卡以及“陷阱热核・空”“魔法热核・袭”各１只送至墓地可以发动。从自己的手牌・牌组・墓地中挑选１只“巨人轰炸机・大空袭”并特殊召唤。','伤害','攻击无效','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89494469,'暗黑魔神 恶梦','传说中会潜入梦中的恶魔。在目标沉睡中夺其性命。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89516305,'编号87 雪月花美神 月下女王',replace(replace('等级８怪兽×３\r\n①：在每个自己・对手回合中１次，去除此卡的１个超量素材，可从以下效果中选择１个发动。\r\n●以对手场上１张里侧表示的魔法・陷阱卡为对象可以发动。只要此卡存在于怪兽区域，该卡不可发动。\r\n●以场上的１只植物族怪兽为对象可以发动。将该植物族怪兽改成里侧守备表示。\r\n●以场上的１只表侧表示怪兽为对象可以发动。该怪兽的攻击力上升３００。','\r',char(13)),'\n',char(10)),'放置的1张魔法·陷阱卡不可发动','1只植物族怪兽变成里侧守备表示','1只怪兽上升攻击力','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89521713,'魔幻甜点・可颂汪汪',replace(replace('①：１回合１次，以自己场上１张其他的“魔幻甜点”卡为对象可以发动。将该卡放回手牌，此卡的等级上升１，攻击力上升３００。\r\n②：此卡被对手破坏并被送至墓地的情况下发动。将此卡放回牌组。','\r',char(13)),'\n',char(10)),'返回牌组','返回手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89529919,'战士 拉兹','此卡召唤、特殊召唤成功时，从我方牌组挑选１只“战士 拉兹”以外的等级４或以下的战士族怪兽放置到牌组最上方。','检索','请选择要在牌组最上面放置的卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89538537,'幻变骚灵・泛在羽衣精','此卡名的①②效果1回合仅可各使用1次。①：将1张此卡以外的自己场上的“幻变骚灵”卡放回持有者的手牌，以对手场上的1张卡为对象可以发动。将该卡放回持有者的手牌。此效果在对手回合中也可以发动。②：此卡从场上被送至墓地的情况下，以自己墓地的1张“幻变骚灵”陷阱卡为对象可以发动。将该卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89544521,'文具博格・喷射机',replace(replace('协调＋１只以上协调以外的怪兽\r\n此卡名的②③效果１回合１次，仅可使用其中１个。①：此卡的攻击力・守备力上升相当于场上“文具博格”卡数量×５００的数值。②：以自己场上的１张“文具博格”卡为对象可以发动。破坏该卡，从牌组将１只“文具博格”怪兽特殊召唤。③：以自己场上的１张“文具博格”卡和场上的１张表侧表示卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','卡片破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89547299,'力量注射师','支付６００点LP发动此卡。该回合中场上所有表侧表示的念动力族怪兽的攻击力上升５００点。此效果在１个回合中只可使用１次。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89552119,'精灵冥骑－急还马',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：在战斗阶段以外，怪兽区域的此卡将被送至墓地。\r\n②：此卡存在于墓地的情况下，在自己・对手的战斗阶段开始时，从手牌及自己场上的表侧表示怪兽中，将１只植物族怪兽送至墓地可以发动。将此卡特殊召唤。然后，可从自己或对手的墓地挑选１只怪兽，特殊召唤至自己场上。以此效果特殊召唤的怪兽将在战斗阶段结束时全部被送至墓地。','\r',char(13)),'\n',char(10)),'','是否选1只怪兽特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89558090,'暗黑囚犯','能巧妙地运用光的反射，隐藏自己的身影。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89558743,'小世界',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：向对手出示手牌的1只怪兽。从牌组挑选1只种族・属性・等级・攻击力・守备力中仅1项与出示的怪兽相同的怪兽进行确认，从手牌将所出示的怪兽以里侧除外。进而从牌组将1只种族・属性・等级・攻击力・守备力中仅1项与确认的怪兽相同的怪兽加入手牌，从牌组将所确认的怪兽以里侧除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89563150,'白银防护罩－银色之力','对手发动给予伤害的陷阱卡时可发动。使该发动无效，并破坏该卡牌和对手场上表侧表示的所有魔法、陷阱卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89567993,'亚马逊训练生','此卡通过战斗破坏的怪兽不送入墓地，而是回到持有者牌组的最下方。此卡通过战斗破坏对手怪兽的场合，此卡的攻击力上升２００点。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89569453,'断绝落穴','①：对手召唤・反转召唤・特殊召唤攻击力１５００以下的怪兽时可以发动。将该攻击力１５００以下的怪兽以里侧除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89571015,'风暴光波',replace(replace('①：此卡不可直接进行攻击，不可攻击额外怪兽区的怪兽。\r\n②：此卡不受额外怪兽区的怪兽所发动之效果的影响，不会因与额外怪兽区怪兽的战斗被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89594399,'爬虫妖・科亚特尔','此卡名的①效果１回合仅可使用１次。①：自己场上存在爬虫类族・暗属性怪兽的情况下可以发动。从手牌将此卡特殊召唤。对手场上存在攻击力０的怪兽的情况下，进而可从手牌将最多其数量的“爬虫妖”怪兽特殊召唤。②：以自己场上的此卡作为爬虫类族同步怪兽的同步素材的情况下，可将此卡视为协调以外的怪兽。','','是否特殊召唤更多「爬虫妖」怪兽？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89604813,'青眼究极灵龙',replace(replace('协调２只以上＋协调以外的“青眼”怪兽１只\r\n此卡名的②③效果１回合仅可各使用１次。\r\n①：只要此卡存在于怪兽区域，对手不可将自己墓地的卡除外。\r\n②：卡的效果在场上发动时可以发动。将该发动无效，此卡的攻击力直至回合结束时为止上升１０００。\r\n③：此卡因战斗・效果被破坏的情况下可以发动。从自己墓地将“青眼究极灵龙”以外的１只龙族・光属性怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'自己墓地的卡不可被对手除外','发动无效','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89609515,'岩浆炎・燃素','此卡被送入墓地时，我方场上所有冠有“岩浆炎”之名怪兽的攻击力上升３００点。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89617515,'摇海鱼 枯叶','此卡名的①②效果１回合仅可各使用１次。①：此卡召唤・反转召唤・特殊召唤成功时可以发动。从牌组将“摇海鱼 枯叶”以外的１只鱼族怪兽送至墓地。②：将墓地的此卡除外，以自己墓地的３只鱼族怪兽为对象可以发动。将该怪兽加入牌组洗牌。然后自己从牌组抽１张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89621922,'新空间人・火焰甲虫','此卡的攻击力上升相当于对手场上的魔法、陷阱卡数量×４００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89628781,'忍法 空蝉之术','选择我方场上１只冠有“忍者”之名的怪兽发动此卡。只要此卡存在于场上，所选择怪兽不会因战斗而被破坏。（伤害计算仍然适用）','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89631139,'青眼白龙','以高攻击力著称的传说之龙。任何对手都能粉碎，其破坏力不可估量。','','','','','','','','','','','','','','','','');
