INSERT INTO texts VALUES(89642993,'编号63 饭勺士兵',replace(replace('等级１怪兽×２\r\n可移除此卡的１个超量素材，并从以下效果选择１个发动。“编号63 饭勺士兵”的效果１回合只可使用１次。\r\n●下一个对手准备阶段开始时，双方玩家从牌组抽取１张卡牌。\r\n●双方玩家回复１０００LP。','\r',char(13)),'\n',char(10)),'选择效果发动','双方玩家从牌组抽牌','双方玩家回复1000基本分','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89662401,'转生炎兽 雄孔雀','这个卡名的①的效果1个回合只能使用1次。①：“转生炎兽 雄孔雀”以外的“转生炎兽”怪兽在自己场上被召唤・特殊召唤的情况下可以发动。将这张卡从手牌进行特殊召唤。②：从手牌及自己场上的表侧表示的卡中把1张“转生炎兽”卡送至墓地，可以对手场上放置的1张魔法・陷阱卡为对象发动。在这个回合中，该放置的魔法・陷阱卡不能发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89662736,'武斗神器－八咫','自己场上名字带有“武斗神”的兽战士族怪兽被对手怪兽选择作为攻击对象时，从手牌将此卡送至墓地可以发动。使攻击怪兽的攻击无效，并给予对手LP该怪兽攻击力一半数值的伤害。“武斗神器－八咫”的效果１回合仅可使用１次。','攻击无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89693655,'亚空间战斗',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：适用以下效果3次。\r\n●双方各从自身牌组挑选1只攻击力为？以外的怪兽给双方确认。所选的怪兽攻击力较高的一方，该玩家将其加入手牌。所选的怪兽攻击力较低的一方，该怪兽将被破坏，该玩家受到500伤害。攻击力相同的情况下，将所选的怪兽放回牌组。此回合，双方不可发动自身以此效果所选的怪兽及其同名怪兽的怪兽效果。','\r',char(13)),'\n',char(10)),'发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89698120,'华丽的潜入工作员','此卡的召唤成功时，不可发动陷阱卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89707961,'王家守护者斯芬克斯',replace(replace('此卡名的②③效果１回合仅可各使用１次。\r\n①：在自己的主要阶段可以发动。将此卡改成里侧守备表示（１回合仅１次）。\r\n②：此卡反转召唤成功的情况下发动。将对手场上的怪兽全部放回持有者的牌组。\r\n③：场上的此卡被对手破坏的情况下可以发动。从手牌・牌组将１只岩石族・等级５怪兽以里侧守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89718302,'兄暴牛鬼','掷硬币猜正反面。猜对的场合，给予对手生命１０００点伤害。猜错的场合，我方受到１０００点伤害。此效果１回合仅１次可于我方主要阶段使用。','猜硬币','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89719143,'决战融合－最终结合','①：在自己场上的融合怪兽与对手场上的融合怪兽进行战斗的战斗步骤，以该２只融合怪兽为对象可以发动。使该攻击无效，双方玩家受到相当于该２只融合怪兽攻击力合计数值的伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89731911,'亲善骑士','①：此卡因战斗破坏并送入墓地的场合发动，双方玩家可从手牌特殊召唤１只等级４的怪兽。','特殊召唤','是否要特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89732524,'魔界发往冥界的巴士','①：此卡反转的场合发动。从牌组将１只除光、暗属性以外的恶魔族怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89739383,'格里莫之魔导书',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从牌组将“格里莫之魔导书”以外的1张“魔导书”卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89743495,'斩机除伐','此卡名的①②效果1回合仅可各使用1次。①：解放额外怪兽区域的1只自己的电子界族怪兽可以发动。从手牌和自己的墓地各挑选最多1只电子界族・等级4怪兽，将其特殊召唤。②：此卡被送至墓地的情况下，可以场上1只表侧表示的怪兽为对象发动。该怪兽的攻击力直至回合结束时为止变为一半。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89753095,'神鸣',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从牌组将1只雷族怪兽加入手牌。此卡发动后，直至下个回合结束时为止，自己不可通常召唤以此效果加入手牌的怪兽及其同名怪兽。','\r',char(13)),'\n',char(10)),'发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89770167,'炎热刀日珥','１回合１次，可将我方墓地１只冠有“岩浆炎”之名的怪兽从游戏中除外并发动。直至回合结束时，此卡的攻击上升３００点。此效果在对手回合也可使用。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89771220,'北斗天熊龙机巧极','此卡名的②效果１回合仅可使用１次。①：从自己的手牌・场上，将“北斗天熊・大舀取号”和“辉龙机巧－法夫纳”各１张除外，将１只“天极辉舰－熊斗龙巧”从额外牌组特殊召唤。场上存在“北斗天熊－勾陈一”或“辉龙机巧－右垣一阿尔法”的情况下，也可将除外的卡中的１张改成从牌组除外。②：自己为发动“北斗天熊”、“龙机巧”怪兽的效果而要解放怪兽的情况下，可将墓地的此卡除外作为代替。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89774530,'英豪挑战者 双长矛','此卡召唤成功时，可从我方手牌、墓地挑选１只“英豪挑战者 双长矛”并以表侧守备表示特殊召唤。此卡不可作为同步素材。此外，将此卡用作超量素材的场合，仅可用于战士族怪兽的超量召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89776023,'进化虫・棱角鳞鳄',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从自己的手牌・墓地将１只“进化虫”怪兽以里侧守备表示特殊召唤。\r\n②：在自己的主要阶段可以发动。从牌组将１张“强制进化”或“突然进化”放置在自己场上。\r\n③：自己场上的怪兽将被战斗・效果破坏的情况下，作为代替可解放自己场上的１只爬虫类族・恐龙族怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89785779,'千年眼幻象师',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己・对手回合中，从手牌将此卡舍弃，以对手场上的1只效果怪兽为对象可以发动。挑选自己场上的1只“眼纳祭魔”融合怪兽或“纳祭魔”，将对象的对手的效果怪兽视为以其效果变成的装备魔法卡装备。\r\n②：此卡存在于墓地的状态下，“眼纳祭魔”融合怪兽或“纳祭魔”被特殊召唤的情况下发动。将此卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89789152,'快子时空银河螺旋',replace(replace('此卡名的卡１回合仅可发动１张。\r\n自己场上存在“银河眼时空龙”怪兽的情况下，此卡也可从手牌发动。\r\n①：以自己场上的１只龙族“银河”怪兽为对象可以发动。该表侧表示怪兽直至回合结束时为止，不会因战斗被破坏，不受自身以外的卡的效果影响。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89792713,'极星宝 雷瓦汀','可选择场上１只此回合因战斗破坏怪兽的表侧表示怪兽并发动。破坏被选择怪兽。对此卡的发动，不可发动魔法、陷阱、怪兽效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89801755,'深渊的指名者','支付１０００点LP。宣言１个种族和１种属性。对手将手牌或牌组中的１张与宣言的种族和属性全都相符的怪兽卡送入墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89809665,'焰圣骑士－托宾',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己场上存在装备有装备卡的怪兽的情况下可以发动。从手牌・墓地将此卡特殊召唤。以此效果从墓地特殊召唤的此卡从场上离开的情况下，将其除外。\r\n②：此卡存在于墓地的情况下，以自己场上的１只战士族怪兽为对象可以发动。将此卡视为装备魔法卡，装备于该自己的怪兽。\r\n③：装备怪兽作为同步素材的情况下，可视为协调。','\r',char(13)),'\n',char(10)),'此卡特殊召唤','此卡当作装备','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89810518,'爬虫妖美杜莎','可将１张手牌送入墓地，选择对手场上的１只表侧表示怪兽并发动。被选择怪兽的攻击力变为０，不可变更表示形式。','攻击变成0，不可改变表示形式','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89812483,'钢铁化・强化反射装甲',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：解放自己场上的１只表侧表示怪兽可以发动此卡。从自己手牌・牌组・墓地将１只记载有“钢铁化・强化反射装甲”卡名的、不可通常召唤的怪兽特殊召唤。然后，可将此卡视为拥有以下效果的装备卡，装备于该怪兽。\r\n●装备怪兽的攻击力・守备力上升４００，不会因魔法・怪兽的效果被破坏，对手不可将装备怪兽作为魔法・怪兽的效果的对象。','\r',char(13)),'\n',char(10)),'','','是否装备？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89813287,'魔救奇迹－提亚马特石',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：自己墓地存在暗属性怪兽的情况下可以发动。从牌组将1张“魔救”魔法・陷阱卡加入手牌。\r\n②：对手发动场上的怪兽的效果时可以发动。从自己牌组上面翻开5张卡。可最多依其中岩石族怪兽的数量，将对手场上的卡放回手牌。将翻开的卡以喜欢的顺序放回牌组下面。','\r',char(13)),'\n',char(10)),'检索效果','回到手牌','是否选卡回到手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89818984,'花札卫－柳间小野道风',replace(replace('此卡不可通常召唤。\r\n解放自己场上“花札卫－柳间小野道风”以外的１只等级１１“花札卫”怪兽的情况下可以特殊召唤。\r\n①：此卡特殊召唤成功的情况下发动。自己从牌组抽１张，双方确认。其为“花札卫”怪兽的情况下，可将该怪兽特殊召唤。不是的情况下，将该卡送至墓地。\r\n②：以场上的此卡作为同步素材的情况下，可将包含此卡在内的所有同步素材怪兽视为等级２怪兽。','\r',char(13)),'\n',char(10)),'抽1张卡并给双方确认','是否特殊召唤？','是否把全部同步素材怪兽当作2星怪兽使用？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89824842,'蕾祸大轮首狩舞',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：以对手场上的卡为对象可以发动，数量最多为自己场上的昆虫族・植物族・爬虫类族连接怪兽的种族种类数量。将该卡破坏。\r\n②：不是在此回合被送至墓地的此卡存在于墓地的状态下，自己场上表侧表示的昆虫族・植物族・爬虫类族怪兽因战斗・效果被破坏的情况下，将此卡除外，以对手场上的１只怪兽为对象可以发动。将该怪兽破坏。','\r',char(13)),'\n',char(10)),'','怪兽破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89832901,'密林的黑龙王','栖息于密林中的漆黑龙。会大口大口地吃树。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89839552,'傀偶兵卒',replace(replace('此卡名的②③效果１回合仅可各使用１次。\r\n①：此卡可直接攻击。\r\n②：此卡给予对手战斗伤害时，可以发动。从牌组将１张“升变”加入手牌。\r\n③：将墓地的此卡除外可以发动。从牌组将“傀偶兵卒”以外的１只战士族・地属性怪兽加入手牌。然后，对手可从自身的牌组将１只怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','是否从牌组把1只怪兽加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89851827,'圣秘龙骑士',replace(replace('龙族怪兽＋魔法师族怪兽\r\n此卡名的③效果1回合仅可使用1次。\r\n①：此卡的攻击力下降自己除外状态的卡的数量×100的数值。\r\n②：只要融合召唤的此卡存在于怪兽区域，对手场上被特殊召唤的龙族・魔法师族怪兽不可发动效果。\r\n③：以自己墓地的龙族和魔法师族怪兽各1只为对象可以发动。将其中1只特殊召唤，另1只放回牌组最下面。','\r',char(13)),'\n',char(10)),'以墓地怪兽为对象','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89856523,'罡炎星－麟俊义',replace(replace('炎属性协调＋协调以外的“炎星”怪兽１只以上\r\n①：此卡同步召唤时可以发动。从牌组将１张“炎舞”魔法・陷阱卡放置在自己场上。\r\n②：只要此卡存在于怪兽区域，对手场上的怪兽的攻击力下降相当于自己场上表侧表示的魔法・陷阱卡的数量×１００的数值。','\r',char(13)),'\n',char(10)),'放置','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89870349,'假面－英雄 暴风',replace(replace('此卡仅可通过“假面变换”的效果特殊召唤。\r\n①：此卡特殊召唤的情况下，以对手场上的1只表侧表示怪兽为对象可以发动。将该怪兽的攻击力改成一半。\r\n②：在每个自己・对手回合中1次，支付500LP，以对手场上的1张魔法・陷阱卡为对象可以发动。将该卡放回手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89875646,'三重枪管轮转',replace(replace('①：可从以下效果中选择1个发动（此卡名的以下效果1回合仅可各选择1次）。\r\n●从自己墓地将1只龙族怪兽放回牌组。然后，可从牌组将1只卡名与所放回的怪兽不同的“枪弹”怪兽特殊召唤。\r\n●从自己墓地将2只龙族怪兽放回牌组。然后，从自己墓地将1张场地魔法卡加入手牌。\r\n●从自己墓地将3只龙族怪兽放回牌组。然后，从对手墓地将最多3只怪兽放回牌组。','\r',char(13)),'\n',char(10)),'发动','让1只回到牌组','让2只回到牌组','让3只回到牌组','是否特殊召唤？','','','','','','','','','','','');
INSERT INTO texts VALUES(89875647,'三重枪管轮转',replace(replace('①：可从以下效果中选择1个发动（此卡名的以下效果1回合仅可各选择1次）。\r\n●从自己墓地将1只龙族怪兽放回牌组。然后，可从牌组将1只卡名与所放回的怪兽不同的“枪弹”怪兽特殊召唤。\r\n●从自己墓地将2只龙族怪兽放回牌组。然后，从自己墓地将1张场地魔法卡加入手牌。\r\n●从自己墓地将3只龙族怪兽放回牌组。然后，从对手墓地将最多3只怪兽放回牌组。','\r',char(13)),'\n',char(10)),'发动','让1只回到牌组','让2只回到牌组','让3只回到牌组','是否特殊召唤？','','','','','','','','','','','');
INSERT INTO texts VALUES(89882100,'夜间摄击','①：以对手场上被放置的1张魔法・陷阱卡为对象可以发动。将被放置的该卡破坏。应对此卡的发动，对手不可发动对象卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89883517,'冤狱',replace(replace('“冤狱”１回合只可发动１张。\r\n①：对手的手牌、场上卡牌的合计数量多于我方手牌、场上卡牌的合计数量的场合，可以场上１张表侧表示卡牌为对象发动。双方玩家在此决斗中，不可发动除该表侧表示卡牌以外的与对象卡牌同名卡的效果。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89893715,'岩浆炎・炎轮舵手','此卡因战斗被破坏并送入墓地时可发动。从牌组将２只冠有“岩浆炎”之名的怪兽送入墓地。','送至墓地','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89899996,'D－精神','我方场上不存在冠有“命运－英雄”之名怪兽的场合，从手牌特殊召唤１只等级４或以下的冠有“命运－英雄”之名的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89904598,'恐龙人','人形恐龙，虽然智慧很高，却不怎么擅长打斗。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89907227,'白斗气双头神龙',replace(replace('同步怪兽的协调＋协调以外的怪兽１只以上\r\n①：此卡在自己回合同步召唤时可以发动。将１只“神龙衍生物”（鱼族・水・星１０・攻３３００／守３０００）以守备表示特殊召唤至自己场上。\r\n②：每个对手回合中１次，自己场上不存在衍生物的情况下可以发动。将１只“神龙衍生物”特殊召唤至自己场上。\r\n③：此卡因对手的效果被破坏并被送至墓地的情况下，如果自己场上存在“神龙衍生物”则可以发动。将此卡以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89907228,'神龙衍生物','由“白斗气双头神龙”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89914395,'雷神的魔槌','可选择我方场上１只冠有“极神”之名的怪兽并发动。此回合，被选择怪兽在１次的战斗阶段中可攻击２次。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89928517,'通贩卖员',replace(replace('①：１回合１次，在自己的主要阶段可以发动。双方玩家分别向对手出示１张手牌。出示的卡种类相同的情况下，根据其种类适用以下效果。\r\n●怪兽：双方玩家可分别特殊召唤所出示的怪兽。\r\n●魔法：双方玩家分别从牌组抽２张。\r\n●陷阱：双方玩家分别挑选牌组的２张卡送至墓地。','\r',char(13)),'\n',char(10)),'','是否特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89932017,'同步独径',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：从自己牌组・墓地挑选1只等级1协调，加入手牌或特殊召唤。\r\n②：此卡存在于墓地，且自己场上存在“废品战士”或记载有该卡名的怪兽的情况下可以发动。将此卡放置在自己场上。以此效果放置的此卡从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'发动','放置','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89943723,'元素－英雄 新宇侠','来自新空间的崭新元素－英雄。通过与新空间人的接触融合，将发挥未知力量！','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89943724,'元素－英雄 新宇侠','来自新空间的崭新元素－英雄。通过与新空间人的接触融合，将发挥未知力量！','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89943725,'元素－英雄 新宇侠','来自新空间的崭新元素－英雄。通过与新空间人的接触融合，将发挥未知力量！','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89943726,'元素－英雄 新宇侠','来自新空间的崭新元素－英雄。通过与新空间人的接触融合，将发挥未知力量！','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89948817,'朱罗纪喷发',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：在自己的主要阶段可以发动。将自己场上的1只恐龙族怪兽破坏，从牌组将1只“朱罗纪”怪兽特殊召唤。\r\n②：对手将怪兽特殊召唤的情况下，如果对手在此回合发动过4次以上怪兽的效果则可以发动。从额外牌组将1只“朱罗纪・陨星龙”视为同步召唤特殊召唤。\r\n③：自己场上的“朱罗纪”怪兽将被效果破坏的情况下，作为代替可将自己墓地的1只恐龙族怪兽除外。','\r',char(13)),'\n',char(10)),'破坏并特殊召唤','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89959682,'王家的保卫者','守护王家几千年的木乃伊士兵。直至今日其灵魂也决不饶恕任何入侵者。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89974735,'魔法妖精 勃根第',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n \r\n①：此卡存在于怪兽区域的状态下，对手的手牌因效果被舍弃的情况下可以发动。给予对手相当于其张数×400的伤害。 \r\n②：此卡因战斗被破坏并被送至墓地时可以发动。随机舍弃对手的1张手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89974904,'同步呼叫','①：可以我方墓地的１只怪兽为对象并发动。使该怪兽效果无效并特殊召唤，并仅以包含该怪兽在内的我方场上的怪兽为素材，同步召唤１只龙族、恶魔族的暗属性同步怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89987208,'东方英雄','传说来自遥远的东方国度的武士，手持之刀相当锋利。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(89997728,'卡通目录','①：从牌组将1张“卡通”卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90000652,'救援王牌 火焰驱动机',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：“救援王牌 火焰驱动机”以外的“救援王牌”怪兽被召唤・特殊召唤至自己场上的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：怪兽被特殊召唤至对手场上的情况下可以发动。从自己手牌・牌组・墓地将1只等级4以下的“救援王牌”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90011152,'扰乱怪之乡','１回合１次，可从手牌将１张冠有“扰乱怪”之名的卡牌送入墓地并发动。选择我方墓地的１只冠有“扰乱怪”之名的怪兽特殊召唤。只要我方场上存在有冠有“扰乱怪”之名的怪兽，将场上所有怪兽的原本攻击力、守备力相互交换。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90011273,'违犯枪管龙',replace(replace('包含“枪弹”怪兽在内的龙族・暗属性怪兽2只\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡连接召唤的情况下可以发动。从牌组将1张“枪管”魔法・陷阱卡加入手牌。\r\n②：在自己・对手回合中，以自己场上的1只暗属性怪兽为对象可以发动。该怪兽的攻击力上升500。对象怪兽不存在的情况下，作为代替可从牌组将1只“枪弹”怪兽以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'检索效果','上升攻击力','是否特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90019393,'宝石骑士・紫翠玉','①：解放此卡可以发动。从牌组将1只“宝石骑士”通常怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90020065,'时间炸弹','反转：在我方的准备阶段时解放此卡，破坏我方场上的所有怪兽，并给予对手生命被破坏怪兽攻击力总和一半数值的伤害。','反转效果','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90020780,'忍尸','此卡名的①②效果１回合仅可各使用１次。①：此卡已存在于怪兽区域的状态下，此卡以外的不死族怪兽从自己的墓地被特殊召唤的情况下可以发动。自己从牌组抽１张。然后，挑选１张手牌舍弃。②：墓地的此卡在为了发动效果而被除外的情况下，或因效果被除外的情况下可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡离开场上的情况下，将其除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90027012,'兆手之神','此卡名的效果１回合仅可使用１次。①：此卡召唤・反转召唤・特殊召唤成功的情况下可以发动。从牌组将１只仪式怪兽和１张仪式魔法卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90036274,'清透翼疾速龙',replace(replace('←4 【灵摆】 4→\r\n此卡名的灵摆效果1回合仅可使用1次。①：为使合计等级为7，将自己场上1只表侧表示的“疾行机人”协调和1只协调以外的怪兽送至墓地可以发动。将灵摆区域的此卡特殊召唤。\r\n【怪兽效果】\r\n协调＋1只以上协调以外的风属性怪兽\n此卡名的①怪兽效果1回合仅可使用1次。①：以对手场上1只从额外牌组被特殊召唤的表侧表示怪兽为对象可以发动。直至回合结束时为止，该怪兽的攻击力变为0，效果无效化。此效果在对手回合中也可以发动。②：怪兽区域的此卡因战斗・效果被破坏的情况下可以发动。将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90050480,'元素－英雄 宇宙新宇侠',replace(replace('“元素－英雄 新宇侠”＋属性不同的“新空间人”怪兽×３\r\n仅在将自己场上的上述卡放回牌组的情况下，可从额外牌组特殊召唤。①：此卡从额外牌组特殊召唤成功的情况下可以发动。此回合，对手不可发动在场上发动的效果。应对此效果的发动，对手不可发动魔法・陷阱・怪兽的效果。②：在结束阶段发动。将此卡放回持有者的额外牌组，将对手场上的卡全部破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90075978,'W星云陨石','将场上的里侧表示怪兽全部变成表侧守备表示。此回合的结束阶段时，将我方场上所有爬虫类族、光属性怪兽变成里侧守备表示，并且我方从牌组抽取与其相同数量的卡牌。之后，可从牌组特殊召唤１只等级７或以上的爬虫类族、光属性怪兽。','是否要特殊召唤７星以上的爬虫类族·光属性怪兽？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90091224,'四天之龙 暗反叛超量龙',replace(replace('暗属性等级4怪兽×2\r\n此卡名在规则上也视为“魅影骑士团”卡。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡特殊召唤的情况下，以相同数量的自己及对手场上的卡为对象可以发动。将该卡破坏。\r\n②：对手发动效果时，去除此卡的1个超量素材可以发动。从额外牌组将1只暗属性・阶级4的超量怪兽重叠在自己场上的此卡上面，视为超量召唤特殊召唤。','\r',char(13)),'\n',char(10)),'破坏效果','超量召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90091225,'四天之龙 暗反叛超量龙',replace(replace('暗属性等级4怪兽×2\r\n此卡名在规则上也视为“魅影骑士团”卡。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡特殊召唤的情况下，以相同数量的自己及对手场上的卡为对象可以发动。将该卡破坏。\r\n②：对手发动效果时，去除此卡的1个超量素材可以发动。从额外牌组将1只暗属性・阶级4的超量怪兽重叠在自己场上的此卡上面，视为超量召唤特殊召唤。','\r',char(13)),'\n',char(10)),'破坏效果','超量召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90098000,'亚特兰蒂斯的战将',replace(replace('此卡名的①③效果1回合仅可各使用1次。\r\n①：从手牌将此卡舍弃可以发动。从牌组将1张记载有“龙都 亚特兰蒂斯”卡名的魔法・陷阱卡加入手牌。\r\n②：此卡只要存在于怪兽区域，卡名视为“海”。\r\n③：此卡存在于墓地，且自己场上存在“海”的情况下可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'检索效果','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90098780,'琴键魔人－挠挠哼唱',replace(replace('等级３怪兽×２\r\n①：这张卡成功特殊召唤时，可以选择我方墓地中的１张“魔人”超量怪兽发动。特殊召唤该怪兽。然后可以将至多２张手牌叠放于其下作为超量素材。\r\n②：１回合１次，可以移除此卡的１个超量素材，以我方场上的１只“魔人”超量怪兽为目标发动。在此回合，该怪兽可以直接攻击对手。','\r',char(13)),'\n',char(10)),'特殊召唤','直接攻击','是否要选择手牌在怪兽下面叠放？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90122655,'天魔大帝','①：只要此卡存在于怪兽区域，应对被通常召唤的怪兽的效果的发动，对手不可发动魔法・陷阱・怪兽的效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90126061,'编号5 亡胧龙 死亡嵌合龙',replace(replace('等级5怪兽×2只以上\r\n①：此卡的攻击力上升此卡超量素材的数量×1000的数值。\r\n②：持有超量素材的此卡可攻击全部对手怪兽各1次。\r\n③：此卡进行过战斗的战斗阶段结束时，可从以下效果中选择1个发动。\r\n●以自己墓地的1只怪兽为对象可以发动。将该怪兽作为此卡的超量素材。\r\n●以对手墓地的1张卡为对象可以发动。将该卡放回对手牌组最上面。','\r',char(13)),'\n',char(10)),'自己墓地的卡作为超量素材','对手墓地的卡回到牌组最上','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90135989,'云魔物－风暴','每次我方准备阶段发动。各放置１个雾计数物至场上的全部表侧表示怪兽。','放置计数物','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90140980,'扰乱怪之王',replace(replace('“扰乱怪之绿色”＋“扰乱怪之黄色”＋“扰乱怪之黑色”\r\n只要此卡以表侧表示存在于场上，最多指定未使用的对手怪兽区域３处并使其不能使用。','\r',char(13)),'\n',char(10)),'是否还要选择一个区域？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90147755,'炎之女暗杀者','反转：从自己牌组上面将３张卡牌从游戏中除外并发动。给予对手生命８００点伤害。','LP伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90156158,'星圣的超新生',replace(replace('发动此卡的回合中，自己无法进行战斗阶段。\r\n①：以自己墓地的2只“星圣”怪兽为对象可以发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90161770,'蜂军－速击之劲弩',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：此卡召唤时，以自己墓地的１只等级３以下的昆虫族怪兽为对象可以发动。将该怪兽以守备表示特殊召唤。\r\n②：此卡被对手破坏的情况下可以发动。从手牌・牌组将１只“蜂军”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90162951,'编号35 贪食捕鸟蛛',replace(replace('等级１０怪兽×２\r\n①：只要此卡存在于怪兽区域，自己场上怪兽的攻击力・守备力上升相当于自己和对手LP之差的数值。②：只要持有超量素材的此卡存在于怪兽区域，对手每次特殊召唤怪兽就给予对手６００伤害。③：１回合１次，去除此卡的１个超量素材可以发动。将对手场上拥有此卡攻击力以下攻击力的怪兽全部破坏。','\r',char(13)),'\n',char(10)),'破坏怪兽','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90164606,'黄金荣耀－并驾齐驱',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：以自己场上的１只“黄金荣耀”怪兽，或自己墓地“黄金荣耀－并驾齐驱”以外的１张“黄金荣耀”卡为对象可以发动。将该卡放回手牌。\r\n②：对手场上存在攻击力高于自己LP数值的怪兽的情况下，从自己的墓地将此卡和１只“黄金荣耀”怪兽除外可以发动。从额外牌组将记载有所除外怪兽的卡名的１只“黄金荣耀”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90173539,'世界恐龙摔跤',replace(replace('此卡名的③效果1回合仅可使用1次。\r\n①：自己场上存在“恐龙摔跤手”怪兽的情况下，双方在1次战斗阶段中仅可用1只怪兽攻击。\r\n②：自己的“恐龙摔跤手”怪兽的攻击力仅在攻击对手怪兽的伤害计算时上升200。\r\n③：对手场上的怪兽数量多于自己场上的怪兽的情况下，将墓地的此卡除外可以发动。从牌组将1只“恐龙摔跤手”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90176467,'梦魔镜之逆徒－涅伊洛','此卡名的①②效果１回合仅可各使用１次。①：此卡召唤・特殊召唤成功的情况下可以发动。从牌组将１只“梦魔镜之使徒－涅伊洛”加入手牌。然后，可将此卡改成光属性。②：解放自己场上１只其他的“梦魔镜”怪兽可以发动。从牌组挑选１只等级与其不同的“梦魔镜”怪兽，将１张卡名记载于所挑选怪兽的“圣光之梦魔镜”或“暗黑之梦魔镜”从牌组加入手牌，将所挑选的怪兽以守备表示特殊召唤。','','','是否变成光属性？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90179822,'喜剧之惨绝戏子','此卡名的①②效果１回合１次，仅可使用其中１个。①：对手发动以自己场上的表侧表示“惨绝戏”卡为对象的魔法・陷阱・怪兽的效果时，从手牌将此卡舍弃可以发动。将该效果无效。②：此卡存在于墓地的情况下，解放自己场上的１只融合怪兽可以发动。将此卡特殊召唤。此效果在对手回合中也可以发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90200789,'忍法 超变化之术','选择我方场上１只冠有“忍者”之名的怪兽和对手场上１只表侧表示的怪兽发动此卡。将所选择怪兽送入墓地，从我方牌组特殊召唤１只等级在所选择怪兽合计等级以下的龙族・恐龙族・海龙族怪兽至我方场上。此卡离开场上时，将该怪兽从游戏中除外。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90207654,'极星天 古尔薇格',replace(replace('等级５以下的“极星”怪兽１只\r\n此卡名的①效果１回合仅可使用１次。\r\n①：此卡连接召唤成功的情况下可以发动。挑选自己的手牌・场上的最多３张卡除外，依该数量从牌组将“极星”怪兽以守备表示特殊召唤。此效果发动过的余下回合，自己不可通常召唤，仅可特殊召唤“极神”怪兽。\r\n②：只要此卡连接端有“极神”怪兽存在，对手不可将该怪兽作为效果的对象，不可将此卡选择为攻击对象。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90219263,'万华镜－华丽的分身－','①：场上有“神鹰女郎”存在的情况下可以发动。从手牌・牌组将１只“神鹰女郎”或“神鹰女郎三姐妹”特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90238142,'神鹰通灵者','此卡名的③效果１回合仅可使用１次。①：此卡只要存在于场上・墓地，卡名视为“神鹰女郎”。②：自己场上有龙族怪兽存在的情况下，此卡的等级变为７。③：从手牌将１张“神鹰”卡舍弃可以发动。从牌组将“神鹰通灵者”以外的１只“神鹰”怪兽以守备表示特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90239723,'变形斗士・修复装备','可从手牌将１只冠有“变形斗士”之名的怪兽送入墓地，并选择我方墓地的１只冠有“变形斗士”之名的怪兽发动。特殊召唤被选择怪兽并装备此卡。装备怪兽不可变更表示形式。此卡从场上离开时，破坏装备怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90241276,'蛇眼炎燐',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：用抽牌以外的方法将此卡加入手牌的情况下可以发动。将此卡特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从牌组将1张“蛇眼”魔法・陷阱卡加入手牌。\r\n③：此卡被送至墓地的情况下，以自己墓地的1只炎属性怪兽为对象可以发动。将该怪兽视为永续魔法卡，以表侧表示放在原本持有者的魔法与陷阱区域。','\r',char(13)),'\n',char(10)),'此卡特殊召唤','检索','当作永续魔法卡放置','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90243945,'白骨公主','①：此卡只要存在于墓地，卡名视为“白骨”。②：此卡召唤・特殊召唤成功的情况下可以发动。从牌组将１只“白骨皇子”送至墓地。③：将自己的手牌、场上的此卡送至墓地可以发动。场上所有怪兽的攻击力・守备力直至回合结束时为止，下降相当于其等级或阶级×３００的数值。此效果在对手回合中也可以发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90246973,'动力镐','１回合１次，可选择１只持有等级为装备怪兽等级或以下的对手墓地怪兽并从游戏中除外，直至回合结束时，装备怪兽的攻击力上升５００点。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90247311,'黄龙的忍者',replace(replace('此卡仅可以“忍者”怪兽或“忍法”卡牌的效果特殊召唤。\r\n①：１回合１次，可从手牌及我方场上的表侧表示卡牌中，将１只“忍者”怪兽与１张“忍法”卡牌送入墓地，并以场上最多２张魔法、陷阱卡为对象发动。破坏该卡。此效果在对手回合也可发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90263923,'闪光吸收','选择对手场上１只表侧表示的光属性怪兽来发动此卡。我方场上所有表侧攻击表示的怪兽的攻击力上升所选择怪兽的攻击力数值，直到结束阶段时。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90276649,'幻奏歌姬 库蒲蕾',replace(replace('←9 【灵摆】 9→\r\n此卡名的②灵摆效果１回合仅可使用１次。\n①：自己仅可灵摆召唤光属性怪兽。此效果不会被无效化。\n②：自己场上不存在“幻奏”怪兽以外的表侧表示怪兽的情况下可以发动。从牌组将１张“幻奏”魔法・陷阱卡加入手牌。\r\n【怪兽效果】\r\n此卡名的①②怪兽效果１回合仅可各使用１次。\n①：此卡以通常抽牌以外的方法加入手牌的情况下，将此卡出示给对手可以发动。从自己的手牌・墓地将１只等级４以下的“幻奏”怪兽特殊召唤。\n②：此卡以表侧存在于额外牌组的状态下，“幻奏”融合怪兽被特殊召唤至自己场上的情况下可以发动。将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90290572,'代行者的近卫 沐恩',replace(replace('天使族怪兽2只\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡连接召唤的情况下可以发动。从牌组将1张“天空的圣域”或记载有该卡名的卡送至墓地。自己或对手的、场上或墓地存在“天空的圣域”的情况下，作为代替也可从自己牌组・墓地将1只“神秘之代行者 娅丝”加入手牌。\r\n②：解放自己场上的1只天使族怪兽，以对手场上的1张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','','是否把「神秘之代行者 娅丝」加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90299015,'吸血鬼的幽鬼','此卡名的①②效果１回合仅可各使用１次。①：此卡召唤成功的情况下，从手牌及自己场上表侧表示的卡中，将此卡以外的１张“吸血鬼”卡送至墓地可以发动。从牌组将１只等级４以上的“吸血鬼”怪兽加入手牌，从牌组将１只等级２以下的“吸血鬼”怪兽送至墓地。②：在自己・对手的主要阶段，将墓地的此卡除外，支付５００LP可以发动。召唤１只“吸血鬼”怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90303176,'寂静鮟鱇','①：自己场上存在水属性怪兽的情况下，此卡可从手牌特殊召唤。以此方法特殊召唤过的余下本回合，自己不可从手牌特殊召唤怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90303227,'K9－EX “狼人”',replace(replace('等级9怪兽×2\r\n此卡名的②效果1回合仅可使用1次。\r\n①：持有超量素材的此卡在1次战斗阶段中最多可攻击相当于其素材数量的次数。\r\n②：对手发动效果时，去除此卡的1个超量素材，根据发动回合可以发动以下效果。\r\n●自己回合：将对手场上及墓地的卡最多各1张除外。\r\n●对手回合：确认对手的手牌，挑选其中1张直至结束阶段为止以表侧除外。','\r',char(13)),'\n',char(10)),'除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90307498,'元素－英雄 新宇智者',replace(replace('“元素－英雄 新宇侠”＋“尤贝尔”\r\n此卡仅可以融合召唤方式特殊召唤。\r\n此卡名的②效果１回合仅可使用１次。\r\n①：此卡与对手怪兽进行战斗的伤害计算前可以发动。给予对手相当于该对手怪兽攻击力数值的伤害。\r\n②：表侧表示的此卡因对手的效果从场上离开的情况下，或因战斗被破坏的情况下可以发动。从手牌・牌组将１只“新宇贤人”无视召唤条件特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90307777,'影灵衣的术士 休里特',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：要仪式召唤1只“影灵衣”仪式怪兽的情况下，使用1张此卡即可作为仪式召唤所必需等级的解放。\r\n②：此卡因效果被解放的情况下可以发动。从牌组将1只战士族“影灵衣”仪式怪兽加入手牌。','\r',char(13)),'\n',char(10)),'牌组检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90311614,'冰结界的水影','①：自己场上表侧表示的怪兽仅有等级２以下的怪兽的情况下，此卡可直接攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90312154,'失落的圣域',replace(replace('此卡名的卡１回合仅可发动１张，此卡名的③效果１回合仅可使用１次。\r\n①：作为此卡发动时的效果处理，从牌组挑选１张“天空的圣域”或记载有该卡名的魔法・陷阱卡放置在自己场上。\r\n②：此卡只要存在于场上・墓地，卡名视为“天空的圣域”。\r\n③：从自己的墓地将１只天使族怪兽除外，以对手场上的１只效果怪兽为对象可以发动。将该怪兽的效果直至回合结束时为止无效。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90315086,'喷气机鲨',replace(replace('此卡名的②③效果1回合1次，仅可使用其中1个。\r\n①：场上存在水属性超量怪兽的情况下，此卡可从手牌特殊召唤。以此方法特殊召唤过的余下本回合，自己不可特殊召唤“喷气机鲨”。\r\n②：在自己的主要阶段可以发动。从牌组将1只鱼族的“鲨”怪兽或1张“超量”魔法・陷阱卡送至墓地。\r\n③：从墓地将此卡除外可以发动。从自己牌组・墓地将1张“水波喷气机”卡加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','送至墓地','检索','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90330453,'魔女狩猎','破坏场上所有表侧表示的魔法师族怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90330454,'魔女狩猎','破坏场上所有表侧表示的魔法师族怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90337190,'鱼雷鱼','只要“海”存在于场上，此卡便不会受到魔法效果的影响。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90351981,'自鸣天琴・巴别塔','①：只要此卡存在于场地区域，原本卡名包括“自鸣天琴”的、自己场上的连接怪兽及自己墓地的怪兽发动的效果，变为在对手回合也可以发动的效果。②：此卡存在于墓地的情况下，将1张手牌送至墓地可以发动。将墓地的此卡加入手牌。此效果在此卡被送至墓地的回合不可发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90357090,'银牙','闪耀银白色光芒的狼。外观优美，但性情凶暴。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90359458,'顶级份享','此卡名的卡１回合仅可发动１张。①：从牌组挑选１张卡，双方确认并放在牌组最上面。然后，对手从自身的牌组挑选１张卡，双方确认并放在自身的牌组最上面。','请选择要放置在牌组最上面的卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90361010,'超重武者装魂 岩融','①：在自己的主要阶段，以自己场上的１只“超重武者”怪兽为对象可以发动。从自己的手牌・场上将此怪兽视为装备卡，装备于该自己的怪兽。②：以此卡的效果装备此卡的怪兽攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。③：此卡从场上被送至墓地的情况下可以发动。从牌组将１只“超重武者装魂 岩融”以外的“超重武者”怪兽加入手牌。','给「超重武者」怪兽装备','牌组检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90361289,'机巧狐－宇迦之御魂稻荷','此卡名的①②效果1回合仅可各使用1次。①：怪兽从牌组被特殊召唤的情况下可以发动。从手牌将此卡特殊召唤。②：此卡召唤・特殊召唤成功的情况下，以对手场上的1只表侧表示怪兽为对象可以发动。从手牌・牌组将1只攻击力与守备力数值相同、属性与对象怪兽相同的怪兽特殊召唤。③：每次对手召唤・特殊召唤怪兽成功发动。给予对手300伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90365482,'河伯',replace(replace('此卡不可特殊召唤。\r\n①：此卡召唤・反转的情况下，以场上的１只表侧表示怪兽为对象可以发动。该表侧表示怪兽改视为灵魂怪兽，将在结束阶段返回持有者的手牌。\r\n②：在此卡召唤・反转的回合的结束阶段发动。将此卡放回持有者的手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90374791,'武装转换','将我方手牌中的１张装备魔法卡送入墓地来发动此卡。装备怪兽通过战斗破坏怪兽的场合，装备卡的控制者可将自己墓地中１只攻击力在装备怪兽以下的怪兽加入到手牌中。','加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90384300,'极超辰醒',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：从手牌及自己场上的表侧表示怪兽中，将不可通常召唤的２只怪兽以里侧表示除外可以发动。自己从牌组抽２张。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90386276,'无罪的罪宝',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：可从以下效果中选择1个发动。\r\n●以自己墓地・除外状态的1只“迪亚贝尔”怪兽为对象可以发动。挑选自己的1张手牌舍弃，将对象怪兽特殊召唤。\r\n●以自己魔法与陷阱区域的1张表侧表示怪兽卡为对象可以发动。将该卡特殊召唤。','\r',char(13)),'\n',char(10)),'以墓地·除外状态的卡为对象','以魔法与陷阱区域的卡为对象','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90397998,'六武众－扫部','我方场上存在有除“六武众－扫部”以外的冠有“六武众”之名的怪兽的场合，１回合１次，可选择场上的１张表侧表示的魔法、陷阱卡破坏。发动此效果的回合，此卡不可进行攻击宣言。此外，场上的此卡被破坏的场合，可破坏我方场上的１只冠有“六武众”之名的怪兽作为代替。','表侧的1张魔法·陷阱卡破坏','是否要使用「六武众－扫部」的代替破坏效果？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90407382,'蹴杀者','此卡特殊召唤成功时，可将我方墓地的１张装备魔法卡装备至此卡。','装备','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90411554,'岩征龙－石壑',replace(replace('此卡名的①～④效果１回合１次，仅可使用其中１个。\r\n①：从手牌将此卡与１只地属性怪兽舍弃至墓地，以自己墓地的１只怪兽为对象可以发动。将该怪兽特殊召唤。\r\n②：从自己的手牌・墓地将２只龙族或地属性的怪兽除外可以发动。从手牌・墓地将此卡特殊召唤。\r\n③：此卡是被特殊召唤的情况下，在对手的结束阶段发动。将此卡放回手牌。\r\n④：此卡被除外的情况下可以发动。从牌组将１只龙族・地属性怪兽加入手牌。','\r',char(13)),'\n',char(10)),'从手牌特殊召唤','返回手牌','选择自己墓地1只怪兽特殊召唤','加入手牌','','','','','','','','','','','','');
INSERT INTO texts VALUES(90432163,'魅影骑士团沾尘袍','此卡名的①②效果1回合仅可各使用1次。①：此卡在场上以攻击表示存在的情况下，以场上1只暗属性怪兽为对象可以发动。将此卡改成守备表示，对象的怪兽的攻击力・守备力直至对手回合结束时为止上升800。②：将墓地的此卡除外可以发动。从牌组将1张“魅影骑士团沾尘袍”以外的“魅影骑士团”卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90434657,'死灵谷的王墓','场上有冠有“守墓的”之名的怪兽及“王家长眠之谷－死灵谷”存在的场合可发动此卡。令效果怪兽的效果・魔法・陷阱卡的发动无效并破坏。１个回合中只可发动１张“死灵谷的王墓”。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90434926,'漆黑的帷幕','我方抽牌阶段时抽取的卡牌为暗属性怪兽的场合，通过将该卡展示给对手，将该卡送入墓地。之后，可从我方牌组抽取１张卡牌。','再次抽牌','是否要抽牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90440725,'电子阴影守卫者','可在对手主要阶段时发动。此卡发动后，变成效果怪兽（机械族、地、星４、攻／守？），并特殊召唤至怪兽区。以此卡为攻击对象的对手怪兽的攻击宣言时，此卡的攻击力、守备力变成与该攻击怪兽相同数值。此卡在对手结束阶段时被盖牌至魔法与陷阱区域。此卡也被视为陷阱卡。','魔陷区放置','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90444325,'巨石异物・黑吉斯','以“巨石异物”卡降临。此卡名的②效果1回合仅可使用1次。①：此卡仪式召唤成功的情况下可以发动。从牌组将1张“巨石异物”魔法・陷阱卡加入手牌。②：在自己的主要阶段可以发动。为使合计等级为仪式召唤的怪兽以上，解放包括场上的此卡的自己手牌・场上的怪兽，从手牌将1只仪式怪兽仪式召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90448279,'神灭兵器－天霆号 扼宙斯',replace(replace('等级12怪兽×2\r\n在超量怪兽战斗过的每个回合有1次，“神灭兵器－天霆号 扼宙斯”也可重叠在自己场上的超量怪兽上面来超量召唤。\r\n①：在自己・对手回合中，去除此卡的2个超量素材可以发动。将场上其他的卡全部送至墓地。\r\n②：1回合1次，自己场上的其他卡因战斗或对手的效果被破坏的情况下可以发动。从手牌・牌组・额外牌组将1张卡作为此卡的超量素材。','\r',char(13)),'\n',char(10)),'是否在超量怪兽上面重叠来超量召唤？','全部送至墓地','补充超量素材','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90448280,'神灭兵器－天霆号 扼宙斯',replace(replace('等级12怪兽×2\r\n在超量怪兽战斗过的每个回合有1次，“神灭兵器－天霆号 扼宙斯”也可重叠在自己场上的超量怪兽上面来超量召唤。\r\n①：在自己・对手回合中，去除此卡的2个超量素材可以发动。将场上其他的卡全部送至墓地。\r\n②：1回合1次，自己场上的其他卡因战斗或对手的效果被破坏的情况下可以发动。从手牌・牌组・额外牌组将1张卡作为此卡的超量素材。','\r',char(13)),'\n',char(10)),'是否在超量怪兽上面重叠来超量召唤？','全部送至墓地','补充超量素材','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90448281,'神灭兵器－天霆号 扼宙斯',replace(replace('等级12怪兽×2\r\n在超量怪兽战斗过的每个回合有1次，“神灭兵器－天霆号 扼宙斯”也可重叠在自己场上的超量怪兽上面来超量召唤。\r\n①：在自己・对手回合中，去除此卡的2个超量素材可以发动。将场上其他的卡全部送至墓地。\r\n②：1回合1次，自己场上的其他卡因战斗或对手的效果被破坏的情况下可以发动。从手牌・牌组・额外牌组将1张卡作为此卡的超量素材。','\r',char(13)),'\n',char(10)),'是否在超量怪兽上面重叠来超量召唤？','全部送至墓地','补充超量素材','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90448282,'神灭兵器－天霆号 扼宙斯',replace(replace('等级12怪兽×2\r\n在超量怪兽战斗过的每个回合有1次，“神灭兵器－天霆号 扼宙斯”也可重叠在自己场上的超量怪兽上面来超量召唤。\r\n①：在自己・对手回合中，去除此卡的2个超量素材可以发动。将场上其他的卡全部送至墓地。\r\n②：1回合1次，自己场上的其他卡因战斗或对手的效果被破坏的情况下可以发动。从手牌・牌组・额外牌组将1张卡作为此卡的超量素材。','\r',char(13)),'\n',char(10)),'是否在超量怪兽上面重叠来超量召唤？','全部送至墓地','补充超量素材','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90452877,'星际仙踪－能量术',replace(replace('“星际仙踪－能量术”１回合仅可发动１张。\r\n①：以自己场上的１只“星际仙踪”怪兽为对象可以发动。将该怪兽破坏，挑选对手场上・墓地的１张卡除外。','\r',char(13)),'\n',char(10)),'除外场上1张卡','除外墓地1张卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90464188,'黑曜岩龙','只要此卡以表侧表示存在于场上，使以我方场上的１只暗属性怪兽为对象的魔法、陷阱卡的效果无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90465153,'玛那桃圆乡・普莱姆哈忒',replace(replace('１只以上协调＋１只光属性怪兽\r\n①：此卡在１次战斗阶段中可攻击的次数最多相当于其同步素材中协调的数量。②：以“玛那桃圆乡”协调作为素材同步召唤的此卡不会成为对手效果的对象。③：同步召唤的、表侧表示的此卡因对手从场上离开的情况下可以发动。从自己墓地的怪兽及被除外的自己的怪兽中，挑选１只“维萨思・史塔弗罗斯特”或攻击力１５００／守备力２１００的怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'「玛那桃圆乡」协调为素材作同步召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90470931,'鬼神连击','选择我方战场上的１只超量怪兽，可以移除其全部超量素材发动。本回合内，选择的怪兽在１次战斗阶段中可以进行２次攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90488465,'混沌创世神',replace(replace('此卡不可通常召唤。\r\n从自己墓地将光・暗属性怪兽各1只除外的情况下可以特殊召唤。\r\n此卡名的效果1回合仅可使用1次。\r\n①：此卡是从手牌特殊召唤的情况下，以自己・对手除外状态的合计3只怪兽为对象可以发动（同名卡最多1张）。将其中1只特殊召唤至自己场上，剩余的以喜欢的顺序放回牌组下面。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90500169,'等级下降！？','可选择场上１只冠有“LV”之名的怪兽并发动。被选择怪兽返回至持有者牌组，并从持有者的墓地挑选１只含有该怪兽卡牌名的“LV”较低的怪兽，无视特殊召唤条件，特殊召唤至持有者的场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90502999,'地层沉陷',replace(replace('指定２个没有使用的主要怪兽区域可以发动此卡。\r\n①：只要此卡存在于魔法与陷阱区域，便不可使用指定的区域。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90508760,'X－军刀 艾亚贝伦','①：此卡以直接攻击给予对手战斗伤害的情况下发动。随机舍弃对手的1张手牌。','丢弃手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90512490,'超刃蝇',replace(replace('风属性怪兽2只\r\n此卡名的②效果1回合仅可使用1次。①：场上的风属性怪兽的攻击力・守备力上升500，地属性怪兽的攻击力・守备力下降400。②：此卡因战斗・效果被破坏的情况下，以自己墓地的1只风属性怪兽为对象可以发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90519313,'检疫','①：可以在我方、对手的结束阶段被盖牌在对手场地的１张魔法、陷阱卡为对象发动此效果。确认该卡牌，返回至原处。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90555947,'大植然盖亚星狮',replace(replace('地属性同步怪兽×２\r\n①：仅以场上的１张卡为对象的魔法・陷阱・怪兽的效果发动时，将１张手牌送至墓地可以发动。将该发动无效并破坏。','\r',char(13)),'\n',char(10)),'无效并破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90557975,'上升气流','移除场上所有的雾计数物可以发动。给予对手LP被移除的雾计数物数量×３００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90576781,'爬虫妖之毒','我方场上存在有冠有“爬虫妖”之名怪兽的场合可发动。选择对手场上１只守备表示怪兽并变更为表侧攻击表示，将该怪兽的攻击力变成０。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90579153,'命运－英雄 敌托邦魔侠',replace(replace('“命运－英雄”怪兽×2\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡特殊召唤的情况下，以自己墓地的1只等级4以下的“命运－英雄”怪兽为对象可以发动。给予对手相当于该怪兽攻击力数值的伤害。\r\n②：在自己・对手回合中，此卡的攻击力与原本攻击力不同的情况下，以场上的1张卡为对象可以发动（不可在伤害步骤发动）。将该卡破坏，此卡的攻击力变为原本数值。','\r',char(13)),'\n',char(10)),'给与对手伤害','场上1张卡破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90582719,'剑斗兽 孤眼','以强大攻击力将敌手逼入绝境的独眼战斗熊。它那引以为傲的重拳有着惊人的速度和威力，一旦出拳，便无人能敌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90583279,'八雷天神',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：将自己墓地１只等级或阶级为８的怪兽除外，可将此卡从手牌特殊召唤。\r\n②：以自己墓地１只等级或阶级为８的仪式・融合・同步・超量怪兽为对象可以发动。将该怪兽放回牌组。然后，依放回的怪兽的种类适用以下效果。\r\n●仪式・融合：自己从牌组抽１张。\r\n●同步・超量：此卡的攻击力上升１０００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90587641,'超重神将 遮那王－O',replace(replace('←1 【灵摆】 1→\r\n此卡名的灵摆效果１回合仅可使用１次。①：对手怪兽攻击宣言时可以发动。将此卡特殊召唤。自己墓地不存在魔法・陷阱卡的情况下，进而该对手怪兽的攻击力变为０，效果无效化。\r\n【怪兽效果】\r\n协调＋１只以上协调以外的怪兽\n此卡名在规则上也视为“超重武者”卡。①：此卡可在表侧守备表示的状态下攻击。该情况下，将此卡的守备力视为攻击力来进行伤害计算。②：此卡是被同步召唤的情况下，１回合１次，在自己・对手的战斗阶段可以发动。从自己的墓地及自己的魔法与陷阱区域的表侧表示卡中，挑选１张“超重武者”怪兽卡特殊召唤。然后，可将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'','','是否将此卡在灵摆区域放置？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90590303,'编号41 泥睡魔兽 貘熟梦',replace(replace('等级4怪兽×2\r\n此卡的控制者在每次自己的准备阶段去除此卡的1个超量素材（无法去除的情况下，将此卡破坏）。\r\n①：只要此卡以攻击表示存在于怪兽区域，此卡不会因对手的效果被破坏，对手不可将此卡作为效果的对象。\r\n②：只要此卡以守备表示存在于怪兽区域，场上的表侧表示怪兽变为守备表示，守备表示怪兽发动的效果无效化。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90590304,'编号41 泥睡魔兽 貘熟梦',replace(replace('等级4怪兽×2\r\n此卡的控制者在每次自己的准备阶段去除此卡的1个超量素材（无法去除的情况下，将此卡破坏）。\r\n①：只要此卡以攻击表示存在于怪兽区域，此卡不会因对手的效果被破坏，对手不可将此卡作为效果的对象。\r\n②：只要此卡以守备表示存在于怪兽区域，场上的表侧表示怪兽变为守备表示，守备表示怪兽发动的效果无效化。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90592429,'大日神械灯丝','仅限装备冠有“大日神械”之名的怪兽。装备怪兽攻击的场合，直至伤害步骤结束时，对手不可发动魔法、陷阱卡。场上表侧表示的此卡被送入墓地的场合可发动。从牌组将１张冠有“大日神械”之名的魔法卡加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90616316,'魔轰神兽佩嘎拉萨斯','此卡从手牌被舍弃至墓地时，可以里侧守备表示从墓地特殊召唤此卡。此外，此卡反转时，可向对手展示手牌１只冠有“魔轰神”之名的怪兽并发动。从牌组将１只冠有“魔轰神”之名的怪兽送入墓地。','在自己场上放置','送至墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90640901,'反转破击者','此卡仅可攻里侧守备表示怪兽。此卡进行攻击的场合，直至伤害步骤结束时，对手不可发动魔法、陷阱卡。此卡攻击了里侧守备表示怪兽的伤害步骤开始时可发动。破坏该里侧守备表示怪兽。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90642597,'未来武士',replace(replace('此卡存在于墓地或以表侧表示存在于场上的场合，将被视为通常怪兽。以通常召唤的方式再次召唤场上表侧表示的此卡，此卡将视为效果怪兽并获得以下效果。\r\n●将我方墓地中的１只怪兽从游戏中除外，破坏场上１只表侧表示的怪兽。此效果在１个回合中只可使用１次。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90654356,'暗黑翼龙','当此卡从场上被战斗破坏以外的方法送入墓地时，此卡回到持有者的手牌中。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90659259,'变形斗士・转换装置',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：以自己场上的１只机械族怪兽为对象可以发动。根据该怪兽的表示形式，适用以下效果。\r\n●攻击表示：将１只卡名与对象怪兽不同的“变形斗士”怪兽从牌组特殊召唤。然后将对象怪兽放回持有者的牌组最上面。\r\n●守备表示：将对象怪兽改成攻击表示，从手牌将１只等级４以下的机械族怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90660762,'陨星黑龙','“真红眼黑龙”＋“陨星龙”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90664684,'龙华袭焉',replace(replace('此卡名的②③效果1回合仅可各使用1次。\r\n①：对手不可将自己场上的“龙华”怪兽作为效果的对象。\r\n②：自己额外牌组（表侧）或场上存在“龙华”灵摆怪兽的情况下，将自己手牌・墓地・除外状态的2只“龙华”怪兽放回牌组，以场上的1只怪兽为对象可以发动。将该怪兽破坏。\r\n③：此卡被破坏的情况下可以发动。将永续陷阱卡以外的、自己牌组・墓地・除外状态的1张“龙华”陷阱卡放置在自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90664857,'电脑堺玄－甲甲',replace(replace('等级３怪兽×２只以上\r\n①：１回合１次，去除此卡的１个超量素材，以自己场上的１只表侧表示怪兽为对象可以发动。直至对手回合结束时为止，该怪兽不会因战斗被破坏。②：１回合１次，自己墓地有２只以上原本种族・属性相同的怪兽存在，此卡与对手怪兽进行战斗的伤害计算后可以发动。将该对手怪兽除外。','\r',char(13)),'\n',char(10)),'不会被战斗破坏','除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90669991,'菠萝爆弹','我方怪兽召唤成功时可发动。对手场上的怪兽数量多于我方控制的怪兽数量的场合，破坏对手的卡牌使数量变得相同。破坏的卡牌由对手选择。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90673288,'闪刀姬－雫',replace(replace('水属性以外的“闪刀姬”怪兽1只\r\n自己1回合仅可特殊召唤1次“闪刀姬－雫”。\r\n①：对手场上的怪兽的攻击力・守备力下降自己墓地的魔法卡数量×100的数值。\r\n②：此卡特殊召唤的回合的结束阶段可以发动。从牌组将同名卡不存在于自己墓地的1张“闪刀”魔法卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90673289,'闪刀姬－雫',replace(replace('水属性以外的“闪刀姬”怪兽1只\r\n自己1回合仅可特殊召唤1次“闪刀姬－雫”。\r\n①：对手场上的怪兽的攻击力・守备力下降自己墓地的魔法卡数量×100的数值。\r\n②：此卡特殊召唤的回合的结束阶段可以发动。从牌组将同名卡不存在于自己墓地的1张“闪刀”魔法卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90673413,'我我我复仇','①：以自己墓地的１只“我我我”怪兽为对象可以发动此卡。将该怪兽特殊召唤，装备此卡。此卡从场上离开时，该怪兽将被破坏。②：装备怪兽被作为超量素材导致此卡被送至墓地的情况下发动。自己场上的所有超量怪兽的攻击力上升３００。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90681088,'真炎王 珀尼克斯',replace(replace('此卡名的①②③效果１回合仅可各使用１次。\r\n①：原本属性为炎属性的自己的怪兽因战斗・效果被破坏的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从牌组将１张“炎王”魔法・陷阱卡加入手牌。\r\n③：此卡被破坏并被送至墓地的情况下，在下个准备阶段发动。将墓地的此卡加入手牌。','\r',char(13)),'\n',char(10)),'此卡从手牌特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90711610,'格布林百罗刹大参上',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：从牌组将１只“格布林”怪兽加入手牌。然后，可适用以下效果。\r\n●去除场上的１个超量素材，从手牌将１只等级４以下的“格布林”怪兽特殊召唤。\r\n②：将墓地的此卡除外可以发动。去除场上的１个超量素材。然后，可从自己的墓地将１只“格布林”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'牌组检索','取除超量素材','是否取除超量素材特殊召唤？','是否选墓地的怪兽加入手牌？','','','','','','','','','','','','');
INSERT INTO texts VALUES(90724272,'暗蔷薇之妖精','此卡名的①②效果１回合仅可各使用１次。①：协调被特殊召唤的情况下可以发动。从手牌将此卡特殊召唤。②：此卡存在于墓地的情况下，将自己手牌・场上的１张卡送至墓地可以发动。将此卡放回牌组最上面或最下面。','特殊召唤','回到牌组','牌组最上面','牌组最下面','','','','','','','','','','','','');
INSERT INTO texts VALUES(90726340,'龙魔人 女王龙',replace(replace('等级４怪兽×２\r\n①：１回合１次，去除此卡的１个超量素材，以自己墓地的１只等级５以上龙族怪兽为对象可以发动。将该龙族怪兽特殊召唤。以此效果特殊召唤的怪兽的效果无效化，此回合不可攻击。②：只要此卡存在于怪兽区域，“龙魔人 女王龙”以外的自己的龙族怪兽不会因战斗被破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90727556,'侵邪蚀的巡逻','我方场上不存在有魔法、陷阱卡的场合，在我方主要阶段１的开始时可发动。从墓地特殊召唤此卡。发动此效果的回合，我方不可以除此效果以外的方式特殊召唤怪兽。此卡不可进行除冠有“侵邪蚀”之名怪兽的上级召唤以外为目的的释放，也不可作为同步素材。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90728287,'无垢奥艺－“幻创之贤者”',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：以自己场上・墓地的最多3只“奥艺”怪兽为对象可以发动。将该怪兽除外。然后，以其数量为上限，可将场上的其他表侧表示卡的效果直至回合结束时为止无效。\r\n②：将墓地的此卡除外可以发动。从自己墓地将1只“狱神”连接怪兽放回额外牌组。然后，可将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'除外效果','回到额外','是否把卡无效？','是否特殊召唤？','','','','','','','','','','','','');
INSERT INTO texts VALUES(90740329,'挑衅','可在对手主要阶段１选择我方场上的１只怪兽并发动。只要被选择怪兽存在于场上，此回合对手以怪兽进行攻击的场合，只能选择被选择怪兽为攻击对象。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90740330,'挑衅','可在对手主要阶段１选择我方场上的１只怪兽并发动。只要被选择怪兽存在于场上，此回合对手以怪兽进行攻击的场合，只能选择被选择怪兽为攻击对象。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90743290,'魔导老士 耶尔密特','只要此卡以表侧表示存在于场上，每次冠有“魔导书”之名的魔法卡发动，此卡等级上升２级，攻击力上升３００点。','等级攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90764871,'恶魔的棋盘游戏',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：额外怪兽区域的恶魔族怪兽的攻击力上升1000。\r\n②：可从以下效果中选择1个发动。\r\n●从自己手牌・墓地将1只恶魔族怪兽或1张“恶魔”卡除外可以发动。从牌组将场地魔法卡以外的1张“恶魔”卡加入手牌。\r\n●从牌组将1只“恶魔”灵摆怪兽以表侧加入额外牌组。','\r',char(13)),'\n',char(10)),'检索效果','加入额外','请选择要加入额外牌组的卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90764875,'蛇魔・食尸鬼',replace(replace('此卡名的效果1回合最多可使用2次。\r\n①：此卡存在于手牌，且自己场上存在“蛇魔・食尸鬼”的情况下，支付300LP可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90788081,'百岁龙',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：1回合1次，在自己的主要阶段可以发动。直至回合结束时为止，此卡的等级上升相当于自己场上的卡的数量，此卡的攻击力上升相当于所上升的等级×100的数值。\r\n②：此卡被送至墓地的情况下，以被从额外牌组特殊召唤的、自己场上的1只表侧表示怪兽为对象可以发动。只要该怪兽以表侧表示存在于场上，仅限1次，不会因战斗・效果被破坏。','\r',char(13)),'\n',char(10)),'','','「百岁龙」效果适用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90790253,'小翼守卫','在我方结束阶段时可发动。变更此卡的表示形式。','改变表示形式','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90807199,'未界域之雷鸟','此卡名的②效果1回合仅可使用1次。①：向对手出示手牌中的此卡可以发动。对手从自己的所有手牌中随机挑选1张，自己舍弃该卡。该卡为“未界域之雷鸟”以外的情况下，进而从手牌将1只“未界域之雷鸟”特殊召唤，自己从牌组抽1张。②：此卡从手牌被舍弃的情况下，以1张被放置在对手场上的卡为对象可以发动。将该卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90809975,'镜饼蛙',replace(replace('水族等级2怪兽×2\r\n①：在双方的准备阶段，去除此卡的1个超量素材可以发动。从牌组将1只“青蛙”怪兽特殊召唤。\r\n②：1回合1次，对手发动怪兽的效果・魔法・陷阱卡时，从自己手牌・场上（表侧表示）将1只水族怪兽送至墓地可以发动。将该发动无效并破坏。然后，可将所破坏的卡放置在自己场上。\r\n③：此卡被送至墓地的情况下，以自己墓地的1只水属性怪兽为对象可以发动。将其加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','无效并破坏','加入手牌','是否把破坏的卡在自己场上放置？','是否把破坏的卡在自己场上放置？','','','','','','','','','','','');
INSERT INTO texts VALUES(90810762,'逆卷炎之精灵','此卡可直接攻击对手玩家。此卡因直接攻击而给予对手生命战斗伤害时，此卡的攻击力上升１０００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90812044,'连锁召唤','①：自己场上有２只以上的超量怪兽存在的情况下，以其中阶级最低的１只超量怪兽为对象可以发动。将１只阶级低于该怪兽的超量怪兽从额外牌组特殊召唤。以此效果特殊召唤的怪兽不可直接攻击，将在结束阶段放回额外牌组。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90814668,'暴君农场',replace(replace('此卡名的卡片１回合只可发动１张。\r\n①：解放１只我方场上的效果怪兽可发动。原种族／属性与该怪兽相同，则从我方墓地选择１只除效果怪兽之外的怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90829280,'尤贝尔之精灵',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：对手怪兽攻击宣言时可以发动。从手牌将此卡特殊召唤。\r\n②：此卡特殊召唤的情况下可以发动。从牌组挑选１张记载有“尤贝尔”卡名的魔法・陷阱卡，加入手牌或放置在自己场上。\r\n③：此卡不会因战斗被破坏，因此卡的战斗对自己造成的战斗伤害变为０。\r\n④：此卡被破坏的情况下可以发动。将自己的手牌・牌组・墓地・除外状态的１只“尤贝尔”特殊召唤。','\r',char(13)),'\n',char(10)),'从手牌特殊召唤','检索魔法·陷阱','','特殊召唤「尤贝尔」','','','','','','','','','','','','');
INSERT INTO texts VALUES(90835938,'圣夜煌龙',replace(replace('①：此卡从手牌的召唤・特殊召唤成功的情况下，以场上的１张卡为对象可以发动。将该卡破坏。\r\n②：场上的此卡不会因与暗属性怪兽的战斗被破坏，不会因暗属性怪兽的效果被破坏。\r\n③：１回合１次，此卡攻击对手怪兽的伤害步骤开始时可以发动。将该对手怪兽直至结束阶段为止除外。发动过此效果的情况下，此卡可继续再攻击仅１次。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90844184,'六剑兽','由“六剑兽的宣誓”降临。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90846359,'群雄割据','①：只要此卡存在于魔法与陷阱区域，双方场上各自仅可有1种种族的怪兽以表侧表示存在。双方玩家自身场上的表侧表示怪兽的种族有2种以上的情况下，必须将怪兽送至墓地，直至只剩1种为止。','请选择要保留的种族','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90861137,'『焰圣剑－咎瓦尤斯』','此卡名的①②效果１回合１次，仅可使用其中１个。①：此卡被装备中的情况下，以自己墓地的１只战士族・炎属性怪兽为对象可以发动。将该怪兽加入手牌。然后破坏此卡。②：因装备怪兽被送至墓地导致此卡被送至墓地的情况下可以发动。从手牌将１只战士族・炎属性怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90873992,'战士抹杀','破坏场上所有表侧表示的战士族怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90875418,'预幻使 墨迪乌斯',replace(replace('此卡名在规则上也视为“狱神”卡。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：场上存在“狱神”卡的情况下可以发动。从手牌将此卡特殊召唤。然后，可从牌组将1张“预幻”魔法・陷阱卡加入手牌。\r\n②：有怪兽以表侧被除外的情况下，可从以下效果中选择1个发动。\r\n●从牌组将1张“奥艺”卡加入手牌。\r\n●将此卡除外，从额外牌组将1只“迪亚克特罗斯”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','选择效果','是否加入手牌？','检索效果','特殊召唤','','','','','','','','','','','');
INSERT INTO texts VALUES(90876561,'卫兵骑士','精通所有剑术的战士。正义感很强，为守护弱者而战。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90880453,'耀圣诗章～再会的三重唱～',replace(replace('①：对手不可将自己中央的主要怪兽区域的怪兽作为效果的对象。\r\n②：根据自己中央的主要怪兽区域的怪兽的属性，此卡获得以下效果。\r\n●炎・地：自己的同步怪兽攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。\r\n●水・风：自己场上其他的表侧表示的魔法・陷阱卡不会因对手的效果被破坏。\r\n●光・暗：自己受到的战斗伤害变为0。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90884403,'究极幻神 奥特美特尔・比希巴尔金',replace(replace('按照规则，此卡的等级被视为１２。\r\n此卡不可同步召唤，仅限将我方场上等级是８或以上并且相同等级的协调与协调以外的怪兽各１只送入墓地的场合，可特殊召唤。\r\n①：此卡不会因效果被破坏，攻击力上升场上怪兽的数量×１０００。\r\n②：１回合１次，在我方、对手的主要阶段可发动。尽可能地以守备表示特殊召唤相同数量的“邪眼神衍生物”（恶魔族、暗、星１、攻／守０）至双方的场上。此回合此卡不可进行攻击。','\r',char(13)),'\n',char(10)),'特殊召唤衍生物','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90884404,'邪眼神衍生物','由“究极幻神 奥特美特尔・比希巴尔金”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90885155,'机壳壳层',replace(replace('←9 【灵摆】 9→\r\n①：我方只可特殊召唤“机壳”怪兽。此效果不会被无效化。\n②：对手场上怪兽的攻击力下降３００。\r\n【怪兽效果】\r\n①：此卡可无需释放进行召唤。\n②：以特殊召唤或无需释放召唤而来的此卡之等级变成４，原本攻击力变成１８００。\n③：通常召唤而来的此卡不受原本等级或阶级低于此卡等级之怪兽所发动的效果影响。\n④：释放“机壳”怪兽并以表侧表示上级召唤此卡成功的场合，此卡可在１次的战斗阶段中进行２次攻击，攻击了守备表示怪兽的场合，给予相当于攻击力超过该守备力数值的战斗伤害。','\r',char(13)),'\n',char(10)),'不用解放作召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90887783,'龙之交感','向对手展示手牌中的１只龙族怪兽，将牌组中１只与所展示怪兽相同等级的龙族怪兽加入到手牌中。之后，将展示的怪兽放回至牌组。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90908427,'铁腕魔像','用钢铁制成的机械人偶，对自己惊人的怪力相当自豪。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90925163,'跳舞妖精','只要此卡以表侧守备表示存在于我方场上，每次我方的准备阶段，我方回复１０００LP。','回复','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90928333,'暗的量产工厂','①：可以我方墓地中的２只通常怪兽为对象发动此卡。将对象怪兽加入到手牌中。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90934570,'侵略的侵蚀崩坏','选择我方场上１只冠有“邪蚀”之名的怪兽并从游戏中除外，选择对手场上的２张卡牌并返回至持有者手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90939874,'六武式真传天魔六段冲',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：自己场上存在3种以上的“六武众”同步怪兽的情况下可以发动（自己场上的武士道计数物每有6个，则为发动此卡所需的怪兽种类减少1种）。将对手场上的卡全部破坏。\r\n②：被放置的此卡因对手所发动的效果，被破坏的情况下或被除外的情况下可以发动。从牌组・额外牌组将1只“六武众”怪兽或“紫炎”效果怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'破坏','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90946420,'格布林百罗刹大重叠',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：以自己场上的１只超量怪兽为对象可以发动。将１只“格布林”超量怪兽重叠在对象的自己的超量怪兽上面，视为超量召唤从额外牌组特殊召唤，将此卡作为其超量素材。\r\n②：将墓地的此卡除外，以自己场上的１只“格布林”超量怪兽和自己或对手墓地的１张卡为对象可以发动。将对象的墓地卡作为对象的场上怪兽的超量素材。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90951921,'先史遗产技术','可选择我方墓地的１只冠有“先史遗产”之名的怪兽并发动。将被选择的怪兽从游戏中除外。之后，从我方牌组的上方确认２张卡牌，并从中挑选１张加入手牌，剩余卡牌送入墓地。“先史遗产技术”１回合只可发动１张，发动此卡的回合，我方只可特殊召唤冠有“先史遗产”的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90953320,'T.G.超图书馆员',replace(replace('协调+1只以上协调以外的怪兽\r\n①：此卡在场上存在，自己或对手将此卡以外的同步怪兽同步召唤成功的情况下发动。此卡在场上以表侧表示存在的情况下，自己从牌组抽1张。','\r',char(13)),'\n',char(10)),'抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90957527,'剑斗兽盖奥鲁迪亚斯',replace(replace('“剑斗兽斯巴达克思”＋冠有“剑斗兽”之名的怪兽\r\n仅限将我方场上的上述卡牌返回至牌组的场合，可从额外牌组特殊召唤（不需要“融合”）。此卡因战斗破坏怪兽并送入墓地时，给予对手生命相当于被破坏怪兽的原本守备力数值的伤害。此卡进行战斗的战斗阶段结束时，可将此卡返回至持有者的额外牌组并发动。从牌组特殊召唤２只除“剑斗兽斯巴达克思”以外的冠有“剑斗兽”之名的怪兽。','\r',char(13)),'\n',char(10)),'伤害','特殊召唤','请选择一只「剑斗兽斯巴达克思」','请选择一只名字带有「剑斗兽」的怪兽','','','','','','','','','','','','');
INSERT INTO texts VALUES(90960358,'卡通黑魔导女孩',replace(replace('此卡不可通常召唤。\r\n自己场上存在“卡通世界”的状态下，解放自己场上的1只怪兽的情况下可以特殊召唤。\r\n①：此卡的攻击力，上升双方墓地的“黑魔导”、“黑混沌之魔导”数量×300的数值。\r\n②：此卡在对手场上不存在卡通怪兽的情况下可直接攻击。存在的情况下，仅可选择卡通怪兽为攻击对象。\r\n③：场上的“卡通世界”被破坏时，此卡将被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90960359,'卡通黑魔导女孩',replace(replace('此卡不可通常召唤。\r\n自己场上存在“卡通世界”的状态下，解放自己场上的1只怪兽的情况下可以特殊召唤。\r\n①：此卡的攻击力，上升双方墓地的“黑魔导”、“黑混沌之魔导”数量×300的数值。\r\n②：此卡在对手场上不存在卡通怪兽的情况下可直接攻击。存在的情况下，仅可选择卡通怪兽为攻击对象。\r\n③：场上的“卡通世界”被破坏时，此卡将被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90963488,'睡眠之子','虽身为小孩却能操控梦魔令人陷入沉睡永远不再醒来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90965652,'二量合成',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：可从以下效果中选择１个发动。\r\n●从牌组将１张“化合电界”加入手牌。\r\n●从牌组将１张“完全燃烧”和１只“化合兽”怪兽加入手牌。\r\n②：将墓地的此卡除外，以包含被再１次召唤状态的二重怪兽在内的、自己场上的２只表侧表示怪兽为对象可以发动。直至回合结束时为止，将１只对象怪兽的攻击力改成０，依其原本攻击力的数值使另１只怪兽的攻击力上升。','\r',char(13)),'\n',char(10)),'选择效果发动','「化合电界」加入手牌','「完全燃烧」和「化合兽」怪兽加入手牌','改变攻守','请选择要把攻击力变成0的怪兽','','','','','','','','','','','');
INSERT INTO texts VALUES(90969892,'部落冲锋','此卡名的卡１回合仅可发动１张。①：自己场上怪兽的种族为３种以上的情况下可以发动。从牌组挑选３只种族与自己场上怪兽相同的怪兽（相同种族最多１只）。对手从其中随机挑选１只，自己将该怪兽加入手牌或特殊召唤。剩余的怪兽以喜欢的顺序放回牌组下面。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(90980792,'黑暗胶体人','此卡名在规则上也视为“机人”卡。成功召唤・反转召唤・特殊召唤此卡时，选择场上１只表侧表示的怪兽。只要该怪兽以表侧表示存在于场上，攻击力下降８００点。','攻击下降','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91002901,'决斗进化－爆裂领域',replace(replace('此卡名的卡1回合仅可发动1张，此卡名的③效果1回合仅可使用1次。\r\n①：作为此卡发动时的效果处理，可从自己牌组・墓地将1只记载有“爆裂模式”卡名的怪兽加入手牌。\r\n②：“／爆裂”怪兽在被特殊召唤的回合不会因战斗及对手的效果被破坏。\r\n③：支付2000LP可以发动。此回合仅1次，自己为发动“爆裂模式”解放的同步怪兽也可从额外牌组挑选。','\r',char(13)),'\n',char(10)),'发动','额外解放','是否检索怪兽？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91011603,'极星工 力矮人',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己场上有“极神”怪兽或“极星”怪兽存在的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：此卡召唤・特殊召唤成功的情况下可以发动。从牌组将１张“极星宝”卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91019775,'废铁车库',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：自己场上表侧表示的机械族怪兽因战斗・效果被破坏的情况下，以自己墓地最多3只机械族・暗属性怪兽为对象可以发动。将该怪兽特殊召唤。以此效果特殊召唤的怪兽的攻击力・守备力变为0。\r\n②：将墓地的此卡除外，以自己场上的1只机械族怪兽为对象可以发动。将该怪兽破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91020571,'地征龙－沉积',replace(replace('此卡名的效果１回合仅可使用１次。\r\n①：从手牌将１只龙族或地属性的怪兽与此卡舍弃可以发动。从牌组将１只“岩征龙－石壑”特殊召唤。以此效果特殊召唤的怪兽在此回合不可攻击。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91025875,'K9－ØØ号 天狼',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：在对手发动过手牌・墓地的怪兽的效果的、自己・对手回合的主要阶段可以发动。从手牌・墓地将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下将被除外。\r\n②：在对手回合可以发动。将包含此卡在内的自己场上的怪兽作为素材进行超量召唤。\r\n③：持有此卡作为超量素材的超量怪兽获得以下效果。\r\n●对手不可将此卡作为效果的对象。','\r',char(13)),'\n',char(10)),'特殊召唤','超量召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91027843,'海晶少女之斗海',replace(replace('①：自己场上的“海晶少女”怪兽的攻击力上升２００，进而再上升相当于装备的“海晶少女”卡的数量×６００的数值。\r\n②：以“海晶少女 水晶心”作为素材连接召唤的、额外怪兽区域的自己的怪兽不受对手的效果影响。\r\n③：自己将“海晶少女”连接怪兽连接召唤至额外怪兽区域时可以发动。从自己的墓地挑选最多３只“海晶少女”连接怪兽，视为装备魔法卡装备于该连接召唤的怪兽（同名卡最多１张）。','\r',char(13)),'\n',char(10)),'「海晶少女 水晶心」为素材作连接召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91034681,'魔玩具・冒失鬼',replace(replace('“锋利小鬼”怪兽＋“绒毛动物”怪兽\r\n“魔玩具・冒失鬼”的②效果１回合仅可使用１次。\r\n①：此卡战斗破坏对手怪兽时可以发动。给予对手１０００点伤害。\r\n②：表侧表示的此卡由于对手的效果从场上离开的情况下，或因战斗被破坏的情况下可以发动。给予对手自己墓地中“魔玩具”怪兽的数量×５００点伤害。','\r',char(13)),'\n',char(10)),'给与对手1000伤害','给与对手「魔玩具」怪兽数量×500伤害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91070115,'外星人心电感应','１回合１次，可移除对手场上的１个A计数物并发动。选择场上的１张魔法、陷阱卡破坏。只要此卡以表侧表示存在于场上，仅限在放置有A计数物的怪兽与冠有“外星人”之名的怪兽进行战斗的伤害计算时，攻击力、守备力下降该A计数器数量×３００点。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91073013,'对击斗魂 龙帝瓦里乌斯',replace(replace('此卡名的①②效果１回合仅可各使用１次，不可在同一连锁上发动。\r\n①：在自己・对手的主要阶段，以自己场上的龙族以外的１只“对击斗魂”怪兽为对象可以发动。将该怪兽放回手牌，从手牌将此卡特殊召唤。\r\n②：在自己・对手回合中，从以下选择１个，将手牌相应属性的怪兽各１只出示给对手可以发动。\r\n●地：此回合，表侧表示的此卡不受对手发动的效果影响。\r\n●地・炎・暗：将场上的１张其他的卡破坏。','\r',char(13)),'\n',char(10)),'此卡从手牌特殊召唤','展示地属性的怪兽','展示地·炎·暗属性的怪兽','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91073014,'对击斗魂 龙帝瓦里乌斯',replace(replace('此卡名的①②效果１回合仅可各使用１次，不可在同一连锁上发动。\r\n①：在自己・对手的主要阶段，以自己场上的龙族以外的１只“对击斗魂”怪兽为对象可以发动。将该怪兽放回手牌，从手牌将此卡特殊召唤。\r\n②：在自己・对手回合中，从以下选择１个，将手牌相应属性的怪兽各１只出示给对手可以发动。\r\n●地：此回合，表侧表示的此卡不受对手发动的效果影响。\r\n●地・炎・暗：将场上的１张其他的卡破坏。','\r',char(13)),'\n',char(10)),'此卡从手牌特殊召唤','展示地属性的怪兽','展示地·炎·暗属性的怪兽','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91078716,'花粉症',replace(replace('①：解放自己场上的1只植物族怪兽，可以发动以下效果。\r\n●魔法・陷阱卡发动时可以发动。将该发动无效并破坏。\r\n●自己或对手召唤・特殊召唤怪兽之际可以发动。将其无效，将该怪兽破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91098230,'古代机械齿轮战车兵',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从手牌将“古代机械齿轮战车兵”以外的１只“古代机械齿轮”怪兽无视召唤条件特殊召唤。对手场上存在怪兽的情况下，作为代替也可从自己的墓地挑选。\r\n②：以自己场上的１张表侧表示卡为对象可以发动。将该卡破坏。此回合中，自己场上的“古代机械齿轮巨人”及记载有该卡名的怪兽的攻击力上升６００。','\r',char(13)),'\n',char(10)),'特殊召唤','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91107093,'电磁盾','自己的守备表示的等级３以下的雷族怪兽不会因战斗被破坏。自己场上有表侧攻击表示怪兽存在的情况下，此卡被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91110378,'辉天使 宝座',replace(replace('以此卡作为超量召唤素材的场合，只可使用于将３只或以上的怪兽作为素材的超量召唤。\r\n①：我方成功召唤、特殊召唤“辉天使”怪兽的场合可发动。从手牌特殊召唤此卡，并我方从牌组抽取１张卡牌。该抽取的卡牌是“辉天使”怪兽的场合，可特殊召唤该怪兽。','\r',char(13)),'\n',char(10)),'特殊召唤','是否要把抽到的怪兽特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91123920,'力量之代行者 玛尔斯','此卡不受魔法卡效果的影响。“天空的圣域”以表侧表示存在于我方场上，且我方的LP高于对手的场合，此卡的攻击力和守备力上升与LP超出部分相同的数值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91133740,'雪人吞噬者','此卡反转时，选择１只场上以表侧表示存在的怪兽破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91135480,'时潜怪盗・双盒芯',replace(replace('等级4怪兽×2\r\n此卡名的效果1回合仅可使用1次。①：对手发动效果时可以发动。去除此卡的最多3种超量素材（怪兽・魔法・陷阱）。然后根据去除素材适用以下内容。\r\n●怪兽：此卡的攻击力上升400。\r\n●魔法：挑选对手场上的1只表侧表示怪兽，直至结束阶段为止获得其控制权。此回合，该怪兽不可攻击宣言，不可发动效果。\r\n●陷阱：挑选场上的1只效果怪兽，其效果直至回合结束时为止无效。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91140491,'炽天蝶',replace(replace('卡名不同的怪兽2只以上\r\n此卡名的①③效果1回合1次，仅可使用其中1个。①：此卡连接召唤成功的情况下发动。在此卡上放计数物，数量为作为此卡连接素材的昆虫族怪兽数量。②：此卡的攻击力上升相当于此卡计数物数量×200的数值。③：去除此卡的1个计数物可以发动。从自己的墓地挑选1只等级4以下的昆虫族怪兽以守备表示特殊召唤。此效果在对手回合中也可以发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91148083,'诸神的黄昏','可选择我方场上１只冠有“极神”之名的怪兽并发动。将被选择怪兽的控制权转移给对手。下一个对手结束阶段时，破坏被选择怪兽，并将所有对手场上的卡牌从游戏中除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91152256,'精灵剑士','学会剑术的精灵。以快速的攻击作弄敌人。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91152257,'精灵剑士','学会剑术的精灵。以快速的攻击作弄敌人。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91152258,'精灵剑士','学会剑术的精灵。以快速的攻击作弄敌人。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91152455,'钢铁化・钢炎装甲',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：解放1只记载有“钢铁化・强化反射装甲”卡名的、自己场上的表侧表示怪兽可以发动此卡。从牌组将1只记载有“钢铁化・强化反射装甲”卡名的、不可通常召唤的怪兽无视召唤条件特殊召唤。然后，可将此卡视为拥有以下效果的装备卡，装备于该怪兽。\r\n●装备怪兽将被战斗・效果破坏的情况下，作为代替可将此卡送至墓地。','\r',char(13)),'\n',char(10)),'发动','是否装备？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91182675,'魔导兽 胡狼',replace(replace('←4 【灵摆】 4→\r\n此卡名的灵摆效果1回合仅可使用1次。\n①：自己另一方的灵摆区域不存在卡的情况下，以自己场上的1张能放魔力计数物的卡为对象可以发动。将此卡破坏，在对象卡上放1个魔力计数物。\r\n【怪兽效果】\r\n①：只要此卡存在于怪兽区域，每当自己或对手发动魔法卡，就在此卡上放1个魔力计数物。\n②：去除自己场上的3个魔力计数物，解放此卡可以发动。从牌组将“魔导兽 胡狼”以外的1只“魔导兽”效果怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','请选择要放置魔力计数物的卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91188343,'神秘之代行者 娅丝','①：此卡召唤时可以发动。从牌组将“神秘之代行者 娅丝”以外的1只“代行者”怪兽加入手牌。场上存在“天空的圣域”的情况下，可将加入手牌的怪兽改成1只“主宰者・许珀里翁”。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91215724,'废品装甲',replace(replace('此卡名的①③效果1回合仅可各使用1次。\r\n①：用抽牌以外的方法将此卡加入手牌的情况下可以发动。将此卡特殊召唤。\r\n②：只要此卡存在于怪兽区域，对手不可将原本卡名包含“战士”或“星尘”的、自己场上的同步怪兽作为效果的对象。\r\n③：解放此卡可以发动。从牌组将“废品装甲”以外的1只“废品”怪兽或“同步士”怪兽以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91222209,'救援王牌 水炮灭火者','此卡名的①②效果１回合仅可各使用１次。①：此卡召唤・特殊召唤成功的情况下可以发动。从牌组将１张“救援王牌”陷阱卡加入手牌。②：对手发动场上的怪兽的效果时，解放手牌・场上的此卡，以自己墓地的１只“救援王牌 水炮灭火者”以外的“救援王牌”怪兽为对象可以发动。将该怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91228233,'迷花之森','①：装备了“星空蝶”的自己的怪兽不受对手发动的效果影响。②：1回合1次，自己的“勇者衍生物”战斗破坏怪兽时可以发动。自己从牌组抽1张。③：在发动此卡的②效果的回合的自己的主要阶段可以发动1次。从自己的牌组・墓地挑选“迷花之森”以外的1张记载有“勇者衍生物”的衍生物名的场地魔法卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91231901,'「A」细胞重组装置',replace(replace('①：可以场上的１只表侧表示怪兽为对象发动。从牌组将１只“外星人”怪兽送入墓地，并在对象怪兽放置A计数物，其数量相当于送入墓地的怪兽等级数量。\r\n②：可在我方主要阶段将墓地的此卡除外并发动。从牌组将１只“外星人”怪兽加入手牌。此效果不可在此卡被送入墓地的回合发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91237821,'小丑戏帮 德比鲁兹',replace(replace('等级3怪兽×2\r\n①：自己场上上级召唤的怪兽的攻击力上升1000。\r\n②：此卡被解放的情况下，可从以下效果中选择1个发动（此卡名的以下效果1回合仅可各选择1次）。\r\n●将双方场上・墓地的超量怪兽全部放回额外牌组。\r\n●从牌组将1张“小丑戏帮”魔法卡放置在自己场上。','\r',char(13)),'\n',char(10)),'选择效果','回收超量怪兽','放置魔法卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91250514,'绕舌怪','上级召唤的此卡从场上被送入墓地时，从我方牌组抽取２张卡牌。发动此效果的场合，将此卡从游戏中除外。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91258852,'秘旋谍－高雅',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：１回合１次，在自己的主要阶段可以发动。从牌组将１张“秘旋谍任务”卡加入手牌。\r\n②：此卡被从场上送至墓地的情况下可以发动。从牌组将“秘旋谍－高雅”以外的１只“秘旋谍”怪兽和１张“秘旋谍胜地”加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91262474,'星尘幼龙','此卡名的①②效果１回合仅可各使用１次。①：此卡存在于手牌・墓地，自己场上存在等级８以上龙族同步怪兽的情况下可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡离开场上的情况下，将其除外。②：解放此卡可以发动。从自己的手牌・墓地挑选最多２只“星尘幼龙”以外的龙族・光属性・等级１怪兽特殊召唤。以此效果特殊召唤的怪兽效果不可发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91269402,'电子界信标','此卡名的卡1回合仅可发动1张。①：因战斗或对手的效果使自己受到伤害的回合可以发动。从牌组将1只等级4以下的电子界族怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91272072,'淘气仙星乐队・苦甜吉他手',replace(replace('“淘气仙星”连接怪兽＋“淘气仙星”怪兽\r\n①：以与此卡连接状态的自己的“淘气仙星”连接怪兽的效果给予对手的伤害变为两倍。②：每次对手因“淘气仙星”怪兽的效果受到伤害发动。此卡的攻击力上升相当于该伤害数值的数值。③：此卡攻击过的回合的结束阶段发动。因此卡的②效果上升的数值变回0。然后，可从自己墓地挑选1只“淘气仙星”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'上升攻击力','攻击力恢复','是否从自己墓地选1只「淘气仙星」怪兽加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91279700,'邪蚀俄菲翁',replace(replace('等级4“邪蚀”怪兽×2\r\n①：只要持有超量素材的此卡存在于怪兽区域，双方不可特殊召唤等级5以上的怪兽。\r\n②：1回合1次，去除此卡的1个超量素材可以发动。从牌组将1张“侵略的”魔法・陷阱卡加入手牌。','\r',char(13)),'\n',char(10)),'加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91283212,'蜂军－追击之飞镖',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己的“蜂军”怪兽战斗破坏原本持有者为对手的怪兽时，从手牌将此卡舍弃可以发动。给予对手该怪兽的原本攻击力数值的伤害。\r\n②：以自己场上的１只其他昆虫族怪兽为对象可以发动。此回合，将该怪兽视为协调。此效果发动后，直至回合结束时为止，自己从额外牌组仅可特殊召唤昆虫族怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91284003,'阿尔戈☆群星－飞燕的卡帕涅',replace(replace('①：只要此卡存在于魔法与陷阱区域，自己的战士族怪兽不会因战斗被破坏。\r\n②：1回合1次，怪兽区域存在永续陷阱卡的情况下可以发动。此卡变为拥有以下效果的效果怪兽（战士族・光・星4・攻/守1800），特殊召唤至怪兽区域（也视为陷阱卡）。有自己的“阿尔戈☆群星”怪兽被除外的情况下，进而自己恢复500LP。\r\n●在每个自己・对手回合中可以发动1次。将此卡以表侧表示放在自己的魔法与陷阱区域。','\r',char(13)),'\n',char(10)),'特殊召唤','表侧表示放置','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91286284,'黄金荣耀－猛然袭来',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：从自己的手牌・墓地将１只“黄金荣耀”怪兽特殊召唤。然后，对手可从自身的手牌・墓地将１只怪兽的效果无效，并特殊召唤至自身的场上。','\r',char(13)),'\n',char(10)),'','是否选怪兽特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91299846,'雷天气姜黄',replace(replace('此卡牌名的①效果１回合只可使用１次。\r\n①：可将我方场上的１张表侧表示的永续魔法、永续陷阱卡送入墓地并发动。从牌组挑选１张“天气”魔法、陷阱卡，并以表侧表示放置在我方的魔法与陷阱区域。\r\n②：场上的此卡为了发动“天气”卡牌效果而被除外的场合，可在下一个回合的准备阶段发动。特殊召唤被除外的此卡。','\r',char(13)),'\n',char(10)),'从牌组放置「天气」魔法·陷阱卡','除外的此卡特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91300233,'骑甲虫 残酷撒旦',replace(replace('“骑甲虫”怪兽＋昆虫族怪兽\r\n此卡名的①③效果１回合仅可各使用１次。\r\n①：此卡特殊召唤的情况下可以发动。从牌组将１张“骑甲虫”卡加入手牌。\r\n②：只要此卡存在于怪兽区域，自己仅可特殊召唤昆虫族怪兽。\r\n③：昆虫族怪兽以表侧被除外的情况下，以自己除外状态的１只“骑甲虫”怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91323605,'奇异界开',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：自己场上的怪兽因对手的攻击・效果被破坏的情况下可以发动。从牌组将１张场地区域不存在同名卡的场地魔法卡以表侧表示放在自己的场地区域。然后，从牌组将５只卡名不同的怪兽出示给对手，对手从其中随机挑选１只。将该１只怪兽特殊召唤至自己场上，剩余的放回牌组。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91336701,'魔导耀士 破晓者',replace(replace('魔法师族怪兽2只\r\n此卡名的②④效果1回合仅可各使用1次。\r\n①：此卡连接召唤的情况下发动。在此卡上放1个魔力计数物。\r\n②：有魔法师族怪兽被特殊召唤至此卡连接端的情况下发动。在此卡上放1个魔力计数物。\r\n③：此卡的攻击力上升此卡魔力计数物的数量×300的数值。\r\n④：去除此卡的2个魔力计数物，以场上的1张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91345518,'裁决之代行者 萨图恩','①：解放此卡可以发动。自己的LP比对手多的情况下，给予对手该差值的伤害。当自己场上有“天空的圣域”存在的情况下，此效果可以发动和处理。发动此效果的回合中，自己无法进行战斗阶段。','给与对手基本分差值的伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91349449,'光芒术师','此卡不可通常召唤。仅限从游戏中被除外的我方光属性怪兽是３只或以上的场合可特殊召唤。１回合１次，可选择１只从游戏中被除外的我方光属性怪兽并返回至牌组，选择场上的１只表侧表示怪兽从游戏中除外。发动此效果的回合，此卡不可进行攻击。','除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91350799,'魔幻甜点・松饼咕咕',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：以自己墓地的１只怪兽为对象可以发动。将该怪兽除外，从牌组将“魔幻甜点・松饼咕咕”以外的１只“魔幻甜点”怪兽特殊召唤。\r\n②：此卡被对手破坏并被送至墓地的情况下发动。将此卡放回牌组。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91351370,'黑旋风','①：“黑羽”怪兽被召唤至自己场上时可以发动。从牌组将1只攻击力低于该怪兽的“黑羽”怪兽加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91392974,'出幻','此卡名的卡１回合仅可发动１张。①：自己场上表侧表示的“－英雄”怪兽因战斗・效果被破坏的情况下可以发动。从牌组将１只等级４以下的“幻影－英雄”怪兽特殊召唤。然后可挑选对手场上的１只怪兽，将其原本的攻击力・守备力改成一半。','特殊召唤','是否选怪兽攻击力·守备力减半？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91397409,'企鹅勇者',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的①③效果1回合仅可各使用1次。\r\n①：此卡同步召唤的情况下可以发动。从牌组将1只“企鹅”怪兽以里侧守备表示特殊召唤。\r\n②：只要此卡存在于怪兽区域，对手不可将自己场上的里侧守备表示怪兽作为效果的对象。\r\n③：对手发动怪兽的效果时可以发动。将自己场上的1只里侧守备表示的水属性怪兽改成表侧守备表示。','\r',char(13)),'\n',char(10)),'特殊召唤','变成表侧','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91405870,'烈风的空牙团','这个卡名的卡1个回合只可发动1张。①：可以自己墓地的1只“空牙团”怪兽为对象发动。以守备表示形式特殊召唤该怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91407982,'命运显示',replace(replace('此卡牌名的卡牌１回合只可发动１张。\r\n①：作为此卡发动时的效果处理，可从牌组将１张“命运女郎”卡牌加入手牌。\r\n②：１回合１次，我方场上的卡牌因效果被除外的场合可发动。此回合，我方场上的怪兽不会因效果被破坏。\r\n③：１回合１次，对手场上的卡牌因效果被除外的场合可发动。此回合，我方受到的战斗伤害仅１次会变成０。','\r',char(13)),'\n',char(10)),'是否从牌组把1张「命运女郎」卡加入手牌？','自己场上的怪兽不会被效果破坏','自己受到的战斗伤害只有1次变成0','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91420202,'降诞疾仇尸者・救世主',replace(replace('不死族怪兽２只\r\n此卡名的②③效果１回合仅可各使用１次。①：只要此卡存在于怪兽区域，卡名视为“复仇尸者・屠戮者”。②：以自己墓地的１张“仇尸”卡为对象可以发动。将该卡加入手牌。③：此卡与对手怪兽进行战斗的伤害计算时，从牌组将１只不死族怪兽送至墓地可以发动。该对手怪兽的攻击力直至回合结束时为止，下降相当于送至墓地的怪兽等级×２００的数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91420254,'妖仙兽 右镰神柱',replace(replace('←5 【灵摆】 5→\r\n①：１回合１次，如果我方的另一个灵摆区中有“妖仙兽”卡，则可发动。此卡的灵摆刻度变为１１，直到回合结束。发动此效果后，直到回合结束，我方不能特殊召唤非“妖仙兽”的怪兽。\r\n【怪兽效果】\r\n①：如果成功召唤了此卡，则发动。将此卡变为守备状态。\n②：只要此卡在怪兽区，对手就不能选择其他“妖仙兽”怪兽为攻击目标。','\r',char(13)),'\n',char(10)),'刻度变换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91422370,'螺旋式上弦','可以解放我方场上攻击力１５００以上的具“发条”之名的怪兽以发动。从手牌中特殊召唤１只具“发条”之名的怪兽。然后，可以从卡组中特殊召唤１只攻击力与该怪兽相同，且具“发条”之名的怪兽。','是否要从牌组特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91434208,'白之轮回',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：作为此卡发动时的效果处理，从牌组将１只拥有把自身视为协调的效果的鱼族怪兽加入手牌。\r\n②：１回合１次，自己的“白斗气”怪兽攻击了的伤害步骤结束时可以发动。该攻击怪兽可继续再攻击仅１次。\r\n③：１回合１次，等级８以上的鱼族同步怪兽被从自己的墓地特殊召唤的情况下可以发动（伤害步骤也可以发动）。将对手场上的怪兽全部破坏。','\r',char(13)),'\n',char(10)),'','怪兽破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91434602,'至尊者・许珀里翁',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次。\r\n①：此卡可通过将自己手牌・场上（表侧表示）・墓地的1只“代行者”怪兽除外来从手牌・墓地特殊召唤。\r\n②：因自己的天使族怪兽的战斗对自己造成的战斗伤害对手也要承受。\r\n③：1回合1次，从自己手牌・墓地将1只天使族怪兽除外，以自己或对手墓地的1张卡为对象可以发动（自己或对手的、场上或墓地存在“天空的圣域”的情况下，此效果1回合可使用最多2次）。将该卡除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91438674,'阿尔戈☆群星－荣冠的阿德拉',replace(replace('此卡名的③效果1回合仅可使用1次。\r\n①：在对手回合中，自己场上存在永续陷阱卡的情况下，从手牌将此卡除外可以发动。将场上的1只怪兽的攻击力直至回合结束时为止改成0。\r\n②：此卡召唤的情况下发动。此回合，应对自己的永续陷阱卡的效果的发动，对手不可发动效果。\r\n③：将场上的此卡除外可以发动。从手牌・牌组将最多2张“阿尔戈☆群星”永续陷阱卡以表侧表示放在自己的魔法与陷阱区域（同名卡最多1张）。','\r',char(13)),'\n',char(10)),'攻击力变为0','不可对应发动','表侧表示放置','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91438994,'A次代机・浴焰',replace(replace('①：每次怪兽被从自己场上送至墓地，在此卡上放１个次代机计数物。\r\n②：每次卡被从对手的墓地除外，在此卡上放２个次代机计数物。\r\n③：此卡的攻击力上升相当于场上次代机计数物的数量×１００的数值。\r\n④：此卡因战斗被破坏并被送至墓地的情况下发动。给予对手相当于此卡上所放次代机计数物的数量×３００的伤害。','\r',char(13)),'\n',char(10)),'伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91444835,'依艮鬼之咒咆',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：可从以下效果中选择1个发动。\r\n●此卡变为通常怪兽（魔法师族・协调・暗・星1・攻/守0），特殊召唤至怪兽区域（不视为陷阱卡）。然后，可进行1只同步怪兽的同步召唤。\r\n●自己场上或墓地存在“艮鬼”怪兽的情况下，以对手场上的1只怪兽为对象可以发动。将该怪兽破坏。','\r',char(13)),'\n',char(10)),'发动','当作怪兽特殊召唤','破坏效果','是否同步召唤？','','','','','','','','','','','','');
INSERT INTO texts VALUES(91449144,'薰风之寂静 卡姆','１回合１次，可将我方墓地的２只冠有“薰风”之名的怪兽返回至牌组并发动。从牌组抽取１张卡牌。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91449532,'娱乐伙伴掩护河马',replace(replace('①：此卡召唤成功时可发动。从手牌特殊召唤１只“娱乐伙伴”怪兽。直至回合结束时，以此效果特殊召唤而来怪兽的效果被无效化。\r\n②：１回合１次，在我方主要阶段可发动。将我方场上的所有怪兽变成守备表示。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91468551,'太阳的祭坛','只要此卡存在于场上，从墓地特殊召唤至我方场上的怪兽的攻击力上升３００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91479482,'红恋之丽杰－布拉达曼特',replace(replace('此卡名在规则上也视为“焰圣骑士”卡。\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：从手牌将此卡舍弃，以自己场上的１只战士族怪兽为对象可以发动。从牌组挑选１张该怪兽可装备的装备魔法卡，装备于该怪兽。\r\n②：未装备装备卡的此卡因与对手怪兽的战斗被破坏并被送至墓地时可以发动。将此卡特殊召唤，将该对手场上的怪兽视为装备魔法卡装备于此卡。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91482773,'网关龙','此卡名以①方法的特殊召唤1回合仅可进行1次。①：对手场上有连接怪兽存在的情况下，此卡可从手牌中特殊召唤。②：1回合1次，在自己的主要阶段可以发动。从手牌将1只等级4以下龙族・暗属性怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91499077,'我我我武士',replace(replace('等级４怪兽×２\r\n①：１回合１次，去除此卡的１个超量素材，以自己场上的１只“我我我”怪兽为对象可以发动。此回合，该怪兽在１次战斗阶段中可攻击２次。②：此卡以外的自己的怪兽被选择为攻击对象时可以发动。将此卡改成表侧守备表示，攻击对象移换为此卡并进行伤害计算。','\r',char(13)),'\n',char(10)),'2次攻击','对象变更','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91500017,'卡通书签',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从牌组将除“卡通书签”以外的、1张“卡通世界”或记载有该卡名的卡加入手牌。\r\n②：自己场上的“卡通世界”将被效果破坏的情况下，作为代替可将墓地的此卡除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91501248,'禁忌之壶',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：此卡反转的情况下，可从以下效果中选择1个发动。\r\n●自己抽2张。\r\n●将场上的魔法・陷阱卡全部放回手牌。\r\n●将对手场上的怪兽全部破坏。\r\n●确认对手的手牌，挑选其中1张放回牌组。','\r',char(13)),'\n',char(10)),'自己抽2张','场上的魔法·陷阱卡全部回到手牌','对手场上的怪兽全部破坏','把对手手牌确认，选那之内的1张回到牌组','','','','','','','','','','','','');
INSERT INTO texts VALUES(91505214,'淘气仙星・娜尔姬丝','此卡名的①效果1回合仅可使用1次。①：对手受到效果伤害的情况下可以发动。从手牌将此卡特殊召唤。②：只要此卡存在于怪兽区域，对手每次发动手牌・墓地的怪兽效果，给予对手200伤害。','此卡从手牌特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91509824,'-艾-并肩伙伴',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：依自己场上原本攻击力为2300的电子界族怪兽的数量，以对手场上的表侧表示卡为对象可以发动。将该卡的效果直至回合结束时为止无效。\r\n②：将墓地的此卡除外，以自己除外状态的1只电子界族怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'效果无效','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91512835,'昆虫女王',replace(replace('①：此卡的攻击力上升场上昆虫族怪兽的数量×２００。\r\n②：此卡进行攻击宣言时，必须解放１只我方场上的其他怪兽。\r\n③：若此卡通过战斗破坏对手怪兽，在该回合的结束阶段时发动此卡。将１只“昆虫怪兽衍生物”（昆虫族・地・１星・攻／守１００）以攻击表示特殊召唤至我方场上。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91512836,'昆虫怪兽衍生物','由“昆虫女王”等的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91530236,'精灵术的操控者',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：舍弃1张手牌可以发动。从牌组挑选“灵使”怪兽、“凭依装着”怪兽、“凭依”魔法・陷阱卡中的2张（同名卡最多1张）。将其中1张加入手牌，另1张放置在自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91530237,'精灵术的操控者',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：舍弃1张手牌可以发动。从牌组挑选“灵使”怪兽、“凭依装着”怪兽、“凭依”魔法・陷阱卡中的2张（同名卡最多1张）。将其中1张加入手牌，另1张放置在自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91534476,'一接一',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：从自己的手牌・场上将１只怪兽送至墓地，从自己墓地的怪兽及自己被除外的怪兽中，以送至墓地的怪兽以外的１只等级１怪兽为对象可以发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91554542,'新炎狱剑士','对手墓地的卡牌为４张或以下的场合，此卡的攻击力上升６００点。对手墓地的卡牌为８张或以上的场合，此卡的攻击力下降３００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91557476,'圣蔓之剑士',replace(replace('植物族通常怪兽１只\r\n①：自己场上的“圣天树”连接怪兽因效果从场上离开的情况下发动。将此卡破坏。\r\n②：此卡特殊召唤的情况下，以场上的１只“圣天树”连接怪兽为对象可以发动。此卡的攻击力上升相当于其连接标记数量×８００的数值。\r\n③：此卡战斗破坏对手怪兽并将其送至墓地时可以发动。将该怪兽的效果无效并特殊召唤至连接怪兽连接端的自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91559748,'棘之妖精','只要此卡以表侧表示存在于场上，对手怪兽不可攻击昆虫族怪兽。与此卡进行战斗的怪兽，在伤害步骤结束时变成守备表示。','变成守备表示','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91575236,'不朽之龙',replace(replace('协调＋１只以上协调以外的怪兽\r\n此卡名的①②效果１回合仅可各使用１次。①：在自己的主要阶段可以发动。从牌组将１只不死族怪兽送至墓地，将此卡的等级改成该怪兽与此卡原本等级之差的数值。②：此卡存在于墓地的状态下，自己的不死族怪兽因战斗被破坏时可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91580102,'爬虫妖之怒','装备怪兽变成爬虫类族，攻击力上升８００点。此外，此卡被破坏并送入墓地时，选择对手场上１只表侧表示怪兽，并将该攻击力下降８００点。','攻击下降','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91584698,'娱乐伙伴扑克魔女',replace(replace('←4 【灵摆】 4→\r\n①：１回合１次，在我方主要阶段可发动。从我方场上将由融合怪兽卡规定之融合素材怪兽送入墓地，从额外牌组融合召唤１只该融合怪兽。\r\n【怪兽效果】\r\n①：可解放此卡并发动。从我方牌组・墓地挑选１张“融合”加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91588074,'创星神 提耶拉',replace(replace('此卡不可通常召唤。\r\n仅可在将自己手牌・场上此卡以外的１０种卡放回持有者的牌组・额外牌组的情况下特殊召唤。\r\n①：此卡的特殊召唤不会被无效化。\r\n②：此卡特殊召唤成功的情况下发动。将双方手牌・场上・墓地此卡以外的卡及额外牌组的表侧表示灵摆怪兽全部放回持有者的牌组。应对此效果的发动，不可发动魔法・陷阱・怪兽的效果。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91592030,'威逼矿石－迫选召唤石',replace(replace('①：以自己墓地的３只怪兽为对象可以发动。自己从该３只中挑选１只。然后，对手从以下效果中挑选１个，自己适用该效果。\r\n●将所挑选怪兽特殊召唤。\r\n●尽可能多地将所挑选怪兽以外的对象怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'选的怪兽特殊召唤','选的怪兽以外的作为对象的怪兽尽可能特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91595718,'秘术之书','仅限装备魔法师族怪兽。令装备怪兽的攻击力和守备力上升３００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91596726,'黑暗十字军','可从手牌将１只暗属性怪兽送入墓地并发动。此卡的攻击力上升４００点。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91597389,'骑乘！','选择我方墓地中的１只联合怪兽，将其装备至我方场上可装备的怪兽上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91598270,'索音服和弦・格蕾西娅',replace(replace('←4 【灵摆】 4→\r\n①：自己的“音服和弦”灵摆怪兽灵摆召唤成功时，对手不可发动怪兽的效果・魔法・陷阱卡。\r\n【怪兽效果】\r\n此卡名的①怪兽效果1回合仅可使用1次。\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将1张“音服和弦”魔法・陷阱卡加入手牌。\n②：自己的灵摆区域存在偶数的灵摆刻度，自己的“音服和弦”灵摆怪兽攻击的情况下，直至伤害步骤结束时为止，对手不可发动怪兽效果。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91607976,'变形斗士・钟头人',replace(replace('此卡依据此卡的表示形式获得以下效果。\r\n●攻击表示：此卡的攻击力上升此卡的变形斗士计数物数量×５００点。\r\n●守备表示：１回合１次，可在此卡放１个变形斗士计数物。解放此卡可以发动。给予对手LP放在此卡的变形斗士计数物数量×１０００点伤害。','\r',char(13)),'\n',char(10)),'放置1个变形斗士计数物','对手基本分此卡放置的变形斗士计数物数量×1000的数值的伤害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91623717,'连锁爆击','连锁２之后可以发动。给予对手LP此卡发动时累积连锁数量×４００点伤害。同一连锁上发动多次同名卡效果的情况下，此卡不可以发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91642007,'海造贼－黑翼水先人',replace(replace('具此卡名的①②效果１回合各只能使用１次。\r\n①：以除“海造贼－黑翼水先人”以外我方墓地中１只“海造贼”怪兽为目标可发动。从手牌特殊召唤此卡，并将目标怪兽加入手牌。此回合我方无法特殊召唤“海造贼”以外的怪兽。\r\n②：此卡从手牌／怪兽区送至墓地的情况下，以我方的魔法与陷阱区域中１只“海造贼”怪兽卡为目标可发动。将该卡以守备状态特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91646304,'神树之圣骑联盟','此卡名以①方法的特殊召唤1回合仅可进行1次，且②效果1回合仅可使用1次。①：此卡可从手牌以守备表示特殊召唤至连接怪兽连接端的自己场上。②：自己场上的“圣骑联盟”怪兽将被战斗・效果破坏的情况下，作为代替，可将场上・墓地的此卡除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91650245,'森罗的恩惠','挑选自己的１张手牌，放回持有者牌组最上面或最下面，从自己的手牌・墓地挑选１只“森罗”怪兽特殊召唤。以此效果特殊召唤的怪兽此回合不受其他卡的效果影响，将在结束阶段时返回持有者牌组最上面或最下面。','返回牌组最上面','返回牌组最下面','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91654806,'与宇宙的交信',replace(replace('此卡名的效果①②在1个回合中仅可各使用1次。\r\n①：将原本持有者为对手的自己场上的1只怪兽送至墓地后可以发动。从自己的手牌、墓地选择1只机械族怪兽特殊召唤。\r\n②：自己场上有“人造人-念力震慑者”存在，在对手的抽牌阶段，对手进行了通常抽牌时，对卡的种类（怪兽、魔法、陷阱）进行宣言后可以发动。互相查看抽出的卡，如果是宣言的种类，则将此卡送至墓地，自己从牌组中抽1张卡。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91662792,'薰风・鹰','此卡因战斗被破坏并送入墓地时可发动。从牌组特殊召唤１只除协调以外的等级４或以下冠有“薰风”之名的怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91663373,'电子超能者','只要此卡以表侧攻击表示存在于我方场上，对手抽取卡牌时，可确认该卡。','确认抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91665064,'安全屏蔽','①：以场上的１只电子界族怪兽为对象可以发动。此回合，该怪兽不会因战斗被破坏，双方将受到的所有战斗伤害变为０。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91668078,'初晴寻踪去 踏雪妮儿复留印 来者沿迹循','①：“初晴寻踪去 踏雪妮儿复留印 来者沿迹循”以外的卡被送至墓地的情况下可以发动。将自己墓地的最多５张卡以里侧除外。然后，自己除外状态的里侧的卡存在７张以上的情况下，对手尽可能地挑选自身墓地的卡以里侧除外，最多５张。','除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91668401,'电子天使－伊舍那－','以“机械天使的仪式”降临。①：此卡仪式召唤成功的情况下可以发动。对手必须将自身场上的１张魔法・陷阱卡送至墓地。②：以此卡的攻击破坏对手怪兽并将其送至墓地时可以发动。此卡可继续攻击对手怪兽仅１次。③：１回合１次，以自己场上的“电子天使”仪式怪兽为对象的对手效果发动时可以发动。挑选自己墓地的１只仪式怪兽放回牌组，挑选对手场上的１张卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91677585,'勇往翔前的挑战','①：在自己战斗阶段，以此回合进行过攻击的１只超量怪兽为对象可以发动。此战斗阶段中，该怪兽可再攻击仅１次。该怪兽以此效果攻击的情况下，直至伤害步骤结束时为止，对手不可发动魔法・陷阱・怪兽的效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91691605,'命运－英雄 钻头魔侠','此卡名的①效果1回合仅可使用1次。①：此卡召唤・特殊召唤成功的情况下可以发动。从手牌将1只拥有此卡攻击力以下的攻击力的“命运-英雄”怪兽特殊召唤。②：此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予战斗伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91697229,'极星邪狼芬里尔',replace(replace('此卡不可通常召唤。\r\n在我方主要阶段２，场上存在有“极神”怪兽的场合可从手牌以守备表示特殊召唤至对手场上。\r\n①：场上不存在有“极神”怪兽的场合此卡被破坏。\r\n②：我方战斗阶段开始时发动。将我方场上的所有守备表示怪兽变成表侧攻击表示。\r\n③：此卡因战斗发生的战斗伤害由双方玩家承受。','\r',char(13)),'\n',char(10)),'特殊召唤','表示变更','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91703676,'炎王神天烧',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：以相同数量的、自己场上的“炎王”怪兽和对手场上的卡为对象可以发动。将该卡破坏。\r\n②：自己场上的“炎王”卡将被效果破坏的情况下，作为代替可将墓地的此卡除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91706817,'青泪的天使',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：以场上的１只表侧表示怪兽为对象可以发动。该怪兽的控制者的对手受到相当于自身手牌数量×２００的伤害。然后，对象怪兽的效果直至回合结束时为止无效。\r\n②：自己或对手受到效果伤害的情况下，将墓地的此卡除外可以发动。从手牌・牌组将１张通常陷阱卡放置在自己场上。从手牌放置的情况下，该卡在放置的回合也可以发动。','\r',char(13)),'\n',char(10)),'','通常陷阱卡放置','适用「青泪的天使」的效果来发动','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91711547,'炎狱魔鬼','此卡给予对手LP战斗伤害时，给予对手LP自己的墓地中炎族怪兽数量×２００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91712985,'时械神 卡弥翁',replace(replace('此卡不可从牌组特殊召唤。\r\n①：自己场上不存在怪兽的情况下，此卡无需解放即可召唤。\r\n②：此卡不会因战斗・效果被破坏，因此卡的战斗对自己造成的战斗伤害变为0。\r\n③：此卡进行过战斗的战斗阶段结束时发动（应对此发动，不可发动卡的效果）。将对手场上的1张卡放回牌组，给予对手500伤害。\r\n④：在自己的准备阶段发动。将此卡放回牌组。','\r',char(13)),'\n',char(10)),'不用解放作召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91714772,'银河防卫机器人・奥比塔尔 7',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：解放手牌・场上的此卡可以发动。从牌组挑选1只“光子”怪兽和1只“银河”怪兽，将其中1只加入手牌，另1只送至墓地。此回合，自己仅可特殊召唤光属性怪兽。\r\n②：“银河眼”怪兽被特殊召唤至自己场上的情况下可以发动。从墓地将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'检索效果','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91714773,'银河防卫机器人・奥比塔尔 7',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：解放手牌・场上的此卡可以发动。从牌组挑选1只“光子”怪兽和1只“银河”怪兽，将其中1只加入手牌，另1只送至墓地。此回合，自己仅可特殊召唤光属性怪兽。\r\n②：“银河眼”怪兽被特殊召唤至自己场上的情况下可以发动。从墓地将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'检索效果','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91718579,'隆隆隆左手与右手',replace(replace('①：只要此卡与此卡以外的“隆隆隆”怪兽存在于怪兽区域，对手不可将“隆隆隆”怪兽选择为攻击对象，也不可作为效果的对象。\r\n②：仅以包含此卡在内的“隆隆隆”怪兽作为素材的超量怪兽获得以下效果。\r\n●此超量召唤成功时，以对手场上的１只表侧攻击表示怪兽为对象可以发动。将该怪兽改成守备表示，守备力改成０。','\r',char(13)),'\n',char(10)),'对手场上1只怪兽变成守备表示并把守备力变成0。','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91731841,'宝石骑士・石榴石','蕴藏石榴石的力量，宝石骑士中的战士。其火焰铁拳将粉碎一切敌人。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91740879,'隐居者的大釜',replace(replace('①：作为此卡发动时的效果处理，在此卡上放１个计数物。\r\n②：在自己的准备阶段发动。在此卡上放１个计数物。\r\n③：１回合１次，可从以下效果中选择１个发动。\r\n●自己恢复相当于此卡计数物数量×５００的LP。\r\n●给予对手相当于此卡计数物数量×３００的伤害。','\r',char(13)),'\n',char(10)),'放置计数物','基本分回复','基本分伤害','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91742238,'不死者归来','此卡名的①②效果１回合仅可各使用１次。①：挑选场上的１只不死族怪兽除外。然后，从其控制者的墓地挑选１只不死族怪兽，以守备表示特殊召唤至其持有者的场上。②：此卡存在于墓地的情况下可以发动。挑选被除外的自己的１只不死族怪兽放回牌组，将此卡放置在自己场上。以此效果放置的此卡离开场上的情况下，将其除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91749600,'创王之咒 渥尔娃','此卡名的②③效果１回合仅可各使用１次。①：“创王之咒 渥尔娃”在自己场上仅可有１只以表侧表示存在。②：此卡存在于手牌・墓地的情况下，从手牌将１张其他的“创王”卡送至墓地可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。③：此卡特殊召唤成功的情况下可以发动。从自己的手牌・墓地挑选“创王之咒 渥尔娃”以外的１只“创王”怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91754175,'人犬兽','①：１回合１次，可在此卡与对手怪兽进行战斗伤害计算时发动。从手牌、牌组将１只兽族、兽战士族、鸟兽族怪兽送入墓地，直至战斗阶段结束时，此卡的攻击力上升送入墓地的该怪兽等级×１００点。','是否发动「人犬兽」的效果？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91781484,'DDD猎头','此卡名的卡１回合仅可发动１张。①：自己场上有“DDD”怪兽存在的情况下，以对手场上的１只表侧表示怪兽为对象可以发动。直至下个回合的结束阶段为止，获得该怪兽的控制权。以此效果获得控制权的怪兽的效果无效化，不可攻击宣言。以此效果获得控制权的怪兽是被从额外牌组特殊召唤的怪兽的情况下，该怪兽也视为“DDD”怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91781589,'霸者的横扫','①：在对手的准备阶段可以发动。此回合，对手无法进行战斗阶段。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91782219,'蟹龟','由“龟的誓言”召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91798373,'二重蝎子','成功召唤・特殊召唤此卡时，可从手牌特殊召唤１只等级４以下的二重怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91800273,'次元吸引者','①：在自己・对手回合中，自己的墓地不存在卡的情况下，从手牌将此卡送至墓地可以发动。直至下个回合结束时为止，被送往墓地的卡不去墓地而直接被除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91800274,'次元吸引者','①：在自己・对手回合中，自己的墓地不存在卡的情况下，从手牌将此卡送至墓地可以发动。直至下个回合结束时为止，被送往墓地的卡不去墓地而直接被除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91810826,'天杯龙 红中龙',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己场上存在龙族・炎属性怪兽的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：怪兽进行战斗的伤害步骤开始时可以发动。从牌组将除“天杯龙 红中龙”之外的１只等级４以下的龙族・炎属性怪兽特殊召唤。\r\n③：１回合１次，在自己・对手的战斗阶段可以发动。将包含此卡在内的自己场上的怪兽作为素材进行同步召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','从牌组特殊召唤','同步召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91812341,'蚁狮之虫惑魔',replace(replace('①：此卡召唤时可以发动。从牌组将１张“空洞”通常陷阱卡或“落穴”通常陷阱卡加入手牌。\r\n②：此卡特殊召唤的情况下，以对手场上的１张魔法・陷阱卡为对象发动。将该对手的卡破坏。\r\n③：此卡只要存在于怪兽区域，不受“空洞”通常陷阱卡及“落穴”通常陷阱卡的效果影响。','\r',char(13)),'\n',char(10)),'牌组检索','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91818544,'威咖杯！摩卡',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：以场上的1只里侧守备表示怪兽为对象可以发动。从手牌将此卡特殊召唤，将对象怪兽改成表侧攻击表示。\r\n②：此卡反转的情况下，以场上的1只表侧表示怪兽为对象可以发动。该怪兽的攻击力上升1000，并将在结束阶段被送至墓地。\r\n③：在自己的结束阶段可以发动。将此卡改成里侧守备表示。','\r',char(13)),'\n',char(10)),'特殊召唤','攻击上升','变成里侧守备表示','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91819979,'魔法爆破','给予对手生命我方场上表侧表示魔法师族怪兽的数量×２００点伤害。此卡存在于墓地的场合，可在我方抽牌阶段时放弃进行普通抽牌，将此卡加入到手牌中。','加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91822647,'薰风的旋风','我方场上不存在有怪兽的场合可发动。选择我方墓地的２只冠有“薰风”之名的怪兽并返回至牌组。之后，从牌组特殊召唤１只守备力为１０００或以下的冠有“薰风”之名的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91831066,'水剧台照明',replace(replace('①：我方场上仅可有１张“水剧台照明”以表侧表示存在。\r\n②：我方的“水伶女”怪兽与对手怪兽进行战斗的伤害计算时发动。该我方怪兽的攻击力、守备力仅限于伤害计算时加倍。\r\n③：此卡从场上被送入墓地的场合，可以我方墓地的１只水族怪兽为对象发动。特殊召唤该怪兽。此效果发动后，直至回合结束时，我方只可特殊召唤水属性怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91842653,'卡通恶魔',replace(replace('此卡不可通常召唤。\r\n自己场上存在“卡通世界”的状态下，解放自己场上的1只怪兽的情况下可以特殊召唤。\r\n①：此卡在特殊召唤的回合不可攻击。\r\n②：此卡攻击宣言之际，自己必须支付500LP。\r\n③：此卡在对手场上不存在卡通怪兽的情况下可直接攻击。存在的情况下，仅可选择卡通怪兽为攻击对象。\r\n④：场上的“卡通世界”被破坏时，此卡将被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91862578,'激昂的姆卡姆卡','此卡的攻击力、守备力上升我方手牌数量×４００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91864689,'超元特防队 刃锋','此卡名的①效果１回合仅可使用１次。①：此卡召唤・特殊召唤成功的情况下可以发动。从手牌将“超元特防队 刃锋”以外的１只“超元特防队”怪兽以攻击表示特殊召唤。②：只要此卡存在于怪兽区域，自己的“超元特防队”怪兽正面的对手怪兽不可作为连接３以上的怪兽的连接素材。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91869203,'亚马逊的射手','解放自己场上的２只怪兽给予对手生命１２００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91870448,'念力电子巨人',replace(replace('按此卡名的方法①进行的特殊召唤在1个回合中仅可进行1次，此卡名的效果②在1个回合中仅可使用1次。\r\n①：对手场上的魔法・陷阱卡的数量多于自己场上的魔法・陷阱卡时，可从手牌中特殊召唤此卡。\r\n②：自己场上有“人造人-念力震慑者”存在，此卡对对手的效果怪兽进行了攻击宣言时，解放此卡后可以发动。将该对手怪兽作为永续陷阱卡以表侧表示放在对手的魔法与陷阱区域。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91880660,'九死必有一生路',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：双方玩家在自己的主要阶段可以发动。以对手场上的卡的数量为上限，从自己牌组上面翻开卡，从其中挑选1张加入手牌。然后，将剩余的卡及自己的1张手牌以喜欢的顺序放回牌组下面。\r\n②：以此卡的①效果1次翻开9张以上的玩家在该回合的结束阶段可以发动。将对手场上・墓地的卡全部放回牌组。','\r',char(13)),'\n',char(10)),'加入手牌','回到牌组','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91895091,'银岭的巨神',replace(replace('地属性等级３怪兽×２\r\n１回合１次，可移除此卡的１个超量素材，选择盖牌于对手魔法与陷阱区域的１张卡牌并发动。只要此卡以表侧表示存在于场上，被选择的卡牌不可发动。此外，持有超量素材的此卡因战斗破坏对手怪兽时，可从我方墓地选择１只地属性怪兽并以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'发动限制','特殊召唤','请选择魔法与陷阱卡区域放置的1张卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91903221,'进化虫・埃尔金螈','①：场上的此卡被解放并被送至墓地的情况下发动。自己抽１张。然后，从手牌将１只恐龙族怪兽放回牌组，可从牌组将１只“进化虫”怪兽加入手牌。','抽牌','是否要把1只名字带有「进化虫」的怪兽加入手牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91907707,'机壳档案',replace(replace('←1 【灵摆】 1→\r\n①：我方只可特殊召唤“机壳”怪兽。此效果不会被无效化。\n②：我方场上的“机壳”怪兽攻击力上升３００。\r\n【怪兽效果】\r\n①：此卡可无需释放进行召唤。\n②：以特殊召唤或无需释放召唤而来的此卡之等级变成４，原本攻击力变成１８００。\n③：通常召唤而来的此卡不受原本等级或阶级低于此卡等级之怪兽所发动的效果影响。\n④：此卡被释放的场合，可以场上的１只怪兽为对象发动。将该怪兽返回至持有者的手牌。','\r',char(13)),'\n',char(10)),'不用解放作召唤','回到手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91932350,'神鹰女郎','有着人身并长有翅膀的兽。其舞姿优美华丽，其攻击凌厉无比。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91939608,'神圣人偶','操纵神圣之力的人偶，在黑暗中拥有很强的攻击力。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91946859,'应身的机械天使','此卡名的②效果１回合仅可使用１次。①：只要此卡存在于魔法与陷阱区域，自己的“电子天使”仪式怪兽不会因战斗被破坏。②：自己因战斗或对手的效果受到伤害时，解放自己手牌・场上的１只“电子天使”仪式怪兽可以发动。从手牌将１只“电子天使”仪式怪兽视为仪式召唤特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91949988,'迅雷骑士盖亚龙骑兵',replace(replace('等级7怪兽×2\r\n此卡也可重叠在自己场上阶级5・6的超量怪兽上面来超量召唤。①：此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予战斗伤害。','\r',char(13)),'\n',char(10)),'是否在5·6阶的超量怪兽上面重叠超量召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91951471,'对击斗魂 螺旋流辻风',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：以自己场上的１只“对击斗魂”怪兽为对象可以发动。变更该怪兽的表示形式。然后，可将对手场上的表侧表示怪兽改成里侧守备表示，数量最多为自己场上的“对击斗魂”怪兽的种类数量。','\r',char(13)),'\n',char(10)),'','是否选对手怪兽变成里侧守备表示？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91953000,'海晶少女 蓝彩刺尾',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将“海晶少女 蓝彩刺尾”以外的１只“海晶少女”怪兽送至墓地。\r\n②：此卡作为水属性连接怪兽的连接素材被送至墓地的情况下可以发动。从自己的牌组上面翻开３张卡。可从其中将１张“海晶少女”卡加入手牌。将剩余的卡放回牌组。','\r',char(13)),'\n',char(10)),'','','是否选卡加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91957038,'妖精之传姬',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：将同名怪兽不存在于自己场上的、手牌的1只攻击力1850的魔法师族怪兽出示给对手可以发动。进行该怪兽的通常召唤。\r\n②：自己场上存在原本攻击力为1850的魔法师族怪兽，且自己将受到战斗・效果伤害的情况下，1回合仅1次，该伤害变为0。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91969909,'女神乌尔德的裁决',replace(replace('①：自己场上的“女战神”怪兽不会成为对手效果的对象，不会因对手的效果被破坏。\r\n②：１回合１次，宣言１个卡名，以放置在对手场上的１张卡为对象可以发动。双方确认该被放置的卡，是所宣言的卡的情况下，将该卡除外。不是的情况下，挑选自己场上的１张卡除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91985515,'核成初始化','可释放１只我方场上冠有“核成”之名的怪兽并发动。从我方牌组、墓地挑选１张“核成之钢核”加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91989718,'攻击反射装置','可解放我方场上的１只“电子龙”怪兽并发动。从手牌、牌组特殊召唤１只“电子屏障龙”。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91996584,'鞭尾石像怪','使用鞭子一般长的尾巴，从空中发动攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91998119,'XYZ－龙型加农炮',replace(replace('“X－首领加农”＋“Y－龙首”＋“Z－金属履带”\r\n此卡从额外牌组仅可在将自己场上的上述卡除外的情况下特殊召唤。\r\n此卡不可从墓地特殊召唤。\r\n①：舍弃１张手牌，以对手场上的１张卡为对象可以发动。将该对手的卡破坏。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91998120,'XYZ－龙型加农炮',replace(replace('“X－首领加农”＋“Y－龙首”＋“Z－金属履带”\r\n此卡从额外牌组仅可在将自己场上的上述卡除外的情况下特殊召唤。\r\n此卡不可从墓地特殊召唤。\r\n①：舍弃１张手牌，以对手场上的１张卡为对象可以发动。将该对手的卡破坏。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91998121,'XYZ－龙型加农炮',replace(replace('“X－首领加农”＋“Y－龙首”＋“Z－金属履带”\r\n此卡从额外牌组仅可在将自己场上的上述卡除外的情况下特殊召唤。\r\n此卡不可从墓地特殊召唤。\r\n①：舍弃１张手牌，以对手场上的１张卡为对象可以发动。将该对手的卡破坏。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(91998122,'XYZ－龙型加农炮',replace(replace('“X－首领加农”＋“Y－龙首”＋“Z－金属履带”\r\n此卡从额外牌组仅可在将自己场上的上述卡除外的情况下特殊召唤。\r\n此卡不可从墓地特殊召唤。\r\n①：舍弃１张手牌，以对手场上的１张卡为对象可以发动。将该对手的卡破坏。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92001300,'古代机械齿轮城',replace(replace('①：场上的“古代机械齿轮”怪兽攻击力上升３００。\r\n②：只要此卡存在于魔法与陷阱区域，每次怪兽被通常召唤，放置１个计数物在此卡。\r\n③：我方以表侧表示上级召唤“古代机械齿轮”怪兽的场合，可代替放置有必要解放数量以上计数物的此卡解放并上级召唤。','\r',char(13)),'\n',char(10)),'解放「古代机械齿轮城」进行通常召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92003832,'黄金荣耀－滚球手',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己的LP少于对手的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：在自己・对手的主要阶段可以发动。以自己的手牌・场上的怪兽作为融合素材，将１只“黄金荣耀”融合怪兽融合召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92015800,'编号76 谐调光师 格拉递艾儿',replace(replace('等级7怪兽×2\r\n此卡名的③效果1回合仅可使用1次。\r\n①：此卡的属性也视为此卡持有的超量素材的各怪兽的属性。\r\n②：此卡不会因与拥有此卡相同属性的怪兽的战斗被破坏，也不会因拥有此卡相同属性的对手怪兽发动的效果被破坏。\r\n③：在自己・对手回合中，以对手墓地的1只怪兽为对象可以发动。去除此卡的1个超量素材，将对象怪兽作为此卡的超量素材。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92034192,'超级量子士 黑层',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：对手发动怪兽的效果时可以发动。从自己手牌挑选1张其他的卡舍弃，从手牌将此卡特殊召唤。\r\n②：此卡特殊召唤的情况下可以发动。从额外牌组将1只“超级量子机兽”超量怪兽重叠在自己场上的此卡上面，视为超量召唤特殊召唤，从自己墓地将1只“超级量子”怪兽作为其超量素材。\r\n③：此卡被送至墓地的情况下可以发动。从牌组将1张“超级量子”魔法卡加入手牌。','\r',char(13)),'\n',char(10)),'此卡特殊召唤','超量召唤','检索','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92035412,'大日神械元素','我方场上表侧表示的冠有“大日神械”之名的装备卡被破坏时，可从牌组中特殊召唤最多被破坏卡牌数量的冠有“大日神械”之名的协调。将以此效果特殊召唤的怪兽作为同步素材的场合，仅可使用于冠有“大日神械”之名怪兽的同步召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92039899,'恶魔的骑兵','①：场上的此卡因效果被破坏并被送至墓地的情况下，以“恶魔的骑兵”以外的、自己墓地的1只“恶魔”怪兽为对象可以发动。将该怪兽特殊召唤。以此效果特殊召唤的怪兽在此回合不可攻击。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92043888,'音服和弦・端庄',replace(replace('此卡名的卡1回合仅可发动1张。①：自己的灵摆区域有“音服和弦”卡存在，对手发动怪兽的效果・魔法・陷阱卡时可以发动。从自己的额外牌组将1只表侧表示的灵摆怪兽放回牌组。然后适用以下效果。\r\n●自己场上的灵摆怪兽不受该对手的效果影响。\r\n●自己灵摆区域的卡不会因该对手的效果被破坏。\r\n●自己灵摆区域的卡不可因该对手的效果除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92053608,'水伶女－龙鱼','①：１回合１次，可在我方主要阶段发动。从牌组将１只“水伶女”怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92058902,'未来融合－永望结合・新星',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：作为此卡发动时的效果处理，将包含“电子龙”在内的、自己牌组的怪兽作为融合素材，将1只机械族・光属性融合怪兽融合召唤。此卡从场上离开时该怪兽将被破坏。该怪兽被破坏时将此卡破坏。此卡发动后，直至回合结束时为止，自己仅可特殊召唤机械族怪兽，仅可用以此效果特殊召唤的怪兽攻击宣言。','\r',char(13)),'\n',char(10)),'发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92058903,'未来融合－永望结合・新星',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：作为此卡发动时的效果处理，将包含“电子龙”在内的、自己牌组的怪兽作为融合素材，将1只机械族・光属性融合怪兽融合召唤。此卡从场上离开时该怪兽将被破坏。该怪兽被破坏时将此卡破坏。此卡发动后，直至回合结束时为止，自己仅可特殊召唤机械族怪兽，仅可用以此效果特殊召唤的怪兽攻击宣言。','\r',char(13)),'\n',char(10)),'发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92065772,'栖居冰结界的魔醉虫',replace(replace('①：此卡召唤的情况下，指定１处未使用的主要怪兽区域发动。此卡获得以下效果。\r\n●只要此卡存在于怪兽区域，所指定的区域不可使用。','\r',char(13)),'\n',char(10)),'怪兽区1处不可使用','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92067220,'王牌顺子',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：挑选１张自己的手牌舍弃，从牌组将１只“王后骑士”特殊召唤，从牌组将“国王骑士”、“卫兵骑士”中的１只加入手牌。然后，可召唤１只怪兽。此回合，自己从额外牌组仅可特殊召唤战士族・光属性怪兽。\r\n②：在自己・对手的结束阶段，以自己墓地的１只战士族・光属性怪兽为对象可以发动。将该怪兽放回牌组，将墓地的此卡加入手牌。','\r',char(13)),'\n',char(10)),'','是否把1只怪兽召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92079625,'狱影依的炎核 虚炼',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：此卡反转的情况下，以对手场上的1只表侧表示怪兽为对象可以发动。从额外牌组将1只属性与该怪兽相同的“影依”怪兽送至墓地，将对象怪兽除外。\r\n②：此卡因效果被送至墓地的情况下可以发动。依场上怪兽原本属性种类的数量，从自己牌组上面将卡送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92080692,'断念秘诀','①：对手发动与对手墓地卡牌同名的怪兽效果、魔法、陷阱卡时可发动。使该发动无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92084010,'髭嘴安康','上级召唤水属性怪兽的情况下，此卡可作为２只解放。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92092092,'调星之直线加速士',replace(replace('①：此卡发动后变为效果怪兽（机械族・协调・炎・星１・攻０／守１８００），特殊召唤至怪兽区域。此卡也视为陷阱卡。\r\n②：只要以此卡的效果特殊召唤的此卡存在于怪兽区域，自己场上此卡以外的协调不会因战斗及对手的效果被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92099232,'变形妖姐','此卡名的卡1回合仅可发动1张。①：此卡发动后，变为通常怪兽（恶魔族・协调・地・星2・攻/守0），特殊召唤至怪兽区域。此卡也视为陷阱卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92107604,'卢恩神碑之泉',replace(replace('①：只要此卡存在于场地区域，自己可以在对手回合从手牌发动“神碑”速攻魔法卡。\r\n②：1回合1次，自己发动“神碑”速攻魔法卡的情况下，以自己墓地的最多3张“神碑”速攻魔法卡为对象可以发动。将该卡以喜欢的顺序放回牌组下面。然后，自己依放回的数量抽牌。','\r',char(13)),'\n',char(10)),'回收并抽牌','适用「卢恩神碑之泉」的效果来发动','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92110878,'三色小工具',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将1张“光之黄金柜”或记载有该卡名的魔法・陷阱卡加入手牌。\r\n②：此卡因战斗・效果被破坏的情况下可以发动。从牌组将1张“隐匿城 坚实堡垒”放置在自己场上。','\r',char(13)),'\n',char(10)),'牌组检索','牌组放置','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92125819,'圣骑士阿托利斯',replace(replace('隶属圣骑士团的聪明青年骑士。他仿佛受到指引般纵身入林，终于找到了命运。于是青年迈出了重要的一大步。\r\n－－这是一切的起源，是一部伟大的叙事诗。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92133240,'恐啡肽骇龙・特镰西娅','此卡名的①②效果１回合仅可各使用１次。①：此卡召唤・特殊召唤成功的情况下可以发动。从牌组挑选１张“恐啡肽骇龙”陷阱卡，放置在自己的魔法与陷阱区域。自己的LP为２０００以下的情况下，此卡的攻击力进而上升５００。②：此卡因战斗・效果被破坏的情况下，从自己的墓地将１张陷阱卡除外可以发动。从自己的墓地挑选１只“恐啡肽骇龙・特镰西娅”以外的、等级４以下的“恐啡肽骇龙”怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92142169,'大口虫','对手场上存在有超量怪兽的场合，此卡可从手牌特殊召唤。以此方法特殊召唤成功时，选择对手场上的１只怪兽并发动。被选择怪兽的攻击力下降３００点。','攻击下降','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92170894,'娱乐伙伴・听筒长角牛',replace(replace('“娱乐伙伴・听筒长角牛”的效果１回合只可使用１次。\r\n①：此卡特殊召唤成功的场合可发动。从牌组将１只除灵摆怪兽以外的“娱乐伙伴”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92171126,'纠罪巧β’－傲慢“alazoneIA”',replace(replace('←0 【灵摆】 0→\r\n此卡名的②灵摆效果1回合仅可使用1次。\n①：每当有怪兽反转，就在此卡上放1个纠罪计数物。\n②：支付900LP可以发动。从牌组将3张“纠罪巧”卡出示给对手，对手从其中随机挑选1张。将该1张加入自己手牌，剩余的放回牌组。\r\n【怪兽效果】\r\n①：向对手出示手牌的此卡可以发动（发动此效果的回合中，自己仅可以里侧守备表示特殊召唤怪兽）。从手牌将1只怪兽以里侧守备表示特殊召唤。\n②：对手发动包含从牌组将卡加入手牌的效果的、卡的效果时，将里侧表示的此卡改成表侧守备表示可以发动。从牌组将1张“纠罪巧”卡加入手牌。\n③：此卡反转的情况下发动。随机挑选对手的1张手牌直至结束阶段为止以表侧除外。','\r',char(13)),'\n',char(10)),'检索','特殊召唤','检索','除外','','','','','','','','','','','','');
INSERT INTO texts VALUES(92176681,'压制碰撞者','与网络世界巨恶战斗的熟练斗士。被其铁锤压缩的数据任何人都无法复原。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92182447,'时间女神的恶作剧',replace(replace('此卡不可连锁发动，应对此卡的发动，魔法・陷阱・怪兽的效果不可发动。\r\n①：自己场上的怪兽仅有“女战神”怪兽的情况下，在自己的战斗阶段结束时可以发动。将此卡送至墓地。跳过回合，跳到下一个自己回合的战斗阶段开始时。直至该回合结束时为止，自己不可发动“时间女神的恶作剧”。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92200612,'灵魂鸟－传鸠',replace(replace('此卡不可特殊召唤。\r\n①：１回合１次，以场上１只其他的灵魂怪兽为对象可以发动。将该怪兽放回手牌。\r\n②：此卡召唤・反转的回合的结束阶段发动。将此卡放回手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92204263,'绀碧之机界骑士','此卡名以①方法的特殊召唤1回合仅可进行1次。①：同一纵列有2张以上的卡存在的情况下，可将此卡特殊召唤至该纵列的自己场上。②：1回合1次，以自己场上的1只“机界骑士”怪兽为对象可以发动。将自己的该怪兽的位置移动至自己的其他主要怪兽区域。此效果在对手回合中也可以发动。','移动位置','请选择要移动位置的「机界骑士」怪兽','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92219931,'二者一两损','双方各自将牌组最上方的卡牌送入墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92221402,'混沌元素',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从自己牌组・墓地将1只等级5以上的、光・暗属性的炎族・水族怪兽加入手牌。然后，自己墓地存在3只以上炎族・水族怪兽的情况下，可将场上的1张卡破坏。\r\n②：对手场上存在光・暗属性的炎族・水族怪兽的情况下，将墓地的此卡除外，以对手场上的1只怪兽为对象可以发动。获得该怪兽的控制权直至结束阶段为止。','\r',char(13)),'\n',char(10)),'加入手牌','得到控制权','是否破坏1张卡？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92223430,'西摩格之灵峰 厄尔布鲁士','此卡名的②③效果1回合仅可各使用1次。①：场上的鸟兽族・风属性怪兽的攻击力・守备力上升300。②：将手牌的等级5以上的鸟兽族・风属性怪兽出示给对手可以发动。此回合，自己召唤鸟兽族怪兽的情况下所必需的解放可减少1只。③：自己场上有鸟兽族・风属性怪兽存在的情况下可以发动。召唤1只鸟兽族怪兽。','减少解放数量','把1只怪兽召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92223641,'天空之泉','光属性怪兽因战斗被破坏并送入我方墓地时，可通过从游戏中除外１只该怪兽，使我方LP回复相当于该怪兽攻击力的数值。','回复LP','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92246806,'妖仙兽 镰贰太刀',replace(replace('①：此卡召唤成功的场合可发动。从手牌召唤１只除“妖仙兽 镰贰太刀”以外的“妖仙兽”怪兽。\r\n②：此卡可直接攻击。因该战斗给予对手的战斗伤害减半。\r\n③：在召唤此卡回合的结束阶段发动。将此卡返回至持有者手牌。','\r',char(13)),'\n',char(10)),'召唤','返回手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92248362,'K9－17号 饭纲',replace(replace('此卡名的②③效果1回合仅可各使用1次。\r\n①：对手的手牌为2张以上的情况下，此卡无需解放即可召唤。\r\n②：在对手发动过手牌・墓地的怪兽的效果的、自己・对手回合的主要阶段可以发动。从手牌将此卡特殊召唤。\r\n③：此卡召唤・特殊召唤的情况下可以发动。从牌组将“K9－17号 饭纲”以外的1张“K9”卡送至墓地。','\r',char(13)),'\n',char(10)),'不用解放召唤(K9－1７号 饭纲)','特殊召唤','送至墓地','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92266279,'润泽之风',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：支付１０００LP可以发动。从牌组将１只“芬芳”怪兽加入手牌。\r\n②：自己的LP少于对手的情况下可以发动。自己恢复５００LP。','\r',char(13)),'\n',char(10)),'是否使用效果？','加入手牌','LP回复','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92269002,'铁兽之击铁',replace(replace('①：可从以下效果中选择1个发动（此卡名的以下效果1回合仅可各选择1次）。\r\n●从牌组将“铁兽之击铁”以外的1张“铁兽”魔法・陷阱卡加入手牌。\r\n●从自己墓地将任意数量的“铁兽”卡除外可以发动。从额外牌组将1只连接标记数量与除外数量相同数量的“铁兽”连接怪兽无视召唤条件特殊召唤。此回合，自己从额外牌组仅可特殊召唤兽族・兽战士族・鸟兽族怪兽。','\r',char(13)),'\n',char(10)),'','检索效果','连接召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92300891,'机偶桶 真九六','①：此卡在可攻击的情况下必须攻击。②：攻击表示的此卡在被选择为攻击对象的情况下发动。将此卡改成守备表示。③：此卡１回合仅１次，不会因战斗被破坏。','变成守备表示','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92327802,'缺陷编译器',replace(replace('①：１回合１次，我方因对手效果受到伤害的场合，放置１个缺陷计数物至此卡作为代替（最多１个）。\r\n②：１回合１次，可移除此卡的１个缺陷计数物，并以我方场上的１只电子界族怪兽为对象发动。直至回合结束时，该怪兽的攻击力上升８００。此效果在对手回合也可发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92332424,'龙剑士 威风凛凛 天马',replace(replace('←2 【灵摆】 2→\r\n此卡名的灵摆效果１回合仅可使用１次。\n①：另一方自己的灵摆区域存在“龙剑士”卡或“威风魔灵”卡的情况下可以发动。从牌组将原本卡名与该卡不同的１只“龙剑士”灵摆怪兽加入手牌。然后，可将自己的灵摆区域的１张卡破坏。\r\n【怪兽效果】\r\n此卡名在规则上也视为“威风魔灵”卡。\n此卡名的②怪兽效果１回合仅可使用１次。\n①：在自己・对手回合中，从手牌将此卡舍弃可以发动。此回合，自己场上的“龙剑士”怪兽不会因对手的效果被破坏，对手不可将这些怪兽作为效果的对象。\n②：此卡灵摆召唤或以“龙剑士”卡的效果特殊召唤的情况下可以发动。从牌组将１张场地魔法卡加入手牌。然后，挑选１张自己的手牌舍弃。','\r',char(13)),'\n',char(10)),'','是否选自己的灵摆区域1张卡破坏？','将此卡从手牌丢弃','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92341815,'星空蝶','仅可装备于自己场上的怪兽。此卡名的③效果1回合仅可使用1次。①：“星空蝶”在自己场上仅可有1张以表侧表示形式存在。②：对手场上的怪兽的攻击力下降相当于自己场上记载有“勇者衍生物”的衍生物名的怪兽种类×500的数值。③：此卡被送至墓地的情况下，以自己场上的1只“勇者衍生物”为对象可以发动。将此卡装备于自己的该怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92345028,'火焰狂暴','此卡的卡名在规则上也视为“转生炎兽”卡。此卡名的卡1回合仅可发动1张。①：从自己的手牌・墓地挑选最多2只“转生炎兽”怪兽以守备表示特殊召唤（同名卡最多1张）。以此效果特殊召唤的怪兽的效果无效化。此卡发动后，直至回合结束时为止自己仅可从额外牌组特殊召唤怪兽1次。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92346415,'念力剑','此卡仅限装备念动力族怪兽。我方的LP少于对手的场合，装备怪兽的攻击力上升相当于该差额数值（最多２０００）。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92353449,'真红眼洞悉','此卡名的卡１回合仅可发动１张。①：从手牌・牌组将１只“真红眼”怪兽送至墓地可以发动。从牌组将“真红眼洞悉”以外的１张“真红眼”魔法・陷阱卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92359409,'超重型炮塔列车 古斯塔夫火箭炮',replace(replace('等级10怪兽×3\r\n“超重型炮塔列车 古斯塔夫火箭炮”1回合1次，也可通过舍弃1张手牌，重叠在自己场上的“超重型炮塔列车 古斯塔夫超大炮”上面来超量召唤。\r\n此卡名的①效果1回合仅可使用1次。\r\n①：此卡持有超量素材，且对手发动怪兽的效果时可以发动。将该效果无效并破坏。然后，给予对手1000伤害。\r\n②：在自己的结束阶段发动。去除此卡的1个超量素材，或破坏此卡。','\r',char(13)),'\n',char(10)),'是否在「超重型炮塔列车 古斯塔夫超大炮」上面重叠来超量召唤？','效果无效','取除超量素材','是否取除超量素材？','','','','','','','','','','','','');
INSERT INTO texts VALUES(92361635,'核能废铁龙',replace(replace('“废铁”协调＋２只以上协调以外的怪兽\r\n①：１回合１次，以自己场上的１张卡和对手墓地的最多３张卡为对象可以发动。将该自己的卡破坏，将对手的卡放回牌组。②：此卡因对手被破坏并被送至墓地的情况下，以自己墓地同步怪兽以外的１只“废铁”怪兽为对象发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'破坏和返回牌组','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92362073,'银河卫龙',replace(replace('龙族怪兽２只\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：在自己・对手的战斗阶段，将场上・墓地的此卡除外，以自己场上原本种族・属性为龙族・光属性的１只“编号”超量怪兽为对象可以发动。直至战斗阶段结束时为止，对手受到的战斗伤害变为一半，对象怪兽的攻击力变为相当于该怪兽拥有的“编号”数值×１００的数值。\r\n②：在对手的结束阶段可以发动。从牌组挑选１张卡放在牌组最上面。','\r',char(13)),'\n',char(10)),'','','请选择要放置在牌组最上面的卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92365601,'升阶魔法－限制型巴利安之力','①：以自己场上的１只阶级４超量怪兽为对象可以发动。将阶级比该自己怪兽高１的１只“混沌编号”怪兽重叠在对象怪兽上面，视为超量召唤从额外牌组特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92373006,'奴隶虎',replace(replace('①：自己场上存在“剑斗兽”怪兽的情况下，此卡可从手牌特殊召唤。\r\n②：解放此卡，以自己场上的１只“剑斗兽”怪兽为对象可以发动。将该自己的“剑斗兽”怪兽放回牌组，从牌组将１只“剑斗兽”怪兽、视为以“剑斗兽”怪兽的效果特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92377303,'黑衣大贤者','此卡不可通常召唤。我方的“时间魔术师”掷硬币猜中时，可解放我方场上的１只“黑魔导”，并从手牌或牌组特殊召唤。以此方法特殊召唤成功时，从牌组将１张魔法卡加入手牌。','特殊召唤','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92379223,'黄金征服王',replace(replace('此卡名的卡1回合仅可发动1张。①：自己场上存在“埃尔德里奇”怪兽的情况下，可以从以下效果选择1个发动。\r\n●挑选自己被除外的“埃尔德里希尔”魔法・陷阱卡3种各1张放回牌组，将场上的卡全部破坏。\r\n●挑选自己被除外的“黄金乡”魔法・陷阱卡3种各1张放回牌组，对手的LP改成一半。之后，自己的LP恢复对手的LP的数值。','\r',char(13)),'\n',char(10)),'场上的卡全部破坏','对手基本分变成一半','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92385016,'神碑之翼 雾尼',replace(replace('“神碑”怪兽×２\r\n①：此卡从额外牌组特殊召唤成功的情况下，舍弃１张手牌可以发动。从牌组将１张“神碑”永续魔法卡加入手牌。②：对手以自己场上的、“神碑”卡或被放置的卡为对象发动魔法・陷阱・怪兽的效果时，将场上的此卡除外可以发动。将该发动无效并破坏。③：在自己・对手的结束阶段发动。自己恢复１０００LP。','\r',char(13)),'\n',char(10)),'牌组检索','发动无效并破坏','回复基本分','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92391084,'威鲁米','相当凶暴的兔子。会用锐利的钩爪，血祭对手。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92394653,'灵魂的诱惑','此卡的控制者每次须在自己的准备阶段支付５００点LP，或者破坏此卡而不支付５００点LP。当场上表侧表示的灵魂怪兽回到我方手牌中时，对手选择对手场上的１只怪兽回到持有者的手牌中。','返回手牌','是否要支付500基本分维持「灵魂的诱惑」？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92408984,'龙之宝珠','仅以１只龙族怪兽为对象的陷阱卡发动时，可舍弃１张手牌并发动此效果。使该效果无效并破坏。','效果无效并破坏','是否现在使用「龙之宝珠」的效果？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92409659,'白色海豚','头上长角的雪白海豚，会掀起大浪进行攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92411493,'雨天气湛蓝',replace(replace('此卡牌名的①效果１回合只可使用１次。\r\n①：此卡特殊召唤成功的场合可发动。从手牌挑选１张“天气”魔法、陷阱卡，并以表侧表示放置在我方的魔法与陷阱区域。\r\n②：场上的此卡为了发动“天气”卡牌效果而被除外的场合，可在下一个回合的准备阶段发动。特殊召唤被除外的此卡。','\r',char(13)),'\n',char(10)),'从手牌放置「天气」魔法·陷阱卡','除外的此卡特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92418590,'机关傀偶－死灵娃娃',replace(replace('此卡名的效果１回合仅可使用１次，将此卡用作超量召唤的素材的情况下，仅可使用于“机关傀偶”怪兽的超量召唤。\r\n①：此卡存在于墓地的情况下，从自己墓地将１只其他的“机关傀偶”怪兽除外可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92421852,'稀有金属女郎','全身覆盖着金属装甲的女战士。与“稀有金属战士”融合提升力量。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92422871,'电子界封存龙',replace(replace('电子界族的仪式・融合・同步・超量・连接怪兽＋电子界族怪兽\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己的主要阶段可以发动。从手牌将1只电子界族怪兽特殊召唤。然后，可将此卡的等级改成与以此效果特殊召唤的怪兽相同。\r\n②：自己场上存在连接4以上的电子界族怪兽，且对手发动魔法・陷阱卡的效果时，将场上・墓地的此卡除外可以发动。将该发动无效。','\r',char(13)),'\n',char(10)),'','','是否改变此卡的等级？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92428405,'霸王龙之魂','①：支付一半LP可以发动。将１只“霸王龙扎克”效果无效，从额外牌组无视召唤条件特殊召唤。该怪兽将在下个回合的结束阶段放回持有者的额外牌组。②：对手发动魔法卡的效果时，将墓地的此卡和自己场上的１只“霸王龙扎克”除外可以发动。从自己的手牌・牌组・额外牌组・墓地挑选“灵摆龙”、“超量龙”、“同步龙”、“结合龙”怪兽各最多１只来特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92435533,'时械神 拉吉恩',replace(replace('此卡不可从牌组特殊召唤。\r\n①：自己场上不存在怪兽的情况下，此卡无需解放即可召唤。\r\n②：此卡不会因战斗・效果被破坏，因此卡的战斗对自己造成的战斗伤害变为０。\r\n③：此卡进行战斗的战斗阶段结束时发动。将对手墓地的卡全部放回牌组。\r\n④：１回合１次，对手抽牌的情况下发动。给予对手１０００伤害。\r\n⑤：在自己的准备阶段发动。将此卡放回持有者的牌组。','\r',char(13)),'\n',char(10)),'不用解放作召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92450185,'限速突破','①：此卡被送至墓地的情况下发动。从自己手牌・牌组・墓地将1只“高速战士”特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92472273,'终刻龙机ⅩⅡ－德拉斯提亚',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：以自己场上的1张“终刻”卡为对象可以发动。将该卡破坏，从手牌将此卡特殊召唤。然后，可从牌组将1张装备魔法卡装备于此卡。\r\n②：在自己・对手回合中，此卡装备有装备卡的情况下可以发动。从额外牌组将阶级与此卡的等级数值相同的1只机械族・风属性超量怪兽视为超量召唤特殊召唤，将此卡及此卡的装备卡全部作为其超量素材。','\r',char(13)),'\n',char(10)),'特殊召唤','超量召唤','是否装备装备卡？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92481084,'心眼的祭坛','①：只要此卡存在于场地区，我方或对手受到战斗伤害的场合，该数值变成１０００。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92487128,'创星龙华－光轮巴王',replace(replace('←0 【灵摆】 0→\r\n此卡名的灵摆效果１回合仅可使用１次。\n①：在自己的主要阶段可以发动。从牌组将灵摆怪兽以外的１张“龙华”卡加入手牌。然后，将此卡破坏。\r\n【怪兽效果】\r\n以“创星龙华－光轮巴王”降临\n此卡仅可以此卡的效果特殊召唤。\n自己１回合仅可特殊召唤１次“创星龙华－光轮巴王”。\n①：此卡存在于额外牌组的状态下，场上的怪兽因战斗・效果被破坏的情况下可以发动。将自己场上的１只等级１０“龙华”怪兽解放，将此卡视为仪式召唤特殊召唤。然后，可适用以下内容。\n●将自己场上的最多２张卡破坏，以其数量为上限，从牌组将“龙华”永续魔法卡以表侧表示放在自己场上。','\r',char(13)),'\n',char(10)),'检索效果','特殊召唤','是否把卡破坏？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92501449,'原石之鸣狞',replace(replace('①：支付２０００LP，宣言１个通常怪兽的卡名可以发动。直至对手回合结束时为止，自己所宣言的通常怪兽及自己的“原石”怪兽不会因战斗被破坏。自己场上不存在怪兽的情况下，进而可从牌组将１只所宣言的通常怪兽以守备表示特殊召唤。\r\n②：对手将怪兽召唤的情况下，将墓地的此卡除外，以自己场上・墓地的１只通常怪兽为对象可以发动。将场上的１只攻击力低于该怪兽的怪兽除外。','\r',char(13)),'\n',char(10)),'是否要把宣言的怪兽特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92510265,'圣战士混沌士兵',replace(replace('“圣战士混沌士兵”的效果①，１回合只可使用１次。\r\n①：此卡召唤、特殊召唤成功时，可以１只我方被除外的光属性或暗属性怪兽和对手场上的１张卡牌为对象发动。该我方的卡牌返回至墓地，并除外该对手卡牌。\r\n②：此卡在战斗中破坏对手怪兽时，可以我方墓地的１只等级７或以下的战士族怪兽为对象发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'除外','加入手牌','请选择要回到墓地的卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92512625,'神之忠告',replace(replace('①：放置在自己的魔法与陷阱区域的卡仅有此卡的情况下，支付3000LP可以发动。\r\n●怪兽的效果・魔法・陷阱卡发动时可以发动。将该发动无效并破坏。\r\n●自己或对手召唤・反转召唤・特殊召唤怪兽之际可以发动。将其无效，将该怪兽破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92517928,'银河眼反物质龙',replace(replace('等级9怪兽×2\r\n“银河眼反物质龙”1回合1次，也可重叠在持有3个以上超量素材的、自己的超量怪兽上面来超量召唤。\r\n①：持有超量素材的此卡给予对手的战斗伤害变为一半。\r\n②：去除此卡的1个超量素材可以发动。此回合，此卡在1次战斗阶段中最多可攻击怪兽2次。去除的超量素材为怪兽的情况下，进而可从牌组将1只与该怪兽种族相同的怪兽送至墓地。','\r',char(13)),'\n',char(10)),'是否在超量怪兽上面重叠超量召唤？','2次攻击','是否把怪兽送至墓地？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92518817,'盛燃希塔','①：1回合1次，解放自己场上的1只其他炎属性怪兽可以发动。从手牌将1只炎属性怪兽特殊召唤。以此效果特殊召唤的怪兽在自己场上表侧表示的“盛燃希塔”从场上离开时将被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92519087,'电脑堺狐－仙仙',replace(replace('协调＋１只以上协调以外的怪兽\r\n此卡名的②③效果１回合仅可各使用１次。①：从场上被送至墓地的卡不去墓地而直接被除外。②：自己怪兽的攻击宣言时可以发动。挑选自己或对手１只被除外的怪兽放回墓地。③：从自己的墓地将此卡以外的２只原本种族・属性不同的怪兽除外可以发动。从墓地将此卡特殊召唤。此效果在此卡被送至墓地的回合不可发动。','\r',char(13)),'\n',char(10)),'选怪兽回到墓地','从墓地特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92530005,'娱乐巫师・骑球手',replace(replace('←3 【灵摆】 3→\r\n此卡名的灵摆效果１回合仅可使用１次。\n①：在自己的主要阶段可以发动。从自己额外牌组（表侧）将１只“娱乐巫师”灵摆怪兽送至墓地。然后，此卡的灵摆刻度可上升相当于送至墓地的怪兽的灵摆刻度的数值。\r\n【怪兽效果】\r\n此卡名的①②③怪兽效果１回合仅可各使用１次。\n①：自己场上存在“娱乐巫师”怪兽的情况下可以发动。从手牌将此卡特殊召唤。\n②：此卡召唤・特殊召唤的情况下，可从以下效果中选择１个发动。\n●从牌组将１只“娱乐巫师”灵摆怪兽以表侧加入额外牌组。\n●将自己场上的１张“娱乐巫师”怪兽卡破坏。\n③：被特殊召唤的对手怪兽的直接攻击宣言时可以发动。从墓地将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'从额外牌组送至墓地','从手牌特殊召唤','发动效果','从墓地特殊召唤','选择1个效果','加入额外牌组','破坏效果','请选择要加入额外牌组的卡','是否上升灵摆刻度？','','','','','','','');
INSERT INTO texts VALUES(92534075,'魔弹－魔鬼交易',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：只要此卡存在于魔法与陷阱区域，自己场上的“魔弹”怪兽不会因效果被破坏。\r\n②：此卡因对手的效果被送至墓地的情况下可以发动。从自己的牌组・墓地将“魔弹－魔鬼交易”以外的１张“魔弹”卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92536468,'DDD 反骨王雷奥尼达',replace(replace('←3 【灵摆】 3→\r\n①：自己受到效果伤害时可以发动。将此卡破坏，在此回合，给予LP伤害的效果变为恢复LP的效果。\r\n【怪兽效果】\r\n①：自己受到效果伤害时可以发动。从手牌将此卡特殊召唤，依所受伤害的数值恢复自己的LP。\n②：只要此卡存在于怪兽区域，自己受到的效果伤害变为0。','\r',char(13)),'\n',char(10)),'此卡破坏','此卡从手牌特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92559258,'恩底弥翁之侍从',replace(replace('←2 【灵摆】 2→\r\n①：每当自己或对手发动魔法卡，就在此卡上放1个魔力计数物。\n②：去除此卡的3个魔力计数物可以发动。将牌组的1只能放魔力计数物的、攻击力1000以上的怪兽和此卡特殊召唤，在该2只上各放1个魔力计数物。\r\n【怪兽效果】\r\n自己1回合仅可特殊召唤1次“恩底弥翁之侍从”。\n①：放有魔力计数物的此卡可直接攻击。\n②：在每个对手回合中1次，舍弃1张手牌可以发动。在此卡以及自己场上能放魔力计数物的所有卡上各放1个魔力计数物。\n③：怪兽区域的此卡被破坏的情况下可以发动。将此卡放在自己的灵摆区域。然后，依此卡原先放有的魔力计数物数量，在此卡上放魔力计数物。','\r',char(13)),'\n',char(10)),'特殊召唤','放置计数物','在灵摆区域放置','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92562411,'星遗物所引导的前路','①：“星遗物所引导的前路”在自己场上仅可有1张以表侧表示形式存在。②：每次场上的等级5以上表侧表示怪兽被送至墓地，每有1只便在此卡上放1个计数物（最多7个）。③：将被放了7个计数物的此卡送至墓地可以发动。从额外牌组将1只电子界族连接怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92565383,'玉米田 科亚特尔',replace(replace('此卡名的①③效果１回合仅可各使用１次。\r\n①：从手牌将此卡舍弃可以发动。从牌组将“玉米田 科亚特尔”以外的１只记载有“客迈拉结合”卡名的怪兽加入手牌。\r\n②：此卡与怪兽进行战斗的情况下，该２只不会因该战斗被破坏。\r\n③：自己场上存在“有翼幻兽 客迈拉”，且对手发动以自己场上的卡为对象的效果时，将场上・墓地的此卡除外可以发动。将该效果无效并破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92572371,'杀炎星－牛逵',replace(replace('此卡名的效果１回合仅可使用１次。\r\n①：此卡存在于墓地的情况下，将自己的手牌・场上（表侧表示）的“炎星”卡或“炎舞”卡共２张送至墓地可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92586237,'武斗神－目一个',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：从手牌将１张其他的“武斗神”卡送至墓地可以发动。从手牌将此卡特殊召唤。\r\n②：可从以下效果中选择１个发动。\r\n●从手牌将１只“武斗神”怪兽送至墓地可以发动。从自己的墓地挑选１只卡名与该怪兽不同的“武斗神”怪兽加入手牌。\r\n●从自己的墓地将１只“武斗神”怪兽除外可以发动。将１只卡名与该怪兽不同的“武斗神”怪兽从牌组送至墓地。','\r',char(13)),'\n',char(10)),'特殊召唤','从墓地加入手牌','从牌组送至墓地','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92595545,'电浆球','此卡可直接攻击对手玩家。此卡因直接攻击给予对手生命战斗伤害时，破坏此卡。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92595643,'罚金','我方挑选２张手牌并舍弃。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92595825,'夜蔷薇之黑骑士',replace(replace('此卡名的①③效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从自己墓地将1只“黑蔷薇龙”或等级4以下的植物族怪兽特殊召唤。以此效果特殊召唤的怪兽的效果无效化。\r\n②：只要自己场上存在同步怪兽，自己场上的植物族怪兽的攻击力上升1000。\r\n③：以自己场上的1只其他的植物族怪兽为对象可以发动。该怪兽的等级上升或下降1。','\r',char(13)),'\n',char(10)),'特殊召唤','改变等级','等级上升','等级下降','','','','','','','','','','','','');
INSERT INTO texts VALUES(92597893,'淘气风龙之费德兰',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡召唤・特殊召唤成功的情况下，以自己场上的１只表侧表示怪兽为对象可以发动。此回合，该怪兽攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。\r\n②：在对手回合中，以此卡以外的场上的１只表侧表示怪兽为对象可以发动。变更该怪兽的表示形式。然后，将此卡放回持有者的手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92607427,'玩具游行队','此卡名在规则上也视为“魔玩具”卡。此卡名的①②效果1回合1次，仅可使用其中1个。①：以自己的1只从额外牌组被特殊召唤的暗属性怪兽为对象可以发动。此回合，自己仅可用该怪兽攻击宣言，每当该怪兽战斗破坏怪兽并将之送至墓地，可继续攻击。②：自己场上有天使族怪兽存在的情况下，将墓地的此卡除外可以发动。从自己的墓地挑选1只等级4以下的暗属性怪兽加入手牌。','多次攻击','墓地回收','是否继续攻击？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92609670,'英豪挑战者 伏击士兵','我方准备阶段时，可释放场上的此卡并发动。最多可从我方手牌、墓地挑选２只除“英豪挑战者 伏击士兵”以外冠有“英豪挑战者”之名的怪兽并特殊召唤。“英豪挑战者 伏击士兵”的此效果１回合只可使用１次。以此效果特殊召唤成功时，可将墓地的此卡从游戏中除外并发动。我方场上所有冠有“英豪挑战者”之名的怪兽等级变成１。','特殊召唤','等级变换','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92610868,'来音服和弦・多利米娅',replace(replace('←7 【灵摆】 7→\r\n①：自己的“音服和弦”灵摆怪兽的灵摆召唤不会被无效化。\r\n【怪兽效果】\r\n此卡名的①怪兽效果1回合仅可使用1次。\n①：自己的灵摆区域存在“音服和弦”卡的情况下可以发动。从手牌将此卡特殊召唤。\n②：自己的灵摆区域存在奇数的灵摆刻度，自己场上的“音服和弦”灵摆怪兽卡将被对手的效果破坏的情况下，可破坏此卡来代替将被破坏的该卡当中的1张。','\r',char(13)),'\n',char(10)),'此卡特殊召唤','请选择要代替被破坏的卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92644052,'娱乐伙伴 稀代的决斗者',replace(replace('←8 【灵摆】 8→\r\n①：１回合１次，怪兽之间进行战斗的伤害步骤开始时可以发动。将此卡放回手牌，从牌组将１张魔法卡除外。自己的怪兽不会因该战斗被破坏，因该战斗对自己造成的战斗伤害变为一半。\r\n【怪兽效果】\r\n①：此卡给予对手战斗伤害时可以发动。从牌组将１只“霸王眷龙”怪兽或“霸王门”怪兽，或１张“霸王龙之魂”加入手牌。\n②：在自己・对手的准备阶段发动。双方可各从自身的牌组将１张魔法卡除外。\n③：１回合１次，自己或对手的怪兽的攻击宣言时发动。被攻击的玩家可适用以下效果。\n●将自身的除外状态的１张魔法卡加入手牌。然后，将该卡舍弃，使该攻击无效。','\r',char(13)),'\n',char(10)),'自己怪兽不会被那次战斗破坏','牌组检索','双方从牌组把魔法卡除外','用除外的魔法卡把攻击无效','是否从牌组把魔法卡除外？','是否用除外的魔法卡把攻击无效？','','','','','','','','','','');
INSERT INTO texts VALUES(92650018,'惊乐游乐设施 鬼屋',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：以自己场上的１只“惊乐园”怪兽或对手场上的表侧表示怪兽为对象可以发动此卡。将此卡视为装备卡，装备于该怪兽。\r\n②：根据装备怪兽的控制者，可以发动以下效果。\r\n●自己：以对手场上的１只效果怪兽为对象可以发动。将该怪兽的效果直至回合结束时为止无效。\r\n●对手：将装备怪兽改成里侧守备表示。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92650749,'成熟编年史',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：每次“尤贝尔”怪兽或记载有“尤贝尔”卡名的怪兽被特殊召唤，在此卡上放１个编年史计数物。\r\n②：依以下数量去除自己场上的编年史计数物，可以发动相应效果。\r\n●１：从自己的墓地将１只“尤贝尔”特殊召唤。\r\n●２：将自己１张除外状态的卡加入手牌。\r\n●３：从牌组挑选１张卡除外。\r\n●４：将场上的１张卡破坏。\r\n●５：从牌组将１张“超融合”加入手牌。','\r',char(13)),'\n',char(10)),'1：从自己墓地把1只「尤贝尔」特殊召唤','2：自己的除外状态的1张卡加入手牌','3：从牌组选1张卡除外','4：场上1张卡破坏','5：从牌组把1张「超融合」加入手牌','','','','','','','','','','','');
INSERT INTO texts VALUES(92652813,'凭依觉醒－大稻荷火',replace(replace('此卡名的②③效果1回合仅可各使用1次。\r\n①：此卡可通过将自己场上表侧表示的、1只魔法师族怪兽和1只等级4以下的炎属性怪兽送至墓地，来从手牌・牌组特殊召唤。\r\n②：以此卡的①方法特殊召唤时可以发动。给予对手相当于对手场上的1只怪兽的原本攻击力数值的伤害。\r\n③：此卡从场上被送至墓地的情况下可以发动。从牌组将1张“火灵术”卡或“凭依”魔法・陷阱卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92661479,'光子雷电豹镖',replace(replace('等级６怪兽×２\r\n１回合１次，怪兽的效果在对手场上发动时，移除此卡的１个超量素材可以发动。使该效果无效，并给予对手LP１０００点伤害。','\r',char(13)),'\n',char(10)),'效果无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92667214,'夺命马戏团僵尸','被黑暗力量复活的小丑。以诡谲摇曳的舞步引人走向死亡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92676637,'调和支援者','①：以场上的此卡作为同步素材的情况下，可将此卡视为等级2怪兽。②：此卡作为同步素材被送至墓地的情况下发动。自己从牌组抽1张。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92693205,'齿轮齿轮锚',replace(replace('①：在我方主要阶段可发动。此卡变成里侧守备表示（１回合仅１次）。\r\n②：此卡反转的场合可发动。挑选场上的怪兽破坏，其数量最多是除此卡以外的我方场上冠有“齿轮齿轮”之名的怪兽数量。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92714517,'欢迎大驾光临拉比丽斯',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：从自己手牌・牌组・墓地将１只“拉比丽斯”怪兽特殊召唤。然后，将自己场上的１只怪兽放回手牌。\r\n②：将墓地的此卡除外，以自己场上的１只恶魔族怪兽为对象可以发动。将该卡放回手牌。自己场上存在等级８以上的恶魔族怪兽的情况下，作为代替也可以对手场上的１张卡作为对象。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92719314,'暗黑创世神','此卡不可通常召唤。自己墓地有５只以上暗属性怪兽存在，且自己场上不存在怪兽的情况下可以特殊召唤。①：１回合１次，将自己墓地的１只暗属性怪兽除外，以自己墓地的１只暗属性怪兽为对象可以发动。将该暗属性怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92720564,'变形斗士・收录机',replace(replace('此卡依据此卡的表示形式获得以下效果。\r\n●攻击表示：此卡在１次战斗阶段中可攻击２次。\r\n●守备表示：１回合１次，我方场上冠有“变形斗士”之名的怪兽被选择为攻击对象时，可使该攻击无效。','\r',char(13)),'\n',char(10)),'战斗无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92723496,'龙宫的双使者',replace(replace('“龙宫的双使者”的效果１回合仅可使用１次。\r\n①：从手牌将１只怪兽舍弃可以发动。从牌组将１只等级４以下的幻龙族怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92729410,'子狸彭彭','此卡召唤成功时，可从牌组以里侧守备表示特殊召唤１只除“子狸彭彭”以外的兽族、等级２怪兽。发动此效果的回合，我方只可特殊召唤兽族怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92731385,'泪冠哀歌・琪多卡洛斯',replace(replace('“泪冠哀歌”怪兽＋水族怪兽\r\n此卡名的①②③效果１回合仅可各使用１次。①：此卡特殊召唤成功的情况下可以发动。从牌组挑选１张“泪冠哀歌”卡，加入手牌或送至墓地。②：以自己场上的１只怪兽为对象可以发动。从自己的手牌・墓地挑选１只“泪冠哀歌”怪兽特殊召唤，将对象怪兽送至墓地。③：此卡因效果被送至墓地的情况下可以发动。从自己的牌组上面将５张卡送至墓地。','\r',char(13)),'\n',char(10)),'牌组检索','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92731455,'磁体战士２号','擅长搭档战斗的战士。有着电磁涂层的甲胄十分坚固。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92736188,'伟大神灵','此卡在１个回合中可有１次机会变为里侧守备表示。成功反转召唤此卡时，可选择场上的１只地属性怪兽来发动此卡。令选择的地属性怪兽的原始攻击力和原始守备力互换，直到结束阶段时。','变成里侧守备','攻守交换','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92744676,'电磁枪虾',replace(replace('协调＋协调以外的怪兽1只\r\n此卡名的①效果1回合仅可使用1次。\r\n①：此卡特殊召唤的情况下，从自己手牌・场上将此卡以外的1张卡送至墓地，以对手场上的1张魔法・陷阱卡为对象可以发动。将该卡破坏。\r\n②：在对手的主要阶段可以发动（同一连锁上最多1次）。将包含此卡在内的、自己场上的怪兽作为素材进行同步召唤。','\r',char(13)),'\n',char(10)),'破坏','进行同步召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92746535,'龙剑士 光栅行者 灵摆',replace(replace('←5 【灵摆】 5→\r\n①：１回合１次，另一方自己的灵摆区域存在卡的情况下可以发动。将该卡破坏，从牌组将该卡的１张同名卡加入手牌。\r\n【怪兽效果】\r\n不能以此卡作为素材来特殊召唤“龙剑士”怪兽以外的融合・同步・超量怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92755808,'元素暴龙',replace(replace('当场上有特定属性的怪兽存在的场合，此怪兽获得以下效果。\r\n●炎属性：此卡的攻击力上升５００点。\r\n●地属性：此卡通过战斗破坏的效果怪兽的效果无效。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92767273,'娱乐伙伴凶猛蔷薇',replace(replace('←5 【灵摆】 5→\r\n①：１回合１次，在我方“娱乐伙伴”怪兽与对手怪兽进行战斗的伤害计算前可发动。该对手怪兽的攻击力下降相当于与该原本攻击力的差额数值。\r\n【怪兽效果】\r\n“娱乐伙伴凶猛蔷薇”的怪兽效果１回合只可使用１次。\n①：可以１只持有攻击力与其原本攻击力不同的“娱乐伙伴”怪兽为对象发动。直至回合结束时，该怪兽的攻击力上升相当于与该原本攻击力的差额数值。此效果在对手回合也可发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92770064,'圣天树之大母神',replace(replace('连接怪兽２只以上\r\n①：此卡连接召唤的情况下可以发动。从牌组将１张“圣天树”魔法・陷阱卡加入手牌。\r\n②：此卡不会因对手的效果被破坏，不会成为攻击对象（自己场上仅存在适用此效果的怪兽的状态下，对手的攻击变为对自己的直接攻击）。\r\n③：１回合１次，解放此卡连接端的自己的１只连接怪兽可以发动。将对手场上最多为该连接标记数量的卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92773018,'人工脑秘密技术','①：对手怪兽攻击宣言时1次，将自己场上1只表侧表示的“电子龙”或1只记载有以“电子龙”作为融合素材的融合怪兽送至墓地，可以1只该攻击怪兽为对象发动。将该攻击怪兽破坏。','攻击怪兽破坏','是否现在使用「人工脑秘密技术」的效果？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92781606,'超机怪虫・感质方舟',replace(replace('“机怪虫”怪兽2只\r\n①：根据自己场上的“机怪虫”怪兽数量适用以下内容。\r\n●2只以上：自己场上的怪兽的攻击力・守备力上升300。\r\n●4只以上：对手在战斗阶段中不可发动效果。\r\n●6只以上：自己的怪兽可直接攻击。\r\n②：表侧表示的此卡因对手的效果从场上离开的情况下，或因战斗被破坏的情况下，以自己墓地的2只“机怪虫”怪兽为对象可以发动（同名卡最多1张）。将该怪兽以里侧守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92784374,'咒仪・艾莉娅儿','①：此卡反转的情况下可以发动。从牌组将１只“咒仪”怪兽加入手牌。','加入手牌','是否要把1只名字带有「咒仪」的怪兽加入手牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92798873,'恐啡肽骇龙・终结暴龙',replace(replace('“恐啡肽骇龙”融合怪兽＋“恐啡肽骇龙”怪兽\r\n此卡名的②③效果１回合仅可各使用１次。①：拥有自己LP数值以上攻击力的对手场上的怪兽不可发动效果。②：在自己・对手回合中，支付一半LP可以发动。对手场上所有怪兽的攻击力直至回合结束时为止，变为与自己LP的数值相同。③：此卡因战斗・效果被破坏的情况下可以发动。从自己的墓地挑选１只等级６以下的“恐啡肽骇龙”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92807548,'堕天使 乌科巴克',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将1张“堕天使”卡送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92812851,'超升灵摆・奇迹的魔剑士',replace(replace('包含灵摆怪兽在内的效果怪兽２只以上\r\n此卡名的①③效果１回合仅可各使用１次。\r\n①：此卡连接召唤的情况下可以发动。从自己的额外牌组将１只表侧灵摆怪兽加入手牌。\r\n②：此卡的攻击力上升相当于自己场上的灵摆怪兽卡的数量×１００的数值。\r\n③：在自己・对手的主要阶段可以发动。根据自己灵摆区域２张卡的灵摆刻度，从自己的手牌・墓地，将１只拥有可灵摆召唤的等级的灵摆怪兽以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92821268,'机关傀偶－暗夜小丑','我方场上冠有“机关傀偶”之名的怪兽因战斗被破坏并被送入我方墓地时，可将该怪兽从游戏中除外并发动。从手牌特殊召唤此卡。“机关傀偶－暗夜小丑”的效果１回合只可使用１次。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92826944,'马头鬼','①：将墓地的此卡除外，以自己墓地的1只不死族怪兽为对象可以发动。将该不死族怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92841002,'幻水龙','我方场上存在有地属性怪兽的场合，此卡可从手牌特殊召唤。以此方法进行的“幻水龙”之特殊召唤，１回合只可进行１次。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92854392,'拦路强敌','对手进行攻击宣言时可发动。选择我方场上表侧表示的１只怪兽。发动回合，对方只能以所选怪兽为攻击对象，必须使用所有表侧攻击表示的怪兽攻击所选怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92868896,'龙骑兵团－元老院','此卡名的①效果1回合仅可使用1次。①：从手牌将1张“龙骑兵团”卡舍弃可以发动。从牌组挑选1只“龙骑兵团”协调，将其视为装备卡装备于此卡。此效果发动后，直至回合结束时为止，自己从额外牌组仅可特殊召唤龙族怪兽。②：自己场上的“龙骑兵团”卡将被战斗・效果破坏的情况下，作为代替，可将1张装备于此卡的“龙骑兵团”卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92870717,'魔装战士 龙夜',replace(replace('←7 【灵摆】 7→\r\n①：对手怪兽的攻击宣言时可发动。破坏此卡，结束该战斗阶段。\r\n【怪兽效果】\r\n①：１回合１次，可舍弃１张手牌，并以我方墓地的１只攻击力２０００或以下的战士族或魔法师族怪兽作为对象发动。以里侧守备表示特殊召唤该怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92881099,'魅惑的千层镜','此卡名的①②效果１回合仅可各使用１次。①：自己的“神鹰女郎”或“神鹰女郎三姐妹”因战斗被破坏时可以发动。将１只原本卡名与该怪兽不同的“神鹰”怪兽从牌组特殊召唤。②：场上的此卡因对手的效果或自己“神鹰”卡的效果被破坏的情况下，以自己墓地的１只“神鹰”怪兽为对象发动。将该怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92887027,'流浪者佣兵部队','此卡因战斗破坏对手怪兽并送入墓地时，可解放此卡并发动。选择对手场上１只里侧守备表示怪兽破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92890308,'变形','我方场上冠有“变形斗士”之名的怪兽被选择为攻击对象时，可选择１只攻击怪兽与１只攻击对象怪兽并发动。使该攻击无效，并变更被选择攻击对象怪兽的表示形式。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92892239,'枪管上膛暴怒龙',replace(replace('龙族・暗属性怪兽×2\r\n此卡名的①②效果1回合仅可各使用1次。①：以自己场上的1只怪兽和对手场上的1张卡为对象可以发动。将该卡破坏。此效果在对手回合中也可以发动。②：将墓地的此卡除外，以自己墓地的1只暗属性连接怪兽为对象可以发动。将该怪兽特殊召唤。以此效果特殊召唤的怪兽此回合不可发动效果。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92895501,'对击斗魂 重型博格',replace(replace('此卡名的①②效果１回合仅可各使用１次，不可在同一连锁上发动。\r\n①：在自己・对手的主要阶段，以自己场上的机械族以外的１只“对击斗魂”怪兽为对象可以发动。将该怪兽放回手牌，从手牌将此卡特殊召唤。\r\n②：在自己・对手回合中，从以下选择１个，将手牌相应属性的怪兽各１只出示给对手可以发动。\r\n●暗：自己抽１张。\r\n●地・炎：给予对手１５００伤害。','\r',char(13)),'\n',char(10)),'此卡从手牌特殊召唤','展示暗属性的怪兽','展示地·炎属性的怪兽','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92901944,'废铁探寻者','①：此卡存在于墓地，自己场上“废铁探寻者”以外的表侧表示“废铁”怪兽因战斗以外被破坏并被送至墓地时可以发动。将此卡特殊召唤。②：此卡特殊召唤成功的情况下发动。将自己场上“废铁”怪兽以外的表侧表示怪兽全部破坏。','特殊召唤','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92907248,'觉醒吧・百夫骑士！',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：怪兽卡以表侧表示存在于自己的魔法与陷阱区域的情况下，宣言等级４或８可以发动。将拥有所宣言等级的１只“百夫骑衍生物”（炎族・暗・攻／守０）特殊召唤至自己场上。此衍生物不可作为融合・连接素材。\r\n②：在自己的主要阶段将墓地的此卡除外可以发动。从牌组将“觉醒吧・百夫骑士！”以外的１张“百夫骑”卡送至墓地。','\r',char(13)),'\n',char(10)),'特殊召唤衍生物','送至墓地','请宣言1个等级','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92907249,'百夫骑衍生物','由「觉醒吧・百夫骑士！」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92918648,'魔导法皇 海隆',replace(replace('魔法师族等级７怪兽×２\r\n１回合１次，可移除此卡的１个超量素材并发动。挑选对手场上的魔法、陷阱卡破坏，其数量最多是我方墓地冠有“魔导书”之名的魔法卡数量。','\r',char(13)),'\n',char(10)),'魔陷破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92919429,'宣告者之神巫','此卡名的①②效果１回合仅可各使用１次。①：此卡召唤・特殊召唤成功的情况下可以发动。从牌组・额外牌组将１只天使族怪兽送至墓地。此卡的等级直至回合结束时为止，上升相当于该怪兽等级的数值。②：此卡被解放的情况下可以发动。从手牌・牌组将“宣告者之神巫”以外的１只等级２以下的天使族怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92924317,'苏醒之魂','①：可以我方墓地中的１只通常怪兽为对象发动此卡。以守备表示特殊召唤该怪兽。当此卡离开场上时破坏该怪兽。当该怪兽被破坏时破坏此卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92932860,'娱乐伙伴 诱导女导演',replace(replace('此卡名的③效果１回合仅可使用１次。\r\n①：只要自己场上存在“异色眼”怪兽，对手不可将此卡选择为攻击对象。\r\n②：只要此卡以守备表示存在于怪兽区域，自己的“异色眼”怪兽不会因战斗被破坏，因该战斗对自己造成的战斗伤害变为０。\r\n③：以自己墓地的１只等级１怪兽为对象可以发动。将该怪兽的效果无效并特殊召唤，仅以该怪兽和此卡作为素材同步召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92933195,'霞之谷的风使','１回合１次，双方手牌都为５张或以上的场合可发动。双方玩家将手牌送入墓地，直到手牌变为４张。','手牌协调','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92936364,'暗红恶魔锁链',replace(replace('此卡名的卡1回合仅可发动1张。\r\n此卡也可通过向对手出示额外牌组的1只“暗红恶魔龙”，来在放置的回合发动。\r\n①：向对手出示手牌任意数量的怪兽，依其中协调的数量＋1只，以对手场上的效果怪兽为对象可以发动此卡。只要此卡存在于魔法与陷阱区域，对象怪兽的攻击力下降从手牌出示的数量×100的数值，效果无效化。对象怪兽不存在场上的情况下，此卡将被破坏。','\r',char(13)),'\n',char(10)),'发动','适用「暗红恶魔锁链」的效果来发动','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92936365,'暗红恶魔锁链',replace(replace('此卡名的卡1回合仅可发动1张。\r\n此卡也可通过向对手出示额外牌组的1只“暗红恶魔龙”，来在放置的回合发动。\r\n①：向对手出示手牌任意数量的怪兽，依其中协调的数量＋1只，以对手场上的效果怪兽为对象可以发动此卡。只要此卡存在于魔法与陷阱区域，对象怪兽的攻击力下降从手牌出示的数量×100的数值，效果无效化。对象怪兽不存在场上的情况下，此卡将被破坏。','\r',char(13)),'\n',char(10)),'发动','适用「暗红恶魔锁链」的效果来发动','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92944626,'邪炎之翼','黑红燃烧的翅膀。从全身喷射出火焰进行攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92958307,'娱乐伙伴秀场尾声','①：以对手场上表侧表示怪兽为对象可以发动，数量最多为自己场上表侧表示魔法卡的数量。将该怪兽改成里侧守备表示。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92962242,'重之忍者－磁翁',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡召唤・特殊召唤・反转的情况下以场上的最多２只表侧表示怪兽为对象可以发动。将该怪兽改成里侧守备表示。对手场上以此效果变为里侧守备表示的怪兽不可变更表示形式。\r\n②：此卡已以表侧表示存在于怪兽区域的状态下，场上的怪兽反转的情况下，以对手场上的１张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'变成里侧守备表示','对手1张卡破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92964816,'成长花','此卡名的效果１回合仅可使用１次。①：此卡被送至墓地的情况下，将墓地的此卡除外可以发动。从牌组将１只等级５以上的不死族怪兽加入手牌。场地区域存在“不死世界”的情况下，也可不加入手牌而是改为将其特殊召唤。此效果发动后，直至回合结束时为止，自己仅可特殊召唤不死族怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92970404,'地中骇界邪龙 熔烬巴利阿里',replace(replace('此卡名的③效果1回合仅可使用1次。\r\n①：自己场上的表侧表示怪兽变为里侧表示时，若自己场上不存在表侧表示怪兽则可以发动。从手牌将此卡以守备表示特殊召唤。\r\n②：在自己的主要阶段可以发动。将此卡改成里侧守备表示（1回合仅1次）。\r\n③：此卡反转的情况下可以发动。将场上其他的表侧表示怪兽全部改成里侧守备表示。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(92998610,'孤高除兽',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡召唤时，从手牌将１只怪兽除外可以发动。从牌组将１只种族与所除外怪兽相同的怪兽除外。\r\n②：此卡因战斗或对手的效果被破坏的情况下，以自己除外状态的１只怪兽为对象可以发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93013676,'摩诃毗卢','①：此卡的攻击力上升装备于此卡上的装备卡数量×５００。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93014827,'零日冲击波','①：解放自己场上的1只暗属性连接怪兽，以该连接标记数量的场上的卡为对象可以发动。将该卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93016201,'王宫的弹压',replace(replace('双方玩家可以通过支付８００LP发动以下效果。\r\n●在包含将怪兽特殊召唤的效果的怪兽的效果・魔法・陷阱卡发动时可以发动。将该效果无效并破坏。 \r\n●在自己或对手特殊召唤怪兽之际可以发动。将该特殊召唤无效，并将该怪兽破坏。','\r',char(13)),'\n',char(10)),'无效特殊召唤','是否现在使用「王宫的弹压」的效果？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93018428,'梅尔菲・凯西','此卡名的①②效果１回合仅可各使用１次。①：对手将怪兽召唤・特殊召唤成功的情况下，或此卡被选择为对手怪兽的攻击对象的情况下可以发动。将此卡放回持有者的手牌。然后，可从牌组中将１只“梅尔菲・凯西”以外的兽族怪兽加入手牌。②：在自己的结束阶段可以发动。从手牌将此卡特殊召唤。','','','是否从牌组把卡加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93020401,'灯影之机界骑士','此卡名以①方法的特殊召唤1回合仅可进行1次。①：同一纵列有2张以上的卡存在的情况下，可将此卡特殊召唤至该纵列的自己场上。②：与此卡同一纵列的对手卡从场上离开的情况下，或因战斗被破坏的情况下可以发动。从手牌将1只“机界骑士”怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93023136,'堕入黑暗的天使',replace(replace('此卡名在规则上也视为“堕天使”卡。\r\n此卡名的卡1回合仅可发动1张。\r\n①：从自己手牌・场上（表侧表示）将1只天使族怪兽送至墓地可以发动。将自己手牌・牌组・除外状态的1只“堕天使”怪兽无视召唤条件特殊召唤。','\r',char(13)),'\n',char(10)),'发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93023479,'守墓的召唤师','此卡从我方场上被送入墓地时，从我方牌组将１只守备力１５００或以下冠有“守墓的”之名的怪兽加入手牌。','牌组检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93031067,'海造贼－大船厂',replace(replace('具此卡名的②③效果１回合各只能使用１次。\r\n①：我方场上的“海造贼”怪兽的攻击力上升我方魔法与陷阱区域的“海造贼”卡片数×５００点。\r\n②：我方主要阶段弃掉１张手牌可发动。将１张除“海造贼－大船厂”以外的“海造贼”卡从卡组加入手牌。\r\n③：此卡存在于墓地中的情况下，以我方魔法与陷阱区域的１张“海造贼”卡为目标可发动。将此卡放置在我方场上，将目标卡移回拥有者的手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93039339,'神兵灾星－厄咒弑 堤・丰',replace(replace('等级12怪兽×2\r\n在对手从额外牌组特殊召唤了2只以上怪兽的回合及其下个回合，此卡也可重叠在自己场上攻击力最高的怪兽上面来超量召唤。\r\n以此方法特殊召唤过的余下本回合，自己不可召唤・特殊召唤怪兽。\r\n①：只要超量召唤的此卡存在于怪兽区域，双方不可发动攻击力3000以上的怪兽的效果。\r\n②：1回合1次，去除此卡的1个超量素材可以发动。将场上的1只怪兽放回手牌。','\r',char(13)),'\n',char(10)),'在自己场上的攻击力最高的怪兽上面重叠来超量召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93039340,'神兵灾星－厄咒弑 堤・丰',replace(replace('等级12怪兽×2\r\n在对手从额外牌组特殊召唤了2只以上怪兽的回合及其下个回合，此卡也可重叠在自己场上攻击力最高的怪兽上面来超量召唤。\r\n以此方法特殊召唤过的余下本回合，自己不可召唤・特殊召唤怪兽。\r\n①：只要超量召唤的此卡存在于怪兽区域，双方不可发动攻击力3000以上的怪兽的效果。\r\n②：1回合1次，去除此卡的1个超量素材可以发动。将场上的1只怪兽放回手牌。','\r',char(13)),'\n',char(10)),'在自己场上的攻击力最高的怪兽上面重叠来超量召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93053159,'白教导枢机龙',replace(replace('“阿尔白斯之落胤”＋自己墓地卡名不同的怪兽×6\r\n此卡从额外牌组仅可通过融合召唤来特殊召唤。\r\n①：此卡可攻击所有对手怪兽各1次。\r\n②：此卡攻击宣言之际，必须将自己额外牌组的1张卡送至墓地。\r\n③：1回合1次，融合召唤的此卡存在于怪兽区域，且自己墓地存在6种以上需以“阿尔白斯之落胤”作为融合素材的融合怪兽的情况下可以发动。将双方额外牌组的卡全部送至墓地。','\r',char(13)),'\n',char(10)),'全部各作1次攻击','额外牌组1张送墓','双方额外全部送至墓地','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93078761,'赛挑战',replace(replace('此卡名的卡在1个回合中仅可发动1张。\r\n①：掷骰子1次，出现1和6时，将牌组中1张拥有掷骰子效果的卡加入手牌。出现1、6以外的数字时，再掷骰子1次，根据出现的数字适用以下效果。\r\n●1、6：将场上的此卡还回持卡人的手牌。\r\n●2～5：将场上的此卡还回持卡人牌组的最上方。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93084621,'破械神 安若磐',replace(replace('包含“破械神”怪兽在内的怪兽2只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：以对手场上的1只表侧表示怪兽为对象可以发动。仅以该对手怪兽和自己场上的此卡作为素材，进行“破械神 安若磐”以外的1只暗属性连接怪兽的连接召唤。\r\n②：场上的此卡因战斗・效果被破坏的情况下，以“破械神 安若磐”以外的、自己墓地的1只恶魔族怪兽为对象可以发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93085839,'圣骑士爱克托・德・马利斯',replace(replace('“圣骑士爱克托・德・马利斯”的①效果１回合只可使用１次。\r\n①：可将我方墓地的２只“圣骑士”怪兽除外并发动。从手牌、墓地特殊召唤此卡。\r\n②：以此卡为素材的“圣骑士”怪兽的同步召唤、超量召唤不会被无效化，且该特殊召唤成功时，对手不可发动魔法、陷阱、怪兽的效果。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93087299,'炎之护封剑','自己场上没有怪兽存在的情况下，对手怪兽不可攻击宣言。自己场上有怪兽存在的情况下，或对手手牌为５张以上的情况下，此卡将被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93104632,'动态认证码','此卡名的卡1回合仅可发动1张。①：将1只“安全衍生物”（电子界族・光・星4・攻/守2000）以守备表示特殊召唤至自己场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93104633,'安全衍生物','由「动态认证码」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93107608,'共鸣虫','此卡因战斗被破坏并送入墓地时可发动。从牌组特殊召唤１只攻击力是１５００或以下的昆虫族怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93108297,'液体怪兽','能够融解后在水中自由移动的液体生命体。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93108433,'怪兽回收','可选择我方场上的原先持有者是我方的１只怪兽并发动。被选择怪兽与我方手牌全部加入牌组并洗牌。之后，从牌组抽取相当于原先手牌张数的卡牌。原先的持有者为对手，且卡牌在我方手牌的场合，此卡不可发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93108839,'编号58 炎压鬼焊接护目镜',replace(replace('等级４怪兽×２\r\n①：１回合１次，可从以下效果选择１个发动。\r\n●以我方场上的１只超量怪兽为对象，且此卡被视为装备卡装备该怪兽。\r\n●以攻击表示特殊召唤被装备的此卡。\r\n②：装备怪兽可直接攻击对手。\r\n③：装备怪兽给予对手战斗伤害时，可舍弃１张手牌并发动。给予对手５００的伤害。','\r',char(13)),'\n',char(10)),'装备','LP伤害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93124273,'雷普提尔的武者骑兵',replace(replace('←3 【灵摆】 3→\r\n【怪兽效果】\r\n①：此卡攻击了除灵摆怪兽以外的对手表侧表示怪兽的伤害步骤开始时，可发动。破坏该怪兽。','\r',char(13)),'\n',char(10)),'怪兽破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93125329,'金云兽－马龙',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的②效果1回合仅可使用1次。\r\n①：此卡特殊召唤的情况下可以发动。此卡的等级上升或下降1。\r\n②：此卡被送至墓地的情况下，以对手场上的1张表侧表示卡为对象可以发动。将该卡放回手牌。','\r',char(13)),'\n',char(10)),'','','等级上升','等级下降','','','','','','','','','','','','');
INSERT INTO texts VALUES(93130021,'胜利毒蛇 XX03',replace(replace('①：此卡战斗破坏对手怪兽的情况下，从以下效果中选择1个发动。\r\n●此卡的攻击力上升400。\r\n●以场上的1张表侧表示的魔法・陷阱卡为对象发动。将该表侧表示卡破坏。\r\n●将1只始终与此卡种族・属性・等级・攻击力・守备力相同的“子机衍生物”特殊召唤至自己场上。此卡不再以表侧表示存在于怪兽区域时，此衍生物将被破坏。','\r',char(13)),'\n',char(10)),'选择一个效果发动','此卡攻击力上升400','表侧表示魔法·陷阱卡破坏','「附属零件衍生物」特殊召唤','','','','','','','','','','','','');
INSERT INTO texts VALUES(93130022,'附属零件衍生物','由“胜利毒蛇XX０３”或“力量胶囊”的效果特殊召唤而来。此衍生物的种族、属性、等级、攻击力、守备力常与原本的「胜利毒蛇 XX０３」相同。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93138457,'战斗无力化音速','①：在对手怪兽攻击宣言时可以发动。将该攻击无效。然后，可从手牌・牌组特殊召唤１只“T.G.”怪兽或等级４以下的协调。','是否特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93149655,'异色眼魅影龙',replace(replace('←4 【灵摆】 4→\r\n①：１回合１次，另一方自己的灵摆区域存在“异色眼”卡的情况下，自己的表侧表示怪兽与对手怪兽进行战斗的攻击宣言时可以发动。该自己的怪兽的攻击力直至战斗阶段结束时为止上升１２００。\r\n【怪兽效果】\r\n此卡名的怪兽效果１回合仅可使用１次。\n①：以灵摆召唤的此卡的攻击给予对手战斗伤害时可以发动。给予对手相当于自己的灵摆区域的“异色眼”卡的数量×１２００的伤害。','\r',char(13)),'\n',char(10)),'攻击力上升','效果伤害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93151201,'电流金刚','此卡给予对手生命战斗伤害时，从对手牌组上方将卡牌送入墓地，其数量相当于我方场上光属性怪兽的数量。','牌组送墓','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93156774,'对击斗魂 神圣苏',replace(replace('此卡名的①②效果1回合仅可各使用1次，不可在同一连锁上发动。\r\n①：在自己・对手的主要阶段，向对手出示手牌的1只其他的“对击斗魂”怪兽可以发动。从手牌将此卡特殊召唤。\r\n②：在自己・对手回合中，从以下选择1个，向对手出示手牌的相应属性的怪兽各1只可以发动。\r\n●地・暗：获得对手场上攻击力最低的1只怪兽的控制权直至结束阶段为止。\r\n●炎・暗：从牌组将念动力族以外的1只“对击斗魂”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'此卡特殊召唤','地·暗属性','炎·暗属性','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93157004,'大日神械Ω',replace(replace('２只协调＋协调以外１只冠有“大日神械”之名的怪兽\r\n此卡同步召唤成功时，破坏场上所有通常召唤而来的表侧表示怪兽。１回合１次，选择１只我方墓地冠有“大日神械”之名的怪兽，并视为装备卡装备此卡。怪兽效果发动时，可将我方场上装备于此卡的１张装备卡送入墓地并发动。使该发动无效并破坏。','\r',char(13)),'\n',char(10)),'通常召唤的怪兽全部破坏','装备','效果怪兽的效果发动无效并破坏','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93169863,'水晶女孩','此卡名的①②效果1回合仅可各使用1次。①：此卡召唤・特殊召唤成功的情况下可以发动。此回合的结束阶段，从牌组将1只等级5以上的水属性怪兽加入手牌。②：此卡存在于墓地、自己场上有等级5以上的水属性怪兽存在的情况下可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡离开场上的情况下，将其除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93170499,'朱罗纪・斑龙',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：自己场上存在恐龙族怪兽的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：在自己的主要阶段可以发动。从手牌挑选包含“朱罗纪”卡在内的2张卡舍弃。然后，自己抽2张。\r\n③：此卡因战斗・效果被破坏的情况下可以发动。从牌组・额外牌组将“朱罗纪・斑龙”以外的1只“朱罗纪”怪兽送至墓地。','\r',char(13)),'\n',char(10)),'特殊召唤','抽牌','送至墓地','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93172951,'小丑戏帮 梅特欧',replace(replace('协调＋协调以外的怪兽1只以上\r\n①：自己怪兽的上级召唤成功时，对手不可发动魔法・陷阱・怪兽的效果。\r\n②：此卡被解放的情况下，可从以下效果中选择1个发动（此卡名的以下效果1回合仅可各选择1次）。\r\n●将双方场上・墓地的同步怪兽全部放回额外牌组。\r\n●以“小丑戏帮 梅特欧”以外的、自己墓地的1张“小丑戏帮”卡为对象可以发动。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'选择效果','回收同步怪兽','回到手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93187568,'魔法打击者',replace(replace('①：此卡可除外我方墓地的１张魔法卡，并从手牌特殊召唤。\r\n②：此卡可直接攻击。\r\n③：此卡在战斗中造成的对我方的战斗伤害变为０。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93191801,'黄金乡盗掘者','此卡名的①②效果1回合1次，仅可使用其中1个。①：此卡发动后变为通常怪兽（不死族・光・等级5・攻1800/守1500），特殊召唤至怪兽区域。此卡也视为陷阱卡。自己场上存在“黄金卿埃尔德里奇”的情况下，可以进而挑选自己・对手墓地的1张卡将其除外。②：在自己・对手的结束阶段将墓地的此卡除外后可以发动。从牌组挑选1张“埃尔德里希尔”魔法・陷阱卡放置在自己场上。','','','是否选卡除外？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93192592,'棒棒喵★黯蜜味',replace(replace('协调＋协调以外的怪兽1只\r\n要同步召唤此卡的情况下，可将自己场上的1只连接1怪兽视为等级1协调。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡同步召唤的情况下可以发动。从自己墓地将2只“黯蜜”怪兽的效果无效并特殊召唤。\r\n②：对手发动魔法・陷阱・怪兽的效果时，将此卡放回额外牌组可以发动。从自己墓地将最多2只“黯蜜”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'从墓地特殊召唤','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93211810,'超音速波','可在我方回合选择场上的１只冠有“幻兽机”之名的怪兽并发动。此回合被选择怪兽的攻击力变成其原本攻击力的２倍，并不受除此卡以外的魔法、陷阱卡效果的影响，攻击守备表示怪兽时，若其攻击力超过守备力，给予对手生命相当于该差值的战斗伤害。之后，在此回合的结束阶段时，破坏我方场上的所有机械族怪兽。发动此卡的回合，除被选择怪兽以外的怪兽不可攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93211836,'军用次代机','①：解放“次代机”怪兽来上级召唤此卡时，以对手场上的１张卡为对象可以发动。将该对手的卡破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93217231,'毒蛇的供品','①：以自己场上的1只爬虫类族怪兽和对手场上的2张卡为对象可以发动。将该1只自己的爬虫类族怪兽和该2张对手的卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93220472,'巨龙','我方场上有怪兽存在的场合，不可召唤此卡。只有在我方场上有除此卡之外的表侧表示的龙族怪兽存在的场合，此卡才可进行攻击宣言。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93221206,'古代精灵','已活了数千年的精灵。可操纵精灵进行攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93224848,'幻魔殉教者','①：除此卡以外自己的手牌存在2张以上，且自己场上有“神炎皇乌利亚”或“降雷皇哈蒙”存在的情况下，将手牌全部送至墓地可以发动。将3只“幻魔殉教者衍生物”（恶魔族・暗・星1・攻/守0）以攻击表示特殊召唤至自己场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93224849,'幻魔殉教者衍生物','由“幻魔殉教者”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93229151,'愤怒风暴之神碑',replace(replace('此卡名的卡１回合仅可发动１张。①：可从以下效果中选择１个发动。此卡发动后，跳过下一个自己的战斗阶段。\r\n●从对手的牌组上面将卡除外，数量最多为对手场上卡的数量。\r\n●从额外牌组将１只“神碑”怪兽特殊召唤至额外怪兽区域。','\r',char(13)),'\n',char(10)),'牌组除外','特殊召唤','请选择要除外的卡的数量','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93236220,'围绕星遗物的战争','①：将自己场上的1只表侧表示怪兽直至结束阶段为止除外，以对手场上的1只表侧表示怪兽为对象可以发动。该对手怪兽的攻击力・守备力分别下降为发动此卡除外的怪兽相应的原本数值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93238626,'千尊的玉座','对手的结束阶段时，自己恢复相当于该回合所受战斗伤害次数×５００的生命值。此外，自己的“混沌编号”以外的“编号”怪兽被选择为攻击对象时，将此卡送至墓地可以发动。将该攻击无效。然后，将拥有与该自己的怪兽相同“编号”数字的“混沌编号”怪兽重叠在该怪兽上面，视为超量召唤从额外牌组特殊召唤。“千尊的玉座”在自己场上仅可有１张以表侧表示存在。','回复','攻击无效特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93260132,'魔法效果之矢','①：将对手场上的表侧表示的魔法卡全部破坏，给予对手相当于破坏的数量×５００的伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93294363,'百臂无形诱惑手',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：自己场上存在“百臂无形”怪兽，且对手发动怪兽的效果时可以发动。将该发动无效并破坏。然后，可将所破坏的怪兽特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'','是否特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93294869,'伤炎星－狼松','①：此卡反转的情况下可以发动。从牌组将１张“炎舞”陷阱卡放置在自己场上。此卡因反转召唤而反转的情况下，进而可从牌组将１张“炎舞”魔法卡放置在自己场上。','放置','是否要选择名字带有「炎舞」的魔法卡在自己场上放置？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93298460,'魔装战士 风之青龙',replace(replace('①：此卡可进行直接攻击。\r\n②：此卡从场上被送入墓地的场合，可以我方墓地中１只龙族・战士族・魔法师族的通常怪兽为对象发动此卡。将该怪兽加入到手牌中。','\r',char(13)),'\n',char(10)),'卡片回收','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93302695,'星际仙踪－暗黑魔女',replace(replace('“星际仙踪－暗黑魔女”的①效果１回合仅可使用１次。\r\n①：将场上的此卡除外可以发动。从手牌将１只等级５以上的“星际仙踪”怪兽特殊召唤。此效果在对手回合中也可以发动。\r\n②：１回合１次，支付１０００LP可以发动。此回合，此卡不会因战斗・效果被破坏。此效果在对手回合中也可以发动。','\r',char(13)),'\n',char(10)),'从手牌把「星际仙踪」怪兽特殊召唤','此卡不会被战斗·效果破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93317313,'DD 防御士兵',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：可从以下效果中选择1个发动。\r\n●以自己灵摆区域的1张“DD”卡为对象可以发动。将该卡特殊召唤。\r\n●从自己墓地将1只“DD”怪兽除外可以发动。此回合，自己的“DDD”怪兽攻击的情况下，对手直至伤害步骤结束时为止，不可发动卡的效果。\r\n②：将墓地的此卡除外可以发动。从自己额外牌组（表侧）・墓地将1只“DD”灵摆怪兽加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','效果封锁','回收','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93332803,'怒焰坏兽 哥吉龙',replace(replace('①：此卡可以解放对手场上1只怪兽，以攻击表示从手牌特殊召唤至对手场上。\r\n②：对手场上存在“坏兽”怪兽的情况下，此卡可以从手牌以攻击表示特殊召唤。\r\n③：“坏兽”怪兽在自己场上仅可有1只以表侧表示存在。\r\n④：1回合1次，去除自己・对手场上的3个坏兽计数物可以发动（发动此效果的回合中，此卡不可攻击）。将对手场上的怪兽全部破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93343894,'水之魔导师','以水包围对手，发动包抄攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93346024,'洞窟潜龙','潜伏在洞窟中的巨龙。平时虽然很温驯，一旦发怒时会变得非常可怕。据说它是财宝的守卫。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93347961,'元素－英雄 火焰翼人－火焰射击',replace(replace('属性不同的“元素－英雄”怪兽×２\r\n此卡仅可以融合召唤方式特殊召唤。\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡特殊召唤的情况下可以发动。从自己的牌组・墓地将１张“至爱”卡加入手牌。\r\n②：解放以通常怪兽作为素材融合召唤的此卡可以发动。从牌组・额外牌组将１只等级７以下、不可通常召唤的“元素－英雄”怪兽无视召唤条件特殊召唤。','\r',char(13)),'\n',char(10)),'','','用通常怪兽为素材作融合召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93353691,'不退之荒武者',replace(replace('战士族协调＋１只以上协调以外的战士族怪兽\r\n受到攻击力高于此卡的怪兽攻击的情况下，此卡不会因该战斗被破坏，在伤害计算后将进行战斗的对手怪兽破坏。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93356623,'魔弹－交叉主宰者',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：自己场上存在“魔弹”怪兽的情况下，以场上的１只表侧表示怪兽为对象可以发动。直至回合结束时为止，该怪兽的攻击力・守备力变为０，效果无效化。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93360904,'黯蜜游乐★巨可口',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：自己将兽族・光属性同步怪兽同步召唤的情况下，以对手场上的1张卡为对象可以发动。将该卡破坏。\r\n②：自己场上的表侧表示怪兽因对手的效果从场上离开的情况下可以发动。从牌组将1只“黯蜜”怪兽特殊召唤。\r\n③：此卡存在于墓地的情况下，以自己墓地・除外状态的2只“黯蜜”怪兽为对象可以发动。将该怪兽和此卡以喜欢的顺序放回牌组下面。','\r',char(13)),'\n',char(10)),'破坏','特殊召唤','回到牌组','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93368494,'魔妖仙兽 大刃祸是',replace(replace('←7 【灵摆】 7→\r\n①：我方场上的“妖仙兽”怪兽的攻击宣言时可发动。直至战斗阶段结束时，该攻击怪兽的攻击力上升３００。\r\n【怪兽效果】\r\n此卡仅可以灵摆召唤进行特殊召唤。\n①：此卡的灵摆召唤不会被无效化。\n②：此卡召唤、特殊召唤成功的场合，最多可以场上的２张卡牌为对象发动。将该卡返回至持有者手牌。\n③：在特殊召唤此卡之回合的结束阶段发动。将此卡返回至持有者手牌。','\r',char(13)),'\n',char(10)),'攻击上升','弹回手牌','返回手牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93369354,'生化鱼－枪手','自己场上有等级３以下的水属性怪兽存在的情况下，舍弃１张手牌可以发动。从墓地将此卡特殊召唤。此卡作为同步素材的情况下，其他的同步素材怪兽必须全部是水属性怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93377803,'孤毒之剑',replace(replace('仅可装备于自己场上的怪兽。\r\n①：“孤毒之剑”在自己场上仅可有1张以表侧表示存在。\r\n②：装备怪兽的原本的攻击力・守备力仅在与对手怪兽进行战斗的伤害计算时变为两倍。\r\n③：自己场上存在装备怪兽以外的怪兽的情况下，此卡将被送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93379652,'宝石骑士・光棱晶',replace(replace('“宝石骑士”怪兽＋雷族怪兽\r\n此卡从额外牌组仅可通过融合召唤来特殊召唤。\r\n①：1回合1次，从手牌将1张“宝石骑士”卡送至墓地，以场上的1张表侧表示卡为对象可以发动。将该表侧表示卡破坏。','\r',char(13)),'\n',char(10)),'表侧表示的1张卡破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93382620,'命之绳索','当我方怪兽因战斗而被送入墓地时，弃置所有手牌发动此卡。令该怪兽的攻击力上升８００点，并将其特殊召唤至场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93394164,'并行装甲车炮',replace(replace('仅可装备于连接怪兽。\r\n此卡名的②效果１回合仅可使用１次。\r\n①：１回合１次，在自己的主要阶段可以发动。将装备怪兽的位置移动至该怪兽连接端的主要怪兽区域（不可移动至从该怪兽来看的对手场上）。\r\n②：将被装备中的此卡送至墓地可以发动。挑选１张与装备过此卡的场上怪兽同一纵列的卡破坏。','\r',char(13)),'\n',char(10)),'移动位置','卡片破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93396832,'角笛粉碎','使怪兽的召唤、特殊召唤无效的怪兽的效果、陷阱卡发动时可发动。使该发动无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93413793,'宇迦之御狐玉响',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：自己场上存在兽族・植物族・天使族的等级4以下的光属性怪兽的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：以此卡作为素材同步召唤的怪兽获得以下效果。\r\n●此卡的守备力上升500。\r\n●只要此卡以守备表示存在于怪兽区域，对手不可将此卡作为效果的对象。','\r',char(13)),'\n',char(10)),'特殊召唤','','「宇迦之御狐玉响」效果适用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93431518,'通往暗黑界之结界通路','选择我方墓地１只冠有“暗黑界”之名的怪兽特殊召唤。此卡发动的回合，我方不可召唤、反转召唤、特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93431862,'命运－英雄 扣杀小子','可从手牌将１只冠有“命运－英雄”之名的卡牌送入墓地并发动。给予对手生命５００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93437091,'宾果机器 冲！冲！',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：从牌组挑选以下合计３张的卡出示给对手，对手从其中随机挑选１张。将该１张卡加入自己手牌，剩余的卡放回牌组。\r\n●“青眼”怪兽\r\n●“宾果机器 冲！冲！”以外的、记载有“青眼白龙”或“青眼究极龙”卡名的魔法・陷阱卡','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93445074,'灰篮眼镜蛇',replace(replace('①：自己怪兽区域的此卡因战斗或陷阱卡的效果被破坏并被送至墓地的情况下，以对手场上的１只表侧表示怪兽为对象可以发动。将此卡视为装备卡，装备于该对手怪兽。\r\n②：此卡以此卡的效果被装备中的情况下，获得装备怪兽的控制权。此卡离开场上时，装备怪兽将被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93449450,'方程式运动员 侧挂马赫','①：此卡的攻击力上升相当于此卡等级×300的数值，不受原本等级或阶级低于此卡等级的对手怪兽发动的效果的影响。②：“方程式运动员”魔法・陷阱卡的效果发动的情况下可以发动（伤害步骤也可以发动）。此卡的等级上升1。③：此卡的等级为7以上的情况下，被送往对手墓地的卡不去墓地而直接被除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93451636,'发条蜜蜂','可以在这张卡在战斗中被破坏并送至墓地时发动。从卡组中特殊召唤１只等级４以下且具“发条”之名的怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93453053,'码丽丝镜中奇缘',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：以对手场上的1只表侧表示怪兽为对象可以发动。从自己手牌・场上（表侧表示）将1只“码丽丝”怪兽除外，将对象怪兽的效果直至回合结束时为止无效。\r\n②：此卡被除外的情况下，以自己墓地的1张“码丽丝”卡为对象可以发动。将该卡除外，从牌组将1张种类（怪兽・魔法・陷阱）与所除外的卡相同的“码丽丝”卡加入手牌。','\r',char(13)),'\n',char(10)),'无效','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93454062,'大植然蝼蛄','此卡名的①②效果１回合仅可各使用１次。①：在自己・对手的主要阶段，解放此卡可以发动。从牌组将１只“大植然”怪兽特殊召唤。攻击力最高的怪兽存在于对手场上的情况下，可将以此效果特殊召唤的数量改成２只。②：此卡存在于墓地的状态下，对手从额外牌组将怪兽特殊召唤的情况下，或自己从额外牌组将“大植然”怪兽特殊召唤的情况下可以发动。将此卡特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93469007,'爆裂爆发','①：解放自己场上的1只“／爆裂”怪兽可以发动。双方受到所解放怪兽的等级×200的伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93473606,'惊乐游乐设施 奇迹摩天轮',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：以自己场上的１只“惊乐园”怪兽或对手场上的表侧表示怪兽为对象可以发动此卡。将此卡视为装备卡，装备于该怪兽。\r\n②：根据装备怪兽的控制者，可以发动以下效果。\r\n●自己：在双方的主要阶段可以发动。挑选１张手牌，放回牌组最下面。然后，自己从牌组抽１张。\r\n●对手：装备怪兽的攻击力・守备力直至回合结束时为止互换。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93481594,'音服和弦・幸福多重奏',replace(replace('①：可从以下效果中选择1个发动（此卡名的以下效果1回合仅可各选择1次）。\r\n●挑选自己的1张手牌舍弃，从牌组将灵摆刻度不同的2只“音服和弦”灵摆怪兽加入手牌。然后，以对手场上的怪兽数量＋1只为上限，可从手牌特殊召唤“音服和弦”灵摆怪兽。\r\n●此回合，自己在通常的灵摆召唤之外，可在自己的主要阶段追加1次灵摆召唤“音服和弦”怪兽。\r\n●将自己灵摆区域的2张“音服和弦”卡特殊召唤。','\r',char(13)),'\n',char(10)),'发动','检索效果','额外灵摆','特殊召唤','是否特殊召唤？','使用「音服和弦・幸福多重奏」的效果灵摆召唤','','','','','','','','','','');
INSERT INTO texts VALUES(93483212,'极神圣帝奥丁',replace(replace('“极星天”协调＋协调以外的怪兽２只或以上\r\n①：１回合１次，可在我方主要阶段发动。直至回合结束时，此卡不受魔法、陷阱卡的效果影响。\r\n②：场上表侧表示的此卡因对手被破坏并送入墓地回合的结束阶段，可从我方墓地将１只“极星天”协调除外并发动。从墓地特殊召唤此卡。\r\n③：以此卡的②效果特殊召唤成功时可发动。我方从牌组抽取１张卡牌。','\r',char(13)),'\n',char(10)),'不受魔法·陷阱卡的影响','特殊召唤','抽牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93490856,'相剑军师－龙渊','此卡名的①②效果１回合仅可各使用１次。①：将此卡以外的手牌的１张“相剑”卡或１只幻龙族怪兽舍弃可以发动。从手牌将此卡特殊召唤。然后，可将１只“相剑衍生物”（幻龙族・协调・水・星４・攻／守０）特殊召唤至自己场上。只要以此效果特殊召唤的衍生物存在，自己从额外牌组仅可特殊召唤同步怪兽。②：此卡作为同步素材被送至墓地的情况下可以发动。给予对手１２００伤害。','','','是否特殊召唤衍生物？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93490857,'相剑衍生物','由“相剑”卡片的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93503294,'幻变骚灵・隐私元班西',replace(replace('“幻变骚灵”怪兽2只以上\r\n此卡名的①②效果1回合仅可各使用1次。①：在自己・对手的主要阶段，解放此卡以外的自己场上的1只“幻变骚灵”怪兽可以发动。从牌组将1只“幻变骚灵”怪兽特殊召唤至此卡连接端的自己场上。②：此卡从场上被送至墓地的情况下，以自己墓地的1张“幻变骚灵”卡为对象可以发动。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93504463,'通往进化的桥梁','①：自己场上的怪兽被选择为攻击对象时，以自己墓地的１只“进化虫”怪兽为对象可以发动。将对象怪兽特殊召唤，将攻击对象移换为该怪兽并进行伤害计算。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93506862,'咒仪虚无法师','在我方主要阶段时，可从手牌舍弃此卡并发动。此回合，针对冠有“咒仪”之名的仪式魔法卡的发动，对手不可发动魔法・陷阱・怪兽效果，冠有“咒仪”之名的仪式怪兽仪式召唤成功时，对手不可发动魔法・陷阱・怪兽效果。','发动限制','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93507434,'恐龙摔跤手・卡帕扑翼龙',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：对手场上的怪兽数量多于自己场上的怪兽的情况下，以对手场上的1只怪兽为对象可以发动。将该怪兽送至墓地。\r\n②：此卡作为“恐龙摔跤手”连接怪兽的连接素材被送至墓地的情况下可以发动。该连接怪兽的攻击力直至回合结束时为止上升1000。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93509766,'恐巄龙华－㟴轮巴王',replace(replace('此卡名的①②③效果１回合仅可各使用１次。\r\n①：从手牌将此卡放回牌组可以发动。从牌组将１张“登龙华恐巄门”加入手牌。\r\n②：在有２张以上卡被破坏的回合的、自己・对手的主要阶段可以发动。从手牌将此卡特殊召唤。\r\n③：将自己场上的１张表侧表示“登龙华恐巄门”放回牌组最下面，以场上的其他卡为对象可以发动，数量最多为场上的种族的种类数量。将该卡破坏。','\r',char(13)),'\n',char(10)),'检索','手牌特殊召唤','卡片破坏','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93542102,'变形斗士・手机',replace(replace('此卡依据此卡的表示形式获得以下效果。\r\n●攻击表示：１回合１次，掷１次骰子，从我方牌组上方翻阅与掷出数字相同数量的卡牌。从中挑选１只等级４或以下的冠有“变形斗士”之名的怪兽，并无视召唤条件特殊召唤，将剩下的卡牌返回至牌组并洗牌。\r\n●守备表示：１回合１次，掷１次骰子，从我方牌组上方确认卡牌并按原本顺序返回至牌组，其数量最多是掷出数字数量。','\r',char(13)),'\n',char(10)),'特殊召唤','确认牌组','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93543806,'先史遗产 太阳独石碑','１回合１次，可选择我方场上１只冠有“先史遗产”之名的怪兽并发动。被选择怪兽的等级变成６。发动此效果的回合，我方只可特殊召唤冠有“先史遗产”之名的怪兽。','等级变换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93553943,'食人花','吃人的人面花，用有毒的触手进行攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93554166,'暗黑界之雷','①：以场上1张里侧表示的卡为对象可以发动。将该里侧表示卡破坏。然后，挑选自己的1张手牌舍弃。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93568288,'编号80 狂装霸王 狂战狂想曲',replace(replace('等级4怪兽×2\r\n此卡名的①效果1回合最多可使用2次。\r\n①：去除此卡的1个超量素材，以对手墓地的1张卡为对象可以发动。将该卡除外。\r\n②：以自己场上的1只超量怪兽为对象可以发动。将自己场上的此卡视为攻击力上升1200的装备魔法卡，装备于该自己的怪兽。','\r',char(13)),'\n',char(10)),'当作装备卡给自己场上的超量怪兽装备','选择对手墓地1张卡从游戏中除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93581434,'刚鬼 地狱训练师','此卡名的①效果1回合仅可使用1次。①：自己场上不存在怪兽的情况下，向对手出示手牌中的此卡，以自己墓地的1只“刚鬼”连接怪兽为对象可以发动。从手牌将此卡特殊召唤。然后将对象怪兽特殊召唤。以此效果特殊召唤的连接怪兽的攻击力下降500。②：只要自己场上存在“刚鬼”连接怪兽，此卡不会因战斗被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93595154,'烙印之裁决','此卡名的②效果１回合仅可使用１次。①：以自己场上１只等级８以上的融合怪兽为对象可以发动。将对手场上拥有该怪兽攻击力以上攻击力的怪兽全部破坏。②：在此卡为发动“阿尔白斯之落胤”的效果被送至墓地的回合的结束阶段可以发动。将此卡放置在自己场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93599951,'沉默的邪恶灵','此卡只可在对手的战斗步骤时发动。令１只攻击怪兽的攻击无效，改为对手场上表侧表示的１只其他怪兽进行攻击。（若所选择怪兽为守备表示的场合，则将其变为攻击表示。）','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93600443,'假面变换二型',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：舍弃1张手牌，以自己场上的1只表侧表示怪兽为对象可以发动。确认该怪兽的等级・属性，并送至墓地。该怪兽因此效果从场上离开的情况下，进而从额外牌组将1只等级高于该怪兽、属性相同的“假面－英雄”怪兽视为由“假面变换”的效果特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93612434,'双持手枪龙','此卡名的①②效果１回合仅可各使用１次。①：解放此卡，以自己墓地２只卡名不同的“枪弹”怪兽为对象可以发动。以守备表示形式将该怪兽特殊召唤。②：将墓地的此卡除外可以发动。从自己的牌组・墓地挑选１张“旋疾扳机”或“重型扳机”加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93655221,'屏蔽盾处理器','①：破坏场上怪兽之魔法・陷阱・怪兽的效果发动时，可以我方及对手场上的各１只连接怪兽为对象发动此卡。使对象之对手怪兽的效果无效，并将此卡视为装备卡装备于对象之我方怪兽。装备怪兽不会因效果被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93657021,'命运－英雄 暮托邦魔侠',replace(replace('“命运－英雄”融合怪兽＋“命运－英雄”怪兽\r\n①：此卡融合召唤的情况下可以发动。将自己手牌・场上的怪兽作为融合素材，将1只融合怪兽融合召唤。\r\n②：在每个自己・对手回合中1次，以场上的1只怪兽为对象可以发动。此回合，该怪兽不会因战斗・效果被破坏，因该怪兽的战斗对双方造成的战斗伤害变为0。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93662626,'点火骑士・乌兹',replace(replace('←7 【灵摆】 7→\r\n①：另一方自己的灵摆区域存在“点火骑士”卡的情况下可以发动。将自己的灵摆区域的２张卡破坏，从自己的牌组・墓地将１只战士族・炎属性怪兽加入手牌。\r\n【怪兽效果】\r\n负责“德林加”的监督工作，也是亲卫队长。总是被冒冒失失的她耍得团团转，只好把苦水都吐给了唯一懂得自己的“点五零”。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93665266,'水晶机巧－石英',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：在对手的主要阶段及战斗阶段可以发动。从手牌将协调以外的1只怪兽的效果无效并特殊召唤，仅以该怪兽和此卡作为素材，进行1只机械族同步怪兽的同步召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93671934,'士气高扬','每次将装备魔法卡装备怪兽，装备魔法卡的控制者回复１０００LP。此外，每次装备魔法卡离开场上，装备魔法卡的控制者受到１０００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93672138,'邪恶★双子 麻烦桑妮',replace(replace('包括“邪恶★双子”怪兽在内的怪兽２只以上\r\n此卡名的①②效果１回合仅可各使用１次。①：解放此卡可以发动。从自己的墓地挑选“姬丝吉尔”怪兽和“璃拉”怪兽各最多１只特殊召唤。此效果在对手回合中也可以发动。②：将墓地的此卡除外，从手牌・牌组及自己场上的表侧表示怪兽中，将１只“邪恶★双子”怪兽送至墓地可以发动。挑选场上的１张卡送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93683815,'圣龙布尔米纳像',replace(replace('←1 【灵摆】 1→\r\n此卡名的灵摆效果1回合仅可使用1次。\n①：有怪兽因自己的陷阱卡的效果被特殊召唤的情况下，以场上的1张卡为对象可以发动。将该卡放回手牌。然后，可将此卡特殊召唤。\r\n【怪兽效果】\r\n此卡名的①怪兽效果1回合仅可使用1次。\n①：对手怪兽攻击宣言时可以发动。将此卡放在自己的灵摆区域，将该对手的怪兽放回手牌。\n②：怪兽区域的此卡被破坏的情况下可以发动。将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'对手怪兽回到手牌','在灵摆区域放置','回到手牌','是否特殊召唤？','','','','','','','','','','','','');
INSERT INTO texts VALUES(93684009,'剑斗排斥波',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：在战斗阶段以外，对手不可将自己场上的“剑斗兽”怪兽作为效果的对象。\r\n②：“剑斗兽”怪兽被从自己牌组特殊召唤的情况下可以发动。从牌组将１只自己场上不存在同种族怪兽的“剑斗兽”怪兽以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93708824,'十六夜蔷薇龙',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将“十六夜蔷薇龙”以外的1张记载有“黑蔷薇龙”卡名的卡加入手牌。\r\n②：此卡存在于墓地的状态下，自己场上表侧表示的“蔷薇龙”怪兽或植物族同步怪兽因战斗或对手的效果被破坏的情况下可以发动。将此卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93709215,'黑暗破坏神','此卡不可特殊召唤。此卡在１次的战斗阶段中可进行２次攻击。此卡攻击守备表示怪兽时，若其攻击力超过守备力，给予对手生命相当于该差值的战斗伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93713837,'编号24 龙血鬼 德古拉斯',replace(replace('等级6怪兽×2\r\n①：在每个自己・对手回合中1次，去除此卡的1个超量素材，以被从额外牌组特殊召唤的1只表侧表示怪兽为对象可以发动。将该怪兽改成里侧守备表示。\r\n②：表侧表示的此卡因对手的效果从场上离开、并被送至墓地的情况下，或者是被除外的情况下可以发动。将此卡以里侧守备表示特殊召唤。\r\n③：此卡反转的情况下发动。将场上的1张卡送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93715853,'魔神 马基纳','①：此卡对对手造成战斗伤害时可发动此卡。从我方的手牌・墓地特殊召唤１只通常怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93717133,'银河眼光子龙',replace(replace('①：此卡可解放自己场上的2只攻击力2000以上的怪兽来从手牌特殊召唤。\r\n②：在此卡与对手怪兽进行战斗的战斗步骤，以该1只对手怪兽为对象可以发动。将该对手怪兽与场上的此卡除外。以此效果除外的怪兽将在战斗阶段结束时放回场上，以此效果除外了超量怪兽的情况下，此卡的攻击力上升相当于将该超量怪兽除外时的超量素材的数量×500的数值。','\r',char(13)),'\n',char(10)),'对手怪兽和此卡从游戏中除外','出场方式为特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93717134,'银河眼光子龙',replace(replace('①：此卡可解放自己场上的2只攻击力2000以上的怪兽来从手牌特殊召唤。\r\n②：在此卡与对手怪兽进行战斗的战斗步骤，以该1只对手怪兽为对象可以发动。将该对手怪兽与场上的此卡除外。以此效果除外的怪兽将在战斗阶段结束时放回场上，以此效果除外了超量怪兽的情况下，此卡的攻击力上升相当于将该超量怪兽除外时的超量素材的数量×500的数值。','\r',char(13)),'\n',char(10)),'对手怪兽和此卡从游戏中除外','出场方式为特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93717135,'银河眼光子龙',replace(replace('①：此卡可解放自己场上的2只攻击力2000以上的怪兽来从手牌特殊召唤。\r\n②：在此卡与对手怪兽进行战斗的战斗步骤，以该1只对手怪兽为对象可以发动。将该对手怪兽与场上的此卡除外。以此效果除外的怪兽将在战斗阶段结束时放回场上，以此效果除外了超量怪兽的情况下，此卡的攻击力上升相当于将该超量怪兽除外时的超量素材的数量×500的数值。','\r',char(13)),'\n',char(10)),'对手怪兽和此卡从游戏中除外','出场方式为特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93723936,'白森之魔',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：解放自己场上的１只同步怪兽，以场上的１张表侧表示卡为对象可以发动。将该卡的效果直至回合结束时为止无效。解放“白森”同步怪兽来发动的情况下，进而可从自己墓地将１只幻想魔族怪兽特殊召唤。\r\n②：此卡为发动怪兽的效果被送至墓地的情况下可以发动。将此卡放置在自己场上。','\r',char(13)),'\n',char(10)),'无效','放置','是否要特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93724592,'机偶忍者 参参九','此卡能够攻击的场合必须攻击。攻击表示的此卡被选择为攻击对象时，将此卡变成守备表示。此卡反转时，选择１只场上的表侧表示怪兽并送入墓地。此外，此卡反转的回合，此卡可直接攻击对手玩家。','变成守备表示','送至墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93729065,'凶饿毒敌龙',replace(replace('←1 【灵摆】 1→\r\n①：每当场上的卡被送至墓地，每有1张就在此卡上放1个毒敌计数物。\n②：龙族・暗属性怪兽以外的场上怪兽的攻击力下降场上的毒敌计数物数量×200的数值。\n③：1回合1次，可将因战斗对自己造成的战斗伤害改成0。\r\n【怪兽效果】\r\n暗属性怪兽＋灵摆怪兽\n此卡名的①怪兽效果1回合仅可使用1次。\n①：以对手场上的1只表侧表示怪兽为对象可以发动。此卡直至结束阶段为止，获得与该怪兽原本卡名・效果相同的卡名・效果。然后，对象怪兽的攻击力・守备力下降500，效果无效化，给予对手500伤害。\n②：怪兽区域的此卡被破坏的情况下可以发动。将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'','','','是否要把战斗伤害变成0？','结束复制效果','','','','','','','','','','','');
INSERT INTO texts VALUES(93729896,'梦魇王座',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：作为此卡发动时的效果处理，可适用以下效果。\r\n●从牌组挑选１只攻击力和守备力为０的恶魔族怪兽，加入手牌或破坏。\r\n②：１回合１次，自己场上的表侧表示“尤贝尔”怪兽因效果从场上离开的情况下可以发动。从自己的牌组・墓地・除外状态，将原本等级比其中１只高１或低１的１只“尤贝尔”怪兽加入手牌。然后，可将该怪兽无视召唤条件特殊召唤。','\r',char(13)),'\n',char(10)),'是否选牌组的恶魔族怪兽？','加入手牌','是否把那只怪兽破坏？','是否特殊召唤？','','','','','','','','','','','','');
INSERT INTO texts VALUES(93730230,'先史遗产水晶外星人',replace(replace('等级３怪兽×２\r\n１回合１次，此卡被选择为攻击对象时，可移除此卡的１个超量素材并发动。此回合，此卡不会因战斗及卡牌效果而被破坏，因此卡战斗而产生的对我方的战斗伤害由对手代替承受。','\r',char(13)),'\n',char(10)),'伤害转移','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93730409,'真空鼬','①：此卡反转的情况下发动。此回合，对手不可发动魔法・陷阱卡。','发动限制','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93738004,'空牙团的孤高 萨吉塔','这个卡名的①的效果1个回合只可使用1次。①：这张卡特殊召唤成功的情况下可以发动。给对手数值为“空牙团的孤高 萨吉塔”以外的自己场上的“空牙团”怪兽种类×500伤害。②：只要这张卡存在于怪兽区域，对手就不可把这张卡以外的自己场上的“空牙团”怪兽作为效果的对象。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93747864,'沙漠之光','将存在于自己场上的怪兽全部变成表侧守备表示。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93749093,'马卡龙棉花糖',replace(replace('此卡牌名的效果１回合只可使用１次。\r\n①：此卡因战斗、效果被破坏的场合可发动。从我方手牌、牌组、墓地最多挑选２只除此卡以外的“马卡龙棉花糖”并特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93751476,'猛炎星－驯鹿明',replace(replace('①：此卡被使用于“炎星”同步怪兽的同步召唤并被送至墓地的情况下可以发动。从牌组将１张“炎舞”魔法卡放置在自己场上。\r\n②：在此卡因效果被破坏并被送至墓地的回合的结束阶段可以发动。从牌组将１只“猛炎星－驯鹿明”以外的等级４“炎星”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','放置','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93754402,'炎舞－洞明－',replace(replace('此卡名的卡１回合仅可发动１张，此卡名的②效果１回合仅可使用１次。\r\n①：作为此卡发动时的效果处理，可适用以下效果。\r\n●为使合计等级为仪式召唤的怪兽的等级以上，解放自己的手牌・场上的怪兽，从手牌将１只兽战士族的仪式怪兽仪式召唤。\r\n②：魔法与陷阱区域表侧表示的此卡被送至墓地的情况下，以自己墓地的１只“炎星”怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','是否仪式召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93775296,'反转再利用','①：可以我方墓地的最多２只反转怪兽作为对象并发动。以表侧守备表示或里侧守备表示特殊召唤该怪兽至对手场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93777634,'编号39 希望皇霍普升华',replace(replace('等级4怪兽×2\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡特殊召唤的情况下，以“编号39 希望皇霍普升华”以外的自己墓地的1只“编号”超量怪兽为对象可以发动。将该怪兽以守备表示特殊召唤。然后，可将此卡的超量素材全部作为该怪兽的超量素材。\r\n②：自己将怪兽超量召唤的情况下可以发动。从墓地将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'特殊召唤墓地超量怪兽','此卡从墓地特殊召唤','是否转移超量素材？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93788854,'彷徨的亡者','无法成佛，漫无目的四处游荡的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93816465,'零点守卫士','解放此卡可以发动。此回合自己的怪兽不会被战斗破坏，与对手怪兽战斗对自己造成的战斗伤害变为０。此效果在对手回合中也可以发动。','战斗伤害免疫','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93830681,'杀手皱鳃鲨','我方场上的鱼族、海龙族、水族怪兽被选择为攻击对象时，可将墓地的此卡从游戏中除外，并选择１只攻击怪兽发动。使被选择怪兽的攻击无效，直至下一个我方回合结束时，该攻击力下降５００点。“杀手皱鳃鲨”的效果１回合只可使用１次。','攻击无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93850652,'空牙团的剑士 比特','这个卡名的①②的效果1个回合各只可使用1次。①：自己主要阶段可以发动。从手牌特殊召唤“空牙团的剑士 比特”以外的1只“空牙团”怪兽。②：这张卡已存在于怪兽区域的状态下，且这张卡以外的“空牙团”怪兽被特殊召唤至自己场上的情况下可以发动。从牌组将“空牙团的剑士 比特”以外的1只“空牙团”怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93850690,'大灵峰相剑门','此卡名的①②效果１回合仅可各使用１次。①：以自己墓地的１只“相剑”怪兽为对象可以发动。将该怪兽特殊召唤。自己场上有同步怪兽存在的情况下，也可以１只幻龙族怪兽为对象作为代替。②：此卡被除外的情况下，以自己场上的１只“相剑”怪兽或幻龙族怪兽为对象可以发动。该怪兽的等级直至回合结束时为止上升或下降１。','','','等级上升','等级下降','','','','','','','','','','','','');
INSERT INTO texts VALUES(93854893,'宵星之自鸣天琴 丁吉尔苏',replace(replace('等级8怪兽×2\r\n自己1回合仅可特殊召唤“宵星之自鸣天琴 丁吉尔苏”1次，此卡也可重叠在自己场上的“自鸣天琴”连接怪兽上面来超量召唤。\r\n①：此卡特殊召唤的情况下，可从以下效果中选择1个发动。\r\n●将对手场上的1张卡送至墓地。\r\n●将自己除外状态的1只机械族怪兽作为此卡的超量素材。\r\n②：自己场上的卡将被战斗・效果破坏的情况下，作为代替可去除此卡的1个超量素材。','\r',char(13)),'\n',char(10)),'是否在「自奏圣乐」连接怪兽上面重叠来超量召唤？','对方卡送至墓地','补充超量素材','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93854894,'宵星之自鸣天琴 丁吉尔苏',replace(replace('等级8怪兽×2\r\n自己1回合仅可特殊召唤“宵星之自鸣天琴 丁吉尔苏”1次，此卡也可重叠在自己场上的“自鸣天琴”连接怪兽上面来超量召唤。\r\n①：此卡特殊召唤的情况下，可从以下效果中选择1个发动。\r\n●将对手场上的1张卡送至墓地。\r\n●将自己除外状态的1只机械族怪兽作为此卡的超量素材。\r\n②：自己场上的卡将被战斗・效果破坏的情况下，作为代替可去除此卡的1个超量素材。','\r',char(13)),'\n',char(10)),'是否在「自奏圣乐」连接怪兽上面重叠来超量召唤？','对方卡送至墓地','补充超量素材','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93860227,'优丽的灵镜姬',replace(replace('装备有怪兽卡的怪兽＋恶魔族怪兽卡\r\n仅可在将自己手牌・场上的上述卡送至墓地的情况下特殊召唤。\r\n此卡名的②效果1回合仅可使用1次。\r\n①：“优丽的灵镜姬”在自己场上仅可有1张以表侧表示存在。\r\n②：有怪兽为发动卡的效果而从手牌被送至墓地的情况下，可从以下效果中选择1个发动。\r\n●将其中1只视为攻击力上升500的装备魔法卡，装备于此卡。\r\n●自己抽1张。','\r',char(13)),'\n',char(10)),'发动效果','装备','抽牌','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93871599,'龙之引导唤笛',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：场上存在魔法师族怪兽的情况下可以发动。从牌组将1只等级5以上的龙族怪兽特殊召唤。对手场上存在2只以上怪兽的情况下，进而可再从牌组将1只特殊召唤的怪兽的同名怪兽特殊召唤。此回合，自己仅可特殊召唤龙族・魔法师族怪兽。\r\n②：在自己的主要阶段2，将在此回合被送至墓地的此卡除外可以发动。自己抽1张。','\r',char(13)),'\n',char(10)),'特殊召唤','抽牌效果','是否特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93871600,'龙之引导唤笛',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：场上存在魔法师族怪兽的情况下可以发动。从牌组将1只等级5以上的龙族怪兽特殊召唤。对手场上存在2只以上怪兽的情况下，进而可再从牌组将1只特殊召唤的怪兽的同名怪兽特殊召唤。此回合，自己仅可特殊召唤龙族・魔法师族怪兽。\r\n②：在自己的主要阶段2，将在此回合被送至墓地的此卡除外可以发动。自己抽1张。','\r',char(13)),'\n',char(10)),'特殊召唤','抽牌效果','是否特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93877990,'富炎星－应天鹅',replace(replace('兽战士族怪兽×２\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡特殊召唤的情况下可以发动。给予对手相当于自己场上“炎舞”魔法・陷阱卡的数量×２００的伤害。\r\n②：在自己・对手的战斗阶段，将自己场上的１张表侧表示的“炎舞”魔法・陷阱卡送至墓地，以对手场上的１张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93880808,'天位胜牌骑士',replace(replace('①：此卡存在于手牌・墓地的情况下，从手牌及自己场上的表侧表示怪兽中，将“王后骑士”、“卫兵骑士”、“国王骑士”各１只送至墓地可以发动。将此卡特殊召唤。\r\n②：此卡的攻击力上升相当于双方手牌数量×５００的数值。\r\n③：舍弃１张手牌可以发动。将种类（怪兽・魔法・陷阱）与所舍弃的卡相同的、对手场上的表侧表示卡全部破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93882364,'次代机・工作员','①：解放此卡可以发动。从手牌将１只“次代机”怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93889755,'杀人小丑','当场上的此卡由守备表示变为表侧攻击表示时，选择对手场上的１只怪兽令其回到持有者的手牌中。','对手1只怪兽回到手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93892436,'娱乐伙伴・秋千眼镜蛇',replace(replace('←2 【灵摆】 2→\r\n①：１回合１次，我方的怪兽给予对手战斗伤害时可发动。将对手牌组最上方的卡牌送入墓地。\r\n【怪兽效果】\r\n①：此卡可直接攻击。\n②：此卡进行攻击的场合，在战斗阶段结束时变成守备表示。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93895605,'仇恨炸弹','①：自己的恶魔族怪兽被选择为攻击对象时，将１只攻击怪兽与１只该攻击对象怪兽作为对象可以发动。破坏该攻击怪兽与该攻击对象怪兽，并给予对手被破坏的２只攻击怪兽的原本攻击力数值的伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93896655,'圣天树之幼精',replace(replace('等级４以下的植物族怪兽１只\r\n①：此卡以“圣种之地灵”作为素材被连接召唤至额外怪兽区域的情况下可以发动。从牌组将１张“圣蔓”魔法・陷阱卡加入手牌。\r\n②：此卡不会成为攻击对象（自己场上仅存在适用此效果的怪兽的状态下，对手的攻击变为对自己的直接攻击）。\r\n③：１回合１次，自己因战斗・效果受到伤害的情况下可以发动。依其数值恢复自己的LP，从额外牌组将１只“圣蔓”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','回复并特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93898740,'破械习合',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：以包含自己场上的“破械神”连接怪兽在内的、自己・对手场上的2只表侧表示怪兽为对象可以发动。仅以该2只怪兽为素材进行1只恶魔族连接怪兽的连接召唤。\r\n②：被放置的此卡因效果被破坏的情况下可以发动。从牌组将1只“破械”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'连接召唤','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93900406,'毒菇怪人','每次我方的准备阶段，给予控制者３００点伤害。可在我方结束阶段支付５００LP并发动。此卡的控制权转移给对手。','伤害','控制权转移','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93912845,'复活礼物','从我方墓地选择１只协调使其效果无效并特殊召唤。特殊召唤２只“礼物恶魔衍生物”（恶魔族、暗、星３、攻／守１５００）至对手场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93912846,'礼物魔衍生物','由「复活礼物」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93918159,'超越天翔',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：以自己或对手的墓地・除外状态的１只恐龙族怪兽为对象可以发动。将该怪兽特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93920420,'星遗物－星杖－','此卡名的②③效果1回合仅可各使用1次。①：通常召唤的此卡不会因与从额外牌组中被特殊召唤的怪兽的战斗而被破坏。②：此卡被送至墓地的情况下可以发动。从手牌将1只“星遗物”怪兽特殊召唤。③：将墓地的此卡除外，以1只被除外的自己的“自鸣天琴”怪兽为对象可以发动。将该怪兽特殊召唤。此效果发动后，直至回合结束时为止自己仅可特殊召唤暗属性怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93920745,'企鹅士兵','①：此卡反转的情况下，以场上最多2只怪兽为对象可以发动。将该怪兽放回手牌。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93927067,'帝王血战士',replace(replace('①：我方场上不存在有怪兽的场合，此卡可从手牌特殊召唤。\r\n②：此卡因战斗破坏对手怪兽的场合发动。此卡的攻击力上升５００。\r\n③：此卡因战斗被破坏的场合发动。破坏此卡怪兽的攻击力下降５００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93946239,'无之炼狱','①：自己的手牌为３张以上的情况下可以发动。自己抽１张。在此回合的结束阶段，将自己的手牌全部舍弃。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93953933,'无双九头蛇・轨道','此卡名的①②效果１回合仅可各使用１次。①：自己墓地存在４只以上的怪兽，且那些卡名全部不同的情况下，解放此卡可以发动。从自己的牌组上面翻开卡，数量为自己墓地的怪兽数量。怪兽被翻开２只以上，且那些卡名全部不同的情况下，将其中１只加入手牌。将剩余的卡以喜欢的顺序放回牌组上面。②：将墓地的此卡除外，以自己墓地的１只怪兽为对象可以发动。将该怪兽放回牌组最下面。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93966624,'魔法进击者','①：此卡存在于手牌的场合，可以我方及对手场上的各１张表侧表示魔法卡为对象发动。将该卡牌除外，并从手牌特殊召唤此卡。','卡片除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93969023,'黑钢龙','①：在自己的主要阶段以自己场上的１只“真红眼”怪兽为对象可以发动。从自己的手牌・场上，将此卡视为攻击力上升６００的装备卡，装备于该自己的怪兽。②：此卡从场上被送至墓地的情况下可以发动。从牌组将１张“真红眼”卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(93983867,'诡计箱','①：自己场上的“娱乐巫师”怪兽因战斗・效果被破坏并被送至墓地的情况下，以对手场上的１只怪兽为对象可以发动。自己直至结束阶段为止获得该怪兽的控制权。然后，挑选自己墓地的１只“娱乐巫师”怪兽，特殊召唤至对手场上。在此回合的结束阶段，以此效果特殊召唤的怪兽的控制权还给原本的持有者。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94004268,'亚马逊的剑士','此卡进行战斗所受到的对控制者的战斗伤害由对手承受。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94014327,'破械焰魔天 阎魔',replace(replace('包含“破械神”怪兽在内的怪兽2只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己的结束阶段，以在此回合被破坏的、自己墓地的最多2只恶魔族怪兽为对象可以发动。将该怪兽特殊召唤。只要以此效果特殊召唤的怪兽以表侧表示存在于自己场上，自己仅可特殊召唤恶魔族怪兽。\r\n②：场上的此卡将被战斗・效果破坏的情况下，作为代替可将自己或对手场上的1张表侧表示卡破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','','「破械焰魔天 阎魔」的效果特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94016752,'深渊之宣告者','此卡名的卡1回合仅可发动1张。①：支付1500LP，宣言种族和属性各1个可以发动。宣言的种族・属性的怪兽存在于对手场上的情况下，对手必须将1只该怪兽送至墓地。此回合，对手不可发动该怪兽及同名怪兽的怪兽效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94022093,'大肚海蛇','非常特别的海蛇。巨大的嘴和牙为其特征。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94042337,'暴风雨','会突然降下如同打翻水桶般的大雨。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94046012,'自鸣天琴・大炮卡农曲','此卡名的效果1回合仅可使用1次。①：将墓地的此卡除外可以发动。从手牌将1只“自鸣天琴・大炮卡农曲”以外的“自鸣天琴”怪兽特殊召唤。此效果发动后，直至回合结束时为止自己仅可特殊召唤暗属性怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94068856,'时间推移','选择我方场上１只冠有“命运女郎”之名的怪兽，直至回合结束时，该等级上升３级。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94073244,'空牙团的击手 东帕',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己的主要阶段可以发动。从手牌将“空牙团的击手 东帕”以外的1只“空牙团”怪兽特殊召唤。\r\n②：此卡存在于怪兽区域的状态下，有“空牙团”怪兽被特殊召唤至自己场上的情况下，以场上的1张表侧表示卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94076521,'水界的秘石－卡特林',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从手牌将此卡舍弃可以发动。此回合，自己在通常召唤之外，可在自己的主要阶段追加1次召唤1只地・水属性怪兽。\r\n②：此卡存在于墓地，自己场上存在地属性怪兽及水属性怪兽的情况下可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下将被除外。','\r',char(13)),'\n',char(10)),'','','使用「水界的秘石－卡特林」的效果召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94079037,'矿场鼹鼠','此卡１回合仅１次，不会因战斗被破坏。此卡作为兽族怪兽的同步召唤素材被送入墓地的场合，从我方牌组抽取１张卡牌。表侧表示的此卡因对手的卡牌效果从场上离场的场合，从游戏中被除外。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94081496,'黑亮的Z','对手场上仅有１只同步怪兽被特殊召唤时，将墓地中的此卡从游戏中除外可以发动。选择该同步怪兽破坏。此效果在对手回合中也可以发动。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94092230,'侵邪蚀 古雷滋','此卡不可特殊召唤。通常召唤此卡的场合，必须释放我方场上的３只冠有“侵邪蚀”之名的怪兽进行召唤。１回合１次，可支付一半的LP发动。破坏场上除此卡以外的所有卡牌。','把3只怪兽解放召唤','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94096018,'秘辣谍－迷雾女郎',replace(replace('①：此卡召唤・特殊召唤的情况下，宣言卡的种类（怪兽・魔法・陷阱）可以发动。将对手牌组最上面的卡给彼此确认，是所宣言的种类的卡的情况下，自己抽１张。\r\n②：在每个自己・对手回合中１次，以自己场上的１只“秘旋谍－花花公子”和对手场上的１只怪兽为对象可以发动。将该２只怪兽放回手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94096616,'武斗神器－大蛇','在我方主要阶段１，可将此卡从手牌送入墓地，并选择我方场上１只冠有“武斗神”之名的怪兽发动。此回合，被选择怪兽可直接攻击对手玩家。','直接攻击','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94103142,'绚岚之显现',replace(replace('①：可从以下效果中选择1个发动（此卡名的以下效果1回合仅可各选择1次）。\r\n●从牌组将1只“绚岚”怪兽送至墓地。\r\n●从自己牌组・墓地将1张“气旋”加入手牌。\r\n②：此卡因“气旋”的效果被破坏的情况下可以发动。将此卡放置在自己的魔法与陷阱区域。','\r',char(13)),'\n',char(10)),'发动','放置','送墓「绚岚」怪兽','检索「气旋」','','','','','','','','','','','','');
INSERT INTO texts VALUES(94113093,'涂yā本－此路不tōng',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己的恐龙族怪兽被选择为攻击对象时可以发动。将该攻击无效。然后，可从自己的墓地将１只“涂yā兽”怪兽特殊召唤。以此效果特殊召唤的怪兽不会因战斗被破坏，将在结束阶段被破坏。\r\n②：从墓地将不是在此回合被送至墓地的此卡除外可以发动。从牌组将１只等级５以上的恐龙族怪兽加入手牌。','\r',char(13)),'\n',char(10)),'是否从墓地特殊召唤？','','「涂yā本-挡路」效果适用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94119480,'终焉保卫者阿德琉斯',replace(replace('等级5怪兽×2\r\n①：1回合1次，去除此卡的1个超量素材，以对手场上的1张表侧表示卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94119974,'双头恐龙王','恐龙族中属於强力的卡。以２个头同时攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94130731,'超越恐龙 冻雪龙',replace(replace('协调＋协调以外的怪兽１只以上\r\n此卡名的③效果１回合仅可使用１次。\r\n①：此卡不会因战斗被破坏。\r\n②：只要此卡存在于怪兽区域，自己场上被从墓地特殊召唤的恐龙族怪兽不会因对手的效果被破坏，且对手不可将那些怪兽作为效果的对象。\r\n③：此卡被破坏的情况下可以发动。从自己的墓地将１只通常怪兽放回牌组。然后，可将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','是否将此卡特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94136469,'校验和龙',replace(replace('①：在对手怪兽攻击宣言时可以发动。从手牌将此卡特殊召唤。然后，依此卡的守备力的一半恢复自己的LP。\r\n②：攻击表示的此卡不会因战斗被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94141712,'武装龙闪电 LV7','此卡名的②③效果１回合仅可各使用１次。①：此卡只要存在于场上・墓地，卡名视为“武装龙 LV7”。②：从手牌将１只怪兽送至墓地可以发动。将场上的此卡送至墓地，从手牌・牌组将１只等级１０以下的“武装龙”怪兽特殊召唤。③：此卡为发动龙族怪兽的效果而被送至墓地的情况下可以发动。从牌组将１张“武装龙”卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94142993,'廷达三角 入侵者',replace(replace('此卡牌名的①②③效果１回合只可各使用１次。\r\n①：此卡反转的场合可发动。从牌组将１张“廷达三角”卡牌加入手牌。\r\n②：此卡召唤成功时可发动。从牌组将１张“廷达三角”卡牌送入墓地。\r\n③：此卡存在于墓地，且怪兽以里侧守备表示被特殊召唤至我方场上的场合可发动。以里侧守备表示从墓地特殊召唤此卡。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94145021,'抽牌小丑与封锁鸟','①：在自己・对手回合中，对手在抽牌阶段以外从牌组将卡加入手牌的情况下，从手牌将此卡送至墓地可以发动。此回合，双方不可从牌组将卡加入手牌。','检索限制','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94145022,'抽牌小丑与封锁鸟','①：在自己・对手回合中，对手在抽牌阶段以外从牌组将卡加入手牌的情况下，从手牌将此卡送至墓地可以发动。此回合，双方不可从牌组将卡加入手牌。','检索限制','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94145683,'燕巢','①：解放自己场上1只表侧表示的鸟兽族怪兽可以发动。将1只与解放的怪兽同等级的鸟兽族怪兽从牌组特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94151981,'超量装甲・鱼雷',replace(replace('等级３怪兽×２\r\n此卡名的②效果１回合仅可使用１次。\r\n①：没有超量素材的此卡不可攻击。\r\n②：去除此卡的２个超量素材可以发动。自己抽１张。\r\n③：只要此卡被装备中，适用以下效果。\r\n●装备怪兽进行战斗的情况下，直至伤害步骤结束时为止，对手不可发动卡的效果，且对手场上的表侧表示怪兽的效果无效化。\r\n●装备怪兽为超量怪兽的情况下，对手不可将装备怪兽作为效果的对象。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94156050,'颠倒眼镜','直至回合结束时，场上所有怪兽的攻击力减半。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94160895,'真龙凰 慈育圣母',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡存在于手牌的情况下可以发动。将此卡以外的、自己手牌・场上（表侧表示）的、包含风属性怪兽在内的2只怪兽破坏，将此卡特殊召唤，破坏了2只风属性怪兽的情况下，可从对手牌组上面将4张卡除外。\r\n②：此卡因效果被破坏的情况下可以发动。从牌组将风属性以外的1只幻龙族怪兽加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','加入手牌','是否把对方卡组的卡除外？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94163677,'无限手牌','只要此卡存在于场上，双方玩家的手牌张数就无限制。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94183877,'创王之影 洛普托尔','此卡名的③效果１回合仅可使用１次。①：“创王之影 洛普托尔”在自己场上仅可有１只以表侧表示存在。②：自己场上的“创王”怪兽的攻击力・守备力在对手回合期间上升１０００。③：在自己・对手的主要阶段，解放自己场上的１只“创王”怪兽可以发动。将１只与该怪兽卡名不同的等级９“创王”怪兽从牌组特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94185340,'献祭升阶',replace(replace('此卡名的卡１回合仅可发动１张。\r\n \r\n①：以自己场上的１只超量怪兽为对象可以发动。将该怪兽的２个超量素材除外，从额外牌组将１只阶级比该怪兽高１的超量怪兽特殊召唤。以此效果特殊召唤的怪兽此回合不可攻击。','\r',char(13)),'\n',char(10)),'','「献祭升阶」的效果特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94187078,'极超之辉龙机巧','此卡名的卡1回合仅可发动1张，发动此卡的回合中，自己仅可特殊召唤不可通常召唤的怪兽。①：从牌组将1只“龙机巧”怪兽特殊召唤。以此效果特殊召唤的怪兽将在结束阶段被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94192409,'强制脱出装置','①：以场上的1只怪兽为对象可以发动。将该怪兽放回手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94192410,'强制脱出装置','①：以场上的1只怪兽为对象可以发动。将该怪兽放回手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94203886,'我我我小子','①：自己场上有“我我我小子”以外的“我我我”怪兽存在的情况下，此卡可从手牌中特殊召唤。②：以此卡的①方法特殊召唤成功时，以自己场上的１只“我我我”怪兽为对象可以发动。将此卡的等级改成与该自己的“我我我”怪兽相同。发动此效果的回合中，自己无法进行战斗阶段。','等级变换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94207108,'海晶少女 奇迹心',replace(replace('水属性怪兽２只以上\r\n①：每次此卡与怪兽进行战斗的伤害计算时可以发动１次。将１张装备于此卡的自己的“海晶少女”怪兽卡特殊召唤。此卡不会因该战斗被破坏，因该战斗对自己造成的战斗伤害变为０。以此效果特殊召唤的怪兽将在结束阶段被视为装备魔法卡装备于此卡。\r\n②：此卡因对手被破坏的情况下可以发动。从自己的墓地将１只连接３以下的“海晶少女”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94212438,'通灵盘',replace(replace('此卡与４种“死之信息”卡齐聚于我方场上时，我方获得决斗获胜。\r\n①：在对方结束阶段时发动此效果。从手牌、牌组将１张“死之信息”卡按照“I”、“N”、“A”、“L”的顺序出示到我方的魔法与陷阱区域。②我方场上的“通灵盘”或“死之信息”卡从场上离开时，我方场上的“通灵盘”及“死之信息”全部被送入墓地。','\r',char(13)),'\n',char(10)),'让「死之信息」卡出现','请选择要出现在魔法与陷阱卡区域的卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94215860,'夜叉','此卡不可特殊召唤。召唤・反转此卡回合的结束阶段时此卡回到持有者的手牌中。召唤・反转此卡时，可选择对手场上１张魔法・陷阱卡回到持有者的手牌中。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94220427,'升阶魔法－紧急混沌之力',replace(replace('此卡名的②效果在决斗中仅可使用１次。\r\n①：以自己场上的１只阶级５以上的超量怪兽为对象可以发动。从额外牌组将１只比该自己的怪兽阶级高１的“混沌编号”怪兽或“混沌超量”怪兽重叠在对象怪兽上面，视为超量召唤来特殊召唤。\r\n②：此卡存在于墓地的状态下，阶级５以上的超量怪兽被特殊召唤至自己场上时可以发动。将此卡加入手牌。','\r',char(13)),'\n',char(10)),'加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94224458,'白色宿命的埃尔德里希尔','此卡名的①②效果1回合1次，仅可使用其中1个。①：从自己的手牌・墓地挑选1只不死族怪兽进行特殊召唤。自己场上不存在“埃尔德里奇”怪兽的情况下，用此效果只可特殊召唤“埃尔德里奇”怪兽。此卡发动后，直到回合结束时为止自己只可特殊召唤不死族怪兽。②：在自己主要阶段将墓地的此卡除外后可以发动。从牌组挑选1张“黄金乡”魔法・陷阱卡放置在自己场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94230224,'针球','反转：只要支付２０００LP，就可给予对手生命１０００点伤害。','反转','是否要使用「针球」的效果？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94243005,'混沌空间','每次有怪兽从游戏中除外时，每１只放置１个混沌计数物于此卡。１回合１次，通过从我方场上移除４个或以上的混沌计数物，选择１只等级与移除数量相同的怪兽，并特殊召唤至我方场上。场上的此卡因对手效果被送入墓地时，可从牌组将１只等级相当于在此卡上放置的混沌计数物数量或以下的光属性或暗属性怪兽加入手牌。','特殊召唤','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94253609,'元素吸收器','将此卡发动时，将手牌的１只怪兽从游戏中除外。只要此卡存在于场上，与被除外的怪兽同属性的对手怪兽不可进行攻击宣言。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94253655,'海造贼－布拉恩号',replace(replace('１只以上协调＋除协调以外的怪兽\r\n具此卡名的②效果１回合只能使用１次。\r\n①：我方场上其他恶魔族怪兽攻击力上升５００点。\r\n②：从手牌中弃掉１张“海造贼”卡，以对手场上１张魔法／陷阱卡为目标可发动。除外该卡。然后将１张“海造贼”怪兽从卡组加入手牌。此卡有“海造贼”卡装备的情况下，此效果在对手回合也能发动。','\r',char(13)),'\n',char(10)),'','是否从牌组把「海造贼」怪兽加入手牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94256039,'通天塔','只要此卡存在于场上，每当自己或对手发动魔法卡时，在此卡上放１个魔力计数物。在此卡上放第４个魔力计数物时破坏此卡，与此同时发动魔法卡的玩家会受到３０００点伤害。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94259633,'纳祭魔・阿尼玛',replace(replace('衍生物以外的等级1怪兽1只\r\n此卡名的①效果1回合仅可使用1次。\r\n①：以此卡的连接端的1只表侧表示怪兽为对象可以发动。将该表侧表示怪兽视为装备魔法卡装备于此卡（仅可以装备1只）。\r\n②：此卡的攻击力上升以此卡的效果装备的怪兽的攻击力数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94283662,'传送恶魔',replace(replace('①：1回合1次，在自己的主要阶段可以发动。从手牌将1只恶魔族怪兽舍弃，此卡的攻击力直至回合结束时为止上升500。\r\n②：自己场上的此卡被破坏并被送至墓地时，以自己除外状态的1只暗属性怪兽为对象可以发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'攻击上升','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94292987,'魔轰神加缪基',replace(replace('“魔轰神”协调＋协调以外的怪兽1只以上\r\n此卡名的①③效果1回合仅可各使用1次。\r\n①：此卡同步召唤的情况下可以发动。从手牌・牌组将1只“魔轰神”怪兽特殊召唤。\r\n②：只要此卡存在于怪兽区域，对手不可将自己场上其他的“魔轰神”同步怪兽作为效果的对象。\r\n③：此卡被送至墓地的情况下可以发动。自己依自己场上的“魔轰神”同步怪兽的数量抽牌。然后，挑选自己的1张手牌舍弃。','\r',char(13)),'\n',char(10)),'特殊召唤','','抽牌并丢弃','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94303232,'妨碍之星','我方场上的表侧攻击表示怪兽被改变成表侧守备表示的回合，仅限装备该怪兽。选择对手场上的１只怪兽。被选择怪兽不可攻击，也不可改变表示形式。因装备怪兽被破坏导致此卡被送入墓地时，将被选择对手怪兽从游戏中除外。','除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94317736,'远东秘泉乡',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：双方玩家１回合１次，在自己的主要阶段２可以发动。自己恢复５００LP，在此回合中适用以下效果。\r\n●自己怪兽的召唤・特殊召唤不会被无效化。\r\n●自己发动包含将怪兽特殊召唤的效果的怪兽的效果・魔法・陷阱卡的情况下，该发动不会被无效化。\r\n●放置在自己场上的魔法・陷阱卡不会成为对手效果的对象，不会因对手的效果被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94326720,'破灭预幻视',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：以自己墓地・除外状态的1只“无垢者 墨迪乌斯”为对象可以发动。将该怪兽特殊召唤。\r\n②：在自己的主要阶段将墓地的此卡除外，以自己场上的1只表侧表示怪兽为对象，宣言1～10的任意等级可以发动。将该怪兽的等级直至回合结束时为止改成宣言的等级。','\r',char(13)),'\n',char(10)),'特殊召唤','改变等级','请选择要改变的等级','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94331452,'音响战士 爵师鼓','①：１回合１次，宣言１个属性，以场上的１只“音响战士”怪兽为对象可以发动。该怪兽变为所宣言的属性。②：将墓地的此卡除外，宣言１个属性，以自己场上的１只“音响战士”怪兽为对象可以发动。该自己的“音响战士”怪兽变为所宣言的属性。','属性变换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94344242,'电子光虫－焊接网蜘蛛',replace(replace('以此卡作为超量召唤之素材的场合，只可使用于昆虫族怪兽的超量召唤。\r\n①：１回合１次，可以我方场上的１只表侧攻击表示怪兽为对象发动。将该怪兽变成守备表示，并从手牌以守备表示特殊召唤１只昆虫族、等级３怪兽。\r\n②：以场上的此卡作为素材超量召唤而来的怪兽获得以下效果。\r\n●此超量召唤成功的场合发动。对手场上的所有表侧表示怪兽，守备力变成０，且变成守备表示。','\r',char(13)),'\n',char(10)),'','全部变成守备表示（电子光虫－焊接网蜘蛛）','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94350039,'T.G.齿轮僵尸','此卡名的效果1回合仅可使用1次。①：以自己场上的1只“T.G.”怪兽为对象可以发动。从手牌将此卡特殊召唤。然后，对象怪兽的攻击力下降1000。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94365540,'廷达三角・底边守卫者',replace(replace('此卡名以①方法的特殊召唤１回合仅可进行１次。\r\n①：自己场上有里侧守备表示怪兽存在的情况下，可将此卡从手牌以守备表示特殊召唤。\r\n②：此卡已经存在于怪兽区域的状态下，怪兽被召唤・特殊召唤至对手的连接怪兽的连接端的情况下，解放此卡可以发动。从手牌・牌组将１只“廷达三角”怪兽以表侧攻击表示或里侧守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94374859,'推销员僵尸','我方场上的怪兽给予对手生命战斗伤害时，选择对方墓地的１张卡牌返回至持有者牌组的最下方。','返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94377247,'假面魔兽的仪式',replace(replace('用于召唤“假面魔兽 地狱修道士”。\r\n①：从我方的手牌・场上解放合计等级达到８以上的怪兽，来从手牌仪式召唤“假面魔兽 地狱修道士”。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94380860,'编号103 神葬零娘 诸神零',replace(replace('等级４怪兽×２\r\n①：在每个自己・对手回合中１次，去除此卡的１个超量素材，以对手场上１只攻击力不同于原本攻击力的攻击表示怪兽为对象可以发动。将该怪兽破坏，自己抽１张。','\r',char(13)),'\n',char(10)),'破坏抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94381039,'光道天使 基路比姆','①：此卡解放“光道”怪兽来上级召唤时，从自己的牌组上面将４张卡送至墓地，以对手场上的最多２张卡为对象可以发动。将该对手的卡破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94384775,'神鲜衍生物','由「海老须神鲜祭」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94384776,'神鲜衍生物','由「海老须神鲜祭」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94388754,'花札卫－胡枝子与猪－',replace(replace('此卡不可通常召唤。\r\n解放了我方场上１只除“花札卫－胡枝子与猪－”以外的“花札卫”怪兽的场合可特殊召唤。\r\n①：此卡特殊召唤成功的场合发动。我方从牌组抽取１张卡牌，并双方相互确认。该卡是“花札卫”怪兽的场合，可挑选对手场上的１只怪兽并破坏。若不是的场合，将该卡送入墓地。','\r',char(13)),'\n',char(10)),'抽牌','是否选对手场上1只怪兽破坏？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94392192,'怒刹帝利・食人魔','此卡名的②③效果１回合仅可各使用１次。①：自己场上不存在怪兽的情况下，此卡可从手牌中特殊召唤。②：在自己的主要阶段可以发动。从牌组将１张“怒刹帝利”陷阱卡加入手牌。③：此卡的攻击宣言时，或对手发动怪兽的效果的情况下可以发动。从对手的牌组上面翻开最多５张卡，从其中挑选１张，以里侧表示除外。将剩余的卡以原本的顺序放回牌组上面。','','','','请选择要翻开的卡的数量','','','','','','','','','','','','');
INSERT INTO texts VALUES(94395649,'超重禽属 鸡蛇矿',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡存在于手牌・墓地的情况下，解放自己场上的１只兽族・兽战士族・鸟兽族怪兽可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡离开场上的情况下，将其除外。\r\n②：从牌组将１只等级４以下的兽族・兽战士族・鸟兽族怪兽除外可以发动。直至结束阶段为止，此卡视为所除外怪兽的同名卡，变为相同的种族・属性・等级。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94410955,'百臂无形神 慑挪',replace(replace('“百臂无形”怪兽×3\r\n此卡名的①③效果1回合仅可各使用1次。\r\n①：在自己・对手的主要阶段可以发动。随机确认对手额外牌组的2张里侧卡。可从其中挑选1张特殊召唤至自己场上。\r\n②：此卡与怪兽进行战斗的情况下，该2只不会因该战斗被破坏。\r\n③：融合召唤的此卡因对手的效果被破坏的情况下可以发动。挑选对手场上任意数量的怪兽，获得其控制权。','\r',char(13)),'\n',char(10)),'特殊召唤','获得控制权','是否特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94412545,'机械变色龙','能够改变身体的颜色，将自己隐身在任何场所。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94415058,'星读的魔术师',replace(replace('←1 【灵摆】 1→\r\n①：自己的灵摆怪兽进行战斗的情况下，对手直至伤害步骤结束时为止，不可发动魔法卡。②：另一方自己的灵摆区域没有“魔术师”卡或“异色眼”卡存在的情况下，此卡的灵摆刻度变为４。\r\n【怪兽效果】\r\n①：１回合１次，自己场上仅１只表侧表示的灵摆怪兽因对手的效果返回自己手牌时可以发动。将１只该怪兽的同名怪兽从手牌特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94418111,'魔弹射手 狂野',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：只要此卡存在于怪兽区域，自己可在自己・对手回合中从手牌发动“魔弹”魔法・陷阱卡。\r\n②：在此卡的同一纵列发动了魔法・陷阱卡的情况下，以自己墓地的３张“魔弹”卡为对象可以发动。将该３张卡放回牌组。然后，自己抽１张。','\r',char(13)),'\n',char(10)),'','适用「魔弹射手 狂野」的效果来发动','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94423983,'同契恶魔术',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：此回合，双方不可特殊召唤和自身场上的怪兽相同种类（仪式・融合・同步・超量・连接）的怪兽。自己场上的仪式・融合・同步・超量・连接怪兽的其中任一都不存在2只以上的情况下，自己场上的所有仪式・融合・同步・超量・连接怪兽的攻击力上升500。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94425169,'元素之泉','场上的怪兽返回至持有者手牌时，我方回复５００LP。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94431029,'精准夺取',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：双方分别从自身的额外牌组挑选１张里侧表示卡。双方确认该卡，种类相同（融合・同步・超量・连接）的情况下，将对手所挑选的卡送至墓地，将自己所挑选的卡特殊召唤。进而原本种族・属性相同的情况下，对手失去相当于自身所挑选的卡的攻击力数值的LP。种类不同的情况下，将自己所挑选的卡送至墓地，对手将自身所挑选的卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94432298,'壳醒的炼狱',replace(replace('①：１回合１次，在自己的准备阶段可以发动。从牌组将最多２只“狱炎机”怪兽送至墓地。\r\n②：自己场上存在“狱炎机”怪兽以外的怪兽的情况下，此卡将被送至墓地。','\r',char(13)),'\n',char(10)),'是否现在使用此卡的效果？','发动同时使用效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94445733,'破坏之神碑',replace(replace('此卡名的卡１回合仅可发动１张。①：可从以下效果中选择１个发动。此卡发动后，跳过下一个自己的战斗阶段。\r\n●以对手场上１张魔法・陷阱卡为对象可以发动。将该卡破坏。然后，从对手的牌组上面将４张卡除外。\r\n●从额外牌组将１只“神碑”怪兽特殊召唤至额外怪兽区域。','\r',char(13)),'\n',char(10)),'魔陷破坏','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94446564,'情侣装','①：双方确认双方牌组最上面的卡，该两张卡种类相同（怪兽・魔法・陷阱）的情况下，双方将该卡加入手牌。不同的情况下，双方将该卡除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94454495,'星际仙踪－魔鞋骑手',replace(replace('①：此卡召唤・特殊召唤成功的情况下，以场上１张魔法・陷阱卡为对象可以发动。将该卡破坏。\r\n②：此卡因战斗・效果被破坏并被送至墓地的情况下，将墓地的此卡除外可以发动。从牌组将１只等级４以下的“星际仙踪”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'魔法·陷阱卡破坏','从牌组把「星际仙踪」怪兽特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94463200,'血之刻印','选择自己场上的１只名字带有“恶魔”的怪兽可以发动。对手玩家也要支付选择的怪兽在准备阶段支付的LP。此卡从场上离开时，破坏选择的怪兽。选择的怪兽从场上离开时，破坏此卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94467314,'恶怪死之雨',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：自己场上存在攻击力2000以上的水族怪兽的情况下可以发动。将水族怪兽以外的、场上的怪兽全部送至墓地。\r\n②：被放置的此卡因效果被破坏的情况下可以发动。将此卡放置在自己场上。','\r',char(13)),'\n',char(10)),'发动','放置','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94484482,'摆脱召唤','对手召唤、反转召唤、特殊召唤怪兽成功时可发动。从手牌以守备表示特殊召唤１只等级４或以下的怪兽。此效果特殊召唤的怪兽在结束阶段时返回至持有者手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94503794,'漆梏之喰兽 凯尔泽布斯',replace(replace('等级7怪兽×2只以上\r\n此卡名的③效果1回合仅可使用1次。\r\n①：此卡的攻击力上升此卡的超量素材数量×700的数值。\r\n②：通常・速攻魔法卡发动时可以发动（同一连锁上最多1次）。将场上的该卡作为表侧表示的此卡的超量素材，此卡不受该发动的效果影响。\r\n③：在自己・对手的结束阶段可以发动。将此卡所持有的超量素材中的1张魔法卡放置在自己场上。','\r',char(13)),'\n',char(10)),'获取超量素材','放置','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94515289,'冰结的菲兹杰拉德',replace(replace('暗属性协调＋协调以外的兽族怪兽1只\r\n①：此卡攻击的情况下，对手直至伤害步骤结束时为止，不可发动魔法・陷阱卡。\r\n②：此卡因战斗被破坏并被送至墓地时，舍弃1张手牌可以发动（此效果在自己场上不存在怪兽的情况下才能发动和处理）。将此卡以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94535485,'牵手魔人',replace(replace('①：只要此卡存在于怪兽区域，对手不可将其他怪兽选择为攻击对象。\r\n②：此卡的守备力上升相当于自己场上此卡以外的表侧守备表示怪兽原本守备力合计的数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94538053,'极限战士','此卡攻击对手怪兽的场合，在伤害步骤期间攻击力上升４００点。此卡因战斗破坏对手怪兽时，直至下一个我方准备阶段时，此卡的等级变为２，原本的攻击力、守备力减半。','等级攻守变换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94553671,'魔女工艺・守护圣者',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：以自己墓地・除外状态的1只魔法师族怪兽为对象可以发动。将该怪兽放回牌组，从牌组将1张“魔女工艺”魔法卡加入手牌。\r\n②：从墓地将不是在此回合被送至墓地的此卡除外，以任意数量的自己除外状态的“魔女工艺”魔法卡为对象可以发动（同名卡最多1张）。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94561645,'反击之门','①：在对手怪兽的直接攻击宣言时可发动。使该攻击无效，我方从牌组抽取１张卡牌。抽取的该卡牌是怪兽的场合，可以表侧攻击表示通常召唤该怪兽。','是否表侧攻击表示通常召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94566432,'帝王龙','“护城翼龙”＋“妖精龙”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94568601,'暴君龙','对手场上有怪兽存在的场合，此卡可在战斗阶段中额外进行１次攻击。只要此卡以表侧表示存在于场上，以此卡为对象的陷阱卡的效果将无效并破坏。以其他卡牌的效果从墓地特殊召唤此卡的场合，该玩家必须解放存在于我方场上的１只龙族怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94573223,'甲虫装机 巨大螳螂',replace(replace('此卡牌名的③效果１回合只可使用１次。\r\n①：可以我方场上１只“甲虫装机”怪兽为对象发动。从手牌将此卡视为装备卡装备该我方的“甲虫装机”怪兽。\r\n②：将此卡视为装备卡装备的怪兽，其原本攻击力变成２４００。\r\n③：被装备于怪兽的此卡被送入墓地的场合，可以我方墓地的１只除“甲虫装机 巨大螳螂”以外的“甲虫装机”怪兽为对象发动。特殊召唤该怪兽。','\r',char(13)),'\n',char(10)),'装备','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94585852,'万魔殿－魔鬼的巢穴－','冠有“恶魔”之名的怪兽在准备阶段可以不必支付LP。当冠有“恶魔”之名的怪兽卡因战斗以外的方式而被破坏送入墓地时，可从牌组中选择１张等级低于该卡，且冠有“恶魔”之名的怪兽卡加入到手牌中。','检索','是否使用「万魔殿－魔鬼的巢穴－」的效果不支付基本分？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94599451,'魔导研究所',replace(replace('①：自己场上的表侧表示的“魔导兽”灵摆怪兽卡每次因战斗・效果被破坏，在此卡上放2个魔力计数物。\r\n②：1回合1次，去除自己场上的任意数量的魔力计数物可以发动。从自己牌组・额外牌组（表侧）将1只等级与去除数量相同的、能放魔力计数物的怪兽加入手牌。\r\n③：场上此卡将被效果破坏的情况下，作为代替可去除此卡的1个魔力计数物。','\r',char(13)),'\n',char(10)),'','请选择要取除的计数物的数量','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94620082,'转生炎兽 狐曦','1个回合1次，这个卡名的①②的效果只能使用其中任意1个。①：这张卡召唤成功时可以发动。从自己牌组上面把3张卡翻开。可以从其中挑选1张“转生炎兽”卡加入手牌。剩下的卡放回牌组。②：这张卡存在于墓地，且场上有表侧表示的魔法・陷阱卡存在的情况下，从手牌中扔掉1张“转生炎兽”卡后可以发动。特殊召唤这张卡。之后，可以挑选场上1张表侧表示的魔法・陷阱卡进行破坏。','','是否选卡加入手牌？','','是否选魔法·陷阱卡破坏？','','','','','','','','','','','','');
INSERT INTO texts VALUES(94622638,'A次代机・充能','①：只要此卡存在于怪兽区域，属性与此卡相同的、自己场上的其他怪兽的攻击力上升５００。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94626050,'鱼雨','场上表侧表示的鱼族、海龙族、水族怪兽从游戏中被除外时可发动。从手牌特殊召唤１只等级３或以下的鱼族、海龙族、水族怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94626871,'淘气仙星・甜蜜魔鬼',replace(replace('“淘气仙星”怪兽2只\r\n①：只要此卡存在于怪兽区域，此卡连接端的怪兽每次因战斗・效果被破坏并被送至墓地，给予对手200伤害。②：对手每次因“淘气仙星”怪兽的效果受到伤害发动。对手场上的所有表侧表示怪兽的攻击力直至回合结束时为止，下降相当于此卡连接端的怪兽数量×200的数值。','\r',char(13)),'\n',char(10)),'下降攻击力','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94634433,'紧急同调','①：在我方、对手的战斗阶段可发动。同步召唤１只同步怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94641726,'岚忌龙 迪斯托比姆',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的②③效果1回合仅可各使用1次。\r\n①：对手不可将场上的此卡作为效果的对象。\r\n②：从自己墓地将任意数量的、不可通常召唤的暗属性怪兽除外可以发动（对手场上的卡的数量多于自己场上的卡的情况下，此效果在对手回合中也可以发动）。依所除外的数量，将对手场上的卡除外。\r\n③：此卡被送至墓地的情况下可以发动。将自己除外状态的1只龙族怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','除外效果','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94655777,'暗征龙－朦胧',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：从手牌将1只龙族或暗属性的怪兽与此卡舍弃，以“暗征龙－朦胧”以外的、自己的除外状态的、属性不同的2只“征龙”怪兽为对象可以发动。将该怪兽特殊召唤。以此效果特殊召唤的怪兽在此回合不可攻击。\r\n②：从自己墓地将1只龙族或暗属性的怪兽和此卡除外，以自己墓地的1只“凶征龙－日蚀”为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94656263,'影蜥蜴','此卡不可通常召唤，以此卡的效果可特殊召唤。此卡不可作为同步素材。①：自己成功召唤等级４怪兽时可以发动。从手牌将此卡特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94661166,'逼近的机械',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：从自己牌组・墓地将记载有“钢铁化・强化反射装甲”卡名的１只怪兽或１张“钢铁化”陷阱卡加入手牌。\r\n②：自己场上存在“钢铁化”陷阱卡的情况下，将墓地的此卡除外，以对手场上的１只守备表示怪兽为对象可以发动。将该怪兽改成表侧攻击表示。','\r',char(13)),'\n',char(10)),'加入手牌','改变表示形式','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94662235,'弯曲命运','我方场上的表侧表示怪兽仅是冠有“命运女郎”之名怪兽的场合，可发动。使魔法、陷阱卡的发动、怪兽召唤中任１项无效，并将该卡从游戏中除外。此回合的结束阶段时，将以此效果从游戏中除外的卡牌返回至持有者手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94664694,'疯狂恶魔',replace(replace('①：此卡攻击守备表示怪兽的场合，若其攻击力超过守备力，给予对手生命相当于该差值的战斗伤害。\r\n②：攻击表示的此卡被选择为攻击对象的场合发动。将此卡变成守备表示。','\r',char(13)),'\n',char(10)),'变成守备表示','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94666032,'复仇尸者・诞生','“仇尸”仪式怪兽的降临所必需。①：为使合计等级为仪式召唤的怪兽的等级以上，解放自己手牌・场上的怪兽，或将自己墓地的不死族怪兽除外作为解放的代替，从自己的手牌・墓地将１只“仇尸”仪式怪兽仪式召唤。②：自己场上的“复仇尸者・屠戮者”将被战斗・效果破坏的情况下，可将墓地的此卡除外作为代替。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94667532,'机械犬小栗子','场上的此卡因战斗被破坏并送往墓地时，双方受到１０００点伤害。场上的此卡因战斗以外的方式被破坏并送往墓地时，给予对手LP１０００点伤害。','双方伤害','对手伤害','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94670654,'兽之忍者－貘',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：用抽牌以外的方法将此卡加入手牌的情况下可以发动。将此卡特殊召唤。\r\n②：此卡特殊召唤・反转的情况下，从自己墓地及自己的魔法与陷阱区域的表侧表示卡中，以“兽之忍者－貘”以外的１张“忍者”卡或“忍法”卡为对象可以发动。将该卡放回持有者的手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94675535,'拉巴斯','动作迅敏的鸟怪物。会用细长的手臂绞杀敌人。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94677445,'星杯神子 伊布',replace(replace('协调＋协调以外的怪兽1只以上\r\n要同步召唤此卡的情况下，可将自己场上的1只“星杯”通常怪兽视为协调。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡同步召唤的情况下可以发动。从牌组将1张“星遗物”卡加入手牌。\r\n②：同步召唤的此卡被送至墓地的情况下可以发动。从自己牌组・墓地将“星杯神子 伊布”以外的1只“星杯”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'牌组检索','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94677446,'星杯神子 伊布',replace(replace('协调＋协调以外的怪兽1只以上\r\n要同步召唤此卡的情况下，可将自己场上的1只“星杯”通常怪兽视为协调。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡同步召唤的情况下可以发动。从牌组将1张“星遗物”卡加入手牌。\r\n②：同步召唤的此卡被送至墓地的情况下可以发动。从自己牌组・墓地将“星杯神子 伊布”以外的1只“星杯”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'牌组检索','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94681654,'羽风攻击','可将我方场上１只表侧表示的冠有“黑羽”之名的怪兽返回至持有者牌组并发动。从牌组将１只冠有“黑羽”之名的怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94689206,'积木龙',replace(replace('此卡不可通常召唤。\r\n仅可在将自己手牌・墓地的3只地属性怪兽除外的情况下，从手牌・墓地特殊召唤。\r\n此卡名的②效果1回合仅可使用1次。\r\n①：只要此卡存在于怪兽区域，自己场上的岩石族怪兽不会被战斗以外的方法破坏。\r\n②：此卡从场上被送至墓地的情况下可以发动。从牌组将合计等级为8的、最多3只岩石族怪兽加入手牌。','\r',char(13)),'\n',char(10)),'加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94689635,'紫光之宣告者','①：对手发动陷阱卡时，从手牌将此卡和１只天使族怪兽送至墓地可以发动。将该发动无效并破坏。','对手的陷阱卡的发动无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94693857,'文具博格００１','①：此卡的攻击力・守备力上升相当于自己场上机械族怪兽数量×５００的数值。②：此卡存在于墓地，２只以上机械族怪兽同时被特殊召唤至场上的情况下可以发动。将此卡特殊召唤。','特殊召唤','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94703021,'集群拥塞器',replace(replace('此卡牌名的①效果１回合只可使用１次。\r\n①：我方场上不存在有连接怪兽，且此卡召唤、特殊召唤成功的场合可发动。特殊召唤１只“拥塞器衍生物”（电子界族・暗・星１・攻／守０）至我方场上。\r\n②：我方连接怪兽被攻击的战斗步骤，可将该连接怪兽与墓地的此卡除外并发动１次。特殊召唤“拥塞器衍生物”至我方场上，其数量最多为对手场上之连接怪兽数量。','\r',char(13)),'\n',char(10)),'是否继续特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94703022,'拥塞器衍生物','由“集群拥塞器”的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94716515,'尖刺神的杀虫剂','破坏场上所有昆虫族怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94722358,'码丽丝＜序＞MTP－07',replace(replace('此卡名的卡1回合仅可发动1张。\r\n此卡也可通过将自己场上的1只表侧表示“码丽丝”怪兽除外，来在放置的回合发动。\r\n①：从牌组将1只“码丽丝”怪兽加入手牌。自己场上存在“码丽丝”连接怪兽的情况下，进而可将场上的1张卡除外。','\r',char(13)),'\n',char(10)),'','','适用「码丽丝＜序＞MTP－0７」的效果来发动','是否把卡除外？','','','','','','','','','','','','');
INSERT INTO texts VALUES(94730900,'焰圣骑士－莫吉斯','此卡名的①②效果１回合仅可各使用１次。①：此卡被送至墓地的情况下，从自己墓地的卡及自己被除外的卡中，将此卡以外的战士族・炎属性怪兽或“圣剑”卡合计３张放回牌组可以发动。自己从牌组抽１张。②：此卡存在于墓地的情况下，以自己场上的１只战士族怪兽为对象可以发动。将此卡视为装备卡装备于自己的该怪兽。③：此卡装备的怪兽不会因战斗被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94739788,'洗脑解除','只要此卡存在于场上，场上所有怪兽的控制权返回至原持有者。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94749594,'古代龟之诅咒',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从自己手牌・墓地将1只不死族怪兽除外可以发动。从牌组将1只不死族怪兽送至墓地。\r\n②：自己的不死族怪兽因战斗被破坏时，将墓地的此卡除外可以发动。从牌组将1只守备力2000以下的不死族怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'送至墓地','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94766498,'先史遗产 阿兹提克面具魔像','我方回合，我方发动冠有“先史遗产”之名的魔法卡的场合。此卡可从手牌特殊召唤。我方场上只可有１只“先史遗产 阿兹提克面具魔像”以表侧表示存在。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94770493,'加倍机会','①：怪兽的攻击被无效时，以该１只怪兽为对象可以发动。此战斗阶段中，该怪兽可再攻击仅１次。该怪兽以此效果攻击的伤害步骤期间，该怪兽的攻击力变为两倍。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94772232,'死之信息“A”','此卡只可通过“通灵盘”的效果上场。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94773007,'地雷蜘蛛','此卡进行攻击宣言时，投掷硬币猜正反面。猜错的场合，我方的LP失去一半。','投掷硬币','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94784213,'威风魔灵・九尾狐狸',replace(replace('←2 【灵摆】 2→\r\n【怪兽效果】\r\n此卡名的①怪兽效果１回合仅可使用１次。\n①：此卡召唤・特殊召唤时可以发动。从牌组将１张“威风魔灵”陷阱卡加入手牌。\n②：只要此卡存在于怪兽区域，此卡不会被对手的效果破坏，对手不可将此卡作为效果的对象。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94793422,'心眼之矛','装备怪兽给予对手玩家战斗伤害的场合，该战斗伤害的数值变为１０００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94798725,'超弩级军贯－海胆型二号舰',replace(replace('等级５怪兽×２\r\n此卡名的①效果１回合仅可使用１次。①：此卡超量召唤成功的情况下可以发动。根据作为该超量召唤的素材的怪兽，适用以下效果。\r\n●“舍利军贯”：自己从牌组抽１张。\r\n●“海胆军贯”：此卡可直接攻击。\r\n②：在每个自己的主要阶段及对手的战斗阶段１次，以对手场上的表侧表示卡为对象可以发动，数量最多为从额外牌组被特殊召唤的自己的“军贯”怪兽的数量。将该卡的效果无效。','\r',char(13)),'\n',char(10)),'按素材种类适用效果','对方卡的效果无效','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94801854,'不知火的隐者','此卡名的①②效果１回合仅可各使用１次。①：解放自己场上的１只不死族怪兽可以发动。从牌组将１只守备力０的不死族协调特殊召唤。②：此卡被除外的情况下，以“不知火的隐者”以外１只自己被除外的“不知火”怪兽为对象可以发动。将该怪兽特殊召唤。场上存在“不知火流 转生之阵”的情况下，可将此效果的对象改成２只。','特殊召唤','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94804055,'火焰壁','对手宣言直接攻击时，将自己的墓地中的１只炎族怪兽从游戏中除外可以发动。将该攻击无效。此卡的控制者在每次自己的准备阶段支付５００LP。或不支付５００LP，将此卡破坏。','攻击无效','是否现在使用「火焰壁」的效果？','是否要支付500基本分维持「火焰壁」？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94807487,'希望剑斩',replace(replace('仅限装备“希望皇霍普”怪兽。\r\n①：装备怪兽不会因效果被破坏。\r\n②：只要此卡存在于魔法与陷阱区域，每次怪兽的攻击变成无效，在此卡放置１个霍普剑计数物。装备怪兽的攻击力上升此卡的霍普剑计数物数量×５００。\r\n③：我方场上的装备怪兽移除超量素材并发动效果的场合，此卡可被视为１个移除的×素材。','\r',char(13)),'\n',char(10)),'放置1个希望剑计数物','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94820406,'黑暗结合','①：将自己的手牌・场上的怪兽作为融合素材，将1只恶魔族的融合怪兽融合召唤。此回合，对手不可将以此效果特殊召唤的怪兽作为效果的对象。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94821366,'惊乐园的经理人＜∀阿尔历奇诺＞',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：陷阱卡发动的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：对手将怪兽召唤・特殊召唤成功的情况下，以该１只对手怪兽为对象可以发动。从牌组挑选１张“游乐设施”陷阱卡，装备于该对手怪兽。\r\n③：１回合１次，从自己的墓地将任意数量的“游乐设施”陷阱卡除外，依其数量以对手场上的卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'此卡特殊召唤','装备','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94845226,'魔轰神兽路比拉达','此卡被选择为攻击对象时，可从手牌舍弃１张冠有“魔轰神”之名的怪兽并发动。使该攻击无效。','攻击无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94845588,'圣徒蓟花',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：将额外牌组的１只“圣徒”融合怪兽出示给对手，其等级每有４，就从自己手牌・场上将１张“罪宝”卡送至墓地（里侧表示卡则翻开确认）。然后，将所出示的怪兽视为融合召唤特殊召唤。\r\n②：此卡存在于墓地的情况下，以自己场上・墓地的１只“圣徒”怪兽为对象可以发动。将该怪兽放回牌组，将此卡加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','回到手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94853057,'闪光的放逐者','只要此卡以表侧表示存在于场上，被送往墓地的卡将不去墓地而是从游戏中除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94861297,'盘查','①：在对手怪兽攻击宣言时可以发动。确认对手的所有手牌，其中有怪兽卡的情况下，将其攻击无效。然后，自己从对手的手牌挑选１只怪兽舍弃。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94878265,'摩迦','此卡因战斗被破坏并送入墓地时可发动。选择我方墓地１只等级４的兽族怪兽并加入手牌。','返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94886282,'光之援军','①：从自己的牌组上面将３张卡送至墓地可以发动。从牌组将１只等级４以下的“光道”怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94905343,'牛头人马兽','“牛头魔人”＋“人马兽”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94919024,'月光红狐','①：此卡因效果被送至墓地的情况下，以对手场上的１只表侧表示怪兽为对象可以发动。将该怪兽的攻击力直至回合结束时为止改成０。②：以自己场上的“月光”怪兽为对象的的魔法・陷阱・怪兽的效果发动时，将墓地的此卡除外可以发动。将该发动无效，双方玩家恢复１０００LP。','特殊召唤的怪兽全部破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94933468,'Vain－背叛的嘲笑',replace(replace('对手的超量怪兽攻击宣言时，以该1只怪兽为对象可以发动此卡。\r\n①：对象怪兽不可攻击，效果无效化。对象怪兽从场上离开时此卡将被破坏。\r\n②：在对手的结束阶段发动（此效果在对象怪兽存在于场上的情况下才会发动和处理）。从对手的牌组上面将3张卡送至墓地。','\r',char(13)),'\n',char(10)),'牌组破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94937430,'临时收入',replace(replace('①：只要此卡存在于魔法与陷阱区域，每次我方额外牌组加入卡牌，放置１个魔力计数物在此卡（最多可放３个）。\r\n②：可将放置有３个魔力计数物的此卡送入墓地并发动。我方从牌组抽取２张卡牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94940436,'磁力召唤圆 LV2','从手牌特殊召唤１只等级２以下的机械族怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94942656,'隐形蜇拉肯・碟状幼体',replace(replace('水属性等级４怪兽×２\r\n①：１回合１次，在自己・对手的主要阶段可以发动。将对手场上的１只水属性怪兽破坏。\r\n②：以“编号”超量怪兽的效果特殊召唤的此卡被破坏的情况下可以发动。从自己的墓地将其他“隐形蜇拉肯”怪兽特殊召唤，数量最多为此卡原先持有的超量素材的数量。进而该特殊召唤的怪兽可各从自己的墓地将最多１只水属性怪兽作为其超量素材。','\r',char(13)),'\n',char(10)),'水属性怪兽破坏','','是否为此怪兽补充超量素材？','「编号」超量怪兽的效果特殊召唤','','','','','','','','','','','','');
INSERT INTO texts VALUES(94944637,'魔族召唤师',replace(replace('此卡存在于墓地或以表侧表示存在于场上的场合，将被视为通常怪兽。以通常召唤的方式再次召唤场上表侧表示的此卡，此卡将视为效果怪兽并获得以下效果。\r\n●１回合１次，可在我方的主要阶段时发动此卡。从手牌或者我方・对手墓地中特殊召唤１只恶魔族怪兽。当此卡离开场上时，破坏所有以此效果特殊召唤的恶魔族怪兽。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94950218,'反转破坏者','仅可以装备在具“希望皇霍普”之名的怪兽上。装备怪兽进行攻击宣告时，选择对手场上的１张魔法或陷阱卡并将其破坏。对手不能对应此效果的发动来发动魔法和陷阱卡。','魔陷破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94973028,'幻兽机 倾翼小马','①：自己场上有其他“幻兽机”怪兽存在、此卡特殊召唤成功的情况下发动。将２只“幻兽机衍生物”（机械族・风・星３・攻／守０）特殊召唤至自己场上。②：此卡的等级上升相当于自己场上“幻兽机衍生物”等级合计的数值。③：只要自己场上有衍生物存在，此卡不会因战斗・效果被破坏。④：１回合１次，解放自己场上的２只衍生物，以对手场上的１张卡为对象可以发动。将该对手的卡破坏并除外。','特殊召唤Token','破坏并除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94973029,'幻兽机衍生物','由名称中带有“幻兽机”的怪兽等的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94977269,'神影依・米德拉什',replace(replace('“影依”怪兽＋暗属性怪兽\r\n此卡从额外牌组仅可通过融合召唤来特殊召唤。\r\n①：场上的此卡不会因对手的效果被破坏。\r\n②：只要此卡存在于怪兽区域，在此期间，双方1回合仅可特殊召唤怪兽1次。\r\n③：此卡被送至墓地的情况下，以自己墓地的1张“影依”魔法・陷阱卡为对象可以发动。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94977270,'神影依・米德拉什',replace(replace('“影依”怪兽＋暗属性怪兽\r\n此卡从额外牌组仅可通过融合召唤来特殊召唤。\r\n①：场上的此卡不会因对手的效果被破坏。\r\n②：只要此卡存在于怪兽区域，在此期间，双方1回合仅可特殊召唤怪兽1次。\r\n③：此卡被送至墓地的情况下，以自己墓地的1张“影依”魔法・陷阱卡为对象可以发动。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94979322,'黑炎之剑士',replace(replace('此卡名的①③效果1回合仅可各使用1次。\r\n①：从额外牌组将1只“炎之剑士”或记载有该卡名的怪兽送至墓地可以发动。从手牌将此卡特殊召唤。此回合，自己仅可用战士族怪兽进行攻击宣言。\r\n②：因此卡的战斗对自己造成的战斗伤害变为0。\r\n③：在自己・对手回合中，解放此卡可以发动。从牌组将等级6以外的、记载有“炎之剑士”卡名的1只怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'此卡特殊召唤','','从牌组特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94982447,'真龙骑将 德利亚Ⅲ世',replace(replace('要以表侧表示上级召唤此卡的情况下，可解放自己场上的永续魔法・永续陷阱卡来作为怪兽的代替。\r\n①：上级召唤的表侧表示的此卡从场上离开的情况下可以发动。从牌组将1只“真龙”怪兽以守备表示特殊召唤。\r\n②：只要此卡存在于怪兽区域，场上其他的“真龙”怪兽不会因对手的效果被破坏，且对手不可将其作为效果的对象。','\r',char(13)),'\n',char(10)),'解放魔法·陷阱卡上级召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(94997874,'圣占卜姬塔罗蕾',replace(replace('由“圣占术的仪式”降临。\r\n“圣占卜姬塔罗蕾”的①②效果１回合只可使用其中任一效果１次，在对手回合也可发动。\r\n①：可以场上的１只里侧表示怪兽为对象发动。将该怪兽变成表侧攻击表示。\r\n②：可以场上的１只表侧表示怪兽为对象发动。将该怪兽变成里侧守备表示。\r\n③：在我方结束阶段可发动。从我方手牌、墓地挑选１只反转怪兽并以里侧守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'变成表侧攻击表示','变成里侧守备表示','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95004025,'真龙导士 威风凛凛 少女',replace(replace('要以表侧表示上级召唤此卡的情况下，可解放自己场上的永续魔法・永续陷阱卡来作为怪兽的代替。\r\n①：此卡是被上级召唤的情况下，1回合1次，对手发动魔法・陷阱・怪兽的效果时可以发动。从牌组将1只“真龙”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'解放魔法·陷阱卡上级召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95026693,'火焰灵魂','对手从牌组中抽取１张卡片。从自己牌组中挑选１只炎族怪兽并从游戏中除外，给予对手LP被除外怪兽攻击力一半数值的伤害。此卡发动的回合，自己不可攻击宣言。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95027497,'忍者大师 HANZO','此卡召唤成功时可发动。从牌组将１张冠有“忍法”之名的卡牌加入手牌。此外，此卡反转召唤、特殊召唤成功时可发动。从牌组将１只除“忍者大师 HANZO”以外的冠有“忍者”之名的怪兽加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95034141,'黄金乡的七摩天','此卡名的①②效果１回合仅可各使用１次。①：在自己的主要阶段可以发动。从自己的手牌・场上，将由融合怪兽卡决定的融合素材怪兽送至墓地，从额外牌组将１只该融合怪兽融合召唤。在此之际，融合素材怪兽必须全部是不死族怪兽。②：不死族怪兽因卡的效果被特殊召唤的情况下，以被放置在魔法与陷阱区域的１张卡为对象可以发动。被放置的该卡在此回合不可发动。','','','请选择要禁止发动的卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95040215,'黑羽－星影之诺顿克',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的①效果1回合仅可使用1次。\r\n①：此卡特殊召唤的情况下发动。给予对手800伤害。然后，对手场上的1只表侧表示怪兽的攻击力・守备力下降800。\r\n②：只要此卡存在于怪兽区域，自己在通常召唤之外，可在自己的主要阶段追加1次召唤1只“黑羽”怪兽。','\r',char(13)),'\n',char(10)),'使用「黑羽－星影之诺顿克」的效果召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95051344,'成佛','破坏所有装有装备卡的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95072744,'英雄之烬影依 古利水晶',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：此卡反转的情况下，以岩石族以外的、自己墓地的1只“影依”怪兽为对象可以发动。适用该怪兽反转的情况下发动的效果。\r\n②：此卡因效果被送至墓地的情况下可以发动（发动此效果的回合中，自己从额外牌组仅可特殊召唤“影依”怪兽）。将自己的手牌・场上・墓地的怪兽作为融合素材除外，将1只“影依”融合怪兽融合召唤。','\r',char(13)),'\n',char(10)),'复制效果','融合召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95081386,'三振屏障',replace(replace('①：对手场上的卡牌仅是３张的场合，可从以下效果选择１个并发动。\r\n●此回合，我方的怪兽不会因战斗被破坏。\r\n●此回合，我方受到的战斗伤害变成０。\r\n●此回合，每次我方怪兽给予对手战斗伤害，我方LP回复该数值数量。','\r',char(13)),'\n',char(10)),'自己怪兽不会被战斗破坏','自己受到的战斗伤害变成0','战斗伤害时自己基本分回复','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95083785,'过早归还','①：可将１张手牌除外，并以我方被除外的１只怪兽为对象发动。以里侧守备表示特殊召唤该怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95084054,'电力加农炮','１回合１次，等级４以下的雷族怪兽被召唤・特殊召唤时，给予对手LP６００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95090813,'核成战斗武装','此卡的控制者每次我方的结束阶段，从手牌将１张“核成之钢核”送入墓地，或向对手展示１只手牌的战士族怪兽。或者不执行上述两项破坏此卡。１回合１次，可选择我方墓地１只等级３或以下的战士族怪兽，并视为装备卡装备此卡。此卡的攻击力上升相当于因此效果所装备怪兽攻击力的一半数值。此卡因战斗被破坏的场合，破坏装备怪兽作为代替。','选择一张「核成之钢核」送至墓地','选择一张战士族怪兽给对手观看','破坏「核成战斗武装」','装备','','','','','','','','','','','','');
INSERT INTO texts VALUES(95091919,'原型念力枪手',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从手牌将此卡舍弃可以发动。将自己手牌・除外状态的1只等级4以下的念动力族怪兽特殊召唤。\r\n②：此卡存在于墓地的情况下，支付1000LP，从自己墓地将1只其他的念动力族怪兽除外可以发动。将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'特殊召唤','此卡特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95095116,'炽天骑士盖亚日珥',replace(replace('“烈日骑士盖亚烈焰”＋自己场上的表侧表示怪兽\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：对手发动手牌・墓地的怪兽的效果时，从手牌舍弃１只怪兽可以发动。将该效果无效并破坏。\r\n②：以此卡的攻击破坏对手怪兽时，以自己墓地的１只炎属性怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95096437,'义贼的精奥书','可选择我方场上的１只通常怪兽来发动此卡。此回合中，所选择怪兽对对手生命造成战斗伤害时，随机弃置对手２张手牌。','丢弃手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95113856,'幻子力航母 神舟进取号',replace(replace('等级9怪兽×2\r\n①：1回合1次，去除此卡的1个超量素材，可从以下效果中选择1个发动。\r\n●挑选对手场上的1张卡除外。\r\n●随机从对手手牌中挑选1张除外。\r\n●挑选对手墓地的1张卡除外。\r\n●将对手牌组最上面的卡除外。','\r',char(13)),'\n',char(10)),'选择效果发动','选对手场上1张卡从游戏中除外','对手手牌随机选1张从游戏中除外','选对手墓地1张卡从游戏中除外','对方卡组最上面的卡从游戏中除外','','','','','','','','','','','');
INSERT INTO texts VALUES(95132338,'水的合唱','①：场上存在同名怪兽，场上的怪兽攻击力、守备力上升５００。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95132593,'百臂无形手 盖伽撕',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：在抽牌阶段以外有卡加入对手手牌的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：在自己的主要阶段可以发动。从对手牌组上面翻开3张卡。可从其中挑选1只怪兽特殊召唤至自己场上。剩余的放回牌组。\r\n③：此卡与怪兽进行战斗的情况下，该2只不会因该战斗被破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','特殊召唤','是否特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95134948,'编号99 希望皇霍普德拉古纳',replace(replace('等级12怪兽×3只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己・对手回合中，去除此卡的2个超量素材可以发动（发动此效果的回合中，自己从额外牌组仅可特殊召唤超量怪兽，自己的其他怪兽不可直接攻击）。从额外牌组将“编号1”～“编号100”中的任意1只“编号”怪兽视为超量召唤特殊召唤。\r\n②：对手怪兽攻击宣言时可以发动。将该对手怪兽的攻击力改成0。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95134949,'编号99 希望皇霍普德拉古纳',replace(replace('等级12怪兽×3只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己・对手回合中，去除此卡的2个超量素材可以发动（发动此效果的回合中，自己从额外牌组仅可特殊召唤超量怪兽，自己的其他怪兽不可直接攻击）。从额外牌组将“编号1”～“编号100”中的任意1只“编号”怪兽视为超量召唤特殊召唤。\r\n②：对手怪兽攻击宣言时可以发动。将该对手怪兽的攻击力改成0。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95136979,'破械式鬼 奢罗',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己・对手的主要阶段，从手牌将此卡舍弃可以发动。从手牌将1只恶魔族怪兽特殊召唤。然后，将自己场上的1张卡破坏。\r\n②：此卡存在于墓地的状态下，场上的卡因战斗或“破械式鬼 奢罗”以外的卡的效果被破坏的情况下可以发动。将此卡加入手牌或特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，放回牌组最下面。','\r',char(13)),'\n',char(10)),'特殊召唤','回收','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95144193,'锹形海克力士','“锹甲阿尔法”＋“海克力士甲虫”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95166228,'贵甲螳螂',replace(replace('此卡存在于墓地或以表侧表示存在于场上的场合，将被视为通常怪兽。以通常召唤的方式再次召唤场上表侧表示的此卡，此卡将视为效果怪兽并获得以下效果。\r\n●此卡可对对手场上的所有怪兽各进行１次攻击。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95169481,'恐牙狼 钻石狼',replace(replace('等级4怪兽×2\r\n①：1回合1次，去除此卡的1个超量素材，以自己场上的1只兽族・兽战士族・鸟兽族怪兽和场上的1张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95174353,'阿米巴','此卡的控制权转移的情况下发动。自己受到２０００点伤害。此卡表侧表示存在于场上期间，此效果仅可使用１次。','LP伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95178994,'巨型病毒','①：此卡因战斗被破坏并送往墓地的情况下发动。给予对手LP５００点伤害。然后，可以从牌组以攻击表示特殊召唤仅任意数量的“巨型病毒”。','伤害','是否要特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95192919,'烈风霸者 西摩格','此卡名的②③效果1回合仅可各使用1次。①：上级召唤的此卡不会成为对手魔法・陷阱卡效果的对象。②：魔法・陷阱卡效果发动时，解放自己场上的1只鸟兽族・风属性怪兽，以对手场上的1张卡为对象可以发动。将该卡放回持有者的牌组。③：此卡存在于墓地，自己的鸟兽族怪兽因战斗被破坏时可以发动。将此卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95194279,'次元歪曲','可在我方墓地中没有卡牌存在的场合发动此卡。选择我方１只被除外的怪兽并将其特殊召唤至我方场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95204084,'核成・龙卷风','从手牌将１张“核成之钢核”放回牌组最上面可以发动。破坏对手场上的所有被特殊召唤的怪兽。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95207988,'地缚共振',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n \r\n①：被从额外牌组特殊召唤的场上怪兽因效果被破坏的情况下，以其中１只为对象可以发动。双方受到相当于该怪兽攻击力一半数值的伤害。 \r\n②：被从额外牌组特殊召唤的自己的暗属性同步怪兽被选择为攻击对象时，以场上的１张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'双方受到伤害','选择卡破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95209656,'仪龙机巧－降星：象限仪','以“辉龙机巧降星”降临。此卡名的②③效果1回合仅可各使用1次。①：场上的此卡不会成为对手魔法・陷阱卡的效果的对象。②：此卡仪式召唤所使用的怪兽等级合计为2以下的情况下可以发动。将对手场上的魔法・陷阱卡全部破坏。③：仪式召唤的此卡被破坏的情况下可以发动。从自己的墓地挑选攻击力合计为4000的、“仪龙机巧-降星：象限仪”以外任意数量的“龙机巧”怪兽特殊召唤。','','','仪式召唤使用的怪兽的等级合计是2星以下','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95214051,'翡翠的虫笛','对手玩家选择牌组中的１只昆虫族怪兽，对牌组进行洗牌后将该卡放置在牌组最上面。','请选择要放置到牌组最上方的卡','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95218695,'地中骇界邪龙 亡骸阿尔沃兰',replace(replace('此卡名的③效果1回合仅可使用1次。\r\n①：自己场上的表侧表示怪兽变为里侧表示时，若自己场上不存在表侧表示怪兽则可以发动。从手牌将此卡以守备表示特殊召唤。\r\n②：在自己的主要阶段可以发动。将此卡改成里侧守备表示（1回合仅1次）。\r\n③：此卡反转的情况下可以发动。此回合中，自己场上的“地中骇界”卡不会因对手的效果被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95220856,'怨灵的湿地带','召唤・反转召唤・特殊召唤的怪兽在该回合不可攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95231062,'迷失之蓝破坏者','场上有除此卡以外的鱼族・海龙族・水族怪兽存在的场合可释放此卡来发动此卡。选择场上１张魔法・陷阱卡并将其破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95238394,'雷龙结合','此卡名的①②效果1回合仅可各使用1次。①：从自己场上・墓地的怪兽及被除外的自己的怪兽中，将由雷族融合怪兽卡决定的融合素材怪兽放回持有者的牌组，从额外牌组将1只该融合怪兽融合召唤。②：将墓地的此卡除外可以发动。从牌组将1只雷族怪兽加入手牌。此效果在此卡被送至墓地的回合不可发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95239444,'森罗的镇神 山精',replace(replace('等级７怪兽×２\r\n１回合１次，可将我方手牌、场上的１只植物族怪兽送入墓地并发动。从牌组的上方确认相当于该等级数量的卡牌，并依照喜好顺序返回至牌组的上方。此外，１回合１次，可移除此卡的１个超量素材并发动。从我方牌组的上方翻阅最多３张卡牌。若其中有植物族怪兽的场合，将所有那些怪兽送入墓地，挑选场上除此卡以外的卡牌返回至手牌，其数量最多是送入墓地怪兽数量。剩余的卡牌依照喜好顺序返回至牌组的下方。','\r',char(13)),'\n',char(10)),'确认牌组','翻开牌组','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95243515,'电脑堺彪－虎虎',replace(replace('等级９怪兽×２只以上\r\n①：根据自己场上的“电脑堺门”卡的数量，此卡获得以下效果。\r\n●２张以上：此卡可直接攻击。\r\n●４张：此卡不受“电脑堺”卡以外的卡发动的效果影响。\r\n②：１回合１次，去除此卡的１个超量素材，以自己场上的１只效果怪兽，和场上的１只种族和属性与该怪兽不同的效果怪兽为对象可以发动。将该怪兽的效果直至回合结束时为止无效。此效果在对手回合中也可以发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95245544,'魔女工艺・涂装皮特莱',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己・对手的主要阶段，解放此卡，从手牌将1张魔法卡舍弃可以发动。从牌组将“魔女工艺・涂装皮特莱”以外的1只“魔女工艺”怪兽特殊召唤。\r\n②：将墓地的此卡除外可以发动。自己抽1张。然后，手牌存在“魔女工艺”卡的情况下，挑选其中1张送至墓地。不存在的情况下，将自己手牌全部除外。','\r',char(13)),'\n',char(10)),'特殊召唤','抽牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95245571,'恐惧爪・双牙','此卡名的卡１回合仅可发动１张。①：解放自己场上的１只“恐惧爪”怪兽，以对手场上的２张卡为对象可以发动。将该卡破坏。自己场上存在“维萨思・史塔弗罗斯特”的情况下，以此效果破坏的卡不去墓地而直接被除外。②：场上存在连接３以上的怪兽的情况下，将墓地的此卡除外可以发动。此回合，场上的连接怪兽不可发动效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95254840,'临时取消','①：对手怪兽的攻击宣言时可发动。将我方场上的所有怪兽变成守备表示。此卡发动后，直至回合结束时，因战斗、效果被破坏的我方场上的“娱乐伙伴”怪兽不前往墓地而直接返回至持有者手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95265975,'大胃王食尸鬼','不管再怎么吃都不会饱的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95281259,'战士生还','①：以自己墓地的1只战士族怪兽为对象可以发动。将该战士族怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95283172,'黄金荣耀－欢腾激昂',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：将手牌的１只“黄金荣耀”怪兽出示给对手可以发动。从牌组将１只卡名与所出示怪兽不同的“黄金荣耀”怪兽加入手牌。然后，可适用以下效果。\r\n●从手牌将１只“黄金荣耀”怪兽特殊召唤，自己失去相当于其原本攻击力数值的LP。','\r',char(13)),'\n',char(10)),'','是否从手牌把怪兽特殊召唤？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95286165,'融合解除','①：以场上的1只融合怪兽为对象可以发动。将该融合怪兽放回额外牌组。然后，如果被放回了额外牌组的该怪兽原先融合召唤所使用的一组融合素材怪兽全部都在自己墓地，可将该一组特殊召唤。','是否要特殊召唤融合素材？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95288024,'天空龙','拥有两对翅膀的鸟形龙。利用刀刃之翼发动攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95291684,'异次元的独角战士','此卡不可通常召唤，特殊召唤此卡的回合，我方不可通常召唤。对手场上存在有怪兽，且我方场上存在有协调的场合，此卡可特殊召唤。以此方法特殊召唤成功时，可选择１只除从游戏中被除外的协调以外的等级３或以下的我方怪兽并特殊召唤。以此效果特殊召唤的怪兽的效果被无效化。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95308449,'终焉的倒计时','支付２０００点LP。发动回合起经过２０个回合后，我方获得决斗的胜利。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95326659,'宝玉的指引','我方的魔法与陷阱区域存在有２张或以上冠有“宝玉兽”之名卡牌的场合，从牌组特殊召唤１只冠有“宝玉兽”之名的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95352218,'天下统一','双方的准备阶段时，回合玩家从自己场上怪兽的等级内挑选１个，将自己场上等级不同于该等级的表侧表示怪兽全部送至墓地。','送至墓地','请选择要保留的等级对应的怪兽','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95360850,'护盾战士','我方怪兽进行战斗的伤害计算时，可将墓地的此卡从游戏中除外并发动。我方怪兽不会因该战斗而被破坏。','不被战斗破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95362816,'元素－英雄 炙炎女郎','我方结束阶段时，给予对手生命相当于我方场上冠有“元素－英雄”之名的怪兽数量×２００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95365081,'百臂无形手 伊卜揶尔',replace(replace('此卡名的①③效果1回合仅可各使用1次。\r\n①：向对手出示手牌的此卡可以发动。将此卡放回牌组。然后，从牌组将“百臂无形手 伊卜揶尔”以外的1只“百臂无形”怪兽以守备表示特殊召唤。\r\n②：此卡与怪兽进行战斗的情况下，该2只不会因该战斗被破坏。\r\n③：此卡被送至墓地的情况下，以“百臂无形手 伊卜揶尔”以外的、自己墓地的1只“百臂无形”怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95372220,'枪口焰龙',replace(replace('龙族怪兽2只以上\r\n自己不可将怪兽出到此卡的连接端。\r\n①：1回合1次，有怪兽被召唤・特殊召唤至此卡连接端的情况下可以发动。将此卡连接端的1只怪兽破坏，给予对手500伤害。\r\n②：以此卡为对象的魔法・陷阱・怪兽的效果发动时，解放自己场上的1只怪兽可以发动。将该发动无效。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95376428,'召唤限制－额外之网',replace(replace('①：我方或对手从额外牌组特殊召唤怪兽的场合发动此效果。特殊召唤该怪兽玩家的对手适用以下效果。\r\n●从牌组抽取１张卡牌。','\r',char(13)),'\n',char(10)),'抽牌','是否抽1张卡？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95382988,'再世十诫',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：对与自己场上的“再世”怪兽同一纵列的、对手场上的所有卡适用以下效果。\r\n●表侧表示卡：效果无效化。\r\n●里侧表示怪兽：不可变更表示形式。\r\n●里侧表示的魔法・陷阱卡：直至下个回合结束时为止不可发动。','\r',char(13)),'\n',char(10)),'发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95395761,'甲虫装机 蚂蚁','１回合１次，可从我方手牌、墓地将１只冠有“甲虫装机”之名的怪兽视为装备卡装备此卡。此卡被视为装备卡装备中的场合，装备怪兽的等级上升３级，攻击力、守备力各上升此卡的攻击力、守备力数值。装备怪兽被破坏的场合，破坏此卡作为代替。','装备','是否要用「甲虫装机 蚂蚁」代替破坏？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95401059,'羁绊影依－源质原核',replace(replace('←7 【灵摆】 7→\r\n①：自己仅可将“影依”怪兽及“源质”怪兽灵摆召唤。此效果不会被无效。\r\n【怪兽效果】\r\n此卡名的怪兽效果1回合仅可使用1次。①：在此卡灵摆召唤成功的情况下，或在此卡被送至墓地的情况下，可以自己灵摆区域的1张“羁绊影依-源质原核”以外的“源质”卡为对象发动。将该卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95403418,'星尘小妖','此卡不可通常召唤。仅可在将自己场上任意数量的表侧表示“尘小妖”怪兽送至墓地的情况下特殊召唤。此卡的攻击力・守备力变为相当于送至墓地的该怪兽数量×１０００点的数值。只要此卡以表侧表示存在于场上，对手不可发动放置在场上的魔法・陷阱卡，对手不可反转召唤・特殊召唤怪兽。自己场上的怪兽数量多于对手场上的怪兽数量的情况下，此卡将被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95440946,'黄金卿埃尔德里奇',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从手牌将此卡和1张魔法・陷阱卡送至墓地，以场上的1张卡为对象可以发动。将该卡送至墓地。\r\n②：此卡存在于墓地的情况下，将自己场上的1张魔法・陷阱卡送至墓地可以发动。将此卡加入手牌。然后，可从手牌将1只不死族怪兽特殊召唤。以此效果特殊召唤的怪兽直至对手回合结束时为止攻击力・守备力上升1000，不会因效果被破坏。','\r',char(13)),'\n',char(10)),'','','是否把不死族怪兽特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95440947,'黄金卿埃尔德里奇',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从手牌将此卡和1张魔法・陷阱卡送至墓地，以场上的1张卡为对象可以发动。将该卡送至墓地。\r\n②：此卡存在于墓地的情况下，将自己场上的1张魔法・陷阱卡送至墓地可以发动。将此卡加入手牌。然后，可从手牌将1只不死族怪兽特殊召唤。以此效果特殊召唤的怪兽直至对手回合结束时为止攻击力・守备力上升1000，不会因效果被破坏。','\r',char(13)),'\n',char(10)),'','','是否把不死族怪兽特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95440948,'黄金卿埃尔德里奇',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从手牌将此卡和1张魔法・陷阱卡送至墓地，以场上的1张卡为对象可以发动。将该卡送至墓地。\r\n②：此卡存在于墓地的情况下，将自己场上的1张魔法・陷阱卡送至墓地可以发动。将此卡加入手牌。然后，可从手牌将1只不死族怪兽特殊召唤。以此效果特殊召唤的怪兽直至对手回合结束时为止攻击力・守备力上升1000，不会因效果被破坏。','\r',char(13)),'\n',char(10)),'','','是否把不死族怪兽特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95442074,'编号31 亚伯魔鬼',replace(replace('等级1怪兽×2\r\n①：在每个自己・对手回合中1次，去除此卡的1个超量素材可以发动。对手场上的所有怪兽变为表侧攻击表示，且在此回合可攻击的情况下必须攻击此卡。\r\n②：只要自己场上存在“编号13 该隐魔鬼”，此卡获得以下效果。\r\n●持有超量素材的此卡不会因战斗・效果被破坏。\r\n●因攻击此卡而对自己造成的战斗伤害由对手代为承受。','\r',char(13)),'\n',char(10)),'变成表侧攻击','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95443805,'霞之谷的祈祷师','１回合１次，可将我方场上除此卡以外的１只怪兽返回至持有者手牌并发动。直至回合结束时，此卡的攻击力上升５００点。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95448372,'刚鬼斗魂',replace(replace('此卡名的卡1回合仅可发动1张，此卡名的②效果1回合仅可使用1次。\r\n①：作为此卡发动时的效果处理，可从手牌将1只等级4以下的战士族・恐龙族・电子界族的地属性怪兽以守备表示特殊召唤。\r\n②：解放自己场上的1只连接3以上的“刚鬼”怪兽可以发动。从牌组・额外牌组将1只“恐龙摔跤手”怪兽或“G魔像”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'发动','从额外牌组特殊召唤','是否特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95448692,'伤害节食','此回合，我方所受到的所有伤害减半。此外，可将墓地的此卡从游戏中除外并发动。此回合，我方所受到的效果伤害减半。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95451366,'魔力枯竭','取除我方和对手场上所有的魔力计数物。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95453143,'百目龙',replace(replace('暗属性协调＋协调以外的恶魔族怪兽1只以上\r\n①：1回合1次，从自己墓地将1只等级6以下的暗属性效果怪兽除外可以发动。此卡直至结束阶段为止，获得与该怪兽原本卡名・效果相同的卡名・效果。\r\n②：此卡被破坏并被送至墓地的情况下发动。从牌组将1只“地缚神”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'获得怪物效果','从自己牌组把1只名字带有「地缚神」的怪兽加入手牌','复制效果结束','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95454996,'码丽丝＜后＞白色绑缚',replace(replace('包含“码丽丝”怪兽在内的怪兽2只以上\r\n此卡名的①②③效果1回合仅可各使用1次。\r\n①：此卡特殊召唤的情况下，以自己・对手墓地的合计最多3张卡为对象可以发动。将该卡除外。\r\n②：在自己的主要阶段可以发动。从自己牌组・墓地将1张“码丽丝”陷阱卡放置在自己场上。\r\n③：此卡被除外的情况下，支付900LP可以发动。将此卡特殊召唤。然后，自己可抽1张。','\r',char(13)),'\n',char(10)),'除外效果','放置陷阱','特殊召唤','是否抽牌？','','','','','','','','','','','','');
INSERT INTO texts VALUES(95457011,'天帝从骑埃迪亚',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将“天帝从骑埃迪亚”以外的1只攻击力800/守备力1000的怪兽以守备表示特殊召唤。此效果发动后，直至回合结束时为止，自己不可从额外牌组特殊召唤怪兽。\r\n②：此卡被送至墓地的情况下，以自己除外状态的1张“帝王”魔法・陷阱卡为对象可以发动。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95463814,'幻魔帝特里洛吉克',replace(replace('等级10怪兽×3\r\n此卡名的效果1回合仅可使用1次。①：此卡特殊召唤成功的情况下，或此卡已经存在于怪兽区域的状态下，此卡以外的怪兽从墓地被特殊召唤至自己场上的情况下，可以对手场上的1只表侧表示怪兽为对象发动。给予对手相当于该怪兽原本攻击力一半的伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95466842,'水精鳞－深渊肺鱼','只要此卡以表侧表示存在于场上，对手不可选择其他水属性怪兽作为攻击对象。此外，只要此卡以表侧表示存在于场上，我方场上的水属性怪兽的攻击力上升３００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95471006,'X・Y・Z 合体',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己的机械族・光属性联合怪兽卡被除外的情况下可以发动。从牌组将“X－首领加农”、“Y－龙首”、“Z－金属履带”中的任意１只特殊召唤。\r\n②：将自己场上１只表侧表示的融合怪兽放回额外牌组可以发动。从自己除外状态的“X－首领加农”、“Y－龙首”、“Z－金属履带”中将最多２只特殊召唤（同名卡最多１张）。','\r',char(13)),'\n',char(10)),'从牌组特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95472621,'大火葬','对手以墓地的怪兽为对象，发动怪兽效果、魔法、陷阱卡时可发动。将双方墓地的所有怪兽从游戏中除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95474755,'编号89 电脑兽 迪亚布罗系司',replace(replace('等级７怪兽×２\r\n此卡名的③效果１回合仅可使用１次。\r\n①：１回合１次，去除此卡的１个超量素材可以发动。确认对手的额外牌组，将其中１张以里侧除外。\r\n②：此卡战斗破坏怪兽的战斗阶段结束时，以对手墓地的１张卡为对象可以发动。将该卡以里侧除外。\r\n③：对手的卡以里侧被除外的情况下可以发动。依以里侧被除外的对手卡的数量，从对手的牌组上面将卡以里侧除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95477924,'魔术师救助',replace(replace('此卡名的卡1回合仅可发动1张，此卡名的②效果1回合仅可使用1次。\r\n①：作为此卡发动时的效果处理，可从牌组将1张“永远之魂”放置在自己场上。\r\n②：自己召唤・特殊召唤“黑魔导”或“黑魔导女孩”的情况下，以该1只怪兽为对象可以发动。从自己的墓地将1只卡名与该怪兽不同的“黑魔导”或“黑魔导女孩”特殊召唤。','\r',char(13)),'\n',char(10)),'是否从牌组把「永远之魂」放置？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95486586,'元素－英雄 Core',replace(replace('“元素－英雄”怪兽×３\r\n此卡只可以融合召唤特殊召唤。\r\n①：１回合１次，此卡变成攻击对象时可发动。直至该伤害步骤结束时，此卡的攻击力加倍。\r\n②：此卡进行了战斗的战斗阶段结束时，可以场上的１只怪兽为对象发动。破坏该怪兽。\r\n③：此卡因战斗、效果被破坏时，可以我方墓地１只等级８或以下的“元素－英雄”融合怪兽为对象发动。无视召唤条件特殊召唤该怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95492061,'万手之神','①：此卡召唤・反转召唤成功时可以发动。从牌组将1只仪式怪兽或1张仪式魔法卡加入手牌。','把1只仪式怪兽或者1张仪式魔法卡加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95493471,'真超级量子机神王 轰闪惊天煌',replace(replace('包含“超级量子”怪兽在内的效果怪兽2只以上\r\n此卡名的③效果1回合仅可使用1次。\r\n①：连接召唤的此卡不会因对手的效果被破坏。\r\n②：每次有自己场上不存在同名卡的“超级量子”超量怪兽从额外牌组被特殊召唤至此卡的连接端则发动。自己抽1张。\r\n③：此卡连接端的超量怪兽因战斗或对手的效果被破坏的情况下可以发动。从牌组将原本属性与该超量怪兽相同的1只“超级量子”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95500396,'超重武者装魂 仲裁','此卡名的③效果１回合仅可使用１次。①：在自己的主要阶段，以自己场上的１只“超重武者”怪兽为对象可以发动。从自己的手牌・场上将此怪兽视为装备卡，装备于该自己的怪兽。②：此卡是以此卡的效果被装备中的情况下，对手不可攻击装备怪兽以外的自己的怪兽。③：解放以此卡的效果装备此卡的自己怪兽可以发动。从牌组将１只“超重武者”怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95503687,'光道召唤士 路米娜丝',replace(replace('①：１回合１次，舍弃１张手牌，以自己墓地的１只等级４以下的“光道”怪兽为对象可以发动。将该怪兽特殊召唤。\r\n②：在自己的结束阶段发动。从自己的牌组上面将３张卡送至墓地。','\r',char(13)),'\n',char(10)),'特殊召唤','从牌组送3张卡去墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95504778,'扳机幻龙',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡作为暗属性连接怪兽的连接素材被送至墓地的情况下可以发动。将墓地的此卡以攻击表示特殊召唤至该连接怪兽连接端的自己场上。以此效果特殊召唤的此卡不可作为连接素材。\r\n②：此卡因连接怪兽发动的效果被破坏的情况下或被除外的情况下发动。自己从牌组抽１张。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95507060,'狂植物的犯滥','直至回合结束时，我方场上的所有植物族怪兽的攻击力上升相当于我方墓地的植物族怪兽数量×３００点。此回合的结束阶段时，破坏我方场上的所有植物族怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95511642,'获得星杯的巫女',replace(replace('向星神献上镇魂祈祷的巫女。\r\n手中的杖是代代传承的祭器，她将力量变为结界，保护森林之民不受机界骑士支配。\r\n虽然她身上隐藏着连森林守护龙都会亲近的神通力，但平时看上去只是个珍视哥哥和发小的善良少女。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95515058,'刚鬼 持剑食人魔',replace(replace('“刚鬼”怪兽2只以上\r\n①：此卡的攻击力上升相当于此卡连接端的怪兽数量×300的数值。②：1回合1次，解放此卡连接端的自己或对手的1只怪兽可以发动。此回合，此卡在1次战斗阶段中可攻击2次。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95515060,'静寂之杖－凯丝特','装备怪兽的守备力上升５００点。令以装备怪兽为对象的此卡以外的魔法卡效果无效并将其破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95515518,'月天气 彩虹',replace(replace('“天气”怪兽３只\r\n①：此卡连接召唤成功的情况下可以发动。挑选１只自己被除外的“天气”怪兽特殊召唤。\r\n②：此卡连接端的“天气”效果怪兽获得以下效果。\r\n●在自己・对手的回合中，将此卡除外，以对手场上的１只怪兽为对象可以发动。将该怪兽直至下个回合的准备阶段为止除外。\r\n③：连接召唤的此卡被破坏的情况下可以发动。从额外牌组将１只“虹天气 彩虹”特殊召唤。','\r',char(13)),'\n',char(10)),'除外的「天气」怪兽特殊召唤','对手怪兽除外（月天气 彩虹）','从额外牌组特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95515789,'赫之圣女 卡尔塔西亚',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：自己场上或墓地存在“阿尔白斯之落胤”的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：在自己・对手的主要阶段可以发动。将自己手牌・场上的怪兽作为融合素材，将1只等级8以上的融合怪兽融合召唤。\r\n③：此回合有融合怪兽被送至自己墓地的情况下，在结束阶段可以发动。将墓地的此卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95515790,'赫之圣女 卡尔塔西亚',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：自己场上或墓地存在“阿尔白斯之落胤”的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：在自己・对手的主要阶段可以发动。将自己手牌・场上的怪兽作为融合素材，将1只等级8以上的融合怪兽融合召唤。\r\n③：此回合有融合怪兽被送至自己墓地的情况下，在结束阶段可以发动。将墓地的此卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95519486,'六武众－斩次','我方场上存在有除“六武众－斩次”以外的冠有“六武众”之名的怪兽的场合，此卡在伤害步骤结束时破坏被攻击的怪兽。此外，场上的此卡被破坏的场合，可破坏我方场上的１只冠有“六武众”之名的怪兽作为代替。','攻击过的怪兽破坏','是否要使用「六武众－斩次」的代替破坏效果？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95526884,'高能念力枪手',replace(replace('协调＋协调以外的念动力族怪兽1只以上\r\n①：此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。\r\n②：此卡攻击守备表示怪兽，且攻击力超出该怪兽守备力的情况下，在伤害步骤结束时发动。依其数值之差恢复自己的LP。','\r',char(13)),'\n',char(10)),'回复LP','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95545183,'异谭忍法帖',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：对手场上存在卡的情况下可以发动。从自己的牌组・墓地挑选“异谭忍法帖”以外的“忍法”魔法・陷阱卡及“忍者”怪兽各最多１张，放置在自己场上（从牌组・墓地分别仅可放置最多１张）。\r\n②：被放置的此卡被送至墓地的情况下，以场上的１只表侧表示怪兽为对象可以发动。将该怪兽改成里侧守备表示。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95561146,'阿波菲斯的蛇神',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡发动后，变为通常怪兽（爬虫类族・地・星4・攻1600/守1800），特殊召唤至怪兽区域（也视为陷阱卡）。然后，可从牌组将“阿波菲斯的蛇神”以外的1张“阿波菲斯”陷阱卡放置在自己场上。以此效果放置的卡在放置的回合也可以发动。\r\n②：此卡被送至墓地的情况下可以发动。从牌组将1张“阿波菲斯的化神”加入手牌。','\r',char(13)),'\n',char(10)),'适用「阿波菲斯之蛇神」的效果来发动','是否把陷阱卡放置？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95561280,'猛毒之风','只要此卡存在于场上，双方都不可特殊召唤风属性怪兽。此外，场上的所有风属性怪兽的攻击力下降５００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95568112,'雨虹娃娃',replace(replace('←8 【灵摆】 8→\r\n①：１回合１次，可以我方场上１只面朝上怪兽为目标发动。该怪兽的攻击力提升等同于双方玩家额外卡组张数之差×１００的数值。\r\n【怪兽效果】\r\n①：在我方回合为此卡的攻击力，在对手回合则为此卡的守备力，提升等同于双方玩家额外卡组张数之差×２００的数值。\n②：如果此卡攻击过，则在战斗阶段结束其变为守备状态。\n③：如果此卡在怪兽区被破坏，则可发动。将此卡放在我方灵摆区中。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95589901,'大狼的恶作剧',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：分别适用以下效果。\r\n●对手场上的所有怪兽的等级下降2。\r\n●自己场上的所有怪兽的等级上升2。\r\n②：在此卡被送至墓地的回合的自己主要阶段，以自己场上的1张表侧表示卡为对象可以发动。将该卡破坏，将此卡加入手牌。','\r',char(13)),'\n',char(10)),'发动','回到手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95600067,'宝玉兽 黄玉虎',replace(replace('①：此卡攻击对手怪兽的场合，在伤害步骤期间此卡的攻击力上升４００。\r\n②：表侧表示的此卡在怪兽区被破坏的场合，可不送入墓地被视作永续魔法卡以表侧表示放置在我方的魔法与陷阱区域。','\r',char(13)),'\n',char(10)),'破坏时放置魔法陷阱区','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95602345,'暗岩之利维坦',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：将自己场上的1张表侧表示的“海”送至墓地可以发动。从手牌・牌组将记载有“海”卡名的怪兽或水属性的通常怪兽合计最多2只以守备表示特殊召唤（同名卡最多1张）。对手场上存在怪兽的情况下，进而可从手牌・牌组将任意数量的等级6以下的水属性通常怪兽特殊召唤。此卡发动后，直至下个自己回合结束时为止，自己仅可特殊召唤水属性怪兽。','\r',char(13)),'\n',char(10)),'是否继续特殊召唤水属性通常怪兽？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95612049,'世界轮转',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：为使合计等级达到仪式召唤的怪兽的等级以上，解放手牌的仪式怪兽，从手牌・牌组将“破灭之女神 露茵”或“终焉之王 迪米斯”仪式召唤。','\r',char(13)),'\n',char(10)),'自己从牌组抽1张','选场上1张卡破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95614612,'炮弹螺贝','只要“海”存在于场上，此卡便不会受到魔法效果的影响。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95621257,'炎狱魔术师','只要我方场上存在冠有“正义盟军”之名的怪兽，此卡的攻击力上升４００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95626382,'终刻狱龙机ⅩⅡ－德拉斯特琉斯',replace(replace('等级8怪兽×3\r\n此卡名的①③效果1回合仅可各使用1次。\r\n①：此卡超量召唤的情况下可以发动。将场上的1只其他的表侧表示怪兽视为装备魔法卡装备于此卡。\r\n②：此卡1回合仅1次，不会因战斗・效果被破坏。\r\n③：对手发动场上・墓地的怪兽的效果时，去除此卡的1个超量素材可以发动。将该效果无效。然后，可将对手场上的1只表侧表示怪兽视为装备魔法卡装备于此卡。','\r',char(13)),'\n',char(10)),'装备','效果无效','是否把对手怪兽装备？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95637655,'后援战士','此卡不可通常召唤。我方场上的怪兽是２只守备表示怪兽的场合可特殊召唤。特殊召唤此卡的回合，我方不可同步召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95638658,'流星之弓－希尔','装备怪兽的攻击力下降１０００点。装备怪兽可直接攻击对手玩家。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95642274,'谦虚的门卫','公开我方的手牌，将其中１张卡牌放回至牌组中。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95658967,'祝福教会－仪式圣堂','此卡名的①②效果１回合仅可各使用１次。①：在自己的主要阶段，从手牌将１张魔法卡舍弃可以发动。从牌组将１只光属性仪式怪兽或１张仪式魔法卡加入手牌。②：将自己墓地任意数量的魔法卡放回牌组，以自己墓地１只等级与放回牌组数量相同的天使族・光属性怪兽为对象可以发动。将该怪兽特殊召唤。','加入手牌','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95664204,'ZEXAL弹射器','此卡名的①②效果１回合仅可各使用１次。①：从手牌将１只“ZEXAL兵器”怪兽或“ZEXAL从者”怪兽特殊召唤。自己场上有“希望皇霍普”怪兽存在的情况下，进而可将自己场上的所有怪兽的等级改成４或５。②：将１只“ZEXAL兵器”怪兽或“ZEXAL从者”怪兽和此卡从自己的墓地除外，以对手场上的１张卡为对象可以发动。将该卡破坏。此效果在此卡被送至墓地的回合不可发动。','特殊召唤','卡片破坏','是否改变等级？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95676943,'灭绝之宿命','①：在自己・对手的主要阶段支付２０００LP可以发动。此卡发动后的第３次战斗阶段结束时，双方玩家必须将各自场上的卡全部送至墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95679145,'教导之大神祇官',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从自己墓地将1只融合・同步・超量・连接怪兽除外可以发动。从手牌将此卡特殊召唤。\r\n②：在自己的主要阶段可以发动。从自己额外牌组将2只卡名不同的怪兽送至墓地。对手从自身的额外牌组将2只怪兽送至墓地。此效果发动后，直至回合结束时为止自己不可从额外牌组特殊召唤怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95685352,'暗黑幻日龙',replace(replace('←10 【灵摆】 10→\r\n①：１回合１次，以对手场上的１只表侧表示怪兽为对象可以发动。该怪兽的原本攻击力直至回合结束时为止变为一半。\r\n【怪兽效果】\r\n等级７怪兽×２\n在等级７可灵摆召唤的情况下，额外牌组表侧表示的此卡可灵摆召唤。\n①：１回合１次，去除此卡的１个超量素材，以对手场上的１只表侧表示怪兽为对象可以发动。直至回合结束时为止，将该怪兽的攻击力改成一半，此卡的攻击力依其数值上升。此效果在对手回合中也可以发动。\n②：怪兽区域的此卡因战斗・效果被破坏的情况下可以发动。将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95697223,'龙的斗志','①：可以我方场上１只在此回合特殊召唤而来的龙族怪兽为对象发动。此回合，该怪兽在１次的战斗阶段中，除了通常攻击以外，可再进行攻击，其次数最多是在此回合特殊召唤至对手场上的怪兽数量。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95701283,'光神机－轰龙','此卡可解放１只怪兽并召唤。以此方法召唤的此卡，在结束阶段时被送入墓地。此卡攻击了守备表示怪兽时，若其攻击力超过守备力，给予对手生命相当于该差值的战斗伤害。','用1只祭品作召唤','送至墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95714077,'发条生产商','１回合１次，如果有具“发条”之名的怪兽发动效果，则可以发动。从卡组中将１只等级４以下且具“发条”之名的怪兽加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95718355,'再世荒恶魔神 贝米德巴尔',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次，且②③效果1回合仅可各使用1次。\r\n①：此卡可通过向对手出示手牌的1只其他的攻击力或守备力为2500的怪兽，来从手牌特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下可以发动。将“再世荒恶魔神 贝米德巴尔”以外的、自己牌组・除外状态的1张“再世”卡加入手牌。\r\n③：在此卡被送至墓地的对手回合，于结束阶段可以发动。将此卡加入手牌。','\r',char(13)),'\n',char(10)),'','检索','回收','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95727991,'飞箭龟','１回合１次，可解放我方场上１只怪兽来发动此卡。给予对手生命该怪兽攻击力一半数值的伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95735217,'古代机械齿轮巨人－究极重拳',replace(replace('此卡不可特殊召唤。\r\n①：此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予对手战斗伤害。\r\n②：１回合最多２次，以此卡的攻击破坏怪兽时，从手牌将１只机械族怪兽舍弃可以发动。此卡可继续攻击。\r\n③：场上的此卡因战斗・效果被破坏的情况下可以发动。从牌组将１张“融合”加入手牌，从自己的墓地将１只其他“古代机械齿轮”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95744531,'咕哩咕噜','只要此卡以表侧表示存在于场上，仅限１次，此卡的控制权转移时，原控制者回复３０００LP。','LP回复','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95750695,'超二之力',replace(replace('仅可装备于二重怪兽。\r\n①：装备怪兽视为被再召唤过1次的状态。\r\n②：表侧表示的此卡从场上被送至墓地的情况下，以自己墓地的1只通常怪兽为对象发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95772051,'魔圣骑士兰斯洛特','此卡存在于手牌、墓地的场合，可将我方场上的１只表侧表示的光属性通常怪兽送入墓地并发动。特殊召唤此卡。此外，可释放我方场上１只冠有“圣骑士”之名的怪兽并发动。从牌组将１张冠有“圣剑”之名的卡牌加入手牌。“魔圣骑士兰斯洛特”的此效果１回合只可使用１次。此外，我方场上只可有１只“魔圣骑士兰斯洛特”以表侧表示存在。','特殊召唤','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95784434,'蜕皮逃生','仅限装备爬虫类族怪兽。装备怪兽在１个回合中有１次机会不会因战斗而被破坏。适用此效果的伤害步骤结束时，装备怪兽的攻击力上升３００点。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95784714,'彷徨幽灵船 飞翔玛丽号',replace(replace('不死族怪兽２只\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：以自己墓地・除外状态的１只等级５以上的不死族怪兽为对象可以发动。将此卡视为永续魔法卡，以表侧表示放在自己的魔法与陷阱区域，将对象怪兽特殊召唤。\r\n②：此卡视为永续魔法卡的情况下，以自己场上的１只等级５以上的不死族怪兽为对象可以发动。将对手场上的１只攻击力在该怪兽攻击力以下的怪兽破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','破坏怪兽','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95788410,'兔龙','栖息于雪原上的龙类突然变异种。巨大的耳朵可分辨距离数千米远的声音，加之其跳跃力惊人，被它盯上的猎物都无处可逃。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95789089,'冠军袋鼠','此卡与怪兽进行战斗的伤害计算后，该怪兽变为守备表示。','变成守备表示','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95793022,'星杯守护龙 魂之马尔杜克',replace(replace('连接怪兽×3\r\n此卡仅可用融合召唤及以下方法从额外牌组特殊召唤。\r\n●解放自己场上的上述卡的情况下，可从额外牌组特殊召唤（无需“融合”）。\r\n①：此卡可攻击所有对手怪兽各1次。②：此卡与对手的连接怪兽进行战斗的攻击宣言时，将1只与该对手怪兽的连接标记数量相同的连接怪兽从自己场上・墓地除外可以发动。将该对手怪兽破坏，给予对手相当于其原本攻击力数值的伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95816395,'土偶',replace(replace('“土偶”的效果１回合只可使用１次。\r\n①：在此卡因对手效果被送入墓地回合的结束阶段可发动。从牌组将１只我方场上、墓地中不存在等级的怪兽加入手牌。','\r',char(13)),'\n',char(10)),'牌组检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95824983,'电气海月－僧帽水母－',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从自己手牌・牌组・场上（表侧表示）将1张“海”送至墓地可以发动。从手牌将1只水属性怪兽特殊召唤。\r\n②：场上存在“海”，且对手发动魔法・怪兽的效果时可以发动。将该效果无效。然后，可使此卡的攻击力・守备力上升600。','\r',char(13)),'\n',char(10)),'','','是否上升攻击力·守备力？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95825679,'恶魔的降临',replace(replace('以“与奈落的契约”降临。\r\n①：此卡只要存在于怪兽区域，卡名视为“恶魔的召唤”。\r\n②：场上的此卡不会因与仪式怪兽以外的怪兽的战斗被破坏，不会因仪式怪兽以外的怪兽的效果被破坏。\r\n③：仪式召唤的此卡被对手送至墓地的情况下可以发动。从自己的手牌・牌组・墓地挑选１只“恶魔的召唤”特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95833645,'岩浆龙',replace(replace('“岩浆龙”的效果１回合只可使用１次，发动此效果的回合，我方只可特殊召唤幻龙族怪兽。\r\n①：此卡特殊召唤成功时，可以我方墓地１只除“岩浆龙”以外的幻龙族怪兽为对象发动。以守备表示特殊召唤该怪兽。以此效果特殊召唤而来的怪兽其效果被无效化。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95841282,'猫耳族','仅在对方回合时，与此卡战斗的对手怪兽的原始攻击力在伤害步骤时变成２００。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95856586,'ZEXAL领域','此卡名的②效果１回合仅可使用１次。①：应对以自己场上超量怪兽为对象的、自己的卡的效果发动，对手不可发动魔法・陷阱・怪兽的效果。②：超量怪兽被特殊召唤至自己场上的情况下，以该１只怪兽为对象可以发动。从自己的额外牌组・墓地挑选１只超量怪兽，重叠在对象怪兽下方作为超量素材。③：自己抽牌阶段的抽牌前可以发动。从牌组挑选１张“闪光抽牌”，放在牌组最上面。','补充超量素材','「闪光抽牌」在牌组最上面放置','请选择要放置在牌组最上面的卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95886782,'ZEXAL兵器－天风精灵翼',replace(replace('①：“ZEXAL兵器－天风精灵翼”在自己场上仅可有１张以表侧表示存在。\r\n②：以自己场上的１只“希望皇霍普”怪兽为对象可以发动。从自己的手牌・场上，将此卡视为攻击力上升８００的装备卡装备于该怪兽。\r\n③：１回合１次，怪兽因对手发动的效果被特殊召唤的情况下可以发动。装备怪兽的攻击力上升１６００。\r\n④：装备怪兽去除超量素材发动效果的情况下，可将此卡送至墓地作为去除１个超量素材的代替。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95888876,'地狱帝王龙',replace(replace('此卡存在于墓地或以表侧表示存在于场上的场合，将被视为通常怪兽。以通常召唤的方式再次召唤场上表侧表示的此卡，此卡将视为效果怪兽并获得以下效果。\r\n●此卡在１个战斗阶段中可进行２次攻击。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95905259,'预言僧 长莲','１回合１次，可宣言１个卡牌的种类（魔法・陷阱），选择对手魔法与陷阱区域域中１张被盖牌的卡牌来发动此卡。确认所选择卡牌，是所宣言种类的卡牌的场合，所选择卡牌在该回合中不可发动。','确认盖卡','请选择一张要确认的卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95911373,'伟魔代蒙 绝火之琐罗亚',replace(replace('魔法师族协调＋协调以外的怪兽1只以上\r\n此卡名的③效果1回合仅可使用1次。\r\n①：此卡同步召唤的情况下可以发动。从额外牌组将1只“伟魔”怪兽视为装备魔法卡装备于此卡。\r\n②：对手不可发动与自己的魔法与陷阱区域的“伟魔”怪兽卡相同种类（融合・同步・超量・连接）的怪兽效果。\r\n③：以自己场上1张“伟魔”卡为对象可以发动。将该卡破坏，从墓地将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95915457,'镜罩',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：以自己场上的1只表侧表示怪兽为对象可以发动此卡。将此卡视为拥有以下效果的装备卡，装备于该怪兽。\r\n●每次装备怪兽与对手怪兽进行战斗的战斗步骤可以发动1次。将该对手怪兽破坏。\r\n②：此卡被破坏的情况下可以发动。从牌组将1张“武装转生”加入手牌。','\r',char(13)),'\n',char(10)),'发动','检索','破坏','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95920682,'英豪赠礼','对手LP是２０００点或以下的场合可发动。使对手的LP变成８０００点，并从我方牌组中抽取２张卡牌。“英豪赠礼”１回合只可发动１张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95923441,'三形金字塔猎人',replace(replace('①：场地魔法卡以表侧表示存在的场合，我方除通常召唤以外仅１次，在我方主要阶段可再召唤１只岩石族怪兽。\r\n②：在对手回合１次，可以我方场上的１张“三形金字塔”场地魔法卡为对象发动。将该卡送入墓地，并从牌组发动１张与该卡卡牌名不同的“三形金字塔”场地魔法卡。','\r',char(13)),'\n',char(10)),'场地魔法卡发动','使用「三形金字塔猎人」的效果召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95929069,'冰冻手','①：此卡因对手被破坏并被送至墓地时，以对手场上１张魔法・陷阱卡为对象可以发动。将该对手的卡破坏。然后，可从自己的牌组将１只“火焰手”特殊召唤。','破坏并特殊召唤','是否要特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95937545,'金色的魅惑女王',replace(replace('魔法师族怪兽３只\r\n①：此卡连接召唤的情况下可以发动。从自己牌组・墓地将１只“魅惑女王”怪兽特殊召唤，此卡的攻击力直至下个回合结束时为止上升１５００。\r\n②：原本卡名包含“魅惑女王”的、自己的怪兽所拥有的、将怪兽装备于自身的效果，变为在对手回合也可以发动的效果。\r\n③：１回合１次，对手发动效果时可以发动。将场上的１张卡破坏。此回合中，自己场上的“魅惑女王”怪兽不会因效果被破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95943058,'邪恶－英雄 地狱掠夺者',replace(replace('①：在自己的主要阶段1，将场上的此卡除外，以自己场上的1只恶魔族怪兽为对象可以发动。该自己的恶魔族怪兽只要以表侧表示存在于场上，在1次战斗阶段中可攻击2次。\r\n②：此卡为发动①效果被除外的情况下，在第2次自己的准备阶段发动。将除外状态的此卡以攻击表示特殊召唤。','\r',char(13)),'\n',char(10)),'两次攻击','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95952802,'花狼','“银牙”＋“魔界的荆棘”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95953557,'焰圣骑士－阿斯托尔福','此卡名的①②效果在决斗中仅可各使用１次。①：从自己的手牌・墓地除外１只战士族・炎属性怪兽可以发动。从手牌将此卡特殊召唤。然后，可以使此卡的等级与被除外的怪兽相同。②：将墓地的此卡除外可以发动。在发动后第２次自己准备阶段，将被除外的此卡特殊召唤。然后，可从自己墓地的怪兽及被除外的自己的怪兽中，挑选１只战士族・炎属性怪兽特殊召唤。','','','是否改变等级？','是否特殊召唤另一只怪兽？','','','','','','','','','','','','');
INSERT INTO texts VALUES(95956346,'闪光天使','①：此卡因战斗被破坏且送至墓地时可以发动。从牌组以攻击表示将1只攻击力为1500以下的光属性怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95973569,'T.G.长柄刀爆破手',replace(replace('同步怪兽的协调＋协调以外的同步怪兽２只以上\r\n此卡仅可以同步召唤方式特殊召唤。\r\n①：在自己・对手回合中，以场上１只被从额外牌组特殊召唤的怪兽为对象可以发动（此效果在１回合中最多可使用的次数为作为此卡同步素材的、协调以外的同步怪兽数量）。将该怪兽除外。\r\n②：１回合１次，怪兽以表侧被除外的情况下，以其中１只为对象可以发动。将该怪兽无视召唤条件特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95974848,'超元特防队 时缝保安官','此卡名的②效果１回合仅可使用１次。①：只要此卡存在于怪兽区域，自己的“超元特防队”怪兽正面的对手怪兽不会成为对手效果的对象。②：对手场上的怪兽发动效果时，从手牌将１张“超元特防队”卡除外可以发动。将该怪兽破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95990456,'阴魔罗鬼',replace(replace('此卡名的效果１回合仅可使用１次。\r\n①：此卡因为对手的效果被破坏送往墓地的情况下，或者从墓地特殊召唤成功的情况下可以发动。自己从牌组抽１张卡。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95992081,'虚空海龙 利维埃尔',replace(replace('等级3怪兽×2\r\n①：1回合1次，去除此卡的1个超量素材，以自己或对手除外状态的1只等级4以下的怪兽为对象可以发动。将该怪兽特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(95993388,'地帝家臣兰德罗布',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：以对手场上的1只表侧表示怪兽为对象可以发动。从手牌将此卡特殊召唤，将对象怪兽改成里侧守备表示。此回合，自己不可从额外牌组特殊召唤怪兽。\r\n②：此卡为上级召唤而被解放的情况下，以“地帝家臣兰德罗布”以外的、自己墓地的1只攻击力800/守备力1000的怪兽为对象可以发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96004535,'超量不屈屏障',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：自己场上存在超量怪兽，且怪兽的效果・魔法・陷阱卡发动时可以发动。将该发动无效。然后，可去除自己场上的2个超量素材。该情况下，进而将场上的1张卡破坏。\r\n②：将墓地的此卡除外，以自己场上的1只超量怪兽为对象可以发动。从自己墓地将1只光属性“霍普”超量怪兽作为对象怪兽的超量素材。','\r',char(13)),'\n',char(10)),'发动','成为素材','是否把卡破坏？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96005454,'猎手龙','用锋利的獠牙捕获猎物的龙。虽然经常以犀利的移动发起进攻，但不具备相应的守备能力。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96008713,'魔术臂盾','①：对手场上存在２只或以上表侧表示怪兽，我方场上存在怪兽的场合，在对手怪兽攻击宣言时，可以攻击怪兽以外的对手场上表侧表示的１只怪兽为对象发动。直到战斗阶段结束时获得该表侧表示怪兽的控制权，攻击对象移到该怪兽，并进行伤害计算。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96012004,'幸运机会！','掷１次硬币的怪兽效果发动时发动。猜硬币的正反面。猜中的场合，从牌组抽取１张卡牌。','猜硬币','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96015976,'再转','①：１回合１次，可以场上１只持有等级与原本等级相异的怪兽为对象发动此效果。掷１次骰子。对象怪兽的等级变成与骰子掷出点数相同。','等级变换','是否使用效果？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96026108,'辉龙机巧－左垣四截塔','此卡不可通常召唤，仅可用“龙机巧”卡的效果特殊召唤。此卡名的效果1回合仅可使用1次。①：从自己的手牌・场上，解放此卡以外的1只“龙机巧”怪兽或仪式怪兽可以发动。将此卡从手牌・墓地以守备表示特殊召唤。然后，可从牌组将1张仪式魔法卡加入手牌。发动此效果的回合中，自己仅可特殊召唤不可通常召唤的怪兽。','','是否从牌组把仪式魔法卡加入手牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96029570,'漆黑的太阳',replace(replace('此卡名的①②③效果１回合仅可各使用１次。\r\n \r\n①：自己场上的表侧表示怪兽因战斗・效果被破坏的情况下可以发动。自己的LP恢复相当于该怪兽原本攻击力的合计数值。 \r\n②：怪兽被以表侧表示从自己墓地特殊召唤的情况下，以其中１只为对象可以发动。该怪兽的攻击力上升１０００。 \r\n③：魔法・陷阱卡被从自己手牌舍弃至自己墓地的情况下，以其中１张为对象可以发动。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'基本分回复','攻击力上升','回收魔法·陷阱卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96029574,'黑色残暴龙',replace(replace('协调＋协调以外的二重怪兽1只以上\r\n①：1回合1次，从手牌将1只二重怪兽送至墓地，以对手场上的1张魔法・陷阱卡为对象可以发动。将该对手的卡破坏。\r\n②：此卡被破坏并被送至墓地时，以自己墓地的1只二重怪兽为对象可以发动。将该怪兽特殊召唤。以此效果特殊召唤的二重怪兽变为被再召唤过1次的状态。','\r',char(13)),'\n',char(10)),'破坏','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96030710,'龙装百夫骑士 阿特莉',replace(replace('此卡名的①③效果１回合仅可各使用１次。\r\n①：此卡召唤・特殊召唤的情况下，如果“徽纹”卡与“百夫骑”卡均存在于自己墓地则可以发动。自己抽１张。此回合，自己不可特殊召唤“龙装百夫骑士 阿特莉”。\r\n②：以自己场上的此卡作为同步素材的情况下，可将此卡视为协调以外的怪兽。\r\n③：此卡视为永续陷阱卡的情况下，在自己・对手的主要阶段可以发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'抽1张','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96051150,'阳炎兽 蝎尾狮','只要此卡以表侧表示存在于场上，对手不可将此卡作为卡牌效果的对象。此外，１回合１次，可将手牌或我方场上以表侧表示存在的１只炎属性怪兽送入墓地并发动。该回合，此卡不因卡牌效果而破坏。此效果也可在对手回合发动。','破坏耐性','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96055137,'狱炎机・贝尔芬葛',replace(replace('此卡不可通常召唤。\r\n仅可在自己场上的效果怪兽的等级・阶级的合计为８以下时，将自己的手牌・墓地的２只“狱炎机”怪兽除外的情况下从手牌・墓地特殊召唤。\r\n①：此卡的攻击宣言时可以发动。对手从自身的额外牌组将１只怪兽除外。\r\n②：在每个自己・对手回合中１次，解放自己场上的１只怪兽，以对手墓地的１张卡为对象可以发动。将该卡除外。','\r',char(13)),'\n',char(10)),'除外对手额外牌组的怪兽','除外对手墓地的卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96073342,'源质的星战',replace(replace('“源质的星战”１回合仅可发动１张。\r\n自己的灵摆区域已存在２张“源质”卡的情况下，此卡也可从手牌发动。\r\n①：以自己场上的１张“源质”卡和对手场上的１张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'适用「源质的星战」的效果来发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96084564,'埃尔隆',replace(replace('此卡名在规则上也视为“闪刀”卡。\r\n此卡名的①③效果１回合１次，仅可使用其中１个。\r\n①：在自己・对手的主要阶段，以自己场上的１只“闪刀姬”怪兽为对象可以发动。从自己的手牌・场上将此卡视为装备魔法卡，装备于该怪兽。\r\n②：装备此卡的“闪刀姬”怪兽的攻击力上升４００。\r\n③：场上的此卡被破坏的情况下可以发动。从牌组将１张“闪刀”魔法卡送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96099959,'X－军刀 帕罗姆罗','①：此卡存在于墓地的状态下，自己的“军刀”怪兽因战斗被破坏并被送至墓地时，支付500LP可以发动。将此卡特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96100333,'三形金字塔的觉醒',replace(replace('①：１回合１次，可从我方墓地将岩石族怪兽或场地魔法卡合计共２张除外，并从以下效果选择１个发动。\r\n●可以场上除此卡以外的１张表侧表示卡牌为对象发动。破坏该卡。\r\n●可以我方墓地的１只岩石族怪兽为对象发动。以守备表示特殊召唤该怪兽。\r\n●最多可以我方墓地的３张场地魔法卡为对象发动。将该卡加入牌组并洗牌。之后，我方从牌组抽取１张卡牌。','\r',char(13)),'\n',char(10)),'选择1个效果发动','卡片破坏','从墓地特殊召唤','回收并抽牌','','','','','','','','','','','','');
INSERT INTO texts VALUES(96113307,'圣灵兽骑 蕾伊拉呗里',replace(replace('效果怪兽３只以上\r\n此卡名的②③效果１回合仅可各使用１次。\r\n①：只要此卡存在于怪兽区域，双方不可为发动卡的效果解放卡。\r\n②：以自己除外状态的１张“灵兽”卡为对象可以发动。将该卡放回手牌・额外牌组。然后，可进行手牌的１只“灵兽”怪兽的召唤。\r\n③：在对手回合中，以自己场上的１张“灵兽”卡与对手场上的１张卡为对象可以发动。将该卡除外。','\r',char(13)),'\n',char(10)),'是否把怪兽召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96127902,'极致魅人鱼女仆装的定制',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：以对手墓地的１张卡为对象可以发动。将该卡除外。然后，可从牌组将该卡的１张同名卡加入手牌。','\r',char(13)),'\n',char(10)),'','是否把和除外的卡同名的卡加入手牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96142517,'升阶魔法－千死蛮巧',replace(replace('“升阶魔法－千死蛮巧”１回合仅可发动１张，发动此卡的回合中，自己仅可通过此卡的效果特殊召唤怪兽。\r\n①：以自己及对手墓地的相同阶级超量怪兽各１只以上为对象可以发动。将１只阶级比该怪兽高１的“混沌编号”怪兽或“混沌超量”怪兽从额外牌组特殊召唤，将对象怪兽重叠在其下面作为超量素材。','\r',char(13)),'\n',char(10)),'特殊召唤','是否还要选择更多对象？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96146814,'AD转换者','我方主要阶段时，可将墓地的此卡从游戏中除外，并选择场上的１只怪兽发动。变更被选择怪兽的表示形式。','变更表示形式','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96148285,'诱发召唤','怪兽被特殊召唤至对手场上时可发动。双方可各从手牌特殊召唤１只等级４或以下的怪兽。','是否要从手牌特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96150936,'魔幻甜点见习・鲜果挞修女',replace(replace('“魔幻甜点”怪兽２只\r\n①：只要此卡的连接端存在“魔幻甜点”怪兽，自己场上的“魔幻甜点”魔法・陷阱卡不会因效果被破坏，双方不可将那些卡作为效果的对象。\r\n②：场上的此卡将被战斗・效果破坏的情况下，作为代替可将自己墓地的１只“魔幻甜点”怪兽放回牌组。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96156729,'风魔女之铃音','此卡名的卡１回合仅可发动１张，发动此卡的回合中，自己仅可特殊召唤风属性怪兽。①：以自己场上的１只“风魔女”怪兽为对象可以发动。从牌组将１只卡名与该怪兽不同的“风魔女”怪兽以守备表示特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96157835,'急袭猛禽－武库猎鹰',replace(replace('等级7怪兽×2\r\n①：1回合1次，去除此卡的1个超量素材可以发动。从牌组将1只鸟兽族・等级4的怪兽特殊召唤。②：持有“急袭猛禽”怪兽作为超量素材的此卡在1次战斗阶段中最多可以攻击相当于素材数量的次数。③：持有“急袭猛禽”怪兽作为超量素材的此卡在被送至墓地的情况下可以发动。从额外牌组将1只“急袭猛禽-武库猎鹰”以外的“急袭猛禽”超量怪兽特殊召唤，将墓地的此卡重叠在该超量怪兽下方作为超量素材。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96162588,'六花风花','此卡名的①效果1回合仅可使用1次。①：自己场上的“六花”怪兽被解放的情况下可以发动。对手必须解放自身场上的1只怪兽。②：对手结束阶段，植物族怪兽以外的表侧表示怪兽存在于自己场上的情况下会发动。破坏此卡。','对手必须把自身场上1只怪兽解放','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96163807,'冥界骑士 崔斯坦','①：此卡召唤成功时，以自己墓地１只守备力０的不死族怪兽为对象可以发动。将该卡加入手牌。②：自己场上存在此卡以外的不死族怪兽的情况下，此卡的攻击力上升３００。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96182448,'氮素同步士','①：此卡被使用于“氮素”怪兽的同步召唤，并被送至墓地的情况下发动。自己从牌组抽1张。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96203584,'溟界之大水蛟','此卡名的①②效果１回合仅可各使用１次。①：从自己的手牌・场上将１只怪兽送至墓地，以自己墓地１只原本属性与该怪兽不同的爬虫类族怪兽为对象可以发动。将该怪兽特殊召唤。②：在自己・对手的主要阶段，怪兽被送至对手的墓地的情况下可以发动。从牌组将１只爬虫类族怪兽送至墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96214561,'招神鸟 西摩格','此卡名的①②效果1回合仅可各使用1次。①：此卡召唤成功时可以发动。从牌组将1张“招神鸟 西摩格”以外的“西摩格”卡加入手牌。②：此卡存在于墓地、对手的魔法与陷阱区域没有卡存在的情况下可以发动。将此卡以守备表示特殊召唤。以此效果特殊召唤的此卡离开场上的情况下，将其除外。此效果发动后，直至回合结束时为止自己仅可特殊召唤鸟兽族怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96216229,'剑斗兽的战车','①：自己场上存在“剑斗兽”怪兽，且怪兽的效果发动时可以发动。将该发动无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96218085,'中央突围','可选择我方场上１只冠有“六武众”之名的怪兽并发动。此回合的战斗阶段中，被选择怪兽因战斗破坏对手怪兽的场合，我方场上冠有“六武众”之名的怪兽或“大将军 紫炎”可直接攻击对手玩家。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96220350,'霸胜星韦驮天',replace(replace('等级５或以上的战士族怪兽×２\r\n此卡牌名的①效果１回合只可使用１次。\r\n①：此卡融合召唤成功的场合可发动。从牌组将１只战士族、等级５怪兽加入手牌。\r\n②：１回合１次，可舍弃任意数量之手牌并发动。此卡的攻击力上升相当于舍弃之数量×２００。\r\n③：此卡与持有等级为此卡等级或以下的对手怪兽进行战斗的伤害计算时，可发动１次。该对手怪兽的攻击力仅限于伤害计算时变成０。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96223501,'光卫星骑士－源质图邦',replace(replace('←1 【灵摆】 1→\r\n①：自己仅可灵摆召唤“星骑士”怪兽及“源质”怪兽。此效果不会被无效化。\r\n【怪兽效果】\r\n此卡名的怪兽效果１回合仅可使用１次。①：此卡召唤・反转召唤・灵摆召唤成功的情况下，以此卡以外的、自己的怪兽区域・灵摆区域的１张“星骑士”卡或“源质”卡，和对手场上的１张表侧表示的卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96227613,'霸王门 零',replace(replace('←0 【灵摆】 0→\r\n①：自己场上存在“霸王龙扎克”的情况下，自己将受到的所有伤害变为０。\n②：１回合１次，另一方自己的灵摆区域存在“霸王门 无限”的情况下可以发动。将自己的灵摆区域的２张卡破坏，从牌组将１张“融合”魔法卡或“结合”魔法卡加入手牌。\r\n【怪兽效果】\r\n①：１回合１次，以自己场上此卡以外的１张表侧表示卡为对象可以发动。将该卡和此卡破坏，从额外牌组将１只龙族融合怪兽或龙族同步怪兽特殊召唤。以此效果特殊召唤的怪兽的攻击力・守备力变为０，效果无效化，不可作为同步・超量召唤的素材。\n②：怪兽区域的此卡因战斗・效果被破坏的情况下可以发动。将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96228804,'恩底弥翁之圣月皇太子 雷格鲁斯',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡存在于手牌的情况下，向对手出示手牌的1只其他魔法师族怪兽可以发动。自己失去所出示的怪兽的等级×300LP，将此卡特殊召唤。\r\n②：此卡特殊召唤的情况下可以发动。从牌组将1张记载有“恩底弥翁之圣月皇太子 雷格鲁斯”卡名的魔法卡加入手牌。\r\n③：此卡1回合仅1次，不会因战斗被破坏。','\r',char(13)),'\n',char(10)),'特殊召唤','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96235275,'光道圣战士 简','此卡在攻击对手怪兽的伤害步骤期间，此卡的攻击力上升３００点。此外，在每次我方的结束阶段发动。从我方牌组的上方依序将２张卡牌送入墓地。','从牌组送2张卡去墓地','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96235944,'炼狱的决界',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：自己场上的“狱炎机”怪兽的攻击力上升相当于自己除外状态的“狱炎机”怪兽数量×１００的数值。\r\n②：自己场上的怪兽，不存在的情况下或仅有恶魔族怪兽的情况下，可从以下效果中选择１个发动。\r\n●将自己除外状态的１只“狱炎机”怪兽加入手牌。\r\n●从手牌将１只“狱炎机”怪兽无视召唤条件特殊召唤。','\r',char(13)),'\n',char(10)),'除外状态的怪兽加入手牌','从手牌把怪兽特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96239878,'集结之力','此卡名的①②效果１回合仅可各使用１次。①：自己使用了“青眼白龙”或“黑魔导”的仪式・融合召唤成功的情况下，以对手场上・墓地的１张卡为对象可以发动。将该卡除外。②：将魔法与陷阱区域的表侧表示的此卡送至墓地，以自己墓地１只等级７以上的通常怪兽为对象可以发动。将该怪兽加入手牌或放回牌组。','卡片除外','回收墓地','回到牌组','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96287685,'瓶龟','只要此卡以表侧表示存在于场上，“强欲之瓶”每次发动，从我方牌组抽取１张卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96300057,'W－飞翼弹射器','１回合１次，可在我方的主要阶段时，将此卡作为装备卡装备至我方的“V－猛虎喷射机”上，或者解除装备状态以表侧攻击表示特殊召唤此卡。以此效果变为装备卡的场合，装备怪兽的攻击力和守备力上升４００点。（１只怪兽最多只可装备１张联合。装备怪兽因战斗而被破坏的场合，破坏此卡来代替。）','装备','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96305350,'黄金荣耀－船长卡莉',replace(replace('此卡名的①②③效果１回合仅可各使用１次。\r\n①：自己的LP少于对手的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从牌组将１张“黄金荣耀”陷阱卡加入手牌。\r\n③：此卡被送至墓地的情况下，以自己场上被从额外牌组特殊召唤的１只“黄金荣耀”怪兽为对象可以发动。从自己的墓地将最多３张“黄金荣耀”卡除外，对象怪兽的攻击力上升相当于所除外数量×５００的数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96316857,'回收','可在我方回合的准备阶段时支付３００LP并发动。从我方墓地选择１张魔法、陷阱卡并返回至牌组的最下方。','返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96331676,'宝玉的祈祷','可将我方魔法与陷阱区域的１张冠有“宝玉兽”之名的卡牌送入墓地并发动。选择对手场上的１张卡牌破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96334243,'忒修斯的魔栖物','协调×２','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96345184,'无穷之三幻魔－幻魔皇拉比艾尔',replace(replace('此卡不可通常召唤，仅可通过“三幻魔”卡的效果特殊召唤。\r\n此卡名的①效果1回合仅可使用1次。\r\n①：向对手出示手牌的此卡可以发动。从牌组将“无穷之三幻魔－幻魔皇拉比艾尔”以外的1只“三幻魔”怪兽加入手牌。然后，挑选自己的1张手牌舍弃。\r\n②：在每个自己・对手回合中1次，解放自己场上的其他2只“三幻魔”怪兽可以发动。将对手场上的怪兽全部破坏，此卡的攻击力上升所破坏的数量×1000的数值。','\r',char(13)),'\n',char(10)),'检索效果','破坏效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96345188,'急袭猛禽－仿声伯劳','此卡名的②效果1回合仅可使用1次。①：在此卡召唤・特殊召唤成功的回合的自己的主要阶段仅限1次可以发动。自己场上的所有“急袭猛禽”怪兽的等级上升1。②：在此卡被送至墓地的回合的自己的主要阶段，将墓地的此卡除外可以发动。从牌组将1张“急袭猛禽-仿声伯劳”以外的“急袭猛禽”卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96352326,'太阳魔术师 艾达',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・反转的情况下可以发动。从手牌・牌组将“太阳魔术师 艾达”以外的1只守备力1500的魔法师族怪兽以里侧守备表示特殊召唤。\r\n②：在对手的主要阶段可以发动。将自己场上的1只里侧表示的魔法师族怪兽改成表侧攻击表示或表侧守备表示。','\r',char(13)),'\n',char(10)),'特殊召唤','改变表示形式','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96352712,'夸大化',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：怪兽之间进行战斗的伤害步骤开始时，可从以下效果中选择１个发动。\r\n●将该攻击怪兽改成守备表示。\r\n●将该攻击对象怪兽放回手牌。\r\n●将该２只进行战斗的怪兽破坏。','\r',char(13)),'\n',char(10)),'','那只攻击怪兽变成守备表示','那只攻击对象怪兽回到手牌','那2只进行战斗的怪兽破坏','','','','','','','','','','','','');
INSERT INTO texts VALUES(96355986,'神圣标枪','对手怪兽的攻击宣言时可发动。我方将回复相当于１只该攻击怪兽的攻击力的LP。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96363153,'调律','①：从牌组将1只“同步士”协调加入手牌。然后，将自己牌组最上面的卡送至墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96363154,'调律','①：从牌组将1只“同步士”协调加入手牌。然后，将自己牌组最上面的卡送至墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96367119,'疾黑崇高','此卡名的①②效果１回合１次，仅可使用其中１个。①：魔法・陷阱卡发动时，去除自己场上的１个黑羽计数物可以发动。将该发动无效并破坏。②：自己场上存在“黑翼龙”的情况下可以发动。将墓地的此卡放置在自己场上。以此效果放置的此卡从场上离开的情况下，将其除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96378317,'铁兽之相遇','此卡名的①②效果１回合仅可各使用１次。①：以自己场上任意数量连接状态的兽族・兽战士族・鸟兽族怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止上升７００。②：自己场上连接状态的兽族・兽战士族・鸟兽族怪兽将被战斗・效果破坏的情况下，可将墓地的此卡除外作为代替。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96380700,'答语枪兵',replace(replace('等级2以下电子界族怪兽1只\r\n此卡名的效果1回合仅可使用1次。①：解放此卡以外的1只自己场上的电子界族怪兽，以与该怪兽原本卡名不同的自己墓地的1只“码语者”怪兽为对象可以发动。将该怪兽特殊召唤至此卡连接端的自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96381979,'魁炎星王－宋虎',replace(replace('兽战士族等级4怪兽×2\r\n①：此卡超量召唤时可以发动。从牌组将1张“炎舞”魔法・陷阱卡放置在自己场上。\r\n②：1回合1次，去除此卡的1个超量素材可以发动。兽战士族以外的场上的所有效果怪兽的效果直至对手回合结束时为止无效化。\r\n③：此卡从场上被送至墓地时，将自己场上的3张表侧表示“炎舞”魔法・陷阱卡送至墓地可以发动。从牌组将2只等级4以下且攻击力相同的兽战士族怪兽以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'放置','效果无效','特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96383838,'三骨地带','选择我方墓地中３只等级２以下的通常怪兽来发动此卡。从墓地特殊召唤所选择怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96384007,'机甲部队・防卫兵','①：此卡反转的情况下发动。从牌组将１只“督战官 科温顿”加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96385345,'蔷薇的圣骑士',replace(replace('“蔷薇的圣骑士”的②效果１回合只可使用１次。\r\n①：此卡因战斗破坏对手怪兽并送入墓地时，可解放此卡并发动。从手牌・牌组以守备表示特殊召唤１只植物族怪兽。\r\n②：可将此卡从手牌送入墓地并发动。从牌组将１只等级７以上的植物族怪兽加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96399967,'机巧鸟－常世宇受卖长鸣','此卡名的①②效果１回合仅可各使用１次。①：解放自己场上１只攻击力和守备力的数值相同的机械族怪兽可以发动。将１只攻击力和守备力的数值相同、等级低于所解放怪兽的机械族怪兽从牌组特殊召唤。②：将墓地的此卡除外可以发动。从被里侧表示除外的自己的卡中，挑选１只攻击力和守备力的数值相同的机械族怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96402918,'冰灵山龙祖 矛枪龙',replace(replace('水属性协调＋协调以外的怪兽１只以上\r\n此卡名的①效果１回合最多可使用２次。\r\n①：对手特殊召唤怪兽的情况下可以发动（同一连锁上最多１次）。从自己的手牌・牌组・额外牌组・墓地将１只“冰结界”怪兽特殊召唤。然后，可将对手场上的１只攻击表示怪兽改成守备表示。\r\n②：同步召唤的、表侧表示的此卡因对手从场上离开的情况下可以发动。从额外牌组将１只“冰结界”同步怪兽视为同步召唤来特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','特殊召唤同步怪兽','是否把1只对手怪兽变成守备表示？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96404912,'无偿交换','①：对手发动怪兽效果时可以发动。将该发动无效并破坏。对手抽1张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96420087,'与暗的支配者的契约',replace(replace('用于召唤“暗的支配者－佐克”。\r\n①：从我方的手牌・场上解放合计等级８以上的怪兽，从手牌仪式召唤“暗的支配者－佐克”。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96427353,'机甲忍者水','对手怪兽直接攻击宣言时，我方墓地存在有除此卡以外的冠有“忍者”之名怪兽的场合，可将墓地的此卡从游戏中除外并发动。选择１只攻击怪兽，使该攻击无效。','攻击无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96428622,'人工脑独眼巨人','只要我方手牌数量为０，此卡的攻击力上升１０００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96433300,'溟界之虚','此卡名的①效果1回合仅可使用1次。①：在自己・对手的主要阶段，解放自己场上的1只爬虫类族效果怪兽，以对手墓地的1只怪兽为对象可以发动。将该怪兽特殊召唤至自己场上。以此效果特殊召唤的怪兽将在结束阶段被送至墓地。②：魔法与陷阱区域的表侧表示的此卡被送至墓地的情况下发动。将自己场上爬虫类族怪兽以外的表侧表示怪兽全部送至墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96434581,'戴冠・圣骑联盟','此卡名的卡1回合仅可发动1张。①：以自己场上的1只“圣骑联盟”怪兽为对象可以发动。此回合，该“圣骑联盟”怪兽不受自身以外的卡的效果影响。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96457619,'超量遮罩','只要此卡存在于场上，双方玩家不可将持有超量素材的超量怪兽作为卡牌效果的对象。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96458440,'传说的黑带','仅限装备我方场上的“格斗鼠 吱助”“僧侣斗士”“僧侣大师”。装备怪兽因战斗破坏对手怪兽并将其送入墓地时，给予对手生命相当于被破坏怪兽原本守备力数值的伤害。','LP伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96462121,'超接地展开','①：自己场上的机械族超量怪兽不会成为对手效果的对象。②：１回合１次，以自己场上的１只“无限起动”超量怪兽为对象可以发动。将１只阶级比该自己的怪兽高２的机械族超量怪兽重叠在对象怪兽上面，视为超量召唤从额外牌组特殊召唤。此效果发动后，直至回合结束时为止，自己仅可特殊召唤机械族・地属性怪兽。','升阶','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96470883,'凛天使蔷薇女王','此卡可释放１只植物族怪兽并以攻击表示上级召唤此卡。我方准备阶段时仅１次，破坏场上１只攻击力最低的表侧表示怪兽。','用1只植物族怪兽解放召唤','攻击力最低的怪兽破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96471335,'幻想黑之魔导师',replace(replace('等级７怪兽×２\r\n此卡也可重叠在自己场上阶级６魔法师族超量怪兽上面来超量召唤。此卡名的②效果１回合仅可使用１次。①：１回合１次，去除此卡的１个超量素材可以发动。从手牌・牌组将１只魔法师族通常怪兽特殊召唤。②：魔法师族通常怪兽的攻击宣言时，以对手场上的１张卡为对象可以发动。将该卡除外。','\r',char(13)),'\n',char(10)),'是否要在自己场上的6阶的魔法师族超量怪兽上面重叠来超量召唤？','特殊召唤','除外','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96474800,'魔法偏转器','①：此回合中，场上的装备・场地・永续・速攻魔法卡的效果无效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96501677,'木天蓼猫','我方场上存在有其他兽族怪兽的场合，对手怪兽不可攻击此卡。１回合１次，可选择对手场上的１只表侧表示怪兽并发动。直至回合结束时，被选择对手怪兽的守备力变成０。','守备变换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96540807,'再世原初战神 贝凌席特',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次，且②③效果1回合仅可各使用1次。\r\n①：场上存在原本攻击力或原本守备力为2500的怪兽的情况下，此卡可从手牌特殊召唤。\r\n②：在自己・对手回合中，解放此卡，以对手场上的1只怪兽为对象可以发动。将该怪兽放回手牌。\r\n③：在此卡被送至墓地的对手回合，于结束阶段可以发动。将此卡加入手牌。','\r',char(13)),'\n',char(10)),'','回到手牌','回收','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96546575,'大要塞鲸',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：场上存在“海”的情况下可以发动。此回合中，自己的水属性怪兽可直接攻击。\r\n②：在对手的战斗阶段，以对手场上的1只表侧表示怪兽为对象可以发动。将该怪兽破坏。\r\n③：场上的此卡因战斗・效果被破坏的情况下可以发动。从自己牌组・墓地挑选1只战士族・水属性怪兽，加入手牌或特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96553688,'凤凰花种','可将场上的此卡送入墓地并发动。从手牌特殊召唤１只“凤凰彼岸花”。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96561011,'真红眼暗龙','此卡不可进行通常召唤。仅限解放我方场上的１只“真红眼黑龙”的场合可特殊召唤。此卡的攻击力上升我方墓地的龙族怪兽数量×３００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96565487,'暴风雪战士','①：此卡战斗破坏对手怪兽的情况下发动。确认对手牌组最上面的卡，放回牌组最上面或最下面。','确认牌组','返回牌组最上面','返回牌组最下面','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96570609,'天帝埃忒耳',replace(replace('此卡可以通过解放1只上级召唤的怪兽来上级召唤。\r\n①：此卡上级召唤的情况下可以发动。从手牌・牌组将2种“帝王”魔法・陷阱卡各1张送至墓地，从牌组将1只攻击力2400以上且守备力1000的怪兽特殊召唤。以此效果特殊召唤的怪兽将在结束阶段被放回手牌。\r\n②：此卡存在于手牌的情况下，在对手的主要阶段，从自己墓地将1张“帝王”魔法・陷阱卡除外可以发动（同一连锁上最多1次）。进行此卡的上级召唤。','\r',char(13)),'\n',char(10)),'把1只上级召唤的怪兽解放作上级召唤','特殊召唤','上级召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96576187,'光道恶魔 拜斯',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：从手牌将１张其他的“光道”卡放回牌组最上面可以发动。从手牌将此卡特殊召唤。然后，从自己的牌组上面将２张卡送至墓地。\r\n②：此卡被从牌组送至墓地的情况下，以自己墓地“光道恶魔 拜斯”以外的１只“光道”怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'从手牌特殊召唤','从墓地特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96592102,'急袭猛禽－燃刃猎鹰',replace(replace('鸟兽族等级４怪兽×２\r\n①：自己的LP比对手少３０００以上，此卡超量召唤成功的情况下可以发动。此卡的攻击力上升３０００。\r\n②：此卡以战斗破坏对手怪兽时，去除此卡任意数量的超量素材可以发动。依去除的超量素材的数量，挑选对手场上怪兽破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96594609,'炎王兽 麒麟',replace(replace('①：自己场上的表侧表示“炎王”怪兽因效果被破坏的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：此卡被破坏并被送至墓地的情况下可以发动。从牌组将１只炎属性怪兽送至墓地。','\r',char(13)),'\n',char(10)),'特殊召唤','送墓','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96598015,'金满之壶','此卡名的卡１回合仅可发动１张，发动此卡的回合中，自己不可进行灵摆召唤以外的特殊召唤。①：从自己的额外牌组的表侧表示灵摆怪兽及自己墓地的灵摆怪兽中挑选合计３只，放回牌组并洗牌。然后，自己从牌组抽２张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96606246,'娱乐伙伴朋友驴','①：此卡召唤成功时可发动。从我方手牌、墓地挑选１只等级４或以下的“娱乐伙伴”怪兽并特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96622984,'捕食植物 苍蝇地狱',replace(replace('①：1回合1次，以对手场上的1只表侧表示怪兽为对象可以发动。在该怪兽上放1个捕食计数物。放有捕食计数物的等级2以上怪兽的等级变为1。\r\n②：此卡与等级在此卡等级以下的怪兽进行战斗的伤害步骤开始时可以发动。将该怪兽破坏。然后，依所破坏怪兽的原本等级，此卡的等级上升。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96631852,'铁壁的布阵','可选择１只我方场上的怪兽并发动此卡。我方场上存在有２只或以上的怪兽，且该怪兽全部是守备表示的场合，被选择怪兽的守备力上升７００点。被选择怪兽从场上离开时，破坏此卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96633955,'相剑大公－承影',replace(replace('协调＋１只以上协调以外的怪兽\r\n此卡名的③效果１回合仅可使用１次。①：依被除外的卡数量×１００的数值，此卡的攻击力・守备力上升，对手场上怪兽的攻击力・守备力下降。②：此卡将被效果破坏的情况下，可将自己墓地的１张卡除外作为代替。③：卡被除外的情况下可以发动。挑选对手场上及墓地的卡各１张除外。','\r',char(13)),'\n',char(10)),'选对手两张卡除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96637156,'席取－六双丸',replace(replace('等级６怪兽×２\r\n①：在对手的战斗阶段开始时发动。摇１次骰子。在双方的主要怪兽区域内，从此卡开始按顺时针方向的下１个区域算起，划分为１～６，将主要怪兽区域的此卡移动至摇出的数字的区域。移动端有怪兽存在的情况下，将其重叠在此下面作为超量素材（是拥有超量素材的怪兽的情况下，将那些全部重叠）。此超量素材超过６个时，自己获得决斗的胜利。无法移动的情况下，或无法将移动端的怪兽作为超量素材的情况下，将此卡送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96643568,'气象精灵','操纵雨的精灵。可以召唤台风，吹走各种东西。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96653775,'大植然南瓜','对方场上存在有怪兽的场合，且此卡召唤成功时，可从手牌特殊召唤１只冠有“大植然”之名的怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96661780,'守护者的力量',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己的LP少于对手的情况下，以自己场上原本卡名包含“门之守护者”的１只怪兽为对象可以发动。将对手的LP改成一半。然后，依对手LP的数值上升对象怪兽的攻击力。\r\n②：将墓地的此卡除外可以发动。将自己的牌组・除外状态的“雷魔神－桑迦”、“风魔神－休迦”、“水魔神－苏迦”中的任意１只加入手牌。','\r',char(13)),'\n',char(10)),'对手基本分变成一半','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96676583,'码丽丝＜兵＞柴郡猫',replace(replace('此卡名的①③效果1回合仅可各使用1次。\r\n①：在自己的主要阶段可以发动。从手牌挑选1张“码丽丝”卡除外。然后，自己可抽2张。\r\n②：连接端指向此卡的“码丽丝”连接怪兽战斗破坏的怪兽不去墓地而直接被除外。\r\n③：此卡被除外的情况下，支付300LP可以发动。将此卡特殊召唤。此回合，自己从额外牌组仅可特殊召唤连接怪兽。','\r',char(13)),'\n',char(10)),'除外并抽牌','','特殊召唤','是否抽牌？','','','','','','','','','','','','');
INSERT INTO texts VALUES(96677818,'魔导书整理','确认我方牌组上面的３张卡牌，按照喜好顺序返回至牌组上面。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96682430,'水精鳞－邃渊希德',replace(replace('此卡名的效果１回合仅可使用１次。\r\n①：此卡被送至墓地的情况下可以发动。从手牌将“水精鳞－邃渊希德”以外的１只“水精鳞”怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96687733,'神殿的守护神',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：将自己手牌・场上的怪兽作为融合素材，将1只地属性融合怪兽融合召唤。要将记载有“王家的神殿”卡名的自己场上的怪兽作为融合素材的情况下，可将对手场上的表侧表示怪兽也作为融合素材。\r\n②：自己场上存在“王家的神殿”的情况下，将墓地的此卡除外可以发动。从牌组将1张“神之怒”加入手牌。','\r',char(13)),'\n',char(10)),'','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96693371,'幻影－英雄 倍增魔侠','此卡名的①②③效果１回合仅可各使用１次。①：自己因战斗・效果受到伤害的情况下可以发动。将墓地的此卡视为永续陷阱卡，以表侧表示放在自己的魔法与陷阱区域。②：此卡视为永续陷阱卡的情况下，在双方的主要阶段，解放自己场上的１只“－英雄”怪兽可以发动。将此卡特殊召唤。③：从魔法与陷阱区域将此卡特殊召唤成功的情况下可以发动。挑选场上的１只怪兽，其攻击力上升８００。','此卡当作永续陷阱卡放置','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96699830,'降生自天龙座','发动此卡的回合中，自己不可用此卡效果之外的方法特殊召唤怪兽。①：从自己的墓地及自己场上的表侧表示怪兽中将机械族・光属性怪兽全部除外可以发动。从手牌将1只等级6以上的机械族・光属性怪兽无视召唤条件特殊召唤。以此效果特殊召唤的怪兽的攻击力・守备力数值变为为发动此卡除外的怪兽数量×500，不受自身以外的卡效果的影响。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96700602,'波动障壁','对手怪兽的攻击宣言时，解放自己场上的１只同步怪兽可以发动。将对手场上所有攻击表示怪兽变更为守备表示。然后，给予对手LP进行了该攻击宣言的怪兽的守备力数值的伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96704018,'纹章兽 伯纳斯猎鹰','①：此卡召唤・反转召唤・特殊召唤时可以发动。将自己场上的所有等级5以上怪兽的等级改成4。','等级变换','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96704974,'诡乐陷阱',replace(replace('此卡牌名的卡牌１回合只可发动１张。\r\n①：可舍弃２张手牌，并以我方墓地的１张陷阱卡为对象发动。将该卡盖牌于我方场上。以此效果盖牌的卡牌在盖牌的回合也可发动。','\r',char(13)),'\n',char(10)),'适用「诡乐陷阱」的效果来发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96708940,'疾行机人 玻璃球机器',replace(replace('←1 【灵摆】 1→\r\n①：1回合1次，自己的守备表示怪兽被选择为攻击对象时可以发动。将该怪兽改为表侧攻击表示。此回合，该怪兽不会因战斗被破坏。\r\n【怪兽效果】\r\n此卡名的怪兽效果1回合仅可使用1次。①：此卡召唤成功时可以发动。从牌组将1只“疾行机人”怪兽加入手牌。此效果发动后，直至回合结束时为止自己仅可特殊召唤风属性怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96729612,'仪式的准备','①：从牌组将1只等级7以下的仪式怪兽加入手牌。然后，可从自己墓地将1张仪式魔法卡加入手牌。','是否把1张仪式魔法卡加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96733134,'霸王眷龙 异色眼',replace(replace('←4 【灵摆】 4→\r\n①：解放自己场上的１只“霸王眷龙”怪兽可以发动。将此卡破坏，从牌组将１只攻击力１５００以下的灵摆怪兽加入手牌。\r\n【怪兽效果】\r\n①：解放自己场上的２只“霸王眷龙”怪兽可以发动。从手牌将此卡特殊召唤。\n②：自己的灵摆怪兽与对手怪兽进行战斗的情况下，给予对手的战斗伤害变为两倍。\n③：在自己・对手的战斗阶段解放此卡可以发动。从自己的额外牌组（表侧）将“霸王眷龙 异色眼”以外的“霸王眷龙”灵摆怪兽或“霸王门”灵摆怪兽合计最多２只以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'牌组检索','解放「霸王眷龙」怪兽特殊召唤','额外牌组怪兽特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96746083,'真龙皇 炽神焰兽 消隐','这张卡的①②的效果1个回合各只能使用1次。①：在自己主要阶段可以发动。从这张卡以外的手牌以及自己场上的表侧表示怪兽中挑选包含炎属性怪兽在内的2只怪兽进行破坏，将这张卡从手牌进行特殊召唤，破坏2只炎属性怪兽的情况下，可以从对手的场上・墓地挑选1只怪兽除外。②：这张卡被效果破坏的情况下可以发动。从自己墓地挑选1只炎属性以外的幻龙族怪兽加入手牌。','是否选怪兽除外？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96765646,'回忆的秋千','①：可以我方墓地中的１只通常怪兽为对象发动此卡。特殊召唤该怪兽。以此效果特殊召唤的怪兽会在该回合的结束阶段被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96782886,'心灵主宰',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：支付800LP，解放自己场上的1只念动力族怪兽可以发动。从牌组将1只等级4以下的念动力族怪兽以攻击表示特殊召唤。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96789758,'芬芳法师－茉莉',replace(replace('①：只要自己的LP多于对手，且此卡存在于怪兽区域，自己除通常召唤外仅可追加１次，在自己的主要阶段召唤“芬芳法师－茉莉”以外的１只植物族怪兽。\r\n②：１回合１次，自己的LP恢复的情况下发动。自己抽１张。','\r',char(13)),'\n',char(10)),'使用「芬芳法师-茉莉」的效果召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96795312,'武之贤者－阿卡丝',replace(replace('此卡名在规则上也视为“闪刀”卡。\r\n此卡名的①②③效果１回合仅可各使用１次。\r\n①：从手牌将１张魔法卡舍弃可以发动。从手牌将此卡特殊召唤。\r\n②：自己场上的连接怪兽将被战斗・效果破坏的情况下，作为代替可将自己墓地的１张魔法卡除外。\r\n③：此卡因战斗・效果被破坏并被送至墓地的情况下，以自己除外状态的１张“闪刀”魔法卡为对象可以发动。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96802306,'点火骑士・点五零',replace(replace('←2 【灵摆】 2→\r\n①：另一方自己的灵摆区域存在“点火骑士”卡的情况下可以发动。将自己的灵摆区域的２张卡破坏，从自己的牌组・墓地将１只战士族・炎属性怪兽加入手牌。\r\n【怪兽效果】\r\n将意气风发的点火骑士们团结起来的特攻队长。对于时常因血气翻滚而冲动行事的部下们总是十分头疼。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96823189,'骄傲与灵魂之龙',replace(replace('此卡不可通常召唤。\r\n仅可在对手墓地存在２５张以上的卡的情况下特殊召唤。\r\n①：只要自己墓地存在２５张以上的卡，此卡的攻击力・守备力上升２５００。','\r',char(13)),'\n',char(10)),'攻击力·守备力上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96851799,'刺焰球','一团炽热的火球。会用其身体与对手正面相撞。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96857854,'钻石尘小妖',replace(replace('①：场上的卡因战斗・效果被破坏时可以发动。依其破坏的卡的数量，从牌组挑选“尘小妖”怪兽特殊召唤至自己・对手场上。\r\n②：此卡存在于墓地的情况下仅１次，将自己墓地的１只“尘小妖”怪兽除外可以发动。此卡变为通常怪兽（恶魔族・暗・星１・攻０／守１０００），以守备表示特殊召唤至对手的怪兽区域（不视为陷阱卡）。以此效果特殊召唤的此卡不可解放，也不可作为融合・同步・超量召唤的素材。','\r',char(13)),'\n',char(10)),'是否在对手场上特殊召唤？','此卡特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96864105,'混沌编号73 激泷瀑神 邃渊涌溅',replace(replace('等级６怪兽×３\r\n①：每次自己的怪兽与对手怪兽进行战斗的伤害计算时１次，去除此卡的１个超量素材可以发动。该自己的怪兽的攻击力仅在该伤害计算时上升相当于该对手怪兽的攻击力的数值。\r\n②：此卡持有“编号73 激泷神 邃渊飞溅”作为超量素材的情况下，获得以下效果。\r\n●此卡不会因效果被破坏。','\r',char(13)),'\n',char(10)),'攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96864811,'禁忌的圣衣','①：以场上的1只表侧表示怪兽为对象可以发动。该怪兽直至回合结束时为止，攻击力下降600，不会因效果被破坏，双方不可将该怪兽作为效果的对象。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96872283,'进甲骑士 谢瓦利埃',replace(replace('此卡存在于墓地或以表侧表示存在于场上的场合，将被视为通常怪兽。以通常召唤的方式再次召唤场上表侧表示的此卡，此卡将视为效果怪兽并获得以下效果。\r\n●将以表侧表示存在于我方场上的１张装备卡送入墓地，破坏对手场上的１张卡牌。','\r',char(13)),'\n',char(10)),'破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96875080,'大气层外射击','可将我方场上的１只冠有“外星人”之名的怪兽送入墓地并发动。选择场上的１张魔法、陷阱卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96890582,'秒杀之暗杀者','此卡的攻击力、守备力下降我方手牌张数×４００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96891787,'教导之铁槌 提奥','此卡名的①③效果１回合仅可各使用１次。①：场上有被从额外牌组特殊召唤的怪兽存在的情况下可以发动。从手牌将此卡特殊召唤。②：此卡不会因与从额外牌组中被特殊召唤的怪兽的战斗而被破坏。③：以场上１只从额外牌组中被特殊召唤的表侧表示怪兽为对象可以发动。直至回合结束时为止，此卡的攻击力上升６００，对象怪兽的攻击力下降６００。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96897184,'古生代化石骑士 骷髅王',replace(replace('岩石族怪兽＋等级７以上的怪兽\r\n此卡仅可通过“化石融合”的效果从额外牌组中特殊召唤。\r\n此卡名的效果③在１个回合中仅可使用１次。\r\n①：此卡在１个战斗阶段中可以进行２次攻击。\r\n②：此卡攻击了守备表示的怪兽时，将对其造成战斗伤害，数值为此卡攻击力超出该怪兽守备力的部分。\r\n③：在对手回合中，可以以对手墓地的１只怪兽为对象发动。选择１张自己的手牌扔掉，将对象怪兽特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96907086,'地缚旋风','我方场上有冠有“地缚神”之名的怪兽存在的场合可发动此卡。破坏对手场上的所有魔法・陷阱卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96914272,'虚荣的大猿',replace(replace('此卡不可通常召唤。从手牌将１只兽族怪兽送入墓地的场合可特殊召唤。以此方法特殊召唤成功时，可从以下效果选择１个发动。\r\n●此卡等级上升相当于送入墓地的该怪兽的等级数值。\r\n●此卡等级下降相当于送入墓地的该怪兽的等级数值。','\r',char(13)),'\n',char(10)),'选择效果发动','等级上升送至墓地的兽族怪兽的等级','等级下降送至墓地的兽族怪兽的等级','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96915510,'魔神仪之创造主－祭坛造物者','以“魔神仪的祝诞”降临。此卡名的①效果1回合仅可使用1次。①：在自己・对手的主要阶段，向对手出示手牌中的此卡可以发动。挑选1张手牌舍弃，然后从自己的墓地挑选等级合计为10的“魔神仪”怪兽特殊召唤。以此效果特殊召唤的怪兽将在结束阶段被放回持有者的牌组。②：只要此卡存在于怪兽区域，仪式怪兽以外的自己场上“魔神仪”怪兽攻击力上升2000，效果无效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96930127,'锁链狗','以此卡为同步素材的场合，只可使用于兽族怪兽的同步召唤。我方场上的兽族怪兽是２的只场合，可从墓地特殊召唤此卡。以此效果特殊召唤的此卡从场上离开的场合，从游戏中被除外。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96938777,'神机王乌尔',replace(replace('①：此卡可对所有对手怪兽各进行１次攻击。\r\n②：此卡进行战斗的场合，对手所受到的战斗伤害变成０。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96938986,'共振虫',replace(replace('①：此卡从场上被送至墓地的情况下可以发动。从牌组将１只等级５以上的昆虫族怪兽加入手牌。\r\n②：此卡被除外的情况下可以发动。从牌组将“共振虫”以外的１只昆虫族怪兽送至墓地。','\r',char(13)),'\n',char(10)),'牌组检索','送墓','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96945958,'疾行机人 歌牌涡轮','此卡名的①②效果1回合仅可各使用1次。①：在自己场上有风属性怪兽存在的情况下可以发动。从手牌将此卡特殊召唤。此效果发动后，直至回合结束时为止，自己不可发动风属性以外的怪兽的效果。②：从自己的墓地将此卡和1只“疾行机人”怪兽除外可以发动。自己场上的所有风属性怪兽的攻击力直至回合结束时为止上升800。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96947648,'打捞','①：以自己墓地的2只攻击力1500以下的水属性怪兽为对象可以发动。将该水属性怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96965364,'孵化','①：解放自己场上的１只怪兽可以发动。从牌组将１只等级比所解放的怪兽高１的昆虫族怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96967123,'大炮达摩','被大炮塞满的机械达摩不倒翁，从不会射偏目标。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(96981563,'食炎大龟','以鲜红色的龟甲为特征的大龟。据说能够吞食火焰。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97000273,'废铁金刚','①：此卡召唤成功的情况下发动。将此卡破坏。②：此卡因“废铁”卡的效果被破坏并被送至墓地的情况下，以自己墓地“废铁金刚”以外的１只“废铁”怪兽为对象可以发动。将该怪兽加入手牌。','此卡破坏','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97001138,'黑暗升级',replace(replace('“黑暗升级”１回合只可发动１张。\r\n①：可在我方、对手的主要阶段及战斗阶段，以１只我方墓地攻击力２４００或以上、守备力１０００的怪兽为对象发动。将该怪兽加入手牌。之后，可以表侧攻击表示从手牌上级召唤１只攻击力２４００或以上守备力１０００的怪兽。','\r',char(13)),'\n',char(10)),'是否把怪兽上级召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97007933,'高速疾行机人 魔剑玉',replace(replace('协调+1只以上协调以外的怪兽\r\n此卡名的②③效果1回合仅可各使用1次。①：此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予战斗伤害。②：将自己墓地的1只机械族怪兽除外可以发动。给予对手500伤害。③：此卡存在于墓地，自己场上不存在卡的情况下可以发动。将此卡特殊召唤。发动此效果的回合中，自己不可通常召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97017120,'巨大老鼠','①：此卡因战斗被破坏并被送至墓地时可以发动。从牌组将１只攻击力１５００以下的地属性怪兽以攻击表示特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97021916,'暗黑共鸣者','①：此卡１回合仅１次，不会因战斗被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97023549,'冰刀滑雪手','冰上的舞姬，华丽的战士。以必杀技－阿克塞尔切裂华丽地将敌人切开。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97024987,'点火骑士・德拉古诺夫',replace(replace('←7 【灵摆】 7→\r\n①：另一方自己的灵摆区域存在“点火骑士”卡的情况下可以发动。将自己的灵摆区域的２张卡破坏，从自己的牌组・墓地将１只战士族・炎属性怪兽加入手牌。\r\n【怪兽效果】\r\n刚强正直讨厌扭曲之事、点火骑士的老练战士。可能是其性格使然，最近对自己的武器开始产生了疑问。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97036149,'天威龙－纳哈塔','此卡名的①②效果1回合仅可各使用1次。①：自己场上没有效果怪兽存在的情况下可以发动。从手牌将此卡特殊召唤。②：效果怪兽以外的自己的表侧表示怪兽与对手的表侧表示怪兽进行战斗的攻击宣言时，将手牌・墓地的此卡除外可以发动。该对手怪兽的攻击力直至回合结束时为止下降1500。','特殊召唤','对手怪兽攻击力下降','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97045737,'圣主王之粉碎',replace(replace('此卡名的卡1回合仅可发动1张。\r\n对手场上存在卡的情况下，此卡也可从手牌发动。\r\n①：包含从牌组将卡加入手牌的效果在内的、魔法・陷阱・怪兽的效果发动时可以发动。将该效果无效。自己墓地存在陷阱卡的情况下，进而将该无效的卡破坏。从手牌发动此卡的情况下，发动后，此决斗中自己不可发动暗・水・炎属性怪兽的效果。','\r',char(13)),'\n',char(10)),'发动','适用「圣主王之粉碎」的效果从手牌发动','「圣主王之粉碎」效果适用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97045738,'圣主王之粉碎',replace(replace('此卡名的卡1回合仅可发动1张。\r\n对手场上存在卡的情况下，此卡也可从手牌发动。\r\n①：包含从牌组将卡加入手牌的效果在内的、魔法・陷阱・怪兽的效果发动时可以发动。将该效果无效。自己墓地存在陷阱卡的情况下，进而将该无效的卡破坏。从手牌发动此卡的情况下，发动后，此决斗中自己不可发动暗・水・炎属性怪兽的效果。','\r',char(13)),'\n',char(10)),'发动','适用「圣主王之粉碎」的效果从手牌发动','「圣主王之粉碎」效果适用中','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97051536,'狱炎机・邪恶',replace(replace('“狱炎机”怪兽×２\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡融合召唤的情况下，从自己的墓地将１只“狱炎机”怪兽除外可以发动。从牌组将张数与该怪兽等级数值相同的“狱炎机”怪兽送至墓地（同名卡最多１张）。\r\n②：此卡被送至墓地的情况下，或被除外的情况下可以发动。从牌组将１张“炼狱”魔法・陷阱卡加入手牌。','\r',char(13)),'\n',char(10)),'从牌组送至墓地','从牌组加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97053215,'G魔像・顽硬巨碑',replace(replace('地属性怪兽2只\r\n此卡名的效果1回合仅可使用1次。\r\n①：此卡从墓地特殊召唤的情况下，以自己墓地的1只可通常召唤的地属性怪兽为对象可以发动。将该怪兽加入手牌或特殊召唤。以此效果特殊召唤的怪兽的效果无效化，从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97064649,'暗跃的德鲁伊・维德',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：此卡从场上被送至墓地的情况下，以自己墓地的1张永续魔法卡为对象可以发动。将该卡放置在自己场上。以此效果放置的卡此回合不可发动。','\r',char(13)),'\n',char(10)),'放置','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97077563,'活死人的呼唤','①：以自己墓地的1只怪兽为对象可以发动此卡。将该怪兽以攻击表示特殊召唤。此卡从场上离开时该怪兽将被破坏。该怪兽被破坏时此卡将被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97077564,'活死人的呼唤','①：以自己墓地的1只怪兽为对象可以发动此卡。将该怪兽以攻击表示特殊召唤。此卡从场上离开时该怪兽将被破坏。该怪兽被破坏时此卡将被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97091969,'武装龙之震霆',replace(replace('此卡名的①效果１回合仅可使用１次。①：以自己场上的１只“武装龙”怪兽为对象，可从以下效果中选择１个发动。\r\n●该怪兽的攻击力上升相当于该怪兽等级×１００的数值。\r\n●从自己的墓地挑选１只拥有该怪兽的等级以下等级的“武装龙”怪兽加入手牌。\r\n②：自己场上的“武装龙”怪兽将被效果破坏的情况下，可将此卡送至墓地作为代替。','\r',char(13)),'\n',char(10)),'攻击力上升','墓地回收','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97093037,'创世者的化身','可解放此卡并发动。从手牌特殊召唤１只“创世神”。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97112505,'先史遗产 墨瓦腊地球仪',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：解放此卡可以发动。从牌组将“先史遗产 墨瓦腊地球仪”以外的１只“先史遗产”怪兽特殊召唤。\r\n②：此卡存在于墓地的情况下，从自己的墓地将１张“先史遗产 墨瓦腊地球仪”以外的“先史遗产”卡除外可以发动。将此卡加入手牌。此效果在此卡被送至墓地的回合不可发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97120394,'封魔之矢',replace(replace('应对此卡的发动，魔法・陷阱・怪兽的效果不可发动。\r\n①：在自己或对手的战斗阶段开始时可以发动。此卡发动后，直至回合结束时为止，双方不可发动魔法・陷阱卡的效果。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97127906,'外星人士兵','不明生物体，外星人的高级战士。拥有较高的攻击力，却不具备任何特殊能力。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97148796,'辉龙机巧－右垣一阿尔法','此卡不可通常召唤，仅可用“龙机巧”卡的效果特殊召唤。此卡名的效果1回合仅可使用1次。①：从自己的手牌・场上，解放此卡以外的1只“龙机巧”怪兽或仪式怪兽可以发动。将此卡从手牌・墓地以守备表示特殊召唤。然后，可从牌组将1只仪式怪兽加入手牌。发动此效果的回合中，自己仅可特殊召唤不可通常召唤的怪兽。','','是否从牌组把仪式怪兽加入手牌？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97151365,'星门','对手怪兽进行了战斗的场合，该伤害步骤结束时放置１个门计数物于此卡。于我方主要阶段时可将此卡送入墓地并发动。从手牌特殊召唤１只等级为放置于此卡的门计数物数量或以下怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97165977,'月光舞豹姬',replace(replace('“月光舞猫姬”＋“月光”怪兽\r\n此卡仅可通过以上述卡作为融合素材的融合召唤来从额外牌组特殊召唤。①：此卡不会因对手的效果被破坏。②：１回合１次，在自己的主要阶段１可以发动。此回合，对手怪兽各仅１次不会因战斗被破坏，此卡可攻击所有对手怪兽各２次。③：此卡战斗破坏对手怪兽时发动。此卡的攻击力直至战斗阶段结束时为止上升２００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97168905,'奇迹之轨迹','选择自己场上的１只表侧攻击表示怪兽可以发动。对手从牌组抽１张卡。此回合，选择的怪兽的攻击力上升１０００点，１次战斗阶段中最多可以攻击２次怪兽，该战斗中对对手造成的战斗伤害变为０。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97169186,'地碎','①：破坏对手场上守备力最高的１只怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97170107,'闪耀精灵',replace(replace('等级２怪兽×２\r\n对手召唤、特殊召唤怪兽成功时，可移除此卡的１个超量素材并发动。该怪兽的攻击力下降５００点。','\r',char(13)),'\n',char(10)),'攻击下降','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97173708,'衍生物诞生祭','可释放我方场上相同等级的衍生物２只或以上并发动。从我方墓地选择与被释放衍生物相同等级的怪兽，其数量最多为被释放衍生物的数量。可依照解放之衍生物的数量，以此效果特殊召唤的怪兽，其效果被无效化，并于结束阶段时被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97182396,'惊乐游乐设施 制霸海盗船',replace(replace('①：以自己场上的１只“惊乐园”怪兽或对手场上的表侧表示怪兽为对象可以发动此卡。将此卡视为装备卡，装备于该怪兽。\r\n②：根据装备怪兽的控制者，可以发动以下效果。\r\n●自己：１回合１次，在对手怪兽攻击宣言时可以发动。使该攻击无效，直至战斗阶段结束时为止，变更装备怪兽的控制权。\r\n●对手：装备怪兽发动效果时可以发动。将装备怪兽放回持有者的手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97204936,'大地骑士 盖亚骑士','协调＋１只以上协调以外的怪兽','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97211663,'影灵衣的反魂术',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：为使合计等级与仪式召唤的怪兽相等，解放自己手牌・场上的怪兽，从自己手牌・墓地将1只“影灵衣”仪式怪兽仪式召唤。\r\n②：自己场上不存在怪兽的情况下，从自己墓地将1只“影灵衣”怪兽和此卡除外可以发动。从牌组将1张“影灵衣”魔法卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97219708,'急袭猛禽－残存林鸮','此卡名的②效果1回合仅可使用1次。①：自己的“急袭猛禽”怪兽进行战斗的伤害计算时可以发动。从手牌将此卡特殊召唤。然后，自己恢复自己的场上・墓地的魔法・陷阱卡数量×100LP。②：解放此卡可以发动。从额外牌组将1只“急袭猛禽”超量怪兽以守备表示特殊召唤。以此效果特殊召唤的怪兽的效果无效化，将在结束阶段放回额外牌组。此回合对手受到的战斗伤害变为0。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97223101,'BBS',replace(replace('①：每次“BBS”以外的卡的效果发动则可以发动。在此卡上放１个访问计数物（最多１０个）。\r\n②：自己场上的怪兽的攻击力上升相当于此卡的访问计数物的数量×１００的数值。\r\n③：访问计数物被放在此卡上，使得该访问计数物的数量变为１０的情况下可以发动。将此卡放回手牌，从牌组将１张拥有以自身作为怪兽特殊召唤的效果的永续陷阱卡放置在自己场上。以此效果放置的卡在放置的回合也可以发动。','\r',char(13)),'\n',char(10)),'放置计数物','回到手牌并放置魔陷','适用「BBS」的效果来发动','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97227123,'决斗者归来',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：场上或自己・对手的墓地存在超量怪兽的情况下可以发动。从自己牌组・墓地将1张装备魔法卡加入手牌。','\r',char(13)),'\n',char(10)),'发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97232518,'深渊的电击魟',replace(replace('①：此卡发动后变为效果怪兽（雷族・光・星５・攻１９００／守０），特殊召唤至怪兽区域。此卡也视为陷阱卡。\r\n②：以此卡的效果被特殊召唤的此卡不会因战斗被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97234686,'剑斗交替','冠有“剑斗兽”之名的怪兽被特殊召唤至我方场上时可发动。对方挑选１张手牌舍弃。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97240270,'疯狂龙虾','因受到全世界美食怪兽们热爱而闻名的高级食材。据说其凶恶的味道相当刺激味觉。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97240499,'浑然斗牛诗－俄耳甫布鲁',replace(replace('此卡不可通常召唤。\r\n仅可在从自己的手牌・墓地将此卡以外的光・暗属性怪兽各２只除外的情况下特殊召唤。\r\n①：以此方法特殊召唤的此卡的攻击力上升相当于为了该特殊召唤而从手牌除外的怪兽数量×１０００的数值，且在１次战斗阶段中，可攻击怪兽的次数最多为为了该特殊召唤而从墓地除外的怪兽数量。\r\n②：此卡战斗破坏对手怪兽的伤害计算后可以发动。将该对手怪兽除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97254001,'夏',replace(replace('①：1回合1次，可以发动。依未使用的、对手的主要怪兽区域的数量，在此卡上放四季计数物。\r\n②：1回合1次，自己怪兽的攻击宣言时可以发动。给予对手此卡的四季计数物数量及自己墓地的“春”的数量×400的伤害。\r\n③：在对手的结束阶段可以发动。从手牌・牌组将1张可放四季计数物的场地魔法卡以表侧表示放在自己场上（此卡的四季计数物移至该卡）。该卡的效果此回合不可发动。','\r',char(13)),'\n',char(10)),'放置计数物','给与伤害','放置场地魔法卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97262307,'蕾祸之姬邪眼',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：从手牌将此卡舍弃可以发动。从手牌将１只昆虫族・植物族・爬虫类族怪兽特殊召唤。\r\n②：此卡被从手牌・墓地除外的情况下可以发动。在此回合的结束阶段，自己依自己场上的昆虫族・植物族・爬虫类族怪兽的种族的种类数量抽牌。','\r',char(13)),'\n',char(10)),'特殊召唤','效果抽牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97268402,'效果遮蒙者','①：在对手的主要阶段从手牌将此卡送至墓地，以对手场上的1只效果怪兽为对象可以发动。将该对手怪兽的效果直至回合结束时为止无效。','怪兽的效果无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97268403,'效果遮蒙者','①：在对手的主要阶段从手牌将此卡送至墓地，以对手场上的1只效果怪兽为对象可以发动。将该对手怪兽的效果直至回合结束时为止无效。','怪兽的效果无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97273514,'甲虫装机 皮可蛾',replace(replace('昆虫族怪兽２只\r\n此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡连接召唤的情况下，舍弃１张手牌，以自己场上的１只其他的昆虫族怪兽为对象可以发动。从牌组挑选１只昆虫族怪兽，视为攻击力・守备力上升５００的装备魔法卡，装备于对象怪兽。\r\n②：以自己墓地的３只昆虫族怪兽为对象可以发动。将该怪兽放回牌组洗牌。然后，自己抽１张。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97300502,'召唤兽 奥格艾迪斯',replace(replace('“召唤师 阿莱斯特”＋融合怪兽\r\n此卡名的①效果１回合仅可使用１次。①：此卡特殊召唤成功的情况下，或怪兽被特殊召唤至对手场上的情况下，以对手场上的１只怪兽为对象可以发动。将该怪兽破坏。②：１回合１次，从自己的墓地将１只融合怪兽除外可以发动。此卡的攻击力直至对手回合结束时为止，上升相当于所除外怪兽的攻击力的数值。','\r',char(13)),'\n',char(10)),'怪兽破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97316367,'无限起动 削岩掘进机','此卡名的①②效果１回合仅可各使用１次。①：解放自己场上的１只机械族・地属性怪兽可以发动。将此卡从手牌以守备表示特殊召唤。②：将墓地的此卡除外，以自己墓地的５只机械族・地属性怪兽为对象可以发动。将该怪兽放回牌组洗牌。然后自己从牌组抽２张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97317530,'森之圣兽 月耳草兔','①：此卡以兽族怪兽的效果特殊召唤成功的情况下，以场上的１张卡为对象可以发动。将该卡破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97342942,'灵魂炮击','双方玩家在各自的结束阶段时仅１次，挑选自己场上１只表侧表示的怪兽并将该怪兽解放，给予对手所解放怪兽的原本攻击力一半数值的伤害。','解放并伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97345699,'宵星的闪光',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：对手场上的怪兽数量比自己场上的怪兽多２只以上的情况下可以发动。对手可将自身场上任意数量的怪兽送至墓地。自己根据对手场上的怪兽数量适用以下效果。\r\n●０只：自己的LP变为一半。\r\n●１只：对手恢复２０００LP。\r\n●２只：将对手的全部手牌直至结束阶段为止以表侧除外。\r\n●３只以上：此回合，对手不可发动怪兽的效果。','\r',char(13)),'\n',char(10)),'','是否把怪兽送至墓地？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97360116,'恶之无名战士','利用敏捷的动作创造真空，斩碎对手的战士。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97362768,'电光枪','仅限装备“元素－英雄 闪光人”。可在我方主要阶段时，选择场上的１只表侧表示怪兽变更表示形式。此效果使用３次后，此卡被破坏。','改变表示形式','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97383507,'暗骑士＠伊格尼斯者',replace(replace('卡名不同的怪兽3只\r\n此卡名的①②效果1回合仅可各使用1次。①：怪兽被特殊召唤至此卡连接端的情况下可以发动（伤害步骤也可以发动）。从自己的墓地将尽可能多的等级4以下“＠伊格尼斯者”怪兽，效果无效并特殊召唤至此卡连接端的自己场上。②：此卡战斗破坏对手怪兽时可以发动。从自己的墓地挑选1只电子界族怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97385276,'等级战士','双方场上都不存在有怪兽的场合，此卡可作为等级２怪兽从手牌召唤。对手场上存在有怪兽，且我方场上不存在有怪兽的场合，此卡可作为等级４怪兽从手牌特殊召唤。','作为2星怪兽召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97396380,'火舞太刀','①：这张卡在被破坏并被送至墓地的情况下，以对手场上1只表侧表示怪兽为对象发动。破坏该对手的表侧表示怪兽，给对手500伤害。','破坏并伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97403510,'编号92 伪骸神龙 心地心龙',replace(replace('等级９怪兽×３\r\n①：此卡不会因战斗被破坏，因此卡的战斗发生的对自己的战斗伤害由对手代为承受。②：在对手的结束阶段，去除此卡的１个超量素材可以发动。将在此回合被召唤・特殊召唤・放置的对手场上的卡全部除外。③：持有超量素材的此卡被破坏并被送至墓地的情况下可以发动。将此卡特殊召唤。④：此卡以自身的效果特殊召唤的情况下发动。此卡的攻击力上升被除外的卡的数量×１０００的数值。','\r',char(13)),'\n',char(10)),'卡片除外','特殊召唤','攻击上升','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97417863,'DDDD 超次元统皇零悖论',replace(replace('←10 【灵摆】 10→\r\n此卡名的灵摆效果1回合仅可使用1次。\n①：以对手灵摆区域的1张卡为对象可以发动。将此卡特殊召唤，将对象卡放在自己的灵摆区域。以此效果所放的卡将在下个回合的结束阶段被破坏。\r\n【怪兽效果】\r\n此卡不可通常召唤，仅可以此卡的效果特殊召唤。\n①：自己将怪兽灵摆召唤时，如果自己灵摆区域的灵摆刻度的合计超过灵摆召唤的怪兽的合计等级则可以发动。从手牌将此卡特殊召唤，将场上的其他卡全部破坏。然后，可将此卡放在自己的灵摆区域。\n②：1回合1次，自己场上的其他表侧表示“DDD”怪兽因魔法卡的效果从场上离开的情况下发动。此卡的攻击力变为6000。','\r',char(13)),'\n',char(10)),'','是否将此卡在自己的灵摆区域放置？','此卡的攻击力变成6000','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97433739,'给未来的思念','可选择我方墓地３只等级各异的怪兽并发动。特殊召唤被选择的３只怪兽。以此效果特殊召唤的怪兽之攻击力变成０，效果被无效化。之后，我方不进行超量召唤的场合，在此回合的结束阶段时我方失去４０００LP。此外，发动此卡的回合，我方不可进行超量召唤以外的特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97434754,'神艺学徒 璃天乐',replace(replace('此卡名的①③效果1回合仅可各使用1次。\r\n①：自己场上存在“神艺”卡的情况下可以发动。从手牌将此卡特殊召唤。然后，可从自己墓地将1张“神艺”卡加入手牌。\r\n②：因此卡的战斗对自己造成的战斗伤害变为0。\r\n③：在对手的主要阶段可以发动。从自己手牌・墓地将“神艺学徒 璃天乐”以外的1只“神艺”怪兽特殊召唤。然后，将场上的此卡放回手牌。','\r',char(13)),'\n',char(10)),'此卡特殊召唤','从手牌·墓地特殊召唤','是否加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97439308,'混沌贪欲','我方墓地不存在卡牌，且从游戏中被除外的我方卡牌为４张或以上的场合可发动。从我方牌组中抽取２张卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97439806,'魔轰神苛黠诺','①：此卡存在于墓地的情况下，从手牌将“魔轰神苛黠诺”以外的1只“魔轰神”怪兽舍弃至墓地可以发动。将此卡加入手牌。','此卡加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97452817,'秘仪之力ⅩⅧ－月亮',replace(replace('①：此卡召唤・反转召唤・特殊召唤的情况下发动。掷1次硬币，根据掷出的正反，此卡获得以下效果。\r\n●正面：在自己的准备阶段可以发动。将1只“月亮衍生物”（天使族・光・星1・攻/守0）特殊召唤至自己场上。\r\n●反面：在自己的结束阶段，以自己场上的1只怪兽为对象发动。将该自己的怪兽的控制权转移给对手。','\r',char(13)),'\n',char(10)),'投掷硬币','特殊召唤','控制权转移','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97452818,'月亮衍生物','由「秘仪之力ⅩⅧ－月亮」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97453744,'英豪胜利者 辉之剑',replace(replace('战士族等级４怪兽×２\r\n此卡名的②③效果１回合仅可各使用１次。\r\n①：对手不可将其他怪兽选择为攻击对象。\r\n②：支付LP使其变为５００LP可以发动。此回合的战斗阶段开始时，挑选自己场上的１只怪兽，将其攻击力改成两倍。\r\n③：对手怪兽进行战斗的攻击宣言时，去除此卡的１个超量素材，以对手场上的１只表侧表示怪兽为对象可以发动。此卡的攻击力直至回合结束时为止，上升相当于该怪兽攻击力的数值。','\r',char(13)),'\n',char(10)),'','','请选择要把攻击力变成2倍的怪兽','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97462632,'咕里佛',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：在自己・对手回合中，从手牌将此卡舍弃，可从以下效果中选择1个发动。\r\n●此回合，自己受到的战斗・效果伤害仅1次变为0。\r\n●从牌组将1张记载有“光与暗的仪式”卡名的速攻魔法・陷阱卡放置在自己场上。以此效果放置的卡在放置的回合也可以发动。\r\n②：要仪式召唤1只等级8仪式怪兽的情况下，使用1张此卡即可作为仪式召唤所必需的解放。','\r',char(13)),'\n',char(10)),'丢弃发动效果','伤害改变','放置魔陷','适用「咕里佛」的效果来发动','','','','','','','','','','','','');
INSERT INTO texts VALUES(97466438,'横纹斑马',replace(replace('←7 【灵摆】 7→\r\n①：此卡发动过的余下回合的自己的主要阶段仅１次，指定１处未使用的怪兽区域或魔法与陷阱区域可以发动。所指定的区域在此卡存在于灵摆区域期间不可使用。\r\n【怪兽效果】\r\n①：此卡召唤・特殊召唤成功的情况下，指定１处未使用的怪兽区域或魔法与陷阱区域可以发动。所指定的区域在此怪兽以表侧表示存在期间不可使用。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97466712,'骇客异虫','①：对手场上不存在有怪兽的场合，此卡可从手牌特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97474300,'决斗者创世',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：自己场上或墓地存在协调的情况下可以发动。从牌组将1张“同步”魔法・陷阱卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97476032,'寒冰塑偶',replace(replace('此卡名的①②③效果1回合仅可各使用1次，发动此效果的回合中，自己仅可特殊召唤水属性怪兽。\r\n①：从手牌将1只其他水属性怪兽舍弃可以发动。从手牌将此卡特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下可以发动。从牌组将1只魔法师族・水属性怪兽加入手牌。\r\n③：此卡从场上被送至墓地的情况下可以发动。从牌组将1张“寒冰塑偶之镜”加入手牌。','\r',char(13)),'\n',char(10)),'特殊召唤','检索怪兽','检索魔法','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97489701,'绯暗红新星龙',replace(replace('协调2只＋“暗红恶魔龙”\r\n①：此卡的攻击力上升自己墓地协调的数量×500的数值。\r\n②：场上的此卡不会因对手的效果被破坏。\r\n③：对手怪兽攻击宣言时，以该1只攻击怪兽为对象可以发动。将场上的此卡除外，将该攻击无效。\r\n④：此卡因③效果被除外的回合的结束阶段发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'攻击无效','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97489702,'绯暗红新星龙',replace(replace('协调2只＋“暗红恶魔龙”\r\n①：此卡的攻击力上升自己墓地协调的数量×500的数值。\r\n②：场上的此卡不会因对手的效果被破坏。\r\n③：对手怪兽攻击宣言时，以该1只攻击怪兽为对象可以发动。将场上的此卡除外，将该攻击无效。\r\n④：此卡因③效果被除外的回合的结束阶段发动。将此卡特殊召唤。','\r',char(13)),'\n',char(10)),'攻击无效','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97518132,'囚影依之巫女 艾莉娅儿',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：此卡反转的情况下，以自己除外状态的1只“影依”怪兽为对象可以发动。将该怪兽以表侧守备表示或里侧守备表示特殊召唤。\r\n②：此卡因效果被送至墓地的情况下，以自己・对手墓地的合计最多3张卡为对象可以发动。将该卡除外。','\r',char(13)),'\n',char(10)),'特殊召唤','除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97520532,'机关傀偶－奇美拉娃娃',replace(replace('机械族怪兽２只\r\n此卡名的效果１回合仅可使用１次。\r\n①：此卡是被连接召唤的情况下可以发动。从牌组挑选１只“机关傀偶”怪兽，加入手牌或送至墓地。自己场上的怪兽仅有“机关傀偶”怪兽的情况下，进而可从手牌将１只“机关傀偶”怪兽特殊召唤。此效果发动后，直至回合结束时为止自己从额外牌组仅可特殊召唤机械族超量怪兽。','\r',char(13)),'\n',char(10)),'','请选择要加入手牌或送至墓地的卡','是否从手牌特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97520701,'临时时刻表',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：以自己墓地1只攻击力3000以上的机械族怪兽为对象可以发动。将该机械族怪兽以守备表示特殊召唤。\r\n②：被放置的此卡被送至墓地的情况下，以自己墓地的1只机械族・等级10怪兽为对象可以发动。将该机械族怪兽加入手牌。','\r',char(13)),'\n',char(10)),'检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97522863,'拥有刻印之人',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组挑选1张“王家的神殿”或记载有该卡名的魔法・陷阱卡，加入手牌或送至墓地。\r\n②：只要自己场上存在“王家的神殿”，此卡及自己场上的“阿波菲斯”怪兽不会因战斗・效果被破坏。\r\n③：只要此卡存在于怪兽区域，自己场上的“王家的神殿”不会因效果被破坏。','\r',char(13)),'\n',char(10)),'检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97526666,'行星探查车','①：解放此卡可以发动。从牌组将１张场地魔法卡加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97534104,'杀手马铃薯','①：场上的此卡因效果被破坏并被送至墓地的情况下可以发动。从牌组将除“杀手马铃薯”之外的、攻击力１５００以下的１只暗属性怪兽以攻击表示特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97556336,'无垢者 墨迪乌斯',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组挑选1只“狱神”怪兽，加入手牌或特殊召唤。\r\n②：此卡存在于墓地的情况下可以发动。从自己手牌・场上（表侧表示）将1只怪兽放回牌组，将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'牌组操作','此卡特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97565997,'溟界神－八元邃渊','此卡名的①②效果1回合仅可各使用1次。①：此卡存在于墓地的情况下，解放自己场上的3只怪兽可以发动。将此卡特殊召唤。②：只要此卡在场上以表侧表示存在，仅限1次可以发动。将从墓地被特殊召唤的表侧表示怪兽以外的、自己・对手场上的怪兽全部送至墓地。此效果在对手回合中也可以发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97567736,'锋利小鬼・战斧',replace(replace('“锋利小鬼・战斧”的①②效果１回合仅可各使用１次。\r\n①：将手牌的１只“锋利小鬼”怪兽送至墓地可以发动。给予对手８００点伤害。\r\n②：从牌组中将１只除“锋利小鬼・战斧”以外的“锋利小鬼”怪兽送往墓地可以发动。直至结束阶段，此卡被视为送往墓地的怪兽的同名卡。','\r',char(13)),'\n',char(10)),'给与对手800伤害','复制卡名','当作同名卡使用','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97570038,'神拳碎裂','我方场上存在“格斗鼠 吱助”、“僧侣斗士”或“僧侣大师”其中１只或以上的场合可发动。在伤害步骤结束时破坏此回合中与上述怪兽进行战斗的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97574404,'秘仪之力Ⅵ－恋人',replace(replace('①：此卡召唤・反转召唤・特殊召唤的情况下发动。掷1次硬币，根据掷出的正反，此卡获得以下效果。\r\n●正面：要上级召唤“秘仪之力”怪兽的情况下，此卡可作为2只解放。\r\n●反面：只要此卡存在于怪兽区域，双方不可上级召唤“秘仪之力”怪兽。','\r',char(13)),'\n',char(10)),'投掷硬币','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97584500,'鬼计・木乃伊','仅在自己场上有“鬼计”怪兽存在的情况下，此卡才可以表侧表示召唤。①：在自己的主要阶段可以发动。将此卡改成里侧守备表示（１回合仅１次）。②：只要此卡存在于怪兽区域，自己除通常召唤外仅可追加１次，在自己的主要阶段召唤１只“鬼计”怪兽。③：只要此卡存在于怪兽区域，自己仅可特殊召唤暗属性怪兽。','变成里侧守备','使用「鬼计・木乃伊」的效果召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97584719,'无限起动 大地撼动者',replace(replace('等级９怪兽×２\r\n此卡名的①③效果１回合仅可各使用１次。①：去除此卡任意数量的超量素材，以场上该数量的卡为对象可以发动。将该卡破坏。②：此卡战斗破坏对手怪兽时可以发动。将该怪兽重叠在此卡下方作为超量素材。③：此卡存在于墓地的情况下，解放自己场上的１只机械族连接怪兽可以发动。将此卡以守备表示特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97588916,'文具博格００７',replace(replace('←10 【灵摆】 10→\r\n①：自己仅可灵摆召唤“文具博格”怪兽。此效果不会被无效化。\r\n【怪兽效果】\r\n①：此卡的攻击力上升相当于自己墓地的“文具博格”卡数量×５００的数值。②：只要此卡存在于怪兽区域，对手不可将其他“文具博格”怪兽作为攻击对象。③：此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予战斗伤害。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97590747,'神灯精灵・拉丁','听从将自己呼唤出来的主人的任何要求和命令的灯之精灵。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97590748,'神灯精灵・拉丁','听从将自己呼唤出来的主人的任何要求和命令的灯之精灵。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97612389,'地狱的魔物使','能够自由自在地操纵怪兽进行攻击的怪兽使。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97616504,'闪刀机构－大力神基地','自己的主要怪兽区域不存在怪兽的情况下可以发动这张卡。①：装备怪兽不可直接攻击，1次的战斗阶段中可以攻击怪兽2次。②：自己墓地存在3张以上的魔法卡，且装备怪兽攻击破坏怪兽的情况下发动。自己从牌组抽1张。③：这张卡被效果从场上送至墓地的情况下，可以“闪刀机构-大力神基地”以外的最多3张自己墓地的“闪刀”卡为对象发动。将该卡放回牌组。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97617181,'银河零式','此卡名的卡１回合仅可发动１张。①：以自己墓地的１只“光子”怪兽或“银河”怪兽为对象可以发动此卡。将该怪兽以攻击表示特殊召唤，装备此卡。装备怪兽不可攻击，也不可发动效果。②：装备怪兽将在战斗阶段被战斗・效果破坏的情况下，可将此卡破坏作为代替。③：表侧表示的此卡从场上离开的情况下发动。装备过此卡的怪兽的攻击力变为０。','攻击变成0','是否要使用「银河零式」的效果代替破坏？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97623219,'元素女武神',replace(replace('当场上有特定属性的怪兽存在的场合，此怪兽获得以下效果。\r\n●炎属性：此卡的攻击力上升５００点。\r\n●水属性：此卡的控制权不可变更。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97631303,'魔术师双魂',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡存在于手牌的情况下，从牌组将1只等级6以上的魔法师族怪兽送至墓地，可从以下效果中选择1个发动。\r\n●将此卡特殊召唤。\r\n●将此卡送至墓地。然后，可从自己墓地将1只“黑魔导”或“黑魔导女孩”特殊召唤。\r\n②：从自己手牌・场上将最多2张魔法・陷阱卡送至墓地可以发动。自己依送至墓地的数量抽牌。','\r',char(13)),'\n',char(10)),'此卡特殊召唤','此卡送至墓地','是否从墓地特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97637162,'赛跑障碍马',replace(replace('①：此卡不可直接攻击。\r\n②：此卡的攻击力上升相当于双方LP之差的数值。\r\n③：自己的LP多于对手的情况下，因此卡的攻击造成的对对手的战斗伤害由自己代为承受。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97639441,'光子跳跃者','此卡名的①②效果１回合仅可各使用１次。①：对手怪兽攻击宣言时可以发动。从手牌将此卡特殊召唤。然后，结束战斗阶段。发动了此效果的情况下，跳过下个自己的战斗阶段。②：此卡被送至墓地的情况下可以发动。从牌组将１张“光子”魔法・陷阱卡或“银河”魔法・陷阱卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97642679,'暗的支配者－佐克',replace(replace('由“与暗的支配者的契约”召唤而来。\r\n①：１回合１次，可在我方主要阶段发动此卡。投掷１次骰子，根据掷出的数字来适用效果。\r\n●掷出１、２时：破坏对手场上的所有怪兽。\r\n●掷出３、４、５时：破坏对手场上的１只怪兽。\r\n●掷出６时：破坏我方场上的所有怪兽。','\r',char(13)),'\n',char(10)),'掷骰子','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97648103,'星遗物之加护','此卡名的卡1回合仅可发动1张。①：以自己墓地卡名不同的2只“星杯”怪兽为对象可以发动。将该怪兽加入手牌。②：自己场上连接状态的连接怪兽将被战斗破坏的情况下，可将墓地的此卡除外作为代替。','是否使用「星遗物之加护」的效果代替破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97651498,'魔轰神鲁力','①：此卡从手牌被舍弃至墓地的情况下发动。将此卡特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97651499,'魔轰神鲁力','①：此卡从手牌被舍弃至墓地的情况下发动。将此卡特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97661969,'崔嵬之地灵使 奥丝',replace(replace('包含地属性怪兽在内的怪兽2只\r\n此卡名在规则上也视为“凭依装着”卡。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：以对手墓地的1只地属性怪兽为对象可以发动。将该怪兽特殊召唤至此卡连接端的自己场上。\r\n②：连接召唤的此卡因战斗或对手的效果被破坏的情况下可以发动。从牌组将1只守备力1500以下的地属性怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97662494,'纹章兽 斯塔德鲸',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下，舍弃1张手牌可以发动。从牌组将2张“徽章”魔法・陷阱卡加入手牌。\r\n②：将墓地的此卡除外，以自己墓地的2只同名“纹章兽”怪兽为对象可以发动。将该怪兽以守备表示特殊召唤。此效果发动后，直至回合结束时为止，自己除了以原本卡名包含“纹章兽”或“编号”的怪兽作为素材的超量召唤之外，不可从额外牌组特殊召唤怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97677329,'备份监督者',replace(replace('怪兽２只\r\n此卡牌名的①②效果１回合只可各使用１次。\r\n①：此卡以“备援秘书”为素材连接召唤而来的场合，此卡连接端之我方怪兽，在与对手怪兽进行战斗的伤害步骤结束时可发动。从手牌特殊召唤１只电子界族怪兽。\r\n②：此卡因战斗或对手效果被破坏的场合可发动。从我方手牌・牌组・墓地挑选１只“备援秘书”并特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97682931,'革命同步士',replace(replace('此卡名的①效果1回合仅可使用1次，②效果在决斗中仅可使用1次。\r\n①：要同步召唤“动力工具”同步怪兽或等级7・8的龙族同步怪兽的情况下，可将手牌的此卡也作为同步素材。\r\n②：此卡存在于墓地，且自己场上存在等级7以上的同步怪兽的情况下可以发动。将自己牌组最上面的卡送至墓地，将此卡特殊召唤。以此效果特殊召唤的此卡的等级变为1。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97687912,'流星直击','装备怪兽攻击守备表示怪兽时，如果攻击力超出守备力，则给对方生命相当于该差值的战斗伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97688360,'刚鬼 锁喉眼镜蛇','此卡名的①②效果1回合仅可各使用1次。①：解放自己场上的1只“刚鬼”怪兽，以自己场上的1只“刚鬼”怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止，上升相当于解放的怪兽原本攻击力的数值。此效果在对手回合中也可以发动。②：此卡从场上被送至墓地的情况下可以发动。从牌组将1张“刚鬼 锁喉眼镜蛇”以外的“刚鬼”卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97692972,'亚马逊的金鞭师',replace(replace('←1 【灵摆】 1→\r\n此卡名的②灵摆效果１回合仅可使用１次。\n①：自己场上的“亚马逊”怪兽的攻击力上升相当于自身等级×１００的数值。\n②：自己的“亚马逊”怪兽进行战斗的攻击宣言时，以场上１张魔法・陷阱卡为对象可以发动。将该卡破坏。\r\n【怪兽效果】\r\n此卡名的①②怪兽效果１回合仅可各使用１次。\n①：怪兽区域的此卡因战斗・效果被破坏的情况下可以发动。将此卡放在自己的灵摆区域。\n②：此卡存在于墓地的状态下，“亚马逊”怪兽被特殊召唤至自己场上的情况下可以发动。将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97697447,'邃渊激流','将自己场上１张表侧表示的“海”送至墓地可以发动。将场上的魔法・陷阱卡全部送至墓地。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97697678,'圆盘姆斯基','只要此卡以表侧表示存在于场上，可在我方的抽牌阶段，从牌组将１张冠有“外星人”之名的卡牌加入手牌代替通常抽牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97698279,'龙装百夫骑兵 卡戈尔Ⅱ',replace(replace('此卡名的①②③效果１回合仅可各使用１次。\r\n①：将自己场上的１张表侧表示“百夫骑”卡送至墓地可以发动。从手牌将此卡特殊召唤。此回合，自己不可特殊召唤“龙装百夫骑兵 卡戈尔Ⅱ”。\r\n②：此卡作为同步素材被送至墓地的情况下可以发动。将此卡加入手牌。\r\n③：此卡视为永续陷阱卡的情况下，在自己・对手的主要阶段可以发动。将此卡特殊召唤。然后，可将此卡的等级下降４。','\r',char(13)),'\n',char(10)),'特殊召唤','回到手牌','特殊召唤','是否下降等级？','','','','','','','','','','','','');
INSERT INTO texts VALUES(97705809,'超级充电','①：我方场上的怪兽仅有机械族的“机人”怪兽的场合，可在对手怪兽的攻击宣言时发动。我方从牌组抽取２张卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97729135,'瞪眼对峙','①：自己将怪兽特殊召唤至额外怪兽区域时，以对手主要怪兽区域的1只怪兽为对象可以发动。将该对手怪兽移动至与自己额外怪兽区域的怪兽同一纵列的、对手主要怪兽区域。②：对手将怪兽特殊召唤至额外怪兽区域时，以自己主要怪兽区域的1只怪兽为对象可以发动。将自己的该怪兽移动至与该对手额外怪兽区域的怪兽同一纵列的、自己主要怪兽区域。','','','请选择要移动到的位置','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97738431,'编号怪兽叠放推进','可选择我方场上１只无超量素材的冠有“编号”之名的超量怪兽并发动。将我方手牌的２只怪兽重叠至被选择的超量怪兽下方当作超量素材。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97750534,'死之代行者 天王星',replace(replace('①：场上存在有“天空的圣域”的场合，此卡可从手牌特殊召唤。\r\n②：１回合１次，在我方主要阶段可发动。从牌组将１只“代行者”怪兽送入墓地。此卡的等级变成与因此效果送入墓地的怪兽相同等级。','\r',char(13)),'\n',char(10)),'送墓','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97769122,'巴利安之混沌抽牌',replace(replace('①：在自己的抽牌阶段通过持续公开以通常抽牌抽到的此卡，在该回合的主要阶段１，可从以下效果中选择１个发动。\r\n●从牌组将１张“七皇”通常魔法卡送至墓地可以发动。此效果变为与该魔法卡发动时的效果相同。\r\n●从牌组将最多２只怪兽的效果无效并特殊召唤，将自己场上的怪兽（须包含该特殊召唤的全部怪兽）作为素材，进行１只“编号”超量怪兽的超量召唤。','\r',char(13)),'\n',char(10)),'是否要持续公开「巴利安混沌抽牌」？','复制「七皇」通常魔法卡','从牌组特殊召唤并超量召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97783338,'水雷魔神－门之守护者',replace(replace('“水魔神－苏迦”＋“雷魔神－桑迦”\r\n仅可在将自己场上的上述卡除外的情况下特殊召唤。\r\n此卡名的①效果１回合最多可使用２次。\r\n①：在自己・对手回合中，以对手场上的１只表侧表示怪兽为对象可以发动（同一连锁上最多１次）。将该怪兽的攻击力直至回合结束时为止改成０。\r\n②：特殊召唤的表侧表示的此卡因对手从场上离开的情况下可以发动。将自己除外状态的１只“水魔神－苏迦”或“雷魔神－桑迦”特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97783659,'吸血怪','此卡给予对手生命战斗伤害时，将对手牌组最上面的１张卡牌送入墓地。','牌组送墓','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97792247,'星尘冲锋战士',replace(replace('协调+1只以上协调以外的怪兽\r\n此卡名的①效果1回合仅可使用1次。①：此卡同步召唤成功时，自己场上没有其他怪兽存在的情况下，以自己墓地的1只“废品”怪兽为对象可以发动。将该怪兽特殊召唤。②：此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予战斗伤害。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97795930,'幻煌龙之天涡',replace(replace('场上有“海”存在的情况下，此卡也可从手牌发动。\r\n①：以自己场上的１只“幻煌龙 螺旋”为对象可以发动。该怪兽装备３种以上“幻煌龙”装备魔法卡的状态下，战斗破坏对手的３只效果怪兽时，自己获得决斗胜利。\r\n②：自己场上的通常怪兽将被战斗・效果破坏的情况下，可将墓地的此卡除外作为代替。','\r',char(13)),'\n',char(10)),'是否使用「幻煌龙之天涡」的效果代替破坏？','适用「幻煌龙之天涡」的效果来发动','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97800311,'圣神蛇 阿波菲斯',replace(replace('记载有“王家的神殿”卡名的怪兽×2\r\n此卡仅可通过融合召唤及以下方法特殊召唤。\r\n●解放自己场上2只“阿波菲斯”怪兽的情况下，可从额外牌组特殊召唤。\r\n①：1回合1次，以自己墓地的最多3张“阿波菲斯”陷阱卡为对象可以发动（同名卡最多1张）。将该卡放置在自己场上。\r\n②：1回合1次，陷阱卡发动的情况下，以对手场上的1张卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'放置','破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97803170,'恶魔的呼唤',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：以自己墓地的1只等级5以上的恶魔族怪兽为对象可以发动。从手牌挑选1只恶魔族怪兽舍弃，将对象怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97806240,'强引的安全协定','舍弃１张手牌。直至此回合结束阶段时，不可发动陷阱卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97809599,'旧神之印','①：支付１０００LP可以发动。确认对手场上所有被盖牌的卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97811903,'清净恶龙','只要此卡表侧表示存在于场上，此卡的控制者不会被“清净世界”的效果适用。此卡在攻击对手怪兽的情况下，仅在伤害计算时此卡的攻击力变为攻击对象怪兽的攻击力的两倍。此卡将被对手的卡的效果破坏的情况下，可以作为代替舍弃自己的１张手牌。','是否要使用「清净恶龙」的效果代替破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97818130,'团结之凶魔龙 黑恶魔龙',replace(replace('此卡不可通常召唤，仅可通过此卡的效果特殊召唤。\r\n此卡名的①效果1回合仅可使用1次。\r\n①：在自己・对手回合中，从手牌将1张速攻・仪式魔法卡舍弃可以发动。从手牌将此卡以守备表示特殊召唤。\r\n②：此卡特殊召唤的情况下可以发动。从自己牌组・墓地将1张记载有“光与暗的仪式”卡名的魔法・陷阱卡放置在自己场上。\r\n③：在双方的战斗阶段开始时可以发动。对手失去800LP，此卡的攻击力上升800。','\r',char(13)),'\n',char(10)),'特殊召唤','放置','失去基本分·攻击力上升','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97836203,'T.G.战戟炮手',replace(replace('同步怪兽的协调＋2只以上协调以外的同步怪兽\r\n此卡只可以同步召唤方式特殊召唤。①：1回合1次，自己或对手召唤・反转召唤・特殊召唤怪兽之际可以发动。此卡在场上以表侧表示存在的情况下，将其无效，将该怪兽破坏。②：此卡从场上被送至墓地时，以自己墓地的1只“T.G.”怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'召唤无效并破坏','反转召唤无效并破坏','特殊召唤无效并破坏','特殊召唤','','','','','','','','','','','','');
INSERT INTO texts VALUES(97843505,'风之看守 吉恩','操纵风来引起龙卷风和飓风吹飞周围的东西。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97854941,'女战神・西格鲁恩',replace(replace('此卡牌名的①②效果１回合只可各使用１次。\r\n①：此卡存在于手牌的场合，可以我方场上的１张表侧表示的魔法、陷阱卡为对象发动。将该卡送入墓地，并特殊召唤此卡。\r\n②：此卡召唤、特殊召唤成功的场合可发动。从我方手牌、墓地挑选１只等级８或以下的“女战神”怪兽并特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97864322,'查理大帝',replace(replace('装备有装备卡的等级９“焰圣骑士帝－查理”１只\r\n①：此卡连接召唤的情况下，以自己墓地的１只“焰圣骑士帝－查理”为对象可以发动。此卡视为该卡的同名卡，获得相同效果。然后，将对象怪兽视为攻击力上升５００的装备魔法卡，装备于此卡。\r\n②：１回合１次，魔法・陷阱卡的效果发动时，从自己手牌・场上（表侧表示）将１张装备魔法卡送至墓地可以发动。将该发动无效并破坏。','\r',char(13)),'\n',char(10)),'复制卡名和效果','发动无效并破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97870394,'亚马逊灵术师',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡存在于手牌・墓地的情况下，以自己场上“亚马逊灵术师”以外的１张“亚马逊”卡为对象可以发动。将该卡放回持有者的手牌，将此卡特殊召唤。此效果发动后，直至回合结束时为止，自己从额外牌组仅可特殊召唤“亚马逊”怪兽。\r\n②：此卡特殊召唤成功的情况下可以发动。从牌组将１张“融合”加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97885363,'电力蜻蜓','①：此卡被对手破坏的情况下可以发动。从牌组将１只“电力”怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97896503,'刷拉拉骑士','①：此卡攻击表侧守备表示怪兽的伤害步骤开始时发动。将该怪兽破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97904474,'手铐龙','此卡因对手怪兽的攻击被破坏并送入墓地时，此卡被视为装备卡装备该怪兽。装备怪兽的攻击力下降１８００点。因装备怪兽被破坏之事而被送入墓地时，可特殊召唤此卡。','装备','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97922283,'野生的咆哮','自己的怪兽战斗破坏仅对手怪兽并将其送至墓地时，给予对手LP自己场上的兽族怪兽数量×３００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97923414,'大木人１８','被劈倒的大树中寄宿了邪恶灵魂的姿态。袭击在森林中迷路的人。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97926515,'紧急救急救命救援','此卡名的卡1回合仅可发动1张。①：自己的LP少于对手的情况下可以发动。从牌组将3只攻击力300/守备力100的兽族怪兽出示给对手，对手从中挑选1只，将1只该怪兽加入自己的手牌，剩下的放回牌组。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97940434,'混沌猎人',replace(replace('①：对手将怪兽特殊召唤时，舍弃1张其他手牌可以发动。从手牌将此卡特殊召唤。\r\n②：只要此卡存在于怪兽区域，对手不可将卡除外。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97946536,'虫装突击－红黄',replace(replace('此卡名在规则上也视为“甲虫装机”卡。\r\n此卡名的卡１回合仅可发动１张。\r\n①：从手牌及自己场上表侧表示的卡中，将１张“甲虫装机”卡送至墓地，可从以下效果中选择１个发动。\r\n●从牌组挑选１只“甲虫装机”怪兽，特殊召唤或视为装备卡装备于自己场上的１只“甲虫装机”怪兽。\r\n●从牌组挑选１张“甲虫装机”装备魔法卡，装备于自己场上的１只“甲虫装机”怪兽。','\r',char(13)),'\n',char(10)),'选择怪兽','选择魔法','当作装备卡','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97947705,'备援操作员','此卡名的效果1回合仅可使用1次。①：以自己的连接怪兽连接端的1只表侧表示怪兽为对象可以发动。将此卡从手牌特殊召唤，将对象怪兽放回持有者的手牌。以此效果特殊召唤的此卡离开场上的情况下，将其除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97949165,'抒情歌鸲－绿松莺','此卡名的②效果1回合仅可使用1次。①：自己场上不存在怪兽的情况下，此卡可从手牌中特殊召唤。②：此卡从手牌特殊召唤成功的情况下可以发动。从自己的手牌・墓地挑选1只“抒情歌鸲”怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97970833,'最后胜地','对手怪兽攻击宣言时可以发动。从牌组发动１张“虹之古代都市－彩虹遗迹”。发动时对手的场地魔法卡以表侧表示存在的情况下，对手可以从牌组抽１张卡。','是否要抽一张卡？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97973387,'大嘴鸟','嘴巴非常大、会大声鸣叫来吓跑胆小的对手。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97973962,'暴走召唤师 阿莱斯特',replace(replace('种族和属性不同的怪兽2只\r\n①：此卡只要存在于场上・墓地，卡名视为“召唤师 阿莱斯特”。\r\n②：此卡存在于怪兽区域的状态下，有融合怪兽被融合召唤的情况下可以发动。挑选自己的1张手牌舍弃，从牌组将1张“召唤魔术”或“法之圣典”加入手牌。\r\n③：表侧表示的此卡因对手的效果从场上离开的情况下可以发动。从牌组将1张“魔法名－“托梅加瑟利昂”大兽”加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(97997309,'命运的魔导书',replace(replace('我方场上存在魔法师族怪兽的场合，可将我方墓地中最多３张冠有“魔导书”之名的魔法卡从游戏中除外并发动。根据为了发动此卡而除外的魔法卡的数量，适用以下效果。“命运的魔导书”１回合只可发动１张。\r\n●１张：挑选场上被盖牌的１张魔法、陷阱卡，返回至持有者手牌。\r\n●２张：挑选场上的１只怪兽，变为里侧守备或表侧攻击表示。\r\n●３张：挑选对手场上的１张卡牌从游戏中除外。','\r',char(13)),'\n',char(10)),'1张：回到手牌','2张：改变表示形式','3张：除外','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98007437,'铠骑士龙－剑侍武装龙－',replace(replace('此卡名的①②③效果１回合仅可各使用１次。\r\n①：自己将等级５以上的龙族怪兽特殊召唤的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：此卡特殊召唤的情况下可以发动。此卡的属性・等级变为与自己１只除外状态的龙族怪兽相同。\r\n③：此卡被送至墓地的情况下，以自己场上的１只龙族怪兽为对象可以发动（应对此效果的发动，双方不可发动效果）。该怪兽的攻击力上升１０００。','\r',char(13)),'\n',char(10)),'手牌特殊召唤','属性等级变换','攻击力上升','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98012938,'兽神 武尔坎',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的效果1回合仅可使用1次。\r\n①：此卡同步召唤的情况下，以自己及对手场上的各1张表侧表示卡为对象发动。将该自己及对手的表侧表示卡放回手牌。此回合，自己不可发动以此效果放回手牌的卡及其同名卡的效果。','\r',char(13)),'\n',char(10)),'返回手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98020526,'救世幻象',replace(replace('①：自己场上表侧表示的“星尘龙”或记载有该卡名的同步怪兽为发动自己卡的效果离开场上的情况下，或因自己卡的效果离开场上的情况下可以发动。从以下效果挑选１个适用。此回合，不可以自己的“救世幻象”的效果适用相同效果。\r\n●挑选该１只怪兽特殊召唤。\r\n●从对手场上・墓地挑选１只怪兽除外。\r\n●此回合，自己受到的所有伤害变为一半。','\r',char(13)),'\n',char(10)),'选那1只怪兽特殊召唤','从对手的场上·墓地选1只怪兽除外','这个回合，自己受到的全部伤害变成一半','发动','发动并使用效果','','','','','','','','','','','');
INSERT INTO texts VALUES(98022050,'珠玉兽－祖龙','此卡名的效果１回合仅可使用１次。①：此卡召唤・特殊召唤成功的情况下可以发动。从手牌及自己场上的表侧表示怪兽中，挑选“珠玉兽－祖龙”以外的１只恐龙族怪兽破坏。然后将１只原本等级与该被破坏的怪兽相同的爬虫类族・海龙族・鸟兽族怪兽或１张“进化药”魔法卡从牌组加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98024118,'白色波坦','我方场上存在有协调的场合，此卡不会因战斗被破坏。我方场上的协调因战斗被破坏并送入墓地时，给予对手生命５００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98045062,'敌人控制器',replace(replace('①：可从以下效果中选择1个发动。\r\n●以对手场上的1只表侧表示的怪兽为对象可以发动。改变该对手的表侧表示怪兽的表示形式。\r\n●解放自己场上的1只怪兽，以对手场上的1只表侧表示的怪兽为对象可以发动。直至结束阶段为止获得该表侧表示怪兽的控制权。','\r',char(13)),'\n',char(10)),'变更对手场上1只表侧表示怪兽的表示形式','获得对手场上1只表侧表示的怪兽的控制权','选择一个效果发动','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98049038,'隐形机人','只要我方场上存在有除此卡以外的冠有“机人”之名的怪兽，此卡进行了战斗的我方战斗阶段结束时，选择场上的１张魔法、陷阱卡破坏。','魔陷破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98049915,'魔法神灯','此卡可直接攻击对手玩家。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98049934,'爱皮尔莉・美丽',replace(replace('等级２怪兽×２\r\n①：１回合１次，以对手场上的１只效果怪兽为对象可以发动。将该怪兽的效果直至回合结束时为止无效。此卡持有“皮尔莉・漂亮回忆”作为超量素材的情况下，此效果在对手回合中也可以发动。②：自己发动“皮尔莉”速攻魔法卡时可以发动。将场上的该卡重叠在此卡下方作为超量素材。然后，可挑选对手场上的１只怪兽变更表示形式。此效果１回合最多可使用３次。','\r',char(13)),'\n',char(10)),'对手怪兽效果无效','发动的速攻魔法卡在此卡下面重叠','是否选对手怪兽变更表示形式？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98069388,'升天之角笛','①：自己或对手将怪兽召唤・反转召唤・特殊召唤之际，解放自己场上的１只怪兽可以发动。将其无效，将该怪兽破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98075147,'恶鬼蜗牛','凭借暗之力进化的蜗牛。它有手和脚，能迅速移动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98076754,'源质的圣选士',replace(replace('①：根据自己额外牌组的表侧表示“源质”怪兽的种类，获得以下效果。\r\n●３种以上：自己场上怪兽的攻击力上升相当于双方额外牌组的表侧表示卡数量×１００的数值。\r\n●５种以上：自己场上的怪兽不会因对手的效果被破坏。\r\n●８种以上：自己场上的怪兽不会成为对手效果的对象。\r\n●１０种：将魔法与陷阱区域表侧表示的此卡送至墓地可以发动。将对手手牌・场上・墓地的卡全部放回持有者的牌组。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98093548,'俊炎星－象清',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡召唤・特殊召唤的情况下，将自己场上的１张表侧表示的“炎舞”魔法・陷阱卡送至墓地可以发动。从手牌将１只“俊炎星－象清”以外的“炎星”怪兽特殊召唤。\r\n②：以自己墓地的１张“炎舞”魔法・陷阱卡为对象可以发动。将该卡放回牌组。然后，可从牌组将１只等级５以上的“炎星”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','是否从牌组把「炎星」怪兽加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98095162,'光道主宰者 居理阿斯',replace(replace('属性相同种族不同的怪兽3只\r\n此卡名的①②效果1回合仅可各使用1次。①：此卡连接召唤成功的情况下可以发动。从牌组挑选1张卡送至墓地。②：自己牌组的卡因效果被送至墓地的情况下发动。从自己牌组上面将3张卡送至墓地。③：表侧表示的此卡因对手的效果从场上离开的情况下，或因战斗被破坏的情况下，以自己墓地的1张卡为对象可以发动。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98126725,'紫炎之参谋','自己场上有“六武众”怪兽存在的情况下，此卡召唤成功时，宣言１个种族可以发动。只要此卡以表侧表示存在于场上，所宣言种族的怪兽不可攻击宣言，双方不可特殊召唤所宣言种族的怪兽。','攻击限制','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98127546,'闭界冥神 蚀日的埃列丝',replace(replace('效果怪兽4只以上\r\n要连接召唤此卡的情况下，可将对手场上的1只怪兽作为连接素材。\r\n①：此卡连接召唤的情况下可以发动。对手场上所有表侧表示怪兽的效果无效化。\r\n②：连接召唤的此卡不受对手发动的效果影响，除非是以此卡为对象的效果。\r\n③：1回合1次，对手发动包含从墓地将怪兽特殊召唤的效果在内的、魔法・陷阱・怪兽的效果时可以发动。将该发动无效。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98127547,'闭界冥神 蚀日的埃列丝',replace(replace('效果怪兽4只以上\r\n要连接召唤此卡的情况下，可将对手场上的1只怪兽作为连接素材。\r\n①：此卡连接召唤的情况下可以发动。对手场上所有表侧表示怪兽的效果无效化。\r\n②：连接召唤的此卡不受对手发动的效果影响，除非是以此卡为对象的效果。\r\n③：1回合1次，对手发动包含从墓地将怪兽特殊召唤的效果在内的、魔法・陷阱・怪兽的效果时可以发动。将该发动无效。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98139712,'死灵的诱惑','每将１张卡牌送入墓地，卡牌持有者便会受到３００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98143165,'同步英雄','①：装备怪兽的等级提升１，攻击力上升５００。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98147766,'基因女战士','１回合１次，可支付１０００LP，选择我方从游戏中被除外的１只念动力族怪兽并发动。将被除外的该怪兽加入手牌。','加入手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98153934,'魅影死枪',replace(replace('①：只要此卡存在于魔法与陷阱区域，每当对手发动以自己场上的“魅影骑士团”怪兽为对象的效果，就给予对手500伤害。\r\n②：自己场上的暗属性怪兽将被战斗或对手的效果破坏的情况下，作为代替可将墓地的此卡除外。','\r',char(13)),'\n',char(10)),'是否使用「魅影死枪」的效果代替破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98154550,'原始蝴蝶',replace(replace('①：我方场上不存在有怪兽的场合，此卡可从手牌特殊召唤。\r\n②：１回合１次，在我方主要阶段可发动。我方场上所有昆虫族怪兽的等级提升１级。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98159737,'天威龙－阿靼剌','此卡名的①②效果1回合仅可各使用1次。①：自己场上没有效果怪兽存在的情况下可以发动。从手牌将此卡特殊召唤。②：自己场上有效果怪兽以外的表侧表示怪兽存在的情况下，将手牌・墓地的此卡除外，以此卡以外的被除外的自己的1只幻龙族怪兽为对象可以发动。将该怪兽加入手牌。','特殊召唤','回收除外的卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98162021,'紫炎的荒武者','此卡召唤成功时，放置１个武士道计数物（最多１个）于此卡。此卡上放置有武士道计数物的场合，此卡的攻击力上升３００点。此外，１回合１次，可移除此卡的武士道计数物，选择场上的１张可放置武士道计数物的表侧表示卡牌，并放置１个武士道计数物。','放置武士道计数物','请选择要放置「武士道计数物」的卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98162242,'钢针蝎','此卡战斗破坏怪兽并将其送往墓地的情况下发动。给予对手LP被破坏的怪兽的等级×５００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98167225,'创神之华耳琴璃',replace(replace('此卡名的②③效果１回合仅可各使用１次。\r\n①：只要自己场上存在６个以上的响鸣计数物，自己场上的“华耳琴璃”连接怪兽的攻击力上升１２００。\r\n②：对手将怪兽特殊召唤的情况下可以发动。进行１只“华耳琴璃”连接怪兽的连接召唤。\r\n③：此卡从手牌・场上被送至墓地的情况下可以发动。在自己灵摆区域可放响鸣计数物的１张卡上放响鸣计数物，直至变为３个。','\r',char(13)),'\n',char(10)),'连接召唤','放置计数物','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98169343,'淘气仙星・卡罗贝恩',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：自己场上的怪兽，不存在的情况下或仅有“淘气仙星”怪兽的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：自己的“淘气仙星”怪兽与对手怪兽进行战斗的伤害步骤开始时至伤害计算前为止，从手牌将此卡送至墓地可以发动。该自己的怪兽的攻击力直至回合结束时为止，上升相当于其原本攻击力的数值。','\r',char(13)),'\n',char(10)),'特殊召唤','攻击上升','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98173209,'深红地狱盖亚',replace(replace('此卡名的①②③效果１回合仅可各使用１次。\r\n①：在自己的主要阶段可以发动。从自己的牌组・墓地将“深红地狱盖亚”以外的、１张记载有“暗红恶魔龙”卡名的卡加入手牌。\r\n②：自己的“暗红恶魔龙”的攻击宣言时可以发动。将对手场上的怪兽全部改成里侧守备表示。\r\n③：场上的怪兽因战斗・效果被破坏的情况下可以发动。从自己的墓地将１只“暗红恶魔龙”特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98204536,'先史遗产惊神殿 三巨石',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己场上不存在怪兽的情况下，或仅有“先史遗产”怪兽的情况下，支付５００LP可以发动。从手牌召唤１只“先史遗产”怪兽。\r\n②：自己的“先史遗产”超量怪兽或自己的“编号”超量怪兽去除超量素材发动效果的情况下，可将此卡送至墓地作为去除１个超量素材的代替。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98225108,'人狮兽','此卡和通常怪兽以外的怪兽进行战斗的场合，伤害步骤期间，攻击力上升５００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98229575,'超级运动员四分卫',replace(replace('１回合只可使用１次以“超级运动员四分卫”①方法的特殊召唤。\r\n①：此卡可将１只除“超级运动员四分卫”以外的我方场上的“超级运动员”怪兽返回至手牌，并从手牌特殊召唤。\r\n②：在除此卡以外的我方“超级运动员”怪兽的攻击宣言时可发动。此卡的攻击力下降８００，并且我方攻击怪兽的攻击力上升８００。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98234196,'魔键铳士－克莱维斯',replace(replace('人皆充满可能性。前行亦或停止，上锁亦或解锁，皆由自己做主。\r\n世界令人眼花缭乱，有门无数。能将之解开的是魔法钥匙。２把钥匙开１扇门。２股意志呈１副模样。若能打开门，则世界相连，巨大的力量面目浮现。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98239899,'锁链炸弹','可选择我方场上的１只表侧表示怪兽发动此卡。将此卡视为攻击力上升５００点的装备卡，并装备在被选择的我方怪兽。被视为装备卡的此卡因卡牌效果被破坏时，选择场上的１张卡牌并破坏。','破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98248208,'暗黑海龙－龙三角',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡存在于手牌，且自己场上・墓地・除外状态的等级10怪兽为3只以上的情况下可以发动。将此卡特殊召唤。\r\n②：此卡特殊召唤的情况下，将自己牌组最上面的卡送至墓地可以发动。此卡的攻击力上升500。然后，被送至墓地的卡是怪兽的情况下，给予对手1000伤害。不是的情况下，可将自己牌组最上面的卡送至墓地。','\r',char(13)),'\n',char(10)),'特殊召唤','送至墓地发动','是否把牌组最上面的卡送至墓地？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98252586,'追寻之风','仅限装备鸟兽族怪兽。令１只装备怪兽的攻击力和守备力上升３００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98259197,'扰乱怪肌肉','可选择场上的１只“扰乱怪之王”并发动。破坏场上所有除被选择的“扰乱怪之王”以外的冠有“扰乱怪”之名的怪兽，被选择的“扰乱怪之王”的攻击力上升被破坏怪兽的数量×１０００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98263709,'银河魔镜士','反转：我方回复我方墓地冠有“银河”之名怪兽的数量×５００LP。此外，反转的此卡被破坏并送入墓地时，可从我方牌组、墓地挑选１只等级４或以下冠有“银河”之名的怪兽，并以里侧守备表示特殊召唤。以此效果特殊召唤的怪兽从场上离开的场合，从游戏中被除外。','抽牌','特殊召唤并除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98266377,'元素－英雄 炙热','①：此卡的攻击力上升我方场上“元素－英雄”怪兽数量×２００。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98273947,'天使升降','可选择我方墓地的１只等级２或以下的怪兽并发动此卡。以攻击表示特殊召唤被选择怪兽。此卡从场上离开时，破坏该怪兽。该怪兽从场上离开时，破坏此卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98280324,'绒毛动物・羊','此卡名的②效果1回合仅可使用1次。①：自己场上有“绒毛动物・羊”以外的“绒毛动物”怪兽存在的情况下，此卡可从手牌中特殊召唤。②：将自己场上此卡以外的1只“绒毛动物”怪兽放回持有者的手牌可以发动。从自己的手牌・墓地挑选1只“锋利小鬼”怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98287529,'虚龙魔王 无形因子心',replace(replace('以“无形假面”降临。\r\n①：此卡仪式召唤成功的情况下，跳过下一个对手的主要阶段１。\r\n②：只要此卡存在于怪兽区域，场上表侧表示的融合・同步・超量怪兽的效果无效化。\r\n③：此卡从场上被送至墓地的情况下可以发动。从牌组将１只“虚龙魔王 无形因子心”以外的“龙魔王”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98299011,'神圣精灵的祝福','我方回复场上存在的怪兽数量×３００LP。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98301564,'解放之阿里阿德涅',replace(replace('←3 【灵摆】 3→\r\n①：只要此卡存在于灵摆区域，适用以下效果。\n●自己不需为发动反击陷阱卡支付LP。\n●自己不需为发动反击陷阱卡舍弃手牌。\r\n【怪兽效果】\r\n①：此卡因战斗・效果被破坏的情况下可以发动。从牌组将３张反击陷阱卡出示给对手，对手从其中挑选１张。将该１张卡加入自己的手牌，剩余的放回牌组。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98319530,'『焰圣剑－阿尔梅斯』',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：此卡被装备中的情况下可以发动。从自己的牌组・墓地挑选“『焰圣剑－阿尔梅斯』”以外的１张“焰圣剑”装备魔法卡，装备于自己场上可装备该卡的１只怪兽。然后，将此卡破坏。\r\n②：因装备怪兽被送至墓地导致此卡被送至墓地的情况下，以自己的墓地・除外状态的１只战士族・炎属性怪兽为对象可以发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98336111,'融合杀手','与此卡进行了战斗的融合怪兽的攻击力，在伤害步骤期间变为０。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98338152,'闪刀机－黑寡妇锚','①：自己的主要怪兽区域不存在怪兽的情况下，以场上的1只效果怪兽为对象可以发动。将该怪兽的效果直至回合结束时为止无效。然后，自己墓地存在3张以上的魔法卡的情况下，可获得该怪兽的控制权直至结束阶段为止。','是否获得控制权？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98338153,'闪刀机－黑寡妇锚','①：自己的主要怪兽区域不存在怪兽的情况下，以场上的1只效果怪兽为对象可以发动。将该怪兽的效果直至回合结束时为止无效。然后，自己墓地存在3张以上的魔法卡的情况下，可获得该怪兽的控制权直至结束阶段为止。','是否获得控制权？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98349765,'第19层 “袭来干涉！漆黑的超级量子士！！”',replace(replace('①：可从以下效果中选择1个发动（此卡名的以下效果1回合仅可各选择1次）。\r\n●以场上1只攻击表示的怪兽为对象可以发动。将该怪兽改成守备表示。\r\n●自己场上存在“超级量子”怪兽的情况下可以发动。从牌组将与自己场上怪兽的原本属性不同的1只“超级量子”怪兽以守备表示特殊召唤。\r\n●从牌组将1张“超级量子”陷阱卡放置在自己场上。以此效果放置的卡在放置的回合也可以发动。','\r',char(13)),'\n',char(10)),'发动','改变表示形式','特殊召唤','放置陷阱','适用「第19层 “袭来干涉！漆黑的超级量子士！！”」的效果来发动','','','','','','','','','','','');
INSERT INTO texts VALUES(98358303,'静寂的念力女巫',replace(replace('①：场上的此卡被破坏并被送至墓地时可以发动。从牌组将1只攻击力2000以下的念动力族怪兽除外。\r\n②：以此卡的①效果除外了怪兽的情况下，在下个准备阶段于墓地发动。将该除外状态的怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'除外','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98360333,'邪恶★双子 挑战',replace(replace('此卡名的卡1回合仅可发动1张。①：以自己墓地的1只“姬丝吉尔”怪兽或“璃拉”怪兽为对象可以发动。将该怪兽特殊召唤。然后，可适用以下效果。\r\n●以自己场上的怪兽作为连接素材，将1只“邪恶★双子”连接怪兽连接召唤。','\r',char(13)),'\n',char(10)),'是否连接召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98371278,'非军事区龙',replace(replace('①：１回合１次，以自己墓地的１只等级４以下龙族怪兽和自己场上的１只龙族怪兽为对象可以发动。将对象的墓地怪兽视为攻击力上升５００的装备卡，装备于对象的场上怪兽。\r\n②：装备了装备卡的自己的怪兽攻击的伤害步骤结束时，将墓地的此卡除外可以发动。将该自己的怪兽的装备卡全部破坏。破坏的情况下，该怪兽可继续攻击仅１次。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98374133,'觉醒','仅限装备地属性怪兽。令装备怪兽的攻击力上升４００点，守备力下降２００点。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98380593,'至高的果实','此卡发动时，我方LP低于对手的场合，我方回复２０００点LP。我方LP高于对手的场合，我方受到１０００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98385955,'白森的西尔薇',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从牌组将1张“白森”魔法・陷阱卡加入手牌。\r\n②：在自己・对手回合中，此卡存在于墓地的情况下，以自己场上・墓地的1只“白森”同步怪兽为对象可以发动。将该怪兽放回额外牌组，将此卡的效果无效并特殊召唤。','\r',char(13)),'\n',char(10)),'加入手牌','墓地特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98396890,'视界共鸣者',replace(replace('此卡名以①方法的特殊召唤１回合仅可进行１次，且②效果１回合仅可使用１次。\r\n①：场上存在等级５以上的暗属性怪兽的情况下，此卡可从手牌中特殊召唤。\r\n②：此卡被送至墓地的情况下可以发动。从牌组将１张记载有“暗红恶魔龙”卡名的魔法・陷阱卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98414735,'伯吉斯吸虫・加拿大虫',replace(replace('①：以对手场上的1只表侧表示怪兽为对象可以发动。将该怪兽改成里侧守备表示。\r\n②：此卡存在于墓地，且陷阱卡发动时可以发动（同一连锁上最多1次）。此卡变为通常怪兽（水族・水・星2・攻1200/守0），特殊召唤至怪兽区域（不视为陷阱卡）。以此效果特殊召唤的此卡不受怪兽效果影响，从场上离开的情况下将被除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98416533,'梅尔菲・瓦莱皮','此卡名的①②效果１回合仅可各使用１次。①：对手将怪兽召唤・特殊召唤成功的情况下，或此卡被选择为对手怪兽的攻击对象的情况下可以发动。将此卡放回持有者的手牌。然后，可从牌组将“梅尔菲・瓦莱皮”以外的２只“梅尔菲”怪兽特殊召唤（同名卡最多１张）。②：在自己的结束阶段可以发动。从手牌将此卡特殊召唤。','此卡回到持有者手牌','','是否从牌组特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98427577,'铁屑稻草人','①：对手怪兽攻击宣言时，以1只攻击怪兽为对象可以发动。将该攻击无效。发动后此卡不会送往墓地，而是就此放置。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98431356,'魅影翼','此卡名的②效果1回合仅可使用1次。①：以场上1只表侧表示怪兽为对象可以发动。该怪兽的攻击力上升500，此回合仅限1次不会因战斗・效果被破坏。②：将墓地的此卡除外，以自己墓地的1只“魅影骑士团”怪兽为对象可以发动。将该怪兽特殊召唤。以此效果特殊召唤的怪兽离开场上的情况下，将其除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98434877,'水魔神－苏迦','①：只要此卡在场上以表侧表示存在，仅限１次，此卡被攻击的伤害计算时，以１只攻击怪兽为对象可以发动。仅在该伤害计算时将该攻击怪兽的攻击力改成０。','攻击变成0','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98437424,'大植然波斯菊株','①：对手将怪兽通常召唤时可以发动。从手牌将此卡特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98439949,'无限起动 蟹式起重机','此卡名的①②效果１回合仅可各使用１次。①：解放自己场上的１只机械族・地属性怪兽可以发动。将此卡从手牌以守备表示特殊召唤。②：从自己的墓地将１只机械族怪兽除外可以发动。从牌组将１张“超接地展开”加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98444741,'积累的幸福','连锁４以后可发动。从牌组抽取２张卡牌。同一连锁上复数同名卡效果发动的场合，此卡不可发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98446407,'奈芙蒂斯的引导者','①：解放自己场上的１只怪兽和此卡可以发动。从手牌・牌组将１只“奈芙蒂斯之凤凰神”特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98452268,'霸王黑龙 异色眼反叛龙－霸主',replace(replace('←4 【灵摆】 4→\r\n①：１回合１次，在自己的主要阶段可以发动。将灵摆区域的此卡特殊召唤，将１只“反叛”怪兽或“魅影骑士团”怪兽重叠在此卡上面，视为超量召唤从额外牌组特殊召唤。然后，可将自己的灵摆区域的１张卡作为该怪兽的超量素材。\r\n【怪兽效果】\r\n等级７怪兽×２\n自己１回合仅可特殊召唤１次“霸王黑龙 异色眼反叛龙－霸主”。\n此卡也可重叠在自己场上的“反叛”超量怪兽上面来超量召唤。在可灵摆召唤等级７的情况下，额外牌组表侧的此卡可以灵摆召唤。\n①：以阶级７超量怪兽作为素材超量召唤的此卡在１次战斗阶段中可攻击３次。\n②：怪兽区域的此卡被破坏的情况下可以发动。将此卡放在自己的灵摆区域。','\r',char(13)),'\n',char(10)),'是否在「反叛」超量怪兽上面重叠来超量召唤？','','','是否选自己的灵摆区域1张卡作为超量素材？','７阶超量怪兽为素材作超量召唤','','','','','','','','','','','');
INSERT INTO texts VALUES(98456117,'骨海马','在海中徘徊，一旦发现猎物就会将吸乾其所有的水分。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98462037,'闪刀姬－阿萨蕾娅',replace(replace('光・暗属性怪兽２只\r\n此卡仅可以连接召唤方式特殊召唤，自己１回合仅可特殊召唤１次“闪刀姬－阿萨蕾娅”。\r\n①：此卡特殊召唤的情况下，以场上的１张卡为对象可以发动。将该卡破坏。然后，自己墓地的魔法卡为３张以下的情况下，将此卡送至墓地。\r\n②：１回合１次，此卡与对手怪兽进行战斗的伤害步骤开始时，从自己的墓地将１张魔法卡除外可以发动。将该对手的怪兽破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98476659,'怠慢之壶','①：自己依对手场上卡的数量抽牌。抽2张以上的情况下，进而依该数量-1，挑选自己手牌以喜欢的顺序放回牌组下面。此卡发动后，直至回合结束时为止自己不可发动“怠慢之壶”。','发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98477480,'肃声结界',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：只要自己场上存在“肃声之祈祷者 律”及光属性仪式怪兽，对手怪兽仅可将仪式怪兽选择为攻击对象，对手不可将自己场上的光属性怪兽作为效果的对象。\r\n②：在自己的主要阶段可以发动。从牌组将除“肃声结界”之外的１张“肃声”卡或１只“律守护者”仪式怪兽加入手牌。','\r',char(13)),'\n',char(10)),'检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98494543,'魔法石的采掘','①：扔掉2张手牌，可以自己墓地1张魔法卡为对象发动。将该卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98495314,'执念之剑',replace(replace('①：装备怪兽的攻击力・守备力上升500。\r\n②：此卡被送至墓地的情况下发动。将此卡放回牌组最上面。','\r',char(13)),'\n',char(10)),'返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98502113,'超魔导剑士－黑暗帕拉丁',replace(replace('“黑魔导”＋“毁灭剑士”\r\n此卡仅可以融合召唤特殊召唤。\r\n①：此卡的攻击力上升双方场上、墓地的龙族怪兽数量×５００点。\r\n②：魔法卡发动时，可舍弃１张手牌发动。此卡以表侧表示存在于场上的场合，使该发动无效并破坏。','\r',char(13)),'\n',char(10)),'魔法发动无效并破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98502114,'超魔导剑士－黑暗帕拉丁',replace(replace('“黑魔导”＋“毁灭剑士”\r\n此卡仅可以融合召唤特殊召唤。\r\n①：此卡的攻击力上升双方场上、墓地的龙族怪兽数量×５００点。\r\n②：魔法卡发动时，可舍弃１张手牌发动。此卡以表侧表示存在于场上的场合，使该发动无效并破坏。','\r',char(13)),'\n',char(10)),'魔法发动无效并破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98502115,'超魔导剑士－黑暗帕拉丁',replace(replace('“黑魔导”＋“毁灭剑士”\r\n此卡仅可以融合召唤特殊召唤。\r\n①：此卡的攻击力上升双方场上、墓地的龙族怪兽数量×５００点。\r\n②：魔法卡发动时，可舍弃１张手牌发动。此卡以表侧表示存在于场上的场合，使该发动无效并破坏。','\r',char(13)),'\n',char(10)),'魔法发动无效并破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98502116,'超魔导剑士－黑暗帕拉丁',replace(replace('“黑魔导”＋“毁灭剑士”\r\n此卡仅可以融合召唤特殊召唤。\r\n①：此卡的攻击力上升双方场上、墓地的龙族怪兽数量×５００点。\r\n②：魔法卡发动时，可舍弃１张手牌发动。此卡以表侧表示存在于场上的场合，使该发动无效并破坏。','\r',char(13)),'\n',char(10)),'魔法发动无效并破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98502117,'超魔导剑士－黑暗帕拉丁',replace(replace('“黑魔导”＋“毁灭剑士”\r\n此卡仅可以融合召唤特殊召唤。\r\n①：此卡的攻击力上升双方场上、墓地的龙族怪兽数量×５００点。\r\n②：魔法卡发动时，可舍弃１张手牌发动。此卡以表侧表示存在于场上的场合，使该发动无效并破坏。','\r',char(13)),'\n',char(10)),'魔法发动无效并破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98506199,'风飞马＠伊格尼斯者',replace(replace('协调＋协调以外的怪兽1只以上\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：在自己的主要阶段可以发动。以自己场上的“＠伊格尼斯者”怪兽的数量为上限，将对手场上的魔法・陷阱卡破坏。\r\n②：此卡存在于怪兽区域或墓地的状态下，此卡以外的自己场上的卡因战斗或对手的效果被破坏的情况下，将此卡除外，以对手场上的1张卡为对象可以发动。将该卡放回牌组。','\r',char(13)),'\n',char(10)),'','对方卡回到牌组','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98520301,'财富螳螂',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n \r\n①：对手场上存在等级6以下的怪兽的情况下可以发动。从手牌将此卡特殊召唤。 \r\n②：自己的手牌多于对手的情况下可以发动。变更场上所有怪兽的表示形式。场上的其他昆虫族怪兽的属性・等级变为与此卡相同。此回合，自己仅可特殊召唤昆虫族怪兽。 \r\n③：此卡被破坏的情况下可以发动。从牌组将1只等级8以上的昆虫族怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98535702,'伤害疫苗ΩMAX','我方因战斗或卡牌效果而受到伤害时可发动。我方回复我方的LP，其数量相当于我方受到的该伤害数值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98552723,'再临的帝王',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：以自己墓地的1只攻击力2400/守备力1000的怪兽或攻击力2800/守备力1000的怪兽为对象可以发动此卡。将该怪兽的效果无效并以守备表示特殊召唤，装备此卡。此卡从场上离开时，该怪兽将被破坏。\r\n②：要上级召唤怪兽的情况下，装备怪兽可作为2只解放。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98555327,'银河魔导师','①：１回合１次，在自己的主要阶段可以发动。此卡的等级直至回合结束时为止上升４。②：解放此卡可以发动。从牌组将１张“银河魔导师”以外的“银河”卡加入手牌。','等级上升','牌组检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98558751,'T.G.奇妙魔术师',replace(replace('协调＋协调以外的“T.G.”怪兽1只以上\r\n①：此卡同步召唤的情况下，以场上的1张魔法・陷阱卡为对象发动。将该卡破坏。\r\n②：在对手的主要阶段可以发动（同一连锁上最多1次）。将包含此卡在内的、自己场上的怪兽作为素材进行同步召唤。\r\n③：场上的此卡被破坏的情况下发动。自己抽1张。','\r',char(13)),'\n',char(10)),'场上1张魔法·陷阱卡破坏','抽牌','同步召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98567237,'契印魔镌・咏圣颂',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：从牌组将１只恶魔族・光属性怪兽加入手牌。然后，挑选自己的１张手牌舍弃。\r\n②：将墓地的此卡除外可以发动。将自己的手牌・场上的怪兽作为融合素材，将１只“魔镌”融合怪兽融合召唤。','\r',char(13)),'\n',char(10)),'检索效果','融合召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98570539,'混沌之梦魔镜','此卡名的卡1回合仅可发动1张。①：将由“梦魔镜”融合怪兽卡决定的融合素材怪兽从自己场上送至墓地，从额外牌组将1只该融合怪兽融合召唤。场地区域有“圣光之梦魔镜”存在的情况下，手牌的怪兽也可作为融合素材。场地区域有“暗黑之梦魔镜”存在的情况下，也可将自己墓地的怪兽除外作为融合素材。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98582704,'羽翼蛋精灵','身体被蛋壳包覆的天使。以巨大的翅膀来阻挡攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98585345,'羽翼库里波 LV10',replace(replace('此卡不可通常召唤，仅可通过“进化之翼”的效果特殊召唤。\r\n①：在对手的战斗阶段，解放此卡可以发动。将对手场上的攻击表示怪兽全部破坏，给予对手相当于所破坏怪兽原本攻击力合计数值的伤害。','\r',char(13)),'\n',char(10)),'破坏并伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98596596,'灵魂游荡的墓场',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n①：此卡已存在于魔法与陷阱区域的状态下，自己场上的怪兽被战斗破坏送至墓地的情况下发动。将１只“火球衍生物”（炎族・炎・星１・攻／守１００）特殊召唤至自己场上。\r\n②：此卡已存在于魔法与陷阱区域的状态下，自己的手牌・场上的怪兽因为对手的效果被送至墓地的情况下发动。将最多该怪兽数量的“火球衍生物”尽可能多地特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98596597,'火球衍生物','由「灵魂游荡的墓场」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98630720,'枪管终极龙',replace(replace('效果怪兽3只以上\r\n此卡名的③效果1回合仅可使用1次。\r\n①：场上的此卡不会因战斗・效果被破坏，双方不可将此卡作为怪兽的效果的对象。\r\n②：此卡可攻击所有对手怪兽各1次。\r\n③：在自己・对手回合中，以场上的1只效果怪兽和自己墓地的1只“枪弹”怪兽为对象可以发动（应对此发动，对手不可发动卡的效果）。将该场上的怪兽的效果无效，将该墓地的怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98630721,'枪管终极龙',replace(replace('效果怪兽3只以上\r\n此卡名的③效果1回合仅可使用1次。\r\n①：场上的此卡不会因战斗・效果被破坏，双方不可将此卡作为怪兽的效果的对象。\r\n②：此卡可攻击所有对手怪兽各1次。\r\n③：在自己・对手回合中，以场上的1只效果怪兽和自己墓地的1只“枪弹”怪兽为对象可以发动（应对此发动，对手不可发动卡的效果）。将该场上的怪兽的效果无效，将该墓地的怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98637386,'御用捕食者',replace(replace('协调＋协调以外的怪兽１只或以上\r\n“御用捕食者”的效果１回合只可使用１次。\r\n①：此卡因战斗破坏对手怪兽并送入墓地时可发动。将该怪兽特殊召唤至我方场上。以此效果特殊召唤的怪兽给予玩家的战斗伤害减半。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98642179,'刚炎之骑士',replace(replace('卡名不同的怪兽２只\r\n此卡名的②效果１回合仅可使用１次。\r\n①：场上的战士族怪兽的攻击力上升５００。\r\n②：连接召唤的此卡因战斗或对手的效果被破坏的情况下，以连接怪兽以外的、自己墓地的１只战士族怪兽为对象可以发动。将该怪兽特殊召唤。以此效果特殊召唤的怪兽从场上离开的情况下，将其除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98643358,'钻石尘埃','破坏场上的所有水属性怪兽。然后，给予对手LP以此效果被破坏并被送至墓地的水属性怪兽数量×５００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98645731,'强欲而谦虚之壶','此卡名的卡１回合仅可发动１张，发动此卡的回合中，自己不可特殊召唤怪兽。①：从自己的牌组上面翻开３张卡，从其中挑选１张加入手牌，然后将剩余的卡放回牌组。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98649372,'骷髅海怪','此卡成功召唤时，可选择对手场上１张面朝上的魔法卡并将其破坏。１回合１次，可以在我方的主要阶段发动。改变此卡的战斗状态。','魔法破坏','改变表示形式','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98666339,'反转次元','原本持有者是我方的怪兽因对手效果而从游戏中被除外时可发动。选择１只该怪兽特殊召唤至我方场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98672567,'贪欲而无欲之壶','发动此卡的回合中，自己无法进行战斗阶段。①：自己的主要阶段１开始时，以自己墓地的３只怪兽为对象可以发动（同种族最多１只）。将该３只怪兽放回牌组并洗牌。然后，自己从牌组抽２张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98684051,'白鰯',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：从牌组将１只“白鰯”送至墓地可以发动。从手牌将此卡特殊召唤。此效果发动后，直至回合结束时为止，自己从额外牌组仅可特殊召唤水属性怪兽。\r\n②：此卡从墓地特殊召唤的情况下可以发动。此回合，此卡视为协调。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98684220,'超魔剑士 黑暗混沌',replace(replace('此卡不可通常召唤。\r\n“超魔剑士 黑暗混沌”1回合1次，仅可在从自己手牌・墓地将1只魔法师族・战士族的仪式怪兽放回牌组的情况下特殊召唤。\r\n①：从手牌将此卡舍弃可以发动。从自己牌组・墓地将1张记载有“光与暗的仪式”卡名的永续陷阱卡以表侧表示放在自己场上。\r\n②：只要自己墓地存在仪式魔法卡，此卡不受对手发动的效果影响。\r\n③：1回合1次，在自己的主要阶段可以发动。将对手场上的2张卡除外。','\r',char(13)),'\n',char(10)),'放置','除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98696958,'暗黑回廊',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从牌组将1只“暗黑界”怪兽加入手牌。然后，挑选自己的1张手牌舍弃。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98700941,'淘气仙星・莉莉贝尔',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：用抽牌以外的方法将此卡加入手牌的情况下可以发动。将此卡特殊召唤。\r\n②：此卡可直接攻击。\r\n③：此卡给予对手战斗伤害时，以自己墓地的１只“淘气仙星”怪兽为对象可以发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98707192,'鬼计・玛丽','仅在自己场上有“鬼计”怪兽存在的情况下，此卡才可以表侧表示召唤。此卡名的①效果１回合仅可使用１次。①：自己因战斗・效果受到伤害时，从手牌将此卡舍弃可以发动。从牌组将１只“鬼计”怪兽以里侧守备表示特殊召唤。②：在自己的主要阶段可以发动。将此卡改成里侧守备表示（１回合仅１次）。','变成里侧守备','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98715423,'守墓的陷阱',replace(replace('此卡名的②③效果1回合仅可各使用1次。\r\n①：只要自己墓地存在“现世与冥界的逆转”，对手不可发动墓地的卡的效果，不可特殊召唤墓地的怪兽。\r\n②：在自己・对手的主要阶段，舍弃1张手牌可以发动。从牌组将1只“守墓”怪兽或天使族・地属性怪兽加入手牌。\r\n③：此卡以表侧表示存在的情况下，在对手的抽牌阶段的抽牌之前，宣言1个卡名发动。确认通常抽牌所抽的卡，是所宣言的卡的情况下，送至墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98719226,'外星人战士','此卡因战斗被破坏并送入墓地时，在破坏此卡的怪兽放置２个A计数物。只要此卡以表侧表示存在于场上，仅限在放置有A计数物的怪兽与冠有“外星人”之名的怪兽进行战斗的伤害计算时，攻击力、守备力下降该A计数物数量×３００点。','放置「A计数物」','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98745000,'胡狼的圣战士','此卡因战斗破坏对手怪兽并送入对手的墓地时可发动。将该卡返回至对手牌组的最上面。','返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98753320,'幻变骚灵・故障转移','此卡名的①②效果1回合仅可各使用1次。①：此卡以外的自己场上的卡因对手的效果被破坏的情况下可以发动。从手牌将1只“幻变骚灵”怪兽特殊召唤。②：将墓地的此卡除外，以自己墓地的1只“幻变骚灵”怪兽为对象可以发动。将该怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98777036,'悲怆魔','①：自己受到了战斗伤害时可以发动。从手牌将此卡特殊召唤。②：此卡的攻击力・守备力上升自己的手牌数量×600。③：1回合1次，可从手牌将1只怪兽送至墓地，以与该怪兽同等级的、对手场上的1只表侧表示怪兽为对象发动。获得该表侧表示怪兽的控制权。④：1回合1次，可以自己墓地的1只怪兽为对象发动。此卡的等级直至回合结束时为止变为与该怪兽相同。','特殊召唤','得到控制权','改变等级','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98780137,'噬恶・餐刀','此卡召唤成功时，可从我方墓地选择１只除“噬恶・餐刀”以外的冠有“噬恶”之名的怪兽并特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98787535,'溟界之昏暗－乌濑特','此卡名的①②效果1回合仅可各使用1次。①：此卡存在于墓地的情况下，解放自己场上的1只怪兽可以发动。将此卡特殊召唤。然后，对手可从自身的墓地挑选1只怪兽加入手牌。②：此卡特殊召唤成功的情况下，从被除外的自己的怪兽中，以包括爬虫类族怪兽在内的2只怪兽为对象可以发动。将该怪兽放回墓地。','','','是否从墓地选怪兽加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98792570,'继承之力','将我方场上的１只怪兽送入墓地。选择我方场上的１只怪兽。所选择怪兽的攻击力上升送入墓地的怪兽卡的攻击力数值，直到发动回合的结束阶段。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98795934,'魔加农炮','大炮般的恶魔。会以肉眼看不到的速度发射眼球飞弹。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98804359,'利维坦的激昂',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从牌组将1张“激流葬”加入手牌。\r\n②：自己场上的水属性怪兽将被效果破坏的情况下，作为代替可将墓地的此卡除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98806751,'执爱之轮回化勒','此卡名的①②效果1回合仅可各使用1次。①：在此卡存在于手牌中的情况下，以自己场上・墓地的1只同步怪兽为对象可以发动。将该怪兽除外，将此卡特殊召唤。②：此卡存在于墓地的情况下，以自己场上・墓地的1只同步怪兽为对象可以发动。将该怪兽除外，将此卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98818516,'杀手熊猫','总是带着一根粗竹子，性格极其凶猛。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98827725,'魅影骑士团暗影铠甲',replace(replace('此卡名的卡１回合仅可发动１张。\r\n自己墓地不存在陷阱卡的情况下，此卡在放置的回合也可以发动。\r\n①：此卡发动后，变为通常怪兽（战士族・暗・星４・攻０／守３００），以守备表示特殊召唤至怪兽区域（不视为陷阱卡）。','\r',char(13)),'\n',char(10)),'适用「魅影骑士团 阴暗布面甲」的效果来发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98828338,'灰灭的愤怒',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：从牌组将１只炎族・暗属性怪兽送至墓地。然后，可从自己墓地将１只等级５以上的炎族怪兽加入手牌。此卡发动后，直至回合结束时为止，自己从额外牌组仅可特殊召唤炎族怪兽。\r\n②：将墓地的此卡除外可以发动。将自己手牌・场上的怪兽作为融合素材，将１只炎族的融合怪兽融合召唤。','\r',char(13)),'\n',char(10)),'','融合召唤','是否把炎族怪兽加入手牌？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98829635,'禁忌的圣冠',replace(replace('此卡名的卡1回合仅可发动1张，应对此卡的发动，不可发动怪兽的效果。\r\n①：挑选场上的1只表侧表示怪兽，直至回合结束时为止适用以下效果。\r\n●效果无效化。\r\n●不可攻击。\r\n●不会因战斗・效果被破坏。\r\n●不受自身以外的卡发动的效果影响。\r\n●不可解放。\r\n●不可作为融合・同步・超量・连接召唤的素材。','\r',char(13)),'\n',char(10)),'发动','「禁忌的圣冠」效果适用中','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98847704,'拘束解放波','可选择我方场上１张表侧表示的装备魔法卡来发动此卡。破坏选择的装备魔法卡和对手场上所有被盖牌的魔法・陷阱卡。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98850929,'圣蛇的息吹',replace(replace('自己场上有仪式・融合・同步・超量怪兽中的２种以上存在的情况下，根据该怪兽的种类，可从以下效果中选择１个以上发动。“圣蛇的息吹”１回合仅可发动１张。\r\n●２种以上：选择自己墓地的１只怪兽，或自己１只被从游戏除外的怪兽加入手牌。\r\n●３种以上：选择自己墓地的１张陷阱卡加入手牌。\r\n●４种：选择自己墓地“圣蛇的息吹”以外的１张魔法卡加入手牌。','\r',char(13)),'\n',char(10)),'2种类以上：回收怪兽','3种类以上：回收陷阱','4种类：回收魔法','是否要继续选择「圣蛇的息吹」的效果发动？','','','','','','','','','','','','');
INSERT INTO texts VALUES(98864751,'空气爆裂风暴',replace(replace('仅限装备机械族怪兽。\r\n①：因装备怪兽的攻击破坏对手怪兽时可发动。此战斗阶段中，装备怪兽仅可再攻击１次。发动此效果的回合，装备怪兽以外的我方怪兽不可攻击。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98865920,'热辣辣弓箭手','此卡成功召唤・反转召唤的情况下发动。给予对手LP５００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98867329,'灾厄的装备品','装备怪兽的攻击力，下降相当于我方场上怪兽数量×６００点。此卡从场上被送入墓地时，可选择对手场上的１只表侧表示怪兽装备此卡。','装备','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98875863,'G魔像・岩锤者',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：此卡存在于手牌的情况下，从手牌将1只其他的电子界族怪兽舍弃可以发动。此回合，此卡的等级下降2。\r\n②：解放此卡可以发动。将3只“G魔像衍生物”（电子界族・地・星1・攻/守0）以守备表示特殊召唤至自己场上。此效果发动后，直至回合结束时为止，自己仅可特殊召唤电子界族怪兽。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98875864,'G魔像衍生物','由「G魔像・岩锤者」的效果特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98881700,'水晶鲨',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：此卡存在于手牌・墓地的情况下，以场上的１只水属性怪兽为对象可以发动。将此卡特殊召唤，将对象怪兽的攻击力改成一半。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。此效果发动后，直至回合结束时为止自己从额外牌组仅可特殊召唤超量怪兽。\r\n②：将此卡使用于“编号”怪兽的超量召唤的情况下，可将此卡的等级视为３或４。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98881931,'光子前行者','此卡名以①方法的特殊召唤１回合仅可进行１次。①：场上有“光子”怪兽存在的情况下，此卡可从手牌中特殊召唤。②：场上有此卡以外的“光子”怪兽存在的情况下，此卡的攻击力上升１０００。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98884569,'蓝蔷薇龙','①：场上的此卡被破坏并被送至墓地时，以自己墓地的１只“黑蔷薇龙”或植物族怪兽为对象可以发动。将该怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98888032,'妖精胞 孢子',replace(replace('此卡名的②效果1回合仅可使用1次。\r\n①：此卡特殊召唤的情况下可以发动。此卡的等级上升最多相当于自己场上怪兽的数量的数值。\r\n②：此卡存在于墓地，自己场上存在“上古精灵龙”或兽族・植物族・天使族的光属性怪兽中的任一的情况下可以发动。将此卡特殊召唤。此效果发动后，直至回合结束时为止自己从额外牌组仅可特殊召唤同步怪兽。','\r',char(13)),'\n',char(10)),'等级上升','特殊召唤','请选择要上升的等级','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98891840,'休息的剑斗兽','从我方手牌挑选２张冠有“剑斗兽”之名的卡牌返回至牌组。之后，从我方牌组抽取３张卡牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98898163,'雄牙龙','此卡名的效果１回合仅可使用１次。①：此卡召唤・特殊召唤成功的情况下，以此卡以外的场上最多２张卡为对象可以发动。将该卡破坏，此卡的攻击力上升相当于所破坏数量×６００的数值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98898173,'融化的赤影','融化自身藏于脚下的影子里，从敌人的正下方发动攻击。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98904974,'魔键锭－解－',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：自己场上存在“魔键”仪式怪兽或被从额外牌组特殊召唤的“魔键”怪兽，对手发动魔法・陷阱卡时可以发动。将该发动无效并破坏。然后，可宣言１个属性。该情况下，直至回合结束时为止，对手场上的所有表侧表示怪兽变为所宣言的属性。','\r',char(13)),'\n',char(10)),'是否改变属性？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98918572,'十二兽的相克',replace(replace('此卡名的①效果1回合仅可使用1次。\r\n①：只要此卡存在于魔法与陷阱区域，自己的“十二兽”超量怪兽要去除超量素材来发动效果的情况下，可从自己场上的其他超量怪兽去除超量素材。\r\n②：将墓地的此卡除外，以自己场上的2只“十二兽”超量怪兽为对象可以发动。将对象怪兽中的1只作为另1只的超量素材。','\r',char(13)),'\n',char(10)),'代替素材','请选择要增加超量素材的怪兽','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98927491,'救援急救机人',replace(replace('“救援机人”＋“救护车机人”\r\n此怪兽仅可以融合召唤特殊召唤。１回合１次，我方场上的怪兽因战斗被破坏并送入墓地时，可以守备表示特殊召唤该怪兽。','\r',char(13)),'\n',char(10)),'特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98931282,'命运－英雄 无惧仆从',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：“命运－英雄”怪兽或场地魔法卡以表侧表示存在于自己场上的情况下可以发动。从手牌将此卡特殊召唤。然后，可适用以下效果。\r\n●将自己场上的1张卡破坏，从牌组将1张“融合”加入手牌。\r\n②：自己将等级8的“命运－英雄”怪兽特殊召唤的情况下，将墓地的此卡除外，以对手场上的1张卡为对象可以发动。将该卡放回牌组最上面。','\r',char(13)),'\n',char(10)),'特殊召唤','回到牌组','是否破坏并检索？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98935722,'安眠于星遗物的深层','①：此卡发动时，可以自己墓地的1只等级5以上的怪兽为对象。该情况下，将该怪兽特殊召唤。此卡从场上离开时该怪兽将被破坏。②：只要自己场上有“机界骑士”怪兽存在，与该怪兽同一纵列发动的对手怪兽的效果无效化。','是否把墓地怪兽特殊召唤？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98937206,'枪弹导爆者',replace(replace('此卡名以①方法的特殊召唤1回合仅可进行1次，且②效果1回合仅可使用1次。\r\n①：自己场上存在龙族・暗属性连接怪兽的情况下，此卡可从手牌特殊召唤。\r\n②：以自己的魔法与陷阱区域的1张龙族・暗属性怪兽卡为对象可以发动。将该卡特殊召唤。以此效果特殊召唤的怪兽不可攻击，效果无效化。此效果发动后，直至回合结束时为止自己从额外牌组仅可特殊召唤暗属性怪兽。','\r',char(13)),'\n',char(10)),'','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98954106,'贪欲之瓶',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：以“贪欲之瓶”以外的、自己墓地的5张卡为对象可以发动。将该5张卡放回牌组。然后，自己抽1张。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98954375,'无限狱破坏王','此卡因战斗破坏对手怪兽并送入墓地时，给予对手生命１６００点伤害。此效果可在我方手牌是０张的场合发动与处理。','给与伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98956134,'破坏干扰','可舍弃１张手牌并发动。持有“破坏场上怪兽效果”的怪兽的效果、魔法、陷阱卡发动无效并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98978921,'连接蜘蛛',replace(replace('通常怪兽1只\r\n①：1回合1次，在自己的主要阶段可以发动。从手牌将1只等级4以下的通常怪兽特殊召唤至此卡连接端的自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98986900,'泰勒玛科技・克拉特斯',replace(replace('等级８怪兽×２\r\n此卡名的②效果１回合仅可使用１次。\r\n①：每次对手发动魔法卡以外的卡的效果，在此卡上放１个魔力计数物（最多９个）。\r\n②：去除此卡的３个魔力计数物可以发动。从以下效果中挑选１个适用。\r\n●从牌组将１张魔法卡或１只魔法师族效果怪兽加入手牌。\r\n●从手牌・牌组将１只魔法师族怪兽特殊召唤。\r\n③：此卡将被破坏的情况下，作为代替可去除此卡的１个超量素材。','\r',char(13)),'\n',char(10)),'','从牌组加入手牌','从手牌·牌组特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(98999181,'奈芙蒂斯的祈祷者',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：在自己的主要阶段可以发动。挑选自己的１张手牌破坏，从牌组将１只“奈芙蒂斯的祈祷者”以外的“奈芙蒂斯”怪兽加入手牌。\r\n②：此卡因效果被破坏并被送至墓地的情况下，在下个自己的准备阶段可以发动。从牌组将１张“奈芙蒂斯”魔法・陷阱卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99000107,'修禅僧 元道',replace(replace('①：只要此卡存在于怪兽区域，场上的表侧攻击表示怪兽不可发动效果。\r\n②：守备表示的此卡不会成为卡效果的对象，不会因效果被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99000151,'死之花','①：此卡因效果被破坏并被送至墓地的情况下可以发动。从牌组将1只“鲜花之魔女”特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99002135,'紧急合成','可将我方墓地的１张“核成之钢核”返回至牌组并发动。从我方手牌、墓地挑选１只等级４或以下的冠有“核成”之名的怪兽并特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99004583,'动作魔法：大转弯',replace(replace('①：本回合，怪兽之间的战斗造成两倍战斗伤害。\r\n②：如果这张卡在墓地，则可以在我方主要阶段从手牌弃掉１张魔法卡以发动。将这张卡放置在我方的魔法与陷阱区域。此效果在此卡被送至墓地的回合不能发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99004752,'最小的勇气','解放自己场上的１只怪兽，并选择对手场上１只表侧表示的怪兽可以发动。选择的怪兽的攻击力直至回合结束时为止变为０。此回合，选择的怪兽因战斗被破坏并被送至对手墓地时，给予对手LP该怪兽原本攻击力数值的伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99011763,'魔界巡逻课死亡警察',replace(replace('怪兽2只\r\n①：以卡名不同的2只暗属性怪兽作为素材连接召唤的此卡获得以下效果。\r\n●解放自己场上的1只怪兽，以场上的1张表侧表示卡为对象可以发动。在该卡上放1个巡逻计数物。此卡名的此效果1回合仅可使用1次。放有巡逻计数物的卡将被战斗・效果破坏的情况下，去除该卡的1个巡逻计数物作为代替。','\r',char(13)),'\n',char(10)),'','持有效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99013397,'剑斗兽之斗器长戟','仅限装备冠有“剑斗兽”之名的怪兽。装备怪兽进行了战斗的战斗阶段结束时，选择场上的１张魔法、陷阱卡破坏。因装备怪兽从我方场上返回至牌组而导致此卡被被送入墓地时，此卡返回至手牌。','场上1张魔法或者陷阱卡破坏','返回手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99030164,'幸福恋使','会从头上发射出爱心光束、带给敌人幸福的小小天使。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99049589,'魔玩具修理','此卡名的①②效果１回合１次，仅可使用其中１个。①：以自己墓地的１只“魔玩具”融合怪兽为对象可以发动。将该怪兽放回额外牌组。然后，可从自己的墓地挑选１只“绒毛动物”怪兽或“锋利小鬼”怪兽特殊召唤。②：将墓地的此卡除外可以发动。从手牌将１只“绒毛动物”怪兽或“锋利小鬼”怪兽特殊召唤。','','','是否从墓地特殊召唤？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99050989,'尖钻兽','对手场上只有表侧表示的攻击力１６００以上的怪兽存在的场合，此怪兽可直接攻击对手玩家。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99054885,'破坏之代行者 维纳斯',replace(replace('此卡名的①②效果1回合1次，仅可使用其中1个。\r\n①：从自己墓地将1只“创造之代行者 维纳斯”除外可以发动。从手牌将此卡特殊召唤。\r\n②：支付500的倍数的LP，每支付LP500，以自己墓地・除外状态的1只“神圣球体”为对象可以发动。将该怪兽特殊召唤。以此效果特殊召唤的怪兽从场上离开的情况下放回牌组最下面。','\r',char(13)),'\n',char(10)),'','','请选择要特殊召唤的怪兽的数量','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99064191,'超量惩罚','１回合１次，我方场上存在有超量怪兽，且等级５或以上的怪兽效果发动时，可舍弃１张手牌并发动。使该效果无效并破坏。','无效并破坏','是否现在使用「超量惩罚」的效果？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99070951,'超能力女孩',replace(replace('①：除外状态的此卡特殊召唤的情况下发动。将自己牌组最上面的卡以里侧除外。\r\n②：以此卡的①效果除外了卡的此卡从场上被送至墓地的情况下发动。将该自己的除外状态的卡加入手牌。','\r',char(13)),'\n',char(10)),'除外','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99075257,'D－时间','我方场上冠有“元素－英雄”之名的表侧表示怪兽从场上离开时可发动。从牌组将１只持有等级是该怪兽等级或以下冠有“命运－英雄”之名的怪兽加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99092624,'漆黑蔷薇之开华','此卡名的②效果１回合仅可使用１次。①：将“蔷薇衍生物”（植物族・暗・星２・攻／守８００）以守备表示特殊召唤至自己・对手场上，数量最多为双方场地区域的卡及墓地的场地魔法卡数量。②：此卡存在于墓地的情况下，以自己场上的１只“黑蔷薇龙”或植物族怪兽为对象可以发动。将该怪兽除外，将此卡放回牌组最下面。以此效果除外的怪兽将在下一个准备阶段放回场上。','是否继续特殊召唤？','在自己场上特殊召唤','在对手场上特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99092625,'蔷薇衍生物','由“黑花园”等的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99111753,'安全龙',replace(replace('怪兽2只\r\n此卡名的效果1回合仅可使用1次。①：只要此卡在场上以表侧表示存在，仅限1次，在此卡处于相互连接状态的情况下以对手场上的1只怪兽为对象可以发动。将该怪兽放回持有者的手牌。','\r',char(13)),'\n',char(10)),'回到持有者手牌','已发动过效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99115354,'超念力平衡者',replace(replace('协调+1只以上协调以外的怪兽\r\n此卡名的②效果1回合仅可使用1次。①：只要此卡存在于怪兽区域，拥有比此卡攻击力低的攻击力的怪兽不可攻击，拥有比此卡攻击力高的攻击力的场上怪兽不可发动效果。②：此卡被对手破坏并被送至墓地的情况下，以自己墓地的、种族与属性相同的1只协调和1只协调以外的怪兽为对象可以发动。将该怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99137266,'忆念之相剑','此卡名的①②效果１回合仅可各使用１次。①：卡被除外的情况下可以发动。从自己的手牌・牌组・墓地及自己・对手场上的表侧表示卡中，挑选１只幻龙族同步怪兽或１张“相剑”卡除外。②：此卡被除外的情况下可以发动。将１只“相剑衍生物”（幻龙族・协调・水・星４・攻／守０）特殊召唤至自己场上。只要以此效果特殊召唤的衍生物存在，自己从额外牌组仅可特殊召唤同步怪兽。','卡片除外','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99137267,'相剑衍生物','由“相剑”卡片的效果特殊召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99150062,'大植然蚂蚁颚','①：对手特殊召唤怪兽成功时可以发动。从牌组将１只等级３以下的“大植然”怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99153051,'蕾祸之毬首',replace(replace('此卡名以①方法的特殊召唤１回合仅可进行１次，且②效果１回合仅可使用１次。\r\n①：此卡可将手牌的１只昆虫族・植物族・爬虫类族怪兽送至墓地，来从手牌特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下可以发动。将“蕾祸之毬首”以外的、自己的牌组・除外状态的最多２张“蕾祸”卡加入手牌（同名卡最多１张）。然后，挑选自己的１张手牌除外。此回合，自己仅可特殊召唤昆虫族・植物族・爬虫类族怪兽。','\r',char(13)),'\n',char(10)),'','检索「蕾祸」卡','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99157310,'廷达三角・德劳内三角化',replace(replace('①：自己的墓地有３种以上的“廷达三角”怪兽存在，自己因对手怪兽的攻击受到战斗伤害时可以发动。将该攻击怪兽破坏，从额外牌组将１只“廷达三角・锐角地狱犬”特殊召唤。\r\n②：额外怪兽区域不存在自己的怪兽的情况下，将墓地的此卡除外，以自己墓地的３只“廷达三角”怪兽为对象可以发动（同名卡最多１张）。将该怪兽以里侧守备表示形式特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99161253,'原石融合',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：将包含通常怪兽在内的、自己场上・墓地・除外状态的怪兽作为融合素材放回牌组，将1只龙族融合怪兽融合召唤。\r\n②：将墓地的此卡除外可以发动。从自己牌组・墓地将1只等级5以上的“原石”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'融合召唤','检索','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99162522,'扑灭！',replace(replace('此卡名在规则上也视为“救援王牌”卡。\r\n①：自己场上存在“救援王牌”怪兽的情况下，以对手场上的1只效果怪兽为对象可以发动。将该怪兽破坏。自己场上存在“救援王牌 消防栓”的情况下，进而在此回合，对手不可发动以此效果破坏的怪兽及与该怪兽原本卡名相同的怪兽的效果。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99162753,'六界召唤',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：从自己的手牌・墓地及自己场上的表侧表示怪兽中，挑选原本种族相同的６种（仪式・融合・同步・超量・灵摆・连接）怪兽各１只除外。然后，将与所除外的怪兽原本种族相同的１只怪兽从牌组・额外牌组特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99171160,'哥查基','将一切奉献给魔界语言研究的恶魔。因工作过度而导致精神崩溃。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99173029,'灵子能量固定装置','只要此卡存在于场上，灵魂怪兽持续存留在场上。在我方结束阶段时弃置１张手牌，若不弃置则破坏此卡。此外，当此卡离开场上时，令场上所有表侧表示的灵魂怪兽回到持有者的手牌中。','是否要丢弃一张手牌维持「灵子能量固定装置」？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99176254,'青泪的少女',replace(replace('此卡名的①②效果１回合１次，仅可使用其中１个。\r\n①：自己场上存在连接怪兽，且对手将怪兽特殊召唤的情况下，以其中１只为对象可以发动。将该怪兽破坏，给予对手相当于其原本攻击力一半数值的伤害。\r\n②：此卡存在于墓地的状态下，自己或对手受到效果伤害的情况下，将此卡除外，以自己的墓地・除外状态的１张通常魔法卡为对象可以发动。将该卡放置在自己场上。该卡在此回合不可发动。','\r',char(13)),'\n',char(10)),'破坏效果','放置效果','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99177923,'无限狱恶魔','①：手牌为0张的情况下抽到此卡时，将此卡出示给对手可以发动。从手牌将此卡特殊召唤。②：此卡特殊召唤成功时可以发动。从牌组将1张“无限狱”卡加入手牌。此效果在自己的手牌为0张的情况下才能发动和处理。','特殊召唤','检索牌组','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99185129,'辉剑鸟的影灵衣',replace(replace('以“影灵衣”仪式魔法卡降临\r\n此卡仅可以仪式召唤方式特殊召唤。\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：从手牌将此卡舍弃可以发动。从牌组将1张“影灵衣”魔法・陷阱卡加入手牌。\r\n②：在自己・对手回合中，以场上的1只被从额外牌组特殊召唤的表侧表示怪兽为对象可以发动。直至回合结束时为止，该怪兽的攻击力变为0，效果无效化。','\r',char(13)),'\n',char(10)),'效果无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99188141,'大革命反击','①：破坏２张或以上场上卡牌的怪兽的效果、魔法、陷阱卡发动时可发动。使该发动无效并除外。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99189322,'秘仪呼唤','可选择我方场上１只冠有“秘仪之力”之名的怪兽并发动。从我方或对手墓地将１只冠有“秘仪之力”之名的怪兽从游戏中除外。直至回合结束时，被选择怪兽由掷硬币而获得的效果将变成与被除外怪兽由掷硬币而获得的效果相同。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99193444,'轰海皇 波塞多拉',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从自己手牌・场上（表侧表示）将1只其他水属性怪兽送至墓地可以发动。从手牌将此卡特殊召唤。\r\n②：此卡召唤・特殊召唤的情况下，从牌组将1只“海皇”怪兽或“水精鳞”怪兽送至墓地，以对手场上的1张卡为对象可以发动。将该卡放回手牌。\r\n③：只要自己场上存在“轰海皇 波塞多拉”以外的怪兽，对手怪兽不可将此卡选择为攻击对象。','\r',char(13)),'\n',char(10)),'特殊召唤','回到手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99199231,'超元特防队 本源',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：将自己手牌・墓地・除外状态的1只“超元特防队”怪兽特殊召唤。以此效果特殊召唤的怪兽从场上离开的情况下，将其除外。\r\n②：此卡存在于墓地的状态下，且其他卡被除外的情况下，将此卡除外可以发动。从牌组挑选2张“超元特防队 本源”以外的“超元特防队”卡，将其中1张除外，另1张送至墓地。','\r',char(13)),'\n',char(10)),'发动','牌组操作','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99212922,'白龙的忍者','此卡仅可以冠有“忍法”之名的卡牌效果特殊召唤。只要此卡以表侧表示存在于场上，我方场上的魔法、陷阱卡不会因卡牌效果而被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99214782,'侵邪蚀的步哨','只要此卡以攻击表示存在于场上，场上等级５或以上被特殊召唤的怪兽不可发动效果。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99217226,'团结与羁绊的超魔导剑士',replace(replace('协调＋协调以外的原本攻击力与原本守备力为2500的怪兽1只以上\r\n①：只要同步召唤的此卡存在于怪兽区域，此卡不会因对手的效果被破坏，对手不可将此卡作为效果的对象。\r\n②：只要自己墓地存在25张以上的卡，同步召唤的此卡的攻击力・守备力上升相当于双方场上・墓地的卡的数量×100的数值。\r\n③：1回合1次，对手墓地存在25张以上的卡，且魔法卡发动时可以发动。将该发动无效并破坏。','\r',char(13)),'\n',char(10)),'发动无效','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99229085,'机关傀偶－牛啸',replace(replace('此卡名的①效果１回合仅可使用１次。\r\n①：去除自己场上的１个超量素材可以发动。从手牌・墓地将此卡特殊召唤。以此效果特殊召唤的此卡从场上离开的情况下，将其除外。\r\n②：持有此卡作为素材的“机关傀偶”超量怪兽获得以下效果。\r\n●１回合１次，以对手墓地的１只怪兽为对象可以发动。将该怪兽以守备表示特殊召唤至对手场上。','\r',char(13)),'\n',char(10)),'特殊召唤此卡','选对手墓地怪兽在对手场上特殊召唤（机关傀偶-悲鸣四方牛）','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99234526,'辉白龙 暴源翼龙','此卡不可通常召唤。仅可在从自己的墓地将１只暗属性怪兽除外的情况下特殊召唤。“辉白龙 暴源翼龙”以此方法的特殊召唤１回合仅可进行１次。①：此卡从场上被送至墓地的情况下可以发动。从牌组将１只“暗黑龙 坍缩星蛇”加入手牌。','检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99243014,'同步超车',replace(replace('此卡名的卡1回合仅可发动1张，发动此卡的回合中，自己从额外牌组仅可特殊召唤同步怪兽。\r\n①：向对手出示额外牌组的1只同步怪兽，从自己牌组・墓地挑选1只卡名记载于该怪兽的同步素材怪兽，加入手牌或特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99249638,'同盟驾驶者',replace(replace('此卡名的②效果1回合仅可使用1次。①：1回合1次，可从以下效果中选择1个发动。\r\n●以自己场上的1只表侧表示怪兽为对象，将此卡视为装备卡装备于该怪兽。装备怪兽将被战斗・效果破坏的情况下，破坏此卡作为代替。\r\n●将被装备的此卡特殊召唤。\r\n②：将被装备的此卡除外可以发动。从牌组将1只可装备的等级4以下联合怪兽装备于此卡原先装备的怪兽。','\r',char(13)),'\n',char(10)),'装备','特殊召唤','更换装备','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99261403,'暗黑兔','来自美国卡通世界的兔子。非常敏捷，匆忙行动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99266988,'混沌领域','此卡名的①②效果１回合仅可各使用１次。①：从手牌将１只光属性或暗属性的怪兽送至墓地可以发动。将１只属性与该怪兽不同、等级４～８、不可通常召唤的光・暗属性怪兽从牌组加入手牌。②：将墓地的此卡除外，以自己１只被除外的、不可通常召唤的光・暗属性怪兽为对象可以发动。将该怪兽放回牌组最下面。然后自己从牌组抽１张。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99267150,'五头神龙',replace(replace('龙族怪兽×５\r\n此卡只可以融合召唤特殊召唤。\r\n①：此卡不会在与暗、地、水、炎、风属性怪兽的战斗中被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99267151,'五头神龙',replace(replace('龙族怪兽×５\r\n此卡只可以融合召唤特殊召唤。\r\n①：此卡不会在与暗、地、水、炎、风属性怪兽的战斗中被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99274184,'水晶机巧・冲击',replace(replace('①：以自己除外状态的1只“水晶机巧”怪兽为对象可以发动。将该怪兽特殊召唤，对手场上存在表侧表示怪兽的情况下，该对手怪兽的守备力变为0。\r\n②：以自己场上的“水晶机巧”怪兽为对象的魔法・陷阱・怪兽的效果发动时，从墓地将不是在此回合被送至墓地的此卡除外可以发动。将该效果无效。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99284890,'壶魔神','可将１张“强欲之壶”从手牌送入墓地并发动。我方从牌组抽取３张卡牌。','抽牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99289828,'白森之异闻',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己场上存在幻想魔族或魔法师族怪兽的情况下可以发动。从牌组将１只“白森”怪兽加入手牌。\r\n②：此卡为发动怪兽的效果被送至墓地的情况下可以发动。将此卡放置在自己场上。','\r',char(13)),'\n',char(10)),'检索','放置','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99307040,'荷鲁斯之黑炎神',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：自己场上存在“荷鲁斯”怪兽及“王之棺”的情况下，向对手出示手牌中的此卡，将自己的手牌・场上的１张卡送至墓地可以发动。将场上的１张卡送至墓地。\r\n②：“荷鲁斯之黑炎神”以外的、自己场上表侧表示的、“荷鲁斯”怪兽或“王之棺”因对手的效果从场上离开的情况下可以发动。从手牌将此卡特殊召唤。然后，可将场上的其他怪兽全部送至墓地。','\r',char(13)),'\n',char(10)),'送至墓地','此卡特殊召唤','是否把场上的其他怪兽全部送至墓地？','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99311109,'战友的誓言','从额外牌组被特殊召唤的怪兽不存在於我方场上的场合，可选择对手场上表侧表示的１只从额外牌组特殊召唤的怪兽并发动。直至结束阶段获得被选择怪兽的控制权。发动此卡的回合，我方不可特殊召唤怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99311889,'绝境狱神域－皮莱亚',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从自己额外牌组・场上（表侧表示）・墓地挑选“创狱神 涅瓦”、“坏狱神 朱庇特”、“调狱神 朱诺拉”各1只给双方确认，此回合，应对自己的“狱神”怪兽的效果的发动，对手不可发动效果。\r\n②：为发动自己场上的“狱神”怪兽的效果而要从牌组上面将卡除外的情况下，作为代替可将墓地的此卡除外。','\r',char(13)),'\n',char(10)),'发动','是否作为代替把「绝境狱神域－皮莱亚」除外？','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99315585,'魅影骑士团裂头盔','此卡名的①②效果1回合仅可各使用1次。①：“魅影骑士团”卡或“魅影”魔法・陷阱卡被送至自己墓地的情况下发动。此卡的攻击力上升500。②：将墓地的此卡除外可以发动。此回合的结束阶段，从自己墓地挑选1张“魅影骑士团”卡或“魅影”魔法・陷阱卡加入手牌。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99328137,'冰骑士',replace(replace('①：此卡的攻击力上升相当于自己场上的水族怪兽的数量×４００的数值。\r\n②：１回合１次，在自己的主要阶段可以发动。此回合自己除通常召唤外仅可追加１次，在自己的主要阶段召唤１只水属性怪兽。此效果发动后，直至回合结束时为止，自己仅可以召唤・特殊召唤水属性怪兽。','\r',char(13)),'\n',char(10)),'','使用「冰骑士」的效果召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99330325,'被打扰的坏兽安眠',replace(replace('此卡名的卡１回合仅可发动１张。\r\n①：将场上的怪兽全部破坏。然后从牌组将卡名不同的“坏兽”怪兽各１只以攻击表示特殊召唤至自己・对手场上。以此效果特殊召唤的怪兽表示形式不可更改，可以攻击的情况下必须攻击。\r\n②：从墓地将不是在此回合被送至墓地的此卡除外可以发动。从牌组将１只“坏兽”怪兽加入手牌。','\r',char(13)),'\n',char(10)),'破坏·特殊召唤','牌组检索','请选择要在自己场上特殊召唤的怪兽','请选择要在对手场上特殊召唤的怪兽','「被打扰的坏兽安眠」效果适用中','','','','','','','','','','','');
INSERT INTO texts VALUES(99342953,'古代遗迹代号A','每次场上表侧表示的冠有“外星人”之名的怪兽被破坏，放置１个A计数物在此卡。１回合１次，可从场上移除２个A计数物并发动。选择我方墓地１只冠有“外星人”之名的怪兽并特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99348756,'女战斗骑士','只要此卡以表侧表示存在于场上，对手不可选择除“女战斗骑士”以外的战士族怪兽为攻击对象。此卡因战斗被破坏并送入墓地时，可将我方墓地的１只战士族怪兽和此卡从游戏中除外并发动。从我方墓地选择１只等级５或以上的战士族怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99351431,'盗贼的精奥','只可在主要阶段１发动此卡。选择场上１只表侧表示的怪兽。该回合中，所选择怪兽每次对对手玩家造成战斗伤害时，对手随机弃置１张卡牌。','丢弃手牌','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99357565,'D３',replace(replace('“D３”的②③效果１回合只可使用１次。\r\n①：此卡召唤成功的场合发动。此怪兽以表侧表示存在的期间，被视为“命运－英雄”怪兽。\r\n②：可舍弃最多２张手牌发动。从我方手牌、牌组、墓地挑选舍弃数量的“D３”特殊召唤。此效果发动之后，直至回合结束时，我方只可召唤、特殊召唤“命运－英雄”怪兽。\r\n③：此卡因战斗、效果被破坏的场合可发动。从牌组将１只“命运－英雄”怪兽送入墓地。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99365553,'光脉冲星龙','①：将自己墓地的光属性和暗属性怪兽各1只除外，可从手牌特殊召唤此卡。②：将手牌的光属性和暗属性怪兽各1只送至墓地，可从墓地特殊召唤此卡。③：此卡从场上被送至墓地时，可以自己墓地的1只等级5以上的龙族・暗属性怪兽为对象发动。将该龙族・暗属性怪兽特殊召唤。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99370594,'劫火之长眠姬 幽灵睡美人','此卡名的①②效果１回合仅可各使用１次。①：此卡被送至墓地的情况下可以发动。从牌组将１张“幽合－幽灵结合”加入手牌。②：将墓地的此卡除外，舍弃１张手牌，以自己１只被除外的等级４以上的不死族怪兽为对象可以发动。将该怪兽加入手牌。此效果在此卡被送至墓地的回合不可发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99397762,'光波防轮','①：以自己场上的１只“银河眼”超量怪兽或“光波”超量怪兽为对象可以发动。将此卡重叠在该怪兽下方作为超量素材，该怪兽在此回合中仅１次，不会因战斗・效果被破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99398682,'深红地狱呼唤',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：从自己墓地将1只等级4以下的恶魔族怪兽加入手牌。自己场上存在“暗红恶魔龙”或记载有该卡名的同步怪兽的情况下，要加入手牌的怪兽也可从牌组挑选。\r\n②：自己的“／爆裂”怪兽或“暗红恶魔龙”攻击的伤害步骤结束时，将墓地的此卡除外可以发动。该攻击怪兽可继续再攻击仅1次。','\r',char(13)),'\n',char(10)),'检索效果','再次攻击','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99414168,'精灵术师 多莉雅德','由“多莉雅德的祈祷”召唤而来。此卡的属性也视为“风”、“水”、“炎”、“地”。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99414629,'恐啡肽骇龙・暴虐','此卡名的卡１回合仅可发动１张。①：支付一半LP可以发动。挑选自己场上的１只“恐啡肽骇龙”怪兽和对手场上的１张卡破坏。②：自己的LP为２０００以下、对手发动魔法・陷阱・怪兽的效果时，将墓地的此卡除外可以发动。此回合，因对手的效果对自己造成的效果伤害变为０。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99423156,'不知火的宫司','此卡名的②效果１回合仅可使用１次。①：此卡召唤成功时可以发动。从自己的手牌・墓地挑选“不知火的宫司”以外的１只“不知火”怪兽特殊召唤。以此效果特殊召唤的怪兽离开场上的情况下，将其除外。②：此卡被除外的情况下，以对手场上的１张表侧表示的卡为对象可以发动。将该卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99426088,'魔键－马夫提亚','①：将由“魔键”融合怪兽卡决定的融合素材怪兽从自己的手牌・场上送至墓地，将该１只融合怪兽从额外牌组融合召唤。或者，为使合计等级为仪式召唤的怪兽以上，解放自己手牌・场上的怪兽，从手牌将１只“魔键”仪式怪兽仪式召唤。自己场上有通常怪兽存在的情况下，也可将牌组的１只通常怪兽送至墓地作为融合素材怪兽或为仪式召唤解放的怪兽。','融合召唤','仪式召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99426834,'沼地魔兽王','此卡可代替融合素材怪兽的其中１只来进行融合。不过此时其他的融合素材怪兽必须是指定的怪兽。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99427357,'电子天使－那沙帝弥－','以“机械天使的仪式”降临。①：１回合１次，以自己场上的１只表侧表示怪兽为对象可以发动。依该怪兽攻击力的一半来恢复自己的LP。②：自己的仪式怪兽被选择为攻击对象时可以发动。将该攻击无效。③：此卡存在于墓地的情况下，从自己的墓地将此卡以外的１只“电子天使”怪兽除外，以对手场上的１只怪兽为对象可以发动。将此卡从墓地特殊召唤，获得对象怪兽的控制权。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99429730,'森罗的守卫 奥克','１回合１次，可在我方主要阶段时发动。最多从我方牌组上方翻阅３张卡牌。翻阅的卡牌中有植物族怪兽的场合，将那些怪兽全部送入墓地。剩下的卡牌依照喜欢的顺序返回至牌组最下方。此外，牌组的此卡因卡牌效果被翻阅并送入墓地的场合，可从我方墓地选择１只除此卡以外的植物族怪兽返回至牌组的最上方。','确认牌组','请选择要翻开的数量','返回牌组','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99456344,'惨绝戏之大导剧神','此卡名的①②效果１回合仅可各使用１次。①：融合・同步・超量・连接怪兽被特殊召唤的情况下，以场上的１只效果怪兽为对象可以发动。将该怪兽的效果直至回合结束时为止无效。②：手牌・场上的此卡成为融合召唤的素材，被送至墓地的情况下或被除外的情况下可以发动。将此卡特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99458769,'暗黑界之魔神 彩莲恩','此卡因对手卡牌效果从手牌被舍弃至墓地的场合，从墓地特殊召唤此卡。以此效果特殊召唤成功时，破坏对手场上的所有怪兽或所有魔法、陷阱卡。','特殊召唤','破坏','对手场上的怪兽全部破坏','对手场上的魔法·陷阱卡全部破坏','','','','','','','','','','','','');
INSERT INTO texts VALUES(99469936,'全装甲－水晶零枪兵',replace(replace('水属性等级６怪兽×３\r\n此卡也可重叠在自己场上的阶级５水属性超量怪兽上面来超量召唤。\r\n①：此卡的攻击力上升相当于此卡的超量素材的数量×５００的数值。\r\n②：１回合１次，去除此卡的１个超量素材可以发动。将对手场上所有表侧表示怪兽的效果直至回合结束时为止无效。\r\n③：场上的此卡将被战斗・效果破坏的情况下，作为代替可去除此卡的１个超量素材。','\r',char(13)),'\n',char(10)),'是否在水属性·5阶超量怪兽上面重叠超量召唤？','是否要使用「全装甲－水晶零枪兵」的效果代替破坏？','效果无效','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99471856,'水晶机巧－鳞龙石英',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：对手发动效果时可以发动。从牌组将“水晶机巧－鳞龙石英”以外的1只“水晶机巧”怪兽特殊召唤。然后，将包含其在内的自己场上的怪兽作为素材，进行1只机械族同步怪兽的同步召唤。\r\n②：将墓地的此卡除外可以发动。将自己场上的1只同步怪兽破坏，从牌组将2只“水晶机巧”怪兽特殊召唤。此回合，自己从额外牌组仅可特殊召唤机械族怪兽。','\r',char(13)),'\n',char(10)),'特殊召唤并同步召唤','破坏并特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99505609,'宾果卡',replace(replace('①：挑选同一纵列全部存在卡的1只怪兽，将该纵列的卡全部破坏。然后，双方各抽1张。\r\n②：将墓地的此卡除外，可从以下效果中选择1个发动。\r\n●将自己的主要怪兽区域的5只怪兽或自己的魔法与陷阱区域的5张卡破坏。然后，自己抽2张。\r\n●将对手的主要怪兽区域的5只怪兽或对手的魔法与陷阱区域的5张卡破坏。然后，对手抽2张。','\r',char(13)),'\n',char(10)),'发动','墓地效果','自己的卡破坏','对手的卡破坏','主要怪兽区域','魔法与陷阱区域','','','','','','','','','','');
INSERT INTO texts VALUES(99510761,'神灯魔人','从魔法神灯中现身的魔人。会服从召唤者的命令。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99517131,'生命力吸收魔术','将场上所有里侧守备表示的怪兽全部变为表侧表示。此时，反转效果怪兽不发动效果。场上每有１只效果怪兽，我方回复４００LP。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99518961,'革命','给予对手生命其手牌数量×２００点伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99523325,'守墓的石板','选择我方墓地中２只冠有“守墓的”之名的怪兽并加入到手牌中。此效果不会因“王家长眠之谷－死灵谷”的效果而无效。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99529628,'游魊之胧 基夫',replace(replace('此卡名的①②③效果１回合仅可各使用１次。\r\n①：场上存在鱼族怪兽的情况下可以发动。从手牌将此卡特殊召唤。\r\n②：怪兽被特殊召唤至对手场上的情况下，以其中１只怪兽和自己除外状态的１只等级６以下鱼族怪兽为对象可以发动。将对象的对手怪兽和此卡除外，将对象的自己怪兽特殊召唤。\r\n③：在此卡被除外的下个回合的准备阶段可以发动。将除外状态的此卡特殊召唤。','\r',char(13)),'\n',char(10)),'此卡从手牌特殊召唤','除外对手怪兽','除外状态的此卡特殊召唤','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99531088,'侏罗纪力量',replace(replace('此卡名的③效果１回合仅可使用１次。\r\n①：自己场上的恐龙族怪兽的攻击力上升３００。\r\n②：自己召唤等级５以上的恐龙族怪兽的情况下，可免除所必须的解放。\r\n③：从自己的手牌・场上（表侧表示）将１只恐龙族怪兽送至墓地可以发动。从牌组将１只守备力１２００的恐龙族怪兽加入手牌。','\r',char(13)),'\n',char(10)),'使用「侏罗纪力量」的效果不用解放召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99532708,'外星人火星','只要此卡以表侧表示存在于场上，场上除了“外星人火星”以外放置有A计数物的效果怪兽的效果被无效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99543666,'烙印剧城 惨绝戏','此卡名的①②效果１回合仅可各使用１次。①：从自己的手牌・场上，将由等级８以上融合怪兽卡决定的融合素材怪兽送至墓地，从额外牌组将该１只该融合怪兽融合召唤。②：自己场上融合怪兽以外的表侧表示天使族怪兽因对手的效果离开场上的情况下，或因战斗被破坏的情况下，以自己墓地１只等级８以上的融合怪兽为对象可以发动。将该怪兽特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99550630,'闪刀术式－烈火重燃','①：自己的主要怪兽区域不存在怪兽的情况下，以场上的1只表侧表示怪兽为对象可以发动。将该怪兽破坏。然后，自己墓地存在3张以上的魔法卡的情况下，可将场上的1张魔法・陷阱卡破坏。','是否选魔法·陷阱卡破坏？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99551425,'迷宫的魔战车','“高科技狼”＋“加农炮兵”','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99581584,'守卫企鹅','我方因卡牌效果受到伤害时可发动。从手牌特殊召唤此卡，回复相当于所受伤害点数的我方LP。','特殊召唤并回复','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99585850,'绯暗红超新星龙',replace(replace('协调3只＋协调以外的同步怪兽1只以上\r\n此卡从额外牌组仅可通过同步召唤来特殊召唤。\r\n①：此卡的攻击力上升自己墓地的协调数量×500的数值。\r\n②：场上的此卡不会因对手的效果被破坏。\r\n③：1回合1次，对手发动怪兽的效果时，或对手怪兽攻击宣言时可以发动。将此卡及对手场上的卡全部除外。\r\n④：此卡因③效果被除外的情况下，在下个自己的结束阶段发动。将除外状态的此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99585851,'绯暗红超新星龙',replace(replace('协调3只＋协调以外的同步怪兽1只以上\r\n此卡从额外牌组仅可通过同步召唤来特殊召唤。\r\n①：此卡的攻击力上升自己墓地的协调数量×500的数值。\r\n②：场上的此卡不会因对手的效果被破坏。\r\n③：1回合1次，对手发动怪兽的效果时，或对手怪兽攻击宣言时可以发动。将此卡及对手场上的卡全部除外。\r\n④：此卡因③效果被除外的情况下，在下个自己的结束阶段发动。将除外状态的此卡特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99590524,'狡猾落穴','①：自己的墓地不存在陷阱卡的情况下，以场上的2只怪兽为对象可以发动。将该怪兽破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99594764,'龙骑兵团－科西嘉枪','①：装备着此卡的怪兽战斗破坏对手怪兽时可以发动。从牌组将1只种族・属性和装备怪兽相同的、等级4以下的怪兽加入手牌。','牌组检索','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99597615,'魔鬼之吻',replace(replace('①：令装备怪兽的攻击力上升７００。\r\n②：将此卡从场上送入墓地时，可支付５００LP发动此卡。将此卡放回到牌组的最上面。','\r',char(13)),'\n',char(10)),'返回牌组','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99599062,'地缚融合',replace(replace('此卡名的②效果１回合仅可使用１次。\r\n场地区域不存在卡的情况下，此卡仅可在自己・对手的主要阶段发动。\r\n①：以自己手牌・场上的怪兽作为融合素材，将１只暗属性融合怪兽融合召唤。\r\n②：场地区域存在卡的情况下，在自己的主要阶段将墓地的此卡除外可以发动。从自己的手牌・墓地将１只“地缚”怪兽特殊召唤。此回合，自己从额外牌组仅可特殊召唤融合・同步怪兽。','\r',char(13)),'\n',char(10)),'融合','特殊召唤','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99628747,'巨石异物・贝索尔','以“巨石异物”卡降临。此卡名的①②效果1回合仅可各使用1次。①：从手牌将此卡舍弃可以发动。为使合计等级为仪式召唤的怪兽以上，解放自己手牌・场上的怪兽，从手牌将1只“巨石异物”仪式怪兽仪式召唤。②：此卡仪式召唤成功的情况下，以对手场上的卡为对象可以发动，数量最多为自己墓地仪式怪兽的种类数量。将该卡破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99634927,'魔界剧团－时髦谐星',replace(replace('←8 【灵摆】 8→\r\n①：１回合１次，解放自己场上的１只“魔界剧团”怪兽，以自己场上的１只“魔界剧团”怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止，上升相当于所解放怪兽原本攻击力的数值。\r\n【怪兽效果】\r\n此卡名的②怪兽效果１回合仅可使用１次，发动此效果的回合中，此卡不可攻击。①：此卡召唤・特殊召唤成功的情况下可以发动。此卡的攻击力直至回合结束时为止，上升相当于自己场上“魔界剧团”怪兽数量×３００的数值。②：以自己场上此卡以外的１只“魔界剧团”怪兽为对象可以发动。该怪兽的攻击力直至回合结束时为止，上升相当于此卡攻击力的数值。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99641328,'森罗的影孢子 伞菌','当此卡反转成功时，最多可从我方牌组上方翻阅５张卡牌。翻阅的卡牌中有植物族怪兽的场合，将那些怪兽全部送入墓地。剩下的卡牌依照喜欢的顺序返回至牌组最下方。此外，牌组的此卡因卡牌效果被翻阅并送入墓地的场合，可选择场上的１张魔法、陷阱卡破坏。','确认牌组','请选择要翻开的数量','破坏','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99645428,'宝石骑士・金碧','始终关注伙伴健康的疗愈型战士。和琉璃关系尤佳。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99657399,'骄兵必败','对手LP回复时可发动。选择对手场上的１只怪兽并破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99659159,'操龙术',replace(replace('①：自己场上装备了“龙骑兵团”怪兽卡的怪兽之攻击力上升500。\r\n②：1回合1次，可以自己场上1只表侧表示怪兽为对象发动。从手牌将1只龙族“龙骑兵团”怪兽视为装备卡装备于自己被选为对象的怪兽。','\r',char(13)),'\n',char(10)),'装备','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99666430,'人造人－念力层叠者',replace(replace('等级6怪兽×2\r\n此卡名的①②效果1回合仅可各使用1次。\r\n①：去除此卡的1个超量素材，以对手场上的1只表侧表示怪兽为对象可以发动。获得该怪兽的控制权直至结束阶段为止。以此效果获得控制权的怪兽不可发动效果，不可攻击宣言。\r\n②：场上存在陷阱卡的情况下可以发动。解放自己场上的1只怪兽，将场上的1张表侧表示卡破坏。','\r',char(13)),'\n',char(10)),'得到控制权','选卡破坏','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99668578,'卫星骑士 小犬普罗席翁','此卡名的效果１回合仅可使用１次。①：此卡召唤・反转召唤・特殊召唤成功的情况下可以发动。将手牌的１只“星骑士”怪兽送至墓地，自己从牌组抽１张。','送至墓地','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99674361,'继承星遗物者','此卡名的卡1回合仅可发动1张。①：以自己墓地的1只怪兽为对象可以发动。将该怪兽特殊召唤至场上连接怪兽连接端的自己场上。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99675356,'紫炎的步兵','此卡因战斗被破坏并送入墓地时可发动。从牌组特殊召唤１只等级３或以下的冠有“六武众”之名的怪兽。','特殊召唤','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99690140,'守墓的随从','此卡对对手玩家造成的战斗伤害视为效果伤害。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99707692,'急袭猛禽－漆黑伯劳',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：在此卡召唤・特殊召唤的回合的自己的主要阶段，以自己场上的１只“急袭猛禽”怪兽为对象可以发动。从牌组将１只等级与该怪兽不同的“急袭猛禽”怪兽加入手牌。\r\n②：将墓地的此卡除外可以发动。自己场上的“急袭猛禽”怪兽的等级全部上升１或下降１。','\r',char(13)),'\n',char(10)),'等级上升','等级下降','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99721536,'骷髅骑士','由“骷髅骑士的复活”召唤而来。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99724761,'XZ－履带加农炮',replace(replace('“X－首领加农”＋“Z－金属履带”\r\n此卡从额外牌组仅可在将自己场上的上述卡除外的情况下特殊召唤。\r\n此卡不可从墓地特殊召唤。\r\n①：舍弃１张手牌，以对手场上的１张里侧表示的魔法・陷阱卡为对象可以发动。将该对手的里侧表示卡破坏。','\r',char(13)),'\n',char(10)),'魔陷破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99726621,'铁兽战线 凶鸟之修莱格',replace(replace('兽族・兽战士族・鸟兽族怪兽２只以上\r\n此卡名的①②效果１回合仅可各使用１次。①：此卡特殊召唤成功的情况下，或此卡以外的兽族・兽战士族・鸟兽族怪兽被特殊召唤至自己场上的情况下可以发动。挑选场上的１张卡除外。②：此卡被送至墓地的情况下可以发动。从牌组将１只拥有自己被除外的兽族・兽战士族・鸟兽族怪兽数量以下等级的兽族・兽战士族・鸟兽族怪兽加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99733359,'盾航战车电子剑龙',replace(replace('“盾航战车电子剑龙”的效果１回合只可使用１次。\r\n①：此卡存在于墓地，且对手怪兽攻击了的场合，可在该伤害计算时支付１０００LP发动。从墓地特殊召唤此卡，且因该战斗造成的对我方的战斗伤害变成０。以此效果特殊召唤的此卡从场上离开的场合被除外。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99735427,'黑暗吸收魔镜','只要此卡存在于场上，在场上、墓地发动的暗属性怪兽的效果被无效化。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99742859,'救援刺猬',replace(replace('此卡名的效果1回合仅可使用1次。\r\n①：将场上的此卡除外可以发动。从牌组将等级3以下的、种族・属性・等级相同的通常怪兽和效果怪兽各1只特殊召唤。以此效果特殊召唤的怪兽的效果无效化，将在结束阶段被破坏。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99745551,'未界域之土龙','此卡名的②效果1回合仅可使用1次。①：向对手出示手牌中的此卡可以发动。对手从自己的所有手牌中随机挑选1张，自己舍弃该卡。该卡为“未界域之土龙”以外的情况下，进而从手牌将1只“未界域之土龙”特殊召唤，自己从牌组抽1张。②：此卡从手牌被舍弃的情况下可以发动。将此卡特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99747800,'传说的魔鬼','此卡的攻击力每次在我方回合的准备阶段上升７００点。','攻击上升','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99748883,'流星连打－黑白机人','此卡名的①效果１回合仅可使用１次。①：在进行了５次以上攻击宣言的回合的战斗阶段可以发动。从手牌将此卡特殊召唤。此效果在对手回合中也可以发动。②：此卡进行战斗的伤害步骤期间，此卡的攻击力上升相当于此回合回合玩家的攻击宣言次数×１０００的数值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99753860,'统合与乖离之奥艺',replace(replace('此卡名的①②③效果1回合仅可各使用1次。\r\n①：从手牌将此卡除外可以发动。从自己墓地・除外状态将1只魔法师族以外的“奥艺”怪兽特殊召唤。此回合中，自己的“狱神”连接怪兽在1次战斗阶段中最多可攻击怪兽3次。\r\n②：此卡为除外状态，且同步・连接怪兽被特殊召唤的情况下可以发动。将此卡特殊召唤。\r\n③：从自己墓地将1张“奥艺”卡除外可以发动。自己抽1张。','\r',char(13)),'\n',char(10)),'特殊召唤','特殊召唤','抽牌效果','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99785935,'磁石战士阿尔法','以阿尔法、贝塔、伽玛变形合体。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99788587,'爆导索','①：与此卡相同纵列全部都有卡存在的情况下，可以发动放置的此卡。将该纵列的卡全部破坏。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99789342,'黑魔术的布幕','可支付一半的LP来发动此卡。从牌组特殊召唤１只“黑魔导”。发动此卡的回合中，我方不可进行召唤・反转召唤・特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99792080,'梦魔镜魔兽－幻塔斯','此卡名的①②效果1回合仅可各使用1次。①：此卡以“梦魔镜”怪兽的效果特殊召唤成功的情况下可以发动。此回合，此卡可直接攻击。②：场地区域有“圣光之梦魔镜”存在的情况下，在自己・对手的主要阶段及战斗阶段，解放此卡可以发动。从牌组将1只“梦魔镜圣兽-幻塔斯”特殊召唤。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99795159,'鬼计屋','①：只要此卡存在于场地区域，双方的怪兽不可攻击里侧守备表示怪兽，对手场上的怪兽仅有里侧守备表示怪兽的情况下，可直接攻击对手。②：只要此卡存在于场地区域，双方受到的效果伤害变为一半，“鬼计”怪兽以外的怪兽给予玩家的战斗伤害变为一半。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99801464,'银翼之斧配饰－萨莉',replace(replace('此卡名的效果１回合仅可使用１次。\r\n①：以场上的１只表侧表示怪兽为对象可以发动。从自己的手牌・场上，将此卡视为攻击力・守备力上升１００的装备卡，装备于该怪兽。此效果在对手回合中也可以发动。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99861526,'潜艇机人','此卡可直接攻击对手。此时，给予对手生命的战斗伤害是此卡原本攻击力的相同数值。此外，此卡进行战斗的伤害步骤结束时，可将此卡变成守备表示。','变成守备表示','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99865167,'旋风结构体','上级召唤风属性通常怪兽的场合，此卡可作为２只怪兽来解放。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99877698,'守墓的重炮手','解放我方场上１只除“守墓的重炮手”以外的冠有“守墓的”之名的怪兽，给予对手生命７００点伤害。','伤害','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99885917,'海晶少女 紫红拟花',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：此卡召唤・特殊召唤的情况下可以发动。从手牌将“海晶少女 紫红拟花”以外的１只“海晶少女”怪兽以守备表示特殊召唤。\r\n②：将不是在此回合被送至墓地的此卡从墓地除外，以自己墓地的１张“海晶少女”魔法・陷阱卡为对象可以发动。将该卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99890852,'淘气仙星・花束','此卡名的卡1回合仅可发动1张。①：以自己场上的1只“淘气仙星”怪兽和场上1只表侧表示怪兽为对象可以发动。将该“淘气仙星”怪兽放回持有者手牌，另1只对象怪兽的攻击力直至回合结束时为止，上升相当于放回手牌的怪兽原本攻击力的数值。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99899504,'骷髅火焰','１回合１次，我方主要阶段时可发动。从手牌特殊召唤１只“燃烧骷髅头”。发动此效果的回合，我方不可进行战斗阶段。此外，在我方抽牌阶段时的抽牌前可发动。此回合，从我方墓地选择１只“燃烧骷髅头”加入手牌来代替通常的抽牌。','特殊召唤','加入手牌','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99902789,'小松狮犬','在以对手怪兽为攻击对象的我方怪兽的攻击宣言时，且对手发动了通常陷阱卡时，可从手牌舍弃此卡并发动。使该发动无效并破坏。','陷阱无效并破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99910751,'落单・悠悠',replace(replace('①：只要此卡存在于场上・墓地，卡名变为“悠悠”，视为通常怪兽。\r\n②：从手牌将此卡舍弃可以发动。从牌组将“落单・悠悠”以外的１张“悠悠”卡加入手牌。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99913726,'捕食植物 露松九头蛇','此卡名以①方法的特殊召唤１回合仅可进行１次，且②效果１回合仅可使用１次。①：此卡可在解放自己或对手场上１只放有捕食计数物的怪兽的情况下，来从手牌・墓地特殊召唤。②：此卡存在于场上・墓地的情况下，将自己墓地此卡以外的１只“捕食植物”怪兽除外，以场上１只表侧表示怪兽为对象可以发动。该怪兽的攻击力下降５００。此效果在对手回合中也可以发动。','','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99916754,'大植然龙兽',replace(replace('“大植然兽”＋“大植然龙”\r\n此卡的融合召唤仅可用上述卡进行。\r\n①：魔法・陷阱卡发动时，从自己墓地将1张卡除外，将自己牌组最上面的卡送至墓地可以发动。此卡以表侧表示存在于怪兽区域的情况下，将该发动无效并破坏。','\r',char(13)),'\n',char(10)),'魔法·陷阱卡的发动无效并破坏','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99927991,'魔救奇缘','①：从自己的牌组上面翻开牌，张数为自己场上岩石族怪兽数量＋５张。可从其中挑选１只拥有翻开卡张数以下的等级的岩石族怪兽加入手牌。将剩余的卡以喜欢的顺序放回牌组最下面。此卡发动后，直至回合结束时为止自己仅可特殊召唤岩石族怪兽。','是否选卡加入手牌？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99937011,'剑神官 姆多拉',replace(replace('此卡名的①②效果1回合仅可各使用1次。\r\n①：从手牌将1只其他的天使族・地属性怪兽舍弃可以发动。从手牌将此卡特殊召唤。然后，可从牌组将1张“守墓的陷阱”以表侧表示放在自己的魔法与陷阱区域。\r\n②：在自己・对手回合中，将场上・墓地的此卡除外，以自己・对手的墓地合计最多3张卡为对象可以发动（自己场上或墓地存在“现世与冥界的逆转”的情况下，此效果的对象变为最多5张）。将该卡放回牌组。','\r',char(13)),'\n',char(10)),'是否选「守墓的陷阱」上场？','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99937842,'T.G.星之守护者',replace(replace('协调＋1只以上协调以外的“T.G.”怪兽\r\n此卡名的①②效果1回合仅可各使用1次。①：此卡特殊召唤成功的情况下，以自己墓地的1只“T.G.”怪兽为对象可以发动。将该怪兽加入手牌。②：在自己的主要阶段可以发动。从手牌将1只“T.G.”怪兽特殊召唤。③：在对手的主要阶段可以发动。将包括此卡在内的自己场上的怪兽作为同步素材同步召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99940363,'帝王的冻气',replace(replace('①：自己场上存在攻击力2400以上且守备力1000的怪兽的情况下，以场上的1张里侧表示卡为对象可以发动。将该卡破坏。\r\n②：从自己墓地将此卡和1张“帝王”魔法・陷阱卡除外，以场上的1张里侧表示卡为对象可以发动。将该卡破坏。','\r',char(13)),'\n',char(10)),'放置的卡破坏','将此卡和1张「帝王」魔法·陷阱卡除外','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99941223,'佚乐的堕天使',replace(replace('此卡名的卡1回合仅可发动1张。\r\n①：将自己手牌・场上・墓地的怪兽作为融合素材除外，将1只天使族・暗属性融合怪兽融合召唤。要融合召唤“堕天使”融合怪兽的情况下，也可将对手场上的“堕天使”怪兽作为融合素材。以此效果特殊召唤的怪兽的攻击力上升1000。','\r',char(13)),'\n',char(10)),'发动','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99946920,'魔龙星－饕餮','此卡名的①效果1回合仅可使用1次。①：自己场上的此卡因战斗・效果被破坏并被送至墓地时可以发动。从牌组将1只“魔龙星-饕餮”以外的“龙星”怪兽以守备表示特殊召唤。②：1回合1次，在对手的主要阶段以及战斗阶段可以发动。仅以自己场上的“龙星”怪兽作为同步素材同步召唤。③：以此卡作为同步素材的同步怪兽不可变更控制权。','特殊召唤','「魔龙星－饕餮」效果适用中','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99984170,'救援！',replace(replace('此卡名在规则上也视为“救援王牌”卡。\r\n此卡名的卡1回合仅可发动1张。\r\n①：以自己墓地的1只“救援王牌”怪兽为对象可以发动（自己场上存在“救援王牌 消防栓”的情况下，作为代替也可以对手墓地的1只怪兽作为对象）。将该怪兽特殊召唤至自己场上。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99989863,'契印魔镌・乐园颂',replace(replace('此卡名的①②效果１回合仅可各使用１次。\r\n①：以自己场上的１只等级７以上的恶魔族・光属性怪兽为对象可以发动。将场上该怪兽以外的卡全部送至墓地。\r\n②：此卡存在于墓地的状态下，对手将怪兽特殊召唤的情况下，将此卡除外可以发动。从牌组・额外牌组将１只“魔镌”怪兽送至墓地。','\r',char(13)),'\n',char(10)),'送至墓地','从牌组额外牌组送至墓地','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99991455,'霸雷星 雷神',replace(replace('等级５以上的战士族・光属性怪兽＋战士族・地属性怪兽\r\n此卡名的③效果１回合仅可使用１次。\r\n①：此卡攻击守备表示怪兽的情况下，依攻击力超出该怪兽守备力的数值来给予战斗伤害。\r\n②：此卡与不拥有等级的怪兽的战斗对对手造成的战斗伤害变为两倍。\r\n③：在此卡因战斗・效果被破坏并被送至墓地的回合的结束阶段，以自己墓地的２只等级７以下的战士族怪兽为对象可以发动。将该怪兽特殊召唤。','\r',char(13)),'\n',char(10)),'','','','','','','','','','','','','','','','');
INSERT INTO texts VALUES(99995595,'电池回收','①：以自己墓地的2只攻击力1500以下的雷族怪兽为对象可以发动。将该雷族怪兽加入手牌。','','','','','','','','','','','','','','','','');
